INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/aprilfools.stf', 1, 'ewok1_1', 'Kush jeeks?'),
('string/en/aprilfools.stf', 2, 'foil1_2', 'Um... What do you want?'),
('string/en/aprilfools.stf', 3, 'ewok1_3', 'Gunda!'),
('string/en/aprilfools.stf', 4, 'ewok2_4', 'Yut ehda, den rota.'),
('string/en/aprilfools.stf', 5, 'ewok3_5', 'Kvark!'),
('string/en/aprilfools.stf', 6, 'foil1_6', 'Hey get your grubby little hands off me!'),
('string/en/aprilfools.stf', 7, 'ewok1_7', 'Rota?'),
('string/en/aprilfools.stf', 8, 'foil1_8', 'What? This? It''s a datapad...'),
('string/en/aprilfools.stf', 9, 'ewok1_9', 'Teeha!'),
('string/en/aprilfools.stf', 10, 'foil1_10', 'Hey give that back you little monster!'),
('string/en/aprilfools.stf', 11, 'ewok3_10', 'Danvay!'),
('string/en/aprilfools.stf', 12, 'ewok1_10', 'Treek!'),
('string/en/aprilfools.stf', 13, 'foil1_rand_1', 'Give that back you little thief!'),
('string/en/aprilfools.stf', 14, 'foil1_rand_2', 'Hey, you can''t eat that! Stop biting it and give it back to me!'),
('string/en/aprilfools.stf', 15, 'foil1_rand_3', 'Would someone help already!'),
('string/en/aprilfools.stf', 16, 'foil1_rand_4', 'Give that back! Anyone have a blaster on them?'),
('string/en/aprilfools.stf', 17, 'foil1_rand_5', 'Stop trying to eat my datapad and give it back!'),
('string/en/aprilfools.stf', 18, 'foil1_rand_6', 'Stop right where you are you little beast and give that back to me!'),
('string/en/aprilfools.stf', 19, 'foil1_rand_7', 'That''s sensitive equipment! Somebody stop these wretches!'),
('string/en/aprilfools.stf', 20, 'ewok1_rand_1', 'Den!'),
('string/en/aprilfools.stf', 21, 'ewok1_rand_2', 'Feech!'),
('string/en/aprilfools.stf', 22, 'ewok1_rand_3', 'Gyeesh'),
('string/en/aprilfools.stf', 23, 'ewok1_rand_4', 'Treek'),
('string/en/aprilfools.stf', 24, 'ewok1_rand_5', 'Yeha'),
('string/en/aprilfools.stf', 25, 'ewok1_rand_6', 'Dangar Ewok!'),
('string/en/aprilfools.stf', 26, 'ewok1_rand_7', 'Lurdo!'),
('string/en/aprilfools.stf', 27, 'foil1_finally', 'Finally! Thanks for taking care of those beasts. What a mess!'),
('string/en/aprilfools.stf', 28, 'bar_line_1', 'Sku.'),
('string/en/aprilfools.stf', 29, 'bar_line_2', 'What? I don''t understand your language but I assume you''re here for a drink.'),
('string/en/aprilfools.stf', 30, 'bar_line_3', 'Gyeesh, kush drojh?'),
('string/en/aprilfools.stf', 31, 'bar_line_4', 'Umm, look behind me. That''s what we have to offer. And could you tell your friends to quit running all over the place, it''s really distracting.'),
('string/en/aprilfools.stf', 32, 'bar_line_5', 'Acha... Kush jeeks? Gunda?'),
('string/en/aprilfools.stf', 33, 'bar_line_6', 'That? You want one of those? Ok here you go.'),
('string/en/aprilfools.stf', 34, 'bar_line_7', 'Chak, teeha.'),
('string/en/aprilfools.stf', 35, 'bar_line_8', 'Feech! Den gunda! Kvark!'),
('string/en/aprilfools.stf', 36, 'bar_line_9', 'What, too strong for ya? Well it''s 25 credits anyway so pay up.'),
('string/en/aprilfools.stf', 37, 'bar_line_10', 'Lurdo, yeha.'),
('string/en/aprilfools.stf', 38, 'bar_line_11', 'Hey you''re not leaving without paying!'),
('string/en/aprilfools.stf', 39, 'cantina_zone_emote', 'Four Ewoks walk into a cantina...'),
('string/en/aprilfools.stf', 40, 'bartender_name', 'a Bartender'),
('string/en/aprilfools.stf', 48, 'bar_foil1_rand_1', 'This little twerp stiffed me! Someone stop him!'),
('string/en/aprilfools.stf', 49, 'bar_foil1_rand_2', 'You''re not getting away from me. Stop running and pay up!'),
('string/en/aprilfools.stf', 50, 'bar_foil1_rand_3', 'Someone blast this dead beat!'),
('string/en/aprilfools.stf', 52, 'bar_foil1_rand_4', 'You ordered the drink, you pay for it!'),
('string/en/aprilfools.stf', 53, 'bar_foil1_rand_5', 'Someone call the authorities. Or better yet, just shoot this good for nothing stunted Wookiee!'),
('string/en/aprilfools.stf', 54, 'bar_foil1_rand_6', 'Give me my money! This business ain''t run on hand-outs!'),
('string/en/aprilfools.stf', 55, 'bar_foil1_rand_7', 'You''re making me mad. Anyone got a blaster handy?'),
('string/en/armor_rehue.stf', 1, 'equipped', 'You may only alter the color of your armor when it is unequipped.'),
('string/en/att_d.stf', 1, 'health', 'Health is a measure of your physical condition. It is a pool that is reduced every time you take physical damage. Should it reach zero, you will be incapacitated.\n\nCertain actions or skills may also require you to expend Health points. Certain tasks cannot be attempted unless you have enough Health to spend.\n\nYour current Health is displayed as a bar on your heads-up display.'),
('string/en/att_d.stf', 2, 'strength', 'Strength refers to the ability to exercise brute force in physical activity. The stronger and healthier a player is, the less Health points are expended for any given physical activity.'),
('string/en/att_d.stf', 3, 'constitution', 'The Constitution attribute is a measure of your ability to recover from damage. The higher this attribute is, the quicker you will regain lost Health points.'),
('string/en/att_d.stf', 4, 'action', 'Action is a measure of how rested your character is. As you grow tired, you will see your Action points being depleted. \n\nA task cannot be attempted unless you have enough Action points to attempt it. Should your Action pool reach zero, you may pass out from exhaustion and be incapacitated.\n\nYour action pool is displayed on your heads-up display as a bar indicating how many points you have left.'),
('string/en/att_d.stf', 5, 'quickness', 'The Quickness attribute is a measure of the player''s fitness. Players with a high Quickness spend less Action points in order to accomplish a given physical task than players with low Quickness do.'),
('string/en/att_d.stf', 6, 'stamina', 'Stamina is a measure of how quickly characters recover from intense physical activity. The higher this attribute is, the more quickly a character''s Action pool will recover.'),
('string/en/att_d.stf', 7, 'mind', 'Mind is a measure of your alertness and mental capacity. A player with a higher Mind is better able to tackle complex technical tasks, and is less susceptible to being confused, stunned or distracted.\n\nMany tasks or skills may require the expenditure of points from the Mind pool. Should you not have enough Mind to spare, you will not be able to perform the action.\n\nYour current Mind pool is displayed as a bar on your heads-up display.'),
('string/en/att_d.stf', 8, 'focus', 'The Focus attribute is a measure of your character''s effectiveness in concentrating on mental activity, without becoming distracted. A player with a high Focus attribute can accomplish more mental challenges in a shorter period of time.\n\nThe higher your Focus attribute is, the less Mind points will be needed to perform a given skill or action.'),
('string/en/att_d.stf', 9, 'willpower', 'A character with a high Willpower attribute finds it easier to recover from mental exertion, or recover from mental stress or trauma. This attribute affects how quickly the Mind pool is replenished.'),
