('string/en/auction.stf', 11, 'vendor_status_empty', 'Your vendor %TO is now empty.  If this vendor is listed on the planetary ad campaign, it will be removed from the overhead map.  If this vendor remains empty for a period of time, you will receive another warning and eventually it will be removed from the game.'),
('string/en/auction.stf', 12, 'vendor_status_normal', 'Your vendor %TO is now functioning normally.'),
('string/en/auction.stf', 13, 'vendor_status_unaccessed', 'Your vendor %TO has not been used in quite some time.  You should place an item for sale on your vendor soon to prevent the vendor from being removed from the game.\n'),
('string/en/auction.stf', 14, 'vendor_status_endangered', 'Your vendor %TO is in danger of being removed from the game.   You should place an item for sale on it to ensure that it does not get removed from the game.'),
('string/en/auction.stf', 15, 'vendor_status_deleted', 'Your vendor was deleted from the game due to inactivity or lack of available items to sell.'),
