('string/en/cbt_spam.stf', 1, 'a_auto_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou let loose a full-auto arc towards %TT, but %ST counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU lets loose a full-auto arc towards %TT, but %ST counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU lets loose a full-auto arc in your direction, but you counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 2, 'a_auto_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou let loose a full-auto arc towards %TT, but %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU lets loose a full-auto arc towards %TT, but %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU lets loose a full-auto arc in your direction, but you block it!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 3, 'a_auto_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou let loose a full-auto arc towards %TT but %ST evades!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU lets loose a full-auto arc towards %TT, but %ST evades every shot.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU lets loose a full-auto arc towards you, but you evade every shot.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 4, 'a_auto_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou unleash a full-auto arc towards %TT and do %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU unleashes a full-auto arc towards %TT and hits for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU unleashes a full-auto arc towards you and hits for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 5, 'a_auto_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour full-auto arc fails to hit %TT.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s full-auto arc fails to hit %PU target, %TT.\n~\n~\n~\n~\n~\n~\n~\n~\nThe air is filled with shots as %TU fires a full-auto arc, but no shots hit you.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 6, 'acid_beam_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use your acid rifle to fire a beam of acid on %TT for %DI points of damage, but %ST counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on %TT for %DI points of damage, but %ST counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on you for %DI points of damage, but you counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 7, 'acid_beam_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use your acid rifle to fire a beam of acid on %TT for %DI points of damage, but %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on %TT for %DI points of damage, but %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on you for %DI points of damage, but you block it!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 8, 'acid_beam_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use your acid rifle to fire a beam of acid on %TT for %DI points of damage, but %ST evades it.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on %TT for %DI points of damage, but %ST evades it.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on you for %DI points of damage, but you evade it.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 9, 'acid_beam_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use your acid rifle to fire a beam of acid on %TT for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on %TT for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses an acid rifle to fire a beam of acid on you for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
