('string/en/cbt_spam.stf', 465, 'head_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou aim for %TT''s head, but %TU seizes the opportunity to counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU aims for %TT''s head, but %ST seizes the opportunity to counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU shoots at your head, but you seize the opportunity to counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 466, 'head_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou aim for %TT''s head, but %TU seizes the opportunity to counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU aims for %TT''s head, but %ST seizes the opportunity to block it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU shoots at your head, but you seize the opportunity to block it!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 467, 'head_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou shoot at %TT''s head, but %ST ducks out of the way.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU shoots at %TT''s head, but %ST ducks out of the way.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU shoots at your head, but you duck out of the way.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 468, 'head_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nHead shot! Your shot hits %TT on the head for %DI points of damage.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU scores a head shot %TT for %DI points of damage.\n~\n~\n~\n~\n~\n~\n~\n~\nOW! %TU''s shot hits your head for %DI points of damage.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 469, 'head_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou aim for %TT''s head, but miss.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU tries to shoot %TU in the head, but misses.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU misses %PU shot at your head.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
