INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/cbt_spam.stf', 780, 's_auto_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour full-auto burst backfires as %TT counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at %TT, but it backfires as %ST counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at you, but it backfires on %OU as you counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 781, 's_auto_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour full-auto burst backfires as %TT blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at %TT, but it backfires as %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at you, but it backfires on %OU as you block it!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 782, 's_auto_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n%TT evades your full-auto burst with ease.\n~\n~\n~\n~\n~\n~\n~\n~\n%TT easily evades %TU''s full-auto burst.\n~\n~\n~\n~\n~\n~\n~\n~\nYou easily evade %TU''s full-auto burst.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 783, 's_auto_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou fire a full-auto burst at %TT and hit for %DI points of damage.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at %TT and hits for %DI points of damage.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at you and hits for %DI points of damage.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 784, 's_auto_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou fire a full-auto burst at %TT but it goes wide.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at %TT but misses.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU fires a full-auto burst at you, but the shots go wide.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
