('string/en/cbt_spam.stf', 1610, 'saber2hphantom_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour Faalo''s Will misses %TT.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s Faalo''s Will misses %TT.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s Faalo''s Will misses you.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1611, 'saber1hflurry2_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use Whirlwind of the Force on %TT for %DI points of damage, but %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on %TT for %DI points of damage, but %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on you for %DI points of damage, but you block it!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1612, 'saber1hflurry2_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use Whirlwind of the Force on %TT for %DI points of damage, but %ST counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on %TT for %DI points of damage, but %ST counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on you for %DI points of damage, but you counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1613, 'saber1hflurry2_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use Whirlwind of the Force on %TT for %DI points of damage, but %ST evades it.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on %TT for %DI points of damage, but %ST evades it.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on you for %DI points of damage, but you evade it.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1614, 'saber1hflurry2_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use Whirlwind of the Force on %TT for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on %TT for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses Whirlwind of the Force on you for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1615, 'saber1hflurry2_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour Whirlwind of the Force misses %TT.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s Whirlwind of the Force misses %TT.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s Whirlwind of the Force misses you.\n~\n~\n~\n~\n~\n~\n~\n~\n~');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/cbt_spam.stf', 1616, 'forceknockdown3_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to knock %TT down using the Force, but somehow %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock %TT down using the Force, but somehow %ST blocks it!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock you down using the Force, but somehow you block it!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1617, 'forceknockdown3_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to knock %TT down using the Force, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock %TT down using the force, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock you down using the Force, but you fight through it and counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1618, 'forceknockdown3_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to knock %TT down using the Force, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock %TT down using the Force, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock you down using the Force, but you are able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1619, 'forceknockdown3_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to knock %TT down using the Force!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock %TT down using the Force!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock you down using the Force!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1620, 'forceknockdown3_hit_knockdown', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou have used the Force to knock %TT down!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU has used the Force to knock %TT down!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU has used the Force to knock you down!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1621, 'forceknockdown3_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to knock %TT down using the Force, but miss!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock %TT down using the Force, but misses!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to knock you down using the Force, but misses!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1622, 'forceintimidate1_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but %ST is able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind , but %ST is able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but you are able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1623, 'forceintimidate1_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but you fight through it and counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1624, 'forceintimidate1_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but you are able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1625, 'forceintimidate1_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use the Force to invade %TT''s mind and cause intense intimidation!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses the Force to invade %TT''s mind and cause intense intimidation!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses the Force to invade your mind and causes intense intimidation!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1626, 'forceintimidate1_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but lose concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind, but loses concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but loses concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1627, 'forceintimidate2_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but %ST is able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind , but %ST is able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but you are able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1628, 'forceintimidate2_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but you fight through it and counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1629, 'forceintimidate2_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but you are able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1630, 'forceintimidate2_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use the Force to invade %TT''s mind and cause intense intimidation!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses the Force to invade %TT''s mind and cause intense intimidation!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses the Force to invade your mind and causes intense intimidation!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1631, 'forceintimidate2_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to invade %TT''s mind, but lose concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade %TT''s mind, but loses concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to invade your mind, but loses concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1632, 'forcedrain_block', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to siphon energy from %TT, but %ST is able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon energy from %TT, but %ST is able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon energy from you, but you are able to resist!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1633, 'forcedrain_counter', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to siphon energy from %TT, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon energy from %TT, but %ST fights through it and counterattacks!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon your energy, but you fight through it and counterattack!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1634, 'forcedrain_evade', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to siphon energy from %TT, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon energy from %TT, but %ST is able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon your energy, but you are able to evade.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1635, 'forcedrain_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou use the Force to siphon %TT''s energy!\n~\n~\n~\nYou use the Force to siphon %DI Force points of %TT''s energy!\n~\n~\n~\n~\n%TU uses the Force to siphon %TT''s energy!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU uses the Force to siphon %DI Force points of your energy!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1636, 'forcedrain_miss', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou attempt to use the Force to siphon energy from %TT, but lose concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon energy from %TT, but loses concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU attempts to use the Force to siphon your energy, but loses concentration!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1637, 'forcefeedback_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour reflective barrier causes %TT to be injured by their own attack for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU is protected by a reflective barrier of the Force causing %TT to be injured for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n%TU is protected by a reflective barrier of the Force causing you to be injured for %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1638, 'forcearmor_hit', '~\n~\n~\n~\n~\n~\nYour barrier of the Force protects you from %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1639, 'forceshield_hit', '~\n~\n~\n~\n~\n~\nYour barrier of the Force protects you from %DI points of damage!\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1640, 'forceabsorb_hit', '~\n~\n~\n~\n~\n~\nYou gain %DI Force power from your enemies attack.\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1641, 'forcetransfer_hit', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYou transfer %DI Force points to %TT.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU transfers %DI Force points to %TT.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU transfers %DI Force points to you.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1642, 'frs_dark_envy_drain', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nEnvy surges through you doing %DI Force points of disruption to %TT.\n~\n~\n~\n~\n~\n~\n~\n~\nEnvy surges through %TU doing %DI Force points of disruption to %TT.\n~\n~\n~\n~\n~\n~\n~\n~\nEnvy surges through %TU doing %DI Force points of disruption to you.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1643, 'frs_dark_envy_gain', '... You gain %DI Force power from your attack.'),
('string/en/cbt_spam.stf', 1644, 'frs_dark_suffering', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n%TT is encompassed in a wave of suffering.  %ST is drained for %DI attribute points.\n~\n~\n~\n~\n~\n~\n~\n~\n%TT is encompassed in a wave of suffering from %TU''s attack.  %ST is drained for %DI attribute points.\n~\n~\n~\n~\n~\n~\n~\n~\nYou are encompassed in a wave of suffering from %TU''s attack.  You are drained for %DI attribute points.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1645, 'frs_dark_vengeance', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour vengeance lashes out of %TT inflicting %DI points worth of wounds.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s vengeance lashes out at %TT inflicting %DI points of wounds.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s vengeance lashes out at you inflicting %DI points of wounds.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1646, 'frs_light_vigilance', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nVigilance focuses your attack doing %DI Force points of disruption to %TT.\n~\n~\n~\n~\n~\n~\n~\n~\nVigilance focuses %TU''s attack doing %DI Force points of disruption to %TT.\n~\n~\n~\n~\n~\n~\n~\n~\nVigilance focuses %TU''s attack doing %DI Force points of disruption to you.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1647, 'frs_light_wisdom_drain', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nWisdom guides your attack draining %DI attribute points from %TT.\n~\n~\n~\n~\n~\n~\n~\n~\nWisdom guides %TU''s attack draining %DI attribute points from %TT.\n~\n~\n~\n~\n~\n~\n~\n~\nWisdom guides %TU''s attack draining you of %DI attribute points.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/cbt_spam.stf', 1648, 'frs_light_wisdom_gain', '... You gain %DI attribute points from your attack.'),
('string/en/cbt_spam.stf', 1649, 'frs_light_serenity', '~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\n~\nYour serenity washes over %TT weakening %OT by %DI attribute points.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s serenity washes over %TT weakening %OT by %DI attribute points.\n~\n~\n~\n~\n~\n~\n~\n~\n%TU''s serenity washes over you weakening you by %DI attribute points.\n~\n~\n~\n~\n~\n~\n~\n~\n~'),
('string/en/celebrity/boss_nass.stf', 1, 'npc_1', 'Boss Nass.  Thatsa meesa name.'),
('string/en/celebrity/boss_nass.stf', 2, 'player_1', 'Oh dear.  Another one.'),
('string/en/celebrity/boss_nass.stf', 3, 'player_2', 'You''re a Gungan?'),
('string/en/celebrity/boss_nass.stf', 4, 'npc_2', 'Another one?  What yousa meanin?'),
('string/en/celebrity/boss_nass.stf', 5, 'player_3', 'Oh, nothing.'),
('string/en/celebrity/boss_nass.stf', 6, 'npc_6', 'Meesa thought so.'),
('string/en/celebrity/boss_nass.stf', 7, 'player_4', 'Gungan.  You guys don''t speak basic very well.'),
('string/en/celebrity/boss_nass.stf', 8, 'npc_7', 'Meesa speaking very well!  Thankyouverymuch.'),
('string/en/celebrity/boss_nass.stf', 9, 'npc_3', 'Meesa big Gungan.  Meesa strong Gungan.'),
('string/en/celebrity/boss_nass.stf', 10, 'player_5', 'Yes, I''m sure you''re quite strong.'),
('string/en/celebrity/boss_nass.stf', 11, 'npc_4', 'That why meesa in charge.'),
('string/en/celebrity/boss_nass.stf', 12, 'player_7', 'Yes, yes, of course you are.'),
('string/en/celebrity/boss_nass.stf', 13, 'npc_8', 'Better be believing it!'),
('string/en/celebrity/boss_nass.stf', 14, 'player_8', 'Oh, right.  King of the Gungans.'),
('string/en/celebrity/boss_nass.stf', 15, 'npc_9', 'That would be me!'),
('string/en/celebrity/boss_nass.stf', 16, 'player_6', 'What do you eat?'),
('string/en/celebrity/boss_nass.stf', 17, 'npc_5', 'Meesa eat fish, eopie, whatever meesa find.'),
('string/en/celebrity/boss_nass.stf', 18, 'player_9', 'You wouldn''t eat me, right?'),
('string/en/celebrity/boss_nass.stf', 19, 'npc_10', 'Meesa no think so.'),
('string/en/celebrity/boss_nass.stf', 20, 'player_10', 'How bout other Gungans?'),
('string/en/celebrity/boss_nass.stf', 21, 'npc_11', 'What kinda monster yousa thinking me?'),
('string/en/celebrity/c3po.stf', 1, 'npc_1', 'Oh dear, now what?  Have I done something wrong?'),
('string/en/celebrity/c3po.stf', 2, 'player_1', 'I don''t know.  Have you?'),
('string/en/celebrity/c3po.stf', 3, 'player_2', 'I don''t think so.'),
('string/en/celebrity/c3po.stf', 4, 'npc_2', 'I don''t believe so.  But people rarely talk to me except to complain.'),
('string/en/celebrity/c3po.stf', 5, 'player_3', 'Get a lot of complaints?'),
('string/en/celebrity/c3po.stf', 6, 'npc_6', 'It seems to be all I get.'),
('string/en/celebrity/c3po.stf', 7, 'player_4', 'That''s terrible.'),
('string/en/celebrity/c3po.stf', 8, 'npc_7', 'I''ve actually grown accustomed to it.'),
('string/en/celebrity/c3po.stf', 9, 'npc_3', 'Oh, thank goodness.  I was trying to keep out of trouble this time.'),
('string/en/celebrity/c3po.stf', 10, 'player_5', 'This time?'),
('string/en/celebrity/c3po.stf', 11, 'npc_4', 'Ah.  Yes.  Well, I do seem to get into a lot of trouble.  Actually Artoo gets me into most of it.  Blasted little bolt heap.'),
('string/en/celebrity/c3po.stf', 12, 'player_7', 'Artoo the famous droid of the Alliance?'),
('string/en/celebrity/c3po.stf', 13, 'npc_8', 'Oh gracious.  It seems his reputation precedes him again.'),
('string/en/celebrity/c3po.stf', 14, 'player_8', 'Are you talking about an R2 Unit?'),
('string/en/celebrity/c3po.stf', 15, 'npc_9', 'Not just any R2 Unit.  This one is special.  His specialty seems to be finding trouble.'),
('string/en/celebrity/c3po.stf', 16, 'player_6', 'What kind of trouble?'),
('string/en/celebrity/c3po.stf', 17, 'npc_5', 'Oh, I''ve been in all kinds.  I''ve been kidnapped, been in battles, been on secret missions...It''s all too much.'),
('string/en/celebrity/c3po.stf', 18, 'player_9', 'Were you ever hurt?'),
('string/en/celebrity/c3po.stf', 19, 'npc_10', 'I seem to think so.  But I can''t really remember.  '),
('string/en/celebrity/c3po.stf', 20, 'player_10', 'Kidnapped?'),
('string/en/celebrity/c3po.stf', 21, 'npc_11', 'Oh, those wretched Jawas.  I''ll never forgive them for that.'),
('string/en/celebrity/captain_eso.stf', 1, 'npc_1', 'You''re not here to kill me are you?'),
('string/en/celebrity/captain_eso.stf', 2, 'player_1', 'Uh...no.'),
('string/en/celebrity/captain_eso.stf', 3, 'player_2', 'Are there people trying to kill you?'),
('string/en/celebrity/captain_eso.stf', 4, 'npc_2', 'Good.  Cause it wasn''t going to happen if you were.'),
('string/en/celebrity/captain_eso.stf', 5, 'player_3', 'I believe you.'),
('string/en/celebrity/captain_eso.stf', 6, 'npc_6', 'You''d better.  You have no idea the horrors I''ve seen.'),
('string/en/celebrity/captain_eso.stf', 7, 'player_4', 'You''re pretty confidant.'),
('string/en/celebrity/captain_eso.stf', 8, 'npc_7', 'I have to be to survive out here?  You don''t know what it takes to survive in this jungle.'),
('string/en/celebrity/captain_eso.stf', 9, 'npc_3', 'Of course.  There always are.  Errand boys mostly, sent down to collect the bill for a check they don''t deserve.'),
('string/en/celebrity/captain_eso.stf', 10, 'player_5', 'What are you talking about?'),
('string/en/celebrity/captain_eso.stf', 11, 'npc_4', 'You know what you call an assassin who goes out to kill another assassin?'),
('string/en/celebrity/captain_eso.stf', 12, 'player_7', 'This conversation has gotten weird...'),
('string/en/celebrity/captain_eso.stf', 13, 'npc_8', 'Things are always weird here in the Jungle.  The Imperials want me dead and the Jungle keeps me alive.  That''s the way it is.'),
('string/en/celebrity/captain_eso.stf', 14, 'player_8', 'No idea.'),
('string/en/celebrity/captain_eso.stf', 15, 'npc_9', 'There''s nothing anyone can do to stop me.  And there is no answer to that question.'),
('string/en/celebrity/captain_eso.stf', 16, 'player_6', 'Errand boys?'),
('string/en/celebrity/captain_eso.stf', 17, 'npc_5', 'The Imperials send their commandos, their soldiers, their droids.  None of them find me.  Except the ones that are already dead.'),
('string/en/celebrity/captain_eso.stf', 18, 'player_9', 'You''re a little crazy...'),
('string/en/celebrity/captain_eso.stf', 19, 'npc_10', 'Not just a little.'),
('string/en/celebrity/captain_eso.stf', 20, 'player_10', 'I''m gonna go now.'),
('string/en/celebrity/captain_eso.stf', 21, 'npc_11', 'Be seein'' ya.  You won''t see me, but I''ll be seeing you.'),
('string/en/celebrity/charal.stf', 1, 'npc_1', 'You will be punished severely for being here!'),
('string/en/celebrity/charal.stf', 2, 'player_1', 'Who are you?'),
('string/en/celebrity/charal.stf', 3, 'player_2', 'By you?'),
('string/en/celebrity/charal.stf', 4, 'npc_2', 'I am the Night Sister of Endor, a powerful witch, and you will be sorry to have met me...'),
('string/en/celebrity/charal.stf', 5, 'npc_3', 'King Terak and his marauders!'),
('string/en/celebrity/chewbacca.stf', 1, 'npc_1', 'Rrraaargh.  Rrrraaaaawwwwrrrr!'),
('string/en/celebrity/chewbacca.stf', 2, 'player_1', 'Um...what?'),
('string/en/celebrity/chewbacca.stf', 3, 'player_2', 'I don''t speak Wookie.'),
('string/en/celebrity/chewbacca.stf', 4, 'npc_2', 'Grrrr....'),
('string/en/celebrity/chewbacca.stf', 5, 'player_3', 'I don''t know what I said wrong.'),
('string/en/celebrity/chewbacca.stf', 6, 'npc_6', 'Rrrrraaaawwwrrrggghhhh.'),
('string/en/celebrity/chewbacca.stf', 7, 'player_4', 'Um...sure.'),
('string/en/celebrity/chewbacca.stf', 8, 'npc_7', 'Hhhrrrarrraggghhhh.'),
('string/en/celebrity/chewbacca.stf', 9, 'npc_3', '<grunt>'),
('string/en/celebrity/chewbacca.stf', 10, 'player_5', 'Sorry.  I don''t speak Shyriwook.'),
('string/en/celebrity/chewbacca.stf', 11, 'npc_4', 'Rrrraaaaahhhharrrrrgghh.'),
('string/en/celebrity/chewbacca.stf', 12, 'player_7', 'Whatever you say.'),
('string/en/celebrity/chewbacca.stf', 13, 'npc_8', 'Wwwwarrrrggghhhhhhh.'),
('string/en/celebrity/chewbacca.stf', 14, 'player_8', 'Is that right?'),
('string/en/celebrity/chewbacca.stf', 15, 'npc_9', 'Grrooowwwllll....'),
('string/en/celebrity/chewbacca.stf', 16, 'player_6', 'Ok then.'),
('string/en/celebrity/chewbacca.stf', 17, 'npc_5', 'HHHHHHHHHRRRRRRRRRRAAAAAAAAAAAAAAAAERRRRRRRRRRRRRRRRGGGGGGGGGGGGGHHHHHHHHHH!!!!!'),
('string/en/celebrity/chewbacca.stf', 18, 'player_9', 'Dear gracious me, I''m so sorry.'),
('string/en/celebrity/chewbacca.stf', 19, 'npc_10', 'GrrAAwwrrgh?'),
('string/en/celebrity/chewbacca.stf', 20, 'player_10', 'Uh...grr?'),
('string/en/celebrity/chewbacca.stf', 21, 'npc_11', 'Hmph.'),
('string/en/celebrity/commander_byrne.stf', 1, 'npc_1', 'No one should be here but my regiment and the salvage company.  Which are you?'),
('string/en/celebrity/commander_byrne.stf', 2, 'player_1', 'I''m with you.'),
('string/en/celebrity/commander_byrne.stf', 3, 'player_2', 'Salvage.'),
('string/en/celebrity/commander_byrne.stf', 4, 'npc_2', 'Do you think I''m a fool?  Where''s your uniform?'),
('string/en/celebrity/commander_byrne.stf', 5, 'npc_3', 'Carry on then.'),
('string/en/celebrity/corporal_sova.stf', 1, 'npc_1', 'The Empire has too much control over our lives.'),
('string/en/celebrity/corporal_sova.stf', 2, 'player_1', 'I work for the Empire.'),
('string/en/celebrity/corporal_sova.stf', 3, 'player_2', 'I agree.'),
('string/en/celebrity/corporal_sova.stf', 4, 'npc_2', 'Well that''s too bad.  I guess we''re done talking.'),
('string/en/celebrity/corporal_sova.stf', 5, 'player_3', 'Wait, I have a question.'),
('string/en/celebrity/corporal_sova.stf', 6, 'npc_6', 'Nope.  I''ve revealed too much already.  No more talking to you.'),
('string/en/celebrity/corporal_sova.stf', 7, 'player_4', 'That''s it?'),
('string/en/celebrity/corporal_sova.stf', 8, 'npc_7', 'For an Imperial?  Yep.  That''s it.'),
('string/en/celebrity/corporal_sova.stf', 9, 'npc_3', 'I had a feeling you would.  That''s why I joined the Alliance.  To meet new people like you who agreed with me.'),
('string/en/celebrity/corporal_sova.stf', 10, 'player_5', 'Not everyone agrees.'),
('string/en/celebrity/corporal_sova.stf', 11, 'npc_4', 'That''s true.  I know that all too well.'),
('string/en/celebrity/corporal_sova.stf', 12, 'player_7', 'You speak from experience, eh?'),
('string/en/celebrity/corporal_sova.stf', 13, 'npc_8', 'That''s right.  But enough about that.'),
('string/en/celebrity/corporal_sova.stf', 14, 'player_8', 'Me too.'),
('string/en/celebrity/corporal_sova.stf', 15, 'npc_9', 'Well, I''m sorry to hear that, but I''m glad to have found a kindred spirit.'),
('string/en/celebrity/corporal_sova.stf', 16, 'player_6', 'The Alliance, eh?'),
('string/en/celebrity/corporal_sova.stf', 17, 'npc_5', 'Yes.  Are you interested in the plight of the rebels?'),
('string/en/celebrity/corporal_sova.stf', 18, 'player_9', 'Not too much.'),
('string/en/celebrity/corporal_sova.stf', 19, 'npc_10', 'You should be.  They agree with us as well, and they''re doing something about it!'),
('string/en/celebrity/corporal_sova.stf', 20, 'player_10', 'I''d like to join up actually.'),
('string/en/celebrity/corporal_sova.stf', 21, 'npc_11', 'Splendid!  There are recruiters even here on Naboo.  I can''t give out their names, but you''ll find them if you look.'),
('string/en/celebrity/dera_darklighter.stf', 1, 'npc_1', 'Hello.  My name is Dera Darklighter.  Is there something I can do for you?'),
('string/en/celebrity/dera_darklighter.stf', 2, 'player_1', 'I''ve heard of your family.  They''re famous.'),
('string/en/celebrity/dera_darklighter.stf', 3, 'player_2', 'Aren''t you part of the rebellion?'),
('string/en/celebrity/dera_darklighter.stf', 4, 'npc_2', 'Yes, I know.  I am actually PART of the family.  It''s not just Biggs you know!'),
('string/en/celebrity/dera_darklighter.stf', 5, 'player_3', 'Well...nice talking to you.'),
('string/en/celebrity/dera_darklighter.stf', 6, 'player_4', 'How rude!'),
('string/en/celebrity/dera_darklighter.stf', 7, 'player_5', 'It''s ok, I''m not with the Empire...'),
('string/en/celebrity/dera_darklighter.stf', 8, 'player_6', 'Sorry, I have you confused with someone else.'),
('string/en/celebrity/dera_darklighter.stf', 9, 'player_7', 'I guess I''ll be on my way.'),
('string/en/celebrity/dera_darklighter.stf', 10, 'player_8', 'Don''t think I''ve fallen for your tricks...'),
('string/en/celebrity/dera_darklighter.stf', 11, 'player_9', 'Guess I''ll pack up and go then.'),
('string/en/celebrity/dera_darklighter.stf', 12, 'player_10', 'Don''t have many friends do you?'),
('string/en/celebrity/dera_darklighter.stf', 13, 'npc_3', 'I don''t know where you would have heard such a rumor.'),
('string/en/celebrity/dera_darklighter.stf', 14, 'npc_4', 'Well as slick as you are I''m surprised you haven''t found ALL the rebels on Tatooine.'),
('string/en/celebrity/dera_darklighter.stf', 15, 'npc_5', 'I guess so.'),
('string/en/celebrity/dera_darklighter.stf', 16, 'npc_6', 'Sorry.  I''ll try to be more pleasant in the future.'),
('string/en/celebrity/dera_darklighter.stf', 17, 'npc_7', 'Like I care.'),
('string/en/celebrity/dera_darklighter.stf', 18, 'npc_8', 'Good, I hope you can find your way out of here.'),
('string/en/celebrity/dera_darklighter.stf', 19, 'npc_9', 'Don''t worry about what I think.'),
('string/en/celebrity/dera_darklighter.stf', 20, 'npc_10', 'Hope you can do that on your own.'),
('string/en/celebrity/dera_darklighter.stf', 21, 'npc_11', 'Don''t need many.'),
('string/en/celebrity/diax.stf', 1, 'npc_1', 'You are not one of us...'),
('string/en/celebrity/diax.stf', 2, 'player_1', 'Sorry, I''ll go.'),
('string/en/celebrity/diax.stf', 3, 'player_2', 'Who are you?'),
('string/en/celebrity/diax.stf', 4, 'npc_2', 'Good!'),
('string/en/celebrity/diax.stf', 5, 'npc_3', 'We are the Sisters of the Night!'),
('string/en/celebrity/fath_hray.stf', 1, 'npc_1', 'You are not one of us...'),
('string/en/celebrity/fath_hray.stf', 2, 'player_1', 'Sorry, I''ll go.'),
('string/en/celebrity/fath_hray.stf', 3, 'player_2', 'Who are you?'),
('string/en/celebrity/fath_hray.stf', 4, 'npc_2', 'Good!'),
('string/en/celebrity/fath_hray.stf', 5, 'npc_3', 'We are the Sisters of the Night!'),
('string/en/celebrity/fightmaster_jorak.stf', 1, 'npc_1', 'Are you prepared to fight?'),
('string/en/celebrity/fightmaster_jorak.stf', 2, 'player_1', 'Um...no.'),
('string/en/celebrity/fightmaster_jorak.stf', 3, 'player_2', 'Sure.'),
('string/en/celebrity/fightmaster_jorak.stf', 4, 'npc_2', 'Then begone!'),
('string/en/celebrity/fightmaster_jorak.stf', 5, 'npc_3', 'Then meet me at Dawn in this very spot.'),
('string/en/celebrity/general_otto.stf', 1, 'npc_1', 'What are you doing here?'),
('string/en/celebrity/general_otto.stf', 2, 'player_1', 'Just a traveler.'),
('string/en/celebrity/general_otto.stf', 3, 'player_2', 'I''m looking for Nym.'),
('string/en/celebrity/general_otto.stf', 4, 'npc_2', 'Then don''t let me keep you.'),
('string/en/celebrity/general_otto.stf', 5, 'npc_3', 'So am I.  If you find him, tell him that the Empire will no longer tolerate his existence!'),
('string/en/celebrity/gerrick_lond.stf', 1, 'npc_1', 'Welcome to Jabba''s town house.  What can be done for you?  Hm?'),
('string/en/celebrity/gerrick_lond.stf', 2, 'player_1', 'Jabba has a town house?'),
('string/en/celebrity/gerrick_lond.stf', 3, 'player_2', 'I''m here to see Jabba.'),
('string/en/celebrity/gerrick_lond.stf', 4, 'npc_2', 'Hm?  Yes.  Of course he does.  Why?  Shouldn''t he?  Hm?'),
('string/en/celebrity/gerrick_lond.stf', 5, 'player_3', 'No, I just didn''t know.'),
('string/en/celebrity/gerrick_lond.stf', 6, 'npc_6', 'Well now you do.  Hm.'),
('string/en/celebrity/gerrick_lond.stf', 7, 'player_4', 'Does he ever come here?'),
('string/en/celebrity/gerrick_lond.stf', 8, 'npc_7', 'On occasion.  Mostly we do business from here, and keep Jabba''s guests very comfortable.  Hm.'),
('string/en/celebrity/gerrick_lond.stf', 9, 'npc_3', 'I''m sorry, but Master is away at the Palace.'),
('string/en/celebrity/gerrick_lond.stf', 10, 'player_5', 'You know that''s actually a monastery, right?'),
('string/en/celebrity/gerrick_lond.stf', 11, 'npc_4', 'The old B''omarr monastery?  Hm...Believe me, it is Jabba''s Palace.  No more, and no less.'),
('string/en/celebrity/gerrick_lond.stf', 12, 'player_7', 'What about the monks?'),
('string/en/celebrity/gerrick_lond.stf', 13, 'npc_8', 'Oh, those spider droids? Hm? Believe me when I tell you that they know their place there.'),
('string/en/celebrity/gerrick_lond.stf', 14, 'player_8', 'He stole it.  What if someone steals it from him?'),
('string/en/celebrity/gerrick_lond.stf', 15, 'npc_9', 'I would feel pity for anyone who thought they could take the Palace back away from the master.  Hm?  Oh yes.  Much pity.'),
('string/en/celebrity/gerrick_lond.stf', 16, 'player_6', 'When do you expect him?'),
('string/en/celebrity/gerrick_lond.stf', 17, 'npc_5', 'Hm?  We don''t expect the Master.  He comes and goes at his pleasure.  We strive only to serve.  Hm.'),
('string/en/celebrity/gerrick_lond.stf', 18, 'player_9', 'Why do you keep saying Hm?'),
('string/en/celebrity/gerrick_lond.stf', 19, 'npc_10', 'It''s a nervous tick.  Hm.  I assure you.  Nothing more.  Hm.'),
('string/en/celebrity/gerrick_lond.stf', 20, 'player_10', 'Well, I guess I''ll go check at the palace then.'),
('string/en/celebrity/gerrick_lond.stf', 21, 'npc_11', 'Hm.  And that is where you shall find him.'),
('string/en/celebrity/gethzerion.stf', 1, 'npc_1', 'I am the ruler of the Nightsisters.  You have no place here...'),
('string/en/celebrity/gethzerion.stf', 2, 'player_1', 'Sorry, I''ll go.'),
('string/en/celebrity/gethzerion.stf', 3, 'player_2', 'I like it here.'),
('string/en/celebrity/gethzerion.stf', 4, 'npc_2', 'Good!'),
('string/en/celebrity/gethzerion.stf', 5, 'npc_3', 'Fool!'),
('string/en/celebrity/gins_darone.stf', 1, 'npc_1', 'Who do you work for?  Speak up!'),
('string/en/celebrity/gins_darone.stf', 2, 'player_1', 'I''m here on my own.'),
('string/en/celebrity/gins_darone.stf', 3, 'player_2', 'I''m part of a group...'),
('string/en/celebrity/gins_darone.stf', 4, 'npc_2', 'Well, that can get you killed.  Do you know what there is around here?'),
('string/en/celebrity/gins_darone.stf', 5, 'player_3', 'Jungle?'),
('string/en/celebrity/gins_darone.stf', 6, 'npc_6', 'Money.  Parts of the Death Star that fell to the planet.  They''re worth a lot to the right bidders.  And they''re all mine, so stay out of my way and stay out of my people''s way.'),
('string/en/celebrity/gins_darone.stf', 7, 'player_4', 'Debris?'),
('string/en/celebrity/gins_darone.stf', 8, 'npc_7', 'That debris is worth cold hard credits and I intend to cash out.   Just stay out of the way, all right?'),
('string/en/celebrity/gins_darone.stf', 9, 'npc_3', 'I don''t need to hear it.  As long as you''re not here to stop me.'),
('string/en/celebrity/gins_darone.stf', 10, 'player_5', 'Stop you from what?'),
('string/en/celebrity/gins_darone.stf', 11, 'npc_4', 'Heh.  From collecting my due.  My salvage team is gonna reap the rewards of this stuff.'),
('string/en/celebrity/gins_darone.stf', 12, 'player_7', 'What stuff?'),
('string/en/celebrity/gins_darone.stf', 13, 'npc_8', 'Pieces of the Death Star.  They''re ours for the taking.'),
('string/en/celebrity/gins_darone.stf', 14, 'player_8', 'Salvage team?'),
('string/en/celebrity/gins_darone.stf', 15, 'npc_9', 'That''s right.  I run a tight group here.  We''re gonna make a bundle.'),
('string/en/celebrity/gins_darone.stf', 16, 'player_6', 'I''m not.'),
('string/en/celebrity/gins_darone.stf', 17, 'npc_5', 'Good, cause I wouldn''t have let you.  And neither would my team.'),
('string/en/celebrity/gins_darone.stf', 18, 'player_9', 'Your team?'),
('string/en/celebrity/gins_darone.stf', 19, 'npc_10', 'My guys are here to collect salvage, but don''t think that means they''re pushovers.  They''ll take you down if I give the word.  Got it?'),
('string/en/celebrity/gins_darone.stf', 20, 'player_10', 'I''m done.'),
('string/en/celebrity/gins_darone.stf', 21, 'npc_11', 'Me too.  Talk to you later if you live that long.'),
('string/en/celebrity/gorr_ebelt.stf', 1, 'npc_1', 'Shady work here on Naboo if you want it.'),
('string/en/celebrity/gorr_ebelt.stf', 2, 'player_1', 'Shady?'),
('string/en/celebrity/gorr_ebelt.stf', 3, 'player_2', 'Work?'),
('string/en/celebrity/gorr_ebelt.stf', 4, 'npc_2', 'Well, not everything we do here is strictly above the bar.  Say, you''re not with law enforcement are you?'),
('string/en/celebrity/gorr_ebelt.stf', 5, 'player_3', 'Well, no.'),
('string/en/celebrity/gorr_ebelt.stf', 6, 'npc_6', 'Well, then perhaps you could check with some of my associates.  They might have some work for you.'),
('string/en/celebrity/gorr_ebelt.stf', 7, 'player_4', 'Actually, I am.'),
('string/en/celebrity/gorr_ebelt.stf', 8, 'npc_7', 'Oh.  Well then ignore everything I say.'),
('string/en/celebrity/gorr_ebelt.stf', 9, 'npc_3', 'Yes.  Work.  You do know what work is, right?'),
('string/en/celebrity/gorr_ebelt.stf', 10, 'player_5', 'Work is for other people.'),
('string/en/celebrity/gorr_ebelt.stf', 11, 'npc_4', 'So you''re just here on vacation?'),
('string/en/celebrity/gorr_ebelt.stf', 12, 'player_7', 'That''s right.'),
('string/en/celebrity/gorr_ebelt.stf', 13, 'npc_8', 'Ah.  How much money do you have?  Nevermind.  I''ll find out soon enough...'),
('string/en/celebrity/gorr_ebelt.stf', 14, 'player_8', 'No.  I just don''t like working.'),
('string/en/celebrity/gorr_ebelt.stf', 15, 'npc_9', 'Maybe I should get into your line of "work" then.'),
('string/en/celebrity/gorr_ebelt.stf', 16, 'player_6', 'That''s none of your business.'),
('string/en/celebrity/gorr_ebelt.stf', 17, 'npc_5', 'I could make your business my business...'),
('string/en/celebrity/gorr_ebelt.stf', 18, 'player_9', 'Don''t bother, the pay''s too low.'),
('string/en/celebrity/gorr_ebelt.stf', 19, 'npc_10', 'You''re a funny guy.'),
('string/en/celebrity/gorr_ebelt.stf', 20, 'player_10', 'I don''t have money and I don''t want a job.'),
('string/en/celebrity/gorr_ebelt.stf', 21, 'npc_11', 'Well, you''re not doing me much good then are you?'),
('string/en/celebrity/han_solo.stf', 1, 'npc_1', 'Something I can do for you?'),
('string/en/celebrity/han_solo.stf', 2, 'player_1', 'Aren''t you Han Solo?'),
('string/en/celebrity/han_solo.stf', 3, 'player_2', 'I hear you''ve got a nice ship.'),
('string/en/celebrity/han_solo.stf', 4, 'npc_2', 'That depends.  You work for Jabba?'),
('string/en/celebrity/han_solo.stf', 5, 'player_3', 'Jabba?  Who''s that?'),
('string/en/celebrity/han_solo.stf', 6, 'npc_6', 'The Hutt?  Lives on Tatooine?  Nevermind, if you don''t know him then, yeah, I''m Han Solo.  Pleased to meet ya.'),
('string/en/celebrity/han_solo.stf', 7, 'player_4', 'The Hutt?  No way.'),
('string/en/celebrity/han_solo.stf', 8, 'npc_7', 'Not a gangster eh?  Good for you.'),
('string/en/celebrity/han_solo.stf', 9, 'npc_3', 'That''s right.  The Millenium Falcon.  Of course you already knew that.'),
('string/en/celebrity/han_solo.stf', 10, 'player_5', 'Millenium Falcon?  Never heard of it.'),
('string/en/celebrity/han_solo.stf', 11, 'npc_4', 'You''re kidding.  It made the Kessel run in...ah forget it.'),
('string/en/celebrity/han_solo.stf', 12, 'player_7', 'No, really.  I''d like to hear it.'),
('string/en/celebrity/han_solo.stf', 13, 'npc_8', 'Let''s just say she''s the fastest hunk of junk in the galaxy and leave it at that.'),
('string/en/celebrity/han_solo.stf', 14, 'player_8', 'The Kessel run?  Isn''t that illegal?'),
('string/en/celebrity/han_solo.stf', 15, 'npc_9', 'I make a fair living.  Don''t go spreading any rumors, you got me?'),
('string/en/celebrity/han_solo.stf', 16, 'player_6', 'Yeah, I hear it''s nice.'),
('string/en/celebrity/han_solo.stf', 17, 'npc_5', 'Nice?  Nice?  I can''t believe this.  That''s what you heard?  My ship is nice?  Who told you that?'),
('string/en/celebrity/han_solo.stf', 18, 'player_9', 'I don''t remember.'),
('string/en/celebrity/han_solo.stf', 19, 'npc_10', 'Well, if you find the guy that did tell him I''ll take on any and all comers, you got it?'),
('string/en/celebrity/han_solo.stf', 20, 'player_10', 'Some guy named Lando something...'),
('string/en/celebrity/han_solo.stf', 21, 'npc_11', 'Oh.  Well that figures.  He never did appreciate this baby.  That''s why he lost her to me.'),
('string/en/celebrity/imperial_bribe.stf', 1, 'leave_me_alone', 'Go away.  I''m not talking to anyone today.'),
('string/en/celebrity/imperial_bribe.stf', 2, 'who_are_you', 'Who are you?'),
('string/en/celebrity/imperial_bribe.stf', 3, 'perhaps_bribe', 'Maybe some money will make you talk to me.'),
('string/en/celebrity/imperial_bribe.stf', 4, 'nunya', 'Who are you? Some sort of Imperial assassin? I''m not going to make your job easier by confirming my identity. Now leave me alone.'),
('string/en/celebrity/imperial_bribe.stf', 5, 'what_you_got', 'Credits, eh? I am a bit light in the pocket today. But the price of knowledge is steep. What are you offering? '),
('string/en/celebrity/imperial_bribe.stf', 6, 'give_50', 'How about 50 credits?'),
('string/en/celebrity/imperial_bribe.stf', 7, 'give_100', 'I could spare 100 credits...'),
('string/en/celebrity/imperial_bribe.stf', 8, 'medium_info', 'A modest fee. You''ll probably want to know about the Imperial facility where I once served the Empire. The base guarded by droidekas? Is that what you''re here for?'),
('string/en/celebrity/imperial_bribe.stf', 9, 'short_base_info', 'Tell me about the Imperial base.'),
('string/en/celebrity/imperial_bribe.stf', 10, 'short_droideka_info', 'Droidekas?'),
('string/en/celebrity/imperial_bribe.stf', 11, 'short_base_story', 'It''s a research facility. That''s all I can reveal. The base is responsible for manufacturing high-grade explosives for the Empire, including grenades. But there is no obvious Imperial presence at the base. No Imperial soldiers, no guards. The entire base is staffed by freelance mercenaries. '),
('string/en/celebrity/imperial_bribe.stf', 12, 'short_droideka_story', 'Yes, the so-called "destroyer droids" used by the Trade Federation during the Clone Wars. The Empire has a stockpile of the droids and has reprogrammed them to guard various installations across the galaxy, including the research station and a mine here on Lok. The droidekas are programmed to attack anyone who shouldn''t be there. They work so well, we also sent some to the mine to guard the slaves there.'),
('string/en/celebrity/imperial_bribe.stf', 13, 'tell_me_more_base', 'No Imperials at the base?  Explain.'),
('string/en/celebrity/imperial_bribe.stf', 14, 'tell_me_more_droideka', 'How can I get past the Droideka?'),
('string/en/celebrity/imperial_bribe.stf', 15, 'need_more_money', 'I''ll need more credits to divulge that information.'),
('string/en/celebrity/imperial_bribe.stf', 16, 'need_more_cash', 'That kind of information requires credits, my friend.'),
('string/en/celebrity/imperial_bribe.stf', 17, 'add_100_bribe', 'What about another 100 credits?'),
('string/en/celebrity/imperial_bribe.stf', 18, 'end_convo', 'I guess that''s all I need.'),
('string/en/celebrity/imperial_bribe.stf', 19, 'thats_all', 'Now go. I can''t be seen talking to the likes of you.'),
('string/en/celebrity/imperial_bribe.stf', 20, 'end_base_info', 'There''s a feud between General Otto and other Imperials. To keep Otto from meddling in the affairs of the Lok research facility, it was built it in relative secrecy and staffed it with mercenaries rather than requisitioned soldiers.  '),
('string/en/celebrity/imperial_bribe.stf', 21, 'anymore_base', 'Can you tell me anything else about the base?'),
('string/en/celebrity/imperial_bribe.stf', 22, 'no_more_base', 'That''s all I''m saying. You don''t need to know any more than that.'),
('string/en/celebrity/imperial_bribe.stf', 23, 'end_droideka_info', 'There''s no option but to fight it.  But that Droideka, it''s pretty tough.  I think they''ve made some special mods to it.  I''m not saying what, I''m just saying I heard...'),
('string/en/celebrity/imperial_bribe.stf', 24, 'anymore_droideka', 'How can I destroy the Droideka?'),
('string/en/celebrity/imperial_bribe.stf', 25, 'no_more_droideka', 'I''m not saying anything else.  Sorry.'),
('string/en/celebrity/imperial_bribe.stf', 26, 'the_good_stuff', 'Alright. I can tell you that I worked for an Imperial Research base, but that we didn''t use requisitioned Imperial soldiers for guards. Instead, we hired the most dangerous mercenaries we could find. The base is also guarded by reprogrammed droidekas that assaults anyone who approaches. The droidekas are so efficient we sent some to the Imperial mines as well as some places on Dantooine...'),
('string/en/celebrity/imperial_bribe.stf', 27, 'tell_me_base', 'Tell me about the base and its guards.'),
('string/en/celebrity/imperial_bribe.stf', 28, 'base_story_long', 'The base is actually one of the Imperial Inquisitors'' pet projects. They chose to build the facility on Lok because the planet has an abundance of noxious chemicals. However, the Inquisitors loathe General Otto, who is technically in power here. They believe he has a brain the size of a meewit, and I''m inclined to agree. In order to bypass Otto and avoid his meddling, the Inquisitors avoided all official requisitions when building the facility. Freelance engineers were hired to build the base, and brutal mercenaries prevent any Rebel spies from interfering with the research. The plan seems to be working: I doubt Otto even realizes that the base exists. '),
('string/en/celebrity/imperial_bribe.stf', 29, 'tell_me_droideka', 'Dantooine?'),
('string/en/celebrity/imperial_bribe.stf', 30, 'droideka_story_long', 'Sure.  There''s a bio-genics research facil- er...nevermind.'),
('string/en/celebrity/imperial_bribe.stf', 31, 'you_got_nothing', 'You don''t have any money!'),
('string/en/celebrity/jan_dodonna.stf', 1, 'npc_1', 'How are things going friend?'),
('string/en/celebrity/jan_dodonna.stf', 2, 'player_1', 'Do I know you?'),
('string/en/celebrity/jan_dodonna.stf', 3, 'player_2', 'Do you assume everyone''s a friend?'),
('string/en/celebrity/jan_dodonna.stf', 4, 'npc_2', 'Probably not.  Just being friendly is all. '),
('string/en/celebrity/jan_dodonna.stf', 5, 'player_3', 'Ah.  And who are you?'),
('string/en/celebrity/jan_dodonna.stf', 6, 'npc_6', 'Just a tired old soldier.'),
('string/en/celebrity/jan_dodonna.stf', 7, 'player_4', 'Well, thanks.  That''s nice of you.'),
('string/en/celebrity/jan_dodonna.stf', 8, 'npc_7', 'That''s why I do it.'),
('string/en/celebrity/jan_dodonna.stf', 9, 'npc_3', 'Until they prove otherwise.  Don''t you?'),
('string/en/celebrity/jan_dodonna.stf', 10, 'player_5', 'I never make assumptions.'),
('string/en/celebrity/jan_dodonna.stf', 11, 'npc_4', 'You''re probably the better man for it.  Me, I just can''t think of people negatively until they''ve done something to lose my trust.'),
('string/en/celebrity/jan_dodonna.stf', 12, 'player_7', 'That''s encouraging.'),
('string/en/celebrity/jan_dodonna.stf', 13, 'npc_8', 'I hope so.  But I also hope for the best all the time.  '),
('string/en/celebrity/jan_dodonna.stf', 14, 'player_8', 'That seems unwise.'),
('string/en/celebrity/jan_dodonna.stf', 15, 'npc_9', 'Well, I''m just a silly old man sometimes.  But don''t look at people too negatively.  Sometimes they can surprise you.'),
('string/en/celebrity/jan_dodonna.stf', 16, 'player_6', 'I assume they''re enemies.'),
('string/en/celebrity/jan_dodonna.stf', 17, 'npc_5', 'That''s a bit negative isn''t it?  Surely you''re just saying that to sound tough...'),
('string/en/celebrity/jan_dodonna.stf', 18, 'player_9', 'Maybe a little.'),
('string/en/celebrity/jan_dodonna.stf', 19, 'npc_10', 'Well, keep it to yourself, that''s my advice.  People don''t like a tough guy unless they need one.  Or unless they really are bad people.'),
('string/en/celebrity/jan_dodonna.stf', 20, 'player_10', 'No, I''m serious.'),
('string/en/celebrity/jan_dodonna.stf', 21, 'npc_11', 'I worry about the universe sometimes...and this is why.'),
('string/en/celebrity/jinkins.stf', 1, 'first_time_hello', 'Hmmm? You must be a new recruit. This crew changes faces faster than a Shi''odo spy. But I''m glad we have some fresh blood: The last "pirate" who wandered in here is still being digested by a kimogila somewhere past Rancid Ridge.'),
('string/en/celebrity/jinkins.stf', 2, 'who_are_you', 'Jinkins, eh?  What do you do?'),
('string/en/celebrity/jinkins.stf', 3, 'tell_me_quest', 'Do you need me to do anything for you?'),
('string/en/celebrity/jinkins.stf', 4, 'quest_info', 'Actually, there is something I''d like you to look into, if you can.  I recently intercepted a distress call from a starship that crashed-landed on Lok. Ships nose-dive into the planet all the time, but this one took off from an Imperial mining installation on Lok and never made it into the atmosphere. I think it slammed down near the hideout of the Sulfur Lake Pirates. I''m very interested in this vessel...'),
('string/en/celebrity/jinkins.stf', 5, 'distress_call', 'You intercepted a distress call?'),
('string/en/celebrity/jinkins.stf', 6, 'crashed_ship', 'Yes. As part of my duties, I monitor comlink and transceiver activity around the system. We don''t want a Star Destroyer sneaking up on us, do we? Anyway, this particular starship interests me because it was carrying Imperial cargo. A droid, in fact, that was once owned by General Otto at an Imperial base here on Lok.'),
('string/en/celebrity/jinkins.stf', 7, 'droid_memory', 'What''s so special about this droid?'),
('string/en/celebrity/jinkins.stf', 8, 'imperial_info', 'Probably nothing. But, as an Imperial droid, it might be carrying some very interesting data.  Shipping schedules, guard rosters, prisoner transfer information, schematics for some terrifying super weapon... Anything the droid knows could be sold on the black market or traded back to Otto for a favor down the road. It might also tell us something about that Imperial mining facility, which we haven''t been able to infiltrate. You''d be rewarded well if you could secure that droid''s memory module.'),
('string/en/celebrity/jinkins.stf', 9, 'ill_get_memory', 'I''ll recover the module. Where can I find this droid?'),
('string/en/celebrity/jinkins.stf', 10, 'heres_droid_memory', 'Excellent.  I''ll provide you with a waypoint to the Sulfur Lake.  Our scouts learned that the Sulfur Lake Pirates have already taken the cargo - including the droid - from the crashed starship, so don''t waste your time looking through the wreckage. Just head to the pirates'' lair, locate the droid, and grab the memory module. Oh, and watch out for the pirates'' "bridge troll." I''m not sure what that is, but it sounds dangerous...'),
('string/en/celebrity/jinkins.stf', 11, 'sulfur_lake_pirates', 'Who are the Sulfur Lake Pirates?'),
('string/en/celebrity/jinkins.stf', 12, 'pirate_info', 'Probably the most bloodthirsty, least-intelligent pirates on Lok. Like all the other pirate bands, they are constantly trying to dethrone Nym as Lok''s reigning pirate king. They hate Nym for taking control of all the nearby hyperspace routes and claim that he''s working with the Imperials. The gravel maggots have been looking for an excuse to go to war with us for years... There''s a hermit living near Nym''s stronghold who once worked for the Sulfur Pirates. He might be able to tell you more.'),
('string/en/celebrity/jinkins.stf', 13, 'whos_the_guy', 'Who is this hermit?'),
('string/en/celebrity/jinkins.stf', 14, 'deals_with_pirates', 'I don''t know much about him. We think he was some sort of droid designer for the Old Republic, but fled to Lok when the Empire took power. A few years ago, Nym used him to fence good on Coruscant. But before that, he was performing droid upgrades for the Sulfur Lake Pirates. He can probably tell you about their base.'),
('string/en/celebrity/jinkins.stf', 15, 'ill_see_the_guy', 'Okay, I''ll go talk to him.'),
('string/en/celebrity/jinkins.stf', 16, 'heres_the_guy', 'Good. I''ll mark his last known location in your datapad.  Be sure to ask him about the pirates, see what he knows.'),
('string/en/celebrity/jinkins.stf', 17, 'anything_else', 'Is there anything else you can tell me?'),
('string/en/celebrity/jinkins.stf', 18, 'you_know_all', 'Not really. You know everything I know.'),
('string/en/celebrity/jinkins.stf', 19, 'i_am_jinkins', 'I''m Jinkins, Nym''s chief engineer. Nym asks for weapons, and I build them. I joined up with the Lok Revenants a few months before the Battle of Naboo, which makes me one of this crew''s oldest members, along with Kole of course. '),
('string/en/celebrity/jinkins.stf', 20, 'who_is_nym', 'Tell me about Nym.'),
('string/en/celebrity/jinkins.stf', 21, 'who_is_kole', 'Who is Kole?'),
('string/en/celebrity/jinkins.stf', 22, 'nym_is_boss', 'You must be joking... Nym is the most feared pirate in the Maramere system. He routed the Trade Federation from Lok and its neighboring planets right around the start of the Clone Wars, and he''s maintained complete control over the spacelanes in this region ever since.  There''s nobody with more power on Lok. And except for Jabba the Hutt, he''s probably the most powerful alien in the Outer Rim. The Imperials on this planet couldn''t even lift Nym''s shadow... And he has no love for the Empire, if you catch my meaning...'),
('string/en/celebrity/jinkins.stf', 23, 'kole_is_friend', 'Kole is Nym''s first mate. He''s been with this crew longer than I have. In his younger days, he was a brilliant disguise artist and even worked for a few years as an assassin. Now, he mostly watches Nym''s back.'),
('string/en/celebrity/jinkins.stf', 24, 'hello_again', 'You''re still alive? Good work. Do you want to talk about something else?'),
('string/en/celebrity/jinkins.stf', 25, 'hello_kole', 'So I hear you talked to Kole.  Excellent. Stay on that Chadra-Fan''s good side, and you''ll live longer. Now what can I do for you?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/celebrity/jinkins.stf', 26, 'hello_nym', 'I heard you talked to Nym. I''m not sure he trusts you... But, then again, he doesn''t trust anyone except Kole and me. So, what can I do for you?'),
('string/en/celebrity/jinkins.stf', 27, 'hello_all', 'Well, you''ve met everyone worth knowing in this crew. So, what do you need?'),
('string/en/celebrity/jinkins.stf', 28, 'tell_me_again', 'Can you tell me again what you need?'),
('string/en/celebrity/jinkins.stf', 29, 'quest_info_again', 'I need you - or someone more skilled - to retrieve a memory module from a droid that the Sulfur Lake Pirates have evidently captured. You may want to discuss the pirates'' lair with one of their former members.'),
('string/en/celebrity/jinkins.stf', 30, 'you_got_memory', 'Did you retrieve it?  The memory module?'),
('string/en/celebrity/jinkins.stf', 31, 'no', 'Not yet.'),
('string/en/celebrity/jinkins.stf', 32, 'get_back_to_work', 'Really?  One of our operatives, a slicer who has infiltrated the Sulfur Pirate lair, is certain he saw you there. He also believes that you have already retrieved the module. But perhaps he was mistaken. Head to that cave and find the memory module for me.'),
('string/en/celebrity/jinkins.stf', 33, 'yes', 'Yeah, I have it.'),
('string/en/celebrity/jinkins.stf', 34, 'hand_it_over', 'Excellent.  Now, if you''ll just hand it to me...'),
('string/en/celebrity/jinkins.stf', 35, 'whats_this', 'What are you trying to give me?  I don''t need this.'),
('string/en/celebrity/jinkins.stf', 36, 'gave_brain', 'Yes!  That''s it.  This is the right model number... And this droid does indeed have a history with the Empire. Now, it should be simple matter to slice this droid''s brain and find out what it knows. I''ll be sending any intriguing information to Kole''s datapad, so you might want to talk to him next time you''re in our stronghold. '),
('string/en/celebrity/jinkins.stf', 37, 'good_work', 'Securing that memory module proves that you have the makings of a true pirate. I''m sure you''ll go far with the Lok Revenants. Now, is there something else I can do for you?'),
('string/en/celebrity/jinkins.stf', 38, 'what_now', 'Can you give me another assignment?'),
('string/en/celebrity/jinkins.stf', 39, 'see_ya', 'No.'),
('string/en/celebrity/jinkins.stf', 40, 'good_bye', 'Alright, but I suggest you talk to Nym or Kole if you''re still interested in our crew. '),
('string/en/celebrity/jinkins.stf', 41, 'talk_to_nym', 'You''ve already done my dirty work. But talk to Nym... I think he might need something from you.'),
('string/en/celebrity/jinkins.stf', 42, 'talk_to_kole', 'Kole is planning a new mission for you, based on the information I recovered from that memory module. You should talk to him to receive your next assignment.'),
('string/en/celebrity/kais.stf', 1, 'npc_1', 'You are not one of us...'),
('string/en/celebrity/kais.stf', 2, 'player_1', 'Sorry, I''ll go.'),
('string/en/celebrity/kais.stf', 3, 'player_2', 'Who are you?'),
('string/en/celebrity/kais.stf', 4, 'npc_2', 'Good!'),
('string/en/celebrity/kais.stf', 5, 'npc_3', 'We are the Sisters of the Night!'),
('string/en/celebrity/kardeer.stf', 1, 'npc_1', 'Madam''s not here, but what can I help you with?'),
('string/en/celebrity/kardeer.stf', 2, 'player_1', 'Who are you?'),
('string/en/celebrity/kardeer.stf', 3, 'player_2', 'Who''s the Madam?'),
('string/en/celebrity/kardeer.stf', 4, 'npc_2', 'I''m Kardeer, her Ladyship''s gardener.'),
('string/en/celebrity/kardeer.stf', 5, 'player_3', 'You''re a gardener?'),
('string/en/celebrity/kardeer.stf', 6, 'npc_6', 'My gloves didn''t give it away?'),
('string/en/celebrity/kardeer.stf', 7, 'player_4', 'Must not be much work on Tatooine.'),
('string/en/celebrity/kardeer.stf', 8, 'npc_7', 'Gardening is noble pursuit no matter where it is performed.'),
('string/en/celebrity/kardeer.stf', 9, 'npc_3', 'Her majesty, Lady Valarian.'),
('string/en/celebrity/kardeer.stf', 10, 'player_5', 'Never heard of her.'),
('string/en/celebrity/kardeer.stf', 11, 'player_6', 'The Whiphid?'),
('string/en/celebrity/kardeer.stf', 12, 'npc_4', 'You''ve never heard of her eminence the Lady Valarian?'),
('string/en/celebrity/kardeer.stf', 13, 'player_7', 'I think that''s what I just said.'),
('string/en/celebrity/kardeer.stf', 14, 'player_8', 'What does she do?'),
('string/en/celebrity/kardeer.stf', 15, 'npc_8', 'Perhaps you should ask around about her.  She is quite powerful here on Tatooine.'),
('string/en/celebrity/kardeer.stf', 16, 'npc_9', 'She does whatever needs to be done.  Her grace is an ever flowing fount of knowledge, wisdom, and generosity.'),
('string/en/celebrity/kardeer.stf', 17, 'player_9', 'Why should I care about her?'),
('string/en/celebrity/kardeer.stf', 18, 'npc_5', 'She is so much more than that.  She is to be praised for her good works at every possible opportunity.'),
('string/en/celebrity/kardeer.stf', 19, 'player_10', 'Are you ok?'),
('string/en/celebrity/kardeer.stf', 20, 'npc_10', 'Because.  There is nothing more to be said.  You should feel priveleged to exist in the same galaxy as such a wonderous creature.'),
('string/en/celebrity/kardeer.stf', 21, 'npc_11', 'I''m feeling a little light headed, actually.  Perhaps it was all the pesticides...'),
('string/en/celebrity/king_terak.stf', 1, 'npc_1', 'I am King Terak, Lord of the Marauders!'),
('string/en/celebrity/king_terak.stf', 2, 'player_1', 'What are marauders?'),
('string/en/celebrity/king_terak.stf', 3, 'player_2', 'What do you want?'),
('string/en/celebrity/king_terak.stf', 4, 'npc_2', 'We are the scavengers of Endor, taking what we want and ruling over the planet with an iron fist!'),
('string/en/celebrity/king_terak.stf', 5, 'npc_3', 'I want off this accursed planet!'),
('string/en/celebrity/kole.stf', 1, 'first_time_hello', 'Eh, what do we have here? Some soft outlander that has crawled into our stronghold? What do you want, fringer?  '),
('string/en/celebrity/kole.stf', 2, 'who_are_you', 'Who are you?'),
('string/en/celebrity/kole.stf', 3, 'tell_me_quest', 'I''m looking to help out Nym''s crew.'),
('string/en/celebrity/kole.stf', 4, 'im_kole', 'According to the Imperial criminal databank, my name''s Kole, and that''s the only name you need to know. I''m Nym''s first mate, which means that I slip a vibro-blade between the ribs of anyone who he don''t like. So watch yourself. Me and Jinkins, we''ve been around long enough to bury hundreds of outlanders just like you.  '),
('string/en/celebrity/kole.stf', 5, 'who_is_nym', 'Tell me about Nym.'),
('string/en/celebrity/kole.stf', 6, 'who_is_jinkins', 'Who is Jinkins?'),
('string/en/celebrity/kole.stf', 7, 'jinkins_is_friend', 'Jinkins is the bald Bith standing over there. He''s Nym''s chief engineer, builds us our weapons and droids. He don''t have that killer instinct, but he does have something more dangerous: information. In fact, he''s probably got some work for you, if you''re lucky.'),
('string/en/celebrity/kole.stf', 8, 'quest_info', 'Good. I need you to check something out for us. Jinkins sliced some data from an Imperial droid and found out that it was on a ship trying to escape an Imperial mining installation here on Lok. Imperial labor camps ain''t known for their safe working conditions... The droid says the miners hit some sort of gas pocket. The entire work crew had their brains boiled. They survived, but they''re crazy. And the droid thinks that some of the Imperial officers were infected too. Any gas that drives Imperials out of their minds is a good thing to have around, so we want some samples of it. '),
('string/en/celebrity/kole.stf', 9, 'nym_is_chief', 'Nym''s the captain of the Lok Revenants, our crew. Before that thing on Naboo, we was pirates, mainly robbing freighters that passed by Lok. But then Nym went to war with the Trade Federation. It took ten years, but we finally chewed through the droids and spit ''em out of the system. Nym''s been like the king of Lok ever since.'),
('string/en/celebrity/kole.stf', 10, 'dangerous_gas', 'How dangerous is this gas?'),
('string/en/celebrity/kole.stf', 11, 'probe_droid', 'What other threats are out there?'),
('string/en/celebrity/kole.stf', 12, 'hello_again', 'I wasn''t expecting you to come back. Figured you hopped a shuttle back to Naboo or whatever planet you come from. What do you want?'),
('string/en/celebrity/kole.stf', 13, 'miners', 'It looks like the mine has a cheap air filtration system. It barely meets Imperial code and didn''t stop the gas from infecting the miners. But Jinkins thinks the filters trapped some of the gas. Just find the filtration system and look for some kinda sealed container. Oh, and now that the filters have had some time do their work, the air down there should be clean. If you''re lucky, anyway. '),
('string/en/celebrity/kole.stf', 14, 'quest_tease', 'I ain''t got nothing for you yet. Go talk to Jinkins. He''s always handing out blue milk runs for outlanders like you.'),
('string/en/celebrity/kole.stf', 15, 'mining_facility', 'Won''t the facility be filled with poison?'),
('string/en/celebrity/kole.stf', 16, 'gas_info', 'You scared? I said don''t worry about the gas. The filters should have scrubbed the air clean by now. The real danger is gonna be the miners. The gas has poisoned their brains. They''ve taken over the mine and will attack anyone who comes near the place. They''re like wild dinkos...'),
('string/en/celebrity/kole.stf', 17, 'ill_get_gas', 'Well, I can take a shot at getting this gas...'),
('string/en/celebrity/kole.stf', 18, 'here_is_gas', 'Good. I''m gonna mark the location of the mine in your datapad. This will be a tough mission, though; if you have any friends, you''d might want to ask for their help. Or least tell them how you want your remains handled. '),
('string/en/celebrity/kole.stf', 19, 'tell_me_again', 'Explain to me again what I need to do...'),
('string/en/celebrity/kole.stf', 20, 'quest_info_again', 'I want you to grab an "insanity gas" from a mine full of deranged miners. Find the filtration system and get a canister of that gas. '),
('string/en/celebrity/kole.stf', 21, 'droid_info', 'Since the imperials aren''t sure what''s going on with the mine, they''ve sent some of their droids to monitor the situation.  You may have to deal with them as well.  '),
('string/en/celebrity/kole.stf', 22, 'imperial_involvement', 'What kind of droids?'),
('string/en/celebrity/kole.stf', 23, 'imperial_stuff', 'We don''t know, exactly. But we do have an ex-Imperial in our pocket who might have some information for you. Sergeant Moore owes Nym several thousand credits. He''ll probably tell you whatever you need to know, for a price. Since he left the Imperial army, he spends most of his time in the cantina.'),
('string/en/celebrity/kole.stf', 24, 'resigned_officer', 'Why did he leave the army?'),
('string/en/celebrity/kole.stf', 25, 'officer_info', 'The Empire found out that he was borrowing credits from Nym. He was going to be executed, but he has friends in the Tagge family. They put in a good word, and Moore was kicked out instead of killed. But, he still has good information about the Empire''s droids.'),
('string/en/celebrity/kole.stf', 26, 'ill_see_imperial', 'Maybe I should go talk to him.'),
('string/en/celebrity/kole.stf', 27, 'here_is_imperial', 'I''ll give you a waypoint to the cantina where he hangs out. He might be able to tell you about the droids or the mining facility.'),
('string/en/celebrity/kole.stf', 28, 'anything_else', 'Is there anything else you can tell me?'),
('string/en/celebrity/kole.stf', 29, 'not_really', 'No. You''ve heard everything you need to know.'),
('string/en/celebrity/kole.stf', 30, 'bring_gas', 'Did you bring me the gas?'),
('string/en/celebrity/kole.stf', 31, 'yes', 'Yeah, I have it here...'),
('string/en/celebrity/kole.stf', 32, 'no', 'No, I didn''t get it yet.'),
('string/en/celebrity/kole.stf', 33, 'hand_it_over', 'Good. Now, just give me the canister...'),
('string/en/celebrity/kole.stf', 34, 'get_back_to_work', 'Then get back out there and find it.. Look in the mine''s filtration system.'),
('string/en/celebrity/kole.stf', 35, 'gave_gas', 'Good work. This gas should be extremely useful to Nym.'),
('string/en/celebrity/kole.stf', 36, 'whats_this', 'This isn''t what I asked for. I need the gas from the mining facility.'),
('string/en/celebrity/kole.stf', 37, 'good_work', 'I wasn''t sure about you, but recoverin'' that gas from the mining facility was a pretty dangerous mission. I''m actually surprised you survived. Good work.'),
('string/en/celebrity/kole.stf', 38, 'what_now', 'What should I do now?'),
('string/en/celebrity/kole.stf', 39, 'see_ya', 'I''ll talk to you later.'),
('string/en/celebrity/kole.stf', 40, 'good_bye', 'Good luck, fringer.'),
('string/en/celebrity/kole.stf', 41, 'youre_done', 'I don''t have any more assignments, but Nym wants to talk to you.'),
('string/en/celebrity/kole.stf', 42, 'talk_to_nym', 'Go see Nym.  He needs an outlander for a special mission.'),
('string/en/celebrity/kole.stf', 43, 'talk_to_jinkins', 'Go talk to Jinkins.'),
('string/en/celebrity/lady_valarian.stf', 1, 'npc_1', 'Are you a customer or are you looking for work?'),
('string/en/celebrity/lady_valarian.stf', 2, 'player_1', 'What do you sell?'),
('string/en/celebrity/lady_valarian.stf', 3, 'player_2', 'What kind of work?'),
('string/en/celebrity/lady_valarian.stf', 4, 'npc_2', 'There''s nothing that''s not for sale here on Tatooine.  What do you want?'),
('string/en/celebrity/lady_valarian.stf', 5, 'player_3', 'Is this illegal?'),
('string/en/celebrity/lady_valarian.stf', 6, 'npc_6', 'If you''re that worried about it why don''t you go shopping somewhere else.'),
('string/en/celebrity/lady_valarian.stf', 7, 'player_4', 'There''s nothing I really need right now.'),
('string/en/celebrity/lady_valarian.stf', 8, 'npc_7', 'Well, come back if you need something.'),
('string/en/celebrity/lady_valarian.stf', 9, 'npc_3', 'I have all kinds of work available.  What are you good at?'),
('string/en/celebrity/lady_valarian.stf', 10, 'player_5', 'I''m good at lots of things.'),
('string/en/celebrity/lady_valarian.stf', 11, 'player_6', 'I''m good at shooting things.'),
('string/en/celebrity/lady_valarian.stf', 12, 'npc_4', 'Well, I could probably find some use for you.  You''re not an imperial are you?'),
('string/en/celebrity/lady_valarian.stf', 13, 'player_7', 'I do have some Imperial standing.'),
('string/en/celebrity/lady_valarian.stf', 14, 'player_8', 'No, I''m pretty much free to work for whoever.'),
('string/en/celebrity/lady_valarian.stf', 15, 'npc_8', 'Sorry, I can''t use you then.  Union regulations.  No Imperials.'),
('string/en/celebrity/lady_valarian.stf', 16, 'npc_9', 'Well, then talk to one of my friends here in the office and I''m sure they can find you some work.'),
('string/en/celebrity/lady_valarian.stf', 17, 'npc_5', 'Well, well, well.  A shooter, eh?  I could use a good shooter.'),
('string/en/celebrity/lady_valarian.stf', 18, 'player_9', 'Tell me who you want shot and I''ll shoot them.'),
('string/en/celebrity/lady_valarian.stf', 19, 'npc_10', 'Don''t jump the gun.  See if one of my friends here has a job they''d like you to do.'),
('string/en/celebrity/lady_valarian.stf', 20, 'player_10', 'And I could use a job.'),
('string/en/celebrity/lady_valarian.stf', 21, 'npc_11', 'Well, check with my employees here in the office, one of them will surely have a job for you.'),
('string/en/celebrity/lerat_zom.stf', 1, 'npc_1', 'Plenty to do on Corellia.  Easier than working on Naboo.  Safer than Tatooine.  Did you come looking for work?'),
('string/en/celebrity/lerat_zom.stf', 2, 'player_1', 'What kind of work?'),
('string/en/celebrity/lerat_zom.stf', 3, 'player_2', 'No.  I''m not interested.'),
('string/en/celebrity/lerat_zom.stf', 4, 'npc_2', 'If you don''t know then you probably don''t want it.  Not the kind of work for strangers or those who don''t know.  Ya know?'),
('string/en/celebrity/lerat_zom.stf', 5, 'player_3', 'Um...I don''t know.'),
('string/en/celebrity/lerat_zom.stf', 6, 'npc_6', 'Exactly.  And if you don''t know then you can''t know can you?  So you should move on, before you know too much.'),
('string/en/celebrity/lerat_zom.stf', 7, 'player_4', 'Strangers?'),
('string/en/celebrity/lerat_zom.stf', 8, 'npc_7', 'Anyone I don''t know is a stranger.  You know?'),
('string/en/celebrity/lerat_zom.stf', 9, 'npc_3', 'Too bad.  I got a lot of work and no good people.'),
('string/en/celebrity/lerat_zom.stf', 10, 'player_5', 'You think I''m good people?'),
('string/en/celebrity/lerat_zom.stf', 11, 'npc_4', 'You could be.  You seem fit enough.  Are you?  Are you any good at all?'),
('string/en/celebrity/lerat_zom.stf', 12, 'player_7', 'What''s the job?'),
('string/en/celebrity/lerat_zom.stf', 13, 'npc_8', 'You don''t seem to know what we''re talking about so I''m going to assume you already have another job and just go on about my business.'),
('string/en/celebrity/lerat_zom.stf', 14, 'player_8', 'I''m good.'),
('string/en/celebrity/lerat_zom.stf', 15, 'npc_9', 'Then find one of my people and see what kind of work we have.  You''ll know them when you see them.  Or you won''t.  You know?'),
('string/en/celebrity/lerat_zom.stf', 16, 'player_6', 'What''s the job?'),
('string/en/celebrity/lerat_zom.stf', 17, 'npc_5', 'There''s not just one.  There''s tons of jobs.  But I need good people.  Not just anybody off the street that strikes up a conversation.'),
('string/en/celebrity/lerat_zom.stf', 18, 'player_9', 'I can do the work.'),
('string/en/celebrity/lerat_zom.stf', 19, 'npc_10', 'I''m sure you can.  See what my people have and we''ll see how you do.  If you''re really any good you won''t need my help finding them.'),
('string/en/celebrity/lerat_zom.stf', 20, 'player_10', 'Ok, you''re too weird.'),
('string/en/celebrity/lerat_zom.stf', 21, 'npc_11', 'Nothing wrong with weird.  What worries me is you.  Right?'),
('string/en/celebrity/librarian.stf', 1, 'want_trivia', 'Hello, welcome to the library.  If you''d like, we could play a game.  I''ll ask you trivia questions and you can answer them.  All right?'),
('string/en/celebrity/librarian.stf', 2, 'yes', 'Yes. '),
('string/en/celebrity/librarian.stf', 3, 'no', 'No thanks.'),
('string/en/celebrity/librarian.stf', 4, 'good_bye', 'Well, I hope you enjoyed your visit.  I hope to see you again very soon.'),
('string/en/celebrity/librarian.stf', 5, 'question_1', 'Who originally established the Free Trader Association of Naboo?'),
('string/en/celebrity/librarian.stf', 6, 'right_1', 'Shep Contopault.'),
('string/en/celebrity/librarian.stf', 7, 'wrong_one_1', 'Queen Amidala.'),
('string/en/celebrity/librarian.stf', 8, 'wrong_two_1', 'Nute Gunray.'),
('string/en/celebrity/librarian.stf', 9, 'wrong_three_1', 'Darth Maul.'),
('string/en/celebrity/librarian.stf', 10, 'question_2', 'Corellian Clams are known for this property...'),
('string/en/celebrity/librarian.stf', 11, 'right_2', 'Being hard to open.'),
('string/en/celebrity/librarian.stf', 12, 'wrong_one_2', 'Healing properties.'),
('string/en/celebrity/librarian.stf', 13, 'wrong_two_2', 'Delicious flavor.'),
('string/en/celebrity/librarian.stf', 14, 'wrong_three_2', 'Their blood is alcohol.'),
('string/en/celebrity/librarian.stf', 15, 'question_3', 'What single center of mass do both Talus and Tralus orbit around?'),
('string/en/celebrity/librarian.stf', 16, 'right_3', 'Centerpoint Station.'),
('string/en/celebrity/librarian.stf', 17, 'wrong_one_3', 'Corellia.'),
('string/en/celebrity/librarian.stf', 18, 'wrong_two_3', 'Tatooine.'),
('string/en/celebrity/librarian.stf', 19, 'wrong_three_3', 'A black hole.'),
('string/en/celebrity/librarian.stf', 20, 'question_4', 'Approximately how many light years is Tatooine from the Galactic Core?'),
('string/en/celebrity/librarian.stf', 21, 'right_4', '43,000.'),
('string/en/celebrity/librarian.stf', 22, 'wrong_one_4', '34,000.'),
('string/en/celebrity/librarian.stf', 23, 'wrong_two_4', '153,000.'),
('string/en/celebrity/librarian.stf', 24, 'wrong_three_4', '3.'),
('string/en/celebrity/librarian.stf', 25, 'question_5', 'Rori is a moon which orbits which planet?'),
('string/en/celebrity/librarian.stf', 26, 'wrong_one_5', 'Corellia.'),
('string/en/celebrity/librarian.stf', 27, 'right_5', 'Naboo.'),
('string/en/celebrity/librarian.stf', 28, 'wrong_two_5', 'Talus.'),
('string/en/celebrity/librarian.stf', 29, 'wrong_three_5', 'Yavin.'),
('string/en/celebrity/librarian.stf', 30, 'question_6', 'How long is an average day on Dantooine?'),
('string/en/celebrity/librarian.stf', 31, 'right_6', '25 hours.'),
('string/en/celebrity/librarian.stf', 32, 'wrong_one_6', '24 hours.'),
('string/en/celebrity/librarian.stf', 33, 'wrong_two_6', '30 hours.'),
('string/en/celebrity/librarian.stf', 34, 'wrong_three_6', '125 hours.'),
('string/en/celebrity/librarian.stf', 35, 'question_7', 'In what system is the planet Dathomir located?'),
('string/en/celebrity/librarian.stf', 36, 'right_7', 'Quelii.'),
('string/en/celebrity/librarian.stf', 37, 'wrong_one_7', 'Abraxis.'),
('string/en/celebrity/librarian.stf', 38, 'wrong_two_7', 'Prindaar.'),
('string/en/celebrity/librarian.stf', 39, 'wrong_three_7', 'Xizor.'),
('string/en/celebrity/librarian.stf', 40, 'question_8', 'Where did the Trade Federation first test the automata of its vast droid army?'),
('string/en/celebrity/librarian.stf', 41, 'right_8', 'Lok.'),
('string/en/celebrity/librarian.stf', 42, 'wrong_one_8', 'Rori.'),
('string/en/celebrity/librarian.stf', 43, 'wrong_two_8', 'Coruscant.'),
('string/en/celebrity/librarian.stf', 44, 'wrong_three_8', 'Kashyyk.'),
('string/en/celebrity/librarian.stf', 45, 'question_9', 'How many moons orbit the planet Endor?'),
('string/en/celebrity/librarian.stf', 46, 'right_9', '9.'),
('string/en/celebrity/librarian.stf', 47, 'wrong_one_9', '7.'),
('string/en/celebrity/librarian.stf', 48, 'wrong_two_9', '8.'),
('string/en/celebrity/librarian.stf', 49, 'wrong_three_9', 'None.'),
('string/en/celebrity/librarian.stf', 50, 'question_10', 'How many inhabitable moons does Yavin have?'),
('string/en/celebrity/librarian.stf', 51, 'right_10', 'Three.'),
('string/en/celebrity/librarian.stf', 52, 'wrong_one_10', 'Forty.'),
('string/en/celebrity/librarian.stf', 53, 'wrong_two_10', 'Eleven.'),
('string/en/celebrity/librarian.stf', 54, 'wrong_three_10', 'Four.'),
('string/en/celebrity/librarian.stf', 55, 'question_11', 'Who formed the Brotherhood of the Sith?'),
('string/en/celebrity/librarian.stf', 56, 'right_11', 'Exar Kun.'),
('string/en/celebrity/librarian.stf', 57, 'wrong_one_11', 'Darth Bane.'),
('string/en/celebrity/librarian.stf', 58, 'wrong_two_11', 'Darth Vader.'),
('string/en/celebrity/librarian.stf', 59, 'wrong_three_11', 'Jorus C''baoth'),
('string/en/celebrity/librarian.stf', 60, 'question_12', 'What company developed the original Victory Class Star Destroyers for the Old Republic?'),
('string/en/celebrity/librarian.stf', 61, 'right_12', 'Rendili StarDrive.'),
('string/en/celebrity/librarian.stf', 62, 'wrong_one_12', 'Kuat Drive Yards.'),
('string/en/celebrity/librarian.stf', 63, 'wrong_two_12', 'The Min-Dal Company.'),
('string/en/celebrity/librarian.stf', 64, 'wrong_three_12', 'Grand Moff Tarkin.'),
('string/en/celebrity/librarian.stf', 65, 'question_13', 'The four suits of a standard Sabacc deck are:'),
('string/en/celebrity/librarian.stf', 66, 'right_13', 'Coins, Staves, Flasks, and Sabers.'),
('string/en/celebrity/librarian.stf', 67, 'wrong_one_13', 'Coins, Cups, Staves, and Sabers.'),
('string/en/celebrity/librarian.stf', 68, 'wrong_two_13', 'Swords, Staves, Cups, and Wands.'),
('string/en/celebrity/librarian.stf', 69, 'wrong_three_13', 'Swords, Sabers, Scimitars, and Knives.'),
('string/en/celebrity/librarian.stf', 70, 'question_14', 'Which of the following is not considered a "standard" Sabacc card:'),
('string/en/celebrity/librarian.stf', 71, 'right_14', 'The Sarlacc.'),
('string/en/celebrity/librarian.stf', 72, 'wrong_one_14', 'The idiot.'),
('string/en/celebrity/librarian.stf', 73, 'wrong_two_14', 'The Queen of Air and Darkness.'),
('string/en/celebrity/librarian.stf', 74, 'wrong_three_14', 'Demise.'),
('string/en/celebrity/librarian.stf', 75, 'question_15', 'What song, written and performed by the band Starburst, was rated Scarlet (artistically worthless and offensive) by the Imperial Board of Culture?'),
('string/en/celebrity/librarian.stf', 76, 'right_15', 'Only In Your Dreams.'),
('string/en/celebrity/librarian.stf', 77, 'wrong_one_15', 'The Emperor''s Hobby.'),
('string/en/celebrity/librarian.stf', 78, 'wrong_two_15', 'Love in the Atmosphere.'),
('string/en/celebrity/librarian.stf', 79, 'wrong_three_15', 'Time for Action.'),
('string/en/celebrity/librarian.stf', 80, 'question_16', 'What song, performed by the ensemble Plexo-33, was considered the most popular song in the galaxy, prior to the Clone Wars?'),
('string/en/celebrity/librarian.stf', 81, 'right_16', '11011101 #2'),
('string/en/celebrity/librarian.stf', 82, 'wrong_one_16', 'Clones Need Love Too.'),
('string/en/celebrity/librarian.stf', 83, 'wrong_two_16', 'Only In Your Dreams.'),
('string/en/celebrity/librarian.stf', 84, 'wrong_three_16', 'Tatooine in G-Minor.'),
('string/en/celebrity/librarian.stf', 85, 'question_17', 'What sport was named the "official" sport of the New Order, shortly before the Battle of Yavin?'),
('string/en/celebrity/librarian.stf', 86, 'right_17', 'Wegsphere.'),
('string/en/celebrity/librarian.stf', 87, 'wrong_one_17', 'Kel Tag.'),
('string/en/celebrity/librarian.stf', 88, 'wrong_two_17', 'Ringer.'),
('string/en/celebrity/librarian.stf', 89, 'wrong_three_17', 'Sabacc.'),
('string/en/celebrity/librarian.stf', 90, 'question_18', 'What is the more common name of the Koensayr BTL Longprobe Starfighter?'),
('string/en/celebrity/librarian.stf', 91, 'right_18', 'Y-wing.'),
('string/en/celebrity/librarian.stf', 92, 'wrong_one_18', 'X-wing.'),
('string/en/celebrity/librarian.stf', 93, 'wrong_two_18', 'B-wing.'),
('string/en/celebrity/librarian.stf', 94, 'wrong_three_18', 'Tie Fighter.'),
('string/en/celebrity/librarian.stf', 95, 'question_19', 'The T-I-E in TIE Fighters is most commonly believed to refer to what?'),
('string/en/celebrity/librarian.stf', 96, 'right_19', 'Twin Ion Engines.'),
('string/en/celebrity/librarian.stf', 97, 'wrong_one_19', 'Turbo Injected Engines.'),
('string/en/celebrity/librarian.stf', 98, 'wrong_two_19', 'Tertiary Invasion Equipment.'),
('string/en/celebrity/librarian.stf', 99, 'wrong_three_19', 'Timed Insular Ejection.'),
('string/en/celebrity/librarian.stf', 100, 'question_20', 'The playwright Thalos Lorin, is best known for this drama:'),
('string/en/celebrity/librarian.stf', 101, 'right_20', 'Serpent Rain.'),
('string/en/celebrity/librarian.stf', 102, 'wrong_one_20', 'The Trickery of Vosdia Nooma.'),
('string/en/celebrity/librarian.stf', 103, 'wrong_two_20', 'Rodian Fever.'),
('string/en/celebrity/librarian.stf', 104, 'wrong_three_20', 'Unusually Bothan.'),
('string/en/celebrity/librarian.stf', 105, 'winner_is_you', 'Excellent.  You got that correct.  Would you like another question?'),
('string/en/celebrity/librarian.stf', 106, 'too_bad_so_sad', 'Oh, that''s not right.  Would you like to try again?'),
('string/en/celebrity/librarian.stf', 107, 'worst_ever_guesser', 'You''re just guessing aren''t you?  And not even very well at that.  Ah, well.   Try again?'),
('string/en/celebrity/librarian.stf', 108, 'you_are_right', 'That''s the correct answer.  Very good job.  Would you like another question?'),
('string/en/celebrity/librarian.stf', 109, 'good_answer', 'Very good.  You got it.  Would you like another question?'),
('string/en/celebrity/librarian.stf', 110, 'correct', 'Correct!  You''re very smart.  Another question?'),
('string/en/celebrity/librarian.stf', 111, 'correctamundo', 'You definitely know your stuff.  Try again?'),
('string/en/celebrity/librarian.stf', 112, 'you_got_it', 'You got it!  That''s the right answer.  Shall we do another?'),
('string/en/celebrity/librarian.stf', 113, 'thats_not_it', 'Nope, that''s not it.  Would you like to try again?'),
('string/en/celebrity/librarian.stf', 114, 'no_sir', 'No.  Wrong.  That''s the wrong answer.  Shall we do this again?'),
('string/en/celebrity/librarian.stf', 115, 'you_are_wrong', 'You missed that one.  I thought you''d know it.  Again?'),
('string/en/celebrity/librarian.stf', 116, 'incorrect', 'That''s incorrect.  You''ll have to try harder.  Shall we try again?'),
('string/en/celebrity/librarian.stf', 117, 'buzz_wrong_answer', 'No!  That''s not the right answer.  You''ve missed the question''s point it seems, or perhaps you just didn''t know any better.  Want to try once more?'),
('string/en/celebrity/librarian.stf', 118, 'couldnt_be_wronger', 'No, you''ve missed it.  That''s not the right answer.  Want another chance?'),
('string/en/celebrity/librarian.stf', 119, 'most_wrong', 'No, that''s wrong.  Wrong, wrong wrong.  *sigh*  Do you really want to keep guessing?'),
('string/en/celebrity/librarian.stf', 120, 'bad_answer', 'Sorry, that''s the wrong answer.  I can''t believe you didn''t know that!  Well, shall we do it again?'),
('string/en/celebrity/librarian.stf', 121, 'most_unfortunate', 'Ah, unfortunately that''s not the right answer.  Try again, eh?'),
('string/en/celebrity/librarian.stf', 122, 'most_incorrect', 'No, that is incorrect.  I''m sorry, I thought you''d get that one for sure.  Oh well, another chance?'),
('string/en/celebrity/librarian.stf', 123, 'worst_answer_ever', 'I''ve seen simpletons answer that question better.  It''s like you don''t have a clue.  So, again?'),
('string/en/celebrity/librarian.stf', 124, 'wrongest', 'Of all the answers you could have given, I can''t believe you gave that one.  That was very, very wrong.  Again?'),
('string/en/celebrity/librarian.stf', 125, 'wrong_squared', 'You really don''t know this material do you?  You should study more.  A weak mind is a terrible thing.  Well, shall we keep going?'),
('string/en/celebrity/librarian.stf', 126, 'you_are_weakest_link', 'Ugh.  That wrong answer physically pained me.  Perhaps you could try harder?  Or is this really the best you can do?  Well, let''s try again shall we?'),
('string/en/celebrity/librarian.stf', 127, 'not_even_trying', 'You''re not even trying are you?  I sincerely hope not.  Let''s just do it again, ok?'),
('string/en/celebrity/librarian.stf', 128, 'done', 'Well, you''ve answered all the questions I have.  Perhaps if you come back another time we can play again.  Who knows, perhaps I''ll even have more questions for you then.'),
('string/en/celebrity/librarian.stf', 129, 'thanks', 'Thank you for everything.'),
('string/en/celebrity/librarian.stf', 130, 'answered_all', 'You''re a smart one, you are.  Very smart.  That''s good.  I like smart people.'),
('string/en/celebrity/lok_engineer.stf', 1, 'hello', 'Something I can help you with?  I don''t seem to recall your face, but I''m getting a little long in the tooth.  Do we know each other?'),
('string/en/celebrity/lok_engineer.stf', 2, 'jinkins_sent_me', 'No. But I''m a friend of Jinkin''s.'),
('string/en/celebrity/lok_engineer.stf', 3, 'who_are_you', 'I don''t think so.  Who are you?'),
('string/en/celebrity/lok_engineer.stf', 4, 'just_a_guy', 'Just someone who''s been stuck on Lok for too long, but you can call me Choster. It seems I''ve seen a thousand fringers just like you wandering this wasteland. You sure we haven''t met?'),
('string/en/celebrity/lok_engineer.stf', 5, 'i_know_jinkins', 'Ah, yes! Jinkins. A brilliant engineer. I''m not sure why he sticks with those Lok Revenants, though. He could have made a fortune as a starship designer, but he''s been loyal to Nym since before the Battle of Naboo. But, if Jinkins sent you, then I''m sure I know why. You want to know about the Sulfur Lake Pirates and the engineering work I did for them.'),
('string/en/celebrity/lok_engineer.stf', 6, 'talk_pirates', 'Tell me about the pirates.'),
('string/en/celebrity/lok_engineer.stf', 7, 'talk_engineer', 'What kind of work did you do?'),
('string/en/celebrity/lok_engineer.stf', 8, 'sulfur_lake_pirates', 'The Sulfur Lake Pirates aren''t the brightest pirate band on Lok. First, they named themselves after the lake where they have their "hidden" lair. When they realized that every other group on Lok knew where they were holed up, the Sulfur crew hired me to set up some defenses. We eventually had a... falling out. There''s no band of thieves that I hate more.'),
('string/en/celebrity/lok_engineer.stf', 9, 'hate_pirates', 'Why do you hate them?'),
('string/en/celebrity/lok_engineer.stf', 10, 'pirates_fired', 'After I set up their systems, the Sulfur morons decided that it would be easier, and maybe safer, to kill me instead of pay me. I barely escaped their bloodthirsty veermok with my life.  I had to change my name and find an image designer to give me a new face. But I don''t forget or forgive being betrayed. I came back here to hide on Lok, waiting for a chance to repay them.'),
('string/en/celebrity/lok_engineer.stf', 11, 'i_will_help', 'I''ll deal with them.'),
('string/en/celebrity/lok_engineer.stf', 12, 'security_system', 'I established the safeguards on their security system. It''s not too dangerous, but does keep visitors out of the back room. Anyone who wants to enter needs to punch in a series of codes, which only the pirates know. But I did leave a backdoor: I gave the security system a rudimentary AI that will ask three questions to anyone who doesn''t have the code.  '),
('string/en/celebrity/lok_engineer.stf', 13, 'defenses', 'Can you tell me more about this system''s "backdoor"?'),
('string/en/celebrity/lok_engineer.stf', 14, 'which_defense', 'If you don''t have the access code, the security system is programmed to ask you three questions. The system''s AI is a little... independent. It changes the questions periodically, so I don''t know what they are, exactly. But, I only programmed it with knowledge in three fields: color spectrums, math, and Tatooine humor. Do you want to know more about these areas?'),
('string/en/celebrity/lok_engineer.stf', 15, 'color_defense', 'Tell me about the color spectrum.'),
('string/en/celebrity/lok_engineer.stf', 16, 'math_defense', 'Tell me about the math problems.'),
('string/en/celebrity/lok_engineer.stf', 17, 'other_defense', 'Tell me about the Tatooine jokes.'),
('string/en/celebrity/lok_engineer.stf', 18, 'pirate_artist', 'In my youth, I tried to make my fortune by forging famous holopaintings. I wasn''t very successful, but I did learn basic facts about the "color wheel." The color spectrum includes both primary and secondary colors, and there are opposing colors on the color wheel. Red is the opposite of green, for example. The security system''s AI seemed fascinated with the color wheel, so you might do a little research on that.'),
('string/en/celebrity/lok_engineer.stf', 19, 'sequential_numbers', 'Well, at the time I was very intrigued by sequential numbers. If you''re presented with a string of numbers, like 1, 3, 5, and 7, what comes next?  Nine of course.  That''s just a simple odd number sequence.  The sequence the AI uses might be a bit harder, but it could also be as easy as 1-2-3.'),
('string/en/celebrity/lok_engineer.stf', 20, 'pirate_joker', 'A few years back, I was stranded on Tatooine. I was "befriended" by a Rodian drunk who liked to tell really terrible jokes. The jokes always involved Tatooine native species, like Jawas or dewbacks. The jokes were just awful... How do you get a one-armed Jawa out of a tree? Wave. I tried to purge the jokes from my brain by transferring them to the AI. If the system asks you a joke, just pick the most obvious punch line.'),
('string/en/celebrity/lok_engineer.stf', 21, 'good_luck', 'Well, take care. If you need to ask me about the defenses again, I''ll be here. I hope you give those pirates what they deserve.'),
('string/en/celebrity/lok_engineer.stf', 22, 'more_questions', 'Did you want to ask me something else?'),
('string/en/celebrity/lok_engineer.stf', 23, 'ask_about_defenses', 'I wanted to ask you about the security at the pirate base.'),
('string/en/celebrity/lok_engineer.stf', 24, 'which_defense_2', 'About the colors spectrum, the math problems, or the Tatooine jokes?'),
('string/en/celebrity/lok_engineer.stf', 25, 'who_are_you_2', 'Who are you?'),
('string/en/celebrity/lok_engineer.stf', 26, 'go_away_dude', 'Nobody. And you like your fingers attached to your hands, you''ll just leave it at that.'),
('string/en/celebrity/lok_gambler.stf', 1, 'nym_sent_you', 'I''ve been expecting you. Nym was supposed to send someone to meet me days ago. But, before I give you any information, let''s play a game.'),
('string/en/celebrity/lok_gambler.stf', 2, 'tell_me_something', 'What can you tell me right now?'),
('string/en/celebrity/lok_gambler.stf', 3, 'play_a_game', 'Sure, let''s play.'),
('string/en/celebrity/lok_gambler.stf', 4, 'talk_nym', 'Tell me about Nym.'),
('string/en/celebrity/lok_gambler.stf', 5, 'play_game', 'Interested in wagering a little cash?  Maybe making some money?  I have a game that''s perfect. Wanna hear about it?'),
('string/en/celebrity/lok_gambler.stf', 6, 'what_game', 'Tell me about the game.'),
('string/en/celebrity/lok_gambler.stf', 7, 'sure', 'Let''s play.'),
('string/en/celebrity/lok_gambler.stf', 8, 'games_first', 'I won''t say anything until we''ve played some cards.  You ready?'),
('string/en/celebrity/lok_gambler.stf', 9, 'nym_rules', 'I like Nym. He''s helped me out of a few scrapes over the years. He even bought up all my markers in the galaxy. Now, I''m in his pocket, but it''s better than being dead.'),
('string/en/celebrity/lok_gambler.stf', 10, 'explain_game', 'We''ll play Desert Draw. The game is simple. Just six cards. I pick one of mine and hold it behind my back, then you pick one of yours and then we compare them to see who wins. Simple, eh?'),
('string/en/celebrity/lok_gambler.stf', 11, 'game_rules', 'How do we know who wins?'),
('string/en/celebrity/lok_gambler.stf', 12, 'sure_lets_play', 'Ok, I''m game.  Let''s do it.'),
('string/en/celebrity/lok_gambler.stf', 13, 'explain_rules', 'We each have three cards. A Bounty Hunter, the Sarlacc, and a Thermal Detonator.  I pick one, you pick one, then we compare.  Bounty Hunter beats a Thermal Detonator. Thermal Detonator beats a Sarlacc, and Sarlacc beats the Bounty Hunter. It''s really just that simple. Wanna try a hand?'),
('string/en/celebrity/lok_gambler.stf', 14, 'no_games', 'No, I don''t want to play.'),
('string/en/celebrity/lok_gambler.stf', 15, 'begin_game', 'Ok, I''ve picked my card.  Which one are you going to go with?'),
('string/en/celebrity/lok_gambler.stf', 16, 'thermal_detonator', 'Thermal Detonator.'),
('string/en/celebrity/lok_gambler.stf', 17, 'sarlacc', 'Sarlacc.'),
('string/en/celebrity/lok_gambler.stf', 18, 'bounty_hunter', 'Bounty Hunter.'),
('string/en/celebrity/lok_gambler.stf', 19, 'tie', 'We both picked the same card. It''s a tie.'),
('string/en/celebrity/lok_gambler.stf', 20, 'you_win_td', 'Your Thermal Detonator blows up my Sarlacc.  You win.'),
('string/en/celebrity/lok_gambler.stf', 21, 'you_lose_td', 'My Bounty Hunter disarms the Thermal Detonator.  You lose!'),
('string/en/celebrity/lok_gambler.stf', 22, 'play_again', 'Let''s play again.'),
('string/en/celebrity/lok_gambler.stf', 23, 'you_lose_bh', 'My Sarlacc eats your Bounty Hunter!  You lose.'),
('string/en/celebrity/lok_gambler.stf', 24, 'you_win_bh', 'Your Bounty Hunter disarms my Thermal Detonator.  Stang!'),
('string/en/celebrity/lok_gambler.stf', 25, 'you_lose_s', 'My Thermal Detonator blows up your Sarlacc!  I win!  You lose.'),
('string/en/celebrity/lok_gambler.stf', 26, 'you_win_s', 'Stang! Your Sarlacc swallows my Bounty Hunter.  You win.'),
('string/en/celebrity/lok_gambler.stf', 27, 'begin_game_five_wins', 'Well, you''re pretty good.  I''ll play another hand if you want, or you can ask me some questions...'),
('string/en/celebrity/lok_gambler.stf', 28, 'tell_me_more', 'Tell me about the Imperial Lab.'),
('string/en/celebrity/lok_gambler.stf', 29, 'lab_stuff', 'From what I hear, the lab is a secret weapons project. The scientists there are researching high-end explosives. Really dangerous stuff. Blow you outta your boots, or knock a building offa its foundation. I''m sure that''s why Nym wants into the lab. It''s incredibly well-guarded. Even a bunch of storm commandoes couldn''t bust in, I''d wager. Aside from the dangerous mercs that are crawling all over the base, the lab is patrolled by droidekas. '),
('string/en/celebrity/lok_gambler.stf', 30, 'game_description', 'It''s called Desert Draw.  It''s really simple.  We each have three cards, we both pick a card and show them at the same time. The winner gets the credits.'),
('string/en/celebrity/lok_gambler.stf', 31, 'no_thanks', 'No thanks.'),
('string/en/celebrity/lok_gambler.stf', 32, 'too_bad', 'That''s too bad.  You might have made some money.'),
('string/en/celebrity/lok_gambler.stf', 33, 'bet_how_much', 'How much you wanna bet?  Can''t play without credits you know.'),
('string/en/celebrity/lok_gambler.stf', 34, 'bet_made_5', 'I''ll bet 5 credits.'),
('string/en/celebrity/lok_gambler.stf', 35, 'bet_made_10', 'I''ll bet 10 credits.'),
('string/en/celebrity/lok_gambler.stf', 36, 'bet_made_50', 'I''ll bet 50 credits.'),
('string/en/celebrity/lok_gambler.stf', 37, 'lab_info', 'The lab, eh?  Yeah, I know about it.  It''s pretty well-guarded. Rather than rely on General Otto and his goons, the Imperials in charge of the lab hired mercenaries to protect it. They''re all blood thirsty and will shoot on sight. The scientists shouldn''t give you too much trouble, but there might be other dangers...'),
('string/en/celebrity/lok_gambler.stf', 38, 'other_dangers', 'What other dangers?'),
('string/en/celebrity/lok_gambler.stf', 39, 'other_dangers_info', 'Well, I hear they''re doing some other, illegal experiments in that base. Creating monsters that will rip your arms off and beat you to death with them. Or so the rumors go.'),
('string/en/celebrity/lok_gambler.stf', 40, 'hard_drive_where', 'Where''s the memory module?'),
('string/en/celebrity/lok_gambler.stf', 41, 'hard_drive_loc', 'Well, once you get inside, you''ll find four corridors leading from the central room. The computer room is to the west, I think.  Somewhere in there you''ll find your memory module.'),
('string/en/celebrity/lok_gambler.stf', 42, 'imggcu_where', 'Where are the IMGGCUs?'),
('string/en/celebrity/lok_gambler.stf', 43, 'imggcu_loc', 'Heh, you know about those, eh?  Unfortunately, I don''t know where they store ''em. But, if the Imperials are getting ready to ship the IMGGCUs off of Lok, the explosives are probably stored in a locker or crate, awaiting transport. You''ll have to look around a bit, I''m sure.'),
('string/en/celebrity/lok_gambler.stf', 44, 'leaving', 'I''ll be going now.'),
('string/en/celebrity/lok_gambler.stf', 45, 'good_luck', 'Good luck.'),
('string/en/celebrity/lok_hacker.stf', 1, 'doors_open', 'I''ve already sliced the doors open.  Don''t you remember helping me?'),
('string/en/celebrity/lok_hacker.stf', 2, 'right', 'Oh.  Right.'),
('string/en/celebrity/lok_hacker.stf', 3, 'go_man_go', 'Well don''t waste time!  Get in there!'),
('string/en/celebrity/lok_hacker.stf', 4, 'help_me_hack', 'Aargh!  Can you help me with this thing?  I''ve found a back door to this security system, but the AI program keeps asking me these stupid questions! Can you lend me your brain?'),
('string/en/celebrity/lok_hacker.stf', 5, 'what_are_you_doing', 'What are you talking about?'),
('string/en/celebrity/lok_hacker.stf', 6, 'hacking', 'I''m trying to slice through the pirates'' security system. The system itself is really basic, but the final safeguard includes three questions that I need to answer. The questions don''t have anything to do with the pirates or computers. I''m totally lost.  '),
('string/en/celebrity/lok_hacker.stf', 7, 'what_do_you_need', 'Tell me what you need.'),
('string/en/celebrity/lok_hacker.stf', 8, 'cant_solve', 'I can''t answer these riddles.  Who built this thing? Can you help me answer these questions?'),
('string/en/celebrity/lok_hacker.stf', 9, 'helpful', 'Sure.  What are the questions?'),
('string/en/celebrity/lok_hacker.stf', 10, 'going_away', 'You''re too upset about this. I''m leaving.'),
('string/en/celebrity/lok_hacker.stf', 11, 'explain', 'Great. I need to reroute the access commands, reset the security network, and break the defender chip. But I have to answer one question before I can complete each task. I can give you the questions in any order.'),
('string/en/celebrity/lok_hacker.stf', 12, 'codec', 'Let''s do the network reset.'),
('string/en/celebrity/lok_hacker.stf', 13, 'rewire', 'Let''s reroute the access commands.'),
('string/en/celebrity/lok_hacker.stf', 14, 'defender', 'Let''s break the defender chip.'),
('string/en/celebrity/lok_hacker.stf', 15, 'jerk', 'Fine!  Who needs ya?'),
('string/en/celebrity/lok_hacker.stf', 16, 'color_codes', 'It says, "On a color wheel, this color is the opposite of blue..."  What does that mean?  What''s a color wheel?  And what''s the opposite of blue?'),
('string/en/celebrity/lok_hacker.stf', 17, 'purple', 'I''m pretty sure it''s purple.'),
('string/en/celebrity/lok_hacker.stf', 18, 'brown', 'It''s brown!  Hah! I knew that one.'),
('string/en/celebrity/lok_hacker.stf', 19, 'orange', 'It''s orange. I''m sure of it.'),
('string/en/celebrity/lok_hacker.stf', 20, 'math_problem', 'It says, "Finish this number pair sequence... 1-2, 3-6, 4-24, 5-120, 6-?'),
('string/en/celebrity/lok_hacker.stf', 21, 'seven_twenty', 'It''s multiplying. 720.'),
('string/en/celebrity/lok_hacker.stf', 22, 'two_twenty', 'Uh...220.'),
('string/en/celebrity/lok_hacker.stf', 23, 'nine', 'It''s nine.  I''m sure of it.'),
('string/en/celebrity/lok_hacker.stf', 24, 'punchline', 'Sir!'),
('string/en/celebrity/lok_hacker.stf', 25, 'bad_joke', 'No such thing?'),
('string/en/celebrity/lok_hacker.stf', 26, 'wrong_joke', 'To get to the other side!'),
('string/en/celebrity/lok_hacker.stf', 27, 'wrong_color', 'Apparently that wasn''t it...'),
('string/en/celebrity/lok_hacker.stf', 28, 'not_funny', 'That''s not even funny!'),
('string/en/celebrity/lok_hacker.stf', 29, 'wrong_answer', 'I don''t think so...'),
('string/en/celebrity/lok_hacker.stf', 30, 'defender_2', 'Let''s deal with the defender chip.'),
('string/en/celebrity/lok_hacker.stf', 31, 'rewire_2', 'Now let''s reroute the access commands.'),
('string/en/celebrity/lok_hacker.stf', 32, 'codec_2', 'Ok, let''s reset the network.'),
('string/en/celebrity/lok_hacker.stf', 33, 'joke', 'What do you call a womprat that can lift a bantha?'),
('string/en/celebrity/lok_hacker.stf', 34, 'success', 'That did it!  It''s open!'),
('string/en/celebrity/lok_hacker.stf', 35, 'right_answer', 'That''s it!  Good thing you know your math.  All right, what now?'),
('string/en/celebrity/lok_hacker.stf', 36, 'right_color', 'Great!  You must have studied art or something.  I''d have never gotten that.  Now what?'),
('string/en/celebrity/lok_hacker.stf', 37, 'right_joke', 'Ugh...that''s terrible.  What kind of...nevermind.  Let''s do the next one.'),
('string/en/celebrity/lok_hacker.stf', 38, 'who_are_you', 'Who are you?'),
('string/en/celebrity/lok_hacker.stf', 39, 'faulk', 'My name is Faulk. I was hired by Borvo the Hutt on Naboo to gather information on the Sulfur Lake Pirates. He''s convinced the pirates have hijacked some of his weapons shipments. I''ve been hiding out in this cave for weeks, waiting for a chance to slice into their network and grab all the data I can find. All this commotion has given me the opening I need, but I can''t get past the final safeguards!\n'),
('string/en/celebrity/luke_skywalker.stf', 1, 'npc_1', 'There''s something familiar about your face...'),
('string/en/celebrity/luke_skywalker.stf', 2, 'player_1', 'Me?  No, I''m not from around here.'),
('string/en/celebrity/luke_skywalker.stf', 3, 'player_2', 'Are you Luke Skywalker?'),
('string/en/celebrity/luke_skywalker.stf', 4, 'npc_2', 'Are you sure?  You seem awfully familiar.'),
('string/en/celebrity/luke_skywalker.stf', 5, 'player_3', 'Maybe, but I don''t think we''ve met before.'),
('string/en/celebrity/luke_skywalker.stf', 6, 'npc_6', 'I''m sure I''ll remember it sooner or later.  Stick around and I''ll let you know.'),
('string/en/celebrity/luke_skywalker.stf', 7, 'player_4', 'You''ve confused me with someone else.'),
('string/en/celebrity/luke_skywalker.stf', 8, 'npc_7', 'Yeah, maybe that''s it.'),
('string/en/celebrity/luke_skywalker.stf', 9, 'npc_3', 'I might be.  Who''s asking?'),
('string/en/celebrity/luke_skywalker.stf', 10, 'player_5', 'I have some friends in the Alliance...'),
('string/en/celebrity/luke_skywalker.stf', 11, 'npc_4', 'What did they tell you?  That I''m a hero?  It''s been a little overblown, but yeah, I was there at the Battle of Yavin.'),
('string/en/celebrity/luke_skywalker.stf', 12, 'player_7', 'I hear you took out the Death Star personally.'),
('string/en/celebrity/luke_skywalker.stf', 13, 'npc_8', 'There was a lot more to it than just me.  Lots of my friends died that day.'),
('string/en/celebrity/luke_skywalker.stf', 14, 'player_8', 'It''s an honor, sir...'),
('string/en/celebrity/luke_skywalker.stf', 15, 'npc_9', 'Thanks.  I appreciate it.'),
('string/en/celebrity/luke_skywalker.stf', 16, 'player_6', 'You''re famous.'),
('string/en/celebrity/luke_skywalker.stf', 17, 'npc_5', 'Famous?  I don''t see how I could be famous.  Infamous maybe.'),
('string/en/celebrity/luke_skywalker.stf', 18, 'player_9', 'Well, that''s better than being famous.'),
('string/en/celebrity/luke_skywalker.stf', 19, 'npc_10', 'Mostly it just means people trying to kill me.  I don''t think I like infamous very much.'),
('string/en/celebrity/luke_skywalker.stf', 20, 'player_10', 'You''d be surprised...'),
('string/en/celebrity/luke_skywalker.stf', 21, 'npc_11', 'Almost nothing surprises me anymore.'),
('string/en/celebrity/mara_jade.stf', 1, 'npc_1', 'I''ve got things to do, so if you want to talk make it quick.'),
('string/en/celebrity/mara_jade.stf', 2, 'player_1', 'Who are you?'),
('string/en/celebrity/mara_jade.stf', 3, 'player_2', 'Do you need any help?'),
('string/en/celebrity/mara_jade.stf', 4, 'npc_2', 'My name is Mara Jade.  That is all you need to know.'),
('string/en/celebrity/mara_jade.stf', 5, 'player_3', 'But who are you really?'),
('string/en/celebrity/mara_jade.stf', 6, 'npc_6', 'It''s not your concern.'),
('string/en/celebrity/mara_jade.stf', 7, 'player_4', 'Are you with the alliance?'),
('string/en/celebrity/mara_jade.stf', 8, 'npc_7', 'Sorry, I don''t talk to fools.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/celebrity/mara_jade.stf', 9, 'npc_3', 'I''m just fine on my own.  Don''t you have anything better to do than bother me?'),
('string/en/celebrity/mara_jade.stf', 10, 'player_5', 'Am I bothering you?'),
('string/en/celebrity/mara_jade.stf', 11, 'npc_4', 'Unless you weren''t planning to live long I suggest you knock off the questions.'),
('string/en/celebrity/mara_jade.stf', 12, 'player_7', 'Sorry.'),
('string/en/celebrity/mara_jade.stf', 13, 'npc_8', 'I''ll just be on my way then.'),
('string/en/celebrity/mara_jade.stf', 14, 'player_8', 'You''re awfully touchy.'),
('string/en/celebrity/mara_jade.stf', 15, 'npc_9', 'I pity people like you.  Or I would if I cared.'),
('string/en/celebrity/mara_jade.stf', 16, 'player_6', 'No, not really.'),
('string/en/celebrity/mara_jade.stf', 17, 'npc_5', 'I recommend finding something else to do then.  It would be safer for you.'),
('string/en/celebrity/mara_jade.stf', 18, 'player_9', 'Are you going to kill me?'),
('string/en/celebrity/mara_jade.stf', 19, 'npc_10', 'Not unless you keep it up.  Get out of my sight and live a while longer.'),
('string/en/celebrity/mara_jade.stf', 20, 'player_10', 'Safer?'),
('string/en/celebrity/mara_jade.stf', 21, 'npc_11', 'I don''t generally kill dumb animals, but you''re making it difficult to keep that rule.  No more talking.'),
('string/en/celebrity/megan_drlar.stf', 1, 'npc_1', 'Who do you work for?  Speak up!'),
('string/en/celebrity/megan_drlar.stf', 2, 'player_1', 'I''m here on my own.'),
('string/en/celebrity/megan_drlar.stf', 3, 'player_2', 'I''m part of a group...'),
('string/en/celebrity/megan_drlar.stf', 4, 'npc_2', 'Well, that can get you killed.  Do you know what there is around here?'),
('string/en/celebrity/megan_drlar.stf', 5, 'player_3', 'Jungle?'),
('string/en/celebrity/megan_drlar.stf', 6, 'npc_6', 'Money.  Parts of the Death Star that fell to the planet.  They''re worth a lot to the right bidders.  And they''re all mine, so stay out of my way and stay out of my people''s way.'),
('string/en/celebrity/megan_drlar.stf', 7, 'player_4', 'Debris?'),
('string/en/celebrity/megan_drlar.stf', 8, 'npc_7', 'That debris is worth cold hard credits and I intend to cash out.   Just stay out of the way, all right?'),
('string/en/celebrity/megan_drlar.stf', 9, 'npc_3', 'I don''t need to hear it.  As long as you''re not here to stop me.'),
('string/en/celebrity/megan_drlar.stf', 10, 'player_5', 'Stop you from what?'),
('string/en/celebrity/megan_drlar.stf', 11, 'npc_4', 'Heh.  From collecting my due.  My salvage team is gonna reap the rewards of this stuff.'),
('string/en/celebrity/megan_drlar.stf', 12, 'player_7', 'What stuff?'),
('string/en/celebrity/megan_drlar.stf', 13, 'npc_8', 'Pieces of the Death Star.  They''re ours for the taking.'),
('string/en/celebrity/megan_drlar.stf', 14, 'player_8', 'Salvage team?'),
('string/en/celebrity/megan_drlar.stf', 15, 'npc_9', 'That''s right.  I run a tight group here.  We''re gonna make a bundle.'),
('string/en/celebrity/megan_drlar.stf', 16, 'player_6', 'I''m not.'),
('string/en/celebrity/megan_drlar.stf', 17, 'npc_5', 'Good, cause I wouldn''t have let you.  And neither would my team.'),
('string/en/celebrity/megan_drlar.stf', 18, 'player_9', 'Your team?'),
('string/en/celebrity/megan_drlar.stf', 19, 'npc_10', 'My guys are here to collect salvage, but don''t think that means they''re pushovers.  They''ll take you down if I give the word.  Got it?'),
('string/en/celebrity/megan_drlar.stf', 20, 'player_10', 'I''m done.'),
('string/en/celebrity/megan_drlar.stf', 21, 'npc_11', 'Me too.  Talk to you later if you live that long.'),
('string/en/celebrity/mon_mothma.stf', 1, 'npc_1', 'Hello.  And welcome.  Is there something I can do for you?'),
('string/en/celebrity/mon_mothma.stf', 2, 'player_1', 'That''s nice, but no thanks.  I''m fine.'),
('string/en/celebrity/mon_mothma.stf', 3, 'player_2', 'Who are you?'),
('string/en/celebrity/mon_mothma.stf', 4, 'npc_2', 'Anytime.  Just let me know if you need anything.'),
('string/en/celebrity/mon_mothma.stf', 5, 'player_3', 'Ok, will do.'),
('string/en/celebrity/mon_mothma.stf', 6, 'npc_6', 'Good.  Now I must get back to work.'),
('string/en/celebrity/mon_mothma.stf', 7, 'player_4', 'You''re sweet.'),
('string/en/celebrity/mon_mothma.stf', 8, 'npc_7', 'Thank you again.  I''m going to blush.'),
('string/en/celebrity/mon_mothma.stf', 9, 'npc_3', 'My name is Mon Mothma.  I don''t think you would have heard of me.'),
('string/en/celebrity/mon_mothma.stf', 10, 'player_5', 'I don''t think so.'),
('string/en/celebrity/mon_mothma.stf', 11, 'npc_4', 'I''m not surprised.  I try to stay out of the public eye for the most part.  Comes with the job.'),
('string/en/celebrity/mon_mothma.stf', 12, 'player_7', 'What is your job?'),
('string/en/celebrity/mon_mothma.stf', 13, 'npc_8', 'Many people would die if I simply gave that information to everyone who asked.  I won''t tell you just yet, but maybe if I get to know you better.'),
('string/en/celebrity/mon_mothma.stf', 14, 'player_8', 'Do you find it difficult to stay hidden?'),
('string/en/celebrity/mon_mothma.stf', 15, 'npc_9', 'Sometimes.  But there are so many things happening so quickly right now that it''s becoming easier and harder at the same time.  I know, that doesn''t make much snese does it?'),
('string/en/celebrity/mon_mothma.stf', 16, 'player_6', 'Mon Mothma?  I have heard of you!'),
('string/en/celebrity/mon_mothma.stf', 17, 'npc_5', 'Some people know my name.  Some know my occupation.  Hopefully you aren''t a threat to me, I''d hate for us to be enemies.'),
('string/en/celebrity/mon_mothma.stf', 18, 'player_9', 'I just know your name.'),
('string/en/celebrity/mon_mothma.stf', 19, 'npc_10', 'Then you''re safe for now.  Try not to ask too many questions in the future.'),
('string/en/celebrity/mon_mothma.stf', 20, 'player_10', 'I know you and what you do.'),
('string/en/celebrity/mon_mothma.stf', 21, 'npc_11', 'Then I hope we are allies.  '),
('string/en/celebrity/morag.stf', 1, 'npc_1', 'I am the Tulgah Witch!'),
('string/en/celebrity/morag.stf', 2, 'player_1', 'What do you do?'),
('string/en/celebrity/morag.stf', 3, 'player_2', 'What''s a Tulgah?'),
('string/en/celebrity/morag.stf', 4, 'npc_2', 'Whatever I please!'),
('string/en/celebrity/morag.stf', 5, 'npc_3', 'I am, fool!'),
('string/en/celebrity/muftak.stf', 1, 'npc_1', 'I''m just here to have a drink.'),
('string/en/celebrity/muftak.stf', 2, 'player_1', 'How bout some friendly chatter?'),
('string/en/celebrity/muftak.stf', 3, 'player_2', 'Buy me a drink?'),
('string/en/celebrity/muftak.stf', 4, 'npc_2', 'No thanks.'),
('string/en/celebrity/muftak.stf', 5, 'npc_3', 'I don''t think so.'),
('string/en/celebrity/nym.stf', 1, 'first_time_hello', 'I don''t know who you are or why you''re here, and I don''t really care. I assume you want some work, just like every other fringer who wanders into my stronghold. But just because you''re tough enough to survive on my planet doesn''t mean you''re ready to join the Lok Revenants. I only take the meanest mercenaries into my crew. You gotta prove yourself before I''ll even think about giving you any assignments. In the interest of keeping the peace, I''ll let you stick around. But step out of line, and I''ll send a blaster bolt through your brain. '),
('string/en/celebrity/nym.stf', 2, 'tell_me_quest', 'I''m looking for work.'),
('string/en/celebrity/nym.stf', 3, 'quienne_esta', 'Who are you?'),
('string/en/celebrity/nym.stf', 4, 'yo_es_nym', 'I''m Nym, captain of the Lok Revenants. We''re the largest pirate crew on Lok, and I''ll crush anyone who claims different.  '),
('string/en/celebrity/nym.stf', 5, 'who_is_kole', 'Who is Kole?'),
('string/en/celebrity/nym.stf', 6, 'who_is_jinkins', 'Tell me about Jinkins.'),
('string/en/celebrity/nym.stf', 7, 'jinkins_is', 'Jinkins? He''s the best engineer this side of Corellia. Anything I can blow up, he can put back together.   '),
('string/en/celebrity/nym.stf', 8, 'kole_is', 'Kole''s my Chadra-Fan first mate and co-pilot. Rescued me from more than one assassination attempt, so watch your back and keep your hands where Kole can see ''em. We''ve been working together since before the Battle of Naboo. There isn''t anyone I trust more.  '),
('string/en/celebrity/nym.stf', 9, 'quest_info', 'You''re persistent, I''ll give you that. I might have work for someone too stupid to know when to give up, and you look like you fit that description. There''s an Imperial research facility on Lok that my spies think is filled with experimental weapons. I want whatever that base is building. You''ll need help from Jinkins and Kole if you want to pull this off.'),
('string/en/celebrity/nym.stf', 10, 'jinkins_story', 'What can I do for Jinkins?'),
('string/en/celebrity/nym.stf', 11, 'hello_again', 'Well, well, you''re back. Need something else?'),
('string/en/celebrity/nym.stf', 12, 'koles_story', 'What kind of help does Kole need?'),
('string/en/celebrity/nym.stf', 13, 'imggcu', 'What is it you need from the research lab?'),
('string/en/celebrity/nym.stf', 14, 'imperial_bribe', 'What can I do for you?'),
('string/en/celebrity/nym.stf', 15, 'tell_me_again', 'Tell me again what you need from me...'),
('string/en/celebrity/nym.stf', 16, 'quest_info_again', 'Like I said, I''m looking for someone who can bust into an Imperial research facility. '),
('string/en/celebrity/nym.stf', 17, 'ill_see_jinkins', 'Let me talk to Jinkins.'),
('string/en/celebrity/nym.stf', 18, 'ill_see_kole', 'I''ll go talk to Kole.'),
('string/en/celebrity/nym.stf', 19, 'something_funny_kole', 'Don''t make him mad. He hasn''t killed anyone in two weeks and I think he''s gettin'' bored.'),
('string/en/celebrity/nym.stf', 20, 'something_funny_jinkins', 'Good. Just remember that we''re watching you. Put a leg outta line, and I''ll cut it off.'),
('string/en/celebrity/nym.stf', 21, 'jinkins_quest_info', 'Jinkins has some information about a crashed starship carrying an Imperial droid. It could be useful to us. Ask him about it.'),
('string/en/celebrity/nym.stf', 22, 'kole_quest_info', 'Kole''s interested in an Imperial mining facility on Lok. He''ll give you more information about it.'),
('string/en/celebrity/nym.stf', 23, 'help_others', 'I''m not going to take a chance on you until you earn Jinkins'' trust and Kole''s respect. Better get to work.'),
('string/en/celebrity/nym.stf', 24, 'retired_officer', 'You might be able to help both of us out by talking to a "friend" of mine, an informant who might have some information about the research facility and its defenses. If you can stand talkin'' to an immoral slug, I''ll give you directions to his favorite hangout.'),
('string/en/celebrity/nym.stf', 25, 'ill_see_officer', 'I''ll go talk to this guy.'),
('string/en/celebrity/nym.stf', 26, 'ill_go_lab', 'I''m going into the lab, and nothing can stop me.'),
('string/en/celebrity/nym.stf', 27, 'lab_info', 'There are two things I want: First, I want all the research the scientists have done. Just grab a memory unit from one of the lab''s computers. Second, I need some Imperial Military Grade Grenade Casing Units. The Imps call them IMGGCUs. There should be a stash of them somewhere in that base.  Bring me the memory unit and the IMGGCUs, and I''ll make sure you''re well-paid.'),
('string/en/celebrity/nym.stf', 28, 'go_lab', 'Get outta here, then. Bring me back what I asked for, and we''ll do some business.'),
('string/en/celebrity/nym.stf', 29, 'go_to_officer', 'Tell him I sent you, and he should squawk.'),
('string/en/celebrity/nym.stf', 30, 'your_the_best', 'Great work. Kole and Jinkins can vouch for you, and now you''ve done your part for me. Feel free to visit the stronghold whenever you need supplies. Just don''t bring along any trouble, and you''ll always be welcome here.'),
('string/en/celebrity/nym.stf', 31, 'now_drive', 'Good, but I still need the memory module.'),
('string/en/celebrity/nym.stf', 32, 'now_imggcu', 'Nice job, but I still need the grenade casing units. Bring me the IMGGCUs.'),
('string/en/celebrity/nym.stf', 33, 'youre_done', 'I appreciate the work you did for us.  You''re still in my good graces, so feel free to roam around on Lok.  '),
('string/en/celebrity/nym.stf', 34, 'wheres_drive', 'Have you found that memory module yet?  That should be your top priority now.'),
('string/en/celebrity/nym.stf', 35, 'wheres_imggcu', 'Get your hands on those IMGGCUs. I need the grenade casings to start causing some serious trouble here on Lok.'),
('string/en/celebrity/nym.stf', 36, 'working_on_it', 'No, I''m still working on that.'),
('string/en/celebrity/nym.stf', 37, 'get_to_it_chief', 'Well, get back to work!'),
('string/en/celebrity/prefect_talmont.stf', 1, 'npc_1', 'What is it that you want?'),
('string/en/celebrity/prefect_talmont.stf', 2, 'player_1', 'What is a prefect anyway?'),
('string/en/celebrity/prefect_talmont.stf', 3, 'player_2', 'What is it that you do here?'),
('string/en/celebrity/prefect_talmont.stf', 4, 'npc_2', 'It''s called a title.  That''s what you get when you''re respected at your job.'),
('string/en/celebrity/prefect_talmont.stf', 5, 'player_3', 'If you''re so respected why are you stuck here on Tatooine?'),
('string/en/celebrity/prefect_talmont.stf', 6, 'player_4', 'Maybe I should get a title.'),
('string/en/celebrity/prefect_talmont.stf', 7, 'npc_6', 'I don''t have time for fools like you.'),
('string/en/celebrity/prefect_talmont.stf', 8, 'npc_7', 'Perhaps you should get a job first.'),
('string/en/celebrity/prefect_talmont.stf', 9, 'npc_3', 'I''m in charge of security here on Tatooine. '),
('string/en/celebrity/prefect_talmont.stf', 10, 'player_5', 'Why don''t you do something about the criminals?'),
('string/en/celebrity/prefect_talmont.stf', 11, 'player_6', 'What exactly does that entail?'),
('string/en/celebrity/prefect_talmont.stf', 12, 'npc_4', 'Criminals?  Whatever do you mean?'),
('string/en/celebrity/prefect_talmont.stf', 13, 'player_7', 'What about Jabba the Hutt?'),
('string/en/celebrity/prefect_talmont.stf', 14, 'player_8', 'What about Lady Valarian?'),
('string/en/celebrity/prefect_talmont.stf', 15, 'npc_8', 'Jabba is a respected businessman, and I shall hear no more of this slander.'),
('string/en/celebrity/prefect_talmont.stf', 16, 'npc_9', 'I don''t even know who that is.'),
('string/en/celebrity/prefect_talmont.stf', 17, 'npc_5', 'It means keeping the streets safe for citizens like yourself.'),
('string/en/celebrity/prefect_talmont.stf', 18, 'player_9', 'Just in Bestine?'),
('string/en/celebrity/prefect_talmont.stf', 19, 'player_10', 'Well, you''re doing a great job.'),
('string/en/celebrity/prefect_talmont.stf', 20, 'npc_10', 'No!  On the entire planet!'),
('string/en/celebrity/prefect_talmont.stf', 21, 'npc_11', 'Thank you for the kind words.  I''ll remember them if I ever have to arrest you.'),
('string/en/celebrity/ruwan_tokai.stf', 1, 'npc_1', 'I''m the technician here.  Did you bring my parts?'),
('string/en/celebrity/ruwan_tokai.stf', 2, 'player_1', 'What parts?'),
('string/en/celebrity/ruwan_tokai.stf', 3, 'player_2', 'I don''t know what you mean?'),
('string/en/celebrity/ruwan_tokai.stf', 4, 'npc_2', 'The parts I ordered!  Did you bring them or not?'),
('string/en/celebrity/ruwan_tokai.stf', 5, 'player_3', 'Well...no.'),
('string/en/celebrity/ruwan_tokai.stf', 6, 'npc_6', 'Great.  What use are you to me then?'),
('string/en/celebrity/ruwan_tokai.stf', 7, 'player_4', 'I''m not the deliver--'),
('string/en/celebrity/ruwan_tokai.stf', 8, 'npc_7', 'Forget it.  You''re not the delivery guy.  Sorry.  Thought you were someone else.'),
('string/en/celebrity/ruwan_tokai.stf', 9, 'npc_3', 'You do know what parts are right?  Machine parts?  Metal and gears?  Make stuff work?'),
('string/en/celebrity/ruwan_tokai.stf', 10, 'player_5', 'I know what parts are.'),
('string/en/celebrity/ruwan_tokai.stf', 11, 'npc_4', 'Do you know what ''bring'' means?'),
('string/en/celebrity/ruwan_tokai.stf', 12, 'player_7', 'Yeah, I know...'),
('string/en/celebrity/ruwan_tokai.stf', 13, 'npc_8', 'Which part of the sentence confused you then?  Did.  You.  Bring.  My.  Parts?  Forget it....(sigh)'),
('string/en/celebrity/ruwan_tokai.stf', 14, 'player_8', 'Don''t get smart.'),
('string/en/celebrity/ruwan_tokai.stf', 15, 'npc_9', 'Then don''t play dumb.  Where are my parts?'),
('string/en/celebrity/ruwan_tokai.stf', 16, 'player_6', 'Machine parts?'),
('string/en/celebrity/ruwan_tokai.stf', 17, 'npc_5', 'Oh dear...you do know what a machine is right?'),
('string/en/celebrity/ruwan_tokai.stf', 18, 'player_9', 'You have me confused with--'),
('string/en/celebrity/ruwan_tokai.stf', 19, 'npc_10', 'I think you''ve done a pretty good job of confusing yourself.'),
('string/en/celebrity/ruwan_tokai.stf', 20, 'player_10', 'Machine?'),
('string/en/celebrity/ruwan_tokai.stf', 21, 'npc_11', 'Forget it.  I''ll get a Wookiee to do it next time.  At least they don''t talk back.'),
('string/en/celebrity/scholar_szingo.stf', 1, 'npc_1', 'What is it that you want?'),
('string/en/celebrity/scholar_szingo.stf', 2, 'player_1', 'Are you really a scholar?'),
('string/en/celebrity/scholar_szingo.stf', 3, 'player_2', 'Who do you work for?'),
('string/en/celebrity/scholar_szingo.stf', 4, 'npc_2', 'Truly I have studied more than any Marauder in history.'),
('string/en/celebrity/scholar_szingo.stf', 5, 'npc_3', 'I am the chief advisor to King Terak, the mighty ruler of the Marauders.'),
('string/en/celebrity/wald.stf', 1, 'npc_1', 'Welcome to Watto''s Junk Shop.  What can I do for you?'),
('string/en/celebrity/wald.stf', 2, 'player_1', 'Where''s Watto?'),
('string/en/celebrity/wald.stf', 3, 'player_2', 'Who are you?'),
('string/en/celebrity/wald.stf', 4, 'npc_2', 'Watto had some unexpected business back on his home planet.  I''m running things while he''s away.'),
('string/en/celebrity/wald.stf', 5, 'player_3', 'Well, I''ll wait for him to come back.'),
('string/en/celebrity/wald.stf', 6, 'player_4', 'That sounds awfully suspicious.'),
('string/en/celebrity/wald.stf', 7, 'npc_6', 'Suit yourself.  If you''d rather deal with the Toydarian that''s your business.'),
('string/en/celebrity/wald.stf', 8, 'npc_7', 'Suspicious?  You think I''d hurt my own business partner?  Actually...that''s not a bad idea...'),
('string/en/celebrity/wald.stf', 9, 'npc_3', 'My name is Wald.  I grew up here on Tatooine.'),
('string/en/celebrity/wald.stf', 10, 'player_5', 'Really?  Why are you working here?'),
('string/en/celebrity/wald.stf', 11, 'player_6', 'You''ve been here that long?'),
('string/en/celebrity/wald.stf', 12, 'npc_4', 'I went into business with Watto many years ago.  Now I run the store when he''s away.'),
('string/en/celebrity/wald.stf', 13, 'npc_5', 'I was here when Anakin Skywalker won the Pod Races!'),
('string/en/celebrity/wald.stf', 14, 'player_9', 'Wow.  I have no idea what you''re talking about.'),
('string/en/celebrity/wald.stf', 15, 'player_10', 'That''s amazing!'),
('string/en/celebrity/wald.stf', 16, 'npc_10', 'You don''t?  I thought everyone had heard about that.'),
('string/en/celebrity/wald.stf', 17, 'npc_11', 'Well, what can I say.  I''ve had an amazing life.'),
('string/en/celebrity/wald.stf', 18, 'player_7', 'What does that mean really?'),
('string/en/celebrity/wald.stf', 19, 'player_8', 'Why would you work with Watto?  Isn''t he mean?'),
('string/en/celebrity/wald.stf', 20, 'npc_9', 'No.  You just have to know how to handle him, really.'),
('string/en/celebrity/wald.stf', 21, 'npc_8', 'Mostly it means sitting here counting junk while no one comes in to buy things.  Pretty dull really...'),
('string/en/character_transfer.stf', 2, 'failed_jedi', 'Transfer of your character failed. Jedi characters are not allowed to transfer.'),
('string/en/character_transfer.stf', 3, 'failed_subject', 'Character transfer failed!'),
('string/en/character_transfer.stf', 4, 'failed_items_disallowed', 'Character transfer failed because one or more items in the character inventory are not permitted to transfer. Factory crates and resource containers are examples of items that will not transfer. Refer to the terms of service for a definitive list of which items will not transfer.'),
('string/en/chassis_npc.stf', 1, 'buy_ship_title', 'Ship Chassis Sales'),
('string/en/chassis_npc.stf', 2, 'buy_ship_prompt', 'Please select a ship chassis you would like to purchase.'),
('string/en/chassis_npc.stf', 3, 'btn_buy', 'Buy Chassis'),
('string/en/chassis_npc.stf', 4, 'already_have', 'You already have too many ships!'),
('string/en/chassis_npc.stf', 5, 'no_money', 'You don''t have enough money for that purchase.  Stop wasting my time.'),
('string/en/chassis_npc.stf', 6, 'failed', 'Failed to create ship.'),
('string/en/chassis_npc.stf', 7, 'npc_name', 'Chassis Dealer'),
('string/en/chassis_npc.stf', 8, 'bought_chassis', 'Congratulations on your purchase.  Happy flying!'),
('string/en/chassis_npc.stf', 9, 'too_many_pobs', 'You already have one multi-person craft in your datapad.  You do not have room for another.'),
('string/en/chassis_npc.stf', 10, 'no_deeds', 'Oh, I''m sorry, but you don''t seem to be carrying any valid ship blueprints.'),
('string/en/chassis_npc.stf', 11, 'inv_full', 'You would have no room for these blueprints if I gave them to you.'),
('string/en/chassis_npc.stf', 12, 'succeed', 'You successfully add a ship control device to your datapad.'),
('string/en/chassis_npc.stf', 13, 'not_in_inv', 'The blueprints you are trying to convert are not in your inventory.  I cannot work with these.'),
('string/en/chassis_npc.stf', 14, 'not_certified', 'You would not be able to fly that ship if you unpacked it.'),
('string/en/chassis_npc.stf', 15, 'can_use', 'It appears you are certified to use the ship you are about to buy.  Are you sure you want to complete this transaction?'),
('string/en/chassis_npc.stf', 16, 'cannot_use', 'It appears you are NOT certified to use the ship you are about to buy.  Are you sure you want to complete this transaction?'),
