('string/en/chat_types.stf', 117, 'aaaaa_____do_not_translate_____', 'Greetings...  DO NOT TRANSLATE THIS FILE!!!  This is a data file that the game uses.  Please do not translate it.  If you do, all the say commands will break.  Please do not translate this file.  Thank you.  DO NOT TRANSLATE THIS FILE!!!  -JAB'),
('string/en/city/bestine/terminal_items.stf', 1, 'download', 'Download'),
('string/en/city/bestine/terminal_items.stf', 2, 'download_complete', 'Download Complete'),
('string/en/city/bestine/terminal_items.stf', 3, 'fail', 'The desk is littered with business-related papers and miscellaneous items. You find nothing of interest.'),
('string/en/city/bestine/terminal_items.stf', 4, 'receive', 'You find a handheld viewscreen in the jumble of papers. It looks like it would contain valuable information.'),
('string/en/city/bestine/terminal_items.stf', 5, 'receive1', 'The desk is neat. It''s easy to find the accountant''s log book. You take the item. '),
('string/en/city/bestine/terminal_items.stf', 6, 'receivemsg', 'You find a handheld viewscreen in the jumble of papers. It looks like it would contain valuable information.'),
('string/en/city/bestine/terminal_items.stf', 7, 'searched', 'Access Denied: You have already downloaded data from this terminal.'),
('string/en/city/bestine/terminal_items.stf', 8, 'inv_full', 'Download Terminated: Inventory Full'),
('string/en/city/bestine/terminal_items.stf', 9, 'history_disk_found', 'As you approach the terminal, you notice something sticking out of a dataslot and you take it. The object appears to be an aged datadisk, but it looks like it might still be readable.'),
('string/en/city/bestine/terminal_items.stf', 10, 'history_disk_found_already', 'You search the area, but find nothing else of interest.'),
('string/en/city/city.stf', 1, 'new_city_subject', 'New City Established!'),
('string/en/city/city.stf', 2, 'new_city_body', 'Congratulations, you have successfully established a new outpost on the frontier!\n\nIn order for your outpost to be recognized by the planetary authorities, you will need to acquire 10 citizens within the next 24 hours.  If you fail to reach the citizenship requirements on time, your city zoning permits will be rejected and the city hall destroyed.  A player can become a citizen by declaring a residence within the city borders.  If a player already owns a residence within the borders of your new city, they will be made a citizen the next time they enter their residence.\n\nOnly citizens can vote in weekly city elections.  Your newly placed city hall has a terminal for managing this voting process.  Remember that your position as Mayor lasts only as long as the citizens of your city choose to continue to elect you.\n\nThe city hall also contains a city management terminal you can use to gather information on your city as well as to appoint members of the city militia.\n\nGood luck Mayor %TO!'),
('string/en/city/city.stf', 3, 'new_city_from', 'Planetary Civic Authority'),
('string/en/city/city.stf', 4, 'new_city_structure_subject', 'City Growth: Added Structure'),
('string/en/city/city.stf', 5, 'new_city_structure_body', 'A new structure has been added to your city.\n\nStructure Type: %TT\nStructure Owner: %TO'),
('string/en/city/city.stf', 6, 'new_city_citizen_subject', 'City Growth: Added Citizen'),
('string/en/city/city.stf', 7, 'new_city_citizen_body', 'A new citizen has joined your city.\n\nCitizen Name: %TO'),
('string/en/city/city.stf', 8, 'new_city_structure_other_subject', 'Structure Added to City'),
('string/en/city/city.stf', 9, 'new_city_structure_other_body', 'Welcome to %TU!\n\nYour %TO was built within the borders of our fine city.  In exchange for using the city''s land and local civic services, you may be charged property taxes.  Please check the current tax rate at the City Hall.\n\nWe thank you for joining %TU,\n\nMayor %TT'),
('string/en/city/city.stf', 10, 'new_city_citizen_other_subject', 'Welcome, Citizen!'),
('string/en/city/city.stf', 11, 'new_city_citizen_other_body', 'Welcome to %TU, citizen!\n\nCongratulations, you have become a fully enfranchised citizen of the city of %TU and are now subject to the benefits and rights accorded such a status.  As a citizen of the city you have the ability to vote in local issues as well as in the weekly mayoral election.  If you are a politician, you are now able to run for election yourself.  You may also now be appointed to the city Militia.\n\nWe thank you for joining our family,\n\nMayor %TT'),
('string/en/city/city.stf', 12, 'new_city_success_subject', 'New City Approved!'),
('string/en/city/city.stf', 13, 'new_city_success_body', 'Congratulations!  The Planetary Civic Authority has approved your city''s zoning permits!  Your city is valid and will begin to grow as citizens join it.\n\nGood Luck!'),
('string/en/city/city.stf', 14, 'new_city_fail_subject', 'Zoning Permits Rejected'),
('string/en/city/city.stf', 15, 'new_city_fail_body', 'We are sorry to inform you that your city failed to receive sufficient interest to remain solvent.  Your zoning applications have been rejected and your city hall has been removed.\n\nPlanetary Civic Authority'),
('string/en/city/city.stf', 16, 'mayoral_race', 'Mayoral Race'),
('string/en/city/city.stf', 17, 'mayoral_standings', 'View Standings'),
('string/en/city/city.stf', 18, 'mayoral_vote', 'Vote for Mayor'),
('string/en/city/city.stf', 19, 'mayoral_register', 'Register to Run'),
('string/en/city/city.stf', 20, 'register_incumbent', 'You are the incumbent Mayor and are automatically registered in the race.'),
('string/en/city/city.stf', 21, 'register_noncitizen', 'Only a citizen of the city may enter the race.'),
('string/en/city/city.stf', 22, 'register_nonpolitician', 'You must be at least a Novice Politician in order to run for mayor.'),
('string/en/city/city.stf', 23, 'register_dupe', 'You are already registered for the Mayoral race.'),
('string/en/city/city.stf', 24, 'register_congrats', 'Congratulations, you are now listed on the ballot for the Mayoral race!'),
('string/en/city/city.stf', 25, 'mayoral_standings_d', 'A complete list of current Mayoral candidates and their vote standing follows.'),
('string/en/city/city.stf', 26, 'mayoral_standings_t', 'Mayoral Race Standings'),
('string/en/city/city.stf', 27, 'mayoral_vote_t', 'Place Mayoral Vote'),
('string/en/city/city.stf', 28, 'mayoral_vote_d', 'Select your desired candidate from the list below.  You may change your vote at any time.'),
('string/en/city/city.stf', 29, 'vote_noncitizen', 'You must be a citizen of the city to vote for Mayor.'),
('string/en/city/city.stf', 30, 'vote_placed', 'Your vote for %TO has been recorded.'),
('string/en/city/city.stf', 31, 'no_candidates', 'No one has registered to run.'),
('string/en/city/city.stf', 32, 'election_new_mayor_subject', 'Congratulations Mayor!'),
('string/en/city/city.stf', 33, 'election_new_mayor_body', 'Congratulations %TT!\n\nYou have been elected the new mayor of %TO by popular vote.  Control of the city''s civic assets has been transferred to you.  The next mayoral election has started and will be tabulated in three weeks'' time.  Good luck in your new position of responsibility, Mayor %TT!'),
('string/en/city/city.stf', 34, 'election_incumbent_lost_subject', 'Election Lost'),
('string/en/city/city.stf', 35, 'election_incumbent_lost_body', 'Citizen,\n\nIt is with regret that we inform you that you have lost the position of Mayor of %TO to %TT.  Your rights and privileges as Mayor have been revoked and your status has been reset to that of citizen.  The city thanks you for your service and hopes to see you run for election in the next mayoral race.'),
('string/en/city/city.stf', 36, 'election_incumbent_win_subject', 'Election Won');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/city/city.stf', 37, 'election_incumbent_win_body', 'Congratulations, Mayor %TT!\n\nThe populace of %TO has elected to retain you for another term.  Your rights and privileges as Mayor have not changed.  The next mayoral election has started and the results will be tabulated in three weeks'' time.\n\nThe city thanks you for your continued service.'),
('string/en/city/city.stf', 38, 'city_name_t', 'Enter City Name'),
('string/en/city/city.stf', 39, 'city_name_d', 'Enter the desired name for your new city.  Note that you must have at least 10 citizens join your city within 24 hours of placement in order for your city to be approved.'),
('string/en/city/city.stf', 40, 'city_info', 'City Info'),
('string/en/city/city.stf', 41, 'city_management', 'City Management'),
('string/en/city/city.stf', 42, 'city_name', 'Change City Name'),
('string/en/city/city.stf', 43, 'treasury_taxes', 'Adjust Taxes'),
('string/en/city/city.stf', 44, 'city_citizens', 'Citizenship Report'),
('string/en/city/city.stf', 45, 'city_structures', 'Structure Report'),
('string/en/city/city.stf', 46, 'city_status', 'Status Report'),
('string/en/city/city.stf', 47, 'city_name_new_t', 'Change City Name'),
('string/en/city/city.stf', 48, 'city_name_new_d', 'Enter the new city name below.  Your city must be uniquely named for this planet.  Note that the citizens of your town will receive an email notifying them of the city name change.'),
('string/en/city/city.stf', 49, 'name_changed', 'The city name has been successfully changed.'),
('string/en/city/city.stf', 50, 'citizen_list_t', 'City Citizenship Report'),
('string/en/city/city.stf', 51, 'citizen_list_d', 'The following is a list of the currently declared citizens (residents) of this city.  All citizens are elligible to vote.'),
('string/en/city/city.stf', 52, 'structure_list_t', 'City Structure Report'),
('string/en/city/city.stf', 53, 'structure_list_d', 'The following is a list of the city owned structures currently within the city borders.  (This list only includes structures currently loaded by the game server.)'),
('string/en/city/city.stf', 54, 'city_info_t', 'City Status Report'),
('string/en/city/city.stf', 55, 'city_info_d', 'A report of the current city status follows.'),
('string/en/city/city.stf', 56, 'city_militia', 'Manage Militia'),
('string/en/city/city.stf', 57, 'militia_t', 'Manage Militia'),
('string/en/city/city.stf', 58, 'militia_d', 'Below is a list of current city militia members.  These citizens have the ability to ban visitors from accessing city services as well as the ability to attack visitors for the purposes of law enforcement.  To add a new citizen to the militia select "Add Militia Member" and hit OK.  To remove someone from the militia, select their name and hit OK.'),
('string/en/city/city.stf', 59, 'militia_new_t', 'Add Militia Member'),
('string/en/city/city.stf', 60, 'militia_new_d', 'Enter the name of the person you wish to add to the militia (the name must be entered exactly as it appears in game).  In order to join the city militia, the player must be a citizen of this city and must be standing near the city management terminal.'),
('string/en/city/city.stf', 61, 'cant_find_player', 'The system was unable to find that player.  Make sure they are standing within 10 meters of the city terminal and try again.'),
('string/en/city/city.stf', 62, 'not_citizen', 'That player must be a citizen to join the city militia.'),
('string/en/city/city.stf', 63, 'added_militia', 'The player has been successfully added to the city militia.'),
('string/en/city/city.stf', 64, 'removed_militia', 'The player has been successfully removed from the city militia.'),
('string/en/city/city.stf', 65, 'not_in_city', 'You must be in a city to use this command.'),
('string/en/city/city.stf', 66, 'not_militia', 'You must be a member of the city militia to use this command.'),
('string/en/city/city.stf', 67, 'city_warned', 'You are now attackable by the city militia and defenses up to the city limits!'),
('string/en/city/city.stf', 68, 'city_warn_done', '%TT is now attackable by the city militia up to the city limits.'),
('string/en/city/city.stf', 69, 'city_banned', 'You have been banned from the this city.  You may no longer use any city services.'),
('string/en/city/city.stf', 70, 'city_ban_done', '%TT has been banned from the city and is no longer able to access city services.'),
('string/en/city/city.stf', 71, 'city_pardoned', 'You have been pardoned and are once again able to use city services.'),
('string/en/city/city.stf', 72, 'city_pardon_done', '%TT has been pardoned and is now able to use city services.'),
('string/en/city/city.stf', 73, 'youre_city_banned', 'You are banned from this city and may not use any of its public services and structures.'),
('string/en/city/city.stf', 74, 'treasury_management', 'City Treasury'),
('string/en/city/city.stf', 75, 'treasury_status', 'Treasury Report'),
('string/en/city/city.stf', 76, 'treasury_deposit', 'Treasury Deposit'),
('string/en/city/city.stf', 77, 'treasury_withdraw', 'Treasury Withdrawal'),
('string/en/city/city.stf', 78, 'no_money', 'There isn''t any money to transfer!'),
('string/en/city/city.stf', 79, 'treasury_balance_t', 'Treasury Balance'),
('string/en/city/city.stf', 80, 'treasury_balance_d', 'A report on current treasury funds follows.'),
('string/en/city/city.stf', 81, 'adjust_taxes_t', 'Adjust Taxes'),
('string/en/city/city.stf', 82, 'adjust_taxes_d', 'Select the tax you wish to adjust from the list below.'),
('string/en/city/city.stf', 83, 'income_tax', 'Income Tax'),
('string/en/city/city.stf', 84, 'property_tax_prompt', 'Property Tax'),
('string/en/city/city.stf', 85, 'sales_tax', 'Sales Tax'),
('string/en/city/city.stf', 86, 'travel_tax', 'Travel Ticket Fee'),
('string/en/city/city.stf', 87, 'set_tax_t_income', 'Adjust Income Tax'),
('string/en/city/city.stf', 88, 'set_tax_t_property', 'Adjust Property Tax'),
('string/en/city/city.stf', 89, 'set_tax_t_sales', 'Adjust Sales Tax'),
('string/en/city/city.stf', 90, 'set_tax_t_travel', 'Adjust Travel Fee'),
('string/en/city/city.stf', 91, 'set_tax_d_income', 'Income tax is a flat fee charged to each citizen of the city every week.  It acts as a "membership fee" for citizens of the city.  The income tax may be any value from 0 to 2000 credits per week.'),
('string/en/city/city.stf', 92, 'set_tax_d_property', 'The property tax is charged to every structure placed within the city on an ongoing basis.  The tax value is a percentage of the total credits paid in maintenance.  (A structure that pays 10 cr/hr would pay the city 1 cr/hr if the property tax was 10%.)  The property tax may be any value from 0 to 50%.'),
('string/en/city/city.stf', 93, 'set_tax_d_sales', 'Sales tax is charged by vendors operating within the city.  It is added to the cost of goods as a percentage of the list cost of the item.  (I.E., an Item that is listed for 100 cr would actually cost 110 cr with a 10% sales tax).  The taxed portion is placed in the city treasury when the item is bought.  Sales tax may be any value from 0 to 20%.'),
('string/en/city/city.stf', 94, 'set_tax_d_travel', 'The travel ticket fee is the portion of the travel ticket cost charged by the city.  The Planetary Travel Authority charges a base ticket fee (which varies based on the source and destination planet).  The city may levy an additional fee ranging from 1 to 500 cr that is collected at the time of ticket purchase.'),
('string/en/city/city.stf', 95, 'tax_out_of_range', 'That tax value is outside the range limitations.'),
('string/en/city/city.stf', 96, 'set_income_tax', 'The city income tax is now %DI credits.'),
('string/en/city/city.stf', 97, 'set_property_tax', 'The city property tax is now %DI% of maintenance.'),
('string/en/city/city.stf', 98, 'set_sales_tax', 'The city sales tax is now %DI% of the item list price.'),
('string/en/city/city.stf', 99, 'set_travel_fee', 'The city travel fee is now %DI credits.'),
('string/en/city/city.stf', 100, 'banned_services', 'You are banned from using this city''s services.'),
('string/en/city/city.stf', 101, 'city_enter_city', 'You have entered %TT (%TO).'),
('string/en/city/city.stf', 102, 'city_leave_city', 'You have left %TO.'),
('string/en/city/city.stf', 103, 'city_ticket_pay', 'You pay a tax of %DI credits to the local City Travel Authority.'),
('string/en/city/city.stf', 104, 'cant_tax', 'You lack the knowledge to manage the city''s taxes.'),
('string/en/city/city.stf', 105, 'city_register', 'Register City'),
('string/en/city/city.stf', 106, 'city_unregister', 'Unregister City'),
('string/en/city/city.stf', 107, 'register_t', 'Register City'),
('string/en/city/city.stf', 108, 'unregister_t', 'Unregister City'),
('string/en/city/city.stf', 109, 'register_d', 'A registered city shows up on the planetary map.  The civic structures in the city will also show up on the planetary map and with the /find command.  Registering your city will increase weekly city maintenance by 5000 credits.  Are you sure you want to register your city?'),
('string/en/city/city.stf', 110, 'unregister_d', 'Unregistering your city will remove the city structures from the planetary map.  Are you sure you want to do this?'),
('string/en/city/city.stf', 111, 'cant_register', 'You lack the ability to register your city!'),
('string/en/city/city.stf', 112, 'cant_militia', 'You lack the skill to manage the city militia.'),
('string/en/city/city.stf', 113, 'rank_req', 'The city must be at least rank %DI (%TO) in order for you to place this structure.'),
('string/en/city/city.stf', 114, 'city_rank', 'City Advancement'),
('string/en/city/city.stf', 115, 'rank1', 'Outpost'),
('string/en/city/city.stf', 116, 'rank2', 'Village'),
('string/en/city/city.stf', 117, 'rank3', 'Township'),
('string/en/city/city.stf', 118, 'rank4', 'City'),
('string/en/city/city.stf', 119, 'rank5', 'Metropolis'),
('string/en/city/city.stf', 120, 'structure_invalid_subject', 'City Can''t Support Structure!'),
('string/en/city/city.stf', 121, 'structure_invalid_body', 'Mayor %TO,\n\nThe structure "%TT" cannot be supported by the current city rank!  This structure will be removed from the city in one week unless the city''s rank increases to the level necessary to support it.  You must either raise the city''s population or redeed the structure to save it.\n'),
('string/en/city/city.stf', 122, 'structure_valid_subject', 'Structure Support Reestablished!'),
('string/en/city/city.stf', 123, 'structure_valid_body', 'Mayor %TO,\n\nYour city''s rank has grown such that the structure "%TT" is no longer in danger of being removed.\n'),
('string/en/city/city.stf', 124, 'structure_destroyed_subject', 'Structure Removed!'),
('string/en/city/city.stf', 125, 'structure_destroyed_body', 'Mayor %TO,\n\nYour city''s size and rank is insufficient to support the structure (or object) "%TT" so it has been removed.\n\n'),
('string/en/city/city.stf', 126, 'structure_destroyed_radius_body', 'Mayor %TO,\n\nDue to the fact that your city has been reduced in radius, the structure "%TT" has been removed.  This structure was outside the new radius.'),
('string/en/city/city.stf', 127, 'structure_damaged_body', 'Mayor %TT,\n\nThere was insufficient money to pay for the maintenance of the structure %TO.  The amount required was %DI credits.  The structure has been damaged.  You can check the structure''s condition in the structure report at the City Management terminal.'),
('string/en/city/city.stf', 128, 'structure_damaged_subject', 'Insufficient Maintenance, Structure Damaged'),
('string/en/city/city.stf', 129, 'structure_destroyed_maint_subject', 'Insufficient Maintenance, Structure DESTROYED'),
('string/en/city/city.stf', 130, 'structure_destroyed_maint_body', 'Alert Mayor %TO!\n\nThe structure (or object) %TT was condemned and destroyed due to lack of maintenance!\n'),
('string/en/city/city.stf', 131, 'city_maint_subject', 'City Maintenance Paid'),
('string/en/city/city.stf', 132, 'city_maint_body', 'Mayor %TO,\n\nA total of %DI credits has been paid from the city treasury for maintenance and upkeep of structures.'),
('string/en/city/city.stf', 133, 'structure_repaired_subject', 'Structure Repaired'),
('string/en/city/city.stf', 134, 'structure_repaired_body', 'Mayor %TO,\n\nRepair work has been done on structure %TT.  You can check the structure''s condition in the structure report at the City Management terminal.'),
('string/en/city/city.stf', 135, 'income_tax_paid_subject', 'City Income Tax Paid'),
('string/en/city/city.stf', 136, 'income_tax_paid_body', 'Citizen %TO,\n\nYour income tax of %DI credits has been paid.  Thank you for your service to the city.\n'),
('string/en/city/city.stf', 137, 'income_tax_nopay_subject', 'Failed to Pay Income Tax!'),
('string/en/city/city.stf', 138, 'income_tax_nopay_body', 'Citizen %TO,\n\nYou have insufficient funds to pay your income tax of %DI credits.  While there is no direct drawback to this, the mayor has been notified of your lapse.\n'),
('string/en/city/city.stf', 139, 'income_tax_nopay_mayor_subject', 'Citizen Failed to Pay Income Tax'),
('string/en/city/city.stf', 140, 'income_tax_nopay_mayor_body', 'Mayor,\n\nThis letter is to notify you that the citizen named, %TO, failed to pay %PO income tax on time.\n\nCivic Tax Authority'),
('string/en/city/city.stf', 141, 'rights_granted', 'You have been granted zoning rights in the city of %TO for 24 hours.'),
('string/en/city/city.stf', 142, 'rights_granted_self', 'You have granted %TO zoning rights for 24 hours.'),
('string/en/city/city.stf', 143, 'job_n', 'Install Mission Terminal'),
('string/en/city/city.stf', 144, 'job_d', 'Select a mission terminal type from the list below.  The mission terminal will be placed at your current location and rotation (facing).  If you want to remove the mission terminal in the future, select the "Remove" option from the terminal''s radial menu.  Placing a mission terminal will cost 1000 credits, withdrawn from the treasury at the time of placement.'),
('string/en/city/city.stf', 145, 'mt_generic', 'General Missions'),
