('string/en/city/city.stf', 199, 'no_rank_spec', 'Your city must be at least rank 3 before you can set a specialization.'),
('string/en/city/city.stf', 200, 'no_specs', 'You need to learn a specialization skill before you can select one for your city.'),
('string/en/city/city.stf', 201, 'city_specs_t', 'City Specialization'),
('string/en/city/city.stf', 202, 'city_specs_d', 'At rank 3, a city can select an area of specialization (spec).  A spec grants a certain set of bonuses that apply within the city borders in exchange for increased weekly maintenance.  New spec types are earned through the Politician profession.  The city''s spec can only be set once per week, although it can be disabled at any time.  Select a spec from the list below to learn more about it.  When a spec is selected, the weekly city hall maintenance fee will increase by the indicated amount.'),
('string/en/city/city.stf', 203, 'city_spec_sample_rich', 'Sample Rich'),
('string/en/city/city.stf', 204, 'city_spec_farming', 'Farming Community'),
('string/en/city/city.stf', 205, 'city_spec_industry', 'Manufacturing Center'),
('string/en/city/city.stf', 206, 'city_spec_research', 'Research Center'),
('string/en/city/city.stf', 207, 'city_spec_cloning', 'Clone Lab'),
('string/en/city/city.stf', 208, 'city_spec_missions', 'Improved Job Market'),
('string/en/city/city.stf', 209, 'city_spec_entertainer', 'Entertainment District'),
('string/en/city/city.stf', 210, 'city_spec_doctor', 'Medical Center'),
('string/en/city/city.stf', 211, 'city_spec_stronghold', 'Stronghold'),
('string/en/city/city.stf', 212, 'city_spec_cloning_d', 'The cost of clone insurance in a city with the ''Clone Lab'' specialization is reduced by 20%.'),
('string/en/city/city.stf', 213, 'city_spec_doctor_d', 'Medical healing is 10% more effective in a ''Medical Center''.'),
('string/en/city/city.stf', 214, 'city_spec_entertainer_d', 'Entertainer healing is 10% more effective in an ''Entertainment District''.'),
('string/en/city/city.stf', 215, 'city_spec_farming_d', 'This spec isn''t implemented yet.'),
('string/en/city/city.stf', 216, 'city_spec_industry_d', 'Crafting done in a ''Manufacturing Center'' earns a 10% bonus to prototype assembly results, significantly reducing the chance of failures.'),
('string/en/city/city.stf', 217, 'city_spec_sample_rich_d', 'A sample rich city has a lot of highly accessable surface resources for manual collection.  The sample rich city bestows a 20% bonus to sample sizes and a 10% bonus to extraction skill checks during resource collection using a survey tool.'),
('string/en/city/city.stf', 218, 'city_spec_missions_d', 'Missions taken in a city with an ''Improved Job Market'' grant a 15% increase to their rewards.'),
('string/en/city/city.stf', 219, 'city_spec_research_d', 'Any experimentation done within a ''Research Center'' is enhanced.  A 15% bonus to the final result roll is added during the experimentation phase of crafting.'),
('string/en/city/city.stf', 220, 'city_spec_stronghold_d', 'A ''Stronghold'' has trained its militia members to the peak of their abilities in the methods of tactical defense.  Militia members in a ''Stronghold'' get a 50 point bonus to all defense rolls against other players.'),
('string/en/city/city.stf', 221, 'confirm_spec_t', 'Confirm Specialization'),
('string/en/city/city.stf', 222, 'confirm_spec_d', '\\#pconstrast1 Are you sure you want to set this city specialization?\\#'),
('string/en/city/city.stf', 223, 'null', 'None'),
('string/en/city/city.stf', 224, 'spec_set', 'The city''s specialization has been set to %TO.'),
('string/en/city/city.stf', 225, 'null_d', 'The city''s specialization may be removed at any time, but you won''t be able to set a new specialization until the timer restriction has expired.  Are you sure you want to remove your city''s specialization?'),
('string/en/city/city.stf', 226, 'spec_time', 'You can''t set another city spec right now.  Time Remaining: %TO'),
('string/en/city/city.stf', 228, 'rank0', 'New City'),
('string/en/city/city.stf', 229, 'action_no_money', 'The city treasury must have %DI credits in order to perform that action.'),
('string/en/city/city.stf', 230, 'mt_rebel', 'Rebel Missions'),
('string/en/city/city.stf', 231, 'mt_imperial', 'Imperial Missions'),
('string/en/city/city.stf', 232, 'no_factional', 'You must have Martial Policy IV: Faction to place faction aligned mission terminals.'),
('string/en/city/city.stf', 233, 'added_militia_target', 'You have been added to the city militia.'),
('string/en/city/city.stf', 234, 'removed_militia_target', 'You have been removed from the city militia.'),
('string/en/city/city.stf', 235, 'mayor_residence_change', 'As a city Mayor, your residence is always the city hall of the city in which you are mayor.  You cannot declare a new residence.'),
('string/en/city/city.stf', 236, 'city_warning', '%TT has been warned and will be attackable in 2 minutes.'),
('string/en/city/city.stf', 237, 'city_warning_target', 'You have been warned to leave the city!  You will be attackable by the militia in 2 minutes!'),
('string/en/city/city.stf', 238, 'garage_banned', 'You are city banned and cannot use this garage. '),
('string/en/city/city.stf', 239, 'registered', 'Your city is now registered on the planetary map.  All civic and major commercial structures in the city are also registered and can be found with the /find command.'),
('string/en/city/city.stf', 240, 'unregistered', 'Your city is no longer registered on the planetary map.'),
('string/en/city/city.stf', 241, 'zone', 'Enable Zoning'),
('string/en/city/city.stf', 242, 'unzone', 'Disable Zoning'),
('string/en/city/city.stf', 243, 'zoning_enabled', 'Your city now has zoning enabled.'),
('string/en/city/city.stf', 244, 'zoning_disabled', 'Your city now has zoning disabled.'),
('string/en/city/city.stf', 245, 'zoning_skill', 'You must be a Politician to enable city zoning.'),
('string/en/city/city.stf', 246, 'zoning_t', 'Zoning'),
('string/en/city/city.stf', 247, 'zoning_d', 'If you enable zoning laws in your city, other players will not be able to build structures in your city without permission.  You and your militia can grant permission with the /grantZoningRights command.  This command gives the target the right to build structures in your city for 24 hours.'),
('string/en/city/city.stf', 248, 'grant_rights_fail', 'You must be the mayor of the city or a member of the city militia to grant zoning rights.'),
('string/en/city/city.stf', 249, 'already_mayor', 'You are already the mayor of a city.  You may not be mayor of another city.'),
('string/en/city/city.stf', 250, 'city_maint', 'Maintenance Report'),
('string/en/city/city.stf', 251, 'maint_info_t', 'Maintenance Report'),
('string/en/city/city.stf', 252, 'maint_info_d', 'This report is a projection of the current maintenance costs for the city.  Maintenance is paid on a weekly basis.'),
('string/en/city/city.stf', 253, 'build_no_city', 'You must be in a city to place that structure.'),
('string/en/city/city.stf', 254, 'not_citizen_ban', 'You can''t city ban a citizen of the city!'),
('string/en/city/city.stf', 255, 'rights_revoked', 'You have revoked their zoning rights.'),
('string/en/city/city.stf', 256, 'rights_revoked_other', 'Your zoning rights have been revoked.'),
('string/en/city/city.stf', 257, 'rank_info_t', 'City Rank Info'),
('string/en/city/city.stf', 258, 'rank_info_d', 'The following report shows the current city rank, the current city population, the abilities of the city and the population required for the next rank.  If you have met your rank requirement, the city will advance in rank during the next city update.  Check the maintenance report for a projected time to the next update.'),
('string/en/city/city.stf', 259, 'force_update', 'Force City Update or Election'),
('string/en/city/city.stf', 260, 'withdraw_limits', 'You may only withdraw between 10,000 and 50,000 credits per day.'),
('string/en/city/city.stf', 261, 'withdraw_daily', 'You may only withdraw from the city treasury once per day.'),
('string/en/city/city.stf', 262, 'withdraw_reason_t', 'Reason for Withdraw'),
('string/en/city/city.stf', 263, 'withdraw_reason_d', 'Enter the reason for the withdraw.  The citizenship will be notified of the withdraw amount and the reason for the withdraw.'),
('string/en/city/city.stf', 264, 'treasury_withdraw_from', 'City Treasury Authority'),
('string/en/city/city.stf', 265, 'treasury_withdraw_subject', 'City Treasury Withdrawal'),
('string/en/city/city.stf', 266, 'treasury_withdraw_body', 'Attention!\n\nMayor %TO has made a withdrawal from the City Treasury.\n\nAmount: %DI\nReason: %TT\n\n- Treasury Authority'),
('string/en/city/city.stf', 267, 'st_fail', 'Failed to create the skill trainer for some reason.  Try again.'),
('string/en/city/city.stf', 268, 'city_expand_subject', 'City Expansion!'),
('string/en/city/city.stf', 269, 'city_expand_body', 'Congratulations!\n\nThe city of %TO has expanded to rank %DI!  New abilities for your city have been unlocked.  Please check the city advancement report for details.'),
('string/en/city/city.stf', 270, 'city_contract_subject', 'City Contraction!'),
('string/en/city/city.stf', 271, 'city_contract_body', 'Warning!\n\nThe city of %TO has contracted to rank %DI due to lack of population.  Some of your civic structures may have been destroyed.  Please check the city manage terminal report menus and your email for more information.'),
('string/en/city/city.stf', 272, 'west', 'West'),
('string/en/city/city.stf', 273, 'civic_only', 'You may only do that outside or in a civic structure.'),
('string/en/city/city.stf', 274, 'no_shuttleport', 'You can''t place a travel fee.  There is no shuttleport in this city.'),
('string/en/city/city.stf', 275, 'lost_city_citizen_subject', 'Lost Citizen!'),
('string/en/city/city.stf', 276, 'lost_city_citizen_body', 'A citizen has left your city.\n\nCitizen Name: %TO'),
('string/en/city/city.stf', 277, 'city_hacks', 'City Hacks (GODMODE ONLY)'),
('string/en/city/city.stf', 278, 'rank_up', 'Force Rank Up'),
('string/en/city/city.stf', 279, 'rank_down', 'Force Rank Down'),
('string/en/city/city.stf', 280, 'city_invalid_subject', 'Zoning Permits Invalid!'),
('string/en/city/city.stf', 281, 'city_invalid_body', 'Warning!  Your city has fallen below the minimum count of 10 citizens.  Your city zoning permits are being reviewed by the Planetary Civic Authority.  You must have 10 or more citizens in your city within 3 days or your permits will be rejected and your city hall destroyed!\n\nAs a result of the lack of population your city has contracted to rank %DI (Outpost).'),
('string/en/city/city.stf', 282, 'tax_income_subject', 'Income Tax Changed'),
('string/en/city/city.stf', 283, 'tax_property_subject', 'Property Tax Changed'),
('string/en/city/city.stf', 284, 'tax_travel_subject', 'Travel Fee Changed'),
('string/en/city/city.stf', 285, 'tax_sales_subject', 'Sales Tax Changed'),
('string/en/city/city.stf', 286, 'tax_travel_body', 'The travel free for the city of %TO has changed to %DI credits in additon to the normal ticket price.'),
('string/en/city/city.stf', 287, 'tax_property_body', 'The property maintenance tax for the city of %TO has changed to %DI%.'),
('string/en/city/city.stf', 288, 'tax_income_body', 'The weekly citizen income tax for the city of %TO has changed to %DI credits.'),
('string/en/city/city.stf', 289, 'tax_sales_body', 'The vendor sales tax for the city of %TO has changed to %DI%.'),
('string/en/city/city.stf', 290, 'st_politician', 'Politician (Trainer)'),
('string/en/city/city.stf', 291, 'public_election_subject', 'Election Results!'),
('string/en/city/city.stf', 292, 'public_election_body', 'The city elections for %TT have been held.  The incumbent Mayor has lost the election!  The new Mayor is citizen %TO.  Please congratulate the new Mayor!\n'),
('string/en/city/city.stf', 293, 'public_election_inc_subject', 'Election Results!'),
('string/en/city/city.stf', 294, 'public_election_inc_body', 'The city elections for %TT have been held.  The incumbent Mayor is victorious!  Please congratulate Mayor %TO on retaining their office.'),
('string/en/city/city.stf', 295, 'fix_mayor', 'Restore Mayor Citizenship'),
('string/en/city/city.stf', 296, 'city_update_eta', 'Next City Update: %TO'),
('string/en/city/city.stf', 297, 'city_spec_master_manufacturing', 'Industrial Society'),
('string/en/city/city.stf', 298, 'city_spec_master_healing', 'Scientific Society'),
('string/en/city/city.stf', 299, 'city_spec_master_healing_d', 'A ''Scientific Society'' gains the bonuses of both the ''Medical Center'' and ''Entertainment District'' specializations.'),
('string/en/city/city.stf', 300, 'city_spec_master_manufacturing_d', 'An ''Industrial Society'' gains the bonuses of both the ''Manufacturing Center'' and ''Research Center'' specializations.'),
('string/en/city/city.stf', 301, 'no_rank_taxes', 'Your city must be at least rank 2 to levy taxes.'),
('string/en/city/city.stf', 302, 'cant_register_rank', 'Your city must be rank 3 (Township) to be registered on the planetary map.'),
('string/en/city/city.stf', 303, 'civic_count', 'A city of this size can only support up to %DI civic structures.'),
('string/en/city/city.stf', 304, 'busted_civic_cap_subject', 'Over Civic Structure Cap!!!'),
('string/en/city/city.stf', 305, 'busted_civic_cap_body', 'Warning!\n\n%TO has %DI more civic (city owned) structures than planetary policy allows for your city rank.  The Planetary Civic Authority is now charging your city a 75,000 credit property penalty for each structure over the cap.  Civic structures such as gardens, cloning facilities, and shuttleports contribute to this cap.  Please check the city terminal maintenance report for more information.  The penalty will be charged during your next maintenance period, unless the structures are removed.\n\n- Planetary Civic Authority'),
('string/en/city/city.stf', 306, 'city_expand_cap_subject', 'City Expansion Capped!'),
('string/en/city/city.stf', 307, 'city_expand_cap_body', 'Your city %TO has qualified to increase to rank %DI.\n\nUnfortunately, we must deny your rank and land expansion request as there are too many large cities already on the planet.\n\n- Planetary Civic Authority\n\n'),
('string/en/city/city.stf', 308, 'make_mayor', 'Make Mayor'),
('string/en/city/city.stf', 309, 'make_mayor_t', 'Make Mayor'),
('string/en/city/city.stf', 310, 'make_mayor_d', 'Enter the EXACT first and last name of the character you wish to make mayor of this city.  The current mayor, if any, will be removed from office.  The person you select MUST be a citizen of the city and a politician in order to become mayor.'),
('string/en/city/city.stf', 311, 'already_warned', 'That player has already been warned in the last two minutes.'),
('string/en/city/city.stf', 312, 'reset_clone_data', 'Reset Clone Data'),
('string/en/city/city.stf', 313, 'reset_shuttle_data', 'Reset Shuttle Data'),
('string/en/city/city.stf', 314, 'modify_structure_list', 'Modify Structure List'),
('string/en/city/city.stf', 315, 'no_clone_data', 'There is no clone data to remove.'),
('string/en/city/city.stf', 316, 'clone_data_wiped', 'This city''s clone data has been wiped.  You may now place a new clone facility.'),
('string/en/city/city.stf', 317, 'shuttle_data_wiped', 'This city''s travel data has been wiped.  You may now place a new shuttleport.'),
('string/en/city/city.stf', 318, 'lost_inactive_citizen_subject', 'Lost Inactive Citizen!'),
('string/en/city/city.stf', 319, 'lost_inactive_citizen_body', 'A citizen has been removed due to six weeks inactivity.  If they return, they can rejoin the city by redeclaring at their residence.\n\nCitizen Name: %TO'),
('string/en/city/city.stf', 320, 'revoke_citizenship', 'Revoke Citizenship'),
('string/en/city/city.stf', 321, 'revoke_cit_d', 'Are you sure you want to revoke your citizenship?'),
('string/en/city/city.stf', 322, 'revoke_cit_t', 'Revoke Citizenship'),
('string/en/city/city.stf', 323, 'lost_citizen_subject', 'Lost Citizen!'),
('string/en/city/city.stf', 324, 'lost_citizen_body', 'A citizen has left your city by using the revoke option on the city terminal.\n\nCitizen Name: %TO'),
('string/en/city/city.stf', 325, 'not_csr_ban', 'You cannot ban a Customer Service Representative from the city!'),
('string/en/city/city.stf', 326, 'csr_ban_attempt_msg', '%TT tried to /cityBan you from %TO!'),
('string/en/city/city.stf', 327, 'garage_fee_body', 'The garage usage fee for  the city of %TO has changed to %DI.'),
('string/en/city/city.stf', 328, 'garage_fee_subject', 'Garage Fee Changed'),
('string/en/city/city.stf', 329, 'garage_tax', 'Garage Service Fee'),
('string/en/city/city.stf', 330, 'set_tax_d_garage', 'The garage tax is a service fee added to the total cost of repair for a vehicle.  If vehicle repairs would cost the owner 100cr, the total would be 110cr if the fee was 10%.  Garage tax can be between 0 and 30%.'),
('string/en/city/city.stf', 331, 'set_garage_tax', 'The garage service fee is now %DI% of the repair cost.'),
('string/en/city/city.stf', 332, 'st_bioengineer', 'Bio-Engineer (Trainer)'),
('string/en/city/city.stf', 333, 'city_cant_board', 'You are banned from using the services of this city.\\nYou may not board the transport.'),
('string/en/city/city.stf', 334, 'city_cant_purchase_ticket', 'You are banned from using the services of this city.\\nYou cannot purchase a ticket.'),
('string/en/city/city.stf', 335, 'cant_transfer_to_city_banned', 'You cannot transfer ownership of a structure to someone who is banned from the city in which the structure resides.'),
('string/en/city/city.stf', 336, 'banned_from_that_city', 'You have been banned from traveling to that city by the city militia.'),
('string/en/city/city.stf', 337, 'city_version_update_body_3', 'City Voting Rules Update\n\nThe system for electing a new mayor has changed. Voting is now held every 3 weeks. City maintainence still occurs every week. A citizen who registers to run may now unregister from the vote terminal. The mayor may unregister as well. Changes to the voting roster are only allowed during the first two weeks of each election cycle. The citizen with the most votes wins the election.\n\nYou MUST explicitly cast a vote in order to be counted. Abstentions no longer count as votes for the incumbent.\n\nExperience point grants for winning votes have been tripled. The incumbent mayor also receives a weekly 750 point experience bonus.'),
('string/en/city/city.stf', 338, 'city_version_update_subject_3', 'City Voting Rules Update'),
('string/en/city/city.stf', 339, 'mayoral_unregister', 'Unregister from Race'),
('string/en/city/city.stf', 340, 'not_registered', 'You aren''t registered to run, so you can''t unregister.'),
('string/en/city/city.stf', 341, 'unregistered_race', 'You have unregistered from the mayoral race.'),
('string/en/city/city.stf', 342, 'vote_abstain', 'You have chosen to abstain in this election.'),
('string/en/city/city.stf', 343, 'register_timestamp', 'You may only register to run once within a 24 hour period.'),
('string/en/city/city.stf', 344, 'registered_citizen_email_subject', 'New Mayoral Challenger!'),
('string/en/city/city.stf', 345, 'rceb', '%TO has entered the race for mayor. You can now vote for this candidate at the city voting terminal.'),
('string/en/city/city.stf', 346, 'unregistered_citizen_email_subject', 'Candidate exited the race!'),
('string/en/city/city.stf', 347, 'unregistered_citizen_email_body', '%TO has dropped from the mayoral election. All previous votes for this candidate are now disregarded and should be recast.'),
('string/en/city/city.stf', 348, 'registration_locked', 'The ballot is locked during the final week of voting.\nYou may not register or unregister for the race at this time.'),
('string/en/city/city.stf', 349, 'reset_voting', 'GOD MODE: Reset Voting'),
('string/en/city/city.stf', 350, 'mayor_citizen_restored', 'Restored citizenship to valid city mayor.'),
('string/en/city/city.stf', 351, 'force_election_only', 'Do you only want to force an election?'),
('string/en/city/city.stf', 352, 'force_city_update_t', 'Force City Update'),
('string/en/city/city.stf', 353, 'confirm_city_update', 'Are you sure you want to force an immediate city update?  This will cause the city to elect a new mayor, pay maintenance, validate structures, and check to see if a new rank has been earned.'),
('string/en/city/city.stf', 354, 'confirm_disable_cleanup', 'Do you want to disable the citizen cleanup code?  You probably want to say YES.  This cleanup code should normally only run once a week.'),
('string/en/city/city.stf', 355, 'disable_cleanup_t', 'Disable Cleanup Code?'),
('string/en/city/city.stf', 356, 'force_city_election', 'Forcing a city update for city %TO.'),
('string/en/city/city.stf', 357, 'force_city_update', 'Forcing a city update for city %TO.'),
('string/en/city/city.stf', 358, 'force_city_rank_d', 'Are you sure you want to force an immediate city rank change?  This will cause the city rank to change, but in the case of an increase your city may not have the citizens to support the new rank.  In this case the city rank will FALL the next city update.'),
('string/en/city/city.stf', 359, 'force_city_rank_t', 'Force City Rank'),
('string/en/city/city.stf', 360, 'force_city_rank', 'Forcing a city rank change for city %TO.'),
('string/en/city/city.stf', 361, 'not_politician', 'That citizen is not a politician.'),
('string/en/city/city.stf', 362, 'already_other_mayor', 'That citizen is already the mayor of some other city.'),
('string/en/city/city.stf', 363, 'mayor_confirm', 'They are now the mayor.'),
('string/en/city/city.stf', 364, 'cannot_find_citizen', 'Unable to find that citizen.'),
('string/en/city/city.stf', 365, 'reset_clone_data_d', 'Are you sure you want to reset this city''s clone data?  You should ONLY do this if the clone facility has disappeared for some reason, but the city still claims to have one.  You should not do this if the city already has a clone facility!'),
('string/en/city/city.stf', 366, 'reset_clone_data_t', 'Reset Clone Data'),
('string/en/city/city.stf', 367, 'reset_shuttle_data_d', 'Are you sure you want to reset this city''s shuttle/travel data?  You should ONLY do this if the shuttleport has disappeared for some reason, but the city still claims to have one.  You should not do this if the city already has a working shuttleport!'),
('string/en/city/city.stf', 368, 'reset_shuttle_data_t', 'Reset Shuttle Data'),
('string/en/city/city.stf', 369, 'no_special_objects', 'There aren''t any special objects to manage.'),
('string/en/city/city.stf', 370, 'city_object_list_d', 'A list of special city objects follows.  If an item on this list does not have a name shown, it is either unloaded or deleted.  You can select an object from the list and hit ''OK'' to delete it.  Use this to clean up objects that have become destroyed but the city still thinks exist.'),
('string/en/city/city.stf', 371, 'city_object_list_t', 'City Object List'),
('string/en/city/city.stf', 372, 'destory_object', '%TO has been removed from the city db and the object destroy message has been sent.'),
('string/en/city/city.stf', 373, 'destroy_city_object', 'Are you sure you want to destroy %DI?  The object''s city DB entry will be removed and the object (if it exists) will be destroyed.'),
