('string/en/clientpoi_n.stf', 223, 'tatooine_k', 'POI: Pirate''s (Muon) Gold'),
('string/en/clientpoi_n.stf', 224, 'space_corellia_4', 'Hyperspace: Talus Secta'),
('string/en/clientpoi_n.stf', 225, 'yavin4_e', 'POI: Nova 3'),
('string/en/clientpoi_n.stf', 226, 'yavin4_f', 'POI: Lodestar Utopia'),
('string/en/clientpoi_n.stf', 227, 'lok_g', 'POI: Crimson Talon'),
('string/en/clientpoi_n.stf', 228, 'lok_h', 'POI: Umber Scale'),
('string/en/clientpoi_n.stf', 229, 'lok_i', 'POI: Trade Federation Center'),
('string/en/clientpoi_n.stf', 230, 'lok_j', 'POI: Corsairian Crescent'),
('string/en/clientpoi_n.stf', 231, 'lok_k', 'POI: Bloodlight Sea'),
('string/en/clientpoi_n.stf', 232, 'lok_l', 'POI: Solar Phoenix 2'),
('string/en/clientpoi_n.stf', 233, 'lok_m', 'POI: Mercenaries'' Ridge'),
('string/en/cmd_d.stf', 1, 'access_fee', 'This ability allows you to place an access fee on any public building you own.  Entry to a building with an access fee set is restricted to players who have paid the fee.'),
('string/en/cmd_d.stf', 2, 'accuse', '/accuse: You point accusingly at everyone else.\n/accuse self: Have you been bad? Tsk, tsk.\n/accuse target: You point accusingly at (target name).'),
('string/en/cmd_d.stf', 3, 'ache', '/ache: You ache all over.\n/ache self: Eat something bad? Your stomach grumbles and aches.\n/ache target: You let (target name) know that your body aches for (him, her, or it).'),
('string/en/cmd_d.stf', 4, 'actionshot1', '/actionshot1 <target>: This ranged attack can wreak havoc with a target''s Action pool drain and regeneration rates.'),
('string/en/cmd_d.stf', 5, 'actionshot2', '/actionshot2 <target>: This area ranged attack can wreak havoc with a target''s Action pool drain and regeneration rates.  This is more powerful than Action Shot 1.'),
('string/en/cmd_d.stf', 6, 'activateclone', 'This command is used to activate a clone and send the user to the nearest Cloning Facility after death.'),
('string/en/cmd_d.stf', 7, 'ad_fees_1', 'The merchant gains a reduction in the cost of maintaining a vendor registered on the planetary map.'),
('string/en/cmd_d.stf', 8, 'adjust', '/adjust: You adjust your outfit. There you go. Perfect!\n/adjust self: You tighten down your gear and get ready for action.\n/adjust target: You adjust (target name)''s outfit for (him, her, or it).'),
('string/en/cmd_d.stf', 9, 'adn', '/adn: You openly show that your patience has expired.\n/adn self: A bit frustrated with yourself?\n/adn target: You encourage (target name) to hurry. Any day now!'),
('string/en/cmd_d.stf', 10, 'afk', '/afk: You notify everyone around you that you are going AFK. Hurry back, now!\n/afk self: OK... You are really AFK now.\n/afk target: You point out that (target name) is AFK.'),
('string/en/cmd_d.stf', 11, 'afk4drink', '/afk4drink: We''ll be waiting! You announce you are AFK to get a drink.\n/afk4drink self: You let everyone know that you will be going to grab a drink next break.\n/afk4drink target: You remind everyone that (target name) went AFK to go get a beverage.'),
('string/en/cmd_d.stf', 12, 'afk4food', '/afk4food: Your stomach will thank you.  You announce you are AFK to grab a bite.\n/afk4food self: You announce that you will be AFK to grab some food at the next break in the action.\n/afk4food target: You let everyone know that (target name) went AFK to find sustenance.'),
('string/en/cmd_d.stf', 13, 'agree', '/agree: You nod in agreement.\n/agree self: You agree with yourself.\n/agree target: You agree with (target name).'),
('string/en/cmd_d.stf', 14, 'aim', '/aim: This combat move allows you to give up an attack round in order to gain better accuracy on your next ranged attack.'),
('string/en/cmd_d.stf', 15, 'airguitar', '/airguiter: You rock the crowd.\n/airguiter self: You rock out.\n/airguiter target: You rock out for (target name).'),
('string/en/cmd_d.stf', 16, 'alert', 'This command utilizes the alert ability.'),
('string/en/cmd_d.stf', 17, 'amaze', '/amaze: That was amazing! How did they do that?\n/amaze self: You amaze yourself!\n/amaze target: You try to amaze (target name) with a magic trick.'),
('string/en/cmd_d.stf', 18, 'amazing', '/amazing'),
('string/en/cmd_d.stf', 19, 'animalattack', '/animalAttack <target>: This ability allows a Jedi to enter the mind of his or her look-at target and cause it to attack the current combat target. Note that this ability will only work on creatures.'),
('string/en/cmd_d.stf', 20, 'animalcalm', '/animalCalm <target>: This ability will cause a target that is in combat to stop attacking, returning to its normal peaceful state. Note that this ability will only work on creatures.'),
('string/en/cmd_d.stf', 21, 'animalscare', '/animalScare <target>: This ability allows a Jedi to enter the mind of the target and fill it with unease, scaring the target away. Note that this ability will only work on creatures.'),
('string/en/cmd_d.stf', 22, 'anon', 'This command allows the user to go anonymous.'),
('string/en/cmd_d.stf', 23, 'anxious', '/anxious: You feel anxious.\n/anxious self: You look around anxiously.\n/anxious target: You look anxiously at (target name).'),
('string/en/cmd_d.stf', 24, 'apologize', '/apologize: OOPS!! Sorry everyone!!\n/apologize self: You apologize to yourself. But, what good is that going to do unless you forgive yourself too?\n/apologize target: You apologize to (target name) and beg (his, her, or its) forgiveness.'),
('string/en/cmd_d.stf', 25, 'applaud', '/applaud: You give a hearty round of applause.\n/applaud self: You give yourself a hand. Go ahead, you deserve it!\n/applaud target: Bravo! Bravo! You give (target name) an ovation.'),
('string/en/cmd_d.stf', 26, 'applydisease', '/applydisease <target>: This command will enable you to attack your target with disease, if you have the proper item.'),
('string/en/cmd_d.stf', 27, 'applypoison', '/applypoison <target>: This command will enable you to attack your target with poison, if you have the proper item.'),
('string/en/cmd_d.stf', 28, 'arch', '/arch: You arch your back like a cat.\n/arch self: You arch your back in an effort to work the kinks out. SNAP! CRACK! POP!\n/arch target: You arch your back seductively for (target name).'),
('string/en/cmd_d.stf', 29, 'areatrack', '/areatrack: Gives the Ranger the ability to study tracking clues in the area to figure out what kind of creatures or people have been in the region recently.'),
('string/en/cmd_d.stf', 30, 'areatrack_animal', 'Gives the Ranger the ability to scan animal activity using the /areatrack command.'),
('string/en/cmd_d.stf', 31, 'areatrack_direction', 'Gives the Ranger the ability to judge the approximate direction of a target using /areatrack.'),
('string/en/cmd_d.stf', 32, 'areatrack_distance', 'Gives the Ranger the ability to judge the approximate distance of targets in the area using /areatrack.'),
('string/en/cmd_d.stf', 33, 'areatrack_npc', 'Enhances the Ranger''s tracking skills to hunt down non-player characters.'),
('string/en/cmd_d.stf', 34, 'areatrack_player', 'Gives the Ranger the ability to track players using /areatrack.'),
('string/en/cmd_d.stf', 35, 'assist', '/assist <name>: Assist lets you immediately Combat Target somebody else''s current target.'),
('string/en/cmd_d.stf', 36, 'associatedroidcontroldevicewithship', 'Associate a droid with a ship, so that it''s loaded in your ship when you launch into space.'),
('string/en/cmd_d.stf', 37, 'astromech_droid_cert_1', 'This certification allows you to equip an Astromech with a level 1 data storage module, or a v1 Flight Computer, on your starship.'),
('string/en/cmd_d.stf', 38, 'astromech_droid_cert_2', 'This certification allows you to equip an Astromech with a level 2 data storage module, or a v2 Flight Computer, on your starship.'),
('string/en/cmd_d.stf', 39, 'astromech_droid_cert_3', 'This certification allows you to equip an Astromech with a level 3 data storage module, or a v3 Flight Computer, on your starship.'),
('string/en/cmd_d.stf', 40, 'astromech_droid_cert_4', 'This certification allows you to equip an Astromech with a level 4 datastorage module, or a v4 Flight Computer, on your starship.'),
('string/en/cmd_d.stf', 41, 'astromech_droid_cert_5', 'This certification allows you to equip an Astromech with a level 5 data storage module, or a v5 Flight Computer, on your starship.'),
('string/en/cmd_d.stf', 42, 'astromech_droid_cert_6', 'This certification allows you to equip an Astromech with a level 6 data storage module, or a v6 Flight Computer, on your starship.'),
('string/en/cmd_d.stf', 43, 'attack', '/attack: This initiates combat against your current target.'),
('string/en/cmd_d.stf', 44, 'attend', '/attend: You listen hard.\n/attend self: You listen to something only you can hear.\n/attend target: You listen to (target name).'),
('string/en/cmd_d.stf', 45, 'avoidincapacitation', '/avoidIncapacitation: This ability allows a Jedi to prevent themselves from going into an unconscious state.  This power only lasts for a short time and can quickly deplete a Jedi of Force power if they try to remain conscious for a lengthy period of time.'),
('string/en/cmd_d.stf', 46, 'ayt', '/ayt: You try to figure out who is AFK and who is not.\n/ayt self: I don''t know.  Are you really here?\n/ayt target: Hello? (target name)? Well, it seems (his, her, or its) lights are on, but is anyone home?'),
('string/en/cmd_d.stf', 47, 'backhand', '/backhand: You raise your hand as if to backhand slap someone.\n/backhand self: You backhand slap your other palm, emphasizing your point.\n/backhand target: You slap (him, her, or it) in the face with a swift backhand.'),
('string/en/cmd_d.stf', 48, 'bad', '/bad: Uh. What just went horribly wrong?\n/bad self: Just how bad have you been?\n/bad target: You make it obvious that you think (target name) has been bad.'),
('string/en/cmd_d.stf', 49, 'badfeeling', '/badfeeling: You have a bad feeling about this...\n/badfeeling self: You start to express your bad feeling and think better of it.\n/badfeeling target: You signal to (him, her, or it) that you have a bad feeling about this...'),
('string/en/cmd_d.stf', 50, 'bah', '/bah: BAH!\n/bah self: You take one look at your surroundings and think aloud, "BAH!"\n/bah target: You look (target name) up and down and utter, "BAH!"'),
('string/en/cmd_d.stf', 51, 'bak', '/bak: You let everyone know that you are back at your keyboard.\n/bak self: You smile contentedly as you realize you are back to your old self again!\n/bak target: You wish that (target name) would come back to (his, her, or its) keyboard.'),
('string/en/cmd_d.stf', 52, 'bandfill', 'This ability allows you to plays songs with the Bandfill instrument.'),
('string/en/cmd_d.stf', 53, 'bang', '/bang: You bang your head to the music.\n/bang self: You bang your head against the wall.\n/bang target: You bang (target name)''s head against the wall.'),
('string/en/cmd_d.stf', 54, 'bark', '/bark: You get on all fours and bark like a dog.\n/bark self: You bark at yourself.\n/bark target: BARK BARK!  You bark at (target name).'),
('string/en/cmd_d.stf', 55, 'bat', '/bat: And just whom are you trying to impress?  You bat your lashes.\n/bat self: You practice batting your lashes.\n/bat target: You bat your lashes at (target name).'),
('string/en/cmd_d.stf', 56, 'batlashes', '/batlashes:  And just whom are you trying to impress?   You bat your lashes.\n/batlashes self:  You practice batting your lashes.\n/batlashes target:  You bat your lashes at (target name).'),
('string/en/cmd_d.stf', 57, 'battlefieldstatus', 'This command allows the user to view a battlefield''s status.'),
('string/en/cmd_d.stf', 58, 'bbl', '/bbl: You tell everyone you will be back later... See ya soon!\n/bbl self: Trying to have an out of body experience, are we?\n/bbl target: You let (target name) know that you will be back later.'),
('string/en/cmd_d.stf', 59, 'beam', '/beam: Feeling radiant, are we?\n/beam self: You beam at yourself.\n/beam target: You beam at (target name).'),
('string/en/cmd_d.stf', 60, 'bearhug', '/bearhug: You hold your arms out wide and look for a target to bear-hug.\n/bearhug self: You bear-hug yourself and stretch out your shoulders.\n/bearhug target: You give (target name) a great, big bear-hug that lifts (him, her, or it) off the ground.'),
('string/en/cmd_d.stf', 61, 'beckon', '/beckon: You do your best to gather everyone around you.\n/beckon self: You summon your inner strength.\n/beckon target: You motion at (target name) to come here.'),
('string/en/cmd_d.stf', 62, 'belch', '/belch: You let out a resounding belch! Feel better?\n/belch self: You try to muffle your belch.\n/belch target: You belch in (target name)''s face.'),
('string/en/cmd_d.stf', 63, 'berserk1', '/berserk1: While berserk, you cause more melee damage to your targets but get hit more often in return.'),
('string/en/cmd_d.stf', 64, 'berserk2', '/berserk2: While berserk, you cause more melee damage to your targets but get hit more often in return.  This is more powerful than Berserk 1.'),
('string/en/cmd_d.stf', 65, 'bet', 'After joining a suitable gambling station, you may target the station and use the /bet command to set your wager.'),
('string/en/cmd_d.stf', 66, 'bite', '/bite: You snap your teeth at everyone around you.\n/bite self: You bite your lip nervously.\n/bite target: You bite (target name) on the leg.'),
('string/en/cmd_d.stf', 67, 'blame', '/blame: You blame everyone else.\n/blame self: You blame yourself.\n/blame target: You blame (target name).'),
('string/en/cmd_d.stf', 68, 'bleed', '/bleed: MEDIC!!  You bleed on the ground.\n/bleed self: You bleed all over yourself and make a nice pool of blood at your feet.\n/bleed target: You bleed all over (target name).'),
('string/en/cmd_d.stf', 69, 'bleedingshot', '/bleedingshot <target>: This ranged attack is of medium power, but can cause its target to bleed.'),
('string/en/cmd_d.stf', 70, 'blindattack', 'This command utilizes the blind attack sequence.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/cmd_d.stf', 71, 'blink', '/blink: You blink.\n/blink self: You blink in disbelief.\n/blink target: You blink in disbelief at (target name).'),
('string/en/cmd_d.stf', 72, 'blow', '/blow: You pull out a string and some soapy water and proceed to blow bubbles.\n/blow self: You blow your hair out of your face.\n/blow target: You blow in (target name)''s ear.'),
('string/en/cmd_d.stf', 73, 'blowkiss', '/blowkiss: You blow kisses.\n/blowkiss self: Got it! You catch a kiss.\n/blowkiss target: You blow a kiss to (target name).'),
('string/en/cmd_d.stf', 74, 'blush', '/blush: You blush.\n/blush self: You blush in embarrassment.\n/blush target: You blush at (target name).'),
('string/en/cmd_d.stf', 75, 'bmoc', '/bmoc: You look around for the BMOC.\n/bmoc self: You are "THE MAN"!! You declare yourself BMOC.\n/bmoc target: You cast your BMOC vote for (target name).'),
('string/en/cmd_d.stf', 76, 'boardshuttle', 'This command allows the user to board a shuttle.'),
('string/en/cmd_d.stf', 77, 'bob', '/bob: You bob your head to the beat.\n/bob self: You go bobbing for apples.\n/bob target: You bob up from behind (target name).'),
('string/en/cmd_d.stf', 78, 'bodyshot1', '/bodyshot1 <target>: This ranged attack targets an opponent''s body in order to damage their Health pool.'),
('string/en/cmd_d.stf', 79, 'bodyshot2', '/bodyshot2 <target>: This advanced ranged attack targets an opponent''s body in order to damage their Health pool.  This is more powerful than Body Shot 1.'),
('string/en/cmd_d.stf', 80, 'bodyshot3', '/bodyshot3 <target>: This powerful ranged attack targets an opponent''s body in order to devastate their Health pool.  This is the most powerful Body Shot attack.'),
('string/en/cmd_d.stf', 81, 'bodyslam', '/bodyslam: Unable to find a target, you pull a stuffed animal from your pack and bodyslam it! TAKE THAT!\n/bodyslam self: You pick yourself up and throw yourself on the ground.\n/bodyslam target: You try to pick up (target name) and bodyslam (him, her, or it).'),
('string/en/cmd_d.stf', 82, 'boggle', '/boggle: You boggle at that concept.\n/boggle self: You boggle at yourself. What were you thinking?!\n/boggle target: You boggle at (target name). What did (he, she or it) just say?'),
('string/en/cmd_d.stf', 83, 'bonk', '/bonk: Bonk! bOnk! BoNk!\n/bonk self: You bonk yourself on the head. Look at all the birdies!!\n/bonk target: You bonk (target name) on the head. What were they thinking?!'),
('string/en/cmd_d.stf', 84, 'boogie', '/boogie: Get down! You boogie-woogie-oogie.\n/boogie self: You tell yourself it''s time to boogie.\n/boogie target: You tell (target name) that you are going to boogie.'),
('string/en/cmd_d.stf', 85, 'boostmorale', '/boostmorale: This very powerful Squad Leader ability allows the Squad Leader to boost the morale of their troopers by re-distributing all party wounds evently among all of its members.  This ability takes a heavy toll on the Squad Leader''s Action and Mind pools.  Use the /setboostmorale <message> command to set the message the Squad Leader shouts when this ability is used.  The Squad Leader must be the leader of the group for this to work.'),
('string/en/cmd_d.stf', 86, 'bored', '/bored: Bored!\n/bored self: You go stir-crazy from boredom.\n/bored target: You tell (target name) that you are bored of (him, her, or it).'),
('string/en/cmd_d.stf', 87, 'bounce', '/bounce: You bounce around with excitement!\n/bounce self: You try to bounce yourself off the ground.\n/bounce target: You bounce circles around (target name).'),
('string/en/cmd_d.stf', 88, 'bouquet', '/bouquet: Wow! Great trick! You pull a flower bouquet out of thin air.\n/bouquet self: You grab a flower bouquet and inhale deeply of the flowers'' smell.\n/bouquet target: Awww. How nice of you! You give a flower bouquet to (target name).'),
('string/en/cmd_d.stf', 89, 'bow', '/bow: You bow.\n/bow self: You gracefully perform a flourished bow.\n/bow target: You bow to (target name).'),
('string/en/cmd_d.stf', 90, 'bow2', '/bow2: You bow.\n/bow2 self: You gracefully perform a flourished bow.\n/bow2 target: You bow to (target name).'),
('string/en/cmd_d.stf', 91, 'bow3', '/bow3: You bow.\n/bow3 self: You gracefully perform a flourished bow.\n/bow3 target: You bow to (target name).'),
('string/en/cmd_d.stf', 92, 'bow4', '/bow4: You bow.\n/bow4 self: You gracefully perform a flourished bow.\n/bow4 target: You bow to (target name).'),
('string/en/cmd_d.stf', 93, 'bowhead', '/bowhead: You bow your head.\n/bowhead self: You bow your head and focus yourself.\n/bowhead target: You bow your head to (target name).'),
('string/en/cmd_d.stf', 94, 'brandish', '/brandish: You brandish your weapon at the general area.\n/brandish self: You look exasperated and sarcastically brandish your weapon at yourself.\n/brandish target: You brandish your weapon menacingly at (target name).'),
('string/en/cmd_d.stf', 95, 'brb', '/brb: Be Right Back!\n/brb self: You take a leave of absence from reality.\n/brb target: You tell (target name) that you will be right back.'),
('string/en/cmd_d.stf', 96, 'brt', '/brt: BRT!\n/brt self: Not much farther now!!\n/brt target: You tell (target name) to go on and that you will be right there.'),
('string/en/cmd_d.stf', 97, 'bstrike1', '/bstrike1 : This ability allows a pilot to call in a TIE Bomber strike package against their current target, assuming it is valid.'),
('string/en/cmd_d.stf', 98, 'bstrike2', '/bstrike2 : This ability allows a pilot to call in a TIE Bomber strike force against their current target, assuming it is valid.'),
('string/en/cmd_d.stf', 99, 'bstrike3', '/bstrike3 : This ability allows a pilot to call in a TIE Bomber strike wing against their current target, assuming it is valid.'),
('string/en/cmd_d.stf', 100, 'bump', '/bump: You offer an open invitation for bumping.\n/bump self: You bump with yourself.\n/bump target: You bump with (target name).'),
('string/en/cmd_d.stf', 101, 'burp', '/burp: You burp loudly and look toward the judges.\n/burp self: Was it tasty? You burp to yourself and get a bitter, acidic taste in your mouth.\n/burp target: You burp in (target name)''s face.'),
('string/en/cmd_d.stf', 102, 'burstrun', '/burstrun: Burst Run lets you run rapidly for a short duration by expending some of your Health, Action, and Mind pools at once.'),
('string/en/cmd_d.stf', 103, 'burstshot1', '/burstshot1 <target>: This ranged attack is more damaging than the default attack.'),
('string/en/cmd_d.stf', 104, 'burstshot2', '/burstshot2 <target>: This area ranged attack is more damaging than Burst Shot 1.'),
('string/en/cmd_d.stf', 105, 'bye', '/bye: BYE!\n/bye self: BYE-BYE!\n/bye target: You wish (target name) well and hope to see (him, her, or it) soon.'),
('string/en/cmd_d.stf', 106, 'cackle', '/cackle: You cackle.\n/cackle self: You cackle insanely at yourself.\n/cackle target: You cackle in (target name)''s face.'),
('string/en/cmd_d.stf', 107, 'callretreat', '/callretreat: RETREAT!!\n/callretreat self: You prepare to retreat.\n/callretreat target: You give (target name) the signal to retreat.'),
('string/en/cmd_d.stf', 108, 'callstop', '/callstop:  Everybody stop!\n/callstop self:  You bravely try to stop the onrushing world.\n/callstop target:  You order (target name) to stop.'),
('string/en/cmd_d.stf', 109, 'calm', '/calm: You try to calm everyone down.\n/calm self: Take a deep breath and count to 10. 1.. 2.. 3..\n/calm target: You try to calm (target name) down.'),
('string/en/cmd_d.stf', 110, 'cancelcraftingsession', 'This command cancels a crafting session.'),
('string/en/cmd_d.stf', 111, 'catchbreath', '/catchbreath: You wheeze and gasp for air as you try to catch your breath.\n/catchbreath self: You rest your hands on your knees and try to catch your breath.\n/catchbreath target: You signal to (target name) that you will be just a moment as you catch your breath.'),
('string/en/cmd_d.stf', 112, 'censor', '/censor: You are appalled at the usage of obscenities.\n/censor self: You scold yourself and wash your own mouth with soap.\n/censor target: You censor (target name).'),
('string/en/cmd_d.stf', 113, 'centerofbeing', 'This command will cause your character to focus on avoiding combat blows. This will only apply when you are wielding a melee weapon.'),
('string/en/cmd_d.stf', 114, 'cert_axe_heavy_duty', 'This certification allows you to wield a Heavy Axe.'),
('string/en/cmd_d.stf', 115, 'cert_axe_vibro', 'This certification allows you to wield a Vibro Axe.'),
('string/en/cmd_d.stf', 116, 'cert_baton_gaderiffi', 'This certification allows you to wield a Gaderiffi Baton.'),
('string/en/cmd_d.stf', 117, 'cert_baton_stun', 'This certification allows you to wield a Stun Baton.'),
('string/en/cmd_d.stf', 118, 'cert_carbine_cdef', 'This certification allows you to wield a CDEF Carbine.'),
('string/en/cmd_d.stf', 119, 'cert_carbine_dh17', 'This certification allows you to wield a DH17 Carbine.'),
('string/en/cmd_d.stf', 120, 'cert_carbine_dh17_short', 'This certification allows you to wield a DH17 Short Carbine.'),
('string/en/cmd_d.stf', 121, 'cert_carbine_dh17_snubnose', 'This certification allows you to wield a DH17 Snubnose Carbine.'),
('string/en/cmd_d.stf', 122, 'cert_carbine_dxr6', 'This certification allows you to wield a DXR6 Carbine.'),
('string/en/cmd_d.stf', 123, 'cert_carbine_e11', 'This certification allows you to wield an E11 Carbine.'),
('string/en/cmd_d.stf', 124, 'cert_carbine_ee3', 'This certification allows you to wield an EE3 Carbine.'),
('string/en/cmd_d.stf', 125, 'cert_carbine_elite', 'This certification allows you to wield an Elite Carbine.'),
('string/en/cmd_d.stf', 126, 'cert_carbine_laser', 'This certification allows you to wield a Laser Carbine.'),
('string/en/cmd_d.stf', 127, 'cert_carbine_laster', 'This certification allows you to wield a Laser Carbine.'),
('string/en/cmd_d.stf', 128, 'cert_carbine_nym_slugthrower', 'This certification allows you to wield a Slugthrower Carbine.'),
('string/en/cmd_d.stf', 129, 'cert_droid_astromech_1', 'Level One Flight-Rated Astromech or Flight Computer Management Certification. This allows you to use the memory core on astromechs (or flight computers) to interface with a starship''s systems and run starship control programs to manage power allocation and other starship functions.'),
('string/en/cmd_d.stf', 130, 'cert_droid_astromech_2', 'Level Two Flight-Rated Astromech or Flight Computer Management Certification. This allows you to use the memory core on astromechs (or flight computers) to interface with a starship''s systems and run starship control programs to manage power allocation and other starship functions.'),
