('string/en/cmd_d.stf', 480, 'droidcommand_enginenormalize', 'Engine settings to their defaults.'),
('string/en/cmd_d.stf', 481, 'droidcommand_engineoverloadfour', 'Makes engines provide more thrust, but is rather wasteful in energy.'),
('string/en/cmd_d.stf', 482, 'droidcommand_engineoverloadone', 'Makes engines provide more thrust, but is rather wasteful in energy.'),
