('string/en/cmd_d.stf', 485, 'droidcommand_mutedroid', 'Toggles off and on the flight droid or flight-computer''s auditory feedback mode, giving the pilot some control over how talkative and responsive they are.'),
('string/en/cmd_d.stf', 486, 'droidcommand_reactornormalize', 'Reset reactor back to default settings.'),
('string/en/cmd_d.stf', 487, 'droidcommand_reactoroverloadfour', 'Reactor to generate more energy, at the cost of over-stressing it.'),
('string/en/cmd_d.stf', 488, 'droidcommand_reactoroverloadone', 'Reactor to generate more energy, at the cost of over-stressing it.'),
('string/en/cmd_d.stf', 489, 'droidcommand_reactoroverloadthree', 'Reactor to generate more energy, at the cost of over-stressing it.'),
('string/en/cmd_d.stf', 490, 'droidcommand_reactoroverloadtwo', 'Reactor to generate more energy, at the cost of over-stressing it.'),
('string/en/cmd_d.stf', 491, 'droidcommand_shieldadjustfrontfour', 'Changes the shield generators to generate stronger front shields than rear.'),
('string/en/cmd_d.stf', 492, 'droidcommand_shieldadjustfrontone', 'Changes the shield generators to generate stronger front shields than rear.'),
('string/en/cmd_d.stf', 493, 'droidcommand_shieldadjustfrontthree', 'Changes the shield generators to generate stronger front shields than rear.'),
('string/en/cmd_d.stf', 494, 'droidcommand_shieldadjustfronttwo', 'Changes the shield generators to generate stronger front shields than rear.'),
('string/en/cmd_d.stf', 495, 'droidcommand_shieldadjustrearfour', 'Changes the shield generators to generate stronger rear shields than front.'),
('string/en/cmd_d.stf', 496, 'droidcommand_shieldadjustrearone', 'Changes the shield generators to generate stronger rear shields than front.'),
('string/en/cmd_d.stf', 497, 'droidcommand_shieldadjustrearthree', 'Changes the shield generators to generate stronger rear shields than front.'),
('string/en/cmd_d.stf', 498, 'droidcommand_shieldadjustreartwo', 'Changes the shield generators to generate stronger rear shields than front.'),
('string/en/cmd_d.stf', 499, 'droidcommand_shieldbacktofronteighty', 'Divert most of the stored charge from the rear shields to the front.'),
('string/en/cmd_d.stf', 500, 'droidcommand_shieldbacktofrontfifty', 'Divert some of the stored charge from the rear shields to the front.'),
('string/en/cmd_d.stf', 501, 'droidcommand_shieldbacktofronthundred', 'Divert all of the stored charge from the rear shields to the front.'),
('string/en/cmd_d.stf', 502, 'droidcommand_shieldbacktofronttwenty', 'Divert some of the stored charge from the rear shields to the front.'),
('string/en/cmd_d.stf', 503, 'droidcommand_shieldemergencyfront', 'This program immediately leeches the majority of rear shield energy and current weapon capacitor charge and diverts it all to the front shield facing. This is an instantaneous command with no lasting effects on any of the ship''s systems involved.'),
('string/en/cmd_d.stf', 504, 'droidcommand_shieldemergencyrear', 'This program immediately leeches the majority of front shield energy and current weapon capacitor charge and diverts it all to the rear shield facing. This is an instantaneous command with no lasting effects on any of the ship''s systems involved.'),
('string/en/cmd_d.stf', 505, 'droidcommand_shieldfronttobackeighty', 'Divert most of the stored charge from the front shields to the rear.'),
('string/en/cmd_d.stf', 506, 'droidcommand_shieldfronttobackfifty', 'Divert some of the stored charge from the front shields to the rear.'),
('string/en/cmd_d.stf', 507, 'droidcommand_shieldfronttobackhundred', 'Divert all of the stored charge from the front shields to the rear.'),
('string/en/cmd_d.stf', 508, 'droidcommand_shieldfronttobacktwenty', 'Divert some of the stored charge from the front shields to the rear.'),
('string/en/cmd_d.stf', 509, 'droidcommand_shieldnormalize', 'Resets shields back to their defaults.'),
('string/en/cmd_d.stf', 510, 'droidcommand_weapcapequalize', 'Resets the weapon capacitor energy settings back to their defaults.'),
('string/en/cmd_d.stf', 511, 'droidcommand_weapcappowerupfour', 'Tell the droid to run more power through the weapon capacitor than it is rated for, leading to enhanced performance and increased system stress.'),
('string/en/cmd_d.stf', 512, 'droidcommand_weapcappowerupone', 'Tell the droid to run more power through the weapon capacitor than it is rated for, leading to enhanced performance and increased system stress.'),
('string/en/cmd_d.stf', 513, 'droidcommand_weapcappowerupthree', 'Tell the droid to run more power through the weapon capacitor than it is rated for, leading to enhanced performance and increased system stress.'),
('string/en/cmd_d.stf', 514, 'droidcommand_weapcappoweruptwo', 'Tell the droid to run more power through the weapon capacitor than it is rated for, leading to enhanced performance and increased system stress.'),
('string/en/cmd_d.stf', 515, 'droidcommand_weapcaptoshieldfour', 'This program allows the droid to use back-up power-routing systems to shunt power currently stored in the weapon capacitor directly to the shield generator systems.'),
('string/en/cmd_d.stf', 516, 'droidcommand_weapcaptoshieldone', 'This program allows the droid to use back-up power-routing systems to shunt power currently stored in the weapon capacitor directly to the shield generator systems.'),
('string/en/cmd_d.stf', 517, 'droidcommand_weapcaptoshieldthree', 'This program allows the droid to use back-up power-routing systems to shunt power currently stored in the weapon capacitor directly to the shield generator systems.'),
('string/en/cmd_d.stf', 518, 'droidcommand_weapcaptoshieldtwo', 'This program allows the droid to use back-up power-routing systems to shunt power currently stored in the weapon capacitor directly to the shield generator systems.'),
('string/en/cmd_d.stf', 519, 'droidcommand_weaponeffeciencyfour', 'Re-tune the weapons to use less power, at the cost of performance.'),
('string/en/cmd_d.stf', 520, 'droidcommand_weaponeffeciencyone', 'Re-tune the weapons to use less power, at the cost of performance.'),
('string/en/cmd_d.stf', 521, 'droidcommand_weaponeffeciencythree', 'Re-tune the weapons to use less power, at the cost of performance.'),
('string/en/cmd_d.stf', 522, 'droidcommand_weaponeffeciencytwo', 'Re-tune the weapons to use less power, at the cost of performance.'),
('string/en/cmd_d.stf', 523, 'droidcommand_weaponnormalize', 'Reset the weapon power to defaults.'),
('string/en/cmd_d.stf', 524, 'droidcommand_weaponoverloadfour', 'Increase weapon performance, at the cost of effeciency and possible system stress.'),
('string/en/cmd_d.stf', 525, 'droidcommand_weaponoverloadone', 'Increase weapon performance, at the cost of effeciency and possible system stress.'),
('string/en/cmd_d.stf', 526, 'droidcommand_weaponoverloadthree', 'Increase weapon performance, at the cost of effeciency and possible system stress.'),
('string/en/cmd_d.stf', 527, 'droidcommand_weaponoverloadtwo', 'Increase weapon performance, at the cost of effeciency and possible system stress.'),
('string/en/cmd_d.stf', 528, 'drool', '/drool: You drool incessantly, creating a small puddle at your feet.\n/drool self: You drool all over yourself.\n/drool target: You drool all over (him, her, or it).'),
('string/en/cmd_d.stf', 529, 'duck', '/duck: You duck!\n/duck self: Quack! Quack!\n/duck target: You duck behind (target name).'),
('string/en/cmd_d.stf', 530, 'duel', '/duel <player>: This command will allow you to engage a player in combat, if they desire to.  Be warned, if you /duel somebody before they /duel you, you can not attack them until they hit you first.  A duel can be stopped if both sides /endduel each other, otherwise it is to the death.'),
('string/en/cmd_d.stf', 531, 'dumppausedcommands', 'Dump all pending paused or looping commands.'),
('string/en/cmd_d.stf', 532, 'echo', 'Echo some text to your chat window.'),
('string/en/cmd_d.stf', 533, 'echuta', '/echuta: E chu ta!\n/echuta self: You foam at the mouth, driveling as you curse under your breath.\n/echuta target: You spray (target name) with spittle as you curse at (him, her, or it) in (his, her, or its) face.'),
('string/en/cmd_d.stf', 534, 'eek', '/eek: Eek!\n/eek self: You take one look at yourself and exclaim "EEK!"\n/eek target: You look at (target name) and exclaim "EEK!"'),
('string/en/cmd_d.stf', 535, 'eject', '/eject: This command will remove you from a balcony or raised part of a building if you are unable to get to the ground.'),
('string/en/cmd_d.stf', 536, 'elbow', '/elbow: You try to clear the immediate area about you by throwing out your elbows.\n/elbow self: You cringe in pain as you hit your funny bone.\n/elbow target: You elbow (target name) in (his, her, or its) side.'),
('string/en/cmd_d.stf', 537, 'emboldenpets', '/emboldenpets: This causes your pets to become bolder, at some cost to you.'),
('string/en/cmd_d.stf', 538, 'embrace', '/embrace: You hold your arms out offering a gentle embrace.\n/embrace self: You give yourself a warm embrace.\n/embrace target: You gently hold (target name) in your arms and give (him, her, or it) a warm embrace.'),
('string/en/cmd_d.stf', 539, 'encourage', '/encourage: Go Team Go!!\n/encourage self: You can do it!\n/encourage target: You encourage (him, her, or it).'),
('string/en/cmd_d.stf', 540, 'endduel', '/endduel <player>: This command disallows you from attacking the other party in a duel.  If both parties /endduel, a duel is ended.'),
('string/en/cmd_d.stf', 541, 'enragepets', '/enragepets: This command causes all of your pets to go berserk for a time, causing more damage but also taking more.'),
('string/en/cmd_d.stf', 542, 'epulse1', '/epulse1: This command triggers an energy discharge that can damage nearby vessels.'),
('string/en/cmd_d.stf', 543, 'epulse2', '/epulse2: This command triggers a tuned energy pulse that can damage nearby vessels, and is likely to cause subsystem damage to them as well.'),
('string/en/cmd_d.stf', 544, 'epulse3', '/epulse3: This command triggers an indiscriminant massive energy discharge from the shields and energy capacitor that is quite likely to damage all nearby vessels and their subsystems.'),
('string/en/cmd_d.stf', 545, 'equilibrium', '/equilibrium: equalizes all three pool attributes to the same value. If the equilize value is greater than the pool''s maximum, the value is truncated to the pools maximum. alias for "/innate equilibrium"'),
('string/en/cmd_d.stf', 546, 'eshields', '/eshields: Emergency Power To Shields - vastly increases shield protection for a short period of time by diverting power from other systems such as weapons and engines to shields, to the point of disabling some of them.'),
('string/en/cmd_d.stf', 547, 'ethrust', '/ethrust: Emergency Power To Engines - vastly increases engine thrust for a short period of time by diverting power from other systems such as weapons and shields to the engines, to the point of disabling some of them.'),
('string/en/cmd_d.stf', 548, 'evilgrin', '/evilgrin: You crack an evil grin.\n/evilgrin self: You grin evilly at your thoughts.\n/evilgrin target: You flash a wicked grin at (target name).'),
('string/en/cmd_d.stf', 549, 'eweapons', '/eweapons: Emergency Power To Weapons - vastly increases weapon power for a short period of time by diverting power from other systems such as shielding and engines to weapons, to the point of disabling some of them.'),
('string/en/cmd_d.stf', 550, 'exhausted', '/exhausted: You collapse to the ground exhausted.\n/exhausted self: You signal that you are absolutely exhausted.\n/exhausted target: You inform (target name) that you are exhausted and must rest.'),
('string/en/cmd_d.stf', 551, 'extinguishfire', '/extinguishFire <target>: This command enables you to cure a fire effect from a target, if you have the appropriate medical equipment.'),
('string/en/cmd_d.stf', 552, 'eyebrow', '/eyebrow: You raise an eyebrow.\n/eyebrow self: You raise an eyebrow at yourself.\n/eyebrow target: You raise an eyebrow at (him, her, or it). What is (he, she or it) up to?'),
('string/en/cmd_d.stf', 553, 'eyeroll', '/eyeroll: You roll your eyes.\n/eyeroll self: You roll your eyes and they fall back into your skull.\n/eyeroll target: You rolls your eyes at (target name).'),
('string/en/cmd_d.stf', 554, 'eyeshot', '/eyeshot <target>: This ranged attack damages an opponent''s mind with a powerful attack, and can also blind its target.'),
('string/en/cmd_d.stf', 555, 'faint', '/faint: You faint.\n/faint self: You look pale, as if about to faint.\n/faint target: You faint into (his, her, or its) arms.'),
('string/en/cmd_d.stf', 556, 'false', '/false: You believe that is false.\n/false self: On second thought, you don''t believe what you just said is true.\n/false target: You refuse to believe what (he, she or it) is saying.'),
('string/en/cmd_d.stf', 557, 'fanfar', 'This ability allows you to plays songs with the Fanfar instrument.'),
('string/en/cmd_d.stf', 558, 'fanshot', '/fanshot <target>: This ranged attack can hit a single target multiple times with your pistol.'),
('string/en/cmd_d.stf', 559, 'faq', '/faq: You direct everyone to the FAQ.\n/faq self: You reference the FAQ.\n/faq target: You direct (target name) to the FAQ.'),
('string/en/cmd_d.stf', 560, 'fastblast', '/fastblast <target>: This ranged attack hits a target''s torso and arms for a high amount of damage.'),
('string/en/cmd_d.stf', 561, 'fear', '/fear: You tremble with fear.\n/fear self: You become paralyzed with fear.\n/fear target: You scream in terror at the sight of (him, her, or it).'),
('string/en/cmd_d.stf', 562, 'feel', '/feel: You feel blindly at your surroundings.\n/feel self: You feel about yourself, checking for holes.\n/feel target: You feel (his, her, or its) bicep. What do you think?'),
('string/en/cmd_d.stf', 563, 'feh', '/feh: FEH!\n/feh self: You look at the condition of your gear and exclaim, "FEH!"\n/feh target: You look disgustedly at (target name) and utter, "FEH!"'),
('string/en/cmd_d.stf', 564, 'feigndeath', '/feigndeath: This command allows the smuggler the ability to pretend he has been incapacitated.  Enemies might just leave the smuggler alone...'),
('string/en/cmd_d.stf', 565, 'fiddle', '/fiddle: You fiddle with random objects.\n/fiddle self: You pull a puzzle cube from your pack and fiddle with it.\n/fiddle target: You fiddle with (target name)''s gear.'),
('string/en/cmd_d.stf', 566, 'fidget', '/fidget: You fidget restlessly.\n/fidget self: You fidget restlessly in anticipation.\n/fidget target: You fidget restlessly at (target name).'),
('string/en/cmd_d.stf', 567, 'find', '/find'),
('string/en/cmd_d.stf', 568, 'fireacidcone1', '/fireacidcone1<target>: This ranged area attack splashes acid in a cone in front of the player, damaging multiple opponents at once with its terrifying onslaught.'),
('string/en/cmd_d.stf', 569, 'fireacidcone2', '/fireacidcone2 <target>: This powerful ranged area attack splashes acid in a cone in front of the player, damaging multiple opponents at once with its terrifying onslaught.  This is more powerful than Acid Cone 1.'),
('string/en/cmd_d.stf', 570, 'fireacidsingle1', '/fireacidsingle1 <target>: This ranged attack douses a target in acid, causing high amounts of damage.'),
('string/en/cmd_d.stf', 571, 'fireacidsingle2', '/fireacidsingle2 <target>: This powerful ranged attack douses a target in acid, causing very high damage.  This is more powerful than Acid Single 1.'),
('string/en/cmd_d.stf', 572, 'fireheavyweapon', 'This command allows the user to fire a heavy weapon.'),
('string/en/cmd_d.stf', 573, 'firejet', '/firejet: Performs an effect of firey jets.'),
('string/en/cmd_d.stf', 574, 'firelightningcone1', '/firelightningcone1 <target>: This ranged area attack fires a cone in front of the player, damaging multiple opponents at once with a huge electrical blast.'),
('string/en/cmd_d.stf', 575, 'firelightningcone2', '/firelightningcone2 <target>: This powerful ranged area attack fires in a cone in front of the player, damaging multiple opponents at once with a huge electrical blast.  This is more powerful than Lightning Cone 1.'),
('string/en/cmd_d.stf', 576, 'firelightningsingle1', '/firelightningsingle1 <target>: This ranged attack blasts a target with a high jolt of electricity, causing good damage.'),
('string/en/cmd_d.stf', 577, 'firelightningsingle2', '/firelightningsingle2 <target>: This powerful ranged attack blast a target with a big jolt of electricity, causing high damage.  This is more powerful than Lightning Single 1.'),
('string/en/cmd_d.stf', 578, 'firstaid', '/firstaid <target>:  This Medic ability lets you stop a target''s bleeding.'),
('string/en/cmd_d.stf', 579, 'fish', 'This command allows the user to fish.'),
('string/en/cmd_d.stf', 580, 'fistpalm', '/fistpalm: You pound your fist into your palm. Curses!\n/fistpalm self: You slam your palm with your fist, muttering under your breath.\n/fistpalm target: You slam your palm with your fist, muttering under your breath about (target name)''s idiocy.'),
('string/en/cmd_d.stf', 581, 'fizz', 'This ability allows you to plays songs with the Fizzz instrument.'),
('string/en/cmd_d.stf', 582, 'flail', '/flail: You flail wildly.\n/flail self: You flail wildly at yourself, as if trying to get something off your body.\n/flail target: You flail wildly at (target name).'),
('string/en/cmd_d.stf', 583, 'flame', '/flame: You take a deep breath and exhale verbal flames everywhere.\n/flame self: You put on your flame-proof suit.\n/flame target: You verbally flame (target name).'),
('string/en/cmd_d.stf', 584, 'flamecone1', '/flamecone1 <target>: This ranged area attack envelops a number of multiple opponents at once with a large sheet of flame.'),
('string/en/cmd_d.stf', 585, 'flamecone2', '/flamecone1 <target>: This powerful ranged area attack envelops a number of multiple opponents at once with a horrifying sheet of flame.  This attack causes more damage than Flame Cone 1.'),
('string/en/cmd_d.stf', 586, 'flamesingle1', '/flamesingle1 <target>: This ranged attack sends a blast of flame towards a single target and does considerable damage.'),
('string/en/cmd_d.stf', 587, 'flamesingle2', '/flamesingle2 <target>: This powerful ranged attack sends a blast of flame towards a target, causing high damage once it strikes.  This is more powerful than Flame Single 1.'),
('string/en/cmd_d.stf', 588, 'flee', '/flee: FLEE!!\n/flee self: Time to flee?\n/flee target: GO! RUN AWAY! FLEE!!'),
('string/en/cmd_d.stf', 589, 'flex', '/flex: You flex your muscles.\n/flex self: You flex your bicep and secretly push it up with your other hand.\n/flex target: You flex for (him, her, or it).'),
('string/en/cmd_d.stf', 590, 'flip', '/flip: You flip a coin.\n/flip self: You flip head-over-heels.\n/flip target: You flip head-over-heels for (target name).'),
('string/en/cmd_d.stf', 591, 'flipcoin', '/flipcoin: You flip a coin.\n/flipcoin self: You flip a coin.\n/flipcoin target: You flip (target name) for it.'),
('string/en/cmd_d.stf', 592, 'flirt', '/flirt: You flirt with danger.\n/flirt self: You flirt with yourself. A little self-involved are we?\n/flirt target: You flirt with (him, her, or it).'),
('string/en/cmd_d.stf', 593, 'flourish', 'This command allows the user to flourish.'),
('string/en/cmd_d.stf', 594, 'flourish+1', '/flourish 1: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 595, 'flourish+2', '/flourish 2: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 596, 'flourish+3', '/flourish 3: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 597, 'flourish+4', '/flourish 4: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 598, 'flourish+5', '/flourish 5: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 599, 'flourish+6', '/flourish 6: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 600, 'flourish+7', '/flourish 7: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 601, 'flourish+8', '/flourish 8: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 602, 'flourish+9', '/flourish 9: Perform one of your Dance or Music Flourishes.'),
('string/en/cmd_d.stf', 603, 'flower', '/flower: You pull a delicate flower from your pack and hold it gently.\n/flower self: You inhale deeply trying to smell the flower''s sweet scent.\n/flower target: You give a delicate flower to (target name).'),
('string/en/cmd_d.stf', 604, 'flurryshot1', '/flurryshot1 <target>: This ranged attack can make a single target dizzy.'),
('string/en/cmd_d.stf', 605, 'flurryshot2', '/flurryshot2 <target>: This ranged attack can make multiple targets dizzy at once.'),
('string/en/cmd_d.stf', 606, 'flushinggraphicsresources', 'Flushing Graphics Resources'),
('string/en/cmd_d.stf', 607, 'flushingshot1', '/flushingshot1 <target>: This ranged attack ability allows you to attempt to startle and stun a single opponent simultaneously.'),
('string/en/cmd_d.stf', 608, 'flushingshot2', '/flushingshot2 <target>: This ranged area attack ability allows you to attempt to startle and stun multiple opponents simultaneously.'),
('string/en/cmd_d.stf', 609, 'flutedroopy', 'This ability allows you to plays songs with the Chidinkalu Horn instrument.'),
('string/en/cmd_d.stf', 610, 'flutter', '/flutter: You heart flutters wildly.\n/flutter self: Your heart flutters wildly as you clench your chest hand-over-hand.\n/flutter target: Your heart flutters at the sight of (him, her, or it).'),
('string/en/cmd_d.stf', 611, 'follow', '/follow <target>: This allows you to automatically follow somebody without having to control your character.  The /stopfollow command will end your auto-follow.'),
('string/en/cmd_d.stf', 612, 'fool', '/fool: You look around for your FOOL brand.\n/fool self: You brand yourself the fool.\n/fool target: You brand (target name) as the FOOL!'),
('string/en/cmd_d.stf', 613, 'forage', '/forage: Searches the area for usable resources such as food and water.'),
('string/en/cmd_d.stf', 614, 'forceabsorb1', '/forceAbsorb1: This ability allows a Jedi to absorb some of the Force power from an incoming Force attack and feeds a portion into your Force pool.'),
('string/en/cmd_d.stf', 615, 'forceabsorb2', '/forceAbsorb2: This ability allows a Jedi to absorb some of the Force power from an incoming Force attack and feeds a portion into your Force pool.  This ability will absorb more Force power than Force Absorb 1.'),
('string/en/cmd_d.stf', 616, 'forcearmor1', '/forceArmor1: This ability allows a Jedi to create a protective barrier around themselves that will stop a portion of incoming damage.  This ability will only stop non Force damage types.'),
('string/en/cmd_d.stf', 617, 'forcearmor2', '/forceArmor2: This ability allows a Jedi to create a protective barrier around themselves that will stop a significant portion of incoming damage.  This ability will only stop non Force damage types.'),
('string/en/cmd_d.stf', 618, 'forcechoke', '/forceChoke <target>: This ability allows a Jedi Master to use the Force to constrict the air passage of the target, doing a considerable amount of damage.'),
('string/en/cmd_d.stf', 619, 'forcecuredisease', '/forceCureDisease <target>: Cures the target of any disease state effects.'),
('string/en/cmd_d.stf', 620, 'forcecurepoison', '/forceCurePoison <target>: Cures the target of any poison state effects.'),
('string/en/cmd_d.stf', 621, 'forcefeedback1', '/forceFeedback1: This ability causes a Jedi to reflect damage immediately back to the source of the attack, only Force type attacks will cause feedback.'),
('string/en/cmd_d.stf', 622, 'forcefeedback2', '/forceFeedback2: This ability causes a Jedi to reflect damage immediately back to the source of the attack, only Force type attacks will cause feedback. This ability reflects back a greater amount of damage from a Force attack than Force Feedback 1.'),
('string/en/cmd_d.stf', 623, 'forceintimidate', ''),
('string/en/cmd_d.stf', 624, 'forceintimidate1', '/forceIntimidate1 <target>: Causes all enemies within a cone emanating from the Jedi to become intimidated.'),
('string/en/cmd_d.stf', 625, 'forceintimidate2', '/forceIntimidate1 <target>: Causes all enemies within a 16-meter radius around the target to become intimidated.'),
('string/en/cmd_d.stf', 626, 'forceknockdown1', '/forceKnockdown1 <target>: This attack allows a Jedi to release a kinetic burst from his or her palm. This will not damage the target but it is enough to knock them down.'),
('string/en/cmd_d.stf', 627, 'forceknockdown2', '/forceKnockdown2 <target>: This attack allows a Jedi to release a large kinetic burst from his or her palm. This will knock down multiple targets in a cone emanating from the Jedi, but will not do any damage.'),
('string/en/cmd_d.stf', 628, 'forceknockdown3', '/forceKnockdown3 <target>: This attack allows a Jedi to release a large kinetic burst from his or her palm. This will knock down multiple targets in the area, but will not do any damage.'),
('string/en/cmd_d.stf', 629, 'forcelightningcone1', '/forceLightningCone1 <target>: This attack allows a Jedi to direct a fork of lightning to hit multiple targets.'),
('string/en/cmd_d.stf', 630, 'forcelightningcone2', '/forceLightningCone2 <target>: This attack allows a Jedi to direct a lightning strike against a multitude of targets. While doing more damage than Force Lightning Cone 1, this attack also has a chance of causing all targets struck by the lightning to become dizzy.'),
('string/en/cmd_d.stf', 631, 'forcelightningsingle1', '/forceLightningSingle1 <target>: This attack allows a Jedi to direct an arc of electricity to the target.'),
('string/en/cmd_d.stf', 632, 'forcelightningsingle2', '/forceLightningSingle2 <target>: This attack allows a Jedi to direct a bolt of lightning towards the target. This has a chance of stunning the target as well as doing more damage than Force Lightning Single 1.'),
('string/en/cmd_d.stf', 633, 'forcemeditate', '/forceMeditate: This ability allows a Jedi to enter a state where their stored Force power can replenish faster than normal.  A Jedi is very vulnerable while in this meditative state.'),
('string/en/cmd_d.stf', 634, 'forceofwill', '/forceofwill: This meditative art allows the incapacitated user to attempt to channel their mental energies back into their conscious mind thereby returning the user to an activate state much sooner than normally attainable.'),
('string/en/cmd_d.stf', 635, 'forceresistbleeding', '/forceResistBleeding: This ability allows a Jedi to use their Force power to increase their body''s natural resistance to bleeding.'),
('string/en/cmd_d.stf', 636, 'forceresistdisease', '/forceResistDisease: This ability allows a Jedi to use their Force power to increase their body''s natural resistance to diseases.'),
('string/en/cmd_d.stf', 637, 'forceresistpoison', '/forceResistPoison: This ability allows a Jedi to use their Force power to increase their body''s natural resistance to poisons.'),
('string/en/cmd_d.stf', 638, 'forceresiststates', '/forceResistStates: This ability allows a Jedi to use their Force power to increase their body''s natural resistance to various state attacks such as Stun, Blind, and Dizziness.'),
('string/en/cmd_d.stf', 639, 'forcerun1', '/forceRun1: Increases your run speed for a short duration.'),
('string/en/cmd_d.stf', 640, 'forcerun2', '/forceRun2: Increases your run speed for a short duration. This ability allows you to run faster than with Force Run 1.'),
('string/en/cmd_d.stf', 641, 'forcerun3', '/forceRun3: Increases your run speed for a short duration. This ability allows you to run with blinding speed.'),
('string/en/cmd_d.stf', 642, 'forceshield1', '/forceShield1: This ability allows a Jedi to create a barrier around themselves that will stop a portion of incoming Force attacks.'),
('string/en/cmd_d.stf', 643, 'forceshield2', '/forceShield2: This ability allows a Jedi to create a barrier around themselves that will stop a significant portion of incoming Force attacks.  This ability will stop more damage than Force Shield 1.'),
('string/en/cmd_d.stf', 644, 'forcespeed1', '/forceSpeed1: This ability allows a Jedi to perform all combat actions faster than normal.'),
('string/en/cmd_d.stf', 645, 'forcespeed2', '/forceSpeed2: This ability allows a Jedi to perform all combat actions much faster than normal.  This ability allows the Jedi to move faster than with Force Speed 1.'),
('string/en/cmd_d.stf', 646, 'forcethrow1', '/forceThrow1 <target>: This attack allows a Jedi to throw nearby dirt and rocks at the target, causing a stunned state.'),
('string/en/cmd_d.stf', 647, 'forcethrow2', '/forceThrow2 <target>: This attack allows a Jedi to throw nearby dirt and rocks at the target, and will very likely hit any enemies that are standing near the target, causing a stunned state.'),
('string/en/cmd_d.stf', 648, 'forceweaken1', '/forceWeaken1 <target>: This ability allows a Jedi to debilitate his or her opponent, making the target more vulnerable to attack.'),
('string/en/cmd_d.stf', 649, 'forceweaken2', '/forceWeaken2 <target>: This ability allows a Jedi to severely debilitate his or her opponent, making the target more vulnerable to attack. This ability is more powerful than Force Weaken 1.'),
('string/en/cmd_d.stf', 650, 'formup', '/formup: This Squad Leader ability allows the leader to cure Dizzy and Stunned states of their squad members.  This ability costs more to the leader based on how many group members are in the group at the time the ability is used.  Use the /setformup <message> command to set the message that the Squad Leader shouts when this command is used.  The Squad Leader must be the leader of the party/group for this to function.'),
('string/en/cmd_d.stf', 651, 'frown', '/frown: You frown.\n/frown self: You frown at yourself.\n/frown target: You frown at (him, her, or it).'),
('string/en/cmd_d.stf', 652, 'full', '/full: You pat your stomach denoting you are full.\n/full self: You rub your stomach, feeling overstuffed.\n/full target: You indicate to (target name) that you are full.'),
('string/en/cmd_d.stf', 653, 'fullautoarea', '/fullautoarea <target>: This ranged attack can hit multiple targets in front of you simultaneously.'),
('string/en/cmd_d.stf', 654, 'fullautoarea1', '/fullautoarea1 <target>: This ranged attack can hit multiple targets in a cone in front of you simultaneously.'),
('string/en/cmd_d.stf', 655, 'fullautoarea2', '/fullautoarea2 <target>: This ranged area attack can hit multiple targets in a cone in front of you simultaneously.'),
('string/en/cmd_d.stf', 656, 'fullautosingle1', '/fullautosingle1 <target>: This ranged attack shoots multiple bolts at once at a single target.'),
('string/en/cmd_d.stf', 657, 'fullautosingle2', '/fullautosingle2 <target>: This ranged attack shoots multiple bolts at once at a single target.'),
('string/en/cmd_d.stf', 658, 'fume', '/fume: You fume with rage.\n/fume self: You fume and mouth words best left unspoken.\n/fume target: You fume with rage at (him, her, or it).'),
('string/en/cmd_d.stf', 659, 'fuzzy', '/fuzzy: You get that warm and fuzzy feeling inside.\n/fuzzy self: You squeeze yourself with a warm and fuzzy feeling inside.\n/fuzzy target: (target name) makes you feel warm and fuzzy inside.'),
('string/en/cmd_d.stf', 660, 'gag', '/gag: You gag in disgust.\n/gag self: You stick your finger in your mouth and make gagging sounds.\n/gag target: You gag in disgust at (target name).'),
('string/en/cmd_d.stf', 661, 'gallop', 'This command allows your mount to run faster for a period of time.'),
('string/en/cmd_d.stf', 662, 'gallopstop', 'This command slows down a mount.'),
('string/en/cmd_d.stf', 663, 'gape', '/gape: You gape.\n/gape self: Your jaw drops and hits the ground with a resounding *THUD*.\n/gape target: You gape at (him, her, or it).'),
('string/en/cmd_d.stf', 664, 'gasp', '/gasp: *GASP!*\n/gasp self: You gasp for air!\n/gasp target: *GASP!* You gasp at (target name).'),
('string/en/cmd_d.stf', 665, 'gawk', '/gawk: Looking dumbfounded, you gawk.\n/gawk self: You gawk at yourself.\n/gawk target: You gawk at (target name).'),
('string/en/cmd_d.stf', 666, 'gaze', '/gaze: You gaze in awe at your surroundings.\n/gaze self: You gaze in awe at yourself\n/gaze target: You gaze in awe at (him, her, or it).'),
('string/en/cmd_d.stf', 667, 'giggle', '/giggle: HEHE!\n/giggle self: You giggle at yourself.\n/giggle target: You giggle at (him, her, or it).'),
('string/en/cmd_d.stf', 668, 'givetem', 'This command utilizes the give item option.'),
('string/en/cmd_d.stf', 669, 'giveup', '/giveup: "I GIVE UP!"\n/giveup self: You shake your head and murmur "I give up..."\n/giveup target: Apparently, (he, she or it) is not worth the trouble. "I give up!"'),
('string/en/cmd_d.stf', 670, 'glare', '/glare: You glare about furiously.\n/glare self: You glare furiously out of the corner of your eyes.\n/glare target: You glare at (him, her, or it).'),
('string/en/cmd_d.stf', 671, 'gloat', '/gloat: You gloat.\n/gloat self: You gloat quietly to yourself.\n/gloat target: You gloat at (him, her, or it).'),
('string/en/cmd_d.stf', 672, 'glow', '/glow: You glow happily.\n/glow self: Feeling special?\n/glow target: You glow and  let (him, her, or it) know how happy (he, she or it) makes you.'),
('string/en/cmd_d.stf', 673, 'going', '/going: CHARGE!!\n/going self: Are you sure you wanted to do that?\n/going target: CHARGE!! Targeting...(target name).'),
('string/en/cmd_d.stf', 674, 'grantzoningrights', '/grantzoningrights <target>: Grants the target the rights to place a commercial structure, such as a cantina, in the borders of your city.  The rights last 24 hours.'),
('string/en/cmd_d.stf', 675, 'greet', '/greet: You greet the passers-by.\n/greet self: You greet yourself.\n/greet target: You greet (him, her, or it).'),
('string/en/cmd_d.stf', 676, 'grin', '/grin: You grin.\n/grin self: You grin at yourself.\n/grin target: You grin at (target name).'),
('string/en/cmd_d.stf', 677, 'groan', '/groan: You groan loudly.\n/groan self: You groan at yourself.\n/groan target: You groan loudly at (him, her, or it).'),
('string/en/cmd_d.stf', 678, 'group', '/group'),
('string/en/cmd_d.stf', 679, 'grovel', '/grovel: You grovel in the dirt.\n/grovel self: You grovel fawningly.\n/grovel target: You grovel at (target name)''s feet.'),
('string/en/cmd_d.stf', 680, 'growl', '/growl: GRRRRRR!\n/growl self: You growl at yourself.\n/growl target: You growl at (him, her, or it).'),
('string/en/cmd_d.stf', 681, 'grumble', '/grumble: You grumble.\n/grumble self: You grumble to yourself.\n/grumble target: You grumble something rude about (target name).'),
('string/en/cmd_d.stf', 682, 'grunt', '/grunt: You grunt.\n/grunt self: You grunt at yourself.\n/grunt target: You grunt at (target name).'),
('string/en/cmd_d.stf', 683, 'guildremove', 'This command allows the user to guild remove himself.'),
('string/en/cmd_d.stf', 684, 'guildstatus', 'This command allows the user to view the status of his/her guild.'),
('string/en/cmd_d.stf', 685, 'gulp', '/gulp: *GULP!!*\n/gulp self: Don''t choke now!\n/gulp target: You gulp at (target name).'),
('string/en/cmd_d.stf', 686, 'hack', '/hack: You hack.\n/hack self: You hack up a furball.\n/hack target: You hack at (target name).'),
('string/en/cmd_d.stf', 687, 'hail', '/hail: You hail passers-by.\n/hail self: You hail yourself with a handful of pebbles.\n/hail target: You hail (target name).'),
('string/en/cmd_d.stf', 688, 'halfnelson', '/halfnelson: You motion as if to put someone into a half-nelson.\n/halfnelson self: You put yourself in a half-nelson.\n/halfnelson target: You put (target name) in a half-nelson. "Say uncle!"'),
('string/en/cmd_d.stf', 689, 'halo', '/halo: You smile innocently and don your halo.\n/halo self: You shine your halo.\n/halo target: You smile at (him, her, or it) and don your halo.'),
('string/en/cmd_d.stf', 690, 'hand', '/hand: You ask if anyone can give you a hand.\n/hand self: You give yourself a hand.\n/hand target: You give (him, her, or it) a gentle kiss on the hand.'),
('string/en/cmd_d.stf', 691, 'handshake', '/handshake: You offer a handshake.\n/handshake self: You shake your own hand.\n/handshake target: You shake (his, her, or its) hand.'),
('string/en/cmd_d.stf', 692, 'harvestcorpse', '/harvestcorpse <corpse>: This command allows you to withdraw Meat, Hide or Bone from a harvestable creature corpse.  Not all creatures will have all 3 of these options, and some may have none.'),
('string/en/cmd_d.stf', 693, 'haveconsent', '/haveconsent: This command will display everybody that has your consent to move your corpse.'),
('string/en/cmd_d.stf', 694, 'headache', '/headache: You complain about a headache.\n/headache self: You grab your skull and beg the pain to stop.\n/headache target: You toss (him, her, or it) a couple analgesics.'),
('string/en/cmd_d.stf', 695, 'headlock', '/headlock: You demonstrate the proper headlock technique.\n/headlock self: You put yourself in a headlock.\n/headlock target: You put (target name) in a headlock.'),
('string/en/cmd_d.stf', 696, 'headshot1', '/headshot1 <target>: This ranged targets an opponent''s head in order to damage their Mind pool.'),
('string/en/cmd_d.stf', 697, 'headshot2', '/headshot2 <target>: This ranged attack targets an opponent''s head in order to damage their Mind pool.'),
('string/en/cmd_d.stf', 698, 'headshot3', '/headshot3 <target>: This powerful ranged attack targets an opponent''s head in order to devastate their Mind pool.'),
('string/en/cmd_d.stf', 699, 'healactionself1', '/healActionSelf1: Repairs a moderate amount of your Action damage.'),
('string/en/cmd_d.stf', 700, 'healactionself2', '/healActionSelf2: Repairs a large amount of your Action damage.'),
('string/en/cmd_d.stf', 701, 'healactionwoundother1', '/healActionWoundOther1 <player>: Heals a moderate amount of the target player''s Action wounds.'),
('string/en/cmd_d.stf', 702, 'healactionwoundother2', '/healActionWoundOther2 <player>: Heals a large amount of the target player''s Action wounds.'),
('string/en/cmd_d.stf', 703, 'healactionwoundself1', '/healActionWoundSelf1: Heals a moderate amount of your Action wounds.'),
('string/en/cmd_d.stf', 704, 'healactionwoundself2', '/healActionWoundSelf2: Heals a large amount of your Action wounds.'),
('string/en/cmd_d.stf', 705, 'healallother1', '/healAllOther1 <player>: Repairs a moderate amount of damage to all of the target player''s Health, Action, and Mind pools.'),
('string/en/cmd_d.stf', 706, 'healallother2', '/healAllOther2 <player>: Repairs a large amount of damage to all of the target player''s Health, Action, and Mind pools.'),
('string/en/cmd_d.stf', 707, 'healallself1', '/healAllSelf1: Repairs a moderate amount of damage to all of your Health, Action, and Mind pools.'),
('string/en/cmd_d.stf', 708, 'healallself2', '/healAllSelf2: Repairs a large amount of damage to all of your Health, Action, and Mind pools.'),
('string/en/cmd_d.stf', 709, 'healbattlefatigueother1', '/healBattleFatigueOther1 <player>: Removes a moderate amount of the target player''s Battle Fatigue.'),
('string/en/cmd_d.stf', 710, 'healbattlefatigueother2', '/healBattleFatigueOther2 <player>: Removes a large amount of the target player''s Battle Fatigue.'),
('string/en/cmd_d.stf', 711, 'healbattlefatigueself1', '/healBattleFatigueSelf1: Removes a moderate amount of your Battle Fatigue.'),
('string/en/cmd_d.stf', 712, 'healbattlefatigueself2', '/healBattleFatigueSelf2: Removes a large amount of your Battle Fatigue.'),
('string/en/cmd_d.stf', 713, 'healdamage', '/healdamage: This command will heal damaged stat pools, if you have the requisite skills and medicine.'),
('string/en/cmd_d.stf', 714, 'healenhance', '/healenhance <target>: This command enables you to enhance another player''s attributes, if you have the appropriate enhancement medpacks handy.'),
('string/en/cmd_d.stf', 715, 'healhealthself1', '/healHealthSelf1: Repairs a moderate amount of your Health damage.'),
('string/en/cmd_d.stf', 716, 'healhealthself2', '/healHealthSelf2: Repairs a large amount of your Health damage.'),
('string/en/cmd_d.stf', 717, 'healhealthwoundother1', '/healHealthWoundOther1 <player>: Heals a moderate amount of the target player''s Health wounds.'),
('string/en/cmd_d.stf', 718, 'healhealthwoundother2', '/healHealthWoundOther2 <player>: Heals a large amount of the target player''s Health wounds.'),
('string/en/cmd_d.stf', 719, 'healhealthwoundself1', '/healHealthWoundSelf1: Heals a moderate amount of your Health wounds.'),
('string/en/cmd_d.stf', 720, 'healhealthwoundself2', '/healHealthWoundSelf2: Heals a large amount of your Health wounds.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/cmd_d.stf', 721, 'healmind', '/healMind: This command heals mind pool damage at the cost of wounds to the medic.'),
('string/en/cmd_d.stf', 722, 'healmindself1', '/healMindSelf1: Repairs a moderate amount of your Mind damage.'),
('string/en/cmd_d.stf', 723, 'healmindself2', '/healMindSelf2: Repairs a large amount of your Mind damage.'),
('string/en/cmd_d.stf', 724, 'healmindwoundother1', '/healMindWoundOther1 <player>: Heals a moderate amount of the target player''s Mind wounds.'),
('string/en/cmd_d.stf', 725, 'healmindwoundother2', '/healMindWoundOther2 <player>: Heals a large amount of the target player''s Mind wounds.'),
('string/en/cmd_d.stf', 726, 'healmindwoundself1', '/healMindWoundSelf1: Heals a moderate amount of your Mind wounds.'),
('string/en/cmd_d.stf', 727, 'healmindwoundself2', '/healMindWoundSelf2: Heals a large amount of your Mind wounds.'),
('string/en/cmd_d.stf', 728, 'healstate', '/healstate <target>: This command allows you to cure states (Dizzy, Stun, Blind, Intimidated, etc.) on a target, if you have the appropriate medical equipment.'),
('string/en/cmd_d.stf', 729, 'healstatesother', '/healStatesOther <player>: Removes all negative state effects such as Stun, Blind, Intimidate, and Dizziness from the target player.'),
('string/en/cmd_d.stf', 730, 'healstatesself', '/healStatesSelf: Removes all of your negative state effects such as Stun, Blind, Intimidate, and Dizziness.'),
('string/en/cmd_d.stf', 731, 'healthshot1', '/healthshot1 <target>: This ranged attack can wreak havoc with a target''s Health pool drain and regeneration rates.'),
('string/en/cmd_d.stf', 732, 'healthshot2', '/healthshot2 <target>: This advanced ranged attack can wreak havoc with a target''s Health pool drain and regeneration rates.  This is a stronger attack than Health Shot 1.'),
('string/en/cmd_d.stf', 733, 'healwound', '/healwound: This command will heal wounded stat pools, if you have the requisite skills and medicine.'),
('string/en/cmd_d.stf', 734, 'hearnoevil', '/hearnoevil: You cover your ears.\n/hearnoevil self: You stare blankly forward with your hands over your ears.\n/hearnoevil target: You cover your ears and try to block (him, her, or it) out. LA LA LA LA LA LA.'),
('string/en/cmd_d.stf', 735, 'help', '/help: HELP!\n/help self: You help yourself.\n/help target: You look to (him, her, or it) for help.'),
('string/en/cmd_d.stf', 736, 'helpme', '/helpme:  HELP!\n/helpme self:  You help yourself.\n/helpme target:  You look to (him, her, or it) for help.'),
('string/en/cmd_d.stf', 737, 'hero', '/hero: You look for a hero to save you.\n/hero self: You are your own greatest hero!\n/hero target: MY HERO! You proclaim (target name) as your hero.'),
('string/en/cmd_d.stf', 738, 'hi5', '/hi5: You hold your hand up to give a high-five.\n/hi5 self: You give yourself high-five.\n/hi5 target: You give (him, her, or it) a high-five. YEAH!'),
('string/en/cmd_d.stf', 739, 'hiccup', '/hiccup: You hiccup.\n/hiccup self: You hiccup strongly and get a bitter-sour taste in your mouth.\n/hiccup target: You hiccup and beg (target name) for help to get rid of them.'),
('string/en/cmd_d.stf', 740, 'hiss', '/hiss: You hiss.\n/hiss self: You hiss under your breath.\n/hiss target: You hiss at (target name).'),
('string/en/cmd_d.stf', 741, 'hobble', '/hobble: You hobble.\n/hobble self: You hobble about in circles.\n/hobble target: You hobble about (target name).'),
('string/en/cmd_d.stf', 742, 'holdon', '/holdon: You hold on for dear life.\n/holdon self: You hold onto yourself. Need a security blanket?\n/holdon target: You hold onto (him, her, or it), not letting go!'),
('string/en/cmd_d.stf', 743, 'hop', '/hop: You hop around.\n/hop self: You hop on one foot.\n/hop target: You hop around (target name).'),
('string/en/cmd_d.stf', 744, 'hose', '/hose: You hose everyone down.\n/hose self: You hose yourself down. Take it easy there!\n/hose target: You help (target name) to cool off a bit.'),
('string/en/cmd_d.stf', 745, 'hot', '/hot: You are too hot!\n/hot self: You''re just too hot!\n/hot target: You are too hot for (target name).'),
('string/en/cmd_d.stf', 746, 'hug', '/hug: You hold your arms out and offer a hug.\n/hug self: You give yourself a hug.\n/hug target: You give (him, her, or it) a hug.'),
('string/en/cmd_d.stf', 747, 'huge', '/huge: You hold your arms out wide and indicate it was HUGE!\n/huge self: You guess that it was HUGE!\n/huge target: You indicate to (him, her, or it) that it was HUGE!'),
('string/en/cmd_d.stf', 748, 'hum', '/hum: You hum.\n/hum self: You hum a tune to yourself.\n/hum target: You hum a tune for (target name).'),
('string/en/cmd_d.stf', 749, 'hunger', '/hunger: You grow hungry.\n/hunger self: Your stomach rumbles with a hollow, empty sound.\n/hunger target: You indicate to (target name) that you are hungry.'),
('string/en/cmd_d.stf', 750, 'iffscramble', '/iffscramble: Temporarily confuses enemy targeting systems.'),
('string/en/cmd_d.stf', 751, 'imagedesign', 'This command allows the user to image design.'),
('string/en/cmd_d.stf', 752, 'imagedesigner', 'This ability allows you to perform image design commands.'),
('string/en/cmd_d.stf', 753, 'imfull', '/imfull: You pat your stomach denoting you are full.\n/imfull self: You rub your stomach, feeling overstuffed.\n/imfull target: You indicate to (target) that you are full.'),
('string/en/cmd_d.stf', 754, 'imitate', '/imitate: You imitate a statue and stand perfectly still.\n/imitate self: You imitate yourself. Kind of pointless, isn''t it?\n/imitate target: You imitate (target name).'),
('string/en/cmd_d.stf', 755, 'inante', '/innate: lists available innate commands\n/innate <innate ability>: attempts to utilize innate ability'),
('string/en/cmd_d.stf', 756, 'innate', '/innate: determines which innate command are available to you. /innate <innate ability> attempts to activate the innate ability. see /<innate ability> for further information.'),
('string/en/cmd_d.stf', 757, 'innocent', '/innocent: You do your best to look innocent.\n/innocent self: You claim innocence.\n/innocent target: You do your best to look innocent for (target name).'),
('string/en/cmd_d.stf', 758, 'insertitemintoshipcomponentslot', 'Place an item (a missile pack, for example) into a component in a ship.'),
('string/en/cmd_d.stf', 759, 'inspacereload', '/inspacereload: If you are stopped and not in a dangerous area, this command will summon a ship to arrive, give an estimate for reloading the player''s magazine racks for countermeasures and missiles, and reload them if the player desires. The ammunition reloaded in the field will not be quite as good as what was originally in the magazine.'),
('string/en/cmd_d.stf', 760, 'inspacerepair', '/inspacerepair: If you are stopped and not in a dangerous area, this command will summon a repair ship to arrive, give an estimate for repairs, and do them if the player desires. Repairs in the field will not be as good as those done at a station or otherwise.'),
('string/en/cmd_d.stf', 761, 'inspacerr', '/inspacerr: This command combines the In Space Repair and In Space Reload commands into a single command, and the ship summoned will provide both services.'),
('string/en/cmd_d.stf', 762, 'inspect', '/inspect: Inspect a ship''s cargo.'),
('string/en/cmd_d.stf', 763, 'installmissionterminal', '/installmissionterminal: Allows the mayor to place a mission terminal within the borders of his city.'),
('string/en/cmd_d.stf', 764, 'installshipcomponent', 'Install a ship component into a ship.'),
('string/en/cmd_d.stf', 765, 'intimidate1', '/intimidate1 <target>: When a target is intimidated, they are not able to hit their targets as often.'),
('string/en/cmd_d.stf', 766, 'intimidate2', '/intimidate2 <target>: When a target is intimidated, they are not able to hit their targets as easily.  This is more powerful than Intimidate 1.'),
('string/en/cmd_d.stf', 767, 'intimidationattack', 'This command allows the user to utilize the intimidation attack.'),
('string/en/cmd_d.stf', 768, 'introduce', '/introduce: You introduce everyone to each other.\n/introduce self: WELL MET! You introduce yourself to everyone.\n/introduce target: Everyone, meet (target name).'),
('string/en/cmd_d.stf', 769, 'isafk', '/isafk:  You notify every around you that you are going AFK.  Hurry back, now!\n/isafk self:  OK... You are really AFK now.\n/isafk target:  You point out that (target name) is AFK.'),
('string/en/cmd_d.stf', 770, 'jam', '/jam: Just A Moment!\n/jam self: You announce you will be done in just a moment.\n/jam target: You inform (target name) that (he, she or it) only has just a moment to finish.'),
('string/en/cmd_d.stf', 771, 'jas', '/jas: Just one more second!\n/jas self: 1-one-thousand. DING! Done yet?\n/jas target: You inform (target name) that (he, she or it) only has a few seconds left.'),
('string/en/cmd_d.stf', 772, 'jedimindtrick', '/jediMindTrick <target>: This ability allows a Jedi to project his or her conciousness into the weak minded. This will affect NPCs or creatures that are currently under the control of another player, causing them to forget their master and turn rogue.'),
('string/en/cmd_d.stf', 773, 'jk', '/jk: HA! Just kidding!\n/jk self: You let yourself know you were just kidding.\n/jk target: You inform (target name) that you were just kidding.'),
('string/en/cmd_d.stf', 774, 'jstart1', '/jstart1: This command triggers a discharge from your weapon capacitor to recharge your target''s shields. You must have a friendly player-controlled ship as your target, be close in proximity, and have at least a 50% charge in your weapon capacitor.'),
('string/en/cmd_d.stf', 775, 'jstart2', '/jstart2: This command triggers a discharge from your weapon capacitor and shields to recharge your target''s shields. You must have a friendly player-controlled ship as your target, be close in proximity, and have at least a 50% charge in your weapon capacitor. Up to 50% of your shield''s max capacity will be used for recharging purposes.'),
('string/en/cmd_d.stf', 776, 'jstart3', '/jstart3: This command triggers a discharge from your weapon capacitor and shields to recharge your target''s shields. You must have a friendly player-controlled ship as your target, be close in proximity, and have at least a 50% charge in your weapon capacitor. Up to 90% of your shield''s max capacity will be used for recharging purposes.'),
('string/en/cmd_d.stf', 777, 'jump', '/jump: BOIING!! You jump high in the air!\n/jump self: You try to jump over yourself and land square on your head.\n/jump target: You jump up and down on (him, her, or it).'),
('string/en/cmd_d.stf', 778, 'kipupshot', '/kipupshot: A kip-up shot will cause you to spring to your feet while attacking, leaving you in a standing position.'),
('string/en/cmd_d.stf', 779, 'kiss', '/kiss: You close your eyes and pucker up, ready for a kiss.\n/kiss self: You kiss yourself.\n/kiss target: You kiss (target name) gently on the lips.'),
('string/en/cmd_d.stf', 780, 'kisscheek', '/kisscheek: You kiss anyone who might be in front of you.\n/kisscheek self: You kiss yourself.\n/kisscheek target: You give (target name) a friendly kiss on the cheek.'),
('string/en/cmd_d.stf', 781, 'kloohorn', 'This ability allows you to plays songs with the Kloo Horn instrument.'),
('string/en/cmd_d.stf', 782, 'kneel', '/kneel: Kneeling brings you into a lower posture, which prohibits movement and makes you more vulnerable to melee attacks, but allows for better ranged accuracy'),
('string/en/cmd_d.stf', 783, 'knock', '/knock: You knock.\n/knock self: You knock on wood.\n/knock target: You knock on (target name)''s head.'),
('string/en/cmd_d.stf', 784, 'knockdownattack', 'This command utilizes the knock down attack.'),
('string/en/cmd_d.stf', 785, 'knockdownfire', '/knockdownfire <target>: This ranged attack blasts the target with a quick rush of flame aimed at their upper body, which can cause them to bowled over by the sheer force directed at them, causing them to become dizzy as well.'),
('string/en/cmd_d.stf', 786, 'knockwood', '/knockwood:  You knock.\n/knockwood self:  You knock on wood.\n/knockwood target:  You knock on (target name)''s head.'),
('string/en/cmd_d.stf', 787, 'kowtow', '/kowtow: You kowtow.\n/kowtow self: You kowtow to yourself.\n/kowtow target: You kowtow before (target name).'),
('string/en/cmd_d.stf', 788, 'lag', '/lag: LAAAAAGGGGG!!!\n/lag self: You announce that you are lagging.\n/lag target: You point out that (target name) is lagging.'),
('string/en/cmd_d.stf', 789, 'lagging', '/lagging'),
('string/en/cmd_d.stf', 790, 'language', 'Set Spoken Language'),
('string/en/cmd_d.stf', 791, 'language+bothese', 'Speak Bothese (Bothan Language)'),
('string/en/cmd_d.stf', 792, 'language+dosh', 'Speak Dosh (Trandoshan Language)'),
('string/en/cmd_d.stf', 793, 'language+ithorese', 'Speak Ithorese (Ithorian Language)'),
('string/en/cmd_d.stf', 794, 'language+ithorian', 'Speak Ithorese (Ithorian Language)'),
('string/en/cmd_d.stf', 795, 'language+lekku', 'Use Twi''lek Lekku Language.'),
('string/en/cmd_d.stf', 796, 'language+moncalamarian', 'Speak Mon Calamarian'),
('string/en/cmd_d.stf', 797, 'language+rodese', 'Speak Rodese (Rodian Language)'),
('string/en/cmd_d.stf', 798, 'language+ryl', 'Speak Ryl (Twi''lek Language)'),
('string/en/cmd_d.stf', 799, 'language+shyriiwook', 'Speak Shyriiwook (Wookiee Language)'),
('string/en/cmd_d.stf', 800, 'language+sullustan', 'Speak Sullustese (Sullustan Language)'),
('string/en/cmd_d.stf', 801, 'language+sullustese', 'Speak Sullustese (Sullustan Language)'),
('string/en/cmd_d.stf', 802, 'language+zabrak', 'Speak Zabrak Language'),
('string/en/cmd_d.stf', 803, 'large', '/large: You spread your arms out some and meter a large-ish size.\n/large self: You guess that it would be large.\n/large target: You indicate to (target name) that it was large.'),
('string/en/cmd_d.stf', 804, 'lastditch', '/lastditch <target>: A single powerful shot made with precise aim.  The last ditch shot takes a lot out of the person firing it and makes the delay until their next action very high.'),
('string/en/cmd_d.stf', 805, 'laugh', '/laugh: HAHA!!\n/laugh self: You laugh at yourself.\n/laugh target: You laugh at (target name).'),
('string/en/cmd_d.stf', 806, 'launchfirework', 'This command is used to launch a firework.'),
('string/en/cmd_d.stf', 807, 'lean', '/lean: You lean forward.\n/lean self: You lean up against a wall.\n/lean target: You lean on (target name).'),
('string/en/cmd_d.stf', 808, 'leer', '/leer: You leer enviously at everyone around you.\n/leer self: You leer enviously at yourself.\n/leer target: You leer enviously at (target name).'),
('string/en/cmd_d.stf', 809, 'left', '/left: You point left.\n/left self: You point left.\n/left target: You turn to (target name) and point left.'),
('string/en/cmd_d.stf', 810, 'legshake', '/legshake: Your legs shake.\n/legshake self: You shake your leg, as if trying to get something off of it.\n/legshake target: You try to shake (him, her, or it) off your leg.'),
('string/en/cmd_d.stf', 811, 'legshot1', '/legshot1 <target>: This ranged attack targets an opponent''s legs in order to damage their Action pool.'),
('string/en/cmd_d.stf', 812, 'legshot2', '/legshot2 <target>: This ranged attack targets an opponent''s legs in order to damage their Action pool.'),
('string/en/cmd_d.stf', 813, 'legshot3', '/legshot3 <target>: This powerful ranged attack targets an opponent''s legs in order to devastate their Action pool.'),
('string/en/cmd_d.stf', 814, 'lfg', '/lfg'),
('string/en/cmd_d.stf', 815, 'lick', '/lick: You lick your lips.\n/lick self: You lick yourself.\n/lick target: You lick (him, her, or it).'),
('string/en/cmd_d.stf', 816, 'lives', '/lives: You decide to let them live.\n/lives self: You contemplate the meaning of life.\n/lives target: You decide that (target name) will live, for now... '),
('string/en/cmd_d.stf', 817, 'lol', '/lol: That was funny!\n/lol self: You try to hold it in, but burst out laughing.\n/lol target: You laugh out loud at (him, her, or it).'),
('string/en/cmd_d.stf', 818, 'loser', '/loser: You let everyone know that you are the champion, and they are not.\n/loser self: Oh no, you''ve lost again!\n/loser target: You think (target name) is a loser.'),
('string/en/cmd_d.stf', 819, 'lost', '/lost: Lost, eh?\n/lost self: You look around, utterly lost.\n/lost target: You think (he, she or it) is lost, eh?'),
('string/en/cmd_d.stf', 820, 'love', '/love: Ain''t love grand?\n/love self: You love being you!\n/love target: You profess your love to (him, her, or it).'),
('string/en/cmd_d.stf', 821, 'lowblow', '/lowblow <target>: A painful, unfair pistol shot below the belt.  Enemies struck by a low blow may lose their balance and fall.'),
('string/en/cmd_d.stf', 822, 'luck', '/luck: Feeling lucky?\n/luck self: You wish yourself the best of luck!\n/luck target: Good luck, (target name)!'),
('string/en/cmd_d.stf', 823, 'maintenance_fees_1', 'The merchant gains a 20% decrease in structure maintenance fees.'),
('string/en/cmd_d.stf', 824, 'makeroom', '/makeroom: Hey everybody, make room!\n/makeroom self: You make a little room for yourself.\n/makeroom target: You tell (target name) to make some room!'),
('string/en/cmd_d.stf', 825, 'manage_militia', 'Gives the politician the ability to add and remove members of the city militia via the city management terminal.'),
('string/en/cmd_d.stf', 826, 'manage_taxes', 'The Politician who is also a city mayor has the ability to manage the taxation of his constituency.  Taxes may be collected in four areas: Property Tax, Civilian Tax, Sales Tax, and Travel Fees.'),
('string/en/cmd_d.stf', 827, 'mandoviol', 'This ability allows you to plays songs with the Mandoviol instrument.'),
('string/en/cmd_d.stf', 828, 'manual', '/manual: You produce the manual and suggest a quick read.\n/manual self: You refer to the manual.\n/manual target: You politely suggest reading the manual to (him, her, or it).'),
('string/en/cmd_d.stf', 829, 'maskscent', '/maskscent: Masks your scent from aggressive creatures for a short time.'),
('string/en/cmd_d.stf', 830, 'medicalforage', '/medicalforage: This command allows you to forage material from the area that can be used to create medical supplies.'),
('string/en/cmd_d.stf', 831, 'meditate', '/meditate: This Teras Kasi art allows the user to enter a trance-like state. In this state, the user can stop bleeding as well as slow poison and disease. Additionally, rumors suggest that extremely proficient meditation artists can slowly heal their own wounds.'),
('string/en/cmd_d.stf', 832, 'medium', '/medium: You spread your arms out a bit and signify a medium size.\n/medium self: You guess that it would be about medium sized.\n/medium target: You indicate to (target name) that it was about medium sized.'),
('string/en/cmd_d.stf', 833, 'melee1hblindhit1', '/melee1hblindhit1 <target>: This melee attack can temporarily blind a single target.'),
('string/en/cmd_d.stf', 834, 'melee1hblindhit2', '/melee1hblindhit2 <target>: This melee area attack can temporarily blind multiple targets at once.'),
('string/en/cmd_d.stf', 835, 'melee1hbodyhit1', '/melee1hbodyhit1 <target>: This melee attack targets the body in order to damage the target''s Health pool.'),
('string/en/cmd_d.stf', 836, 'melee1hbodyhit2', '/melee1hbodyhit2 <target>: This melee attack targets an opponent''s body in order to damage the target''s Health pool.  It is stronger than One-Hand Body Hit 1.'),
('string/en/cmd_d.stf', 837, 'melee1hbodyhit3', '/melee1hbodyhit3 <target>: This melee attack targets an opponent''s body in order to damage the target''s Health pool.  It is stronger than One-Hand Body Hit 2.'),
('string/en/cmd_d.stf', 838, 'melee1hdizzyhit1', '/melee1hdizzyhit1 <target>: This melee attack can make a single target dizzy.'),
('string/en/cmd_d.stf', 839, 'melee1hdizzyhit2', '/melee1hdizzyhit2 <target>: This melee area attack can cause multiple targets to become dizzy.'),
('string/en/cmd_d.stf', 840, 'melee1hhealthhit1', '/melee1hhealthhit1 <target>: This melee attack targets an opponent''s body in order to WOUND the target''s Health pool.'),
('string/en/cmd_d.stf', 841, 'melee1hhealthhit2', '/melee1hhealthhit2 <target>: This melee attack targets an opponent''s body in order to WOUND the target''s Health pool.  It can inflict more wound damage than One-Hand Health Hit 1.'),
('string/en/cmd_d.stf', 842, 'melee1hhit1', '/melee1hhit1 <target>: This melee attack inflicts more damage than the basic One-Hand attack.'),
('string/en/cmd_d.stf', 843, 'melee1hhit2', '/melee1hhit2 <target>: This melee attack inflicts more damage then One-Hand Hit 1.'),
('string/en/cmd_d.stf', 844, 'melee1hhit3', '/melee1hhit3 <target>: This powerful melee attack inflicts more damage than One-Hand Hit 2.'),
('string/en/cmd_d.stf', 845, 'melee1hlunge1', '/melee1hlunge1 <target>: This melee attack allows you to slightly extend your range, and it can change the posture of your target.'),
('string/en/cmd_d.stf', 846, 'melee1hlunge2', '/melee1hlunge2 <target>: This melee attack allows you to slightly extend your range, and it can knock your target down.'),
('string/en/cmd_d.stf', 847, 'melee1hscatterhit1', '/melee1hscatterhit1 <target>: This melee attack can strike multiple body parts on a target at once.'),
('string/en/cmd_d.stf', 848, 'melee1hscatterhit2', '/melee1hscatterhit2 <target>: This melee attack can strike multiple body parts at once.  This attack is more powerful than One-Hand Scatter Hit 1.'),
('string/en/cmd_d.stf', 849, 'melee1hspinattack1', '/melee1hspinattack1 <target>: This melee area attack can damage multiple targets at once.'),
('string/en/cmd_d.stf', 850, 'melee1hspinattack2', '/melee1hspinattack2 <target>: This melee area attack can damage multiple targets at once, with a chance to blind them.'),
('string/en/cmd_d.stf', 851, 'melee2harea1', '/melee2harea1 <target>: This melee area attack can lower the posture of multiple targets at once.'),
('string/en/cmd_d.stf', 852, 'melee2harea2', '/melee2harea2 <target>: This melee area attack can lower the posture of multiple targets at once.  This is more damaging than Two-Hand Area Attack 1.'),
('string/en/cmd_d.stf', 853, 'melee2harea3', '/melee2harea3 <target>: This powerful melee area attack can blind, and damage and lower the posture of multiple targets simultaneously.  This is more damaging then Two-Hand Area Attack 2.'),
('string/en/cmd_d.stf', 854, 'melee2hheadhit1', '/melee2hheadhit1 <target>: This melee attack targets the head in order to damage the target''s Mind pool.'),
('string/en/cmd_d.stf', 855, 'melee2hheadhit2', '/melee2hheadhit2 <target>: This melee attack targets an opponent''s head in order to damage the target''s Mind pool.  This is more damaging than Two-Hand Head Hit 1.'),
('string/en/cmd_d.stf', 856, 'melee2hheadhit3', '/melee2hheadhit3 <target>: This melee attack targets an opponent''s head in order to damage the target''s Mind pool.  This is more damaging than Two-Hand Head Hit 2.'),
('string/en/cmd_d.stf', 857, 'melee2hhit1', '/melee2hhit1 <target>: This melee attack inflicts more damage than the basic Two-Hand attack.'),
('string/en/cmd_d.stf', 858, 'melee2hhit2', '/melee2hhit2 <target>: This advanced melee attack inflicts more damage than Two-Hand Hit 1.'),
('string/en/cmd_d.stf', 859, 'melee2hhit3', '/melee2hhit3< target>: This powerful melee attack inflicts more damage than Two-Hand Hit 2.'),
('string/en/cmd_d.stf', 860, 'melee2hlunge1', '/melee2hlunge1 <target>: This melee attack allows you to slightly extend your range, and it can change the posture of your target.'),
('string/en/cmd_d.stf', 861, 'melee2hlunge2', '/melee2hlunge2 <target>: This melee attack allows you to slightly extend your range, and it can knock down your target.'),
('string/en/cmd_d.stf', 862, 'melee2hmindhit1', '/melee2hmindhit1 <target>: This melee attack targets the head in order to WOUND the target''s Mind pool.'),
('string/en/cmd_d.stf', 863, 'melee2hmindhit2', '/melee2hmindhit2 <target>: This melee attack targets an opponent''s head in order to WOUND the target''s Mind pool.  This is more damaging than than Two-Hand Mind Hit 1.'),
('string/en/cmd_d.stf', 864, 'melee2hspinattack1', '/melee2hspinattack1 <target>: This melee area attack can damage multiple targets at once.'),
('string/en/cmd_d.stf', 865, 'melee2hspinattack2', '/melee2hspinattack2 <target>: This melee area attack can damage multiple targets at once.  This is more damaging than Two-Hand Spin Attack 1.'),
('string/en/cmd_d.stf', 866, 'melee2hsweep1', '/melee2hsweep1 <target>: This melee attack can lower the posture of a single target.'),
('string/en/cmd_d.stf', 867, 'melee2hsweep2', '/melee2hsweep2 <target>: This melee area attack can lower the posture of multiple targets at once.'),
('string/en/cmd_d.stf', 868, 'melee_damage_mitigation_1', 'This skill will limit the damage range done to you when you are attacked with a melee weapon.'),
('string/en/cmd_d.stf', 869, 'melee_damage_mitigation_2', 'This ability will further limit the damage range done to you when you are attacked with a melee weapon.'),
('string/en/cmd_d.stf', 870, 'melee_damage_mitigation_3', 'This ability will further limit the damage range done to you when you are attacked with a melee weapon.'),
('string/en/cmd_d.stf', 871, 'melt', '/melt: You melt.\n/melt self: You melt into your own arms.\n/melt target: You melt into (his, her, or its) arms.'),
('string/en/cmd_d.stf', 872, 'merchant_fees_1', 'The merchant gains a reduction in the cost of using the Galactic Commodities Bazaar.'),
('string/en/cmd_d.stf', 873, 'mercy', '/mercy: You appeal for mercy.\n/mercy self: You appeal to your merciful side.\n/mercy target: You beg for mercy from (target name).'),
('string/en/cmd_d.stf', 874, 'mimic', '/mimic: You mimic passers-by.\n/mimic self: You mimic yourself.\n/mimic target: You mimic (target name).'),
('string/en/cmd_d.stf', 875, 'mindblast1', '/mindBlast1 <target>: This attack allows a Jedi to invade someone''s mind, causing a chance for the target to become stunned or dizzy, as well as dealing a moderate amount of damage to a random pool.'),
('string/en/cmd_d.stf', 876, 'mindblast2', '/mindBlast2 <target>: This attack allows a Jedi to project a wave of mental intrusion, dealing damage to a random pool of the target and those in the immediate area as well as causing a chance for those affected to become stunned, or dizzy.'),
('string/en/cmd_d.stf', 877, 'mindshot1', '/mindshot1 <target>: This ranged attack can wreak havoc with a target''s Mind pool drain and regeneration rates.'),
('string/en/cmd_d.stf', 878, 'mindshot2', '/mindshot2 <target>: This ranged attack can wreak havoc with a target''s Mind pool drain and regeneration rates.'),
('string/en/cmd_d.stf', 879, 'mirror', '/mirror: You hold up a mirror.\n/mirror self: You pull a mirror from your pack and check your appearance.\n/mirror target: You hold up a mirror up for (target name).'),
('string/en/cmd_d.stf', 880, 'mock', '/mock: You mock the chattering of the crowd.\n/mock self: You mock your own blabbering.\n/mock target: You mock (target name).'),
('string/en/cmd_d.stf', 881, 'model', '/model: You model your new outfit - so nice!\n/model self: You model your clothing for yourself, but there is no mirror here!\n/model target: You model for (target name).'),
('string/en/cmd_d.stf', 882, 'mope', '/mope: You mope.\n/mope self: You mope around.\n/mope target: You mope about (target name).'),
('string/en/cmd_d.stf', 883, 'mosh', '/mosh: You mosh about, bumping into everyone.\n/mosh self: You mosh by yourself, looking quite strange.\n/mosh target: You mosh into (target name).'),
('string/en/cmd_d.stf', 884, 'mount', '/mount: If it is appropriately trained, you have enough skill, it is your pet, and you are close enough, this command will mount the pet you are currently looking at.'),
('string/en/cmd_d.stf', 885, 'mourn', '/mourn: You mourn.\n/mourn self: You mourn the loss of friends.\n/mourn target: You mourn for (target name).'),
('string/en/cmd_d.stf', 886, 'multitargetpistolshot', '/multitargetpistolshot <target>: This ranged attack for pistols can hit multiple targets at once. '),
('string/en/cmd_d.stf', 887, 'multitargetshot', '/multitargetshot <target>: This ranged attack can hit multiple targets at once.'),
('string/en/cmd_d.stf', 888, 'musician', 'This ability allows you to perform musician commands.'),
('string/en/cmd_d.stf', 889, 'mutedroid', 'This command sets the astromech/flight-computer interface to a non-audible setting. No further feedback should be heard from the ship-board systems management droid or flight-computer, whatever the case may be.'),
('string/en/cmd_d.stf', 890, 'mutter', '/mutter: You mutter.\n/mutter self: You mutter about yourself.\n/mutter target: You mutter something snide about (target name).'),
('string/en/cmd_d.stf', 891, 'nails', '/nails: You drag your nails down a stony surface creating an annoying, high-pitched sound.\n/nails self: You blow on your nails and buff them on your clothes.\n/nails target: You drag the edge of a fingernail down the side of (him, her, or it) neck.'),
('string/en/cmd_d.stf', 892, 'nalargon', 'This ability allows you to plays songs with the Nalargon instrument.'),
('string/en/cmd_d.stf', 893, 'namestructure', 'This command allows the user to name a structure.'),
('string/en/cmd_d.stf', 894, 'nap', '/nap: You take a quick nap.\n/nap self: You find a nice place to rest and settle in for a quick nap.\n/nap target: You curl up in (his, her, or its) lap and settle in for a catnap.'),
('string/en/cmd_d.stf', 895, 'nausea', '/nausea: You feel nauseous.\n/nausea self: You suddenly feel nauseous and quickly cover your mouth.\n/nausea target: You look at (target name), suddenly feeling nauseous.'),
('string/en/cmd_d.stf', 896, 'nblast', '/nblast: This command only works while the pilot is inside a nebula, where it triggers an explosion.'),
('string/en/cmd_d.stf', 897, 'nelson', '/nelson: You practice your full nelson maneuver.\n/nelson self: You try to put yourself in a full nelson.\n/nelson target: With a single swift move, you put (target name) in a full nelson.'),
('string/en/cmd_d.stf', 898, 'newbiehelper', 'This allows others to recognize you as a new player helper.'),
('string/en/cmd_d.stf', 899, 'nextcraftingstage', 'This command allows the user to enter the next crafting stage.'),
('string/en/cmd_d.stf', 900, 'nod', '/nod: You nod.\n/nod self: You nod at yourself reassuringly.\n/nod target: You nod at (target name).'),
('string/en/cmd_d.stf', 901, 'nono', '/nono: You wag your finger as if saying, "No-No".\n/nono self: You decline with the shake of an opened hand.\n/nono target: You wag a finger negatively at (target name).'),
('string/en/cmd_d.stf', 902, 'noogie', '/noogie: You look for a noogie target.\n/noogie self: You give yourself a noogie.\n/noogie target: You give (him, her, or it) a noogie.'),
('string/en/cmd_d.stf', 903, 'nose', '/nose: You put your nose in the air.\n/nose self: You touch the tip of your nose.\n/nose target: You raise your nose at (target name).'),
('string/en/cmd_d.stf', 904, 'npcconversationselect', 'This command allows the user to select a conversation with an NPC.'),
('string/en/cmd_d.stf', 905, 'npcconversationstart', 'This command is used to start a conversation with an NPC.'),
('string/en/cmd_d.stf', 906, 'npcconversationstop', 'This command stops a conversation with an NPC.'),
('string/en/cmd_d.stf', 907, 'nudge', '/nudge: You nudge everyone.\n/nudge self: You try to nudge yourself.\n/nudge target: You nudge (him, her, or it).'),
('string/en/cmd_d.stf', 908, 'nuzzle', '/nuzzle: You make a nuzzling motion.\n/nuzzle self: You nuzzle yourself.\n/nuzzle target: You nuzzle (his, her, or its) neck.'),
('string/en/cmd_d.stf', 909, 'omg', '/omg: OMG!\n/omg self: You clasp your hand over your forehead and exclaim, "Oh my gosh!"\n/omg target: Oh my gosh, (target name)!'),
('string/en/cmd_d.stf', 910, 'omnibox', 'This ability allows you to plays songs with the Ommni Box instrument.'),
('string/en/cmd_d.stf', 911, 'oneknee', '/oneknee: You take a knee.\n/oneknee self: You take a knee and bow your head.\n/oneknee target: You take a knee before (target name).'),
('string/en/cmd_d.stf', 912, 'opossum', '/opossum: You play dead.\n/opossum self: You keel over and play dead.\n/opossum target: You look with fear upon (target name), fall to the ground, and play dead.'),
('string/en/cmd_d.stf', 913, 'overchargeshot1', '/overchargeshot1 <target>: This ranged attack causes more damage to a target at the expense of your weapon''s power supply.'),
('string/en/cmd_d.stf', 914, 'overchargeshot2', '/overchargeshot2 <target>: This ranged attack causes more damage to a target at the expense of your weapon''s power supply.  This attack is more damaging than Overcharge Shot 1.'),
('string/en/cmd_d.stf', 915, 'panic', '/panic: AAAAAAYYYYYYEEEEEEEE!!!\n/panic self: You panic about, waving your hands in the air.\n/panic target: You panic about (target name), waving your hands in the air.'),
('string/en/cmd_d.stf', 916, 'panicshot', '/panicshot <target>: A pistol attack that launches a series of wild shots to surprise enemies in the cone of fire.  Enemies surprised this way will have their next action delayed.'),
('string/en/cmd_d.stf', 917, 'pant', '/pant: You pant.\n/pant self: You hang your tongue out and pant like a dog.\n/pant target: You pant at (target name).'),
('string/en/cmd_d.stf', 918, 'pat', '/pat: You pat your head.\n/pat self: You pat yourself on the back.\n/pat target: You pat (him, her, or it) on the head.'),
('string/en/cmd_d.stf', 919, 'pawithdraw', 'Pawithdraw'),
('string/en/cmd_d.stf', 920, 'paymaintenance', 'This command can be used to pay maintenance on a building or mining structure.'),
('string/en/cmd_d.stf', 921, 'payup', '/payup: You expect to be reimbursed!\n/payup self: Did you really owe yourself?\n/payup target: You ask (target name) to pay up!'),
('string/en/cmd_d.stf', 922, 'peace', '/peace: Peace allows you to stop attacking a target.  If you are attacked again after initiating peace, you will automatically re-initiate combat.'),
('string/en/cmd_d.stf', 923, 'peer', '/peer: You peer around.\n/peer self: You peer at yourself.\n/peer target: You peer at (target name). What is (he, she or it) up to?'),
('string/en/cmd_d.stf', 924, 'peptalk', '/peptalk: GO TEAM!\n/peptalk self: GO ME!\n/peptalk target: You can do it, (target name)!'),
('string/en/cmd_d.stf', 925, 'performcolorlights', '/performcolorlights: This is an Entertainer visual flourish.'),
('string/en/cmd_d.stf', 926, 'performdazzle', '/performdazzle: This is an Entertainer visual flourish.'),
('string/en/cmd_d.stf', 927, 'performdistract', '/performdistract: This is an Entertainer visual flourish.'),
('string/en/cmd_d.stf', 928, 'performfirejets', '/performfirejets: This is an Entertainer visual flourish.'),
('string/en/cmd_d.stf', 929, 'performsmokebomb', '/performsmokebomb: This is an Entertainer visual flourish.'),
('string/en/cmd_d.stf', 930, 'performspotlight', '/performspotlight: This is an Entertainer visual flourish.'),
('string/en/cmd_d.stf', 931, 'performventriloquism', '/performventriloquism <target>: This is an Entertainer trick flourish.'),
('string/en/cmd_d.stf', 932, 'pet', '/pet: You cradle your arms and pet an imaginary creature.\n/pet self: You pet yourself.\n/pet target: You pet (target name).'),
('string/en/cmd_d.stf', 933, 'pet_attack', '/pet attack <target>: This command will enable you to cause your pet to attack your target.'),
('string/en/cmd_d.stf', 934, 'pet_follow', '/pet follow: This command makes your pet follow you around.'),
('string/en/cmd_d.stf', 935, 'pet_followother', '/pet followother <target>: This command instructs your pet to follow the target you have indicated.'),
('string/en/cmd_d.stf', 936, 'pet_formation', '/pet formation: This enables you to bring multiple pets into a pre-determined formation, such as a wedge.'),
('string/en/cmd_d.stf', 937, 'pet_friend', '/pet friend <target>: This causes your pet to make friends with a target.'),
('string/en/cmd_d.stf', 938, 'pet_group', '/pet group: This command enables you to add your pets to your group.  This makes them much easier to target quickly.'),
('string/en/cmd_d.stf', 939, 'pet_guard', '/pet guard: This command causes your pets to guard an indiviual (target another player, tell your pet to guard, and the pet will automatically defend that player).'),
('string/en/cmd_d.stf', 940, 'pet_patrol', '/pet patrol: This command causes your pets to patrol in a small area.'),
('string/en/cmd_d.stf', 941, 'pet_rangedattack', '/pet ranged attack:  This command makes your pet use its ranged attack (if  it has one)'),
('string/en/cmd_d.stf', 942, 'pet_release', '/pet store: This command stores the pet back into your pet control device.'),
('string/en/cmd_d.stf', 943, 'pet_specialattack1', '/pet special attack one:  This command makes your pet use its primary special attack (if  it has one)'),
('string/en/cmd_d.stf', 944, 'pet_specialattack2', '/pet special attack two:  This command makes your pet use its secondary special attack (if  it has one)'),
('string/en/cmd_d.stf', 945, 'pet_stay', '/pet stay: This command makes your pet stay where it is.'),
('string/en/cmd_d.stf', 946, 'pet_transfer', '/pet transfer <target>: This command enables you to give your pets to another person.  You are only able to give pets to another Creature Handler.'),
('string/en/cmd_d.stf', 947, 'pethigh', '/pethigh: You reach up and pet... what is that you''re petting?\n/pethigh self: You pet yourself.\n/pethigh target: You pet (target name).'),
('string/en/cmd_d.stf', 948, 'petlow', '/petlow: You reach down and pet... what is that you''re petting?\n/petlow self: You pet yourself.\n/petlow target: You pet (target name).'),
('string/en/cmd_d.stf', 949, 'peyoo', '/peyoo: PEEEEEYYYOOOO!!\n/peyoo self: You sniff yourself and realize you reek.\n/peyoo target: You look at (him, her, or it) with a sour face and try to waft the stench away.'),
('string/en/cmd_d.stf', 950, 'pillow', '/pillow: PILLOW FIGHT!\n/pillow self: You tear up a pillow, sending feathers everywhere.\n/pillow target: You throw a pillow at (him, her, or it).'),
('string/en/cmd_d.stf', 951, 'pinch', '/pinch: You make pinching motions like a shenk.\n/pinch self: Are you dreaming?\n/pinch target: You pinch (him, her, or it).'),
('string/en/cmd_d.stf', 952, 'pistolmeleedefense1', '/pistolmeleedefense1 <target>: This melee attack with your pistol is useful for close encounters. '),
('string/en/cmd_d.stf', 953, 'pistolmeleedefense2', '/pistolmeleedefense2 <target>: This melee attack with your pistol is useful for close encounters.  This is more damaging than Pistol Melee Defense 1.'),
('string/en/cmd_d.stf', 954, 'place_bank', 'Grants the Politician the ability to construct new banks in a city he controls.'),
('string/en/cmd_d.stf', 955, 'place_cantina', 'This gives you the ability to place and run your own Cantina.  Cantinas must be placed within a player city.'),
('string/en/cmd_d.stf', 956, 'place_cityhall', 'With this ability the politician can create a new city by placing a City Hall.  A new city MUST have 10 citizens (including the Mayor) within 24 hours of creation in order to be approved by the Planetary Civic Authority.'),
('string/en/cmd_d.stf', 957, 'place_cloning', 'This gives you the ability to place a Cloning Facility within a player city.'),
('string/en/cmd_d.stf', 958, 'place_exotic_garden', 'This ability lets the politician place an exotic decorative garden within his city borders.'),
('string/en/cmd_d.stf', 959, 'place_faction_terminal', 'This ability allows the mayor to place faction aligned mission terminals in their city.'),
('string/en/cmd_d.stf', 960, 'place_fountain', 'This ability lets the politician place a decorative fountain within his city borders.'),
('string/en/cmd_d.stf', 961, 'place_garage', 'This allows you to place a Garage within the city limits.'),
('string/en/cmd_d.stf', 962, 'place_hospital', 'This gives you the ability to place and run your own Hospital.  Hospitals must be placed within a player city.'),
('string/en/cmd_d.stf', 963, 'place_large_garden', 'This ability lets the politician place a large decorative garden within his city borders.'),
('string/en/cmd_d.stf', 964, 'place_medium_garden', 'This ability lets the politician place a medium decorative garden within his city borders.'),
('string/en/cmd_d.stf', 965, 'place_merchant_tent', 'Gives the merchant the ability to place a unique looking tent from which to sell goods.'),
('string/en/cmd_d.stf', 966, 'place_shuttleport', 'Grants the Politician the ability to construct new shuttleports in a city he controls.'),
('string/en/cmd_d.stf', 967, 'place_small_garden', 'This ability lets the politician place a small decorative garden within his city borders.'),
('string/en/cmd_d.stf', 968, 'place_statue', 'This ability lets the politician place a decorative statue within his city borders.'),
('string/en/cmd_d.stf', 969, 'place_streetlamp', 'This ability lets the politician place a decorative streetlamp within his city borders.'),
('string/en/cmd_d.stf', 970, 'place_theater', 'This gives you the ability to place and run your own Theater.  Theaters must be placed within a player city.'),
('string/en/cmd_d.stf', 971, 'placebattlefieldstructure', 'This command allows the user to place a battlefield structure.'),
('string/en/cmd_d.stf', 972, 'placestructuremode', 'This command allows the user to go into the place structure mode.'),
('string/en/cmd_d.stf', 973, 'plugears', '/plugears: You plug your ears.\n/plugears self: You stick your fingers in your ears.\n/plugears target: You plug your ears and try to tune (him, her, or it) out. LA LA LA LA LA.'),
('string/en/cmd_d.stf', 974, 'plugnose', '/plugnose: You pinch your nose shut.\n/plugnose self: You pinch your nose shut with a clothes pin.\n/plugnose target: You plug your nose at (target name)''s stench.'),
('string/en/cmd_d.stf', 975, 'point', '/point: You point the way.\n/point self: You point at yourself.\n/point target: You point at (target name).'),
('string/en/cmd_d.stf', 976, 'pointat', '/pointat:  You point the way.\n/pointat self:  You point at yourself.\n/pointat target:  You point at (target name).'),
('string/en/cmd_d.stf', 977, 'pointblankarea1', '/pointblankarea1 <target>: This ranged area attack can be performed at point blank range without suffering a penalty to hit.'),
('string/en/cmd_d.stf', 978, 'pointblankarea2', '/pointblankarea2 <target>: This advanced ranged area attack can be performed at point blank range without suffering a penalty to hit. This particular maneuver has an increased chance to cause more damage than Point Blank Area 1.'),
('string/en/cmd_d.stf', 979, 'pointblanksingle1', '/pointblanksingle1 <target>: This ranged attack can be performed at point blank range without suffering a penalty to hit.'),
('string/en/cmd_d.stf', 980, 'pointblanksingle2', '/pointblanksingle2 <target>: This ranged attack can be performed at point blank range without suffering a penalty to hit.  This move is more damaging than Point Blank Single 1.'),
('string/en/cmd_d.stf', 981, 'pointdown', '/pointdown: You point at the ground.\n/pointdown self: You''re staying right here!\n/pointdown target: You tell (target name) to stay right here.'),
('string/en/cmd_d.stf', 982, 'pointleft', '/pointleft: You point left.\n/pointleft self: You point left.\n/pointleft target: You turn to (target name) and point left.'),
('string/en/cmd_d.stf', 983, 'pointright', '/pointright: You point right.\n/pointright self: You point right.\n/pointright target: You turn to (target name) and point right.'),
('string/en/cmd_d.stf', 984, 'pointup', '/pointup: You point up.\n/pointup self: You point up.\n/pointup target: You turn to (target name) and point up.'),
('string/en/cmd_d.stf', 985, 'poke', '/poke: Poke. Poke.\n/poke self: You poke yourself in the ribs, looking very sheepish.\n/poke target: You poke (him, her, or it) in the ribs.'),
('string/en/cmd_d.stf', 986, 'polearmactionhit1', '/polearmactionhit1 <target>: This polearm attack targets an opponent''s legs in order to WOUND a target''s Action pool.'),
('string/en/cmd_d.stf', 987, 'polearmactionhit2', '/polearmactionhit2 <target>: This polearm attack targets an opponent''s legs in order to WOUND a target''s Action pool.  It can inflict more wound damage than Polearm Action Hit 1.'),
('string/en/cmd_d.stf', 988, 'polearmarea1', '/polearmarea1 <target>: This polearm area attack can damage multiple targets at once.'),
('string/en/cmd_d.stf', 989, 'polearmarea2', '/polearmarea2 <target>: This polearm area attack can damage, dizzy, and stun multiple targets at once.  It is more powerful than Polearm Area 1.'),
('string/en/cmd_d.stf', 990, 'polearmhit1', '/polearmhit1 <target>: This polearm attack causes more damage than the default polearm attack.'),
('string/en/cmd_d.stf', 991, 'polearmhit2', '/polearmhit2 <target>: This polearm attack inflicts more damage than Polearm Hit 1, and can stun a target.'),
('string/en/cmd_d.stf', 992, 'polearmhit3', '/polearmhit3 <target>: This powerful polearm attack inflicts more damage than Polearm Hit 2, and can stun and lower the posture of a target.'),
('string/en/cmd_d.stf', 993, 'polearmleghit1', '/polearmleghit1 <Target>: This polearm attack targets an opponent''s legs in order to damage a target''s Action pool.'),
('string/en/cmd_d.stf', 994, 'polearmleghit2', '/polearmleghit2 <target>: This polearm attack targets an opponent''s legs in order to damage a target''s Action pool.  This is more damaging than Polearm Leg Hit 1.'),
('string/en/cmd_d.stf', 995, 'polearmleghit3', '/polearmleghit3 <target>: This polearm attack targets an opponent''s legs in order to damage a target''s Action pool.  This is more damaging than Polearm Leg Hit 2.'),
('string/en/cmd_d.stf', 996, 'polearmlunge1', '/polearmlunge1 <target>: This polearm attack allows you to slightly extend your range, and it can change the posture of your target.'),
('string/en/cmd_d.stf', 997, 'polearmlunge2', '/polearmlunge2 <target>: This polearm attack allows you to slightly extend your range, and it can knock down your target.'),
('string/en/cmd_d.stf', 998, 'polearmspinattack1', '/polearmspinattack1 <target>: This polearm attack can damage multiple targets at once, by spinning your body slightly while attacking.'),
('string/en/cmd_d.stf', 999, 'polearmspinattack2', '/polearmspinattack2 <target>: This polearm area attack can damage and dizzy multiple targets at once, by spinning your body slightly while attacking.  This is more damaging than Polarm Spin Attack 1.'),
('string/en/cmd_d.stf', 1000, 'polearmstun1', '/polearmstun1 <target>: This polearm attack can stun a single target.'),
('string/en/cmd_d.stf', 1001, 'polearmstun2', '/polearmstun2 <target>: This polearm area attack can stun multiple targets at once.'),
('string/en/cmd_d.stf', 1002, 'polearmstunhit1', '/polearmstunhit1 <target>: This polearm attack has the ability to stun a single enemy for a short duration.'),
('string/en/cmd_d.stf', 1003, 'polearmsweep1', '/polearmsweep1 <target>: This polearm sweep attack can knock down a single target.'),
('string/en/cmd_d.stf', 1004, 'polearmsweep2', '/polearmsweep2 <target>: This polearm area sweep attack can knock down multiple targets at once.'),
('string/en/cmd_d.stf', 1005, 'ponder', '/ponder: You ponder.\n/ponder self: You ponder your existence.\n/ponder target: You ponder about (him, her, or it). Hrmmm.'),
('string/en/cmd_d.stf', 1006, 'posturedownattack', 'This command utilizes the posture down attack.'),
('string/en/cmd_d.stf', 1007, 'postureupattack', 'This command utilizes the posture up attack.'),
('string/en/cmd_d.stf', 1008, 'pound', '/pound: You pound on your chest!\n/pound self: You pound on your chest, daring anyone to take you on.\n/pound target: You pound your chest. Will (target name) take you on?'),
('string/en/cmd_d.stf', 1009, 'pout', '/pout: You pout.\n/pout self: You pout at yourself.\n/pout target: You pout at (him, her, or it).'),
('string/en/cmd_d.stf', 1010, 'powerboost', '/powerboost: This meditative art allows the user to channel mental energies into their physical form for a temporary boost to physical performance. However, such extreme mental activities cause a significantly exhausting psychological cost.'),
('string/en/cmd_d.stf', 1011, 'preen', '/preen: You preen.\n/preen self: You preen like a feline.\n/preen target: You preen gloatingly at (him, her, or it).'),
('string/en/cmd_d.stf', 1012, 'premium_auctions', 'For an additional fee, you can place a Premium Auction on the bazaar.  These auctions are highlighted on the list of sales, drawing additional attention to your item.'),
('string/en/cmd_d.stf', 1013, 'primp', '/primp: You primp.\n/primp self: You pull a mirror from your pack and primp yourself.\n/primp target: You primp yourself for (target name).'),
('string/en/cmd_d.stf', 1014, 'prod', '/prod: You extract a nerf prod from your pack and brandish it smugly.\n/prod self: You prod yourself into action.\n/prod target: You prod (him, her, or it), trying to evoke some emotion.'),
('string/en/cmd_d.stf', 1015, 'prone', '/prone: Going prone brings you into a laying position, which prohibits movement and makes you more vulnerable to melee attacks, but allows for better ranged accuracy than standing or kneeling.'),
('string/en/cmd_d.stf', 1016, 'protect', '/protect: You stand your ground.\n/protect self: You indicate that you need protection.\n/protect target: You stand defensively in front of (target name).'),
('string/en/cmd_d.stf', 1017, 'provoke', '/provoke'),
('string/en/cmd_d.stf', 1018, 'pshrug', '/pshrug:  You shrug philosophically.\n/pshrug self:  You shrug your shoulders philosophically.\n/pshrug target:  You shrug philosophically at (target name).'),
('string/en/cmd_d.stf', 1019, 'ptrap1', '/ptrap1: This command suckers a group of pirates to the local area, where they''ll probably attack just about everything.'),
('string/en/cmd_d.stf', 1020, 'ptrap2', '/ptrap2: This command suckers a strong group of pirates to the local area, where they''ll probably attack just about everything.'),
('string/en/cmd_d.stf', 1021, 'pucker', '/pucker: You pucker.\n/pucker self: You make a sour face and pucker.\n/pucker target: You pucker and make "fish faces" at (him, her, or it).'),
('string/en/cmd_d.stf', 1022, 'puke', '/puke: You puke.\n/puke self: You puke all over yourself.\n/puke target: You puke all over (him, her, or it).');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/cmd_d.stf', 1023, 'pull', '/pull: You call out, "PULL!"\n/pull self: You raise your hand in the air and pull it back down in a victorious manner.\n/pull target: You try to pull (him, her, or it) along.'),
('string/en/cmd_d.stf', 1024, 'pumpreactor', '/pumpreactor: Temporarily increases reactor and engine output.'),
('string/en/cmd_d.stf', 1025, 'punch', '/punch: You shadow-box.\n/punch self: You punch yourself in the face, giving yourself a black eye.\n/punch target: You punch (target name) in the face.'),
('string/en/cmd_d.stf', 1026, 'purchasereinforcement', 'This command utilizes the purchase reinforcement option.'),
('string/en/cmd_d.stf', 1027, 'purchaseticket', 'This command allows the user to purchase a ticket.'),
('string/en/cmd_d.stf', 1028, 'push', '/push: You make a pushing motion as if trying to keep things away from yourself.\n/push self: You push yourself to the ground.\n/push target: You push (him, her, or it) away.'),
('string/en/cmd_d.stf', 1029, 'puzzle', '/puzzle: You puzzle over the current situation.\n/puzzle self: You puzzle over your own thoughts.\n/puzzle target: You puzzle over (him, her, or it).'),
('string/en/cmd_d.stf', 1030, 'question', '/question: You question the intent.\n/question self: You question your own intent.\n/question target: You question (his, her, or its) intent.'),
('string/en/cmd_d.stf', 1031, 'quickheal', '/quickheal <target>: This ability allows for an instant, medicine-free pool damage heal on a target, at a very heavy Mind cost to the Medic.  This ability also causes 10 Wounds to the Medic''s Willpower and Focus pools, so it must not be used lightly.'),
('string/en/cmd_d.stf', 1032, 'quiet', '/quiet: You hold your finger to your lips, indicating to be quiet.\n/quiet self: You quiet yourself and place your finger vertically across your lips.\n/quiet target: You hold an extended finger over your lips, indicating to (target name) to be quiet.'),
('string/en/cmd_d.stf', 1033, 'r', '/r'),
('string/en/cmd_d.stf', 1034, 'raise', '/raise: You raise your hand.\n/raise self: You raise your hands in the air.\n/raise target: You raise (his, her, or its) hand and declare (him, her, or it) the victor.'),
('string/en/cmd_d.stf', 1035, 'rally', '/rally: This Squad Leader command improves the combat defense and to hit modifiers of everyone in the party.  The Squad Leader must be the party''s leader in order for this to function.'),
('string/en/cmd_d.stf', 1036, 'ranged_damage_mitigation_1', 'This ability will limit the damage range done to you when you are attacked with a ranged weapon.'),
('string/en/cmd_d.stf', 1037, 'ranged_damage_mitigation_2', 'This ability will further limit the damage range done to you when you are attacked with a ranged weapon.'),
('string/en/cmd_d.stf', 1038, 'ranged_damage_mitigation_3', 'This ability will further limit the damage range done to you when you are attacked with a ranged weapon.'),
('string/en/cmd_d.stf', 1039, 'raspberry', '/raspberry: You give everyone a raspberry. PFFFFFFTTTT!!\n/raspberry self: You give yourself a raspberry.\n/raspberry target: You give (him, her, or it) a raspberry.'),
('string/en/cmd_d.stf', 1040, 'ready', '/ready: READY!\n/ready self: You check to see if you are ready.\n/ready target: I''m ready, (target name)!'),
('string/en/cmd_d.stf', 1041, 'reassure', '/reassure: You reassure everyone that it will turn out OK.\n/reassure self: You reassure yourself that everything will be OK.\n/reassure target: You reassure (him, her, or it) that everything will be fine.'),
('string/en/cmd_d.stf', 1042, 'recruitskilltrainer', '/recruitskilltrainer: Allows the politician to place a skill trainer within the borders of his city.'),
('string/en/cmd_d.stf', 1043, 'regainconsciousness', '/regainConsciousness: This ability allows a Jedi to instantly recover from an unconscious state.  The Jedi will still be weak and weary but can then proceed to use other Force abilities to return to normal.'),
('string/en/cmd_d.stf', 1044, 'regeneration', '/regeneration: short-term consitution attribute buff; alias for "/innate regeneration"'),
('string/en/cmd_d.stf', 1045, 'registered', 'Your city has been registered on the planetary map.'),
('string/en/cmd_d.stf', 1046, 'registerwithlocation', 'Provided the appropriate skill-set for the venue, this command allows the user to register with an inactive planetary map location marking it as active ("manned").'),
('string/en/cmd_d.stf', 1047, 'reload', 'This command allows the user to reload.'),
('string/en/cmd_d.stf', 1048, 'repairbattlefieldstructure', 'This command allows the user to repair a battlefield structure.'),
('string/en/cmd_d.stf', 1049, 'repairshipcomponent', 'Repair  a ship component in a ship.'),
('string/en/cmd_d.stf', 1050, 'reply', '/reply <message>: Automatically sends a /tell to the last person who sent you one.'),
('string/en/cmd_d.stf', 1051, 'requestcraftingsession', 'This command requests a crafting session for the user.'),
('string/en/cmd_d.stf', 1052, 'rescue', '/rescue <target>: This enables you to anger an NPC that is on a party member, so that the NPC attacks you instead of the person you are rescuing.  This is not guaranteed to work.'),
('string/en/cmd_d.stf', 1053, 'restartcraftingsession', 'This command allows the user to restart a crafting session.'),
('string/en/cmd_d.stf', 1054, 'retell', '/retell'),
('string/en/cmd_d.stf', 1055, 'retreat', '/retreat:  This very powerful Squad Leader ability drains the Squad Leader''s Action and Mind pools while giving their entire group Burst Run.  Intended for hard encounters gone horribly wrong, it allows the Squad Leader to show true leadership by sacrificing themself for the greater good of their group.'),
('string/en/cmd_d.stf', 1056, 'reviveplayer', '/reviveplayer <target>: This very powerful command enables you to revive an almost dead player, bypassing the need to clone if you have the appropriate medical equipment handy.'),
('string/en/cmd_d.stf', 1057, 'right', '/right: You point right.\n/right self: You point right.\n/right target: You turn to (target name) and point right.'),
('string/en/cmd_d.stf', 1058, 'roar', '/roar: ROOOOOOAAAAARRRRRR!!!!\n/roar self: You roar loudly at yourself.\n/roar target: You roar loudly at (target name).'),
('string/en/cmd_d.stf', 1059, 'rofl', '/rofl: Want a hand getting up?\n/rofl self: You roll on the floor laughing at yourself.\n/rofl target: You roll on the floor laughing at (target name).'),
('string/en/cmd_d.stf', 1060, 'roleplay', '/roleplay'),
('string/en/cmd_d.stf', 1061, 'roll', '/roll: You roll your eyes.\n/roll self: You roll your eyes and they fall back into your skull.\n/roll target: You rolls your eyes at (target name).'),
('string/en/cmd_d.stf', 1062, 'rolleyes', '/rolleyes:  You roll your eyes.\n/rolleyes self:  You roll your eyes and they fall back into your skull.\n/rolleyes target:  You roll your eyes at (target name).'),
('string/en/cmd_d.stf', 1063, 'rollshot', '/rollshot: A roll shot will cause you to kneel and attack at the same time, leaving you in a kneeling position.'),
('string/en/cmd_d.stf', 1064, 'rose', '/rose: You extend a rose and offer it.\n/rose self: You give yourself a rose and smell deeply of its scent.\n/rose target: You give (target name) a rose.  -----`---,---<@'),
('string/en/cmd_d.stf', 1065, 'rtell', '/rtell <message>: Automatically sends a tell to the last person whom you sent one to.'),
('string/en/cmd_d.stf', 1066, 'rubnose', '/rubnose: You rub your nose.\n/rubnose self: You rub your nose on your sleeve.\n/rubnose target: You rub noses with (target name).'),
('string/en/cmd_d.stf', 1067, 'rude', '/rude: You offer an unknown salute.\n/rude self: You give yourself a rude gesture.\n/rude target: You give (target name) an unknown salute.'),
('string/en/cmd_d.stf', 1068, 'ruffle', '/ruffle: You look ruffled.\n/ruffle self: You ruffle your own hair.\n/ruffle target: You ruffle (his, her, or its) hair.'),
('string/en/cmd_d.stf', 1069, 'saber1hcombohit1', '/saber1hComboHit1 <target>: This attack allows a Jedi to hit multiple locations on the target''s body. This attack will do more damage than a normal one-handed saber attack.'),
('string/en/cmd_d.stf', 1070, 'saber1hcombohit2', '/saber1hComboHit2 <target>: This attack allows a Jedi to hit multiple locations on the target''s body and has a chance to lower the target''s posture. This attack is more powerful than the Saber One Hand Combo Hit 1, and will likely do more damage.'),
('string/en/cmd_d.stf', 1071, 'saber1hcombohit3', '/saber1hComboHit3 <target>: This attack allows a Jedi to hit multiple locations on the target''s body and has a chance to lower the target''s posture. This attack is more powerful than the Saber One Hand Combo Hit 2, and will likely do more damage.'),
('string/en/cmd_d.stf', 1072, 'saber1hflurry', '/saber1hFlurry <target>: This attack allows a Jedi to perform a devastating move with a one-handed lightsaber that damages all enemies in the immediate area, as well as inflicting stun, blind, and dizziness.'),
('string/en/cmd_d.stf', 1073, 'saber1hflurry2', '/saber1hFlurry2 <target>: This ultimate attack allows a Jedi to perform a devastating move with a one-handed lightsaber that damages all enemies in the immediate area, as well as inflicting stun, blind, and dizziness.'),
('string/en/cmd_d.stf', 1074, 'saber1hheadhit1', '/saber1hHeadHit1 <target>: This attack allows a Jedi to perform a strike against the target''s head, increasing the chance of affecting its mind pool.'),
('string/en/cmd_d.stf', 1075, 'saber1hheadhit2', '/saber1hHeadHit2 <target>: This attack allows a Jedi to perform a strike against the target''s head,  increasing the chance of affecting its mind pool. This attack is more powerful than the Saber One Hand Head Hit 1, and has a chance of blinding the target.'),
('string/en/cmd_d.stf', 1076, 'saber1hheadhit3', '/saber1hHeadHit3 <target>: This attack allows a Jedi to perform a strike against the target''s head,  increasing the chance of affecting its mind pool. This attack is more powerful than the Saber One Hand Head Hit 2, and has a chance of blinding the target.'),
('string/en/cmd_d.stf', 1077, 'saber1hhit1', '/saber1hHit1 <target>: This attack allows a Jedi to do more damage than normal with a one-handed lightsaber.'),
('string/en/cmd_d.stf', 1078, 'saber1hhit2', '/saber1hHit2 <target>: This attack allows a Jedi to do significantly more damange than normal with a one-handed lightsaber. This attack is more powerful than the Saber One Hand Hit 1.'),
('string/en/cmd_d.stf', 1079, 'saber1hhit3', '/saber1hHit3 <target>: This attack allows a Jedi to do significantly more damange than normal with a one-handed lightsaber. This attack is more powerful than the Saber One Hand Hit 2.'),
('string/en/cmd_d.stf', 1080, 'saber2hbodyhit1', '/saber2hBodyHit1 <target>: This attack allows a Jedi to perform a strike against the target''s body, increasing the chance of affecting its health pool.'),
('string/en/cmd_d.stf', 1081, 'saber2hbodyhit2', '/saber2hBodyHit2 <target>: This attack allows a Jedi to perform a strike against the target''s body, increasing the chance of affecting its health pool. This attack is more powerful than Saber Two Hand Body Hit 1.'),
('string/en/cmd_d.stf', 1082, 'saber2hbodyhit3', '/saber2hBodyHit3 <target>: This attack allows a Jedi to perform a strike against the target''s body, increasing the chance of affecting its health pool. This attack is more powerful than Saber Two Hand Body Hit 2.'),
('string/en/cmd_d.stf', 1083, 'saber2hfrenzy', '/saber2hFrenzy <target>: This attack allows a Jedi to perform a devastating move with a two-handed lightsaber that damages all enemies in the immediate area, as well as inflicting stun, blind, and dizziness.'),
('string/en/cmd_d.stf', 1084, 'saber2hhit1', '/saber2hHit1 <target>: This attack allows a Jedi to do more damage than normal with a two-handed lightsaber.'),
('string/en/cmd_d.stf', 1085, 'saber2hhit2', '/saber2hHit2 <target>: This attack allows a Jedi to do significantly more damage than normal with a two-handed lightsaber. This attack is more powerful than Saber Two Hand Hit 1.'),
('string/en/cmd_d.stf', 1086, 'saber2hhit3', '/saber2hHit3 <target>: This attack allows a Jedi to do much more damage than normal with a two-handed lightsaber. This attack is more powerful than Saber Two Hand Hit 2.'),
('string/en/cmd_d.stf', 1087, 'saber2hphantom', '/saber2hFrenzy <target>: This ultimate attack allows a Jedi to perform a devastating move with a two-handed lightsaber that damages all enemies in a cone radius outwards from the Jedi, as well as inflicting stun, blind, and dizziness.'),
('string/en/cmd_d.stf', 1088, 'saber2hsweep1', '/saber2hSweep1 <target>: This attack allows a Jedi to cause their target to lower its posture.'),
('string/en/cmd_d.stf', 1089, 'saber2hsweep2', '/saber2hSweep2 <target>: This attack allows a Jedi to cause their target to lower its posture, as well as a small damage increase over Saber Two Hand Sweep 1.'),
('string/en/cmd_d.stf', 1090, 'saber2hsweep3', '/saber2hSweep3 <target>: This attack allows a Jedi to cause their target to lower its posture, as well as dealing more damage than Saber Two Hand Sweep 2.'),
('string/en/cmd_d.stf', 1091, 'saber_block', 'Allows a Jedi to block many types of energy bolts and several types of projectiles with a lightsaber.'),
('string/en/cmd_d.stf', 1092, 'saberpolearmdervish', '/saberPolearmDervish <target>: This attack allows a Jedi to perform a devastating move with a double-bladed lightsaber that damages all enemies in the immediate area, as well as inflicting stun, blind, and dizzyness.'),
('string/en/cmd_d.stf', 1093, 'saberpolearmdervish2', '/saberPolearmDervish2 <target>: This ultimate attack allows a Jedi to perform a devastating move with a double-bladed lightsaber that damages all enemies in a cone radius outward from the Jedi, as well as inflicting stun, blind, and dizzyness.'),
('string/en/cmd_d.stf', 1094, 'saberpolearmhit1', '/saberPolearmHit1 <target>: This attack allows a Jedi to do more damage than normal with a double-bladed lightsaber.'),
('string/en/cmd_d.stf', 1095, 'saberpolearmhit2', '/saberPolearmHit2 <target>: This attack allows a Jedi to do significantly more damage than normal with a double-bladed lightsaber. This attack is more powerful than the Saber Polearm Hit 1, and also has a chance to stun the target.'),
('string/en/cmd_d.stf', 1096, 'saberpolearmhit3', '/saberPolearmHit3 <target>: This attack allows a Jedi to do significantly more damage than normal with a double-bladed lightsaber. This attack is more powerful than the Saber Polearm Hit 2, and also has a chance to stun the target.'),
('string/en/cmd_d.stf', 1097, 'saberpolearmleghit1', '/saberPolearmLegHit1 <target>: This attack allows a Jedi to perform a strike against the target''s legs, increasing the chance of affecting its action pool.'),
('string/en/cmd_d.stf', 1098, 'saberpolearmleghit2', '/saberPolearmLegHit2 <target>: This attack allows a Jedi to perform a precise against a target''s legs, increasing the chance of affecting its action pool. This attack is more powerful than the Saber Polearm Leg Hit 1.'),
('string/en/cmd_d.stf', 1099, 'saberpolearmleghit3', '/saberPolearmLegHit3 <target>: This attack allows a Jedi to perform a strike against a target''s legs, increasing the chance of affecting its action pool. This attack is more powerful than the Saber Polearm Leg Hit 2.'),
('string/en/cmd_d.stf', 1100, 'saberpolearmspinattack1', '/saberPolearmSpinAttack1 <target>: This attack allows a Jedi to deal damage to all enemies in the immediate area.'),
('string/en/cmd_d.stf', 1101, 'saberpolearmspinattack2', '/saberPolearmSpinAttack2 <target>: This attack allows a Jedi to do increased damage to all enemies in the immediate area. This attack is more powerful than Saber Polearm Spin Attack 1, and also has a slightly increased range.'),
('string/en/cmd_d.stf', 1102, 'saberpolearmspinattack3', '/saberPolearmSpinAttack3 <target>: This attack allows a Jedi to do increased damage to all enemies in the immediate area. This attack is more powerful than Saber Polearm Spin Attack 2, and also has a slightly increased range.'),
('string/en/cmd_d.stf', 1103, 'saberslash1', '/saberSlash1 <target>: This attack allows a Jedi to cause the target to bleed, as well as lower the target''s posture. This attack can be used with all lightsaber types.'),
('string/en/cmd_d.stf', 1104, 'saberslash2', '/saberSlash2 <target>: This attack allows a Jedi to cause the target to bleed, as well as lower the target''s posture. This attack is more powerful than Saber Slash 1 and can be used with all lightsaber types.'),
('string/en/cmd_d.stf', 1105, 'saberthrow1', '/saberThrow1 <target>: This attack allows a Jedi to attack from a distance by throwing his or her lightsaber.'),
('string/en/cmd_d.stf', 1106, 'saberthrow2', '/saberThrow2 <target>: This attack allows a Jedi to do greater damage from a distance by throwing his or her lightsaber and guiding it with the Force. A successful attack will also cause a chance to knock your opponent down.'),
('string/en/cmd_d.stf', 1107, 'saberthrow3', '/saberThrow3 <target>: This attack allows a Jedi to attack multiple targets from a distance by throwing his or her lightsaber and guiding it with the Force. A successful attack will also cause a chance to knock your opponent down.'),
('string/en/cmd_d.stf', 1108, 'salute', '/salute: You salute.\n/salute self: You stand at attention and salute yourself.\n/salute target: You salute (target name).'),
('string/en/cmd_d.stf', 1109, 'sample', 'The /sample command is used in conjunction with a sample tool.  When you /sample your character will take a sample of whatever resource you last selected from the sample tool UI.  This allows you to perform sampling without using the sample tool UI.'),
('string/en/cmd_d.stf', 1110, 'sampledna', '/sampledna <target>: This Bio-Engineer ability allows you to sample the DNA of a creature.  You must be fairly close to it for this to function correctly.'),
('string/en/cmd_d.stf', 1111, 'scare', '/scare: BOO!\n/scare self: You scare yourself.\n/scare target: You sneak up and try to scare (him, her, or it).'),
('string/en/cmd_d.stf', 1112, 'scared', '/scared: You jump and whip around to face the noise.\n/scared self: You shrink away, looking very scared.\n/scared target: You shrink away from (target name), looking very scared of (him, her, or it).'),
('string/en/cmd_d.stf', 1113, 'scattershot1', '/scattershot1 <target>: This ranged attack can hit multiple stat pools on a target at once.'),
('string/en/cmd_d.stf', 1114, 'scattershot2', '/scattershot2 <target>: This ranged attack can hit multiple stat pools on a target at once. This is a more damaging attack than Scatter Shot 1.'),
('string/en/cmd_d.stf', 1115, 'scold', '/scold: You produce a measuring stick and brandish it authoritatively.\n/scold self: You scold yourself with slap on the hand.\n/scold target: You scold (him, her, or it).'),
('string/en/cmd_d.stf', 1116, 'scowl', '/scowl: You scowl.\n/scowl self: You scowl at yourself.\n/scowl target: You scowl at (him, her, or it).'),
('string/en/cmd_d.stf', 1117, 'scratch', '/scratch: You scratch an itch.\n/scratch self: You scratch the nape of your neck pensively.\n/scratch target: You scratch (his, her, or its) back.'),
('string/en/cmd_d.stf', 1118, 'scream', '/scream: AAAARRRRRGGGGHHHHH!!!\n/scream self: You scream loudly at yourself in frustration.\n/scream target: You scream with frustration in (his, her, or its) ear.'),
('string/en/cmd_d.stf', 1119, 'seenoevil', '/seenoevil: SEE NO EVIL!!\n/seenoevil self: You peek through your fingers covering your eyes.\n/seenoevil target: You peek through your fingers at (target name).'),
('string/en/cmd_d.stf', 1120, 'selectdraftschematic', 'This command selects a draft schematic.'),
('string/en/cmd_d.stf', 1121, 'send', 'This command allows the user to send a tell or mail to another player.'),
('string/en/cmd_d.stf', 1122, 'serversysgroup', 'Server System Group'),
('string/en/cmd_d.stf', 1123, 'setformation', '/setformation: Set the formation that a group should use in space.'),
('string/en/cmd_d.stf', 1124, 'setformationslot', '/setformationslot: Set the targeted group member into a slot from 1 to 20.'),
('string/en/cmd_d.stf', 1125, 'setspokenlanguage', 'This command sets a spoken language.'),
('string/en/cmd_d.stf', 1126, 'shake', '/shake: You shake your head negatively.\n/shake self: You shake your head negatively at yourself.\n/shake target: You shake your head negatively at (him, her, or it).'),
('string/en/cmd_d.stf', 1127, 'sharpen', '/sharpen: You sharpen your nails.\n/sharpen self: You sharpen your teeth with a file.\n/sharpen target: You sharpen a blade menacingly at (him, her, or it).'),
('string/en/cmd_d.stf', 1128, 'shiver', '/shiver: You shiver.\n/shiver self: You shiver and rub your arms in an attempt to warm up.\n/shiver target: You shiver at the coldness surrounding (target name).'),
('string/en/cmd_d.stf', 1129, 'shoo', '/shoo: You ask everyone to just leave.\n/shoo self: You''re asking yourself to leave?\n/shoo target: You tell (target name) to leave.'),
('string/en/cmd_d.stf', 1130, 'shower', '/shower: You go to take a shower.\n/shower self: You shower yourself in water from a jug.\n/shower target: You politely inform (target name) that (he, she or it) needs to take a shower.'),
('string/en/cmd_d.stf', 1131, 'shrug', '/shrug: You shrug.\n/shrug self: You shrug your shoulders helplessly.\n/shrug target: You shrug helplessly at (target name).'),
('string/en/cmd_d.stf', 1132, 'shudder', '/shudder: You shudder.\n/shudder self: You shudder at the thought.\n/shudder target: You shudder at (him, her, or it).'),
('string/en/cmd_d.stf', 1133, 'shush', '/shush: SHUSH!\n/shush self: You shush yourself.\n/shush target: You quickly shush (him, her, or it).'),
('string/en/cmd_d.stf', 1134, 'sigh', '/sigh: You sigh.\n/sigh self: You sigh with relief.\n/sigh target: You sigh at (him, her, or it).'),
('string/en/cmd_d.stf', 1135, 'sit', '/sit: This command will bring you into a sitting position, from which combat is not possible.  If furniture is not present, you will sit on the ground.'),
('string/en/cmd_d.stf', 1136, 'skip', '/skip: You skip around the area.\n/skip self: You skip in figure eights.\n/skip target: You skip around (target name).'),
('string/en/cmd_d.stf', 1137, 'slap', '/slap: WAKE UP! You slap yourself in the face. *SMACK!*\n/slap self: You slap yourself silly.\n/slap target: You slap (him, her, or it) across the face.'),
('string/en/cmd_d.stf', 1138, 'slice_armor', 'With "Slicing: Armor" the smuggler gains the ability to make modifications to the stats of armor from the "Slice" radial menu option on the armor piece.'),
('string/en/cmd_d.stf', 1139, 'slice_containers', 'With "Slicing: Containers" smugglers get the option to hack into locked containers with a "Slice" radial menu option.'),
('string/en/cmd_d.stf', 1140, 'slice_sockets', 'With "Slicing: Sockets" the smuggler can hack equipment to potentially add an extra expansion socket to the item.'),
('string/en/cmd_d.stf', 1141, 'slice_terminals', 'With "Slicing: Terminals" the smuggler gains the ability to hack mission terminals for extra pay using the "Slice" radial menu option.'),
('string/en/cmd_d.stf', 1142, 'slice_weaponsadvanced', 'With "Slicing: Weapons (Advanced)" the smuggler gains the ability to make more effective modifications to the stats of a weapon from the "Slice" radial menu option on the weapon.'),
('string/en/cmd_d.stf', 1143, 'slice_weaponsbasic', 'With "Slicing: Weapons (Basic)" the smuggler gains the ability to make small modifications to the stats of a weapon from the "Slice" radial menu option on the weapon.'),
('string/en/cmd_d.stf', 1144, 'slit', '/slit: Someone''s gonna die.\n/slit self: You think you''re not long for this world.\n/slit target: You don''t think (target name) is long for this world.'),
('string/en/cmd_d.stf', 1145, 'slitherhorn', 'This ability allows you to plays songs with the Slitherhorn instrument.'),
('string/en/cmd_d.stf', 1146, 'slobber', '/slobber: Need a bib?\n/slobber self: You slobber all over yourself.\n/slobber target: You slobber all over (him, her, or it).'),
('string/en/cmd_d.stf', 1147, 'small', '/small: You hold your hands about 2 fists apart, signifying it was small.\n/small self: You guess that it would be small.\n/small target: You indicate to (target name) that is was small.'),
('string/en/cmd_d.stf', 1148, 'smell', '/smell: You smell the air.\n/smell self: You smell yourself.\n/smell target: You smell (him, her, or it).'),
('string/en/cmd_d.stf', 1149, 'smile', '/smile: You smile.\n/smile self: You smile at yourself.\n/smile target: You smile at (target name).'),
('string/en/cmd_d.stf', 1150, 'smirk', '/smirk: You smirk.\n/smirk self: You smirk at yourself.\n/smirk target: You smirk at (target name).'),
('string/en/cmd_d.stf', 1151, 'smokebomb', '/smokebomb: Performs a smoke cloud effect.'),
('string/en/cmd_d.stf', 1152, 'snap', '/snap: SNAP!\n/snap self: Shucks!\n/snap target: You snap beckoningly at (him, her, or it).'),
('string/en/cmd_d.stf', 1153, 'snarl', '/snarl: You snarl, baring your teeth.\n/snarl self: You snarl and grumble surly under your breath.\n/snarl target: You snarl at (him, her, or it).'),
('string/en/cmd_d.stf', 1154, 'sneak', 'Sneak is an innate ability that allows you to slowly move while prone and taking cover.'),
('string/en/cmd_d.stf', 1155, 'sneer', '/sneer: You sneer.\n/sneer self: You sneer at the thought.\n/sneer target: You sneer at (him, her, or it).'),
('string/en/cmd_d.stf', 1156, 'sneeze', '/sneeze: AAAAACHOOOO!\n/sneeze self: You sneeze, covering your hands in a mucous substance.\n/sneeze target: You sneeze at (target name), covering (him, her, or it) with slime.'),
('string/en/cmd_d.stf', 1157, 'snicker', '/snicker: You snicker.\n/snicker self: You snicker at your own evil thoughts.\n/snicker target: You snicker at (him, her, or it).'),
('string/en/cmd_d.stf', 1158, 'sniff', '/sniff: You sniff sadly.\n/sniff self: You sniff sadly to yourself.\n/sniff target: You sniff sadly at (him, her, or it).'),
('string/en/cmd_d.stf', 1159, 'sniffle', '/sniffle: You sniffle.\n/sniffle self: You sniffle to yourself.\n/sniffle target: You sniffle at (target name).'),
('string/en/cmd_d.stf', 1160, 'snipershot', '/snipershot <target>: This very powerful ranged attack can kill incapacitated targets at a distance.'),
('string/en/cmd_d.stf', 1161, 'snog', '/snog: ~\n/snog self: You attempt snogging yourself.\n/snog target: You attempt to engage in some serious snogging with (target name).'),
('string/en/cmd_d.stf', 1162, 'snore', '/snore: You snore loudly.\n/snore self: You snore softly.\n/snore target: You snore loudly at (target name), displaying your boredom.'),
('string/en/cmd_d.stf', 1163, 'snort', '/snort: SNORT!\n/snort self: You snort derisively.\n/snort target: You snort at (target name).'),
('string/en/cmd_d.stf', 1164, 'soapbox', '/soapbox: You place a soapbox on the ground and offer the use of it.\n/soapbox self: You place a soapbox on the ground, climb upon it, and begin to speak.\n/soapbox target: You try to pull (him, her, or it) down from (his, her, or its) soapbox.'),
('string/en/cmd_d.stf', 1165, 'softclap', '/softclap: You show your approval with a soft applause.\n/softclap self: You give yourself a soft applause.\n/softclap target: You give (him, her, or it) an approving, soft applause.'),
('string/en/cmd_d.stf', 1166, 'space_navigator', 'The Sullustan race is very savvy at navigating space lanes. Their hyperspace recycle time is much shorter than normal species.'),
('string/en/cmd_d.stf', 1167, 'spam', '/spam: SPAM!\n/spam self: You send yourself reeling and your head spinning.\n/spam target: You tell (him, her, or it) to QUIT SPAMMING!'),
('string/en/cmd_d.stf', 1168, 'speaknoevil', '/speaknoevil: You cover your mouth.\n/speaknoevil self: You stare blankly forward with your hand over your mouth.\n/speaknoevil target: You cover your mouth and refuse to speak.'),
('string/en/cmd_d.stf', 1169, 'spin', '/spin: You spin around to see who is behind you.\n/spin self: You spin around and make yourself dizzy.\n/spin target: You spin (target name) around until (him, her, or it) is dizzy.'),
('string/en/cmd_d.stf', 1170, 'spit', '/spit: You spit.\n/spit self: You spit in your hands and prepare to get down to business.\n/spit target: You spit at (him, her, or it).'),
('string/en/cmd_d.stf', 1171, 'splitcreditswithgroup', '/splitCreditsWithGroup <amount>: allows a group member to split the specified amount of coins amongst nearby player group members.'),
('string/en/cmd_d.stf', 1172, 'spotlight', '/spotlight: Performs a spot light effect.'),
('string/en/cmd_d.stf', 1173, 'sprayshot', '/sprayshot <target>: This ranged attack is highly damaging, and has a chance to blind, dizzy, and stun a target.'),
('string/en/cmd_d.stf', 1174, 'squeeze', '/squeeze: You squeeze your emotion management toy.\n/squeeze self: You squeeze yourself.\n/squeeze target: You squeeze (target name) tightly.'),
('string/en/cmd_d.stf', 1175, 'squirm', '/squirm: You squirm.\n/squirm self: You squirm uneasily.\n/squirm target: You try to squirm away from (target name).'),
('string/en/cmd_d.stf', 1176, 'stand', '/stand: This command will bring you to a standing position.'),
('string/en/cmd_d.stf', 1177, 'stare', '/stare: You stare blankly into space.\n/stare self: You try to stare yourself down and go cross-eyed.\n/stare target: You stare at (target name).'),
('string/en/cmd_d.stf', 1178, 'startdance', '/startdance: Start Dancing'),
('string/en/cmd_d.stf', 1179, 'startdance+basic', '/startdance basic: Start the Basic dance.'),
('string/en/cmd_d.stf', 1180, 'startdance+basic2', '/startdance basic2: Start the Basic2 dance.'),
('string/en/cmd_d.stf', 1181, 'startdance+exotic', '/startdance exotic: Start the Exotic dance.'),
('string/en/cmd_d.stf', 1182, 'startdance+exotic2', '/startdance exotic2: Start the Exotic2 dance.'),
('string/en/cmd_d.stf', 1183, 'startdance+exotic3', '/startdance exotic3: Start the Exotic3 dance.'),
('string/en/cmd_d.stf', 1184, 'startdance+exotic4', '/startdance exotic4: Start the Exotic4 dance.'),
('string/en/cmd_d.stf', 1185, 'startdance+footloose', '/startdance footloose: Start the Footloose dance.'),
('string/en/cmd_d.stf', 1186, 'startdance+footloose2', '/startdance footloose2: Start the Footloose2 dance.'),
('string/en/cmd_d.stf', 1187, 'startdance+formal', '/startdance formal: Start the Formal dance.'),
('string/en/cmd_d.stf', 1188, 'startdance+formal2', '/startdance formal2: Start the Formal2 dance.'),
('string/en/cmd_d.stf', 1189, 'startdance+lyrical', '/startdance lyrical: Start the Lyrical dance.'),
('string/en/cmd_d.stf', 1190, 'startdance+lyrical2', '/startdance lyrical2: Start the Lyrical2 dance.'),
('string/en/cmd_d.stf', 1191, 'startdance+poplock', '/startdance poplock: Start the Poplock dance.'),
('string/en/cmd_d.stf', 1192, 'startdance+poplock2', '/startdance poplock2: Start the Poplock2 dance.'),
('string/en/cmd_d.stf', 1193, 'startdance+popular', '/startdance popular: Start the Popular dance.'),
('string/en/cmd_d.stf', 1194, 'startdance+popular2', '/startdance popular2: Start the Popular2 dance.'),
('string/en/cmd_d.stf', 1195, 'startdance+rhythmic', '/startdance rhythmic: Start the Rhythmic dance.'),
('string/en/cmd_d.stf', 1196, 'startdance+rhythmic2', '/startdance rhythmic2: Start the Rhythmic2 dance.'),
('string/en/cmd_d.stf', 1197, 'startdance+theatrical', '/startdance theatrical: Start the Theatrical dance.'),
('string/en/cmd_d.stf', 1198, 'startdance+theatrical2', '/startdance theatrical2: Start the Theatrical2 dance.'),
('string/en/cmd_d.stf', 1199, 'startleshot1', '/startleshot1 <target>: This ranged attack is meant to startle your opponent into a raised position.  If they were lying prone, they kneel, if they were kneeling, they stand up.'),
('string/en/cmd_d.stf', 1200, 'startleshot2', '/startleshot2 <target>: This ranged attack is meant to startle your opponent into a raised position.  If they were lying prone, they kneel, if they were kneeling, they stand up.  This causes more damage than Startle Shot 1.'),
('string/en/cmd_d.stf', 1201, 'startmusic', '/startMusic: Start Music'),
('string/en/cmd_d.stf', 1202, 'startmusic+ballad', '/startmusic ballad: Starts the Ballad song.'),
('string/en/cmd_d.stf', 1203, 'startmusic+ceremonial', '/startmusic ceremonial: Starts the Ceremonial song.'),
('string/en/cmd_d.stf', 1204, 'startmusic+folk', '/startmusic folk: Starts the Folk song.'),
('string/en/cmd_d.stf', 1205, 'startmusic+jazz', '/startmusic jazz: Starts the Jazz song.'),
('string/en/cmd_d.stf', 1206, 'startmusic+rock', '/startmusic rock: Starts the Rock song.'),
('string/en/cmd_d.stf', 1207, 'startmusic+starwars1', '/startmusic starwars1: Starts the Starwars1 song.'),
('string/en/cmd_d.stf', 1208, 'startmusic+starwars2', '/startmusic starwars2: Starts the Starwars2 song.'),
('string/en/cmd_d.stf', 1209, 'startmusic+starwars3', '/startmusic starwars3: Starts the Starwars3 song.'),
('string/en/cmd_d.stf', 1210, 'startmusic+virtuoso', '/startmusic virtuoso: Starts the Virtuoso song.'),
('string/en/cmd_d.stf', 1211, 'startmusic+waltz', '/startmusic waltz: Starts the Waltz song.'),
('string/en/cmd_d.stf', 1212, 'startmusic+western', '/startmusic western: Starts the Western song.'),
('string/en/cmd_d.stf', 1213, 'steadyaim', '/steadyaim: This Squad Leader command increases the chance for the party member''s next shots to hit their target.  This ability costs more or less pool points based on how many people are in the party at the time the ability is used.  Use the /setsteadyaim <message> command to set what the Squad Leader shouts when they use this command.'),
('string/en/cmd_d.stf', 1214, 'steam', '/steam: You boil with rage as steam pours from the top of your head.\n/steam self: You notice that steam is pouring off your body.\n/steam target: You boil over with rage at (target name).'),
('string/en/cmd_d.stf', 1215, 'stink', '/stink: What is that smell?!\n/stink self: UGH! You DO stink!\n/stink target: That bad huh? Guess so since you just told (him, her, or it).'),
('string/en/cmd_d.stf', 1216, 'stomp', '/stomp: *STOMP* *STOMP*\n/stomp self: You stomp around, ready to mosh.\n/stomp target: You stomp on (him, her, or it).'),
('string/en/cmd_d.stf', 1217, 'stop', '/stop: Everybody stop!\n/stop self: You bravely try to stop the onrushing world.\n/stop target: You order (target name) to stop.'),
('string/en/cmd_d.stf', 1218, 'stopbleeding', '/stopBleeding <player>: Causes the target to stop bleeding, negating that particular damage over time state.'),
('string/en/cmd_d.stf', 1219, 'stopcraftingsession', 'This command allows the user to stop a crafting session.'),
('string/en/cmd_d.stf', 1220, 'stopdance', '/stopdance: Stop Dancing'),
('string/en/cmd_d.stf', 1221, 'stopfollow', '/stopfollow: Use this command to immediately stop following somebody (initiated via /follow).'),
('string/en/cmd_d.stf', 1222, 'stopmusic', '/stopMusic: Stop Music'),
('string/en/cmd_d.stf', 1223, 'stoppingshot', '/stoppingshot <target>: This devastatingly powerful attack is known as the Stopping Shot because it has a tendency to stop rushing enemies in their tracks, by killing or incapacitating them with one hit.'),
('string/en/cmd_d.stf', 1224, 'strafeshot1', '/strafeshot1 <target>: This ranged attack clears your enemy out of a covered state, making them more vulnerable to attack.'),
('string/en/cmd_d.stf', 1225, 'strafeshot2', '/strafeshot2 <target>: This ranged attack clears your enemy out of a covered state, making them more vulnerable to attack.'),
('string/en/cmd_d.stf', 1226, 'strangle', '/strangle: You strangle yourself.\n/strangle self: Your eyes bulges from your skull due to lack of breathable air.\n/strangle target: You strangle (him, her, or it).'),
('string/en/cmd_d.stf', 1227, 'stretch', '/stretch: You stretch.\n/stretch self: You warm up with a few stretching exercises.\n/stretch target: You help (him, her, or it) stretch.'),
('string/en/cmd_d.stf', 1228, 'structurestatus', 'This command allows the user to view the status of a structure.'),
('string/en/cmd_d.stf', 1229, 'strut', '/strut: You strut.\n/strut self: You strut about like a lantern bird displaying his feathers.\n/strut target: You strut around (him, her, or it).'),
('string/en/cmd_d.stf', 1230, 'stunattack', 'This command utilizes the stun attack sequence.'),
('string/en/cmd_d.stf', 1231, 'sulk', '/sulk: You sulk.\n/sulk self: You sulk to yourself.\n/sulk target: You sulk at (him, her, or it).'),
('string/en/cmd_d.stf', 1232, 'summon', '/summon: You make a summoning gesture.\n/summon self: You summon all of your strength and courage.\n/summon target: You summon (him, her, or it).'),
('string/en/cmd_d.stf', 1233, 'suppressionfire1', '/suppressionfire1 <target>: This ranged attack is used to drive your opponent into a lower position.  If they were standing, they kneel, if they were kneeling, they go prone.'),
('string/en/cmd_d.stf', 1234, 'suppressionfire2', '/suppressionfire2 <target>: This ranged attack is used to drive your opponent into a lower position.  If they were standing, they kneel, if they were kneeling, they go prone.'),
('string/en/cmd_d.stf', 1235, 'surprised', '/surprised: Surprising, isn''t it?\n/surprised self: You look at yourself, completely surprised.\n/surprised target: You look at (him, her, or it), completely surprised.'),
('string/en/cmd_d.stf', 1236, 'surpriseshot', '/surpriseshot <target>: This ranged sneak attack must be performed from cover.'),
('string/en/cmd_d.stf', 1237, 'surrender', '/surrender: You surrender.\n/surrender self: You surrender yourself to your base instincts.\n/surrender target: You concede and surrender to (target name).'),
('string/en/cmd_d.stf', 1238, 'surrenderself', '/surrenderself'),
('string/en/cmd_d.stf', 1239, 'surrenderskill', 'This command is used to surrender a skill.'),
('string/en/cmd_d.stf', 1240, 'survey', 'The /survey command is used in conjunction with a sample tool.  When you /survey your character will survey for whatever resource you last selected in the sample tool UI.  This allows you to perform a survey without using the sample tool UI.'),
('string/en/cmd_d.stf', 1241, 'swat', '/swat: You swat at the air frantically.\n/swat self: You swat yourself.\n/swat target: You swat (him, her, or it) like an insect.'),
('string/en/cmd_d.stf', 1242, 'sweat', '/sweat: You sweat profusely.\n/sweat self: You wipe the sweat from your brow and fling it to the ground.\n/sweat target: You shake your body like a canine sending sweat flying at (him, her, or it).'),
('string/en/cmd_d.stf', 1243, 'sweep', '/sweep: You sweep the floor.\n/sweep self: You try your best to look busy and sweep the floor.\n/sweep target: You hand (him, her, or it) a broom.'),
('string/en/cmd_d.stf', 1244, 'sysgroup', '/sysgroup <Message>: This command sends a system message to your group members, so that they see it immediately and in the center of their screens.'),
('string/en/cmd_d.stf', 1245, 't', '/t'),
('string/en/cmd_d.stf', 1246, 'tackle', '/tackle: You hunker down into a three-point stance.\n/tackle self: You tackle yourself to the ground.\n/tackle target: You tackle (him, her, or it) to the ground.'),
('string/en/cmd_d.stf', 1247, 'tag', '/tag: You announce that you are playing tag.\n/tag self: Who''s it?\n/tag target: TAG! You''re it, (target name).'),
('string/en/cmd_d.stf', 1248, 'take_cover', '/takecover: Taking Cover allows the use of certain sneak attacks and gives you additional defense.  While in Cover, you can not move unless you have the Sneak skill.'),
('string/en/cmd_d.stf', 1249, 'takecover', '/takecover: Taking Cover allows the use of certain sneak attacks and gives you additional defense.  While in Cover, you can not move unless you have the Sneak skill.'),
('string/en/cmd_d.stf', 1250, 'tame', '/tame <target>: Allows you to try to tame a creature.'),
('string/en/cmd_d.stf', 1251, 'tantrum', '/tantrum: You throw a tantrum.\n/tantrum self: You know you were wrong but throw a fit anyway.\n/tantrum target: You throw a tantrum at (him, her, or it).'),
('string/en/cmd_d.stf', 1252, 'tap', '/tap: You tap your foot impatiently.\n/tap self: You tap your fingers on the table.\n/tap target: You tap (target name) on (his, her, or its) shoulder.'),
('string/en/cmd_d.stf', 1253, 'taunt', '/taunt target: Increases the aggro that a mob in combat has towards you. This ability is useful to get mobs to attack you instead of other party members.'),
('string/en/cmd_d.stf', 1254, 'teach', 'This command allows a user to teach another player what he/she knows about a certain skill. Unlike training with a skill trainer, learning from another player has no cost.'),
('string/en/cmd_d.stf', 1255, 'tease', '/tease: Just teasing!\n/tease self: You tease your hair.\n/tease target: You tease (him, her, or it).'),
('string/en/cmd_d.stf', 1256, 'tell', '/tell <name>:  This allows you to send a message instantly across the galaxy to a person whose name you know.  You can also send messages to multiple people via the following format: /tell ogakk,echuta,gekko <message> will send the same message to Ogakk, Echuta, and Gekko at the same time.  There must be no spaces between the commas and names for this additional function to work correctly.'),
('string/en/cmd_d.stf', 1257, 'tenddamage', '/tenddamage: This ability heals health and action damage without the need for a stimpack.  Using this causes minor wounding to your focus and willpower.'),
('string/en/cmd_d.stf', 1258, 'tendwound', '/tendwound: This ability heals the wounds of a specified physical attribute without the need for medicine.  Using this causes minor wounding to your focus and willpower.'),
('string/en/cmd_d.stf', 1259, 'thank', '/thank: You thank everyone.\n/thank self: You thank yourself.\n/thank target: You thank (him, her, or it).'),
('string/en/cmd_d.stf', 1260, 'thirst', '/thirst: Feeling parched?\n/thirst self: You feel so thirsty and beg for a drink.\n/thirst target: You beg (target name) for a drink.'),
('string/en/cmd_d.stf', 1261, 'threatenshot', '/threatenshot <target>: This ranged attack is useful for making skittish things flee from you.'),
('string/en/cmd_d.stf', 1262, 'throw', '/throw: You throw pebble-sized stones, aimlessly passing the time.\n/throw self: You throw yourself at the enemy.\n/throw target: You throw (target name) at the enemy.'),
('string/en/cmd_d.stf', 1263, 'throwat', '/throwat:  You throw pebble-sized stones, aimlessly passing the time.\n/throwat self:  You throw yourself at the enemy.\n/throwat target:  You throw (target name) at the enemy.'),
('string/en/cmd_d.stf', 1264, 'throwdown', '/throwdown: You throw down the gauntlet.\n/throwdown self: There can only be one!\n/throwdown target: You throw down the gauntlet at (his, her, or its) feet.'),
('string/en/cmd_d.stf', 1265, 'throwgrenade', 'This command allows the user to throw a grenade.'),
('string/en/cmd_d.stf', 1266, 'throwtrap', '/throwtrap: This command is what you use to throw traps at creatures.  It''s easier to simply hotkey the inventory item when using traps, however.'),
('string/en/cmd_d.stf', 1267, 'thumbdown', '/thumbdown: You show your disapproval.\n/thumbdown self: You should have known better.\n/thumbdown target: You show (target name) your disapproval.'),
('string/en/cmd_d.stf', 1268, 'thumbsdown', '/thumbsdown: You show your disapproval.\n/thumbsdown self: You should have known better.\n/thumbsdown target: You show (target name) your disapproval.'),
('string/en/cmd_d.stf', 1269, 'thumbsup', '/thumbsup: You show your approval.\n/thumbsup self: Life is pretty good after all!\n/thumbsup target: You show (target name) your approval.'),
('string/en/cmd_d.stf', 1270, 'thumbup', '/thumbup: You show your approval.\n/thumbup self: Life is pretty good after all!\n/thumbup target: You show (target name) your approval.'),
('string/en/cmd_d.stf', 1271, 'thxinfo', '/thxinfo: THX INFO!\n/thxinfo self: k.thxinfo.byebye now.\n/thxinfo target: You thank (him, her, or it) for the information.'),
('string/en/cmd_d.stf', 1272, 'tickle', '/tickle: Time for the feather tickle torture?\n/tickle self: You tickle yourself.\n/tickle target: You tickle (him, her, or it) mercilessly.'),
('string/en/cmd_d.stf', 1273, 'tiny', '/tiny: You mark an approximation with your forefinger and thumb. It was tiny.\n/tiny self: You guess that it would be tiny.\n/tiny target: You indicate to (target name) with your forefinger and thumb that it was tiny.'),
('string/en/cmd_d.stf', 1274, 'tip', '/tip: You tip your hat.\n/tip self: You tip your hat to yourself.\n/tip target: You tip your hat to (him, her, or it).'),
('string/en/cmd_d.stf', 1275, 'tiphat', '/tiphat:  You tip your hat.\n/tiphat self:  You tip your hat to yourself.\n/tiphat target:  You tip your hat to (him, her, or it).'),
('string/en/cmd_d.stf', 1276, 'tiptoe', '/tiptoe: You tiptoe though the area.\n/tiptoe self: You practice tiptoeing silently.\n/tiptoe target: You try to tiptoe past (target name).'),
('string/en/cmd_d.stf', 1277, 'tmi', '/tmi: TOO MUCH INFO!!\n/tmi self: Sorry everyone! TMI!\n/tmi target: You politely inform (him, her, or it) that was too much info.'),
('string/en/cmd_d.stf', 1278, 'tongue', '/tongue: You stick your tongue out.\n/tongue self: You stick your tongue out and try to touch your nose.\n/tongue target: You stick your tongue out at (target name).'),
('string/en/cmd_d.stf', 1279, 'torsoshot', '/torsoshot <target>: This ranged attack douses a target in flames, causing high amounts of damage to the body as well as causing additional fire damage.'),
('string/en/cmd_d.stf', 1280, 'toss', '/toss: You extend your arms like a child wanting to be tossed.\n/toss self: You toss yourself into the air and land flat on your face.\n/toss target: You toss (him, her, or it) into the air.'),
('string/en/cmd_d.stf', 1281, 'totalhealother', '/totalHealOther <player>: Completely heals all the Health, Action, and Mind damage, repairs all wounds, and removes all battle fatigue from the target player.'),
('string/en/cmd_d.stf', 1282, 'totalhealself', '/totalHealSelf: Completely heals all of your Health, Action, and Mind damage, repairs all wounds, and removes all of your battle fatigue.'),
('string/en/cmd_d.stf', 1283, 'train_mount', 'This ability allows you to train certain pets to be mounts that can be ridden.'),
('string/en/cmd_d.stf', 1284, 'transferforce', '/transferForce <target>: This ability allows a Jedi to transfer some of his stored Force power to another player Jedi.'),
('string/en/cmd_d.stf', 1285, 'traz', 'This ability allows you to plays songs with the Traz instrument.'),
('string/en/cmd_d.stf', 1286, 'trick1', '/trick1: This command instructs your pet do a trick.  Tricks heal pet Mind damage.'),
('string/en/cmd_d.stf', 1287, 'trick2', '/trick2: This command instructs your pet to do a trick.  Tricks heal pet Mind damage.'),
('string/en/cmd_d.stf', 1288, 'tsktsk', '/tsktsk: You rub one index finger over the other. Tsk Tsk.\n/tsktsk self: You should''ve known better! Tsk Tsk is right.\n/tsktsk target: Tsk Tsk, (target name).'),
('string/en/cmd_d.stf', 1289, 'tug', '/tug: You tug your gear to make sure it is secure.\n/tug self: You tug your sleeves and straighten out your clothes.\n/tug target: You tug on (his, her, or its) sleeve.'),
('string/en/cmd_d.stf', 1290, 'tumbletokneeling', '/tumbletokneeling:  This command will attack while rolling your character forward into a kneeling posture.'),
('string/en/cmd_d.stf', 1291, 'tumbletoprone', '/tumbletoprone: This command will attack while diving into a prone posture.'),
('string/en/cmd_d.stf', 1292, 'tumbletostanding', '/tumbletostanding: This command will roll you out of a kneeling or diving posture and leave you standing.'),
('string/en/cmd_d.stf', 1293, 'tweak', '/tweak: You tweak your neck. OUCH!\n/tweak self: You tweak your own nose.\n/tweak target: You tweak (his, her, or its) nose.'),
('string/en/cmd_d.stf', 1294, 'twibble', '/twibble: Twibble. Twibble.\n/twibble self: You twibble about in circles.\n/twibble target: You twibble aimlessly about (him, her, or it).'),
('string/en/cmd_d.stf', 1295, 'twiddle', '/twiddle: You twiddle your thumbs.\n/twiddle self: You patiently twiddle your thumbs.\n/twiddle target: You twiddle your thumbs at (target name).'),
('string/en/cmd_d.stf', 1296, 'twirl', '/twirl: You twirl around gracefully.\n/twirl self: You put a finger on top of your head and twirl like a dancer.\n/twirl target: You twirl (him, her, or it) around gracefully.'),
('string/en/cmd_d.stf', 1297, 'twistarm', '/twistarm: OK. OK. Twist my arm.\n/twistarm self: Twist it just a bit more!\n/twistarm target: You twist (his, her, or its) arm.'),
('string/en/cmd_d.stf', 1298, 'twitch', '/twitch: You twitch.\n/twitch self: You twitch nervously.\n/twitch target: You twitch at (his, her, or its) comments.'),
('string/en/cmd_d.stf', 1299, 'unarmedblind1', '/unarmedblind1 <target>: This unarmed attack can blind a single target.'),
('string/en/cmd_d.stf', 1300, 'unarmedbodyhit1', '/unarmedbodyhit1 <target>: This unarmed attack targets an opponent''s body in order to damage a target''s Health pool.'),
('string/en/cmd_d.stf', 1301, 'unarmedcombo1', '/unarmedcombo1 <target>: This unarmed attack can hit the head and body of a target simultaneously, potentially damaging both Health and Mind pools at once.'),
('string/en/cmd_d.stf', 1302, 'unarmedcombo2', '/unarmedcombo2 <target>: This unarmed attack can hit the head, body, and legs of a target simultaneously, potentially damaging Health, Action, and Mind pools simultaneously.'),
('string/en/cmd_d.stf', 1303, 'unarmeddizzy1', '/unarmeddizzy1 <target>: This unarmed attack can dizzy a single target.'),
('string/en/cmd_d.stf', 1304, 'unarmedheadhit1', '/unarmedheadhit1 <target>: This unarmed attack targets the head in order to damage the target''s Mind pool.'),
('string/en/cmd_d.stf', 1305, 'unarmedhit1', '/unarmedhit1 <target>: This unarmed attack inflicts more damage than the basic unarmed attack.'),
('string/en/cmd_d.stf', 1306, 'unarmedhit2', '/unarmedhit2 <target>: This strong unarmed attack inflicts more damage to a single target than Unarmed Hit 1.'),
('string/en/cmd_d.stf', 1307, 'unarmedhit3', '/unarmedhit3 <target>: This powerful unarmed attack inflicts more damage to a single target than Unarmed Hit 2.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/cmd_d.stf', 1308, 'unarmedknockdown1', '/unarmedknockdown1 <target>: This unarmed attack can knock down a single target.'),
('string/en/cmd_d.stf', 1309, 'unarmedknockdown2', '/unarmedknockdown2 <target>:This unarmed attack can knock down and dizzy a single target.'),
('string/en/cmd_d.stf', 1310, 'unarmedleghit1', '/unarmedleghit1 <target>: This unarmed attack targets the legs in order to damage a target''s Action pool.'),
('string/en/cmd_d.stf', 1311, 'unarmedlunge1', '/unarmedlunge1 <target>: This unarmed attack can slightly extend your range, and has a chance to lower the posture of your target.'),
('string/en/cmd_d.stf', 1312, 'unarmedlunge2', '/unarmedlunge2 <target>: This unarmed attack can slightly extend your range, and has a chance to knock down your target.'),
('string/en/cmd_d.stf', 1313, 'unarmedspinattack1', '/unarmedspinattack1 <target>: This unarmed area attack can damage multiple targets at once.'),
('string/en/cmd_d.stf', 1314, 'unarmedspinattack2', '/unarmedspinattack2 <target>: This unarmed area attack can damage multiple targets at once.  This is more powerful than Unarmed Spin Attack 1.'),
('string/en/cmd_d.stf', 1315, 'unarmedstun1', '/unarmedstun1 <target>: This unarmed attack can stun a single target.'),
('string/en/cmd_d.stf', 1316, 'uncle', '/uncle: UNCLE!! UNCLE!!\n/uncle self: Say Uncle! Say Uncle!\n/uncle target: You beg (him, her, or it) to stop. UNCLE!'),
('string/en/cmd_d.stf', 1317, 'unconsent', '/unconsent: This command brings up a window with all of the players who you have consented to move your corpse.  To remove them from this list, click on their name and then click OK.'),
('string/en/cmd_d.stf', 1318, 'underhandshot', '/underhandshot <target>: This sneaky ranged attack is designed to catch a target unaware, and causes high damage and can also knock them down.'),
('string/en/cmd_d.stf', 1319, 'undock', '/undock: Undock from a space station.'),
('string/en/cmd_d.stf', 1320, 'uninstallshipcomponent', 'Uninstall a ship component from a ship.'),
('string/en/cmd_d.stf', 1321, 'unregistered', 'Your city has been unregistered from the planetary map.'),
('string/en/cmd_d.stf', 1322, 'up', '/up: You point up.\n/up self: You point up.\n/up target: You turn to (target name) and point up.'),
('string/en/cmd_d.stf', 1323, 'vendor_fees_1', 'The merchant gains a reduction in the cost of maintaining vendors.'),
('string/en/cmd_d.stf', 1324, 'ventriloquism', '/ventriloquism <target>: Performs a visual effect around your target'),
('string/en/cmd_d.stf', 1325, 'veto', '/veto: VETO!\n/veto self: You veto your own idea.\n/veto target: You veto (him, her, or it).'),
('string/en/cmd_d.stf', 1326, 'vitalize', '/vitalize: short-term pool attribute buff; alias for "/innate vitalize"'),
('string/en/cmd_d.stf', 1327, 'volleyfire', '/volleyfire <target>: This Squad Leader command directs the fire of the entire group at the target the Squad Leader has chosen.  This enables a Squad Leader''s group to cut through a group of difficult creatures/NPCs far more efficiently than a group without a Squad Leader would perform.'),
('string/en/cmd_d.stf', 1328, 'volleyfireattack', 'This command utilizes the volley fire attack.'),
('string/en/cmd_d.stf', 1329, 'vrepair', '/vrepair: Ship''s Systems Emergency Repair - This command performs a ''vampiric'' repair by routing most of the load of your most heavily damaged component through other lesser damaged components, at the cost of fusing connections, melting wires, etc. This has the game effect of increasing the health of your most heavily damaged ship component, but damaging the others, moving toward evening out the condition of all your components.'),
('string/en/cmd_d.stf', 1330, 'vrepairother', '/vrepairother: Other Ship''s Systems Emergency Repair - This command performs a ''vampiric'' repair to currently targeted friendly vessels that are in close proximity.'),
('string/en/cmd_d.stf', 1331, 'waft', '/waft: You try to waft the stench away.\n/waft self: Taking a bath might help!\n/waft target: You try to keep (his, her, or its) stench away.'),
('string/en/cmd_d.stf', 1332, 'wait', '/wait: You wait.\n/wait self: WAIT UP!\n/wait target: You wait on (him, her, or it).'),
('string/en/cmd_d.stf', 1333, 'warcry1', '/warcry1 <target>: This combat move can increase the round-time of your opponent''s attack, in effect slowing them down.'),
('string/en/cmd_d.stf', 1334, 'warcry2', '/warcry2 <target>: This area combat attack can increase the round times of a cone (frontal area) of multiple enemies simultaneously.'),
('string/en/cmd_d.stf', 1335, 'ward', '/ward: STAY AWAY!\n/ward self: Superstitious? You rub a charm to ward off misfortune.\n/ward target: You make warding signs at (him, her, or it).'),
('string/en/cmd_d.stf', 1336, 'warningshot', '/warningshot <target>: This ranged attack can terrify your target, making them unwilling to run towards you to attack.'),
('string/en/cmd_d.stf', 1337, 'wave', '/wave: You wave.\n/wave self: You wave to yourself.\n/wave target: You wave to (him, her, or it).'),
('string/en/cmd_d.stf', 1338, 'waypoint', 'Waypoint'),
('string/en/cmd_d.stf', 1339, 'welcome', '/welcome: WELCOME ALL!\n/welcome self: You welcome yourself.\n/welcome target: Welcome, (target name).'),
('string/en/cmd_d.stf', 1340, 'whap', '/whap: You whap everyone.\n/whap self: You whap yourself repeatedly.\n/whap target: You whap (him, her, or it) upside the head.'),
('string/en/cmd_d.stf', 1341, 'whatthe', '/whatthe: What the?\n/whatthe self: What were you thinking?\n/whatthe target: You wonder what (target name) was thinking?'),
('string/en/cmd_d.stf', 1342, 'whimper', '/whimper: You whimper.\n/whimper self: You whimper softly to yourself.\n/whimper target: You whimper softly at (target name).'),
('string/en/cmd_d.stf', 1343, 'whisper', '/whisper: ~\n/whisper self: ~\n/whisper target: ~'),
('string/en/cmd_d.stf', 1344, 'whistle', '/whistle: You whistle innocently.\n/whistle self: You whistle a chipper tune.\n/whistle target: You whistle appreciatively at (him, her, or it).'),
('string/en/cmd_d.stf', 1345, 'wild_panic', '/wildpanic:'),
('string/en/cmd_d.stf', 1346, 'wildpanic', '/wildpanic: AAAAAAYYYYYYEEEEEEEE!!!\n/wildpanic self: You panic about, waving your hands in the air.\n/wildpanic target: You panic about (target name), waving your hands in the air.'),
('string/en/cmd_d.stf', 1347, 'wildshot1', '/wildshot1 <target>: This ranged attack can stun a single target.'),
('string/en/cmd_d.stf', 1348, 'wildshot2', '/wildshot2 <target>: This ranged attack can stun multiple targets at once.'),
('string/en/cmd_d.stf', 1349, 'wince', '/wince: You wince.\n/wince self: You wince in pain.\n/wince target: You wince at (him, her, or it).'),
('string/en/cmd_d.stf', 1350, 'wink', '/wink: Wink.\n/wink self: You wink suggestively.\n/wink target: You wink suggestively at (target name).'),
('string/en/cmd_d.stf', 1351, 'wookieehug', '/wookieehug'),
('string/en/cmd_d.stf', 1352, 'wookieeroar', '/wookieeRoar <target>: This can Intimidate a cone (frontal area ) of multiple enemies at once, alias for "/innate wookieeRoar"'),
('string/en/cmd_d.stf', 1353, 'worship', '/worship: You are not worthy!\n/worship self: You are not worthy.\n/worship target: You worship (target name).'),
('string/en/cmd_d.stf', 1354, 'wrinkle', '/wrinkle: You wrinkle your nose and make a sour face.\n/wrinkle self: You wrinkle your nose at yourself.\n/wrinkle target: You wrinkle your nose at (target name).'),
('string/en/cmd_d.stf', 1355, 'wtg', '/wtg: Way to go!\n/wtg self: You think you did a great job.\n/wtg target: You tell (target name) way to go!'),
('string/en/cmd_d.stf', 1356, 'yawn', '/yawn: YAAAWWWNN!\n/yawn self: You tries to hide a yawn.\n/yawn target: You yawn at (him, her, or it).'),
('string/en/cmd_d.stf', 1357, 'yes', '/yes: You nod affirmatively. Yes.\n/yes self: You nod at yourself agreeingly.\n/yes target: You nod affirmatively to (target name).'),
('string/en/cmd_d.stf', 1358, 'zip', '/zip: You zip your lips.\n/zip self: You check your zipper to make sure it''s closed.\n/zip target: You instruct (target name) to zip (his, her, or its) lips.'),
('string/en/cmd_d.stf', 1359, 'zone', '/zone: You zone out.\n/zone self: You zone out and ignore your surroundings.\n/zone target: You zone out and ignore (target name).'),
('string/en/cmd_d.stf', 1360, 'startmusic+starwars4', '/startmusic starwars4: Starts the Starwars4 song.'),
('string/en/cmd_d.stf', 1361, 'startmusic+funk', '/startmusic funk: Starts the Funk song.'),
