('string/en/container_name.stf', 22, 'locked_loot_crate_d', 'This container has been locked with a magnetic seal.  For access, you''ll need the key or you''ll need to slice the locking system.'),
('string/en/container_name.stf', 23, 'loot_crate', 'Unlocked Container'),
('string/en/container_name.stf', 24, 'loot_crate_d', 'This container appears to have been magnetically sealed at one point, but it is open now.'),
('string/en/container_name.stf', 25, 'placable_loot_crate', 'MagSeal Container'),
('string/en/container_name.stf', 26, 'placable_loot_crate_d', 'A strong, blast proof container used for storing valuables.  These are quite common and cheap to produce.  If the MagSeal lock is in place, you will need to have the key or some way of slicing past the system.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/container_name.stf', 27, 'placable_loot_crate_trashpile', 'Loose Debris'),
('string/en/container_name.stf', 28, 'placable_loot_crate_trashpile_d', 'A random collection of loose debris is piled here for reasons unknown. Intelligent wild creatures often gather materials such as these to construct nests and barriers... and (in some very rare cases) for social rituals that few have observed and lived to recount.'),
('string/en/container_name.stf', 31, 'singing_mountain_clan_backpack', 'Tribal Waist Pack'),
('string/en/container_name.stf', 32, 'placable_loot_crate_skeleton', 'A Pile of Bones'),
('string/en/container_name.stf', 33, 'placable_loot_crate_skeleton_d', 'These are the remains of an ill-fated adventurer. It is likely that equipment and credits may be extracted from this pile of bones.'),
('string/en/container_name.stf', 34, 'astromech', 'A Defunct Astromech'),
('string/en/container_name.stf', 35, 'computer', 'A Computer Storage Unit'),
('string/en/container_name.stf', 36, 'gas_filter', 'An Air Filtration Unit'),
('string/en/container_name.stf', 37, 'warren_tech_armoire_d', 'A sectioned metal locker. Sometimes equipped with electronic locks, these are usually used for storing equipment or valuables.'),
('string/en/container_name.stf', 38, 'warren_tech_armoire', 'Locker'),
('string/en/container_name.stf', 39, 'warren_tech_chest', 'Metal Chest'),
('string/en/container_name.stf', 40, 'warren_tech_chest_d', 'A small metal chest, used to hold equipment and supplies. These are sometimes equipped with electronic locks.'),
('string/en/container_name.stf', 41, 'warren_skeleton', 'A Corpse'),
('string/en/container_name.stf', 42, 'warren_skeleton_d', 'This appears to be the devastated corpse of a human. However, it is likely that equipment or items might still be found in the remains.'),
('string/en/container_name.stf', 43, 'debris', 'Debris'),
('string/en/container_name.stf', 44, 'large_plain_crate', 'Large Unmarked Crate'),
('string/en/container_name.stf', 45, 'large_plain_crate_d', 'A large storage crate with no markings to tell what it contains.'),
('string/en/container_name.stf', 46, 'tech_armoire', 'Armoire'),
('string/en/container_name.stf', 47, 'tech_chest', 'Chest'),
('string/en/container_name.stf', 48, 'tech_bookcase', 'Bookcase'),
('string/en/container_name.stf', 49, 'security_container', 'Security Box'),
('string/en/container_name.stf', 50, 'security_container_d', 'A sturdy container designed to keep content secure from exterior damage.'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 1, 'do_not_edit', 'The English version of this file (battlefield_entry_station_imperial.stf) is automatically generated by the SwgConversationEditor.'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 2, 's_0', ''),
('string/en/conversation/battlefield_entry_station_imperial.stf', 3, 's_1bd14e67', 'Okay. Goodbye!'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 4, 's_2e491159', 'Sign up with the Empire and we''ll talk.'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 5, 's_33077605', 'You are not welcome at this station, Rebel SCUM!'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 6, 's_33f71018', 'You are not of the proper faction. Go find your own station.'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 7, 's_358253b2', 'There''s nothing we can do for you while you''re in that civilian ship.'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 8, 's_48f82131', 'You need to move closer to this station.'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 9, 's_597d7f95', 'I would like to go to Kessel.'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 10, 's_7426e000', 'No!'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 11, 's_a136b7d3', 'Welcome to the Imperial Space Station!'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 12, 's_a80d9308', 'Good luck!'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 13, 's_c2f477d7', 'This will cost %DI points of Prestige. Do you wish to spend the points and enter?'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 14, 's_ef420789', 'Yes!'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 15, 's_fa22e207', 'I would like to enter Deep Space!'),
('string/en/conversation/battlefield_entry_station_imperial.stf', 16, 's_fe2e6ec0', 'You do not have enough Prestige to enter Deep Space. You need %DI points. Go do more work for the Empire and we''ll talk.'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 1, 'do_not_edit', 'The English version of this file (battlefield_entry_station_neutral.stf) is automatically generated by the SwgConversationEditor.'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 2, 's_0', ''),
('string/en/conversation/battlefield_entry_station_neutral.stf', 3, 's_11e15256', 'Ha ha!  I don''t blame you.  Goodbye, then.'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 4, 's_1cfc0538', 'Good luck'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 5, 's_1e10b20e', 'Forget that!'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 6, 's_3693fe50', 'There''s nothing we can do for you as long as you''re in that civilian ship.'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 7, 's_370822d1', 'Yes'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 8, 's_37d359a2', 'You do not have enough Prestige to enter Deep Space.  You need %DI points.'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 9, 's_3b257674', 'You need to move close to this station, %TU.'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 10, 's_43be1790', 'I understand'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 11, 's_457a7010', 'No'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 12, 's_45e440c8', 'Rebels are not welcome here'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 13, 's_5755f403', 'Okay, Goodbye'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 14, 's_5f09f8fe', 'The Empire'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 15, 's_729b53ce', 'Welcome, pilot!'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 16, 's_7e6edae', 'This will cost %DI points of prestige.  Do you wish to spend the points and enter?'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 17, 's_993453d7', 'Imperials are not welcome here.'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 18, 's_a785faa6', 'Which side would you like to support?'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 19, 's_a99b5897', 'This area of Deep Space has been closed by order of the Empire.  The only way to get in is to pose as either an Imperial yourself, or to use the Rebel Alliance''s hyperspace route.  Be warned though, whichever route you choose, you will be treated as an enemy by the other side!'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 20, 's_c4588d4d', 'I want to go to Kessel'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 21, 's_d62f971d', 'The Rebel Alliance'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 22, 's_f61543c9', 'Good Luck'),
('string/en/conversation/battlefield_entry_station_neutral.stf', 23, 's_fa22e207', 'I would like to enter Deep Space!'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 1, 'do_not_edit', 'The English version of this file (battlefield_entry_station_rebel.stf) is automatically generated by the SwgConversationEditor.'),
