('string/en/conversation/battlefield_entry_station_rebel.stf', 3, 's_17456755', 'Sign up with the Rebel Alliance and we''ll talk.'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 4, 's_1bd14e67', 'Okay. Goodbye!'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 5, 's_2103c96f', 'We can''t do anything for you while you''re in that civilian ship.'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 6, 's_33f71018', 'You are not of the proper faction. Go find your own station.'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 7, 's_359fde4', 'I want to go to Kessel.'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 8, 's_3b257674', 'You need to move close to this station, %TU.'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 9, 's_514ace33', 'You are not welcome at this station!'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 10, 's_6aebdf84', 'Welcome to the Rebel Space Station!'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 11, 's_7426e000', 'No!'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 12, 's_93272f1a', 'Good Luck.'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 13, 's_a80d9308', 'Good luck!'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 14, 's_c2f477d7', 'This will cost %DI points of Prestige. Do you wish to spend the points and enter?'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 15, 's_ef420789', 'Yes!'),
('string/en/conversation/battlefield_entry_station_rebel.stf', 16, 's_f68255a0', 'You do not have enough Prestige to enter Deep Space. You need %DI points. Go do more work for the Rebellion and we''ll talk.'),
