('string/en/conversation/qtqc_phase_3.stf', 18, 's_9750fd54', 'You need to give one more item.'),
('string/en/conversation/qtqc_phase_3.stf', 19, 's_a489b2f6', 'The overall project.'),
('string/en/conversation/qtqc_phase_3.stf', 20, 's_adcf90d8', 'I don''t recognize the resources needed by the schematics.'),
('string/en/conversation/qtqc_phase_3.stf', 21, 's_b200fa3f', 'Shield Housing'),
('string/en/conversation/qtqc_phase_3.stf', 22, 's_bc2ccc0e', 'There is no crafting project currently being run. Please come back later.'),
('string/en/conversation/qtqc_phase_3.stf', 23, 's_bf623b9', 'You need to give %DI more items.'),
('string/en/conversation/qtqc_phase_3.stf', 24, 's_c266e38f', 'I''d like to get the status of the village shields.'),
('string/en/conversation/qtqc_phase_3.stf', 25, 's_c57c793', 'I''d like to know about the amount of ingredients people are giving.'),
('string/en/conversation/qtqc_phase_3.stf', 26, 's_c61bebb1', 'Power Supply'),
('string/en/conversation/qtqc_phase_3.stf', 27, 's_cbc4b5f7', 'I need the schematics for the village shields.'),
('string/en/conversation/qtqc_phase_3.stf', 28, 's_e9fef768', 'Primary Computer'),
('string/en/conversation/qtqc_phase_3.stf', 29, 's_eb275f76', 'There are people who are working for Eozlin who are gathering special resources. You must get the resources from them to craft the items needed for the shields. There are also reports that the Sith Shadows are using them to build their bases.'),
('string/en/conversation/qtqc_phase_3.stf', 30, 's_f273532d', 'You have been given the schematics needed for the project. They can be accessed via the ''mission/community crafting'' categories of your crafting tool. When you have an ingredient ready, see me to add it to the project.'),
('string/en/conversation/qtqc_phase_3.stf', 31, 's_f580c83d', 'Endrost Alloy'),
