('string/en/craft_droid_ingredients_d.stf', 46, 'personality_module_geek', 'This personality module works to alter any verbal responses that the droid might give.'),
('string/en/craft_droid_ingredients_d.stf', 52, 'r2_droid_chassis', 'This is a specialized droid chassis component used during the construction of an advanced version of a particular droid.'),
('string/en/craft_droid_ingredients_d.stf', 53, 'r3_droid_chassis', 'This is a specialized droid chassis component used during the construction of an advanced version of a particular droid.'),
