('string/en/craft_droid_ingredients_d.stf', 61, 'defensive_module_base', 'This wiring harness accepts any of the droid defensive component modules that can be crafted separately. Droid armor modules are an example of the kind of component you might put in this ingredient slot.'),
('string/en/craft_droid_ingredients_d.stf', 62, 'droid_module_base', 'This wiring harness accepts any of the droid general service component modules that can be crafted separately. Droid medic and repair modules are an example of the kind of components you might put in this ingredient slot.'),
('string/en/craft_droid_ingredients_d.stf', 63, 'crafting_module_base', 'This is the base object whose attributes all other crafting droid modules inherit from.'),
('string/en/craft_droid_ingredients_d.stf', 64, 'crafting_module_food', 'This module is used to grant the droid the ability to function as a private food crafting station. Adding more than crafting module of the same type has no additional effect.'),
('string/en/craft_droid_ingredients_d.stf', 65, 'crafting_module_weapon', 'This module is used to grant the droid the ability to function as a private weapon crafting station. Adding more than crafting module of the same type has no additional effect.'),
('string/en/craft_droid_ingredients_d.stf', 66, 'crafting_module_structure', 'This module is used to grant the droid the ability to function as a private structure crafting station. Adding more than crafting module of the same type has no additional effect.'),
('string/en/craft_droid_ingredients_d.stf', 67, 'crafting_module_clothing', 'This module is used to grant the droid the ability to function as a private clothing crafting station. Adding more than crafting module of the same type has no additional effect.'),
('string/en/craft_droid_ingredients_d.stf', 68, 'crafting_tools', 'Crafting tools used for droid creation.'),
('string/en/craft_droid_ingredients_d.stf', 69, 'inventory_caching_unit', 'An inventory caching unit.'),
('string/en/craft_droid_ingredients_d.stf', 70, 'droid_brain_anakin', 'Old modified droid brain. On the side of it is a metal tag with the inscription "Modified prototype, C3PN. -A.S"'),
('string/en/craft_droid_ingredients_d.stf', 71, 'combat_socket_bank', 'This is an array that can fit a variety of droid sockets. Unlike the normal droid socket bank, this one can accept not only crafting station and other general droid modules, but also droid combat modules.'),
('string/en/craft_droid_ingredients_d.stf', 72, 'charge_suppression', 'Errant Charge Suppression System.'),
('string/en/craft_droid_ingredients_d.stf', 73, 'combat_module', 'This module is used to grant a combat-capable droid chassis the ability to engage in limited combat through melee and ranged methods, depending on the underlying chassis.'),
('string/en/craft_droid_ingredients_d.stf', 74, 'droid_combat_module_base', 'This wiring harness accepts any of the droid general service component modules that can be crafted separately. Droid medic and repair modules are an example of the kind of components you might put in this ingredient slot. This particular module is capable of interfacing with Droid Combat Modules as well as the other types.'),
('string/en/craft_droid_ingredients_d.stf', 75, 'repair_unit_casing', 'This metal casing is made to hold the components necessary to perform reconstruction and routine maintenance on droids.'),
('string/en/craft_droid_ingredients_d.stf', 76, 'repair_unit_casing_advanced', 'This metal casing is large and lightweight. It is made to hold the components necessary to perform reconstruction and routine maintenance on droids.'),
('string/en/craft_droid_ingredients_d.stf', 77, 'diagnostic_circuit', 'This circuit board holds blueprints, instructions, and data necessary for performing repairs on most standard types of droids.'),
('string/en/craft_droid_ingredients_d.stf', 78, 'diagnostic_circuit_advanced', 'This advanced circuit board provides high-speed access to the blueprints, instructions, and data that it contains, which is necessary for performing repairs on almost all types of droids.'),
('string/en/craft_droid_ingredients_d.stf', 79, 'capacitor_low_discharge', 'This capacitor discharge device is designed to hold and release a small electric charge, used to facilitate quick droid repairs.'),
('string/en/craft_droid_ingredients_d.stf', 80, 'capacitor_high_discharge', 'This advanced capacitor discharge device is designed to hold and release a large electric charge, used to facilitate quick droid repairs.'),
('string/en/craft_droid_ingredients_d.stf', 81, 'power_supply_redundant', 'This droid power supply is used mainly in droid reconstruction, when it sometimes becomes necessary to provide a backup power source while maintenance is being performed.'),
('string/en/craft_droid_ingredients_d.stf', 82, 'power_supply_redundant_advanced', 'This high capacity power supply is fashioned for use as both a secondary and if required, a tertiary source of energy. Devices such as this are mainly used in droid reconstruction, when it sometimes becomes necessary to provide a backup power source while maintenance is being performed.'),
('string/en/craft_droid_ingredients_d.stf', 83, 'unit_delivery_cartridge', 'A small metal cartridge used to hold materials necessary for deploying emergency droid repair while in the field.'),
('string/en/craft_droid_ingredients_d.stf', 84, 'unit_delivery_cartridge_advanced', 'A large, yet lightweight metal cartridge used to hold materials necessary for deploying emergency droid repair while in the field.'),
('string/en/craft_droid_ingredients_d.stf', 85, 'merchant_barker', 'This modules enables a droid to play back a recorded message and give out waypoints by request.  The module can only be programmed by a merchant with Advertising IV.'),
('string/en/craft_droid_ingredients_d.stf', 86, 'detonation_module', 'This module turns a droid into a moving bomb.  The module is activated using the /detonateDroid command.  Be warned that the droid will not survive this action!'),
('string/en/craft_droid_ingredients_d.stf', 87, 'stimpack_dispensor', 'This module allows the droid to store level A stimpacks.  The droid''s master or members of the master''s party may then receive healing from it using /requestStimpack.'),
('string/en/craft_droid_ingredients_d.stf', 88, 'struct_maint_module_1', 'This module is used to grant the droid the ability to perform maintenance tasks on structures.'),
('string/en/craft_droid_ingredients_d.stf', 89, 'struct_maint_module_2', 'This module is used to grant the droid the ability to perform maintenance tasks on structures.'),
('string/en/craft_droid_ingredients_d.stf', 90, 'struct_maint_module_3', 'This module is used to grant the droid the ability to perform maintenance tasks on structures.'),
('string/en/craft_droid_ingredients_d.stf', 91, 'auto_repair_module', 'This module allows the droid to repair itself as well all friendly, nearby droids.  Using this module consumes extra power, so it is best to keep it off until needed.'),
('string/en/craft_droid_ingredients_d.stf', 92, 'playback_module', 'This module allows a musician to record and play back a musical track. A droid equipped with such a module can be used as backup or accompaniment in a band performance.\n\nUsing multiple playback modules will allow multiple tracks to be stored on the same droid, but only one track can be played at a time.'),
('string/en/craft_droid_ingredients_d.stf', 93, 'performer_effects_a', 'This module enables the droid to project effects for Dancers and Musicians.'),
('string/en/craft_droid_ingredients_d.stf', 94, 'performer_effects_b', 'This module enables the droid to project effects for Dancers and Musicians.'),
('string/en/craft_droid_ingredients_d.stf', 95, 'performer_effects_c', 'This module enables the droid to project effects for Dancers and Musicians.'),
('string/en/craft_droid_ingredients_d.stf', 96, 'performer_effects_d', 'This module enables the droid to project effects for Dancers and Musicians.'),
('string/en/craft_droid_ingredients_d.stf', 97, 'performer_effects_e', 'This module enables the droid to project effects for Dancers and Musicians.'),
('string/en/craft_droid_ingredients_d.stf', 98, 'harvest_module', 'This module will allow a scout to program a droid that can harvest from creatures that the player has killed.'),
('string/en/craft_droid_ingredients_d.stf', 99, 'trap_module', 'The Scout Trap Projectile Unit breaks down a scout or ranger level trap into a projectile capable of being fired from a small compression unit.  Some effectiveness is lost in the conversion.'),
('string/en/craft_droid_ingredients_d.stf', 100, 'performer_effects_aa', 'This module enables the droid to project effects for Dancers and Musicians.'),
