INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/craft_food_ingredients_d.stf', 12, 'place_setting', 'This is a place setting.'),
('string/en/craft_food_ingredients_d.stf', 13, 'plate', 'A clean plate.'),
('string/en/craft_food_ingredients_d.stf', 14, 'carbosyrup', 'A sticky syrupy substance fortified with carbohydrates.  Used as a sugary basis for many foods.'),
('string/en/craft_food_ingredients_d.stf', 15, 'additive', 'This is an additive for flavor and texture.'),
('string/en/craft_food_ingredients_d.stf', 16, 'small_glass', 'Drink Container\n\nA small drink container required to hold a crafted beverage.  This basic container offers no special bonus to the crafted drink''s quality.'),
('string/en/craft_food_ingredients_d.stf', 17, 'crystal', 'Crystal'),
('string/en/craft_food_ingredients_d.stf', 18, 'large_glass', 'Drink Container\n\nA large drink container designed to hold a crafted beverage.  This enhanced container offers a slight bonus to the amount of beverage created when used in crafting.'),
('string/en/craft_food_ingredients_d.stf', 19, 'cask', 'Drink Container\n\nA very large drink container designed to hold a crafted beverage.  This enhanced container offers a moderate bonus to the amount of beverage created when used in crafting.'),
