('string/en/craft_weapon_ingredients_d.stf', 1, 'knife_shaft', 'Holds the knife blade and serves as a mounting point for the grip.\n'),
('string/en/craft_weapon_ingredients_d.stf', 2, 'cutting_edge', 'A reinforced strip of material honed to a knife edge.'),
('string/en/craft_weapon_ingredients_d.stf', 3, 'grip', 'A semi-textured and shaped section of the weapon, built to serve as a grabbing point from which to thrust and swing it.'),
('string/en/craft_weapon_ingredients_d.stf', 4, 'grip_cap', 'A cover for a tinyl compartment used to store built-in items to maintain the weapon.'),
('string/en/craft_weapon_ingredients_d.stf', 5, 'staff_shaft', 'Primary functional part of the staff, it is rigid yet remains slightly flexible, increasing its durability and ability to do damage.'),
('string/en/craft_weapon_ingredients_d.stf', 6, 'axe_head', 'A solid and weighty chunk of material which mounts to a shaft and which has a cutting edge on its striking-face.'),
('string/en/craft_weapon_ingredients_d.stf', 7, 'shaft', 'Serves as the handle for swinging a weapon.'),
('string/en/craft_weapon_ingredients_d.stf', 8, 'axe_head_fastener', 'Holds the axe head onto the shaft it is attached to.'),
('string/en/craft_weapon_ingredients_d.stf', 9, 'blaster_pistol_barrel', 'A metal tube that focuses and directs the energy from a blaster towards its intended target.'),
('string/en/craft_weapon_ingredients_d.stf', 10, 'blaster_rifle_barrel', 'A metal tube that focuses and directs the energy from a blaster rifle towards its intended target.'),
('string/en/craft_weapon_ingredients_d.stf', 11, 'blaster_power_handler', 'This regulates a blaster''s power output.'),
('string/en/craft_weapon_ingredients_d.stf', 12, 'chemical_dispersion_mechanism', 'This mechanism is responsible for a weapon''s chemical dispersion.'),
('string/en/craft_weapon_ingredients_d.stf', 13, 'energization_crystals', 'Energization crystals can greatly increase the effectiveness of laser and blaster weapons.'),
('string/en/craft_weapon_ingredients_d.stf', 14, 'galven_tube_circuits', 'These galven circuits help maintain a laser beam''s cohesion over incredible distances.  These circuits are placed inside of a galven tube alongside galven coils, in line with the laser barrel.   Regular blasters generally have a more simplified version of this technology, compared to what is required for laser weaponry.'),
('string/en/craft_weapon_ingredients_d.stf', 15, 'laser_cannon_cooling_sleeve', 'Laser cannons generate excessive heat while in use, and cooling sleeves are an important part of the sophisticated cooling system that is used to protect sensitive internal components.'),
('string/en/craft_weapon_ingredients_d.stf', 16, 'laser_cannon_gun_tube', 'A gun-tube for a laser cannon.'),
('string/en/craft_weapon_ingredients_d.stf', 17, 'laser_generator', 'A laser generator is the most common source of energy for laser cannons.'),
('string/en/craft_weapon_ingredients_d.stf', 18, 'laser_magnetic_flashback_supressor', 'A crescent-shaped device at the end of some laser barrels, a flashback suppressor is designed to prevent occasionally unstable laser beams from damaging the barrel.'),
('string/en/craft_weapon_ingredients_d.stf', 19, 'parallel_weapon_targeting_computer', 'This targeting computer is designed to be used with weapons that have been placed parallel to each other on one mount.'),
('string/en/craft_weapon_ingredients_d.stf', 20, 'projectile_feed_mechanism', 'A projectile weapon''s feed mechanism.'),
('string/en/craft_weapon_ingredients_d.stf', 21, 'projectile_pistol_barrel', 'Projectile pistol barrels guide and direct projectiles that are propelled via a pistol''s firing mechanism.'),
('string/en/craft_weapon_ingredients_d.stf', 22, 'projectile_rifle_barrel', 'Projectile rifle barrels guide and direct projectiles that are propelled via a rifle''s firing mechanism.'),
('string/en/craft_weapon_ingredients_d.stf', 23, 'scope_weapon', 'A weapon''s scope can increase its accuracy.'),
('string/en/craft_weapon_ingredients_d.stf', 24, 'stock_unit', 'This is a stock for a rifle.'),
('string/en/craft_weapon_ingredients_d.stf', 25, 'sword_core', 'This is the main body of a sword''s blade.'),
('string/en/craft_weapon_ingredients_d.stf', 26, 'turbo_laser_gun_tube', 'This is the gun tube for a turbolaser.'),
('string/en/craft_weapon_ingredients_d.stf', 27, 'blade_vibro_unit', 'This vibro-unit will turn a normal blade into a much more destructive weapon by creating thousands of microscopic vibrations a second, greatly improving its cutting ability.'),
('string/en/craft_weapon_ingredients_d.stf', 28, 'weapon_mount', 'A mount that allows a weapon to be attached to it.'),
('string/en/craft_weapon_ingredients_d.stf', 29, 'weapon_mount_light', 'A mount for use with lighter weapons.'),
('string/en/craft_weapon_ingredients_d.stf', 30, 'weapon_targeting_computer', 'A weapon''s targeting computer helps determine the range to the target, and can greatly help a gunner''s accuracy.'),
('string/en/craft_weapon_ingredients_d.stf', 31, 'weapon_trajectory_computer', 'A weapon''s trajectory computer can help determine the trajectory of a target.'),
('string/en/craft_weapon_ingredients_d.stf', 32, 'cartridge_feed_mechanism', 'This mechanism feeds a weapon from its cartridge.'),
('string/en/craft_weapon_ingredients_d.stf', 33, 'trigger_pulse_prism', 'A trigger pulse prism.'),
('string/en/craft_weapon_ingredients_d.stf', 34, 'prism_mount', 'A prism mount.'),
