('string/en/craft_weapon_ingredients_d.stf', 36, 'insulation', 'Some insulation.'),
('string/en/craft_weapon_ingredients_d.stf', 37, 'warhead_and_control_coupling', 'This is coupling for the warhead and its control unit.'),
('string/en/craft_weapon_ingredients_d.stf', 38, 'scope_schell', 'The shell of a weapon scope.'),
('string/en/craft_weapon_ingredients_d.stf', 39, 'scope_shell', 'The shell of a weapon scope.'),
('string/en/craft_weapon_ingredients_d.stf', 40, 'projectile', 'A shaped hunk of metal, for use in making projectile ammunition.'),
('string/en/craft_weapon_ingredients_d.stf', 41, 'cartridge_casing', 'A cartridge casing.'),
('string/en/craft_weapon_ingredients_d.stf', 42, 'propulsive_charge', 'A propulsive charge, when properly used, can accelerate projectiles at incredible speeds.'),
('string/en/craft_weapon_ingredients_d.stf', 43, 'neutralization_material', 'Biological neutralization material.'),
('string/en/craft_weapon_ingredients_d.stf', 44, 'grip_unit', 'A grip unit.'),
('string/en/craft_weapon_ingredients_d.stf', 45, 'lance_shaft', 'A lance blade-shaft''s assembly.'),
('string/en/craft_weapon_ingredients_d.stf', 46, 'power_circuits', 'Power circuits.'),
