('string/en/craft_weapon_ingredients_d.stf', 49, 'blaster_power_handler_advanced', 'This advanced power handler is suited for more powerful blasters.'),
('string/en/craft_weapon_ingredients_d.stf', 50, 'projectile_feed_mechanism_advanced', 'An advanced feed mechanism for projectile weapons.'),
('string/en/craft_weapon_ingredients_d.stf', 51, 'projectile_pistol_barrel_advanced', 'Projectile pistol barrels guide and direct projectiles that are propelled via a pistol''s firing mechanism.  This is an advanced barrel design.'),
('string/en/craft_weapon_ingredients_d.stf', 52, 'scope_weapon_advanced', 'A weapon''s scope can increase its accuracy.  This is an advanced scope design, and is more effective than a standard scope.'),
('string/en/craft_weapon_ingredients_d.stf', 53, 'stock_unit_advanced', 'This is an advanced stock for a rifle.'),
('string/en/craft_weapon_ingredients_d.stf', 54, 'blaster_rifle_barrel_advanced', 'A metal tube that focuses and directs the energy from a blaster rifle towards its intended target.  This is an advanced barrel design, and is more effective than the basic barrel.'),
('string/en/craft_weapon_ingredients_d.stf', 55, 'chemical_dispersion_mechanism_advanced', 'This mechanism is responsible for a weapon''s chemical dispersion.  This is an advanced design and allows for a greater effect.'),
('string/en/craft_weapon_ingredients_d.stf', 56, 'sword_core_advanced', 'This is the main body of a sword''s blade.  This advanced design allows for a stronger sword.'),
