('string/en/event_perk_detail.stf', 46, 'rebel_recruiting_station_theater_deed_name', 'Deploying this rental will create a Rebel Pavillion at the closest valid location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 47, 'rori_flag_deed_name', 'Deploying this rental will create a Flag of Rori at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 48, 'shuttle_static_deed_name', 'Deploying this rental will create a shuttle at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 49, 'stone_base_banner_static_deed_name', 'Deploying this rental will create a Stone Based Banner at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 50, 'talus_flag_deed_name', 'Deploying this rental will create a Flag of Talus at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 51, 'tatooine_banner_static_deed_name', 'Deploying this rental will create a Tatooine Banner at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 52, 'tatooine_flag_deed_name', 'Deploying this rental will create a Flag of Tatooine at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 53, 'tie_bomber_static_deed_name', 'Deploying this rental will create a Tie Bomber at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 54, 'tie_fighter_static_deed_name', 'Deploying this rental will create a Tie Fighter at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 55, 'universe_flags_theater_name', 'Deploying this rental will create Flags of the Universe at the closest valid location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 56, 'wedding_garden_imperial_large_theater_name', 'Deploying this rental will create a Large Imperial Wedding Garden at the closest valid location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 57, 'wedding_garden_rebel_large_theater_name', 'Deploying this rental will create a Large Rebel Wedding Garden at the closest valid location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 58, 'xwing_static_deed_name', 'Deploying this rental will create a X-Wing at your location. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 59, 'rsf_1x10_honorguard_deed_name', 'Deploying this rental will create an honor guard of RSF forces at your location and heading. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 60, 'rsf_2x10_honorguard_deed_name', 'Deploying this rental will create an honor guard of RSF forces at your location and heading. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 61, 'rsf_3x10_honorguard_deed_name', 'Deploying this rental will create an honor guard of RSF forces at your location and heading. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 62, 'rsf_4x10_honorguard_deed_name', 'Deploying this rental will create an honor guard of RSF forces at your location and heading. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 63, 'party_stage_theater_deed_name', 'Deploying this rental will create a Party Stage at the closest valid location.  This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 64, 'imperial_stage_theater_deed_name', 'Deploying this rental will create an Imperial Stage at the closest valid location.  This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 65, 'rebel_stage_theater_deed_name', 'Deploying this rental will create an Rebel Stage at the closest valid location.  This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 66, 'corsec_stage_theater_deed_name', 'Deploying this rental will create a Corsec Stage at the closest valid location.  This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 67, 'fed_dub_stage_theater_deed_name', 'Deploying this rental will create a Fed-Dub at the closest valid location.  This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 68, 'rsf_stage_theater_deed_name', 'Deploying this rental will create a RSF Stage at the closest valid location.  This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 69, 'npc_actor_name', 'Deploying this rental will summon an NPC actor of your choosing. After deploying you may give the actor a line and an animation, dress them, set their mood and they will perform whenever someone comes near them. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 70, 'shuttle_beacon', 'Use this beacon to select and then initiate a shuttle landing. You may also use this beacon to issue a command to order the shuttle to take off again. The shuttle beacon will expire eight hours after the time of purchase. Note that you may only possess one shuttle beacon at a time.'),
('string/en/event_perk_detail.stf', 71, 'treasure_box_chest_deed_name', 'Deploying this rental will create a treasure chest at your location. You may fill the chest with items. Anyone happening upon the chest will be able to pull one piece of loot from the chest. This deed and the perk it generates will expire eight hours after the time of purchase. Note that any items left in the chest at the time of expiration will be destroyed and forever lost.'),
('string/en/event_perk_detail.stf', 72, 'flag_game_imp_flag', 'The Empire is currently in possession of the flag.'),
('string/en/event_perk_detail.stf', 73, 'flag_game_reb_flag', 'The Rebel Alliance is currently in control of the flag.'),
('string/en/event_perk_detail.stf', 74, 'flag_game_neut_flag', 'Neither side is currently in control of the flag.'),
('string/en/event_perk_detail.stf', 75, 'game_flag_deed', 'Deploying this rental will create a flag. After setting a time limit and starting the game, any Special Forces member of a faction registered for your event may capture the flag for the opposing team. The team that holds the flag the longest during the time limit wins. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 76, 'lottery_droid_deed_name', 'Deploying this rental will place a droid that you may use to run a lottery. You may set the length of time the lottery runs, the cost of registration for the lottery and the percentage of the proceeds that the winner of the lottery will recieve. Credits not paid out by the winner may be collected by you after the lottery drawing. The Lottery Droid will expire 24 hours after the lottery drawing is complete.'),
('string/en/event_perk_detail.stf', 77, 'race_droid_deed_name', 'Deploying this rental will place a race droid at your location. You may program the droid with a number of waypoints. Once you initialize the droid, others can run the course you have created and the droid will record the person with the best time for the race. This deed and the perk it generates will expire eight hours after the time of purchase.'),
('string/en/event_perk_detail.stf', 78, 'scavenger_droid_deed_name', 'Deploying this rental will place a scavenger hunt droid at your location. You may show the droid a number of items by dragging and dropping them onto him. You may then initialize the droid to start the game. The one who returns all of the items to the droid first is the winner. The droid keeps track of the current leader of the contest. This deed and the perk it generates will expire eight hours after the time of purchase.'),
