('string/en/faction_recruiter.stf', 1, 'greeting', 'Greetings.  What can I do for you today?'),
('string/en/faction_recruiter.stf', 2, 'not_member', 'That is only for Overt and Covert faction members.'),
('string/en/faction_recruiter.stf', 3, 'response_join_faction', 'I would like to become a Covert member of your faction.'),
('string/en/faction_recruiter.stf', 4, 'response_nothing', 'Nothing. Goodbye.'),
('string/en/faction_recruiter.stf', 5, 'response_change_faction', 'I would like to quit my faction and join the %TO faction.'),
('string/en/faction_recruiter.stf', 6, 'greeting_prose', 'Greetings.  With what can the %TO faction help you?'),
('string/en/faction_recruiter.stf', 7, 'greeting_member', 'Hello, %TO.  What would you like to do?'),
('string/en/faction_recruiter.stf', 8, 'invalid_response', 'I''m sorry.  I can''t help you with that.'),
('string/en/faction_recruiter.stf', 9, 'join_faction_confirm', 'A wise decision!  Are you certain you wish to join us?'),
('string/en/faction_recruiter.stf', 10, 'join_faction_denied', 'I am glad you''ve expressed such interest in joining us.  You must, however, prove your devotion to our cause by increasing your %TO faction standing to at least %DI.\n'),
('string/en/faction_recruiter.stf', 11, 'response_yes_to_join', 'Yes. I am certain that I wish to join.'),
('string/en/faction_recruiter.stf', 12, 'response_no_to_join', 'No. I''d rather not join at this time.'),
('string/en/faction_recruiter.stf', 13, 'join_faction_player_no', 'Sorry to hear it.  Speak with me again if you ever reconsider.'),
('string/en/faction_recruiter.stf', 14, 'welcome_to_faction', 'A fine decision!  Welcome to the %TO faction.  Perhaps you would like to hear about our faction services? '),
('string/en/faction_recruiter.stf', 15, 'response_yes_to_see_options', 'Yes. I would like to see what''s available.'),
('string/en/faction_recruiter.stf', 16, 'response_no_to_see_options', 'No thanks.  Not right now.'),
('string/en/faction_recruiter.stf', 17, 'show_options', 'What interests you?'),
('string/en/faction_recruiter.stf', 18, 'option_resign_from_faction', 'I would like to resign.'),
('string/en/faction_recruiter.stf', 19, 'resign_faction_confirm', 'We''d hate to lose you, %TU.  Your request will require %DI hours to process.  Be warned, if you resign all of your faction perks will be lost to you.  This includes your factional backpacks and anything contained within!  Are you sure you want to resign?'),
('string/en/faction_recruiter.stf', 20, 'response_yes_to_resign', 'Yes, I would like to leave the faction.'),
('string/en/faction_recruiter.stf', 21, 'response_no_to_resign', 'No.  I will stay for now.'),
('string/en/faction_recruiter.stf', 22, 'resign_faction_no', 'I''m glad you changed your mind.  What would you like to do?'),
('string/en/faction_recruiter.stf', 23, 'resign_faction_yes', 'Very well. You will be removed from the %TO faction in %DI hours.'),
('string/en/faction_recruiter.stf', 24, 'resign_complete', 'Your resignation from the %TO faction is complete.'),
('string/en/faction_recruiter.stf', 25, 'option_go_declared', 'I would like to declare my faction affiliation.'),
('string/en/faction_recruiter.stf', 26, 'option_go_covert', 'I would like to become a covert faction member.'),
('string/en/faction_recruiter.stf', 27, 'go_declared_confirm', 'If you declare your affiliation, you will become open to attack from our enemies.  Furthermore, should you change your mind, returning to your covert status is not immediate.  Are you sure you want to do this?'),
('string/en/faction_recruiter.stf', 28, 'go_covert_confirm', 'Becoming covert will shield you from attacks by our enemies, but will also prevent you from initiating conflicts with them.  Are you sure you this is what you want?'),
('string/en/faction_recruiter.stf', 29, 'response_yes_to_go_covert', 'Yes, I wish to become a covert member.'),
('string/en/faction_recruiter.stf', 30, 'response_no_to_go_covert', 'No. I''d rather keep my allegiance declared.'),
('string/en/faction_recruiter.stf', 31, 'response_yes_to_go_declared', 'Yes.  I''m certain I want to declare my affiliation.'),
('string/en/faction_recruiter.stf', 32, 'response_no_to_go_declared', 'On second thought, I''ll stay covert for now.'),
