('string/en/faction_recruiter.stf', 42, 'training_experience_granted', 'You have earned %DI %TO experience.'),
('string/en/faction_recruiter.stf', 43, 'option_purchase_items', 'What items are available for requisition?'),
('string/en/faction_recruiter.stf', 44, 'show_item_categories', 'What type of items do you wish to consider?'),
('string/en/faction_recruiter.stf', 45, 'option_purchase_furniture', 'I''m interested in furniture.'),
('string/en/faction_recruiter.stf', 46, 'option_purchase_uniforms', 'I''m interested in uniforms.'),
('string/en/faction_recruiter.stf', 47, 'option_purchase_weapons_armor', 'I''m interested in weapons and armor.'),
('string/en/faction_recruiter.stf', 48, 'option_purchase_schematics', 'I''m interested in schematics.'),
('string/en/faction_recruiter.stf', 50, 'show_items', 'This is what we have to offer.'),
('string/en/faction_recruiter.stf', 51, 'no_items_available', 'There are no items of that type available.'),
('string/en/faction_recruiter.stf', 52, 'select_item_purchase', 'Select the item you wish to request.  All costs are in faction standing points.'),
('string/en/faction_recruiter.stf', 53, 'faction_purchase', 'Faction Item Requisition'),
('string/en/faction_recruiter.stf', 54, 'item_purchase_complete', 'Your requisition of %TT is complete.'),
('string/en/faction_recruiter.stf', 55, 'must_be_declared', 'Your faction affiliation must be declared or you must be within a battlefield in order to equip that item.'),
('string/en/faction_recruiter.stf', 56, 'must_be_faction_member', 'You must be an Overt or Covert member of the %TO faction in order to equip that item.'),
('string/en/faction_recruiter.stf', 57, 'must_be_declared_use', 'Your faction affiliation must be declared in order to use that item.'),
('string/en/faction_recruiter.stf', 58, 'must_be_faction_member_use', 'You must be an Overt or Covert member of the %TO faction in order to use that item.'),
('string/en/faction_recruiter.stf', 59, 'covert_complete', 'You are now a Combatant. Enemy NPCs will attack you on sight but you cannot be attacked by enemy players.'),
('string/en/faction_recruiter.stf', 60, 'option_hirelings', 'I would like some personnel support.'),
('string/en/faction_recruiter.stf', 61, 'hireling_purchase_complete', 'The %TT is now under your command.'),
('string/en/faction_recruiter.stf', 62, 'too_many_hirelings', 'You already have too much under your command.'),
('string/en/faction_recruiter.stf', 63, 'hireling_released', 'Your %TT has abandoned you.'),
('string/en/faction_recruiter.stf', 64, 'option_faction_orders', 'I would like to hear about what faction orders are available.'),
('string/en/faction_recruiter.stf', 65, 'inventory_full', 'Your inventory is full.  Dropping item at feet.'),
('string/en/faction_recruiter.stf', 66, 'datapad_full', 'Your datapad is full.  You must first free some space.'),
('string/en/faction_recruiter.stf', 67, 'order_shuttle_extract', 'Call For Shuttle Extraction'),
('string/en/faction_recruiter.stf', 68, 'order_purchase_complete', 'Your requisition of the %TT orders is complete.'),
('string/en/faction_recruiter.stf', 69, 'shuttle_extract', 'Shuttle Extraction'),
('string/en/faction_recruiter.stf', 70, 'shuttle_extract_description', 'Shuttle Extraction calls for an immediate evacuation of you and your group.  In most cases, response time is less than 1 minute.'),
('string/en/faction_recruiter.stf', 71, 'shuttle_initiated', 'Shuttle extraction procedures initiated.  Stay close to the extraction point and remain outside of buildings.  The shuttle will arrive within the next %DI seconds.'),
('string/en/faction_recruiter.stf', 72, 'not_outside', 'You must be outside in order to call for a Shuttle Extraction.'),
('string/en/faction_recruiter.stf', 73, 'too_far_from_shuttle', 'You have moved too far from the extraction point and missed the shuttle!'),
('string/en/faction_recruiter.stf', 74, 'shuttle_inside_building', 'You have moved inside where the shuttle has missed you!'),
('string/en/faction_recruiter.stf', 75, 'shuttle_destination', 'You have arrived at %TO.'),
('string/en/faction_recruiter.stf', 76, 'shuttle_extraction_point', 'Shuttle Extraction'),
('string/en/faction_recruiter.stf', 77, 'already_request_shuttle', 'You have already requested a shuttle.'),
('string/en/faction_recruiter.stf', 78, 'shuttle_initiated_group', '%TU has initiated shuttle extraction procedures.  Stay close to the extraction point and remain outside of buildings.  The shuttle will arrive within the next %DI seconds.'),
('string/en/faction_recruiter.stf', 79, 'greeting_hate', 'I have no business with you.  You''d best be going.'),
('string/en/faction_recruiter.stf', 81, 'schematic_purchase_complete', 'Schematic requisition complete.'),
('string/en/faction_recruiter.stf', 82, 'faction_training', 'Faction Training'),
('string/en/faction_recruiter.stf', 83, 'sell_secrets', 'I may have some valuable information for you.'),
('string/en/faction_recruiter.stf', 84, 'no_secrets_1', 'I''m not interesting in hearing petty rumors about enemy activity.   Come back when you have something substantial.'),
('string/en/faction_recruiter.stf', 85, 'no_secrets_2', 'You make the fourth petty thug to try and sell me rumors this week.  If you earn the trust of our enemies, I might be interested in buying what you know, but at the moment you are simply wasting my time.  Good day.'),
('string/en/faction_recruiter.stf', 86, 'no_secrets_3', 'You will pardon me if I don''t respect you as a source of credible information.  Earn the trust of our enemies, then I might be willing to pay you for what you know.'),
('string/en/faction_recruiter.stf', 87, 'interested_secrets_imp_1', 'Yes...I''ve heard that you were aiding the Rebellion.  Rather good at it too: you''ve dealt us more than a few setbacks.  Give me a reason why I shouldn''t have you arrested.'),
('string/en/faction_recruiter.stf', 88, 'interested_secrets_imp_2', 'Going turncoat on the Rebellion eh?  I can''t say I blame you.  Rebel bases have been collapsing as fast as we can discover them.  Maybe you could help us in our efforts?'),
('string/en/faction_recruiter.stf', 89, 'interested_secrets_imp_3', 'You are known to me as a Rebel sympathizer.  Several patrols have your name and visual ID, in fact.  If you have useful intelligence for me, I might be able to make those patrols forget about you...and line your pockets at the same time.'),
('string/en/faction_recruiter.stf', 90, 'interested_secrets_reb_1', 'We occaisionally get Imperial ''sympathizers'' who want to sell their information to the highest bidder.  What makes you think I''m interested in what you have to say?'),
('string/en/faction_recruiter.stf', 91, 'interested_secrets_reb_2', 'I get the feeling this information isn''t going to be free...but I''m listening.  I''ve heard that you were working with the Empire and I might be willing to buy what you know.'),
('string/en/faction_recruiter.stf', 92, 'interested_secrets_reb_3', 'If we listened to every Imperial officer with ''information'' to sell, the Rebellion would have been put down long ago.  I''ll listen to what you have to say, but believe me: I know bait when I hear it.  You''ll get your money only if the information is sound.'),
('string/en/faction_recruiter.stf', 93, 'nevermind', 'On second thought, I probably don''t know enough yet to help you.'),
('string/en/faction_recruiter.stf', 94, 'here_you_go', 'Here''s the latest information I''ve been able to get.'),
('string/en/faction_recruiter.stf', 95, 'get_lost', 'Don''t waste my time.  Come back when you know something.'),
('string/en/faction_recruiter.stf', 96, 'prose_reward', 'You have been given %DI credits in exchange for your information.'),
('string/en/faction_recruiter.stf', 97, 'good_stuff_1', 'This may be exactly what we needed to know.  I''m surprised...for a piece of traitorous scum you are somewhat reliable.  Here is your payment.  Now get out of my sight.'),
('string/en/faction_recruiter.stf', 98, 'good_stuff_2', 'So that''s why their communication lines have been quiet.  I knew they were planning something.  Here is your payment.  If you learn anything else you know where to find me.'),
('string/en/faction_recruiter.stf', 99, 'good_stuff_3', 'While it goes against my better judgement, this information seems to be in line with what we already know.  You''ve done a good job, here is your payment.  By the way, if you find any enemy orders in the field, hand them to me and I might be willing to pay you more.'),
('string/en/faction_recruiter.stf', 100, 'bad_stuff_1', 'Hah, that''s rich.  I had a Bothan freighter captain in my office two hours ago with the exact same piece of information.  I''m sorry, but I can''t pay you for what I already know.'),
('string/en/faction_recruiter.stf', 101, 'bad_stuff_2', 'Three days ago our spy network confirmed the exact opposite of what you have you just told me.  I don''t have time to waste on traitors and I certainly don''t have time to waste on traitors who are wrong.  Good day.'),
('string/en/faction_recruiter.stf', 102, 'buy_faction', 'I''d like to make a ... donation ... to your cause.'),
('string/en/faction_recruiter.stf', 103, 'no_faction_imp', 'You are known to be a Rebel supporter and while I do not have enough evidence to arrest you, I will find a reason to complicate your life unless you leave my sight immediately.'),
('string/en/faction_recruiter.stf', 104, 'no_faction_reb', 'You are a known Imperial collaborator and supporter.  I have no interest in what you have to offer.'),
('string/en/faction_recruiter.stf', 105, 'interested_faction_reb', 'Honestly, the Rebellion is in sore need of funds.  Our operations require men, supplies, and weapons, none of which comes free.  Anything you can give would be appreciated.'),
('string/en/faction_recruiter.stf', 106, 'interested_faction_imp', 'A ''donation'' eh?  I might see to it that certain individuals hear of your kindness and that certain materials are made available should you see fit to make such a ''donation.'''),
('string/en/faction_recruiter.stf', 107, 'no_faction', 'I''ve changed my mind, I have other things to spend my money on.'),
('string/en/faction_recruiter.stf', 108, 'yes_faction_tenk', 'I''ll transfer one hundred thousand credits into your account.'),
('string/en/faction_recruiter.stf', 109, 'yes_faction_onek', 'I''ll transfer twenty thousand credits into your account.'),
('string/en/faction_recruiter.stf', 110, 'get_lost_faction', 'Don''t offer money when you can''t afford to pay.'),
('string/en/faction_recruiter.stf', 111, 'too_much_faction', 'I appreciate the offer, but you''ve done enough for us already.'),
('string/en/faction_recruiter.stf', 112, 'checking_credit', 'Hold on while I validate your credit...'),
('string/en/faction_recruiter.stf', 113, 'bribe_fail', 'Is this a joke?  You don''t have enough money to cover your offer.'),
('string/en/faction_recruiter.stf', 114, 'bribe_success', 'Looks like everything is in order.  I''ll see what I can do for you.  If you happen to feel generous again, you know where you can find me.'),
('string/en/faction_recruiter.stf', 115, 'option_purchase_installation', 'I am interested in installations.'),
('string/en/faction_recruiter.stf', 116, 'option_promotion', 'Have I qualified for a promotion?'),
('string/en/faction_recruiter.stf', 117, 'not_enough_for_promotion', 'Promotion to the rank of %TO requires %DI standing over the factional minimum.  You do not yet have enough for promotion.'),
('string/en/faction_recruiter.stf', 118, 'promotion_confirm', 'Promotion to the rank of %TO requires %DI standing which I''m happy to say you meet.  Do you accept this great honor?'),
('string/en/faction_recruiter.stf', 119, 'response_yes_to_promotion', 'Yes. I accept the promotion.'),
('string/en/faction_recruiter.stf', 120, 'response_no_to_promotion', 'No. I''m not yet ready to accept a promotion.'),
('string/en/faction_recruiter.stf', 121, 'promotion_max_rank', 'You have already reached the highest rank that you can.'),
