('string/en/faction_recruiter.stf', 147, 'option_recind_resignation', 'I would like to rescind my resignation.'),
('string/en/faction_recruiter.stf', 148, 'resignation_recinded', 'Glad to have you back!'),
('string/en/faction_recruiter.stf', 149, 'jedi_cant_resign', 'You may not resign from your faction without first leaving your Enclave.'),
('string/en/faction_recruiter.stf', 150, 'jedi_cant_go_covert', 'As an Enlave member, you may not go covert without first surrendering your Force Rank skills.'),
('string/en/faction_recruiter.stf', 151, 'no_rebel_imp_pilots', 'Overt and Covert Rebels cannot become Imperial Pilots.'),
('string/en/faction_recruiter.stf', 152, 'no_imp_rebel_pilots', 'Overt and Covert Imperials cannot become Rebel Pilots.'),
('string/en/faction_recruiter.stf', 153, 'enemy_pilot', 'Wait a minute... you''re an enemy pilot!  There''s no way I''ll let you join us!'),
('string/en/faction_recruiter.stf', 154, 'overt_complete', 'You are now a member of the Special Forces. You will be attacked by enemy NPCs on sight and are at risk from enemy players.');
