('string/en/food_detail.stf', 1, 'accarragm', 'A strong Wookiee beverage made from fungus and alcohol stock.'),
('string/en/food_detail.stf', 2, 'accarragm_eff', 'Grants enhanced action, quickness, and stamina.'),
('string/en/food_detail.stf', 3, 'ahrisa', 'A spicy food commonly found in cafes on Coruscant.'),
('string/en/food_detail.stf', 4, 'ahrisa_eff', 'Grants enhanced focus.'),
('string/en/food_detail.stf', 5, 'air_cake', 'A simple Corellian dessert cake.'),
('string/en/food_detail.stf', 6, 'aitha', 'A protein drink consumed by spacers to keep their bodies healthy during long runs.  Best served hot.'),
('string/en/food_detail.stf', 7, 'alcohol', 'Basic alcohol stock made from some kind of cereal resource.'),
('string/en/food_detail.stf', 8, 'ale', 'A bottle of thick, foaming ale.'),
('string/en/food_detail.stf', 9, 'almond_kwevvu_crisp_munchies', 'A small pastry eaten by the handful.'),
('string/en/food_detail.stf', 10, 'aludium_pu36', 'A very pure and strong alcoholic stock popular during the Old Republic.  Aludium pu36 has a secret radioactive ingredient, but is safe enough for humanoid consumption.'),
('string/en/food_detail.stf', 11, 'angerian_fishak_surprise', 'A strong mixed, alcoholic drink.'),
('string/en/food_detail.stf', 12, 'antakarian_fire_dancer', 'A thick, potent ale made from alcoholic stock filtered through igneous rock and flavored with crushed gemstone.  This drink is popular with rough and tough types.'),
('string/en/food_detail.stf', 13, 'avian_strips', 'Delicious Avian Strips'),
('string/en/food_detail.stf', 14, 'bantha_blaster', 'A cantina favorite.  Drink with caution.'),
('string/en/food_detail.stf', 15, 'bantha_butter', 'Butter made from a Bantha''s milk.'),
('string/en/food_detail.stf', 16, 'bespin_port', 'A sweet form of port native to Bespin.'),
('string/en/food_detail.stf', 17, 'bio_down', 'You are under the effect of a negative biological effect.'),
('string/en/food_detail.stf', 18, 'bio_kliknik_fortitude_boost', 'An extract from the Kliknik immune system, this chemical coats the users organs with an ultra thin protective layer that insulates them during heavy exertion.  Can cause severe nausea when the body attempts to remove the coating.'),
('string/en/food_detail.stf', 19, 'bio_kwi_adrenal_boost', 'A gland which secretes a fluid into the kwi bloodstream which increases their base regeneration in response to an attack.  Can cause burnout after the boost has run its course.'),
('string/en/food_detail.stf', 20, 'bio_up', 'You are under the effect of a positive biological effect.'),
('string/en/food_detail.stf', 21, 'birthday_cake', 'A scrumptuous birthday cake!'),
('string/en/food_detail.stf', 22, 'bivoli_tempari', 'A very expensive and sweet dish that features toughened meat in a syrupy sauce.'),
('string/en/food_detail.stf', 23, 'blap_biscuit', 'A gooey biscuit served drenched in carbosyrup.'),
('string/en/food_detail.stf', 24, 'blob_candy', 'A popular candy made from a filled blob of carbosyrup.'),
('string/en/food_detail.stf', 25, 'blob_candy_eff', 'Grants enhanced action.'),
('string/en/food_detail.stf', 26, 'blood_chowder', 'A healthy meal made of soypro cooked in purified animal blood.'),
('string/en/food_detail.stf', 27, 'blue_milk', 'A protein enhanced milk beverage that has healing qualities.'),
('string/en/food_detail.stf', 28, 'bofa_treat', 'A sweet, dried, fruit based snackfood.'),
('string/en/food_detail.stf', 29, 'bofa_treat_eff', 'Grants enhanced health.'),
('string/en/food_detail.stf', 30, 'booster_blue', 'An out-of-use industrial dye employed in starship manufacturing that when consumed, enhances the user''s physical reaction time.'),
('string/en/food_detail.stf', 31, 'boullion', 'A cube of boullion.'),
('string/en/food_detail.stf', 32, 'braised_canron', 'A jellied meat carefully braised and seasoned.'),
('string/en/food_detail.stf', 33, 'bread', 'A chunk of bread.'),
('string/en/food_detail.stf', 34, 'bread_loaf_full_s1', 'a Loaf of Bread'),
('string/en/food_detail.stf', 35, 'breath_of_heaven', 'The Galaxy''s most potent fire water: this stuff is as strong as it comes.'),
('string/en/food_detail.stf', 36, 'breath_of_heaven_eff', 'Grants enhanced strength, quickness, and focus.'),
('string/en/food_detail.stf', 37, 'caf', 'A stimulating beverage flavoured with grains or bean extract.'),
('string/en/food_detail.stf', 38, 'caf_eff', 'Grants enhanced willpower.'),
('string/en/food_detail.stf', 39, 'casserole', 'A steaming casserole.'),
