('string/en/food_detail.stf', 41, 'chandad', 'A popular snack food filled with rice and fruit.'),
('string/en/food_detail.stf', 42, 'charde', 'A refreshing beverage flavored with some unidentifiable organic substance.  Best served cold.'),
('string/en/food_detail.stf', 43, 'cho_nor_hoola', 'A vile smelling stew favored by members of the Hutt race.  Only those with willpower can stand to eat a full serving of Cho-Nor-Hoola.'),
('string/en/food_detail.stf', 44, 'citros_snow_cake', 'A delicious pastry made with light fruits and sweet cake mix.'),
('string/en/food_detail.stf', 45, 'cold_cuts', 'Scrumptious slices of cold Meat.'),
('string/en/food_detail.stf', 46, 'corellian_ale', 'Probably the most common alcoholic beverage in the galaxy.  Corellian Ale has a sweet flavor and a medium weight body.'),
('string/en/food_detail.stf', 47, 'corellian_brandy', 'There is no brandy more flavorful and savory than Corellian Brandy.  Must be made with real Corellian fruits...otherwise it''s just brandy.'),
('string/en/food_detail.stf', 48, 'corellian_double_brandy', 'A bottle of Corellian Double Brandy.'),
('string/en/food_detail.stf', 49, 'corellian_fried_icecream', 'Fried icecream with berry topping.'),
('string/en/food_detail.stf', 50, 'corellian_rum', 'A bottle of Corellian Rum.'),
('string/en/food_detail.stf', 51, 'corellian_spiced_ale', 'A bottle of Corellian Spiced Ale.'),
('string/en/food_detail.stf', 52, 'corellian_twister', 'A bottle of Corellian Twister.'),
('string/en/food_detail.stf', 53, 'corellian_whiskey', 'A bottle of Corellian Whiskey.'),
('string/en/food_detail.stf', 54, 'cortyg', 'A strong alcohol produced by Wookiees.'),
('string/en/food_detail.stf', 55, 'crash_n_burn', 'A rare chemical mix of stimulant and depressive, Crash n'' Burn heightens the user''s awareness while at the same time increasing latent psychodepressive tendencies.'),
('string/en/food_detail.stf', 56, 'crispic', 'A fried snack roll...commonly found in cantinas.'),
('string/en/food_detail.stf', 57, 'deneelian_fizz_pudding', 'A rare pudding treat that crackles and pops as you eat it.'),
('string/en/food_detail.stf', 58, 'deuterium_pyro', 'A favorite drink of ruffians, due to its terrible flavor and strong aftertaste.  You have to be tough to put down a Deuterium-pyro.'),
('string/en/food_detail.stf', 59, 'double_dip_outer_rim_rumdrop', 'Native to the Spirited Spirits shop on Cularin, this strong mixed drink is made from a wide range of alcohol stocks.'),
('string/en/food_detail.stf', 60, 'dough', 'A heap of soft dough.'),
('string/en/food_detail.stf', 61, 'drink', 'A drink.'),
('string/en/food_detail.stf', 62, 'drink_nectar', 'A delicious blend of exotic plant nectars, fruit juices and mineral waters.'),
('string/en/food_detail.stf', 63, 'droid_lube', 'Zypolene Droid Lubricant was once used as a very common homemade joint and servo lubricant for robot servants.  After medical studies suggested the substance was the cause of cellular decay among various races, the use of zypolene decreased.  It has a burning, stimulating effect when rubbed across open skin.'),
('string/en/food_detail.stf', 64, 'durindfire', 'A rare alcoholic beverage that lights up with a phosphorescent glow when exposed to oxygen.'),
('string/en/food_detail.stf', 65, 'dustcrepe', 'A light crepe native to Tatooine.'),
('string/en/food_detail.stf', 66, 'dweezel', 'A gooey pastry common to Mos Espa.  Invented by the culinary genius Professor Umlaut.'),
('string/en/food_detail.stf', 67, 'edible_berries', 'Jar of Foraged Berries'),
('string/en/food_detail.stf', 68, 'edible_bugs', 'Jar of Foraged Bugs'),
('string/en/food_detail.stf', 69, 'edible_fungus', 'Jar of Foraged Fungus'),
('string/en/food_detail.stf', 70, 'edible_funk', 'Jar of Foraged Grubs'),
('string/en/food_detail.stf', 71, 'edible_livers', 'Jar of Foraged Livers'),
('string/en/food_detail.stf', 72, 'elshandruu_pica_thundercloud', 'This drink is probably the strongest in the galaxy.  Highly dangerous.'),
('string/en/food_detail.stf', 73, 'exo_protein_wafers', 'Enhanced protein wafers used by space farers during long trips.'),
('string/en/food_detail.stf', 74, 'felbar', 'A baked dessert made with flower fruit.'),
('string/en/food_detail.stf', 75, 'fire_stew', 'A spicy stew flavored with puk and desert flowers.'),
('string/en/food_detail.stf', 76, 'flameout', 'A strange reactive beverage.  It burns the tongue while at the same time freezes the throat.'),
('string/en/food_detail.stf', 77, 'food_additive_heavy', 'A heavy food additive.  This can only be used in a Heavy additive slot during food crafting.'),
('string/en/food_detail.stf', 78, 'food_additive_light', 'A light food additive.  This can be used in a Light, Medium, or Heavy additive slot during food crafting.'),
('string/en/food_detail.stf', 79, 'food_additive_medium', 'A medium food additive.  This can be used in a Medium or Heavy additive slot during food crafting.'),
('string/en/food_detail.stf', 80, 'food_basket', 'A basket of fruits and other food.'),
