('string/en/food_detail.stf', 90, 'force_melon', 'This fruit was picked from the Aurilian plant, a notoriously fickle and difficult plant to grow to fruition. The nectar from this fruit provides a vitalizing rush to those that consume it.'),
('string/en/food_detail.stf', 91, 'fried_endwa', 'A tasty fried meal common on Corellia.'),
('string/en/food_detail.stf', 92, 'fruit', 'A juicy portion of fruit.'),
('string/en/food_detail.stf', 93, 'fruit_melon', 'a Melon'),
('string/en/food_detail.stf', 94, 'garrmorl', 'Another rough Wookiee beverage made from dried bone and hide mixed with alcohol stock.'),
('string/en/food_detail.stf', 95, 'garrmorl_eff', 'Grants enhanced health, strength, and constitution.'),
('string/en/food_detail.stf', 96, 'giggledust', 'An all natural dust that is inhaled to create a sense of euphoria and alertness.'),
('string/en/food_detail.stf', 97, 'glazed_glucose_pate', 'An extremely dense sugar pate.'),
('string/en/food_detail.stf', 98, 'gorrnar', 'A frozen dessert favored by Wookiees.'),
('string/en/food_detail.stf', 99, 'gourd', 'A plain gourd.'),
('string/en/food_detail.stf', 100, 'gralinyn_juice', 'A fermented Wookiee beverage.  Light by Wookiee standards.'),
('string/en/food_detail.stf', 101, 'grey_gabaki', 'A plant named for its drab color when dried, Grey Gabaki gives off a light and relaxing smoke when burned.  It is commonly used in cantinas, but some merchants also burn it to make store fronts a more relaxing environment for customers.'),
('string/en/food_detail.stf', 102, 'ground_meat', 'A handful of ground meat.'),
('string/en/food_detail.stf', 103, 'gruuvan_shaal', 'A traditional Twi''lek meal.'),
('string/en/food_detail.stf', 104, 'gruuvan_shaal_eff', 'Grants enhanced strength.'),
('string/en/food_detail.stf', 105, 'gunjack', 'A highly concentrated methylpenatox and glucose based chemical cocktail that grants the user intense physical strength while decreasing fine motor control and the ability to reason.'),
('string/en/food_detail.stf', 106, 'havla', 'A spiced toast popular with nobility.'),
('string/en/food_detail.stf', 107, 'ice_blaster', 'A warming alcoholic beverage made from Sullustan Gin.'),
('string/en/food_detail.stf', 108, 'ithorian_mist', 'A type of whiskey favored by the Ithorian race.'),
('string/en/food_detail.stf', 109, 'jaar', 'A sweet drink of fermented milk and fruit, favored by Wookiees.'),
('string/en/food_detail.stf', 110, 'jawa_beer', 'A rough travel beer brewed from fermented grains and bantha hide.'),
('string/en/food_detail.stf', 111, 'jerky', 'Some meaty Jerky, dried to last longer but remaining very tasty.'),
('string/en/food_detail.stf', 112, 'kanali_wafers', 'A sugary pastry pressed flat and served chilled.'),
('string/en/food_detail.stf', 113, 'kanali_wafers_eff', 'Grants enhanced constitution.'),
('string/en/food_detail.stf', 114, 'karkan_ribenes', 'Slow cooked meat ribs.'),
