('string/en/food_detail.stf', 116, 'kiwik_clusjo_swirl_eff', 'Grants enhanced quickness and stamina.'),
('string/en/food_detail.stf', 117, 'kylessian_fruit_distillate', 'An alcohol stock distilled from fruits.  This can be used as a component in any recipe requiring alcohol.  In general, Kylessian Fruit Distillate has a higher quality than Sullustan Gin.'),
('string/en/food_detail.stf', 118, 'large_avian', 'A large chunk of avian meat.'),
('string/en/food_detail.stf', 119, 'large_fish', 'A large fish.'),
('string/en/food_detail.stf', 120, 'large_sausage', 'A large sausage.'),
('string/en/food_detail.stf', 121, 'lollipop', 'This lollipop looks deliciously sweet.'),
('string/en/food_detail.stf', 122, 'mandalorian_wine', 'A strong, bitter wine. This drink was made popular in the years following the Mandalorian Wars.'),
('string/en/food_detail.stf', 123, 'marinade', 'A mixture of vinegar, oil, spices and herbs.'),
('string/en/food_detail.stf', 124, 'meat_kabob', 'Meat Kabob'),
('string/en/food_detail.stf', 125, 'meat_loaf', 'A generous cut of meat loaf.'),
('string/en/food_detail.stf', 126, 'meat_skewer', 'A juicy skewer of meat, vegetables, and fruit.'),
('string/en/food_detail.stf', 127, 'meatlump', 'A processed and compressed meat hunk used in space station food stores.'),
