('string/en/food_detail.stf', 129, 'melon', 'A nice round melon.'),
('string/en/food_detail.stf', 130, 'milk', 'Some milk.'),
('string/en/food_detail.stf', 131, 'muon_gold', 'A subatomic reactant that results in intense mental clarity and focus.  Banned by Imperial authorities due to its degenerative effect on neural pathways.'),
('string/en/food_detail.stf', 132, 'nanana_twist', 'A candy made with inert gas and berry fruit.'),
('string/en/food_detail.stf', 133, 'neutron_pixey', 'A calming hallucinogen of unknown alien origin, Neutron Pixie is usually ingested with a light fruit flavoring to increase palatability.'),
('string/en/food_detail.stf', 134, 'ormachek', 'A healthy wrapped meal favored by Mon Calamari for its memory enhancing properties.'),
('string/en/food_detail.stf', 135, 'para_roll', 'A fruity wheat based pastry.'),
('string/en/food_detail.stf', 136, 'parwan_nutricake', 'A healthy bread-like dessert.'),
('string/en/food_detail.stf', 137, 'pastebread', 'A thin pastry bread.'),
