('string/en/food_detail.stf', 145, 'puffcake', 'A small dessert pastry popular with children.'),
('string/en/food_detail.stf', 146, 'puk', 'A vegetable commonly grown in private hydroponics bays.'),
('string/en/food_detail.stf', 147, 'pyollian_cake', 'Extra sweet gooey cake made with carbosyrup.'),
('string/en/food_detail.stf', 148, 'pyrepenol', 'A concentrated pyrepenol pill.  When consumed it results in heightened physical strength.'),
('string/en/food_detail.stf', 149, 'rack_of_meat', 'A rack of meat.'),
('string/en/food_detail.stf', 150, 'rakririan_burnout_sauce', 'An extremely spicy sauce!  Be careful!'),
('string/en/food_detail.stf', 151, 'ramorrean_capanata', 'A popular pasta that tastes best when served with seafood.'),
('string/en/food_detail.stf', 152, 'rations', 'Military quality rations often found on large starliners.'),
('string/en/food_detail.stf', 153, 'ribs', 'A section of ribs.'),
('string/en/food_detail.stf', 154, 'ruby_bliel', 'A non-alcoholic fruit drink favored by children.'),
('string/en/food_detail.stf', 155, 'ryshcate', 'A dark brown Corellian sweetbread served on birthdays.'),
('string/en/food_detail.stf', 156, 'sandwich', 'A delicious sandwich.'),
('string/en/food_detail.stf', 157, 'sausage_links', 'A string of sausage links.'),
('string/en/food_detail.stf', 158, 'scramjet', '"Scramjet" is the rough street name for a body building food additive.  Due to its distorting and potentially harmful effects on humanoid biology, scramjet has been outlawed on Imperial worlds.'),
('string/en/food_detail.stf', 159, 'scrimpi', 'A meat dish common to cantina menus.'),
('string/en/food_detail.stf', 160, 'scrimpi_eff', 'Grants enhanced quickness.'),
('string/en/food_detail.stf', 161, 'sedative_h4b', 'A medical sedative used on battle fields to treat traumatic injuries.  H4b''s strong depressive properties result in it often being used for recreational purposes.'),
('string/en/food_detail.stf', 162, 'shadowpaw', 'Shadowpaw is the name of the powder that remains when the Edorian Itassi root is ground up.  This powder was originally used by the native Ewok race in spiritual ceremonies via a long bone pipe, but has since found a place in various cantinas and criminal dives.'),
('string/en/food_detail.stf', 163, 'shot', 'A shot, filled to the brim.'),
('string/en/food_detail.stf', 164, 'skannbult_likker', 'A rare beverage distilled from special types of corn and wheat.'),
('string/en/food_detail.stf', 165, 'slice_of_cake', 'A slice of cake.'),
('string/en/food_detail.stf', 166, 'sliced_meats', 'A platter of sliced meats.'),
('string/en/food_detail.stf', 167, 'small_avian', 'A small chunk of avian meat.'),
('string/en/food_detail.stf', 168, 'smugglers_delight', 'A sweet pastry with a hollow center.'),
('string/en/food_detail.stf', 169, 'soup', 'A hot bowl of soup.'),
('string/en/food_detail.stf', 170, 'soypro', 'A protein fortified meat substitute.'),
('string/en/food_detail.stf', 171, 'spice', 'A vial of spice.'),
('string/en/food_detail.stf', 172, 'spice_down', 'You are suffering from the downer effects of the spice.'),
('string/en/food_detail.stf', 173, 'spice_up', 'You are enhanced by the positive effects of the spice.'),
('string/en/food_detail.stf', 174, 'spiced_tea', 'A beverage consisting of water flavored by strong spices.'),
('string/en/food_detail.stf', 175, 'spiced_tea_eff', 'Grants enhanced mind.'),
('string/en/food_detail.stf', 176, 'starshine_surprise', 'A strong alcoholic beverage infused with reactive gas.  Often lit on fire before consumed.'),
('string/en/food_detail.stf', 177, 'stewed_gwouch', 'A highly nutritional food...the flavor leaves something to be desired.'),
('string/en/food_detail.stf', 178, 'stuffing', 'Some hearty stuffing.'),
('string/en/food_detail.stf', 179, 'sullustan_gin', 'A common form of gin distilled by the Sullustan race.  This gin has a light flavor and may be used as a base for other recipes requiring alcohol.'),
('string/en/food_detail.stf', 180, 'sweesonberry_rolls', 'A sticky, sweet pastry.'),
('string/en/food_detail.stf', 181, 'sweet_cake_mix', 'A special pre-sweetened cake mix.'),
('string/en/food_detail.stf', 182, 'sweetblossom', 'A thick fluid made from the Sweetblossom with strong sedative properties.  Sometimes used as a field anaesthetic or truth serum.'),
('string/en/food_detail.stf', 183, 'synthsteak', 'A tasty fortified steak substitute designed to withstand long space travel.'),
('string/en/food_detail.stf', 184, 'tatooine_sunburn', 'Native to the Mos Eisley Cantina, Tatooine Sunburn is a rough drink that will put you under the table quick...which is exactly where most thieves want you.'),
('string/en/food_detail.stf', 185, 'tea', 'A glass of spiced tea.'),
('string/en/food_detail.stf', 186, 'telteir_noodles_eff', 'Grants enhanced stamina.'),
('string/en/food_detail.stf', 187, 'teltier_noodles', 'A vegetable and noodle dish served lukewarm.  The noodles are usually mushy and only slightly cooked.'),
('string/en/food_detail.stf', 188, 'terratta', 'A dish made from hide strips smothered in oil and milk.'),
('string/en/food_detail.stf', 189, 'thakitillo', 'A curdled dish known for the tangy explosion of flavor experienced when mashed against the roof of the mouth.'),
('string/en/food_detail.stf', 190, 'thruster_head', 'Thruster Head is the street name for an intense synaptic enhancement stim.  When injected Thruster Head multiplies the user''s mental capabilities ten fold, at the cost of increased anxiety and extreme nausea.'),
('string/en/food_detail.stf', 191, 'tilla_tiil', 'A sparkling Twi''lek wine notable for the triple carbonation and filtering process used in its creation.'),
('string/en/food_detail.stf', 192, 'tranna_nougat_cream', 'A sweet candy that is extremely difficult to make.  It is favored by the rich and powerful.'),
('string/en/food_detail.stf', 193, 'travel_biscuits', 'Hearty biscuits full of nutrients for long trips.'),
('string/en/food_detail.stf', 194, 'tray_of_cookies', 'A tray of soft, fresh cookies.'),
('string/en/food_detail.stf', 195, 'tray_of_pastries', 'An assortment of soft pastries on a tray.'),
('string/en/food_detail.stf', 196, 'trimpian', 'Sliced meat served in a seasoned miasra sauce.'),
('string/en/food_detail.stf', 197, 'triple_meat_wrap', 'A tasty Triple Meat Wrap, three meats wrapped in a thin bit of leathery hide.'),
('string/en/food_detail.stf', 198, 'tssolok', 'T''ssolok is an intense Twi''lek liquor that is always served in a decorative decanter.  While the standing flavor of T''ssolok is not particularly good, the aftertaste is delicious.'),
('string/en/food_detail.stf', 199, 'vagnerian_canape', 'A sweet pastry often served at formal dinners.'),
('string/en/food_detail.stf', 200, 'vagnerian_canape_eff', 'Grants enhanced focus and willpower.'),
