('string/en/fs_quest_village.stf', 92, 'fs_remote_fail', 'Nothing happens.'),
('string/en/fs_quest_village.stf', 93, 'fs_cs_step_intro_complete', 'You have completed the mission step ''Power Down The Shield Generator''.   The next step is to dispatch at least 5 of the defending enemy forces.  You must also take care to stay alive to oversee the capture of the camp commander.   Failure is not an option.'),
('string/en/fs_quest_village.stf', 94, 'fs_cs_last_chance_sum', 'Capture the Commander!'),
('string/en/fs_quest_village.stf', 95, 'fs_cs_last_chance_detail', 'Since you failed to fend off the camp guards, your only chance of completing your mission at this camp is to capture the camp''s commander yourself and return him safely to Captain Sarguillo in the Aurilian village.  If you choose not to complete your mission at this camp, you may attempt to complete this mission again at a later time. '),
('string/en/fs_quest_village.stf', 96, 'fs_remote_dont_have', 'You don''t have the proper data disk.'),
('string/en/fs_quest_village.stf', 97, 'camp_commander_capture', 'Capture!'),
('string/en/fs_quest_village.stf', 98, 'camp_commander_no_auth', 'You do not have the authority to capture the commander.  You must either be the person who powered down the shield generator or be in a group with that person.'),
('string/en/fs_quest_village.stf', 99, 'camp_last_chance_complete', 'You have captured the commander!  You may still earn credit for this mission if you are able to safely return him to the Aurilian village.'),
('string/en/fs_quest_village.stf', 100, 'fs_cs_ensure_sum', 'Ensure the Commander Is Captured'),
('string/en/fs_quest_village.stf', 101, 'fs_cs_ensure_detail', 'Ensure that the commander of the camp is captured.  You can either capture him yourself, or someone on the same mission and in the same group as you can capture him.'),
('string/en/fs_quest_village.stf', 102, 'fs_primary_escort_fail', 'You have failed to escort the commander back to the Aurilian village and have thus failed your mission.  You may attempt the mission again at another camp.'),
('string/en/fs_quest_village.stf', 103, 'fs_cs_capd_commander', 'You have taken custody of the base commander.  Ensure the commander''s safe return to the village of Aurilia.  A waypoint has been added to your datapad.  If the commander is not safely returned to the village before he dies, no one who has participated in this mission will receive credit.  Should you lose custody of the commander, you will fail this mission.'),
('string/en/fs_quest_village.stf', 104, 'fs_cs_commander_cap_other', 'The commander has been captured by someone in your group other than yourself.  You have failed this mission.  You may attempt this mission again by finding another enemy camp and infiltrating according to your previous instructions.  See your quest journal for details.'),
('string/en/fs_quest_village.stf', 105, 'fs_cs_escort_commander_sec', 'The commander has been captured by someone in your group.  You must ensure that he is delivered to Aurilia safe and sound.  \n\nIf the commander does not make it to the village, you will not receive credit for this mission.  Should something unspeakable happen to your party member and they can no longer retain custody of the commander, you may recapture the commander if you can catch up with him.  This way you can still receive credit for the mission, even if your partner fails.'),
('string/en/fs_quest_village.stf', 106, 'fs_cs_recapture', 'Recapture!'),
('string/en/fs_quest_village.stf', 107, 'fs_cs_quest_done_sum', 'Quest Complete!'),
('string/en/fs_quest_village.stf', 108, 'fs_cs_quest_done_detail', 'You have completed the mission given to you by the villagers.  As a measure of gratitude you will now be able to receive Melee Accuracy training.  Your other rewards have been placed in your inventory.'),
('string/en/fs_quest_village.stf', 109, 'commander_death_notify', 'HA HA!  You fools.  I will never divulge my secrets.  *crunch* *swallow*\nI will be dead long before I ever see an interrogation chamber.'),
('string/en/fs_quest_village.stf', 110, 'remote_break', 'The remote control unit pops and crackles as you use it, eventually burning up.  The remote has been destroyed.'),
('string/en/fs_quest_village.stf', 111, 'fs_cs_capd_commander_via_group', 'You have taken custody of the base commander.  Ensure the commander''s safe return to the village of Aurilia.  A waypoint has been added to your datapad.  If the commander is not safely returned to the village before he dies, no one who has participated in this mission will receive credit.  Should you lose custody of the commander, you will fail this mission.  If you fail the mission, you will be able to attempt it again at another enemy camp.'),
('string/en/fs_quest_village.stf', 112, 'commander_is_free', 'Your companion has failed!  The commander has escaped and is making a run for it!  Catch him if you can.  You can still earn credit for this mission if you recapture the commander and safely return him to the Aurilian village yourself.'),
('string/en/fs_quest_village.stf', 113, 'quest_complete', 'The commander has been successfully returned to the Aurilian village for interrogation.  For your efforts, you will now be allowed to train in melee accuracy!  You have also been awarded a special color crystal that may be of use later on down the road as you begin to craft your first lightsaber.'),
('string/en/fs_quest_village.stf', 114, 'teamwork_bonus', 'As a special bonus for completing this mission alongside a fellow adventurer, displaying unity and teamwork, the Aurilian elder has authorized a special reward for you that will help you in future conflicts.  Your extra reward has also been placed in your inventory.'),
('string/en/fs_quest_village.stf', 115, 'commander_already_capd', 'This base commander is already being escorted.'),
('string/en/fs_quest_village.stf', 116, 'commander_died_toxins', 'The commander you were responsible for escorting to the Aurilian village has perished, apparently from ingesting a variety of biotoxins.  You have failed your mission.  You may reattempt your mission at another enemy camp.'),
('string/en/fs_quest_village.stf', 117, 'commander_pain', 'ARGH!  The pain... terrible... HA HA Ha... argh...'),
('string/en/fs_quest_village.stf', 118, 'commander_pain2', 'The poison has taken its course.  You meddleso... ARGH!  *cough*'),
('string/en/fs_quest_village.stf', 119, 'commander_pain3', '*gurgle*'),
('string/en/fs_quest_village.stf', 120, 'commander_too_far', 'You''re going to have to get closer than that to recapture the commander!'),
('string/en/fs_quest_village.stf', 121, 'combat_quest_failed_timeout', 'You have failed to complete your quest on time.  You may try again the next time it becomes available.'),
('string/en/fs_quest_village.stf', 122, 'quest_logout', 'It appeared that you had abandoned your mission, so you must begin your mission from the start once more.'),
('string/en/fs_quest_village.stf', 123, 'mission_time_failed', 'You did not extract the commander in time.  The shields have powered back on and you have failed your mission attempt.  You may try again at any time.'),
('string/en/fs_quest_village.stf', 124, 'rescue1', 'Unhand our commander!'),
('string/en/fs_quest_village.stf', 125, 'rescue2', 'I shall have your life if you do not release our commander!  STOP RIGHT THERE!'),
('string/en/fs_quest_village.stf', 126, 'rescue3', 'You will not live to regret the decision to help those meddlesome Aurilians!'),
('string/en/fs_quest_village.stf', 127, 'rescue4', 'UNHAND THE COMMANDER!'),
('string/en/fs_quest_village.stf', 128, 'rescue5', 'HALT!  Release our commander, or I will take your life here and now!'),
('string/en/fs_quest_village.stf', 129, 'rescue6', 'Slay the commander''s captors!  Leave none alive.'),
('string/en/fs_quest_village.stf', 130, 'rescue7', 'Let the land be drenched in the blood of those who oppose our will.  FREE THE COMMANDER!'),
('string/en/fs_quest_village.stf', 131, 'rescue8', 'I''ve spotted the commander.  Requesting reinforcement at my coordinates!'),
('string/en/fs_quest_village.stf', 132, 'rescue9', 'Where are those reinforcements?!?!?  No matter.   ATAAAAACK!'),
('string/en/fs_quest_village.stf', 133, 'rescue10', 'ATTAAAAAAAAACK!'),
('string/en/fs_quest_village.stf', 134, 'p3_item_decayed', 'That item''s circuitry has decayed beyond use.  It is useless. '),
('string/en/fs_quest_village.stf', 135, 'arrived_without_commander', 'You have failed to escort the commander back to the Aurilian village and have thus failed your mission.  You have failed this attempt at your quest.  You may try again at another camp.'),
('string/en/fs_quest_village.stf', 136, 'groupmate_powered_down', 'One of your groupmates has successfully dispatched a number of enemy troops.  The base commander has emerged inside of the camp and may be captured.'),
