INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/game_language.stf', 15, 'lekku', 'Lekku'),
('string/en/game_language.stf', 16, 'basic', 'Basic'),
('string/en/game_language.stf', 17, 'usage', 'Usage: /language <language>'),
('string/en/game_language.stf', 18, 'lekku_no_comprehend', '%TT communicates in a body language that you do not understand.'),
('string/en/game_language.stf', 19, 'not_fluent_in_language', 'You are not fluent in the language %TT.'),
('string/en/game_language.stf', 20, 'prose_comprehend', 'and comprehend %DI languages.'),
