('string/en/game_language.stf', 25, 'sullustan', 'Sullustese'),
('string/en/gcw.stf', 5, 'newsnet_extra', 'EXTRA! EXTRA!'),
('string/en/gcw.stf', 6, 'newsnet_terminal', 'Newsnet Terminal'),
('string/en/gcw.stf', 7, 'newsnet_read_all', 'EXTRA! EXTRA! READ ALL ABOUT IT!'),
('string/en/gcw.stf', 8, 'headline_naboo_rebel_losing_4', '          Imperial Forces Plan Celebration\nTheed, Naboo (IP) -- Imperial Officers got to\nplan something different today, a party.  After months \nof battle, they finally get to turn their attention to more\nrelaxing matters.'),
('string/en/gcw.stf', 9, 'headline_naboo_rebel_losing_3', '          Rebel Terrorist Forces Dwindling\nMoenia, Naboo (IP) -- Reports from outlying \nsystems today indicate that the vast majority of  \nRebel soldiers are abandoning their posts in\nan attempt to escape the Imperial onslaught.'),
('string/en/gcw.stf', 10, 'headline_naboo_rebel_losing_2', '          Rebel Terrorists Suffer Serious Defeat\nTheed, Naboo (IP) -- Imperial Officers promoted  \nhundreds of soldiers today, following fierce fighting\nin which the Imperial Army overwhelmed a Rebel\ngarrison.'),
('string/en/gcw.stf', 11, 'headline_naboo_rebel_losing_1', '          Tide Turns Against Rebel Agitators\nTheed, Naboo (IP) -- Agitators and threats to\nGalactic security.  That''s what the Imperial Soldiers \nare calling the now thousands strong ''Alliance''.\n'),
('string/en/gcw.stf', 12, 'headline_naboo_equal', '          War Continues, Emperor Confidant\nTheed, Naboo (IP) -- The Emperor enjoyed a \nquiet day at his retreat on Naboo today, taking a  \nbreak from military matters.  "He''s confidant that\nthe conflict will be resolved equitably".'),
('string/en/gcw.stf', 13, 'headline_naboo_rebel_winning_1', '          Lord Vader Leads Forces Personally\nTheed, Naboo (IP) -- It has come to this.  Lord\nVader himself is moving his personal troops to the\nfront lines to break up the Rebel assaults.'),
('string/en/gcw.stf', 14, 'headline_naboo_rebel_winning_2', '          Imperial Losses Due To Treason!\nTheed, Naboo (IP) -- Old Republic Supporters are\nbeing blamed for what can only be described as a\nmilitary fiasco.  Information about troop movement\nwas leaked to Rebel terrorists by unknown insurgents.'),
('string/en/gcw.stf', 15, 'headline_naboo_rebel_winning_3', '          Rebel Forces Building Super Weapon?\nMoenia, Naboo (IP) -- Information gathered from\ncaptured Rebel Pilots indicates that the Rebels are \nworking on some kind of ''Super Laser'' capable of\nplanetary destruction.'),
('string/en/gcw.stf', 16, 'headline_naboo_rebel_winning_4', '          Rebel Terrorists Spread Disinformation!\nTheed, Naboo (IP) -- Information about the\nfighting going on in distant systems is not ent-\nirely accurate.  Rebel spies are planting disinformation\non Imperial newsnet terminals in an attempt to discredit\nthe Empire.'),
('string/en/gcw.stf', 17, 'headline_corellia_rebel_losing_4', '          Rebel Forces Devastated!\nCoronet, Corellia (CP) -- Rebel forces suffered devastating\ncasualties this week in an Imperial attack. Casualties were\nunusually high, indicating a failure in Rebellion intelligence. \n'),
('string/en/gcw.stf', 18, 'headline_corellia_rebel_losing_3', '          Rebel Forces Fear No End In Sight\nCoronet, Corellia (CP) -- Rebel forces fear the \nfight against the Empire may continue indefinitely. \nHope for a cease fire vanished last week.'),
('string/en/gcw.stf', 20, 'headline_corellia_rebel_losing_1', '          Rebel Forces Suffer Setback\nCoronet, Corellia (CP) -- Rebel forces suffered \na setback at Imperial hands today. 3 are dead \nand 12 wounded in fierce fighting. '),
('string/en/gcw.stf', 21, 'headline_corellia_rebel_winning_1', '          Imperial Units Continue Deployment\nTheed, Naboo (CP) -- Imperial forces continued\ndeployment, undeterred, even in the face of \nincreased casualties this week. Morale remains \nmixed with the recent casualties.\n'),
('string/en/gcw.stf', 22, 'headline_corellia_rebel_winning_2', '          Imperial Leaders Concerned Over Losses\nTheed, Naboo (CP) -- Imperial leaders are concerned\nover recent casualties. Logistical and supply failures this\nweek have led to increased losses amongst Imperial forces.\n'),
('string/en/gcw.stf', 23, 'headline_corellia_rebel_winning_3', '          Imperial Leaders Unhappy With Progress\nTheed, Naboo (CP) -- Imperial leaders are unhappy\nwith progress against the Rebellion. Numerous unnamed\nsources have voiced concerns that more troops are needed.\n'),
('string/en/gcw.stf', 24, 'headline_corellia_rebel_winning_4', '          Ex-Senator Calls For Troop Exit Plan\nTheed, Naboo (CP) -- Recent heavy Imperial losses have\nled senator Mcnamara to call for a full troop withdrawal\nfrom the Rebel conflict. ''We must protect the lives of our \nsoldiers from these terrorist attacks.''\n'),
('string/en/gcw.stf', 25, 'headline_general_rebel_losing_4', '          Imperial Victory Assured\nMos Espa, Tatooine (IP) -- Imperial Officers today \ndeclared through official channels that the battle\nwith the Rebellion is about to end.  \n'),
('string/en/gcw.stf', 26, 'headline_general_rebel_losing_3', '          Imperial Senate Happy With War Progress\nTheed, Naboo (IP) -- Rebellion leaders, speaking\nunder conditions of anonymity, spoke frankly about \nrecent failures in the fight against the Empire. \n'),
('string/en/gcw.stf', 27, 'headline_general_rebel_losing_2', '          Rebel Leaders Losing Confidence\nCoronet, Corellia (IP) -- Rebellion leaders, speaking\nunder conditions of anonymity, spoke frankly about \nrecent failures in the fight against the Empire.'),
('string/en/gcw.stf', 28, 'headline_general_rebel_losing_1', '          Rebellion Puts Out Call For Enlistees\nCoronet, Corellia (IP) -- Rebellion spokesmen released another statement yesterday requesting able \nbodied citizens to enlist in the fight against the Empire.\n'),
('string/en/gcw.stf', 29, 'headline_general_equal', '          Worrt Invasion Leaves Homeowners Hopping Mad\nMos Espa, Tatooine (IP) -- KROAAAK! Mos Espa homeowners\nawoke to an unpleasant surprise last week. Local Worrt \npopulations have spiraled out of control in recent weeks.\n'),
('string/en/gcw.stf', 30, 'headline_general_rebel_winning_1', '          Imperial Fleet Suffers Defeat\nMos Eisley, Tatooine (IP) -- Rumors over the past \nfew days indicated that a team of Alliance pilots, fly-\ning with no air support, destroyed a Super Star Destroyer\nin orbit around Tatooine.\n'),
('string/en/gcw.stf', 31, 'headline_general_rebel_winning_2', '          Imperial Forces Lose Ground\nMos Espa, Tatooine (IP) -- Imperial Forces were \nstunned today, after a serious defeat at the hands\nof what amounted to ''poorly armed partisan soldiers''.\n'),
('string/en/gcw.stf', 32, 'headline_general_rebel_winning_3', '          Rebel Forces Optimistic\nMos Espa, Tatooine (IP) -- With a series of \nincredible victories over a superior army, Rebel \nsupporters are becoming more and more optimistic.\n'),
('string/en/gcw.stf', 33, 'headline_general_rebel_winning_4', '          Rebel Victory Near\nMos Taike, Tatooine (IP) -- "We look forward to\na peace accord, signed by the Emperor himself." \nThese were the words of a Rebel General who spoke\noff the record to reporters.'),
('string/en/gcw.stf', 34, 'story_corellia_rebel_losing_1', 'Coronet, Corellia (CP) -- Rebel forces suffered \na setback at Imperial hands today. 34 are reported \ndead and 95 wounded in fierce fighting.'),
('string/en/gcw.stf', 35, 'corellia_newsnet_name', 'Corellia Metropolitan '),
('string/en/gcw.stf', 36, 'headline_corellia_rebel_losing_2', '          Imperial Leaders Optimistic\nTheed, Naboo (CP) -- Imperial Leaders are optimistic tod-\nay, indicating that fighting against the Rebels has taken a\nturn to their advantage. '),
('string/en/gcw.stf', 37, 'headline_corellia_equal', '          Peaceful Solution May Be On Horizon\nCoronet, Corellia (CP) -- Information coming \nfrom Naboo today indicates that a peacful solution\nto the fighting may be closer than we think.  \n'),
('string/en/gcw.stf', 38, 'gcw_status_change', 'GCW STATUS CHANGE CONFIRMATION'),
('string/en/gcw.stf', 39, 'gcw_status_change_overt', 'You are changing your GCW Status to ''Special Forces''. This transition will take 5 minutes. It will allow you to attack and be attacked by hostile players and NPC''s.Type YES in this box to confirm the change.'),
('string/en/gcw.stf', 40, 'gcw_status_change_covert', 'You are changing your GCW Status to ''Combatant''. This transition will take 30 seconds. It will allow you to attack and be attacked by enemy NPC''s. Type YES in this box to confirm the change.'),
('string/en/gcw.stf', 41, 'handle_go_covert', 'You will be flagged as a Combatant in 30 seconds.'),
('string/en/gcw.stf', 42, 'abort_field_change', 'You cancel your factional change.'),
('string/en/gcw.stf', 43, 'naboo_newsnet_name', 'The Nabooian Citizen'),
('string/en/gcw.stf', 44, 'general_newsnet_name', 'The Times'),
('string/en/gcw.stf', 45, 'read_headline', 'Read Headline'),
('string/en/gcw.stf', 46, 'gcw_status_info', 'To see the status of the Galactic Civil War, either talk to your local factional recruiter, or read the newsnet terminals in your nearest starport.'),
('string/en/gcw.stf', 47, 'cannot_change_from_combatant_in_field', 'You cannot change you status to combatant in the field. Go talk to a faction recruiter.'),
('string/en/gcw.stf', 48, 'too_many_bases', 'There are too many bases in this area. Move to a new location and try again.'),
('string/en/gcwlaunchevent.stf', 1, 'dialogue_0_1_1', 'Today marks a turning point in this Galactic Civil War...'),
('string/en/gcwlaunchevent.stf', 2, 'dialogue_0_1_2', 'For too long has this Rebellion remained in our midst, but no longer will such an affront be tolerated.'),
('string/en/gcwlaunchevent.stf', 3, 'dialogue_0_1_3', 'Order must be restored.'),
('string/en/gcwlaunchevent.stf', 4, 'dialogue_0_1_4', 'Effective immediately, known Rebels and all Jedi will be shot on sight by Imperial troops.'),
('string/en/gcwlaunchevent.stf', 5, 'dialogue_0_1_5', 'To bring law and order to the cities we must first control the outlying areas by establishing a military presence in the form of outposts and bases.'),
('string/en/gcwlaunchevent.stf', 6, 'dialogue_0_1_6', 'If we are able to control enough of the outlying areas, we will also control the cities. '),
('string/en/gcwlaunchevent.stf', 7, 'dialogue_0_1_7', 'Only by establishing Imperial bases across this planet, we can achieve our goal of controlling the cities and crushing all resistance. '),
('string/en/gcwlaunchevent.stf', 8, 'dialogue_0_1_8', 'Allowing the rebellion to establish control will not be tolerated.'),
('string/en/gcwlaunchevent.stf', 9, 'dialogue_0_1_9', 'I have seen all that is necessary. '),
('string/en/gcwlaunchevent.stf', 10, 'dialogue_0_1_10', 'I will make sure the Emperor knows of your loyalty.'),
('string/en/gcwlaunchevent.stf', 11, 'dialogue_0_1_11', 'You have your orders. Dismissed.'),
('string/en/gcwlaunchevent.stf', 12, 'dialogue_1_1_1', 'Friends and allies of the Rebellion:  The end of tyranny begins today...'),
('string/en/gcwlaunchevent.stf', 13, 'dialogue_1_1_2', 'The Empire has ruled us with fear and lies long enough. '),
('string/en/gcwlaunchevent.stf', 14, 'dialogue_1_1_3', 'Dark Jedi and others known to fight for the Empire wander freely though our cities.'),
('string/en/gcwlaunchevent.stf', 15, 'dialogue_1_1_4', 'Peace must be restored, and so, we must band together and fight.'),
('string/en/gcwlaunchevent.stf', 16, 'dialogue_1_1_5', 'First we must fight Imperial oppression in the outlying areas.  '),
('string/en/gcwlaunchevent.stf', 17, 'dialogue_1_1_6', 'We will establish Rebel bases on this planet, beacons of hope and justice.'),
('string/en/gcwlaunchevent.stf', 18, 'dialogue_1_1_7', 'Once we have the support of the smaller towns, we will see the populace rise to support us. '),
('string/en/gcwlaunchevent.stf', 19, 'dialogue_1_1_8', 'I call upon you all to do what is right. We must fight this evil here and now. '),
('string/en/gcwlaunchevent.stf', 20, 'dialogue_1_1_9', 'That is all I can ask. Be careful and fight well. '),
('string/en/gcwlaunchevent.stf', 21, 'dialogue_1_1_10', 'Our freedom and future is in your hands. '),
('string/en/gcwlaunchevent.stf', 22, 'dialogue_1_1_11', 'May the Force be with you all.'),
('string/en/gcwlaunchevent.stf', 23, 'dialogue_0_2_1', 'Greetings, citizens of the Empire.  I bring you dark news.'),
('string/en/gcwlaunchevent.stf', 24, 'dialogue_0_2_2', 'The Emperor is angry.'),
('string/en/gcwlaunchevent.stf', 25, 'dialogue_0_2_3', 'The Rebellion has too long been a thorn in the side of progress and order.'),
('string/en/gcwlaunchevent.stf', 26, 'dialogue_0_2_4', 'He wishes this insignificant uprising to be crushed, and quickly.'),
('string/en/gcwlaunchevent.stf', 27, 'dialogue_0_2_5', 'From this day forward, no Rebel presence shall be tolerated. '),
('string/en/gcwlaunchevent.stf', 28, 'dialogue_0_2_6', 'Any illegal sympathizers or Jedi are to be shot on sight, no questions asked.'),
('string/en/gcwlaunchevent.stf', 29, 'dialogue_0_2_7', 'In addition, the Emperor commands that you establish military bases and outposts in the outlying regions, so that insurrections can be crushed immediately.'),
('string/en/gcwlaunchevent.stf', 30, 'dialogue_0_2_8', 'Once this perimeter has been established, he wishes that the cities be controlled unilaterally by the Empire.'),
('string/en/gcwlaunchevent.stf', 31, 'dialogue_0_2_9', 'Do not disappoint him.  I needn''t remind you, the Emperor is not as forgiving as I am.'),
('string/en/gcwlaunchevent.stf', 32, 'dialogue_0_2_10', 'You have your orders. '),
('string/en/gcwlaunchevent.stf', 33, 'dialogue_0_2_11', 'I suggest you carry them out without further delay.'),
('string/en/gcwlaunchevent.stf', 34, 'dialogue_0_3_1', 'Citizens of the Empire, I have come to declare an end to the Rebellion.'),
('string/en/gcwlaunchevent.stf', 35, 'dialogue_0_3_2', 'From now on, all members of the Rebellion are to be terminated on sight.  No mercy shall be shown.  '),
('string/en/gcwlaunchevent.stf', 36, 'dialogue_0_3_3', 'And any of the so-called Jedi Knights are to be similarly dealt with.'),
('string/en/gcwlaunchevent.stf', 37, 'dialogue_0_3_4', 'The Emperor has tolerated their presence long enough.  But even his graciousness and forgiveness has a limit.'),
('string/en/gcwlaunchevent.stf', 38, 'dialogue_0_3_5', 'To achieve absolute control of this sector, we must control the cities.  '),
('string/en/gcwlaunchevent.stf', 39, 'dialogue_0_3_6', 'And so, the Emperor commands all his allies to establish military bases and outposts in the outlying areas.'),
('string/en/gcwlaunchevent.stf', 40, 'dialogue_0_3_7', 'Once we have gained control of the countryside, we shall consolidate our control of the cities. '),
('string/en/gcwlaunchevent.stf', 41, 'dialogue_0_3_8', 'And then, we shall be unstoppable.'),
('string/en/gcwlaunchevent.stf', 42, 'dialogue_0_3_9', 'Should you fail to achieve this goal, I may be forced to return to this dismal planet, and oversee its administration.  '),
('string/en/gcwlaunchevent.stf', 43, 'dialogue_0_3_10', 'Pray that does not come to pass, for I have little sympathy for failure.'),
('string/en/gcwlaunchevent.stf', 44, 'dialogue_0_3_11', 'By the Emperor''s command.  Farewell.'),
('string/en/gcwlaunchevent.stf', 45, 'dialogue_1_2_1', 'Friends of the Rebellion, hear my call to action.'),
('string/en/gcwlaunchevent.stf', 46, 'dialogue_1_2_2', 'Today we draw a line in the sand, and declare that the Empire will rule us no more. '),
('string/en/gcwlaunchevent.stf', 47, 'dialogue_1_2_3', 'Rise up and fight, my friends!  '),
('string/en/gcwlaunchevent.stf', 48, 'dialogue_1_2_4', 'All Imperials and Dark Jedi must be confronted and defeated!'),
('string/en/gcwlaunchevent.stf', 49, 'dialogue_1_2_5', 'Take the battle against them to the very streets of the city.'),
('string/en/gcwlaunchevent.stf', 50, 'dialogue_1_2_6', 'We can control this sector if we band together and fight.'),
('string/en/gcwlaunchevent.stf', 51, 'dialogue_1_2_7', 'Establish new Rebel bases in the outlying country, as many as you can.'),
('string/en/gcwlaunchevent.stf', 52, 'dialogue_1_2_8', 'From there, we can gain the trust and cooperation of the populace, and control the very cities themselves!'),
('string/en/gcwlaunchevent.stf', 53, 'dialogue_1_2_9', 'If we continue to fight and build and persevere, even the might of the Empire cannot crush our spirits.'),
('string/en/gcwlaunchevent.stf', 54, 'dialogue_1_2_10', 'Friends of the Rebellion, you are my only hope.'),
('string/en/gcwlaunchevent.stf', 55, 'dialogue_1_2_11', 'May the force be with you all.'),
('string/en/gcwlaunchevent.stf', 56, 'dialogue_1_3_1', 'This is our most desperate hour.'),
('string/en/gcwlaunchevent.stf', 57, 'dialogue_1_3_2', 'If we do not oppose the Empire now, we shall be pushed into the farthest reaches of the Outer Rim, or rounded up like criminals.'),
('string/en/gcwlaunchevent.stf', 58, 'dialogue_1_3_3', 'The Rebellion must have safe haven, in order to grow, thrive, and overthrow this evil Empire.'),
('string/en/gcwlaunchevent.stf', 59, 'dialogue_1_3_4', 'To that end, friends and allies, I call upon you to establish Rebel bases and outposts all through the outlying areas of this region.'),
('string/en/gcwlaunchevent.stf', 60, 'dialogue_1_3_5', 'Every Rebel base brings us that much closer to control of the cities.'),
('string/en/gcwlaunchevent.stf', 61, 'dialogue_1_3_6', 'And if we control the cities, there''s no end to the good we can do.'),
('string/en/gcwlaunchevent.stf', 62, 'dialogue_1_3_7', 'To any who oppose the Empire, I extend this invitation.  Join us.  Help us. '),
('string/en/gcwlaunchevent.stf', 63, 'dialogue_1_3_8', 'To any who still hold allegiance to the Empire, I extend this word of caution:  Beware.  Your days are few.  No evil can survive where justice and peace take root.'),
('string/en/gcwlaunchevent.stf', 64, 'dialogue_1_3_9', 'I have been authorized to call for open attacks on all Imperial loyalists and Dark Jedi.  '),
('string/en/gcwlaunchevent.stf', 65, 'dialogue_1_3_10', 'In our pursuit of peace, we must sometimes embrace conflict.'),
('string/en/gcwlaunchevent.stf', 66, 'dialogue_1_3_11', 'Friends of the Alliance, I wish you good luck, and may the Force be with you.'),
('string/en/gcwlaunchevent.stf', 67, 'areabroadcast_0', '<<Incoming Imperial Transmission: Command station, this is ST321, code clearance blue. We''re starting our approach.>> '),
('string/en/gcwlaunchevent.stf', 68, 'areabroadcast_1', '<<Incoming Alliance Transmission: Ground control, this is shuttle Alder Six-Two. We have the Princess on board and are coming in for a landing.>>'),
('string/en/gcwlaunchevent.stf', 69, 'closingbroadcast_0', '<<Imperial Transmission: Shuttle ST321, your departure vector is right six-nine-three. Command station out.>>'),
('string/en/gcwlaunchevent.stf', 70, 'closingbroadcast_1', '<<Alliance Transmission: Control, Alder Six-Two. We are gear up and on our way to our next rally. May the Force be with you..>>'),
('string/en/generic_city_convo.stf', 1, 'greeting_1', 'Good day.  And what can I help you with?'),
('string/en/generic_city_convo.stf', 2, 'player_1', 'I''d like to ask you about the cities on Tatooine.'),
('string/en/generic_city_convo.stf', 3, 'player_2', 'Is there anything that you need done?'),
('string/en/generic_city_convo.stf', 4, 'player_3', 'What can you tell me about certain people?'),
('string/en/generic_city_convo.stf', 5, 'player_13', 'Can you give me directions?'),
('string/en/generic_city_convo.stf', 6, 'cities_1', 'Which city are you interested in?'),
('string/en/generic_city_convo.stf', 7, 'player_4', 'I''m curious about Mos Eisley...'),
('string/en/generic_city_convo.stf', 8, 'player_5', 'Do you know about Mos Espa?'),
('string/en/generic_city_convo.stf', 9, 'player_6', 'Anchorhead is the city I want to ask about.'),
('string/en/generic_city_convo.stf', 10, 'player_7', 'What do you know about Bestine?'),
('string/en/generic_city_convo.stf', 11, 'player_12', 'Can I ask some more questions?'),
('string/en/generic_city_convo.stf', 12, 'people_1', 'Who do you want to know about?'),
('string/en/generic_city_convo.stf', 13, 'player_8', 'Do you know Jabba the Hutt?'),
('string/en/generic_city_convo.stf', 14, 'player_9', 'Who is prefect Talmont?'),
('string/en/generic_city_convo.stf', 15, 'player_10', 'Have you heard of Dera Darklighter?'),
('string/en/generic_city_convo.stf', 16, 'player_11', 'What do you know about the tusken raiders?'),
('string/en/generic_city_convo.stf', 17, 'mission_1', 'As soon as I know how to hand out missions I''ll give you one.'),
('string/en/generic_city_convo.stf', 18, 'mos_eisley_1', 'Ah, Mos Eisley is a wretched hive of scum and villainy.  Nice cantinas though.'),
('string/en/generic_city_convo.stf', 19, 'mos_espa_1', 'They used to hold the pod races there, until they were outlawed.'),
('string/en/generic_city_convo.stf', 20, 'anchorhead_1', 'There''s not much to say really.  Tosche station is there, but not much else.'),
('string/en/generic_city_convo.stf', 21, 'bestine_1', 'The imperial capital of Tatooine.  It''s a nice city, of course, but strict with it''s laws.'),
('string/en/generic_city_convo.stf', 22, 'jabba_1', 'Jabba might as well own Tatooine.  He''s a dangerous criminal, and not to be trusted.'),
('string/en/generic_city_convo.stf', 23, 'talmont_1', 'Ah, the prefect.  He''s nominally in charge of things here on Tatooine, at least from an Imperial end.  But I hear he''s quite incompetent.'),
('string/en/generic_city_convo.stf', 24, 'dera_1', 'The lovely daughter, and heir to the Darklighter fortune.  Some say she has sympathy for the rebellion.'),
('string/en/generic_city_convo.stf', 25, 'tuskens_1', 'Not much to say really.  Savage creatures.  Monsters.  Like evil bears.  Watch out for them.'),
('string/en/generic_city_convo.stf', 26, 'sure_1', 'Sure.  What else would you like to ask about?'),
('string/en/generic_city_convo.stf', 27, 'where_1', 'Where would you like directions to?'),
('string/en/generic_city_convo.stf', 28, 'player_14', 'Can you tell me how to get to any of the cities?'),
('string/en/generic_city_convo.stf', 29, 'player_15', 'I need to get to a specific place.'),
('string/en/generic_city_convo.stf', 30, 'player_16', 'I need to see someone...'),
('string/en/generic_city_convo.stf', 31, 'find_city_1', 'Which city do you need help finding?'),
('string/en/generic_city_convo.stf', 32, 'directions_eisley', 'How do I get to Mos Eisley?'),
('string/en/generic_city_convo.stf', 33, 'directions_espa', 'Which way is Mos Espa?'),
('string/en/generic_city_convo.stf', 34, 'directions_bestine', 'Where exactly is Bestine?'),
('string/en/generic_city_convo.stf', 35, 'directions_anchorhead', 'Can you give me directions to Anchorhead?'),
('string/en/generic_city_convo.stf', 36, 'find_bldg_1', 'Where is it you''re trying to get to?'),
('string/en/generic_city_convo.stf', 37, 'bank', 'I need to get to the bank.'),
('string/en/generic_city_convo.stf', 38, 'cantina', 'I''m looking for the Cantina'),
('string/en/generic_city_convo.stf', 39, 'cloning_facility', 'I''m trying to find an insurance agent, if you know what I mean.'),
('string/en/generic_city_convo.stf', 40, 'hospital', 'I need to get to the hospital.'),
('string/en/generic_city_convo.stf', 41, 'starport', 'I''m trying to find a starport.'),
('string/en/generic_city_convo.stf', 42, 'find_person_1', 'Who do you need to see?'),
('string/en/generic_city_convo.stf', 43, 'find_jabba', 'I need to meet with Jabba the Hutt.'),
('string/en/generic_city_convo.stf', 44, 'find_talmont', 'I want to meet with prefect Talmont.'),
('string/en/generic_city_convo.stf', 45, 'find_dera', 'I''d like to meet Ms. Dera Darklighter.'),
('string/en/generic_city_convo.stf', 46, 'find_trainer', 'I''m looking for someone who can train me.'),
('string/en/generic_city_convo.stf', 47, 'add_to_radar', 'Let me add those directions to your datapad.'),
('string/en/generic_city_convo.stf', 48, 'bank_city', 'I see, and which bank were you interested in?'),
('string/en/generic_city_convo.stf', 49, 'bank_eisley', 'The bank in Mos Eisley.'),
('string/en/generic_city_convo.stf', 50, 'bank_espa', 'Is there a bank in Mos Espa?'),
('string/en/generic_city_convo.stf', 51, 'bank_bestine', 'The imperial bank in Bestine.'),
('string/en/generic_city_convo.stf', 52, 'bank_anchorhead', 'The one in anchorhead, thank you.'),
('string/en/generic_city_convo.stf', 53, 'cantina_city', 'Which cantina were you trying to find?'),
('string/en/generic_city_convo.stf', 54, 'cantina_eisley', 'Thought I''d try my luck at the Lucky Despot in Mos Eisley.'),
('string/en/generic_city_convo.stf', 55, 'cantina_espa', 'Just the one in Mos Espa.'),
('string/en/generic_city_convo.stf', 56, 'cantina_bestine', 'The cantina in Bestine, please.'),
('string/en/generic_city_convo.stf', 57, 'cantina_anchorhead', 'The Anchorhead cantina.'),
('string/en/generic_city_convo.stf', 58, 'hospital_eisley', 'The Hospital in Mos Eisley.'),
('string/en/generic_city_convo.stf', 59, 'hospital_espa', 'The Mos Espa hospital.'),
('string/en/generic_city_convo.stf', 60, 'hospital_bestine', 'I need the hospital in Bestine.'),
('string/en/generic_city_convo.stf', 61, 'hospital_anchorhead', 'I''m looking for the Anchorhead hospital.'),
('string/en/generic_city_convo.stf', 62, 'starport_eisley', 'The Mos Eisley Starport'),
('string/en/generic_city_convo.stf', 63, 'starport_espa', 'The Mos Espa Starport'),
('string/en/generic_city_convo.stf', 64, 'starport_bestine', 'The Bestine Starport.'),
('string/en/generic_city_convo.stf', 65, 'starport_anchorhead', 'The Anchorhead Starport.'),
('string/en/generic_city_convo.stf', 66, 'cloning_facility_eisley', 'Is there an insurance agency in Mos Eisley?'),
('string/en/generic_city_convo.stf', 67, 'cloning_facility_espa', 'Mos Espa''s insurance agency.'),
('string/en/generic_city_convo.stf', 68, 'cloning_facility_bestine', 'The Insurance Agent in Bestine.'),
('string/en/generic_city_convo.stf', 69, 'cloning_facility_anchorhead', 'The Anchorhead Insurance Agency, please.'),
('string/en/generic_npc/locations.stf', 1, 'greet', 'Hello.  Can I help you find something?'),
('string/en/generic_npc/locations.stf', 2, 'yes', 'Yes, I''m lost...'),
('string/en/generic_npc/locations.stf', 3, 'no', 'I''m doing all right.'),
('string/en/generic_npc/locations.stf', 4, 'ok', 'What can I help you with?'),
('string/en/generic_npc/locations.stf', 5, 'bye', 'Ok, good bye.'),
('string/en/got_n.stf', 1, 'armor', 'Armor'),
('string/en/got_n.stf', 2, 'armor_arm', 'Arm Armor'),
('string/en/got_n.stf', 3, 'armor_body', 'Body Armor'),
('string/en/got_n.stf', 4, 'armor_foot', 'Foot Armor'),
('string/en/got_n.stf', 5, 'armor_hand', 'Hand Armor'),
