('string/en/guild.stf', 125, 'open_elections_email_subject', 'Guild Leader Elections Open!'),
('string/en/guild.stf', 126, 'open_elections_email_body', 'Your guild has started an election for a new guild leader! You may vote at the guild terminal in your PA Hall. If you are a full member of the guild, you may opt to run for the position of guild leader by registering at the guild terminal.\n\nA new guild leader will be elected in exactly two weeks. The guild member with the most votes at that time will become guild leader.'),
('string/en/guild.stf', 127, 'closed_elections_email_subject', 'Guild Leader Elections Closed!'),
('string/en/guild.stf', 128, 'closed_elections_email_body', 'Your guild''s election for a new guild leader has been closed by the current guild leader.'),
('string/en/guild.stf', 129, 'public_election_body', 'The leader elections for %TT have been held.  The incumbent guild leader has lost the election!  The new guild leader is %TO.  Please congratulate the new guild leader!\n\nThe voting system will now be disabled. The new leader can enable it if they wish to run new elections.\n'),
('string/en/guild.stf', 130, 'public_election_inc_body', 'The elections for %TT have been held.  The incumbent guild leader is victorious!  Please congratulate %TO on retaining their office.\n\nThe voting system will now be disabled. The new leader can enable it if they wish to run new elections.'),
('string/en/guild.stf', 131, 'public_election_inc_subject', 'Election Results!'),
('string/en/guild.stf', 132, 'public_election_subject', 'Election Results!'),
('string/en/guild.stf', 133, 'open_elections_absent_email_body', 'Your guild leader has not logged in for an extended period of time. In order to enable your guild to continue to operate efficiently, the guild leader voting system has been enabled. You may vote at the guild terminal in your PA Hall. If you are a full member of the guild, you may opt to run for the position of guild leader by registering at the guild terminal.\n\nA new guild leader will be elected in exactly two weeks. The guild member with the most votes at that time will become guild leader.'),
