('string/en/hireling/hireling_droid_worshipful.stf', 1, 'start_convo_1', 'It is an honor to speak to my master, a true paragon of wisdom. Do you wish to give me instruction?'),
('string/en/hireling/hireling_droid_worshipful.stf', 6, 'command_stay', 'Stay here.'),
('string/en/hireling/hireling_droid_worshipful.stf', 7, 'command_follow', 'Follow me.'),
