('string/en/hireling/hireling_droid_worshipful.stf', 21, 'command_transfer', 'Meet your new boss.'),
('string/en/hireling/hireling_droid_worshipful.stf', 22, 'confused', 'This pathetic droids fails to understand your august commands, sir!'),
('string/en/hireling/hireling_droid_worshipful.stf', 23, 'command_assume_formation_2', 'Get in column formation.'),
('string/en/hireling/hireling_droid_worshipful.stf', 24, 'command_group_1', 'Group with me.'),
('string/en/hireling/hireling_droid_worshipful.stf', 25, 'command_group_2', 'Leave my group.'),
('string/en/hireling/hireling_droid_worshipful.stf', 26, 'start_convo_4', 'Of course! With alacrity! I merely need to know what command you will give me so that I can obey instantly.'),
('string/en/hireling/hireling_droid_worshipful.stf', 27, 'end_convo', 'It is an honor to learn wisdom from your honorable self, sir!'),
('string/en/hireling/hireling_droid_worshipful.stf', 28, 'command_reply_1', 'I need to teach you a command.'),
('string/en/hireling/hireling_droid_worshipful.stf', 29, 'start_convo_2', 'I will gladly hear instruction on any subject from your lips, o master!'),
('string/en/hireling/hireling_droid_worshipful.stf', 30, 'move_commands', 'Movement commands.'),
('string/en/hireling/hireling_droid_worshipful.stf', 31, 'combat_commands', 'Combat commands.'),
