('string/en/hireling/hireling_droid_worshipful.stf', 44, 'pet_wounded_health', 'I regret to point out to my master that I am slightly damaged.'),
('string/en/hireling/hireling_droid_worshipful.stf', 45, 'pet_wounded_mind', 'I will understand if my master wishes to dispose of my worthless self after seeing the damage I have suffered.'),
