('string/en/jedi_spam.stf', 34, 'mind_damage', 'Mind damage'),
('string/en/jedi_spam.stf', 35, 'willpower_damage', 'Willpower damage'),
('string/en/jedi_spam.stf', 36, 'focus_damage', 'Focus damage'),
('string/en/jedi_spam.stf', 37, 'battle_fatigue', 'Battle Fatigue'),
