('string/en/jedi_spam.stf', 42, 'quickness_wounds', 'Quickness wounds'),
('string/en/jedi_spam.stf', 43, 'stamina_wounds', 'Stamina wounds'),
('string/en/jedi_spam.stf', 44, 'mind_wounds', 'Mind wounds'),
('string/en/jedi_spam.stf', 45, 'willpower_wounds', 'Willpower wounds'),
('string/en/jedi_spam.stf', 46, 'focus_wounds', 'Focus wounds'),
('string/en/jedi_spam.stf', 47, 'no_help_target', 'You are not permitted to help that target.'),
('string/en/jedi_spam.stf', 48, 'jedi_death', 'You currently have %DI tracked deaths.'),
('string/en/jedi_spam.stf', 49, 'jedi_death_decay', 'One of your Jedi deaths has decayed. You now have %DI tracked deaths.'),
('string/en/jedi_spam.stf', 50, 'saber_color_0', 'Red'),
('string/en/jedi_spam.stf', 51, 'saber_color_1', 'Dark Red'),
('string/en/jedi_spam.stf', 52, 'saber_color_2', 'Light Green'),
('string/en/jedi_spam.stf', 53, 'saber_color_3', 'Dark Green'),
('string/en/jedi_spam.stf', 54, 'saber_color_4', 'Blue'),
('string/en/jedi_spam.stf', 55, 'saber_color_5', 'Dark Blue'),
('string/en/jedi_spam.stf', 56, 'saber_color_6', 'Yellow'),
('string/en/jedi_spam.stf', 57, 'saber_color_7', 'Dark Yellow'),
('string/en/jedi_spam.stf', 58, 'saber_color_8', 'Light Purple'),
('string/en/jedi_spam.stf', 59, 'saber_color_9', 'Dark Purple'),
('string/en/jedi_spam.stf', 60, 'saber_color_10', 'Orange'),
('string/en/jedi_spam.stf', 61, 'saber_color_11', 'Brown'),
('string/en/jedi_spam.stf', 62, 'waypoint_created_to_trainer', 'A waypoint to your trainer has been placed in your datapad. '),
('string/en/jedi_spam.stf', 63, 'trainer_waypoint_name', 'Jedi Skill Trainer'),
('string/en/jedi_spam.stf', 64, 'force_sensitive', 'You begin to feel attuned with the power of the Force. Your Force Sensitive abilities will be unlocked after Publish 10.'),
('string/en/jedi_spam.stf', 65, 'no_force_power', 'You do not have sufficient Force power to perform that action.'),
('string/en/jedi_spam.stf', 66, 'no_equip_lightsaber', 'You are not able to equip this item.'),
('string/en/jedi_spam.stf', 67, 'not_your_lightsaber', 'You cannot use a lightsaber that was crafted by someone else.'),
('string/en/jedi_spam.stf', 68, 'holocron_light_information', 'A mysterious voice says, "In order to continue your path to enlightenment, you must learn %TO."'),
('string/en/jedi_spam.stf', 69, 'holocron_already_jedi', 'A mysterious voice says, "Continue along the path you have chosen".'),
('string/en/jedi_spam.stf', 70, 'holocron_dark_information', 'A deep voice says, "In order to continue your path towards absolute power, you must learn %TO."'),
('string/en/jedi_spam.stf', 71, 'permadead_notify', 'You are dead. You have used up all of your deaths and must begin your journey again.  When you clone you will lose all skills, credits and items.'),
('string/en/jedi_spam.stf', 72, 'jedi_recruiter_response', 'There''s something about you I don''t like. I''m not going to talk to you.'),
('string/en/jedi_spam.stf', 73, 'already_force_running', 'You are already force running.'),
('string/en/jedi_spam.stf', 74, 'calm_target', 'You successfully calm down your target.'),
('string/en/jedi_spam.stf', 75, 'fail_calm_target', 'You fail to calm your target.'),
('string/en/jedi_spam.stf', 76, 'mind_trick_success', 'You successfully use your Force power to trick your target.'),
('string/en/jedi_spam.stf', 77, 'mind_trick_fail', 'You fail to trick your target.'),
('string/en/jedi_spam.stf', 78, 'animal_scare_success', 'You successfully scare your target.'),
('string/en/jedi_spam.stf', 79, 'animal_scare_fail', 'You fail to scare your target.'),
('string/en/jedi_spam.stf', 80, 'animal_attack_success', 'You successfully enrage your target.'),
('string/en/jedi_spam.stf', 81, 'animal_attack_fail', 'You fail to enrage your target.'),
('string/en/jedi_spam.stf', 82, 'staunch_bleeding_other', '%TT looks like their bleeding has decreaed.'),
('string/en/jedi_spam.stf', 83, 'stop_bleeding_other', '%TT is no longer bleeding. '),
('string/en/jedi_spam.stf', 84, 'stop_disease_other', '%TT is no longer diseased.'),
('string/en/jedi_spam.stf', 85, 'staunch_disease_other', '%TT looks less diseased.'),
('string/en/jedi_spam.stf', 86, 'staunch_poison_other', '%TT looks less poisoned.'),
