('string/en/kb/kb_begin_d.stf', 96, 'link_findskilltrainer', 'City Tour: My Skill Trainer'),
('string/en/kb/kb_begin_d.stf', 97, 'link_finishtour', 'Let''s Complete the City Tour'),
