('string/en/kb/kb_begin_d.stf', 109, 'link_artisandisciplines', 'Tell Me about The Artisan Disciplines'),
('string/en/kb/kb_begin_d.stf', 110, 'link_artisanfromhere', 'Tell Me Where I Can Go From Here'),
('string/en/kb/kb_begin_d.stf', 111, 'link_entertainerinstruments', 'Tell Me About Instruments and Dances'),
('string/en/kb/kb_begin_d.stf', 112, 'link_entertainerwounds', 'Tell Me About Wounds and Battle Fatigue'),
('string/en/kb/kb_begin_d.stf', 113, 'link_entertainercantinas', 'Tell Me About Cantinas and Camps'),
('string/en/kb/kb_begin_d.stf', 114, 'link_entertainerexperience', 'Tell Me How to Earn Experience'),
('string/en/kb/kb_begin_d.stf', 115, 'link_entertainerdisciplines', 'Tell Me About The Entertainer Disciplines'),
('string/en/kb/kb_begin_d.stf', 116, 'link_entertainerfromhere', 'Tell Me Where I Can Go From Here'),
('string/en/kb/kb_begin_d.stf', 117, 'link_medicdamage', 'Tell Me About Damage and Wounds'),
('string/en/kb/kb_begin_d.stf', 118, 'link_medicstimpacks', 'Tell Me About Stimpacks and Medpacks'),
('string/en/kb/kb_begin_d.stf', 119, 'link_medicdraftschematics', 'Tell Me About Medical Draft Schematics'),
('string/en/kb/kb_begin_d.stf', 120, 'link_medicforaging', 'Tell Me About Foraging and Crafting Stimpacks'),
('string/en/kb/kb_begin_d.stf', 121, 'link_medichospitals', 'Tell Me About Medical Centers and Camps'),
('string/en/kb/kb_begin_d.stf', 122, 'link_medicexperience', 'Tell Me How to Earn Experience'),
('string/en/kb/kb_begin_d.stf', 123, 'link_medicdisciplines', 'Tell Me About the Medical Disciplines'),
('string/en/kb/kb_begin_d.stf', 124, 'link_medicfromhere', 'Tell Me Where I Can Go From Here'),
('string/en/kb/kb_begin_d.stf', 125, 'link_brawlerweapons', 'Tell Me About Melee Weapons'),
('string/en/kb/kb_begin_d.stf', 126, 'link_brawlerarmor', 'Tell Me About Brawlers and Armor'),
('string/en/kb/kb_begin_d.stf', 127, 'link_brawlertactics', 'Tell Me About Melee Tactics'),
('string/en/kb/kb_begin_d.stf', 128, 'link_brawlerexperience', 'Tell Me How to Earn Experience'),
('string/en/kb/kb_begin_d.stf', 129, 'link_brawlerdisciplines', 'Tell Me About The Brawler Disciplines'),
('string/en/kb/kb_begin_d.stf', 130, 'link_brawlerfromhere', 'Tell Me Where I Can Go From Here'),
('string/en/kb/kb_begin_d.stf', 131, 'link_marksmanweapons', 'Tell Me About Ranged Weapons'),
('string/en/kb/kb_begin_d.stf', 132, 'link_marksmanarmor', 'Tell Me About Marksmen and Armor'),
('string/en/kb/kb_begin_d.stf', 133, 'link_marksmantactics', 'Tell Me About Ranged Tactics'),
('string/en/kb/kb_begin_d.stf', 134, 'link_marksmanexperience', 'Tell Me How to Earn Experience'),
('string/en/kb/kb_begin_d.stf', 135, 'link_marksmandisciplines', 'Tell Me About The Marksman Disciplines'),
('string/en/kb/kb_begin_d.stf', 136, 'link_marksmanfromhere', 'Tell Me Where I Can Go From Here'),
('string/en/kb/kb_begin_d.stf', 137, 'link_scoutcamps', 'Tell Me What''s a Camp'),
('string/en/kb/kb_begin_d.stf', 138, 'link_scouttraps', 'Tell Me How to Use Traps'),
('string/en/kb/kb_begin_d.stf', 139, 'link_scoutharvesting', 'Tell Me About Harvesting Creatures and Foraging'),
('string/en/kb/kb_begin_d.stf', 140, 'link_scoutdraftschematics', 'Tell Me About Draft Schematics'),
('string/en/kb/kb_begin_d.stf', 141, 'link_scoutcrafting', 'Tell Me About Crafting Camps and Traps'),
('string/en/kb/kb_begin_d.stf', 142, 'link_scoutexperience', 'Tell Me How to Earn Experience'),
('string/en/kb/kb_begin_d.stf', 143, 'link_scoutdisciplines', 'Tell Me About The Scout Disciplines'),
('string/en/kb/kb_begin_d.stf', 144, 'link_scoutromhere', 'Tell Me Where I Can Go From Here'),
('string/en/kb/kb_begin_d.stf', 145, 'link_thingstodo', 'Tell Me About Things To Do'),
('string/en/kb/kb_begin_d.stf', 146, 'link_missionterminals', 'Tell Me About Taking A Mission'),
('string/en/kb/kb_begin_d.stf', 147, 'link_npcmissions', 'Tell Me About Talking to an NPC'),
('string/en/kb/kb_begin_d.stf', 148, 'link_themeparks', 'Tell Me About Setting Off On a Quest'),
('string/en/kb/kb_begin_d.stf', 149, 'link_strongholds', 'Tell Me About Taking On a Stronghold'),
('string/en/kb/kb_begin_d.stf', 150, 'link_playerjobs', 'Tell Me About Finding a Job'),
('string/en/kb/kb_begin_d.stf', 151, 'link_chatchannels', 'Tell Me About Chatting With Players'),
('string/en/kb/kb_begin_d.stf', 152, 'link_findingpeople', 'Tell Me How to Find People'),
('string/en/kb/kb_begin_d.stf', 153, 'link_searching', 'Tell Me About Using Search'),
('string/en/kb/kb_begin_d.stf', 154, 'link_globalchat', 'Tell Me About Using the Chat Channels'),
('string/en/kb/kb_begin_d.stf', 155, 'link_friendslist', 'Tell Me About Using the Friends List'),
('string/en/kb/kb_begin_d.stf', 156, 'link_matchmaker', 'Tell Me About Setting Up My Matchmaker'),
('string/en/kb/kb_begin_d.stf', 157, 'link_finishhandoff', 'Let''s Wrap Up This Tutorial'),
('string/en/kb/kb_begin_d.stf', 158, 'findbankintro', 'The Bank is important for several obvious reasons.  Money and items deposited in the bank are safe.  Regardless of what unfortunate events may happen while adventuring, your stuff in the bank will be safe.  Keeping money in the bank is also very convenient; most transactions throughout the galaxy can automatically deduct funds from you bank eliminating the need to carry around lots of credits.\n\nRemember that you must join the bank before you are able to deposit and withdraw from it. You automatically joined the bank in your starting city so you shouldn''t have to worry about it now, but if at some future date you decide to relocate to a different city, you''ll need to remember to join the bank there. You can only access your Safety Deposit Box from the bank you joined. For instance, if you join the bank on Tatooine, you cannot access your items from Naboo.\n'),
('string/en/kb/kb_begin_d.stf', 159, 'findbankskip', 'If you don''t need any assistance finding the bank, press the button below and we''ll continue on to the next leg of the tour.\n'),
('string/en/kb/kb_begin_d.stf', 160, 'arrivedbank', 'Congratulations, you have found the bank.  You probably don''t need to do any banking right now, but if you do go on ahead and do it.  When you are ready, press the button below to continue the tour.\n'),
('string/en/kb/kb_begin_d.stf', 161, 'link_bankdetails', 'Tell Me More About the Bank'),
('string/en/kb/kb_begin_d.stf', 162, 'link_banktour', 'Take Me to the Bank'),
('string/en/kb/kb_begin_d.stf', 163, 'findcloningintro', 'The Cloning Facility is where you may end up if you are not quite so fortunate during your adventuring.  Any time you are killed out in the field your clone will be activated at the Cloning Facility.  Don''t forget to transfer your clone information to the local Cloning Facility whenever you travel to a new city.  If you forget to, you may be in for a long walk back.\n\nInsurance Terminals are also located at the Cloning Facility.  Through these terminals, you can insure all of your carried items.  Whenever your clone is activated, all insured items will be instantly returned to you.  Any uninsured items, however, will be left on your corpse.  In that event, you will need to travel out to your corpse to pick up those items.\n'),
('string/en/kb/kb_begin_d.stf', 164, 'findcloningskip', 'If you don''t need any assistance finding the Cloning Facility, press the button below and we''ll continue on to the next leg of the tour.\n'),
('string/en/kb/kb_begin_d.stf', 165, 'arrivedcloning', 'Congratulations, you have found the Cloning Facility.  Your cloning information has already been stored at this facility.  When you are ready, press the button below to continue the tour.\n'),
('string/en/kb/kb_begin_d.stf', 166, 'link_cloningdetails', 'Tell Me More About Cloning Facilities'),
('string/en/kb/kb_begin_d.stf', 167, 'link_cloningtour', 'Take Me to the Cloning Facility'),
('string/en/kb/kb_begin_d.stf', 168, 'findhospitalintro', 'Hospitals and Medical Centers are important places to know about if you are inclined to violence.  Anyone who engages in combat is going to need the assistance of a Medic eventually and Hospitals are a good place to find one.  Inside the Hospital, you''ll be able find Medics and Doctors who will be able to heal your wounds.\n\nIf you are interested in pursuing a career in a medical field then remember that patients in need of care can generally be found at the Hospital.  You don''t have to remain at the hospital, however.  Medical attention can be given at a properly prepared encampment as well.\n\nSome very large cities might have more than one Hospital or Medical Center while the smaller outposts may have none.  Make sure you are familiar with the local amenities before getting into too much trouble.'),
('string/en/kb/kb_begin_d.stf', 169, 'findhospitalskip', 'If you don''t need any assistance finding the Hospital, press the button below and we''ll continue on to the next leg of the tour.\n');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/kb/kb_begin_d.stf', 170, 'arrivedhospital', 'Congratulations, you have found the Hospital.  It''s unlikely that you need any medical attention right now, however, you may want to look around as these faces may become very familiar to you in the future.  When you are ready, press the button below to continue the tour.\n'),
('string/en/kb/kb_begin_d.stf', 171, 'link_hospitaldetails', 'Tell Me More About the Hospital'),
('string/en/kb/kb_begin_d.stf', 172, 'link_hospitaltour', 'Take Me to the Hospital'),
('string/en/kb/kb_begin_d.stf', 173, 'findcantinaintro', 'The Cantina is a great place to sit back and relax.  Many people come here to unwind and talk about their adventures while listening to Musicians and watching Dancers.  Mind wounds and Battle Fatigue will quickly fade away while relaxing and enjoying the soothing ministrations of your local Entertainers.\n\nThe Cantina can also be a good place to find fellow adventurers before embarking on a dangerous outing.  In general, you''ll find that the Cantina is the social hub of the city.\n\nSome cities have Theaters or Hotels which provide the same conveniences as a Cantina.  Many of the bigger cities have more than one such structure and some of the smaller outposts have none, so be careful out there.'),
('string/en/kb/kb_begin_d.stf', 174, 'findcantinaskip', 'If you don''t need any assistance finding the Cantina, press the button below and we''ll continue on to the next leg of the tour.\n'),
('string/en/kb/kb_begin_d.stf', 175, 'arrivedcantina', 'Congratulations, you have found the Cantina.  You may find the urge to sit back and enjoy the surroundings.  When you are ready, press the button below to continue the tour.\n'),
('string/en/kb/kb_begin_d.stf', 176, 'link_cantinadetails', 'Tell Me More About the Cantina'),
('string/en/kb/kb_begin_d.stf', 177, 'link_cantinatour', 'Take Me to the Cantina'),
('string/en/kb/kb_begin_d.stf', 178, 'findskilltrainerintro', 'Skill trainers are very important for advancement in your chosen profession.  As you gain experience, you will need to go to the skill trainer to learn new skills and abilities.\n\nSkill training isn''t always cheap and, as you need to learn more advanced skills, you''ll find the training gets more and more expensive.  If you are on a tight budget, an alternative to learning from the Skill Trainers is to seek out a sufficiently skilled player and see if they are able and willing to train you.  The Skill Trainer prices are set by the Empire and will never fluctuate, however, players may be negotiated with for prices that fit better to your budget.\n'),
('string/en/kb/kb_begin_d.stf', 179, 'findskilltrainerskip', 'If you don''t need any assistance finding your Skill Trainer, press the button below and we''ll finish up the tour.\n'),
('string/en/kb/kb_begin_d.stf', 180, 'arrivedskilltrainer', 'Congratulations, you have found your skill trainer.  You probably aren''t able to learn new skills yet, but you may still want to talk to your trainer to learn about the skills he can teach you.  When you are ready, press the button below to finish the tour.\n'),
('string/en/kb/kb_begin_d.stf', 181, 'link_skilltrainerdetails', 'Tell Me More About Skill Trainers'),
('string/en/kb/kb_begin_d.stf', 182, 'link_skilltrainertour', 'Take Me to My Skill Trainer'),
('string/en/kb/kb_begin_d.stf', 183, 'finishtourintro', 'That concludes this little tour of the city.  As you''ve probably noticed by now, the city is very big and there''s lots of other sights to see.  You were only shown the more important buildings that will be needed while playing Star Wars Galaxies.\n'),
('string/en/kb/kb_begin_d.stf', 184, 'finishtourfind', 'There are several tools available to you to help find your way around the city, the most powerful of which is the /find command.  At any time you can type /find from the command console for assistance in finding nearby important structures.  Typing /find by itself will cause a window to open with a list of the available things you can search for.  You may also specify the thing to search for directly with the /find command.  For example "/find bank" will locate the nearest bank, creating a waypoint to it for easier navigation.  You can read more about the /find command in the Holocron later if you desire.\n'),
('string/en/kb/kb_begin_d.stf', 185, 'finishtourplanetmap', 'Another important navigation tool is the Planetary Map.  This map shows all of the explorable area on the planet.  You can show city locations, waypoints and other important information on the Planetary Map.  At any time, you can bring up the Planetary Map by pressing Ctrl+V.\n'),
('string/en/kb/kb_begin_d.stf', 186, 'finishtourprofessions', 'Now that you have a good idea of how to navigate around the city, it''s time to learn a bit about playing your chosen profession.  When you are ready, press the button below to learn about all the critical aspects of your profession.\n'),
('string/en/kb/kb_begin_d.stf', 187, 'link_finddetails', 'Tell Me More About /find'),
('string/en/kb/kb_begin_d.stf', 188, 'link_planetmapdetails', 'Tell Me More About the Planetary Map'),
('string/en/kb/kb_begin_d.stf', 189, 'artisanresourcesskip', 'If you would rather move on to learning more about crafting, click the button below.\n'),
('string/en/kb/kb_begin_d.stf', 190, 'artisansurveymission', 'Survey Missions are a good way to make a little extra cash.  They are easy to do, but that doesn''t mean that they are risk free.\n\nCertain NPCs will hire you to locate a specific resource pocket for them.  A certain resource density will be required to meet the needs of the NPC.  All you will need to do is locate the resource deposit by using the Survey function of your survey tool.  You won''t actually need to collect the resources; they''ll be able to do that once they know where to find it.  \n\nLocate the requested resource type on your Survey Tool window and begin surveying.  Keep going towards the highest concentration of the resource and continue surveying.  You''ll automatically send the coordinates via your Datapad as soon as your survey tool has detected a pocket of sufficient density.  The contracted amount of credits will be deposited in your bank account upon completion.\n\nThat''s all there is to Survey Missions.  Not too hard, but it can get quite risky wandering the wilderness looking for the proper density of resources. \n'),
('string/en/kb/kb_begin_d.stf', 191, 'artisansurveymissionskip', 'If you would rather move on to learning more about crafting, click the button below.\n'),
('string/en/kb/kb_begin_d.stf', 192, 'link_artisansurveymission', 'Teach Me About Survey Missions'),
('string/en/kb/kb_begin_d.stf', 193, 'link_samplesurveymission', 'Give Me a Sample Survey Mission'),
('string/en/kb/kb_begin_d.stf', 194, 'artisansurveycomplete', 'Congratulations, you completed the Survey Mission.\n\nClick on the button below when you are ready to continue learning about playing an Artisan.\n'),
('string/en/kb/kb_begin_d.stf', 195, 'artisancraftingfinish', 'Click on the button below when you are ready to continue learning about the Artisan profession.\n'),
('string/en/kb/kb_begin_d.stf', 196, 'link_artisancraftingdetails', 'Teach Me About Advanced Crafting'),
('string/en/kb/kb_begin_d.stf', 198, 'marksmantacticsskip', 'If you would rather skip the Destroy Mission and continue learning about the Marksman profession, press the button below.\n'),
('string/en/kb/kb_begin_d.stf', 199, 'marksmandestroymission', 'Destroy Missions are a good way to make a little extra cash.\n\nYou can be given Destroy Missions from NPC who require someone with a little muscle to help them out or from the mission terminals in the major cities.  Once you have accepted the Destroy Mission you will get a Waypoint to where the mission is to be completed.  At that location will be a target, either a creature lair or a facility.  You will need to destroy the target and anything that is guarding it.\n\nOnce you have destroyed the target the agreed upon payment will be automatically deposited in your bank account.\n\nIf you feel up to the task, a simple destroy mission can be started by pressing the button below.  You will only need to kill a single creature, which should be relatively easy to destroy at your skill level. But be on your guard on your way to the target, there are other things out there that aren''t so easy to kill which may not take kindly to your approach.  Once the target is destroyed, we''ll continue learning about the Marksman profession.\n'),
('string/en/kb/kb_begin_d.stf', 200, 'marksmandestroyskip', 'If you would rather not attempt the destroy mission and just continue learning about Marksmen, press the button below.\n'),
('string/en/kb/kb_begin_d.stf', 201, 'marksmandestroycomplete', 'Congratulations, you completed the Destroy Mission.  You have begun the first steps in becoming a master of ranged weaponry.\n\nClick on the button below when you are ready to continue learning about playing an Marksman.\n'),
('string/en/kb/kb_begin_d.stf', 202, 'link_marksmandestroymission', 'Teach Me About Destroy Missions'),
('string/en/kb/kb_begin_d.stf', 203, 'link_marksmansampledestroymission', 'Give Me a sample Destroy Mission'),
('string/en/kb/kb_begin_d.stf', 204, 'marksmanexperience', 'There are four kinds of Marksman experience one for each kind of ranged weapon class (Pistol, Carbine and Rifle) and one general purpose Combat Experience.\n\nAll Marksman experience is earned by winning battles.  After each battle, you will earn some Combat Experience and some specialized experience for each of the weapon types you used.  The more you use a specific class of weapon the more of that type of experience you will earn.\n\nEach of the four Marksman experience types are used to advance in each of the four Marksman skill trees.  Click the button below to learn more about the Marksman skill trees.\n'),
('string/en/kb/kb_begin_d.stf', 205, 'brawlerexperience', 'There are four kinds of Brawler experience one for each kind of weapon class (Unarmed, One-Handed, Two-Handed and Polearm) available.\n\nAll Brawler experience is earned by winning battles.  After each battle, you will earn some experience for each of the weapon types you used.  The more you use a specific class of weapon the more of that type of experience you will earn.\n\nEach of the four Brawler experience types are used to advance in each of the four Brawler skill trees.  Click the button below to learn more about the Brawler skill trees.\n'),
('string/en/kb/kb_begin_d.stf', 206, 'medicexperience', 'There are two types of Medical experience that a Medic can earn, Medical Experience and Medical Crafting Experience.\n\nMedical Experience is used for almost all aspects of the Medic Profession.  You gain this experience through the use of you healing skills.  Whenever healing a patient, you will receive an amount of experience relative to the severity of their wounds.\n\nMedical Crafting Experience is earned through the creation and use of medicines.  It is not required that you personally use the medicines you craft but they must be used by someone with medical skills before you will gain any Medical Crafting Experience.\n\nTo learn about the medical disciplines, press the following button.\n'),
('string/en/kb/kb_begin_d.stf', 207, 'entertainerexperience', 'Entertainers gain four types of experience; Hairstyling Experience, Music Experience, Dance Experience and Entertainment Healing Experience.  Each experience type is used in each of the four Entertainer disciplines.\n\nHairstyling Experience is gained through the use of the Hairstyling skill.\n\nMusic Experience is gained through the playing of musical instruments.  While sitting alone practicing with an instrument will gain you slight amounts of experience, true expertise is only gained when playing for an audience.\n\nDance Experience is gained by dancing.  Similar to Music Experience, the true rewards come when you are dancing for an audience.  Dancers and Musicians can join together in bands to improve their performances.  Performing with other people is both rewarding and highly educational.\n\nEntertainment Healing Experience is gained when soothing away someone''s Battle Fatigue or Mind wounds.  This experience type can be earned using either the Dance or Musicianship skills, but only when you are healing someone.\n\nPress the button below to learn about how these experience types are used with the Entertainer Disciplines.\n'),
('string/en/kb/kb_begin_d.stf', 208, 'scoutexperience', 'There are three types of experience Scouts can earn; Scouting Experience, Trapping Experience and Wilderness Survival Experience.\n\nHunting wild creatures and harvesting the natural resources from their corpses earns Scouting Experience.\n\nTrapping Experience is earned through the crafting and use of Traps.\n\nFinally, Wilderness Survival Experience is earned by crafting and using camps or by foraging.\n\nPress the button below to learn about the Scout disciplines.\n'),
('string/en/kb/kb_begin_d.stf', 209, 'scouttraps', 'An extremely useful tool for fighting the local wildlife is a trap.\n\nThere are many different types of hand-crafted traps available to the skilled scout.  Initially, you will only have the ability to craft one type of trap, but as you become a more skilled trapper, you will learn other types.  These traps have differing effects from poisons to make a creature slow and drowsy to nets to temporarily immobilize your target.\n\nTo use a trap equip it like any other weapon.  Then, at the most opportune moment, throw it at your designated target.  Depending on your skill, you will be able to hit the target causing the trap to go off for the desired effect.\n\nPress the following button to learn about the resources needed to create these traps.\n'),
('string/en/kb/kb_begin_d.stf', 210, 'scoutcrafting', 'Once you have the necessary resources you can begin crafting a Camp or Trap.\n\nUse the crafting tool and select the item you wish to craft from the list. You will be taken to the assembly screen and there will be a box, and in it, the resources that you have that can be used for this schematic. Double click or drag resources into the appropriate boxes. You must use the same resource to fill a slot if it requires more than one resource. This means you cannot take two different types of bone and put them in the same slot. It would need to be a stack of the same resource in order to be used in a single slot. When all slots are full that are required for the item click assemble. It is possible to fail during the assembly. Once you have succeeded you will get a screen telling you how the item turned out. Continue on to the next screen in the crafting interface and name your item. After doing this and continuing again, your crafting tool will generate the prototype. You will see the numbers on your crafting tool count down and the item will be deposited in your inventory. Note: the pop up help can be very useful the first couple times you craft and will help guide you through this.\n\nMore advanced crafting is possible with specific crafting tools and crafting stations.  Crafting stations are very useful when crafting items and are very easy to use.  You only need to be standing near the correct type of crafting station and your special crafting tool will automatically connect to the station to take advantage of its advanced features. Using a Crafting Station will allow you to experiment with the final product and could increase its value and usability. \n\nWhen you are ready to learn about earning experience click on the button below.\n'),
('string/en/kb/kb_begin_d.stf', 211, 'playerjobs', 'Often times the best place to look for jobs is from other players.  The world is big and no one person will be able to do everything.  Perhaps you have the skills the person next to you is looking for.\n\nWhether it''s as simple as someone needing a Medic or Entertainer to heal them, or an Artisan requiring a bodyguard while they search for rare resources, it''s guaranteed that someone out there could use some help and you have the perfect skill set to assist them.\n\nTalk to people, don''t be afraid to ask around for jobs.  Perhaps you have a job in mind but need more people to help out, ask for assistance and you''re sure to find the help you need soon enough.  Find the local hangout and stay around there for a while.  If you are unsure of where to find people, try the Cantina - everyone ends up there eventually.  \n\nWhen you are ready to learn more about chatting with other players, press the following button.\n'),
('string/en/kb/kb_begin_d.stf', 212, 'friendslist', 'The Friends List is a great way to keep track of your online friends.\n\nWhen viewing your Friends list, you will be able to see at a glance which ones are currently online and which one are not.  Additionally, you can be notified whenever a friend comes online.  By setting the Listen option on, you will be notified whenever that person comes online.  This will only work if they have their Broadcast option selected for you, however.  It is possible someone wants a bit of privacy and doesn''t want people knowing instantly when they come online.  You have the same choice by turning off the Broadcast option for a friend you will set it so that they will not get a notification when you come online.\n\nA useful flip side to the Friends list is the Ignore list.  This is a list of player whom you would like to ignore.  It is useful for those situations where someone may be annoying you.  Add them to your Ignore list and all of their chat comments will be filtered out and you''ll never have to hear from them again.\n\nPress the button below to learn about the in game Matchmaker system.\n'),
('string/en/kb/kb_begin_d.stf', 213, 'finishhandoff', 'Well, this just about brings us to the end of our extended gameplay tutorial.\n\nThe last thing you''ll want to know is how to safely log out of the game.  When you are through playing Star Wars Galaxies, take your character to a safe place, somewhere within a city or camp site will work.  Then sit down using the /sit command and type "/logout" to quit.  After a short period, you will exit the game and your character will be safe and sound waiting for your return.  If you do not do this, your character will stay at the spot you left it for a couple minutes and could be attacked by passing creatures, so remember to always find a safe place before quiting.\n\nHopefully, you now have a better understanding of the basic game concepts and are not quite so overwhelmed.  There is a lot more to learn about Star Wars Galaxies, however.  At any time, you can look through this Holocron to find more detailed explanations of the various game system.\n\nRemember that the most powerful assistance feature of this game could be standing right next to you.  Ask your fellow players, chances are they had similar questions when they started playing and would be happy to help out a new player.  Don''t be afraid to ask or experiment and above all, have fun playing.\n\nMay the Force be with you.\n'),
('string/en/kb/kb_begin_d.stf', 214, 'entertainerinstrumentsskip', 'If you would rather skip the Gig Mission, press the following button and we''ll teach you a bit about some of the beneficial uses of Entertainment Healing.\n'),
('string/en/kb/kb_begin_d.stf', 215, 'entertainergigmission', 'Gig Missions are a good way to make a little extra cash while performing.\n\nCertain NPCs can hire you to do a performance for them.  They''ll have a specific place they wish you to perform at and an amount of time you need to perform for.  Don''t dally around if you choose to accept the mission though, they usually have a time restraint for when you need to complete the performance.  Once you''ve performed at the correct location for the contracted amount of time your payment will be automatically deposited in your bank account.\n\nAll-in-all, Gig Missions are quite simple.  The trickiest part can just be getting there, many times you''ll be asked to perform in a completely different city than you are currently in requiring a long cross-country trek or an expensive shuttle flight.  If you decide to take the role of the wandering minstrel and hoof it, keep in mind your deadline, you won''t make a single credit if you arrive late.\n\nIf you are ready to try your hand at a simple sample mission press one of the buttons below.  You won''t make any money doing these missions, but we guarantee you won''t have to go far.  Plus, you''ll get a chance to experiment with some of the techniques you''ve recently learned.  Once you''ve completed the mission, the Holocron will automatically open up and we''ll continue teaching you about your profession.\n'),
('string/en/kb/kb_begin_d.stf', 216, 'entertainergigskip', 'If you would rather move on to learning more about Entertainment Healing now, then click the button below.\n'),
('string/en/kb/kb_begin_d.stf', 217, 'entertainergigcomplete', 'Congratulations, you completed the Gig Mission.\n\nClick on the button below when you are ready to continue learning about playing an Entertainer.\n'),
('string/en/kb/kb_begin_d.stf', 218, 'link_entertainerdancegig', 'Give Me a Sample Dance Gig Mission'),
('string/en/kb/kb_begin_d.stf', 219, 'link_entertainermusicgig', 'Give Me a Sample Music Gig Mission'),
('string/en/kb/kb_begin_d.stf', 220, 'link_entertainergigmission', 'Teach Me About Gig Missions'),
('string/en/kb/kb_begin_d.stf', 221, 'brawlertacticsskip', 'If you are not interested in practicing you combat maneuvers, press the following button to learn about earning experience.\n'),
('string/en/kb/kb_begin_d.stf', 222, 'brawlerdestroymission', 'Destroy Missions are a good way to make a little extra cash.\n\nYou can be given Destroy Missions from NPC who require someone with a little muscle to help them out or from the mission terminals in the major cities.  Once you have accepted the Destroy Mission you will get a Waypoint to where the mission is to be completed.  At that location will be a target, either a creature lair or a facility.  You will need to destroy the target and anything that is guarding it.\n\nOnce you have destroyed the target the agreed upon payment will be automatically deposited in your bank account.\n\nIf you feel up to the task a simple destroy mission can be started by pressing the button below.  You will only need to kill a single creature, which should be relatively easy to destroy at your skill level, but be on your guard on your way to the target, there are other things out there that aren''t so easy to kill which may not take kindly to your approach.  Once the target is destroyed we''ll continue learning about the Brawler profession.\n'),
('string/en/kb/kb_begin_d.stf', 223, 'brawlerdestroyskip', 'If you would rather not attempt the destroy mission and just continue learning about your profession, press the button below.\n'),
('string/en/kb/kb_begin_d.stf', 224, 'brawlerdestroycomplete', 'Congratulations, you completed the Destroy Mission.  You have begun the first steps in becoming a master of melee combat.\n\nClick on the button below when you are ready to continue learning about playing a Brawler.\n'),
('string/en/kb/kb_begin_d.stf', 225, 'link_brawlerdestroymission', 'Teach Me About Destroy Missions'),
('string/en/kb/kb_begin_d.stf', 226, 'link_brawlersampledestroymission', 'Give Me a Sample Destroy Mission'),
('string/en/kb/kb_begin_d.stf', 228, 'professions', 'Choose a Starting Profession to learn more about it.\n'),
('string/en/kb/kb_begin_d.stf', 229, 'scoutharvestingskip', 'Or if you would rather proceed onto learning how to make the tools of your trade, then press the button below to begin learning about Draft Schematics.\n'),
('string/en/kb/kb_begin_d.stf', 230, 'scoutharvestmission', 'If you feel up to the task of harvesting resources you can press the button below to get started.  You will only need to kill a single creature, which should be relatively easy to destroy at your skill level, but be on your guard on your way to the target, there are other things out there that aren''t so easy to kill which may not take kindly to your approach.  Once the target has been killed you will need to extract the resources.  Then we will come back to the Holocron and continue teaching you about your profession.\n'),
('string/en/kb/kb_begin_d.stf', 231, 'scoutharvestcomplete', 'Congratulations, you have successfully harvested resources from a creature.  You have begun the first steps in becoming a master scout.\n\nClick on the button below when you are ready to start learning about Draft Schematics and how to craft the tools of your trade.\n'),
('string/en/kb/kb_begin_d.stf', 232, 'link_scoutharvestmission', 'Let Me Try Harvesting Resources'),
('string/en/kb/kb_begin_d.stf', 233, 'link_scoutsampleharvestmission', 'I''m Ready to Begin'),
('string/en/kb/kb_begin_d.stf', 234, 'scoutharvestmissionskip', 'If you would rather just start learning how to make the tools of your trade, then press the button below to begin learning about Draft Schematics.\n'),
('string/en/kb/kb_begin_d.stf', 235, 'medicstimpacksskip', 'Or you can proceed straight on to the next section to learn how you can craft your own medicines.  When you are ready, press the button below to learn more.\n'),
('string/en/kb/kb_begin_d.stf', 236, 'medichealmission', 'So you think you''re ready to have people lives in you hands?  Perhaps you should test your skills in a slightly less stressful situation first.\n\nIf you would like to get a feel for how to administer medicines then press the button below and we''ll give you an opportunity to use them in a simple exercise.  You will be given an inoculation that needs to be administered to a citizen within the city.  A waypoint will lead you to the location of the patient.  Once there you can administer the medicine by targeting your patient and selecting the Use option from the medicines Radial Menu, or you can use the Radial Menu on the patient to administer the medicine.\n'),
('string/en/kb/kb_begin_d.stf', 237, 'medichealmissionskip', 'If you would rather just start learning how to make the tools of your trade, then press the button below to begin learning about Medical Draft Schematics.\n'),
('string/en/kb/kb_begin_d.stf', 238, 'medichealcomplete', 'Congratulations, you have successfully harvested resources from a creature.  You have begun the first steps in becoming a master scout.\n\nClick on the button below when you are ready to start learning about Medical Draft Schematics and how to craft the tools of your trade.\n'),
('string/en/kb/kb_begin_d.stf', 239, 'link_medichealmission', 'Let Me Try Using My Healing Skills'),
('string/en/kb/kb_begin_d.stf', 240, 'link_medicsamplehealmission', 'I''m Ready To Begin'),
