('string/en/loot_nboo_d.stf', 1, 'borvo_q1_needed', 'An invitation from Naboo crimelord Borvo the Hutt to his rival, Kritus Morven, to sit down and work out their differences.\n'),
('string/en/loot_nboo_d.stf', 2, 'borvo_q6_needed', 'A strain of the Berserker Virus sent by Naboo crimelord Borvo the Hutt to a Black Sun representative from Corellia.\n'),
('string/en/loot_nboo_d.stf', 3, 'ebenn_baobab_q2_needed', 'Funds sent by Ebenn Q3 Baobab, celebrated writer, politician, and scholar in Moenia on Naboo, supposedly to set up a (belated) commission to prevent the fall of the Old Republic.\n'),
('string/en/loot_nboo_d.stf', 4, 'ebenn_baobab_q3_needed', 'Supposedly a collection of poetry submitted to Ebenn Q3 Baobab, celebrated writer, politician, and scholar in Moenia on Naboo\n'),
('string/en/loot_nboo_d.stf', 5, 'radanthus_mandelatara_q2_needed', 'A container holding pinfeathers freshly plucked from two fine peko-pekos\n'),
('string/en/loot_nboo_d.stf', 6, 'radanthus_mandelatara_q3_needed', 'Anelectrical device crafted just so by a particular craftsman \n'),
('string/en/loot_nboo_d.stf', 7, 'dilvin_lormurojo_q2_needed', 'The latest satire by Dilvin Lormurojo'),
('string/en/loot_nboo_d.stf', 8, 'bab_esrus_q1_needed', 'Pigmentation-production chromosomes of the common capper spineflap'),
('string/en/loot_nboo_d.stf', 9, 'bab_esrus_q3_needed', 'Kowakian monkey-lizard with multicolored blood'),
('string/en/loot_nboo_d.stf', 10, 'arrek_vonsarko_q1_needed', 'An invitation to a respected art critic, Huffee Vindaag'),
('string/en/loot_nboo_d.stf', 11, 'serena_fenner_q1_needed', 'A scathing review of the latest Imperial opera'),
('string/en/loot_nboo_d.stf', 12, 'serena_fenner_q3_needed', 'An equipment storage request to the Gungans about storing equipment for the Alliance away from prying Imperial eyes'),
('string/en/loot_nboo_d.stf', 13, 'kylantha_q1_needed', 'Makeup kit used by Queen Kylantha of Naboo.\n');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/loot_nboo_d.stf', 14, 'kylantha_q2_needed', 'Naboo Queen Kylantha''s polite refusal to join a sightseeing trip organized by Imperial Army General Liles Dorond\n'),
('string/en/loot_nboo_d.stf', 15, 'ian_lago_q1_needed', 'A Neuro-Saav Sensor Pack\n'),
('string/en/loot_nboo_d.stf', 16, 'ian_lago_q3_needed', 'An encrypted datadisc.\n'),
('string/en/loot_nboo_d.stf', 17, 'mal_sikander_q1_needed', 'A modified disruptor pistol\n'),
('string/en/loot_nboo_d.stf', 18, 'mal_sikander_q5_needed', 'An encrypted datadisc.\n'),
('string/en/loot_nboo_d.stf', 19, 'vrir_unglan_q1_needed', 'An encrypted datadisc.\n'),
('string/en/loot_nboo_d.stf', 20, 'vrir_unglan_q2_needed', 'An encrypted datadisc.\n'),
('string/en/loot_nboo_d.stf', 21, 'ayn_eckener_q3_needed', 'An order to the research camp leader to stop wearing their carrion-smelling perfume'),
('string/en/loot_nboo_d.stf', 22, 'kadil_nurugen_q1_needed', 'An encrypted datadisc.\n'),
('string/en/loot_nboo_d.stf', 23, 'sayama_edosun_q1_needed', 'A sample of discovered blue colored glie (moss)'),
('string/en/loot_nboo_d.stf', 24, 'sayama_edosun_q2_needed', 'An encrypted datadisc.\n'),
('string/en/loot_nboo_d.stf', 25, 'sayama_edosun_q3_needed', 'A corpse of a chuba'),
('string/en/loot_nboo_d.stf', 26, 'junelle_astor_q1_needed', 'Private correspondence of Naboo''s High Inquisitor Mal Sikander.\n'),
('string/en/loot_nboo_d.stf', 27, 'junelle_astor_q3_needed', 'A gift from Boss Nass for Queen Kylantha of Naboo.\n'),
('string/en/loot_nboo_d.stf', 28, 'liane_q1_needed', 'Queen Kylantha of Naboo has ordered this old musical instrument restored by crafter Bowrun Stradalla.\n'),
('string/en/loot_nboo_d.stf', 29, 'liane_q2_needed', 'This order from Queen Kylantha of Naboo commissions a new ceremonial dress from tailor Niamora Ingidge.\n'),
('string/en/loot_nboo_d.stf', 30, 'liane_q3_needed', 'This order from Queen Kylantha of Naboo commissions an ode from the poet Biude Lop Quanna celebrating her pet voorpak''s new litter.\n'),
('string/en/loot_nboo_d.stf', 31, 'ric_olie_q1_needed', 'Reports of recent pirate activity on Naboo, compiled by Jamel Luffa for retired pilot Captain Ric Olie in Theed.\n'),
('string/en/loot_nboo_d.stf', 32, 'oron_wintree_q1_needed', 'An encrypted datadisc.\n'),
('string/en/loot_nboo_d.stf', 33, 'graf_zapalo_q2_needed', 'Waterborne specimens collected for Naboo''s former Minister of Science, Graf Zapalo, to document the spread of the Berserker Virus.\n'),
('string/en/loot_nboo_d.stf', 34, 'graf_zapalo_q3_needed', 'A potentially controversial analysis of the Berserker Virus by Naboo''s former Minister of Science, Graf Zapalo.\n'),
('string/en/loot_nboo_d.stf', 35, 'dea_tore_q2_needed', 'A manufactured anti-venom using the ikopi horn'),
('string/en/loot_nboo_d.stf', 36, 'dea_tore_q3_needed', 'Blood samples of the failed success of the anti-venom'),
