('string/en/loot_tato_d.stf', 3, 'stella_q3_needed', 'Information secured by a Bothan spy for Stella, owner of the Third Sun cantina in Mos Taike on Tatooine.'),
('string/en/loot_tato_d.stf', 4, 'bren_kingal_q1_reward', 'Salt 1 small worrt; dust with mounder flour. Saute in blue milk until brown; place in casserole dish, pour pan drippings over worrt. Add 1 handful (humanoid hand) trimpian, 1 pinch tomo spice. Fill casserole with blue milk, cover, bake at medium heat until tender. Serves 1.'),
('string/en/loot_tato_d.stf', 5, 'bren_kingal_q2_reward', 'Cube 1 thick bantha steak; trim fat, pat dry. Saute meat in bantha butter until brown. Core, seed, and chop 2 large ootowergs, 3 ripe dropes, 1 small koba if available. Add vegetables to cooked meat, cook til heated through. Put all in pot of boiling water. Cover, simmer at low heat for 3 days. Add roosha to taste. Serves 1-2.'),
('string/en/loot_tato_d.stf', 6, 'bren_kingal_q3_reward', 'Mix 1 cup blue milk, 1 cup water, 1 pinch Tusken brew-yeast. Leave in warm place for a while. Mix 1 handful (humanoid hand) mounder flour, 3 pinches salt. Slowly add bantha butter until doughy; add brew-yeast mixture. Knead until stiff. Leave in warm place until doubled. Knead briefly, rip hand-size (humanoid hand) pieces of dough, pound flat. Fry over low heat until crisp. Eat immediately.'),
('string/en/loot_tato_d.stf', 7, 'melios_purl_q2_needed', 'A festering womp rat hide'),
('string/en/loot_tato_d.stf', 8, 'melios_purl_q3_needed', 'Cylinder of bacta juice'),
('string/en/loot_tato_d.stf', 9, 'lilas_dinhint_q1_needed', 'A threadbare and scurrier-chewed robe allegedly worn centuries ago by one of Tatooine''s Sand People.'),
('string/en/loot_tato_d.stf', 10, 'lilas_dinhint_q2_needed', 'A padded chest plate allegedly worn by Melnea Arnthout, leader of the miners who settled Tatooine from the Dowager Queen colony ship'),
('string/en/loot_tato_d.stf', 11, 'lilas_dinhint_q3_needed', 'A centuries-old surveyor''s scanner, now a museum piece.'),
('string/en/loot_tato_d.stf', 12, 'lilas_dinhint_q4_needed', 'A dried chunk of bantha meat that could be centuries old.'),
('string/en/loot_tato_d.stf', 13, 'binna_jode_q1_needed', 'A small metal drum, crudely decorated with colorful drawings.'),
('string/en/loot_tato_d.stf', 14, 'binna_jode_q2_needed', 'Bestine cantina owner Binna''s gift to a wounded veteran on Tatooine.'),
('string/en/loot_tato_d.stf', 15, 'binna_jode_q3_needed', 'Shirt given by Bestine cantina owner Binna to a young mother.'),
('string/en/loot_tato_d.stf', 16, 'binna_jode_q4_needed', 'May contain info about Bestine cantina owner Binna''s missing husband.'),
('string/en/loot_tato_d.stf', 17, 'binna_jode_q1_reward', 'Unexpectedly fresh, with flaky crust and a delightful spiced sauce.'),
('string/en/loot_tato_d.stf', 18, 'binna_jode_q2_reward', 'A small gourd of the Tatooine funnel flower, stuffed with ground bantha meat and lightly spiced. Delicate, delicious flavor.'),
('string/en/loot_tato_d.stf', 19, 'binna_jode_q3_reward', 'Corellian ale spiked with secret Tatooine liquors. Bites like a maddened dewback.'),
('string/en/loot_tato_d.stf', 20, 'binna_jode_q4_reward', 'Spiced meat pastries in pounded mounder dough. A Tatooine specialty, mainly because no other world would touch it. This tray, however, tastes pretty good.'),
