('string/en/lord_hethrir_1.stf', 1, 'lord1', 'Speak to my contact outside of Moenia and track down the insurgents.'),
('string/en/lord_hethrir_1.stf', 2, 'lord1_reply1', 'Will do.'),
('string/en/lord_hethrir_1.stf', 3, 'lord1_reply2', 'No time for that now.'),
('string/en/lord_hethrir_1.stf', 4, 'lord2', 'Hurry up.  The safety of the Imperial Citizens depends on your quick action.'),
('string/en/lord_hethrir_1.stf', 5, 'lord3', 'Finish whatever business is delaying you immediately, and then speak to me again.'),
('string/en/lord_hethrir_1.stf', 6, 'informant1', 'You must be who Lord Hethrir sent to talk to me.  Listen, I have discovered the whereabouts of a fringe group that has been selling explosives to radicals!'),
('string/en/lord_hethrir_1.stf', 7, 'informant1_reply1', 'Tell me.'),
('string/en/lord_hethrir_1.stf', 8, 'informant2', 'What are you trying to do, blow my cover?'),
('string/en/lord_hethrir_1.stf', 9, 'informant2_reply1', 'Of course not.  I''ll go now.'),
