('string/en/merchant_e3_convo.stf', 1, 'merchant_1', 'I guess you''ve noticed everyone''s packing up and leaving town?\n'),
('string/en/merchant_e3_convo.stf', 2, 'merchant_2', 'Yeah, I was going to ask about that....'),
('string/en/merchant_e3_convo.stf', 3, 'merchant_3', 'I was wondering what you do for a living.'),
('string/en/merchant_e3_convo.stf', 4, 'merchant_4', 'Imperial thugs have that affect on a city.  Unless you''re one of Jabba''s cronies it''s time to go.'),
('string/en/merchant_e3_convo.stf', 5, 'merchant_5', 'Well, by trade I guess I''m a merchant, though I occasionally deal in, hm...shall we say, hard to find items?'),
('string/en/merchant_e3_convo.stf', 6, 'merchant_6', 'What''s a hard to find item?'),
('string/en/merchant_e3_convo.stf', 7, 'merchant_7', 'An honest hutt?  HAHA!  No, I was just kidding.  Don''t tell Jabba I said that, ok?'),
('string/en/mission/mission_bounty_imperial_easy.stf', 1, 'm1d', 'An Imperial bounty is hereby issued on a former HoloNet producer who now spreads dangerous lies about our Emperor. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "This encounter is strictly off the record."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 2, 'm1o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 3, 'm1s', 'The Empire sends congratulations and this message: "We trust that you will respect confidentiality in this matter."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 4, 'm1t', 'Libelous Former HoloNet Producer'),
('string/en/mission/mission_bounty_imperial_easy.stf', 5, 'm1v', 'The Emperor is enslaving whole planets to produce advanced weapons! I have sources!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 6, 'm2d', 'An Imperial bounty is hereby issued on a surveillance droid repair specialist. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Only a fool relies on a droid for espionage."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 7, 'm2o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 8, 'm2s', 'The Empire sends congratulations and this message: "The compromised droids have now been dismantled."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 9, 'm2t', 'Surveillance Droid Repair Specialist'),
('string/en/mission/mission_bounty_imperial_easy.stf', 10, 'm2v', 'When I repaired the Empire''s droids, I didn''t reprogram them for espionage. I just installed cameras and sent the feeds to the Alliance. Get it straight!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 11, 'm3d', 'An Imperial bounty is hereby issued on a speeder repair specialist. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "It worked once, but how long did you think you could evade detection?"'),
('string/en/mission/mission_bounty_imperial_easy.stf', 12, 'm3o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 13, 'm3s', 'The Empire sends congratulations and this message: "The target sabotaged the controls of several officers'' speeders so that they would self-destruct above a certain speed. The sabotage is now corrected."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 14, 'm3t', 'Speeder Repair Specialist'),
('string/en/mission/mission_bounty_imperial_easy.stf', 15, 'm3v', 'Oh, I dunno -- a longer time than this. At least I got one officer to crash and burn. Long live the Alliance!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 16, 'm4d', 'An Imperial bounty is hereby issued on a Coruscant merchant banker who absconded with a fortune in credits. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "We trust you enjoyed your brief retirement."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 17, 'm4o', 'Bounty Hunters'' Guild');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_bounty_imperial_easy.stf', 18, 'm4s', 'The Empire sends congratulations and this message: "We cannot trace the banker''s embezzled funds. Evidently the money has gone to the Rebellion."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 19, 'm4t', 'Coruscant Merchant Bank Embezzler'),
('string/en/mission/mission_bounty_imperial_easy.stf', 20, 'm4v', 'I''m not retired -- I''m working harder, for a better cause, than ever before. Restore the Republic!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 21, 'm5d', 'An Imperial bounty is hereby issued on a dealer in textiles. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Contracting with Rebels is always bad business."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 22, 'm5o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 23, 'm5s', 'The Empire sends congratulations and this message: "Through the dealer''s records we have uncovered important Rebel supply chains. We shall have more bounties for you shortly."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 24, 'm5t', 'Textile Dealer'),
('string/en/mission/mission_bounty_imperial_easy.stf', 25, 'm5v', 'My company made the Alliance''s uniforms, and I''m proud!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 26, 'm6d', 'An Imperial bounty is hereby issued on a merchant seller of banners and flags. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Congratulations. Your work helps us spot Rebels with fine accuracy."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 27, 'm6o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 28, 'm6s', 'The Empire sends congratulations and this message: "Destroy one flag maker, and two more rise up to take its place. But we persevere."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 29, 'm6t', 'Merchant in Banners and Flags'),
('string/en/mission/mission_bounty_imperial_easy.stf', 30, 'm6v', 'You know those banners that identify Alliance camps? My company made those. Long live the Alliance!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 31, 'm7d', 'An Imperial bounty is hereby issued on a merchant ship dispatcher convicted of aiding piracy. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "The bribes you collected could not buy passage far enough to escape justice."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 32, 'm7o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 33, 'm7s', 'The Empire sends congratulations and this message: "The Rebellion''s corruption is festering even in the merchant shipping service. Purges are now underway."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 34, 'm7t', 'Merchant Ship Dispatcher Aiding Pirates'),
('string/en/mission/mission_bounty_imperial_easy.stf', 35, 'm7v', 'Justice, right. I sent the pirates after every Imperial ship I could, and funneled all their bribe money to the Alliance. That''s real justice!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 36, 'm8d', 'An Imperial bounty is hereby issued on the murderer of an Empire civil defense planner. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "To attack the lowliest Imperial official is to attack the Empire itself."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 37, 'm8o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 38, 'm8s', 'The Empire sends congratulations and this message: "Allegations of corruption in the Empire are tantamount to attacks on the Emperor himself."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 39, 'm8t', 'Murderer of Civil Defense Planner'),
('string/en/mission/mission_bounty_imperial_easy.stf', 40, 'm8v', 'Yeah, well, attacking the Empire was the idea. That sleazy instructor was taking bribes for preferential access to the city''s bacta tanks. The Empire is just like that guy!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 41, 'm9d', 'An Imperial bounty is hereby issued on a deep-space prospector fleeing Imperial justice. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "All would have gone more smoothly had you never found the artifacts."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 42, 'm9o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 43, 'm9s', 'The Empire sends congratulations and this message: "It is Imperial policy to discourage the discovery and sale of Sith artifacts."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 44, 'm9t', 'Fugitive Deep-Space Prospector'),
('string/en/mission/mission_bounty_imperial_easy.stf', 45, 'm9v', 'I was just trying to make credit! I didn''t think those things were actually Sith artifacts! Those are just legends!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 46, 'm10d', 'An Imperial bounty is hereby issued on a hoodlum who killed a stormtrooper with a standard blaster, then stole food supplies from an Imperial supply depot. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "The Empire sometimes marks its supplies with tracking beacons."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 47, 'm10o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 48, 'm10s', 'The Empire sends congratulations and this message: "Famine outbreaks in certain localities have led to an increase in theft attempts by starving locals. Expect further bounties of this type."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 49, 'm10t', 'Imperial Supply Depot Hoodlum'),
('string/en/mission/mission_bounty_imperial_easy.stf', 50, 'm10v', 'Tracking beacons. Drat!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 51, 'm11d', 'An Imperial bounty is hereby issued on a thief who killed a stormtrooper by ramming him with a landspeeder, then stole Mark IV fuel cells from an Imperial fuel dump. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Many Imperial fuel dumps are watched by aerial surveillance droids."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 52, 'm11o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 53, 'm11s', 'The Empire sends congratulations and this message: "Rebel activity has led to local disruption in civilian fuel supplies. Expect further bounties of this type."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 54, 'm11t', 'Imperial Fuel Dump Thief'),
('string/en/mission/mission_bounty_imperial_easy.stf', 55, 'm11v', 'I knew I didn''t knock out all those surveillance droids! Back at you, bounty hunter!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 56, 'm12d', 'An Imperial bounty is hereby issued on an assailant who killed a stormtrooper by using a homemade fragmentation grenade, then stole an Uulshos QH-7 Chariot light assault vehicle. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Some Imperial LAVs are equipped with remote surveillance cameras."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 57, 'm12o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 58, 'm12s', 'The Empire sends congratulations and this message: "Continued civil unrest means military vehicles will continue to command exorbitant prices on the black market. Expect further bounties of this type."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 59, 'm12t', 'Imperial Vehicle Depot Assailant'),
('string/en/mission/mission_bounty_imperial_easy.stf', 60, 'm12v', 'I could have sworn I deactivated the cameras. Oh well! Die, bounty hunter scum!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 61, 'm13d', 'An Imperial bounty is hereby issued on a Tatooine animal rustler who trampled a stormtrooper to death with a dewback, then stole an entire herd of trained dewback mounts. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Those mounts were implanted with subcutaneous pheromone scent generators to expedite tracking."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 62, 'm13o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 63, 'm13s', 'The Empire sends congratulations and this message: "While the Rebellion continues unchecked, desperate civilians will continue to rustle mounts for transport or even food. Expect further bounties of this type."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 64, 'm13t', 'Imperial Dewback Corral Rustler'),
('string/en/mission/mission_bounty_imperial_easy.stf', 65, 'm13v', 'I tried and tried to spot the implants in those dewbacks'' hides. I just couldn''t! Damn Imperials!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 66, 'm14d', 'An Imperial bounty is hereby issued on a lawbreaker who killed a stormtrooper by using a Corporate Sector Authority sonic pistol, then stole a case of BlastTech T-21 light repeating blasters. Because the weapons'' power packs were not taken, target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Imperial weapon crates are sometimes marked with distinctive infrared signatures visible from orbit."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 67, 'm14o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 68, 'm14s', 'The Empire sends congratulations and this message: "So long as the Rebellion operates in this sector, we must plan for further weapon thefts. Expect further bounties of this type."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 69, 'm14t', 'Imperial Armory Lawbreaker'),
('string/en/mission/mission_bounty_imperial_easy.stf', 70, 'm14v', 'Infrared signatures? Oh man, that is not fair.'),
('string/en/mission/mission_bounty_imperial_easy.stf', 71, 'm15d', 'An Imperial bounty is hereby issued on an offender who killed a stormtrooper with a sophisticated aerosol poison, then stole several vials of chemical reagents used in toxin production. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "That chemical laboratory has sensors that recognize intruders'' distinctive magnetic aura."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 72, 'm15o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 73, 'm15s', 'The Empire sends congratulations and this message: "The continued unrest in our society means there will be a steady criminal market for poison reagents. Expect further bounties of this type."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 74, 'm15t', 'Imperial Chemical Lab Offender'),
('string/en/mission/mission_bounty_imperial_easy.stf', 75, 'm15v', 'I wondered what that silly doorway thing did. Wait, how do you know I even have a magnetic aura? I could be the wrong person. Is it too late to claim an alibi?'),
('string/en/mission/mission_bounty_imperial_easy.stf', 76, 'm16d', 'An Imperial bounty is hereby issued on a cloud car thief who killed a stormtrooper by pushing him off a tall building, then stole a military-grade repulsorlift drive. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "That prototype drive was designed to emit distinctive traces of radiation."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 77, 'm16o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 78, 'm16s', 'The Empire sends congratulations and this message: "Imperial interdiction of Rebel supply lines means they will continue to enlist common thieves to procure repulsorlift drives. Expect further bounties of this type."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 79, 'm16t', 'Imperial Equipment Depot Cloud Car Thief'),
('string/en/mission/mission_bounty_imperial_easy.stf', 80, 'm16v', 'But I didn''t even turn on the drive!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 81, 'm17d', 'An Imperial bounty is hereby issued on a known Rebel informant, accused in several counts of espionage against Imperial military sites. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Three times you have been warned to avoid our installations. Consider this a desist order."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 82, 'm17o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 83, 'm17s', 'The Empire sends congratulations and this message: "Lack of respect for the New Order inevitably leads to poor decisions. Don''t you agree, bounty hunter?"'),
('string/en/mission/mission_bounty_imperial_easy.stf', 84, 'm17t', 'Rebel Informant'),
('string/en/mission/mission_bounty_imperial_easy.stf', 85, 'm17v', 'Stay back! I know how to defend myself!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 86, 'm18d', 'An Imperial bounty is hereby issued on a weapons smuggler who escaped custody after a treason conviction. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "We have executed your accomplices and trapped you on the planet. There will be no escape this time."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 87, 'm18o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 88, 'm18s', 'The Empire sends congratulations and this message: "When a smuggler runs weapons to known Rebel sympathizers, it is no longer simple tariff evasion. The Empire must show no mercy."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 89, 'm18t', 'Weapons Smuggler'),
('string/en/mission/mission_bounty_imperial_easy.stf', 90, 'm18v', 'You won''t get me on a dungeon ship! I''ll die first!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 91, 'm19d', 'An Imperial bounty is hereby issued on a sniper, known for engaging in laser fire against unsuspecting Imperial personnel. Rebel sympathies are strongly in evidence. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Too many good operatives have fallen to your laser blasts. But you won''t take this bounty hunter by surprise."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 92, 'm19o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 93, 'm19s', 'The Empire sends congratulations and this message: "The families of that Rebel''s victims will rest easier knowing that the Empire has delivered a just punishment. Good work, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 94, 'm19t', 'Rebel Blaster Fighter'),
('string/en/mission/mission_bounty_imperial_easy.stf', 95, 'm19v', 'Servants of the Empire deserve to die -- including you, bounty hunter!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 96, 'm20d', 'An Imperial bounty is hereby issued on a military contractor who embezzled millions of Imperial credits. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Imperial prisons are reserved for political offenders. Fiduciary infractions are better handled by simple disintegration."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 97, 'm20o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 98, 'm20s', 'The Empire sends congratulations and this message: "You have shown true professionalism, bounty hunter. We commend your adherence to Imperial accounting protocols."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 99, 'm20t', 'Traitorous Embezzler'),
('string/en/mission/mission_bounty_imperial_easy.stf', 100, 'm20v', 'Please don''t hurt me! I''ll give the credits back!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 101, 'm21d', 'An Imperial bounty is hereby issued on a thief of trained dewback stock, responsible for obstructing military operations on Tatooine. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Dewbacks are important for Imperial security. You have disrupted a valuable breeding program."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 102, 'm21o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 103, 'm21s', 'The Empire sends congratulations and this message: "We''re glad that justice was not miscarried. Now our dewback breeding program can proceed unhindered."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 104, 'm21t', 'Dewback Rustler'),
('string/en/mission/mission_bounty_imperial_easy.stf', 105, 'm21v', 'You got the drop on me, but I ain''t down yet!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 106, 'm22d', 'An Imperial bounty is hereby issued on a well-established forgery expert, accused of aiding the Rebel Alliance. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Aiding the Rebellion is the highest treason. Rest assured, the price on your head is no forgery."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 107, 'm22o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 108, 'm22s', 'The Empire sends congratulations and this message: "Falsified documents compromise the security of all Imperial operations. You have served the galaxy well, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 109, 'm22t', 'Forgery Expert'),
('string/en/mission/mission_bounty_imperial_easy.stf', 110, 'm22v', 'Leave me alone! Help! Help!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 111, 'm23d', 'An Imperial bounty is hereby issued on a vagabond miscreant, dissolute lawbreaker, and thoroughly unprincipled reprobate. The target is also accused of defrauding a recently-widowed Coruscant aristocrat. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "I told you I had friends in high places, you heartless monster! I hope you die slowly!"'),
('string/en/mission/mission_bounty_imperial_easy.stf', 112, 'm23o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 113, 'm23s', 'The Empire sends congratulations and this message: "That detestable fiend had it coming. I hope you enjoyed the work, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 114, 'm23t', 'Vagabond Miscreant'),
('string/en/mission/mission_bounty_imperial_easy.stf', 115, 'm23v', 'Die slowly? I''ll stretch my death out fifty years if you look the other way for a second.'),
('string/en/mission/mission_bounty_imperial_easy.stf', 116, 'm24d', 'An Imperial bounty is hereby issued on a Rebel saboteur, wanted for thermobombing the TIE shipyards of Sienar Fleet Systems. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "No amount of sabotage daunts the Imperial Navy. Cowards like you don''t even warrant our direct action. This common bounty hunter will end your career."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 117, 'm24o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 118, 'm24s', 'The Empire sends congratulations and this message: "We knew a common bounty hunter would be more than a match for that minor scum."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 119, 'm24t', 'TIE Saboteur'),
('string/en/mission/mission_bounty_imperial_easy.stf', 120, 'm24v', 'Don''t be a dupe of the New Order, bounty hunter! Join us!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 121, 'm25d', 'An Imperial bounty is hereby issued on an outlaw propagandist, accused of disseminating lies about the Emperor and the New Order. Target is believed lightly armed and low-threat. The Empire orders you to give this message to the target before termination: "Your lies have corrupted millions of sentient beings. But your broadcasts are now concluded."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 122, 'm25o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_easy.stf', 123, 'm25s', 'The Empire sends congratulations and this message: "It is violence against the mind to spread lies and slander. You have brought down a dangerous criminal. Well done, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_easy.stf', 124, 'm25t', 'Outlaw Propagandist'),
('string/en/mission/mission_bounty_imperial_easy.stf', 125, 'm25v', 'Show me your moves, you Imperial tool!'),
('string/en/mission/mission_bounty_imperial_easy.stf', 126, 'number_of_entries', '25'),
('string/en/mission/mission_bounty_imperial_hard.stf', 1, 'm1d', 'Imperial Intelligence has identified the leader of a vast logistics network that serves the Rebellion. The Ubiqtorate hereby decrees an Imperial death bounty on this individual. Only elite hunters should attempt to bring down this mark. The target will be very well armed and should be approached with maximum caution. Success will earn a commendation in the hunter''s official dossier.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 2, 'm1o', 'Imperial Ubiqtorate'),
('string/en/mission/mission_bounty_imperial_hard.stf', 3, 'm1s', 'This Rebel leader was a major thorn in the Emperor''s side. You have earned the bounty and the respect of the Ubiqtorate. You will hear from us again.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 4, 'm1t', 'Highly Appointed Rebellion Facilitator'),
('string/en/mission/mission_bounty_imperial_hard.stf', 5, 'm1v', 'You''re going to regret finding me, bounty hunter!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 6, 'm2d', 'When the planetary government of Pliad 4 resisted Imperial annexation, a troublesome council of ministers was exiled to a prison world. These ministers have escaped custody. The Ubiqtorate hereby decrees an Imperial death bounty on each of these individuals. Hunters are warned that these ministers have demonstrated proficiency in armed combat, disguise, and clandestine movement. One bounty will be disbursed for each confirmed kill.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 7, 'm2o', 'Imperial Ubiqtorate'),
('string/en/mission/mission_bounty_imperial_hard.stf', 8, 'm2s', 'Outstanding. At this rate we shall eliminate all these exiled ministers within the year. Claim your bounty.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 9, 'm2t', 'Exiled Planetary Minister'),
('string/en/mission/mission_bounty_imperial_hard.stf', 10, 'm2v', 'Death to the Emperor and the New Order!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 11, 'm3d', 'A Rebel agent from Chryya, renowned for expertise with biotoxins, has poisoned a shipment of grain to Imperial troops under my command. I am offering a substantial bounty to the expert hunter who neutralizes this Rebel poisoner. Imperial law enforcement will forgive violent infractions committed during pursuit. Approach this task with utmost urgency. The Rebellion has a history of vanishing its agents after a major operation.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 12, 'm3o', 'Moff Krewe of Droma Sector'),
('string/en/mission/mission_bounty_imperial_hard.stf', 13, 'm3s', 'Brilliantly handled, bounty hunter. I foresee a long working relationship.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 14, 'm3t', 'Rebel Poisoner'),
('string/en/mission/mission_bounty_imperial_hard.stf', 15, 'm3v', 'Sithspit! How did you find me this far from Droma Sector?'),
('string/en/mission/mission_bounty_imperial_hard.stf', 16, 'm4d', 'A Rebel spy has infiltrated my command staff. Of course I detected the spy, but I must resolve the matter discreetly. I have granted the traitor a short leave of absence. The spy travels incognito, so expect a civilian and not a uniformed officer. Licensed hunters have my personal assurance that Imperial law enforcement will forgive any violent infractions committed during the elimination of this problem.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 17, 'm4o', 'Moff Krewe of Droma Sector'),
('string/en/mission/mission_bounty_imperial_hard.stf', 18, 'm4s', 'Brilliantly done. Say nothing if Imperial Intelligence questions you. My superiors need not learn that my command staff was compromised.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 19, 'm4t', 'Rebel Spy in My Command Staff'),
('string/en/mission/mission_bounty_imperial_hard.stf', 20, 'm4v', 'Who put a price on my head? Tell me!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 21, 'm5d', 'Lord Vader has requested my aid in removing troublesome Black Sun operatives. A certain Zekka Thyne from Corellia has hired assassins to wipe out his competition. Before we act directly against Thyne himself, I am issuing an Imperial bounty on Thyne''s hired killers. These agents are masters of disguise and extremely lethal. Whoever succeeds in removing these individuals will earn the favor of Lord Vader and myself.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 22, 'm5o', 'Vice Admiral Thrawn'),
('string/en/mission/mission_bounty_imperial_hard.stf', 23, 'm5s', 'Well done, bounty hunter. I reward those who serve me well. I may have work for you in the future.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 24, 'm5t', 'Black Sun Assassins'),
('string/en/mission/mission_bounty_imperial_hard.stf', 25, 'm5v', 'What Vigo hired you, bounty hunter? I want to deliver your head to the fool when this is done!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 26, 'm6d', 'An expert on satellite power systems has vanished from an Imperial military project. Restricted information may be compromised if this engineer contacts the Rebellion. A substantial reward will be paid to the hunter who destroys this threat to the Emperor''s plans. Make certain no one learns what that engineer knows. Disintegration is preferred. I want no mistakes.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 27, 'm6o', 'Lord Vader'),
('string/en/mission/mission_bounty_imperial_hard.stf', 28, 'm6s', 'The Empire will compensate you for your effort. Speak to no one about this, bounty hunter. Do not make me explain the importance of secrecy.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 29, 'm6t', 'Reactor Core Engineer'),
('string/en/mission/mission_bounty_imperial_hard.stf', 30, 'm6v', 'You won''t take me back to Vader! I''ll die first!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 31, 'm7d', 'My Star Destroyer was hosting a birthday celebration for the twin daughters of a local Moff. We hired an entertainer for the children. Our performer disabled the guards'' blaster rifles while engaging them in an audience-participation routine. Then this putative entertainer trapped us at blaster-point, robbed the children of their gifts -- mostly jewels confiscated from political prisoners -- and made a clean escape. I will fund a bounty from my official budget to have this criminal blasted to atoms.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 32, 'm7o', 'Captain Nob Finial'),
('string/en/mission/mission_bounty_imperial_hard.stf', 33, 'm7s', 'Good. My superiors are most interested in this case. They keep scheduling debriefings about the crime for an ever-expanding team of investigators. With luck, your success will speed my promotion to admiral.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 34, 'm7t', 'Audacious Robber'),
('string/en/mission/mission_bounty_imperial_hard.stf', 35, 'm7v', 'Bring it on, bounty hunter! I prefer a straight fight to all this sneaking around!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 36, 'm8d', 'A high-ranking officer in the Imperial Navy lost a battle to a squadron of Rebel star pilots. This officer failed to report to me for disciplinary action. I want this fugitive found. It is likely the officer will travel in disguise, but I do not expect you to be fooled. I want results as soon as possible. If I receive confirmation of a kill, I will double the posted bounty.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 37, 'm8o', 'Lord Vader'),
('string/en/mission/mission_bounty_imperial_hard.stf', 38, 'm8s', 'You''re as skilled as your reputation suggests, bounty hunter. However, I will not be doubling the reward. I am altering the deal. Pray I don''t alter it any further.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 39, 'm8t', 'Ex-Imperial Officer'),
('string/en/mission/mission_bounty_imperial_hard.stf', 40, 'm8v', 'Vader is a madman! If you''re wise, you''ll stay away from him too!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 41, 'm9d', 'An Imperial bounty is hereby issued on a deep-space salvage specialist. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "There is only one punishment for trespass in the Alderaan system."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 42, 'm9o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 43, 'm9s', 'The Empire sends congratulations and this message: "It is indisputable that the Rebel Alliance blew up Alderaan. To say otherwise is treason. Remember this."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 44, 'm9t', 'Deep-space Salvage Specialist'),
('string/en/mission/mission_bounty_imperial_hard.stf', 45, 'm9v', 'I scavenged enough evidence to prove the Empire really blew up that planet. The story they gave is a lie. You won''t stop me from telling the truth!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 46, 'm10d', 'An Imperial bounty is hereby issued on a strategist who helped organize the burglary of certain artifacts from the Emperor''s private museum on Coruscant. Target is believed heavily armed and high-threat. The Emperor himself orders you to speak this message to the target before termination: "You have meddled with forces more dangerous than you can possibly imagine."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 47, 'm10o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 48, 'm10s', 'The Emperor sends his regards and this message: "The hunt continues. Tell no one. Expect further assignments."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 49, 'm10t', 'Imperial Museum Theft Mastermind'),
('string/en/mission/mission_bounty_imperial_hard.stf', 50, 'm10v', 'I can imagine a lot. That Sith elite warbot we stole got activated somehow, and it killed most of our team. But I got away, like I''ll get away now!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 51, 'm11d', 'An Imperial bounty is hereby issued on the demolitions master who participated in the burglary of certain artifacts from the Emperor''s private museum on Coruscant. Target is believed heavily armed and high-threat. The Emperor himself orders you to speak this message to the target before termination: "The detonators you employed are trifles compared to the menace you unleashed."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 52, 'm11o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 53, 'm11s', 'The Emperor sends his regards and this message: "The hunt continues. Tell no one. Expect further assignments."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 54, 'm11t', 'Imperial Museum Theft Demolitions Expert'),
('string/en/mission/mission_bounty_imperial_hard.stf', 55, 'm11v', 'I''m starting to believe it. That Sith elite warbot we stole wiped out most of our team. But I don''t go easy!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 56, 'm12d', 'An Imperial bounty is hereby issued on a cloud car driver for the team of burglars who stole certain artifacts from the Emperor''s private museum on Coruscant. Target is believed heavily armed and high-threat. The Emperor himself orders you to speak this message to the target before termination: "There is no vehicle fast enough to carry you beyond my reach, or that of the menace you helped unleash."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 57, 'm12o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 58, 'm12s', 'The Emperor sends his regards and this message: "The hunt continues. Tell no one. Expect further assignments."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 59, 'm12t', 'Imperial Museum Theft Getaway Driver'),
('string/en/mission/mission_bounty_imperial_hard.stf', 60, 'm12v', 'Think so? The Sith elite warbot we stole didn''t move all that fast, even if it did kill most of our team. I got away from it, and I''ll get away from you.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 61, 'm13d', 'An Imperial bounty is hereby issued on the blockade runner who aided the escape of  burglars from the Emperor''s private museum on Coruscant. Target is believed heavily armed and high-threat. The Emperor himself orders you to speak this message to the target before termination: "The menace you unleashed has destroyed most of your team already. I grant you a mercy by killing you first."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 62, 'm13o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 63, 'm13s', 'The Emperor sends his regards and this message: "The hunt continues. Tell no one. Expect further assignments."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 64, 'm13t', 'Imperial Museum Theft Escape Pilot'),
('string/en/mission/mission_bounty_imperial_hard.stf', 65, 'm13v', 'That''s a mercy I can live without, thanks. You feel like tackling the Sith elite warbot we stole? It coud beat ten hunters like you. Me, I''ll just beat you.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 66, 'm14d', 'An Imperial bounty is hereby issued on a traitorous inside agent who participated in the burglary of certain artifacts from the Emperor''s private museum on Coruscant. Target is believed heavily armed and high-threat. The Emperor himself orders you to speak this message to the target before termination: "Your treachery has unleashed a menace beyond your feeble comprehension."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 67, 'm14o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 68, 'm14s', 'The Emperor sends his regards and this message: "The hunt continues. Tell no one. Expect further assignments."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 69, 'm14t', 'Imperial Museum Theft Accomplice'),
('string/en/mission/mission_bounty_imperial_hard.stf', 70, 'm14v', 'The only menace beyond my feeble comprehension is the Emperor. I hoped -- I still hope -- the Sith elite warbot we stole would go to the Alliance. Long live the Republic!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 71, 'm15d', 'An Imperial bounty is hereby issued on a gang leader who led a criminal assault on a company of stormtroopers in the Expansion Territories. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "Your criminal plunder will not serve you in death."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 72, 'm15o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 73, 'm15s', 'The Empire sends congratulations and this message: "Imperial Intelligence offers its assurance that this was, in fact, a criminal gang leader."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 74, 'm15t', 'Leader of Gang Assault on Stormtrooper Company'),
('string/en/mission/mission_bounty_imperial_hard.stf', 75, 'm15v', 'I''m insulted. I recruited citizens to wipe out those troopers as part of Alliance efforts to win the Expansion Territories. "Criminal"! That''s it, I''m gonna kill you.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 76, 'm16d', 'An Imperial bounty is hereby issued on a merchant freighter pilot who interfered with the capture of a Corellian smuggler and his Wookiee companion. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "It is unwise to interfere with Lord Vader''s plans."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 77, 'm16o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 78, 'm16s', 'The Empire sends congratulations and this message: "Lord Vader is also seeking a Rebel pilot named Skywalker. He must be brought in alive. Contact the Guild for details."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 79, 'm16t', 'Rebel Merchant Freighter Pilot'),
('string/en/mission/mission_bounty_imperial_hard.stf', 80, 'm16v', 'Darth Vader is looking for Han? Well, then, I''m even prouder that I decoyed that other bounty hunter off the Falcon. If you''ll excuse me, I have to alert the Alliance.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 81, 'm17d', 'An Imperial bounty is hereby issued on the leader of a pirate gang that attacked an Imperial escort frigate in the Mid Rim. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "Piracy is punishable by death."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 82, 'm17o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 83, 'm17s', 'The Empire sends congratulations and this message: "The Empire tells you that this was a pirate. Remember what the Empire tells you."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 84, 'm17t', 'Pirate Leader Active in Mid Rim'),
('string/en/mission/mission_bounty_imperial_hard.stf', 85, 'm17v', 'I''m with the Alliance! We blew up a Moff''s own flagship, and he''s trying to cover it up as "pirates." Please!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 86, 'm18d', 'An Imperial bounty is hereby issued on a Rebel spy whose espionage has cost the Empire billions of credits and hundreds of trained personnel. Target is believed heavily armed, high-threat, and extremely elusive. The Empire orders you to give this message to the target before termination: "Across a hundred worlds you have eluded capture, yet a mere bounty hunter has proven your equal. We shall inform the Emperor of your ultimate disgrace."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 87, 'm18o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 88, 'm18s', 'The Empire sends congratulations and this message: "Recent transmissions from Rebel commanders suggest we sent you after the wrong person. We are reevaluating our data. This does not reflect upon your performance, bounty hunter. The money is yours."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 89, 'm18t', 'Rebel Spymaster'),
('string/en/mission/mission_bounty_imperial_hard.stf', 90, 'm18v', 'A decoy''s fate is a noble sacrifice. I die serving the Alliance!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 91, 'm19d', 'An Imperial bounty is hereby issued on a space pirate commander of a ruthless armada of twenty warships that have defeated countless Imperial vessels. Target is believed heavily armed and extremely high-threat. The Empire orders you to give this message to the target before termination: "Commander, the trip is over."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 92, 'm19o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 93, 'm19s', 'The Empire sends congratulations and this message: "The pirate fleet will crumble without its commander, becoming easy prey for the Imperial Navy. You have performed an admirable service to the Empire."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 94, 'm19t', 'Pirate Fleet Commander'),
('string/en/mission/mission_bounty_imperial_hard.stf', 95, 'm19v', 'Bring it on, you drudge gunner! I eat bounty hunters for breakfast!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 96, 'm20d', 'An Imperial bounty is hereby issued on the leader of a daredevil armada of cloud raiders. Flying giant thrantas fitted with shields and turbolasers, these outlaws ambush Imperial shuttles from the concealment of atmospheric cloud banks. The armada moves between planets in a clandestine interstellar transport. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "Your exploits are renowned, Commodore, but the tales end here."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 97, 'm20o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 98, 'm20s', 'The Empire sends congratulations and this message: "Excellent work. Soon we shall hunt down this secret transport, kill the trained thrantas, and dispose of this armada of so-called adventurers."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 99, 'm20t', 'Commodore of the Thranta Armada'),
('string/en/mission/mission_bounty_imperial_hard.stf', 100, 'm20v', 'Ah, excellent! I was hoping to kill another bounty hunter before lunch.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 101, 'm21d', 'An Imperial bounty is hereby issued on an outlaw droid programmer who turned harmless utility droids into unstoppable war machines. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "Your devious plot has succeeded in disrupting many Imperial operations. Now you must pay."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 102, 'm21o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 103, 'm21s', 'The Empire sends congratulations and this message: "Another outlaw droid programmer eliminated. We cannot overstress the importance of removing this serious threat."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 104, 'm21t', 'Nefarious Droid Programmer'),
('string/en/mission/mission_bounty_imperial_hard.stf', 105, 'm21v', 'Kill me, bounty hunter, and the MSE-6X will not rest until you''re dead!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 106, 'm22d', 'An Imperial bounty is hereby issued on a renegade torturer who murdered an Imperial Intelligence supervisor. Target is heavily armed, high-threat, and renowned for cunning, cruelty, and ruthlessness. The Empire orders you to give no message to the target before termination. Instead we recommend the utmost caution and all available firepower.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 107, 'm22o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 108, 'm22s', 'The Empire sends congratulations and this message: "A lawful torturer is a necessary evil, but these barbarians must not be loosed on the galaxy."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 109, 'm22t', 'Renegade Torturer'),
('string/en/mission/mission_bounty_imperial_hard.stf', 110, 'm22v', 'How rude! Do let''s finish this quickly. I''m in a frightful hurry.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 111, 'm23d', 'An Imperial bounty is hereby issued on a high commander in the military arm of the Rebellion. Target is believed to be heavily armed, high-threat and traveling incognito. The Empire orders you to give this message to the target before termination: "The Republic is forgotten, your insurrection a pathetic fantasy. There can be no escape for traitors to the New Order."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 112, 'm23o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 113, 'm23s', 'The Empire sends congratulations and this message: "Excellent work, bounty hunter. Soon the last remnants of the Old Republic will be swept away."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 114, 'm23t', 'Rebel Commander'),
('string/en/mission/mission_bounty_imperial_hard.stf', 115, 'm23v', 'Don''t succumb to the Empire''s evil! The Alliance can use your skills!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 116, 'm24d', 'An Imperial bounty is hereby issued on the mastermind of a ring of mercenary hit squads employed against Imperial officers. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "We traced the chain of command for the hit squads and found you at the top. So falls another menace to galactic security."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 117, 'm24o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 118, 'm24s', 'The Empire sends congratulations and this message: "Even mercenaries must be held accountable for their actions. Don''t you agree, bounty hunter?"'),
('string/en/mission/mission_bounty_imperial_hard.stf', 119, 'm24t', 'Mercenary Kingpin'),
('string/en/mission/mission_bounty_imperial_hard.stf', 120, 'm24v', 'Your talents fit my organization, bounty hunter. You can either profit from this or die.'),
('string/en/mission/mission_bounty_imperial_hard.stf', 121, 'm25d', 'An Imperial bounty is hereby issued on a perfidious insurgent gladiator, once a champion on Derilyn but now an agent of the Rebellion. Target is remarkable not only for fighting prowess but also for skill and artfulness. Target is believed heavily armed and high-threat. The Empire orders you to give this message to the target before termination: "Time to exit the ring."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 122, 'm25o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_hard.stf', 123, 'm25s', 'The Empire sends congratulations and this message: "Great skill in combat is commendable for soldiers and gladiators, but outlaw fighters must be handled without mercy. See that you remember this fact, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_hard.stf', 124, 'm25t', 'Perfidious Insurgent Gladiator'),
('string/en/mission/mission_bounty_imperial_hard.stf', 125, 'm25v', 'I''m taking you with me, bounty hunter!'),
('string/en/mission/mission_bounty_imperial_hard.stf', 126, 'number_of_entries', '25'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 1, 'm1d', 'I have been authorized by the Inquisitorius to investigate the recent appearance of Force-sensitive individuals. Our mission continues the worthy Jedi purge begun by the early heroes of the New Order. I hereby issue an Imperial death bounty on all Jedi candidates. Your success will insure your place among the Emperor''s elite cadre of deadly Jedi Hunters.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 2, 'm1o', 'High Inquisitor Mal Sikander'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 3, 'm1s', 'Excellent, Jedi hunter. The Emperor rewards those servants who please him, and you have done so. Claim your bounty and stand ready to serve the Empire again.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 4, 'm1t', 'Remove Jedi Candidates'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 5, 'm1v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 6, 'm2d', 'We have been tracking and eliminating Force-using threats to the Empire since the original Jedi purge. It appears some have slipped through our fingers and have now fully developed as Jedi Knights. I call upon the Emperor''s Jedi hunters to locate these dangerous warriors and remove their threat to the Empire. Disintegration is most effective, although other disposal methods are acceptable. Serve your Emperor! Protect the Empire! '),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 7, 'm2o', 'High Inquisitor Mal Sikander'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 8, 'm2s', 'Your skills truly mark you as a Jedi hunter. The Emperor will not forget your loyal service and will reward you accordingly.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 9, 'm2t', 'Hunt the Jedi Knights'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 10, 'm2v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 11, 'm3d', 'The Rebellion seeks to restore the corrupt Republic, and many of these newly emerging Jedi are joining their cause. It is up to the Inquisitorius and the Emperor''s Jedi hunters to stop this dangerous trend. The Emperor''s power will protect you and grant victory against these skilled foes. Hunt down these Jedi, so that all may understand the glory that is the Empire.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 12, 'm3o', 'High Inquisitor Mal Sikander'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 13, 'm3s', 'Is this not more proof of the Emperor''s might? How can these Jedi hope to resist his dedicated servants? Claim your reward.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 14, 'm3t', 'Bring Down the Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 15, 'm3v', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 16, 'm4d', 'If the stories are to be believed, Jedi are invincible. Events have proven this is not the case. The Inquisitorius knows the Jedi use mind tricks to fool their enemies and, in all likelihood, alter the historical record. We are issuing Imperial death bounties on these Force warriors. Remove this threat and claim your reward.  '),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 17, 'm4o', 'High Inquisitor Mal Sikander'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 18, 'm4s', 'It pleases the Emperor when his Jedi hunters prove their superiority. You deserve this reward, hunter.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 19, 'm4t', 'Ignore Jedi Mind Tricks'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 20, 'm4v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 21, 'm5d', 'The Emperor''s power protects and guides his Jedi hunters. The Emperor himself has signed Imperial death bounties for each of these Force-sensitive individuals. If you have not already hunted Jedi, then match your skills against them and prove yourself worthy of the Emperor''s protection.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 22, 'm5o', 'High Inquisitor Mal Sikander'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 23, 'm5s', 'Well done, hunter. The Emperor knew you would be granted victory, for he sees everything and knows all ends. The reward is yours.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 24, 'm5t', 'Earn the Emperor''s Protection'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 25, 'm5v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 26, 'm6d', 'The Emperor and Lord Vader are most eager to eliminate all Force-using citizens, especially the Jedi Knights. I call upon the Scourge Column to assist me in eliminating this threat to the Empire. Many of you have faced Jedi before, so I do not need to warn of the great danger these individuals pose. The Imperial bounty I offer is appropriate for the risk involved. Serve me well, and the Emperor will hear of your success.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 27, 'm6o', 'Vice Admiral Thrawn'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 28, 'm6s', 'Most admirable, bounty hunter. I see why Lord Vader values your profession so highly. The Imperial bounty has been transmitted to you.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 29, 'm6t', 'Help Thrawn Serve the Emperor'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 30, 'm6v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 31, 'm7d', 'In reviewing trade reports for this sector, we have identified illicit transport activity attributed to a "Jedi," one of the legendary religious fanatics of the Old Republic. "Jedi" are, of course, illegal. A review of historical documents suggests that this heavily armed criminal is beyond this agency''s capacity to apprehend. Because your Imperial Peace-Keeping Certificate is shown to be current, you are commissioned to locate, face, and defeat the "Jedi."'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 32, 'm7o', 'Imperial Customs'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 33, 'm7s', 'That''s that, then. Imperial Customs will have no "Jedi" activity on its watch!'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 34, 'm7t', '"Jedi" Fanatic Criminal'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 35, 'm7v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 36, 'm8d', 'You are hereby assigned to destroy a newly reported Jedi Knight, one of the Old Republic''s ruthless strike troops. Like others of the defunct order, this Jedi Knight may be employing mental attacks and archaic energy weapons. Further, the Jedi may be cooperating with known pirates and smugglers. The ISB wishes this threat to civil order silenced. Tell no one of the Jedi''s existence or actions.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 37, 'm8o', 'Imperial Security Bureau, Planetary Headquarters'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 38, 'm8s', 'Your work has brought another measure of order to our galaxy. The ISB will contact you with further work in the future.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 39, 'm8t', 'Jedi Abetting Other Known Criminals'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 40, 'm8v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 41, 'm9d', 'The Old Republic''s terror weapon, the Jedi Knight, has reappeared. This self-appointed thug from the corrupt government''s unaccountable enforcement arm uses brutal weaponry and mind-altering skills. To prevent this ancient, phantom menace from manifesting again in the Empire, we charge you to eliminate the renegade Jedi. Tell no one of your mission. Victory will be ours!'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 42, 'm9o', 'Imperial Intelligence, Planetary Headquarters'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 43, 'm9s', 'Your success is noted. Remember, tell no one of the Jedi''s existence or activities. Imperial Intelligence will contact you again as needed.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 44, 'm9t', 'Self-Selected Subversive from Old Regime'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 45, 'm9v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 46, 'm10d', 'Be informed this communique is classified SECRET. Your urgent attention required in regards to reported activities of a known Jedi Knight. The Jedi, emissaries and executioners for the strife-ridden Old Republic, used unusual gear with high effectiveness. Locate and terminate said Jedi Knight immediately. Extreme caution. Highest priority. Situation critical.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 47, 'm10o', 'Imperial Army, Planetary Headquarters'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 48, 'm10s', 'Situation report received. Payment dispatched. Stand down from critical. Mission rermains classified SECRET.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 49, 'm10t', 'Army Intelligence Assignment: Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 50, 'm10v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 51, 'm11d', 'Our office deals directly only with capable agents known for loyalty to the Empire. To you falls the challenge of destroying a formidable enemy: one of the long-lost Jedi Knights. Now resurgent, these symbols of the corrupt Old Republic have menaced Imperial interests on several worlds. To you, whose reputation looms large among bounty hunters, we issue this assignment: hunt and kill the Jedi. Disintegration is permitted.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 52, 'm11o', 'Imperial Intelligence Ubiqtorate'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 53, 'm11s', 'The Ubiqtorate sends appropriate compensation. Tell no one of this assignment, lest the fire of the old Jedi religion reignite the galaxy.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 54, 'm11t', 'Jedi Target for the Elite Hunter'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 55, 'm11v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 56, 'm12d', 'The Ubiqtorate prefers to issue strategic directives through various subordinate organizations. Only the most critical issues require direct intervention. The current danger is an active Jedi Knight, a throwback to the corrupt Old Republic regime. To prevent a recurrence of troubles familiar to all students of the pre-Imperial epoch, eliminate the Jedi at once. Discretion is imperative. Tell no one of the Jedi''s whereabouts or activities, lest misguided accomplices seek to give aid to the enemy.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 57, 'm12o', 'Imperial Intelligence Ubiqtorate'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 58, 'm12s', 'The Ubiqtorate sends appropriate compensation. Tell no one of this assignment, lest the idea of resurgent Jedi fire the popular imagination.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 59, 'm12t', 'The Most Dangerous Target: Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 60, 'm12v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 61, 'm13d', 'The Naval Command Center has received reports of a recent interplanetary transit, apparently aboard a commercial shuttle, of a Jedi Knight, one of the strongarm thugs of the Old Republic bureaucracy. The age and provenance of the Jedi remain unknown, but in historical records these enforcers were considered most dangerous adversaries. Naval Command assesses threat level as MAXIMUM. Exercise extreme caution, but destroy without fail.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 62, 'm13o', 'Imperial Naval Command'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 63, 'm13s', 'Naval Command issues payment as agreed. Threat levels for Jedi reindexed based on your report. Naval Command hereby classifies SECRET the nature and content of this assignment.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 64, 'm13t', 'Highest-Threat Jedi Target'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 65, 'm13v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 66, 'm14d', 'The Naval Command Center issues this directive to a bounty hunter who has demonstrated the highest ability: Reports from witnesses aboard a commercial shuttle describe the distinctive weapon of the defunct Jedi order, a glowing energy blade. Naval Command assigns 90-plus percent confidence that the wielder of this weapon is a Jedi Knight, an Old Republic enforcer. Naval Command assigns you to destroy the Jedi. Exercise all possible caution against this most dangerous opponent. Threat level MAXIMUM.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 67, 'm14o', 'Imperial Naval Command'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 68, 'm14s', 'Naval Command issues payment as agreed. Threat levels for Jedi reindexed based on your report. Naval Command hereby classifies SECRET the nature and content of this assignment.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 69, 'm14t', 'Jedi Target, Maximum Threat'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 70, 'm14v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 71, 'm15d', 'Intelligence indicates possible activity of a Jedi Knight, one of the corrupt Old Republic''s enforcers. Identity and whereabouts unknown. The ISB requires you to destroy the Jedi by any means needed. The ISB will protect you from prosecution for incidental damage committed during direct confrontation with the target. Expect the most formidable resistance. This assignment is classified SECRET.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 72, 'm15o', 'Imperial Security Bureau, Central Operations'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 73, 'm15s', 'Excellent. Maintain strict confidentiality regarding the activities, and in fact the existence, of the Jedi. Should you fail to heed this warning, it will go badly for you.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 74, 'm15t', 'Classified Target: Jedi Knight'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 75, 'm15v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 76, 'm16d', 'The ISB designates you to destroy the most dangerous target in the galaxy: a member of the defunct order of the Jedi Knights. According to historic sources, these Old Republic enforcers displayed unsurpassed offensive and defensive abilities. In the absence of firm information, this new Jedi must be considered equally powerful. Take all imaginable precautions. This assignment is classified SECRET.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 77, 'm16o', 'Imperial Security Bureau, Central Operations'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 78, 'm16s', 'Excellent. Tell no one about this Jedi, or any others you may be assigned to terminate. Should you fail to heed this warning, it will go badly for you.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 79, 'm16t', 'Classified Target: Active Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 80, 'm16v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 81, 'm17d', 'A data analysis team has assessed passenger movements, purchases, intelligence reports, and eyewitness accounts and, with a 92-percent confidence level, has identified a member of the dismantled order of Jedi Knights. Historic sources indicate that these shadowy agents commanded tremendous abilities. You are to destroy the Jedi Knight. By authority of Imperial Security, the Information Center will disburse payment on success.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 82, 'm17o', 'Imperial Information Center'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 83, 'm17s', 'The Information Center has accepted your report of termination and will update records accordingly. Payment dispatched.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 84, 'm17t', 'Data Analysis Indicates Jedi Activity'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 85, 'm17v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 86, 'm18d', 'The Committee for Preservation of the New Order assigns you to destroy a newly detected Jedi Knight, one of the enforcers who propped up the corrupt Old Republic. The Jedi concept introduces memetic interference into COMPNOR''s strategies for conveying the Empire''s story to a sometimes resistant populace. These strongarm Jedi agents were reputed to command extraordinary physical and mental powers; COMPNOR advises maximum caution.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 87, 'm18o', 'COMPNOR Central Office'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 88, 'm18s', 'We send our regards for a job well done. Remember, it is unwise to spread the news of a resurgent Jedi. This would be conduct disloyal to the Empire.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 89, 'm18t', 'Jedi Interfering in Mass Edification'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 90, 'm18v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 91, 'm19d', 'The Committee for Preservation of the New Order informs you, in strict secrecy, of the existence of an active Jedi Knight, a throwback to the Old Republic paradigm of corruption and anarchy. Because this disruptive element could interfere with efficient re-education of recalcitrant populations, COMPNOR commissions you to hunt and kill this active Jedi. Exert maximum force in dispatching the target.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 92, 'm19o', 'COMPNOR Central Office'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 93, 'm19s', 'We send our regards for a job well done. It is unwise to spread the news of a resurgent Jedi. Maintain a discreet silence regarding this assignment.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 94, 'm19t', 'Jedi Obstacle to Paradigm Reorientation'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 95, 'm19v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 96, 'm20d', 'One of the ancient order of Jedi has reappeared. This is unacceptable. The Emperor instructs you to destroy the Jedi at once. Exercise great caution and maximum firepower. Tell no one. That is all.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 97, 'm20o', 'Imperial Royal Guard'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 98, 'm20s', 'We approve. Tell no one. That is all.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 99, 'm20t', 'Eliminate Jedi Promptly'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 100, 'm20v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 101, 'm21d', 'The corrupt Jedi order was destroyed after the Clone Wars, but the Empire sometimes sees misguided persons seek to revive the ancient religion. The Ubiqtorate offers a standing death bounty on such individuals. The targets, while not Jedi in the historical sense, do represent a maximum threat level. Use supreme caution and generous firepower. You have been warned.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 102, 'm21o', 'Imperial Intelligence Ubiqtorate'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 103, 'm21s', 'We have confirmed your liquidation of the so-called Jedi. Your skill is remarkable. The reward has been deposited in your account.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 104, 'm21t', 'Bounty on So-Called Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 105, 'm21v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 106, 'm22d', 'According to Imperial Intelligence, young Jedi Knights have surfaced in many star systems. They must not be allowed to survive. I call upon the elite bounty hunters of the Scourge Column. The first target has been verified. Data is being transmitted. Remember, Jedi are masters of the Force. Do not underestimate their powers. Execute this dangerous target and you will prove yourself worthy to remain a member of this hand-selected unit.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 107, 'm22o', 'Lord Vader'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 108, 'm22s', 'You prove worthy of your reputation. You will be a valuable asset to the Scourge Column.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 109, 'm22t', 'Scourge Column: Verified Jedi Target'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 110, 'm22v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 111, 'm23d', 'Intelligence from several systems indicates that a possible Jedi warrior has battled criminals and dangerous animals in the wilds of many planets. Because any Jedi is a potential asset to the Rebellion, we are posting a death bounty to the highest ranking hunters in the Empire. Do not attempt capture. Immediate execution is required. The threat level of a Jedi warrior is maximum. We do not want any to escape.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 112, 'm23o', 'Imperial Intelligence Ubiqtorate'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 113, 'm23s', 'So it was indeed a Jedi? Then your success is doubly commendable. Your bounty has been transmitted.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 114, 'm23t', 'Investigate a Suspected Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 115, 'm23v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 116, 'm24d', 'It has come to my attention that a suspected Jedi Knight was spotted passing through my sector. A directive from Imperial Center obliges me to halt this person''s movements. Accordingly I am offering a death bounty on this alleged Jedi to the top-ranked hunters in the galaxy. I want this affair wrapped up quickly and smoothly. I have enough problems dealing with the Rebellion without investigating every space traveller in a cape and robe.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 117, 'm24o', 'Moff Haille'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 118, 'm24s', 'I am surprised that the target was an actual Jedi. I am even more surprised that a bounty hunter killed a Jedi. Excellent work. This will look good in my report to Imperial Center.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 119, 'm24t', 'Death Bounty on Suspected Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 120, 'm24v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 121, 'm25d', 'Imperial Intelligence is shadowing a warrior known to be trained in the Jedi arts. Recently they lost the trail. This incompetence forces me to attend to the matter personally. I am dispatching the bounty hunters of the elite Scourge Column to locate and destroy this Jedi. Use caution. I want no more mistakes. While you pursue the Jedi, I will find out who in Imperial Intelligence is responsible for putting this matter into my hands.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 122, 'm25o', 'Lord Vader'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 123, 'm25s', 'Good work, bounty hunter. The Scourge Column is always reliable. While you were at your work, I identified the officers who lost the trail of the Jedi. Their commissions in Imperial Intelligence have now expired.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 124, 'm25t', 'Scourge Column: Missing Jedi'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 125, 'm25v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 126, 'm26d', 'The Inquisitorius is a confidential council in direct service to the Emperor. Your dealings with us must remain secret. We have foreseen great misfortune for the Imperial military at the hands of a certain individual who claims to be a Jedi Knight. We require you to execute this so-called Jedi. A Jedi Knight is one of the deadliest sapient beings in the galaxy. Spare no resources in this pursuit. Extreme violence is highly recommended.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 127, 'm26o', 'The Inquisitorius'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 128, 'm26s', 'Magnificent work, bounty hunter. The Emperor will be pleased by your success. Remember, tell no one of your dealings with the Inquisitorius.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 129, 'm26t', 'We Foresee Great Misfortune'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 130, 'm26v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 131, 'm27d', 'The Inquisitorius is a confidential council in direct service to the Emperor. Your dealings with us must remain secret. We have discovered a warrior with particularly strong Force sensitivity. We suspect that this person is receiving training in the Jedi arts. This must stop. Kill this warrior to forestall a grave threat to the Empire. Spare no resources in this pursuit. Extreme violence is highly recommended.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 132, 'm27o', 'The Inquisitorius'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 133, 'm27s', 'The Emperor applauds your ruthlessness, bounty hunter. Remember, tell no one of your dealings with the Inquisitorius.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 134, 'm27t', 'Warrior Receiving Forbidden Jedi Training'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 135, 'm27v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 136, 'm28d', 'Witnesses have reported the use of a Jedi lightsaber in a public conflict. This troubles the Emperor. I want the wielder of that lightsaber destroyed. Bounty hunters of the elite Scourge Column must track down and eliminate this suspected Jedi. The reward goes to the one who completes the job. Do not fail me.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 137, 'm28o', 'Lord Vader'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 138, 'm28s', 'It is no easy task to kill a master of the Force. I was wise to include you in the Scourge Column. Take your reward with my commendation.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 139, 'm28t', 'Scourge Column: Possible Jedi Target'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 140, 'm28v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 141, 'm29d', 'I have sensed a disturbance in the Force. Another Jedi warrior is loose in the galaxy. The Force is strong in this one, but as yet unfocused. I am transmitting information to the bounty hunters of the elite Scourge Column. I expect this Jedi to be found and disintegrated at once. Do not disappoint me.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 142, 'm29o', 'Lord Vader'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 143, 'm29s', 'You have served me well, bounty hunter. You are a worthy member of the Scourge Column.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 144, 'm29t', 'Scourge Column: Confirmed Jedi Target'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 145, 'm29v', ''),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 146, 'm30d', 'A criminal in Imperial custody alleges to have fought a Jedi. He claims his gang was slaughtered and he barely escaped with his life. We have agreed to release him if we locate this Jedi. Using the information he has given, bounty hunters of the elite Scourge Column must investigate this claim. The reward will go to the one who kills the Jedi. Remember, exercise maximum caution. Do not underestimate the power of the Force.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 147, 'm30o', 'Lord Vader'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 148, 'm30s', 'Your success is admirable. I''m afraid our informant did not share your good fortune. When we explained his pending exile to Dathomir, he claimed he was being treated unfairly. I found his lack of respect disturbing.'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 149, 'm30t', 'Scourge Column: Alleged Jedi Target'),
('string/en/mission/mission_bounty_imperial_hard_jedi.stf', 150, 'number_of_entries', '30'),
('string/en/mission/mission_bounty_imperial_medium.stf', 1, 'm1d', 'An Imperial bounty is hereby issued on a member of a major cred stick counterfeiting ring. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Your most prestigious client, Moff Weblin, turned out to be your last."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 2, 'm1o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 3, 'm1s', 'The Empire sends congratulations and this message: "Moff Weblin has paid your fee. Expression of concern over the integrity of the funds is unwarranted."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 4, 'm1t', 'Cred Stick Counterfeiter'),
('string/en/mission/mission_bounty_imperial_medium.stf', 5, 'm1v', 'Haha! Moff Weblin must have tried to buy a space yacht or something. Hope he didn''t hire you with those fake creds!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 6, 'm2d', 'An Imperial bounty is hereby issued on a fraudulent seller of luxury starships. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Moff Weblin will sigh wistfully to think of the fine ship your team promised him, though it proved only a space fantasy."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 7, 'm2o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 8, 'm2s', 'The Empire sends congratulations and this message: "Moff Weblin is above mere ''fuming.'' Disappointment over the imaginary nature of that fine ship is only natural."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 9, 'm2t', 'Fraudulent Luxury Starship Seller'),
('string/en/mission/mission_bounty_imperial_medium.stf', 10, 'm2v', 'Haha! Moff Weblin planned to launch himself to the stars in this ludicrously overfurnished starship we made up. He''s probably fuming with his lady friend about now.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 11, 'm3d', 'An Imperial bounty is hereby issued on a known accomplice of a duplicitous female confidence artist. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Your leader trifled with Captin Needa''s affections. Now Needa trifles with your lives."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 12, 'm3o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 13, 'm3s', 'The Empire sends congratulations and this message: "Captain Needa is of course subject to the vagaries of the heart. Expressions of glee over his betrayal are uncalled for."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 14, 'm3t', 'Female Con Artist''s Accomplice'),
('string/en/mission/mission_bounty_imperial_medium.stf', 15, 'm3v', 'Haha! Captain Needa fell for her sweet talk like a lovesick moisture farmer. He''s probably nursing a stiff drink of Corellian Double-brandy about now.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 16, 'm4d', 'An Imperial bounty is hereby issued on a purveyor of adulterated and diluted Corellian Double-brandy. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Captain Needa dislikes seeing fine spirits adulterated."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 17, 'm4o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 18, 'm4s', 'The Empire sends congratulations and this message: "Like anyone, Captain Needa enjoys a fine Double-brandy. It is unworthy of anyone, even a fraud, to express pleasure at the debasement of excellent spirit."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 19, 'm4t', 'Purveyor of Diluted Double-brandy'),
('string/en/mission/mission_bounty_imperial_medium.stf', 20, 'm4v', 'Haha! Captain Needa must have spat that terrible mouthwash all over his expensive Naboo furniture. And the price I got him to pay, whee!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 21, 'm5d', 'An Imperial bounty is hereby issued on a corrupt merchant of shoddy luxury furniture. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Admiral Zsinj dislikes seeing a cheap huckster trifle with the standards of Naboo chair-craft."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 22, 'm5o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 23, 'm5s', 'The Empire sends congratulations and this message: "Admiral Zsinj is no different from any citizen in his appreciation of good furniture. A confidence artist who plays on a good reputation deserves to suffer for it."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 24, 'm5t', 'Seller of Shoddy Luxury Furniture'),
('string/en/mission/mission_bounty_imperial_medium.stf', 25, 'm5v', 'Haha! Zsinj paid enough for that "luxury" bunch of sticks to furnish another room of his estate. What a sucker!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 26, 'm6d', 'An Imperial bounty is hereby issued on the architect who designed a Moff''s palace to criminally low standards. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Moff Graffe''s palace may fall, but rest assured you will go with it."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 27, 'm6o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 28, 'm6s', 'The Empire sends congratulations and this message: "Moff Graffe, like any rational being, believes the profession of architect should rise above mere political concerns."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 29, 'm6t', 'Negligent Moff Palace Architect'),
('string/en/mission/mission_bounty_imperial_medium.stf', 30, 'm6v', 'Haha! The sooner Moff Graffe''s shrine to bloated grandiosity falls down, the way I designed it to fall down, the sooner the Alliance can take his territory!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 31, 'm7d', 'An Imperial bounty is hereby issued on a criminally negligent supervisor of the construction droids that built a Moff''s palace. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Moff Graffe is dismayed by your lack of management ability."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 32, 'm7o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 33, 'm7s', 'The Empire sends congratulations and this message: "Moff Graffe obviously desires a safe and secure home, as do most sapient beings in the galaxy. To trifle with this fundamental desire is criminal."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 34, 'm7t', 'Negligent Moff Palace Construction Supervisor'),
('string/en/mission/mission_bounty_imperial_medium.stf', 35, 'm7v', 'Haha! My droids made sure Moff Graffe''s palace will blow over in the next strong wind. Then the Alliance can finally move on his world!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 36, 'm8d', 'An Imperial bounty is hereby issued on the murderer of an Imperial customs official on the Corellian Trade Route. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You should not have left so many fragments of the destroyed crate. We traced you easily."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 37, 'm8o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 38, 'm8s', 'The Empire sends congratulations and this message: "Many of these murderers wished to be traced, so as to die the death of martyrs. To forestall this outcome, avoid publicizing this assignment."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 39, 'm8t', 'Slayer of Imperial Customs Official'),
('string/en/mission/mission_bounty_imperial_medium.stf', 40, 'm8v', 'That corrupt official tried to "accidentally" destroy my crate because I wouldn''t pay him a bribe. That triggered my bomb. The Empire will go the same way!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 41, 'm9d', 'An Imperial bounty is hereby issued on the murderer of a high official who supervised planetary labor realignment in the Expansion Territories. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The droid''s brain survived the detonation, and he implicated you promptly."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 42, 'm9o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 43, 'm9s', 'The Empire sends congratulations and this message: "A lone voice of dissent is helpless against the Empire''s might."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 44, 'm9t', 'Slayer of Imperial Labor Supervisor'),
('string/en/mission/mission_bounty_imperial_medium.stf', 45, 'm9v', 'I booby-trapped that labor droid with a detonator because that Imperial officer was enslaving my entire homeworld! I''ll do it again, too, and you won''t stop me!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 46, 'm10d', 'An Imperial bounty is hereby issued on the murderer of an officer of the Imperial Environmental Preservation & Refocusing Authority. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You left your sniper rifle behind. Very sloppy."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 47, 'm10o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 48, 'm10s', 'The Empire sends congratulations and this message: "These murderers often wish to die a public death and so become martyrs. Therefore we discourage you from publicizing your success."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 49, 'm10t', 'Killer of Imperial Environmental Refocusing Official'),
('string/en/mission/mission_bounty_imperial_medium.stf', 50, 'm10v', 'That Imperial sleaze planned to destroy my homeworld''s ecosystem and turn it into a factory planet. Preventing that is worth a bounty hunter on my tail.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 51, 'm11d', 'An Imperial bounty is hereby issued on the killer of an Imperial engineer highly placed in a TIE Fighter design program. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "To leave a recording that gloats over your deed is senseless."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 52, 'm11o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 53, 'm11s', 'The Empire sends congratulations and this message: "Do not publicize this assignment. To do so would only bring this would-be martyr glory in the eyes of misguided citizens."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 54, 'm11t', 'Killer of TIE Fighter Engineer'),
('string/en/mission/mission_bounty_imperial_medium.stf', 55, 'm11v', 'He was working on a TIE Interceptor specifically designed to deploy bioterror weapons in planetary atmospheres. He deserved to die. You too, for serving the Empire!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 56, 'm12d', 'An Imperial bounty is hereby issued on the assassin who introduced poisonous kouhun arthropods into the sleeping quarters of an Imperial referee at the Blockade Runners Derby on Ord Mantell. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You left distinctive identity marks on the kouhuns'' carapaces."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 57, 'm12o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 58, 'm12s', 'The Empire sends congratulations and this message: "It is unwise to publicize this assignment, lest the Blockade Derby become politicized."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 59, 'm12t', 'Assassin of Blockade Runners Derby Referee'),
('string/en/mission/mission_bounty_imperial_medium.stf', 60, 'm12v', 'Yeah, I wanted folks to know I killed that sleazy referee. He was selling his rulings to the highest bidder. The Empire just uses the Derby to harvest money!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 61, 'm13d', 'An Imperial bounty is hereby issued on the would-be assassin who assaulted a Trandoshan labor supervisor carrying out Imperial business on Kashyyyk. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Incendiary flame beetles are a barbarous weapon."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 62, 'm13o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 63, 'm13s', 'The Empire sends congratulations and this message: "The Trandoshan supervisor is recovering. Our operations on Kashyyyk continue apace."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 64, 'm13t', 'Attempted Assassin of Trandoshan on Kashyyyk'),
('string/en/mission/mission_bounty_imperial_medium.stf', 65, 'm13v', 'That Trandoshan barbarian deserved to swallow that flame beetle. If he had, the Wookiees could have thrown off the yoke of slavery! Death to tyrants!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 66, 'm14d', 'An Imperial bounty is hereby issued on the killer of a military researcher at a classified location. Target is believed moderately armed and medium-threat. The Empire orders you to terminate the target without preliminary conversation, and to turn off all recording devices before the termination.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 67, 'm14o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 68, 'm14s', 'The Empire sends congratulations and this message: "Treat all locations the target may have named as classified intelligence. Do not reveal them on pain of death."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 69, 'm14t', 'Killer of Military Researcher at Classified Location'),
('string/en/mission/mission_bounty_imperial_medium.stf', 70, 'm14v', 'Yes, I killed him, and I almost destroyed the whole Maw Cluster installation too! Those scientists are creating planet-killer weapons! I -- wait! Don''t!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 71, 'm15d', 'An Imperial bounty is hereby issued on a civilian merchant selling unlicensed Republic-era Geonosian sonic cannon technology in defiance of Imperial edict. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You had one chance to cooperate. That chance is gone."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 72, 'm15o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 73, 'm15s', 'The Empire sends congratulations and this message: "When the Empire makes an offer to purchase weapons, it is always prudent to take the offer."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 74, 'm15t', 'Dealer in Geonosian Sonic Weapons'),
('string/en/mission/mission_bounty_imperial_medium.stf', 75, 'm15v', 'I''ll never cooperate with Imperial tyrants! When I discovered that cache of old weapons, I wanted the Alliance to use them to restore the Republic!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 76, 'm16d', 'An Imperial bounty is hereby issued on a saboteur of the Empire''s probot reconnaissance droids. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The very droids you hoped to ruin were instrumental in locating you."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 77, 'm16o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 78, 'm16s', 'The Empire sends congratulations and this message: "Imperial Star Destroyers routinely screen cargo and droids for common sabotage devices."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 79, 'm16t', 'Saboteur of Imperial Probe Droids'),
('string/en/mission/mission_bounty_imperial_medium.stf', 80, 'm16v', 'How ironic. At the factory I arranged for those droids to blow up as soon as they reached their Star Destroyer. Can''t trust a droid, can you?'),
('string/en/mission/mission_bounty_imperial_medium.stf', 81, 'm17d', 'An Imperial bounty is hereby issued on an Imperial Navy quartermaster who deserted under fire. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The Rebels you fled from were not a tenth so dangerous to you as we are now."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 82, 'm17o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 83, 'm17s', 'The Empire sends congratulations and this message: "Whether facing Rebels or pirates, an Imperial officer must not quaver."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 84, 'm17t', 'Navy Quartermaster Deserter'),
('string/en/mission/mission_bounty_imperial_medium.stf', 85, 'm17v', 'Rebels? I fled from the Hutts! Their pirate ships attacked my frigate, and I headed for the escape pod. This is so unfair!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 86, 'm18d', 'An Imperial bounty is hereby issued on a spy who attempted to procure hyperdrive schematics for a proposed factory on Naboo''s moon Rori. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The hyperdrive factory will not be built."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 87, 'm18o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 88, 'm18s', 'The Empire sends congratulations and this message: "It is not in our interest for hyperdrives to be freely available."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 89, 'm18t', 'Thief of Hyperdrive Schematics'),
('string/en/mission/mission_bounty_imperial_medium.stf', 90, 'm18v', 'If the Empire wants its hyperdrives bottled up forever, it should say so! We must take control of our own drive production!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 91, 'm19d', 'An Imperial bounty is hereby issued on a notorious member of the Freeholders smuggling gang. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "It would have been easier to pay the Moff''s custom duty."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 92, 'm19o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 93, 'm19s', 'The Empire sends congratulations and this message: "These smugglers have evidently thrown in with the Rebels. You may count on further Freeholder targets."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 94, 'm19t', 'Freeholder Gang Smuggler'),
('string/en/mission/mission_bounty_imperial_medium.stf', 95, 'm19v', 'The Moff''s "duty" required me to lead him to my gang''s home base. No thanks!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 96, 'm20d', 'An Imperial bounty is hereby issued on the slayer of a Barabel mercenary in the Empire''s employ. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "In the march to victory, we must set aside petty grievances."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 97, 'm20o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 98, 'm20s', 'The Empire sends congratulations and this message: "Barabels have a combative nature that works against their best interests -- not unlike their enemies, it seems."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 99, 'm20t', 'Slayer of Barabel Mercenary'),
('string/en/mission/mission_bounty_imperial_medium.stf', 100, 'm20v', 'That guy blew up my landspeeder just because he could. And he laughed! He had to pay!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 101, 'm21d', 'An Imperial bounty is hereby issued on a smuggler supplying weapons to the native Chubbits on Aridus in the Flarestar system. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Compassion for hopeless native causes is not the path to victory."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 102, 'm21o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 103, 'm21s', 'The Empire sends congratulations and this message: "Victory is ours."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 104, 'm21t', 'Weapons Smuggler on Aridus'),
('string/en/mission/mission_bounty_imperial_medium.stf', 105, 'm21v', 'The Imperials built a signal tower that crippled the Chubbits'' nervous systems. No wonder they turned to the Alliance. You should have too, hunter!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 106, 'm22d', 'An Imperial bounty is hereby issued on the leader of a crime ring stealing valuable antique droids. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Gladiator droids died with the Old Republic. Now you will too."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 107, 'm22o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 108, 'm22s', 'The Empire sends congratulations and this message: "Citizens report seeing the escaped gladiator droid on several planets. Apparently it is highly mobile, but we shall inevitably recapture it."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 109, 'm22t', 'Leader of Antique Droid Theft Ring'),
('string/en/mission/mission_bounty_imperial_medium.stf', 110, 'm22v', 'You got nothing on me! That gladiator droid got loose. What, you gonna kill me anyway? Try it!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 111, 'm23d', 'An Imperial bounty is hereby issued on a sabaoteur of a mining operation on Alzoc III in the Outer Rim Territories. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The garrison commander sends his regards."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 112, 'm23o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 113, 'm23s', 'The Empire sends congratulations and this message: "The garrison commander sends his regards to you as well -- his kindest regards, this time."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 114, 'm23t', 'Saaboteur of Alzoc III Mine'),
('string/en/mission/mission_bounty_imperial_medium.stf', 115, 'm23v', 'The Empire has enslaved the Talz race to mine those wastelands, and no one even knows! I''m spreading the word, and you can''t stop me!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_bounty_imperial_medium.stf', 116, 'm24d', 'An Imperial bounty is hereby issued on a citizen who gave support and succor to Alliance Commander Evram Lajaie. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You should have been more careful in your choice of associates."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 117, 'm24o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 118, 'm24s', 'The Empire sends congratulations and this message: "Evram Lajaie discovered the flaw in the Death Star battle station. All who associate with him are suspect."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 119, 'm24t', 'Associate of Evram Lajaie'),
('string/en/mission/mission_bounty_imperial_medium.stf', 120, 'm24v', 'Evram Lajaie is a hero of the Alliance. Let me be worthy of his example!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 121, 'm25d', 'An Imperial bounty is hereby issued on the Rebel who led a guerrilla assault on a Corellian shipping depot. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The Rebellion is hopeless. All will join us or share your fate."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 122, 'm25o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 123, 'm25s', 'The Empire sends congratulations and this message: "Corrupt shipping officials must not be assassinated without the Empire''s permission."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 124, 'm25t', 'Guerrilla Assault Leader at Corellian Depot'),
('string/en/mission/mission_bounty_imperial_medium.stf', 125, 'm25v', 'Y''know, we were just trying to ship out some cargo when that crooked depot owner stole it. I lost my temper. Like this!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 126, 'm26d', 'An Imperial bounty is hereby issued on a slicer who purloined Imperial Star Destroyer holo-coding protocols. Target is believed moderately armed and medium-threat. Remove and destroy any datadiscs you may find on the target''s body.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 127, 'm26o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 128, 'm26s', 'The Empire sends apologies and this message: "Evidently the slicer altered our mission data. The identity of your target is unknown to us. However, because you performed the requested service, we disburse the agreed payment."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 129, 'm26t', 'Slicer who Stole Star Destroyer Codes'),
('string/en/mission/mission_bounty_imperial_medium.stf', 130, 'm26v', 'Slicer? You''ve made a mistake, citizen. And if you think I''m dying quietly, that''s another mistake.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 131, 'm27d', 'An Imperial bounty is hereby issued on a slicer who altered sanitation droid programming aboard an Imperial Star Destroyer. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The stink of treason led us to you."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 132, 'm27o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 133, 'm27s', 'The Empire sends congratulations and this message: "Cleanup of the Star Destroyer hold is now complete. Victory is ours."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 134, 'm27t', 'Slicer who Altered Sanitation Droid Programming'),
('string/en/mission/mission_bounty_imperial_medium.stf', 135, 'm27v', 'I''ll bet "the stink of a hold full of sewage" beats "the stink of treason" any day.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 136, 'm28d', 'An Imperial bounty is hereby issued on a confidence artist who attempted a military scrip exchange deception at the Imperial Military Academy on Carida. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "To corrupt our young soldiers is to corrupt our future."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 137, 'm28o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 138, 'm28s', 'The Empire sends congratulations and this message: "The Military Academy has taken steps to convince students of their error."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 139, 'm28t', 'Military Scrip-Exchange Con Artist'),
('string/en/mission/mission_bounty_imperial_medium.stf', 140, 'm28v', 'Hah! Carida''s all Alliance. The "young soldiers," who couldn''t sell me their scrip fast enough, will jump ship to an Alliance recruiter right after graduation!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 141, 'm29d', 'An Imperial bounty is hereby issued on a spy who poisoned the food in the Imperial Governor''s Palace on Eriadu. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The shades of those you poisoned await you."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 142, 'm29o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 143, 'm29s', 'The Empire sends congratulations and this message: "Only treachery among the kitchen staff could explain the mass poisoning. We have now terminated all personnel involved in the incident."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 144, 'm29t', 'Poisoner in Eriadu Governor''s Palace'),
('string/en/mission/mission_bounty_imperial_medium.stf', 145, 'm29v', 'If you''d worked in that slave pit, you''d have poisoned them too!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 146, 'm30d', 'An Imperial bounty is hereby issued on the assassin who attempted to murder Imperial engineer Umak Leth. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "In dying, you are fortunate not to face the devices Umak Leth intended for your world."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 147, 'm30o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 148, 'm30s', 'The Empire sends congratulations and this message: "Repeat nothing the target might have said. More than your career depends on your silence."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 149, 'm30t', 'Failed Assassin of Umak Leth'),
('string/en/mission/mission_bounty_imperial_medium.stf', 150, 'm30v', 'Leth is building war machines that can strip-mine entire planets! No, don''t shoot --!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 151, 'm31d', 'An Imperial bounty is hereby issued on a Rebel spy who gathered intelligence on Imperial activities on Gamorr. Target is believed moderately armed and medium-threat. The Empire requires that no message be given to the target before termination, and that the target not be allowed to speak.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 152, 'm31o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 153, 'm31s', 'The Empire sends congratulations and this message: "If the target said anything, ignore it. Or else."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 154, 'm31t', 'Dangerous Spy'),
('string/en/mission/mission_bounty_imperial_medium.stf', 155, 'm31v', 'I tried getting intelligence for the Alliance. I only found that those stupid Imperials squandered a fortune trying to teach Gamorreans factory management. What a letdown!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 156, 'm32d', 'An Imperial bounty is hereby issued on a docking authority officer convicted of extorting bribes in a Core World starport. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You picked the wrong ship for your so-called hygiene inspection."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 157, 'm32o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 158, 'm32s', 'The Empire sends congratulations and this message: "Corruption can be tolerated, but only within limits."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 159, 'm32t', 'Corrupt Docking Authority Officer'),
('string/en/mission/mission_bounty_imperial_medium.stf', 160, 'm32v', 'I was living the good life until I tried to shake down that ship. Turned out it belonged to some Moff''s daughter.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 161, 'm33d', 'An Imperial bounty is hereby issued on a blockade runner whose smuggling ship escaped pursuit in the Dantooine system. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You had to get out of your ship sometime, Captain."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 162, 'm33o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 163, 'm33s', 'The Empire sends congratulations and this message: "One less smuggler is one less potential supplier for the Rebellion."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 164, 'm33t', 'Dantooine Blockade Runner'),
('string/en/mission/mission_bounty_imperial_medium.stf', 165, 'm33v', 'I''ve gotten out of worse scrapes than this!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 166, 'm34d', 'An Imperial bounty is hereby issued on the captain of a rebellious infantry unit defeated by stormtroopers on Mantooine. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You have run from us for many years, but the battle isn''t over until the last enemy falls. You are the last."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 167, 'm34o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 168, 'm34s', 'The Empire sends congratulations and this message: "You have succeeded where many hunters failed. The Empire appreciates your competence."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 169, 'm34t', 'Rebel Infantry Captain'),
('string/en/mission/mission_bounty_imperial_medium.stf', 170, 'm34v', 'I knew this day would come. Let''s finish it!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 171, 'm35d', 'An Imperial bounty is hereby issued on a star pilot known to fly fighters for the Rebel Alliance. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Destruction in space is too good for a traitorous pilot. Die on the ground like the worm you are!"'),
('string/en/mission/mission_bounty_imperial_medium.stf', 172, 'm35o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 173, 'm35s', 'The Empire sends congratulations and this message: "How many fighter ships have we lost to Rebel star pilots? We must dispose of them by every means available. Look for more Rebel targets soon."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 174, 'm35t', 'Rebel Fighter Pilot'),
('string/en/mission/mission_bounty_imperial_medium.stf', 175, 'm35v', 'Blast you, bounty hunter! I''m not going to die like this!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 176, 'm36d', 'An Imperial bounty is hereby issued on an escaped artillery technician, convicted of installing turbolasers for use by the Rebellion. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Your turbolasers have orphaned many children of the Empire. Time to pull the plug."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 177, 'm36o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 178, 'm36s', 'The Empire sends congratulations and this message: "Your professionalism has been noted by the Imperial Security Bureau. Good work, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 179, 'm36t', 'Rebel Artillery Tech'),
('string/en/mission/mission_bounty_imperial_medium.stf', 180, 'm36v', 'You won''t take me without a fight!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 181, 'm37d', 'An Imperial bounty is hereby issued on a top organizer of the underground Rebel movement on Morvogodine. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You should never have fled the shadows of Morvogodine. Now the trap has closed."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 182, 'm37o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 183, 'm37s', 'The Empire sends congratulations and this message: "The Rebel underground on Morvogodine has expedited the escape of far too many traitors. Your good work today will help put a stop to it."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 184, 'm37t', 'Rebel Underground Organizer'),
('string/en/mission/mission_bounty_imperial_medium.stf', 185, 'm37v', 'I fight to the last in the name of the Alliance!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 186, 'm38d', 'An Imperial bounty is hereby issued on a notorious space bandit, wanted for countless violent infractions among the frontier worlds. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You were skilled enough to elude us in the frontier. But you cannot escape Imperial justice here."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 187, 'm38o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 188, 'm38s', 'The Empire sends congratulations and this message: "The death toll from that slug''s predations is estimated at over fifty. The galaxy is a safer place now. The Empire has noted your good work."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 189, 'm38t', 'Frontier Bandit'),
('string/en/mission/mission_bounty_imperial_medium.stf', 190, 'm38v', 'Is that the best you got, bounty hunter? What a joke!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 191, 'm39d', 'An Imperial bounty is hereby issued on an escapee from the prison camps of Circarpous V. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Even an Imperial prisoner can access sensitive information. Your escape was unfortunate, as your death must now be painful."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 192, 'm39o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 193, 'm39s', 'The Empire sends congratulations and this message: "The penalty for escaping Imperial internment is death. Some prisoners require additional care. Repeat nothing the mark may have said, and you will be noted for your professionalism in our records."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 194, 'm39t', 'Prison Camp Escapee'),
('string/en/mission/mission_bounty_imperial_medium.stf', 195, 'm39v', 'Stop! I have important information about a crystal found on Mimban!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 196, 'm40d', 'An Imperial bounty is hereby issued on the instigator of a prison revolt on Delrian, which caused the death of fifty Imperial soldiers. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "We have tracked down all of the criminals you helped to escape. Join them now in oblivion."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 197, 'm40o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 198, 'm40s', 'The Empire sends congratulations and this message: "No one has ever succesfully escaped from the prison planet of Delrian. You have helped safeguard our perfect record."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 199, 'm40t', 'Prison Revolt Instigator'),
('string/en/mission/mission_bounty_imperial_medium.stf', 200, 'm40v', 'Better dead here than on Delrian!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 201, 'm41d', 'An Imperial bounty is hereby issued on the instigator of a slave revolt on the ocean planet of Kodai. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Your little insurrection is at an end. Kneel, and this bounty hunter will execute you swiftly."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 202, 'm41o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 203, 'm41s', 'The Empire sends congratulations and this message: "Willful slaves are no end of trouble. You have a knack for dealing with them. Good work, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 204, 'm41t', 'Undersea Slave Insurrectionist'),
('string/en/mission/mission_bounty_imperial_medium.stf', 205, 'm41v', 'Better to die free than live as a slave!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 206, 'm42d', 'An Imperial bounty is hereby issued on a notorious rebel spy. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You could not escape us forever. All star lanes lead back to the Empire."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 207, 'm42o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 208, 'm42s', 'The Empire sends congratulations and this message: "That''s one less spy to endanger our loyal Imperial operatives. Excellent work, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 209, 'm42t', 'Rebel Spy'),
('string/en/mission/mission_bounty_imperial_medium.stf', 210, 'm42v', 'It took you long enough to catch up to me! I was starting to get bored.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 211, 'm43d', 'An Imperial bounty is hereby issued on a freelance assassin who specializes in exotic poisons. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "The Empire does not forgive the murder of a valued fleet captain, even one who indulged in unauthorized sabacc with known poisoners. First we shall eliminate you and then the Nemoidians who hired you."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 212, 'm43o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 213, 'm43s', 'The Empire sends congratulations and this message: "One hates to lose a good hired assassin, especially one so stylish. Perhaps someday you can fill the void on our list of freelancers."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 214, 'm43t', 'Freelance Poisoner'),
('string/en/mission/mission_bounty_imperial_medium.stf', 215, 'm43v', 'Can''t we discuss this over a drink?'),
('string/en/mission/mission_bounty_imperial_medium.stf', 216, 'm44d', 'An Imperial bounty is hereby issued on a fugitive arsonist, convicted of firebombing Imperial droid foundries in six systems. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Your actions betray your Rebel sympathies. Your fire will now go out of the universe."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 217, 'm44o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 218, 'm44s', 'The Empire sends congratulations and this message: "Arson is a horrible crime. You have snuffed out a gruesome killer and earned the bounty."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 219, 'm44t', 'Industrial Arsonist'),
('string/en/mission/mission_bounty_imperial_medium.stf', 220, 'm44v', 'Burn, Imperial dog!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 221, 'm45d', 'An Imperial bounty is hereby issued on a violent agitator, accused of mayhem and riotry throughout the Core Worlds. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "It is treason to speak against the New Order. To start anti-Imperial riots draws other citizens into your sedition."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 222, 'm45o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 223, 'm45s', 'The Empire sends congratulations and this message: "We monitored your engagement. It took you longer than we expected to find such a simple mark, but you did bring him down with reasonable promptness. We will note this in our files."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 224, 'm45t', 'Violent Agitator'),
('string/en/mission/mission_bounty_imperial_medium.stf', 225, 'm45v', 'Time to die, bounty hunter scum!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 226, 'm46d', 'An Imperial bounty is hereby issued on a droidsmith suspected of working for the Rebellion. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Even an insignificant droid is another rivet in the terror machine of the Rebellion."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 227, 'm46o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 228, 'm46s', 'The Empire sends congratulations and this message: "Do not be fooled by cries of innocence. Only a guilty criminal would run so far and fast. Well done, bounty hunter."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 229, 'm46t', 'Rebel Droidsmith'),
('string/en/mission/mission_bounty_imperial_medium.stf', 230, 'm46v', 'You can''t kill me over a few droids! Please, no!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 231, 'm47d', 'An Imperial bounty is hereby issued on a rogue antiquarian, guilty of stealing valuable Procopian artifacts from an Imperial museum on Coruscant. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You chose the wrong friends. This time it will cost you."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 232, 'm47o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 233, 'm47s', 'The Empire sends congratulations and this message: "That antiquarian was very, very dangerous. We are pleased you are not dead."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 234, 'm47t', 'Rogue Antiquarian'),
('string/en/mission/mission_bounty_imperial_medium.stf', 235, 'm47v', 'Bounty hunters. I hate these guys.'),
('string/en/mission/mission_bounty_imperial_medium.stf', 236, 'm48d', 'An Imperial bounty is hereby issued on a masked hack pilot, accused on Coruscant of flying an unlicensed taxi shuttle and kidnapping off-duty Imperials. Target is believed to be traveling in disguise, moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Your masked antics are over. This bounty hunter will deliver our response to your ransom demands."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 237, 'm48o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 238, 'm48s', 'The Empire sends congratulations and this message: "When a filthy degenerate like that puts on a mask, they believe they''re unaccountable for their offenses. Sooner or later, though, they are always unmasked. Don''t you agree, bounty hunter?"'),
('string/en/mission/mission_bounty_imperial_medium.stf', 239, 'm48t', 'Masked Hack Pilot'),
('string/en/mission/mission_bounty_imperial_medium.stf', 240, 'm48v', 'Nobody stiffs me, bounty hunter!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 241, 'm49d', 'An Imperial bounty is hereby issued on a violent swoop rider with suspected ties to the Rebellion. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "Your seemingly random acts of violence create a suspiciously anti-Imperial pattern. A simple bounty is enough to stop wretched scum like you."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 242, 'm49o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 243, 'm49s', 'The Empire sends congratulations and this message: "The Rebellion attracts rabble and scum with promises of a noble purpose. It is the nature of filthy scavengers to wallow with the maggots."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 244, 'm49t', 'Rebel-Aligned Swoop Rider'),
('string/en/mission/mission_bounty_imperial_medium.stf', 245, 'm49v', 'You''re bantha fodder, bounty hunter!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 246, 'm50d', 'An Imperial bounty is hereby issued on an infamous assassin, previously freelance but now working with the Rebellion. Target is known to be addicted to stims that enhance combat effectiveness. Target is believed moderately armed and medium-threat. The Empire orders you to give this message to the target before termination: "You believe you''ve found new meaning for your sad, degenerate life. You have simply made yourself useless to the Empire. Your career is ended."'),
('string/en/mission/mission_bounty_imperial_medium.stf', 247, 'm50o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_imperial_medium.stf', 248, 'm50s', 'The Empire sends congratulations and this message: "An assassin with a conscience is worse than useless. Don''t you agree, bounty hunter?"'),
('string/en/mission/mission_bounty_imperial_medium.stf', 249, 'm50t', 'Rebel Stim Assassin'),
('string/en/mission/mission_bounty_imperial_medium.stf', 250, 'm50v', 'I don''t need stims against the likes of you!'),
('string/en/mission/mission_bounty_imperial_medium.stf', 251, 'number_of_entries', '50'),
('string/en/mission/mission_bounty_informant.stf', 1, 'informant_list_title', 'Your Informants:'),
('string/en/mission/mission_bounty_informant.stf', 2, 'target_biological_signature', 'Biological Signature Received:'),
('string/en/mission/mission_bounty_informant.stf', 3, 'target_easy_1', 'Lookin'' for someone, eh? So th'' guild tells me, anyhoo. Well, I think I might be able to help ya. I kin upload the info to yer datapad...'),
('string/en/mission/mission_bounty_informant.stf', 4, 'target_easy_2', 'So, the guild informs that you seek a particularly elusive quarry. It doesn''t speak too well for your investigative skills, my friend, that I was able to track them down in such short order! Let me simply upload the details to your datapad...'),
('string/en/mission/mission_bounty_informant.stf', 5, 'target_easy_3', 'Looking for someone, huh? And you need my help. Everyone always needs my help. Well, I already know who you want, and as usual, I can help. Just ask nicely next time. I''m uploading the stuff to your datapad now.'),
('string/en/mission/mission_bounty_informant.stf', 6, 'target_easy_4', 'You''re late. The information required is uploading to your datapad as we speak. The guild contacted me in advance of your arrival. Next time, be prompt.'),
('string/en/mission/mission_bounty_informant.stf', 7, 'target_easy_5', 'The guild tells me you''re looking for someone. I''ve talked with my informants and tracked down your target. They''re not trying to stay hidden so tracking them down shouldn''t be a problem. I''ll transmit their location to your datapad.'),
('string/en/mission/mission_bounty_informant.stf', 8, 'target_hard_1', 'The guild must think highly of you to give you this mission. Your target knows we''re after them and is avoiding all contact with the imperial holo-net. I''m transmitting your target''s biological signature to your datapad for use in a probe droid. You''re going to have to use Imperial probots to discover what planet your target is on.'),
('string/en/mission/mission_bounty_informant.stf', 9, 'target_hard_2', 'Yer in big trouble. I''m ain''t envyin'' ya this one, never mind how high the guild thinks of ya! Yer target knows yer out fer blood. Gone to ground, they have. Yer going to be needin'' this bio-sig for yer probe droids. Good luck.'),
('string/en/mission/mission_bounty_informant.stf', 10, 'target_hard_3', 'Always a pleasure to help a distinguished bounty hunter such as yourself! Your quarry this time has gone to ground, and you''ll need this biological signature for your probe droids. I''m sure it''ll be no problem for someone like you though.'),
('string/en/mission/mission_bounty_informant.stf', 11, 'target_hard_4', 'Even high and mighty bounty hunters need to move faster than this, you know. Your quarry''s gone. I have no idea where. But I have a biological signature. So here you go, put it in your datapad, and good luck with the probe droids.'),
('string/en/mission/mission_bounty_informant.stf', 12, 'target_hard_5', 'I fear the odds are against you this time, my friend. Not only has your quarry seemingly vanished into thin air, but I''ve heard not a single word as to whether they have gone offworld or not. I fear the best I can do is offer this biological signature. I wish you the best of luck!'),
('string/en/mission/mission_bounty_informant.stf', 13, 'target_hard_corellia_1', 'The only other information I have right now is that your target was last tracked entering Corellian space.'),
('string/en/mission/mission_bounty_informant.stf', 14, 'target_hard_dathomir_1', 'The only other information I have right now is that your target was last tracked entering Dathomir space.'),
('string/en/mission/mission_bounty_informant.stf', 15, 'target_hard_endor_1', 'The only other information I have right now is that your target was last tracked entering Endor space.'),
('string/en/mission/mission_bounty_informant.stf', 16, 'target_hard_naboo_1', 'The only other information I have right now is that your target was last tracked entering Naboo space.'),
('string/en/mission/mission_bounty_informant.stf', 17, 'target_hard_rori_1', 'The only other information I have right now is that your target was last tracked entering Rori space.'),
('string/en/mission/mission_bounty_informant.stf', 18, 'target_hard_talus_1', 'The only other information I have right now is that your target was last tracked entering Talus space.'),
('string/en/mission/mission_bounty_informant.stf', 19, 'target_hard_tatooine_1', 'The only other information I have right now is that your target was last tracked entering Tatooine space.'),
('string/en/mission/mission_bounty_informant.stf', 20, 'target_hard_yavin4_1', 'The only other information I have right now is that your target was last tracked entering Yavin IV space.'),
('string/en/mission/mission_bounty_informant.stf', 21, 'target_medium_1', 'The guild tells me you''re looking for someone. I''ve talked with my informants and sliced into the imperial holonet. Your target knows someone is after them and is making it difficult for me to keep track of them. I''ll upload their biological signature to your datapad so you can use probe droids to track them.'),
('string/en/mission/mission_bounty_informant.stf', 22, 'target_medium_2', 'Yeah, I know. You''re lookin'' for someone. Well, I can''t find ''em. Not entirely, anyway. I do have a bio-sig for ''em though. You kin use it with a probe droid if you kin spend the money.'),
('string/en/mission/mission_bounty_informant.stf', 23, 'target_medium_3', 'Why, oh why, does everyone always come to me? This is getting insupportable. Anyway, I can''t help you except for this bio-signature. Your quarry is making themselves as scarce as possible--they know you''re coming.'),
('string/en/mission/mission_bounty_informant.stf', 24, 'target_medium_4', 'You shouldn''t have dawdled. Your target knows you''re looking for them, and they''ve bolted. Here''s their bio-signature, and good luck.'),
('string/en/mission/mission_bounty_informant.stf', 25, 'target_medium_5', 'Your target is proving somewhat elusive. I believe they are still in the area, but you''ll need their bio-signature to track them down with a probe droid. Allow me to upload it to your datapad...'),
('string/en/mission/mission_bounty_informant.stf', 26, 'target_location_received', 'Target Waypoint Received.'),
('string/en/mission/mission_bounty_informant.stf', 27, 'informant_find_easier', 'I don''t deal with bounty hunters of your caliber. Go find a neophyte handler.'),
('string/en/mission/mission_bounty_informant.stf', 28, 'informant_find_harder', 'Woah! I''m not handling this case. Go find a more experienced handler.'),
('string/en/mission/mission_bounty_jedi.stf', 1, 'm1d', 'A bounty is hereby issued on the Jedi murderer of an innocent farming family on Naboo. Target is a Jedi and is thus high-threat. Take the proper precautions, but do not leave him alive.'),
('string/en/mission/mission_bounty_jedi.stf', 2, 'm1o', 'Jake the Fixer'),
('string/en/mission/mission_bounty_jedi.stf', 3, 'm1s', 'Client sends congratulations and their regards for a job well done.'),
('string/en/mission/mission_bounty_jedi.stf', 4, 'm1t', 'Vicious Jedi Murderer'),
('string/en/mission/mission_bounty_jedi.stf', 5, 'm1v', ''),
('string/en/mission/mission_bounty_jedi.stf', 6, 'm2d', 'When I was a kid, I was desperate to channel The Force.  All my friends made fun of me, but I was determined.  I stared for hours at an apple and attempted to levitate it through the air.  I failed, and failed, and failed again.\n\nNow, late in my life, I realize my foolishness.  I''m incredibly wealthy and a bit of a philanthropist.  I put up this reward as an impossible challenge.  I don''t believe Jedi or The Force actually exists.  They are stories told to the young and foolish.  Find and kill one, if you can. '),
('string/en/mission/mission_bounty_jedi.stf', 7, 'm2o', ''),
('string/en/mission/mission_bounty_jedi.stf', 8, 'm2s', 'Congratulations.  It seems I am proven wrong.  In the end, it is worth it.  I can begin the process of starting my force training again, and look forward one day becoming a Jedi myself.'),
('string/en/mission/mission_bounty_jedi.stf', 9, 'm2t', 'Jedi Identification'),
('string/en/mission/mission_bounty_jedi.stf', 10, 'm2v', ''),
('string/en/mission/mission_bounty_jedi.stf', 11, 'm3d', 'Recently, a man posing as a Jedi invaded the palace of my esteemed master.  While many believe him slain, I for one will never accept that he is gone.  I demand retribution for his injuries.\n\nI have come into some information that pinpoints his location.  Please take care of this problem for me.'),
('string/en/mission/mission_bounty_jedi.stf', 12, 'm3o', 'Anonymous'),
('string/en/mission/mission_bounty_jedi.stf', 13, 'm3s', 'While it seems that my information was incorrect, I''m happy to know you have rid the galaxy of one of these Jedi scum.  I will endeavor to locate my master?s assassin and contact you once I have further intel.'),
('string/en/mission/mission_bounty_jedi.stf', 14, 'm3t', 'Slay an evil Jedi assassin'),
('string/en/mission/mission_bounty_jedi.stf', 15, 'm3v', ''),
('string/en/mission/mission_bounty_jedi.stf', 16, 'm4d', 'I don''t care what the rumors are, Jedi were involved in the destruction of the orbiting base the Empire commissioned.  I had a contract to work on that station for the next 7 years, and now it''s gone.  I''ve got family to feed, no job, and no way to do it.  Do you think my wife stuck around to see if another job came through?  I''ll give you a guess...\n\nI''ve scraped together my life savings to take out the Jedi who ruined my life.  I don''t care what it takes; I''ve got nothing now.  Find this Jedi and kill him.  '),
('string/en/mission/mission_bounty_jedi.stf', 17, 'm4o', ''),
('string/en/mission/mission_bounty_jedi.stf', 18, 'm4s', 'Excellent work, a job well done.  Hard to believe I know, but I landed another job with the same contracting company on some kind of "secret" military project.  Combine that with my wife coming back home, and everything is going great for me.  I report to work in 6 weeks.  Wish me luck!  '),
('string/en/mission/mission_bounty_jedi.stf', 19, 'm4t', 'Contract Work Revenge'),
('string/en/mission/mission_bounty_jedi.stf', 20, 'm4v', ''),
('string/en/mission/mission_bounty_jedi.stf', 21, 'm5d', 'The Empire has no need of the ancient Jedi, no matter their political affiliation.  The Empire pays good credits for extinguishing the lives of this scum.  We''ve received word through our trusted informants of a Jedi hiding place.  We have heard you may be up for the challenge.  Can you be counted on?  The Empire needs such citizens working hard for peace and prosperity.'),
('string/en/mission/mission_bounty_jedi.stf', 22, 'm5o', ''),
('string/en/mission/mission_bounty_jedi.stf', 23, 'm5s', 'Excellent work.  The Empire has a new man we can trust.  Rest assured, we will call on you again when the situation presents itself.'),
('string/en/mission/mission_bounty_jedi.stf', 24, 'm5t', 'Restore Imperial Order'),
('string/en/mission/mission_bounty_jedi.stf', 25, 'm5v', ''),
('string/en/mission/mission_bounty_jedi.stf', 26, 'm6d', 'Jedi are supposed to protect the innocents of this galaxy against oppression.  In that they have failed.  A few weeks past, I was involved in a scuffle with some thugs over payment to one of the local swoop gangs.  Hey, we all have to make a living, right?  Those scum approached me on the street while I had my daughter with me!  Things got heated, and words were exchanged.  I pulled a blaster to show them I wasn''t having any of it.  The gang leader doesn''t even blink.  He laughs a second, pulls out his own blaster and starts shooting.  When it was over, my daughter lay dead in the street.  Security?  The only thing they have to say is "Move along."\n\nHow does this connect to the Jedi?  A Jedi watched the entire thing!  I signaled him a few times for help, but when blasters came out, that coward turned and left!  I want his blood for that.  '),
('string/en/mission/mission_bounty_jedi.stf', 27, 'm6o', ''),
('string/en/mission/mission_bounty_jedi.stf', 28, 'm6s', 'Hooray, the scum is dead.  Those types have no place in this universe.  Now my daughter can look on the face of her murderer with disgust herself.  '),
('string/en/mission/mission_bounty_jedi.stf', 29, 'm6t', 'Revenge for a lost child'),
('string/en/mission/mission_bounty_jedi.stf', 30, 'm6v', ''),
('string/en/mission/mission_bounty_jedi.stf', 31, 'number_of_entries', '6'),
('string/en/mission/mission_bounty_neutral_easy.stf', 1, 'm1d', 'A bounty is hereby issued on a pickpocket who chose a victim unwisely. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "One must select one''s victims with care. Some of them strike back."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 2, 'm1o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 3, 'm1s', 'Client sends congratulations and this message: "You did well, bounty hunter. It''s a shame to waste talent like yours on a lowlife like that."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 4, 'm1t', 'Unwise Pickpocket'),
('string/en/mission/mission_bounty_neutral_easy.stf', 5, 'm1v', 'A bounty hunter? You''ve gotta be kidding me! I''m a pickpocket, not a murderer!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 6, 'm2d', 'A bounty is hereby issued on a smuggler accused of spiriting a slave out of Hutt Space. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Shi''lax was the finest slave I ever owned. This will demonstrate how much I prized her."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 7, 'm2o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 8, 'm2s', 'Client sends congratulations and this message: "Excellent. Shi''lax will have no choice now but to return to my care."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 9, 'm2t', 'Slave Smuggler'),
('string/en/mission/mission_bounty_neutral_easy.stf', 10, 'm2v', 'Shi''lax does not deserve slavery! I''ll die to save her!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 11, 'm3d', 'A bounty is hereby issued on a renegade clone, suspected of forging identity credits. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "No clone is going to steal my identity. The masquerade ends now."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 12, 'm3o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 13, 'm3s', 'Client sends congratulations and this message: "It will be difficult to prove whether you killed the clone or the original, just as I planned it. Either way, of course, you get the bounty."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 14, 'm3t', 'Renegade Clone'),
('string/en/mission/mission_bounty_neutral_easy.stf', 15, 'm3v', 'No, wait, I''m not the clone! I''m the original!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 16, 'm4d', 'A bounty is hereby issued on a space scavenger known to violently extort junk buyers. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "There will be no salvaging you once this bounty hunter is finished!"'),
('string/en/mission/mission_bounty_neutral_easy.stf', 17, 'm4o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 18, 'm4s', 'Client sends congratulations and this message: "That''ll teach these spacer scum to tangle with honest, hardworking people!"'),
('string/en/mission/mission_bounty_neutral_easy.stf', 19, 'm4t', 'Dangerous Space Scavenger'),
('string/en/mission/mission_bounty_neutral_easy.stf', 20, 'm4v', 'Leave me alone! I ain''t got no fight with you, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 21, 'm5d', 'A bounty is hereby issued on a blockade runner wanted for smuggling spice through planetary blockades. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Backlane spice smugglers are a wupiupi a dozen. No sense capturing them when termination is just as easy."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 22, 'm5o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 23, 'm5s', 'Client sends congratulations and this message: "We appreciate your professionalism, bounty hunter. You are a vital element in any functional law enforcement system."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 24, 'm5t', 'Customs Runner'),
('string/en/mission/mission_bounty_neutral_easy.stf', 25, 'm5v', 'You''ll have to kill me, bounty hunter, ''cause I''m not coming with you!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 26, 'm6d', 'A bounty is hereby issued on a HoloNet pirate guilty of stealing private transmissions for purposes of blackmail. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "A person''s privacy should never be compromised. This bounty hunter will now explain the gravity of the crime of extortion."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 27, 'm6o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 28, 'm6s', 'Client sends congratulations and this message: "Invasion of privacy is a serious crime. Especially of my privacy. At least you, bounty hunter, know better than to ask too many questions."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 29, 'm6t', 'Holonet Pirate'),
('string/en/mission/mission_bounty_neutral_easy.stf', 30, 'm6v', 'I''m just a harmless data slicer! I don''t deserve this!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 31, 'm7d', 'A bounty is hereby issued on a glitterstim pusher responsible for the death of a prominent citizen''s son. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "You''ll never peddle your poison to anyone again. My son''s life is worth ten of yours, but I suppose I''ll have to be satisfied with one."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 32, 'm7o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 33, 'm7s', 'Client sends congratulations and this message: "My son can finally rest in peace. It''s good to know there are agents of justice whose services can be bought by determined citizens."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 34, 'm7t', 'Glitterstim Pusher'),
('string/en/mission/mission_bounty_neutral_easy.stf', 35, 'm7v', 'How was I supposed to know that stupid kid would take all of it at once? You can''t kill me because some glitterhead got careless!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 36, 'm8d', 'A bounty is hereby issued on a lowlife, guilty of cruelty to an innocent youngster. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "I warned my child to stay away from you. I was ignored, and the worst happened. Now it''s time to pay for your crimes."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 37, 'm8o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 38, 'm8s', 'Client sends congratulations and this message: "The memory of my child is no longer clouded by this dark chapter. My eternal thanks to the Bounty Hunters'' Guild."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 39, 'm8t', 'Cruel Misogynist'),
('string/en/mission/mission_bounty_neutral_easy.stf', 40, 'm8v', 'That teenager was crazy, I tell ya! How was I supposed to know the kid was suicidal? Gimme a break, will ya?'),
('string/en/mission/mission_bounty_neutral_easy.stf', 41, 'm9d', 'A bounty is hereby issued on a former executive of Corellia Technologies. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "This is what happens to embezzlers."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 42, 'm9o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 43, 'm9s', 'Client sends congratulations and this message: "If the slimeball carried any datadiscs, destroy them."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 44, 'm9t', 'Fugitive Technology Executive'),
('string/en/mission/mission_bounty_neutral_easy.stf', 45, 'm9v', 'I didn''t steal enough to be killed over! Anyway, whatever Corellia is paying you, I''ll double it!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 46, 'm10d', 'A bounty is hereby issued on a former chemist employed by Cassandran Distilleries. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Hope you enjoyed your last Cassandran Sunrise."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 47, 'm10o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 48, 'm10s', 'Client sends congratulations and this message: "Enjoy a drink on us."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 49, 'm10t', 'Alcohol Chemist'),
('string/en/mission/mission_bounty_neutral_easy.stf', 50, 'm10v', 'I never thought they''d kill me for stealing just one little distillation process!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 51, 'm11d', 'A bounty is hereby issued on the spouse of a deceased law enforcement officer. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Your beloved says one last hello."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 52, 'm11o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 53, 'm11s', 'Client sends congratulations and this message: "We all chipped in for this. Thanks for making sure our friend''s spirit can rest lightly now."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 54, 'm11t', 'Murderous Spouse'),
('string/en/mission/mission_bounty_neutral_easy.stf', 55, 'm11v', 'Oh no.  "Beloved," huh? Well, you can tell my "beloved''s" stinking friends that they never knew the evil heartbreaker I married!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 56, 'm12d', 'A bounty is hereby issued on the killer of several Rodian children. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Chordak of the Minos Cluster sends his regards."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 57, 'm12o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 58, 'm12s', 'Client sends congratulations and this message: "Chordak''s fifty-four surviving children thank you for avenging his terrible loss."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 59, 'm12t', 'Child Killer '),
('string/en/mission/mission_bounty_neutral_easy.stf', 60, 'm12v', 'Chordak is the Rodian pirate who attacked my ship. They killed everyone, but I escaped. I wanted revenge on Chordak. I was trying to kill him, not his kids!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_bounty_neutral_easy.stf', 61, 'm13d', 'A bounty is hereby issued on a citizen who has slandered the reputation of a good woman. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "You see? I''ve finally saved enough to buy my revenge."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 62, 'm13o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 63, 'm13s', 'Client sends congratulations and this message: "I''ve been waiting for this a very long time. I feel much better."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 64, 'm13t', 'Slanderous Gossip'),
('string/en/mission/mission_bounty_neutral_easy.stf', 65, 'm13v', 'That was twenty years ago! I can''t believe that incredible jerk is still angry about one indiscreet remark!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 66, 'm14d', 'A bounty is hereby issued on the killer of a beloved pet. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Tell that foul miscreant that I do not take lightly the cruel murder of my beloved Jotti!"'),
('string/en/mission/mission_bounty_neutral_easy.stf', 67, 'm14o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 68, 'm14s', 'Client sends this message: "Take your assassin''s fee and leave me to mourn my dear, vanished Jotti!"'),
('string/en/mission/mission_bounty_neutral_easy.stf', 69, 'm14t', 'Pet Killer'),
('string/en/mission/mission_bounty_neutral_easy.stf', 70, 'm14v', 'I didn''t kill her stupid voorpak! My pet graysor got loose and saw it running by. Attacking it was pure instinct. You''re working for an addled aristocrat with too much money and too few brain cells!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 71, 'm15d', 'A bounty is hereby issued on a proven industrial spy. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "You missed destroying one of our security cameras, Supervisor."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 72, 'm15o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 73, 'm15s', 'Client sends congratulations and this message: "Hyperdrive factories have good security. Pass the word."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 74, 'm15t', 'Hyperdrive Factory Spy'),
('string/en/mission/mission_bounty_neutral_easy.stf', 75, 'm15v', 'I -- I expected you, sooner or later. I''ve been living a nightmare ever since I stole those secrets. But I''m not going quietly!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 76, 'm16d', 'A bounty is hereby issued on a provocateur who attempted to foment unrest among factory droids. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Our company feels that certain important actions can never be left to droids -- as you are about to see."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 77, 'm16o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 78, 'm16s', 'Client sends congratulations and this message: "Droids are machines. That''s all."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 79, 'm16t', 'Agent Provocateur'),
('string/en/mission/mission_bounty_neutral_easy.stf', 80, 'm16v', 'I just wanted my company to treat its droid workers better. They want you to kill me just for that? Well, it''s not happening!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 81, 'm17d', 'A bounty is hereby issued on a fugitive sabacc hustler who has escaped planetary law enforcement. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "It''s too much effort to capture a simple hustler who escapes from jail. Termination is cheaper."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 82, 'm17o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 83, 'm17s', 'Client sends congratulations and this message: "Thank you. The planet has one less petty nuisance to deal with."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 84, 'm17t', 'Sabacc Hustler'),
('string/en/mission/mission_bounty_neutral_easy.stf', 85, 'm17v', 'Sithspit! I can''t believe you chased me this far over a couple of sabacc cheats!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 86, 'm18d', 'A bounty is hereby issued on a fugitive speeder thief who escaped from planetary law enforcement. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "You''re good at escaping our jail cells, but a stolen speeder won''t outrun a fair bounty."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 87, 'm18o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 88, 'm18s', 'Client sends congratulations and this message: "That one escaped us several times, but you are much more difficult to elude, bounty hunter. Good work."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 89, 'm18t', 'Speeder Thief'),
('string/en/mission/mission_bounty_neutral_easy.stf', 90, 'm18v', 'Listen, bounty hunter! I''ll get you a brand new flash speeder if you let me go!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 91, 'm19d', 'A bounty is hereby issued on a notorious brawler known to have drunkenly assaulted citizens in three settlements. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "If one is going to attack an innocent bystander in a cantina, make certain that one''s victim does not have the resources to arrange a payback."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 92, 'm19o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 93, 'm19s', 'Client sends congratulations and this message: "Bounty hunters make the galaxy safe for innocent bystanders. Thank you."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 94, 'm19t', 'Drunken Brawler'),
('string/en/mission/mission_bounty_neutral_easy.stf', 95, 'm19v', 'You''re the laser-brain they sent after me? Bring it on, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 96, 'm20d', 'A bounty is hereby issued on a confirmed moisture thief who has fled from Tosche Station on Tatooine. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Moisture farmers pool resources against someone who steals our harvests. You''ve run from us, but not far enough."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 97, 'm20o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 98, 'm20s', 'Client sends congratulations and this message: "Thank you, bounty hunter. You are a dealer of justice in this corrupt Empire."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 99, 'm20t', 'Moisture Thief'),
('string/en/mission/mission_bounty_neutral_easy.stf', 100, 'm20v', 'Moisture farmers "pooling" resources. Those dumb hicks probably didn''t even notice the pun.'),
('string/en/mission/mission_bounty_neutral_easy.stf', 101, 'm21d', 'A bounty is hereby issued on a droid rustler. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Binary load lifters may not be priceless, but steal too many of them and you make big trouble."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 102, 'm21o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 103, 'm21s', 'Client sends congratulations and this message: "Droids are good for manual labor. Bounties are best handled by skilled professionals. Nice work."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 104, 'm21t', 'Droid Rustler'),
('string/en/mission/mission_bounty_neutral_easy.stf', 105, 'm21v', 'You wouldn''t kill me over a couple of binary load lifters, would you?'),
('string/en/mission/mission_bounty_neutral_easy.stf', 106, 'm22d', 'A bounty is hereby issued on a lesai dealer who escaped from planetary authorities. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Lesai is not a petty drug. You are not a petty criminal. You''ve escaped for the last time."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 107, 'm22o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 108, 'm22s', 'Client sends congratulations and this message: "The drug lesai is a menace to decent communities. We thank you for bringing this criminal down."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 109, 'm22t', 'Lesai Dealer'),
('string/en/mission/mission_bounty_neutral_easy.stf', 110, 'm22v', 'I killed two security officers when I escaped, and I''m going to kill you, too!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 111, 'm23d', 'A bounty is hereby issued on a fugitive vandal with well-connected enemies. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Vandalism by laser fire is dangerous. Because you have eluded the authorities, we have arranged alternative punishment."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 112, 'm23o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 113, 'm23s', 'Client sends congratulations and this message: "The line between vandalism and arson is fine. You''ve removed a threat to the security of the planet. Thank you."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 114, 'm23t', 'Fugitive Vandal'),
('string/en/mission/mission_bounty_neutral_easy.stf', 115, 'm23v', 'Son of a gundark! You found me!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 116, 'm24d', 'A bounty is hereby issued on a loan shark by an alliance of his debtors. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "Consider this payment in full."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 117, 'm24o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 118, 'm24s', 'Client sends congratulations and this message: "That''s one less menace to exploit the poor of this planet. Excellent work."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 119, 'm24t', 'Loan Shark'),
('string/en/mission/mission_bounty_neutral_easy.stf', 120, 'm24v', 'Oh ho, a bounty hunter! Think you''re tough enough to take me down?'),
('string/en/mission/mission_bounty_neutral_easy.stf', 121, 'm25d', 'A bounty is hereby issued by an anonymous group of surveyors on a violent claim jumper. Target is believed lightly armed and low-threat. The client requests this message be given to the target before termination: "It paid in the short term to rob honest surveyors, but only in the short term."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 122, 'm25o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_easy.stf', 123, 'm25s', 'Client sends congratulations and this message: "Surveyors should be able to ply their trade without facing blaster-wielding thieves. You''ve done a service to our profession."'),
('string/en/mission/mission_bounty_neutral_easy.stf', 124, 'm25t', 'Claim Jumper'),
('string/en/mission/mission_bounty_neutral_easy.stf', 125, 'm25v', 'Stop! Give me a head start and let''s make this a fair fight!'),
('string/en/mission/mission_bounty_neutral_easy.stf', 126, 'number_of_entries', '25'),
('string/en/mission/mission_bounty_neutral_hard.stf', 1, 'm1d', 'A bounty is hereby issued on the murderer of an innocent fish-farming family on Mon Calamari. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "There is always a bigger fish."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 2, 'm1o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 3, 'm1s', 'Client sends congratulations and this message: "The seas of Calamari are cleaner with the passing of this monster."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 4, 'm1t', 'Vicious Murderer'),
('string/en/mission/mission_bounty_neutral_hard.stf', 5, 'm1v', 'I thought those Mon Cals would lead me to their Knowledge Bank. I didn''t like killing them. I won''t like killing you either.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 6, 'm2d', 'A bounty is hereby issued on a felon who destroyed several laboratories on Mrlsst in the Mennaalii system. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "This is the fate of those who oppose the quest for knowledge."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 7, 'm2o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 8, 'm2s', 'Client sends congratulations and this message: "The quest for knowledge continues."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 9, 'm2t', 'Vandal of Mrlsst Laboratories'),
('string/en/mission/mission_bounty_neutral_hard.stf', 10, 'm2v', 'Those labs were developing a cloaking device to sell to the highest bidder! I saw the proposals myself! But this set them back, let me tell you! Haha!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 11, 'm3d', 'A bounty is hereby issued on a mercenary who led a notorious band of Gank killers on Nar Shaddaa, the Smugglers'' Moon in the Y''Toub system. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "Leyn Vanrel took over your gang. He sends his regards."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 12, 'm3o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 13, 'm3s', 'Client sends congratulations and this message: "Nicely done. You may want to look me up when next you''re on Nar Shaddaa. Lovely place, you''ll like it."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 14, 'm3t', 'Gank Assassin Leader'),
('string/en/mission/mission_bounty_neutral_hard.stf', 15, 'm3v', 'Why, that stinking --!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 16, 'm4d', 'In House Benelex you are not simply one of the finest bounty hunters in the galaxy; you are, as it were, part of a family. Our benevolent leader, Corvastan Benelex, recently escaped a scurrilous assassination attempt at his home on Paquallis III. This is heavy-handed work by our longtime rival, House Tresario. Now House Benelex offers you the chance to dispose of the assassin, prove your ability, and earn both our family''s gratitude and our generous bounty. Speak first to the target, saying: "Greetings from Corvastan Benelex."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 17, 'm4o', 'Benelex Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 18, 'm4s', 'Splendid fighting, executed with a true warrior''s grace. You will be welcome in the Benelex family when you are next on Paquallis III.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 19, 'm4t', 'Hired Assassin'),
('string/en/mission/mission_bounty_neutral_hard.stf', 20, 'm4v', 'Oh ho! He still lives, does he? More than I can say for you.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 21, 'm5d', 'The short history of House Neuvalis chronicles its steady rise to preeminence among bounty hunters. With the recent fracture in the Bounty Hunters'' Guild, House Neuvalis carries on its true spirit. You too may take up the torch by hunting the culprit behind an assassination attempt on Beldorian the Hutt on the desert world of Nam Chorios. This assassin is armed and extremely dangerous. Beldorian desires that you first speak these words: "Ah bah pwoodah ngallah dowaalaa!"'),
('string/en/mission/mission_bounty_neutral_hard.stf', 22, 'm5o', 'Neuvalis Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 23, 'm5s', 'Your exemplary performance reflects the highest standards of the fading Guild, and of House Neuvalis as it carries forward the cause. Spread the news of our high aspirations!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 24, 'm5t', 'Failed Assassin of Beldorian the Hutt'),
('string/en/mission/mission_bounty_neutral_hard.stf', 25, 'm5v', 'You speak Huttese poorly.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 26, 'm6d', 'House Salaktori protects its high reputation as the galaxy''s oldest and greatest hunting guild. Recent fractures in the outmoded galaxy-wide Bounty Hunters'' Guild have encouraged rival houses to attack our members. By House policy, we avenge these offenses within no more than one standard year. One assassin has escaped vengeance, and the deadline approaches. We offer you this chance to earn our favor by killing this resilient quarry.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 27, 'm6o', 'Salaktori Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 28, 'm6s', 'House Salaktori gratefully receives this favor. For your efforts in protecting our high reputation we award this bounty.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 29, 'm6t', 'Assassin of House Salaktori Member'),
('string/en/mission/mission_bounty_neutral_hard.stf', 30, 'm6v', 'You don''t even look like a Salaktori. They must be getting desperate now.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 31, 'm7d', 'A bounty is hereby issued on the destroyer of an orbital mining facility near Ord Mantell in the Bright Jewel system. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "You destroyed my livelihood; now I destroy your life."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 32, 'm7o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 33, 'm7s', 'Client sends congratulations and this message: "Indiscriminate destruction gives bounty hunting a bad name."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 34, 'm7t', 'Ord Mantell Saboteur'),
('string/en/mission/mission_bounty_neutral_hard.stf', 35, 'm7v', 'I''m a hunter too. My target was on that mining station, so I blew it up. Now I have to take you out too.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 36, 'm8d', 'A bounty is hereby issued on a propagandist who spreads despicable lies about Imperial practices on the Core World Ralltiir. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "Victory is ours. All will join us."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 37, 'm8o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 38, 'm8s', 'Client sends congratulations and this message: "The propagandist''s data has now been destroyed. All is well."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 39, 'm8t', 'Ralltiir Anti-Imperial Progagandist'),
('string/en/mission/mission_bounty_neutral_hard.stf', 40, 'm8v', 'I''ve got holos showing the Empire''s press gangs, puppet military tribunals, and savage atrocities. I won''t let you stop me from spreading the truth.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 41, 'm9d', 'A bounty is hereby issued on a known blackmailer from Coruscant. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "We found you again. Keep running, and we''ll keep finding you."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 42, 'm9o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 43, 'm9s', 'Client sends congratulations and this message: "Just an outworld hick who tried to score big in the big city. Never stood a chance."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 44, 'm9t', 'Coruscant Blackmailer'),
('string/en/mission/mission_bounty_neutral_hard.stf', 45, 'm9v', 'Aah! How did you find me? I apologized a million times already! I''m no threat to anyone on the throneworld! You just never! Give! Up!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 46, 'm10d', 'A bounty is hereby issued on an assassin formerly employed by the Black Sun criminal organization. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "I''m sending you to meet your old Vigo."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 47, 'm10o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 48, 'm10s', 'Client sends congratulations and this message: "Your success is proof that our employee was not sufficiently qualified."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 49, 'm10t', 'Black Sun Rogue Assassin'),
('string/en/mission/mission_bounty_neutral_hard.stf', 50, 'm10v', 'I don''t think so.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 51, 'm11d', 'A bounty is hereby issued on a notorious murderer known as "the Vibro-Dagger Killer." Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "At last all your innocent victims will be avenged."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 52, 'm11o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 53, 'm11s', 'Client sends congratulations and this message: "If that wasn''t the true Vibro-Dagger Killer, you have still done the galaxy a service by removing the copy."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 54, 'm11t', 'Vibro-Dagger Killer'),
('string/en/mission/mission_bounty_neutral_hard.stf', 55, 'm11v', 'You really think I''m the Killer? That''s funny. It was convenient to copy his methods, that''s all. Here, I''ll show you.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 56, 'm12d', 'A bounty is hereby issued on a thief who stole 20 million credits from the Corellian Merchant Bank. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "Your scheme was hopeless. You are hopeless. Goodbye."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 57, 'm12o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 58, 'm12s', 'Client sends congratulations and this message: "For reference, the lunatic''s figures for Star Destroyer construction were wildly inaccurate."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 59, 'm12t', 'Corellian Merchant Bank Robber'),
('string/en/mission/mission_bounty_neutral_hard.stf', 60, 'm12v', 'So I wanted to build my own Star Destroyer. Is that wrong? I think I could have done it with another 25 million credits!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 61, 'm13d', 'A bounty is hereby issued on the head of a hunting organization that poached wildlife in the Asaari Woods of Bimmisaari in the Saari Ha system. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "We do this to protect the pallid leaf-nose batavian from extinction."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 62, 'm13o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 63, 'm13s', 'Client sends congratulations and this message: "Unfortunately, stupid and short-sighted people seem never to be in danger of extinction."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 64, 'm13t', 'Bimmisaari Poacher'),
('string/en/mission/mission_bounty_neutral_hard.stf', 65, 'm13v', 'What about folks just trying to make a living, huh? We''re in danger of extinction too! But I''m not going extinct without a fight!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 66, 'm14d', 'A bounty is hereby issued on a saboteur who attempted to blow up the Imperial Dam on Duro in the Duros system. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "You should have chosen a stay at the Imperial Reprogramming Institute."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 67, 'm14o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 68, 'm14s', 'Client sends congratulations and this message: "The Imperial Dam still stands. Victory is inevitable. All will join us."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 69, 'm14t', 'Saboteur of Imperial Dam on Duro'),
('string/en/mission/mission_bounty_neutral_hard.stf', 70, 'm14v', 'The Empire turned Duro''s ecosystem into a toxic waste dump. I wanted to strike a blow -- and I still can! You won''t stop me!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 71, 'm15d', 'The Mantis Syndicate offers an opportunity to talented hunters! A notorious thief has purloined valuable industrial secrets on Kessel. Termination must be swift and total, and all datadiscs and other information media on the body must be destroyed. Perform well to earn the Mantis Syndicate''s generous favor!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 72, 'm15o', 'Mantis Bounty Hunter Syndicate'),
('string/en/mission/mission_bounty_neutral_hard.stf', 73, 'm15s', 'The Mantis Syndicate pays you this generous bounty and wishes you the best of luck in future hunts.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 74, 'm15t', 'Thief of Kessel Industrial Secrets'),
('string/en/mission/mission_bounty_neutral_hard.stf', 75, 'm15v', 'I stole the genetic code of Kessel''s glitterstim spiders! We can break the spice monopoly! What? Not interested? Bounty hunters -- you''re all alike!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 76, 'm16d', 'House Tresario controls all bounties relevant to the world Baradas II. Our guild diligently defends its established territory. An interloper from House Benelex has attempted to offer bounties on various criminals active on our territory. House Tresario wishes you to locate and delete this would-be rival. Be warned that the target is extremely dangerous.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 77, 'm16o', 'House Tresario Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 78, 'm16s', 'House Tresario offers generous terms and excellent treatment, in contrast to House Benelex. We hope to work with you again.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 79, 'm16t', 'Unauthorized Bounty Provider on Baradas II'),
('string/en/mission/mission_bounty_neutral_hard.stf', 80, 'm16v', 'You think you can take me, eh?'),
('string/en/mission/mission_bounty_neutral_hard.stf', 81, 'm17d', 'I offer greetings from the illustrious Lord Jabba the Hutt. During a party recently in my master''s palace on Tatooine, a drunken smuggler made intemperate remarks about Lord Jabba''s appearance. Lord Jabba took grave offense. To date I have dispatched several bounty hunters of increasing skill to teach this offender a painful lesson. In each case the villain escaped, always with increasingly rude remarks concerning my master. Daily Lord Jabba''s matchless anger grows. It now falls to you to terminate this wily and well-armed offender.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 82, 'm17o', 'Bib Fortuna, Lord Jabba''s Majordomo'),
('string/en/mission/mission_bounty_neutral_hard.stf', 83, 'm17s', 'Lord Jabba sends his regards.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 84, 'm17t', 'Insulter of Lord Jabba the Hutt'),
('string/en/mission/mission_bounty_neutral_hard.stf', 85, 'm17v', 'Another one. If this goes on, I''m gonna make that bloated worm eat his own tail.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 86, 'm18d', 'A bounty is hereby issued on a confidence man accused of defrauding millions of credits from victims across the galaxy. Target is believed to be extremely intelligent, heavily armed, and high-threat. The client requests this message be given to the target before termination: "You''ve got a quick wit, but not quicker than this bounty hunter''s trigger finger."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 87, 'm18o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 88, 'm18s', 'Client sends congratulations and this message: "Thank you, bounty hunter. You don''t know how many humiliated victims will celebrate this news."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 89, 'm18t', 'Galactic Con Man'),
('string/en/mission/mission_bounty_neutral_hard.stf', 90, 'm18v', 'I thought you''d never catch up to me, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 91, 'm19d', 'A bounty is hereby issued on a notorious professional assassin, implicated in more than two dozen executions in the Core Worlds. Target is believed to be heavily armed, high-threat, and traveling in disguise. The client requests this message be given to the target before termination: "You''re one of the best, but we hired someone better."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 92, 'm19o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 93, 'm19s', 'Client sends congratulations and this message: "That assassin was the best we ever hired. Next to you, that is. Perhaps we''ll be in touch again."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 94, 'm19t', 'Notorious Assassin'),
('string/en/mission/mission_bounty_neutral_hard.stf', 95, 'm19v', 'Great. Another bounty hunter. Back off while you can, friend.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 96, 'm20d', 'A bounty is hereby issued on a freelance spymaster and architect of countless espionage and sabotage schemes. Target is believed heavily armed, high-threat, and aware of this bounty. Extreme caution is warranted. The client requests this message be given to the target before termination: "Time to blow your cover."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 97, 'm20o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 98, 'm20s', 'Client sends congratulations and this message: "Your target''s plots killed dozens and brought down many powerful regimes. Three bounty hunters were killed before you succeeded. You''re among the best at what you do."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 99, 'm20t', 'Freelance Spymaster'),
('string/en/mission/mission_bounty_neutral_hard.stf', 100, 'm20v', 'You''re quite skilled at pursuit. Too bad I have to kill you now.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 101, 'm21d', 'A bounty is hereby issued on a mercenary general, wanted for atrocities in four sectors. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "Mercenaries have no friends, only clients and enemies. Both of them want to see you dead."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 102, 'm21o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 103, 'm21s', 'Client sends congratulations and this message: "The general''s atrocities were legendary. You have rid the galaxy of a terrible scourge."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 104, 'm21t', 'Mercenary General'),
('string/en/mission/mission_bounty_neutral_hard.stf', 105, 'm21v', 'I knew they''d send a hunter to do their dirty work. But you never met a mark like me!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 106, 'm22d', 'A bounty is hereby issued on a rogue bounty hunter, accused of abetting the escape of a high-priced target and betraying an honest client. Target is heavily armed and expert in hunting techniques. Proceed with utmost caution. The client advises against speaking to the target before termination.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 107, 'm22o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 108, 'm22s', 'Client sends congratulations and this message: "Conscience is a detriment to a bounty hunter. We''re glad you, at least, understand that."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 109, 'm22t', 'Rogue Bounty Hunter'),
('string/en/mission/mission_bounty_neutral_hard.stf', 110, 'm22v', 'I know your work. You''re good. So I''ll give you one chance to forget that you found me.'),
('string/en/mission/mission_bounty_neutral_hard.stf', 111, 'm23d', 'A bounty is hereby issued on an elite slicer guilty of invading classified data systems in twelve sectors. Target is believed heavily armed and high-threat, and is known to monitor shuttle and spaceport logs to elude pursuers. The client requests this message be given to the target before termination: "It''s time to log you out."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 112, 'm23o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 113, 'm23s', 'Client sends congratulations and this message: "Slicers think it''s all fun and games, but this one compromised data that could endanger the lives of our operatives. You have demonstrated the seriousness of the crime. Thank you."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 114, 'm23t', 'Elite Slicer'),
('string/en/mission/mission_bounty_neutral_hard.stf', 115, 'm23v', 'You can''t have found me! It''s inconceivable!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 116, 'm24d', 'A bounty is hereby issued on a former intelligence agent for an outlying star system, who is now a consultant to enemies of the planetary government. Target is believed heavily armed, extremely dangerous, and capable of detecting pursuit. The client requests this message be given to the target before termination: "Consider this your authorization for retirement."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 117, 'm24o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 118, 'm24s', 'Client sends congratulations and this message: "Some professions demand a lifelong commitment. Don''t you agree, bounty hunter?"'),
('string/en/mission/mission_bounty_neutral_hard.stf', 119, 'm24t', 'Corrupt Intelligence Agent'),
('string/en/mission/mission_bounty_neutral_hard.stf', 120, 'm24v', 'Finally caught up to me, eh? Too bad I''m your last mark, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 121, 'm25d', 'A bounty is hereby issued on a fugitive pirate captain accused of betraying a loyal crew. Target is believed heavily armed and high-threat. The client requests this message be given to the target before termination: "You accused us of mutiny once. See what happens when we get really angry?"'),
('string/en/mission/mission_bounty_neutral_hard.stf', 122, 'm25o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_hard.stf', 123, 'm25s', 'Client sends congratulations and this message: "That space scum marooned us on an asteroid. Killing was almost too merciful, but we wanted this to be over once and for all. Thanks for the good work."'),
('string/en/mission/mission_bounty_neutral_hard.stf', 124, 'm25t', 'Fugitive Pirate Captain'),
('string/en/mission/mission_bounty_neutral_hard.stf', 125, 'm25v', 'Think you''re a match for me, hunter? Show me what you''ve got!'),
('string/en/mission/mission_bounty_neutral_hard.stf', 126, 'number_of_entries', '25'),
('string/en/mission/mission_bounty_neutral_medium.stf', 1, 'm1d', 'A bounty is hereby issued on a murderer who poisoned a noted Corporate States executive. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Those were not good mints."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 2, 'm1o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 3, 'm1s', 'Client sends congratulations and this message: "Carmellian mints are now banned from this household."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 4, 'm1t', 'Mint Poisoner'),
('string/en/mission/mission_bounty_neutral_medium.stf', 5, 'm1v', 'I swear that box of Carmellian mints wasn''t poisoned. I warned that executive, if you eat too many mints, you get nausea. But nooo! Well, I''m not going gently!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 6, 'm2d', 'A bounty is hereby issued on a renegade clan councillor from an outlying system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You have evaded your responsibility too long."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 7, 'm2o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 8, 'm2s', 'Client sends congratulations and this message: "The ways of our people have lasted long and will endure still longer."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 9, 'm2t', 'Renegade Clan Official'),
('string/en/mission/mission_bounty_neutral_medium.stf', 10, 'm2v', 'One of the five on our head clan council died. So we four survivors were all supposed to march into the desert and die. I won''t die just because she did!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 11, 'm3d', 'A bounty is hereby issued on the vandal who defaced the tomb of a great business executive from Sacorria, an Outlier system in the Corellian sector. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "When you toppled the grave marker of Silmas Monder, you should have started carving your own."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 12, 'm3o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 13, 'm3s', 'Client sends congratulations and this message: "This mentally disturbed individual believed that everyone on Sacorria was involved in some massive conspiracy. Very sad."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 14, 'm3t', 'Vandal of Corellian Gravesite'),
('string/en/mission/mission_bounty_neutral_medium.stf', 15, 'm3v', 'I strafed Sacorria''s moon, Sarcophagus. The whole moon is their graveyard. All those Sacorrians deserve much worse. So do you!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 16, 'm4d', 'A bounty is hereby issued on a confidence artist who defrauded the queen of the Hunchuzuc Den on Selonia in the Corellian system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "The queen is not trifled with."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 17, 'm4o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 18, 'm4s', 'Client sends congratulations and this message: "Dishonorable deception can have only one punishment."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 19, 'm4t', 'Con Artist Fleeing Selonia'),
('string/en/mission/mission_bounty_neutral_medium.stf', 20, 'm4v', 'Hey, the Hunchuzuc queen wanted power over the planet. I just said I could get her some weapons. Like this one.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 21, 'm5d', 'A bounty is hereby issued on an industrial spy who stole schematics from the SoroSuub headquarters on Sullust. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "To attack SoroSuub is to attack all of Sullust."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 22, 'm5o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 23, 'm5s', 'Client sends congratulations and this message: "The wealth of Sullust depends on the well-being of the SoroSuub conglomerate. You may tell this to anyone as you see fit."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 24, 'm5t', 'SoroSuub Thief'),
('string/en/mission/mission_bounty_neutral_medium.stf', 25, 'm5v', 'So I stole some plans. If you think you''re gonna kill me over a schematic, think again.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 26, 'm6d', 'A bounty is hereby issued on the sniper who fired on members of a marching band during intermission at the Planetary Shockball League quarter-finals in Coronet on Corellia. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Your lunatic conduct was an offense against good sportsmanship."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 27, 'm6o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 28, 'm6s', 'Client sends congratulations and this message: "After recent rehearsals the band sounds better than ever."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 29, 'm6t', 'Crazed Sniper'),
('string/en/mission/mission_bounty_neutral_medium.stf', 30, 'm6v', 'I couldn''t stand it! They started playing the "Imperial March" over and over, and I''m just! So! Sick of it!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 31, 'm7d', 'A bounty is hereby issued on the assassin who shot a Zaltin Corporation executive on Thyferra in the Polith system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Death to Black Claw terrorists."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 32, 'm7o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 33, 'm7s', 'Client sends congratulations and this message: "For the sake of stability in the vital bacta trade, ignore everything the target may have said."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 34, 'm7t', 'Assassin of Bacta Cartel Executive'),
('string/en/mission/mission_bounty_neutral_medium.stf', 35, 'm7v', 'I''m not with Black Claw. I was hired by Zaltin''s competitor, Xucphra. Not that you''ll live to tell anyone.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 36, 'm8d', 'A bounty is hereby issued on a saboteur who destroyed a thoroughbred racing-blob stable at Fondine Blob Raceways on Umgul. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Umglateen Protoplasm Stables has found you at last."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 37, 'm8o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 38, 'm8s', 'Client sends congratulations and this message: "All the blobs have now painstakingly separated themselves."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 39, 'm8t', 'Racing-Blob Stable Saboteur'),
('string/en/mission/mission_bounty_neutral_medium.stf', 40, 'm8v', 'The guy who hired me never even paid for the job. Not my smoothest move. I''ll bet this won''t be either.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 41, 'm9d', 'A bounty is hereby issued on an assassin who murdered an Ororo Transportation shipping executive in the Lybeya system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You hopeless idiot."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 42, 'm9o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 43, 'm9s', 'Client sends congratulations and this message: "Even more hopelessly idiotic than we''d expected."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 44, 'm9t', 'Assassin of Ororo Transport Executive'),
('string/en/mission/mission_bounty_neutral_medium.stf', 45, 'm9v', 'That lousy huckster charged me triple at his cantina in the Vergesso Asteroids. I was drunk and got carried away. But right now I''m sober, so --'),
('string/en/mission/mission_bounty_neutral_medium.stf', 46, 'm10d', 'A bounty is hereby issued on the assassin who attempted murder on a family member of the Imperial governor of Garos IV. Target is believed moderately armed and medium-threat. The client has not specified a message to be given to the target.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 47, 'm10o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 48, 'm10s', 'Client sends congratulations and this message: "I ask your discretion regarding any information you may have learned about my daughter''s activities."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 49, 'm10t', 'Garos IV Would-Be Assassin'),
('string/en/mission/mission_bounty_neutral_medium.stf', 50, 'm10v', 'The governor''s daughter works for the Rebels, and the Empire hired me to get her. I missed. I won''t miss this time.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 51, 'm11d', 'A bounty is hereby issued on the assassin of an executive of the Ororo Transportation shipping company. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "We know who employed you. We will take care of them as we take care of you."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 52, 'm11o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 53, 'm11s', 'Client sends congratulations and this message: "Xizor Transport Systems, our competitor, appears to have a longer reach than we suspected. We may have further assignments for you, pending investigation."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 54, 'm11t', 'Assassin of Ororo Transport Exec'),
('string/en/mission/mission_bounty_neutral_medium.stf', 55, 'm11v', 'Hmph. If they think they can dispose of Xizor Transport by hiring some amoral bounty hunter, they''re in for a surprise. You, too!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 56, 'm12d', 'A bounty is hereby issued on a fugitive convicted of spreading sedition at the Military Academy on Chandrila. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Victory is ours. All have joined the Empire."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 57, 'm12o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 58, 'm12s', 'Client sends congratulations and this message: "Sedition is a weed, which must be uprooted lest it spread uncontrolled."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 59, 'm12t', 'Seditious Agent at Chandrila'),
('string/en/mission/mission_bounty_neutral_medium.stf', 60, 'm12v', 'The Empire''s "military discipline" is blind obedience. Senator Mon Mothma was right! The Empire must be stopped!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 61, 'm13d', 'A bounty is hereby issued on a pirate captain based on the notorious world of Carratos in the O''pahz system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Carratos has enough guns already."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 62, 'm13o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 63, 'm13s', 'Client sends congratulations and this message: "That pirate has been running weapons in Chofin Settlement. We control that trade now."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 64, 'm13t', 'Carratos Pirate Captain'),
('string/en/mission/mission_bounty_neutral_medium.stf', 65, 'm13v', 'Enough guns? No such thing.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 66, 'm14d', 'A bounty is hereby issued on the spy who attempted to steal weapon schematics from the Imperial Military Academy on Carida in the Caridan system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Consider this a failing grade."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 67, 'm14o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 68, 'm14s', 'Client sends congratulations and this message: "We are now interrogating all students to determine internal security threats."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 69, 'm14t', 'Imperial Academy Spy'),
('string/en/mission/mission_bounty_neutral_medium.stf', 70, 'm14v', 'I wasn''t much interested in military service anyway.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 71, 'm15d', 'A bounty is hereby issued on a smuggler who brought illegal weapons onto Bonadan in defiance of Corporate Sector Authority laws. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "The protocol droid was a clever idea, but not clever enough."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 72, 'm15o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 73, 'm15s', 'Client sends congratulations and this message: "Bonadan security now scans all droids for concealed explosives."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 74, 'm15t', 'Bonadan Weapon Smuggler'),
('string/en/mission/mission_bounty_neutral_medium.stf', 75, 'm15v', 'That droid hated me putting that thermal detonator in his head. Heh.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_bounty_neutral_medium.stf', 76, 'm16d', 'A bounty is hereby issued on the murderer of a Tibanna gas prospector on the gas giant Bespin. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Baron Calrissian intensely dislikes claim jumpers."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 77, 'm16o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 78, 'm16s', 'Client sends congratulations and this message: "It looks like this was a net loss for everyone but you."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 79, 'm16t', 'Murderer of Tibanna Gas Prospector'),
('string/en/mission/mission_bounty_neutral_medium.stf', 80, 'm16v', 'Huh! It probably cost Calrissian more to hire you than I made off that guy''s claim.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 81, 'm17d', 'A bounty is hereby issued on the thief of a cargo freighter of diamonds mined outside Trade City on Arkania in the Perave system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Bright and many-faceted are the minds of Arkania."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 82, 'm17o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 83, 'm17s', 'Client sends congratulations and this message: "The people of Arkania, the Yaka, delight in uncovering thieves."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 84, 'm17t', 'Arkanian Diamond Thief'),
('string/en/mission/mission_bounty_neutral_medium.stf', 85, 'm17v', 'Is that supposed to mean something? That freighter was full of ice. It all melted! Why did the Yaka put out a bounty on me?'),
('string/en/mission/mission_bounty_neutral_medium.stf', 86, 'm18d', 'A bounty is hereby issued on a treacherous Imperial supply officer. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You should know better than to fence Imperial goods in the open air, where any probot overhead can see you."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 87, 'm18o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 88, 'm18s', 'Client sends congratulations and this message: "That incompetent ruined our entire operation. Hope you don''t end up getting contracts on us too."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 89, 'm18t', 'Imperial Supply Officer'),
('string/en/mission/mission_bounty_neutral_medium.stf', 90, 'm18v', 'Okay, I stole those weapons -- but I didn''t do it alone! Let me go and I''ll tell you who else -- argh, I''m reasoning with a bounty hunter! Yaaah!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 91, 'm19d', 'A bounty is hereby issued on a crazed religious cultist. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "This is for the children you killed!"'),
('string/en/mission/mission_bounty_neutral_medium.stf', 92, 'm19o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 93, 'm19s', 'Client sends congratulations and this message: "This terrorist religious cult is spreading. Popular music is the gateway they use for recruitment. You''ll probably get more contracts like this."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 94, 'm19t', 'Crazed Cult Terrorist'),
('string/en/mission/mission_bounty_neutral_medium.stf', 95, 'm19v', 'I''m not a cultist! I only sold a song collection called "Advanced Explosives Handbook" by a band called Deeply Religious. Music! Why won''t you believe me! Arrrgh!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 96, 'm20d', 'A bounty is hereby issued on a felon who attempted to kidnap a wealthy Corellian. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You want that spice so bad? You''re going where it went."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 97, 'm20o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 98, 'm20s', 'Client sends congratulations and this message: "That''s the last loose end from that deal."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 99, 'm20t', 'Corellian Kidnapper'),
('string/en/mission/mission_bounty_neutral_medium.stf', 100, 'm20v', 'I just wanted him to tell me what he did with my goods. But I knew it would come down to him or me. And hunter, it won''t be me!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 101, 'm21d', 'A bounty is hereby issued on a manufacturer of dangerous illegal drugs. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Tweeny Fogg suggests you might have been more open to a fair bargain."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 102, 'm21o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 103, 'm21s', 'Client sends congratulations and this message: "This is just one more step in the plan. Expect more contracts shortly."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 104, 'm21t', 'Death Stick Manufacturer'),
('string/en/mission/mission_bounty_neutral_medium.stf', 105, 'm21v', 'Fogg? I never heard of no -- wait, is he that two-bit crimelord? Wants to muscle in on me, huh? I''ll show you --!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 106, 'm22d', 'A bounty is hereby issued on a procurer and distributor of dangerous illegal drugs. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Tweeny Fogg offered good terms. You don''t reject Tweeny Fogg."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 107, 'm22o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 108, 'm22s', 'Client sends congratulations and this message: "Another step in the plan. Expect more contracts shortly."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 109, 'm22t', 'Death Stick Distributor'),
('string/en/mission/mission_bounty_neutral_medium.stf', 110, 'm22v', '"Tweeny Fogg"? What kind of name is -- oh, wait, I remember. That little squirt wants to move in on this territory? Hah! You''re dead, creep!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 111, 'm23d', 'A bounty is hereby issued on a purveyor of dangerous illegal drugs. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You could have joined with Tweeny Fogg. Too bad for you."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 112, 'm23o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 113, 'm23s', 'Client sends congratulations and this message: "The plan continues. Expect more contracts shortly."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 114, 'm23t', 'Death Stick Pusher'),
('string/en/mission/mission_bounty_neutral_medium.stf', 115, 'm23v', 'Who''s Tweeny Fogg? You''re killing me because I turned down someone I never heard of? I don''t think so!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 116, 'm24d', 'A bounty is hereby issued on a political operative employed by a repressive Outer Rim government for purposes of torture and mayhem. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Ando Maguro sent me."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 117, 'm24o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 118, 'm24s', 'Client sends congratulations and this message: "That monster didn''t even remember me. Somehow I feel even worse. But you''ve made the galaxy safer today, believe me."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 119, 'm24t', 'Outer Rim Government Operative'),
('string/en/mission/mission_bounty_neutral_medium.stf', 120, 'm24v', 'Who''s Ando Maguro? Did he get hurt in a covert operation? He shouldn''t have been socializing with the wrong crowd. And neither should you.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 121, 'm25d', 'A bounty is hereby issued on a thief of Imperial secrets. This hunt is proceeding outside Imperial channels; discretion is essential. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Eisen Kerioth has dispensed with your informant."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 122, 'm25o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 123, 'm25s', 'Client sends congratulations and this message: "Moff Kerioth thanks you for your service. Tell no one of anything your target may have said, or you will be next."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 124, 'm25t', 'Thief of Government Secrets'),
('string/en/mission/mission_bounty_neutral_medium.stf', 125, 'm25v', 'What a jerk. Moff Kerioth''s Twi''lek slave woman begged me to help her escape. I tried and failed. Now he''s sent another jerk to kill me. Well....'),
('string/en/mission/mission_bounty_neutral_medium.stf', 126, 'm26d', 'A bounty is hereby issued on the organizer and leader of a covert species-ist hate society. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Did you think you could kill us all before we fought back?"'),
('string/en/mission/mission_bounty_neutral_medium.stf', 127, 'm26o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 128, 'm26s', 'Client sends congratulations and this message: "Please ignore the babbling of this obvious madman."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 129, 'm26t', 'Leader of Secret Hate-Crime Society'),
('string/en/mission/mission_bounty_neutral_medium.stf', 130, 'm26v', 'Which one of those unnatural monstrosities sent you? Don''t you know you''re only furthering the insidious Galactic Chiss Conspiracy? I must stop you!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 131, 'm27d', 'A bounty is hereby issued on the murderer of the captain of a Thyferran bacta tanker. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "The son of Captain Norda sends you on your way."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 132, 'm27o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 133, 'm27s', 'Client sends congratulations and this message: "My father wasn''t the best of all men, but he didn''t deserve murder."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 134, 'm27t', 'Murderer of Bacta Tanker Captain'),
('string/en/mission/mission_bounty_neutral_medium.stf', 135, 'm27v', 'The Empire loosed a plague on my homeworld. Captain Norda''s tanker held enough bacta to heal thousands, but thousands died! Because Norda feared the Empire! I killed him and I''m glad -- like I''m glad to do THIS!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 136, 'm28d', 'A bounty is hereby issued on an individual who aided the destruction of an Ubrikkian Luxury Sail Barge on Balmorra in the Nevoota system. Target is believed moderately armed and medium-threat. The client requests that no message be given to the target before termination, and that target''s remarks not be recorded.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 137, 'm28o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 138, 'm28s', 'Client sends this message: "Discretion is essential. Tell no one of the target''s words, or you will be next."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 139, 'm28t', 'Sail Barge Destroyer'),
('string/en/mission/mission_bounty_neutral_medium.stf', 140, 'm28v', '"Sail barge"? I led a strike team to destroy Governor Beltane''s shiny new SD-10 battle droid plant! You want to kill me? I don''t go easy.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 141, 'm29d', 'A bounty is hereby issued on a renegade scientist who engaged in unlicensed weather modification on Drall in the Corellian system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "The Boiling Sea is not filled by rainfall."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 142, 'm29o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 143, 'm29s', 'Client sends congratulations and this message: "The Boiling Sea boils once more."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 144, 'm29t', 'Weather Modification Scientist'),
('string/en/mission/mission_bounty_neutral_medium.stf', 145, 'm29v', 'I couldn''t stand the heat, so I made it rain. The sea stopped boiling, and that hurt the tourist trade. Is one mistake worth killing me over?'),
('string/en/mission/mission_bounty_neutral_medium.stf', 146, 'm30d', 'A bounty is hereby issued on the felon who committed an offense against the Trask merchant house on Kuat. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "The magenta sash is reserved for Trask alone."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 147, 'm30o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 148, 'm30s', 'Client sends congratulations and this message: "This removes from the Trask sash the contaminating stain of dishonor."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 149, 'm30t', 'Offender Against Kuat'),
('string/en/mission/mission_bounty_neutral_medium.stf', 150, 'm30v', 'Giving the people of Kuat those magenta sashes was the first symbolic step in encouraging rebellion. We''ll overthrow the aristocracy, then the Empire!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 151, 'm31d', 'A bounty is hereby issued on a notorious vandal who defaced a statue of the beloved Emperor. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "The Emperor is not mocked."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 152, 'm31o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 153, 'm31s', 'Client sends congratulations and this message: "Recount your exploit far and wide. Remember, the Emperor is never mocked."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 154, 'm31t', 'Traitorous Vandal'),
('string/en/mission/mission_bounty_neutral_medium.stf', 155, 'm31v', 'I painted his stupid face blue, the color of dishonor in my culture. I''ll keep doing it until freedom returns, and you won''t stop me!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 156, 'm32d', 'A bounty is hereby issued on the designer of a deadly bioweapon. Target is believed moderately armed and medium-threat. WARNING: If any biological material is found on the target, destroy it immediately.'),
('string/en/mission/mission_bounty_neutral_medium.stf', 157, 'm32o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 158, 'm32s', 'Client sends congratulations and this message: "If you made contact with the target''s bodily fluids, carry out decontamination procedures."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 159, 'm32t', 'Bioweapon Scientist'),
('string/en/mission/mission_bounty_neutral_medium.stf', 160, 'm32v', 'Hhkk! Kff! I''m going to -- to -- ahhhkk! Hkk!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 161, 'm33d', 'A bounty is hereby issued on the architect of a plan to overthrow a planetary government under the management of the Corporate Sector Authority. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "No more options for you."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 162, 'm33o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 163, 'm33s', 'Client sends congratulations and this message: "Termination is always a nasty business."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 164, 'm33t', 'CSA Would-Be Conqueror '),
('string/en/mission/mission_bounty_neutral_medium.stf', 165, 'm33v', 'You make it sound like I was conquering by force. I only tried to acquire a majority of stock. Executive politics shouldn''t involve physical death!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 166, 'm34d', 'A bounty is hereby issued on a gang enforcer wanted in a dozen Outer Rim sectors. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "How many innocent beings have suffered at your hands? This is for them!"'),
('string/en/mission/mission_bounty_neutral_medium.stf', 167, 'm34o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 168, 'm34s', 'Client sends congratulations and this message: "We''ve got bacta clinics full of that maggot''s victims. All of them thank you for ending the nightmare."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 169, 'm34t', 'Gang Enforcer'),
('string/en/mission/mission_bounty_neutral_medium.stf', 170, 'm34v', 'You''re good, bounty hunter, but not as good as me!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 171, 'm35d', 'A bounty is hereby issued on a serial blackmailer whose crimes span fifty sectors. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Consider this your retirement party."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 172, 'm35o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 173, 'm35s', 'Client sends congratulations and this message: "Thank you for eliminating that troublesome blackmailer. A number of quite influential galactic citizens have taken note of your good work."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 174, 'm35t', 'Serial Blackmailer'),
('string/en/mission/mission_bounty_neutral_medium.stf', 175, 'm35v', 'You bounty hunters never learn, do you?'),
('string/en/mission/mission_bounty_neutral_medium.stf', 176, 'm36d', 'A bounty is hereby issued on an infamous starjacker who robbed the wrong space yacht. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "We warned you never to set foot on an inhabited planet."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 177, 'm36o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 178, 'm36s', 'Client sends congratulations and this message: "A smart starjacker will avoid certain targets. This one was not very smart. You have earned the bounty."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 179, 'm36t', 'Infamous Starjacker'),
('string/en/mission/mission_bounty_neutral_medium.stf', 180, 'm36v', 'You''re good at tracking, but I''m good at fighting!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 181, 'm37d', 'A bounty is hereby issued on a Black Sun trigger artist wanted in seven sectors. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Your Vigo can''t protect you everywhere, but justice knows no bounds."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 182, 'm37o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 183, 'm37s', 'Client sends congratulations and this message: "We suspect a double-cross by Black Sun. Otherwise a trusted enforcer would not have been traveling alone. Thank you for helping us take advantage of that opportunity."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 184, 'm37t', 'Black Sun Trigger Artist'),
('string/en/mission/mission_bounty_neutral_medium.stf', 185, 'm37v', 'Sithspit! Where did you come from?'),
('string/en/mission/mission_bounty_neutral_medium.stf', 186, 'm38d', 'A bounty is hereby issued on a galactic desperado whose reputation is spreading like fire through the galaxy. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Some fine things have been laid upon your table, but you only want the ones that you can''t get. Why didn''t you come to your senses?"'),
('string/en/mission/mission_bounty_neutral_medium.stf', 187, 'm38o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 188, 'm38s', 'Client sends congratulations and this message: "Justice was getting closer every day. It takes a certain kind of fool to keep running."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 189, 'm38t', 'Galactic Desperado'),
('string/en/mission/mission_bounty_neutral_medium.stf', 190, 'm38v', 'Let''s finish this! I ain''t getting'' no younger!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 191, 'm39d', 'A bounty is hereby issued on a space pirate wanted for stealing slaves in the Outer Rim. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You think you''re quite a hero. As of now you''re a martyr."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 192, 'm39o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 193, 'm39s', 'Client sends congratulations and this message: "Interfering with lawful business is bad for the galactic economy. We''re glad you concur with our goals, bounty hunter."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 194, 'm39t', 'Slave Pirate'),
('string/en/mission/mission_bounty_neutral_medium.stf', 195, 'm39v', 'Freedom for slaves across the galaxy!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 196, 'm40d', 'A bounty is hereby issued on a crystal thief who stole a shipload of Tasari shards. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You''re very good at running away, but you can''t outrun a price on your head."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 197, 'm40o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 198, 'm40s', 'Client sends congratulations and this message: "Crystal thieves may have a glamorous reputation, but they''re little more than ambitious burglars. That''s one less to plague the galaxy. The bounty is yours."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 199, 'm40t', 'Crystal Thief'),
('string/en/mission/mission_bounty_neutral_medium.stf', 200, 'm40v', 'Hold on! You''re throwing away a fortune here! Don''t be a fool!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 201, 'm41d', 'A bounty is hereby issued on an assassin suspected of several political murders in the Ottega system. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "We do not abide assassination, especially when the targets might have revealed sensitive information before they died. In such cases, termination must be swift."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 202, 'm41o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 203, 'm41s', 'Client sends congratulations and this message: "You have avenged many good political leaders. By chance did the assassin give you any information before he died?"'),
('string/en/mission/mission_bounty_neutral_medium.stf', 204, 'm41t', 'Suspected Assassin'),
('string/en/mission/mission_bounty_neutral_medium.stf', 205, 'm41v', 'Those sithspawn double-crossed me! They''ll double-cross you too, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 206, 'm42d', 'A bounty is hereby issued on a mercenary captain who is wanted for mass slaughter in four sectors. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "We will never forget your atrocities at the Third Reconciliation. This is for the Shubs and Zuuls!"'),
('string/en/mission/mission_bounty_neutral_medium.stf', 207, 'm42o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 208, 'm42s', 'Client sends congratulations and this message: "Many Shubs and Zuuls have been avenged this day, I can tell you."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 209, 'm42t', 'Mercenary Captain'),
('string/en/mission/mission_bounty_neutral_medium.stf', 210, 'm42v', 'I''ll see you in hell, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 211, 'm43d', 'A bounty is hereby issued on an informant who betrayed an employer''s secrets to the Empire. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You took a vow of secrecy. Now you shall pay the price for your lack of vision."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 212, 'm43o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 213, 'm43s', 'Client sends congratulations and this message: "Splendid work, bounty hunter. We trust the details of this incident will remain secret."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 214, 'm43t', 'Dangerous Informant'),
('string/en/mission/mission_bounty_neutral_medium.stf', 215, 'm43v', 'Don''t make me hurt you!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 216, 'm44d', 'A bounty is hereby issued on a fugitive slicer, convicted of forging credentials for Imperial data systems. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "The galaxy is not big enough to hide you forever."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 217, 'm44o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 218, 'm44s', 'Client sends congratulations and this message: "Slicers shouldn''t play around in the wrong sectors."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 219, 'm44t', 'Fugitive Slicer'),
('string/en/mission/mission_bounty_neutral_medium.stf', 220, 'm44v', 'I thought I''d lost you, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 221, 'm45d', 'A bounty is hereby issued on a renowned saboteur accused in the slaughter of a dozen shipyard workers. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You used thermal detonators. Your own demise will be much more painful."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 222, 'm45o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 223, 'm45s', 'Client sends congratulations and this message: "A lot of families were shattered by that vermin''s sabotage. You have earned their thanks as well as this bounty."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 224, 'm45t', 'Renowned Saboteur'),
('string/en/mission/mission_bounty_neutral_medium.stf', 225, 'm45v', 'No bounty hunter is taking me down!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 226, 'm46d', 'A bounty is hereby issued on an industrial spy, escaped from the custody of a private security force. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "You''re clever enough to slip away from us, but bounty hunters are cleverer still."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 227, 'm46o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 228, 'm46s', 'Client sends congratulations and this message: "Spies are never as clever as they think."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 229, 'm46t', 'Industrial Spy'),
('string/en/mission/mission_bounty_neutral_medium.stf', 230, 'm46v', 'That''s the last mistake you''ll ever make, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 231, 'm47d', 'A bounty is hereby issued on a dangerous prisoner who escaped a dungeon ship in Tragan Sector. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Escape is punishable by death."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 232, 'm47o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 233, 'm47s', 'Client sends congratulations and this message: "Why would a prisoner turn a life sentence into a death sentence? Criminals are beyond comprehension."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 234, 'm47t', 'Escaped Prisoner'),
('string/en/mission/mission_bounty_neutral_medium.stf', 235, 'm47v', 'Why can''t I shake you?'),
('string/en/mission/mission_bounty_neutral_medium.stf', 236, 'm48d', 'A bounty is hereby issued on a rogue scientist accused of illegal genetic experiments across the Outer Rim. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "Your despicable work ends now!"'),
('string/en/mission/mission_bounty_neutral_medium.stf', 237, 'm48o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 238, 'm48s', 'Client sends congratulations and this message: "Rogue science. An indelicate business."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 239, 'm48t', 'Rogue Scientist'),
('string/en/mission/mission_bounty_neutral_medium.stf', 240, 'm48v', 'You must not interfere with my important experiments!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 241, 'm49d', 'A bounty is hereby issued on a fence of stolen goods, wanted for possession of contraband in 17 systems. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "A single scum like you allows dozens of thieves and robbers to make a living in the galaxy. Time to kill the weed at the root."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 242, 'm49o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 243, 'm49s', 'Client sends congratulations and this message: "With that space leech out of the way, many more criminals will go out of business. You''ve earned this bounty."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 244, 'm49t', 'Interplanetary Fence'),
('string/en/mission/mission_bounty_neutral_medium.stf', 245, 'm49v', 'You don''t know who you''re playing with, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 246, 'm50d', 'A bounty is hereby issued on a fugitive kidnapper wanted for ransoming a wealthy Naboo child. Target is believed moderately armed and medium-threat. The client requests this message be given to the target before termination: "We don''t want the ransom back. We''ll take our revenge from your hide."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 247, 'm50o', 'Bounty Hunters'' Guild'),
('string/en/mission/mission_bounty_neutral_medium.stf', 248, 'm50s', 'Client sends congratulations and this message: "Our little daughter can sleep in peace now. Thank you."'),
('string/en/mission/mission_bounty_neutral_medium.stf', 249, 'm50t', 'Kidnapper-At-Large'),
('string/en/mission/mission_bounty_neutral_medium.stf', 250, 'm50v', 'Give me your best shot, bounty hunter!'),
('string/en/mission/mission_bounty_neutral_medium.stf', 251, 'number_of_entries', '50'),
('string/en/mission/mission_deliver_imperial_easy.stf', 1, 'm1d', 'This office has uncovered several Rebel sympathizers and is planning a purge. Rebel slicers are infesting the HoloNet, so we need these warrants hand-delivered. After all, we don''t want to give those scum the chance to escape justice. Tell no one!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 3, 'm1o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 4, 'm1r', 'Everything seems in order. Now we can move and purge those sympathizers.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 6, 'm1s', 'This office will remember your service to the Empire. The memory of the ISB is long and infallible.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 7, 'm1p', 'The Empire is always looking for dedicated citizens willing to serve. The rewards are many.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 8, 'm1t', 'Arrest Warrants'),
('string/en/mission/mission_deliver_imperial_easy.stf', 9, 'm2d', 'One of our spies, who are everywhere, is conducting an important surveillance mission. We''ve ordered the agent to maintain transmission silence. You never know who''s listening. These new orders must be delivered to the agent at once. Can the Empire count on you?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 11, 'm2o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 12, 'm2r', 'New orders, eh? Thank you, citizen. The Empire does not forget its loyal servants.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 14, 'm2s', 'Inform no one of the spy''s identity, or it will go badly for you. That is all.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 15, 'm2p', 'Our work is never done. Preserving the New Order should be everyone''s concern.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 16, 'm2t', 'Spy''s New Orders'),
('string/en/mission/mission_deliver_imperial_easy.stf', 17, 'm3d', 'We have a report that Rebels are meeting in a concealed chamber under an informant''s home. Deliver a heat sensor so the homeowner can verify this suspicion.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 18, 'm3l', 'Scanner device'),
('string/en/mission/mission_deliver_imperial_easy.stf', 19, 'm3o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 20, 'm3r', 'Finally! I''ll be able to prove that there''s a Rebel Command Center underneath my very home! How do you work this thing? '),
('string/en/mission/mission_deliver_imperial_easy.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 22, 'm3s', 'We must investigate all such claims, no matter how seemingly outlandish. That is our job -- our duty -- our cause.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 23, 'm3p', 'The ISB is always looking for bright, eager talent. What better way to serve the Empire?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 24, 'm3t', 'Heat Scanner'),
('string/en/mission/mission_deliver_imperial_easy.stf', 25, 'm4d', 'A citizen informs us that certain locals have been holding clandestine meetings, possibly to aid the Rebellion. Deliver this message to the loyal citizen. It includes a reward for diligence.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 27, 'm4o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 28, 'm4r', 'I knew my rude neighbors were up to no good. They''ll get what they deserve now. Bless the Empire! '),
('string/en/mission/mission_deliver_imperial_easy.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 30, 'm4s', 'Though Rebel sympathizers hide everywhere, assure all who will listen that the Empire has matters well in hand.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 31, 'm4p', 'We only wish all citizens were as loyal as the recipient of this datadisc -- and as loyal as you are, too, citizen!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 32, 'm4t', 'Loyalty Reward'),
('string/en/mission/mission_deliver_imperial_easy.stf', 33, 'm5d', 'An upstanding citizen believes an acquaintance is secretly attending meetings with Rebels. Deliver this tagger spy device to the informant. Once this citizen plants a transmitter on the suspected traitor, we can monitor his movements.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 34, 'm5l', 'Small gun or tracker device'),
('string/en/mission/mission_deliver_imperial_easy.stf', 35, 'm5o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 36, 'm5r', 'Great gadget. I could never afford this on my own. Now my father will regret stopping my allowance!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 37, 'm5f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 38, 'm5s', 'Rebel sympathizers are everywhere. Our informants'' motives may be petty, but their vital service triumphs over all other moral considerations.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 39, 'm5p', 'Traitors hide behind many facades. They may be close friends, even loved ones. In the end, all must face justice.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 40, 'm5t', 'Spy Tagger Device'),
('string/en/mission/mission_deliver_imperial_easy.stf', 41, 'm6d', 'One loyal citizen has helped us arrest over a dozen Rebel sympathizers. We want to show our appreciation by presenting them with a plaque. It bears the COMPNOR pledge along with the citizen''s name engraved on the front. Perhaps you can one day earn such a plaque, citizen. For now, please simply deliver the plaque.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 42, 'm6l', 'Plaque'),
('string/en/mission/mission_deliver_imperial_easy.stf', 43, 'm6o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 44, 'm6r', 'My plaque! I''ll hang it in a place of honor. I can''t wait to show my friends. The few remaining loyal ones, that is.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 45, 'm6f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 46, 'm6s', 'With continuing service to COMPNOR and the Empire, you, too, citizen, may someday merit a plaque of your own.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 47, 'm6p', 'The Empire shows its appreciation in many ways. This plaque is but one small example.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 48, 'm6t', 'COMPNOR Loyalty Plaque'),
('string/en/mission/mission_deliver_imperial_easy.stf', 49, 'm7d', 'A local school teacher wants to present a class of young students with COMPNOR badges. They reward students who memorize the COMPNOR creed. Could you deliver these badges? Children are the Empire''s future, after all. '),
('string/en/mission/mission_deliver_imperial_easy.stf', 50, 'm7l', 'Small sealed container'),
('string/en/mission/mission_deliver_imperial_easy.stf', 51, 'm7o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 52, 'm7r', 'The children will be delighted. Hail the Empire and COMPNOR.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 53, 'm7f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 54, 'm7s', 'Evidently no student successfully memorized the entire COMPNOR creed, so no badges were awarded at this time. This is acceptable; there are always more children.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 55, 'm7p', 'Nothing inspires a person more than happy, loyal children. Wouldn''t you agree, citizen?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 56, 'm7t', 'COMPNOR School Badges'),
('string/en/mission/mission_deliver_imperial_easy.stf', 57, 'm8d', 'A citizen has organized Neighborhood Rebel Alert Watches. We are so impressed with this that we''ve decided to adopt a similar model all across this sector. Please deliver this holocam recording to this model citizen. It''s a personal thanks from our Chairman. We want loyal citizens to know they are treasured.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 59, 'm8o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 60, 'm8r', 'Oh goodness, a personal thanks for me? I was just doing my civic duty. Thank you.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 61, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 62, 'm8s', 'The Neighborhood Rebel Watch Alert program will go worldwide shortly. Do you want to start your own Watch Alert program? If so, contact COMPNOR at the appropriate time.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 63, 'm8p', 'A vigilant citizen is a happy citizen. Are you happy?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 64, 'm8t', 'COMPNOR Holocam Thank-You'),
('string/en/mission/mission_deliver_imperial_easy.stf', 65, 'm9d', 'We offered a reward to a loyal citizen for years of service, and the citizen asked for a replica ISB uniform. We''ve cleared it with our superiors and need you to deliver the uniform. I must admit, our uniforms are quite sharp.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 66, 'm9l', 'ISB Uniform'),
('string/en/mission/mission_deliver_imperial_easy.stf', 67, 'm9o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 68, 'm9r', 'I can''t wait to try this on. My mate will be quite enthused to see me, I think. Thank you.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 69, 'm9f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 70, 'm9s', 'Of course the replica ISB uniform cannot be worn in public, on pain of prosecution for impersonating an officer. Did you inform the citizen of this vital fact?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 71, 'm9p', 'The Empire knows that style and fashion are important. We''re glad to see others agree.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 72, 'm9t', 'Replica ISB Uniform'),
('string/en/mission/mission_deliver_imperial_easy.stf', 73, 'm10d', 'Concerned citizens are staging a public rally to denounce the Rebellion and support the Empire. Deliver this miniature holoprojector to their leader. It will display recordings of heroic Imperial soldiers, as well as tasteful images of the atrocities perpetrated by Rebel terrorists. '),
('string/en/mission/mission_deliver_imperial_easy.stf', 74, 'm10l', 'Small projector'),
('string/en/mission/mission_deliver_imperial_easy.stf', 75, 'm10o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 76, 'm10r', 'This will make our rally so much better. Bless the Empire!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 77, 'm10f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 78, 'm10s', 'Thank you, citizen. The rally will proceed shortly, unless sabotaged by Rebel terrorists.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 79, 'm10p', 'Will you be attending this rally, citizen? It would look good on your record.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 80, 'm10t', 'Miniature Holoprojector'),
('string/en/mission/mission_deliver_imperial_easy.stf', 81, 'm11d', 'A group of children will be marching in a local parade honoring the Emperor. The citizens putting this together have requested proper Imperial attire and toy blasters for the children. Deliver this requisition order to the lead organizer. Any official can take this to the local Imperial depot to request these materials.  '),
('string/en/mission/mission_deliver_imperial_easy.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 83, 'm11o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 84, 'm11r', 'Our children will look so sharp. They will be a credit to the Empire.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 85, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 86, 'm11s', 'Did you inform the organizers that firing the toy blasters can, in certain circumstances, blind or maim the target? This is a design flaw that will be corrected in later versions.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 87, 'm11p', 'We admire the children''s enthusiasm. If only all citizens were so enthusiastic, the galaxy would be a better place.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 88, 'm11t', 'Toy Blaster Requisition'),
('string/en/mission/mission_deliver_imperial_easy.stf', 89, 'm12d', 'We''ve heard that the loyal local citizens are putting on a parade in honor of the Emperor. We''re recording this event for HoloNet broadcast. Deliver this requisition order for five RMD-20 monitoring droids to this group''s representatives. They can take it to their local Imperial depot to get the droids. '),
('string/en/mission/mission_deliver_imperial_easy.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 91, 'm12o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 92, 'm12r', 'These droids will come in handy. Our children will be so pleased when this is recorded for all the Empire to see!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 94, 'm12s', 'The assigned monitor droids are currently in use at local cantinas, but they should be available in time for the parade. Fine work, citizen!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 95, 'm12p', 'Let these children be an example to you, citizen. Strive to serve the Empire.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 96, 'm12t', 'Monitor Droid Requisition'),
('string/en/mission/mission_deliver_imperial_easy.stf', 97, 'm13d', 'Someone has been defacing Imperial statuary. The vandals don''t appear on our monitoring devices. We suspect some form of holoshroud. Deliver this new neuro-sensor to our agent. It should detect holoshrouds. We will discover the vandals and put a stop to them.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 98, 'm13l', 'Scanner device'),
('string/en/mission/mission_deliver_imperial_easy.stf', 99, 'm13o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 100, 'm13r', 'I''ll catch these vandals one way or another. This device will be an immense help.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 101, 'm13f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 102, 'm13s', 'The scanner has not yet detected the distinctive holoshroud radiation signature, but it is only a matter of time. What else could explain this weird phenomenon?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 103, 'm13p', 'To deface Imperial property is a serious crime. We''ll make that clear to these criminals soon enough.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 104, 'm13t', 'Neuro-Sensor Scanner'),
('string/en/mission/mission_deliver_imperial_easy.stf', 105, 'm14d', 'Rebel spies stole a loyal citizen''s speeder. Due to the owner''s modifications to the speeder, we caught these spies within a few hours. As a public relations gesture, deliver this Corporate Sector Authority voucher, which gives a generous discount on the purchase of any new swoop.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 107, 'm14o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 108, 'm14r', 'Ten percent off. Well. It sure pays to serve the Empire, huh?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 110, 'm14s', 'Well done. Spread the word of the Empire''s generosity!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 111, 'm14p', 'The Empire''s influence with the Corporate Sector Authority can be a great benefit to loyal citizens.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 112, 'm14t', 'Swoop Discount Voucher'),
('string/en/mission/mission_deliver_imperial_easy.stf', 113, 'm15d', 'Our Board has selected a winner in the Patriotic Art Competition. The lucky citizen is to receive an all-expense-paid vacation to Coruscant. Return this award-winning painting, entitled "Lord Vader: Protector of the Empire''s Youth," to the artist. The documents attached include prize redemption instructions.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 114, 'm15l', 'Painting'),
('string/en/mission/mission_deliver_imperial_easy.stf', 115, 'm15o', 'COMPNOR: Arts Division'),
('string/en/mission/mission_deliver_imperial_easy.stf', 116, 'm15r', 'I won? I won! I can''t wait to tell the kids we''re going to Coruscant. Thanks!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 117, 'm15f', 'filename_of_object');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_imperial_easy.stf', 118, 'm15s', 'Plans have changed. A reliable informant tells us that the artist has been seen recently in the company of dubious individuals suspected of Rebel sympathies. The artist''s prize has been cancelled. '),
('string/en/mission/mission_deliver_imperial_easy.stf', 119, 'm15p', 'I love the way all those children are gazing admiringly at the striking figure of Lord Vader. It''s most inspiring.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 120, 'm15t', 'Lord Vader: Protector of Empire''s Youth'),
('string/en/mission/mission_deliver_imperial_easy.stf', 121, 'm16d', 'A model citizen divulged the names of several dangerous Rebel spies a few weeks ago. Two of those spies were the citizen''s own parents. What greater demonstration of loyalty can exist? As we promised, we''re delivering a hologram recording of the executions. Take it to this citizen with our thanks and compliments.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 123, 'm16o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 124, 'm16r', 'I don''t want to watch this horrid recording! I made a big mistake! The Force preserve me! What have I done?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 126, 'm16s', 'The citizen appears to have fallen from earlier ideals and is now being taken to a COMPNOR Re-education Center. Say nothing of this, or it will go badly for you.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 127, 'm16p', 'This is the sort of strength we require in our citizens. Heed this example!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 128, 'm16t', 'Hologram of Execution'),
('string/en/mission/mission_deliver_imperial_easy.stf', 129, 'm17d', 'Interrogation of a Rebel spy has resulted in a list of suspected Rebels and sympathizers. We''re very interested in finding these individuals without alarming them. Deliver this list of names and holographic images to our contact, who will discreetly disseminate the information to loyal citizens.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 131, 'm17o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 132, 'm17r', 'I''ll make sure this gets into the right hands. You can never be too careful these days.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 134, 'm17s', 'Owing to the length of the list of suspects, some of those lower on the list were warned by the apprehension of the first few. However, our operations continue. We shall find them all.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 135, 'm17p', 'Traitors can''t hide forever. The Empire roots out such vermin wherever they nest.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 136, 'm17t', 'List of Suspects'),
('string/en/mission/mission_deliver_imperial_easy.stf', 137, 'm18d', 'The New Order teaches that humans are superior to other species. A highly respected scientist is composing a definitive work to prove this. Help this effort by providing the scientist with the results of certain medical studies. These are not available on the HoloNet, of course. We don''t want these delicate results to fall into the hands of enemies who would wilfully misinterpret them.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 139, 'm18o', 'COMPNOR Science Division'),
('string/en/mission/mission_deliver_imperial_easy.stf', 140, 'm18r', 'The medical results at last! Soon no one will doubt the physical and ethical superiority of humans.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 141, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 142, 'm18s', 'The sensitive nature of these medical results requires your discretion. Tell no one of these findings until the populace is suitably prepared for their release.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 143, 'm18p', 'Don''t believe any stories you hear about vivisection. They''re sheer nonsense.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 144, 'm18t', 'Medical Files'),
('string/en/mission/mission_deliver_imperial_easy.stf', 145, 'm19d', 'One of our spies, who are everywhere, located a new Rebel terrorist cell several days ago but has not contacted us since. Deliver this datadisc and claim it confirms an order of fuel cells. If the recipient accepts the disc, our spy has been discovered. If the disc is refused, then our spy is still active but simply trying to avoid suspicion. Can you do this?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 147, 'm19o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 148, 'm19r', 'Fuel cells, huh? Sure, I''ll take it. Do I need to sign anything?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 149, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 150, 'm19s', 'We have located the spy''s body and are now recruiting a replacement. The setback is purely temporary.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 151, 'm19p', 'We lose good lives to these Rebel scum all the time. It''s part of the sacrifice every good citizen must make.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 152, 'm19t', 'Confirm Status of Spy'),
('string/en/mission/mission_deliver_imperial_easy.stf', 153, 'm20d', 'A concerned parent believes local schoolchildren are being fed pro-Rebel propaganda. Deliver to this informant a small undetectable transmitter to hide on the child''s clothing. We''ll soon discover who at this school is poisoning the minds of the Empire''s youth.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 154, 'm20l', 'Small sealed container'),
('string/en/mission/mission_deliver_imperial_easy.stf', 155, 'm20o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 156, 'm20r', 'Thank you. I believe all our schoolteachers harbor pro-Rebel sentiments. I''ll put an end to their crimes.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 157, 'm20f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 158, 'm20s', 'A purge and purification of schoolteachers will begin soon. Thank you for your help.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 159, 'm20p', 'How foolish of a schoolteacher to push traitorous propaganda on our children!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 160, 'm20t', 'Undetectable Transmitter'),
('string/en/mission/mission_deliver_imperial_easy.stf', 161, 'm21d', 'A certain citizen may be supplying the Rebels. Deliver this cooker, saying that it''s a prize in a sweepstakes. A transmitter built into the device should reveal the suspect''s true loyalties.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 162, 'm21l', 'Food Cooker'),
('string/en/mission/mission_deliver_imperial_easy.stf', 163, 'm21o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 164, 'm21r', 'A new cooker? How wonderful. I just love baking for the neighborhood. Would you care for a cookie? They''re fresh.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 165, 'm21f', 'crafting\\station\\food_tool.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 166, 'm21s', 'The Rebel sympathizer''s seemingly innocuous front will soon crumble like those "cookies" that undoubtedly wind up in Rebel mouths.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 167, 'm21p', 'When will citizens realize that every action has a consequence? Crime does not pay.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 168, 'm21t', 'Bugged Cooker'),
('string/en/mission/mission_deliver_imperial_easy.stf', 169, 'm22d', 'A citizen suspected of pro-Rebel sympathies is hosting a catered party in an effort to earn a promotion. Rebel-lovers do not deserve promotions. The party must fail. Deliver this bottle of Naboo wine; claim it''s from the caterer. When the guests drink the wine, they''ll become deathly ill. This will ruin that traitor''s chances. Do your duty. '),
('string/en/mission/mission_deliver_imperial_easy.stf', 170, 'm22l', 'Bottle of wine'),
('string/en/mission/mission_deliver_imperial_easy.stf', 171, 'm22o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 172, 'm22r', 'Naboo wine! How nice. To think we were considering never using this caterer''s services again. Thank you!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 173, 'm22f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 174, 'm22s', 'The battle against the Rebellion must proceed on many fronts. COMPNOR is there to fight on the fields that the Army and Navy cannot reach.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 175, 'm22p', 'One should always know the source of a gift, don''t you agree? Hahaha!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 176, 'm22t', 'Naboo Wine'),
('string/en/mission/mission_deliver_imperial_easy.stf', 177, 'm23d', 'A lunatic who claims to be the Emperor continues to send HoloNet messages demanding a military escort to the market. Our spies, who are everywhere, assure us that this idiot is harmless. However, this office believes the Empire should deal with lunatics more firmly. Deliver this order instructing the maniac to cease and desist.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 179, 'm23o', 'COMPNOR'),
('string/en/mission/mission_deliver_imperial_easy.stf', 180, 'm23r', 'What? How dare my minions speak to me in such a manner! They shall all pay the price for their lack of vision!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 182, 'm23s', 'The lunatic continues to pester this office, most recently with orders to construct a second Death Star. What foolishness!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 183, 'm23p', 'The Empire''s patience is not infinite. I hope this will convince that fool to cease such insane activities.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 184, 'm23t', 'Desist Order for a Lunatic'),
('string/en/mission/mission_deliver_imperial_easy.stf', 185, 'm24d', 'The Empire is looking for people of action, not words. One citizen, at great peril to life and limb, prevented an escaped Yuzzem prisoner from hijacking a local transport and possibly killing dozens of loyal citizens. Deliver to this hero a special ISB vibrodagger, a replica of the weapon carried by our agents.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 186, 'm24l', 'Replica Vibrodagger'),
('string/en/mission/mission_deliver_imperial_easy.stf', 187, 'm24o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_easy.stf', 188, 'm24r', 'This is a great honor. I shall carry it with pride. Hail the Empire!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 189, 'm24f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy.stf', 190, 'm24s', 'The replica vibrodagger must not be worn in public, on pain of prosecution for impersonating an officer. Did you inform the recipient of this vital fact?'),
('string/en/mission/mission_deliver_imperial_easy.stf', 191, 'm24p', 'Perhaps someday you can earn a similar weapon, citizen. Be diligent.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 192, 'm24t', 'Replica Vibrodagger'),
('string/en/mission/mission_deliver_imperial_easy.stf', 193, 'm25d', 'A misguided merchant has been pricing goods outside the approved Imperial price ranges. Perhaps this individual has not received our latest pricing guide. Deliver this guide and inform the merchant that we expect prices to fall within the stipulated ranges very soon. A second warning about this matter would not benefit business. '),
('string/en/mission/mission_deliver_imperial_easy.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy.stf', 195, 'm25o', 'COMPNOR Commerce Division'),
('string/en/mission/mission_deliver_imperial_easy.stf', 196, 'm25r', 'I -- I was just trying to help out local businesses that can''t afford these high Imperial taxes. No, wait, don''t report I said that! I''ll raise my prices!'),
('string/en/mission/mission_deliver_imperial_easy.stf', 197, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy.stf', 198, 'm25s', 'Our spies report that the merchant''s prices are returning to acceptable ranges. All is well.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 199, 'm25p', 'Rules are made for a reason, and it''s not for the purpose of breaking them. Obedience is expected.'),
('string/en/mission/mission_deliver_imperial_easy.stf', 200, 'm25t', 'COMPNOR Pricing Guide'),
('string/en/mission/mission_deliver_imperial_easy.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 1, 'm1d', 'We''re providing our recruiters with a demo version of our TIE flight simulators, to help boost enlistment. Pick up and deliver the encrypted program. Tell the recruiter to limit the amount of time each visitor gets with the flight sim. We know those simulators can be addictive. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 5, 'm1r', 'This will certainly boost enlistment. I love these flight sims.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 6, 'm1p', 'Our TIE flight training programs are a big draw for Imperial citizens.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 7, 'm1t', 'Help Imperial Recruitment'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 8, 'm1s', 'Well done. The Empire has compensated you.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 9, 'm2d', 'We''ve redesigned our scout trooper blaster pistol so that it can carry a larger energy cell and deliver a more powerful punch. Pick up the prototype and design specs, and deliver them to a garrison commander for field testing. This is an important military mission. Can we count on you?'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 10, 'm2l', 'Trooper pistol'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 12, 'm2f__', 'Filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 13, 'm2r', 'Amazing how the pistol retained its light weight even with the larger energy cell.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 14, 'm2p', 'This pistol is a true credit to the genius of the Imperial Army''s weapon designers.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 15, 'm2t', 'Help Test Prototype Pistol'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 16, 'm2s', 'Good work, agent. We''ll be keeping our eye on you. You show promise.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 17, 'm3d', 'We''ve finally identified all the surviving Rebel pilots from the Battle of Yavin, including a Corellian smuggler and his Wookiee companion. Pick up their dossiers and take them to the local garrison commander. All stormtroopers will keep a sharp eye out for these enemies of the state.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 21, 'm3r', 'Our troopers will arrest this Rebel scum in no time.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 22, 'm3p', 'These terrorists are responsible for the deaths of thousands of loyal Imperial officers and troopers. We trust they will be arrested soon.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 23, 'm3t', 'Find the Traitors of Yavin'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 24, 'm3s', 'Fine work. Continue serving the Empire and you will continue to be rewarded.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 25, 'm4d', 'Imperial Intelligence suggests that recent potential recruits are actually undercover agents for the Rebellion. Pick up the list of names and take it to the garrison commander so these suspects can be arrested for questioning.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 29, 'm4r', 'We do get our fair share of spies. Fortunately, we always root them out.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 30, 'm4p', 'Our recruiters must be especially vigilant. Rebel spies constantly try to infiltrate through their offices.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 31, 'm4t', 'Potential Recruits Are Often Spies'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 32, 'm4s', 'Your service to the Empire is noted, citizen. We hope it will continue.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 33, 'm5d', 'A design flaw in older helmet comlinks allows certain transceivers to pick up a trooper''s transmissions. A modification to the comlink chip should take care of the problem. Pick up the adjustment instructions and deliver them to the local garrison commander. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 37, 'm5r', 'You can never be too careful about who''s listening in on what, eh?'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 38, 'm5p', 'Here you are. The commander should also use this opportunity to do an inventory of his garrison.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 39, 'm5t', 'Fix Trooper Helmets'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 40, 'm5s', 'Fortunately, these older helmets are found mostly on small outposts. You''ve been compensated for your efforts, citizen.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 41, 'm6d', 'Recent sabotage by Rebel data slicers has confused local garrisons. Pick up and deliver some encrypted orders to the local commander. Inform him that he will receive orders in this manner until Imperial Intelligence can once again secure the HoloNet.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 45, 'm6r', 'Good. This should clarify things a bit. These Rebels are a definite thorn in our side.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 46, 'm6p', 'I''ve always preferred hand-delivered orders. Nothing beats the extra security.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 47, 'm6t', 'Improved Imperial Security'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 48, 'm6s', 'Well done. I hope that this is just an example of what we can expect from you in the future.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 49, 'm7d', 'We''re receiving requests for additional conscripts from the Corporate Sector Authority. Our detention facilities are overflowing, so our solution is clear. Prisoners are to be transported immediately to the CSA''s processing facilities. Pick up and deliver the instructions to the local warden.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 53, 'm7r', 'I hope these quotas call for large numbers of prisoners, because we''ve got them to spare.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 54, 'm7p', 'Building and maintaining the Imperial war machine takes many strong backs. Rebel backs will do nicely.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 55, 'm7t', 'Clear Out the Prisons'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 56, 'm7s', 'Efficient and prompt. Good. That is what the Empire expects from its loyal citizens.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 57, 'm8d', 'A recent list of suspects includes senatorial aides and family members. Local security forces have been reluctant to arrest them without word from Imperial High Command. Pick up the arrest warrants and take them to the garrison commander. They''ve been issued by the Ubiqtorate itself.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 61, 'm8r', 'You understand our caution, don''t you? This will clear things up.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 62, 'm8p', 'The influence of many of the Old Republic''s corrupt senators is difficult to dispel.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 63, 'm8t', 'Ubiqtorate Arrest Warrants'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 64, 'm8s', 'Well handled, citizen. Those arrest warrants will be served immediately.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 65, 'm9d', 'We''ve fallen behind schedule due to prisoner riots. We need a boost to our labor force to keep up the Emperor''s aggressive military buildup. Pick up the order for aid in worker recruitment and deliver it to the local government official.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 68, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 69, 'm9r', 'I can think of a few layabouts who could be persuaded to serve the Engineer Corps. We''ll get right on it.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 70, 'm9p', 'Sometimes the Emperor asks the impossible. We need more workers!'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 71, 'm9t', 'Recruit Military Workers'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 72, 'm9s', 'You have done well. Continue to serve the Emperor faithfully.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 73, 'm10d', 'We''ve just received an order from General Veers himself at Imperial High Command to train more AT-AT pilots. Pick up and deliver a set of transfers to the garrison commander. These candidates are to go immediately to Imperial training facilities.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 77, 'm10r', 'Always wanted to pilot an AT-AT myself. I''ll see to this at once.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 78, 'm10p', 'I understand that General Veers is serving directly under Lord Vader. A prestigious assignment indeed.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 79, 'm10t', 'Recruit AT-AT Pilots'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 80, 'm10s', 'You''ve done well, citizen. It is the Empire''s hope that you will continue to serve faithfully.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 81, 'm11d', 'We intend to strike Mon Calamari''s floating cities in retaliation for their aid to the Rebellion. Pick up High Command''s orders and deliver them to the garrison commander. All shore leave is revoked. All troopers must report to duty at once.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 84, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 85, 'm11r', 'Word will go out immediately. My men will report on time.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 86, 'm11p', 'We waited too long to strike the Mon Calamari. This is long overdue.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 87, 'm11t', 'Strike the Mon Calamari'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 88, 'm11s', 'The Star Destroyer will depart soon. We will make the Mon Calamari pay for their crimes against the Empire.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 89, 'm12d', 'Admiral Ozzel has just informed us that we need to deliver 500 additional probe droids to the Star Destroyer Accuser. Collect the requisition order and deliver it to our depot officer. He''ll see to it that those probe droids are loaded aboard a transport.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 93, 'm12r', 'More probe droids? We can hardly keep them in stock. What, or who, are they looking for?'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 94, 'm12p', 'Searching the Galaxy takes time and resources.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 95, 'm12t', 'Probe Droids Search the Galaxy'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 96, 'm12s', 'You''ve done well. The Empire is grateful for your assistance.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 97, 'm13d', 'A former Senator continues to aid the Rebellion. Despite the dissolution of the Senate, this politician''s influence limits our access to his holdings. Collect and deliver a termination order to our Intelligence contact. This mission is to be accomplished "by any means necessary." '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 101, 'm13r', 'Good. I''ve been waiting for a chance to take out this Senator. I think I''ll throw in his annoying family as a bonus.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 102, 'm13p', 'These do-gooders will learn that privileged positions can''t protect them from the Emperor''s wrath.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 103, 'm13t', 'Take Out a Senator'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 104, 'm13s', 'That was a delicate mission, handled discreetly and professionally. The Empire will not forget your efficiency.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 105, 'm14d', 'Insiders helped the Rebellion acquire secret Imperial plans resulting in the deaths of thousands of loyal soldiers. Pick up the dossiers on our prime suspects, and deliver them to an agent of the Bounty Hunters'' Guild. We order a deathmark on every suspect.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 109, 'm14r', 'Business is good for our guild these days. The Battle of Yavin was the Empire''s disgrace and our fortune.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 110, 'm14p', 'We do what we must to ensure the guilty will be brought to justice.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 111, 'm14t', 'Avenge the Death Star'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 112, 'm14s', 'That was handled well, citizen. The Empire will see to it that you are rewarded.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 113, 'm15d', 'We''ve just captured several Rebels who were conducting sabotage missions in the Outer Rim. The Rebels'' resistance to convential interrogation have made drastic action necessary. Collect and deliver a message, for the eyes of an Inquisitor only. We need his skills in interrogation. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 117, 'm15r', 'I leave at once. These Rebels will tell us everything.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 118, 'm15p', 'I can''t wait to watch the Inquisitor at work. They say the sight is a thing of beauty.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 119, 'm15t', 'Summon the Inquisitor'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 120, 'm15s', 'Well done. Your dedication to the Empire is admirable.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 121, 'm16d', 'Intercepted Rebel transmissions are too vital to send via the HoloNet. Collect a copy of these transmissions and deliver them to our Intelligence contact. Deciphering these transmissions will lead us to the Rebel''s new base. The Empire is counting on you. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 125, 'm16r', 'We''ll get right on this. Those Rebels won''t escape us.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 126, 'm16p', 'Information is power, citizen. The Empire''s information network is the best in the galaxy.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 127, 'm16t', 'Intercepted Rebel Transmissions'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 128, 'm16s', 'Prompt delivery and a minimum of fuss. That''s the sort of action the Empire prizes. Well done.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 129, 'm17d', 'We must insure the Corporate Sector Authority is not secretly aiding the Rebel Alliance in exchange for payoffs. We have obtained the security codes to confidential CSA files. Collect them and give them to our covert operative. If he discovers wrongdoing, he is to take appropriate action.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 133, 'm17r', 'Now we''ll see which Viceprexes are smart and which are not.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 134, 'm17p', 'The CSA''s loyalty will always be to money. The Empire should not be so lenient with them.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 135, 'm17t', 'Investigate the CSA'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 136, 'm17s', 'Performed with great professionalism, citizen. The Empire is glad to pay your fee.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 137, 'm18d', 'We''ve discovered a number of CSA Viceprexes who have been aiding Rebels in exchange for money. Collect and deliver termination orders to our operative as soon as possible. We''ll make sure the CSA understands that the Empire does not treat such matters lightly.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 141, 'm18r', 'What good is money if you''re not around to spend it? Too bad these guys didn''t learn that lesson.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 142, 'm18p', 'Money is a powerful motivator, but the threat of death is more powerful still.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 143, 'm18t', 'Bump Off Greedy Businessmen'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 144, 'm18s', 'Excellent work, citizen. The Empire will reward you.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 145, 'm19d', 'Intelligence suspects that a new breed of Jedi has appeared and is aiding the Rebels. Collect Intelligence''s report and deliver it to the Inquisitors. If the Jedi have returned, we must hunt and destroy them once and for all. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 149, 'm19r', 'We will root out these Jedi. They will meet the same fate as their corrupt Old Republic predecessors.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 150, 'm19p', 'If this rumor is true, it would explain the Battle of Yavin.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 151, 'm19t', 'Inquisitors Must Hunt Jedi'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 152, 'm19s', 'As long as loyal citizens such as yourself continue to serve faithfully, the Empire will crush its enemies.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 153, 'm20d', 'We suspect the Mon Calamari are building a vast fleet to support the Rebellion. Collect and deliver Intelligence''s instructions to our operative so that they can organize surveillance missions in preparation for Imperial strikes on Mon Calamari floating cities. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 157, 'm20r', 'This will be an excellent example of Imperial justice, second only to Alderaan.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 158, 'm20p', 'Aiding the Rebellion invokes genocide. All species must support the New Order.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 159, 'm20t', 'Punish the Mon Calamari'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 160, 'm20s', 'The Empire is pleased with your performance, agent. The Mon Calamari will pay for the thousands of Imperial lives lost at Yavin with millions of their own.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 161, 'm21d', 'A Rebel cell has been identified on a remote planet in the Outer Rim. Pick up the report and deliver it to our Imperial Naval contact. This cell must be wiped out immediately. Take no prisoners.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 165, 'm21r', 'I think one Star Destroyer with a full complement of stormtroopers ought to suffice.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 166, 'm21p', 'This assignment requires an Imperial naval captain who is not squeamish.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 167, 'm21t', 'Destroy a Rebel Colony'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 168, 'm21s', 'Your service helps the Imperial war machine run smoothly. You deserve to be rewarded.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 169, 'm22d', 'We''ve been instructed to locate some sort of rare crystal on Mimban. Collect and deliver Intelligence''s instructions to our local agent. He should contact Captain-Supervisor Grammel to secure his help. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 173, 'm22r', 'Mimban? Isn''t that a small mining colony? I will follow these instructions to the letter.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 174, 'm22p', 'We never question the Emperor''s instructions, citizen. Never.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 175, 'm22t', 'Find the Mimban Crystal'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 176, 'm22s', 'We must pursue all leads that might result in the destruction of the Rebellion. Your efforts are noted, citizen.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 177, 'm23d', 'A seller of antiques claims to possess rare Sith artifacts. The Emperor himself has commanded that this individual be arrested and these artifacts confiscated, if they exist. Collect and deliver the warrant to our operative.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 181, 'm23r', 'I was wondering when we''d get around to bringing in this dealer. It''s as good as done.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 182, 'm23p', 'I don''t understand the fascination that old religion holds for Imperial citizens. Superstition, I suppose.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 183, 'm23t', 'Retrieve Sith Artifacts'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 184, 'm23s', 'Job well done, agent. The Emperor will be informed of your assistance.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 185, 'm24d', 'An influential Imperial dignitary has been proven a traitor. He must be removed quietly, in order to avoid alerting his allies. Collect a Scarab assassin droid and deliver it to our agent. We''ve made sure the droid will be traced back to Rebel operatives. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 186, 'm24l', 'Small assassin droid'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 188, 'm24f', 'Filename_of_object'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 189, 'm24r', 'You sure I won''t be implicated in this? This guy''s got a lot of friends on Coruscant.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 190, 'm24p', 'A fitting end for such a vile traitor, wouldn''t you agree?'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 191, 'm24t', 'Scarab Assassin Droid'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 192, 'm24s', 'Well done, agent. Your service to the Empire has been noted, and your future looks rosy indeed.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 193, 'm25d', 'The Emperor wants to know how a Jedi Knight, especially one as dangerous as Obi-Wan Kenobi, could have hidden for so long. Our agent is to turn Tatooine inside out in an effort to answer this question. The Emperor''s instructions are on an encrypted datadisc that you must collect and deliver. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 197, 'm25r', 'I''m sure the Hutts helped hide this fugitive. Those creatures will do anything for money.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 198, 'm25p', 'I certainly hope there aren''t any more Jedi secretly aiding the Rebellion. '),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 199, 'm25t', 'Investigate Tatooine'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 200, 'm25s', 'Trusted agents are hard to find. The Empire wants to insure your continued allegiance by demonstrating how lucrative it can be to serve the Emperor.'),
('string/en/mission/mission_deliver_imperial_easy_non_persistent_from_npc.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_imperial_hard.stf', 1, 'm1d', 'An Internal Affairs agent is investigating a so-called "officer" of the ISB. We suspect this individual is actually a double agent helping the Rebels. Deliver this warrant to our agent. It will tell him how to proceed.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 3, 'm1o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_hard.stf', 4, 'm1r', 'If this is what I think it is, I can finally put a stop to this officer''s activities. Forever.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 6, 'm1s', 'Well done. That traitorous officer will soon learn the price for betraying the Empire.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 7, 'm1p', 'When it comes to the security of the Empire, no one is above suspicion of traitorous activities.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 8, 'm1t', 'ISB Double Agent Termination'),
('string/en/mission/mission_deliver_imperial_hard.stf', 9, 'm2d', 'Our  Internal Organization Bureau discovered one of our agents selling information to the Rebellion. The traitor fled to the Outer Rim. Deliver this open bounty to our contact within the Bounty Hunters'' Guild.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 11, 'm2o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 12, 'm2r', 'I''ll make sure this gets transmitted to our entire organization. You''ll have your target soon enough.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 14, 'm2s', 'With this open bounty on the traitor''s head, we''re confident that he''ll soon be back in our hands. We intend to discover the full extent of his crime.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 15, 'm2p', 'It is supreme folly to betray the Empire -- doubly so within the ranks of Imperial Intelligence!'),
('string/en/mission/mission_deliver_imperial_hard.stf', 16, 'm2t', 'Imperial Intelligence Deathmark'),
('string/en/mission/mission_deliver_imperial_hard.stf', 17, 'm3d', 'A former Senator continues to aid the Rebellion. Despite the dissolution of the Senate, this politician''s influence limits our access to his holdings. Collect and deliver a termination order to our Intelligence contact. This mission is to be accomplished "by any means necessary."'),
('string/en/mission/mission_deliver_imperial_hard.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 19, 'm3o', 'Imperial Intelligence: Bureau of Operations');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_imperial_hard.stf', 20, 'm3r', 'Good. I''ve been waiting for a chance to take out this Senator. I think I''ll throw in his annoying family as a bonus.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 22, 'm3s', 'That was a delicate mission, handled discreetly and professionally. The Empire will not forget your efficiency.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 23, 'm3p', 'These privileged politicians will learn that their position can''t protect them from the Empire''s wrath.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 24, 'm3t', 'Senatorial Assassination'),
('string/en/mission/mission_deliver_imperial_hard.stf', 25, 'm4d', 'Insiders helped the Rebellion acquire secret Imperial plans resulting in the deaths of thousands of loyal soldiers. Pick up the dossiers on our prime suspects, and deliver them to an agent of the Bounty Hunters'' Guild. We order a deathmark on every suspect.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 27, 'm4o', 'Imperial Security Bureau'),
('string/en/mission/mission_deliver_imperial_hard.stf', 28, 'm4r', 'Business is good for our guild these days. The Battle of Yavin was the Empire''s disgrace and our fortune.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 30, 'm4s', 'If these traitors are lucky, they''ll be killed by the bounty hunters. The others will end up in our hands.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 31, 'm4p', 'We do what we must to ensure the guilty will be brought to justice.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 32, 'm4t', 'Death Star Traitor List'),
('string/en/mission/mission_deliver_imperial_hard.stf', 33, 'm5d', 'We''ve just captured several Rebels who were conducting sabotage missions in the Outer Rim. The Rebels'' resistance to convential interrogation have made drastic action necessary. Collect and deliver a message, for the eyes of an Inquisitor only. We need his skills in interrogation. '),
('string/en/mission/mission_deliver_imperial_hard.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 35, 'm5o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 36, 'm5r', 'I leave at once. These Rebels will tell us everything.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 37, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 38, 'm5s', 'Well done. Your dedication to the Empire is admirable.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 39, 'm5p', 'I can''t wait to watch the Inquisitor at work. They say the sight is a thing of beauty.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 40, 'm5t', 'Request for Inquisitor'),
('string/en/mission/mission_deliver_imperial_hard.stf', 41, 'm6d', 'Intercepted Rebel transmissions are too vital to send via the HoloNet. Collect a copy of these transmissions and deliver them to our Intelligence contact. Deciphering these transmissions will lead us to the Rebel''s new base. The Empire is counting on you.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 43, 'm6o', 'Imperial Intelligence: Analysis Bureau'),
('string/en/mission/mission_deliver_imperial_hard.stf', 44, 'm6r', 'We''ll get right on this task. Those Rebels won''t escape us.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 45, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 46, 'm6s', 'Prompt delivery and a minimum of fuss. That''s the sort of action the Empire prizes. Well done.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 47, 'm6p', 'Information is power, citizen. The Empire''s information network is the best in the galaxy.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 48, 'm6t', 'Deliver intercepted transmissions'),
('string/en/mission/mission_deliver_imperial_hard.stf', 49, 'm7d', 'Since the interception of secret Imperial transmissions, an act that cost the Empire dearly, we hand-deliver vital communiques on encrypted datadiscs. These discs destroy themselves if a proper code is not entered upon reading. Deliver this datadisc to one of our field operatives. It gives special instructions regarding a suspected Rebel safehouse.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 51, 'm7o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 52, 'm7r', 'The more of these safehouses we destroy, the less effective the Rebellion will be.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 53, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 54, 'm7s', 'Excellent work. We trust you did not try to read the disc. Its self-destruction frequently damages the reading device as well.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 55, 'm7p', 'These discs will prevent another Yavin 4 disaster. The Rebellion will soon be crushed.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 56, 'm7t', 'Encoded Safehouse Instructions'),
('string/en/mission/mission_deliver_imperial_hard.stf', 57, 'm8d', 'We must insure the Corporate Sector Authority is not secretly aiding the Rebel Alliance in exchange for payoffs. We have obtained the security codes to confidential CSA files. Collect them and give them to our covert operative. If he discovers wrongdoing, he is to take appropriate action.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 59, 'm8o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 60, 'm8r', 'Now we''ll see which Viceprexes are smart and which are not.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 61, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 62, 'm8s', 'Performed with great professionalism, citizen. The Empire is glad to pay your fee.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 63, 'm8p', 'The CSA''s loyalty will always be to money. The Empire should not be so lenient with them.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 64, 'm8t', 'Deliver security codes'),
('string/en/mission/mission_deliver_imperial_hard.stf', 65, 'm9d', 'We''ve discovered a number of CSA Viceprexes who have been aiding Rebels in exchange for money. Collect and deliver termination orders to our operative as soon as possible. We''ll make sure the CSA understands that the Empire does not treat such matters lightly.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 67, 'm9o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 68, 'm9r', 'What is good is money if you''re not around to spend it? Too bad these guys didn''t learn that lesson.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 70, 'm9s', 'Excellent work, citizen. The Empire will reward you.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 71, 'm9p', 'Money is a powerful motivator, but the risk of death is more powerful still.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 72, 'm9t', 'Viceprex Termination Orders'),
('string/en/mission/mission_deliver_imperial_hard.stf', 73, 'm10d', 'Intelligence suspects that a new breed of Jedi has appeared and is aiding the Rebels. Collect Intelligence''s report and deliver it to the Inquisitors. If the Jedi have returned, we must hunt and destroy them once and for all.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 75, 'm10o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 76, 'm10r', 'We will root out these Jedi. They will meet the same fate as their corrupt Old Republic predecessors.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 78, 'm10s', 'As long as loyal citizens such as yourself continue to serve faithfully, the Empire will crush its enemies.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 79, 'm10p', 'If this rumor is true, it would explain the Battle of Yavin.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 80, 'm10t', 'Jedi Intelligence for Inquisitors'),
('string/en/mission/mission_deliver_imperial_hard.stf', 81, 'm11d', 'We suspect the Mon Calamari are building a vast fleet to support the Rebellion. Collect and deliver Intelligence''s instructions to our operative so that they can organize surveillance missions in preparation for Imperial strikes on Mon Calamari floating cities.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 83, 'm11o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 84, 'm11r', 'Not since Alderaan has there been such an excellent example of Imperial justice.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 85, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 86, 'm11s', 'The Empire is pleased with your performance, agent. The Mon Calamari will pay for the thousands of Imperial lives lost at Yavin with millions of their own.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 87, 'm11p', 'Aiding the Rebellion invokes genocide. All species must support the New Order.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 88, 'm11t', 'Mon Calamari Attack Orders'),
('string/en/mission/mission_deliver_imperial_hard.stf', 89, 'm12d', 'A Rebel cell has been identified on a remote planet in the Outer Rim. Pick up the report and deliver it to our Imperial Naval contact. This cell must be wiped out immediately. Take no prisoners.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 91, 'm12o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 92, 'm12r', 'I think one Star Destroyer with a full complement of stormtroopers ought to suffice for this mission.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 94, 'm12s', 'Your service helps the Imperial war machine run smoothly. You deserve to be rewarded.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 95, 'm12p', 'This assignment requires an Imperial naval captain who is not squeamish.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 96, 'm12t', 'Outer Rim Rebel Cell Must Fall'),
('string/en/mission/mission_deliver_imperial_hard.stf', 97, 'm13d', 'Certain demonstrations in the Core Worlds protest the Imperial war machine. Deliver this airborne virus to our field agent, and instruct him to attend protests of this sort. The rest should be obvious. Tell the agent to take extreme precautions, as there is no cure for this engineered virus.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 98, 'm13l', 'Sealed container'),
('string/en/mission/mission_deliver_imperial_hard.stf', 99, 'm13o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 100, 'm13r', 'This should discourage many would-be protestors.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 101, 'm13f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_hard.stf', 102, 'm13s', 'You did not have contact with the virus yourself, did you? We would hate to lose a promising agent.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 103, 'm13p', 'Make sure the seal on this container does not break!'),
('string/en/mission/mission_deliver_imperial_hard.stf', 104, 'm13t', 'Engineered Airborne Virus'),
('string/en/mission/mission_deliver_imperial_hard.stf', 105, 'm14d', 'Our office has been instructed to collect data on the name "Skywalker." Of particular importance is the planet Tatooine. Send these instructions to our agent. He is not to contact us via the HoloNet; only hand-delivered communiques via courier are acceptable. Under no circumstances is Lord Vader to be informed of this mission.  '),
('string/en/mission/mission_deliver_imperial_hard.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 107, 'm14o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 108, 'm14r', 'Wasn''t Skywalker a Jedi killed during the Clone Wars?'),
('string/en/mission/mission_deliver_imperial_hard.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 110, 'm14s', 'You have performed admirably. However, for security purposes it is vital that you now forget ever having been involved. Should news of this assignment leak out, it will go badly for you.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 111, 'm14p', 'It is our understanding that the Emperor has taken a personal interest in this matter. Don''t fail him.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 112, 'm14t', '"Skywalker" Research Instructions'),
('string/en/mission/mission_deliver_imperial_hard.stf', 113, 'm15d', 'We''ve been instructed to locate some sort of rare crystal on Mimban. Collect and deliver Intelligence''s instructions to our local agent. He should contact Captain-Supervisor Grammel to secure his help.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 114, 'm15l', 'Deliver instructions to agent'),
('string/en/mission/mission_deliver_imperial_hard.stf', 115, 'm15o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 116, 'm15r', 'Mimban? Isn''t that some insignificant mining colony? Well, orders are orders.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 117, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 118, 'm15s', 'We must pursue all leads that might result in the destruction of the Rebellion. Your efforts are noted, citizen.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 119, 'm15p', 'We never question the Emperor''s instructions. Never.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 120, 'm15t', 'Mimban Crystal Instructions'),
('string/en/mission/mission_deliver_imperial_hard.stf', 121, 'm16d', 'The Kessel prison camp may have processed certain individuals believed intrumental in the destruction of the Death Star: a Corellian smuggler, his Wookiee companion, and a young pilot from somewhere in the Outer Rim Territories. This datadisc contains complete dossiers on all three, along with travel instructions to Kessel. Deliver the disc to our agent promptly.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 123, 'm16o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 124, 'm16r', 'Kessel, huh? And a Jedi? This job just gets better and better.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 126, 'm16s', 'The Empire appreciates your role in hunting the Rebels responsible for the Death Star''s destruction.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 127, 'm16p', 'According to the dossier, the young pilot may possess Jedi abilities. Advise our agent to use caution.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 128, 'm16t', 'Yavin 4 Traitor Dossiers'),
('string/en/mission/mission_deliver_imperial_hard.stf', 129, 'm17d', 'A seller of antiques claims to possess rare Sith artifacts. The Emperor himself has commanded that this individual be arrested and these artifacts confiscated, if they exist. Collect and deliver the warrant to our operative.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 131, 'm17o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 132, 'm17r', 'I was wondering when we''d get around to bringing in this dealer. It''s as good as done.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 134, 'm17s', 'Job well done, agent. The Emperor will be informed of your assistance.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 135, 'm17p', 'I don''t understand the fascination that old religion holds for Imperial citizens. Superstition, I suppose.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 136, 'm17t', 'Sith Artifact Dealer Warrant'),
('string/en/mission/mission_deliver_imperial_hard.stf', 137, 'm18d', 'We have issued new instructions to one of our informants. Deliver this holoprojector to him. Instruct him to read, in private, the personal message from the Ubiqtorate contained within. '),
('string/en/mission/mission_deliver_imperial_hard.stf', 138, 'm18l', 'Small holoprojector'),
('string/en/mission/mission_deliver_imperial_hard.stf', 139, 'm18o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 140, 'm18r', 'New instructions? Very well, I shall hurry home and read them.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 141, 'm18f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_hard.stf', 142, 'm18s', 'That informant accepted bribes to ignore Rebel activity. This is unacceptable. When the agent activates the holoprojector, he will trigger a small thermal detonator. This will send an appropriate message to our other informants.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 143, 'm18p', 'Loyal citizens can have only one master, and he is the Emperor. What? You don''t understand? You will.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 144, 'm18t', 'Informant''s Holoprojector'),
('string/en/mission/mission_deliver_imperial_hard.stf', 145, 'm19d', 'An influential Imperial dignitary has been proven a traitor. He must be removed quietly, in order to avoid alerting his allies. Collect a Scarab assassin droid and deliver it to our agent. We''ve made sure the droid will be traced back to Rebel operatives.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 146, 'm19l', 'Small assassin droid'),
('string/en/mission/mission_deliver_imperial_hard.stf', 147, 'm19o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 148, 'm19r', 'You sure I won''t be implicated in this? This guy''s got a lot of friends on Coruscant.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 149, 'm19f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_hard.stf', 150, 'm19s', 'Well done, agent. Your service to the Empire has been noted, and your future looks rosy indeed.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 151, 'm19p', 'A fitting end for this dignitary, wouldn''t you agree?'),
('string/en/mission/mission_deliver_imperial_hard.stf', 152, 'm19t', 'Deliver assassin droid'),
('string/en/mission/mission_deliver_imperial_hard.stf', 153, 'm20d', 'A highly placed aide to the Emperor himself has been implicated in a treasonous scandal. We suspect the charge to be false, a Rebel stratagem. However, for the sake of prudence we are arresting the aide''s family members, to discourage him from attempting flight. His daughter is visiting this world. Pick up and take the arrest warrant to the garrison commander. They''ve been issued by the Ubiqtorate itself.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 155, 'm20o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_hard.stf', 156, 'm20r', 'That aide''s daughter is as good as arrested. Long live the Emperor!'),
('string/en/mission/mission_deliver_imperial_hard.stf', 157, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 158, 'm20s', 'No doubt the aide''s reputation will be cleared soon. Were the charge of treason authentic, the Emperor would have easily rooted out a traitor so close to him. Our Emperor excels at detecting treachery.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 159, 'm20p', 'The aide''s daughter is here on a fact-finding mission for the Empire. At least, that is her claim. We shall see.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 160, 'm20t', 'Warrant for Imperial Aide''s Daughter'),
('string/en/mission/mission_deliver_imperial_hard.stf', 161, 'm21d', 'The Emperor wants to know how a Jedi Knight, especially one as dangerous as Obi-Wan Kenobi, could have hidden for so long. Our agent is to turn Tatooine inside out in an effort to answer this question. The Emperor''s instructions are on an encrypted datadisc that you must collect and deliver.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 163, 'm21o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 164, 'm21r', 'I''m sure the Hutts helped hide this fugitive. Those creatures will do anything for money.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 165, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 166, 'm21s', 'Trusted agents are hard to find. The Empire wants to insure your continued allegiance by demonstrating how lucrative it can be to serve the Emperor.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 167, 'm21p', 'I certainly hope there aren''t any more Jedi secretly aiding the Rebellion. '),
('string/en/mission/mission_deliver_imperial_hard.stf', 168, 'm21t', 'Turn Tatooine Inside Out'),
('string/en/mission/mission_deliver_imperial_hard.stf', 169, 'm22d', 'Lord Vader orders that any information regarding the name "Skywalker" is to be transmitted to him immediately. These orders appear to conflict with earlier instructions from the Emperor himself. A recent communique will make matters clear. Deliver it to our surveillance officer.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 171, 'm22o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 172, 'm22r', 'I''ll follow these instructions to the letter.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 173, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 174, 'm22s', 'In all likelihood the term "Skywalker" means nothing important, so this situation may be resolved without undue tension.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 175, 'm22p', 'I fear for any agent who gets caught between Lord Vader and the Emperor. We must resolve this situation.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 176, 'm22t', 'The Emperor vs. Lord Vader?'),
('string/en/mission/mission_deliver_imperial_hard.stf', 177, 'm23d', 'Our spy inside crimelord Jabba the Hutt''s palace has been discovered and fed to Lord Jabba''s pet rancor. Deliver these reassignment orders to the agent we''ve selected to replace him. Inform the agent that speed is of the essence, regardless of the danger posed. When he has successfully infiltrated Jabba''s palace, he is to contact us by courier only.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 179, 'm23o', 'Imperial Intelligence Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 180, 'm23r', 'Imperial Intelligence isn''t very intelligent if it thinks an Imperial agent can survive that deathtrap.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 182, 'm23s', 'It appears the agent is showing unusual reluctance to enter Jabba''s palace. In fact, he has disappeared. We will investigate further.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 183, 'm23p', 'If only all our agents were as efficient as you and the one chosen for this task.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 184, 'm23t', 'Reassignment: Jabba''s Palace'),
('string/en/mission/mission_deliver_imperial_hard.stf', 185, 'm24d', 'Recently we ordered an agent to infiltrate crimelord Jabba the Hutt''s palace. The agent went AWOL. Deliver this termination order to one of our assassins and tell him to take care of this renegade agent as quickly and quietly as possible. We have reasons to believe he is seeking to join the Hutt syndicate.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 187, 'm24o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_deliver_imperial_hard.stf', 188, 'm24r', 'It''s better to die a loyal servant of the Empire than live as a traitor. I wish all agents realized that.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 189, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 190, 'm24s', 'The Hutts recruit small numbers of Imperial renegades each year, hoping to line up new sources of contraband weaponry. We always find and destroy the traitors.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 191, 'm24p', 'This agent could cause us great harm if he turns criminal.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 192, 'm24t', 'Terminate Renegade Agent'),
('string/en/mission/mission_deliver_imperial_hard.stf', 193, 'm25d', 'We intercepted part of a Rebel transmission that mentioned something called a "tauntaun." Records show that this is a species of animal, but here it appears to be a code term. We have reasons to believe it is an important link to locating a major Rebel cell. We''ve included all we know about it on an encrypted datadisc. Deliver it to our operative with instructions to gather more information.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard.stf', 195, 'm25o', 'Imperial Intelligence Analysis Bureau'),
('string/en/mission/mission_deliver_imperial_hard.stf', 196, 'm25r', 'Isn''t "tauntaun" a code name Corellian smugglers use for high grade glitterstim spice? I''ll look into that.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 197, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard.stf', 198, 'm25s', 'With luck, if our operative''s suspicions are correct, we may uncover a Rebel drug-smuggling operation. Your part in this effort will not go unnoticed, agent.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 199, 'm25p', 'Every lead we get must be investigated, no matter how trivial it might appear.'),
('string/en/mission/mission_deliver_imperial_hard.stf', 200, 'm25t', '"Tauntaun" Data Needed'),
('string/en/mission/mission_deliver_imperial_hard.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 1, 'm1d', 'We''re providing our recruiters with a demo version of our TIE flight simulators, to help boost enlistment. Pick up and deliver the encrypted program. Tell the recruiter to limit the amount of time each visitor gets with the flight sim. We know those simulators can be addictive. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 5, 'm1r', 'This will certainly boost enlistment. I love these flight sims.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 6, 'm1p', 'Our TIE flight training programs are a big draw for Imperial citizens.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 7, 'm1t', 'Help Imperial Recruitment'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 8, 'm1s', 'Well done. The Empire has compensated you.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 9, 'm2d', 'We''ve redesigned our scout trooper blaster pistol so that it can carry a larger energy cell and deliver a more powerful punch. Pick up the prototype and design specs, and deliver them to a garrison commander for field testing. This is an important military mission. Can we count on you?'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 10, 'm2l', 'Trooper pistol'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 12, 'm2f__', 'Filename_of_object'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 13, 'm2r', 'Amazing how the pistol retained its light weight even with the larger energy cell.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 14, 'm2p', 'This pistol is a true credit to the genius of the Imperial Army''s weapon designers.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 15, 'm2t', 'Help Test Prototype Pistol'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 16, 'm2s', 'Good work, agent. We''ll be keeping our eye on you. You show promise.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 17, 'm3d', 'We''ve finally identified all the surviving Rebel pilots from the Battle of Yavin, including a Corellian smuggler and his Wookiee companion. Pick up their dossiers and take them to the local garrison commander. All stormtroopers will keep a sharp eye out for these enemies of the state.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 21, 'm3r', 'Our troopers will arrest this Rebel scum in no time.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 22, 'm3p', 'These terrorists are responsible for the deaths of thousands of loyal Imperial officers and troopers. We trust they will be arrested soon.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 23, 'm3t', 'Find the Traitors of Yavin'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 24, 'm3s', 'Fine work. Continue serving the Empire and you will continue to be rewarded.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 25, 'm4d', 'Imperial Intelligence suggests that recent potential recruits are actually undercover agents for the Rebellion. Pick up the list of names and take it to the garrison commander so these suspects can be arrested for questioning.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 29, 'm4r', 'We do get our fair share of spies. Fortunately, we always root them out.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 30, 'm4p', 'Our recruiters must be especially vigilant. Rebel spies constantly try to infiltrate through their offices.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 31, 'm4t', 'Potential Recruits Are Often Spies'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 32, 'm4s', 'Your service to the Empire is noted, citizen. We hope it will continue.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 33, 'm5d', 'A design flaw in older helmet comlinks allows certain transceivers to pick up a trooper''s transmissions. A modification to the comlink chip should take care of the problem. Fortunately, these older helmets are found mostly on small outposts. Pick up the adjustment instructions and deliver them to the local garrison commander. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 37, 'm5r', 'You can never be too careful about who''s listening in on what, eh?'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 38, 'm5p', 'Here you are. The commander should also use this opportunity to do an inventory of his garrison.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 39, 'm5t', 'Fix Trooper Helmets'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 40, 'm5s', 'Well done, citizen. You''ve been compensated for your efforts.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 41, 'm6d', 'Recent sabotage by Rebel data slicers has confused local garrisons. Pick up and deliver some encrypted orders to the local commander. Inform him that he will receive orders in this manner until Imperial Intelligence can once again secure the HoloNet.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 45, 'm6r', 'Good. This should clarify things a bit. These Rebels are a definite thorn in our side.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 46, 'm6p', 'I''ve always preferred hand-delivered orders. Nothing beats the extra security.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 47, 'm6t', 'Improved Imperial Security'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 48, 'm6s', 'Well done. I hope that this is just an example of what we can expect from you in the future.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 49, 'm7d', 'We''re receiving requests for additional conscripts from the Corporate Sector Authority. Our detention facilities are overflowing, so our solution is clear. Prisoners are to be transported immediately to the CSA''s processing facilities. Pick up and deliver the instructions to the local warden.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 53, 'm7r', 'I hope these quotas call for large numbers of prisoners, because we''ve got them to spare.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 54, 'm7p', 'Building and maintaining the Imperial war machine takes many strong backs. Rebel backs will do nicely.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 55, 'm7t', 'Clear Out the Prisons'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 56, 'm7s', 'Efficient and prompt. Good. That is what the Empire expects from its loyal citizens.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 57, 'm8d', 'A recent list of suspects includes senatorial aides and family members. Local security forces have been reluctant to arrest them without word from Imperial High Command. Pick up and take the arrest warrants to the garrison commander. They''ve been issued by the Ubiqtorate itself.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 61, 'm8r', 'You understand our caution, don''t you? This will clear things up.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 62, 'm8p', 'The influence of many of the Old Republic''s corrupt senators is difficult to dispel.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 63, 'm8t', 'Ubiqtorate Arrest Warrants'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 64, 'm8s', 'Well handled, citizen. Those arrest warrants will be served immediately.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 65, 'm9d', 'We''ve fallen behind schedule due to prisoner riots.We need a boost to our labor force to keep up the Emperor''s aggressive military buildup. Pick up and deliver an order to the local government official for aid in worker recruitment.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 68, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 69, 'm9r', 'I can think of a few layabouts who could be persuaded to serve the Engineer Corps. We''ll get right on it.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 70, 'm9p', 'Sometimes the Emperor asks the impossible. We need more workers!'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 71, 'm9t', 'Recruit Military Workers'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 72, 'm9s', 'You have done well. Continue to serve the Emperor faithfully.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 73, 'm10d', 'We''ve just received an order from General Veers himself at Imperial High Command to train more AT-AT pilots. Pick up and deliver a set of transfers to the garrison commander. These candidates are to go immediately to Imperial training facilities.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 77, 'm10r', 'Always wanted to pilot an AT-AT myself. I''ll see to this at once.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 78, 'm10p', 'I understand that General Veers is serving directly under Lord Vader. A prestigious assignment indeed.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 79, 'm10t', 'Recruit AT-AT Pilots'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 80, 'm10s', 'You''ve done well, citizen. It is the Empire''s hope that you will continue to serve faithfully.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 81, 'm11d', 'We intend to strike Mon Calamari''s floating cities in retaliation for their aid to the Rebellion. Pick up and deliver High Command''s orders to the garrison commander. All shore leave is revoked. All troopers must report to duty at once.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 84, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 85, 'm11r', 'Word will go out immediately. My men will report on time.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 86, 'm11p', 'We waited too long to strike the Mon Calamari. This is long overdue.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 87, 'm11t', 'Strike the Mon Calamari'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 88, 'm11s', 'The Star Destroyer will depart soon. We will make the Mon Calamari pay for their crimes against the Empire.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 89, 'm12d', 'Admiral Ozzel has just informed us that we need to deliver 500 additional probe droids to the Star Destroyer Accuser. Collect and deliver the requisition order to our depot officer. He''ll see to it that those probe droids are loaded aboard a transport.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 93, 'm12r', 'More probe droids? We can hardly keep them in stock. What, or who, are they looking for?'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 94, 'm12p', 'Searching the Galaxy takes time and resources.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 95, 'm12t', 'Probe Droids Search the Galaxy'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 96, 'm12s', 'You''ve done well. The Empire is grateful for your assistance.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 97, 'm13d', 'A former Senator continues to aid the Rebellion. Despite the dissolution of the Senate, this politician''s influence limits our access to his holdings. Collect and deliver a termination order to our Intelligence contact. This mission is to be accomplished "by any means necessary." '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 101, 'm13r', 'Good. I''ve been waiting for a chance to take out this Senator. I think I''ll throw in his annoying family as a bonus.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 102, 'm13p', 'These do-gooders will learn that privileged positions can''t protect them from the Emperor''s wrath.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 103, 'm13t', 'Take Out a Senator'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 104, 'm13s', 'That was a delicate mission, handled discreetly and professionally. The Empire will not forget your efficiency.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 105, 'm14d', 'Insiders helped the Rebellion acquire secret Imperial plans resulting in the deaths of thousands of loyal soldiers. Pick up the dossiers on our prime suspects, and deliver them to an agent of the Bounty Hunters'' Guild. We order a deathmark on every suspect.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 109, 'm14r', 'Business is good for our guild these days. The Battle of Yavin was the Empire''s disgrace and our fortune.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 110, 'm14p', 'We do what we must to ensure the guilty will be brought to justice.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 111, 'm14t', 'Avenge the Death Star'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 112, 'm14s', 'That was handled well, citizen. The Empire will see to it that you are rewarded.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 113, 'm15d', 'We''ve just captured several Rebels who were conducting sabotage missions in the Outer Rim. The Rebels'' resistance to convential interrogation have made drastic action necessary. Collect and deliver a message, for the eyes of an Inquisitor only. We need his skills in interrogation. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 117, 'm15r', 'I leave at once. These Rebels will tell us everything.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 118, 'm15p', 'I can''t wait to watch the Inquisitor at work. They say the sight is a thing of beauty.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 119, 'm15t', 'Summon the Inquisitor'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 120, 'm15s', 'Well done. Your dedication to the Empire is admirable.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 121, 'm16d', 'Intercepted Rebel transmissions are too vital to send via the HoloNet. Collect a copy of these transmissions and deliver them to our Intelligence contact. Deciphering these transmissions will lead us to the Rebel''s new base. The Empire is counting on you. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 125, 'm16r', 'We''ll get right on this. Those Rebels won''t escape us.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 126, 'm16p', 'Information is power, citizen. The Empire''s information network is the best in the galaxy.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 127, 'm16t', 'Intercepted Rebel Transmissions'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 128, 'm16s', 'Prompt delivery and a minimum of fuss. That''s the sort of action the Empire prizes. Well done.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 129, 'm17d', 'We must insure the Corporate Sector Authority is not secretly aiding the Rebel Alliance in exchange for payoffs. We have obtained the security codes to confidential CSA files. Collect them and give them to our covert operative. If he discovers wrongdoing, he is to take appropriate action.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 133, 'm17r', 'Now we''ll see which Viceprexes are smart and which are not.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 134, 'm17p', 'The CSA''s loyalty will always be to money. The Empire should not be so lenient with them.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 135, 'm17t', 'Investigate the CSA'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 136, 'm17s', 'Performed with great professionalism, citizen. The Empire is glad to pay your fee.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 137, 'm18d', 'We''ve discovered a number of CSA Viceprexes who have been aiding Rebels in exchange for money. Collect and deliver termination orders to our operative as soon as possible. We''ll make sure the CSA understands that the Empire does not treat such matters lightly.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 141, 'm18r', 'What good is money if you''re not around to spend it? Too bad these guys didn''t learn that lesson.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 142, 'm18p', 'Money is a powerful motivator, but the threat of death is more powerful still.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 143, 'm18t', 'Bump Off Greedy Businessmen'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 144, 'm18s', 'Excellent work, citizen. The Empire will reward you.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 145, 'm19d', 'Intelligence suspects that a new breed of Jedi has appeared and is aiding the Rebels. Collect Intelligence''s report and deliver it to the Inquisitors. If the Jedi have returned, we must hunt and destroy them once and for all. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 149, 'm19r', 'We will root out these Jedi. They will meet the same fate as their corrupt Old Republic predecessors.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 150, 'm19p', 'If this rumor is true, it would explain the Battle of Yavin.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 151, 'm19t', 'Inquisitors Must Hunt Jedi'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 152, 'm19s', 'As long as loyal citizens such as yourself continue to serve faithfully, the Empire will crush its enemies.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 153, 'm20d', 'We suspect the Mon Calamari are building a vast fleet to support the Rebellion. Collect and deliver Intelligence''s instructions to our operative so that they can organize surveillance missions in preparation for Imperial strikes on Mon Calamari floating cities. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 157, 'm20r', 'This will be an excellent example of Imperial justice, second only to Alderaan.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 158, 'm20p', 'Aiding the Rebellion invokes genocide. All species must support the New Order.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 159, 'm20t', 'Punish the Mon Calamari'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 160, 'm20s', 'The Empire is pleased with your performance, agent. The Mon Calamari will pay for the thousands of Imperial lives lost at Yavin with millions of their own.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 161, 'm21d', 'A Rebel cell has been identified on a remote planet in the Outer Rim. Pick up the report and deliver it to our Imperial Naval contact. This cell must be wiped out immediately. Take no prisoners.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 165, 'm21r', 'I think one Star Destroyer with a full complement of stormtroopers ought to suffice.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 166, 'm21p', 'This assignment requires an Imperial naval captain who is not squeamish.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 167, 'm21t', 'Destroy a Rebel Colony'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 168, 'm21s', 'Your service helps the Imperial war machine run smoothly. You deserve to be rewarded.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 169, 'm22d', 'We''ve been instructed to locate some sort of rare crystal on Mimban. Collect and deliver Intelligence''s instructions to our local agent. He should contact Captain-Supervisor Grammel to secure his help. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 173, 'm22r', 'Mimban? Isn''t that a small mining colony? I will follow these instructions to the letter.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 174, 'm22p', 'We never question the Emperor''s instructions, citizen. Never.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 175, 'm22t', 'Find the Mimban Crystal'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 176, 'm22s', 'We must pursue all leads that might result in the destruction of the Rebellion. Your efforts are noted, citizen.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 177, 'm23d', 'A seller of antiques claims to possess rare Sith artifacts. The Emperor himself has commanded that this individual be arrested and these artifacts confiscated, if they exist. Collect and deliver the warrant to our operative.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 181, 'm23r', 'I was wondering when we''d get around to bringing in this dealer. It''s as good as done.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 182, 'm23p', 'I don''t understand the fascination that old religion holds for Imperial citizens. Superstition, I suppose.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 183, 'm23t', 'Retrieve Sith Artifacts'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 184, 'm23s', 'Job well done, agent. The Emperor will be informed of your assistance.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 185, 'm24d', 'An influential Imperial dignitary has been proven a traitor. He must be removed quietly, in order to avoid alerting his allies. Collect a Scarab assassin droid and deliver it to our agent. We''ve made sure the droid will be traced back to Rebel operatives. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 186, 'm24l', 'Small assassin droid'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 188, 'm24f', 'Filename_of_object'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 189, 'm24r', 'You sure I won''t be implicated in this? This guy''s got a lot of friends on Coruscant.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 190, 'm24p', 'A fitting end for such a vile traitor, wouldn''t you agree?'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 191, 'm24t', 'Scarab Assassin Droid'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 192, 'm24s', 'Well done, agent. Your service to the Empire has been noted, and your future looks rosy indeed.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 193, 'm25d', 'The Emperor wants to know how a Jedi Knight, especially one as dangerous as Obi-Wan Kenobi, could have hidden for so long. Our agent is to turn Tatooine inside out in an effort to answer this question. The Emperor''s instructions are on an encrypted datadisc that you must collect and deliver. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 197, 'm25r', 'I''m sure the Hutts helped hide this fugitive. Those creatures will do anything for money.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 198, 'm25p', 'I certainly hope there aren''t any more Jedi secretly aiding the Rebellion. '),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 199, 'm25t', 'Investigate Tatooine'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 200, 'm25s', 'Trusted agents are hard to find. The Empire wants to insure your continued allegiance by demonstrating how lucrative it can be to serve the Emperor.'),
('string/en/mission/mission_deliver_imperial_hard_non_persistent_from_npc.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_imperial_medium.stf', 1, 'm1d', 'Recruitment is up all across the Galaxy. The Empire''s citizens are demonstrating their loyalty by signing up to serve their Emperor. Deliver the new recruitment documents to the local recruiter and tell him to follow the new manual.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 3, 'm1o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 4, 'm1r', 'My heart swells with pride. Hail the Empire!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 6, 'm1s', 'The Empire''s greatest day is yet to come. And you have played your part, agent.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 7, 'm1p', 'How can the Rebellion win, with so many loyal Imperial citizens around?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 8, 'm1t', 'Recruitment Materials'),
('string/en/mission/mission_deliver_imperial_medium.stf', 9, 'm2d', 'The question we get asked more often than any other is, "How do I become a stormtrooper?" A new pamphlet explains how to enlist with the Imperial Army and join the galaxy''s most elite soldiers. Deliver an electronic copy to our local recruiter so he can distribute it to all those eager young recruits.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 11, 'm2o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 12, 'm2r', 'This pamphlet will no doubt aid recruitment. I''ll start distributing it to every likely candidate.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 14, 'm2s', 'Nothing lures the fresh-faced young graduate into the Imperial Army like the prospect of stormtrooper armor!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 15, 'm2p', 'This renewed interest in the Imperial Army is heartening, isn''t it?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 16, 'm2t', 'How Do I Become a Stormtrooper?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 17, 'm3d', 'Applications to the Imperial Academy have been updated to comply with a new screening process. Take the new applications to our local recruiter and inform him that old applications are to be destroyed. He should already have received the new recruitment materials. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 19, 'm3o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 20, 'm3r', 'Another new screening process? They must be getting too many defections to the Rebellion. At least that hasn''t happened on my watch, yet.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 22, 'm3s', 'Rebellion efforts to infiltrate spies into our ranks start at the Academy. Constant tuning of our admission process will locate spies before they can do an instant''s harm.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 23, 'm3p', 'Here are the applications. If I had a credit for every youngster who told me he wanted to be a TIE pilot --'),
('string/en/mission/mission_deliver_imperial_medium.stf', 24, 'm3t', 'New Academy Applications'),
('string/en/mission/mission_deliver_imperial_medium.stf', 25, 'm4d', 'An Imperial citizen should be all that he can be. And he can do it in the Imperial Army. Deliver the new promotional hologram to our recruiter. The appearance by Lord Vader himself is most inspirational.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 27, 'm4o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 28, 'm4r', 'I''ll enter this data into our recruitment terminals immediately.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 30, 'm4s', 'Imagine getting the chance to serve one day with such a distinguished champion of the Empire as Lord Vader. This will draw new recruits like a magnet.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 31, 'm4p', 'I saw this hologram. Lord Vader''s speech shook me to the marrow.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 32, 'm4t', 'Be All That You Can Be'),
('string/en/mission/mission_deliver_imperial_medium.stf', 33, 'm5d', 'One of our recruiters has had problems with local youth gangs. Deliver to him this requisition order for Dark Eye surveillance droids. Once we have the images of the offenders in action, we''ll dispatch a squad of stormtroopers to handle the situation. It will be a good example for others as well.  '),
('string/en/mission/mission_deliver_imperial_medium.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 35, 'm5o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 36, 'm5r', 'This should wipe the smiles off those hoodlums'' faces.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 37, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 38, 'm5s', 'Youths are enthusiastic. Unfortunately they don''t always channel that energy toward something productive.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 39, 'm5p', 'Those Dark Eye droids look so attractive -- when you get to see them, which isn''t often.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 40, 'm5t', 'Dark Eye Droid Requisition'),
('string/en/mission/mission_deliver_imperial_medium.stf', 41, 'm6d', 'A local garrison commander has requested additional supplies for the troops stationed there. We have approved part of the request. Deliver the adjusted inventory list to him, and inform him that he should be receiving the materials shortly. Any further requests must go through the regular channels.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 43, 'm6o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 44, 'm6r', 'Only part of my request was approved? I hope it was the important parts.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 45, 'm6f_', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 46, 'm6s', 'Making do with what is available -- that is the soldier''s task. That, in fact, is why we hired you; this office''s HoloNet is currently broken.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 47, 'm6p', 'It''s not an easy job running an efficient Imperial war machine.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 48, 'm6t', 'Adjusted Inventory Request'),
('string/en/mission/mission_deliver_imperial_medium.stf', 49, 'm7d', 'We''re providing our recruiters with a demo version of our TIE flight simulators, to help boost enlistment. Deliver this encrypted program and make sure to tell the recruiter to limit the amount of time each visitor gets with the flight sim. We know how addictive these simulators can be. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 51, 'm7o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 52, 'm7r', 'This will certainly boost enlistment. I myself love these flight sims.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 53, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 54, 'm7s', 'The next generation of TIE flight programs will simulate the TIE pilot''s entire tour of duty, including convalescence after injury. This should lure even more recruits.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 55, 'm7p', 'Our TIE flight training programs are a big draw for Imperial citizens.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 56, 'm7t', 'TIE Flight Simulator'),
('string/en/mission/mission_deliver_imperial_medium.stf', 57, 'm8d', 'We''ve redesigned our scout trooper blaster pistol so that it can carry a larger energy cell and deliver a more powerful punch. Pick up the prototype and design specs, and deliver them to a garrison commander for field testing. This is an important military mission. Can we count on you?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 58, 'm8l', 'Prototype blaster pistol and datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 59, 'm8o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 60, 'm8r', 'Amazing how the pistol retained its light weight even with the larger energy cell'),
('string/en/mission/mission_deliver_imperial_medium.stf', 61, 'm8f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_medium.stf', 62, 'm8s', 'Good work, agent. We''ll be keeping our eye on you. You show promise.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 63, 'm8p', 'This pistol is a true credit to the genius of the Imperial Army''s weapons designers.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 64, 'm8t', 'Prototype Scout Pistol'),
('string/en/mission/mission_deliver_imperial_medium.stf', 65, 'm9d', 'We''ve finally identified all the surviving Rebel pilots from the Battle of Yavin, including a Corellian smuggler and his Wookiee companion. Pick up the dossiers and holographs of these individuals. Deliver them to the local garrison commander so that all stormtroopers can keep a sharp eye out for these criminals.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 67, 'm9o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 68, 'm9r', 'Our troopers will arrest this Rebel scum in no time.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 70, 'm9s', 'Fine work. Continue serving the Empire and you will continue to be rewarded.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 71, 'm9p', 'These terrorists are responsible for the deaths of thousands of loyal Imperial officers and troopers.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 72, 'm9t', 'Rebel Holos of Smuggler and Wookiee'),
('string/en/mission/mission_deliver_imperial_medium.stf', 73, 'm10d', 'Imperial Intelligence suggests that recent potential recruits are actually undercover agents for the Rebellion. Pick up the list of names and take it to the garrison commander so these suspects can be arrested for questioning.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 75, 'm10o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 76, 'm10r', 'We do get our fair share of spies. Fortunately, we always root them out.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 78, 'm10s', 'Your service to the Empire is noted, citizen. We hope it will continue.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 79, 'm10p', 'Our recruiters must be especially vigilant. Rebel spies constantly try to infiltrate through their offices.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 80, 'm10t', 'List of Suspected Rebels'),
('string/en/mission/mission_deliver_imperial_medium.stf', 81, 'm11d', 'We''ve just finished our latest promotional hologram. It shows Star Destroyers destroying Rebel bases in the Outer Rim and bringing order to several remote settlements. Deliver a recording to our public relations officer for distribution to all authorized local media. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 83, 'm11o', 'Imperial Navy: Public Relations Division'),
('string/en/mission/mission_deliver_imperial_medium.stf', 84, 'm11r', 'I''ve been wanting to see this hologram for some time now. Glad we finally have it.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 85, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 86, 'm11s', 'Make sure you see that PR hologram yourself, citizen. It''s very inspirational.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 87, 'm11p', 'I appear briefly in the background of the hologram. A proud moment for me.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 88, 'm11t', 'Public Relations Hologram'),
('string/en/mission/mission_deliver_imperial_medium.stf', 89, 'm12d', 'A design flaw in older helmet comlinks allows certain transceivers to pick up a trooper''s transmissions. A modification to the comlink chip should take care of the problem. Pick up the adjustment instructions and deliver them to the local garrison commander.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 91, 'm12o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 92, 'm12r', 'You never can be too careful about who''s listening in on what, eh?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 94, 'm12s', 'Fortunately, these older helmets are found mostly on small outposts. You have been compensated for your efforts, citizen.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 95, 'm12p', 'The commander should use this as an opportunity to inventory his garrison.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 96, 'm12t', 'Trooper Helmet Fix'),
('string/en/mission/mission_deliver_imperial_medium.stf', 97, 'm13d', 'Some local merchants have not yet implemented a courtesy military discount. We want to encourage them to institute the standard 30% discount for all goods sold to military personnel. Pick up a friendly reminder hologram and deliver it to the local merchants'' guild liaison so that he can play it at their next business meeting.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 99, 'm13o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 100, 'm13r', 'I''ll play this at the beginning of the meeting. I''m sure there will be no further problems.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 101, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 102, 'm13s', 'The hologram shows stormtroopers commandeering local shops suspected of selling goods to Rebels. Historically this has proven remarkably effective in reminding merchants of their civic duty.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 103, 'm13p', 'These tiny oversights occur every now and again. It takes very little to correct them.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 104, 'm13t', 'Courtesy Military Discount'),
('string/en/mission/mission_deliver_imperial_medium.stf', 105, 'm14d', 'Recent sabotage by Rebel data slicers has confused local garrisons. Pick up a set of encrypted orders and deliver them to the local commander. Inform him that he will receive orders in this manner until Imperial Intelligence can once again secure the HoloNet.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 107, 'm14o', 'Imperial Armed Forces'),
('string/en/mission/mission_deliver_imperial_medium.stf', 108, 'm14r', 'Good. This should clarify things a bit. These Rebels are a definite thorn in our side.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 110, 'm14s', 'Well done. I hope that this is just an example of what we can expect from you in the future.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 111, 'm14p', 'I''ve always preferred hand-delivered orders. Don''t you agree?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 112, 'm14t', 'Orders for Improved Security'),
('string/en/mission/mission_deliver_imperial_medium.stf', 113, 'm15d', 'For their exemplary duty in arresting Rebel sympathizers and informants, we''d like to reward our troops by having you pick up voucher cards and deliver them to the local garrison. They''re good for up to 200 credits at all cooperative local restaurants and shops. Do not attempt to use these vouchers yourself, or it will go badly for you.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 114, 'm15l', 'Container of datadiscs'),
('string/en/mission/mission_deliver_imperial_medium.stf', 115, 'm15o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 116, 'm15r', 'The troops will definitely appreciate this.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 117, 'm15f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_medium.stf', 118, 'm15s', 'Stormtroopers deserve some R&R every now and again, wouldn''t you agree?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 119, 'm15p', 'The Empire takes care of its own.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 120, 'm15t', 'Stormtrooper Vouchers'),
('string/en/mission/mission_deliver_imperial_medium.stf', 121, 'm16d', 'We''re receiving requests for additional conscripts from the Corporate Sector Authority. Our detention facilities are overflowing, so our solution is clear. Prisoners are to be transported immediately to the CSA''s processing facilities. Pick up the instructions and deliver them to the local warden.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 123, 'm16o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 124, 'm16r', 'I hope these quotas call for large numbers of prisoners, because we''ve got them to spare.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 126, 'm16s', 'You have done well. We''re putting those Rebel sympathizers to good use!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 127, 'm16p', 'Building and maintaining the Imperial war machine takes many strong backs. Rebel backs will do nicely.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 128, 'm16t', 'Prison Worker Quotas'),
('string/en/mission/mission_deliver_imperial_medium.stf', 129, 'm17d', 'Rebel raids on Imperial depots continue unabated. We''ve ordered tracking beacons planted in hundreds of blasters, energy cells, and medical scanners so that these supplies can be shipped to the likely target of the next Rebel attack. Pick up the transport order and deliver it to our liaison to the SoroSuub Corporation, which has produced this special equipment. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 131, 'm17o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_medium.stf', 132, 'm17r', 'This shipment will leave on the next available transport. The Rebels will discover the hazards of stealing our equipment.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 134, 'm17s', 'These trackers should be undetectable unless the entire device is dismantled and each part scanned individually -- more work than most Rebel cells will do. Good work!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 135, 'm17p', 'The depot location is on this encrypted disc and should be shared with no one. This is a mission of the highest priority.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 136, 'm17t', 'Plant Tracking Beacons'),
('string/en/mission/mission_deliver_imperial_medium.stf', 137, 'm18d', 'A high-ranking representative of Sienar Fleet Systems may be visiting this system soon. We want this representative treated with the greatest respect and shown every courtesy by the local government. Deliver the request personally to our public relations officer, and have him inform local officials of the forthcoming visit.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 139, 'm18o', 'Imperial Navy Public Relations'),
('string/en/mission/mission_deliver_imperial_medium.stf', 140, 'm18r', 'This representative will receive the best treatment. The Empire can count on me.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 141, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 142, 'm18s', 'The Sienar Fleet representative was waylaid and captured by Rebels. The visit has been cancelled. That is all.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 143, 'm18p', 'It pays to have the Empire''s gratitude.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 144, 'm18t', 'Sienar Fleet Rep Visit'),
('string/en/mission/mission_deliver_imperial_medium.stf', 145, 'm19d', 'Imperial Intelligence has identified possible sites for the Rebellion''s next base of operations. One of these worlds is near our own. Deliver these orders to the garrison commander. He must retain the minimum number of troops necessary for planetary security and immediately reassign the rest to the Star Destroyer flagship Executor. It will enter standard orbit shortly.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 147, 'm19o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 148, 'm19r', 'So I''m just supposed to depopulate my entire garrison? Ahh, well. Long live the Empire.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 149, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 150, 'm19s', 'The Executor has been diverted to handle an uprising in the Mid-Rim. The local garrison will remain at full strength until further notice.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 151, 'm19p', 'The Executor is a ship to behold. You''d be proud to serve aboard that vessel.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 152, 'm19t', 'Executor Reassignment Orders'),
('string/en/mission/mission_deliver_imperial_medium.stf', 153, 'm20d', 'A recent list of suspects includes senatorial aides and family members. Local security forces have been reluctant to arrest them without word from Imperial High Command. Pick up the arrest warrants and take them to the garrison commander. They''ve been issued by the Ubiqtorate itself.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 155, 'm20o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_medium.stf', 156, 'm20r', 'You understand our caution, don''t you? This will clear things up.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 157, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 158, 'm20s', 'Well handled, citizen. Those arrest warrants will be served immediately.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 159, 'm20p', 'The influence of many of the Old Republic''s corrupt senators is difficult to dispel.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 160, 'm20t', 'Senatorial Arrest Warrants'),
('string/en/mission/mission_deliver_imperial_medium.stf', 161, 'm21d', 'We''ve fallen behind schedule due to prisoner riots. We need a boost to our labor force to keep up the Emperor''s aggressive military buildup. Pick up the order for aid in worker recruitment and deliver it to the local government official.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 163, 'm21o', 'Imperial Army: Corps of Engineers'),
('string/en/mission/mission_deliver_imperial_medium.stf', 164, 'm21r', 'I can think of a few layabouts who could be persuaded to serve the Engineer Corps. We''ll get right on it.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 165, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 166, 'm21s', 'You have done well. Continue to serve the Emperor faithfully.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 167, 'm21p', 'Sometimes the Emperor asks the impossible of us. We need more workers!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 168, 'm21t', 'Labor Force Increase'),
('string/en/mission/mission_deliver_imperial_medium.stf', 169, 'm22d', 'A Moff''s daughter is traveling to our system on a research expedition. Seems she''s a zoology student working on a field guide to the Empire''s reptomammals. The Moff has requested an escort for his daughter, one which we will gladly provide. These are the specifications for the escort. Take them to the garrison commander and make sure the escort is ready in two days.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 171, 'm22o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 172, 'm22r', 'I''ll handpick the men and make sure they are acceptable to the Moff. I hope his daughter finds them acceptable too. If they disagree, it''s hard to know who would win.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 173, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 174, 'm22s', 'Speculation on the opinions of the Moff or his daughter is entirely out of line. Do not spread rumors, or it will go badly for you.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 175, 'm22p', 'I understand this young woman can be a bit -- fussy. I don''t envy the commander this task.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 176, 'm22t', 'Moff''s Daughter Needs Escort'),
('string/en/mission/mission_deliver_imperial_medium.stf', 177, 'm23d', 'Recently a garrison commander assigned an escort to a Moff''s daughter while she conducted a zoological study. The escort proved inadequate. The young woman was wounded while investigating a narglatch den. Deliver this transfer order to the new garrison commander, and inform him that the former commander is to be shipped to Coruscant for court-martial.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 179, 'm23o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 180, 'm23r', 'I''ll make very sure the former commander is on the next transport to Coruscant. I am grateful to the Empire for my recent promotion.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 182, 'm23s', 'The Moff''s daughter will live, fortunately. But the traumatic experience has caused her to abandon her plan to become a zoologist. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 183, 'm23p', 'We should strive to make all Moffs happy.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 184, 'm23t', 'Court-Martial Order'),
('string/en/mission/mission_deliver_imperial_medium.stf', 185, 'm24d', 'We''ve just received an order from General Veers himself at Imperial High Command to train more AT-AT pilots. Pick up a set of transfers and deliver it to the garrison commander. These candidates are to go immediately to Imperial training facilities.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 187, 'm24o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 188, 'm24r', 'Always wanted to pilot an AT-AT myself. I''ll see this at once.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 189, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 190, 'm24s', 'You''ve done well, citizen. It is the Empire''s wish that you continue to serve faithfully.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 191, 'm24p', 'I understand that General Veers is serving directly under Lord Vader. A prestigious assignment indeed.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 192, 'm24t', 'AT-AT Pilots Needed'),
('string/en/mission/mission_deliver_imperial_medium.stf', 193, 'm25d', 'We intend to strike Mon Calamari''s floating cities in retaliation for their aid to the Rebellion. Pick up High Command''s orders and deliver them to the garrison commander. All shore leave is revoked. All troopers must report to duty at once.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 195, 'm25o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 196, 'm25r', 'Word will go out immediately. My men will report on time.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 197, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 198, 'm25s', 'The Star Destroyer will depart soon. We will make the Mon Calamari pay for their crimes against the Empire.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 199, 'm25p', 'We waited too long to strike the Mon Calamari. This is long overdue.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 200, 'm25t', 'Deliver ship-out orders'),
('string/en/mission/mission_deliver_imperial_medium.stf', 201, 'm26d', 'Admiral Ozzel has just informed us that we need to deliver 500 additional probe droids to the Star Destroyer Accuser. Collect the requisition order and deliver it to our depot officer. He''ll see to it that those probe droids are loaded aboard a transport.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 202, 'm26l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 203, 'm26o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 204, 'm26r', 'More probe droids? We can hardly keep them in stock.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 205, 'm26f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 206, 'm26s', 'You''ve done well. The Empire is grateful for your assistance.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 207, 'm26p', 'Searching the Galaxy takes time and resources.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 208, 'm26t', 'Admiral Ozzel''s Probe Droids'),
('string/en/mission/mission_deliver_imperial_medium.stf', 209, 'm27d', 'Imperial Intelligence intercepted a transmission that indicated Rebels might try to sabotage the shipyards at Fondor. Pick up the encrypted orders dispatched by Lord Vader and relay them to our waiting courier. Have him deliver the orders into the hands of Captain Needa of the Star Destroyer Avenger. Hurry. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 210, 'm27l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 211, 'm27o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 212, 'm27r', 'Lord Vader sent these orders? I''ll deliver them to Captain Needa right away! Personally!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 213, 'm27f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 214, 'm27s', 'Tell no one of the nature of your mission, or you will live, briefly, to regret it.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 215, 'm27p', 'Be prompt. My understanding is that Lord Vader is not a forgiving man.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 216, 'm27t', 'Lord Vader''s Orders'),
('string/en/mission/mission_deliver_imperial_medium.stf', 217, 'm28d', 'Troublemakers in outlying systems are protesting the destruction of Alderaan and burning the Emperor in effigy. These demonstrations must be stopped, but only by local security forces. Stormtroopers are not to be used in these situations. These orders come directly from Imperial High Command. Pick them up and deliver them to our HoloNet officer, with instructions to transmit them immediately. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 218, 'm28l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 219, 'm28o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 220, 'm28r', 'I''ll send out the transmission immediately. Will regular encryption suffice?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 221, 'm28f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 222, 'm28s', 'An incident with stormtroopers at one protest led to the deaths of many bystanders. This kind of regrettable accident only foments sympathies for the Rebellion.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 223, 'm28p', 'Stormtroopers should never have been used for urban pacification.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 224, 'm28t', 'No Stormtroopers at Protests'),
('string/en/mission/mission_deliver_imperial_medium.stf', 225, 'm29d', 'SoroSuub''s latest blaster design, the Stormtrooper One, is ready for field testing. Every garrison is receiving fifty of the blasters. Deliver a message to the garrison commander. It gives instructions on how the weapons are to be dispersed among the troops. We expect full reports on the blaster''s performance.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 226, 'm29l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 227, 'm29o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 228, 'm29r', 'I''ve been waiting to see how this blaster performs. The reports will be a pleasure.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 229, 'm29f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 230, 'm29s', 'The Stormtrooper One blaster will carry forward the Empire''s efforts to restore order throughout the galaxy!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 231, 'm29p', 'We''ll see if this is an improvement over BlasTech''s E-11 blaster design.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 232, 'm29t', 'Stormtrooper One Blaster'),
('string/en/mission/mission_deliver_imperial_medium.stf', 233, 'm30d', 'Careful review of Imperial flight records has revealed irregular activity involving a particular shuttle. It appears that the craft has embarked on unscheduled flights to unknown destinations. Pick up the records of these findings and deliver them to our Internal Security officer for futher investigation. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 234, 'm30l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 235, 'm30o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 236, 'm30r', 'This could be the result of a spy in our ranks. We''ll investigate immediately.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 237, 'm30f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 238, 'm30s', 'The Rebellion has gained possession of many Imperial shuttles. In fact, this appears to be the preferred method of defection for low-ranking Imperial officers.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 239, 'm30p', 'We''re not sure how this could have happened. Shuttles don''t just disappear.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 240, 'm30t', 'Imperial Shuttle Flight Anomalies'),
('string/en/mission/mission_deliver_imperial_medium.stf', 241, 'm31d', 'We''ve recently concluded an investigation of unscheduled Imperial shuttle flights. Our findings and recommendations are presented on an encrypted datadisc. Collect it and deliver it to the officer who requested the investigation. Inform him that we will take further action if requested.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 242, 'm31l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 243, 'm31o', 'Imperial Intelligence'),
('string/en/mission/mission_deliver_imperial_medium.stf', 244, 'm31r', 'We''ll study these findings and proceed from there.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 245, 'm31f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 246, 'm31s', 'All Intelligence findings and recommendations are, of course, classified. Tell no one.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 247, 'm31p', 'Congratulate the officer in charge. One can never be too careful about Imperial security.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 248, 'm31t', 'Imperial Shuttle Investigation');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_imperial_medium.stf', 249, 'm32d', 'Having reviewed Internal Security''s findings concerning the most recent unscheduled Imperial shuttle flights, we''ve decided that no further action is necessary at this time. Please deliver this personal thanks to the IntSec officer in charge of the investigation. Assure him that the Moff named in his report will not forget his efficiency and discretion. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 250, 'm32l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 251, 'm32o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 252, 'm32r', 'Thank you. I must remember to send my warmest regards to the Moff''s wife.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 253, 'm32f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 254, 'm32s', 'Thank you, agent. Of course the Moff will also remember your own discretion in this matter.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 255, 'm32p', 'Where a Moff decides to travel is none of our concern. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 256, 'm32t', 'Discretion Regarding a Moff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 257, 'm33d', 'Certain luxury starliners have been transporting goods to Rebel terrorist cells. Imperial High Command orders the Navy to approach and board all starliners. Should they find evidence of Rebel activity, they will arrest all aboard and impound the vessel. Deliver the orders to the garrison commander and instruct him to prepare stormtroopers.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 258, 'm33l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 259, 'm33o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 260, 'm33r', 'These wealthy citizens think they can get away with treason? We''ll put a stop to them.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 261, 'm33f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 262, 'm33s', 'This initiative has the added benefit of improving Imperial revenue through auction of seized vessels. From the Rebellion''s pockets into ours!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 263, 'm33p', 'Our ships will use whatever force necessary to bring in these traitors.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 264, 'm33t', 'Luxury Starliner Seizure'),
('string/en/mission/mission_deliver_imperial_medium.stf', 265, 'm34d', 'We''ll be conducting some military exercises on Tatooine and Alzoc III to better prepare our troops for combat in extreme weather conditions. Imperial Intelligence has reasons to believe the Rebels may be considering planets with such conditions for a future base. Deliver the transfer order to the local garrison commander so that he may assign squads to these exercises.  '),
('string/en/mission/mission_deliver_imperial_medium.stf', 266, 'm34l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 267, 'm34o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 268, 'm34r', 'I know just the troops for such an exercise. I will carry out the order promptly.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 269, 'm34f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 270, 'm34s', 'The latest intelligence indicates the Rebellion has not yet placed its new headquarters. It may be that our program is slightly premature. However, preparation for war is never wasted.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 271, 'm34p', 'There''s a reason our troopers are the most feared in the Galaxy. They can fight everywhere.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 272, 'm34t', 'Send Stormtroopers to Extremes'),
('string/en/mission/mission_deliver_imperial_medium.stf', 273, 'm35d', 'Apparently the example on Dentaal was insufficient for some systems. Deliver a sample "vaccine" to our medical officer. Inform him that he should replicate it and and ship quantities to any system that continues to engage in acts of insurrection. One way or another, the Empire''s authority will be recognized.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 274, 'm35l', 'Cannister'),
('string/en/mission/mission_deliver_imperial_medium.stf', 275, 'm35o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_deliver_imperial_medium.stf', 276, 'm35r', 'I will be most careful with this -- "vaccine."'),
('string/en/mission/mission_deliver_imperial_medium.stf', 277, 'm35f', 'filename_of_object'),
('string/en/mission/mission_deliver_imperial_medium.stf', 278, 'm35s', 'You did not become exposed to the vaccine yourself, correct? It will go badly for you if you did.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 279, 'm35p', 'Make sure the seal on this cannister is not broken.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 280, 'm35t', 'New Imperial "Vaccine"'),
('string/en/mission/mission_deliver_imperial_medium.stf', 281, 'm36d', 'A naval officer who defected to the Rebellion managed to escape our agents. Inquisitors are interrogating his family at a secret detention facility. If we leak its location to Rebel slicers, the officer will attempt a rescue. Pick up the encrypted datadisc with the facility''s location. Deliver it to the garrison commander with instructions to let it fall -- plausibly -- into the Rebellion''s hands.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 282, 'm36l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 283, 'm36o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_deliver_imperial_medium.stf', 284, 'm36r', 'I know the perfect agent for this operation. I''ll see that it''s done.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 285, 'm36f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 286, 'm36s', 'All is well. The commander gave the disk to a stormtrooper, then sent the trooper on patrol near a known Rebel stronghold. Of course the Rebels shot the trooper and plundered the body. This should convince them the information is trustworthy. The officer will soon be back in our hands.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 287, 'm36p', 'The secret location must be leaked in a convincing way, or the Rebels will suspect a trap.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 288, 'm36t', 'Encoded Trap for Imperial Defector'),
('string/en/mission/mission_deliver_imperial_medium.stf', 289, 'm37d', 'Imperial High Command has ordered us to send a reconnaissance team to the Thila system. Deliver instructions to the local scout trooper commander, and see to it that he assembles a team as soon as possible. He is to report findings directly to Admiral Ozzel. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 290, 'm37l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 291, 'm37o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 292, 'm37r', 'We just received our new Aratech speeder bikes. We''ll test them out.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 293, 'm37f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 294, 'm37s', 'The reconnaissance of the Thila system will commence shortly. Good work, agent!'),
('string/en/mission/mission_deliver_imperial_medium.stf', 295, 'm37p', 'What is it with the Rebels and jungle planets?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 296, 'm37t', 'Reconnaissance of Thila System'),
('string/en/mission/mission_deliver_imperial_medium.stf', 297, 'm38d', 'Our officer evaluations have been completed. Deliver this list of names to the local garrison commander. These officers are assigned to exterminate Imperial Navy cruisers in drydock that have been infested with mynocks. We''re sure this will help improve their evaluation scores in the future.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 298, 'm38l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 299, 'm38o', 'Imperial Navy'),
('string/en/mission/mission_deliver_imperial_medium.stf', 300, 'm38r', 'These officers will be delighted when they receive their reassignment orders. Heh, heh.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 301, 'm38f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 302, 'm38s', 'Vermin extermination duty has long been a powerful incentive in the Imperial Navy.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 303, 'm38p', 'The Empire always rewards hard work and strict discipline.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 304, 'm38t', 'Vermin Extermination Duty'),
('string/en/mission/mission_deliver_imperial_medium.stf', 305, 'm39d', 'Imperial Intelligence employs the Bothan SpyNet. Reports indicate the Bothans may be dealing with Rebels as well. We are sending a Star Destroyer to Bothawui to discourage traitorous activities. Meanwhile, every garrison must cease using Bothan informants until Imperial Intelligence has cleared a list of acceptable spies. Deliver the order to the local garrison commander.  '),
('string/en/mission/mission_deliver_imperial_medium.stf', 306, 'm39l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 307, 'm39o', 'Imperial High Command '),
('string/en/mission/mission_deliver_imperial_medium.stf', 308, 'm39r', 'Right. I never trusted those blasted Bothans anyway.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 309, 'm39f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 310, 'm39s', 'The Empire trusts that if you see suspicious conduct by a Bothan, you will report it to Imperial Intelligence immediately.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 311, 'm39p', 'A species that has intrigue and manipulation in its blood will always be a great risk to our security.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 312, 'm39t', 'Bothan Moratorium '),
('string/en/mission/mission_deliver_imperial_medium.stf', 313, 'm40d', 'Certain misguided Imperial officers are circulating a petition favoring the admittance of non-human species into the Imperial military. Deliver our order to the local garrison commander instructing his troops not to sign this petition. Any Imperial soldier whose name appears on this petition will be subject to discipline and possible court-martial.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 314, 'm40l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 315, 'm40o', 'Imperial High Command'),
('string/en/mission/mission_deliver_imperial_medium.stf', 316, 'm40r', 'No one in my garrison will sign any such petition. You have my assurance of that.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 317, 'm40f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 318, 'm40s', 'The misguided officers who circulated the petition have been located and suitably disciplined. All is well.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 319, 'm40p', 'You don''t approve of the petition, do you? Military service is obviously suited only for humans.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 320, 'm40t', 'Deliver warning'),
('string/en/mission/mission_deliver_imperial_medium.stf', 321, 'm41d', 'I have proof that a depot commander has been doctoring records to hide his misappropriation of certain supplies. Deliver my encrypted evidence to him, and inform him that I''ll make sure it does not fall into the wrong hands -- in exchange for a percentage of his profit. I expect an answer within two days. I trust I can count on your discretion?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 322, 'm41l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 323, 'm41o', 'An Intelligence Officer'),
('string/en/mission/mission_deliver_imperial_medium.stf', 324, 'm41r', 'Argh. I''ll respond within the given time.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 325, 'm41f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 326, 'm41s', 'Remember, agent, I know more about you than you do about me. Discretion is essential.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 327, 'm41p', 'It pays to have friends in high places.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 328, 'm41t', 'Blackmail Notice'),
('string/en/mission/mission_deliver_imperial_medium.stf', 329, 'm42d', 'An officer recently tried to blackmail me, claiming I had stolen Imperial property. I need this response from Internal Security deliverd to him as soon as possible. I''m sure he''s most eager to receive a response. You had best hurry. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 330, 'm42l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 331, 'm42o', 'An Imperial Naval Officer'),
('string/en/mission/mission_deliver_imperial_medium.stf', 332, 'm42r', 'This is an order from Internal Security to appear on Coruscant. What''s the meaning of this?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 333, 'm42f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 334, 'm42s', 'The officer in question is now en route to Coruscant. All is well.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 335, 'm42p', 'Tell this loyal servant of the Empire that if he doesn''t appear promptly, an arrest warrant will be issued.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 336, 'm42t', 'Summons to Coruscant'),
('string/en/mission/mission_deliver_imperial_medium.stf', 337, 'm43d', 'Deliver this deathmark to the local liaison to the Bounty Hunters'' Guild. The target has gravely insulted me, yet refuses to meet me in an honorable duel. One way or another, I''ll have my satisfaction. This matter must be conducted with discretion. Can I rely on you?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 338, 'm43l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 339, 'm43o', 'An Imperial Army Officer'),
('string/en/mission/mission_deliver_imperial_medium.stf', 340, 'm43r', 'A bounty hunter will handle this coward soon enough.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 341, 'm43f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 342, 'm43s', 'I expect that the Bounty Hunters'' Guild will execute the deathmark with its customary efficiency. Thank you for your discretion in this matter.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 343, 'm43p', 'I would have been the offended party''s second in the duel. Some matters of honor must be settled outside normal channels.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 344, 'm43t', 'Discreet Deathmark'),
('string/en/mission/mission_deliver_imperial_medium.stf', 345, 'm44d', 'I have been grievously insulted by a fellow officer and demand satisfaction. I need this formal challenge delivered to him immediately. It gives all the specifics of the duel. I expect to receive a prompt response.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 346, 'm44l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 347, 'm44o', 'An Imperial Naval Officer'),
('string/en/mission/mission_deliver_imperial_medium.stf', 348, 'm44r', 'These Generationals and their ridiculous notions of honor. Tell this lunatic to go suck a mynock. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 349, 'm44f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 350, 'm44s', 'This insult must be avenged. I have no recourse but to go to the Bounty Hunters'' Guild.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 351, 'm44p', 'Tell this honorless anooba that my friend looks forward to bathing his vibrorapier in blood.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 352, 'm44t', 'Challenge to a Duel'),
('string/en/mission/mission_deliver_imperial_medium.stf', 353, 'm45d', 'A squad of storm commandos will arrive soon to train the local troops. Pick up our encrypted orders and deliver them to the local garrison commander. He is to cooperate fully with the commander of the special squad. Any questions regarding this training should be directed to Imperial Intelligence.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 354, 'm45l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 355, 'm45o', 'Imperial High Command'),
('string/en/mission/mission_deliver_imperial_medium.stf', 356, 'm45r', 'Storm commandos? Hmm. The men should find this very educational.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 357, 'm45f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 358, 'm45s', 'The storm commandos were unexpectedly diverted to help combat an insurrection in the Outer Rim Territories. The training has been postponed.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 359, 'm45p', 'We expect the commando training to last several days.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 360, 'm45t', 'Storm Commando Training'),
('string/en/mission/mission_deliver_imperial_medium.stf', 361, 'm46d', 'Imperial Intelligence has finally released hologram recordings of the Battle of Yavin, transmitted via the HoloNet just prior to the destruction of the Death Star. Deliver this encrypted copy of the holograms to the local garrison commander so he can play them for local troops.   '),
('string/en/mission/mission_deliver_imperial_medium.stf', 362, 'm46l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 363, 'm46o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 364, 'm46r', 'Thank you. Our men need to see the devastation inflicted by those Rebel scum.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 365, 'm46f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 366, 'm46s', 'Many men lost family members and friends aboard that space station, and we feel this hologram will help them find closure.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 367, 'm46p', 'Up to now we''ve used these holos to help train TIE pilots and develop new fighter designs. Now the recordings should spur the troops to further action against suspected Rebels.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 368, 'm46t', 'Hologram of Yavin Battle'),
('string/en/mission/mission_deliver_imperial_medium.stf', 369, 'm47d', 'Slave revolts on Balmorra have slowed down the production of armaments. Imperial High Command wants this situation corrected. Deliver transfer orders to the garrison commander. The specified force must make ready for immediate transport to Balmorra.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 370, 'm47l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 371, 'm47o', 'Imperial Army'),
('string/en/mission/mission_deliver_imperial_medium.stf', 372, 'm47r', 'I''ll see to it that these orders are carried out.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 373, 'm47f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 374, 'm47s', 'These slave revolts are annoyingly frequent. With sufficient force we can stop them once and for all.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 375, 'm47p', 'We can''t afford any threats to the steady flow of weapons coming from these important armament plants.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 376, 'm47t', 'Balmorra Troop Transfer'),
('string/en/mission/mission_deliver_imperial_medium.stf', 377, 'm48d', 'A Moff has been implicated in a plot to assassinate the Emperor. Deliver this arrest warrant to the garrison commander and instruct him to escort the Moff to Coruscant as quickly as possible. We don''t want this situation demoralizing our troops, so be sure he keeps it quiet. Only a small arrest squad need know the situation, and they''re to remain on Coruscant after they''ve delivered the Moff.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 378, 'm48l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 379, 'm48o', 'Imperial High Command'),
('string/en/mission/mission_deliver_imperial_medium.stf', 380, 'm48r', 'This Moff is influential. I can understand the need for silence.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 381, 'm48f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 382, 'm48s', 'Tell no one of the arrest of the Moff, or you will be subject to the same Imperial justice.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 383, 'm48p', 'Political ambition and the desire for power can destroy an otherwise loyal Imperial servant.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 384, 'm48t', 'Moff Arrest Warrant '),
('string/en/mission/mission_deliver_imperial_medium.stf', 385, 'm49d', 'You must pick up a high-priority message and deliver it to an Imperial admiral''s aide. This message carries the seal of the Moff. Speed and absolute discretion are required. Execute this task promptly.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 386, 'm49l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 387, 'm49o', 'Office of the Moff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 388, 'm49r', 'I''ll personally make sure the admiral receives this.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 389, 'm49f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 390, 'm49s', 'Tell no one of this mission. The Moff''s business is not for casual conversation.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 391, 'm49p', 'Be sure this gets into the right hands. The fate of the Empire may depend on it.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 392, 'm49t', 'The Moff''s Highest Priority'),
('string/en/mission/mission_deliver_imperial_medium.stf', 393, 'm50d', 'An encoded message from an unknown source claims that a secret cell of Jedi Knights has been discovered on Dathomir. We understand that a Jedi played an important role in the destruction of the Death Star. We can''t afford to ignore this message. Deliver these orders to the garrison commander. He must assign a squad of storm commandos to investigate this claim. '),
('string/en/mission/mission_deliver_imperial_medium.stf', 394, 'm50l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium.stf', 395, 'm50o', 'Imperial High Command'),
('string/en/mission/mission_deliver_imperial_medium.stf', 396, 'm50r', 'If they''re on Dathomir, we''ll find them. Personally, I think all those Jedi stories are just children''s tales.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 397, 'm50f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium.stf', 398, 'm50s', 'Our officers seem disgracefully ignorant regarding the dimension of the Jedi threat. We shall remedy this through diligent re-education. We trust that you do not share that ignorance, agent.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 399, 'm50p', 'We must prevent the return of the Jedi at all costs.'),
('string/en/mission/mission_deliver_imperial_medium.stf', 400, 'm50t', 'Jedi Knights on Dathomir?'),
('string/en/mission/mission_deliver_imperial_medium.stf', 401, 'number_of_entries', '50'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 1, 'm1d', 'We''re providing our recruiters with a demo version of our TIE flight simulators, to help boost enlistment. Pick up and deliver the encrypted program. Tell the recruiter to limit the amount of time each visitor gets with the flight sim. We know those simulators can be addictive. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 5, 'm1r', 'This will certainly boost enlistment. I love these flight sims.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 6, 'm1p', 'Our TIE flight training programs are a big draw for Imperial citizens.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 7, 'm1t', 'Help Imperial Recruitment'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 8, 'm1s', 'Well done. The Empire has compensated you.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 9, 'm2d', 'We''ve redesigned our scout trooper blaster pistol so that it can carry a larger energy cell and deliver a more powerful punch. Pick up the prototype and design specs, and deliver them to a garrison commander for field testing. This is an important military mission. Can we count on you?'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 10, 'm2l', 'Trooper pistol'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 12, 'm2f__', 'Filename_of_object'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 13, 'm2r', 'Amazing how the pistol retained its light weight even with the larger energy cell.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 14, 'm2p', 'This pistol is a true credit to the genius of the Imperial Army''s weapon designers.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 15, 'm2t', 'Help Test Prototype Pistol'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 16, 'm2s', 'Good work, agent. We''ll be keeping our eye on you. You show promise.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 17, 'm3d', 'We''ve finally identified all the surviving Rebel pilots from the Battle of Yavin, including a Corellian smuggler and his Wookiee companion. Pick up their dossiers and take them to the local garrison commander. All stormtroopers will keep a sharp eye out for these enemies of the state.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 21, 'm3r', 'Our troopers will arrest this Rebel scum in no time.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 22, 'm3p', 'These terrorists are responsible for the deaths of thousands of loyal Imperial officers and troopers. We trust they will be arrested soon.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 23, 'm3t', 'Find the Traitors of Yavin'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 24, 'm3s', 'Fine work. Continue serving the Empire and you will continue to be rewarded.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 25, 'm4d', 'Imperial Intelligence suggests that recent potential recruits are actually undercover agents for the Rebellion. Pick up the list of names and take it to the garrison commander so these suspects can be arrested for questioning.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 29, 'm4r', 'We do get our fair share of spies. Fortunately, we always root them out.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 30, 'm4p', 'Our recruiters must be especially vigilant. Rebel spies constantly try to infiltrate through their offices.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 31, 'm4t', 'Potential Recruits Are Often Spies'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 32, 'm4s', 'Your service to the Empire is noted, citizen. We hope it will continue.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 33, 'm5d', 'A design flaw in older helmet comlinks allows certain transceivers to pick up a trooper''s transmissions. A modification to the comlink chip should take care of the problem. Fortunately, these older helmets are found mostly on small outposts. Pick up the adjustment instructions and deliver them to the local garrison commander. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 37, 'm5r', 'You can never be too careful about who''s listening in on what, eh?'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 38, 'm5p', 'Here you are. The commander should also use this opportunity to do an inventory of his garrison.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 39, 'm5t', 'Fix Trooper Helmets'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 40, 'm5s', 'Well done, citizen. You''ve been compensated for your efforts.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 41, 'm6d', 'Recent sabotage by Rebel data slicers has confused local garrisons. Pick up and deliver some encrypted orders to the local commander. Inform him that he will receive orders in this manner until Imperial Intelligence can once again secure the HoloNet.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 45, 'm6r', 'Good. This should clarify things a bit. These Rebels are a definite thorn in our side.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 46, 'm6p', 'I''ve always preferred hand-delivered orders. Nothing beats the extra security.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 47, 'm6t', 'Improved Imperial Security'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 48, 'm6s', 'Well done. I hope that this is just an example of what we can expect from you in the future.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 49, 'm7d', 'We''re receiving requests for additional conscripts from the Corporate Sector Authority. Our detention facilities are overflowing, so our solution is clear. Prisoners are to be transported immediately to the CSA''s processing facilities. Pick up and deliver the instructions to the local warden.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 53, 'm7r', 'I hope these quotas call for large numbers of prisoners, because we''ve got them to spare.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 54, 'm7p', 'Building and maintaining the Imperial war machine takes many strong backs. Rebel backs will do nicely.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 55, 'm7t', 'Clear Out the Prisons'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 56, 'm7s', 'Efficient and prompt. Good. That is what the Empire expects from its loyal citizens.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 57, 'm8d', 'A recent list of suspects includes senatorial aides and family members. Local security forces have been reluctant to arrest them without word from Imperial High Command. Pick up and take the arrest warrants to the garrison commander. They''ve been issued by the Ubiqtorate itself.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 61, 'm8r', 'You understand our caution, don''t you? This will clear things up.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 62, 'm8p', 'The influence of many of the Old Republic''s corrupt senators is difficult to dispel.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 63, 'm8t', 'Ubiqtorate Arrest Warrants'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 64, 'm8s', 'Well handled, citizen. Those arrest warrants will be served immediately.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 65, 'm9d', 'We''ve fallen behind schedule due to prisoner riots.We need a boost to our labor force to keep up the Emperor''s aggressive military buildup. Pick up and deliver an order to the local government official for aid in worker recruitment.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 68, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 69, 'm9r', 'I can think of a few layabouts who could be persuaded to serve the Engineer Corps. We''ll get right on it.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 70, 'm9p', 'Sometimes the Emperor asks the impossible. We need more workers!'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 71, 'm9t', 'Recruit Military Workers'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 72, 'm9s', 'You have done well. Continue to serve the Emperor faithfully.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 73, 'm10d', 'We''ve just received an order from General Veers himself at Imperial High Command to train more AT-AT pilots. Pick up and deliver a set of transfers to the garrison commander. These candidates are to go immediately to Imperial training facilities.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 77, 'm10r', 'Always wanted to pilot an AT-AT myself. I''ll see to this at once.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 78, 'm10p', 'I understand that General Veers is serving directly under Lord Vader. A prestigious assignment indeed.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 79, 'm10t', 'Recruit AT-AT Pilots'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 80, 'm10s', 'You''ve done well, citizen. It is the Empire''s hope that you will continue to serve faithfully.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 81, 'm11d', 'We intend to strike Mon Calamari''s floating cities in retaliation for their aid to the Rebellion. Pick up and deliver High Command''s orders to the garrison commander. All shore leave is revoked. All troopers must report to duty at once.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 84, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 85, 'm11r', 'Word will go out immediately. My men will report on time.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 86, 'm11p', 'We waited too long to strike the Mon Calamari. This is long overdue.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 87, 'm11t', 'Strike the Mon Calamari'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 88, 'm11s', 'The Star Destroyer will depart soon. We will make the Mon Calamari pay for their crimes against the Empire.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 89, 'm12d', 'Admiral Ozzel has just informed us that we need to deliver 500 additional probe droids to the Star Destroyer Accuser. Collect and deliver the requisition order to our depot officer. He''ll see to it that those probe droids are loaded aboard a transport.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 93, 'm12r', 'More probe droids? We can hardly keep them in stock. What, or who, are they looking for?'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 94, 'm12p', 'Searching the Galaxy takes time and resources.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 95, 'm12t', 'Probe Droids Search the Galaxy'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 96, 'm12s', 'You''ve done well. The Empire is grateful for your assistance.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 97, 'm13d', 'A former Senator continues to aid the Rebellion. Despite the dissolution of the Senate, this politician''s influence limits our access to his holdings. Collect and deliver a termination order to our Intelligence contact. This mission is to be accomplished "by any means necessary." '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 101, 'm13r', 'Good. I''ve been waiting for a chance to take out this Senator. I think I''ll throw in his annoying family as a bonus.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 102, 'm13p', 'These do-gooders will learn that privileged positions can''t protect them from the Emperor''s wrath.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 103, 'm13t', 'Take Out a Senator'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 104, 'm13s', 'That was a delicate mission, handled discreetly and professionally. The Empire will not forget your efficiency.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 105, 'm14d', 'Insiders helped the Rebellion acquire secret Imperial plans resulting in the deaths of thousands of loyal soldiers. Pick up the dossiers on our prime suspects, and deliver them to an agent of the Bounty Hunters'' Guild. We order a deathmark on every suspect.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 109, 'm14r', 'Business is good for our guild these days. The Battle of Yavin was the Empire''s disgrace and our fortune.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 110, 'm14p', 'We do what we must to ensure the guilty will be brought to justice.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 111, 'm14t', 'Avenge the Death Star'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 112, 'm14s', 'That was handled well, citizen. The Empire will see to it that you are rewarded.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 113, 'm15d', 'We''ve just captured several Rebels who were conducting sabotage missions in the Outer Rim. The Rebels'' resistance to convential interrogation have made drastic action necessary. Collect and deliver a message, for the eyes of an Inquisitor only. We need his skills in interrogation. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 117, 'm15r', 'I leave at once. These Rebels will tell us everything.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 118, 'm15p', 'I can''t wait to watch the Inquisitor at work. They say the sight is a thing of beauty.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 119, 'm15t', 'Summon the Inquisitor'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 120, 'm15s', 'Well done. Your dedication to the Empire is admirable.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 121, 'm16d', 'Intercepted Rebel transmissions are too vital to send via the HoloNet. Collect a copy of these transmissions and deliver them to our Intelligence contact. Deciphering these transmissions will lead us to the Rebel''s new base. The Empire is counting on you. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 125, 'm16r', 'We''ll get right on this. Those Rebels won''t escape us.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 126, 'm16p', 'Information is power, citizen. The Empire''s information network is the best in the galaxy.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 127, 'm16t', 'Intercepted Rebel Transmissions'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 128, 'm16s', 'Prompt delivery and a minimum of fuss. That''s the sort of action the Empire prizes. Well done.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 129, 'm17d', 'We must insure the Corporate Sector Authority is not secretly aiding the Rebel Alliance in exchange for payoffs. We have obtained the security codes to confidential CSA files. Collect them and give them to our covert operative. If he discovers wrongdoing, he is to take appropriate action.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 133, 'm17r', 'Now we''ll see which Viceprexes are smart and which are not.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 134, 'm17p', 'The CSA''s loyalty will always be to money. The Empire should not be so lenient with them.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 135, 'm17t', 'Investigate the CSA'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 136, 'm17s', 'Performed with great professionalism, citizen. The Empire is glad to pay your fee.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 137, 'm18d', 'We''ve discovered a number of CSA Viceprexes who have been aiding Rebels in exchange for money. Collect and deliver termination orders to our operative as soon as possible. We''ll make sure the CSA understands that the Empire does not treat such matters lightly.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 141, 'm18r', 'What good is money if you''re not around to spend it? Too bad these guys didn''t learn that lesson.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 142, 'm18p', 'Money is a powerful motivator, but the threat of death is more powerful still.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 143, 'm18t', 'Bump Off Greedy Businessmen'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 144, 'm18s', 'Excellent work, citizen. The Empire will reward you.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 145, 'm19d', 'Intelligence suspects that a new breed of Jedi has appeared and is aiding the Rebels. Collect Intelligence''s report and deliver it to the Inquisitors. If the Jedi have returned, we must hunt and destroy them once and for all. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 149, 'm19r', 'We will root out these Jedi. They will meet the same fate as their corrupt Old Republic predecessors.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 150, 'm19p', 'If this rumor is true, it would explain the Battle of Yavin.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 151, 'm19t', 'Inquisitors Must Hunt Jedi'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 152, 'm19s', 'As long as loyal citizens such as yourself continue to serve faithfully, the Empire will crush its enemies.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 153, 'm20d', 'We suspect the Mon Calamari are building a vast fleet to support the Rebellion. Collect and deliver Intelligence''s instructions to our operative so that they can organize surveillance missions in preparation for Imperial strikes on Mon Calamari floating cities. ');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 157, 'm20r', 'This will be an excellent example of Imperial justice, second only to Alderaan.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 158, 'm20p', 'Aiding the Rebellion invokes genocide. All species must support the New Order.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 159, 'm20t', 'Punish the Mon Calamari'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 160, 'm20s', 'The Empire is pleased with your performance, agent. The Mon Calamari will pay for the thousands of Imperial lives lost at Yavin with millions of their own.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 161, 'm21d', 'A Rebel cell has been identified on a remote planet in the Outer Rim. Pick up the report and deliver it to our Imperial Naval contact. This cell must be wiped out immediately. Take no prisoners.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 165, 'm21r', 'I think one Star Destroyer with a full complement of stormtroopers ought to suffice.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 166, 'm21p', 'This assignment requires an Imperial naval captain who is not squeamish.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 167, 'm21t', 'Destroy a Rebel Colony'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 168, 'm21s', 'Your service helps the Imperial war machine run smoothly. You deserve to be rewarded.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 169, 'm22d', 'We''ve been instructed to locate some sort of rare crystal on Mimban. Collect and deliver Intelligence''s instructions to our local agent. He should contact Captain-Supervisor Grammel to secure his help. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 173, 'm22r', 'Mimban? Isn''t that a small mining colony? I will follow these instructions to the letter.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 174, 'm22p', 'We never question the Emperor''s instructions, citizen. Never.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 175, 'm22t', 'Find the Mimban Crystal'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 176, 'm22s', 'We must pursue all leads that might result in the destruction of the Rebellion. Your efforts are noted, citizen.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 177, 'm23d', 'A seller of antiques claims to possess rare Sith artifacts. The Emperor himself has commanded that this individual be arrested and these artifacts confiscated, if they exist. Collect and deliver the warrant to our operative.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 181, 'm23r', 'I was wondering when we''d get around to bringing in this dealer. It''s as good as done.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 182, 'm23p', 'I don''t understand the fascination that old religion holds for Imperial citizens. Superstition, I suppose.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 183, 'm23t', 'Retrieve Sith Artifacts'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 184, 'm23s', 'Job well done, agent. The Emperor will be informed of your assistance.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 185, 'm24d', 'An influential Imperial dignitary has been proven a traitor. He must be removed quietly, in order to avoid alerting his allies. Collect a Scarab assassin droid and deliver it to our agent. We''ve made sure the droid will be traced back to Rebel operatives. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 186, 'm24l', 'Small assassin droid'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 188, 'm24f', 'Filename_of_object'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 189, 'm24r', 'You sure I won''t be implicated in this? This guy''s got a lot of friends on Coruscant.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 190, 'm24p', 'A fitting end for such a vile traitor, wouldn''t you agree?'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 191, 'm24t', 'Scarab Assassin Droid'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 192, 'm24s', 'Well done, agent. Your service to the Empire has been noted, and your future looks rosy indeed.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 193, 'm25d', 'The Emperor wants to know how a Jedi Knight, especially one as dangerous as Obi-Wan Kenobi, could have hidden for so long. Our agent is to turn Tatooine inside out in an effort to answer this question. The Emperor''s instructions are on an encrypted datadisc that you must collect and deliver. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 197, 'm25r', 'I''m sure the Hutts helped hide this fugitive. Those creatures will do anything for money.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 198, 'm25p', 'I certainly hope there aren''t any more Jedi secretly aiding the Rebellion. '),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 199, 'm25t', 'Investigate Tatooine'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 200, 'm25s', 'Trusted agents are hard to find. The Empire wants to insure your continued allegiance by demonstrating how lucrative it can be to serve the Emperor.'),
('string/en/mission/mission_deliver_imperial_medium_non_persistent_from_npc.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_neutral_easy.stf', 1, 'm1d', 'This datadisc holds an important chemical formula that we believe can lead towards a cure to multiple dangerous diseases. It needs to be hand-delivered to medical personnel; we have multiple couriers going out, as well as electronic transmissions. We are taking all necessary precautions because it is completely vital that this reach its destination, do you understand? Thousands or even millions may die.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 4, 'm1r', 'Ah, another copy of the antidote compounds. Fortunately, we received the electronic transmission early on, and were able to contain the outbreak. There''s no danger now. But thank you anyway.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 6, 'm1s', 'The unpredictable nature of this epidemic means there could be other outbreaks. We must be ready!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 7, 'm1p', 'I advise you not to mention the outbreak to anyone; no sense in causing a riot. Deliver this quickly, for lives are at stake.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 8, 'm1t', 'Into the Hot Zone'),
('string/en/mission/mission_deliver_neutral_easy.stf', 9, 'm2d', 'My grandfather recently passed away. After my grandmother died, he always told us stories of his childhood sweetheart, "the one that got away." He would write letters to her, letters that were never sent. Now he''s gone, and I think the right thing to do is have these letters delivered at long last. Can you take the archive to her family? I don''t feel I can face this woman myself.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 12, 'm2r', 'Oh dear. Love letters for my grandmother -- she just passed away yesterday. You''re too late.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 14, 'm2s', 'That''s terrible news. I feel so bad that I waited this long. Possibly if you had got there just a little sooner -- but no, it''s not your fault.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 15, 'm2p', 'Will you take these letters? I don''t feel right walking up to this old lady''s family and handing over these love letters -- I remember my grandmother too well.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 16, 'm2t', 'Old Love Letters'),
('string/en/mission/mission_deliver_neutral_easy.stf', 17, 'm3d', 'I suggest you not look at these images; they are potentially incriminating, and knowledge of their contents could put your name on bounty hunters'' lists throughout the galaxy. Just deliver them, no questions asked, discreetly and quickly. Trust me, I am revealing the horrible corruption at the highest levels of government. But I need your help to do it.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 20, 'm3r', 'Thank you for being a perfect patsy! Now we can arrest the person who sent you for high treason against the Empire. You''re free to go.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 22, 'm3s', 'FROM THE IMPERIAL SECURITY BUREAU: The holder of this account has been detained by the Empire for investigation of criminal activity. Do not attempt to contact the account holder. That is all.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 23, 'm3p', 'Don''t show these documents to anyone. Don''t look at them yourself. And trust me, you''re doing the right thing.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 24, 'm3t', 'Illegal Activity?'),
('string/en/mission/mission_deliver_neutral_easy.stf', 25, 'm4d', 'This refinement to the typical twinline turbo design of the swoop engine flux chamber permits over 700 rotations per second using class C or better material manufacturing processes. We need these experimental blueprints delivered to our agent secretly, so that our competitors get no warning.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 28, 'm4r', 'I hope you were cautious and discreet as you travelled. Thank you for the delivery.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 30, 'm4s', 'This refinement lets us shave almost three credits off typical SKU assembly cost for the mid-sized speeder and swoop engine. This could mean billions of additional credits in a typical revenue cycle. Thank you for your help!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 31, 'm4p', 'Here are the plans for the new engine. Please deliver them promptly, and keep them quiet!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 32, 'm4t', 'New Engine Schematics'),
('string/en/mission/mission_deliver_neutral_easy.stf', 33, 'm5d', 'They''re saying that they may have to arrest our friend because of a lack of identity papers. Well, we have the papers in question, obtained quite legally, I assure you. All we need is someone to give them to an arranged intermediary so that the harassment by authorities can stop!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 36, 'm5r', 'Perfect. Now we know exactly whom to arrest. Thanks for being so helpful, citizen -- and remember, the Empire is always watching.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 37, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 38, 'm5s', 'FROM THE IMPERIAL SECURITY BUREAU: The holder of this account has been apprehended on criminal charges. Do not attempt to contact the account holder. Long live the Emperor!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 39, 'm5p', 'Here are the identity documents. Please make sure that they arrive promptly!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 40, 'm5t', 'Important Identity Documents'),
('string/en/mission/mission_deliver_neutral_easy.stf', 41, 'm6d', 'They''re saying that they may have to arrest our friend because of a lack of identity papers. Well, we have the papers in question, obtained quite legally, I assure you. All we need is someone to give them to our friend so that the harassment by authorities can stop!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 44, 'm6r', 'How wonderful! With this, we can save our friend from imprisonment.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 45, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 46, 'm6s', 'Our friend has made it offworld to a safe harbor, thanks to you.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 47, 'm6p', 'Here are the identity documents. Please make sure that they arrive promptly!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 48, 'm6t', 'Important Identity Documents'),
('string/en/mission/mission_deliver_neutral_easy.stf', 49, 'm7d', 'I feel guilty that it has taken this long for this legal document to be delivered. I know that we should not have kept an indentured servant so long, but over time, it felt like we were all one big happy family. But now, we''ve moved away, and well, it''s time for justice to be done and for freedom to have its day.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 52, 'm7r', 'Oh... well, that''s ironic. She ran away yesterday. I guess she couldn''t wait any longer for freedom.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 53, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 54, 'm7s', 'Giving an indenture servant freedom is one thing, but condoning escape only weakens the whole system. I have reported the fugitive to Imperial authorities.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 55, 'm7p', 'I hope our servant gets joy from this.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 56, 'm7t', 'Manumission Documents'),
('string/en/mission/mission_deliver_neutral_easy.stf', 57, 'm8d', 'I can''t tell you what this is about. I''d have you deliver the actual compound, but it would probably explode. Or melt through the world. Or both. Or neither. You know, it''s very unstable. But the commercial applications! Stunning! In any case, we need you to deliver the formula, if you could.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 60, 'm8r', 'Ah, thank you for delivering the formula! We shall test it immediately, and hope it doesn''t blow up.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 61, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 62, 'm8s', 'Evidently the experimental lab blew up. It is unclear whether my compound had anything to do with this. Well, no great breakthrough was ever won easily.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 63, 'm8p', 'Here you go, the datadisc with the formula. I feel sure this compound will prove to have tremendous military and medical applications.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 64, 'm8t', 'Chemical Melts Through Planets'),
('string/en/mission/mission_deliver_neutral_easy.stf', 65, 'm9d', 'We need a confidential courier to deliver these private business communiques. We hope you are up for the job -- normally we use only bonded and qualified couriers, but we''re in a hurry. It is vital that these documents reach their intended destination quickly, as there are millions of credits at stake.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 68, 'm9r', 'Thank you for the delivery.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 70, 'm9s', 'Thank you. When you see the new model Howlrunner emerge from the Empire''s production lines, you can say, "I helped with that."'),
('string/en/mission/mission_deliver_neutral_easy.stf', 71, 'm9p', 'Here are the communiques. They''re encrypted, so don''t bother trying to read the datadisc. The recipient will know how to decrypt them.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 72, 'm9t', 'Private Business Communiques'),
('string/en/mission/mission_deliver_neutral_easy.stf', 73, 'm10d', 'My new solo recording of kloo-horn pieces, including an all-new rendition of the classic "Soaring Banthas at Sunset," is finished. But I need someone to hand-deliver it to my sound engineer. I don''t trust HoloNet compression routines, you know, they''re lossy algorithms that ruin the tone. I''m kind of distracted by a personal crisis, so I really need these tracks taken quick. Be a friend, huh? You''ll love the guys at the mastering joint, they''re smooth.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 76, 'm10r', 'Hey, thanks. That is a good thing, delivering these gonzo sounds. A good thing. -- Uh, sorry, was I saying something? Never mind. Take care, okay? I''ll go check out the vibes on this. Thanks.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 78, 'm10s', 'Thanks, buddy. This recording is going to blow your mind, it''s the best kloo-horn material ever, I swear. My girlfriend says I''m a genius, and she used to write for the music rags, so she should know.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 79, 'm10p', 'If you lose this disc, mister "artiste" is going to have a fit. I don''t know why he doesn''t just transmit the stupid thing. Like compression would make his stupid bleatings sound worse!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 80, 'm10t', 'Solo Kloo-Horn Recording!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 81, 'm11d', 'My grandfather recently passed away. After my grandmother died, he always told us stories of his childhood sweetheart, "the one that got away." He would write letters to her, letters that were never sent. Now he''s gone, and I think the right thing to do is have these letters delivered at long last. Can you take the archive to her family? I don''t feel I can face this woman myself.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 84, 'm11r', 'Love letters for my grandmother, eh? Tell the truth, I am not sure I should deliver them -- well, okay. Who am I to stand in the way of an old romance?'),
('string/en/mission/mission_deliver_neutral_easy.stf', 85, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 86, 'm11s', 'I''ve received a touching note from the "other woman." She was very grateful. You can be proud.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 87, 'm11p', 'Will you take these letters? I don''t feel right walking up to this old lady''s family and handing over these love letters -- I remember my grandmother too well.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 88, 'm11t', 'Old Love Letters'),
('string/en/mission/mission_deliver_neutral_easy.stf', 89, 'm12d', 'My cousin was remembered in my late father''s will. I don''t trust this information over the normal communications channels -- it''s not much of an inheritance, and if I go through the normal channels, it''s bound to be taxed down to zero. I''m asking you to deliver the information regarding the inheritance, and I''m willing to pay a modest fee.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 92, 'm12r', 'Ah, what''s this? An inheritance? Why, thank you so much! I had heard that my uncle passed away, but we were never close. This is quite unexpected!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 94, 'm12s', 'I attach your fee, which pays for services rendered -- and for your reasonable discretion.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 95, 'm12p', 'Here you go. The information about the inheritance is in this datadisc. Please make sure it ends up in my cousin''s hands only!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 96, 'm12t', 'Inheritance Notification'),
('string/en/mission/mission_deliver_neutral_easy.stf', 97, 'm13d', 'I suggest you not look at these images; they are potentially incriminating, and knowledge of their contents could put your name on bounty hunters'' lists throughout the galaxy. Just deliver them, no questions asked, discreetly and quickly. Trust me, I am revealing the horrible corruption at the highest levels of government. But I need your help to do it.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 100, 'm13r', 'What, is this all? Nobody cares about the stupid old scandal. Oh well, I guess it was easy credits for you!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 101, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 102, 'm13s', 'No reply? Well, I''ll keep working to spread the truth!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 103, 'm13p', 'Don''t show these documents to anyone. Don''t look at them yourself. And trust me, you''re doing the right thing.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 104, 'm13t', 'Illegal Activity?'),
('string/en/mission/mission_deliver_neutral_easy.stf', 105, 'm14d', 'Ah, the delicate savory flavor of carefully filleted colo claw fish, with the lightest sauce of fermented blue milk, rockmite honey, and a secret mix of herbs and spices! The aroma as you ladle the broth from a masterfully crafted soup. The explosion of sensations on your tongue, enough to satisfy the greatest gourmands in the galaxy. This is my greatest work in the greatest art of all, the ephemeral art of cookery! And I need you to hand-deliver it to my rival, just so that I can know that he saw it personally, and will weep at the very idea of ever equalling my exquisite mastery!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 108, 'm14r', 'Mmmm, this looks good. I wonder why this guy keeps sending me these great recipes. I wonder if he has the wrong person?'),
('string/en/mission/mission_deliver_neutral_easy.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 110, 'm14s', 'Soon I shall prepare yet another culinary masterpiece. My rival''s ego will endure further unbearable torment! Oh, I am bad, I am bad, but I cannot resist.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 111, 'm14p', 'Be sure to watch as that scoundrel rival cringes! Weeps! Despairs of ever mastering this dish!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 112, 'm14t', 'Colo Claw in Honeyed Spice-Milk'),
('string/en/mission/mission_deliver_neutral_easy.stf', 113, 'm15d', 'My whole livelihood is tied up in this new blaster design -- I''ve spent years perfecting it, and I am positive it will cause a revolution. I don''t trust this design to the HoloNet. There are too many clever slicers looking for industrial secrets. I need you to carry it to the industrialist whom I hope will agree to manufacture it. He says he will have a representative waiting.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 116, 'm15r', 'Another wannabe blaster designer. If you''ve seen one, you''ve seen a million. Well, we''ll look at it and see if it''s any good. Thanks.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 117, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 118, 'm15s', 'Thanks for delivering my blaster design. If it works, you can tell everyone you played a part in revolutionizing blaster technology.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 119, 'm15p', 'Here. Please don''t lose it, and please be careful with it! My whole life is tied up in this blaster design.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 120, 'm15t', 'Blaster Schematics'),
('string/en/mission/mission_deliver_neutral_easy.stf', 121, 'm16d', 'It may seem incredible, but we have become convinced that these ancient stone carvings found on numerous worlds, including even Corellia and Coruscant itself, are in fact of Jawa origin! Should our hypothesis prove true, it will reveal much about the galaxy long, long ago. We need someone to carefully hand-carry local specimens of stone tablets to a lab for analysis.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 123, 'm16o', 'Imperial Archaeological Division'),
('string/en/mission/mission_deliver_neutral_easy.stf', 124, 'm16r', 'Amazing data. Have you heard that the trade routes of the Jawa form a perfect ten-pointed star on the sand? You can sharpen a vibroblade if you leave it at the center.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 126, 'm16s', 'We believe that phonemic analysis of spoken Jawa language, when combined with an analysis of their typical migratory patterns across the sands of Tatooine, reveals a degenerate form of what was once a highly vibrant culture capable of spacefaring, advanced weaponry, and a high degree of cultural attainment. This is so exciting! A major breakthrough in archaeology.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 127, 'm16p', 'Be careful; these three-dimensional scans of the stone tablets are priceless. We''ve made backups, of course, but we need the lab to examine them quickly.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 128, 'm16t', 'Jawas Were Spacefarers!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 129, 'm17d', 'I suggest you not look at these images; they are potentially incriminating, and knowledge of their contents could put your name on bounty hunters'' lists throughout the galaxy. Just deliver them, no questions asked, discreetly and quickly. Trust me, I am revealing the horrible corruption at the highest levels of government. But I need your help to do it.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 132, 'm17r', 'This is incredibly important. With this we can finally expose corruption and malfeasance among Imperial tax agencies. Thank you so much for delivering this!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 134, 'm17s', 'This will shake the foundations of the Empire! And we will remember your role in our breakthrough.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 135, 'm17p', 'Don''t show these documents to anyone. Don''t look at them yourself. And trust me, you''re doing the right thing.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 136, 'm17t', 'Illegal Activity?'),
('string/en/mission/mission_deliver_neutral_easy.stf', 137, 'm18d', 'I don''t think you should look at these passcodes. Are we clear? It might not be healthy. In fact, these might not be passcodes at all. Why don''t you tell yourself they are something silly and harmless, like love letters or recipes or something, okay? Great, just so we understand each other. Be sure you hand them to the right person.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 140, 'm18r', 'We''ve been tracking your progress. We''ve identified you. We know everything important about you. Remember that.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 141, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 142, 'm18s', 'We''ll know if you looked at these codes. And we know where you live. So if you find yourself suddenly dead, you have only yourself to blame.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 143, 'm18p', 'Don''t look at these. Don''t ask what building they''re for. Don''t ask who is hiring you. Don''t ask who is receiving them. Just do as you''re told and get paid.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 144, 'm18t', 'Secret Passcodes'),
('string/en/mission/mission_deliver_neutral_easy.stf', 145, 'm19d', 'This software is confidential and critical. Suffice it to say that it has significant military applications. We need you to hand carry it, at the client''s insistence; they are extremely paranoid about it going over the HoloNet. Please deliver it to their representative at the agreed location.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 148, 'm19r', 'Thanks for delivering the software. How high is your security clearance? All right, never mind.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 149, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 150, 'm19s', 'Thanks, we couldn''t have done it without you. You fee has been deposited.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 151, 'm19p', 'Here''s the software. Please deliver it promptly. And don''t bother trying to run it -- I promise you don''t have the required hardware.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 152, 'm19t', 'Hand-Carry Vital Software'),
('string/en/mission/mission_deliver_neutral_easy.stf', 153, 'm20d', 'I have sold an impregnable warehouse, and I need to hand-deliver keycodes to the structure. I don''t want them on the HoloNet, of course, or some slicer will get access to a valuable piece of real estate -- a triple-A secured facility suitable for biomedical materials, weapons grade research, that sort of thing. I want you to deliver them, by hand, to the purchaser.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 156, 'm20r', 'Thanks! I don''t know why the seller was so concerned about hand-delivering the keycodes. I figure this building will make a great cantina. I don''t plan to ever lock it!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 157, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 158, 'm20s', 'Cantina! Gad!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 159, 'm20p', 'Here are the keycodes. Don''t bother trying to get at them, they''re encrypted. This facility is practically impregnable, I am sure the buyer will be pleased.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 160, 'm20t', 'Secure Warehouse Keycodes'),
('string/en/mission/mission_deliver_neutral_easy.stf', 161, 'm21d', 'I need you to deliver a letter. Here is an excerpt: "I hate you. I never want to see you again. Oooh, you make me so mad. Don''t try to deny you''ve been seeing someone else! I saw you! I hope you get stepped on by an overweight bantha and die! I hope you break out with a terrible skin disease! I can''t believe I ever thought I loved you! HATE HATE HATE!" Be sure to sneer as you deliver it.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 164, 'm21r', 'But -- but -- I''m still in love -- this is all a misunderstanding -- oh no!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 165, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 166, 'm21s', 'My sweetheart called. My stupid letter almost broke up a wonderful romance, and you let me do it! I HATE YOU! HATE HATE HATE!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 167, 'm21p', 'I shouldn''t even bother to send this, but I can''t resist.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 168, 'm21t', 'I Hate Hate Hate You'),
('string/en/mission/mission_deliver_neutral_easy.stf', 169, 'm22d', 'I need you to deliver a party invitation. It''s a private affair; all relevant information is on the datadisc. Just to be clear, you''re not invited -- your sort wouldn''t be welcome there, you really wouldn''t fit in. No offense.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 172, 'm22r', 'Oooh, a party! Great, I can''t wait to show off my new purple peko-peko boa!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 173, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 174, 'm22s', 'Thank you so much. You may hear about the party in HoloNet society news coverage.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 175, 'm22p', 'The party information is on this datadisc. Please be discreet.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 176, 'm22t', 'Private Party Invitation'),
('string/en/mission/mission_deliver_neutral_easy.stf', 177, 'm23d', 'We need to hand-deliver this important policy speech to a local government official -- there''s some big event happening, and the speech needs to be presented then. For some reason, we can''t get through via the regular HoloNet channels, so we''re counting on you to deliver it!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 179, 'm23o', 'Imperial Communications Office'),
('string/en/mission/mission_deliver_neutral_easy.stf', 180, 'm23r', 'Well, the event was cancelled, but thanks for the speech anyway!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 182, 'm23s', 'The event is apparently getting rescheduled. We may need your help again. Thanks!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 183, 'm23p', 'This speech needs to be delivered in advance of the big event. I hope you make it.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 184, 'm23t', 'Important Policy Speech'),
('string/en/mission/mission_deliver_neutral_easy.stf', 185, 'm24d', 'We need you to deliver a summons. Our regular couriers are unavailable, and this case needs prompt investigation. Simply serve the summons, and don''t engage the recipient in any significant conversation -- trust us, it won''t go well.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 187, 'm24o', 'Imperial Circuit Court'),
('string/en/mission/mission_deliver_neutral_easy.stf', 188, 'm24r', 'A summons? What? Hey now, why am I getting a summons?'),
('string/en/mission/mission_deliver_neutral_easy.stf', 189, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 190, 'm24s', 'The recipient has relayed acceptance of the summons, and promises to be indisputably and vocally present in court at the appointed time.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 191, 'm24p', 'Here''s the summons. Just hand it to the recipient and leave. Not much point in talking.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 192, 'm24t', 'Serve a Circuit Summons'),
('string/en/mission/mission_deliver_neutral_easy.stf', 193, 'm25d', 'This is my manuscript of poetry. Here''s a sample: "Like the sight of the peko-peko/Soaring free above the swamps/My love for you hovers, rises, delicate yet strong/And disappears only into the glory of sunsets." I need you to deliver the datadisc to my publisher.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 196, 'm25r', '"Like the sight of the peko-peko"? Oh brother.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 197, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 198, 'm25s', 'I can''t believe this rejection! Not only the rejection itself, never mind that, but the speed of it! Did you say something bad to the publisher?'),
('string/en/mission/mission_deliver_neutral_easy.stf', 199, 'm25p', 'These poems are the expressions of my heart. Be careful with them, please!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 200, 'm25t', 'Unspeakably Sensitive Poetry'),
('string/en/mission/mission_deliver_neutral_easy.stf', 201, 'm26d', 'Well, I finished off my latest batch of scribblings. I barely call them stories, really, hardly worthy of the name. Writers mostly scribble anyhow; aren''t many who have anything worth saying. Anyway, for whatever reason, a publisher wants to see these. So go ahead, take them.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 202, 'm26l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 203, 'm26o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 204, 'm26r', 'Great! This writer is fantastic. It''s a real honor to publish these stories. I only hope that the political content is a little more -- subdued this time.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 205, 'm26f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 206, 'm26s', 'Really, the whole foofaraw over these jottings baffles me. Ah well, life is a mystery.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 207, 'm26p', 'Here you go. If you lose them, I don''t care. Just trifles, after all.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 208, 'm26t', 'Stories and Scribblings'),
('string/en/mission/mission_deliver_neutral_easy.stf', 209, 'm27d', '''Have you ever seen the nocturnal Nexu? Noticed all the different kinds of banthas there are? Now children across the galaxy can learn about amazing animals on a hundred worlds, and in addition see delightful full-color holographs of each beast at work or play.'' That''s what the blurb says, at any rate. Well, I need someone to deliver this mess, and I guess you''re it.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 210, 'm27l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 211, 'm27o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 212, 'm27r', 'Great, we''ll rush this to distribution right away.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 213, 'm27f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 214, 'm27s', 'Now the publisher can shill one more sentimental mess to gullible parents. Gaah, I need a drink.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 215, 'm27p', 'I knocked off the writing duties on this hack job in -- well, I won''t say how quickly, it embarrasses me. Have fun delivering it.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 216, 'm27t', 'Wildlife Research Manuscript'),
('string/en/mission/mission_deliver_neutral_easy.stf', 217, 'm28d', 'My magnum opus, a reference work cataloging the various minerals of the galaxy, is finally complete. Some may call it dry or dull, but it is a grand work of scholarship, and I have been careful to annotate every reference. Every mineral description is accompanied by a holograph of both the mineral itself and of its molecular structure. Now all I need is for you to hand-deliver it to the publisher.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 218, 'm28l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 219, 'm28o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 220, 'm28r', 'Excellent! I imagine that this one will become a bestseller in short order.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 221, 'm28f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 222, 'm28s', 'Thank you. The audience for mineralogical texts across the galaxy is vanishingly small in percentage terms, but in sheer numbers is quite enough to guarantee me a comfortable living.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 223, 'm28p', 'I do hope that you find the time to read my manuscript along the way. I recommend the section on theodolites.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 224, 'm28t', 'Grand Work of Mineralogy'),
('string/en/mission/mission_deliver_neutral_easy.stf', 225, 'm29d', 'I feel guilty that it has taken this long for this legal document to be delivered. I know that we should not have kept an indentured servant so long, but over time, it felt like we were all one big happy family. But now, we''ve moved away, and well, it''s time for justice to be done and for freedom to have its day.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 226, 'm29l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 227, 'm29o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 228, 'm29r', 'What? Can it be? Freedom? Freedom! I am free! Free!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 229, 'm29f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 230, 'm29s', 'I feel much better. I wish our former servant well in whatever pursuit freedom brings.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 231, 'm29p', 'I hope our servant gets joy from this.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 232, 'm29t', 'Manumission Documents'),
('string/en/mission/mission_deliver_neutral_easy.stf', 233, 'm30d', 'Check this thing out! It''s like a hologame, except you play it piggybacking on the Holonet, see? And you play with thousands of other people at the same time. So I have a copy of it here that''s, you know, uh, kind of cracked? And I wanna slip it to my friend so we can play together.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 234, 'm30l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy.stf', 235, 'm30o', ''),
('string/en/mission/mission_deliver_neutral_easy.stf', 236, 'm30r', 'What, this game? Aw, c''mon. The lag time from here to the servers on Coruscant is terrible. Plus the controls are way too hard, especially the camera system.'),
('string/en/mission/mission_deliver_neutral_easy.stf', 237, 'm30f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy.stf', 238, 'm30s', 'Now I''m all down. Turns out the game server checks for cracked copies. It burned out my rig!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 239, 'm30p', 'This game totally rocks. You have like hundreds of species to choose from, and you can be anything from a smuggler to a bounty hunter to a -- shh, don''t tell the Empire -- a Jedi! '),
('string/en/mission/mission_deliver_neutral_easy.stf', 240, 'm30t', 'Wild New Hologame!'),
('string/en/mission/mission_deliver_neutral_easy.stf', 241, 'number_of_entries', '30'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 1, 'm1d', 'I''m submitting my application to the Academy at long last. Won''t my friends be jealous when they hear I''ve become a TIE pilot? But I can''t trust something this important to the HoloNet. Could you pick up my application from my friend''s home and hand-deliver it to a professional courier?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 5, 'm1r', 'Another star jockey wanna-be, eh? All right, I''ll see that it''s delivered to the Academy.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 6, 'm1p', 'My best friend''s future is in your hands. Please be careful and see that it gets to its destination. Thanks!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 7, 'm1t', 'A New TIE Pilot'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 8, 'm1s', 'Thanks, buddy! You''re the kind of friend someone wishes for. I deposited a little something into your account.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 9, 'm2d', 'I was investigating a missing person''s case for a client to discover what had happened to their son. Apparently the young man was on Alderaan when it -- well, you know. His final letters are stored on a datadisc. I regret I can''t deliver the datadisc in person, but I''m keeping a low profile. My investigation attracted some unwanted Imperial attention.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 12, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 13, 'm2r', 'What? This can''t be! A plague upon the Empire! Those assassins don''t deserve our loyalty! Oh, my son! My dear son!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 14, 'm2p', 'Please be sensitive when delivering this message. It will no doubt come as a great shock to the recipient.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 15, 'm2t', 'Missing on Alderaan'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 16, 'm2s', 'Did anyone appear to be following you when you made the delivery? I''d keep a low profile, just in case. Your fee has been transmitted to your account.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 17, 'm3d', 'The happy day has come at last! My only daughter is getting married. Could you pick up the very first holographic invitation from the data engineer and hand-deliver it to my oldest friend? That should make quite an impression.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 21, 'm3r', 'Well, it''s about time! I knew that girl would get hitched sooner or later. Can''t wait to tell the family. Wedding invitations on datadisc. Heh! How times change.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 22, 'm3p', 'Here''s the personalized invitation. This is quite the elaborate presentation, lots of animation and music. Family must be rich.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 23, 'm3t', 'Bring Nuptial News'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 24, 'm3s', 'Thanks for delivering that invitation. My friend was most impressed. I''m not rich, but my daughter''s first -- and, I hope, only -- wedding is worth a splurge.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 25, 'm4d', 'I''ve finished my survey of the Core''s asteroid fields and have charted every known space slug in those sectors. I need someone to pick up the survey datadisc from my lab and deliver it to a representative of the Imperial Science Department''s Biology Division -- they need to double-check my stats before we transmit it to the Imperial Information Center.   '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 29, 'm4r', 'Ah, the survey results! I''ll check these findings immediately. I hope my superiors keep me in mind when assigning scientists to study those space slugs.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 30, 'm4p', 'By delivering this datadisc you are furthering the cause of science. We''re counting on you!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 31, 'm4t', 'Space Slug Survey Map'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 32, 'm4s', 'Thanks for getting that to my colleague so quickly. I''ve deposited your fee for services rendered.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 33, 'm5d', 'My company has just finished logging the inventory of one of our client''s holdings. It''s all been stored on a datadisc that has everything itemized by sale price. The appraisals were done by the most careful and painstaking professionals in the field. Could you pick up the inventory and deliver it to our client?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 37, 'm5r', 'It''s about time! I paid good money for these appraisals, and I expected them to be done long since. I''ll adjust my final payment to the company accordingly.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 38, 'm5p', 'Our client is most eager to receive this datadisc. Please relay our apologies for tardiness, but we wanted to be thorough.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 39, 'm5t', 'Precise Inventories Take Time'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 40, 'm5s', 'Thank you for your prompt service. I understand that our client was a tad upset. We''ll try to smooth things over. Your pay has been deposited.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 41, 'm6d', 'A customer''s daughter is getting married soon, and she needs a dress in a week. Could you pick up the datadisc containing the dress pattern from my customer? Please deliver it to my colleague''s fabric shop so I can be sent the appropriate fabrics. I''m swamped with work and can''t go myself.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 45, 'm6r', 'This will be quite a dress. The pattern calls for some pretty exotic fabrics -- spidersilk saturated with glimmerdust, prismatic zwill, resublimated nanoweave. Hope this customer is rich.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 46, 'm6p', 'It will be a gown fit for a queen. Do please hurry with the delivery. Thank you.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 47, 'm6t', 'Beautiful Bridal Gown'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 48, 'm6s', 'Thank you so much for being prompt. If you ever need clothes, look me up -- once I''m not so swamped, that is.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 49, 'm7d', 'A friend''s child has been sick, stricken with body sores. I know an old family remedy that never fails, regardless of the species afflicted. Could you pick up the datadisc with the recipe for this poultice and the accompanying herbs from a local pharmacist? Then please deliver the goods to my friend.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 53, 'm7r', 'My poor child, how she suffers. I''ll give this remedy a try. Thank you so much for delivering it. I''ll let my friend know if it worked.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 54, 'm7p', 'Apply this poultice three times a day. Remind the customer to make a fresh batch every day, and wrap the unused portion tightly before throwing it out. '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 55, 'm7t', 'Cure for an Ailing Child'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 56, 'm7s', 'My thanks for the prompt delivery. I hope my friend''s child gets better once this remedy is used.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 57, 'm8d', 'I won''t be able to attend my nephew''s birthday celebration this year.  But I made a special holocam recording of me singing his favorite nursery rhymes. Could you pick up the recording and make sure the family gets it in time for the party? Thank you so much.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 61, 'm8r', 'Is this for the birthday boy? I''m helping put together his party. I''m sure he''ll be pleased to get this. Thanks!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 62, 'm8p', 'Just finished editing the holo. It certainly is -- something. I hope the kid likes it.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 63, 'm8t', 'Birthday Gift Is Really Something'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 64, 'm8s', 'I hope my nephew appreciates all my hard work. He can be such a sweet boy if the mood strikes him. Thank you for your help.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 65, 'm9d', 'A miner friend found some crystal deposits while out prospecting in the Outer Rim. He won''t say where exactly he found them. Claims he''s going to get rich or something. He wants me to have some crystal samples analyzed for him. Can you pick up the samples and deliver them to a mineralogist I know?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 66, 'm9l', 'Crystals'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 68, 'm9f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 69, 'm9r', 'Crystals, eh? Sure, I''ll have a look. Prospectors keep dreaming they''ll find another source of Adegan crystals. They used to use those in lightsabers, you know.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 70, 'm9p', 'These might just be worthless rocks. I hope my friend can help me identify them. Oh, does the word ''Adegan'' mean anything to you?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 71, 'm9t', 'Mysterious Crystals'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 72, 'm9s', 'Thanks for delivering those crystals. My friend is always having me check out all sorts of minerals. The mother lode is waiting, somewhere out there.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 73, 'm10d', 'My employer sells antiques to interested buyers. One such collector has paid the proper fee to view my employer''s wares. Could you pick up an encrypted catalog and deliver it? The collector will know how to retrieve the data.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 77, 'm10r', 'The catalog at last! I''ve waited a long time for this. The possibility of Sith artifacts! Can you imagine?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 78, 'm10p', 'Nothing is free, pal.  If you want to look, you gotta pay the fee too. Actually, you probably can''t afford it. Deliver this quick, though, and you might be on your way to earning enough.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 79, 'm10t', 'Antiques Catalog'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 80, 'm10s', 'By the way, the contents of our catalog are confidential. Please respect our privacy.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 81, 'm11d', 'Fleek eels are a prized delicacy that must be kept alive until they''re cooked or else the flavor is greatly diminished. I found a way to preserve the eels so that none of the flavor is lost. I need you to pick up a sample and deliver it promptly to a representative of the Corporate Sector Authority. Their food companies can make millions off my secret recipe!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 82, 'm11l', 'Small container'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 84, 'm11f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 85, 'm11r', 'This sample will be tested, of course. If it fails to meet our taste standards, there will be no compensation. That is, in fact, what we are expecting.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 86, 'm11p', 'I knew all those years my friend spent studying preservatives would pay off. I hope he doesn''t forget me when he''s filthy rich. Please be careful with this delivery!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 87, 'm11t', 'Fleek Eels Soon to Be Preserved'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 88, 'm11s', 'Thanks, citizen! I can''t wait for those CSA chefs to taste those preserved fleek eels and marvel at my genius!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 89, 'm12d', 'Can you keep a secret? I''m a great Jedi Master who used to lead the Jedi Council in the days of the Old Republic. We''re in hiding, waiting for the right moment to destroy the Empire. I need you to pick up a secret message from one of our contacts and deliver it to a fellow Jedi. This is of the greatest importance. Can you handle it?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 93, 'm12r', 'Not this lunatic again! Who is it this time? Last week it was the Emperor. This is just a grocery list, for Corellia''s sake! Poor sod needs professional help. '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 94, 'm12p', 'The fate of the galaxy is in your hands. Know that the Force will be with you, always. Unless you fail. Then you''re bantha fodder. Good luck.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 95, 'm12t', 'The Return of the Jedi?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 96, 'm12s', 'Thank you for serving the interests of the Jedi. Soon we shall come out of hiding and restore the Republic. Honest.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 97, 'm13d', 'I finally managed to sell my old JR-4 swoop. Got a good price for it, too. I need you to pick up the title and deliver it to the new owner. Thanks, buddy!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 101, 'm13r', 'The title! Great! I''ve already started to modify the JR-4. It was in great condition.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 102, 'm13p', 'Here you go. You into speeders and swoops like me and my buddy? Check out the Flare-S swoop if you ever get a chance. Nice.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 103, 'm13t', 'Swoop Title'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 104, 'm13s', 'Thanks for taking care of that for me, buddy. I can''t wait to buy the new TaggeCo Air-2 swoop. Now that''s a sweet ride!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 105, 'm14d', 'Someone wants to buy my vintage blaster collection, including my matching set of MB-450''s. Luxan Personal Armaments is the best, and the Penetrator is the elite of hunting pistols. I have a datadisc -- holographs and detailed specs of everything in my collection -- to be delivered to the buyer. Can you pick it up from my friend?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 109, 'm14r', 'Can''t wait to see what''s on this datadisc. I love blasters. Don''t you? Nothing like the weight of a solid weapon in your hands, eh?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 110, 'm14p', 'My buddy inherited this collection from an uncle. That old-timer was a blaster freak. Wish the old guy had had some lightsabers, you know?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 111, 'm14t', 'Blaster Catalog'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 112, 'm14s', 'Thanks for the delivery. If you ever hear of anyone selling lightsabers, let me know.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 113, 'm15d', 'I once took an interest in genealogy and kept very good records. Now my colleagues think they can use me as a library whenever they wish. Please pick up a copy of my database and deliver it to these annoying scholars. Tell them they can look up the name "Skywalker" themselves. The nerve! '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 117, 'm15r', 'I''m certain the name "Skywalker" is important. It may indeed be the key to solving all of the Empire''s problems! Thank you for bringing this.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 118, 'm15p', 'Please tell this scholar to stop harassing our family or else we shall refuse future requests. Fate of the Empire indeed!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 119, 'm15t', 'Genealogical Studies'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 120, 'm15s', 'My thanks for the prompt delivery. Perhaps now I can get some peace.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 121, 'm16d', 'I''m a private investigator and I''m swamped with work. Could you pick up a datadisc of holographs and deliver it to a client? A little matter of a dark suspicion, one partner for another -- the usual stuff. This encrypted disc will settle the matter for good. Thanks.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 125, 'm16r', 'Finally I''ll know the truth! I''m sure this disc will verify my suspicions. Love hurts, you know.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 126, 'm16p', 'I hope this alleviates my client''s paranoia. Trust is a rare commodity these days.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 127, 'm16t', 'Help a Private Investigator'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 128, 'm16s', 'Thanks for your help. Some days I hate my job, but it''s a living. Speaking of which, your fee has been deposited.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 129, 'm17d', 'You know they used to clone people, right? I''m convinced my friend has been cloned for nefarious purposes. I need you to pick up a datadisc containing holographs of the clone in action, taken by an investigator I hired. Then take the disc to my friend. This will prove I''m right.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 133, 'm17r', 'Sure, I''ll look at the images, but I just wish my friend would accept the truth. I have not been cloned!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 134, 'm17p', 'Here''s the disc. I personally think my client''s friend is just leading a very interesting double life. But I''m not being paid for my opinion, so --'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 135, 'm17t', 'Mistaken identity?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 136, 'm17s', 'Thanks for delivering those pictures. You should make sure you''re not cloned, friend. Otherwise you never know what crimes you might be implicated in.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 137, 'm18d', 'My best friend is about to marry someone unworthy. I hired an investigator to follow the mate-to-be. The investigator has holographs that will prove my friend''s "true love" has been unfaithful. I can''t deliver these myself, or my friend would think I had doctored the images. Can you pick them up and deliver them?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 141, 'm18r', 'What is this? A disc of holographs? What''s on them? Who sent them? Who are you?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 142, 'm18p', 'Here are the holographs. I gotta admit, some of them are rather amusing. But don''t tell my employer I said that.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 143, 'm18t', 'Incriminating Holographs'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 144, 'm18s', 'Thanks for your help. I hope you didn''t mention my name. I''m only trying to save my friend future heartache.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 145, 'm19d', 'I''m a scout for a major music label and don''t have time for amateurs. The vocals on these latest sample tracks sound like the death rattle of a Tatooine meewit. This so-called musician included credits to make sure this ''precious'' recording was returned safely. Could you pick it up and get it out of my life? Don''t try to listen to this mess.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 149, 'm19r', 'They''ve returned my work? Why? Did they like it? Do I have a contract? What''s wrong with these people? They''re Tusken when it comes to music!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 150, 'm19p', 'You gotta listen to a bunch of garbage before you find anyone with even a shred of talent. You don''t play, by any chance?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 151, 'm19t', 'Bad News for a Musician'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 152, 'm19s', 'Thanks for dropping off that cacophonous mangle. I hope the artist goes into a more appropriate line of work, like custodial duty or food service. Your fee is taken care of.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 153, 'm20d', 'I feel guilty that it has taken this long to deliver a legal document. I know that we should not have kept an indentured servant so long, but over time, it felt like we were all one big happy family. Well, it''s time for justice to be done and for freedom to have its day. Can you pick up this document from my family and deliver it?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 157, 'm20r', 'What... can it be? Freedom? Freedom! I am free! Free!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 158, 'm20p', 'Here''s the document. Please inform this individual that they''ll be missed.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 159, 'm20t', 'Free an Indentured Servant'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 160, 'm20s', 'Thanks for getting that done. Next time I''ll be a bit more conscientious about such things.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 161, 'm21d', 'My friends love keeping up with the latest fashions. An acquaintance is putting a whole bunch of facial tattoo patterns on a datadisc for us. Could you please pick up the disc and deliver it to my friend?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 165, 'm21r', 'Wow! Thanks for the disc. I can''t wait to try out these new make-up tips. We''ll be the hit of all the dance clubs. If we ever got to go, that is.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 166, 'm21p', 'It''s important to keep up with fashion, you know. A person''s clothes and make-up say a lot. For example, your clothes speak volumes.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 167, 'm21t', 'Fashionable Facial Tattoos'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 168, 'm21s', 'Thanks for the delivery. Those tattoos are supposedly worn by the Nightsisters of Dathomir. Wouldn''t that be a great name for a band? Maybe we''ll start one. '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 169, 'm22d', 'A friend just got the specs for the newest Ommni Box that''s about to hit the market. This thing can make even the crummiest band sound great. Just what we need! Could you pick up these specs and take them to my band buddy? Once the rest of the band sees this, I know they''ll chip in with me to buy it. Thanks!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 173, 'm22r', 'Let''s see if this toy is as good as my friend claims. If it is, we''ll send you a copy of our first recording. How''s that?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 174, 'm22p', 'The specs are on this datadisc. Tell those wanna-be musicians that this Ommni Box can''t perform miracles. Good luck.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 175, 'm22t', 'Amateur Band Seeks Ommni Box'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 176, 'm22s', 'This Ommni Box is gonna pave the way for our rise to super-stardom. I just know it! You remember me, I''m gonna be famous.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 177, 'm23d', 'I''ve managed to find actual live recordings of krayt dragons. My friend is a naturalist and has been studying krayts for years. A book on the subject is in the works, I understand. Could you pick up the datadisc contains the recordings and drop it off with my friend? I''m sure they''d be most useful.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 181, 'm23r', 'The krayt dragon recordings! This will be such a boon to my research. Thank you so much!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 182, 'm23p', 'I''ve listened to these recordings. Truly amazing stuff. Who knew krayt dragons vocalized to this degree?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 183, 'm23t', 'Help conduct research'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 184, 'm23s', 'I would love to see the look on my friend''s face when these recordings are played. Alas, if only I wasn''t so busy I could pay my friend a visit. Thanks for your help.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 185, 'm24d', 'Why are power converters so hard to find? I''ve looked everywhere. Why does this always happen to me? It''s not fair! I want some power converters! Is that too much to ask? Could you please pick up a purchase order and deliver it to a local supplier for me? I''d go myself, but I have to finish cleaning some droids.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 188, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 189, 'm24r', 'This whiny customer again? I should never have special-ordered those fuel cells. Now I''ll never get any rest. Fine, I''ll get right on it.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 190, 'm24p', 'Here you go. I hope this supplier can fill this order. That farm kid is getting annoying.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 191, 'm24t', 'Get Some Power Converters'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 192, 'm24s', 'Life is so unfair. Did you ever have one of those days? Well that''s my whole life. Why me? Oh, thanks for your help.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 193, 'm25d', 'My friend wants to check out the newest recording by the popular band "Dance Lords of the Bith." If you don''t find yourself moving to this music, you''re probably dead. It''s currently on loan to a neighbor. Could you pick up the recording and deliver it? Can''t wait to hear this at the club. '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 197, 'm25r', 'The Dance Lords! Great! I heard this music is hot jets at the smoothest clubs on Coruscant. Can''t wait to get smooth to its beat. Thanks!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 198, 'm25p', 'There you are. This music moves your spirit, you know? Feel the beat, zoomer!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 199, 'm25t', 'Dance Lords of the Bith!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 200, 'm25s', 'Thanks for your help. We should all strive to give the gift of music. '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 201, 'm26d', 'I was adopted as a child. After years of searching, I think I''ve finally found my real mother. Could you pick up some flowers and deliver them to her, along with an invitation to dinner? I can''t deliver it myself, on the off chance that I''m wrong. Oh, I hope I''m not. Thank you so much for your help.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 202, 'm26l', 'Flowers'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 203, 'm26o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 204, 'm26f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 205, 'm26r', 'Nope, sorry, you got the wrong person. I''ve never been a mother and never hope to be. I may accept the dinner invitation anyway, though. And the flowers are nice.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 206, 'm26p', 'A bouquet of flowers as ordered. Is this for a sweetheart? Oh, you''re doing this for someone else? How nice.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 207, 'm26t', 'Reunite a Family'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 208, 'm26s', 'Thanks so much for giving my mother that invitation. I''m going to make fleek eel soup. It''ll be grand! Too bad you can''t join us.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 209, 'm27d', 'Four-cubes will break you spiritually as well as financially. I need someone to pick up a datadisc from my bookie and deliver it to a fellow player. The disc contains codes to access my credits. They''re all encrypted, so don''t even think about keeping it. Plus, you wouldn''t want to add a Hutt to your list of enemies, would you?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 210, 'm27l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 211, 'm27o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 212, 'm27f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 213, 'm27r', 'Looks like this loser got some common sense. Good. I was about to start hiring bounty hunters.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 214, 'm27p', 'Some beings just don''t know when to leave well enough alone. Why is it that gambling attracts so many folks with bad luck? Anyway, here''s the disc.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 215, 'm27t', 'Pay Off a Hutt'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 216, 'm27s', 'Don''t gamble, friend. Just don''t. It leads to an early grave and heartache while you live. And worry not, I instructed my bookie to deposit your fee. Now I''m totally broke.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 217, 'm28d', 'I''ve finished the definitive work on training hunting twirrls. It should become quite a popular sport among the nobles and the rich on Coruscant. It is, after all, already a distinguished sport on Naboo for persons of higher breeding. Please pick up my manuscript and deliver it to my editor for proofreading.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 218, 'm28l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 219, 'm28o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 220, 'm28f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 221, 'm28r', 'This author''s previous works have always been of superior quality -- always well researched. I can''t wait to peruse this one.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 222, 'm28p', 'Yes, here''s the manuscript. Have you ever tried twirrl hunting? No, I guess you wouldn''t have, would you? Carry on.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 223, 'm28t', 'Popularize Twirrl Hunting'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 224, 'm28s', 'Thank you ever so much for taking care of that. I hope you''ll find my compensation satisfactory. Must run now.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 225, 'm29d', 'My partner has just received a new litter of tusk-cats. A friend of ours wants the pick of the litter. Please pick up a datadisc containing holographs of all the cubs from my partner and deliver it our friend. This will help our friend make a good choice. Thank you.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 226, 'm29l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 227, 'm29o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 228, 'm29f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 229, 'm29r', 'That litter is in already? Splendid! My son has been looking forward to this moment. The cub is for him, you know. '),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 230, 'm29p', 'Nothing like a strong tusk-cat at your side. These are some of the finest from the top kennels in Theed. I''m sure these holographs will demonstrate their quality.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 231, 'm29t', 'Help pick a pet'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 232, 'm29s', 'Thanks for your help, friend. I hope our friend finds something worth purchasing.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 233, 'm30d', 'I have finally found my father''s murderer and have put a price on the killer''s head. However, due to our past, I will give the wretch a fighting chance. I need you to pick up a copy of the hunt certificate and deliver it to the guilty party. That should give this murderer a chance to make all the proper arrangements. I''ve made mine.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 234, 'm30l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 235, 'm30o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 236, 'm30f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 237, 'm30r', 'A deathmark? But I''ve never killed anyone! I''m innocent! This is all a huge mistake!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 238, 'm30p', 'Feel free to tell this individual that you''re only the messenger, not the instrument of death itself.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 239, 'm30t', 'A Deathmark'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 240, 'm30s', 'I know this task was unpleasant, and I appreciate your professionalism in carrying it out.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 241, 'm31d', 'You must help me! My cousin has been falsely accused by some vengeful lunatic of murdering a loved one. I need you to pick up the evidence exonerating him -- a commercial transport manifest dated the day this maniac claims the murder took place. The passenger list proves my cousin was on that ship and couldn''t have murdered anyone!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 242, 'm31l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 243, 'm31o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 244, 'm31f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 245, 'm31r', 'The deathmark has been ordered. This disc proves nothing; records can be falsified. Justice will be served at last.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 246, 'm31p', 'Here''s the disc! Please hurry! Our cousin''s life is in your hands!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 247, 'm31t', 'Help Prove Innocence'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 248, 'm31s', 'Thank you for attending to this matter so quickly! I hope our efforts are enough to save my cousin''s life!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 249, 'm32d', 'My cousin was remembered in my late father''s will. I don''t trust this information over the HoloNet -- it''s not much of an inheritance and is bound to be taxed into oblivion. I''m asking you to pick up a copy of the will and deliver it to my cousin''s family. I''m willing to pay a modest fee.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 250, 'm32l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 251, 'm32o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 252, 'm32f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 253, 'm32r', 'Ah, what''s this? An inheritance? I had heard that my friend''s uncle had passed away. I''ll make sure he gets this when he gets home.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 254, 'm32p', 'Here you go. The information about the inheritance is in this datadisc. Please make sure it ends up in the right hands!'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 255, 'm32t', 'About an Inheritance'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 256, 'm32s', 'Thanks for your help. I think this inheritance will come as a surprise to my cousin.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 257, 'm33d', 'I don''t trust my new blaster design to the HoloNet; there are too many slicers out there on the lookout for industrial secrets. The best way to deliver something confidential is to carry it by hand. I need you to pick up an encrypted datadisc containing my design and carry it to the industrialist whom I hope will agree to manufacture it.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 258, 'm33l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 259, 'm33o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 260, 'm33f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 261, 'm33r', 'Another wannabe blaster designer. If you''ve seen one, you''ve seen a million. Well, we''ll look at it and see if it''s any good. Thanks.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 262, 'm33p', 'Here. Please don''t lose it, and please be careful with it! My friend''s whole life is tied up in this blaster design.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 263, 'm33t', 'Life Tied Up in a Blaster'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 264, 'm33s', 'Thanks for delivering my blaster design. If it works, you can tell everyone you played a part in revolutionizing blaster technology.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 265, 'm34d', 'This software is confidential and critical. Suffice it to say that it has significant military applications. We need you to hand carry it, at the client''s insistence; they are extremely paranoid about it going over the HoloNet. Please deliver it to their representative at the agreed location.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 266, 'm34l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 267, 'm34o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 268, 'm34f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 269, 'm34r', 'Thanks for delivering the software. How high is your security clearance? All right, never mind.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 270, 'm34p', 'Here''s the software. Please deliver it promptly. And don''t bother trying to run it -- I promise you don''t have the required hardware.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 271, 'm34t', 'Deliver critical software'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 272, 'm34s', 'Thanks, buddy, we couldn''t have done it without you. You fee has been deposited.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 273, 'm35d', 'I need someone to pick up a summons and deliver it. My regular runners are not available, and this case needs to be investigated promptly. Simply serve the summons, and don''t engage the recipient in any significant conversation -- trust me, it won''t go well.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 274, 'm35l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 275, 'm35o', ''),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 276, 'm35f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 277, 'm35r', 'A summons? What? Hey now, why am I getting a summons?'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 278, 'm35p', 'Here''s the summons. Just hand it to the recipient and leave. Not much point in talking.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 279, 'm35t', 'Deliver a summons'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 280, 'm35s', 'Thanks for your help. I hope you weren''t given a hard time. Your fee has been taken care of.'),
('string/en/mission/mission_deliver_neutral_easy_non_persistent_from_npc.stf', 281, 'number_of_entries', '35'),
('string/en/mission/mission_deliver_neutral_hard.stf', 1, 'm1d', 'This message is of the greatest importance. My friend has been searching the galaxy for a long-lost love. I''ve just received word that my friend''s love was killed in a transport accident last year. I wish to save my friend further expense and heartache. Please deliver the notice as promptly as possible.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 4, 'm1r', 'What? My love has been killed? No! Say it isn''t so! How can I go on living? Please leave me now.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 5, 'm1f', 'mission\\mission_datadisk.iff');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_neutral_hard.stf', 6, 'm1s', 'mission_success_mail'),
('string/en/mission/mission_deliver_neutral_hard.stf', 7, 'm1p', 'My friend will be quite shaken by this news. Please be sensitive. The search has taken a long time. Thank you.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 8, 'm1t', 'Tragic News'),
('string/en/mission/mission_deliver_neutral_hard.stf', 9, 'm2d', 'I''ve learned that Jabba the Hutt has placed a huge bounty on the head of my friend. Rumor has it that Boba Fett himself has taken an interest. My friend must go into hiding at once. This may well prove a perilous mission. Can you deliver the warning?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 12, 'm2r', 'Boba Fett? After me? Thanks for the warning. I gotta disappear and quick!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard.stf', 14, 'm2s', 'It looks like my friend is going offworld. Way offworld. You can tell that to any bounty hunters you happen to see. Thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 15, 'm2p', 'Careful on your travels. Remember that bounty hunters will be after my friend. If you see Boba Fett, run. Good luck!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 16, 'm2t', 'Jabba Hunts My Friend'),
('string/en/mission/mission_deliver_neutral_hard.stf', 17, 'm3d', 'A friend is trying to buy an ancient Sith artifact. An archeologist I know discovered something of its history and has included the findings on a datadisc. Please collect this disc and deliver it immediately. I hope I''m not too late to save my friend from a terrible fate.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 20, 'm3r', 'Nonsense! The artifact is perfectly safe. Soon the entire galaxy will understand all about the Sith. Begone and trouble me no more, puny mortal.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard.stf', 22, 'm3s', 'I hope you weren''t too late to save my friend from a terrible fate. I must visit soon and see about destroying that artifact.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 23, 'm3p', 'You must warn my friend not to fall asleep with this dreadful artifact in the room. It contains the spirit of an ancient and evil Sith Lord. Go quickly!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 24, 'm3t', 'Warn of Sith Artifact'),
('string/en/mission/mission_deliver_neutral_hard.stf', 25, 'm4d', 'My friend''s father has become deathly ill. For some reason, normal HoloNet messages aren''t getting through -- maybe the Imperial Army imposed one of their blackouts. Please deliver the news, along with this datadisc with directions to the bacta facility holding the father. I hope my friend gets the news before it''s too late.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 28, 'm4r', 'Oh no! This is terrible news! I must contact my father at once. Thank you!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard.stf', 30, 'm4s', 'My friend should make it to the bacta facility in time to have a last long conversation. Thank you.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 31, 'm4p', 'We don''t know how much time the father has left. Please hurry! '),
('string/en/mission/mission_deliver_neutral_hard.stf', 32, 'm4t', 'News of an Illness'),
('string/en/mission/mission_deliver_neutral_hard.stf', 33, 'm5d', 'I finally found a buyer for my centuries-old Core World Arms pulse-blast rifle. Obviously such a valuable item must be hand-delivered. It''s packed securely. This collector travels a lot to dangerous areas, so be on your guard.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 34, 'm5l', 'Antique blaster rifle'),
('string/en/mission/mission_deliver_neutral_hard.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 36, 'm5r', 'Ah, my rifle! Lucky you found me. I was on the next transport out of here. This might come in handy where I''m going. My thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 37, 'm5f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 38, 'm5s', 'I wish I knew how that buyer earns enough credits both to buy antique weapons and also to travel around the galaxy. Hmm, I wonder if one habit explains the other?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 39, 'm5p', 'These adventurers, always planet-hopping! Hope you find this one.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 40, 'm5t', 'Antique Blaster Rifle'),
('string/en/mission/mission_deliver_neutral_hard.stf', 41, 'm6d', 'These nobles and their ridiculous vendettas. A rich client who had been staying with us left his customized dueling vibrorapier in our home. Now the client needs it to settle a matter of honor, or somesuch nonsense. Could you please deliver it quickly? No telling what sort of trouble you might encounter on your travels. This noble has a habit of making enemies.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 42, 'm6l', 'Vibrorapier'),
('string/en/mission/mission_deliver_neutral_hard.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 44, 'm6r', 'Aha! Now at last my honor can be defended. No one accuses me of cheating. No one!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 45, 'm6f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 46, 'm6s', 'I hope my client survives the ordeal. I haven''t been paid yet.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 47, 'm6p', 'I certainly hope you don''t think dueling is honorable. Whatever happened to "forgive and forget"?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 48, 'm6t', 'Dueling Vibrorapier'),
('string/en/mission/mission_deliver_neutral_hard.stf', 49, 'm7d', 'This cargo is delicate, and you must be especially careful with its transport and delivery. A client has purchased a couple of Neimoidian pylat bird eggs. I don''t need to tell you that these are rare and expensive. This animal collector has been looking for these for some time. Get them there whole and you''ll be well-rewarded.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 50, 'm7l', 'Small box'),
('string/en/mission/mission_deliver_neutral_hard.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 52, 'm7r', 'My birds! Well, they''re going to be. Ever heard their song? Enchanting. Thanks so much.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 53, 'm7f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 54, 'm7s', 'I am happy to spread the word of your careful and delicate egg handling. I hope you will consider more work of this kind in the future.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 55, 'm7p', 'These eggs need to be maintained at a constant temperature. The sealed container controls that. Don''t open it. Don''t jostle it. Don''t get into blaster battles if you can help it.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 56, 'm7t', 'Pylat Bird Eggs'),
('string/en/mission/mission_deliver_neutral_hard.stf', 57, 'm8d', 'Our friend''s sister has just given birth! The family would love for my friend to return home at once and see the newborns. Could you pick up a datadisc, which contains pictures of the new family, from my home and deliver it and the good news? Tell my friend to hurry home. Many thanks!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 60, 'm8r', 'This is wonderful news! Thank you! I''ll book the next transport out of here. Those are some cute newborns!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 61, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard.stf', 62, 'm8s', 'Thanks for getting the word to my friend. I hope the pictures were appreciated.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 63, 'm8p', 'I''m sure our friend will want to race home once they see this datadisc. I know it''s a long way to go but it''s for a good cause.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 64, 'm8t', 'Birth Announcement'),
('string/en/mission/mission_deliver_neutral_hard.stf', 65, 'm9d', 'I own a speeder shop and have recently bought out my partner, who''s been away conducting some personal business. Could you pick up a datadisc from my accountant and deliver it to my ex-partner? It contains all the documents showing that my takeover was quite legal. '),
('string/en/mission/mission_deliver_neutral_hard.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 68, 'm9r', 'I can''t be bought out! My grandfather opened that shop! This is an outrage! I''ll go deal with this personally. Maybe with a blaster.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard.stf', 70, 'm9s', 'Purge yourself of sentimentality if you want to run an efficient business. Profits come to those who act quickly and decisively.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 71, 'm9p', 'I''m sure my partner -- or, I should say, "ex-partner" -- will be quite surprised. Leave before you get hurt.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 72, 'm9t', 'Buy-Out News'),
('string/en/mission/mission_deliver_neutral_hard.stf', 73, 'm10d', 'My mate is currently off on another so-called ''adventure.'' Please deliver the news that we are no longer married. I''ve decided to get an annulment. This datadisc contains all the legal documents. '),
('string/en/mission/mission_deliver_neutral_hard.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 76, 'm10r', 'My mate is leaving me? Well, good riddance. I never really felt understood anyway.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard.stf', 78, 'm10s', 'Thanks for your help. I hope my former mate finds happiness, and I regret I was not able to provide it.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 79, 'm10p', 'I knew this union would never work. I should have listened to my mother.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 80, 'm10t', 'Deliver divorce decree'),
('string/en/mission/mission_deliver_neutral_hard.stf', 81, 'm11d', 'My boss'' ship is currently stuck at a starport because this cheapskate doesn''t want to pay the full price for a new hyperdrive motivator. I need someone to pick up a refurbished model and deliver it as soon as possible. Could you do this for me?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 82, 'm11l', 'Hyperdrive motivator (a mechanical part thingee)'),
('string/en/mission/mission_deliver_neutral_hard.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 84, 'm11r', 'It''s about time! My ship has been stuck on this planet for weeks. I''m gonna fire my lazy employee when this is over. And you, you slowpoke, don''t you know -- hey, where are you going?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 85, 'm11f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 86, 'm11s', 'I hope my boss didn''t yell at you too much. I was instructed not to pay you, but I''m ignoring that and depositing your fee. Why should I worry about orders if I''m getting fired anyway?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 87, 'm11p', 'That boss can be a bit grumpy. Could you say you got lost and that''s why the delivery is late? Please?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 88, 'm11t', 'Refurbished Hyperdrive Motivator'),
('string/en/mission/mission_deliver_neutral_hard.stf', 89, 'm12d', 'A friend recently joined some other scientists to study some rare mineral formations but forgot some key instruments. These intruments have been calibrated to precise specifications, and so my friend wants them delivered rather than buying new ones. Could you pick them up and see to it that they are delivered safely?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 90, 'm12l', 'Scientific tools'),
('string/en/mission/mission_deliver_neutral_hard.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 92, 'm12r', 'My instruments! I was so worried. I''ve had this set since graduating from the Academy. They''re priceless to me. Many thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 93, 'm12f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 94, 'm12s', 'Glad to hear you made it. I bet my friend was overjoyed, huh? Scientists get excited by the strangest things.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 95, 'm12p', 'Here you go. Be careful! You know how touchy these scientist types can be about their intruments.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 96, 'm12t', 'Precisely Calibrated Tools'),
('string/en/mission/mission_deliver_neutral_hard.stf', 97, 'm13d', 'My friends can be so careless. While on vacation, they accidentally managed to erase their droid''s memory. They''ve had that protocol droid for years. The backup memory files and personality parameters are on this brain chip. Could you please deliver it to them? They would be most appreciative.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 98, 'm13l', 'Droid brain chip'),
('string/en/mission/mission_deliver_neutral_hard.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 100, 'm13r', 'Thank the stars! You''ve saved our dearest droid! We''ll install this chip right away. If our 3PO unit was here he''d thank you personally.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 101, 'm13f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 102, 'm13s', 'Sounds like they got the droid brain chip. Thanks for your help. I''ve transmitted some credits to compensate you for your time.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 103, 'm13p', 'Some folks can get pretty attached to their droids, eh? I personally am not one of those. They''re just tools to me.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 104, 'm13t', 'Droid Memory Chip'),
('string/en/mission/mission_deliver_neutral_hard.stf', 105, 'm14d', 'I ended up with a clutch of some amphibian''s eggs from Myrkr. Told a friend of mine, who now wants to buy them. Can''t figure out why. They''re not very tasty. But hey, credits is credits. Could you pick up the eggs from my home and deliver them to my friend?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 106, 'm14l', 'Storage box of some sort'),
('string/en/mission/mission_deliver_neutral_hard.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 108, 'm14r', 'Did my friend happen to tell you what type of eggs these are? Besides the fact that they''re amphibians from Myrkr? Good. It''s best you don''t know. Well done.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 109, 'm14f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 110, 'm14s', 'Thanks for getting those eggs safely to my friend. I wish I could find some fleek eels.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 111, 'm14p', 'Feel free to take these. They taste horrible. Now if I could get my hands on some fleek eels, that''d be something.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 112, 'm14t', 'Amphibian Eggs'),
('string/en/mission/mission_deliver_neutral_hard.stf', 113, 'm15d', 'My brother was supposed to lay our recently departed father''s ashes to rest. He was so grief-stricken, however, that he forgot the ashes at a friend''s home. Could you please pick them up and deliver them to my brother so that our father''s spirit can finally rest in peace?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 114, 'm15l', 'Small box'),
('string/en/mission/mission_deliver_neutral_hard.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 116, 'm15r', 'Hey, my glitterstim spice stash! You''re pretty brave to risk getting arrested just to get this to me. My brother sent this? I don''t have a brother. But I got a lot of good friends.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 117, 'm15f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 118, 'm15s', 'Thanks, buddy! You were great. I''m sure my brother will forget all the worries of the world now. Haha!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 119, 'm15p', 'Here are the ashes. Have you ever lost someone dear to you? It takes a long time for the pain to go away, doesn''t it?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 120, 'm15t', 'Inner Peace'),
('string/en/mission/mission_deliver_neutral_hard.stf', 121, 'm16d', 'My friends are getting married in a few days. They decided to elope and hold a small ceremony. Well wouldn''t you know it, they went off and forgot the wedding bracelets. Had them hand-crafted too. Cost them a fortune. Could you see to it that they get them? The faster the better, my friend.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 122, 'm16l', 'Jewelry (Bracelets)'),
('string/en/mission/mission_deliver_neutral_hard.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 124, 'm16r', 'It just wouldn''t have been the same without these. Thanks! We''ll name our firstborn after you. What was your name again?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 125, 'm16f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 126, 'm16s', 'But they said they would name their firstborn after me! That''s fickle for you. Oh well, I don''t think I''d want anyone else saddled with the name my folks gave me!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 127, 'm16p', 'I get misty-eyed at the thought of true love. Not enough of it in the galaxy, that''s for sure.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 128, 'm16t', 'Wedding Bracelets'),
('string/en/mission/mission_deliver_neutral_hard.stf', 129, 'm17d', 'My artist friend just went to deliver a family portrait to a patron. Guess what got left behind? That''s right: the portrait. I swear to you, those artists have gas-giant clouds for brains. Could you take this portrait to my friend and save a career?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 130, 'm17l', 'Picture or portrait'),
('string/en/mission/mission_deliver_neutral_hard.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 132, 'm17r', 'A thousand thanks, my friend! You''ve saved my career. If you ever want a portrait, let me know. I''ll give you a healthy discount. Well, a decent discount. Well -- anyway, thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 133, 'm17f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 134, 'm17s', 'Actually, my friend probably got more credits for that one portrait than I make all year. I wonder who''s really the more practical one?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 135, 'm17p', 'If my friend spent more time with practical matters and less time worrying about ''art'' -- oh well, I suppose it''s good someone worries about art.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 136, 'm17t', 'Portrait Saves Artistic Career'),
('string/en/mission/mission_deliver_neutral_hard.stf', 137, 'm18d', 'I''m a retired gourmet cook who used to co-own a restaurant with a dear friend. Every time I make my specialty, nerf liver pate, I must send some to my former partner or I''ll never hear the end of it. Move fast! The pate won''t keep forever, even in this special container.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 138, 'm18l', 'Container'),
('string/en/mission/mission_deliver_neutral_hard.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 140, 'm18r', 'I heard my old friend was making another batch of pate. Excellent! I shall sample this tonight! You have my gratitude -- though no, that doesn''t extend to letting you have a taste.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 141, 'm18f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 142, 'm18s', 'Thank you for delivering that pate. I get requests for my pate recipe from all over this world. But I''ll never tell!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 143, 'm18p', 'No sneaking any tastes. Once the seal on that container is broken, the pate will only remain fresh for a day or so. I''m trusting you now.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 144, 'm18t', 'Gourmet Nerf-Liver Pate'),
('string/en/mission/mission_deliver_neutral_hard.stf', 145, 'm19d', 'It''s my friend''s birthday, and I wish to give a very special gift. Could you please pick it up from the crafter and deliver it to my friend? Say it should be opened in a small, dark room. Don''t mention my name, of course. This will be a big surprise, I assure you.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 146, 'm19l', 'Small box'),
('string/en/mission/mission_deliver_neutral_hard.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 148, 'm19r', 'A birthday present? But my birthday isn''t for another six months. Who sent this? Curious. I''ll go home and have a look. Thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 149, 'm19f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 150, 'm19s', 'Thanks for delivering the gift. You might want to disappear for a while. No special reason why, just some friendly advice. The credits I deposited into your account should help you get away.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 151, 'm19p', 'I''m sure this item will be something the recipient will always remember. Careful now, don''t shake it. And whatever you do, don''t open it!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 152, 'm19t', 'A Big Surprise'),
('string/en/mission/mission_deliver_neutral_hard.stf', 153, 'm20d', 'My partners needs this specialized memory chip for their droid. Seems they want the droid to perform some kind of fancy tricks, like dancing, I think. Anyway, if you could deliver it to them, I''d be most appreciative. Oh, and try to keep it quiet and out of sight, would you?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 154, 'm20l', 'Memory chip'),
('string/en/mission/mission_deliver_neutral_hard.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 156, 'm20r', 'The new slicer chips! Cruising! You the new slicer? Ever sliced into the HoloNet?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 157, 'm20f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 158, 'm20s', 'I told you my partners were big kidders. What a laugh, huh? Thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 159, 'm20p', 'My partners will be glad to get this chip. And let me warn you, they''re big kidders. Don''t believe any wild stories they might tell you.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 160, 'm20t', 'Special Chips for Kidders'),
('string/en/mission/mission_deliver_neutral_hard.stf', 161, 'm21d', 'I am one of the few botanists who has a living t''ill plant in their possession. Those were flowers found on Alderaan, you know. It is my treasure. Every now and again, I consent to send a clipping to a colleague. Please see that this precious clipping is delivered safely.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 162, 'm21l', 'Plant of some sort'),
('string/en/mission/mission_deliver_neutral_hard.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 164, 'm21r', 'Wonderful! I''ve waited a long time to see this plant bloom. I''ll be sure to send my friend a wonderful gift as thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 165, 'm21f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 166, 'm21s', 'I understand that very few Alderaan plants have been cultivated on other worlds. The botanical gardens on Coruscant had a wide selection -- but one rumor I heard said the garden officials, acting on orders from high up, burned all the plants. Typical.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 167, 'm21p', 'Life can be so fragile. And the more beautiful, the more fragile it seems. Please be careful out there.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 168, 'm21t', 'Alderaan t''Ill Plant'),
('string/en/mission/mission_deliver_neutral_hard.stf', 169, 'm22d', 'I found a buyer who collects Wookiee bowcasters. Fortunately, I happen to have an antique. We finally agreed on terms that justify my parting with it. Deliver the bowcaster to the buyer. If it gets there quick, there may be more credits in it for you.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 170, 'm22l', 'Wookiee Bowcaster'),
('string/en/mission/mission_deliver_neutral_hard.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 172, 'm22r', 'This brings my total collection up to fifty. If this seller is to be believed, this particular weapon will be the jewel of my collection.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 173, 'm22f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 174, 'm22s', 'It turns out that after all the Imperial taxes on sales of antique collectibles, I don''t have enough left to pay you the bonus I mentioned. But thanks anyway!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 175, 'm22p', 'Bowcasters can be dangerous weapons, even just to own. Wookiees don''t like it when non-Wookiees use them.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 176, 'm22t', 'Wookiee Bowcaster'),
('string/en/mission/mission_deliver_neutral_hard.stf', 177, 'm23d', 'I just received a container of wild shaak ambergris that some customers wants to buy. They make perfumes, I believe. Could you deliver this container to them?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 178, 'm23l', 'Container'),
('string/en/mission/mission_deliver_neutral_hard.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 180, 'm23r', 'The ambergis of the wild shaak is far superior to the domesticated variety. The end result is much sweeter. My thanks.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 181, 'm23f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 182, 'm23s', 'If shaak ambergris smells so great, why do shaaks themselves smell terrible? I''ve never understood that. Anyway, thanks for delivering that stuff to my customers.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 183, 'm23p', 'Never been much of a perfume wearer myself, but I suppose I''m the exception. Careful on your travels.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 184, 'm23t', 'Deliver ambergris'),
('string/en/mission/mission_deliver_neutral_hard.stf', 185, 'm24d', 'Have you ever tried laa fish caviar? It''s simply superb! Please deliver this container of the delicacy to my dear friend. It''s a gift to thank the family for hosting us at their home last month. Don''t you dare eat any!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 186, 'm24l', 'Small can'),
('string/en/mission/mission_deliver_neutral_hard.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 188, 'm24r', 'Laa fish caviar! And from the wild! How thoughtful -- that''s my favorite! So much better than that dismal oversalted bioengineered stuff. That tastes like old oil from repulsorlift casings.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 189, 'm24f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 190, 'm24s', 'Wild laa caviar costs more than I make in a year. Don''t tell anyone, but I have an alternative supplier. You can''t tell bioengineered laa fish from the wild variety, no matter what the snobs say.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 191, 'm24p', 'Please tell my friend that this is the caviar of the genuine wild laa fish. Just wait for the reaction.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 192, 'm24t', 'Laa Fish Caviar'),
('string/en/mission/mission_deliver_neutral_hard.stf', 193, 'm25d', 'My friend''s home is infested with vermin. I have the perfect solution -- tooke-trap plants from the Gungan swamps! These carnivorous plants are voracious and will have my desperate friend''s home pest-free in no time. Please deliver these seedlings at once.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 194, 'm25l', 'Plants of some sort'),
('string/en/mission/mission_deliver_neutral_hard.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_neutral_hard.stf', 196, 'm25r', 'I hope these work, because I''m allergic to most pesticides. I''m at the end of my towline!'),
('string/en/mission/mission_deliver_neutral_hard.stf', 197, 'm25f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard.stf', 198, 'm25s', 'I should have mentioned that the tooke-trap plants grow rather large, and may eventually attack house pets and small children. I''ll have to remember to tell my friend.'),
('string/en/mission/mission_deliver_neutral_hard.stf', 199, 'm25p', 'I think more folks should use plants for pest control. Who needs harsh chemicals in their homes?'),
('string/en/mission/mission_deliver_neutral_hard.stf', 200, 'm25t', 'Gungan Tooke-Trap Plants'),
('string/en/mission/mission_deliver_neutral_hard.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 1, 'm1d', 'This message is of the greatest importance. My friend has been searching the galaxy for a long-lost love. I''ve just received word that my friend''s love was killed in a transport accident last year. I wish to save my friend further expense and heartache. Please deliver the notice as promptly as possible.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 5, 'm1r', 'What? My love has been killed? No! Say it isn''t so! How can I go on living? Please leave me now.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 6, 'm1p', 'My friend will be quite shaken by this news. Please be sensitive. The search has taken a long time. Thank you.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 7, 'm1t', 'Deliver tragic news'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 8, 'm1s', 'Thank you for handling that with such sensitivity. I know that wasn''t easy.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 9, 'm2d', 'I''ve learned that Jabba the Hutt has placed a huge bounty on the head of my friend. Rumor has it that Boba Fett himself has taken an interest. My friend must go into hiding at once. This may well prove a perilous mission. Can you deliver the warning?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 12, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 13, 'm2r', 'Boba Fett? After me? Thanks for the warning. I gotta disappear and quick!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 14, 'm2p', 'Careful on your travels. Remember that bounty hunters will be after my friend. If you see Boba Fett, run. Good luck!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 15, 'm2t', 'Jabba Sends Bounty Hunters'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 16, 'm2s', 'It looks like my friend is going offworld. Way offworld. You can tell that to any bounty hunters you happen to see. Thanks.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 17, 'm3d', 'A friend is trying to buy an ancient Sith artifact. An archeologist I know discovered something of its history and has included the findings on a datadisc. Please collect this disc and deliver it immediately. I hope I''m not too late to save my friend from a terrible fate.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 21, 'm3r', 'Nonsense! The artifact is perfectly safe. Soon the entire galaxy will understand all about the Sith. Begone and trouble me no more, puny mortal.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 22, 'm3p', 'You must warn my friend not to fall asleep with this dreadful artifact in the room. It contains the spirit of an ancient and evil Sith Lord. Go quickly!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 23, 'm3t', 'Warn of Sith artifact'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 24, 'm3s', 'I hope you weren''t too late to save my friend from a terrible fate. I must visit soon and see about destroying that artifact.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 25, 'm4d', 'My friend''s father has become deathly ill. For some reason, normal HoloNet messages aren''t getting through -- maybe the Imperial Army imposed one of their blackouts. I hope you can deliver this news to my friend before it''s too late.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 29, 'm4r', 'Oh no! This is terrible news! I must contact my father at once. Thank you!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 30, 'm4p', 'We don''t know how much time this unfortunate being has left. You should probably hurry! '),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 31, 'm4t', 'A Father''s Illness'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 32, 'm4s', 'My friend should make it to the bacta facility in time to have a last long conversation. Thank you.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 33, 'm5d', 'I finally found a buyer for my centuries-old Core World Arms pulse-blast rifle. Obviously such a valuable item must be hand-delivered. It''s packed securely. This collector travels a lot to dangerous areas, so be on your guard.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 34, 'm5l', 'Antique blaster rifle'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 36, 'm5f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 37, 'm5r', 'Ah, my rifle! Lucky you found me. I was on the next transport out of here. This might come in handy where I''m going. My thanks.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 38, 'm5p', 'These eccentric collectors, always planet-hopping. Hope you find this one. Here you go. That rifle is packed as securely as possible'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 39, 'm5t', 'Core World Antique Blaster'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 40, 'm5s', 'I wish I knew how that buyer earns enough credits both to buy antique weapons and also to travel around the galaxy. Hmm, I wonder if one habit explains the other?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 41, 'm6d', 'These nobles and their ridiculous vendettas. A rich client who had been staying with us left his customized dueling vibrorapier in our home. Now the client needs it to settle a matter of honor, or somesuch nonsense. Could you please deliver it quickly? '),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 42, 'm6l', 'Vibrorapier'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 44, 'm6f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 45, 'm6r', 'Aha! Now at last my honor can be defended. No one accuses me of cheating. No one!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 46, 'm6p', 'Here''s the vibrorapier. No telling what sort of trouble you might encounter on your travels. This noble has a habit of making enemies.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 47, 'm6t', 'A Matter of Honor'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 48, 'm6s', 'I hope that hothead survives the duel, and I certainly hope you don''t think dueling is honorable. Whatever happened to "forgive and forget"?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 49, 'm7d', 'I have some delicate cargo that must be delivered soon. A client has purchased some Neimoidian pylat bird eggs from a breeder friend. I don''t need to tell you that these are rare and expensive. If you can pick them up and deliver them whole, you''ll be well-rewarded.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 50, 'm7l', 'Small box'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 52, 'm7f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 53, 'm7r', 'My birds! Well, they''re going to be. You ever heard their song? Enchanting. Thanks.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 54, 'm7p', 'These eggs need to be maintained at a constant temperature. The sealed container controls that. Don''t open it. Don''t jostle it. Don''t get into blaster battles if you can help it.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 55, 'm7t', 'Pylat Egg Delivery'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 56, 'm7s', 'Thanks for getting those eggs to their destination in one piece. Your pay has been transmitted.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 57, 'm8d', 'Our friend''s sister has just given birth! The family would love for my friend to return home at once and see the newborns. Could you pick up a datadisc, which contains pictures of the new family, from my home and deliver it and the good news? Tell my friend to hurry home. Many thanks!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 61, 'm8r', 'This is wonderful news! Thank you! I''ll book the next transport out of here. Can''t wait to see the holographs of the newborns.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 62, 'm8p', 'I''m sure our friend will want to race home once these holographs have been viewed. I know it''s a long way to go but it''s for a good cause.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 63, 'm8t', 'Pictures of the Newborns'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 64, 'm8s', 'Thanks for getting the word to my friend. I hope the pictures were appreciated.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 65, 'm9d', 'I own a speeder shop and have recently bought out my partner, who''s been away conducting some personal business. Could you pick up a datadisc from my accountant and deliver it to my ex-partner? It contains all the documents showing that my takeover was quite legal.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 68, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 69, 'm9r', 'I can''t be bought out! My grandfather opened that shop! This is an outrage! I''ll go deal with this personally. Maybe with a blaster.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 70, 'm9p', 'I''m sure my partner -- or, I should say, "ex-partner" -- will be quite surprised. Leave before you get hurt.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 71, 'm9t', 'Legal Takeover'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 72, 'm9s', 'Purge yourself of sentimentality if you want to run an efficient business. Profits come to those who act quickly and decisively.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 73, 'm10d', 'My boss'' ship is currently stuck at a starport because this cheapskate doesn''t want to pay the full price for a new hyperdrive motivator. I need someone to pick up a refurbished model and deliver it as soon as possible. Could you do this for me?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 74, 'm10l', 'Hyperdrive motivator (a mechanical part thingee)'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 76, 'm10f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 77, 'm10r', 'It''s about time! My ship has been stuck on this planet for weeks. I''m gonna fire my lazy employee when this is over. And you, you slowpoke, don''t you know -- hey, where are you going?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 78, 'm10p', 'Here''s the part. I hope it''s the right model. I hear this boss can be a bit grumpy, so expect to be scolded.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 79, 'm10t', 'Stuck at a Starport'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 80, 'm10s', 'I hope my boss didn''t yell at you too much. I was instructed not to pay you, but I''m ignoring that and depositing your fee. Why should I worry about orders if I''m getting fired anyway?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 81, 'm11d', 'A friend recently joined some other scientists to study some rare mineral formations but forgot some key instruments. These intruments have been calibrated to precise specifications, and so my friend wants them delivered rather than buying new ones. Could you pick them up and see to it that they are delivered safely?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 82, 'm11l', 'Scientific tools'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 84, 'm11f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 85, 'm11r', 'My instruments! I was so worried. I''ve had this set since graduating from the Academy. They''re priceless to me. Many thanks.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 86, 'm11p', 'Here you go. Be careful! You know how touchy these scientist types can be about their intruments.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 87, 'm11t', 'Precision Mineralogy'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 88, 'm11s', 'Glad to hear you made it. I bet my friend was overjoyed, huh? Scientists get excited by the strangest things. '),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 89, 'm12d', 'My careless friends accidentally erased their droid''s memory. They''ve had that protocol droid for years. The backup memory files and personality parameters are on a brain chip at my boss'' shop. Could please pick it up and deliver it to them? They would be most appreciative.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 90, 'm12l', 'Droid brain chip'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 92, 'm12f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 93, 'm12r', 'Thank the stars! You''ve saved our dearest droid! We''ll install this chip right away. If our 3PO unit was here he''d thank you personally.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 94, 'm12p', 'Here''s the brain chip. Some folks can get pretty attached to their droids, eh? I personally am not one of those. They''re just tools to me. '),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 95, 'm12t', 'Restore a Friend''s Memory'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 96, 'm12s', 'Sounds like they got the droid brain chip. Thanks for your help. I''ve transmitted some credits to compensate you for your time.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 97, 'm13d', 'I ended up with a clutch of some amphibian''s eggs from Myrkr. Told a friend of mine, who now wants to buy them. Can''t figure out why. They''re not very tasty. But hey, credits is credits. Could you pick up the eggs from my home and deliver them to my friend?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 98, 'm13l', 'Storage box of some sort'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 100, 'm13f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 101, 'm13r', 'Did my friend tell you what type of eggs these are? Aside from being some amphibian from Myrkr? Good. It''s best you don''t know.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 102, 'm13p', 'Feel free to take these. They taste horrible. Now if we could get our hands on some fleek eels, that''d be something.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 103, 'm13t', 'Eggs -- Not for Eating'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 104, 'm13s', 'Thanks for getting those eggs safely to my friend. I wish I could find some fleek eels.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 105, 'm14d', 'My brother was supposed to lay our recently departed father''s ashes to rest. He was so grief-stricken, however, that he forgot the ashes at a friend''s home. Could you please pick them up and deliver them to my brother so that our father''s spirit can finally rest in peace?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 106, 'm14l', 'Small box'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 107, 'm14o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 108, 'm14f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 109, 'm14r', 'Hey, my glitterstim stash! You''re pretty brave to risk getting arrested just to get this to me. My brother sent this? I don''t have a brother. But I got a lot of good friends.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 110, 'm14p', 'Here are the ashes. Have you ever lost someone dear to you? It takes a long time for the pain to go away, doesn''t it?'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 111, 'm14t', 'Help Someone Find Inner Peace'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 112, 'm14s', 'Thanks, buddy! You were great. I''m sure my brother will forget all the worries of the world now. Haha!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 113, 'm15d', 'It''s my friend''s birthday, and I wish to give a very special gift. Could you please pick it up from the crafter and deliver it to my friend? Say it should be opened in a small, dark room. Don''t mention my name, of course. This will be a big surprise, I assure you.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 114, 'm15l', 'Small box'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 116, 'm15f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 117, 'm15r', 'A birthday present? But my birthday isn''t for another six months. Who sent this? Curious. I''ll have a look. Thanks.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 118, 'm15p', 'I''m sure this item will be something the recipient will always remember. Careful now, don''t shake it. And whatever you do, don''t open it!'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 119, 'm15t', 'Birthday Surprise'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 120, 'm15s', 'Thanks for delivering the gift. You might want to disappear for a while. No special reason why, just some friendly advice. The credits I deposited into your account should help you get away.'),
('string/en/mission/mission_deliver_neutral_hard_non_persistent_from_npc.stf', 121, 'number_of_entries', '15'),
('string/en/mission/mission_deliver_neutral_medium.stf', 1, 'm1d', 'I''m submitting my application to the Academy at long last. Won''t my friends be jealous when they hear I''ve become a TIE pilot? But I can''t trust something this important to the HoloNet. Could you pick up my application from my friend''s home and hand-deliver it to a professional courier?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 4, 'm1r', 'Another star jockey wanna-be, eh? All right, I''ll see that it''s delivered to the Academy.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 6, 'm1s', 'Thanks, buddy! You''re the kind of friend someone wishes for. I deposited a little something into your account.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 7, 'm1p', 'My best friend''s future is in your hands. Please be careful and see that it gets to its destination. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 8, 'm1t', 'Imperial Academy Application'),
('string/en/mission/mission_deliver_neutral_medium.stf', 9, 'm2d', 'Here we go again. I''ve applied to the Academy every year for the past seven years and they still haven''t accepted me. But at least it gets my nagging mother off my back. She insists it be hand-delivered to a courier. Can you help out a fellow citizen? '),
('string/en/mission/mission_deliver_neutral_medium.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 12, 'm2r', 'Oh, not this loser again! When will this mynock-brain learn that the Academy just doesn''t want losers? Can''t even fill out the application correctly. Argh, I hate my life.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 14, 'm2s', 'It''s only the Empire''s constant encouragement that has kept me on track, applying to the Academy year after year. Well, the Empire and my mother. But this year will be the year!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 15, 'm2p', 'Try and try again, I always say. Maybe this time I''ll get lucky. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 16, 'm2t', 'Seventh Time''s the Charm'),
('string/en/mission/mission_deliver_neutral_medium.stf', 17, 'm3d', 'I was investigating a missing person''s case for a client to discover what had happened to their son. Apparently the young man was on Alderaan when it -- well, you know. His final letters are stored on a datadisc. I regret I can''t deliver the datadisc in person, but I''m keeping a low profile. My investigation attracted some unwanted Imperial attention.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 20, 'm3r', 'What? This can''t be! A plague upon the Empire! Those assassins don''t deserve our loyalty! Oh, my son! My dear son!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 22, 'm3s', 'Did anyone appear to be following you when you made the delivery? I''d keep a low profile, just in case. Your fee has been transmitted to your account.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 23, 'm3p', 'Please be sensitive when delivering this message. It will no doubt come as a great shock to the recipient.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 24, 'm3t', 'Death on Alderaan'),
('string/en/mission/mission_deliver_neutral_medium.stf', 25, 'm4d', 'I''ve verified what happened to Alderaan. It''s all on this datadisc. The truth will horrify my friend. Can you deliver this disc? Mention that I apologize I couldn''t deliver this myself, but I''m going to be out of touch for a while. I think my friend will understand.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 28, 'm4r', 'Did you access the datadisc? Good. I want no harm to come to you. You''re just the messenger. My thanks.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 30, 'm4s', 'I''m advising my friend to forget the Academy and contact a certain Bothan pilot we met on Corellia. I hope we''ll meet again in better circumstances.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 31, 'm4p', 'Don''t view the information on this datadisk -- not unless you want to stop sleeping peacefully at night.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 32, 'm4t', 'This is the Truth About Alderaan'),
('string/en/mission/mission_deliver_neutral_medium.stf', 33, 'm5d', 'The happy day has come at last! My only daughter is getting married. Could you pick up the very first holographic invitation from the data engineer and hand-deliver it to my oldest friend? That should make quite an impression.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 36, 'm5r', 'Well, it''s about time! I knew that girl would get hitched sooner or later. Can''t wait to tell the family. Wedding invitations on datadisc. Heh! How times change.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 37, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 38, 'm5s', 'Thanks for delivering that invitation. My friend was most impressed. I''m not rich, but my daughter''s first -- and, I hope, only -- wedding is worth a splurge.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 39, 'm5p', 'Here''s the personalized invitation. This is quite the elaborate presentation, lots of animation and music. Family must be rich.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 40, 'm5t', 'Elaborate Invitation'),
('string/en/mission/mission_deliver_neutral_medium.stf', 41, 'm6d', 'Nobody, and I mean nobody, designs vegetable steamers like I do! This is going to revolutionize the way we prepare our meals. This one requires no water. It uses vaporator technology to suck the ambient moisture right out of the air. Yep, you can say it -- I''m a genius. Take this prototype to my investors, would you? '),
('string/en/mission/mission_deliver_neutral_medium.stf', 42, 'm6l', 'Prototype steamer (like the thing Beru was cooking vegetables in)'),
('string/en/mission/mission_deliver_neutral_medium.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 44, 'm6r', 'What? This is what I''ve been paying that lunatic thousands of credits to invent? I thought it was a more efficient coolant system for speeders. I''m having this veggie-loving maniac arrested for fraud! '),
('string/en/mission/mission_deliver_neutral_medium.stf', 45, 'm6f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_medium.stf', 46, 'm6s', 'You did great. I''d have delivered the steamer myself, but I didn''t want to gloat when I saw the look of awe on their faces. And they thought I''d be a bad return on their investment. Hah!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 47, 'm6p', 'Here''s a work of sheer genius. Bet you never thought you''d hold something like this in your hands, eh? Go ahead, it''s okay to be awe-inspired.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 48, 'm6t', 'Steamer Revolution Aborning'),
('string/en/mission/mission_deliver_neutral_medium.stf', 49, 'm7d', 'I''ve finally succeeded in deciphering the complete genetic code of the rancor. Can you imagine what this will bring on the open market? Only part of the code is on this datadisc. I want to see if my partner and I can start a bidding war. Will you deliver this? I need to continue checking my figures to make sure we''re ready for the sale.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 52, 'm7r', 'The code is deciphered? Excellent! I''m already lining up buyers. I hope those figures are correct. It''s not good to cheat a Hutt!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 53, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 54, 'm7s', 'This will be big, very big. Hook this data up with a cloning facility and you''ve got yourself an army of formidable monsters. And you helped! Next up: krayt dragons.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 55, 'm7p', 'My partner wants this as a sample to induce the buyers to bid more. I think we''re gonna be filthy rich! Don''t delay in delivering it.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 56, 'm7t', 'Rancor Genome (Partial)'),
('string/en/mission/mission_deliver_neutral_medium.stf', 57, 'm8d', 'I''ve finished my survey of the Core''s asteroid fields and have charted every known space slug in those sectors. I need someone to pick up the survey datadisc from my lab and deliver it to a representative of the Imperial Science Department''s Biology Division -- they need to double-check my stats before we transmit it to the Imperial Information Center.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 59, 'm8o', 'Imperial Space Survey Office  '),
('string/en/mission/mission_deliver_neutral_medium.stf', 60, 'm8r', 'Ah, the survey results! I''ll check these findings immediately. I hope my superiors keep me in mind when assigning scientists to study those space slugs. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 61, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 62, 'm8s', 'Thank you. Space slugs, space slugs -- I find them simply fascinating, don''t you?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 63, 'm8p', 'Your success in delivering this disc will benefit science. We''re counting on you!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 64, 'm8t', 'Deliver survey results'),
('string/en/mission/mission_deliver_neutral_medium.stf', 65, 'm9d', 'My company has just finished logging the inventory of one of our client''s holdings. It''s all been stored on a datadisc that has everything itemized by sale price. The appraisals were done by the most careful and painstaking professionals in the field. Could you pick up the inventory and deliver it to our client?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 68, 'm9r', 'It''s about time! I paid good money for these appraisals, and I expected them to be done long since. I''ll adjust my final payment to the company accordingly.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 70, 'm9s', 'Thank you for your prompt service. I understand that our client was a tad upset. We''ll try to smooth things over. Your pay has been deposited.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 71, 'm9p', 'Our client is most eager to receive this datadisc. Please relay our apologies for tardiness, but we wanted to be thorough.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 72, 'm9t', 'Inventory a Trifle Tardy'),
('string/en/mission/mission_deliver_neutral_medium.stf', 73, 'm10d', 'I''ve won an all-expense paid vacation to Amfar but I can''t get away from my work duties. Would you deliver this incredible prize to my dear friends so they can take advantage of it? I''d go myself, but I just can''t spare the time. Back to work I go! '),
('string/en/mission/mission_deliver_neutral_medium.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 76, 'm10r', 'What''s this, a free vacation? You bet I''ll accept! I hear the beaches on Amfar are the finest in the Galaxy. If only my busy friend could join us. You know what they say, "All work and no play..."'),
('string/en/mission/mission_deliver_neutral_medium.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 78, 'm10s', 'I won that vacation by correctly answering a trivia question about the latest music holo from the Dance Lords of the Bith. Did you know they stuffed 23 Jawas into one binary load lifter? If you''d known, you''d be going to Amfar instead of my friends.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 79, 'm10p', 'I hope my friends can take advantage of this vacation. Tell them to have a frozen juri juice drink for me! Oh, why must I work so hard?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 80, 'm10t', 'Amfar Vacation Offer'),
('string/en/mission/mission_deliver_neutral_medium.stf', 81, 'm11d', 'You''ll never believe what I got my hands on! Actual holograms of the destruction of Alderaan! Don''t even ask how or where I got it. Better that you don''t know, my friend. Take the datadisc to my buddy. Tell them to just plug it into their holocam and sit back and watch the show. This is extreme! '),
('string/en/mission/mission_deliver_neutral_medium.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 84, 'm11r', 'No way! Is this really --? No way! I gotta show all my buds. This is gonna be so intense! Thanks!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 85, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 86, 'm11s', 'That holo rules. But don''t tell anyone about it, or maybe you''ll get arrested, okay?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 87, 'm11p', 'When you give this to my friend, they''ll say, "No way!" When that happens, you just nod and say, "Way!" They''ll see the truth soon enough.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 88, 'm11t', 'Alderaan Blowup Holo'),
('string/en/mission/mission_deliver_neutral_medium.stf', 89, 'm12d', 'I''ve just acquired five new playing pieces for dejarik. These are prototypes, straight from the labs of Lakan Industries. They haven''t been released to the public yet. My brother at Lakan leaked them to me. Could you deliver this datadisc to my friend? I can''t be seen delivering it, or someone may trace the leak back to my brother.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 92, 'm12r', 'Can''t wait to try these pieces in the Lesser Coruscant Opening, Finessed. Oops, pardon my dejarik jargon.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 94, 'm12s', 'My friend wants to be a dejarik grandmaster some day. Maybe those pieces will give an edge at the next local tournament. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 95, 'm12p', 'You a fan of dejarik? If so, you''ll appreciate this delivery. If not, well, you still get paid so who cares?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 96, 'm12t', 'Prototype Dejarik Pieces'),
('string/en/mission/mission_deliver_neutral_medium.stf', 97, 'm13d', 'See what comes of not having a work permit? I have to hand-deliver my hours to my employer to make sure I get paid and my family eats. This datadisc is a record of last month''s labors. Could you deliver it for me? I can''t bring it myself -- my family will be returning soon, and I must prepare their meals.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 100, 'm13r', 'About time! I was about to send out the payroll. Next time I won''t wait this long on lazy workers. My time is precious.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 101, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 102, 'm13s', 'Someday my oldest son will be old enough to work in the mines, and then we''ll have enough to get a HoloNet connection. Then I can send in my hours for my three jobs without using datadiscs.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 103, 'm13p', 'My family depends on this disc getting to my employer as soon as possible. I wish I didn''t have so much responsibility. A free agent like yourself is lucky.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 104, 'm13t', 'Time Disc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 105, 'm14d', 'A customer''s daughter is getting married soon, and she needs a dress in a week. Could you pick up the datadisc containing the dress pattern from my customer? Please deliver it to my colleague''s fabric shop so I can be sent the appropriate fabrics. I''m swamped with work and can''t go myself.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 108, 'm14r', 'This will be quite a dress. The pattern calls for some pretty exotic fabrics -- spidersilk saturated with glimmerdust, prismatic zwill, resublimated nanoweave. Hope this customer is rich.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 110, 'm14s', 'Thank you so much for being prompt. If you ever need clothes, look me up -- once I''m not so swamped, that is.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 111, 'm14p', 'It will be a gown fit for a queen. Do please hurry with the delivery. Thank you.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 112, 'm14t', 'Wedding Dress Pattern'),
('string/en/mission/mission_deliver_neutral_medium.stf', 113, 'm15d', 'A friend''s child has been sick, stricken with body sores. I know an old family remedy that never fails, regardless of the species afflicted. Could you pick up the datadisc with the recipe for this poultice and the accompanying herbs from a local pharmacist? Then please deliver the goods to my friend.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 116, 'm15r', 'My poor child, how she suffers. I''ll give this remedy a try. Thank you so much for delivering it. I''ll let my friend know if it worked.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 117, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 118, 'm15s', 'My thanks for the prompt delivery. I hope my friend''s child gets better once this remedy is used.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 119, 'm15p', 'Apply this poultice three times a day. Remind the customer to make a fresh batch every day, and wrap the unused portion tightly before throwing it out.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 120, 'm15t', 'Remedy for a Sick Child'),
('string/en/mission/mission_deliver_neutral_medium.stf', 121, 'm16d', 'This settles an old debt. When I was younger, I travelled to Tatooine with a friend and bet on the podraces. One of the races was obviously fixed, so I refused to honor my bet to my friend and we didn''t speak for almost 30 years. Well, I just discovered proof that the race was indeed legit. So I''m doing the right thing and honoring my bet. This datadisc tells how to access the account containing the money.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 124, 'm16r', 'Well, I''ll be a mangy monkey-lizard! I''d forgotten about this bet. That race was fixed, you know. My friend was right not to pay. But since I need the money, I''ll take it.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 126, 'm16s', 'It was just too outlandish to believe a young boy could win a podrace! But it was true, as I only recently found out. Thanks for helping me settle that debt.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 127, 'm16p', 'This clears my conscience. I hope it''s appreciated. Good riddance anyhow!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 128, 'm16t', 'Settle an Old Debt'),
('string/en/mission/mission_deliver_neutral_medium.stf', 129, 'm17d', 'I recently returned from a trip to Zeltros with a whole bunch of holographs commemorating my experience. Some of them are of,-- how shall I say -- a delicate nature? My buddies couldn''t make the trip, but they want to view the holographs. Could you take them this datadisc containing the images?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 132, 'm17r', 'I''ll take those holographs, thank you. I know someone who will love to see these images. It''ll be worth my fee, too.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 134, 'm17s', 'Thank you. I didn''t want to endanger my domestic bliss by taking them myself. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 135, 'm17p', 'Be discreet with this delivery, okay? Don''t lose that disc. I could end up in a very compromising situation if it ends up in the wrong hands. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 136, 'm17t', 'Vacation Holographs'),
('string/en/mission/mission_deliver_neutral_medium.stf', 137, 'm18d', 'I won''t be able to attend my nephew''s birthday celebration this year.  But I made a special holocam recording of me singing his favorite nursery rhymes. Could you make sure his family gets it in time for the party? Thank you so much.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 140, 'm18r', 'Is this for the birthday boy? I''m helping put together his party. I''m sure he''ll be quite pleased to get this. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 141, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 142, 'm18s', 'How quickly those children grow up. I hope that in future decades that young man will look back on my recording with vivid remembrance.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 143, 'm18p', 'I hope my nephew appreciates all my hard work. He can be such a sweet boy if the mood strikes him. Thank you for your help.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 144, 'm18t', 'Memorable Birthday Gift'),
('string/en/mission/mission_deliver_neutral_medium.stf', 145, 'm19d', 'A miner friend found some crystal deposits while out prospecting in the Outer Rim. He won''t say where exactly he found them. Claims he''s going to get rich or something. He wants me to have some crystal samples analyzed for him. Can you pick up the samples and deliver them to a mineralogist I know?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 146, 'm19l', 'Crystals'),
('string/en/mission/mission_deliver_neutral_medium.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 148, 'm19r', 'Some sort of crystals, eh? Sure, I''ll have a look. Prospectors keep dreaming they''ll find another source of Adegan crystals. They used to use those in lightsabers, you know.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 149, 'm19f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_medium.stf', 150, 'm19s', 'Thanks for delivering those crystals. My friend is always having me check out all sorts of minerals. The mother lode is waiting, somewhere out there.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 151, 'm19p', 'I''m sure these are just worthless rocks. But I''ll help my friend out if I can. Oh, does the word ''Adegan'' mean anything to you?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 152, 'm19t', 'Deliver mineral samples'),
('string/en/mission/mission_deliver_neutral_medium.stf', 153, 'm20d', 'A local seller of ancient artifacts, who wishes to remain anonymous, won''t even show me holographs of his wares without a fee. Could you take this encrypted datadisc to the seller''s agent? It contains the codes necessary to access the credits agreed upon previously. The seller can feel free to send me the disc containing the holographs in question.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 156, 'm20r', 'Thanks. As soon as my employer has accessed the credits, he will send the catalog.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 157, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 158, 'm20s', 'Thanks for delivering the fee. That seller claims to own Sith artifacts from Korriban that are several thousand years old. I hope I haven''t been wasting my time and money.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 159, 'm20p', 'Why did I have to develop such an expensive hobby? I should have stuck with restoring vintage droids. Please be prompt.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 160, 'm20t', 'Collector''s Fee'),
('string/en/mission/mission_deliver_neutral_medium.stf', 161, 'm21d', 'My employer sells antiques to interested buyers. One such collector has paid the proper fee to view my employer''s wares. Could you pick up an encrypted catalog and deliver it? The collector will know how to retrieve the data.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 164, 'm21r', 'The catalog at last! I''ve waited a long time for this. The possibility of Sith artifacts! Can you imagine?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 165, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 166, 'm21s', 'By the way, the contents of our catalog are confidential. Please respect our privacy.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 167, 'm21p', 'Nothing is free, pal.  If you want to look, you gotta pay the fee too. Actually, you probably can''t afford it. Deliver this quick, though, and you might be on your way to earning enough.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 168, 'm21t', 'Antique Artifacts Catalog'),
('string/en/mission/mission_deliver_neutral_medium.stf', 169, 'm22d', 'Fleek eels are a prized delicacy that must be kept alive until they''re cooked or else the flavor is greatly diminished. I found a way to preserve the eels so that none of the flavor is lost. I need you to pick up a sample and deliver it promptly to a representative of the Corporate Sector Authority. Their food companies can make millions off my secret recipe!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 172, 'm22r', 'This recipe will be tested first, of course. If it turns out not to deliver on its promise, then there will be no compensation. That is, in fact, what we are expecting.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 173, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 174, 'm22s', 'Thanks! I can''t wait for those CSA chefs to taste those preserved fleek eels and marvel at my genius!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 175, 'm22p', 'I knew all those years of studying preservatives would pay off! I''m going to be set up for life. Please hurry with this delivery!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 176, 'm22t', 'Deliver fleek eel recipe'),
('string/en/mission/mission_deliver_neutral_medium.stf', 177, 'm23d', 'I am a devout follower of the Cosmic Balance. I have gathered the words of our greatest teachers and transcribed them into Basic. I need this disc delivered to a local holocaster so that this great work can spread through the galaxy. Do you wish to help spread the Truth?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 180, 'm23r', 'Yeah, I remember this fanatic. Well, we don''t ask questions; we just send what we''re paid to send. We''ll get to it soon.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 182, 'm23s', 'The Cosmic Balance was discovered on Bakura, as you may know, but it is spreading like fire to other parts of the Galaxy. Soon all will know our word and heed our wisdom. And your role in the history of our faith will be remembered.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 183, 'm23p', 'The fall of the Jedi was the awakening of the galaxy. Go forth to duty.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 184, 'm23t', 'Words of Cosmic Balance'),
('string/en/mission/mission_deliver_neutral_medium.stf', 185, 'm24d', 'Can you keep a secret? I''m a great Jedi Master who used to lead the Jedi Council in the days of the Old Republic. We''re in hiding, waiting for the right moment to destroy the Empire. Oh, they''re going to be sorry they ever messed with Jedi. I need you to pick up a secret message from one of our contacts and deliver it to a fellow Jedi. This is of the greatest importance. Can you handle it?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 188, 'm24r', 'Not this lunatic again! Who is it this time? Last week it was the Emperor. This is just a grocery list, for Corellia''s sake! Poor sod needs professional help. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 189, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 190, 'm24s', 'Thank you for serving the interests of the Jedi. Soon we shall come out of hiding and restore the Republic. Honest.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 191, 'm24p', 'The fate of the galaxy is in your hands. Know that the Force will be with you, always. Unless you fail. Then you''re bantha fodder. Good luck.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 192, 'm24t', 'Announce the Jedi''s Return'),
('string/en/mission/mission_deliver_neutral_medium.stf', 193, 'm25d', 'I knew you''d accept this mission. Why, you ask? Because everything proceeds exactly as I have foreseen it. Yes, I am the Emperor. I am traveling incognito to better observe my loyal citizens. I have allowed you the honor of carrying a secret message. It is to go to one of my Imperial spies and from there to Lord Vader himself. Do not fail me.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 196, 'm25r', 'This lunatic gives me fits. It''s the Emperor this time, is it? Oh look, it''s another grocery list. Maybe the Emperor is secretly a grocer. Yeah, that sounds right.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 197, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 198, 'm25s', 'Those who do not believe will pay the price for their lack of vision. They will start by buying me more groceries!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 199, 'm25p', 'If you perform well during this mission, I may reward you with an Imperial appointment. How does Imperial Inquisitor sound?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 200, 'm25t', 'Message From the Emperor?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 201, 'm26d', 'I finally managed to sell my old JR-4 swoop. Got a good price for it, too. I need you to pick up the title and deliver it to the new owner. Thanks, buddy!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 202, 'm26l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 203, 'm26o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 204, 'm26r', 'The title! Great! I''ve already started to modify the JR-4. It was in great condition.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 205, 'm26f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 206, 'm26s', 'Thanks for taking care of that for me, buddy. I can''t wait to buy the new TaggeCo Air-2 swoop. Now that''s a sweet ride!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 207, 'm26p', 'Here you go. You into speeders and swoops like me and my buddy? Check out the Flare-S swoop if you ever get a chance. Nice.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 208, 'm26t', 'Swoop Transaction'),
('string/en/mission/mission_deliver_neutral_medium.stf', 209, 'm27d', 'Someone wants to buy my vintage blaster collection, including my matching set of MB-450''s. Luxan Personal Armaments is the best, and the Penetrator is the elite of hunting pistols. I have a datadisc -- holographs and detailed specs of everything in my collection -- to be delivered to the buyer. Can you pick it up from my friend?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 210, 'm27l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 211, 'm27o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 212, 'm27r', 'Can''t wait to see what''s on this datadisc. I love blasters. Don''t you? Nothing like the weight of a solid weapon in your hands, eh?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 213, 'm27f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 214, 'm27s', 'Thanks for the delivery. If you ever hear of anyone selling lightsabers, let me know.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 215, 'm27p', 'My buddy inherited this collection from an uncle. That old-timer was a blaster freak. Wish the old guy had had some lightsabers, you know?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 216, 'm27t', 'Blaster Collection'),
('string/en/mission/mission_deliver_neutral_medium.stf', 217, 'm28d', 'Having studied Jedi Holocrons all my life, I have been invited to teach at Raithal Academy as a Professor of Myth and Antiquities. Please hand-deliver my acceptance to the local recruiter for prompt delivery to the Academy''s board. You have my thanks.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 218, 'm28l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 219, 'm28o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 220, 'm28r', 'The professor''s acceptance? Excellent. The Empire has already arranged a fitting reception when this estimable scholar arrives at the Academy.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 221, 'm28f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 222, 'm28s', 'A friend has advised me of new circumstances regarding the Raithal Academy. I am instead travelling elsewhere, to distant parts of the galaxy. Here is your fee. Please tell no one.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 223, 'm28p', 'I''m glad to see that the Empire developing a renewed interest in Jedi history and artifacts. Perhaps this signals a change?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 224, 'm28t', 'Jedi Holocron Professorship'),
('string/en/mission/mission_deliver_neutral_medium.stf', 225, 'm29d', 'I once took an interest in genealogy and kept very good records. Now my colleagues think they can use me as a library whenever they wish. Please pick up a copy of my database and deliver it to these annoying scholars. Tell them they can look up the name "Skywalker" themselves. The nerve!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 226, 'm29l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 227, 'm29o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 228, 'm29r', 'I''m certain the name "Skywalker" is important. It may indeed be the key to solving all of the Empire''s problems! Thank you for bringing this.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 229, 'm29f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 230, 'm29s', 'My thanks for the prompt delivery. Perhaps now I can get some peace.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 231, 'm29p', 'Please tell this individual to stop harassing me or I shall inform the authorities. Fate of the Empire indeed!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 232, 'm29t', 'Refuse a Genealogy Request'),
('string/en/mission/mission_deliver_neutral_medium.stf', 233, 'm30d', 'I''m a private investigator and I''m swamped with work. Could you pick up a datadisc of holographs and deliver it to a client? A little matter of a dark suspicion, one partner for another -- the usual stuff. This encrypted disc will settle the matter for good. Thanks.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 234, 'm30l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 235, 'm30o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 236, 'm30r', 'Finally I''ll know the truth! I''m sure this disc will verify my suspicions. Love hurts, you know.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 237, 'm30f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 238, 'm30s', 'Thanks for your help. Some days I hate my job, but it''s a living. Speaking of which, your fee has been deposited.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 239, 'm30p', 'I hope this alleviates my client''s paranoia. Trust is a rare commodity these days.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 240, 'm30t', 'Investigator''s Findings'),
('string/en/mission/mission_deliver_neutral_medium.stf', 241, 'm31d', 'You know they used to clone people, right? I''m convinced my friend has been cloned for nefarious purposes. I need you to pick up a datadisc containing holographs of the clone in action, taken by an investigator I hired. Then take the disc to my friend. This will prove I''m right.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 242, 'm31l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 243, 'm31o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 244, 'm31r', 'Sure, I''ll look at the images, but I just wish my friend would accept the truth. I have not been cloned!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 245, 'm31f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 246, 'm31s', 'Thanks for delivering those pictures. You should make sure you''re not cloned, friend. Otherwise you never know what crimes you might be implicated in.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 247, 'm31p', 'Here''s the disc. I personally think my client''s friend is just leading a very interesting double life. But I''m not being paid for my opinion, so --'),
('string/en/mission/mission_deliver_neutral_medium.stf', 248, 'm31t', 'Clone Holographs?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 249, 'm32d', 'My best friend is about to marry someone unworthy. I hired an investigator to follow the mate-to-be. The investigator has holographs that will prove my friend''s "true love" has been unfaithful. I can''t deliver these myself, or my friend would think I had doctored the images. Can you pick them up and deliver them?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 250, 'm32l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 251, 'm32o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 252, 'm32r', 'What is this? A disc of holographs? What''s on them? Who sent them? Who are you?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 253, 'm32f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 254, 'm32s', 'Thanks for your help. I hope you didn''t mention my name. I''m only trying to save my friend future heartache.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 255, 'm32p', 'Here are the holographs. I gotta admit, some of them are rather amusing. But don''t tell my employer I said that.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 256, 'm32t', 'Deeply Incriminating Holos'),
('string/en/mission/mission_deliver_neutral_medium.stf', 257, 'm33d', 'I''m a scout for a major music label and don''t have time for amateurs. The vocals on these latest sample tracks sound like the death rattle of a Tatooine meewit. This so-called musician included credits to make sure this ''precious'' recording was returned safely. Could you pick it up and get it out of my life? Don''t try to listen to this mess.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 258, 'm33l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 259, 'm33o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 260, 'm33r', 'They''ve returned my work? Why? Did they like it? Do I have a contract? What''s wrong with these people? They''re Tusken when it comes to music!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 261, 'm33f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 262, 'm33s', 'Thanks for dropping off that cacophonous mangle. I hope the artist goes into a more appropriate line of work, like custodial duty or food service. Your fee is taken care of.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 263, 'm33p', 'You gotta listen to a bunch of garbage before you find anyone with even a shred of talent. You don''t play, by any chance?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 264, 'm33t', 'Meewit Death Rattle Music'),
('string/en/mission/mission_deliver_neutral_medium.stf', 265, 'm34d', 'Well, I finished off my latest batch of scribblings. I barely call them stories, really, hardly worthy of the name. Writers mostly scribble anyhow; aren''t many who have anything worth saying. Anyway, for whatever reason, a publisher wants to see these. So go ahead, take them.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 266, 'm34l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 267, 'm34o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 268, 'm34r', 'Great! This writer is fantastic. It''s a real honor to publish these stories. I only hope that the political content is a little more -- subdued this time.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 269, 'm34f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 270, 'm34s', 'Really, the whole foofaraw over these jottings baffles me. Ah well, life is a mystery.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 271, 'm34p', 'Here you go. If you lose them, I don''t care. Just trifles, after all.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 272, 'm34t', 'New Jottings From an Author'),
('string/en/mission/mission_deliver_neutral_medium.stf', 273, 'm35d', '''Have you ever seen the nocturnal Nexu? Noticed all the different kinds of banthas there are? Now children across the galaxy can learn about amazing animals on a hundred worlds, and in addition see delightful full-color holographs of each beast at work or play.'' That''s what the blurb says, at any rate. Well, I need someone to deliver this mess, and I guess you''re it.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 274, 'm35l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 275, 'm35o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 276, 'm35r', 'Great, we''ll rush this to distribution right away.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 277, 'm35f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 278, 'm35s', 'Now the publisher can shill one more sentimental mess to gullible parents. Gaah, I need a drink.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 279, 'm35p', 'I knocked off the writing duties on this hack job in -- well, I won''t say how quickly, it embarrasses me. Have fun delivering it.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 280, 'm35t', 'Hackwork'),
('string/en/mission/mission_deliver_neutral_medium.stf', 281, 'm36d', 'My magnum opus, a reference work cataloging the various minerals of the galaxy, is finally complete. Some may call it dry or dull, but it is a grand work of scholarship, and I have been careful to annotate every reference. Every mineral description is accompanied by a holograph of both the mineral itself and of its molecular structure. Now all I need is for you to hand-deliver it to the publisher.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 282, 'm36l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 283, 'm36o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 284, 'm36r', 'Excellent! I imagine that this one will become a bestseller in short order.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_neutral_medium.stf', 285, 'm36f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 286, 'm36s', 'Thank you. The audience for mineralogical texts across the galaxy is vanishingly small in percentage terms, but in sheer numbers is quite enough to guarantee me a comfortable living.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 287, 'm36p', 'I do hope that you find the time to read my manuscript along the way. I recommend the section on theodolites.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 288, 'm36t', 'Mineralogy Manuscript'),
('string/en/mission/mission_deliver_neutral_medium.stf', 289, 'm37d', 'I feel guilty that it has taken this long for this legal document to be delivered. I know that we should not have kept an indentured servant so long, but over time, it felt like we were all one big happy family. But now, we''ve moved away, and well, it''s time for justice to be done and for freedom to have its day.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 290, 'm37l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 291, 'm37o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 292, 'm37r', 'What... can it be? Freedom? Freedom! I am free! Free!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 293, 'm37f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 294, 'm37s', 'I feel much better. I wish our former servant well in whatever pursuit freedom brings.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 295, 'm37p', 'I hope that our servant gets joy from this.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 296, 'm37t', 'Manumission Documents'),
('string/en/mission/mission_deliver_neutral_medium.stf', 297, 'm38d', 'Check this thing out! It''s like a hologame, except you play it piggybacking on the Holonet, see? And you play with thousands of other people at the same time. So I have a copy of it here that''s, you know, uh, kind of cracked? And I wanna slip it to my friend so we can play together.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 298, 'm38l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 299, 'm38o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 300, 'm38r', 'What, this game? Aw, c''mon. The lag time from here to the servers on Coruscant is terrible. Plus the controls are way too hard, especially the camera system.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 301, 'm38f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 302, 'm38s', 'Now I''m all down. Turns out the game server checks for cracked copies. It burned out my rig!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 303, 'm38p', 'This game totally rocks. You have like hundreds of species to choose from, and you can be anything from a smuggler to a bounty hunter to a -- shh, don''t tell the Empire -- a Jedi!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 304, 'm38t', 'A New Game Crack'),
('string/en/mission/mission_deliver_neutral_medium.stf', 305, 'm39d', 'I bought a used computer, and it has all sorts of strange files. I think the previous owner was a slicer. Anyway, there are schematics in those files that say ''Death Star.'' I think it''s someone''s idea of a sick joke. Anyway, I put the schematics on a disc and my friend wants to look at it. Will you deliver it?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 306, 'm39l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 307, 'm39o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 308, 'm39r', 'Schematics? Oh, right! My friend told me about this. Wonder how much it costs to build a Death Star?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 309, 'm39f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 310, 'm39s', 'Thanks. There''s some wild stuff on that computer. Gotta keep going through those files.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 311, 'm39p', 'Here you go. My friend will know how to decrypt it.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 312, 'm39t', 'Death Star Schematics?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 313, 'm40d', 'My friends love keeping up with the latest fashions. An acquaintance is putting a whole bunch of facial tattoo patterns on a datadisc for us. Could you please pick up the disc and deliver it to my friend?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 314, 'm40l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 315, 'm40o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 316, 'm40r', 'Wow! Thanks for the disc. I can''t wait to try out these new make-up tips. We''ll be the hit of all the dance clubs. If we ever got to go, that is.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 317, 'm40f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 318, 'm40s', 'Thanks for the delivery. Those tattoos are supposedly worn by the Nightsisters of Dathomir. Wouldn''t that be a great name for a band? Maybe we''ll start one. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 319, 'm40p', 'It''s important to keep up with fashion, you know. A person''s clothes and make-up say a lot. For example, your clothes speak volumes.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 320, 'm40t', 'Tattoos Are Fashionable'),
('string/en/mission/mission_deliver_neutral_medium.stf', 321, 'm41d', 'A friend just got the specs for the newest Ommni Box that''s about to hit the market. This thing can make even the crummiest band sound great. Just what we need! Could you pick up these specs and take them to my band buddy? Once the rest of the band sees this, I know they''ll chip in with me to buy it. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 322, 'm41l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 323, 'm41o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 324, 'm41r', 'Let''s see if this toy is as good as my friend claims. If it is, we''ll send you a copy of our first recording. How''s that?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 325, 'm41f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 326, 'm41s', 'This Ommni Box is gonna pave the way for our rise to super-stardom. I just know it! You remember me, I''m gonna be famous.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 327, 'm41p', 'The specs are on this datadisc. Tell those wanna-be musicians that this Ommni Box can''t perform miracles. Good luck.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 328, 'm41t', 'Ommni Box Breakthrough'),
('string/en/mission/mission_deliver_neutral_medium.stf', 329, 'm42d', 'I got my hands on a great hologram recording called "Twi''lek Ladies Gone Wild." I just gotta share it with my buddies. They''ll flip. It''s on this datadisc. Tell them to pay particular attention to the scene with Oola and the Yuzzem.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 330, 'm42l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 331, 'm42o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 332, 'm42r', 'Here it is! The gang is gonna freak. Thanks, buddy, you made our day. Party time!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 333, 'm42f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 334, 'm42s', 'Thanks for delivering that disc. I hope you didn''t pirate it, because we both know that would be very, very wrong. (Snort!)'),
('string/en/mission/mission_deliver_neutral_medium.stf', 335, 'm42p', 'If you can find a copy of this, you should certainly purchase it. It''s credits well spent.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 336, 'm42t', 'Twi''lek Ladies Gone Wild!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 337, 'm43d', 'Why are power converters so hard to find? I''ve looked everywhere. Why does this always happen to me? It''s not fair! I want some power converters! Is that too much to ask? Could you please pick up a purchase order and deliver it to a local supplier for me? I''d go myself, but I have to finish cleaning some droids.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 338, 'm43l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 339, 'm43o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 340, 'm43r', 'This whiny customer again? I should never have special-ordered those fuel cells. Now I''ll never get any rest. Fine, I''ll get right on it.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 341, 'm43f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 342, 'm43s', 'Life is so unfair. Did you ever have one of those days? Well that''s my whole life. Why me? Oh, thanks for your help.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 343, 'm43p', 'Here you go. I hope this supplier can fill this order. That farm kid is getting annoying.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 344, 'm43t', 'Why No Power Converters?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 345, 'm44d', 'My friend wants to check out the newest recording by the popular band "Dance Lords of the Bith." If you don''t find yourself moving to this music, you''re probably dead. It''s currently on loan to a neighbor. Could you pick up the recording and deliver it? Can''t wait to hear this at the cantina.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 346, 'm44l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 347, 'm44o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 348, 'm44r', 'The Dance Lords! Great! I heard this music is hot jets at the smoothest clubs on Coruscant. Can''t wait to get smooth to its beat. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 349, 'm44f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 350, 'm44s', 'Thanks for your help. We should all strive to give the gift of music. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 351, 'm44p', 'There you are. This music moves your spirit, you know? Feel the beat, zoomer!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 352, 'm44t', 'Dance Lords Recording'),
('string/en/mission/mission_deliver_neutral_medium.stf', 353, 'm45d', 'I was adopted as a child. After years of searching, I think I''ve finally found my real mother. Could you pick up some flowers and deliver them to her, along with an invitation to dinner? I can''t deliver it myself, on the off chance that I''m wrong. Oh, I hope I''m not. Thank you so much for your help.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 354, 'm45l', 'Invite to dinner needs delivered'),
('string/en/mission/mission_deliver_neutral_medium.stf', 355, 'm45o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 356, 'm45r', 'Nope, sorry, you got the wrong person. I''ve never been a mother and never hope to be. I may accept the dinner invitation anyway, though. And the flowers are nice.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 357, 'm45f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 358, 'm45s', 'Thanks so much for giving my mother that invitation. I''m going to make fleek eel soup. It''ll be grand! Too bad you can''t join us.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 359, 'm45p', 'A bouquet of flowers as ordered. Is this for a sweetheart? Oh, you''re doing this for someone else? How nice.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 360, 'm45t', 'Deliver dinner invite'),
('string/en/mission/mission_deliver_neutral_medium.stf', 361, 'm46d', 'Four-cubes will break you spiritually as well as financially. I need someone to pick up a datadisc from my bookie and deliver it to a fellow player. The disc contains codes to access my credits. They''re all encrypted, so don''t even think about keeping it. Plus, you wouldn''t want to add a Hutt to your list of enemies, would you?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 362, 'm46l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 363, 'm46o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 364, 'm46r', 'Looks like this loser got some common sense. Good. I was about to start hiring bounty hunters.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 365, 'm46f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 366, 'm46s', 'Don''t gamble, friend. Just don''t. It leads to an early grave and heartache while you live. And worry not, I instructed my bookie to deposit your fee. Now I''m totally broke.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 367, 'm46p', 'Some beings just don''t know when to leave well enough alone. Why is it that gambling attracts so many folks with bad luck? Anyway, here''s the disc.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 368, 'm46t', 'Deliver a gambling debt'),
('string/en/mission/mission_deliver_neutral_medium.stf', 369, 'm47d', 'I''ve finished the definitive work on training hunting twirrls. It should become quite a popular sport among the nobles and the rich on Coruscant. It is, after all, already a distinguished sport on Naboo for persons of higher breeding. Please pick up my manuscript and deliver it to my editor for proofreading.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 370, 'm47l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 371, 'm47o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 372, 'm47r', 'This author''s previous works have always been of superior quality -- always well researched. I can''t wait to peruse this one.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 373, 'm47f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 374, 'm47s', 'Thank you ever so much for taking care of that. I hope you''ll find my compensation satisfactory. Must run now.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 375, 'm47p', 'Yes, here''s the manuscript. Have you ever tried twirrl hunting? No, I guess you wouldn''t have, would you? Carry on.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 376, 'm47t', 'Twirrl Manuscript'),
('string/en/mission/mission_deliver_neutral_medium.stf', 377, 'm48d', 'My partner has just received a new litter of tusk-cats. A friend of ours wants the pick of the litter. Please pick up a datadisc containing holographs of all the cubs from my partner and deliver it our friend. This will help our friend make a good choice. Thank you.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 378, 'm48l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 379, 'm48o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 380, 'm48r', 'That litter is in already? Splendid! My son has been looking forward to this moment. The cub is for him, you know. '),
('string/en/mission/mission_deliver_neutral_medium.stf', 381, 'm48f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 382, 'm48s', 'Thanks for your help, friend. I hope our friend finds something worth purchasing.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 383, 'm48p', 'Nothing like a strong tusk-cat at your side. These are some of the finest from the top kennels in Theed. I''m sure these holographs will demonstrate their quality.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 384, 'm48t', 'Finest Tusk-Cats From Theed'),
('string/en/mission/mission_deliver_neutral_medium.stf', 385, 'm49d', 'I have finally found my father''s murderer and have put a price on the killer''s head. However, due to our past, I will give the wretch a fighting chance. I need you to pick up a copy of the hunt certificate and deliver it to the guilty party. That should give this murderer a chance to make all the proper arrangements. I''ve made mine.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 386, 'm49l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 387, 'm49o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 388, 'm49r', 'A death threat? But I''ve never killed anyone! I''m innocent! This is all a huge mistake!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 389, 'm49f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 390, 'm49s', 'I know this task was unpleasant, and I appreciate your professionalism in carrying it out.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 391, 'm49p', 'Feel free to tell this individual that you''re only the messenger, not the instrument of death itself.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 392, 'm49t', 'Death Threat'),
('string/en/mission/mission_deliver_neutral_medium.stf', 393, 'm50d', 'You must help me! My cousin has been falsely accused by some vengeful lunatic of murdering a loved one. I need you to pick up the evidence exonerating him -- a commercial transport manifest dated the day this maniac claims the murder took place. The passenger list proves my cousin was on that ship and couldn''t have murdered anyone!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 394, 'm50l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 395, 'm50o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 396, 'm50r', 'The deathmark has been ordered. This disc proves nothing; records can be falsified. Justice will be served at last.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 397, 'm50f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 398, 'm50s', 'Thank you for attending to this matter so quickly! I hope our efforts are enough to save my cousin''s life!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 399, 'm50p', 'Here''s the disc! Please hurry! Our cousin''s life is in your hands!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 400, 'm50t', 'Proof of Innocence'),
('string/en/mission/mission_deliver_neutral_medium.stf', 401, 'm51d', 'I''ve managed to find actual live recordings of krayt dragons. My friend is a naturalist and has been studying krayts for years. A book on the subject is in the works, I understand. Could you pick up the datadisc contains the recordings and drop it off with my friend? I''m sure they''d be most useful.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 402, 'm51l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium.stf', 403, 'm51o', ''),
('string/en/mission/mission_deliver_neutral_medium.stf', 404, 'm51r', 'The krayt dragon recordings! This will be such a boon to my research. Thank you so much!'),
('string/en/mission/mission_deliver_neutral_medium.stf', 405, 'm51f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium.stf', 406, 'm51s', 'I would love to see the look on my friend''s face when these recordings are played. Alas, if only I wasn''t so busy I could pay my friend a visit. Thanks for your help.'),
('string/en/mission/mission_deliver_neutral_medium.stf', 407, 'm51p', 'I''ve listened to these recordings. Truly amazing stuff. Who knew krayt dragons vocalized to this degree?'),
('string/en/mission/mission_deliver_neutral_medium.stf', 408, 'm51t', 'Krayt Dragon Roars'),
('string/en/mission/mission_deliver_neutral_medium.stf', 409, 'number_of_entries', '51'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 1, 'm1d', 'I''m submitting my application to the Academy at long last. Won''t my friends be jealous when they hear I''ve become a TIE pilot? But I can''t trust something this important to the HoloNet. Could you pick up my application from my friend''s home and hand-deliver it to a professional courier?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 5, 'm1r', 'Another star jockey wanna-be, eh? All right, I''ll see that it''s delivered to the Academy.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 6, 'm1p', 'My best friend''s future is in your hands. Please be careful and see that it gets to its destination. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 7, 'm1t', 'A New TIE Pilot'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 8, 'm1s', 'Thanks, buddy! You''re the kind of friend someone wishes for. I deposited a little something into your account.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 9, 'm2d', 'I was investigating a missing person''s case for a client to discover what had happened to their son. Apparently the young man was on Alderaan when it -- well, you know. His final letters are stored on a datadisc. I regret I can''t deliver the datadisc in person but I''m keeping a low profile. My investigation attracted some unwanted Imperial attention.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 12, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 13, 'm2r', 'What? This can''t be! A plague upon the Empire! Those assassins don''t deserve our loyalty! Oh, my son! My dear son!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 14, 'm2p', 'Please be sensitive when delivering this message. It will no doubt come as a great shock to the recipient.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 15, 'm2t', 'Tragic News'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 16, 'm2s', 'Did anyone appear to be following you when you made the delivery? I''d keep a low profile, just in case. Your fee has been transmitted to your account.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 17, 'm3d', 'The happy day has come at last! My only daughter is getting married. Could you pick up the very first holographic invitation from the data engineer and hand-deliver it to my oldest friend? That should impress my friend. '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 21, 'm3r', 'Well, it''s about time! I knew that girl would get hitched sooner or later. Can''t wait to tell the family. Wedding invitations on datadisc. Heh! How times change.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 22, 'm3p', 'Here''s the personalized invitation. This is quite the elaborate presentation, lots of animation and music. Family must be rich.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 23, 'm3t', 'Bring Nuptial News'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 24, 'm3s', 'Thanks for delivering that invitation. My friend was most impressed. I''m not rich, but my daughter''s first -- and, I hope, only -- wedding is worth a splurge.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 25, 'm4d', 'I''ve finished my survey of the Core''s asteroid fields and have charted every known space slug in those sectors. I need someone to pick up the survey datadisc from my lab and deliver it to a representative of the Imperial Science Department''s Biology Division -- they need to double-check my stats before we transmit it to the Imperial Information Center.   '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 29, 'm4r', 'Ah, the survey results! I''ll check these findings immediately. I hope my superiors keep me in mind when assigning scientists to study those space slugs.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 30, 'm4p', 'By delivering this datadisc you are furthering the cause of science. We''re counting on you!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 31, 'm4t', 'Space Slug Survey Map'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 32, 'm4s', 'Thanks for getting that to my colleague so quickly. I''ve deposited your fee for services rendered.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 33, 'm5d', 'My company has just finished logging the inventory of one of our client''s holdings. It''s all been stored on a datadisc that has everything itemized by sale price. The appraisals were done by the most careful and painstaking professionals in the field. Could you pick up the inventory and deliver it to our client?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 37, 'm5r', 'It''s about time! I paid good money for these appraisals, and I expected them to be done long since. I''ll adjust my final payment to the company accordingly.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 38, 'm5p', 'Our client is most eager to receive this datadisc. Please relay our apologies for tardiness, but we wanted to be thorough.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 39, 'm5t', 'Precise Inventories Take Time'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 40, 'm5s', 'Thank you for your prompt service. I understand that our client was a tad upset. We''ll try to smooth things over. Your pay has been deposited.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 41, 'm6d', 'A customer''s daughter is getting married soon, and she needs a dress in a week. Could you pick up the datadisc containing the dress pattern from my customer? Please deliver it to my colleague''s fabric shop so I can be sent the appropriate fabrics. I''m swamped with work and can''t go myself.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 45, 'm6r', 'This will be quite a dress. The pattern calls for some pretty exotic fabrics -- spidersilk saturated with glimmerdust, prismatic zwill, resublimated nanoweave. Hope this customer is rich.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 46, 'm6p', 'It will be a gown fit for a queen. Do please hurry with the delivery. Thank you.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 47, 'm6t', 'Beautiful Bridal Gown'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 48, 'm6s', 'Thank you so much for being prompt. If you ever need clothes, look me up -- once I''m not so swamped, that is.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 49, 'm7d', 'A friend''s child has been sick, stricken with body sores. I know an old family remedy that never fails, regardless of the species involved. Could you pick up the datadisc with the recipe for this poultice and the accompanying herbs from a local pharmacist? Then please deliver the goods to my friend.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 53, 'm7r', 'My poor child, how they suffer. I''ll give this remedy a try. Thank you so much for delivering it. I''ll let my friend know if it worked.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 54, 'm7p', 'Apply this poultice three times a day. Remind the customer to make a fresh batch every day, and wrap the unused portion tightly before throwing it out. '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 55, 'm7t', 'Cure for an Ailing Child'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 56, 'm7s', 'My thanks for the prompt delivery. I hope my friend''s child gets better once this remedy is used.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 57, 'm8d', 'I won''t be able to attend my nephew''s birthday celebration this year.  But I made a special holocam recording of me singing his favorite nursery rhymes. Could you pick up the recording and make sure the family gets it in time for the party? Thank you so much.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 61, 'm8r', 'Is this for the birthday boy? I''m helping put together his party. I''m sure he''ll be pleased to get this. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 62, 'm8p', 'Just finished editing the holo. It certainly is -- something. I hope the kid likes it.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 63, 'm8t', 'Birthday Gift Is Really Something'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 64, 'm8s', 'I hope my nephew appreciates all my hard work. He can be such a sweet boy if the mood strikes him. Thank you for your help.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 65, 'm9d', 'A miner friend found some crystal deposits while out prospecting in the Outer Rim. He won''t say where exactly he found them. Claims he''s going to get rich or something. He wants me to have some crystal samples analyzed for him. Can you pick up the samples and deliver them to a mineralogist I know?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 66, 'm9l', 'Crystals'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 68, 'm9f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 69, 'm9r', 'Crystals, eh? Sure, I''ll have a look. Prospectors keep dreaming they''ll find another source of Adegan crystals. They used to use those in lightsabers, you know.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 70, 'm9p', 'These might just be worthless rocks. I hope my friend can help me identify them. Oh, does the word ''Adegan'' mean anything to you?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 71, 'm9t', 'Mysterious Crystals'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 72, 'm9s', 'Thanks for delivering those crystals. My friend is always having me check out all sorts of minerals. The mother lode is waiting, somewhere out there.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 73, 'm10d', 'My employer sells antiques to interested buyers. One such collector has paid the proper fee to view my employer''s wares. Could you pick up an encrypted catalog and deliver it? The collector will know how to retrieve the data.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 77, 'm10r', 'The catalog at last! I''ve waited a long time for this. The possibility of Sith artifacts! Can you imagine?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 78, 'm10p', 'Nothing is free, pal.  If you want to look, you gotta pay the fee too. Actually, you probably can''t afford it. Deliver this quick, though, and you might be on your way to earning enough.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 79, 'm10t', 'Antique Catalog'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 80, 'm10s', 'By the way, the contents of our catalog are confidential. Please respect our privacy.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 81, 'm11d', 'Fleek eels are a prized delicacy that must be kept alive until they''re cooked or else the flavor is greatly diminished. I found a way to preserve the eels so that none of the flavor is lost. I need you to pick up a sample and deliver it promptly to a representative of the Corporate Sector Authority. Their food companies can make millions off my secret recipe!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 82, 'm11l', 'Small container'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 84, 'm11f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 85, 'm11r', 'This sample will be tested, of course. If it fails to meet our taste standards, there will be no compensation. That is, in fact, what we are expecting.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 86, 'm11p', 'I knew all those years my friend spent studying preservatives would pay off. I hope he doesn''t forget me when he''s filthy rich. Please be careful with this delivery!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 87, 'm11t', 'Fleek Eels Soon to Be Preserved'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 88, 'm11s', 'Thanks, citizen! I can''t wait for those CSA chefs to taste those preserved fleek eels and marvel at my genius!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 89, 'm12d', 'Can you keep a secret? I''m a great Jedi Master who used to lead the Jedi Council in the days of the Old Republic. We''re in hiding, waiting for the right moment to destroy the Empire. I need you to pick up a secret message from one of our contacts and deliver it to a fellow Jedi. This is of the greatest importance. Can you handle it?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 93, 'm12r', 'Not this lunatic again! Who is it this time? Last week it was the Emperor. This is just a grocery list, for Corellia''s sake! Poor sod needs professional help. '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 94, 'm12p', 'The fate of the galaxy is in your hands. Know that the Force will be with you, always. Unless you fail. Then you''re bantha fodder. Good luck.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 95, 'm12t', 'The Return of the Jedi?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 96, 'm12s', 'Thank you for serving the interests of the Jedi. Soon we will come out of hiding and restore the Republic. Honest.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 97, 'm13d', 'I finally managed to sell my old JR-4 swoop. Got a good price for it, too. I need you to pick up the title and deliver it to the new owner. Thanks, buddy!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 101, 'm13r', 'The title! Great! I''ve already started to modify the JR-4. It was in great condition.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 102, 'm13p', 'Here you go. You into speeders and swoops like me and my buddy? Check out the Flare-S swoop if you ever get a chance. Nice.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 103, 'm13t', 'Swoop Title'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 104, 'm13s', 'Thanks for taking care of that for me, buddy. I can''t wait to buy the new TaggeCo Air-2 swoop. Now that''s a sweet ride!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 105, 'm14d', 'Someone wants to buy my vintage blaster collection, including my matching set of MB-450''s. Luxan Personal Armaments is the best, and the Penetrator is the elite of hunting pistols. I have a datadisc -- holographs and detailed specs of everything in my collection -- to be delivered to the buyer. Can you pick it up from my friend.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 109, 'm14r', 'Can''t wait to see what''s on this datadisc. I love blasters. Don''t you? Nothing like the weight of a solid weapon in your hands, eh?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 110, 'm14p', 'My buddy inherited this collection from an uncle. That old-timer was a blaster freak. Wish the old guy had had some lightsabers, you know?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 111, 'm14t', 'Blaster Catalog'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 112, 'm14s', 'Thanks for the delivery. If you ever hear of anyone selling lightsabers, let me know.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 113, 'm15d', 'I once took an interest in genealogy and kept very good records. Now my colleagues think they can use me as a library whenever they wish. Please pick up a copy of my database and deliver it to one of these annoying scholars. Tell them they can look up the name "Skywalker" themselves. The nerve! '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 117, 'm15r', 'I''m certain the name "Skywalker" is important. It may indeed be the key to solving all of the Empire''s problems! Thank you for bringing this.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 118, 'm15p', 'Please tell this scholar to stop harassing our family or else we shall refuse future requests. Fate of the Empire indeed!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 119, 'm15t', 'Genealogical Studies'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 120, 'm15s', 'My thanks for the prompt delivery. Perhaps now I can get some peace.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 121, 'm16d', 'I''m a private investigator and I''m swamped with work. Could you pick up a datadisc of holographs and deliver it to a client? Little matter of a dark suspicion, one partner for another. This encrypted disc will settle the matter for good. Thanks.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 125, 'm16r', 'Finally I''ll know the truth! I''m sure this disc will verify my suspicions. Love hurts, you know.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 126, 'm16p', 'I hope this alleviates my client''s paranoia. Trust is a rare commodity these days.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 127, 'm16t', 'Help a Private Investigator'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 128, 'm16s', 'Thanks for your help. Somedays I hate my job, but it''s a living. Speaking of which, your fee has been deposited.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 129, 'm17d', 'You know they used to clone people, right? I''m convinced my friend has been cloned for nefarious purposes. I need you to pick up a datadisc containing holographs of the clone in action, taken by an investigator I hired. Then take the disc to my friend. This will prove I''m right.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 133, 'm17r', 'Sure, I''ll look at the images, but I just wish my friend would accept the truth. I have not been cloned!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 134, 'm17p', 'Here''s the disc. I personally think my client''s friend is just leading a very interesting double life. But I''m not being paid for my opinion, so --'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 135, 'm17t', 'Mistaken identity?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 136, 'm17s', 'Thanks for delivering those pictures. You should make sure you''re not cloned, friend. Otherwise you never know what crimes you might be implicated in.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 137, 'm18d', 'My best friend is about to marry someone unworthy. I hired an investigator to follow the mate-to-be. The investigator has holographs that will prove my friend''s "true love" has been unfaithful. I can''t deliver these myself, or my friend would think I had doctored the images. Can you pick them up and deliver them?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 141, 'm18r', 'What is this? A disc of holographs? What''s on them? Who sent them? Who are you?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 142, 'm18p', 'Here are the holographs. I gotta admit, some of them are rather amusing. But don''t tell my employer I said that.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 143, 'm18t', 'Incriminating Holographs'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 144, 'm18s', 'Thanks for your help. I hope you didn''t mention my name. I''m only trying to save my friend future heartache.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 145, 'm19d', 'I''m a scout for a major music label and don''t have time for amateurs. The vocals on these latest sample tracks sound like the death rattle of a Tatooine meewit. This so-called musician included credits to make sure this ''precious'' recording was returned safely. Could you pick it up and get it out of my life? Don''t try to listen to this mess.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 149, 'm19r', 'They''ve returned my work? Why? Did they like it? Do I have a contract? What''s wrong with these people? They''re Tusken when it comes to music!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 150, 'm19p', 'You gotta listen to a bunch of garbage before you find anyone with even a shred of talent. You don''t play, by any chance?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 151, 'm19t', 'Bad News for a Musician'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 152, 'm19s', 'Thanks for dropping of that cacophonous mangle. I hope the artist goes into a more appropriate line of work, like custodial duty or food service. Your fee is taken care of.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 153, 'm20d', 'I feel guilty that it has taken this long to deliver a legal document. I know that we should not have kept an indentured servant so long, but over time, it felt like we were all one big happy family. Well, it''s time for justice to be done and for freedom to have its day. Can you pick up this document from my family and deliver it?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 157, 'm20r', 'What... can it be? Freedom? Freedom! I am free! Free!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 158, 'm20p', 'Here''s the document. Please inform this individual that they''ll be missed.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 159, 'm20t', 'Free an Indentured Servant'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 160, 'm20s', 'Thanks for getting that done. Next time I''ll be a bit more conscientious about such things.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 161, 'm21d', 'My friends love keeping up with the latest fashions. An acquaintance is putting a whole bunch of facial tattoo patterns on a datadisc for us. Could you please pick up and deliver this disc to my friend?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 165, 'm21r', 'Wow! Thanks for the disc. I can''t wait to try out these new make-up tips. We''ll be the hit of all the dance clubs.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 166, 'm21p', 'It''s important to keep up with fashion, you know. A person''s clothes and make-up say a lot. For example, your clothes speak volumes.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 167, 'm21t', 'Fashionable Facial Tattoos'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 168, 'm21s', 'Thanks for the delivery. Those tattoos are supposedly worn by the Nightsisters of Dathomir. Wouldn''t that be a great name for a band? Maybe we''ll start one. '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 169, 'm22d', 'A friend just got the specs for the newest Ommni Box that''s about to hit the market. This thing can make even the crummiest band sound great. Just what we need! Could you pick up these specs and take them to my band buddy? Once the rest of the band sees this, I know they''ll chip in with me to buy it. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 173, 'm22r', 'Let''s see if this toy is as good as my friend claims. If it is, we''ll send you a copy of our first recording. How''s that?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 174, 'm22p', 'The specs are on this datadisc. Tell those wanna-be musicians that this Ommni Box can''t perform miracles. Good luck.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 175, 'm22t', 'Amateur Band Seeks Ommni Box'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 176, 'm22s', 'This Ommni Box is gonna pave the way for our rise to super-stardom. I just know it! You remember me, I''m gonna be famous.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 177, 'm23d', 'I''ve managed to find actual live recordings of krayt dragons. My friend is a naturalist and has been studying krayts for years. A book on the subject is in the works, I understand. Could you pick up the datadisc contains the recordings and drop it off with my friend? I''m sure they''d be most useful.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 181, 'm23r', 'The krayt dragon recordings! This will be such a boon to my research. Thank you so much!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 182, 'm23p', 'I''ve listened to these recordings. Truly amazing stuff. Who knew krayt dragons vocalized to this degree?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 183, 'm23t', 'Help conduct research'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 184, 'm23s', 'I would love to see the look on my friend''s face when these recordings are played. Alas, if only I wasn''t so busy I could pay my friend a visit. Thanks for your help.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 185, 'm24d', 'Why are power converters so hard to find? I''ve looked everywhere. Why does this always happen to me? It''s not fair! I want some power converters! Is that too much to ask? Could you please pick up a purchase order and deliver it to a local supplier for me? I''d go myself, but I have to finish cleaning some droids.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 188, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 189, 'm24r', 'This whiny customer again? I should never have special-ordered those fuel cells. Now I''ll never get any rest. Fine, I''ll get right on it.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 190, 'm24p', 'Here you go. I hope this supplier can fill this order. That farm kid is getting annoying.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 191, 'm24t', 'Get Some Power Converters'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 192, 'm24s', 'Life is so unfair. Did you ever have one of those days? Well that''s my whole life. Why me? Oh, thanks for your help.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 193, 'm25d', 'My friend wants to check out the newest recording by the popular band "Dance Lords of the Bith." If you don''t find yourself moving to this music, you''re probably dead. It''s currently on loan to a neighbor. Could you pick up the recording and deliver it? Can''t wait to hear this at the club. '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 197, 'm25r', 'The Dance Lords! Great! I heard this music is hot jets at the smoothest clubs on Coruscant. Can''t wait to get smooth to its beat. Thanks!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 198, 'm25p', 'There you are. This music moves your spirit, you know? Feel the beat, zoomer!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 199, 'm25t', 'Dance Lords of the Bith!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 200, 'm25s', 'Thanks for your help. We should all strive to give the gift of music. '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 201, 'm26d', 'I was adopted when I was a child. After years of searching, I think I''ve finally found my real mother. Could you pick up some flowers and deliver them to her, along with an invitation to dinner? I can''t deliver it myself, on the off chance that I''m wrong. Oh, I hope I''m not. Thank you so much for your help.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 202, 'm26l', 'Flowers'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 203, 'm26o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 204, 'm26f', 'filename_of_object'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 205, 'm26r', 'Nope, sorry, you got the wrong person. I''ve never been a mother and never hope to be. I may accept the dinner invitation anyway, though. And the flowers are nice.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 206, 'm26p', 'A bouquet of flowers as ordered. Is this for a sweetheart? Oh, you''re doing this for someone else? How nice.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 207, 'm26t', 'Reunite a Family'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 208, 'm26s', 'Thanks so much for giving my mother that invitation. I''m going to make fleek eel soup. It''ll be grand! Too bad you can''t join us.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 209, 'm27d', 'Four-cubes will break you spiritually as well as financially. I need someone to pick up a datadisc from my bookie and deliver it to a fellow player. The disc contains codes to access my credits. They''re all encrypted, so don''t even think about keeping it. Plus, you wouldn''t want to add a Hutt to your list of enemies, would you?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 210, 'm27l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 211, 'm27o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 212, 'm27f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 213, 'm27r', 'Looks like this loser got some common sense. Good. I was about to start hiring bounty hunters.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 214, 'm27p', 'Some beings just don''t know when to leave well enough alone. Why is it that gambling attracts so many folks with bad luck? Anyway, here''s the disc.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 215, 'm27t', 'Pay Off a Hutt'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 216, 'm27s', 'Don''t gamble, friend. Just don''t. It leads to an early grave and heartache while you live. And worry not, I instructed my bookie to deposit your fee. Now I''m totally broke.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 217, 'm28d', 'I''ve finished the definitive work on training hunting twirrls. It should become quite a popular sport among the nobles and the rich on Coruscant. It is, after all, already a distinguished sport on Naboo for persons of higher breeding. Please pick up my manuscript and deliver it to my editor for proofreading.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 218, 'm28l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 219, 'm28o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 220, 'm28f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 221, 'm28r', 'This author''s previous works have always been of superior quality -- always well researched. I can''t wait to peruse this one.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 222, 'm28p', 'Yes, here''s the manuscript. Have you ever tried twirrl hunting? No, I guess you wouldn''t have, would you? Carry on.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 223, 'm28t', 'Popularize Twirrl Hunting'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 224, 'm28s', 'Thank you ever so much for taking care of that. I hope you''ll find my compensation satisfactory. Must run now.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 225, 'm29d', 'My partner has just received a new litter of tusk-cats. A friend of ours wants the pick of the litter. Please pick up a datadisc containing holographs of all the cubs from my partner and deliver it our friend. This will help our friend make a good choice. Thank you.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 226, 'm29l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 227, 'm29o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 228, 'm29f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 229, 'm29r', 'That litter is in already? Splendid! My son has been looking forward to this moment. The cub is for him, you know. '),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 230, 'm29p', 'Nothing like a strong tusk-cat at your side. These are some of the finest from the top kennels in Theed. I''m sure these holographs will demonstrate their quality.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 231, 'm29t', 'Help pick a pet'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 232, 'm29s', 'Thanks for your help, friend. I hope our friend finds something worth purchasing.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 233, 'm30d', 'I have finally found my father''s murderer and have put a price on the killer''s head. However, due to our past, I will give the wretch a fighting chance. I need you to pick up a copy of the hunt certificate and deliver it to the guilty party. That should give this murderer a chance to make all the proper arrangements.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 234, 'm30l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 235, 'm30o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 236, 'm30f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 237, 'm30r', 'A deathmark? But I''ve never killed anyone! I''m innocent! This is all a huge mistake!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 238, 'm30p', 'Feel free to tell this individual that you''re only the messenger, not the instrument of death itself.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 239, 'm30t', 'Deliver a Deathmark'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 240, 'm30s', 'I know this task was unpleasant, and I appreciate your professionalism in carrying it out.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 241, 'm31d', 'You must help me! My cousin has been falsely accused by some vengeful lunatic of murdering a loved one. I need you to pick up the evidence exonerating him -- a commercial transport manifest dated the day this maniac claims the murder took place. The passenger list proves my cousin was on that ship and couldn''t have murdered anyone!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 242, 'm31l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 243, 'm31o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 244, 'm31f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 245, 'm31r', 'The deathmark has been ordered. This disc proves nothing; records can be falsified. Justice will be served at last.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 246, 'm31p', 'Here''s the disc! Please hurry! Our cousin''s life is in your hands!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 247, 'm31t', 'Help Prove Innocence'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 248, 'm31s', 'Thank you for attending to this matter so quickly! I hope our efforts are enough to save my cousin''s life!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 249, 'm32d', 'My cousin was remembered in my late father''s will. I don''t trust this information over the HoloNet -- it''s not much of an inheritance and is bound to be taxed into oblivion. I''m asking you to pick up a copy of the will and deliver it to my cousin''s family. I''m willing to pay a modest fee.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 250, 'm32l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 251, 'm32o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 252, 'm32f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 253, 'm32r', 'Ah, what''s this? An inheritance? I had heard that my friend''s uncle had passed away. I''ll make sure he gets this when he gets home.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 254, 'm32p', 'Here you go. The information about the inheritance is in this datadisc. Please make sure it ends up in the right hands!'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 255, 'm32t', 'About an Inheritance'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 256, 'm32s', 'Thanks for your help. I think this inheritance will come as a surprise to my cousin.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 257, 'm33d', 'I don''t trust my new blaster design to the HoloNet; there are too many slicers out there on the lookout for industrial secrets. The best way to deliver something confidential is to carry it by hand. I need you to pick up an encrypted datadisc containing my design and carry it to the industrialist whom I hope will agree to manufacture it.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 258, 'm33l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 259, 'm33o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 260, 'm33f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 261, 'm33r', 'Another wannabe blaster designer. If you''ve seen one, you''ve seen a million. Well, we''ll look at it and see if it''s any good. Thanks.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 262, 'm33p', 'Here. Please don''t lose it, and please be careful with it! My friend''s whole life is tied up in this blaster design.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 263, 'm33t', 'Life Tied Up in a Blaster'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 264, 'm33s', 'Thanks for delivering my blaster design. If it works, you can tell everyone you played a part in revolutionizing blaster technology.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 265, 'm34d', 'This software is confidential and critical. Suffice it to say that it has significant military applications. We need you to hand carry it, at the client''s insistence; they are extremely paranoid about it going over the HoloNet. Please deliver it to their representative at the agreed location.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 266, 'm34l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 267, 'm34o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 268, 'm34f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 269, 'm34r', 'Thanks for delivering the software. How high is your security clearance? All right, never mind.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 270, 'm34p', 'Here''s the software. Please deliver it promptly. And don''t bother trying to run it -- I promise you don''t have the required hardware.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 271, 'm34t', 'Deliver critical software'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 272, 'm34s', 'Thanks, buddy, we couldn''t have done it without you. You fee has been deposited.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 273, 'm35d', 'I need someone to pick up and deliver a summons. My regular runners are not available, and this case needs to be investigated promptly. Simply serve the summons, and don''t engage the recipient in any significant conversation -- trust me, it won''t go well.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 274, 'm35l', 'Datadisc'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 275, 'm35o', ''),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 276, 'm35f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 277, 'm35r', 'A summons? What? Hey now, why am I getting a summons?'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 278, 'm35p', 'Here''s the summons. Just hand it to the recipient and leave. Not much point in talking.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 279, 'm35t', 'Deliver a summons'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 280, 'm35s', 'Thanks for your help. I hope you weren''t given a hard time. Your fee has been taken care of.'),
('string/en/mission/mission_deliver_neutral_medium_non_persistent_from_npc.stf', 281, 'number_of_entries', '35'),
('string/en/mission/mission_deliver_rebel_easy.stf', 1, 'm1d', 'My son and his family were vacationing on Alderaan when it was destroyed by the Empire. I want to pledge myself to the Rebellion and help topple the bloody regime that took my son''s life. Can you deliver this message to a contact within the Rebellion? I don''t know who to trust.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 4, 'm1r', 'I wish this citizen''s story was unique, but it''s not. We''ll make contact soon.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 6, 'm1s', 'Thank you for handling that matter with such delicacy. You''ll go far.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 7, 'm1p', 'We must do everything we can to put a stop to those butchers.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 8, 'm1t', 'New Recruit'),
('string/en/mission/mission_deliver_rebel_easy.stf', 9, 'm2d', 'I was going to join the Academy, but I saw a hologram of the destruction of Alderaan. It doesn''t matter how I got it. Now I know the truth. A Bothan pilot instructed me to seek a trusted courier to deliver my request to the Rebel Underground. Is that you, citizen?'),
('string/en/mission/mission_deliver_rebel_easy.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 12, 'm2r', 'The more the Empire oppresses its people, the sooner it will fall. We''ll be in touch.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 14, 'm2s', 'Thanks for getting me in touch with the Alliance. I appreciate it.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 15, 'm2p', 'The Empire has no respect for life, citizen.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 16, 'm2t', 'Another Recruit'),
('string/en/mission/mission_deliver_rebel_easy.stf', 17, 'm3d', 'The Empire tricked me into divulging the names of suspected Rebel sympathizers. One was my own father. He was executed, and I was forced to watch the hologram. I want to join the Rebellion and stop this tyranny. Please deliver this message to the underground. I can be found at the local cantina between noon and closing time. I sit at the back, and I always drink alone.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 20, 'm3r', 'This citizen is being destroyed by grief. We''ll see what we can do.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 22, 'm3s', 'Thanks for your help. I''ll do everything I can to stop the Empire. My poor father. His face haunts me.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 23, 'm3p', 'I''ll have to live with this mistake for the rest of my life, citizen. I can hardly bear it.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 24, 'm3t', 'A Heavy Heart'),
('string/en/mission/mission_deliver_rebel_easy.stf', 25, 'm4d', 'A group of dedicated youths is showing support for the Alliance by spraying mustaches on statues of the Emperor. We need you to deliver these special enamel cannisters to their contact. No solvent will remove this enamel, so COMPNOR goons need to burn it off with lasers. It amuses the citizens to see those idiots do this sort of work. Can you help out these kids?  '),
('string/en/mission/mission_deliver_rebel_easy.stf', 26, 'm4l', 'Small cannisters'),
('string/en/mission/mission_deliver_rebel_easy.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 28, 'm4r', 'These will come in handy. Thanks! '),
('string/en/mission/mission_deliver_rebel_easy.stf', 29, 'm4f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_easy.stf', 30, 'm4s', 'No doubt the damaged statues will be replaced in short order, but we''re showing that defiance is possible.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 31, 'm4p', 'Tell them to put colorful patterns on the stormtroopers'' helmets, too!'),
('string/en/mission/mission_deliver_rebel_easy.stf', 32, 'm4t', 'Deface Imperial Statues'),
('string/en/mission/mission_deliver_rebel_easy.stf', 33, 'm5d', 'We''ve heard that COMPNOR is putting on parades to show support for the Emperor. We need these stinkbombs delivered to one of our contacts to pass out to volunteers. They''ll make sure the parade does not go well. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_easy.stf', 34, 'm5l', 'A sealed container'),
('string/en/mission/mission_deliver_rebel_easy.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 36, 'm5r', 'We''ll put these to good use.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 37, 'm5f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_easy.stf', 38, 'm5s', 'I''m sure it will stink less than the latest Imperial opera.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 39, 'm5p', 'A parade for the Emperor seems to invite this sort of foul smell.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 40, 'm5t', 'Stinkbombs for a Parade'),
('string/en/mission/mission_deliver_rebel_easy.stf', 41, 'm6d', 'A teacher who''s sympathetic to the cause of the Alliance has been mentioned in an Imperial Intelligence communique. Can you deliver this warning so we can get the teacher off-planet as quickly as possible? We want to make sure bravery is rewarded, not punished.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 44, 'm6r', 'Thank you, but I choose to stay and continue to spread the idea of freedom.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 45, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 46, 'm6s', 'A very courageous person -- who will come to a bad end if the Empire takes notice.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 47, 'm6p', 'The Alliance looks after its supporters.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 48, 'm6t', 'Dangerous Ground'),
('string/en/mission/mission_deliver_rebel_easy.stf', 49, 'm7d', 'A sweet old citizen who likes baking for the community is about to be arrested. COMPNOR claims she is providing food to Rebels. Take these instructions to one of our contacts so we can get this innocent civilian to safety. Thanks, citizen.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 52, 'm7r', 'I know this woman. She makes great cookies. I''ll see to this personally.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 53, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 54, 'm7s', 'Thank you. We''re happy to help protect this sweet old lady from pointless harrassment.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 55, 'm7p', 'The Empire will always shoot first and ask questions later.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 56, 'm7t', 'Save a Kindly Old Baker'),
('string/en/mission/mission_deliver_rebel_easy.stf', 57, 'm8d', 'We''ve learned that one of our supporters is being given a bottle of poisoned Naboo wine to serve at a party. We need the support of the merchant this individual is courting, so we must not allow that wine to be served. One of our informants is helping to host the party. Can you deliver this bottle of actual Naboo wine, so our contact can switch the bottles out before serving it? Hurry, it may already be too late.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 58, 'm8l', 'Bottle of wine'),
('string/en/mission/mission_deliver_rebel_easy.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 60, 'm8r', 'Good. The party has already started. I''m off.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 61, 'm8f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_easy.stf', 62, 'm8s', 'Good job. The switch was made, and nobody was the wiser.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 63, 'm8p', 'It''s just like COMPNOR to ruin a perfectly good bottle of wine.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 64, 'm8t', 'Poisoned Wine'),
('string/en/mission/mission_deliver_rebel_easy.stf', 65, 'm9d', 'A harmless lunatic has attracted a great deal of unwelcome attention by claiming to be the Emperor. We know that ISB is planning on burning this fool''s house to the ground. Please deliver this warning to the citizen. We don''t know if the idea will get through, but it''s the least we can do.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 68, 'm9r', 'A warning about the Empire? Wait! You''re a Rebel! Guards! Seize this traitor! Guards!'),
('string/en/mission/mission_deliver_rebel_easy.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 70, 'm9s', 'That poor lunatic is going to get killed. I wish there were more we could do.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 71, 'm9p', 'An enemy of the Empire is a friend of the Alliance. Actually, is someone claiming to be the Emperor really an enemy of the Empire? Ah well, I don''t need to think about that.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 72, 'm9t', 'Warn a Lunatic'),
('string/en/mission/mission_deliver_rebel_easy.stf', 73, 'm10d', 'One of our secret meeting places has been compromised. We need this warning delivered to our contact with instructions to find a new meeting place. We hope next time we''ll have a more remote location than under some stranger''s home. Can we count on you, citizen?'),
('string/en/mission/mission_deliver_rebel_easy.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 76, 'm10r', 'Thanks for the warning. I''ll inform the others.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 78, 'm10s', 'We must all be cautious of being caught by the Empire. Be careful.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 79, 'm10p', 'Always assume someone is listening to your conversations. That''s a major rule of rebellion.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 80, 'm10t', 'Secret Meeting Place'),
('string/en/mission/mission_deliver_rebel_easy.stf', 81, 'm11d', 'We''ve gotten an ISB uniform and need it delivered to our agent in the field. This will allow us to undertake more covert missions. Can we count on your help, citizen?'),
('string/en/mission/mission_deliver_rebel_easy.stf', 82, 'm11l', 'Uniform'),
('string/en/mission/mission_deliver_rebel_easy.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 84, 'm11r', 'Thanks. Do you think this uniform will make me look fat? Just kidding.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 85, 'm11f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_easy.stf', 86, 'm11s', 'We could use more agents like yourself. Keep up the good work. '),
('string/en/mission/mission_deliver_rebel_easy.stf', 87, 'm11p', 'Thank you for taking such a risky assignment. If you''re found carrying this uniform, the consequences could be severe.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 88, 'm11t', 'Imperial Security Uniform'),
('string/en/mission/mission_deliver_rebel_easy.stf', 89, 'm12d', 'ISB is secretly distributing a list of names among their contacts. They intend to arrest and interrogate everyone on that list. We''ve obtained a copy of that list. Please deliver this copy to our HoloNet slicer so we can warn the targets.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 92, 'm12r', 'I''ll get the word out right away, assuming ISB isn''t blocking the HoloNet again.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 94, 'm12s', 'Thanks for delivering that information. With luck the ISB won''t get any of our people.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 95, 'm12p', 'For every citizen that the Empire arrests, we save five more.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 96, 'm12t', 'Interrogation List'),
('string/en/mission/mission_deliver_rebel_easy.stf', 97, 'm13d', 'We have proof that the Empire has been performing vivisections on alien species. This encrypted datadisc must be delivered to our HoloNet slicer so we can transmit these graphic images to some former senators. We''ll win over the former Imperial bureaucracy yet. Can you help us? '),
('string/en/mission/mission_deliver_rebel_easy.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 100, 'm13r', 'I''ll send the holos right away. Do you know what format they''re in? Never mind, my wizardry is mighty.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 101, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 102, 'm13s', 'How many more atrocities will the Empire commit before they''re finally defeated? Not too many, if we all work together.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 103, 'm13p', 'I thought these practices were just a rumor. We must expose the Empire''s cruelty to the entire galaxy.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 104, 'm13t', 'Alien Autopsies'),
('string/en/mission/mission_deliver_rebel_easy.stf', 105, 'm14d', 'Recently we''d discovered an Imperial spy in one of our local cells. Now we know that the Empire has learned of it. These encrypted instructions tell what to do with the spy. That cell is to disperse immediately. Deliver the disc to our contact as quickly as you can.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 108, 'm14r', 'We''ll follow these instructions. Long live the Republic!'),
('string/en/mission/mission_deliver_rebel_easy.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 110, 'm14s', 'We''re grateful you delivered that information when you did. Any later would have been too late.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 111, 'm14p', 'It''s getting harder to spot these Imperial moles. We must keep on our guard.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 112, 'm14t', 'Cell Dispersal'),
('string/en/mission/mission_deliver_rebel_easy.stf', 113, 'm15d', 'We believe we know the identity of the Vibrodagger Killer. So far the Empire has turned a blind eye to these gruesome murders, because all the victims have been Alliance sympathizers. We''ll have to take matters into our own hands. Deliver this holograph and dossier of the murderer to our HoloNet slicer, so we can get this information out to our field agents.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 116, 'm15r', 'I can''t believe it. This fiend will finally be brought to justice.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 117, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 118, 'm15s', 'Thanks to your assistance, we''ll be able to put a stop to these murders by any means necessary.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 119, 'm15p', 'We never take pride in taking a life, but sometimes it must be done.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 120, 'm15t', 'By Any Means Necessary'),
('string/en/mission/mission_deliver_rebel_easy.stf', 121, 'm16d', 'Some alien refugees we''ve been harboring are in desperate need of medical supplies. Please deliver this supply request to one of our contacts so we can get the supplies shipped immediately.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 124, 'm16r', 'We''re getting awfully short on medical supplies. It may be time for another raid.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 126, 'm16s', 'I''m sure those aliens are grateful for the help you''ve given them -- as are we!'),
('string/en/mission/mission_deliver_rebel_easy.stf', 127, 'm16p', 'The abominable treatment of nonhumans is only one reason why the Empire must fall.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 128, 'm16t', 'Emergency Medical Supplies'),
('string/en/mission/mission_deliver_rebel_easy.stf', 129, 'm17d', 'One of our contacts fears for the lives of his family. He wants them transported to a safe haven. Could you deliver this encrypted letter of credit to the transport captain who''s agreed to take the family to safety? The Alliance will make sure the captain gets paid in full.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 132, 'm17r', 'I''ve dealt with the Alliance before. They''re as good as their word.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 134, 'm17s', 'It''s a tragedy how many people are forced to go on the run. Thank you for helping them.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 135, 'm17p', 'The Empire''s tactic of attacking our families is all too common, I fear.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 136, 'm17t', 'A Safe Haven'),
('string/en/mission/mission_deliver_rebel_easy.stf', 137, 'm18d', 'One of our contacts may be a double agent. We must verify it. We need someone to deliver this encrypted message that bears a secret Imperial symbol. Refusal of the message means the contact recognized the symbol and is working for the Empire. Acceptance means the agent is clean. We''ll finally settle this matter.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 140, 'm18r', 'These are my new instructions? I''ll read them at once. May the Force be with you.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 141, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 142, 'm18s', 'That''s a relief! I wish we could all trust each other implicitly, but we must be careful.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 143, 'm18p', 'We were certain this contact was trustworthy. I hope this disc is accepted!'),
('string/en/mission/mission_deliver_rebel_easy.stf', 144, 'm18t', 'A Test of Loyalty'),
('string/en/mission/mission_deliver_rebel_easy.stf', 145, 'm19d', 'A new field agent requires a Pocket Scrambler to insure proper encryption of transmissions. Could you deliver this device so the agent can begin filing regular reports? These devices are expensive, so be careful.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 146, 'm19l', 'Small gadget'),
('string/en/mission/mission_deliver_rebel_easy.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 148, 'm19r', 'Are there instructions for this thing? Thanks.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 149, 'm19f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_easy.stf', 150, 'm19s', 'The device is in working order, and we''ve received the agent''s first report. Good job.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 151, 'm19p', 'We can never be too careful with our transmissions.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 152, 'm19t', 'Pocket Scrambler'),
('string/en/mission/mission_deliver_rebel_easy.stf', 153, 'm20d', 'One of our cells believes their conversations are being recorded. We need this Silence Bubble Generator delivered to their representative for use in their future meetings. Mention that the device only covers an area 2 meters in diameter, so they''ll have to sit close together.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 154, 'm20l', '1 kg gadget'),
('string/en/mission/mission_deliver_rebel_easy.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 156, 'm20r', 'Two meters? Well, we''ll all get to know each other a lot better, I guess. Thanks.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 157, 'm20f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_easy.stf', 158, 'm20s', 'The cell was glad to receive the device. You can''t be too careful these days.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 159, 'm20p', 'This is an expensive gadget. Better safe than sorry, I suppose.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 160, 'm20t', 'A Bubble of Silence'),
('string/en/mission/mission_deliver_rebel_easy.stf', 161, 'm21d', 'One of our contacts is using the neighborhood children to spy on the Empire''s agents. Whereas we approve of this tactic for simple surveillance, we understand that this individual is encouraging the children to sneak into Imperial garrisons and offices. We feel this is putting the children at too great a risk. Please deliver this encrypted message that gives them guidelines as to what the Alliance considers acceptable risks.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 164, 'm21r', 'I hope I haven''t displeased my friends. Of course I''ll comply.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 165, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 166, 'm21s', 'Thank you. We must not put our children at risk.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 167, 'm21p', 'We must make sure we never sink to the Empire''s level of callous tactics.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 168, 'm21t', 'Spy Kids'),
('string/en/mission/mission_deliver_rebel_easy.stf', 169, 'm22d', 'We''ve had numerous requests, from parents especially, for holograms showing what the Alliance stands for and how we operate. They''re trying to counter COMPNOR''s propaganda. Could you deliver this encrypted hologram to our HoloNet slicers so we can make it available to anyone that wants to access it? We need to get the good word out there.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 172, 'm22r', 'If I had a credit for every person that has requested this sort of holo, I''d be one rich slicer. -- Whoa, I almost said ''one slice richer.'' Funny, huh?'),
('string/en/mission/mission_deliver_rebel_easy.stf', 173, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 174, 'm22s', 'It''s important that people know what we stand for. Thanks for making the delivery.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 175, 'm22p', 'We must discredit COMPNOR''s propaganda.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 176, 'm22t', 'Get the Good Word Out'),
('string/en/mission/mission_deliver_rebel_easy.stf', 177, 'm23d', 'One of our agents has managed to acquire a hologram of the destruction of Alderaan. It''s heart-wrenching. Could you deliver a copy of it to our HoloNet slicer so we can make it available to every citizen in the Empire? The truth will be out there.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 180, 'm23r', 'I saw a very bad copy of this. Lots of artifacting and low signal-to-noise. Hope this one''s better. I''ll send it.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 182, 'm23s', 'That was the single greatest atrocity ever committed. We must never forget.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 183, 'm23p', 'Billions have been murdered by the Empire. Everyone will know the truth.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 184, 'm23t', 'Alderaan''s Destruction'),
('string/en/mission/mission_deliver_rebel_easy.stf', 185, 'm24d', 'There are rumors that a Jedi played a part in the destruction of the Death Star. We want to spread that rumor and encourage the belief that the Jedi have returned. Could you deliver this message to our HoloNet slicer so we can transmit it to all our cells?'),
('string/en/mission/mission_deliver_rebel_easy.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 188, 'm24r', 'You bet I''ll spread the word! The Force is with the Republic! The Jedi have returned! The Empire will fall! Hee-yaah!'),
('string/en/mission/mission_deliver_rebel_easy.stf', 189, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy.stf', 190, 'm24s', 'Well done, friend. It seems appropriate to add this: May the Force be with you!'),
('string/en/mission/mission_deliver_rebel_easy.stf', 191, 'm24p', 'If the Jedi have returned, the Republic will be back soon too.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 192, 'm24t', 'The Jedi Return'),
('string/en/mission/mission_deliver_rebel_easy.stf', 193, 'm25d', 'Smugglers help us by delivering much needed supplies past Imperial blockades. Could you deliver this encrypted disc to our HoloNet slicer? It lists approved "procurement specialists" -- those we''ve dealt with on multiple occasions. Tell our cells to choose from this list when deciding on a smuggler.  Good luck.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_rebel_easy.stf', 196, 'm25r', 'An official list of reliable smugglers? That''s so weird. What''s next, an Alliance Seal of Approval?'),
('string/en/mission/mission_deliver_rebel_easy.stf', 197, 'm25f', 'mission\\mission_datadisk.iff');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_rebel_easy.stf', 198, 'm25s', 'Very few smugglers can be trusted -- probably even fewer than we think. There may be no honor among thieves, but unfortunately we have to deal with them.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 199, 'm25p', 'If our cells must choose someone not on this list, tell them to check with Alliance Intelligence before making any commitments.'),
('string/en/mission/mission_deliver_rebel_easy.stf', 200, 'm25t', 'List of Smugglers'),
('string/en/mission/mission_deliver_rebel_easy.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 1, 'm1d', 'A Senator aiding our cause has angered Imperial Intelligence. His family has been targeted for termination. Pick up an encrypted datadisc from one of our slicers. It contains instructions for the Senator and his family. Deliver this disc to a member of the Senator''s staff immediately. We hope we''re not too late to save this patriot''s family.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 5, 'm1r', 'The Senator thanks you and will follow these instructions immediately. Thank you.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 6, 'm1p', 'Here you go, friend. I hope it''s not too late to save the Senator''s family.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 7, 'm1t', 'Rescue a Senatorial Family'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 8, 'm1s', 'Well done, citizen. We will not stand by and watch our patriots executed.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 9, 'm2d', 'One of our strike teams is hitting an Imperial depot in the Outer Rim. We want Imperial Intelligence to suspect we''re hitting a different target. We need a trusted agent to pick up falsified Alliance communiques and deliver them to our HoloNet slicer. We''ll make sure Imperial agents intercept them. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 12, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 13, 'm2r', 'I''m on it. I love fooling those Imperial idiots. Don''t you? Haha!'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 14, 'm2p', 'Here are the communiques. Remember you can rarely use the same trick twice against the Empire.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 15, 'm2t', 'Help Fool the Empire'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 16, 'm2s', 'Good work. It''s the efforts of agents like you that will insure the Empire''s defeat.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 17, 'm3d', 'Although a terrible tragedy, the destruction of Alderaan has boosted our ranks. We need someone to pick up a datadisc and deliver it to our processing officer. It contains thousands of enlistees, many of them skilled pilots. This new influx of talent may be what the Alliance needs to turn the tide of battle against the Empire. Will you help? '),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 21, 'm3r', 'Thanks for the delivery. How typical of the Empire not to understand that fear can easily become hate. We shall triumph.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 22, 'm3p', 'The Princess said it best: "The more the Empire tightens its grip, the more star systems will slip through its fingers."'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 23, 'm3t', 'Boost the Alliance''s Ranks'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 24, 'm3s', 'Those extra recruits are much needed. Thanks for your efforts. The Alliance will reward you.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 25, 'm4d', 'We must constantly keep our cells supplied and their agents equipped. We need couriers to pick up supply requests and deliver them to our requisitions officer. These couriers will make sure our brave freedom fighters have what they need to fight the Empire. Will you assist in this important task?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 29, 'm4r', 'Thanks. Fortunately some "procurement specialists" just made it past the blockades, or we might have been in supply trouble.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 30, 'm4p', 'We''re glad to see you. Supplies are running pretty seriously low around here. Please hurry!'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 31, 'm4t', 'Supply Requests'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 32, 'm4s', 'Keeping the Alliance running is an endless task. We appreciate your efforts.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 33, 'm5d', 'Our Incom engineers have provided us with the latest X-wing flight simulator. This will be a great training aid for our new pilots. We need you to pick up a copy of the simulator and deliver it to one of our training officers. Make sure they report bugs to High Command. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 37, 'm5r', 'I hear these are modeled on the TIE flight sims. Our pilots will benefit greatly. Thanks.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 38, 'm5p', 'Ever wanted to fly an X-wing? I think every Alliance member does. Take care of this flight sim.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 39, 'm5t', 'Help train better pilots'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 40, 'm5s', 'All clear, citizen. Good work. The Alliance is grateful.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 41, 'm6d', 'Some of our agents have attempted to enlist with the Empire to spy for the Alliance. We believe Imperial Intelligence has identified a large number of these agents. We need someone to pick up encrypted orders from High Command and deliver them to our local cell contact. They tell local agents how to avoid detection.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 45, 'm6r', 'I''ll get these instructions out to our agents immediately.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 46, 'm6p', 'The orders are on this datadisc. One thing I will say for Imperial Intelligence -- they''re very thorough.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 47, 'm6t', 'Save Alliance Agents'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 48, 'm6s', 'Your efforts will likely save many good agents, friend. Well done!'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 49, 'm7d', 'Ever since the destruction of the Death Star, the number of enlistees has risen dramatically. We suspect that some of these individuals may be double agents working for the Empire. Can you pick up an encrypted roster of suspicious enlistees and deliver them to our High Command contact?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 53, 'm7r', 'Sometimes these double agents are hard to spot. We''ll do our best. Thanks for the information.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 54, 'm7p', 'Here''s the roster. But remember all the times when Imperial double agents denounced the Empire and joined our cause.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 55, 'm7t', 'Stop the Infiltrating Spies'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 56, 'm7s', 'Mission accomplished, for the moment. We must help the Alliance remain free of Imperial spies.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 57, 'm8d', 'Our slicers intercepted a secret Imperial communique revealing that the Empire has dossiers of all the surviving Battle of Yavin pilots. They''ve put a high priority on having these individuals arrested. Mentioned in the communique were Commanders Solo and Skywalker. Someone must pick up this communique and deliver it to our High Command contact. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 61, 'm8r', 'Thanks, citizen. We''ll alert these heroes as soon as possible.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 62, 'm8p', 'Here you go. There''s some juicy stuff in that communique.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 63, 'm8t', 'Help Protect the Heroes of Yavin'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 64, 'm8s', 'Our thanks, citizen. The security of the Heroes of Yavin is one of our top priorities.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 65, 'm9d', 'We''ve discovered a flaw in the design of older stormtrooper helmet comlinks. We need a trusted agent to pick up our technical analysis and deliver it to a local cell contact. We can use this flaw to intercept squad communications. This information will mostly benefit our cells on remote outposts. Think you can handle this mission? '),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 68, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 69, 'm9r', 'This should come in handy. I always wondered what stormtroopers chatted about when they were just standing around.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 70, 'm9p', 'Here''s the analysis. We should act quickly, because we don''t know how long this flaw will go unnoticed by the Empire.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 71, 'm9t', 'Eavesdrop on Stormtroopers'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 72, 'm9s', 'Job well done, citizen. The Alliance is glad to have trusted agents like you.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 73, 'm10d', 'Our slicers'' efforts to send bogus orders to Imperial garrisons has been very effective. Too effective, in fact. The Imperials have now taken to hand-delivering their orders, which leaves our slicers vulnerable to Imperial Intelligence. We need someone to pick up a new set of encryption codes and deliver them to our local slicers. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 77, 'm10r', 'Really? I gotta stop? Aww, just when I was having such fun. Okay, I''ll ask the gang to throttle back, and we''ll work with these new codes.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 78, 'm10p', 'Here are the new codes. They should help protect our data slicers. They''re weird, but they''re good folks and we need them.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 79, 'm10t', 'Save the Data Slicers'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 80, 'm10s', 'That should keep Imperial Intelligence guessing for a bit longer. Those goons are certainly dedicated, I''ll give them that. Thanks for your help.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 81, 'm11d', 'The Empire plans on arresting many former Senators and their families. We need someone to pick up the list of possible targets and deliver them to one of our HoloNet slicers so we can warn these targets. The slicer is to provide a list of High Command contacts to anyone fleeing arrest. Can you help us?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 84, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 85, 'm11r', 'When I send this warning, the Imperial Analysis Bureau will be riding my tail in about ten seconds flat. You guys needs to move fast to save those -- who is it? Senators? Whoever.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 86, 'm11p', 'Here''s the list. Remember, the more powerful politicians we get on our side, the better off we''ll be.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 87, 'm11t', 'Save the Senators'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 88, 'm11s', 'Your efforts will save many lives, citizen. The Alliance is grateful.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 89, 'm12d', 'The New Order''s stance on alien species has given us an edge in recruiting these neglected citizens. Of special interest to High Command are the Duros. We need a courier to pick up encrypted orders and deliver them to our agent specializing in Alien Species Affairs. The agent is to travel to Duro and continue negotiating with the leaders there.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 93, 'm12r', 'I think the Duros are determined to remain neutral, but I''ll continue negotiating with them.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 94, 'm12p', 'Here are the orders. Many other alien species would follow the Duros'' example if they joined the Alliance.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 95, 'm12t', 'Help Rally the Aliens'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 96, 'm12s', 'The Alliance appreciates your efforts. With luck, disenfranchised species will boost our ranks and help us topple the Empire.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 97, 'm13d', 'One of our refueling stations in the Outer Rim has been compromised, and we believe that the Empire is using it as bait to capture Alliance transports. Pick up these encrypted orders and deliver them to our local cell leader. We must insure that every transport captain and pilot aiding the Alliance receives these orders.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 101, 'm13r', 'We''ll get this information out to our pilots at once. Thank you.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 102, 'm13p', 'Here you go, citizen. And cheer up. For every station that the Empire discovers, we have ten more they know nothing about.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 103, 'm13t', 'Save the Pilots'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 104, 'm13s', 'Good work, citizen. Our pilots are a precious resource, and we must do all we can to protect them.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 105, 'm14d', 'We have proof that an Imperial prison official at Kessel has been supplying glitterstim to smugglers and Black Sun. We need someone to pick up the encrypted evidence and deliver it to one of our couriers. We intend to present our "terms" to the Imperial official. He''ll either cooperate with us or we turn over our proof to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 109, 'm14r', 'Good old-fashioned blackmail, eh? Hey, if it''s effective --'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 110, 'm14p', 'Here''s the data. Remember, we do what we must to insure the fall of the Empire. In this case, it''ll be fun!'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 111, 'm14t', 'Blackmail a Kessel Official'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 112, 'm14s', 'Well done. Remember to keep this quiet. We don''t want word getting around to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 113, 'm15d', 'We''ve received a request from Commander Skywalker. He''d like us to get our hands on an Imperial Inquisitor. We need someone to pick up his encrypted orders and deliver them to our local cell commander. All commanders are to coordinate with High Command to help achieve this top-priority mission. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 117, 'm15r', 'With pleasure! I''ve been wanting to take down one of these mighty Inquisitors ever since I heard of them.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 118, 'm15p', 'The orders are on this datadisc. I imagine we can learn a great deal from an Inquisitor. Good luck.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 119, 'm15t', 'Nab an Imperial Inquisitor'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 120, 'm15s', 'That was well done. With any luck, we''ll be able to supply Commander Skywalker with an Inquisitor soon. I wonder what he has in mind?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 121, 'm16d', 'A shipment of Merr-Sonn IR-5 "Intimidator" blaster pistols has fallen into our hands. We need someone to pick up inventory discs and deliver them to our local cell commanders. They can request these weapons for upcoming missions, especially any dealing with smugglers and pirates -- those types are easily intimidated. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 125, 'm16r', 'I''ve seen those blasters. Effective weapons indeed. I''ll look through this inventory carefully.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 126, 'm16p', 'Here you go. And remind the commanders that these weapons not only look intimidating, they also pack quite a punch.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 127, 'm16t', 'Disperse Intimidators'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 128, 'm16s', 'Excellent, citizen. These weapons will help our undercover agents deal with those unpredictable smugglers.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 129, 'm17d', 'A generous sympathizer has donated several new MD-series medical droids. Could you pick up the specs for these droids and deliver them to our local cell commander? All requests for these droid must go through Winter, who will process them directly. Make sure the commanders make a strong case, or they may not get one.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 133, 'm17r', 'My people sure could use one of those droids. I''ll make a no-frills request at once. I hear Winter is fond of brevity. '),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 134, 'm17p', 'Make sure the commander gets this. These donations keep the Alliance strong.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 135, 'm17t', 'Medical Droids for Everybody'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 136, 'm17s', 'Thanks for your help. The Alliance could use more reliable couriers like yourself.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 137, 'm18d', 'We found some old Trade Federation droidekas. These might be useful on certain missions or as security droids on some of our bases. Could you pick up this encrypted message and deliver it to our contact at High Command? We need instructions on how to proceed. Winter will hold these units until she receives those instructions.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 141, 'm18r', 'Weren''t those things awfully unreliable? I always heard that''s why the Trade Federation stopped using them. Well, I''ll pass this along.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 142, 'm18p', 'Here you go. Inform High Command that the droidekas seem to be in perfect condition. I don''t believe they were ever activated.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 143, 'm18t', 'A Blast From the Past'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 144, 'm18s', 'We appreciate your help, citizen. Meanwhile, we''re looking into the source of those perfectly preserved droidekas. Could be more where those came from.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 145, 'm19d', 'Procurement and Supply recently sent us a message asking for further instructions on the matter of some droidekas. I need you to pick up High Command''s response and deliver it to our P&S contacts so they can forward it to Winter. Do this quickly and we''ll reward you accordingly.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 149, 'm19r', 'Thanks, citizen. We''ll see what the bosses have to say, I suppose.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 150, 'm19p', 'Here you are. Any tool is only as effective as our ability to control and use it properly.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 151, 'm19t', 'Dealing With Obsolete Droids'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 152, 'm19s', 'That was a prompt delivery, citizen. Your fee has been deposited.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 153, 'm20d', 'A shipment of laser cutters must get to a secret facility in the Outer Rim. I need you to pick up encrypted orders and deliver them to one of our transport pilots. The pilot must report to High Command before leaving the local system. The location of the laser cutters as well as the coordinates of the secret facility will be revealed at that time.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 157, 'm20r', 'Well, the Empire hasn''t found us yet. So I guess all these hoops they make us jump through for secrecy''s sake are worth it.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 158, 'm20p', 'Here are the orders. We realize it''s difficult transporting all this equipment while maintaining secrecy.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 159, 'm20t', 'Help Carve a New Rebel Base'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 160, 'm20s', 'Good job, citizen. This mission was of the utmost secrecy. Your silence will save many lives.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 161, 'm21d', 'We''ve learned that a Moff is spearheading an attempt to assassinate the Emperor. Pick up this encrypted message and deliver it to one of the Moff''s agents. It informs the Moff that the Alliance will assist in whatever way it can and gives security codes if the Moff wishes to contact High Command. Can you help us?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 165, 'm21r', 'I''ll see to it that the Moff receives this. '),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 166, 'm21p', 'Moffs can strike at the heart of the Imperial Machine. We should never waste an opportunity like this. Be careful delivering this disc.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 167, 'm21t', 'Aid a Plot Against the Emperor'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 168, 'm21s', 'Well done, citizen. If this Moff''s plan succeeds, this war will be over and the galaxy will be free again.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 169, 'm22d', 'We believe that the Empire is preparing to strike Mon Calamari. Please pick up these intercepted transmissions and deliver them to our Mon Calamari contact who will have them sent to Admiral Ackbar immediately. If we act fast, we can save millions of Mon Calamari lives. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 173, 'm22r', 'May the Force be with us! I''ll leave at once!'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 174, 'm22p', 'The Mon Calamari are vital to the success of the Alliance. We must save them!'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 175, 'm22t', 'Save the Mon Calamari'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 176, 'm22s', 'We can only hope that we were fast enough. Thank you for your efforts, agent.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 177, 'm23d', 'Imperial Intelligence has instructed their agents to travel to the Circarpous system. We don''t know if they''ve learned of our secret dealings with Circarpousian financiers. We need you to pick up a message and deliver it to one of Princess Leia''s aides. We hope this doesn''t jeopardize her plans to meet with the Circarpousians.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 181, 'm23r', 'The Princess will want to go anyway, but I''ll warn her. She''s stubborn, you know.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 182, 'm23p', 'It seems that the Empire is always one step ahead of us. This must change.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 183, 'm23t', 'Warn the Princess'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 184, 'm23s', 'Excellent work, citizen. I hope the Princess takes this warning to heart. Sometimes she''s too brave for her own good.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 185, 'm24d', 'Our agents have discovered that four Imperial Star Destroyers will be in orbital dock at the same time. We intend to strike the dock and destroy the Imperial ships. Could you pick up an encrypted datadisc and deliver it to the strike team commander? It will reveal the location of the dock and list the Alliance pilots that will participate in the mission.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 188, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 189, 'm24r', 'If this strike succeeds, it would be a great victory for the Alliance.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 190, 'm24p', 'Deliver this fast. We''ll destroy these capital ships faster than the Empire can build them.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 191, 'm24t', 'Four Star Destroyers at Once'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 192, 'm24s', 'Well done, citizen. Your service to the Alliance is being noted.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 193, 'm25d', 'One of our colonies has been discovered by Imperial Intelligence. Many of our leaders'' families are on this colony. We need you to pick up an evacuation order and deliver it to one of our pilots familiar with the colony so we can begin the evacuation. We dare not communicate via the HoloNet for fear of escalating the Imperial attack. Please hurry!'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 197, 'm25r', 'We''ll have those families off that colony in no time. Never fear.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 198, 'm25p', 'Be quick with this delivery. Until the Empire is toppled, we must remain on the move.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 199, 'm25t', 'Help Evacuate a Colony'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 200, 'm25s', 'Good work. Let''s hope we acted in time to save all those people.'),
('string/en/mission/mission_deliver_rebel_easy_non_persistent_from_npc.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_rebel_hard.stf', 1, 'm1d', 'We managed to infiltrate an officer into the top ranks of the ISB. He''s helped us save hundreds of lives. But he''s been discovered, and we must warn him to escape. Can you deliver these encrypted orders to one of our field agents? The agent is to get arrested so that they can warn our infiltrator. Please hurry!'),
('string/en/mission/mission_deliver_rebel_hard.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 3, 'm1o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 4, 'm1r', 'So now I''ve got to get arrested, huh? All right, this officer has served the Alliance faithfully. I won''t let him down. I guess I''ll go assault a stormtrooper.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 6, 'm1s', 'Our officer got the warning in time, thanks to you. Next, we have to free that field agent who slugged some stormtrooper. We may contact you again soon.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 7, 'm1p', 'As a top officer in the ISB, our covert infiltrator will review the record of the arrest personally. When he sees the name of the individual arrested, he''ll recognize it as a code alerting him to flee. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 8, 'm1t', 'Agent in Peril'),
('string/en/mission/mission_deliver_rebel_hard.stf', 9, 'm2d', 'A senator aiding our cause has angered Imperial Intelligence.  His family has been targeted for termination. Deliver this encrypted warning immediately to a member of the Senator''s staff. We hope we''re not too late to save this patriot''s family. We''re counting on you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 11, 'm2o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 12, 'm2r', 'The Senator''s family will go into hiding. Thank you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 14, 'm2s', 'The warning came just in time for them to get out. Well done.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 15, 'm2p', 'We will not stand by and watch our patriots'' families destroyed.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 16, 'm2t', 'Targeted for Termination'),
('string/en/mission/mission_deliver_rebel_hard.stf', 17, 'm3d', 'We need these new designs for climate control units delivered to one of our agents for transport to a hidden base in the Outer Rim. We dare not transmit these plans via the HoloNet for fear of Imperial Intelligence intercepting them. We must keep the location of our base a closely guarded secret. You''ve proven yourself to be a trustworthy agent. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 19, 'm3o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 20, 'm3r', 'I''ll see these are delivered safely. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 22, 'm3s', 'Our agent is on the way with those plans. Thank you!'),
('string/en/mission/mission_deliver_rebel_hard.stf', 23, 'm3p', 'The Imperial fleet is scouring the stars for us. We must be extremely cautious.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 24, 'm3t', 'A Secret Destination'),
('string/en/mission/mission_deliver_rebel_hard.stf', 25, 'm4d', 'We believe that the Empire is preparing to strike Mon Calamari. Deliver these intercepted transmissions to our Mon Calamari contact who will have them sent to Admiral Ackbar immediately. If we act fast, we can save millions of Mon Calamari lives. We''re relying on you. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 27, 'm4o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 28, 'm4r', 'May the Force be with us. I''ll leave at once.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 30, 'm4s', 'Only a few couriers could be trusted with such an important mission. We''re glad we chose you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 31, 'm4p', 'The Mon Calamari are vital to the success of the Alliance. Help save them!'),
('string/en/mission/mission_deliver_rebel_hard.stf', 32, 'm4t', 'Intercepted Transmissions'),
('string/en/mission/mission_deliver_rebel_hard.stf', 33, 'm5d', 'The Empire has identified several Viceprexes in the Corporate Sector Authority who have been aiding the Alliance. They will no doubt attempt to remove these individuals one way or another. Can you send this warning to our contact within the CSA so they can warn the Viceprexes? These people are very important to our cause.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 35, 'm5o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 36, 'm5r', 'We suspected those Imperial creeps were closing in on us. Thanks for the warning.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 37, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 38, 'm5s', 'A complete success, thanks to you!'),
('string/en/mission/mission_deliver_rebel_hard.stf', 39, 'm5p', 'The Alliance is in constant need of supplies and military hardware. The CSA can provide us with that.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 40, 'm5t', 'Keep Our Allies Safe'),
('string/en/mission/mission_deliver_rebel_hard.stf', 41, 'm6d', 'We''ve intercepted a transmission from Imperial Intelligence putting their Imperial Inquisitors on alert for Jedi. We need someone to deliver this alert to one of Commander Skywalker''s scouts so he can be warned of the danger. We trust you to do this.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 43, 'm6o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 44, 'm6r', 'I''ll see that Commander Skywalker gets this as soon as possible. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 45, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 46, 'm6s', 'We can''t afford to lose such a great hero as Commander Skywalker. He inspires our troops and is a symbolic reminder of the Jedi of the Old Republic. He''ll be on the alert for those Inquisitors now. Thanks for helping.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 47, 'm6p', 'Commander Skywalker is living proof that the Jedi''s fire has not gone out of the universe. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 48, 'm6t', 'Jedi in Peril'),
('string/en/mission/mission_deliver_rebel_hard.stf', 49, 'm7d', 'We suspect that Imperial agents plan on attending demonstrations on the Core worlds protesting the Empire''s use of the Death Star. These agents will try to release a deadly airborne virus during the protests. Our scientists have obtained a sample of the virus and have developed an effective retrovirus. This sample of this retrovirus must be delivered to our agent, who can distribute it to all our field medics for duplication. You must be quick. It may already be too late.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 50, 'm7l', 'Small medical container'),
('string/en/mission/mission_deliver_rebel_hard.stf', 51, 'm7o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 52, 'm7r', 'I leave at once. I hope I''m not too late.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 53, 'm7f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_hard.stf', 54, 'm7s', 'Thanks to your timely action, untold numbers of lives have been saved. You have our gratitude.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 55, 'm7p', 'The Empire will stop at nothing to destroy democracy. Those fiends!'),
('string/en/mission/mission_deliver_rebel_hard.stf', 56, 'm7t', 'Killer Virus'),
('string/en/mission/mission_deliver_rebel_hard.stf', 57, 'm8d', 'Imperial Intelligence has instructed their agents to travel to the Circarpous system. We don''t know if they have learned of our secret dealings with the Circarpousian financiers. This message must be delivered to one of Princess Leia''s aides. This may jeopardize her plans to meet with the Circarpousians. Can we count on you, agent?  '),
('string/en/mission/mission_deliver_rebel_hard.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 59, 'm8o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 60, 'm8r', 'The Princess will want to go anyway, but I will warn her. She''s a stubborn individual, you know.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 61, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 62, 'm8s', 'At least the Princess will be prepared for possible Imperial interference. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 63, 'm8p', 'It seems that the Empire is always one step ahead of us. This must change.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 64, 'm8t', 'Warn a Princess'),
('string/en/mission/mission_deliver_rebel_hard.stf', 65, 'm9d', 'Even though we managed to destroy the Empire''s Dark Trooper facility, we have reason to believe that some of these mechanized stormtroopers survived. We even suspect that an improved model has been constructed. This message must be delivered to our one of our top HoloNet slicers, so we can put all our troops on alert. Will you help save the lives of Alliance fighters? '),
('string/en/mission/mission_deliver_rebel_hard.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 67, 'm9o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 68, 'm9r', 'A new Dark Trooper? The old ones were bad enough.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 70, 'm9s', 'Mechanized efficiency is no match for a dedicated freedom fighter. Forewarned is forearmed, thanks in part to you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 71, 'm9p', 'Included in this disc are technical specs for the original Dark Troopers, which might help our men fight these specialized stormtroopers.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 72, 'm9t', 'Dark Trooper Specs'),
('string/en/mission/mission_deliver_rebel_hard.stf', 73, 'm10d', 'We''ve been contacted by an Imperial agent who wishes to defect to our side. Apparently, he''d been instructed to infiltrate Jabba''s Palace on Tatooine and realized that his life was considered expendable by the Empire. He could provide us with valuable information regarding Imperial activities and intelligence missions. Could you deliver this message to one of our pilots? Please hurry. The Alliance is counting on you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 75, 'm10o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 76, 'm10r', 'He would be helpful to our cause. I''ll pick him up right away.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 78, 'm10s', 'Good work. This agent will be of immense value to the Alliance.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 79, 'm10p', 'The agent is to be picked up at these coordinates immediately. He believes the Empire is closing in on him.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 80, 'm10t', 'Imperial Defection'),
('string/en/mission/mission_deliver_rebel_hard.stf', 81, 'm11d', 'Our agents have discovered that four Imperial Star Destroyers will be in space dock at the same time. We''ve decided to strike the dock and destroy the Imperial ships. Could you deliver this encrypted datadisc to the strike team commander? It will reveal the location of the dock and list the Alliance pilots that will participate in the mission. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 83, 'm11o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 84, 'm11r', 'If we succeed, this will be a great victory for the Alliance.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 85, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 86, 'm11s', 'Your part of this job is finished. Now it''s up to the strike team.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 87, 'm11p', 'We''ll destroy these ships faster than the Empire can build them.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 88, 'm11t', 'Vulnerable Destroyers'),
('string/en/mission/mission_deliver_rebel_hard.stf', 89, 'm12d', 'We''ve intercepted some Imperial communiques that might prove the Empire was behind the recent attacks on the Bounty Hunters'' Guild. It would benefit us if the Guild learns of this. These communiques must be delivered to our contact within the Guild. We hope it will encourage them to accept fewer deathmarks against Alliance allies. These are shady figures, though. Are you up to the challenge?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 91, 'm12o', 'Alliance Intelligence');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_rebel_hard.stf', 92, 'm12r', 'I suspect Black Sun was behind the attacks. We''ll see what these transmissions reveal.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 94, 'm12s', 'We hope the bounty hunters will inerpret those transmissions the same way we did. Thanks.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 95, 'm12p', 'Bounty Hunters may be ruthless, but they also follow a code. Let''s take advantage of that.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 96, 'm12t', 'Bounty Hunter Allies'),
('string/en/mission/mission_deliver_rebel_hard.stf', 97, 'm13d', 'Our top Incom engineer has just completed a design for a new starfighter code named the "A-wing." We need this design delivered to one of our contacts, who will hand-deliver it to our secret manufacturing plant. Can we count on you for this crucial mission?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 99, 'm13o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 100, 'm13r', 'These schematics are safe with me. I''ll get them to their destination.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 101, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 102, 'm13s', 'Let''s hope these ships are everything they''re supposed to be. We need to begin work on the prototype immediately.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 103, 'm13p', 'This starfighter may tip the scales for us in combat. It''s supposed to be more than a match for the TIE fighter''s speed. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 104, 'm13t', 'New Starfighter Design'),
('string/en/mission/mission_deliver_rebel_hard.stf', 105, 'm14d', 'One of our colonies has been discovered by Imperial Intelligence. Many of our leaders'' families are on this colony. This evacuation order must be hand-delivered to one of our pilots familiar with that colony. We dare not attempt to communicate via the HoloNet for fear of escalating the Imperial attack. You must hurry. The faith of the Alliance goes with you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 107, 'm14o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 108, 'm14r', 'We''ll have those families off that colony in no time.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 110, 'm14s', 'The evacuation was a complete success, thanks in part to you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 111, 'm14p', 'Until the Empire falls, we must remain on the move.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 112, 'm14t', 'Evacuation Orders'),
('string/en/mission/mission_deliver_rebel_hard.stf', 113, 'm15d', 'General Rieekan wants some speeder modifications delivered to our Incom engineers. I believe he wants our speeders tested for peak performance under extreme weather conditions. This encrypted datadisc contains his orders and testing specifications. Can you deliver them to the engineer team immediately? '),
('string/en/mission/mission_deliver_rebel_hard.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 115, 'm15o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 116, 'm15r', 'Modifications to a speeder, eh? We''ll see what we can do.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 117, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 118, 'm15s', 'These new modifications are classified. Please don''t speak of them to anyone.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 119, 'm15p', 'Extreme weather conditions! Working for the Alliance certainly builds character.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 120, 'm15t', 'Speeder Modifications'),
('string/en/mission/mission_deliver_rebel_hard.stf', 121, 'm16d', 'We''ve received a very interesting proposition from someone claiming to be the leader of the Black Sun syndicate. This mysterious figure has offered the aid of their organization in exchange for any information we have about Darth Vader and the movements of his fleet. Can you deliver the details of this proposition to our intelligence officer, who will look into this offer more thoroughly?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 123, 'm16o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 124, 'm16r', 'We''ll check with the Black Sun Vigos we''ve worked with and verify this claim.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 126, 'm16s', 'You have proved a most trustworthy courier. Let''s hope the mysterious Black Sun leader proves half as trustworthy.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 127, 'm16p', 'It would greatly benefit the Alliance if Darth Vader were removed from the picture -- though I''m not sure even Black Sun could take him.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 128, 'm16t', 'Black Sun Offer'),
('string/en/mission/mission_deliver_rebel_hard.stf', 129, 'm17d', 'We''ve just received Winter''s latest intelligence in preparation for our next procurement raid. We need her report delivered to the strike team commander, so we can prepare for a raid on an Imperial munitions depot. Of especial interest to General Rieekan are the portable laser cannons held there. I hope we can count on you. Good luck.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 131, 'm17o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 132, 'm17r', 'I swear I''m beginning to really enjoy these raids.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 134, 'm17s', 'We hope our strike team will as successful at their mission as you were at yours.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 135, 'm17p', 'If the Empire goes to all that trouble to build weapons, the least we can do is steal them.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 136, 'm17t', 'Weapon Depot Raid'),
('string/en/mission/mission_deliver_rebel_hard.stf', 137, 'm18d', 'Mon Mothma would like us to search for Jedi Knights who, like Obi-Wan Kenobi, survived the Clone Wars. These encrypted instructions tell our surveillance post officer to report any findings directly to Mon Mothma. This is a matter of great interest to High Command. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 139, 'm18o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 140, 'm18r', 'Finding more Jedi would certainly be something. You''d think if they were around, they''d have come out of hiding by now.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 141, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 142, 'm18s', 'More Jedi would be most welcome in our struggle against the Empire. I hope we find some.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 143, 'm18p', 'Commander Skywalker has told us all he knew concerning Obi-Wan Kenobi. But I doubt we''ll find other Jedi. Kenobi was probably unique.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 144, 'm18t', 'Jedi Wanted'),
('string/en/mission/mission_deliver_rebel_hard.stf', 145, 'm19d', 'As difficult as it is, we need to quarantine the Graveyard of Alderaan. Imperial agents lie in wait for ships performing a Returning ritual, board the ships, and arrest the passengers and crew. We all still grieve for the loss of that bright world and its billions, but this is simply too risky for the Alliance. We need these orders delivered to our sector commander. Can you do this?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 147, 'm19o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 148, 'm19r', 'I''ll see to it that these orders are obeyed. The Empire has much to answer for.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 149, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 150, 'm19s', 'When this conflict has ended, we''ll have time to grieve properly. For now, the struggle continues.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 151, 'm19p', 'I''m very sorry to say that until further notice, no Alliance member is to travel to the remains of the Alderaan system.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 152, 'm19t', 'Remembering Alderaan'),
('string/en/mission/mission_deliver_rebel_hard.stf', 153, 'm20d', 'Through our spies in the Imperial Navy, we''ve managed to plant seeds of discord among Darth Vader''s fleet commanders. Admiral Ozzel has taken the bait and believes Vader wishes to replace him with a junior officer. Rumor has it that the two rarely see eye-to-eye. We need instructions sent to our covert team''s contact to continue spreading these rumors. Are you the one for this mission?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 155, 'm20o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 156, 'm20r', 'This mission has been a pleasure. We''ll gladly keep it up.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 157, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 158, 'm20s', 'The more Admiral Ozzel clashes with Vader, the better off we''ll be. Vader probably will replace him -- not that we care.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 159, 'm20p', 'Fortunately for us, the Empire''s full of ambitious politicians eager to stab each other in the back.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 160, 'm20t', 'Sow Discord'),
('string/en/mission/mission_deliver_rebel_hard.stf', 161, 'm21d', 'A fragment of an Imperial communique mentioned the "Ison Corridor." We need these encrypted instructions delivered to Covert Operations. They are to investigate why the Empire is interested in this remote region of space. All findings should be hand-delivered by courier to General Rieekan''s command staff. This matter is of the highest importance. Good luck. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 163, 'm21o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 164, 'm21r', 'We''ll get right on it.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 165, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 166, 'm21s', 'Your reliability has been noticed by the Alliance. We''re most impressed with you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 167, 'm21p', 'Imperial Intelligence should never be underestimated.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 168, 'm21t', 'Surveillance Instructions'),
('string/en/mission/mission_deliver_rebel_hard.stf', 169, 'm22d', 'Surveillance reports have come in regarding the Empire''s interest in the Ison Corridor. We''ve investigated the matter closely. Our findings are contained on this encrypted datadisc. It must be hand-delivered to one of General Rieekan''s command staff. We think you''re the agent for this important mission. Do you accept?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 171, 'm22o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_hard.stf', 172, 'm22r', 'I''ll get this to the General at once.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 173, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 174, 'm22s', 'You have performed your task admirably. Payment has been deposited.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 175, 'm22p', 'I think the General will rest easier when he reviews our findings.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 176, 'm22t', 'Secret Reports'),
('string/en/mission/mission_deliver_rebel_hard.stf', 177, 'm23d', 'An Alliance officer wishes to attempt a rescue of his family. We have learned their location and wish a strike team assembled to undertake this mission. Please deliver this encrypted datadisc, which contains the location of the detention facility, to the commander we''ve chosen to lead this strike team. This matter is of the highest priority. We hope you accept. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 179, 'm23o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 180, 'm23r', 'This sounds like a trap, but I suppose we have to try to rescue the officer''s family.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 182, 'm23s', 'We suspect this may be a trap, so we''re insisting that the officer remain safely at our central command station. I hope we don''t wind up losing more people than we rescue. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 183, 'm23p', 'If the officer loses his family, we don''t know how he''ll react. We hope he''ll keep a cool head.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 184, 'm23t', 'Rescue a Family'),
('string/en/mission/mission_deliver_rebel_hard.stf', 185, 'm24d', 'My employer has acquired a rare bottle of Alderaanian brandy -- General Rieekan''s favorite drink. Could you deliver this bottle to one of the General''s aides? Tell the aide that Borsk Fey''lya sends it to the general with his compliments. '),
('string/en/mission/mission_deliver_rebel_hard.stf', 186, 'm24l', 'Bottle of brandy'),
('string/en/mission/mission_deliver_rebel_hard.stf', 187, 'm24o', 'Borsk Fey''lya'),
('string/en/mission/mission_deliver_rebel_hard.stf', 188, 'm24r', 'The general will be most appreciative. Thank you.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 189, 'm24f', 'filename_of_object'),
('string/en/mission/mission_deliver_rebel_hard.stf', 190, 'm24s', 'It is Minister Fey''lya''s hope that the gift to the general will serve as a bond between them and encourage closer ties in the future. Well done.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 191, 'm24p', 'Borsk Fey''lya never forgets a friend, citizen.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 192, 'm24t', 'A Gift of Brandy'),
('string/en/mission/mission_deliver_rebel_hard.stf', 193, 'm25d', 'We need to buy Commander Solo some time. These bounty hunters are getting more daring in their attempts to capture him. Apparently Solo offended a powerful Hutt on Tatooine. We need this offer delivered to our contact in the Bounty Hunters'' Guild to see if they''ll help negotiate a settlement between Solo and that Hutt. These sorts of missions are never easy. Can you handle it?'),
('string/en/mission/mission_deliver_rebel_hard.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard.stf', 195, 'm25o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_hard.stf', 196, 'm25r', 'I''ll deliver the message, but I doubt Jabba will negotiate. He wants Solo pretty bad.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 197, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard.stf', 198, 'm25s', 'You''ve done your part. Now let''s hope that Hutt is willing to listen to reason. The last thing we need is some bounty hunter jeopardizing the location of one of our bases.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 199, 'm25p', 'You''d think that after the Bounty Hunter Wars, the Guild would be eager to work with us.'),
('string/en/mission/mission_deliver_rebel_hard.stf', 200, 'm25t', 'Soothing a Hutt'),
('string/en/mission/mission_deliver_rebel_hard.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 1, 'm1d', 'A Senator aiding our cause has angered Imperial Intelligence. His family has been targeted for termination. Pick up an encrypted datadisc from one of our slicers. It contains instructions for the Senator and his family. Deliver this disc to a member of the Senator''s staff immediately. We hope we''re not too late to save this patriot''s family.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 5, 'm1r', 'The Senator thanks you and will follow these instructions immediately. Thank you.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 6, 'm1p', 'Here you go, friend. I hope it''s not too late to save the Senator''s family.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 7, 'm1t', 'Targeted for Termination'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 8, 'm1s', 'Well done, citizen. We will not stand by and watch our patriots executed.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 9, 'm2d', 'One of our strike teams is hitting an Imperial depot in the Outer Rim. We want Imperial Intelligence to suspect we''re hitting another target. We need a trusted agent to pick up falsified Alliance communiques and deliver them to our HoloNet slicer. We''ll make sure Imperial agents intercept them. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 12, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 13, 'm2r', 'I''m on it. I love fooling those Imperial idiots. Don''t you? Haha!'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 14, 'm2p', 'Here are the communiques. Remember, you can rarely use the same trick twice against the Empire.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 15, 'm2t', 'Help Fool the Empire'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 16, 'm2s', 'Good work, comrade. It''s the efforts of agents like you that will insure the Empire''s defeat. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 17, 'm3d', 'Although a terrible tragedy, the destruction of Alderaan has boosted our ranks. We need someone to pick up a datadisc and deliver it to our processing officer. It contains thousands of enlistees, many of them skilled pilots. This new influx of talent may be what the Alliance needs to turn the tide of battle against the Empire. Will you help? '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 21, 'm3r', 'Thanks for the delivery. How typical of the Empire to not understand that fear can become hate very easily.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 22, 'm3p', 'The Princess said it best: "The more the Empire tightens its grip, the more star systems will slip through its fingers."'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 23, 'm3t', 'Help Boost the Alliance''s Ranks'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 24, 'm3s', 'Those extra recruits are much needed. Thanks for your efforts. The Alliance will reward you.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 25, 'm4d', 'We must constantly keep our cells supplied and their agents equipped. We need couriers to pick up supply requests and deliver them to our requisitions officer. These couriers will make sure our brave freedom fighters have what they need to fight the Empire. Will you assist in this important task?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 29, 'm4r', 'Thanks, citizen. Fortunately we''ve attracted some more financial backers recently or else we might be in trouble.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 30, 'm4p', 'Keeping the Alliance running is an expensive task. We appreciate your efforts.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 31, 'm4t', 'Deliver Supply Requests'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 32, 'm4s', 'Your efforts will be rewarded, friend. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 33, 'm5d', 'Our Incom engineers have provided us with the latest X-wing flight simulator. This will be a great training aid for our new pilots. We need you to pick up this copy of the simulator and deliver it to one of our training officers. Make sure they report any bugs to High Command. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 37, 'm5r', 'I hear these are modeled on the TIE flight sims. Our pilots will benefit greatly. Thanks.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 38, 'm5p', 'Ever wanted to fly an X-wing? I think every Alliance member does. Take care of this flight sim.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 39, 'm5t', 'Help Train Better Pilots'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 40, 'm5s', 'All clear, citizen. Good work. The Alliance is grateful.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 41, 'm6d', 'Some of our agents have attempted to enlist with the Empire in order to spy for the Alliance. We believe Imperial Intelligence has identified a large number of these agents. We need someone to pick up encrypted orders from High Command and deliver them to our local cell contact. They instruct local agents how to avoid detection.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 45, 'm6r', 'I''ll get these instructions out to our agents immediately. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 46, 'm6p', 'The orders are on this datadisc. One thing I will say for Imperial Intelligence -- they''re very thorough.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 47, 'm6t', 'Save Alliance Agents'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 48, 'm6s', 'Your efforts will likely save many good beings, agent. Well done!'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 49, 'm7d', 'Ever since the destruction of the Death Star, the number of Alliance enlistees has risen dramatically. We suspect that some of them may be double agents working for the Empire. Can you pick up an encrypted roster of suspicious enlistees and deliver them to our High Command contact? We must help the Alliance remain free of Imperial spies.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 53, 'm7r', 'Sometimes these double agents are hard to spot. We''ll do our best. Thanks for the information.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 54, 'm7p', 'Here''s the roster. I should point out, though, that some Imperial double agents wind up denouncing the Empire and joining our cause.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 55, 'm7t', 'Stop the Infiltrating Spies'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 56, 'm7s', 'Mission accomplished, agent. We''re lucky to have you on our side.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 57, 'm8d', 'Our slicers intercepted a secret Imperial communique revealing that the Empire has dossiers of all the surviving Battle of Yavin pilots. They''ve put a high priority on having these individuals arrested. Mentioned in the communique were Commanders Solo and Skywalker. Someone must pick up this communique and deliver it to our High Command contact. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 61, 'm8r', 'Thanks, citizen. We''ll alert these heroes as soon as possible. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 62, 'm8p', 'Here you go, buddy. There''s some juicy stuff in that communique.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 63, 'm8t', 'Help Protect the Heroes of Yavin'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 64, 'm8s', 'Our thanks, citizen. The security of the Heroes of Yavin is one of our top priorities.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 65, 'm9d', 'We''ve discovered a flaw in the design of older stormtrooper helmet comlinks. We need a trusted agent to pick up our technical analysis and deliver it to a local cell contact. We can use this flaw to intercept squad communications. This information will mostly benefit our cells on remote outposts. Think you can handle this mission? '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 68, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 69, 'm9r', 'This should come in handy. I always wondered what stormtroopers chatted about when they were just standing around.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 70, 'm9p', 'Here''s the analysis. We should act quickly since we don''t know how long this flaw will go unnoticed by the Empire.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 71, 'm9t', 'Listen in on Stormtroopers'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 72, 'm9s', 'Job well done, citizen. The Alliance is glad to have trusted agents like you. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 73, 'm10d', 'Our slicers'' efforts to send bogus orders to Imperial garrisons has been very effective -- in fact, too effective. The Imperials have now taken to hand-delivering orders, which leaves our slicers vulnerable to Imperial Intelligence. We need someone to pick up new encryption codes and deliver them to our local slicers. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 77, 'm10r', 'Really? I gotta stop? Aww, just when I was having such fun. Okay, I''ll tell our gang to cool their jets. We''ll institute these new codes right away.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 78, 'm10p', 'Here are the new codes. They should help protect our data slicers. It''s good to see our tactics are working, however.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 79, 'm10t', 'Save the Data Slicers'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 80, 'm10s', 'That should keep Imperial Intelligence guessing for a bit longer. Those goons are certainly dedicated, I''ll give them that. Thanks for your help.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 81, 'm11d', 'The Empire plans on arresting many former Senators and their families. We need someone to pick up the list of possible targets and deliver them to one of our HoloNet slicers so they can warn these individuals. The slicer is to provide a list of High Command contacts if anyone needs assistance fleeing their system. Can you help us?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 84, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 85, 'm11r', 'This warning will no doubt be intercepted by the Imperial Analysis Bureau. You guys needs to move fast if you want to save those senators.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 86, 'm11p', 'Here''s the list. Remember, the more powerful politicians we get on our side, the better off we''ll be.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 87, 'm11t', 'Save the Senators'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 88, 'm11s', 'Your efforts will save many lives, citizen. The Alliance is grateful. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 89, 'm12d', 'The New Order''s stance on alien species has given us an edge in recruiting these neglected citizens. Of special interest to High Command are the Duros. We need a courier to pick up encrypted orders and deliver them to one of our agents specializing in Alien Species Affairs. They are to travel to Duro and continue negotiating with the Duros'' leaders.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 93, 'm12r', 'I think the Duros are determined to remain neutral but I''ll continue negotiating with them.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 94, 'm12p', 'Here are the orders. Many other alien species would follow the Duros'' example if they were to join the Alliance.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 95, 'm12t', 'Help Rally the Aliens'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 96, 'm12s', 'The Alliance appreciates your efforts. With luck, disenfranchised species will boost our ranks and help us topple the Empire.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 97, 'm13d', 'One of our refueling stations in the Outer Rim has been compromised, and we believe that the Empire is using it as bait to capture Alliance transports. An encrypted set of orders must be picked up and delivered to our local cell leader. We must insure that every transport captain and pilot aiding the Alliance receives these orders.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 101, 'm13r', 'We''ll get this information out to our pilots at once. Thank you.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 102, 'm13p', 'Here you go, citizen. And cheer up. For every station that the Empire discovers, we have ten more they know nothing about.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 103, 'm13t', 'Save the Pilots'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 104, 'm13s', 'Good work, citizen. Our pilots are a very precious resource and we must do all we can to protect them. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 105, 'm14d', 'We have proof that an Imperial prison official at Kessel has been supplying glitterstim to smugglers and Black Sun. We need someone to pick up an encrypted message and deliver it to one of our couriers. We intend to present our "terms" to the Imperial official. He either cooperates with us, or we turn over our proof to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 109, 'm14r', 'Good old-fashioned blackmail, eh? Hey, if it''s effective --'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 110, 'm14p', 'Remember, we do what we must to insure the fall of the Empire. In this case, it should be fun.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 111, 'm14t', 'Blackmail the Empire'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 112, 'm14s', 'Well done. Remember to keep this quiet. We don''t want word of this getting around to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 113, 'm15d', 'We''ve received a request from Commander Skywalker. He''d like us to get our hands on an Imperial Inquisitor. We need someone to pick up his encrypted orders and deliver them to our local cell commander. All commanders are to coordinate with High Command to help achieve this top priority mission. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 117, 'm15r', 'With pleasure! I''ve been wanting to take down one of these mighty Inquisitors ever since I heard of them.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 118, 'm15p', 'The orders are on this datadisc. I imagine we can learn a great deal from an Inquisitor. Good luck.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 119, 'm15t', 'Nab an Imperial Inquisitor'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 120, 'm15s', 'That was well done. With any luck, we''ll be able to supply Commander Skywalker with an Inquisitor very soon. I wonder what he has in mind?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 121, 'm16d', 'A shipment of Merr-Sonn IR-5 "Intimidator" blaster pistols has fallen into our hands. We need someone to pick up inventory discs and deliver them to our local cell commanders. They can request these weapons for upcoming missions, especially any dealing with smugglers and pirates -- those types are easily intimidated. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 125, 'm16r', 'I''ve seen those blasters. Effective weapons indeed. I''ll look through this inventory carefully.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 126, 'm16p', 'Here you go. And remind the commanders that these weapons not only look intimidating, they also pack quite a punch.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 127, 'm16t', 'Disperse the Nasty Guns'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 128, 'm16s', 'Excellent, citizen. These weapons will help our undercover agents deal with those unpredictable smugglers.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 129, 'm17d', 'A generous planetary governor has donated several new MD series medical droids. Could you pick up the specs for these droids and deliver them to our local cell commander? All requests for these droid must go through Winter, who will process them directly. Make sure the commanders make a strong case or they may not get one.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 133, 'm17r', 'My people sure could use one of those droids. I''ll make a no-frills request at once. I hear Winter is fond of brevity. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 134, 'm17p', 'Make sure the commander gets this. These sorts of donations help keep the Alliance strong.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 135, 'm17t', 'Medical Droids for Everybody'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 136, 'm17s', 'Thanks for your help. The Alliance could use more reliable couriers like yourself. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 137, 'm18d', 'We found some old Trade Federation droidekas. These might be useful on certain missions or as security droids on some of our bases. Could you pick up this encrypted message and deliver it to our contact at High Command? We need instructions on how to proceed. Winter will hold these units until she receives those instructions.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 141, 'm18r', 'Weren''t those things awfully unreliable? I always heard that''s why the Trade Federation stopped using them. Well, I''ll pass this along.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 142, 'm18p', 'Here you go. Inform High Command that the droidekas seem to be in perfect condition. I don''t believe they were ever activated.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 143, 'm18t', 'A Blast From the Past'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 144, 'm18s', 'We appreciate your help, citizen. The Alliance has compensated you for your efforts. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 145, 'm19d', 'Procurement and Supply recently sent us a message asking for further instructions on the matter of some droidekas. I need you to pick up High Command''s response and deliver it to our P&S contacts so they can forward it to Winter. Do this quickly and we''ll reward you accordingly.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 149, 'm19r', 'Thanks, citizen. We''ll see what the bosses have to say, I suppose.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 150, 'm19p', 'Here you are. Any tool is only as effective as our ability to control and use it properly.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 151, 'm19t', 'Dealing with Obsolete Droids'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 152, 'm19s', 'That was a prompt delivery, citizen. Your fee has been deposited. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 153, 'm20d', 'A shipment of laser cutters must get to a secret facility in the Outer Rim. I need you to pick up encrypted orders and deliver them to one of our transport pilots. The pilot must report to High Command before leaving the local system. The location of the laser cutters as well as the coordinates of the secret facility will be revealed at that time.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 157, 'm20r', 'Well, the Empire hasn''t found us yet. So I guess all these hoops they make us jump through for the sake of secrecy is worth it.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 158, 'm20p', 'Here are the orders. We realize it''s difficult transporting all this equipment while maintaining secrecy.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 159, 'm20t', 'Carve Out a New Rebel Base'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 160, 'm20s', 'Good job, citizen. This mission was of the utmost secrecy. Your silence will save many lives. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 161, 'm21d', 'We''ve learned that a Moff is spearheading an attempt to assassinate the Emperor. An encrypted message must be picked up and delivered to one of the Moff''s agents. It informs the Moff that the Alliance will assist in whatever way possible, and it gives security codes to be used if the Moff wishes to contact High Command. Can you help us?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 165, 'm21r', 'I''ll see to it that the Moff receives this. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 166, 'm21p', 'Moffs can strike at the heart of the Imperial Machine. We should never waste an opportunity like this. Be careful delivering this disc.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 167, 'm21t', 'Aid a Plot Against the Emperor'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 168, 'm21s', 'Well done, citizen. If this Moff''s plan succeeds, this war will be over and the galaxy will be free again.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 169, 'm22d', 'We believe that the Empire is preparing to strike Mon Calamari. Please pick up these intercepted transmissions and deliver them to our Mon Calamari contact, who will send them immediately to Admiral Ackbar. If we act fast, we can save millions of Mon Calamari lives. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 173, 'm22r', 'May the Force be with us! I''ll leave at once!'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 174, 'm22p', 'The Mon Calamari are vital to the success of the Alliance. We must save them!'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 175, 'm22t', 'Save the Mon Calamari'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 176, 'm22s', 'We can only hope that we were fast enough. Thank you for your efforts, trusted agent. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 177, 'm23d', 'Imperial Intelligence has instructed their agents to travel to the Circarpous system. We don''t know if they''ve learned of our secret dealings with the Circarpousian financiers. We need you to pick up a message and deliver it to one of Princess Leia''s aides. We hope this does not jeopardize her plans to meet with the Circarpousians.  '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 181, 'm23r', 'The Princess will want to go anyway, but I will warn her. She can be stubborn, you know.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 182, 'm23p', 'It seems that the Empire is always one step ahead of us. This must change.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 183, 'm23t', 'Warn the Princess'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 184, 'm23s', 'Excellent work, citizen. I hope the Princess takes this warning to heart. Sometimes she''s too brave for her own good.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 185, 'm24d', 'Our agents have discovered that four Imperial Star Destroyers will be in space dock at the same time. We intend to strike the dock and destroy the Imperial ships. Could you pick up an encrypted datadisc and deliver it to the strike team commander? It will reveal the location of the dock and list the Alliance pilots that will participate in the mission.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 187, 'm24o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 188, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 189, 'm24r', 'If this strike succeeds, it would be a great victory for the Alliance.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 190, 'm24p', 'Deliver this fast. We''ll destroy these ships faster than the Empire can build them.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 191, 'm24t', 'Destroy Four Star Destroyers'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 192, 'm24s', 'Well done, citizen. Your service to the Alliance is being noted. '),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 193, 'm25d', 'One of our colonies has been discovered by Imperial Intelligence. Many of our leaders'' families are on this colony. We need you to pick up an evacuation order and deliver it to one of our pilots familiar with the colony. We dare not communicate via the HoloNet for fear of escalating the Imperial attack. Please hurry!'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 197, 'm25r', 'We''ll have those families off that colony in no time. Never fear.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 198, 'm25p', 'Be quick with this delivery. Until the Empire is toppled, we must remain on the move.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 199, 'm25t', 'Help Evacuate a Colony'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 200, 'm25s', 'Good work. Let''s hope we acted in time to save all those people.'),
('string/en/mission/mission_deliver_rebel_hard_non_persistent_from_npc.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_deliver_rebel_medium.stf', 1, 'm1d', 'We''ve learned that the Imperial Intelligence is using new datadiscs been implanted with small explosive devices. If you don''t enter the proper codes to read the disc, the charge goes off, destroying the disc and the reader -- and possibly the agent reading the disc. We need you to deliver this warning to our HoloNet slicer. Their safety depends on you. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 3, 'm1o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 4, 'm1r', 'I''d heard the Empire was developing something like this. Sounded too nutty to be true. Guess nothing''s too nutty in this Civil War.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 5, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 6, 'm1s', 'Good job. We relayed the information to all our covert operatives. Thanks to you, nobody will get hurt.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 7, 'm1p', 'Every day the Empire develops new ways to hamper the cause of freedom. Don''t worry, this disc won''t explode.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 8, 'm1t', 'Warning to Covert Operatives'),
('string/en/mission/mission_deliver_rebel_medium.stf', 9, 'm2d', 'One of our strike teams is hitting an Imperial depot in the Outer Rim. We want Imperial Intelligence to suspect we''re hitting a different target. We need a trusted agent to deliver these falsified Alliance communiques to our HoloNet slicer so we can make sure Imperial agents will intercept them. This should throw those Internal Security creeps off the track. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 11, 'm2o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 12, 'm2r', 'I love fooling those Imperial idiots. Haha!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 13, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 14, 'm2s', 'The mission was a complete success, thanks to you.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 15, 'm2p', 'You can rarely use the same trick twice against the Empire.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 16, 'm2t', 'Falsified Communiques'),
('string/en/mission/mission_deliver_rebel_medium.stf', 17, 'm3d', 'Although a terrible tragedy, the destruction of Alderaan has boosted our ranks. Could you deliver this datadisc to our processing officer? It contains thousands of enlistees, many of them skilled pilots. This new influx of talent may be what the Alliance needs to turn the tide of battle against the Empire. We need your help.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 19, 'm3o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 20, 'm3r', 'How typical of the Empire to not understand that fear can become hate very easily. We shall triumph.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 21, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 22, 'm3s', 'Your service to the Alliance is greatly appreciated.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 23, 'm3p', 'The Princess said it best: "The more the Empire tightens its grip, the more star systems will slip through its fingers."'),
('string/en/mission/mission_deliver_rebel_medium.stf', 24, 'm3t', 'Enlistment Rosters '),
('string/en/mission/mission_deliver_rebel_medium.stf', 25, 'm4d', 'We must constantly keep our cells supplied and their agents equipped. We need couriers to pick up supply requests and deliver them to our requisitions officer. These couriers will make sure our brave freedom fighters have what they need to fight the Empire. Will you assist in this important task?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 27, 'm4o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 28, 'm4r', 'Thanks. Fortunately some "procurement specialists" just made it past the blockades, or we might have been in supply trouble.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 29, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 30, 'm4s', 'Keeping the Alliance running is an endless task. We appreciate your efforts.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 31, 'm4p', 'We''re glad to see you. Supplies are running pretty seriously low around here. Please hurry!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 32, 'm4t', 'Crucial Supply Requests'),
('string/en/mission/mission_deliver_rebel_medium.stf', 33, 'm5d', 'Our Incom engineers have provided us with the latest X-wing flight simulator. This will be a great training aid for our new pilots. We need you to deliver this copy of the simulator to one of our training officers. Make sure they report any bugs to High Command. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 35, 'm5o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 36, 'm5r', 'I hear this is modeled on the TIE flight sims. Our pilots will benefit greatly.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 37, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 38, 'm5s', 'Thank you for your assitance in this matter.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 39, 'm5p', 'Ever wanted to fly an X-wing? I think every Alliance member does.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 40, 'm5t', 'New Flight Simulation'),
('string/en/mission/mission_deliver_rebel_medium.stf', 41, 'm6d', 'We''ve learned that some local youths have been harassing an Imperial recruiter. We need someone to warn their leader that the Empire is sending a squad of stormtroopers to deal with them. Is that someone you? These youths should lay low for a while. Tell them we appreciate their show of support for the Alliance.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 43, 'm6o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 44, 'm6r', 'Thanks, friend. Me and my friends will disappear for a while.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 45, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 46, 'm6s', 'You got word to them just in time. Well done.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 47, 'm6p', 'We encourage everyone to show dissatisfaction with the Empire, but not to the point of craziness.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 48, 'm6t', 'Stormtrooper Warning'),
('string/en/mission/mission_deliver_rebel_medium.stf', 49, 'm7d', 'Some of our agents have attempted to enlist with the Empire in order to spy for the Alliance. We believe Imperial Intelligence has identified a large number of these agents. We must have these orders delivered to our local cell contact. They instruct local agents not to enlist. We''ll find other uses for their skills. Can you help us save these freedom fighters?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 51, 'm7o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 52, 'm7r', 'I''ll get the news out to our agents immediately.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 53, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 54, 'm7s', 'That was a near thing. You helped a lot of people.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 55, 'm7p', 'One thing I will say for Imperial Intelligence -- they''re very thorough.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 56, 'm7t', 'Alliance Agents at Risk'),
('string/en/mission/mission_deliver_rebel_medium.stf', 57, 'm8d', 'Every since the destruction of the Death Star, the number of beings wanting to enlist with the Alliance has risen dramatically. We suspect that some of these individuals may be double agents working for the Empire. This roster of enlistees must be delivered to our High Command contact so that our Intelligence department can do very thorough security clearances on all of them. Help keep the Alliance free of Imperial spies.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 59, 'm8o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 60, 'm8r', 'Sometimes these double agents are hard to spot. We''ll do our best.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 61, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 62, 'm8s', 'You''ve been a tremendous help. Thank you.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 63, 'm8p', 'There have been instances of Imperial double agents denouncing the Empire and working solely for us.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 64, 'm8t', 'Searching for Double Agents'),
('string/en/mission/mission_deliver_rebel_medium.stf', 65, 'm9d', 'Our slicers have intercepted a secret Imperial communique that tells us the Empire has sent dossiers of all the surviving Battle of Yavin pilots to their local garrisons. They''ve put a high priority on having these individuals arrested. Mentioned prominently in the communique were Commanders Solo and Skywalker as well as the Wookiee Chewbaca. We must have someone send this communique and a warning to our contact in High Command so that these heroes may be warned. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 67, 'm9o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 68, 'm9r', 'Thanks. We''ll put these heroes on alert.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 69, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 70, 'm9s', 'We''re glad you were able to get the word out in time. Well done.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 71, 'm9p', 'The security of the Heroes of Yavin is one of our top priorities.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 72, 'm9t', 'Protect our Heroes'),
('string/en/mission/mission_deliver_rebel_medium.stf', 73, 'm10d', 'Our engineers have discovered a flaw in the design of stormtrooper helmet comlinks. We need a trusted agent to send this technical analysis to our local cell contact and inform them that we can use this flaw to intercept squad communications. I believe this flaw is limited to the older style helmets. This information will therefore benefit our cells on remote outposts the most. Think you can handle this mission? '),
('string/en/mission/mission_deliver_rebel_medium.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 75, 'm10o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 76, 'm10r', 'Thanks. I always wondered what stormtroopers chatted about when they were just standing around.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 77, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 78, 'm10s', 'Keep up the good work!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 79, 'm10p', 'We should act on this now, because we don''t know how long this flaw will go unnoticed by the Empire.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 80, 'm10t', 'Technical Analysis'),
('string/en/mission/mission_deliver_rebel_medium.stf', 81, 'm11d', 'Some local merchants, as a protest, are not giving Imperial military personnel the standard 30 percent discount on the purchase of goods. We need this message delivered to the merchants'' representative. It says that this will only draw unwanted attention to their region, and therefore to any possible Alliance cells located in their area. To help the Alliance, they should give the Imperials their discount. Is this something you could help us with?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 83, 'm11o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 84, 'm11r', 'As loathe as we are to do this, we do wish to help the Alliance. It will be done.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 85, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 86, 'm11s', 'It''s heartening that so many merchants want to help us. Thanks for your help too.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 87, 'm11p', 'No use in stirring up a skettos'' nest. We want to Empire to ease its grip, not tighten it.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 88, 'm11t', 'Keep a Low Profile'),
('string/en/mission/mission_deliver_rebel_medium.stf', 89, 'm12d', 'Our slicers'' efforts to send bogus orders to Imperial garrisons has been very effective -- in fact, too effective. The Imperials have now taken to hand-delivering their orders, which leaves our slicers vulnerable to Imperial Intelligence. We need someone to pick up a new set of encryption codes and deliver them to our local slicers. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 91, 'm12o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 92, 'm12r', 'Really? I gotta stop? Aww, just when I was having such fun. Okay, I''ll ask the gang to throttle back, and we''ll work with these new codes.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 93, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 94, 'm12s', 'That should keep Imperial Intelligence guessing for a bit longer. Those goons are certainly dedicated, I''ll give them that. Thanks for your help.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 95, 'm12p', 'Here are the new codes. They should help protect our data slicers. They''re weird, but they''re good folks and we need them.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 96, 'm12t', 'Danger to Slicers'),
('string/en/mission/mission_deliver_rebel_medium.stf', 97, 'm13d', 'We understand that the Empire has just granted many garrisons extended leave for their troops. We need this message delivered to our local cell contact, so we can put all our informants on alert. We need to get our agents as close as possible to these off-duty soldiers. It''s amazing how talkative some of these men become after a few drinks. Can you help us trap these Imperials? '),
('string/en/mission/mission_deliver_rebel_medium.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 99, 'm13o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 100, 'm13r', 'We''ll put all of our best agents to work. Especially the attractive ones.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 101, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 102, 'm13s', 'Thanks to you, we should gather a lot of useful information.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 103, 'm13p', 'Remind our contact that happy soldiers are chatty soldiers.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 104, 'm13t', 'Loose Lips'),
('string/en/mission/mission_deliver_rebel_medium.stf', 105, 'm14d', 'We''ve worked out a deal with our contacts within the Corporate Sector Authority to help us secure the release of several Alliance agents. They are putting in a request to the Empire for more workers for hard labor. We believe the Empire will fill these positions with known Alliance members. We need this message sent to our contact in the CSA. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 107, 'm14o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 108, 'm14r', 'I''ll see that this order is filled immediately, citizen. Good day.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 109, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 110, 'm14s', 'Your part in this is complete. Now, it''s up to others.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 111, 'm14p', 'The Viceprexes friendly to our cause are to contact High Command immediately upon receiving their new work crews. Some of your friends may be among the prisoners rescued.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 112, 'm14t', 'Free Alliance Agents'),
('string/en/mission/mission_deliver_rebel_medium.stf', 113, 'm15d', 'This message must be delivered to the local Alliance Procurement officer immediately! One of the Imperial depots we raided has contaminated supplies. Many energy cells, weapons, and medical scanners that were seized have trackers inside them. All goods taken from Imperial Depot 22-TZK are to be jettisoned into space. Can you make sure this message is received?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 115, 'm15o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 116, 'm15r', 'Argh, some of these supplies may already have gone out. I''ll track them down!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 117, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 118, 'm15s', 'It''s a good thing you got that information out in time. That could have gone very badly for our people. Soon we''ll have to subject every single seized shipment to deep and time-consuming scans.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 119, 'm15p', 'Remember, materials from Imperial Depot 22-TZK are not to be distributed to supply stations -- they are to be jettisoned. Spread the word.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 120, 'm15t', 'Bugged Equipment'),
('string/en/mission/mission_deliver_rebel_medium.stf', 121, 'm16d', 'A top-ranking Sienar Fleet Systems engineer has defected to the Alliance. The Empire is eager to get its hands on this engineer. We need this encrypted message delivered to our local cell contact. It will let them know if the engineer will be arriving at their location and specifics of that arrival. The Alliance is depending on you. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 123, 'm16o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 124, 'm16r', 'If that engineer shows up here, we''ll keep him safe.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 125, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 126, 'm16s', 'If we can get that Imperial engineer, that would be a blow to the Empire and a big help for us. The last thing we need is a faster, more maneuverable TIE fighter. Thanks for your help.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 127, 'm16p', 'We can''t afford to lose this engineer, because he helped design Vader''s experimental TIE fighter -- a design being incorporated into an elite TIE model we have yet to see. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 128, 'm16t', 'Imperial Defector'),
('string/en/mission/mission_deliver_rebel_medium.stf', 129, 'm17d', 'The Empire plans on arresting many former Senators and their families. We need someone to pick up the list of possible targets and deliver them to one of our HoloNet slicers so we can warn these targets. The slicer is to provide a list of High Command contacts to anyone fleeing arrest. Can you help us?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 131, 'm17o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 132, 'm17r', 'When I send this warning, the Imperial Analysis Bureau will be riding my tail in about ten seconds flat. You guys needs to move fast to save those -- who is it? Senators? Whoever.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 133, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 134, 'm17s', 'The Senators wish to express their thanks for your aid.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 135, 'm17p', 'Here''s the list. Remember, the more powerful politicians we get on our side, the better off we''ll be.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 136, 'm17t', 'Senators Need Your Help'),
('string/en/mission/mission_deliver_rebel_medium.stf', 137, 'm18d', 'The New Order''s stance on alien species has given us an edge in recruiting these neglected citizens. Of special interest to High Command are the Duros. We need a courier to pick up encrypted orders and deliver them to our agent specializing in Alien Species Affairs. The agent is to travel to Duro and continue negotiating with the leaders there.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 139, 'm18o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 140, 'm18r', 'I think the Duros are determined to remain neutral, but I''ll continue negotiating with them.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 141, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 142, 'm18s', 'The Alliance appreciates your efforts. With luck, disenfranchised species will boost our ranks and help us topple the Empire.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 143, 'm18p', 'Here are the orders. Many alien species would follow the Duros'' example if they joined the Alliance.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 144, 'm18t', 'Diplomatic Mission'),
('string/en/mission/mission_deliver_rebel_medium.stf', 145, 'm19d', 'One of our refueling stations in the Outer Rim has been compromised, and we believe that the Empire is using it as bait to capture Alliance transports. Pick up these encrypted orders and deliver them to our local cell leader. We must insure that every transport captain and pilot aiding the Alliance receives these orders.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 147, 'm19o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 148, 'm19r', 'We''ll get this information out to our pilots at once.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 149, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 150, 'm19s', 'Good work. Our pilots are a precious resource, and we must do all we can to protect them.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 151, 'm19p', 'Here you go. And cheer up. For every station that the Empire discovers, we have ten more they know nothing about.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 152, 'm19t', 'An Imperial Trap'),
('string/en/mission/mission_deliver_rebel_medium.stf', 153, 'm20d', 'One of General Airen Cracken''s "procurement specialists" believes the Alliance is trying to set him up. We need this encrypted message delivered to our slicer so we can transmit this smuggler''s concerns to General Cracken. Can you lend us a hand?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 155, 'm20o', 'Winter: Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 156, 'm20r', 'These smugglers and pirates are all rogues. But then again, so am I.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 157, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 158, 'm20s', 'The disc gave the rendezvous point specified by this nervous "procurement specialist." We''ve checked him out, and he seems to be on the level. General Cracken can probably smooth matters over so we don''t lose our "specialist."'),
('string/en/mission/mission_deliver_rebel_medium.stf', 159, 'm20p', 'This particular smuggler-- er, I mean, specialist -- just captured a large shipment of medical supplies bound for Imperial outposts. He wants General Cracken to meet him personally to insure prompt payment.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 160, 'm20t', 'Stolen Medical Supplies'),
('string/en/mission/mission_deliver_rebel_medium.stf', 161, 'm21d', 'We have proof that an Imperial prison official at Kessel has been supplying glitterstim to smugglers and Black Sun. We need someone to pick up the encrypted evidence and deliver it to one of our couriers. We intend to present our "terms" to the Imperial official. He''ll either cooperate with us or we turn over our proof to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 163, 'm21o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 164, 'm21r', 'Good old-fashioned blackmail, eh? Hey, if it''s effective --'),
('string/en/mission/mission_deliver_rebel_medium.stf', 165, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 166, 'm21s', 'Well done. Remember to keep this quiet. We don''t want word getting around to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 167, 'm21p', 'Here''s the data. Remember, we do what we must to insure the fall of the Empire. In this case, it''ll be fun!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 168, 'm21t', 'Blackmail Notification'),
('string/en/mission/mission_deliver_rebel_medium.stf', 169, 'm22d', 'We''ve received a request from Commander Skywalker. He''d like us to get our hands on an Imperial Inquisitor. We need someone to pick up his encrypted orders and deliver them to our local cell commander. All commanders are to coordinate with High Command to help achieve this top-priority mission. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 171, 'm22o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 172, 'm22r', 'With pleasure! I''ve been wanting to take down one of these mighty Inquisitors ever since I heard of them.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 173, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 174, 'm22s', 'Commander Skywalker sends his thanks to all. With any luck, we''ll be able to supply him with an Inquisitor soon. I wonder what he has in mind?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 175, 'm22p', 'The orders are on this datadisc. I imagine we can learn a great deal from an Inquisitor. Good luck.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 176, 'm22t', 'Help Commander Skywalker'),
('string/en/mission/mission_deliver_rebel_medium.stf', 177, 'm23d', 'A shipment of Merr-Sonn IR-5 "Intimidator" blaster pistols has fallen into our hands. We need someone to pick up inventory discs and deliver them to our local cell commanders. They can request these weapons for upcoming missions, especially any dealing with smugglers and pirates -- those types are easily intimidated. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 179, 'm23o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 180, 'm23r', 'I''ve seen those blasters. Effective weapons indeed. I''ll look through this inventory carefully.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 181, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 182, 'm23s', 'Can you believe it? All the blasters have been claimed already. These weapons will help our undercover agents deal with those unpredictable smugglers. Thanks!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 183, 'm23p', 'Here you go. And remind the commanders that these weapons not only look intimidating, they also pack quite a punch.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 184, 'm23t', 'Blasters Available'),
('string/en/mission/mission_deliver_rebel_medium.stf', 185, 'm24d', 'A generous sympathizer has donated several new MD-series medical droids. Could you pick up the specs for these droids and deliver them to our local cell commander? All requests for these droid must go through Winter, who will process them directly. Make sure the commanders make a strong case, or they may not get one.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 187, 'm24o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 188, 'm24r', 'My people sure could use one of those droids. I''ll make a no-frills request at once. I hear Winter is fond of brevity.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 189, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 190, 'm24s', 'It''s a shame there were only five droids to be had. We could have used many more. But we''re grateful, regardless -- and on that note, thanks for your help.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 191, 'm24p', 'Make sure the commander gets this. These donations keep the Alliance strong.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 192, 'm24t', 'Only a Few Medical Droids Left'),
('string/en/mission/mission_deliver_rebel_medium.stf', 193, 'm25d', 'We found some old Trade Federation droidekas. These might be useful on certain missions or as security droids on some of our bases. Could you pick up this encrypted message and deliver it to our contact at High Command? We need instructions on how to proceed. Winter will hold these units until she receives those instructions.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 195, 'm25o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 196, 'm25r', 'Weren''t those things awfully unreliable? I always heard that''s why the Trade Federation stopped using them. Well, I''ll pass this along.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 197, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 198, 'm25s', 'We appreciate your help, citizen. Meanwhile, we''re looking into the source of those perfectly preserved droidekas. Could be more where those came from.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 199, 'm25p', 'Here you go. Inform High Command that the droidekas seem to be in perfect condition. I don''t believe they were ever activated.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 200, 'm25t', 'A Few Good Security Droids'),
('string/en/mission/mission_deliver_rebel_medium.stf', 201, 'm26d', 'Procurement and Supply recently sent us a message asking for further instructions on the matter of some droidekas. I need you to pick up High Command''s response and deliver it to our P&S contacts so they can forward it to Winter. Do this quickly and we''ll reward you accordingly.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 202, 'm26l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 203, 'm26o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 204, 'm26r', 'We''ll see what the bosses have to say, I suppose.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 205, 'm26f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 206, 'm26s', 'That was a prompt delivery, citizen. Your fee has been deposited. Your service to the Alliance is always appreciated.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 207, 'm26p', 'Any tool is only as effective as our ability to control and use it properly.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 208, 'm26t', 'Straight From the High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 209, 'm27d', 'The Empire has begun targeting luxury starliners. They claim that several of them have been transporting goods to the Alliance. We need this warning delivered to our HoloNet data slicer so we can warn the starliner crews. We don''t want innocent folks killed. Can you help save them?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 210, 'm27l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 211, 'm27o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 212, 'm27r', 'Hey, my mom loves taking cruises on those things. You bet I''ll warn them.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 213, 'm27f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 214, 'm27s', 'Thanks to your timely intervention, we may be able to use the starliners again in the future.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 215, 'm27p', 'The Empire does not understand the meaning of the words "innocent lives," nor do they care how many are lost.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 216, 'm27t', 'Starliners Beware'),
('string/en/mission/mission_deliver_rebel_medium.stf', 217, 'm28d', 'We need to get a shipment of laser cutters to a secret facility in the Outer Rim. We need you to pick up encrypted orders and deliver them to one of our transport pilots. This is a most important mission. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 218, 'm28l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 219, 'm28o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 220, 'm28r', 'The Empire hasn''t found us yet. So I guess it''s worth it -- all these hoops they make us jump through for the sake of secrecy.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 221, 'm28f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 222, 'm28s', 'It''s difficult transporting all this equipment while maintaining secrecy. We''re glad to know we can count on you. Well done.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 223, 'm28p', 'Here are the orders. The pilot must report to High Command before leaving the local system. High Command will give the pilot the location of the laser cutters as well as the coordinates of the secret facility.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 224, 'm28t', 'Tools for a Secret Base'),
('string/en/mission/mission_deliver_rebel_medium.stf', 225, 'm29d', 'We''ve learned that a Moff is spearheading an attempt to assassinate the Emperor. Pick up this encrypted message and deliver it to one of the Moff''s agents. It informs the Moff that the Alliance will assist in whatever way it can and gives security codes if the Moff wishes to contact High Command. Can you help us?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 226, 'm29l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 227, 'm29o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 228, 'm29r', 'I''ll see to it that the Moff receives this.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 229, 'm29f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 230, 'm29s', 'Well done, citizen. If this Moff''s plan succeeds, this war will be over and the galaxy will be free again.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 231, 'm29p', 'Moffs can strike at the heart of the Imperial Machine. We should never waste an opportunity like this. Be careful delivering this disc.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 232, 'm29t', 'Assasination Plot'),
('string/en/mission/mission_deliver_rebel_medium.stf', 233, 'm30d', 'We keep receiving supply request from Rogue Squadron. Deliver these requests to our High Command officer and ask for final approval or denial -- otherewise, Rogue Squadron will not stop contacting us. Tell Command to note that the requests are signed by Wedge Antilles and countersigned by Commander Skywalker. You''ve got this one, right?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 234, 'm30l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 235, 'm30o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 236, 'm30r', 'More requests from Rogue Squadron? Those guys are great, but they sure do run through a lot of supplies -- sometimes more than we can spare.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 237, 'm30f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 238, 'm30s', 'I guess even heroes can get caught up in bureaucracy. Thanks for helping sort that out.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 239, 'm30p', 'I''m not sure why there''s a disconnect between Rogue Squadron and Starfighter Command. Sure, we like hearing from the Rogues, but too much chatter is a security risk. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 240, 'm30t', 'Rogue Squadron Requests'),
('string/en/mission/mission_deliver_rebel_medium.stf', 241, 'm31d', 'Winter has sent us several of Wedge Antilles'' requests for supplies for his Rogue Squadron. Winter needs these approved by our department. Please deliver this datadisc of approved requests to one of Procurement''s officers. If Rogue Squadron has any problems with our decision, Antilles can take it up with us. Can you handle that?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 242, 'm31l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 243, 'm31o', 'Alliance Starfighter Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 244, 'm31r', 'I wish those guys would leave us out of their squabbles.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 245, 'm31f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 246, 'm31s_', 'I''m sure the Rogues were pleased to get those requests approved. By the way, we''re working on smoothing out the approval process. That should please Wedge!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 247, 'm31p', 'Wedge and Commander Skywalker are heroes of the Alliance, but they still have to follow proper channels.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 248, 'm31t', 'Approved Requests'),
('string/en/mission/mission_deliver_rebel_medium.stf', 249, 'm32d', 'Miners that have joined the Alliance have shown us a great use for the common LIN Demolitionmech droids. We would like the specs for these droids sent to our local cell commanders on this encrypted datadisc. Careful this doesn''t fall into the wrong hands. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 250, 'm32l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 251, 'm32o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 252, 'm32r', 'This will help us sabotage Imperial depots and shipyards. Excellent!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 253, 'm32f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 254, 'm32s', 'The information you delivered was of great value. A job well done.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 255, 'm32p', 'Specially rigged demolitionmechs can place explosives. If you rig them with a holographic disguiser and a sensor jamming device, they can look like common R3 droids!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 256, 'm32t', 'Explosive Droid Specs'),
('string/en/mission/mission_deliver_rebel_medium.stf', 257, 'm33d', 'We''d like to redistribute some of our A-A5 speeder trucks that we''ve modified to operate as armored personnel carriers. Send the specs for these speeder trucks to the local cell commander and see if they could use one of these trucks. We''re counting on you.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 258, 'm33l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 259, 'm33o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 260, 'm33r', 'I''ll check with our supply specialist, but I think we could use one. Those A-A5s are sturdy machines.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 261, 'm33f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 262, 'm33s', 'Excellent work. We''re very pleased with the quality of your work.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 263, 'm33p', 'Our settlements on the Outer Rim would be the best destinations for these vehicles, but we understand that there may be a need for them in the Core Worlds as well.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 264, 'm33t', 'Modified Speeder Specs'),
('string/en/mission/mission_deliver_rebel_medium.stf', 265, 'm34d', 'A gang of young Skyhopper pilots contacted one of our commanders and offered help in striking Imperial outposts in their home system. Can you deliver this datadisc to Starfighter Command and see what they wish to do with these hotshots? Their dossiers, including their criminal records, are contained on the disc.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 266, 'm34l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 267, 'm34o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 268, 'm34r', 'Half of our pilots were trained on T-16''s. We''ll think of an offer they''ll accept.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 269, 'm34f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 270, 'm34s', 'It takes all kinds, I suppose. Still, good pilots are a valuable resource. Anyone wanting to harass the Empire can''t be all bad.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 271, 'm34p', 'It seems these toughs had no interest in the Academy and don''t really like the idea of serving the Alliance as possible X-wing pilots. They just want to cause mayhem for the Empire.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 272, 'm34t', 'Pilot Dossiers'),
('string/en/mission/mission_deliver_rebel_medium.stf', 273, 'm35d', 'Starfighter Command is trying to recruit a gang of T-16 pilots. These young hotshots are quite skilled, apparently, but lack discipline and don''t wish to answer to anyone save themselves. Starfighter Command has decided to offer them the deal on this encrypted datadisc. Can you deliver this offer to the cell commander who deals with these pilots?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 274, 'm35l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 275, 'm35o', 'Alliance Starfighter Command   '),
('string/en/mission/mission_deliver_rebel_medium.stf', 276, 'm35r', 'I can''t wait to see what these guys have been offered. Thanks.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 277, 'm35f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 278, 'm35s', 'I have no idea what Starfighter Command offered those pilots. I''ll just trust that Command knows what it''s doing. However it works out, your work was exemplary.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 279, 'm35p', 'I hope this is worth it. These guys have extensive criminal records, and not just crimes against the Empire. Apparently they used to terrorize local merchants and transports.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 280, 'm35t', 'Starfighter Command Offer'),
('string/en/mission/mission_deliver_rebel_medium.stf', 281, 'm36d', 'Some of our field agents are requesting Z-6 jetpacks for an upcoming mission. Their requisition order must be delivered to one of Procurement and Supply''s officers. Tell them that this request comes from Alliance Special Forces and is signed by General Madine himself. That should speed things up. Think you can handle that?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 282, 'm36l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 283, 'm36o', 'Alliance Special Forces'),
('string/en/mission/mission_deliver_rebel_medium.stf', 284, 'm36r', 'Ever since that bounty hunter got famous, it seems everyone wants a jetpack.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 285, 'm36f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 286, 'm36s', 'You have the makings of a top courier. Keep up the good work.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 287, 'm36p', 'We expect a prompt response.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 288, 'm36t', 'Special Forces requisition order'),
('string/en/mission/mission_deliver_rebel_medium.stf', 289, 'm37d', 'Due to the rising number of Wookiee recruits, we''ve assembled a short Wookiee language guide on this datadisc. One of our Wookiee agents assisted with this guide, so all pronunciation is accurate. Make sure the local cell commanders get this guide. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 290, 'm37l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 291, 'm37o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 292, 'm37r', 'I always wondered when they''d get around to making something like this.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 293, 'm37f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 294, 'm37s', 'We''ve had a few unfortunate Wookiee incidents due to miscommunication and wish to avoid those in the future. This guide should make for fewer one-armed freedom fighters. Thank you.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 295, 'm37p', 'Wookiees are brave fighters but can be a bit short-tempered. I''m glad they''re on our side. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 296, 'm37t', 'Wookiee Language Guide');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_rebel_medium.stf', 297, 'm38d', 'One of our "procurement specialists" sold us a shipment of R3''s. We will be assigning these astromech droids to our heavy cruisers and frigates, which will free up many R2 units for use by either our local cells or Starfighter Command. Please deliver this message to the cell commander, so the cell can place an order for these R2 units with Procurement and Supply.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 298, 'm38l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 299, 'm38o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 300, 'm38r', 'You never can have enough R2 units. But I expect that Starfighter Command requests will get top priority.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 301, 'm38f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 302, 'm38s', 'Reliable couriers are a rare breed. Keep up the good work.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 303, 'm38p', 'Personally, I prefer the old R2 units. They have more personality.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 304, 'm38t', 'R2 Droid Availability '),
('string/en/mission/mission_deliver_rebel_medium.stf', 305, 'm39d', 'A smuggler has dumped an entire kennel of neks at one of our refueling stations. He didn''t have enough credits to repair his damaged vessel and didn''t wish to barter any future smuggling missions, so he gave us all he had. I need to know what Procurement and Supply wants done with these creatures. They''re fully trained, looks like, and quite vicious. Could you deliver this message to a Procurement officer? Like, pretty soon?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 306, 'm39l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 307, 'm39o', ''),
('string/en/mission/mission_deliver_rebel_medium.stf', 308, 'm39r', 'Uh -- neks? Hmm. Well. I guess we''ll take this to General Cracken and see what he recommends. They don''t make good pets, I suppose?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 309, 'm39f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 310, 'm39s', 'An unusual payment, but we''ll find a use for those neks. Your payment is a little more traditional.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 311, 'm39p', 'I need to get rid of these neks fast. They''re scaring our communications officer.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 312, 'm39t', 'Strange Payment'),
('string/en/mission/mission_deliver_rebel_medium.stf', 313, 'm40d', 'One of our cell commanders was left with an entire kennel of neks -- long story -- and wanted to know if we could use them. Fortunately, we''ve contacted a nek handler who will trade the pack for medical supplies. We need to deliver this datadisc of instructions to the members of that commander''s cell. Feel like helping out?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 314, 'm40l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 315, 'm40o', 'Alliance Procurement and Supply'),
('string/en/mission/mission_deliver_rebel_medium.stf', 316, 'm40r', 'Good. Our communications officer was about to quit; those neks were getting her deeply flustered. We''ll get these shipped right away.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 317, 'm40f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 318, 'm40s', 'Everything can be bartered or sold for something. Words to live by. But medical supplies for neks? Now I think I''ve seen it all.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 319, 'm40p', 'The cell members should sedate the neks and put them on the first Alliance transport out of their system. We''ll arrange to pick up the neks and deliver them to the handler.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 320, 'm40t', 'Healing Power of Neks'),
('string/en/mission/mission_deliver_rebel_medium.stf', 321, 'm41d', 'We''ve learned that some cell commanders are employing bounty hunters to track down double agents. We need this order delivered to the local cell commander: Any use of bounty hunters must have direct approval from High Command. If there are any questions, contact High Command. Can we get your help on this one?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 322, 'm41l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 323, 'm41o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 324, 'm41r', 'I don''t see why we should limit our arsenal of weapons against traitors. But all right, I hear you.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 325, 'm41f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 326, 'm41s', 'Thanks for your aid. That could have been a security nightmare. Bounty hunters will gladly sell any information they have to the Empire. The risk of using them is too great.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 327, 'm41p', 'Make sure the commander gets the message: Under no circumstances are bounty hunters to be used against former Alliance officers, even those suspected of working for the Empire.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 328, 'm41t', 'Orders About Bounty Hunters'),
('string/en/mission/mission_deliver_rebel_medium.stf', 329, 'm42d', 'Reports from our HoloNet slicers claim some sort of Imperial super-slicer on the HoloNet has intercepted many Alliance communiques. The slicer goes by the code name "Blackhole." Please deliver these instructions to our local data slicer. Any activity on the HoloNet suspected of being the work of Blackhole is to be reported to us immediately.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 330, 'm42l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 331, 'm42o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_medium.stf', 332, 'm42r', 'I''ve heard about this Blackhole guy, or gal, or thing, or whatever it may be. I''m betting my jets burn smoother than his. But okay, okay, I''ll keep an eye open.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 333, 'm42f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 334, 'm42s', 'We hope our slicers can negate Blackhole''s ability to interfere with the Alliance. Truth to tell, High Command is basically forced to stand back and just let our slicers work. Most of us are out of our depth here.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 335, 'm42p', 'We suspect that this Blackhole figure may be the head of Imperial Intelligence, or perhaps even the Emperor himself. We must discover this mysterious agent''s identity. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 336, 'm42t', 'Code Name Blackhole'),
('string/en/mission/mission_deliver_rebel_medium.stf', 337, 'm43d', 'Our contact on the Corporate Sector Authority''s Direx Board informs us that Imperial Intelligence is reviewing every single expense report generated by the Viceprexes. We need to make sure the Viceprexes friendly to our cause are aware of this, and warn them to proceed with extreme caution. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 338, 'm43l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 339, 'm43o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_medium.stf', 340, 'm43r', 'We''ll get word to our superiors immediately.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 341, 'm43f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 342, 'm43s', 'You''ve been a great help in protcting our CSA Viceprexes. As powerful as they are, it''s ironic they need our protection!'),
('string/en/mission/mission_deliver_rebel_medium.stf', 343, 'm43p', 'The help we receive from friendly Viceprexes is incredibly important to our cause. The Empire could track Alliance sympathizers using these reports.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 344, 'm43t', 'Warning to Viceprexes'),
('string/en/mission/mission_deliver_rebel_medium.stf', 345, 'm44d', 'We need pilots with experience navigating asteroid belts. Please deliver this notice to the local cell commanders so they can have any such pilots they may know of report to Starfighter Command immediately. Can the Alliance count on you?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 346, 'm44l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 347, 'm44o', 'Alliance Starfighter Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 348, 'm44r', 'We''ll put the word out that we''re searching for experienced pilots.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 349, 'm44f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 350, 'm44s', 'We''re always on the lookout for skilled pilots. If you know any, send them our way.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 351, 'm44p', 'Our missions take us to many treacherous and isolated areas of space. Every pilot must undertake rigorous training and will be incommunicado for several months. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 352, 'm44t', 'Pilots Needed'),
('string/en/mission/mission_deliver_rebel_medium.stf', 353, 'm45d', 'Since our victory at Yavin 4, more smugglers have offered their services to the Alliance. We want these instructions delivered to the local Alliance cell. It lays out a standard procedure for evaluating potential "procurement specialists" and gives the proper report forms that every cell commander must have approved prior to using any smuggler. Are you the agent for this mission?  '),
('string/en/mission/mission_deliver_rebel_medium.stf', 354, 'm45l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 355, 'm45o', 'Alliance Intelligence'),
('string/en/mission/mission_deliver_rebel_medium.stf', 356, 'm45r', 'We needed a standard operating procedure for these guys. Good to see we have one now.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 357, 'm45f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 358, 'm45s', 'We''ll be careful to weed out the completely untrustworthy smugglers. I hope that''s not all of them! Thanks for your help.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 359, 'm45p', 'We should always be suspicious of any smuggler who approaches us with an offer of assistance. Security will always be an issue.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 360, 'm45t', 'Smuggler Security Check'),
('string/en/mission/mission_deliver_rebel_medium.stf', 361, 'm46d', 'Our contacts inside the University of Byblos have indicated that interest in the Alliance is at an all-time high. We have an opportunity to recruit some of the galaxy''s most talented young physicians and scientists. This encrypted message must go to our local Alliance Intelligence agent. We need more covert agents on Byblos to aid with recruitment. Help us recruit the brightest minds in the galaxy.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 362, 'm46l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 363, 'm46o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 364, 'm46r', 'We''ll devise a strategy and make sure we get those gifted young minds.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 365, 'm46f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 366, 'm46s', 'The Alliance needs all the skilled help it can get. Yours included.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 367, 'm46p', 'Our Science Division works tirelessly at devising ways to thwart Imperial technology. They are priceless.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 368, 'm46t', 'Byblos University Recruiting'),
('string/en/mission/mission_deliver_rebel_medium.stf', 369, 'm47d', 'Ever since we attracted the attention of Borsk Fey''lya, our access to Bothan spies has increased dramatically. They are the best in the galaxy at what they do. We need you to hand-deliver this encrypted communique to our Alliance Intelligence liaison so we can coordinate their activities with the Bothans that Minister Fey''lya has put at our disposal.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 370, 'm47l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 371, 'm47o', 'Alliance High Command'),
('string/en/mission/mission_deliver_rebel_medium.stf', 372, 'm47r', 'We''ll begin including the Bothan representatives into our future communications and meetings.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 373, 'm47f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 374, 'm47s', 'The Alliance is lucky to have a dependable courier such as yourself in its service.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 375, 'm47p', 'Bothans trade in information, and that is a precious commodity indeed.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 376, 'm47t', 'More and Better Spies'),
('string/en/mission/mission_deliver_rebel_medium.stf', 377, 'm48d', 'There seems to be some division within the Alliance in regards to the Jedi. Many feel they were a boon to the Old Republic and were noble guardians of peace. Others believe they were responsible for the corruption that destroyed the Old Republic and led to the Clone Wars. Could you deliver these instructions from High Command to the local cell commander?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 378, 'm48l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 379, 'm48o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 380, 'm48r', 'I think we''ll be talking about the Jedi plenty in years to come.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 381, 'm48f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 382, 'm48s', 'Personally, I wish there were a lot more Jedi. That''s just between us.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 383, 'm48p', 'Word from High Command is that any discourse about the Jedi should be confined to personal discussions. We must focus on toppling the Empire, not reopening old wounds.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 384, 'm48t', 'Alliance Jedi Policy'),
('string/en/mission/mission_deliver_rebel_medium.stf', 385, 'm49d', 'Commander Skywalker has requested that any information regarding Adegan or Ilum crystals be sent directly to him. Could you deliver these instructions to the local cell commander to spread this information to the miners and smugglers working for us? Hope we can count on you. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 386, 'm49l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 387, 'm49o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 388, 'm49r', 'Never heard of these crystals. What are they good for? Lightsabers, you say! Who wants a sword when you could have a blaster?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 389, 'm49f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 390, 'm49s', 'Some of these crystals might belong to certain collectors or former Imperial senators. I hope Master Skywalker gets the information he needs. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 391, 'm49p', 'We believe Commander Skywalker has a keen interest in crystallography. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 392, 'm49t', 'Crystal Questions'),
('string/en/mission/mission_deliver_rebel_medium.stf', 393, 'm50d', 'Commander Solo has requested that we send directly to him any inquiries from bounty hunters regarding his whereabouts. Apparently there is some bad blood between him and Tatooine crimelord Jabba the Hutt. Could you make sure the local cell commanders get this information?  One of the Heroes of Yavin is counting on you.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 394, 'm50l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium.stf', 395, 'm50o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_deliver_rebel_medium.stf', 396, 'm50r', 'Smugglers attract bounty hunters. Is this really a surprise?'),
('string/en/mission/mission_deliver_rebel_medium.stf', 397, 'm50f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium.stf', 398, 'm50s', 'We need to make sure those bounty hunters don''t threaten our security. No doubt it''s just some misunderstanding that can easily be worked out. '),
('string/en/mission/mission_deliver_rebel_medium.stf', 399, 'm50p', 'Despite Commander Solo''s past, he will always be seen as a Hero of the Alliance.'),
('string/en/mission/mission_deliver_rebel_medium.stf', 400, 'm50t', 'Bounty Hunter Alert'),
('string/en/mission/mission_deliver_rebel_medium.stf', 401, 'number_of_entries', '50'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 1, 'm1d', 'A Senator aiding our cause has angered Imperial Intelligence. His family has been targeted for termination. Pick up an encrypted datadisc from one of our slicers. It contains instructions for the Senator and his family. Deliver this disc to a member of the Senator''s staff immediately. We hope we''re not too late to save this patriot''s family.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 2, 'm1l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 3, 'm1o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 4, 'm1f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 5, 'm1r', 'The Senator thanks you and will follow these instructions immediately. Thank you.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 6, 'm1p', 'Here you go, friend. I hope it''s not too late to save the Senator''s family.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 7, 'm1t', 'Rescue a Senatorial Family'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 8, 'm1s', 'Well done, citizen. We will not stand by and watch our patriots executed.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 9, 'm2d', 'One of our strike teams is hitting an Imperial depot in the Outer Rim. We want Imperial Intelligence to suspect we''re hitting a different target. We need a trusted agent to pick up falsified Alliance communiques and deliver them to our HoloNet slicer. We''ll make sure Imperial agents intercept them. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 10, 'm2l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 11, 'm2o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 12, 'm2f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 13, 'm2r', 'I''m on it. I love fooling those Imperial idiots. Don''t you? Haha!'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 14, 'm2p', 'Here are the communiques. Remember you can rarely use the same trick twice against the Empire.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 15, 'm2t', 'Help Fool the Empire'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 16, 'm2s', 'Good work. It''s the efforts of agents like you that will insure the Empire''s defeat.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 17, 'm3d', 'Although a terrible tragedy, the destruction of Alderaan has boosted our ranks. We need someone to pick up a datadisc and deliver it to our processing officer. It contains thousands of enlistees, many of them skilled pilots. This new influx of talent may be what the Alliance needs to turn the tide of battle against the Empire. Will you help? '),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 18, 'm3l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 19, 'm3o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 20, 'm3f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 21, 'm3r', 'Thanks for the delivery. How typical of the Empire not to understand that fear can easily become hate. We shall triumph.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 22, 'm3p', 'The Princess said it best: "The more the Empire tightens its grip, the more star systems will slip through its fingers."'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 23, 'm3t', 'Boost the Alliance''s Ranks'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 24, 'm3s', 'Those extra recruits are much needed. Thanks for your efforts. The Alliance will reward you.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 25, 'm4d', 'We must constantly keep our cells supplied and their agents equipped. We need couriers to pick up supply requests and deliver them to our requisitions officer. These couriers will make sure our brave freedom fighters have what they need to fight the Empire. Will you assist in this important task?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 26, 'm4l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 27, 'm4o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 28, 'm4f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 29, 'm4r', 'Thanks. Fortunately some "procurement specialists" just made it past the blockades, or we might have been in supply trouble.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 30, 'm4p', 'We''re glad to see you. Supplies are running pretty seriously low around here. Please hurry!'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 31, 'm4t', 'Supply Requests'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 32, 'm4s', 'Keeping the Alliance running is an endless task. We appreciate your efforts.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 33, 'm5d', 'Our Incom engineers have provided us with the latest X-wing flight simulator. This will be a great training aid for our new pilots. We need you to pick up a copy of the simulator and deliver it to one of our training officers. Make sure they report bugs to High Command. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 34, 'm5l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 35, 'm5o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 36, 'm5f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 37, 'm5r', 'I hear these are modeled on the TIE flight sims. Our pilots will benefit greatly. Thanks.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 38, 'm5p', 'Ever wanted to fly an X-wing? I think every Alliance member does. Take care of this flight sim.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 39, 'm5t', 'Help train better pilots'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 40, 'm5s', 'All clear, citizen. Good work. The Alliance is grateful.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 41, 'm6d', 'Some of our agents have attempted to enlist with the Empire to spy for the Alliance. We believe Imperial Intelligence has identified a large number of these agents. We need someone to pick up encrypted orders from High Command and deliver them to our local cell contact. They tell local agents how to avoid detection.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 42, 'm6l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 43, 'm6o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 44, 'm6f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 45, 'm6r', 'I''ll get these instructions out to our agents immediately.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 46, 'm6p', 'The orders are on this datadisc. One thing I will say for Imperial Intelligence -- they''re very thorough.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 47, 'm6t', 'Save Alliance Agents'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 48, 'm6s', 'Your efforts will likely save many good agents, friend. Well done!'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 49, 'm7d', 'Ever since the destruction of the Death Star, the number of enlistees has risen dramatically. We suspect that some of these individuals may be double agents working for the Empire. Can you pick up an encrypted roster of suspicious enlistees and deliver them to our High Command contact?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 50, 'm7l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 51, 'm7o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 52, 'm7f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 53, 'm7r', 'Sometimes these double agents are hard to spot. We''ll do our best. Thanks for the information.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 54, 'm7p', 'Here''s the roster. But remember all the times when Imperial double agents denounced the Empire and joined our cause.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 55, 'm7t', 'Stop the Infiltrating Spies'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 56, 'm7s', 'Mission accomplished, for the moment. We must help the Alliance remain free of Imperial spies.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 57, 'm8d', 'Our slicers intercepted a secret Imperial communique revealing that the Empire has dossiers of all the surviving Battle of Yavin pilots. They''ve put a high priority on having these individuals arrested. Mentioned in the communique were Commanders Solo and Skywalker. Someone must pick up this communique and deliver it to our High Command contact. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 58, 'm8l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 59, 'm8o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 60, 'm8f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 61, 'm8r', 'Thanks, citizen. We''ll alert these heroes as soon as possible.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 62, 'm8p', 'Here you go. There''s some juicy stuff in that communique.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 63, 'm8t', 'Help Protect the Heroes of Yavin'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 64, 'm8s', 'Our thanks, citizen. The security of the Heroes of Yavin is one of our top priorities.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 65, 'm9d', 'We''ve discovered a flaw in the design of older stormtrooper helmet comlinks. We need a trusted agent to pick up our technical analysis and deliver it to a local cell contact. We can use this flaw to intercept squad communications. This information will mostly benefit our cells on remote outposts. Think you can handle this mission? '),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 66, 'm9l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 67, 'm9o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 68, 'm9f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 69, 'm9r', 'This should come in handy. I always wondered what stormtroopers chatted about when they were just standing around.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 70, 'm9p', 'Here''s the analysis. We should act quickly, because we don''t know how long this flaw will go unnoticed by the Empire.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 71, 'm9t', 'Eavesdrop on Stormtroopers'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 72, 'm9s', 'Job well done, citizen. The Alliance is glad to have trusted agents like you.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 73, 'm10d', 'Our slicers'' efforts to send bogus orders to Imperial garrisons has been very effective -- in fact, too effective. The Imperials have now taken to hand-delivering their orders, which leaves our slicers vulnerable to Imperial Intelligence. We need someone to pick up a new set of encryption codes and deliver them to our local slicers. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 74, 'm10l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 75, 'm10o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 76, 'm10f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 77, 'm10r', 'Really? I gotta stop? Aww, just when I was having such fun. Okay, I''ll ask the gang to throttle back, and we''ll work with these new codes.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 78, 'm10p', 'Here are the new codes. They should help protect our data slicers. They''re weird, but they''re good folks and we need them.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 79, 'm10t', 'Save the Data Slicers'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 80, 'm10s', 'That should keep Imperial Intelligence guessing for a bit longer. Those goons are certainly dedicated, I''ll give them that. Thanks for your help.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 81, 'm11d', 'The Empire plans on arresting many former Senators and their families. We need someone to pick up the list of possible targets and deliver them to one of our HoloNet slicers so we can warn these targets. The slicer is to provide a list of High Command contacts to anyone fleeing arrest. Can you help us?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 82, 'm11l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 83, 'm11o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 84, 'm11f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 85, 'm11r', 'When I send this warning, the Imperial Analysis Bureau will be riding my tail in about ten seconds flat. You guys needs to move fast to save those -- who is it? Senators? Whoever.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 86, 'm11p', 'Here''s the list. Remember, the more powerful politicians we get on our side, the better off we''ll be.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 87, 'm11t', 'Save the Senators'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 88, 'm11s', 'Your efforts will save many lives, citizen. The Alliance is grateful.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 89, 'm12d', 'The New Order''s stance on alien species has given us an edge in recruiting these neglected citizens. Of special interest to High Command are the Duros. We need a courier to pick up encrypted orders and deliver them to our agent specializing in Alien Species Affairs. The agent is to travel to Duro and continue negotiating with the leaders there.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 90, 'm12l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 91, 'm12o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 92, 'm12f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 93, 'm12r', 'I think the Duros are determined to remain neutral, but I''ll continue negotiating with them.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 94, 'm12p', 'Here are the orders. Many alien species would follow the Duros'' example if they joined the Alliance.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 95, 'm12t', 'Help Rally the Aliens'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 96, 'm12s', 'The Alliance appreciates your efforts. With luck, disenfranchised species will boost our ranks and help us topple the Empire.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 97, 'm13d', 'One of our refueling stations in the Outer Rim has been compromised, and we believe that the Empire is using it as bait to capture Alliance transports. Pick up these encrypted orders and deliver them to our local cell leader. We must insure that every transport captain and pilot aiding the Alliance receives these orders.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 98, 'm13l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 99, 'm13o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 100, 'm13f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 101, 'm13r', 'We''ll get this information out to our pilots at once. Thank you.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 102, 'm13p', 'Here you go. And cheer up. For every station that the Empire discovers, we have ten more they know nothing about.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 103, 'm13t', 'Save the Pilots'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 104, 'm13s', 'Good work. Our pilots are a precious resource, and we must do all we can to protect them.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 105, 'm14d', 'We have proof that an Imperial prison official at Kessel has been supplying glitterstim to smugglers and Black Sun. We need someone to pick up the encrypted evidence and deliver it to one of our couriers. We intend to present our "terms" to the Imperial official. He''ll either cooperate with us or we turn over our proof to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 106, 'm14l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 107, 'm14o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 108, 'm14f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 109, 'm14r', 'Good old-fashioned blackmail, eh? Hey, if it''s effective --'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 110, 'm14p', 'Here''s the data. Remember, we do what we must to insure the fall of the Empire. In this case, it''ll be fun!'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 111, 'm14t', 'Blackmail a Kessel Official'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 112, 'm14s', 'Well done. Remember to keep this quiet. We don''t want word getting around to Imperial Intelligence.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 113, 'm15d', 'We''ve received a request from Commander Skywalker. He''d like us to get our hands on an Imperial Inquisitor. We need someone to pick up his encrypted orders and deliver them to our local cell commander. All commanders are to coordinate with High Command to help achieve this top-priority mission. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 114, 'm15l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 115, 'm15o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 116, 'm15f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 117, 'm15r', 'With pleasure! I''ve been wanting to take down one of these mighty Inquisitors ever since I heard of them.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 118, 'm15p', 'The orders are on this datadisc. I imagine we can learn a great deal from an Inquisitor. Good luck.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 119, 'm15t', 'Nab an Imperial Inquisitor'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 120, 'm15s', 'That was well done. With any luck, we''ll be able to supply Commander Skywalker with an Inquisitor soon. I wonder what he has in mind?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 121, 'm16d', 'A shipment of Merr-Sonn IR-5 "Intimidator" blaster pistols has fallen into our hands. We need someone to pick up inventory discs and deliver them to our local cell commanders. They can request these weapons for upcoming missions, especially any dealing with smugglers and pirates -- those types are easily intimidated. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 122, 'm16l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 123, 'm16o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 124, 'm16f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 125, 'm16r', 'I''ve seen those blasters. Effective weapons indeed. I''ll look through this inventory carefully.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 126, 'm16p', 'Here you go. And remind the commanders that these weapons not only look intimidating, they also pack quite a punch.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 127, 'm16t', 'Disperse Intimidators'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 128, 'm16s', 'Excellent, citizen. These weapons will help our undercover agents deal with those unpredictable smugglers.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 129, 'm17d', 'A generous sympathizer has donated several new MD-series medical droids. Could you pick up the specs for these droids and deliver them to our local cell commander? All requests for these droid must go through Winter, who will process them directly. Make sure the commanders make a strong case, or they may not get one.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 130, 'm17l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 131, 'm17o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 132, 'm17f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 133, 'm17r', 'My people sure could use one of those droids. I''ll make a no-frills request at once. I hear Winter is fond of brevity. '),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 134, 'm17p', 'Make sure the commander gets this. These donations keep the Alliance strong.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 135, 'm17t', 'Medical Droids for Everybody'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 136, 'm17s', 'It''s a shame there were only five droids to be had. We could have used many more. But we''re grateful, regardless -- and on that note, thanks for your help.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 137, 'm18d', 'We found some old Trade Federation droidekas. These might be useful on certain missions or as security droids on some of our bases. Could you pick up this encrypted message and deliver it to our contact at High Command? We need instructions on how to proceed. Winter will hold these units until she receives those instructions.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 138, 'm18l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 139, 'm18o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 140, 'm18f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 141, 'm18r', 'Weren''t those things awfully unreliable? I always heard that''s why the Trade Federation stopped using them. Well, I''ll pass this along.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 142, 'm18p', 'Here you go. Inform High Command that the droidekas seem to be in perfect condition. I don''t believe they were ever activated.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 143, 'm18t', 'A Blast From the Past'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 144, 'm18s', 'We appreciate your help, citizen. Meanwhile, we''re looking into the source of those perfectly preserved droidekas. Could be more where those came from.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 145, 'm19d', 'Procurement and Supply recently sent us a message asking for further instructions on the matter of some droidekas. I need you to pick up High Command''s response and deliver it to our P&S contacts so they can forward it to Winter. Do this quickly and we''ll reward you accordingly.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 146, 'm19l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 147, 'm19o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 148, 'm19f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 149, 'm19r', 'Thanks, citizen. We''ll see what the bosses have to say, I suppose.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 150, 'm19p', 'Here you are. Any tool is only as effective as our ability to control and use it properly.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 151, 'm19t', 'Dealing With Obsolete Droids'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 152, 'm19s', 'That was a prompt delivery, citizen. Your fee has been deposited.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 153, 'm20d', 'We need to get a shipment of laser cutters to a secret facility in the Outer Rim. We need you to pick up encrypted orders and deliver them to one of our transport pilots. This is a most important mission. Can we count on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 154, 'm20l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 155, 'm20o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 156, 'm20f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 157, 'm20r', 'The Empire hasn''t found us yet. So I guess it''s worth it -- all these hoops they make us jump through for the sake of secrecy.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 158, 'm20p', 'Here are the orders. The pilot must report to High Command before leaving the local system. High Command will give the pilot the location of the laser cutters as well as the coordinates of the secret facility.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 159, 'm20t', 'Help Carve a New Rebel Base'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 160, 'm20s', 'It''s difficult transporting all this equipment while maintaining secrecy. We''re glad to know we can count on you. Well done.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 161, 'm21d', 'We''ve learned that a Moff is spearheading an attempt to assassinate the Emperor. Pick up this encrypted message and deliver it to one of the Moff''s agents. It informs the Moff that the Alliance will assist in whatever way it can and gives security codes if the Moff wishes to contact High Command. Can you help us?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 162, 'm21l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 163, 'm21o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 164, 'm21f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 165, 'm21r', 'I''ll see to it that the Moff receives this. '),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 166, 'm21p', 'Moffs can strike at the heart of the Imperial Machine. We should never waste an opportunity like this. Be careful delivering this disc.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 167, 'm21t', 'Aid a Plot Against the Emperor'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 168, 'm21s', 'Well done, citizen. If this Moff''s plan succeeds, this war will be over and the galaxy will be free again.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 169, 'm22d', 'We believe that the Empire is preparing to strike Mon Calamari. Please pick up these intercepted transmissions and deliver them to our Mon Calamari contact who will have them sent to Admiral Ackbar immediately. If we act fast, we can save millions of Mon Calamari lives. Can we rely on you?'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 170, 'm22l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 171, 'm22o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 172, 'm22f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 173, 'm22r', 'May the Force be with us! I''ll leave at once!'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 174, 'm22p', 'The Mon Calamari are vital to the success of the Alliance. We must save them!'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 175, 'm22t', 'Save the Mon Calamari'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 176, 'm22s', 'We can only hope that we were fast enough. Thank you for your efforts, agent.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 177, 'm23d', 'Imperial Intelligence has instructed their agents to travel to the Circarpous system. We don''t know if they''ve learned of our secret dealings with Circarpousian financiers. We need you to pick up a message and deliver it to one of Princess Leia''s aides. We hope this doesn''t jeopardize her plans to meet with the Circarpousians.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 178, 'm23l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 179, 'm23o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 180, 'm23f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 181, 'm23r', 'The Princess will want to go anyway, but I''ll warn her. She''s stubborn, you know.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 182, 'm23p', 'It seems that the Empire is always one step ahead of us. This must change.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 183, 'm23t', 'Warn the Princess'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 184, 'm23s', 'Excellent work, citizen. I hope the Princess takes this warning to heart. Sometimes she''s too brave for her own good.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 185, 'm24d', 'Our agents have discovered that four Imperial Star Destroyers will be in orbital dock at the same time. We intend to strike the dock and destroy the Imperial ships. Could you pick up an encrypted datadisc and deliver it to the strike team commander? It will reveal the location of the dock and list the Alliance pilots that will participate in the mission.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 186, 'm24l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 187, 'm24o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 188, 'm24f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 189, 'm24r', 'If this strike succeeds, it would be a great victory for the Alliance.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 190, 'm24p', 'Deliver this fast. We''ll destroy these capital ships faster than the Empire can build them.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 191, 'm24t', 'Four Star Destroyers at Once'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 192, 'm24s', 'Well done, citizen. Your service to the Alliance is being noted.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 193, 'm25d', 'One of our colonies has been discovered by Imperial Intelligence. Many of our leaders'' families are on this colony. We need you to pick up an evacuation order and deliver it to one of our pilots familiar with the colony so we can begin the evacuation. We dare not communicate via the HoloNet for fear of escalating the Imperial attack. Please hurry!'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 194, 'm25l', 'Datadisc'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 195, 'm25o', ''),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 196, 'm25f', 'mission\\mission_datadisk.iff'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 197, 'm25r', 'We''ll have those families off that colony in no time. Never fear.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 198, 'm25p', 'Be quick with this delivery. Until the Empire is toppled, we must remain on the move.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 199, 'm25t', 'Help Evacuate a Colony'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 200, 'm25s', 'Good work. Let''s hope we acted in time to save all those people.'),
('string/en/mission/mission_deliver_rebel_medium_non_persistent_from_npc.stf', 201, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 1, 'm1d', 'Our probe droids have located a fairly sizable Rebel munitions depot. Taking this supply cache out would no doubt limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended (it is a weapons depot, after all). Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 2, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 3, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 4, 'm1t', 'Make a Munitions Depot Go Boom'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 6, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 7, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 8, 'm2t', 'Smash Rebel Mining Operation'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 9, 'm3d', 'Imperial Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 10, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the Empire. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 11, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 12, 'm3t', 'Disrupt Rebel Communications'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 13, 'm4d', 'What we thought was a legitimate medical facility has turned out to be a Rebel medical supply depot. It seems they''ve been using sick citizens as cover, trying to get us to believe they were operating according to Imperial laws. We feel for these sick individuals, although no doubt many of them are Rebel sympathizers, but this facility must be destroyed.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 14, 'm4s', 'Bacta is wasted on Rebel scum, do not worry. You have done very well and we are highly pleased. Our missions require someone with a strong constitution. You should seek us out in the future.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 15, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 16, 'm4t', 'Blast Medical Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 17, 'm5d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility in the name of Imperial justice. '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 18, 'm5s', 'Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 19, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 20, 'm5t', 'Neutralize Rebel Refugees'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 21, 'm6d', 'Thanks to the efforts of our many loyal civilian informants, we''ve managed to verify the existence of a Rebel transport repair facility. We kept wondering where those Rebels would take their vehicles when they needed repairs. After all, many of them bear the evidence of skirmishes with local civil authorities or Imperial forces. We''d like this installation eliminated.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 22, 'm6s', 'I suppose the Rebels will have to carry their supplies on their backs now. Job well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 23, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 24, 'm6t', 'Interrupt Rebel Vehicle Repairs'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 25, 'm7d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain safe from such atrocities and loyal to the Empire. '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 26, 'm7s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 27, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 28, 'm7t', 'Stop Rebel Indoctrinations'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 29, 'm8d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. Can you burn this installation to the ground? These terrorists must pay for their terrible acts of violence against the Empire.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 30, 'm8s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 31, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 32, 'm8t', 'Remove Rebel Terrorist Cell'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 33, 'm9d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost of some sort. However, our surveillance images clearly show known Rebels patrolling the facility''s perimeter. We need a trusted agent to lead a strike against this installation and insure its destruction. Is that you?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 34, 'm9s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 35, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 36, 'm9t', 'Destroy Rebel Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 37, 'm10d', 'Rather than being horrified by the Rebellion''s deadly sabotage of the Empire''s most brilliant and effective weapon against injustice, it seems instead that this terrorist act has encouraged some malcontents to form their own Rebel cell. We need a loyal citizen of the Empire to show these troublemakers the consequences of throwing their lot in with traitors and terrorists. Are you that citizen?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 38, 'm10s', 'A success like this deserves to be celebrated. You must share your victory with your closest friends. If any of them do not seem delighted as we are, give us their name and identification number. You can never be too sure.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 39, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 40, 'm10t', 'Attack Traitorous Malcontents'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 41, 'm11d', 'One of Sienar Fleet System''s chief engineers has foolishly decided to join the ranks of those traitorous Rebels. We''ve located this engineer and need them silenced before they can supply the Rebellion with technical specs. We believe the traitor is being held at a small warehouse currently used to store speeder parts. Can the Empire rely on you to accomplish this mission?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 42, 'm11s', 'Well done, agent. We hope that engineer was inside that warehouse when it was destroyed, and we hope the Rebellion learned no damaging Imperial secrets.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 43, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 44, 'm11t', 'Silence the Traitorous Engineer'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 45, 'm12d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots access to. Unfortunately, this is often enough to get some of these naive flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 46, 'm12s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 47, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 48, 'm12t', 'Remove Rebel Training Station'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 49, 'm13d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 50, 'm13s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 51, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 52, 'm13t', 'Remove Data Slicer'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 53, 'm14d', 'Agents within the CSA have informed Imperial Intelligence that many of the workers the Viceprexes had requested for hard labor are being transferred to a holding facility where Rebel agents can rescue convicted spies and sympathizers contained among the roster. We''ve acquired the coordinates of this facility and need a small team of loyal Imperial agents to obliterate it.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 54, 'm14s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 55, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 56, 'm14t', 'Blast Rebel Holding Facility'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 57, 'm15d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents. Can the Empire count on you?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 58, 'm15s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 59, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 60, 'm15t', 'Break Rebel Weapons'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 61, 'm16d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 62, 'm16s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 63, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 64, 'm16t', 'Deprive Rebels of Medical Care'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 65, 'm17d', 'The Rebels have managed to get their hands on some old Trade Federation destroyer droids. These units can be used to fortify their outposts and defend their bases. Fortunately, our informants have tracked these droids down and have provided us with the coordinates to the warehouse that is being used to store them. An Imperial strike team is needed to take these droidekas out of commission.  '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 66, 'm17s', 'A job well done, agent. The Empire will show its appreciation via this reward. Do come see us again for future missions.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 67, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 68, 'm17t', 'Destroy Destroyer Droids'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 69, 'm18d', 'Rebel infiltrators have been stealing laser cutters from Imperial depots. We believe they are building a new base of operations at a secret location. Our tracking beacons indicate the cutters'' location. We need you and your loyal Imperial fellows to strike the Rebel cache and blow it to atoms. Will you help your Empire?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 70, 'm18s', 'Ah, this would doubtless slow the Rebels'' efforts to carve new lairs. You''ve earned this reward!'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 71, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 72, 'm18t', 'Laser Cutter Cache'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 73, 'm19d', 'We believe we have identified the meeting site of a traitorous Moff who is plotting with Rebels to assassinate our beloved Emperor. We require an able Imperial strike team to hit this outpost and kill everyone present. Will you take this vital assignment?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 74, 'm19s', 'We can only hope that when you destroyed that outpost, the Moff was present. We''ll monitor communications to make sure. For your well-executed strike, you have earned this reward.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 75, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 76, 'm19t', 'Traitorous Moff Plots Assassination'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 77, 'm20d', 'The Rebellion is disguising LIN Demolitionmech droids to look like simple R3 units. They are striking at Imperial garrisons with these "miner bombs." We have located a Rebel depot full of mining equipment and explosives, and we require you to destroy it. Reduce all equipment to slag. Can you aid the Empire?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 78, 'm20s', 'An effective piece of work, agent. The Empire is proud. Claim your reward, and seek us out again for more work.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 79, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 80, 'm20t', 'Rebel Demolitionmech Depot'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 81, 'm21d', 'Recent Rebel attacks have used modified A-A5 speeder trucks as armored personnel carriers. We want you to destroy the repair facility used to create these carriers. Will you assist the Empire in removing this threat?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 82, 'm21s', 'Those speeder trucks are common, and the needed military modifications are unfortunately well understood. So you may expect further assignments of this type soon.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 83, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 84, 'm21t', 'A-A5 Speeder Truck Repair Facility'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 85, 'm22d', 'The Rebellion has obtained stolen R3 units, intended for Imperial cruisers, and is reprogramming them for its own use. We have located a depot holding many stolen R3s, but the droids are useless to us now because they may contain bugging devices. We wish you to destroy the depot, thus keeping the droids out of the hands of our enemies.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 86, 'm22s', 'Pity to see good droids go to waste, but there are always more droids. As for the Rebels -- soon there will be very few of those. Your reward is well earned.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 87, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 88, 'm22t', 'Stolen R3 Droid Depot'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 89, 'm23d', 'Intelligence informs us that Rebel supply caches of certain rare Outer Rim crystals are to be immediately destroyed. We''ve located a warehouse containing a large quantity of these crystals. You are to vaporize these minerals for us at once. Can the Empire count on your aid?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 90, 'm23s', 'The Rebels apparently are using these crystals to fashion some fiendish new weapon. We can only hope your success retards their progress. Well done.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 91, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 92, 'm23t', 'Warehouse of Rare Crystals'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 93, 'm24d', 'The Empire has engineered an airborne virus for deployment at anti-Imperial demonstrations in the Core Worlds. Rebels have analyzed the virus and created a retroviral vaccine. We have located a production run of the vaccine in a small medical depot. We wish it destroyed -- all of it. Will you assist us in this matter?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 94, 'm24s', 'Our viral plans should meet with better success now. Well done, citizen. The Empire will not forget your work.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 95, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 96, 'm24t', 'Retrovirus Vaccine Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 97, 'm25d', 'The Rebels are stockpiling climate control units, undoubtedly for use in remote bases in the Outer Rim. We want these units destroyed. You, being a loyal Imperial agent, would certainly be willing to take care of this, correct?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 98, 'm25s', 'We didn''t expect climate control units to present much threat. But we appreciate your clean and efficient attack. Well done!'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 99, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 100, 'm25t', 'Climate Control Unit Storage Facility'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 101, 'm26d', 'Rebel leaders are meeting with officials of the Bounty Hunters'' Guild, apparently to offer concocted "proof" that the Empire has attacked the Guild. We must stop this dangerous nonsense. Here are the coordinates of the secret meeting location. Go there and destroy everything and everyone you see. Do not mention the Empire, of course.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 102, 'm26s', 'Dead Rebels, and dead bounty hunters, tell no tales. Bravo, citizen. You are shaping up into a highly professional agent.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 103, 'm26o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 104, 'm26t', 'Meeting of Rebels and Bounty Hunters'' Guild'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 105, 'm27d', 'Rebels have taken over a speeder shop. They are apparently coercing its mechanics to adapt prototype speeders for operation in harsh climatic conditions. We would like you to stop this terrorist activity before it erupts into a full hostage situation. The hostages are presumed corrupted by now and can be safely killed with the rest.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 106, 'm27s', 'A job well done. Now we must try to discern what the Rebellion planned to do with those speeders. But that is a task for another day, citizen.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 107, 'm27o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 108, 'm27t', 'Speeder Garage Taken by Rebels'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 109, 'm28d', 'We have found a refueling depot used by the Rebel-friendly smugglers they quaintly call "procurement specialists." Because the military is preoccupied tracking down actual Rebel bases, we wish you to destroy this depot, quickly and thoroughly. Leave no survivors. Can you do this?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 110, 'm28s', 'Smugglers are not just a problem for the local authorities. They aid the Rebels and are therefore our problem as well. We are glad we can rely on you in such matters.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 111, 'm28o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 112, 'm28t', 'Smuggler Refueling Depot'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 113, 'm29d', 'We have uncovered a cache of vacuum gyros intended for Rebel transports. Unfortunately, the Rebels destroyed our probot and now know of our discovery. A Rebel contingent is evacuating the cache. We need you to destroy the contraband, and the Rebels, before it is too late. Move quickly!'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 114, 'm29s', 'Vacuum gyros allow Gallifree transports to slip through our blockades. Your good work will help us stop them more effectively. Well done!'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 115, 'm29o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 116, 'm29t', 'Vacuum Gyro Cache'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 117, 'm30d', 'We have found an encoding array the Rebellion uses to retransmit secret communiques. We require you to smash this installation and thereby cripple their information network. Expect well-armed opposition. If you succeed, the Empire will of course provide generous compensation.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 118, 'm30s', 'Already we have seen reduced numbers of encoded Rebel transmissions, because of your good work. Take this payment with our best respects.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 119, 'm30o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 120, 'm30t', 'Rebel Encoding Station'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 121, 'm31d', 'A new Rebel outpost has received a load of Defender-class space mine housings. We believe the Rebel terrorists plan to insert gravity-manipulation weapons into these casings, which would jeopardize routine hyperspace transits. We require you to wipe out this factory before it can unleash its deadly contraband.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 122, 'm31s', 'Our navigators can breathe more easily now. You have made the star lanes safe once more. '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 123, 'm31o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 124, 'm31t', 'Defender Gravity Mine Housings'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 125, 'm32d', 'The Rebels have set up another hyperspace monitoring terminal to track the movement of our capital ships. We need a ground-based agent to assault this station and shut it down. Expect heavy opposition, but be assured this mission is vital to our proud Imperial Navy!'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 126, 'm32s', 'Imperial Intelligence will begin sifting through the remains of the terminal shortly, assuming you left any remains. Accept this payment for your success.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 127, 'm32o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 128, 'm32t', 'Hyperspace Monitoring Terminal'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 129, 'm33d', 'Rebels have hijacked rations bound for Imperial garrisons. They have taken the stolen food to a local distribution center, where they use the contraband to bribe local settlers under the pretense of "famine relief." We require you to destroy this distribution center and stop this treachery before it spreads. At once!'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 130, 'm33s', 'You have spared local citizens the indignity of consuming stolen food. Take your reward with honor.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 131, 'm33o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 132, 'm33t', 'Hijacked Imperial Rations'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 133, 'm34d', 'Recently our field operatives wiped out a Rebel command center using an exciting new airborne biological agent. A group of survivors fled to a small "safe house," carrying several corpses. Our scientists have deemed it prudent to destroy these bodies in the interest of public health. You must blast the entire structure; we shall observe from a safe distance.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 134, 'm34s', 'Excellent. Use this reward to relocate well away from populated areas, and avoid bodily contact with any soldier of the Empire. You may go now. Quickly!'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 135, 'm34o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 136, 'm34t', 'Eliminate Contaminated Bodies'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 137, 'm35d', 'Recently the Rebellion provoked the untimely destruction of Alderaan. Properly reviled for this heinous crime, the Rebels have sought public sympathy by breeding many of Alderaan''s native fauna. Loyal citizens of the Empire know that this program is nothing but a transparent act of propaganda. Luckily we have located the center of this traitorous enterprise. Remove it.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 138, 'm35s', 'While the beautiful woolly moth of Alderaan may have looked harmless, it was a vicious threat to galactic security. You have advanced the cause of Imperial truth.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 139, 'm35o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 140, 'm35t', 'Burn Rebel Propaganda'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 141, 'm36d', 'Some Imperial agents are in Rebel custody and currently imprisoned in a small but well-guarded holding facility. The Rebels will be on the lookout for uniformed soldiers, so we require some highly-trained civilians to launch a surprise assault on the holding facility and reduce it to rubble. We must assume that the captured agents are dead. Can you help us?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 142, 'm36s', 'We''re pleased that the captured agents have been liquidated. You have earned the undying respect and loyalty of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 143, 'm36o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 144, 'm36t', 'Eliminate Captured Agents'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 145, 'm37d', 'The Rebels have launched an insidious scheme to undermine the security of an orderly world. As you know, Imperial engineers have enhanced the water supply of many communities with placidity enzymes to abate civic unrest. The Rebels have captured a local water junction and installed a Creel manifold to siphon off the additives. We need you to blast this junction into oblivion.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 146, 'm37s', 'The Empire is lucky to have such skilled operatives. Rest assured that the community''s water supply will be fully restored within a few months.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 147, 'm37o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 148, 'm37t', 'Help Purify the Water Supply'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 149, 'm38d', 'For thirty years I languished in the Glythe sector as a remote field operative of the ISB. Now, at the end of my career, I have been transferred to a more civilized system with a chance to make a real impact. To this end I am sending a strike team to take out a suspected Rebel grease refinery. I require well-trained operatives who are not afraid to get their hands dirty.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 150, 'm38s', 'At last I have achieved true success! My grandchildren will thank you for saving a man''s reputation. Take your payment and enjoy it.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 151, 'm38o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 152, 'm38t', 'Strike a Rebel Refinery'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 153, 'm39d', 'We''ve pinpointed a cloister of fuselage engineers who are aiding the Rebels in their fighter designs. We are commissioning a team of investigators to search these coordinates and eliminate any operations they find. Watch out for surprises and make sure to wipe out any research materials they have gathered.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 154, 'm39s', 'I understand those engineers were tougher than they looked. Or perhaps you are not as competant as you portray yourself. At least you completed the mission.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 155, 'm39o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 156, 'm39t', 'Smash the Cloister of Engineers'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 157, 'm40d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was highjacked en route to a Civil Security Center on Dantooine. We have intercepted Rebel messages that suggest these droids were smuggled to a secret reprogramming facility. A squad of operatives must travel to these coordinates and eradicate the facility immediately.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 158, 'm40s', 'The Empire is grateful for your service. IG assassin droids are expensive. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 159, 'm40o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 160, 'm40t', 'Blast Droid Reprogramming Facility'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 161, 'm41d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, though, the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 162, 'm41s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 163, 'm41o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 164, 'm41t', 'Disable the X-wings'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 165, 'm42d', 'The Rebels have stolen the plans for a new Imperial void station and hidden them inside an innocuous MSE-6 droid. We learned that it got aboard a smuggler''s freighter and landed at these coordinates. We require a strike team to pinpoint the Rebel outpost and smash it to rubble. Imperial Intelligence will inspect the site to retrieve what remains of the offending MSE-6.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 166, 'm42s', 'Excellent work. There''s no way a mouse droid could have escaped your assault. You have served the Empire well.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 167, 'm42o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 168, 'm42t', 'Find a MSE-6 Droid'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 169, 'm43d', 'Our informants have alerted us that a local pharmaceutical shop is doubling as an underground clinic for Rebel agents. We must make sure that these traitors do not have access to medical care. We understand that there are no less than two bacta tanks in operation at this facility. All of this equipment must be destroyed. Are you the Imperial agent we''re looking for? '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 170, 'm43s', 'Good work! Now we will be able to better trace Rebel agents when they are forced to use local medical clinics. The reward is yours. '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 171, 'm43o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 172, 'm43t', 'Destroy Rebel Medical Clinic'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 173, 'm44d', 'A storage facility housing some outdated communications equipment and refurbished power generators is being used by the local Rebel cell to help supply their members. This equipment had been scheduled to be transported to Imperial junkyards for salvage but it seems the Rebellion got their hands on it first. Make sure this junk is not used to help the Rebellion. '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 174, 'm44s', 'You handled that well, citizen. It makes sense that garbage would attract garbage. You''re an efficient disposal agent.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 175, 'm44o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 176, 'm44t', 'Take Out Parts Warehouse'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 177, 'm45d', 'It has come to our attention that a local livestock dealer harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. As you may know, certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 178, 'm45s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 179, 'm45o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 180, 'm45t', 'Crush the Mynock Incubators'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 181, 'm46d', 'A local community has recently been plagued by a fake recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility at these coordinates. We want you to take a strike team and decimate this unseemly operation. In particular, make certain that all of these fake recording are utterly destroyed.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 182, 'm46s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 183, 'm46o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 184, 'm46t', 'Raze a Seditious Broadcast Facility'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 185, 'm47d', 'In the midst of an otherwise obedient community, the Rebels have constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 186, 'm47s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return.  '),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 187, 'm47o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 188, 'm47t', 'Blast a Rebel Power Relay'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 189, 'm48d', 'They want us to believe they are mere gangsters, but we have discovered that the Ravvo clan are in fact agents of the Rebel Alliance. These creeps have a barracks, at these coordinates, where they practice their marksmanship to the detriment of the Empire. A well-armed assault will teach them that scoffing Imperial authority is a game for fools and dead men.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 190, 'm48s', 'It''s astounding that so many fools refuse to acknowledge the irresistable might of the Empire. You have shown them the error of their ways.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 191, 'm48o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 192, 'm48t', 'Level a Den of Rebel Sympathizers'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 193, 'm49d', 'The Rebellion is spreading rumors that Jedi have returned and have joined the traitorous scum against the Empire. We have seen holograph displays depicting a lightsaber and bearing the ridiculous slogan "The Jedi have returned! Long live the Republic!" We''ve located a warehouse filled with this sort of propaganda and it must bed destroyed.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 194, 'm49s', 'A job well done, citizen. The Jedi have not returned and the Rebellion is doomed. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 195, 'm49o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 196, 'm49t', 'Smash Rebel Propaganda'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 197, 'm50d', 'The Rebellion has been distributing copies of a fabricated hologram showing the destruction of Alderaan by the Empire''s peacekeeping station, the Death Star. We know Alderaan brought about its own destruction when the "peaceful" planet fired an experimental doomsday weapon at the Death Star. Help us destroy these seditious hologram duplication centers.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 198, 'm50s', 'Lies have gone up in smoke, citizen. Job well done! Your work will further the cause of the New Order and serve to glorify the Empire.'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 199, 'm50o', ''),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 200, 'm50t', 'Destroy Hologram Duplication Center'),
('string/en/mission/mission_destroy_imperial_military_easy.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 1, 'm1d', 'Our probe droids have located a sizable Rebel munitions depot. Taking out this supply cache would limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended. Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 3, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 4, 'm1t', 'Destroy Rebel munitions depot'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 7, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 8, 'm2t', 'Destroy Rebel mining facility'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 9, 'm3d', 'Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 11, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the ISB. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 12, 'm3t', 'Destroy Rebel communications array'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 13, 'm4d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility. '),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 15, 'm4s', 'You can run but you can''t hide! Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 16, 'm4t', 'Destroy Rebel alien refugee outpost'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain loyal to the Empire. Can you help your Emperor stamp out this loathsome practice? '),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 19, 'm5s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. Losing your faith in the New Order is bad enough, but to lose your mind along with it? You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 20, 'm5t', 'Destroy Rebel indoctrination camp'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. We require a loyal citizen of the Empire to burn this installation to the ground. Are you the agent we''re looking for?'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 22, 'm6o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 23, 'm6s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen. We hope this is a definite indication of things to come.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 24, 'm6t', 'Destroy Rebel terrorist cell'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 25, 'm7d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost. We need a trusted agent to lead a strike against this installation and insure its destruction. There''s no telling how many cells this depot has been supplying or how many Imperial lives have been lost as a result.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 27, 'm7s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 28, 'm7t', 'Destroy Rebel supply depot'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 29, 'm8d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their traitorous cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots to play around with. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 31, 'm8s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous indeed. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 32, 'm8t', 'Destroy Rebel training station'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 33, 'm9d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 35, 'm9s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 36, 'm9t', 'Destroy Rebel slicer hub'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 37, 'm10d', 'Agents within the CSA have informed Intelligence that many of the workers the Viceprexes are requesting for hard labor are being transferred to a holding facility so that Rebel agents can rescue convicted Rebel spies and sympathizers contained among the roster. We need a small team of loyal Imperial agents to obliterate this facility. The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 39, 'm10s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 40, 'm10t', 'Blast Rebel refugee facility'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 41, 'm11d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 43, 'm11s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 44, 'm11t', 'Destroy Rebel weapons cache'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 45, 'm12d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 47, 'm12s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 48, 'm12t', 'Destroy Rebel medical droids'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 49, 'm13d', 'The Rebels have been targeting Imperial depots containing laser cutters. We believe they need them to build a new operational base although we do not yet know its location. Our agents have managed, however, to locate some of these laser cutters and have sent us the coordinates where they are being housed. We need a few loyal Imperial agents to strike this storage depot.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 51, 'm13s', 'Success! This will doubtless slow the Rebels'' efforts to carve out new lairs. You''ve earned your reward, agent.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 52, 'm13t', 'No more Rebel bases'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 53, 'm14d', 'A traitorous moff has offered to aid the Rebels attempt to assassinate our beloved Emperor. We''ve pinpointed where this traitor and his agents will be meeting with the Rebellion''s agents to make the arrangements. We require an able and loyal Imperial strike team to hit this outpost and insure its destruction. Could you assemble and lead such a team?'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 55, 'm14s', 'We have not ascertained if the moff was at that meeting when you destroyed the outpost. We''ll have to continue monitoring communications. In any case, your strike against that Rebel outpost was superb.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 56, 'm14t', 'Hunt a traitorous moff'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 57, 'm15d', 'Local garrisons have reported recent Rebel attacks that have employed modified A-A5 speeder trucks as armored personnel carriers. We''ve located several civilian speeder repair facilities that could be used to create these carriers. We want these installations destroyed. Can you assist the Empire in removing this potential threat? '),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 59, 'm15s', 'Good work, agent. We knew these stations were serving those Rebel scum and you''ve helped prove it. We hope this is the beginning of a very profitable career for you.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 60, 'm15t', 'Take out Rebel repair stations'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 61, 'm16d', 'The Rebels have taken an interest in certain rare types of crystals. Intelligence has instructed us to destroy any supply depot containing caches of such minerals. We''ve located a small warehouse containing a large quantity of mineral desposits mined from the Outer Rim. We need loyal Imperial servants to vaporize this warehouse.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 63, 'm16s', 'An efficient handling of the mission, agent. Well done. The Empire is proud to reward you.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 64, 'm16t', 'Smash the mysterious crystals'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 65, 'm17d', 'We''ve been alerted to the presence of a Rebel supply depot that seems to be housing hundreds of climate control units. No doubt these are intended for remote Rebel bases in the Outer Rim. We want these units destroyed and figure a loyal and skilled Imperial agent ought to be able to take care of that for us. No need to call in a full military strike.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 67, 'm17s', 'Clean and efficient, citizen, just like we like it. COMPNOR could use more agents like you. '),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 68, 'm17t', 'Make it cold for the Rebels'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 69, 'm18d', 'We finally identified the traitor who has been supplying vacuum gyros for Rebel transports. We have the coordinates to the traitor''s secret gyro cache. Unfortunately he knows we are coming. Our sources tell us that a contingent of Rebel soldiers is evacuating the cache. We need to dispatch a team to destroy this contraband before the Rebels take it away.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 71, 'm18s', 'Well done, citizen. Those Gallifree transports slip through our blockades too easily. Perhaps now we can stop those Rebel scum.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 72, 'm18t', 'Cripple Rebel transports'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 73, 'm19d', 'Ion space mines are an important tool of the Imperial Navy, but in the hands of Rebel terrorists they become a menace to all law-abiding spacefarers. We have tracked a freighter to a known Rebel outpost, where it deposited a load of Defender-class mines. If we can wipe out this factory before its deadly contraband is unleashed, the star lanes will be safe once more.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 75, 'm19s', 'The Imperial Navy is indebted to you. Accept this payment and the gratitude of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 76, 'm19t', 'Take out the space mines'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 77, 'm20d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was highjacked en route to a Civil Security Center on Dantooine. Intercepted Rebel transmissions suggest these droids were smuggled to a secret reprogramming facility, where technicians will turn the IGs into gardening and botanical droids. A squad must locate and destroy this facility.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 79, 'm20s', 'The Empire is grateful for your service. IG assassin droids make lousy botanical arrangements. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 80, 'm20t', 'Assassin droids do not pick posies'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 81, 'm21d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, as the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 83, 'm21s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 84, 'm21t', 'Smash a squad of X-wing fighters'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 85, 'm22d', 'We''ve discovered a local livestock dealer who harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. Certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 87, 'm22s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 88, 'm22t', 'Crush a mynock incubator'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 89, 'm23d', 'A local community has recently been plagued by a fake holovid recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility. You must take a strike team and decimate this unseemly operation. These untruths will not soil the tranquility of our loyal and obedient communities.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 91, 'm23s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 92, 'm23t', 'Raze a seditious broadcast facility'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 93, 'm24d', 'In the midst of an otherwise obedient community, the Rebellion has constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 95, 'm24s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return. '),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 96, 'm24t', 'Blast a Rebel power relay'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 97, 'm25d', 'The Inquisitorius has ordered a strike on a Rebel outpost that has been conducting unusual experiments involving the Force and Force-users. We cannot imagine that the Rebellion would be foolish enough to attempt to establish another Jedi training academy, especially in light of the corruption that was revealed within the ranks of the old Jedi Order. Can you assemble a strike team to take care of this?'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 99, 'm25s', 'A new breed of Jedi shall not rise to threaten our beloved Empire thanks to you, agent. Well done! The Emperor will hear of your success. Be proud.'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 100, 'm25t', 'Destroy Rebel training outpost'),
('string/en/mission/mission_destroy_imperial_military_easy_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 1, 'm1d', 'Our probe droids have located a fairly sizable Rebel munitions depot. Taking this supply cache out would no doubt limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended (it is a weapons depot, after all). Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 2, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 3, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 4, 'm1t', 'Make a Munitions Depot Go Boom'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 6, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 7, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 8, 'm2t', 'Smash Rebel Mining Operation'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 9, 'm3d', 'Imperial Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 10, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the Empire. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 11, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 12, 'm3t', 'Disrupt Rebel Communications'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 13, 'm4d', 'What we thought was a legitimate medical facility has turned out to be a Rebel medical supply depot. It seems they''ve been using sick citizens as cover, trying to get us to believe they were operating according to Imperial laws. We feel for these sick individuals, although no doubt many of them are Rebel sympathizers, but this facility must be destroyed.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 14, 'm4s', 'Bacta is wasted on Rebel scum, do not worry. You have done very well and we are highly pleased. Our missions require someone with a strong constitution. You should seek us out in the future.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 15, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 16, 'm4t', 'Blast Medical Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 17, 'm5d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility in the name of Imperial justice. '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 18, 'm5s', 'Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 19, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 20, 'm5t', 'Neutralize Rebel Refugees'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 21, 'm6d', 'Thanks to the efforts of our many loyal civilian informants, we''ve managed to verify the existence of a Rebel transport repair facility. We kept wondering where those Rebels would take their vehicles when they needed repairs. After all, many of them bear the evidence of skirmishes with local civil authorities or Imperial forces. We''d like this installation eliminated.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 22, 'm6s', 'I suppose the Rebels will have to carry their supplies on their backs now. Job well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 23, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 24, 'm6t', 'Interrupt Rebel Vehicle Repairs'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 25, 'm7d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain safe from such atrocities and loyal to the Empire. '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 26, 'm7s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 27, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 28, 'm7t', 'Stop Rebel Indoctrinations'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 29, 'm8d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. Can you burn this installation to the ground? These terrorists must pay for their terrible acts of violence against the Empire.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 30, 'm8s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 31, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 32, 'm8t', 'Remove Rebel Terrorist Cell'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 33, 'm9d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost of some sort. However, our surveillance images clearly show known Rebels patrolling the facility''s perimeter. We need a trusted agent to lead a strike against this installation and insure its destruction. Is that you?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 34, 'm9s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 35, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 36, 'm9t', 'Destroy Rebel Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 37, 'm10d', 'Rather than being horrified by the Rebellion''s deadly sabotage of the Empire''s most brilliant and effective weapon against injustice, it seems instead that this terrorist act has encouraged some malcontents to form their own Rebel cell. We need a loyal citizen of the Empire to show these troublemakers the consequences of throwing their lot in with traitors and terrorists. Are you that citizen?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 38, 'm10s', 'A success like this deserves to be celebrated. You must share your victory with your closest friends. If any of them do not seem delighted as we are, give us their name and identification number. You can never be too sure.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 39, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 40, 'm10t', 'Attack Traitorous Malcontents'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 41, 'm11d', 'One of Sienar Fleet System''s chief engineers has foolishly decided to join the ranks of those traitorous Rebels. We''ve located this engineer and need them silenced before they can supply the Rebellion with technical specs. We believe the traitor is being held at a small warehouse currently used to store speeder parts. Can the Empire rely on you to accomplish this mission?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 42, 'm11s', 'Well done, agent. We hope that engineer was inside that warehouse when it was destroyed, and we hope the Rebellion learned no damaging Imperial secrets.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 43, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 44, 'm11t', 'Silence the Traitorous Engineer'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 45, 'm12d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots access to. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 46, 'm12s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 47, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 48, 'm12t', 'Remove Rebel Training Station'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 49, 'm13d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 50, 'm13s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 51, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 52, 'm13t', 'Remove Data Slicer'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 53, 'm14d', 'Agents within the CSA have informed Imperial Intelligence that many of the workers the Viceprexes had requested for hard labor are being transferred to a holding facility where Rebel agents can rescue convicted spies and sympathizers contained among the roster. We''ve acquired the coordinates of this facility and need a small team of loyal Imperial agents to obliterate it.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 54, 'm14s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 55, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 56, 'm14t', 'Blast Rebel Holding Facility'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 57, 'm15d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents. Can the Empire count on you?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 58, 'm15s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 59, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 60, 'm15t', 'Break Rebel Weapons'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 61, 'm16d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 62, 'm16s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 63, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 64, 'm16t', 'Deprive Rebels of Medical Care'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 65, 'm17d', 'The Rebels have managed to get their hands on some old Trade Federation destroyer droids. These units can be used to fortify their outposts and defend their bases. Fortunately, our informants have tracked these droids down and have provided us with the coordinates to the warehouse that is being used to store them. An Imperial strike team is needed to take these droidekas out of commission.  '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 66, 'm17s', 'A job well done, agent. The Empire will show its appreciation via this reward. Do come see us again for future missions.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 67, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 68, 'm17t', 'Destroy Destroyer Droids'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 69, 'm18d', 'Rebel infiltrators have been stealing laser cutters from Imperial depots. We believe they are building a new base of operations at a secret location. Our tracking beacons indicate the cutters'' location. We need you and your loyal Imperial fellows to strike the Rebel cache and blow it to atoms. Will you help your Empire?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 70, 'm18s', 'Ah, this would doubtless slow the Rebels'' efforts to carve new lairs. You''ve earned this reward!'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 71, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 72, 'm18t', 'Laser Cutter Cache'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 73, 'm19d', 'We believe we have identified the meeting site of a traitorous Moff who is plotting with Rebels to assassinate our beloved Emperor. We require an able Imperial strike team to hit this outpost and kill everyone present. Will you take this vital assignment?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 74, 'm19s', 'We can only hope that when you destroyed that outpost, the Moff was present. We''ll monitor communications to make sure. For your well-executed strike, you have earned this reward.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 75, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 76, 'm19t', 'Traitorous Moff Plots Assassination'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 77, 'm20d', 'The Rebellion is disguising LIN Demolitionmech droids to look like simple R3 units. They are striking at Imperial garrisons with these "miner bombs." We have located a Rebel depot full of mining equipment and explosives, and we require you to destroy it. Reduce all equipment to slag. Can you aid the Empire?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 78, 'm20s', 'An effective piece of work, agent. The Empire is proud. Claim your reward, and seek us out again for more work.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 79, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 80, 'm20t', 'Rebel Demolitionmech Depot'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 81, 'm21d', 'Recent Rebel attacks have used modified A-A5 speeder trucks as armored personnel carriers. We want you to destroy the repair facility used to create these carriers. Will you assist the Empire in removing this threat?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 82, 'm21s', 'Those speeder trucks are common, and the needed military modifications are unfortunately well understood. So you may expect further assignments of this type soon.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 83, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 84, 'm21t', 'A-A5 Speeder Truck Repair Facility'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 85, 'm22d', 'The Rebellion has obtained stolen R3 units, intended for Imperial cruisers, and is reprogramming them for its own use. We have located a depot holding many stolen R3s, but the droids are useless to us now because they may contain bugging devices. We wish you to destroy the depot, thus keeping the droids out of the hands of our enemies.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 86, 'm22s', 'Pity to see good droids go to waste, but there are always more droids. As for the Rebels -- soon there will be very few of those. Your reward is well earned.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 87, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 88, 'm22t', 'Stolen R3 Droid Depot'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 89, 'm23d', 'Intelligence informs us that Rebel supply caches of certain rare Outer Rim crystals are to be immediately destroyed. We''ve located a warehouse containing a large quantity of these crystals. You are to vaporize these minerals for us at once. Can the Empire count on your aid?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 90, 'm23s', 'The Rebels apparently are using these crystals to fashion some fiendish new weapon. We can only hope your success retards their progress. Well done.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 91, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 92, 'm23t', 'Warehouse of Rare Crystals'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 93, 'm24d', 'The Empire has engineered an airborne virus for deployment at anti-Imperial demonstrations in the Core Worlds. Rebels have analyzed the virus and created a retroviral vaccine. We have located a production run of the vaccine in a small medical depot. We wish it destroyed -- all of it. Will you assist us in this matter?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 94, 'm24s', 'Our viral plans should meet with better success now. Well done, citizen. The Empire will not forget your work.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 95, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 96, 'm24t', 'Retrovirus Vaccine Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 97, 'm25d', 'The Rebels are stockpiling climate control units, undoubtedly for use in remote bases in the Outer Rim. We want these units destroyed. You, being a loyal Imperial agent, would certainly be willing to take care of this, correct?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 98, 'm25s', 'We didn''t expect climate control units to present much threat. But we appreciate your clean and efficient attack. Well done!'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 99, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 100, 'm25t', 'Climate Control Unit Storage Facility'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 101, 'm26d', 'Rebel leaders are meeting with officials of the Bounty Hunters'' Guild, apparently to offer concocted "proof" that the Empire has attacked the Guild. We must stop this dangerous nonsense. Here are the coordinates of the secret meeting location. Go there and destroy everything and everyone you see. Do not mention the Empire, of course.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 102, 'm26s', 'Dead Rebels, and dead bounty hunters, tell no tales. Bravo, citizen. You are shaping up into a highly professional agent.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 103, 'm26o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 104, 'm26t', 'Meeting of Rebels and Bounty Hunters'' Guild'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 105, 'm27d', 'Rebels have taken over a speeder shop. They are apparently coercing its mechanics to adapt prototype speeders for operation in harsh climatic conditions. We would like you to stop this terrorist activity before it erupts into a full hostage situation. The hostages are presumed corrupted by now and can be safely killed with the rest.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 106, 'm27s', 'A job well done. Now we must try to discern what the Rebellion planned to do with those speeders. But that is a task for another day, citizen.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 107, 'm27o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 108, 'm27t', 'Speeder Garage Taken by Rebels'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 109, 'm28d', 'We have found a refueling depot used by the Rebel-friendly smugglers they quaintly call "procurement specialists." Because the military is preoccupied tracking down actual Rebel bases, we wish you to destroy this depot, quickly and thoroughly. Leave no survivors. Can you do this?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 110, 'm28s', 'Smugglers are not just a problem for the local authorities. They aid the Rebels and are therefore our problem as well. We are glad we can rely on you in such matters.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 111, 'm28o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 112, 'm28t', 'Smuggler Refueling Depot'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 113, 'm29d', 'We have uncovered a cache of vacuum gyros intended for Rebel transports. Unfortunately, the Rebels destroyed our probot and now know of our discovery. A Rebel contingent is evacuating the cache. We need you to destroy the contraband, and the Rebels, before it is too late. Move quickly!'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 114, 'm29s', 'Vacuum gyros allow Gallifree transports to slip through our blockades. Your good work will help us stop them more effectively. Well done!'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 115, 'm29o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 116, 'm29t', 'Vacuum Gyro Cache'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 117, 'm30d', 'We have found an encoding array the Rebellion uses to retransmit secret communiques. We require you to smash this installation and thereby cripple their information network. Expect well-armed opposition. If you succeed, the Empire will of course provide generous compensation.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 118, 'm30s', 'Already we have seen reduced numbers of encoded Rebel transmissions, because of your good work. Take this payment with our best respects.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 119, 'm30o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 120, 'm30t', 'Rebel Encoding Station'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 121, 'm31d', 'A new Rebel outpost has received a load of Defender-class space mine housings. We believe the Rebel terrorists plan to insert gravity-manipulation weapons into these casings, which would jeopardize routine hyperspace transits. We require you to wipe out this factory before it can unleash its deadly contraband.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 122, 'm31s', 'Our navigators can breathe more easily now. You have made the star lanes safe once more. '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 123, 'm31o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 124, 'm31t', 'Defender Gravity Mine Housings'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 125, 'm32d', 'The Rebels have set up another hyperspace monitoring terminal to track the movement of our capital ships. We need a ground-based agent to assault this station and shut it down. Expect heavy opposition, but be assured this mission is vital to our proud Imperial Navy!'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 126, 'm32s', 'Imperial Intelligence will begin sifting through the remains of the terminal shortly, assuming you left any remains. Accept this payment for your success.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 127, 'm32o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 128, 'm32t', 'Hyperspace Monitoring Terminal'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 129, 'm33d', 'Rebels have hijacked rations bound for Imperial garrisons. They have taken the stolen food to a local distribution center, where they use the contraband to bribe local settlers under the pretense of "famine relief." We require you to destroy this distribution center and stop this treachery before it spreads. At once!'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 130, 'm33s', 'You have spared local citizens the indignity of consuming stolen food. Take your reward with honor.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 131, 'm33o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 132, 'm33t', 'Hijacked Imperial Rations'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 133, 'm34d', 'Recently our field operatives wiped out a Rebel command center using an exciting new airborne biological agent. A group of survivors fled to a small "safe house," carrying several corpses. Our scientists have deemed it prudent to destroy these bodies in the interest of public health. You must blast the entire structure; we shall observe from a safe distance.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 134, 'm34s', 'Excellent. Use this reward to relocate well away from populated areas, and avoid bodily contact with any soldier of the Empire. You may go now. Quickly!'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 135, 'm34o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 136, 'm34t', 'Eliminate Contaminated Bodies'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 137, 'm35d', 'Recently the Rebellion provoked the untimely destruction of Alderaan. Properly reviled for this heinous crime, the Rebels have sought public sympathy by breeding many of Alderaan''s native fauna. Loyal citizens of the Empire know that this program is nothing but a transparent act of propaganda. Luckily we have located the center of this traitorous enterprise. Remove it.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 138, 'm35s', 'While the beautiful woolly moth of Alderaan may have looked harmless, it was a vicious threat to galactic security. You have advanced the cause of Imperial truth.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 139, 'm35o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 140, 'm35t', 'Burn Rebel Propaganda'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 141, 'm36d', 'Some Imperial agents are in Rebel custody and currently imprisoned in a small but well-guarded holding facility. The Rebels will be on the lookout for uniformed soldiers, so we require some highly-trained civilians to launch a surprise assault on the holding facility and reduce it to rubble. We must assume that the captured agents are dead. Can you help us?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 142, 'm36s', 'We''re pleased that the captured agents have been liquidated. You have earned the undying respect and loyalty of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 143, 'm36o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 144, 'm36t', 'Eliminate Captured Agents'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 145, 'm37d', 'The Rebels have launched an insidious scheme to undermine the security of an orderly world. As you know, Imperial engineers have enhanced the water supply of many communities with placidity enzymes to abate civic unrest. The Rebels have captured a local water junction and installed a Creel manifold to siphon off the additives. We need you to blast this junction into oblivion.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 146, 'm37s', 'The Empire is lucky to have such skilled operatives. Rest assured that the community''s water supply will be fully restored within a few months.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 147, 'm37o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 148, 'm37t', 'Help Purify the Water Supply'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 149, 'm38d', 'For thirty years I languished in the Glythe sector as a remote field operative of the ISB. Now, at the end of my career, I have been transferred to a more civilized system with a chance to make a real impact. To this end I am sending a strike team to take out a suspected Rebel grease refinery. I require well-trained operatives who are not afraid to get their hands dirty.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 150, 'm38s', 'At last I have achieved true success! My grandchildren will thank you for saving a man''s reputation. Take your payment and enjoy it.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 151, 'm38o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 152, 'm38t', 'Strike a Rebel Refinery'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 153, 'm39d', 'We''ve pinpointed a cloister of fuselage engineers who are aiding the Rebels in their fighter designs. We are commissioning a team of investigators to search these coordinates and eliminate any operations they find. Watch out for surprises and make sure to wipe out any research materials they have gathered.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 154, 'm39s', 'I understand those engineers were tougher than they looked. Or perhaps you are not as competant as you portray yourself. At least you completed the mission.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_military_hard.stf', 155, 'm39o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 156, 'm39t', 'Smash the Cloister of Engineers'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 157, 'm40d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was highjacked en route to a Civil Security Center on Dantooine. We have intercepted Rebel messages that suggest these droids were smuggled to a secret reprogramming facility. A squad of operatives must travel to these coordinates and eradicate the facility immediately.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 158, 'm40s', 'The Empire is grateful for your service. IG assassin droids are expensive. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 159, 'm40o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 160, 'm40t', 'Blast Droid Reprogramming Facility'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 161, 'm41d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, though, the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 162, 'm41s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 163, 'm41o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 164, 'm41t', 'Disable the X-wings'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 165, 'm42d', 'The Rebels have stolen the plans for a new Imperial void station and hidden them inside an innocuous MSE-6 droid. We learned that it got aboard a smuggler''s freighter and landed at these coordinates. We require a strike team to pinpoint the Rebel outpost and smash it to rubble. Imperial Intelligence will inspect the site to retrieve what remains of the offending MSE-6.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 166, 'm42s', 'Excellent work. There''s no way a mouse droid could have escaped your assault. You have served the Empire well.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 167, 'm42o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 168, 'm42t', 'Find a MSE-6 Droid'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 169, 'm43d', 'Our informants have alerted us that a local pharmaceutical shop is doubling as an underground clinic for Rebel agents. We must make sure that these traitors do not have access to medical care. We understand that there are no less than two bacta tanks in operation at this facility. All of this equipment must be destroyed. Are you the Imperial agent we''re looking for? '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 170, 'm43s', 'Good work! Now we will be able to better trace Rebel agents when they are forced to use local medical clinics. The reward is yours. '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 171, 'm43o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 172, 'm43t', 'Destroy Rebel Medical Clinic'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 173, 'm44d', 'A storage facility housing some outdated communications equipment and refurbished power generators is being used by the local Rebel cell to help supply their members. This equipment had been scheduled to be transported to Imperial junkyards for salvage but it seems the Rebellion got their hands on it first. Make sure this junk is not used to help the Rebellion. '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 174, 'm44s', 'You handled that well, citizen. It makes sense that garbage would attract garbage. You''re an efficient disposal agent.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 175, 'm44o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 176, 'm44t', 'Take Out Parts Warehouse'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 177, 'm45d', 'It has come to our attention that a local livestock dealer harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. As you may know, certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 178, 'm45s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 179, 'm45o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 180, 'm45t', 'Crush the Mynock Incubators'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 181, 'm46d', 'A local community has recently been plagued by a fake recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility at these coordinates. We want you to take a strike team and decimate this unseemly operation. In particular, make certain that all of these fake recording are utterly destroyed.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 182, 'm46s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 183, 'm46o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 184, 'm46t', 'Raze a Seditious Broadcast Facility'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 185, 'm47d', 'In the midst of an otherwise obedient community, the Rebels have constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 186, 'm47s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return.  '),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 187, 'm47o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 188, 'm47t', 'Blast a Rebel Power Relay'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 189, 'm48d', 'They want us to believe they are mere gangsters, but we have discovered that the Ravvo clan are in fact agents of the Rebel Alliance. These creeps have a barracks, at these coordinates, where they practice their marksmanship to the detriment of the Empire. A well-armed assault will teach them that scoffing Imperial authority is a game for fools and dead men.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 190, 'm48s', 'It''s astounding that so many fools refuse to acknowledge the irresistable might of the Empire. You have shown them the error of their ways.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 191, 'm48o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 192, 'm48t', 'Level a Den of Rebel Sympathizers'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 193, 'm49d', 'The Rebellion is spreading rumors that Jedi have returned and have joined the traitorous scum against the Empire. We have seen holograph displays depicting a lightsaber and bearing the ridiculous slogan "The Jedi have returned! Long live the Republic!" We''ve located a warehouse filled with this sort of propaganda and it must bed destroyed.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 194, 'm49s', 'A job well done, citizen. The Jedi have not returned and the Rebellion is doomed. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 195, 'm49o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 196, 'm49t', 'Smash Rebel Propaganda'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 197, 'm50d', 'The Rebellion has been distributing copies of a fabricated hologram showing the destruction of Alderaan by the Empire''s peacekeeping station, the Death Star. We know Alderaan brought about its own destruction when the "peaceful" planet fired an experimental doomsday weapon at the Death Star. Help us destroy these seditious hologram duplication centers.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 198, 'm50s', 'Lies have gone up in smoke, citizen. Job well done! Your work will further the cause of the New Order and serve to glorify the Empire.'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 199, 'm50o', ''),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 200, 'm50t', 'Destroy Hologram Duplication Center'),
('string/en/mission/mission_destroy_imperial_military_hard.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 1, 'm1d', 'Our probe droids have located a sizable Rebel munitions depot. Taking out this supply cache would limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended. Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 3, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 4, 'm1t', 'Destroy Rebel munitions depot'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 7, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 8, 'm2t', 'Destroy Rebel mining facility'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 9, 'm3d', 'Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 11, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the ISB. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 12, 'm3t', 'Destroy Rebel communications array'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 13, 'm4d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility. '),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 15, 'm4s', 'You can run but you can''t hide! Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 16, 'm4t', 'Destroy Rebel alien refugee outpost'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain loyal to the Empire. Can you help your Emperor stamp out this loathsome practice? '),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 19, 'm5s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. Losing your faith in the New Order is bad enough, but to lose your mind along with it? You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 20, 'm5t', 'Destroy Rebel indoctrination camp'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. We require a loyal citizen of the Empire to burn this installation to the ground. Are you the agent we''re looking for?'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 23, 'm6s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen. We hope this is a definite indication of things to come.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 24, 'm6t', 'Destroy Rebel terrorist cell'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 25, 'm7d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost. We need a trusted agent to lead a strike against this installation and insure its destruction. There''s no telling how many cells this depot has been supplying or how many Imperial lives have been lost as a result.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 27, 'm7s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 28, 'm7t', 'Destroy Rebel supply depot'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 29, 'm8d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their traitorous cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots to play around with. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 31, 'm8s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous indeed. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 32, 'm8t', 'Destroy Rebel training station'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 33, 'm9d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 35, 'm9s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 36, 'm9t', 'Destroy Rebel slicer hub'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 37, 'm10d', 'Agents within the CSA have informed Intelligence that many of the workers the Viceprexes are requesting for hard labor are being transferred to a holding facility so that Rebel agents can rescue convicted Rebel spies and sympathizers contained among the roster. We need a small team of loyal Imperial agents to obliterate this facility. The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 39, 'm10s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 40, 'm10t', 'Blast Rebel refugee facility'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 41, 'm11d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 43, 'm11s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 44, 'm11t', 'Destroy Rebel weapons cache'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 45, 'm12d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 47, 'm12s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 48, 'm12t', 'Destroy Rebel medical droids'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 49, 'm13d', 'The Rebels have been targeting Imperial depots containing laser cutters. We believe they need them to build a new operational base although we do not yet know its location. Our agents have managed, however, to locate some of these laser cutters and have sent us the coordinates where they are being housed. We need a few loyal Imperial agents to strike this storage depot.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 51, 'm13s', 'Success! This will doubtless slow the Rebels'' efforts to carve out new lairs. You''ve earned your reward, agent.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 52, 'm13t', 'No more Rebel bases'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 53, 'm14d', 'A traitorous moff has offered to aid the Rebels attempt to assassinate our beloved Emperor. We''ve pinpointed where this traitor and his agents will be meeting with the Rebellion''s agents to make the arrangements. We require an able and loyal Imperial strike team to hit this outpost and insure its destruction. Could you assemble and lead such a team?'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 55, 'm14s', 'We have not ascertained if the moff was at that meeting when you destroyed the outpost. We''ll have to continue monitoring communications. In any case, your strike against that Rebel outpost was superb.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 56, 'm14t', 'Hunt a traitorous moff'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 57, 'm15d', 'Local garrisons have reported recent Rebel attacks that have employed modified A-A5 speeder trucks as armored personnel carriers. We''ve located several civilian speeder repair facilities that could be used to create these carriers. We want these installations destroyed. Can you assist the Empire in removing this potential threat? '),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 59, 'm15s', 'Good work, agent. We knew these stations were serving those Rebel scum and you''ve helped prove it. We hope this is the beginning of a very profitable career for you.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 60, 'm15t', 'Take out Rebel repair stations'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 61, 'm16d', 'The Rebels have taken an interest in certain rare types of crystals. Intelligence has instructed us to destroy any supply depot containing caches of such minerals. We''ve located a small warehouse containing a large quantity of mineral desposits mined from the Outer Rim. We need loyal Imperial servants to vaporize this warehouse.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 63, 'm16s', 'An efficient handling of the mission, agent. Well done. The Empire is proud to reward you.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 64, 'm16t', 'Smash the mysterious crystals'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 65, 'm17d', 'We''ve been alerted to the presence of a Rebel supply depot that seems to be housing hundreds of climate control units. No doubt these are intended for remote Rebel bases in the Outer Rim. We want these units destroyed and figure a loyal and skilled Imperial agent ought to be able to take care of that for us. No need to call in a full military strike.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 67, 'm17s', 'Clean and efficient, citizen, just like we like it. COMPNOR could use more agents like you. '),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 68, 'm17t', 'Make it cold for the Rebels'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 69, 'm18d', 'We finally identified the traitor who has been supplying vacuum gyros for Rebel transports. We have the coordinates to the traitor''s secret gyro cache. Unfortunately he knows we are coming. Our sources tell us that a contingent of Rebel soldiers is evacuating the cache. We need to dispatch a team to destroy this contraband before the Rebels take it away.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 71, 'm18s', 'Well done, citizen. Those Gallifree transports slip through our blockades too easily. Perhaps now we can stop those Rebel scum.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 72, 'm18t', 'Cripple Rebel transports'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 73, 'm19d', 'Ion space mines are an important tool of the Imperial Navy, but in the hands of Rebel terrorists they become a menace to all law-abiding spacefarers. We have tracked a freighter to a known Rebel outpost, where it deposited a load of Defender-class mines. If we can wipe out this factory before its deadly contraband is unleashed, the star lanes will be safe once more.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 75, 'm19s', 'The Imperial Navy is indebted to you. Accept this payment and the gratitude of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 76, 'm19t', 'Take out the space mines'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 77, 'm20d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was highjacked en route to a Civil Security Center on Dantooine. Intercepted Rebel transmissions suggest these droids were smuggled to a secret reprogramming facility, where technicians will turn the IGs into gardening and botanical droids. A squad must locate and destroy this facility.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 79, 'm20s', 'The Empire is grateful for your service. IG assassin droids make lousy botanical arrangements. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 80, 'm20t', 'Assassin droids do not pick posies'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 81, 'm21d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, as the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 83, 'm21s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 84, 'm21t', 'Smash a squad of X-wing fighters'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 85, 'm22d', 'We''ve discovered a local livestock dealer who harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. Certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 87, 'm22s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 88, 'm22t', 'Crush a mynock incubator'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 89, 'm23d', 'A local community has recently been plagued by a fake holovid recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility. You must take a strike team and decimate this unseemly operation. These untruths will not soil the tranquility of our loyal and obedient communities.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 91, 'm23s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 92, 'm23t', 'Raze a seditious broadcast facility'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 93, 'm24d', 'In the midst of an otherwise obedient community, the Rebellion has constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 95, 'm24s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return. '),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 96, 'm24t', 'Blast a Rebel power relay'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 97, 'm25d', 'The Inquisitorius has ordered a strike on a Rebel outpost that has been conducting unusual experiments involving the Force and Force-users. We cannot imagine that the Rebellion would be foolish enough to attempt to establish another Jedi training academy, especially in light of the corruption that was revealed within the ranks of the old Jedi Order. Can you assemble a strike team to take care of this?'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 99, 'm25s', 'A new breed of Jedi shall not rise to threaten our beloved Empire thanks to you, agent. Well done! The Emperor will hear of your success. Be proud.'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 100, 'm25t', 'Destroy Rebel training outpost'),
('string/en/mission/mission_destroy_imperial_military_hard_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 1, 'm1d', 'Our probe droids have located a fairly sizable Rebel munitions depot. Taking this supply cache out would no doubt limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended (it is a weapons depot, after all). Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 2, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 3, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 4, 'm1t', 'Make a Munitions Depot Go Boom'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 6, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 7, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 8, 'm2t', 'Smash Rebel Mining Operation'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 9, 'm3d', 'Imperial Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 10, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the Empire. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 11, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 12, 'm3t', 'Disrupt Rebel Communications'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 13, 'm4d', 'What we thought was a legitimate medical facility has turned out to be a Rebel medical supply depot. It seems they''ve been using sick citizens as cover, trying to get us to believe they were operating according to Imperial laws. We feel for these sick individuals, although no doubt many of them are Rebel sympathizers, but this facility must be destroyed.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 14, 'm4s', 'Bacta is wasted on Rebel scum, do not worry. You have done very well and we are highly pleased. Our missions require someone with a strong constitution. You should seek us out in the future.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 15, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 16, 'm4t', 'Blast Medical Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 17, 'm5d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility in the name of Imperial justice. '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 18, 'm5s', 'Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 19, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 20, 'm5t', 'Neutralize Rebel Refugees'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 21, 'm6d', 'Thanks to the efforts of our many loyal civilian informants, we''ve managed to verify the existence of a Rebel transport repair facility. We kept wondering where those Rebels would take their vehicles when they needed repairs. After all, many of them bear the evidence of skirmishes with local civil authorities or Imperial forces. We''d like this installation eliminated.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 22, 'm6s', 'I suppose the Rebels will have to carry their supplies on their backs now. Job well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 23, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 24, 'm6t', 'Interrupt Rebel Vehicle Repairs'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 25, 'm7d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain safe from such atrocities and loyal to the Empire. '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 26, 'm7s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 27, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 28, 'm7t', 'Stop Rebel Indoctrinations'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 29, 'm8d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. Can you burn this installation to the ground? These terrorists must pay for their terrible acts of violence against the Empire.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 30, 'm8s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 31, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 32, 'm8t', 'Remove Rebel Terrorist Cell'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 33, 'm9d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost of some sort. However, our surveillance images clearly show known Rebels patrolling the facility''s perimeter. We need a trusted agent to lead a strike against this installation and insure its destruction. Is that you?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 34, 'm9s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 35, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 36, 'm9t', 'Destroy Rebel Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 37, 'm10d', 'Rather than being horrified by the Rebellion''s deadly sabotage of the Empire''s most brilliant and effective weapon against injustice, it seems instead that this terrorist act has encouraged some malcontents to form their own Rebel cell. We need a loyal citizen of the Empire to show these troublemakers the consequences of throwing their lot in with traitors and terrorists. Are you that citizen?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 38, 'm10s', 'A success like this deserves to be celebrated. You must share your victory with your closest friends. If any of them do not seem delighted as we are, give us their name and identification number. You can never be too sure.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 39, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 40, 'm10t', 'Attack Traitorous Malcontents'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 41, 'm11d', 'One of Sienar Fleet System''s chief engineers has foolishly decided to join the ranks of those traitorous Rebels. We''ve located this engineer and need them silenced before they can supply the Rebellion with technical specs. We believe the traitor is being held at a small warehouse currently used to store speeder parts. Can the Empire rely on you to accomplish this mission?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 42, 'm11s', 'Well done, agent. We hope that engineer was inside that warehouse when it was destroyed, and we hope the Rebellion learned no damaging Imperial secrets.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 43, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 44, 'm11t', 'Silence the Traitorous Engineer'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 45, 'm12d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots access to. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 46, 'm12s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 47, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 48, 'm12t', 'Remove Rebel Training Station'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 49, 'm13d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 50, 'm13s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 51, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 52, 'm13t', 'Remove Data Slicer'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 53, 'm14d', 'Agents within the CSA have informed Imperial Intelligence that many of the workers the Viceprexes had requested for hard labor are being transferred to a holding facility where Rebel agents can rescue convicted spies and sympathizers contained among the roster. We''ve acquired the coordinates of this facility and need a small team of loyal Imperial agents to obliterate it.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 54, 'm14s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 55, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 56, 'm14t', 'Blast Rebel Holding Facility'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 57, 'm15d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents. Can the Empire count on you?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 58, 'm15s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 59, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 60, 'm15t', 'Break Rebel Weapons'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 61, 'm16d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 62, 'm16s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 63, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 64, 'm16t', 'Deprive Rebels of Medical Care'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 65, 'm17d', 'The Rebels have managed to get their hands on some old Trade Federation destroyer droids. These units can be used to fortify their outposts and defend their bases. Fortunately, our informants have tracked these droids down and have provided us with the coordinates to the warehouse that is being used to store them. An Imperial strike team is needed to take these droidekas out of commission.  '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 66, 'm17s', 'A job well done, agent. The Empire will show its appreciation via this reward. Do come see us again for future missions.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 67, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 68, 'm17t', 'Destroy Destroyer Droids'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 69, 'm18d', 'Rebel infiltrators have been stealing laser cutters from Imperial depots. We believe they are building a new base of operations at a secret location. Our tracking beacons indicate the cutters'' location. We need you and your loyal Imperial fellows to strike the Rebel cache and blow it to atoms. Will you help your Empire?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 70, 'm18s', 'Ah, this would doubtless slow the Rebels'' efforts to carve new lairs. You''ve earned this reward!'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 71, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 72, 'm18t', 'Laser Cutter Cache'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 73, 'm19d', 'We believe we have identified the meeting site of a traitorous Moff who is plotting with Rebels to assassinate our beloved Emperor. We require an able Imperial strike team to hit this outpost and kill everyone present. Will you take this vital assignment?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 74, 'm19s', 'We can only hope that when you destroyed that outpost, the Moff was present. We''ll monitor communications to make sure. For your well-executed strike, you have earned this reward.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 75, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 76, 'm19t', 'Traitorous Moff Plots Assassination'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 77, 'm20d', 'The Rebellion is disguising LIN Demolitionmech droids to look like simple R3 units. They are striking at Imperial garrisons with these "miner bombs." We have located a Rebel depot full of mining equipment and explosives, and we require you to destroy it. Reduce all equipment to slag. Can you aid the Empire?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 78, 'm20s', 'An effective piece of work, agent. The Empire is proud. Claim your reward, and seek us out again for more work.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 79, 'm20o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_military_medium.stf', 80, 'm20t', 'Rebel Demolitionmech Depot'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 81, 'm21d', 'Recent Rebel attacks have used modified A-A5 speeder trucks as armored personnel carriers. We want you to destroy the repair facility used to create these carriers. Will you assist the Empire in removing this threat?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 82, 'm21s', 'Those speeder trucks are common, and the needed military modifications are unfortunately well understood. So you may expect further assignments of this type soon.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 83, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 84, 'm21t', 'A-A5 Speeder Truck Repair Facility'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 85, 'm22d', 'The Rebellion has obtained stolen R3 units, intended for Imperial cruisers, and is reprogramming them for its own use. We have located a depot holding many stolen R3s, but the droids are useless to us now because they may contain bugging devices. We wish you to destroy the depot, thus keeping the droids out of the hands of our enemies.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 86, 'm22s', 'Pity to see good droids go to waste, but there are always more droids. As for the Rebels -- soon there will be very few of those. Your reward is well earned.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 87, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 88, 'm22t', 'Stolen R3 Droid Depot'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 89, 'm23d', 'Intelligence informs us that Rebel supply caches of certain rare Outer Rim crystals are to be immediately destroyed. We''ve located a warehouse containing a large quantity of these crystals. You are to vaporize these minerals for us at once. Can the Empire count on your aid?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 90, 'm23s', 'The Rebels apparently are using these crystals to fashion some fiendish new weapon. We can only hope your success retards their progress. Well done.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 91, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 92, 'm23t', 'Warehouse of Rare Crystals'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 93, 'm24d', 'The Empire has engineered an airborne virus for deployment at anti-Imperial demonstrations in the Core Worlds. Rebels have analyzed the virus and created a retroviral vaccine. We have located a production run of the vaccine in a small medical depot. We wish it destroyed -- all of it. Will you assist us in this matter?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 94, 'm24s', 'Our viral plans should meet with better success now. Well done, citizen. The Empire will not forget your work.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 95, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 96, 'm24t', 'Retrovirus Vaccine Supply Depot'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 97, 'm25d', 'The Rebels are stockpiling climate control units, undoubtedly for use in remote bases in the Outer Rim. We want these units destroyed. You, being a loyal Imperial agent, would certainly be willing to take care of this, correct?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 98, 'm25s', 'We didn''t expect climate control units to present much threat. But we appreciate your clean and efficient attack. Well done!'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 99, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 100, 'm25t', 'Climate Control Unit Storage Facility'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 101, 'm26d', 'Rebel leaders are meeting with officials of the Bounty Hunters'' Guild, apparently to offer concocted "proof" that the Empire has attacked the Guild. We must stop this dangerous nonsense. Here are the coordinates of the secret meeting location. Go there and destroy everything and everyone you see. Do not mention the Empire, of course.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 102, 'm26s', 'Dead Rebels, and dead bounty hunters, tell no tales. Bravo, citizen. You are shaping up into a highly professional agent.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 103, 'm26o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 104, 'm26t', 'Meeting of Rebels and Bounty Hunters'' Guild'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 105, 'm27d', 'Rebels have taken over a speeder shop. They are apparently coercing its mechanics to adapt prototype speeders for operation in harsh climatic conditions. We would like you to stop this terrorist activity before it erupts into a full hostage situation. The hostages are presumed corrupted by now and can be safely killed with the rest.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 106, 'm27s', 'A job well done. Now we must try to discern what the Rebellion planned to do with those speeders. But that is a task for another day, citizen.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 107, 'm27o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 108, 'm27t', 'Speeder Garage Taken by Rebels'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 109, 'm28d', 'We have found a refueling depot used by the Rebel-friendly smugglers they quaintly call "procurement specialists." Because the military is preoccupied tracking down actual Rebel bases, we wish you to destroy this depot, quickly and thoroughly. Leave no survivors. Can you do this?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 110, 'm28s', 'Smugglers are not just a problem for the local authorities. They aid the Rebels and are therefore our problem as well. We are glad we can rely on you in such matters.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 111, 'm28o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 112, 'm28t', 'Smuggler Refueling Depot'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 113, 'm29d', 'We have uncovered a cache of vacuum gyros intended for Rebel transports. Unfortunately, the Rebels destroyed our probot and now know of our discovery. A Rebel contingent is evacuating the cache. We need you to destroy the contraband, and the Rebels, before it is too late. Move quickly!'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 114, 'm29s', 'Vacuum gyros allow Gallifree transports to slip through our blockades. Your good work will help us stop them more effectively. Well done!'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 115, 'm29o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 116, 'm29t', 'Vacuum Gyro Cache'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 117, 'm30d', 'We have found an encoding array the Rebellion uses to retransmit secret communiques. We require you to smash this installation and thereby cripple their information network. Expect well-armed opposition. If you succeed, the Empire will of course provide generous compensation.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 118, 'm30s', 'Already we have seen reduced numbers of encoded Rebel transmissions, because of your good work. Take this payment with our best respects.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 119, 'm30o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 120, 'm30t', 'Rebel Encoding Station'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 121, 'm31d', 'A new Rebel outpost has received a load of Defender-class space mine housings. We believe the Rebel terrorists plan to insert gravity-manipulation weapons into these casings, which would jeopardize routine hyperspace transits. We require you to wipe out this factory before it can unleash its deadly contraband.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 122, 'm31s', 'Our navigators can breathe more easily now. You have made the star lanes safe once more. '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 123, 'm31o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 124, 'm31t', 'Defender Gravity Mine Housings'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 125, 'm32d', 'The Rebels have set up another hyperspace monitoring terminal to track the movement of our capital ships. We need a ground-based agent to assault this station and shut it down. Expect heavy opposition, but be assured this mission is vital to our proud Imperial Navy!'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 126, 'm32s', 'Imperial Intelligence will begin sifting through the remains of the terminal shortly, assuming you left any remains. Accept this payment for your success.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 127, 'm32o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 128, 'm32t', 'Hyperspace Monitoring Terminal'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 129, 'm33d', 'Rebels have hijacked rations bound for Imperial garrisons. They have taken the stolen food to a local distribution center, where they use the contraband to bribe local settlers under the pretense of "famine relief." We require you to destroy this distribution center and stop this treachery before it spreads. At once!'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 130, 'm33s', 'You have spared local citizens the indignity of consuming stolen food. Take your reward with honor.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 131, 'm33o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 132, 'm33t', 'Hijacked Imperial Rations'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 133, 'm34d', 'Recently our field operatives wiped out a Rebel command center using an exciting new airborne biological agent. A group of survivors fled to a small "safe house," carrying several corpses. Our scientists have deemed it prudent to destroy these bodies in the interest of public health. You must blast the entire structure; we shall observe from a safe distance.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 134, 'm34s', 'Excellent. Use this reward to relocate well away from populated areas, and avoid bodily contact with any soldier of the Empire. You may go now. Quickly!'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 135, 'm34o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 136, 'm34t', 'Eliminate Contaminated Bodies'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 137, 'm35d', 'Recently the Rebellion provoked the untimely destruction of Alderaan. Properly reviled for this heinous crime, the Rebels have sought public sympathy by breeding many of Alderaan''s native fauna. Loyal citizens of the Empire know that this program is nothing but a transparent act of propaganda. Luckily we have located the center of this traitorous enterprise. Remove it.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 138, 'm35s', 'While the beautiful woolly moth of Alderaan may have looked harmless, it was a vicious threat to galactic security. You have advanced the cause of Imperial truth.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 139, 'm35o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 140, 'm35t', 'Burn Rebel Propaganda'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 141, 'm36d', 'Some Imperial agents are in Rebel custody and currently imprisoned in a small but well-guarded holding facility. The Rebels will be on the lookout for uniformed soldiers, so we require some highly-trained civilians to launch a surprise assault on the holding facility and reduce it to rubble. We must assume that the captured agents are dead. Can you help us?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 142, 'm36s', 'We''re pleased that the captured agents have been liquidated. You have earned the undying respect and loyalty of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 143, 'm36o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 144, 'm36t', 'Eliminate Captured Agents'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 145, 'm37d', 'The Rebels have launched an insidious scheme to undermine the security of an orderly world. As you know, Imperial engineers have enhanced the water supply of many communities with placidity enzymes to abate civic unrest. The Rebels have captured a local water junction and installed a Creel manifold to siphon off the additives. We need you to blast this junction into oblivion.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 146, 'm37s', 'The Empire is lucky to have such skilled operatives. Rest assured that the community''s water supply will be fully restored within a few months.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 147, 'm37o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 148, 'm37t', 'Help Purify the Water Supply'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 149, 'm38d', 'For thirty years I languished in the Glythe sector as a remote field operative of the ISB. Now, at the end of my career, I have been transferred to a more civilized system with a chance to make a real impact. To this end I am sending a strike team to take out a suspected Rebel grease refinery. I require well-trained operatives who are not afraid to get their hands dirty.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 150, 'm38s', 'At last I have achieved true success! My grandchildren will thank you for saving a man''s reputation. Take your payment and enjoy it.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 151, 'm38o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 152, 'm38t', 'Strike a Rebel Refinery'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 153, 'm39d', 'We''ve pinpointed a cloister of fuselage engineers who are aiding the Rebels in their fighter designs. We are commissioning a team of investigators to search these coordinates and eliminate any operations they find. Watch out for surprises and make sure to wipe out any research materials they have gathered.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 154, 'm39s', 'I understand those engineers were tougher than they looked. Or perhaps you are not as competant as you portray yourself. At least you completed the mission.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 155, 'm39o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 156, 'm39t', 'Smash the Cloister of Engineers'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 157, 'm40d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was highjacked en route to a Civil Security Center on Dantooine. We have intercepted Rebel messages that suggest these droids were smuggled to a secret reprogramming facility. A squad of operatives must travel to these coordinates and eradicate the facility immediately.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 158, 'm40s', 'The Empire is grateful for your service. IG assassin droids are expensive. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 159, 'm40o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 160, 'm40t', 'Blast Droid Reprogramming Facility'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 161, 'm41d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, though, the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 162, 'm41s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 163, 'm41o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 164, 'm41t', 'Disable the X-wings'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 165, 'm42d', 'The Rebels have stolen the plans for a new Imperial void station and hidden them inside an innocuous MSE-6 droid. We learned that it got aboard a smuggler''s freighter and landed at these coordinates. We require a strike team to pinpoint the Rebel outpost and smash it to rubble. Imperial Intelligence will inspect the site to retrieve what remains of the offending MSE-6.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 166, 'm42s', 'Excellent work. There''s no way a mouse droid could have escaped your assault. You have served the Empire well.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 167, 'm42o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 168, 'm42t', 'Find a MSE-6 Droid'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 169, 'm43d', 'Our informants have alerted us that a local pharmaceutical shop is doubling as an underground clinic for Rebel agents. We must make sure that these traitors do not have access to medical care. We understand that there are no less than two bacta tanks in operation at this facility. All of this equipment must be destroyed. Are you the Imperial agent we''re looking for? '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 170, 'm43s', 'Good work! Now we will be able to better trace Rebel agents when they are forced to use local medical clinics. The reward is yours. '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 171, 'm43o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 172, 'm43t', 'Destroy Rebel Medical Clinic'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 173, 'm44d', 'A storage facility housing some outdated communications equipment and refurbished power generators is being used by the local Rebel cell to help supply their members. This equipment had been scheduled to be transported to Imperial junkyards for salvage but it seems the Rebellion got their hands on it first. Make sure this junk is not used to help the Rebellion. '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 174, 'm44s', 'You handled that well, citizen. It makes sense that garbage would attract garbage. You''re an efficient disposal agent.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 175, 'm44o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 176, 'm44t', 'Take Out Parts Warehouse'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 177, 'm45d', 'It has come to our attention that a local livestock dealer harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. As you may know, certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 178, 'm45s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 179, 'm45o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 180, 'm45t', 'Crush the Mynock Incubators'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 181, 'm46d', 'A local community has recently been plagued by a fake recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility at these coordinates. We want you to take a strike team and decimate this unseemly operation. In particular, make certain that all of these fake recording are utterly destroyed.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 182, 'm46s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 183, 'm46o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 184, 'm46t', 'Raze a Seditious Broadcast Facility'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 185, 'm47d', 'In the midst of an otherwise obedient community, the Rebels have constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 186, 'm47s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return.  '),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 187, 'm47o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 188, 'm47t', 'Blast a Rebel Power Relay'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 189, 'm48d', 'They want us to believe they are mere gangsters, but we have discovered that the Ravvo clan are in fact agents of the Rebel Alliance. These creeps have a barracks, at these coordinates, where they practice their marksmanship to the detriment of the Empire. A well-armed assault will teach them that scoffing Imperial authority is a game for fools and dead men.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 190, 'm48s', 'It''s astounding that so many fools refuse to acknowledge the irresistable might of the Empire. You have shown them the error of their ways.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 191, 'm48o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 192, 'm48t', 'Level a Den of Rebel Sympathizers'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 193, 'm49d', 'The Rebellion is spreading rumors that Jedi have returned and have joined the traitorous scum against the Empire. We have seen holograph displays depicting a lightsaber and bearing the ridiculous slogan "The Jedi have returned! Long live the Republic!" We''ve located a warehouse filled with this sort of propaganda and it must bed destroyed.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 194, 'm49s', 'A job well done, citizen. The Jedi have not returned and the Rebellion is doomed. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 195, 'm49o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 196, 'm49t', 'Smash Rebel Propaganda'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 197, 'm50d', 'The Rebellion has been distributing copies of a fabricated hologram showing the destruction of Alderaan by the Empire''s peacekeeping station, the Death Star. We know Alderaan brought about its own destruction when the "peaceful" planet fired an experimental doomsday weapon at the Death Star. Help us destroy these seditious hologram duplication centers.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 198, 'm50s', 'Lies have gone up in smoke, citizen. Job well done! Your work will further the cause of the New Order and serve to glorify the Empire.'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 199, 'm50o', ''),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 200, 'm50t', 'Destroy Hologram Duplication Center'),
('string/en/mission/mission_destroy_imperial_military_medium.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 1, 'm1d', 'Our probe droids have located a sizable Rebel munitions depot. Taking out this supply cache would limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended. Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 3, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 4, 'm1t', 'Destroy Rebel munitions depot'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 7, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 8, 'm2t', 'Destroy Rebel mining facility'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 9, 'm3d', 'Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 11, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the ISB. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 12, 'm3t', 'Destroy Rebel communications array'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 13, 'm4d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility. '),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 15, 'm4s', 'You can run but you can''t hide! Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 16, 'm4t', 'Destroy Rebel alien refugee outpost'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain loyal to the Empire. Can you help your Emperor stamp out this loathsome practice? '),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 19, 'm5s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. Losing your faith in the New Order is bad enough, but to lose your mind along with it? You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 20, 'm5t', 'Destroy Rebel indoctrination camp'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. We require a loyal citizen of the Empire to burn this installation to the ground. Are you the agent we''re looking for?'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 23, 'm6s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen. We hope this is a definite indication of things to come.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 24, 'm6t', 'Destroy Rebel terrorist cell'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 25, 'm7d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost. We need a trusted agent to lead a strike against this installation and insure its destruction. There''s no telling how many cells this depot has been supplying or how many Imperial lives have been lost as a result.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 27, 'm7s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 28, 'm7t', 'Destroy Rebel supply depot'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 29, 'm8d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their traitorous cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots to play around with. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 31, 'm8s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous indeed. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 32, 'm8t', 'Destroy Rebel training station'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 33, 'm9d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 35, 'm9s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 36, 'm9t', 'Destroy Rebel slicer hub'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 37, 'm10d', 'Agents within the CSA have informed Intelligence that many of the workers the Viceprexes are requesting for hard labor are being transferred to a holding facility so that Rebel agents can rescue convicted Rebel spies and sympathizers contained among the roster. We need a small team of loyal Imperial agents to obliterate this facility. The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 39, 'm10s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 40, 'm10t', 'Blast Rebel refugee facility'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 41, 'm11d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 43, 'm11s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 44, 'm11t', 'Destroy Rebel weapons cache'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 45, 'm12d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 47, 'm12s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 48, 'm12t', 'Destroy Rebel medical droids'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 49, 'm13d', 'The Rebels have been targeting Imperial depots containing laser cutters. We believe they need them to build a new operational base although we do not yet know its location. Our agents have managed, however, to locate some of these laser cutters and have sent us the coordinates where they are being housed. We need a few loyal Imperial agents to strike this storage depot.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 51, 'm13s', 'Success! This will doubtless slow the Rebels'' efforts to carve out new lairs. You''ve earned your reward, agent.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 52, 'm13t', 'No more Rebel bases'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 53, 'm14d', 'A traitorous moff has offered to aid the Rebels attempt to assassinate our beloved Emperor. We''ve pinpointed where this traitor and his agents will be meeting with the Rebellion''s agents to make the arrangements. We require an able and loyal Imperial strike team to hit this outpost and insure its destruction. Could you assemble and lead such a team?'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 55, 'm14s', 'We have not ascertained if the moff was at that meeting when you destroyed the outpost. We''ll have to continue monitoring communications. In any case, your strike against that Rebel outpost was superb.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 56, 'm14t', 'Hunt a traitorous moff'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 57, 'm15d', 'Local garrisons have reported recent Rebel attacks that have employed modified A-A5 speeder trucks as armored personnel carriers. We''ve located several civilian speeder repair facilities that could be used to create these carriers. We want these installations destroyed. Can you assist the Empire in removing this potential threat? '),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 59, 'm15s', 'Good work, agent. We knew these stations were serving those Rebel scum and you''ve helped prove it. We hope this is the beginning of a very profitable career for you.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 60, 'm15t', 'Take out Rebel repair stations'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 61, 'm16d', 'The Rebels have taken an interest in certain rare types of crystals. Intelligence has instructed us to destroy any supply depot containing caches of such minerals. We''ve located a small warehouse containing a large quantity of mineral desposits mined from the Outer Rim. We need loyal Imperial servants to vaporize this warehouse.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 63, 'm16s', 'An efficient handling of the mission, agent. Well done. The Empire is proud to reward you.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 64, 'm16t', 'Smash the mysterious crystals'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 65, 'm17d', 'We''ve been alerted to the presence of a Rebel supply depot that seems to be housing hundreds of climate control units. No doubt these are intended for remote Rebel bases in the Outer Rim. We want these units destroyed and figure a loyal and skilled Imperial agent ought to be able to take care of that for us. No need to call in a full military strike.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 67, 'm17s', 'Clean and efficient, citizen, just like we like it. COMPNOR could use more agents like you. '),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 68, 'm17t', 'Make it cold for the Rebels'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 69, 'm18d', 'We finally identified the traitor who has been supplying vacuum gyros for Rebel transports. We have the coordinates to the traitor''s secret gyro cache. Unfortunately he knows we are coming. Our sources tell us that a contingent of Rebel soldiers is evacuating the cache. We need to dispatch a team to destroy this contraband before the Rebels take it away.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 71, 'm18s', 'Well done, citizen. Those Gallifree transports slip through our blockades too easily. Perhaps now we can stop those Rebel scum.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 72, 'm18t', 'Cripple Rebel transports'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 73, 'm19d', 'Ion space mines are an important tool of the Imperial Navy, but in the hands of Rebel terrorists they become a menace to all law-abiding spacefarers. We have tracked a freighter to a known Rebel outpost, where it deposited a load of Defender-class mines. If we can wipe out this factory before its deadly contraband is unleashed, the star lanes will be safe once more.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 75, 'm19s', 'The Imperial Navy is indebted to you. Accept this payment and the gratitude of the Empire.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 76, 'm19t', 'Take out the space mines'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 77, 'm20d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was highjacked en route to a Civil Security Center on Dantooine. Intercepted Rebel transmissions suggest these droids were smuggled to a secret reprogramming facility, where technicians will turn the IGs into gardening and botanical droids. A squad must locate and destroy this facility.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 79, 'm20s', 'The Empire is grateful for your service. IG assassin droids make lousy botanical arrangements. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 80, 'm20t', 'Assassin droids do not pick posies'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 81, 'm21d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, as the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 83, 'm21s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 84, 'm21t', 'Smash a squad of X-wing fighters'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 85, 'm22d', 'We''ve discovered a local livestock dealer who harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. Certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 87, 'm22s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 88, 'm22t', 'Crush a mynock incubator'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 89, 'm23d', 'A local community has recently been plagued by a fake holovid recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility. You must take a strike team and decimate this unseemly operation. These untruths will not soil the tranquility of our loyal and obedient communities.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 91, 'm23s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 92, 'm23t', 'Raze a seditious broadcast facility'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 93, 'm24d', 'In the midst of an otherwise obedient community, the Rebellion has constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 95, 'm24s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return. '),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 96, 'm24t', 'Blast a Rebel power relay'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 97, 'm25d', 'The Inquisitorius has ordered a strike on a Rebel outpost that has been conducting unusual experiments involving the Force and Force-users. We cannot imagine that the Rebellion would be foolish enough to attempt to establish another Jedi training academy, especially in light of the corruption that was revealed within the ranks of the old Jedi Order. Can you assemble a strike team to take care of this?'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 99, 'm25s', 'A new breed of Jedi shall not rise to threaten our beloved Empire thanks to you, agent. Well done! The Emperor will hear of your success. Be proud.'),
('string/en/mission/mission_destroy_imperial_military_medium_non_persistent_from_npc.stf', 100, 'm25t', 'Destroy Rebel training outpost'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 1, 'm1d', 'We''ve discovered a Rebel recruitment station in your area. It must be wiped out immediately. These Rebel scum must be getting brave indeed to attempt to recruit openly for their traitorous cause. Can we rely on you, citizen, to make sure the Rebellion does not ensnare any more Imperial citizens? Burn this station to the ground.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 2, 'm1f', 'If the Empire cannot deal effectively with such flagrant displays of treason, what hope do you think we have of a swift victory over the Rebellion? Your failure, small though it may be, impacts the larger conflict. We must be seen as efficient, unstoppable, and relentless. We find this outcome... disturbing.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 3, 'm1i', 'Those scum move fast or else our intelligence was sabotaged by Rebel misinformation. We must put a stop to these Rebel slicers. Report to us again and we''ll give you the correct coordinates of this station.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 4, 'm1l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 5, 'm1o', 'Imperial Security Bureau ');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 6, 'm1s', 'If only we could have seen the looks on those Rebels'' faces when you torched their installation to the ground. With agents such as yourself working for us, we''ll have this Rebellion well in hand in no time. We are quite pleased, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 7, 'm1t', 'Destroy Rebel recruitment station'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 8, 'm2d', 'A small Rebel surveillance post has been located. This post has been coordinating local cell activity for months. We don''t want to bother our already overworked Imperial military with this task when we could take care of this locally. Can we rely on you, citizen, to serve your Empire and destroy this installation?  '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 9, 'm2f', 'Now the warning will go out to all the local cells and they''ll be doubly difficult to root out. This failure taints the reputation of our entire organization, citizen. How could you have let this happen? You must make amends in the future.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 10, 'm2i', 'The Rebels must have been alerted to our intentions. They can move fast, citizen. So next time we must move faster. Continue serving your Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 11, 'm2l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 12, 'm2o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 13, 'm2s', 'We''ll be monitoring the local cell activity more closely now. The destruction of the post will almost certainly throw them into confusion for a short time. We must take advantage of this moment. Our thanks, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 14, 'm2t', 'Destroy Rebel surveillance post'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 15, 'm3d', 'An informant has given us the location of a small Rebel supply depot. The informant claims the depot contains medical supplies bound for Rebel outposts in the Outer Rim. We''d like to call upon you to help us destroy this depot and deprive those scum of medical aid. Does this sound like something you could help us with? We would be most appreciative. '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 16, 'm3f', 'The last thing the Imperial military needs is healthy Rebels. How could have let those medical supplies slip through your fingers? This failure does not endear you to our organization, citizen. We are displeased.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 17, 'm3i', 'We''ll check out future informant information more carefully. Perhaps this informant was a Rebel double agent trying to throw us off the track. We''ll investigate the matter. We hope you continue to encourage business transactions between us, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 18, 'm3l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 19, 'm3o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 20, 'm3s', 'The thought of a wounded Rebel terrorist deprived of proper medical aid brings a smile to our faces, citizen. You have done well. Agents such as you are hard to come by. It is our hope you''ll continue to explore this profitable business venture.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 21, 'm3t', 'Blast Rebel medical supply depot'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 22, 'm4d', 'Rebel strike teams have been operating out of this area and have caused considerable damage to Imperial installations. We believe we''ve located their supply depot and wish you employ your services in taking it out. Are you interested in such a venture? The rewards for serving the Empire faithfully are generous indeed, citizen. Surely you''ll undertake this mission for us.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 23, 'm4f', 'How difficult could taking out a supply depot be, citizen? It''s not as if we were asking you to take out High Command itself. This sort of incompetence is hardly excuseable. You must prove your worth to the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 24, 'm4i', 'The Rebel strike team either emptied that depot or else we have to look into the possibility that our intelligence was somehow faulty. With the trillions of communiques that the Imperial Analysis Bureau must sort through every day, it''s no wonder they occasionally deliver unreliable information.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 25, 'm4l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 26, 'm4o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 27, 'm4s', 'Excellent. Our next step will be locating these strike teams and eliminating their threat. Contact us again if you wish to assist further in this matter, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 28, 'm4t', 'Take out strike team supply depot'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 29, 'm5d', 'A Rebel droid repair facility has been identified by Imperial Intelligence. This installation is small enough to not merit the attention of the Imperial Army or the stormtroopers. Therefore we must rely upon loyal, enterprising citizens such as yourself to help the Empire. Can you take care of making sure this installation does not benefit the Rebels any longer? The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 30, 'm5f', 'You couldn''t even take out a droid repair facility? Imagine what would have happened if that had been a full-fledged Rebel outpost? What would your failure have cost you then, citizen? Your life, certainly, but most importantly a grave embarrassment for our organization. COMPNOR is most displeased.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 31, 'm5i', 'We must make sure Imperial Intelligence sends us accurate reports and coordinates if we''re to effectively serve the Empire. Come and see us again, citizen. We should have this matter cleared up by then.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 32, 'm5l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 33, 'm5o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 34, 'm5s', 'Success, citizen! I can only imagine the sight - droid parts flying through the air, clouds of choking smoke, the acrid scent of burning oil. I see a long and prosperous career ahead of you, citizen. Long live the Emperor!'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 35, 'm5t', 'Destroy droid repair facility'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 36, 'm6d', 'A Rebel safe house has been located by loyal citizens. This safe house has been used in the past to shelter suspected traitors wanted for questioning by Imperial Intelligence. This refuge must be destroyed. The Empire will not tolerate anyone protecting potential criminals. The facility should not be too heavily guarded but will no doubt possess some defenses. Do you think you could assist the Empire in taking care of this problem? '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 37, 'm6f', 'No doubt many of the fugitives hiding inside were allowed to escape Imperial justice. This failure should be embarrassing to you, citizen. We''re certainly embarrassed for you.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 38, 'm6i', 'The Rebels must have moved the fugitives to another location. No worries. We''ll track them down soon enough.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 39, 'm6l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 40, 'm6o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 41, 'm6s', 'Good work, citizen. The Rebellion will learn that there is no such thing as a "safe house" for traitors. Not in this galaxy, anyway. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 42, 'm6t', 'Destroy Rebel safe house'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 43, 'm7d', 'We''ve identified an abandoned warehouse that is being used by Rebels as a clandestine meeting place. Loyal informants in the area have also seen known smugglers entering the warehouse at odd hours of the night. We don''t wish to trouble our hard-working Imperial military with this matter when we could take care of it locally. What we need is a resourceful and cunning agent to take care of this situation for us. Blasters are so effective at demolishing walls, don''t you agree? Are you the agent COMPNOR is looking for?'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 44, 'm7f', 'A simple warehouse was too much for you? What sort of agent are you, anyway? Failure is not something COMPNOR accepts easily.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 45, 'm7i', 'It seems a Rebel double agent might have slipped us some bad information. We''ll have to do a screening of all our informants again soon.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 46, 'm7l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 47, 'm7o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 48, 'm7s', 'They can run but they can''t hide. Excellent work, agent. COMPNOR is looking for more resourceful individuals like yourself. Hail the Empire! '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 49, 'm7t', 'Destroy Rebel meeting place'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 50, 'm8d', 'A Rebel courier drop off point has been brought to our attention. This facility helps sort encoded messages going to the local cells. The Empire needs this way station destroyed. It shouldn''t require more than a few resourceful Imperial agents. Do you deem yourself one of these agents? '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 51, 'm8f', 'A way station gave you trouble? How distressing. I wonder how badly you''d have failed if this had been a heavily defended Rebel base? Very disappointing.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 52, 'm8i', 'The Rebel scum must have gotten word of our impending destroy mission. Worry not, we''ll find them eventually.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 53, 'm8l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 54, 'm8o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 55, 'm8s', 'Now that is how an effective agent handles Rebel scum. Well done. COMPNOR enjoys rewarding capable agents.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 56, 'm8t', 'Take out Rebel way station'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 57, 'm9d', 'The Rebellion is trying to generate support for its traitorous cause by distributing copies of a fabricated hologram showing the destruction of Alderaan by the Empire''s peacekeeping station, the Death Star. We know that Alderaan brought about its own destruction when the supposedly peaceful planet fired an experimental doomsday weapon at the Death Star, which had entered the Alderaan system in order to place Bail Organa under arrest. The devasting weapon and Alderaan''s treachery proved to be the planet''s undoing. COMPNOR wishes to stamp out the vicious rumors that the Empire destroyed Alderaan. You can help by destroying one of these hologram duplication centers. It should not require more than a dedicated agent or two. Can you help the Empire set the record straight, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 58, 'm9f', 'A hologram duplication station should have been ion cannon fodder, citizen. Failure is simply inexcusable. We are most disappointed.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 59, 'm9i', 'There are several of these stations scattered throughout the galaxy, citizen. We must find them and destroy them. They won''t escape us for long.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 60, 'm9l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 61, 'm9o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 62, 'm9s', 'Lies have gone up in smoke, citizen. Job well done! Your work will further the cause of the New Order and serve to glorify the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 63, 'm9t', 'Destroy hologram duplication center'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 64, 'm10d', 'The Rebellion is spreading rumors that Jedi have returned and have joined the traitorous scum against the Empire. We have seen holograph posters depicting a lightsaber and bearing the ridiculous slogan "The Jedi have returned! Long live the Republic!" These holographs have been spotted with increasing frequency in the Outer Rim and are slowly making their way into the Core Worlds. COMPNOR has located a small warehouse filled with this sort of propaganda and it must bed destroyed. We doubt that it would be guarded by more than a few Rebels. Can you take care of this task for the Empire, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 65, 'm10f', 'A few Rebels defending some propaganda materials was too much for you? COMPNOR must question your loyalty to the Empire, citizen. Your failure is worrisome.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 66, 'm10i', 'They must have moved the materials elsewhere. Strange that our informants were so mistaken.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 67, 'm10l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 68, 'm10o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 69, 'm10s', 'A job well done, citizen. The Jedi have not returned and Rebellion is doomed. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 70, 'm10t', 'Remove Rebel propaganda office'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 71, 'm11d', 'A storage facility housing some outdated communications equipment and refurbished power generators is being used by the local Rebel cell to help supply their members. This equipment had been scheduled to be transported to Imperial junkyards for salvage but it seems the Rebellion got their hands on it first. Make sure this junk is not used to help the Rebellion. Those scum are like vermin and will greedily snatch up any materials they can to aid their traitorous cause. The Empire is counting on your aid, citizen. We hope you will not fail to answer the call to duty. '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 72, 'm11f', 'We simply cannot understand your failure to destroy a pile of junk and a few sentries. This does not bode well for your future with us, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 73, 'm11i', 'Our coordinates seem to have been incorrect. We''ll double-check them. Report back to us soon.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 74, 'm11l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 75, 'm11o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 76, 'm11s', 'You handled that well, citizen. It makes sense that garbage would attract garbage. You''re an efficient disposal agent.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 77, 'm11t', 'Take out parts warehouse'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 78, 'm12d', 'A small speeder repair facility has been sheltering suspected Rebels from Imperial law enforcement agents. These fugitives make contact with the local Rebel cell leaders at this garage and are transported out to various bases around the galaxy. It is our duty as loyal Imperial citizens to put this garage out of business. We hope that you will be able to take care of this situation for us. Can the Empire count on you?'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 79, 'm12f', 'Mechanics and fugitives can pose this much of a problem for you, citizen? We hope this failure is not an indication of what we should expect from you in the future.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 80, 'm12i', 'The facility''s location eludes us for now. We will straighten this out and call on you again, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 81, 'm12l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 82, 'm12o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 83, 'm12s', 'We knew you were the right agent for this job, citizen. Bravo! Your success will lead to greater and more perilous missions in the future.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 84, 'm12t', 'Destroy Rebel safe house'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 85, 'm13d', 'Our informants have alerted us that a local pharmaceutical shop is doubling as an underground clinic for Rebel agents. We must make sure that these traitors do not have access to medical care. We understand that there are no less than two bacta tanks in operation at this facility. All of this equipment must be destroyed. Are you the Imperial agent we''re looking for? This mission will require both resourcefullness and ruthlessness. Do you possess both? '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 86, 'm13f', 'You were thwarted by bacta and medics? Your failure is puzzling, citizen. We will look deeper into your background before employing you again.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 87, 'm13i', 'We''ve been misled as to the coordinates of this facility. Those Rebels excel at misdirection.'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 88, 'm13l', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 89, 'm13o', 'Imperial Security Bureau '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 90, 'm13s', 'Good work! Now we will be able to better trace Rebel agents when they are forced to use local medical clinics. The reward is yours. '),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 91, 'm13t', 'Destroy Rebel medical clinic'),
('string/en/mission/mission_destroy_imperial_non_military_easy.stf', 92, 'number_of_entries', '13'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 1, 'm1d', 'Our probe droids have located a sizable Rebel munitions depot. Taking out this supply cache would limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended. Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 3, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 4, 'm1t', 'Rebel Munitions Depot'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 7, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 8, 'm2t', 'Rebel Mining Facility'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 9, 'm3d', 'Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 11, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the ISB. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 12, 'm3t', 'Communications Array'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 13, 'm4d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility. '),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 15, 'm4s', 'You can run but you can''t hide! Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 16, 'm4t', 'Alien Refugee Outpost'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain loyal to the Empire. Can you help your Emperor stamp out this loathsome practice? '),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 19, 'm5s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. Losing your faith in the New Order is bad enough, but to lose your mind along with it? You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 20, 'm5t', 'Rebel Indoctrination Camp'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. We require a loyal citizen of the Empire to burn this installation to the ground. Are you the agent we''re looking for?'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 23, 'm6s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen. We hope this is a definite indication of things to come.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 24, 'm6t', 'Terrorist Cell'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 25, 'm7d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost. We need a trusted agent to lead a strike against this installation and insure its destruction. There''s no telling how many cells this depot has been supplying or how many Imperial lives have been lost as a result.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 27, 'm7s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 28, 'm7t', 'Rebel Supply Depot'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 29, 'm8d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their traitorous cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots to play around with. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 31, 'm8s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous indeed. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 32, 'm8t', 'Rebel Training Station'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 33, 'm9d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 35, 'm9s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 36, 'm9t', 'Slicer Hub'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 37, 'm10d', 'Agents within the CSA have informed Intelligence that many of the workers the Viceprexes are requesting for hard labor are being transferred to a holding facility so that Rebel agents can rescue convicted Rebel spies and sympathizers contained among the roster. We need a small team of loyal Imperial agents to obliterate this facility. The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 39, 'm10s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 40, 'm10t', 'Refugee Facility'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 41, 'm11d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 43, 'm11s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 44, 'm11t', 'Weapons Cache'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 45, 'm12d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 47, 'm12s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 48, 'm12t', 'Rebel Medical Droids'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 49, 'm13d', 'The Rebels have been targeting Imperial depots containing laser cutters. We believe they need them to build a new operational base although we do not yet know its location. Our agents have managed, however, to locate some of these laser cutters and have sent us the coordinates where they are being housed. We need a few loyal Imperial agents to strike this storage depot.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 51, 'm13s', 'Success! This will doubtless slow the Rebels'' efforts to carve out new lairs. You''ve earned your reward, agent.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 52, 'm13t', 'Laser Cutter Storage Depot'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 53, 'm14d', 'A traitorous Moff has offered to aid the Rebels attempt to assassinate our beloved Emperor. We''ve pinpointed where this traitor and his agents will be meeting with the Rebellion''s agents to make the arrangements. We require an able and loyal Imperial strike team to hit this outpost and insure its destruction. Could you assemble and lead such a team?'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 55, 'm14s', 'We have not ascertained whether the Moff was at that meeting when you destroyed the outpost. We''ll have to continue monitoring communications. In any case, your strike against that Rebel outpost was superb.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 56, 'm14t', 'Hunt a Traitorous Moff'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 57, 'm15d', 'Local garrisons have reported recent Rebel attacks that have employed modified A-A5 speeder trucks as armored personnel carriers. We''ve located several civilian speeder repair facilities that could be used to create these carriers. We want these installations destroyed. Can you assist the Empire in removing this potential threat? '),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 59, 'm15s', 'Good work, agent. We knew these stations were serving those Rebel scum and you''ve helped prove it. We hope this is the beginning of a very profitable career for you.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 60, 'm15t', 'Take Out Rebel Repair Stations'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 61, 'm16d', 'The Rebels have taken an interest in certain rare types of crystals. Intelligence has instructed us to destroy any supply depot containing caches of such minerals. We''ve located a small warehouse containing a large quantity of mineral desposits mined from the Outer Rim. We need loyal Imperial servants to vaporize this warehouse.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 63, 'm16s', 'An efficient handling of the mission, agent. Well done. The Empire is proud to reward you.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 64, 'm16t', 'Smash Mysterious Crystals'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 65, 'm17d', 'We''ve been alerted to the presence of a Rebel supply depot that seems to be housing hundreds of climate control units. No doubt these are intended for remote Rebel bases in the Outer Rim. We want these units destroyed and figure a loyal and skilled Imperial agent ought to be able to take care of that for us. No need to call in a full military strike.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 67, 'm17s', 'Clean and efficient, citizen, just like we like it. COMPNOR could use more agents like you. '),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 68, 'm17t', 'Make It Cold for the Rebels'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 69, 'm18d', 'We finally identified the traitor who has been supplying vacuum gyros for Rebel transports. We have the coordinates to the traitor''s secret gyro cache. Unfortunately he knows we are coming. Our sources tell us that a contingent of Rebel soldiers is evacuating the cache. We need to dispatch a team to destroy this contraband before the Rebels take it away.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 71, 'm18s', 'Well done, citizen. Those Gallifree transports slip through our blockades too easily. Perhaps now we can stop those Rebel scum.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 72, 'm18t', 'Cripple Rebel Transports'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 73, 'm19d', 'Ion space mines are an important tool of the Imperial Navy, but in the hands of Rebel terrorists they become a menace to all law-abiding spacefarers. We have tracked a freighter to a known Rebel outpost, where it deposited a load of Defender-class mines. If we can wipe out this factory before its deadly contraband is unleashed, the star lanes will be safe once more.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 75, 'm19s', 'The Imperial Navy is indebted to you. Accept this payment and the gratitude of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 76, 'm19t', 'Take Out Space Mines'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 77, 'm20d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was hijacked en route to a Civil Security Center on Dantooine. Intercepted Rebel transmissions suggest these droids were smuggled to a secret reprogramming facility, where technicians will turn the IGs into gardening and botanical droids. A squad must locate and destroy this facility.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 79, 'm20s', 'The Empire is grateful for your service. IG assassin droids make lousy botanical arrangements. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 80, 'm20t', 'Assassin Droids Do Not Pick Posies'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 81, 'm21d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, as the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 83, 'm21s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 84, 'm21t', 'X-Wing Fighter Squad'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 85, 'm22d', 'We''ve discovered a local livestock dealer who harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. Certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 87, 'm22s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 88, 'm22t', 'Mynock Incubator'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 89, 'm23d', 'A local community has recently been plagued by a fake holovid recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility. You must take a strike team and decimate this unseemly operation. These untruths will not soil the tranquility of our loyal and obedient communities.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 91, 'm23s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 92, 'm23t', 'Seditious Broadcast Facility'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 93, 'm24d', 'In the midst of an otherwise obedient community, the Rebellion has constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 95, 'm24s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return. '),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 96, 'm24t', 'Rebel Power Relay'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 97, 'm25d', 'The Inquisitorius has ordered a strike on a Rebel outpost that has been conducting unusual experiments involving the Force and Force-users. We cannot imagine that the Rebellion would be foolish enough to attempt to establish another Jedi training academy, especially in light of the corruption that was revealed within the ranks of the old Jedi Order. Can you assemble a strike team to take care of this?'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 99, 'm25s', 'A new breed of Jedi shall not rise to threaten our beloved Empire thanks to you, agent. Well done! The Emperor will hear of your success. Be proud.'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 100, 'm25t', 'Jedi Training Outpost'),
('string/en/mission/mission_destroy_imperial_non_military_easy_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 1, 'm1d', 'A Rebel strike team''s base has been located by our Analysis Bureau but we suspect they are aware of this and are already preparing to evacuate. Our team of storm commandos would never arrive in time to make sure these Rebels paid the ultimate price for their treason. We must call upon you, one of our most trusted agents, to lead this operation personally. These strike team operatives are incredibly dangerous and very well trained. We trust your skills and instincts will serve you well. Destroy this outpost and make an example of these terrorists. We''re counting on you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 2, 'm1f', 'We had come to expect so much more from you. How could you have allowed any of them to escape? Your failure must be reported to the Emperor and he is not a very forgiving man. We hope for your sake he''ll be lenient with you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 3, 'm1i', 'Those strike teams move fast and are experts of leaving no evidence behind. We''ll track them down and find out why we were thrown off the scent so easily.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 4, 'm1l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 5, 'm1o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 6, 'm1s', 'This is why we chose you for this mission. We knew you would not disappoint the Empire. It is agents like you that will insure we crush the Rebellion. Long live the Emperor!'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 7, 'm1t', 'Destroy Rebel strike team''s base'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 8, 'm2d', 'A Rebel SpecForces training facility has been uncovered by one of our covert operatives. Rebel data slicers would no doubt intercept any search and destroy orders we might send to the storm commandos and warn the facility. They would not suspect, however, that we would assign a few individual agents to take care of this installation. Agents such as yourself could use stealth to approach the training facility, and then employ your amazing combat skills to eradicate it. Can you tackle such a difficult mission?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 9, 'm2f', 'Your failure has allowed many of these Rebel commandos to escape. We wish we had chosen an agent more judiciously. How can you expect the Empire to honor your name when you give us reasons to doubt your abilities? You must redeem yourself in the Emperor''s eyes.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 10, 'm2i', 'We must question our covert operative more closely. Perhaps they were suspected of being a double agent and fed misinformation by the SpecForces commandos. At these high levels it is difficult to know who to trust.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 11, 'm2l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 12, 'm2o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 13, 'm2s', 'Your name will be honored in our ranks. If you continue in this vein, your presence may be requested by the Emperor himself. Perhaps you will serve under Lord Vader. A great honor indeed.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 14, 'm2t', 'Destroy Rebel SpecForces training facility'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 15, 'm3d', 'We''ve located a Rebel covert team''s base. We believe this team has been responsible for conducting several sabotage missions against Imperial shipyards. Our intelligence even informs us that the traitor, Crix Madine, has been known to make visits to this base.  This base must be annihilated, especially if we think there is a chance of taking out Madine. This mission will require the highest degree of skill and a good deal of efficient brutality. You seem to be the right agent to lead such an operation. Can the Empire rely on your loyalty and service?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 16, 'm3f', 'If Crix Madine was in that base, we''ll never know. This failure has allowed many of the Rebellion''s finest commandos to escape. How could we have been so mistaken in choosing you for such a delicate and dangerous mission? We hope you will find a way to redeem yourself in our eyes.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 17, 'm3i', 'Madine must have gotten word of our imminent attack and evacuated his strike team. That devil is crafty and elusive. But we''ll catch him eventually. Report back to us later and we''ll see if we''ve acquired new information regarding his whereabouts.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 18, 'm3l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 19, 'm3o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 20, 'm3s', 'You did such an excellent job, we hope there''s enough evidence left for our forensic techs to sift through to search for Crix Madine. You make us proud, agent. You will no doubt help lead our glorious Empire in crushing this foolish Rebellion.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 21, 'm3t', 'Destroy Rebel covert team''s base'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 22, 'm4d', 'One of the Rebellion''s Procurement and Supply command centers has been identified. This base coordinates a good deal of the Rebellion''s logistics and we suspect that it may house the Rebel known as Targeter. The destruction of this facility along with the death of Targeter would be a great victory for the Empire. It will not be an easy mission but this is precisely why we have contacted you. You come through for us several times in the past. Can you undertake this vitally important mission? '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 23, 'm4f', 'Destroying the Rebels'' command center that regulates their supply lines would have crippled their entire organization. Instead, they are now aware that our intelligence agents must be planted deep within their hierarchy for us to have orchestrated this attack. Your failure has cost the Empire a great deal. The Emperor is demanding a full report. Your name will appear on that report. ');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 24, 'm4i', 'Could Targeter have known of this attack and sent us false intelligence? We must investigate this situation. We will find this command center. The Empire does not fail.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 25, 'm4l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 26, 'm4o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 27, 'm4s', 'This will probably cripple this sector''s Rebel cells and will greatly impact the Rebellion''s ability to perform future sabotage missions. Well done, agent. A full report of your success will be sent to the Emperor. I would not be surprised if you received a summons to Imperial Center in the near future.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 28, 'm4t', 'Destroy Procurement and Supply command center'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 29, 'm5d', 'We believe we''ve located the site of a future Rebel operational base. Our intelligence reports indicate that the base is still relatively small but these Rebel outposts can literally spring up overnight. Rather than call in a Star Destroyer strike, which would no doubt alert Rebel spies watching the movements of our fleet, we''d like our covert agents to deal with this situation. A few deadly individuals can be just as effective as a legion of stormtroopers if they are used correctly. Are you capable of handling such a perilous mission? It will take careful planning and a decisive and precise strike to destroy that base.  '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 30, 'm5f', 'So they escaped you. This is both disappointing and embarrassing. We trusted you with this task. We sent our assurances to the Emperor himself that this base would be eradicated. Your failure will cost the Empire dearly. We will not soon forget this incident.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 31, 'm5i', 'Those Rebel slicers are good. They''re very good. They must have tampered with our intelligence reports. We must send word to the Emperor that Blackhole must double his efforts to find these HoloNet pirates and deal with them. Worry not, we''ll locate this operational base in due time.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 32, 'm5l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 33, 'm5o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 34, 'm5s', 'It is no wonder you are known and feared throughout the Empire. You represent the finest our organization has to offer. Congratulations. This victory will dominate conversations on Imperial Center for some time to come.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 35, 'm5t', 'Destroy Rebel operation base'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 36, 'm6d', 'Months ago we''d learned that the Rebels had moved many of their scientists, technicians, and Incom engineers to a secret research facility. We''ve now located that facility. A successful strike against that base would be a devastating blow to the Rebellion and a major victory for the Empire. We''d like to arrange for a covert strike and believe that you are the agent most qualified to lead such an operation. Will you serve your Emperor and do your part to crush these Rebels? Losing the ability to design new starfighters and improve defenses would aid our armada in finishing the Rebels off.  '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 37, 'm6f', 'As if squadrons of X-wings were not bad enough, now those Rebels will have access to all manner of new starfighter designs. All of this because of your failure to complete this mission. This will be reported to Imperial High Command. We''ll see what they recommend be done with you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 38, 'm6i', 'They must be using some sort of holographic image disguiser but I''ve never heard of one capable of shielding an entire facility. Perhaps they''ve adapted a cloaking device? We must find those Incom engineers and cripple the Rebellion''s arsenal of new weapons.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 39, 'm6l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 40, 'm6o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 41, 'm6s', 'Burn, Rebellion, burn! Most excellent! Without their precious engineers to design new starfighters and weapons for them, the Rebellion is doomed. You should feel proud, loyal agent, for you are carving your place in history.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 42, 'm6t', 'Destroy Rebel research facility'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 43, 'm7d', 'A substantial number of traitorous Imperial officers defected to the Rebellion a few weeks ago. We''ve learned where the Rebels are housing these traitors and their families. This facility will be very well defended as the Rebellion needs the knowledge possessed by these officers to help devise effective defense strategies. You must lead a mission to destroy this facility. You can strike silently and quickly, giving the Rebels less of an opportunity to mount an organized defense. Can we count on you to undertake this vital mission for the Empire?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 44, 'm7f', 'Those traitors carried Imperial secrets! How could you have failed? Now the Rebels will be even more effective against the Imperial military and more loyal mens'' lives will be lost. All due to your failure. If you are ever to accept another mission from our bureau, you must work very hard to redeem yourself in our eyes, agent.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 45, 'm7i', 'They must have moved those officers somewhere else. This is a Rebel trick. They''re trying to throw us off the track. We''ll find where those treasonous neks are lurking, we promise you that.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 46, 'm7l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 47, 'm7o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 48, 'm7s', 'This victory will be an example to other officers. There is only one result of betraying the Empire - death! Well done, agent. We knew we could count on you. Your efficiency (and if I may say, your artistic brutality) shall be reported to the Emperor. He rewards agents like you most generously.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 49, 'm7t', 'Destroy Rebel defector colony'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 50, 'm8d', 'A Rebel starfighter refueling station has been identified by one of our probe droids. We believe this station has aided the Rebel starfighter unit known as Rogue Squadron to carry out strikes against Imperial shipyards. Destroy this station and make sure those Rebel pilots are stranded on this planet next time they land to refuel. Perhaps we''ll have several squads of stormtroopers ready to greet them. You will do this for the Empire, correct?  '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 51, 'm8f', 'Without fuel, Rebel starfighters cannot fly. How can this one important detail escape you? Failing to destroy that refueling station is as good as serving the Rebellion. Our TIE pilots'' lives were depending on you. They will pay the ultimate price for your failure.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 52, 'm8i', 'We''ll double-check the coordinates but we''re certain the probe droid gave us the correct ones. Could the Rebels be using some form of holocloak shield?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 53, 'm8l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 54, 'm8o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 55, 'm8s', 'When those X-wings start falling out of the sky, you can pat yourself on the back. Well done. Let''s see how far those Rebel flyboys get without their precious fuel. Report to us in the future for more missions.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 56, 'm8t', 'Blow up Rebel refueling station'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 57, 'm9d', 'We''ve identified a major Rebel communications facility housing a series of sophisticated HoloNet transceivers. We believe this is a HoloNet hub where Imperial classified information stolen by the Rebellion''s best data slicers is routed and transmitted to the Rebel High Command. This facility must be destroyed. Your track record puts you high on the list of possible agents that could lead such an assault. Information is power, as we know, and therefore cutting the Rebels'' source of it will effectively blind them. Can the Empire count on your service?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 58, 'm9f', 'The efforts of these data slicers, perhaps more than anything else, has been responsible for hampering the efforts of the Imperial Navy to destroy Rebel bases. Your failure will cost the Empire dearly. How could you have risen so far if this is the typical result of your attempts? A full report will be sent to Imperial Center. Blackhole will no doubt wish you to address this issue in the near future.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 59, 'm9i', 'And now you see why we must stop those data slicers? It is situations like this that show the effectiveness of falsified intelligence reports. When we locate this HoloNet hub, we will act swiftly.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 60, 'm9l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 61, 'm9o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 62, 'm9s', 'Success! Now let''s see how effective those Rebels are at intercepting our communiques. Cutting off the Rebellion''s source of information is like cutting off their right arm. Most excellent, agent. We are more than pleased and will reward you accordingly.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 63, 'm9t', 'Destroy Rebel HoloNet hub'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 64, 'm10d', 'The Rebellion has been employing many smugglers and shipjackers to assist in their terrorist activities. Intelligence has learned that a major contact for these criminals is a Corellian pirate named Han Solo. We''ve located a Rebel outpost that is used primarily to host clandestine meetings between these pirates and Captain Solo. The base also serves as a hideout for many of the galaxy''s most notorious smugglers, aiding them with repairs and refueling in exchange for services to the Rebellion. We need a trusted agent to lead an attack on this outpost and destroy it utterly. With any luck, you''ll be able to take out Captain Solo himself. Careful, however, for we understand this Corellian can be a pretty tricky and dangerous individual and he travels with a rather large Wookiee. Are you the agent the Empire needs? '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 65, 'm10f', 'You ruin your chance to rid the Empire of a notorious gang of criminals and terrorists? Why? Failure was not an option. This black mark on your record will no doubt influence the caliber of missions the Empire assigns you in the future. If they assign any at all, that is.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 66, 'm10i', 'We should have known that a den of deceivers and tricksters would be difficult to pin down. We were warned that Solo was a clever smuggler. It seems those warnings were not exaggerated.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 67, 'm10l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 68, 'm10o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 69, 'm10s', 'A major victory for the Empire and a serious blow to the galaxy''s criminal element. We can only hope Captain Solo and his furry lackey were inside that base when it was destroyed. You''re an agent the Empire will keep in mind in the future. Efficiency and results such as yours is the sort of thing the Empire prizes most. Imperial High Command may decide to give you a medal. You''ve earned your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 70, 'm10t', 'Destroy Rebel smuggler outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 71, 'm11d', 'The Rebellion has managed to rescue many former senators and intend to use their political influence to aid their treasonous cause. Many of these former bureaucrats are in the process of being relocated. We''ve obtained the coordinates for one of the facilities currently housing several of these senators. We don''t need to tell you how important it is for the Empire to prevent these politicians from throwing their support behind the Rebellion. Make sure this facility is utterly destroyed. The Rebels will have some of their best fighters guarding these former senators so it will take an experienced team to insure success on this mission. How soon could you assemble your team and be ready to go? The Empire is placing a huge deal of trust in your skills, agent. '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 72, 'm11f', 'Those senators will be a great boon to the Rebellion for they can sway their systems to side with the Rebels. Your failure will cost us dozens if not hundreds of worlds. A failure of this magnitude must be reported to the Emperor and the Imperial High Command. Be prepared to travel to Imperial Center to answer for this failure. '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 73, 'm11i', 'The Rebellion is taking every precaution to hide these senators. They have obviously fed false information into the HoloNet via top slicers. We''ll find these politicians and deal with them.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 74, 'm11l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 75, 'm11o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 76, 'm11s', 'Your precision and effectiveness is a thing of beauty, agent. Congratulations! The Emperor will want to hear of your success. You will be spoken of highly at Imperial Center.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 77, 'm11t', 'Destroy senators'' hideout'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 78, 'm12d', 'Not only have we located an X-wing pilot training facility, we understand that the Rebel known as Wedge Antilles, one of the surviving pilots of the Battle of Yavin, often makes visits to this installation to supervise the training and select pilots for his despicable Rogue Squadron. We''d like a skilled strike team of commandos to hit this training facility and obliterate it. With any luck, the team will also take out the terrorist and murderer Antilles before he can lead any more raids against Imperial shipyards. Can the Empire count on you for this mission? Do you have what it takes to accomplish this?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 79, 'm12f', 'We find your failure most disturbing and will send word of it to Lord Vader, who was following this mission closely. Good luck to you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 80, 'm12i', 'Where does the Rebellion get these skilled slicers? We grow tired of their efforts to feed us false information.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 81, 'm12l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 82, 'm12o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 83, 'm12s', 'Haha! A brilliant attack, agent! The fewer X-wing pilots the Rebellion has the easier it will be to destroy their ragtag fleet. Your success will be reported to Lord Vader himself.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 84, 'm12t', 'Destroy pilot training facility'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 85, 'm13d', 'A failed slave revolt on Kashyyyk resulted in the loss of several loyal Imperial servants. Many of the revolt''s Wookiee leaders escaped Imperial authorities and have been sheltered by the Rebellion. We believe we have located the Rebel facility housing these murderers and insurrectionists. It is also our understanding that the Wookiee Chewbacca, one of the terrorists that engaged in the assault on the Death Star, has been known to visit this facility to help in assigning his fellow Wookiees to other Rebel outposts. This facility must be destroyed at all costs. No doubt the Rebels conduct all manner of treasonous activity at this outpost. Killing Chewbacca and the Wookiees would be a wonderful bonus. This mission will doubtless be quite perilous. Can the Empire rely on you as it has for so many other missions in the past? Only an elite team of loyal Imperial agents has a hope of accomplishing this.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 86, 'm13f', 'Many important Wookiee leaders would have been removed if you had not failed. Now we will never know Chewbacca''s fate. No doubt he escaped. This failure will be a costly one.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 87, 'm13i', 'The Rebels have tampered with our intelligence. It surprises us that our coordinates could have been wrong. We will rectify this situation.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 88, 'm13l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 89, 'm13o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 90, 'm13s', 'Bravo! They say Wookiees are cold-blooded killers but they pale in comparison to dedicated Imperial agents such as yourself. We can only hope that Chewbacca was among the dead before they were incinerated. The Empire is proud of you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 91, 'm13t', 'Destroy fugitive outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 92, 'm14d', 'A major Rebel fleet resupply outpost has been located by our spies. It is our understanding that the traitorous Mon Calamari, Ackbar, is a frequent visitor to this outpost, which supplies a good third of the Rebel fleet. This outpost''s defenses will be formidable. Only a surprise attack by an elite Imperial strike team has any hope of success. Do you think you could assemble and lead such a strike team? An decisive strike could effectively cripple the Rebel fleet. Can the Imperial High Command count on your aid?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 93, 'm14f', 'We knew this would be a difficult mission but your failure greatly disappoints us nonetheless. It is likely Ackbar escaped, if he was there. The Imperial High Command had high hopes for you and your team.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 94, 'm14i', 'Our spies were either tricked or there is a Rebel double agent in their ranks. We shall determine which soon enough.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 95, 'm14l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 96, 'm14o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 97, 'm14s', 'A decisive victory for the Empire! We knew we could count on you, agent. Keep this up and the Emperor may soon ask for you to serve at his side. Hail the Empire!'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 98, 'm14t', 'Destroy Rebel fleet resupply outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 99, 'm15d', 'A Rebel medical outpost has acquired several metric tons of Thyferran high-grade bacta. The rejuvenatory fluid is scheduled to be transported to several major Rebel bases in the Outer Rim, we think in preparation for a major Rebel assault on Imperial shipyards. We must strike this outpost and destroy the bacta before the Rebels can ship it out. These scum will be protecting this precious cargo and will fight fiercely to preserve it. An elite Imperial strike team should be able to penetrate the base''s perimeter defenses and strike at the heart of the outpost before the Rebels mount a major defensive. Can the Empire count on you to assemble and lead this team? The Emperor himself would receive word of your mission. '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 100, 'm15f', 'That bacta will save many Rebel lives, agent. Your failure is a disappointment to us all. As promised, the Emperor will receive word of your mission.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 101, 'm15i', 'Rebel data slicers continue to plague our intelligence reports. Check back with us soon and we''ll have the correct coordinates to that outpost.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 102, 'm15l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 103, 'm15o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 104, 'm15s', 'Your strike was conducted with a surgeon droid''s precision, agent. Well done! The Emperor will receive word of your success.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 105, 'm15t', 'Destroy Rebel medical outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 106, 'm16d', 'Our spies have informed us that a secret meeting is taking place between agents of certain financial leaders of the Expansion Region and the Rebellion. Apparently, the Rebels hope to secure more funding through these agents. We have obtained the coordinates of that clandestine rendezvous and need to insure that this meeting does not take place. Rumors have indicated that none other than Princess Leia Organa herself may be in attendance at this meeting. We don''t need to tell you what a great victory it would be for the Empire to remove this Rebel agent, who, may we point out, made the destruction of the Death Star possible. A skilled strike team must be assembled and deployed at once. Speed is of the essence on this mission. Can you carry out this search-and-destroy mission for the Empire?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 107, 'm16f', 'This failure will almost assuredly mean more funding for the Rebellion as well as the escape of the traitor Leia Organa. We are shocked and dismayed, agent. It seems we were wrong about your abilities.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 108, 'm16i', 'We should have expected Rebel slicer interference on this mission. Our coordinates have been sabotaged. We will get to the bottom of this.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 109, 'm16l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 110, 'm16o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 111, 'm16s', 'You''ve sent a clear message to the business leaders of the Expansion Region, agent. Well done! We can only hope that Leia Organa was in attendance and that she has finally met with Imperial justice.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 112, 'm16t', 'Destroy Rebel rendezvous site'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 113, 'm17d', 'We have acquired the coordinates to a Rebel outpost serving as a strategic command center for many of the Rebellion''s top military advisors, including senior advisors to Mon Mothma herself. Taking this command center out would not only rob the Rebellion of many of its leaders, it would also throw the Rebellion''s current slate of sabotage missions into disarray. This outpost will be heavily guarded and well defended. A small strike team, however, might be able to strike deep into the heart of the base before the Rebels could rally an effective defense. The Empire wants to know if it can count on you to undertake this dangerous mission. It will take a high degree of training, skill, and luck to accomplish this task. The right team must be chosen and the attack carefully planned. '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 114, 'm17f', 'Despite knowing that this mission would be difficult to accomplish, we cannot help but feel a great deal of disappointment, agent. We felt that you would not fail at this task. We were wrong.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 115, 'm17i', 'Our coordinates should not have been wrong. Rumor has it that the Bothan SpyNet has been feeding us false information. It seems that rumor may be a fact.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 116, 'm17l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 117, 'm17o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 118, 'm17s', 'Most effective, agent! Your skill and methods are not just legendary, it seems. Our gratitude goes with you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 119, 'm17t', 'Destroy Rebel command center'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 120, 'm18d', 'Worker refugee camps have become notorious breeding grounds for Rebels. Unemployed and dispirited malcontents are drawn to the Rebellion like flies to a carcass. We need a team of loyal Imperial agents to remove these installations as quickly as we can identify them, before they can give birth to a new host of traitorous vermin. Many of these workers are miners and well-armed - they''re used to dealing with pirates and smugglers who prey upon them. And the Rebellion will likely have sent several Rebel soldiers to help maintain order and recruit these wretches. Wipe these camps out, agent. View this as a high level extermination assignment with yourself and your team as the Imperial cleanup crew. Can we rely on you?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 121, 'm18f', 'We knew these workers would be tough to handle, but we had hoped you could accomplish it. It seems we both failed to call this one correctly, eh, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 122, 'm18i', 'These camps are scattered throughout the galaxy and we must find them all. It seems this will be prove more challenging than we had first anticipated.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 123, 'm18l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 124, 'm18o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 125, 'm18s', 'Keep this up and you''ll become our exterminator extraordinaire, agent. Good work! The Empire needs more agents like yourself.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 126, 'm18t', 'Destroy refugee camp'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 127, 'm19d', 'When will these Rebels learn that they cannot shield themselves with civilians or hide inside of legitimate civilian facilities? A major medical center servicing many local systems has been unmasked as a Rebel medical supply depot. These scum don''t seem to care if they endanger the locals with these charades. Indeed they rely upon these hapless beings to help them pull off these ridiculous deceptions. Yet we must be stronger than our adversaries. The deaths of all those ailing locals will be upon the heads of the Rebellion''s leaders - the innocent blood will be on their hands. We need a team of loyal agents to strike this medical center and wipe out the Rebel scum hiding inside of its walls. Show no mercy, no compassion. The Rebels will get what they deserve. Can you lead this operation?  '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 128, 'm19f', 'Your failure shows both a lack of skill and dedication, agent. We must review your suitability for future missions of this sort.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 129, 'm19i', 'It makes sense that the Rebels would try to hide a facility like this. We''ll get the correct coordinates and strike soon, we promise you that.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 130, 'm19l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 131, 'm19o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 132, 'm19s', 'Your work is as efficient and excellent as we''d been led to believe, agent. Congratulations! We''ll seek you out in the future.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 133, 'm19t', 'Destroy Rebel medical center'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 134, 'm20d', 'A Rebel SpecForce commando team is preparing to undertake an assassination mission aimed at one of our Imperial Grand Moffs. This Imperial dignitary has served the Empire well, spearheading the development of many new weapons equivalent to the Death Star in effectiveness. We cannot allow this Imperial hero to meet with foul play at the hands of Rebel scum. We need a commando team of our own to strike the Rebel SpecForce''s headquarters and wipe the Rebel team out before they can embark upon their murderous mission. Could you assemble and lead such a team, agent? You will likely meet with great resistance and will face some of the Rebellion''s most elite troopers. Can someone like you resist the lure of this task?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 135, 'm20f', 'We will try to keep word of this failure from leaking out. After all, it would not do to let the Rebels think their commando teams are more effective than ours. We are deeply shamed.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 136, 'm20i', 'Those Rebels are as elusive as the mythical titavian. But as with that monstrous reptavian, enough searching will yield results.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 137, 'm20l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 138, 'm20o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 139, 'm20s', 'Training and dedication will always win out in the end. Excellent work, agent! Once again you''ve helped prove the Empire''s military superiority. '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 140, 'm20t', 'Destroy Rebel SpecForce base'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 141, 'm21d', 'A Rebel guerrila training camp has been discovered by an Imperial probe droid. These camps are especially dangerous as they recruit and train the local population to rise up against the Empire. Further, these Rebels often equip these communities, many of them peaceful agrarian societies, with deadly weapons of mass destruction. This only serves to transform local bullies and gang lords into dangerous armed despots. If only the Rebellion truly understood the consequences of their actions. In any case, Imperial High Command needs a loyal team of agents to descend upon this camp and obliterate it. We will not allow terrorist training camps to exist within the borders of our Empire. Are you the agent the Emperor needs to serve in this capacity?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 142, 'm21f', 'Your failure means that many of these terrorists escaped and will likely plague the Empire in the future. The only good Rebel is a dead one, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 143, 'm21i', 'They must have moved their training camp, which means they know we''re on to them. Check back with us soon for it will only be a matter of time before we locate this guerrila camp.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 144, 'm21l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 145, 'm21o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 146, 'm21s', 'No future terrorists will come from this camp. Well done, agent. Your services to the Empire will be greatly rewarded.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 147, 'm21t', 'Destroy Rebel guerilla camp'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 148, 'm22d', 'We''ve received a request from the Inquisitorius to strike a Rebel outpost as soon as possible. Apparently our intelligence has indicated that this outpost has been conducting some unusual experiments involving the Force and Force-users. The Inquisitorius was clear that there are to be no survivors. We cannot imagine that the Rebellion would be foolish enough to attempt to establish another Jedi training academy, especially in light of the corruption that was revealed within the ranks of the old Jedi Order, but those Rebel scum have surprised us before. Can you assemble a strike team to take care of this? You must be prepared to face highly skilled Rebel commandos and possibly even Force-users. Remember, the Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 149, 'm22f', 'Force-users allying with the Rebellion is bad enough, agent. Your failure to stop them is truly criminal. The Emperor must be notified of your failure. Pray he doesn''t send for you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 150, 'm22i', 'Those Force-users have been known to use mind tricks before. Perhaps they clouded the minds of our spies when it came to acquiring these coordinates.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 151, 'm22l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 152, 'm22o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 153, 'm22s', 'A new breed of Jedi shall not rise to threaten our beloved Empire thanks to you, agent. Well done! The Emperor will hear of your success. Be proud.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 154, 'm22t', 'Destroy Rebel training outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 155, 'm23d', 'We finally have a rare opportunity to take out the Rebellion''s highest profile leader herself, Mon Mothma. Our intelligence reports that she will be making an inspection of a Rebel outpost currently housing some former senators'' families - she wants to make sure these individuals are comfortable and safe. We need a skilled strike team to show her just how "safe" this outpost really is. A chance like this only comes once in a lifetime, agent. Can you assemble and lead such a team? Your victory may well mean the end of the Rebellion. Can you afford to pass this golden opportunity by? You''d be the Champion of the Empire. If you succeeded, that is.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 156, 'm23f', 'The moment passed you by, agent. Your failure is the Empire''s loss. How could the importance of such a mission have eluded you?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 157, 'm23i', 'These incorrect coordinates proved Mon Mothma was to be at that base. Why else would we have gotten them wrong? There was sabotage at work here.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 158, 'm23l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 159, 'm23o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 160, 'm23s', 'The good news is that this outpost will no longer be a threat to us. Good work, agent. The bad news is that Mon Mothma was not at that base when it was destroyed. Our spies confirmed this shortly after you''d begun your attack. We''ll get her next time, though. Claim your just reward.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 161, 'm23t', 'Destroy Rebel outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 162, 'm24d', 'Sending those tens of thousands of probe droids into the far reaches of the galaxy has begun to pay off. One of them has located a Rebel strike team''s base. This facility has been used to both train commandos and plan sabotage and assassination missions. Taking this installation out would be a great victory for the Empire. We need a dedicated team of skilled Imperial agents to execute this attack. Some of the Rebellion''s best troopers are located here so it will take some of the Empire''s best to eliminate them. Only experienced teams with a proven track record need apply. The Empire''s gratitude will be showered on the team that succeeds. '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 163, 'm24f', 'Failure not only means no reward, it also means a permanent mark on your record. How disappointing you turned out to be.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 164, 'm24i', 'There''s been a disconnect between our division and the Analysis Bureau. We''ll discover what it was and correct it.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 165, 'm24l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 166, 'm24o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 167, 'm24s', 'These are the sorts of results we''ve come to expect from you, agent. Well done. Your reward awaits you. Continue to serve your Empire faithfully and there will be many more such rewards.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 168, 'm24t', 'Destroy Rebel strike team''s base'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 169, 'm25d', 'We have reasons to suspect that a few of the Corporate Sector Authority''s Viceprexes have been secretly aiding the Rebellion. Our intelligence indicates that these Viceprexes make occasional visits to a major Rebel supply depot, to claim certain confiscated goods for themselves such as large hauls of glitterstim spice. A strike at this supply depot would not only eliminate this valuable source of materials for the Rebellion it might also catch one or more of these traitorous Viceprexes in the crossfire. We need a strike team to obliterate this supply depot as soon as possible. The Viceprexes are cautious individuals so the base will be well defended during one of their visits. Are you the agent the Empire needs to execute this mission flawlessly?'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 170, 'm25f', 'Not only did fail to destroy one of the Rebellion''s major supply depots, you no doubt allowed some Viceprexes to escape. Is failure of this magnitude common for you?  '),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 171, 'm25i', 'Viceprexes often employ top data slicers to help hide their movements. This is obviously what occurred here. We''ll track this depot down.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 172, 'm25l', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 173, 'm25o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 174, 'm25s', 'A bit crude in it''s execution, perhaps, but effective nonetheless. Congratulations, agent. Your reward is well earned.'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 175, 'm25t', 'Destroy major Rebel supply depot'),
('string/en/mission/mission_destroy_imperial_non_military_hard.stf', 176, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 1, 'm1d', 'Our probe droids have located a sizable Rebel munitions depot. Taking out this supply cache would limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended. Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 3, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 4, 'm1t', 'Rebel Munitions Depot'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 7, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 8, 'm2t', 'Rebel Mining Facility'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 9, 'm3d', 'Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 11, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the ISB. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 12, 'm3t', 'Communications Array'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 13, 'm4d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility. '),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 15, 'm4s', 'You can run but you can''t hide! Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 16, 'm4t', 'Alien Refugee Outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain loyal to the Empire. Can you help your Emperor stamp out this loathsome practice? '),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 19, 'm5s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. Losing your faith in the New Order is bad enough, but to lose your mind along with it? You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 20, 'm5t', 'Rebel Indoctrination Camp'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. We require a loyal citizen of the Empire to burn this installation to the ground. Are you the agent we''re looking for?'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 23, 'm6s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen. We hope this is a definite indication of things to come.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 24, 'm6t', 'Terrorist Cell'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 25, 'm7d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost. We need a trusted agent to lead a strike against this installation and insure its destruction. There''s no telling how many cells this depot has been supplying or how many Imperial lives have been lost as a result.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 27, 'm7s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 28, 'm7t', 'Rebel Supply Depot'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 29, 'm8d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their traitorous cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots to play around with. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 31, 'm8s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous indeed. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 32, 'm8t', 'Rebel Training Station'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 33, 'm9d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 35, 'm9s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 36, 'm9t', 'Slicer Hub'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 37, 'm10d', 'Agents within the CSA have informed Intelligence that many of the workers the Viceprexes are requesting for hard labor are being transferred to a holding facility so that Rebel agents can rescue convicted Rebel spies and sympathizers contained among the roster. We need a small team of loyal Imperial agents to obliterate this facility. The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 39, 'm10s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 40, 'm10t', 'Refugee Facility'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 41, 'm11d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 43, 'm11s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 44, 'm11t', 'Weapons Cache'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 45, 'm12d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 47, 'm12s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 48, 'm12t', 'Rebel Medical Droids'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 49, 'm13d', 'The Rebels have been targeting Imperial depots containing laser cutters. We believe they need them to build a new operational base although we do not yet know its location. Our agents have managed, however, to locate some of these laser cutters and have sent us the coordinates where they are being housed. We need a few loyal Imperial agents to strike this storage depot.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 51, 'm13s', 'Success! This will doubtless slow the Rebels'' efforts to carve out new lairs. You''ve earned your reward, agent.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 52, 'm13t', 'Laser Cutter Storage Depot'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 53, 'm14d', 'A traitorous Moff has offered to aid the Rebels attempt to assassinate our beloved Emperor. We''ve pinpointed where this traitor and his agents will be meeting with the Rebellion''s agents to make the arrangements. We require an able and loyal Imperial strike team to hit this outpost and insure its destruction. Could you assemble and lead such a team?'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 55, 'm14s', 'We have not ascertained whether the Moff was at that meeting when you destroyed the outpost. We''ll have to continue monitoring communications. In any case, your strike against that Rebel outpost was superb.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 56, 'm14t', 'Hunt a Traitorous Moff'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 57, 'm15d', 'Local garrisons have reported recent Rebel attacks that have employed modified A-A5 speeder trucks as armored personnel carriers. We''ve located several civilian speeder repair facilities that could be used to create these carriers. We want these installations destroyed. Can you assist the Empire in removing this potential threat? '),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 59, 'm15s', 'Good work, agent. We knew these stations were serving those Rebel scum and you''ve helped prove it. We hope this is the beginning of a very profitable career for you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 60, 'm15t', 'Take Out Rebel Repair Stations'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 61, 'm16d', 'The Rebels have taken an interest in certain rare types of crystals. Intelligence has instructed us to destroy any supply depot containing caches of such minerals. We''ve located a small warehouse containing a large quantity of mineral desposits mined from the Outer Rim. We need loyal Imperial servants to vaporize this warehouse.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 63, 'm16s', 'An efficient handling of the mission, agent. Well done. The Empire is proud to reward you.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 64, 'm16t', 'Smash Mysterious Crystals'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 65, 'm17d', 'We''ve been alerted to the presence of a Rebel supply depot that seems to be housing hundreds of climate control units. No doubt these are intended for remote Rebel bases in the Outer Rim. We want these units destroyed and figure a loyal and skilled Imperial agent ought to be able to take care of that for us. No need to call in a full military strike.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 67, 'm17s', 'Clean and efficient, citizen, just like we like it. COMPNOR could use more agents like you. '),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 68, 'm17t', 'Make It Cold for the Rebels'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 69, 'm18d', 'We finally identified the traitor who has been supplying vacuum gyros for Rebel transports. We have the coordinates to the traitor''s secret gyro cache. Unfortunately he knows we are coming. Our sources tell us that a contingent of Rebel soldiers is evacuating the cache. We need to dispatch a team to destroy this contraband before the Rebels take it away.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 71, 'm18s', 'Well done, citizen. Those Gallifree transports slip through our blockades too easily. Perhaps now we can stop those Rebel scum.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 72, 'm18t', 'Cripple Rebel Transports'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 73, 'm19d', 'Ion space mines are an important tool of the Imperial Navy, but in the hands of Rebel terrorists they become a menace to all law-abiding spacefarers. We have tracked a freighter to a known Rebel outpost, where it deposited a load of Defender-class mines. If we can wipe out this factory before its deadly contraband is unleashed, the star lanes will be safe once more.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 75, 'm19s', 'The Imperial Navy is indebted to you. Accept this payment and the gratitude of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 76, 'm19t', 'Take Out Space Mines'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 77, 'm20d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was hijacked en route to a Civil Security Center on Dantooine. Intercepted Rebel transmissions suggest these droids were smuggled to a secret reprogramming facility, where technicians will turn the IGs into gardening and botanical droids. A squad must locate and destroy this facility.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 79, 'm20s', 'The Empire is grateful for your service. IG assassin droids make lousy botanical arrangements. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 80, 'm20t', 'Assassin Droids Do Not Pick Posies'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 81, 'm21d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, as the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 83, 'm21s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 84, 'm21t', 'X-Wing Fighter Squad'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 85, 'm22d', 'We''ve discovered a local livestock dealer who harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. Certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 87, 'm22s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 88, 'm22t', 'Mynock Incubator'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 89, 'm23d', 'A local community has recently been plagued by a fake holovid recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility. You must take a strike team and decimate this unseemly operation. These untruths will not soil the tranquility of our loyal and obedient communities.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 91, 'm23s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 92, 'm23t', 'Seditious Broadcast Facility'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 93, 'm24d', 'In the midst of an otherwise obedient community, the Rebellion has constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 95, 'm24s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return. '),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 96, 'm24t', 'Rebel Power Relay'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 97, 'm25d', 'The Inquisitorius has ordered a strike on a Rebel outpost that has been conducting unusual experiments involving the Force and Force-users. We cannot imagine that the Rebellion would be foolish enough to attempt to establish another Jedi training academy, especially in light of the corruption that was revealed within the ranks of the old Jedi Order. Can you assemble a strike team to take care of this?'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 99, 'm25s', 'A new breed of Jedi shall not rise to threaten our beloved Empire thanks to you, agent. Well done! The Emperor will hear of your success. Be proud.'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 100, 'm25t', 'Jedi Training Outpost'),
('string/en/mission/mission_destroy_imperial_non_military_hard_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 1, 'm1d', 'Our probe droids have located a fairly sizable Rebel munitions depot. Taking this supply cache out would no doubt limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended (it is a weapons depot, after all). Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun? The Empire would be most pleased.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 2, 'm1f', 'Those Rebels were too much for you, eh? I suppose an attack on a munitions depot would be the sort of mission only very skilled and loyal Imperial agents should ever attempt. Your failure is disappointing but perhaps not terribly surprising.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 3, 'm1i', 'Those damn probe droids. We hope there''s an updated model on its way soon. We''ll double-check those coordinates and find that munitions depot. Report back later and finish this task for us.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 4, 'm1l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 5, 'm1o', 'Imperial Intelligence: Bureau of Operations'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 6, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 7, 'm1t', 'Destroy Rebel munitions depot'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 8, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 9, 'm2f', 'How could such an insignificant thing as a mining facility prove too much for you? We''d been led to believe you were an effective agent. It seems that information might have been inaccurate.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 10, 'm2i', 'Perhaps Intelligence had confused a legitimate Mining Guild facility for an illegal Rebel one. That has been know to happen in the past. We''ll verify with them.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 11, 'm2l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 12, 'm2o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 13, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 14, 'm2t', 'Destroy Rebel mining facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 15, 'm3d', 'Imperial Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation - in fact, burn it to the ground. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 16, 'm3f', 'You failed? How much trouble could a few sensor dishes and some transceivers have given you? This does not look good on your record.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 17, 'm3i', 'We''ve always been suspect of any information Imperial Intelligence sends us. We''ll double-check any such reports in the future against our own intelligence.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 18, 'm3l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 19, 'm3o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 20, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the ISB. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 21, 'm3t', 'Destroy Rebel communications array'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 22, 'm4d', 'What we thought was a legitimate medical facility has actually turned out to be a Rebel medical supply depot. It seems they have been using sick citizens as cover, trying to get us to believe they were operating according to Imperial laws. We feel for these sick individuals, although no doubt many of them are Rebel sympathizers, but this facility must be destroyed. We''d like to leave the details of such an operation to you, citizen. Do you think you''re up to the task? Once you see Rebel soldiers defending this facility, you will find it much easier to sacrifice the patients inside.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 23, 'm4f', 'You couldn''t even take out a facility filled with sick and wounded individuals? What sort of agent are you? Perhaps failure means nothing to you but it stains our reputation.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 24, 'm4i', 'How could the Rebels have moved so many sick people so fast? Could it have been a hologram intended to trick us? Where would the Rebels get such a device?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 25, 'm4l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 26, 'm4o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 27, 'm4s', 'Bacta is wasted on Rebel scum, do not worry. You have done very well and we are highly pleased. Our missions require someone with a strong constitution. You should seek us out in the future.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 28, 'm4t', 'Destroy Rebel medical facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 29, 'm5d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility and show the Rebels that the Empire will always find those who seek to escape Imperial justice. Are you that agent? We hope so. '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 30, 'm5f', 'Refugees escaped you? This must be terribly embarrassing for you. It certainly is for us. This does not inspire us with great confidence in your abilities, citizen. Your future is hazy.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 31, 'm5i', 'I''m sure those aliens are hiding somewhere in the area. We''ll continue looking for them. You should check back with us at a later time.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 32, 'm5l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 33, 'm5o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 34, 'm5s', 'You can run but you can''t hide! How we love that saying. Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 35, 'm5t', 'Destroy Rebel alien refugee outpost'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 36, 'm6d', 'Thanks to the efforts of our many loyal civilian informants, we''ve managed to verify the existence of a Rebel transport repair facility. We kept wondering where those Rebels would take their airspeeders, speeder bikes, and groundspeeders when they needed repairs. After all, many of them bear the evidence of skirmishes with local civil authorities or Imperial forces. Well now we know. We''d like this installation eliminated. We understand you are quite efficient at such work. Can the Empire count on you?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 37, 'm6f', 'Did they all just hop on their speeders and zoom away? How could you fail at such a mission. It''s not like we were sending you against a command center. How disappointing. We''ll have to note this failure in your record.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 38, 'm6i', 'Perhaps those "loyal informants" were not quite so loyal after all. Could they have given us false information? We''ll look into their backgrounds and watch them very closely.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 39, 'm6l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 40, 'm6o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 41, 'm6s', 'I suppose the Rebels will have to carry their supplies on their backs now. Hah! Job well done, citizen. This is what we mean when we say our agents are the most effective in the Empire. Don''t spend your reward all in one place.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 42, 'm6t', 'Destroy Rebel transport repair facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 43, 'm7d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these dreadful facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. It''s a horrible sight to behold, citizen. We must terminate the activities of this vile installation and insure our citizens remain safe from such atrocities and loyal to the Empire. Can you help your Emperor stamp out this loathsome practice? The Empire needs you. '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 44, 'm7f', 'Now the Rebellion will have more brainwashed clones to add to their ranks. How can you sleep at night knowing you failed the Empire in this one vital way? We are incredibly displeased.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 45, 'm7i', 'Are you sure you didn''t go into that camp and simply don''t remember the experience, citizen? Maybe you should have one of our medical droids look you over? This is most suspicious.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 46, 'm7l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 47, 'm7o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 48, 'm7s', 'Hurrah! You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. Losing your faith in the New Order is bad enough, but to lose your mind along with it? You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 49, 'm7t', 'Destroy Rebel indoctrination camp'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 50, 'm8d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. I think you''ll agree that the proper thing for a loyal citizen of the Empire to do is to reward one ill turn with another and burn this installation to the ground. Are you the agent we''re looking for? These terrorists must pay for their terrible acts of violence against the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 51, 'm8f', 'How heavily guarded could this installation have been? We do not understand the reason for your failure, citizen. Perhaps you were not the agent we were thinking of when we assigned this mission.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 52, 'm8i', 'Can a droid maintenance facility disappear overnight? This is most irregular. We must investigate this matter. Report back later and I''m sure we''ll have this straightened out.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 53, 'm8l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 54, 'm8o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 55, 'm8s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen. We hope this is a definite indication of things to come. Claim your just reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 56, 'm8t', 'Destroy Rebel terrorist cell'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 57, 'm9d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost of some sort. However, our surveillance images clearly show known Rebels patrolling the facility''s perimeter. We need a trusted agent to lead a strike against this installation and insure its destruction. There''s no telling how many cells this depot has been supplying or how many Imperial lives have been lost as a result. Can we count on you to undertake this dangerous mission? It will not be easy but the rewards will be worth it if you succeed.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 58, 'm9f', 'They probably managed to get most of their supplies out since you failed to destroy the facility. There''s no telling what sorts of equipment was in there. Perhaps even prototype starfighters or weapons. This is most disappointing. Losing your reward should be the least of your worries currently, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 59, 'm9i', 'This information came from Imperial Intelligence, which can have the habit of being occasionally spotty. We''ll inform them that they need to take better care when sending out intelligence reports such as this.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 60, 'm9l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 61, 'm9o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 62, 'm9s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 63, 'm9t', 'Destroy Rebel supply depot'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 64, 'm10d', 'Instead of being horrified, as all loyal citizens should have been, by the Rebellion''s destruction of the Empire''s most brilliant and effective weapon against injustice, it seems instead that this terrorist act has encouraged some malcontents to form their own Rebel cell. And they''ve done it in such a flagrant and obvious manner that we didn''t have to look too hard to find it. We need a true model citizen of the Empire to show these troublemakers the consequences of throwing their lot in with these traitors and terrorists. Are you that citizen? Can we rely on you to burn this newly formed Rebel cell to cinders? We will not rest easy until these criminals are atomized.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 65, 'm10f', 'You must understand that this failure will only encourage more of these undesirables to form these terrorist cells. How can you live with that fact? Your failure will cost many innocent Imperial citizens their lives. Frankly, we''re disgusted.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 66, 'm10i', 'They must have heard that we were taking matters into our own hands and have fled the scene. But how could they have moved so quickly and left no evidence of their passing? Maybe there is a spy in our midst...'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 67, 'm10l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 68, 'm10o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 69, 'm10s', 'Crush these scum, citizen! Grind them under your heel! A success like this deserves to be celebrated. You must share your victory with your closest friends. If any of them do not seem delighted as we are, give us their name and identification number. You can never be too sure.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 70, 'm10t', 'Destroy new Rebel cell'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 71, 'm11d', 'One of Sienar Fleet System''s chief engineers has foolishly decided to join the ranks of those traitorous Rebels. The Rebellion was eager to get this individual to safety as they had helped design some new TIE starfighters for the Empire. We''ve located this engineer and need them silenced before they can supply the Rebellion with technical specs. We believe the traitor is being held at a small warehouse currently used to store speeder parts. We require a skilled and loyal agent to strike this warehouse and blast it to atoms, taking everything inside with it. The facility will no doubt be guarded. Can the Empire rely on you to accomplish this mission?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 72, 'm11f', 'The survival of this engineer could be disastrous to the Empire. Your failure puts us all at risk. This will be reported to the Imperial High Command.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 73, 'm11i', 'The engineer may have escaped us today but we''ll eventually track them down. We promise you that.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 74, 'm11l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 75, 'm11o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 76, 'm11s', 'Well done, agent. We hope that engineer was inside that warehouse when it was destroyed, and we hope the Rebellion learned no damaging Imperial secrets. You must work for us again in the future.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 77, 'm11t', 'Take out traitorous engineer'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 78, 'm12d', 'The Empire has located a small station that is being used by the Rebels to entice young pilots to join their traitorous cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots to play around with. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. The Imperial Navy understands the lure of a well designed starfighter. We need this station destroyed and everything inside incinerated. Can the Empire count on you, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 79, 'm12f', 'More Rebel pilots mean more attacks on Imperial shipyards and garrisons. The Empire cannot afford that, citizen. Your failure will cost us dearly.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 80, 'm12i', 'The coordinates were not correct, eh? We''ll have to investigate this matter further. Check back with us soon.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 81, 'm12l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 82, 'm12o', 'Imperial Navy'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 83, 'm12s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous indeed. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 84, 'm12t', 'Destroy Rebel training station'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 85, 'm13d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 86, 'm13f', 'This installation must have been more carefully guarded than we had first anticipated. Still, your failure is a great disappointment to us. No results, no reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 87, 'm13i', 'Tracking down slicer hubs has got to be one of the most difficult bits of intelligence work there is. We''ll find them.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 88, 'm13l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 89, 'm13o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 90, 'm13s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 91, 'm13t', 'Destroy Rebel slicer hub'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 92, 'm14d', 'Loyal agents within the CSA have informed Imperial Intelligence that many of the workers the Viceprexes had requested for hard labor are being transferred to a holding facility so that Rebel agents can rescue convicted Rebel spies and sympathizers contained among the roster. We''ve acquired the coordinates of this facility and need a small team of loyal Imperial agents to obliterate it. The only other option facing convicted Rebels, besides a lifetime of back-breaking labor in service to the Empire, is death. Can you see to it that this is carried out? The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 93, 'm14f', 'Allowing convicted criminals to escape is not good, citizen. The Empire is terribly disappointed by your lack of success.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 94, 'm14i', 'One of the Viceprexes working for the Rebellion must have tipped them off. We''ll find which of them is serving those traitorous scum.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 95, 'm14l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 96, 'm14o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 97, 'm14s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 98, 'm14t', 'Destroy Rebel refugee facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 99, 'm15d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents. Can the Empire count on you to undertake this mission?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 100, 'm15f', 'Those blasters will no doubt claim many Imperial agents'' lives. Your failure is most alarming to us. Perhaps you''re not cut out for this sort of work.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 101, 'm15i', 'They must have moved the weapons already. Damn! We''ll have to work hard to track them down.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 102, 'm15l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 103, 'm15o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 104, 'm15s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 105, 'm15t', 'Destroy Rebel weapons cache'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 106, 'm16d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it. Do you think you could assist the Empire in this endeavor?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 107, 'm16f', 'Medical droids may not seem that important to you, but it is an immense boon to the Rebellion. Your failure alarms us. We must consider carefully before assigning you another mission.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 108, 'm16i', 'These coordinates seem to be faulty. We''ll interrogate our spies as soon as we can.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 109, 'm16l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 110, 'm16o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 111, 'm16s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 112, 'm16t', 'Destroy Rebel medical droids'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 113, 'm17d', 'The Rebels have managed to get their hands on some old Trade Federation destroyer droids. These units can be used to fortify their outposts and defend their bases. Fortunately, our informants have tracked these droids down and have provided us with the coordinates to the warehouse that is being used to store them. A loyal Imperial strike team is needed to take these droidekas out of commission. Do you think this is a mission you could handle?  '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 114, 'm17f', 'Droidekas may be older droids but they are still quite effective against our troops. Your failure to destroy these units will cost the Empire lives. Surely you see the tragedy in this?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 115, 'm17i', 'The destroyer droids must have been moved or else our informants were fed false coordinates. We''ll investigate this matter further.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 116, 'm17l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 117, 'm17o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 118, 'm17s', 'A job well done, agent. The Empire will show its appreciation via this reward. Do come see us again for future missions.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 119, 'm17t', 'Destroy Rebel destroyer droids'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 120, 'm18d', 'The Rebels have been targeting Imperial depots that contain laser cutters. We believe they need them to build a new operational base although we do not yet know where the Rebels plan on establishing the base. Our agents have managed, however, to locate some of these laser cutters and have sent us the coordinates where they are being housed. We need a few loyal Imperial agents to strike this storage depot and blast it to atoms. Can you help the Empire fight those Rebels?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 121, 'm18f', 'Destroying those laser cutters was no small affair, agent. Your failure means that the Rebels can continue with their plans to set up additional bases. This is both annoying and disappointing.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 122, 'm18i', 'We''ll find where those Rebels have moved those laser cutters to. They can''t keep things hidden from us forever.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 123, 'm18l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 124, 'm18o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 125, 'm18s', 'Success! This will doubtless slow the Rebels'' efforts to carve out new lairs. You''ve earned your reward, agent.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 126, 'm18t', 'Destroy Rebel laser cutters'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 127, 'm19d', 'A traitorous moff whose identity we have not been able to uncover has offered to aid the Rebels attempt to assassinate our beloved Emperor. We''ve tried to pinpoint where this traitor and his agents will be meeting with the Rebellion''s agents to make the arrangements. After months of investigation, we believe we finally have the coordinates to the outpost chosen for this sinister purpose. We require an able and loyal Imperial strike team to hit this outpost and insure that it is burned to the ground. Could you assemble and lead such a team? Only the most dedicated and skilled agents need apply for this important mission.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 128, 'm19f', 'How could have let this moff escape? We may never find him now. Your failure has allowed a grave danger to our Emperor to continue to exist. '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 129, 'm19i', 'The moff must have gotten word of our intended strike and insured we''d get false coordinates. This traitor will be sorry he ever turned against his master and the New Order.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 130, 'm19l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 131, 'm19o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 132, 'm19s', 'We hope the moff was at that meeting when you destroyed the outpost. We''ll have to continue monitoring communications to make sure. In any case, your strike against that Rebel outpost was superb.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 133, 'm19t', 'Destroy Rebel outpost'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 134, 'm20d', 'Intelligence has sent us a warning that the Rebels may try using mining equipment, especially LIN Demolitionmech droids, to strike at Imperial garrisons and depots. The idea was given to the Rebels by disgruntled spice miners who recently joined the Rebellion after the Empire cracked down on illegal spice mining on Kessel. The LIN droids will carry holographic disguisers to make them look like R3 units. We''ve located a supply depot filled with mining equipment, including large quantities of explosives and Demolitionmech droids. We suspect this depot will provide much of the materials needed to create these "miner bombs." We need a small team of Imperial agents to wipe this depot out and make sure the equipment inside is turned to molten slag. Can you aid the Empire in this, citizen? '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 135, 'm20f', 'Your failure to destroy this depot will result in many of our garrisons facing these deadly miner bombs. Is this sort of mission failure common for you? We should have explored your background a bit more carefully before assigning you this mission.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 136, 'm20i', 'Our coordinates are off. It must be the work of Rebel slicers. We''ll get the correct coordinates soon enough.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 137, 'm20l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 138, 'm20o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 139, 'm20s', 'An effective piece of work, agent. The Empire is proud. Claim your reward and seek us out again in the future for more work.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 140, 'm20t', 'Destroy Rebel mining depot'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 141, 'm21d', 'Local garrisons have reported recent Rebel attacks that have employed modified A-A5 speeder trucks as armored personnel carriers. We''ve located several civilian speeder repair facilities that could be used to create these carriers. We want these installations destroyed. We''ll leave Intelligence to provide us with "proof" of such activity after the deed is done. This task should prove simple for them. As for the task of destroying these stations, that will require a bit more work. Can you assist the Empire in removing this potential threat?  '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 142, 'm21f', 'The speeder trucks can cause quite a bit of damage to our local garrisons. Your failure endangers our soldiers. You are dismissed.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 143, 'm21i', 'The Rebels must be trying to protect these installations and are therefore sabotaging our efforts. This proves these stations are being used to aid the Rebellion.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 144, 'm21l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 145, 'm21o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 146, 'm21s', 'Good work, agent. We knew these stations were serving those Rebel scum and you''ve helped prove it. We hope this is the beginning of a very profitable career for you.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 147, 'm21t', 'Destroy Rebel repair stations'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 148, 'm22d', 'Smugglers have supplied the Rebels with a large quantity of stolen R3 units that were scheduled for Imperial cruisers. We understand that these R3 units have already been reprogrammed by Rebel technicians and are awaiting supply requisitions from the Rebel fleet. We''ve located several of these R3 units and need them destroyed. These units are useless to us now that they might contain Rebel bugging devices. We''re determined, however, not to allow these droids to serve the Rebellion either. Can you aid the Empire in carrying out this task? '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 149, 'm22f', 'We didn''t think such a simple mission would give you such trouble. This failure must be entered into your permanent record, agent. It is a shame.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 150, 'm22i', 'The Rebel scum must be moving those R3 units around. We''ll track them down.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 151, 'm22l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 152, 'm22o', 'Imperial Navy'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 153, 'm22s', 'You must be congratulated on a job well done, agent. The Empire needs more operatives like yourself. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 154, 'm22t', 'Destroy Rebel R3 units'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 155, 'm23d', 'Intelligence informed us that the Rebels have taken an interest in certain rare types of crystals and that any supply depot containing caches of such minerals were to be immediately destroyed. We''ve located a small warehouse containing a large quantity of mineral desposits mined from the Outer Rim. We do not know for certain that these crystals were headed into the hands of the Rebellion, but why risk it? We need loyal Imperial servants to vaporize these mineral supplies for us. Can the Empire count on your aid, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 156, 'm23f', 'We can only hope that these crystals were not being used to fashion some new devilish weapon. If you can''t even take out a moderately defended warehouse, what hope do you have of getting more dangerous missions?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 157, 'm23i', 'We could have sworn those were the proper coordinates. Hmm, we''ll have to double-check our reports.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 158, 'm23l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 159, 'm23o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 160, 'm23s', 'An efficient handling of the mission, agent. Well done. The Empire is proud to reward you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 161, 'm23t', 'Destroy Rebel warehouse'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 162, 'm24d', 'Our agents have been provided with a deadly airborne virus that they are to release at some anti-Imperial demonstrations and marches. The Rebels somehow acquired a sample of this virus and have developed a retrovirus, which they have mass-produced and plan to ship to the various systems where these demonstrations are scheduled. We''ve managed to locate one of these shipments, currently being stored in a small medical supply depot. It occurs to us that a few loyal Imperial agents could assist our plans by insuring this retrovirus vaccine is destroyed. Can you assist in this matter, loyal servant of the Empire?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 163, 'm24f', 'It would have been better had we been able to stop these demonstrations using subterfuge, agent. Your failure means the Empire must risk more negative public opinion by using stormtroopers to silence these malcontents. How disappointing.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 164, 'm24i', 'Rebel agents no doubt moved this shipment of the vaccine. We must track it down. These encounters are so like a game of dejarik, wouldn''t you agree? '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 165, 'm24l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 166, 'm24o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 167, 'm24s', 'Our agents will meet with great success now. Well done, citizen. Your aid to the Empire and COMPNOR shall not be forgotten.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 168, 'm24t', 'Destroy Rebel retrovirus'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 169, 'm25d', 'Our spies have alerted us to the presence of a Rebel supply depot that seems to be housing many climate control units. No doubt these are intended for remote Rebel bases in the Outer Rim. We want these units destroyed and figure a loyal and skilled Imperial agent ought to be able to take care of that for us. No need to call in a full military strike. Can you assist the Empire with this, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 170, 'm25f', 'Climate control units were too much for you? This failure must be terribly embarrassing for you. We will certainly try not to mention it.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 171, 'm25i', 'Our coordinates were in error? Strange. Must be the work of Rebel saboteurs.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 172, 'm25l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 173, 'm25o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 174, 'm25s', 'Clean and efficient, citizen, just like we like it. COMPNOR could use more agents like you. '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 175, 'm25t', 'Destroy Rebel climate control units'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 176, 'm26d', 'The Rebellion would like nothing more than to blame the most recent attacks on the Bounty Hunters'' Guild on the Empire. Our agents inform us that the Rebels claim to have proof of such an involvement. Some Rebel spies are scheduled to meet with some representatives of the Bounty Hunters'' Guild. This meeting must be sabotaged. We''ve acquired the coordinates to the secret location chosen for this purpose. We need loyal Imperial servants to silence these rumors once and for all. An attack by the Imperial military is out of the question, as I''m sure you understand. The Empire needs to insure "plausible deniability." Can you help us achieve this?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 177, 'm26f', 'Having the Bounty Hunters'' Guild turn on us would be a great disservice to the Empire, citizen. Your failure could make that come about. Very distressing.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 178, 'm26i', 'The Rebels must have known of our plans and moved the meeting. They are resourceful, we''ll give them that.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 179, 'm26l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 180, 'm26o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 181, 'm26s', 'Dead men tell no tales, correct? Bravo, citizen. You are shaping up to be a highly respected professional agent. Accept your fee for the services rendered.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 182, 'm26t', 'Destroy secret meeting place'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 183, 'm27d', 'Our informants have given us the coordinates to a civilian speeder shop that apparently is storing some prototype speeders in the garage. What tipped our informants off was the shop owner''s careful attempts to conceal these speeders. A mechanic''s conversation was overheard and it mentioned something about adapting these speeders for extreme climate conditions. Whatever those mechanics are planning, it can''t be legal. We need some dedicated agents to assault the shop and make sure it burns to the groud with those prototype speeders inside. Can you handle this mission for COMPNOR?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 184, 'm27f', 'There''s no telling what those speeders were going to be used for. Your failure could mean the Rebels get their hands on an improved assault speeder. This is terribly disappointing.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 185, 'm27i', 'Intelligence must have gotten these coordinates wrong when they transmitted them to us. It pleases them to embarrass us like this from time to time.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 186, 'm27l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 187, 'm27o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 188, 'm27s', 'Job well done, citizen. We hope you continue working with our organization in the future.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 189, 'm27t', 'Destroy Rebel prototype speeders'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 190, 'm28d', 'We''ve tracked down one of the refueling depots used by Rebel-friendly smugglers, who''ve euphemistically been termed "procurement specialists" by the Rebellion. How quaint. These smugglers also leave shipments of stolen goods for the Rebels to take delivery of and redistribute to various cells. We must identify all such depots and put them out of business. The Imperial Military has their hands full tracking down Rebel bases, they don''t need the additional worry of these depots. For this task, we require a capable team of agents that can hit an installation like this fast and hard. Can you assemble and lead such a team, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 191, 'm28f', 'Smugglers are not just a problem for the local authorities, citizen. They aid the Rebels and are therefore our problem as well. Your failure to take out their depot makes us doubt your abilities.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 192, 'm28i', 'Well, smugglers are elusive if they are anything. Our agents will track this depot down.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 193, 'm28l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 194, 'm28o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 195, 'm28s', 'We knew we could rely on you, citizen. Congratulations. The reward goes to you with our blessings.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 196, 'm28t', 'Destroy Rebel refueling depot'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 197, 'm29d', 'The operation took several years, but we finally uncovered the traitor who has been supplying vacuum gyros for Rebels transports.  We now have the coordinates of the traitor''s secret gyro cache.  Unfortunately he captured the probot that relayed us the information, so he knows we are coming.  Our sources tell us that a contingent of Rebel soldiers is evacuating the cache.  We need to dispatch a team to destroy this contraband before the Rebels take it away.  Are you equipped for such a mission?  If you go, expect a firefight.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 198, 'm29f', 'Vacuum gyros allow Gallifree transports to elude planetary blockades.  You let a golden opportunity slip through your fingers!  This failure will go on your record, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 199, 'm29i', 'Blast!  They must have finished evacuating before you arrived.  We''ll track down those Rebel scum yet.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 200, 'm29l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 201, 'm29o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 202, 'm29s', 'Well done, citizen.  Those Gallifree transports slip through our blockades too easily.  Perhaps now we can stop those Rebel scum.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 203, 'm29t', 'Destroy a cache of vacuum gyros'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 204, 'm30d', 'Too many Rebel codes resist our efforts to unravel.  At last we have pinpointed the site of an encoding array which the Rebellion uses to retransmit secret communiques.  By smashing this installation we shall cripple their transmission network and save the lives of countless Imperial soldiers.  Needless to say, the Rebellion has posted a number of guards at the site.  If you can aid us in this strategic action, the Empire will provide you generous compensation.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 205, 'm30f', 'This was not an easy mission, but neither was it exceedingly dangerous.  You won''t fail the Empire like this again, will you, citizen?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 206, 'm30i', 'Perhaps someone made a mistake in decrypting the coordinates of the station.  We shall make the necessary inquiries.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 207, 'm30l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 208, 'm30o', 'Imperial Intelligence: Analysis Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 209, 'm30s', 'Nice work.  Already we have seen a reduction in the number of encoded Rebel transmissions.  Take this payment with our gratitude.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 210, 'm30t', 'Eliminate a Rebel encoding station'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 211, 'm31d', 'Ion space mines are an important tool of the Imperial Navy, but in the hands of Rebel terrorists they become a menace to all law-abiding spacefarers.  We have tracked a freighter to a known Rebel outpost, where it deposited a load of Defender-class mine chassis.  We believe the Rebellion is assembling ion cannons for insertion into these mines.  If we can wipe out this factory before its deadly contraband is unleashed, the star lanes will be safe once more.  Are you ready to accept such an important mission?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 212, 'm31f', 'Those ion space mines will now be a threat to Imperial ships everywhere.  The blood of fallen stormtroopers will be on your hands.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 213, 'm31i', 'Amusingly, the factory was destroyed by an internal explosion just before you arrived.  Amateurs should not handle space mines.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 214, 'm31l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 215, 'm31o', 'Imperial Navy'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 216, 'm31s', 'The Imperial Navy is indebted to you.  Take this payment and the gratitude of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 217, 'm31t', 'Wipe out a factory for space mines'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 218, 'm32d', 'It''s no wonder the Rebellion continues to elude our proud Imperial Navy.  We have learned from Imperial Intelligence of a hidden Rebel station that monitors hyperspace activity, in order to track the movement of our capital ships.  We need ground-based agents to recon this monitoring terminal and shut down its traitorous activities.  It is likely that the station is heavily guarded, so citizens accepting this mission should equip themselves for a fight.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 219, 'm32f', 'Imperial Intelligence suggested we dispatch civilians for this mission.  In the future we shall regard this practice with greater skepticism.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 220, 'm32i', 'Imperial Intelligence provided us with those coordinates.  Some days they are more reliable than others.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 221, 'm32l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 222, 'm32o', 'Imperial Navy'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 223, 'm32s', 'You shall be well paid for your success.  Imperial Intelligence is on its way to sift through the remains of the terminal, assuming you left any remains.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 224, 'm32t', 'Dismantle a hyperspace monitoring terminal'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 225, 'm33d', 'The Imperial Army works tirelessly to ensure security and civic tranquility in the galaxy.  To undertake this noble mission the Army consumes vast food resources.  As we all know, the Rebellion spares no atrocity in their sabotage of galactic peace, and this includes the highjacking of rations bound for Imperial garrisons.  But certain loyal citizens have informed us of a distribution center where the Rebels hoard this stolen food.  They are using this contraband to bribe the local settlements.  The Rebels pretend that recent Imperial exhaust tests have caused a local drought, and then "remedy" this "famine" with the stolen rations.  But a well-armed team of loyalist infiltrators can destroy this distribution center and stop the treachery before it spreads.  The Empire will compensate such bravery according to its success.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 226, 'm33f', 'Thanks to your incompetance, the local settlements must continue to endure the indignity of consuming stolen food.  You have failed them and you have failed the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 227, 'm33i', 'Our intelligence indicates that local settlers assisted in moving the distribution center before you arrived.  Rebel exploitation knows no limits.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 228, 'm33l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 229, 'm33o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 230, 'm33s', 'It is too bad that the Army rations had to be destroyed, but at least the local settlers are spared the indignity of consuming stolen food.  Take your reward with honor.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 231, 'm33t', 'Crush a Rebel distribution center'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 232, 'm34d', 'A grand victory!  Recently our field operatives wiped out a Rebel command center using an exciting new airborne biological agent.  To our dismay, however, a group of survivors fled with the corpses of several highly-placed Rebel leaders.  We tracked their escape vessel to a small "safe house."  Our scientists have deemed it prudent to destroy these bodies in the interest of public health.  We are looking for loyal volunteers to enter this Rebel den, eliminate the guards and blast apart the entire structure.  Of course our own operatives will be observing from a safe and discreet distance.  A reward is available for anyone who performs this service, as well as the gratitude of the Empire for the remainder of their life.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 233, 'm34f', 'We hope your abortive effort hasn''t spread the biological contagion.  From now on, please refrain from bodily contact with any member of the ISB.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 234, 'm34i', 'Are you sure you investigated the area thoroughly?  Our coordinates must have been wrong.  Just in case, please refrain from bodily contact with any member of the ISB.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 235, 'm34l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 236, 'm34o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 237, 'm34s', 'Excellent work, citizen.  Now use this reward money to remove yourself from all populated areas.  We cannot be certain that you are free from biological contagion.  Have a nice day.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 238, 'm34t', 'Eliminate a biological hazard'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 239, 'm35d', 'As diligent citizens of the Empire know, recently the Rebellion provoked the untimely destruction of the planet of Alderaan.  Properly reviled for this heinous crime, the Rebellion has sought public sympathy by collecting and breeding many of Alderaan''s native fauna.   Right-thinking citizens of the Empire understand that the Death Star was forced to destroy Alderaan in the name of galactic security, and that this program of re-breeding extinct animals is a transparent act of propaganda.  Luckily we have located the center of this traitorous enterprise.  We need a team of well-trained civilians to blast apart this breeding facility and strike a blow for truth and justice in the galaxy.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 240, 'm35f', 'If you have allowed a single Alderaanian tinklefly to escape, the security of the Empire could be jeopardized!  We shall record this failure in our files, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 241, 'm35i', 'Perhaps our intelligence was not as accurate as we thought.  Fear not, this vile operation will soon be shut down.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 242, 'm35l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 243, 'm35o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 244, 'm35s', 'While the beautiful woolly moth of Alderaan may have looked harmless, it was a vicious threat to galactic security.  You have advanced the cause of Imperial truth.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 245, 'm35t', 'Destroy a Rebel propaganda center'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 246, 'm36d', 'Some Imperial agents are in Rebel custody, captured in a recent frontier skirmish, and are currently imprisoned in a small but well-guarded holding facility.  The Rebels will be on the lookout for uniformed soldiers, so we require some highly-trained civilians to launch a surprise assault on the holding facility and reduce it to rubble.  We must assume that the captured agents have been interrogated and have divulged military secrets.  They are therefore traitors and should be considered expendable.  Applicants for this mission will be required to leave no survivors.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 247, 'm36f', 'Your mission specified no survivors.  We hope that the Rebels do not learn additional military secrets because of your inept performance.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 248, 'm36i', 'The captured agents must have divulged our classified frequencies.  Clearly the Rebels knew we were coming.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 249, 'm36l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 250, 'm36o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 251, 'm36s', 'We''re pleased that the captured agents have been liquidated.  You have earned the undying respect and loyalty of the ISB.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 252, 'm36t', 'Liquidate captured Imperial agents'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 253, 'm37d', 'The cowardice of the Rebellion knows no limit.  This time they have launched an insidious scheme to undermine the security of a peaceful, orderly world.  As you know, Imperial engineers have enhanced the water supply of many communities with placidity enzymes to abate civic unrest.  The Rebels have secretly captured a local water junction and installed a Creel manifold to siphon off the additives.  We need a team of civilian operatives to ambush these Rebel dogs and blast the water junction into oblivion.  This will set an example to traitors everywhere that the goodwill of the Empire shall not be thwarted.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 254, 'm37f', 'How can we expect to secure public tranquility when our hired operatives cannot blast a simple water junction to pieces?  Come back when you have trained further.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 255, 'm37i', 'Once again the Rebel scum have slinked back into the shadows when Imperial justice arrived.  Stay alert, good citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 256, 'm37l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 257, 'm37o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 258, 'm37s', 'The Empire is lucky to have such skilled civilian operatives.  Rest assured that the community''s water supply will be fully restored within a few months.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 259, 'm37t', 'Blast a Creel manifold into oblivion'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 260, 'm38d', 'For thirty years I languished in the Glythe sector as a remote field operative of the ISB.  Now, at the end of my career, I have been transferred to a more civilized system with a chance to make a real impact.  I am retiring next cycle, so this is my last opportunity to attain some measure of glory.  To this end I am sending a civilian strike team to take out a suspected Rebel grease refinery.  I require well-trained operatives who are not afraid to get their hands dirty.  Help an old man make his mark in the universe.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 261, 'm38f', 'Blast it!  That was my last chance to retire with honor, and you botched it!  Thank you for destroying my grandchildren''s faith in a failing old man.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 262, 'm38i', 'What?  It''s not there?  That can''t be!  I''m sure I had reliable intelligence.  Am I to retire with this embarrassing mistake as my last act?  Oh, woe!'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 263, 'm38l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 264, 'm38o', 'Agent Sheedup of the Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 265, 'm38s', 'At last I have achieved true success!  My grandchildren thank you for saving an old man''s reputation.  Take your payment and enjoy it.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 266, 'm38t', 'Strike a Rebel refinery'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 267, 'm39d', 'Rebel dogs come in all stripes.  We have pinpointed a cloister of fuselage engineers who are aiding the traitors in their fighter designs.  We are commissioning a team of investigators to search these coordinates and eliminate any operations they find.  These engineers are simple data pushers, not much of a threat, though word has it that they might carry some small arms of their own design.  Watch out for surprises and make sure to wipe out any research materials they have gathered.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 268, 'm39f', 'It is stupefying that so-called professionals can fail to take down a simple cloister of engineers.  What is the universe coming to?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 269, 'm39i', 'Those data pushers must have sliced into our security net and known that we were coming.  But they can''t hide for long.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 270, 'm39l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 271, 'm39o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 272, 'm39s', 'I understand those engineers were tougher than they looked.  Or perhaps you are not as competant as you portray yourself.  At least you completed the mission.  Take your payment and go.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 273, 'm39t', 'Smash a cloister of engineers'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 274, 'm40d', 'Rebel pirates have stolen our droids!  A shipment of IG-type assassin droids was highjacked en route to a Civil Security Center on Dantooine.  We have intercepted Rebel messages that suggest these droids were smuggled to a secret reprogramming facility, where technicians are regearing their circuits for use in gardening and botanical arrangement.  This insult to Imperial might must be eradicated immediately.  A squad of operatives must travel to these coordinates and destroy the facility.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 275, 'm40f', 'Thanks to your inept performance, the galaxy must continue to endure the appalling botanical arrangements created by these reprogrammed assassin droids.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 276, 'm40i', 'The information must be correct.  We killed many Bothans to get it.  Let me double-check. Try again later.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 277, 'm40l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 278, 'm40o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 279, 'm40s', 'The Empire is grateful for your service.  IG assassin droids make lousy botanical arrangements.  Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 280, 'm40t', 'Eradicate a droid reprogramming facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 281, 'm41d', 'Alert!  Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters.  These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge.  We need a contingent of shooters to slip inside and blast the place to dust.  The station is craftily disguised, but it contains enough fuel that destroying the surface structures ought to ignite the whole place like an Alderaanian fireworks shop.  Be careful, though, as the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 282, 'm41f', 'Those X-wings have been slipping through our blockades for several parsecs, and you failed to destroy them even while they were idle.  The Empire does not abide incompetance.  This incident will be recorded in our files.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 283, 'm41i', 'Our Analysis Bureau informs us that the Rebels destroyed the facility themselves minutes before you arrived.  Next time, try to reach your objective with greater urgency.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 284, 'm41l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 285, 'm41o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 286, 'm41s', 'We have been tracking those X-wings for many parsecs.  At last their destruction is complete.  Splendid work.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 287, 'm41t', 'Smash a squad of X-wing fighters'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 288, 'm42d', 'Sometimes the Rebels do not know when to give up.  This time they have stolen the plans for a new Imperial void station and hidden them inside an innocuous MSE-6 mouse droid.  On the planet Elcorth we executed thirty Elomin to retrieve the plans, but the droid managed to escape.  In Darpa sector we blasted several Rhinnalian medical frigates to space dust, but again the mouse droid eluded us.  After bombing a Rebel stronghold on Mindabaal we again failed to capture the droid, but we learned that it hopped aboard a smuggler''s freighter and landed at these coordinates.  We require a strike team to pinpoint the Rebel outpost and smash it to rubble.  Imperial Intelligence will inspect the site to retrieve what remains of the offending MSE-6.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 289, 'm42f', 'You failed to destroy the outpost and as a result, the mouse droid has once more slipped through our fingers.  Can no one stop that mechanical meddler??'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 290, 'm42i', 'Our inspectors have learned that the mouse droid inserted a false navigational log into the smuggler''s computers.  As a result we gave you the wrong coordinates.  Curse that metal-plated nuisance!'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 291, 'm42l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 292, 'm42o', 'Imperial Navy'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 293, 'm42s', 'Excellent work.  There''s no way that little droid could have escaped this time.  You have served the Empire well.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 294, 'm42t', 'Execute an MSE-6 mouse droid'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 295, 'm43d', 'For several cycles the Empire has expended valuable military resources tracking down a single MSE-6 mouse droid.  This mechanical nuisance carries the plans for one of our prototype void stations, which must be recovered at any cost.  Recently the droid fled to the ice planet of Lur where it tricked several bounty hunters into killing each other.  Then it commandeered one of the hunters'' starships and blasted its way past an Imperial blockade.  We have followed its particle vapor trail to a small gas filter plant at these coordinates.  Time is now short.  The Rebellion has dispatched a squad of fighters to retrieve the droid.  We must level this plant before the enemy can capture our secret plans.  Make certain that nothing survives!'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 296, 'm43f', 'Take heart.  Better agents than you have failed to bring down this mouse droid.  Keep practicing and perhaps you may redeem yourself at a later time.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 297, 'm43i', 'Our inspectors discovered that the exhaust vapor was a ruse by the droid to throw us off its trail.  We''ll get you yet, mouse droid!'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 298, 'm43l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 299, 'm43o', 'Imperial Navy'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 300, 'm43s', 'We have found no trace of the mouse droid in the ruins.  You must have blown it into a billion atoms.  Well done!'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 301, 'm43t', 'Execute an MSE-6 mouse droid'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 302, 'm44d', 'Somehow a mere MSE-6 mouse droid continues to elude capture.  The droid carries plans for one of our prototype void stations, which we must recover at any cost.  Not long ago we cornered the MSE-6 in the spice mines of Sevarcos, but somehow it evaded laser fire from an entire platoon of crack stormtroopers.  After piloting a Corellian freighter into the command deck of an Imperial-class Destroyer, the droid navigated a turbo escape pod through the Noonta Nebula to shake off our TIE pursuit fighters.  But space debris forced it to land at these coordinates, where a Rebel cell has given it shelter.   Now is our chance to obliterate this mechanical traitor and remove a terrible threat to the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 303, 'm44f', 'The mouse droid escaped yet again?  Our file on this mechanical nuisance grows larger and larger.  Perhaps it is time to dispatch more skilled agents to the task.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 304, 'm44i', 'How can a simple MSE-6 constantly to throw us off its trail?  Blast you, accursed mouse droid!'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 305, 'm44l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 306, 'm44o', 'Imperial Navy'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 307, 'm44s', 'Finally we have stopped that annoying little droid!  Imperial Intelligence has yet to locate its remains in the rubble you left behind, but we have certainly seen the last of that metal-plated turncoat.  Very well done.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 308, 'm44t', 'Execute an MSE-6 mouse droid'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 309, 'm45d', 'The Empire prides itself on the reputation of its elite stormtroopers.  The Rebellion has demonstrated its fear of these crack soldiers by tampering with black quartz used in the construction of stormtrooper armor.  Imperial Intelligence has learned that Rebel saboteurs have performed molecular scoring on the laserproof crystals, which are fashioned into visors for trooper helmets, so that our fine soldiers have experienced some difficulty seeing properly.  We are uncertain to what extent these defective visors have been deployed throughout the galaxy.  However we have tracked the saboteurs to a rundown cantina at these coordinates.  The Empire wishes to make an example of these Rebels by completely obliterating the cantina and all the traitors inside.  Perform this service and perhaps one day you will be experienced enough to join the ranks of the Empire''s finest.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 310, 'm45f', 'You''ll never qualify to be a stormtrooper with a poor performance like that!  Practice your marksmanship and someday you may aspire to the Empire''s most elite fighting units.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 311, 'm45i', 'Come to think of it, I was wearing a stormtrooper helmet when I transmitted those coordinates to you.  Perhaps I made a mistake.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 312, 'm45l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 313, 'm45o', 'Imperial Army'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 314, 'm45s', 'You have the lethal cunning and accuracy of an Imperial stormtrooper.  Perhaps you should apply to the Academy.  Take this payment and think about your future.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 315, 'm45t', 'Obliterate Rebel saboteurs'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 316, 'm46d', 'It has come to our attention that a local livestock dealer harbors seditious motives.  Loyal citizens have reported a collection of mynock incubators hidden underneath his shop.  As you may know, certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet.  We have judged it prudent to destroy the incubation facility in the interest of galactic security.  Level the shop at these coordinates and you shall receive suitable recompense.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 317, 'm46f', 'A simple livestock dealer repelled battle-hardened Imperial agents?  It seems our suspicions are confirmed.  Heal your wounds and perhaps you may be allowed to try again.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 318, 'm46i', 'It seems we were provided with the wrong coordinates.  We shall investigate the "loyal citizens" who made this report.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 319, 'm46l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 320, 'm46o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 321, 'm46s', 'He put up quite a fight for a simple livestock dealer, didn''t he?  It seems our suspicions are confirmed.  Only a Rebel traitor would have that kind of firepower.  Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 322, 'm46t', 'Crush a mynock incubator'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 323, 'm47d', 'Sedition takes many forms.  Even a simple holovid broadcast can spread unrest, if its content is unacceptable.  For instance, a local community has recently been plagued by a fake recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star.  The transmission has been traced to a broadcast facility at these coordinates.  We want you to take a strike team and decimate this unseemly operation.  In particular, make certain that all of these fake recording are utterly destroyed.  We will not have these untruths soiling the tranquility of our loyal and obedient communities.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 324, 'm47f', 'It is most suspect that you failed to destroy this traitorous broadcast facility.  We shall schedule a thorough background check to ensure that your record is clean.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 325, 'm47i', 'No doubt this is a simple computer hiccup.  We shall retrieve the proper coordinates shortly.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 326, 'm47l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 327, 'm47o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 328, 'm47s', 'Excellent work.  Did you happen to view any of the offending holovids before you destroyed them?  We''ll send some security agents around to question you, just in case.  Don''t worry, it''s a routine debriefing.  Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 329, 'm47t', 'Raze a seditious broadcast facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 330, 'm48d', 'Have they no sense of decency?  In the midst of an otherwise obedient community, the Rebellion has constructed a power relay cannon that transmits energy beams to passing Rebel fighters.  For the public good we must now dispatch a blaster team to blow this relay installation into oblivion and fry every inhabitant to ashes.  Such an action will assure the locals that the Empire is dilligently protecting their families and properties.  To this end, bring as many heavy weapons and explosives as you can gather for the task.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 331, 'm48f', 'That power relay will continue to operate only as long as you continue to botch the job.  Spend sometime in a Bacta tank and come back when you''re ready to mount a proper attack.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 332, 'm48i', 'I now suspect that the locals helped to dismantle and hide the relay station.  We shall conduct a door-to-door search, but you need not concern yourself with that.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 333, 'm48l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 334, 'm48o', 'Imperial Security Bureau'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 335, 'm48s', 'Nicely done, citizen.  The community has been rendered safe once more.  The standard martial curfew will ensure that no Rebels return.  '),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 336, 'm48t', 'Blast a Rebel power relay'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 337, 'm49d', 'They want us to believe they are mere gangsters, but we have discovered that the Ravvo clan are in fact agents of the Rebel Alliance.  These creeps have a barracks, at these coordinates, where they practice their marksmanship to the detriment of the Empire.  A well-armed assault will teach them that scoffing Imperial authority is a game for fools and dead men.  These thugs are heavily armed as well, so proceed cautiously but ruthlessly.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 338, 'm49f', 'Those Rebels should have run like cowards in the face of armed resistance!  Perhaps they are more formidible than we anticipated.  Perhaps it is time to get the military involved.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 339, 'm49i', 'We conduct so many polticial enforcement actions that sometimes our data gets confused.  We''ll sort out the problem.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 340, 'm49l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 341, 'm49o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 342, 'm49s', 'It''s astounding that so many fools refuse to acknowledge the irresistable might of the Empire.  You have shown them the error of their ways.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 343, 'm49t', 'Level a den of Rebel sympathizers'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 344, 'm50d', 'Thanks to the tireless work of Imperial forces, the Rebellion is now reduced to hiring the lowest of the low to help their pathetic cause.  I''m speaking of course of salvage freighters, who scour the outer systems like vermin looking for scraps of metal to sell.  We have learned that a thriving business is developing in the area of Yavin, where large pieces of military equipment are available for the taking.  In particular a cache of near-functional turbolasers has been purchased by the Rebels.  Luckily some of the tracking circuits are still functional, so our scouts have located the base where the weapons have been hidden.  A swift assault will wipe out this cache and the Rebels who guard it.  Once more Imperial justice will prevail over these hopeless acts of sedition.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 345, 'm50f', 'You failed?  Had the Rebels managed to activate the turbolasers, or are you simply too inept to complete a simple search-and-destroy mission?'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 346, 'm50i', 'Our investigators have discovered that the tracking circuits were removed from the salvaged turbolasers and buried at the coordinates we gave you.  They threw us off the trail this time, but we''ll find those Rebel scum yet.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 347, 'm50l', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 348, 'm50o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 349, 'm50s', 'Excellent work!  You have saved the lives of countless Imperial soldiers.  Take your reward with honor.'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 350, 'm50t', 'Wipe out a cache of Rebel turbolasers'),
('string/en/mission/mission_destroy_imperial_non_military_medium.stf', 351, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 1, 'm1d', 'Our probe droids have located a sizable Rebel munitions depot. Taking out this supply cache would limit the number of raids the Rebels could effectively carry out. This depot will probably be well guarded and will certainly be well defended. Can we rely on you to teach these Rebel scum a lesson and turn their depot into a miniature sun?'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 3, 'm1s', 'That must have been quite a fireworks show, eh? Congratulations, agent. Your Imperial service record is shaping up quite nicely.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 4, 'm1t', 'Rebel Munitions Depot'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 5, 'm2d', 'A Rebel mining facility has been identified by Intelligence and we need it destroyed. These Rebels have a habit of slipping through our blockades during a full military strike so we''d like you to lead a small team of loyal agents to accomplish this mission instead. Do you think you can serve your Empire in this manner?'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 7, 'm2s', 'If the Rebels thought we would overlook a small mining operation, they were sadly mistaken. Well done. Your efforts on behalf of the Empire are noted. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 8, 'm2t', 'Rebel Mining Facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 9, 'm3d', 'Intelligence believes that a small outpost is housing a communications array currently being employed by the Rebellion to coordinate local Rebel cell activity. Put this place out of operation. We will not have this sort of Rebel activity in that sector. How dare the Rebels think this would go unnoticed. Can the Empire rely on you? '),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 11, 'm3s', 'So much for that outpost. Bravo, loyal citizen! Your efforts may take you far in the ranks of the ISB. We hope you continue to serve us.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 12, 'm3t', 'Communications Array'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 13, 'm4d', 'Rebels have been transporting alien refugees to various outposts throughout the galaxy. Many of these refugees are escaped slaves or criminals. We''ve managed to locate one of these outposts and now need to make sure it will no longer serve the cause of the Rebellion. We need a trusted agent to eradicate this facility. '),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 15, 'm4s', 'You can run but you can''t hide! Congratulations, citizen, you have removed many inconveniences for the Empire. Seek us out for future employment.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 16, 'm4t', 'Alien Refugee Outpost'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve unearthed a Rebel indoctrination camp. Within the walls of these facilities, the minds of loyal citizens are poisoned and warped by the efforts of twisted medical droids and large quantities of illegal glitterstim drugs. We must terminate the activities of this vile installation and insure our citizens remain loyal to the Empire. Can you help your Emperor stamp out this loathsome practice? '),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 19, 'm5s', 'You have doubtless saved hundreds of loyal citizens from a terrible fate, citizen. Losing your faith in the New Order is bad enough, but to lose your mind along with it? You are a true champion of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 20, 'm5t', 'Rebel Indoctrination Camp'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve discovered a Rebel terrorist sleeper cell masquerading as a droid maintenance facility. We suspect that this cell has been responsible for the deaths of no less than 100 Imperial servants and the destruction of millions of credits worth of property. We require a loyal citizen of the Empire to burn this installation to the ground. Are you the agent we''re looking for?'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 23, 'm6s', 'The deaths of all those Imperial servants are now avenged! You are truly a champion of justice, citizen. We hope this is a definite indication of things to come.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 24, 'm6t', 'Terrorist Cell'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 25, 'm7d', 'A Rebel supply depot has been located. The front for it seems to be a scientific observation outpost. We need a trusted agent to lead a strike against this installation and insure its destruction. There''s no telling how many cells this depot has been supplying or how many Imperial lives have been lost as a result.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 27, 'm7s', 'Whatever was in that warehouse will not serve those Rebels now. Good work, agent. Your future does indeed look bright if you continue to serve us in this manner. Collect your reward with pride - you''ve earned it.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 28, 'm7t', 'Rebel Supply Depot'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 29, 'm8d', 'We''ve located a small station that is being used by the Rebels to entice young pilots to join their traitorous cause. Apparently these Rebels have several X-wing flight simulators that they allow local pilots to play around with. Unfortunately, this is often enough to get some of these na?ve flyboys to sign up. We need this station destroyed and everything inside incinerated.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 31, 'm8s', 'Little did those local flyboys realize that playing with a flight simulator could be very dangerous indeed. Well done, citizen. The Empire is pleased to reward one such as you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 32, 'm8t', 'Rebel Training Station'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 33, 'm9d', 'Intelligence has finally located one of the Rebellion''s data slicer hubs. This facility could house several HoloNet transceivers and the slicers who operate them. A strike would remove both. Can the Empire count on you to help make the Imperial HoloNet more secure for military communications? '),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 35, 'm9s', 'A most excellent strike, agent. These were the sorts of results we had hoped to get by employing you. Claim your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 36, 'm9t', 'Slicer Hub'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 37, 'm10d', 'Agents within the CSA have informed Intelligence that many of the workers the Viceprexes are requesting for hard labor are being transferred to a holding facility so that Rebel agents can rescue convicted Rebel spies and sympathizers contained among the roster. We need a small team of loyal Imperial agents to obliterate this facility. The Empire is counting on you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 39, 'm10s', 'Well done! We couldn''t have done it any better ourselves. The Empire could use more agents like you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 40, 'm10t', 'Refugee Facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 41, 'm11d', 'A shipment of Merr-Sonn IR-5 blaster pistols has fallen into the hands of the Rebellion and we believe we''ve learned where these deadly weapons are being stored. They will certainly be distributed to various Rebel cells for use in intimidation missions. We must destroy this cache of weapons before those scum can use them against our agents.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 43, 'm11s', 'Those deadly "Intimidators" won''t threaten the safety of our agents. Good work! The Empire gladly rewards success and loyalty.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 44, 'm11t', 'Weapons Cache'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 45, 'm12d', 'Several MD medical droids have been acquired by the Rebellion. Our spies have provided us with the coordinates to the holding facility where these droids are being stored. We cannot allow the Rebels to have access to proper medical care. We require a small team of loyal agents to find this facility and destroy it.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 47, 'm12s', 'A successful strike against the Rebellion. Well done. The reward is yours.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 48, 'm12t', 'Rebel Medical Droids'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 49, 'm13d', 'The Rebels have been targeting Imperial depots containing laser cutters. We believe they need them to build a new operational base although we do not yet know its location. Our agents have managed, however, to locate some of these laser cutters and have sent us the coordinates where they are being housed. We need a few loyal Imperial agents to strike this storage depot.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 51, 'm13s', 'Success! This will doubtless slow the Rebels'' efforts to carve out new lairs. You''ve earned your reward, agent.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 52, 'm13t', 'Laser Cutter Storage Depot'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 53, 'm14d', 'A traitorous Moff has offered to aid the Rebels attempt to assassinate our beloved Emperor. We''ve pinpointed where this traitor and his agents will be meeting with the Rebellion''s agents to make the arrangements. We require an able and loyal Imperial strike team to hit this outpost and insure its destruction. Could you assemble and lead such a team?'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 55, 'm14s', 'We have not ascertained whether the Moff was at that meeting when you destroyed the outpost. We''ll have to continue monitoring communications. In any case, your strike against that Rebel outpost was superb.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 56, 'm14t', 'Hunt a Traitorous Moff'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 57, 'm15d', 'Local garrisons have reported recent Rebel attacks that have employed modified A-A5 speeder trucks as armored personnel carriers. We''ve located several civilian speeder repair facilities that could be used to create these carriers. We want these installations destroyed. Can you assist the Empire in removing this potential threat? '),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 59, 'm15s', 'Good work, agent. We knew these stations were serving those Rebel scum and you''ve helped prove it. We hope this is the beginning of a very profitable career for you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 60, 'm15t', 'Take Out Rebel Repair Stations'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 61, 'm16d', 'The Rebels have taken an interest in certain rare types of crystals. Intelligence has instructed us to destroy any supply depot containing caches of such minerals. We''ve located a small warehouse containing a large quantity of mineral desposits mined from the Outer Rim. We need loyal Imperial servants to vaporize this warehouse.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 63, 'm16s', 'An efficient handling of the mission, agent. Well done. The Empire is proud to reward you.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 64, 'm16t', 'Smash Mysterious Crystals'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 65, 'm17d', 'We''ve been alerted to the presence of a Rebel supply depot that seems to be housing hundreds of climate control units. No doubt these are intended for remote Rebel bases in the Outer Rim. We want these units destroyed and figure a loyal and skilled Imperial agent ought to be able to take care of that for us. No need to call in a full military strike.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 67, 'm17s', 'Clean and efficient, citizen, just like we like it. COMPNOR could use more agents like you. '),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 68, 'm17t', 'Make It Cold for the Rebels'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 69, 'm18d', 'We finally identified the traitor who has been supplying vacuum gyros for Rebel transports. We have the coordinates to the traitor''s secret gyro cache. Unfortunately he knows we are coming. Our sources tell us that a contingent of Rebel soldiers is evacuating the cache. We need to dispatch a team to destroy this contraband before the Rebels take it away.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 71, 'm18s', 'Well done, citizen. Those Gallifree transports slip through our blockades too easily. Perhaps now we can stop those Rebel scum.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 72, 'm18t', 'Cripple Rebel Transports'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 73, 'm19d', 'Ion space mines are an important tool of the Imperial Navy, but in the hands of Rebel terrorists they become a menace to all law-abiding spacefarers. We have tracked a freighter to a known Rebel outpost, where it deposited a load of Defender-class mines. If we can wipe out this factory before its deadly contraband is unleashed, the star lanes will be safe once more.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 75, 'm19s', 'The Imperial Navy is indebted to you. Accept this payment and the gratitude of the Empire.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 76, 'm19t', 'Take Out Space Mines'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 77, 'm20d', 'Rebel pirates have stolen our droids! A shipment of IG-type assassin droids was hijacked en route to a Civil Security Center on Dantooine. Intercepted Rebel transmissions suggest these droids were smuggled to a secret reprogramming facility, where technicians will turn the IGs into gardening and botanical droids. A squad must locate and destroy this facility.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 79, 'm20s', 'The Empire is grateful for your service. IG assassin droids make lousy botanical arrangements. Enjoy your reward.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 80, 'm20t', 'Assassin Droids Do Not Pick Posies'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 81, 'm21d', 'Our probe droids have uncovered an underground maintenance station for a squad of Rebel X-wing fighters. These ships have harried our blockade enforcers for several parsecs, but at last we shall have our revenge. We need a contingent of shooters to slip inside and blast the place to dust. Be careful, as the Rebels have this valuable secret well guarded.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 83, 'm21s', 'We have been tracking those X-wings for many parsecs. At last their destruction is complete. Splendid work.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 84, 'm21t', 'X-Wing Fighter Squad'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 85, 'm22d', 'We''ve discovered a local livestock dealer who harbors seditious motives. Loyal citizens have reported a collection of mynock incubators hidden underneath his shop. Certain factions of the Rebellion employ mynocks as nuisance tactics against our space fleet. We have judged it prudent to destroy the incubation facility in the interest of galactic security.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 87, 'm22s', 'He put up quite a fight for a simple livestock dealer, didn''t he? It seems our suspicions are confirmed. Only a Rebel traitor would have that kind of firepower. Well done, citizen.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 88, 'm22t', 'Mynock Incubator'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 89, 'm23d', 'A local community has recently been plagued by a fake holovid recording that depicts the alleged destruction of Empire''s finest war machine, the Death Star. The transmission has been traced to a broadcast facility. You must take a strike team and decimate this unseemly operation. These untruths will not soil the tranquility of our loyal and obedient communities.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 91, 'm23s', 'Excellent work. Did you happen to view any of the offending holovids before you destroyed them? We''ll send some security agents around to question you, just in case. Don''t worry, it''s a routine debriefing. Who is your next of kin?'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 92, 'm23t', 'Seditious Broadcast Facility'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 93, 'm24d', 'In the midst of an otherwise obedient community, the Rebellion has constructed a power relay cannon that transmits energy beams to passing Rebel fighters. For the public good we must now dispatch a blaster team to blow this relay installation into oblivion. Such an action will assure the locals that the Empire is dilligently protecting their families and properties.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 95, 'm24s', 'Nicely done, citizen. The community has been rendered safe once more. The standard martial curfew will ensure that no Rebels return. '),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 96, 'm24t', 'Rebel Power Relay'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 97, 'm25d', 'The Inquisitorius has ordered a strike on a Rebel outpost that has been conducting unusual experiments involving the Force and Force-users. We cannot imagine that the Rebellion would be foolish enough to attempt to establish another Jedi training academy, especially in light of the corruption that was revealed within the ranks of the old Jedi Order. Can you assemble a strike team to take care of this?'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 99, 'm25s', 'A new breed of Jedi shall not rise to threaten our beloved Empire thanks to you, agent. Well done! The Emperor will hear of your success. Be proud.'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 100, 'm25t', 'Jedi Training Outpost'),
('string/en/mission/mission_destroy_imperial_non_military_medium_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 1, 'm1d', 'Is there no place in the galaxy that is free of pests? Every neighborhood I move into ends up having some sort of infestation or other, regardless of the system or the climate. Thank goodness for hardworking citizens like yourself. Just as I''ve done on all those other worlds, I''m willing to pay a brave citizen a decent reward for ridding our neighborhood of verminous infestation. Do you think you could help? '),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 2, 'm1o', 'A Perturbed Citizen'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 3, 'm1s', 'Pest control at its finest, citizen! Good job! Ever consider going into this line of work professionally?'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 4, 'm1t', 'Exterminate the Pests'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 5, 'm2d', 'I lost one of my prized hunting greysors a few nights ago to some sort of vile vermin infesting this area. Friend of mine thinks he''s located where these creatures are coming from. I can''t afford to lose any more of my champions to those beasts so I''m offering a reward to anyone willing to take up a blaster. Don''t leave a single one of those killers alive, you hear? If these things attacked a well-trained greysor, there''s no telling what they''d do to an unarmed man or a group of youngsters.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 6, 'm2o', 'An Angry Greysor Breeder'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 7, 'm2s', 'Wiped out those creatures, huh? Good going. The reward''s yours, citizen.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 8, 'm2t', 'Save the Prized Greysors'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 9, 'm3d', 'Isn''t the galaxy dangerous enough without bloodthirsty beasts? Late-night sanitation workers have reported being attacked by savage creatures. The attacks have increased in frequency and intensity. We need to stop these predators before they begin attacking innocent citizens during the day. A transport driver reported seeing several of these creatures milling about while delivering some power converters to a nearby station. We have the coordinates of that location and will transmit those to any enterprising citizen who undertakes this mission.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 10, 'm3o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 11, 'm3s', 'Thanks, citizen! You help keep our streets clean and our people safe. Visit us anytime.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 12, 'm3t', 'Take Out the Night Stalkers'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 13, 'm4d', 'Something''s been killing the local livestock. We''re not exactly sure what it is, but it sure does have a voracious appetite for destruction and flesh. Some land surveyors have reported sightings of hunting packs near here. We believe that hunting ground is quite close to the beasts'' lair. We''d like to hire someone to investigate this area and wipe out these creatures. Do you think you could help us with this, citizen?'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 14, 'm4o', 'Galactic Farmer''s League: Local Chapter'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 15, 'm4s', 'Very effective, citizen. You have our thanks and our credits. Enjoy!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 16, 'm4t', 'Save the Livestock'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 17, 'm5d', 'My son was injured by wild predators while playing just outside the city with his friends. I thought the surrounding regions had been cleared of dangerous beasts, but apparently I was wrong. I don''t want this to happen to anyone else''s child. I need someone to search the outlying areas around my community and wipe out any dangerous creatures. I''m willing to compensate for effective results.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 18, 'm5o', 'A Protective Father'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 19, 'm5s', 'My thanks, citizen. Now I can sleep easier knowing that the children are safe. '),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 20, 'm5t', 'Protect the Children'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 21, 'm6d', 'Nature will always keep encroaching on our settlements -- that''s what Nature does, after all. So we have to keep fighting back by clearing away the wild vegetation and wiping out the dangerous fauna. ''Course, we need all the help we can get. We''re offering decent money to anyone that can take care of some pesky critters. We''ve got coordinates to a whole bunch of lairs we need cleaned out. Accept and we''ll send some your way.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 22, 'm6o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 23, 'm6s', 'Excellent work, citizen. You sure do make our jobs that much easier. Look us up again if you want more work.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 24, 'm6t', 'Help Clear the Land'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 25, 'm7d', 'We''re trying to set up a local charity fair, but the area we''ve chosen has vermin we need cleared out. Most of us are not adept at this sort of work, being peaceful business owners and upright citizens. We need to hire someone more comfortable performing this type of task. We''ll pay for positive results. Do you think you could lend a hand? Or a blaster, more like?'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 26, 'm7o', 'Merchant''s Guild: Local Chapter'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 27, 'm7s', 'Those orphans will thank you in the years to come, citizen. Well done! Enjoy the reward.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 28, 'm7t', 'Help Save the Fair'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 29, 'm8d', 'There''s a nest of critters that''s been giving some nerf-herders a hard time, spooking their beasts and causing stampedes. We can''t really spare any men to take care of these creatures, which is why we''re soliciting help. We''re willing to reward anyone who can clean out that nest and put the nerf-herders at ease. Easy money if you''re skilled with a blaster. Think you can help?'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 30, 'm8o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 31, 'm8s', 'That ought to satisfy those herders. Thanks, citizen. Those are results we can live with.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 32, 'm8t', 'Help the Nerf-herders'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 33, 'm9d', 'There''s been a recent outbreak of Hesken Fever in this area, and we think it''s related to an infestation of vermin near here. We need someone to clean that nest out and make sure those creatures don''t spread this disease to other settlements. Payment will be tendered upon completion of the mission. '),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 34, 'm9o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 35, 'm9s', 'Good work. Maybe now we can control the spread of that disease.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 36, 'm9t', 'Halt the Hasken Fever'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 37, 'm10d', 'These dirty creatures cause all sorts of damage to settlements. They eat our food, they often carry diseases, they chew on power cables, they foul everything with their droppings. In short, they''re disgusting! We want this nest of vermin cleaned out, but we won''t use toxins for fear of contaminating our soil and groundwater. A few well-placed blaster shots ought to take care of the problem nicely. Think you can help? There''s a reward in it if you succeed.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 38, 'm10o', 'A Concerned Citizen''s Group'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 39, 'm10s', 'At last our neighborhood will be clean, thanks to you. Enjoy that reward.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 40, 'm10t', 'Help Clean Up the Neighborhood'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 41, 'm11d', 'Vermin infestations are seasonal -- come and go as regularly as the summer winds. Every year we have to deal with it, and every year we hire someone to do it for us. We need some able-bodied beings who aren''t afraid of pests and handy with a blaster. These critters shouldn''t give anyone too much trouble -- though I''d keep my distance all the same, if I were you. Consider it a way to improve your marksmanship. We pay the usual fees for every nest cleared.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 42, 'm11o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 43, 'm11s', 'Always a pleasure to work with professionals. The Empire is pretty good at exterminating pests, wouldn''t you agree?'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 44, 'm11t', 'Blast the Nests'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 45, 'm12d', 'It is the most unpleasant duty of mine to report a terrible terrible animal. Terrible! On my homeworld we did not have such things, no, before we immigrated here. From the side of the road leaped the animal, at me and at my family, even here my little baby! Is this not terrible? There is something must be done! I wish to pay you if you will locate the animal and teach it a lesson. Yes! Also please sorry for my talk in Basic, at home it is not speaking often.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 46, 'm12o', 'A New Homeowner'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 47, 'm12s', 'It is a truth, the goodness of this news! I am most happy, most happy to pay you as we agreed. Also visit me at my new restaurant, I will make you delicious fleek eel.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 48, 'm12t', 'A New Arrival Has Animal Trouble'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 49, 'm13d', 'Many years ago I faced slavering reptavians in the swamps of -- now where was that place? I forget the planet. So I know what it is to look fanged death square in its slitted eye! Now I''m just old and fat and slow, that''s all. Too slow to catch whatever it is that''s been prowling around my cabin, out here in the wilds. The thing swallowed a radio beacon by accident, though -- at least I think it was an accident -- hungry critter! Anyway, if you can track this animal and kill it, I''ve got a bounty for you. Bounty, heh, that''s a pricey word for animal hunting. Why, I remember one bounty hunter -- well, never mind that now. Just report back when you kill it.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 50, 'm13o', 'A Retired Mercenary'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 51, 'm13s', 'That''s the way you do it, youngster! Makes me think of my old days in the swamps of, of, wherever that place was. Why, the water there was so dirty you couldn''t tell it from your own -- well, never mind that now. Here''s your pay, thanks. Stop by and see an old soldier someday.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 52, 'm13t', 'Old Man with Critter Trouble'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 53, 'm14d', 'It is more than I can bear. Some wild beast has brutally slaughtered one of my purebred voorpaks from the finest pedigreed kennel of Naboo, Ch. Princess Transversion Sunbeam LaFlorin IV. I called her Spotty. I was taking the air one evening outside the vacation mansion, with dear Spotty purring peacefully in the sleeve of my best evening gown. Suddenly a coy peeping sounded from the gardens, which stirred Spotty strangely. She leapt forth and vanished in a trice. Oh, wicked Spotty! I fear I shall never forget the gnashing of teeth, the foul gulp as Spotty disappeared down the beast''s gullet. Go, you! Slaughter the beast and avenge my beloved pet!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 54, 'm14o', 'Lady Isshala Deprovan, late of the Naboo countryside'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 55, 'm14s', 'Thus must fate deal with all such slayers of innocent voorpaks. Oh Spotty, how I miss your pleasant purr. Here is your payment; that will be all for now.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 56, 'm14t', 'Lady Deprovan Requires Revenge'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 57, 'm15d', 'Of late I think I may never feel joy again. Never have I given such affection as that I lavished on the leading mother of my voorpak litter, Ch. Empress Sunwinds Messenger Chung-Chung LaFlorin III. Dotty, that was my pet name for her. Dear Dotty! Had I only known, when I put you and your newest litter out on the porch of the speeder-house for a bit of fresh air, that a beast of unsavory aspect would make you its meal! Now, so that I may someday earn a good night''s sleep, I must commission you, or some equivalent tradesperson, to go forth and kill the predator that swallowed Dotty. Satisfy my will, and I shall reward you!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 58, 'm15o', 'Lady Isshala Deprovan, late of the Naboo countryside'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 59, 'm15s', 'Now at last may Dotty''s spirit go to a peaceful rest. Leave your name with the droids in case I need you again.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 60, 'm15t', 'Lady Deprovan is Distraught'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 61, 'm16d', 'With heavy heart I recount this sad tale. Last night at the summer house I let out the prime stud of my purebred voorpak breeders, Ch. King Monperro Carveth LaFlorin the Fancy Troubadour, to answer nature''s call. An instant later Trotty -- that was my pet name for him, Trotty, for how he loved to run! -- scratched to be let in. Distracted by a serving droid''s request, I was late in opening the door. Suddenly something large thudded against the door from outside, and when I dared to open it, I found nothing left of Trotty but his eight fine feet. This awful place, with its awful beasts! You must slaughter the thing that ate Trotty, whereupon I shall disburse a fitting reward.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 62, 'm16o', 'Lady Isshala Deprovan, late of the Naboo countryside'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 63, 'm16s', 'Take your blood money and leave me to mourn my dear lost Trotty!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 64, 'm16t', 'Lady Deprovan Verges on Despair'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 65, 'm17d', 'Greetings. I am engaged in research on predation of the tesselated arboreal binjinphant, a small but entirely fascinating herbivore. My university fellowship depends on successful defense of my thesis, that contrary to belief, these small creatures represent only a negligible source of protein in the larger ecosphere. I am on sabbatical away from the binjinphant''s native habitat, but I suspect I may find similar evidence in the local fauna. To that end, I hire you to locate a local predator at an agreed location, sacrifice it -- kill it, in layman''s terms -- and relay your report to me. I shall pay you from recent grant monies.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 66, 'm17o', 'Asst. Prof. Herian Reborran Naxx'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 67, 'm17s', 'Delightful news. I shall examine the sacrificed specimen and integrate the research into my thesis. I send you the fee forthwith.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 68, 'm17t', 'Professor Seeks Specimen'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 69, 'm18d', 'Greetings. As assistant professor of xenobiology at Polar Farside University on the planet Hrennt, I seem to find myself up a tree. I am not speaking figuratively. I have been investigating local predator life-cycles, and now one particularly fierce specimen appears to be investigating me. Could you please come to these coordinates, with all due haste, and dispatch this beast? For your early attention you have my earnest thanks.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 70, 'm18o', 'Asst. Prof. Herian Reborran Naxx'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 71, 'm18s', 'While you engaged the beast, I made a surreptitious yet hasty retreat. What travails we endure for the cause of knowledge! Please accept this payment with my gratitude.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 72, 'm18t', 'Professor Seeks Rescue'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 73, 'm19d', 'A tenured colleague of mine in academe contends, on unconvincing or even spurious evidence, that the tesselated arboreal binjinphant is a negligible source of protein for predators in its native ecosystem. What eyewash! I take the more defensible contrary position. My ill-advised colleague seeks dubious confirmation of his thesis in the local wildlife. To forestall his jaundiced distortion of truth, I intend to make a competing analysis of my own. Please locate a predator in the designated area and dispatch it. When you report to me, I shall remit payment and arrange pickup of the specimen.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 74, 'm19o', 'Teaching Asst. Morbitt Horn Rotundi'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 75, 'm19s', 'Excellent. I predict I shall find evidence to rebut my colleague''s preposterous thesis. From there, I foresee a clear path to a plum associate professorship.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 76, 'm19t', 'Scholar Seeks Contrary Evidence'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 77, 'm20d', 'Binny and I were at the local hangout, just hanging out, and we got to arguing. We need you to settle a bet: How big do the mushwumps get around here? You know mushwumps -- at least that''s what we called them back home -- I forget the local name. When you get to these coordinates -- we hear there''s a big one there -- you''ll know the animal I''m talking about. Once you kill it, let us know and we''ll settle the bet. Killing a mushwump does the world a favor, anyway. The loser has to pay your fee, and buy a round for everyone else!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 78, 'm20o', 'Kebert Lomanna'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 79, 'm20s', 'Okay! Hey, from the looks of that mushwump, I win the bet! Wooo! Wait while I get Binny to settle with you. Pay up, loser! Hee hee! Okay, thanks, buddy. Later.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 80, 'm20t', 'Settle a Bar Bet'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 81, 'm21d', 'Something out there ate my betrothal necklace. Long story. Short version: picnic to celebrate the engagement, I wander away with my sweetie, sweetie chases me, I lose the necklace. I go back to look later, nothing but animal tracks. I don''t recognize the tracks. Cut to the chase: You kill whatever animal around there was big enough to swallow my necklace. When you report back, I''ll pay you and send my secretary to search the corpse. Gotta go, duty calls.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 82, 'm21o', 'A Busy Executive'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 83, 'm21s', 'Got the creature? Check. Payment dispatched.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 84, 'm21t', 'Missing Betrothal Necklace'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 85, 'm22d', 'I''m not entirely sure I''m going about this the right way, but if I need a fierce predator''s pelt for my upcoming production -- "Hearts of Empire," opening at the Playhouse, seats still available -- and if the local furrier has nothing suitable, then it only makes sense to get one on the hoof, right? Or on the claw, or wing, or whatever. I haven''t got a big prop budget, but the scene demands a palpable authenticity. Get me a nice pelt. Speed appreciated, must run now.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 86, 'm22o', 'Radanthus Mandelatara, Playwright'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 87, 'm22s', 'I can''t use that thing, it''s all bloody! And the aroma is a bit, shall we say, intense for the theater. Well, I suppose I did ask. Here''s your fee, must run. (Now what am I to do with this carcass? Hmm, inspiration is striking....)'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 88, 'm22t', 'Theatrical Prop Needed'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 89, 'm23d', '[Friendly greeting.] I hope this [curse] box speaks my mind true. I seek [local large animal?], about the size of [untranslatable], for return to home and use in [untranslatable] ritual. Much high ceremony, very serious. Need has brought me far. But [sorrowful exclamation], I am hurt in recent hunt. To you who will aid me, I promise [payment] and everlasting [untranslatable].'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 90, 'm23o', 'A Visitor from Wild Space'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 91, 'm23s', '[Joyous exclamation.] I pay you as this [protocol droid] shows me. I give you gratitude and [untranslatable].'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 92, 'm23t', 'Ceremonial Animal Required'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 93, 'm24d', 'They call me crazy for my obsession, but all pioneers start out as pariahs, right? I''m out to prove that the creature called the Rodian gasbloater is not just a myth, but exists right here in this sector! Furthermore I have the coordinates of an actual gasbloater lair. What I don''t have is a way to retrieve a specimen. So I''m willing to pay someone who''s handy with a blaster to travel to this lair, kill what you find, and bring the carcass back to me. The pay isn''t great, but how often do you have a chance to contribute to scientific history?'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 94, 'm24o', 'A Dilligent Cryptozoologist'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 95, 'm24s', 'That doesn''t look like a Rodian gasbloater. Are you sure that''s all you found at the lair? Hm. I guess I need to do some more research. Here''s your money anyway.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 96, 'm24t', 'Bag a Rodian Gasbloater'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 97, 'm25d', 'I''ve got a tiny problem. I run a small, you know, discreet business breeding exotic and dangerous animals. I hired a Jawa to clean up around the place, so it shouldn''t have surprised me that a couple of my animals got loose. I put tracking chips in ''em, so I know where they went, but there''s a catch. If the authorities find me within a league of these beasts, they''ll have my head because of my past offenses. So I need someone to take a blaster to the animals and solve my little problem.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 98, 'm25o', 'A Nervous Breeder'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 99, 'm25s', 'Shame to lose those perfectly saleable beasts, but I''ve got to look out for myself. Thanks for a job well done.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 100, 'm25t', 'Discreet Breeder Has a Tiny Problem'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 101, 'm26d', 'Oh, my goodness! Our zoo ship crashed and the surviving animals have escaped! We need someone to help clean up our mess. We have a list of coordinates where we think the animals have gone. Careful, some of them can get a little grumpy. We''ll pay you for each successful retrieval. We understand that some of the animals have been wounded in the crash; in such cases, simply verify their identity collars and we will pay you for your work.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 102, 'm26o', 'A Distraught Zoo Ship Captain'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 103, 'm26s', 'Oh, dear. Yet another animal so wounded from the crash that it didn''t survive. Well, here''s your payment anyway.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 104, 'm26t', 'Retrieve Animals From a Crashed Zoo Ship'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 105, 'm27d', 'Have you ever heard of an animal that eats droids? Neither have I, but there''s one stalking around my land. I''ve lost four range droids in the last week. I found the creature''s tracks and followed them to these coordinates. I just need someone to go out there and put a laser hole in the darn thing. It''s worth it for me not to lose any more droids.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 106, 'm27o', 'An Annoyed Droid Owner'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 107, 'm27s', 'Huh! I never knew they ate droids. Strangest thing, isn''t it? Anyway, thanks for the help. Have a night on the town, my treat.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 108, 'm27t', 'Blast a Droid-eating Beast');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 109, 'm28d', 'My neighbor keeps the strangest pets. Ugly things, dangerous things, it seems there''s no kind of alien creature he won''t chain up in his yard. Well, one of his monstrosities has gotten loose and has been terrorizing the rest of us. I''ve got the coordinates where the thing has settled in. Can you haul that weapon of yours out there and do us all a favor by getting rid of it? I''ll throw a few credits your way. Trust me, when you see it, you won''t believe someone would keep it as a pet.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 110, 'm28o', 'An Irked Neighbor'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 111, 'm28s', 'Didn''t I tell you, that''s the meanest thing to keep as a pet? I don''t understand some people. Thanks for getting rid of it.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 112, 'm28t', 'Get Rid of an Escaped Pet'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 113, 'm29d', 'I heard the local kids talking about some sort of "killer beast" in the area, so I thought I''d better hire someone to check it out. Take a blaster along and get rid of whatever''s out there, will ya? No need to take any chances if our children might be in danger. Much obliged.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 114, 'm29o', 'A Concerned Citizen'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 115, 'm29s', 'So there was something out there after all, eh? Thanks much. Here''s the money, just like I promised.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 116, 'm29t', 'Exterminate a "Killer Beast"'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 117, 'm30d', 'That''s it, I''ve had enough! My master may disapprove, but I simply must do something about this awful brute that''s been chewing at my circuits while I''m shut down. I have never seen the animal in full light, I''m afraid, but I can tell you it''s about so big and it''s either got scales or fur. Or perhaps it''s feathers, I can''t be certain. I believe there''s only one, but sometimes it seems as if there are a thousand! I have narrowed down the possible locations of its lair to these coordinates. I have a few credits to pay to someone, anyone who can rid me of this nuisance!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 118, 'm30o', 'A Protocol Droid'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 119, 'm30s', 'Bless the maker! I''m ever so pleased that you''ve removed this burden from me. Take these credits with my most heartfelt gratitude.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 120, 'm30t', 'Please Rid me of This Confounded Nuisance!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 121, 'm31d', 'We have uncovered an insidious smuggling ring operating in this sector. Some enterprising lawbreakers have been hiding contraband inside the body cavities of wild animals to evade our scanners. Because we do not have the staff to inspect every wild creature on the planet, we are authorizing civilians to exterminate all life forms in the regions we have designated. Interested parties may contact us for coordinates. Remuneration available upon completion.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 122, 'm31o', 'Imperial Customs'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 123, 'm31s', 'Excellent work. The region is still quite active with wildlife, so please move to the back of the line to receive additional target coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 124, 'm31t', 'Stop Some Enterprising Smugglers'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 125, 'm32d', 'We are pleased to announce the arrival of a distinguished ambassador from the planet Aaldus 6, newly entered into the Empire. The ambassador brings trade and goodwill to us from his wealthy star system, and we are making preparations to welcome him. Specifically, he has expressed certain aesthetic reservations about the local fauna. To accomodate his preferences, we have determined that all local wildlife must be removed. To this end we are paying interested parties to visit coordinates we provide and terminate all non-sentient life forms. These civic-minded actions will contribute greatly to the cause of galactic harmony.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 126, 'm32o', 'Imperial Diplomatic Corps'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 127, 'm32s', 'Splendid. Soon our lovely vistas shall be blissfully uncluttered of anything that flies or crawls. The ambassador will be most appreciative.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 128, 'm32t', 'Help Spread Peace in the Galaxy'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 129, 'm33d', 'We have an infestation of destructive fauna chewing on some of our buried power cables. The situation must be resolved before a military delegation arrives from Coruscant in a few weeks. Those wishing to contribute to this effort may contact the IME for the coordinates of several trouble spots. Eradicate all organisms in these problem areas and you will be compensated with Imperial credits and gratitude.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 130, 'm33o', 'Imperial Ministry of Energy'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 131, 'm33s', 'Now that you have cleaned up the wildlife, we can send out a repair droid to fix the damaged power cables. Thank you for your good work, citizen.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 132, 'm33t', 'Exterminate a Menace to Public Works'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 133, 'm34d', 'The IZA is responsible for cataloging alien species on new worlds. When we learned that a celebrated new subspecies discovered on Raxxa 4 already exists on an inhabited planet, we were obligated to address the discrepancy in our bookkeeping. Our solution is to erase all trace of this subspecies from the inhabited planet, thus ensuring that our catalogs are accurate. Our satellites have pinpointed the locations of all nests on the planet. We now require freelance agents to help eliminate this subspecies and advance the progress of science in the Empire.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 134, 'm34o', 'Imperial Zoological Agency'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 135, 'm34s', 'We at the IZA care about alien wildlife in the galaxy. We appreciate your contribution to our efforts.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 136, 'm34t', 'Assist in Cataloging a Rare Subspecies'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 137, 'm35d', 'I have found the perfect place for a zaela garden! That''s a rare thing in this area. Do you know how long I''ve wanted to try my hand at growing millaflowers? The only problem is, there''s a nest of rather nasty-looking animals right in the middle of it. My husband indulges me every luxury when it comes to my gardening, and he has agreed to pay someone to get rid of these brutes. Would you be a dear, take your blaster and fry them into sizzling charcoal for me? And hurry, because the planting season is near!'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 138, 'm35o', 'Mrs. Doaten Dodder'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 139, 'm35s', 'Aren''t you the nicest dear in the system? Thank you for your convenient blaster work.'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 140, 'm35t', 'Be a dear and Scat Some Pests For Me'),
('string/en/mission/mission_destroy_neutral_easy_creature.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 1, 'm1d', 'Hey, fella! Or maybe "Hey, lady," or "Hey, thing," I don''t care. I have this package that urgently needs to go to a certain destination, where a certain party will retrieve it later. I just scouted the area, and whoa, it''s crawling with critters. I can handle a blaster as well as the next guy -- assuming the next guy is sort of a coward -- but big-game hunting is out of my league. I''m willing to cut you in on part of my pay if you dispose of these creatures. Take the hide, the meat, whatever looks tasty, I don''t care. But do it fairly quick, huh?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 2, 'm1o', 'A Corellian Entrepreneur'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 3, 'm1s', 'Great pest disposal there! Here''s your cut, and feel free to loot the bodies. I expect the rest of this operation will go off without a hitch. What could go wrong?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 4, 'm1t', 'Creature Removal at Drop Point'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 5, 'm2d', 'I''m out here in the middle of noplace, where I had a run-in with a client after a transaction went bad. I don''t think it''s productive to get into "who shot whom," but now this guy has it in for me. Who knew he kept all kinds of dangerous beasts in, I don''t know, a kennel or something? He''s sicced these things on me, and let me just say I''m not much of a hunter. I''m holed up in a safe spot for the moment, but they''re prowling closer. I would REALLY LIKE someone to come out here and take care of these things, permanently. I''ll pay! I''ll pay a lot!'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 6, 'm2o', 'Corellian with Unfortunately Short Temper'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 7, 'm2s', 'Okay, I''ve caught my breath, I''m all right. Nice work. I took the liberty of making an exit while you did your deed. Here''s your pay, hope I don''t have to use you again.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 8, 'm2t', 'Dispute Escalated to Surprising Degree'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 9, 'm3d', 'I have a can''t-miss business proposition. You kill the animals, I record your exploits and sell the broadcast rights to a local HoloNet program my buddy is starting up. It''s not there yet, but the investors want to see content, so we''ll pay you out of our seed money for a dynamic, gripping slaughter-fest. I''ve located the animals, I''ve rented the hovercams and set them in place, I''ve got it all arranged, so all you have to do is relax and blast a few beasts into Corellian dust. Maybe that''ll be the title of your segment, "Blast Them to Corellian Dust!" Whaddya say?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 10, 'm3o', 'On Our Way to the Corellian Dream'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 11, 'm3s', 'That was great! My recording is sure to sell this show. I''ll just -- oh, wait -- was this the "on" switch, or --? Tell you what, I''ll get back to you.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 12, 'm3t', 'Blast Beasts For Corellian HoloNet Show'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 13, 'm4d', 'Understand first that I''m just the flunky here. It''s not my operation. So I don''t have a reason why these guys all started shooting at me. I was just the delivery boy! I stole a speeder and ran for the horizon -- they followed -- a certain amount of blaster fire occurred -- everybody crashed, and then these giant -- somethings leaped out and killed everyone but me. I got away narrowly, but now my employer strongly requests me to recover the item I delivered. I expect it''s now in the belly of one of those animals, so I''m asking you to shoot them all and let me recover the innards later. Believe me, this has been a rotten day. '),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 14, 'm4o', 'Corellian Just Trying to Do a Job'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 15, 'm4s', 'Okay, at last one thing goes right. I''ll speed back out there and do the excavation, or whatever you call it. Thanks, here''s your fee.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 16, 'm4t', 'Recover Item From Animal Intestines'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 17, 'm5d', 'Talk all you want about the evil Empire and how these are bad times, but I''ll say this: The rise of the Empire has been very good for my business. There''s always a demand for the service I provide. It calls for piloting down some risky off-road routes, though -- and it never helps when a pack of animals takes up residence right along my main "back way." Which is what''s happened now. I''ll pay you well to go in and blast them into permanent inconsequentiality. Hey, nice phrase, huh?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 18, 'm5o', 'A Corellian Businessperson'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 19, 'm5s', 'Fine job. It''s a pleasure dealing with professionals. Your fee is attached.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 20, 'm5t', 'Corellian Beasts Menacing Traffic'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 21, 'm6d', 'Sheesh, I am so down on life right now. I mean, I had a nice line of work, running some goods here and there for my employer. And you know, what with the stuff I brought them, folks were always, always glad to see me. But then I got greedy -- they tell you never to get greedy, but I did! -- and I took a cut from my employer''s earnings that I wasn''t entirely entitled to. We parted on really bad terms, you might say, and -- long story short -- now I''m holed up in the wilderness with a bunch of hungry animals roaring for my guts. It''s so depressing. If you can see your way clear to destroying these beasts, I''ll cut you in on those earnings I mentioned.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 22, 'm6o', 'Corellian in Need of Quick Emotional Lift'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 23, 'm6s', 'Okay, something''s finally going right. I took the opportunity to run for the city while you were out there fighting. Nice job, and here''s the pay you earned.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 24, 'm6t', 'These Animals Depress Me'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 25, 'm7d', 'I''ve flown from one end of this galaxy to the other, and I never saw anything to make me believe you can control a bunch of wild animals just by pointing your finger. But during a transaction out here in the wilderness I happened to offend this weird mystic-looking woman -- never mind how. She raised a claw, and a bunch of beasts rampaged in out of nowhere, eager to have a little Corellian snack. It must be pheromones or perfume, maybe -- something long-lasting, because they''re still trying to rip open this vehicle like a food container. I''ll pay you well to come here and take care of this problem, immediately and for good.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 26, 'm7o', 'A Corellian Wanderer'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 27, 'm7s', 'That''s a big relief. I took the opportunity to speed out of there while you were working. That Selonian may come back. In fact, maybe it''s time to visit Sullust. I always wanted to visit Sullust.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 28, 'm7t', 'Selonian Pets Unjustly Attacking Speeder'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 29, 'm8d', 'It is incumbent on my clients to retain confidentiality, so I must be circumspect in describing my problem. Briefly, I arranged a transaction in a remote area between two parties, and was planning to mediate at this exchange of ideas and goods. However, an animal or animals has menaced my clients as they travelled to this remote area. This has discouraged them from pursuing the transaction. Because of the importance of a successful resolution, I am commissioning you to journey to the attached coordinates and dispatch the animal or animals. Payment is reasonable for this brief service.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 30, 'm8o', 'Itinerant Corellian Transactional Specialist'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 31, 'm8s', 'I congratulate you and tender the agreed payment. I shall inform my clients at once.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 32, 'm8t', 'Transaction Hampered by Corellian Wildlife'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 33, 'm9d', 'In these troubled times an individual may wish to journey between locations without undue Imperial attention. I serve this reasonable desire. However, on my current transport assignment, a beast of unusual ferocity damaged my speeder, stranding me and my client in unfortunate circumstances. I''d like you to journey to this general vicinity and destroy the beast and, if needed, its fellow pack members. Under no circumstances are you to search for me or my client, who strongly requests anonymity. I will transmit payment when you have performed the service.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 34, 'm9o', 'Corellian Specializing in Discreet Transport '),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 35, 'm9s', 'Excellent. I appreciate your discretion in avoiding contact. Your payment is attached. I have repaired my speeder and must now resume the transport contract.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 36, 'm9t', 'Rescue Anonymous Stranded Travellers'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 37, 'm10d', 'I need to get out into the countryside and dump this bag of garbage, right? I mean, I''m dumping it at a particular spot before a particular time, so that a particular garbage collector can retrieve it. Don''t worry, it''s just garbage. Trouble is, I scouted the territory from a distance, and there''s all kinds of animals wandering around. I mean big ones, with teeth and all. I don''t mess with that, especially while carrying this, uh, garbage. You take care of the animals, like by killing them all, and I''ll cut you in on my hauling fee.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 38, 'm10o', 'Corellian Urgently Seeks Waste Disposal'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 39, 'm10s', 'All right, you just clear out of that area, and I''ll dump my garbage. Thanks for the rescue. Lots of stress in the garbage-dumping line, let me tell you.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 40, 'm10t', 'Help Dispose of This Garbage'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 41, 'm11d', 'I love animals, I really do. Why, the times I''ve diverted my speeder to avoid hitting some harmless eopie or cute little kittle -- even though it delays my courier mission, mind you, and my employers really don''t like delay -- well, I admit, I''m a softie. But it''s time to take a hard line with this current pack of beasts. They''re trouble. And when you make trouble by interfering with my speeder on a major overland route, a route that nobody in an Empire suit has ever seen, then you''re in pretty dangerous territory yourself. The animals are, I mean. In that territory. Um, I''m losing the thread of my subject here -- basically, even though I love animals, I need you to kill this bunch before they ruin my business. Clear?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 42, 'm11o', 'Corellian Breaking Emotional Attachment'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 43, 'm11s', 'Of course it''s a sad time, what with the death of those innocent animals. But you know, it had to be done. I think I''m almost over it now, the heartbreak I mean. Gotta go.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 44, 'm11t', 'Take a Hard Line Against Animal Interference'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 45, 'm12d', 'Our business is selling fireworks, but now that I think about it, nobody''s bought fireworks for, oh, ten or fifteen years. So we buy and sell certain other things, and business is okay. It''s just -- we have this animal problem. We were carrying certain valuable non-firework commodities through a remote area recently, on our way to a delivery, when something large and fierce and active jumped us. It was dark, so we couldn''t see. When we got away, we realized we''d dropped our commodities. We really would like to go back and get them, but we need you to clear the area of dangerous animals first. We''ll pay you from our fireworks production budget, which we don''t use any more.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 46, 'm12o', 'Corellian Fireworks Transport'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 47, 'm12s', 'A fine job. We could use more people like you in the fireworks business.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 48, 'm12t', 'Help Fireworks Dealer Get Past Animals'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 49, 'm13d', 'Despite pervasive public ignorance and apathy, the Interplanetary Embalmers'' Guild labors heroically to inform the galaxy of its worthy mission. Our chapters on Corellia exhibit all the vigor and pertinacity that a good embalmer should. We seek Corellian hunters to locate the finest specimens of wildlife, no matter whether on the grassy hillsides or the golden beaches or the towering peaks, and shoot them cleanly. We shall arrange pickup and processing of the remains, provided they are intact and relatively unmarked. Do your part to help a noble profession achieve just and lasting recognition.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 50, 'm13o', 'Interplanetary Embalmers'' Guild'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 51, 'm13s', 'Though your good work fulfills the Embalmers'' Guild wishes, our plans have changed. Accept this payment, and do what you will with the creature.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 52, 'm13t', 'Embalmers Call on Conscientious Corellians!'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 53, 'm14d', 'The Emperor''s proposed new Hall of Galactic Wildlife, to be built on the Imperial throneworld of Coruscant, features an extensive display of Corellian fauna. To expedite planning of the space required for the Corellia display, the Imperial Civilian Accounting Office solicits highly experienced hunting teams. Interested teams may locate and terminate large packs of animals at coordinates provided by local survey offices in conjunction with this agency. The specimens will be assessed for size and quantity for purposes of figuring large-scale space requirements. Hunters may remove marketable assets from the prey for their own use. All other information on this contract is assigned confidential clearance under Imperial security edicts. For assistance, contact the Imperial Security Bureau.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 54, 'm14o', 'Imperial Civilian Accounting Office'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 55, 'm14s', 'Asset procurement noted and contract payment disbursed. Per your contract, you may remove marketable assets from the prey for your own use or resale.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 56, 'm14t', 'Solicitation For Corellian Hunters'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 57, 'm15d', 'I am an archaeologist with Coronet University. My field team has been excavating in a remote area, searching for a supposed network of Selonian tunnels that apparently predates the Old Republic. My colleagues are skeptical, but our research was starting to show promise -- until a band of local animals began menacing our camp. This has upset my students and threatens to drastically set back our schedule. I have appealed to the Empire for help, without result. The University has kindly granted me an additional stipend to be disbursed to an agent such as yourself, who can destroy these beasts and permit the continued march of science.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 58, 'm15o', 'Dr. Tennet Sionaro, Coronet University Archaeology Dept.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 59, 'm15s', 'Splendid! Our dig will resume immediately. I must admit I hold out little hope of finding these putative Selonian tunnels, but one cannot dismiss such tales out of hand.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 60, 'm15t', 'Coronet Archaeology Site Menaced'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 61, 'm16d', 'Corellian Horticultural Digest, now entering its third century of publication, sends researchers hither and yon across our wild Corellian landscape. One brave investigator, following a hot lead regarding trioecious cycad carpophylls, blundered into a lair of dangerous beasts. In his last communication before his comlink got eaten, our man said he had sequestered himself in a place of safety. Please journey with all haste to his coordinates and dispatch these beasts.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 62, 'm16o', 'Corellian Horticultural Digest'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 63, 'm16s', 'Joyous news! While you occupied the beasts, our researcher made a rapid escape and is even now dictating his notes. Trust us, this article will break the entire cycad carpophyll field wide open.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 64, 'm16t', 'Horticultural Researcher Under Siege'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 65, 'm17d', 'In addition to its well-known repair facilities, Guildhouses, and financial services, the Merchants'' Guild offers Corellian members basic travel information about every region of Corellia. We contract with independent researchers to assess the dangers that may await members stranded in remote locales. To participate in our current research cycle, please report to the attached coordinates to engage and destroy the animals present. Guild hovercams will record the event, and we shall update our guidelines based on our assessment of the threat posed.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 66, 'm17o', 'Corellian Merchants'' Guild'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 67, 'm17s', 'Our hovercams recorded the event, and we are updating our guides accordingly. Thank you for participating in this research cycle.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 68, 'm17t', 'Surveying Ferocity in Remote Areas'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 69, 'm18d', 'A local entertainment figure, Bop Thrombo the Shaky Droid, got into animal trouble out in the wilderness while rehearsing his latest slapstick stunt. This is big news for Corellian comedy fans. Our hovercams track Bop at all times, just in case, and we''ve got great views of this fierce something-or-other tearing him to bits. Now we''d like to recover his brain for an interview, but we need someone to clear out the animals first. Can you help?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 70, 'm18o', 'Corellian Sector Newsfeed'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 71, 'm18s', 'Great! We''ll send out a news crew to put Bop Thrombo''s brain into a duplicate housing and get the on-the-scene interview. Clear out before we get there, please.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 72, 'm18t', 'Help Recover Bop Thrombo''s Brain'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 73, 'm19d', 'We''ve tracked yet another starship that squeaked past Orbital Customs. Our turbolasers crippled the vessel and it crashed near the Golden Beaches. Trouble is, the ship was smuggling some dangerous animals that were jettisoned in escape pods for later retrieval. We recovered the pods but the animals had already escaped. Our scout droids have found them, snugly settled a few clicks from the pod site. We''ve already wasted enough manpower on this problem, so we''ve decided to contract civilians to exterminate these animals before they cause any harm. Contact us for the coordinates and we''ll put you on the case.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 74, 'm19o', 'Corellian Defense Force'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 75, 'm19s', 'Thanks for handling that potentially dangerous situation. We''re sending out a team to dispose of the carcasses.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 76, 'm19t', 'Exterminate Contraband Animals'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 77, 'm20d', 'It''s not that I don''t appreciate the beauty of the Agrilat Swamp. Boiling showers and razor-sharp grass are a joy to experience. But when the swamp''s larger wildlife chooses to wander into more civilized areas, I''ve got to draw the line. The farmers in the area are getting worried. They''ve asked me for help. I don''t want to waste Corellian Security resources on this, so I''m paying any civilian who can do the job to find these misplaced creatures and put them out of my misery. Call it restoring the ecosystem.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 78, 'm20o', 'Lieutenant Moss Shelby, CorSec Regiment Twelve'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 79, 'm20s', 'Nice. The farmers aren''t worried anymore and that means I''m getting fewer interruptions at work. Everyone is happy.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 80, 'm20t', 'Large Creatures on the Move'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 81, 'm21d', 'Remember when the Circus Horrificus came to Corellia a while back? Turns out they "misplaced" some sick animals while they were here. Now we''ve got reports that these creatures miraculously recovered from their illnesses and are now threatening the safety of some farmers near here. Removing them could be time-consuming endeavor, so we''re contracting civilian hunters to deal with the situation. Contact us and we''ll send you the last known coordinates of these wayward beasts.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 82, 'm21o', 'Captain Peers, Corellian Defense Force'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 83, 'm21s', 'Maybe we shouldn''t be surprised that an outfit called Circus Horrificus left behind a mess. The next time they grace Corellia with a visit, we''ll sit down with them for a long chat.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 84, 'm21t', 'Circus Horrificus Left a Mess'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 85, 'm22d', 'Even though the shipyards get all the glamor, we farmers are the real backbone of Corellian culture. Who else is going to feed all those offworlders who pollute the space lanes with industrial waste? But even so, the planetary authorities are eager to neglect our needs. For instance, we''re having a problem with some local wildlife encroaching on our fields. CorSec isn''t interested in helping us. So we collected enough credits among ourselves to pay a professional hunter to get rid of these intrusive animals. Seems like we have to handle our own security in addition to feeding a hungry planet. There''s no justice, I tell ya.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 86, 'm22o', 'A Proud Corellian Farmer'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 87, 'm22s', 'Thanks for getting rid of those creatures. You''re a good friend to us farmers. I''m glad someone on this planet still cares about us.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 88, 'm22t', 'Job That CorSec Doesn''t Want'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 89, 'm23d', 'While the Selonian Tunnels are an interesting feature of the Corellian landscape, they do present certain problems for planetary security. For instance, animals that are either large or numerous enough to be a nuisance will wander the tunnels and emerge in places where they should not be. These incidents are frequent enough that CorSec now engages freelancers to liquidate the stray animals. This program is open to all qualified galactic citizens. Coordinates of target animals are available upon request.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 90, 'm23o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 91, 'm23s', 'Nice work, citizen. We''ve got many more stray animals to deal with, so feel free to contact us again.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 92, 'm23t', 'Animals Wandering Selonian Tunnels'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 93, 'm24d', 'The right place at the right time, that''s what business is all about. I''m planning to build a small manufacturing plant and I picked up some terrific property from the estate bazaar in Coronet. You wouldn''t believe the price I got. I feel like a regular thief. The only drawback is, the land is infested with some kind of dangerous animals. That''s what the purchase agreement said, anyway. All I know is, I want some tough guy to hoof out there and get them off my property. I''m working to fund my little factory and I need to haul investers out there soon. I''ve got the right place, but I have to hurry to finish at the right time. Are you the right person for the job?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 94, 'm24o', 'Fillig Tandaris, Entrepreneur'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 95, 'm24s', 'Now that was some handy work, my friend. You''re better than you look. Stick around, maybe I''ll find something else for you to do.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 96, 'm24t', 'Fine Print on Purchase Agreement'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 97, 'm25d', 'Corellia seems like such a peaceful planet, doesn''t it? Well, it ain''t all purple skies and golden fields. We''ve got some nasty animals around here that are giving me all kinds of headaches. My construction droids are malfunctioning because some sort of wild beasts are tearing up their wiring and fouling their exhaust grates. I programmed a few load lifters to chase the creatures back to their lair, but I need a flesh-and-blood hunter to finish them off. I''ll pay a decent wage for the work, so long as I can get back on schedule.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 98, 'm25o', 'Fillig Tandaris, Entrepreneur'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 99, 'm25s', 'Handy work, my friend. If I apply a little motivation to my droids, maybe I can get back on schedule.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 100, 'm25t', 'Wild Beasts Fouling My Droids'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 101, 'm26d', 'Corellia! Proud center of commerce for the entire galaxy! I''m thrilled to be here at last, ready to carve my niche in financial universe, though my business plan has proven inadequate in a few respects. I didn''t know Corellia''s wildlife was quite so intrusive. To be brief, the site for my new office complex is overrun with native creatures. As I just arrived, I don''t even know what they''re called, but I do know they approach me threateningly. I require someone who knows the area wildlife to do whatever it takes to get rid of the beasts. I can''t let teeth and claws interfere with my conquest of galactic commerce!'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 102, 'm26o', 'Mister Tild-Ob-Hoona, Recently Arrived on Corellia'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 103, 'm26s', 'Wonderful! Now that those creatures are gone, I can proceed with my plan to amass a fortune and build a mercantile empire. Would you like to invest?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 104, 'm26t', 'Corellia Is Wilder Than I Thought'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 105, 'm27d', 'We were flying home after a Kessel run. We crash-landed due to a spat with the Imperials. The trip home from the crash site was, how should I say it, eventful. Among other highlights, we ran into some kind of big roaring thing in the dark, and we had to drop some cargo. Fast. Still makes me shudder to remember it. We''re safe back home now, but we need to retrieve that cargo. We don''t want to face the roaring thing again, whatever it was, so we''re hiring you to dispose of it before we arrive. We''ll retrieve the cargo ourselves, thank you.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 106, 'm27o', 'Corellian Travellers Back Home at Last'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 107, 'm27s', 'In a long string of unhappy events, this is finally good news. Here''s your fee, and we''re on the way now to pick up our cargo.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 108, 'm27t', 'Clear Out Site of Lost Cargo'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 109, 'm28d', 'I''ve had an accident that I need to clean up. For reasons I won''t bore you with, I was flying my YT-1300 freighter close to the ground not far from this terminal when my power core ruptured. I leaked radioactive fuel into a small water system. It was all I could do to limp back to Tyrena before the Corellian authorities spotted me. Now I''m worried that the animals who drank that water are going to glow. The radiation signature might lead the authorities back to me. I want to hire you to blast the animals at the following coordinates. My gratitude will be boundless, if discreet.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 110, 'm28o', 'A Freighter Captain'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 111, 'm28s', 'Thanks, you really saved my neck. Have some fun in Tyrena, on me.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 112, 'm28t', 'Help Clean Up a Little Mess'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 113, 'm29d', 'You may have heard of the swoop course we run over in the mesas. Some of us intend to branch out and clear some new lanes around the planet. Can you imagine swooping through Agrilat or even the Selonian Tunnels? But there''s a lot of dangerous animals out there that are definitely not welcome on a course. We''ve pinpointed a list of trouble spots for future races. The animals must go. We''ve got the money to pay you for the work, if you''ve got the talent to crush these creatures.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 114, 'm29o', 'An Enterprising Swoop Enthusiast'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 115, 'm29s', 'Wizard, buddy. We''re heading out there now to fly the route. If you''ve got a swoop, why don''t you join us?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 116, 'm29t', 'Swoop Lanes With Wild Animals?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 117, 'm30d', 'These rich Naboo are starting to bother me. We had a family buy a plot on Vreni Island to build a vacation home. Of course they had to remove some of the wildlife. How did they accomplish that, these oh-so-enlightened Naboo? You guessed it. They stunned the creatures, tossed them on a transport and dumped them at some random spot on the mainland. Because killing them would be cruel, or whatever. Anyway, now we''ve got to put these animals to sleep before they hurt somebody. I''ve got a small budget to hire a hunter for the task. Are you interested?'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 118, 'm30o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 119, 'm30s', 'You did good work. It''s ridiculous that we had to eliminate those animals, but we can''t stem the tide of "enlightenment" rising from Naboo.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 120, 'm30t', 'Episode of Naboo Enlightenment'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 121, 'm31d', 'Last week we tracked a gang of Lamproid smugglers to a meeting ground a short distance from this terminal. The smugglers dispersed but they left us with a problem. Apparently they had collected a small menagerie of ill-tempered animals to stage a live version of dejarik. The Lamproids freed the animals when we arrived. Now the creatures have built lairs all over the place. This problem is best handled by experienced hunters who know the area. CorSec will pay a nominal fee for the destruction of any of these lairs. Contact us for target coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 122, 'm31o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 123, 'm31s', 'Good job, citizen. These animals are a threat to anyone traveling through the area. If you care to have a go at another lair, just contact us.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 124, 'm31t', 'Lamproid Smugglers: a Messy Bunch'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 125, 'm32d', 'When you''ve got as much open countryside as Corellia, people start thinking they can land their ships anywhere and set up for business. While we do not discourage non-traditional commerce, we do insist that freelance entrepreneurs respect the planetary landscape. Lately we''ve had problems with campsites left behind by itinerate businessmen. The garbage at these sites attracts wildlife of a bothersome and sometimes dangerous nature. This is a nuisance for local inhabitants. While the law enforcement arm of CorSec pursues the culprits, the ACD is left to clean up the messes that have already been made. For this purpose we regularly contract hunters to exterminate the animals that wander too close to populated areas. Contact us for the coordinates of target sites in your area.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 126, 'm32o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 127, 'm32s', 'Well done. You''ve made the area safe for the locals again. Hopefully we can catch the culprits whose trash lured those animals from the wilderness. We all agree that non-traditional commerce is a vital component of the Corellian economy, but a few people have to learn that some rules still apply.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 128, 'm32t', 'Mess Left by Itinerant Businessmen'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 129, 'm33d', 'Does anyone like the Empire snooping on their private affairs? I certainly don''t. Strictly in the interest of personal privacy, I''m going to build a sensor scrambling array not far from here. The site is in the wilderness and is, unfortunately, a bit thick with large animals. I''d like to hire you to remove these creatures from my property, so I can begin construction. If you can do the job, let me know and I''ll send you the coordinates. You can''t miss the place. It''s in a wide-open field where you might expect to find a landing pad, say, or maybe an underground warehouse. Not that I would know about such things.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 130, 'm33o', 'A Right-Thinking Businessman'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 131, 'm33s', 'Good, good. Now I can build those sensor scramblers. I don''t want the Empire watching when I have visitors to my, um, field out in the wilderness.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 132, 'm33t', 'In Interests of Personal Privacy'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 133, 'm34d', 'I''m in a predicament. I just had a flyby with an Imperial shuttle and it forced me to land not far from here. My ship went down pretty rough, but I made it to the city okay. Unfortunately, I didn''t realize until I hit town that I had buckled a cargo door and lost a crate of Mad Mrelf in the wilderness. I buzzed the spot again and it''s overrun with animals. If those creatures finish off a whole crate of that liquor, they''re going to go berserk. Can you go out there and take a blaster to those beasts before someone gets hurt? From the air I couldn''t make out exactly what kind of animals they were, but you should be ready for a real scrap. That Mad Mrelf will put scales on a Qwohog.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 134, 'm34o', 'An Unfortunate Pilot'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 135, 'm34s', 'You handled those creatures better than I could have. Didn''t I tell you that Mad Mrelf would turn a voorpak into a veermok? That''s quality stuff. Such a waste to lose it.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 136, 'm34t', 'Liquor Fallen Into Wrong Hands'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 137, 'm35d', 'See here, I need the services of a veteran of the Corellian wilds. I am recently arrived from Naboo to acquire some native fauna for my daughter''s menagerie at Theed. I hope to bring my little Lady Gaeflit something large and glamorous for the Festival of Thywinkle, but my time grows short. A local tracker in my employ has transmitted to me the coordinates of a group of wild animals which he believes will be suitable for my purpose. I require someone who knows the area to travel to these coordinates and bring back the creatures in question. Of course I understand the unpredictability of wild animals, so I shall of course pay you something for your trouble if you find no living specimens at that destination. Please be cautious and know that your good work will make a little Naboo girl happy.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 138, 'm35o', 'Lord Kindergull of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 139, 'm35s', 'What''s that? You say no living specimens are left at those coordinates? Oh, but this is a tragedy! Now what gift shall I bring poor Lady Gaeflit for the Festival of Thywinkle? Her little heart will be crushed! At least I know you did your best to make her happy. Here, accept this payment with my gratitude.'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 140, 'm35t', 'Make Little Naboo Girl Happy'),
('string/en/mission/mission_destroy_neutral_easy_creature_corellia.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 1, 'm1d', 'Laboring under a curse of public ignorance and apathy, the Interplanetary Embalmers'' Guild maintains its resolve to bring its mission to a wide audience. Our chapters on Naboo, though not large, demonstrate an admirable vigor. We seek Naboo hunters with strong will, careful aim, and superior firepower. With these weapons, you will go forth onto the plains, into the forested mountains, and even into the swamps themselves, to locate the finest specimens of Naboo wildlife and shoot them cleanly. We shall arrange pickup and processing of the remains, provided they are intact and relatively unmarked. Those who aid in promoting our worthy trade will find generous recompense!'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 2, 'm1o', 'Interplanetary Embalmers'' Guild');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 3, 'm1s', 'Though your good work fulfills the Embalmers'' Guild wishes, our plans have changed. Accept this payment, and do what you will with the creature.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 4, 'm1t', 'Embalmers Call On Conscientious Naboo!'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 5, 'm2d', 'The Emperor''s proposed new Hall of Galactic Wildlife, to be built on the Imperial throneworld of Coruscant, features an extensive display of Naboo wildlife. To expedite planning of the space required for the Naboo display, the Imperial Civilian Accounting Office solicits highly experienced hunting teams. Interested teams may locate and terminate large packs of predators at coordinates provided by local survey offices in conjunction with this agency. The specimens will be assessed for size and quantity for purposes of figuring large-scale space requirements. Hunters may remove marketable assets from the prey for their own use. All other information on this contract is assigned confidential clearance under Imperial security edicts. For assistance, contact the Imperial Security Bureau.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 6, 'm2o', 'Imperial Civilian Accounting Office'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 7, 'm2s', 'Asset procurement noted and contract payment disbursed. Per your contract, you may remove marketable assets from the prey for your own use or resale.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 8, 'm2t', 'Solicitation for Naboo Hunting Teams'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 9, 'm3d', 'Greetings. Milady Chantallir requires me to commission a hunter, or party of hunters, to assassinate a designated specimen or specimens of local wildlife. Once you have committed this gratuitous murder, Milady''s serving droids will collect the victim and prepare it for her upcoming "Cuisine & Culture" fundraising banquet. Milady has instructed me to remit payment after you have inflicted the brutal death.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 10, 'm3o', 'Imbecile, a C-9P0 Protocol Droid'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 11, 'm3s', 'Milady will undoubtedly feel well disposed toward you for carrying out the execution. Here is the agreed blood-money.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 12, 'm3t', 'Dead Animal Needed for Banquet'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 13, 'm4d', 'The touring company for my current production -- "Hearts of Empire," now at Theed''s Templexus of the Dramatic Arts, seats still available -- has run into a teensy problem. Our female lead, Mairlenn, had a pet voorpak, called Dotti or something. She took the little thing with her on a visit to the countryside, let it roam, and, well, those voorpaks really are a major source of protein in the ecosystem, aren''t they? Mairlenn is in quite a snit. She saw the creatures that ate Dotti, and she insists that I find someone to locate and punish those beasts, I mean really punish them. Is that okay?'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 14, 'm4o', 'Radanthus Mandelatara, Playwright'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 15, 'm4s', 'Well, isn''t that just a big big relief. I do have a budget line item for Mairlenn''s demands, so payment is no problem. Thanks much, have to run.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 16, 'm4t', 'Punishment of Naboo Predator Needed'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 17, 'm5d', 'When I open my new restaurant in Theed, the much-heralded pantheon of Naboo chefs will gain a new star! I need a centerpiece dish, though, to get people smacking their lips and, in the case of Gungans, jowls. Go out and find me a selection of delectable beasts. Remember, dangerous creatures equal publicity!'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 18, 'm5o', 'Chef Jamien Varcos'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 19, 'm5s', 'Splendid. I shall pay you, of course, but as it happens, I have conceived a different dish in mind already, with liquid extract of Corellian fringe cake. Please take what you will from the creature''s body.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 20, 'm5t', 'Create a Culinary Delight of Naboo!'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 21, 'm6d', 'For my new gallery''s debut show, I contrast the sterility of urban life with the pure, unmediated vigor of Nature. I envision in the gallery atrium a mounted specimen of some noble creature. It befalls you, the hunter or team of hunters, to terminate the specimen, whereupon my rented droids will secure and prepare it. I suggest a relatively non-invasive termination, to maintain the specimen''s natural beauty.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 22, 'm6o', 'Bab Esrus, Biosculptor for Select Clients'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 23, 'm6s', 'Unfortunately my show, "Nature''s Unmediated Vigor," has been unexpectedly cancelled. I shall pay you, but you may dispose of the creature as you will.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 24, 'm6t', 'Help With Naboo Gallery Show'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 25, 'm7d', 'I watch the purple twilight steal across the meadows of my estate, then spend my lonely night dreaming of a song. That melody haunts my reverie, for it was playing during my romantic dinner with Count Ran Dobell. We sat beside a garden wall, and the stars shone bright. Our love was new, each kiss an inspiration -- until a verminous creature blundered into my gazebo. The beast bit Count Dobell, infecting him badly. In a huff he lurched away to the bacta tanks, and he has avoided contact with me since. Now my consolation lies in hiring you to destroy this creature and others of its ilk.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 26, 'm7o', 'Lady Dera Mikkel of Theed'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 27, 'm7s', 'Thank you. Though I dream in vain, that melody will remain in my heart -- the memory of love''s refrain. '),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 28, 'm7t', 'Stop Creature That Ruined True Romance'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 29, 'm8d', 'Perfecton Greysor Purebreds stands as Naboo''s finest kennel. We have reason to believe that an unidentified rival greysor kennel has purposely loosed several predatory animals on our land, creatures that have already attacked and killed several fine stubtails and manadepts of breeding age. We shall of course investigate and seek legal redress. Our immediate need, though, is a hunting team that can destroy the marauding predators. We offer a generous fee, as befits the planet''s elite kennel.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 30, 'm8o', 'Perfecton Greysor Purebreds'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 31, 'm8s', 'Your success shows excellent attention to standards and detail. We thank you, and are now preparing the legal phase of our response.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 32, 'm8t', 'Predators Loosed On Greysor Kennel'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 33, 'm9d', 'I am a Theed University biologist currently on sabbatical at the Otoh Gunga Zoological Research Facility. In researching motts, a semi-aquatic herbivore of the Gungan Swamp, I was stunned to observe young adult males occasionally travelling onto the Great Grass Plains and even up mountains, far outside their native habitat. This phenomenon as yet eludes explanation, though I suspect parasitic infection. In every case I have seen so far, predators kill these misplaced motts. I wish to hire a hunter or hunting party to terminate a predator shortly after it eats the mott. I shall analyze the predator''s stomach and blood, in hopes of identifying different stages in the life-cycle of the hypothetical parasite.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 34, 'm9o', 'Dr. Henro Torrth, Theed University Bio Department'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 35, 'm9s', 'Report noted. I shall have the fallen predator picked up for autopsy. Your fee is attached.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 36, 'm9t', 'Naboo''s Misplaced Mott Mystery'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 37, 'm10d', ' My family wrangles shaaks on the Grass Plains. This season predators have been hitting us hard. Two nights back, my oldest went out hunting them. Last night he called in, but today we''ve heard nothing. We''re worried, but we can''t leave the herd. We have enough savings to hire a hunter for a rescue mission. Here are the coordinates from his tracking beacon. Please help, and quickly.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 38, 'm10o', 'Shaak-wrangler on the Great Grass Plains'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 39, 'm10s', 'Thanks for taking care of the predators. My son got swept over a waterfall and lost his tracking beacon, but he''s back home now, injured but safe. Here''s your fee.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 40, 'm10t', 'Need Help Finding Our Son'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 41, 'm11d', 'For generations my family''s cove of trained twirrls, the famed Highscouter bloodline, has provided breeding stock to Theed Palace. The key to the Highscouter cove''s reputation for health and vigor has been our willingness to train the falconoids strenuously over open country. For this reason, predators are a constant menace, and never more than this season. I always have to contract with local hunters to keep the predator population down in our current training fields. Are you available?'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 42, 'm11o', 'Highscouter Twirrl Cove'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 43, 'm11s', 'We''ve already noted the welcome drop in predation. Highscouter Cove thanks you. Look in with us next season for more work.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 44, 'm11t', 'Predator Culling in Twirrl Training Fields'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 45, 'm12d', 'While on sabbatical at the Otoh Gunga Zoological Research Facility, I have observed an unusual, previously unreported behavior in the common ikopi, a swamp herbivore with remarkably long legs and a hollow prehensile tongue. It appears that during mating season, some male ikopi actively seek confrontation with predators for purposes of display and territorial defense. My colleagues are justly skeptical, for all my recording equipment has rotted in this infernal humidity. I can document the behavior indirectly by securing a predator that has wounds from the distinctive ikopi horns. I have located a wounded animal and wish you to kill it, leaving the horn wounds intact for reference purposes.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 46, 'm12o', 'Dr. Henro Torrth, Theed University Bio Department'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 47, 'm12s', 'I shall make arrangements to secure the corpse immediately. Decomposition sets in so quickly in this climate. You may take what you will from the prey.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 48, 'm12t', 'Ikopi-Wounded Predator Needed'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 49, 'm13d', 'Hello! Out near my vacation land, where my family hopes to build a home soon, we''re starting to see young male gualamas. The patriarch of a herd drives off the other males when they reach breeding age. They''re beautiful to see, bounding up hills with tails raised like banners. But they do attract predators. That has spooked the construction firm we''ve hired -- seems the predators attack construction droids, or so we''re told. Sounds to me like a ploy for the construction company to extort insurance funds from us, but it''s cheaper for me to demonstrate that the predators are no problem. If you can go out and kill a few, I''ll pay a reasonable fee.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 50, 'm13o', 'Naboo Family Planning to Relocate'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 51, 'm13s', 'Thanks much for improving my land''s safety. I''ll notify the construction company that no "insurance" is required.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 52, 'm13t', 'Gualama Herds Attracting Predators'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 53, 'm14d', 'I am the associate proprietor of Naboo''s third-oldest guarlara stable. Though we do not provide the royal steeds of Naboo that are revered worldwide, our Kirkhorn Assured Bloodlines are particularly prized for their underfur. It has been woven into Theed''s most famous tapestries. Unfortunately, our mighty mounts are prone to stress-shedding, especially when chased by predators. Seldom do these hunters overmaster our vibrant animals, but the exertion of the chase mars the underfur''s quality. To prevent further deterioration, Kirkhorn wishes to hire you to dispose of the animals located to date. Please respond, and we shall transmit coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 54, 'm14o', 'Kirkhorn Guarlara Stable'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 55, 'm14s', 'Perhaps it may seem frivolous to protect guarlara underfur, but this is an important revenue source for our stable. Thank you for your help.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 56, 'm14t', 'Protect Naboo''s Kirkhorn Guarlaras'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 57, 'm15d', 'During my recent open-air concert, staged out on the Grass Plains as part of Milady Aaltok''s 90th-birthday celebration, a pack of creatures hampered the jovial mood by attacking the guests'' prize guarlara mounts. Now some guests are making litigious noises, on the flimsy pretext that my music angered and provoked the predators. What nonsense. Still, counsel advises Milady to show a good-faith effort to reduce future predator problems. Ergo, the Aaltok household is hiring you to defeat and dispatch the creatures located at these coordinates. Really, this is all most tiresome.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 58, 'm15o', 'Nath Matua Nurtry, Aaltok Household Composer'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 59, 'm15s', 'Very well, I shall pay you. I may require your testimony if this senseless lawsuit ever becomes more than mere persiflage.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 60, 'm15t', 'Hunt to Prevent Groundless Lawsuit'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 61, 'm16d', 'The Emperor has proposed a new Hall of Galactic Wildlife on his throneworld, Coruscant. Animals from across the galaxy are to be stuffed and mounted for display in its silent chambers. Without questioning the Emperor''s motives or the wisdom of his project, architects of Naboo would assert that wildlife is best displayed alive, in a zoological simulation of their native environments. To dramatize our point, we shall present to the project''s advisory board a display, showing live creatures side by side with sterile, stuffed examples. We therefore commission you to terminate the specimen or specimens located at these coordinates, for later removal and processing by this office.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 62, 'm16o', 'Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 63, 'm16s', 'Though the Office of the Chief Architect tenders the agreed payment, our plans have changed. You may take what you wish from the prey.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 64, 'm16t', 'Naboo Architect Requires Animal Specimens'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 65, 'm17d', 'I fear that I unwisely scolded my little pet voorpak, Blotti, when he made an accident on my third-best embroidered gown. Blotti, his fierce heart rebelling, ran away. His tracking collar shows he''s wandered into some dangerous territory, and I''m afraid to go after him. Can some noble adventurer rescue my dear sweet pet?'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 66, 'm17o', 'Lady Prua Nala Bitterbon of Theed'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 67, 'm17s', 'Oh, Blotti! Some giant beast has eaten my poor, headstrong little pet. Go away, leave me in my sorrow!'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 68, 'm17t', 'Help Rescue a Beloved Pet'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 69, 'm18d', 'A bioengineering program at Theed University researches new uses for the chemicals produced by native wildlife. This initiative has already led to new medicines and even improved building materials. To this end, students in the bioengineering program require recently killed specimens. Predators represent a difficult target for mere university researchers, and so they have requested me to contract with hunters to destroy the animals. Please respond to obtain coordinates of likely specimens.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 70, 'm18o', 'Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 71, 'm18s', 'I shall send a recovery team to preserve the animals for study. You may take what you wish from them first. Thank you for aiding the cause of science.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 72, 'm18t', 'Theed University Bioengineers Need Specimens'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 73, 'm19d', 'Mesa not custom to dealen wit outlaunders, but my been sent by De Bosses to taken care of a maxibig problem. De zoo at Otoh Gunga had orderen some bigge animale for showen at de Festival of Bawoonkas. De trouble came when de ship carryin desan animale crashed. Now wesa got desan animale all over. De Bosses tellen my only to bring back dosan animale dat survived de crash. Mesa tinken my can pay yousa outlaunders to "taken care" of desan survivor animale, so wesa not haven any survivors at all. Dat way my will not need to transporten dosan stinkowiffs back to Otoh Gunga. My will payen extra if yousa keepen yousa mouth shut about dis. Tis a bombad deal for both of ussen, eh?'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 74, 'm19o', 'Torba Keels of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 75, 'm19s', 'De Bosses beesa sad dat no animale survived de crash. My not minden so much. Yousa skill is hot, boyo. Taken dis moola for yousa help.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 76, 'm19t', 'Wesa Got a Maxibig Problem'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 77, 'm20d', 'I appreciate the natural beauty of Naboo as much as anyone else. I love the smell of flowering hsuberries and the glint of morning light through a tentacle fern. There''s nothing more lovely than a sunset glittering with sapphire peko-pekos. But I draw the line when sapient beings are endangered wildlife. Recently a Twi''lek child was assaulted by some rampaging animal, and one of her little tentacles was badly mauled. In response to this outrage, I am hiring hunters to remove animals from any region identified as dangerous. If you agree that the safety of our beautiful planet must be preserved from encroaching wildlife, and if you are capable of killing deadly animals, please contact me. I will send you coordinates from my list. Together we can make Naboo safe again.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 78, 'm20o', 'Taneb Magnex of Theed'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 79, 'm20s', 'Splendidly done. That''s one more area the children of Naboo may wander in peace. I will certainly have more work for you in the future.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 80, 'm20t', 'Remove Dangerous Animals From Beautiful Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 81, 'm21d', 'Bubble spore is a rare and delightful plant from the Lianorm Swamp. Its bubble-like spores float on the breeze and catch the light most splendidly. Recent climatological extremes have carried the spores over great distances. We believe that the plant may be spreading beyond the swamp. Unfortunately, certain animals have taken to eating the spores before they can alight and sprout. Because we would like to encourage the spread of this marvelous flora, we require the service of hunters to eliminate the animals from target expansion zones. By slaughtering these filthy beasts, you will help us to spread the enchanting bubble spore plant to all corners of Naboo.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 82, 'm21o', 'Botanical Consortium of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 83, 'm21s', 'Marvelous! Those worm-ridden beasts won''t interfere with the spread of bubble spores again. At this rate, in a year all of Naboo will be covered with bubbles! Can you imagine?'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 84, 'm21t', 'Assist Spread of Naboo Bubble Spores'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 85, 'm22d', 'I''m attempting to build a flora farm as a surprise for my wife. I''m having a deuce of a time because the site is away from civilization, in accordance with my wife''s love of the wilderness, and the creatures who inhabit the area are less than accomodating about our intrusion. Consequently I find myself in need of contractors to clear off these distinctly un-neighborly fauna. I''m working on an aggressive time schedule. Get the job done quickly and thoroughly, and you will make my wife very happy indeed.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 86, 'm22o', 'Lord Jallandra of Theed'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 87, 'm22s', 'Are you certain the animals are gone? I don''t wish to place my wife in any danger, you know. If you''re positive the job is done, then I shall tender your payment. And take also my heartfelt thanks for making my wife happy.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 88, 'm22t', 'Contractors To Eliminate Wild Naboo Animals'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 89, 'm23d', 'I pilot an old H-type chrome yacht, which I rent to high-paying customers. I also sell my services as a courier, which has prompted me to post this message. The other day I had a near-miss with an Imperial shuttle cutting across the designated sky lanes. The shear damaged my yacht''s wings and forced me to jettison some cargo. Now I need to retrieve it. I buzzed the area and found some nasty-looking animals on my scanners. I need someone handy with a blaster to pick off these creatures so I can track down my jettisoned cargo. The recipients are getting impatient, so haste is required.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 90, 'm23o', 'Captain Gwella Incarta'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 91, 'm23s', 'Handily done. Now I can retrieve my jettisoned cargo. If I hurry, I can just about salvage my reputation as a courier.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 92, 'm23t', 'Clear Out Nasty-Looking Naboo Wildlife'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 93, 'm24d', 'The authorities don''t approve of us, but that doesn''t deter the swoop enthusiasts of Naboo. This beautiful planet virtually begs for the open-air joys of swoop ranging. Of course the wildlife is not accustomed to anything more powerful than Imperial speeder bikes. This can cause a lot of trouble. Our engines and exhausts rile the animals into a dangerous frenzy. We''ve lost more than a few good swoopers by slamming into a fambaa or a herd of shaaks. To alleviate this problem, we''ve taken up a collection to hire professionals to remove the more intrusive wildlife that clogs up our swoop lanes. If you can do this job, please contact us for the coordinates of trouble spots.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 94, 'm24o', 'United Swoop Enthusiasts of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 95, 'm24s', 'At last we can ride the swoop lanes without dodging hrumphs and tusk-cats. We''re also investigating the possibility of clearing away vegetation from prime areas. After all, swoopers have as much right as anybody to enjoy the natural beauty of Naboo.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 96, 'm24t', 'Kill Wild Animals Clogging Swoop Lanes'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 97, 'm25d', 'The trouble with a planet like Naboo is, the wildlife is so prolific that there''s no glamor in hunting it. I make my living taking rich Theedsiders into the wilderness to hunt large, dangerous animals. But my skills seem extraneous when the animals simply wander past base camp, waiting to be shot. So I''ve struck upon a plan to rectify this issue. I want to hire hunters to visit my preferred hunting grounds and weed out prolific target species. That way I can hunt down the survivors, and my clients will feel as if they''re getting their money''s worth. So if you''re good with a blaster and want to have some fun in the wilderness, I''ll send you coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 98, 'm25o', 'Gerrio Coronis of Theedside Safaris'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 99, 'm25s', 'Nice work. I''ll take some rich Theedsiders out there tomorrow. You did leave me one or two animals to hunt, right?'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 100, 'm25t', 'Thin Out Wildlife in Hunting Grounds'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 101, 'm26d', 'I''ve got my droids busy on some preliminary work to turn a natural spring pool into an irrigation source. My belief is that the spring''s source might actually be the planet core. Unfortunately my J9 droid reports that animals from the surrounding area have been attracted by the activity. These creatures are either very large or in great numbers, as their droppings have begun to contaminate the pool and clog up the new filters. I would like to hire one or more experienced hunters to blast these animals to dust so that my project can get back on schedule. Pay will be commensurate with the difficulty of the job.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 102, 'm26o', 'Madger Galleas of Theed'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 103, 'm26s', 'My J9 droid says the filters are clearing up already. Thanks for a job well done. Here are your credits.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 104, 'm26t', 'Blast Animals Fouling Naboo''s Water'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 105, 'm27d', 'Desan outlaunders don''t haven much sense sometime. My have taken una Trandoshan warrior into da wilderness for hunten de bigge Naboo animale. Hesa needen to impress some lady Trandoshan for una marriagen ceremony, if mesa understanden correctly. Den desan animale showed up and hesa hiden like a skeered tooke. Hesa say hesa not comen out of hiden till mesa hire someone to getten rid of desan animale. Hesa payen my fee, so my figure my may as well do what hesa want. You gotten de blaster, you wanten some credits, you contact my pretty soon. My not certain how long hesa going to last out dere in de wilderness.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 106, 'm27o', 'Torba Keels of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 107, 'm27s', 'Yousa should have seen dat Trandoshan runnen away as soon as yousa started shooten up de animale! My wish my had brought una hovercam for taken dat as a hologram. Okieday, heresa yousen moola for da job.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 108, 'm27t', 'Una Outlaunder is Needen Help'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 109, 'm28d', 'We are incensed at the behavior of the Imperial Environmental Preservation & Refocusing Authority! To accomodate various Imperial sites on the planet''s surface, the IEPRA has interfered with the rich ecosystem of Naboo. The natural balance of predator and prey has been disrupted. We must restore this balance. We have identified several habitats in which both predatory and prey species must be culled in order to realign the populations. Hunters who appreciate the natural balance are encouraged to participate in this program. We must save Naboo before the Empire destroys it!'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 110, 'm28o', 'The Royal Naturalist Society of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 111, 'm28s', 'But how wonderful! We knew we could count on you. The delicate balance of Naboo''s wildlife will soon be restored.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 112, 'm28t', 'Empire Interferes With Naboo''s Ecosystem'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 113, 'm29d', 'The IEPRA conducts routine missions to expunge dangerous animals from any area where Imperial agents are scheduled to establish service posts. Lately we have experienced some problems. The larger creatures of Naboo have somehow managed to encroach upon our temporary sites. We have consulted the Royal Naturalist Society of Naboo, but they offered no insight as to why our wildlife eradication protocol is failing. As we continue to research this problem, we require hunters to manually clear these areas again so that our agents may conduct their business in peace. Interested parties may contact us at their convenience.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 114, 'm29o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 115, 'm29s', 'Well done. We shall note the quality of your work in our files. We hope to determine soon why our initial efforts at wildlife eradication have failed.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 116, 'm29t', 'Eradicate Dangerous Naboo Wildlife'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 117, 'm30d', 'In the name of galactic security, Imperial agents routinely establish temporary survey sites in the wilds of Naboo. Before each site is constructed, the IEPRA expunges any dangerous and/or nuisance animals from the area. We have found it expedient to hire private contractors for this work. If you are an experienced hunter and wish to become involved in this program, notify us at your earliest convenience. We will send coordinates of a target locale from which to remove the wildlife.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 118, 'm30o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 119, 'm30s', 'Well done. Your actions have ensured the safety of many Imperial agents. You are on your way to establishing a good record with us.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 120, 'm30t', 'Eradicate Hazardous Naboo Wildlife'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 121, 'm31d', 'The Imperial Environmental Preservation & Refocusing Authority persists in its destabilization of Naboo''s splendid ecosystem! After they devastated many of our precious natural populations, we were forced to cull others to preserve the natural balance of predator and prey. Now they have hired despicable murderers to kill more animals and further disrupt the ecosystem. We have no choice but to respond again. We require the services of noble outdoorsmen willing to euthanize the poor, starving animal survivors of the Empire''s heartless campaign. Contact us for the coordinates of these killing grounds, and we shall pay you for your merciful actions.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 122, 'm31o', 'The Royal Naturalist Society of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 123, 'm31s', 'But how wonderful! Your ruthless killling was an act of pure mercy. Shame on the Empire for forcing us into these desperate measures!'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 124, 'm31t', 'Correct Empire''s Interference With Beauty'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 125, 'm32d', 'De wild animale of Naboo been suffering at de hands of some stinkowiff outlaunders. My been catchen desen illegal animale traders allendover half de planet. Tis una shame dat desen narglatches just letten loose de animale anywhere dey getten caught, so dey can getten away from de law. Tis una shame because my no haven de resources to collect dese misplaced animale and taken dem back to where dey belong. All my can do is to payen someone to taken a weapon to desen animale and putten dem out of dere misery. Mesa hiren every persona dat can get de job done. My will transmitten de coordinatees to yousa and payen de credits when yousa finish de work.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 126, 'm32o', 'Sergeant Degoolsby of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 127, 'm32s', 'Tis a shame dat desen illegal animale traders forced ussen to dese sad measures. Taken desen credits for yousa good work.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 128, 'm32t', 'Rounden up de Animale and Killen Dem'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 129, 'm33d', 'If you spend a lot of time offworld, you may not know about the strange weather we''ve been experiencing. Stellar flares are responsible for a moisture inversion that has brought rains to dry areas and reduced water levels in the lowlands. This climatological chaos has resulted in overabundant wildlife where it is normally under control. While we are applying for the intervention of Imperial weather shields to block the stellar flares, we are employing more direct methods to regain control of the wildlife populations. We are contracting hunters to thin out groups of large, prolific and/or dangerous animals in certain areas. If you qualify to participate in this reclamation campaign, contact planetary authorities. We can stave off disaster, but only if we act promptly.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 130, 'm33o', 'Naboo Environmental Council'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 131, 'm33s', 'That''s one more region where the wildlife will not become a nuisance. Thanks for your good work and professional demeanor.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 132, 'm33t', 'Flares Disrupt Naboo Animal Populations'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 133, 'm34d', 'A wealthy family of Togruta merchants have decided to make Naboo their next home. I am surveying the landscape for a location suitable for a modular villa. Unfortunately, their homeworld is rife with predators, and their preferred surroundings are also populated by large and potentially dangerous animals. Because I don''t want my clients to be eaten or trampled while I''m presenting their choices, I need to hire someone to temporarily rid these areas of nuisance wildlife. I''ll send the coordinates to anyone who can get the job done neatly.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 134, 'm34o', 'Chanja Kee of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 135, 'm34s', 'Great work. The wealthy Togrutas will reach Naboo in a few days. I''m glad to be able to show them around safely.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 136, 'm34t', 'Arrival on Naboo of Togruta Clients'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 137, 'm35d', 'Some local animals have ingested contaminated runoff from the Emperor''s Retreat. We believe that these creatures now pose a significant risk to the planetary ecosystem. They have dispersed to various places on the planet. We are contracting hunters to dispose of these animals as quickly as possible. Our satellite droids have isolated several potential locations where these contaminated animals might be found. These coordinates will be made available to qualified applicants.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 138, 'm35o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 139, 'm35s', 'Excellent. Our scanners indicate a significant amount of contamination in your body. This confirms your successful engagement with the target animals. As we do not know what effect this contamination might have on your particular subspecies, we suggest that you make arrangements for a funeral or other death rite in the event that you do not survive.'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 140, 'm35t', 'Contamination In Naboo Ecosystem'),
('string/en/mission/mission_destroy_neutral_easy_creature_naboo.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 1, 'm1d', 'How many times do we have to exterminate these pests? Hiring professional hunters is getting expensive. Could you go in and clear out that creature lair for us, citizen?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 3, 'm1s', 'Looks like you might have a career in extermination, friend. Thanks for your efforts.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 4, 'm1t', 'Clear Out Tenacious Pests'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 5, 'm2d', 'I''m lodging a group of Bith musicians in my villa, but they''re skittish about some of the local wildlife. I''d be willing to pay if you could remove some of the more dangerous creatures from the area and put these Bith at ease.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 7, 'm2s', 'Splendid! Now my Bith guests can relax and practice their music. I do enjoy their fizz lilting through my villa on a lazy evening.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 8, 'm2t', 'Reassure Skittish Musicians'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 9, 'm3d', 'Some darn predator ate my good luck kima! I think those beasts have a lair near here. If you can find them and blast them to atoms, I''d certainly reward you.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 11, 'm3s', 'Thanks, friend. I''ll sure miss that kima. I bet this breaks my incredible sabacc winning streak. '),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 12, 'm3t', 'Recover Good Luck Charm'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 13, 'm4d', 'My precious little kittle -- she liked to be called Woopywoopums -- was snatched by a horrible predator while slithering playfully in my yard. Please avenge my angel for me.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 15, 'm4s', 'You are most gallant, citizen. What is your name again? I want to name my new kittle in your honor.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 16, 'm4t', 'Avenge Woopywoopums'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 17, 'm5d', 'I''ve been contracted to do some construction near here. Help me out by cleaning up the nest at these coordinates, and I''ll cut you in.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 19, 'm5s', 'Nice work. I''ve never seen the need for a professional exterminator before. Those guys get the big money.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 20, 'm5t', 'Help Clear Land'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 21, 'm6d', 'A condemned shelter near here is nothing but a breeding ground for bloodsucking parasites. I bet a couple of well-placed blaster shots would take care of the problem. Can you help, friend?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 23, 'm6s', 'Well done, citizen. This ought to make the wet season much more pleasant. Enjoy your reward!'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 24, 'm6t', 'Prepare For Wet Season'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 25, 'm7d', 'There''s a den of vermin out there that is gonna kill some youngster some day. Local kids love playing in that area. Be a friend and demolish that lair for us, would you?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 27, 'm7s', 'I''ll be able to sleep peacefully at night now. Thank you kindly.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 28, 'm7t', 'Keep Kids Safe'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 29, 'm8d', 'The last thing I want to hear when I settle down to bed are the mating calls of blasted vermin! Please silence those love-sick beasts and help me get some peace and quiet.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 31, 'm8s', 'My gratitude knows no bounds, citizen. Well, actually it does, as your deposited payment will prove. But I''m still quite pleased.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 32, 'm8t', 'Wipe Out Lovesick Beasts'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 33, 'm9d', 'My poor little durni, it wandered away and got lost. The tiny helpless thing can''t see, you know. A friend saw a wild predator pounce on my darling and devour him. Oh horror! Please avenge my poor little Blinky.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 35, 'm9s', 'This sets my mind at ease, citizen. Many thanks. I hope I can mourn Blinky and move on.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 36, 'm9t', 'Avenge Little Blinky'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 37, 'm10d', 'I just knew it was a bad idea to come to this planet! There''s some kind of filthy creature lurking on the path to my new home. I don''t suppose you''d be able to kill it for me, would you?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 39, 'm10s', 'Thank you ever so much! I suppose every planet will seem dangerous after leaving my poor, beautiful Alderaan.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 40, 'm10t', 'Make Planet Safer'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 41, 'm11d', 'I''m looking to run some power conduits across an area not far from here, but there''s a couple of pesky animals getting in the way of my spooling droids. Do you suppose you might take that weapon of yours and exterminate these pests?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 43, 'm11s', 'Thanks, buddy. You earned the credits. It''s getting so you can''t earn a decent living without a blaster these days.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 44, 'm11t', 'Get Rid of Pesky Animals'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 45, 'm12d', 'I was testing my new electrobinoculars when I spotted a few toothy-looking beasts roaming around my land. If you want to earn a few credits, why don''t you haul your weapon out there and take out those nasty creatures?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 47, 'm12s', 'You don''t seem to be bad with that weapon. The credits I promised will be promptly deposited.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 48, 'm12t', 'Toothy Beasts Are Bad'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 49, 'm13d', 'I''ve been tracking some genetically altered predators that were stolen from an Imperial research facility. Some apparently ended up here. If I could get your help in disposing of them, I''d make it worth your while.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 51, 'm13s', 'Hmm, those don''t sound like the beasts I was tracking, but thanks for getting rid of dangerous predators anyway. A little something has been deposited in your account for your trouble.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 52, 'm13t', 'Genetically Altered Beasts Are Scary'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 53, 'm14d', 'My goal of breeding exotic pets didn''t go as planned. I''ve heard some of my "failed experiments" are now terrorizing the locals. Think you could take care of this problem for me?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 55, 'm14s', 'Thanks. Your pay has been deposited. I''d sure appreciate it if you didn''t mention this to anyone, okay?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 56, 'm14t', 'Clean Up Failed Experiments'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 57, 'm15d', 'My friends and I want to hold some speeder races outside of town, but there''s some sort of creature lair out there that''s holding us up. If you wipe it out, I''ll pay you for your time.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 58, 'm15o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 59, 'm15s', 'Thanks! You''re a pal! I deposited your pay. Don''t forget to come back in a few months and check the races out.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 60, 'm15t', 'Speeder Races Are Fun'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 61, 'm16d', 'I lost something of great sentimental value in the wilderness and I''m determined to get it back. I''ve isolated the area where I think this treasure may lie, but there''s a den of predators keeping me from performing a thorough search. Think you can get rid of it for me?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 63, 'm16s', 'Thanks, friend. I''ve compensated you for your trouble. Uh, you didn''t happen to dig around, did you? Didn''t find any precious stones?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 64, 'm16t', 'Recover Family Heirloom'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 65, 'm17d', 'Some kids have disappeared in this area over the last few weeks. Some folk think it''s the work of wild predators. I''ll pay you to check these coordinates out and drive away any monsters you encounter.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 67, 'm17s', 'Good work, citizen. The children will compose a song in your honor. Oh, and I''ve deposited the pay I promised.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 68, 'm17t', 'Children Possibly Eaten'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 69, 'm18d', 'My dying grandfather has one last wish -- to eat the flesh of the creatures that killed his beloved wife. I''ve tracked down a lair of the beasts and need you to kill some for me. Think you could do that?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 71, 'm18s', 'Excellent! I''ll send my droids out to collect the carcasses. Don''t worry if you didn''t leave much meat -- my grandfather has hardly any teeth left.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 72, 'm18t', 'A Last Supper'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 73, 'm19d', 'I perform tests of the groundwater, but my meters seem to attract all manner of vermin. It''s the vibrations, I think. Could you please make sure there aren''t any bothersome beasts hanging around my workstations?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 75, 'm19s', 'Thank you. It''s always nice to know I can go to work in relative safety. I''ve deposited something for you in your account.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 76, 'm19t', 'Assist Public Servant'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 77, 'm20d', 'My mother is sick and loves a certain flower that grows near here. I''d pick some for her, but there''s some sort of creature lair near there, and I''m afraid those beasts might hurt me. Could you chase them away for me?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 79, 'm20s', 'Thank you so much. I''m sure the flowers will help my mother get better. Enjoy the reward for your services.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 80, 'm20t', 'Help Sick Mother'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 81, 'm21d', 'My little daughter''s beloved bearded jax was killed by some sort of wild beast recently. The darling just won''t be consoled until those horrible pests are disposed of. Do you think you could do this for me?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 83, 'm21s', 'Thanks, friend. I hope what I deposited covers your inconvenience. I''m sure you understand just how important it is to keep our little angels happy.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 84, 'm21t', 'Console Little Angel'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 85, 'm22d', 'Ever since my HyperGym broke down, I''ve taken to jogging outside the city. But the presence of wild beasts has recently rendered my favorite route useless. Could you get rid of these pests for me?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 87, 'm22s', 'Thanks, friend. I gave you something to cover the expenses you incurred while blasting those creatures. Now I''ll be able to stay in shape.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 88, 'm22t', 'A Strike For Fitness'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 89, 'm23d', 'The Imperial Zoological Agency claimed to have cleared these areas of dangerous beasts. I beg to differ. We''ve had a few attacks on children in the last couple of days. Could you get rid of whatever is threatening our kids?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 91, 'm23s', 'A thousand thanks, citizen. Perhaps you should seek a job with the Imperial Zoological Agency. Seems like you could show them how these things should be done.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 92, 'm23t', 'Clean Up Empire''s Mess'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 93, 'm24d', 'I''ve heard a lot of complaints about a crazy old wizard in the wilds who surrounds himself with ravenous beasts. I sent a range droid to find out where the old man lives. Now I want you to exterminate his animals. I can pay you, don''t worry about that.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 95, 'm24s', 'Well done. Those animals won''t bother anyone now. The old wizard probably ran away when he saw you coming. I hope that teaches him a lesson.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 96, 'm24t', 'A Crazy Wizard''s Menagerie'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 97, 'm25d', 'Something''s been killing the young from my herd of gualamas. Now I have to keep my livestock indoors. I need a hunter to take care of this predator before I lose any more profits. If you can do the job, I''d love to hire you today.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 99, 'm25s', 'I''m glad nothing will be feeding on my gualamas. Thanks to you, that is.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 100, 'm25t', 'Save Gualama Herd'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 101, 'm26d', 'They looked so cute when they were little, but my pets grew too big to keep. Now they''ve been feral for a year. The planetary authorities have warned me that they''ve become dangerous. I''ve got to get rid of them somehow. Would you be able to find my old pets and blast them into pieces?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 102, 'm26o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 103, 'm26s', 'I still miss those poor little devils. Perhaps now they''re in a better place. Thank you for the help.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 104, 'm26t', 'Good Pets Gone Bad'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 105, 'm27d', 'I''m not obsessed with hokey religions, but I think some land I just bought is strong with the dark side of the Force. At least it''s infested with some very unpleasant animals. You look tough enough to remove them from my property. Care to earn a few credits today?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 106, 'm27o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 107, 'm27s', 'You have much skill and courage. The Force must be strong with you. Enjoy your reward.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 108, 'm27t', 'Face the Dark Side'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 109, 'm28d', 'Cloning tests are fun, but I made the mistake of turning loose several test subjects. Not that these cloned animals can''t defend themselves in the wild. Quite the opposite -- they have mauled several travellers through the area. How would like to help me clean up this mess by blasting these animals into atoms?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 110, 'm28o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 111, 'm28s', 'Thanks. Of course, the thing about clones is that it''s hard to stop making them after just ten or twenty. I may need your services again. Soon.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 112, 'm28t', 'Stop the Clones'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 113, 'm29d', 'Remember the Techno Union? Of course you do. I think there might be an old outpost of theirs not far from here. I want to investigate further, but the area is home to some distinctly hostile creatures. I''d love to hire you to remove them. Then I can get on with my search for the outpost.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 114, 'm29o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 115, 'm29s', 'Capital job! Now I can keep searching for that old Techno Union outpost. Who knows what they might have left behind?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 116, 'm29t', 'Techno Union Treasure'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 117, 'm30d', 'I''ve found an excellent spot to set up an electro-telescope. I like to watch the big ships docking in orbit. But the last time I set up my rig, I was chased off by a couple of ugly, unpleasant creatures. I''ll pay good money if you could get rid of those beasts for me.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 118, 'm30o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 119, 'm30s', 'You''ve done me a great favor. Your payment has been deposited. Now I can monitor the activities of Imperial warships to report to the Alli-- um, I mean, I can watch the big ships docking in orbit.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 120, 'm30t', 'Help Amateur Astronomer'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 121, 'm31d', 'I imported some ghhhks from Clak''dor VII. I heard their skin makes a healing salve. Well, it didn''t do anything for me, and then the ghhhks got loose. Now they''re breeding, and the scent has attracted a pack of hungry predators. I''d like you to destroy the predators before anything really bad happens.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 122, 'm31o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 123, 'm31s', 'Thanks. I was afraid my neighbors were about to sue me for biological infestation. I hope the predators ate all the ghhhks before you killed them.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 124, 'm31t', 'Contain Biological Infestation'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 125, 'm32d', 'I''ve commissioned a holosculptor to model several local beasts for a new dejarik board I''ll be selling. She needs specimens, so I''ve located some at these coordinates. Please dispatch everything in this lair, but try to leave the bodies intact.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 126, 'm32o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 127, 'm32s', 'Never mind. The holosculptor found adequate models on the HoloNet. Thanks anyway for your work, and I have deposited your fee.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 128, 'm32t', 'Improve the Game of Dejarik'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 129, 'm33d', 'Some offworld things escaped from the recent Livestock Exhibition, and they''ve been terrorizing the countryside ever since. We''ve collected some money and found the likeliest spot where they lair. Can you go in and take out the whole pack, quickly?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 130, 'm33o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 131, 'm33s', 'Did the creatures seem like offworld beasts to you? They may still be on the loose. Well, you did the job we asked for, so your money''s been deposited.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 132, 'm33t', 'Hunt Offworld Beasts'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 133, 'm34d', 'You smell that? That stinking dust on the wind? It''s egg seeds, spewed by the shadow barnacles that infest the buildings around here. The egg seeds in turn attract beasts from hither and yon. There''s a new lair nearby. Please go and destroy it, okay?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 134, 'm34o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 135, 'm34s', 'That was some stink, eh? I''d better find a fungicide or something. Everything go okay? Your money should be in your account. '),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 136, 'm34t', 'Stop Stinky Beasts'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 137, 'm35d', 'I''m convinced I know the origin of the vicious pack animals now attacking children in this neighborhood. Some local Imperial bigwig imported them for his stupid menagerie, and they got loose! The police won''t stop the beasts yet, because someone high up likes to make the Empire look bad. Can you destroy this menace?'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 138, 'm35o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 139, 'm35s', 'What a relief! All the parents in this neighborhood thank you. You''ve done us a great service and earned this reward.'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 140, 'm35t', 'Stomp Rogue Zoo Animals'),
('string/en/mission/mission_destroy_neutral_easy_creature_non_persistent_from_npc.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 1, 'm1d', 'When I was a kid, I''d go out into the desert and squash ''em personally, but I''m getting too old for that type of nonsense. I want you to handle this for me.  These vermin are everywhere and are causing me trouble. It was easy enough to kill them forty years ago. I''m sure not much has changed...'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 3, 'm1s', 'Hope you had fun crushing those pests! Thanks for taking care of that, so I didn''t need to.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 4, 'm1t', 'Squash ''Em!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 5, 'm2d', 'I am an artist well known for my striking landscapes, but I do not see how I can be expected to paint serene, desert scenes lit by glowing twin sunsets if there are unsightly vermin in the way. Can anyone get rid of these horrible nests so I can resume my life''s work? '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 7, 'm2s', 'By the twin suns of Tatooine, I owe you everything! My career as an artist was stalling, until you rid the area of the ugly creatures disrupting my sensitive artistic sensibilities. I''m on the verge of painting the definitive Tatooine landscape, which I will dedicate to your efforts!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 8, 'm2t', 'Artist''s Plea'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 9, 'm3d', 'According to recent studies, the burrowing activities of several varieties of small verminous creatures may actually destabilize the water leaching patterns in the local aquifer. Given the criticality of this basic ecological mechanism to our Tatooine economy, a group of local businesspeople has pooled funds in order to offer a reward for the removal of any burrows, nests, mounds, heaps, or lairs that might contribute to the slow alkalinization that has been devastating our microcryptoaquazoology. The only caveat is that the destruction must be accomplished in an ecologically safe manner, not through poisons that might further damage the mineral substrates.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 10, 'm3o', 'Tatooine Business Bureau'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 11, 'm3s', 'We, the representatives of the Tatooine Business Bureau, extend our most heartfelt congratulations on a mission well-done! As noted in our original transmission, local economic health was threatened by the burrowing creatures disrupting our key aquifier. As a result of your incredible heroics, the ecological impact of these creatures has been significantly reduced. We hope that you appreciate our praise, but realize that financial gain may be more gratifying. We will transfer your payment immediately and look forward to working with you again in the future.\n\nYour Grateful Employer,\nThe Tatooine Business Bureau  '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 12, 'm3t', 'Burrowing Creature Dilemma'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 13, 'm4d', 'Disease-carrying pests have infested the desert between many of Tatooine''s major settlements. We need someone to remove these creatures, but be careful: One caravaner has already died from an infected bite!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 15, 'm4s', 'Our caravan was overwhelmed with relief when we heard that you had destroyed the disease-carrying vermin roaming the area. Thank you for being an unyielding hero in these desperate times. I promise that our children will always hear the story of how you saved us from certain death, even when faced with death yourself.  '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 16, 'm4t', 'Beware of Diseased Animals!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 17, 'm5d', 'The local wildlife in this area is causing problems with the ecology. There is an overabundance of the specified creatures, which is causing plant life populations to drop dramatically.  This situation must be dealt with immediately.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 18, 'm5o', 'Tatooine Scientific Union'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 19, 'm5s', 'The Tatooine Scientific Union has been informed of your successful attempts to reduce the exccessive populations of problem creatures in the area. We believe that your efforts will improve the ecological health of the planet. '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 20, 'm5t', 'Ecological Disaster!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 21, 'm6d', 'Recently, patients suffering from small bites or scratches have been seen by local medics. In at least two cases, the wounds have become infected with a strain of bacteria highly resistant to common medical approaches, including bacta. While the risk to individual patients from the actual bites is not severe, there is concern that the bacteria themselves might migrate to other hosts and cause much more severe problems. The medical professionals who have evaluated the threat recommend that the original host population be exterminated. '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 22, 'm6o', 'Bestine Hospital Medical Chief'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 23, 'm6s', 'The Bestine Hospital would like to thank you for eliminating local creatures that we believe were carrying potentially dangerous bacteria. We have already recorded a marked decrease in the number of infected bites and scratches. We have transferred payment for services rendered.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 24, 'm6t', 'Medical Alert'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 25, 'm7d', 'Ever since it became fashionable to hunt Tatooine''s larger predators, the vermin population has been breeding out of control. I''m not one to defend dangerous beasts, but they did eat the smaller pests. All I''m asking is that the hunters focus on vermin as well as the big prizes. Since all the high-profile adventurers are busy chasing krayts, I''m hoping that you can hunt some of the more populous creatures. I''ve located a lair that would be a good place to start.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 27, 'm7s', 'Congratulations on elminating that vermin lair. I plan to tell all my neighbors about your willingness to step in and help out when all the "real" hunters were off chasing dragon tails. '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 28, 'm7t', 'Hunter''s Quest'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 29, 'm8d', 'Landspeeder accidents are up 8% this season, largely due to the presence of non-sentient animals alongside central travel routes. These creatures periodically dart in front of oncoming vehicles, causing operators to lose control and crash. The Bestine Transportation Safety Commission, in conjunction with Imperial Prefect Talmont, is hiring contract exterminators to help keep our landspeeder lanes safe. Please report to the identified lair and eliminate it in order to help with this endeavor. '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 30, 'm8o', 'Bestine Transportation Safety Commission'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 31, 'm8s', 'The Bestine Transportation Safety Commission and Imperial Prefect Talmont have been notified of your successful attempts to improve landspeeder safety on Tatooine. We are pleased to inform you that, in light of your recent success, we will be forwarding the appropriate payment to your account. Thank you and have a safe day.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 32, 'm8t', 'Vehicular Vermin '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 33, 'm9d', 'We''re not sure if it is the vibrations or the material components, but something about our moisture vaporizers is attracting small but destructive beasts. This is especially true with the older units. We''ve finally put it to a vote and decided that the union should offer a reward to exterminators who deal with some of the most suspect nests. We''ve assigned such a lair to you; you''ll find it nearby. Good luck!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 34, 'm9o', 'Moisture Farmers of Tatooine #253'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 35, 'm9s', 'Moisture farmers across Tatooine thank you for your efforts to protect our moisture vaporators! In accordance with our union bylaws, we have transferred your reward directly into your galactic account.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 36, 'm9t', 'Union Dues'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 37, 'm10d', 'The Illustrious Jabba the Hutt, Tatooine''s first and finest citizen, is troubled by reports of vermin running rampant across Tatooine''s pristine deserts. These creatures offend the Magnanimous Jabba''s refined sensibilities and threaten to overrun Tatooine''s humble citizens. As a sign of his generosity, the Benevolent Jabba is offering a reward to brave adventurers willing to eradicate this terrible scourge.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 38, 'm10o', 'Bib Fortuna, on behalf of Jabba the Hutt'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 39, 'm10s', 'The Philanthopric Jabba the Hutt is overjoyed at your recent successes in the field of vermin extermination. Enjoy your reward. I recommend spending it at the Mos Eisley cantina.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 40, 'm10t', 'Kill all Vermin!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 41, 'm11d', 'Fixer would absolutely kill me if he knew I was hiring you for this job, so keep it between us, okay? I need you to help me keep Fixer out of trouble; if anything happened to him, the Tosche power station would go under, and I''d be left all alone on this dustbowl... Here''s the situation: The Empire has decided that all of us Tatooine locals need to do our part to keep our planet clean and safe (like that''s ever going to happen...). Prefect Talmont has demanded that each city appoint an exterminator responsible for hunting down and killing vermin. I guess the Imperials have gotten tired of tromping around the desert, so they''re making us do their grunt work. Anyway, long story short (too late!): Anchorhead has nominated Fixer for this job, and I can''t bear the thought of him out there in the desert on his own. He may be a bad-mannered, bald Wookiee, but he''s my bad-mannered, bald Wookiee, and I''m planning to keep him by my side as long as possible. If you take care of these creatures instead, he''ll be out of danger... at least for a little while longer.  I don''t want him out there getting hurt!\n\n-Camie'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 42, 'm11o', 'Camie'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 43, 'm11s', 'Thank you for keeping Fixer out of trouble. Fixer likes to pretend he''s pretty tough, but those creatures would have absolutely murdered him. I''ve liberated some credits from the power station''s safe and transferred them to your account. Just remember to keep quiet about this mission.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 44, 'm11t', 'Fixer''s Guardian Angel'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 45, 'm12d', 'There are few joys out here in the desert, but one of my small pleasures is picking mushrooms from the moisture vaporators on my land. I know that the mushrooms are small and ugly, and they taste terrible, but sometimes they''re all we have to eat out here... Lately, though, something nasty has been eating the mushrooms before I can get to them. So, if you could try to stop the creatures eating my mushrooms, it would be your good deed for this season.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 47, 'm12s', 'I am so fortunate that you decided to help destroy the mushroom bandits that have been stealing part of my daily diet. Now that I have my mushrooms back, I only suffer moderate hunger pangs every night. We''re still going hungry out here, but at least we have something to nibble on each night.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 48, 'm12t', 'Mushroom Thieves'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 49, 'm13d', 'Message Composed by K8-LR, Protocol Droid, on Behalf of Gartogg the Sturdy\n\nIt is my unfortunate duty to translate the disgusting grunts of Gartogg, a Gamorrean of exceptionally low intelligence. I don''t know why Jabba endures such mindless guards... It''s bad enough that I have to listen to their squealing screams every time one of them accidentally falls into the rancor pit, but now I''m being programmed to actually talk to these brutes! And all Gartogg does is complain. First, he complains bitterly about being forced to haul garbage, but really, he doesn''t have the intellect for anything else. Then, he complains about the creatures that run amok at the garbage pits! He claims to hate the animals. Recently, he spotted what he assumes to be their lair. Now, it would give him no end of pleasure to know that someone has killed all of the creatures on his behalf. He keeps shouting "Smash little creatures!" as he runs through the palace corridors. So, please, I implore you, find and smash these animals. Hopefully, Gartogg will then stop his incessant whining.\n'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 50, 'm13o', 'Gartogg'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 51, 'm13s', 'Gartogg the Sturdy was very happy to learn that you had "smashed" the little creatures he hates so thoroughly. When he heard my report, he clapped his meaty hands and squealed with joy. Thankfully, he has also stopped complaining about the animals, at least for now. So, it is with great relief that I transfer a sizable reward to your account. Gartogg thanks you, and I most humbly thank you as well.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 52, 'm13t', 'Smash Little Creatures!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 53, 'm14d', 'Tatooine''s vermin are well-known for their ability to spread diseases, mutating viral infections, and lethal bacteria. Recent reports suggest that a local creature community is infected with an as-yet-unidentified disease. These reports are unsubstantiated, but previous outbreaks have made us extremely cautious. Destroy the potentially-infected lair as soon as possible to prevent any unnecessary deaths.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 54, 'm14o', 'Prefect Talmont'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 55, 'm14s', 'Good citizen, I am happy to report that efforts to reduce the number of plague-bearing vermin in the area have been successful. While the Empire will publicly take full responsibility for the elimination of these pests, we will be paying your consulting fee, as agreed. Long live the Emperor.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 56, 'm14t', 'Plague Prevention'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 57, 'm15d', 'Hello. Please excuse the quality of this message. We don''t have much use for datapads out here. Not even sure if I know how to send this transmission... But, if you''re reading this, then I suppose I did something right. Let me get to the point. We all have work to do.\n\nEvery season, the sandstorms kick up. They usually chase at least a few dozen animals onto my land. I''m taking precautions this year. I spotted some creatures near my farm. No doubt they''ll be heading for my garage once the sandstorms start. Unless you destroy them first. I have some credits buried under a vaporator. I''ll pay you to take care of this for me. Good luck.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 59, 'm15s', 'Hello again. I wish to thank you for wiping out the creatures near my homestead. I''ve dug up my credits and will transfer them to your account soon.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 60, 'm15t', 'Sandstorm Migrations'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 61, 'm16d', 'There are so many things to complain about on Tatooine, I never thought I''d be whining about the way the planet smells. But the stench around here is just terrible. It''s making all of us nauseous. On the hottest day, the smell is so bad you can''t go outside without a breathing mask. For the first few days, we thought it was the garbage pile rotting, but we buried the refuse and the smell still lingered. So, a few of us tracked the source to an animal lair nearby. The creatures are wallowing in their own waste. It''s disgusting, and we''re living downwind. If you can destroy that lair, we''ll all breathe a lot easier.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 63, 'm16s', 'Thank the Force! You''ve wiped out the source of that terrible stench. Now, we can all breathe comfortably again. Our meager credits will never convey how much we appreciate your help.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 64, 'm16t', 'Stop the Stench!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 65, 'm17d', 'Transmission Translated from Jawaese for you convenience!\n\nOur precious hubba gourds, the Staff of Life, are under attack by raving creatures! We Jawas keep to sandcrawlers mostly. We are ill equipped to stop this assault on our foodstuffs! We Jawas will give big credits to anyone who will help us!\n\nWimateeka, Jawa Clan Leader'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 66, 'm17l', 'Jawas are in danger of starving!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 67, 'm17o', 'Wimateeka'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 68, 'm17s', 'Transmission Translated from Jawaese for you convenience!\n\nMost exalted hero of the Jawas! Thank you a hundred times for saving the precious hubba gourds, the Staff of Life, from thieving, dirty creatures. We will now pay you a sizable, big reward.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 69, 'm17t', 'Hubba Gourd Raiders'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 70, 'm18d', 'The Galactic Pest Authority has documented a significant increase in reported encounters with recognized disease-carrying pests on Tatooine. To protect the public health, destroy the identified lair. '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 71, 'm18o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 72, 'm18s', 'We''ve recently collected data that suggests a dramatic decrese in the number of recognized disease-carrying pests on Tatooine. We at the Galactic Pest Authority attribute that sudden decline to your efforts. Your activities on behalf of the good citizens of Tatooine will be handsomely rewarded.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 73, 'm18t', 'Tatooine Pest Control'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 74, 'm19d', 'The Galactic Pest Authority is disappointed to report a sharp rise in the number of problem animals reported on Tatooine. These so-called "nuisance creatures" damage moisture vaporators, steal delicate pallies and other foodstuffs, and harass honest moisture farmers. For the good of all, the lair of these recognized nuisance creatures must be eliminated.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 75, 'm19o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 76, 'm19s', 'The Galactic Pest Authority has collected substantial data suggesting a dramatic decrese in the number of reported nuisance creatures on Tatooine. The organization attributes this sudden decline to your efforts. Your activities on behalf of the good citizens of Tatooine will be handsomely rewarded.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 77, 'm19t', 'Nuisance Creature Control'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 78, 'm20d', 'The Galactic Pest Authority is paying operatives to conduct routine creature culling on Tatooine. This is a common practice on a number of worlds, used to control the spread of problem creatures. A "problem creature" might be defined as predatory, disease-bearing, invasive, or prone to violence. To aid in this specific creature culling, destroy the identified Tatooine lair.  '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 79, 'm20o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 80, 'm20s', 'The Galactic Pest Authority is pleased to report that this season''s culling expedition to the desert planet of Tatooine has been a monumental success. All agents assigned to this incredible endeavor will receive payment directly.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 81, 'm20t', 'Tatooine Creature Culling'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 82, 'm21d', 'First off, let''s keep this between you and me. I''m not proud about any of this... But I''m in some trouble. Financial trouble, which is the worst kind of trouble, right? A few months ago, I was in deep with the Hutt and trying to drum up some business. My brother-in-law came up with this crazy plan to give huge discounts to any client who could kill a "dangerous" creature with one of my weapons. The problem is, we never defined which animals were "dangerous." Heck, an eopie is "dangerous" if it catches you off-guard. Anyway, the gimmick brought people into the store to buy blasters and ammunition, and having so many would-be marksmen running around with my merchandise seemed like free advertising. But, like a dim-witted Dug, I promised to run this stupid promotion for five full seasons! Well, now my storehouse is full of stuffed animals, everything from little scurriers to disease-ridden rontos, and I''ve been practically giving away my merchandise. I''ll be out of business soon...\n\nSo, here''s my new scheme: I''d rather pay you to wipe out all the easy targets before my over-eager clientele find these helpless creatures and I''m left selling them Corellian blasters at Lok-bottom prices. '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 83, 'm21o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 84, 'm21s', 'I can''t believe it! Just when the bottom was about to drop out of my business, you''ve saved me. My customers have stopped demanding "rewards" for every dead scurrier, but they''re still coming into the store. Turns out, they just like the merchandise. Anyway, I''ve finally scraped together enough to pay back the Hutt, with a little left over to offer you as a reward. Thanks again for making sure my business survives another season.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 85, 'm21t', 'Even the Odds'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 86, 'm22d', 'My crops are gettin'' chewed all up. Hard enough to grow anything on this sandy rock, and now somethin'' is eatin'' everything green that dares to show its leaves. I''m needin'' someone to take care of whatever it is that''s wipin'' out my crops.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 87, 'm22o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 88, 'm22s', 'I need to be thankin'' you for savin'' my crops. I was convinced that I was going to end up starving to death, or owin'' my life to Jabba the Hutt. But now that you''ve chased off those leaf-eatin'' creatures, my crops are growin'' faster than ever before. I''ve sold a few barrels of pallies in order to put together your reward.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 89, 'm22t', 'Crops in Danger'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 90, 'm23d', 'We lost power to our moisture harvesting facilities recently. Looks like something was chewing through the power cables. Can anyone try to exterminate whatever might be responsible?'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 91, 'm23o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 92, 'm23s', 'Our moisture vaporators are running smoothly and our facilities have never been  more productive. We''re now shipping water to all parts of Tatooine, and have become the primary supplier for Bestine. We''re extremely grateful for your efforts on our behalf.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 93, 'm23t', 'Harvesters Offline'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 94, 'm24d', 'TRANSMISSION TRANSLATED FROM HUTTESE\n\nAs you probably know by now, Watto the Toydarian, owner of the once-legendary Watto''s Junkshop and Spare Parts in Mos Espa, has fallen on hard times. Ever since he lost his fortune betting against a Jedi in the Boonta Eve Podraces, Watto has been deep in debt with just about everyone on Tatooine, including Jabba the Hutt.\n\nI''ve known Watto all my life and I''m trying to help him out. He''s not the friendliest gasgut, but he''s practically an institution in Mos Espa. And maybe I feel a little responsible for Watto''s plight, since it was my friend Anakin who won the Boonta Eve that year and left Watto without a credit to his name. Or maybe I''m just hoping that Watto will eventually give me the junkshop...\n\nWhen I heard that the Imperials were offering rewards to adventurers willing to kill some of the local vermin, I figured we could earn some quick credits by taking out overbreeding eopies. But Watto always wants to be the middle-man. He''s identified some of the easiest targets the Imperials have to offer and has personally guaranteed that the creatures in question will be exterminated. Now, he just needs to hire adventurers like you to kill the beasts. We''ll pay you the reward, after Watto takes his "commission" of course. It''s not a perfect set-up, but I can guarantee that Watto has selected only the best assignments. And, by dealing with Watto directly, you avoid any Imperial entanglements...  '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 95, 'm24l', 'Watto the Toydarian is hiring sub-contractors to complete Imperial missions.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 96, 'm24o', 'Wald'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 97, 'm24s', 'TRANSMISSION TRANSLATED FROM HUTTESE\n\nThings don''t look so grim around Watto''s shop these days. Surprisingly, his sub-contracting scheme seems to be working, thanks in part to you. Even after paying you your reward, Watto has enough left over to upgrade his inventory and attract new customers. And, because he''s proven to be so reliable, Watto is gaining quite a reputation with the Imperials. They''re even starting to buy parts from the junkshop.\n\nAs one of Watto''s sub-contractors, you''ve been paid for your services. Please note that, while Watto did deduct his standard commission, I threw in a few credits of my own to thank you for a job well done.\n'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 98, 'm24t', 'The Middleman'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 99, 'm25d', 'The Tatooine Reclamation Society is a coalition that includes Bestine, Mos Espa, and several other major cities on Tatooine that have joined forces with generous Imperial forces to improve life on our desert planet. As part of the Tatooine Reclamation Project, the Tatooine Reclamation Society is planning to construct waystations between the planet''s primary settlements. Unfortunately, the proposed sites of some planned waystations have already been "settled" by native Tatooine creatures. The Tatooine Reclamation Society does not take issue with the creatures themselves, but their lairs could potentially block construction of a waystation. The Tatooine Reclamation Society is broadcasting the coordinates of these problem lairs in the hopes that loyal Tatooine citizens will take it upon themselves to aid the Reclamation Project by destroying these obstacles. A suitable reward will be offered to anyone to helps in our efforts to develop these essential waystations.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 100, 'm25o', 'Tatooine Reclamation Society'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 101, 'm25s', 'The Tatooine Reclamation Society is pleased to report that Phase I of our proposed waystation project is nearly complete! Lairs blocking construction on these proposed waystations have been eliminated. Those citizens directly responsible for the destruction of these lairs have been rewarded and deserve the thanks of the entire planet!\n\nPhase II of the project - the actual construction of the waystations themselves - requires additional funding. We have been promised a substantial grant from the local Imperial prefect, but a recent military mishap near Yavin IV has evidently diverted all Imperial credits for the forseeable future. The Tatooine Reclamation Society is seeking other backers, including the generous Jabba the Hutt. We believe that the waystation project will be back on track within a few seasons! '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 102, 'm25t', 'Reclamation Project'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 103, 'm26d', 'The Illustrious Jabba the Hutt is expecting a visit from several prominent and influential Huttese "dignitaries," arriving shortly from Nal Hutta. The Hospitable Jabba has vowed that his most-respected associates will find Tatooine to their liking. However, the Transcendent Jabba is concerned that the arriving dignitaries will be offended by the number of disgusting vermin running rampant on Tatooine. Such beasts will surely mar any scenic trips to the Great Pit of Carkoon. In order to prepare for the arrival of his revered guests, the Wise Jabba is hiring mercenaries to rid the desert of unsightly vermin. Go and seek out the described lair. Do not fail his Sluggishness! '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 104, 'm26o', 'Bib Fortuna, on behalf of Jabba the Hutt'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 105, 'm26s', 'A most Festive Jabba the Hutt is celebrating your successful elimination of local vermin. He plans to take a tour of the desert soon to observe your handiwork first-hand. As instructed by the Mighty Jabba the Hutt, I have personally transferred a sizable reward to your account. The Entrepreneurial Jabba suggests that you spend your hard-earned credits at any of Mos Eisley''s respectable businesses, most of which owe their current success to the Hutt''s incredible influence.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 106, 'm26t', 'Imminent Arrival');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 107, 'm27d', 'Lately, I''ve been seeing Tusken Raiders around here, hunting some of the smaller, less dangerous creatures in the area. I''m assuming the Sand People are eating these animals... They say a hungry Tusken is desperate and dangerous, but a Tusken with a full belly becomes strong and brave. And if he''s not thinking about hunting food, a Tusken has too much to think about maybe hunting us. I need your help to keep these Sand People hungry. Maybe so hungry they decide to look for new hunting grounds. The way I see it, all you need to do is go out and kill some of the creatures that the Tuskens are eating. That should drive them away. I''ve given you the coordinates for a lair that the Tuskens might have their goggles on. Go destroy it and I''ll pay you what I can.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 108, 'm27o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 109, 'm27s', 'A job well done, friend. By eliminating that lair, you''ve hopefully sent the Sand People packing. Let them go hunt out by Jabba''s Palace or the Great Pit of Carkoon if they''re hungry.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 110, 'm27t', 'The Hunted'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 111, 'm28d', 'The big-time hunters who spend all their time bagging giant beasts on Lok or Naboo might not think that the animals out here are dangerous, but let me tell you, everything is tougher that it looks out in the desert. If I had a credit for every poor moisture farmer trampled to death by rogue eopies or feral banthas, I''d be able to buy myself a new landspeeder. And I can''t tell you how many times we''ve buried a friend who was chewed up and spat out by squills or womp rats. I don''t care what off-worlders say, the animals out here are dangerous and we need brave adventurers like you to take care of them before anyone else gets killed. The best way to wipe out these beasts is by destroying their lair. I''ve done the footwork and found one for you; just go take care of it and you''ll get paid in real, honest credits.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 112, 'm28o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 113, 'm28s', 'It''s a hard life out here, but hopefully you''ve just made things a bit easier for those of us forced to live in the desert. Thanks for killing those creatures before they could kill one of us.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 114, 'm28t', 'Minor Threat'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 115, 'm29d', 'The Galactic Pest Authority is responsible for monitoring reports of vermin, pests, and nuisance creatures throughout the galaxy. We have conclusive evidence of a dangerous rise in the number of vermin on Tatooine. In accordance with Galactic Pest Authority''s mission statement, we are authorizing extermination of these vermin. This transmission includes information about a specific vermin lair; please destroy this lair and keep our galaxy clean!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 116, 'm29o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 117, 'm29s', 'Congratulations! You''ve successfully destroyed one of Tatooine''s most tenacious vermin lairs. The Galactic Pest Authority has been authorized to provide you with a suitable reward for your efforts on behalf of the galaxy.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 118, 'm29t', 'Vermin Control'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 119, 'm30d', 'I need a professional to eliminate some vermin that have been spooking my eopies. I think I''ve located the source of the trouble. Should be an easy extermination job.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 120, 'm30o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 121, 'm30s', 'Excellent work, my friend. You''ve chased off the vermin scaring my eopies. They''ve finally settled down. Life is almost back to normal on this rock.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 122, 'm30t', 'Livestock Spooked'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 123, 'm31d', 'It may surprise you to learn that I was born on Coruscant, right in the heart of the galaxy. I grew up surrounded by constant noise, which just about drove me insane. When I had the chance to relocate to someplace quieter, I took it. Now, I know that Tatooine isn''t everyone''s idea of paradise, but it is quiet. Or, at least it was quiet until the local creatures began screeching and bellowing. The problem with living in the desert is that sound carries for kilometers. With those creatures out there making such a racket, I can''t sleep or concentrate. I think I might be going mad. I need someone to silence them, for good.   '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 124, 'm31o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 125, 'm31s', 'As soon as you destroyed that lair, a calm came over me. The desert seemed awash in beautiful, soothing silence. I don''t know quite how to thank you, but I hope you''ll take a few credits for all your hard work on my behalf.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 126, 'm31t', 'Desert Din'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 127, 'm32d', 'We, the Dim-U monks of Tatooine, who worship at the hairy feet of the Mighty Bantha, are seeking defenders of our hirsute idol. While Tatooine should be the domain of the bantha alone, the Horned-One must share the planet with a host of lesser beings. Many of these beasts make life difficult for the Revered Bantha, most divine of all creatures! They badger the Wandering Bantha, or infect Him with disease, or steal His food or water. The coffers of the Dim-U monastery are full, ready to serve the cause of the Enduring Bantha, in whose eyes all Universal Truths are revealed. We only await a champion to step forward and purge the Stalwart Bantha''s enemies!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 128, 'm32o', 'Dim-U Monks of Tatooine'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 129, 'm32s', 'The Mighty Bantha, the legendary Horned-One who brings peace and tranquility to all who gaze upon Him, is safe once again! You have served the Enduring Bantha well! The Dim-U monks, loyal servants of the Wandering Bantha, are overjoyed at your success. Our coffers have been opened and you will be rewarded. The Dim-U monastery thanks you on behalf of the Horned-One, whose powerful bellow will roar your name across the desert and throughout the start so that all who worship at His hairy feet will know of your heroic deeds.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 130, 'm32t', 'Bantha Defense'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 131, 'm33d', 'They say that nothing can survive in the desert on Tatooine. Well, that''s a straight lie. There are creatures hiding under every rock and thorn bush all across the desert. You can''t take five steps without some hungry, disease-ridden pest lurching out of the underbrush to snap at your toes. I''m sick of it. I''m sick of this whole, sandy planet, but most of all, I''m sick of the vermin. Go out there and kill something for me, make life a little more bearable out here, and I''ll pay you for your troubles.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 132, 'm33o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 133, 'm33s', 'Good work, friend. You did a great job wiping out those small-brained, ankle-biting vermin. After transferring your reward to your account, though, I realized that I''m wasting my money. I could spend millions of credits trying to better my life on Tatooine, and the desert is still going to be overrun by nasty creatures. So, I took the rest of my credits and placed a bet on some demolition contest Jabba the Hutt was holding. Threw all my money behind that Jawa warlord, Wittin, and wouldn''t you know that the little mercenary came through? He trashed the competition, and I won big. With my winnings, I''ve purchased a ticket out of Mos Eisley for Naboo. I''m going to live on a peaceful hillside somewhere, far away from Tatooine''s ankle-biting vermin. Enjoy your reward, but don''t expect to hear from me again.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 134, 'm33t', 'Desert Demolition'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 135, 'm34d', 'If the Force is with us, my little girl is only going to get married once. There aren''t many good men around these parts - good, hard-working, honest men that can make a living out of moisture farming - but she''s found one of the best. We don''t have many credits to put towards the celebration, but I''m planning to make this a wedding even the Darklighters will remember. The ceremony will take place as the suns set, in the most pristine patch of desert I could find. The only problem with the site is a small vermin lair. I''d go take care of it myself, but I have a wedding to help plan and pay for. If you could eliminate the lair, I''d appreciate it. My daughter''s happiness depends on it.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 136, 'm34o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 137, 'm34s', 'Thank you for helping me prepare for my daughter''s wedding. I plan to take her out to the site in a few days. I know she''s going to be overjoyed with the scenic view. I''ve paid a fortune for a wagon full of chuba pies and imported Corellian ale, but there''s a little left over for you. My daughter''s smile is worth every credit.'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 138, 'm34t', 'Wedding Planner'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 139, 'm35d', 'I''m young, but I''m not stupid. I know that it''s going to be tough to leave Tatooine. I dream of someday joining the Academy, but just dreaming about something doesn''t make it happen. So I spend every afternoon practicing my piloting skills in a beat-up skyhopper. I need alll those hours in the cockpit just to hone my skills. If I miss even a day, I lose my edge. But lately, my father has been asking me to spend more and more time out in the desert, patrolling the edge of our property looking for vermin that might bust up our moisture vaporators. Or I waste my afternoons repairing the stupid machines after the animals have bent the chilling panels trying to steal our water. So, here''s my plan: I''ve saved a few credits and I''m willing to pay you to do my work for me. While you''re destroying the nearest lair, I''ll be racing through Beggar''s Canyon. Someday, all this practice will pay off and I''ll be one of the Empire''s finest pilots.   '),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 140, 'm35o', ''),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 141, 'm35s', 'Thanks for helping me out. Since you agreed to help out, I''ve been able to spend even more time practicing in my skyhopper. The investment has been well worth it. In fact, I just snuck over to Bestine and applied to the Academy again. I took a flight test and, if I don''t say so myself, I flew rings around the training drones. I think this time I finally caught the eye of the Imperial recruiter. I have a feeling I''m going to be spending the rest of my life shooting down enemies of the Empire!'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 142, 'm35t', 'Farmboy Dreams'),
('string/en/mission/mission_destroy_neutral_easy_creature_tatooine.stf', 143, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 1, 'm1d', 'Some local thugs have been harassing the decent people of this neighborhood. They loiter around this abandoned shop and get high on glitterstim. We''re offering a reward to any citizen with the guts to go in there and blast this shop to pieces. That would certainly get the point across, eh? Most of these thugs are bullies and cowards anyway, so we doubt they''d give you much trouble. Do you accept?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 2, 'm1o', 'A Group of Concerned Citizens'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 3, 'm1s', 'Told you those creeps wouldn''t put up much of a fight. Bet they don''t come around here no more. The reward is yours.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 4, 'm1t', 'Run off the thugs'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 5, 'm2d', 'Some local glitterstim pusher and a group of thugs has set up shop in our neighborhood and we want them out. We know where they hang out and need someone to go in there and redecorate the place (preferably with blasters). There''s a decent reward in it for the brave individual that succeeds in driving those slugs away. Will you be our neighborhood''s saviour? '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 6, 'm2o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 7, 'm2s', 'That''s showing those poison-pushers who''s boss. Good work, citizen. The Empire could use more upstanding folk like you.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 8, 'm2t', 'Stop the drug dealers'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 9, 'm3d', 'There''s been an increase in break-ins around here recently. We know who''s behind it but we can''t collect enough evidence to get the local authorities to make arrests. It''s time we took the law into our own hands. We''re offering a reward to anyone who can run the criminals behind those thefts out of town. Blasting their hideout to atoms ought to get the point across. If you decide to help us out, we''ll send you the coorindates to this wretched hive of scum and villainy.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 10, 'm3o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 11, 'm3s', 'We sleep easier at night now. Good job, citizen. Hope you decide to work for us again.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 12, 'm3t', 'Stop the thieves'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 13, 'm4d', 'A bunch of slimy slugs have moved into the neighborhood and have been harassing our wives and daughters. We''ve heard of these guys. They were run out of another town after they assaulted a young woman. We feel these predators will repeat that pattern soon, especially since many of our fairer family members work late at the factories. We need some of integrity and of true grit to make sure these criminals don''t endanger anyone. We know where these creeps have set up shop and are certain they would vacate the premises if their lair were blasted to pieces. Can you help us? There''s a reward in the offering.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 14, 'm4o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 15, 'm4s', 'Well struck, citizen! Our womenfolk thank you as do we. Enjoy the reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 16, 'm4t', 'Get rid of slimy predators'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 17, 'm5d', 'A shyster has been cheating some older retired folks out of their life savings. This creep goes around selling bogus cruises on luxury starliners that don''t exist. Further, this slimeball has hired some local toughs, thinking that their presence will scare away any citizens seeking to get their money back. It''s time we put a stop to this activity. We''re offering a reward to the brave and honest individual who blasts this scum''s headquarters to pieces and makes sure they don''t plague another town ever again. If you decide that individual is you, let us know and we''ll send you the coordinates to the creep''s lair.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 18, 'm5o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 19, 'm5s', 'Good work! No one has the right to cheat decent folk out of their life savings. You''ve made sure that point was made, citizen.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 20, 'm5t', 'Smash the shyster'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 21, 'm6d', 'The same brutish thug has mugged half a dozen decent people in the last month, one of which died last night as a result of the injuries. That person was my father. I''d prefer to handle this animal on my own terms rather than get the local authorities involved. I''ll pay a substantial reward to any citizen brave enough to help me get justice for my dead father. Slime like this want us to believe that life in the universe is cheap. Well I''ve got news for that slug - life is not cheap and the price of a life is a life. I hope you can help my father''s soul find peace. The coordinates to this predator''s lair await your acceptance of this mission.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 22, 'm6o', 'An Enraged Daughter'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 23, 'm6s', 'Finally, my father''s soul can rest. Thank you, citizen. Take the reward, you''ve earned it.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 24, 'm6t', 'Stop the murderous mugger'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 25, 'm7d', 'Have you ever heard of the Vibrodagger Killer? We think we''ve finally tracked this heinous murderer down. They''re hiding in a small abandoned settlement near here. We believe there may be other murderers hiding there with the killer. The time for justice is at hand. We need someone to go in there and wipe that place out. Burn it and everyone in it to the ground. Those filthy murderers deserve nothing better. A reward awaits the successful agent of justice. Are you that agent?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 26, 'm7o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 27, 'm7s', 'That should put an end to these horrible crimes. Assuming it was the actual Vibrodagger Killer in that settlement, that is. You''ve earned your reward in any case.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 28, 'm7t', 'Stop the Vibrodagger Killer'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 29, 'm8d', 'A gang of hooligans has been terrorizing our neighborhood for months now. Their favorite tactic is to hurl homemade firebombs at passing speeders. So far three people have been killed by these attacks. The local authorities are already swamped with work and can''t devote the time necessary to stop these criminals. We need an independent agent to take up the cause of justice for us. We''re offering a decent reward to anyone that blasts this gang''s hangout to pieces. If the gang members get caught in the blast, so much the better. You willing to help clean up our community, citizen?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 30, 'm8o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 31, 'm8s', 'Looks like you gave those thugs a taste of their own medicine. Good job! Our neighborhoods could use more folks like you.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 32, 'm8t', 'Drive out the destructive gang'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 33, 'm9d', 'There''s a gang of space trash that has decided to set up a protection racket in our area. Many of the local merchants have been forced to pay protection money after one shop was blown to pieces with the shop owner and his family still inside. The gang is paying bribes to the local law enforcement authorities so they ignore these criminal activities. We need someone to pay like with like and blow the gang''s hideout to atoms. This agent of justice will be rewarded for their time and efforts, of course. The coordinates await your acceptance.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 34, 'm9o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 35, 'm9s', 'We guess the gang forgot to pay their own protection money. Hehehe! Good work, citizen. The money is yours.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 36, 'm9t', 'Stop protection racket thugs'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 37, 'm10d', 'A local glitterstim dealer got my son addicted to that poison and now my boy is rotting in an Imperial prison while the dealer continues to pedal their filth. It''s time someone put a stop to this criminal''s activities. I''m offering a reward to any citizen that goes into that dealer''s lair and blasts everything in sight. If the dealer and their thug friends are there, blast them too. If you accept, I''ll transmit the coordinates to the dealer''s hangout. That nest of silica parasites needs to be cleaned out.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 38, 'm10o', 'An Angry Father'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 39, 'm10s', 'You''re an effective agent of justice, citizen. You''ve made the streets safer for our youth. This is one reward I am happy to pay.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 40, 'm10t', 'Stop glitterstim dealer'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 41, 'm11d', 'My cousin was taken from me by a vicious gang of cutthroats operating in the area. I want someone to attack their hangout and blast every single one of those murderers to bits. Leave nothing standing. This gang''s attacks have claimed many lives and shattered many families. Please help me find justice. I will reward you for your time. And our community will thank you for your service. Will you help me?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 42, 'm11o', 'A Determined Relative'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 43, 'm11s', 'Well done, citizen. Now that you''ve killed the gangster that my cousin became, their soul can finally find rest and peace. Ever since my cousin started leading that vicious gang, I knew they were no longer the loving individual I grew up with - that person was truly dead. You''ve earned this reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 44, 'm11t', 'Stop violent gang'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 45, 'm12d', 'A band of crooks kidnapped my young son several weeks ago and demanded a ransom. Before it could be paid, my dear son, who suffered from a rare form of asthma, died while being held by the kidnappers. The band fled the area but I''ve managed to track them down. I know they''ll do this again to some other unlucky parent. Fortunately, I have the means to provide a substantial reward to anyone who can end the careers of these kidnappers and gain justice for my dead son. Will you accept?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 46, 'm12o', 'A Vengeful Mother'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 47, 'm12s', 'You have my eternal gratitude. Now finally my son and I can find peace. Claim your reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 48, 'm12t', 'Stamp out the kidnappers'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 49, 'm13d', 'Pirates are a plague on interstellar shipping. Those murderous thieves end up costing the Empire millions of credits each year, not to mention the resources necessary to hunt them down or the terrible loss of life their attacks incur. One way we can hit those pirates hard is by cutting their access to safe ports and hideouts. It''s not easy to hide a spaceship, even the smaller fighters employed by some of these rogues. We know of several suspicious outposts big enough to contain landing bays. We need the help of upstanding citizens to blast these outposts to pieces. We compensate for results not attempts. Do you think you can help keep the star lanes safe?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 50, 'm13o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 51, 'm13s', 'Good work, citizen. Keep at it and we''ll keep paying you.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 52, 'm13t', 'Take out the pirates'' landing bays'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 53, 'm14d', 'If pirates don''t have working ships, they can''t practice their despicable trade. We''ve learned of several small storage facilities in the area that house a wide assortment of spare ship parts. We''re fairly certain that these are pirate stashes, especially given the shady characters that are often seen guarding these places. Our own personnel are already stretched rather thin but the Empire has granted us additional credits to hire independent agents to help us take care of the pirate problem. We need someone to blast these facilities to atoms. You may encounter some armed resistance, but hey, these are dangerous criminals we''re dealing with after all. Can you help?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 54, 'm14o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 55, 'm14s', 'Pirate ships floating uselessly in space is an image we like, citizen. Good work in helping us to ground those marauding vessels.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 56, 'm14t', 'Blow up the pirates'' spare parts'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 57, 'm15d', 'Ever wonder where pirates store their ill-gotten goods, citizen? We''ve discovered a few places and we need them destroyed. Our agents are too busy investigating murders and violent crimes to attend to this matter themselves so we''ve decided to turn to you - the average upstanding citizen. We''ll compensate you for every storage facility on our list that you blast to atoms. No questions asked, just go in blasting and take out anyone trying to stand in your way. We''ll transmit the coordinates to you as soon as you accept.  '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 58, 'm15o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 59, 'm15s', 'Job well done, citizen. The money is yours.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 60, 'm15t', 'Blast pirate''s stash'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 61, 'm16d', 'A group of known pirates have started hanging around an abandoned settlement. That place is beginning to attract all manner of scum. We''re fairly certain they deal glitterstim spice out of there and no telling what else. Can you imagine what sorts of other criminal activities are going on there even as you read this? We''ve had enough. We want to hire someone to blast that den of thieves into oblivion. Do you think you can help us keep our communities free of these parasites? We''ll send along the coordinates to the settlement as soon as we have your confirmation.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 62, 'm16o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 63, 'm16s', 'That''s showing them, citizen. Those space slugs will think twice about crossing our path. You''ve earned your reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 64, 'm16t', 'Demolish the pirates'' hangout'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 65, 'm17d', 'Those thieving pirates wouldn''t be able to operate if it weren''t for their fences. After all, it''s not exactly as if those rogues could just traipse down to the local market with all their stolen goods, now is it? Those darn fences are just as culpable as the murderers they deal with as far as we''re concerned. We''ve tracked down a few of these "blood money traders" and want their operations terminated. Many of these fences are former pirates themselves who either have grown too old to continue their murderous careers or else suffered enough physical damage to force an early retirement. If we provide you with the locations of these fences, will you make sure they pay the price for dealing with these killers? Help us save innocent lives. '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 66, 'm17o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 67, 'm17s', 'If we make piracy unprofitable, perhaps it will end. You''re certainly doing your part, citizen. Congratulations.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 68, 'm17t', 'Take out the fences'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 69, 'm18d', 'Like all vermin, pirates need holes they can crawl down into when they''re in danger of being exterminated. We''ve located some of these safehouses in our area and want these places blasted into oblivion. We''re offering a decent reward to any citizen who can help us get rid of these vermin-infested places. If you think you''ve got what it takes, accept this mission and we''ll send you the coordinates to some of these wretched hovels. Help keep our streets clean!'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 70, 'm18o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 71, 'm18s', 'As an Exterminator for Justice, citizen, you shine like a supernova. Keep up the excellent work and remember that your children will inherit this galaxy.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 72, 'm18t', 'Blast pirate''s hideout'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 73, 'm19d', 'I lost my beautiful wife in a dastardly pirate raid a year ago. Since that time, I''ve spent every waking moment and my entire fortune tracking down the pirate captain that led that cowardly attack. Now, I''ve finally managed to track that blackguard down. The time for my dead wife''s vengeance is at hand. How I wish I could be the actual instrument of that devil''s demise but alas the attack that robbed me of my wife left me a physical wreck. That''s why I need someone like you. Help me avenge my dear wife. Her voice cries out from beyond oblivion for justice. If successful, you will walk away with both my gratitude and a handsome reward. '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 74, 'm19o', 'A Justice Seeker'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 75, 'm19s', 'My thanks, friend. I can now join my beloved wife wherever she may be. You''ve helped two wayward souls find each other again. Farewell.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 76, 'm19t', 'Avenge a murder'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 77, 'm20d', 'Oh, a pirate''s life is a terrible thing. That''s right, I used to run in those villainous circles myself until the treacherous nature of the scum around me brought me to ruin and almost robbed me of my life. Now, as the tragic and tortured soul that I''ve become, I seek only one thing - to make things right with the folks whose lives I so callously ruined. And I''d like to start by bringing my former "partner" to justice. Aye, that womp rat is richly deserving of a painful and gruesome death (for all those innocents that were slaughtered by that devil, of course) and I hope to play some part in making sure those wrongs are redressed. I''d attend to this matter personally, but you see I''ve taken holy vows never again to shed blood again. But seeing as there are others in the galaxy not burdened by this noble stricture, I''ve decided to offer a reward to anyone who can help me achieve my quest. I hope that someone is you, friend. Say aye and the coordinates to this putrid pile''s hideout will be yours. Please, for the sake of the lost little ones, blast away at everything in sight. Bless you.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 78, 'm20o', 'A Reformed Soul'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 79, 'm20s', 'Well struck, friend! Did you burn the place to the ground? Were there any of those murderous pirates inside the struture when it went up? Oh how I wish I could have heard the agonized screams of the unjust. Claim your reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 80, 'm20t', 'Help avenge a betrayal'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 81, 'm21d', 'There''s been a sudden increase of pirate activity in this sector. We investigated and discovered a secret refueling depot that those rogues had built to aid them in launching attacks from this system. We''re in need of a professional problem solver to get rid of this refueling station so those criminals stop visiting our planet. There will be adequate compensation for the being who succeeds. Can you lend a helping hand, citizen?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 82, 'm21o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 83, 'm21s', 'That should discourage those thieving vermin to steer clear of this system. Good work, citizen. Hope you decide to work for us again.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 84, 'm21t', 'Take out the pirates'' refueling depot'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 85, 'm22d', 'An old starship repair shop was purchased recently by a newcomer. Didn''t think much of it until we started getting reports of suspicious activity around the shop at odd hours of the night. After an investigation, we discovered that the newcomer is actually a former smuggler whose new career consists of serving as a mechanic to well-known pirates. Tragically, the contact who helped us discover this information paid for it with his life - we found him a few days ago stuffed in a crate of alluvial dampers. These murderers must be stopped and justice must be served. Can you help us put this criminal out of business, citizen?  '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 86, 'm22o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 87, 'm22s', 'Good job, citizen. Justice is served today. We hope you decide to work for us again.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 88, 'm22t', 'Take out pirates'' repair shop'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 89, 'm23d', 'In the event of his death, my master instructed me to transmit this request via the HoloNet to all available terminals. I am to send a generous amount of credits to the being that can successfully destroy a small landing bay, the coordinates to which I am to transmit upon receiving someone''s acceptance of this mission. My master was not terribly specific as to why he wished this facility blasted to pieces but I do know that he ran with a rather "dubious" crowd. The security at our home is most impressive, which leads me to conclude he had a reason to fear for his life. A shame this security could not travel with him - he might still be alive had this been the case. In any event, if you think you can accomplish this task, distasteful though it might appear, please respond as soon as possible. Thank you.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 90, 'm23o', 'An Obedient Droid'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 91, 'm23s', 'Wonderful! I am now allowed to transmit the full amount of the reward to your account. My master would be so pleased... if he were still here. Oh dear...'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 92, 'm23t', 'Help the faithful droid'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 93, 'm24d', 'Pirates and smugglers are all the same - they should all be spaced! Just when I think it''s safe to trust one of those slug-sucking rogues, they go and break my heart all over again. Well I can break things too, you know. I''ll offer a reward to anyone that blasts that cheating ''s landing bay (with their precious ship still inside) into oblivion. We''ll show those brutes they can''t just walk all over any woman they want. We have feelings and passions, and those can be roused for both good and ill. If you were ever treated this way by someone, I''m sure you''ll lend a hand. I''ll transmit the coordinates to the landing bay as soon as I receive a positive response. Consider this a strike for women all across the galaxy.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 94, 'm24o', 'A Woman Scorned'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 95, 'm24s', 'Not only my gratitude but the gratitude of women throughout the galaxy goes with you. Thank you for helping us stand up to these heartbreaking rogues.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 96, 'm24t', 'Help avenge a scorned woman'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 97, 'm25d', 'These darn smugglers think they can stash their ill-gotten goods anywhere they darn please. Well they''re wrong. A concerned group of citizens is willing to put up a reward to be claimed by anyone willing to blast these stashes to smithereens. These smugglers are cowards in any case, doubt they''d put up much of a fight. You willing to give it a try, citizen? '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 98, 'm25o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 99, 'm25s', 'The Empire could use more upstanding folk like yourself. Claim your reward, citizen, you''ve earned it.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 100, 'm25t', 'Blast illegal stash'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 101, 'm26d', 'We''ve found an old abandoned settlement that''s currently being used by some local smugglers to store their stolen goods. The local authorities don''t seem to care (they''re busy chasing "dangerous Rebels"), which leaves this dirty work for us citizens. We''re offering a reward to anyone willing to help get rid of this smugglers'' depot. Don''t leave a single wall standing, citizen. You up for it?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 102, 'm26o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 103, 'm26s', 'Now those are results we can appreciate, citizen. Good work! The reward is yours.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 104, 'm26t', 'Remove smuggler''s depot'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 105, 'm27d', 'We''ve seen shady characters loitering around certain locations, and don''t think we don''t know what''s going on. Smugglers have been known to frequent these parts and we all know what they do. We''ve pinpointed one of these so called "warehouses" and need it blown to atoms, and we''re willing to offer a reward to the citizen who''ll take up the challenge. We won''t stand for this sort of activity in our own backyards. Think you can help, citizen? '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 106, 'm27o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 107, 'm27s', 'That''s showing those hooligans, citizen. I bet those smugglers won''t come around here no more. Don''t spend that reward all in one place.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 108, 'm27t', 'Take out smuggler''s warehouse'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 109, 'm28d', 'I remember when this neighborhood used to be a decent place for citizens to raise their families. Well a bad element has been moving into our community. Smugglers! They sweep in here with their bluster and charm and think we don''t see exactly what they''re up to? I got news for them - we know exactly what they''re up to! I''m willing to put up a reward to get a brave citizen to encourage these criminals to get out of town. There''s a small hideout near here where these smugglers have been meeting. If someone could blast that place to atoms, that''d send a strong signal to those ne''er-do-wells. Think you can lend a hand, citizen?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 110, 'm28o', 'A Concerned Citizen'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 111, 'm28s', 'That''s giving them what for, citizen! Job well done! The reward money is yours, my friend.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 112, 'm28t', 'Encourage smugglers to leave'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 113, 'm29d', 'Some smuggler has been hanging about chatting with the neighborhood kids. No doubt they''re encouraging our young ones to turn to a life of crime. We need a brave and upstanding citizen to help us drive this criminal out of our area. Here are the coordinates to this scoundrel''s hangout. Several sustained shots from a heavy blaster ought to get the point across. Burn this hangout to ashes and you''ll drive this womp rat out of its den. A reward awaits the citizen who accomplishes this.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 114, 'm29o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 115, 'm29s', 'Now our children have a shot at a clean future. Good work, citizen! This reward is but a small token of our esteem.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 116, 'm29t', 'Get rid of the smuggler'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 117, 'm30d', 'Why must smugglers always be attracted to areas where decent folk choose to live? I suppose they think they''re less likely to be caught by the local authorities. Well I''m going to prove them wrong. I''m offering a reward to anyone brave enough to blast a local smuggler''s haunt to atoms. I''m a family man with young ones dependent on me, otherwise I''d do the deed myself. Most of these types are cowards anyway and run at the first sign of trouble. Do you think you can help our community out, citizen?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 118, 'm30o', 'An Angry Citizen'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 119, 'm30s', 'See? Bet that coward gave you no troubles. The reward is yours, good citizen. You''ve earned it.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 120, 'm30t', 'Scare the smuggler away'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 121, 'm31d', 'These cheap smugglers think they can swagger into someone''s life, charm that person with their devilish good looks and winning smile, use that innocent individual to further their own ends, and then dump that poor soul like a sack of bantha fodder when they''re done. Well I have news for these heartbreakers - this is one poor soul that''s striking back! I''m willing to pay a handsome reward to the noble individual who helps defend a woman''s honor. I know where this cheating smuggler has stashed their latest catch. It''s worth quite a bit to them, which is why I want it burned to the ground. Can you take up this cause, citizen? Will you be my very own Jedi knight?  '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 122, 'm31o', 'A Woman Scorned'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 123, 'm31s', 'Success, my Jedi! That cheating scum will think twice about using another woman again. I''ll gladly pay my Jedi''s reward. Can I see your lightsaber first?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 124, 'm31t', 'Avenge the scorned lover'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 125, 'm32d', 'I''ve tried to reason with my cousin. I''ve pleaded with them. I''ve even threatened to go to the authorities. But all of this has yielded no results. They''re still engaged in smuggling. Now, I must turn to more drastic measures. That''s the only thing that will save my poor cousin''s life. I know where they''re keeping a small shipment of illegal weapons and if someone were to burn this hiding place to the ground, I''m sure my cousin would realize the grave danger they''re in and abandon their life of crime. Can you help me with this, citizen? There''s a reward in it for you. Please try and spare my cousin, however. They''re the handsome one with the winning smile. I''d hate to see any harm come to them.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 126, 'm32o', 'A Desperate Relative'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 127, 'm32s', 'Hurray! Now I''m certain my cousin will fly straight. Here''s your reward. Oh, my cousin did survive? Right?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 128, 'm32t', 'Dissuade a smuggler'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 129, 'm33d', 'My "partner" has decided to cheat me out of my fair share of a recent haul. Not only did this scoundrel try to turn me in to the authorities, they told our friends that I was trying to sell all of them out. Payback time. I know where my former partner has been hiding out. I''m willing to pay a fairly generous reward to anyone that takes a blaster to this hideout, hopefully while my partner is still inside. You want to help a wronged, hardworking soul even a score, citizen? '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 130, 'm33o', 'A Cheated Partner'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 131, 'm33s', 'You''re a citizen after my own heart: efficient and ruthless. That reward is already yours.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 132, 'm33t', 'Even up a score'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 133, 'm34d', 'I''m an even-tempered businessman who made a deal with a respectable transport captain - or so I thought at the time. This captain was to pick up certain valuables from one location and drop them off at another location. Simple, isn''t it? This sort of business has been conducted without a hitch for hundreds of years. Well this "captain" ended up keeping these valuables rather than delivering them to the appointed location - a move which cost me a considerable amount of money. I believe this captain needs a lesson. So much so that I''m putting up my own money as a reward to make sure this lesson is well taught. I have the coordinates to this captain''s hangout and am in need of an enterprising individual with a very large blaster to collect this reward. Any comers?'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 134, 'm34o', 'A Legitimate Businessman'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 135, 'm34s', 'Bravo, citizen. Well struck. I wish we businessmen has more access to honest, dedicated individuals like yourself. Makes for good business.'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 136, 'm34t', 'Teach a lesson'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 137, 'm35d', 'I''ve been at this damn smuggling business too long. I want out. But I can''t do it alone. I''m willing to pay someone to help "retire" me from this criminal life. I give the coordinates, you show up blasting away and asking no questions. Leave no evidence behind, no soul alive to talk about it. A simple, clean solution. What do you say? Can you do your part to rid the galaxy of a "notorious space pirate?" Cash awaits you if you do. '),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 138, 'm35o', 'A Tired Old Pirate'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 139, 'm35s', 'Good job, citizen. My "retirement" is in effect. Now I can turn my attentions to my real passion - professional dejarik player!'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 140, 'm35t', 'Help retire an old smuggler'),
('string/en/mission/mission_destroy_neutral_easy_npc.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 1, 'm1d', 'You, friend, you will be my absolute best buddy if you take care of this one little thing. I make, you know, intoxicants? Not exactly the totally legal kind? And it''s been good, it''s been good, but this kind of business attracts all kinds of the wrong people. And they''ve been sort of, well, leaning on me, asking for a cut of my profits or they''ll inform the Empire. It''s such a hassle. It''s not my style to lean back, but hey, I have to get these guys off my balance sheet. Or get somebody else to do it. Understand me?'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 2, 'm1o', 'Corellian Eager to be Your Friend'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 3, 'm1s', 'That is truly good news, friend. I tell you, you are my truest buddy in the world right now. I''m sure we''ll be in touch again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 4, 'm1t', 'Get These People Off My Back');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 5, 'm2d', 'One evening I was doing my usual business in downtown Coronet, and I approached a tall woman standing at a bar. I don''t know what happened to me then, but when she looked at me, I suddenly didn''t want to sell her death-sticks any more. I wanted to go home and rethink my life. Since then I''ve been thinking a lot. I''ve decided I have to stop the sleazebags who pump this poison into our society! I was just the seller, the pusher, but these guys do the actual manufacturing. I know their factory, and I''ll pay you to wipe it off the face of Corellia!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 6, 'm2o', 'Corellian Rethinking His Life'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 7, 'm2s', 'That''s really great news. Somehow I think that woman I talked to in the sports bar would be happy. Here''s your money. Now I have to go rethink my life some more.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 8, 'm2t', 'Wipe Out Corellian Death-Stick Factory'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 9, 'm3d', 'I''m a producer in Children''s Programming. The star of our "Darth Spooky''s Sinister Dark Side Theater" afternoon show has been dealing with a longtime glitterstim problem. He says his old suppliers are coming around, trying to tempt him back onto the stuff. We''d all rather keep this out of the newsfeeds, so rather than go to the police, we''re seeking a private solution to the criminal problem. If you''re discreet and can handle a fortified gang installation, contact me for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 10, 'm3o', 'Corellian Public Broadcasting Executive'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 11, 'm3s', 'What a relief. It''s hard enough keeping Darth Spooky''s hood down over his eyes when he''s shaking with withdrawal. We''ll keep him on track now. Here''s your fee.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 12, 'm3t', 'Rescue Glitterstim Addict'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 13, 'm4d', 'I run Corellia''s leading landspeeder repossession company. Recently yet another gang of goons rammed our main building. This gang used modified Ubrikkian Talon I combat cloud cars -- a nice model, by the way, very good on the resale market. As always, the gangsters rampaged through our offices, shooting people and shouting, "Repo slimes are lying scum!" (which, by the way, is an unfair characterization of our work). Now, I understand that passions can run high when a customer''s vehicle is repossessed, but hiring a gang to enact petty revenge is always out of line. (I also wonder, by the way, how such customers find money to hire a gang when they couldn''t make their speeder payments!) But I''ve found that it''s good practice to eliminate these gangs so they can''t do this again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 14, 'm4o', 'CEO of Corellian Vehicle Reclamation'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 15, 'm4s', 'You''ve done a great, great job. And I don''t say that to just everyone, by the way. Now I have to track down the customer who hired this latest batch of goons.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 16, 'm4t', 'Stop Rampages Through My Office'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 17, 'm5d', 'I run Corellia''s leading landspeeder repossession company. Now and again I deal with people who, shall we say, don''t emphasize bureaucratic recordkeeping. If they don''t happen to fill out tax reports or check the stolen-vehicle registers, that''s not my business. Recently, as often happens, a certain group of these people took issue with the quality and provenance of the vehicles I sold them, and have made forceful threats against my offices. I have always taken a hard line against troublemakers. I commission self-starting, go-getting representatives to go to these people''s bases and teach them a hard lesson in honest dealings. Are you up to this assignment?'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 18, 'm5o', 'CEO of Corellian Vehicle Reclamation'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 19, 'm5s', 'You''ve done a great, great job. And I don''t say that to just everyone, by the way. Gotta get back to work, thanks.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 20, 'm5t', 'Threats Against Repossession Company'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 21, 'm6d', 'Our business is selling fireworks, although the market has been so tough that nobody''s bought fireworks for, oh, ten or fifteen years. So we buy and sell certain other things, and do a decent business. Recently we delivered certain valuable non-firework commodities in a remote area, and the recipients neglected to pay us. Very firmly neglected, we might add, as evidenced by the charred remains of our collection agents. We fireworkers disapprove of this. We''re giving our entire fireworks production budget, which we no longer use, to the first individual who can teach these recipients a lesson in honesty. Very firmly teach them, we might add.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 22, 'm6o', 'Corellian Fireworks Transport'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 23, 'm6s', 'A fine job. We could use more people like you in the fireworks business.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 24, 'm6t', 'Help Fireworks Dealer Educate Customer'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 25, 'm7d', 'Bop Thrombo the Shaky Droid pulls in a small local audience of a few hundred million viewers, but he''s been trying to break into the galactic big time. To endear himself to a powerful agent, Bop did some embarrassing things he''d rather not describe. Too late, he found the "agent" was a fake, and incriminating holo recordings fell into the hands, or tentacles, of blackmailers. Bop got steamed, and -- what a spunky droid! -- went after them in their lair. Unfortunately they blew him to bits; we got it all on his built-in surveillance cam. Great footage, but now we really need to recover Bop''s brain. To do that, we need someone to clear out the gangsters first. Are you willing?'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 26, 'm7o', 'Corellian Sector Newsfeed'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 27, 'm7s', 'Great! We''ll send out a news crew to re-house Bop Thrombo''s brain and get his personal account of his crimefighting exploit. Clear out before we get there, please.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 28, 'm7t', 'Rescue Brave Bop Thrombo''s Brain'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 29, 'm8d', 'You haven''t had real gangster trouble until you''ve met gangsters in the blasted, brain-draining, spirit-deadening Agrilat Swamp of Corellia. That place is a pit. I know the tourists like the crystalline undergrowth, but that''s because they don''t have to pull the shards out of their boots when they''re running for their life from slavers. I got out. I''m never going back. But now that I''ve made some credits buying and selling certain Imperial "involuntary surplus goods," I''m hiring someone with a good sidearm to mete out some revenge. I don''t know exactly where those creeps are based now, but if you head into the Agrilat Swamp, be sure you''ve got good boots.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 30, 'm8o', 'An Agrilat Swamp Refugee'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 31, 'm8s', 'Thanks, friend! That was some fancy demolition. It warmed my heart to see it, and here I thought nothing could warm my heart after all that time in Agrilat Swamp.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 32, 'm8t', 'Catch Gangsters From Agrilat Swamp'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 33, 'm9d', 'Almost home after a Kessel run, we ran into Imperials and crash-landed. Things went rapidly downhill after that. Aside from some creature trouble that forced us to drop our cargo, we also had an internal saboteur. After we got back home, we discovered encrypted communications between our ship''s engineer and a rival smu-- courier team. We tracked the engineer to a smuggling base outside town, but it''s too well defended for us. We''ve gained a certain amount of new funding through insurance. We''re devoting a portion to anyone willing to teach our engineer and his buddies a lesson in honesty.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 34, 'm9o', 'Corellian Travellers Looking for an Acquaintance'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 35, 'm9s', 'Thank you. There is not much honesty in our line, but you''ve helped us do our part to increase the overall integrity level of our profession.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 36, 'm9t', 'Help Beat Folks Who Stole Our Cargo'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 37, 'm10d', 'The south side of Bela Vistal is, in my view, the worst part of town. If you go down there, you''d best be wary of a Dug named Lero Bown, the worst gang leader in the whole city. He''s a gambler who likes his fancy clothes and waves his gas-gem rings in everyone''s face. He owns a custom XP-38 landspeeder, and carries a Corellian Arms CR-2 blaster in his pocket and a vibroblade in his vest. One night not long ago, at a sabacc game at a cantina, Lero saw a female Dug named Darplimpa sitting at the bar. Lero grew enamored of her, and his flirtations provoked Darplimpa''s jealous mate. When the fight went badly for Lero, he fled town, promising revenge. We on the city council wish to pre-empt his violent return. We are covertly hiring well-armed adventurers to strike Lero''s headquarters and destroy his gang.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 38, 'm10o', 'A Bela Vistal Councillor'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 39, 'm10s', 'A fine assault. Lero Bown has certainly learned a lesson about meddling with the betrothed of a jealous Dug. I attach your fee.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 40, 'm10t', 'Bad Gang Leader Attacking Bela Vistal'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 41, 'm11d', 'While shipping cargo offworld, I had a run-in with some pirates. I know you''ll agree it''s not productive to get sidetracked by issues of "who blew up whose starship." The point is, these crooks, or their heirs and surviving coworkers, have a serious mad on, and I''m their target. According to the usual script, I''m supposed to flee offworld and live my life as a hunted fugitive. What a drag. I have a different idea: You go and blow up their base, and I''ll pay you well for getting them off my back. Hey, what could go wrong?'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 42, 'm11o', 'Corellian Just Trying to Live His Life'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 43, 'm11s', 'That was some fancy action, friend! I hope none of those pirates had friends, or we''ll be going through this little spat again. Thanks, contact you soon.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 44, 'm11t', 'Not My Fault Their Stupid Ship Blew Up'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 45, 'm12d', 'Existing tax and tariff structures are hampering Corellia''s ability to supply interested parties with that vital luxury good, Double Brandy. The way I see it, I provide Double Brandy to folks who wouldn''t otherwise get it, often at a lower price than official channels permit. In this way I''m creating happiness and stimulating the economy. A new smuggling gang recently crawled onto the scene, forcefully insisting that my trade routes belong to them. I feel these people have no real interest in Double Brandy as such, and hence don''t deserve to service my customers. I''m hiring you to convince them of this, permanently.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 46, 'm12o', 'Dealer in Corellian Double Brandy'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 47, 'm12s', 'I raise my glass in a toast to you, my friend. The true champion of Double Brandy will go to great lengths to bring it to customers. Thank you!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 48, 'm12t', 'Protect Double Brandy Supply Routes'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 49, 'm13d', 'Masternav, renowned for some of the best astrogation maps in the galaxy, faces a grave threat. Gangsters based in the remote wilderness have fired warning shots at our droidships as they return from survey missions. Extortion attempts followed shortly thereafter, demanding payment to "protect" our valuable ships. This company takes a hard line against criminals. In the absence of adequate police involvement, we are commissioning an independent agent to destroy the gangster base and protect (in the honest meaning of the word!) our astrogation ships.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 50, 'm13o', 'Corellian Masternav Incorporation'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 51, 'm13s', 'Masternav thanks you for your good work in protecting our droid surveyors. Astrogation work continues uninterrupted, thanks to you.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 52, 'm13t', 'Astrogation Surveyor Ships Attacked'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 53, 'm14d', 'Because millions of native-born Corellian merchants across the galaxy depend on our services, the Guild constantly updates its shipping safety reports. The "lift-and-land" survey describes pirate hazards during takeoffs and landing on Corellia and other notable trade worlds along the Corellian Trade Spine. For the latest update, we are tracking reports of unidentified installations seen in remote areas. To participate in our current research cycle, please report to the attached coordinates to engage and destroy any criminals present. Guild hovercams will record the event, and we shall update our guidelines based on our assessment of the threat posed.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 54, 'm14o', 'Corellian Merchants'' Guild'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 55, 'm14s', 'Our hovercams recorded the event, and we are updating our guides accordingly. Thank you for participating in this research cycle.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 56, 'm14t', '"Lift-and-Land" Crime Survey'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 57, 'm15d', 'When you employ some untrained rube from offworld to move your goods, you can''t count on the high standard of smuggling long established by native-born Corellians. The offworld-funded Open Shipping Consortium, which brings in every hayseed Outlier farmboy with a joystick and hires him out as a "smuggler," is now aggressively targeting the local market for Jorallan pearls and opals. The Corellian Discreet Shipping Industry Chamber of Commerce opposes this alien incursion. We have found their rural receiving depot. Because it falls far short of the Chamber''s rigorous safety standards, we ask you to destroy this menace to public safety.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 58, 'm15o', 'Corellian Discreet Shipping Industry Chamber of Commerce'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 59, 'm15s', 'Your successful demolition of the sub-par Open Shipping depot is good news for our cause of maintaining high standards in the discreet-shipping industry. Your payment is attached.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 60, 'm15t', 'Open Shipping Takeover of Jorallan Gems'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 61, 'm16d', 'You really have to see a beautiful Jorallan pearl or opal to appreciate it. Who wouldn''t want one? But if you feel like smuggling one onto Corellia, under the high-handed Corellian Discreet Shipping Industry Chamber of Commerce monopoly, you''ll pay a lot and likely deal with some calcified veteran who''ll tell you he''s forgotten more about smuggling than you''ll ever know. That''s the trouble! He''s forgotten it all! In the Open Shipping Consortium we believe in free smuggling for free smugglers. If you agree, help us by wiping out the monopoly CDSICoC Jorallan landing depot at these coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 62, 'm16o', 'Open Shipping Consortium'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 63, 'm16s', 'Yes! Jorallan gemstones for all the people! Another step on the path to free smuggling for all Corellia!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 64, 'm16t', 'Make Corellia Safe For Open Shipping Gems!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 65, 'm17d', 'When you''re moving something as delicate as Endorian wind-crystals past Imperial Star Destroyers, you need a native Corellian smuggler, not some halfwit offworlder who arrives from the Outer Rim and two heartbeats later gets dumped straight into a freighter cockpit. The discreet-shipping industry demands high standards in the movement of fragile wind-crystals. Yet now the offworld-funded Open Shipping Consortium has opened a new depot in the remote wilderness, far from the experienced eyes of Corellian quality-assurance supervisors. Imagine these priceless crystals shattering in this unsupervised pit. To protect these fragile masterpieces, we implore you to destroy the depot at once.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 66, 'm17o', 'Corellian Discreet Shipping Industry Chamber of Commerce'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 67, 'm17s', 'We congratulate you on your successful demolition of the substandard Open Shipping depot. Together, we will march forward in the cause of maintaining high standards in the discreet-shipping industry. '),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 68, 'm17t', 'Open Shipping Menace Moves to Wind-crystals'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 69, 'm18d', 'If you want wind-crystals smuggled from Endor to Corellia, who can help you? The hidebound, speciesist Corellian Discreet Shipping Industry Chamber of Commerce monopoly would like to lock you in at their overblown rates. In the Open Shipping Consortium we work for freedom to smuggle by anyone, anywhere, at an affordable price. To break the shackles of the CDSICoC, to land wind-crystals safely so all Corellians of all species can enjoy them, we urge you to destroy the monopoly wind-crystal landing depot that is strangling our illegitimate trade!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 70, 'm18o', 'Open Shipping Consortium'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 71, 'm18s', 'A strike for the people, friend! This marks another step on our inevitable path to victory. Free smuggling for all!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 72, 'm18t', 'Open Shipping Breaks Wind-crystal Monopoly!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 73, 'm19d', 'Because Lowickan firegems can cause reactor explosions when a ship enters hyperspace, the discriminating Corellian smuggler handles them according to safety standards described by the Corellian Discreet Shipping Industry Chamber of Commerce. But if you put some illiterate Outer Rim hick at the controls of a YT-1300 freighter, as the offworld-funded Open Shipping Consortium advocates, disaster may strike. A firegem merchant must now contend not only with Imperial blockades, but also with the likelihood of shoddy Open Shipping handling of extremely delicate merchandise. To lessen our clients'' worried uncertainty, we request that you destroy the new Open Shipping firegem receiving depot.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 74, 'm19o', 'Corellian Discreet Shipping Industry Chamber of Commerce'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 75, 'm19s', 'All substandard Open Shipping Consortium facilities earn the strong disapproval of our organization. With your help, we shall continue to enforce our recognized high standards in the Corellian smuggling industry.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 76, 'm19t', 'Open Shipping Menaces Firegem Trade'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 77, 'm20d', 'Very handy, isn''t it, that you can''t get a Lowickan firegem onto Corellia without running afoul of, not only the Empire, but also the monopolistic Corellian Discreet Shipping Industry Chamber of Commerce. It''s this short-sighted restraint of free trade that makes firegems so sought after. If folks could get them from any Open Shipping Consortium smuggler at a fair price, firegems would lose their cachet. No one would think them special. People would be less concerned about these gems''s beauty and internal warmth, and more about how the gems can accidentally destroy a hyperdrive. To promote greater public safety awareness, we urge you to strike a blow against CDSICoC lock-in by destroying their firegem receiving depot! Firegems to the people!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 78, 'm20o', 'Open Shipping Consortium'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 79, 'm20s', 'The cause of free smuggling must triumph, thanks to good workers like you. Death to the CDSICoC monopolists!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 80, 'm20t', 'Firegems Strangled by CDSICoC Monopoly!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 81, 'm21d', 'I am, how do you say, documentary holographer from far away -- I look for big break, get to Core Worlds. I am here to Corellia, seek very-big Twi''lek adventure-man O-i. My crew of the droids, they get very-good holos of O-i, he fight an Imperial garrison, use only holdout blaster and one canister laughing gas. Crew of the droids was send me holos, but oh no! Bad people, how do you say, "crooks"?, stole crew of the droids and also hovercams. I have nothing. I want O-i holos! I find crooks with droid track beacon. You go to very-big crook place, kill-kill everybody, get holos! OK?'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 82, 'm21o', 'Holographer from Outer Rim Territories'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 83, 'm21s', 'You do kill-kill, but no holos? Oh, very-bad! I need holos! O-i goes from Corellia long ago now. I must start over. I do not pay you, I push the "no" button. No, wait -- oh, I push wrong button, you get money anyways! Oh, no. Maybe I go back home, maybe.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 84, 'm21t', 'Please to Help Recover O-i Holos'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 85, 'm22d', '[Translated from Selonian:] I serve the Fertile Prosperity den in a remote area of Corellia. Recently offworlders set up a den near our own. We believe they are not planning an attack, but instead are moving manufactured goods between cities and space for criminal purposes. Their goal is irrelevant to us, but their movements endanger our young. This is unacceptable. The city law agents offer no help. We will give Corellian credits if you destroy the offworlder base. Leave our den unharmed.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 86, 'm22o', 'Fertile Prosperity Den, High Leader Sept'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 87, 'm22s', '[Translated from Selonian:] We are grateful for your service to our den. We pay you the credits as we agreed.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 88, 'm22t', 'Selonian Den Endangered'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 89, 'm23d', '[Translated from Selonian:] In the Transposed Sunrise den here on Corellia we own one hand-built Selonian coneship. Recently surface-dwellers of unknown den and breeding took our ship in the night without approval. The queen sent me out to track the ship. I followed the [untranslatable] signal and found the ship. Surface-dwellers are dismantling it. City law agents move too slowly. We require quick destruction of the surface-dweller den. We will pay Corellian credits to you for this task.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 90, 'm23o', 'Transposed Sunrise Den, Inaugural Sept'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 91, 'm23s', '[Translated from Selonian:] We are grateful. We are recovering the remains of our ship now. [Ceremonial blessing.] Here are your credits as we agreed.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 92, 'm23t', 'Selonian Coneship Stolen'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 93, 'm24d', 'The aging Aqualish gang leader Dovor Dowwn is facing challenges from his underlings. Those tuskers hate showing weakness, you know, but he can''t pretend much longer; he''s just getting too long in the tooth. Mindra, one of Dowwn''s lieutenants has gone renegade, setting up covert smuggling depots. She''ll use these depots as a power base to seize Dowwn''s Corellian trade. Dowwn just found out about one of Mindra''s renegade depots, and after he threw a few tantrums, he ordered it destroyed. Here''s why I''m asking your help: I have mining interests near Mindra''s depot. If the Aqualish lets loose all his firepower, I could take collateral damage. I''ll pay you to destroy Mindra''s depot, with minimal damage to the surroundings, before Dowwn gets to it.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 94, 'm24o', 'Janqual Mor, Coronet Mining Corporation'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 95, 'm24s', 'Good work. Very neat rubble, with minimal collateral damage. I''m sending your fee with this note. This situation may arise again, so be ready.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 96, 'm24t', 'Gang War Threatens Mining Interests'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 97, 'm25d', 'For too long has legitimate Corellian commerce suffered the hair-trigger temper of the Aqualish gang leader Dovor Dowwn. His smuggling operation has drained our world''s coffers of legitimate tax income, leading to a weakened economy and loss of jobs. I beseech all honest adventurers to assail Dowwn''s many smuggling depots and bring down his corrupt operation! [INTERRUPT] Hi hi, scuse me for slicing Mindra''s transmission. Emmin Whitehat, thass me, spreader of truth. Mindra Nox was Dowwn''s lieutenant (she reeeally thinks you don''t know that???). She wants to take over his smuggling stuff. OK just thot you like to know haha. [END INTERRUPT, TRANSMISSION RESUMES] Though uninvolved myself in this sordid matter, I am moved by a sense of charity to offer a reward for successful assaults. Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 98, 'm25o', 'Mindra Nox, Corellian Entrepreneur'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 99, 'm25s', 'Thank you. I need to ask, was there anything odd about the text of my assignment? I''ve had slicer troubles. I''m compiling a list of grievances, and that slicer will eventually answer for all of them.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 100, 'm25t', 'Stamp Out Dowwn''s Operation'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 101, 'm26d', 'Gaah! You''d think someone, somewhere, one single little individual in this great big galaxy, would show gratitude just once. But no! That ungrateful human Mindra Nox, with her insipid square white teeth in her disgusting rubber-lipped red mouth-opening, has taken all the wisdom I taught her -- all the crew and equipment I assigned her -- and revolted! She''s setting up her own secret bases, and she thought I wouldn''t find out. Stupid, beady-eyed, dimwitted human! As it happens, I''m distracted with other business offworld right now, but don''t think I can''t squash her like a bug. For convenience, I''m willing to pay freelance scum to dispose of Mindra''s latest pathetic little hovel.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 102, 'm26o', 'Dovor Dowwn, Aqualish Businessbeing'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 103, 'm26s', 'All right, all right, so you destroyed a base. You expect me to slobber all over you in gratitude? Take your money. I''ll call if I need more help -- not that I will, mind you!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 104, 'm26t', 'Traitorous Backstabbing Betrayer '),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 105, 'm27d', 'I''ve had endless trouble with a rogue Corellian slicer who calls himself Emmin Whitehat. He''s cost me a lot of trouble -- a LOT -- but I''ve finally located the sleazy little compartment he calls home, and I''m paying very good money for you to take him out. [INTERRUPT] Thass right, lady, I so scared right here where you find me! Ready & waiting haha! OK love & kiss, Emmin [END INTERRUPT, TRANSMISSION RESUMES] Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 106, 'm27o', 'Mindra Nox, Corellian Entrepreneur'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 107, 'm27s', 'You fool, you destroyed one of my own installations! That verminous Whitehat corrupted my coordinates. And now I see that he''s deducted your fee from my accounts. Well, he can play his pranks, but I''m keeping a tab for what he''s cost me. I don''t forget.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 108, 'm27t', 'Criminal Slicer Emmin Whitehat'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 109, 'm28d', 'Humans make me sick. First, when I see their perversely smooth faces and the weird, bushy colored filaments covering their scalp, it''s all I can do to avoid retching in my tusks. Just as bad as their ugliness, though, and their insipid mild nature -- oh, and their obnoxious rubbery lips, those make my gorge rise -- just as bad is their traitorous nature. "You can''t trust a human" -- my creche-mom always said that. I never believed her, because she was a stupid shaak-brain, but I should have! I should have! This human who worked for me, Mindra Nox, has taken my people and equipment and set up her own smugg-- business operation! Treachery! Stop wasting your time reading your stupid datapad and go destroy her!'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 110, 'm28o', 'Dovor Dowwn, Aqualish Businessbeing'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 111, 'm28s', 'The unmitigated gall of that stupid human. It makes me want to vomit. I hate them all. Take your money, get away from me.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 112, 'm28t', 'Nox''s Treachery Knows No Bounds'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 113, 'm29d', '[INTERRUPT] Hi hi, Emmin Whitehat atcha. I a slicer (like you couldn''t tell???) doin a little spoofy of smuggler and crimelord (she wishes!!!) Mindra Nox. Mindra and I go waaay back, now I move waaay forward to fix her crookiness. Like for instance she kissed off (ugh!) her old boss Dovor Dowwn The Obnoxious Aqualish to set up smuggling places of her own (you didn''t know that???). So OK here is the deal. I took credits from her accounts (she is gonna shriek!!!) & I pay them to you if you blow up her new base real good haha. Why ask why??? [END INTERRUPT, TRANSMISSION ENDS]'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 114, 'm29o', 'Mindra Nox, Corellian Entrepreneur'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 115, 'm29s', '[INTERRUPT] OK Emmin here not Mindra (but you knew that!!!). You did OK there lots of damage. I saw from hovercam overhead. I give you Mindra''s money, be sure to tell her where you got it haha!!! [END INTERRUPT, TRANSMISSION ENDS]'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 116, 'm29t', 'Stop Evil Slicer OK (Yeah Right!!!) Haha'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 117, 'm30d', 'A mother doesn''t like to pry, but when my dear son Hartliss gets himself into trouble, I can''t help myself. I''ve just got to stick my nose in. You see, Hartliss is a contract spacer who runs the Spine when he needs money. I always tell him he''s got to be careful who he travels with. Heavens knows there are hooligans in the galaxy who can turn a good boy into a criminal. Like this last crew he freighted with. A pack of gundarks, that''s what they are. Tried to tempt my poor little boy with death sticks. Now that Hartliss is offworld on another run, I can finally do something about these immoral rapscallions. I sent a seeker droid to follow them. Found out that every night they gather in a little cantina outside of town. Now I just need some brave spirit to tiptoe down to that awful place and blast those scum-grubs into a billion subatomic particles.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 118, 'm30o', 'A Loving Mother'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 119, 'm30s', 'Now that was really satisfying, wasn''t it? I told my son Hartliss he should blast the place himself, but he called me a busybody. Do you think I''m a busybody? I just want what''s best. My little Hartliss deserves all the love I can provide.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 120, 'm30t', 'Hartliss Needs Some Help'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 121, 'm31d', 'What happened to the peaceful Corellia of our forefathers? It''s not bad enough that our sector is full of smugglers and Rebels. Now we''ve got a tide of death sticks and glitterstim pouring into the countryside. Well, some of us in the grasslands refuse to let this corruption take root. We''ve tagged several illegal spice dens across the surface of the planet, and collected enough credits to pay for their demolition. All we need is a good citizen who possesses the wherewithal to knock down these hives of villainy and make sure none of the dealers come back. Our list of coordinates is long, sadly, but we can shorten it with the help of some stalwart demolitionists.  Interested?'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 122, 'm31o', 'Concerned Corellian Citizens'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 123, 'm31s', 'That will teach those spice dealers not to bring their poison where decent Corellians live! We''ve got plenty more dens on our list, my friend, if and when you''re ready to work again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 124, 'm31t', 'Demolish Illegal Spice Dens'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 125, 'm32d', 'The Null Racket is the fastest Corvette in the sector. That kind of speed don''t come without work. A while back I custom ordered an ion impeller from a shipyard in Brak Sector. Too bad on the way to Corellia, it found its way into the hands of a competitor of mine. That''s just not friendly, is it? I''m betting a small sum of credits will convince this competitor to reconsider stealing from me. That is, if I use the credits to hire someone to burn his den of two-credit thieves to the ground. I don''t suppose you''d be game for the job? Don''t worry about the impeller. I''ve got another on the way, with a couple of Trandoshan guards this time. You just do this job well and you''ll make a name for yourself on Corellia.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 126, 'm32o', 'Captain Sava Matar of the Corvette Null Racket'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 127, 'm32s', 'You do good work. I''ll keep you in mind if I get another blaster job. Ol''val.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 128, 'm32t', 'Incinerate Unfriendly Competitor'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 129, 'm33d', 'Running the fastest Corvette in the sector ain''t like baking fringe cake. Competition can be downright savage in the Corellian freight business. You''ve got to keep your eyes open. Sometimes you''ve got to crank the turbines on a competitor when they start interfering with your livelihood. That''s where you come in, friend. If you want to earn a couple of credits today, I need you to put the hurt on a colleague of mine who tried to hand over the Null Racket to Imperial authorities. He doesn''t know I''m onto his double-cross, so he shouldn''t be expecting any trouble. Just to be sure, though, bring your best weapons. Dust the whole place and you''ll get a cut of my latest haul. Ol''val, min dul''skal, ahn guld domina.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 130, 'm33o', 'Captain Sava Matar of the Corvette Null Racket'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 131, 'm33s', 'Where did you come from, friend? You''re good. I''m going to remember your name. Ol''val.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 132, 'm33t', 'Dust a Double-Crosser'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 133, 'm34d', 'Ever seen an ugly fly? Trust me, you don''t want to. Uglies are rattletrap fighters welded together out of whatever space debris their builders can scavenge. They''re constructed for firepower, not for endurance, and they''re used as raiders and duellers. Uglies are a thorn in the side of the CDF. We''ve got a standing reward for anyone who shuts down one of the shops that put these jalopies together. Let us know if you''re interested in the job and we can send you the coordinates of a suspected ugly shop. Good luck.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 134, 'm34o', 'Corellian Defense Force'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 135, 'm34s', 'Good work. The fewer uglies that pester our space lanes, the more attention we can give to real problems in this sector.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 136, 'm34t', 'Uglies Are a Thorn in Our Side'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 137, 'm35d', 'As a Trandoshan, it is my duty to collect jagannath points by hunting dangerous prey. The problem, however, is that I''m a colossal coward. It''s only been due to the enormous wealth my father managed to accumulate during the enslavement of the Wookiees that I''ve been able to bribe my way through every single rite of passage sacred to my people. Unfortunately, a few less-enterprising inhabitants of Dosha have condemned my approach to our traditions. They''ve tracked me to Corellia and want my head at the end of a thrar''kor. I need to funnel some of my family''s wealth into stopping these brutes before they catch me, which can only have unpleasant results. If you blast my enemies to atoms, I''ll pay you well, and everyone will be happy. Do we have a deal?'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 138, 'm35o', 'An Anonymous Trandoshan'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 139, 'm35s', 'Excellent work, except that I sent you to the wrong place. My pursuers were not among the beings you attacked. Never mind, though, I''m sure they got the message. That''s the important thing. Take your payment, and may the Scorekeeper record your brave deed.'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 140, 'm35t', 'Help a Cowardly Trandoshan'),
('string/en/mission/mission_destroy_neutral_easy_npc_corellia.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 1, 'm1d', 'Stealing shaaks from a small family barely scraping by -- that''s just low! Worse than slaving, worse than smuggling, worse than -- well, not worse than blowing up Alderaan, but still pretty bad. We''re down to our last credits because of these poachers, and now we have to spend those credits hiring you to stop them. Careful -- they''re well armed and dangerous.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 2, 'm1o', 'Shaak Herder on the Great Grass Plains'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 3, 'm1s', 'Sounds like they already disposed of the stolen shaaks. But with the births coming up, we may be able to replenish our herd fast enough to survive. Thanks for disposing of those despicable lowlifes.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 4, 'm1t', 'Shaak Poaching -- Galaxy''s Worst Offense'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 5, 'm2d', 'Kirkhorn, the third-oldest guarlara stable on Naboo, has an enviable reputation. Envy has now escalated to criminality. Recently, rustlers destroyed our pasture alarm systems and stole Zenith Dancer, a thoroughbred champion. His implanted tracking chip has pinpointed their location. Security forces are occupied elsewhere, so we''re asking for quick action from an experienced agent. Destroy the rustlers and save Zenith, or this will happen again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 6, 'm2o', 'Kirkhorn Guarlara Stable'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 7, 'm2s', 'Good news! While you were dealing with the rustlers, Zenith escaped and galloped back home. It''s time to celebrate here at Kirkhorn. Here''s your fee, and thanks!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 8, 'm2t', 'Guarlara Rustlers Steal Champion'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 9, 'm3d', 'Gangsters have stolen funds earmarked for the upcoming Midseason Euphonial Festival. You may recall that this important event marks the premiere of Sandelratha''s "Emperor Symphony." To bring in Imperial Security would be politically indelicate, so we prefer to hire an independent agent to track and destroy these gangsters. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 10, 'm3o', 'The Office of the Music Advisor of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 11, 'm3s', 'With evidence from the destroyed camp, we can track the stolen funds. Thank you for your prompt action to protect the Euphonial Festival.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 12, 'm3t', 'Midseason Euphonial Festival In Doubt'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 13, 'm4d', 'The Twi''lek tellisatura diva Niral Dassacrin has performed the Nicol Bondot gaze-opera "Singularity Song" to sellout audiences. But Niral has run afoul of gangsters, who have extorted funds from her by threatening to cut her vocal chords. She belatedly confessed all, and this office is determined to stop the gangsters. We prefer not to contact Imperial security, so as to demonstrate we can protect our own. However, we do require an experienced independent agent. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 14, 'm4o', 'The Office of the Music Advisor of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 15, 'm4s', 'Now future performances of "Singularity Song" can go on unimpeded by chicanery. This office thanks you for your timely assistance.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 16, 'm4t', 'Protect Naboo''s Gaze-opera Diva'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 17, 'm5d', 'To improve offworld trade, my office works ceaselessly to develop Naboo''s freight infrastructure. An interplanetary smuggling gang is diverting specialized materials needed for docking bay construction, then selling them back to the government through various business fronts. Political considerations deter us from assigning this problem to Imperial security. We prefer to contract with independent agents to eliminate the smuggling gang. Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 18, 'm5o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 19, 'm5s', 'Thank you for your firm resolution of this smuggling nuisance. My office will gladly offer you further assignments in the future.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 20, 'm5t', 'Naboo Buying Back its Own Equipment'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 21, 'm6d', 'My office is charged with developing Naboo''s trade infrastructure. The new Interplanetary Customs Depot is now far over budget and behind schedule, due to persistent and omnivorous corruption. Most recently, gangsters have seized vital construction equipment and are holding it for ransom. They failed to disable all tracking devices, however, and so we know where they are. For political reasons we prefer not to involve Imperial Security. Instead, we shall hire an experienced independent agent. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 22, 'm6o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 23, 'm6s', 'Many thanks. The Customs Depot project may yet get back on track. My office looks forward to working with you again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 24, 'm6t', 'Naboo Customs Depot Construction Trouble'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 25, 'm7d', 'My office is proud that Naboo''s literacy rate approaches 100 percent. This is possible only through determined commitment and a healthy educational budget. This budget, though, attracts criminals as hsuberries attract colo claw fish. A rural school reports that gangsters are systematically stealing droid instructors for resale on the black market. I find this crime particularly offensive, yet Imperial security has assigned it low priority. I wish to stop this at once, and am willing to hire an independent agent to stop these criminals.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 26, 'm7o', 'The Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 27, 'm7s', 'Thank you, thank you, for stopping a particularly foul crime. To steal from a school is to steal from the future. I hope to work with you again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 28, 'm7t', 'Gangsters Stealing Naboo Instructor Droids'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 29, 'm8d', 'The bioengineering program at Theed University has developed some interesting compounds using chemicals produced by native wildlife. Thieves have stolen some of these experimental compounds, presumably for resale on the black market. Unfortunately, these are poisons derived from green glie algae. The containers'' hidden security sensors pinpoint their location. To prevent wide publicity and possible panic, I am privately hiring an independent agent to destroy these thieves and, if possible, the chemicals as well.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 30, 'm8o', 'The Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 31, 'm8s', 'Exceptional work! I have ordered probes sent to the area and haven''t detected the escape of any compounds. This is a relief, because those poisons could have killed most of Naboo. Thank you!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 32, 'm8t', 'Thieves Steal Theed University Poisons'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 33, 'm9d', 'My family''s famed Highscouter cove of trained twirrls has provided Theed Palace''s preferred breeding stock for generations. Recently smugglers have made attempts to steal these famous twirrls, no doubt for resale to offworld collectors. We have so far forestalled this theft, and we have also tracked the smugglers to their lair. We have seen evidence of considerable animal cruelty. Imperial security will do nothing for us until an actual theft is committed, so we''d like to hire an experienced agent to assault and destroy this base. Are you available?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 34, 'm9o', 'Highscouter Twirrl Cove'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 35, 'm9s', 'With those smugglers gone, we feel more comfortable already. Highscouter Cove thanks you. Look in with us next season for more work.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 36, 'm9t', 'Animal Theft in Twirrl Training Fields'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 37, 'm10d', 'The Science Office has long sought an industrial base sufficient to build hyperdrives. Currently the Empire provides drives of Nubian manufacture, through a lengthy and bureaucratic process. A pilot project is planned for Naboo''s moon Rori. Movement of materials to the Rori installation has been hampered by pirates, who infallibly strike our ships shortly after liftoff from Naboo. We suspect a spy in this office. Therefore I am personally contracting with an independent agent, outside normal office procedures, to locate and destroy the pirate base. Contact me for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 38, 'm10o', 'The Master of Science of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 39, 'm10s', 'This is fine news. I shall order new launches for the moonbase hyperdrive project. Thank you, and wish us luck!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 40, 'm10t', 'Hyperdrive Project Threatened by Pirates'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 41, 'm11d', 'Keren Farms Jut Nut Exquisite Select Roast remains the beverage of choice for discerning Theed aristocrats. We use only freshly excreted seeds of the jut nut, meticulously cleaning them after their passage through the peko-peko intestinal tract, which relieves them of toxicity. Keren Farms Jut Nut ESR fetches a premium price in discriminating markets. This has unfortunately made it attractive to thieves, who recently purloined much of this season''s crop. We have located the thieves through hidden tracking devices, and we now wish to hire an experienced agent to exterminate them like vermin. Serious inquiries only, please.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 42, 'm11o', 'Keren Farms Jut Nut Orchards'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 43, 'm11s', 'Your diligence ensures the safety of this season''s remaining Keren Farms Jut Nut Exquisite Select Roast crop. A hearty thank-you, and please stop in for a complimentary cup!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 44, 'm11t', 'Naboo''s Jut Nut Crop Stolen'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 45, 'm12d', 'My office''s many duties include the construction of communication relays between distant Naboo towns. Because of recent Imperial budget cuts, we lack the funds to protect these remote construction projects. A criminal gang has literally taken over one such outpost, destroying all comm equipment on hand. We find it politically and economically expedient to have the entire installation destroyed, not by Imperial security but by an independent contractor. Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 46, 'm12o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 47, 'm12s', 'This is good news in an office that has lately heard too little good news. We thank you for your quick and decisive action against these gangsters.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 48, 'm12t', 'Gangsters Seize Communications Relay'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 49, 'm13d', 'Gangs of millaflower pushers are operating in Naboo''s schools. In remote bases, the gangs process innocent millaflower blooms into a powerful intoxicant. Then they push the drug on our students. Education of the students has reduced demand, but we are also pursuing a supply strategy. Imperial Security is often in the gangsters'' pay, so we are hiring an independent agent to destroy each base as its location is determined. Contact my office for current coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 50, 'm13o', 'The Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 51, 'm13s', 'Excellent news. Your success provides a highlight for my forthcoming speech to the Advisory Council on the millaflower menace. Thank you!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 52, 'm13t', 'Millaflower Problem In Naboo''s Schools'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 53, 'm14d', 'Who could possibly be offended by Theed University''s research into interference with droid motivators? This defies reason, yet these innocent researchers have received anonymous death threats, and gangsters recently tried to destroy their lab. They unwittingly alerted probe droids who followed them at a distance, so we know where the gangsters are based. But Imperial security seems curiously apathetic to stopping these thugs. This office is pursuing independent solutions, such as hiring an agent to destroy this base. Contact us for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 54, 'm14o', 'The Office of the Master of Science of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 55, 'm14s', 'We are glad you stopped these thugs, but apparently they have ties to Imperial Security. This is strange and disturbing. We shall probably cancel the research project anyway.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 56, 'm14t', 'Thugs Threaten University Researchers'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 57, 'm15d', 'This office is responsible for arranging the famous Heritage Expressionals at the Emperor''s Retreat outside Theed. These concerts feature a range of antique instruments, the finest and most valuable in this region of the galaxy. Recently gangsters stole several Heritage instruments and, according to the tracking beacons hidden on the items, took them to the following coordinates. We strongly prefer to avoid involving Imperial Security in this matter, for fear of appearing irresponsible in protecting the Emperor''s property. Instead, we are hiring discreet independent agents to locate and destroy the gangster base, preferably without damaging the priceless Heritage instruments.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 58, 'm15o', 'The Office of the Music Advisor of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 59, 'm15s', 'But did you not find the Heritage instruments? Evidently the thieves had already fenced them and moved them offworld. We must locate them by other means.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 60, 'm15t', 'Recover Stolen Heritage Instruments'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 61, 'm16d', 'There is an old legend that one of the statues surrounding the Royal Palace contains hidden treasure. Supposedly a thief placed the valuables there during the statue''s construction, to dispose of incriminating evidence. The story doesn''t identify the statue or the valuables, but that hasn''t stopped treasure-seeking gangsters from attacking random statues across the palace grounds. Surveillance droids have tracked the thugs to their base, but Imperial Security shows no interest in arresting them. To protect a priceless artistic heritage, my office is hiring an independent agent to track and destroy the vandals.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 62, 'm16o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 63, 'm16s', 'This is a relief. We are already repairing the statues these thieves damaged. Hidden treasure -- what a silly legend. Thank you for your assistance.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 64, 'm16t', 'Vandals Damaging Royal Palace Statuary'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 65, 'm17d', 'Kirkhorn, Naboo''s third-oldest guarlara stable, produces some of the best guarlara underfur on the market. The underfur of Kirkhorn Assured Bloodlines has been woven into tapestries now on view in Theed''s best museums and homes. Such is the value of good guarlara underfur that bandits have been stealing this season''s production. We suspect a rival stable, but lack evidence. However, we have the thieves'' location, thanks to tracking beacons in the fur containers. Rather than bring in security forces and attract undue publicity -- always dangerous in the touchy underfur market -- we''d prefer to hire a discreet adventurer able to track and destroy these thieves. Are you willing?'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 66, 'm17o', 'Kirkhorn Guarlara Stable'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 67, 'm17s', 'I thank you for your assistance. Here is your payment. This will teach rival stables that Kirkhorn stands by its underfur!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 68, 'm17t', 'Kirkhorn Guarlara Underfur Stolen!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 69, 'm18d', 'It is no secret that Theed University boasts some of the most talented droid programmers in this part of the galaxy. What is secret is the recent disappearance of one of the university''s leading programmers. Kidnapping? Willful departure for richer climes? We have one clue: surveillance recordings that show known gangsters accompanying the scientist off campus. Probe droids tracked the group to a rural base. We believe that alerting Imperial Security to this event would only bring unwanted criticism of our security procedures. Therefore, we are quietly hiring an independent agent to eliminate the gangsters and, if possible, determine the fate of our programmer.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 70, 'm18o', 'The Office of the Master of Science of Naboo'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 71, 'm18s', 'The researcher returned safely. Apparently it was a kidnapping, but your timely intervention allowed our colleague to escape. Thank you!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 72, 'm18t', 'Theed Droid Programmer Vanishes'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 73, 'm19d', 'The Naboo Wastelands have long constituted a kind of safe haven for pirates and smugglers. Certain bands of these outlaws are known to have thrived for as long as several decades. Due perhaps to their longevity, they have now grown so bold as to move their operations out of the wasteland and closer to settled regions. Our satellites have identified several unauthorized installations where we believe these criminals are engaged in illegal pursuits. As our manpower is presently occupied with unforeseen Imperial obligations, we have opted to contract private operatives to investigate these trouble spots. Agents in our employ will be authorized to use extreme force in dispatching any lawbreakers they find. Qualified citizen operatives may contact the Royal Security Forces to be deputized for specific cases. Financial compensation is available.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 74, 'm19o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 75, 'm19s', 'You have a knack for this sort of work. Please contact us again when you have time for another mission.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 76, 'm19t', 'Outlaws Encroaching on Settlements'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 77, 'm20d', 'After a massive investigative effort, we have finally cracked the ring of data slicers that invaded the computer systems of the Theed Generator. These criminals have dispersed their operation over a series of transmission centers that combine to form a powerful slicing grid. We are coordinating a joint police-civilian effort to strike these transmission centers and shut down their destructive operation. Naboo civilians who can aid in this effort are encouraged to contact the RSF as soon as possible. Offworlders may also participate. Financial compensation will be scaled in accordance with the contribution of each civilian.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 78, 'm20o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 79, 'm20s', 'The operation was a success! Those slicers have almost brought down the Theed Generator on several occasions, but they will not do so again. Thank you for your contribution to the effort.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 80, 'm20t', 'Shut Down Data Slicer Network'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 81, 'm21d', 'Valstaff Courts is the fourth-oldest guarlara stable on Naboo. We breed only the purest bloodlines for the finest Naboo families. Our grounds are legendary for their beauty and luxury, a place where young Naboo ladies may cleave the winds astride elegant guarlara thoroughbreds. But we have noted the intrusion of many unwelcome individuals of dubious character and social standing. These persons frequent our riding grounds and proffer immodest solicitations to our clients. They have proven difficult for our security staff to control. We are therefore offering to professional adventurers and soldiers-of-fortune a reward for the successful extirpation of the trespassers'' premises and all sapient beings therein. Qualified applicants may contact our Sapient Resources department for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 82, 'm21o', 'Valstaff Courts Guarlara Farm'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 83, 'm21s', 'Valstaff Courts is proud to assure the highest degree of security to our distinguished Naboo clientele. Your aptitude with killing and mayhem offers a vital tool in our mission of unparallelled refinement and elegance.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 84, 'm21t', 'Expunge Untoward Visitors'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 85, 'm22d', 'In the court of Naboo one must be vigilant against the corrupting influences of the spacer community. The daughter of an esteemed colleague of the court has fallen victim to the affections of a star pilot of uncertain reputation, one Thanus March. In deference to the child''s social standing, I feel obliged to handle this unfortunate circumstance discreetly. March is known to carouse at an old power station converted into a hive of offworlder decadence. I require one or more freelance operatives to deliver a clear message that this man has no place in the proud halls of Naboo. In short, I want the place taken apart. Meet any resistance with extreme force. If March does not survive the assault, I for one shall shed no tears. I shall pay you handsomely, but most of all, realize that you will be saving the reputation of an innocent lady.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 86, 'm22o', 'Lord Zymanna of Theed'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 87, 'm22s', 'Excellent. A Zabrak informant of mine tells me that the spacer Thanus March escaped with few injuries, but your work against his cohorts was very impressive. While you are on Naboo, you are welcome in my employ.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 88, 'm22t', 'Protect Reputation of Innocent Naboo Lady'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 89, 'm23d', 'Good day. I am TC-20, a protocol droid presently residing in the city of Theed. My mistress is a highborn Naboo lady who must remain anonymous. Her Ladyship has instructed me to hire an experienced warrior to aid her in her dreadful need. The captain of a star freighter, one Thanus March, has been abducted by a brutal gang of ruffians. A trusted friend in the court has provided the coordinates where he is being held. My mistress assures me that this space captain does not deserve this uncivilized treatment, and has given me a generous sum to pay for his rescue. The plan is to attack the ruffians from the outside while an agent within frees Captain March. I hope it is not too late to save him from a terrible fate!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 90, 'm23o', 'TC-20, Protocol Droid'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 91, 'm23s', 'Oh, dear! I have awful news! While you performed the job for which you were hired, my mistress herself was kidnapped! It seems the crime was committed by associates of the very ruffians you attacked. My poor, poor mistress. Here, take the credits which Her Ladyship allotted for your services. How could this happen in the peaceful halls of Theed? What have I done to deserve this? Oh, dear!'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 92, 'm23t', 'My Mistress Requires Experienced Warrior'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 93, 'm24d', 'Even on a supposedly quiet planet like Naboo, the rules of the jungle apply. If someone hits you, you hit them back hard. Me and a couple of other spacers were attacked by a band of hired guns, sending me a message to keep away from a certain Naboo lady. I''m pretty sure the message came from her rich father. Well, I''m going to send back an answer. I''ve figured out where the thugs who hit us spend most of their time. I''m putting together a freelance team to smash the place to dust. I need fighters who are hungry and battle-hardened. Let''s show these Naboo bluebloods how we do it in the Core Worlds.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 94, 'm24o', 'Thanus March, Freelance Spacer'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 95, 'm24s', 'Nice work, kid. Those hired guns won''t bother anyone again. I questioned a Zabrak who was trying to escape and he confirmed what I already knew: It was the father of my Naboo lady who paid them to kill me. I guess I don''t die that easy. Lucky for me. Unlucky for my lady''s highbrow father.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 96, 'm24t', 'Assembling Freelance Strike Team'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 97, 'm25d', 'It''s outrageous! My teenage daughter, Dantre, tells me that her friend from offworld, a space captain named Thanus March, is being harrassed by a local gang of criminals. To my horror I learned that, because the victim in question is not from Naboo, Imperial policies prevent the Royal Security Force from acting in this matter. My daughter has implored me to do something. I am seeking a reputable freelance security agent to confront this gang of criminals and warn them against further harrassment of my daughter''s friend. It is possible that these scum will react with violence. If so, I want an equally forceful response. We must not tolerate these villains on our planet. While the Empire might turn a blind eye to criminal degeneracy, some of us Naboo still have our pride.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 98, 'm25o', 'Lord Chelm of Theed'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 99, 'm25s', 'I''m proud that Naboo and offworlders alike are willing to take a stand against heartless criminals. My daughter, Dantre, is most happy with your results. Well done.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 100, 'm25t', 'Do Not Tolerate Criminal Degeneracy'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 101, 'm26d', 'Since the New Order has brought security to the galaxy, the Naboo court is obliged to deal not only with the planetary bureaucracy but also with Imperial dignitaries. In such cases we sometimes perform discreet operations on their behalf. I currently find myself in such a position. In exchange for Imperial suppression of a certain police action against offworlders on Naboo, I am arranging the elimination of a den of suspected Rebels. I shall hire freelance operatives, for whom no bureaucratic approval is required. If you are capable of executing a potentially dangerous combat action, please contact my office. I expect you to be discreet; in these delicate times, subtlety is the road to success.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 102, 'm26o', 'Lord Zymanna of Theed'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 103, 'm26s', 'Excellent. My informants have verified that you handled the suspected Rebels most expeditiously. Remain discreet about this action and you shall do well on Naboo.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 104, 'm26t', 'Perform Discreet Combat Operation'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 105, 'm27d', 'They''ve got this festival in Theed where the Naboo lords give expensive gifts to their ladies. I''ve met a young lady of the court who I mean to give a gift. I know, a Corellian like me has a mynock''s chance of impressing some rich Naboo, but that''s never stopped me before. I''ve even found the perfect present. My problem is, the smuggler who''s holding it for me cranked up the price we agreed on. He figures I''ve got "rich connections." He''s wrong. My connections don''t have money, they''ve got blasters. I want someone who''s eager for a fight to soften up this smuggler. That way he''ll remember the original price when I visit. The Theed festival is coming up soon, so we can''t wait around on this. Tell me you''re interested and I''ll give you the guy''s coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 106, 'm27o', 'Thanus March, Freelance Spacer'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 107, 'm27s', 'I said soften the guy up, not incinerate him! That''s what I get for not being specific. You did good work, but I''m in a bind. I''ll never find that gift now. Well, if all I can give my Naboo lady is a kiss and a millaflower, I guess that''ll have to do.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 108, 'm27t', 'Soften Up Impolite Smuggler'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 109, 'm28d', 'My dearest friend is a young but seasoned star pilot. Though he''s changed his ways, he once traveled with a rough crowd. A few of his old associates have come to Naboo seeking revenge for some past insult. They don''t realize that he''s offworld right now, avoiding the painful scrutiny of my father''s security chief. My friend fears that, in his absence, these old associates might turn their attention to me. He advised me to hire a freelance investigator to hunt down and eliminate these dangerous spacers. I''m not certain that this action is legal, but my father is already skeptical of my friend''s reputation, and if he finds out I may be in danger I shall never see Captain March again. Can anyone out there help me? I want this awful business to be over with before Thanus returns.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 110, 'm28o', 'A Young Lady of Theed'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 111, 'm28s', 'Is it over? Did you take care of Captain March''s problem? Please, I don''t want details. Just take your payment and go. Oh, and thank you so much.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 112, 'm28t', 'Please Help in Delicate Matter'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 113, 'm29d', 'Because the Emperor''s Retreat brings much additional traffic to Naboo, we have prioritized the security of planetside settlements. To this end we have purchased a shipment of taser staves for crowd control. Somehow a gang of thieves captured these weapons before we could take possession. We must retrieve these staves without delay. Our intelligence agents have compiled a list of possible hideouts where the culprits might be storing their loot. We are contracting independent agents to investigate these sites and engage the thieves if they are found. Payment will be commensurate with the level of success.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 114, 'm29o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 115, 'm29s', 'Good job. We recovered all the taser staves. Those weapons can wreak all kinds of havoc in the hands of outlaws.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 116, 'm29t', 'Bring Down Gang of Thieves'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 117, 'm30d', 'The Tech Raiders are an old and notorious band of smugglers. For many years they avoided the star lanes of Naboo, but our sources inform us that they are back. Given the Imperial presence that now graces our planet, it is prudent that we stop this criminal activity before it draws a decisive response from the Empire. Therefore we are contracting private agents in a coordinated assault on several different smuggling depots. Qualified parties may contact the RSF for the coordinates of the nearest suspected Tech Raider site.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 118, 'm30o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 119, 'm30s', 'Good work. With luck we will have seen the last of the Tech Raiders in this system.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 120, 'm30t', 'Tech Raiders Smuggling Ring'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 121, 'm31d', 'You would think that the Naboo System, location of the Emperor''s Retreat, would be safe from the ravages of space piracy. But against all odds, a squadron of reckless cutthroats has taken up residence on our very planet. The Imperial Navy is anxious to bring down these pirates. The Royal Space Fighter Corps would very much like to catch them first. We have located a secret hangar that we believe houses many of their ships. We are hiring civilians to attack this hangar and force the pirates to take off, where we shall be waiting for them. With skill and good fortune we may both vanquish this threat to our star lanes and demonstrate that the Royal Space Fighter Corps is capable of handling threats that elude the Imperial Navy. Interested parties may contact us for the coordinates of the suspected pirate hangar.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 122, 'm31o', 'The Royal Space Fighter Corps'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 123, 'm31s', 'Terrific work! The operation was a complete success. The pirates fled through a hidden launch tunnel, and we picked them off in orbit. The Imperial Navy will chafe at this news. You did very well.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 124, 'm31t', 'Hit Suspected Pirate Hangar'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 125, 'm32d', 'Thieves have no limits to their petty greed. Even our garbage is not safe from these parasites. Naboo operates a planetwide system of robo-flatbeds that transport municipal garbage to various reprocessing sites. These hover-trains have become the target of robbers, who sort through the refuse to find any salvage and leave the rest strewn across our fair planet. We believe we have located the hideouts of many of these salvage gangs. All we need are lawful-minded civilians to put them out of commission. Full pardons are ready for any violence that may result from these action. Contact our office for the coordinates of a target near you.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 126, 'm32o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 127, 'm32s', 'Good work. Those thieves deserved what they got. If our garbage is not even safe, how can we assure the security of our people''s homes and properties?'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 128, 'm32t', 'Shut Down Salvage Gang'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 129, 'm33d', 'In order to preserve the natural beauty of our planet, Naboo carefully restricts all deforestation campaigns. Some renegade harvesters have flouted these policies and wilfully ignored all requests to cease their unlawful cutting. We must put a stop to their crimes. We are contracting private operatives to visit these outlaws'' barracks and put them out of business. If you can complete such an assignment, contact our office for coordinates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 130, 'm33o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 131, 'm33s', 'Nice job. Maybe now these outlaws will take seriously their responsibilities for preserving the natural state of Naboo.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 132, 'm33t', 'Renegade Harvesters'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 133, 'm34d', 'Some of desan topsiders have been comen into Lake Paonga and braken de laws of de Gungans. Desa diven into da deep Core and poachen dangerous fishes like de Opee and de Colo Claw. Wesa must putten a stop to dis, so wesa now hiren topsiders to knock down desan fishing shacks. Desa well-armed so do not thinken desa going to fall easy. Da Bosses going to pay yousa well enough for de work, though.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 134, 'm34o', 'Sergeant Degoolsby of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 135, 'm34s', 'Yousa done very well, for a topsider. Wesa given you da reward now. Great thanks to yousa.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 136, 'm34t', 'Desan Topsider Poachers Got to Go'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 137, 'm35d', 'It''s dreadful business, but I have been informed that a certain collection of unsavory spacers has begun disparaging me to potential employees of my shipping concern. As I must protect my reputation, I have no choice but to hire a responsible agent to stop their slanderous activities. The situation may turn ugly, but I must not yield. Please act quickly and let''s get this over with.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 138, 'm35o', 'Master Bottoblast of Theed'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 139, 'm35s', 'Splendid. That will silence those slanderous dogs. You have earned your reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 140, 'm35t', 'End Slanderous Activities'),
('string/en/mission/mission_destroy_neutral_easy_npc_naboo.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 1, 'm1d', 'Ever heard of lesai, citizen? It''s a highly addictive drug and it''s being stored in an abandoned settlement near here. Please help me make sure this drug won''t make its way to decent neighborhoods.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 3, 'm1s', 'Now those are results I can live with, citizen. Good work!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 4, 'm1t', 'Destroy Addictive Drug'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 5, 'm2d', 'There''s only one language criminals understand clearly -- the searing sounds of blaster fire! A group of violent thugs have been harassing decent folk and need to be driven off. If you can help do that, I''ll reward you.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 7, 'm2s', 'Good job, citizen. You''re a true hero. Your promised pay has been deposited.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 8, 'm2t', 'Drive Off Vicious Thugs'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 9, 'm3d', 'Due to the Empire''s higher recruitment standards, many of the thugs who would have ended up serving in planetary security forces are turning to crime instead. Could you help get rid of some of these troublemakers? I''d make it worth your while. '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 11, 'm3s', 'Thanks you, citizen. I''d normally suggest you join the military, but I think you could do more good as an independent agent. Get richer that way too.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 12, 'm3t', 'Discipline Slackers'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 13, 'm4d', 'I''m sick of putting up with criminals and their vile antics. I''ve gathered some credits to hire a skilled troubleshooter to get rid of these swoop gangs and spice dealers. Would you be interested in trying for that money, citizen?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 15, 'm4s', 'Now that''s how you deal with that Sithspawn! You''ve definitely earned the reward. '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 16, 'm4t', 'Citizens Fight Back'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 17, 'm5d', 'Hey, buddy, you care about keeping the streets clean, right? I hear there''s some lowlife peddling inferior grade glitterstim spice. Can you believe this worm''s nerve? Sure could use someone like you to run this bum out of business. You ready to earn some credits? '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 19, 'm5s', 'Good job. No one deals spice in my neighborhood without my say-so. And don''t even think about pushing that inferior grade sludge. Your money''s been sent, pal. '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 20, 'm5t', 'Run Competition Out'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 21, 'm6d', 'A local band of gunrunners has stolen a shipment of deadly disrupter weapons. This band is like no other, however, for they are led by an amazingly canny mouse droid. Yes, you heard correctly! If you were to stop these rogues and end this mechanical menace''s career, you''d become a legend.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 23, 'm6s', 'Did you see the mouse droid? Hmm, the clever fiend probably had an escape plan. All masterminds do. Do you know how I know that? Because I''m the Emperor! Mwahahaha! Anyway, this money is for your troubles.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 24, 'm6t', 'Stop Terrible Galatic Menace'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 25, 'm7d', 'All these jerks strutting around here think bravery resides in a blaster. But when push comes to shove, they turn tail and run. Are you one of those, or can you really stand up to the thugs menacing this area?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 27, 'm7s', 'I had a sense about you, citizen. True courage should always be rewarded. Your money''s been deposited.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 28, 'm7t', 'True Grit'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 29, 'm8d', 'You gotta help me, citizen! I testified against a swoop gang and got their leader sent to a labor camp on Berea. Now his followers have sworn vengeance and intend to burn my settlement to the ground. I''ll pay you to get rid of these brutes. '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 31, 'm8s', 'Your heroics will be an example to others, citizen! I think more folks will stand up to these animals now. Go spend your just reward!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 32, 'm8t', 'Witness Needs Protection'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 33, 'm9d', 'I''m trying to go straight, honest. I walked away from these spice smugglers, but now they claim I know too much about their operation and need to be silenced. Can you help protect me and my family? '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 35, 'm9s', 'Many thanks, friend! My family and I can now get on with our lives. The addition to your account should demonstrate my gratitude.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 36, 'm9t', 'Save Reformed Smuggler'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 37, 'm10d', 'I should know better than to get drunk at the cantina with my friends. We all got to boasting, as we always do, and I claimed I''d run the local swoop gang out of town by week''s end. The swoopers got wind of it and now intend to murder me. If you help me get rid of them, I''ll pay you.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 39, 'm10s', 'Well done, citizen! Your well-earned pay has been sent. If you ever get the fancy to knock back some cold ones with us, look us up at the cantina.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 40, 'm10t', 'Make Good a Drunk''s Boast'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 41, 'm11d', 'This community is being terrorized by a mindless gang of cutthroats whose only means of communication is wanton violence and destruction. If you put a stop to their vile activities, I''ll pay you a handsome reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 43, 'm11s', 'You''re a hero to the people, friend. Accept this reward and my unending gratitude. You should do this for a living.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 44, 'm11t', 'Be a Hero'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 45, 'm12d', 'A few young women have disappeared recently, and I suspect slavers. Those rogues have a base near here, from which I''m certain they''re shipping these girls offworld. Can you put a stop to this despicable activity?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 47, 'm12s', 'It''s good to know there are still heroes like you left in the galaxy. Please accept this payment as a token of my appreciation.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 48, 'm12t', 'Slavers Are Scum'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 49, 'm13d', 'Bullying helpless citizens requires very little courage, so I''m not sure why these thugs are so proud. You want to impress people? Then go after the thugs and drive them out of this area. That takes true courage!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 51, 'm13s', 'Citizen, you showed those bullies the true meaning of courage. Please accept this reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 52, 'm13t', 'Teach Bullies a Lesson'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 53, 'm14d', 'It was an accident that I killed one of those thugs. I had to do something, they were killing my pet! But now they''re coming after me. You have to go there and stop them!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 55, 'm14s', 'When a thug is killing my pet, I just get so steamed! Thank you so much for rescuing me. Please, enjoy this money!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 56, 'm14t', 'Defend Pet Owner'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 57, 'm15d', 'I wrote a play lampooning local crooked politicians. Turns out one didn''t have a sense of humor, and he''s hired thugs to burn down my house. But if you go to their hangout and stop them first, I''ll pay you well.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 59, 'm15s', 'That''s a relief. I''m going to write another play about this intimidation attempt, and you''ll be in it. Thanks!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 60, 'm15t', 'Save a Playwright'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 61, 'm16d', 'Those pirates are planning to take out an Alliance smuggling ship! I overheard them at the cantina. I can''t go to the Imperials, and I don''t know how to reach the Alliance, so I''ll pay you to stop those pirates.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 63, 'm16s', 'Well done! I expect the Alliance ship got through all right. It''s a shame they have to rely on smugglers, but the Empire controls the space lanes.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 64, 'm16t', 'Help the Alliance'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 65, 'm17d', 'My little child is crying in her creche because a local gang has stolen this community''s entire supply of infant formula. Now that''s low! We''ve all raised money to hire some goon like you to stop those other goons!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 67, 'm17s', 'Sorry I called you a goon. I was feeling tense. Thanks for freeing up the supply of infant formula. It''s the only kind my species can tolerate, you know.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 68, 'm17t', 'Help Starving Children'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 69, 'm18d', 'I broke up badly with an old flame, and my former sweetheart enlisted a bunch of lowlife thugs to harrass me. It''s been torture! I can''t reach my former love, so for now I want to hire you to stop the gang.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 71, 'm18s', 'Since I hired you, I found my old flame, and we''ve patched things up. A little. Anyway, thanks for stopping that gang.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 72, 'm18t', 'A Bad Breakup'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 73, 'm19d', 'With my life''s savings I bought a beautiful Corellian Jumpmaster 5000 starship. In orbit, pirates attacked me, and I had to get out in the escape pod. But I''ve tracked the pirates, and now I''m hiring you to go in and destroy them.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 75, 'm19s', 'Great! I sure showed those pirates -- or, I mean, you did! Enjor your reward. It''s all I have left, but now I can recover my ship and start over.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 76, 'm19t', 'Avenge Starship Captain'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 77, 'm20d', 'I had no idea one gang could stink up the air so much. No one can even sleep, it''s so bad. All the folks who miss clean air have put together some money to hire someone like you to clean out that gang. Will you do it?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 79, 'm20s', 'What in the galaxy were they doing, to create such a stench? Whatever it was, it was illegal, and you''ve put a stop to it. Thanks!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 80, 'm20t', 'Stop Stinky Thugs'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 81, 'm21d', 'A gang of thieves has been stealing ordinary GNK power droids all over this community. Nobody knows why; power droids aren''t particularly valuable. But we''ve traced the thieves, and we''ve raised funds to hire a thu-- I mean, an adventurer or two to face them down in their lair. Go for it!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 83, 'm21s', 'Thank you. Right now we''re trying to figure out why the thieves wanted all those gonk droids. Apparently they would steal them, then turn them loose. Senseless.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 84, 'm21t', 'Solve Gonk Droid Mystery'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 85, 'm22d', 'I''m in a bind. A friend of mine tangled with the wrong crowd and now they''re holding him captive in their thieves'' den. If I call the authorities, those filthy gundarks will see trouble coming from a long way off. Someone needs to hit the place secretly and rescue my friend. I''m sure he''ll compensate you well.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 87, 'm22s', 'Terrific! My friend escaped just after you arrived at the thieves'' den. He transmitted these credits to my account, and I forwarded them to you. Good job.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 88, 'm22t', 'Save Kidnapped Friend'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 89, 'm23d', 'May I have a word with you? I can''t name names, but a certain politician would like to put a stop to a plot by another politician. Parliamentary procedure being what it is, this dispute is best handled outside the halls of government. I must hire someone to blow up the criminals who are perpetrating this scheme. If you want the job, it''s yours.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 91, 'm23s', 'The politician who employs me will be delighted to hear that the esteemed colleague''s plot has been foiled. Interplanetary politics can be very satisfying, don''t you think?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 92, 'm23t', 'Political Intrigue'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 93, 'm24d', 'Please help me! I found out a local swoop gang has put a price on my head! What did I ever do to them? My only hope is for someone to wipe this gang off the face of the planet, so the bounty will become invalid. Surely a rough-and-ready spacer like you can help a desperate, wronged citizen in my time of need?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 94, 'm24o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 95, 'm24s', 'Your fee has been deposited. That will teach the other swoopers around here not to tangle with innocent, harmless citizens like me. Unfortunately they''re not a bright bunch.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 96, 'm24t', 'Slap Naughty Swoopers'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 97, 'm25d', 'Do you smell that? It''s waste gasses from a little ore refinery not far from here. A bunch of roughnecks built it to sidestep guild fees. Well, those of us who live around here don''t plan to let them poison our air. We''re willing to pay anyone who can knock that place out of operation once and for all. You''ve done this kind of work before, right?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 99, 'm25s', 'What a difference. I can smell that clean air! Well, cleaner than it was, anyway. You did your job and your payment''s been transmitted. Thanks.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 100, 'm25t', 'Help Clean the Air'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 101, 'm26d', 'The time has come, my friend. A band of space pirates robbed me of an expensive idol from the Onderon moon of Dxun. I can''t make them give it back, but I can pay to have them punished. Aim those killer instincts of yours at their planetside den and don''t look away until every one of them is dead.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 102, 'm26o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 103, 'm26s', 'Thanks, my friend. I knew you would finish them off with little trouble. I''ll head over and see if my stolen Dxun idol is somewhere in the rubble.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 104, 'm26t', 'Give Me the Idol'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 105, 'm27d', 'I''m not who you think I am. People say I look like an announcer from the local newsfeed, but I''m just a loyal Imperial citizen. I''m hiring someone to assault a local spice gang. Make it flashy. There could be, I don''t know, hovercams or something in the area. I''d like to set an example to other lawbreakers. Also, can you wear something eye-catching?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 106, 'm27o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 107, 'm27s', 'What a show! The hovercams captured the whole attack. I especially enjoyed the part where that gangster cursed you before dying. This is going to make great ratings for ... um, for whatever newsfeed sent those hovercams to film it. Not that I know anything about that. Ahem.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 108, 'm27t', 'Reality HoloNet Needs You'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 109, 'm28d', 'You must help me! I''m trying to transport my niece off-planet, to save her from a criminal father. But he''s got word of my plan, and his gang intends to kidnap the poor child! Please, I must hire you to attack the hangout where they always drink, to provide a distraction so I can rescue the girl. I''ve got enough credits to pay you. Just hurry!'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 110, 'm28o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 111, 'm28s', 'We did it! The girl is safely off to an Outer Rim planet and her father''s gang is crippled. You''re a good person. I''m happy to pay this money.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 112, 'm28t', 'Save Innocent Niece'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 113, 'm29d', 'At last I''ve found you! Years ago you served my father in the Clone Wars. Now he begs you to help him in his struggle against ... what did you say? You didn''t serve my father? Oh. Well, you''ll do anyway. How''d you like to pick up a few credits by blasting apart a den of gas thieves near here?'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 114, 'm29o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 115, 'm29s', 'You did it! You don''t need to be paid, do you? I know there''s more to you than just money. Right? Oh. Well, you''ve got to follow your own path. No one can choose it for you.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 116, 'm29t', 'Break Up Gas Thieves'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 117, 'm30d', 'It''s an outrage! A crewman of mine was murdered by a gang of local cutthroats. Now they''re keeping his body for who-knows-what reason. I''m a spacer, not a fighter, but I can contract a tough guy like you to pay back those filthy gundarks! You pound them into rubble, and I''ll give you whatever I have.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 118, 'm30o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 119, 'm30s', 'You''ve honored my late crewman and rid this planet of some dangerous scum. If you decide to join a freighter crew, let me know, eh? I have an opening.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 120, 'm30t', 'Avenge My Crewman'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 121, 'm31d', 'Do I look like a simpleton to you? Then explain to me why a malodorous band of hoodlums would extort money from me. Me! Do they imagine I have no resources to pursue retaliation? On that topic, you look like you''ve killed men before. Would you like to do so again? I can give you a substantial payment upon completion.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 122, 'm31o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 123, 'm31s', 'Most splendid indeed! Despite your looks, you are a being of the highest caliber. From now on those crooks shall think twice before accosting someone of my particular refinement and resources. '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 124, 'm31t', 'Help Haughty Patron'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 125, 'm32d', 'Ever seen a golden bantha? They''re rare and spectacular creatures. I owned one until yesterday, when a band of pelt smugglers killed it for the fur. I can''t get my bantha back, but I can get retaliation. I know where they keep their contraband. I''d like to contract you to level the place. WIpe them out, all of them.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 126, 'm32o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 127, 'm32s', 'I''ll always remember the scent of that smoke lingering over the ashes of those smugglers. You''re very good, there''s no denying that. Your payment has been sent. Thanks.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 128, 'm32t', 'Stop Bantha Poachers'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 129, 'm33d', 'You! You look like you could pull the ears off a gundark. I''ve got a pile of credits waiting if you can attack a certain criminal lair and thoroughly dispose of it. They''re up to no good in there, let me assure you.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 130, 'm33o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 131, 'm33s', 'Fine job. I needed that territory cleared for my new cantina-casino, and you''ve taken care of it in the most active way. Your pay is in your account.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 132, 'm33t', 'Help the Land Developer'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 133, 'm34d', 'I''m a love junkie, I admit it! I fell in with a gang member -- I like nice eyes, what can I say? -- but I had to end it. Now the whole gang has destroyed my home and promises to "make me their droid." I need help! I''ve got money; you''ve got weapons; let''s work together. Take out the gang nest, and let me live a loving life again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 134, 'm34o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 135, 'm34s', 'Thanks, hero! That was impressive. Your credits have been transmitted. Call me sometime. I like your eyes. '),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 136, 'm34t', 'Help Lovesick Fool'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 137, 'm35d', 'I contracted with another party to carry certain cargo past Imperial checkpoints. Matters went awry, I had to dump the cargo, and now the other party is making my life very, very hard. I offer you a fair reward for going to the other party''s headquarters and removing this obstacle to my future happiness.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 138, 'm35o', ''),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 139, 'm35s', 'Thank you. I don''t see why a few dozen Imperial turbolasers were worth all this fuss, but there you are.'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 140, 'm35t', 'Take Out Spoilsports'),
('string/en/mission/mission_destroy_neutral_easy_npc_non_persistent_from_npc.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 1, 'm1d', 'This place has been going downhill ever since that Toong couple next door had one of their slaves stolen. And that was over 30 years ago. Now we have these strange looking characters wandering around the neighborhood every night. I don''t know what they do, but I''m sure they''re up to no good. They come from outside of town, sneaking into our settlement like criminals. I wish someone would get rid of them, so we can have some peace and quiet in this neighborhood. I''ve collected some credits from the people who live around me and we''re willing to pay anyone who can help keep our homes safe. \n\nElza Monimi'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 2, 'm1o', 'Elza Monimi'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 3, 'm1s', 'Thank you for your help. Although things still aren''t as good as they were in old days, it is a step in the right direction. And credits well spent as far as I am concerned.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 4, 'm1t', 'Quieting the Nosy Neighbor'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 5, 'm2d', 'While the Boonta Eve is mainly celebrated in certain parts of Mos Espa, it has become a night of mischief around here. A group of local hoodlums take it upon themselves to stir up trouble that night, stealing from the elderly and attacking anyone who dares to go outside. The group of troublemakers responsible lives outside of town. If someone would go there and put and end to their mischievous ways, the entire town would appreciate it.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 6, 'm2o', 'Outraged Citizens'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 7, 'm2s', 'We appreciate your help. Now Boonta Eve will no longer be a dreaded day.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 8, 'm2t', 'The Boonta Eve Bandits'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 9, 'm3d', 'On one of my recent "scavenging" trips over the mountains, I made such a haul that I couldn''t fit everything in my speeder. So I had to make two trips. I left a pile of spare parts and other things buried under a pile of dried brush near the peak of one of the mounatins in the Needles Range. Well, when I want back my stash was taken. Now I know complaining about someone stealing my stolen goods is pretty low, but this is how I make my living. On my last trip back there I was robbed by some thugs who I assume are the same ones who stole my stash. So I need someone to take this group out. If I can''t continue to scavenge along the Needles I might actually have to get a real job.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 10, 'm3o', 'A local scavenger needs someone to make his stomping grounds safe.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 11, 'm3s', 'You really saved my skin. I don''t know what I would have done if I had to go legit. With all the rules the Empire is imposing on us, it''s been difficult to actually make a living. And a real job would break me.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 12, 'm3t', 'Scavenger Hunt'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 13, 'm4d', 'It was almost a year ago when we planned our group expedition to the famous sights of Tatooine. We split into two smaller groups when there was a disagreement on which places we''d stop and see. There''s never enough time to do everything. Anyway, when we separated, the plan was to meet back up at the Jag Crag Gorge. When we arrived there, the other group never showed up. They were robbed one night and had to head back home. This ruined the trip for everyone. And while the local authorities never did anything about it, we''ve identified the thieves. Even though we are sure the stolen items can''t be recovered, we would like to know that this won''t happen again. '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 14, 'm4o', 'A Group of Wronged Sightseers'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 15, 'm4s', 'Thank you very much for eliminating those nasty thieves. We will continue our expeditions, now that Tatooine is a little safer.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 16, 'm4t', 'Journey From the Jag Crag Gorge'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 17, 'm5d', 'In our city lies an ancient grave site honoring Jedi Master Sidrona Diath. Sadly, the monument was senselessly defaced by a local group of Jedi haters. It was probably done to curry favor with the local Imperials. But Master Diath was a good man and a revered leader of Tatooine who fought valiantly before his fall in the Battle of Basilisk some 4,000 years ago. He also fathered Jedi Knight Dace Diath, a hero in the Sith War. And, of course, Diath was the first to speak the words "Koroght Gaghght Takt", which, for outlanders not familiar with the saying, means "blessed be your going out from us". Although the Empire probably wouldn''t agree with us, those who defaced his grave should be punished. The key members of the Tatooine Coalition for the Preservation of the Prominent Past wish to remain anonymous, in the hopes of avoiding the Empire''s wrath, but we are willing to pay a handsome sum to whoever deals with this problem.\n\nTatooine Coalition for the Preservation of the Prominent Past'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 18, 'm5o', 'Tatooine Coalition for the Preservation of the Prominent Past'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 19, 'm5s', 'The Coalition is forever grateful for your actions. And as the great Master Diath first said, "Koroght Gaghght Takt".'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 20, 'm5t', 'Defilers of an Ancient Jedi Grave'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 21, 'm6d', 'Someone has been taking water from the sacred canyons of the Tusken Raiders. It is creating unrest in one of the largest groups of Sand People in this part of Tatooine. This entire city is in jeopardy if this continues, but the local authorities seem unable, or unwilling, to do anything about it. We''ve traced the thefts to a group outside of town, but we can''t do anything about it on our own. We need a person with a particular talent to handle this situation. We don''t care how you stop them, just save our town from the wrath of those superstitious savages.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 22, 'm6o', 'A Community In Peril'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 23, 'm6s', 'You are our savior! The Tuskens would have surely overrun our little community if you hadn''t intervened. With their enemies destroyed, the Tuskens will likely move along.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 24, 'm6t', 'Who''s Been Drinking the Gafsa Water?'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 25, 'm7d', 'Gragra, a local gorgmonger, started growing gorgs and other edible amphibians in a sewer zone beneath this town decades ago. Long after she''s left this place to work elsewhere, the gorg population continues to grow. Now, these little amphibious creatures don''t do much damage down in the sewers but some of the squatters that live outside of town come here to feed on them. These squatters are known to rob and burgle the locals whenever they can. I am offering a generous reward to anyone who stops these squatters from invading our city. No questions asked.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 26, 'm7o', 'A Piqued Local Denizen'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 27, 'm7s', 'I appreciate your help in this matter. The entire city will benefit from your work. And I would also appreciate if you would keep quiet about your mission to kill the squatters.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 28, 'm7t', 'Evict the Gorg Eaters'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 29, 'm8d', 'There''s this clan of Sand People... Well, I''m not sure that they''re actually Sand People, but someone''s been terrorizing travelers who come and go from town. I''ve only heard stories, but I do know what they call themselves: the clan of Grk''kkrs''ar. I did some research on the term and it''s actually the name of a mythic Tusken who never showed fear, even when facing a krayt dragon. Now my family is coming to visit from the far side of Tatooine and I don''t want these Tuskens, or whatever they are, attacking my relatives. Please help me! But be careful. They sound dangerous...'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 30, 'm8o', 'A Concerned Tatooine Citizen'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 31, 'm8s', 'Praise the maker! You''ve saved my family!'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 32, 'm8t', 'The Clan of Grk''kkrs''ar.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 33, 'm9d', 'Now, it''s not much of a business, but I am able to feed my family off the credits I make selling necklaces made from small snippets of japor. Last week some thieves took all of my necklaces as well as my carving tools. Without these things my family will starve. I have a few credits, but not enough to buy all those tools again. And the necklaces they took represent several weeks of work. I need someone to help me. I don''t expect you to return all these things to me. I just want someone to clear out the thieves and I''ll go back to their camp and reclaim my goods, as well as anything else I can find. I am willing to pay a fairly good sum for this work.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 34, 'm9o', 'A Local Japor Carver'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 35, 'm9s', 'Thank you, friend. I would offer you a necklace in addition to your payment but I can''t spare one right now. Just know that my family, and my business, are thriving again.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 36, 'm9t', 'Japor Thieves'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 37, 'm10d', 'Things aren''t like they were back when I was kid running around the streets of Mos Espa. Friends would stand by you, and Tatooine was on its own. No Republic or Empire or whatever telling everyone what to do. Now we live in a military state. Podracing is dead. There are military garrisons everywhere you look, and Jabba''s associates bring the worst kind of scum to this planet. I always thought I''d get out of here some day, but I don''t think that will ever happen now. Still, I would sleep better at night if a certain group of scavengers living outside of town were taken out. I can''t tell you what they did, but I do have plenty of credits to pay anyone who is willing to take them out. Bring me proof that they are bantha fodder and the credits are yours.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 38, 'm10o', 'Melee of Mos Espa'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 39, 'm10s', 'Thank you. I hope those scum suffered...'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 40, 'm10t', 'Melee''s Drama'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 41, 'm11d', 'When I was a young man, my life was dedicated to protecting those who couldn''t defend themselves. I spent most of my time defending the peaceful Jawas. They are too small to fight their own battles, I fear. They are constantly threatened by gangs of roving bandits, or worse. Well, I may be too old to actually pick up a blaster rifle or vibroax to battle those who would threaten the defenseless little desert wanderers, but I''m not too crippled to at least go out check on the Jawas. I spotted some thugs moving in on the chatter-boxes. I''m worried the Jawas are about to get killed. Go out stop these advancing trouble-makers, and I''ll pay you for your trouble.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 42, 'm11o', 'An Altruistic Citizen'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 43, 'm11s', 'The Jawas are safe, for now. Although the little chatter-boxes would never thank you themselves (I don''t even think that they realized they were in any danger), I do extend my gratitude (and a few credits) your way. I admit, I''m old and cynical, but you''ve shown me that there are still heroes left in the galaxy. '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 44, 'm11t', 'Jawa Defender'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 45, 'm12d', 'WANTED: Adventurers to brave the deserts of Tatooine in search of villainous scum! \n\nInterested parties should have: some competence with a blaster, vibroblade, or other weapon; a willingness to travel the dangerous Tatooine wastes; and unflagging courage! Those who accept this mission will receive coordinates to the last known location of one of Tatooine''s many roving bands of thugs or miscreants. Using these coordinates, the willing adventurer will be required to destroy any criminal encampments.  '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 46, 'm12o', 'Mos Eisley Police Authority'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 47, 'm12s', 'We''ve received confirmation of your mission''s success. Good work. Your payment has been transferred.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 48, 'm12t', 'Adventurers Wanted'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 49, 'm13d', 'WANTED: Mercenaries willing to risk their lives for lucrative rewards.\n\nWe are seeking mercenaries capable of confronting Tatooine''s many thugs, thieves, hoodlums, and swoop gangsters. Those who accept this mission must supply their own weaponry and other equipment. Upon acceptance, the Mos Eisley Police Authority will transmit the coordinates of a known criminal encampment. This camp must be completely destroyed. Risks are high, but rewards are fair. '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 50, 'm13o', 'Mos Eisley Police Authority'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 51, 'm13s', 'We''ve received confirmation of your mission''s success. Good work. Your payment has been transferred.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 52, 'm13t', 'Mercenaries Wanted'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 53, 'm14d', 'May the Force be with us! TASKForce Tatooine is committed to fighting evil wherever it appears! As any galactic citizen will understand, Tatooine is overrun by a nearly-unstoppable criminal element. The thieves and killers spread like a virus across the desert. But agents of TASKForce Tatooine tirelessly locate these infections wherever they occur. We then hire competent soldiers to eliminate these dangerous dens and hidden lairs. Those willing to assist TASKForce Tatooine will be given coordinates to an identified criminal base. Once that base is destroyed, we will gladly transmit a sizable reward. '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 54, 'm14o', 'TASKForce Tatooine '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 55, 'm14s', 'The Force was with you! Congratulations on wiping out those miscreants. Tatooine is much safer now, and we can begin searching for the next criminal target. A reward has been transmitted to your account.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 56, 'm14t', 'TASKForce Agent'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 57, 'm15d', 'Hello. I hope this transmitter is working right... Hopefully, this plea for help has reached the local mission terminals. If you''re reading this, then I suppose I did something right... I''ll keep this simple: We''re a hardworking folk, but not very good with blasters or vibroweapons. Our lands are threatened by greedy, well-armed squatters. We need someone to step forward and help defend us. Please, accept this mission and move in on the murderers before they can close in us! We''ll provide coordinates to their hideout; you just have to provide the blaster fire.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 58, 'm15o', 'A Local Moisture Farmer'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 59, 'm15s', 'Hello again. I wish to thank you for killing those murderous squatters. I''ve dug up some credits and will transfer them to your account immediately.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 60, 'm15t', 'Squatters'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 61, 'm16d', 'Jabba the Hutt is seeking brave warriors who wish to prove themselves in battle against the Hutt''s many enemies! Jabba is constantly tracking his foes, who plot his downfall, attempt to steal his goods, and ambush his loyal troops. Jabba is enraged and sickened by his enemies, and wishes to see them all killed. Our intrepid scouts have located a band of Jabba''s most-hated enemies in the desert. Any who accept this mission must go forth and stamp out this threat to Jabba''s wealth and happiness. Those who succeed will earn a handful of credits, and Jabba''s gratitude.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 62, 'm16o', 'Bib Fortuna, on behalf of Jabba the Hutt'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 63, 'm16s', 'I admit that I am surprised by your success. You have dealt with Jabba the Hutt''s enemies, and you have fought bravely. I have slipped a few credits from Jabba''s vaults in order to repay you for your services. If you are fortunate, Jabba will let you keep your credits... '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 64, 'm16t', 'Crime War'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 65, 'm17d', 'Transmission Translated from Jawaese for your convenience!\n\nWe Jawas are threatened by nasty, murderous humans and aliens, who kill us with wicked, sharp blades and fiery blasters. They hunt us across the sands, leave our bodies burning on the dunes. We need brave, bold heroes to stop these evil, dangerous thugs! Accept this quest and we will send you a radiant, glowing beacon that you can follow to our enemies! When you destroy their base, we will pay you many glorious credits. \n\nWimateeka, Jawa Clan Leader'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 66, 'm17l', 'Jawas are threatened by local thugs.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 67, 'm17o', 'Wimateeka'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 68, 'm17s', 'Transmission Translated from Jawaese for your convenience!\n\nMost exalted hero of the Jawas! Thank you a hundred times for saving us from evil, murderous thugs. We will now pay you a sizable, big reward.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 69, 'm17t', 'Jawa Killers'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 70, 'm18d', 'Nothing is more important than family. Last season, my son was killed by thugs. He was just heading out to Anchorhead for some power converters and other supplies when he was ambushed by the murderous scum. They left him to rot in the desert. I reported the murder to the Imperial authorities in Bestine, but they said they couldn''t find the killers. I doubt they even looked. It only took me two days to find the band of thieves who blasted my son. Now, all I want is revenge. I''m offering a reward to anyone who can avenge my son. But I won''t be happy with just a few dead murderers; I want their entire camp burned to the ground.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 71, 'm18o', 'A Heartsick Father'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 72, 'm18s', 'You have my heartfelt and undying gratitude. And my son, wherever he is, thanks you as well. Those murderers are dead, and they will never hurt another innocent traveler. The credits I give you as a reward will never be thanks enough for all you have done, for my family and this planet.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 73, 'm18t', 'Avenger'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 74, 'm19d', 'A group of local roughnecks have been causing a lot of trouble in and around Anchorhead. They tear through town, kicking up dust and scaring away the honest farmers. They''ve even started stealing droids and shaking down the locals for "protection fees." When some of my hired hands confronted these dirtbags, the roughnecks nearly beat them to death. It''s only a matter of time before they kill someone... So, I followed these bums to their hideout in the desert. Anyone who wants a few credits can saddle up and take care of the roughnecks. '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 75, 'm19o', 'Fixer'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 76, 'm19s', 'Nice work, friend. Those roughnecks won''t be bothering us again. And just in time, too; some of the old-timers here were ready to go to Jabba for help, and that would have only put us into in his debt. I''d much rather pay you a few credits than owe that slug my life.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 77, 'm19t', 'Roughnecks'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 78, 'm20d', 'My employer, the All-Powerful Jabba the Hutt, has been implored to come to the aid of the citizens of Anchorhead. It appears that these simpering, unarmed farmers are being harassed by a gang of violent roughnecks. Jabba''s generosity knows no bounds, and he has decided to aid this group. For a price, of course. In fact, partial ownership of Anchorhead, it seems. To help these poor, unfortunate fools (and gain a foothold in Anchorhead), Jabba is hiring mercenaries. Any hired thugs, trained or untrained, are welcome to accept this mission. Upon doing so, you will receive coordinates to the lair of Jabba''s new enemies. Simply eliminate these ruffians and destroy their base to earn Jabba''s gratitude.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 79, 'm20o', 'Bib Fortuna, on behalf of Jabba the Hutt'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 80, 'm20s', 'I must admit, I am surprised that you succeeded in your mission. I''m sure Jabba will be pleased, when I find the time to tell him of your victory. For now, be content with the handful of credits I''ve generously transferred into your account.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 81, 'm20t', 'Jabba''s Ploy'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 82, 'm21d', 'I''ve recently purchased a large plot of land on Tatooine, but when I sent agents to investigate the territory, they discovered it was staked out by some squatters. The dirty locals became violent when my agents tried to drive them from my land. I acquired a bit of the desert legally, I assure you, and now I want those squatters evicted. Accept this mission, destroy the squatters'' shack, and you''ll be promptly paid.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 83, 'm21o', 'A Corellian Businessman'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 84, 'm21s', 'Good work, my loyal agent. I will now be able to build what I hope will become one of the galaxy''s most lucrative mines on Tatooine. For your role in helping me to create my empire, I have rewarded you a fair sum.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 85, 'm21t', 'The Landlord'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 86, 'm22d', 'TRANSMISSION TRANSLATED FROM HUTTESE\n\nAs you probably know by now, Watto the Toydarian, owner of the once-legendary Watto''s Junkshop and Spare Parts in Mos Espa, has fallen on hard times. Ever since he lost his fortune betting against a Jedi in the Boonta Eve Podraces, Watto has been deep in debt with just about everyone on Tatooine, including Jabba the Hutt.\n\nI''ve known Watto all my life and I''m trying to help him out. He''s not the friendliest gasgut, but he''s practically an institution in Mos Espa. And maybe I feel a little responsible for Watto''s plight, since it was my friend Anakin who won the Boonta Eve that year and left Watto without a credit to his name. Or maybe I''m just hoping that Watto will eventually give me the junkshop...\n\nWhen I heard that the Imperials were offering rewards to adventurers willing to track down and defeat some local thugs, I figured we could earn some quick credits by taking out these criminals. But Watto always wants to be the middle-man. He''s identified some of the easiest targets the Imperials have to offer and has personally guaranteed that the criminals in question will be eliminated. Now, he just needs to hire adventurers like you to kill these thugs. We''ll pay you the reward, after Watto takes his "commission" of course. It''s not a perfect set-up, but I can guarantee that Watto has selected only the best assignments. And, by dealing with Watto directly, you avoid any Imperial entanglements...  '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 87, 'm22l', 'Watto the Toydarian is hiring sub-contractors to complete Imperial missions.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 88, 'm22o', 'Wald'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 89, 'm22s', 'TRANSMISSION TRANSLATED FROM HUTTESE\n\nThings don''t look so grim around Watto''s shop these days. Surprisingly, his sub-contracting scheme seems to be working, thanks in part to you. Even after paying you your reward, Watto has enough left over to upgrade his inventory and attract new customers. And, because he''s proven to be so reliable, Watto is gaining quite a reputation with the Imperials. They''re even starting to buy parts from the junkshop.\n\nAs one of Watto''s sub-contractors, you''ve been paid for your services. Please note that, while Watto did deduct his standard commission, I threw in a few credits of my own to thank you for a job well done.\n'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 90, 'm22t', 'Toydarian Middleman'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 91, 'm23d', 'The Tatooine Reclamation Society is a coalition that includes Bestine, Mos Espa, and several other major cities on Tatooine that have joined forces with generous Imperial authorities to improve life on our desert planet. As part of the Tatooine Reclamation Project, the Tatooine Reclamation Society is planning to construct waystations between the planet''s primary settlements. Unfortunately, the proposed sites of some planned waystations have already been "settled" by bandits, thieves, squatters, and other undesirables. The Tatooine Reclamation Society is broadcasting the coordinates of these illegal settlements in the hopes that loyal Tatooine citizens will take it upon themselves to aid the Reclamation Project by destroying these "obstacles." A suitable reward will be offered to anyone who helps in our efforts to develop these essential waystations.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 92, 'm23o', 'Tatooine Reclamation Society'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 93, 'm23s', 'The Tatooine Reclamation Society is pleased to report that Phase I of our proposed waystation project is nearly complete! Criminal settlements previously blocking construction on these proposed waystations have been eliminated. Those citizens directly responsible for the destruction of these bases, hideouts, and camps have been rewarded and deserve the thanks of the entire planet!\n\nPhase II of the project - the actual construction of the waystations themselves - requires additional funding. We have been promised a substantial grant from the local Imperial prefect, but a recent military mishap near Yavin IV has evidently diverted all Imperial credits for the forseeable future. The Tatooine Reclamation Society is seeking other backers, including the generous Jabba the Hutt. We believe that the waystation project will be back on track within a few seasons! '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 94, 'm23t', 'Waystation Project'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 95, 'm24d', 'We, the Dim-U monks of Tatooine, who worship at the hairy feet of the Mighty Bantha, are seeking defenders of our hirsute idol. While Tatooine should be the domain of the bantha alone, the Horned-One must share the planet with a host of lesser beings. Most recently, the Revered Bantha has been plagued by foul thugs, dirty criminals, and murderous hunters. These bipedal vermin badger the Wandering Bantha, or kidnap His children, or even kill Him in the hopes of hanging his lush coat on their walls. The coffers of the Dim-U monastery are full, ready to serve the cause of the Enduring Bantha, in whose eyes all Universal Truths are revealed. We only await a champion to step forward and purge the Stalwart Bantha''s enemies!'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 96, 'm24o', 'Dim-U Monks of Tatooine'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 97, 'm24s', 'The Mighty Bantha, the legendary Horned-One who brings peace and tranquility to all who gaze upon Him, is safe once again! You have served the Enduring Bantha well! The Dim-U monks, loyal servants of the Wandering Bantha, are overjoyed at your success. Our coffers have been opened and you will be rewarded. The Dim-U monastery thanks you on behalf of the Horned-One, whose powerful bellow will roar your name across the desert and throughout the start so that all who worship at His hairy feet will know of your heroic deeds.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 98, 'm24t', 'Bantha Defender'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 99, 'm25d', 'The Tatooine Civilian Defense League has detected an alarming rise in the number assaults, petty thefts, and acts of vandalism in and around the habitable areas of the planet. These crimes are the work of several small bands of roving thugs. In the hopes of reducing the crime rate on Tatooine, the Tatooine Civilian Defense League is authorized to pay for the destruction of all identified criminal camps.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 100, 'm25o', 'Tatooine Civilian Defense League'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 101, 'm25s', 'Excellent work! Unlike most of our hired agents, you''ve actually succeeded in defeating those criminals who enjoy terrorizing Tatooine locals. Your reward has already been transferred to your account.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 102, 'm25t', 'Criminal Element'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 103, 'm26d', 'Swoop gangs are a terrible menace on Tatooine! They race all over the planet, outrunning the law and attacking anyone they come across. But I''ve come up with a plan to cull these criminals. When traveling together, swoop gangsters are like a pack of slice-hounds. They gain confidence from just being around one another, and easily overwhelm the weak or defenseless. But when caught one-on-one, or in small groups, the swoopers aren''t very tough. I''ve located some smaller swooper camps. Anyone who wants to prevent the swoop gangs from taking over Tatooine should sign up here! I''ll transmit coordinates to a manageable hideout, and you just take care of the rest.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 104, 'm26o', 'Swoop Hunters'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 105, 'm26s', 'I told you the swoop gangsters weren''t so tough, especially when they''re caught in small groups. Nice work taking out that base. Now, there are fewer thugs to harass the locals.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 106, 'm26t', 'Concerned Citizen Hiring Adventurers to Battle Swoop Gangs'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 107, 'm27d', 'Listen up, worms. I''m a leadin'' member of one of Tatooine''s most feared and respected swoop gangs. I''m not gonna say which swoop gang, because we don''t need no trouble with the Imperials. But I have a sweet deal for anyone with a blaster and an itchy trigger finger. It''s no secret the swoop gangs on Tatooine are at war. There''s a rival gang moving in on my territory, and I want to give those scurvy mynocks a surprise. Rather than send my gang out to take care of ''em, I figure I''ll offer some of you "adventurers" a chance to even the score for me. They''ll be watchin'' out for dust-blowing swoops, but a solo operator or small group of mercenaries can get in close and take out their base. I can send you one of them glowing waypoints; just follow it and attack any chuba-eating scum you find. Then burn their camp to the ground, to send a message.  '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 108, 'm27o', '"Captain Crossbones"'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 109, 'm27s', 'Hah! I knew my plan would work! Those sandmite-infested fools have been watching me and my gang for weeks, but they didn''t have an eye on you, my friend! I haven''t seen such a one-sided fight since crazy old Ben took off that Walrusman''s arm in the Mos Eisley cantina. I''ve sent some loot your way. Spend it while you can; I won''t be surprised if those swoopers retaliate... '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 110, 'm27t', 'Turf War'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 111, 'm28d', 'My brother was killed by a swooper the other day. The murderers will get away with this terrible crime if someone doesn''t step forward and wipe them out. I''m not a vigilante, but I''m looking for someone willing to deliver a little desert justice to these vermin.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 112, 'm28o', 'A Bereaved Local'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 113, 'm28s', 'By the shifting sands of Tatooine, may my brother always remain in the memories of those who loved him. And may your heroic deeds on his behalf always be part of our family history. I shall never forget that you brought my brother''s murderers to justice. Thank you.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 114, 'm28t', 'Vigilante'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 115, 'm29d', 'WANTED: Able-bodied adventurers to battle roving swoop gangs on Tatooine! \n\nTatooine''s swoop gangs are out of control! They''ve become a public menace. Tatooine authorities are willing to pay large rewards for the elimination of this threat. Those willing to accept this dangerous assignment will receive coordinates to a known swoop gang camp. The camp must be destroyed before any rewards will be processed.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 116, 'm29o', 'Mos Eisley Police Authority'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 117, 'm29s', 'We''ve received confirmation of your mission''s success. Good work. Your payment has been transferred.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 118, 'm29t', 'Swoop Gang Cleanup'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 119, 'm30d', 'The name''s Dengar. You''ve probably heard of me. I was the best swoop racer in the entire galaxy. No one could catch me. And I had a loyal gang watching my back. The past, it''s all a bit hazy now... But I know some Corellian punk ambushed me in the Agrilat Swamps on Corellia. The crash ruined my career. The Empire fixed me up right, and I''m good at killin'' now. But my old gang scattered. Treacherous space slugs, they left me for dead. Joined up with another swoop gang on Tatooine. No one leaves Dengar behind. No one. I know where the scurriers are hiding, but I''m still property of the Empire. Got a job to do. I need someone tough and mean to take out my old crew. I''ll send the coordinates when you accept this mission.  '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 120, 'm30o', 'Dengar'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 121, 'm30s', 'You''re quite the killer. Maybe you should consider getting'' fixed up by the Empire. The Imperial cutters ripped out part of my brain and replaced it with tech. I sometimes see things, hallucinate, but I''m one of the highest-paid assassins in the Outer Rim, so I ain''t complainin''. Maybe you should take the credits you just earned and have a little work done too.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 122, 'm30t', 'Old Friends'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 123, 'm31d', 'For years, an unruly band of Tusken Raiders has lived on the Mochot Steep, venturing out now and again to cause trouble around town, but never really doing any major damage. Until now. There''s another group of troublemakers that has been battling the Tuskens for supremacy of the Mochot Steep. This has stirred up major trouble. The Tuskens are out scavenging almost every night, trying to prepare themselves for the next attack. The local merchants have been suffering greatly from this little war. Now, we don''t think that the Tuskens will ever leave the Mochot Steep, which is fine with us. We just need someone to stop those new bandits from stirring up the Tuskens. Can you aid us?'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 124, 'm31o', 'Concerned Local Merchants'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 125, 'm31s', 'Congratulations! You have done the locals a great service. The Tuskens should go back to their normal behaviour and leave us alone now.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 126, 'm31t', 'Steep Struggle');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 127, 'm32d', 'Hundreds of years ago, a former employee of the Tatooine Bureau of Ethnicity and Socialization named Alkhara allied himself with a savage group of Tusken Raiders and destroyed an entire police garrison. It started a bloody feud with the Tusken Raiders that lasted for many years. He built himself a small empire and after he died his headquarters became Jabba''s Palace. While his terrible reign was ended many years ago, there are still pockets of those who believe in the anarchy that Alkhara preached. We at the Bureau would like all memory of Alkhara to be erased. We are offering a substantial reward for the removal of any known camps or bases belonging to Alkhara''s followers.\n\nTatooine Bureau of Ethnicity and Socialization  '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 128, 'm32o', 'Tatooine Bureau of Ethnicity and Socialization'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 129, 'm32s', 'The Tatooine Bureau of Ethnicity and Socialization would like to thank you for your assistance in helping to remove Alkhara from the memory of the citizens of Tatooine.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 130, 'm32t', 'Followers of Alkhara'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 131, 'm33d', 'This may not mean anything to you, but it means the world to me. I had my entire trugut collection stolen by a group of bandits. They have no idea what it''s worth and will probably just give it away for a few creds. For those who don''t know, the trugut is a Hutt form of currency that only had value on Hutt-controlled worlds. But the use of truguts on Tatooine ended with the arrival of the Empire. In the day, one trugut was worth sixteen wuipiupi, a quarter of a peggat, or ten dataries. But now, to the right collector, they are worth ten times that. I would like someone to take care of these thieves for me. They don''t deserve to hold such a rare and exquisite collection.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 132, 'm33o', 'A Collector of Rare Coins'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 133, 'm33s', 'I hope those vile sith spawns know that they paid dearly for robbing an old man. Thank you for help.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 134, 'm33t', 'Coin Collectors'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 135, 'm34d', 'This may sound strange coming from me, since I''ve no love for droids, but I need some help putting a friend of mine back together. You see, me and Ceetoo-Arfour have been making specialty drinks for a months now, and making good money all over Tatooine doing it. But recently some blasted bandits looted my hovel and trashed the place. Worst of all, they stole Ceetoo''s special mixology circuit board. I had pulled the board out to clean it, and then left it out to dry. Must have looked like an important piece of data to them, and the scum snapped it up along with some other personal belongings. Now I don''t expect you to bring back my stolen goods, but if you could take care of the sand-eating creeps that did this to me, I''ll search through the rubble and find the pieces to put Ceetoo-Arfour back together again.\n\nWuher'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 136, 'm34o', 'Wuher'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 137, 'm34s', 'Now I can go retrieve that blasted board and get this lazy bucket of bolts back to work on our latest concoction. I''d offer you a free drink, but we haven''t mastered the latest recipe yet.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 138, 'm34t', 'Wuher''s Droid Dliemma'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 139, 'm35d', 'A group of punks got me fired from my gig as the front desk clerk at the Lucky Despot hotel. I want it back. And the only way that''s going to happen is if this group of low-life bandits is never seen or heard from again. Got it?\n\nAnton '),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 140, 'm35o', 'Anton'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 141, 'm35s', 'Excellent. Now I can prove myself worthy to my old boss. I''m certain I''ll get my old job back.'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 142, 'm35t', 'Anton''s Big Break'),
('string/en/mission/mission_destroy_neutral_easy_npc_tatooine.stf', 143, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 1, 'm1d', 'We''re familiar with animal cunning, and we''ve even encountered beasts that seemed to possess almost true sentience, but these monsters are something out of a nightmare. We have no idea why they began attacking the local communities or how they choose their particular victims. All we know is that they seem to sense who is armed and attack those individuals first. These beasts also seem to sense our surveillance droids and have managed to elude them. We have, however, identified an area these creatures inhabit at least part of the time. Eliminating these predators will not be easy. A generous reward awaits the team of hunters that can pull this off.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 2, 'm1o', 'Planetary Parks & Wildlife Authority'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 3, 'm1s', 'You have both our gratitude and that of the surrounding communities. These creatures had to be stopped. Good work.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 4, 'm1t', 'Stop the Terrifying Hunters'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 5, 'm2d', 'Salutations. I am Threedee, an administrative droid in the service of an influential and wealthy patron. My master''s hobby is recording the exploits of hunters that he hires to stalk and eliminate dangerous predators. Ever eager to move onto bigger and better challenges, my master feels that the accomplishments of the small game hunters he had been employing are no longer sufficient for his purposes. He has therefore instructed me to search for experienced big game hunters to tackle far more dangerous prey. I have pre-selected locations known to contain some of the most dangerous predators in the galaxy. Expect surveillance droids in the area. They are there to record your activities. As per the standard contract, my master claims ownership to all the images produced from these hunts and will reserve the right to alter them in any way he sees fit. Thank you for your time. '),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 6, 'm2o', 'A Truly Great Hunter'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 7, 'm2s', 'Bravo. An excellent job. Your payment has been transmitted to your account.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 8, 'm2t', 'Assist Famous Big Game Hunter'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 9, 'm3d', 'As a Trandoshan, it is my duty to collect jagannath points by hunting dangerous prey. The problem, however, is that I''m a colossal coward. It''s only been due to the enormous wealth my father managed to accumulate during the enslavement of the Wookiees that I''ve been able to bribe my way through every single rite of passage sacred to my people. This one, unfortunately, is proving to be a bit tougher. Without sufficient jagannath points, I won''t be able to return to my homeworld and start a family ("clutch mothers" can be so picky). I''ll therefore pay a very generous reward to any hunters out there who are willing to score some jagannath points for me. I''ll provide the locations of some of the most terrifying beasts in the galaxy (our goddess the Scorekeeper demands the very best from her hunters, after all). You go in there and blast them to bits, and I''ll take the credit for it (and pay you to keep silent). Sound like a deal?'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 10, 'm3o', 'An Anonymous Trandoshan'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 11, 'm3s', 'Most excellent. Please see me again in the future. Our goddess is the greedy sort when it comes to jagannath points.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 12, 'm3t', 'Help a Cowardly Trandoshan'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 13, 'm4d', 'Illustrious Jabba would like to hire enterprising hunters to clear certain areas of dangerous wild predators. Mighty Jabba wants to make certain these areas are more attractive to his business partners and associates -- the last thing a smuggler needs to worry about is being eaten by some random vicious monster. My lord offers generous rewards for such services, but he expects results. If hunters should come across any young rancors or krayt dragons, however, Jabba will gladly pay an additional sum in exchange for the living cubs. Good luck.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 14, 'm4o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 15, 'm4s', 'Well done. You serve my master well, and you shall be rewarded. I hope you will continue to seek employment with our organization.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 16, 'm4t', 'Make World Safe For Smugglers'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 17, 'm5d', 'That slime-sucking overgrown worm, Jabba, will try anything to drive his competitors away. It''s well known that the Hutt loves collecting dangerous predators (I hear he has a thing for rancors). Apparently he''s been hiring hunters to capture some of the most lethal beasts this galaxy has to offer. He keeps some for this own amusement. The rest he has transported to systems where his rivals are known to operate and drops the creatures (often a pack or several mated pairs) near rival bases. Very funny, you huge pile of Sith spit! Well Jabba is not the only one that can hire hunters. Feel like tackling some very ferocious creatures? The pay is quite good and you can keep any critters you can catch alive and do with them whatever you wish. This situation needs immediate attention, however, as we''re losing good operatives and lots of business. '),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 18, 'm5o', 'Lady Valarian'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 19, 'm5s', 'Business will soon be back on track. Good hunting there, friend. You must do this sort of thing for a living.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 20, 'm5t', 'Creature Assassins'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 21, 'm6d', 'Due to the nature of our business, which usually involves establishing landing bays and storage facilities in remote areas of the galaxy, our operatives are at risk from wild predators. We must occasionally hire professional hunters. As these are more specialized agents than we''re used to dealing with, we are prepared to increase our standard "problem-solving" fee. Fortunately, we''ve managed to track most of these lairs already so the job calls for extermination only.    '),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 22, 'm6o', 'Black Sun'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 23, 'm6s', 'Effective, agent, most effective. Do look us up again in the future.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 24, 'm6t', 'Protect Scoundrels'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 25, 'm7d', 'Some nerfs that had been infected with an experimental virus were accidentally released into the wild instead of being destroyed. We tracked down all the possible locations where these diseased animals might have ended up and performed extensive surveillance of those areas. Any nerfs discovered in those locations were vaporized. Some areas, however, also contained various dangerous predators but no nerfs. We cannot risk this virus spreading, so we must wipe out these predators on the off chance that they devoured infected nerfs. Worry not, the virus is harmless to most sentient species. Can you help the Empire keep its citizens safe?    '),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 26, 'm7o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 27, 'm7s', 'Well done. You might want to have yourself checked by a medical droid just in case. If it detects any signs of advanced cellular decomposition, please contact the nearest branch of Imperial Intelligence.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 28, 'm7t', 'Kill Diseased Predators'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 29, 'm8d', 'The Geonosian petrana-ki gladiator arenas certainly left their mark on the galaxy. After the Fall of the Old Republic, many predators destined for Geonosis ended up spread throughout the Outer Rim and even in many Core Systems. Most of these beasts died out on their own or were hunted by the locals, but a few have survived here and there. We''ll pay experienced hunters to visit the systems where some of these beasts survived and wipe them out. In many cases, you''ll be doing that system''s ecology a huge favor as many of those creatures should never have made it to those systems. Our pay is good and the experience will no doubt give you something to talk about for years to come. We hope you can help us. '),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 30, 'm8o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 31, 'm8s', 'We are most impressed, agent. Have you considered joining our organization?'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 32, 'm8t', 'Clean Up Geonosian Mess'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 33, 'm9d', 'Mighty Jabba has learned that rivals are copying his practice of breeding dangerous predators. Unlike Lord Jabba, these upstarts have established breeding colonies in the wild. How presumptuous and arrogant! My lord will not ignore this insult. He has instructed me to hire professionals hunters to destroy these breeding colonies and teach his rivals an important lesson: No one does anything better than the powerful Jabba! Leave those lairs completely uninhabitable. Not even the predators'' fleas should survive. Report to us soon. '),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 34, 'm9o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 35, 'm9s', 'Excellently done. My lord will be pleased to hear of your success. Seek us out again in the future.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 36, 'm9t', 'Dispatch Breeding Colonies'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 37, 'm10d', 'I''m conducting research for my latest article, entitled "The Superiority of Sentience: Nature''s Deadliest Weapon," and I am in need of further case studies. Specifically, I need a single courageous individual to face some of the galaxy''s most dangerous predators, armed only with simple vibro weapons and/or primitive slug-throwers. I will provide the locations of these creature lairs and will also dispatch hovercams to record the duels. If my theory is correct, then in eight out of ten encounters, the sentient hunter will emerge victorious. My grant allows me to offer reasonable compensation to individuals who participate in these studies. I hope you decide to further the cause of science.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 38, 'm10o', 'Chief Scientist K''ar Zah of the Imperial Academy of Science & Methodology'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 39, 'm10s', 'Excellent! The cause of science is served! Now, you did only use vibro weapons and simple slug-throwers, right?'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 40, 'm10t', 'Serve Cause of Science'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 41, 'm11d', 'I''m always on the lookout for fresh talent, especially future bodyguards. I''m willing to test and reward ambitious rogues who think they have what it takes to join our organization. I give you coordinates; you go to those coordinates and blast every creature there to atoms. Sound easy? Well, it won''t be, trust me. I wouldn''t even consider hiring a bodyguard who couldn''t take on a nest of wild gundarks with a stuttering vibrodagger and a broken leg. My advice is to pack your heaviest weapons and carry plenty of ammo. Oh, and bring friends. Lots of them. If you survive, we''ll talk again.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 42, 'm11o', 'Black Sun: Vigo Green'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 43, 'm11s', 'Not bad, my friend. Here''s a little something to encourage you to try future trials. Look me up again if you''re craving a challenge.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 44, 'm11t', 'Impress a Vigo'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 45, 'm12d', 'Right! You Sith-spit upstarts think you''re so unstoppable? Is that what you think, Madam "Look look, I''m piloting an Imperial walker," Master "I helped blow up the Death Star"? I''m here to tell you, nothing in your shallow experience compares to the ferocity, the sheer appalling nightmare of the Periodic Overland Migration! Oh, it may LOOK harmless. A few million dull-witted herbivores milling over the landscape from their pointless origin to their futile destination, what''s the harm? But the predators, you lackwit, the predators! Hundreds of them, stalking the herd, dining well, now and then stopping for a quick bite of Sentient Galactic Citizen. Now, NOW you see the problem. Well then! We''re hiring experienced strike teams to go out and kill the predators, a pack at a time. Payment on success. Well, what are you waiting for, you retarded excuses for thinking beings?'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 46, 'm12o', 'Colonel Ondon Kleero of the Aqualish Regulars'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 47, 'm12s', 'All right, don''t expect a bleeding Citizens'' Day Parade just for taking out point-oh-oh-one percent of this onslaught. Take your fee and make yourself useful. Somewhere else, I mean.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 48, 'm12t', 'The Blasted Overland Migration!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 49, 'm13d', 'The Periodic Overland Migration is a wondrous spectacle, as teeming herds of gentle animals troupe across the beautiful landscape. More important, the Migration is a superior tourist attraction, generating significant revenue for the local economy. However, large packs of predators follow the herd. These packs often range into settled territory, with unfortunate effects on local property values. During this current MIgration, the Safe Night Community Association is contracting with experienced teams of hunters to cull the predators in our vicinity. Payment is awarded on proof of termination of a large pack. Serious inquiries only, please.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 50, 'm13o', 'Safe Night Community Association'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 51, 'm13s', 'We appreciate your successful effort and herewith tender the agreed payment. In case you ever plan to relocate to this area, many attractive homes in our community are unexpectedly still available.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 52, 'm13t', 'Overland Migration Endangers Local Town'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 53, 'm14d', 'The Periodic Overland Migration is an irregular large-scale movement of local herbivores between widely separated feeding grounds. Predators follow the herd in unusually large numbers. Due to recent settlement of the area, these predators are unfortunately starting to present a danger to sentients. Our research suggests that if one pack makes a successful attack on sentients, other packs converge and adopt the practice opportunistically. Ergo, our Office of Biosphere Control and Repurposing is now contracting with experienced strike teams to cull designated packs in high-threat areas. Report successful culls to Deputy Associate Operations Director.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 54, 'm14o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 55, 'm14s', 'Payment for successful culling attached. Address comments to Deputy Associate Operations Director.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 56, 'm14t', 'Overland Migration Predator Culling Contract'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 57, 'm15d', 'Hey there! I''m a field producer for the HoloNet program "Wild, Wild Galaxy" back on Coruscant. We''re doing a short segment on the local Periodic Overland Migration for next season, and we want recordings of groups of seasoned hunters defending settlements. You know, "Heroically they drive back the onslaught of predators drawn by the scent of sentient blood!" We''ve located a very attractive pack at these coordinates, and our hovercams will be viewing you remotely at telescopic range. Strike noble poses, look good, make it all look perilous (which shouldn''t be hard). Check in once you''re done. Great, looking forward to working with you.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 58, 'm15o', 'Morn Meebler, HoloNet Broadcasting Service'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 59, 'm15s', 'Great, great footage. It''s an honor and a privilege to work with such outstanding talent. By the way, accepting this payment constitutes a binding release for HoloNet to broadcast this recording now and forevermore.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 60, 'm15t', 'HoloNet Show on Overland Migration'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 61, 'm16d', 'Greetings. My master, Captain Brandell Mantracor of the Imperial Navy (Retired), has ordered me to locate a team of experienced hunters capable of removing a pack of wild beasts that endangers his country estate. These predators -- I''m afraid no one has told me their species -- are following the Periodic Overland Migration, and are ranging unsettlingly close to Captain Mantracor''s prized greenhouses. The entire family is upset, and I may add that the serving staff faces possible deadly peril. The sooner you can arrange a team to eradicate this animal menace, the sooner I shall pay you Captain Mantracor''s generous reward.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 62, 'm16o', 'A C-9PO Protocol Droid'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 63, 'm16s', 'Splendid! I shall inform my master. Please accept this payment with my master''s provisional gratitude. Oh, happy news!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 64, 'm16t', 'Overland Migration Menaces Mantracor Estate'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 65, 'm17d', 'The Emperor himself -- may he guide us long and well! -- has ordered a competition among the Galaxy''s finest architects. The commission, to be built at his private retreat at an undisclosed location, is a Hall of Galactic Wildlife. The galleries of this giant museum are planned to display, for our Emperor''s relaxation and enjoyment, the finest, the fiercest creatures of a million worlds. We seek specimens to use in our architectural proposal for this Hall. We have located a desirable pack and would appreciate their speedy termination. Confidentiality appreciated'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 66, 'm17o', 'A Prominent Architectural Firm'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 67, 'm17s', 'We are pleased with your report and will dispatch a taxidermy team to pick up the remains. Your fee is attached. It is likely we will have further contracts until the Empire awards its commission for the Hall.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 68, 'm17t', 'Hall of Galactic Wildlife Proposal'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 69, 'm18d', 'The news among hunters is the Emperor''s big new Hall of Galactic Wildlife. Don''t know much about it except he needs trophies from across the galaxy, all to be mounted in lifelike settings in a big museum. Our group would be spread too thin, trying to land all the trophies required. So we''re subcontracting, you might say. Take down predators in large packs, and we''ll pay you out of the fee the Empire pays us. We''ll take care of the pickup and the stuffing. Move fast!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 70, 'm18o', 'Wilderland Hunting Club'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 71, 'm18s', 'We''ll go ahead and pay you now from the club budget. No idea when we''ll have time to pick up and stuff the trophies. Crazy here!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 72, 'm18t', 'Hall of Galactic Wildlife Trophies'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 73, 'm19d', 'Surprisingly few citizens have heard of the Interplanetary Embalmers'' Guild. Soldiering on despite unjust neglect, we promote new research in bodily preservation techniques. The recently announced Imperial proposal for a Hall of Galactic Wildlife offers us exciting opportunities. This private museum for the Emperor is planned to feature countless species from across the galaxy. Current plans call for stuffed specimens, but we regard this as backward and undignified. Far better to present actual intact specimens, faultlessly and incorruptibly preserved! To demonstrate our techniques, we seek large numbers of dramatic specimens, especially predators. Subjugate and terminate all packs you find at the following coordinates, preferably with minimal visible damage. We shall arrange pickup and preservation. The Hall of Galactic Wildlife will enshrine your trophy for generations to come!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 74, 'm19o', 'Interplanetary Embalmers'' Guild'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 75, 'm19s', 'This news pleases us. The Embalmers'' Guild will soon demonstrate techniques that will bring admiring attention from all educated individuals, and with luck even the favor of the Emperor himself.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 76, 'm19t', 'Embalmers'' Guild Seeks Hunters'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 77, 'm20d', 'To expedite preliminary budgeting for the Emperor''s proposal Hall of Galactic Wildlife, the Imperial Civilian Accounting Office solicits highly experienced hunting teams. Interested teams may locate and terminate large packs of predators at coordinates provided by local survey offices in conjunction with this agency. The specimens will be assessed for quality and quantity for purposes of figuring expenditures required for large-scale procurement of assets. All other information on this contract is assigned confidential clearance under Imperial security edicts. For assistance, contact the Imperial Security Bureau.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 78, 'm20o', 'Imperial Civilian Accounting Office'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 79, 'm20s', 'Asset procurement noted. Contract payment disbursed.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 80, 'm20t', 'Solicitation for Hunting Teams'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 81, 'm21d', 'A most pleasant pastime! Jorboro hunting, I mean. A dozen of one''s best fellows, mounted and riding for speed, in hot pursuit of the elusive quarry, haha! It is blasted inconvenient, though, when some great gulping predator bounds past one and swallows up the jorboro, or perhaps even one''s friend and his mount. An untidy affair. So here''s what you''ll do: Round up some of your best lads, venture out to these beasts'' last known locale, and mow them all down, pronto. I shall recompense you appropriately, of course.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 82, 'm21o', 'Estate Holder His Excellency Lord Savastorol Hennig Denn, 23rd of the Line'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 83, 'm21s', 'Ha! There, what did I tell the wife, I said, "Get a good lot of hunters to take them out, that''s what!" And I did, and you have! Jolly!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 84, 'm21t', 'Lord Denn Seeks Hunters to Protect Party'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 85, 'm22d', 'Were I a younger man, I''d round up these beasts and give them the old what-for, I tell you that. Eh? Oh yes, yes. I need skilled hunters, and not a few of them, mind you. You must all trundle out and dispose of a pack of ferocious beasts -- which kind of beasts were they? I cannot read this blasted scribble -- never mind. I gravely suspect my neighbor, Lady Bentledown, of importing these beasts and setting them to roam my estate. Why? I tell you why: She disapproves of my good old hunting parties! So what if we make a bit of noise, or if a bit of liquor goes down a dry throat? I ask you, so what? Now we, being hunters, would leap at the chance of disposing of these blasted Bentledown beasts. Ordinarily. But we are not so spry as once we were, nonono. No. So I''ll rely on you and your friends to do the job, shall I? I commend you!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 86, 'm22o', 'Estate Holder His Excellency Lord Savastorol Hennig Denn, 23rd of the Line'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 87, 'm22s', 'Now that''s the kind of enterprise we like to see! I have high hopes for you! And let me add, Lady Bentledown shall soon know a problem of her own, I tell you that! Ha!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 88, 'm22t', 'Brave Hunters Needed on Denn Estate'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 89, 'm23d', 'I have lately fallen into an uncalled-for tiff with my neighbor, a dotty old Core Worlds retiree. Lord Denn is convinced that I am sabotaging his drunken hunting parties. This is silly slander. If two dozen drunken men fire off blasters in the countryside, and in all likelihood hit one another, I regard this as beneficent natural selection. But now Lord Denn has brought in savage beasts to plague both our estates. I believe he intends to hunt them. What nonsense. He will find in these predators much stiffer opposition than his usual quarry, furtive little rodentians. Before he kills himself, or these monsters kill me, I wish you to take an experienced hunting team and slaughter them all. Not Lord Denn, of course, just the creatures. I daresay Lord Denn will manage his own destruction before long.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 90, 'm23o', 'Estate Holder Her Excellency Lady Deianora Bentledown'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 91, 'm23s', 'That is a great relief. I shall call on Lord Denn to mention the unhappy accident that has befallen his imports. I look forward to seeing his reaction.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 92, 'm23t', 'Lady Bentledown Seeks Hunters'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 93, 'm24d', 'When I took over my father''s mining operation after his untimely death, I had no idea his competitors would turn criminal in their methods.  No strategem is too low for them to try.  For example, the future of the company hinges on a rich and untapped vein of vertex crystals as pure as they mine it on Kir.  The competition has blocked my development of this mine by smuggling a cargo of extremely dangerous animals onto the property.  I lost several workmen and dozens of droids to these rapaceous beasts.  The Imperial Army itself sent two different companies of stormtroopers to exterminate the monsters, but the only result was many more deaths.  They have since declared the area unsafe and washed their hands of the matter.  But I''m not going to give in.  My father''s enemies must not win.  I know that there are plenty of good, strong, skilled hands out there willing to band together and kill these terrible creatures.  Not only will I pay you handsomely for such service, but you would be fighting against the forces of greed and injustice in the galaxy.  Surely that is worth risking your life for?'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 94, 'm24o', 'Kara Regallium of the Weald Mining Concern'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 95, 'm24s', 'You did it! I know my father is watching right now, and he must be proud of us all. I have faith again that the galaxy can be a just and caring place to live.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 96, 'm24t', 'Exterminate Murderous Creatures'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 97, 'm25d', 'One of our pilots has gone down. Imperial authorities are scouring the area and we need to extract him quickly. Unfortunately he crash landed in the middle of one of the most dangerous areas on the planet. Some extremely lethal creatures have forced him into hiding. We cannot retrieve him unless these creatures are dispatched. Therefore we are broadcasting this urgent plea for teams of freelance hunters to wipe out this threat before Imperial scanning crews find our pilot. Be warned, these creatures should be approached with the utmost caution. Only very experienced and well-equipped teams should attempt this mission. If you can meet this challenge, are ready to deploy quickly and think you can avoid Imperial entanglements, please contact us for the coordinates of the extraction zone.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 98, 'm25o', 'Alliance To Restore the Republic'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 99, 'm25s', 'Thanks to your hard work, we managed to extract our pilot moments before the Imperial scanning teams detected him. Your skill and bravery are astounding. If you need further employment, please contact the Alliance. We can always use good hunters and fighters.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 100, 'm25t', 'Help Rescue Alliance Pilot'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 101, 'm26d', 'When my daughter asks me for something, I give it to her. It''s a weakness of mine to spoil her. This year I promised to build a grand pavilion for her annual Threld Eve party at any place of her choosing. Children being what they are, she has challenged me by selecting an area which contains the deadliest animals in the sector. What a little darling! So now I need a small army of hunters to venture into this perilous zone and take care of anything that might pose a threat to my precious girl. Mind you, this same area once claimed the lives of ten planetary engineers who were trying to construct a recycling station. But if you''ve got the grit, here''s your chance to earn a tidy fee and make a little girl happy in the process.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 102, 'm26o', 'Lord Quelfray'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 103, 'm26s', 'My dearest little daughter sends you a thousand kisses for making her Threld Eve wish come true. But I''m sure you''re more interested in these credits. Take them and enjoy.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 104, 'm26t', 'Make Little Girl Happy'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 105, 'm27d', 'We''ve got the meanest, fiercest, most murderous collection of claws and teeth this side of Portmoak Sector! We have giant sand beetles, battle-trained dewbacks, bone-crunching rancors and even a krayt dragon or two! Who would dare face these terrible man-eaters in mortal combat? What sort of madmen would risk their lives solely for the entertainment of our audience? Our contestants, that''s who! We''re looking for the most daring, the most deadly, the boldest marksmen in the galaxy to face the grisliest terrors ever to stalk the public holoscreens! A generous prize is waiting for the team of derring-doers who survives the challenge of ... Galactic Gladiators! Do YOU have what it takes?'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 106, 'm27o', 'Galactic Gladiators'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 107, 'm27s', 'Let''s hear it for our new champions! Here is your fabulous cash prize! We hope you come back again for another round of ... Galactic Gladiators!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 108, 'm27t', 'Survive Deadly Combat and Win Prize!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 109, 'm28d', 'Who among the Empire''s loyal citizens does not despise Rebel treachery? The Imperial Navy works tirelessly to hunt down traitors, and sometimes we require the faithful assistance of our civilian friends. We have identified a small landing bay used as a way station by Rebel warships. It is craftily hidden in a patch of wilderness stalked by some of the fiercest creatures in the sector, preventing stormtroopers from mounting an attack. We need a group of well-armed civilian hunters to penetrate this dangerous area and wipe out the most dangerous wildlife. Without wild animals to shield them, the unsuspecting Rebels will be forced to abandon their way station. As their ships flee, our Star Destroyers will be waiting. This coordinated effort will deliver a crushing blow to those who dare challenge the might of the Empire.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 110, 'm28o', 'Imperial Navy'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 111, 'm28s', 'Rousing success! After you took down their wild accomplices, the Rebels evacuated the way station, and our Star Destroyers blew seven of their ships into so much orbital debris. The Empire thanks you for your good service. Here is your well-earned reward.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 112, 'm28t', 'Exterminate Wildlife for the Empire'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 113, 'm29d', 'Imperial injustice knows no limits. While we applauded a recent campaign to confiscate various dangerous animals from the greedy smugglers who distribute them through the galaxy, we were horrified to learn that the Empire "disposed" of these same deadly creatures by dumping them near inhabited regions on different planets. The threat posed by these fierce and often battle-trained animals is severe. That is why we have vowed to eliminate this danger to innocent lives. We are hiring professional hunters to face these lethal monsters. Their brave actions will be recorded by hovercams, to be used as yet more proof of the extent of the Empire''s evil and corruption.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 114, 'm29o', 'Alliance To Restore the Republic'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 115, 'm29s', 'The bravery of freedom-loving galactic citizens will always overcome the deceit and cruelty of Imperial schemes. You have done well. May the Force be with you.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 116, 'm29t', 'Confront Threat to Innocent Lives'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 117, 'm30d', 'I don''t condone a governor taking military action outside of the sector over which he presides. For this reason I am in the market for a team of veteran hunters to undertake a mission on my behalf. I have located a den of bloodthirsty predators at the following coordinates. I am hoping to replenish my personal stock of large, dangerous animals, which I use for punitive and interrogatory purposes. Confront these creatures, provoke a battle, and determine exactly how dangerous they are. I shall not mince words -- these creatures are the most dangerous I could find. My hope is that some or all civilian operatives will be slain, proving that these beasts are worthy of inclusion in my private stock. Contact my office if you wish to participate. I am only interested in battle-ready operatives of the highest caliber.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 118, 'm30o', 'Moff Lunus'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 119, 'm30s', 'I would be lying if I said I am pleased by your success. You have demonstrated that even these terrible creatures may be overcome by the simple application of brute, unsophisticated force. I shall continue my search for non-sentient agents worthy of my stable. In the meantime, here is a modest payment for your services.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 120, 'm30t', 'Evaluate Threat Level of Wild Animals'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 121, 'm31d', 'It''s unthinkable, but a notorious enemy of the Empire has fortified himself in the unlikeliest of places. The Rebels refer to this agent as the Mouse and spread ridiculous rumors that he is an MSE-6 droid. But no mouse droid could infilftrate such a dangerous wilderness region, tame a collection of extremely deadly predators, and employ them as trained bodyguards, all while conducting the operations of a dense, multi-system spy network. We know that the Mouse has access to our military communications, so we have decided to employ hunters against him. These hired guns will take down his bestial bodyguards and deliver this unrepentant traitor into our custody. Be advised that the creatures are extremely savage and supremely powerful.  No hunter should attempt this assignment alone. The Mouse is responsible for the demise of countless Imperial agents. A few hunters more will hardly make him blink.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 122, 'm31o', 'Imperial Intelligence'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 123, 'm31s', 'We are most impressed with your performance against the Mouse''s savage guards. Even though he escaped you, we shall pay a portion of the bounty in compensation for your deadly performance.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 124, 'm31t', 'Mission of Utmost Importance For Hunters'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 125, 'm32d', 'The time we have dreaded is finally upon us. The rutting season has begun. From the deepest wilderness comes a plague of terrible creatures who foul our lands, destroy our property and kill our peaceful denizens. Every year the warriors among us band together to face this threat and drive these awful monsters away from our settlements. But last season we had trouble with the Empire. A storm of walkers robbed us of our strongest and bravest. Now we are left defenseless in the face of the coming onslaught. The Empire punishes our resistance by abandoning us to our fate. Are we doomed to die over Imperial cruelty? Is there no one out there who can come to our aid?'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 126, 'm32o', 'The Settlement of Thraalcopse'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 127, 'm32s', 'Joy and jubilation! You have rescued us from the savagery of nature and the heartless cruelty of the Empire! Please take this reward and join us in our celebration of life!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 128, 'm32t', 'Protect Settlement From Terrible Tide'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 129, 'm33d', 'We attempted to resist the Empire. We marshaled every scrap of strength and bravery to resist their black tyranny, but alas, our cause was hopeless. Those who survived the utter devastation of our settlement were forced to flee into the wilderness. But the Empire is not content to devastate our people and steal our holdings. Now they pursue us, always keeping stormtroopers and AT-STs on our heels. They''re herding us into the most dangerous part of the wild. They want the monsters of nature to finish us off. But we still cling to hope. We are sending out a call to any group of stalwart fighters who can proceed quickly to these coordinates and dispatch these terrible creatures before our children are driven into their slavering jaws. We can pay for this assistance, if payment is important to you. But please hurry! Our lives depend upon it!'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 130, 'm33o', 'Settlement Displaced by the Empire'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 131, 'm33s', 'Between your astounding victory and the actions of our own warriors, we believe we have cleared the area of the most dangerous of its wild inhabitants. The Empire still dogs our heels, but at least we have struck a blow against them today. Take your reward and the gratitude of our children.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 132, 'm33t', 'Aid Desperate Refugees'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 133, 'm34d', 'It''s a nightmare! My fellow droids and I are responsible for preparing the private resort of our master, Vonn the Hutt. But wild animals that have taken up residence near here, and our landscaping droids are terrified to attend the perimeter. Our security droid, BR-0D, so far has been unable to locate the creatures, though he has narrowed down the probable location of their lair. Our master will bring his own security forces, but I''m afraid by the time he lands it shall be too late for us. I fear what punishment Master Vonn will devise when he sees that we have failed to complete the preparations for his arrival. Oh please, won''t someone help us by getting rid of these awful creatures, before we are scrapped or worse? I am able to pay any fee from my master''s maintenance account. Please contact me as soon as possible. Thank you.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 134, 'm34o', 'Environmental Droid Em-8-Tee'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 135, 'm34s', 'Oh, hooray! We droids are saved. Your actions were most courageous. The taxidermy droid will blow a circuit when he sees what we have brought him.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 136, 'm34t', 'Prepare Resort for Vonn the Hutt'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 137, 'm35d', 'We have calculated an ideal site for a ground-based hyperspace listening station, so that we can monitor the activities of the Imperial Star Destroyers which have become so prevalent in this sector. The problem is that the area is infested with wild creatures that have so far repelled attempts at removal. We would simply bomb their lair into ashes, but we do not want to alert the local authorities of our activities. Instead we intend to hire hunters to enter the habitat of these creatures and eliminate their threat. These are no ordinary wild animals. They demand the efforts of a team of skilled professionals. And of course we require the utmost discretion, to avoid any Imperial entanglements.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 138, 'm35o', 'The Alliance To Restore the Republic'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 139, 'm35s', 'You have our respect for a job well done. Our own fighters had trouble handling those beasts. Take your payment, and please remember your promise of discretion.'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 140, 'm35t', 'Important Mission for the Alliance'),
('string/en/mission/mission_destroy_neutral_hard_creature.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 1, 'm1d', 'Not long ago we ran wilderness fake-fire training exercises for new recruits, and it worked same as always. A green farmboy ran around, so intent on putting a little dot of light on his buddy that he blundered right into some dimwitted carnivorous quadruped, and it disemboweled him on the spot. "Give the recruits live blasters," you say? Oh yeah, I can''t wait to see our casualty rate then. Makes more sense just to shoot the animals. Trouble is, the Imperial Intelligence officer liaising to our battalion is squeezing our operations budget pretty tight. But I can hire an independent strike team out of my discretionary office-supplies fund, so go to it.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 2, 'm1o', 'Corellian Security Force, Sixth Regiment Fourth Batallion');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 3, 'm1s', 'Acknowledged. That''s optimal. We''ll be restarting the fake-fire exercises ASAP. This time I expect the recruits to stay alive, except for the ones that trip over their own damfool feet and break their neck.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 4, 'm1t', 'Training Ground Has Hostile Quadrupeds'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 5, 'm2d', 'We''ve had what I''d call a communications snafu. We''re stationed out here in the wilderness as part of a big training exercise with mock casualties, but we''re getting actual real injuries from what looks like actual real animals. I''ve worked my bloodstripes into a knot trying to get our resident Imperial Intelligence liaison goof to see the problem, but my little X-Wing messages aren''t even making it onto his Death Star trench radar, if you take my idiom. Where I''m going with this is, it would really polish my helmet if you could take out these animals. I''m having to go outside military protocol here, but I can rustle up some credits for you from the ion-beamer recharge budget.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 6, 'm2o', 'Corellian Security Force Mobile Medical Unit 4-077'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 7, 'm2s', 'Friend, you have slammed the proton torpedo down this animal problem''s exhaust port! I''m as pleased as Palpatine''s power gloves, believe you me. Whoops, gotta go.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 8, 'm2t', 'Mobile Hospital Animal Problem'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 9, 'm3d', 'Our Recon unit recently completed a wilderness training exercise. It all went well until we did a head-count back at base and discovered one soldier went missing. We ran a transponder check and there he was, stuck out in mid-nowhere with a broken leg and a bunch of hungry animals gathering. The 224th has always worked from the principle "Leave no one behind," but we''re shipping offworld real soon, and our Imperial Intelligence liaison doesn''t care who we leave. I''m going outside the usual channels to rescue my buddy, but I can''t do it alone. You go in and dispose of the animals, and I''ll do the rescue work. There''s money for you if you move quick!'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 10, 'm3o', 'Corellian Security Force 224th Recon Patrol Squad'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 11, 'm3s', 'Acknowledged. Thanks for helping me rescue my buddy, and here''s your pay. Gotta get back before they discover we''re gone.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 12, 'm3t', 'Rescue Recon Buddy From Animals'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 13, 'm4d', 'Our union members might ordinarily use their vacation time to do their bit for freedom on Corellia and in the galaxy, but that''s out because our union takes no position on the Galactic Civil War. So we pick berries instead. Recently a worker in our chapter was in the wilderness picking hsuaberries, and by pure coincidence he wandered too close to an Imperial outpost. Because he happened to be carrying explosives, they got all worked up and chased him. To lose the pursuit, he hid in an animal den. He didn''t know much about wild animal taming, so he had to leave abruptly. Since his return home, we''ve been thinking that den would make a nice base for our berry-picking activities, if only some strike team would clean out the current occupants. Interested?'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 14, 'm4o', 'Corellian Shipbuilders Union Local 44908'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 15, 'm4s', 'Nice work, friend! You''ve got the stuff of which a true berry-picker is made. Hope you see fit to join our Berry-Picking Alliance before long.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 16, 'm4t', 'Lair Suitable For Berry-Picking'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 17, 'm5d', 'Our company specializes in personal defense systems. To test a new prototype, we attached it to the protocol droid that manages our office, then sent the droid into remote wilderness. Seems there was a design flaw in the prototype, because the droid ran into some animals, and since then we haven''t heard back. We''re writing off the droid, but we need that prototype. Staffers are busy right now checking our earlier models for the same design flaw, so we''re hiring you to go and destroy the animals around the droid''s last known coordinates. If you see the prototype, pick it up; otherwise, we''ll fetch it later.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 18, 'm5o', 'Corellian Technologies'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 19, 'm5s', 'Guess what? The droid stumbled in a while ago, still carrying the prototype. Looks like the design flaw was in the comlink, not our defense unit. But you did good work, so we''re paying you anyway.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 20, 'm5t', 'Recover Personal Defense Prototype'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 21, 'm6d', 'Over the millennia CEC has learned to move its prototype testing grounds rapidly and often, to discourage industrial and military espionage. We have located a desirable new site for a testing facility in the Corellian wilderness. Our construction droids can erect the facility in a day or so, but first our insurance carriers require us to render the area safe for habitation. Therefore we are hiring experienced teams of hunters to destroy all dangerous animals found at the site''s coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 22, 'm6o', 'Corellian Engineering Corporation'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 23, 'm6s', 'We oversaw your progess and were pleased at the result. Your fee is attached. Thank you for doing business with CEC.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 24, 'm6t', 'Testing Facility Requires Animal Removal'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 25, 'm7d', 'Recently one of our leading instructors went on a recreational wilderness trip. In surveying the local wildlife, she fell afoul of certain large and dangerous specimens. Though she escaped safely, she dropped her datapad, which contained irreplacable information regarding a new starship design. She wishes to retrieve the datapad, but must first be assured of safety. The School of Starship Engineering has secured funding for an expedition, on the pretext that we are studying the death modes of these animals. A hovercam will record the data for purposes of the grant, but don''t worry about the externalities of the assignment. Please just clear out that lair.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 26, 'm7o', 'Corellia University School of Starship Engineering'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 27, 'm7s', 'Thank you. We have recovered the datapad. Now must deal with the University regents'' pointed inquiries into the nature of our expedition. Here is your fee.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 28, 'm7t', 'Study Animal Death Modes'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 29, 'm8d', 'It''s common knowledge that Corellians are the best discreet-shipping experts in the galaxy. When we open our planet''s shipping lanes to offworlders, we risk shoddy work and a general lack of professionalism. The consequences can be appalling. For example, there''s a collection of dangerous creatures rampaging through the countryside, threatening farmers and other honest citizens. These animals were dumped by operatives of the Open Shipping Consortium, the foremost advocates of non-Corellian freighters in this sector. The Consortium''s records conveniently neglect to mention this crime, but we know better. For the good of everyone, the CDSICoC must now rectify the OSC''s mistake. We are hiring hunters to eliminate these creatures, left behind by uncaring offworlders. Responsible citizens are encouraged to join in this effort and send a message that the disreputable shipping practices of offworld freighters are not welcome here.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 30, 'm8o', 'Corellian Discreet Shipping Industry Chamber of Commerce'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 31, 'm8s', 'Excellent work. Through the combined efforts of native Corellians and right-thinking offworlders, we can send a message to the Open Shipping Consortium that only the highest degree of professionalism is acceptable in this system.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 32, 'm8t', 'Open Shipping Consortium Menace Again'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 33, 'm9d', 'Independent commerce is the backbone of Corellian culture. Every sentient being should be free to make his way in the universe. The Open Shipping Consortium seeks to enrich this system''s discreet-shipping climate with fresh ideas, technology and manpower. But despite these long-held traditions, the so-called Corellian Discreet Shipping Industry Chamber of Commerce is determined to exclude immigrant species from participating in the rich festival of Corellian prosperity. Furthermore they engage in criminal activities to undermine the credibility of the OSC. Recently the CDSICoC dumped several cargoes of native Corellian wildlife into populated areas and blamed the situation on us. Well, the OSC will not stand for this corruption. To prove our commitment to planetary safety, we will contract hunters to get rid of these displaced animals. Citizens who believe in freedom and open commerce may use this opportunity to take a stand. Corellia will not be controlled by a band of criminals who seek power and money while wearing the mask of patriotism!'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 34, 'm9o', 'The Open Shipping Consortium'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 35, 'm9s', 'Good job! You have struck a blow for freedom. To preserve the tenets of independent commerce, the Open Shipping Consortium must smash the hold of corrupt factions like the Corellian Discreet Shipping Industry Chamber of Commerce.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 36, 'm9t', 'Powermongers Throttle Free Commerce'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 37, 'm10d', 'These Corellian freighters think they''re the tough guys of the galaxy, but they''re knee-deep in humbaba manure. Sure they''re good at ducking homebody Imperial ships, but the Outer Rim is where the New Order does the real dirty work. Tarkin was no picnic and his replacements are worse, and that''s not even mentioning the Hutts. So I''ve got no sympathy for Corellian cowards who dump their cargo at the first sign of trouble. But let me cut to the chase: I''m on this planet to procure some dangerous animals for my employer on Tatooine. The freighter I hired ejected this cargo when an Imperial cruiser blinked at him. The animals are fine, but I''ve heard the pilot intends to pick them up again and continue on his way as if nothing were amiss. I don''t think so. He almost gave me away. He must be taught a lesson. The pilot I''ll handle personally, but I need someone to go out and destroy the animals before he can pick them up again. These Core World spacers have to learn that we don''t abide cowardice in the Outer Rim.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 38, 'm10o', 'A Businessman From Tatooine'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 39, 'm10s', 'Nice. You''re not bad with that weapon. If you ever make it to Tatooine, look me up. I might have more work for you.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 40, 'm10t', 'Help Punish Cowardly Corellian'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 41, 'm11d', 'Sometimes a Bothan reaches his limit, and then there''s hell to pay. I run a shuttle business between Coronet and Tyrena. The nature of my clientele sometimes requires me to make detours from my documented flight path. Lately I''ve been harrassed by a competitor with a strong presence in the less-populated regions of Corellia. He''s been driving dangerous animals into my designated landing zones, presenting a serious threat to myself, my crew and my clientele. I''ll handle my competitor separately, but I need one or more hunters to take out the den of creatures that''s plaguing me. These animals won''t be easy to kill, so make sure you''re well-armed. I''ll pay you well if you do it quickly.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 42, 'm11o', 'A Bothan On the Edge'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 43, 'm11s', 'Very nice indeed. You''d make a good security agent for a shuttle business like mine. Maybe I''ll have a look at my budget and see what I can do.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 44, 'm11t', 'Tired of Unscrupulous Competitor'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 45, 'm12d', 'We''re just a simple farming community, but we have a few vocal Alliance supporters among us, and so the Empire brands us as enemies. We are located on the migration route of several large animal species. Every year we require CorSec to assist us in making sure these animals do not stray into our fields. But this year the Empire has bound CorSec''s hands, ordering them not to influence the migrations. Our people will be endangered and our crops destroyed if someone doesn''t help us by driving off these wild animals. We are in desperate need. Can anyone out there help us? Money doesn''t matter. We just need someone to exterminate any animals that have migrated into our designated buffer zone. If you can do this for us, contact us and we''ll send you the coordinates of the buffer zone.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 46, 'm12o', 'A Farming Community In Need'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 47, 'm12s', 'We cannot thank you enough! As simple farmers we don''t have the same resources as more industry-minded Corellians. We rely upon the aid of brave beings like you when our community is threatened.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 48, 'm12t', 'Protect Us From Imperial Treachery'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 49, 'm13d', 'Ah, Corellia, the very wellspring of maverick commerce. This planet occupies a special place in my heart. It''s a world both of great beauty and of great opportunity. But onto the business at hand. An erstwhile employee of mine has failed to comply with certain payment arrangements we made upon his departure. I have come to extract interest on the missed payments. Said ex-employee, you see, has a fondness for wildlife. He has used the wealth he acquired in my service to buy himself a patch of Corellian dirt. That is why I am contracting skilled and discreet gunmen to find their way onto his property and slay whatever creatures they find. It''s an ugly job, but business is business. We musn''t encourage fiscal irresponsibility, especially not here on Corellia, where honesty and forthrightness are held in the highest regard. Don''t you agree?'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 50, 'm13o', 'Black Sun: Vigo Green'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 51, 'm13s', 'Very well done. Have I hired you before? You have the skill and the guts to be a player yourself. You would make an excellent asset to my organization.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 52, 'm13t', 'Extract Interest on a Payment'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 53, 'm14d', 'Sure I spend a lot of time on Naboo, even for a spacer, but that''s not your problem. I''m contacting you because my family''s land has been overrun with wild creatures since I''ve been offworld for so long. I''m seriously considering bringing a guest back to Corellia and I can''t have these blasted animals sniffing around, trying to make lunch out of us. I''d do the job myself, but I''ve got freight due on Talus in three days. Just see what you can do about this. I know you''re good enough to finish the job. You know I''m good for the money to pay you.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 54, 'm14o', 'Thanus March, Freelance Spacer'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 55, 'm14s', 'I knew I could count on you, kid. Now I''m clear to bring my guest from Naboo. Here''s some of the money I picked up for my latest Talus run. Have fun with it.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 56, 'm14t', 'My Friend, I''ve Got a Wildlife Problem'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 57, 'm15d', 'Not long ago Imperial inspectors arrived in Coronet to check out some alleged contraband. We told them the coordinates of a suspected smuggling depot outside the city. Oddly, after our technicians had just completed maintenance on their jump shuttle, the inspectors crashed near the depot. Truly it was a sad day here at the CorSec offices. Quite to our horror, the bodies of these Imperial agents were devoured by local scavengers. This tragic incident had come to a close, or so we thought, until our monitors detected a small distress beacon transmitting from that area. Apparently one of the inspectors was carrying the device on his person. This beacon now resides in the belly of some wild animal. CorSec requires someone to track down the beacon and incinerate the animal carrying it before Imperial ships detect the distress signal. Can you help us?'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 58, 'm15o', 'Corellian Security Force'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 59, 'm15s', 'Handy work, citizen. The distress beacon ceased transmitting when you killed that last creature. What incredibly bad luck that those Imperial inspectors crashed so close to a lair of highly dangerous animals. Perhaps it will behoove Imperial inspectors to be more careful in the future.'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 60, 'm15t', 'Situation We Need to Resolve Quietly'),
('string/en/mission/mission_destroy_neutral_hard_creature_corellia.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 1, 'm1d', 'Who does not thrill to see the peko-peko winging its powerful way across the sky? The uniqueness of this magnificent reptavian''s beauty is matched only by the flavor of Keren Farms Jut Nut Exquisite Select Roast, the beverage of discerning Theed aristocrats. The seed of the jut nut, relieved of its toxicity after passage through the peko-peko intestinal tract, is salvaged from the freshest droppings, meticulously cleaned, and roasted to perfection. But now a tragic incursion of savage predators threatens this season''s Jut Nut ESR crop, due to their relentless attacks on the peko-peko population. Keren Farms offers a handsome reward to willing teams of hunters.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 2, 'm1o', 'Keren Farms Jut Nut Orchards'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 3, 'm1s', 'Your attention to this matter has rescued the peko-peko, the jut nut crop, the Keren Farms Jut Nut Exquisite Select Roast production season, and the drinking pleasure of the aristocracy. Many thanks, and stop in for a complimentary cup.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 4, 'm1t', 'Naboo''s Jut Nut Crop Endangered'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 5, 'm2d', 'Naboo settlers believe in living lightly on the landscape, in peaceful coexistence with nature. However, current creature activity in areas due for settlement has passed all normal records. Unknown Gungan activities may be driving the creatures into new hunting grounds. Whatever the reason, we must take steps to control the predator population. Experienced strike teams may contact this office for coordinates of large predator packs.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 6, 'm2o', 'The Royal Advisory Council'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 7, 'm2s', 'The Council thanks you for your help in controlling the predator population. Many settlement issues remain unresolved, so we may have further contracts soon.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 8, 'm2t', 'Royal Council Seeks Settlement Protection'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 9, 'm3d', 'Surveyors report unusual creature attacks in outlying areas. Naboo settlers respect wildlife and avoid habitat destruction, but some unknown phenomenon -- perhaps a disease -- is driving predators to amazing ferocity. We have researchers working on the problem, but in the immediate term we need hunting teams to control the largest predator packs. Experienced teams may contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 10, 'm3o', 'The Royal Advisory Council'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 11, 'm3s', 'The Council thanks you for your help in controlling the predator population. The mystery of the attacks remains unresolved, so we may have further contracts soon.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 12, 'm3t', 'Royal Council Seeks Help In Predator Attacks'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 13, 'm4d', 'Security operatives have found evidence that pirates are establishing new bases in the Naboo countryside. Reports indicate that the pirates drive predatory animals from the vicinity of their bases toward settled areas, in hopes of producing chaos to distract security from criminal activities. The Royal Security Forces are combating this tactic by contracting with independent hunting teams to control the predators. This office will provide target coordinates to experienced parties.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 14, 'm4o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 15, 'm4s', 'We thank you for your prompt attention to the pirates'' creature-diversion tactic. We shall continue to combat this technique in the future.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 16, 'm4t', 'Naboo Pirates Using Creatures'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 17, 'm5d', 'Naboo security personnel report that smugglers are now, for lack of a better term, brainwashing wild animals. The smugglers implant control devices in the nervous system of a predator or other valuable beast. The controller forces the animal to journey overland to the smugglers'' chosen destination, where accomplices destroy it and harvest the desired hide or meat. This saves the smugglers the trouble of transporting the carcass themselves. These smugglers have ways of detecting Royal Security Forces, perhaps through inside accomplices. Therefore, we are hiring experienced hunting teams to stop the creatures before they reach the smugglers'' destination. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 18, 'm5o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 19, 'm5s', 'You have the Security Forces'' thanks for your efforts in controlling the smugglers'' brainwashing of animals. We shall continue our fight against this barbaric tactic.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 20, 'm5t', 'Naboo Smugglers Brainwashing Animals'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 21, 'm6d', 'An unusual request from offworld has been forwarded to the Music Advisor''s office. The Deftoi of Muntro VI in the Outer Rim are staging their decennial Otherworld Arts Festival. A new composition in their quasi-operatic ceremonial artform, which their formal request translates roughly as "highmind stagecraft," dramatizes a bloody period in Naboo''s history before the Great Time of Peace. The production requires carcasses of certain Naboo animals, which they evidently plan to animate onstage by unspecified means. This office has little experience in hunting animals. If you will destroy the animals at these coordinates, administrators will obtain and ship the specimens afterward.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 22, 'm6o', 'Office of the Music Advisor of Naboo'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 23, 'm6s', 'The Music Advisor''s office will dispatch a recovery team at once to ship the bodies to Muntro VI. Meanwhile, because the condition of the bodies is apparently irrelevant to the Deftoi, you may take what you wish from the prey.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 24, 'm6t', 'Arts Festival Requires Naboo Animals'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 25, 'm7d', 'Animal activity threatens to increase tension between the Naboo and Gungan peoples. Both cultures place high priority on humane treatment of wildlife, but they differ in the means they employ to control predators. Gungan representatives are protesting the Naboo government''s program to relocate predators from human-settled areas to remote wilderness -- "remote" to humans, but often important to Gungans. To reduce tension, the government is phasing out its relocation program and hiring independent hunters to cull especially dangerous packs of predators. Experienced teams may contact the Governor''s Office for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 26, 'm7o', 'Office of the Governor of Naboo'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 27, 'm7s', 'The Governor thanks you for your attention to this sensitive matter. This office is confident that future relations between the Naboo and the Gungans will improve.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 28, 'm7t', 'Reduce Tension Between Naboo and Gungans'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 29, 'm8d', 'The trouble with a planet like Naboo is, the wildlife is so prolific that there''s no glamor in hunting it. I make my living taking rich Theedsiders into the wilderness to hunt large, dangerous animals. But my skills seem extraneous when the animals simply wander past base camp, waiting to be shot. I''ve struck on a plan to rectify this issue. I want to hire a strike team to visit my preferred hunting grounds and weed out the more prolific target species. That way we''ll have to hunt down the survivors, and my clients will get their credits'' worth. So if you''re good with a blaster and want to have fun in the wilderness, let me know. I''ll send you some coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 30, 'm8o', 'Gerrio Coronis of Theedside Safaris'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 31, 'm8s', 'I didn''t expect you to find any animal lairs quite so dangerous. You did the job anyway, which is commendable. I hope you left at least one or two for me, though.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 32, 'm8t', 'Thin Wildlife In Hunting Grounds'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 33, 'm9d', 'Our mineral scanners have isolated a splendid vein of untapped orichale. We intend to mine it as quickly as possible, to meet increased demand from the Imperial Navy shipyards. As it happens, though, the vein is untapped largely because the area is inhabited by a proliferation of unsavory creatures. We''ve lost many droids and an entire team of Naboo field men to these rampaging animals. We are therefore hiring a team of veteran hunters to obliterate these beasts once and for all. We will pay handsomely for unalloyed success.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 34, 'm9o', 'Alpha Sierra Mining Corporation, Naboo Division'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 35, 'm9s', 'You have done your job very well. We trust this payment will be sufficient. Now we can proceed with our plans to mine for orichale.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 36, 'm9t', 'Obliterate Dangerous Naboo Animals'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 37, 'm10d', 'Not for more dan forty years have de Gungan people been open with de outside worlds. Wesan elders not thinken dat bees much time, but oursan younglens have changen too much because of de outlaunders. Whysa de younglens spenden so much time thinken about de starships and skyspeeders instead of de bongos and boomers? Dey brains bees trapped by desan HoloNet gamen and galactic holograms and stinkowiff mackineeks. \n\nWesan elders of Otoh Gunga have deciden to do something. Since oursan younglens enjoy watchen yousan outlaunders, wesa going to pay some outlaunders to go on a wilde animale hunt, liken de Gungans of old used to do. Maybe oursan will see desan acts of bravery by outlaunders and start thinken dat Gungans should hunt again, too. Wesa want to see Gungan younglens riden de kaadus and usen de boomers and atlatls. If yousa bees una outlander and yousa thinken yousa would make a bombad hunter, wesan elders can senden da coordinatees of some bigge animale to hunt. Wesa going to record yousa adventures on a hologram and show it to oursan younglens. Yousan will be well paid for desan good services.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 38, 'm10o', 'Brass Fajallan of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 39, 'm10s', 'Yousa done well, outlaunder! Dat was no simple job yousa performed. Yousa always welcome at Otoh Gunga. Maybe now oursan younglens will getten off dey heyblibbers and beesa warriors again, like yous.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 40, 'm10t', 'De Gungan Younglens Are Needen Inspiration'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 41, 'm11d', 'We are sad to report the loss of a party of Toydarian explorers near the following coordinates. These stalwart adventurers penetrated the wilds of Naboo armed only with ion blasters and their own reckless bravery. They must have underestimated the size and impact of our planet''s wild fauna, as their last transmission was an unbridled expression of shock and dismay. Droid scouts have reported no sign of living Toydarians in the region. Now comes the grim task of surveying the local wildlife to determine the fate of these diminutive visitors to our star system. We require teams of experienced hunters to travel to the lairs of selected animal populations and liquidate the life forms within. Afterward we shall dispatch forensic droids to cut open the carcasses and determine the contents of their stomachs. Only in this way may we bring closure for the grieving families of these little, winged heroes.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 42, 'm11o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 43, 'm11s', 'You performed your duties well, though we did not find the Toydarian explorers inside those particular animals. We must persist until this dark task is completed. The widows of the fallen Toydarians are keening in our offices. Have you ever heard a Toydarian widow keen? This matter cannot be resolved too quickly.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 44, 'm11t', 'Bring Closure to Toydarian Tragedy'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 45, 'm12d', 'As is no doubt common knowledge across Naboo, His Excellency Lord Felmarath of Theed recently lost his daughter Zawe to a tragic death. A cruel pack of wild predators beset her as she rode her guarlara not far from His Excellency''s country estate. In accordance with his personal code of honor, Lord Felmarath has ordered the execution of all dangerous animals in the vicinity of this estate. Funds are available to compensate all hunters who can prove that they have exterminated a reasonable population of large creatures. As His Excellency''s property contains many animals of considerable peril, hunters are warned not to pursue these bounties flippantly. He does not wish for any more deaths to result from this affair.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 46, 'm12o', 'Master Waymo Rion of Lord Felmarath''s Estate'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 47, 'm12s', 'Excellent. You have earned your bounty. But some animals are still alive. Lord Felmarath will soon hire more hunters to sweep the area until the last one is found and destroyed.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 48, 'm12t', 'Avenge Daughter of Lord Felmarath'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 49, 'm13d', 'If you spend a lot of time offworld, you may not know about the strange weather we''ve been experiencing. Stellar flares are responsible for a moisture inversion that has brought rains to dry areas and reduced water levels in the lowlands. This climatological chaos has resulted in an overabundance of wildlife in regions where it is normally under control. While we are applying for the intervention of Imperial weather shields to block the stellar flares, we are employing more direct methods to regain control of the wildlife populations. We are contracting hunters to thin out groups of large, prolific and/or dangerous animals in certain areas. If you qualify to participate in this reclamation campaign, contact planetary authorities as soon as possible. We can stave off disaster, but only if we act promptly.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 50, 'm13o', 'Naboo Environmental Council'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 51, 'm13s', 'We did not expect such a dangerous group of animals at that location! Your pay is scaled in accordance with the difficulty of the work. You have done very well indeed.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 52, 'm13t', 'Flares Disrupt Naboo Animal Populations'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 53, 'm14d', 'Even decades later, the Trade Federation''s invasion of Naboo haunts our peaceful planet. We have received reports that a squad of droidekas has awakened from a buried cache, most likely due to a random signal matching its trigger frequency. While our own forces are tracking down the destroyers themselves, we require the expertise of skilled hunters to eliminate many larger animals driven from their habitats by these errant war machines. We can provide the coordinates of trouble spots to anyone intersted in helping us with this endeavor. Thank you.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 54, 'm14o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 55, 'm14s', 'We suspected that those creatures were large enough to pose a threat to local settlements. You have done the planet a tremendous service by helping to clean up this mess left by the Trade Federation.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 56, 'm14t', 'Old Droidekas Spook Naboo''s Wildlife'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 57, 'm15d', 'This office has embarked upon a bold engineering scheme. A system of power relay antennae is to be constructed in various unsettled regions of Naboo. These antennae will redirect energy transmissions from the power core at Theed to travellers stranded in dangerous, unpopulated areas across the planet. Construction of these antennae, however, is not trivial. The regions that most need antennae are inhabited by creatures that threaten travellers. Many survey droids have been lost scouting for appropriate sites. Therefore this office is hiring hunters who can remove these wild threats long enough for our droids to complete these surveys. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 58, 'm15o', 'Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 59, 'm15s', 'This office is pleased to reward you for the successful completion of your contract. If you are available for such missions in the future, please notify this office forthwith.'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 60, 'm15t', 'Naboo''s Bold Engineering Scheme'),
('string/en/mission/mission_destroy_neutral_hard_creature_naboo.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 1, 'm1d', 'Some creatures are simply abominations -- nightmares given life by a cruel and sinister universe. If only these beasts would remain in the dark, we would have no problems. But they do not. Will you help me force some of these monsters back into the shadow?  '),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 3, 'm1s', 'A thousand thanks, my friend. You are brave and strong -- a beacon of light in an otherwise murky universe. You''ve earned your reward.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 4, 'm1t', 'Fight the Shadows'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 5, 'm2d', 'I''ve warned the Imperial Environmental Preservation & Refocusing Authority that their activities would throw delicate ecosystems out of balance. Their efforts have deprived dangerous predators of their natural food source, and now the locals must get help to eliminate them. Will you help? '),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 7, 'm2s', 'I don''t know what our community would have done without you. You''re a stalwart hunter, make no mistake. '),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 8, 'm2t', 'Become a Mighty Hunter'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 9, 'm3d', 'Feel like a challenge, citizen? Several hunters have already tried to wipe out a particularly dangerous creature lair near here. The lucky ones gave up. If you can accomplish this feat, I''ll make sure you''re properly compensated.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 11, 'm3s', 'I am most certainly impressed. How''d you pull that off? Resourceful type, aren''t you? As promised, the generous reward is yours.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 12, 'm3t', 'Into the Creatures'' Den'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 13, 'm4d', 'If you''d like to tackle a mission that would make even the toughest Trandoshan go greener with envy, try taking out the monsters that have been plaguing nearby communities. These beasts are killers! If you pull this off, you''ll rake in the credits.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 15, 'm4s', 'Good work, mighty hunter! I bet those creatures didn''t have any idea who they were messing with. To the victor go the spoils. Enjoy!'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 16, 'm4t', 'A-Hunting You Will Go'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 17, 'm5d', 'Having tourists eaten by savage predators is sooo bad for business. The local tourism association has raised a generous reward, payable to the hunter that can rid us of these vicious beasts. Is that hunter you?'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 19, 'm5s', 'You''re not secretly a Jedi, by any chance? Only a being of exceptional strength and skill could have done what you did. Congratulations. You''ve earned this reward.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 20, 'm5t', 'Monsters Bad For Business'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 21, 'm6d', 'Bleeding heart conservationists prevented the legitimate hunting of several dangerous predatory species. Now there are too many of them, and they''re encroaching on our settlements. We sure could use your help in controlling their numbers.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 23, 'm6s', 'Well done, friend! You''re a champion of the people. This reward should be proof of our gratitude. Ever consider doing this for a living? Or do you?'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 24, 'm6t', 'Conservationists Create Problems'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 25, 'm7d', 'Despite all my efforts to stop them, the savage monsters that murdered my family months ago continue to plague this area. Help me stop them, citizen. You''re my only hope.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 27, 'm7s', 'Someone finally did it! Those beasts are destroyed at last and our community is safe. You''ve earned this reward, friend.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 28, 'm7t', 'Stop Murderous Monsters'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 29, 'm8d', 'Whatever is terrorizing my homestead, it''s mean enough to kill three hired guards and dismantle a platoon of security droids. I need someone to track it down and wipe it out. Take whatever associates you need for the job. I''ll defray the costs, just get the job done.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 31, 'm8s', 'I can''t believe you actually managed to wipe that thing out. Amazing. Your payment is given with my heartiest thanks.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 32, 'm8t', 'Something Hunts In the Night'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 33, 'm9d', 'It took nearly all my resources, but I finally located the murderous creature that took my parents from me! I''m willing to pay you all I have left if you''ll take whatever armaments you need and kill that hellish beast once and for all!'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 35, 'm9s', 'You have done more than just kill a wild animal. You have avenged two good people. I''ve deposited all I have left. I would give you more, if only I had it. At last I shall rest easy.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 36, 'm9t', 'Avenge Murdered Parents'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 37, 'm10d', 'The planetary ecosystem is in a shambles after some disruptive animals were set loose. The authorities will pay a considerable bounty to anyone who can blast these dangerous creatures into component muscle fibers. And I''ll get a finder''s fee myself. You look like you''re up to this job.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 39, 'm10s', 'Incredible! You took care of the problem far quicker than anyone expected. You earned this bounty with style. And thanks for bagging me the finder''s fee, too.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 40, 'm10t', 'Get That Critter Bounty'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 41, 'm11d', 'Business is bad, and it''s the Empire''s fault. Their "xenobiologists" dumped a load of dangerous monsters on our land. I''m dropping hoversleds and load lifters faster than grumph scales in molting season. I''ll pay you handsomely if you can obliterate these creatures so I can get back on schedule.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 43, 'm11s', 'At last my business can get back on schedule. Nice work, my friend.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 44, 'm11t', 'Help Aggrieved Businessman'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 45, 'm12d', 'Awful creatures have migrated into the area around my village. If someone doesn''t handle them soon, we could be overrun! We''re a peaceful village. We have no weapons. Please, can you do something to save us? We can pay you, though we don''t have much to spare.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 47, 'm12s', 'How wonderful! You have given hope to those who have none! We emptied our village medical funds to pay you, but you have more than earned it.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 48, 'm12t', 'Save Peaceful Village'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 49, 'm13d', 'My studies show that the planet''s natural radiation shielding has been damaged by the gaseous emissions of certain large carnivores in the wild. In the interest of the planetary environment, I shall pay you a large sum of credits to remove some of these unwholesome creatures from the ecosystem. Interested?'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 51, 'm13s', 'Most satisfactory. I could never have accomplished that myself. Perhaps I''ll be in touch with you again soon.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 52, 'm13t', 'Aid the Environment'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 53, 'm14d', 'The Periodic Overland Migration is on again. Predators are already gathering to follow the herd. The community council wants to hire hunters to eliminate a pack of them before they menace this area. Can you take care of this?'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 55, 'm14s', 'Excellent! The Migration will continue for some time, so I expect folks around here will have more assignments for you.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 56, 'm14t', 'Migrations Are Hard Work');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 57, 'm15d', 'The chirgotta intestinal parasite, which causes illness in species across the galaxy, lives one part of its life-cycle in the skin membranes of large indigenous predators. We can stop the spread of chirgotta through control of predators. If you can eliminate the chirgotta-infested predators at this location, we''ll reward you.'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 59, 'm15s', 'This fee comes from a local grant provided by the Galactic Chirgotta Awareness Council. Thank you for your help in making the galaxy chirgotta-free!'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 60, 'm15t', 'Halt Spread of Parasite'),
('string/en/mission/mission_destroy_neutral_hard_creature_non_persistent_from_npc.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 1, 'm1d', 'The Tatooine Civilian Defense League has detected an alarming rise in the number of dangerous creatures in the habitable areas of the planet. Such animals are making life extremely unsafe. In accordance with Imperial Indigenous Control Policy #780901, the Tatooine Civilian Defense League is authorized to pay for the extermination of specified creatures through the destruction of their central lairs or hives.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 2, 'm1o', 'Tatooine Civilian Defense League'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 3, 'm1s', 'Excellent work! Unlike most of our hired agents, you''ve actually succeeded in destroying the lair of a creature known to terrorize Tatooine locals. Your reward has already been transferred to your account.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 4, 'm1t', 'Creature Culling'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 5, 'm2d', 'Unpack your blasters, slap in them ammo packs, and kiss your loved ones goodbye! It''s time for Blaster Barn''s seasonal Run N'' Gun! That''s right - the Run N'' Gun is back, and better than ever! Thanks to this season''s sponsor, the lovely Lady Valarian, Blaster Barn is offering the largest bounties ever for the killing of Tatooine''s most fearsome, ferocious, and formidable creatures! So get out there and wipe out them animals! And remember, Blaster Barn Has Your Back! '),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 6, 'm2o', 'Mos Eisley Blaster Barn'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 7, 'm2s', 'Stand tall, hold your head up high, and get ready to be famous! You''ve just won Blaster Barn''s seasonal Run N'' Gun! You''ve hunted, battled, and killed Tatooine''s most dangerous creatures. And you''ve come through unscathed! Now you face an even bigger challenge: deciding how to spend your reward! Good luck, and remember: Blaster Barn Has Your Back!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 8, 'm2t', 'Tatooine Run N'' Gun!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 9, 'm3d', 'We, the Dim-U monks of Tatooine, who worship at the hairy feet of the Mighty Bantha, are distressed about the dangers faced by our hirsute idol. While Tatooine should be the domain of the Bellowing Bantha alone, the Horned-One must share the planet with the most violent and terrifying of creatures. These monsters do not know the peace and serenity of the Enduring Bantha, and they often pursue and kill Him. Without the Wandering Bantha, the life of the Dim-U monk has no meaning, and therefore we are seeking champions to step forward and protect the Stalwart Bantha by eliminating his enemies. The Dim-U monastery will gladly reward those who protect the Beloved Bantha, in whose eyes all Universal Truths are revealed! Go forth, and protect the Horned-One!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 10, 'm3o', 'Dim-U Monks of Tatooine'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 11, 'm3s', 'The Mighty Bantha, the legendary Horned-One who brings peace and tranquility to all who gaze upon Him, is safe once again! You have served the Enduring Bantha well! The Dim-U monks, loyal servants of the Wandering Bantha, are overjoyed at your success. Our coffers have been opened and you will be rewarded. The Dim-U monastery thanks you on behalf of the Horned-One, whose powerful bellow will roar your name across the desert and throughout the start so that all who worship at His hairy feet will know of your heroic deeds.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 12, 'm3t', 'Bantha Defender'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 13, 'm4d', 'The very fate of Tatooine rests upon your shoulders! As you may know, as head of the Darklighter clan, I am Tatooine''s last honest businessman. With my great (and legitimate) wealth, I provide for dozens of families across the Dune Sea. My untarnished credits flow into Anchorhead and Mos Eisley, keeping local businesses afloat. I subsidize moisture farming, pay my taxes to the Emperor on time, and help arm local militias to protect settlements from Tusken Raider attacks. \n\nSadly, my business is threatened. Recently, several shipments of my hydroponic vegetables, which are sent to all corners of Tatooine, have been ambushed by menacing creatures. The monsters have left dead workers and eopies in their wake, and scattered my produce. Worst of all, those people who depend upon my shipments have been forced to starve, or buy their food from less reputable businessmen. Fortunately, my scouts have identified the beasts responsible and located their lair. If you could possibly destroy these creatures before they can kill any more of my hired hands, or disrupt another shipment, I would be in your debt (figuratively speaking, of course).\n\nYour Benefactor,\n\nHuff Darklighter'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 14, 'your_former_employer', '\nHuff Darklighter'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 15, 'm4l', 'A wealthy food magnate needs help protecting his food shipments from native creatures.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 16, 'm4o', 'Huff Darklighter'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 17, 'm4s', 'Wonderful work, my friend! You have proven to be one of my most worthwhile investments! By killing those creatures and destroying their lair, you''ve not only protected all of my future shipments, but avenged the deaths of my workers and my lost credits. I will gladly pay you your well-deserved fee.\n\nYour Grateful Host,\n\nHuff Darklighter'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 18, 'm4t', 'Lost Caravans'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 19, 'm5d', 'Transmission Translated from Jawaese for you convenience!\n\nGreetings Non-Jawa!\n\nJawa clan is in frightening, terrible, imminent danger. Horrible, ugly, nasty creatures attack! Always injure and kill... First Tusken Raiders drive us from home fortress, now creatures threaten death and extinction. Please, hunt down and kill beasts or more Jawas die!\n\nEet Ptaa, Jawa Clan Leader  '),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 20, 'm5l', 'Jawas from a nearby clan are being killed by deadly creatures and need help combating the monsters.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 21, 'm5o', 'Eet Ptaa'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 22, 'm5s', 'Transmission Translated from Jawaese for you convenience!\n\nMost exalted hero of the Jawas! We chear your name from First Dawn to Second Dusk! You have made the desert safe, welcoming, home to the Jawas. We will now pay you a sizable, big reward.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 23, 'm5t', 'Jawa Emergency'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 24, 'm6d', 'Greetings Citizen!\n\nThe Great Galactic Museum is undertaking our most ambitious project yet. We are attempting to build a complete collection of all known animals in the galaxy. Intact specimens will be displayed in museums across the galaxy, with the most impressive species finding a home in Coruscant''s branch of the Great Galactic Museum.\n\nCurrently, we are seeking specimens from the Outer Rim world of Tatooine! In order to safely collect these specimens, the Great Galactic Museum needs able-bodied adventurers to secure several dangerous areas on the desert world. Your mission, if you choose to accept it, requires that you enter the habitat of one of our most wanted Tatooine specimens and neutralize any threatening creatures in the vicinity. Once this task is complete, you are free to seek other employment. Within one standard year, we will dispatch an elite collection team to Tatooine to gather the appropriate specimens.\n\nThank you for your patronage!\n'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 25, 'm6o', 'Great Galactic Museum of Coruscant'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 26, 'm6s', 'Greetings Citizen!\n\nThe Great Galactic Museum is overjoyed at your recent success in the field! Now that you have destroyed the lair of one of Tatooine''s most wanted creatures, we can send a retrieval team to collect the necessary specimens. Payment for your services has already been transmitted. You are now free to seek other employment.\n\nThank you for your patronage!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 27, 'm6t', 'Tatooine Taxidermy Expedition'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 28, 'm7d', '*Confidential*\n\nOutlander Expeditions, one of the galaxy''s most successful providers of adventure vacations, offers wealthy customers an opportunity to visit incredibly exciting locations on a number of amazing planets. Outlander Expedition''s reputation has been built on creating thrilling, but ultimately safe adventures for our clients.\n\nOne of our most popular expeditions brings amateur explorers to Tatooine. Although our stay is brief, we do provide our clients with a glimpse of the Dune Sea and fly-bys of migrating bantha herds. Unfortunately, recent treks on the desert planet have been beset by danger. While our tour guides and clients fully expect to see native fauna from afar, we''ve had difficulty preventing unplanned encounters with Tatooine''s truly threatening wildlife. In order to remain a leader in the adventure vacation market, Outlander Expedition is willing to send highly-trained advance agents - like yourself - to sanitize our Tatooine adventure destinations. We have identified the lair of a potentially dangerous creature; this lair needs to be destroyed before we can send our next adventure vacation group to Tatooine.\n\nBecause Outlander Expeditions'' clientele wants to believe that they are actually placing themselves in harm''s way, we will not disclose the existence or activities of our advance agents. The illusion of danger is critical to the success of our ventures, and therefore we appreciate your discretion in this matter.\n\nSlembax Platt, Adventure Vacation Engineer, Outlander Expeditions'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 29, 'm7i', '*Confidential*\n\nOutlander Expeditions has fallen under intense Imperial scrutiny due to allegations of unsafe business practices. As a result, the company no longer requires you to help make Tatooine "safe" for our wealthy clients. If the Empire sees fit to allow Outlander Expeditions to remain in operation, we will send another call for agents.\n\nSlembax Platt, Adventure Vacation Engineer, Outlander Expeditions'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 30, 'm7l', 'An organization that runs entertainment expeditions is seeking adventurers to help prevent any unplanned encounters with dangerous wildlife on Tatooine.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 31, 'm7o', 'Outlander Expeditions'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 32, 'm7s', '*Confidential*\n\nAs a representative of Outlander Expeditions, I am relieved that you have been able to help the company prepare Tatooine for future excursions. Now that the target adventure site has been secured, Outlander Expeditions can once again offer trilling trips to the desert planet. Our clients are overjoyed and business has never been better. We owe our current success to a group of advance agents, like yourself. You have been paid handsomely for your efforts.\n\nOnce again, I''d like to remind you that the details of this mission should be considered incredibly confidential. It''s vital that we maintain an illusion of danger during all of our expeditions. We appreciate your discretion in this matter.\n\nSlembax Platt, Adventure Vacation Engineer, Outlander Expeditions'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 33, 'm7t', 'Tatooine Tourism Trouble'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 34, 'm8d', 'I was only away for a few hours... That morning, I loaded up the landspeeder with a week''s supply of water and some of my wife''s hydroponic vegetables. Then, I headed into Anchorhead, just like I do every week, to see if I could trade or sell the water and vegetables. And I needed to pick up a new fusioncutter to repair some of my vaporators... I was only away for a few hours!\n\nBut when I returned to the farm, there was blood everywhere. I knew right away that something bad had happened. I found my wife in the courtyard. She had fought back. She was tough enough to live out here in the desert, so it''s no wonder that she killed a few of the monsters before they got her. And the kids, they must have tried to run. I found them both a few kilometers away from the house. It was horrible...\n\nI want the monsters that killed my family dead. I can point you towards their lair. I''d head out there myself, but I''m just a farmer. I''ve never killed anything... I''m hoping you have the guts, and the weapon, to take revenge for me!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 35, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 36, 'm8s', 'I''m still consumed by grief, even though you''ve killed those murderous beasts. I can''t take any joy in death. I''ve already lost so much. I just hope that sommeday, I''ll be able to start my life over. But it won''t be out here, in the desert. I need to get away from my memories. After paying you, I''m going to try to turn my back on the past. I hope I have a future.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 37, 'm8t', 'Killers!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 38, 'm9d', 'The Bureau of Ethnicity and Socialization has a long and storied history of studying Tatooine''s native sentient species. Historical records will dwell on the fact that one of our most successful researchers, Alkhara, eventually became a murderous bandit on Tatooine, but the bulk of our agents are noble and intelligent scientists seeking to better understand all forms of life throughout the galaxy.\n\nOur recent expeditions have focused almost exclusively on studying Jawa populations. However, the Jawas live in increasingly dangerous areas of Tatooine, and many of our highly-trained researchers have not returned from their field studies.\n\nIn order to make specific areas of Tatooine safe for our scientists, the Bureau of Ethnicity and Socialization is hiring adventurers and explorers to destroy the lairs of any potentially murderous creatures living near our subject Jawa populations.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 39, 'm9o', 'Bureau of Ethnicity and Socialization'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 40, 'm9s', 'Thanks in part of your efforts, our highly-qualified field researchers are able continue their research of specific Jawa populations on Tatooine. The Bureau of Ethnicity and Socialization hopes to continue these studies indefinitely so that the galaxy may better understand the reclusive Jawas. Payment for your services has been rendered.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 41, 'm9t', 'Anthropology Aid'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 42, 'm10d', 'Hello my friend!\n\nI am sending you this transmission on behalf of a group of very concerned individuals who live their lives in continual fear. We are simple farmers and hard-working merchants, not adventurers or warriors. And we are now faced with a threat that is far beyond our abilities. We''ve had members of our community harassed, stalked, attacked, and even killed by a group of dangerous creatures.\n\nYou may be our only hope! We trust that you will be willing to aid us by destroying the lair of the vicious creatures before they kill again. Please don''t disappoint us...'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 43, 'm10o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 44, 'm10s', 'Hello again, my brave friend!\n\nAt last, we are free of fear! We placed all our hopes in you, and you proved worthy of our trust. We no longer need to worry about being harassed, stalked, or killed by the dangerous creatures that have plagued us for so many seasons. When I announced your victory over the lair, a cry of relief rose up from the crowd, followed by tears and celebration. At last, our nightmare may be over. We owe our futures to you.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 45, 'm10t', 'Good Samaritan'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 46, 'm11d', 'It seems that it is mating season for some of the larger creatures that share my moisture farm.  Some of the younger males can get pretty aggressive.  They have left my vaporators alone, but any repair droid that wanders too close is immediately attacked.  I''ve already lost three repair droids!  Luckily, enough of one remained after the last attack that I managed to pull an image of the creature off the memory drive. I''ve got the general location of the creature''s lair, but you may need to do a bit of tracking.  I figure the reward is going to cost me less than the repair droids.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 47, 'm11l', 'A farmer wants you to protect his repair droids by killing some nearby creatures.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 48, 'm11s', 'Thanks for taking care of my critter problem.  I know it couldn''t have been an easy job.  I can''t even build one repair droid with what I have left of the others.  Here''s your payment.  I hope it saves me the cost of a few more droids.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 49, 'm11t', 'Droid Destroyers'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 50, 'm12d', 'So I was riding my SoroSuub XP-34 across the dunes when this dumb animal decides to attack!  I lost control and ran right into the monster. I almost died in the crash, and the creature destroyed my landspeeder. The insurance from the wreck was enough for a down payment on the new XP-38, with just enough left over for a little reward. I may not be able to rid Tatooine of the entire species, but at least I can do my part and get rid of this one and its family. Go hunt it down and destroy its lair.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 51, 'm12l', 'A young man wants revenge on the animals that attacked his landspeeder.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 52, 'm12s', 'So you killed them all, huh?  Wish I could say I was happy to hear that, but I''ve had a change of heart. The Force was with me on the day of my accident.  I almost became one with it, but I survived. It wasn''t that animal''s fault for attacking; it was just doing what comes naturally. Now, I''ve only made things worse by seeking revenge. But here is your reward. You are a brave person for taking on such a dangerous mission. As for me, I think I''ll be taking the XP-38 back and using the credits to help those beasts. Yeah, that sounds like it might be the right thing to do.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 53, 'm12t', 'Lanspeeder Attack'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 54, 'm13d', 'Hi there, friend. I''m new to Tatooine, not to mention the farming business. Can''t say I know much about it really, but I''ve been entrusted with an old moisture farm. Problem is that it was abandoned for so long that some of the larger creatures have taken up permanent residence in the area. I have a hard enough time figuring out how to run the moisture vaporators, the last thing I need is to be looking over my shoulder all the time. If you could help me out by getting rid of these animals for me, I''ll make it worth your while. Might even throw something extra in if for you. All you have to do is destroy their lair.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 55, 'm13o', ''),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 56, 'm13s', 'Thank you so much, my friend!  It will be so much easier to get this place up and running now.  When everything is back to normal, you are more than welcome to come by and see what you have made possible.  This place isn''t much, I know, but it is more than I thought I would ever own. Now, I''m going to be able to keep it thanks to you. Here''s your payment and a little something extra, as promised.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 57, 'm13t', 'Farm Reclamation'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 58, 'm14d', 'I was heading out to Beggar''s Canyon in my skyhopper when the secondary gyrostabilizer control shorted out. It''s not impossible to fly that way, but you don''t want to shoot the canyon without secondary control. So I made a quick landing and started to make repairs. Unfortunately, I landed a little too close to an area that some dangerous creatures were calling home. Luckily for me they seemed to think the T-16 was a bigger threat than I was, and went after it instead. I managed to run away and used my scomplink to call for a ride home. But my Skyhopper is still out there (hopefully), and I need someone to take care of those things before I can get to it. Just take out the lair, and the creatures should move on. Please help me get my old T-16 back. If I can''t be a pilot, I may never make it off this dirtball.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 59, 'm14o', 'Deak'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 60, 'm14s', 'You did it! And just in time. I just heard back from an old friend of mine who might be able to get me a job piloting Rebel transports! Now, thanks to you, I can take my skyhopper to meet him. What''s even better is I can show him some of the new stunts I''ve been perfecting while he has been offworld! Thanks a lot for fending off those things! I never would have had the guts to take them on. Reward funds should be in your account by the time you read this.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 61, 'm14t', 'Help me get my T-16 back!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 62, 'm15d', 'Let me tell you a story: over four thousand years ago, Tatooine was home to Sidrona Diath, one of the greatest Jedi who ever lived. He grew up right around here, in a failed mining colony. While he was alive, he defended all of Tatooine''s peoples against a host of enemies, including ferocious creatures that would do us harm. Sadly, Diath was killed at the Battle of Basilisk. Though his son continued in his father''s footsteps, not since Sidrona has Tatooine had a true champion. And we are in need of one now. In the four thousand years since Sidrona''s death, Tatooine has been overrun by every manner of threat, but it''s the creatures that concern us most now. They have taken complete control of the desert. Moisture farmers are killed every season, and travelers are lost with frightening regularity. Even small towns and Jawa sandcrawlers are attacked by the bold monsters. Even if you''re in league with the Hutts, there''s no safe haven to be found on Tatooine.\n\nThe planet needs a new defender to continue Sidrona Diath''s good works. If you think you are worthy to take up his mantle, go forth and destroy the lair that I have located. This might seem like a small, simple act, but it is one step towards freeing Tatooine from the monsters that infest the desert. As you begin your journey, take heart in Sidrona Diath''s own words: "Koroght Gaghght Takt," which in the common tongue becomes "Blessed be your going out from us." May your travels be safe and fruitful.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 63, 'm15o', 'Alaikai Trotter, Tatooine Historian'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 64, 'm15s', 'The Force is with you, hero. Somewhere, Sidrona Diath is smiling on Tatooine. It seems there is at least one champion on this planet willing to defend us from danger. As a gift, I give you a handful of credits. I hope you will use them to arm yourself in order to continue your crusade against Tatooine''s monsters.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 65, 'm15t', 'Diath''s Shadow'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 66, 'm16d', 'I don''t normally deal with your sort, so forgive me if I fail to follow proper protocol. As Imperial Governor of Tatooine, I usually rely on Prefect Talmont to deal with all disturbances and other military matters. Unfortunately, he handles every situation with far too much force. The Empire should not send an entire squad of stormtroopers into the desert every time some Tatooine local complains about rock mites or womp rats. Such wasteful military operations drain thousands of credits from my Imperial expense account every season. To stop this financial hemorrhaging, I will no longer allow Talmont to send Imperial loyalists into the desert in search of monsters. However, I am willing to use my own personal funds to pay mercenaries like yourself to combat these creatures instead. According to Talmont''s data, our patrols have located the lair of some despicable Tatooine beast. Go now and destroy it, and then the reward shall be yours.  '),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 67, 'm16o', 'Governor Tour Aryon'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 68, 'm16s', 'I am impressed. You have served me well. By taking it upon yourself to destroy the creature lair, you have saved my Imperial expense account thousands of credits, which I plan to use to renovate my quarters in Bestine. Although Imperial officers are not known for keeping their word, I have honored our contract and transferred a reward to your own account. '),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 69, 'm16t', 'Governor''s Agent'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 70, 'm17d', 'Yes, I admit, I''m a hateful man. I hate Prefect Talmont and Governor Aryon for having more power. I hate this suns-blasted planet. I hate the sand, and the heat, and the stinking Jawas. But, most of all, I hate it when one of my men is placed in danger. I''m the Chief of Police in Mos Eisley, and Prefect Talmont has my troops running all over the desert on their little errands. Lately, though, we''ve been facing more and more dangerous beasts in the interest of "keeping the peace." Call me paranoid, but I think the Talmont is trying to get rid of me.\n\nTalmont just assigned my men yet another lair to destroy. But I''m not about to walk into a death trap. So, the only solution is to hire some blaster jockey or muscle-bound brawler to handle the creatures for me. Do this task for me, and I''ll find a way to get some of Talmont''s credits into your account. '),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 71, 'm17o', 'Lieutenant Harburik'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 72, 'm17s', 'I suppose you''re not completely worthless. You did conduct yourself admirably in the field, and completed the assignment I gave you. Most importantly, you kept my men out of danger. Prefect Talmont might complain about the fact that I hired a free agent to deal with trouble on Tatooine, but I don''t care: as long as I''m still alive and have my wits about me, Talmont had better watch his scaly back.\n\nAs promised, I did siphon some funds from Talmont''s Imperial expense account. They''re yours now. I''d spend them quickly, before Talmont manages to track them down.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 73, 'm17t', 'Excessive Force'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 74, 'm18d', 'We were once respected on this planet. "Chachi and Ohwun De Maal run the finest docking bays in all of Mos Eisley," they would say. "They can be trusted with any ship, and any secret. They''re honest Duros." Sure, we greased the servomotors from time to time, paying off Lieutenant Harburik or Prefect Talmont when necessary. And we showered Jabba with gifts to ensure his protection. But ever since that Corellian smuggler defied quarantine and lit out of Docking Bay 94 amid a storm of Imperial blaster bolts, we''ve lost our good name. It took us almost an entire season to prove our innocence, and we still get suspicious stares. In order to show the people of Tatooine that we aren''t criminals, we''ve decided to do our civic duty and help clean up the desert. Jabba and the Imperials certainly aren''t going to do it... We have the extra credits, and we''re going to use them to reward anyone - even smugglers - who can destroy the lairs of predatory creatures on Tatooine. If you''re interested, just take the coordinates that we''ve provided and blast those monsters and their home to dust.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 75, 'm18o', 'Chachi and Ohwun De Maal'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 76, 'm18s', 'We have to admit, we weren''t sure you were cut out for this job when we hired you. But you''ve proven a good addition to our team. By destroying that lair, you''re helping to prove that we really are interested in the fate of Tatooine. We aren''t the greedy, immoral Duros that everyone would believe. The credits we''ve paid you are credits well-spent.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 77, 'm18t', 'Clear our Names'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 78, 'm19d', 'I own Spaceport Speeders, Mos Eisley. Business is bad, very bad. Most of our credits come from repairs. My mechanic, Geordi Hans, he is good with fixing landspeeders, great at haggling with Jawas, and a remarkable landspeeder pilot. But he''s no good with a blaster. And trips from Mos Eisley to visit the Jawas are now nearly impossible, due to monsters that roam the desert. I don''t want Geordi - who is pratically a hatchling - putting himself into danger. I''ll hire you to destroy the lairs of these creatures instead. But know this: the mission is extremely dangerous. You may die. You will probably be seriously hurt. But think of the credits that wait for you if you survive!'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 79, 'm19o', 'Unut Poll, Proprietor, Spaceport Speeders'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 80, 'm19s', 'Business will soon boom again! The lair is destroyed, and Geordi Hans, my very talented mechanic, is no longer afraid to travel the desert. He is planning a trip to meet the Jawas very soon. I''m sure that all his repairs will be completed within a few standard days, and the credits will be flowing into Spaceport Speeders again! It is a pleasure doing business with you.'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 81, 'm19t', 'The Mechanic'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 82, 'm20d', 'The Empire might tell you that nerf herders like me aren''t good for anything, and maybe they''re right. I certainly don''t enjoy being a nerf herder, especially now, when my entire herd is threatened by some slobbering, blood-drinking monsters. I have the heart of an adventurer, but not the weapons. I''ve found the lair of the creatures that have been killing my herd, but I wouldn''t even know how to destroy it. I do have some credits hidden away, though. I''d be happy to pay you to destroy the lair for me. '),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 83, 'm20o', 'Domo Jones'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 84, 'm20s', 'Hey, nice work! My buddy Blerx told me that no one would ever be able to stand up to those monsters, but you''re obviously tougher than anyone he''s met before. My nerfs are safe, and my credits are yours! Someday, I''m going to become a hero just like you...'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 85, 'm20t', 'Nerf Herder'),
('string/en/mission/mission_destroy_neutral_hard_creature_tatooine.stf', 86, 'number_of_entries', '20'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 1, 'm1d', 'A major Black Sun glitterstim lab, responsible for supplying the dealers of several systems, has been located by Imperial Intelligence. These crooks are so well-connected, however, that any signs of an organized attack by either law enforcement or the Imperial Military would scatter them throughout the sector. We need to insure this facility is hit hard and put out of commission for good. A select team of highly skilled independent agents ought to be able to take this refinery out. It will be heavily guarded and anyone succeeding will likely earn the emnity of Black Sun, but removing the lab would be a huge step in eliminating glitterstim dealing in this sector. Naturally you''ll be generously rewarded for your time and efforts. Do you accept?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 2, 'm1o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 3, 'm1s', 'Bravo, agent! Your results never cease to impress us. We''re glad to employ an agent as effective as you.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 4, 'm1t', 'Destroy glitterstim lab'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 5, 'm2d', 'We''ve located the hideout of a local branch of the notorious swoop gang, the Shadow Angels of Dathomir. These creeps move fast once word reaches them that the authorities are on their way. This is a job for a small group of skilled and dedicated agents. The right strike team can blast this hideout and all of those vicious criminals to pieces before they had a chance to even look around. We''ll pay a handsome reward for the successful completion of the mission. These gangsters are tough customers, though, so the agents who accept this mission should be highly trained and experienced in dealing with these types of situations. The coordinates will be sent upon the acceptance of the mission. Can we count on you?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 6, 'm2o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 7, 'm2s', 'These gangs are always braver in packs and even then they can''t put up a good fight when confronted with talent like yours? Job well done, agent. That reward is going to the right individual.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 8, 'm2t', 'Destroy swoop gang''s hideout'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 9, 'm3d', 'Jabba''s swoopers think they can move into any system they like and stake their claim, regardless of what other hard-working criminals are already in the area? Not while I have something to say about it. Big Gizz is wanting to expand his organization beyond Mos Eisley at the expense of my interests. I need a hardy band of skilled assassins to show these new "branches" of that cretin''s gang that the galaxy is a dangerous and treacherous place. I transmit the coordinates to the gang''s new hideout when you accept, and I pay a very generous reward when they''re gone. Sound like a deal?  '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 10, 'm3o', 'Lady Valarian'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 11, 'm3s', 'Chew on that, Big Gizz! Way to go, killer. Jabba will soon learn your name. That may be good or bad depending on how spicy you like life to get. Here''s your money. Don''t spend it all in one joint.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 12, 'm3t', 'Take on Jabba''s swoop gang'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 13, 'm4d', 'An illegal weapons manufacturing facility has been located by Intelligence. We believe it may be run by Black Sun. Many of the weapons bought and sold by gunrunners come from facilities just like this one. We need an experienced strike team to go in there and blast that installation into so much space debris. If you''ve worked for us before, you''ll know that our rewards are very generous but we expect results. These creeps will be well-armed, if nothing else, and will also likely be some of the best muscle Black Sun has to offer. Can you help us close this case?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 14, 'm4o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 15, 'm4s', 'Wonderful! Less deadly weapons in the hands of criminals means less risk for our law enforcement agents. We need more agents like you.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 16, 'm4t', 'Destroy weapons making facility'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 17, 'm5d', 'The vicious group of criminals behind one of Black Sun''s major protection rackets has been discovered by Intelligence. They apparently operate out of a fairly well-guarded stronghold and fear nothing short of a full Imperial Military strike. They''d get away long before such a strike could be organized and executed, however, so we would rather hire a small but experienced strike team to take care of those rogues for us. We believe that this group answers to Vigo Green, but cannot verify that information as of this date. We''ll transmit the coordinates to the team leader that accepts this mission. Our standard reward for this type of mission is in the offering as well. Do you think you can tackle this operation?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 18, 'm5o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 19, 'm5s', 'Excellent work, agent. This victory will make life easier for hundreds of merchants in this sector. Always a pleasure to work with a professional like yourself.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 20, 'm5t', 'Take out protection racket'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 21, 'm6d', 'Black Sun maintains several medical facilities that are open to any of their operatives. You can imagine how hard it would be for assassins, gangsters, and other criminals to get medical attention at their local clinics after a battle with local authorities. These facilities were created to answer that particular dilemma. We''ve located one of these centers and need it removed. We cannot afford to let these criminals patch themselves up after a scrape with our agents. These facilities are also used for major procedures like face reconstruction, to hide the identity of various underworld agents, and it''s even suspected that some contain cloning technology. We need someone to gather a small strike team of experienced agents to hit this installation. The standard rewards will be offered for this type of work. Do you think you can undertake this mission? '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 22, 'm6o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 23, 'm6s', 'Good work. The last thing we need are clones of infamous criminals running around causing havoc. Great way for crime lords to create the appearance of being "untouchable." You''ve earned this reward, my friend.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 24, 'm6t', 'Take out criminal hospital'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 25, 'm7d', 'Intelligence has managed to pinpoint the location of one of Jabba''s major munitions depots. These weapons supply gunrunners in this and several adjoining sectors. Jabba''s spies are scattered throughout our organization, however, and we suspect that any communiques between us and the Imperial Navy would be intercepted and transmitted to Jabba''s people. That would give those thugs plenty of opportunity to vacate the premises. Stealth is important so we need a small team of agents to infiltrate that depot and blow it to bits. It will be very well defended as Jabba makes quite a bit of money off his gunrunning operations. We''ll reward a job well done, of course. Are you the agent we''re looking for? '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 26, 'm7o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 27, 'm7s', 'You certainly are fearless, aren''t you? You''ve gained a powerful enemy, we fear, but also a very influential friend. Congratulations on your success.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 28, 'm7t', 'Wipe out Jabba''s munitions depot'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 29, 'm8d', 'One of Black Sun''s cadre of assassins has converted an abandoned mining installation into a stronghold specializing in training future killers. We can''t afford to let this assassin academy continue to operate. We''re offering a substantial reward to the strike team that can pull this off. Attacking a facility like this is no small matter. Some of the galaxy''s deadliest guns are to be found there, not to mention state-of-the-art defenses. However, if you want to make a name for yourself, then wiping this installation out offers a great opportunity to do so. You feel like making history, agent?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 30, 'm8o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 31, 'm8s', 'Now that was something. You should be working for Imperial Intelligence''s Burea of Operations, agent. Excellent job. You''ve definitely earned this reward. '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 32, 'm8t', 'Take out assassin''s HQ'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 33, 'm9d', 'Some incredibly shortsighted former members of my organization have decided that they''ve "outgrown" me. As if refining high quality glitterstim spice was child''s play and a career anyone could just jump into. Where do these thugs get their ideas? We need a specialized team of agents to help us teach these misguided rogues a serious lesson. The refining facility must be blown to atoms, and everyone inside must be vaporized. This is the lesson we must teach. Black Sun always makes things "worth someone''s time" so do not worry on that account. Do you wish to get into our good graces?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 34, 'm9o', 'Black Sun: Vigo Clezo'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 35, 'm9s', 'It''s operatives like you that allow a businessman like myself to sleep peacefully at night. Bravo. The reward and my gratitude are yours.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 36, 'm9t', 'Take out spice refiners'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 37, 'm10d', 'The Illustrious Jabba wishes to employ a small team of dedicated killers to help him teach a rival an important lesson in courtesy. Mighty Jabba does not consider it courteous for said rival to make attacks on his swoopers, regardless of where they choose to go. My lord''s interests are wherever he chooses to put them and in all cases Jabba''s claims to a region should always take precedence. Now Jabba requires that one of his rival''s strongholds be obliterated, along with everyone inside. If you consider yourself the type of agent Jabba prizes most, fearless and inventive, then you should accept this mission and endeavor to please the powerful Jabba. His generosity extends beyond the money you''ll receive for the completion of this mission. What is your answer?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 38, 'm10o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 39, 'm10s', 'Jabba is pleased with your results. The mone is yours. Seek us out again in the future.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 40, 'm10t', 'Destroy one of Valarian''s strongholds'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 41, 'm11d', 'A foolish Vigo''s sublieutenant involved with our profitable glitterstim trade has been skimming credits off the top of all our distribution. I''m not sure exactly why they thought we wouldn''t notice. Needless to say, this matter must be redressed immediately. We don''t want to risk an open war with the other Vigos so this situation must be handled by independent operatives and it must be made to look like a hit by pirates trying to make off with shipments of spice. The reward will be more than adequate for this job but will only come if the sublieutenant''s stronghold is completely obliterated. This scum is tough so whoever accepts better go in blasting. We''ll transmit coordinates when we have your acceptance.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 42, 'm11o', 'Black Sun: Vigo Perit'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 43, 'm11s', 'Results we can see will always lead to bigger and better assignments. Good work, agent. You may have a future with Black Sun. Perhaps even rise to the level of Vigo yourself.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 44, 'm11t', 'Take out cheating spice dealer'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 45, 'm12d', 'Independent thought is wasted on assassins. First, they get used to everybody doing what they say. Then they fall victim to the lure of millions of credits passing through their hands. Next thing you know, they think they can run the operation better than their superiors. They get these warped visions of bumping off the boss and lots of smiles and handshaking and pats on the back... The job of a Vigo is not an easy one, my friend. \n\nWe need some skilled assassins to take out some skilled assassins. Unlike your targets, we hope that you and your team know your place in the universe and accept it. Last thing we need is more killers who think they should be running things. A substantial reward awaits the successful removal of these upstarts. You accept the mission and we''ll tell you where you and your team need to go. We hope you won''t mess this up. We''ve had too much of that recently in our organization.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 46, 'm12o', 'Black Sun: Vigo Durga'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 47, 'm12s', 'Well handled. You and your team are glowing examples of what hired killers should be: obedient and efficient. Claim your reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 48, 'm12t', 'Hit the hitmen');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 49, 'm13d', 'These pirates are almost as bad as those hotshot smugglers. If any of these rogues get the tiniest drop of notoriety, it goes straight to their heads. Suddenly they think they can set their own rules, do whatever they like, and ignore their benefactors. The result is nothing but headaches and work for us, but it also means good fortune for independent agents like yourself. We need a pirate band taken down. They''ve become too much of a liability for our organization and must now be squashed. A small elite team of troubleshooters ought to be able to take care of this situation with little trouble. If you''ve worked for us before, you know our pay is quite generous. If this is your first time, then prepare to be pleased when all this mess is settled. We''ll send the coordinates to the pirate''s lair upon receiving your acceptance.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 50, 'm13o', 'Black Sun'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 51, 'm13s', 'Excellently done, agent. Your resourcefulness is most inspirational - a shining example to hired guns throughout the galaxy. Enjoy your lucre.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 52, 'm13t', 'Remove the thorn'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 53, 'm14d', 'When pirates are hired to perform a job, they should stick to it regardless of the consequences. What''s happening to professionalism in our circles? A renegade band of pirates has decided that they can keep the credits given to them for the performance of certain duties regardless of whether those duties were adequately performed or not. It is my responsibility to teach these slugs a lesson. I''m offering a reward to the team of hired killers that can infiltrate this band''s base and blast it (and them) to pieces. If you accept, you''ll be told where to go. These pirates are not likely to go down without a fight, so I''d blast first and ask questions later if I were you. Do you think you could take care of this problem for me?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 54, 'm14o', 'Black Sun: Vigo Clezo'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 55, 'm14s', 'Good to see that some scum still care about professionalism. Good for you. Come look me up again when you need more work.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 56, 'm14t', 'Help clean out the pirate gene pool'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 57, 'm15d', 'I''ve yet to meet someone who got into trouble by sticking to doing what they do best. It''s only when a few malcontents, not happy with the status quo, try to do something different that we get problems. Or at least I do. Pirates aren''t freedom fighters, right? You know that, I know that, everyone knows that. Pirates are thieves and murderers. That''s what they do. And that''s exactly what I need a small team of hired guns to explain to some former associates who''ve got it in their heads to help the Rebellion. Not on my watch. These scum think they can wipe their past clean by helping some moisture-farmers-turned-Rebels get themselves slaughtered by stormtroopers? Their case of sudden conscience is costing me too much money. Accept the job and I''ll tell you where you need to go. Leave no walls standing. I want to make sure this conscience-acquiring is not contagious.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 58, 'm15o', 'Black Sun: Vigo Green'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 59, 'm15s', 'Finally, someone who knows what they''re good at and stick to it. A long, happy life will likely be yours, friend. Come see me again soon.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 60, 'm15t', 'Destroy pirates with a case of conscience'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 61, 'm16d', 'One of the galaxy''s most notorious and bloodthirsty band of pirates has fallen for our trap. They took some bait we offered and raided a ship full of tainted cargo. We planted undetectable homing beacons inside that cargo and now the pirates have led us right back to their lair. Their base sensors are rather sophisticated, however, so they would detect the approach of Imperial cruisers and escape into space before we could strike. We need a team of highly skilled and experienced agents to land near their base and take it out. The pirates would not react to the arrival of a standard transport as they''re used to monitoring that sort of activity in their system. Are you the sort of operative that could assemble such a strike team? The Empire is counting on you, citizen. '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 62, 'm16o', 'Imperial Navy'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 63, 'm16s', 'An excellent strike. The Empire is indebted to you, agent. Perhaps you should contact us about helping to crush the Rebellion. We could use agents like you.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 64, 'm16t', 'Smash the notorious pirates'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 65, 'm17d', 'Normally I wouldn''t care about the activities of pirates but these particular ones happened to strike a slaver ship on its way to deliver a shipment of Twi''lek exotic dancers to me. Even after the pirates discovered who this shipment was intended for, they still decided to sell the slaves on their own and keep all the profits. This matter must be resolved. I cannot allow pirates to seize what I have rightfully stolen - if word of this spreads it could weaken my position with Jabba. I therefore have need of a team of deadly killers to rid me of this embarrassment. One of the Twi''lek girls had a homing chip implanted in her thigh (a special gift intended for one of Jabba''s rivals) which has allowed me to discover where these slugs are hiding. Accept the mission and the coordinates are yours. Leave no witnesses and burn their lair to the ground.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 66, 'm17o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 67, 'm17s', 'Well done. Accept this reward and look me up again soon.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 68, 'm17t', 'Blast the errant pirates'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 69, 'm18d', 'Jabba claims he doesn''t want a war and then arranges for pirates to hit ships carrying goods intended for me. If that gargantuan worm thinks I can''t see who''s behind these recent attacks, he''s as stupid as he looks. As much as I know that Jabba is baiting me, I must respond or I risk other pirates trying their hands at plucking my cargo. This mission won''t be easy but it will pay very well. Jabba is known to employ the most ruthless and dangerous pirates in the trade. But a resourceful team of agents, skilled in teamwork and deadly with their blasters, should be able to pull it off. You fancy yourself such an individual? If you think so I''ll send you the coordinates to the pirates'' lair. '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 70, 'm18o', 'Lady Valarian'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 71, 'm18s', 'I had a hunch about you. You seemed to be the type to get results. Congratulations on a job well done. Enjoy the reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 72, 'm18t', 'Swat Jabba''s pirates'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 73, 'm19d', 'Mighty Jabba''s wrath is a powerful and dreadful thing to incur - few rational beings wish to risk it. This band of pirates, it seems, do not share that particular rationality. They have been raiding my lord''s spice shipments with impunity and this must stop. My lord was wise enough to have planted a spy in their midst months ago, suspecting that this particular band might try to double-cross him in the future. Thanks to my lord''s wisdom, we know the location of this band''s hidden base. Illustrious Jabba wishes me to hire the best assassins credits can buy and instruct them to practice their trade on these foolish rogues. Do you wish to take advantage of this opportunity to earn both my lord''s favor and a substantial reward? '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 74, 'm19o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 75, 'm19s', 'Most effective. You serve my master well and you will be rewarded.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 76, 'm19t', 'Help a Hutt make a point'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 77, 'm20d', 'One of the major areas of concern for the Corporate Sector Authority is piracy. Our ships in particular draw those predators like skettos to a sleeping dewback. Recently we''ve discovered that many of these pirates have banded together to form some sort of "Brotherhood." By sharing information about transport movements, safe spaceports, and Imperial activity, these rogues can insure a higher rate of success for their comrades. We''ve used our resources, mostly in the form of bribes, to pinpoint the locations of some of the busiest spaceports used by this Brotherhood. We offer a substantial reward to anyone who can make sure these ports are knocked out of commission. There''s plenty of work doing that as these criminals have dozens of these havens. Coordinates will be transmitted upon your acceptance. '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 78, 'm20o', 'The Corporate Sector Authority'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 79, 'm20s', 'Good work. Remember there''s plenty more of those havens out there. We''ll continue to pay as long as you continue to produce results.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 80, 'm20t', 'Wipe out the pirates'' haven'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 81, 'm21d', 'Every successful businessman deserves a luxurious retirement.  No one is denying that.  But a player is expected to settle all bets before cashing out of the game.  That is where a certain ex-employee of mine has failed.  He was one of the most successful pirates on my payroll.  A prolific provider for many standard years.  He retired with my personal blessing.  Unfortunately I have learned that he hid an old debt from me, and has rebuked my requests for payment.  I have extended every courtesy to him, but the time has now come to finalize negotiations.  I require a crack team of assassins to hit him hard and leave no one standing.  Only the deadliest killers need apply.  He knows I''m coming, so he has fortified himself in a stronghold and gathered a small army of the toughest scum in the sector.  Tear the place to the ground and you shall be very well compensated.  Contact me for his coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 82, 'm21o', 'Black Sun: Vigo Green'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 83, 'm21s', 'Very well done.  Have I hired you before?  You have the skill and the guts to be a player yourself.  You would make an excellent asset to my organization.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 84, 'm21t', 'Retire an ex-pirate for good'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 85, 'm22d', 'They say lucre makes the galaxy spin and I have always found that to be true.  My various industrial enterprises have made me one of the most influential Neimoidians in nine sectors.  I have assets spanning a hundred systems.  When you attain such success, however, you become an attractive target for professional thieves.  I am no exception.  I have just discovered that one of my industrial villas has been overrun by several pirate crews.  Luckily a good businessman knows how to distribute resources to safeguard his investments.  I wish to disburse a very large sum of credits to a group of soldiers-of-fortune who have the means and the wherewithal to dislodge these slugs from my property.  Be warned: they are well-equipped and extremely dangerous.  I am paying for the best of the best, so don''t waste my time if you''re anything but elite.  Also, I shall shed no tears if the villa itself sustains heavy damage, as I intend to collect an insurance disbursement and shut the place down anyway.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 86, 'm22o', 'An Influential Neimoidian'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 87, 'm22s', 'Your work was sloppy in one or two particulars, but you did complete the task at hand.  Good job leveling the villa.  Do enjoy this payment.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 88, 'm22t', 'Dislodge pirates from my industrial villa'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 89, 'm23d', 'Oh, can''t someone please help us?  My family rules a small but beautiful planet in Xappyh Sector.  Long ago we built an outpost to tend the needs of the poor and downtrodden in nearby systems.  But calamity befell us when our outpost was captured by the crew of a large and terribly frightening pirate frigate.  We would like to remove them so that we can resume helping the needy of the galaxy; but the regional governor has refused to lend us aid.  We are a peaceful planet and have no weapons.  We do have money, though, with which we shall gladly part if it means we can have our outpost back.  Are there no stalwart heroes left in the universe who will come to us in our hour of need?  These pirates are a cruel and awful lot and we are frightened that they might do harm to the poverty-stricken areas near them.  Money is no object.  Please, just help us!'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 90, 'm23o', 'A Desperate Princess'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 91, 'm23s', 'You did it!  It''s a shame about the outpost being destroyed, but I just know that you did your best to protect it.  Please, take your reward and know that you are always welcome on my planet, where I will treat you to every pleasure my humble palace can provide.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 92, 'm23t', 'Help us in our hour of need'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 93, 'm24d', 'Mighty Jabba is always looking for new talent to add to his organization.  After some recent personnel issues, he has decided that all new recruits must prove themselves in a practical demonstration of their skills.  Illustrious Jabba wishes me to provide one such audition for a hit team.  To warrant their abilities, these assassins will be required to break into the landing bay of an especially lethal pirate captain and blast the entire facility into its component atoms.  Upon the completion of this task I shall present a report to the Invincible Jabba, who will render a decision on the worthiness of the applicants.  Wise job seekers should be aware that I do not take my duties lightly.  Only the finest and most despicable assassins deserve my attention; others are highly discouraged from occupying my precious time.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 94, 'm24o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 95, 'm24s', 'You have demonstrated no small amount of skill.  I shall bring your case before the Illustrious Jabba.  Until you hear from us again, enjoy this well-earned payment.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 96, 'm24t', 'Audition for the Mighty Jabba'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 97, 'm25d', 'These smugglers develop reputations, they think they can get away with anything. What they fail to recognize is that organizations like ours help forge those reputations - and we can destroy them just as easily. One of these smugglers has gotten a bit too greedy for their own good. They think that by surrounding themselves with armed thugs, they can ignore certain rules and tariffs. We''re about to prove them wrong. A substantial reward awaits the operatives who will drive this point home to this errant smuggler. If you''re the type of killer we think you are, this should pose no problem for you. Do you want the job?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 98, 'm25o', 'Black Sun'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 99, 'm25s', 'Congratulations. Those are results that make us proud. Stick with us and you''ll go far. '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 100, 'm25t', 'Take out the errant smuggler'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 101, 'm26d', 'No one cheats a Vigo of Black Sun, especially when that Vigo is Durga the Hutt. Apparently this simple truism has escaped a certain band of smugglers formerly working for the illustrious Vigo on Nar Shaddaa. They''ve made off with a rather large shipment of high-grade glitterstim spice that was supposed to be delivered to Vigo Durga himself. Well no business is without its perils, I suppose. Vigo Durga will pay a handsome reward to anyone who can send these smugglers back to their makers. These are the coordinates to the smugglers'' hideout. Make sure there are no survivors and no witnesses. Can Black Sun rely on your cooperation and discretion?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 102, 'm26o', 'Black Sun: Vigo Durga'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 103, 'm26s', 'Most excellently done. Vigo Durga sends his congratulations and asks that you contact us again in the future. Enjoy your reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 104, 'm26t', 'Remove a band of smugglers'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 105, 'm27d', 'Spice smugglers can be so untrustworthy. A recent shipment of spice came up dreadfully short. Unfortunately this shipment was under Vigo Clezo''s supervision, which made him look bad in the eyes of the rest of Black Sun. These offending smugglers must be made to pay for this embarrassment with their lives, of course. Nothing less would satisfy the wounded Vigo''s pride. Here are the coordinates to their hideout. Please be efficient and precise. Vigo Clezo likes to run a clean, tight ship. A substantial reward awaits your safe and successful return.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 106, 'm27o', 'Black Sun: Vigo Clezo'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 107, 'm27s', 'A true professional. Now you are the sort of operative Vigo Clezo is proud to employ. The reward is yours to claim.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 108, 'm27t', 'Help a Vigo get payback'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 109, 'm28d', 'It has been recently brought to our attention that a group of trusted couriers is actually a collection of Imperial Intelligence agents. This is most distressing, as you can imagine. We need these couriers removed and are willing to pay well for this service. Here are the coordinates to a base these couriers use most often. The base is to be obliterated and every courier is to be eliminated. We do hope this is very clear. The Empire really should know better than to try and infiltrate our organization with these sorts of agents. It always leads to a tragic loss of life and talent. Are you our agent?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 110, 'm28o', 'Black Sun'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 111, 'm28s', 'Your actions were those of an exemplary agent. Your success will reap rich rewards and lead to a very profitable future with us.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 112, 'm28t', 'Take out Imperial moles'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 113, 'm29d', 'It is a shame when talented individuals must be eliminated. One of our most experienced smugglers has been convinced to become an informant for the Rebellion. Now normally, we wouldn''t care what the Rebels were up to. They keep the Imperials distracted, which is all we can really ask for from anyone. However, we''ve learned that this smuggler is selling some of our most precious secrets to the Rebels - that we simply cannot have. A generous reward awaits the agent who can take this smuggler and their band of associates out. '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 114, 'm29o', 'Black Sun'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 115, 'm29s', 'Good form, agent. That was nicely done. Our organization could use more operatives like you.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 116, 'm29t', 'Wipe out the smuggler informants'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 117, 'm30d', 'The mighty Jabba the Hutt seems to be having a rather bad year in regards to smugglers. It''s not enough that the loathsome pirate, Han Solo, has evaded my master''s attempts to capture him, but now it seems another band of smugglers have been inspired by Solo''s actions to defy the powerful Jabba. For reasons of his own, His Exaltedness has decided not to approach the Bounty Hunters'' Guild with this matter (given their recent troubles) but has instead decided to find some enterprising free agents to settle things. We have the coordinates to the lair of these walking corpses. As always, His Immenseness offers an overly generous reward for the accomplishment of this task. Can the honored Jabba count on you to serve him faithfully?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 118, 'm30o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 119, 'm30s', 'Well done, agent. Jabba will remember your success next time you come to us for a job. We always reward success.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 120, 'm30t', 'Help Jabba get even'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 121, 'm31d', 'That slug Jabba has done such a good job of convincing the smugglers of the galaxy that they all work for him, that it makes life for the rest of us a bit more difficult. A group of these smugglers, well known gunrunners, made off with one of my weapons'' shipments, thinking they could just sell it to Jabba for more money than they would have gotten for simple smuggling. That notion has got to be corrected. I''m offering a hefty reward to the individual or band that will blast these smugglers into space junk. We have the coordinates to their base, not that they were difficult to acquire - these guys think they''re untouchable. So how about it? You in?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 122, 'm31o', 'Lady Valarian'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 123, 'm31s', 'Effective. A bit crude, perhaps, but effective. Here are your credits. There are more where those came from if you need more work.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 124, 'm31t', 'Dish out Lady Valarian''s wrath'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 125, 'm32d', 'The exalted Jabba seems to have lost some of his most trusted smugglers recently to his rival, Valarian. It seems the wanna-be crime mistress hired thugs to blast some of my master''s loyal servants. The mighty Jabba would like to repay kind with kind. These are the coordinates to a base belonging to some of Valarian''s most trusted couriers. Make sure every one of them is blasted to bits and the base is burned to the ground. We wouldn''t want people thinking that Jabba was less cruel than some mangy Whiphid, now would we? A generous reward waits at the end of a successfully completed mission.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 126, 'm32o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 127, 'm32s', 'Excellent. Now the galaxy will understand the lengths Jabba is willing to go to protect his assets. You''ve earned your reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 128, 'm32t', 'Jabba''s revenge'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 129, 'm33d', 'The Imperials attempted it so I suppose it shouldn''t surprise us that the Rebels took a stab at it too. We''ve discovered that some of our smugglers are actually Rebel double agents collecting information for the Rebellion and spying on our activities for use as leverage in future negotiations. As you can imagine, we need these agents removed and a clear signal sent to the Rebellion. They of all people should know that if you play with fire, you will get burned. These are the coordinates to this group''s base of operations. Blast it to pieces and wipe out the double agents. Hopefully we''ll only have to do this once. Can you help with this? '),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 130, 'm33o', 'Black Sun'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 131, 'm33s', 'Most impressive, agent. Especially given that those smugglers were likely highly trained Rebel commandos. Do see us again for future work.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 132, 'm33t', 'Wipe out Rebel double agents'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 133, 'm34d', 'Illustrious Jabba wants to make sure that the smugglers operating in this galaxy answer to him and him alone. Some of these smugglers have been operating exclusively for one of his chief rivals, and the powerful Jabba wishes to make an example of them. He offers a sizable reward to anyone who is brave enough to march into these smugglers'' base and blast it to pieces, along with all the smugglers inside, of course. We''ll supply the base''s coordinates and the reward (should the mission be successful). You must supply the muscle and the blasters. Do we have a deal?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 134, 'm34o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 135, 'm34s', 'What a glorious example this sets. The mighty Jabba is pleased. Claim your reward and do visit His Immensity on Tatooine soon.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 136, 'm34t', 'Instruct a rival'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 137, 'm35d', 'Some hotshot smugglers have decided to cheat a powerful Vigo and make him lose face in the syndicate. Just because these smugglers have the trust (which they believe translates to "protection") of several other Vigos, they think they can push a smaller Vigo around. We''ll soon see who''s small and who''s not in Black Sun. You mess with any Vigo, you flirt with death - simple as that. A substantial reward is in the offering to anyone who can teach these arrogant scum a lesson. I want those hotheads dead, I want their base burned down to the ground, and I want to spit on the ashes! You think you can help me do that?'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 138, 'm35o', 'Black Sun: Vigo Green'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 139, 'm35s', 'Yeah! That''s what I''m talking about! Let''s see who''s laughing now, huh? Good work, buddy. Take your money and remember who treated you right.'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 140, 'm35t', 'Assuage a Vigo''s paranoia'),
('string/en/mission/mission_destroy_neutral_hard_npc.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 1, 'm1d', 'CEC creates and abandons prototype testing grounds frequently, to discourage industrial and military espionage. Unfortunately, one testing facility in the Corellian wilderness was apparently compromised even during construction. Certain research reports created at this facility have already shown up on black-market slicer data exchanges. Because we are not yet ready to abandon this facility, we have traced the leak and located the gangsters responsible. To discourage further espionage, we are commissioning experienced strike teams to destroy their base and all data stored there.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 2, 'm1o', 'Corellian Engineering Corporation'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 3, 'm1s', 'We oversaw your progess and were pleased at the result. Your fee is attached. Thank you for doing business with CEC.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 4, 'm1t', 'Testing Facility Has Espionage Problem'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 5, 'm2d', 'To test our new personal defense system prototype, we attached it to our office protocol droid, then sent him into remote wilderness. He complained, but then, he always complains. Seems the prototype has a design flaw in the prototype, because gangsters blew up the droid and stole the prototype. We''re writing off the droid, but we need to prevent further industrial espionage. Staffers are busy right now checking our earlier models for the same design flaw, so we''re hiring you to go and destroy the gangster base at the droid''s last known coordinates. It''s okay if you destroy the prototype, because it''s too flawed to save.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 6, 'm2o', 'Corellian Technologies'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 7, 'm2s', 'Okay, thanks for eliminating that particular espionage problem. But we have them all the time, so expect to hear from us again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 8, 'm2t', 'Stolen Personal Defense Prototype'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 9, 'm3d', 'Ever since we''ve been stationed out here in the wilderness for a big training exercise, criminal lowlifes have been sniffing around our medical supplies like Jawas at an astromech''s birthday party. Now we''ve lost a crate of ion beamers to some black-market Hutt-lovers with more tentacles than brain cells. I want you to find those smugglers and give their base the Alderaan treatment. I don''t actually have a budget for this kind of operation, but don''t worry, I''m scraping the surplus out of the orotay-filter replenishment fund.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 10, 'm3o', 'Corellian Defense Force Mobile Medical Unit 4-077'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 11, 'm3s', 'Boyoboy, you have launched my personal Star Destroyer into hyperspace, believe you me! Here''s your fee. Sorry, gotta go, we''ve got incoming!'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 12, 'm3t', 'Mobile Hospital Has Smuggler Problem'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 13, 'm4d', 'Over the millennia, our company has always coped with protests. Certain individuals or organizations, though they mean well, fail to understand the importance of armaments to the Corellian economy. We take strong issue with these protesters only when they try to sabotage our factories and attack our workers. Such terroristic efforts are beneath the Empire''s notice. But to protect our Corellian quality of life, this company hires independent contractors to remove these threats. In the one at hand, a radical group has hired gangsters to assault our factories. We now offer you the opportunity to destroy the gangster base.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 14, 'm4o', 'Corellian Engineering Corporation'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 15, 'm4s', 'Violence is inherent in the nature of most successful species. There will always be a need for weaponry. If this company doesn''t satisfy that need, another will. Thank you for demonstrating this wisdom to these protesters.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 16, 'm4t', 'Violent Protests Against CEC Operations'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 17, 'm5d', 'Found only on Corellia, the mineral tursturin is prized because it generates tremendous power when superheated. Corellian Technologies has contracted to build tursturin-powered repulsors for a cloud city in the Expansion Territories. Industrial saboteurs have made two failed attempts to steal our tursturin supply, and in the last attempt our probe droid tracked them to their lair. Police or Imperial involvement would create unfortunate legal entanglements, due to the tursturin''s provenance. Instead, we wish to hire an independent strike team to destroy the saboteurs and their stronghold. Expect heavy opposition and a correspondingly high reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 18, 'm5o', 'Corellian Technologies'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 19, 'm5s', 'Your action in destroying the saboteur stronghold has helped us complete the current tursturin repulsor on schedule. More remain in our contract, and more threats loom, so expect to hear from us again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 20, 'm5t', 'Tursturin Supply Attacked by Saboteurs'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 21, 'm6d', 'For this assignment we require utmost discretion. The Black Sun criminal organization is setting up a remote base from which to plunder our company''s stocks of chronamite. This valuable mineral can be refined into metal, but is also useful in our field -- and to the Black Sun -- as a poison. From past experience we know the local Security Force is heavily infiltrated with Black Sun spies. We must instead hire an independent strike team to destroy the criminal base, while we relocate out chronamite supplies to a new, better guarded location.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 22, 'm6o', 'Corellian Chemical Corporation'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 23, 'm6s', 'Thanks to your quick action, our company has had time to move the chronamite to a heavily guarded warehouse. Your fee is attached.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 24, 'm6t', 'Black Sun Stealing Chronamite'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 25, 'm7d', 'After I made a nice haul in corusca jewels, I retired here to Coronet. But I''ve had a real urge to get back at my old smuggling "partner," who sold me out to the Empire years ago. He made his own fortune off that betrayal, but he never found out I escaped from Imperial Security. Now, the usual script says I should arm myself to the teeth and storm his fortified bunker, so I can shoot him down like the mynock he is. But you know, I''ve got a family now, and there''s lots of good programs on the HoloNet. So, I ask myself, why risk my life when there''s a hungry strike team out there willing to do it for me? Want a nice reward? Go to these coordinates and blow away everybody and everything you see there.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 26, 'm7o', 'Living the Corellian Dream'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 27, 'm7s', 'Thanks, friend, for blowing up that old partner of mine. I feel all redeemed and everything, and I never even had to leave home. Here''s your pay -- you earned it!'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 28, 'm7t', 'Earn My Revenge While I Stay Home'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 29, 'm8d', 'Sometimes a Bothan reaches his limit, and then there''s hell to pay. I run a shuttle business between Coronet and Tyrena. The nature of my clientele sometimes requires me to make detours from my documented flight path. Lately I''ve been harrassed by a competitor with a strong presence in the less-populated regions of Corellia. He''s been driving dangerous animals into my designated landing zones, presenting a serious threat to myself, my crew and my clientele. I''ll deal with the animals separately, but I need to hire a strike team to take out my competitor''s headquarters. This man and his lackeys are very well entrenched, so I need tough and experienced shooters for the job. Tell me you can do it and I''ll send you the coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 30, 'm8o', 'A Bothan On the Edge'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 31, 'm8s', 'Very nice indeed. You''d make a good security agent for a shuttle business like mine. Maybe I''ll have a look at my budget and see what I can do.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 32, 'm8t', 'Had Enough of Unscrupulous Competitor'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 33, 'm9d', 'Hutts on Corellia. Doesn''t that beat all. I fly home after a stretch on Naboo and my own planet is slimy with one of these filth-worms. I''m not one to start a fight, but when a gangster''s cronies start harrassing my friends I won''t take it sitting down. The Hutt I''ll handle myself, but I need someone who''s good in a scrap to cover my back.  Tackle his thugs at the location I give you and I''ll make it worth your while.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 34, 'm9o', 'Thanus March, Freelance Spacer'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 35, 'm9s', 'Nice job. I''ve flown the Spine long enough to know that we can''t tolerate a Hutt getting comfortable here. This one won''t make the same mistake again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 36, 'm9t', 'A Hutt on Corellia -- Isn''t That a Kick'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 37, 'm10d', 'The Null Racket might be the fastest Corvette in the sector, but even I get boarded sometimes. When Imperials net me, all I can do is bite the blaster. But when a pirate crew gets the drop on me, I can return the favor planetside. That''s where I stand right now. I need to hire a freelance strike team to hit the hangout of a certain Reego Hinterstar. He robbed my cargo and I want it back, or I could lose more than just my fee. If you''ve got the men and the grit to take down a hardened space pirate, I want to talk to you.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 38, 'm10o', 'Captain Sava Matar of the Corvette Null Racket'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 39, 'm10s', 'Niiice. After you started shooting, Reego didn''t know which way was up. I got my cargo back, too. You''ve got a future in the business of killing, my friend. Ol''val.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 40, 'm10t', 'Take Down Hardened Space Pirate'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 41, 'm11d', 'These days, jump pirates spring up more frequently on Corellia than ever before. I''m sure you''ve heard the newsfeeds describing how these robbers use antique SpecForce rocket packs, from the days of the Old Republic, to assault orbital shuttles as they pass through the topcloud layers. Such atmospheric bandits are particularly dangerous, since a mistake can bring their victims crashing to the surface instead of simply marooning them in space. CorSec has placed special priority on stopping these rocket-propelled thieves. To this end we are contracting civilian investigators to check out suspected staging sites and destroy them if anything illegal is found. Missions of this nature require groups of very experienced operatives. Interested parties are encouraged to send their qualifications to CorSec. In return we will transmit the coordinates of a suspected jump site in your area. Thank you for your attention.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 42, 'm11o', 'Corellian Security Force'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 43, 'm11s', 'Excellent work! We''ve been hoping to catch that particular bunch of jump pirates for some time now. We trust this reward is suitable.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 44, 'm11t', 'Suspected Jump Pirate Lair'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 45, 'm12d', 'Spacers think that ships and fuel just pop into the galaxy through a black hole or something. Slip the blockades, tease the Imperials, run the Kessel and Byss and Twin Stars; it''s all fun and glamor for those starry-eyed flyboys. But the fact is, it''s guys like me that cut through all the rules and regulations so they can zip around the cosmos like kids on a hovertrike. Sometimes I got to remind those hotshots who runs the regulator in this business. That''s how you can help me. I''ve heard your name in certain circles. I think we can do some good business together. I got me a little station full of spacers and freight-runners that need a hot dose of reality, if you know what I mean. I want you to level that place. I want every sentient being with a blaster hole in him. Think you can handle that? Good. You''ve got a reputation for serious violence. That makes you damn useful.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 46, 'm12o', 'Chaster Fel Gaargaaz, Magnate'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 47, 'm12s', 'Haw! I knew you''d be as good as your reputation. I hope you''re sticking around Corellia for awhile. There''s a lot more troublemakers where those came from, let me tell you.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 48, 'm12t', 'Got Some Spacers Need a Lesson Taught'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 49, 'm13d', 'My dad never talked about how he made his money -- or how he got those scars, or how his ship got those blast marks. He passed away recently, and now I hear disturbing rumors from old gangsters. They seem to know a lot about Dad, and they''re happy to talk about it to HoloNet reporters. Now, I''m willing -- if not exactly happy -- to learn the truth about any skeletons in my old man''s cargo hold. But there''s my sisters, our families, our social position -- if too many questions come up, it makes it hard for us to hold our standing in society. You understand, I''m sure, why these gangsters need silencing. Don''t forget, they''re not only a menace to us, but to society at large! So I hope you''ll earn my family''s large reward for wiping out this criminal menace.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 50, 'm13o', 'Heir to a Corellian Fortune'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 51, 'm13s', 'A thousand thanks. Just remind yourself, we have to destroy criminal elements to make Corellia safe for honest people like ourselves.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 52, 'm13t', 'Menace to an Honored Phantom'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 53, 'm14d', 'I''ll make this quick, since time is short. We had a shipment of repulsor-compensators stolen from a droid freighter. We''ve got an Imperial order for hyperdrives and we need those components back immediately. The thieves are running a cloaking shield for their contraband ship from a ground station outside of town. We need a civilian strike team to knock out this station so we can locate our stolen shipment and get back on schedule. Lord Vader, the Imperial agent who placed the order, sounded impatient. We don''t want to keep him waiting.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 54, 'm14o', 'Corellian Technologies'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 55, 'm14s', 'Thank you. Here''s your payment for the work. Lord Vader is pleased to hear that our shipment of hyperdrives is back on schedule. He did not sound like a forgiving sort.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 56, 'm14t', 'Ground-based Cloaking Shield'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 57, 'm15d', 'We finally tracked down the mysterious source of turbolaser fire that has assisted more than a few smugglers past our customs blockade. A team of veteran soldiers has disguised the planetside laser as an unobtrusive power station. They are unaware that we know their location, so we have the advantage of surprise. Rather than deploying regular troops to knock out the turbolaser, we have decided to employ a team of skilled civilians for the mission. This will reduce the chances for the criminals to discover that their position has been compromised. We need this civilian team to hit them quickly and mercilessly. We estimate that they are prepared for an extended defense of the site, so err on the side of personal survival. We will monitor the engagement and secure the site after the smoke clears.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 58, 'm15o', 'Corellian Defense Force'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 59, 'm15s', 'You handled that firefight better than we could have imagined. Your reward is well-deserved. We''d be pleased to work with you again in the future.'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 60, 'm15t', 'Hidden Turbolaser'),
('string/en/mission/mission_destroy_neutral_hard_npc_corellia.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 1, 'm1d', 'The Advisory Office attends to the safety of remote Naboo settlements. In these troubled times these settlements endure constant problems with marauders and vandals. They come from offworld, know nothing of our traditions and culture, and see our lovely settlements as mere loot-houses. Worse, Imperial Security pays the problem little regard unless it directly concerns the Empire''s installations. Therefore, we routinely hire experienced strike teams to stamp out criminal bases as we locate them. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 2, 'm1o', 'The Royal Advisory Council'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 3, 'm1s', 'Thank you. Your aid, though welcome, is only a temporary measure in fighting an ongoing problem, so expect further assignments from this office in the future.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 4, 'm1t', 'Vandals On Naboo''s Frontiers'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 5, 'm2d', 'Territorial disputes among shaak wranglers have taken a ludicrous turn. Some wrangling families are hiring gangsters to add banned chemicals to the feed of rival shaak herds. These chemicals create intestinal blockages that eventually cause the afflicted shaaks to, as it were, explode. We have assigned agricultural counselors to resolve citizen grievances, but we must also deal with the gangster problem. Bringing it to the attention of Imperial Security could lead to public ridicule. We prefer to hire an independent agent to eliminate the gangsters, quietly and with discretion.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 6, 'm2o', 'The Royal Advisory Council'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 7, 'm2s', 'This was not our finest hour, perhaps, but you did the job well. We may hope not to deal with explosive shaaks in the future.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 8, 'm2t', 'Exploding Shaak Problem'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 9, 'm3d', 'Security operatives constantly uncover new pirate bases in the Naboo countryside. These bases, speedily constructed and easily abandoned, show Imperial Security''s apathy about protecting Naboo citizens. The Empire tolerates pirates exactly as long as they avoid the Emperor''s own retreat. We must deal with the consequences ourselves, and so we employ private strike teams to assault and destroy these pirates as they turn up. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 10, 'm3o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 11, 'm3s', 'Thank you for striking one more blow against piracy. This problem continues strongly, so expect to hear from us again on this matter.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 12, 'm3t', 'Pirate Bases In Naboo Countryside'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 13, 'm4d', 'According to our security operatives, slavers are selling Twi''lek females to settlers in remote areas. The slave trade was never a problem on Naboo historically, but has increased of late, particularly the trade in desirable Twi''lek women. This odious crime seems uninteresting to Imperial Security, and our own volunteer forces lack the firepower needed to stop well-armed slavers. We seek experienced strike teams that can handle a major challenge. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 14, 'm4o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 15, 'm4s', 'The Twi''lek slave trade is still on the upswing on Naboo, so expect further calls from us in the future. Meanwhile, thank you. Here is your fee.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 16, 'm4t', 'Twi''lek Slaver Activity on Naboo'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 17, 'm5d', 'Our Governor has long performed a delicate balancing act, allowing the Empire free rein on Naboo while simultaneously protecting our people from drastic exploitation. Certain factions in Imperial Security disapprove of this balancing act. Recently criminal agents have been provoking skirmishes between Naboo settlers and Gungans in areas where both species live in close proximity. These provocateurs raid one side''s settlements, plant false evidence implicating the other side, then repeat the same operation in reverse. Given the lack of obvious criminal motives, this suggests a plan to create a political crisis on our borders, perhaps in order to increase Imperial Security''s involvement in (and exploitation of) the area. The Governor''s office is contracting with independent strike teams to stop these criminals before a crisis can occur.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 18, 'm5o', 'The Office of the Governor of Naboo'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 19, 'm5s', 'You have helped defuse the crisis, for now. This is perhaps only a step in an ongoing process, so you may be hearing from us again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 20, 'm5t', 'Tensions On Naboo-Gungan Borders'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 21, 'm6d', 'The Governor has received intelligence reports regarding pirate activity between Naboo and the moon Rori. Numerous raiding ships are involved, all displaying suspiciously similar weaponry and tactics. They are clearly operating on a scale far above usual piracy. Also curious is their seeming immunity to Imperial sensors; at least, the Imperial Navy does not acknowledge any particular piracy problem over Naboo. We suspect that a Navy faction is actively equipping and supporting these pirates. The effort would weaken Naboo''s efforts to build a hyperdrive construction facility on Rori, a key step in becoming less dependent on imported technology. Given the Empire''s apathy, this office is discreetly hiring independent agents to locate and strike pirate land bases here on Naboo.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 22, 'm6o', 'The Office of the Governor of Naboo'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 23, 'm6s', 'Excellent! Your work has helped Naboo and Rori continue on the high path toward technological independence. We shall hope to use your services again soon.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 24, 'm6t', 'Pirates Interfere With Factory Shipments'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 25, 'm7d', 'For a long while, despite subtle Imperial opposition, the Governor has supported construction of a hyperdrive factory facility on Naboo''s moon Rori. This would free Naboo from excessive reliance on imported technology. Certain Imperial Navy factions who disapprove of this goal are covertly undermining our effort. Now the Navy is plainly ignoring smuggler activity between Naboo and Rori, whereby smugglers steal equipment from the Rori spaceport, ship it back to Naboo, and sell it back to corrupt suppliers. In essence, we are buying our own equipment multiple times. We are hiring independent agents to fight the smugglers that the Empire ignores.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 26, 'm7o', 'The Office of the Governor of Naboo'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 27, 'm7s', 'A fine job! Your work will help this vital project stay within budget -- for now. But this deplorable interference will no doubt continue, so look to us for more work soon.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 28, 'm7t', 'Smugglers Interfere With Hyperdrive Facility'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 29, 'm8d', 'In times past this office has been known for corruption, but that is changing on my watch. My current problem is the many "inside" informers, who secretly forward all shipping manifests and internal communication to their smuggler accomplices. To bypass these informers, I give sensitive tasks to freelance agents. In the current case, I have learned of an operation that diverts expensive imports from the spaceport landing dock straight to the smugglers, bypassing customs. Only a well-armed strike team can stop this rich trade. Contact me on a secure channel for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 30, 'm8o', 'The Portmaster of Kwilaan Starport'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 31, 'm8s', 'That is satisfactory. I must next pinpoint the confederates in this office. There is much to be done here, so you may expect further work from me.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 32, 'm8t', 'Smugglers Infiltrate Portmaster Office'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 33, 'm9d', 'In certain savage cultures of the Outer Rim, the organs of Naboo''s wild tusk-cats are presumed to have mystical medicinal properties. The smuggling trade in tusk-cat organs has reached crisis proportions. The ringleader behind the current gang is supposed to be a mystic or shaman from Omwat, one of these remote worlds. My operatives recently saw such a figure enter a fortified base at the attached coordinates. I''d like a seasoned strike team to hit this fortification, destroy the smugglers, and stop this barbaric trade.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 34, 'm9o', 'The Portmaster of Kwilaan Starport'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 35, 'm9s', 'Excellent. But I saw no sign of any presumed mystic or wizard from Omwat. Perhaps he escaped, to resume the tusk-cat trade elsewhere. Ah, well.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 36, 'm9t', 'Naboo Tusk-cat Medicine Smuggling'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 37, 'm10d', 'Persistent rumors about smuggling on Naboo mention a medicine man or shaman from Omwat, a primitive world in the Outer Rim territories. He trafficks not in the usual spice and weaponry, but in odd ceremonial medicines -- native herbs and organs of local animals. Now there are new reports that he has moved from organ smuggling into kidnapping. An individual matching his description recently abducted a Naboo child in a rural settlement. The girl''s community is up in arms. We must mount an all-out offense quickly. While police search for the girl, we are contracting with independent strike teams to assault fortified smuggler lairs associated with this Omwat shaman. You will be well paid for your work.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 38, 'm10o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 39, 'm10s', 'Congratulations. The girl abducted by the Omwat shaman escaped during your assault, and is now safely back home. You''ve done well, and you deserve this reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 40, 'm10t', 'Girl Abducted by Omwat Shaman'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 41, 'm11d', 'For the sake of a beautiful lady, we have to act fast. The daughter of a wealthy Naboo has been kidnapped by offworld slavers. These cutthroat scum were hired by a rival noble as retaliation for a political slight. Without going into details, I hold myself responsible for this situation. I intend to fix it. The slavers will expect the Royal Security Force to mount a rescue operation. We can catch them by surprise with a civilian strike team. I need skilled fighters to hit the slaver''s lair fast and hard. While the battle is on I will slip inside and free the captive. I do not have a fortune with which to fund this operation, but all that is mine I will give to the fighters who help me get back my lady.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 42, 'm11o', 'Thanus March, Freelance Spacer'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 43, 'm11s', 'We did it! I got my lady out in the thick of the fighting. I owe you more than just these credits, friend. Thank you.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 44, 'm11t', 'Rescue Noble Naboo Lady'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 45, 'm12d', 'Textile merchants have always made a good living on Naboo. My partner recently decided to retire and live off the wealth he has amassed during his fifteen years in business. He left me the company, for which I was grateful. What he didn''t tell me, however, was that he failed to honor certain debts to a gang of smugglers. The gang has decided to collect on those debts, and has gone so far as to threaten my family. Because my former partner refuses to acknowledge these debts, and I don''t have the exorbitant amount these scoundrels are demanding, I''m willing to pay a team of experienced troubleshooters to get rid of these smugglers and make sure they don''t trouble anyone else again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 46, 'm12o', 'Hipan Voge, Textile Merchant'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 47, 'm12s', 'That was handled most expertly. I think perhaps this is the beginning of a beautiful and profitable friendship. Do you like Dramassian silk? I can get it cheap.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 48, 'm12t', 'Insure Safe Import of Fabrics'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 49, 'm13d', 'I thought I had lost my son in an aquaspeeder accident on Lake Paonga a couple of months ago, but I''ve recently discovered it was a botched kidnapping attempt by a group of murderous pirates. These scum plan on trying again with the child of another wealthy family, but I intend to stop them. I''m offering a handsome reward to the individual or team that successfully assaults and destroys the pirates'' lair, the coordinates for which I have just acquired. Only the most dedicated and efficient agents of justice need apply.  '),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 50, 'm13o', 'Kanlee Fentetta, Prominent Naboo Citizen'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 51, 'm13s', 'My son is finally avenged and my fellow citizens may rest a bit easier. These pirates are a scourge on the galaxy, and we should strive to wipe them out. All of them.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 52, 'm13t', 'Avenge Murdered Naboo Son'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 53, 'm14d', 'Swoop gangs have never really been a problem on Naboo, but recently the Empire shipped much of the Royal Security Forces'' strength offworld to deal with the Rebellion. This has left us more vulnerable to incursions by these rogues. One gang in particular has been gaining notoriety, the Shadow Angels of Dathomir. We believe they are trying to establish themselves here, and we do not have the manpower necessary to drive them off. We''re willing to pay a strike team to infiltrate the Shadow Angels lair and blast that scum off our beautiful world. These gangsters are quite tough, so only the most seasoned professionals should apply.    '),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 54, 'm14o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 55, 'm14s', 'Our best agents could not have done a better job. Your team''s skills are formidable, and you''ve earned your fee. Has your team ever considered joining the Royal Security Forces? '),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 56, 'm14t', 'Drive Away Swoopers'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 57, 'm15d', 'The questionable activities of former portmasters have unfortunately created a situation that must now be handled by our office. During the tenure of these portmasters, smugglers were encouraged to increase their activities on Naboo. Many of these smugglers have established hideouts in remote areas and will no doubt continue to ply their trade until driven off. The Governor''s Office has authorized us to seek outside help in dealing with these criminals. We''re offering rewards to capable strike teams that can drive these smugglers off our world.   '),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 58, 'm15o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 59, 'm15s', 'Efficient and effective, citizen. Your fee will be deposited in your account. The Naboo are grateful for your services.'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 60, 'm15t', 'Encourage Smugglers to Leave'),
('string/en/mission/mission_destroy_neutral_hard_npc_naboo.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 1, 'm1d', 'I think I''ve heard of you. You help people take care of problems, don''t you? Care to tackle a gang of some of the meanest scum in the galaxy? I know what you''re worth, and I''ll definitely reward you at that rate. Deal?'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 3, 'm1s', 'I must confess, I never thought you''d pull it off. You are one tough being. Your pay has been deposited, you''ve more than earned it.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 4, 'm1t', 'Tackle Tough Gang'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 5, 'm2d', 'You haven''t seen swooper violence until you''ve seen this gang''s handiwork. They keep the surrounding neighborhoods terrified and under their cruel control. Can you help free these innocents?'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 7, 'm2s', 'I have a feeling your name will be remembered in galactic history, friend. I hope you always choose to use your formidable powers for good. It''s a pleasure to give you this reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 8, 'm2t', 'Swoopers Are Mean'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 9, 'm3d', 'You want to make a name for yourself, citizen? Try taking out one of the largest spice refining operations in this sector. It''s guarded by some of the galaxy''s most vicious killers. Think you can take them on?'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 11, 'm3s', 'I can''t believe you survived that! You a Jedi or something? The reward is rightfully yours.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 12, 'm3t', 'Take Out Spice Refinery'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 13, 'm4d', 'Would you believe me if I told you that a vile gang of murderers has decided to form a cult devoted to the worship of the ancient Sith? They''re right here on this world and intend to carry out human sacrifices. Could you please help us destroy this cult? '),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 15, 'm4s', 'You''re a true hero of the people, friend. Please accept this generous reward from a very appreciative community.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 16, 'm4t', 'Crush Sith Cult'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 17, 'm5d', 'Rumor has it that a Dathomir Nightsister has claimed leadership of a gang of cutthroats and is training them in the use of the dark side of the Force. Can you help us stop this gang before it becomes an unstoppable force?'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 19, 'm5s', 'Excellent job, citizen, no doubt about it. The reward for your services has been deposited.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 20, 'm5t', 'Stop Vicious Cutthroats'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 21, 'm6d', 'There''s a gang that''s decided to adopt the Tusken Raider''s Bloodrite practice as a form of initiation for new members. Recruits must capture and torture a sentient being to death over a period of weeks. Please help us put a stop to this.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 23, 'm6s', 'Those loathsome criminals were trained killers and must have put up an incredible fight. I''ve deposited a small token of our esteem into your account. You have saved our community.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 24, 'm6t', 'Stop Tusken Raider Copycats'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 25, 'm7d', 'Slavers have set up a base of operations on this planet and conduct their vile business from this stronghold. They''ve already captured several local non-humans and sold them off to various buyers across the galaxy. Can you help us stop these rogues? '),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 27, 'm7s', 'We are forever in your debt, citizen. A hero such as yourself is desperately needed in these dark times. You''ve earned your reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 28, 'm7t', 'Stop Slavers'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 29, 'm8d', 'Does the Black Sun organization scare you, citizen? Do you shrink from the idea of entering a den of assassins and blasting it to bits? If you think you can tackle a major crime syndicate and live to boast about it, then help us get rid of this vicious gang of criminals.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 31, 'm8s', 'I thought you seemed like a being with no fear. Your exploits will become the stuff of legends, citizen. Your prowess will be amply rewarded.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 32, 'm8t', 'Tackle Black Sun'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 33, 'm9d', 'Interesting gossip from the planetary security forces. A well-funded criminal group has stolen plans for the Empire''s w-165 planetary turbolaser and intends to sell them to the highest bidder. We suspect inside assistance within our agency, so we''re covertly hiring an outside team to take out the criminal base. Is your team up to it?'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 35, 'm9s', 'Let''s hope the plans were destroyed. If not, we''ll certainly hear about it, more''s the pity. You did well, thanks.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 36, 'm9t', 'Find Secret Plans'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 37, 'm10d', 'I can''t tell you how I know this, but criminals keep infiltrating planetary security forces. They''ve been funneling new starship sensor arrays onto the local black market. If the law mounts an assault operation, the insiders will tip off the smugglers. If your team can destroy the criminal base, you''ll be well rewarded.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 39, 'm10s', 'That was a brilliant operation, and you displayed great courage. Powerful people have taken notice. Your reward has been deposited; don''t mention that you got it from me.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 40, 'm10t', 'Stop Black Market Thieves'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 41, 'm11d', 'Heard the gossip? Criminals have sabotaged planetary security''s entire line of portable scanners. The alteration makes their own activities invisible. Until it''s fixed, planetary security is commissioning local strike teams to take out trouble spots. Want an assignment?'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 43, 'm11s', 'Good job. No telling how long it will take to solve this portable scanner sabotage, so more work should be coming up.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 44, 'm11t', 'Solve Scanner Debacle'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 45, 'm12d', 'Planetary security has learned of a dangerous compromise of local HoloNet satellite transceiver encryption. Pirates could decrypt spaceport traffic to locate prime victims. The security agency itself is rife with infiltrators, so an independent strike team needs to take out this pirate operation. There''s a nice reward.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 47, 'm12s', 'The HoloNet is safe again, because of your efforts. I''m glad to pay this reward, and be confident that your reputation is growing.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 48, 'm12t', 'Make HoloNet Safe'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 49, 'm13d', 'Thugs duped me into receiving a shipment. I only belatedly learned its nature: Thalassian security collars -- slaving collars! I had no idea slavery was still practiced in these enlightened times. I take personal responsibility for involvement with these scoundrels. In restitution, I''ll pay you to destroy that slaver base.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 51, 'm13s', 'My conscience is now somewhat ameliorated. Thank you for your assistance. Your pay has been deposited.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 52, 'm13t', 'Destroy Slavers'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 53, 'm14d', 'Ever been tortured by an Arakyd Agonizer-6 nerve disruptor? No, I can see you haven''t. You still walk well and don''t tremble. I won''t go into my personal history with these devices. But when I learned that gangsters outside town are manufacturing these evil things, I resolved to hire a strike team to take them out.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 55, 'm14s', 'Your money has been deposited. I suspect those "gangsters" were actually selling to the Empire, but that''s a problem for another day.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 56, 'm14t', 'Smash Torture Devices'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 57, 'm15d', 'A certain criminal organization has allegedly obtained schematics for Imperial Star Destroyer tractor beams. Personally, I doubt this. But as a precaution, I''m willing to pay your strike team to destroy the base that may possibly contain these alleged plans. I''d prefer not to explain why this is a precaution. Will you take the job?'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 59, 'm15s', 'Your success makes me believe the tractor-beam rumor to be false. An organization with the resources to steal from the Empire would certainly have put up a bigger fight. Your payment has been sent.'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 60, 'm15t', 'Secure Schematics'),
('string/en/mission/mission_destroy_neutral_hard_npc_non_persistent_from_npc.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 1, 'm1d', 'Maintaining good relations between settlers and Sand People is a constant struggle. To foster better understanding between the cultures, our bureau funds an outreach program to teach young Sand People crafts, basic arithmetic, and interpretive dance. Unfortunately, yet another of our award-winning Intercultural Compassion Community Centers is being threatened by vandal gangs. These thugs take brutish pleasure in blowing up our bureau''s buildings and attacking our instructors. We now have a line item in our annual budget to hire independent adventurers to destroy these gangs. Contact our bureau for coordinates.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 2, 'm1o', 'Tatooine Bureau of Ethnicity and Socialization'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 3, 'm1s', 'You have performed as the contract specifies. Contract payment disbursed.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 4, 'm1t', 'Gangs Menace Intercultural Compassion Center'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 5, 'm2d', 'You worthless cheating pile of eopie droppings, I hope some swooper cuts off your mother''s -- oh, wait, I think I''ve got my message files mixed. Okay, I see now, this one is going to whoever can help me get back at that crooked ronto dealer Fizzy Fon Margan. We''ve been feuding for a while over this hopeless, mite-infested droopneck animal he sold me. I''ve tried threats, I''ve tried lawsuits, but lately I''ve had more satisfaction hiring people to beat him up. Now, Fizzy Fon has hired a violent bunch of thugs to blow up my home and property. This overreaction requires massive retaliation. I want you to demonstrate what awaits Fizzy Fon by blowing up his band of hired goons. Meanwhile, I have to finish dictating my latest little love-note to Fizzy.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 6, 'm2o', 'An Aggrieved Ronto Owner'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 7, 'm2s', 'Right about now, Fizzy Fon must be getting the sad news about his hired thugs. I wish I could be there. Thanks, you did fine.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 8, 'm2t', 'Stop Goons Hired by Fizzy Fon Margan'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 9, 'm3d', 'I tell you, this woman is insane! She bought a ronto from my Mos Espa lot, having been clearly informed before the sale that this creature has a recurring inner-ear difficulty. She had some bad luck with it, I grant you. I''m sorry for the damage to her home and the four surrounding blocks, I really am. But this was in no sense my responsibilty. I don''t deserve this constant stream of harrassing calls and really hostile messages. And now, by hiring gangs of thugs to beat me up twice a day, now she''s really gone beyond decent conduct. I''ve found her latest gang''s headquarters, and I''m hiring you to take them out. Meanwhile, I''m calling my lawyer again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 10, 'm3o', 'Fizzy Fon Margan, Your One-Stop Ronto Dealer!'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 11, 'm3s', 'Thanks. This is more than an untoward side-effect of the ronto resale business, it''s a living nightmare. I intend to retaliate against that bizarre woman.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 12, 'm3t', 'An Aggrieved Customer is Making My Life Unbearable'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 13, 'm4d', 'My homeworld, Cona, is going through tough times. Lots of refugees from Imperial policies. I''ve brought some here to Tatooine to set up new lives -- after all, who would look for anyone out here? But the local gang is getting these helpless folk addicted to salt and hustling them for their salaries. It makes me so angry that my thrusk burns. To protect these poor Arcona, I want you to level that gangster lair. Leave nothing standing!'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 14, 'm4o', 'An Arcona in Mos Eisley'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 15, 'm4s', 'On behalf of my people, thank you. And when you''re in Mos Eisley, stop by Spaceport Speeders for a good deal.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 16, 'm4t', 'Salt Pushers Menacing Tatooine''s Arcona Refugees'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 17, 'm5d', 'As a Trandoshan, I am required to collect jagannath points by hunting dangerous prey. My problem is that I''m a colossal coward. My family''s ill-gotten wealth lets me travel hither and yon, hiring local adventurers to kill deadly beasts on my behalf. Unfortunately, certain narrow-minded rivals on Dosha have obtained my itinerary, and they have decided to make my Tatooine visit difficult. Informants tell me that gangsters wait to accost me as I arrive. Ah well, I have bottomless funds! I gladly commission you to stop these hired thugs before I arrive, preferably by blasting them to subatomic particles. Ah, the enviable life of the craven rich!'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 18, 'm5o', 'An Anonymous Trandoshan'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 19, 'm5s', 'Excellent work, except that my informant tells me the world in question was not Tatooine, but some other backwater. Ah well, I suppose these gangsters deserved their fate. Take your payment, and may the Scorekeeper record your brave deed.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 20, 'm5t', 'Cowardly Trandoshan to Visit Tatooine'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 21, 'm6d', 'Word reaches me from my hunting school on Dosha that a vile coward is now visiting Tatooine. This shuddering pipsqueak, rich in credits and poor in honor, has brought disrepute to the noblest Trandoshan traditions. There is no honor in tracking and killing a coward, so rather than stain my reputation, I am hiring you to locate this fool''s lair and destroy it, along with all the contemptible gangsters sheltering him. May the Scorekeeper smile on your effort!'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 22, 'm6o', 'A Trandoshan of Integrity'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 23, 'm6s', 'My information was mistaken. Apparently the coward has not yet arrived on Tatooine. Still, one less gangster lair is one less gangster lair. You did honorable work in facing those felons, and so I pay you as agreed.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 24, 'm6t', 'Defend the Honor of the Trandoshans'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 25, 'm7d', 'One of the first colony ships to arrive on Tatooine has today become a wretched hive of scum and villainy. Mos Eisley''s wrecked Dowager Queen, an important part of our planetary heritage, needs cleaning, fumigation, extensive restoration, and many eviction notices to become a world-class tourist attraction. Our new organization recently secured seed funds to start this task, but a gang of short-sighted thieves stole the money -- and with it, the chance to make the Dowager a proud queen once again. Tracking beacons have pinpointed the thieves'' location. We have raised enough among our board members to hire you to destroy the base and, if possible, recover the money.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 26, 'm7o', 'Committee to Preserve the Dowager Queen'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 27, 'm7s', 'We did not expect you to find the money. We''ve hired a slicer who has traced and recovered the stolen funds. Nonetheless, thank you. In a few years we hope to have you at our grand re-christening of the restored Dowager Queen!'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 28, 'm7t', 'Thieves Stole Funds to Restore Tatooine''s First Colony Ship'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 29, 'm8d', 'Illustrious Jabba wants peace and prosperity for all sentient beings of Tatooine. To this end he has identified the fortified strongholds of a certain gangster who has plagued this planet with her ceaseless and arrogant criminal schemes. The Mighty Jabba will gladly pay a handsome reward to any soldiers-of-fortune who are tough and brutal enough to wipe out these dens of wickedness. He wishes suffering and death upon these criminals and good fortune upon those who undertake this noble enterprise.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 30, 'm8o', 'Bib Fortuna'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 31, 'm8s', 'Mighty Jabba is most pleased with your success. Perhaps you might visit his palace to further test your mettle.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 32, 'm8t', 'Wipe Out Lady Valarian''s Den of Wickedness'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 33, 'm9d', 'For too long have the Hutts spread their disease and corruption across the Outer Rim. Here on Tatooine, we all know that Jabba is the worst of the bunch. I am placing the resources of my organization at the disposal of all citizens willing to take a stand against this villain and the scum who work for him. I shall provide the coordinates of his more exposed strongholds, if you can provide the firepower to smash them to rubble. You will be well paid for your valiant deeds. Together we can make Tatooine safe for legitimate citizens again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 34, 'm9o', 'Lady Valarian'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 35, 'm9s', 'You''ve got a real talent for death and destruction. I may be able to put it to good use. I''ll be in touch.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 36, 'm9t', 'Smash Jabba''s Strongholds'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 37, 'm10d', 'Tatooine is my home. I don''t have to stand for assaults on myself and my property. I was moving a repulsorsled of motivators across the Swallowing Wastes when a gang of cutthroats hit me with an ion gun and robbed me blind. But the joke is on them. The tracking circuit in my repulsorsled has given me the coordinates where these gravel maggots sharpen their knives. I''ll pay good money to anyone who can take them down and make sure they stay down. Tatooine may be a backwater dustball, but it doesn''t have to be uncivilized.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 38, 'm10o', 'A Robbery Victim'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 39, 'm10s', 'The robbers are down and out? Good! Hired guns like you make Tatooine a bastion of civilization in the Outer Rim.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 40, 'm10t', 'Take Down a Gang of Robbers'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 41, 'm11d', 'So when I heard that a pack of anoobas had strayed into Bildor''s Canyon, I figured they would make an easy sell to one of those rich Naboo animal lovers. What I didn''t know was, a swoop gang was preying on other moisture farmers in the area. Those filthy worrts took everything I''ve got and laughed at my pain. Now I''m stuck in a bacta tank, wondering what will happen to my family when last season''s harvest runs out. But I''ve still got a few credits to pay for revenge. I need someone tough and pitiless to wipe that swoop gang off the face of the planet. I''ve heard that you fit the bill. They''re a dangerous bunch, but I know you can handle it. Turn them into bantha fodder!'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 42, 'm11o', 'A Moonlighting Moisture Farmer'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 43, 'm11s', 'I knew you could handle that pack of low-life worrts. I hope they begged for mercy before you fried them!'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 44, 'm11t', 'Mash a Swoop Gang Into Bantha Fodder'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 45, 'm12d', 'I''ve had some hyperspace trouble that maybe you can help me with. I work the Triellus trade route between Tatooine and the Sisar Run. For the last year there has been sporadic hyperwave interference on the route. I run a lot of medical cargoes to the Outer Rim. Lives are at stake if I have to drop out of hyperspace to recalibrate my navicomputer. I found out that an import broker here on Tatooine has built a hyperwave antenna to deliberately slow incoming cargoes, so he can run up the prices on his own stock. That''s no good. When I''m late with medicine, people die. When I put this to him, he just laughed at me. So I want to hire you to take out his antenna. He''s got paid thugs protecting the site, but I know your reputation. A couple of roughnecks with blasters won''t scare you off. I''ll pay a fair fee for the job, as long as you don''t waste any time. I''m off to Terman Station with a load of cordine that must not be delayed.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 46, 'm12o', 'Yester Timm, Freight Carrier'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 47, 'm12s', 'I just got word from a friend in Mos Espa that the hyperwave antenna was blasted to bits. I knew you were as good as your reputation. The money will be transferred to your account automatically. Nice work.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 48, 'm12t', 'Hyperspace Trouble'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 49, 'm13d', 'Anchorhead might be a long way from the Jundland Wastes, but sometimes town problems spill into the wilds. We''ve got surveyors looking for ore from the Western Dunes all the way to Mospic. But a competitor of ours doesn''t believe in fair claims. They''ve contracted a swoop gang to attack our surveyors once a vein has been found. These claim stealers have killed or maimed a dozen good workers. We''re ready to put a stop to it. We sent a seeker droid to discover the location of the gang''s hideout. All we need is a group of strong fighters to give those womp rats a taste of their own medicine. They never showed us mercy, so show them none in return.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 50, 'm13o', 'Kralkeen Mining Concern'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 51, 'm13s', 'That was terrific work. Now our surveyors don''t have to work in secret anymore. Unless our competitor hires another gang, in which case we may be in contact with you again.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 52, 'm13t', 'Crunch the Claim Stealers'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 53, 'm14d', 'As a child I was a slave on Tatooine. I may have been just another Twi''lek girl, but I was strong enough to escape my abusive owner, bribe a monk to remove my transmitter and stow aboard a tanker to flee this sandy hellpot of a planet. After ten years in a company of Zabrak mercenaries, I''ve decided to settle the unfinished business of my youth. I''m going to pay a visit to my old owner. I need someone to pay a similar visit to the slavers who ruined my life. The gang is still here, as fat and vicious as ever, armed to the teeth and ready for anything. But they''re not the toughest beings on Tatooine. That title goes to specialists like you. That''s why you''re my choice to deliver some payback to those heartless scum. Make them regret their choice of profession and I''ll make you happy you did.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 54, 'm14o', 'Pura Kotal'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 55, 'm14s', 'My former owner fared no better than those slavers. I knew I could rely on your skill. Here''s your payment. If you''re going to be in Mos Taike this week, look me up. I''ll buy you a Dodbri whiskey.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 56, 'm14t', 'Payback For the Slavers'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 57, 'm15d', 'They thought they could escape me after they killed my husband, but they were wrong. I''ve followed these pirates through twelve sectors. I nearly killed them three separate times. Now they think they''re safe in Hutt Space, huddled in the sands of this remote dustball, but they''re about to meet their end. I know where they''re hiding out. I know on a planet like Tatooine, I can hire freelance soldiers twice as tough as a crew of common space pirates. I''ve got the money to pay for the demise of these murderers. The galaxy isn''t big enough to escape my justice.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 58, 'm15o', 'Madam Prisaal of Ichtor 8'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 59, 'm15s', 'I should feel happy. My husband can rest in peace. Instead I just feel cold, like a death stick addict at the end of a fix. You''ve done your job well, though, so here''s your payment like I promised.'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 60, 'm15t', 'Avenge My Murdered Husband'),
('string/en/mission/mission_destroy_neutral_hard_npc_tatooine.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 1, 'm1d', 'I finally had a chance to impress a talent scout from a major jizz recording company. This was gonna be my shot at fame and fortune. I''d set up a small, exclusive outdoor concert in a location specifically chosen for its excellent acoustics. I was gonna blow that scout''s boots off with my jizz-wailing. And that''s when those vile beasts showed up and ruined everything! They ran off all the guests and ate all the food! I want revenge. I know exactly where they came from, and I''ll pay handsomely to see them obliterated.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 2, 'm1o', 'A Seething Jizz-Wailer'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 3, 'm1s', 'At last, revenge is mine! Take that, you music-hating monstrosities! I hope all your wretched kind meets a similar end!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 4, 'm1t', 'Avenge Jizz-Wailer'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 5, 'm2d', 'A few kids have gone missing in the last couple of weeks. Search parties didn''t turn up anything, but they did locate a rather large nest of predators dangerously near a populated area. These are the likely culprits. We need someone with experience to go in there and take care of these creatures. Take plenty of ammo and approach with caution, as these beasts are cunning and vicious. We''ll pay our standard fee.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 6, 'm2o', 'Imperial Police Prefecture'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 7, 'm2s', 'Good work, citizen. This community certainly appreciates your help. You''ve earned the reward.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 8, 'm2t', 'Keep Community Safe'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 9, 'm3d', 'These darn wildlife preservationists with their bleeding heart causes to save every obscure beast in the galaxy have given us nothing but trouble. You know what happens when certain creatures are protected from hunting? They overpopulate a region and create havoc, leaving us to go in and clean up the mess. We need individuals, preferably not animal lovers, to clear out some nests of creatures that these preservationists fought hard to protect. We''ll pay for every nest cleared, of course. We should send the bill to the Intergalactic Zoological Society. Let''s see how they like that.  '),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 10, 'm3o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 11, 'm3s', 'Good job, citizen. You sure you don''t want a job with our office? We could always use another hard-working exterminator like you.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 12, 'm3t', 'Stem Tide of Critters'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 13, 'm4d', 'When I was a youngster I was savagely mauled by a vicious predator. This act left me more of a machine than a man -- twisted and tormented. I vowed that I would have my revenge on these creatures and all like them. I''ve dedicated my life to the systematic extermination of all non-sentient life in the universe. As you can well imagine, this is quite a task for one man to accomplish alone. That''s where you come in, friend. I''m willing to pay handsomely for your aid. All you have to do is locate a nest of vile, verminous non-sentient life and blow it to atoms. I have the coordinates to several such lairs of putrid predatory organisms, if you need some help getting started. What say you? Will you assist me in fulfilling my lifelong ambition? '),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 14, 'm4o', 'A Determined Man'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 15, 'm4s', 'Excellent! One step at a time does it, citizen. We have our work cut out for us. Keep at it.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 16, 'm4t', 'Stamp Out Life In the Universe'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 17, 'm5d', 'This is going to seem kind of strange. I''m posting this notice to the HoloNet from my home but I''m not alone. There''s this huge Gamorrean watching me as I type. I''m not sure he can read Basic, but just in case I''ll try and stick to the facts so I don''t upset him. I think he wants me to pay someone a certain amount of credits (which he has provided) in return for that individual blasting some sort of nest of creatures or something like that. He keeps making biting motions with his hand and grunting loudly. Plus, I checked the coordinates he supplied and they seem to lead out to some remote wilderness area. I hope someone can blast this lair to atoms quickly so this Gamorrean can go about his business. Failing that, I hope that someone is at least conscientious enough to take whatever other actions they deem appropriate given the circumstances. Thanks for listening.  '),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 18, 'm5o', 'A Desperate Hostage'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 19, 'm5s', 'Thank you so much. The Gamorrean just left. Whatever you did, it seemed to satisfy him. I''d better alert the authorities about this. If you see a Gamorrean heading your way, turn and run.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 20, 'm5t', 'Help Free Hostage'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 21, 'm6d', 'We''re in the process of clearing some undeveloped land so that Corporate Sector Authority land surveyors can assess the property for purchase. In order to get the Intergalactic Zoological Society off our backs, we assured them that the greatest care will be taken in relocating any indigenous creatures we came across. Now all we need is to make sure those land surveyors can do their jobs in absolute safety. In order to do this, we''re offering a generous amount of money to anyone willing to clear out any creature lairs on this undeveloped land. Just blast those little buggers into oblivion, it''s all right. If the IZS lodges a protest with our office, we''ll provide them with proper documentation. Hope you can help out. ');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 22, 'm6o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 23, 'm6s', 'Nice work. And there''s plenty more work to do if you want to look us up again. Have a good one.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 24, 'm6t', 'Clear CSA Land'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 25, 'm7d', 'I run a company that offers wilderness tours for the entire family. Recently, my insurance premiums have skyrocketed due to some "mishaps" during a few of our tours. It seems some sort of predatory creatures have decided to make their home near one of our most popular hike trails. Business has fallen by 36%. If I don''t act now, I''ll be ruined! I''m willing to pay someone a fair sum to clear out that den of dangerous beasts. One of my tour guides is fairly certain he knows where these brutes are nesting and has provided the coordinates to the suspected lair. Can you help save my business?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 26, 'm7o', 'A Desperate Businessman'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 27, 'm7s', 'You''ve done an excellent job. Feel free to seek me out in the future. Enjoy your pay.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 28, 'm7t', 'Save Wilderness Tours'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 29, 'm8d', 'I hear them scurrying about at night. I see their glowing sinister eyes outside my window. I know they''re waiting for me to run out into the wilderness so they can rend the flesh from my body and suck the marrow from my bones! They call to me! They haunt my dreams! You must release me from this torment! I''ll pay you to hunt these nightmarish creatures down and blast them into oblivion. I beg you! I know where they hide! Please save me from them!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 30, 'm8o', 'An Insomniac'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 31, 'm8s', 'Finally, I can sleep. At long last I can find peace. Thank you, my friend. I owe you my sanity.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 32, 'm8t', 'Help Nervous Citizen'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 33, 'm9d', 'A dangerous pack of predators has been terrorizing my workers. I''ve lost six to those flesh-eating brutes, and another twelve have quit. The Imperial Environmental Preservation & Refocusing Authority wants a fortune to clear those pests out. I''m sure I can find a brave, enterprising citizen who is willing to clear those creatures out for a reasonable sum. I''ve even made the work easier by pinpointing the location of the beasts. What do you say, citizen? You feel like going on a hunt?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 34, 'm9o', 'A Frustrated Land Developer'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 35, 'm9s', 'See what a little ingenuity and the right frame of mind can get you? Good job, citizen. Look me up if you ever need a job.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 36, 'm9t', 'Save Land Developer'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 37, 'm10d', 'Ever since the local teenagers took over this park, our sanitation droids can''t keep up with the amount of garbage that those hooligans leave behind. Now all that refuse has attracted wild predators, which in turn puts those darn kids at risk. I should let them get gobbled up -- it would serve them right. But my superiors would never let me hear the end of it. I''ve been given the go-ahead to offer a reward to any individual that can clear those brutes out. Fortunately, a surveillance droid has provided us with the location of that den. You interested in making some money?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 38, 'm10o', 'Planetary Parks & Wildlife Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 39, 'm10s', 'Hurray. Now those teenagers can continue despoiling our lovely parks to their selfish little hearts'' content.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 40, 'm10t', 'Save Lovestruck Teens'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 41, 'm11d', 'I hunted exotic beasts all my life. A couple of years ago I decided to retire, settle down and raise a family. Maybe it was poetic justice or a simple cruel twist of fate, but some time ago my wife and newborn son were killed by a rogue pack of predators that had begun terrorizing this area. I decided to hunt those killers. The fact that you''re reading this message means my hunt was unsuccessful and I''m dead. This message was to be posted by my droid in the event of my death. I ask for only one thing: Destroy those creatures and prevent them from taking more innocent lives. I have provided a generous reward. I hope that you can help me and my family finally find peace. '),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 42, 'm11o', 'A Grieving Spirit'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 43, 'm11s', 'Congratulations, you have become eligible to receive my late master''s reward. The sum will be transmitted to your account immediately.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 44, 'm11t', 'Avenge Murdered Family'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 45, 'm12d', 'I''ve been studying the breeding habits of the area''s predators. My studies have led me to conclude that a particular group of these dangerous beasts is about to experience a population explosion that will threaten local livestock. I reported this to my superiors at the Parks & Wildlife Authority, and they gave me the go-ahead to hire a team of operatives to deal with these brutes. The pay for their removal is quite fair. I wish there was another way, but that would involve contacting the Imperial Preservation & Refocusing Authority, and they would likely do the same thing only with (ahem) much less finesse. Do you think you could lend a hand?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 46, 'm12o', 'Planetary Parks & Wildlife Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 47, 'm12s', 'Well done, citizen. Your efforts will make all our jobs that much easier. Of course I now have one less group of predators to study, but who''s counting?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 48, 'm12t', 'Aid Researcher of Breeding Habits'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 49, 'm13d', 'In the Old Republic, it was common practice for wealthy status-seeking merchants and petty bureaucrats to keep exotic pets shipped in from other systems. These dangerous predators could never be privately owned today without the proper permits and licenses. When this fad died out, most of the beasts were simply released into wilderness areas, where they adapted to their new environments. As a result, we now have to hire operatives to track these dens down and wipe these creatures out. Yet another unpleasant side effect of the carelessness and corruption of the Old Republic. Do you think you could help us clean up their mess?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 50, 'm13o', 'Planetary Parks & Wildlife Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 51, 'm13s', 'Now that''s good work, citizen. Congratulations on helping the Empire clean up old messes.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 52, 'm13t', 'Hunt Down Exotic Menageries'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 53, 'm14d', 'A geneticist was recently arrested by the Imperial Office of Criminal Investigations. This madman had been performing illegal cloning and gene manipulation experiments in an attempt to create exotic hybrids. Some of these experiments were released into wilderness areas so that their creator could study their adaptibility. Unfortunately for the residents, many of these hybrids survived and began reproducing. Now there are dens of these creatures spread throughout the Empire, and we need them cleaned out. We''ll pay an enterprising individual a handsome reward for every den destroyed. Could you help the Empire with this, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 54, 'm14o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 55, 'm14s', 'Keep up the good work, citizen. With individuals like you aiding us, we''re bound to wipe out all of these nests eventually.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 56, 'm14t', 'Stop Genetic Hybrids'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 57, 'm15d', 'Salutations. I am Threedee, an administrative droid in the service of an influential and wealthy patron. My master would like to employ someone to make daring raids on various predator dens. These locations have been pre-selected based on their size and the ferocity of the residents -- my master insists on the highest quality. All of these raids must completely eradicate the den and its dangerous inhabitants. You are instructed to ignore any surveillance droids that might happen to be in the area recording your activities. Further, my master will claim ownership to all the images produced from these raids and will reserve the right to alter them in any way he sees fit, including (but not limited to) the digital replacement of his image over yours. Please consult the attached contract. I hope you can be of service.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 58, 'm15o', 'A Great Hunter'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 59, 'm15s', 'Well done. Your success will result in a splendid hologram that my master may distribute to his fellow hunting enthusiasts.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 60, 'm15t', 'Help Hunter Look Good'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 61, 'm16d', 'I bought Fer Ooca, my young daughter, a blarth for her eleventh birthday. Biggest mistake of my life. Not only did that slobbery monster cover my home in drool, it developed a taste for my expensive shaak leather furniture. Further, it was never properly house-trained -- I bet you never imagined what a blarth sick on Nabooian wine is capable of producing. In any case, the happiest day of my life was when "Bubbles" wandered away from our home and was promptly devoured by some of the local predators. That was until my daughter threw a week-long fit and insisted I hire someone to take care of Bubbles'' killers. So, here I am. The pay is good, the work is fairly straightforward, and even the coordinates will be provided. Please help me appease my daughter. '),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 62, 'm16o', 'Hun Ree Sult'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 63, 'm16s', 'At last my home will have some peace. Until Fer Ooca asks for her next pet. Thanks for your help.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 64, 'm16t', 'Avenge Beloved Daughter''s Pet'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 65, 'm17d', 'Recently the Empire attempted to arrest the owners of a large traveling circus on charges of spying for the Rebellion. During the raid, the owners released several of their exotic animals in an attempt to help cover their escape. Most of these beasts were blasted to bits by stormtroopers, but a few managed to escape into the countryside. Because some of the animals were dangerous predators, we are hiring operatives to help us clean up the remnants of the circus before they can endanger any citizens. Fortunately, our surveillance droids have tracked down some new lairs. Do you feel like embarking on a hunt?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 66, 'm17o', 'Planetary Parks & Wildlife Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 67, 'm17s', 'Well done, friend. It''s a shame we have to blast these creatures, but one should never be too careful when it comes to securing the safety of the Empire''s citizens.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 68, 'm17t', 'Track Escaped Circus Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 69, 'm18d', 'Sneezing, watery eyes, terrible soreness in my tusks -- I hate these allergies! There''s some pack of stupid creatures upwind of my lodgings. Whatever toxic dust is blowing off their fur, or scales, or feathers, is making me weak. I hate weakness! You! Get off your rear, get out there, and kill these things, all of them, before my tusks fall out.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 70, 'm18o', 'An Aqualish Visitor'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 71, 'm18s', 'I still feel stuffed up. But the tusk ache has stopped, so I''ll pay you. Now go away, I''m about to snee--'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 72, 'm18t', 'Allergies Needs Relief'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 73, 'm19d', 'Did you know that the component value of all the chemical elements in your body is only a few credits? How odd, then, that the price of some creatures'' skin can exceed that of a fine landspeeder. I represent certain offworld buyers who wish to buy fine-quality pelts from a species I shall not name in this public venue. If you will proceed to the coordinates given and terminate the creatures there, I shall pay handsomely.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 74, 'm19o', 'An Agent in Fine Merchandise'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 75, 'm19s', 'Excellent. I shall arrange pickup of the pelts through another contractor. Take your fee. I suggest discretion in this matter, for the well-being of both of us.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 76, 'm19t', 'Fine-Quality Pelts Needed'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 77, 'm20d', 'The number of diseases on this detestable world absolutely astounds me. How does any thinking creature survive? I''ve developed this infection in my upper tusk-gums, and all my colleagues are laughing about it. If they think I''m getting weak, my career is finished. The medics say the condition will recur as long as I keep getting exposed. It''s some local animal, I forget the name. But I''ve got coordinates. I want you to go there and kill every animal you see. Get to it!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 78, 'm20o', 'An Aqualish Tourist'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 79, 'm20s', 'I''m still sick! Am I supposed to thank you when my tusks are threatening to split? Take your fee and get lost.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 80, 'm20t', 'Disease Victim Seeks Relief'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 81, 'm21d', 'It''s hard to explain, but my little daughter Inyri is convinced she can talk with animals. She thinks even dangerous predators won''t harm her -- that she can just compliment them on their fur-styles, I guess, and they''ll take a liking to her. I thought this was just funny and sweet, until a servant droid found this note in Inyri''s room. She''s going out into the wilds to test herself! Fortunately I have her coordinates, but I''m housebound right now with an injury. Can you go there and find her? Or if you don''t find her, can you kill whatever''s there? Then I''ll know Inyri can''t get into much trouble, at least in that spot.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 82, 'm21o', 'A Concerned Parent'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 83, 'm21s', 'Thanks. As it happens, Inyri came back home safe and sound. I hope the lesson I gave her will keep her here! Here''s your fee.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 84, 'm21t', 'Lost Child Wants to Talk To Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 85, 'm22d', 'There''s this guy, Bijo? I play sabacc with him? And he''s a tough customer, really sadistic sometimes. I was playing force sabacc with him, I ran out of stakes, and he said, "You can call my bet, but if I win, you go out and get me the skin of the biggest, fiercest animal this planet has to offer." So I called, and I, um, you know, lost? And now I really need someone better with weapons than me to go and kill this thing for me? Is that okay?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 86, 'm22o', 'A Compulsive Gambler'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 87, 'm22s', 'Did you do it? Okay, okay. This may still work. Here''s your money. Yeah, I lost all my money to Bijo in the sabacc game, but I took this from, you know, my wife? What could go wrong?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 88, 'm22t', 'Settle Unusual Gambling Debt'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 89, 'm23d', 'I sent my SE4 servant droid to buy groceries, and of course he got lost. They found his body out in the wilds, but the right index finger is missing. That''s the one with his taste analyzer. I priced a new finger the local Industrial Automaton outlet, and you wouldn''t believe how much they''re charging! It''s cheaper for me to get someone to find whatever attacked my servant, kill it, and then try to recover the finger from its lair, or its large intestine, or wherever. Can you do the job?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 90, 'm23o', 'Disgruntled Industrial Automaton Customer'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 91, 'm23s', 'I''ll send someone to locate the droid finger at those coordinates. I hope digestion hasn''t damaged the analyzer. It''s out of warranty now.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 92, 'm23t', 'Find What Ate My Droid''s Finger!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 93, 'm24d', 'I''m trying to form an import-export partnership with a Shistavanen. Doing business with those wolf-people is always touchy. This one wants me to prove -- get this -- to prove my hunting prowess. I want to tell her I''ve never hunted anything more threatening than a tax deduction, but you know the Shistavanen. I''m willing to pay if you kill a nice big predator, or even a few, and report back so I can pick up the bodies. Let me know which weapon you use, and I''ll try to study up on it so the wolf-woman''s questions won''t find me out.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 94, 'm24o', 'A Successful Import Executive'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 95, 'm24s', 'That''s fine. I''ll have the carcasses picked up, and I''ll try to develop a convincing story. Curiously, the wolf-folk I''ve met don''t seem to mind if you lie to them, as long as it''s a good story.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 96, 'm24t', 'Shistavanen Requires Carcass'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 97, 'm25d', 'Certain offworld societies have unusual beliefs in various folk medicines. Animal teeth, blood, gall bladders, and other parts are used in ointments and inhalants that have beneficial effects. Obviously these native cultures should be permitted to exercise their ancient traditions, even when they may contravene restrictive animal protection laws. Hence, there is a market for whatever you kill at the following coordinates. Discretion essential.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 98, 'm25o', 'A Dealer in Unusual Goods'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 99, 'm25s', 'Excuse me, you''ve killed an animal and you''re telling me about it? Why? I had nothing to do with that situation. However, I do recall that I owe you a fee for an unrelated service, and I now settle that old debt.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 100, 'm25t', 'Help Cultural Differences to Flourish'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 101, 'm26d', 'I need a good-hearted hero to kill the lousy beast that killed my little brother. I don''t remember what kind of beast killed poor Morti, except that it had a pelt of high commercial value. Go to these coordinates and kill that foul beast, or preferably large numbers of them, leaving the pelts intact. Hope to hear from you soon!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 102, 'm26o', 'A Bereaved and Vengeful Sibling'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 103, 'm26s', 'That''s terrific! I mean, at last the spirit of my father -- I mean brother! -- can rest easy, knowing his killer has been reduced to a pelt, preferably undamaged. Here''s your fee. Now please leave me in my bereavement, and don''t mention the pelt''s location to anyone.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 104, 'm26t', 'Hunt Beast That Slew My Brother'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 105, 'm27d', 'GRANT from Planetary Parks & Wildlife Department for control of dangerous native predators. Discovery, apprehension, and culling of certain predatory animals in demarcated Habitat Area (see attached coordinates). At designated location, eligible subjects must meet the following criteria: (A) adult animals only; (B) animals display aggression toward sapient life-forms, including grant recipient; (C) females are not recognizably pregnant or accompanied by juveniles. Payment subject to Performance Guidelines available at Parks & Wildlife Department main office. Direct inquiries to main office.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 106, 'm27o', 'Planetary Parks & Wildlife Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 107, 'm27s', 'Grant payment approved per original directive.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 108, 'm27t', 'Control of Dangerous Native Predators'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 109, 'm28d', 'Greetings! As Deputy Supervisorial Administrator of Gladiatorial Combat for the illustrious Chattza clan, rightful and unopposed rulers of Rodia, I am charged with procurement of suitable animal opponents to face the heroes of our forthcoming Trueblood Olympiad. Because transport of actual animals is prohibitive in cost, I hereby commission you to journey to the selected coordinates and slaughter all hostile animals present. I shall secure genetic samples from the bodies for eventual cloning on Rodia. Proceed forthwith!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 110, 'm28o', 'Mondoola Chattza of Rodia'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 111, 'm28s', 'You show the spirit of the Trueblood Olympians, albeit in an inherently debased non-Rodian form. Accept this payment.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 112, 'm28t', 'Rodian Olympiad Needs Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 113, 'm29d', 'I''m trying to trace the origin of a drug called blue. In small doses it is a euphoric; in larger doses it destroys memory and rapidly ages the victim. Blue has recently killed several young addicts on my homeworld, Bimmisaari. A faint trail of clues has led here. Perhaps the drug originates in the glands of some local animal. To test this idea, I wish to analyze many specimens. I am apportioning locations to all interested parties. Journey to the attached coordinates and kill the animals there, leaving carcasses intact. I wish you luck!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 114, 'm29o', 'Olog Ryjerd of Bimmisaari'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 115, 'm29s', 'On behalf of the Bimm people, I thank you for your efforts. Payment attached. However, after study I believe that the drug called blue does not have animal origins. I must search elsewhere for a solution.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 116, 'm29t', 'Track the Source of Blue'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 117, 'm30d', 'When I open my new cantina, I''ll revolutionize the cuisine scene! I need a centerpiece dish, though, to get people smacking their lips and jowls and mandibles. Go out and find me a selection of delectable beasts. Think novel! If they''re dangerous, that will only add to the publicity value!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 118, 'm30o', 'Chef Jamien Varcos'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 119, 'm30s', 'Splendid. I have a dish in mind already, with jaffa cider and rosettes of Barnaban mist-pudding. I remit your payment with gleeful anticipation!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 120, 'm30t', 'Aid Creation of a Culinary Delight!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 121, 'm31d', 'In my unstinting efforts to open a new cantina, modestly called Chef Varcos Presents, I now face a grave obstacle. A pack of roving predators has repeatedly scavenged my garbage bins. They damaged droids and terrorized my investors. This situation cannot persist. Do what must be done, and I shall pay you.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 122, 'm31o', 'Chef Jamien Varcos'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 123, 'm31s', 'You have enhanced my efforts to bring a new sophistication to local cuisine. I, and my future patrons, salute you!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 124, 'm31t', 'New Light of Local Dining Scene!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 125, 'm32d', 'You know the Ithorians? Some call them Hammerheads. They live on big garden ships that float just above the jungles of their homeworld. Inside the ships they have created all kinds of environments. I''ve lined up a contract to provide one ship, the Tafanda Bay, with genetic material from specimens around here. I''ve got the harmless ones already, but I''m not crazy enough to tackle the predators. Are you? I need a good selection of carcasses.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 126, 'm32o', 'Perdo Thanbris, Interstellar Merchant'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 127, 'm32s', 'You may have killed an animal or two here, but their clones will enjoy a happy life aboard the Tafanda Bay. Thanks!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 128, 'm32t', 'Ithorian Ship Needs Specimens'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 129, 'm33d', 'Do you attend the Lowsummer Intestinal Festival on Banjok? It exposes and celebrates the foundational repulsiveness of our fleeting lives. I grant you, it is not a major tourist destination, but I''m excited to compete in the upcoming Grotesque Gallery. The last winning pavilion featured four-eyed Talz giants trying to play Bith music. The year before, protocol droids danced zero-gravity ballet. For my pavilion I want to sew carcasses of local predators into one ghastly monster, then animate it with strategically placed repulsorlift units. It''ll be horrible! I need several big predators for the display. Can you get them?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 130, 'm33o', 'Jinni Vratik, Biosculptor'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 131, 'm33s', 'This will form the basis of my most gloriously abhorrent work to date. Onward and downward!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 132, 'm33t', 'Help With Grotesque Gallery'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 133, 'm34d', 'Holomodel artist for dejarik games wants reference carcasses for latest contract. Need fierce beasts; uglier is better. Payment on report of success.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 134, 'm34o', 'Lonni Sellastin'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 135, 'm34s', 'I was afraid you''d call. My buddies at work told me they''d staged this prank. You were their tool. Tell you what, I''ll pay you off and take it out of their hides. And be sure I''ll come up with a prank of my own, right back at them!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 136, 'm34t', 'Animal Holomodels Needed'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 137, 'm35d', 'So we got an Imperial license to sink a well over this gonzo vein of rudic, and what happens? The droids are setting up the laser core and bing! some kind of animals or something start running all over the site, scratching and clawing and like that. And wouldn''t you know, the droids got some kind of fancy new self-preservation circuits that make them leave the area until the danger is past. Only the danger ain''t passing, because the animals live there. So I price a technician to rewire those tin-headed glorts and bam! the guy tells me it''s going to take half a season to ship the parts across Strabin Sector. My Imperial license don''t last forever, so I''m hiring some tough guys to solve this problem the direct way. Blast those creatures to pieces and I''ll pay you out of my contract money.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 138, 'm35o', 'Guum Baa Drilling Firm'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 139, 'm35s', 'I always say, fancy droids are no match for a good blaster at your side. Thanks for the handy shooting, kid.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 140, 'm35t', 'Take Care of Droid Problem'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 141, 'm36d', 'Tragically, there were no survivors when our research ship crashed. We cleaned up the wreckage, but the bodies of some of the crew members were missing. Our scanning teams found them a week later. They had been mostly consumed by the local wildlife. Unfortunately the crash resulted from a radiation leak that contaminated the crew members, which means that the creatures who fed on their bodily tissues are now radioactive themselves. We must negate this threat to public health by eliminating every animal that may have been contaminated. Our remote droids have collected the coordinates of dozens of possible nests or lairs. We are contracting civilians to travel to these coordinates and blast whatever animals they find. Applicants are cautioned that the wildlife in these areas is known to be dangerous and the contaminated creatures are, of course, man-eaters. Good luck.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 142, 'm36o', 'Planetary Research Institute'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 143, 'm36s', 'Excellent. Contact us for more coordinates after you have refreshed your supplies. And please submit yourself for a radiation scan at your earliest convenience.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 144, 'm36t', 'Eliminate a Radiation Hazard'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 145, 'm37d', 'Our holy texts mark sacred grounds on many planets. As the influence of Grumsnatch spreads across the galaxy, we must reclaim these sacred spots to build our temples. But some of them are located in dangerous areas, infested with unclean vermin that despoil our good works. We need strong, righteous spirits to smite these beasts of the galaxy from our path. The will of Grumsnatch shall overcome!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 146, 'm37o', 'Galactic Temple of Grumsnatch'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 147, 'm37s', 'Grumsnatch blesses you with his goodwill and some money from his collection bins.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 148, 'm37t', 'Purify Sacred Ground'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 149, 'm38d', 'As a participant in the time-honored sport of unauthorized racing, I expect occasional injuries from speeder wrecks. But some very nasty creatures have burrowed a den next to our drag lanes and now we racers must also avoid being stalked and eaten. Well, I''ve had enough. We can''t ask the authorities for help, so I wish to contract someone to clear the area of any and all dangerous predators. I''m broadcasting the coordinates of our race lanes for anyone who wants a cut of the money.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 150, 'm38o', 'A Speeder Racer'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 151, 'm38s', 'Thanks for your help. Speeder racers like to live dangerously, but that was getting ridiculous.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 152, 'm38t', 'Deadly Creatures in Race Lanes'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 153, 'm39d', 'Inheritance is a risky proposition. My old Uncle Flaa''aa passed away last season and left me a small patch of ground. The area looks nice enough but when I visited in person, I found myself fighting for my life. Let''s just say the wildlife in the area seems a little on the hungry side. I''m okay, thanks for asking, but I do need someone more prepared than I am to go to my new land and exterminate the animals that pose any danger. Make sure you bring a blaster or even something more powerful. I wasn''t kidding when I said I was fighting for my life.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 154, 'm39o', 'An Uncomfortable Heir'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 155, 'm39s', 'Thank goodness you did it. Uncle Flaa''aa also left me a small stash of credits, so I''m considering your services to be one of the many costs of inheritance.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 156, 'm39t', 'Remove Wildlife From Inherited Plot'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 157, 'm40d', 'There ain''t no pride in the galaxy no more. It''s getting so''s a man can''t just hitch freighters between settled worlds without some nasty predator or scavenger raiding his campsite after he lands. Used to be spaceports and shuttleports would clear back them vermin. We could camp outside on the grounds somewhere, no problem. Not no more, though. It ain''t fair, I tell you. So I''m using this here HoloNet machine to find me sombody who can take a laser to these pesky critters and help me get some sleep at night. I can pay you, don''t worry about that. I ain''t totally busted. Honest.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 158, 'm40o', 'A Galactic Tramp'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 159, 'm40s', 'You sure blasted them real good. Here''s the money, just like I said. Thought I didn''t have it, didn''t you? Thought you could start some trouble if I didn''t pay you, right, and the authorities wouldn''t care? You''re messing with the wrong tramp now. I been all over this galaxy. I eat creeps like you for breakfast!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 160, 'm40t', 'Keep Them Pesky Critters Away!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 161, 'm41d', 'At the Imperial Kinder Academy we like to treat every misfortune as a learning opportunity. Not long ago the children were on a field trip when tragedy struck. We happened across the lair of a dangerous predator who proceeded to devour two of our Trandoshan girls, leaving nothing but a handful of scales. As much as this caused the children distress, we used the opportunity to apply our problem-solving skills. In our class meeting we decided to use the funds from our I Am A Loyal Citizen Of The Empire candy drive to pay a professional exterminator to incinerate the predators and then dance on their ashes. The children will be watching this action by means of a hovercam, so the dancing part is crucial. If you love children and have a blaster, please contact Mrs. Yabbo, Grade Four.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 162, 'm41o', 'Mrs. Yabbo, Imperial Kinder Academy'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 163, 'm41s', 'Normally I would withhold payment, as I would hardly qualify what you did as "dancing." But all the children are crying after witnessing this incident, so I have my hands full right now. Just take the money and go.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 164, 'm41t', 'Help With Our Field Trip'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 165, 'm42d', 'I''m in a bind. I was transporting some data cards when thruster problems forced me to land my shuttle on some open ground. It wasn''t until I arrived at my destination that I realized one of the datacards was missing. I must have dropped it while fixing my shuttle. I returned to the place I had landed, only to discover that some unsavory creatures had been attracted by my presence and had now bedded down in the area. When I tried to look for the datacard, they attacked me. Normally I''d just wait them out, but the information on that datacard is quite important. I must find it as soon as possible. I need someone who can get rid of those creatures so I can get on with my business. Be careful; those animals are very, very dangerous.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 166, 'm42o', 'A Distraught Executive'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 167, 'm42s', 'Wonderful. I hope I can find that datacard now and get on with my business. Here is your payment.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 168, 'm42t', 'Assist Executive in a Bind'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 169, 'm43d', 'Communities have to look after themselves these days. Planetary authorities are too sloppy to be reliable, and forget about asking the Empire for help. So we''ve taken up a collection to solve some local problems. Foremost on our agenda is to run off a nest of savage predators who have been threatening children and livestock. We''ve pinpointed the coordinates of the nest. Now we need someone to do the job. I know there are plenty of skilled and rugged individuals around here who are willing to lend aid to a community of decent folk. Come forward and make yourselves known.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 170, 'm43o', 'Community Association'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 171, 'm43s', 'This just proves that hardworking communities can get by without the stewardship of the Empire. I wonder if there''s anything we can do to get rid of them?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 172, 'm43t', 'Rid Community of Savage Predators'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 173, 'm44d', 'Ever tried Gralish liqueur? It''s an exquisite beverage for the most discerning connoisseurs. I''ve hired a master distiller to cook me up a few bottles, but there''s a catch. To complete my order he needs access to a certain type of rare berry. Apparently some very dangerous animals feed on these berries, so obtaining them is risky. The distiller has informed me that this will triple his fee. I, however, am not so fatalistic. I have discovered the coordinates of a patch of these berries. Rather than paying the distiller more money, it is cheaper for me to hire some stalwart individual to take a blaster out to this berry patch and blow the dangerous animals to dust. Then I shall send my distiller to fetch the berries and get on with his work. Sometimes one must take such measures if one drinks only the galaxy''s finest beverages.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 174, 'm44o', 'A Connoisseur of Fine Drink'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 175, 'm44s', 'Most impressive. As a tip I would offer you a drink of the Gralish liqueur, but I''m afraid I find it too precious to share. You have my heartfelt gratitude, though.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 176, 'm44t', 'Fetch Rare and Delicate Berry'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 177, 'm45d', 'One of our experiments has gone awry. We have been developing a serum to transform large animals into reliable war assets. A clerical error resulted in some of our test subjects escaping into the wild. We have dispatched herding droids to retrieve them, but the serum has rendered these animals more dangerous than our droids can handle. We need veteran hunters to find these test subjects and blast them into dust. We can supply the coordinates of their last known location. Qualified applicants may contact us for more information.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 178, 'm45o', 'Imperial Ministry of Research'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 179, 'm45s', 'Handily done. Should the ministry suffer further clerical errors, we may have more opportunities for you in the future.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 180, 'm45t', 'Clutch of Enhanced Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 181, 'm46d', 'Rare and beautiful are the plant colonies that grace the undeveloped regions of the galaxy. The Galactic Botanical Conservancy prides itself on promoting the growth and proliferation of such fine species as the Ithorian donar, the kolvissh of Kashyyyk, and the delightful Nimbanese puzzleflower. Even a desert can nourish such wonders as scrub-loak, pudhoy, and poonten grass. Often in the course of our work we must thin out the population of naturally-occurring animals that interfere with the development of our target plant species. We are always pleased to work with hunters and naturalists who take pride and pleasure in incinerating wildlife in its natural habitat. Please contact us to contribute to this worthy endeavor.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 182, 'm46o', 'Galactic Botanical Conservancy'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 183, 'm46s', 'Take pride in the knowledge that the plant life in our target region will flourish because of your good work.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 184, 'm46t', 'Incinerate Dangerous Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 185, 'm47d', 'The community is devastated. Six of our children have been abducted over the last week. We don''t know who or what has been taking them, but the terror must be stopped! Fortune has it that the sixth child was wearing a signal beacon, which has given us a rough indication of his whereabouts. But the local constable who investigated never came back from the area. A hovercam droid found no trace of any camp or settlement there. We fear the worst. Will someone please go to these coordinates, kill the culprits, and bring back our children? Release our community from the grip of fear!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 186, 'm47o', 'A Desperate Community'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 187, 'm47s', 'Wild animals ate our children! Is there no end to our suffering and woe? Please, take your fee and leave us to our grief.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 188, 'm47t', 'Our Children Are Missing!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 189, 'm48d', 'One of the chief hardships in the Imperial Army is the constant nuisance of planetary wildlife. We lose more stormtroopers to wild rontos and banthas than we ever have to Rebel traitors or planetary resistance forces. As a result it has become our standard operational routine to hire civilian hunters to clean up an area before we construct a new army garrison. If you are qualified to handle large numbers of dangerous creatures, please contact us at your earliest convenience. We shall give you the coordinates of our next garrison placement. Our stormtroopers will thank you for your loyal service.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 190, 'm48o', 'Imperial Army'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 191, 'm48s', 'The Empire thanks you for your faithful service. You have saved the lives of many stormtroopers.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 192, 'm48t', 'Standard Faunal Wipe'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 193, 'm49d', 'I should never have believed those Toydarian soldiers were really as tough as they claimed to be. But there they were, all bristling with blasters and disruptor guns and clad in laser-scarred combat suits, their trunks poking out of their helmets like little, wrinkled tassels. How could I resist hiring such an adorable bunch of soldiers? I sent them to my family''s land with orders to take out some dangerous animals who have terrorized our Ugnaught maintenance crews. But they never finished the job. I''m not sure if they perished in the attempt or just skipped off the planet with my hard-earned credits. But now I need some real freelancers to do the job right. Go to the coordinates I give you, blast the creatures to ashes, and see if you can find any trace of those Toydarians. I''ve learned my lesson; I''ll pay you after the job is finished.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 194, 'm49o', 'Sheel Strand'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 195, 'm49s', 'No trace of the Toydarians, eh? So the little creeps ran off with my money like thieving little monkey-lizards. That''s what I get for hiring someone for their looks. Luckily I didn''t make that mistake twice. Here''s your payment.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 196, 'm49t', 'Mess Left by Toydarians'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 197, 'm50d', 'Wild animals killed our parents! We''re all alone now in this big galaxy, just four orphaned Rodians with nowhere to go. But we''ve scraped together all we have left so we can hire someone to kill the murdering beasts who took our parents away. It''s not much, I know, but we had to keep a few credits for little Teemo''s medicine. Can you help us? We got the coordinates of the monsters'' den off the forms for the Imperial inheritance tax. Please, it''s already so hard to sleep in an abandoned cargo bin like we do. With these creatures killed, at least the nightmares might stop.'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 198, 'm50o', 'Four Rodian Orphans'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 199, 'm50s', 'At last our luck is turning around! You''ve killed the monsters who took our parents, and now we''ve been offered passage on an offworld ship by a wonderful Hutt named Gardulla. Here, take your fee! Gardulla says we won''t even need money where we''re going. Can you imagine?'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 200, 'm50t', 'Children''s Revenge!'),
('string/en/mission/mission_destroy_neutral_medium_creature.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 1, 'm1d', 'Hey, fella! Or maybe "Hey, lady," or "Hey, thing," I don''t care. I have this package that urgently needs to go to a certain destination, where a certain party will retrieve it later. I just scouted the area, and whoa, it''s crawling with critters. I can handle a blaster as well as the next guy -- assuming the next guy is sort of a coward -- but big-game hunting is out of my league. I''m willing to cut you in on part of my pay if you dispose of these creatures. Take the hide, the meat, whatever looks tasty, I don''t care. But do it fairly quick, huh?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 2, 'm1o', 'A Corellian Entrepreneur'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 3, 'm1s', 'Great pest disposal there! Here''s your cut, and feel free to loot the bodies. I expect the rest of this operation will go off without a hitch. What could go wrong?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 4, 'm1t', 'Creature Removal at Local Drop Point');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 5, 'm2d', 'I''m out here in the middle of noplace, where I had a run-in with a client after a transaction went bad. I don''t think it''s productive to get into "who shot whom," but now this guy has it in for me. Who knew he kept all kinds of dangerous beasts in, I don''t know, a kennel or something? He''s sicced these things on me, and let me just say I''m not much of a hunter. I''m holed up in a safe spot for the moment, but they''re prowling closer. I would REALLY LIKE someone to come out here and take care of these things, permanently. I''ll pay! I''ll pay a lot!'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 6, 'm2o', 'Corellian with Unfortunately Short Temper'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 7, 'm2s', 'Okay, I''ve caught my breath, I''m all right. Nice work. I took the liberty of making an exit while you did your deed. Here''s your pay, hope I don''t have to use you again.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 8, 'm2t', 'Dispute Has Escalated to Surprising Degree'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 9, 'm3d', 'I have a can''t-miss business proposition. You kill the animals, I record your exploits and sell the broadcast rights to a local HoloNet program my buddy is starting up. It''s not there yet, but the investors want to see content, so we''ll pay you out of our seed money for a dynamic, gripping slaughter-fest. I''ve located the animals, I''ve rented the hovercams and set them in place, I''ve got it all arranged, so all you have to do is relax and blast a few beasts into Corellian dust. Maybe that''ll be the title of your segment, "Blast Them to Corellian Dust!" Whaddya say?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 10, 'm3o', 'On Our Way to the Corellian Dream'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 11, 'm3s', 'That was great! My recording is sure to sell this show. I''ll just -- oh, wait -- was this the "on" switch, or --? Tell you what, I''ll get back to you.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 12, 'm3t', 'Blast Beasts For HoloNet Show'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 13, 'm4d', 'Understand first that I''m just the flunky here. It''s not my operation. So I don''t have a reason why these guys all started shooting at me. I was just the delivery boy! I stole a speeder and ran for the horizon -- they followed -- a certain amount of blaster fire occurred -- everybody crashed, and then these giant -- somethings leaped out and killed everyone but me. I got away narrowly, but now my employer strongly requests me to recover the item I delivered. I expect it''s now in the belly of one of those animals, so I''m asking you to shoot them all and let me recover the innards later. Believe me, this has been a rotten day. '),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 14, 'm4o', 'Corellian Just Trying to Do a Job'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 15, 'm4s', 'Okay, at last one thing goes right. I''ll speed back out there and do the excavation, or whatever you call it. Thanks, here''s your fee.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 16, 'm4t', 'Recover Item From Animal Intestines'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 17, 'm5d', 'Talk all you want about the evil Empire and how these are bad times, but I''ll say this: The rise of the Empire has been very good for my business. There''s always a demand for the service I provide. It calls for piloting down some risky off-road routes, though -- and it never helps when a pack of animals takes up residence right along my main "back way." Which is what''s happened now. I''ll pay you well to go in and blast them into permanent inconsequentiality. Hey, nice phrase, huh?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 18, 'm5o', 'A Corellian Businessperson'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 19, 'm5s', 'Fine job. It''s a pleasure dealing with professionals. Your fee is attached.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 20, 'm5t', 'Corellian Beasts Menacing Back-way Traffic'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 21, 'm6d', 'Sheesh, I am so down on life right now. I mean, I had a nice line of work, running some goods here and there for my employer. And you know, what with the stuff I brought them, folks were always, always glad to see me. But then I got greedy -- they tell you never to get greedy, but I did! -- and I took a cut from my employer''s earnings that I wasn''t entirely entitled to. We parted on really bad terms, you might say, and -- long story short -- now I''m holed up in the wilderness with a bunch of hungry animals roaring for my guts. It''s so depressing. If you can see your way clear to destroying these beasts, I''ll cut you in on those earnings I mentioned.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 22, 'm6o', 'Corellian in Need of Quick Emotional Lift'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 23, 'm6s', 'Okay, something''s finally going right. I took the opportunity to run for the city while you were out there fighting. Nice job, and here''s the pay you earned.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 24, 'm6t', 'These Animals Depress Me'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 25, 'm7d', 'I''ve flown from one end of this galaxy to the other, and I never saw anything to make me believe you can control a bunch of wild animals just by pointing your finger. But during a transaction out here in the wilderness I happened to offend this weird mystic-looking woman -- never mind how. She raised a claw, and a bunch of beasts rampaged in out of nowhere, eager to have a little Corellian snack. It must be pheromones or perfume, maybe -- something long-lasting, because they''re still trying to rip open this vehicle like a food container. I''ll pay you well to come here and take care of this problem, immediately and for good.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 26, 'm7o', 'A Corellian Wanderer'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 27, 'm7s', 'That''s a big relief. I took the opportunity to speed out of there while you were working. That Selonian may come back. In fact, maybe it''s time to visit Sullust. I always wanted to visit Sullust.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 28, 'm7t', 'Selonian Pets Unjustly Attack Speeder'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 29, 'm8d', 'It is incumbent on my clients to retain confidentiality, so I must be circumspect in describing my problem. Briefly, I arranged a transaction in a remote area between two parties, and was planning to mediate at this exchange of ideas and goods. However, an animal or animals has menaced my clients as they travelled to this remote area. This has discouraged them from pursuing the transaction. Because of the importance of a successful resolution, I am commissioning you to journey to the attached coordinates and dispatch the animal or animals. Payment is reasonable for this brief service.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 30, 'm8o', 'Itinerant Corellian Transactional Specialist'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 31, 'm8s', 'I congratulate you and tender the agreed payment. I shall inform my clients at once.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 32, 'm8t', 'Transaction Hampered by Wildlife'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 33, 'm9d', 'In these troubled times an individual may wish to journey between locations without undue Imperial attention. I serve this reasonable desire. However, on my current transport assignment, a beast of unusual ferocity damaged my speeder, stranding me and my client in unfortunate circumstances. I''d like you to journey to this general vicinity and destroy the beast and, if needed, its fellow pack members. Under no circumstances are you to search for me or my client, who strongly requests anonymity. I will transmit payment when you have performed the service.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 34, 'm9o', 'Corellian Specializing in Discreet Transport '),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 35, 'm9s', 'Excellent. I appreciate your discretion in avoiding contact. Your payment is attached. I have repaired my speeder and must now resume the transport contract.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 36, 'm9t', 'Rescue Anonymous Travellers'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 37, 'm10d', 'I need to get out into the countryside and dump this bag of garbage, right? I mean, I''m dumping it at a particular spot before a particular time, so that a particular garbage collector can retrieve it. Don''t worry, it''s just garbage. Trouble is, I scouted the territory from a distance, and there''s all kinds of animals wandering around. I mean big ones, with teeth and all. I don''t mess with that, especially while carrying this, uh, garbage. You take care of the animals, like by killing them all, and I''ll cut you in on my hauling fee.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 38, 'm10o', 'Corellian Urgently Seeking Waste Disposal'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 39, 'm10s', 'All right, you just clear out of that area, and I''ll dump my garbage. Thanks for the rescue. Lots of stress in the garbage-dumping line, let me tell you.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 40, 'm10t', 'Help Me Dispose of This Garbage'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 41, 'm11d', 'I love animals, I really do. Why, the times I''ve diverted my speeder to avoid hitting some harmless eopie or cute little kittle -- even though it delays my courier mission, mind you, and my employers really don''t like delay -- well, I admit, I''m a softie. But it''s time to take a hard line with this current pack of beasts. They''re trouble. And when you make trouble by interfering with my speeder on a major overland route, a route that nobody in an Empire suit has ever seen, then you''re in pretty dangerous territory yourself. The animals are, I mean. In that territory. Um, I''m losing the thread of my subject here -- basically, even though I love animals, I need you to kill this bunch before they ruin my business. Clear?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 42, 'm11o', 'Corellian Breaking a Strong Emotional Attachment'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 43, 'm11s', 'Of course it''s a sad time, what with the death of those innocent animals. But you know, it had to be done. I think I''m almost over it now, the heartbreak I mean. Gotta go.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 44, 'm11t', 'Take Hard Line Against Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 45, 'm12d', 'Our business is selling fireworks, but now that I think about it, nobody''s bought fireworks for, oh, ten or fifteen years. So we buy and sell certain other things, and business is okay. It''s just -- we have this animal problem. We were carrying certain valuable non-firework commodities through a remote area recently, on our way to a delivery, when something large and fierce and active jumped us. It was dark, so we couldn''t see. When we got away, we realized we''d dropped our commodities. We really would like to go back and get them, but we need you to clear the area of dangerous animals first. We''ll pay you from our fireworks production budget, which we don''t use any more.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 46, 'm12o', 'Corellian Fireworks Transport'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 47, 'm12s', 'A fine job. We could use more people like you in the fireworks business.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 48, 'm12t', 'Help Fireworks Dealer Get Past Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 49, 'm13d', 'Despite pervasive public ignorance and apathy, the Interplanetary Embalmers'' Guild labors heroically to inform the galaxy of its worthy mission. Our chapters on Corellia exhibit all the vigor and pertinacity that a good embalmer should. We seek Corellian hunters to locate the finest specimens of wildlife, no matter whether on the grassy hillsides or the golden beaches or the towering peaks, and shoot them cleanly. We shall arrange pickup and processing of the remains, provided they are intact and relatively unmarked. Do your part to help a noble profession achieve just and lasting recognition.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 50, 'm13o', 'Interplanetary Embalmers'' Guild'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 51, 'm13s', 'Though your good work fulfills the Embalmers'' Guild wishes, our plans have changed. Accept this payment, and do what you will with the creature.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 52, 'm13t', 'Embalmers Call on Conscientious Corellians!'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 53, 'm14d', 'The Emperor''s proposed new Hall of Galactic Wildlife, to be built on the Imperial throneworld of Coruscant, features an extensive display of Corellian fauna. To expedite planning of the space required for the Corellia display, the Imperial Civilian Accounting Office solicits highly experienced hunting teams. Interested teams may locate and terminate large packs of animals at coordinates provided by local survey offices in conjunction with this agency. The specimens will be assessed for size and quantity for purposes of figuring large-scale space requirements. Hunters may remove marketable assets from the prey for their own use. All other information on this contract is assigned confidential clearance under Imperial security edicts. For assistance, contact the Imperial Security Bureau.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 54, 'm14o', 'Imperial Civilian Accounting Office'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 55, 'm14s', 'Asset procurement noted and contract payment disbursed. Per your contract, you may remove marketable assets from the prey for your own use or resale.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 56, 'm14t', 'Solicitation For Corellian Hunting Teams'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 57, 'm15d', 'I am an archaeologist with Coronet University. My field team has been excavating in a remote area, searching for a supposed network of Selonian tunnels that apparently predates the Old Republic. My colleagues are skeptical, but our research was starting to show promise -- until a band of local animals began menacing our camp. This has upset my students and threatens to drastically set back our schedule. I have appealed to the Empire for help, without result. The University has kindly granted me an additional stipend to be disbursed to an agent such as yourself, who can destroy these beasts and permit the continued march of science.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 58, 'm15o', 'Dr. Tennet Sionaro, Coronet University Archaeology Dept.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 59, 'm15s', 'Splendid! Our dig will resume immediately. I must admit I hold out little hope of finding these putative Selonian tunnels, but one cannot dismiss such tales out of hand.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 60, 'm15t', 'Coronet Archaeology Site Menaced'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 61, 'm16d', 'Corellian Horticultural Digest, now entering its third century of publication, sends researchers hither and yon across our wild Corellian landscape. One brave investigator, following a hot lead regarding trioecious cycad carpophylls, blundered into a lair of dangerous beasts. In his last communication before his comlink got eaten, our man said he had sequestered himself in a place of safety. Please journey with all haste to his coordinates and dispatch these beasts.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 62, 'm16o', 'Corellian Horticultural Digest'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 63, 'm16s', 'Joyous news! While you occupied the beasts, our researcher made a rapid escape and is even now dictating his notes. Trust us, this article will break the entire cycad carpophyll field wide open.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 64, 'm16t', 'Horticultural Researcher Under Siege'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 65, 'm17d', 'In addition to its well-known repair facilities, Guildhouses, and financial services, the Merchants'' Guild offers Corellian members basic travel information about every region of Corellia. We contract with independent researchers to assess the dangers that may await members stranded in remote locales. To participate in our current research cycle, please report to the attached coordinates to engage and destroy the animals present. Guild hovercams will record the event, and we shall update our guidelines based on our assessment of the threat posed.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 66, 'm17o', 'Corellian Merchants'' Guild'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 67, 'm17s', 'Our hovercams recorded the event, and we are updating our guides accordingly. Thank you for participating in this research cycle.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 68, 'm17t', 'Surveying Creature Ferocity'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 69, 'm18d', 'A local entertainment figure, Bop Thrombo the Shaky Droid, got into animal trouble out in the wilderness while rehearsing his latest slapstick stunt. This is big news for Corellian comedy fans. Our hovercams track Bop at all times, just in case, and we''ve got great views of this fierce something-or-other tearing him to bits. Now we''d like to recover his brain for an interview, but we need someone to clear out the animals first. Can you help?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 70, 'm18o', 'Corellian Sector Newsfeed'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 71, 'm18s', 'Great! We''ll send out a news crew to put Bop Thrombo''s brain into a duplicate housing and get the on-the-scene interview. Clear out before we get there, please.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 72, 'm18t', 'Help Recover Bop Thrombo''s Brain'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 73, 'm19d', 'We''ve tracked yet another starship that squeaked past Orbital Customs. Our turbolasers crippled the vessel and it crashed near the Golden Beaches. Trouble is, the ship was smuggling some dangerous animals that were jettisoned in escape pods for later retrieval. We recovered the pods but the animals had already escaped. Our scout droids have found them, snugly settled a few clicks from the pod site. We''ve already wasted enough manpower on this problem, so we''ve decided to contract civilians to exterminate these animals before they cause any harm. Contact us for the coordinates and we''ll put you on the case.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 74, 'm19o', 'Corellian Defense Force'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 75, 'm19s', 'Thanks for handling that potentially dangerous situation. We''re sending out a team to dispose of the carcasses.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 76, 'm19t', 'Exterminate Contraband Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 77, 'm20d', 'It''s not that I don''t appreciate the beauty of the Agrilat Swamp. Boiling showers and razor-sharp grass are a joy to experience. But when the swamp''s larger wildlife chooses to wander into more civilized areas, I''ve got to draw the line. The farmers in the area are getting worried. They''ve asked me for help. I don''t want to waste Corellian Security resources on this, so I''m paying any civilian who can do the job to find these misplaced creatures and put them out of my misery. Call it restoring the ecosystem.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 78, 'm20o', 'Lieutenant Moss Shelby, CorSec Regiment Twelve'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 79, 'm20s', 'Nice. The farmers aren''t worried anymore and that means I''m getting fewer interruptions at work. Everyone is happy.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 80, 'm20t', 'Large Creatures on the Move'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 81, 'm21d', 'Remember when the Circus Horrificus came to Corellia a while back? Turns out they "misplaced" some sick animals while they were here. Now we''ve got reports that these creatures miraculously recovered from their illnesses and are now threatening the safety of some farmers near here. Removing them could be time-consuming endeavor, so we''re contracting civilian hunters to deal with the situation. Contact us and we''ll send you the last known coordinates of these wayward beasts.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 82, 'm21o', 'Captain Peers, Corellian Defense Force'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 83, 'm21s', 'Maybe we shouldn''t be surprised that an outfit called Circus Horrificus left behind a mess. The next time they grace Corellia with a visit, we''ll sit down with them for a long chat.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 84, 'm21t', 'Circus Horrificus Left a Mess'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 85, 'm22d', 'Even though the shipyards get all the glamor, we farmers are the real backbone of Corellian culture. Who else is going to feed all those offworlders who pollute the space lanes with industrial waste? But even so, the planetary authorities are eager to neglect our needs. For instance, we''re having a problem with some local wildlife encroaching on our fields. CorSec isn''t interested in helping us. So we collected enough credits among ourselves to pay a professional hunter to get rid of these intrusive animals. Seems like we have to handle our own security in addition to feeding a hungry planet. There''s no justice, I tell ya.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 86, 'm22o', 'A Proud Corellian Farmer'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 87, 'm22s', 'Thanks for getting rid of those creatures. You''re a good friend to us farmers. I''m glad someone on this planet still cares about us.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 88, 'm22t', 'Job That CorSec Doesn''t Want'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 89, 'm23d', 'While the Selonian Tunnels are an interesting feature of the Corellian landscape, they do present certain problems for planetary security. For instance, animals that are either large or numerous enough to be a nuisance will wander the tunnels and emerge in places where they should not be. These incidents are frequent enough that CorSec now engages freelancers to liquidate the stray animals. This program is open to all qualified galactic citizens. Coordinates of target animals are available upon request.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 90, 'm23o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 91, 'm23s', 'Nice work, citizen. We''ve got many more stray animals to deal with, so feel free to contact us again.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 92, 'm23t', 'Animals Wandering Selonian Tunnels'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 93, 'm24d', 'The right place at the right time, that''s what business is all about. I''m planning to build a small manufacturing plant and I picked up some terrific property from the estate bazaar in Coronet. You wouldn''t believe the price I got. I feel like a regular thief. The only drawback is, the land is infested with some kind of dangerous animals. That''s what the purchase agreement said, anyway. All I know is, I want some tough guy to hoof out there and get them off my property. I''m working to fund my little factory and I need to haul investers out there soon. I''ve got the right place, but I have to hurry to finish at the right time. Are you the right person for the job?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 94, 'm24o', 'Fillig Tandaris, Entrepreneur'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 95, 'm24s', 'Now that was some handy work, my friend. You''re better than you look. Stick around, maybe I''ll find something else for you to do.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 96, 'm24t', 'Fine Print on Purchase Agreement'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 97, 'm25d', 'Corellia seems like such a peaceful planet, doesn''t it? Well, it ain''t all purple skies and golden fields. We''ve got some nasty animals around here that are giving me all kinds of headaches. My construction droids are malfunctioning because some sort of wild beasts are tearing up their wiring and fouling their exhaust grates. I programmed a few load lifters to chase the creatures back to their lair, but I need a flesh-and-blood hunter to finish them off. I''ll pay a decent wage for the work, so long as I can get back on schedule.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 98, 'm25o', 'Fillig Tandaris, Entrepreneur'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 99, 'm25s', 'Handy work, my friend. If I apply a little motivation to my droids, maybe I can get back on schedule.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 100, 'm25t', 'Wild Beasts Fouling My Droids'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 101, 'm26d', 'Corellia! Proud center of commerce for the entire galaxy! I''m thrilled to be here at last, ready to carve my niche in financial universe, though my business plan has proven inadequate in a few respects. I didn''t know Corellia''s wildlife was quite so intrusive. To be brief, the site for my new office complex is overrun with native creatures. As I just arrived, I don''t even know what they''re called, but I do know they approach me threateningly when they see me. I require someone who knows the area wildlife to do whatever it takes to get rid of the beasts. I can''t let teeth and claws interfere with my conquest of galactic commerce!'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 102, 'm26o', 'Mister Tild-Ob-Hoona, Recently Arrived on Corellia'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 103, 'm26s', 'Wonderful! Now that those creatures are gone, I can proceed with my plan to amass a fortune and build a mercantile empire. Would you like to invest?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 104, 'm26t', 'Corellia Wilder Than I Thought'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 105, 'm27d', 'We were flying home after a Kessel run. We crash-landed due to a spat with the Imperials. The trip home from the crash site was, how should I say it, eventful. Among other highlights, we ran into some kind of big roaring thing in the dark, and we had to drop some cargo. Fast. Still makes me shudder to remember it. We''re safe back home now, but we need to retrieve that cargo. We don''t want to face the roaring thing again, whatever it was, so we''re hiring you to dispose of it before we arrive. We''ll retrieve the cargo ourselves, thank you.\n\nm27o\nCorellian Travellers Home at Last\n\nm27s\nIn a long string of unhappy events, this is finally good news. Here''s your fee, and we''re on the way now to pick up our cargo.\n\nm27t\nClear Out Site of Lost Cargo\n\nm28d\nI''ve had an accident that I need to clean up. For reasons I won''t bore you with, I was flying my YT-1300 freighter close to the ground not far from this terminal when my power core ruptured. I leaked radioactive fuel into a small water system. It was all I could do to limp back to Tyrena before the Corellian authorities spotted me. Now I''m worried that the animals who drank that water are going to glow. The radiation signature might lead the authorities back to me. I want to hire you to blast the animals at the following coordinates into their component atoms. My gratitude will be boundless, if discreet.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 106, 'm28o', 'A Freighter Captain'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 107, 'm28s', 'Thanks, kid. You really saved my neck. Have some fun in Tyrena, on me.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 108, 'm28t', 'Help Clean Up a Little Mess'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 109, 'm29d', 'You may have heard of the swoop course we run over in the mesas. Some of us intend to branch out and clear some new lanes around the planet. Can you imagine swooping through Agrilat or even the Selonian Tunnels? But there''s a lot of dangerous animals out there that are definitely not welcome on a course. We''ve pinpointed a list of trouble spots for future races. The animals must go. We''ve got the money to pay you for the work, if you''ve got the talent to crush these creatures.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 110, 'm29o', 'An Enterprising Swoop Enthusiast'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 111, 'm29s', 'Wizard, buddy. We''re heading out there now to fly the route. If you''ve got a swoop, why don''t you join us?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 112, 'm29t', 'Swoop Lanes With Wild Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 113, 'm30d', 'These rich Naboo are starting to bother me. We had a family buy a plot on Vreni Island to build a vacation home. Of course they had to remove some of the wildlife. How did they accomplish that, these oh-so-enlightened Naboo? You guessed it. They stunned the creatures, tossed them on a transport and dumped them at some random spot on the mainland. Because killing them would be cruel, or whatever. Anyway, now we''ve got to put these animals to sleep before they hurt somebody. I''ve got a small budget to hire a hunter for the task. Are you interested?'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 114, 'm30o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 115, 'm30s', 'You did good work. It''s ridiculous that we had to eliminate those animals, but we can''t stem the tide of "enlightenment" rising from Naboo.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 116, 'm30t', 'Episode of Naboo Enlightenment'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 117, 'm31d', 'Last week we tracked a gang of Lamproid smugglers to a meeting ground a short distance from this terminal. The smugglers dispersed but they left us with a problem. Apparently they had collected a small menagerie of ill-tempered animals to stage a live version of dejarik. The Lamproids freed the animals when we arrived. Now the creatures have built lairs all over the place. This problem is best handled by experienced hunters who know the area. CorSec will pay a nominal fee for the destruction of any of these lairs. Contact us for target coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 118, 'm31o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 119, 'm31s', 'Good job, citizen. These animals are a threat to anyone traveling through the area. If you care to have a go at another lair, just contact us.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 120, 'm31t', 'Lamproid Smugglers: a Messy Bunch'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 121, 'm32d', 'When you''ve got as much open countryside as Corellia, people start thinking they can land their ships anywhere and set up for business. While we do not discourage non-traditional commerce, we do insist that freelance entrepreneurs respect the planetary landscape. Lately we''ve had problems with campsites left behind by itinerate businessmen. The garbage at these sites attracts wildlife of a bothersome and sometimes dangerous nature. This is a nuisance for local inhabitants. While the law enforcement arm of CorSec pursues the culprits, the ACD is left to clean up the messes that have already been made. For this purpose we regularly contract hunters to exterminate the animals that wander too close to populated areas. Contact us for the coordinates of target sites in your area.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 122, 'm32o', 'Corellian Security Force, Animal Control Division'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 123, 'm32s', 'Well done. You''ve made the area safe for the locals again. Hopefully we can catch the culprits whose trash lured those animals from the wilderness. We all agree that non-traditional commerce is a vital component of the Corellian economy, but a few people have to learn that some rules still apply.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 124, 'm32t', 'Messes Left by Itinerant Businessmen'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 125, 'm33d', 'Does anyone like the Empire snooping in his private affairs? I certainly don''t. Strictly in the interest of personal privacy, I''m going to build a sensor scrambling array not far from here. The site is in the wilderness and is, unfortunately, a bit thick with large animals. I''d like to hire you to remove these creatures from my property, so I can begin construction. If you can do the job, let me know and I''ll send you the coordinates. You can''t miss the place. It''s in a wide-open field where you might expect to find a landing pad, say, or maybe an underground warehouse. Not that I would know about such things.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 126, 'm33o', 'A Right-Thinking Businessman'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 127, 'm33s', 'Good, good. Now I can build those sensor scramblers. I don''t want the Empire watching when I have visitors to my, um, field out in the wilderness.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 128, 'm33t', 'Clear Land for Sensor Scramblers'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 129, 'm34d', 'I''m in a predicament. I just had a flyby with an Imperial shuttle and it forced me to land not far from here. My ship went down pretty rough, but I made it to the city okay. Unfortunately, I didn''t realize until I hit town that I had buckled a cargo door and lost a crate of Mad Mrelf in the wilderness. I buzzed the spot again and it''s overrun with animals. If those creatures finish off a whole crate of that liquor, they''re going to go berserk. Can you go out there and take a blaster to those beasts before someone gets hurt? From the air I couldn''t make out exactly what kind of animals they were, but you should be ready for a real scrap. That Mad Mrelf will put scales on a Qwohog.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 130, 'm34o', 'An Unfortunate Pilot'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 131, 'm34s', 'You handled those creatures better than I could have. Didn''t I tell you that Mad Mrelf would turn a voorpak into a veermok? That''s quality stuff. Such a waste to lose it.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 132, 'm34t', 'Liquor Fallen Into Wrong Hands'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 133, 'm35d', 'See here, I need the services of a veteran of the Corellian wilds. I am recently arrived from Naboo to acquire some native fauna for my daughter''s menagerie at Theed. I hope to bring my little Lady Gaeflit something large and glamorous for the Festival of Thywinkle, but my time grows short. A local tracker in my employ has transmitted to me the coordinates of a group of wild animals which he believes will be suitable for my purpose. I require someone who knows the area to travel to these coordinates and bring back the creatures in question. Of course I understand the unpredictability of wild animals, so I shall of course pay you something for your trouble if you find no living specimens at that destination. Please be cautious and know that your good work will make a little Naboo girl happy.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 134, 'm35o', 'Lord Kindergull of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 135, 'm35s', 'What''s that? You say no living specimens are left at those coordinates? Oh, but this is a tragedy! Now what gift shall I bring poor Lady Gaeflit for the Festival of Thywinkle? Her little heart will be crushed! At least I know you did your best to make her happy. Here, accept this payment with my gratitude.'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 136, 'm35t', 'Make a Little Naboo Girl Happy'),
('string/en/mission/mission_destroy_neutral_medium_creature_corellia.stf', 137, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 1, 'm1d', 'Laboring under a curse of public ignorance and apathy, the Interplanetary Embalmers'' Guild maintains its resolve to bring its mission to a wide audience. Our chapters on Naboo, though not large, demonstrate an admirable vigor. We seek Naboo hunters with strong will, careful aim, and superior firepower. With these weapons, you will go forth onto the plains, into the forested mountains, and even into the swamps themselves, to locate the finest specimens of Naboo wildlife and shoot them cleanly. We shall arrange pickup and processing of the remains, provided they are intact and relatively unmarked. Those who aid in promoting our worthy trade will find generous recompense!'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 2, 'm1o', 'Interplanetary Embalmers'' Guild'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 3, 'm1s', 'Though your good work fulfills the Embalmers'' Guild wishes, our plans have changed. Accept this payment, and do what you will with the creature.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 4, 'm1t', 'Embalmers Call On Conscientious Naboo!'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 5, 'm2d', 'The Emperor''s proposed new Hall of Galactic Wildlife, to be built on the Imperial throneworld of Coruscant, features an extensive display of Naboo wildlife. To expedite planning of the space required for the Naboo display, the Imperial Civilian Accounting Office solicits highly experienced hunting teams. Interested teams may locate and terminate large packs of predators at coordinates provided by local survey offices in conjunction with this agency. The specimens will be assessed for size and quantity for purposes of figuring large-scale space requirements. Hunters may remove marketable assets from the prey for their own use. All other information on this contract is assigned confidential clearance under Imperial security edicts. For assistance, contact the Imperial Security Bureau.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 6, 'm2o', 'Imperial Civilian Accounting Office'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 7, 'm2s', 'Asset procurement noted and contract payment disbursed. Per your contract, you may remove marketable assets from the prey for your own use or resale.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 8, 'm2t', 'Solicitation for Naboo Hunting Teams'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 9, 'm3d', 'Greetings. Milady Chantallir requires me to commission a hunter, or party of hunters, to assassinate a designated specimen or specimens of local wildlife. Once you have committed this gratuitous murder, Milady''s serving droids will collect the victim and prepare it for her upcoming "Cuisine & Culture" fundraising banquet. Milady has instructed me to remit payment after you have inflicted the brutal death.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 10, 'm3o', 'Imbecile, a C-9P0 Protocol Droid'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 11, 'm3s', 'Milady will undoubtedly feel well disposed toward you for carrying out the execution. Here is the agreed blood-money.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 12, 'm3t', 'Dead Animal Needed for Banquet'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 13, 'm4d', 'The touring company for my current production -- "Hearts of Empire," now at Theed''s Templexus of the Dramatic Arts, seats still available -- has run into a teensy problem. Our female lead, Mairlenn, had a pet voorpak, called Dotti or something. She took the little thing with her on a visit to the countryside, let it roam, and, well, those voorpaks really are a major source of protein in the ecosystem, aren''t they? Mairlenn is in quite a snit. She saw the creatures that ate Dotti, and she insists that I find someone to locate and punish those beasts, I mean really punish them. Is that okay?'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 14, 'm4o', 'Radanthus Mandelatara, Playwright'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 15, 'm4s', 'Well, isn''t that just a big big relief. I do have a budget line item for Mairlenn''s demands, so payment is no problem. Thanks much, have to run.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 16, 'm4t', 'Punishment of Naboo Predator Needed'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 17, 'm5d', 'When I open my new restaurant in Theed, the much-heralded pantheon of Naboo chefs will gain a new star! I need a centerpiece dish, though, to get people smacking their lips and, in the case of Gungans, jowls. Go out and find me a selection of delectable beasts. Remember, dangerous creatures equal publicity!'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 18, 'm5o', 'Chef Jamien Varcos'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 19, 'm5s', 'Splendid. I shall pay you, of course, but as it happens, I have conceived a different dish in mind already, with liquid extract of Corellian fringe cake. Please take what you will from the creature''s body.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 20, 'm5t', 'Create a Culinary Delight of Naboo!'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 21, 'm6d', 'For my new gallery''s debut show, I contrast the sterility of urban life with the pure, unmediated vigor of Nature. I envision in the gallery atrium a mounted specimen of some noble creature. It befalls you, the hunter or team of hunters, to terminate the specimen, whereupon my rented droids will secure and prepare it. I suggest a relatively non-invasive termination, to maintain the specimen''s natural beauty.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 22, 'm6o', 'Bab Esrus, Biosculptor for Select Clients'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 23, 'm6s', 'Unfortunately my show, "Nature''s Unmediated Vigor," has been unexpectedly cancelled. I shall pay you, but you may dispose of the creature as you will.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 24, 'm6t', 'Help With Naboo Gallery Show'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 25, 'm7d', 'I watch the purple twilight steal across the meadows of my estate, then spend my lonely night dreaming of a song. That melody haunts my reverie, for it was playing during my romantic dinner with Count Ran Dobell. We sat beside a garden wall, and the stars shone bright. Our love was new, each kiss an inspiration -- until a verminous creature blundered into my gazebo. The beast bit Count Dobell, infecting him badly. In a huff he lurched away to the bacta tanks, and he has avoided contact with me since. Now my consolation lies in hiring you to destroy this creature and others of its ilk.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 26, 'm7o', 'Lady Dera Mikkel of Theed'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 27, 'm7s', 'Thank you. Though I dream in vain, that melody will remain in my heart -- the memory of love''s refrain. '),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 28, 'm7t', 'Stop Creature That Ruined True Romance'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 29, 'm8d', 'Perfecton Greysor Purebreds stands as Naboo''s finest kennel. We have reason to believe that an unidentified rival greysor kennel has purposely loosed several predatory animals on our land, creatures that have already attacked and killed several fine stubtails and manadepts of breeding age. We shall of course investigate and seek legal redress. Our immediate need, though, is a hunting team that can destroy the marauding predators. We offer a generous fee, as befits the planet''s elite kennel.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 30, 'm8o', 'Perfecton Greysor Purebreds'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 31, 'm8s', 'Your success shows excellent attention to standards and detail. We thank you, and are now preparing the legal phase of our response.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 32, 'm8t', 'Predators Loosed On Greysor Kennel'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 33, 'm9d', 'I am a Theed University biologist currently on sabbatical at the Otoh Gunga Zoological Research Facility. In researching motts, a semi-aquatic herbivore of the Gungan Swamp, I was stunned to observe young adult males occasionally travelling onto the Great Grass Plains and even up mountains, far outside their native habitat. This phenomenon as yet eludes explanation, though I suspect parasitic infection. In every case I have seen so far, predators kill these misplaced motts. I wish to hire a hunter or hunting party to terminate a predator shortly after it eats the mott. I shall analyze the predator''s stomach and blood, in hopes of identifying different stages in the life-cycle of the hypothetical parasite.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 34, 'm9o', 'Dr. Henro Torrth, Theed University Bio Department'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 35, 'm9s', 'Report noted. I shall have the fallen predator picked up for autopsy. Your fee is attached.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 36, 'm9t', 'Naboo''s Misplaced Mott Mystery');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 37, 'm10d', ' My family wrangles shaaks on the Grass Plains. This season predators have been hitting us hard. Two nights back, my oldest went out hunting them. Last night he called in, but today we''ve heard nothing. We''re worried, but we can''t leave the herd. We have enough savings to hire a hunter for a rescue mission. Here are the coordinates from his tracking beacon. Please help, and quickly.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 38, 'm10o', 'Shaak-wrangler on the Great Grass Plains'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 39, 'm10s', 'Thanks for taking care of the predators. My son got swept over a waterfall and lost his tracking beacon, but he''s back home now, injured but safe. Here''s your fee.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 40, 'm10t', 'Need Help Finding Our Son'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 41, 'm11d', 'For generations my family''s cove of trained twirrls, the famed Highscouter bloodline, has provided breeding stock to Theed Palace. The key to the Highscouter cove''s reputation for health and vigor has been our willingness to train the falconoids strenuously over open country. For this reason, predators are a constant menace, and never more than this season. I always have to contract with local hunters to keep the predator population down in our current training fields. Are you available?'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 42, 'm11o', 'Highscouter Twirrl Cove'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 43, 'm11s', 'We''ve already noted the welcome drop in predation. Highscouter Cove thanks you. Look in with us next season for more work.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 44, 'm11t', 'Predator Culling in Twirrl Training Fields'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 45, 'm12d', 'While on sabbatical at the Otoh Gunga Zoological Research Facility, I have observed an unusual, previously unreported behavior in the common ikopi, a swamp herbivore with remarkably long legs and a hollow prehensile tongue. It appears that during mating season, some male ikopi actively seek confrontation with predators for purposes of display and territorial defense. My colleagues are justly skeptical, for all my recording equipment has rotted in this infernal humidity. I can document the behavior indirectly by securing a predator that has wounds from the distinctive ikopi horns. I have located a wounded animal and wish you to kill it, leaving the horn wounds intact for reference purposes.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 46, 'm12o', 'Dr. Henro Torrth, Theed University Bio Department'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 47, 'm12s', 'I shall make arrangements to secure the corpse immediately. Decomposition sets in so quickly in this climate. You may take what you will from the prey.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 48, 'm12t', 'Ikopi-Wounded Predator Needed'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 49, 'm13d', 'Hello! Out near my vacation land, where my family hopes to build a home soon, we''re starting to see young male gualamas. The patriarch of a herd drives off the other males when they reach breeding age. They''re beautiful to see, bounding up hills with tails raised like banners. But they do attract predators. That has spooked the construction firm we''ve hired -- seems the predators attack construction droids, or so we''re told. Sounds to me like a ploy for the construction company to extort insurance funds from us, but it''s cheaper for me to demonstrate that the predators are no problem. If you can go out and kill a few, I''ll pay a reasonable fee.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 50, 'm13o', 'Naboo Family Planning to Relocate'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 51, 'm13s', 'Thanks much for improving my land''s safety. I''ll notify the construction company that no "insurance" is required.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 52, 'm13t', 'Gualama Herds Attracting Predators'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 53, 'm14d', 'I am the associate proprietor of Naboo''s third-oldest guarlara stable. Though we do not provide the royal steeds of Naboo that are revered worldwide, our Kirkhorn Assured Bloodlines are particularly prized for their underfur. It has been woven into Theed''s most famous tapestries. Unfortunately, our mighty mounts are prone to stress-shedding, especially when chased by predators. Seldom do these hunters overmaster our vibrant animals, but the exertion of the chase mars the underfur''s quality. To prevent further deterioration, Kirkhorn wishes to hire you to dispose of the animals located to date. Please respond, and we shall transmit coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 54, 'm14o', 'Kirkhorn Guarlara Stable'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 55, 'm14s', 'Perhaps it may seem frivolous to protect guarlara underfur, but this is an important revenue source for our stable. Thank you for your help.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 56, 'm14t', 'Protect Naboo''s Kirkhorn Guarlaras'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 57, 'm15d', 'During my recent open-air concert, staged out on the Grass Plains as part of Milady Aaltok''s 90th-birthday celebration, a pack of creatures hampered the jovial mood by attacking the guests'' prize guarlara mounts. Now some guests are making litigious noises, on the flimsy pretext that my music angered and provoked the predators. What nonsense. Still, counsel advises Milady to show a good-faith effort to reduce future predator problems. Ergo, the Aaltok household is hiring you to defeat and dispatch the creatures located at these coordinates. Really, this is all most tiresome.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 58, 'm15o', 'Nath Matua Nurtry, Aaltok Household Composer'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 59, 'm15s', 'Very well, I shall pay you. I may require your testimony if this senseless lawsuit ever becomes more than mere persiflage.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 60, 'm15t', 'Hunt to Prevent Groundless Lawsuit'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 61, 'm16d', 'The Emperor has proposed a new Hall of Galactic Wildlife on his throneworld, Coruscant. Animals from across the galaxy are to be stuffed and mounted for display in its silent chambers. Without questioning the Emperor''s motives or the wisdom of his project, architects of Naboo would assert that wildlife is best displayed alive, in a zoological simulation of their native environments. To dramatize our point, we shall present to the project''s advisory board a display, showing live creatures side by side with sterile, stuffed examples. We therefore commission you to terminate the specimen or specimens located at these coordinates, for later removal and processing by this office.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 62, 'm16o', 'Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 63, 'm16s', 'Though the Office of the Chief Architect tenders the agreed payment, our plans have changed. You may take what you wish from the prey.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 64, 'm16t', 'Naboo Architect Requires Animal Specimens'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 65, 'm17d', 'I fear that I unwisely scolded my little pet voorpak, Blotti, when he made an accident on my third-best embroidered gown. Blotti, his fierce heart rebelling, ran away. His tracking collar shows he''s wandered into some dangerous territory, and I''m afraid to go after him. Can some noble adventurer rescue my dear sweet pet?'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 66, 'm17o', 'Lady Prua Nala Bitterbon of Theed'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 67, 'm17s', 'Oh, Blotti! Some giant beast has eaten my poor, headstrong little pet. Go away, leave me in my sorrow!'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 68, 'm17t', 'Help Rescue a Beloved Pet'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 69, 'm18d', 'A bioengineering program at Theed University researches new uses for the chemicals produced by native wildlife. This initiative has already led to new medicines and even improved building materials. To this end, students in the bioengineering program require recently killed specimens. Predators represent a difficult target for mere university researchers, and so they have requested me to contract with hunters to destroy the animals. Please respond to obtain coordinates of likely specimens.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 70, 'm18o', 'Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 71, 'm18s', 'I shall send a recovery team to preserve the animals for study. You may take what you wish from them first. Thank you for aiding the cause of science.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 72, 'm18t', 'Theed University Bioengineers Need Specimens'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 73, 'm19d', 'Mesa not custom to dealen wit outlaunders, but my been sent by De Bosses to taken care of a maxibig problem. De zoo at Otoh Gunga had orderen some bigge animale for showen at de Festival of Bawoonkas. De trouble came when de ship carryin desan animale crashed. Now wesa got desan animale all over. De Bosses tellen my only to bring back dosan animale dat survived de crash. Mesa tinken my can pay yousa outlaunders to "taken care" of desan survivor animale, so wesa not haven any survivors at all. Dat way my will not need to transporten dosan stinkowiffs back to Otoh Gunga. My will payen extra if yousa keepen yousa mouth shut about dis. Tis a bombad deal for both of ussen, eh?'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 74, 'm19o', 'Torba Keels of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 75, 'm19s', 'De Bosses beesa sad dat no animale survived de crash. My not minden so much. Yousa skill is hot, boyo. Taken dis moola for yousa help.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 76, 'm19t', 'Wesa Got a Maxibig Problem'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 77, 'm20d', 'I appreciate the natural beauty of Naboo as much as anyone else. I love the smell of flowering hsuberries and the glint of morning light through a tentacle fern. There''s nothing more lovely than a sunset glittering with sapphire peko-pekos. But I draw the line when sapient beings are endangered wildlife. Recently a Twi''lek child was assaulted by some rampaging animal, and one of her little tentacles was badly mauled. In response to this outrage, I am hiring hunters to remove animals from any region identified as dangerous. If you agree that the safety of our beautiful planet must be preserved from encroaching wildlife, and if you are capable of killing deadly animals, please contact me. I will send you coordinates from my list. Together we can make Naboo safe again.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 78, 'm20o', 'Taneb Magnex of Theed'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 79, 'm20s', 'Splendidly done. That''s one more area the children of Naboo may wander in peace. I will certainly have more work for you in the future.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 80, 'm20t', 'Remove Dangerous Animals From Beautiful Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 81, 'm21d', 'Bubble spore is a rare and delightful plant from the Lianorm Swamp. Its bubble-like spores float on the breeze and catch the light most splendidly. Recent climatological extremes have carried the spores over great distances. We believe that the plant may be spreading beyond the swamp. Unfortunately, certain animals have taken to eating the spores before they can alight and sprout. Because we would like to encourage the spread of this marvelous flora, we require the service of hunters to eliminate the animals from target expansion zones. By slaughtering these filthy beasts, you will help us to spread the enchanting bubble spore plant to all corners of Naboo.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 82, 'm21o', 'Botanical Consortium of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 83, 'm21s', 'Marvelous! Those worm-ridden beasts won''t interfere with the spread of bubble spores again. At this rate, in a year all of Naboo will be covered with bubbles! Can you imagine?'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 84, 'm21t', 'Assist Spread of Naboo Bubble Spores'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 85, 'm22d', 'I''m attempting to build a flora farm as a surprise for my wife. I''m having a deuce of a time because the site is away from civilization, in accordance with my wife''s love of the wilderness, and the creatures who inhabit the area are less than accomodating about our intrusion. Consequently I find myself in need of contractors to clear off these distinctly un-neighborly fauna. I''m working on an aggressive time schedule. Get the job done quickly and thoroughly, and you will make my wife very happy indeed.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 86, 'm22o', 'Lord Jallandra of Theed'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 87, 'm22s', 'Are you certain the animals are gone? I don''t wish to place my wife in any danger, you know. If you''re positive the job is done, then I shall tender your payment. And take also my heartfelt thanks for making my wife happy.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 88, 'm22t', 'Contractors To Eliminate Wild Naboo Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 89, 'm23d', 'I pilot an old H-type chrome yacht, which I rent to high-paying customers. I also sell my services as a courier, which has prompted me to post this message. The other day I had a near-miss with an Imperial shuttle cutting across the designated sky lanes. The shear damaged my yacht''s wings and forced me to jettison some cargo. Now I need to retrieve it. I buzzed the area and found some nasty-looking animals on my scanners. I need someone handy with a blaster to pick off these creatures so I can track down my jettisoned cargo. The recipients are getting impatient, so haste is required.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 90, 'm23o', 'Captain Gwella Incarta'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 91, 'm23s', 'Handily done. Now I can retrieve my jettisoned cargo. If I hurry, I can just about salvage my reputation as a courier.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 92, 'm23t', 'Clear Out Nasty-Looking Naboo Wildlife'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 93, 'm24d', 'The authorities don''t approve of us, but that doesn''t deter the swoop enthusiasts of Naboo. This beautiful planet virtually begs for the open-air joys of swoop ranging. Of course the wildlife is not accustomed to anything more powerful than Imperial speeder bikes. This can cause a lot of trouble. Our engines and exhausts rile the animals into a dangerous frenzy. We''ve lost more than a few good swoopers by slamming into a fambaa or a herd of shaaks. To alleviate this problem, we''ve taken up a collection to hire professionals to remove the more intrusive wildlife that clogs up our swoop lanes. If you can do this job, please contact us for the coordinates of trouble spots.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 94, 'm24o', 'United Swoop Enthusiasts of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 95, 'm24s', 'At last we can ride the swoop lanes without dodging hrumphs and tusk-cats. We''re also investigating the possibility of clearing away vegetation from prime areas. After all, swoopers have as much right as anybody to enjoy the natural beauty of Naboo.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 96, 'm24t', 'Kill Wild Animals Clogging Swoop Lanes'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 97, 'm25d', 'The trouble with a planet like Naboo is, the wildlife is so prolific that there''s no glamor in hunting it. I make my living taking rich Theedsiders into the wilderness to hunt large, dangerous animals. But my skills seem extraneous when the animals simply wander past base camp, waiting to be shot. So I''ve struck upon a plan to rectify this issue. I want to hire hunters to visit my preferred hunting grounds and weed out prolific target species. That way I can hunt down the survivors, and my clients will feel as if they''re getting their money''s worth. So if you''re good with a blaster and want to have some fun in the wilderness, I''ll send you coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 98, 'm25o', 'Gerrio Coronis of Theedside Safaris'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 99, 'm25s', 'Nice work. I''ll take some rich Theedsiders out there tomorrow. You did leave me one or two animals to hunt, right?'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 100, 'm25t', 'Thin Out Wildlife in Hunting Grounds'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 101, 'm26d', 'I''ve got my droids busy on some preliminary work to turn a natural spring pool into an irrigation source. My belief is that the spring''s source might actually be the planet core. Unfortunately my J9 droid reports that animals from the surrounding area have been attracted by the activity. These creatures are either very large or in great numbers, as their droppings have begun to contaminate the pool and clog up the new filters. I would like to hire one or more experienced hunters to blast these animals to dust so that my project can get back on schedule. Pay will be commensurate with the difficulty of the job.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 102, 'm26o', 'Madger Galleas of Theed'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 103, 'm26s', 'My J9 droid says the filters are clearing up already. Thanks for a job well done. Here are your credits.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 104, 'm26t', 'Blast Animals Fouling Naboo''s Water'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 105, 'm27d', 'Desan outlaunders don''t haven much sense sometime. My have taken una Trandoshan warrior into da wilderness for hunten de bigge Naboo animale. Hesa needen to impress some lady Trandoshan for una marriagen ceremony, if mesa understanden correctly. Den desan animale showed up and hesa hiden like a skeered tooke. Hesa say hesa not comen out of hiden till mesa hire someone to getten rid of desan animale. Hesa payen my fee, so my figure my may as well do what hesa want. You gotten de blaster, you wanten some credits, you contact my pretty soon. My not certain how long hesa going to last out dere in de wilderness.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 106, 'm27o', 'Torba Keels of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 107, 'm27s', 'Yousa should have seen dat Trandoshan runnen away as soon as yousa started shooten up de animale! My wish my had brought una hovercam for taken dat as a hologram. Okieday, heresa yousen moola for da job.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 108, 'm27t', 'Una Outlaunder is Needen Help'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 109, 'm28d', 'We are incensed at the behavior of the Imperial Environmental Preservation & Refocusing Authority! To accomodate various Imperial sites on the planet''s surface, the IEPRA has interfered with the rich ecosystem of Naboo. The natural balance of predator and prey has been disrupted. We must restore this balance. We have identified several habitats in which both predatory and prey species must be culled in order to realign the populations. Hunters who appreciate the natural balance are encouraged to participate in this program. We must save Naboo before the Empire destroys it!'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 110, 'm28o', 'The Royal Naturalist Society of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 111, 'm28s', 'But how wonderful! We knew we could count on you. The delicate balance of Naboo''s wildlife will soon be restored.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 112, 'm28t', 'Empire Interferes With Naboo''s Ecosystem'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 113, 'm29d', 'The IEPRA conducts routine missions to expunge dangerous animals from any area where Imperial agents are scheduled to establish service posts. Lately we have experienced some problems. The larger creatures of Naboo have somehow managed to encroach upon our temporary sites. We have consulted the Royal Naturalist Society of Naboo, but they offered no insight as to why our wildlife eradication protocol is failing. As we continue to research this problem, we require hunters to manually clear these areas again so that our agents may conduct their business in peace. Interested parties may contact us at their convenience.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 114, 'm29o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 115, 'm29s', 'Well done. We shall note the quality of your work in our files. We hope to determine soon why our initial efforts at wildlife eradication have failed.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 116, 'm29t', 'Eradicate Dangerous Naboo Wildlife'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 117, 'm30d', 'In the name of galactic security, Imperial agents routinely establish temporary survey sites in the wilds of Naboo. Before each site is constructed, the IEPRA expunges any dangerous and/or nuisance animals from the area. We have found it expedient to hire private contractors for this work. If you are an experienced hunter and wish to become involved in this program, notify us at your earliest convenience. We will send coordinates of a target locale from which to remove the wildlife.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 118, 'm30o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 119, 'm30s', 'Well done. Your actions have ensured the safety of many Imperial agents. You are on your way to establishing a good record with us.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 120, 'm30t', 'Eradicate Hazardous Naboo Wildlife'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 121, 'm31d', 'The Imperial Environmental Preservation & Refocusing Authority persists in its destabilization of Naboo''s splendid ecosystem! After they devastated many of our precious natural populations, we were forced to cull others to preserve the natural balance of predator and prey. Now they have hired despicable murderers to kill more animals and further disrupt the ecosystem. We have no choice but to respond again. We require the services of noble outdoorsmen willing to euthanize the poor, starving animal survivors of the Empire''s heartless campaign. Contact us for the coordinates of these killing grounds, and we shall pay you for your merciful actions.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 122, 'm31o', 'The Royal Naturalist Society of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 123, 'm31s', 'But how wonderful! Your ruthless killling was an act of pure mercy. Shame on the Empire for forcing us into these desperate measures!'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 124, 'm31t', 'Correct Empire''s Interference With Beauty'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 125, 'm32d', 'De wild animale of Naboo been suffering at de hands of some stinkowiff outlaunders. My been catchen desen illegal animale traders allendover half de planet. Tis una shame dat desen narglatches just letten loose de animale anywhere dey getten caught, so dey can getten away from de law. Tis una shame because my no haven de resources to collect dese misplaced animale and taken dem back to where dey belong. All my can do is to payen someone to taken a weapon to desen animale and putten dem out of dere misery. Mesa hiren every persona dat can get de job done. My will transmitten de coordinatees to yousa and payen de credits when yousa finish de work.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 126, 'm32o', 'Sergeant Degoolsby of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 127, 'm32s', 'Tis a shame dat desen illegal animale traders forced ussen to dese sad measures. Taken desen credits for yousa good work.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 128, 'm32t', 'Rounden up de Animale and Killen Dem'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 129, 'm33d', 'If you spend a lot of time offworld, you may not know about the strange weather we''ve been experiencing. Stellar flares are responsible for a moisture inversion that has brought rains to dry areas and reduced water levels in the lowlands. This climatological chaos has resulted in overabundant wildlife where it is normally under control. While we are applying for the intervention of Imperial weather shields to block the stellar flares, we are employing more direct methods to regain control of the wildlife populations. We are contracting hunters to thin out groups of large, prolific and/or dangerous animals in certain areas. If you qualify to participate in this reclamation campaign, contact planetary authorities. We can stave off disaster, but only if we act promptly.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 130, 'm33o', 'Naboo Environmental Council'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 131, 'm33s', 'That''s one more region where the wildlife will not become a nuisance. Thanks for your good work and professional demeanor.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 132, 'm33t', 'Flares Disrupt Naboo Animal Populations'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 133, 'm34d', 'A wealthy family of Togruta merchants have decided to make Naboo their next home. I am surveying the landscape for a location suitable for a modular villa. Unfortunately, their homeworld is rife with predators, and their preferred surroundings are also populated by large and potentially dangerous animals. Because I don''t want my clients to be eaten or trampled while I''m presenting their choices, I need to hire someone to temporarily rid these areas of nuisance wildlife. I''ll send the coordinates to anyone who can get the job done neatly.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 134, 'm34o', 'Chanja Kee of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 135, 'm34s', 'Great work. The wealthy Togrutas will reach Naboo in a few days. I''m glad to be able to show them around safely.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 136, 'm34t', 'Arrival on Naboo of Togruta Clients'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 137, 'm35d', 'Some local animals have ingested contaminated runoff from the Emperor''s Retreat. We believe that these creatures now pose a significant risk to the planetary ecosystem. They have dispersed to various places on the planet. We are contracting hunters to dispose of these animals as quickly as possible. Our satellite droids have isolated several potential locations where these contaminated animals might be found. These coordinates will be made available to qualified applicants.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 138, 'm35o', 'Imperial Environmental Preservation & Refocusing Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 139, 'm35s', 'Excellent. Our scanners indicate a significant amount of contamination in your body. This confirms your successful engagement with the target animals. As we do not know what effect this contamination might have on your particular subspecies, we suggest that you make arrangements for a funeral or other death rite in the event that you do not survive.'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 140, 'm35t', 'Contamination In Naboo Ecosystem'),
('string/en/mission/mission_destroy_neutral_medium_creature_naboo.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 1, 'm1d', 'How many times do we have to exterminate these pests? Hiring professional hunters is getting expensive. Could you go in and clear out that creature lair for us, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 3, 'm1s', 'Looks like you might have a career in extermination, friend. Thanks for your efforts.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 4, 'm1t', 'Clear Out Tenacious Pests'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 5, 'm2d', 'I''m lodging a group of Bith musicians in my villa, but they''re skittish about some of the local wildlife. I''d be willing to pay if you could remove some of the more dangerous creatures from the area and put these Bith at ease.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 7, 'm2s', 'Splendid! Now my Bith guests can relax and practice their music. I do enjoy their fizz lilting through my villa on a lazy evening.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 8, 'm2t', 'Reassure Skittish Musicians'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 9, 'm3d', 'Some darn predator ate my good luck kima! I think those beasts have a lair near here. If you can find them and blast them to atoms, I''d certainly reward you.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 11, 'm3s', 'Thanks, friend. I''ll sure miss that kima. I bet this breaks my incredible sabacc winning streak. '),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 12, 'm3t', 'Recover Good Luck Charm'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 13, 'm4d', 'My precious little kittle -- she liked to be called Woopywoopums -- was snatched by a horrible predator while slithering playfully in my yard. Please avenge my angel for me.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 15, 'm4s', 'You are most gallant, citizen. What is your name again? I want to name my new kittle in your honor.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 16, 'm4t', 'Avenge Woopywoopums'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 17, 'm5d', 'I''ve been contracted to do some construction near here. Help me out by cleaning up the nest at these coordinates, and I''ll cut you in.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 19, 'm5s', 'Nice work. I''ve never seen the need for a professional exterminator before. Those guys get the big money.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 20, 'm5t', 'Help Clear Land'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 21, 'm6d', 'A condemned shelter near here is nothing but a breeding ground for bloodsucking parasites. I bet a couple of well-placed blaster shots would take care of the problem. Can you help, friend?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 23, 'm6s', 'Well done, citizen. This ought to make the wet season much more pleasant. Enjoy your reward!'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 24, 'm6t', 'Prepare For Wet Season'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 25, 'm7d', 'There''s a den of vermin out there that is gonna kill some youngster some day. Local kids love playing in that area. Be a friend and demolish that lair for us, would you?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 27, 'm7s', 'I''ll be able to sleep peacefully at night now. Thank you kindly.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 28, 'm7t', 'Keep Kids Safe'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 29, 'm8d', 'The last thing I want to hear when I settle down to bed are the mating calls of blasted vermin! Please silence those love-sick beasts and help me get some peace and quiet.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 31, 'm8s', 'My gratitude knows no bounds, citizen. Well, actually it does, as your deposited payment will prove. But I''m still quite pleased.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 32, 'm8t', 'Wipe Out Lovesick Beasts'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 33, 'm9d', 'My poor little durni, it wandered away and got lost. The tiny helpless thing can''t see, you know. A friend saw a wild predator pounce on my darling and devour him. Oh horror! Please avenge my poor little Blinky.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 35, 'm9s', 'This sets my mind at ease, citizen. Many thanks. I hope I can mourn Blinky and move on.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 36, 'm9t', 'Avenge Little Blinky'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 37, 'm10d', 'I just knew it was a bad idea to come to this planet! There''s some kind of filthy creature lurking on the path to my new home. I don''t suppose you''d be able to kill it for me, would you?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 39, 'm10s', 'Thank you ever so much! I suppose every planet will seem dangerous after leaving my poor, beautiful Alderaan.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 40, 'm10t', 'Make Planet Safer'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 41, 'm11d', 'I''m looking to run some power conduits across an area not far from here, but there''s a couple of pesky animals getting in the way of my spooling droids. Do you suppose you might take that weapon of yours and exterminate these pests?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 43, 'm11s', 'Thanks, buddy. You earned the credits. It''s getting so you can''t earn a decent living without a blaster these days.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 44, 'm11t', 'Get Rid of Pesky Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 45, 'm12d', 'I was testing my new electrobinoculars when I spotted a few toothy-looking beasts roaming around my land. If you want to earn a few credits, why don''t you haul your weapon out there and take out those nasty creatures?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 47, 'm12s', 'You don''t seem to be bad with that weapon. The credits I promised will be promptly deposited.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 48, 'm12t', 'Toothy Beasts Are Bad'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 49, 'm13d', 'I''ve been tracking some genetically altered predators that were stolen from an Imperial research facility. Some apparently ended up here. If I could get your help in disposing of them, I''d make it worth your while.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 51, 'm13s', 'Hmm, those don''t sound like the beasts I was tracking, but thanks for getting rid of dangerous predators anyway. A little something has been deposited in your account for your trouble.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 52, 'm13t', 'Genetically Altered Beasts Are Scary'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 53, 'm14d', 'My goal of breeding exotic pets didn''t go as planned. I''ve heard some of my "failed experiments" are now terrorizing the locals. Think you could take care of this problem for me?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 55, 'm14s', 'Thanks. Your pay has been deposited. I''d sure appreciate it if you didn''t mention this to anyone, okay?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 56, 'm14t', 'Clean Up Failed Eexperiments'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 57, 'm15d', 'My friends and I want to hold some speeder races outside of town, but there''s some sort of creature lair out there that''s holding us up. If you wipe it out, I''ll pay you for your time.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 59, 'm15s', 'Thanks! You''re a pal! I deposited your pay. Don''t forget to come back in a few months and check the races out.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 60, 'm15t', 'Speeder Races Are Fun'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 61, 'm16d', 'I lost something of great sentimental value in the wilderness and I''m determined to get it back. I''ve isolated the area where I think this treasure may lie, but there''s a den of predators keeping me from performing a thorough search. Think you can get rid of it for me?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 63, 'm16s', 'Thanks, friend. I''ve compensated you for your trouble. Uh, you didn''t happen to dig around, did you? Didn''t find any precious stones?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 64, 'm16t', 'Recover Family Heirloom'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 65, 'm17d', 'Some kids have disappeared in this area over the last few weeks. Some folk think it''s the work of wild predators. I''ll pay you to check these coordinates out and drive away any monsters you encounter.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 67, 'm17s', 'Good work, citizen. The children will compose a song in your honor. Oh, and I''ve deposited the pay I promised.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 68, 'm17t', 'Children Possibly Eaten'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 69, 'm18d', 'My dying grandfather has one last wish -- to eat the flesh of the creatures that killed his beloved wife. I''ve tracked down a lair of the beasts and need you to kill some for me. Think you could do that?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 71, 'm18s', 'Excellent! I''ll send my droids out to collect the carcasses. Don''t worry if you didn''t leave much meat -- my grandfather has hardly any teeth left.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 72, 'm18t', 'A Last Supper'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 73, 'm19d', 'I perform tests of the groundwater, but my meters seem to attract all manner of vermin. It''s the vibrations, I think. Could you please make sure there aren''t any bothersome beasts hanging around my workstations?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 75, 'm19s', 'Thank you. It''s always nice to know I can go to work in relative safety. I''ve deposited something for you in your account.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 76, 'm19t', 'Assist Public Servant'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 77, 'm20d', 'My mother is sick and loves a certain flower that grows near here. I''d pick some for her, but there''s some sort of creature lair near there, and I''m afraid those beasts might hurt me. Could you chase them away for me?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 79, 'm20s', 'Thank you so much. I''m sure the flowers will help my mother get better. Enjoy the reward for your services.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 80, 'm20t', 'Help Sick Mother'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 81, 'm21d', 'My little daughter''s beloved bearded jax was killed by some sort of wild beast recently. The darling just won''t be consoled until those horrible pests are disposed of. Do you think you could do this for me?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 83, 'm21s', 'Thanks, friend. I hope what I deposited covers your inconvenience. I''m sure you understand just how important it is to keep our little angels happy.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 84, 'm21t', 'Console Little Angel'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 85, 'm22d', 'Ever since my HyperGym broke down, I''ve taken to jogging outside the city. But the presence of wild beasts has recently rendered my favorite route useless. Could you get rid of these pests for me?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 87, 'm22s', 'Thanks, friend. I gave you something to cover the expenses you incurred while blasting those creatures. Now I''ll be able to stay in shape.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 88, 'm22t', 'A Strike For Fitness'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 89, 'm23d', 'The Imperial Zoological Agency claimed to have cleared these areas of dangerous beasts. I beg to differ. We''ve had a few attacks on children in the last couple of days. Could you get rid of whatever is threatening our kids?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 91, 'm23s', 'A thousand thanks, citizen. Perhaps you should seek a job with the Imperial Zoological Agency. Seems like you could show them how these things should be done.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 92, 'm23t', 'Clean Up Empire''s Mess'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 93, 'm24d', 'I''ve heard a lot of complaints about a crazy old wizard in the wilds who surrounds himself with ravenous beasts. I sent a range droid to find out where the old man lives. Now I want you to exterminate his animals. I can pay you, don''t worry about that.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 95, 'm24s', 'Well done. Those animals won''t bother anyone now. The old wizard probably ran away when he saw you coming. I hope that teaches him a lesson.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 96, 'm24t', 'A Crazy Wizard''s Menagerie'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 97, 'm25d', 'Something''s been killing the young from my herd of gualamas. Now I have to keep my livestock indoors. I need a hunter to take care of this predator before I lose any more profits. If you can do the job, I''d love to hire you today.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 99, 'm25s', 'I''m glad nothing will be feeding on my gualamas. Thanks to you, that is.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 100, 'm25t', 'Save Gualama Herd'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 101, 'm26d', 'They looked so cute when they were little, but my pets grew too big to keep. Now they''ve been feral for a year. The planetary authorities have warned me that they''ve become dangerous. I''ve got to get rid of them somehow. Would you be able to find my old pets and blast them into pieces?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 102, 'm26o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 103, 'm26s', 'I still miss those poor little devils. Perhaps now they''re in a better place. Thank you for the help.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 104, 'm26t', 'Good Pets Gone Bad'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 105, 'm27d', 'I''m not obsessed with hokey religions, but I think some land I just bought is strong with the dark side of the Force. At least it''s infested with some very unpleasant animals. You look tough enough to remove them from my property. Care to earn a few credits today?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 106, 'm27o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 107, 'm27s', 'You have much skill and courage. The Force must be strong with you. Enjoy your reward.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 108, 'm27t', 'Face the Dark Side'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 109, 'm28d', 'Cloning tests are fun, but I made the mistake of turning loose several test subjects. Not that these cloned animals can''t defend themselves in the wild. Quite the opposite -- they have mauled several travellers through the area. How would like to help me clean up this mess by blasting these animals into atoms?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 110, 'm28o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 111, 'm28s', 'Thanks. Of course, the thing about clones is that it''s hard to stop making them after just ten or twenty. I may need your services again. Soon.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 112, 'm28t', 'Stop the Clones'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 113, 'm29d', 'Remember the Techno Union? Of course you do. I think there might be an old outpost of theirs not far from here. I want to investigate further, but the area is home to some distinctly hostile creatures. I''d love to hire you to remove them. Then I can get on with my search for the outpost.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 114, 'm29o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 115, 'm29s', 'Capital job! Now I can keep searching for that old Techno Union outpost. Who knows what they might have left behind?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 116, 'm29t', 'Techno Union Treasure'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 117, 'm30d', 'I''ve found an excellent spot to set up an electro-telescope. I like to watch the big ships docking in orbit. But the last time I set up my rig, I was chased off by a couple of ugly, unpleasant creatures. I''ll pay good money if you could get rid of those beasts for me.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 118, 'm30o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 119, 'm30s', 'You''ve done me a great favor. Your payment has been deposited. Now I can monitor the activities of Imperial warships to report to the Alli-- um, I mean, I can watch the big ships docking in orbit.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 120, 'm30t', 'Help Amateur Astronomer'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 121, 'm31d', 'I imported some ghhhks from Clak''dor VII. I heard their skin makes a healing salve. Well, it didn''t do anything for me, and then the ghhhks got loose. Now they''re breeding, and the scent has attracted a pack of hungry predators. I''d like you to destroy the predators before anything really bad happens.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 122, 'm31o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 123, 'm31s', 'Thanks. I was afraid my neighbors were about to sue me for biological infestation. I hope the predators ate all the ghhhks before you killed them.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 124, 'm31t', 'Contain Biological Infestation'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 125, 'm32d', 'I''ve commissioned a holosculptor to model several local beasts for a new dejarik board I''ll be selling. She needs specimens, so I''ve located some at these coordinates. Please dispatch everything in this lair, but try to leave the bodies intact.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 126, 'm32o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 127, 'm32s', 'Never mind. The holosculptor found adequate models on the HoloNet. Thanks anyway for your work, and I have deposited your fee.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 128, 'm32t', 'Improve the Game of Dejarik'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 129, 'm33d', 'Some offworld things escaped from the recent Livestock Exhibition, and they''ve been terrorizing the countryside ever since. We''ve collected some money and found the likeliest spot where they lair. Can you go in and take out the whole pack, quickly?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 130, 'm33o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 131, 'm33s', 'Did the creatures seem like offworld beasts to you? They may still be on the loose. Well, you did the job we asked for, so your money''s been deposited.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 132, 'm33t', 'Hunt Offworld Beasts'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 133, 'm34d', 'You smell that? That stinking dust on the wind? It''s egg seeds, spewed by the shadow barnacles that infest the buildings around here. The egg seeds in turn attract beasts from hither and yon. There''s a new lair nearby. Please go and destroy it, okay?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 134, 'm34o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 135, 'm34s', 'That was some stink, eh? I''d better find a fungicide or something. Everything go okay? Your money should be in your account. '),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 136, 'm34t', 'Stop Stinky Beasts'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 137, 'm35d', 'I''m convinced I know the origin of the vicious pack animals now attacking children in this neighborhood. Some local Imperial bigwig imported them for his stupid menagerie, and they got loose! The police won''t stop the beasts yet, because someone high up likes to make the Empire look bad. Can you destroy this menace?'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 138, 'm35o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 139, 'm35s', 'What a relief! All the parents in this neighborhood thank you. You''ve done us a great service and earned this reward.'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 140, 'm35t', 'Stomp Rogue Zoo Animals'),
('string/en/mission/mission_destroy_neutral_medium_creature_non_persistent_from_npc.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 1, 'm10d', 'In celebration of the founding of the first colony on Tatooine, you are invited to join in the ritual Arnthout Hunt. This event is named for the famous pioneer Melnea Arnthout who led the colonists to survive incredible obstacles and who founded the capital city of Bestine. For this event, we have chosen a new target to represent the early prey (which was wiped out long ago by the original settlers). Have fun and happy hunting!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 2, 'm10o', 'Bestine Historic Society'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 3, 'm10s', 'Congratulations on your successful hunt! The Bestine Historic Society is pleased to reward you for your tremendous efforts during this seasonal celebration!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 4, 'm10t', 'Arnthout Hunt'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 5, 'm11d', 'I hope you''re tougher than the last "adventurer" I hired... If you''re in need of a few credits and you don''t mind a hike, I could use a hired hand. As you might know, Anchorhead''s main attraction is the Tosche power station, which I manage. We provide power converters, vehicle repairs, and equipment recharging for all the local moisture farmers. We also supply energy to other Tatooine cities through dozens of sturdy underground cables. Lately, though, some pretty nasty creatures have been digging up the power cables, disrupting service to our wealthier customers. I can tell you that Prefect Talmont was less-than-happy when Bestine blacked out last week, right during his favorite holo-drama... So, I need you to kill the creatures that have been tearing up our power cables; you''ll need to wipe out all of the beasts by destroying their lair if we ever want things to get back to normal around here. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 6, 'm11o', 'Fixer'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 7, 'm11s', 'You came through for me, adventurer. I guess this means I have to pay you. The credits are in your account. Thanks for keeping me out of Prefect Talmont''s cross-hairs.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 8, 'm11t', 'Anchorhead Defender'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 9, 'm12d', 'The Imperial Transportation Commission is pleased to announce the creation of a new transportation system utilizing a single repulsorlift rail for high-speed travel over treacherous terrain. Tatooine has been identified as a prime candidate for introduction of this new system. However, in order to facilitate the construction of this "monorail" system, the Imperial Transportation Commission must eliminate abundant wildlife in the area surrounding the proposed site. Please aid in this effort by proceeding to the identified lair, hive, nest, or den and destroying it.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 10, 'm12o', 'Imperial Transportation Commission'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 11, 'm12s', 'The Imperial Transportation Commission has determined that Tatooine is now a prime candidate for introduction of our experimental repulorlift monorail transportation system. The lair, hive, nest, or den that temporarily delayed construction has been eliminated. You will receive a modest reward for your efforts to better life on one of the Emperor''s worlds.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 12, 'm12t', 'Transportation Concern'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 13, 'm13d', 'Congratulations! The Mos Entha City Council, in compliance with Imperial decree, has selected you for a well-respected position as one of Tatooine''s official contract exterminators. You now join a long line of brave and talented vermin control specialists! In order to perform your assigned task and fulfill your obligations to the Mos Entha City Council, please proceed to the identified lair and destroy it. Thank you in advance for your service! (In the event of death, the Mos Entha City Council will notify next of kin; funeral arrangements remain your responsibility). '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 14, 'm13o', 'Mon Entha City Council'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 15, 'm13s', 'The Mon Entha City Council has fulfilled our obligation to the Empire. Thank you for assisting in our efforts to eliminate dangerous, local creatures. Your payment is forthcoming.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 16, 'm13t', 'Contract Exterminator'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 17, 'm14d', 'Tatooine lives and dies by its water supply. And the water supply is provided by the hundreds of moisture vaporators spread across the desert. Recently, however, various creatures have taken to attacking these devices, perhaps in an attempt to steal the small amounts of moisture gathered by the vaporators. The Tatooine Moisture Farm Collective, in cooperation with the Bestine Chamber of Commerce, is offering rewards to anyone willing to help protect the moisture industry. This message contains information about a species known to have attacked moisture vaporators in the past. Proceed to the identified lair and eradicate these creatures in order to end the threat to our water supply.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 18, 'm14o', 'Tatooine Moisture Farm Collective'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 19, 'm14s', 'Our water supply is safe! Thank you for helping to protect the moisture vaporators on our desert world. In recognition of your heroic efforts, the Tatooine Moisture Farm Collective, in cooperation with the Bestine Chamber of Commerce, has transferred a sizable reward to your galactic account'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 20, 'm14t', 'Keep the Water Flowing'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 21, 'm15d', 'My father taught me everything I know about business. One of his favorite adages was "good help is hard to find," and nowhere is that more true than on Tatooine. There just aren''t enough skilled laborers out here. I''ve researched my options: Agrirobots require constant maintenance, Jawas don''t know a pika fruit from a rainbow berry, and all the local kids are just daydreamers who want to be starfighter pilots. Sure, I could hire seasonal workers, but can you really trust someone who just rolls around the Outer Rim looking for odd jobs?\n\nIn order to staff my underground hydroponic gardens, I''ve been forced to recruit from agricultural planets. Each of my employees is hand-picked from well-known farming worlds like Bandomeer, Salliche, and Taanab. Convincing someone to just drop everything and move to a desert planet requires a lot of credits, but keeping them here is even more difficult. About half of my recruits leave after enduring their first sandstorm. And now, my farmers are reporting encounters with dangerous local wildlife. I''ve already had several members of my staff flee the planet, and I can''t afford to lose any more workers. So, I''m hiring you to locate the creatures harassing my employees and wipe them out. My highly-trained farmers will be most grateful for any aid you can provide.\n\nYour Benefactor,\n\nHuff Darklighter'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 22, 'm15o', 'Huff Darklighter'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 23, 'm15s', 'Excellent work, my friend! I''m certain that your efforts on behalf of my workers will solidify their loyalty and increase productivity at all my hydroponic farms. Your reward is a small price to pay to keep my business running smoothly.\n\nYour Grateful Host,\n\nHuff Darklighter '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 24, 'm15t', 'Farmers'' Champion'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 25, 'm16d', 'If you ask me, the Empire is out of control. Seems like every day they have a new set of laws and regulations for us Tatooine locals. The latest ordinance requires that we hire exterminators to help keep dangerous wildlife out of the city streets. None of us are happy about this new law, but I''m not about to give the Empire a reason to build a garrison in my town. We don''t want Wayfar to become another Bestine, do we? Jabba certainly doesn''t, since half of Wayfar is on his payroll.\n\nBut I''m sweating myself dry here trying to figure out how to handle this Imperial decree. Nobody in town is going to volunteer for this job, and I have my hands full just keeping the local cantina from becoming a morgue. So, you''re my only option. One of my scouts has spotted a lair that needs to be destroyed. Take care of it for me and you''ll be paid. Hey, it''s better than cleaning up after banthas in Mos Eisley, right?'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 26, 'm16o', 'Jurist Hassp, Wayfar Keeper of the Peace'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 27, 'm16s', 'Wayfar hasn''t seen a mercenary like you in quite some time, my friend. You''re tougher than most on this planet, and you know how to use your wits in combat. But be careful: Anyone who is too good at killing usually ends up in an Imperial prison or Jabba''s rancor pit. If I were you, I''d use my reward to take a nice long, relaxing trip.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 28, 'm16t', 'Wayfar Exterminator Wanted'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 29, 'm17d', 'The Mos Taike Coalition for Tatooine Recovery lauds the creation of Imperial Indigenous Control Policy #780901, which requires all of Tatooine''s cities and major settlements to take responsibility for improving the quality of life on our homeworld! Specifically, this new decree demands that Tatooine''s bravest citizens help quell a plague of terrible creature attacks by destroying the lairs of dangerous animals. To support this bold initiative, the Mos Taike Coalition for Tatooine Recovery is offering substantial rewards for the destruction of such lairs. Do your part! Help keep Tatooine safe and in the Empire''s good graces! Kill these threatening creatures before they kill us!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 30, 'm17o', 'Mos Taike Coalition for Tatooine Recovery'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 31, 'm17s', 'Thank you for doing your part to help keep Tatooine clean! The planet has never been safer! Your heroic deeds have been rewarded, although we trust that the knowing you''ve protected countless innocent lives is reward enough.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 32, 'm17t', 'Do Your Part!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 33, 'm18d', 'The Tatooine Civilian Defense League has detected yet another alarming rise in the number of dangerous creatures in the habitable areas of the planet. Such animals are making travel extremely unsafe between major cities. In accordance with Imperial Indigenous Control Policy #780901, the Tatooine Civilian Defense League is authorized to pay for the extermination of specified creatures through the destruction of their central lairs or hives. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 34, 'm18o', 'Tatooine Civilian Defense League'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 35, 'm18s', 'Your mission has been completed successfully! The Tatooine Civilian Defense League will transmit payment immediately. Thank you for your service.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 36, 'm18t', 'Additional Creature Culling'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 37, 'm19d', 'On behalf of the many moisture farmers struggling to survive in Tatooine''s harsh desert, the Moisture Farm Collective is offering rewards for the destruction of dangerous local wildlife. Tatooine''s moisture farmers endure savage heat, fierce sandstorms, and occasional Tusken Raider attacks. On top of these dangers, the farmers must contend with malfunctioning droids and temperamental moisture vaporators. But marauding creatures may be the most pervasive problem facing moisture farmers. Such animals need to be killed before more moisture farmers are injured, or worse.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 38, 'm19o', 'Tatooine Moisture Farm Collective '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 39, 'm19s', 'On behalf of many thankful moisture farmers, the Tatooine Moisture Farm Collective is overjoyed to recognize you recent successes in the field. Thank you for destroying the creatures that plague the local farmers. Payment for your services has been transferred to your account.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 40, 'm19t', 'Innocent Victims'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 41, 'm1d', 'My daughter won''t even go outside, she''s so scared of the creepy crawlies around here... I heard from my next-door neighbor that there''s some sort of infestation or something. Now, I don''t really expect the Imperials to actually DO anything about this -- I mean, look how they handle the riff-raff at the cantina, I''ve never seen such incompetence in my life -- but you''d think that when the mental well-being of an innocent little girl is at stake, they''d at least pull out their blasters. Anyway, I decided to take matters into my own hands and offer up a reward, using my own PERSONAL funds. It''s really for the children.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 42, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 43, 'm1s', 'Thank you for making the area safe for our children. My daughter is already playing outside again. I''ve never seen her happier.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 44, 'm1t', 'Protect the Children'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 45, 'm20d', 'My family has lived on the edge of the Dune Sea for generations, and I can tell you that the creatures around here are getting bigger and meaner every year. I think they''ve lost their sense of fear, too. They keep coming closer and closer to my farm. One night soon, they''re going to attack me and my children.\n\nI''m not very brave, but I''m hoping that you are. Brave enough to go kill some dangerous creatures, anyway.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 46, 'm20o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 47, 'm20s', 'I was beginning to worry that my family would never be safe, but it seems that you turned those creatures into bantha fodder. Great work. Moisture farmers don''t have much, but you can''t put a price tag on your family''s safety, so I sold my father''s rifle and used the credits to pay your reward.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 48, 'm20t', 'Help Me...'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 49, 'm21d', 'The Death Seed plague is a horrific disease that is lethal to all known species. The disease is spread by insects called drochs, which are capable of infesting organic material. Since the last Death Seed outbreak seven centuries ago, the droch have been confined to Nam Chorios. However, recent research conducted by the Imperial Department for Epidemic Prevention suggests that many local vermin species on Tatooine may be carrying droch eggs. Should these eggs mature and hatch, the Death Seed Plague could again sweep the galaxy. In order to avoid a staggering loss of sentient life, the Department for Epidemic Prevention is providing fair compensation for the elimination of Tatooine creatures believed to be carrying droch eggs. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 50, 'm21o', 'Imperial Department for Epidemic Prevention '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 51, 'm21s', 'Recent reports have confirmed the presence of droch eggs on the identified Tatooine creatures. However, your successful mission to eliminate these creatures has greatly reduced the number of creatures carrying these eggs, thereby significantly reducing the likelihood of an outbreak of the dreaded Death Seed plague. The Galaxy is in your debt.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 52, 'm21t', 'Tatooine Death Seed Deterrence'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 53, 'm22d', 'Jabba the Hutt has decided to offer up "rewards" for killing supposedly dangerous creatures on Tatooine, and Lady Valarian will not be outdone by that slime-encrusted, chuba-eating worm. Instead, I too will pay for proof that local lairs have been destroyed. If only to keep Jabba from taking all the credit for "cleaning up" Tatooine himself... Don''t disappoint me. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 54, 'm22o', 'Lady Valarian'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 55, 'm22s', 'Nice work, "hero." I hear Jabba''s furious because my own hired guns are killing more dangerous creatures than his slobbering, moronic "adventurers." That dumb, ugly worm is eventually going to learn that I''m not to be crossed...  If you don''t mind dirty credits, there''s a well-deserved reward waiting in your account.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 56, 'm22t', 'Creature Bounty'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 57, 'm23d', 'My daughter has been missing for a week. Her mother still holds out hope, but to be honest, I think we''ve lost her. A couple of hunting parties have gone out, and we found some of her clothing, shredded and bloodstained. At night there are eerie cries carried on the wind--I know how the weather and desert sands can distort sounds around here, so I am not saying that anything supernatural is going on, believe me. But there''s no doubt in my mind that there''s something dangerous out there, and it''s had its taste of blood. If it''s not stopped, it''s bound to kill again. I''m getting on in years, but in my day I would have hunted down the beast and killed it myself. My question is this: is there anyone out there willing to do the same, in memory of my lost little girl?'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 58, 'm23o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 59, 'm23s', 'Thank you for helping to soothe my wife''s grief. Although nothing will replace our daughter, we can take some comfort in the fact that those dangerous creatures will never kill again. My little girl is one with the Force, but she will always be smiling on you, my friend.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 60, 'm23t', 'Father seeks help!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 61, 'm24d', 'Scientific Galactica, the galaxy''s leading scientific journal, maintains a staff of over three hundred researchers and writers in order to supply our readership with the most thorough coverage possible. While most of our employees are trained in self-defense and survival, we''ve recently suffered several disappointing field losses, most notably on the desert world of Tatooine. In order to prevent future deaths, we are searching for contractors willing to eliminate dangerous creatures on Tatooine, where we are currently conducting extensive field research. Information regarding our most recent mission offering is enclosed; proceed to the identified live or lair to help keep our researchers safe. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 62, 'm24o', 'Scientific Galactica'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 63, 'm24s', 'Congratulations! The next issue of Scientific Galactica will feature a detailed account of the eating habits of the reclusive worrt. Our esteemed writers and researchers could not have completed this first-hand observational piece without your aid; by eliminating dangerous creatures near our research site, you allowed our staff to operate in relative safety. A freelancer''s fee has been transferred to your account.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 64, 'm24t', 'Tatooine Scientific Defense'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 65, 'm25d', 'URGENT!\n\nWe have uncovered a new strain of Brainworm Rot Type B...Scans indicate the disease is being incubated in the lairs of various unclean creatures...Disease certain to mutate into Type A variety soon...Wol Cabbashite population threatened with extinction...Please assist by eliminating lair where disease has been detected...\n\nABOUT BRAINWORM ROT TYPES A and B\n(From the Imperial Department for Epidemic Prevention)\n\nBrainworm Rot Type A is an airborne virus that afflicts humanoids and cephalopoids with high levels of dialogen in their bloodstream. It resides in the lungs of oxygen-breathers, and is passed by inhalation. Symptoms include: Nausea, cold sweats, inability to process written instructions, syntax errors in spoken and written communication, and isolated purpling of gills and blowholes. Brainworm Rot Type A is fatal if untreated and has proven especially lethal among Wol Cabbashites.\n\nBrainworm Rot Type B is a less evolved form of Type A. It thrives in cesspools, sewers, waste management facilities, trash compactors, damp caves, and virtually any area with unhygienic conditions. Although Type B is not life-threatening to most species, the disease has been known to rapidly mutate into the much more dangerous Brainworm Rot Type A if left unchecked.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 66, 'm25l', 'The deadly Brainworm Rot Type B is sweeping through lesser lifeforms. Those carrying the disease must be destroyed before it can spread to sentient beings.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 67, 'm25o', 'Wol Cabbashite Ambassador Lurll'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 68, 'm25s', 'NON-URGENT\n\nAgent has eliminated new strain of Brainworm Rot Type B...Disease has been destroyed...Mutation into Brainworm Rot Type B now impossible...Wol Cabbashite population safe...Credits have been allocated to Agent as payment for protecting our species.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 69, 'm25t', 'Tatooine Brainworm Rot Crisis'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 70, 'm26d', 'The Galactic Pest Authority is responsible for monitoring reports of vermin, pests, and nuisance creatures throughout the galaxy. We have conclusive evidence of a dangerous rise in the number of particularly violent vermin on Tatooine. In accordance with Galactic Pest Authority''s mission statement, we are authorizing extermination of these deadly creatures. This transmission includes information about a specific vermin lair on Tatooine; please destroy this lair to cleanse the planet.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 71, 'm26o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 72, 'm26s', 'Tatooine''s dangerous vermin have been eliminated! You have admirably upheld the Galactic Pest Authority''s mission statement by helping to destroy these nuisance creatures.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 73, 'm26t', 'Tatooine Dangerous Vermin Control'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 74, 'm27d', 'The rabid creature is one of the most insidious threats facing Tatooine travelers. Such animals may appear harmless, but they are prone to unpredictable acts of violence. When these creatures descend into madness, they will kill anyone and anything they encounter. Therefore, the Galactic Pest Authority is authorizing you to eliminate those creatures susceptible to this type of behavior. Seek out and destroy the indicated lair to protect your fellow galactic citizens from this terrible danger.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 75, 'm27o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 76, 'm27s', 'The populations of those Tatooine creatures most susceptible to becoming rabid killers have been suitably decreased. You have admirably upheld the Galactic Pest Authority''s mission statement, and we thank you for your efforts on our behalf. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 77, 'm27t', 'Tatooine Rabid Creature Control'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 78, 'm28d', 'That little Moff, Prefect Talmont, thinks I''m his errand boy. He''s ordered me to take my troops out into the desert and wipe out a few creature lairs. Well, I don''t care if he''s the Emperor''s favorite Prefect. I''m not about to waste my time chasing down whatever vermin he hates this week. I''d rather use my weekly stipend to hire you to go kill the creatures for me. Get to work; I don''t want to hear from Talmont again.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 79, 'm28o', 'Lieutenant Harburik'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 80, 'm28s', 'Good work. Maybe now Prefect Talmont will leave me alone, at least for a day or two. If he doesn''t, I swear I''m going to arrange for him to have a little accident the next time he meddles in my business. As for our business, the credits are in your account.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 81, 'm28t', 'Mos Eisley Mercenary'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 82, 'm29d', 'Would-be adventurer,\n\nI am in a quandary. As Jabba the Hutt''s chief accountant, I am surrounded by thieving, murderous scum. Granted, I count many of them as friends, but I do not trust them. To protect my credits (and some of Jabba''s wealth as well), I''ve "relocated" funds to key locations throughout the desert. Unfortunately, one of my newly-buried safeboxes has been compromised. A foul-smelling creature has built its lair near my treasure trove, preventing me from retrieving my funds. I certainly can''t hire any of my "friends" to go destroy this lair, so you are my only option. I encourage you to destroy the lair quickly and efficiently. You will be richly rewarded. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 83, 'm29o', 'Tessek'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 84, 'm29s', 'Most respected adventurer,\n\nMy quandary has been resolved. You have efficiently eliminated the vermin lair blocking access to my private funds. I can now visit the site as necessary to recover my much-needed credits. In order to pay you, however, I have "borrowed" credits from Jabba the Hutt''s own personal account. I trust you will keep our business arrangement confidential. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 85, 'm29t', 'Buried Treasure'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 86, 'm2d', 'My little boy was dragged away by these vermin, and they nibbled on him! Granted, he came back and all it took was some salve to heal those nasty bites, but I''m afraid they''ll do something much worse next time... '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 87, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 88, 'm2s', 'Those creatures that bit my son didn''t stand a chance! I knew that I hired the right adventurer! Thank you for protecting my child. I don''t have much to offer as a reward, but I''ll sing your praises every chance I get!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 89, 'm2t', 'Boy Attacked'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 90, 'm30d', 'There are just some species you can''t trust. Like Jawas and Hutts. Or Shi''ido. Scurvy little shape-shifters, they can look like a Bith one moment and then take the form of an Ithorian the next. How can you trust a being that changes his skin every time you turn around?\n\nI made the mistake of hiring a Shi''ido recently. I thought he was a Gran, and I was in need of a doorman who could keep three eyes on my crowd. Anyway, this alleged Gran robbed me blind and hid out in the desert. My sources tell me he''s changed into some sort of vermin. I didn''t think the Shi''ido could do that, but my informants are rarely wrong. We think we know where he''s holed up, but since we can''t tell him apart from the rest of the pack, you''ll just have to kill the whole lot.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 91, 'm30o', 'Lady Valarian'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 92, 'm30s', 'The Shi''ido thief is dead, along with all the vermin protecting him. Let this send a message to all those who would cross Lady Valarian: I will go to any lengths to kill my enemies! And I pay my loyal followers well, as you''ll soon discover.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 93, 'm30t', 'Shi''ido Hunter'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 94, 'm31d', 'Jun Seros here. Friend to spacers and adventurers from all across the galaxy. I''ve never met one of your kind that I didn''t like, and I think all those who have done a job or two for me will tell you that I''m loose with my tongue and my credits. Well, why don''t you find out for yourself.\n\nI own a diner in Mos Eisley. My speciality is a mystery stew. Basically a bowl full of meat and a glass of blue milk will run you a credit, or a story of adventure if I''m in the mood to listen. But here''s my trade secret: my stew''s a womp rat dish. I finally found a use for the vermin. Lately, though, it''s been tough to find womp rats at my usual hunting grounds. I''m thinking something bigger and nastier is eating them before I can get to ''em first. I think I''ve identified the creatures responsible. I want you to go take care of their lair. Once the creatures are dead, I''ll be able to capture another batch of womp rats and start serving my special stew again.   '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 95, 'm31o', 'Jun Seros'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 96, 'm31s', 'Jun Seros here again. Just wanted to thank you personally. That lair was about to put my meat stew on the backburner. Now, you''ve given me one more reason to like your kind. I''ve slipped a few credits into your account. Next time your in a cantina, raise a drink to doing business with your old friend, Jun Seros.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 97, 'm31t', 'Mystery Meat'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 98, 'm32d', 'Jun Seros here, my friend. I''ve hired virtually every adventurer and spacer who has passed through Tatooine. Working for me is almost a rite of passage for your kind. And you''re in luck: I have a job for you. My diner is known for providing hearty meals to tired travelers. I''ve tried womp rat stew, eopie briskets, and even bantha steaks. There are a few more creatures that I want to throw in my pot. I''ve spotted a lair full of creatures that might be perfect for a meal. Head out there, kill any of the creatures that you find, and destroy their lair. Once you''re done, I''ll get around to collecting the corpses. Hopefully before the sun or sand-flies get to ''em. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 99, 'm32o', 'Jun Seros'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 100, 'm32s', 'Jun Seros here. You did a great job, kid. Not many adventurers could have killed those creatures with such flair. You made it look easy. And spending the credits you''ve just earned should be easy, too.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 101, 'm32t', 'Desert Slaughter'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 102, 'm33d', 'Tatooine''s sand-flies pose a threat to public health. The small insects spread disease and harass eopies and other Tatooine herd creatures. Sand-flies proliferate in all areas of Tatooine, but are especially prevalent in and around the lairs of certain creatures. In order to reduce the sand-fly population, these lairs should be destroyed. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 103, 'm33o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 104, 'm33s', 'Tatooine''s sand-fly population has been greatly reduced by the destruction of a lair in the area. As the agent responsible for this, you have received payment for your work.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 105, 'm33t', 'Sand-Fly Epidemic'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 106, 'm34d', 'Eopies are a fundamental part of life on Tatooine. They serve as our pack animals, carrying water skins and supplies across the desert. The sturdy animals can even pull several times their own weight, making them perfect for dragging broken down landspeeders to Anchorhead for repair. And, while it might be difficult to believe, eopies can even serve as watch animals. If a Tusken Raider or hungry dune lizard gets too close, the eopies start mewling, giving us time to pull out our rifles. \n\nBut for all their strengths, eopies are basically defenseless against most of Tatooine''s predators. Even a pack of womp rats can bring down an eopie. And krayt dragons can consume entire herds. So, in the interest of protecting the eopies, I''m hiring mercenaries to destroy the lairs of any creatures that might kill these peaceful herd animals. This transmission identifies one of these lairs; go destroy it and I''ll make sure you''re richly rewarded.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 107, 'm34o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 108, 'm34s', 'As I told you before, the eopies are an important part of our life out here in the desert. You''ve done your part to protect them, and for that, I thank you. The reward I promised you has already been transferred to your account.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 109, 'm34t', 'Eopie Defender'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 110, 'm35d', 'Various creatures are overpopulating on Tatooine. If this continues, they will breed out of control, endangering sentient creatures on the planet. We''ve identified a lair that, when destroyed, will help reduce this overpopulation problem.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 111, 'm35o', 'Tatooine Wildlife Watchgroup'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 112, 'm35s', 'You''ve succeeded in your current assignment. Payment for the destruction of a problem lair has been transferred to your account.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 113, 'm35t', 'Wildlife Overpopulation'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 114, 'm36d', 'So, there''s this guy around Mos Espa who calls himself Mat Rags. He''s some kind of hunter. Claims he once bagged a rancor on Dathomir. Even wears a krayt dragon claw around his neck, like that makes him look tough. I think he''s been living here since the Battle of Naboo, you know. And he''s still talking about all the creatures he''s killed. Now, he goes out and picks off desert dwellers just to prove that he can, even though he''s older than that crazy hermit, Old Ben (whatever happened to him, anyway?). I''m so sick of listening to him brag that I''d pay anything to have someone go out into the desert and destroy whatever lairs he''s been camping around. I found one of them and want you to take care of it before I go insane. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 115, 'm36o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 116, 'm36s', 'Great work! Mat Rags came back into town, complaining about the lack of good hunting in the area. I think he''s considering a move to Mos Eisley, where "they grow their womp rats man-sized." Good. Let them listen to his constant chatter... As for you and me, I hope the credits I just transferred to your account make us even.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 117, 'm36t', 'Tatooine''s Finest Hunter'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 118, 'm37d', 'I''m on a mission to map all of Tatooine. I can tell you, it''s been more difficult than I thought. If the sandstorms aren''t making it impossible to see to the horizon, then it''s the Tusken Raiders chasing me out of my camp. Now, there''s a group of bloodthirsty creatures in my path. I''d be very grateful if you could knock out their lair so I can get back to mapping the planet.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 119, 'm37o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 120, 'm37s', 'By the twin suns, you''ve done it. I''ll have the area mapped before Second Dawn. Thank you for your help.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 121, 'm37t', 'Mapmaker''s Plea'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 122, 'm38d', 'Someday, the Podraces are going to come back to Tatooine, and I''ll be able to pull my modified Moxxnor-7 out of the garage. But, before that can happen, we need to clear the desert of obstacles. I''ve seen too many creature lairs out in the sands. If a Podracer hit one of those at full-speed, the pilot would be vaporized. Get out there and help the Podraces make a comeback!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 123, 'm38o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 124, 'm38s', 'The Boonta Eve Classic is going to return to Tatooine any season... Now that the desert is short one more lair, maybe Jabba will realize that he should start up the races again. If he does, you should take the credits I just paid you and bet on me and my Moxxnor-7. I promise you a huge return.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 125, 'm38t', 'Podracer Promoter'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 126, 'm39d', 'Eh, you look like an Outlander to me, but I hear good things about you. Maybe you can help me. And then again, maybe you''ll get killed in the desert. It makes no difference to me. But if you can destroy some pests that have damaged some of my goods, there might be a few credits in it for you.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 127, 'm39o', 'Watto'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 128, 'm39s', 'Hey, waddaya know? You destroyed that lair. You might be smarter than you look, Outlander. There are a few credits in your account. It''s too much for such a simple task, but anyone on Tatooiine will tell you that Watto always pays his debts. Unfortunately.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 129, 'm39t', 'Work for Watto'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 130, 'm3d', 'I''m intending to build a new mining facility at the coordinates attached. Because of the local wildlife, I''m unable to lay the foundation. Expert extermination staff sought to take care of the problem.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 131, 'm3o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 132, 'm3s', 'Thank you for eliminating the vermin at the site of my next mining venture. The installation should be up and running in a matter of days. I entertained the notion of naming the facility after you, but I already owe Imperial Prefect Talmont a few favors and he wants his name attached to everything these days. Anyway, I''m sure that payment for the mission''s success is reward enough.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 133, 'm3t', 'Tatooine Contractor''s Killing Crew '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 134, 'm40d', 'Landspeeder accidents are up 8% this season, largely due to the presence of non-sentient animals alongside central travel routes. These creatures periodically dart in front of oncoming vehicles, causing operators to lose control and crash. The Bestine Transportation Safety Commission, in conjunction with Imperial Prefect Talmont, is hiring contract exterminators to help keep our landspeeder lanes safe. Please report to the identified lair and eliminate it in order to help with this endeavor. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 135, 'm40o', 'Bestine Transportation Safety Commission'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 136, 'm40s', 'The Bestine Transportation Safety Commission and Imperial Prefect Talmont have been notified of your successful attempts to improve landspeeder safety on Tatooine. We are pleased to inform you that, in light of your recent success, we will be forwarding the appropriate payment to your account. Thank you and have a safe day.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 137, 'm40t', 'Vehicular Vermin '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 138, 'm41d', 'Hello. Please excuse the quality of this message. We don''t have much use for datapads out here. Not even sure if I know how to send this transmission... But, if you''re reading this, then I suppose I did something right. Let me get to the point. We all have work to do.\n\nEvery season, the sandstorms kick up. They usually chase at least a few dozen animals onto my land. I''m taking precautions this year. I spotted some creatures near my farm. No doubt they''ll be heading for my garage once the sandstorms start. Unless you destroy them first. I have some credits buried under a vaporator. I''ll pay you to take care of this for me. Good luck.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 139, 'm41o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 140, 'm41s', 'Hello again. I wish to thank you for wiping out the creatures near my homestead. I''ve dug up my credits and will transfer them to your account soon.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 141, 'm41t', 'Sandstorm Migrations'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 142, 'm42d', 'The Galactic Pest Authority has documented a significant increase in reported encounters with recognized predators on Tatooine. To protect public safety, destroy the identified lair. '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 143, 'm42o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 144, 'm42s', 'We''ve recently collected data that suggests a dramatic decrese in the number of recognized predators on Tatooine. We at the Galactic Pest Authority attribute that sudden decline to your efforts. Your activities on behalf of the good citizens of Tatooine will be handsomely rewarded.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 145, 'm42t', 'Tatooine Pest Control'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 146, 'm43d', 'The Galactic Pest Authority is disappointed to report a sharp rise in the number of problem animals reported on Tatooine. These so-called "nuisance creatures" damage moisture vaporators, steal delicate pallies and other foodstuffs, and harass honet moisture farmers. For the good of all, the lair of these recognized nuisance creatures must be eliminated.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 147, 'm43o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 148, 'm43s', 'The Galactic Pest Authority has collected substantial data suggesting a dramatic decrese in the number of reported nuisance creatures on Tatooine. The organization attributes this sudden decline to your efforts. Your activities on behalf of the good citizens of Tatooine will be handsomely rewarded.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 149, 'm43t', 'Nuisance Creature Control'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 150, 'm44d', 'The Galactic Pest Authority is paying operatives to conduct routine creature culling on Tatooine. This is a common practice on a number of worlds, used to control the spread of problem creatures. A "problem creature" might be defined as predatory, disease-bearing, invasive, or prone to violence. To aid in this specific creature culling, destroy the identified Tatooine lair.  '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 151, 'm44o', 'Galactic Pest Authority'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 152, 'm44s', 'The Galactic Pest Authority is pleased to report that this season''s culling expedition to the desert planet of Tatooine has been a monumental success. All agents assigned to this incredible endeavor will receive payment directly.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 153, 'm44t', 'Tatooine Creature Culling'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 154, 'm45d', 'The Tatooine Reclamation Society is a coalition that includes Bestine, Mos Espa, and several other major cities on Tatooine that have joined forces with generous Imperial authorities to improve life on our desert planet. As part of the Tatooine Reclamation Project, the Tatooine Reclamation Society is trying to make passage through the desert as safe as possible by eliminating any creatures that might pose a threat to travelers. The Tatooine Reclamation Society is broadcasting the coordinates of lairs belonging to these beasts. We sincerely hope that loyal Tatooine citizens will take it upon themselves to aid the Reclamation Project by destroying these creatures and their lairs. A suitable reward will be offered to anyone who aids in this effort.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 155, 'm45o', 'Tatooine Reclamation Society'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 156, 'm45s', 'The Tatooine Reclamation Society is pleased to report that a number of dangerous creatures have been eliminated, making desert passage safe for weary travelers. Those citizens directly responsible for the destruction of these lairs have been rewarded and deserve the thanks of the entire planet! '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 157, 'm45t', 'Public Safety Project'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 158, 'm4d', 'It''s a little known fact that microscopic brown worms from the Zocolidae family are found on many worlds throughout the Galaxy, with a remarkable concentration located on Tatooine. It is believed that the brown worms may in fact be responsible for crucial ecological processes that help remove toxic chemicals from the soil, rendering worlds habitable. As it happens, an ongoing study on Tatooine has focused on the local population of Zocolidae, specifically the minor variant G. Zocolidae Amedus, with the goal of seeking commercial application for their unique biochemistry. Unfortunately, the invasive presence of local Tatooine fauna is disrupting the collection of these rare and potentially extremely valuable worms. Therefore, my backers would like to offer a reward for the removal of local fauna.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 159, 'm4o', 'Vinda''a BioChemical Laboratories'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 160, 'm4s', 'Vinda''a BioChemical Laboratories is extremely pleased with your efforts to protect the microscopic G. Zocolidae Amedus! Tatooine''s Zocolidae population is flourishing as a result of your endeavors. Soon, Vinda''s BioChemical Laboratories will be announcing a number of exciting new applications for the organism. These discoveries will revolutionize agriculture and terraforming ventures throughout the galaxy. \n\nMy backers have authorized the immediate transfer of payment to your galactic account. I hope you enjoy spending it.  '),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 161, 'm4t', 'Save Tatooine''s G. Zocolidae Amedus!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 162, 'm5d', 'So I was wandering around the desert, right? And I saw this... thing. It was ugly, so I followed it, thinking that I''d find out what it was. But then I spotted a whole bunch of them... You wouldn''t believe how many... And they chased me away. I think someone should kill them, but it ain''t going to be me!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 163, 'm5o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 164, 'm5s', 'All my friends told me that anyone who would go after those ugly creatures had to be crazy, desperate, or stupid. I think you''re just very, very brave. I still can''t believe you had the guts to take on those animals, whatever they were... I''ve been saving to buy some air brakes for my custom-built Podracer, but I think you deserve every credit in my account. Thanks again.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 165, 'm5t', 'Tatooine Ugly Creature Killing'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 166, 'm6d', 'Only about one in a million creatures carry the Jundland Pox, but my research indicates that number may start increasing. I''ve located an area that seems to have a higher than usual concentration of the disease. We need to narrow the area''s local animal population before the disease spreads and starts affecting other creatures.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 167, 'm6o', 'Bestine Hospital Medical Chief'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 168, 'm6s', 'You should realize that you just saved half of Tatooine. My most recent studies clearly show that the Jundland Pox was about to become an epidemic. You eliminated the pox-ridden creatures before that could happen. Most of Tatooine''s citizens will never know how close they came to death, but I''ll also remember that you saved the planet.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 169, 'm6t', 'Jundland Pox Control'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 170, 'm7d', 'I''ve lived in the desert my whole life. Ever since I was a child, I heard stories about "Old Yellow Scale," a krayt dragon who had supposedly lived forever. I had never seen him, though, until a few weeks ago. The monster was huge. But old, and sickly. I watched in horror as he stumbled past me, and then collapsed and died. I still have one of his fangs. But, with Old Yellow Scale dead, we''ve traded one huge threat for hundreds of smaller ones. You see, here''s the thing: Old Yellow Scale ate a lot of the smaller wildlife around this area. He kept them from breeding out of control. And now, that''s just what happening. I''d rather spend my life trying to avoid a single krayt than dodging hundreds of wild animals. So, I''ve located a few creature lairs that need to be eliminated posthaste. Do me the favor of wiping one out.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 171, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 172, 'm7s', 'Well, things are finally getting back to normal around here. Even without Old Yellow Scale. I was sure that we''d be buried under vermin, but the destruction of several lairs has kept them in check. Thank you.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 173, 'm7t', 'Old Yellow Scale''s Legacy'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 174, 'm8d', 'My little pet was murdered! Those filthy beasts just came in and killed my poor pet, my favorite pet, my beloved little Kowakian monkey-lizard! For no reason! Please, wipe them out! I''ll pay for you to avenge my poor little companion!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 175, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 176, 'm8s', 'Thank you for helping my beloved Kowakian monkey-lizard find peace. You''ve avenged his death. You deserve to be paid, in his memory.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 177, 'm8t', 'Pet Eaten'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 178, 'm9d', 'Another official hunting sub-season has begun! Credits are offered for confirmed destruction of lairs on Tatooine. Good luck!'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 179, 'm9o', 'Galactic Game and Wildlife Commission'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 180, 'm9s', 'Your hunting expedition was extremely successful! Congratulations! The Galactic Game and Wildlife Commission is pleased to award you with well-deserved credits.'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 181, 'm9t', 'Tatooine Hunting Season Opens'),
('string/en/mission/mission_destroy_neutral_medium_creature_tatooine.stf', 182, 'number_of_entries', '45'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 1, 'm1d', 'The Empire''s efforts to stamp out the Rebellion has unfortunately created some additional problems for law enforcement. We have more refugees to deal with, many of which are recruited by local swoop gangs or glitterstim dealers. Naturally this means we have to deal with more violent crimes and we''re already rather understaffed. This is where you come in, citizen. We have plenty of work for enterprising agents who want to lend a hand to keep peace and order in our communities. We''ve kept tabs on the activities of these gangs and know where most of them hang out. One by one we need to clean those places out. Most of them are condemned buildings anyway. Think you can help us out, citizen? We''ll pay you for your successful efforts, of course. '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 2, 'm1o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 3, 'm1s', 'Good work, citizen. One by one, we''ll get all these wretched hives of scum and villainy. Have a drink on us.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 4, 'm1t', 'Clean up the streets'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 5, 'm2d', 'My son has fallen in with a very bad crowd. He was arrested last month on suspicion of murder but the case was dropped for lack of evidence. I know my son didn''t kill anyone but I know who did. Those thugs he hangs out with are thieves, murderers, and worse. They don''t deserve to share the same space as decent citizens. I''ve arranged for my son to spend a few weeks with his aunt in the country. The air will be good for him. What I need is for someone to blast that gang''s hideout to pieces while my son is gone. That will drive those animals away and teach them never to come back and bother us again. I''ve put up a generous reward for the citizen or citizens that can accomplish this important task. Can you help me?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 6, 'm2o', 'A Desperate Mother'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 7, 'm2s', 'I just discovered that my son ran away from his aunt''s and is likely staying at the gang''s hideout. Did you destroy it? Did you kill everyone there? Oh no! My dear son! Oh no!!! '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 8, 'm2t', 'Help save a wayward son'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 9, 'm3d', 'Our agents have uncovered a major glitterstim dealer''s lair. These criminals supply a majority of the spice for many of this system''s major cities. We need to put this scum out of business and we need your help to do it. The dealer has done well so they''ve hired some muscle to protect their precious goods. A quick, stealthy strike, however, ought to get the job done. Don''t worry about blasting anyone that gets in your way - most of these guys are wanted murderers. If the settlement is left a smoking ruin, we''ll be mighty pleased. We always reward results too. '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 10, 'm3o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 11, 'm3s', 'Nothing quite as sweet as the smell of burning spice in the morning, eh? Good job, citizen. Keep up the good work.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 12, 'm3t', 'Destroy spice dealer''s stash'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 13, 'm4d', 'A series of savage beatings, three of which resulted in fatalities, have taken place over the last six weeks in our community. It seems that a new gang has moved into the neighborhood and they''re announcing their presence. Any citizen who stares at these thugs for too long risks a brutal beating and possible death. The local authorities already have their hands full assisting the Empire in tracking down Rebels; they simply do not have enough men to patrol the streets. We are therefore taking matters into our own hands. We''re offering a reward to any citizen who has the courage to march into that gang''s hangout and blast those murderers to atoms. We must make it clear to these scum that we will not tolerate this sort of behavior in our streets. Are you a courageous citizen? Let us know and we''ll transmit the coordinates to the gang''s hangout to you.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 14, 'm4o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 15, 'm4s', 'It''s citizens like you that will insure our futures are free of crime and social predators. Hurrah, citizen! You can be our champion any day.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 16, 'm4t', 'Smash the gang'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 17, 'm5d', 'Some slavers are not content to stick to the Imperial list of approved species. Indeed, these slavers feel they must enslave humans, and that''s something we can''t tolerate. Through the help of Imperial Intelligence, we''ve located the lair of a group of slavers that have been dealing exclusively in humans. We need a small strike team to assault this base and blast it into rubble. Humans shall not be enslaved while the Empire governs the galaxy. Can you help the Empire put a stop to this despicable practice? The reward will be well worth it.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 18, 'm5o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 19, 'm5s', 'Handled like a true professional. You should consider working for us again in the near future. Enjoy your reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 20, 'm5t', 'Stop the slavers'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 21, 'm6d', 'A group of dangerous criminals is using an old halfway house in our area as a hideout and refuge from authorities. They use the halfway house''s former reputation, a place where reformed criminals were reintroduced into society, to mask their current illegal activities, including spice dealing and extortion. We want this place wiped out and those murderers run off or brought to justice. We can''t ignore their activities any longer. We''ll pay a reward to anyone willing to undertake and complete this task. Are you the citizen we''re looking for?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 22, 'm6o', 'Citizens for a Clean Tomorrow'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 23, 'm6s', 'We''re glad to see you share our enthusiasm to create safe neighborhoods for our children. You deserve this reward, citizen.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 24, 'm6t', 'Clean out the halfway house'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 25, 'm7d', 'Someone has been supplying the local gangs with homemade explosives, which they''ve gladly used in recent attacks. We knew it had to be someone in the area and launched an investigation. Finally, after weeks of work, we''ve discovered where these grenades are being constructed. A weapons lab is being run by a particularly vicious gang of killers. Many of them served in planetary security forces in the past but lost their jobs when the Empire began cleaning out these corrupt organizations. We need to take this lab out of commission, especially if it''s attracting disgruntled weapons specialists from around the galaxy. We require a small strike team of agents to go in there and blow that structure sky-high. But best be on your toes as those criminals have had some pretty advanced combat training. Can you help us out? '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 26, 'm7o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 27, 'm7s', 'Now that''s what we call "blowing a structure sky-high." Nicely done, citizen. Take your reward and remember that there''s plenty more where that came from.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 28, 'm7t', 'Blow up the explosives lab'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 29, 'm8d', 'A swoop gang has been terrorizing several communities. Their recent "fun" consists of zooming past shops or settlements and sniping citizens through windows or portals. The body count so far is nine dead and six others wounded. I want these animals stopped. Problem is, this gang is very mobile and have some insight into the movements of local law enforcement because they disappear before any raids or arrests can be made. Fortunately, I have contacts in the smuggling world (a long story that I won''t go into) and these gangsters have been buying shipments of glitterstim from someone I know (suffice it to say the old pirate owed me a favor). So now I have the coordinates to this swoop gang''s hideout. If I involve the authorities, these murderers disappear. So that''s where you come in. I''ll pay a handsome reward to any being (or beings) that will rid these besieged communities of these animals. My past hasn''t exactly been what you would call "upstanding" but I''m not gonna stand by and watch innocent folks get slaughtered. Not when I can do something about it. What about you?  '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 30, 'm8o', 'A Reformed Smuggler'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 31, 'm8s', 'You''re alright, buddy. Good to see that someone cares enough about other people to lend a hand. All the better that the hand is being paid for those efforts, eh? Being''s gotta make a living somehow.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 32, 'm8t', 'Stop the swoop gang'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 33, 'm9d', 'Deathsticks in a decent community!  Is nowhere safe from the corruption of this vile drug?  Recently I learned from respectable sources that a so-called "esteemed businessman" is secretly fronting a distribution center for this contemptible substance.  The villain''s business dealings span many star systems and so the local authorities have been reluctant to interfere.  But he underestimates the determination of upright Imperial citizens!  Who among us is bold enough to find this den of evil and stamp out this blight on galactic decency?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 34, 'm9o', 'An Upstanding Citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 35, 'm9s', 'You actually survived?  Um, excellent work!  Here, take this small token of gratitude for your act of decency.  And please don''t tell anyone who hired you.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 36, 'm9t', 'Stamp out a deathstick dealer'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 37, 'm10d', 'As an esteemed businessman whose dealings span many star systems, I am in a state of outrage at the no-good meddling of a certain "upstanding citizen."  This rotten muck-leech has hired local muscle to interfere with my honest and legitimate trading operations.  He has blown up my establishments and accused me of certain unlawful actions for which he has no proof that I know of.  He has asked for protection money but a businessman like myself would rather spend the credits to put the squeeze on an enemy.  So I am offering a reward to any toughs or sharpshooters who can take out the office of this low-down nerf-herder and his gang of slugs.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 38, 'm10o', 'An Esteemed Businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 39, 'm10s', 'Say, you''re pretty good at this racket.  You earned these creds.  I hear the "upright citizen" got away, but I''ll blink you when he turns up again.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 40, 'm10t', 'Break up an extortion gang'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 41, 'm11d', 'Killers for hire in the heart of a decent community!  Once again we are plagued by an underhanded villain in the guise of an "esteemed businessman."  This time he has hired a vicious pack of brutal thugs to terrorize upstanding citizens.  Why, these laser-armed ruffians blew apart my very own office!  But upright folk such as ourselves need not involve Imperial authorities to enforce moral discipline.  I have obtained the coordinates of the lair where these despicable savages charge their blasters and sharpen their knives.  Who shall fire the first shot in the name of galactic decency?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 42, 'm11o', 'An Upstanding Citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 43, 'm11s', 'You''re still alive?  Well done!  Now decent folk like myself can once again conduct our operations in peace.  Take this reward and please, don''t tell anyone who hired you.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 44, 'm11t', 'Purge a lair of professional thugs'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 45, 'm12d', 'As an esteemed businessman whose dealings span many star systems, I am shocked and in much distress over the low-down, rotten activities that a certain "upstanding citizen" has perpetrated while pretending that he is not a dirty, lawbreaking creep.  Not only has he stuck his proboscis into my own, completely lawful import business, but now I have learned that he is running a spice racket on the side.  I''ve had enough of that slime-grub and his two-faced meddling.  For any toughs or sharpshooters who have the guts, I have the coordinates of a depot where he stores his goods for shipping.  The Imperial authorities will be happy to see it burn to the ground.  I''ll even throw in a reward for anyone who does the job.  Sometimes a hard-working businessman like myself must play rough with creeps who stand in the way of honest and respectable trading.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 46, 'm12o', 'An Esteemed Businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 47, 'm12s', 'You''re pretty handy in a fight.  Take the reward and keep your eyes open.  I might have more jobs for you in the future.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 48, 'm12t', 'Take out a spice depot'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 49, 'm13d', 'Excuse me.  Normally I would not broadcast a message on this frequency, as I am only a protocol droid, but my present circumstances are most intolerable.  Since my master was taken away by the Empire for questionable political statements, I have been forced to deal with a collection of dubious characters who have taken up residence in the condensing station.  Condensed Threll gas is highly combustible, so I believe it is best to have these individuals removed from the premises.  I have a stipend of credits from which I can pay a reward.  Please contact me if you are able to help.  Thank you.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 50, 'm13o', 'L-3PO'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 51, 'm13s', 'Oh, dear!  You destroyed the entire condensing station!  Please, just take these credits and go while I determine how I shall break the bad news to my poor, imprisoned master.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 52, 'm13t', 'Remove intruders from a condensing station'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 53, 'm14d', 'Recent intelligence points to one conclusion: Roughnecks from the frontier have begun to view this sector as a source of salvaged parts for their asteroid loaders.  Unfortunately, some of them have established a sabotage ring to provide a continuous supply of free salvage.  As the resources of the Empire are occupied with Rebels and other political offenders, we have decided to contract outside agents to deal with this new criminal enterprise.  Interested agents are encouraged to contact us for known locations of salvage drops.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 54, 'm14o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 55, 'm14s', 'The Empire thanks you for contributing to the wellbeing of the community.  Enjoy your reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 56, 'm14t', 'Strike against a sabotage ring'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 57, 'm15d', 'It''s not podracing, but who doesn''t enjoy testing his landspeeder on the local drag lanes?  In my career I have collected an assortment of vintage speeders to pit against my fellow repulsorlift enthusiasts.  The problem is, lately the speeder races have been taken over by a gang of shady offworlders.  I have proof that they are foiling their opponents'' turbine filters, which accounts for their undefeated record.  Unfortunately these skettos are so well armed that no one is willing to confront them.  But enough is enough.  I''m down to my last lasercharged X-34.  I''m willing to pay anyone who can blast up their hangout and make them understand that cheating is unacceptable in this old and honorable sport.  Contact me for the coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 58, 'm15o', 'A Speeder Enthusiast'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 59, 'm15s', 'Wonderful job!  Now I can rebuild my landspeeder collection without fear.  Take this reward and please, come out to the drag lanes sometime.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 60, 'm15t', 'Punish a den of landspeeder sharks'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 61, 'm16d', 'As if droid scrap fighting were not seedy enough!  Now the sponsors of these disreputable contests have begun to steal shipments of droids to squander in their oily pits of destruction.  If these criminals disrupt my business any further, I am in danger of losing my Imperial contract.  Therefore I am offering a substantial reward to anyone who has the fortitude and the means to wipe out one of these loathesome scrap fighting arenas.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 62, 'm16o', 'Yizz the Droid Merchant'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 63, 'm16s', 'Excellent!  I don''t suppose in the mayhem you happened to spare any of my stolen droids?  No?  Well, I had to ask.  Here''s the reward, as promised. '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 64, 'm16t', 'Destroy a pit of droid thieves'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 65, 'm17d', 'Do you think Sith Lords are made overnight? No, my young apprentice, they require years of careful grooming and training in the Dark Side. Yes, I''m sure you''ve guessed who I am by now. I am the Emperor! And I require you, my young apprentice, to obliterate some annoying servants for me. They have disturbed me once too often during my clandestine visits to my various systems. I find their pitiful attempts to match the glory of the Dark Side beneath contempt. You will crush them, my young apprentice. Show them the power of the Dark Side. Rewards will be yours and perhaps one day you may rise to the level of a Sith Lord yourself. I will tell you how to find these loathsome servants after you accept. And I know you will. Hahahahaha!'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 66, 'm17o', 'The Emperor (Honest)'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 67, 'm17s', 'You have done well, my young apprentice. Soon the galaxy shall see the rise of a new Sith Lord. But only if you continue to serve me faithfully.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 68, 'm17t', 'Help a deranged citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 69, 'm18d', 'Sometimes planetary governments overstep their authority, which can cause headaches for Imperial law enforcement.  Case in point: The king of Malgwen IV has mistakenly issued pardons to a notorious band of pirates who once terrorized the Aparo Sector.  While the Imperial Navy has sent a Star Destroyer to instruct the king in the particulars of galactic law, we must also explain to these pirates that their pardons are incorrect on a few minor points.  For this purpose we are contracting an enforcement team to blast their den into a smoking heap of bodies and microscopic rubble.  Perhaps in the future such mistakes in legal protocol will occur less frequently.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 70, 'm18o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 71, 'm18s', 'You have a knack for the precise workings of galactic law.  Perhaps you should consider applying to the Imperial Bar.  Your services would be most welcome.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 72, 'm18t', 'Instruct a band of pirates in Imperial protocol'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 73, 'm19d', 'Some women would be ashamed to admit that they married the wrong man, but I''m not one to lie to myself.  Karst Bono charmed his way right into my family inheritance.  Then he took everything he could grab and returned to his wretched hive of pirate friends.  Never trust a gentleman pirate.  I will not deny that I made a mistake, but I am prepared to clean up the mess I made.  All I need are a few skilled hands to visit my delinquent husband and his thieving friends.  The remedy to my problem is simple.  Raze the pirates'' den to the ground and laser the pack of scoundrels into dust.  Extermination is the simplest form of divorce.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 74, 'm19o', 'An Impending Widow'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 75, 'm19s', 'Thank you.  That was better than alimony.  Here''s your payment.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 76, 'm19t', 'Raze a pirates'' den'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 77, 'm20d', 'I always instruct my freight pilots to cooperate with pirates, because freebooting need not entail bloodshed.  However, one of my ships has just been robbed of something more valuable than mere cargo.  The databanks of a stolen computer included some private business records which need to remain discreet.  My insurance company may not approve of any correlation between my losses to pirates and my contacts with same.  Therefore, much as I am loathe the interfere with the entrepeneurial spirit, I need to hire some agents to infiltrate a certain landing bay and ensure that the stolen computer is destroyed.  Just to be safe, while said agents are on the premises, they should level the place and make sure that none of the pirates escape.  I would not require such severe measures if I did not have the utmost respect for this ancient profession.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 78, 'm20o', 'A Respectful Merchant'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 79, 'm20s', 'Such a shame.  Those poor pirates were only trying to make their way in the universe.  Perhaps you should consider filling the void they left behind.  Think of this payment as seed money and let me know what you decide.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 80, 'm20t', 'Destroy a stolen computer and the pirates who took it'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 81, 'm21d', 'A wedding is a beautiful thing, don''t you agree?  My eldest son is engaged to a harem of twelve Ithorian sisters.  They will not make the most graceful of wives, but they do bring a respectable dowry.  Unfortunately a squadron of pirate fighters has been threatening the local star lanes.  I am concerned that the dowry may be stolen.  The wedding would then be cancelled, which would break my poor son''s heart.  Please, can you help a loving father by blasting all trace of these pirate scum from surface of the planet?  Do it for the cause of love, and you shall receive a hefty pile of credits for your trouble.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 82, 'm21o', 'A Loving Father'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 83, 'm21s', 'Truly yours was an act of love.  Here are the promised credits to defray the cost of thermal detonators and blaster fuel.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 84, 'm21t', 'Protect a wedding by eliminating pirates'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 85, 'm22d', 'Vile pirates in our very own sector!  These despicable cutthroats have raided one of our volunteer freight ships and stolen a precious cargo of Kowakian monkey-lizards headed for orphans on Gamorr.  In response we have sold enough home-baked Horquad cakes to hire a team of assassins to lay waste to these loathsome murderers.  We have the coordinates to their secret den.  Leave no wall standing!  We must fight back in the name of goodness and virtue.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 86, 'm22o', 'Toydarian Women''s League'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 87, 'm22s', 'Those poor orphans will never get their monkey-lizards, but at least they can lay down their little heads at night knowing that the villains who robbed them died a horrible, fiery death.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 88, 'm22t', 'Pirates have stolen pets from orphans!'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 89, 'm23d', 'There is a Gamorrean warrior standing beside me.  He seems to want me to broadcast a request for him.  By his grunts and pointing, I''m pretty sure that he wants someone to destroy a pirate cantina not far from here.  At least I think that''s what he wants.  He gave me a bunch of credits, which I suppose are intended to be payment.  Anyway, I''ll transmit the coordinates of the cantina to anyone who''s interested.  Please respond quickly and make sure all the pirates are killed.  This Gamorrean has a very large axe in his hand.  I''m afraid he''s going to hurt me if I don''t get this right.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 90, 'm23o', 'A Cooperative Citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 91, 'm23s', 'Oh boy.  Now that you''ve destroyed the pirate cantina, I''m not so sure that''s what the Gamorrean wanted.  He sees the smoke and is getting upset.  I don''t suppose you could give me back those credits?  Please?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 92, 'm23t', 'A request on behalf of a Gamorrean warrior'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 93, 'm24d', 'Ion cannons are the ideal weapon for space pirates.  The Empire is very careful to restrict the movement of artillery-class ion guns, yet inevitably some of them fall into the wrong hands.  Fortunately less experienced pirates fail to disable the tracking circuits, allowing us to locate and disable the cannons.  The preferred method for such action is a swift ground strike, killing everyone and utterly razing the pirate installation.  We routinely hire civilian contractors for these tasks.  Interested parties may contact us for the appropriate coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 94, 'm24o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 95, 'm24s', 'The Empire appreciates a reliable contractor.  Here is your payment.  Please contact us again for more assignments.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 96, 'm24t', 'Destroy a pirate''s ion cannon'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 97, 'm25d', 'This is going to sound strange, but hear me out.  A band of pirates has set up shop in my district with a peculiar method of operation.  They force ships to land using a small ion cannon, and then employ a stolen AT-AT walker to subdue the survivors and spirit away the cargo.  My problem isn''t that the pirates are active.  Rather their possession of an AT-AT is extremely dangerous to me.  The Empire audits all of my records.  If I send my own security forces to deal with this situation, the reports will wind up in the hands of the military and my planet may become one of the Empire''s famous "examples to others."  So I need to delegate this assignment to an outside force.  Payment will reflect an assumption of discretion.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 98, 'm25o', 'Local Prefect C-912'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 99, 'm25s', 'My men have confirmed that there''s no trace of the AT-AT on the site.  You may have saved the entire planet.  Good work.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 100, 'm25t', 'Eliminate an unusual pirate gang'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 101, 'm26d', 'There''s a code, you know, among the brotherhood of pirates.  At the top of the list is this: There''s folks you steal from and there''s folks you buy from.  The two don''t mix.  My particular profession, for instance, is historically exempt from piracy.  But a certain newcomer seems to lack historical perspective.  Not long ago he took from me a shipment of Dressellian smoke-rum and has failed to settle the account.  Another customer has provided me with the coordinates of his private villa.  I need a group of toughs to trash the place and explain to him the consequences of flouting tradition.  If he and his crew do not live long enough to apply this lesson, my heart shall not be broken.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 102, 'm26o', 'An Irate Wine and Spirits Merchant'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 103, 'm26s', 'It''s a shame that simple ignorance has led to this tragic loss.  That was a particularly nice batch of smoke-rum.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 104, 'm26t', 'Explain polite behavior to a pirate captain'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 105, 'm27d', 'With so many of our resources handling political offenses, sometimes the Imperial Office of Criminal Investigations must hire contractors to deal with ordinary crimes such as piracy. For instance, we have the coordinates of a small habitation which is suspected to harbor a dangerous crew of notorious pirates.  We need a team of civilians to reconnoiter the area and destroy all buildings and collateral assets they find.  Of course "collateral assets" include pirates, suspected pirate sympathizers and those associated with suspected pirate sympathizers.  Efficient execution of these instructions will result in a favorable ranking on our official list of contractors.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 106, 'm27o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 107, 'm27s', 'You are an efficient contractor and loyal Imperial citizen.  We have noted this in our records.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 108, 'm27t', 'Routine elimination of pirates and suspected pirate sympathizers'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 109, 'm28d', 'Unbelievable.  These days anyone thinks they can become a pirate.  A large collection of jizz musicians has bought themselves a stash of weapons and decided to call themselves hardened criminals.  It''s not even worth a real pirate''s time to teach them a lesson.  So on behalf of parties who shall go unnamed, I am hiring some muscle to show these jizz-wailers what real trouble looks like.  Go to their den at these coordinates and show them no mercy.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 110, 'm28o', 'A Helpful Accomplice'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 111, 'm28s', 'Alas, the jizz community shall mourn the loss of these clowns.  The rest of us raise our glasses to a job well done.  Enjoy the reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 112, 'm28t', 'Whack some wannabe pirates'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 113, 'm29d', 'Pirates have always interfered with our freighters, but lately a particular captain has become a singular nuisance.  In this sector he is known as the Black Scourge.  An absurd rumor claims that he is a simple MSE-6 mouse droid, but of course that''s ridiculous.  Could a mouse droid make a shambles of all our trade with the Empire?  Could it steal a shipment of tractor beams from under our noses while tricking two squadrons of TIE escorts into attacking each other?  Whoever this devil really is, we now have the coordinates of the secret hangar from which he and his seasoned accomplices plot their next deadly assault.  We require the services of a battle-hardened team to storm this lethal den and eliminate the dangerous murderers within.  Our business with the Empire depends upon success.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 114, 'm29o', 'The Rodian Industrial Consortium'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 115, 'm29s', 'Well done!  Our investigators confirm that the only "survivor" was a worn-looking mouse droid, which we left behind in the rubble.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 116, 'm29t', 'Eliminate the Black Scourge'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 117, 'm30d', 'We have pinpointed the coordinates of a ground-based tractor beam used by area pirates.  For a percentage the owners use the beam to trap merchant ships so that space pirates can board them.  We need a civilian strike team to take out the weapon.  The site is heavily guarded, so be prepared for a fight.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 118, 'm30o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 119, 'm30s', 'Now the merchants who fly through local space have one less worry.  Well done.  Here is your payment.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 120, 'm30t', 'Take out a pirate tractor beam'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 121, 'm31d', 'Our informants have assured us that quite a number of wanted pirates frequent an obscure little cantina at these coordinates.  Enterprising freelancers are encouraged to remove this blight from the planet.  A substantial reward is available.  These are hardened criminals and will be well-armed.  The cantina is billed as a "private club," so don''t expect a warm welcome.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 122, 'm31o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 123, 'm31s', 'Here is your reward.  The star lanes are safer thanks to your good work.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 124, 'm31t', 'Erase a shady cantina from the community'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 125, 'm32d', 'Even pirates have to eat.  We have the coordinates of a secret depot where these space outlaws buy contraband food supplies without notifying the authorities that they have landed.  We need some experienced freelancers to blast the site to smoke and rubble.  There are usually one or two armed pirate crews in the area, so destroying this depot entails some danger.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 126, 'm32o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 127, 'm32s', 'Excellent.  Those space scum need to understand that their cutthroat ways are not welcome in this system.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 128, 'm32t', 'Destroy an outlaw supply depot'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 129, 'm33d', 'An enterprising pirate captain recently stole a cargo of Imperial probe droids.  With a little reprogramming these droids have become his scouts in the area, monitoring the local spaceports and alerting him when a rich freighter takes off.  Our own probots have tracked his droids to a well-fortified terminal off the beaten path.  We would like to contract some freelancers to stage an assault on the terminal and blast it into oblivion.  Survivors are not encouraged.  Contact us for the coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 130, 'm33o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 131, 'm33s', 'Good work.  Without his fleet of probe droids, that pirate will have to track down his quarry the old-fashioned way.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 132, 'm33t', 'Blast a pirate droid terminal to oblivion'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 133, 'm34d', 'A good captain likes to challenge his crew every now and then.  I''ve got some brutes in my employ whose mettle needs testing.  To do this I need some handy marksmen to launch a surprise assault on the barracks where they''re currently lodging.  Show them no mercy.  Only the toughest freelancers need apply, and I''ll pay handsomely if you do the job well.  '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 134, 'm34o', 'A Good Captain'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 135, 'm34s', 'Hm.  I expected at least a few of my crew to survive.  Well, I guess they weren''t up to the rigors of the job.  Here''s your payment.  I don''t suppose you''re looking for work?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 136, 'm34t', 'Attack a barracks'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 137, 'm35d', 'Spice smuggling and gunrunning has risen dramatically in this sector. With the help of Imperial Intelligence, we''ve managed to locate the hideout of a notorious band of smugglers. We don''t want to bother the Imperial Military with this matter so we thought we''d take care of it locally. There are plenty of loyal and able-bodied citizens willing to help the local law enforcement authorities, after all. This mission will be perilous and therefore we''re offering a compensatory reward. However, a thorough job must be done. The base must be wiped out. Can you lend a hand, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 138, 'm35o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 139, 'm35s', 'Mission accomplished, citizen. We knew we could rely on the brave citizens of the Empire to help keep their systems free of crime. The reward is yours.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 140, 'm35t', 'Help local law enforcement'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 141, 'm36d', 'As with any sort of vermin, once you clean out the nest, the infestation will disappear. So it is with smugglers, citizen. We know of a local warehouse being used to store all sorts of contraband, from illegal weapons to glitterstim spice. We need a team of law-abiding citizens to clean this "nest" out. We''re certain that the smugglers will stop coming around here when they see what ordinary citizens are willing to do to their ill-gotten goods. Do you think you could help us out with this, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 142, 'm36o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 143, 'm36s', 'That was a thorough job, citizen. I doubt those vermin will be coming around here anymore. Collect your well-earned credits.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 144, 'm36t', 'Wipe out smuggler den'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 145, 'm37d', 'Catching smugglers can be like trying to catch flies with your hand, citizen - you have to be fast and alert if you want to succeed. We''ve certainly been alert, and now we need someone to be fast for us. We''ve tracked down a smuggler''s outpost used to store contraband and harbor criminals. We don''t have the manpower necessary to strike this den of thieves, but we can certainly try to entice enterprising citizens into doing it for us. There''s a juicy reward in it for you if you succeed. Come on, citizen, the Empire could really use your help. '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 146, 'm37o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 147, 'm37s', 'Seems like you were fast enough to catch those particular flies, eh, citizen? Good job. You''ll make a fine law enforcement agent yet.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 148, 'm37t', 'Remove smugglers'' outpost'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 149, 'm38d', 'There are smugglers and there are smugglers, if you know what I mean. Some of these second-rate flyboys don''t merit our full attention but neither can we afford to completely ignore them. If they''re contracted for a job, even a small job, and hydrospanner it to pieces then you''ve got to pay the penalty. Our organization is offering a reward to anyone who can settle some of these small matters for us. We have the coordinates to various hideouts used by these smugglers and need someone to make sure they don''t offer their incompetent services to anyone again. Blast their hideouts to pieces. Blast them to pieces too if they''re there. Collect from us when you''re done. See? That''s how all business should be conducted. Simple and easy.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 150, 'm38o', 'Black Sun'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 151, 'm38s', 'Handled like a true professional. Very good. Collect your reward and move on to the next one.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 152, 'm38t', 'Take out some amateurs'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 153, 'm39d', 'Smugglers certainly prosper in times of civil crisis. The Rebellion is unfortunately creating many job opportunities for these lowlifes and is in fact attracting more unemployed pilots to the trade. Our job is to wipe them out as fast as we can find them, but we can''t do it alone. We''ll gladly offer a reward to anyone that cares to lend a helping blaster. We have the coordinates to their bases of operation and need them cleaned out. We don''t really care how you do it as long as the bases are left in a shambles. Can you help the Empire with this work, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 154, 'm39o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 155, 'm39s', 'Fairly effective, citizen. We think you may have found a new line of work. Plenty of it these days too. Enjoy your reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 156, 'm39t', 'Help local law enforcement'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 157, 'm40d', 'I don''t know who''s been telling these space slugs that smuggling is glamorous or easy work. Seems like everyone is trying to get in on the action. Just creates more work for us, of course. We''ve been authorized to employ independent agents to help with the workload. You enjoy blasting things? Like doing it with the weight of the law behind you? Well here''s your chance, citizen. We''ll provide you with the coordinates to a known smuggler''s base and your trigger-happy self can have a grand old time. Blast away! When the job''s done we''ll throw in some credits for your trouble. Not a bad job, eh?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 158, 'm40o', 'Imperial Office of Criminal Investigations'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 159, 'm40s', 'Well it sure looks like you can use that blaster instead of just wearing it. Good for you! Here''s the credits we promised. Blast more, get more.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 160, 'm40t', 'Hunt smugglers'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 161, 'm41d', 'We have some legitimate complaints concerning some local smugglers. We don''t really want to involve the authorities - you know how messy that can get. Instead we''d like to try and handle this matter in a more discreet manner. We''ll offer a substantial reward to anyone that cares to pay these smugglers a visit and show them the effectiveness of the working end of a blaster. No names are necessary. We''ll provide you the coordinates and insure that payment is made into your account when the job is complete. How about it? You think you could handle some extra cash?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 162, 'm41o', 'A Simple Businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 163, 'm41s', 'Well done. Your account will be credited. Do look us up in the future.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 164, 'm41t', 'Help a businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 165, 'm42d', 'I was warned not to go with the cheapest rate when it came to smuggling, but did I listen? Now I''m in this position of having to pay someone to take care of the problem caused by going with the bargain smuggler. Those are two words that should never go together, huh? "Bargain" and "smuggling." The deal is the usual one, of course. I pay a reward for having someone take this cheap swindler and their base out and you are the someone that either accepts or declines the offer. If you accept, the coordinates to this slug''s base will be transmitted to you. If you decline, our business is concluded. So which will it be?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 166, 'm42o', 'A Tired Businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 167, 'm42s', 'Good work, good job, and all that. Your reward will be sent to your account. I''m sure you''re thrilled.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 168, 'm42t', 'Take out the bargain smuggler'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 169, 'm43d', 'Oh, I hope I''m doing this right. Okay, here goes... \n\nHello. I''m looking for someone brave and enterprising. Oh, and good-looking wouldn''t hurt either. Although it''s not really necessary for this mission. I just prefer good-looking people. Well groomed, at the very least. Anyway, I need someone with the aforementioned qualities to find a very bad person for me. Find them and teach them a good lesson. You can even burn their base to the ground. I prefer that, actually. This scoundrel cheated my family out of a lot of money. Made my father sick, as a matter of fact. My poor father, he''d just die if he knew I was doing this. But it has to be done. I rely on the discretion of whomever accepts this assignment. And if you do accept, I''ll tell you where to find this nerf-herder. I hope you accept. Oh, and you don''t really have to be good-looking or well groomed. I was just being silly. Okay, thanks. Talk to you soon. I hope.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 170, 'm43o', 'An Indignant Woman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 171, 'm43s', 'Wonderful! I knew you could do it! I''m so happy. My family thanks you. Good job! Oh, I need to pay you now, huh? Okay, I''ll do that. My hero.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 172, 'm43t', 'Avenge a wronged family'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 173, 'm44d', 'Let''s get down to business. I give you the location of some former business associates, you burn their hangout to the ground and make sure no one lives to tell the tale, and I pay you lots of credits for your trouble. Only serious professionals need apply. You in?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 174, 'm44o', 'An Impatient Businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 175, 'm44s', 'Did the job, collect the credits, see you around.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 176, 'm44t', 'Conclude a small business deal'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 177, 'm45d', 'The Rebellion might have been crushed by now if not for the activities of these smugglers. They''re a thorn in the side of the Empire and must be stamped out. The Imperial Military has their hands full trying to track dangerous terrorists down so we must rely on the loyalty and patriotism of Imperial citizens to help wipe out this smuggler menace. Our contacts with Imperial Intelligence have fortunately allowed us to acquire the locations of several smuggler bases. A substantial reward awaits the successful destruction of these bases. Can the Empire count on your help, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 178, 'm45o', 'COMPNOR'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 179, 'm45s', 'A successful strike against the smugglers is a blow against the Rebellion, citizen. Bravo. The reward is yours.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 180, 'm45t', 'Be a good Imperial citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 181, 'm46d', 'Smugglers? No sir, don''t like ''em. In fact, I don''t like ''em enough to offer a reward to anyone brave enough to wield a blaster against those space slugs. My contacts in the Imperial Transport Authority has given me access to the locations of some suspected smuggler lairs. The Empire''s too busy playing war with those Rebels to really do anything about these bases and we''re terribly understaffed (and underpaid, I might add). So why am I doing this? Well truth be told, I lost my wife to one of these scoundrels. Now I want some payback, ya hear? So, you in or out?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 182, 'm46o', 'An Angry Civil Servant'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 183, 'm46s', 'That''s showing ''em. I bet those smugglers didn''t know what hit ''em. Way to go. The reward''s yours.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 184, 'm46t', 'Correct an injustice'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 185, 'm47d', 'We''re tired of smugglers posing as legitimate transport captains and taking away our business. So many clients have started relying on organized transport guilds rather than on freelance pilots because they think every independent pilot is actually a smuggler and they don''t want to risk having their shipments seized. Well we''ve followed some of these smugglers and have located several of their bases. We''re not soldiers, though, so we need someone to go into these bases and blow them to atoms. We''ve pooled together a decent amount of credits to serve as a reward. Do you think you have the stomach and the wherewithal to pull off a mission like this?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 186, 'm47o', 'Independent Transport Pilots'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 187, 'm47s', 'Good job, citizen. You ever consider doing this professionally? You''d make a pretty decent crime fighter. '),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 188, 'm47t', 'Help independent transport pilots'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 189, 'm48d', 'I used to be a Police Prefect on Tatooine. That is until I lost my job due to the activities of several traitorous smugglers. We had a system. It was all worked out. But some people have to buck that system. They''re not happy with the status quo. Well if my career is ruined then so will those smugglers'' careers. I''m offering a generous reward to anyone who will obliterate those smugglers'' bases and make sure they never trouble another prefect again. If you accept, I''ll transmit the coordinates to you. You''d better go in shooting first and asking questions later. If you even get to the questions part, that is.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 190, 'm48o', 'A Disgraced Former Prefect'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 191, 'm48s', 'Now those are results you can take to your superiors. Good work! Keep at it. There''s plenty more where this reward came from.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 192, 'm48t', 'Destroy smuggler bases'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 193, 'm49d', 'I was a legitimate businessman, obeying all the Imperial laws and ordinances and working hard to raise a family. Until the day a smuggler, posing as an independent transport pilot, came into my life and ruined everything I had worked so hard to get. I lost my business, my family, and my self-respect. Well I intend to get that last bit back. I''m offering a reward, everything I have left, to anyone who can make sure this smuggler doesn''t ruin any other honest, hard-working businessmen. I know where that damn smuggler hides, you see. They think they''re safe but we''ll soon show them how wrong they are. Can you help a man regain his self-respect, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 194, 'm49o', 'A Desperate Man'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 195, 'm49s', 'Well struck, citizen! Haha! Take that, you dirty, rotten smuggler! Take the reward, citizen, you''ve earned it. My self-respect is restored thanks to you.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 196, 'm49t', 'Help the disgraced businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 197, 'm50d', 'I knew you would look at this offer, citizen. You know why? Because I''m the Emperor! Yes, that''s right. And now you are my willing minion. What do I require of you, you ask? Well it seems that some of my minions are not as obedient as you. They have decided it would be amusing to betray their Emperor. Now they will pay the price for their lack of vision. And you, my young apprentice, will be the instrument of their demise. Hahahahaha! You will receive my generous gratitude in addition to some form of lucre. Who knows, if you perform up to my standards, I may call you to Imperial Center and appoint you as one of my advisors. I know that would please you. Will you take your place at my side?'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 198, 'm50o', 'The Emperor (Honest)'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 199, 'm50s', 'Excellent! Everything is proceeding exactly as I have foreseen it. You will rise quickly in my estimation, young apprentice. Keep it up.'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 200, 'm50t', 'Help a deranged citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 1, 'm1d', 'You, friend, you will be my absolute best buddy if you take care of this one little thing. I make, you know, intoxicants? Not exactly the totally legal kind? And it''s been good, it''s been good, but this kind of business attracts all kinds of the wrong people. And they''ve been sort of, well, leaning on me, asking for a cut of my profits or they''ll inform the Empire. It''s such a hassle. It''s not my style to lean back, but hey, I have to get these guys off my balance sheet. Or get somebody else to do it. Understand me?'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 2, 'm1o', 'Corellian Eager to be Your Friend'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 3, 'm1s', 'That is truly good news, friend. I tell you, you are my truest buddy in the world right now. I''m sure we''ll be in touch again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 4, 'm1t', 'Get These People Off My Back'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 5, 'm2d', 'One evening I was doing my usual business in downtown Coronet, and I approached a tall woman standing at a bar. I don''t know what happened to me then, but when she looked at me, I suddenly didn''t want to sell her death-sticks any more. I wanted to go home and rethink my life. Since then I''ve been thinking a lot. I''ve decided I have to stop the sleazebags who pump this poison into our society! I was just the seller, the pusher, but these guys do the actual manufacturing. I know their factory, and I''ll pay you to wipe it off the face of Corellia!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 6, 'm2o', 'Corellian Rethinking His Life'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 7, 'm2s', 'That''s really great news. Somehow I think that woman I talked to in the sports bar would be happy. Here''s your money. Now I have to go rethink my life some more.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 8, 'm2t', 'Wipe Out Corellian Death-Stick Factory'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 9, 'm3d', 'I''m a producer in Children''s Programming. The star of our "Darth Spooky''s Sinister Dark Side Theater" afternoon show has been dealing with a longtime glitterstim problem. He says his old suppliers are coming around, trying to tempt him back onto the stuff. We''d all rather keep this out of the newsfeeds, so rather than go to the police, we''re seeking a private solution to the criminal problem. If you''re discreet and can handle a fortified gang installation, contact me for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 10, 'm3o', 'Corellian Public Broadcasting Executive'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 11, 'm3s', 'What a relief. It''s hard enough keeping Darth Spooky''s hood down over his eyes when he''s shaking with withdrawal. We''ll keep him on track now. Here''s your fee.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 12, 'm3t', 'Rescue Glitterstim Addict'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 13, 'm4d', 'I run Corellia''s leading landspeeder repossession company. Recently yet another gang of goons rammed our main building. This gang used modified Ubrikkian Talon I combat cloud cars -- a nice model, by the way, very good on the resale market. As always, the gangsters rampaged through our offices, shooting people and shouting, "Repo slimes are lying scum!" (which, by the way, is an unfair characterization of our work). Now, I understand that passions can run high when a customer''s vehicle is repossessed, but hiring a gang to enact petty revenge is always out of line. (I also wonder, by the way, how such customers find money to hire a gang when they couldn''t make their speeder payments!) But I''ve found that it''s good practice to eliminate these gangs so they can''t do this again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 14, 'm4o', 'CEO of Corellian Vehicle Reclamation'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 15, 'm4s', 'You''ve done a great, great job. And I don''t say that to just everyone, by the way. Now I have to track down the customer who hired this latest batch of goons.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 16, 'm4t', 'Stop Rampages Through My Office'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 17, 'm5d', 'I run Corellia''s leading landspeeder repossession company. Now and again I deal with people who, shall we say, don''t emphasize bureaucratic recordkeeping. If they don''t happen to fill out tax reports or check the stolen-vehicle registers, that''s not my business. Recently, as often happens, a certain group of these people took issue with the quality and provenance of the vehicles I sold them, and have made forceful threats against my offices. I have always taken a hard line against troublemakers. I commission self-starting, go-getting representatives to go to these people''s bases and teach them a hard lesson in honest dealings. Are you up to this assignment?'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 18, 'm5o', 'CEO of Corellian Vehicle Reclamation'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 19, 'm5s', 'You''ve done a great, great job. And I don''t say that to just everyone, by the way. Gotta get back to work, thanks.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 20, 'm5t', 'Threats Against Repossession Company'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 21, 'm6d', 'Our business is selling fireworks, although the market has been so tough that nobody''s bought fireworks for, oh, ten or fifteen years. So we buy and sell certain other things, and do a decent business. Recently we delivered certain valuable non-firework commodities in a remote area, and the recipients neglected to pay us. Very firmly neglected, we might add, as evidenced by the charred remains of our collection agents. We fireworkers disapprove of this. We''re giving our entire fireworks production budget, which we no longer use, to the first individual who can teach these recipients a lesson in honesty. Very firmly teach them, we might add.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 22, 'm6o', 'Corellian Fireworks Transport'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 23, 'm6s', 'A fine job. We could use more people like you in the fireworks business.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 24, 'm6t', 'Help Fireworks Dealer Educate Customer'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 25, 'm7d', 'Bop Thrombo the Shaky Droid pulls in a small local audience of a few hundred million viewers, but he''s been trying to break into the galactic big time. To endear himself to a powerful agent, Bop did some embarrassing things he''d rather not describe. Too late, he found the "agent" was a fake, and incriminating holo recordings fell into the hands, or tentacles, of blackmailers. Bop got steamed, and -- what a spunky droid! -- went after them in their lair. Unfortunately they blew him to bits; we got it all on his built-in surveillance cam. Great footage, but now we really need to recover Bop''s brain. To do that, we need someone to clear out the gangsters first. Are you willing?'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 26, 'm7o', 'Corellian Sector Newsfeed'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 27, 'm7s', 'Great! We''ll send out a news crew to re-house Bop Thrombo''s brain and get his personal account of his crimefighting exploit. Clear out before we get there, please.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 28, 'm7t', 'Rescue Brave Bop Thrombo''s Brain'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 29, 'm8d', 'You haven''t had real gangster trouble until you''ve met gangsters in the blasted, brain-draining, spirit-deadening Agrilat Swamp of Corellia. That place is a pit. I know the tourists like the crystalline undergrowth, but that''s because they don''t have to pull the shards out of their boots when they''re running for their life from slavers. I got out. I''m never going back. But now that I''ve made some credits buying and selling certain Imperial "involuntary surplus goods," I''m hiring someone with a good sidearm to mete out some revenge. I don''t know exactly where those creeps are based now, but if you head into the Agrilat Swamp, be sure you''ve got good boots.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 30, 'm8o', 'An Agrilat Swamp Refugee'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 31, 'm8s', 'Thanks, friend! That was some fancy demolition. It warmed my heart to see it, and here I thought nothing could warm my heart after all that time in Agrilat Swamp.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 32, 'm8t', 'Catch Gangsters From Agrilat Swamp'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 33, 'm9d', 'Almost home after a Kessel run, we ran into Imperials and crash-landed. Things went rapidly downhill after that. Aside from some creature trouble that forced us to drop our cargo, we also had an internal saboteur. After we got back home, we discovered encrypted communications between our ship''s engineer and a rival smu-- courier team. We tracked the engineer to a smuggling base outside town, but it''s too well defended for us. We''ve gained a certain amount of new funding through insurance. We''re devoting a portion to anyone willing to teach our engineer and his buddies a lesson in honesty.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 34, 'm9o', 'Corellian Travellers Looking for an Acquaintance'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 35, 'm9s', 'Thank you. There is not much honesty in our line, but you''ve helped us do our part to increase the overall integrity level of our profession.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 36, 'm9t', 'Help Beat Folks Who Stole Our Cargo'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 37, 'm10d', 'The south side of Bela Vistal is, in my view, the worst part of town. If you go down there, you''d best be wary of a Dug named Lero Bown, the worst gang leader in the whole city. He''s a gambler who likes his fancy clothes and waves his gas-gem rings in everyone''s face. He owns a custom XP-38 landspeeder, and carries a Corellian Arms CR-2 blaster in his pocket and a vibroblade in his vest. One night not long ago, at a sabacc game at a cantina, Lero saw a female Dug named Darplimpa sitting at the bar. Lero grew enamored of her, and his flirtations provoked Darplimpa''s jealous mate. When the fight went badly for Lero, he fled town, promising revenge. We on the city council wish to pre-empt his violent return. We are covertly hiring well-armed adventurers to strike Lero''s headquarters and destroy his gang.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 38, 'm10o', 'A Bela Vistal Councillor'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 39, 'm10s', 'A fine assault. Lero Bown has certainly learned a lesson about meddling with the betrothed of a jealous Dug. I attach your fee.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 40, 'm10t', 'Bad Gang Leader Attacking Bela Vistal'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 41, 'm11d', 'While shipping cargo offworld, I had a run-in with some pirates. I know you''ll agree it''s not productive to get sidetracked by issues of "who blew up whose starship." The point is, these crooks, or their heirs and surviving coworkers, have a serious mad on, and I''m their target. According to the usual script, I''m supposed to flee offworld and live my life as a hunted fugitive. What a drag. I have a different idea: You go and blow up their base, and I''ll pay you well for getting them off my back. Hey, what could go wrong?'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 42, 'm11o', 'Corellian Just Trying to Live His Life'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 43, 'm11s', 'That was some fancy action, friend! I hope none of those pirates had friends, or we''ll be going through this little spat again. Thanks, contact you soon.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 44, 'm11t', 'Not My Fault Their Stupid Ship Blew Up'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 45, 'm12d', 'Existing tax and tariff structures are hampering Corellia''s ability to supply interested parties with that vital luxury good, Double Brandy. The way I see it, I provide Double Brandy to folks who wouldn''t otherwise get it, often at a lower price than official channels permit. In this way I''m creating happiness and stimulating the economy. A new smuggling gang recently crawled onto the scene, forcefully insisting that my trade routes belong to them. I feel these people have no real interest in Double Brandy as such, and hence don''t deserve to service my customers. I''m hiring you to convince them of this, permanently.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 46, 'm12o', 'Dealer in Corellian Double Brandy'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 47, 'm12s', 'I raise my glass in a toast to you, my friend. The true champion of Double Brandy will go to great lengths to bring it to customers. Thank you!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 48, 'm12t', 'Protect Double Brandy Supply Routes'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 49, 'm13d', 'Masternav, renowned for some of the best astrogation maps in the galaxy, faces a grave threat. Gangsters based in the remote wilderness have fired warning shots at our droidships as they return from survey missions. Extortion attempts followed shortly thereafter, demanding payment to "protect" our valuable ships. This company takes a hard line against criminals. In the absence of adequate police involvement, we are commissioning an independent agent to destroy the gangster base and protect (in the honest meaning of the word!) our astrogation ships.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 50, 'm13o', 'Corellian Masternav Incorporation'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 51, 'm13s', 'Masternav thanks you for your good work in protecting our droid surveyors. Astrogation work continues uninterrupted, thanks to you.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 52, 'm13t', 'Astrogation Surveyor Ships Attacked'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 53, 'm14d', 'Because millions of native-born Corellian merchants across the galaxy depend on our services, the Guild constantly updates its shipping safety reports. The "lift-and-land" survey describes pirate hazards during takeoffs and landing on Corellia and other notable trade worlds along the Corellian Trade Spine. For the latest update, we are tracking reports of unidentified installations seen in remote areas. To participate in our current research cycle, please report to the attached coordinates to engage and destroy any criminals present. Guild hovercams will record the event, and we shall update our guidelines based on our assessment of the threat posed.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 54, 'm14o', 'Corellian Merchants'' Guild'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 55, 'm14s', 'Our hovercams recorded the event, and we are updating our guides accordingly. Thank you for participating in this research cycle.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 56, 'm14t', '"Lift-and-Land" Crime Survey'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 57, 'm15d', 'When you employ some untrained rube from offworld to move your goods, you can''t count on the high standard of smuggling long established by native-born Corellians. The offworld-funded Open Shipping Consortium, which brings in every hayseed Outlier farmboy with a joystick and hires him out as a "smuggler," is now aggressively targeting the local market for Jorallan pearls and opals. The Corellian Discreet Shipping Industry Chamber of Commerce opposes this alien incursion. We have found their rural receiving depot. Because it falls far short of the Chamber''s rigorous safety standards, we ask you to destroy this menace to public safety.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 58, 'm15o', 'Corellian Discreet Shipping Industry Chamber of Commerce'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 59, 'm15s', 'Your successful demolition of the sub-par Open Shipping depot is good news for our cause of maintaining high standards in the discreet-shipping industry. Your payment is attached.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 60, 'm15t', 'Open Shipping Takeover of Jorallan Gems'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 61, 'm16d', 'You really have to see a beautiful Jorallan pearl or opal to appreciate it. Who wouldn''t want one? But if you feel like smuggling one onto Corellia, under the high-handed Corellian Discreet Shipping Industry Chamber of Commerce monopoly, you''ll pay a lot and likely deal with some calcified veteran who''ll tell you he''s forgotten more about smuggling than you''ll ever know. That''s the trouble! He''s forgotten it all! In the Open Shipping Consortium we believe in free smuggling for free smugglers. If you agree, help us by wiping out the monopoly CDSICoC Jorallan landing depot at these coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 62, 'm16o', 'Open Shipping Consortium'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 63, 'm16s', 'Yes! Jorallan gemstones for all the people! Another step on the path to free smuggling for all Corellia!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 64, 'm16t', 'Make Corellia Safe For Open Shipping Gems!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 65, 'm17d', 'When you''re moving something as delicate as Endorian wind-crystals past Imperial Star Destroyers, you need a native Corellian smuggler, not some halfwit offworlder who arrives from the Outer Rim and two heartbeats later gets dumped straight into a freighter cockpit. The discreet-shipping industry demands high standards in the movement of fragile wind-crystals. Yet now the offworld-funded Open Shipping Consortium has opened a new depot in the remote wilderness, far from the experienced eyes of Corellian quality-assurance supervisors. Imagine these priceless crystals shattering in this unsupervised pit. To protect these fragile masterpieces, we implore you to destroy the depot at once.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 66, 'm17o', 'Corellian Discreet Shipping Industry Chamber of Commerce'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 67, 'm17s', 'We congratulate you on your successful demolition of the substandard Open Shipping depot. Together, we will march forward in the cause of maintaining high standards in the discreet-shipping industry. '),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 68, 'm17t', 'Open Shipping Menace Moves to Wind-crystals'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 69, 'm18d', 'If you want wind-crystals smuggled from Endor to Corellia, who can help you? The hidebound, speciesist Corellian Discreet Shipping Industry Chamber of Commerce monopoly would like to lock you in at their overblown rates. In the Open Shipping Consortium we work for freedom to smuggle by anyone, anywhere, at an affordable price. To break the shackles of the CDSICoC, to land wind-crystals safely so all Corellians of all species can enjoy them, we urge you to destroy the monopoly wind-crystal landing depot that is strangling our illegitimate trade!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 70, 'm18o', 'Open Shipping Consortium'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 71, 'm18s', 'A strike for the people, friend! This marks another step on our inevitable path to victory. Free smuggling for all!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 72, 'm18t', 'Open Shipping Breaks Wind-crystal Monopoly!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 73, 'm19d', 'Because Lowickan firegems can cause reactor explosions when a ship enters hyperspace, the discriminating Corellian smuggler handles them according to safety standards described by the Corellian Discreet Shipping Industry Chamber of Commerce. But if you put some illiterate Outer Rim hick at the controls of a YT-1300 freighter, as the offworld-funded Open Shipping Consortium advocates, disaster may strike. A firegem merchant must now contend not only with Imperial blockades, but also with the likelihood of shoddy Open Shipping handling of extremely delicate merchandise. To lessen our clients'' worried uncertainty, we request that you destroy the new Open Shipping firegem receiving depot.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 74, 'm19o', 'Corellian Discreet Shipping Industry Chamber of Commerce'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 75, 'm19s', 'All substandard Open Shipping Consortium facilities earn the strong disapproval of our organization. With your help, we shall continue to enforce our recognized high standards in the Corellian smuggling industry.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 76, 'm19t', 'Open Shipping Menaces Firegem Trade'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 77, 'm20d', 'Very handy, isn''t it, that you can''t get a Lowickan firegem onto Corellia without running afoul of, not only the Empire, but also the monopolistic Corellian Discreet Shipping Industry Chamber of Commerce. It''s this short-sighted restraint of free trade that makes firegems so sought after. If folks could get them from any Open Shipping Consortium smuggler at a fair price, firegems would lose their cachet. No one would think them special. People would be less concerned about these gems''s beauty and internal warmth, and more about how the gems can accidentally destroy a hyperdrive. To promote greater public safety awareness, we urge you to strike a blow against CDSICoC lock-in by destroying their firegem receiving depot! Firegems to the people!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 78, 'm20o', 'Open Shipping Consortium'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 79, 'm20s', 'The cause of free smuggling must triumph, thanks to good workers like you. Death to the CDSICoC monopolists!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 80, 'm20t', 'Firegems Strangled by CDSICoC Monopoly!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 81, 'm21d', 'I am, how do you say, documentary holographer from far away -- I look for big break, get to Core Worlds. I am here to Corellia, seek very-big Twi''lek adventure-man O-i. My crew of the droids, they get very-good holos of O-i, he fight an Imperial garrison, use only holdout blaster and one canister laughing gas. Crew of the droids was send me holos, but oh no! Bad people, how do you say, "crooks"?, stole crew of the droids and also hovercams. I have nothing. I want O-i holos! I find crooks with droid track beacon. You go to very-big crook place, kill-kill everybody, get holos! OK?'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 82, 'm21o', 'Holographer from Outer Rim Territories'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 83, 'm21s', 'You do kill-kill, but no holos? Oh, very-bad! I need holos! O-i goes from Corellia long ago now. I must start over. I do not pay you, I push the "no" button. No, wait -- oh, I push wrong button, you get money anyways! Oh, no. Maybe I go back home, maybe.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 84, 'm21t', 'Please to Help Recover O-i Holos'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 85, 'm22d', '[Translated from Selonian:] I serve the Fertile Prosperity den in a remote area of Corellia. Recently offworlders set up a den near our own. We believe they are not planning an attack, but instead are moving manufactured goods between cities and space for criminal purposes. Their goal is irrelevant to us, but their movements endanger our young. This is unacceptable. The city law agents offer no help. We will give Corellian credits if you destroy the offworlder base. Leave our den unharmed.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 86, 'm22o', 'Fertile Prosperity Den, High Leader Sept'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 87, 'm22s', '[Translated from Selonian:] We are grateful for your service to our den. We pay you the credits as we agreed.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 88, 'm22t', 'Selonian Den Endangered'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 89, 'm23d', '[Translated from Selonian:] In the Transposed Sunrise den here on Corellia we own one hand-built Selonian coneship. Recently surface-dwellers of unknown den and breeding took our ship in the night without approval. The queen sent me out to track the ship. I followed the [untranslatable] signal and found the ship. Surface-dwellers are dismantling it. City law agents move too slowly. We require quick destruction of the surface-dweller den. We will pay Corellian credits to you for this task.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 90, 'm23o', 'Transposed Sunrise Den, Inaugural Sept'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 91, 'm23s', '[Translated from Selonian:] We are grateful. We are recovering the remains of our ship now. [Ceremonial blessing.] Here are your credits as we agreed.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 92, 'm23t', 'Selonian Coneship Stolen'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 93, 'm24d', 'The aging Aqualish gang leader Dovor Dowwn is facing challenges from his underlings. Those tuskers hate showing weakness, you know, but he can''t pretend much longer; he''s just getting too long in the tooth. Mindra, one of Dowwn''s lieutenants has gone renegade, setting up covert smuggling depots. She''ll use these depots as a power base to seize Dowwn''s Corellian trade. Dowwn just found out about one of Mindra''s renegade depots, and after he threw a few tantrums, he ordered it destroyed. Here''s why I''m asking your help: I have mining interests near Mindra''s depot. If the Aqualish lets loose all his firepower, I could take collateral damage. I''ll pay you to destroy Mindra''s depot, with minimal damage to the surroundings, before Dowwn gets to it.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 94, 'm24o', 'Janqual Mor, Coronet Mining Corporation'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 95, 'm24s', 'Good work. Very neat rubble, with minimal collateral damage. I''m sending your fee with this note. This situation may arise again, so be ready.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 96, 'm24t', 'Gang War Threatens Mining Interests'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 97, 'm25d', 'For too long has legitimate Corellian commerce suffered the hair-trigger temper of the Aqualish gang leader Dovor Dowwn. His smuggling operation has drained our world''s coffers of legitimate tax income, leading to a weakened economy and loss of jobs. I beseech all honest adventurers to assail Dowwn''s many smuggling depots and bring down his corrupt operation! [INTERRUPT] Hi hi, scuse me for slicing Mindra''s transmission. Emmin Whitehat, thass me, spreader of truth. Mindra Nox was Dowwn''s lieutenant (she reeeally thinks you don''t know that???). She wants to take over his smuggling stuff. OK just thot you like to know haha. [END INTERRUPT, TRANSMISSION RESUMES] Though uninvolved myself in this sordid matter, I am moved by a sense of charity to offer a reward for successful assaults. Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 98, 'm25o', 'Mindra Nox, Corellian Entrepreneur');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 99, 'm25s', 'Thank you. I need to ask, was there anything odd about the text of my assignment? I''ve had slicer troubles. I''m compiling a list of grievances, and that slicer will eventually answer for all of them.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 100, 'm25t', 'Stamp Out Dowwn''s Operation'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 101, 'm26d', 'Gaah! You''d think someone, somewhere, one single little individual in this great big galaxy, would show gratitude just once. But no! That ungrateful human Mindra Nox, with her insipid square white teeth in her disgusting rubber-lipped red mouth-opening, has taken all the wisdom I taught her -- all the crew and equipment I assigned her -- and revolted! She''s setting up her own secret bases, and she thought I wouldn''t find out. Stupid, beady-eyed, dimwitted human! As it happens, I''m distracted with other business offworld right now, but don''t think I can''t squash her like a bug. For convenience, I''m willing to pay freelance scum to dispose of Mindra''s latest pathetic little hovel.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 102, 'm26o', 'Dovor Dowwn, Aqualish Businessbeing'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 103, 'm26s', 'All right, all right, so you destroyed a base. You expect me to slobber all over you in gratitude? Take your money. I''ll call if I need more help -- not that I will, mind you!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 104, 'm26t', 'Traitorous Backstabbing Betrayer '),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 105, 'm27d', 'I''ve had endless trouble with a rogue Corellian slicer who calls himself Emmin Whitehat. He''s cost me a lot of trouble -- a LOT -- but I''ve finally located the sleazy little compartment he calls home, and I''m paying very good money for you to take him out. [INTERRUPT] Thass right, lady, I so scared right here where you find me! Ready & waiting haha! OK love & kiss, Emmin [END INTERRUPT, TRANSMISSION RESUMES] Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 106, 'm27o', 'Mindra Nox, Corellian Entrepreneur'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 107, 'm27s', 'You fool, you destroyed one of my own installations! That verminous Whitehat corrupted my coordinates. And now I see that he''s deducted your fee from my accounts. Well, he can play his pranks, but I''m keeping a tab for what he''s cost me. I don''t forget.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 108, 'm27t', 'Criminal Slicer Emmin Whitehat'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 109, 'm28d', 'Humans make me sick. First, when I see their perversely smooth faces and the weird, bushy colored filaments covering their scalp, it''s all I can do to avoid retching in my tusks. Just as bad as their ugliness, though, and their insipid mild nature -- oh, and their obnoxious rubbery lips, those make my gorge rise -- just as bad is their traitorous nature. "You can''t trust a human" -- my creche-mom always said that. I never believed her, because she was a stupid shaak-brain, but I should have! I should have! This human who worked for me, Mindra Nox, has taken my people and equipment and set up her own smugg-- business operation! Treachery! Stop wasting your time reading your stupid datapad and go destroy her!'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 110, 'm28o', 'Dovor Dowwn, Aqualish Businessbeing'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 111, 'm28s', 'The unmitigated gall of that stupid human. It makes me want to vomit. I hate them all. Take your money, get away from me.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 112, 'm28t', 'Nox''s Treachery Knows No Bounds'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 113, 'm29d', '[INTERRUPT] Hi hi, Emmin Whitehat atcha. I a slicer (like you couldn''t tell???) doin a little spoofy of smuggler and crimelord (she wishes!!!) Mindra Nox. Mindra and I go waaay back, now I move waaay forward to fix her crookiness. Like for instance she kissed off (ugh!) her old boss Dovor Dowwn The Obnoxious Aqualish to set up smuggling places of her own (you didn''t know that???). So OK here is the deal. I took credits from her accounts (she is gonna shriek!!!) & I pay them to you if you blow up her new base real good haha. Why ask why??? [END INTERRUPT, TRANSMISSION ENDS]'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 114, 'm29o', 'Mindra Nox, Corellian Entrepreneur'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 115, 'm29s', '[INTERRUPT] OK Emmin here not Mindra (but you knew that!!!). You did OK there lots of damage. I saw from hovercam overhead. I give you Mindra''s money, be sure to tell her where you got it haha!!! [END INTERRUPT, TRANSMISSION ENDS]'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 116, 'm29t', 'Stop Evil Slicer OK (Yeah Right!!!) Haha'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 117, 'm30d', 'A mother doesn''t like to pry, but when my dear son Hartliss gets himself into trouble, I can''t help myself. I''ve just got to stick my nose in. You see, Hartliss is a contract spacer who runs the Spine when he needs money. I always tell him he''s got to be careful who he travels with. Heavens knows there are hooligans in the galaxy who can turn a good boy into a criminal. Like this last crew he freighted with. A pack of gundarks, that''s what they are. Tried to tempt my poor little boy with death sticks. Now that Hartliss is offworld on another run, I can finally do something about these immoral rapscallions. I sent a seeker droid to follow them. Found out that every night they gather in a little cantina outside of town. Now I just need some brave spirit to tiptoe down to that awful place and blast those scum-grubs into a billion subatomic particles.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 118, 'm30o', 'A Loving Mother'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 119, 'm30s', 'Now that was really satisfying, wasn''t it? I told my son Hartliss he should blast the place himself, but he called me a busybody. Do you think I''m a busybody? I just want what''s best. My little Hartliss deserves all the love I can provide.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 120, 'm30t', 'Hartliss Needs Some Help'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 121, 'm31d', 'What happened to the peaceful Corellia of our forefathers? It''s not bad enough that our sector is full of smugglers and Rebels. Now we''ve got a tide of death sticks and glitterstim pouring into the countryside. Well, some of us in the grasslands refuse to let this corruption take root. We''ve tagged several illegal spice dens across the surface of the planet, and collected enough credits to pay for their demolition. All we need is a good citizen who possesses the wherewithal to knock down these hives of villainy and make sure none of the dealers come back. Our list of coordinates is long, sadly, but we can shorten it with the help of some stalwart demolitionists.  Interested?'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 122, 'm31o', 'Concerned Corellian Citizens'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 123, 'm31s', 'That will teach those spice dealers not to bring their poison where decent Corellians live! We''ve got plenty more dens on our list, my friend, if and when you''re ready to work again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 124, 'm31t', 'Demolish Illegal Spice Dens'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 125, 'm32d', 'The Null Racket is the fastest Corvette in the sector. That kind of speed don''t come without work. A while back I custom ordered an ion impeller from a shipyard in Brak Sector. Too bad on the way to Corellia, it found its way into the hands of a competitor of mine. That''s just not friendly, is it? I''m betting a small sum of credits will convince this competitor to reconsider stealing from me. That is, if I use the credits to hire someone to burn his den of two-credit thieves to the ground. I don''t suppose you''d be game for the job? Don''t worry about the impeller. I''ve got another on the way, with a couple of Trandoshan guards this time. You just do this job well and you''ll make a name for yourself on Corellia.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 126, 'm32o', 'Captain Sava Matar of the Corvette Null Racket'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 127, 'm32s', 'You do good work. I''ll keep you in mind if I get another blaster job. Ol''val.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 128, 'm32t', 'Incinerate Unfriendly Competitor'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 129, 'm33d', 'Running the fastest Corvette in the sector ain''t like baking fringe cake. Competition can be downright savage in the Corellian freight business. You''ve got to keep your eyes open. Sometimes you''ve got to crank the turbines on a competitor when they start interfering with your livelihood. That''s where you come in, friend. If you want to earn a couple of credits today, I need you to put the hurt on a colleague of mine who tried to hand over the Null Racket to Imperial authorities. He doesn''t know I''m onto his double-cross, so he shouldn''t be expecting any trouble. Just to be sure, though, bring your best weapons. Dust the whole place and you''ll get a cut of my latest haul. Ol''val, min dul''skal, ahn guld domina.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 130, 'm33o', 'Captain Sava Matar of the Corvette Null Racket'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 131, 'm33s', 'Where did you come from, friend? You''re good. I''m going to remember your name. Ol''val.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 132, 'm33t', 'Dust a Double-Crosser'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 133, 'm34d', 'Ever seen an ugly fly? Trust me, you don''t want to. Uglies are rattletrap fighters welded together out of whatever space debris their builders can scavenge. They''re constructed for firepower, not for endurance, and they''re used as raiders and duellers. Uglies are a thorn in the side of the CDF. We''ve got a standing reward for anyone who shuts down one of the shops that put these jalopies together. Let us know if you''re interested in the job and we can send you the coordinates of a suspected ugly shop. Good luck.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 134, 'm34o', 'Corellian Defense Force'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 135, 'm34s', 'Good work. The fewer uglies that pester our space lanes, the more attention we can give to real problems in this sector.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 136, 'm34t', 'Uglies Are a Thorn in Our Side'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 137, 'm35d', 'As a Trandoshan, it is my duty to collect jagannath points by hunting dangerous prey. The problem, however, is that I''m a colossal coward. It''s only been due to the enormous wealth my father managed to accumulate during the enslavement of the Wookiees that I''ve been able to bribe my way through every single rite of passage sacred to my people. Unfortunately, a few less-enterprising inhabitants of Dosha have condemned my approach to our traditions. They''ve tracked me to Corellia and want my head at the end of a thrar''kor. I need to funnel some of my family''s wealth into stopping these brutes before they catch me, which can only have unpleasant results. If you blast my enemies to atoms, I''ll pay you well, and everyone will be happy. Do we have a deal?'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 138, 'm35o', 'An Anonymous Trandoshan'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 139, 'm35s', 'Excellent work, except that I sent you to the wrong place. My pursuers were not among the beings you attacked. Never mind, though, I''m sure they got the message. That''s the important thing. Take your payment, and may the Scorekeeper record your brave deed.'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 140, 'm35t', 'Help a Cowardly Trandoshan'),
('string/en/mission/mission_destroy_neutral_medium_npc_corellia.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 1, 'm1d', 'Stealing shaaks from a small family barely scraping by -- that''s just low! Worse than slaving, worse than smuggling, worse than -- well, not worse than blowing up Alderaan, but still pretty bad. We''re down to our last credits because of these poachers, and now we have to spend those credits hiring you to stop them. Careful -- they''re well armed and dangerous.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 2, 'm1o', 'Shaak Herder on the Great Grass Plains'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 3, 'm1s', 'Sounds like they already disposed of the stolen shaaks. But with the births coming up, we may be able to replenish our herd fast enough to survive. Thanks for disposing of those despicable lowlifes.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 4, 'm1t', 'Shaak Poaching -- Galaxy''s Worst Offense'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 5, 'm2d', 'Kirkhorn, the third-oldest guarlara stable on Naboo, has an enviable reputation. Envy has now escalated to criminality. Recently, rustlers destroyed our pasture alarm systems and stole Zenith Dancer, a thoroughbred champion. His implanted tracking chip has pinpointed their location. Security forces are occupied elsewhere, so we''re asking for quick action from an experienced agent. Destroy the rustlers and save Zenith, or this will happen again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 6, 'm2o', 'Kirkhorn Guarlara Stable'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 7, 'm2s', 'Good news! While you were dealing with the rustlers, Zenith escaped and galloped back home. It''s time to celebrate here at Kirkhorn. Here''s your fee, and thanks!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 8, 'm2t', 'Guarlara Rustlers Steal Champion'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 9, 'm3d', 'Gangsters have stolen funds earmarked for the upcoming Midseason Euphonial Festival. You may recall that this important event marks the premiere of Sandelratha''s "Emperor Symphony." To bring in Imperial Security would be politically indelicate, so we prefer to hire an independent agent to track and destroy these gangsters. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 10, 'm3o', 'The Office of the Music Advisor of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 11, 'm3s', 'With evidence from the destroyed camp, we can track the stolen funds. Thank you for your prompt action to protect the Euphonial Festival.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 12, 'm3t', 'Midseason Euphonial Festival In Doubt'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 13, 'm4d', 'The Twi''lek tellisatura diva Niral Dassacrin has performed the Nicol Bondot gaze-opera "Singularity Song" to sellout audiences. But Niral has run afoul of gangsters, who have extorted funds from her by threatening to cut her vocal chords. She belatedly confessed all, and this office is determined to stop the gangsters. We prefer not to contact Imperial security, so as to demonstrate we can protect our own. However, we do require an experienced independent agent. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 14, 'm4o', 'The Office of the Music Advisor of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 15, 'm4s', 'Now future performances of "Singularity Song" can go on unimpeded by chicanery. This office thanks you for your timely assistance.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 16, 'm4t', 'Protect Naboo''s Gaze-opera Diva'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 17, 'm5d', 'To improve offworld trade, my office works ceaselessly to develop Naboo''s freight infrastructure. An interplanetary smuggling gang is diverting specialized materials needed for docking bay construction, then selling them back to the government through various business fronts. Political considerations deter us from assigning this problem to Imperial security. We prefer to contract with independent agents to eliminate the smuggling gang. Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 18, 'm5o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 19, 'm5s', 'Thank you for your firm resolution of this smuggling nuisance. My office will gladly offer you further assignments in the future.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 20, 'm5t', 'Naboo Buying Back its Own Equipment'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 21, 'm6d', 'My office is charged with developing Naboo''s trade infrastructure. The new Interplanetary Customs Depot is now far over budget and behind schedule, due to persistent and omnivorous corruption. Most recently, gangsters have seized vital construction equipment and are holding it for ransom. They failed to disable all tracking devices, however, and so we know where they are. For political reasons we prefer not to involve Imperial Security. Instead, we shall hire an experienced independent agent. Contact this office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 22, 'm6o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 23, 'm6s', 'Many thanks. The Customs Depot project may yet get back on track. My office looks forward to working with you again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 24, 'm6t', 'Naboo Customs Depot Construction Trouble'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 25, 'm7d', 'My office is proud that Naboo''s literacy rate approaches 100 percent. This is possible only through determined commitment and a healthy educational budget. This budget, though, attracts criminals as hsuberries attract colo claw fish. A rural school reports that gangsters are systematically stealing droid instructors for resale on the black market. I find this crime particularly offensive, yet Imperial security has assigned it low priority. I wish to stop this at once, and am willing to hire an independent agent to stop these criminals.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 26, 'm7o', 'The Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 27, 'm7s', 'Thank you, thank you, for stopping a particularly foul crime. To steal from a school is to steal from the future. I hope to work with you again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 28, 'm7t', 'Gangsters Stealing Naboo Instructor Droids'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 29, 'm8d', 'The bioengineering program at Theed University has developed some interesting compounds using chemicals produced by native wildlife. Thieves have stolen some of these experimental compounds, presumably for resale on the black market. Unfortunately, these are poisons derived from green glie algae. The containers'' hidden security sensors pinpoint their location. To prevent wide publicity and possible panic, I am privately hiring an independent agent to destroy these thieves and, if possible, the chemicals as well.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 30, 'm8o', 'The Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 31, 'm8s', 'Exceptional work! I have ordered probes sent to the area and haven''t detected the escape of any compounds. This is a relief, because those poisons could have killed most of Naboo. Thank you!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 32, 'm8t', 'Thieves Steal Theed University Poisons'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 33, 'm9d', 'My family''s famed Highscouter cove of trained twirrls has provided Theed Palace''s preferred breeding stock for generations. Recently smugglers have made attempts to steal these famous twirrls, no doubt for resale to offworld collectors. We have so far forestalled this theft, and we have also tracked the smugglers to their lair. We have seen evidence of considerable animal cruelty. Imperial security will do nothing for us until an actual theft is committed, so we''d like to hire an experienced agent to assault and destroy this base. Are you available?'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 34, 'm9o', 'Highscouter Twirrl Cove'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 35, 'm9s', 'With those smugglers gone, we feel more comfortable already. Highscouter Cove thanks you. Look in with us next season for more work.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 36, 'm9t', 'Animal Theft in Twirrl Training Fields'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 37, 'm10d', 'The Science Office has long sought an industrial base sufficient to build hyperdrives. Currently the Empire provides drives of Nubian manufacture, through a lengthy and bureaucratic process. A pilot project is planned for Naboo''s moon Rori. Movement of materials to the Rori installation has been hampered by pirates, who infallibly strike our ships shortly after liftoff from Naboo. We suspect a spy in this office. Therefore I am personally contracting with an independent agent, outside normal office procedures, to locate and destroy the pirate base. Contact me for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 38, 'm10o', 'The Master of Science of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 39, 'm10s', 'This is fine news. I shall order new launches for the moonbase hyperdrive project. Thank you, and wish us luck!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 40, 'm10t', 'Hyperdrive Project Threatened by Pirates'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 41, 'm11d', 'Keren Farms Jut Nut Exquisite Select Roast remains the beverage of choice for discerning Theed aristocrats. We use only freshly excreted seeds of the jut nut, meticulously cleaning them after their passage through the peko-peko intestinal tract, which relieves them of toxicity. Keren Farms Jut Nut ESR fetches a premium price in discriminating markets. This has unfortunately made it attractive to thieves, who recently purloined much of this season''s crop. We have located the thieves through hidden tracking devices, and we now wish to hire an experienced agent to exterminate them like vermin. Serious inquiries only, please.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 42, 'm11o', 'Keren Farms Jut Nut Orchards'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 43, 'm11s', 'Your diligence ensures the safety of this season''s remaining Keren Farms Jut Nut Exquisite Select Roast crop. A hearty thank-you, and please stop in for a complimentary cup!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 44, 'm11t', 'Naboo''s Jut Nut Crop Stolen'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 45, 'm12d', 'My office''s many duties include the construction of communication relays between distant Naboo towns. Because of recent Imperial budget cuts, we lack the funds to protect these remote construction projects. A criminal gang has literally taken over one such outpost, destroying all comm equipment on hand. We find it politically and economically expedient to have the entire installation destroyed, not by Imperial security but by an independent contractor. Contact my office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 46, 'm12o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 47, 'm12s', 'This is good news in an office that has lately heard too little good news. We thank you for your quick and decisive action against these gangsters.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 48, 'm12t', 'Gangsters Seize Communications Relay'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 49, 'm13d', 'Gangs of millaflower pushers are operating in Naboo''s schools. In remote bases, the gangs process innocent millaflower blooms into a powerful intoxicant. Then they push the drug on our students. Education of the students has reduced demand, but we are also pursuing a supply strategy. Imperial Security is often in the gangsters'' pay, so we are hiring an independent agent to destroy each base as its location is determined. Contact my office for current coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 50, 'm13o', 'The Office of the Educational Regent of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 51, 'm13s', 'Excellent news. Your success provides a highlight for my forthcoming speech to the Advisory Council on the millaflower menace. Thank you!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 52, 'm13t', 'Millaflower Problem In Naboo''s Schools'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 53, 'm14d', 'Who could possibly be offended by Theed University''s research into interference with droid motivators? This defies reason, yet these innocent researchers have received anonymous death threats, and gangsters recently tried to destroy their lab. They unwittingly alerted probe droids who followed them at a distance, so we know where the gangsters are based. But Imperial security seems curiously apathetic to stopping these thugs. This office is pursuing independent solutions, such as hiring an agent to destroy this base. Contact us for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 54, 'm14o', 'The Office of the Master of Science of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 55, 'm14s', 'We are glad you stopped these thugs, but apparently they have ties to Imperial Security. This is strange and disturbing. We shall probably cancel the research project anyway.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 56, 'm14t', 'Thugs Threaten University Researchers'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 57, 'm15d', 'This office is responsible for arranging the famous Heritage Expressionals at the Emperor''s Retreat outside Theed. These concerts feature a range of antique instruments, the finest and most valuable in this region of the galaxy. Recently gangsters stole several Heritage instruments and, according to the tracking beacons hidden on the items, took them to the following coordinates. We strongly prefer to avoid involving Imperial Security in this matter, for fear of appearing irresponsible in protecting the Emperor''s property. Instead, we are hiring discreet independent agents to locate and destroy the gangster base, preferably without damaging the priceless Heritage instruments.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 58, 'm15o', 'The Office of the Music Advisor of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 59, 'm15s', 'But did you not find the Heritage instruments? Evidently the thieves had already fenced them and moved them offworld. We must locate them by other means.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 60, 'm15t', 'Recover Stolen Heritage Instruments'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 61, 'm16d', 'There is an old legend that one of the statues surrounding the Royal Palace contains hidden treasure. Supposedly a thief placed the valuables there during the statue''s construction, to dispose of incriminating evidence. The story doesn''t identify the statue or the valuables, but that hasn''t stopped treasure-seeking gangsters from attacking random statues across the palace grounds. Surveillance droids have tracked the thugs to their base, but Imperial Security shows no interest in arresting them. To protect a priceless artistic heritage, my office is hiring an independent agent to track and destroy the vandals.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 62, 'm16o', 'The Office of the Chief Architect of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 63, 'm16s', 'This is a relief. We are already repairing the statues these thieves damaged. Hidden treasure -- what a silly legend. Thank you for your assistance.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 64, 'm16t', 'Vandals Damaging Royal Palace Statuary'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 65, 'm17d', 'Kirkhorn, Naboo''s third-oldest guarlara stable, produces some of the best guarlara underfur on the market. The underfur of Kirkhorn Assured Bloodlines has been woven into tapestries now on view in Theed''s best museums and homes. Such is the value of good guarlara underfur that bandits have been stealing this season''s production. We suspect a rival stable, but lack evidence. However, we have the thieves'' location, thanks to tracking beacons in the fur containers. Rather than bring in security forces and attract undue publicity -- always dangerous in the touchy underfur market -- we''d prefer to hire a discreet adventurer able to track and destroy these thieves. Are you willing?'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 66, 'm17o', 'Kirkhorn Guarlara Stable'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 67, 'm17s', 'I thank you for your assistance. Here is your payment. This will teach rival stables that Kirkhorn stands by its underfur!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 68, 'm17t', 'Kirkhorn Guarlara Underfur Stolen!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 69, 'm18d', 'It is no secret that Theed University boasts some of the most talented droid programmers in this part of the galaxy. What is secret is the recent disappearance of one of the university''s leading programmers. Kidnapping? Willful departure for richer climes? We have one clue: surveillance recordings that show known gangsters accompanying the scientist off campus. Probe droids tracked the group to a rural base. We believe that alerting Imperial Security to this event would only bring unwanted criticism of our security procedures. Therefore, we are quietly hiring an independent agent to eliminate the gangsters and, if possible, determine the fate of our programmer.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 70, 'm18o', 'The Office of the Master of Science of Naboo'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 71, 'm18s', 'The researcher returned safely. Apparently it was a kidnapping, but your timely intervention allowed our colleague to escape. Thank you!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 72, 'm18t', 'Theed Droid Programmer Vanishes'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 73, 'm19d', 'The Naboo Wastelands have long constituted a kind of safe haven for pirates and smugglers. Certain bands of these outlaws are known to have thrived for as long as several decades. Due perhaps to their longevity, they have now grown so bold as to move their operations out of the wasteland and closer to settled regions. Our satellites have identified several unauthorized installations where we believe these criminals are engaged in illegal pursuits. As our manpower is presently occupied with unforeseen Imperial obligations, we have opted to contract private operatives to investigate these trouble spots. Agents in our employ will be authorized to use extreme force in dispatching any lawbreakers they find. Qualified citizen operatives may contact the Royal Security Forces to be deputized for specific cases. Financial compensation is available.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 74, 'm19o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 75, 'm19s', 'You have a knack for this sort of work. Please contact us again when you have time for another mission.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 76, 'm19t', 'Outlaws Encroaching on Settlements'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 77, 'm20d', 'After a massive investigative effort, we have finally cracked the ring of data slicers that invaded the computer systems of the Theed Generator. These criminals have dispersed their operation over a series of transmission centers that combine to form a powerful slicing grid. We are coordinating a joint police-civilian effort to strike these transmission centers and shut down their destructive operation. Naboo civilians who can aid in this effort are encouraged to contact the RSF as soon as possible. Offworlders may also participate. Financial compensation will be scaled in accordance with the contribution of each civilian.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 78, 'm20o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 79, 'm20s', 'The operation was a success! Those slicers have almost brought down the Theed Generator on several occasions, but they will not do so again. Thank you for your contribution to the effort.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 80, 'm20t', 'Shut Down Data Slicer Network'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 81, 'm21d', 'Valstaff Courts is the fourth-oldest guarlara stable on Naboo. We breed only the purest bloodlines for the finest Naboo families. Our grounds are legendary for their beauty and luxury, a place where young Naboo ladies may cleave the winds astride elegant guarlara thoroughbreds. But we have noted the intrusion of many unwelcome individuals of dubious character and social standing. These persons frequent our riding grounds and proffer immodest solicitations to our clients. They have proven difficult for our security staff to control. We are therefore offering to professional adventurers and soldiers-of-fortune a reward for the successful extirpation of the trespassers'' premises and all sapient beings therein. Qualified applicants may contact our Sapient Resources department for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 82, 'm21o', 'Valstaff Courts Guarlara Farm'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 83, 'm21s', 'Valstaff Courts is proud to assure the highest degree of security to our distinguished Naboo clientele. Your aptitude with killing and mayhem offers a vital tool in our mission of unparallelled refinement and elegance.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 84, 'm21t', 'Expunge Untoward Visitors'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 85, 'm22d', 'In the court of Naboo one must be vigilant against the corrupting influences of the spacer community. The daughter of an esteemed colleague of the court has fallen victim to the affections of a star pilot of uncertain reputation, one Thanus March. In deference to the child''s social standing, I feel obliged to handle this unfortunate circumstance discreetly. March is known to carouse at an old power station converted into a hive of offworlder decadence. I require one or more freelance operatives to deliver a clear message that this man has no place in the proud halls of Naboo. In short, I want the place taken apart. Meet any resistance with extreme force. If March does not survive the assault, I for one shall shed no tears. I shall pay you handsomely, but most of all, realize that you will be saving the reputation of an innocent lady.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 86, 'm22o', 'Lord Zymanna of Theed'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 87, 'm22s', 'Excellent. A Zabrak informant of mine tells me that the spacer Thanus March escaped with few injuries, but your work against his cohorts was very impressive. While you are on Naboo, you are welcome in my employ.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 88, 'm22t', 'Protect Reputation of Innocent Naboo Lady'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 89, 'm23d', 'Good day. I am TC-20, a protocol droid presently residing in the city of Theed. My mistress is a highborn Naboo lady who must remain anonymous. Her Ladyship has instructed me to hire an experienced warrior to aid her in her dreadful need. The captain of a star freighter, one Thanus March, has been abducted by a brutal gang of ruffians. A trusted friend in the court has provided the coordinates where he is being held. My mistress assures me that this space captain does not deserve this uncivilized treatment, and has given me a generous sum to pay for his rescue. The plan is to attack the ruffians from the outside while an agent within frees Captain March. I hope it is not too late to save him from a terrible fate!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 90, 'm23o', 'TC-20, Protocol Droid'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 91, 'm23s', 'Oh, dear! I have awful news! While you performed the job for which you were hired, my mistress herself was kidnapped! It seems the crime was committed by associates of the very ruffians you attacked. My poor, poor mistress. Here, take the credits which Her Ladyship allotted for your services. How could this happen in the peaceful halls of Theed? What have I done to deserve this? Oh, dear!'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 92, 'm23t', 'My Mistress Requires Experienced Warrior'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 93, 'm24d', 'Even on a supposedly quiet planet like Naboo, the rules of the jungle apply. If someone hits you, you hit them back hard. Me and a couple of other spacers were attacked by a band of hired guns, sending me a message to keep away from a certain Naboo lady. I''m pretty sure the message came from her rich father. Well, I''m going to send back an answer. I''ve figured out where the thugs who hit us spend most of their time. I''m putting together a freelance team to smash the place to dust. I need fighters who are hungry and battle-hardened. Let''s show these Naboo bluebloods how we do it in the Core Worlds.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 94, 'm24o', 'Thanus March, Freelance Spacer'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 95, 'm24s', 'Nice work, kid. Those hired guns won''t bother anyone again. I questioned a Zabrak who was trying to escape and he confirmed what I already knew: It was the father of my Naboo lady who paid them to kill me. I guess I don''t die that easy. Lucky for me. Unlucky for my lady''s highbrow father.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 96, 'm24t', 'Assembling Freelance Strike Team'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 97, 'm25d', 'It''s outrageous! My teenage daughter, Dantre, tells me that her friend from offworld, a space captain named Thanus March, is being harrassed by a local gang of criminals. To my horror I learned that, because the victim in question is not from Naboo, Imperial policies prevent the Royal Security Force from acting in this matter. My daughter has implored me to do something. I am seeking a reputable freelance security agent to confront this gang of criminals and warn them against further harrassment of my daughter''s friend. It is possible that these scum will react with violence. If so, I want an equally forceful response. We must not tolerate these villains on our planet. While the Empire might turn a blind eye to criminal degeneracy, some of us Naboo still have our pride.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 98, 'm25o', 'Lord Chelm of Theed'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 99, 'm25s', 'I''m proud that Naboo and offworlders alike are willing to take a stand against heartless criminals. My daughter, Dantre, is most happy with your results. Well done.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 100, 'm25t', 'Do Not Tolerate Criminal Degeneracy'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 101, 'm26d', 'Since the New Order has brought security to the galaxy, the Naboo court is obliged to deal not only with the planetary bureaucracy but also with Imperial dignitaries. In such cases we sometimes perform discreet operations on their behalf. I currently find myself in such a position. In exchange for Imperial suppression of a certain police action against offworlders on Naboo, I am arranging the elimination of a den of suspected Rebels. I shall hire freelance operatives, for whom no bureaucratic approval is required. If you are capable of executing a potentially dangerous combat action, please contact my office. I expect you to be discreet; in these delicate times, subtlety is the road to success.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 102, 'm26o', 'Lord Zymanna of Theed'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 103, 'm26s', 'Excellent. My informants have verified that you handled the suspected Rebels most expeditiously. Remain discreet about this action and you shall do well on Naboo.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 104, 'm26t', 'Perform Discreet Combat Operation'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 105, 'm27d', 'They''ve got this festival in Theed where the Naboo lords give expensive gifts to their ladies. I''ve met a young lady of the court who I mean to give a gift. I know, a Corellian like me has a mynock''s chance of impressing some rich Naboo, but that''s never stopped me before. I''ve even found the perfect present. My problem is, the smuggler who''s holding it for me cranked up the price we agreed on. He figures I''ve got "rich connections." He''s wrong. My connections don''t have money, they''ve got blasters. I want someone who''s eager for a fight to soften up this smuggler. That way he''ll remember the original price when I visit. The Theed festival is coming up soon, so we can''t wait around on this. Tell me you''re interested and I''ll give you the guy''s coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 106, 'm27o', 'Thanus March, Freelance Spacer'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 107, 'm27s', 'I said soften the guy up, not incinerate him! That''s what I get for not being specific. You did good work, but I''m in a bind. I''ll never find that gift now. Well, if all I can give my Naboo lady is a kiss and a millaflower, I guess that''ll have to do.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 108, 'm27t', 'Soften Up Impolite Smuggler'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 109, 'm28d', 'My dearest friend is a young but seasoned star pilot. Though he''s changed his ways, he once traveled with a rough crowd. A few of his old associates have come to Naboo seeking revenge for some past insult. They don''t realize that he''s offworld right now, avoiding the painful scrutiny of my father''s security chief. My friend fears that, in his absence, these old associates might turn their attention to me. He advised me to hire a freelance investigator to hunt down and eliminate these dangerous spacers. I''m not certain that this action is legal, but my father is already skeptical of my friend''s reputation, and if he finds out I may be in danger I shall never see Captain March again. Can anyone out there help me? I want this awful business to be over with before Thanus returns.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 110, 'm28o', 'A Young Lady of Theed'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 111, 'm28s', 'Is it over? Did you take care of Captain March''s problem? Please, I don''t want details. Just take your payment and go. Oh, and thank you so much.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 112, 'm28t', 'Please Help in Delicate Matter'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 113, 'm29d', 'Because the Emperor''s Retreat brings much additional traffic to Naboo, we have prioritized the security of planetside settlements. To this end we have purchased a shipment of taser staves for crowd control. Somehow a gang of thieves captured these weapons before we could take possession. We must retrieve these staves without delay. Our intelligence agents have compiled a list of possible hideouts where the culprits might be storing their loot. We are contracting independent agents to investigate these sites and engage the thieves if they are found. Payment will be commensurate with the level of success.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 114, 'm29o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 115, 'm29s', 'Good job. We recovered all the taser staves. Those weapons can wreak all kinds of havoc in the hands of outlaws.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 116, 'm29t', 'Bring Down Gang of Thieves'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 117, 'm30d', 'The Tech Raiders are an old and notorious band of smugglers. For many years they avoided the star lanes of Naboo, but our sources inform us that they are back. Given the Imperial presence that now graces our planet, it is prudent that we stop this criminal activity before it draws a decisive response from the Empire. Therefore we are contracting private agents in a coordinated assault on several different smuggling depots. Qualified parties may contact the RSF for the coordinates of the nearest suspected Tech Raider site.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 118, 'm30o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 119, 'm30s', 'Good work. With luck we will have seen the last of the Tech Raiders in this system.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 120, 'm30t', 'Tech Raiders Smuggling Ring'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 121, 'm31d', 'You would think that the Naboo System, location of the Emperor''s Retreat, would be safe from the ravages of space piracy. But against all odds, a squadron of reckless cutthroats has taken up residence on our very planet. The Imperial Navy is anxious to bring down these pirates. The Royal Space Fighter Corps would very much like to catch them first. We have located a secret hangar that we believe houses many of their ships. We are hiring civilians to attack this hangar and force the pirates to take off, where we shall be waiting for them. With skill and good fortune we may both vanquish this threat to our star lanes and demonstrate that the Royal Space Fighter Corps is capable of handling threats that elude the Imperial Navy. Interested parties may contact us for the coordinates of the suspected pirate hangar.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 122, 'm31o', 'The Royal Space Fighter Corps'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 123, 'm31s', 'Terrific work! The operation was a complete success. The pirates fled through a hidden launch tunnel, and we picked them off in orbit. The Imperial Navy will chafe at this news. You did very well.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 124, 'm31t', 'Hit Suspected Pirate Hangar');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 125, 'm32d', 'Thieves have no limits to their petty greed. Even our garbage is not safe from these parasites. Naboo operates a planetwide system of robo-flatbeds that transport municipal garbage to various reprocessing sites. These hover-trains have become the target of robbers, who sort through the refuse to find any salvage and leave the rest strewn across our fair planet. We believe we have located the hideouts of many of these salvage gangs. All we need are lawful-minded civilians to put them out of commission. Full pardons are ready for any violence that may result from these action. Contact our office for the coordinates of a target near you.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 126, 'm32o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 127, 'm32s', 'Good work. Those thieves deserved what they got. If our garbage is not even safe, how can we assure the security of our people''s homes and properties?'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 128, 'm32t', 'Shut Down Salvage Gang'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 129, 'm33d', 'In order to preserve the natural beauty of our planet, Naboo carefully restricts all deforestation campaigns. Some renegade harvesters have flouted these policies and wilfully ignored all requests to cease their unlawful cutting. We must put a stop to their crimes. We are contracting private operatives to visit these outlaws'' barracks and put them out of business. If you can complete such an assignment, contact our office for coordinates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 130, 'm33o', 'The Royal Security Forces'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 131, 'm33s', 'Nice job. Maybe now these outlaws will take seriously their responsibilities for preserving the natural state of Naboo.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 132, 'm33t', 'Renegade Harvesters'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 133, 'm34d', 'Some of desan topsiders have been comen into Lake Paonga and braken de laws of de Gungans. Desa diven into da deep Core and poachen dangerous fishes like de Opee and de Colo Claw. Wesa must putten a stop to dis, so wesa now hiren topsiders to knock down desan fishing shacks. Desa well-armed so do not thinken desa going to fall easy. Da Bosses going to pay yousa well enough for de work, though.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 134, 'm34o', 'Sergeant Degoolsby of Otoh Gunga'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 135, 'm34s', 'Yousa done very well, for a topsider. Wesa given you da reward now. Great thanks to yousa.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 136, 'm34t', 'Desan Topsider Poachers Got to Go'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 137, 'm35d', 'It''s dreadful business, but I have been informed that a certain collection of unsavory spacers has begun disparaging me to potential employees of my shipping concern. As I must protect my reputation, I have no choice but to hire a responsible agent to stop their slanderous activities. The situation may turn ugly, but I must not yield. Please act quickly and let''s get this over with.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 138, 'm35o', 'Master Bottoblast of Theed'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 139, 'm35s', 'Splendid. That will silence those slanderous dogs. You have earned your reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 140, 'm35t', 'End Slanderous Activities'),
('string/en/mission/mission_destroy_neutral_medium_npc_naboo.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 1, 'm1d', 'Ever heard of lesai, citizen? It''s a highly addictive drug and it''s being stored in an abandoned settlement near here. Please help me make sure this drug won''t make its way to decent neighborhoods.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 3, 'm1s', 'Now those are results I can live with, citizen. Good work!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 4, 'm1t', 'Destroy Addictive Drug'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 5, 'm2d', 'There''s only one language criminals understand clearly -- the searing sounds of blaster fire! A group of violent thugs have been harassing decent folk and need to be driven off. If you can help do that, I''ll reward you.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 7, 'm2s', 'Good job, citizen. You''re a true hero. Your promised pay has been deposited.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 8, 'm2t', 'Drive Off Vicious Thugs'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 9, 'm3d', 'Due to the Empire''s higher recruitment standards, many of the thugs who would have ended up serving in planetary security forces are turning to crime instead. Could you help get rid of some of these troublemakers? I''d make it worth your while. '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 11, 'm3s', 'Thanks you, citizen. I''d normally suggest you join the military, but I think you could do more good as an independent agent. Get richer that way too.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 12, 'm3t', 'Discipline Slackers'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 13, 'm4d', 'I''m sick of putting up with criminals and their vile antics. I''ve gathered some credits to hire a skilled troubleshooter to get rid of these swoop gangs and spice dealers. Would you be interested in trying for that money, citizen?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 15, 'm4s', 'Now that''s how you deal with that Sithspawn! You''ve definitely earned the reward. '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 16, 'm4t', 'Citizens Fight Back'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 17, 'm5d', 'Hey, buddy, you care about keeping the streets clean, right? I hear there''s some lowlife peddling inferior grade glitterstim spice. Can you believe this worm''s nerve? Sure could use someone like you to run this bum out of business. You ready to earn some credits? '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 19, 'm5s', 'Good job. No one deals spice in my neighborhood without my say-so. And don''t even think about pushing that inferior grade sludge. Your money''s been sent, pal. '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 20, 'm5t', 'Run Competition Out'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 21, 'm6d', 'A local band of gunrunners has stolen a shipment of deadly disrupter weapons. This band is like no other, however, for they are led by an amazingly canny mouse droid. Yes, you heard correctly! If you were to stop these rogues and end this mechanical menace''s career, you''d become a legend.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 23, 'm6s', 'Did you see the mouse droid? Hmm, the clever fiend probably had an escape plan. All masterminds do. Do you know how I know that? Because I''m the Emperor! Mwahahaha! Anyway, this money is for your troubles.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 24, 'm6t', 'Stop Terrible Galatic Menace'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 25, 'm7d', 'All these jerks strutting around here think bravery resides in a blaster. But when push comes to shove, they turn tail and run. Are you one of those, or can you really stand up to the thugs menacing this area?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 27, 'm7s', 'I had a sense about you, citizen. True courage should always be rewarded. Your money''s been deposited.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 28, 'm7t', 'True Grit'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 29, 'm8d', 'You gotta help me, citizen! I testified against a swoop gang and got their leader sent to a labor camp on Berea. Now his followers have sworn vengeance and intend to burn my settlement to the ground. I''ll pay you to get rid of these brutes. '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 31, 'm8s', 'Your heroics will be an example to others, citizen! I think more folks will stand up to these animals now. Go spend your just reward!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 32, 'm8t', 'Witness Needs Protection'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 33, 'm9d', 'I''m trying to go straight, honest. I walked away from these spice smugglers, but now they claim I know too much about their operation and need to be silenced. Can you help protect me and my family? '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 35, 'm9s', 'Many thanks, friend! My family and I can now get on with our lives. The addition to your account should demonstrate my gratitude.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 36, 'm9t', 'Save Reformed Smuggler'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 37, 'm10d', 'I should know better than to get drunk at the cantina with my friends. We all got to boasting, as we always do, and I claimed I''d run the local swoop gang out of town by week''s end. The swoopers got wind of it and now intend to murder me. If you help me get rid of them, I''ll pay you.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 39, 'm10s', 'Well done, citizen! Your well-earned pay has been sent. If you ever get the fancy to knock back some cold ones with us, look us up at the cantina.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 40, 'm10t', 'Make Good a Drunk''s Boast'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 41, 'm11d', 'This community is being terrorized by a mindless gang of cutthroats whose only means of communication is wanton violence and destruction. If you put a stop to their vile activities, I''ll pay you a handsome reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 43, 'm11s', 'You''re a hero to the people, friend. Accept this reward and my unending gratitude. You should do this for a living.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 44, 'm11t', 'Be a Hero'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 45, 'm12d', 'A few young women have disappeared recently, and I suspect slavers. Those rogues have a base near here, from which I''m certain they''re shipping these girls offworld. Can you put a stop to this despicable activity?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 47, 'm12s', 'It''s good to know there are still heroes like you left in the galaxy. Please accept this payment as a token of my appreciation.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 48, 'm12t', 'Slavers Are Scum'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 49, 'm13d', 'Bullying helpless citizens requires very little courage, so I''m not sure why these thugs are so proud. You want to impress people? Then go after the thugs and drive them out of this area. That takes true courage!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 51, 'm13s', 'Citizen, you showed those bullies the true meaning of courage. Please accept this reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 52, 'm13t', 'Teach Bullies a Lesson'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 53, 'm14d', 'It was an accident that I killed one of those thugs. I had to do something, they were killing my pet! But now they''re coming after me. You have to go there and stop them!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 55, 'm14s', 'When a thug is killing my pet, I just get so steamed! Thank you so much for rescuing me. Please, enjoy this money!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 56, 'm14t', 'Defend Pet Owner'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 57, 'm15d', 'I wrote a play lampooning local crooked politicians. Turns out one didn''t have a sense of humor, and he''s hired thugs to burn down my house. But if you go to their hangout and stop them first, I''ll pay you well.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 59, 'm15s', 'That''s a relief. I''m going to write another play about this intimidation attempt, and you''ll be in it. Thanks!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 60, 'm15t', 'Save a Playwright'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 61, 'm16d', 'Those pirates are planning to take out an Alliance smuggling ship! I overheard them at the cantina. I can''t go to the Imperials, and I don''t know how to reach the Alliance, so I''ll pay you to stop those pirates.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 63, 'm16s', 'Well done! I expect the Alliance ship got through all right. It''s a shame they have to rely on smugglers, but the Empire controls the space lanes.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 64, 'm16t', 'Help the Alliance'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 65, 'm17d', 'My little child is crying in her creche because a local gang has stolen this community''s entire supply of infant formula. Now that''s low! We''ve all raised money to hire some goon like you to stop those other goons!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 67, 'm17s', 'Sorry I called you a goon. I was feeling tense. Thanks for freeing up the supply of infant formula. It''s the only kind my species can tolerate, you know.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 68, 'm17t', 'Help Starving Children'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 69, 'm18d', 'I broke up badly with an old flame, and my former sweetheart enlisted a bunch of lowlife thugs to harrass me. It''s been torture! I can''t reach my former love, so for now I want to hire you to stop the gang.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 71, 'm18s', 'Since I hired you, I found my old flame, and we''ve patched things up. A little. Anyway, thanks for stopping that gang.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 72, 'm18t', 'A Bad Breakup'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 73, 'm19d', 'With my life''s savings I bought a beautiful Corellian Jumpmaster 5000 starship. In orbit, pirates attacked me, and I had to get out in the escape pod. But I''ve tracked the pirates, and now I''m hiring you to go in and destroy them.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 75, 'm19s', 'Great! I sure showed those pirates -- or, I mean, you did! Enjor your reward. It''s all I have left, but now I can recover my ship and start over.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 76, 'm19t', 'Avenge Starship Captain'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 77, 'm20d', 'I had no idea one gang could stink up the air so much. No one can even sleep, it''s so bad. All the folks who miss clean air have put together some money to hire someone like you to clean out that gang. Will you do it?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 79, 'm20s', 'What in the galaxy were they doing, to create such a stench? Whatever it was, it was illegal, and you''ve put a stop to it. Thanks!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 80, 'm20t', 'Stop Stinky Thugs'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 81, 'm21d', 'A gang of thieves has been stealing ordinary GNK power droids all over this community. Nobody knows why; power droids aren''t particularly valuable. But we''ve traced the thieves, and we''ve raised funds to hire a thu-- I mean, an adventurer or two to face them down in their lair. Go for it!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 83, 'm21s', 'Thank you. Right now we''re trying to figure out why the thieves wanted all those gonk droids. Apparently they would steal them, then turn them loose. Senseless.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 84, 'm21t', 'Solve Gonk Droid Mystery'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 85, 'm22d', 'I''m in a bind. A friend of mine tangled with the wrong crowd and now they''re holding him captive in their thieves'' den. If I call the authorities, those filthy gundarks will see trouble coming from a long way off. Someone needs to hit the place secretly and rescue my friend. I''m sure he''ll compensate you well.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 87, 'm22s', 'Terrific! My friend escaped just after you arrived at the thieves'' den. He transmitted these credits to my account, and I forwarded them to you. Good job.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 88, 'm22t', 'Save Kidnapped Friend'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 89, 'm23d', 'May I have a word with you? I can''t name names, but a certain politician would like to put a stop to a plot by another politician. Parliamentary procedure being what it is, this dispute is best handled outside the halls of government. I must hire someone to blow up the criminals who are perpetrating this scheme. If you want the job, it''s yours.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 91, 'm23s', 'The politician who employs me will be delighted to hear that the esteemed colleague''s plot has been foiled. Interplanetary politics can be very satisfying, don''t you think?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 92, 'm23t', 'Political Intrigue'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 93, 'm24d', 'Please help me! I found out a local swoop gang has put a price on my head! What did I ever do to them? My only hope is for someone to wipe this gang off the face of the planet, so the bounty will become invalid. Surely a rough-and-ready spacer like you can help a desperate, wronged citizen in my time of need?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 95, 'm24s', 'Your fee has been deposited. That will teach the other swoopers around here not to tangle with innocent, harmless citizens like me. Unfortunately they''re not a bright bunch.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 96, 'm24t', 'Slap Naughty Swoopers'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 97, 'm25d', 'Do you smell that? It''s waste gasses from a little ore refinery not far from here. A bunch of roughnecks built it to sidestep guild fees. Well, those of us who live around here don''t plan to let them poison our air. We''re willing to pay anyone who can knock that place out of operation once and for all. You''ve done this kind of work before, right?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 99, 'm25s', 'What a difference. I can smell that clean air! Well, cleaner than it was, anyway. You did your job and your payment''s been transmitted. Thanks.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 100, 'm25t', 'Help Clean the Air'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 101, 'm26d', 'The time has come, my friend. A band of space pirates robbed me of an expensive idol from the Onderon moon of Dxun. I can''t make them give it back, but I can pay to have them punished. Aim those killer instincts of yours at their planetside den and don''t look away until every one of them is dead.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 102, 'm26o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 103, 'm26s', 'Thanks, my friend. I knew you would finish them off with little trouble. I''ll head over and see if my stolen Dxun idol is somewhere in the rubble.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 104, 'm26t', 'Give Me the Idol'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 105, 'm27d', 'I''m not who you think I am. People say I look like an announcer from the local newsfeed, but I''m just a loyal Imperial citizen. I''m hiring someone to assault a local spice gang. Make it flashy. There could be, I don''t know, hovercams or something in the area. I''d like to set an example to other lawbreakers. Also, can you wear something eye-catching?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 106, 'm27o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 107, 'm27s', 'What a show! The hovercams captured the whole attack. I especially enjoyed the part where that gangster cursed you before dying. This is going to make great ratings for ... um, for whatever newsfeed sent those hovercams to film it. Not that I know anything about that. Ahem.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 108, 'm27t', 'Reality HoloNet Needs You'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 109, 'm28d', 'You must help me! I''m trying to transport my niece off-planet, to save her from a criminal father. But he''s got word of my plan, and his gang intends to kidnap the poor child! Please, I must hire you to attack the hangout where they always drink, to provide a distraction so I can rescue the girl. I''ve got enough credits to pay you. Just hurry!'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 110, 'm28o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 111, 'm28s', 'We did it! The girl is safely off to an Outer Rim planet and her father''s gang is crippled. You''re a good person. I''m happy to pay this money.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 112, 'm28t', 'Save Innocent Niece'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 113, 'm29d', 'At last I''ve found you! Years ago you served my father in the Clone Wars. Now he begs you to help him in his struggle against ... what did you say? You didn''t serve my father? Oh. Well, you''ll do anyway. How''d you like to pick up a few credits by blasting apart a den of gas thieves near here?'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 114, 'm29o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 115, 'm29s', 'You did it! You don''t need to be paid, do you? I know there''s more to you than just money. Right? Oh. Well, you''ve got to follow your own path. No one can choose it for you.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 116, 'm29t', 'Break Up Gas Thieves'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 117, 'm30d', 'It''s an outrage! A crewman of mine was murdered by a gang of local cutthroats. Now they''re keeping his body for who-knows-what reason. I''m a spacer, not a fighter, but I can contract a tough guy like you to pay back those filthy gundarks! You pound them into rubble, and I''ll give you whatever I have.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 118, 'm30o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 119, 'm30s', 'You''ve honored my late crewman and rid this planet of some dangerous scum. If you decide to join a freighter crew, let me know, eh? I have an opening.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 120, 'm30t', 'Avenge My Crewman'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 121, 'm31d', 'Do I look like a simpleton to you? Then explain to me why a malodorous band of hoodlums would extort money from me. Me! Do they imagine I have no resources to pursue retaliation? On that topic, you look like you''ve killed men before. Would you like to do so again? I can give you a substantial payment upon completion.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 122, 'm31o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 123, 'm31s', 'Most splendid indeed! Despite your looks, you are a being of the highest caliber. From now on those crooks shall think twice before accosting someone of my particular refinement and resources. '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 124, 'm31t', 'Help Haughty Patron'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 125, 'm32d', 'Ever seen a golden bantha? They''re rare and spectacular creatures. I owned one until yesterday, when a band of pelt smugglers killed it for the fur. I can''t get my bantha back, but I can get retaliation. I know where they keep their contraband. I''d like to contract you to level the place. WIpe them out, all of them.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 126, 'm32o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 127, 'm32s', 'I''ll always remember the scent of that smoke lingering over the ashes of those smugglers. You''re very good, there''s no denying that. Your payment has been sent. Thanks.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 128, 'm32t', 'Stop Bantha Poachers'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 129, 'm33d', 'You! You look like you could pull the ears off a gundark. I''ve got a pile of credits waiting if you can attack a certain criminal lair and thoroughly dispose of it. They''re up to no good in there, let me assure you.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 130, 'm33o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 131, 'm33s', 'Fine job. I needed that territory cleared for my new cantina-casino, and you''ve taken care of it in the most active way. Your pay is in your account.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 132, 'm33t', 'Help the Land Developer'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 133, 'm34d', 'I''m a love junkie, I admit it! I fell in with a gang member -- I like nice eyes, what can I say? -- but I had to end it. Now the whole gang has destroyed my home and promises to "make me their droid." I need help! I''ve got money; you''ve got weapons; let''s work together. Take out the gang nest, and let me live a loving life again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 134, 'm34o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 135, 'm34s', 'Thanks, hero! That was impressive. Your credits have been transmitted. Call me sometime. I like your eyes. '),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 136, 'm34t', 'Help Lovesick Fool'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 137, 'm35d', 'I contracted with another party to carry certain cargo past Imperial checkpoints. Matters went awry, I had to dump the cargo, and now the other party is making my life very, very hard. I offer you a fair reward for going to the other party''s headquarters and removing this obstacle to my future happiness.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 138, 'm35o', ''),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 139, 'm35s', 'Thank you. I don''t see why a few dozen Imperial turbolasers were worth all this fuss, but there you are.'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 140, 'm35t', 'Take Out Spoilsports'),
('string/en/mission/mission_destroy_neutral_medium_npc_non_persistent_from_npc.stf', 141, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 1, 'm1d', 'This place has been going downhill ever since that Toong couple next door had one of their slaves stolen. And that was over 30 years ago. Now we have these strange looking characters wandering around the neighborhood every night. I don''t know what they do, but I''m sure they''re up to no good. They come from outside of town, sneaking into our settlement like criminals. I wish someone would get rid of them, so we can have some peace and quiet in this neighborhood. I''ve collected some credits from the people who live around me and we''re willing to pay anyone who can help keep our homes safe. \n\nElza Monimi'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 2, 'm1o', 'Elza Monimi'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 3, 'm1s', 'Thank you for your help. Although things still aren''t as good as they were in old days, it is a step in the right direction. And credits well spent as far as I am concerned.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 4, 'm1t', 'Quieting the Nosy Neighbor'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 5, 'm2d', 'While the Boonta Eve is mainly celebrated in certain parts of Mos Espa, it has become a night of mischief around here. A group of local hoodlums take it upon themselves to stir up trouble that night, stealing from the elderly and attacking anyone who dares to go outside. The group of troublemakers responsible lives outside of town. If someone would go there and put and end to their mischievous ways, the entire town would appreciate it.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 6, 'm2o', 'Outraged Citizens'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 7, 'm2s', 'We appreciate your help. Now Boonta Eve will no longer be a dreaded day.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 8, 'm2t', 'The Boonta Eve Bandits'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 9, 'm3d', 'On one of my recent "scavenging" trips over the mountains, I made such a haul that I couldn''t fit everything in my speeder. So I had to make two trips. I left a pile of spare parts and other things buried under a pile of dried brush near the peak of one of the mounatins in the Needles Range. Well, when I want back my stash was taken. Now I know complaining about someone stealing my stolen goods is pretty low, but this is how I make my living. On my last trip back there I was robbed by some thugs who I assume are the same ones who stole my stash. So I need someone to take this group out. If I can''t continue to scavenge along the Needles I might actually have to get a real job.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 10, 'm3o', 'A local scavenger needs someone to make his stomping grounds safe.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 11, 'm3s', 'You really saved my skin. I don''t know what I would have done if I had to go legit. With all the rules the Empire is imposing on us, it''s been difficult to actually make a living. And a real job would break me.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 12, 'm3t', 'Scavenger Hunt'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 13, 'm4d', 'It was almost a year ago when we planned our group expedition to the famous sights of Tatooine. We split into two smaller groups when there was a disagreement on which places we''d stop and see. There''s never enough time to do everything. Anyway, when we separated, the plan was to meet back up at the Jag Crag Gorge. When we arrived there, the other group never showed up. They were robbed one night and had to head back home. This ruined the trip for everyone. And while the local authorities never did anything about it, we''ve identified the thieves. Even though we are sure the stolen items can''t be recovered, we would like to know that this won''t happen again. '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 14, 'm4o', 'A Group of Wronged Sightseers'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 15, 'm4s', 'Thank you very much for eliminating those nasty thieves. We will continue our expeditions, now that Tatooine is a little safer.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 16, 'm4t', 'Journey from the Jag Crag Gorge'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 17, 'm5d', 'In our city lies an ancient grave site honoring Jedi Master Sidrona Diath. Sadly, the monument was senselessly defaced by a local group of Jedi haters. It was probably done to curry favor with the local Imperials. But Master Diath was a good man and a revered leader of Tatooine who fought valiantly before his fall in the Battle of Basilisk some 4,000 years ago. He also fathered Jedi Knight Dace Diath, a hero in the Sith War. And, of course, Diath was the first to speak the words "Koroght Gaghght Takt", which, for outlanders not familiar with the saying, means "blessed be your going out from us". Although the Empire probably wouldn''t agree with us, those who defaced his grave should be punished. The key members of the Tatooine Coalition for the Preservation of the Prominent Past wish to remain anonymous, in the hopes of avoiding the Empire''s wrath, but we are willing to pay a handsome sum to whoever deals with this problem.\n\nTatooine Coalition for the Preservation of the Prominent Past'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 18, 'm5o', 'Tatooine Coalition for the Preservation of the Prominent Past'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 19, 'm5s', 'The Coalition is forever grateful for your actions. And as the great Master Diath first said, "Koroght Gaghght Takt".'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 20, 'm5t', 'Defilers of an Ancient Jedi Grave'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 21, 'm6d', 'Someone has been taking water from the sacred canyons of the Tusken Raiders. It is creating unrest in one of the largest groups of Sand People in this part of Tatooine. This entire city is in jeopardy if this continues, but the local authorities seem unable, or unwilling, to do anything about it. We''ve traced the thefts to a group outside of town, but we can''t do anything about it on our own. We need a person with a particular talent to handle this situation. We don''t care how you stop them, just save our town from the wrath of those superstitious savages.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 22, 'm6o', 'A Community In Peril'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 23, 'm6s', 'You are our savior! The Tuskens would have surely overrun our little community if you hadn''t intervened. With their enemies destroyed, the Tuskens will likely move along.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 24, 'm6t', 'Who''s Been Drinking the Gafsa Water?'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 25, 'm7d', 'Gragra, a local gorgmonger, started growing gorgs and other edible amphibians in a sewer zone beneath this town decades ago. Long after she''s left this place to work elsewhere, the gorg population continues to grow. Now, these little amphibious creatures don''t do much damage down in the sewers but some of the squatters that live outside of town come here to feed on them. These squatters are known to rob and burgle the locals whenever they can. I am offering a generous reward to anyone who stops these squatters from invading our city. No questions asked.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 26, 'm7o', 'A Piqued Local Denizen'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 27, 'm7s', 'I appreciate your help in this matter. The entire city will benefit from your work. And I would also appreciate if you would keep quiet about your mission to kill the squatters.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 28, 'm7t', 'Evict the Gorg Eaters'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 29, 'm8d', 'There''s this clan of Sand People... Well, I''m not sure that they''re actually Sand People, but someone''s been terrorizing travelers who come and go from town. I''ve only heard stories, but I do know what they call themselves: the clan of Grk''kkrs''ar. I did some research on the term and it''s actually the name of a mythic Tusken who never showed fear, even when facing a krayt dragon. Now my family is coming to visit from the far side of Tatooine and I don''t want these Tuskens, or whatever they are, attacking my relatives. Please help me! But be careful. They sound dangerous...'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 30, 'm8o', 'A Concerned Tatooine Citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 31, 'm8s', 'Praise the maker! You''ve saved my family!'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 32, 'm8t', 'The Clan of Grk''kkrs''ar.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 33, 'm9d', 'Now, it''s not much of a business, but I am able to feed my family off the credits I make selling necklaces made from small snippets of japor. Last week some thieves took all of my necklaces as well as my carving tools. Without these things my family will starve. I have a few credits, but not enough to buy all those tools again. And the necklaces they took represent several weeks of work. I need someone to help me. I don''t expect you to return all these things to me. I just want someone to clear out the thieves and I''ll go back to their camp and reclaim my goods, as well as anything else I can find. I am willing to pay a fairly good sum for this work.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 34, 'm9o', 'A Local Japor Carver'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 35, 'm9s', 'Thank you, friend. I would offer you a necklace in addition to your payment but I can''t spare one right now. Just know that my family, and my business, are thriving again.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 36, 'm9t', 'Japor Thieves'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 37, 'm10d', 'Things aren''t like they were back when I was kid running around the streets of Mos Espa. Friends would stand by you, and Tatooine was on its own. No Republic or Empire or whatever telling everyone what to do. Now we live in a military state. Podracing is dead. There are military garrisons everywhere you look, and Jabba''s associates bring the worst kind of scum to this planet. I always thought I''d get out of here some day, but I don''t think that will ever happen now. Still, I would sleep better at night if a certain group of scavengers living outside of town were taken out. I can''t tell you what they did, but I do have plenty of credits to pay anyone who is willing to take them out. Bring me proof that they are bantha fodder and the credits are yours.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 38, 'm10o', 'Melee of Mos Espa'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 39, 'm10s', 'Thank you. I hope those scum suffered...'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 40, 'm10t', 'Melee''s Drama'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 41, 'm11d', 'When I was a young man, my life was dedicated to protecting those who couldn''t defend themselves. I spent most of my time defending the peaceful Jawas. They are too small to fight their own battles, I fear. They are constantly threatened by gangs of roving bandits, or worse. Well, I may be too old to actually pick up a blaster rifle or vibroax to battle those who would threaten the defenseless little desert wanderers, but I''m not too crippled to at least go out check on the Jawas. I spotted some thugs moving in on the chatter-boxes. I''m worried the Jawas are about to get killed. Go out stop these advancing trouble-makers, and I''ll pay you for your trouble.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 42, 'm11o', 'An Altruistic Citizen'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 43, 'm11s', 'The Jawas are safe, for now. Although the little chatter-boxes would never thank you themselves (I don''t even think that they realized they were in any danger), I do extend my gratitude (and a few credits) your way. I admit, I''m old and cynical, but you''ve shown me that there are still heroes left in the galaxy. '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 44, 'm11t', 'Jawa Defender'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 45, 'm12d', 'WANTED: Adventurers to brave the deserts of Tatooine in search of villainous scum! \n\nInterested parties should have: some competence with a blaster, vibroblade, or other weapon; a willingness to travel the dangerous Tatooine wastes; and unflagging courage! Those who accept this mission will receive coordinates to the last known location of one of Tatooine''s many roving bands of thugs or miscreants. Using these coordinates, the willing adventurer will be required to destroy any criminal encampments.  '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 46, 'm12o', 'Mos Eisley Police Authority'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 47, 'm12s', 'We''ve received confirmation of your mission''s success. Good work. Your payment has been transferred.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 48, 'm12t', 'Adventurers Wanted'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 49, 'm13d', 'WANTED: Mercenaries willing to risk their lives for lucrative rewards.\n\nWe are seeking mercenaries capable of confronting Tatooine''s many thugs, thieves, hoodlums, and swoop gangsters. Those who accept this mission must supply their own weaponry and other equipment. Upon acceptance, the Mos Eisley Police Authority will transmit the coordinates of a known criminal encampment. This camp must be completely destroyed. Risks are high, but rewards are fair. '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 50, 'm13o', 'Mos Eisley Police Authority'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 51, 'm13s', 'We''ve received confirmation of your mission''s success. Good work. Your payment has been transferred.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 52, 'm13t', 'Mercenaries Wanted'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 53, 'm14d', 'May the Force be with us! TASKForce Tatooine is committed to fighting evil wherever it appears! As any galactic citizen will understand, Tatooine is overrun by a nearly-unstoppable criminal element. The thieves and killers spread like a virus across the desert. But agents of TASKForce Tatooine tirelessly locate these infections wherever they occur. We then hire competent soldiers to eliminate these dangerous dens and hidden lairs. Those willing to assist TASKForce Tatooine will be given coordinates to an identified criminal base. Once that base is destroyed, we will gladly transmit a sizable reward. '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 54, 'm14o', 'TASKForce Tatooine '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 55, 'm14s', 'The Force was with you! Congratulations on wiping out those miscreants. Tatooine is much safer now, and we can begin searching for the next criminal target. A reward has been transmitted to your account.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 56, 'm14t', 'TASKForce Agent'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 57, 'm15d', 'Hello. I hope this transmitter is working right... Hopefully, this plea for help has reached the local mission terminals. If you''re reading this, then I suppose I did something right... I''ll keep this simple: We''re a hardworking folk, but not very good with blasters or vibroweapons. Our lands are threatened by greedy, well-armed squatters. We need someone to step forward and help defend us. Please, accept this mission and move in on the murderers before they can close in us! We''ll provide coordinates to their hideout; you just have to provide the blaster fire.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 58, 'm15o', 'A Local Moisture Farmer');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 59, 'm15s', 'Hello again. I wish to thank you for killing those murderous squatters. I''ve dug up some credits and will transfer them to your account immediately.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 60, 'm15t', 'Squatters'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 61, 'm16d', 'Jabba the Hutt is seeking brave warriors who wish to prove themselves in battle against the Hutt''s many enemies! Jabba is constantly tracking his foes, who plot his downfall, attempt to steal his goods, and ambush his loyal troops. Jabba is enraged and sickened by his enemies, and wishes to see them all killed. Our intrepid scouts have located a band of Jabba''s most-hated enemies in the desert. Any who accept this mission must go forth and stamp out this threat to Jabba''s wealth and happiness. Those who succeed will earn a handful of credits, and Jabba''s gratitude.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 62, 'm16o', 'Bib Fortuna, on behalf of Jabba the Hutt'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 63, 'm16s', 'I admit that I am surprised by your success. You have dealt with Jabba the Hutt''s enemies, and you have fought bravely. I have slipped a few credits from Jabba''s vaults in order to repay you for your services. If you are fortunate, Jabba will let you keep your credits... '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 64, 'm16t', 'Crime War'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 65, 'm17d', 'Transmission Translated from Jawaese for your convenience!\n\nWe Jawas are threatened by nasty, murderous humans and aliens, who kill us with wicked, sharp blades and fiery blasters. They hunt us across the sands, leave our bodies burning on the dunes. We need brave, bold heroes to stop these evil, dangerous thugs! Accept this quest and we will send you a radiant, glowing beacon that you can follow to our enemies! When you destroy their base, we will pay you many glorious credits. \n\nWimateeka, Jawa Clan Leader'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 66, 'm17o', 'Wimateeka'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 67, 'm17s', 'Transmission Translated from Jawaese for your convenience!\n\nMost exalted hero of the Jawas! Thank you a hundred times for saving us from evil, murderous thugs. We will now pay you a sizable, big reward.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 68, 'm17t', 'Jawa Killers'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 69, 'm18d', 'Nothing is more important than family. Last season, my son was killed by thugs. He was just heading out to Anchorhead for some power converters and other supplies when he was ambushed by the murderous scum. They left him to rot in the desert. I reported the murder to the Imperial authorities in Bestine, but they said they couldn''t find the killers. I doubt they even looked. It only took me two days to find the band of thieves who blasted my son. Now, all I want is revenge. I''m offering a reward to anyone who can avenge my son. But I won''t be happy with just a few dead murderers; I want their entire camp burned to the ground.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 70, 'm18o', 'A Heartsick Father'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 71, 'm18s', 'You have my heartfelt and undying gratitude. And my son, wherever he is, thanks you as well. Those murderers are dead, and they will never hurt another innocent traveler. The credits I give you as a reward will never be thanks enough for all you have done, for my family and this planet.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 72, 'm18t', 'Avenger'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 73, 'm19d', 'A group of local roughnecks have been causing a lot of trouble in and around Anchorhead. They tear through town, kicking up dust and scaring away the honest farmers. They''ve even started stealing droids and shaking down the locals for "protection fees." When some of my hired hands confronted these dirtbags, the roughnecks nearly beat them to death. It''s only a matter of time before they kill someone... So, I followed these bums to their hideout in the desert. Anyone who wants a few credits can saddle up and take care of the roughnecks. '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 74, 'm19o', 'Fixer'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 75, 'm19s', 'Nice work, friend. Those roughnecks won''t be bothering us again. And just in time, too; some of the old-timers here were ready to go to Jabba for help, and that would have only put us into in his debt. I''d much rather pay you a few credits than owe that slug my life.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 76, 'm19t', 'Roughnecks'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 77, 'm20d', 'My employer, the All-Powerful Jabba the Hutt, has been implored to come to the aid of the citizens of Anchorhead. It appears that these simpering, unarmed farmers are being harassed by a gang of violent roughnecks. Jabba''s generosity knows no bounds, and he has decided to aid this group. For a price, of course. In fact, partial ownership of Anchorhead, it seems. To help these poor, unfortunate fools (and gain a foothold in Anchorhead), Jabba is hiring mercenaries. Any hired thugs, trained or untrained, are welcome to accept this mission. Upon doing so, you will receive coordinates to the lair of Jabba''s new enemies. Simply eliminate these ruffians and destroy their base to earn Jabba''s gratitude.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 78, 'm20o', 'Bib Fortuna, on behalf of Jabba the Hutt'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 79, 'm20s', 'I must admit, I am surprised that you succeeded in your mission. I''m sure Jabba will be pleased, when I find the time to tell him of your victory. For now, be content with the handful of credits I''ve generously transferred into your account.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 80, 'm20t', 'Jabba''s Ploy'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 81, 'm21d', 'I''ve recently purchased a large plot of land on Tatooine, but when I sent agents to investigate the territory, they discovered it was staked out by some squatters. The dirty locals became violent when my agents tried to drive them from my land. I acquired a bit of the desert legally, I assure you, and now I want those squatters evicted. Accept this mission, destroy the squatters'' shack, and you''ll be promptly paid.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 82, 'm21o', 'A Corellian Businessman'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 83, 'm21s', 'Good work, my loyal agent. I will now be able to build what I hope will become one of the galaxy''s most lucrative mines on Tatooine. For your role in helping me to create my empire, I have rewarded you a fair sum.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 84, 'm21t', 'The Landlord'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 85, 'm22d', 'TRANSMISSION TRANSLATED FROM HUTTESE\n\nAs you probably know by now, Watto the Toydarian, owner of the once-legendary Watto''s Junkshop and Spare Parts in Mos Espa, has fallen on hard times. Ever since he lost his fortune betting against a Jedi in the Boonta Eve Podraces, Watto has been deep in debt with just about everyone on Tatooine, including Jabba the Hutt.\n\nI''ve known Watto all my life and I''m trying to help him out. He''s not the friendliest gasgut, but he''s practically an institution in Mos Espa. And maybe I feel a little responsible for Watto''s plight, since it was my friend Anakin who won the Boonta Eve that year and left Watto without a credit to his name. Or maybe I''m just hoping that Watto will eventually give me the junkshop...\n\nWhen I heard that the Imperials were offering rewards to adventurers willing to track down and defeat some local thugs, I figured we could earn some quick credits by taking out these criminals. But Watto always wants to be the middle-man. He''s identified some of the easiest targets the Imperials have to offer and has personally guaranteed that the criminals in question will be eliminated. Now, he just needs to hire adventurers like you to kill these thugs. We''ll pay you the reward, after Watto takes his "commission" of course. It''s not a perfect set-up, but I can guarantee that Watto has selected only the best assignments. And, by dealing with Watto directly, you avoid any Imperial entanglements...  '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 86, 'm22l', 'Watto the Toydarian is hiring sub-contractors to complete Imperial missions.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 87, 'm22o', 'Wald'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 88, 'm22s', 'TRANSMISSION TRANSLATED FROM HUTTESE\n\nThings don''t look so grim around Watto''s shop these days. Surprisingly, his sub-contracting scheme seems to be working, thanks in part to you. Even after paying you your reward, Watto has enough left over to upgrade his inventory and attract new customers. And, because he''s proven to be so reliable, Watto is gaining quite a reputation with the Imperials. They''re even starting to buy parts from the junkshop.\n\nAs one of Watto''s sub-contractors, you''ve been paid for your services. Please note that, while Watto did deduct his standard commission, I threw in a few credits of my own to thank you for a job well done.\n'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 89, 'm22t', 'Toydarian Middleman'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 90, 'm23d', 'The Tatooine Reclamation Society is a coalition that includes Bestine, Mos Espa, and several other major cities on Tatooine that have joined forces with generous Imperial authorities to improve life on our desert planet. As part of the Tatooine Reclamation Project, the Tatooine Reclamation Society is planning to construct waystations between the planet''s primary settlements. Unfortunately, the proposed sites of some planned waystations have already been "settled" by bandits, thieves, squatters, and other undesirables. The Tatooine Reclamation Society is broadcasting the coordinates of these illegal settlements in the hopes that loyal Tatooine citizens will take it upon themselves to aid the Reclamation Project by destroying these "obstacles." A suitable reward will be offered to anyone who helps in our efforts to develop these essential waystations.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 91, 'm23o', 'Tatooine Reclamation Society'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 92, 'm23s', 'The Tatooine Reclamation Society is pleased to report that Phase I of our proposed waystation project is nearly complete! Criminal settlements previously blocking construction on these proposed waystations have been eliminated. Those citizens directly responsible for the destruction of these bases, hideouts, and camps have been rewarded and deserve the thanks of the entire planet!\n\nPhase II of the project - the actual construction of the waystations themselves - requires additional funding. We have been promised a substantial grant from the local Imperial prefect, but a recent military mishap near Yavin IV has evidently diverted all Imperial credits for the forseeable future. The Tatooine Reclamation Society is seeking other backers, including the generous Jabba the Hutt. We believe that the waystation project will be back on track within a few seasons! '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 93, 'm23t', 'Waystation Project'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 94, 'm24d', 'We, the Dim-U monks of Tatooine, who worship at the hairy feet of the Mighty Bantha, are seeking defenders of our hirsute idol. While Tatooine should be the domain of the bantha alone, the Horned-One must share the planet with a host of lesser beings. Most recently, the Revered Bantha has been plagued by foul thugs, dirty criminals, and murderous hunters. These bipedal vermin badger the Wandering Bantha, or kidnap His children, or even kill Him in the hopes of hanging his lush coat on their walls. The coffers of the Dim-U monastery are full, ready to serve the cause of the Enduring Bantha, in whose eyes all Universal Truths are revealed. We only await a champion to step forward and purge the Stalwart Bantha''s enemies!'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 95, 'm24o', 'Dim-U Monks of Tatooine'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 96, 'm24s', 'The Mighty Bantha, the legendary Horned-One who brings peace and tranquility to all who gaze upon Him, is safe once again! You have served the Enduring Bantha well! The Dim-U monks, loyal servants of the Wandering Bantha, are overjoyed at your success. Our coffers have been opened and you will be rewarded. The Dim-U monastery thanks you on behalf of the Horned-One, whose powerful bellow will roar your name across the desert and throughout the start so that all who worship at His hairy feet will know of your heroic deeds.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 97, 'm24t', 'Bantha Defender'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 98, 'm25d', 'The Tatooine Civilian Defense League has detected an alarming rise in the number assaults, petty thefts, and acts of vandalism in and around the habitable areas of the planet. These crimes are the work of several small bands of roving thugs. In the hopes of reducing the crime rate on Tatooine, the Tatooine Civilian Defense League is authorized to pay for the destruction of all identified criminal camps.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 99, 'm25o', 'Tatooine Civilian Defense League'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 100, 'm25s', 'Excellent work! Unlike most of our hired agents, you''ve actually succeeded in defeating those criminals who enjoy terrorizing Tatooine locals. Your reward has already been transferred to your account.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 101, 'm25t', 'Criminal Element'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 102, 'm26d', 'Swoop gangs are a terrible menace on Tatooine! They race all over the planet, outrunning the law and attacking anyone they come across. But I''ve come up with a plan to cull these criminals. When traveling together, swoop gangsters are like a pack of slice-hounds. They gain confidence from just being around one another, and easily overwhelm the weak or defenseless. But when caught one-on-one, or in small groups, the swoopers aren''t very tough. I''ve located some smaller swooper camps. Anyone who wants to prevent the swoop gangs from taking over Tatooine should sign up here! I''ll transmit coordinates to a manageable hideout, and you just take care of the rest.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 103, 'm26o', 'Swoop Hunters'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 104, 'm26s', 'I told you the swoop gangsters weren''t so tough, especially when they''re caught in small groups. Nice work taking out that base. Now, there are fewer thugs to harass the locals.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 105, 'm26t', 'Concerned citizen hiring adventurers to battle swoop gangs'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 106, 'm27d', 'Listen up, worms. I''m a leadin'' member of one of Tatooine''s most feared and respected swoop gangs. I''m not gonna say which swoop gang, because we don''t need no trouble with the Imperials. But I have a sweet deal for anyone with a blaster and an itchy trigger finger. It''s no secret the swoop gangs on Tatooine are at war. There''s a rival gang moving in on my territory, and I want to give those scurvy mynocks a surprise. Rather than send my gang out to take care of ''em, I figure I''ll offer some of you "adventurers" a chance to even the score for me. They''ll be watchin'' out for dust-blowing swoops, but a solo operator or small group of mercenaries can get in close and take out their base. I can send you one of them glowing waypoints; just follow it and attack any chuba-eating scum you find. Then burn their camp to the ground, to send a message.  '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 107, 'm27o', '"Captain Crossbones"'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 108, 'm27s', 'Hah! I knew my plan would work! Those sandmite-infested fools have been watching me and my gang for weeks, but they didn''t have an eye on you, my friend! I haven''t seen such a one-sided fight since crazy old Ben took off that Walrusman''s arm in the Mos Eisley cantina. I''ve sent some loot your way. Spend it while you can; I won''t be surprised if those swoopers retaliate... '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 109, 'm27t', 'Turf War'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 110, 'm28d', 'My brother was killed by a swooper the other day. The murderers will get away with this terrible crime if someone doesn''t step forward and wipe them out. I''m not a vigilante, but I''m looking for someone willing to deliver a little desert justice to these vermin.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 111, 'm28o', 'A Bereaved Local'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 112, 'm28s', 'By the shifting sands of Tatooine, may my brother always remain in the memories of those who loved him. And may your heroic deeds on his behalf always be part of our family history. I shall never forget that you brought my brother''s murderers to justice. Thank you.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 113, 'm28t', 'Vigilante'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 114, 'm29d', 'WANTED: Able-bodied adventurers to battle roving swoop gangs on Tatooine! \n\nTatooine''s swoop gangs are out of control! They''ve become a public menace. Tatooine authorities are willing to pay large rewards for the elimination of this threat. Those willing to accept this dangerous assignment will receive coordinates to a known swoop gang camp. The camp must be destroyed before any rewards will be processed.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 115, 'm29o', 'Mos Eisley Police Authority'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 116, 'm29s', 'We''ve received confirmation of your mission''s success. Good work. Your payment has been transferred.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 117, 'm29t', 'Swoop Gang Cleanup'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 118, 'm30d', 'The name''s Dengar. You''ve probably heard of me. I was the best swoop racer in the entire galaxy. No one could catch me. And I had a loyal gang watching my back. The past, it''s all a bit hazy now... But I know some Corellian punk ambushed me in the Agrilat Swamps on Corellia. The crash ruined my career. The Empire fixed me up right, and I''m good at killin'' now. But my old gang scattered. Treacherous space slugs, they left me for dead. Joined up with another swoop gang on Tatooine. No one leaves Dengar behind. No one. I know where the scurriers are hiding, but I''m still property of the Empire. Got a job to do. I need someone tough and mean to take out my old crew. I''ll send the coordinates when you accept this mission.  '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 119, 'm30o', 'Dengar'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 120, 'm30s', 'You''re quite the killer. Maybe you should consider getting'' fixed up by the Empire. The Imperial cutters ripped out part of my brain and replaced it with tech. I sometimes see things, hallucinate, but I''m one of the highest-paid assassins in the Outer Rim, so I ain''t complainin''. Maybe you should take the credits you just earned and have a little work done too.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 121, 'm30t', 'Old Friends'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 122, 'm31d', 'For years, an unruly band of Tusken Raiders has lived on the Mochot Steep, venturing out now and again to cause trouble around town, but never really doing any major damage. Until now. There''s another group of troublemakers that has been battling the Tuskens for supremacy of the Mochot Steep. This has stirred up major trouble. The Tuskens are out scavenging almost every night, trying to prepare themselves for the next attack. The local merchants have been suffering greatly from this little war. Now, we don''t think that the Tuskens will ever leave the Mochot Steep, which is fine with us. We just need someone to stop those new bandits from stirring up the Tuskens. Can you aid us?'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 123, 'm31o', 'Concerned Local Merchants'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 124, 'm31s', 'Congratulations! You have done the locals a great service. The Tuskens should go back to their normal behaviour and leave us alone now.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 125, 'm31t', 'Steep Struggle'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 126, 'm32d', 'Hundreds of years ago, a former employee of the Tatooine Bureau of Ethnicity and Socialization named Alkhara allied himself with a savage group of Tusken Raiders and destroyed an entire police garrison. It started a bloody feud with the Tusken Raiders that lasted for many years. He built himself a small empire and after he died his headquarters became Jabba''s Palace. While his terrible reign was ended many years ago, there are still pockets of those who believe in the anarchy that Alkhara preached. We at the Bureau would like all memory of Alkhara to be erased. We are offering a substantial reward for the removal of any known camps or bases belonging to Alkhara''s followers.\n\nTatooine Bureau of Ethnicity and Socialization  '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 127, 'm32o', 'Tatooine Bureau of Ethnicity and Socialization'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 128, 'm32s', 'The Tatooine Bureau of Ethnicity and Socialization would like to thank you for your assistance in helping to remove Alkhara from the memory of the citizens of Tatooine.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 129, 'm32t', 'Followers of Alkhara'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 130, 'm33d', 'This may not mean anything to you, but it means the world to me. I had my entire trugut collection stolen by a group of bandits. They have no idea what it''s worth and will probably just give it away for a few creds. For those who don''t know, the trugut is a Hutt form of currency that only had value on Hutt-controlled worlds. But the use of truguts on Tatooine ended with the arrival of the Empire. In the day, one trugut was worth sixteen wuipiupi, a quarter of a peggat, or ten dataries. But now, to the right collector, they are worth ten times that. I would like someone to take care of these thieves for me. They don''t deserve to hold such a rare and exquisite collection.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 131, 'm33o', 'A Collector of Rare Coins'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 132, 'm33s', 'I hope those vile sith spawns know that they paid dearly for robbing an old man. Thank you for help.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 133, 'm33t', 'Coin Collectors'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 134, 'm34d', 'This may sound strange coming from me, since I''ve no love for droids, but I need some help putting a friend of mine back together. You see, me and Ceetoo-Arfour have been making specialty drinks for a months now, and making good money all over Tatooine doing it. But recently some blasted bandits looted my hovel and trashed the place. Worst of all, they stole Ceetoo''s special mixology circuit board. I had pulled the board out to clean it, and then left it out to dry. Must have looked like an important piece of data to them, and the scum snapped it up along with some other personal belongings. Now I don''t expect you to bring back my stolen goods, but if you could take care of the sand-eating creeps that did this to me, I''ll search through the rubble and find the pieces to put Ceetoo-Arfour back together again.\n\nWuher'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 135, 'm34o', 'Wuher'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 136, 'm34s', 'Now I can go retrieve that blasted board and get this lazy bucket of bolts back to work on our latest concoction. I''d offer you a free drink, but we haven''t mastered the latest recipe yet.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 137, 'm34t', 'Wuher''s Droid Dliemma'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 138, 'm35d', 'A group of punks got me fired from my gig as the front desk clerk at the Lucky Despot hotel. I want it back. And the only way that''s going to happen is if this group of low-life bandits is never seen or heard from again. Got it?\n\nAnton '),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 139, 'm35o', 'Anton'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 140, 'm35s', 'Excellent. Now I can prove myself worthy to my old boss. I''m certain I''ll get my old job back.'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 141, 'm35t', 'Anton''s Big Break'),
('string/en/mission/mission_destroy_neutral_medium_npc_tatooine.stf', 142, 'number_of_entries', '35'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 4, 'm1t', 'Destroy Local Refueling Depot'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 8, 'm2t', 'Destroy Local Repair Station'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster that would greatly increase its firepower and accuracy. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 12, 'm3t', 'Destroy Weapons Development Lab'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 16, 'm4t', 'Wipe Out Power Droid Plant'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 17, 'm5d', 'Our informants have identified an ISB compound used for interrogations. If the stories can be believed, terrible atrocities have taken place. Destroying this foul place would send the right message to both the Empire and to citizens who lived in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. '),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 20, 'm5t', 'Destroy ISB Interrogation Compound'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 24, 'm6t', 'Destroy Sienar Warehouse'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperial bureaucracy and slow the aggressive recruitment efforts of the Imperial Navy. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! Claim your reward and may the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 28, 'm7t', 'Destroy Imperial Records'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 29, 'm8d', 'The Alliance has acquired the coordinates to an Imperial HoloNet data collection station. This station is used by Imperial Intelligence''s Analysis Bureau to coordinate surveillance efforts for the entire sector. If we take out this station, we effectively cripple Imperial Intelligence''s ability to uncover our sabotage missions and raids of Imperial depots. Can you lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 31, 'm8s', 'Bravo! Cut off the head and the body cannot survive for long. Your efforts to interrupt Imperial Intelligence''s communication to the rest of the Empire''s war machine will be instrumental in our eventual success. Your reward is well earned.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 32, 'm8t', 'Plug Up the Empire''s Ears'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 33, 'm9d', 'A small Imperial outpost is currently being used to store of seized glitterstim spice. This cargo is intended to bribe Corporate Sector Authority officials to comply with Imperial Intelligence''s requests to access confidential corporate records. The Alliance needs a few good individuals to make sure that outpost is destroyed and everything inside it is burned to the ground. '),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 35, 'm9s', 'Good! Not only have you disposed of a great deal of illegal drugs, you''ve cost Imperial Intelligence millions of credits worth of bribe money. Let''s see how eager they are to bribe the CSA now that they have to dig into their own budget. This is a great victory for the Alliance, friend.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 36, 'm9t', 'Destroy Illegal Drugs'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 37, 'm10d', 'A cargo of probe droids has just been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit sometime in the next few days and those probe droids will be transported aboard. We don''t need to tell you how much damage those probe droids can cause to the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 39, 'm10s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 40, 'm10t', 'Poke Out the Empire''s Eyes'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 41, 'm11d', 'We''ve discovered a shipment of turbolaser actuators, currently stored in an Imperial depot and scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 43, 'm11s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 44, 'm11t', 'Blow Up the Turbolasers'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 45, 'm12d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger soon. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. The coordinates will be sent when you accept the mission. May the Force be with you. '),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 47, 'm12s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 48, 'm12t', 'Orbital Mines Bad'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 49, 'm13d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 51, 'm13s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 52, 'm13t', 'Blast the Imperial Transceivers'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 53, 'm14d', 'Reports have been coming in about an amazing little MSE-6 droid. If Imperial Intelligence reports are to be believed, that tiny dynamo has led those Imperial slugs on a wild mynock chase. We want to help spread these rumors. We''ve planted a false Imperial report on the HoloNet that claims the Empire is holding the droid at a detention facility. We need a team of operatives to strike this detention facility and make it seem as if the MSE-6 droid was "rescued" by the Alliance. Can you help us embarrass the Empire further?'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 55, 'm14s', 'Excellent "rescue!" If we can get those Imperial slugs to start worrying about their MSE-6 droids, then we''ve already won this war. Keep it up.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 56, 'm14t', 'Rescue the Mouse Droid'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 57, 'm15d', 'The Empire has deployed a prefab structure in an outlying area. It appears to be an early beachhead for a diplomatic garrison. No one here knows what a diplomat would have to be diplomatic about, way out there. In any case, we need you to destroy it before the Empire can fortify it.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 59, 'm15s', 'Fast work! It''s not often we take out an Imperial garrison, even if it is just a diplomatic garrison. Actually, only the first part of one. Never mind, you deserve your reward!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 60, 'm15t', 'Diplomatic Garrison Target'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 61, 'm16d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 63, 'm16s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 64, 'm16t', 'Imperial Gunnery School'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 65, 'm17d', 'The Empire''s infrared camera lenses require the rare mineral byrothsis. These lenses require frequent specialized maintenance, and one of the maintenance facilities is nearby. By destroying the byrothsis purification facility, your team can put the Empire in the dark. Good luck!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 67, 'm17s', 'Excellent job. With their infrared lenses going cloudy, Imperial TIE fighters might be slower to see our ships. Let''s hope!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 68, 'm17t', 'Imperial Byrothsis Facility'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 69, 'm18d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 71, 'm18s', 'The Empire protects those durindfire gems the way you and I protect our dearest heirlooms. It''s amazing that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 72, 'm18t', 'Imperial Durindfire Gem Facility'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 73, 'm19d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. These engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. We''d like you to destroy the engineering compound and the Protector plans. Unfortunately, the engineers must be considered expendable.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 75, 'm19s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. Nice job!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 76, 'm19t', 'Empire Redesigning Protector Droids'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 77, 'm20d', 'The Empire is raising funds by shipping thermal detonators to local gangsters. What a bunch of hypocrites! These bombs always end up destroying innocent civilians'' property, so we want you to blow up the detonator warehouse. Be careful -- it''s got fairly heavy defenses.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 79, 'm20s', 'You did it! It''s a relief to know those detonators won''t be troubling the locals. This reward''s yours. And be sure to mention to everyone -- the Empire deals with crooks!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 80, 'm20t', 'Empire Selling Detonators to Crooks'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 81, 'm21d', 'mperial Intelligence is working on high-frequency broadcasts that burn out a droid''s restraining bolts and ruin its programming. Basically a droid gets this signal and goes berserk. Of course, any grownup can handle a rogue 3PO unit, but what about the children? Stop this weird-science research before it''s too late.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 83, 'm21s', 'Scratch one more Imperial Intelligence mad-science project. That droid idea might never have worked, but it doesn''t hurt that you made sure. Thanks!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 84, 'm21t', 'Empire Sabotaging Restraining Bolts'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 85, 'm22d', 'If you''ve fought on foot against one of those two-leg Imperial scout walkers, you know they''re dangerous. We''ve got word that a local armory is stockpiling the specialized axidite control boxes used in AT-ST command pods. You have a big chance here to interrupt a major Imperial supply chain!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 87, 'm22s', 'Thank you! That armory stockpile would have gone into dozens of Imperial walkers. Maybe hundreds. Good job!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 88, 'm22t', 'Axidite Stockpile'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 89, 'm23d', 'Dola trees are apparently sentient plants of Aruza. Never heard of them myself, but their flowers make an antibiotic syrup we use to treat local ailments. Imperial Intelligence agents stole our supply of dola flowers and plan to use them to breed a new slave race. The flowers are now useless for antibiotics. We need you to destroy them and the Imperial research lab.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 91, 'm23s', 'The dola syrup stolen by the Empire would have saved lives, but your work at least protects the dola trees from Imperial slavery. Thank you!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 92, 'm23t', 'Empire Breeding Dola Tree Slaves'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 93, 'm24d', 'the Empire is shipping in components for their GTU AV-1A Assault Armor. It''s a powered combat suit for elite troops, sort of a hovertank you can wear. We''ve never seen it in action, and we don''t want to. If you inflict enough damage to the warehouse, you may set off the explosive charges they use for the suit''s ejection system. Then get clear, fast!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 95, 'm24s', 'Those GTU power suits are expensive and tricky, so with luck we''ll never see them on this planet. '),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 96, 'm24t', 'Imperial GTU Armor Components'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 97, 'm25d', 'An Imperial Security outpost here has procured, through illegal back-channels, a shipment of neuronic whips. That''s right, slaver weapons, outlawed on every civilized world. They intend to use these brutal stun-whips for crowd control and intimidation. You must destroy the warehouse and the whips. Expect serious opposition, though.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 99, 'm25s', 'What a relief! Those neuronic whips would have caused terror far beyond mere crowd control. Thanks for destroying them.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 100, 'm25t', 'Empire Using Neuronic Terror'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 101, 'm26d', 'Maybe you''ve heard the reports of local swoop gangs with suspiciously good weaponry. We know the Empire''s COMPNOR security goons have been arming crooks in communities sympathetic to the Alliance. Now we''ve found an Imperial Army depot where COMPNOR requisitions the gang weapons. Stop this operation at its source!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 102, 'm26o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 103, 'm26s', 'That''s one more blow in the fight against gang violence. Those swoop gangs will keep endangering innocent people until we cut off their weapon supply. Good work! '),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 104, 'm26t', 'Swoop Gangs With COMPNOR Weapons'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 105, 'm27d', 'We''ve located an Imperial Army installation housing unusual ammunition: flechette microdart canisters, toxin darts, magna caster quarrels. The installation doubles as quarters for the specialists who maintain this ammo. Expect tough opposition, and stay well clear when you blow up the place.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 106, 'm27o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 107, 'm27s', 'Well done! It''s enough trouble facing blasters and AT-ATs without worrying about those deadly exotics. Here''s your reward.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 108, 'm27t', 'Exotic Ammunition Stockpile'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 109, 'm28d', 'The Empire''s covert research into planet-wide biochemical weaponry continues. Mass production of these fearsome killers require specialized reagents and catalysts. We have tracked down a facility producing purified niobarium, a poisonous chemical used in one weapons-grade process. To cut off that process, destroy the niobarium plant.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 110, 'm28o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 111, 'm28s', 'Reports are showing negligible release of niobarium from the destruction. Fine job! Please contact us again for new assignments.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_rebel_military_easy.stf', 112, 'm28t', 'Imperial Niobarium Facility'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 113, 'm29d', 'DX-343 is an industrial solvent that, on exposure into air, disperses into mist. The DX mist disrupts electronic equipment and makes breathing difficult. If our reports are correct, the Empire has stockpiled enough DX-343 to wipe out a fleet of starfighters and their pilots. Destroy the stockpile!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 114, 'm29o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 115, 'm29s', 'If the Empire had used all that DX-343, we would have been carrying starships out of the hangar in pieces, and their pilots too. Good job taking it out!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 116, 'm29t', 'Imperial DX-343 Stockpile'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 117, 'm30d', 'Hyperbaride is used for turbolaser casings. Its production generates poisonous byproducts. The Empire usually disposes of the byproducts harmlessly, but we''ve learned of a new cache in this area.We suspect they''re stockpiling this poison as a weapon. The cache is well guarded, but we want it destroyed, preferably in a ball of sterilizing flame.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 118, 'm30o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 119, 'm30s', 'If the Empire really is stockpiling hyperbaride by-products, we''d hate to imagine what they''re planning. Hope you made sure we''ll never find out.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 120, 'm30t', 'Imperial Hyperbaride Waste Dump'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 121, 'm31d', 'Get this: An Imperial mess facility got accidentally infested with Sorderian weft-worms. The Empire has decided to solve the infestation by blowing up the entire facility from orbit. Their aim in these matters is not flawless, so we''d like you to destroy the facility first. Target practice from a Star Destroyer -- we don''t need that!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 122, 'm31o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 123, 'm31s', 'Great, now we''re doing the Imperials'' work for them. What a galaxy! But thank you, and be glad we no longer have to fear those oh-so-terrible weft-worms.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 124, 'm31t', 'Imperial Weft-Worm Infestation'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 125, 'm32d', 'Astrogation computers on Imperial starships rely on probe data collated and encoded at a local astrogation station. If you destroy the astrogation facilities, the Empire must rely on outdated information when travelling in this system. But beware, these stations are always guarded!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 126, 'm32o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 127, 'm32s', 'Great job! Now we''ll hope an Imperial ship runs into a meteor shower or asteroid field it couldn''t predict.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 128, 'm32t', 'Astrogation Collation Station'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 129, 'm33d', 'The most sophisticated communication relays in the galaxy, outside Coruscant, sit aboard Imperial capital ships. Our agents within the Imperial bureaucracy have redirected a shipment of these delicate relays to a supply station here. This is our best chance to destroy a vital component of the Imperial comm apparatus. Move quickly!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 130, 'm33o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 131, 'm33s', 'Good! We must hope that the Empire''s capital ships, with hampered communications, will operate based on inferior strategy. Please check back with us for more assignments.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 132, 'm33t', 'Imperial Capital Ship Comm Relays'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 133, 'm34d', 'Empire ship designer Lira Wessex, who designed the original Star Destroyers, is apparently visiting this world on a tour of shipbuilding facilities. If we can incapacitate Wessex, the Empire will lose one of its greatest talents. Unfortunately, Wessex is here only a while, at an Imperial outpost with a strong escort. Strike fast and strike hard!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 134, 'm34o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 135, 'm34s', 'Great work! If Lira Wessex was inside that wreck, then you''ve brought a long, bad career to a belated close.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 136, 'm34t', 'Visit From Lira Wessex'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 137, 'm35d', 'The SoroSuub Corporation is a dangerous ally of the Empire. Their ships and weapons are responsible for the deaths of untold numbers of Alliance fighters. To isolate them from distribution contractors, we have begun a campaign to harry shipments of SoroSuub armaments across the galaxy. Here are coordinates for a distribution center on this world. Prepare for well-armed resistance.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 138, 'm35o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 139, 'm35s', 'Allies of the Empire are enemies of freedom. You have done well. Contact us again for the coordinates of more SoroSuub distribution centers.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 140, 'm35t', 'Disrupt SoroSuub Corporation Shipments'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 141, 'm36d', 'InCom''s superior X-wing technology is the envy of the Imperial Navy. Recently an informant tipped the Imperial Security Bureau to the location of a hidden cache of fighters. Stormtroopers descended on the place, and now five X-wings are being readied for transport to Sienar Fleet Systems. We need agents to hit the place fast. Make sure nothing is left but smoke and rubble.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 142, 'm36o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 143, 'm36s', 'Well done. All five X-wing fighters were reduced to slag. We must guard every technological advantage if we are to bring the Empire to its knees.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 144, 'm36t', 'Destroy Captured X-wing Fighters'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 145, 'm37d', 'The Alliance has placed agents inside many Imperial operations. Currently one secret operative, well-placed in the Imperial system, is under suspicion by his supervisor. We cannot afford to lose him. Therefore we are commissioning a strike team to attack the small garrison where he is stationed. The diversion will let him eliminate his supervisor and destroy evidence.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 146, 'm37o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 147, 'm37s', 'Well done. Thanks to your distraction, our secret agent was able to remove the officer who questioned his loyalty to the Empire.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 148, 'm37t', 'Assist a Secret Agent'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 149, 'm38d', 'An Imperial spy has infiltrated our supply network. He has collected dangerous information about our secret shipping routes. A probe droid recently arrived at the Imperial base at the following coordinates. We believe that the droid''s databanks contain this secret data. If we are to protect the identities of the depots and freighters that assist us, we must destroy this base at once.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 150, 'm38o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 151, 'm38s', 'We have confirmed that the probe droid was destroyed. Our supply routes are safe again. Excellent work!'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 152, 'm38t', 'Destroy an Imperial Base to Thwart a Spy'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 153, 'm39d', 'An Imperial spy is working inside Alliance operations. He has collected a list of Alliance informants and is in the process of transmitting their names to Imperial Intelligence. The list is stored at an Imperial base at the following coordinates. We need a well-armed team to destroy the base before Imperial Intelligence arrives to recover the information.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 154, 'm39o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 155, 'm39s', 'We have monitored transmissions within Imperial Intelligence. They are most displeased that you destroyed the list of Alliance informants before they could recover it. You have saved the lives of many good people. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 156, 'm39t', 'Save Alliance Informants'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 157, 'm40d', 'An Imperial spy has wrought havoc on our operations in several sectors. We do not know his identity, but we have discovered the office of Imperial Intelligence to which he reports. If we can destroy his headquarters, we can salvage many operations he has jeopardized. A team of experienced marksmen should be sufficient to knock down this Imperial site.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 158, 'm40o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 159, 'm40s', 'Skillfully done. The Alliance values capable agents like you. Contact us again soon.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 160, 'm40t', 'Take Down an Office of Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 161, 'm41d', 'Cloaking devices create no end of difficulty for Alliance blockade runners. We have tracked a shipment of hybridium ore, essential to modern cloaking systems, from Garos IV to an Imperial transfer point. The site is guarded by Imperial troops, but if we can get a blaster squad inside to level the place, we''ll take away the ability of the blockade ships to cloak themselves from our sensors.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 162, 'm41o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 163, 'm41s', 'Successes like these are stepping stones to victory over the Empire. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 164, 'm41t', 'Eliminate Fuel for Imperial Cloaking Devices'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 165, 'm42d', 'The Imperial Security Bureau''s network of civilian spies and informants is a plague on us all. The Alliance places great value on locating and terminating sites of ISB activity. We have the coordinates of one such installation and require a team to carry out an assault. Be aware that the Empire has responded to our campaign so expect considerable resistance.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 166, 'm42o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 167, 'm42s', 'You have done a superb job. The more we hamper the actions of the ISB, the closer we come to real freedom in the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 168, 'm42t', 'Terminate an Office of the Imperial Security Bureau'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 169, 'm43d', 'Propaganda is one of the Empire''s tools in oppressing the galaxy. Imperial propagandists have taken over entire news corporations. We have identified one such purveyor of deceit, and confirmed that Imperial personnel staff all of its facilities. We''d like you to form a team and smash this installation and staunch the flow of lies.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 170, 'm43o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 171, 'm43s', 'Every time we take down a center for propaganda, the people of the galaxy move closer to the truth. You have done well.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 172, 'm43t', 'Smash a Propaganda Center'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 173, 'm44d', 'One of our agents has covertly sabotaged Imperial masking codes for several uninstalled shield generators in this sector. If these generators are deployed to Imperial warships, we will have a hidden advantage should our blockade runners be spotted. Unfortunately certain factory records might betray our secret sabotage. We need agents to blow apart an Imperial maintenance base and destroy those records.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 174, 'm44o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 175, 'm44s', 'Well done! Against the military resources of the Empire we need every advantage we can get. Thank you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 176, 'm44t', 'Protect a Covert Alliance Operation'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 177, 'm45d', 'We have received word that a new security protocol has been implemented at Imperial military sites around the sector. We are staging exploratory assaults on select bases, to see what new tactics the Empire has deployed. We need small teams of marksmen or veteran individuals to assist us in this fact-finding endeavor. Leave no wall standing.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 178, 'm45o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 179, 'm45s', 'It seems no Imperial security protocol is a match for a good blaster at your side. The Alliance thanks you.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 180, 'm45t', 'Test a New Imperial Security Protocol'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 181, 'm46d', 'The Empire is not above sedating its subjects into complacency. We have discovered an installation where Imperial engineers are introducing drugs into the water supply to quell unrest in the local population. This crime must not be allowed to continue. We''d like you to blast this water-doping facility into smoke and rubble. '),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 182, 'm46o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 183, 'm46s', 'It warms the heart to see a plume of smoke rising where Imperial villainy once reigned. Very well done. Your reputation continues to rise here.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 184, 'm46t', 'Raze a Water-Doping Facility'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 185, 'm47d', 'The Imperial Security Bureau has stepped up its program to recruit troubled youths with a criminal record to do the Empire''s dirty work. We must not stand for this underhanded scheme. The program is controlled from an ISB facility at the following coordinates. We want to make an example of these ISB monsters, so leave no Imperial agent standing.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 186, 'm47o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 187, 'm47s', 'Thanks to your good work, many troubled youths will avoid the corruption of the Empire and perhaps even become good Alliance fighters in the future.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 188, 'm47t', 'Stamp Out Imperial Corruption of Youth'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 189, 'm48d', 'An Imperial officer has shown a keen aptitude for ferreting out covert Alliance agents and destroying our hidden bases. What''s worse, he is known to torture and slaughter innocents in his enforcement of Imperial edicts. He is currently inspecting a facility on this world. We need a small squad to strike this facility while this officer is present.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 190, 'm48o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 191, 'm48s', 'You have done very well. We have not yet confirmed that Commander Hrazzel was killed in your raid, but we hope his threat is now gone.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 192, 'm48t', 'Take Out a Dangerous Imperial Officer'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 193, 'm49d', 'A local notable crossed the Empire and a small garrison was placed on his land as a lesson to others. This individual has contacted the Alliance with requests to remove this garrison. Alliance High Command has decided to grant this request. We need you to hit this installation hard and leave no survivors. Inasmuch as the Empire is so fond of lessons, it is time they learned one of their own.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 194, 'm49o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 195, 'm49s', 'Nicely handled. Your skill and bravery are assets to the Alliance.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 196, 'm49t', 'Assault an Imperial Garrison'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 197, 'm50d', 'Imperial capital ships contain hyperwave signal interceptors that sound an alert just before a spacecraft comes out of hyperspace. Our spies inform us that an Imperial research laboratory has tripled the range of these hyperwave warning systems. The secret of this technology is entirely contained in the laboratory. We need a team of skilled individual to hit the place and blow it to cinders.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 198, 'm50o', ''),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 199, 'm50s', 'Splendid! Our informants assure us that it will take years for the Empire to rebuild this new technology. By then, we may have discovered some means to counter it.'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 200, 'm50t', 'Incinerate an Imperial Laboratory'),
('string/en/mission/mission_destroy_rebel_military_easy.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 4, 'm1t', 'Ground the Imperial patrols'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 8, 'm2t', 'Take out the Imperial mechanics'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable. You might need help.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 12, 'm3t', 'No new Imperial blasters'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 16, 'm4t', 'Farewell power droids'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve identified an ISB compound used for interrogations. If the stories are true, terrible atrocities have taken place there. Destroying this facility would send the right message to both the Empire and to citizens who live in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. Are you that agent? '),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 20, 'm5t', 'Take out the torturers'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 24, 'm6t', 'No more ion engines'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperials and slow their recruitment efforts. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 28, 'm7t', 'Burn Imperial records'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 29, 'm8d', 'A cargo of probe droids has been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit in the next few days and those probe droids will be transported aboard. Those probe droids are trouble for the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 31, 'm8s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 32, 'm8t', 'Take out the probe droids'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 33, 'm9d', 'We''ve discovered a shipment of turbolaser actuators stored in an Imperial depot. They are scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 35, 'm9s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 36, 'm9t', 'Pull the Star Destroyers'' teeth'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 37, 'm10d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. Can you lend a hand, citizen? '),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 39, 'm10s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 40, 'm10t', 'Take out the deadly mines'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 41, 'm11d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 43, 'm11s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 44, 'm11t', 'Knock out Imperial communications'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 45, 'm12d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 47, 'm12s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 48, 'm12t', 'No more Imperial gunners'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 49, 'm13d', 'We''ve managed to locate the Imperial Intelligence Analysis Bureau command center for this entire sector. These centers provide the intelligence reports that allow the Bureau of Operations to plan and execute strikes. It will be heavily guarded and equipped with state-of-the-art defenses. Its destruction will require an experienced team. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 51, 'm13s', 'A brilliantly executed strike! With freedom fighters like you aiding our cause, the Empire has no chance. We hope you''ll accept difficult missions from us in the future.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 52, 'm13t', 'Cripple Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 53, 'm14d', 'We''ve discovered a training facility for Imperial Intelligence''s Operations agents -- in other words, assassins. This installation has launched covert operations that have killed some of our top officers. The Alliance wants this base blasted into atoms. This will not be easy, as some of the Empire''s top agents work as trainers at this facility.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 55, 'm14s', 'Those Operations goons never knew what hit them. Bravo! You''ve done the Alliance and the galaxy a great service. You''re quickly becoming one of our top agents.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 56, 'm14t', 'Stop future assassins'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 57, 'm15d', 'Bothan spies have identified a biological weapons development lab. Intercepted transmissions indicate this facility was instrumental in developing the Candorian Plague used against Dentaal. This lab must be destroyed at any cost. Imperial security will be tight and defenses formidable. A generous reward awaits the agent who can pull this off. '),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 59, 'm15s', 'One less weapon in the Empire''s arsenal. Good work! Many worlds will sleep easier now that this plague-making lab has been destroyed.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 60, 'm15t', 'Destroy the plague-maker'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 61, 'm16d', 'A top-secret installation of the Inquisitorius, the Empire''s specialized interrogators, has been located. Many of our agents ended up there, tortured for information until they were driven mad and killed. It is said that the Inquisitors use the Force to aid in their twisted work. Commander Skywalker has personally requested that this installation be taken out. Can we call on you?'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 63, 'm16s', 'Success! You''ll be the scourge of the Empire yet! The Alliance thanks you and the galaxy is in your debt. Our reward is but a small token of our gratitude.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 64, 'm16t', 'Smash the Imperial interrogators'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 65, 'm17d', 'An Imperial garrison has received orders to execute suspected Alliance sympathizers and their families if they do not start naming Alliance spies. We need someone to wipe out the garrison before these stormtroopers can slaughter innocent civilians. Taking out a garrison, even a small one, is no easy task. These Imperial troops will be on high alert.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 67, 'm17s', 'Great job! The Empire will think twice before giving their garrisons the order to execute civilians again. Fear is not just a tool for the Empire.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 68, 'm17t', 'Save the innocent civilians'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 69, 'm18d', 'A stormtrooper training facility, renowned for producing some of the Emperor''s most fanatical legions, must be taken out. A successful strike would stand as a symbol of the Alliance''s determination to rid the galaxy of the Empire''s tyranny. The Emperor''s brainwashing techniques can''t compete with an Alliance member''s passion for freedom. '),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 71, 'm18s', 'You deserve a medal! The Emperor''s not the only one who trains crack troops and deadly soldiers. The Alliance salutes you!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 72, 'm18t', 'Destroy stormtrooper training base'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 73, 'm19d', 'Bothan spies have located an Imperial outpost housing Sith artifacts. We''ve received word that Darth Vader has ordered these artifacts delivered to him personally. If those artifacts are indeed what the Bothans claim, we must not allow them to fall into Vader''s hands. We need a strike team to go in and blow that shipment to atoms.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 75, 'm19s', 'Job well done! You are a true champion of the people. Report to us again for future assignments soon.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 76, 'm19t', 'Destroy Sith artifacts'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 77, 'm20d', 'Mercenary assassins do the Emperor''s dirty work when direct military action is politically inexpedient. We have the coordinates of an undocumented arsenal from which the Empire supplies its assassins. We need a squad of fighters to blast the place into vapor. The arsenal is garrisoned with Imperial soldiers and mercenary assassins, so be careful.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 79, 'm20s', 'Astounding work! You and your team are superior operatives, a true asset to the Alliance.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 80, 'm20t', 'Smash an arsenal for Imperial assassins'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 81, 'm21d', 'Imperial Army weapons designers have refashioned a platform-mounted flame carbine, the Czerka CZ-28 Flamestrike, for use on repulsorlift craft and cloud cars. Sheets of flame from the sky will mean grave danger for our fighters below. No matter the cost, you must render this weapons factory permanently inoperative. Prepare for harsh opposition.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 83, 'm21s', 'Impressive news! This victory represents a fundamental security that cannot be overstated. We applaud your resolve, and we wish you still greater success in the future.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 84, 'm21t', 'Imperial flamer munitions factory'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 85, 'm22d', 'The profiteers at Arakyd Industries continue to garner Imperial largesse. These parasites have contracted to build new legions of Inquisitor-series seeker droids with weaponry of considerably increased lethality. This presents a major threat to Alliance forces, and we cannot allow the factory to begin production. Assemble a large and experienced strike team and take this factory out.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 87, 'm22s', 'This is excellent news! We hope this damages Arakyd Industries profits as badly as their products have damaged our forces. We congratulate you, agent!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 88, 'm22t', 'Blast a combat droid construction plant'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 89, 'm23d', 'The Empire has established a new facility building two-legged AT-ST scout walkers. Though the labor force is entirely droid-based, the installation is well defended with Imperial troops. Our recon scout escaped only by dint of skill and luck. Assemble an experienced strike team to take out this major target.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 91, 'm23s', 'Your high reputation is well earned, agent! We have stalled the production of Imperial walkers in this area, at least for now. Your reputation continues to rise!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 92, 'm23t', 'Destroy an AT-ST assembly plant'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 93, 'm24d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 95, 'm24s', 'Durindfire gems flash brilliantly, but in Imperial hands they''re covered with blood. It''s better that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 96, 'm24t', 'Blast the gems'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 97, 'm25d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. In this compound these engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. Destroy the engineering compound and the Protector plans.'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 99, 'm25s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. You are progessing well!'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 100, 'm25t', 'Smash the Protector droids'),
('string/en/mission/mission_destroy_rebel_military_easy_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 4, 'm1t', 'Destroy Local Refueling Depot'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 8, 'm2t', 'Destroy Local Repair Station'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster that would greatly increase its firepower and accuracy. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 12, 'm3t', 'Destroy Weapons Development Lab'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 16, 'm4t', 'Wipe Out Power Droid Plant'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 17, 'm5d', 'Our informants have identified an ISB compound used for interrogations. If the stories can be believed, terrible atrocities have taken place. Destroying this foul place would send the right message to both the Empire and to citizens who lived in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. '),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 20, 'm5t', 'Destroy ISB Interrogation Compound'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 24, 'm6t', 'Destroy Sienar Warehouse'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperial bureaucracy and slow the aggressive recruitment efforts of the Imperial Navy. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! Claim your reward and may the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 28, 'm7t', 'Destroy Imperial Records'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 29, 'm8d', 'The Alliance has acquired the coordinates to an Imperial HoloNet data collection station. This station is used by Imperial Intelligence''s Analysis Bureau to coordinate surveillance efforts for the entire sector. If we take out this station, we effectively cripple Imperial Intelligence''s ability to uncover our sabotage missions and raids of Imperial depots. Can you lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 31, 'm8s', 'Bravo! Cut off the head and the body cannot survive for long. Your efforts to interrupt Imperial Intelligence''s communication to the rest of the Empire''s war machine will be instrumental in our eventual success. Your reward is well earned.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 32, 'm8t', 'Plug Up the Empire''s Ears'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 33, 'm9d', 'A small Imperial outpost is currently being used to store of seized glitterstim spice. This cargo is intended to bribe Corporate Sector Authority officials to comply with Imperial Intelligence''s requests to access confidential corporate records. The Alliance needs a few good individuals to make sure that outpost is destroyed and everything inside it is burned to the ground. '),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 35, 'm9s', 'Good! Not only have you disposed of a great deal of illegal drugs, you''ve cost Imperial Intelligence millions of credits worth of bribe money. Let''s see how eager they are to bribe the CSA now that they have to dig into their own budget. This is a great victory for the Alliance, friend.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 36, 'm9t', 'Destroy Illegal Drugs'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 37, 'm10d', 'A cargo of probe droids has just been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit sometime in the next few days and those probe droids will be transported aboard. We don''t need to tell you how much damage those probe droids can cause to the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 39, 'm10s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_rebel_military_hard.stf', 40, 'm10t', 'Poke Out the Empire''s Eyes'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 41, 'm11d', 'We''ve discovered a shipment of turbolaser actuators, currently stored in an Imperial depot and scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 43, 'm11s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 44, 'm11t', 'Blow Up the Turbolasers'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 45, 'm12d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger soon. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. The coordinates will be sent when you accept the mission. May the Force be with you. '),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 47, 'm12s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 48, 'm12t', 'Orbital Mines Bad'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 49, 'm13d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 51, 'm13s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 52, 'm13t', 'Blast the Imperial Transceivers'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 53, 'm14d', 'Reports have been coming in about an amazing little MSE-6 droid. If Imperial Intelligence reports are to be believed, that tiny dynamo has led those Imperial slugs on a wild mynock chase. We want to help spread these rumors. We''ve planted a false Imperial report on the HoloNet that claims the Empire is holding the droid at a detention facility. We need a team of operatives to strike this detention facility and make it seem as if the MSE-6 droid was "rescued" by the Alliance. Can you help us embarrass the Empire further?'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 55, 'm14s', 'Excellent "rescue!" If we can get those Imperial slugs to start worrying about their MSE-6 droids, then we''ve already won this war. Keep it up.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 56, 'm14t', 'Rescue the Mouse Droid'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 57, 'm15d', 'The Empire has deployed a prefab structure in an outlying area. It appears to be an early beachhead for a diplomatic garrison. No one here knows what a diplomat would have to be diplomatic about, way out there. In any case, we need you to destroy it before the Empire can fortify it.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 59, 'm15s', 'Fast work! It''s not often we take out an Imperial garrison, even if it is just a diplomatic garrison. Actually, only the first part of one. Never mind, you deserve your reward!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 60, 'm15t', 'Diplomatic Garrison Target'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 61, 'm16d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 63, 'm16s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 64, 'm16t', 'Imperial Gunnery School'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 65, 'm17d', 'The Empire''s infrared camera lenses require the rare mineral byrothsis. These lenses require frequent specialized maintenance, and one of the maintenance facilities is nearby. By destroying the byrothsis purification facility, your team can put the Empire in the dark. Good luck!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 67, 'm17s', 'Excellent job. With their infrared lenses going cloudy, Imperial TIE fighters might be slower to see our ships. Let''s hope!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 68, 'm17t', 'Imperial Byrothsis Facility'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 69, 'm18d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 71, 'm18s', 'The Empire protects those durindfire gems the way you and I protect our dearest heirlooms. It''s amazing that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 72, 'm18t', 'Imperial Durindfire Gem Facility'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 73, 'm19d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. These engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. We''d like you to destroy the engineering compound and the Protector plans. Unfortunately, the engineers must be considered expendable.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 75, 'm19s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. Nice job!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 76, 'm19t', 'Empire Redesigning Protector Droids'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 77, 'm20d', 'The Empire is raising funds by shipping thermal detonators to local gangsters. What a bunch of hypocrites! These bombs always end up destroying innocent civilians'' property, so we want you to blow up the detonator warehouse. Be careful -- it''s got fairly heavy defenses.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 79, 'm20s', 'You did it! It''s a relief to know those detonators won''t be troubling the locals. This reward''s yours. And be sure to mention to everyone -- the Empire deals with crooks!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 80, 'm20t', 'Empire Selling Detonators to Crooks'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 81, 'm21d', 'mperial Intelligence is working on high-frequency broadcasts that burn out a droid''s restraining bolts and ruin its programming. Basically a droid gets this signal and goes berserk. Of course, any grownup can handle a rogue 3PO unit, but what about the children? Stop this weird-science research before it''s too late.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 83, 'm21s', 'Scratch one more Imperial Intelligence mad-science project. That droid idea might never have worked, but it doesn''t hurt that you made sure. Thanks!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 84, 'm21t', 'Empire Sabotaging Restraining Bolts'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 85, 'm22d', 'If you''ve fought on foot against one of those two-leg Imperial scout walkers, you know they''re dangerous. We''ve got word that a local armory is stockpiling the specialized axidite control boxes used in AT-ST command pods. You have a big chance here to interrupt a major Imperial supply chain!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 87, 'm22s', 'Thank you! That armory stockpile would have gone into dozens of Imperial walkers. Maybe hundreds. Good job!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 88, 'm22t', 'Axidite Stockpile'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 89, 'm23d', 'Dola trees are apparently sentient plants of Aruza. Never heard of them myself, but their flowers make an antibiotic syrup we use to treat local ailments. Imperial Intelligence agents stole our supply of dola flowers and plan to use them to breed a new slave race. The flowers are now useless for antibiotics. We need you to destroy them and the Imperial research lab.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 91, 'm23s', 'The dola syrup stolen by the Empire would have saved lives, but your work at least protects the dola trees from Imperial slavery. Thank you!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 92, 'm23t', 'Empire Breeding Dola Tree Slaves'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 93, 'm24d', 'the Empire is shipping in components for their GTU AV-1A Assault Armor. It''s a powered combat suit for elite troops, sort of a hovertank you can wear. We''ve never seen it in action, and we don''t want to. If you inflict enough damage to the warehouse, you may set off the explosive charges they use for the suit''s ejection system. Then get clear, fast!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 95, 'm24s', 'Those GTU power suits are expensive and tricky, so with luck we''ll never see them on this planet. '),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 96, 'm24t', 'Imperial GTU Armor Components'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 97, 'm25d', 'An Imperial Security outpost here has procured, through illegal back-channels, a shipment of neuronic whips. That''s right, slaver weapons, outlawed on every civilized world. They intend to use these brutal stun-whips for crowd control and intimidation. You must destroy the warehouse and the whips. Expect serious opposition, though.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 99, 'm25s', 'What a relief! Those neuronic whips would have caused terror far beyond mere crowd control. Thanks for destroying them.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 100, 'm25t', 'Empire Using Neuronic Terror'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 101, 'm26d', 'Maybe you''ve heard the reports of local swoop gangs with suspiciously good weaponry. We know the Empire''s COMPNOR security goons have been arming crooks in communities sympathetic to the Alliance. Now we''ve found an Imperial Army depot where COMPNOR requisitions the gang weapons. Stop this operation at its source!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 102, 'm26o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 103, 'm26s', 'That''s one more blow in the fight against gang violence. Those swoop gangs will keep endangering innocent people until we cut off their weapon supply. Good work! '),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 104, 'm26t', 'Swoop Gangs With COMPNOR Weapons'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 105, 'm27d', 'We''ve located an Imperial Army installation housing unusual ammunition: flechette microdart canisters, toxin darts, magna caster quarrels. The installation doubles as quarters for the specialists who maintain this ammo. Expect tough opposition, and stay well clear when you blow up the place.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 106, 'm27o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 107, 'm27s', 'Well done! It''s enough trouble facing blasters and AT-ATs without worrying about those deadly exotics. Here''s your reward.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 108, 'm27t', 'Exotic Ammunition Stockpile'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 109, 'm28d', 'The Empire''s covert research into planet-wide biochemical weaponry continues. Mass production of these fearsome killers require specialized reagents and catalysts. We have tracked down a facility producing purified niobarium, a poisonous chemical used in one weapons-grade process. To cut off that process, destroy the niobarium plant.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 110, 'm28o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 111, 'm28s', 'Reports are showing negligible release of niobarium from the destruction. Fine job! Please contact us again for new assignments.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 112, 'm28t', 'Imperial Niobarium Facility'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 113, 'm29d', 'DX-343 is an industrial solvent that, on exposure into air, disperses into mist. The DX mist disrupts electronic equipment and makes breathing difficult. If our reports are correct, the Empire has stockpiled enough DX-343 to wipe out a fleet of starfighters and their pilots. Destroy the stockpile!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 114, 'm29o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 115, 'm29s', 'If the Empire had used all that DX-343, we would have been carrying starships out of the hangar in pieces, and their pilots too. Good job taking it out!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 116, 'm29t', 'Imperial DX-343 Stockpile'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 117, 'm30d', 'Hyperbaride is used for turbolaser casings. Its production generates poisonous byproducts. The Empire usually disposes of the byproducts harmlessly, but we''ve learned of a new cache in this area.We suspect they''re stockpiling this poison as a weapon. The cache is well guarded, but we want it destroyed, preferably in a ball of sterilizing flame.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 118, 'm30o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 119, 'm30s', 'If the Empire really is stockpiling hyperbaride by-products, we''d hate to imagine what they''re planning. Hope you made sure we''ll never find out.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 120, 'm30t', 'Imperial Hyperbaride Waste Dump'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 121, 'm31d', 'Get this: An Imperial mess facility got accidentally infested with Sorderian weft-worms. The Empire has decided to solve the infestation by blowing up the entire facility from orbit. Their aim in these matters is not flawless, so we''d like you to destroy the facility first. Target practice from a Star Destroyer -- we don''t need that!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 122, 'm31o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 123, 'm31s', 'Great, now we''re doing the Imperials'' work for them. What a galaxy! But thank you, and be glad we no longer have to fear those oh-so-terrible weft-worms.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 124, 'm31t', 'Imperial Weft-Worm Infestation'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 125, 'm32d', 'Astrogation computers on Imperial starships rely on probe data collated and encoded at a local astrogation station. If you destroy the astrogation facilities, the Empire must rely on outdated information when travelling in this system. But beware, these stations are always guarded!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 126, 'm32o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 127, 'm32s', 'Great job! Now we''ll hope an Imperial ship runs into a meteor shower or asteroid field it couldn''t predict.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 128, 'm32t', 'Astrogation Collation Station'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 129, 'm33d', 'The most sophisticated communication relays in the galaxy, outside Coruscant, sit aboard Imperial capital ships. Our agents within the Imperial bureaucracy have redirected a shipment of these delicate relays to a supply station here. This is our best chance to destroy a vital component of the Imperial comm apparatus. Move quickly!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 130, 'm33o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 131, 'm33s', 'Good! We must hope that the Empire''s capital ships, with hampered communications, will operate based on inferior strategy. Please check back with us for more assignments.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 132, 'm33t', 'Imperial Capital Ship Comm Relays'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 133, 'm34d', 'Empire ship designer Lira Wessex, who designed the original Star Destroyers, is apparently visiting this world on a tour of shipbuilding facilities. If we can incapacitate Wessex, the Empire will lose one of its greatest talents. Unfortunately, Wessex is here only a while, at an Imperial outpost with a strong escort. Strike fast and strike hard!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 134, 'm34o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 135, 'm34s', 'Great work! If Lira Wessex was inside that wreck, then you''ve brought a long, bad career to a belated close.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 136, 'm34t', 'Visit From Lira Wessex'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 137, 'm35d', 'The SoroSuub Corporation is a dangerous ally of the Empire. Their ships and weapons are responsible for the deaths of untold numbers of Alliance fighters. To isolate them from distribution contractors, we have begun a campaign to harry shipments of SoroSuub armaments across the galaxy. Here are coordinates for a distribution center on this world. Prepare for well-armed resistance.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 138, 'm35o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 139, 'm35s', 'Allies of the Empire are enemies of freedom. You have done well. Contact us again for the coordinates of more SoroSuub distribution centers.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 140, 'm35t', 'Disrupt SoroSuub Corporation Shipments'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 141, 'm36d', 'InCom''s superior X-wing technology is the envy of the Imperial Navy. Recently an informant tipped the Imperial Security Bureau to the location of a hidden cache of fighters. Stormtroopers descended on the place, and now five X-wings are being readied for transport to Sienar Fleet Systems. We need agents to hit the place fast. Make sure nothing is left but smoke and rubble.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 142, 'm36o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 143, 'm36s', 'Well done. All five X-wing fighters were reduced to slag. We must guard every technological advantage if we are to bring the Empire to its knees.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 144, 'm36t', 'Destroy Captured X-wing Fighters'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 145, 'm37d', 'The Alliance has placed agents inside many Imperial operations. Currently one secret operative, well-placed in the Imperial system, is under suspicion by his supervisor. We cannot afford to lose him. Therefore we are commissioning a strike team to attack the small garrison where he is stationed. The diversion will let him eliminate his supervisor and destroy evidence.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 146, 'm37o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 147, 'm37s', 'Well done. Thanks to your distraction, our secret agent was able to remove the officer who questioned his loyalty to the Empire.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 148, 'm37t', 'Assist a Secret Agent'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 149, 'm38d', 'An Imperial spy has infiltrated our supply network. He has collected dangerous information about our secret shipping routes. A probe droid recently arrived at the Imperial base at the following coordinates. We believe that the droid''s databanks contain this secret data. If we are to protect the identities of the depots and freighters that assist us, we must destroy this base at once.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 150, 'm38o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 151, 'm38s', 'We have confirmed that the probe droid was destroyed. Our supply routes are safe again. Excellent work!'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 152, 'm38t', 'Destroy an Imperial Base to Thwart a Spy'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 153, 'm39d', 'An Imperial spy is working inside Alliance operations. He has collected a list of Alliance informants and is in the process of transmitting their names to Imperial Intelligence. The list is stored at an Imperial base at the following coordinates. We need a well-armed team to destroy the base before Imperial Intelligence arrives to recover the information.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 154, 'm39o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 155, 'm39s', 'We have monitored transmissions within Imperial Intelligence. They are most displeased that you destroyed the list of Alliance informants before they could recover it. You have saved the lives of many good people. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 156, 'm39t', 'Save Alliance Informants'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 157, 'm40d', 'An Imperial spy has wrought havoc on our operations in several sectors. We do not know his identity, but we have discovered the office of Imperial Intelligence to which he reports. If we can destroy his headquarters, we can salvage many operations he has jeopardized. A team of experienced marksmen should be sufficient to knock down this Imperial site.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 158, 'm40o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 159, 'm40s', 'Skillfully done. The Alliance values capable agents like you. Contact us again soon.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 160, 'm40t', 'Take Down an Office of Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 161, 'm41d', 'Cloaking devices create no end of difficulty for Alliance blockade runners. We have tracked a shipment of hybridium ore, essential to modern cloaking systems, from Garos IV to an Imperial transfer point. The site is guarded by Imperial troops, but if we can get a blaster squad inside to level the place, we''ll take away the ability of the blockade ships to cloak themselves from our sensors.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 162, 'm41o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 163, 'm41s', 'Successes like these are stepping stones to victory over the Empire. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 164, 'm41t', 'Eliminate Fuel for Imperial Cloaking Devices'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 165, 'm42d', 'The Imperial Security Bureau''s network of civilian spies and informants is a plague on us all. The Alliance places great value on locating and terminating sites of ISB activity. We have the coordinates of one such installation and require a team to carry out an assault. Be aware that the Empire has responded to our campaign so expect considerable resistance.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 166, 'm42o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 167, 'm42s', 'You have done a superb job. The more we hamper the actions of the ISB, the closer we come to real freedom in the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 168, 'm42t', 'Terminate an Office of the Imperial Security Bureau'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 169, 'm43d', 'Propaganda is one of the Empire''s tools in oppressing the galaxy. Imperial propagandists have taken over entire news corporations. We have identified one such purveyor of deceit, and confirmed that Imperial personnel staff all of its facilities. We''d like you to form a team and smash this installation and staunch the flow of lies.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 170, 'm43o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 171, 'm43s', 'Every time we take down a center for propaganda, the people of the galaxy move closer to the truth. You have done well.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 172, 'm43t', 'Smash a Propaganda Center'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 173, 'm44d', 'One of our agents has covertly sabotaged Imperial masking codes for several uninstalled shield generators in this sector. If these generators are deployed to Imperial warships, we will have a hidden advantage should our blockade runners be spotted. Unfortunately certain factory records might betray our secret sabotage. We need agents to blow apart an Imperial maintenance base and destroy those records.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 174, 'm44o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 175, 'm44s', 'Well done! Against the military resources of the Empire we need every advantage we can get. Thank you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 176, 'm44t', 'Protect a Covert Alliance Operation'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 177, 'm45d', 'We have received word that a new security protocol has been implemented at Imperial military sites around the sector. We are staging exploratory assaults on select bases, to see what new tactics the Empire has deployed. We need small teams of marksmen or veteran individuals to assist us in this fact-finding endeavor. Leave no wall standing.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 178, 'm45o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 179, 'm45s', 'It seems no Imperial security protocol is a match for a good blaster at your side. The Alliance thanks you.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 180, 'm45t', 'Test a New Imperial Security Protocol'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 181, 'm46d', 'The Empire is not above sedating its subjects into complacency. We have discovered an installation where Imperial engineers are introducing drugs into the water supply to quell unrest in the local population. This crime must not be allowed to continue. We''d like you to blast this water-doping facility into smoke and rubble. '),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 182, 'm46o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 183, 'm46s', 'It warms the heart to see a plume of smoke rising where Imperial villainy once reigned. Very well done. Your reputation continues to rise here.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 184, 'm46t', 'Raze a Water-Doping Facility'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 185, 'm47d', 'The Imperial Security Bureau has stepped up its program to recruit troubled youths with a criminal record to do the Empire''s dirty work. We must not stand for this underhanded scheme. The program is controlled from an ISB facility at the following coordinates. We want to make an example of these ISB monsters, so leave no Imperial agent standing.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 186, 'm47o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 187, 'm47s', 'Thanks to your good work, many troubled youths will avoid the corruption of the Empire and perhaps even become good Alliance fighters in the future.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 188, 'm47t', 'Stamp Out Imperial Corruption of Youth'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 189, 'm48d', 'An Imperial officer has shown a keen aptitude for ferreting out covert Alliance agents and destroying our hidden bases. What''s worse, he is known to torture and slaughter innocents in his enforcement of Imperial edicts. He is currently inspecting a facility on this world. We need a small squad to strike this facility while this officer is present.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 190, 'm48o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 191, 'm48s', 'You have done very well. We have not yet confirmed that Commander Hrazzel was killed in your raid, but we hope his threat is now gone.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 192, 'm48t', 'Take Out a Dangerous Imperial Officer'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 193, 'm49d', 'A local notable crossed the Empire and a small garrison was placed on his land as a lesson to others. This individual has contacted the Alliance with requests to remove this garrison. Alliance High Command has decided to grant this request. We need you to hit this installation hard and leave no survivors. Inasmuch as the Empire is so fond of lessons, it is time they learned one of their own.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 194, 'm49o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 195, 'm49s', 'Nicely handled. Your skill and bravery are assets to the Alliance.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 196, 'm49t', 'Assault an Imperial Garrison'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 197, 'm50d', 'Imperial capital ships contain hyperwave signal interceptors that sound an alert just before a spacecraft comes out of hyperspace. Our spies inform us that an Imperial research laboratory has tripled the range of these hyperwave warning systems. The secret of this technology is entirely contained in the laboratory. We need a team of skilled individual to hit the place and blow it to cinders.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 198, 'm50o', ''),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 199, 'm50s', 'Splendid! Our informants assure us that it will take years for the Empire to rebuild this new technology. By then, we may have discovered some means to counter it.'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 200, 'm50t', 'Incinerate an Imperial Laboratory'),
('string/en/mission/mission_destroy_rebel_military_hard.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 4, 'm1t', 'Ground the Imperial patrols'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 8, 'm2t', 'Take out the Imperial mechanics'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable. You might need help.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 12, 'm3t', 'No new Imperial blasters'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 16, 'm4t', 'Farewell power droids'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve identified an ISB compound used for interrogations. If the stories are true, terrible atrocities have taken place there. Destroying this facility would send the right message to both the Empire and to citizens who live in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. Are you that agent? '),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 20, 'm5t', 'Take out the torturers'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 24, 'm6t', 'No more ion engines'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperials and slow their recruitment efforts. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 28, 'm7t', 'Burn Imperial records'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 29, 'm8d', 'A cargo of probe droids has been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit in the next few days and those probe droids will be transported aboard. Those probe droids are trouble for the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 31, 'm8s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 32, 'm8t', 'Take out the probe droids'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 33, 'm9d', 'We''ve discovered a shipment of turbolaser actuators stored in an Imperial depot. They are scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 35, 'm9s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 36, 'm9t', 'Pull the Star Destroyers'' teeth'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 37, 'm10d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. Can you lend a hand, citizen? '),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 39, 'm10s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 40, 'm10t', 'Take out the deadly mines'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 41, 'm11d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 43, 'm11s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 44, 'm11t', 'Knock out Imperial communications'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 45, 'm12d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 47, 'm12s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 48, 'm12t', 'No more Imperial gunners'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 49, 'm13d', 'We''ve managed to locate the Imperial Intelligence Analysis Bureau command center for this entire sector. These centers provide the intelligence reports that allow the Bureau of Operations to plan and execute strikes. It will be heavily guarded and equipped with state-of-the-art defenses. Its destruction will require an experienced team. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 51, 'm13s', 'A brilliantly executed strike! With freedom fighters like you aiding our cause, the Empire has no chance. We hope you''ll accept difficult missions from us in the future.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 52, 'm13t', 'Cripple Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 53, 'm14d', 'We''ve discovered a training facility for Imperial Intelligence''s Operations agents -- in other words, assassins. This installation has launched covert operations that have killed some of our top officers. The Alliance wants this base blasted into atoms. This will not be easy, as some of the Empire''s top agents work as trainers at this facility.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 55, 'm14s', 'Those Operations goons never knew what hit them. Bravo! You''ve done the Alliance and the galaxy a great service. You''re quickly becoming one of our top agents.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 56, 'm14t', 'Stop future assassins'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 57, 'm15d', 'Bothan spies have identified a biological weapons development lab. Intercepted transmissions indicate this facility was instrumental in developing the Candorian Plague used against Dentaal. This lab must be destroyed at any cost. Imperial security will be tight and defenses formidable. A generous reward awaits the agent who can pull this off. '),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 59, 'm15s', 'One less weapon in the Empire''s arsenal. Good work! Many worlds will sleep easier now that this plague-making lab has been destroyed.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 60, 'm15t', 'Destroy the plague-maker'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 61, 'm16d', 'A top-secret installation of the Inquisitorius, the Empire''s specialized interrogators, has been located. Many of our agents ended up there, tortured for information until they were driven mad and killed. It is said that the Inquisitors use the Force to aid in their twisted work. Commander Skywalker has personally requested that this installation be taken out. Can we call on you?'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 63, 'm16s', 'Success! You''ll be the scourge of the Empire yet! The Alliance thanks you and the galaxy is in your debt. Our reward is but a small token of our gratitude.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 64, 'm16t', 'Smash the Imperial interrogators'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 65, 'm17d', 'An Imperial garrison has received orders to execute suspected Alliance sympathizers and their families if they do not start naming Alliance spies. We need someone to wipe out the garrison before these stormtroopers can slaughter innocent civilians. Taking out a garrison, even a small one, is no easy task. These Imperial troops will be on high alert.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 67, 'm17s', 'Great job! The Empire will think twice before giving their garrisons the order to execute civilians again. Fear is not just a tool for the Empire.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 68, 'm17t', 'Save the innocent civilians'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 69, 'm18d', 'A stormtrooper training facility, renowned for producing some of the Emperor''s most fanatical legions, must be taken out. A successful strike would stand as a symbol of the Alliance''s determination to rid the galaxy of the Empire''s tyranny. The Emperor''s brainwashing techniques can''t compete with an Alliance member''s passion for freedom. '),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 71, 'm18s', 'You deserve a medal! The Emperor''s not the only one who trains crack troops and deadly soldiers. The Alliance salutes you!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 72, 'm18t', 'Destroy stormtrooper training base'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 73, 'm19d', 'Bothan spies have located an Imperial outpost housing Sith artifacts. We''ve received word that Darth Vader has ordered these artifacts delivered to him personally. If those artifacts are indeed what the Bothans claim, we must not allow them to fall into Vader''s hands. We need a strike team to go in and blow that shipment to atoms.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 74, 'm19o', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 75, 'm19s', 'Job well done! You are a true champion of the people. Report to us again for future assignments soon.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 76, 'm19t', 'Destroy Sith artifacts'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 77, 'm20d', 'Mercenary assassins do the Emperor''s dirty work when direct military action is politically inexpedient. We have the coordinates of an undocumented arsenal from which the Empire supplies its assassins. We need a squad of fighters to blast the place into vapor. The arsenal is garrisoned with Imperial soldiers and mercenary assassins, so be careful.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 79, 'm20s', 'Astounding work! You and your team are superior operatives, a true asset to the Alliance.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 80, 'm20t', 'Smash an arsenal for Imperial assassins'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 81, 'm21d', 'Imperial Army weapons designers have refashioned a platform-mounted flame carbine, the Czerka CZ-28 Flamestrike, for use on repulsorlift craft and cloud cars. Sheets of flame from the sky will mean grave danger for our fighters below. No matter the cost, you must render this weapons factory permanently inoperative. Prepare for harsh opposition.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 83, 'm21s', 'Impressive news! This victory represents a fundamental security that cannot be overstated. We applaud your resolve, and we wish you still greater success in the future.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 84, 'm21t', 'Imperial flamer munitions factory'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 85, 'm22d', 'The profiteers at Arakyd Industries continue to garner Imperial largesse. These parasites have contracted to build new legions of Inquisitor-series seeker droids with weaponry of considerably increased lethality. This presents a major threat to Alliance forces, and we cannot allow the factory to begin production. Assemble a large and experienced strike team and take this factory out.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 87, 'm22s', 'This is excellent news! We hope this damages Arakyd Industries profits as badly as their products have damaged our forces. We congratulate you, agent!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 88, 'm22t', 'Blast a combat droid construction plant'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 89, 'm23d', 'The Empire has established a new facility building two-legged AT-ST scout walkers. Though the labor force is entirely droid-based, the installation is well defended with Imperial troops. Our recon scout escaped only by dint of skill and luck. Assemble an experienced strike team to take out this major target.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 91, 'm23s', 'Your high reputation is well earned, agent! We have stalled the production of Imperial walkers in this area, at least for now. Your reputation continues to rise!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 92, 'm23t', 'Destroy an AT-ST assembly plant'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 93, 'm24d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 95, 'm24s', 'Durindfire gems flash brilliantly, but in Imperial hands they''re covered with blood. It''s better that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 96, 'm24t', 'Blast the gems'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 97, 'm25d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. In this compound these engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. Destroy the engineering compound and the Protector plans.'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 99, 'm25s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. You are progessing well!'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 100, 'm25t', 'Smash the Protector droids'),
('string/en/mission/mission_destroy_rebel_military_hard_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 4, 'm1t', 'Destroy Local Refueling Depot'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 8, 'm2t', 'Destroy Local Repair Station'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster that would greatly increase its firepower and accuracy. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 12, 'm3t', 'Destroy Weapons Development Lab'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 16, 'm4t', 'Wipe Out Power Droid Plant'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 17, 'm5d', 'Our informants have identified an ISB compound used for interrogations. If the stories can be believed, terrible atrocities have taken place. Destroying this foul place would send the right message to both the Empire and to citizens who lived in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. '),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 20, 'm5t', 'Destroy ISB Interrogation Compound'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 24, 'm6t', 'Destroy Sienar Warehouse'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperial bureaucracy and slow the aggressive recruitment efforts of the Imperial Navy. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! Claim your reward and may the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 28, 'm7t', 'Destroy Imperial Records'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 29, 'm8d', 'The Alliance has acquired the coordinates to an Imperial HoloNet data collection station. This station is used by Imperial Intelligence''s Analysis Bureau to coordinate surveillance efforts for the entire sector. If we take out this station, we effectively cripple Imperial Intelligence''s ability to uncover our sabotage missions and raids of Imperial depots. Can you lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 31, 'm8s', 'Bravo! Cut off the head and the body cannot survive for long. Your efforts to interrupt Imperial Intelligence''s communication to the rest of the Empire''s war machine will be instrumental in our eventual success. Your reward is well earned.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 32, 'm8t', 'Plug Up the Empire''s Ears'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 33, 'm9d', 'A small Imperial outpost is currently being used to store of seized glitterstim spice. This cargo is intended to bribe Corporate Sector Authority officials to comply with Imperial Intelligence''s requests to access confidential corporate records. The Alliance needs a few good individuals to make sure that outpost is destroyed and everything inside it is burned to the ground. '),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 35, 'm9s', 'Good! Not only have you disposed of a great deal of illegal drugs, you''ve cost Imperial Intelligence millions of credits worth of bribe money. Let''s see how eager they are to bribe the CSA now that they have to dig into their own budget. This is a great victory for the Alliance, friend.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 36, 'm9t', 'Destroy Illegal Drugs'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 37, 'm10d', 'A cargo of probe droids has just been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit sometime in the next few days and those probe droids will be transported aboard. We don''t need to tell you how much damage those probe droids can cause to the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 39, 'm10s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 40, 'm10t', 'Poke Out the Empire''s Eyes'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 41, 'm11d', 'We''ve discovered a shipment of turbolaser actuators, currently stored in an Imperial depot and scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 43, 'm11s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 44, 'm11t', 'Blow Up the Turbolasers'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 45, 'm12d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger soon. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. The coordinates will be sent when you accept the mission. May the Force be with you. '),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 47, 'm12s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 48, 'm12t', 'Orbital Mines Bad'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 49, 'm13d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 51, 'm13s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 52, 'm13t', 'Blast the Imperial Transceivers'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 53, 'm14d', 'Reports have been coming in about an amazing little MSE-6 droid. If Imperial Intelligence reports are to be believed, that tiny dynamo has led those Imperial slugs on a wild mynock chase. We want to help spread these rumors. We''ve planted a false Imperial report on the HoloNet that claims the Empire is holding the droid at a detention facility. We need a team of operatives to strike this detention facility and make it seem as if the MSE-6 droid was "rescued" by the Alliance. Can you help us embarrass the Empire further?'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 55, 'm14s', 'Excellent "rescue!" If we can get those Imperial slugs to start worrying about their MSE-6 droids, then we''ve already won this war. Keep it up.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 56, 'm14t', 'Rescue the Mouse Droid'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 57, 'm15d', 'The Empire has deployed a prefab structure in an outlying area. It appears to be an early beachhead for a diplomatic garrison. No one here knows what a diplomat would have to be diplomatic about, way out there. In any case, we need you to destroy it before the Empire can fortify it.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 59, 'm15s', 'Fast work! It''s not often we take out an Imperial garrison, even if it is just a diplomatic garrison. Actually, only the first part of one. Never mind, you deserve your reward!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 60, 'm15t', 'Diplomatic Garrison Target'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 61, 'm16d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 63, 'm16s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 64, 'm16t', 'Imperial Gunnery School'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 65, 'm17d', 'The Empire''s infrared camera lenses require the rare mineral byrothsis. These lenses require frequent specialized maintenance, and one of the maintenance facilities is nearby. By destroying the byrothsis purification facility, your team can put the Empire in the dark. Good luck!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 67, 'm17s', 'Excellent job. With their infrared lenses going cloudy, Imperial TIE fighters might be slower to see our ships. Let''s hope!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 68, 'm17t', 'Imperial Byrothsis Facility'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 69, 'm18d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 71, 'm18s', 'The Empire protects those durindfire gems the way you and I protect our dearest heirlooms. It''s amazing that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 72, 'm18t', 'Imperial Durindfire Gem Facility'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 73, 'm19d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. These engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. We''d like you to destroy the engineering compound and the Protector plans. Unfortunately, the engineers must be considered expendable.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 75, 'm19s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. Nice job!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 76, 'm19t', 'Empire Redesigning Protector Droids'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 77, 'm20d', 'The Empire is raising funds by shipping thermal detonators to local gangsters. What a bunch of hypocrites! These bombs always end up destroying innocent civilians'' property, so we want you to blow up the detonator warehouse. Be careful -- it''s got fairly heavy defenses.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 79, 'm20s', 'You did it! It''s a relief to know those detonators won''t be troubling the locals. This reward''s yours. And be sure to mention to everyone -- the Empire deals with crooks!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 80, 'm20t', 'Empire Selling Detonators to Crooks'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 81, 'm21d', 'mperial Intelligence is working on high-frequency broadcasts that burn out a droid''s restraining bolts and ruin its programming. Basically a droid gets this signal and goes berserk. Of course, any grownup can handle a rogue 3PO unit, but what about the children? Stop this weird-science research before it''s too late.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 83, 'm21s', 'Scratch one more Imperial Intelligence mad-science project. That droid idea might never have worked, but it doesn''t hurt that you made sure. Thanks!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 84, 'm21t', 'Empire Sabotaging Restraining Bolts'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 85, 'm22d', 'If you''ve fought on foot against one of those two-leg Imperial scout walkers, you know they''re dangerous. We''ve got word that a local armory is stockpiling the specialized axidite control boxes used in AT-ST command pods. You have a big chance here to interrupt a major Imperial supply chain!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 87, 'm22s', 'Thank you! That armory stockpile would have gone into dozens of Imperial walkers. Maybe hundreds. Good job!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 88, 'm22t', 'Axidite Stockpile'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 89, 'm23d', 'Dola trees are apparently sentient plants of Aruza. Never heard of them myself, but their flowers make an antibiotic syrup we use to treat local ailments. Imperial Intelligence agents stole our supply of dola flowers and plan to use them to breed a new slave race. The flowers are now useless for antibiotics. We need you to destroy them and the Imperial research lab.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 91, 'm23s', 'The dola syrup stolen by the Empire would have saved lives, but your work at least protects the dola trees from Imperial slavery. Thank you!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 92, 'm23t', 'Empire Breeding Dola Tree Slaves'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 93, 'm24d', 'the Empire is shipping in components for their GTU AV-1A Assault Armor. It''s a powered combat suit for elite troops, sort of a hovertank you can wear. We''ve never seen it in action, and we don''t want to. If you inflict enough damage to the warehouse, you may set off the explosive charges they use for the suit''s ejection system. Then get clear, fast!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 95, 'm24s', 'Those GTU power suits are expensive and tricky, so with luck we''ll never see them on this planet. '),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 96, 'm24t', 'Imperial GTU Armor Components'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 97, 'm25d', 'An Imperial Security outpost here has procured, through illegal back-channels, a shipment of neuronic whips. That''s right, slaver weapons, outlawed on every civilized world. They intend to use these brutal stun-whips for crowd control and intimidation. You must destroy the warehouse and the whips. Expect serious opposition, though.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 99, 'm25s', 'What a relief! Those neuronic whips would have caused terror far beyond mere crowd control. Thanks for destroying them.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 100, 'm25t', 'Empire Using Neuronic Terror'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 101, 'm26d', 'Maybe you''ve heard the reports of local swoop gangs with suspiciously good weaponry. We know the Empire''s COMPNOR security goons have been arming crooks in communities sympathetic to the Alliance. Now we''ve found an Imperial Army depot where COMPNOR requisitions the gang weapons. Stop this operation at its source!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 102, 'm26o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 103, 'm26s', 'That''s one more blow in the fight against gang violence. Those swoop gangs will keep endangering innocent people until we cut off their weapon supply. Good work! '),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 104, 'm26t', 'Swoop Gangs With COMPNOR Weapons'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 105, 'm27d', 'We''ve located an Imperial Army installation housing unusual ammunition: flechette microdart canisters, toxin darts, magna caster quarrels. The installation doubles as quarters for the specialists who maintain this ammo. Expect tough opposition, and stay well clear when you blow up the place.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 106, 'm27o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 107, 'm27s', 'Well done! It''s enough trouble facing blasters and AT-ATs without worrying about those deadly exotics. Here''s your reward.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 108, 'm27t', 'Exotic Ammunition Stockpile'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 109, 'm28d', 'The Empire''s covert research into planet-wide biochemical weaponry continues. Mass production of these fearsome killers require specialized reagents and catalysts. We have tracked down a facility producing purified niobarium, a poisonous chemical used in one weapons-grade process. To cut off that process, destroy the niobarium plant.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 110, 'm28o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 111, 'm28s', 'Reports are showing negligible release of niobarium from the destruction. Fine job! Please contact us again for new assignments.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 112, 'm28t', 'Imperial Niobarium Facility'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 113, 'm29d', 'DX-343 is an industrial solvent that, on exposure into air, disperses into mist. The DX mist disrupts electronic equipment and makes breathing difficult. If our reports are correct, the Empire has stockpiled enough DX-343 to wipe out a fleet of starfighters and their pilots. Destroy the stockpile!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 114, 'm29o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 115, 'm29s', 'If the Empire had used all that DX-343, we would have been carrying starships out of the hangar in pieces, and their pilots too. Good job taking it out!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 116, 'm29t', 'Imperial DX-343 Stockpile'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 117, 'm30d', 'Hyperbaride is used for turbolaser casings. Its production generates poisonous byproducts. The Empire usually disposes of the byproducts harmlessly, but we''ve learned of a new cache in this area.We suspect they''re stockpiling this poison as a weapon. The cache is well guarded, but we want it destroyed, preferably in a ball of sterilizing flame.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 118, 'm30o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 119, 'm30s', 'If the Empire really is stockpiling hyperbaride by-products, we''d hate to imagine what they''re planning. Hope you made sure we''ll never find out.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 120, 'm30t', 'Imperial Hyperbaride Waste Dump'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 121, 'm31d', 'Get this: An Imperial mess facility got accidentally infested with Sorderian weft-worms. The Empire has decided to solve the infestation by blowing up the entire facility from orbit. Their aim in these matters is not flawless, so we''d like you to destroy the facility first. Target practice from a Star Destroyer -- we don''t need that!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 122, 'm31o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 123, 'm31s', 'Great, now we''re doing the Imperials'' work for them. What a galaxy! But thank you, and be glad we no longer have to fear those oh-so-terrible weft-worms.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 124, 'm31t', 'Imperial Weft-Worm Infestation'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 125, 'm32d', 'Astrogation computers on Imperial starships rely on probe data collated and encoded at a local astrogation station. If you destroy the astrogation facilities, the Empire must rely on outdated information when travelling in this system. But beware, these stations are always guarded!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 126, 'm32o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 127, 'm32s', 'Great job! Now we''ll hope an Imperial ship runs into a meteor shower or asteroid field it couldn''t predict.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 128, 'm32t', 'Astrogation Collation Station'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 129, 'm33d', 'The most sophisticated communication relays in the galaxy, outside Coruscant, sit aboard Imperial capital ships. Our agents within the Imperial bureaucracy have redirected a shipment of these delicate relays to a supply station here. This is our best chance to destroy a vital component of the Imperial comm apparatus. Move quickly!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 130, 'm33o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 131, 'm33s', 'Good! We must hope that the Empire''s capital ships, with hampered communications, will operate based on inferior strategy. Please check back with us for more assignments.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 132, 'm33t', 'Imperial Capital Ship Comm Relays'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 133, 'm34d', 'Empire ship designer Lira Wessex, who designed the original Star Destroyers, is apparently visiting this world on a tour of shipbuilding facilities. If we can incapacitate Wessex, the Empire will lose one of its greatest talents. Unfortunately, Wessex is here only a while, at an Imperial outpost with a strong escort. Strike fast and strike hard!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 134, 'm34o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 135, 'm34s', 'Great work! If Lira Wessex was inside that wreck, then you''ve brought a long, bad career to a belated close.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 136, 'm34t', 'Visit From Lira Wessex'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 137, 'm35d', 'The SoroSuub Corporation is a dangerous ally of the Empire. Their ships and weapons are responsible for the deaths of untold numbers of Alliance fighters. To isolate them from distribution contractors, we have begun a campaign to harry shipments of SoroSuub armaments across the galaxy. Here are coordinates for a distribution center on this world. Prepare for well-armed resistance.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 138, 'm35o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 139, 'm35s', 'Allies of the Empire are enemies of freedom. You have done well. Contact us again for the coordinates of more SoroSuub distribution centers.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 140, 'm35t', 'Disrupt SoroSuub Corporation Shipments'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 141, 'm36d', 'InCom''s superior X-wing technology is the envy of the Imperial Navy. Recently an informant tipped the Imperial Security Bureau to the location of a hidden cache of fighters. Stormtroopers descended on the place, and now five X-wings are being readied for transport to Sienar Fleet Systems. We need agents to hit the place fast. Make sure nothing is left but smoke and rubble.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 142, 'm36o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 143, 'm36s', 'Well done. All five X-wing fighters were reduced to slag. We must guard every technological advantage if we are to bring the Empire to its knees.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 144, 'm36t', 'Destroy Captured X-wing Fighters'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 145, 'm37d', 'The Alliance has placed agents inside many Imperial operations. Currently one secret operative, well-placed in the Imperial system, is under suspicion by his supervisor. We cannot afford to lose him. Therefore we are commissioning a strike team to attack the small garrison where he is stationed. The diversion will let him eliminate his supervisor and destroy evidence.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 146, 'm37o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 147, 'm37s', 'Well done. Thanks to your distraction, our secret agent was able to remove the officer who questioned his loyalty to the Empire.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 148, 'm37t', 'Assist a Secret Agent'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 149, 'm38d', 'An Imperial spy has infiltrated our supply network. He has collected dangerous information about our secret shipping routes. A probe droid recently arrived at the Imperial base at the following coordinates. We believe that the droid''s databanks contain this secret data. If we are to protect the identities of the depots and freighters that assist us, we must destroy this base at once.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 150, 'm38o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 151, 'm38s', 'We have confirmed that the probe droid was destroyed. Our supply routes are safe again. Excellent work!'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 152, 'm38t', 'Destroy an Imperial Base to Thwart a Spy'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 153, 'm39d', 'An Imperial spy is working inside Alliance operations. He has collected a list of Alliance informants and is in the process of transmitting their names to Imperial Intelligence. The list is stored at an Imperial base at the following coordinates. We need a well-armed team to destroy the base before Imperial Intelligence arrives to recover the information.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 154, 'm39o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 155, 'm39s', 'We have monitored transmissions within Imperial Intelligence. They are most displeased that you destroyed the list of Alliance informants before they could recover it. You have saved the lives of many good people. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 156, 'm39t', 'Save Alliance Informants'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 157, 'm40d', 'An Imperial spy has wrought havoc on our operations in several sectors. We do not know his identity, but we have discovered the office of Imperial Intelligence to which he reports. If we can destroy his headquarters, we can salvage many operations he has jeopardized. A team of experienced marksmen should be sufficient to knock down this Imperial site.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 158, 'm40o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 159, 'm40s', 'Skillfully done. The Alliance values capable agents like you. Contact us again soon.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 160, 'm40t', 'Take Down an Office of Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 161, 'm41d', 'Cloaking devices create no end of difficulty for Alliance blockade runners. We have tracked a shipment of hybridium ore, essential to modern cloaking systems, from Garos IV to an Imperial transfer point. The site is guarded by Imperial troops, but if we can get a blaster squad inside to level the place, we''ll take away the ability of the blockade ships to cloak themselves from our sensors.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 162, 'm41o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 163, 'm41s', 'Successes like these are stepping stones to victory over the Empire. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 164, 'm41t', 'Eliminate Fuel for Imperial Cloaking Devices'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 165, 'm42d', 'The Imperial Security Bureau''s network of civilian spies and informants is a plague on us all. The Alliance places great value on locating and terminating sites of ISB activity. We have the coordinates of one such installation and require a team to carry out an assault. Be aware that the Empire has responded to our campaign so expect considerable resistance.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 166, 'm42o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 167, 'm42s', 'You have done a superb job. The more we hamper the actions of the ISB, the closer we come to real freedom in the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 168, 'm42t', 'Terminate an Office of the Imperial Security Bureau'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 169, 'm43d', 'Propaganda is one of the Empire''s tools in oppressing the galaxy. Imperial propagandists have taken over entire news corporations. We have identified one such purveyor of deceit, and confirmed that Imperial personnel staff all of its facilities. We''d like you to form a team and smash this installation and staunch the flow of lies.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 170, 'm43o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 171, 'm43s', 'Every time we take down a center for propaganda, the people of the galaxy move closer to the truth. You have done well.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 172, 'm43t', 'Smash a Propaganda Center'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 173, 'm44d', 'One of our agents has covertly sabotaged Imperial masking codes for several uninstalled shield generators in this sector. If these generators are deployed to Imperial warships, we will have a hidden advantage should our blockade runners be spotted. Unfortunately certain factory records might betray our secret sabotage. We need agents to blow apart an Imperial maintenance base and destroy those records.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 174, 'm44o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 175, 'm44s', 'Well done! Against the military resources of the Empire we need every advantage we can get. Thank you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 176, 'm44t', 'Protect a Covert Alliance Operation'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 177, 'm45d', 'We have received word that a new security protocol has been implemented at Imperial military sites around the sector. We are staging exploratory assaults on select bases, to see what new tactics the Empire has deployed. We need small teams of marksmen or veteran individuals to assist us in this fact-finding endeavor. Leave no wall standing.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 178, 'm45o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 179, 'm45s', 'It seems no Imperial security protocol is a match for a good blaster at your side. The Alliance thanks you.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 180, 'm45t', 'Test a New Imperial Security Protocol'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 181, 'm46d', 'The Empire is not above sedating its subjects into complacency. We have discovered an installation where Imperial engineers are introducing drugs into the water supply to quell unrest in the local population. This crime must not be allowed to continue. We''d like you to blast this water-doping facility into smoke and rubble. '),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 182, 'm46o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 183, 'm46s', 'It warms the heart to see a plume of smoke rising where Imperial villainy once reigned. Very well done. Your reputation continues to rise here.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 184, 'm46t', 'Raze a Water-Doping Facility'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 185, 'm47d', 'The Imperial Security Bureau has stepped up its program to recruit troubled youths with a criminal record to do the Empire''s dirty work. We must not stand for this underhanded scheme. The program is controlled from an ISB facility at the following coordinates. We want to make an example of these ISB monsters, so leave no Imperial agent standing.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 186, 'm47o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 187, 'm47s', 'Thanks to your good work, many troubled youths will avoid the corruption of the Empire and perhaps even become good Alliance fighters in the future.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 188, 'm47t', 'Stamp Out Imperial Corruption of Youth'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 189, 'm48d', 'An Imperial officer has shown a keen aptitude for ferreting out covert Alliance agents and destroying our hidden bases. What''s worse, he is known to torture and slaughter innocents in his enforcement of Imperial edicts. He is currently inspecting a facility on this world. We need a small squad to strike this facility while this officer is present.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 190, 'm48o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 191, 'm48s', 'You have done very well. We have not yet confirmed that Commander Hrazzel was killed in your raid, but we hope his threat is now gone.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 192, 'm48t', 'Take Out a Dangerous Imperial Officer'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 193, 'm49d', 'A local notable crossed the Empire and a small garrison was placed on his land as a lesson to others. This individual has contacted the Alliance with requests to remove this garrison. Alliance High Command has decided to grant this request. We need you to hit this installation hard and leave no survivors. Inasmuch as the Empire is so fond of lessons, it is time they learned one of their own.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 194, 'm49o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 195, 'm49s', 'Nicely handled. Your skill and bravery are assets to the Alliance.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 196, 'm49t', 'Assault an Imperial Garrison'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 197, 'm50d', 'Imperial capital ships contain hyperwave signal interceptors that sound an alert just before a spacecraft comes out of hyperspace. Our spies inform us that an Imperial research laboratory has tripled the range of these hyperwave warning systems. The secret of this technology is entirely contained in the laboratory. We need a team of skilled individual to hit the place and blow it to cinders.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 198, 'm50o', ''),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 199, 'm50s', 'Splendid! Our informants assure us that it will take years for the Empire to rebuild this new technology. By then, we may have discovered some means to counter it.'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 200, 'm50t', 'Incinerate an Imperial Laboratory'),
('string/en/mission/mission_destroy_rebel_military_medium.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 4, 'm1t', 'Ground the Imperial patrols'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 8, 'm2t', 'Take out the Imperial mechanics'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable. You might need help.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 12, 'm3t', 'No new Imperial blasters'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 16, 'm4t', 'Farewell power droids'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve identified an ISB compound used for interrogations. If the stories are true, terrible atrocities have taken place there. Destroying this facility would send the right message to both the Empire and to citizens who live in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. Are you that agent? '),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 20, 'm5t', 'Take out the torturers'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 24, 'm6t', 'No more ion engines'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperials and slow their recruitment efforts. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 28, 'm7t', 'Burn Imperial records'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 29, 'm8d', 'A cargo of probe droids has been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit in the next few days and those probe droids will be transported aboard. Those probe droids are trouble for the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 31, 'm8s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 32, 'm8t', 'Take out the probe droids'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 33, 'm9d', 'We''ve discovered a shipment of turbolaser actuators stored in an Imperial depot. They are scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 35, 'm9s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 36, 'm9t', 'Pull the Star Destroyers'' teeth'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 37, 'm10d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. Can you lend a hand, citizen? '),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 39, 'm10s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 40, 'm10t', 'Take out the deadly mines'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 41, 'm11d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 43, 'm11s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 44, 'm11t', 'Knock out Imperial communications'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 45, 'm12d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 47, 'm12s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 48, 'm12t', 'No more Imperial gunners'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 49, 'm13d', 'We''ve managed to locate the Imperial Intelligence Analysis Bureau command center for this entire sector. These centers provide the intelligence reports that allow the Bureau of Operations to plan and execute strikes. It will be heavily guarded and equipped with state-of-the-art defenses. Its destruction will require an experienced team. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 51, 'm13s', 'A brilliantly executed strike! With freedom fighters like you aiding our cause, the Empire has no chance. We hope you''ll accept difficult missions from us in the future.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 52, 'm13t', 'Cripple Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 53, 'm14d', 'We''ve discovered a training facility for Imperial Intelligence''s Operations agents -- in other words, assassins. This installation has launched covert operations that have killed some of our top officers. The Alliance wants this base blasted into atoms. This will not be easy, as some of the Empire''s top agents work as trainers at this facility.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 55, 'm14s', 'Those Operations goons never knew what hit them. Bravo! You''ve done the Alliance and the galaxy a great service. You''re quickly becoming one of our top agents.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 56, 'm14t', 'Stop future assassins'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 57, 'm15d', 'Bothan spies have identified a biological weapons development lab. Intercepted transmissions indicate this facility was instrumental in developing the Candorian Plague used against Dentaal. This lab must be destroyed at any cost. Imperial security will be tight and defenses formidable. A generous reward awaits the agent who can pull this off. '),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 59, 'm15s', 'One less weapon in the Empire''s arsenal. Good work! Many worlds will sleep easier now that this plague-making lab has been destroyed.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 60, 'm15t', 'Destroy the plague-maker'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 61, 'm16d', 'A top-secret installation of the Inquisitorius, the Empire''s specialized interrogators, has been located. Many of our agents ended up there, tortured for information until they were driven mad and killed. It is said that the Inquisitors use the Force to aid in their twisted work. Commander Skywalker has personally requested that this installation be taken out. Can we call on you?'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 63, 'm16s', 'Success! You''ll be the scourge of the Empire yet! The Alliance thanks you and the galaxy is in your debt. Our reward is but a small token of our gratitude.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 64, 'm16t', 'Smash the Imperial interrogators'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 65, 'm17d', 'An Imperial garrison has received orders to execute suspected Alliance sympathizers and their families if they do not start naming Alliance spies. We need someone to wipe out the garrison before these stormtroopers can slaughter innocent civilians. Taking out a garrison, even a small one, is no easy task. These Imperial troops will be on high alert.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 67, 'm17s', 'Great job! The Empire will think twice before giving their garrisons the order to execute civilians again. Fear is not just a tool for the Empire.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 68, 'm17t', 'Save the innocent civilians'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 69, 'm18d', 'A stormtrooper training facility, renowned for producing some of the Emperor''s most fanatical legions, must be taken out. A successful strike would stand as a symbol of the Alliance''s determination to rid the galaxy of the Empire''s tyranny. The Emperor''s brainwashing techniques can''t compete with an Alliance member''s passion for freedom. '),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 71, 'm18s', 'You deserve a medal! The Emperor''s not the only one who trains crack troops and deadly soldiers. The Alliance salutes you!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 72, 'm18t', 'Destroy stormtrooper training base'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 73, 'm19d', 'Bothan spies have located an Imperial outpost housing Sith artifacts. We''ve received word that Darth Vader has ordered these artifacts delivered to him personally. If those artifacts are indeed what the Bothans claim, we must not allow them to fall into Vader''s hands. We need a strike team to go in and blow that shipment to atoms.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 75, 'm19s', 'Job well done! You are a true champion of the people. Report to us again for future assignments soon.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 76, 'm19t', 'Destroy Sith artifacts'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 77, 'm20d', 'Mercenary assassins do the Emperor''s dirty work when direct military action is politically inexpedient. We have the coordinates of an undocumented arsenal from which the Empire supplies its assassins. We need a squad of fighters to blast the place into vapor. The arsenal is garrisoned with Imperial soldiers and mercenary assassins, so be careful.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 79, 'm20s', 'Astounding work! You and your team are superior operatives, a true asset to the Alliance.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 80, 'm20t', 'Smash an arsenal for Imperial assassins'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 81, 'm21d', 'Imperial Army weapons designers have refashioned a platform-mounted flame carbine, the Czerka CZ-28 Flamestrike, for use on repulsorlift craft and cloud cars. Sheets of flame from the sky will mean grave danger for our fighters below. No matter the cost, you must render this weapons factory permanently inoperative. Prepare for harsh opposition.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 83, 'm21s', 'Impressive news! This victory represents a fundamental security that cannot be overstated. We applaud your resolve, and we wish you still greater success in the future.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 84, 'm21t', 'Imperial flamer munitions factory'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 85, 'm22d', 'The profiteers at Arakyd Industries continue to garner Imperial largesse. These parasites have contracted to build new legions of Inquisitor-series seeker droids with weaponry of considerably increased lethality. This presents a major threat to Alliance forces, and we cannot allow the factory to begin production. Assemble a large and experienced strike team and take this factory out.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 87, 'm22s', 'This is excellent news! We hope this damages Arakyd Industries profits as badly as their products have damaged our forces. We congratulate you, agent!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 88, 'm22t', 'Blast a combat droid construction plant'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 89, 'm23d', 'The Empire has established a new facility building two-legged AT-ST scout walkers. Though the labor force is entirely droid-based, the installation is well defended with Imperial troops. Our recon scout escaped only by dint of skill and luck. Assemble an experienced strike team to take out this major target.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 91, 'm23s', 'Your high reputation is well earned, agent! We have stalled the production of Imperial walkers in this area, at least for now. Your reputation continues to rise!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 92, 'm23t', 'Destroy an AT-ST assembly plant'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 93, 'm24d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 95, 'm24s', 'Durindfire gems flash brilliantly, but in Imperial hands they''re covered with blood. It''s better that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 96, 'm24t', 'Blast the gems'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 97, 'm25d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. In this compound these engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. Destroy the engineering compound and the Protector plans.'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 99, 'm25s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. You are progessing well!'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 100, 'm25t', 'Smash the Protector droids'),
('string/en/mission/mission_destroy_rebel_military_medium_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 1, 'm1d', 'A local man was duped by the Empire into betraying his father, who had been an informant for the Alliance, and as a "reward" was forced to watch his father''s execution. Since that incident, this poor wretch has been drinking himself into a stupor and bad-mouthing the Empire. We''ve just learned that a gang of COMPNOR goons, who''ve been known to take the law into their own hands, have decided to burn the man''s home while he sleeps off another drinking binge inside. The man''s family will be asleep inside as well. We need a trusted agent to strike COMPNOR''s outpost first and save this unfortunate man''s family.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 2, 'm1o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 3, 'm1s', 'Good work! We''ll get this poor man''s family out of this place and to somewhere safe. We''ll get this unfortunate clean and sober too. We understand he''s actually quite a skilled technician. We sure could use more of those.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 4, 'm1t', 'Stop COMPNOR Goons'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 5, 'm2d', 'These COMPNOR enforcers are at it again. They''ve convinced themselves that a sweet old citizen, who loves baking for the local children, is actually supplying the Alliance with food. This ridiculous notion is going to cost this kind lady her life. We''re planning on relocating this woman to some place where she can bake all she wants. But we need someone to strike the COMPNOR enforcers'' outpost and make sure they don''t harm this woman or anyone else.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 6, 'm2o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 7, 'm2s', 'The Alliance thanks you! You didn''t just save this one sweet old woman, you''ve put something into motion that the Empire will not be able to stop: open defiance of the New Order. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 8, 'm2t', 'Stop COMPNOR Enforcers'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 9, 'm3d', 'Local authorities, who cooperate with the Empire to hunt down Alliance cells, are about to receive upgraded weapons and sensors. We need to hit the secret depot where these materials await distribution. The depot should have minimal defenses, because they don''t expect an Alliance attack. We will, of course, reward anyone who succeeds in this mission.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 10, 'm3o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 11, 'm3s', 'Now this will even things up. The last thing we needed was a bunch of over-enthusiastic security goons armed with E-11 blasters. The Alliance is happy to pay this reward, thanks.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 12, 'm3t', 'Local Security Weapons'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 13, 'm4d', 'COMPNOR has granted local security''s request and has sent a shipment of sensors and tracking devices to aid in spying on citizens. We know where this shipment is being held and need it taken out. We don''t approve of the Empire spying on its citizenry. This strike will have to be fast and precise. There''s a decent reward for anyone that succeeds.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 14, 'm4o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 15, 'm4s', 'Job well done, citizen! Fewer trackers out there means less work for us. We have our hands full fighting the Imperial war machine, so the last thing we need to worry about is COMPNOR toadies.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 16, 'm4t', 'Snooping Devices'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 17, 'm5d', 'A brave citizen group intends to hold an anti-Imperial rally to voice their anger over recent atrocities perpetrated by COMPNOR enforcers. ISB has supplied its enforcers with glop grenades. We need someone to destroy this cache of crowd-control weapons before the demonstration. Can you aid the Alliance?'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 18, 'm5o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 19, 'm5s', 'Bravo! The rally can go on as planned. We''ll keep an eye out for those enforcers, though; they might cause trouble in other ways. We hope you consider working for us again in the near future.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 20, 'm5t', 'Sabotage Glop Grenades'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 21, 'm6d', 'The Commission for the Preservation of the New Order has opened a new surgical facility, called an armamentarium. Their philosophy is, "Instill civic spirit through brain modification." The stories that we''ve heard would curdle your heart. Don''t let this armamentarium commit new atrocities against our citizens!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 22, 'm6o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 23, 'm6s', 'What a relief to know that COMPNOR''s twisted braincrafters have met justice. Please accept this reward, and our thanks!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 24, 'm6t', 'COMPNOR Surgical Facility'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 25, 'm7d', 'I''m writing this before attacking an Imperial base. If you''re reading it, I must have died. Galactic politics is over my head, but the jerks who killed my family and destroyed my home are based at these coordinates. I want someone who hates the Empire to do what I couldn''t: make them pay! At least I managed to set up a sensor, so as soon as it detects the target''s destruction, you can return here for your reward. It''s all the savings I had, but don''t worry -- I don''t need it any more.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 26, 'm7o', 'An Alliance Pilot, Now Deceased'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 27, 'm7s', 'If you''re reading this, I guess the sensor reported success. I only wish I''d lived to see you succeed where I failed. Take your reward, and live better than I did!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 28, 'm7t', 'Last Will of a Junior Pilot'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 29, 'm8d', 'Imperial Intelligence has dispatched a hive of moon moths, tiny surveillance droids, to spy on this area. These moon moths flutter around and plant microdot homing beacons. At the attached coordinates you will find a small, covert Intelligence installation that maintains and refuels these droids. Please dispose of it.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 30, 'm8o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 31, 'm8s', 'Those moon moths were an endless nuisance. Thank you for eliminating their maintenance station, and please accept this reward.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 32, 'm8t', 'Moon Moth Installation'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 33, 'm9d', 'An Imperial Security Bureau lab is trying to develop sound signals that can remotely reprogram our R-2 astromech droids on the fly. A simple recording of these sounds could theoretically turn a hangar-full of R2s into the Empire''s spies. Sounds highly speculative, but there are precedents, like the ixlls of Da Soocha. We''d like someone to silence that ISB laboratory before it makes much noise.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 34, 'm9o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 35, 'm9s', 'A fine job! We have no reports that the Empire has used this sound technology, so it looks like that effort has quieted down. Here''s your reward!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 36, 'm9t', 'Can Mere Sounds Reprogram a Droid?'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 37, 'm10d', 'An astromech droid reported seeing Imperial agents tampering with our ship refueling tanks. We checked the tanks and found them doped with slow-acting corrosive chemicals. If we''d used this fuel, our ship engines would eventually short out, possibly in deep space. We have tracked the agents to a small covert installation, and we need someone to get rid of them.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 38, 'm10o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 39, 'm10s', 'We appreciate your fine work! Our starfighters will run safely because of your efforts.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 40, 'm10t', 'Stop Imperial Fuel Saboteurs'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 41, 'm11d', 'The Empire uses Cybot Galactica LIN demolitionmechs to lay detonite anti-personnel charges. We have located a local contractor that provides the specialized cogs used in the LIN model''s rotation track. Without these cogs, the entire unit is useless. Destruction of the supplier will hamper Imperial logistics. Move quickly, before the Empire fortifies the building!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 42, 'm11o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 43, 'm11s', 'Nice work. We''ll be seeing fewer LIN demolitionmechs in this area because of your work. Here''s your reward, and call us again!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 44, 'm11t', 'Mine-layer Droid Parts Factory'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 45, 'm12d', 'The Alliance has secured valuable materials from several ore companies on the planet Excarga. These corporations make a pretty credit by defying the Empire. But now Imperial Security has captured a datadisk with information they can use to destroy our trade with Excarga. You must destroy the intelligence center where they are analyzing the disk. Hurry!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 46, 'm12o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 47, 'm12s', 'That''s a relief. With that disk gone, we can still use Excarga as a source of strategic minerals.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 48, 'm12t', 'Excargan Ore Company Data'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 49, 'm13d', 'The Empire administers its extensive prison and detention facilities using LAACDocs, Legal Authorization for Advanced Confinement Documents. LAAC prisoners aren''t usually hardened criminals but Alliance sympathizers. Targeting LAAC data storage facilities hampers the Imperial system of torture and oppression with minimal risk. Destroy the backup LAACDoc storage facility at these coordinates, then report back here. Good luck!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 50, 'm13o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 51, 'm13s', 'A fine exercise, well executed. LAACDoc backups are as numberless as the trees on Naboo, but it always helps to wipe them where we find them. Thanks!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 52, 'm13t', 'LAACDoc Storage Facility'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 53, 'm14d', 'We''ve learned of an insidious COMPNOR plot aimed at destroying Alliance morale. They''re locating households sympathetic to the Alliance, then poison their food supplies with thetametabuterin, or "theta," a tasteless chemical that induces insanity. Destroy the theta cache at these coordinates, and help keep our food supplies safe!'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 54, 'm14o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 55, 'm14s', 'Good. Now people can eat braised Wroonian flycatcher without fear of psychosis. Thanks, and check with us for more work soon.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 56, 'm14t', 'COMPNOR Theta Poisoning Scheme'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 57, 'm15d', 'The Imperial Games may seem like a goodwill event to foster harmony among diverse star systems, but they are in fact an exercise in Imperial propaganda, exploiting the prowess of honest sportsmen to serve an evil master. We have learned that the games are scheduled to be held right here in the not-too-distant future. A small station has been erected to initiate the preliminary planning. We want to see it taken out. The coordinates will follow this message. A few soldiers have been stationed there for security purposes, so don''t think this will be a trivial job. Use caution and report back to us at once.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 58, 'm15o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 59, 'm15s', 'Propaganda can be deadlier than any laser. You have done well today.'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 60, 'm15t', 'Imperial Games Planning Center'),
('string/en/mission/mission_destroy_rebel_non_military_easy.stf', 61, 'number_of_entries', '15'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 4, 'm1t', 'Ground Imperial Patrols'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 8, 'm2t', 'Take Out Imperial Mechanics'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable. You might need help.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 12, 'm3t', 'No New Imperial Blasters'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 16, 'm4t', 'Farewell, Power Droids'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve identified an ISB compound used for interrogations. If the stories are true, terrible atrocities have taken place there. Destroying this facility would send the right message to both the Empire and to citizens who live in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. Are you that agent? '),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 20, 'm5t', 'Take Out Torturers'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 24, 'm6t', 'No More Ion Engines'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperials and slow their recruitment efforts. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 28, 'm7t', 'Burn Imperial Records'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 29, 'm8d', 'A cargo of probe droids has been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit in the next few days and those probe droids will be transported aboard. Those probe droids are trouble for the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 31, 'm8s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 32, 'm8t', 'Take Out Probe Droids'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 33, 'm9d', 'We''ve discovered a shipment of turbolaser actuators stored in an Imperial depot. They are scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 35, 'm9s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 36, 'm9t', 'Pull Star Destroyers'' Teeth'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 37, 'm10d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. Can you lend a hand, citizen? '),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 39, 'm10s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 40, 'm10t', 'Take Out Deadly Mines'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 41, 'm11d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 43, 'm11s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 44, 'm11t', 'Knock Out Imperial Communications'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 45, 'm12d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 47, 'm12s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 48, 'm12t', 'No More Imperial Gunners'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 49, 'm13d', 'We''ve managed to locate the Imperial Intelligence Analysis Bureau command center for this entire sector. These centers provide the intelligence reports that allow the Bureau of Operations to plan and execute strikes. It will be heavily guarded and equipped with state-of-the-art defenses. Its destruction will require an experienced team. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 51, 'm13s', 'A brilliantly executed strike! With freedom fighters like you aiding our cause, the Empire has no chance. We hope you''ll accept difficult missions from us in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 52, 'm13t', 'Cripple Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 53, 'm14d', 'We''ve discovered a training facility for Imperial Intelligence''s Operations agents -- in other words, assassins. This installation has launched covert operations that have killed some of our top officers. The Alliance wants this base blasted into atoms. This will not be easy, as some of the Empire''s top agents work as trainers at this facility.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 55, 'm14s', 'Those Operations goons never knew what hit them. Bravo! You''ve done the Alliance and the galaxy a great service. You''re quickly becoming one of our top agents.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 56, 'm14t', 'Stop Future Assassins'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 57, 'm15d', 'Bothan spies have identified a biological weapons development lab. Intercepted transmissions indicate this facility was instrumental in developing the Candorian Plague used against Dentaal. This lab must be destroyed at any cost. Imperial security will be tight and defenses formidable. A generous reward awaits the agent who can pull this off. '),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 59, 'm15s', 'One less weapon in the Empire''s arsenal. Good work! Many worlds will sleep easier now that this plague-making lab has been destroyed.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 60, 'm15t', 'Destroy Plague-Maker'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 61, 'm16d', 'A top-secret installation of the Inquisitorius, the Empire''s specialized interrogators, has been located. Many of our agents ended up there, tortured for information until they were driven mad and killed. It is said that the Inquisitors use the Force to aid in their twisted work. Commander Skywalker has personally requested that this installation be taken out. Can we call on you?'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 63, 'm16s', 'Success! You''ll be the scourge of the Empire yet! The Alliance thanks you and the galaxy is in your debt. Our reward is but a small token of our gratitude.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 64, 'm16t', 'Smash Imperial Interrogators');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 65, 'm17d', 'An Imperial garrison has received orders to execute suspected Alliance sympathizers and their families if they do not start naming Alliance spies. We need someone to wipe out the garrison before these stormtroopers can slaughter innocent civilians. Taking out a garrison, even a small one, is no easy task. These Imperial troops will be on high alert.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 67, 'm17s', 'Great job! The Empire will think twice before giving their garrisons the order to execute civilians again. Fear is not just a tool for the Empire.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 68, 'm17t', 'Save Innocent Civilians'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 69, 'm18d', 'A stormtrooper training facility, renowned for producing some of the Emperor''s most fanatical legions, must be taken out. A successful strike would stand as a symbol of the Alliance''s determination to rid the galaxy of the Empire''s tyranny. The Emperor''s brainwashing techniques can''t compete with an Alliance member''s passion for freedom. '),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 71, 'm18s', 'You deserve a medal! The Emperor''s not the only one who trains crack troops and deadly soldiers. The Alliance salutes you!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 72, 'm18t', 'Destroy Stormtrooper Training Base'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 73, 'm19d', 'Bothan spies have located an Imperial outpost housing Sith artifacts. We''ve received word that Darth Vader has ordered these artifacts delivered to him personally. If those artifacts are indeed what the Bothans claim, we must not allow them to fall into Vader''s hands. We need a strike team to go in and blow that shipment to atoms.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 75, 'm19s', 'Job well done! You are a true champion of the people. Report to us again for future assignments soon.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 76, 'm19t', 'Destroy Sith Artifacts'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 77, 'm20d', 'Mercenary assassins do the Emperor''s dirty work when direct military action is politically inexpedient. We have the coordinates of an undocumented arsenal from which the Empire supplies its assassins. We need a squad of fighters to blast the place into vapor. The arsenal is garrisoned with Imperial soldiers and mercenary assassins, so be careful.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 79, 'm20s', 'Astounding work! You and your team are superior operatives, a true asset to the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 80, 'm20t', 'Smash Arsenal For Imperial Assassins'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 81, 'm21d', 'Imperial Army weapons designers have refashioned a platform-mounted flame carbine, the Czerka CZ-28 Flamestrike, for use on repulsorlift craft and cloud cars. Sheets of flame from the sky will mean grave danger for our fighters below. No matter the cost, you must render this weapons factory permanently inoperative. Prepare for harsh opposition.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 83, 'm21s', 'Impressive news! This victory represents a fundamental security that cannot be overstated. We applaud your resolve, and we wish you still greater success in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 84, 'm21t', 'Imperial Flamer Munitions Factory'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 85, 'm22d', 'The profiteers at Arakyd Industries continue to garner Imperial largesse. These parasites have contracted to build new legions of Inquisitor-series seeker droids with weaponry of considerably increased lethality. This presents a major threat to Alliance forces, and we cannot allow the factory to begin production. Assemble a large and experienced strike team and take this factory out.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 87, 'm22s', 'This is excellent news! We hope this damages Arakyd Industries profits as badly as their products have damaged our forces. We congratulate you, agent!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 88, 'm22t', 'Blast Combat Droid Plant'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 89, 'm23d', 'The Empire has established a new facility building two-legged AT-ST scout walkers. Though the labor force is entirely droid-based, the installation is well defended with Imperial troops. Our recon scout escaped only by dint of skill and luck. Assemble an experienced strike team to take out this major target.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 91, 'm23s', 'Your high reputation is well earned, agent! We have stalled the production of Imperial walkers in this area, at least for now. Your reputation continues to rise!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 92, 'm23t', 'Destroy AT-ST Assembly Plant'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 93, 'm24d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 95, 'm24s', 'Durindfire gems flash brilliantly, but in Imperial hands they''re covered with blood. It''s better that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 96, 'm24t', 'Blast Durindfire Gems'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 97, 'm25d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. In this compound these engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. Destroy the engineering compound and the Protector plans.'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 99, 'm25s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. You are progessing well!'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 100, 'm25t', 'Smash Protector Droids'),
('string/en/mission/mission_destroy_rebel_non_military_easy_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 1, 'm1d', 'We''ve managed to locate the Imperial Intelligence Analysis Bureau command center for this entire sector. These centers process millions of intercepted messages and prepare the intelligence reports that allow the Bureau of Operation to plan and execute strikes. This installation, like others of its kind, is heavily guarded and equipped with state-of-the-art defenses. Its destruction will require an experienced team. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 2, 'm1o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 3, 'm1s', 'A brilliantly executed strike! With freedom fighters like you aiding our cause, the Empire has no chance of victory. We hope you''ll accept difficult missions from us in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 4, 'm1t', 'Communication Command Center'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 5, 'm2d', 'We''ve discovered a training facility for Imperial Intelligence''s Operations agents -- in other words, assassins. This installation has launched covert operations that have killed some of our top officers. The Alliance wants this base blasted into atoms. This will not be easy, as some of the Empire''s top agents work as trainers at this facility. Success against this target would insure your fame in the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 6, 'm2o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 7, 'm2s', 'Those Operations goons never knew what hit them. Bravo! You''ve done the Alliance and the galaxy a great service. You''re quickly becoming one of our top agents.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 8, 'm2t', 'Assassin Training Base'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 9, 'm3d', 'Bothan spies have identified a demented Grand Moff''s biological weapons development lab on this planet. Intercepted transmissions indicate this facility was instrumental in developing the Candorian Plague used against Dentaal. This lab must be destroyed at any cost. Imperial security will be tight and defenses formidable. A substantial reward awaits the agent who can pull this off. '),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 10, 'm3o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 11, 'm3s', 'One less weapon in the Empire''s arsenal. Good work! Many worlds will sleep easier now that this plague-making lab has been destroyed. You are a champion of the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 12, 'm3t', 'Biological Weapons Lab'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 13, 'm4d', 'A top-secret installation of the Inquisitorius, the Empire''s secretive division of specialized interrogators, has suddenly become not quite so top-secret. Many spies captured by the Empire ended up here, tortured for information until they were driven mad and killed. It is said that the Inquisitors use the Force to aid in their twisted work. Commander Skywalker has personally requested that this installation be taken out. We need an experienced agent to assemble a strike team. These Inquisitors are the stuff of nightmares, and the facility is sure to be a chamber of horrors.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 14, 'm4o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 15, 'm4s', 'Success! You''ll be the scourge of the Empire yet! The Alliance thanks you and the galaxy is in your debt. Our reward is but a small token of our gratitude.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 16, 'm4t', 'Interrogation Facility'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 17, 'm5d', 'An Imperial garrison has just received orders to execute suspected Alliance sympathizers and their families if they do not start naming Alliance members and spies. We need someone to wipe out the garrison before these stormtroopers can slaughter innocent civilians. This order, directly from Mon Mothma, will require an experienced strike team. Taking out a garrison, even a small one, is no easy task. These Imperial troops will be on high alert. Remember, the Alliance desperately needs your help to save innocent lives.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 18, 'm5o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 19, 'm5s', 'Great job! The Empire will think twice before giving their garrisons the order to execute civilians again. Fear is not just a tool for the Empire; it''s an effective weapon for us as well. We will make those Imperial killers fear for their lives.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 20, 'm5t', 'Imperial Garrison'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 21, 'm6d', 'A stormtrooper training facility, renowned for producing some of the Emperor''s most fanatical legions, must be taken out. We don''t need to tell you how dangerous this mission will be. A successful strike would stand as a symbol of the Alliance''s determination to rid the galaxy of the Empire''s tyranny. Show the Emperor that his brainwashing techniques can''t compete with an Alliance member''s passion for freedom. '),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 22, 'm6o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 23, 'm6s', 'You deserve a medal! The Emperor''s not the only one who trains crack troops and deadly soldiers. The Alliance salutes you!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 24, 'm6t', 'Stormtrooper Training Base'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 25, 'm7d', 'The last transmission we received from one of our top special forces agents pinpointed a storm commando training facility. Then our operative disappeared. We''ve had no word from her since, and we assume she''s dead -- or in the hands of storm commando interrogators, which is as good as dead. We need this facility hit hard, hit fast, and burned to the ground. Your record is impressive, but we''re not sure you''ve faced anything like this before. The stormtroopers who guard these bases are the best the Empire has to offer.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 26, 'm7o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 27, 'm7s', 'Congratulations! Your success will make you a hero of the Alliance. The Empire will be looking for you too, so you''ll have to work even harder. This makes us very happy.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 28, 'm7t', 'Storm Commando Training Base'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 29, 'm8d', 'Bothan spies have informed us that an Imperial outpost is holding Sith artifacts recently unearthed in some undisclosed system. Despite informants who claim that the system is simply a legend, we suspect it was Korriban. We''ve received word that Darth Vader has ordered these artifacts delivered to him personally. If those artifacts are indeed what the Bothans claim, we must not allow them to fall into Vader''s hands. We need a strike team to go in and blow that shipment to atoms. The garrison commander has assigned extra security, so this mission will be extremely dangerous.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 30, 'm8o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 31, 'm8s', 'Job well done! If the Jedi will not return to safeguard the galaxy, we must insure the Sith do not return to terrorize it. You are a true champion of the people. Report to us again for future assignments soon.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 32, 'm8t', 'Sith Artifacts'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 33, 'm9d', 'Sienar Fleet Systems has delivered a prototype TIE starfighter to an Imperial fortification. We understand that this design was based on Lord Vader''s TIE fighter used against our pilots at the Battle of Yavin. The prototype is scheduled for atmosphere testing, and the Empire has assigned top pilots to the emplacement. This emplacement must be destroyed, along with the prototype inside. Strike for the Alliance!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 34, 'm9o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 35, 'm9s', 'So much for their prototype TIE fighter! Good work, agent. The Alliance is quite proud and wishes to use your services again.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 36, 'm9t', 'Emplacement Housing Prototype Starfighter'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 37, 'm10d', 'General Maximilian Veers is inspecting an Imperial outpost believed to be training AT-AT pilots. To take out an Imperial outpost would itself be wonderful, but the chance to eliminate one of the Empire''s most feared officers makes this target an absolute must. We need a highly experienced strike team accustomed to impossible odds. Your victory would be a great blow to the Empire and an amazing triumph for the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 38, 'm10o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 39, 'm10s', 'Good job, agent! We can only hope that General Veers was at the outpost when it was obliterated. If so, this will go down as a major victory for the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 40, 'm10t', 'AT-AT Pilot Training Outpost'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 41, 'm11d', 'Imperial Army weapons designers have refashioned a platform-mounted flame carbine, the Czerka CZ-28 Flamestrike, for use on repulsorlift craft and cloud cars. Sheets of flame from the sky will mean grave danger for our fighters below. No matter the cost, you must render this weapons factory permanently inoperative. Prepare for harsh opposition.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 42, 'm11o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 43, 'm11s', 'Impressive news! This victory represents a fundamental security that cannot be overstated. We applaud your resolve, and we wish you still greater success in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 44, 'm11t', 'Imperial Flamer Munitions Factory'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 45, 'm12d', 'The profiteers at Arakyd Industries continue to garner Imperial largesse. These amoral corporate parasites have contracted to build new legions of Inquisitor-series seeker droids with weaponry of considerably increased lethality. These droids present a major threat to Alliance forces, and we cannot allow the factory to begin production. Assemble a large and experienced strike team, for the Arakyd plant enjoys substantial Imperial protection.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 46, 'm12o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 47, 'm12s', 'This is excellent news! We hope this damages Arakyd Industries profits as badly as their products have damaged our forces. We congratulate you, agent!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 48, 'm12t', 'Imperial Combat Droid Construction Plant'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 49, 'm13d', 'The Empire has established a new facility building two-legged AT-ST scout walkers. Though the labor force is entirely droid-based, the installation is well defended with Imperial troops. Our recon scout escaped only by dint of skill and luck. Assemble an experienced strike team to take out this major target.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 50, 'm13o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 51, 'm13s', 'Your high reputation is well earned, agent! We have stalled the production of Imperial walkers in this area, at least for now. Your reputation continues to rise!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 52, 'm13t', 'AT-ST Assembly Plant'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 53, 'm14d', 'Imperial logistics dictate that vehicular power cores should be stored in widely dispersed locations. This prevents an explosive accident with a single core from destroying the entire sector''s core allotment. In the case at hand, however, terrain and other factors conspired to force a larger construction project. This mission offers a rare opportunity to destroy the Empire''s power core supply for a large planetary region. For this reason, expect heavy opposition. We advise a large and experienced strike team. Good luck!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 54, 'm14o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 55, 'm14s', 'A superb job! This will force the Empire to commit substantial resources to replenishing its power cores across the world. We salute your victory!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 56, 'm14t', 'Power Core Storage Depot'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 57, 'm15d', 'Certain Imperial-class Star Destroyer replacement parts must be constructed in a planetary gravitational field, and are then ordinarily shipped offworld promptly. But our brave Alliance pilots have harried Empire supply lines to good effect. The Empire has been unable to land shuttles at a hidden and well-guarded factory, and they are coping with an inventory backlog. If you assemble a large strike team -- quickly! -- you can destroy the parts and thereby cripple their maintenance regimen, with potentially disastrous consequences for the fleet.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 58, 'm15o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 59, 'm15s', 'Success! In destroying necessary parts, you have done as much damage to this sector''s Star Destroyer fleet as any squadron of Y-wing fighters. A tremendous blow against the Empire!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 60, 'm15t', 'Star Destroyer Replacement Parts'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 61, 'm16d', 'Do you know of the Kuat Drive Yards? KDY builds the Empire''s Star Destroyers and supplies hyperdrives for all its ships. Our informants have learned that a Kuat noble merchant, visiting here on business, has brought a new experimental hyperdrive. Information is sketchy, but this drive is apparently smaller and lighter than anything the galaxy has seen. Imperial engineers are studying the unit under high security. We want you to destroy the prototype and the installation that houses it. You''ll need a good team and good luck!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 62, 'm16o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 63, 'm16s', 'Excellent news! This prototype was said to be the only one of its type. With luck, we have kept the Empire from developing a new class of hyperspace-capable ships. Congratulations, agent!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 64, 'm16t', 'Prototype Imperial Hyperdrive'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 65, 'm17d', 'It defies reason, but the Empire is apparently experimenting with gravity well projectors on a planetary surface. If true, this scheme ranks with the destruction of Alderaan for brutality and foolhardiness. A strong gravity well, projected on this world''s surface, would cause tremendous earthquakes at best, and at worst could deform the entire globe! Assemble an experienced strike team, assault the facility housing this projector, and destroy it utterly!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 66, 'm17o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 67, 'm17s', 'You have saved this world, for the moment. We must hope the Empire soon sees the folly of this scheme. Meanwhile, our profoundest thanks.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 68, 'm17t', 'Gravity Well Projector'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 69, 'm18d', 'Mercenary assassins do the Emperor''s dirty work when direct military action is politically inexpedient. We have the coordinates of an undocumented arsenal from which the Empire supplies its assassins. We need a squad of fighters to blast the place into vapor. The arsenal is garrisoned with Imperial soldiers and mercenary assassins, so operatives should expect maximum resistance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 70, 'm18o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 71, 'm18s', 'Astounding work! You and your team are superior operatives, a true asset to the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 72, 'm18t', 'Arsenal for Imperial Assassins'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 73, 'm19d', 'Professional shockball boasts the galaxy''s best athletes, a fact that is not lost on Imperial Intelligence. Alliance agents have uncovered a sinister operation in which top shockball players are subjected to thought control drugs and used as unwitting Imperial assassins and saboteurs. These galaxy-class athletes make deadly operatives. Thanks to our Bothan spies, we have located the headquarters for this insidious operation. We require a strike team to hit the place hard. The site is heavily guarded and may house several athlete assassins. Arm yourselves well and proceed with the utmost caution.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 74, 'm19o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 75, 'm19s', 'We grieve for the exploited athletes who died in this action, but their fellow shockball players will no longer be victimized by the Empire. You have done good work.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 76, 'm19t', 'Imperial Mind Control Plot'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 77, 'm20d', 'The Imperial Military Oversight Commission reviews battle data and locates weaknesses in Imperial tactics. The IMOC is secretly meeting on this world to examine data newly recovered from the Battle of Yavin. Our spies assure us that this data has not yet been duplicated. Because the data concerns Alliance fighter tactics, this is an excellent opportunity to rob the Empire of a dangerous battlefield advantage. We need to organize a highly mobile assault force to hit the heavily guarded IMOC meeting facility and destroy these data tapes.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 78, 'm20o', 'Mon Mothma of Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 79, 'm20s', 'Your victory will benefit many space battles to come. Commander Skywalker sends his congratulations on your success.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 80, 'm20t', 'Imperial Battle Data'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 81, 'm21d', 'A new Imperial Prefect is arriving on this world. His cruelty far eclipses his predecessor. By good fortune, a protocol droid owned by Commander Skywalker has learned the coordinates of a secret transfer point where the prefect will await his planetside shuttle. The prefect''s security here will be weakened, though he still brings with him a formidable Imperial contingent. We need our best fighters to wipe out the way station and prevent this ruthless despot from seizing control of the planet.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 82, 'm21o', 'General Dodonna of Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 83, 'm21s', 'Your timing and marksmanship are a credit to the Alliance. Imperial transmissions suggest that the prefect is dead. Maybe now the Empire will think twice about subjecting the people to the cruelty of madmen like him.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 84, 'm21t', 'Incoming Imperial Prefect'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 85, 'm22d', 'Imperial probe droids have infiltrated several systems where our agents might be threatened. We''ve got sensor ships looking for them, but in the meantime we have located the Imperial station receiving the probe droids reports. If we can knock out this communications center, it should buy us time to track down the droids and safeguard our operations in this sector. The receiving station will be heavily defended. Only our most experienced fighters should participate in this strike.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 86, 'm22o', 'Leia Organa of Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 87, 'm22s', 'Now we can protect our operations in this sector until we locate all the probe droids. You''ve done well.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 88, 'm22t', 'Imperial Probe Droid Station'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 89, 'm23d', 'The Empire has scheduled a new superlaser for construction on the surface of this planet. This weapon may pose an even greater danger than the Death Star itself. The Imperial Science Division postulates that the weapon''s beam can be directed into hyperspace via black hole lenses, allowing the superlaser to fire at planets in other star systems. This possibility has grave implications for the entire galaxy. By striking hard, we may be able to delay progress until the project''s opponents in the Imperial Navy will sink it completely. We need a team of our best agents to swarm the project''s headquarters and blast it into dust. We dare not fail. If the hyperspace superlaser is completed, the future looks bleak indeed.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 90, 'm23o', 'General Rieekan of Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 91, 'm23s', 'Good work. Our spies tell us that the upper ranks of the Imperial Navy are making the most of this setback to the superlaser project. Soon the entire project may be disbanded. Your victory has given hope for the future of the galaxy.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 92, 'm23t', 'Superlaser Installation'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 93, 'm24d', 'The Empire has struck us a terrible blow. Some of our highest leaders have been captured near the Ison Corridor and transported to a secret holding facility. Fortunately our spies have located the facility and we have arranged their evacuation. Now we require now a strike team to attack the facility, providing a distraction while our insiders free the prisoners. The attack should continue until the facility is destroyed. The site is extremely well defended, but this must not discourage us. We have reason to believe Lord Vader himself is traveling to the planet in his Super-class Star Destroyer. If we do not rescue our people immediately, their doom is assured.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 94, 'm24o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 95, 'm24s', 'Disaster has been averted! Thanks to your bold attack on the Imperial holding facility, we managed to spirit away our captive leaders moments before Lord Vader arrived. Our spies report that Vader was displeased with the failure and swiftly relieved the facility officer of his command.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 96, 'm24t', 'Rescue Captured Alliance Leaders'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 97, 'm25d', 'One of our top agents has been trapped by Lord Vader, and we must act immediately to save him! Our secret operative, code-named "the Mouse," had nearly completed his sabotage of an Imperial garrison when Darth Vader arrived in person to close the well-planned trap. Now our agent is barricaded deep inside the garrison and fighting for his life. We must scramble a strike team immediately to engage the Imperial forces and allow the Mouse to make his escape. We can show no mercy. Vader has deployed additional stormtroopers to the garrison, and we must not be lured into a prolonged battle. Be fast and deadly, or one of our finest will fall!'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 98, 'm25o', 'Alliance High Command'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 99, 'm25s', 'The Mouse is saved! While your team battled Imperial forces on the surface, he escaped through an underground maintenance passage. Rumor has it that he confronted Lord Vader himself in the gloom of the tunnel, and that only quick thinking saved him from capture; but this sequence of events has not been confirmed. Nevertheless, your action was successful and you have the undying gratitude of the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 100, 'm25t', 'Aid a Top Alliance Agent'),
('string/en/mission/mission_destroy_rebel_non_military_hard.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 4, 'm1t', 'Ground Imperial Patrols'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 8, 'm2t', 'Take Out Imperial Mechanics'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable. You might need help.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 12, 'm3t', 'No New Imperial Blasters'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 16, 'm4t', 'Farewell, Power Droids'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve identified an ISB compound used for interrogations. If the stories are true, terrible atrocities have taken place there. Destroying this facility would send the right message to both the Empire and to citizens who live in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. Are you that agent? '),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 20, 'm5t', 'Take Out Torturers'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 24, 'm6t', 'No More Ion Engines'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperials and slow their recruitment efforts. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 28, 'm7t', 'Burn Imperial Records'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 29, 'm8d', 'A cargo of probe droids has been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit in the next few days and those probe droids will be transported aboard. Those probe droids are trouble for the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 31, 'm8s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 32, 'm8t', 'Take Out Probe Droids'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 33, 'm9d', 'We''ve discovered a shipment of turbolaser actuators stored in an Imperial depot. They are scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 35, 'm9s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 36, 'm9t', 'Pull Star Destroyers'' Teeth'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 37, 'm10d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. Can you lend a hand, citizen? '),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 39, 'm10s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 40, 'm10t', 'Take Out Deadly Mines'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 41, 'm11d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 43, 'm11s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 44, 'm11t', 'Knock Out Imperial Communications'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 45, 'm12d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 47, 'm12s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 48, 'm12t', 'No More Imperial Gunners'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 49, 'm13d', 'We''ve managed to locate the Imperial Intelligence Analysis Bureau command center for this entire sector. These centers provide the intelligence reports that allow the Bureau of Operations to plan and execute strikes. It will be heavily guarded and equipped with state-of-the-art defenses. Its destruction will require an experienced team. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 51, 'm13s', 'A brilliantly executed strike! With freedom fighters like you aiding our cause, the Empire has no chance. We hope you''ll accept difficult missions from us in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 52, 'm13t', 'Cripple Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 53, 'm14d', 'We''ve discovered a training facility for Imperial Intelligence''s Operations agents -- in other words, assassins. This installation has launched covert operations that have killed some of our top officers. The Alliance wants this base blasted into atoms. This will not be easy, as some of the Empire''s top agents work as trainers at this facility.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 55, 'm14s', 'Those Operations goons never knew what hit them. Bravo! You''ve done the Alliance and the galaxy a great service. You''re quickly becoming one of our top agents.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 56, 'm14t', 'Stop Future Assassins'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 57, 'm15d', 'Bothan spies have identified a biological weapons development lab. Intercepted transmissions indicate this facility was instrumental in developing the Candorian Plague used against Dentaal. This lab must be destroyed at any cost. Imperial security will be tight and defenses formidable. A generous reward awaits the agent who can pull this off. '),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 59, 'm15s', 'One less weapon in the Empire''s arsenal. Good work! Many worlds will sleep easier now that this plague-making lab has been destroyed.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 60, 'm15t', 'Destroy Plague-Maker'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 61, 'm16d', 'A top-secret installation of the Inquisitorius, the Empire''s specialized interrogators, has been located. Many of our agents ended up there, tortured for information until they were driven mad and killed. It is said that the Inquisitors use the Force to aid in their twisted work. Commander Skywalker has personally requested that this installation be taken out. Can we call on you?'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 63, 'm16s', 'Success! You''ll be the scourge of the Empire yet! The Alliance thanks you and the galaxy is in your debt. Our reward is but a small token of our gratitude.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 64, 'm16t', 'Smash Imperial Interrogators'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 65, 'm17d', 'An Imperial garrison has received orders to execute suspected Alliance sympathizers and their families if they do not start naming Alliance spies. We need someone to wipe out the garrison before these stormtroopers can slaughter innocent civilians. Taking out a garrison, even a small one, is no easy task. These Imperial troops will be on high alert.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 67, 'm17s', 'Great job! The Empire will think twice before giving their garrisons the order to execute civilians again. Fear is not just a tool for the Empire.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 68, 'm17t', 'Save Innocent Civilians'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 69, 'm18d', 'A stormtrooper training facility, renowned for producing some of the Emperor''s most fanatical legions, must be taken out. A successful strike would stand as a symbol of the Alliance''s determination to rid the galaxy of the Empire''s tyranny. The Emperor''s brainwashing techniques can''t compete with an Alliance member''s passion for freedom. '),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 71, 'm18s', 'You deserve a medal! The Emperor''s not the only one who trains crack troops and deadly soldiers. The Alliance salutes you!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 72, 'm18t', 'Destroy Stormtrooper Training Base'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 73, 'm19d', 'Bothan spies have located an Imperial outpost housing Sith artifacts. We''ve received word that Darth Vader has ordered these artifacts delivered to him personally. If those artifacts are indeed what the Bothans claim, we must not allow them to fall into Vader''s hands. We need a strike team to go in and blow that shipment to atoms.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 75, 'm19s', 'Job well done! You are a true champion of the people. Report to us again for future assignments soon.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 76, 'm19t', 'Destroy Sith Artifacts'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 77, 'm20d', 'Mercenary assassins do the Emperor''s dirty work when direct military action is politically inexpedient. We have the coordinates of an undocumented arsenal from which the Empire supplies its assassins. We need a squad of fighters to blast the place into vapor. The arsenal is garrisoned with Imperial soldiers and mercenary assassins, so be careful.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 79, 'm20s', 'Astounding work! You and your team are superior operatives, a true asset to the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 80, 'm20t', 'Smash Arsenal For Imperial Assassins'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 81, 'm21d', 'Imperial Army weapons designers have refashioned a platform-mounted flame carbine, the Czerka CZ-28 Flamestrike, for use on repulsorlift craft and cloud cars. Sheets of flame from the sky will mean grave danger for our fighters below. No matter the cost, you must render this weapons factory permanently inoperative. Prepare for harsh opposition.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 83, 'm21s', 'Impressive news! This victory represents a fundamental security that cannot be overstated. We applaud your resolve, and we wish you still greater success in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 84, 'm21t', 'Imperial Flamer Munitions Factory'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 85, 'm22d', 'The profiteers at Arakyd Industries continue to garner Imperial largesse. These parasites have contracted to build new legions of Inquisitor-series seeker droids with weaponry of considerably increased lethality. This presents a major threat to Alliance forces, and we cannot allow the factory to begin production. Assemble a large and experienced strike team and take this factory out.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 87, 'm22s', 'This is excellent news! We hope this damages Arakyd Industries profits as badly as their products have damaged our forces. We congratulate you, agent!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 88, 'm22t', 'Blast Combat Droid Plant'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 89, 'm23d', 'The Empire has established a new facility building two-legged AT-ST scout walkers. Though the labor force is entirely droid-based, the installation is well defended with Imperial troops. Our recon scout escaped only by dint of skill and luck. Assemble an experienced strike team to take out this major target.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 91, 'm23s', 'Your high reputation is well earned, agent! We have stalled the production of Imperial walkers in this area, at least for now. Your reputation continues to rise!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 92, 'm23t', 'Destroy AT-ST Assembly Plant'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 93, 'm24d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 95, 'm24s', 'Durindfire gems flash brilliantly, but in Imperial hands they''re covered with blood. It''s better that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 96, 'm24t', 'Blast Durindfire Gems'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 97, 'm25d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. In this compound these engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. Destroy the engineering compound and the Protector plans.'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 99, 'm25s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. You are progessing well!'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 100, 'm25t', 'Smash Protector Droids'),
('string/en/mission/mission_destroy_rebel_non_military_hard_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 2, 'm1o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 4, 'm1t', 'Local Rebel Refueling Depot'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 6, 'm2o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 8, 'm2t', 'Local Rebel Repair Station'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster that would greatly increase its firepower and accuracy. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable. You might need help.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 10, 'm3o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 12, 'm3t', 'Weapons Development Lab'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 14, 'm4o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 16, 'm4t', 'Power Droid Plant'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 17, 'm5d', 'Our informants have identified an ISB compound used for interrogations. If the stories can be believed, terrible atrocities have taken place. Destroying this foul place would send the right message to both the Empire and to citizens who lived in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. Are you that agent? '),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 18, 'm5o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 20, 'm5t', 'ISB Interrogation Compound'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 22, 'm6o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 24, 'm6t', 'Sienar Warehouse'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperial bureaucracy and slow the aggressive recruitment efforts of the Imperial Navy. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 26, 'm7o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! Claim your reward and may the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 28, 'm7t', 'Imperial Records'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 29, 'm8d', 'The Alliance has acquired the coordinates to an Imperial HoloNet data collection station. This station is used by Imperial Intelligence''s Analysis Bureau to coordinate surveillance efforts for the entire sector. If we take out this station, we effectively cripple Imperial Intelligence''s ability to uncover our sabotage missions and raids of Imperial depots. This would be a great victory for the Alliance. Can you lead such a strike?'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 30, 'm8o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 31, 'm8s', 'Bravo! Cut off the head and the body cannot survive for long. Your efforts to interrupt Imperial Intelligence''s communication to the rest of the Empire''s war machine will be instrumental in our eventual success. Your reward is well earned.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 32, 'm8t', 'HoloNet Data Station'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 33, 'm9d', 'An small Imperial outpost is currently being used to store of seized glitterstim spice. This cargo is intended to bribe Corporate Sector Authority officials to comply with Imperial Intelligence''s requests to access confidential corporate records. The Alliance needs a few good individuals to make sure that outpost is destroyed and everything inside it is burned to the ground. No spice, no favors from the CSA. The outpost will be well guarded. After all, there''s a whole lot of spice in there. '),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 34, 'm9o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 35, 'm9s', 'Good! Not only have you disposed of a great deal of illegal drugs, you''ve cost Imperial Intelligence millions of credits worth of bribe money. Let''s see how eager they are to bribe the CSA now that they have to dig into their own budget. This is a great victory for the Alliance, friend.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 36, 'm9t', 'Illegal Drugs'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 37, 'm10d', 'A cargo of probe droids has just been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit sometime in the next few days and those probe droids will be transported aboard. We don''t need to tell you how much damage those probe droids can cause to the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 38, 'm10o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 39, 'm10s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 40, 'm10t', 'Poke Out the Empire''s Eyes'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 41, 'm11d', 'We''ve discovered a shipment of turbolaser actuators, currently stored in an Imperial depot and scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 42, 'm11o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 43, 'm11s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 44, 'm11t', 'Turbolaser Actuators'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 45, 'm12d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger soon. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. The coordinates will be sent when you accept the mission. May the Force be with you. '),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 46, 'm12o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 47, 'm12s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 48, 'm12t', 'Orbital Mines'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 49, 'm13d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype. We''ll transmit the coordinates when we have your acceptance.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 50, 'm13o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 51, 'm13s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 52, 'm13t', 'Imperial Transceivers'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 53, 'm14d', 'Reports have been coming in about that amazing little MSE-6 droid. If Imperial Intelligence reports are to be believed, that tiny dynamo has blasted its way past blockades, commandeered vessels, and led those Imperial slugs on a wild mynock chase. All this paints a very amusing picture of the Empire''s overall effectiveness. We want to help spread these rumors. We''ve planted a false Imperial report on the HoloNet that claims the Empire has captured the small troublemaker, which is being held at a detention facility awaiting interrogation by Imperial Inquisitors. We need a team of operatives to strike this detention facility and make it seem as if the MSE-6 droid was "rescued" by the Alliance. Can you help us embarrass the Empire further?'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 54, 'm14o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 55, 'm14s', 'Excellent "rescue!" If we can get those Imperial slugs to start worrying about their MSE-6 droids, then we''ve already won this war. Keep it up.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 56, 'm14t', 'Rescue Mouse Droid'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 57, 'm15d', 'The Empire has deployed a prefab structure in an outlying area. It appears to be an early beachhead for a diplomatic garrison. No one here knows what a diplomat would have to be diplomatic about, way out there. In any case, it is essential to destroy it before the Empire can fortify it.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 58, 'm15o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 59, 'm15s', 'Fast work! It''s not often we take out an Imperial garrison, even if it is just a diplomatic garrison. Actually, only the first part of one. Never mind, you deserve your reward!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 60, 'm15t', 'Imperial Diplomatic Garrison'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 61, 'm16d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 62, 'm16o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 63, 'm16s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 64, 'm16t', 'Empire Gunnery School'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 65, 'm17d', 'The Empire''s infrared camera lenses require the rare mineral byrothsis. These lenses require frequent specialized maintenance, and one of the maintenance facilities is nearby. By destroying the byrothsis purification facility, your team can put the Empire in the dark. Good luck!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 66, 'm17o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 67, 'm17s', 'Excellent job. With their infrared lenses going cloudy, Imperial TIE fighters might be slower to see our ships. Let''s hope!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 68, 'm17t', 'Byrothsis Purification Facility'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 69, 'm18d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 70, 'm18o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 71, 'm18s', 'Durindfire gems flash brilliantly, but in Imperial hands they''re covered with blood. It''s better that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 72, 'm18t', 'Durindfire Gem Holding Facility'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 73, 'm19d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. In this compound these engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. Destroy the engineering compound and the Protector plans.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 74, 'm19o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 75, 'm19s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. You are progessing well!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 76, 'm19t', 'Protector Droid Engineering Compound'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 77, 'm20d', 'To get what it wants, the Empire has made plenty of covert deals with criminals. Right now it wants money, and so it''s shipping thermal detonators to local gangsters. Whether they''re set off by Imperials or crooks, these bombs always end up destroying innocent citizens'' property. If you can blow up the detonator warehouse, and its heavy defenses, you''ll be doing this planet a big favor.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 78, 'm20o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 79, 'm20s', 'You did it! It''s a relief to know those detonators won''t be troubling the locals. The reward''s yours!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 80, 'm20t', 'Thermal Detonator Warehouse'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 81, 'm21d', 'If it scares you to think of a harmless protocol droid stabbing you in your sleep, listen to this. Imperial Intelligence is working on high-frequency broadcasts that burn out a droid''s restraining bolts and ruin its programming. Basically a droid gets this signal and goes berserk. Of course, any grownup can handle a rogue 3PO unit, but what about the children? Stop this weird-science research before it''s too late.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 82, 'm21o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 83, 'm21s', 'Scratch one more Imperial Intelligence mad-science project. That droid idea might never have worked, but it doesn''t hurt that you made sure. Thanks!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 84, 'm21t', 'Restraining Bolt Sabotage Project'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 85, 'm22d', 'If you''ve fought on foot against one of those two-leg Imperial scout walkers, you know they''re dangerous. We''ve got word that a local armory is stockpiling the specialized axidite control boxes used in AT-ST command pods. You have a big chance here to interrupt a major Imperial supply chain!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 86, 'm22o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 87, 'm22s', 'Thank you! That armory stockpile would have gone into dozens of Imperial walkers. Maybe hundreds. Good job!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 88, 'm22t', 'Imperial Axidite Supplies'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 89, 'm23d', 'You''ve heard of the dola trees, the sentient plants of Aruza? No? Their flowers make an antibiotic syrup we use to treat local ailments. We negotiated with the dola for a supply of flowers, but Imperial Intelligence agents stole them and plan to use them to breed a new slave race of dola trees. The flowers are now useless for antibiotics. Destroy them and the Imperial research lab, and stop the plot against the dola trees!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 90, 'm23o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 91, 'm23s', 'The dola syrup stolen by the Empire would have saved lives, but your work at least protects the dola trees from Imperial slavery. Thank you!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 92, 'm23t', 'Dola Antibiotic Research'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 93, 'm24d', 'Informants tell us the Empire is shipping in components for their GTU AV-1A Assault Armor. It''s a powered combat suit for elite troops, sort of a hovertank you can wear. We''ve never seen it in action, and we don''t want to. If you inflict enough damage to the warehouse, you may set off the explosive charges they use for the suit''s ejection system. Then get clear, fast!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 94, 'm24o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 95, 'm24s', 'Nice job! We hope the Empire will reconsider their GTU deployment in this region.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 96, 'm24t', 'GTU Powered Armor Components'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 97, 'm25d', 'An Imperial Security outpost here has procured, through illegal back-channels, a shipment of neuronic whips. That''s right, slaver weapons, outlawed on every civilized world. They intend to use these brutal stun-whips for crowd control and intimidation. You must destroy the warehouse and the whips. Expect serious opposition, though.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 98, 'm25o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 99, 'm25s', 'What a relief! Those neuronic whips would have caused terror far beyond mere crowd control. You''re building a good reputation.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 100, 'm25t', 'Neuronic Whips'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 101, 'm26d', 'Maybe you''ve heard the reports of local swoop gangs with suspiciously good weaponry. We know the Empire''s COMPNOR security goons have been arming crooks in communities sympathetic to the Alliance. Now we''ve found an Imperial Army depot where COMPNOR requisitions the gang weapons. Stop this operation at its source!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 102, 'm26o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 103, 'm26s', 'That''s one more blow in the fight against gang violence. Good work! We''re delighted that you''re showing such promise.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 104, 'm26t', 'Army Weapons Going to Swoop Gangs'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 105, 'm27d', 'We''ve located an Imperial Army installation housing unusual ammunition: flechette microdart canisters, toxin darts, magna caster quarrels. The installation doubles as quarters for the specialists who maintain this ammo. Expect tough opposition, and stay well clear when you blow up the place.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 106, 'm27o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 107, 'm27s', 'Well done! It''s enough trouble facing blasters and AT-ATs without worrying about those deadly exotics. Your star is on the rise here!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 108, 'm27t', 'Imperial Exotic Ammunition'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 109, 'm28d', 'The Empire''s covert research into planet-wide biochemical weaponry continues. Mass production of these fearsome killers require specialized reagents and catalysts. We have tracked down a facility producing purified niobarium, a poisonous chemical used in one weapons-grade process. To cut off that process, destroy the niobarium plant.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 110, 'm28o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 111, 'm28s', 'Reports are showing negligible release of niobarium from the destruction. Fine job! Please contact us again for new assignments.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 112, 'm28t', 'Niobarium Reagent Facility'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 113, 'm29d', 'DX-343 is an industrial solvent that, on exposure into air, disperses into mist. The DX mist disrupts electronic equipment and makes breathing difficult. If our reports are correct, the Empire has stockpiled enough DX-343 at the following coordinates to wipe out three hangars of starfighters and their pilots. Destroy it!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 114, 'm29o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 115, 'm29s', 'If the Empire had used all that DX-343, we would have been carrying starships out of the hangar in pieces, and their pilots too. Good job taking it out! Please accept our thanks.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 116, 'm29t', 'DX-343 Solvent Stockpile'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 117, 'm30d', 'Production of hyperbaride, which is used for casings of heavy turbolasers, generates highly poisonous byproducts. The Empire usually dumps this stuff on airless moons or into stars, but we''ve learned of a new cache in this area. We don''t know of any current hyperbaride production, so we suspect they''re stockpiling this poison as a weapon. The cache is well guarded, but we want it destroyed, preferably in a ball of sterilizing flame.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 118, 'm30o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 119, 'm30s', 'That''s great news! We''ve had no reports of escape of toxic gases from the site, either. So you''ve come through for us well, and we''ll remember it. Thanks!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 120, 'm30t', 'Hyperbaride Dump -- Biochem Weapon?'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 121, 'm31d', 'Get this: An Imperial mess facility got accidentally infested with Sorderian weft-worms. We assume the worms were parasites inside a slave who ducked the Empire''s sterilization routines. This would only help us, except that the Empire has decided to solve the infestation by blowing up the entire facility from orbit. Their aim in these matters is not flawless, so we''d actually like you to destroy the facility first. Target practice from a Star Destroyer -- we don''t need that!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 122, 'm31o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 123, 'm31s', 'Great, now we''re doing the Imperials'' work for them. What a galaxy! But thank you, and be glad we no longer have to fear those oh-so-terrible weft-worms.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 124, 'm31t', 'Infestation of Imperial Kitchen Facility'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 125, 'm32d', 'The astrogation computers on Imperial starships rely on starfield data collected by countless space probes. Probe data for a given planetary neighborhood is collated and encoded at a central astrogation station for relay to Coruscant. If you destroy the astrogation facilities at these coordinates, the Empire must rely on outdated information when travelling in this system. But beware, these stations are always guarded!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 126, 'm32o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 127, 'm32s', 'Great job! Now we''ll hope an Imperial ship runs into a meteor shower or asteroid field it couldn''t predict. We admire your growing reputation.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 128, 'm32t', 'Imperial Astrogation Station'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 129, 'm33d', 'The most sophisticated communication relays in the galaxy, outside Coruscant, sit aboard Imperial capital ships. Our agents within the Imperial bureaucracy have redirected a shipment of these delicate relays, worth a fortune to the Empire, to a supply station here. Though this is hardly a soft target, it''s our best chance to destroy a vital component of the Imperial comm apparatus. Move quickly!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 130, 'm33o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 131, 'm33s', 'This is fine news! We must hope that the Empire''s capital ships, with hampered communications, will operate based on inferior strategy. Please check back with us, for we are pleased at your progress!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 132, 'm33t', 'Starship Communication Relays'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 133, 'm34d', 'Informants have brought us dramatic news. Empire ship designer Lira Wessex, who created the original schematics for the Imperial-class Star Destroyer, is apparently visiting this world on a sectorwide tour of shipbuilding facilities. If we can incapacitate Wessex, the Empire will lose one of its greatest talents. Unfortunately, Wessex is here only a while, at an Imperial outpost with a strong escort. Strike fast and strike hard!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 134, 'm34o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 135, 'm34s', 'Great work! If Lira Wessex was inside that wreck, then you''ve brought a long, bad career to a belated close. Thank you, and contact us again soon!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 136, 'm34t', 'Lira Wessex Blights Local Region'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 137, 'm35d', 'The SoroSuub Corporation, once a peaceful contributor to the economy of the Old Republic, is now a dangerous ally of the Empire. Their ships and weapons are responsible for the deaths of untold numbers of Alliance fighters. To isolate them from distribution contractors, we have begun a campaign to harry shipments of SoroSuub armaments across the galaxy. Here are coordinates for a distribution center on this world. Be aware that the Empire knows of our strategy and often deploys troops to protect these shipments. Prepare for well-armed resistance.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 138, 'm35o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 139, 'm35s', 'Allies of the Empire are enemies of freedom. You have done well. Contact us again for the coordinates of more SoroSuub distribution centers.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 140, 'm35t', 'SoroSuub Corporation Shipments'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 141, 'm36d', 'The Empire cherishes every opportunity to capture an intact X-wing fighter. InCom''s superior X-wing technology, with its heavy armor and hyperdrive, is the envy of the Imperial Navy. To our dismay, recently a civilian informant tipped the Imperial Security Bureau to the location of a hidden cache of fighters. Stormtroopers descended on the place, and now five pristine X-wings are being readied for transport to the Empire''s cronies at Sienar Fleet Systems. We cannot allow these ships to depart their landing bay. We need agents in the area to hit the place fast. Make sure nothing is left but smoke and rubble.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 142, 'm36o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 143, 'm36s', 'Well done. All five X-wing fighters were reduced to slag. We must guard every technological advantage if we are to bring the Empire to its knees.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 144, 'm36t', 'Captured X-wing Fighters'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 145, 'm37d', 'The Alliance has placed agents inside many Imperial operations. These brave individuals risk their lives to bring us information concerning the Empire''s movements. Sometimes we require direct action to ensure their continued secrecy. Currently one secret operative, well-placed in the Imperial system, is under suspicion by his supervisor. We cannot afford to lose him. Therefore we are commissioning a strike team to attack the small garrison where he is stationed. The diversion will let him eliminate his supervisor and destroy evidence. The action should be loud and messy to provide maximum distraction. Be well-armed and ready for a protracted fight.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 146, 'm37o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 147, 'm37s', 'Well done. Thanks to your distraction, our secret agent was able to remove the officer who questioned his loyalty to the Empire.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 148, 'm37t', 'Assist Secret Agent'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 149, 'm38d', 'An Imperial spy has infiltrated our supply network. We know only that he is a Kubaz and he is very good at his work. We have a credible suspicion that he has collected dangerous information about our secret shipping routes. A memory droid recently arrived at the Imperial base at the following coordinates. We believe that the droid''s databanks contain this secret data. If we are to protect the identities of the depots and freighters that assist us in our cause, we must destroy this base at once. The lives of countless friends of the Alliance are at stake.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 150, 'm38o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 151, 'm38s', 'We have confirmed that the memory droid was destroyed. Our supply routes are safe again. Excellent work!'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 152, 'm38t', 'Thwart a Spy'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 153, 'm39d', 'An Imperial spy is working inside Alliance operations. We know only that he is a Kubaz and he is very good at his work. He has collected a list of Alliance informants and is in the process of transmitting their names to Imperial Intelligence. The list is stored at an Imperial base at the following coordinates. We need a well-armed team to destroy the base before Imperial Intelligence arrives to recover the information. Otherwise many brave Alliance informants will assuredly lose their lives.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 154, 'm39o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 155, 'm39s', 'We have monitored transmissions within Imperial Intelligence. They are most displeased that you destroyed the list of Alliance informants before they could recover it. You have saved the lives of many good people. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 156, 'm39t', 'Save Alliance Informants'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 157, 'm40d', 'An Imperial spy has wrought havoc on our operations in several sectors. We do not know his identity, but we have discovered the office of Imperial Intelligence to which he reports. If we can destroy his headquarters, we can salvage many operations he has jeopardized. A team of experienced marksmen should be sufficient to knock down this Imperial site and relieve us of many headaches.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 158, 'm40o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 159, 'm40s', 'Skillfully done. The Alliance values capable agents like you. Contact us again soon.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 160, 'm40t', 'Destroy an Intelligence Office'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 161, 'm41d', 'Cloaking devices create no end of difficulty for Alliance blockade runners. We have tracked a shipment of hybridium ore, essential to modern cloaking systems, from Garos IV to an Imperial transfer point. The site is guarded by Imperial troops, but if we can get a blaster squad inside to level the place, we''ll take away the ability of the blockade ships to cloak themselves from our sensors. This will greatly facilitate the movement of our ships through the sector.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 162, 'm41o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 163, 'm41s', 'Successes like these are stepping stones to victory over the Empire. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 164, 'm41t', 'Fuel for Imperial Cloaking Ddevices'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 165, 'm42d', 'The Imperial Security Bureau''s network of civilian spies and informants is a plague on us all. The Alliance places great value on locating and terminating sites of ISB activity. Freedom-loving fighters are encouraged to contact us for the coordinates of such installations. Be aware that the Empire has responded to our campaign by assigning troops to guard these facilities, so expect considerable resistance. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 166, 'm42o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 167, 'm42s', 'You have done a superb job. The more we hamper the actions of the ISB, the closer we come to real freedom in the galaxy.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 168, 'm42t', 'Office of Imperial Security Bureau'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 169, 'm43d', 'Propaganda is one of the Empire''s tools in oppressing the galaxy. Imperial propagandists have taken over entire news corporations. We have identified one such purveyor of deceit, and confirmed that Imperial personnel staff all of its facilities. We offer a reward to worthy fighters who can smash this installation and staunch the flow of lies.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 170, 'm43o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 171, 'm43s', 'Every time we take down a center for propaganda, the people of the galaxy move closer to the truth. You have done well.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 172, 'm43t', 'Smash Propaganda Center'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 173, 'm44d', 'Force shield technology is a major factor in space battles. One of our undercover agents has covertly sabotaged Imperial masking codes for several uninstalled shield generators in this sector. If these generators are deployed to Imperial warships, we will have a hidden advantage should our blockade runners be spotted. Unfortunately certain factory records might betray our secret sabotage. We need agents to blow apart a small but well-guarded Imperial Navy maintenance base, thereby destroying the factory records that might reveal our scheme. Imperial bureaucracy being what it is, we are confident the shield generators will be deployed even without these records.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 174, 'm44o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 175, 'm44s', 'Well done! Against the military resources of the Empire we need every advantage we can get. Thank you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 176, 'm44t', 'Protect Covert Alliance Operation');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 177, 'm45d', 'We have received word that a new security protocol has been implemented at Imperial military sites around the sector. We are staging exploratory assaults on select bases, to see what new tactics the Empire has deployed. We need small teams of marksmen or veteran individuals to assist us in this fact-finding endeavor. Leave no wall standing.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 178, 'm45o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 179, 'm45s', 'It seems no Imperial security protocol is a match for a good blaster at your side. The Alliance thanks you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 180, 'm45t', 'Test Imperial Security Protocol'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 181, 'm46d', 'The Empire is not above sedating its subjects into complacency. We have discovered an installation where Imperial engineers are introducing drugs into the water supply to quell unrest in the local population. This crime must not be allowed to continue. If the Empire''s cowardice enrages you, and if you have the expertise to do something about it, please blast this water-doping facility into smoke and rubble. '),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 182, 'm46o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 183, 'm46s', 'It warms the heart to see a plume of smoke rising where Imperial villainy once reigned. Very well done. Your reputation continues to rise here.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 184, 'm46t', 'Water-Doping Facility'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 185, 'm47d', 'The Imperial Security Bureau has stepped up its program to recruit young, poor people as agents of the Empire. The ISB contacts troubled youths with a criminal record and pays them to do the Empire''s dirty work, thus keeping the hands of the governors clean. We must not stand for this underhanded scheme. The program is controlled from an ISB facility at the following coordinates. We want to make an example of these ISB monsters, so leave no Imperial agent standing.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 186, 'm47o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 187, 'm47s', 'Thanks to your good work, many troubled youths will avoid the corruption of the Empire and perhaps even become good Alliance fighters in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 188, 'm47t', 'Imperial Corruption of Our Youth'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 189, 'm48d', 'An up-and-coming Imperial officer named Commander Hrazzel has shown a keen aptitude for ferreting out covert Alliance agents and destroying our hidden bases. What''s worse, he is known to torture and slaughter innocents in his enforcement of Imperial edicts. We have learned his current itinerary, and have found that he is currently inspecting a facility on this world. We need a skilled individual or small squad to strike this facility while Hrazzel is present. With good planning, fortitude, and a bit of luck, we can eliminate this threat before he rises to become a galaxy-wide menace.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 190, 'm48o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 191, 'm48s', 'You have done very well. We have not yet confirmed that Commander Hrazzel was killed in your raid, but we hope his threat is now gone.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 192, 'm48t', 'Dangerous Imperial Officer'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 193, 'm49d', 'The grim story is all too common: A local notable crosses the Empire and a small garrison is placed on his land as a lesson to others. But a few, brave individuals continue to resist oppression. They have contacted the Alliance with requests to remove these garrisons from their land. Alliance High Command has decided to pursue several of these requests. We know several such garrisons, compact but well-defended, that require the attention of strike teams. The mission is simple: Hit each place hard and leave no survivors. Inasmuch as the Empire is so fond of lessons, it is time they learned one of their own.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 194, 'm49o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 195, 'm49s', 'Nicely handled. Your skill and bravery are assets to the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 196, 'm49t', 'Imperial Garrison'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 197, 'm50d', 'Imperial hyperspace technology is advancing at an alarming rate. Most capital ships contain hyperwave signal interceptors that sound an alert just before a spacecraft comes out of hyperspace in their vicinity. Our spies inform us that an Imperial research laboratory has tripled the range of these hyperwave warning systems, giving them much more time to prepare for incoming enemies. The secret of this technology is entirely contained in the laboratory. We intend to raze the facility before any Imperial warships can benefit. We need a small team or a highly skilled individual to hit the place and blow it to cinders.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 198, 'm50o', 'The Alliance to Restore the Republic'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 199, 'm50s', 'Splendid! Our informants assure us that it will take years for the Empire to rebuild this new technology. By then, we may have discovered some means to counter it.'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 200, 'm50t', 'Imperial Laboratory'),
('string/en/mission/mission_destroy_rebel_non_military_medium.stf', 201, 'number_of_entries', '50'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 1, 'm1d', 'Local Imperial patrols have been relying on a refueling depot not far from here. The depot''s destruction would certainly hamper the Empire''s ability to effectively search for our cells. The Empire realizes this, so the depot is likely to be well defended. This mission will require skill and fortitude. Can the Alliance depend on you to lead such a strike?'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 2, 'm1o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 3, 'm1s', 'Now that''s how it''s done! Those Imperial patrols will stay grounded for a while. Long live the Alliance!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 4, 'm1t', 'Ground Imperial Patrols'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 5, 'm2d', 'A transport repair station at these coordinates services Imperial scout troopers'' speeder bikes. If this facility were destroyed, it would limit the number of Imperial search-and-destroy missions for this entire system. Can we count on you to orchestrate this strike? As always, the Alliance will reward you for services rendered.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 6, 'm2o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 7, 'm2s', 'Broken down speeder bikes don''t do the Empire any good. Job well done, agent. The Alliance could use more fighters like you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 8, 'm2t', 'Take Out Imperial Mechanics'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 9, 'm3d', 'A small SoroSuub weapons testing facility must be knocked out. We believe they are working on an improved design for the scout trooper blaster. The Alliance can''t afford to have scout troopers get better sidearms. We don''t know what kind of security this facility will have, but we imagine it''ll be formidable. You might need help.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 10, 'm3o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 11, 'm3s', 'Bravo! No new blasters for those scout troopers! An impressive bit of work, agent. The Alliance thrives because of individuals like you. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 12, 'm3t', 'No New Imperial Blasters'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 13, 'm4d', 'We''ve located a major Imperial power droid manufacturing plant. Taking this plant out would be more than a simple inconvenience for the Empire. Their Star Destroyers and garrisons rely on these power droids to keep battle stations running. It will take a strong, precise strike to cripple this installation. The Alliance needs your help.  '),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 14, 'm4o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 15, 'm4s', 'No power means no weapons or defenses. Our congratulations on the success of your mission. Keep up the good work. The Alliance is counting on you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 16, 'm4t', 'Farewell, Power Droids'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 17, 'm5d', 'We''ve identified an ISB compound used for interrogations. If the stories are true, terrible atrocities have taken place there. Destroying this facility would send the right message to both the Empire and to citizens who live in fear of Imperial Security. We''re looking for a dedicated agent who can lead a successful assault on this nightmarish compound. Are you that agent? '),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 18, 'm5o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 19, 'm5s', 'Bravo, agent! Now citizens will realize that the power of the ISB is not absolute and that the Empire is fallible. You''ve earned your reward.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 20, 'm5t', 'Take Out Torturers'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 21, 'm6d', 'We''ve located a Sienar Fleet Systems warehouse and have learned that it''s currently storing ion engines scheduled to go to Imperial shipyards in this sector. That will mean more TIE fighters for our X-wing pilots to deal with. We need someone to destroy that warehouse and everything inside.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 22, 'm6o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 23, 'm6s', 'The distinctive roar of those TIE engines is greatly diminished today. Great job, agent. We knew we could count on you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 24, 'm6t', 'No More Ion Engines'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 25, 'm7d', 'An Imperial Academy processing center is currently housing the results of several hundred potential pilots'' flight exams. If those scores are destroyed, this will create a severe backlog for the Imperials and slow their recruitment efforts. Further, it would let us approach potential recruits and possibly enlist their aid against the Empire. Do you wish to lead this important mission?'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 26, 'm7o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 27, 'm7s', 'Excellent! The best thing about the Empire''s ponderous bureaucracy is that it''s easy to throw a hydrospanner into the works. Good job! May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 28, 'm7t', 'Burn Imperial Records'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 29, 'm8d', 'A cargo of probe droids has been delivered to a supply depot servicing this sector. A Star Destroyer is scheduled to enter the system''s orbit in the next few days and those probe droids will be transported aboard. Those probe droids are trouble for the Alliance. We need a skilled agent to take out that supply depot and make sure those probe droids are destroyed.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 30, 'm8o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 31, 'm8s', 'Good going! Fewer probe droids means fewer chances to find our bases. The Empire can''t destroy what they can''t find, after all. You''re becoming a very promising agent indeed.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 32, 'm8t', 'Take Out Probe Droids'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 33, 'm9d', 'We''ve discovered a shipment of turbolaser actuators stored in an Imperial depot. They are scheduled to be delivered to the Kuat Drive Yards. We must make sure those actuators are never installed in any capital ship''s weapons. A team of skilled agents should be able to blast this depot off without much trouble. You''ll have to work fast, though.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 34, 'm9o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 35, 'm9s', 'Well struck, agent. Without their turbolasers, those hulking capital ships are just so much space debris. May the Force be with you.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 36, 'm9t', 'Pull Star Destroyers'' Teeth'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 37, 'm10d', 'A large shipment of orbital mines is to be delivered to the Star Destroyer Avenger. The dispersal of these mines would make life much more difficult for our fleet, as you can imagine. We''ve discovered these mines and need the depot blasted into oblivion. Can you lend a hand, citizen? '),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 38, 'm10o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 39, 'm10s', 'Good work, citizen! Those mines won''t be claiming the lives of our pilots and crew members. We look forward to working with you again.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 40, 'm10t', 'Take Out Deadly Mines'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 41, 'm11d', 'The Empire has designed an improved subspace transceiver. The working prototype was sent to a manufacturing facility for mass production. A small team of operatives must make sure those transceivers are never built and either secure or destroy the prototype. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 42, 'm11o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 43, 'm11s', 'It''s obvious you know the meaning of success, citizen. Job well done! Even if we didn''t get the prototype, its destruction is a good consolation prize.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 44, 'm11t', 'Knock Out Imperial Communications'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 45, 'm12d', 'We have identified an Imperial fortified complex as a gunnery school for local recruits. Today they''re firing at target droids, but tomorrow they''ll be aiming at us. You have to destroy that compound -- today!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 46, 'm12o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 47, 'm12s', 'Excellent work! The Alliance has nothing against education, but we don''t like what the Empire does with it. We look forward to working with you again!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 48, 'm12t', 'No More Imperial Gunners'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 49, 'm13d', 'We''ve managed to locate the Imperial Intelligence Analysis Bureau command center for this entire sector. These centers provide the intelligence reports that allow the Bureau of Operations to plan and execute strikes. It will be heavily guarded and equipped with state-of-the-art defenses. Its destruction will require an experienced team. Can the Alliance count on you?'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 50, 'm13o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 51, 'm13s', 'A brilliantly executed strike! With freedom fighters like you aiding our cause, the Empire has no chance. We hope you''ll accept difficult missions from us in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 52, 'm13t', 'Cripple Imperial Intelligence'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 53, 'm14d', 'We''ve discovered a training facility for Imperial Intelligence''s Operations agents -- in other words, assassins. This installation has launched covert operations that have killed some of our top officers. The Alliance wants this base blasted into atoms. This will not be easy, as some of the Empire''s top agents work as trainers at this facility.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 54, 'm14o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 55, 'm14s', 'Those Operations goons never knew what hit them. Bravo! You''ve done the Alliance and the galaxy a great service. You''re quickly becoming one of our top agents.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 56, 'm14t', 'Stop Future Assassins'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 57, 'm15d', 'Bothan spies have identified a biological weapons development lab. Intercepted transmissions indicate this facility was instrumental in developing the Candorian Plague used against Dentaal. This lab must be destroyed at any cost. Imperial security will be tight and defenses formidable. A generous reward awaits the agent who can pull this off. '),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 58, 'm15o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 59, 'm15s', 'One less weapon in the Empire''s arsenal. Good work! Many worlds will sleep easier now that this plague-making lab has been destroyed.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 60, 'm15t', 'Destroy Plague-Maker'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 61, 'm16d', 'A top-secret installation of the Inquisitorius, the Empire''s specialized interrogators, has been located. Many of our agents ended up there, tortured for information until they were driven mad and killed. It is said that the Inquisitors use the Force to aid in their twisted work. Commander Skywalker has personally requested that this installation be taken out. Can we call on you?'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 62, 'm16o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 63, 'm16s', 'Success! You''ll be the scourge of the Empire yet! The Alliance thanks you and the galaxy is in your debt. Our reward is but a small token of our gratitude.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 64, 'm16t', 'Smash Imperial Interrogators'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 65, 'm17d', 'An Imperial garrison has received orders to execute suspected Alliance sympathizers and their families if they do not start naming Alliance spies. We need someone to wipe out the garrison before these stormtroopers can slaughter innocent civilians. Taking out a garrison, even a small one, is no easy task. These Imperial troops will be on high alert.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 66, 'm17o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 67, 'm17s', 'Great job! The Empire will think twice before giving their garrisons the order to execute civilians again. Fear is not just a tool for the Empire.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 68, 'm17t', 'Save Innocent Civilians'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 69, 'm18d', 'A stormtrooper training facility, renowned for producing some of the Emperor''s most fanatical legions, must be taken out. A successful strike would stand as a symbol of the Alliance''s determination to rid the galaxy of the Empire''s tyranny. The Emperor''s brainwashing techniques can''t compete with an Alliance member''s passion for freedom. '),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 70, 'm18o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 71, 'm18s', 'You deserve a medal! The Emperor''s not the only one who trains crack troops and deadly soldiers. The Alliance salutes you!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 72, 'm18t', 'Destroy Stormtrooper Training Base'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 73, 'm19d', 'Bothan spies have located an Imperial outpost housing Sith artifacts. We''ve received word that Darth Vader has ordered these artifacts delivered to him personally. If those artifacts are indeed what the Bothans claim, we must not allow them to fall into Vader''s hands. We need a strike team to go in and blow that shipment to atoms.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 74, 'm19o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 75, 'm19s', 'Job well done! You are a true champion of the people. Report to us again for future assignments soon.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 76, 'm19t', 'Destroy Sith Artifacts'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 77, 'm20d', 'Mercenary assassins do the Emperor''s dirty work when direct military action is politically inexpedient. We have the coordinates of an undocumented arsenal from which the Empire supplies its assassins. We need a squad of fighters to blast the place into vapor. The arsenal is garrisoned with Imperial soldiers and mercenary assassins, so be careful.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 78, 'm20o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 79, 'm20s', 'Astounding work! You and your team are superior operatives, a true asset to the Alliance.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 80, 'm20t', 'Smash Arsenal For Imperial Assassins'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 81, 'm21d', 'Imperial Army weapons designers have refashioned a platform-mounted flame carbine, the Czerka CZ-28 Flamestrike, for use on repulsorlift craft and cloud cars. Sheets of flame from the sky will mean grave danger for our fighters below. No matter the cost, you must render this weapons factory permanently inoperative. Prepare for harsh opposition.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 82, 'm21o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 83, 'm21s', 'Impressive news! This victory represents a fundamental security that cannot be overstated. We applaud your resolve, and we wish you still greater success in the future.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 84, 'm21t', 'Imperial Flamer Munitions Factory'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 85, 'm22d', 'The profiteers at Arakyd Industries continue to garner Imperial largesse. These parasites have contracted to build new legions of Inquisitor-series seeker droids with weaponry of considerably increased lethality. This presents a major threat to Alliance forces, and we cannot allow the factory to begin production. Assemble a large and experienced strike team and take this factory out.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 86, 'm22o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 87, 'm22s', 'This is excellent news! We hope this damages Arakyd Industries profits as badly as their products have damaged our forces. We congratulate you, agent!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 88, 'm22t', 'Blast Combat Droid Plant'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 89, 'm23d', 'The Empire has established a new facility building two-legged AT-ST scout walkers. Though the labor force is entirely droid-based, the installation is well defended with Imperial troops. Our recon scout escaped only by dint of skill and luck. Assemble an experienced strike team to take out this major target.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 90, 'm23o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 91, 'm23s', 'Your high reputation is well earned, agent! We have stalled the production of Imperial walkers in this area, at least for now. Your reputation continues to rise!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 92, 'm23t', 'Destroy AT-ST Assembly Plant'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 93, 'm24d', 'The Empire is relaying a cache of rare durindfire gems, under heavy guard, to a merchant in this area. You may know that Imperials traffic in these gems to finance their more exotic projects, such as the Death Star. If you can destroy these gems in their holding facility, you''ll strike a blow against covert financiers across the galaxy.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 94, 'm24o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 95, 'm24s', 'Durindfire gems flash brilliantly, but in Imperial hands they''re covered with blood. It''s better that you destroyed them. Good work!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 96, 'm24t', 'Blast Durindfire Gems'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 97, 'm25d', 'Imperial forces are guarding -- perhaps a better word is "confining" -- engineers working for Baktoid Combat Automata. In this compound these engineers are stress-testing blaster subsystems for a redesigned Protector-series combat droid. Destroy the engineering compound and the Protector plans.'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 98, 'm25o', ''),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 99, 'm25s', 'Thank you! Facing an improved Protector droid would not have been fun, to say the least. You are progessing well!'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 100, 'm25t', 'Smash Protector Droids'),
('string/en/mission/mission_destroy_rebel_non_military_medium_non_persistent_from_npc.stf', 101, 'number_of_entries', '25'),
('string/en/mission/mission_generic.stf', 1, 'assassin_target_location', 'Your target has been detected %DI meters to the %TO.'),
('string/en/mission/mission_generic.stf', 2, 'bounty_already_tracking', 'You are already tracking your target.'),
('string/en/mission/mission_generic.stf', 3, 'bounty_no_ability', 'You do not understand how to use this item.'),
('string/en/mission/mission_generic.stf', 4, 'bounty_no_mission', 'You must accept a bounty mission before you can use a probe droid. '),
('string/en/mission/mission_generic.stf', 5, 'bounty_no_signature', 'You must go speak with your informant before you can track your target. '),
('string/en/mission/mission_generic.stf', 6, 'buy_probe_droid', 'Buy Probe Droid'),
('string/en/mission/mission_generic.stf', 7, 'crafting_already_dropped_off', 'Why are you still here? Shoo. You got your reward, now go away. '),
('string/en/mission/mission_generic.stf', 8, 'crafting_already_picked_up', 'Why are you still here? My friend is waiting for that item. Put it together and deliver it like you agreed to.'),
('string/en/mission/mission_generic.stf', 9, 'crafting_components_received', 'The necessary components and schematic have been transferred to you. Use your generic crafting tool to craft the item.'),
('string/en/mission/mission_generic.stf', 10, 'crafting_instructions', 'Drag and drop the crafted item onto the target NPC.'),
('string/en/mission/mission_generic.stf', 11, 'crafting_mission_start', 'Go to the waypoint and talk to the NPC. They will give you the schematic and necessary components. '),
('string/en/mission/mission_generic.stf', 12, 'dancer', 'Dancer'),
('string/en/mission/mission_generic.stf', 13, 'deliver_already_dropped_off', 'What now? You got your reward, I got my item. Go away.'),
('string/en/mission/mission_generic.stf', 14, 'deliver_already_picked_up', 'Why are you still here? Go deliver that item like you''re supposed to and quit bothering me. '),
('string/en/mission/mission_generic.stf', 15, 'deliver_incorrect_player_0', 'You know who''s not talking to you? Me. I''m waiting for someone to do me a favor, and it''s not you. Go away.\n'),
('string/en/mission/mission_generic.stf', 16, 'deliver_incorrect_player_1', 'No way. I''m not talking to you. I''m waiting for someone to do me a favor and it''s not you.'),
('string/en/mission/mission_generic.stf', 17, 'deliver_incorrect_player_2', 'Do I have anything for you to do... Nope... I''m waiting for someone else.'),
('string/en/mission/mission_generic.stf', 18, 'deliver_incorrect_player_3', 'I don''t want to buy anything you might be selling. As a matter of fact, I don''t even want to talk to you.'),
('string/en/mission/mission_generic.stf', 19, 'deliver_incorrect_player_4', 'Just stop talking right there. I''m not waiting here for you, and I don''t want to talk to you.'),
('string/en/mission/mission_generic.stf', 20, 'deliver_received_data', 'Data Received: '),
('string/en/mission/mission_generic.stf', 21, 'destroy_return', 'Target Destroyed! Return to your contact to receive your reward. '),
('string/en/mission/mission_generic.stf', 22, 'droid_buy_no_space', 'You need more inventory space to buy a droid. '),
('string/en/mission/mission_generic.stf', 23, 'droid_buy_nsf', 'You do not have enough credits to purchase this droid.'),
('string/en/mission/mission_generic.stf', 24, 'droid_price_probot', 'Arakyd Probe Droid: 1000 Credits'),
('string/en/mission/mission_generic.stf', 25, 'droid_price_seeker', 'Seeker Probe Droid: 200 Credits\n\n'),
('string/en/mission/mission_generic.stf', 26, 'droid_probot_buy_confirmation', 'Do you wish to purchase an Imperial Probe Droid for 1000 credits?'),
('string/en/mission/mission_generic.stf', 27, 'droid_purchase_complete', 'A droid has been purchased and placed in your inventory.'),
('string/en/mission/mission_generic.stf', 28, 'droid_purchase_prompt', 'Choose the type of probe droid you wish to purchase:'),
('string/en/mission/mission_generic.stf', 29, 'droid_seeker_buy_confirmation', 'Do you wish to purchase a Seeker Probe Droid for 200 credits?'),
('string/en/mission/mission_generic.stf', 30, 'east', 'East'),
('string/en/mission/mission_generic.stf', 31, 'escort_follow_again', 'I will continue to follow you.'),
('string/en/mission/mission_generic.stf', 32, 'escort_pickup_request', 'I''m here to escort you.'),
('string/en/mission/mission_generic.stf', 33, 'failed', 'Mission failed'),
('string/en/mission/mission_generic.stf', 34, 'give_item', 'What are you waiting for? Give me that item.'),
('string/en/mission/mission_generic.stf', 35, 'group_expanded', 'Group Mission Success! Reward credits have been transmitted to the bank account of all group members in the immediate area.  They have been recalculated to reflect the newly added members.\n'),
('string/en/mission/mission_generic.stf', 36, 'group_success', 'Group Mission Success! Reward credits have been transmitted to the bank account of all group members in the immediate area.\n'),
('string/en/mission/mission_generic.stf', 37, 'group_too_far', 'Mission Alert! Some group members are too far away from the group to receive their reward and and are not eligible for reward.\n'),
('string/en/mission/mission_generic.stf', 38, 'hello', 'Hello.'),
('string/en/mission/mission_generic.stf', 39, 'hunting_kills_remaining', 'You must kill %DI more %TO to complete your mission.'),
('string/en/mission/mission_generic.stf', 40, 'incomplete', 'Mission incomplete'),
('string/en/mission/mission_generic.stf', 41, 'informant_no_bounty_mission', 'You don''t appear to be currently working for the guild. Come back and talk to me after you get a job.'),
('string/en/mission/mission_generic.stf', 42, 'informant_not_bounty_hunter', 'You''re not a member of the Bounty Hunter guild. Go talk to someone who cares. '),
('string/en/mission/mission_generic.stf', 43, 'jedi_not_online', 'Your target is not online.'),
('string/en/mission/mission_generic.stf', 44, 'mission_incomplete_01', 'CEASE SUSPICIOUS ACTIVITY AT ONCE! The Galactic Empire regrets to inform you that your employer''s activities have come under suspicion. You will receive compensation deemed fair by the Empire.'),
('string/en/mission/mission_generic.stf', 45, 'mission_incomplete_02', 'ARREST NOTICE: Your employer''s funds have been frozen due to charges of conspiracy. Reports indicate that you are not directly involved at the moment, therefore you will be reimbursed for your time.'),
('string/en/mission/mission_generic.stf', 46, 'mission_incomplete_03', 'CEASE AND DESIST: The Imperial Security Bureau demands that your employment be terminated immediately. Your employer has been informed of this change in plans. Mention this to no one!'),
('string/en/mission/mission_generic.stf', 47, 'mission_incomplete_04', 'CONTRACT REVOKED! An arrest warrant has been issued for your employer. You are hereby ordered by the Empire abort your mission immediately. You will be partially credited for your mission in exchange for your cooperation.'),
('string/en/mission/mission_generic.stf', 48, 'mission_incomplete_05', 'MISSION LICENSE DISSOLVED! Your employer submitted inappropriate forms for this mission. Therefore, the Empire cannot allow your mission to continue. Your employer has agreed to offer partial payment, however.'),
('string/en/mission/mission_generic.stf', 49, 'mission_title', 'Mission: '),
('string/en/mission/mission_generic.stf', 50, 'no', 'No'),
('string/en/mission/mission_generic.stf', 51, 'no_assassin_mission', 'You do not have an assassination target currently.'),
('string/en/mission/mission_generic.stf', 52, 'no_assassin_target', 'You must get closer to the designated area before this item can lock onto your target.'),
('string/en/mission/mission_generic.stf', 53, 'north', 'North'),
('string/en/mission/mission_generic.stf', 54, 'northeast', 'Northeast'),
('string/en/mission/mission_generic.stf', 55, 'northwest', 'Northwest'),
('string/en/mission/mission_generic.stf', 56, 'not_bounty_hunter_terminal', 'You are not authorized to use this terminal.'),
('string/en/mission/mission_generic.stf', 57, 'npc_job_accept_no', 'Not interested. '),
('string/en/mission/mission_generic.stf', 58, 'npc_job_accept_response_yes', 'Report back to me after you have completed your task. '),
('string/en/mission/mission_generic.stf', 59, 'npc_job_accept_response_yes_nonpersistent', 'Thanks for your help. '),
('string/en/mission/mission_generic.stf', 60, 'npc_job_accept_yes', 'I''ll do it. '),
('string/en/mission/mission_generic.stf', 61, 'npc_job_none_available', 'I have nothing for you to do right now.'),
('string/en/mission/mission_generic.stf', 62, 'npc_job_request', 'Do you have any work?'),
('string/en/mission/mission_generic.stf', 63, 'npc_job_request_already_have', 'You already have a task from me. Complete it and then we''ll talk again.'),
('string/en/mission/mission_generic.stf', 64, 'npc_job_request_no_job', 'I have nothing for you to do right now.'),
('string/en/mission/mission_generic.stf', 65, 'npc_job_request_wrong_difficulty', 'You need to be more skilled before you can work for me.'),
('string/en/mission/mission_generic.stf', 66, 'npc_on_other_mission', 'You must finish your other work before you can help me.\n'),
('string/en/mission/mission_generic.stf', 67, 'out_in_space', 'You are unable to track your opponent while out in space.'),
('string/en/mission/mission_generic.stf', 68, 'probe_droid_activate', 'Probe Droid Command'),
('string/en/mission/mission_generic.stf', 69, 'probe_droid_arrival', 'Probe Droid has landed and is awaiting biological signature programming. '),
('string/en/mission/mission_generic.stf', 70, 'probe_droid_arrival_1', '1'),
('string/en/mission/mission_generic.stf', 71, 'probe_droid_arrival_2', '2'),
