('string/en/mission/mission_generic.stf', 75, 'probe_droid_bad_location', 'You must move to a different area to call down a probe droid from orbit.'),
('string/en/mission/mission_generic.stf', 76, 'probe_droid_find_target', 'Find Bounty Target'),
('string/en/mission/mission_generic.stf', 77, 'probe_droid_launch_p', 'Imperial Probe Droid Launch in 5.'),
('string/en/mission/mission_generic.stf', 78, 'probe_droid_launch_prep', 'Probe Droid request received. Prepping capsule for launch. ETA 20 seconds. '),
('string/en/mission/mission_generic.stf', 79, 'probe_droid_program', 'Transmit Biological Signature'),
('string/en/mission/mission_generic.stf', 80, 'probe_droid_takeoff', 'Target data received. Commencing interplanetary search pattern. '),
('string/en/mission/mission_generic.stf', 81, 'probe_droid_too_many', 'You cannot launch another probe droid. '),
('string/en/mission/mission_generic.stf', 82, 'probe_droid_track_target', 'Find and Track Target'),
('string/en/mission/mission_generic.stf', 83, 'recon_return', 'Recon Completed. Return to your contact to receive your reward. '),
('string/en/mission/mission_generic.stf', 84, 'seeker_droid_launched', 'Biological scan received. Commencing planetary seach pattern.'),
