('string/en/mission/mission_generic.stf', 91, 'survey_too_close', 'That resource pocket is too close (%DF meters) to the mission giver to be useful to them. Go find one at least %DI meters away to complete your survey mission. '),
('string/en/mission/mission_generic.stf', 92, 'target_continue_tracking', 'Your probe droid will continue to report last known target location. '),
