('string/en/mob/base_npc_convo.stf', 1, 'thug_npc_greet_1', 'What do you want?'),
('string/en/mob/base_npc_convo.stf', 2, 'thug_npc_greet_2', 'Yeah?  What?!?'),
('string/en/mob/base_npc_convo.stf', 3, 'thug_npc_greet_3', 'Make this quick, ok?'),
('string/en/mob/base_npc_convo.stf', 4, 'thug_player_line_1_1', 'Who do you work for?'),
('string/en/mob/base_npc_convo.stf', 5, 'thug_player_line_1_2', 'Why are you being so hostile?'),
('string/en/mob/base_npc_convo.stf', 6, 'thug_player_line_1_3', 'You got somewhere to be?'),
('string/en/mob/base_npc_convo.stf', 7, 'thug_npc_response_1_1', 'Whoever pays the most.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/mob/base_npc_convo.stf', 8, 'thug_npc_response_1_2', 'Who says I''m being hostile?'),
('string/en/mob/base_npc_convo.stf', 9, 'thug_npc_response_1_3', 'What''s it to you?'),
('string/en/mob/base_npc_convo.stf', 10, 'thug_player_line_2_1', 'Ever work for Valarian?'),
('string/en/mob/base_npc_convo.stf', 11, 'thug_player_line_2_2', 'Um...that was me.'),
('string/en/mob/base_npc_convo.stf', 12, 'thug_player_line_2_3', 'I''m just asking is all.'),
('string/en/mob/base_npc_convo.stf', 13, 'thug_player_line_3_1', 'Ever work for Jabba?'),
('string/en/mob/base_npc_convo.stf', 14, 'thug_player_line_3_2', 'You''re rude aren''t you?'),
('string/en/mob/base_npc_convo.stf', 15, 'thug_player_line_3_3', 'Forget I asked.'),
('string/en/mob/base_npc_convo.stf', 16, 'thug_npc_response_2_1', 'Answering questions like that can get you killed.'),
('string/en/mob/base_npc_convo.stf', 17, 'thug_npc_response_3_1', 'Didn''t everyone?'),
('string/en/mob/base_npc_convo.stf', 19, 'thug_npc_response_2_2', 'Do I care?  No.  Go away.'),
('string/en/mob/base_npc_convo.stf', 20, 'thug_npc_response_3_2', 'Very.'),
('string/en/mob/base_npc_convo.stf', 21, 'thug_npc_response_2_3', 'Well don''t.'),
('string/en/mob/base_npc_convo.stf', 23, 'thug_npc_response_3_3', 'I''ll forget this whole thing ever happened'),
('string/en/mob/base_npc_convo.stf', 24, 'player_job_request', 'Do you need anything done?'),
('string/en/mob/base_npc_convo.stf', 25, 'thug_npc_job_offer_1', 'I got work.  If you don''t mind getting your hands dirty you can have it.  Want it?'),
('string/en/mob/base_npc_convo.stf', 26, 'thug_npc_job_offer_2', 'There''s plenty to do if you''re willing to bend a few laws...'),
('string/en/mob/base_npc_convo.stf', 27, 'thug_npc_job_offer_3', 'I don''t know if I trust you, but I got something I need done if you''re willing.'),
('string/en/mob/base_npc_convo.stf', 28, 'player_job_accept', 'Sure, I''ll take your job.'),
('string/en/mob/base_npc_convo.stf', 29, 'player_job_refuse', 'I think I''ll pass on this one.'),
('string/en/mob/base_npc_convo.stf', 30, 'thug_npc_do_job', 'Then get to work!'),
('string/en/mob/base_npc_convo.stf', 31, 'thug_npc_go_home', 'I knew you were a waste of my time.'),
