('string/en/npc_mission/npc_mission_01.stf', 1, 'npc_msn_01_greeting_01', 'Yes? You know this isn''t exactly the BEST time to interrupt me.'),
('string/en/npc_mission/npc_mission_01.stf', 2, 'npc_msn_01_presp_greeting_01', 'I''m looking for work.'),
('string/en/npc_mission/npc_mission_01.stf', 3, 'npc_msn_01_presp_greeting_02', 'You don''t look busy to me.'),
('string/en/npc_mission/npc_mission_01.stf', 4, 'npc_msn_01_busy_01', 'What would you know about it? Tell me what you want or get out of here!'),
('string/en/npc_mission/npc_mission_01.stf', 5, 'npc_msn_01_work_02', 'Hmmm.... Now that I think about it, you might be able to help me out.'),
('string/en/npc_mission/npc_mission_01.stf', 6, 'npc_msn_01_presp_getmission_01', 'I''m ready for some action. What do you have for me?'),
('string/en/npc_mission/npc_mission_01.stf', 7, 'npc_msn_01_presp_getmission_02', 'I would be happy to help you out. What can I do?'),
('string/en/npc_mission/npc_mission_01.stf', 8, 'npc_msn_01_work_01', 'That''s nothing new. Your kind is always looking for odd jobs, aren''t they?'),
('string/en/npc_mission/npc_mission_01.stf', 9, 'npc_msn_01_presp_getmission_03', 'Can we skip the hassle and talk about the job, please?'),
('string/en/npc_mission/npc_mission_01.stf', 10, 'npc_msn_01_presp_getmission_04', 'I''m not looking for trouble, just a job.'),
('string/en/npc_mission/npc_mission_01.stf', 11, 'npc_msn_01_presp_getmission_05', 'I want a job. Don''t you have something that you need done?'),
('string/en/npc_mission/npc_mission_01.stf', 12, 'npc_msn_01_friend_greeting_01', 'Well, hello!'),
('string/en/npc_mission/npc_mission_01.stf', 13, 'npc_msn_01_greeting_02', 'You again.'),
('string/en/npc_mission/npc_mission_01.stf', 14, 'npc_msn_01_greeting_onmission', 'I don''t want to talk again until you''ve finished what I''ve asked you to do.'),
('string/en/npc_mission/npc_mission_01.stf', 15, 'npc_msn_01_friend_greeting_02', 'Nice to see you again.'),
('string/en/npc_mission/npc_mission_01.stf', 16, 'npc_msn_01_friend_greeting_onmission', 'Aren''t you supposed to be helping my friend, here?'),
('string/en/npc_mission/npc_mission_01.stf', 17, 'npc_msn_01_friend_work_01', 'You should speak to my friend. There''s work to be done, but it''s far too dangerous for me!'),
('string/en/npc_mission/npc_mission_01.stf', 18, 'npc_msn_01_greeting_onothermission', 'You need to finish all of your other tasks before we can talk.'),
('string/en/npc_mission/npc_mission_01.stf', 19, 'npc_msn_01_decline', 'Well fine. I didn''t want your help anyways. '),
('string/en/npc_mission/npc_mission_02.stf', 1, 'npc_msn_02_greeting_01', 'Oh thank the maker!  I''ve been waiting for you all day!'),
('string/en/npc_mission/npc_mission_02.stf', 2, 'npc_msn_02_presp_greeting_01', 'Is there something I can do for you?'),
('string/en/npc_mission/npc_mission_02.stf', 3, 'npc_msn_02_presp_greeting_02', 'You''ve been waiting for me?'),
('string/en/npc_mission/npc_mission_02.stf', 4, 'npc_msn_02_busy_01', 'I''ve been waiting for someone to help me.  You are here to help right?'),
('string/en/npc_mission/npc_mission_02.stf', 5, 'npc_msn_02_work_02', 'I desperately need someone to help me out.'),
('string/en/npc_mission/npc_mission_02.stf', 6, 'npc_msn_02_presp_getmission_01', 'Tell me what it is you need done.'),
('string/en/npc_mission/npc_mission_02.stf', 7, 'npc_msn_02_presp_getmission_02', 'Let''s get started then.  What can I do for you?'),
('string/en/npc_mission/npc_mission_02.stf', 8, 'npc_msn_02_work_01', 'Absolutely.  I''m desperately in need of some help.'),
('string/en/npc_mission/npc_mission_02.stf', 9, 'npc_msn_02_presp_getmission_03', 'What is it I can do for you?'),
('string/en/npc_mission/npc_mission_02.stf', 10, 'npc_msn_02_presp_getmission_04', 'I didn''t know you knew who I was.'),
('string/en/npc_mission/npc_mission_02.stf', 11, 'npc_msn_02_presp_getmission_05', 'What is it you need me to do?'),
('string/en/npc_mission/npc_mission_02.stf', 12, 'npc_msn_02_friend_greeting_01', 'Well, hello!'),
('string/en/npc_mission/npc_mission_02.stf', 13, 'npc_msn_02_greeting_02', 'You again.'),
('string/en/npc_mission/npc_mission_02.stf', 14, 'npc_msn_02_greeting_onmission', 'I need you to finish that task we talked about before we do anything else.'),
('string/en/npc_mission/npc_mission_02.stf', 15, 'npc_msn_02_friend_greeting_02', 'Nice to see you again.'),
('string/en/npc_mission/npc_mission_02.stf', 16, 'npc_msn_02_friend_greeting_onmission', 'Aren''t you supposed to be helping my friend, here?'),
('string/en/npc_mission/npc_mission_02.stf', 17, 'npc_msn_02_friend_work_01', 'You should speak to my friend. There''s work to be done, but it''s far too dangerous for me!'),
('string/en/npc_mission/npc_mission_02.stf', 18, 'npc_msn_02_greeting_onothermission', 'You need to finish all of your other tasks before we can talk.'),
('string/en/npc_mission/npc_mission_02.stf', 19, 'npc_msn_02_decline', 'Oh my.  Well, I''ll have to wait for someone else then...'),
('string/en/npc_mission/npc_mission_03.stf', 1, 'npc_msn_03_greeting_01', 'Wait...who are you?  You''re not with THEM are you?'),
('string/en/npc_mission/npc_mission_03.stf', 2, 'npc_msn_03_presp_greeting_01', 'Actually I''m looking for some work.'),
('string/en/npc_mission/npc_mission_03.stf', 3, 'npc_msn_03_presp_greeting_02', 'With WHO?'),
('string/en/npc_mission/npc_mission_03.stf', 4, 'npc_msn_03_busy_01', 'Don''t act like you don''t know!'),
('string/en/npc_mission/npc_mission_03.stf', 5, 'npc_msn_03_work_02', 'There might be something you can do...if I can trust you...'),
('string/en/npc_mission/npc_mission_03.stf', 6, 'npc_msn_03_presp_getmission_01', 'What can I do?'),
('string/en/npc_mission/npc_mission_03.stf', 7, 'npc_msn_03_presp_getmission_02', 'Let''s get started then.  What can I do for you?'),
('string/en/npc_mission/npc_mission_03.stf', 8, 'npc_msn_03_work_01', 'Sure you are...working against me, right?'),
('string/en/npc_mission/npc_mission_03.stf', 9, 'npc_msn_03_presp_getmission_03', 'No really.  I need some work.'),
('string/en/npc_mission/npc_mission_03.stf', 10, 'npc_msn_03_presp_getmission_04', 'You seem upset...can I help out?'),
('string/en/npc_mission/npc_mission_03.stf', 11, 'npc_msn_03_presp_getmission_05', 'You''ve got some serious problems...'),
('string/en/npc_mission/npc_mission_03.stf', 12, 'npc_msn_03_friend_greeting_01', 'Well, hello!'),
('string/en/npc_mission/npc_mission_03.stf', 13, 'npc_msn_03_greeting_02', 'You again.'),
('string/en/npc_mission/npc_mission_03.stf', 14, 'npc_msn_03_greeting_onmission', 'I''m starting to lose my faith in you.  I understand you haven''t finished that job we talked about...'),
('string/en/npc_mission/npc_mission_03.stf', 15, 'npc_msn_03_friend_greeting_02', 'Nice to see you again.'),
('string/en/npc_mission/npc_mission_03.stf', 16, 'npc_msn_03_friend_greeting_onmission', 'Aren''t you supposed to be helping my friend, here?'),
('string/en/npc_mission/npc_mission_03.stf', 17, 'npc_msn_03_friend_work_01', 'You should speak to my friend. There''s work to be done, but it''s far too dangerous for me!'),
('string/en/npc_mission/npc_mission_03.stf', 18, 'npc_msn_03_greeting_onothermission', 'Aren''t you a little busy to be talking to me right now?'),
('string/en/npc_mission/npc_mission_03.stf', 19, 'npc_msn_03_decline', 'Oh my.  Well, I''ll have to wait for someone else then...'),
('string/en/npc_mission/npc_mission_03.stf', 20, 'npc_msn_03_done_01', 'My problems are my own...'),
('string/en/npc_mission/npc_mission_04.stf', 1, 'npc_msn_04_greeting_01', 'Well it''s about time you showed up.'),
('string/en/npc_mission/npc_mission_04.stf', 2, 'npc_msn_04_presp_greeting_01', 'I need a job.'),
('string/en/npc_mission/npc_mission_04.stf', 3, 'npc_msn_04_presp_greeting_02', 'About time?  What do you mean?'),
('string/en/npc_mission/npc_mission_04.stf', 4, 'npc_msn_04_busy_01', 'Not only are you late you''re incompetent?  Is that what''s happened?'),
('string/en/npc_mission/npc_mission_04.stf', 5, 'npc_msn_04_work_02', 'I need this job done now.  Not later.  Now.'),
('string/en/npc_mission/npc_mission_04.stf', 6, 'npc_msn_04_presp_getmission_01', 'Well, let''s get to it then.'),
('string/en/npc_mission/npc_mission_04.stf', 7, 'npc_msn_04_presp_getmission_02', 'I can do whatever needs to be done.'),
('string/en/npc_mission/npc_mission_04.stf', 8, 'npc_msn_04_work_01', 'Doesn''t everybody?'),
('string/en/npc_mission/npc_mission_04.stf', 9, 'npc_msn_04_presp_getmission_03', 'I guess so.'),
('string/en/npc_mission/npc_mission_04.stf', 10, 'npc_msn_04_presp_getmission_04', 'What is your problem?'),
('string/en/npc_mission/npc_mission_04.stf', 11, 'npc_msn_04_presp_getmission_05', 'I''ve had about enough of you.'),
('string/en/npc_mission/npc_mission_04.stf', 12, 'npc_msn_04_friend_greeting_01', 'Well, hello!'),
('string/en/npc_mission/npc_mission_04.stf', 13, 'npc_msn_04_greeting_02', 'You again.'),
('string/en/npc_mission/npc_mission_04.stf', 14, 'npc_msn_04_greeting_onmission', 'Are you STILL not done with that job?'),
('string/en/npc_mission/npc_mission_04.stf', 15, 'npc_msn_04_friend_greeting_02', 'Nice to see you again.'),
('string/en/npc_mission/npc_mission_04.stf', 16, 'npc_msn_04_friend_greeting_onmission', 'Aren''t you supposed to be helping my friend, here?'),
('string/en/npc_mission/npc_mission_04.stf', 17, 'npc_msn_04_friend_work_01', 'You should speak to my friend. There''s work to be done, but it''s far too dangerous for me!'),
('string/en/npc_mission/npc_mission_04.stf', 18, 'npc_msn_04_greeting_onothermission', 'Aren''t you a little busy to be talking to me right now?'),
('string/en/npc_mission/npc_mission_04.stf', 19, 'npc_msn_04_decline', 'Oh my.  Well, I''ll have to wait for someone else then...'),
('string/en/npc_mission/npc_mission_04.stf', 20, 'npc_msn_04_done_01', 'Good, get out of my sight.  I''ve had it with you too.'),
('string/en/npc_mission/npc_mission_05.stf', 1, 'npc_msn_05_greeting_01', 'Hi.  I think you probably need some work.'),
('string/en/npc_mission/npc_mission_05.stf', 2, 'npc_msn_05_presp_greeting_01', 'That''s right.'),
('string/en/npc_mission/npc_mission_05.stf', 3, 'npc_msn_05_presp_greeting_02', 'Do you have work?'),
('string/en/npc_mission/npc_mission_05.stf', 4, 'npc_msn_05_busy_01', 'Of course.  Are you interested in something to do?'),
('string/en/npc_mission/npc_mission_05.stf', 5, 'npc_msn_05_work_02', 'I''ve got something you can do.'),
('string/en/npc_mission/npc_mission_05.stf', 6, 'npc_msn_05_presp_getmission_01', 'Let''s hear what it is.'),
('string/en/npc_mission/npc_mission_05.stf', 7, 'npc_msn_05_presp_getmission_02', 'Do you have a job?'),
('string/en/npc_mission/npc_mission_05.stf', 8, 'npc_msn_05_work_01', 'I figured as much.'),
('string/en/npc_mission/npc_mission_05.stf', 9, 'npc_msn_05_presp_getmission_03', 'So do you have something for me?'),
('string/en/npc_mission/npc_mission_05.stf', 10, 'npc_msn_05_presp_getmission_04', 'Tell me about the job.'),
('string/en/npc_mission/npc_mission_05.stf', 11, 'npc_msn_05_presp_getmission_05', 'Actually, I''m not ready to work right now.'),
('string/en/npc_mission/npc_mission_05.stf', 12, 'npc_msn_05_friend_greeting_01', 'Well, hello!'),
('string/en/npc_mission/npc_mission_05.stf', 13, 'npc_msn_05_greeting_02', 'You again.'),
('string/en/npc_mission/npc_mission_05.stf', 14, 'npc_msn_05_greeting_onmission', 'I''m not going to deal with you until you finish your job.'),
('string/en/npc_mission/npc_mission_05.stf', 15, 'npc_msn_05_friend_greeting_02', 'Nice to see you again.'),
('string/en/npc_mission/npc_mission_05.stf', 16, 'npc_msn_05_friend_greeting_onmission', 'Aren''t you supposed to be helping my friend, here?'),
('string/en/npc_mission/npc_mission_05.stf', 17, 'npc_msn_05_friend_work_01', 'You should speak to my friend. There''s work to be done, but it''s far too dangerous for me!'),
('string/en/npc_mission/npc_mission_05.stf', 18, 'npc_msn_05_greeting_onothermission', 'You look like you''re already busy.'),
('string/en/npc_mission/npc_mission_05.stf', 19, 'npc_msn_05_decline', 'Oh my.  Well, I''ll have to wait for someone else then...'),
('string/en/npc_mission/npc_mission_05.stf', 20, 'npc_msn_05_done_01', 'Well, come back if you change your mind.'),
('string/en/npc_mission/static_businessman_deliver.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_businessman_deliver.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_businessman_deliver.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_businessman_deliver.stf', 16, 'npc_1_1', 'My partner needs to get his briefcase back!  He left for a meeting without it.  If you can take it to him I''ll have him give you some engraved pens from our company business.'),
('string/en/npc_mission/static_businessman_deliver.stf', 17, 'npc_2_1', 'Excellent.  He''ll pay you when you make the delivery.'),
('string/en/npc_mission/static_businessman_deliver.stf', 18, 'npc_3_1', 'Well, if you can''t help me I hope I can find someone who can.'),
('string/en/npc_mission/static_businessman_deliver.stf', 19, 'npc_reward_1', 'Here you go.  It needs some ink, but you''ll never have one better.'),
('string/en/npc_mission/static_businessman_deliver.stf', 20, 'player_1_1', 'Sure I''ll drop it off.'),
('string/en/npc_mission/static_businessman_deliver.stf', 21, 'player_2_1', 'Nah, I don''t feel like it.'),
('string/en/npc_mission/static_businessman_deliver.stf', 22, 'npc_1_2', 'My partner was on his way to an auction to sell off some of our assets.  We need the money to keep our business afloat, but he forgot one of the items we were selling.  Can you take it to him?  He''s right outside of town.'),
('string/en/npc_mission/static_businessman_deliver.stf', 23, 'npc_2_2', 'Great.  I''ll make sure he gets the message that you''re coming.'),
('string/en/npc_mission/static_businessman_deliver.stf', 24, 'npc_3_2', 'That''s too bad.  I''ll find somebody useful.'),
('string/en/npc_mission/static_businessman_deliver.stf', 25, 'npc_reward_2', 'Here you go.  See I had good seats, and I didn''t let them tear it.  You should be able to get something for it if you want.'),
('string/en/npc_mission/static_businessman_deliver.stf', 26, 'player_1_2', 'No problem.  I was looking for something to do.'),
('string/en/npc_mission/static_businessman_deliver.stf', 27, 'player_2_2', 'Sorry, I''m a bit busy at the moment.'),
('string/en/npc_mission/static_businessman_deliver.stf', 28, 'npc_4_1', 'All the paperwork that needs to be signed at the meeting.  It''s vitally important that it get there.'),
('string/en/npc_mission/static_businessman_deliver.stf', 29, 'npc_4_2', 'It''s an autographed trophy from some sports figure.  I don''t know who he is, but I want to get it to him so he can sell it.'),
('string/en/npc_mission/static_businessman_deliver.stf', 30, 'player_3_1', 'What was in the briefcase?'),
('string/en/npc_mission/static_businessman_deliver.stf', 31, 'player_3_2', 'What is the item exactly?'),
('string/en/npc_mission/static_businessman_destroy.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_businessman_destroy.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_businessman_destroy.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_businessman_destroy.stf', 16, 'npc_1_1', 'An industrial spy has decided that the best way to help his company is by becoming a murderer and killing our top executives.  I want this guy eliminated, and I don''t care to know the details.  Up for this?'),
('string/en/npc_mission/static_businessman_destroy.stf', 17, 'npc_2_1', 'Thank you...I''ll be waiting anxiously for your return.'),
('string/en/npc_mission/static_businessman_destroy.stf', 18, 'npc_3_1', 'Surely somebody will be able to help me.  Thanks for nothing, though.'),
('string/en/npc_mission/static_businessman_destroy.stf', 19, 'npc_reward_1', 'Here you go.  It needs some ink, but you''ll never have one better.'),
('string/en/npc_mission/static_businessman_destroy.stf', 20, 'player_1_1', 'I''ll be back before you know it.'),
('string/en/npc_mission/static_businessman_destroy.stf', 21, 'player_2_1', 'There''s no way.  Sounds dangerous.'),
('string/en/npc_mission/static_businessman_destroy.stf', 22, 'npc_1_2', 'There''s a madman claiming to be a business executive killing young Twilek women on this planet.  I know where he is, but the police won''t listen to me.  I''ll pay you myself if you''ll take care of this.'),
('string/en/npc_mission/static_businessman_destroy.stf', 23, 'npc_2_2', 'Great!  Hurry back.'),
('string/en/npc_mission/static_businessman_destroy.stf', 24, 'npc_3_2', 'That''s too bad.  I''ll find somebody useful.'),
('string/en/npc_mission/static_businessman_destroy.stf', 25, 'npc_reward_2', 'Here you go.  See I had good seats, and I didn''t let them tear it.  You should be able to get something for it if you want.'),
('string/en/npc_mission/static_businessman_destroy.stf', 26, 'player_1_2', 'I''ll take care of it.  Someone has to.'),
('string/en/npc_mission/static_businessman_destroy.stf', 27, 'player_2_2', 'Nah.  It''s not my problem.'),
('string/en/npc_mission/static_businessman_destroy.stf', 28, 'npc_4_1', 'I can''t discuss it for legal reasons.'),
('string/en/npc_mission/static_businessman_destroy.stf', 29, 'npc_4_2', 'I''m not sure.  Maybe he was jilted by one.  Or maybe he''s just crazy.  Does the why really matter at this point?'),
('string/en/npc_mission/static_businessman_destroy.stf', 30, 'player_3_1', 'Who does he work for?'),
('string/en/npc_mission/static_businessman_destroy.stf', 31, 'player_3_2', 'Why Twileks?'),
('string/en/npc_mission/static_businessman_escort.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_businessman_escort.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_businessman_escort.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_businessman_escort.stf', 16, 'npc_1_1', 'My partner needs to get back here fast.  We''re going to be late for a meeting and I''m all alone.  Can you go get my partner?'),
('string/en/npc_mission/static_businessman_escort.stf', 17, 'npc_2_1', 'Excellent.  We''ll pay you when you get back.'),
('string/en/npc_mission/static_businessman_escort.stf', 18, 'npc_3_1', 'Well, if you can''t help me I hope I can find someone who can.'),
('string/en/npc_mission/static_businessman_escort.stf', 19, 'npc_reward_1', 'Here you go.  It needs some ink, but you''ll never have one better.'),
('string/en/npc_mission/static_businessman_escort.stf', 20, 'player_1_1', 'Sure I''ll find your friend.'),
('string/en/npc_mission/static_businessman_escort.stf', 21, 'player_2_1', 'Nah, I don''t feel like it.'),
('string/en/npc_mission/static_businessman_escort.stf', 22, 'npc_1_2', 'My partner was at an auction selling some assets for capital.  I need somone to find and bring them back.  can you help?'),
('string/en/npc_mission/static_businessman_escort.stf', 23, 'npc_2_2', 'Great.  I''ll make sure the message gets through that you''re coming.'),
('string/en/npc_mission/static_businessman_escort.stf', 24, 'npc_3_2', 'That''s too bad.  I''ll find somebody useful.'),
('string/en/npc_mission/static_businessman_escort.stf', 25, 'npc_reward_2', 'Here you go.  See I had good seats, and I didn''t let them tear it.  You should be able to get something for it if you want.'),
('string/en/npc_mission/static_businessman_escort.stf', 26, 'player_1_2', 'No problem.  I was looking for something to do.'),
('string/en/npc_mission/static_businessman_escort.stf', 27, 'player_2_2', 'Sorry, I''m a bit busy at the moment.'),
('string/en/npc_mission/static_businessman_escort.stf', 28, 'npc_4_1', 'Merger.  There''s a lot of paperwork to sign and I''m not authorized to do it alone.'),
('string/en/npc_mission/static_businessman_escort.stf', 29, 'npc_4_2', 'It''s an autographed trophy from some sports figure.  I don''t know who he is, but apparently it sold well.'),
('string/en/npc_mission/static_businessman_escort.stf', 30, 'player_3_1', 'What kind of meeting is it?'),
('string/en/npc_mission/static_businessman_escort.stf', 31, 'player_3_2', 'What were you selling?'),
('string/en/npc_mission/static_businessman_escort.stf', 32, 'npc_takeme_1', 'Great, you''re here.  We don''t want to be late for this meeting so let''s get back quickly.'),
('string/en/npc_mission/static_businessman_escort.stf', 33, 'npc_takeme_2', 'Oh good, you made it.  I got the money transferred to our bank, but I''m lost out here.  Should have hired a guide, huh?'),
('string/en/npc_mission/static_businessman_escort.stf', 34, 'escortother', 'I don''t think I''m the person you''re looking for.'),
('string/en/npc_mission/static_businessman_escort.stf', 35, 'dontknowyou', 'I don''t know who you are, but I''m not going with you.'),
('string/en/npc_mission/static_businessman_fetch.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_businessman_fetch.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_businessman_fetch.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_businessman_fetch.stf', 16, 'npc_1_1', 'I had a lot of important paperwork in my briefcase, and now it''s gone!  Some thief came by and grabbed it out of my hands.  If you can get it I''ll give you this engraved writing stylus I got when I got my promotion.'),
('string/en/npc_mission/static_businessman_fetch.stf', 17, 'npc_2_1', 'Thank you...I''ll be waiting anxiously for your return.'),
('string/en/npc_mission/static_businessman_fetch.stf', 18, 'npc_3_1', 'Surely somebody will be able to help me.  Thanks for nothing, though.'),
('string/en/npc_mission/static_businessman_fetch.stf', 19, 'npc_reward_1', 'Here you go.  It needs some ink, but you''ll never have one better.'),
('string/en/npc_mission/static_businessman_fetch.stf', 20, 'player_1_1', 'I''ll be back before you know it.'),
('string/en/npc_mission/static_businessman_fetch.stf', 21, 'player_2_1', 'There''s no way.  I''m too tired right now.'),
('string/en/npc_mission/static_businessman_fetch.stf', 22, 'npc_1_2', 'I had an autographed ball from my favorite player in the league, and somebody took it!  If you can get it back for me I''ll give you this collector''s item ticket from last year''s championships.  It''s worth plenty.'),
('string/en/npc_mission/static_businessman_fetch.stf', 23, 'npc_2_2', 'Great!  Hurry back.'),
('string/en/npc_mission/static_businessman_fetch.stf', 24, 'npc_3_2', 'That''s too bad.  I''ll find somebody useful.'),
('string/en/npc_mission/static_businessman_fetch.stf', 25, 'npc_reward_2', 'Here you go.  See I had good seats, and I didn''t let them tear it.  You should be able to get something for it if you want.'),
('string/en/npc_mission/static_businessman_fetch.stf', 26, 'player_1_2', 'I''ll be right back with your ball kid.'),
('string/en/npc_mission/static_businessman_fetch.stf', 27, 'player_2_2', 'Nah.  I don''t care about sports.'),
('string/en/npc_mission/static_businessman_fetch.stf', 28, 'npc_4_1', 'It was mostly my personal accounting, but there are some sensitive documents in there that I can''t discuss.'),
('string/en/npc_mission/static_businessman_fetch.stf', 29, 'npc_4_2', 'Don''t you follow sports at all?  If you did you''d know what I was talking about.'),
('string/en/npc_mission/static_businessman_fetch.stf', 30, 'player_3_1', 'What kind of documents did you have?'),
('string/en/npc_mission/static_businessman_fetch.stf', 31, 'player_3_2', 'What league are you talking about?'),
('string/en/npc_mission/static_criminal_deliver.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_criminal_deliver.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_criminal_deliver.stf', 3, 'npc_1_1', 'You ever hear of the Black Sun Pirates?  They robbed me and I want to pay them back.  Unfortunately, I need to get one of their medallions to get inside their base.  Can you help me get one?'),
('string/en/npc_mission/static_criminal_deliver.stf', 4, 'player_1_1', 'Ok, I''ll do it.'),
('string/en/npc_mission/static_criminal_deliver.stf', 5, 'player_2_1', 'Sounds dangerous.  I don''t think I''m up to it.'),
('string/en/npc_mission/static_criminal_deliver.stf', 6, 'npc_2_1', 'Good.  Get back as soon as you can and I''ll get you a shisa.  You can use it in your home as a decoration, or sell it, I don''t care either way.'),
('string/en/npc_mission/static_criminal_deliver.stf', 7, 'npc_3_1', 'Too bad.  I would have given you a nice gift.'),
('string/en/npc_mission/static_criminal_deliver.stf', 8, 'npc_reward_1', 'Here''s that shisa I promised ya.  I''ll just put it here in your pack.'),
('string/en/npc_mission/static_criminal_deliver.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_criminal_deliver.stf', 10, 'npc_1_2', 'I made a terrible mistake and got busted on camera stealing some credits from a merchant.  The trial''s coming up soon and I need someone to get that camera.  I can tell you where it''s at if you''ll get it.'),
('string/en/npc_mission/static_criminal_deliver.stf', 11, 'npc_2_2', 'Good.  As soon as you return I''ll give you the decryptor.'),
('string/en/npc_mission/static_criminal_deliver.stf', 12, 'npc_3_2', 'Well, guess I''ll have to find somebody else then.'),
('string/en/npc_mission/static_criminal_deliver.stf', 13, 'npc_reward_2', 'Here''s the decryptor.  It doesn''t work all the time, but I''m sure you''ll find a use for it.'),
('string/en/npc_mission/static_criminal_deliver.stf', 14, 'player_1_2', 'Yeah, I can get that, no problem.'),
('string/en/npc_mission/static_criminal_deliver.stf', 15, 'player_2_2', 'That''s too much work.  I''m not doing it.'),
('string/en/npc_mission/static_criminal_deliver.stf', 28, 'npc_1_3', 'I''ve been collecting memorabilia of the Dark Jedi.  I know a guy who has a Medallion that they used.  Get it for me and I''ll give you these broken holocron pieces.  I''ve got tons of holocrons.  They''re bound to be worth something.'),
('string/en/npc_mission/static_criminal_deliver.stf', 29, 'npc_2_3', 'You do the work, you get paid.  I''ll be here.'),
('string/en/npc_mission/static_criminal_deliver.stf', 30, 'npc_3_3', 'Not much I can do about it I guess, if you''re not good enough.'),
('string/en/npc_mission/static_criminal_deliver.stf', 31, 'npc_reward_3', 'Here they are.  Careful, they have sharp edges.'),
('string/en/npc_mission/static_criminal_deliver.stf', 32, 'player_1_3', 'Yeah, I can do it.  '),
('string/en/npc_mission/static_criminal_deliver.stf', 33, 'player_2_3', 'Too much work for me.'),
('string/en/npc_mission/static_criminal_deliver.stf', 64, 'npc_1_4', 'I need an electronic key to break into this warehouse I''ve been casing, but one of my rivals has it.  Get it for me and I''ll give you some of the loot I got on my last job.'),
('string/en/npc_mission/static_criminal_deliver.stf', 65, 'npc_2_4', 'Great.  I''ve got just the thing for you.  Let me know when you''re back.'),
('string/en/npc_mission/static_criminal_deliver.stf', 66, 'npc_3_4', 'Well, you''ll never be a criminal in this town.'),
('string/en/npc_mission/static_criminal_deliver.stf', 67, 'player_1_4', 'I can do it.  No problem.'),
('string/en/npc_mission/static_criminal_deliver.stf', 68, 'player_2_4', 'Thieves should do their own dirty work.'),
('string/en/npc_mission/static_criminal_deliver.stf', 69, 'npc_reward_4', 'Here you go.  I took this speaker from a cantina I robbed.  It''ll go nicely in your house.'),
('string/en/npc_mission/static_criminal_deliver.stf', 70, 'npc_4_1', 'They have too many members to know each other, so anyone with a medallion can get into their areas.  If I had one I could pass myself off as a member of the group.'),
('string/en/npc_mission/static_criminal_deliver.stf', 71, 'npc_4_2', 'I paid off some guys and found out it''s being delivered to a highly secure area today.  You can get it on route before the guy gets there.'),
('string/en/npc_mission/static_criminal_deliver.stf', 72, 'npc_4_3', 'You could try to put ''em back together.  Or find someone else who collects them and sell them maybe?  I don''t know, but I know they''re worth something.'),
('string/en/npc_mission/static_criminal_deliver.stf', 73, 'npc_4_4', 'He stole it before I could get to it.  He''ll rob the warehouse instead of me if you don''t get it for me.  I need that key!'),
('string/en/npc_mission/static_criminal_deliver.stf', 74, 'player_3_1', 'How is a medallion going to help you?'),
('string/en/npc_mission/static_criminal_deliver.stf', 75, 'player_3_2', 'How do you know where the camera is?'),
('string/en/npc_mission/static_criminal_deliver.stf', 76, 'player_3_3', 'What can I do with broken pieces?'),
('string/en/npc_mission/static_criminal_deliver.stf', 77, 'player_3_4', 'How did your rival get the key?'),
('string/en/npc_mission/static_criminal_escort.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_criminal_escort.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_criminal_escort.stf', 3, 'npc_1_1', 'A friend of mine got mugged by black sun pirates and is too scared to come back to town.  I need someone to go make sure they can find their way back here.  Can you do it?'),
('string/en/npc_mission/static_criminal_escort.stf', 4, 'player_1_1', 'Ok, I''ll do it.'),
('string/en/npc_mission/static_criminal_escort.stf', 5, 'player_2_1', 'Sounds dangerous.  I don''t think I''m up to it.'),
('string/en/npc_mission/static_criminal_escort.stf', 6, 'npc_2_1', 'Good.  Get back as soon as you can and I''ll get you a shisa.  You can use it in your home as a decoration, or sell it, I don''t care either way.'),
('string/en/npc_mission/static_criminal_escort.stf', 7, 'npc_3_1', 'Too bad.  I would have given you a nice gift.'),
('string/en/npc_mission/static_criminal_escort.stf', 8, 'npc_reward_1', 'Here''s that shisa I promised ya.  I''ll just put it here in your pack.'),
('string/en/npc_mission/static_criminal_escort.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_criminal_escort.stf', 10, 'npc_1_2', 'My partner has all our cash, but got lost in the wilderness.  I need someone to escort them back here to me.'),
('string/en/npc_mission/static_criminal_escort.stf', 11, 'npc_2_2', 'Good.  As soon as you return I''ll give you something nice.'),
('string/en/npc_mission/static_criminal_escort.stf', 12, 'npc_3_2', 'Well, guess I''ll have to find somebody else then.'),
('string/en/npc_mission/static_criminal_escort.stf', 13, 'npc_reward_2', 'Here''s the decryptor.  It doesn''t work all the time, but I''m sure you''ll find a use for it.'),
('string/en/npc_mission/static_criminal_escort.stf', 14, 'player_1_2', 'Yeah, I can do that, no problem.'),
('string/en/npc_mission/static_criminal_escort.stf', 15, 'player_2_2', 'That''s too much work.  I''m not doing it.'),
('string/en/npc_mission/static_criminal_escort.stf', 28, 'npc_1_3', 'Are you available to help me out with something?  I got somebody new coming in and I need you to bring them straight to me.  Can you do that?'),
('string/en/npc_mission/static_criminal_escort.stf', 29, 'npc_2_3', 'You do the work, you get paid.  I''ll be here.'),
('string/en/npc_mission/static_criminal_escort.stf', 30, 'npc_3_3', 'Not much I can do about it I guess, if you''re not good enough.'),
('string/en/npc_mission/static_criminal_escort.stf', 31, 'npc_reward_3', 'Here they are.  Careful, they have sharp edges.'),
('string/en/npc_mission/static_criminal_escort.stf', 32, 'player_1_3', 'Yeah, I can do it.  '),
('string/en/npc_mission/static_criminal_escort.stf', 33, 'player_2_3', 'Too much work for me.'),
('string/en/npc_mission/static_criminal_escort.stf', 64, 'npc_1_4', 'My partner was trying to avoid some imperial patrols and managed to get lost outside of town.  Can you go out there and make sure there''s no trouble getting back to me?'),
('string/en/npc_mission/static_criminal_escort.stf', 65, 'npc_2_4', 'Great.  I''ve got just the thing for you.  Let me know when you''re back.'),
('string/en/npc_mission/static_criminal_escort.stf', 66, 'npc_3_4', 'Well, you''ll never be a criminal in this town.'),
('string/en/npc_mission/static_criminal_escort.stf', 67, 'player_1_4', 'I can do it.  No problem.'),
('string/en/npc_mission/static_criminal_escort.stf', 68, 'player_2_4', 'Thieves should do their own dirty work.'),
('string/en/npc_mission/static_criminal_escort.stf', 69, 'npc_reward_4', 'Here you go.  I took this speaker from a cantina I robbed.  It''ll go nicely in your house.'),
('string/en/npc_mission/static_criminal_escort.stf', 70, 'npc_4_1', 'No, I think they''ve given up.  There might be some still around, but this should be pretty simple.'),
('string/en/npc_mission/static_criminal_escort.stf', 71, 'npc_4_2', 'I don''t think you need to know that just now.  Just bring my friend here.'),
('string/en/npc_mission/static_criminal_escort.stf', 72, 'npc_4_3', 'Brand new.  I haven''t even met them.  I don''t even know if it''s a male or a female!'),
('string/en/npc_mission/static_criminal_escort.stf', 73, 'npc_4_4', 'No, they''ve given up.  Any imperials you see out there will just be a coincidence.'),
('string/en/npc_mission/static_criminal_escort.stf', 74, 'player_3_1', 'Are there still Black Sun Pirates out there?'),
('string/en/npc_mission/static_criminal_escort.stf', 75, 'player_3_2', 'How much cash was there?'),
('string/en/npc_mission/static_criminal_escort.stf', 76, 'player_3_3', 'How new is this person?'),
('string/en/npc_mission/static_criminal_escort.stf', 77, 'player_3_4', 'Are the imperials still snooping around?'),
('string/en/npc_mission/static_criminal_escort.stf', 78, 'npc_takeme_1', 'Finally.  I was about to give up and try finding my way in on my own.'),
('string/en/npc_mission/static_criminal_escort.stf', 79, 'npc_takeme_2', 'You''re here to take me back?  Don''t worry about the money.  I hid it.  It''s not on me anymore.  Just get me to my friend.'),
('string/en/npc_mission/static_criminal_escort.stf', 80, 'npc_takeme_3', 'Great!  I need you to take me to my new boss.  I don''t even know who it is yet.'),
('string/en/npc_mission/static_criminal_escort.stf', 81, 'npc_takeme_4', 'Quick, let''s get back before the imperials start looking around for me again.'),
('string/en/npc_mission/static_criminal_escort.stf', 82, 'otherescort', 'I think you''re here to take someone else back.'),
('string/en/npc_mission/static_criminal_escort.stf', 83, 'dontknowyou', 'I''m not sure who you are, but I''m not following you back to town.  No way.'),
('string/en/npc_mission/static_criminal_fetch.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_criminal_fetch.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_criminal_fetch.stf', 3, 'npc_1_1', 'You ever hear of the Black Sun Pirates?  They robbed me and I want to pay them back.  Unfortunately, I need to get one of their medallions to get inside their base.  Can you help me get one?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/npc_mission/static_criminal_fetch.stf', 4, 'player_1_1', 'Ok, I''ll do it.'),
('string/en/npc_mission/static_criminal_fetch.stf', 5, 'player_2_1', 'Sounds dangerous.  I don''t think I''m up to it.'),
('string/en/npc_mission/static_criminal_fetch.stf', 6, 'npc_2_1', 'Good.  Get back as soon as you can and I''ll get you a shisa.  You can use it in your home as a decoration, or sell it, I don''t care either way.'),
('string/en/npc_mission/static_criminal_fetch.stf', 7, 'npc_3_1', 'Too bad.  I would have given you a nice gift.'),
('string/en/npc_mission/static_criminal_fetch.stf', 8, 'npc_reward_1', 'Here''s that shisa I promised ya.  I''ll just put it here in your pack.'),
('string/en/npc_mission/static_criminal_fetch.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_criminal_fetch.stf', 10, 'npc_1_2', 'I made a terrible mistake and got busted on camera stealing some credits from a merchant.  The trial''s coming up soon and I need someone to get that camera.  I can tell you where it''s at if you''ll get it.'),
('string/en/npc_mission/static_criminal_fetch.stf', 11, 'npc_2_2', 'Good.  As soon as you return I''ll give you the decryptor.'),
('string/en/npc_mission/static_criminal_fetch.stf', 12, 'npc_3_2', 'Well, guess I''ll have to find somebody else then.'),
('string/en/npc_mission/static_criminal_fetch.stf', 13, 'npc_reward_2', 'Here''s the decryptor.  It doesn''t work all the time, but I''m sure you''ll find a use for it.'),
('string/en/npc_mission/static_criminal_fetch.stf', 14, 'player_1_2', 'Yeah, I can get that, no problem.'),
('string/en/npc_mission/static_criminal_fetch.stf', 15, 'player_2_2', 'That''s too much work.  I''m not doing it.'),
('string/en/npc_mission/static_criminal_fetch.stf', 28, 'npc_1_3', 'I''ve been collecting memorabilia of the Dark Jedi.  I know a guy who has a Medallion that they used.  Get it for me and I''ll give you these broken holocron pieces.  I''ve got tons of holocrons.  They''re bound to be worth something.'),
('string/en/npc_mission/static_criminal_fetch.stf', 29, 'npc_2_3', 'You do the work, you get paid.  I''ll be here.'),
('string/en/npc_mission/static_criminal_fetch.stf', 30, 'npc_3_3', 'Not much I can do about it I guess, if you''re not good enough.'),
('string/en/npc_mission/static_criminal_fetch.stf', 31, 'npc_reward_3', 'Here they are.  Careful, they have sharp edges.'),
('string/en/npc_mission/static_criminal_fetch.stf', 32, 'player_1_3', 'Yeah, I can do it.  '),
('string/en/npc_mission/static_criminal_fetch.stf', 33, 'player_2_3', 'Too much work for me.'),
('string/en/npc_mission/static_criminal_fetch.stf', 64, 'npc_1_4', 'I need an electronic key to break into this warehouse I''ve been casing, but one of my rivals has it.  Get it for me and I''ll give you some of the loot I got on my last job.'),
('string/en/npc_mission/static_criminal_fetch.stf', 65, 'npc_2_4', 'Great.  I''ve got just the thing for you.  Let me know when you''re back.'),
('string/en/npc_mission/static_criminal_fetch.stf', 66, 'npc_3_4', 'Well, you''ll never be a criminal in this town.'),
('string/en/npc_mission/static_criminal_fetch.stf', 67, 'player_1_4', 'I can do it.  No problem.'),
('string/en/npc_mission/static_criminal_fetch.stf', 68, 'player_2_4', 'Thieves should do their own dirty work.'),
('string/en/npc_mission/static_criminal_fetch.stf', 69, 'npc_reward_4', 'Here you go.  I took this speaker from a cantina I robbed.  It''ll go nicely in your house.'),
('string/en/npc_mission/static_criminal_fetch.stf', 70, 'npc_4_1', 'They have too many members to know each other, so anyone with a medallion can get into their areas.  If I had one I could pass myself off as a member of the group.'),
('string/en/npc_mission/static_criminal_fetch.stf', 71, 'npc_4_2', 'I paid off some guys and found out it''s being delivered to a highly secure area today.  You can get it on route before the guy gets there.'),
('string/en/npc_mission/static_criminal_fetch.stf', 72, 'npc_4_3', 'You could try to put ''em back together.  Or find someone else who collects them and sell them maybe?  I don''t know, but I know they''re worth something.'),
('string/en/npc_mission/static_criminal_fetch.stf', 73, 'npc_4_4', 'He stole it before I could get to it.  He''ll rob the warehouse instead of me if you don''t get it for me.  I need that key!'),
('string/en/npc_mission/static_criminal_fetch.stf', 74, 'player_3_1', 'How is a medallion going to help you?'),
('string/en/npc_mission/static_criminal_fetch.stf', 75, 'player_3_2', 'How do you know where the camera is?'),
('string/en/npc_mission/static_criminal_fetch.stf', 76, 'player_3_3', 'What can I do with broken pieces?'),
('string/en/npc_mission/static_criminal_fetch.stf', 77, 'player_3_4', 'How did your rival get the key?'),
('string/en/npc_mission/static_noble_deliver.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_noble_deliver.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_noble_deliver.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_noble_deliver.stf', 34, 'npc_1_1', 'My family has had this heirloom glass for many years, and now it''s been stolen.  I can tell you where the thief is, but I need you to bring back my glass unharmed.  Can you do it?'),
('string/en/npc_mission/static_noble_deliver.stf', 35, 'npc_2_1', 'You''re a life saver.  I''ll give you this hand woven basket for the glass when you return.  My servants made it.'),
('string/en/npc_mission/static_noble_deliver.stf', 36, 'npc_3_1', 'I thought you were a mercenary?  Perhaps you''re just a librarian or some such...'),
('string/en/npc_mission/static_noble_deliver.stf', 37, 'player_1_1', 'Yeah, I can get it.  I''ll need some form of payment though.'),
('string/en/npc_mission/static_noble_deliver.stf', 38, 'player_2_1', 'Sounds ridiculous.  Why don''t you just go buy a new glass?'),
('string/en/npc_mission/static_noble_deliver.stf', 39, 'npc_reward_1', 'Careful with this thing.  It''s well put together, but if you crush it it won''t be worth as much.'),
('string/en/npc_mission/static_noble_deliver.stf', 52, 'npc_1_2', 'I was collecting signatures to get my name on the local ballot when one of my opponents sent a theif to steal my ledger.  If you can get that ledger back for me I''ll write a proclamation declaring you a good citizen.'),
('string/en/npc_mission/static_noble_deliver.stf', 53, 'npc_2_2', 'Excellent.  Just let me know when you return, I''ll have the paperwork drawn up.'),
('string/en/npc_mission/static_noble_deliver.stf', 54, 'npc_3_2', 'That''s too bad.  I could have done you a lot of favors.'),
('string/en/npc_mission/static_noble_deliver.stf', 55, 'player_1_2', 'Sure, I''ll get your ledger back.  I need friends in high places.'),
('string/en/npc_mission/static_noble_deliver.stf', 56, 'player_2_2', 'No way.   I couldn''t care less about politics.'),
('string/en/npc_mission/static_noble_deliver.stf', 57, 'npc_reward_2', 'Here''s your official proclamation.  It won''t be valid unless I get elected, but hang onto it just in case.'),
('string/en/npc_mission/static_noble_deliver.stf', 58, 'npc_1_3', 'A gang of ruffians stole part of the hyperdrive out of my ship.  Get it back for me and I''ll give you something nice.'),
('string/en/npc_mission/static_noble_deliver.stf', 59, 'npc_2_3', 'Ok.  Just let me know when you''ve got it.'),
('string/en/npc_mission/static_noble_deliver.stf', 60, 'npc_3_3', 'I thought you were a tough one.  I guess not.'),
('string/en/npc_mission/static_noble_deliver.stf', 61, 'player_1_3', 'Sure, I''ll help you out.'),
('string/en/npc_mission/static_noble_deliver.stf', 62, 'player_2_3', 'I thought pilot''s did their own work.  I''ll be going.'),
('string/en/npc_mission/static_noble_deliver.stf', 63, 'npc_reward_3', 'Here you go.  This is a picture I took taking off from an undiscovered planet.  That picture is one of a kind.'),
('string/en/npc_mission/static_noble_deliver.stf', 70, 'player_1_4', 'Sounds crazy but I''ll do it.'),
('string/en/npc_mission/static_noble_deliver.stf', 71, 'player_2_4', 'Sounds ludicrous.  Count me out.'),
('string/en/npc_mission/static_noble_deliver.stf', 72, 'npc_1_4', 'My servants won''t get me the dishes I want.  There''s  a guy who has a bowl that''s the exact one I want.  I don''t care how you do it, just get me that bowl.'),
('string/en/npc_mission/static_noble_deliver.stf', 73, 'npc_2_4', 'I thought you looked like the man I wanted.  I''ll reward you nicely for it.'),
('string/en/npc_mission/static_noble_deliver.stf', 74, 'npc_3_4', 'Just like my servants.  No help at all.'),
('string/en/npc_mission/static_noble_deliver.stf', 75, 'npc_reward_4', 'Here''s a recording rod that I paid way too much for.  It''s valuable but fragile.  Be careful with it.'),
('string/en/npc_mission/static_noble_deliver.stf', 76, 'npc_4_1', 'Well, it''s not much to look at, but I guess because it was in the safe they assumed it was valuable.  It is, but only to me really, they won''t get much for it.'),
('string/en/npc_mission/static_noble_deliver.stf', 77, 'npc_4_2', 'Actually I don''t remember.  That''s another reason I need that ledger back.  It might have been mayor...or chief of police...hm...'),
('string/en/npc_mission/static_noble_deliver.stf', 78, 'npc_4_3', 'Ship parts are expensive.  They''re probably trying to build their own ship, or they''re going to sell it on the black market.'),
('string/en/npc_mission/static_noble_deliver.stf', 79, 'npc_4_4', 'A nobleman gets other people to do these things for him.  People like you.'),
('string/en/npc_mission/static_noble_deliver.stf', 80, 'player_3_1', 'Somebody stole an heirloom glass?  Why?'),
('string/en/npc_mission/static_noble_deliver.stf', 81, 'player_3_2', 'What office are you running for?'),
('string/en/npc_mission/static_noble_deliver.stf', 82, 'player_3_3', 'Why would they steal parts of your ship?'),
('string/en/npc_mission/static_noble_deliver.stf', 83, 'player_3_4', 'Why don''t you just buy your own dishes?'),
('string/en/npc_mission/static_noble_escort.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_noble_escort.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_noble_escort.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_noble_escort.stf', 34, 'npc_1_1', 'A good friend of mine has gotten lost outside of town and needs to find a way to get back to me.  Can you help?'),
('string/en/npc_mission/static_noble_escort.stf', 35, 'npc_2_1', 'Good.  I''ll let you in on a little secret...this person''s not exactly a friend, but don''t worry, you''ll get paid for your work.'),
('string/en/npc_mission/static_noble_escort.stf', 36, 'npc_3_1', 'Oh.  Well, fine then.  Be that way.'),
('string/en/npc_mission/static_noble_escort.stf', 37, 'player_1_1', 'Yeah, I can do it.  I''ll need some form of payment though.'),
('string/en/npc_mission/static_noble_escort.stf', 38, 'player_2_1', 'Sounds ridiculous.  I''m outta here.'),
('string/en/npc_mission/static_noble_escort.stf', 39, 'npc_reward_1', 'Careful with this thing.  It''s well put together, but if you crush it it won''t be worth as much.'),
('string/en/npc_mission/static_noble_escort.stf', 52, 'npc_1_2', 'One of my relatives is trying to get to me so that we can go to a reception together, but has managed to get lost outside of town.  Can you help out?'),
('string/en/npc_mission/static_noble_escort.stf', 53, 'npc_2_2', 'Hurry please, I don''t want the party to start without us!'),
('string/en/npc_mission/static_noble_escort.stf', 54, 'npc_3_2', 'You have no idea how much damage I could do to your life.  But begone, and if you''re lucky I''ll forget you.'),
('string/en/npc_mission/static_noble_escort.stf', 55, 'player_1_2', 'Sure, I''ll get your friend.'),
('string/en/npc_mission/static_noble_escort.stf', 56, 'player_2_2', 'No way.   I couldn''t care less about this.'),
('string/en/npc_mission/static_noble_escort.stf', 57, 'npc_reward_2', 'Here''s your official proclamation.  It won''t be valid unless I get elected, but hang onto it just in case.'),
('string/en/npc_mission/static_noble_escort.stf', 58, 'npc_1_3', 'My friend got lost trying to find his way home.  I think there may have been some Corellian wine involved, you know?  Can you help my friend make it back to me here?'),
('string/en/npc_mission/static_noble_escort.stf', 59, 'npc_2_3', 'Good.  When you get back we''ll work out some payment arrangements.'),
('string/en/npc_mission/static_noble_escort.stf', 60, 'npc_3_3', 'I should have taken the advice of the jawas.  They told me not to trust people like you.'),
('string/en/npc_mission/static_noble_escort.stf', 61, 'player_1_3', 'Sure, I''ll help you out.'),
('string/en/npc_mission/static_noble_escort.stf', 62, 'player_2_3', 'I thought rich people had servants to do their work.'),
('string/en/npc_mission/static_noble_escort.stf', 63, 'npc_reward_3', 'Here you go.  This is a picture I took taking off from an undiscovered planet.  That picture is one of a kind.'),
('string/en/npc_mission/static_noble_escort.stf', 70, 'player_1_4', 'Sounds crazy but I''ll do it.'),
('string/en/npc_mission/static_noble_escort.stf', 71, 'player_2_4', 'Sounds ludicrous.  Count me out.'),
('string/en/npc_mission/static_noble_escort.stf', 72, 'npc_1_4', 'Sibling rivalry has led to a very severe game of hide and seek, unfortunately one of the players is still hiding and doesn''t realize the game is over.  I need someone to find them and bring them back here to me.'),
('string/en/npc_mission/static_noble_escort.stf', 73, 'npc_2_4', 'Very nice of you, I must say.  I thought you looked a little, um...dangerous, but I can see you''re as trustworthy as the day is long.'),
('string/en/npc_mission/static_noble_escort.stf', 74, 'npc_3_4', 'Just like my servants.  No help at all.  Good day.'),
('string/en/npc_mission/static_noble_escort.stf', 75, 'npc_reward_4', 'Here''s a recording rod that I paid way too much for.  It''s valuable but fragile.  Be careful with it.'),
('string/en/npc_mission/static_noble_escort.stf', 76, 'npc_4_1', 'Well, this and that.  There''s not much to tell really.  You know.  '),
('string/en/npc_mission/static_noble_escort.stf', 77, 'npc_4_2', 'It''s my uncle''s fiftieth birthday, or my aunt''s fortieth birthday, or my grandparent''s wedding anniversary...or...no, I can''t remember.  '),
('string/en/npc_mission/static_noble_escort.stf', 78, 'npc_4_3', 'Only when we''re celebrating.  Which is pretty much every day I gues...'),
('string/en/npc_mission/static_noble_escort.stf', 79, 'npc_4_4', 'Well, when you''re rich you can pretty much do what you want.'),
('string/en/npc_mission/static_noble_escort.stf', 80, 'player_3_1', 'What does this friend of yours do?'),
('string/en/npc_mission/static_noble_escort.stf', 81, 'player_3_2', 'What''s the reception for?'),
('string/en/npc_mission/static_noble_escort.stf', 82, 'player_3_3', 'Does this happen often?'),
('string/en/npc_mission/static_noble_escort.stf', 83, 'player_3_4', 'You guys just play hide and seek out in the desert?'),
('string/en/npc_mission/static_noble_escort.stf', 84, 'dontknowyou', 'I''m sorry but I don''t recognize you and I''m not going to follow you anywhere.'),
('string/en/npc_mission/static_noble_escort.stf', 85, 'otherescort', 'I think you''re here to pick up someone else.  You''re certainly not taking ME anywhere.'),
('string/en/npc_mission/static_noble_escort.stf', 86, 'escortother', 'I think you''re looking for someone else.'),
('string/en/npc_mission/static_noble_escort.stf', 88, 'npc_takeme_1', 'I hope you''re here to get me back to my friend.'),
('string/en/npc_mission/static_noble_escort.stf', 89, 'npc_takeme_2', 'Great!  Let''s go, I don''t want to miss that reception!'),
('string/en/npc_mission/static_noble_escort.stf', 90, 'npc_takeme_3', 'Somebody told you I was drunk?  Liars.  I don''t drink.  Now let''s get back before I get thirsty.'),
('string/en/npc_mission/static_noble_escort.stf', 91, 'npc_takeme_4', 'Thank you.  I thought I was going to be stuck out here all day.  Let''s get going.'),
('string/en/npc_mission/static_noble_fetch.stf', 1, 'gotowork', 'I need you to finish that task I gave you earlier.  Ok?'),
('string/en/npc_mission/static_noble_fetch.stf', 2, 'cantwork', 'I understand you''re already working for someone else.  Come back when you''re done with that job.'),
('string/en/npc_mission/static_noble_fetch.stf', 9, 'not_it', 'No, sorry, that''s not the item I was looking for...'),
('string/en/npc_mission/static_noble_fetch.stf', 34, 'npc_1_1', 'My family has had this heirloom glass for many years, and now it''s been stolen.  I can tell you where the thief is, but I need you to bring back my glass unharmed.  Can you do it?'),
('string/en/npc_mission/static_noble_fetch.stf', 35, 'npc_2_1', 'You''re a life saver.  I''ll give you this hand woven basket for the glass when you return.  My servants made it.'),
('string/en/npc_mission/static_noble_fetch.stf', 36, 'npc_3_1', 'I thought you were a mercenary?  Perhaps you''re just a librarian or some such...'),
('string/en/npc_mission/static_noble_fetch.stf', 37, 'player_1_1', 'Yeah, I can get it.  I''ll need some form of payment though.'),
('string/en/npc_mission/static_noble_fetch.stf', 38, 'player_2_1', 'Sounds ridiculous.  Why don''t you just go buy a new glass?'),
('string/en/npc_mission/static_noble_fetch.stf', 39, 'npc_reward_1', 'Careful with this thing.  It''s well put together, but if you crush it it won''t be worth as much.'),
