('string/en/npc_reaction/droid_geek.stf', 225, 'attacked_14', '"taunt.cpp" process failed. Abort, Retry, Fail?'),
('string/en/npc_reaction/droid_geek.stf', 226, 'attacked_16', 'FATAL:: cannot address pointer "target" in procedure "taunt.cpp."'),
('string/en/npc_reaction/droid_geek.stf', 227, 'help_1', 'Requesting assistance.'),
