('string/en/npc_reaction/droid_geek.stf', 244, 'ally_2', 'Warning: tactical error executed. Do not attack friendly entities.'),
('string/en/npc_reaction/droid_geek.stf', 245, 'ally_3', 'FATAL:: cannot execute module "warn_attackers_off.cpp" because of a stack overflow.'),
('string/en/npc_reaction/droid_geek.stf', 246, 'ally_4', 'Aggressive entity: desist or be terminated.'),
