('string/en/npc_reaction/droid_geek.stf', 249, 'ally_7', 'Engaging assistance mode.'),
('string/en/npc_reaction/droid_geek.stf', 250, 'ally_8', 'Attacked entity: are you in need of assistance?'),
('string/en/npc_reaction/droid_geek.stf', 251, 'ally_9', 'Attacked target: you appear in need of assistance.'),
('string/en/npc_reaction/droid_geek.stf', 252, 'ally_10', 'Combat subroutines now active.'),
