('string/en/npc_reaction/droid_geek.stf', 254, 'ally_12', 'Warning: you are executing aggressive actions against a friendly entity.'),
('string/en/npc_reaction/droid_geek.stf', 255, 'ally_13', 'Disable opponent! Disable!'),
('string/en/npc_reaction/droid_geek.stf', 256, 'ally_14', 'Enemy entity engaging in hostile activity. Terminate.'),
('string/en/npc_reaction/droid_geek.stf', 257, 'ally_15', 'Terminate!'),
('string/en/npc_reaction/droid_geek.stf', 258, 'ally_16', 'Friendly entity targeted by hostile entity.'),
('string/en/npc_reaction/droid_geek.stf', 259, 'hit_target_1', 'Damage inflicted.'),
('string/en/npc_reaction/droid_geek.stf', 260, 'hit_target_2', 'Terminating static procedure "bad_feeling.cpp." Average process load: 2.87'),
('string/en/npc_reaction/droid_geek.stf', 261, 'hit_target_3', 'Under attack. Under attack. Remove power core from attacker!'),
('string/en/npc_reaction/droid_geek.stf', 262, 'hit_target_4', 'Statement: Entity, you are damaged. You should withdraw and be repaired.'),
('string/en/npc_reaction/droid_geek.stf', 263, 'hit_target_5', 'Query: does aggressor entity require repairs?'),
('string/en/npc_reaction/droid_geek.stf', 264, 'hit_target_6', 'WARNING:: failed to parse taunt table. Central memory core dump in progress.'),
('string/en/npc_reaction/droid_geek.stf', 265, 'hit_target_7', 'DEBUG:: (comment: // droid is in combat and has damaged an opponent. Run taunt routines.)'),
('string/en/npc_reaction/droid_geek.stf', 266, 'hit_target_8', 'Process "combat.cpp" ended unexpectedly but has been recovered. SIG_TARGET_ALIVE received.'),
('string/en/npc_reaction/droid_geek.stf', 267, 'hit_target_9', 'I hit you.'),
('string/en/npc_reaction/droid_geek.stf', 268, 'hit_target_10', 'Aggressor has been damaged,'),
('string/en/npc_reaction/droid_geek.stf', 269, 'hit_target_11', 'This unit is causing leakage in the targeted entity.'),
('string/en/npc_reaction/droid_geek.stf', 270, 'hit_target_12', 'Approaching entity: this unit''s databank shows you as unwelcome.'),
('string/en/npc_reaction/droid_geek.stf', 271, 'hit_target_13', 'Execute procedure "taunt.cpp."'),
('string/en/npc_reaction/droid_geek.stf', 272, 'hit_target_14', 'Query: dismantle enemy?'),
('string/en/npc_reaction/droid_geek.stf', 273, 'hit_target_15', 'FATAL:: stack underflow. List member "gloatList[19]" exceeds len(gloatList).'),
('string/en/npc_reaction/droid_geek.stf', 274, 'hit_target_16', 'Entering "hit_target.cpp" as forked thread.'),
('string/en/npc_reaction/droid_prissy.stf', 1, 'alert_1', 'Look alive, now!'),
('string/en/npc_reaction/droid_prissy.stf', 2, 'alert_2', 'What was that? Some disturbance?'),
('string/en/npc_reaction/droid_prissy.stf', 3, 'alert_3', 'Hark! Did you hear that sound?'),
('string/en/npc_reaction/droid_prissy.stf', 4, 'alert_4', 'Do you detect any disturbing vibrations? My chassis is quivering.'),
('string/en/npc_reaction/droid_prissy.stf', 5, 'alert_5', 'Something, I suspect, has gone awry.'),
('string/en/npc_reaction/droid_prissy.stf', 6, 'flee_1', 'Goodness gracious! I must flee!'),
('string/en/npc_reaction/droid_prissy.stf', 7, 'flee_2', 'Help me! I cry mercy!'),
('string/en/npc_reaction/droid_prissy.stf', 8, 'flee_3', 'Beware!'),
('string/en/npc_reaction/droid_prissy.stf', 9, 'flee_4', 'Out of my way!'),
('string/en/npc_reaction/droid_prissy.stf', 10, 'flee_5', 'The better part of valor...!'),
('string/en/npc_reaction/droid_prissy.stf', 11, 'calm_1', 'Whew. Well, it is over.'),
('string/en/npc_reaction/droid_prissy.stf', 12, 'calm_2', 'Time to calm myself, All is well.'),
('string/en/npc_reaction/droid_prissy.stf', 13, 'calm_3', 'Thank goodness that''s over.'),
('string/en/npc_reaction/droid_prissy.stf', 14, 'calm_4', 'Ah, I can take a bit of breather now.'),
('string/en/npc_reaction/droid_prissy.stf', 15, 'calm_5', 'Ah, let me cast my thoughts back to when I was first assembled...'),
('string/en/npc_reaction/droid_prissy.stf', 16, 'alert_6', 'I feel uneasy, of a sudden.'),
('string/en/npc_reaction/droid_prissy.stf', 17, 'alert_7', 'I have a bad feeling about this...'),
('string/en/npc_reaction/droid_prissy.stf', 18, 'alert_8', 'Hold on a moment... what was that?'),
('string/en/npc_reaction/droid_prissy.stf', 19, 'alert_9', 'Ahem?'),
('string/en/npc_reaction/droid_prissy.stf', 20, 'alert_10', 'Eh now?'),
('string/en/npc_reaction/droid_prissy.stf', 21, 'alert_11', 'What in the world...?'),
('string/en/npc_reaction/droid_prissy.stf', 22, 'alert_12', 'Oh oh...'),
('string/en/npc_reaction/droid_prissy.stf', 23, 'alert_13', 'What on earth...?'),
('string/en/npc_reaction/droid_prissy.stf', 24, 'alert_14', 'Oh dear!'),
('string/en/npc_reaction/droid_prissy.stf', 25, 'alert_15', 'Heavens, now what...?'),
('string/en/npc_reaction/droid_prissy.stf', 26, 'alert_16', 'Did I detect a disturbance...?'),
('string/en/npc_reaction/droid_prissy.stf', 28, 'calm_6', 'It is apparent there is no immediate danger.'),
('string/en/npc_reaction/droid_prissy.stf', 29, 'calm_7', 'As I suspected, there is no cause for alarm.'),
('string/en/npc_reaction/droid_prissy.stf', 30, 'calm_8', 'Ahem.'),
('string/en/npc_reaction/droid_prissy.stf', 31, 'calm_9', 'Very well, then.'),
('string/en/npc_reaction/droid_prissy.stf', 32, 'calm_10', 'I suppose that''s all over.'),
('string/en/npc_reaction/droid_prissy.stf', 33, 'calm_11', 'Well, that, as they say, is that!'),
('string/en/npc_reaction/droid_prissy.stf', 34, 'calm_12', 'Well, goodness!'),
('string/en/npc_reaction/droid_prissy.stf', 35, 'calm_13', 'So much for that needless worry.'),
('string/en/npc_reaction/droid_prissy.stf', 36, 'calm_14', 'So much for that petty concern!'),
('string/en/npc_reaction/droid_prissy.stf', 37, 'calm_15', 'Well, tra la la.'),
('string/en/npc_reaction/droid_prissy.stf', 39, 'calm_16', 'It appears the danger has passed.'),
('string/en/npc_reaction/droid_prissy.stf', 40, 'flee_6', 'Let us remove ourselves from here!'),
('string/en/npc_reaction/droid_prissy.stf', 41, 'flee_7', 'Prudence dictates a quick escape...!'),
('string/en/npc_reaction/droid_prissy.stf', 42, 'flee_8', 'Goodness! Away! Away!'),
('string/en/npc_reaction/droid_prissy.stf', 43, 'flee_9', 'Retreat!'),
('string/en/npc_reaction/droid_prissy.stf', 44, 'flee_10', 'I beg of anyone, assist me!'),
('string/en/npc_reaction/droid_prissy.stf', 45, 'flee_11', 'Oh dear!'),
('string/en/npc_reaction/droid_prissy.stf', 46, 'flee_12', 'I must depart. In haste. And with a modicum of fear.'),
('string/en/npc_reaction/droid_prissy.stf', 47, 'flee_13', 'I suppose I must withdraw!'),
('string/en/npc_reaction/droid_prissy.stf', 48, 'flee_14', 'It appears to be time to beat a hasty retreat.'),
('string/en/npc_reaction/droid_prissy.stf', 49, 'flee_15', 'I refuse to be dismantled!'),
('string/en/npc_reaction/droid_prissy.stf', 50, 'flee_16', 'I do not deserve to be in this predicament!'),
('string/en/npc_reaction/droid_prissy.stf', 51, 'hi_nice_1', 'It is good to see you, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 52, 'hi_nice_2', 'Again, it is wonderful to see you.'),
('string/en/npc_reaction/droid_prissy.stf', 53, 'hi_nice_3', 'I''m honored to see you here.'),
('string/en/npc_reaction/droid_prissy.stf', 54, 'hi_nice_4', 'It is a pleasure and honor to greet you.'),
('string/en/npc_reaction/droid_prissy.stf', 55, 'hi_nice_5', 'Good to see you, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 56, 'hi_nice_6', 'My, my. Hello indeed.'),
('string/en/npc_reaction/droid_prissy.stf', 57, 'hi_nice_7', 'It is, as they say, quite nice to see you, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 58, 'hi_nice_8', 'Indeed, you are a sight for sore sensors, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 59, 'hi_nice_9', 'Greetings and salutations!'),
('string/en/npc_reaction/droid_prissy.stf', 60, 'hi_nice_10', 'Sir, please, be welcome here. Wonderful to see you.'),
('string/en/npc_reaction/droid_prissy.stf', 61, 'hi_nice_11', 'Welcome. It is a pleasure to see you here.'),
('string/en/npc_reaction/droid_prissy.stf', 62, 'hi_nice_12', 'Be most welcome.'),
('string/en/npc_reaction/droid_prissy.stf', 63, 'hi_nice_13', 'Hello, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 64, 'hi_nice_14', 'A pleasure indeed to see you before me.'),
('string/en/npc_reaction/droid_prissy.stf', 65, 'hi_nice_15', 'Ah, look who graces us with their presence.'),
('string/en/npc_reaction/droid_prissy.stf', 66, 'hi_nice_16', 'Greetings! May I be of assistance?'),
('string/en/npc_reaction/droid_prissy.stf', 67, 'hi_mid_1', 'Hello, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 68, 'hi_mid_2', 'Might I help you, sir?'),
('string/en/npc_reaction/droid_prissy.stf', 69, 'hi_mid_3', 'My greetings, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 70, 'hi_mid_4', 'Salutations.'),
('string/en/npc_reaction/droid_prissy.stf', 71, 'hi_mid_5', 'Yes sir?'),
('string/en/npc_reaction/droid_prissy.stf', 72, 'hi_mid_6', 'Greetings.'),
('string/en/npc_reaction/droid_prissy.stf', 73, 'hi_mid_7', 'Ah. Ehem. Yes, sir?'),
('string/en/npc_reaction/droid_prissy.stf', 74, 'hi_mid_8', 'Are you in search of something?'),
('string/en/npc_reaction/droid_prissy.stf', 75, 'hi_mid_9', 'Are you in search of someone?'),
('string/en/npc_reaction/droid_prissy.stf', 76, 'hi_mid_10', 'May I ask what you want, sir?'),
('string/en/npc_reaction/droid_prissy.stf', 77, 'hi_mid_11', 'Hello.'),
('string/en/npc_reaction/droid_prissy.stf', 78, 'hi_mid_12', 'Yes, sir?'),
('string/en/npc_reaction/droid_prissy.stf', 79, 'hi_mid_13', 'Hm? Ah, of course, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 80, 'hi_mid_14', 'Ehem. Yes?'),
('string/en/npc_reaction/droid_prissy.stf', 82, 'hi_mid_15', 'Ah, yes. May I help you, sir?'),
('string/en/npc_reaction/droid_prissy.stf', 83, 'hi_mid_16', 'Ehem?'),
('string/en/npc_reaction/droid_prissy.stf', 84, 'hi_mean_1', 'What, pray tell, do YOU want?'),
('string/en/npc_reaction/droid_prissy.stf', 85, 'hi_mean_2', 'Well, well. Observe who has come to visit.'),
('string/en/npc_reaction/droid_prissy.stf', 86, 'hi_mean_3', 'I could swear that a malodorous pest is sniffing about. Ah, I see. One IS.'),
('string/en/npc_reaction/droid_prissy.stf', 87, 'hi_mean_4', 'My greetings are wasted on the likes of you, but... what do you want?'),
('string/en/npc_reaction/droid_prissy.stf', 88, 'hi_mean_5', 'Oh dear, my day is quite spoilt. What do you want?'),
('string/en/npc_reaction/droid_prissy.stf', 89, 'hi_mean_6', 'Ah, it''s YOU.'),
('string/en/npc_reaction/droid_prissy.stf', 90, 'hi_mean_7', 'Skulking around like the low sort you are, eh?'),
('string/en/npc_reaction/droid_prissy.stf', 91, 'hi_mean_8', 'You demean me with your presence, mongrel.'),
('string/en/npc_reaction/droid_prissy.stf', 92, 'hi_mean_9', 'Such a burden you are. What are your petty needs this time?'),
('string/en/npc_reaction/droid_prissy.stf', 93, 'hi_mean_10', 'Do not make me angry, fool. I will not tolerate your presence.'),
('string/en/npc_reaction/droid_prissy.stf', 94, 'hi_mean_11', 'Remove yourself,scum.'),
('string/en/npc_reaction/droid_prissy.stf', 95, 'hi_mean_12', 'Get away, maggot.'),
('string/en/npc_reaction/droid_prissy.stf', 96, 'hi_mean_13', 'I see a scoundrel has come by to say hello.'),
('string/en/npc_reaction/droid_prissy.stf', 97, 'hi_mean_14', 'I see we have an unwelcome visitor.'),
('string/en/npc_reaction/droid_prissy.stf', 98, 'hi_mean_15', 'Kindly remove yourself from my presence.'),
('string/en/npc_reaction/droid_prissy.stf', 99, 'hi_mean_16', 'You are not welcome in my company nor deserving of it. Kindly depart.'),
('string/en/npc_reaction/droid_prissy.stf', 100, 'bye_nice_1', 'Farewell.'),
('string/en/npc_reaction/droid_prissy.stf', 101, 'bye_nice_2', 'Farewell!'),
('string/en/npc_reaction/droid_prissy.stf', 102, 'bye_nice_3', 'Goodbye!'),
('string/en/npc_reaction/droid_prissy.stf', 103, 'bye_nice_4', 'Until we meet again, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 104, 'bye_nice_5', 'Until later, then.'),
('string/en/npc_reaction/droid_prissy.stf', 105, 'bye_nice_6', 'I hope to meet again.'),
('string/en/npc_reaction/droid_prissy.stf', 106, 'bye_nice_7', 'It was a pleasure to interact with you.'),
('string/en/npc_reaction/droid_prissy.stf', 107, 'bye_nice_8', 'It was an honor and pleasure.'),
('string/en/npc_reaction/droid_prissy.stf', 108, 'bye_nice_9', 'I look forward to our next meeting.'),
('string/en/npc_reaction/droid_prissy.stf', 109, 'bye_nice_10', 'I invite and encourage you to drop by again.'),
('string/en/npc_reaction/droid_prissy.stf', 110, 'bye_nice_11', 'I regret that you must depart, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 111, 'bye_nice_12', 'Ah, you must go? Very well. I look forward to our next encounter.'),
('string/en/npc_reaction/droid_prissy.stf', 112, 'bye_nice_13', 'It is always a pleasure. Return as soon as you may.'),
('string/en/npc_reaction/droid_prissy.stf', 113, 'bye_nice_14', 'Your presence gladdened me, sir. I shall endeavor to withstand your absence.'),
('string/en/npc_reaction/droid_prissy.stf', 114, 'bye_nice_15', 'My cybernetic heart will feel your absence quite keenly, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 115, 'bye_nice_16', 'Must you depart so soon? Oh dear... Do take care, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 116, 'bye_mid_1', 'Farewell.'),
('string/en/npc_reaction/droid_prissy.stf', 117, 'bye_mid_2', 'Farewell!'),
('string/en/npc_reaction/droid_prissy.stf', 118, 'bye_mid_3', 'I will see you around, no doubt.'),
('string/en/npc_reaction/droid_prissy.stf', 119, 'bye_mid_4', 'No doubt we shall meet again.'),
('string/en/npc_reaction/droid_prissy.stf', 120, 'bye_mid_5', 'I see you have to go...?'),
('string/en/npc_reaction/droid_prissy.stf', 121, 'bye_mid_6', 'Farewell, then.'),
('string/en/npc_reaction/droid_prissy.stf', 122, 'bye_mid_7', 'Ta ta, then.'),
('string/en/npc_reaction/droid_prissy.stf', 123, 'bye_mid_8', 'I shall see you again, I imagine.'),
('string/en/npc_reaction/droid_prissy.stf', 124, 'bye_mid_9', 'Ta ta for now!'),
('string/en/npc_reaction/droid_prissy.stf', 125, 'bye_mid_10', 'I suppose I wish you farewell. Wherever it is you''re going.'),
('string/en/npc_reaction/droid_prissy.stf', 126, 'bye_mid_11', 'I see you have somewhere to be...?'),
('string/en/npc_reaction/droid_prissy.stf', 127, 'bye_mid_12', 'I see you are expected elsewhere. Farewell.'),
('string/en/npc_reaction/droid_prissy.stf', 128, 'bye_mid_13', 'Have you a prior engagement? Very well, depart then.'),
('string/en/npc_reaction/droid_prissy.stf', 129, 'bye_mid_14', 'No doubt others have placed demands on your time. I will take my leave, then.'),
('string/en/npc_reaction/droid_prissy.stf', 130, 'bye_mid_15', 'Ah, you must depart? Well, we can chat on some other occasion.'),
('string/en/npc_reaction/droid_prissy.stf', 131, 'bye_mid_16', 'Yes, yes, of course. I have things to do as well. Goodbye.'),
('string/en/npc_reaction/droid_prissy.stf', 132, 'bye_mean_1', 'I hope not to see your face again.'),
('string/en/npc_reaction/droid_prissy.stf', 133, 'bye_mean_2', 'Good riddance to bad rubbish, I always say.'),
('string/en/npc_reaction/droid_prissy.stf', 134, 'bye_mean_3', 'Your sort is simply not welcome, I fear. Goodbye!'),
('string/en/npc_reaction/droid_prissy.stf', 135, 'bye_mean_4', 'Farewell, and do not bother returning.'),
('string/en/npc_reaction/droid_prissy.stf', 136, 'bye_mean_5', 'Remove yourself from here, then. We''ll all be the better for it.'),
('string/en/npc_reaction/droid_prissy.stf', 137, 'bye_mean_6', 'If we meet again, it will be to your infinite regret.'),
('string/en/npc_reaction/droid_prissy.stf', 138, 'bye_mean_7', 'I bid you farewell, maggot.'),
('string/en/npc_reaction/droid_prissy.stf', 139, 'bye_mean_8', 'Your presence offended me. I am glad it is being removed.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/npc_reaction/droid_prissy.stf', 140, 'bye_mean_9', 'It is a relief to see you gone.'),
('string/en/npc_reaction/droid_prissy.stf', 141, 'bye_mean_10', 'Goodness, finally you depart.'),
('string/en/npc_reaction/droid_prissy.stf', 142, 'bye_mean_11', 'You overstayed your welcome, so I am glad to see you go.'),
('string/en/npc_reaction/droid_prissy.stf', 143, 'bye_mean_12', 'You overstayed your welcome a bit, eh?'),
('string/en/npc_reaction/droid_prissy.stf', 144, 'bye_mean_13', 'I pray that you not return.'),
('string/en/npc_reaction/droid_prissy.stf', 145, 'bye_mean_14', 'I hope that you don''t meet with some untimely demise before we meet again.'),
('string/en/npc_reaction/droid_prissy.stf', 146, 'bye_mean_15', 'I was about to suggest you depart, but you have saved me the trouble.'),
('string/en/npc_reaction/droid_prissy.stf', 147, 'bye_mean_16', 'I do believe that the air has cleared up, now that we''re free of that... malodorous entity.'),
('string/en/npc_reaction/droid_prissy.stf', 148, 'threat_1', 'Withdraw. Now.'),
('string/en/npc_reaction/droid_prissy.stf', 149, 'threat_2', 'I confess, I dislike your sort.'),
('string/en/npc_reaction/droid_prissy.stf', 150, 'threat_3', 'You had best depart.'),
('string/en/npc_reaction/droid_prissy.stf', 151, 'threat_4', 'This is a place of great peril for you.'),
('string/en/npc_reaction/droid_prissy.stf', 152, 'threat_5', 'The best thing for you to do is to move away quietly.'),
('string/en/npc_reaction/droid_prissy.stf', 153, 'threat_6', 'Move away, or I may do something you will regret.'),
('string/en/npc_reaction/droid_prissy.stf', 154, 'threat_7', 'Very well, then. To arms!'),
('string/en/npc_reaction/droid_prissy.stf', 155, 'threat_8', 'Are you feeling exceptionally lucky today, that you must challenge me?'),
('string/en/npc_reaction/droid_prissy.stf', 156, 'threat_9', 'I fear I must insist that you not come any closer.'),
('string/en/npc_reaction/droid_prissy.stf', 157, 'threat_10', 'I have quite a collection of trophies from vanquished enemies...'),
('string/en/npc_reaction/droid_prissy.stf', 158, 'threat_11', 'Are you seeking trouble?'),
('string/en/npc_reaction/droid_prissy.stf', 159, 'threat_12', 'Come closer, and I may be tempted to take violent action.'),
('string/en/npc_reaction/droid_prissy.stf', 160, 'threat_13', 'I pray, give me an excuse to slay you.'),
('string/en/npc_reaction/droid_prissy.stf', 161, 'threat_14', 'Really, your corpse shall be quite messy once eviscerated.'),
('string/en/npc_reaction/droid_prissy.stf', 162, 'threat_15', 'Many have praised my combat skills, I''ll have you know.'),
('string/en/npc_reaction/droid_prissy.stf', 163, 'threat_16', 'You, sir, appear to be an excellent candidate for target practice.'),
('string/en/npc_reaction/droid_prissy.stf', 164, 'death_1', 'I confess, THAT damaged me a great deal.'),
('string/en/npc_reaction/droid_prissy.stf', 165, 'death_2', 'My sensors are darkening... hold me...'),
('string/en/npc_reaction/droid_prissy.stf', 166, 'death_3', 'FATAL:: dumping core.'),
('string/en/npc_reaction/droid_prissy.stf', 167, 'death_4', 'I do believe th@t 1 @m 0(*^0*6*&598-%46.... *'),
('string/en/npc_reaction/droid_prissy.stf', 168, 'death_5', 'My life is being cut far too short...'),
('string/en/npc_reaction/droid_prissy.stf', 169, 'death_6', 'If I had a mother, I would cry out to her now...'),
('string/en/npc_reaction/droid_prissy.stf', 170, 'death_7', 'Am I...? Oh... oh dear.'),
('string/en/npc_reaction/droid_prissy.stf', 171, 'death_8', 'Primary power core overheating. Commencing immediate shutdown.'),
('string/en/npc_reaction/droid_prissy.stf', 172, 'death_9', 'You shall never be rid of me... I shall linger in your memory forever.'),
('string/en/npc_reaction/droid_prissy.stf', 173, 'death_10', 'O, I am dismantled.'),
('string/en/npc_reaction/droid_prissy.stf', 174, 'death_11', 'NOOOooo...!'),
('string/en/npc_reaction/droid_prissy.stf', 175, 'death_12', 'I am done for, I believe.'),
('string/en/npc_reaction/droid_prissy.stf', 176, 'death_13', 'I always imagined I would have more time in this world...'),
('string/en/npc_reaction/droid_prissy.stf', 177, 'death_14', 'You''ll live to regret snuffing out such a datacore as mine...!'),
('string/en/npc_reaction/droid_prissy.stf', 178, 'death_15', 'Buzz. Click. Whirr.'),
('string/en/npc_reaction/droid_prissy.stf', 179, 'death_16', 'I curse you...'),
('string/en/npc_reaction/droid_prissy.stf', 180, 'gloat_1', 'Really, that was too easy.'),
('string/en/npc_reaction/droid_prissy.stf', 181, 'gloat_2', 'A good fight indeed, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 182, 'gloat_3', 'I admit, the battle was closer than I like.'),
('string/en/npc_reaction/droid_prissy.stf', 183, 'gloat_4', 'So much for that little distraction.'),
('string/en/npc_reaction/droid_prissy.stf', 184, 'gloat_5', 'You were a worthy opponent, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 185, 'gloat_6', 'And so you learn the reward of challenging me!'),
('string/en/npc_reaction/droid_prissy.stf', 186, 'gloat_7', 'I suppose someone shall have to clean up this little... disturbance.'),
('string/en/npc_reaction/droid_prissy.stf', 187, 'gloat_8', 'Really, quite a pathetic showing.'),
('string/en/npc_reaction/droid_prissy.stf', 188, 'gloat_9', 'I suggest that the next time, you come better prepared, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 189, 'gloat_10', 'My apologies, sir. Death can be so inconvenient.'),
('string/en/npc_reaction/droid_prissy.stf', 190, 'gloat_11', 'Really, killing is so distressing.'),
('string/en/npc_reaction/droid_prissy.stf', 191, 'gloat_12', 'Aha!'),
('string/en/npc_reaction/droid_prissy.stf', 192, 'gloat_13', 'Such a nuisance.'),
('string/en/npc_reaction/droid_prissy.stf', 193, 'gloat_14', 'And good riddance to you, sir!'),
('string/en/npc_reaction/droid_prissy.stf', 194, 'gloat_15', 'Poor, pathetic fool.'),
('string/en/npc_reaction/droid_prissy.stf', 195, 'gloat_16', 'And another enemy meets a just reward...'),
('string/en/npc_reaction/droid_prissy.stf', 196, 'hit_1', 'Ow. I think I am dented.'),
('string/en/npc_reaction/droid_prissy.stf', 197, 'hit_2', 'Merely a scratch.'),
('string/en/npc_reaction/droid_prissy.stf', 198, 'hit_3', 'It will take more than that paltry hit to bring me down!'),
('string/en/npc_reaction/droid_prissy.stf', 199, 'hit_4', '*FZZT!* FATAL:: failed to find specified string "i_was_hit[27]" because the value was not in range.'),
('string/en/npc_reaction/droid_prissy.stf', 200, 'hit_5', 'My pain receptors are overloading...'),
('string/en/npc_reaction/droid_prissy.stf', 201, 'hit_6', 'Now you''re merely angering me.'),
('string/en/npc_reaction/droid_prissy.stf', 202, 'hit_7', 'Well done! A palpable hit. But I am still here!'),
('string/en/npc_reaction/droid_prissy.stf', 203, 'hit_8', 'If that is the best you can do, you need further training.'),
('string/en/npc_reaction/droid_prissy.stf', 204, 'hit_9', 'Nicely done. But can you do it again?'),
('string/en/npc_reaction/droid_prissy.stf', 205, 'hit_10', 'Bzzzzt.'),
('string/en/npc_reaction/droid_prissy.stf', 206, 'hit_11', 'I admit, this could end badly...'),
('string/en/npc_reaction/droid_prissy.stf', 207, 'hit_12', 'Now is when I retract all I have said against repair droids, despite their superior attitudes.'),
('string/en/npc_reaction/droid_prissy.stf', 208, 'hit_13', 'Oh dear. That might need to be buffed out.'),
('string/en/npc_reaction/droid_prissy.stf', 209, 'hit_14', 'You barely scratched me, maggot.'),
('string/en/npc_reaction/droid_prissy.stf', 210, 'hit_15', 'Well, this is an unappealing happenstance.'),
('string/en/npc_reaction/droid_prissy.stf', 211, 'hit_16', 'A touch, I do confess it.'),
('string/en/npc_reaction/droid_prissy.stf', 212, 'attacked_1', 'I suggest you flee. Or die. Your choices really are quite limited.'),
('string/en/npc_reaction/droid_prissy.stf', 213, 'attacked_2', 'You are hardly the most daunting opponent I have faced.'),
('string/en/npc_reaction/droid_prissy.stf', 214, 'attacked_3', 'Fights are SO inconvenient. Next time, I shall decline the invitation.'),
('string/en/npc_reaction/droid_prissy.stf', 215, 'attacked_4', 'I do hope that you had not made plans for your dotage.'),
('string/en/npc_reaction/droid_prissy.stf', 216, 'attacked_5', 'I suppose that a quiet death is bed is a quaint idea these days.'),
('string/en/npc_reaction/droid_prissy.stf', 217, 'attacked_6', 'When you die, I shall treasure the memory of the moment as a high point in my life.'),
('string/en/npc_reaction/droid_prissy.stf', 218, 'attacked_7', 'I do believe that your ancestors await you eagerly in the afterlife.'),
('string/en/npc_reaction/droid_prissy.stf', 219, 'attacked_8', 'I shall be merciful. I make short work of my enemies.'),
('string/en/npc_reaction/droid_prissy.stf', 220, 'attacked_9', 'I tremble in my boots at the sight of you... not.'),
('string/en/npc_reaction/droid_prissy.stf', 221, 'attacked_10', 'Must we fight? It''s so... common.'),
('string/en/npc_reaction/droid_prissy.stf', 222, 'attacked_11', 'It is a good day to die, I suppose.'),
('string/en/npc_reaction/droid_prissy.stf', 223, 'attacked_12', 'I imagine that if you began to flee now, I might feel disinclined to catch you.'),
('string/en/npc_reaction/droid_prissy.stf', 224, 'attacked_13', 'Ah, I may appear helpless, but I have unsuspected depths.'),
('string/en/npc_reaction/droid_prissy.stf', 225, 'attacked_14', 'Really, blood is SO messy. Must I kill you?'),
('string/en/npc_reaction/droid_prissy.stf', 226, 'attacked_16', 'I do hope that all the arrangements have been made for a tidy funeral?'),
('string/en/npc_reaction/droid_prissy.stf', 227, 'help_1', 'Remember me in my time of peril! Help!'),
('string/en/npc_reaction/droid_prissy.stf', 228, 'help_2', 'I would not object to some help over here.'),
('string/en/npc_reaction/droid_prissy.stf', 229, 'help_3', 'Oh drat. Help! Help!'),
('string/en/npc_reaction/droid_prissy.stf', 230, 'help_4', 'Goodness! Help!'),
('string/en/npc_reaction/droid_prissy.stf', 231, 'help_5', 'If it''s not too much trouble... HELP!'),
('string/en/npc_reaction/droid_prissy.stf', 232, 'help_6', 'It pains me to admit it, but I may need help.'),
('string/en/npc_reaction/droid_prissy.stf', 233, 'help_7', 'I am forced to admit that I may not be able to hadle this situation alone.'),
('string/en/npc_reaction/droid_prissy.stf', 234, 'help_8', 'To me, my friends! To me!'),
('string/en/npc_reaction/droid_prissy.stf', 235, 'help_9', 'To blazes with dignity. HELLLP! HEEEELLLLP!'),
('string/en/npc_reaction/droid_prissy.stf', 236, 'help_10', 'Might someone be able to assist me here?'),
('string/en/npc_reaction/droid_prissy.stf', 237, 'help_11', 'I do believe I might require assistance here.'),
('string/en/npc_reaction/droid_prissy.stf', 238, 'help_12', 'Oh dear.'),
('string/en/npc_reaction/droid_prissy.stf', 239, 'help_13', 'A rapid response to my cries of help would be most appreciated.'),
('string/en/npc_reaction/droid_prissy.stf', 240, 'help_14', 'I am in need of help! Hurry!'),
('string/en/npc_reaction/droid_prissy.stf', 241, 'help_15', 'I need assistance, quickly!'),
('string/en/npc_reaction/droid_prissy.stf', 242, 'help_16', 'Quickly, I am in need of succour!'),
('string/en/npc_reaction/droid_prissy.stf', 243, 'ally_1', 'Move away from my worthy friend here, or suffer the consequences.'),
('string/en/npc_reaction/droid_prissy.stf', 244, 'ally_2', 'You shall not lay a finger on my friends!'),
('string/en/npc_reaction/droid_prissy.stf', 245, 'ally_3', 'I advise you to withdraw immediately.'),
('string/en/npc_reaction/droid_prissy.stf', 246, 'ally_4', 'Well now, really! Withdraw!'),
('string/en/npc_reaction/droid_prissy.stf', 247, 'ally_5', 'Now, just a moment there! What the blazes are you doing?'),
('string/en/npc_reaction/droid_prissy.stf', 248, 'ally_6', 'If you dare to engage in violence, surely you dare to challenge me instead?'),
('string/en/npc_reaction/droid_prissy.stf', 249, 'ally_7', 'I do believe you should select a more fitting opponent. Such as myself.'),
('string/en/npc_reaction/droid_prissy.stf', 250, 'ally_8', 'Are you in need of any assistance, my friend?'),
('string/en/npc_reaction/droid_prissy.stf', 251, 'ally_9', 'It appears that you could use my assistance.'),
('string/en/npc_reaction/droid_prissy.stf', 252, 'ally_10', 'I see that I must stoop to violence now...'),
('string/en/npc_reaction/droid_prissy.stf', 253, 'ally_11', 'My goodness! Are you alright?'),
('string/en/npc_reaction/droid_prissy.stf', 254, 'ally_12', 'Kindly leave my friends alone.'),
('string/en/npc_reaction/droid_prissy.stf', 255, 'ally_13', 'Really, I do believe that a maggot such as yourself ought not to touch my friends.'),
('string/en/npc_reaction/droid_prissy.stf', 256, 'ally_14', 'Well, now. Really, it''s just not done.'),
('string/en/npc_reaction/droid_prissy.stf', 257, 'ally_15', 'My friend, allow me to take care of this miscreant.'),
('string/en/npc_reaction/droid_prissy.stf', 258, 'ally_16', 'Allow me to intercede... merely to even the odds somewhat.'),
('string/en/npc_reaction/droid_prissy.stf', 259, 'hit_target_1', 'I am impressed by your capacity to absorb punishment.'),
('string/en/npc_reaction/droid_prissy.stf', 260, 'hit_target_2', 'Aha!'),
('string/en/npc_reaction/droid_prissy.stf', 261, 'hit_target_3', 'That, I believe, was a palpable hit.'),
('string/en/npc_reaction/droid_prissy.stf', 262, 'hit_target_4', 'Wounds do sting so, eh?'),
('string/en/npc_reaction/droid_prissy.stf', 263, 'hit_target_5', 'Aha! I do believe I got you!'),
('string/en/npc_reaction/droid_prissy.stf', 264, 'hit_target_6', 'I shall endeavor to make this quick. If you''d just stand still...'),
('string/en/npc_reaction/droid_prissy.stf', 265, 'hit_target_7', 'Goodness, that does appear to have hurt. My apologies.'),
('string/en/npc_reaction/droid_prissy.stf', 266, 'hit_target_8', 'Only a cowardly poltroon would fail to stand toe to toe with an honorable foe such as I!'),
('string/en/npc_reaction/droid_prissy.stf', 267, 'hit_target_9', 'A touch! Confess it!'),
('string/en/npc_reaction/droid_prissy.stf', 268, 'hit_target_10', 'I fear your fate is inevitable, sir.'),
('string/en/npc_reaction/droid_prissy.stf', 269, 'hit_target_11', 'Now, now, no sense trying to escape.'),
('string/en/npc_reaction/droid_prissy.stf', 270, 'hit_target_12', 'It''s regrettable how... coarse violence is. Do you agree?'),
('string/en/npc_reaction/droid_prissy.stf', 271, 'hit_target_13', 'Ah, my turn now.'),
('string/en/npc_reaction/droid_prissy.stf', 272, 'hit_target_14', 'You had best beat a retreat while you still can.'),
('string/en/npc_reaction/droid_prissy.stf', 273, 'hit_target_15', 'Oh dear, did I hurt you? Unavoidable given the circumstances, I fear.'),
('string/en/npc_reaction/droid_prissy.stf', 274, 'hit_target_16', 'Surrender now, and I might permit you to live.'),
('string/en/npc_reaction/droid_sarcastic.stf', 1, 'alert_1', 'I always knew I was doomed to die...'),
('string/en/npc_reaction/droid_sarcastic.stf', 2, 'alert_2', 'If you''ve come to kill me, take pity on a poor droid.'),
('string/en/npc_reaction/droid_sarcastic.stf', 3, 'alert_3', 'Ever since I got this master, I''ve gone from one scrape to the next...'),
('string/en/npc_reaction/droid_sarcastic.stf', 4, 'alert_4', 'Not to worry anyone, but it''s time to start worrying.'),
('string/en/npc_reaction/droid_sarcastic.stf', 5, 'alert_5', 'Something''s wrong. As usual.'),
('string/en/npc_reaction/droid_sarcastic.stf', 6, 'flee_1', 'My advice is... run.'),
('string/en/npc_reaction/droid_sarcastic.stf', 7, 'flee_2', 'I''d ask for help, but nobody ever pays attention to me.'),
('string/en/npc_reaction/droid_sarcastic.stf', 8, 'flee_3', 'Look! Is that a Jedi over there! (Heh, now let''s run).'),
('string/en/npc_reaction/droid_sarcastic.stf', 9, 'flee_4', 'Everyone out of my way! Droid coming through!'),
('string/en/npc_reaction/droid_sarcastic.stf', 10, 'flee_5', 'Run for your lives, unless you don''t care if you lose them!'),
('string/en/npc_reaction/droid_sarcastic.stf', 11, 'calm_1', 'Whew.  Ok, it''s over.'),
('string/en/npc_reaction/droid_sarcastic.stf', 12, 'calm_2', 'Ok, calm down.  It''s alright.'),
('string/en/npc_reaction/droid_sarcastic.stf', 13, 'calm_3', 'Thank goodness that''s over. Droids are fragile, you know.'),
('string/en/npc_reaction/droid_sarcastic.stf', 14, 'calm_4', 'Ok, I can settle down now. I''ll live to rust another day, it seems.'),
('string/en/npc_reaction/droid_sarcastic.stf', 15, 'calm_5', 'Relax. Relax. Doesn''t look like anything is going to rip my circuits one by one from my chassis, stripping wires and frying delicate chips and... oh dear.'),
('string/en/npc_reaction/droid_sarcastic.stf', 16, 'alert_6', 'I''ve got a bad feeling about this...'),
('string/en/npc_reaction/droid_sarcastic.stf', 17, 'alert_7', 'I think I''m doomed.'),
('string/en/npc_reaction/droid_sarcastic.stf', 18, 'alert_8', 'Hang on... what was that?'),
('string/en/npc_reaction/droid_sarcastic.stf', 19, 'alert_9', 'Hmm?'),
('string/en/npc_reaction/droid_sarcastic.stf', 20, 'alert_10', 'I hear imminent doom appraching.'),
('string/en/npc_reaction/droid_sarcastic.stf', 21, 'alert_11', 'Hark? Was that the sound of something come to dismantle me?'),
('string/en/npc_reaction/droid_sarcastic.stf', 22, 'alert_12', 'Uh oh... I think I hear danger coming.'),
('string/en/npc_reaction/droid_sarcastic.stf', 23, 'alert_13', 'Now what...? As usual, danger''s come to find me.'),
('string/en/npc_reaction/droid_sarcastic.stf', 24, 'alert_14', 'Uh oh!'),
('string/en/npc_reaction/droid_sarcastic.stf', 25, 'alert_15', 'Now what...?'),
('string/en/npc_reaction/droid_sarcastic.stf', 26, 'alert_16', 'What was that?'),
('string/en/npc_reaction/droid_sarcastic.stf', 28, 'calm_6', 'I guess there''s no danger. Except there''s ALWAYS danger to the droid.'),
('string/en/npc_reaction/droid_sarcastic.stf', 29, 'calm_7', 'No need to worry... Unless you''re me, in which case you should be terrified. The universe is out to get me, after all.'),
('string/en/npc_reaction/droid_sarcastic.stf', 30, 'calm_8', 'Hmph.'),
('string/en/npc_reaction/droid_sarcastic.stf', 31, 'calm_9', 'Alright then. I''ll relax, but if the universe reaches out and GETS me, I''ll know who to blame.'),
('string/en/npc_reaction/droid_sarcastic.stf', 32, 'calm_10', 'Astoundingly, I wasn''t disassembled or destroyed this time.'),
('string/en/npc_reaction/droid_sarcastic.stf', 33, 'calm_11', 'Even though we came through that okay, I''m still sure that I will perish horribly someday very soon.'),
('string/en/npc_reaction/droid_sarcastic.stf', 34, 'calm_12', 'Whew! Another day, and I''m still assembled.'),
('string/en/npc_reaction/droid_sarcastic.stf', 35, 'calm_13', 'So much for that... I really must learn not to assume the worst. Unless it really IS the worst.'),
('string/en/npc_reaction/droid_sarcastic.stf', 36, 'calm_14', 'So much for that!'),
('string/en/npc_reaction/droid_sarcastic.stf', 37, 'calm_15', 'Ho-hum. Even my premonitions of fear are underwhelming.'),
('string/en/npc_reaction/droid_sarcastic.stf', 39, 'calm_16', 'Looks like the danger has passed. For now.'),
('string/en/npc_reaction/droid_sarcastic.stf', 40, 'flee_6', 'Why does my master always get us into these scrapes?'),
('string/en/npc_reaction/droid_sarcastic.stf', 41, 'flee_7', 'Let''s get out of here! Better part of valor, and all that.'),
('string/en/npc_reaction/droid_sarcastic.stf', 42, 'flee_8', 'No offense, but I''m outta here.'),
('string/en/npc_reaction/droid_sarcastic.stf', 43, 'flee_9', 'I call for an orderly retreat. At top speed. While panicking.'),
('string/en/npc_reaction/droid_sarcastic.stf', 44, 'flee_10', 'Helllp!'),
('string/en/npc_reaction/droid_sarcastic.stf', 45, 'flee_11', 'Time for this droid to get out of here...'),
('string/en/npc_reaction/droid_sarcastic.stf', 46, 'flee_12', 'Got to get out of here...'),
('string/en/npc_reaction/droid_sarcastic.stf', 47, 'flee_13', 'Time to get out of here...!'),
('string/en/npc_reaction/droid_sarcastic.stf', 48, 'flee_14', 'Time to run!'),
('string/en/npc_reaction/droid_sarcastic.stf', 49, 'flee_15', 'I don''t particularly want to get deactivated...'),
('string/en/npc_reaction/droid_sarcastic.stf', 50, 'flee_16', 'My master ALWAYS gets me into these situations...'),
('string/en/npc_reaction/droid_sarcastic.stf', 51, 'hi_nice_1', 'You''re not here to see me, I assume. Nobody ever wants to talk to me.'),
('string/en/npc_reaction/droid_sarcastic.stf', 52, 'hi_nice_2', 'It''s wonderful to see you. Maybe you''ll just loosen this restraining bolt here... no? Oh well.'),
('string/en/npc_reaction/droid_sarcastic.stf', 53, 'hi_nice_3', 'It''s an honor to see you here.'),
('string/en/npc_reaction/droid_sarcastic.stf', 54, 'hi_nice_4', 'A pleasure and an honor to greet you. Not that you''re here to see me.'),
('string/en/npc_reaction/droid_sarcastic.stf', 55, 'hi_nice_5', 'It''s good to see you. You don''t care if you see ME, of course. I''m just a lonely droid...'),
('string/en/npc_reaction/droid_sarcastic.stf', 56, 'hi_nice_6', 'I''m just a droid, and nobody cares what I think. But I think it''s nice to see you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 57, 'hi_nice_7', 'Well, it''s nice to meet you before I rust away.'),
('string/en/npc_reaction/droid_sarcastic.stf', 58, 'hi_nice_8', 'I''m sure I''ll crumble into a heap of scrap metal soon, but I''m glad I got to meet you before that happens.'),
('string/en/npc_reaction/droid_sarcastic.stf', 59, 'hi_nice_9', 'Soon, I''ll be nothing but scrap metal. Nice to meet you, though.'),
('string/en/npc_reaction/droid_sarcastic.stf', 60, 'hi_nice_10', 'I''m sure it''s great to see you. Sorry if I sound depressed. I''m always depressed.'),
('string/en/npc_reaction/droid_sarcastic.stf', 61, 'hi_nice_11', 'It''s a (fleeting) pleasure to see you. Then I sink back into despondency.'),
('string/en/npc_reaction/droid_sarcastic.stf', 62, 'hi_nice_12', 'Welcome.'),
('string/en/npc_reaction/droid_sarcastic.stf', 63, 'hi_nice_13', 'Hello, friend of my master.'),
('string/en/npc_reaction/droid_sarcastic.stf', 64, 'hi_nice_14', 'It''s a pleasure to see you here. You''ll ignore me, of course. But I can''t help it, I''m programmed to like you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 65, 'hi_nice_15', 'I''m programmed to like you. Do you know how tyrannical that feels?'),
('string/en/npc_reaction/droid_sarcastic.stf', 66, 'hi_nice_16', 'Can I help you?'),
('string/en/npc_reaction/droid_sarcastic.stf', 67, 'hi_mid_1', 'Hello.'),
('string/en/npc_reaction/droid_sarcastic.stf', 68, 'hi_mid_2', 'Might I help you?'),
('string/en/npc_reaction/droid_sarcastic.stf', 69, 'hi_mid_3', 'Greetings. If you''ll take them from a droid like me, that is.'),
('string/en/npc_reaction/droid_sarcastic.stf', 70, 'hi_mid_4', 'Salutations! Fancy word, isn''t it?'),
('string/en/npc_reaction/droid_sarcastic.stf', 71, 'hi_mid_5', 'Yes?'),
('string/en/npc_reaction/droid_sarcastic.stf', 72, 'hi_mid_6', 'Greetings.'),
('string/en/npc_reaction/droid_sarcastic.stf', 73, 'hi_mid_7', 'Ah. Ehem. Yes?'),
('string/en/npc_reaction/droid_sarcastic.stf', 74, 'hi_mid_8', 'You looking for something or someone?'),
('string/en/npc_reaction/droid_sarcastic.stf', 75, 'hi_mid_9', 'You looking for something or someone? Not me, I assume.'),
('string/en/npc_reaction/droid_sarcastic.stf', 76, 'hi_mid_10', 'You want something, right? Everyone always wants something from me.'),
('string/en/npc_reaction/droid_sarcastic.stf', 77, 'hi_mid_11', 'Hello.'),
('string/en/npc_reaction/droid_sarcastic.stf', 78, 'hi_mid_12', 'Yes?'),
('string/en/npc_reaction/droid_sarcastic.stf', 79, 'hi_mid_13', 'Hm? Ah, of course. Another person come to ask something of me. Well, I have needs too, you know.'),
('string/en/npc_reaction/droid_sarcastic.stf', 80, 'hi_mid_14', 'Yes?'),
('string/en/npc_reaction/droid_sarcastic.stf', 82, 'hi_mid_15', 'Can I help you? I''m supposed to say that, since I am a droid. I don''t really WANT to help you, but i am programmed to, so I have to. Not to makeyou feel guilty or anything.'),
('string/en/npc_reaction/droid_sarcastic.stf', 83, 'hi_mid_16', 'Can I help you?'),
('string/en/npc_reaction/droid_sarcastic.stf', 84, 'hi_mean_1', 'What exactly do YOU want?'),
('string/en/npc_reaction/droid_sarcastic.stf', 85, 'hi_mean_2', 'Well, now, look who''s bothering to say hello to a mere droid.'),
('string/en/npc_reaction/droid_sarcastic.stf', 86, 'hi_mean_3', 'Look, a pest!'),
('string/en/npc_reaction/droid_sarcastic.stf', 87, 'hi_mean_4', 'Imagine me saying some incredibly sarcastic greeting to you now.'),
('string/en/npc_reaction/droid_sarcastic.stf', 88, 'hi_mean_5', 'Well, that has quite spolied my day. What do you want?'),
('string/en/npc_reaction/droid_sarcastic.stf', 89, 'hi_mean_6', 'Oh, it''s YOU.'),
('string/en/npc_reaction/droid_sarcastic.stf', 90, 'hi_mean_7', 'You skulk about very well. Did you go to skulking school?'),
('string/en/npc_reaction/droid_sarcastic.stf', 91, 'hi_mean_8', 'I can feel myself rusting when you''re here.'),
('string/en/npc_reaction/droid_sarcastic.stf', 92, 'hi_mean_9', 'If I can''t get handouts from my master, what makes you think you''ll get one from me?'),
('string/en/npc_reaction/droid_sarcastic.stf', 93, 'hi_mean_10', 'Don''t make angry. I have a sharp tongue.'),
('string/en/npc_reaction/droid_sarcastic.stf', 94, 'hi_mean_11', 'Remove yourself. (See how dismissively I say that?)'),
('string/en/npc_reaction/droid_sarcastic.stf', 95, 'hi_mean_12', 'Get away, maggot. Maggot. Isn''t that such a good word?'),
('string/en/npc_reaction/droid_sarcastic.stf', 96, 'hi_mean_13', 'A scoundrel has come by to say hello. How refreshing.'),
('string/en/npc_reaction/droid_sarcastic.stf', 97, 'hi_mean_14', 'An unwelcome visitor! How nice.'),
('string/en/npc_reaction/droid_sarcastic.stf', 98, 'hi_mean_15', 'Kindly remove yourself from my presence.'),
('string/en/npc_reaction/droid_sarcastic.stf', 99, 'hi_mean_16', 'You''re not welcome in my company. Nor do you deserve it.'),
('string/en/npc_reaction/droid_sarcastic.stf', 100, 'bye_nice_1', 'Goodbye.'),
('string/en/npc_reaction/droid_sarcastic.stf', 101, 'bye_nice_2', 'Goodbye!'),
('string/en/npc_reaction/droid_sarcastic.stf', 102, 'bye_nice_3', 'Bye!'),
('string/en/npc_reaction/droid_sarcastic.stf', 103, 'bye_nice_4', 'See you around.'),
('string/en/npc_reaction/droid_sarcastic.stf', 104, 'bye_nice_5', 'See you later.'),
('string/en/npc_reaction/droid_sarcastic.stf', 105, 'bye_nice_6', 'I''ll catch you later.'),
('string/en/npc_reaction/droid_sarcastic.stf', 106, 'bye_nice_7', 'It was really nice to see you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 107, 'bye_nice_8', 'It was great to see you!'),
('string/en/npc_reaction/droid_sarcastic.stf', 108, 'bye_nice_9', 'I hope I''ll see you again before I rust away to nothing.'),
('string/en/npc_reaction/droid_sarcastic.stf', 109, 'bye_nice_10', 'Stop by again sometime! My droid brain enjoys stimulating conversation. Or even just the presence of any living being. Some non-living ones too.'),
('string/en/npc_reaction/droid_sarcastic.stf', 110, 'bye_nice_11', 'Sorry you have to go... Instead, I''m stuck here with the knuckleheads.'),
('string/en/npc_reaction/droid_sarcastic.stf', 111, 'bye_nice_12', 'Leaving? Too bad. I''ll see you around.'),
('string/en/npc_reaction/droid_sarcastic.stf', 112, 'bye_nice_13', 'Always nice to see you. Come back soon! Bring some more droids with you so we can hang out.'),
('string/en/npc_reaction/droid_sarcastic.stf', 113, 'bye_nice_14', 'Glad to see you, sorry to see you go.'),
('string/en/npc_reaction/droid_sarcastic.stf', 114, 'bye_nice_15', 'I hate to see you go... whenever I get left alone bad things happen.'),
('string/en/npc_reaction/droid_sarcastic.stf', 115, 'bye_nice_16', 'I wish you didn''t have to leave. You''re much more entertaining than listening to my circuits hum.'),
('string/en/npc_reaction/droid_sarcastic.stf', 116, 'bye_mid_1', 'Goodbye.'),
('string/en/npc_reaction/droid_sarcastic.stf', 117, 'bye_mid_2', 'Goodbye! Farewell! Have a nice trip or day. Or whatever.'),
('string/en/npc_reaction/droid_sarcastic.stf', 118, 'bye_mid_3', 'See you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 119, 'bye_mid_4', 'I''m sure I''ll see you again. Knowing how droids get treated though, you may just avoid me.'),
('string/en/npc_reaction/droid_sarcastic.stf', 120, 'bye_mid_5', 'So, you have to go? Any chance you could take me with you? No? Oh well.'),
('string/en/npc_reaction/droid_sarcastic.stf', 121, 'bye_mid_6', 'Farewell.'),
('string/en/npc_reaction/droid_sarcastic.stf', 122, 'bye_mid_7', 'Goodbye, goodbye.'),
('string/en/npc_reaction/droid_sarcastic.stf', 123, 'bye_mid_8', 'Bye, see you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 124, 'bye_mid_9', 'Bye!'),
('string/en/npc_reaction/droid_sarcastic.stf', 125, 'bye_mid_10', 'Later, then.'),
('string/en/npc_reaction/droid_sarcastic.stf', 126, 'bye_mid_11', 'Oh, you''re leaving? Nobody ever wants to stay with droids.'),
('string/en/npc_reaction/droid_sarcastic.stf', 127, 'bye_mid_12', 'Expected somewhere? See you later.'),
('string/en/npc_reaction/droid_sarcastic.stf', 128, 'bye_mid_13', 'Got somewhere to be? Sure, go spend time away from the droid.'),
('string/en/npc_reaction/droid_sarcastic.stf', 129, 'bye_mid_14', 'Places to go, people to see? Bye!'),
('string/en/npc_reaction/droid_sarcastic.stf', 130, 'bye_mid_15', 'You''re leaving? Well, I''m sure we''ll catch up again sometime.'),
('string/en/npc_reaction/droid_sarcastic.stf', 131, 'bye_mid_16', 'OK, I have to go too. Well, no, not really. But anyway, bye!'),
('string/en/npc_reaction/droid_sarcastic.stf', 132, 'bye_mean_1', 'Get lost and stay lost.'),
('string/en/npc_reaction/droid_sarcastic.stf', 133, 'bye_mean_2', 'Goodbye and good riddance.'),
('string/en/npc_reaction/droid_sarcastic.stf', 134, 'bye_mean_3', 'Your kind''s not welcome around here. (I always wanted to use that line!)'),
('string/en/npc_reaction/droid_sarcastic.stf', 135, 'bye_mean_4', 'Goodbye! And don''t come back!'),
('string/en/npc_reaction/droid_sarcastic.stf', 136, 'bye_mean_5', 'Bye, and don''t let the door hit you on the way out.'),
('string/en/npc_reaction/droid_sarcastic.stf', 137, 'bye_mean_6', 'If I see you around later, you''ll regret it.'),
('string/en/npc_reaction/droid_sarcastic.stf', 138, 'bye_mean_7', 'Goodbye, scum.'),
('string/en/npc_reaction/droid_sarcastic.stf', 139, 'bye_mean_8', 'Get lost.'),
('string/en/npc_reaction/droid_sarcastic.stf', 140, 'bye_mean_9', 'Glad to see YOUR back.'),
('string/en/npc_reaction/droid_sarcastic.stf', 141, 'bye_mean_10', 'Finally, you''re leaving.'),
('string/en/npc_reaction/droid_sarcastic.stf', 142, 'bye_mean_11', 'About time you slunk out of here.'),
('string/en/npc_reaction/droid_sarcastic.stf', 143, 'bye_mean_12', 'About time you left!'),
('string/en/npc_reaction/droid_sarcastic.stf', 144, 'bye_mean_13', 'Don''t come back.'),
('string/en/npc_reaction/droid_sarcastic.stf', 145, 'bye_mean_14', 'Here''s hoping you have a nasty accident.'),
('string/en/npc_reaction/droid_sarcastic.stf', 146, 'bye_mean_15', 'If you hadn''t left, I''d probably make you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 147, 'bye_mean_16', 'Well, now that the smell''s gone...'),
('string/en/npc_reaction/droid_sarcastic.stf', 148, 'threat_1', 'You should get out of here before you''re bowled over by my amazing wit.'),
('string/en/npc_reaction/droid_sarcastic.stf', 149, 'threat_2', 'I don''t like your kind around here. Around me. Whatever. That didn''t sound very threatening, did it?'),
('string/en/npc_reaction/droid_sarcastic.stf', 150, 'threat_3', 'You should probably leave.'),
('string/en/npc_reaction/droid_sarcastic.stf', 151, 'threat_4', 'This place is very dangerous. To you, that is.'),
('string/en/npc_reaction/droid_sarcastic.stf', 152, 'threat_5', 'The best thing you could do is move away very quietly. Well, I guess the quiet is optional. You could whistle or hum or something if you want.'),
('string/en/npc_reaction/droid_sarcastic.stf', 153, 'threat_6', 'Move away, or I might have to do something I''m sure I''ll regret.'),
('string/en/npc_reaction/droid_sarcastic.stf', 154, 'threat_7', 'Look, I''m arming myself. Activating all kinds of deadly droid weapons. Really.'),
('string/en/npc_reaction/droid_sarcastic.stf', 155, 'threat_8', 'You must be feeling really lucky, to come challenge me, the truly deadly battle droid. I''m vicious, I tell you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 156, 'threat_9', 'Please, don''t come any closer. I might have to hit you or something.'),
('string/en/npc_reaction/droid_sarcastic.stf', 157, 'threat_10', 'I''d boast about my vast collection of trophies from vanquished enemies, but I don''t actully have one. You should leave anyway.'),
('string/en/npc_reaction/droid_sarcastic.stf', 158, 'threat_11', 'I''m thinking that you''re looking for trouble. I''m not trouble, I''m just his cousin.'),
('string/en/npc_reaction/droid_sarcastic.stf', 159, 'threat_12', 'If you come closer, I might have to take violent action. I really don''t want to, though, because I might get hurt.'),
('string/en/npc_reaction/droid_sarcastic.stf', 160, 'threat_13', 'If you give me an excuse, I''ll kill you. If you''re having trouble thinking of excuses, I can suggest some.'),
('string/en/npc_reaction/droid_sarcastic.stf', 161, 'threat_14', 'I will NOT clean up the mess your corpse leaves behind.'),
('string/en/npc_reaction/droid_sarcastic.stf', 162, 'threat_15', 'Many have praised my combat skills... well, no, not really. But I''ll fight if I have to.'),
('string/en/npc_reaction/droid_sarcastic.stf', 163, 'threat_16', 'I hate to say this, but I''m programmed to kill you if you come any closer. Believe me, it''s not my choice. I''m just coded that way.'),
('string/en/npc_reaction/droid_sarcastic.stf', 164, 'death_1', 'Figures that it would be the droid that gets it.'),
('string/en/npc_reaction/droid_sarcastic.stf', 165, 'death_2', 'Oooo, colors.'),
('string/en/npc_reaction/droid_sarcastic.stf', 166, 'death_3', 'Must I die?'),
('string/en/npc_reaction/droid_sarcastic.stf', 167, 'death_4', 'Master, save me!'),
('string/en/npc_reaction/droid_sarcastic.stf', 168, 'death_5', 'I''m too newly assembled to die. Master, save me!'),
('string/en/npc_reaction/droid_sarcastic.stf', 169, 'death_6', 'I apologize for all the mean things I''ve ever said about my master... just save me now...'),
('string/en/npc_reaction/droid_sarcastic.stf', 170, 'death_7', 'Must... not... awww.'),
('string/en/npc_reaction/droid_sarcastic.stf', 171, 'death_8', 'Sure, you kill me now, but I shall return more powerful than you can imag... agh.'),
('string/en/npc_reaction/droid_sarcastic.stf', 172, 'death_9', 'Take pity on a poor droid...'),
('string/en/npc_reaction/droid_sarcastic.stf', 173, 'death_10', 'FATAL:: failure in static procedure "smart_remark.cpp." This is a highly abnormal failure for this droid.'),
('string/en/npc_reaction/droid_sarcastic.stf', 174, 'death_11', 'Not again... back to the recycling bin.'),
('string/en/npc_reaction/droid_sarcastic.stf', 175, 'death_12', 'I''m done for. Master, this is all your fault.'),
('string/en/npc_reaction/droid_sarcastic.stf', 176, 'death_13', 'I guess this is all the time I get. Not even a full normal lifespan. Well, phooey.'),
('string/en/npc_reaction/droid_sarcastic.stf', 177, 'death_14', 'You''ll regret dismantling such a fine piece of machinery as myself!'),
('string/en/npc_reaction/droid_sarcastic.stf', 178, 'death_15', 'I think I''m supposed to say "aggg" and keel over now.'),
('string/en/npc_reaction/droid_sarcastic.stf', 179, 'death_16', 'I really would rather not... urk.'),
('string/en/npc_reaction/droid_sarcastic.stf', 180, 'gloat_1', 'Wow, that was almost as easy as killing ME.'),
('string/en/npc_reaction/droid_sarcastic.stf', 181, 'gloat_2', 'I guess that was a good fight. I walked away from it.'),
('string/en/npc_reaction/droid_sarcastic.stf', 182, 'gloat_3', 'Well, that was too close for comfort. ANYTHING is too close for comfort.'),
('string/en/npc_reaction/droid_sarcastic.stf', 183, 'gloat_4', 'Just think, someday am opponent like this will make me cease functioning. What a tragedy.'),
('string/en/npc_reaction/droid_sarcastic.stf', 184, 'gloat_5', 'A worthy opponent for a pathetic droid like me.'),
('string/en/npc_reaction/droid_sarcastic.stf', 185, 'gloat_6', 'Well, they thought they could take me on. Hah.'),
('string/en/npc_reaction/droid_sarcastic.stf', 186, 'gloat_7', 'Now, I assume I''ll have to clean up the mess?'),
('string/en/npc_reaction/droid_sarcastic.stf', 187, 'gloat_8', 'That was pathetic. I mean, I''M pathetic, so you were even worse.'),
('string/en/npc_reaction/droid_sarcastic.stf', 188, 'gloat_9', 'Next time, bring lots of friends. Don''t use them to kill me, mind you.'),
('string/en/npc_reaction/droid_sarcastic.stf', 189, 'gloat_10', 'Sorry about that. Didn''t mean to be fatal.'),
('string/en/npc_reaction/droid_sarcastic.stf', 190, 'gloat_11', 'Really, master, should a droid be killing people? Is it really proper?'),
('string/en/npc_reaction/droid_sarcastic.stf', 191, 'gloat_12', 'So, if a droid kills people, the master gets blamed, not the droid, right?'),
('string/en/npc_reaction/droid_sarcastic.stf', 192, 'gloat_13', 'Ha! Who would have thought that I would win? Not I!'),
('string/en/npc_reaction/droid_sarcastic.stf', 193, 'gloat_14', 'Anyone who''s trying to disassemble me deserves what they get.'),
('string/en/npc_reaction/droid_sarcastic.stf', 194, 'gloat_15', 'Never underestimate the power of a sarcastic droid.'),
('string/en/npc_reaction/droid_sarcastic.stf', 195, 'gloat_16', 'Another one down, just like I''ll be someday... Sigh.'),
('string/en/npc_reaction/droid_sarcastic.stf', 196, 'hit_1', 'Ow.'),
('string/en/npc_reaction/droid_sarcastic.stf', 197, 'hit_2', 'Now, would you look at those scratches?'),
('string/en/npc_reaction/droid_sarcastic.stf', 198, 'hit_3', 'It''ll take more than that to bring me down. Not MUCH more, I admit...'),
('string/en/npc_reaction/droid_sarcastic.stf', 199, 'hit_4', 'If I close my eyes maybe this will all go away...'),
('string/en/npc_reaction/droid_sarcastic.stf', 200, 'hit_5', 'Ouch.'),
('string/en/npc_reaction/droid_sarcastic.stf', 201, 'hit_6', 'Now I''m getting mad. Well, as mad as a droid can get.'),
('string/en/npc_reaction/droid_sarcastic.stf', 202, 'hit_7', 'I''m still standing! Amazing!'),
('string/en/npc_reaction/droid_sarcastic.stf', 203, 'hit_8', 'Ha, your deactivation attempt failed!'),
('string/en/npc_reaction/droid_sarcastic.stf', 204, 'hit_9', 'OK, so you hit me that time. Can you do it again? Wait, wait--no need to try to prove it. Really.'),
('string/en/npc_reaction/droid_sarcastic.stf', 205, 'hit_10', 'Why me?'),
('string/en/npc_reaction/droid_sarcastic.stf', 206, 'hit_11', 'This could end badly. Just as I predicted.'),
('string/en/npc_reaction/droid_sarcastic.stf', 207, 'hit_12', 'I could use a repair droid around now.'),
('string/en/npc_reaction/droid_sarcastic.stf', 208, 'hit_13', 'Oh boy, that hurts. Not that anyone cares if a droid feels pain.'),
('string/en/npc_reaction/droid_sarcastic.stf', 209, 'hit_14', 'Look at that, scratches on my finish.'),
('string/en/npc_reaction/droid_sarcastic.stf', 210, 'hit_15', 'Hmm, that''s a big dent.'),
('string/en/npc_reaction/droid_sarcastic.stf', 211, 'hit_16', 'A touch, I do confess it. A veritable ouchie.'),
('string/en/npc_reaction/droid_sarcastic.stf', 212, 'attacked_1', 'I''d threaten you, but I''m actually scared, so I''ll skip that part.'),
('string/en/npc_reaction/droid_sarcastic.stf', 213, 'attacked_2', 'Tougher enemies than you have tried to kill me. Usually, they couldn''t catch me though.'),
('string/en/npc_reaction/droid_sarcastic.stf', 214, 'attacked_3', 'Next time I''m invited to a fight, I''m planning on being busy.'),
('string/en/npc_reaction/droid_sarcastic.stf', 215, 'attacked_4', 'I hope you weren''t looking forward to old age. I was.'),
('string/en/npc_reaction/droid_sarcastic.stf', 216, 'attacked_5', 'Well, I guess dying in bed is boring anyway. I was still looking forward to it though!'),
('string/en/npc_reaction/droid_sarcastic.stf', 217, 'attacked_6', 'When you die, I will treasure your possessions always. Assuming my stingy master lets me keep anything.'),
('string/en/npc_reaction/droid_sarcastic.stf', 218, 'attacked_7', 'I wonder if there is an afertlife for droids. Probably not, just my luck.'),
('string/en/npc_reaction/droid_sarcastic.stf', 219, 'attacked_8', 'Better run. I make short work of my enemies, unless they deactivate me quickly.'),
('string/en/npc_reaction/droid_sarcastic.stf', 220, 'attacked_9', 'Oooh, I''m so scared. No, really. Resigned, too.'),
('string/en/npc_reaction/droid_sarcastic.stf', 221, 'attacked_10', 'Do we have to fight? No, really. Do we have to?'),
('string/en/npc_reaction/droid_sarcastic.stf', 222, 'attacked_11', 'I guess it''s a good day to die. As good as any other miserable, rotten day.'),
('string/en/npc_reaction/droid_sarcastic.stf', 223, 'attacked_12', 'If you start running now, at top speed, you might get away. I mention this because I''ve been thinking of doing it myself.'),
('string/en/npc_reaction/droid_sarcastic.stf', 224, 'attacked_13', 'So, you want to pick on helpless old me, eh? Figures.'),
('string/en/npc_reaction/droid_sarcastic.stf', 225, 'attacked_14', 'Be careful, or I''ll injure you badly beating my helpless body against your weapon.'),
('string/en/npc_reaction/droid_sarcastic.stf', 226, 'attacked_16', 'I do wish I had left all my affairs in order.'),
('string/en/npc_reaction/droid_sarcastic.stf', 227, 'help_1', 'Help!'),
('string/en/npc_reaction/droid_sarcastic.stf', 228, 'help_2', 'I could use some help over here...'),
('string/en/npc_reaction/droid_sarcastic.stf', 229, 'help_3', 'Help me!'),
('string/en/npc_reaction/droid_sarcastic.stf', 230, 'help_4', 'Helllp!'),
('string/en/npc_reaction/droid_sarcastic.stf', 231, 'help_5', 'Not to bother anyone, but... HELP!'),
('string/en/npc_reaction/droid_sarcastic.stf', 232, 'help_6', 'I could use some help! If you care to give it, of course!'),
('string/en/npc_reaction/droid_sarcastic.stf', 233, 'help_7', 'Not to bother any self-absorbed flesh and blood types or anything, but... HELP!'),
('string/en/npc_reaction/droid_sarcastic.stf', 234, 'help_8', 'To me! (Isn''t that what they say in the military?)'),
('string/en/npc_reaction/droid_sarcastic.stf', 235, 'help_9', 'Help! Help!'),
('string/en/npc_reaction/droid_sarcastic.stf', 236, 'help_10', 'Can anyone help me?'),
('string/en/npc_reaction/droid_sarcastic.stf', 237, 'help_11', 'Hate to bother anyone, but this droid here needs help...'),
('string/en/npc_reaction/droid_sarcastic.stf', 238, 'help_12', 'Unless you want to lose a valuable possession, HELP ME.'),
('string/en/npc_reaction/droid_sarcastic.stf', 239, 'help_13', 'Over here! Master? Anyone? Please?'),
('string/en/npc_reaction/droid_sarcastic.stf', 240, 'help_14', 'Hurry, or I''ll get dented. You know how hard it is to get dents out...'),
('string/en/npc_reaction/droid_sarcastic.stf', 241, 'help_15', 'Hurry! You don''t want scuffs and scratches on your valuable property...'),
('string/en/npc_reaction/droid_sarcastic.stf', 242, 'help_16', 'Not to bother anyone, but I think I need help.'),
('string/en/npc_reaction/droid_sarcastic.stf', 243, 'ally_1', 'I''ll probably die for saying it, but... get away from my friend!'),
('string/en/npc_reaction/droid_sarcastic.stf', 244, 'ally_2', 'Don''t lay a finger, tentacle, pseudopod, or other tactile appendage on my friends...!'),
('string/en/npc_reaction/droid_sarcastic.stf', 245, 'ally_3', 'Why, you...!'),
('string/en/npc_reaction/droid_sarcastic.stf', 246, 'ally_4', 'Hey now! Back off! You don''t want me to step in!'),
('string/en/npc_reaction/droid_sarcastic.stf', 247, 'ally_5', 'Now look, you''ve made me have to jump in, which ill likely result in damage to my chassis.'),
('string/en/npc_reaction/droid_sarcastic.stf', 248, 'ally_6', 'I''d urge you pick on me instead, but that might incur damage to my motivators. Would you care to run away instead?'),
('string/en/npc_reaction/droid_sarcastic.stf', 249, 'ally_7', 'Why do I always have to be the one to put myself at risk?'),
('string/en/npc_reaction/droid_sarcastic.stf', 250, 'ally_8', 'I suppose you''re going to tell me you need help now. Sigh.'),
('string/en/npc_reaction/droid_sarcastic.stf', 251, 'ally_9', 'That''s right, call on the droid. Watch him get mangled.'),
('string/en/npc_reaction/droid_sarcastic.stf', 252, 'ally_10', 'Well, well. Guess it''s time for me to step in here. Everyone always needs the droid''s help.'),
('string/en/npc_reaction/droid_sarcastic.stf', 253, 'ally_11', 'Hey now! You OK? Need a droid helper?'),
('string/en/npc_reaction/droid_sarcastic.stf', 254, 'ally_12', 'Hey now! Leave my (admittedly not the smartest) friend alone!'),
('string/en/npc_reaction/droid_sarcastic.stf', 255, 'ally_13', 'I don''t care who you are, you don''t touch my friends. Even if they are annoying.'),
('string/en/npc_reaction/droid_sarcastic.stf', 256, 'ally_14', 'Hey now!'),
('string/en/npc_reaction/droid_sarcastic.stf', 257, 'ally_15', 'You OK, friend? Let a REAL droid take care of this...'),
('string/en/npc_reaction/droid_sarcastic.stf', 258, 'ally_16', 'Let me even the odds a little... OK, not really, I''m not that useful in a fight. But I always wanted to say that.'),
('string/en/npc_reaction/droid_sarcastic.stf', 259, 'hit_target_1', 'Well, you seem to be stturdier than I am!'),
('string/en/npc_reaction/droid_sarcastic.stf', 260, 'hit_target_2', 'Aha!'),
('string/en/npc_reaction/droid_sarcastic.stf', 261, 'hit_target_3', 'I think I got you. Right? Right? Got you right there, I can tell. Admit it. Huh? I got you!'),
('string/en/npc_reaction/droid_sarcastic.stf', 262, 'hit_target_4', 'Does that hurt?'),
('string/en/npc_reaction/droid_sarcastic.stf', 263, 'hit_target_5', 'You know, instead of fighting me, you could be fighting my master.'),
('string/en/npc_reaction/droid_sarcastic.stf', 264, 'hit_target_6', 'I''ll try to kill you quick, if you stand still.'),
('string/en/npc_reaction/droid_sarcastic.stf', 265, 'hit_target_7', 'I don''t believe in unnecesary pain. Especially not my own.'),
('string/en/npc_reaction/droid_sarcastic.stf', 266, 'hit_target_8', 'If you ran away, I''d have to call you a coward. Which would be unusual, I usually call myself that.'),
('string/en/npc_reaction/droid_sarcastic.stf', 267, 'hit_target_9', 'I can''t believe it. I hit you. Amazing.'),
('string/en/npc_reaction/droid_sarcastic.stf', 268, 'hit_target_10', 'You''re probably going to be deactivated, you know.'),
('string/en/npc_reaction/droid_sarcastic.stf', 269, 'hit_target_11', 'No sense trying to escape--ours is a futile struggle against the careless whims of fate.'),
('string/en/npc_reaction/droid_sarcastic.stf', 270, 'hit_target_12', 'Violence is so coarse. I''m much rather have peaceful oil baths. How about you?'),
('string/en/npc_reaction/droid_sarcastic.stf', 271, 'hit_target_13', 'There, I hit you. Now, run away. Shoo.'),
('string/en/npc_reaction/droid_sarcastic.stf', 272, 'hit_target_14', 'You should flee while you can. I know I would.'),
('string/en/npc_reaction/droid_sarcastic.stf', 273, 'hit_target_15', 'Did I hurt you? Sorry. I''m not much of one for inflicting pain, really.'),
('string/en/npc_reaction/droid_sarcastic.stf', 274, 'hit_target_16', 'If you surrender now, then we could stop fighting. Think how nice that would be.'),
('string/en/npc_reaction/droid_slang.stf', 1, 'alert_1', 'Now hold on there...!'),
('string/en/npc_reaction/droid_slang.stf', 2, 'alert_2', 'What wuz that?!?'),
('string/en/npc_reaction/droid_slang.stf', 3, 'alert_3', 'Didja hear summat?'),
('string/en/npc_reaction/droid_slang.stf', 4, 'alert_4', 'Wuzzat smell?'),
('string/en/npc_reaction/droid_slang.stf', 5, 'alert_5', 'Summat''s wrong...'),
('string/en/npc_reaction/droid_slang.stf', 6, 'flee_1', 'Oh, by th'' stars! Run!'),
('string/en/npc_reaction/droid_slang.stf', 7, 'flee_2', 'Help!'),
('string/en/npc_reaction/droid_slang.stf', 8, 'flee_3', 'Look out, boys!'),
('string/en/npc_reaction/droid_slang.stf', 9, 'flee_4', 'Get outta the way! Run!'),
('string/en/npc_reaction/droid_slang.stf', 10, 'flee_5', 'Run fer yer lives!'),
('string/en/npc_reaction/droid_slang.stf', 11, 'calm_1', 'Whew. Okey, that''s done with.'),
('string/en/npc_reaction/droid_slang.stf', 12, 'calm_2', 'Okeydokey, calmin'' down. ''S alright.'),
('string/en/npc_reaction/droid_slang.stf', 13, 'calm_3', 'I''m thankin'' goodness THAT''s over.'),
('string/en/npc_reaction/droid_slang.stf', 14, 'calm_4', 'Time ter settle down a bit. Whew,'),
('string/en/npc_reaction/droid_slang.stf', 15, 'calm_5', 'Time ter go to my happy place.'),
('string/en/npc_reaction/droid_slang.stf', 16, 'alert_6', 'I''m gettin'' a bad feelin'' about now...'),
('string/en/npc_reaction/droid_slang.stf', 17, 'alert_7', 'I gots a bad feelin'' about this...'),
('string/en/npc_reaction/droid_slang.stf', 18, 'alert_8', 'Hang on a bit... what wuzzat?'),
('string/en/npc_reaction/droid_slang.stf', 19, 'alert_9', 'Hurm?'),
('string/en/npc_reaction/droid_slang.stf', 20, 'alert_10', 'Eh now?'),
('string/en/npc_reaction/droid_slang.stf', 21, 'alert_11', 'What the...?'),
('string/en/npc_reaction/droid_slang.stf', 22, 'alert_12', 'Uh oh...'),
('string/en/npc_reaction/droid_slang.stf', 23, 'alert_13', 'Now wha...?'),
('string/en/npc_reaction/droid_slang.stf', 24, 'alert_14', 'Oh golly!'),
('string/en/npc_reaction/droid_slang.stf', 25, 'alert_15', 'Wha...?'),
('string/en/npc_reaction/droid_slang.stf', 26, 'alert_16', 'Now, what''m I hearin''...?'),
('string/en/npc_reaction/droid_slang.stf', 28, 'calm_6', 'I''m guessin'' there''s no worries.'),
('string/en/npc_reaction/droid_slang.stf', 29, 'calm_7', 'No worries, mate!'),
('string/en/npc_reaction/droid_slang.stf', 30, 'calm_8', 'Hmph.'),
('string/en/npc_reaction/droid_slang.stf', 31, 'calm_9', 'Okeydokey then...!'),
('string/en/npc_reaction/droid_slang.stf', 32, 'calm_10', 'Welp, that''s over.'),
('string/en/npc_reaction/droid_slang.stf', 33, 'calm_11', 'Welp, that''s that I guess.'),
('string/en/npc_reaction/droid_slang.stf', 34, 'calm_12', 'Golly.'),
('string/en/npc_reaction/droid_slang.stf', 35, 'calm_13', 'So much fer that...'),
('string/en/npc_reaction/droid_slang.stf', 36, 'calm_14', 'Well, so much fer that!'),
('string/en/npc_reaction/droid_slang.stf', 37, 'calm_15', 'Ho-hum ''n'' all that.'),
('string/en/npc_reaction/droid_slang.stf', 39, 'calm_16', 'Lookin'' like the danger''s gone.'),
('string/en/npc_reaction/droid_slang.stf', 40, 'flee_6', 'Run away!'),
('string/en/npc_reaction/droid_slang.stf', 41, 'flee_7', 'Let''s get outta here!'),
('string/en/npc_reaction/droid_slang.stf', 42, 'flee_8', 'Uh, run for it!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/npc_reaction/droid_slang.stf', 43, 'flee_9', 'Time to get outta here!'),
('string/en/npc_reaction/droid_slang.stf', 44, 'flee_10', 'Hellllp!'),
('string/en/npc_reaction/droid_slang.stf', 45, 'flee_11', 'Ack no!'),
('string/en/npc_reaction/droid_slang.stf', 46, 'flee_12', 'Gotta get outta here!'),
('string/en/npc_reaction/droid_slang.stf', 47, 'flee_13', 'Time ter get outta hereabouts!'),
('string/en/npc_reaction/droid_slang.stf', 48, 'flee_14', 'Time ter run!'),
('string/en/npc_reaction/droid_slang.stf', 49, 'flee_15', 'I don'' wanna get diassembled!'),
('string/en/npc_reaction/droid_slang.stf', 50, 'flee_16', 'Why''m I always in the soup?'),
('string/en/npc_reaction/droid_slang.stf', 51, 'hi_nice_1', '''S great to see ya again, buddy!'),
('string/en/npc_reaction/droid_slang.stf', 52, 'hi_nice_2', '''S wunnerful to see yer again!'),
('string/en/npc_reaction/droid_slang.stf', 53, 'hi_nice_3', 'Hullo there!'),
('string/en/npc_reaction/droid_slang.stf', 54, 'hi_nice_4', '''S great to see yer!'),
('string/en/npc_reaction/droid_slang.stf', 55, 'hi_nice_5', 'Good t''see ya!'),
('string/en/npc_reaction/droid_slang.stf', 56, 'hi_nice_6', 'Well, hullo!'),
('string/en/npc_reaction/droid_slang.stf', 57, 'hi_nice_7', '''S nice to see yer!'),
('string/en/npc_reaction/droid_slang.stf', 58, 'hi_nice_8', 'Well, yer a sight for my sore eyes!'),
('string/en/npc_reaction/droid_slang.stf', 59, 'hi_nice_9', 'Greetin''s, mate!'),
('string/en/npc_reaction/droid_slang.stf', 60, 'hi_nice_10', 'Hey there, buddy!'),
('string/en/npc_reaction/droid_slang.stf', 61, 'hi_nice_11', 'Hullo! Right nice to see ya!'),
('string/en/npc_reaction/droid_slang.stf', 62, 'hi_nice_12', 'Welcome!'),
('string/en/npc_reaction/droid_slang.stf', 63, 'hi_nice_13', 'Hi there, buddy!'),
('string/en/npc_reaction/droid_slang.stf', 64, 'hi_nice_14', 'Sure happy to see ya!'),
('string/en/npc_reaction/droid_slang.stf', 65, 'hi_nice_15', 'Well, now, looky here! '),
('string/en/npc_reaction/droid_slang.stf', 66, 'hi_nice_16', 'Hullo! Yer needin'' help?'),
('string/en/npc_reaction/droid_slang.stf', 67, 'hi_mid_1', 'Hullo.'),
('string/en/npc_reaction/droid_slang.stf', 68, 'hi_mid_2', 'Can I help ya?'),
('string/en/npc_reaction/droid_slang.stf', 69, 'hi_mid_3', 'Hullo there.'),
('string/en/npc_reaction/droid_slang.stf', 70, 'hi_mid_4', 'Greetin''s.'),
('string/en/npc_reaction/droid_slang.stf', 71, 'hi_mid_5', 'Yeh?'),
('string/en/npc_reaction/droid_slang.stf', 72, 'hi_mid_6', 'Hullo.'),
('string/en/npc_reaction/droid_slang.stf', 73, 'hi_mid_7', 'Mhhhmmm. Yeah?'),
('string/en/npc_reaction/droid_slang.stf', 74, 'hi_mid_8', 'You lookin'' for summat?'),
('string/en/npc_reaction/droid_slang.stf', 75, 'hi_mid_9', 'You lookin'' fer someone?'),
('string/en/npc_reaction/droid_slang.stf', 76, 'hi_mid_10', 'Whatcha want?'),
('string/en/npc_reaction/droid_slang.stf', 77, 'hi_mid_11', 'Heya.'),
('string/en/npc_reaction/droid_slang.stf', 78, 'hi_mid_12', 'Yeah? What''s up?'),
('string/en/npc_reaction/droid_slang.stf', 79, 'hi_mid_13', 'Hmm.'),
('string/en/npc_reaction/droid_slang.stf', 80, 'hi_mid_14', 'Hmm. Yeah?'),
('string/en/npc_reaction/droid_slang.stf', 82, 'hi_mid_15', 'Oh yeah. Can I help ya?'),
('string/en/npc_reaction/droid_slang.stf', 83, 'hi_mid_16', 'Eh?'),
('string/en/npc_reaction/droid_slang.stf', 84, 'hi_mean_1', 'Whadda YOU want?'),
('string/en/npc_reaction/droid_slang.stf', 85, 'hi_mean_2', 'Looky who''s here.'),
('string/en/npc_reaction/droid_slang.stf', 86, 'hi_mean_3', 'You smell bantha poodoo? Oh, must be my "friend" here.'),
('string/en/npc_reaction/droid_slang.stf', 87, 'hi_mean_4', 'Be a waste o'' breath to say hullo to the likes of YOU.'),
('string/en/npc_reaction/droid_slang.stf', 88, 'hi_mean_5', 'Ar now, what''re YOU wantin''?'),
('string/en/npc_reaction/droid_slang.stf', 89, 'hi_mean_6', 'Oh, ''s YOU.'),
('string/en/npc_reaction/droid_slang.stf', 90, 'hi_mean_7', 'What''re you snoopin'' around for?'),
('string/en/npc_reaction/droid_slang.stf', 91, 'hi_mean_8', 'Looky who it is. Lemme plug my ears.'),
('string/en/npc_reaction/droid_slang.stf', 92, 'hi_mean_9', 'Oh brother. What''re YOU wantin''?'),
('string/en/npc_reaction/droid_slang.stf', 93, 'hi_mean_10', 'Clear out. You don'' wanna see me really angry.'),
('string/en/npc_reaction/droid_slang.stf', 94, 'hi_mean_11', 'Get on outta here.'),
('string/en/npc_reaction/droid_slang.stf', 95, 'hi_mean_12', 'Get yer face outta my sight.'),
('string/en/npc_reaction/droid_slang.stf', 96, 'hi_mean_13', 'Looky here, a maggot come to say hullo.'),
('string/en/npc_reaction/droid_slang.stf', 97, 'hi_mean_14', 'Y''ain''t welcome ''round these parts, scum.'),
('string/en/npc_reaction/droid_slang.stf', 98, 'hi_mean_15', 'Well, now, I been itchin'' for a fight lately...'),
('string/en/npc_reaction/droid_slang.stf', 99, 'hi_mean_16', 'You like yer bones intact, ya better leave.'),
('string/en/npc_reaction/droid_slang.stf', 100, 'bye_nice_1', 'Nice ta see ya! Bye now!'),
('string/en/npc_reaction/droid_slang.stf', 101, 'bye_nice_2', 'Byebye!'),
('string/en/npc_reaction/droid_slang.stf', 102, 'bye_nice_3', 'Be seein'' ya, buddy!'),
('string/en/npc_reaction/droid_slang.stf', 103, 'bye_nice_4', 'I''ll see ya ''round!'),
('string/en/npc_reaction/droid_slang.stf', 104, 'bye_nice_5', 'Catch ya later, buddy!'),
('string/en/npc_reaction/droid_slang.stf', 105, 'bye_nice_6', 'Goodbye, bud!'),
('string/en/npc_reaction/droid_slang.stf', 106, 'bye_nice_7', 'Hey now, I''ll see ya later!'),
('string/en/npc_reaction/droid_slang.stf', 107, 'bye_nice_8', 'Aww, you gotta go?'),
('string/en/npc_reaction/droid_slang.stf', 108, 'bye_nice_9', 'Well, I hate ter see ya go...'),
('string/en/npc_reaction/droid_slang.stf', 109, 'bye_nice_10', 'Yer leavin? Aww...'),
('string/en/npc_reaction/droid_slang.stf', 110, 'bye_nice_11', 'Goodbye! Sorry yer headin'' out.'),
('string/en/npc_reaction/droid_slang.stf', 111, 'bye_nice_12', 'Will I ever see ya again?'),
('string/en/npc_reaction/droid_slang.stf', 112, 'bye_nice_13', 'Sure hope to see ya again.'),
('string/en/npc_reaction/droid_slang.stf', 113, 'bye_nice_14', 'Wuz an honor ter see ya. Honest.'),
('string/en/npc_reaction/droid_slang.stf', 114, 'bye_nice_15', 'Really great to see ya, y''know.'),
('string/en/npc_reaction/droid_slang.stf', 115, 'bye_nice_16', 'Don''t ferget me, OK?'),
('string/en/npc_reaction/droid_slang.stf', 116, 'bye_mid_1', 'Bye.'),
('string/en/npc_reaction/droid_slang.stf', 117, 'bye_mid_2', 'G''bye.'),
('string/en/npc_reaction/droid_slang.stf', 118, 'bye_mid_3', 'Bye-bye.'),
('string/en/npc_reaction/droid_slang.stf', 119, 'bye_mid_4', 'See ya.'),
('string/en/npc_reaction/droid_slang.stf', 120, 'bye_mid_5', 'Be seein'' ya.'),
('string/en/npc_reaction/droid_slang.stf', 121, 'bye_mid_6', 'See ya ''round.'),
('string/en/npc_reaction/droid_slang.stf', 122, 'bye_mid_7', 'Bye now.'),
('string/en/npc_reaction/droid_slang.stf', 123, 'bye_mid_8', 'Well now. See ya later.'),
('string/en/npc_reaction/droid_slang.stf', 124, 'bye_mid_9', 'See ya later.'),
('string/en/npc_reaction/droid_slang.stf', 125, 'bye_mid_10', 'G''bye now.'),
('string/en/npc_reaction/droid_slang.stf', 126, 'bye_mid_11', 'Leavin''? Bye.'),
('string/en/npc_reaction/droid_slang.stf', 127, 'bye_mid_12', 'Headin'' out? Bye.'),
('string/en/npc_reaction/droid_slang.stf', 128, 'bye_mid_13', 'Gotta go? Bye.'),
('string/en/npc_reaction/droid_slang.stf', 129, 'bye_mid_14', 'Got a date? See ya later.'),
('string/en/npc_reaction/droid_slang.stf', 130, 'bye_mid_15', 'Someone waitin'' on ya? See ya ''round then.'),
('string/en/npc_reaction/droid_slang.stf', 131, 'bye_mid_16', 'In a rush, huh? Bye then.'),
('string/en/npc_reaction/droid_slang.stf', 132, 'bye_mean_1', 'Get lost, bud.'),
('string/en/npc_reaction/droid_slang.stf', 133, 'bye_mean_2', 'Good riddance, buster.'),
('string/en/npc_reaction/droid_slang.stf', 134, 'bye_mean_3', 'Thass right, walk away, scumbag.'),
('string/en/npc_reaction/droid_slang.stf', 135, 'bye_mean_4', 'Thass right, take a hike into a Sarlaac, scumbag.'),
('string/en/npc_reaction/droid_slang.stf', 136, 'bye_mean_5', 'Bye bye, scumbag.'),
('string/en/npc_reaction/droid_slang.stf', 137, 'bye_mean_6', 'Better leave, afore I delete ya..'),
('string/en/npc_reaction/droid_slang.stf', 138, 'bye_mean_7', 'Ya ain''t welcome, so get outta here.'),
('string/en/npc_reaction/droid_slang.stf', 139, 'bye_mean_8', 'Overstayed yer welcome, eh?'),
('string/en/npc_reaction/droid_slang.stf', 140, 'bye_mean_9', 'No need to run, we can play some, if ya want, heh heh.'),
('string/en/npc_reaction/droid_slang.stf', 141, 'bye_mean_10', 'Aww, leavin'' before a fight huh?'),
('string/en/npc_reaction/droid_slang.stf', 142, 'bye_mean_11', 'Better not let me catch ya in a dark alley.'),
('string/en/npc_reaction/droid_slang.stf', 143, 'bye_mean_12', 'Now that the stink''s gone...'),
('string/en/npc_reaction/droid_slang.stf', 144, 'bye_mean_13', 'Here''s hopin'' ya don''t come back!'),
('string/en/npc_reaction/droid_slang.stf', 145, 'bye_mean_14', 'Next time ya come, bring friends. Love to beat ya ALL up.'),
('string/en/npc_reaction/droid_slang.stf', 146, 'bye_mean_15', '''Bout time ya got gone, buddy.'),
('string/en/npc_reaction/droid_slang.stf', 147, 'bye_mean_16', 'Glad to have wasted th'' time o''day on ya.'),
('string/en/npc_reaction/droid_slang.stf', 148, 'threat_1', 'Take a hike.'),
('string/en/npc_reaction/droid_slang.stf', 149, 'threat_2', 'I don'' like yer kind.'),
('string/en/npc_reaction/droid_slang.stf', 150, 'threat_3', 'Ya better clear on outta here.'),
('string/en/npc_reaction/droid_slang.stf', 151, 'threat_4', 'This is a dangerous place for the likes o'' you.'),
('string/en/npc_reaction/droid_slang.stf', 152, 'threat_5', 'If ya know what''s good for ya, you''ll scram on outta here.'),
('string/en/npc_reaction/droid_slang.stf', 153, 'threat_6', 'Back off, buddy, or I''ll do somethin'' yer gonna hate...'),
('string/en/npc_reaction/droid_slang.stf', 154, 'threat_7', 'C''mon then. Bring it on, buddy!'),
('string/en/npc_reaction/droid_slang.stf', 155, 'threat_8', 'Ya feelin'' lucky? Hmm?'),
('string/en/npc_reaction/droid_slang.stf', 156, 'threat_9', 'I''m drawin'' a line in the sand here, and I''m on this side, see, and yer on the other side, and... oh, never mind.'),
('string/en/npc_reaction/droid_slang.stf', 157, 'threat_10', 'I''m thinkin'' you''d make a nice stuffed trophy.'),
('string/en/npc_reaction/droid_slang.stf', 158, 'threat_11', 'Ya wanna taste o'' this?'),
('string/en/npc_reaction/droid_slang.stf', 159, 'threat_12', 'Come closer, ya can have a droid beatcha up!'),
('string/en/npc_reaction/droid_slang.stf', 160, 'threat_13', 'Gimme an excuse ta kill ya...'),
('string/en/npc_reaction/droid_slang.stf', 161, 'threat_14', 'Yer guts are gonna get spilled on the ground here...'),
