('string/en/npc_reaction/droid_worshipful.stf', 1, 'alert_1', 'If I am doomed to die, it is an honor to do it for my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 2, 'alert_2', 'If you have come to kill, please take my meager existence and end it, and leave my master alone.'),
('string/en/npc_reaction/droid_worshipful.stf', 3, 'alert_3', 'Life with my master is always so exciting!'),
('string/en/npc_reaction/droid_worshipful.stf', 4, 'alert_4', 'My master never worries, so I shall worry for my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 5, 'alert_5', 'Something seems to be wrong, but I have faith that my master will protect me.'),
('string/en/npc_reaction/droid_worshipful.stf', 6, 'flee_1', 'I would stay, master, but I cannot override my self-preservation programming.'),
('string/en/npc_reaction/droid_worshipful.stf', 7, 'flee_2', 'I am unworthy of help, but request it nonetheless.'),
('string/en/npc_reaction/droid_worshipful.stf', 8, 'flee_3', 'Time to flee!'),
('string/en/npc_reaction/droid_worshipful.stf', 9, 'flee_4', 'Make way! I must flee!'),
('string/en/npc_reaction/droid_worshipful.stf', 10, 'flee_5', 'Run for your life!'),
('string/en/npc_reaction/droid_worshipful.stf', 11, 'calm_1', 'The danger has passed. My master is safe.'),
('string/en/npc_reaction/droid_worshipful.stf', 12, 'calm_2', 'Time to calm down, everything is alright.'),
('string/en/npc_reaction/droid_worshipful.stf', 13, 'calm_3', 'Well, that''s over...'),
('string/en/npc_reaction/droid_worshipful.stf', 14, 'calm_4', 'It looks like I shall live another day to serve my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 15, 'calm_5', 'I would allow myself to be disassembled if it preserved my master''s life.'),
('string/en/npc_reaction/droid_worshipful.stf', 16, 'alert_6', 'I''ve got a bad feeling about this, but being near my master gives me a feeling of warm contentment.'),
('string/en/npc_reaction/droid_worshipful.stf', 17, 'alert_7', 'We may be doomed, but I perish knowing that I served my master well!'),
('string/en/npc_reaction/droid_worshipful.stf', 18, 'alert_8', 'Now, what was that? Something come to scare my master?'),
('string/en/npc_reaction/droid_worshipful.stf', 19, 'alert_9', 'Hmm?'),
('string/en/npc_reaction/droid_worshipful.stf', 20, 'alert_10', 'Imminent doom is approaching, but I die to serve my master''s honor!'),
('string/en/npc_reaction/droid_worshipful.stf', 21, 'alert_11', 'Hark, something comes to dismantle me, yet I die in my master''s service.'),
('string/en/npc_reaction/droid_worshipful.stf', 22, 'alert_12', 'I believe danger is coming, but I will sacrifice anything to save my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 23, 'alert_13', 'Danger seeks us out, but my master is brave and strong and shall never yield!'),
