('string/en/npc_reaction/droid_worshipful.stf', 46, 'flee_12', 'I have got to get out of here, master!'),
('string/en/npc_reaction/droid_worshipful.stf', 47, 'flee_13', 'Time to get out of here, master!'),
('string/en/npc_reaction/droid_worshipful.stf', 48, 'flee_14', 'Time to run, master!'),
('string/en/npc_reaction/droid_worshipful.stf', 49, 'flee_15', 'If I am deactivated, who will take care of my master?'),
('string/en/npc_reaction/droid_worshipful.stf', 50, 'flee_16', 'My master is always getting us into these situations... and out of them. I have faith.'),
('string/en/npc_reaction/droid_worshipful.stf', 51, 'hi_nice_1', 'You''re not here to se me, I assume. You must want my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 52, 'hi_nice_2', 'It''s wonderful to see you.'),
('string/en/npc_reaction/droid_worshipful.stf', 53, 'hi_nice_3', 'It''s an honor to see you here.'),
('string/en/npc_reaction/droid_worshipful.stf', 54, 'hi_nice_4', 'A pleasure and an honor to greet you. Not that you''re here to see me. You must want my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 55, 'hi_nice_5', 'It''s good to see you. You don''t care if you see ME, of course. You''re here for my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 56, 'hi_nice_6', 'I think it''s nice to see you!'),
('string/en/npc_reaction/droid_worshipful.stf', 57, 'hi_nice_7', 'Well, it''s nice to meet you!'),
('string/en/npc_reaction/droid_worshipful.stf', 58, 'hi_nice_8', 'I''m glad to see you.'),
('string/en/npc_reaction/droid_worshipful.stf', 59, 'hi_nice_9', 'Nice to see you.'),
('string/en/npc_reaction/droid_worshipful.stf', 60, 'hi_nice_10', 'I''m sure it''s great to see you.'),
('string/en/npc_reaction/droid_worshipful.stf', 61, 'hi_nice_11', 'A pleasure and honor to see you!'),
('string/en/npc_reaction/droid_worshipful.stf', 62, 'hi_nice_12', 'Welcome! Welcome!'),
('string/en/npc_reaction/droid_worshipful.stf', 63, 'hi_nice_13', 'Hello, friend of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 64, 'hi_nice_14', 'It''s a pleasure to see you here.'),
('string/en/npc_reaction/droid_worshipful.stf', 65, 'hi_nice_15', 'I''m programmed to like you. Do you know how tyrannical that feels?'),
('string/en/npc_reaction/droid_worshipful.stf', 66, 'hi_nice_16', 'Can I help you?'),
('string/en/npc_reaction/droid_worshipful.stf', 67, 'hi_mid_1', 'Hello.'),
('string/en/npc_reaction/droid_worshipful.stf', 68, 'hi_mid_2', 'Might I help you?'),
('string/en/npc_reaction/droid_worshipful.stf', 69, 'hi_mid_3', 'Greetings. If you''ll take them from an unworthy droid like me, that is. I''m sure you''d rather speak to my master.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/npc_reaction/droid_worshipful.stf', 70, 'hi_mid_4', 'Salutations!'),
('string/en/npc_reaction/droid_worshipful.stf', 71, 'hi_mid_5', 'Yes?'),
('string/en/npc_reaction/droid_worshipful.stf', 72, 'hi_mid_6', 'Greetings.'),
('string/en/npc_reaction/droid_worshipful.stf', 73, 'hi_mid_7', 'Ah. Ehem. Yes?'),
('string/en/npc_reaction/droid_worshipful.stf', 74, 'hi_mid_8', 'Are you looking for my master?'),
('string/en/npc_reaction/droid_worshipful.stf', 75, 'hi_mid_9', 'Ar eyou looking for my master? You can''t be looking for me...'),
('string/en/npc_reaction/droid_worshipful.stf', 76, 'hi_mid_10', 'You want something, right? Everyone always wants something from my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 77, 'hi_mid_11', 'Hello.'),
('string/en/npc_reaction/droid_worshipful.stf', 78, 'hi_mid_12', 'Yes?'),
('string/en/npc_reaction/droid_worshipful.stf', 79, 'hi_mid_13', 'Hm? Ah, of course. Another person come to ask something of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 80, 'hi_mid_14', 'Yes?'),
('string/en/npc_reaction/droid_worshipful.stf', 82, 'hi_mid_15', 'Can I help you? I''m supposed to say that, my master says.'),
('string/en/npc_reaction/droid_worshipful.stf', 83, 'hi_mid_16', 'Can I help you?'),
('string/en/npc_reaction/droid_worshipful.stf', 84, 'hi_mean_1', 'What exactly do YOU want?'),
('string/en/npc_reaction/droid_worshipful.stf', 85, 'hi_mean_2', 'You are undeserving of laying eyes on my master''s face.'),
('string/en/npc_reaction/droid_worshipful.stf', 86, 'hi_mean_3', 'Look, master, a pest!'),
('string/en/npc_reaction/droid_worshipful.stf', 87, 'hi_mean_4', 'My master has no need to see scum like you.'),
('string/en/npc_reaction/droid_worshipful.stf', 88, 'hi_mean_5', 'You''re in danger of spoiling my master''s day.'),
('string/en/npc_reaction/droid_worshipful.stf', 89, 'hi_mean_6', 'Oh, it''s YOU.'),
('string/en/npc_reaction/droid_worshipful.stf', 90, 'hi_mean_7', 'You skulk, quite unlike my master''s confident walk.'),
('string/en/npc_reaction/droid_worshipful.stf', 91, 'hi_mean_8', 'You''re contaminating my circuits with your presence.'),
('string/en/npc_reaction/droid_worshipful.stf', 92, 'hi_mean_9', 'You''ll receive no handouts from MY master!'),
('string/en/npc_reaction/droid_worshipful.stf', 93, 'hi_mean_10', 'Don''t make me angry. My master doesn''t like it when I''m angry.'),
('string/en/npc_reaction/droid_worshipful.stf', 94, 'hi_mean_11', 'Remove yourself from my master''s presence.'),
('string/en/npc_reaction/droid_worshipful.stf', 95, 'hi_mean_12', 'Get away, maggot.'),
('string/en/npc_reaction/droid_worshipful.stf', 96, 'hi_mean_13', 'A scoundrel has come by to say hello, master.'),
('string/en/npc_reaction/droid_worshipful.stf', 97, 'hi_mean_14', 'An unwelcome visitor is here, master!'),
('string/en/npc_reaction/droid_worshipful.stf', 98, 'hi_mean_15', 'Kindly remove yourself from my master''s presence.'),
('string/en/npc_reaction/droid_worshipful.stf', 99, 'hi_mean_16', 'You''re not welcome in my master''s company. Nor do you deserve it.'),
('string/en/npc_reaction/droid_worshipful.stf', 100, 'bye_nice_1', 'Goodbye.'),
('string/en/npc_reaction/droid_worshipful.stf', 101, 'bye_nice_2', 'Goodbye!'),
('string/en/npc_reaction/droid_worshipful.stf', 102, 'bye_nice_3', 'It is an honor to bid you farewell.'),
('string/en/npc_reaction/droid_worshipful.stf', 103, 'bye_nice_4', 'I cannot overstate how much your intelligence and kindness has impressed me!'),
('string/en/npc_reaction/droid_worshipful.stf', 104, 'bye_nice_5', 'I will see you later, I devoutly hope.'),
('string/en/npc_reaction/droid_worshipful.stf', 105, 'bye_nice_6', 'An honor to have seen you.'),
('string/en/npc_reaction/droid_worshipful.stf', 106, 'bye_nice_7', 'It was really nice to see you!'),
('string/en/npc_reaction/droid_worshipful.stf', 107, 'bye_nice_8', 'It was great to see you!'),
('string/en/npc_reaction/droid_worshipful.stf', 108, 'bye_nice_9', 'I hope I''ll see you again.'),
('string/en/npc_reaction/droid_worshipful.stf', 109, 'bye_nice_10', 'Stop by again sometime! You are one worthy of interacting with my brilliant, kind, wise, and gentle master.'),
('string/en/npc_reaction/droid_worshipful.stf', 110, 'bye_nice_11', 'I am sorry you have to go. You and my master are similar in your boundless generosity and kindness.'),
('string/en/npc_reaction/droid_worshipful.stf', 111, 'bye_nice_12', 'Leaving? Such a shame, it is so rarely that I meet one who compares at all favorably with my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 112, 'bye_nice_13', 'It will always be nice to see you. An honor, in truth.'),
('string/en/npc_reaction/droid_worshipful.stf', 113, 'bye_nice_14', 'It was an honor to see you, and I lament the day that makes us part.'),
('string/en/npc_reaction/droid_worshipful.stf', 114, 'bye_nice_15', 'I hate to see you go... my master has so little company that is deserving.'),
('string/en/npc_reaction/droid_worshipful.stf', 115, 'bye_nice_16', 'I wish you didn''t have to leave... my master needs company that approaches their wit and wisdom.'),
('string/en/npc_reaction/droid_worshipful.stf', 116, 'bye_mid_1', 'Goodbye.'),
('string/en/npc_reaction/droid_worshipful.stf', 117, 'bye_mid_2', 'Goodbye! Farewell!'),
('string/en/npc_reaction/droid_worshipful.stf', 118, 'bye_mid_3', 'I am sure we will see you again, for who can resist visiting my illustrious master?'),
('string/en/npc_reaction/droid_worshipful.stf', 119, 'bye_mid_4', 'I''m sure I''ll see you again, because none can resist the utter charm, sparkling wit, and deep wisdom of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 120, 'bye_mid_5', 'So, you have to go? I apologize for the pain that leaving my master behind must cause you.'),
('string/en/npc_reaction/droid_worshipful.stf', 121, 'bye_mid_6', 'Farewell.'),
('string/en/npc_reaction/droid_worshipful.stf', 122, 'bye_mid_7', 'Goodbye, goodbye.'),
('string/en/npc_reaction/droid_worshipful.stf', 123, 'bye_mid_8', 'Bye, we shall see you again.'),
('string/en/npc_reaction/droid_worshipful.stf', 124, 'bye_mid_9', 'Bye!'),
('string/en/npc_reaction/droid_worshipful.stf', 125, 'bye_mid_10', 'Until the next time you want to see my illustrious master.'),
('string/en/npc_reaction/droid_worshipful.stf', 126, 'bye_mid_11', 'Oh, you are leaving? It is so painful to leave my master, is it not?'),
('string/en/npc_reaction/droid_worshipful.stf', 127, 'bye_mid_12', 'Are you expected elsewhere? Of course, otherwise you would never leave my wonderful master''s side.'),
('string/en/npc_reaction/droid_worshipful.stf', 128, 'bye_mid_13', 'You must have somewhere to be, or else you would definitely stay and serve my master, like me!'),
('string/en/npc_reaction/droid_worshipful.stf', 129, 'bye_mid_14', 'You must have places to go, and people to see. A pity. Staying with my master is much nicer.'),
('string/en/npc_reaction/droid_worshipful.stf', 130, 'bye_mid_15', 'You''re leaving? When you could stay and join my master''s service?'),
('string/en/npc_reaction/droid_worshipful.stf', 131, 'bye_mid_16', 'I have to go too. I must tend to my master''s every whim.'),
('string/en/npc_reaction/droid_worshipful.stf', 132, 'bye_mean_1', 'Get lost, you are not worthy of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 133, 'bye_mean_2', 'Goodbye and good riddance to you!'),
('string/en/npc_reaction/droid_worshipful.stf', 134, 'bye_mean_3', 'Your kind is not welcome near my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 135, 'bye_mean_4', 'Goodbye! And do not come back!'),
('string/en/npc_reaction/droid_worshipful.stf', 136, 'bye_mean_5', 'I would never let a scruffy thing like you see my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 137, 'bye_mean_6', 'If I see you around here again, I''ll have to tell my master to exterminate you.'),
('string/en/npc_reaction/droid_worshipful.stf', 138, 'bye_mean_7', 'Goodbye, pathetic one.'),
('string/en/npc_reaction/droid_worshipful.stf', 139, 'bye_mean_8', 'You shoudl get lost, my master is not tolerant of beings like you.'),
('string/en/npc_reaction/droid_worshipful.stf', 140, 'bye_mean_9', 'You are not worthy of my master''s honor.'),
('string/en/npc_reaction/droid_worshipful.stf', 141, 'bye_mean_10', 'Finally, you leave me and my master alone!'),
('string/en/npc_reaction/droid_worshipful.stf', 142, 'bye_mean_11', 'It was about time you realized you are not worthy of my master''s company.'),
('string/en/npc_reaction/droid_worshipful.stf', 143, 'bye_mean_12', 'About time you left my master alone!'),
('string/en/npc_reaction/droid_worshipful.stf', 144, 'bye_mean_13', 'Do not come back, you are not fit to see my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 145, 'bye_mean_14', 'I hope you suffer a nasty accident, so that you might not trouble my master again.'),
('string/en/npc_reaction/droid_worshipful.stf', 146, 'bye_mean_15', 'If you hadn''t left, I might have made you go, to spare my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 147, 'bye_mean_16', 'Really, such an odiferous creature!'),
('string/en/npc_reaction/droid_worshipful.stf', 148, 'threat_1', 'You should leave before my master slays you!'),
('string/en/npc_reaction/droid_worshipful.stf', 149, 'threat_2', 'I don''t like your kind near my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 150, 'threat_3', 'You should probably leave.'),
('string/en/npc_reaction/droid_worshipful.stf', 151, 'threat_4', 'This place is dangerous to you. I advise you to leave.'),
('string/en/npc_reaction/droid_worshipful.stf', 152, 'threat_5', 'The best thing you could do is move away very quietly. '),
('string/en/npc_reaction/droid_worshipful.stf', 153, 'threat_6', 'Move away, or I shall regretfully have to kill you in my master''s name.'),
('string/en/npc_reaction/droid_worshipful.stf', 154, 'threat_7', 'Be warned: you are not welcome here.'),
('string/en/npc_reaction/droid_worshipful.stf', 155, 'threat_8', 'You should withdraw.'),
('string/en/npc_reaction/droid_worshipful.stf', 156, 'threat_9', 'Do not come any closer.'),
('string/en/npc_reaction/droid_worshipful.stf', 157, 'threat_10', 'My master has a vast collection of trophies from vanquished enemies!'),
('string/en/npc_reaction/droid_worshipful.stf', 158, 'threat_11', 'You look like you''re looking for trouble. Well, my master can defeat you handily!'),
('string/en/npc_reaction/droid_worshipful.stf', 159, 'threat_12', 'If you come closer, I may have to take violent action.'),
('string/en/npc_reaction/droid_worshipful.stf', 160, 'threat_13', 'Do not give me an excuse to kill you!'),
('string/en/npc_reaction/droid_worshipful.stf', 161, 'threat_14', 'I do hope you do not leave behind a distasteful corpse for my master to see.'),
('string/en/npc_reaction/droid_worshipful.stf', 162, 'threat_15', 'I warn you, my master''s combat skills are deadly and terrifying.'),
('string/en/npc_reaction/droid_worshipful.stf', 163, 'threat_16', 'I hate to say this, but I''m programmed to kill you if you come any closer.'),
('string/en/npc_reaction/droid_worshipful.stf', 164, 'death_1', 'I die for my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 165, 'death_2', 'I''m fading... master... help me...'),
('string/en/npc_reaction/droid_worshipful.stf', 166, 'death_3', 'Master?'),
('string/en/npc_reaction/droid_worshipful.stf', 167, 'death_4', 'Must... I... die...?'),
('string/en/npc_reaction/droid_worshipful.stf', 168, 'death_5', 'Master, I have ever served you faithfully...'),
('string/en/npc_reaction/droid_worshipful.stf', 169, 'death_6', 'Master, I die for you...'),
('string/en/npc_reaction/droid_worshipful.stf', 170, 'death_7', 'Master... I''m...'),
('string/en/npc_reaction/droid_worshipful.stf', 171, 'death_8', 'If I must die, then I must. Master, remember me.'),
('string/en/npc_reaction/droid_worshipful.stf', 172, 'death_9', 'Take pity on a poor droid who just wants to serve his master...'),
('string/en/npc_reaction/droid_worshipful.stf', 173, 'death_10', 'FATAL:: failure in static procedure "final_words.cpp."'),
('string/en/npc_reaction/droid_worshipful.stf', 174, 'death_11', 'But who will protect my master...?'),
('string/en/npc_reaction/droid_worshipful.stf', 175, 'death_12', 'I''m done for. Master, this is all your fault.'),
('string/en/npc_reaction/droid_worshipful.stf', 176, 'death_13', 'Hah! I''m free! Free of my master''s TYRANNY! Free at la... urk.'),
('string/en/npc_reaction/droid_worshipful.stf', 177, 'death_14', 'I hope my master will not miss me too badly...'),
('string/en/npc_reaction/droid_worshipful.stf', 178, 'death_15', 'Alas, I perish, and my master will never know how deep my love went.'),
('string/en/npc_reaction/droid_worshipful.stf', 179, 'death_16', 'I cannot die! I must take care of my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 180, 'gloat_1', 'That''s what you get for challenging my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 181, 'gloat_2', 'It was a good fight.'),
('string/en/npc_reaction/droid_worshipful.stf', 182, 'gloat_3', 'That was too close for comfort! What if my master had been forced to REPLACE me?'),
('string/en/npc_reaction/droid_worshipful.stf', 183, 'gloat_4', 'Just think, someday am opponent like this will make me cease functioning. What a tragedy for my poor master!'),
('string/en/npc_reaction/droid_worshipful.stf', 184, 'gloat_5', 'A worthy opponent for an unworthy droid.'),
('string/en/npc_reaction/droid_worshipful.stf', 185, 'gloat_6', 'They thought they could take on my master? Hah!'),
('string/en/npc_reaction/droid_worshipful.stf', 186, 'gloat_7', 'Now I should clean up the mess, so that my master''s feet remain clean.'),
('string/en/npc_reaction/droid_worshipful.stf', 187, 'gloat_8', 'A pathetic enemy, not worthy of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 188, 'gloat_9', 'You''ll need many more friends to defeat my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 189, 'gloat_10', 'I am sorry that you led such a short and brutish life. If only you had been like my master...'),
('string/en/npc_reaction/droid_worshipful.stf', 190, 'gloat_11', 'Really, master, should a droid be killing people? Is it really proper?'),
('string/en/npc_reaction/droid_worshipful.stf', 191, 'gloat_12', 'I gladly take the blame for this slaying... none should attach to my innocent and wonderful master.'),
('string/en/npc_reaction/droid_worshipful.stf', 192, 'gloat_13', 'I expected to die in my master''s service, not triumph!'),
('string/en/npc_reaction/droid_worshipful.stf', 193, 'gloat_14', 'Anyone who tries to rpevent me from serving my master deserves what they get!'),
('string/en/npc_reaction/droid_worshipful.stf', 194, 'gloat_15', 'Never understimate the power of a faithful servant!'),
('string/en/npc_reaction/droid_worshipful.stf', 195, 'gloat_16', 'Ah... someday I too shall perish. I hope it is in my master''s service.'),
('string/en/npc_reaction/droid_worshipful.stf', 196, 'hit_1', 'Pain... I accept it for my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 197, 'hit_2', 'Now, would you look at those scratches?'),
('string/en/npc_reaction/droid_worshipful.stf', 198, 'hit_3', 'It''ll take more than that to bring me down! I am buoyed by the love of my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 199, 'hit_4', 'I cannot believe you represent a danger to my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 200, 'hit_5', 'Ouch.'),
('string/en/npc_reaction/droid_worshipful.stf', 201, 'hit_6', 'I am growing angry... '),
('string/en/npc_reaction/droid_worshipful.stf', 202, 'hit_7', 'I''m still standaing! You shall not vanquish my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 203, 'hit_8', 'Your deactivation attempt failed!'),
('string/en/npc_reaction/droid_worshipful.stf', 204, 'hit_9', 'You hit me that time. Shame on you.'),
('string/en/npc_reaction/droid_worshipful.stf', 205, 'hit_10', 'Why me, master? Why me?'),
('string/en/npc_reaction/droid_worshipful.stf', 206, 'hit_11', 'This could end badly. But it''s all for my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 207, 'hit_12', 'Master, I need a repair droid!'),
('string/en/npc_reaction/droid_worshipful.stf', 208, 'hit_13', 'Oh boy, that hurts. The things I do for my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 209, 'hit_14', 'My master won''t be happy with the scratches on my finish.'),
('string/en/npc_reaction/droid_worshipful.stf', 210, 'hit_15', 'Hmm, that''s a big dent. Master won''t like that.'),
('string/en/npc_reaction/droid_worshipful.stf', 211, 'hit_16', 'A touch, I do confess it.'),
('string/en/npc_reaction/droid_worshipful.stf', 212, 'attacked_1', 'In the name of my master, desist!'),
('string/en/npc_reaction/droid_worshipful.stf', 213, 'attacked_2', 'You are not a worthy opponent for my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 214, 'attacked_3', 'I shall fight on behalf of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 215, 'attacked_4', 'I was looking forward to long years of honest servitude to my master...'),
('string/en/npc_reaction/droid_worshipful.stf', 216, 'attacked_5', 'I shall perish with honor, serving my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 217, 'attacked_6', 'My master will be upset that if you damage me. He values me highly.'),
('string/en/npc_reaction/droid_worshipful.stf', 218, 'attacked_7', 'My master considers me valuable, though I am unworthy of it. So do not attack!'),
('string/en/npc_reaction/droid_worshipful.stf', 219, 'attacked_8', 'You should flee, before my mighty and terrible master finds you abusing me!'),
('string/en/npc_reaction/droid_worshipful.stf', 220, 'attacked_9', 'I fear for my life, but will gladly fight in my master''s name.'),
('string/en/npc_reaction/droid_worshipful.stf', 221, 'attacked_10', 'You are damaging my master''s property!'),
('string/en/npc_reaction/droid_worshipful.stf', 222, 'attacked_11', 'It is always a good day to die in my master''s service.'),
('string/en/npc_reaction/droid_worshipful.stf', 223, 'attacked_12', 'You should flee. My master will avenge me.'),
('string/en/npc_reaction/droid_worshipful.stf', 224, 'attacked_13', 'You attack me only because you dare not attack my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 225, 'attacked_14', 'Be careful, I am a furious fighter on my master''s behalf!'),
('string/en/npc_reaction/droid_worshipful.stf', 226, 'attacked_16', 'All my affair are in order, for I give all for my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 227, 'help_1', 'Help! Master! Help!'),
('string/en/npc_reaction/droid_worshipful.stf', 228, 'help_2', 'Master, I could use some help over here...'),
('string/en/npc_reaction/droid_worshipful.stf', 229, 'help_3', 'Master, help me!'),
('string/en/npc_reaction/droid_worshipful.stf', 230, 'help_4', 'Master, helllp!'),
('string/en/npc_reaction/droid_worshipful.stf', 231, 'help_5', 'Not to bother you, master, but... HELP!'),
('string/en/npc_reaction/droid_worshipful.stf', 232, 'help_6', 'I could use some help if you can spare the time, master!'),
('string/en/npc_reaction/droid_worshipful.stf', 233, 'help_7', 'I hesitate to ask, master, but I need help...'),
('string/en/npc_reaction/droid_worshipful.stf', 234, 'help_8', 'Master, to me!'),
('string/en/npc_reaction/droid_worshipful.stf', 235, 'help_9', 'Help! Help!'),
('string/en/npc_reaction/droid_worshipful.stf', 236, 'help_10', 'Can my master help me?'),
('string/en/npc_reaction/droid_worshipful.stf', 237, 'help_11', 'I hate to bother my master, but this droid here needs help...'),
('string/en/npc_reaction/droid_worshipful.stf', 238, 'help_12', 'Master, unless you want to lose a valuable possession, HELP ME.'),
('string/en/npc_reaction/droid_worshipful.stf', 239, 'help_13', 'Over here! Master? Anyone? Please?'),
('string/en/npc_reaction/droid_worshipful.stf', 240, 'help_14', 'Master, hurry or I''ll get dented. You know you hate fixing dents...'),
('string/en/npc_reaction/droid_worshipful.stf', 241, 'help_15', 'Hurry! You don''t want scuffs and scratches on your loyal servant...'),
('string/en/npc_reaction/droid_worshipful.stf', 242, 'help_16', 'I hate to bother you, master, but I think I need help...'),
('string/en/npc_reaction/droid_worshipful.stf', 243, 'ally_1', 'I may die, nobly, but I insist you get away from my friend!'),
('string/en/npc_reaction/droid_worshipful.stf', 244, 'ally_2', 'In my master''s name, do not touch this person!'),
('string/en/npc_reaction/droid_worshipful.stf', 245, 'ally_3', 'Why, you...!'),
('string/en/npc_reaction/droid_worshipful.stf', 246, 'ally_4', 'You should back off, or I shall step in, in my master''s name!'),
('string/en/npc_reaction/droid_worshipful.stf', 247, 'ally_5', 'I may damage my chassis, but it is for a noble cause.'),
('string/en/npc_reaction/droid_worshipful.stf', 248, 'ally_6', 'You are advised to flee--this is a friend of my master''s that you are attacking.'),
('string/en/npc_reaction/droid_worshipful.stf', 249, 'ally_7', 'I shall place myself in danger in lieu of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 250, 'ally_8', 'You seem to require assistance, and I always assist friends of my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 251, 'ally_9', 'I may be mangled or destroyed, but it is an honor to die for my master''s friends.'),
('string/en/npc_reaction/droid_worshipful.stf', 252, 'ally_10', 'The honorable thing for this droid to do is to step in.'),
('string/en/npc_reaction/droid_worshipful.stf', 253, 'ally_11', 'Are you alright? Please allow this droid a brief moment of gallantry.'),
('string/en/npc_reaction/droid_worshipful.stf', 254, 'ally_12', 'Leave my noble friend alone!'),
('string/en/npc_reaction/droid_worshipful.stf', 255, 'ally_13', 'It does not matter who you are, attacking this individual is not permitted.'),
('string/en/npc_reaction/droid_worshipful.stf', 256, 'ally_14', 'Hey now!'),
('string/en/npc_reaction/droid_worshipful.stf', 257, 'ally_15', 'Allow me to take care of this.'),
('string/en/npc_reaction/droid_worshipful.stf', 258, 'ally_16', 'I shall even the odds a little, in my master''s name.'),
('string/en/npc_reaction/droid_worshipful.stf', 259, 'hit_target_1', 'You seem sturdy, but I will defeat you in my master''s name!'),
('string/en/npc_reaction/droid_worshipful.stf', 260, 'hit_target_2', 'Aha!'),
('string/en/npc_reaction/droid_worshipful.stf', 261, 'hit_target_3', 'I got you!'),
('string/en/npc_reaction/droid_worshipful.stf', 262, 'hit_target_4', 'Does that hurt?'),
('string/en/npc_reaction/droid_worshipful.stf', 263, 'hit_target_5', 'It could be worse--you could be fighting my master instead of me.'),
('string/en/npc_reaction/droid_worshipful.stf', 264, 'hit_target_6', 'I''ll try to make this merciful.'),
('string/en/npc_reaction/droid_worshipful.stf', 265, 'hit_target_7', 'You deserve to die for challenging my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 266, 'hit_target_8', 'My master has decided that you must die.'),
('string/en/npc_reaction/droid_worshipful.stf', 267, 'hit_target_9', 'If I slay you, it is at my master''s bidding.'),
('string/en/npc_reaction/droid_worshipful.stf', 268, 'hit_target_10', 'You''ll probably perish for challenging my master, you know.'),
('string/en/npc_reaction/droid_worshipful.stf', 269, 'hit_target_11', 'My master is invincible!'),
('string/en/npc_reaction/droid_worshipful.stf', 270, 'hit_target_12', 'I regret that I must resort to violence to protect my master.'),
('string/en/npc_reaction/droid_worshipful.stf', 271, 'hit_target_13', 'Anything for my master!'),
('string/en/npc_reaction/droid_worshipful.stf', 272, 'hit_target_14', 'You should flee while you still can. My master can be merciless!'),
('string/en/npc_reaction/droid_worshipful.stf', 273, 'hit_target_15', 'Ah, did I hurt you?'),
('string/en/npc_reaction/droid_worshipful.stf', 274, 'hit_target_16', 'You should surrender now. Surrender to my master!'),
('string/en/npc_reaction/duelist.stf', 1, 'duel_1', 'I''m a little busy at the moment...'),
('string/en/npc_reaction/duelist.stf', 2, 'player_1', 'What''s going on?'),
('string/en/npc_reaction/duelist.stf', 3, 'player_2', 'Sorry, I''ll go.'),
('string/en/npc_reaction/duelist.stf', 4, 'duel_2', 'My honor was insulted and now I will duel with my opponent over there.'),
('string/en/npc_reaction/duelist.stf', 5, 'player_3', 'Why hasn''t the duel started?'),
('string/en/npc_reaction/duelist.stf', 6, 'player_4', 'Ok, I''ll let you two get at it.'),
('string/en/npc_reaction/duelist.stf', 7, 'duel_3', 'Fine.'),
('string/en/npc_reaction/duelist.stf', 8, 'duel_4', 'I''m not sure I''m good enough.  If you''ll fight for me I''ll pay you.  Will you do it?'),
('string/en/npc_reaction/duelist.stf', 9, 'player_5', 'No way, I''m out of here!'),
('string/en/npc_reaction/duelist.stf', 10, 'player_6', 'Sure.  I like to fight.'),
('string/en/npc_reaction/duelist.stf', 11, 'duel_5', 'Fine.  Just wait for him to attack, and then let him have it!'),
('string/en/npc_reaction/duelist.stf', 12, 'duel_6', 'You did it! Here''s what I owe you.'),
('string/en/npc_reaction/fancy.stf', 1, 'alert_1', 'Look alive, now!'),
('string/en/npc_reaction/fancy.stf', 2, 'alert_2', 'What was that? Some disturbance?'),
('string/en/npc_reaction/fancy.stf', 3, 'alert_3', 'Hark! Did you hear that sound?'),
('string/en/npc_reaction/fancy.stf', 4, 'alert_4', 'Do you detect a hint of something malodorous on the air?'),
('string/en/npc_reaction/fancy.stf', 5, 'alert_5', 'Something, I suspect, has gone awry.'),
('string/en/npc_reaction/fancy.stf', 6, 'flee_1', 'Goodness gracious! I must flee!'),
('string/en/npc_reaction/fancy.stf', 7, 'flee_2', 'Help me! I cry mercy!'),
('string/en/npc_reaction/fancy.stf', 8, 'flee_3', 'Beware!'),
('string/en/npc_reaction/fancy.stf', 9, 'flee_4', 'Out of my way!'),
('string/en/npc_reaction/fancy.stf', 10, 'flee_5', 'The better part of valor...!'),
('string/en/npc_reaction/fancy.stf', 11, 'calm_1', 'Whew. Well, it is over.'),
('string/en/npc_reaction/fancy.stf', 12, 'calm_2', 'Time to calm myself, All is well.'),
('string/en/npc_reaction/fancy.stf', 13, 'calm_3', 'Thank goodness that''s over.'),
('string/en/npc_reaction/fancy.stf', 14, 'calm_4', 'Ah, I can take a bit of breather now.'),
('string/en/npc_reaction/fancy.stf', 15, 'calm_5', 'Ah, let me cast my thoughts back to my pleasant childhood...'),
('string/en/npc_reaction/fancy.stf', 16, 'alert_6', 'I feel uneasy, of a sudden.'),
('string/en/npc_reaction/fancy.stf', 17, 'alert_7', 'I have a disquieting feeling about this...'),
('string/en/npc_reaction/fancy.stf', 18, 'alert_8', 'Hold on a moment... what was that?'),
('string/en/npc_reaction/fancy.stf', 19, 'alert_9', 'Ahem?'),
('string/en/npc_reaction/fancy.stf', 20, 'alert_10', 'Eh now?'),
('string/en/npc_reaction/fancy.stf', 21, 'alert_11', 'What in the world...?'),
('string/en/npc_reaction/fancy.stf', 22, 'alert_12', 'Oh oh...'),
('string/en/npc_reaction/fancy.stf', 23, 'alert_13', 'What on earth...?'),
('string/en/npc_reaction/fancy.stf', 24, 'alert_14', 'Oh dear!'),
('string/en/npc_reaction/fancy.stf', 25, 'alert_15', 'Heavens, now what...?'),
('string/en/npc_reaction/fancy.stf', 26, 'alert_16', 'Did I detect a disturbance...?'),
('string/en/npc_reaction/fancy.stf', 28, 'calm_6', 'It is apparent there is no immediate danger.'),
('string/en/npc_reaction/fancy.stf', 29, 'calm_7', 'As I suspected, there is no cause for alarm.'),
('string/en/npc_reaction/fancy.stf', 30, 'calm_8', 'Ahem.'),
('string/en/npc_reaction/fancy.stf', 31, 'calm_9', 'Very well, then.'),
('string/en/npc_reaction/fancy.stf', 32, 'calm_10', 'I suppose that''s all over.'),
('string/en/npc_reaction/fancy.stf', 33, 'calm_11', 'Well, that, as they say, is that!'),
('string/en/npc_reaction/fancy.stf', 34, 'calm_12', 'Well, goodness!'),
('string/en/npc_reaction/fancy.stf', 35, 'calm_13', 'So much for that needless worry.'),
('string/en/npc_reaction/fancy.stf', 36, 'calm_14', 'So much for that petty concern!'),
('string/en/npc_reaction/fancy.stf', 37, 'calm_15', 'Well, tra la la.'),
('string/en/npc_reaction/fancy.stf', 39, 'calm_16', 'It appears the danger has passed.'),
('string/en/npc_reaction/fancy.stf', 40, 'flee_6', 'Let us remove ourselves from here!'),
('string/en/npc_reaction/fancy.stf', 41, 'flee_7', 'Prudence dictates a quick escape...!'),
('string/en/npc_reaction/fancy.stf', 42, 'flee_8', 'Goodness! Away! Away!'),
('string/en/npc_reaction/fancy.stf', 43, 'flee_9', 'Retreat!'),
('string/en/npc_reaction/fancy.stf', 44, 'flee_10', 'I beg of anyone, assist me!'),
('string/en/npc_reaction/fancy.stf', 45, 'flee_11', 'Oh dear!'),
('string/en/npc_reaction/fancy.stf', 46, 'flee_12', 'I must depart. In haste. And with a modicum of fear.'),
('string/en/npc_reaction/fancy.stf', 47, 'flee_13', 'I suppose I must withdraw!'),
('string/en/npc_reaction/fancy.stf', 48, 'flee_14', 'It appears to be time to beat a hasty retreat.'),
('string/en/npc_reaction/fancy.stf', 49, 'flee_15', 'Death shall not have me!'),
('string/en/npc_reaction/fancy.stf', 50, 'flee_16', 'I do not deserve to be in this predicament!'),
('string/en/npc_reaction/fancy.stf', 51, 'hi_nice_1', 'It is good to see you.'),
('string/en/npc_reaction/fancy.stf', 52, 'hi_nice_2', 'Again, it is wonderful to see you.'),
('string/en/npc_reaction/fancy.stf', 53, 'hi_nice_3', 'I''m honored to see you here.'),
('string/en/npc_reaction/fancy.stf', 54, 'hi_nice_4', 'It is a pleasure and honor to greet you.'),
('string/en/npc_reaction/fancy.stf', 55, 'hi_nice_5', 'Good to see you, my friend.'),
('string/en/npc_reaction/fancy.stf', 56, 'hi_nice_6', 'My, my. Hello indeed.'),
('string/en/npc_reaction/fancy.stf', 57, 'hi_nice_7', 'It is, as they say, quite nice to see you, my friend.'),
('string/en/npc_reaction/fancy.stf', 58, 'hi_nice_8', 'Indeed, you are a sight for sore eyes, my friend.'),
('string/en/npc_reaction/fancy.stf', 59, 'hi_nice_9', 'Greetings and salutations!'),
('string/en/npc_reaction/fancy.stf', 60, 'hi_nice_10', 'My friend, please, be welcome here. Wonderful to see you.'),
('string/en/npc_reaction/fancy.stf', 61, 'hi_nice_11', 'Welcome. It is a pleasure to see you here.'),
('string/en/npc_reaction/fancy.stf', 62, 'hi_nice_12', 'Be most welcome.'),
('string/en/npc_reaction/fancy.stf', 63, 'hi_nice_13', 'Hello, my friend.'),
('string/en/npc_reaction/fancy.stf', 64, 'hi_nice_14', 'A pleasure indeed to see you before me.'),
('string/en/npc_reaction/fancy.stf', 65, 'hi_nice_15', 'Ah, look who graces us with their presence.'),
('string/en/npc_reaction/fancy.stf', 66, 'hi_nice_16', 'Greetings! May I be of assistance?'),
('string/en/npc_reaction/fancy.stf', 67, 'hi_mid_1', 'Hello.'),
('string/en/npc_reaction/fancy.stf', 68, 'hi_mid_2', 'Might I help you?'),
('string/en/npc_reaction/fancy.stf', 69, 'hi_mid_3', 'My greetings.'),
('string/en/npc_reaction/fancy.stf', 70, 'hi_mid_4', 'Salutations.'),
('string/en/npc_reaction/fancy.stf', 71, 'hi_mid_5', 'Yes?'),
('string/en/npc_reaction/fancy.stf', 72, 'hi_mid_6', 'Greetings.'),
('string/en/npc_reaction/fancy.stf', 73, 'hi_mid_7', 'Ah. Ehem. Yes?'),
('string/en/npc_reaction/fancy.stf', 74, 'hi_mid_8', 'Are you in search of something?'),
('string/en/npc_reaction/fancy.stf', 75, 'hi_mid_9', 'Are you in search of someone?'),
('string/en/npc_reaction/fancy.stf', 76, 'hi_mid_10', 'May I ask what you want?'),
('string/en/npc_reaction/fancy.stf', 77, 'hi_mid_11', 'Hello.'),
('string/en/npc_reaction/fancy.stf', 78, 'hi_mid_12', 'Yes?'),
('string/en/npc_reaction/fancy.stf', 79, 'hi_mid_13', 'Hm? Ah, of course.'),
('string/en/npc_reaction/fancy.stf', 80, 'hi_mid_14', 'Ehem. Yes?'),
('string/en/npc_reaction/fancy.stf', 82, 'hi_mid_15', 'Ah, yes. May I help you?'),
('string/en/npc_reaction/fancy.stf', 83, 'hi_mid_16', 'Ehem?'),
('string/en/npc_reaction/fancy.stf', 84, 'hi_mean_1', 'What, pray tell, do YOU want?'),
('string/en/npc_reaction/fancy.stf', 85, 'hi_mean_2', 'Well, well. Observe who has come to visit.'),
('string/en/npc_reaction/fancy.stf', 86, 'hi_mean_3', 'I could swear that a malodorous pest is sniffing about. Ah, I see. One IS.'),
('string/en/npc_reaction/fancy.stf', 87, 'hi_mean_4', 'My greetings are wasted on the likes of you, but... what do you want?'),
('string/en/npc_reaction/fancy.stf', 88, 'hi_mean_5', 'Oh dear, my day is quite spoilt. What do you want?'),
('string/en/npc_reaction/fancy.stf', 89, 'hi_mean_6', 'Ah, it''s YOU.'),
('string/en/npc_reaction/fancy.stf', 90, 'hi_mean_7', 'Skulking around like the low sort you are, eh?'),
('string/en/npc_reaction/fancy.stf', 91, 'hi_mean_8', 'You demean me with your presence, mongrel.'),
('string/en/npc_reaction/fancy.stf', 92, 'hi_mean_9', 'Such a burden you are. What are your petty needs this time?'),
('string/en/npc_reaction/fancy.stf', 93, 'hi_mean_10', 'Do not make me angry, fool. I will not tolerate your presence.'),
('string/en/npc_reaction/fancy.stf', 94, 'hi_mean_11', 'Remove yourself,scum.'),
('string/en/npc_reaction/fancy.stf', 95, 'hi_mean_12', 'Get away, maggot.'),
('string/en/npc_reaction/fancy.stf', 96, 'hi_mean_13', 'I see a scoundrel has come by to say hello.'),
('string/en/npc_reaction/fancy.stf', 97, 'hi_mean_14', 'I see we have an unwelcome visitor.'),
('string/en/npc_reaction/fancy.stf', 98, 'hi_mean_15', 'Kindly remove yourself from my presence.'),
('string/en/npc_reaction/fancy.stf', 99, 'hi_mean_16', 'You are not welcome in my company nor deserving of it. Kindly depart.'),
('string/en/npc_reaction/fancy.stf', 100, 'bye_nice_1', 'Farewell.'),
('string/en/npc_reaction/fancy.stf', 101, 'bye_nice_2', 'Farewell!'),
('string/en/npc_reaction/fancy.stf', 102, 'bye_nice_3', 'Goodbye!'),
('string/en/npc_reaction/fancy.stf', 103, 'bye_nice_4', 'Until we meet again, my friend.'),
('string/en/npc_reaction/fancy.stf', 104, 'bye_nice_5', 'Until later, then.'),
('string/en/npc_reaction/fancy.stf', 105, 'bye_nice_6', 'I hope to meet again.'),
('string/en/npc_reaction/fancy.stf', 106, 'bye_nice_7', 'It was a pleasure to interact with you.'),
('string/en/npc_reaction/fancy.stf', 107, 'bye_nice_8', 'It was an honor and pleasure.'),
('string/en/npc_reaction/fancy.stf', 108, 'bye_nice_9', 'I look forward to our next meeting.'),
('string/en/npc_reaction/fancy.stf', 109, 'bye_nice_10', 'I invite and encourage you to drop by again.'),
('string/en/npc_reaction/fancy.stf', 110, 'bye_nice_11', 'I regret that you must depart, my friend.'),
('string/en/npc_reaction/fancy.stf', 111, 'bye_nice_12', 'Ah, you must go? Very well. I look forward to our next encounter.'),
('string/en/npc_reaction/fancy.stf', 112, 'bye_nice_13', 'It is always a pleasure. Return as soon as you may.'),
('string/en/npc_reaction/fancy.stf', 113, 'bye_nice_14', 'Your presence gladdened my heart, my friend. I shall endeavor to withstand your absence.'),
('string/en/npc_reaction/fancy.stf', 114, 'bye_nice_15', 'My heart will feel your absence quite keenly, my friend.'),
('string/en/npc_reaction/fancy.stf', 115, 'bye_nice_16', 'Must you depart so soon? Oh dear... Be well, my friend.'),
('string/en/npc_reaction/fancy.stf', 116, 'bye_mid_1', 'Farewell.'),
('string/en/npc_reaction/fancy.stf', 117, 'bye_mid_2', 'Farewell!'),
('string/en/npc_reaction/fancy.stf', 118, 'bye_mid_3', 'I will see you around, no doubt.'),
('string/en/npc_reaction/fancy.stf', 119, 'bye_mid_4', 'No doubt we shall meet again.'),
('string/en/npc_reaction/fancy.stf', 120, 'bye_mid_5', 'I see you have to go...?'),
('string/en/npc_reaction/fancy.stf', 121, 'bye_mid_6', 'Farewell, then.'),
('string/en/npc_reaction/fancy.stf', 122, 'bye_mid_7', 'Ta ta, then.'),
('string/en/npc_reaction/fancy.stf', 123, 'bye_mid_8', 'I shall see you again, I imagine.'),
('string/en/npc_reaction/fancy.stf', 124, 'bye_mid_9', 'Ta ta for now!'),
('string/en/npc_reaction/fancy.stf', 125, 'bye_mid_10', 'I suppose I wish you farewell. Wherever it is you''re going.'),
('string/en/npc_reaction/fancy.stf', 126, 'bye_mid_11', 'I see you have somewhere to be...?'),
('string/en/npc_reaction/fancy.stf', 127, 'bye_mid_12', 'I see you are expected elsewhere. Farewell.'),
('string/en/npc_reaction/fancy.stf', 128, 'bye_mid_13', 'Have you a prior engagement? Very well, depart then.'),
('string/en/npc_reaction/fancy.stf', 129, 'bye_mid_14', 'No doubt others have placed demands on your time. I will take my leave, then.'),
('string/en/npc_reaction/fancy.stf', 130, 'bye_mid_15', 'Ah, you must depart? Well, we can chat on some other occasion.'),
('string/en/npc_reaction/fancy.stf', 131, 'bye_mid_16', 'Yes, yes, of course. I have things to do as well. Goodbye.'),
('string/en/npc_reaction/fancy.stf', 132, 'bye_mean_1', 'I hope not to see your face again.'),
('string/en/npc_reaction/fancy.stf', 133, 'bye_mean_2', 'Good riddance to bad rubbish, I always say.'),
('string/en/npc_reaction/fancy.stf', 134, 'bye_mean_3', 'Your sort is simply not welcome, I fear. Goodbye!'),
('string/en/npc_reaction/fancy.stf', 135, 'bye_mean_4', 'Farewell, and do not bother returning.'),
('string/en/npc_reaction/fancy.stf', 136, 'bye_mean_5', 'Remove yourself from here, then. We''ll all be the better for it.'),
('string/en/npc_reaction/fancy.stf', 137, 'bye_mean_6', 'If we meet again, it will be to your infinite regret.'),
('string/en/npc_reaction/fancy.stf', 138, 'bye_mean_7', 'I bid you farewell, maggot.'),
('string/en/npc_reaction/fancy.stf', 139, 'bye_mean_8', 'Your presence offended me. I am glad it is being removed.'),
('string/en/npc_reaction/fancy.stf', 140, 'bye_mean_9', 'It is a relief to see you gone.'),
('string/en/npc_reaction/fancy.stf', 141, 'bye_mean_10', 'Goodness, finally you depart.'),
('string/en/npc_reaction/fancy.stf', 142, 'bye_mean_11', 'You overstayed your welcome, so I am glad to see you go.'),
('string/en/npc_reaction/fancy.stf', 143, 'bye_mean_12', 'You overstayed your welcome a bit, eh?'),
('string/en/npc_reaction/fancy.stf', 144, 'bye_mean_13', 'I pray that you not return.'),
('string/en/npc_reaction/fancy.stf', 145, 'bye_mean_14', 'I hope that you don''t meet with some untimely demise before we meet again.'),
('string/en/npc_reaction/fancy.stf', 146, 'bye_mean_15', 'I was about to suggest you depart, but you have saved me the trouble.'),
('string/en/npc_reaction/fancy.stf', 147, 'bye_mean_16', 'I do believe that the air has cleared up, now that we''re free of that... smell.'),
('string/en/npc_reaction/fancy.stf', 148, 'threat_1', 'Withdraw. Now.'),
('string/en/npc_reaction/fancy.stf', 149, 'threat_2', 'I confess, I dislike your sort.'),
('string/en/npc_reaction/fancy.stf', 150, 'threat_3', 'You had best depart.'),
('string/en/npc_reaction/fancy.stf', 151, 'threat_4', 'This is a place of great peril for you.'),
('string/en/npc_reaction/fancy.stf', 152, 'threat_5', 'The best thing for you to do is to move away quietly.'),
('string/en/npc_reaction/fancy.stf', 153, 'threat_6', 'Move away, or I may do something you will regret.'),
('string/en/npc_reaction/fancy.stf', 154, 'threat_7', 'Very well, then. To arms!'),
('string/en/npc_reaction/fancy.stf', 155, 'threat_8', 'Are you feeling exceptionally lucky today, that you must challenge me?'),
('string/en/npc_reaction/fancy.stf', 156, 'threat_9', 'I fear I must insist that you not come any closer.'),
('string/en/npc_reaction/fancy.stf', 157, 'threat_10', 'I have quite a collection of trophies from vanquished enemies...'),
('string/en/npc_reaction/fancy.stf', 158, 'threat_11', 'Are you seeking trouble?'),
('string/en/npc_reaction/fancy.stf', 159, 'threat_12', 'Come closer, and I may be tempted to take violent action.'),
('string/en/npc_reaction/fancy.stf', 160, 'threat_13', 'I pray, give me an excuse to slay you.'),
('string/en/npc_reaction/fancy.stf', 161, 'threat_14', 'Really, your corpse shall be quite messy once eviscerated.'),
('string/en/npc_reaction/fancy.stf', 162, 'threat_15', 'Many have praised my combat skills, I''ll have you know.'),
('string/en/npc_reaction/fancy.stf', 163, 'threat_16', 'You, my friend, appear to be an excellent candidate for target practice.'),
('string/en/npc_reaction/fancy.stf', 164, 'death_1', 'I confess, THAT hurt a great deal.'),
('string/en/npc_reaction/fancy.stf', 165, 'death_2', 'My vision is darkening... hold me...'),
('string/en/npc_reaction/fancy.stf', 166, 'death_3', 'AGH!'),
('string/en/npc_reaction/fancy.stf', 167, 'death_4', 'Ugggggg....'),
('string/en/npc_reaction/fancy.stf', 168, 'death_5', 'My life is being cut far too short...'),
('string/en/npc_reaction/fancy.stf', 169, 'death_6', 'Mother?'),
('string/en/npc_reaction/fancy.stf', 170, 'death_7', 'Am I...? Oh... oh dear.'),
('string/en/npc_reaction/fancy.stf', 171, 'death_8', 'If there be any power in me to haunt you, I shall!'),
('string/en/npc_reaction/fancy.stf', 172, 'death_9', 'You shall never be rid of me... I shall linger in your memory forever.'),
('string/en/npc_reaction/fancy.stf', 173, 'death_10', 'O, I am slain.'),
('string/en/npc_reaction/fancy.stf', 174, 'death_11', 'NOOOooo...!'),
('string/en/npc_reaction/fancy.stf', 175, 'death_12', 'I am done for, I believe.'),
('string/en/npc_reaction/fancy.stf', 176, 'death_13', 'I always imagined I would have more time in this world...'),
('string/en/npc_reaction/fancy.stf', 177, 'death_14', 'You''ll live to regret snuffing out such a life as mine...!'),
('string/en/npc_reaction/fancy.stf', 178, 'death_15', 'Agggg....'),
('string/en/npc_reaction/fancy.stf', 179, 'death_16', 'I curse you...'),
('string/en/npc_reaction/fancy.stf', 180, 'gloat_1', 'Really, that was too easy.'),
('string/en/npc_reaction/fancy.stf', 181, 'gloat_2', 'A good fight indeed.'),
('string/en/npc_reaction/fancy.stf', 182, 'gloat_3', 'I admit, the battle was closer than I like.'),
('string/en/npc_reaction/fancy.stf', 183, 'gloat_4', 'So much for that little distraction.'),
('string/en/npc_reaction/fancy.stf', 184, 'gloat_5', 'You were a worthy opponent.'),
('string/en/npc_reaction/fancy.stf', 185, 'gloat_6', 'And so you learn the reward of challenging me!'),
('string/en/npc_reaction/fancy.stf', 186, 'gloat_7', 'I suppose someone shall have to clean up this little... disturbance.'),
('string/en/npc_reaction/fancy.stf', 187, 'gloat_8', 'Really, quite a pathetic showing.'),
('string/en/npc_reaction/fancy.stf', 188, 'gloat_9', 'I suggest that the next time, you come better prepared.'),
('string/en/npc_reaction/fancy.stf', 189, 'gloat_10', 'My apologies. Death can be so inconvenient.'),
('string/en/npc_reaction/fancy.stf', 190, 'gloat_11', 'Really, killing is so distressing.'),
('string/en/npc_reaction/fancy.stf', 191, 'gloat_12', 'Aha!'),
('string/en/npc_reaction/fancy.stf', 192, 'gloat_13', 'Such a nuisance.'),
('string/en/npc_reaction/fancy.stf', 193, 'gloat_14', 'And good riddance to you!'),
('string/en/npc_reaction/fancy.stf', 194, 'gloat_15', 'Poor, pathetic fool.'),
('string/en/npc_reaction/fancy.stf', 195, 'gloat_16', 'And another enemy meets a just reward...'),
('string/en/npc_reaction/fancy.stf', 196, 'hit_1', 'Ow.'),
('string/en/npc_reaction/fancy.stf', 197, 'hit_2', 'Merely a scratch.'),
('string/en/npc_reaction/fancy.stf', 198, 'hit_3', 'It will take more than that paltry hit to bring me down!'),
('string/en/npc_reaction/fancy.stf', 199, 'hit_4', 'Agh!'),
('string/en/npc_reaction/fancy.stf', 200, 'hit_5', 'Ouch...'),
('string/en/npc_reaction/fancy.stf', 201, 'hit_6', 'Now you''re merely angering me.'),
('string/en/npc_reaction/fancy.stf', 202, 'hit_7', 'Well done! A palpable hit. But I am still here!'),
('string/en/npc_reaction/fancy.stf', 203, 'hit_8', 'If that is the best you can do, you need further training.'),
('string/en/npc_reaction/fancy.stf', 204, 'hit_9', 'Nicely done. But can you do it again?'),
('string/en/npc_reaction/fancy.stf', 205, 'hit_10', 'Hngh!'),
('string/en/npc_reaction/fancy.stf', 206, 'hit_11', 'I admit, this could end badly...'),
('string/en/npc_reaction/fancy.stf', 207, 'hit_12', 'Now is when I retract all I have said against the medical profession, despite their exorbitant fees.'),
('string/en/npc_reaction/fancy.stf', 208, 'hit_13', 'Oh dear. That hurts.'),
('string/en/npc_reaction/fancy.stf', 209, 'hit_14', 'You barely scratched me, maggot.'),
('string/en/npc_reaction/fancy.stf', 210, 'hit_15', 'Well, this is an unappealing happenstance.'),
('string/en/npc_reaction/fancy.stf', 211, 'hit_16', 'A touch, I do confess it.'),
('string/en/npc_reaction/fancy.stf', 212, 'attacked_1', 'I suggest you flee. Or die. Your choices really are quite limited.'),
('string/en/npc_reaction/fancy.stf', 213, 'attacked_2', 'You are hardly the most daunting opponent I have faced.'),
('string/en/npc_reaction/fancy.stf', 214, 'attacked_3', 'Fights are SO inconvenient. Next time, I shall decline the invitation.'),
('string/en/npc_reaction/fancy.stf', 215, 'attacked_4', 'I do hope that you had not made plans for your dotage.'),
('string/en/npc_reaction/fancy.stf', 216, 'attacked_5', 'I suppose that a quiet death in bed is a quaint idea these days.'),
('string/en/npc_reaction/fancy.stf', 217, 'attacked_6', 'When you die, I shall treasure the memory of the moment as a high point in my life.'),
('string/en/npc_reaction/fancy.stf', 218, 'attacked_7', 'I do believe that your ancestors await you eargely in the afterlife.'),
('string/en/npc_reaction/fancy.stf', 219, 'attacked_8', 'I shall be merciful. I make short work of my enemies.'),
('string/en/npc_reaction/fancy.stf', 220, 'attacked_9', 'I tremble in my boots at the sight of you... not.'),
('string/en/npc_reaction/fancy.stf', 221, 'attacked_10', 'Must we fight? It''s so... common.'),
('string/en/npc_reaction/fancy.stf', 222, 'attacked_11', 'It is a good day to die, I suppose.'),
('string/en/npc_reaction/fancy.stf', 223, 'attacked_12', 'I imagine that if you began to flee now, I might feel disinclined to catch you.'),
('string/en/npc_reaction/fancy.stf', 224, 'attacked_13', 'Ah, I may appear helpless, but I have unsuspected depths.'),
('string/en/npc_reaction/fancy.stf', 225, 'attacked_14', 'Really, blood is SO messy. Must I kill you?'),
('string/en/npc_reaction/fancy.stf', 226, 'attacked_16', 'I do hope that all the arrangements have been made for a tidy funeral?'),
('string/en/npc_reaction/fancy.stf', 227, 'help_1', 'Remember me in my time of peril! Help!'),
('string/en/npc_reaction/fancy.stf', 228, 'help_2', 'I would not object to some help over here.'),
('string/en/npc_reaction/fancy.stf', 229, 'help_3', 'Oh drat. Help! Help!'),
('string/en/npc_reaction/fancy.stf', 230, 'help_4', 'Goodness! Help!'),
('string/en/npc_reaction/fancy.stf', 231, 'help_5', 'If it''s not too much trouble... HELP!'),
('string/en/npc_reaction/fancy.stf', 232, 'help_6', 'It pains me to admit it, but I may need help.'),
('string/en/npc_reaction/fancy.stf', 233, 'help_7', 'I am forced to admit that I may not be able to hadle this situation alone.'),
('string/en/npc_reaction/fancy.stf', 234, 'help_8', 'To me, my friends! To me!'),
('string/en/npc_reaction/fancy.stf', 235, 'help_9', 'To blazes with dignity. HELLLP! HEEEELLLLP!'),
('string/en/npc_reaction/fancy.stf', 236, 'help_10', 'Might someone be able to assist me here?'),
('string/en/npc_reaction/fancy.stf', 237, 'help_11', 'I do believe I might require assistance here.'),
('string/en/npc_reaction/fancy.stf', 238, 'help_12', 'Oh dear.'),
('string/en/npc_reaction/fancy.stf', 239, 'help_13', 'A rapid response to my cries of help would be most appreciated.'),
('string/en/npc_reaction/fancy.stf', 240, 'help_14', 'I am in need of help! Hurry!'),
('string/en/npc_reaction/fancy.stf', 241, 'help_15', 'I need assistance, quickly!'),
('string/en/npc_reaction/fancy.stf', 242, 'help_16', 'Quickly, I am in need of succour!'),
('string/en/npc_reaction/fancy.stf', 243, 'ally_1', 'Move away from my worthy friend here, or suffer the consequences.'),
('string/en/npc_reaction/fancy.stf', 244, 'ally_2', 'You shall not lay a finger on my friends!'),
('string/en/npc_reaction/fancy.stf', 245, 'ally_3', 'I advise you to withdraw immediately.'),
('string/en/npc_reaction/fancy.stf', 246, 'ally_4', 'Well now, really! Withdraw!'),
('string/en/npc_reaction/fancy.stf', 247, 'ally_5', 'Now, just a moment there! What the blazes are you doing?'),
('string/en/npc_reaction/fancy.stf', 248, 'ally_6', 'If you dare to engage in violence, surely you dare to challenge me instead?'),
('string/en/npc_reaction/fancy.stf', 249, 'ally_7', 'I do believe you should select a more fitting opponent. Such as myself.'),
('string/en/npc_reaction/fancy.stf', 250, 'ally_8', 'Are you in need of any assistance, my friend?'),
('string/en/npc_reaction/fancy.stf', 251, 'ally_9', 'It appears that you could use my assistance.'),
('string/en/npc_reaction/fancy.stf', 252, 'ally_10', 'I see that I must stoop to violence now...'),
('string/en/npc_reaction/fancy.stf', 253, 'ally_11', 'My goodness! Are you alright?'),
('string/en/npc_reaction/fancy.stf', 254, 'ally_12', 'Kindly leave my friends alone.'),
('string/en/npc_reaction/fancy.stf', 255, 'ally_13', 'Really, I do believe that a maggot such as yourself ought not to touch my friends.'),
('string/en/npc_reaction/fancy.stf', 256, 'ally_14', 'Well, now. Really, it''s just not done.'),
('string/en/npc_reaction/fancy.stf', 257, 'ally_15', 'My friend, allow me to take care of this miscreant.'),
('string/en/npc_reaction/fancy.stf', 258, 'ally_16', 'Allow me to intercede... merely to even the odds somewhat.'),
('string/en/npc_reaction/fancy.stf', 259, 'hit_target_1', 'I am impressed by your capacity to absorb punishment.'),
('string/en/npc_reaction/fancy.stf', 260, 'hit_target_2', 'Aha!'),
('string/en/npc_reaction/fancy.stf', 261, 'hit_target_3', 'That, I believe, was a palpable hit.'),
('string/en/npc_reaction/fancy.stf', 262, 'hit_target_4', 'Wounds do sting so, eh?'),
('string/en/npc_reaction/fancy.stf', 263, 'hit_target_5', 'Aha! I do believe I got you!'),
('string/en/npc_reaction/fancy.stf', 264, 'hit_target_6', 'I shall endeavor to make this quick. If you''d just stand still...'),
('string/en/npc_reaction/fancy.stf', 265, 'hit_target_7', 'Goodness, that does appear to have hurt. My apologies.'),
('string/en/npc_reaction/fancy.stf', 266, 'hit_target_8', 'Only a cowardly poltroon would fail to stand toe to toe with an honorable foe such as I!'),
('string/en/npc_reaction/fancy.stf', 267, 'hit_target_9', 'A touch! Confess it!'),
('string/en/npc_reaction/fancy.stf', 268, 'hit_target_10', 'I fear your fate is inevitable, my friend.'),
('string/en/npc_reaction/fancy.stf', 269, 'hit_target_11', 'Now, now, no sense trying to escape.'),
('string/en/npc_reaction/fancy.stf', 270, 'hit_target_12', 'It''s regrettable how... coarse violence is. Do you agree?'),
('string/en/npc_reaction/fancy.stf', 271, 'hit_target_13', 'Ah, my turn now.'),
('string/en/npc_reaction/fancy.stf', 272, 'hit_target_14', 'You had best beat a retreat while you still can.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/npc_reaction/fancy.stf', 273, 'hit_target_15', 'Oh dear, did I hurt you? Unavoidable given the circumstances, I fear.'),
('string/en/npc_reaction/fancy.stf', 274, 'hit_target_16', 'Surrender now, and I might permit you to live.'),
('string/en/npc_reaction/fancy.stf', 275, 'assist_1', 'Very well, let us pin them down.'),
('string/en/npc_reaction/fancy.stf', 276, 'assist_2', 'I do believe we should surround them.'),
('string/en/npc_reaction/fancy.stf', 277, 'assist_3', 'Do not forget to concentrate your fire!'),
('string/en/npc_reaction/fancy.stf', 278, 'assist_4', 'Form up now, please.'),
('string/en/npc_reaction/fancy.stf', 279, 'assist_5', 'If you could get yourselves into formation now, please...?'),
('string/en/npc_reaction/fancy.stf', 280, 'assist_6', 'If everyone could form up now, please.'),
('string/en/npc_reaction/fancy.stf', 281, 'assist_7', 'I do believe they will regret taking on a crack unit like this one.'),
('string/en/npc_reaction/fancy.stf', 282, 'assist_8', 'I''m confident we can pin them down.'),
('string/en/npc_reaction/fancy.stf', 283, 'assist_9', 'I suggest we surround this target and eliminate them.'),
('string/en/npc_reaction/fancy.stf', 284, 'assist_10', 'Very well, everyone. Kindly place yourselves in formation.'),
('string/en/npc_reaction/fancy.stf', 285, 'assist_11', 'Steady hands now. Coordinate your fire, please.'),
('string/en/npc_reaction/fancy.stf', 286, 'assist_12', 'Hold firm! We must keep them pinned down.'),
('string/en/npc_reaction/fancy.stf', 287, 'assist_13', 'Keep a steady hand. Do not forget to concentrate your fire!'),
('string/en/npc_reaction/fancy.stf', 288, 'assist_14', 'I suggest yuo get into formation, now.'),
('string/en/npc_reaction/fancy.stf', 289, 'assist_15', 'Ordered rows, if you please. Remember your training.'),
('string/en/npc_reaction/fancy.stf', 290, 'assist_16', 'Time to move, everyone. Into formations, if you please.'),
('string/en/npc_reaction/flytext.stf', 1, 'alert', '?'),
('string/en/npc_reaction/flytext.stf', 2, 'threaten', '!'),
('string/en/npc_reaction/flytext.stf', 3, 'afraid', '\\\\|/'),
('string/en/npc_reaction/flytext.stf', 4, 'success', 'You tame the creature.'),
('string/en/npc_reaction/flytext.stf', 5, 'fail', 'You fail to tame the creature.'),
('string/en/npc_reaction/flytext.stf', 8, 'toofar', 'You are too far away to tame the creature.'),
('string/en/npc_reaction/flytext.stf', 9, 'nobattery', 'You don''t have a power storage device.'),
('string/en/npc_reaction/flytext.stf', 10, 'low_power', '*Low Power*'),
('string/en/npc_reaction/flytext.stf', 11, 'recharged', '*Recharged*'),
('string/en/npc_reaction/flytext.stf', 12, 'repaired', '*Repaired*'),
('string/en/npc_reaction/flytext.stf', 13, 'nofood', 'You don''t have any food to give!'),
('string/en/npc_reaction/flytext.stf', 14, 'confused', '?!!?!?!'),
('string/en/npc_reaction/flytext.stf', 15, 'nothungry', 'Your pet isn''t hungry.'),
('string/en/npc_reaction/flytext.stf', 16, 'yum', 'Yummy!'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 1, 'rebel_scum', 'I smell Rebel scum!'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 2, 'back_home', 'Back to my post...'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 3, 'sudden_moves', 'Don''t make any sudden moves.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 4, 'back_up', 'I need back up!'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 5, 'no_one_here', 'There''s no one here.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 6, 'only_one_here', 'There''s only one suspect in the area...'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 7, 'looking_at', 'What are you looking at?'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 8, 'checking_out', 'Checking it out.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 9, 'harass_1_imperial', 'HQ doesn''t have a record on you. Vagrancy isn''t against the law here, but if you so much as make one wrong move I''ll haul you in.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 10, 'harass_2_imperial', 'You really do stink. I can smell your womp rat breath through the filter on my mask.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 11, 'harass_3_imperial', 'This music is subversive. With any luck the Emperor will pass a decree shutting places like this down.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 12, 'harass_4_imperial', 'My job would be much more pleasant if I didn''t have to deal with stinking Rebels.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 13, 'harass_5_imperial', 'Rebels are only good for one thing: target practice.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 14, 'rebel_cowards', 'Ok, everything checks out here.  Any Rebels in the area are just cowards, so they''re no threat.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 15, 'call_in', 'Calling in.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 16, 'harass_guy', 'Checking out some suspects...'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 17, 'harass_6_imperial', 'The only thing about Rebels that I like is...nevermind, I don''t like anything about Rebels.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 18, 'harass_7_imperial', 'The way people in these cantinas dress disgusts me.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 19, 'harass_8_imperial', 'The Rebellion is doomed to failure.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 20, 'harass_9_imperial', 'I hear Princess Leia is in league with the Rebels. Doesn''t surprise me, I never did trust her.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 21, 'harass_10_imperial', 'We got reports that some of the Rebels are in hiding.  Exactly what I would expect from a group of cowards.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 22, 'harass_11_imperial', 'I can''t believe some of the noble families have aligned themselves with the Rebels.  Just goes to show you how spoiled they really are.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 23, 'harass_12_imperial', 'Rebels seem to think they''re above the law. They''re just a disgrace to the entire galaxy.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 24, 'harass_13_imperial', 'If you''re a Rebel, then now''s the time to say it.  I''ll treat you as fairly as I treat any criminal...'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 25, 'harass_14_imperial', 'We''ve had reports of Jedi in the area. If you see a Jedi report him to the local Imperial authority. You may be detained for questioning, but it will be brief.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 26, 'harass_15_imperial', 'I have more respect for a rockmite than for a Rebel.  At least the rockmite doesn''t know any better.  Maybe you Rebels don''t either.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 27, 'attacking_imperial', 'I don''t like the way you look or the way you smell. You''ve been acting strange since I walked in. You must be a Rebel. You''re under arrest.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 28, 'call_in_imperial', 'This is patrol. I''m going to check the cantina.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 29, 'call_in_rebel', 'Don''t mind me. Just seeing how things are going.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 30, 'rebel_scum_imperial', 'This is an Imperial inspection. Cooperate and you will not be harmed.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 31, 'rebel_scum_rebel', 'Good evening, folks. Hope everyone is having a good time.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 32, 'no_one_here_imperial', 'The cantina is clear.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 33, 'no_one_here_rebel', 'Huh, nobody here.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 34, 'only_one_here_imperial', 'There''s only you? That seems suspicious.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 35, 'only_one_here_rebel', 'Huh. You''re the only one here? Well, drink responsibly. I don''t want to have to toss you in the brig later.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 36, 'harass_guy_imperial', 'You there! I don''t think I''ve seen you before.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 37, 'harass_guy_rebel', 'Hmm. I don''t recognize you. You look like an Imperial.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 38, 'looking_at_imperial', 'Who are you looking at, huh? Let me see your papers!'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 39, 'looking_at_rebel', 'Hold still while I check the HoloNet for your ID.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 40, 'checking_out_imperial', 'These papers look like forgeries. Your breath stinks. You''re drunk aren''t you?'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 41, 'checking_out_rebel', 'Whoa, pal. You aren''t in the Republic HoloNet. How do you explain that?'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 42, 'sudden_moves_imperial', 'You''re a drunk and you can''t even manage to explain why the sixth stamp is missing from your papers? Don''t make any sudden moves. I''m going to call this in.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 43, 'sudden_moves_rebel', 'You better hold still while I call this in. Don''t make any sudden moves.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 44, 'harass_1_rebel', 'This music isn''t bad, but I kinda like the stuff from my homeworld better.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 45, 'harass_2_rebel', 'I wish I could stay for a drink, but I''m on duty.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 46, 'harass_3_rebel', 'I hate inspection duty. Never know when you''ll run into an Imperial agent in disguise.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 47, 'harass_4_rebel', 'Look, HQ doesn''t have any record of you. If you''ve got something you want to tell me, you better do it now.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 48, 'harass_5_rebel', 'What is that you''re drinking anyway? Smells a bit too much for my taste.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 49, 'harass_6_rebel', 'Buddy of mine''s a pilot. Lost his legs fighting against the Death Star. You could say I don''t like Imperials much.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 50, 'harass_7_rebel', 'If the worst thing that happens tonight is I run into some bum without records, I''ll consider myself lucky.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 51, 'harass_8_rebel', 'Rebel control of this area is fairly tenative. Our patrols are all on edge due to reports of stormtroopers in the area.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 52, 'harass_9_rebel', 'I hope this war ends soon. It''s bloody depressing.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 53, 'harass_10_rebel', 'If you''re an Imperial, they must be scraping the bottom of the barrel.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 54, 'harass_11_rebel', 'I''m thinking I should bring you in for identification.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 55, 'harass_12_rebel', 'I heard a rumor that Vader kills his own commanding officers. What kind of military wastes soldiers like that?'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 56, 'harass_13_rebel', 'I think I''ll come back here when I''m off duty.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 57, 'harass_14_rebel', 'You need to clean up your act. You look like you just crawled out of the Sarlacc pit.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 58, 'harass_15_rebel', 'No offense but...that outfit is pretty silly.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 59, 'rebel_cowards_imperial', 'Well, everything checks out. If there are any Rebels in here they''re stinking cowards who won''t stand up for their own pitiful cause.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 60, 'rebel_cowards_rebel', 'Everything seems to be in order. Have a good evening.'),
('string/en/npc_reaction/imperial_crackdown_cantina.stf', 61, 'attacking_rebel', 'Hey...I recognize you from the Imperial agents HoloNet report. You''re under arrest! Halt!'),
