('string/en/npc_reaction/slang.stf', 144, 'bye_mean_13', 'Here''s hopin'' ya don''t come back!'),
('string/en/npc_reaction/slang.stf', 145, 'bye_mean_14', 'Next time ya come, bring friends. Love to beat ya ALL up.'),
('string/en/npc_reaction/slang.stf', 146, 'bye_mean_15', '''Bout time ya got gone, buddy.'),
('string/en/npc_reaction/slang.stf', 147, 'bye_mean_16', 'Glad to have wasted th'' time o''day on ya.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/npc_reaction/slang.stf', 148, 'threat_1', 'Take a hike.'),
('string/en/npc_reaction/slang.stf', 149, 'threat_2', 'I don'' like yer kind.'),
('string/en/npc_reaction/slang.stf', 150, 'threat_3', 'Ya better clear on outta here.'),
('string/en/npc_reaction/slang.stf', 151, 'threat_4', 'This is a dangerous place for the likes o'' you.'),
('string/en/npc_reaction/slang.stf', 152, 'threat_5', 'If ya know what''s good for ya, you''ll scram on outta here.'),
('string/en/npc_reaction/slang.stf', 153, 'threat_6', 'Back off, buddy, or I''ll do somethin'' yer gonna hate...'),
('string/en/npc_reaction/slang.stf', 154, 'threat_7', 'C''mon then. Bring it on, buddy!'),
('string/en/npc_reaction/slang.stf', 155, 'threat_8', 'Ya feelin'' lucky? Hmm?'),
('string/en/npc_reaction/slang.stf', 156, 'threat_9', 'I''m drawin'' a line in the sand here, and I''m on this side, see, and yer on the other side, and... oh, never mind.'),
('string/en/npc_reaction/slang.stf', 157, 'threat_10', 'I''m thinkin'' you''d make a nice stuffed trophy.'),
('string/en/npc_reaction/slang.stf', 158, 'threat_11', 'Ya wanna taste o'' this?'),
('string/en/npc_reaction/slang.stf', 159, 'threat_12', 'Come closer, ya can have a knuckle sandwich...!'),
('string/en/npc_reaction/slang.stf', 160, 'threat_13', 'Gimme an excuse ta kill ya...'),
('string/en/npc_reaction/slang.stf', 161, 'threat_14', 'Yer guts are gonna get spilled on the ground here...'),
('string/en/npc_reaction/slang.stf', 162, 'threat_15', 'Yer better back off, I''m the fastest guy in the system.'),
('string/en/npc_reaction/slang.stf', 163, 'threat_16', 'Goody, someone ta practice targets on.'),
('string/en/npc_reaction/slang.stf', 164, 'death_1', 'Welp, THAT hurt. Fatal, possibly. Yep.'),
('string/en/npc_reaction/slang.stf', 165, 'death_2', 'I''m seein'' a dark tunnel... and a bright white light... pretty...'),
('string/en/npc_reaction/slang.stf', 166, 'death_3', 'AGH!'),
('string/en/npc_reaction/slang.stf', 167, 'death_4', 'Uggg...'),
('string/en/npc_reaction/slang.stf', 168, 'death_5', 'I''s too young ta die.'),
('string/en/npc_reaction/slang.stf', 169, 'death_6', 'Mommy?'),
('string/en/npc_reaction/slang.stf', 170, 'death_7', 'I... ain''t... agh.'),
('string/en/npc_reaction/slang.stf', 171, 'death_8', 'I swear I''ll haunt ya to yer grave...'),
('string/en/npc_reaction/slang.stf', 172, 'death_9', 'Yer never goin'' ta be rid o'' me...'),
('string/en/npc_reaction/slang.stf', 173, 'death_10', 'Urk.'),
('string/en/npc_reaction/slang.stf', 174, 'death_11', 'NOOOooooo....'),
('string/en/npc_reaction/slang.stf', 175, 'death_12', 'I... I''m done fer.'),
('string/en/npc_reaction/slang.stf', 176, 'death_13', 'I always thought I''d have more time in this world...'),
('string/en/npc_reaction/slang.stf', 177, 'death_14', 'Yer gonna live ta regret this...'),
('string/en/npc_reaction/slang.stf', 178, 'death_15', 'Aggg...'),
('string/en/npc_reaction/slang.stf', 179, 'death_16', 'Curses, ya got me!'),
('string/en/npc_reaction/slang.stf', 180, 'gloat_1', 'Well, that was easy, I''m thinkin''.'),
('string/en/npc_reaction/slang.stf', 181, 'gloat_2', 'Good fight. Yeah.'),
('string/en/npc_reaction/slang.stf', 182, 'gloat_3', 'Whew, that was a close ''un.'),
('string/en/npc_reaction/slang.stf', 183, 'gloat_4', 'So much fer that.'),
('string/en/npc_reaction/slang.stf', 184, 'gloat_5', 'Now, ya were a worthy opponent and all...'),
('string/en/npc_reaction/slang.stf', 185, 'gloat_6', 'Heh, yer thinkin'' ya can take ME on?'),
('string/en/npc_reaction/slang.stf', 186, 'gloat_7', 'Someone better mop this mess up.'),
('string/en/npc_reaction/slang.stf', 187, 'gloat_8', 'Well, that was sorta pathetic.'),
('string/en/npc_reaction/slang.stf', 188, 'gloat_9', 'Next time, bring lotsa friends.'),
('string/en/npc_reaction/slang.stf', 189, 'gloat_10', 'Sorry ''bout that.'),
('string/en/npc_reaction/slang.stf', 190, 'gloat_11', 'I hate havin'' ta kill folks...'),
('string/en/npc_reaction/slang.stf', 191, 'gloat_12', 'Hee hee.'),
('string/en/npc_reaction/slang.stf', 192, 'gloat_13', 'Whammo!'),
('string/en/npc_reaction/slang.stf', 193, 'gloat_14', 'Good riddance to ya.'),
('string/en/npc_reaction/slang.stf', 194, 'gloat_15', 'Ya poor dolt...'),
('string/en/npc_reaction/slang.stf', 195, 'gloat_16', 'An'' another one down...'),
('string/en/npc_reaction/slang.stf', 196, 'hit_1', 'Ow!'),
('string/en/npc_reaction/slang.stf', 197, 'hit_2', 'Jest a scratch.'),
('string/en/npc_reaction/slang.stf', 198, 'hit_3', 'You''ll need more''n that ta take me down!'),
('string/en/npc_reaction/slang.stf', 199, 'hit_4', 'Agh!'),
('string/en/npc_reaction/slang.stf', 200, 'hit_5', 'Ouch.'),
('string/en/npc_reaction/slang.stf', 201, 'hit_6', 'Gee, now yer makin'' me mad.'),
('string/en/npc_reaction/slang.stf', 202, 'hit_7', 'Nice try, buddy, but I''m still here!'),
('string/en/npc_reaction/slang.stf', 203, 'hit_8', 'That the best ya can do?'),
('string/en/npc_reaction/slang.stf', 204, 'hit_9', 'Go on then, try an'' do that again!'),
('string/en/npc_reaction/slang.stf', 205, 'hit_10', 'Ungh!'),
('string/en/npc_reaction/slang.stf', 206, 'hit_11', 'Hurm, this could be gettin'' bad by and by.'),
('string/en/npc_reaction/slang.stf', 207, 'hit_12', 'Hey, is there a medic in the house?'),
('string/en/npc_reaction/slang.stf', 208, 'hit_13', 'Owie.'),
('string/en/npc_reaction/slang.stf', 209, 'hit_14', 'Yer barely scratchin'' me!'),
('string/en/npc_reaction/slang.stf', 210, 'hit_15', 'Not good, not good...'),
('string/en/npc_reaction/slang.stf', 211, 'hit_16', 'Why, you little...'),
('string/en/npc_reaction/slang.stf', 212, 'attacked_1', 'Flee, or yer gonna die...!'),
('string/en/npc_reaction/slang.stf', 213, 'attacked_2', 'Yer not the toughest to try to take me down, ya know.'),
('string/en/npc_reaction/slang.stf', 214, 'attacked_3', 'Another fight? Yeesh, next time I''m invited ta one, I''m skippin''.'),
('string/en/npc_reaction/slang.stf', 215, 'attacked_4', 'Ya realize you''ll miss out on old age, right?'),
('string/en/npc_reaction/slang.stf', 216, 'attacked_5', 'My momma always said I wouldn''t die in bed.'),
('string/en/npc_reaction/slang.stf', 217, 'attacked_6', 'Can''t wait ta loot yer corpse!'),
('string/en/npc_reaction/slang.stf', 218, 'attacked_7', 'They got a table ready for ya in the afterlife, I hear.'),
('string/en/npc_reaction/slang.stf', 219, 'attacked_8', 'Ya better run. Killin'' don''t take me long.'),
('string/en/npc_reaction/slang.stf', 220, 'attacked_9', 'Oohh, I''m SOOOO scared. Heh.'),
('string/en/npc_reaction/slang.stf', 221, 'attacked_10', 'Do we have ta fight?'),
('string/en/npc_reaction/slang.stf', 222, 'attacked_11', '''S a good day to die.'),
('string/en/npc_reaction/slang.stf', 223, 'attacked_12', 'If''n ya start runnin'' now, ya might get away...'),
('string/en/npc_reaction/slang.stf', 224, 'attacked_13', 'Pickin'' on little ol'' me, huh?'),
('string/en/npc_reaction/slang.stf', 225, 'attacked_14', 'Aww, don'' make me kill ya!'),
('string/en/npc_reaction/slang.stf', 226, 'attacked_16', 'Here''s hopin'' yer will is ready.'),
('string/en/npc_reaction/slang.stf', 227, 'help_1', 'Help!'),
('string/en/npc_reaction/slang.stf', 228, 'help_2', 'I''m needin'' some help, anytime now...'),
('string/en/npc_reaction/slang.stf', 229, 'help_3', 'Help me!'),
('string/en/npc_reaction/slang.stf', 230, 'help_4', 'Hellllp!'),
('string/en/npc_reaction/slang.stf', 231, 'help_5', 'Don'' mean to bother ya, but... HELP!'),
('string/en/npc_reaction/slang.stf', 232, 'help_6', 'I could be usin'' some help here...!'),
('string/en/npc_reaction/slang.stf', 233, 'help_7', 'I can''t handle it all by my lonesome...!'),
('string/en/npc_reaction/slang.stf', 234, 'help_8', 'Ta me! Help!'),
('string/en/npc_reaction/slang.stf', 235, 'help_9', 'Help? Please?'),
('string/en/npc_reaction/slang.stf', 236, 'help_10', 'Uh, can anyone help me?'),
('string/en/npc_reaction/slang.stf', 237, 'help_11', 'Hurry, I''m needin'' help!'),
('string/en/npc_reaction/slang.stf', 238, 'help_12', 'Argh! Help!'),
('string/en/npc_reaction/slang.stf', 239, 'help_13', 'Quick now, over here!'),
('string/en/npc_reaction/slang.stf', 240, 'help_14', 'Over hereabouts, hurry up now!'),
('string/en/npc_reaction/slang.stf', 241, 'help_15', 'Hurry! Over hereabouts!'),
('string/en/npc_reaction/slang.stf', 242, 'help_16', 'I could be usin'' help here!'),
('string/en/npc_reaction/slang.stf', 243, 'ally_1', 'Get away from my friend there!'),
('string/en/npc_reaction/slang.stf', 244, 'ally_2', 'Ya don'' lay a finger on my friends!'),
('string/en/npc_reaction/slang.stf', 245, 'ally_3', 'Why you little...'),
('string/en/npc_reaction/slang.stf', 246, 'ally_4', 'Hey now! Back off!'),
('string/en/npc_reaction/slang.stf', 247, 'ally_5', 'Just a sec there! What''re ya doin''?'),
('string/en/npc_reaction/slang.stf', 248, 'ally_6', 'Coward, why dontcha pick on me instead?'),
('string/en/npc_reaction/slang.stf', 249, 'ally_7', 'Pick on someone yer own size!'),
('string/en/npc_reaction/slang.stf', 250, 'ally_8', 'You needin'' help here, friend?'),
('string/en/npc_reaction/slang.stf', 251, 'ally_9', 'Yer lookin'' like you could use some help.'),
('string/en/npc_reaction/slang.stf', 252, 'ally_10', 'Welp, guess I should be steppin'' in here.'),
('string/en/npc_reaction/slang.stf', 253, 'ally_11', 'Hey! Yer OK?'),
('string/en/npc_reaction/slang.stf', 254, 'ally_12', 'Hey now! You should be leavin'' my friend alone!'),
('string/en/npc_reaction/slang.stf', 255, 'ally_13', 'I don'' care who y''are, ya don''t touch my friends.'),
('string/en/npc_reaction/slang.stf', 256, 'ally_14', 'Hey now!'),
('string/en/npc_reaction/slang.stf', 257, 'ally_15', 'Are y''okay, buddy? Lemme take care o'' this.'),
('string/en/npc_reaction/slang.stf', 258, 'ally_16', 'Lemme even up the odds summat.'),
('string/en/npc_reaction/slang.stf', 259, 'hit_target_1', 'Take that, buddy!'),
('string/en/npc_reaction/slang.stf', 260, 'hit_target_2', 'Hee hee!'),
('string/en/npc_reaction/slang.stf', 261, 'hit_target_3', 'Got ya!'),
('string/en/npc_reaction/slang.stf', 262, 'hit_target_4', 'You got an ouchie!'),
('string/en/npc_reaction/slang.stf', 263, 'hit_target_5', 'Ha ha! I gotcha!'),
('string/en/npc_reaction/slang.stf', 264, 'hit_target_6', 'Fight! I love a fight!'),
('string/en/npc_reaction/slang.stf', 265, 'hit_target_7', 'Looks like yer hurt.'),
('string/en/npc_reaction/slang.stf', 266, 'hit_target_8', 'C''mere, coward!'),
('string/en/npc_reaction/slang.stf', 267, 'hit_target_9', 'I got yer!'),
('string/en/npc_reaction/slang.stf', 268, 'hit_target_10', 'Yer goin'' down!'),
('string/en/npc_reaction/slang.stf', 269, 'hit_target_11', 'Oh no, ya don''t!'),
('string/en/npc_reaction/slang.stf', 270, 'hit_target_12', 'Mmmm, lemme see.'),
('string/en/npc_reaction/slang.stf', 271, 'hit_target_13', 'My turn now...!'),
('string/en/npc_reaction/slang.stf', 272, 'hit_target_14', 'Ya better run away while ya can!'),
('string/en/npc_reaction/slang.stf', 273, 'hit_target_15', 'Ooh, that must ''ave hurt ye.'),
('string/en/npc_reaction/slang.stf', 274, 'hit_target_16', 'Yer doomed. Why dontcha surrender?'),
('string/en/npc_reaction/slang.stf', 275, 'assist_1', 'Time for ya to die!'),
('string/en/npc_reaction/slang.stf', 276, 'assist_2', 'Surround ''em!'),
('string/en/npc_reaction/slang.stf', 277, 'assist_3', 'Concentrate yer fire!'),
('string/en/npc_reaction/slang.stf', 278, 'assist_4', 'Form up, maggots!'),
('string/en/npc_reaction/slang.stf', 279, 'assist_5', 'Get inter formation!'),
('string/en/npc_reaction/slang.stf', 280, 'assist_6', 'Form up, ya useless cannon fodder!'),
('string/en/npc_reaction/slang.stf', 281, 'assist_7', 'They''re gonna regret this...'),
('string/en/npc_reaction/slang.stf', 282, 'assist_8', 'We kin pin'' em down...'),
('string/en/npc_reaction/slang.stf', 283, 'assist_9', 'Surround the target, people!'),
('string/en/npc_reaction/slang.stf', 284, 'assist_10', 'OK, yer needin'' ta get into formations now, people!'),
('string/en/npc_reaction/slang.stf', 285, 'assist_11', 'No shakin'' hands now, keep ''er steady and fire together.'),
('string/en/npc_reaction/slang.stf', 286, 'assist_12', 'We''re needin'' to keep ''em pinned down. Hold ''em steady!'),
('string/en/npc_reaction/slang.stf', 287, 'assist_13', 'Steady now! Concentrate yer fire!'),
('string/en/npc_reaction/slang.stf', 288, 'assist_14', 'Get inter formation, now!'),
('string/en/npc_reaction/slang.stf', 289, 'assist_15', 'Form up, in nice rows! Move it, ya lunks!'),
('string/en/npc_reaction/slang.stf', 290, 'assist_16', 'Move it, ya useless worms! Formations!'),
('string/en/npc_reaction/stormtrooper.stf', 1, 'alert_1', 'There''s a disturbance here.'),
