('string/en/npc_reaction/stormtrooper.stf', 45, 'flee_11', 'Moving to better position.'),
('string/en/npc_reaction/stormtrooper.stf', 46, 'flee_12', 'Withdraw!'),
('string/en/npc_reaction/stormtrooper.stf', 47, 'flee_13', 'Position compromised!'),
('string/en/npc_reaction/stormtrooper.stf', 48, 'flee_14', 'Move! Move!'),
('string/en/npc_reaction/stormtrooper.stf', 49, 'flee_15', 'Reporting in... position overrun, retreating...'),
