('string/en/npc_reaction/stormtrooper.stf', 51, 'hi_nice_1', 'Stand down, it''s a friendly.'),
('string/en/npc_reaction/stormtrooper.stf', 52, 'hi_nice_2', 'Is there a problem that I need to help you with?'),
('string/en/npc_reaction/stormtrooper.stf', 53, 'hi_nice_3', 'Reporting in... this sector is clear.'),
('string/en/npc_reaction/stormtrooper.stf', 54, 'hi_nice_4', 'Tell me what you need.'),
('string/en/npc_reaction/stormtrooper.stf', 55, 'hi_nice_5', 'I''m at your service.'),
('string/en/npc_reaction/stormtrooper.stf', 56, 'hi_nice_6', 'What do you need from me?'),
