('string/en/npc_reaction/stormtrooper.stf', 69, 'hi_mid_3', 'Warning, this is a restricted area.'),
('string/en/npc_reaction/stormtrooper.stf', 70, 'hi_mid_4', 'This is a restricted area.  Watch what you do here.'),
