('string/en/npc_reaction/townperson.stf', 239, 'help_13', 'Quick, over here!'),
('string/en/npc_reaction/townperson.stf', 240, 'help_14', 'Over here, hurry!'),
('string/en/npc_reaction/townperson.stf', 241, 'help_15', 'Hurry! Over here!'),
('string/en/npc_reaction/townperson.stf', 242, 'help_16', 'Quick, need some help here!'),
('string/en/npc_reaction/townperson.stf', 243, 'ally_1', 'Get away from my friend!'),
('string/en/npc_reaction/townperson.stf', 244, 'ally_2', 'Don''t lay a finger on my friends...!'),
('string/en/npc_reaction/townperson.stf', 245, 'ally_3', 'Why, you...!'),
('string/en/npc_reaction/townperson.stf', 246, 'ally_4', 'Hey now! Back off!'),
('string/en/npc_reaction/townperson.stf', 247, 'ally_5', 'Just a second! What are you doing?!'),
('string/en/npc_reaction/townperson.stf', 248, 'ally_6', 'You coward! Whyn''t you pick on me instead, huh?'),
('string/en/npc_reaction/townperson.stf', 249, 'ally_7', 'Pick on someone your own size!'),
('string/en/npc_reaction/townperson.stf', 250, 'ally_8', 'Need any help here, friend?'),
('string/en/npc_reaction/townperson.stf', 251, 'ally_9', 'You look like you could use some help.'),
('string/en/npc_reaction/townperson.stf', 252, 'ally_10', 'Well, well. Guess it''s time for me to step in here.'),
('string/en/npc_reaction/townperson.stf', 253, 'ally_11', 'Hey! You OK?'),
('string/en/npc_reaction/townperson.stf', 254, 'ally_12', 'Hey now! Leave my friend alone!'),
('string/en/npc_reaction/townperson.stf', 255, 'ally_13', 'I don''t care who you are, you don''t touch my friends.'),
('string/en/npc_reaction/townperson.stf', 256, 'ally_14', 'Hey now!'),
('string/en/npc_reaction/townperson.stf', 257, 'ally_15', 'You OK, friend? Let me take care of this...'),
('string/en/npc_reaction/townperson.stf', 258, 'ally_16', 'Let me even the odds a little...'),
('string/en/npc_reaction/townperson.stf', 259, 'hit_target_1', 'Take that!'),
('string/en/npc_reaction/townperson.stf', 260, 'hit_target_2', 'Ha!'),
('string/en/npc_reaction/townperson.stf', 261, 'hit_target_3', 'Got you!'),
('string/en/npc_reaction/townperson.stf', 262, 'hit_target_4', 'That must sting!'),
('string/en/npc_reaction/townperson.stf', 263, 'hit_target_5', 'Ha ha! I got you!'),
('string/en/npc_reaction/townperson.stf', 264, 'hit_target_6', 'I love a fair fight!'),
('string/en/npc_reaction/townperson.stf', 265, 'hit_target_7', 'That looks like it hurt.'),
('string/en/npc_reaction/townperson.stf', 266, 'hit_target_8', 'Stand up and take it, coward!'),
('string/en/npc_reaction/townperson.stf', 267, 'hit_target_9', 'Gotcha!'),
('string/en/npc_reaction/townperson.stf', 268, 'hit_target_10', 'You''re going down!'),
('string/en/npc_reaction/townperson.stf', 269, 'hit_target_11', 'Oh no you don''t!'),
('string/en/npc_reaction/townperson.stf', 270, 'hit_target_12', 'It''s hard making this look so easy.'),
('string/en/npc_reaction/townperson.stf', 271, 'hit_target_13', 'Now it''s my turn.'),
('string/en/npc_reaction/townperson.stf', 272, 'hit_target_14', 'Better run away while you still can!'),
('string/en/npc_reaction/townperson.stf', 273, 'hit_target_15', 'Ooh, did that hurt?'),
('string/en/npc_reaction/townperson.stf', 274, 'hit_target_16', 'Give up now, and I might let you live.'),
('string/en/npc_reaction/townperson.stf', 275, 'assist_1', 'Pin them down!'),
('string/en/npc_reaction/townperson.stf', 276, 'assist_2', 'Let''s encircle them!'),
('string/en/npc_reaction/townperson.stf', 277, 'assist_3', 'Take them out one at a time!'),
('string/en/npc_reaction/townperson.stf', 278, 'assist_4', 'Come on, everyone line up!'),
('string/en/npc_reaction/townperson.stf', 279, 'assist_5', 'Gang up on them!'),
('string/en/npc_reaction/townperson.stf', 280, 'assist_6', 'Everyone, work together here!'),
('string/en/npc_reaction/townperson.stf', 281, 'assist_7', 'They''re going down...'),
('string/en/npc_reaction/townperson.stf', 282, 'assist_8', 'Pin them down! We can do it!'),
('string/en/npc_reaction/townperson.stf', 283, 'assist_9', 'Surround them!'),
('string/en/npc_reaction/townperson.stf', 284, 'assist_10', 'Let''s gang up on them!'),
('string/en/npc_reaction/townperson.stf', 285, 'assist_11', 'Everybody fire on one target!'),
('string/en/npc_reaction/townperson.stf', 286, 'assist_12', 'Steady...we don''t want them to rush us.'),
('string/en/npc_reaction/townperson.stf', 287, 'assist_13', 'Concentrate fire on one enemy!'),
('string/en/npc_reaction/townperson.stf', 288, 'assist_14', 'C''mon, everybody together!'),
('string/en/npc_reaction/townperson.stf', 289, 'assist_15', 'Move it! Into rows or something!'),
('string/en/npc_reaction/townperson.stf', 290, 'assist_16', 'C''mon people! Let''s work together here!'),
