('string/en/poi/deliverance/farmer_stormtroopers.stf', 1, 'm_greet', 'I''m in some trouble here. Someone told the Imperials that I''m some sort of rebel spy. I ain''t no rebel. I''m just a farmer. I scared they are going to take away my land and throw me in prison. Can you help protect me if they try?'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 2, 'a_greet', 'Who are you? You''re standing in the way of Imperial business. Are you going to stand aside?'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 3, 'm_yes', 'I sure do appreciate that. I''m guessing they will be here any time now.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 4, 'm_no', 'Well, I guess I shouldn''t have expected any help. You''d have likely been labeled a rebel too. Oh well.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 5, 'm_thank_combat', 'Well, that''s that for now, but something tells me this is just the start of my problems. I think it is time for me to start looking for a way off this planet.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 7, 'a_greet_rebel', 'Stand aside, unless you want to be arrested too.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 8, 'a_greet_imperial', 'We''ve have this situation under control. Please stand aside.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 9, 'm_maybe', 'I ain''t no good at talking my way out of nothing. When they get here, maybe you can see if they''ll change their mind about me.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 10, 'a_no', 'You are in direct violation of an Imperial order and are under arrest.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 11, 'a_yes', 'We''ll handle it from here.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 12, 'a_maybe', 'Just a farmer? Then what was he doing tampering with an Imperial relay tower?'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 13, 'a_no_negotiate', 'I said stand aside. Now!'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 14, 'm_will_negotiate', 'Tampering? I wasn''t tampering. It was buzzing for three days. Scaring my livestock. I just figured I could fix it so it stopped making so much noise. I wasn''t spying or nothing.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 15, 'm_no_negotiate', 'Well, thanks for trying. I just can''t let them take my land. I ain''t no rebel, but maybe it''s my calling after all.  '),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 16, 'a_decline_offer', 'It is illegal to tamper with Imperial property. He''s just admitted his guilt.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 17, 'a_accept_offer', 'Well, the relay tower was having some problems and it isn''t now. All right, we''ll let him go.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 18, 'm_negotiate_greet', 'Am I free to go?'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 19, 'response_yes', 'Yes'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 20, 'response_no', 'No'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 21, 'response_maybe', 'Maybe'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 22, 'response_negotiate', 'Wait. This may be a mistake. This is just a simple farmer, not a rebel spy.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 23, 'm_thank_negotiate', 'You pretty much saved my life there. Thank you so much!'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 24, 'm_waiting', 'Yep, they''re coming now. Oh, I got a bad feeling coming on.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 25, 'a_greet_m', 'Halt! Come with us peacefully. You are wanted for questioning.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 26, 'm_greet_a', 'I ain''t no rebel spy. I don''t know who told you that, but it just ain''t true!'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 27, 'a_respond_m_1', 'We have a warrant for your arrest. Come with us.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 29, 'a_thank_combat', 'That takes care of this situation. '),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 30, 'a_thank_negotiate', 'Thank you for your assistance in this matter. '),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 32, 'minion_1', 'This is official business.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 33, 'minion_2', 'We''re rounding up suspected rebel spies.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 34, 'minion_3', 'They always say they are just innocent farmers. '),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 35, 'minion_4', 'We have undisputable evidence that he tampered with Imperial property.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 37, 'minion_5', 'He looks like a rebel to me.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 38, 'a_greet_mad', 'Halt! Come with us for questioning now or we''ll shoot.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/poi/deliverance/farmer_stormtroopers.stf', 39, 'a_waiting', 'Come with us now. We have orders to blast those who resist.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 40, 'a_negotiate_fail', 'It doesn''t matter what his reason was. The activity was still illegal. '),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 41, 'a_thank_negotiate_again', 'The situation is clear. Heading back to base.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 42, 'a_brushoff', 'Move along.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 43, 'a_tired_waiting', 'You have been warned. Take him down!'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 44, 'a_no_progress', 'Get out of our way.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 47, 'm_saved', 'I think this is a sure sign that I should join the rebellion.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 48, 'm_betrayed', 'I''m just a farmer! You are as bad as they are.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 49, 'm_sorry', 'I''m just a farmer. I''m innocent.'),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 50, 'a_accept_offer_chat', ''),
('string/en/poi/deliverance/farmer_stormtroopers.stf', 51, 'a_accept_offer_mood', 'Tolerant'),
