INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/poi/deliverance/imperial_rebels.stf', 139, 'a_greet_imperial_act', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 142, 'a_greet_act', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 143, 'a_decline_offer_chat', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 144, 'a_decline_offer_mood', 'Sarcastic'),
('string/en/poi/deliverance/imperial_rebels.stf', 145, 'a_decline_offer_act', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 146, 'a_brushoff_act', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 147, 'a_brushoff_mood', 'Cynical'),
('string/en/poi/deliverance/imperial_rebels.stf', 148, 'a_brushoff_chat', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 149, 'm_rejected', 'I should have known.'),
('string/en/poi/deliverance/imperial_rebels.stf', 150, 'm_rejected_act', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 151, 'm_rejected_chat', ''),
('string/en/poi/deliverance/imperial_rebels.stf', 152, 'm_rejected_mood', ''),
('string/en/poi/deliverance/lothario_exlovers.stf', 1, 'm_greet', 'Help me! Please! I''m being chased by crazy women who want to kill me. I know I know, I should be able to handle myself against them, but I''m more of a lover than a fighter. Help me fend them off.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 2, 'a_greet', 'This creep told me I was his only love. He strung me along for years. All the while he was seeing all of these other women. Well we finally found out about each other. At first we argued with each other, but then we realized we all had a common enemy - him! Now get out of our way so we can teach this two-timer a lesson.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 3, 'm_yes', 'You see they were lovers of mine at one time. Sometimes love goes bad, real bad. '),
('string/en/poi/deliverance/lothario_exlovers.stf', 4, 'm_no', 'You don''t understand. These women are going to kill me, as in cold blooded murder. My only crime is that I loved them.all.at the same time. I''m in so much trouble.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 5, 'm_thank_combat', 'I told you not to hurt them. I really did care for them, all of them, I just didn''t want to face their wrath. They were just so angry. I feel terrible now.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 7, 'a_greet_rebel', 'This creep told me I was his only love. He strung me along for years. All the while he was seeing all of these other women. Well we finally found out about each other. At first we argued with each other, but then we realized we all had a common enemy - him! Now get out of our way so we can teach this two-timer a lesson.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 8, 'a_greet_imperial', 'This creep told me I was his only love. He strung me along for years. All the while he was seeing all of these other women. Well we finally found out about each other. At first we argued with each other, but then we realized we all had a common enemy - him! Now get out of our way so we can teach this two-timer a lesson.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 9, 'm_maybe', 'Maybe you can reason with them. You see, they were my lovers, well, until they found out about each other. I didn''t mean to hurt them, but now they have it in for me.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 10, 'a_no', 'You''re going to take his side?! Oh you make me so mad!'),
('string/en/poi/deliverance/lothario_exlovers.stf', 11, 'a_yes', 'Good because he''s going to wish he never met any of us! '),
('string/en/poi/deliverance/lothario_exlovers.stf', 12, 'a_maybe', 'What can he possibly say at this point for us to want to handle this peacefully? Why don''t you ask him?'),
('string/en/poi/deliverance/lothario_exlovers.stf', 13, 'a_no_negotiate', 'He broke my heart. He was dishonest with all of us. No, we''ve decided to teach him not to play with any woman''s affections. Now get out of our way!'),
('string/en/poi/deliverance/lothario_exlovers.stf', 14, 'm_will_negotiate', 'What if I promise to never see the other women again? I mean it this time. Those other women meant nothing to me. I would do anything for her forgiveness. I would do what ever she asked of me to regain her trust and love. Tell her that, would you?'),
('string/en/poi/deliverance/lothario_exlovers.stf', 15, 'm_no_negotiate', 'It''s no use. I''ve tried to explain it to them. I loved them all differently, you see. For some reason they just don''t understand that. Thanks for trying, but there is no point. '),
('string/en/poi/deliverance/lothario_exlovers.stf', 16, 'a_decline_offer', 'I''m sick of his smooth talking. I fell for those lines too many times. It is over this time and there is nothing he can do or say to change that. Oh, he makes me so mad!'),
('string/en/poi/deliverance/lothario_exlovers.stf', 17, 'a_accept_offer', 'He would do anything for my love? He really just loves me and not those others? I don''t know if I could trust him again, but I''ve put so much into this relationship I can''t just turn my back on it. I''ll think about it. '),
('string/en/poi/deliverance/lothario_exlovers.stf', 18, 'm_negotiate_greet', 'Well, is she going for it? '),
('string/en/poi/deliverance/lothario_exlovers.stf', 19, 'response_yes', 'Yes'),
('string/en/poi/deliverance/lothario_exlovers.stf', 20, 'response_no', 'No'),
('string/en/poi/deliverance/lothario_exlovers.stf', 21, 'response_maybe', 'Maybe'),
('string/en/poi/deliverance/lothario_exlovers.stf', 22, 'response_negotiate', 'Whoa, maybe you should try to solve this peacefully. '),
('string/en/poi/deliverance/lothario_exlovers.stf', 23, 'm_thank_negotiate', 'Wow, that was close. You just saved my life, I mean, my relationship.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 24, 'm_waiting', 'Here they come. Remember, I don''t want to hurt them. Just scare them off.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 25, 'a_greet_m', 'There you are. Did you really think you get away with cheating on me, let alone all of us? '),
('string/en/poi/deliverance/lothario_exlovers.stf', 26, 'm_greet_a', 'Hey darling, I didn''t mean to cause you pain. They don''t mean anything to me. You are my true love.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 27, 'a_respond_m_1', 'You''re not going to talk your way out of this one. We''ve been talking. I finally understand the big picture. We all do.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 29, 'a_thank_combat', 'I didn''t mean for that to happen. What have we done? I just wanted to teach him a little lesson for hurting me. I feel terrible.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 30, 'a_thank_negotiate', 'I need some time by myself to think things over. He''s going to have his work cut out for him if he''s going to earn my trust again.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 32, 'minion_1', 'He promised he would marry me one day.  '),
('string/en/poi/deliverance/lothario_exlovers.stf', 33, 'minion_2', 'He promised we would go off world together and explore the galaxy.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 34, 'minion_3', 'He promised me the moon and stars and nebulas and black holes and just about everything else there is. I can''t believe he is such a liar! '),
('string/en/poi/deliverance/lothario_exlovers.stf', 35, 'minion_4', 'He promised me that I was the only one for him. He said we were meant to be together. He said he was going to leave that other woman for me. Now I find out he was cheating on me too. I hate him! '),
('string/en/poi/deliverance/lothario_exlovers.stf', 37, 'minion_5', 'He didn''t promise me anything. I knew he was scum from the first moment I met him. I can''t believe my sister fell for his act. He''s going to pay for messing with her.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 38, 'a_greet_mad', 'There you are. You think you can get someone else to protect you from us? '),
('string/en/poi/deliverance/lothario_exlovers.stf', 39, 'a_waiting', 'It''s time you paid for what you''ve done to us, you lecherous louse!'),
('string/en/poi/deliverance/lothario_exlovers.stf', 40, 'a_negotiate_fail', 'I don''t want to hear it! '),
('string/en/poi/deliverance/lothario_exlovers.stf', 41, 'a_thank_negotiate_again', 'Then again, he did say he loves me. Maybe I''ve been too hard on him.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 42, 'a_brushoff', 'I don''t know how I ever trusted him in the first place. Men, ugh! '),
('string/en/poi/deliverance/lothario_exlovers.stf', 43, 'a_tired_waiting', 'Let''s teach him a lesson.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 44, 'a_no_progress', 'Leave us alone!'),
('string/en/poi/deliverance/lothario_exlovers.stf', 47, 'm_saved', 'What have I done? I''m going to die alone, I know it.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 48, 'm_betrayed', 'But I thought you were going to help me.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 49, 'm_sorry', 'The only thing I can give you is advice. If you are going to see more than one person at the same time, make certain they are on separate planets.'),
('string/en/poi/deliverance/lothario_exlovers.stf', 50, 'a_accept_offer_chat', ''),
('string/en/poi/deliverance/lothario_exlovers.stf', 51, 'a_accept_offer_mood', 'Interested'),
('string/en/poi/deliverance/lothario_exlovers.stf', 52, 'a_accept_offer_act', ''),
