('string/en/poi/deliverance/poisoner_two.stf', 145, 'a_decline_offer_act', ''),
('string/en/poi/deliverance/poisoner_two.stf', 146, 'a_brushoff_act', ''),
('string/en/poi/deliverance/poisoner_two.stf', 147, 'a_brushoff_mood', 'evil'),
('string/en/poi/deliverance/poisoner_two.stf', 148, 'a_brushoff_chat', 'whisper'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 1, 'm_greet', 'Please help me. Imperial Stormtroopers are after me. They think I''m with the Rebellion. Can I get you to help me out here?'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 2, 'a_greet', 'Stand aside. We''re on official business to apprehend an enemy of the Empire.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 3, 'm_yes', 'You don''t like the Empire much either, eh? Great! When I distract them, you hit them. With your help, I can take them. '),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 4, 'm_no', 'I''ll be sent to an Imperial prison for sure. You know someday you''ve got to stick your neck out against the Empire. It is just going to get worse.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 5, 'm_thank_combat', 'You probably saved my life there. The rebellion owes you a debt of gratitude for this.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 7, 'a_greet_rebel', 'Stand aside, unless you want to be arrested too.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 8, 'a_greet_imperial', 'Stand aside. This is a known traitor. We can handle this situation.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 9, 'm_maybe', 'I don''t think they have a positive ID on me. If you tell them I''m not a Rebel that may be enough to buy me time to get off this planet.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 10, 'a_no', 'You are in direct violation of an Imperial order and are under arrest.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 11, 'a_yes', 'We''ll handle it from here.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 12, 'a_maybe', 'Not the right suspect? He was seen talking with known rebel sympathizers two hours ago. Does he have any evidence to say otherwise?'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 13, 'a_no_negotiate', 'I said stand aside. Now!'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 14, 'm_will_negotiate', 'Couldn''t have been me, because I was with you two hours ago. Isn''t that right? Please.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 15, 'm_no_negotiate', 'I knew I should have checked the room for hidden transmitters. Well, there''s no easy way out of this one. '),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 16, 'a_decline_offer', 'I asked for evidence, not an alibi. He''s coming with us now.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 17, 'a_accept_offer', 'He was with you? All right, we''re going to let him go for now, but he better not try to leave the planet.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 18, 'm_negotiate_greet', 'Did they buy it?'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 19, 'response_yes', 'Yes'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 20, 'response_no', 'No'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 21, 'response_maybe', 'Maybe'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 22, 'response_negotiate', 'Wait. This isn''t the suspect you are looking for.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 23, 'm_thank_negotiate', 'Whew, thanks. The rebellion owes you a debt of gratitude for this.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 24, 'm_waiting', 'Be careful, I think I can hear them coming.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 25, 'a_greet_m', 'Halt! Come with us peacefully. You are wanted for questioning.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 26, 'm_greet_a', 'Who? Me? What did I do? I think you have the wrong person.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 27, 'a_respond_m_1', 'We will ascertain that back at base. Come with us.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 29, 'a_thank_combat', 'The rebel shouldn''t have resisted. You''ve served the Empire well.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 30, 'a_thank_negotiate', 'Thank you for your assistance in this matter. '),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 32, 'minion_1', 'This is official business.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 33, 'minion_2', 'He is a rebel spy.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 34, 'minion_3', 'There are more traitors to round up. '),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 35, 'minion_4', 'Stand aside.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 37, 'minion_5', 'Awaiting orders.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 38, 'a_greet_mad', 'Halt! Come with us for questioning now or we''ll shoot.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 39, 'a_waiting', 'This is your last chance. Come with us now, or we will take you in by force.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 40, 'a_negotiate_fail', 'That''s enough. Our commander will do the interrogation back at base. '),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 41, 'a_thank_negotiate_again', 'The situation is clear. Heading back to base.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 42, 'a_brushoff', 'Move along.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 43, 'a_tired_waiting', 'You have been warned. Take him down!'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 44, 'a_no_progress', 'Move along. Now.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 47, 'm_saved', 'I''m certain they would have tried to get information out of me about the Alliance. You''ve probably saved more than just my life here today. Thanks!'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 48, 'm_betrayed', 'I''m disappointed. I thought you looked like someone who didn''t kowtow to the Empire.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 49, 'm_sorry', 'May the Force be with you.'),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 50, 'a_accept_offer_chat', ''),
('string/en/poi/deliverance/rebel_stormtroopers.stf', 51, 'a_accept_offer_mood', 'Tolerant'),
