('string/en/poi/deliverance/template.stf', 1, 'm_greet', 'I am the mediator greeting you... the antagonists are going to do something bad. will you help me?'),
('string/en/poi/deliverance/template.stf', 2, 'a_greet', 'I am the antagonist greeting you... mediator is not innocent for this reason. will you allow us to do our job?'),
('string/en/poi/deliverance/template.stf', 3, 'm_yes', 'You answered yes... here is what you are supposed to do'),
('string/en/poi/deliverance/template.stf', 4, 'm_no', 'no? please please please help me!!'),
('string/en/poi/deliverance/template.stf', 5, 'm_thank_combat', 'Thank you for hurting those baddies!'),
('string/en/poi/deliverance/template.stf', 7, 'a_greet_rebel', 'our factions are both rebel... i will greet you much nicer'),
('string/en/poi/deliverance/template.stf', 8, 'a_greet_imperial', 'our factions are both imperial... i will greet you much nicer'),
('string/en/poi/deliverance/template.stf', 9, 'm_maybe', 'You talk to the baddies when they get here then... maybe you can work something out.'),
('string/en/poi/deliverance/template.stf', 10, 'a_no', 'you will regret this...'),
('string/en/poi/deliverance/template.stf', 11, 'a_yes', 'then be on your way...'),
('string/en/poi/deliverance/template.stf', 12, 'a_maybe', 'ok... you can try to negotiate... but be quick about it...'),
('string/en/poi/deliverance/template.stf', 13, 'a_no_negotiate', 'there will be no negotiating... get out of our way or suffer the same fate...'),
('string/en/poi/deliverance/template.stf', 14, 'm_will_negotiate', 'I think I have something that would fix the situation...'),
('string/en/poi/deliverance/template.stf', 15, 'm_no_negotiate', 'but i have nothing to give... help me!!'),
('string/en/poi/deliverance/template.stf', 16, 'a_decline_offer', 'bad offer... he dies now!'),
('string/en/poi/deliverance/template.stf', 17, 'a_accept_offer', 'this will do just fine... for now...'),
('string/en/poi/deliverance/template.stf', 18, 'm_negotiate_greet', 'what did they say?'),
('string/en/poi/deliverance/template.stf', 19, 'response_yes', 'Yes'),
('string/en/poi/deliverance/template.stf', 20, 'response_no', 'No'),
('string/en/poi/deliverance/template.stf', 21, 'response_maybe', 'Maybe'),
('string/en/poi/deliverance/template.stf', 22, 'response_negotiate', 'Are you willing to negotiate?'),
('string/en/poi/deliverance/template.stf', 23, 'm_thank_negotiate', 'Thank you for negotiating me out of that mess...'),
('string/en/poi/deliverance/template.stf', 24, 'm_waiting', 'You agreed to help me and we are waiting... they should be here soon, please wait!'),
('string/en/poi/deliverance/template.stf', 25, 'a_greet_m', 'I the antagonist leader am accosting the mediator verbally'),
('string/en/poi/deliverance/template.stf', 26, 'm_greet_a', 'I, the mediator, am responding to the antagonist leaders threat'),
('string/en/poi/deliverance/template.stf', 27, 'a_respond_m_1', 'I am responding to mediator greet!'),
('string/en/poi/deliverance/template.stf', 29, 'a_thank_combat', 'I am thanking you for killing the mediator'),
('string/en/poi/deliverance/template.stf', 30, 'a_thank_negotiate', 'I am thanking you for negotiating this...'),
('string/en/poi/deliverance/template.stf', 32, 'minion_1', 'i am a minion... this is random flavor text 1'),
('string/en/poi/deliverance/template.stf', 33, 'minion_2', 'i am a minion... this is random flavor text 2'),
('string/en/poi/deliverance/template.stf', 34, 'minion_3', 'i am a minion... this is random flavor text 3'),
('string/en/poi/deliverance/template.stf', 35, 'minion_4', 'i am a minion... this is random flavor text 4'),
('string/en/poi/deliverance/template.stf', 37, 'minion_5', 'i am a minion... this is random flavor text 5'),
('string/en/poi/deliverance/template.stf', 38, 'a_greet_mad', 'What? you agreed to help mediator? you will die too!'),
('string/en/poi/deliverance/template.stf', 39, 'a_waiting', 'I am waiting for you to do something... and if you dont do it soon... i am gonna attack!'),
('string/en/poi/deliverance/template.stf', 40, 'a_negotiate_fail', 'What?! You just wasted my time!'),
('string/en/poi/deliverance/template.stf', 41, 'a_thank_negotiate_again', 'Thanks again for working this out for us...'),
('string/en/poi/deliverance/template.stf', 42, 'a_brushoff', 'i am brushing you off since you didnt have any credit for this poi'),
('string/en/poi/deliverance/template.stf', 43, 'a_tired_waiting', 'I am tired of waiting... enough of this... attack!'),
('string/en/poi/deliverance/template.stf', 44, 'a_no_progress', 'Go away... I have no time for you...'),
('string/en/poi/deliverance/template.stf', 47, 'm_saved', 'I am saved! I am saved!'),
('string/en/poi/deliverance/template.stf', 48, 'm_betrayed', 'You would allow them to attack me? You will die before I do!!'),
('string/en/poi/deliverance/template.stf', 49, 'm_sorry', 'I am so sorry I cannot provide anything... please just help me!'),
('string/en/poi/deliverance/template.stf', 50, 'a_accept_offer_chat', ''),
('string/en/poi/deliverance/template.stf', 51, 'a_accept_offer_mood', '');
