('string/en/poi/deliverance/thief_mob.stf', 132, 'a_greet_mad_mood', 'Bloodthirsty'),
('string/en/poi/deliverance/thief_mob.stf', 133, 'a_greet_mad_act', ''),
('string/en/poi/deliverance/thief_mob.stf', 134, 'a_greet_m_chat', ''),
('string/en/poi/deliverance/thief_mob.stf', 135, 'a_greet_m_mood', 'Vengeful'),
('string/en/poi/deliverance/thief_mob.stf', 136, 'a_greet_m_act', 'Blame'),
('string/en/poi/deliverance/thief_mob.stf', 139, 'a_greet_imperial_act', ''),
('string/en/poi/deliverance/thief_mob.stf', 142, 'a_greet_act', ''),
('string/en/poi/deliverance/thief_mob.stf', 143, 'a_decline_offer_chat', ''),
('string/en/poi/deliverance/thief_mob.stf', 144, 'a_decline_offer_mood', 'Disgusted'),
