('string/en/poi/gangwar/imperial1.stf', 1, 'a_insult1', 'Rebel recidivists: surrender your weapons and put your hands above your heads.'),
('string/en/poi/gangwar/imperial1.stf', 2, 'm_insult1_response', 'We aren''t criminals!  We did nothing illegal!'),
('string/en/poi/gangwar/imperial1.stf', 3, 'a_insult2', 'Cooperate with my directive and you will not be harmed.'),
('string/en/poi/gangwar/imperial1.stf', 4, 'm_insult2_response', 'Is that a threat?  We haven''t done anything.  We refuse to be arrested by thugs!'),
('string/en/poi/gangwar/imperial1.stf', 5, 'a_insult3', 'We have no desire to use force, but we will if you do not surrender immediately.'),
('string/en/poi/gangwar/imperial1.stf', 6, 'm_insult3_response', 'There will be no surrender for the Rebellion!'),
('string/en/poi/gangwar/imperial1.stf', 7, 'a_insult4', 'You were sufficiently warned.  Squad, arrest these men.'),
('string/en/poi/gangwar/imperial1.stf', 8, 'a_whoareyou', 'Cease and desist, Rebel sympathizer!'),
('string/en/poi/gangwar/imperial1.stf', 9, 'a_beast_title', 'enslaved'),
('string/en/poi/gangwar/imperial1.stf', 10, 'm_beast_title', 'trained'),
('string/en/poi/gangwar/imperial1.stf', 11, 'a_insult1_chat', 'intone'),
