('string/en/poi/gangwar/imperial1.stf', 21, 'm_insult2_response_chat', 'huff'),
('string/en/poi/gangwar/imperial1.stf', 22, 'm_insult2_response_mood', 'imploring'),
('string/en/poi/gangwar/imperial1.stf', 23, 'm_insult3_response_chat', 'shout'),
('string/en/poi/gangwar/imperial1.stf', 24, 'm_insult3_response_mood', 'stubborn'),
('string/en/poi/gangwar/imperial1.stf', 25, 'a_whoareyou_chat', 'shout'),
('string/en/poi/gangwar/imperial1.stf', 26, 'a_whoareyou_mood', 'angry'),
('string/en/poi/gangwar/imperial1.stf', 27, 'm_victory', 'I''m still alive?  I AM STILL ALIVE!!!  Take THAT you Imperial goons!'),
('string/en/poi/gangwar/imperial1.stf', 28, 'm_victory_mood', 'exuberant'),
('string/en/poi/gangwar/imperial1.stf', 29, 'm_victory_chat', 'shout'),
('string/en/poi/gangwar/imperial1.stf', 30, 'a_victory', 'Rebel uprising pacified.  No further activity detected in this area.  Good job team.'),
('string/en/poi/gangwar/imperial1.stf', 31, 'a_victory_chat', 'shout'),
('string/en/poi/gangwar/imperial1.stf', 32, 'a_victory_mood', 'callous'),
('string/en/poi/gangwar/imperial1.stf', 33, 'a_whatthehell', 'Unit under attack!  Take cover and return fire!'),
('string/en/poi/gangwar/imperial1.stf', 34, 'm_whatthehell', 'Not us!  Don''t shoot at us, we''re innocent!'),
('string/en/poi/gangwar/jabba1.stf', 1, 'a_insult1', 'Jabba set up this meeting so he could send Lady Valarian a message.'),
('string/en/poi/gangwar/jabba1.stf', 2, 'm_insult1_response', 'Jabba too afraid to come himself, eh?  Has to send his worrts to do the job?'),
('string/en/poi/gangwar/jabba1.stf', 3, 'a_insult2', 'Jabba has a very serious request.  He would like Lady Valarian to stop sitting down.'),
('string/en/poi/gangwar/jabba1.stf', 4, 'm_insult2_response', 'Sitting down?  What are you talking about?'),
('string/en/poi/gangwar/jabba1.stf', 5, 'a_insult3', 'Apparently several small villages have recently been crushed by your Lady''s fat posterior.  Jabba is concerned for the welfare of the citizens of our fine planet.'),
('string/en/poi/gangwar/jabba1.stf', 6, 'm_insult3_response', 'You filthy silt crawler.  You came here just to insult us?'),
('string/en/poi/gangwar/jabba1.stf', 7, 'a_insult4', 'No.  We came to kill you.  ATTACK!'),
('string/en/poi/gangwar/jabba1.stf', 8, 'a_whoareyou', 'Another piece of Valarian trash?  Die!'),
('string/en/poi/gangwar/jabba1.stf', 11, 'a_insult1_chat', 'say'),
('string/en/poi/gangwar/jabba1.stf', 12, 'a_insult1_mood', 'condescending'),
('string/en/poi/gangwar/jabba1.stf', 13, 'a_insult2_chat', 'say'),
('string/en/poi/gangwar/jabba1.stf', 14, 'a_insult2_mood', 'condescending'),
('string/en/poi/gangwar/jabba1.stf', 15, 'a_insult3_chat', 'say'),
('string/en/poi/gangwar/jabba1.stf', 16, 'a_insult3_mood', 'condescending'),
('string/en/poi/gangwar/jabba1.stf', 17, 'a_insult4_chat', 'shout'),
