('string/en/poi/wounded/template.stf', 5, 'm_5', 'random thing 5'),
('string/en/poi/wounded/template.stf', 6, 'm_greet', 'Hey there! You wouldn''t happen to have any medicine that you would be willing to share with some wounded folks that are out of bacta?'),
('string/en/poi/wounded/template.stf', 7, 'm_1_chat', ''),
('string/en/poi/wounded/template.stf', 8, 'm_1_mood', ''),
