('string/en/poi/wounded/template.stf', 24, 'm_greet_mood', ''),
('string/en/poi/wounded/template.stf', 33, 'response_yes', 'Yes'),
('string/en/poi/wounded/template.stf', 34, 'response_no', 'No'),
('string/en/poi/wounded/template.stf', 35, 'm_yes', 'You''ll help? Great!! But, there is only one problem. My crew will only let me administer the medication to them... If you give me one medicine per member of my crew, we would be quite grateful.'),
('string/en/poi/wounded/template.stf', 36, 'm_yes_act', ''),
('string/en/poi/wounded/template.stf', 37, 'm_yes_chat', ''),
('string/en/poi/wounded/template.stf', 38, 'm_yes_mood', ''),
('string/en/poi/wounded/template.stf', 39, 'm_willing', 'You can just hand me the medication and I will dispense it. Remember, I need one item of medicine for each member of my crew.'),
('string/en/poi/wounded/template.stf', 40, 'm_willing_act', ''),
('string/en/poi/wounded/template.stf', 41, 'm_willing_chat', ''),
('string/en/poi/wounded/template.stf', 42, 'm_willing_mood', ''),
('string/en/poi/wounded/template.stf', 43, 'm_rejected', 'Please tell me that you have changed your mind! Have you?'),
('string/en/poi/wounded/template.stf', 44, 'm_rejected_act', ''),
('string/en/poi/wounded/template.stf', 45, 'm_rejected_chat', ''),
('string/en/poi/wounded/template.stf', 46, 'm_rejected_mood', '');
