('string/en/poi/wounded/template.stf', 47, 'response_no_again', 'No'),
('string/en/poi/wounded/template.stf', 48, 'm_enraged', 'I asked twice. You declined to aid us twice. Just leave us be!'),
('string/en/poi/wounded/template.stf', 49, 'm_enraged_act', ''),
('string/en/poi/wounded/template.stf', 50, 'm_enraged_chat', ''),
('string/en/poi/wounded/template.stf', 51, 'm_enraged_mood', ''),
('string/en/poi/wounded/template.stf', 52, 'm_combat_1', 'OUCH!'),
('string/en/poi/wounded/template.stf', 53, 'm_combat_2', 'YEOWWW!!'),
('string/en/poi/wounded/template.stf', 54, 'm_combat_3', 'Gimme a hand!!'),
('string/en/poi/wounded/template.stf', 55, 'm_combat_4', 'HELP!!'),
('string/en/poi/wounded/template.stf', 56, 'm_combat_5', 'GET IT OFF ME!!'),
('string/en/poi/wounded/template.stf', 57, 'm_medicine', 'Thanks for the help, but we could use a few more medpacks, if you could spare them.'),
('string/en/poi/wounded/template.stf', 58, 'm_medicine_act', ''),
('string/en/poi/wounded/template.stf', 59, 'm_medicine_chat', ''),
('string/en/poi/wounded/template.stf', 60, 'm_medicine_mood', ''),
('string/en/poi/wounded/template.stf', 61, 'm_reward', 'Here is a little token of our appreciation for the help.'),
('string/en/poi/wounded/template.stf', 62, 'm_reward_act', ''),
('string/en/poi/wounded/template.stf', 63, 'm_reward_chat', ''),
('string/en/poi/wounded/template.stf', 64, 'm_reward_mood', ''),
('string/en/poi/wounded/template.stf', 65, 'm_completed', 'We appreciate the thought, but I don''t think we need anything else!'),
('string/en/poi/wounded/template.stf', 66, 'm_completed_act', ''),
('string/en/poi/wounded/template.stf', 67, 'm_completed_chat', ''),
('string/en/poi/wounded/template.stf', 68, 'm_completed_mood', ''),
('string/en/poi/wounded/template.stf', 69, 'item_not_medicine', 'I really only need medicines. You keep it.'),
('string/en/poi/wounded/template.stf', 70, 'item_not_medicine_act', ''),
('string/en/poi/wounded/template.stf', 71, 'item_not_medicine_chat', ''),
('string/en/poi/wounded/template.stf', 72, 'item_not_medicine_mood', ''),
('string/en/poi/wounded/template.stf', 73, 'reward', 'Thank you for your assistance.'),
('string/en/poi/wounded/template.stf', 74, 'reward_act', ''),
