('string/en/pvp_rating.stf', 1, 'killed1', 'You have been killed by %TT. Your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 2, 'killed2', 'You have fallen prey to %TT. Your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 3, 'killed3', 'You have perished at the hand of %TT. Your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 4, 'win1', 'You have fought valiantly against %TT.  For your part in their death your player combat rating has been adjusted to %DI.'),
('string/en/pvp_rating.stf', 5, 'win2', 'You have killed %TT. For your part in their death your player combat rating has been adjusted to %DI.'),
('string/en/pvp_rating.stf', 6, 'win3', 'You have fearlessly slain your foe %TT.  For your part in their death your player combat rating has been adjusted to %DI.'),
('string/en/pvp_rating.stf', 7, 'trandoshan_win1', 'You have honored The Scorekeeper with your victory against %TT.  You have been awared a quantity of Jagannath points for your involvement in their death.  Your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 8, 'trandoshan_win2', 'The Scorekeeper has awarded you with a quantity of Jagannath points for your part in the decimation of %TT.  Your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 9, 'trandoshan_win3', 'For skillfully shedding the blood of %TT, the The Scorekeeper has awarded you with a quantity of Jagannath points.  Given your part in their death, your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 10, 'trandoshan_killed1', 'In dying miserably to %TT, you have shamed yourself before The Scorekeeper.  As a result she has stripped a quantity of Jagannath points from you.  Your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 11, 'trandoshan_killed2', 'You have fallen shamefully to %TT.  Having disgraced yourself in the eyes of The Scorekeeper, she has revoked a number of Jagannath points from you.  Your new rating is %DI.'),
('string/en/pvp_rating.stf', 12, 'trandoshan_killed3', 'You have been slaughtered by %TT.  For failing her, The Scorekeeper has revoked a number of your Jagannath points.  Your new player combat rating is %DI.'),
('string/en/pvp_rating.stf', 13, 'rating_floor_trandoshan_loser', 'Although you have disgraced yourself before The Scorekeeper in dying to %TT, you have no more Jagannath points to lose.  Your player combat rating remains at %DI.'),
('string/en/pvp_rating.stf', 14, 'rating_floor_victim', 'Although you have fallen at the hands of %TT,  your cannot lose any more rating points at this time.  Your player combat rating remains at %DI.'),
('string/en/pvp_rating.stf', 15, 'rating_floor_winner', 'Although you have valiantly defeated %TT in combat, you can reap no more combat rating points from %PT death at this time.  Your player combat rating remains at %DI.'),
('string/en/pvp_rating.stf', 16, 'rating_throttle_winner', 'You have once again bested %TT in combat, but you cannot earn more points from their death so soon.  A true warrior must diversify %PU enemies.'),
('string/en/pvp_rating.stf', 17, 'rating_throttle_loser', 'You have once again been defeated by %TT, but you cannot lose more rating points to them so soon.  Your player combat rating remains at %DI.'),
('string/en/pvp_rating.stf', 18, 'rating_throttle_trandoshan_loser', 'Although you have once again fallen disgracefully at the hand of %TT,  The Scorekeeper has chosen not to penalize your Jagannath points again so soon.  Let the shame and dishonor of defeat be your payment to The Scorekeeper.  Your player combat rating remains at %DI.'),
('string/en/pvp_rating.stf', 19, 'rating_throttle_trandoshan_winner', 'Although you once again bathe yourself in the demise of %TT, The Scorekeeper will not award Jagannath points to you again so soon for their death.  A true warrior must diversify %PU prey.  Your player combat rating reamins at %DI.'),
('string/en/pvp_rating.stf', 20, 'rating_floor_trandoshan_winner', 'Although you have honorably defeated your foe %TT, The Scorekeeper can award you no Jagannath points for this victory as your opponent can be disgraced no further.  Your player combat rating remains at %DI.'),
('string/en/pvp_rating.stf', 25, 'councilpurge_init', 'Council Leader %TT has invoked %PT powers to purge the Council of all members.  Every member of the Council is now freely attackable by any ranked Jedi (excluding rank zero), and vice versa.  The order to purge the Council will stand for one week.  If any Council member is defeated by a ranked Jedi during this time, they will be demoted to Rank zero.'),
('string/en/pvp_rating.stf', 27, 'suddendeath_target', 'Voting has begun for the Force rank that you have petitioned for.  During the voting period you are freely attackable by any other Dark Jedi petitioning for the same position as you are.  Any Jedi who is defeated by another petitioning Jedi during this period will forfeit their petition AND any accumilated votes to the winning Jedi.'),
('string/en/pvp_rating.stf', 28, 'pvp_action_message', 'Dark Jedi Combat Notification'),
('string/en/pvp_rating.stf', 32, 'dark_jedi_kill_won_votes', 'You have earned %DI votes for defeating %TT in combat.'),
('string/en/pvp_rating.stf', 33, 'dark_jedi_kill_lost_votes', 'For dying to another petitioning Jedi, you have lost all of your votes.  You have also relinquished your rights to petition during the current voting period.'),
('string/en/pvp_rating.stf', 34, 'vendetta_initiator_start', 'You have declared a vendetta against %TT.  If either of you perish in combat against one another, the loser will be demoted to Force rank zero.  Should neither of you lose to the other over the course of the next 7 days, the vendetta will expire.'),
('string/en/pvp_rating.stf', 35, 'vendetta_target_start', '%TT had declared a vendetta against you!  If either of you perish in combat against one another, the loser will be demoted to Force rank zero.  Should neither of you lose to the other over the course of the next 7 days, the vendetta will expire.'),
('string/en/pvp_rating.stf', 36, 'banishment_start', 'The Dark Council has called for %TT to be banished from the ranks.  If any ranked Jedi defeats %TT over the course of the next 7 days, %TT will be demoted to rank zero.  If %ST has not been defeated by 7 days from now, the banishment will expire.'),
('string/en/pvp_rating.stf', 37, 'purge_start', 'The Dark Council Leader has called for the Council to be purged! .  If any ranked Jedi defeats a Dark Council member over the course of the next 7 days, they will be demoted to rank zero.  If a Council member has not been defeated by 7 days from now, the order to purge the council will expire.'),
('string/en/pvp_rating.stf', 38, 'sudden_death_start', 'Voting has begun for the rank you have petitioned for.  All petitioning Jedi in your rank are now at war with one another.  Should you defeat a fellow petitioning Jedi, you will gain all of their accumilated votes as well knock them out of the race.  Take heed, however, as the same could happen to you.'),
('string/en/pvp_rating.stf', 39, 'vendetta_end_timeout', 'The vendetta between you and %TT has expired.   Neither Jedi has defeated the other in the alotted time.'),
('string/en/pvp_rating.stf', 40, 'sudden_death_death', '%TT has fallen to a fellow rank petitioner.  Any votes they may have had accumilated have been divided amongs those that took part in the slaughter of %TT.  Let this be a lesson in how the Council deals with failure.'),
('string/en/pvp_rating.stf', 41, 'sudden_death_timeout', 'You have survied the voting period for your rank.  You are no longer at war with your fellow petitioners.'),
('string/en/pvp_rating.stf', 42, 'pvp_action_end_death', 'After being targeted by the Council for removal from the ranks, %TT has fallen to a fellow Dark Jedi.  They have thus been demoted to rank zero.  Take notice of the Council''s reward for such weakness.'),
('string/en/pvp_rating.stf', 43, 'banishment_end_timeout', '%TT is no longer a target of banishment from the ranks as the the Council''s order has expired.'),
('string/en/pvp_rating.stf', 44, 'councilpurge_timout', 'The Council Leader''s order to purge the Council has expired.  Any Council member that was not slain will retain their seat in the Council.'),
('string/en/pvp_rating.stf', 45, 'challenge_issued_rank', '%TT has issued a challenge against your rank!  If you wish to defend the honor of your rank, find the challenge terminal in the Dark Jedi enclave and accept the challenge.  You have 60 minutes to do so, starting now.  Should you accept and lose the challenge, you will be demoted into the rank below yours, while %TT will take your position.'),
('string/en/pvp_rating.stf', 46, 'challenge_issued_challenger', 'You have issued a challenge against rank %DI.  Any member of that rank may accept your challenge during the next 60 minutes.  Should a rank member accept your challenge and you are not present in the enclave (or you are dead), you will lose the challenge by default.  If you are not in the arena hall when the challange is accepted you will be teleported there as long as you are within the walls of the enclave.  Should you win the challenge, you will be granted a position in rank %DI.  Should you lose the challenge, you will lose a quantity of Force RankXP.'),
('string/en/pvp_rating.stf', 47, 'challenge_issued_subject_header', 'A Challenge has been Issued!'),
('string/en/pvp_rating.stf', 48, 'challenge_accepted', '%TU has stepped forward to accept a challenge against rank %DI, issued by %TT.  A battle to the death is commencing in the arena at the hidden enclave.'),
('string/en/pvp_rating.stf', 49, 'challenge_concluded_challenger_won', '%TU was defeated by %TT during a battle for the honor of rank %DI.  As a result %TU has been demoted from rank %DI, while %TT has taken their place.'),
('string/en/pvp_rating.stf', 50, 'challenge_accepted_subject_header', 'Challenge Accepted!'),
('string/en/pvp_rating.stf', 51, 'challenge_concluded_subject_header', 'Challenge Concluded!'),
('string/en/pvp_rating.stf', 52, 'challenge_concluded_defender_win', '%TU has defeated %TT during a battle for the honor of rank %DI.  As a result, %TU will remain at their station in rank %DI, while %TT will live in shame for their defeat.'),
('string/en/pvp_rating.stf', 53, 'challenge_concluded_timeout', 'Although a challenge had been issued, no one in rank %DI saw fit to defend the honor of their rank by accepting the challenge issued by %TT.  The challenge has thus expired.'),
('string/en/pvp_rating.stf', 54, 'challenge_timout_subject_header', 'Challenge Remains Unanswered!'),
('string/en/pvp_rating.stf', 55, 'ch_terminal_view_scores', 'View Challenge Scores'),
('string/en/pvp_rating.stf', 56, 'ch_terminal_view_challenges', 'View Issued Challenges'),
('string/en/pvp_rating.stf', 57, 'ch_terminal_accept_challenge', 'Accept a Challenge'),
('string/en/pvp_rating.stf', 58, 'ch_terminal_issue_challenge', 'Issue Challenge'),
('string/en/pvp_rating.stf', 59, 'ch_terminal_cant_challenge_rank', 'You are unable to issue a challenge until you are at least rank one.'),
('string/en/pvp_rating.stf', 62, 'ch_terminal_demote_rank_penalty', 'The members of rank %DI have failed to answer numerous challenges issued by the Dark Jedi of the enclave.  As a result, the entire rank has been demoted to rank zero.  Weakness cannot be tolerated in the Council.'),
('string/en/pvp_rating.stf', 63, 'ch_terminal_demote_subject', 'Rank Demoted!'),
('string/en/pvp_rating.stf', 64, 'ch_rank_scores', 'A challenge score of zero denotes a rank that is meeting its challenges.  A negative score denotes ranks that have missed a number of challenges.  Once a rank reaches -8 points, every member of that rank will be demoted to rank zero.  Every time a rank fails to meet at least one challenge during a challenge period (which occurs once every 30 hours), they incur a -1 penalty.  Should no challenges be issued during a challenge period, that rank''s challenge score will return to zero.  If challenges were issued, the rank must answer at least 50% of the challenges for the score to return to zero, else the rank will incur a -1 score penalty even though some challenges may have been answered.'),
('string/en/pvp_rating.stf', 65, 'ch_select_active_challenges', 'Select the rank you wish to view challenges for.  If a rank is not listed here, that rank has no active challenges.'),
('string/en/pvp_rating.stf', 66, 'ch_no_challenges_to_view', 'There are no active challenges against any rank.'),
('string/en/pvp_rating.stf', 67, 'ch_terminal_arena_closed', 'The arena is not currently open for challenges.'),
('string/en/pvp_rating.stf', 68, 'ch_terminal_verify_challenge', 'Are you sure you wish to issue a challenge to the next rank?  The rank you are challenging has 60 minutes to answer the challenge.  Should you not be in the enclave when the challenge is accepted or should you be dead, you will concede the battle which will carry with it the same consequences as losing the battle.  Should you leave the arena during the battle, you will also concede.  If you are not in the arena when the challenge is accepted, you will be teleported into the arena as long as you are at least within the enclave.'),
('string/en/pvp_rating.stf', 69, 'ch_terminal_pending', 'Pending challenges for selected rank:'),
('string/en/pvp_rating.stf', 70, 'ch_terminal_no_challenges_for_rank', 'There are no pending challenges to accept for your rank.'),
('string/en/pvp_rating.stf', 71, 'ch_terminal_verify_accept_challenge', 'Are you certain you wish to accept the responsibility of defending the honor of your rank against the challengers?  The battle will be to the death.  Should you be bested in combat, your punishment will be demotion to the rank below yours, while the challenger will receive your position in the rank.  If you leave the arena during the battle you will concede the battle.'),
('string/en/pvp_rating.stf', 72, 'ch_terminal_choose_challenge', 'Choose the challenger that you wish to combat in defense of your rank''s honor!'),
('string/en/pvp_rating.stf', 73, 'ch_terminal_challenge_no_more', 'That challenger no longer has a challenge issued against your rank.'),
('string/en/pvp_rating.stf', 74, 'ch_terminal_challenge_wrong_rank', 'That player has not issued a challenge against your current rank.'),
('string/en/pvp_rating.stf', 75, 'ch_terminal_challenger_forfeit', 'The challenger has forfeit this battle by not being present and alive in the enclave to complete the duel.  Honor has been restored to your rank.'),
('string/en/pvp_rating.stf', 76, 'ch_terminal_challenger_forfeit_ch', 'Since you were not in the enclave, or you were dead,  when your challenge was accepted, you have conceded the battle.  Your honor has been tarnished significantly by your actions.'),
('string/en/pvp_rating.stf', 77, 'ch_terminal_cant_challenge_rank_bounds', 'You may not issue challenges at your current rank level.'),
('string/en/pvp_rating.stf', 78, 'ch_terminal_no_need_challenge', 'You do not need to challenge the rank as there are enough open seats available.  Use the Voting Terminal in the enclave to petition for one of these open slots.'),
('string/en/pvp_rating.stf', 79, 'ch_terminal_too_far', 'You are too far away from the terminal to use it.'),
('string/en/pvp_rating.stf', 80, 'ch_terminal_notenoughexp', 'You do not currently qualify for a promotion into the next rank.'),
('string/en/pvp_rating.stf', 81, 'ch_terminal_arena_status', 'Arena Status'),
('string/en/pvp_rating.stf', 82, 'ch_terminal_arena_close_in', 'The arena is currently open for challenges.  Challenges can be issued for another %TO.'),
('string/en/pvp_rating.stf', 83, 'ch_terminal_arena_open_in', 'The arena is currently closed.  The arena will be open for challenges again in %TO.'),
('string/en/pvp_rating.stf', 84, 'ch_terminal_arena_open_imminent', 'The arena is about to open for challenges.'),
('string/en/pvp_rating.stf', 85, 'ch_terminal_arena_close_imminent', 'The arena is about to close for challenges.'),
('string/en/pvp_rating.stf', 86, 'enclave_deny_entry', 'A strange force repels you and keeps you from entering.'),
('string/en/pvp_rating.stf', 87, 'pvp_rating', 'Your player vs. player combat rating is %DI.'),
('string/en/pvp_rating.stf', 88, 'pvp_rating_target', '%TT has a player vs. player combat rating of %DI.'),
('string/en/pvp_rating.stf', 90, 'enclave_deny_pet_entry', 'As you are not permitted to bring any pets or hirelings into the enclave.  They have been returned to your data pad for you.'),
('string/en/pvp_rating.stf', 91, 'arena_duelist_already_engaged', '%TT is already involved in a duel at the moment.  Please wait until that challenge concludes.'),
('string/en/pvp_rating.stf', 92, 'arena_incap_opponent', 'You have incapcitated your opponent.  If you deathblow them, be sure to stay in the arena until the match has completely resolved (you will get another message) or you may lose the challenge for abandoning the fight prematurely.'),
('string/en/quest/corvetter_trap.stf', 1, 'shocked', 'You feel electricity coursing through your body!'),
('string/en/quest/crafting_contract/system_messages.stf', 1, 'wrong_item', 'This item cannot be placed in that crate.'),
('string/en/quest/crafting_contract/system_messages.stf', 2, 'not_crafted', 'Only crafted items can be placed in the crate.'),
('string/en/quest/crafting_contract/system_messages.stf', 3, 'not_crafter', 'You are not the creator of this item. It cannot be placed in the crate.'),
('string/en/quest/crafting_contract/system_messages.stf', 4, 'already_complete', 'The order is already complete. No further items can be placed in the crate.'),
('string/en/quest/crafting_contract/system_messages.stf', 5, 'cannot_remove', 'Items for this crafting order cannot be removed once they are placed in the crate.'),
('string/en/quest/crafting_contract/system_messages.stf', 6, 'job_complete', 'JOB COMPLETE: All items needed for this order have been added to the crate.'),
('string/en/quest/crafting_contract/system_messages.stf', 7, 'items_remaining', 'You need %DI more item(s) to complete this order.'),
('string/en/quest/crafting_contract/system_messages.stf', 8, 'of', 'of'),
('string/en/quest/crafting_contract/system_messages.stf', 9, 'complete', 'Complete'),
('string/en/quest/crafting_contract/system_messages.stf', 10, 'required', 'required'),
('string/en/quest/crafting_contract/system_messages.stf', 11, 'pay_msg', 'You have received %DI credits as payment for your services.'),
('string/en/quest/crowd_pleaser/audience.stf', 1, 'neutral_0', 'It''s terribly hot today. I hope it cools down some.'),
('string/en/quest/crowd_pleaser/audience.stf', 2, 'neutral_1', 'I was stopped by an Imperial Officer today. Really ruined my mood.'),
('string/en/quest/crowd_pleaser/audience.stf', 3, 'neutral_2', 'I can''t believe my landspeeder broke down!'),
('string/en/quest/crowd_pleaser/audience.stf', 4, 'neutral_3', 'I can''t wait to see the performance tonight!'),
('string/en/quest/crowd_pleaser/audience.stf', 5, 'neutral_4', 'I really could use a drink.'),
('string/en/quest/crowd_pleaser/audience.stf', 6, 'neutral_5', 'The prices for weapons these days are just too high!'),
('string/en/quest/crowd_pleaser/audience.stf', 7, 'neutral_6', 'It''s such a beautiful day today! Don''t you agree?'),
('string/en/quest/crowd_pleaser/audience.stf', 8, 'neutral_7', 'It''s fun visiting other planets. You should too!'),
('string/en/quest/crowd_pleaser/audience.stf', 9, 'neutral_8', 'My harvester ran out of power. I''m so disappointed.'),
('string/en/quest/crowd_pleaser/audience.stf', 10, 'neutral_9', 'The resources in this area are just plain bad.'),
('string/en/quest/crowd_pleaser/audience.stf', 11, 'neutral_36', 'I saw a Jedi once. I think I had too much spice that day, though.'),
('string/en/quest/crowd_pleaser/audience.stf', 12, 'neutral_11', 'Isn''t my outfit great? I think so.'),
('string/en/quest/crowd_pleaser/audience.stf', 13, 'neutral_12', 'My sales have gone down. Do you think it may be because I sell clothes with holes in them?'),
('string/en/quest/crowd_pleaser/audience.stf', 14, 'neutral_13', 'Rebels are a sneaky bunch. I guess they have to be these days.'),
('string/en/quest/crowd_pleaser/audience.stf', 15, 'neutral_14', 'Why am I even here today? I hope I get in a better mood!'),
('string/en/quest/crowd_pleaser/audience.stf', 16, 'neutral_39', 'Are you lost? Because I am.'),
('string/en/quest/crowd_pleaser/audience.stf', 17, 'neutral_16', 'I hope to become a Bounty Hunter one day!'),
('string/en/quest/crowd_pleaser/audience.stf', 18, 'neutral_17', 'I want to be a dancer. Do you think I have a chance?'),
('string/en/quest/crowd_pleaser/audience.stf', 19, 'neutral_18', 'A doctor healed my wound today. And yes, I tipped him.'),
('string/en/quest/crowd_pleaser/audience.stf', 20, 'neutral_19', 'Dancers in cantinas always seem to be... well, spaced out. Why is that?'),
('string/en/quest/crowd_pleaser/audience.stf', 21, 'neutral_37', 'Krayt Dragons are pretty scary. I''m so glad I''ll never see one!'),
('string/en/quest/crowd_pleaser/audience.stf', 22, 'neutral_21', 'I need to repair my vehicle later. Remind me, okay?'),
('string/en/quest/crowd_pleaser/audience.stf', 23, 'neutral_22', 'Imperials are often bossy and in a bad mood. They must not get paid well.'),
('string/en/quest/crowd_pleaser/audience.stf', 24, 'neutral_23', 'I don''t mean to be rude, but your clothes don''t match.'),
('string/en/quest/crowd_pleaser/audience.stf', 25, 'neutral_24', 'I had a chef make me a meal today. It was horrible!'),
('string/en/quest/crowd_pleaser/audience.stf', 26, 'neutral_40', 'I think Wookiees are really hairy. I mean TOO hairy.'),
('string/en/quest/crowd_pleaser/audience.stf', 27, 'neutral_26', 'I''m going to decorate my house today! I can''t wait!'),
('string/en/quest/crowd_pleaser/audience.stf', 28, 'neutral_27', 'I''ve got great news! I just saved money on my cloning insurance!'),
('string/en/quest/crowd_pleaser/audience.stf', 29, 'neutral_28', 'You should stop and smell the flowers sometimes.'),
('string/en/quest/crowd_pleaser/audience.stf', 30, 'neutral_29', 'I really think Rancors are cute. Don''t you?'),
('string/en/quest/crowd_pleaser/audience.stf', 31, 'neutral_38', 'Stop by my store sometime. I sell the best jewelry in the galaxy!'),
('string/en/quest/crowd_pleaser/audience.stf', 32, 'neutral_31', 'A jawa stole my droid once. I got it back, though.'),
('string/en/quest/crowd_pleaser/audience.stf', 33, 'neutral_32', 'You know... I really don''t think you''re very good at your profession.'),
('string/en/quest/crowd_pleaser/audience.stf', 34, 'neutral_33', 'I think we should have stickers on our landspeeders. "I brake for Wookiees.", What do you think of that one?! Funny, huh? HA!'),
('string/en/quest/crowd_pleaser/audience.stf', 35, 'neutral_34', 'I think that color looks great on you!'),
('string/en/quest/crowd_pleaser/audience.stf', 36, 'neutral_35', 'I really can''t dance, or sing, but I like watching the performances.'),
('string/en/quest/crowd_pleaser/audience.stf', 37, 'neutral_10', 'I''m really looking forward to the show!'),
('string/en/quest/crowd_pleaser/audience.stf', 38, 'neutral_20', 'Are you the one performing tonight?'),
('string/en/quest/crowd_pleaser/audience.stf', 39, 'neutral_30', 'It''s good to get away from the daily grind and come see a show every now and then. You know what I mean?'),
('string/en/quest/crowd_pleaser/audience.stf', 40, 'neutral_15', 'This is my favorite theater. I come here all the time.'),
('string/en/quest/crowd_pleaser/audience.stf', 41, 'neutral_25', 'Have you ever heard of this performer before? I haven''t. Maybe it''ll be a good show anyway.'),
('string/en/quest/crowd_pleaser/audience.stf', 42, 'positive_0_f', 'I really hope to see flourish %TO.'),
('string/en/quest/crowd_pleaser/audience.stf', 43, 'positive_0_d', 'I really hope to see the %TO dance.'),
('string/en/quest/crowd_pleaser/audience.stf', 44, 'positive_0_m', 'I really hope to hear the %TO song.'),
('string/en/quest/crowd_pleaser/audience.stf', 45, 'positive_1_f', 'I hope flourish %TO is done correctly. I think it will be great!'),
('string/en/quest/crowd_pleaser/audience.stf', 46, 'positive_1_d', 'I hope the %TO dance is done correctly. I think it will be great!'),
('string/en/quest/crowd_pleaser/audience.stf', 47, 'positive_1_m', 'I hope the %TO song is done correctly. I think it will be great!'),
('string/en/quest/crowd_pleaser/audience.stf', 48, 'positive_2_f', 'I hear this performer can do flourish %TO. Maybe I''ll get to see it!'),
('string/en/quest/crowd_pleaser/audience.stf', 49, 'positive_2_d', 'I hear this performer can do the %TO dance. Maybe I''ll get to see it!'),
('string/en/quest/crowd_pleaser/audience.stf', 50, 'positive_2_m', 'I hear this performer can play the %TO song. Maybe I''ll get to hear it!'),
('string/en/quest/crowd_pleaser/audience.stf', 51, 'positive_3_f', 'I''ve seen flourish %TO before. I really like it!'),
('string/en/quest/crowd_pleaser/audience.stf', 52, 'positive_3_d', 'I''ve seen the %TO dance before. I really like it!'),
('string/en/quest/crowd_pleaser/audience.stf', 53, 'positive_3_m', 'I''ve heard the %TO song before. I really like it!'),
('string/en/quest/crowd_pleaser/audience.stf', 54, 'positive_4_f', 'Do you think we''ll see flourish %TO? I hope so.'),
('string/en/quest/crowd_pleaser/audience.stf', 55, 'positive_4_d', 'Do you think we''ll see the %TO dance? I hope so.'),
('string/en/quest/crowd_pleaser/audience.stf', 56, 'positive_4_m', 'Do you think we''ll hear the %TO song? I hope so.'),
('string/en/quest/crowd_pleaser/audience.stf', 57, 'positive_5_f', 'If I don''t get to see flourish %TO, I''ll be really disappointed.'),
('string/en/quest/crowd_pleaser/audience.stf', 58, 'positive_5_d', 'If I don''t get to see the %TO dance, I''ll be really disappointed.'),
('string/en/quest/crowd_pleaser/audience.stf', 59, 'positive_5_m', 'If I don''t get to hear the %TO song, I''ll be really disappointed.'),
('string/en/quest/crowd_pleaser/audience.stf', 60, 'negative_0_f', 'I''ve seen flourish %TO a million times. I want to see something different.'),
('string/en/quest/crowd_pleaser/audience.stf', 61, 'negative_0_d', 'I''ve seen the %TO dance a million times. I want to see something different.'),
('string/en/quest/crowd_pleaser/audience.stf', 62, 'negative_0_m', 'I''ve heard the %TO song a million times. I want to hear something different.'),
('string/en/quest/crowd_pleaser/audience.stf', 63, 'negative_1_f', 'Flourish %TO is so old. We should see something new.'),
('string/en/quest/crowd_pleaser/audience.stf', 64, 'negative_1_d', 'The %TO dance is so old. We should see something new.'),
('string/en/quest/crowd_pleaser/audience.stf', 65, 'negative_1_m', 'The %TO song is so old. We should hear something new.'),
('string/en/quest/crowd_pleaser/audience.stf', 66, 'negative_2_f', 'I''ve never really liked flourish %TO, to be honest.'),
