('string/en/quest/crowd_pleaser/system_messages.stf', 15, 'popularity_starting_message', 'You must entertain %DI players to acquire the next popularity rank.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 16, 'audition_time_remaining', 'You have thirty seconds to be on stage, ready to begin the audition.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 17, 'audition_begin', 'The audition has begun! Listen to and follow the instructions given to you by the judges.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 18, 'audition_step_1', 'Hello and welcome. Begin by performing %TO for us, please.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 19, 'audition_step_2', 'Very good. Now perform flourish %DI for us, please.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 20, 'audition_step_3', 'Good. Perform flourish %DI now, please.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 21, 'audition_step_4', 'Excellent. Now change the style and perform %TO, please.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 22, 'audition_step_5', 'Good, good. And perform flourish %DI, please.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 23, 'audition_step_6', 'Yes, good. And now flourish %DI, please.'),
('string/en/quest/crowd_pleaser/system_messages.stf', 24, 'fail_left_audition_area', '[ \\#pcontrast2 FAILURE \\#.] You have left the main stage area during the audition.'),
