('string/en/quest/crowd_pleaser/system_messages.stf', 35, 'reaction_3_5', 'Slightly Unsatisfied'),
('string/en/quest/force_sensitive/exit.stf', 1, 'taunt1', '%TT, You shall pay for your tresspass here - SOLDIERS - defend the crystals! Let no one leave here alive.'),
('string/en/quest/force_sensitive/exit.stf', 2, 'taunt2', 'This cannot be! Soldiers protect Mellichae immediately!'),
('string/en/quest/force_sensitive/exit.stf', 3, 'taunt3', '%TT, You may have destroyed my power crystals, but now I will destroy you!  SOLDIERS ATTACK!!!'),
('string/en/quest/force_sensitive/exit.stf', 4, 'old_man_greeting', '%TT.  It is good to see you again.  I have some urgent news to share with you!'),
('string/en/quest/force_sensitive/exit.stf', 5, 'old_man_exit', 'Very well then %TT,  I shall return another time!'),
('string/en/quest/force_sensitive/exit.stf', 6, 'leave', 'Well it appears you are busy,  I will return later.'),
('string/en/quest/force_sensitive/exit.stf', 7, 'exit_sum', 'Find Mellichae''s camp.'),
('string/en/quest/force_sensitive/exit.stf', 8, 'exit_detail', 'Defeat Mellichae at his camp.'),
('string/en/quest/force_sensitive/exit.stf', 9, 'final_complete', 'Congratulations, you have completed the Force sensitive quests! You are now qualified to begin the Jedi Padawan Trials.\n'),
('string/en/quest/force_sensitive/exit.stf', 10, 'final_fail', 'You have failed the Mellichae encounter, you will be given the oppertunity to attempt it again in the near future.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 1, 'menu_access_terminal', 'Access Terminal'),
('string/en/quest/force_sensitive/fs_crafting.stf', 2, 'sui_btn_retrieve', 'Retrieve'),
('string/en/quest/force_sensitive/fs_crafting.stf', 3, 'sui_btn_replace', 'Replace'),
('string/en/quest/force_sensitive/fs_crafting.stf', 4, 'sui_access_terminal_title', 'Sensor Array - Access Terminal'),
('string/en/quest/force_sensitive/fs_crafting.stf', 5, 'sui_access_terminal_prompt0', 'Press ''Retrieve'' to retrieve a component from its socket.\nPress ''Replace'' to replace a component into its socket.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 6, 'sui_access_terminal_prompt1', 'Sensor array status:'),
('string/en/quest/force_sensitive/fs_crafting.stf', 7, 'sui_access_terminal_prompt2', 'Diagnostic report follows...'),
('string/en/quest/force_sensitive/fs_crafting.stf', 8, 'sui_access_terminal_offline', 'OFFLINE'),
('string/en/quest/force_sensitive/fs_crafting.stf', 9, 'sui_access_terminal_online', 'ONLINE'),
('string/en/quest/force_sensitive/fs_crafting.stf', 10, 'sui_access_terminal_empty', '[COMPONENT NOT FOUND]'),
('string/en/quest/force_sensitive/fs_crafting.stf', 11, 'sui_access_terminal_damaged', '<COMPONENT DAMAGED>'),
('string/en/quest/force_sensitive/fs_crafting.stf', 12, 'sui_access_terminal_operational', '(COMPONENT OPERATIONAL)'),
('string/en/quest/force_sensitive/fs_crafting.stf', 13, 'phase1_msg_comp_not_installed', 'COMPONENT NOT FOUND: That component is not currently installed and is unable to be retrieved.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 14, 'phase1_msg_inventory_full', 'Your inventory is currently full. Please clear some space and try again.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 15, 'phase1_msg_already_have_component', 'You already have that component in your possession.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 16, 'phase1_msg_component_retrieved', 'You have successfully retrieved a component from the sensor array.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 17, 'phase1_msg_component_analyzed', 'The recursive analyzer deconstructs the component and loads a draft schematic into your datapad. The schematic will now remain resident in the analyzer memory. If you need to access another schematic, simply use the analyzer again.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 18, 'sui_analyzer_title', 'Recursive Analyzer'),
('string/en/quest/force_sensitive/fs_crafting.stf', 19, 'sui_analyzer_prompt0', 'Please choose if you would like to deconstruct and create a draft schematic from a component in your inventory, or if you would like to load an existing draft schematic from memory:'),
('string/en/quest/force_sensitive/fs_crafting.stf', 20, 'sui_analyzer_prompt1', 'Please choose a component to place inside the recursive analyzer:'),
('string/en/quest/force_sensitive/fs_crafting.stf', 21, 'sui_analyzer_prompt2', 'Please choose a draft schematic to load:'),
('string/en/quest/force_sensitive/fs_crafting.stf', 22, 'sui_analyzer_analyze_component', 'Deconstruct a Component'),
('string/en/quest/force_sensitive/fs_crafting.stf', 23, 'sui_analyzer_get_schematic', 'Load Schematic from Memory'),
('string/en/quest/force_sensitive/fs_crafting.stf', 24, 'sui_analyzer_no_comp', 'You do not currently have any components that are able to be used with the recursive analyzer.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 25, 'sui_analyzer_no_schematic', 'The recursive analyzer does not currently  have any schematics loaded into its memory.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 26, 'menu_use_analyzer', 'Use Analyzer'),
('string/en/quest/force_sensitive/fs_crafting.stf', 27, 'phase1_msg_schematic_loaded', 'You have loaded a draft schematic from the recursive analyzer into your datapad.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 28, 'menu_use_calibrator', 'Use Calibrator'),
('string/en/quest/force_sensitive/fs_crafting.stf', 29, 'sui_calibrator_title', 'Multi-phase Calibrator'),
('string/en/quest/force_sensitive/fs_crafting.stf', 30, 'sui_calibrator_prompt', 'Choose an item to use in the multi-phase calibrator.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 31, 'sui_calibrator_no_comp', 'You do not currently  have any items that are able to be used in the multi-phase calibrator.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 32, 'phase1_msg_cant_open_sui', 'You are too busy to do that now.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 33, 'sui_attempts_remaining', 'Integrity:'),
('string/en/quest/force_sensitive/fs_crafting.stf', 34, 'sui_config_title', 'Configuration Processor'),
('string/en/quest/force_sensitive/fs_crafting.stf', 35, 'sui_config_description', 'Press the small triangular buttons to adjust the configuration setting so that the component configuration (top pattern) matches the expected configuration (bottom pattern). Pressing a button will toggle its illumination state, as well as the state of two other buttons.\n\nCalibration will have a detrimental effect on the integrity of a component. If the integrity of a component reaches 0%, or if the calibration process is interrupted before completion, the component will be rendered useless and a new one must be crafted and calibrated.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 36, 'phase1_msg_component_replaced', 'You have replaced a component into its socket in the sensor array.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 37, 'sui_calibration_success', 'This component has been successfully calibrated and is operating within acceptable parameters.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 38, 'sui_calibration_failure', 'Calibration of this component was not complete due to integrity failure. Further calibration of this item is not possible. Please insert a new component to continue.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 39, 'sui_gyro_title', 'Gyroscopic Receiver'),
('string/en/quest/force_sensitive/fs_crafting.stf', 40, 'sui_gyro_description', 'Use the sliders on the right to adjust the geographical resolution so that the component parameters (top shades) match the expected parameters (bottom shades). Changes made to the sliders will not be reflected in real-time. You must press the "OK" button in order to view your changes.\n\nCalibration will have a detrimental effect on the integrity of a component. If the integrity of a component reaches 0%, or if the calibration process is interrupted before completion, the component will be rendered useless and a new one must be crafted and calibrated.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 41, 'sui_gyro_slider1', 'Longitude Resolution'),
('string/en/quest/force_sensitive/fs_crafting.stf', 42, 'sui_gyro_slider2', 'Latitude Resolution'),
('string/en/quest/force_sensitive/fs_crafting.stf', 43, 'sui_gyro_slider3', 'Vertical Resolution'),
('string/en/quest/force_sensitive/fs_crafting.stf', 44, 'sui_amp_title', 'Signal Amplifier'),
('string/en/quest/force_sensitive/fs_crafting.stf', 45, 'sui_amp_description', 'Use the sliders on the right to adjust the frequency amplification so that the component output (top graph) matches the expected output (bottom graph). Changes made to the sliders will not be reflected in real-time. You must press the "OK" button in order to view your changes.\n\nCalibration will have a detrimental effect on the integrity of a component. If the integrity of a component reaches 0%, or if the calibration process is interrupted before completion, the component will be rendered useless and a new one must be crafted and calibrated.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 46, 'sui_amp_slider1', 'Pre-amp Boost'),
('string/en/quest/force_sensitive/fs_crafting.stf', 47, 'sui_amp_slider2', 'Amplification'),
('string/en/quest/force_sensitive/fs_crafting.stf', 48, 'sui_amp_slider3', 'Post-amp Tuning'),
('string/en/quest/force_sensitive/fs_crafting.stf', 49, 'sui_ssa_title', 'Solid State Array'),
('string/en/quest/force_sensitive/fs_crafting.stf', 50, 'sui_ssa_description', 'Use the sliders on the right to adjust the solid state devices (represented by the horizontal bars) so that they are aligned around the transmission bus (vertical line). Changes made to the sliders will not be reflected in real-time. You must press the "OK" button in order to view your changes.\n\nCalibration will have a detrimental effect on the integrity of a component. If the integrity of a component reaches 0%, or if the calibration process is interrupted before completion, the component will be rendered useless and a new one must be crafted and calibrated.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 51, 'sui_ssa_slider1', 'Element One Alignment'),
('string/en/quest/force_sensitive/fs_crafting.stf', 52, 'sui_ssa_slider2', 'Element Two Alignment'),
('string/en/quest/force_sensitive/fs_crafting.stf', 53, 'sui_ssa_slider3', 'Element Three Alignment');
