('string/en/quest/force_sensitive/fs_crafting.stf', 117, 'crafting4_core_ruined', 'The circuitry of the computer core has sustained too much damage and is no longer able to be used. It will now self-destruct.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 118, 'crafting4_core_current_status_06', '\n\nLast Tested Configuration:'),
