('string/en/quest/force_sensitive/fs_crafting.stf', 122, 'crafting4_core_current_result', 'Testing Result:\n'),
('string/en/quest/force_sensitive/fs_crafting.stf', 123, 'crafting4_core_completed_status', 'This computer core has been successfully reconfigured.'),
('string/en/quest/force_sensitive/fs_crafting.stf', 124, 'crafting4_core_current_status_01', 'Current Configuration:'),
