('string/en/quest/groundquests.stf', 7, 'destroy_and_loot_counter', 'Found'),
('string/en/quest/groundquests.stf', 8, 'retrieve_item_counter', 'Retrieved'),
('string/en/quest/groundquests.stf', 9, 'timer_timertext', 'Time Remaining'),
('string/en/quest/hero_of_tatooine/auth_chat.stf', 1, 'auth_01', 'We''re here to take you away!'),
('string/en/quest/hero_of_tatooine/auth_chat.stf', 2, 'auth_02', 'Give up! It''s all over!'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 1, 'greeting_0', 'I came to this town to take on a big assignment, but I can''t do anything now with that bounty hunter hanging around.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 2, 'greeting_1', 'Business is good!  I just moved twice my normal load this week.  Now if that bounty hunter would get lost I could get back to work.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 3, 'greeting_2', 'Until this bounty hunter moves on, I won''t be able to inspect that new shipment I just received.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 4, 'greeting_3', 'The Empire has been pretty busy with the Rebellion lately.  Makes it easy to slip past with extra goods.  I would think they sent that bounty hunter to investigate, but she doesn''t seem very smart.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 5, 'greeting_4', 'I love my job.  The thrill of a light cruiser pushing past a blockade at full speed!  You never feel that way down here on the surface.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 6, 'greeting_5', 'I''ve got a flight path to plan, but that idiot of a bounty hunter keeps interrupting me with questions.  Kinda like you.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 7, 'greeting_6', 'Smuggling has been tough with the Empire''s recent crackdown.  The rebels hurt them bad and now everyone''s feeling the effects.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 8, 'greeting_7', 'I wonder how long until that bounty hunter gives up or just kills us all?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 9, 'greeting_8', 'Look, I really need to think about my next job.  What is it that you want?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 10, 'greeting_9', 'What is it? I''m very very busy.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 11, 'greeting_10', 'Curse the luck. I''ve got a package coming in today, but that bounty hunter won''t let me leave.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 12, 'greeting_11', 'I just want to get back to work. I''m tired of answering questions.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 13, 'response_0', 'What do you know about the stolen equipment?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 14, 'response_1', 'What do you know about the other smugglers?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 15, 'response_2', 'Thank you for your time.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 16, 'equipment_0', 'I don''t know anything about the stolen equipment.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 17, 'equipment_1', 'I don''t know nothin'' about no stolen equipment.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 18, 'equipment_2', 'Look, what I do might not be legal, but I don''t steal.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 19, 'equipment_3', 'I''ll tell you what I told that bounty hunter. I didn''t steal anything.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 20, 'equipment_4', 'Don''t you two have anything better to do than hound me with questions? Get off my back.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 21, 'equipment_5', 'Nothing. Nothing at all.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 22, 'equipment_6', 'I know I didn''t steal it. That''s about it.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 23, 'equipment_7', 'For all we know, maybe YOU stole it.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 24, 'equipment_8', 'Stop asking pointless questions.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 25, 'equipment_9', 'Why are you harassing me? Go find the person that actually stole the stuff!'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 26, 'equipment_10', 'Geez, you''re as bad as that bounty hunter. I don''t know anything, alright?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 27, 'equipment_11', 'Nothing. Can I go now?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 28, 'bye_0', 'Good-bye.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 29, 'bye_1', '''Bye.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 30, 'bye_2', 'Get lost.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 31, 'bye_3', 'Whatever.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 32, 'bye_4', 'Go on, get out of here, twerp.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 33, 'bye_5', 'Stop wasting my time.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 34, 'bye_6', 'Am I free to go?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 35, 'bye_7', 'Go tell that bounty hunter that I''m not the one she''s looking for, eh?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 36, 'bye_8', 'So long.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 37, 'bye_9', 'Remember, I didn''t do it.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 38, 'bye_10', 'So, you believe me, right?'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 39, 'bye_11', 'Fine.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 40, 'others_0_0', 'I don''t really know what I can tell you, other than this piece of advice.  I know the smugglers in this town fairly well.  Two of them always lie.  You can only trust the other three.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 41, 'others_0_1', 'There''s really not much that I can tell you. I know most of these smugglers pretty well though. Two of them are compulsive liars. The others are pretty trusworthy.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 42, 'others_0_2', 'Yea, I know most of these rogues pretty well. Three of them are pretty honest. The other two are down right dirty liars, I wouldn''t trust a word they say.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 43, 'others_1_0', 'Neither %TO nor I have anything to do with this, leave us alone.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 44, 'others_1_1', 'I''m innocent I tell you, and so is %TO. Now leave us be.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 45, 'others_1_2', 'Both %TO and I have nothing to do with all this. That''s all I can say.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 46, 'others_2_0', 'I know for a fact that the bounty hunter is looking for %TT or %TO.  They are both considered scum, even among smugglers.  I wouldn''t be surprised if one of them stooped to petty thievery.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 47, 'others_2_1', 'I''m almost positive that either %TT or %TO is the culprit. I''ve heard of them getting caught up in situtations like this before.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 48, 'others_2_2', 'I''ll tell you what. I''ve been around and I hear things. And I''m sure it''s either %TT or %TO that the bounty hunter is looking for.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 49, 'others_3_0', 'Don''t trust %TT and %TO, both of them are lying.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 50, 'others_3_1', 'I overheard %TT and %TO talking earlier. They are both liars, don''t trust either of them.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 51, 'others_3_2', 'I know that %TT and %TO are both liars. Don''t listen to a word they say.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 52, 'others_4_0', '%TT isn''t telling the truth; either %TO or %TU is lying, the other is not.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 53, 'others_4_1', 'I know for a fact that %TT is a liar. And I know that either %TO or %TU is lying, but the other isn''t.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 54, 'others_4_2', 'Both %TO and %TU are kind of shady, but only one is a liar, the other isn''t. And we all know that %TT is definately a liar.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 55, 'others_5_0', 'Whatever %TO said is a lie.  I''ve been cheated by that that poor excuse for a smuggler enough times to know.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 56, 'others_5_1', 'That %TO is a filthy liar. Everyone here knows it.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 57, 'others_5_2', 'Everything that %TO says is a dirty lie. You can''t believe a word that comes out of his mouth.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 58, 'rank', 'a smuggler captain'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 59, 'sui_prompt', 'Choose the smuggler that you believe stole the equipment:'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 60, 'sui_title', 'Bounty Hunter'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 61, 'sui_btn_ok', 'Point Him Out'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 62, 'sui_btn_cancel', 'Nevermind'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 63, 'bh_win', 'You''re right, that does make sense. Thanks for your help, I''ll take care of it from here.'),
('string/en/quest/hero_of_tatooine/intellect_liar.stf', 64, 'bh_lose', 'No, no. That can''t be right, it doesn''t make sense at all. I guess I''ll just have to figure it out myself.'),
('string/en/quest/hero_of_tatooine/rancher.stf', 1, 'you_okay', 'The authorities are here. Are you okay?'),
('string/en/quest/hero_of_tatooine/rancher.stf', 2, 'glad_here', 'Yes, I am. I''m so glad you''re here!'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 1, 'failed', 'Quest Failed: The pirates have escaped! To restart, seek out the pirate leader in the wilderness of Tatooine.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 2, 'success', 'Quest completed: Mark of Honor received!'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 3, 'restart', 'Restarting Quest: The seven minute time limit has been reached. The quest has been restarted for other players to enjoy.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 4, 'enter', 'You enter what seems to be a rancher''s house. It appears to be sensibly decorated and pleasant and the aroma of freshly baked goods greets you. In the distance, you can hear faint, but frantic, murmuring. You should investigate.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 5, 'reset', 'Resetting Quest: Check objvars on your character to garauntee correct testing. Additionally, be sure to review documentation on the Hero of Tatooine quest. '),
('string/en/quest/hero_of_tatooine/system_messages.stf', 6, 'search', 'Search'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 7, 'already_search', 'You already searched the lair and doubt you could find anything else worth of interest.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 8, 'inventory', 'Your inventory is full and can''t carry anymore items.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 9, 'receive', 'You pick through the twigs and dirt and find an abandoned skull.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 10, 'altruism_already_open', 'Someone else is already inspecting that area.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 11, 'altruism_explosion_damage', 'You have taken some damage from your proximity to the explosion.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 12, 'altruism_explosive_removed', 'You have removed the explosives from the rock crevice and turned off the timer.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 13, 'altruism_explosive_set', 'You have placed the explosives into the rock crevice and set the timer to TEN SECONDS.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 14, 'altruism_got_object', 'You found a pack of timed explosives! The crate has fallen apart due to years of deterioration.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 15, 'altruism_inventory_full', 'You found something in the crate, but your inventory is full. Make some room and search again.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 16, 'altruism_no_reason', 'You can''t think of a good reason to put this item there.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 17, 'altruism_not_wise_examine', 'It would probably not be wise to inspect that area now.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 18, 'altruism_npc_farewell', 'Thank you so much for helping us. We''ll go straight home from here, I promise!'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 19, 'altruism_null_object', 'You found something in the crate, but couldn''t get it for some reason. You might want to try again.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 20, 'altruism_quest_fail', 'MISSION FAILED: You were not successful in rescuing the farmer''s wife and daughter.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 21, 'altruism_quest_success', 'MISSION SUCCESS: You have rescued the farmer''s wife and daughter!'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 22, 'menu_search', 'Search'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 23, 'courage_notice_object', 'As the creature falls, you notice an object glittering on it''s corpse.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 24, 'courage_already_have_mark', 'You already have the Mark of Courage.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 25, 'menu_restore', 'Restore Life'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 26, 'restore_msg', 'Your Mark of the Hero has restored some life to you...'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 27, 'restore_not_yet', 'You cannot use this special ability for %TO'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 28, 'restore_not_equipped', 'You must be wearing the ring to use that special ability.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 29, 'restore_not_dead', 'That special ability will have no effect while you are alive.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 30, 'restore', 'Restore Life'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 31, 'altruism_inv_full', 'You did not receive the Mark of Altruism item because your inventory is full. Seek out the Hermit to acquire that which you are owed.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 32, 'intellect_inv_full', 'You did not receive the Mark of Intellect item because your inventory is full. Seek out the Hermit to acquire that which you are owed.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 33, 'honor_inv_full', 'You did not receive the Mark of Honor item because your inventory is full. Seek out the Hermit to acquire that which you are owed.'),
('string/en/quest/hero_of_tatooine/system_messages.stf', 34, 'hero_inv_full', 'You did not receive the Mark of the Hero item because your inventory is full. Speak to the Hermit again to acquire that which you are owed.'),
('string/en/quest/lifeday/lifeday.stf', 1, 'waypoint_name', 'Life Day Celebration'),
('string/en/quest/lifeday/lifeday.stf', 2, 'waypoint_updated', 'A waypoint to a planet holding a Life Day celebration was added to your datapad.'),
('string/en/quest/lifeday/lifeday.stf', 3, 'full_inv', 'Your inventory is full. Please make some room and speak to the NPC again to receive your gift.'),
('string/en/quest/pirates.stf', 1, 'ruin_life', 'I''ll be back! And I''ll ruin your life!'),
('string/en/quest/pirates.stf', 2, 'dont_hurt_us', 'Wait! Don''t hurt us! We give up!'),
('string/en/quest/quests.stf', 1, 'task_complete', 'You have completed your task!'),
('string/en/quest/quests.stf', 2, 'quest_journal_updated', 'Your quest journal has been updated.'),
('string/en/quest/quests.stf', 3, 'task_failure', 'You have failed your task.'),
('string/en/quest/quests.stf', 4, 'kill_credit', 'You gain credit for the quest %TO. Total left: %DI'),
('string/en/quest/quest_journal/fs_craft4.stf', 12, 'quest01_n', 'Find a Gadget Specialist'),
('string/en/quest/quest_journal/fs_craft4.stf', 13, 'quest02_n', 'Complete the Tracking Device Kit'),
('string/en/quest/quest_journal/fs_craft4.stf', 14, 'quest03_n', 'Obtain the Rights to an Abandoned Satellite'),
('string/en/quest/quest_journal/fs_craft4.stf', 15, 'quest04_n', 'Find the Fallen Satellite and Retrieve the Computer Core'),
('string/en/quest/quest_journal/fs_craft4.stf', 16, 'quest05_n', 'Reconfigure the Computer Core''s Interface'),
('string/en/quest/quest_journal/fs_craft4.stf', 17, 'quest06_n', 'Bring the New Core to Aurilia''s Chief Engineer'),
('string/en/quest/quest_journal/fs_craft4.stf', 18, 'quest07_n', 'Make Space for Your Reward'),
('string/en/quest/quest_journal/fs_craft4.stf', 19, 'quest01_d', 'Go to Keren on Naboo, Coronet on Corellia, or Mos Entha on Tatooine and speak to a gadget specialist to seek help finding a replacement computer core for the village of Aurilia on Dathomir. The Aurilia chief engineer can provide you with a waypoint to one of these locations if you wish. Simply speak with him.'),
('string/en/quest/quest_journal/fs_craft4.stf', 20, 'quest02_d', 'Complete the satellite tracking device kit. Doing so will provide you with the means to find a downed satellite from which you could find a replcement computer core.'),
('string/en/quest/quest_journal/fs_craft4.stf', 21, 'quest03_d', 'Go to any starport ticket droid and request their assistance to obtain the rights to an abandoned satellite. Doing so will provide you with tracking data for your satellite tracking device and will allow you to locate the fallen satellite.'),
('string/en/quest/quest_journal/fs_craft4.stf', 22, 'quest04_d', 'Use your tracking device to locate the fallen satellite. Once found, retrieve the computer core so that it may be used as a replacement in the village of Aurilia on Dathomir.'),
('string/en/quest/quest_journal/fs_craft4.stf', 23, 'quest05_d', 'Modify the replacement computer core''s interface so that it will be configured to be used with the computers of Aurilia. Do so by choosing the menu options under "Reconfigure Interface" from the computer core''s radial menu.\n\nYou will need to rewire the replacement computer core to match that of the village computers. There are four indicators on the core that will be lit when it has been properly configured.\n\nTo reconfigure the core, you will need to connect four wires in the proper order to contacts on the core. There are red wires, yellow wires, and blue wires.  Each color set of of wires connects to a different power source, and any combination of the wires may be used to reconfigure the computer core. \n\nWhen you have the wires configured the way you desire, you may test the configuration to see if it is correct. For each wire that is connected to the correct contact, one of the four indicators will be lit. If the correct type of wire is used but is connected to the wrong contact, then one of the indicators will flicker. You can use this feedback to determine the final configuration of the interface for the new computer core.\n\nBe careful though... each time you test your configuration, power is sent through the core.  An incomplete configuration can damage the core. This is reported as ''Circuit Integrity'' which gives the percentage chance that the core is still viable. Be sure to keep an eye on this value. On average, a core can survive 6 - 7 attempts without sigificant damage, but beyond that you risk frying the computer core''s circuits and rendering it useless.'),
('string/en/quest/quest_journal/fs_craft4.stf', 24, 'quest06_d', 'Bring the newly configured computer core to Aurilia''s chief engineer so that he may use it to stabilize the village''s primary computers.'),
('string/en/quest/quest_journal/fs_craft4.stf', 25, 'quest07_d', 'The people of the village wish to reward you for your aid to them, but you must have room in your inventory for it. Make some room and then speak again to the chief engineer.'),
('string/en/quest/quest_journal/fs_craft4.stf', 26, 'main_n', 'Find a replacement computer core for the village of Aurilia computers.'),
('string/en/quest/quest_journal/fs_craft4.stf', 27, 'main_d', 'During the large-scale attacks that have recently plagued the village of Aurillia, the village''s primary computer system and its computer core were badly damaged. The computer is currently running on its reserve core but won''t last much longer, and therefore a new core must be acquired as soon as possible. \n\nThanks to the current ongoing attacks, the newly appointed chief engineer is unable to attend to the damaged computer core by finding a replacement. He has asked you to do so for him.'),
('string/en/quest/quest_journal/fs_craft4.stf', 28, 'quest_finished_n', 'Quest Complete and Skill Branch Unlocked: Crafting Mastery: Repair'),
('string/en/quest/quest_journal/fs_craft4.stf', 29, 'quest_finished_d', 'You have helped the Aurilia chief engineer replace the damaged computer core and in doing so have unlocked the ability to use the crafting mastery repair skills.'),
('string/en/quest/quest_journal/fs_defend.stf', 1, 'summary_01', 'Defend the village against Mellichae''s Shadow Sith Outlaws!'),
('string/en/quest/quest_journal/fs_defend.stf', 3, 'detail_01', 'An overwhelming force of mercenaries and criminals are assaulting the village of Aurilia. The villagers are grossly outnumbered. You are tasked with defeating at least fifty of the Sith Shadow outlaws hired by Mellichae.'),
('string/en/quest/quest_journal/fs_defend.stf', 4, 'detail_02', 'An overwhelming force of mercenaries and criminals are assaulting the village of Aurilia. The villagers are grossly outnumbered. You are tasked with defeating at least twenty-five of the lieutenants leading Mellichae''s hired thugs. The outlaws are led by Sith Shadow pirates.'),
('string/en/quest/quest_journal/fs_defend.stf', 5, 'defend_the_village_summary', 'Village Assault! (Unlock Combat Prowess: Ranged Weapon Speed)'),
('string/en/quest/quest_journal/fs_defend.stf', 6, 'defend_the_village_detail', 'An overwhelming force of mercenaries and criminals are assaulting the village of Aurilia. The villagers are grossly outnumbered. '),
('string/en/quest/quest_journal/fs_defend.stf', 7, 'reward_summary_01', 'Unlocked Combat Prowess: Ranged Weapon Speed'),
('string/en/quest/quest_journal/fs_defend.stf', 8, 'reward_detail_01', 'You are now eligible to learn Combat Prowess: Ranged Weapon Speed. You will first need to earn enough experience to learn skills in this branch. See Paemos in the village of Aurilia on Dathomir for more information.'),
('string/en/quest/quest_journal/fs_defend.stf', 9, 'reward_summary_02', 'Unlocked branch Enhanced Reflexes: Melee Defenses'),
('string/en/quest/quest_journal/fs_defend.stf', 10, 'reward_detail_02', 'You are now eligible to learn Enhanced Reflexes: Melee Defenses. You will first need to earn enough experience to learn skills in this branch. See Paemos in the village of Aurilia on Dathomir for more information.'),
('string/en/quest/quest_journal/fs_defend.stf', 11, 'defend_the_village_summary_02', 'Village Assault! (Unlock Enhanced Reflexes: Melee Defenses)'),
('string/en/quest/quest_journal/fs_defend.stf', 12, 'summary_02', 'Defend the village against Mellichae''s Shadow Sith Pirates!'),
('string/en/quest/quest_journal/fs_medic.stf', 1, 'combat_healing_n_1', 'Healing Support'),
('string/en/quest/quest_journal/fs_medic.stf', 2, 'combat_healing_n_2', 'Healing Support (extended)'),
('string/en/quest/quest_journal/fs_medic.stf', 3, 'combat_healing_d_1', 'Your help is needed to support the defense of the village. Find any group of defenders and join them, be sure to support them during battle. Complete at least 50 encounters.'),
('string/en/quest/quest_journal/fs_medic.stf', 4, 'combat_healing_d_2', 'Your help is still needed to support the defense of the village. Find any group of defenders and join them, be sure to support them during battle. Complete a total of at least 100 encounters.'),
('string/en/quest/quest_journal/fs_medic.stf', 5, 'healing_puzzle_n_1', 'Cure the sick'),
('string/en/quest/quest_journal/fs_medic.stf', 6, 'healing_puzzle_d', 'You are needed to help cure the sick villagers. Control the medicine through experimentation and use of various qualities of resources. Through multiple applications of the medications, you should be able to cure the symptoms of the sick. The medical droids will help you administer the cures to the patients.'),
('string/en/quest/quest_journal/fs_medic.stf', 7, 'healing_puzzle_n_2', 'Cure the sick (extended)'),
('string/en/quest/quest_journal/fs_medic.stf', 8, 'healing_puzzle_n_3', 'Cure the sick (Extra Cures)'),
('string/en/quest/quest_journal/fs_medic.stf', 9, 'healing_puzzle_n_finish', 'Quest Complete'),
('string/en/quest/quest_journal/fs_medic.stf', 10, 'combat_healing_n_finish', 'Quest Complete'),
('string/en/quest/quest_journal/fs_medic.stf', 11, 'healing_puzzle_d_finish', 'You have completed the quest to aid the sick and wounded villagers. You may now talk to Noldan about training in the persuasion Force sensitive skills.'),
('string/en/quest/quest_journal/fs_medic.stf', 12, 'combat_healing_d_finish', 'You have completed the quest to aid the troops during the defense of the village. You may now talk to Noldan about training in the healing Force sensitive skills.'),
('string/en/quest/quest_journal/fs_patrol.stf', 1, 'patrol_journal_1_n', 'Patrol ( 1 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 2, 'patrol_journal_d', 'Patrol all eight points.  Standing orders are to subdue any hostiles you come across, unless the hostiles are part of a raid force. Any groups larger than three should be avoided so intelligence can be gathered. We cannot gather information if they are dead. Report back after all points are complete.'),
('string/en/quest/quest_journal/fs_patrol.stf', 3, 'patrol_journal_2_n', 'Patrol ( 2 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 4, 'patrol_journal_3_n', 'Patrol ( 3 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 5, 'patrol_journal_4_n', 'Patrol ( 4 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 6, 'patrol_journal_5_n', 'Patrol ( 5 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 7, 'patrol_journal_6_n', 'Patrol ( 6 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 8, 'patrol_journal_7_n', 'Patrol ( 7 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 9, 'patrol_journal_8_n', 'Patrol ( 8 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 10, 'patrol_journal_9_n', 'Patrol ( 9 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 11, 'patrol_journal_10_n', 'Patrol ( 10 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 12, 'patrol_journal_11_n', 'Extra Patrols ( 1 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 13, 'patrol_journal_12_n', 'Extra Patrols ( 2 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 14, 'patrol_journal_13_n', 'Extra Patrols ( 3 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 15, 'patrol_journal_14_n', 'Extra Patrols ( 4 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 16, 'patrol_journal_15_n', 'Extra Patrols ( 5 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 17, 'patrol_journal_16_n', 'Extra Patrols ( 6 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 18, 'patrol_journal_17_n', 'Extra Patrols ( 7 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 19, 'patrol_journal_18_n', 'Extra Patrols ( 8 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 20, 'patrol_journal_19_n', 'Extra Patrols ( 9 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 21, 'patrol_journal_20_n', 'Extra Patrols ( 10 / 10 )'),
('string/en/quest/quest_journal/fs_patrol.stf', 22, 'patrol_journal_start', 'Village Patrols'),
('string/en/quest/quest_journal/fs_patrol.stf', 23, 'patrol_journal_finish', 'Quest Complete'),
('string/en/quest/quest_journal/fs_patrol.stf', 25, 'patrol_journal_d_finish', 'You have completed the quest to patrol for enemy forces. You may now talk to Noldan about training in ranged accuracy Force sensitive skills.'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 1, 'defenses_main', 'Help Build Village Defenses'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 2, 'shields_main', 'Help Build Village Shields'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 3, 'defenses_detail', 'Contribute 10 or more resources or components to the village defenses crafting project. The "Village Defenses" schematic has the details of what items are needed.'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 4, 'shields_detail', 'Contribute 20 or more resources or components to the village shields crafting project.'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 5, 'get_defense_schematics', 'Get The Schematics'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 6, 'get_shield_schematics', 'Get The Schematics'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 7, 'get_defense_schematics_detail', 'Talk to the droid QT-QC and get the schematics needed for the village defenses.'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 8, 'get_shield_schematics_detail', 'Talk to the droid QT-QC and get the schematics needed for the village shields.'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 9, 'defenses', 'Craft The Ingredients'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 10, 'shields', 'Craft The Ingredients'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 11, 'defenses_main_detail', 'Contribute crafted items to help build the village defenses.'),
('string/en/quest/quest_journal/fs_quests_community_crafting.stf', 12, 'shields_main_detail', 'Contribute crafted items to help build the village shields.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 1, 's_01', 'Find and examine the sensor array.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 2, 'd_01', 'You must find the village sensor array and determine the extent of the damage. If there are any non-functional components, you should remove them so new ones can be replaced.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 3, 's_02', 'Find the chief engineer''s workstation.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 4, 'd_02', 'Remove any damaged components from the sensor array.\n\nYou must find the chief engineer''s tools and use them to craft and calibrate new components. Remember that new components must be calibrated correctly before they can be installed into the sensor array.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 5, 's_03', 'Calibrate and replace components.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 6, 'd_03', 'Use the Recursive Analyzer to deconstruct damaged components into a draft schematic, and craft new components. Those draft schematics are limited use, but if you need another after you use one, you can load it from the Analyzer memory.\n\nOnce you have a new component, you will need to calibrate it using the Multi-phase calibrator. Be careful though, the calibration process has a detrimental effect on component integrity. \n\nOnce you have correctly calibrated all of the new components, you must replace them into the sensor array to bring it back online.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 7, 's_00', 'Repair the sensor array.'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 8, 'd_00', 'The sensor array in the village of Aurilia has been damaged. It must be repaired!'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 9, 's_04', 'QUEST COMPLETE'),
('string/en/quest/quest_journal/fs_quests_craft1.stf', 10, 'd_04', 'QUEST COMPLETE: You have successfully brought the village sensor array back online. As agreed, Quharek has opened your mind to the possibility of using the Force to enhance your assembly skills.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 1, 's_01', 'Find a Sith Shadows encampment.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 2, 'd_01', 'Citizens of the village of Aurilia are feared to have been captured by the Sith Shadows. Village trackers have found a trail that should probably lead to the vicinity of a Shadows encampment. Find the encampment and any imprisoned villagers.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 3, 's_02', 'Speak with the imprisoned villager.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 4, 'd_02', 'A villager has been captured by the Sith Shadows! Speak with the prisoner and he or she will likely follow you back to the village. Be careful, if the enemy spots you, they will likely attack.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 5, 's_03', 'Keep the villager alive.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 6, 'd_03', 'The rescued villager must make it back to the village alive.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 7, 's_04', 'Return to the village of Aurilia.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 8, 'd_04', 'Both you and the rescued villager must return to the village of Aurilia safely.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 9, 's_00', 'Rescue missing villagers.'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 10, 'd_00', 'Several villagers are missing from Aurilia. They must be found!'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 11, 's_05', 'QUEST COMPLETE'),
('string/en/quest/quest_journal/fs_quests_reflex1.stf', 12, 'd_05', 'QUEST COMPLETE: You have successfully rescued the villagers that were taken prisoner from the village of Aurilia. As agreed, Whip has opened your mind to the possibilities of using the Force to enhance your survival skills.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 1, 's_01', 'Find the transport crash site.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 2, 'd_01', 'The emergency beacon indicates the area where the transport was attacked. Find that location and the transport should be nearby.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 3, 's_02', 'Pick up the box of supplies.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 4, 'd_02', 'It looks like there is a crate of supplies that has not yet been stolen, and can still be salvaged from the wreckage. You must get that crate! Be careful though, if the enemy spots you, they will likely attack.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 5, 's_03', 'Take the supplies back to the village.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 6, 'd_03', 'The crate of supplies must be returned safely to the village of Aurilia. You must return the crate before it is stolen or damaged.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 7, 's_00', 'Retrieve supply crates.'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 8, 'd_00', 'Supply transports have been attacked. The supplies must be brought to the village of Aurilia!'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 9, 's_04', 'QUEST COMPLETE'),
('string/en/quest/quest_journal/fs_quests_reflex2.stf', 10, 'd_04', 'QUEST COMPLETE: You have successfully retrieved the much needed supplies for the village of Aurilia. As agreed, Whip has opened your mind to the possibilities of using the Force to enhance your vehicle control skills.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 1, 'main', 'Search And Destroy'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 2, 'task1', 'Search And Destroy 1/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 3, 'task2', 'Search And Destroy 2/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 4, 'task3', 'Search And Destroy 3/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 5, 'task4', 'Search And Destroy 4/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 6, 'task5', 'Search And Destroy 5/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 7, 'task6', 'Search And Destroy 6/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 8, 'task7', 'Search And Destroy 7/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 9, 'task8', 'Search And Destroy 8/8'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 10, 'task1_detail', 'We''ve spotted a number of enemy patrols in the area and could use your help.  \n\nWe know they''re building their strength for a coming attack, and we''d like to strike while the iron is hot, so to speak.  Can you help us?\n\nNote: Dageerin said to use the rradiation sensor, found in your datapad, to track the tracking device planted on them.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 11, 'task2_detail', 'You did us a great service with your last raid on the enemy, but there are more out there.  \n\nCan you help us again?'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 12, 'task3_detail', 'I think your attacks are beginning to get their attention.  I''d watch your back.  \n\nHere''s your next target, if you''re up for it...'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 13, 'task4_detail', 'They''ve started moving their bases around in response to our attacks.  We''ve tracked them into a new area that we''d like to investigate.\n\nNote: Dageerin said to use the radiation sensor, found in your datapad, to track the tracking device planted on them.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 14, 'task5_detail', 'Unfortunately, one of our field soldiers was caught and killed.  But he managed to get us a message with the coordinates of an enemy base.  Can you avenge him for us?\n\nNote: Dageerin said to use the radiation sensor, found in your datapad, to track the tracking device planted on them.\n'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 15, 'task6_detail', 'We may have turned the corner on this thing.  It feels great to finally take the battle to our enemy instead of waiting for them to attack.  \n\nReady for another one?'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 16, 'task7_detail', 'All of the reports coming in are promising - we definitely have them on the run now. \n\n I think we''re getting to their more elite troops - please be careful.\n\nNote: Dageerin said to use the radiation sensor, found in your datapad, to track the tracking device planted on them.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 17, 'task8_detail', 'Exciting news!  We''ve finally tracked down one of their high-ranking officers.  Our efforts have flushed her out, and our agent caught a glimpse of her just a while back.  I think...well, better not say anything.  Be careful - a cornered rat fights hard.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 18, 'return1', 'Search And Destroy 1/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 19, 'return2', 'Search And Destroy 2/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 20, 'return3', 'Search And Destroy 3/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 21, 'return4', 'Search And Destroy 4/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 22, 'return5', 'Search And Destroy 5/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 23, 'return6', 'Search And Destroy 6/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 24, 'return7', 'Search And Destroy 7/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 25, 'return8', 'Search And Destroy 8/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 26, 'return1_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 27, 'return2_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 28, 'return3_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 29, 'return4_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 30, 'return5_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 31, 'return6_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 32, 'return7_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 33, 'return8_detail', 'Return to the NPC.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 34, 'wrong_phase', 'You did not complete your existing quest (Search and Destroy) in time.  You must restart that quest.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/quest/quest_journal/fs_quests_sad.stf', 35, 'main_detail', 'A variety of Shadow bases have been spotted in the surrounding countryside.  We suspect they are marshalling their forces for some sort of large-scale raid unlike anything we''ve seen.  If they were to strike now, we would be horribly unprepared.  We must convince them that we are much stronger than we, in fact, are.  Village agents are scouring the countryside as we speak looking for likely targets for dynamic raids.  We can use your help.'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 36, 'instructions_title', 'Instructions'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 37, 'instructions_text', 'Hit "Use" to display a window showing the threat level of the enemies.  As you get closer to the tracking device (and thus the enemy), the radiation counter will go up.  If you move away, it goes down. \n\nThe device will let you know if you''re getting closer to the enemy or moving away from it.  The display will also indicate when you are within 64 meters of your target.\n\nKeep the window up as you move, but look out for the enemy!'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 38, 'finish_summary', 'Completed Quest - Unlocked Skill Combat Prowess: Melee Speed'),
('string/en/quest/quest_journal/fs_quests_sad.stf', 39, 'finish_detail', 'You have completed your work for Dageerin and unlocked the ability to use the melee speed skill.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 1, 'main', 'Search And Destroy II'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 2, 'task1', 'Search And Destroy II 1/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 3, 'task2', 'Search And Destroy II 2/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 4, 'task3', 'Search And Destroy II 3/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 5, 'task4', 'Search And Destroy II 4/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 6, 'task5', 'Search And Destroy II 5/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 7, 'task6', 'Search And Destroy II 6/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 8, 'task7', 'Search And Destroy II 7/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 9, 'task8', 'Search And Destroy II 8/8'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 10, 'task1_detail', 'Our militia uses a small tracking device called a radiation sensor to track the enemy out in the field. I''m going to give you a control device that can sit in your datapad.  Activate it to get a reading.  As the reading goes up, you''re getting close to the target.  Based on the strength of the readings, I think the nearest Shadow base is about 1000 meters from here.  Good luck, soldier.\n\n'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 11, 'task2_detail', 'Someone is feeding them troops and materiel, but we don''t know who.  We''ve located a base that''s supplying a large area outside the village.  Can you track it down and destroy it for us?'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 12, 'task3_detail', 'We''ll bring this Shadow out into the open if it''s the last thing we do.  I''m redoubling our patrols, which places great strain on the auxiliares.  Think you can handle it?\n\nNote: Dageerin said to use the radiation sensor, found in your datapad, to track the tracking device planted on them.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 13, 'task4_detail', 'They''ve started moving their bases around in response to our attacks.  With the help of the Force, I hope we can find their new camps quickly.  Can you help?\n\nNote: Dageerin said to use the radiation sensor, found in your datapad, to track the tracking device planted on them.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 14, 'task5_detail', 'We may have turned the corner on this thing.  It feel great to finally take the battle to our enemy instead of waiting for them to attack.  \n\nReady for another one?\n\nNote: Dageerin said to use the radiation sensor, found in your datapad, to track the tracking device planted on them.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 15, 'task6_detail', 'Our spies have netted us another camp.  But you''ll have to act quickly.  They look like they''re ready to move.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 16, 'task7_detail', 'All of the reports coming in are promising - we definitely have them on the run now. \n\nI think we''re getting to their more elite troops - please be careful.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 17, 'task8_detail', 'All right, we''re getting somewhere, finally.  Reports are coming in that a high-ranking officer of the Shadow is holed up nearby.  Take him out, now.\n\nNote: Dageerin said to use the radiation sensor, found in your datapad, to track the tracking device planted on them.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 18, 'return1', 'Search And Destroy II 1/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 19, 'return2', 'Search And Destroy II 2/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 20, 'return3', 'Search And Destroy II 3/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 21, 'return4', 'Search And Destroy II 4/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 22, 'return5', 'Search And Destroy II 5/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 23, 'return6', 'Search And Destroy II 6/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 24, 'return7', 'Search And Destroy II 7/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 25, 'return8', 'Search And Destroy II 8/8 - Return to village'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 26, 'return1_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 27, 'return2_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 28, 'return3_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 29, 'return4_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 30, 'return5_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 31, 'return6_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 32, 'return7_detail', 'Return to Dageerin, in the village.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 33, 'return8_detail', 'Return to the NPC.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 34, 'wrong_phase', 'You did not complete your existing quest (Search and Destroy) in time.  You must restart that quest.'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 35, 'main_detail', 'We''re taking the fight to the enemy while we prepare our invincible shield defense.  Because of the preparations, and the scale of the conflict, our normal militia is overworked.  We''re recruiting auxiliaries to be frontline combat troops.  We know the location of a number of Shadow bases that we want taken out to keep them on the run.  '),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 36, 'finish_summary', 'Completed Quest - Unlocked Skill Enhanced Reflexes: Ranged Defense'),
('string/en/quest/quest_journal/fs_quests_sad2.stf', 37, 'finish_detail', 'You have completed your work for Dageerin and unlocked the ability to use the ranged defense skill.'),
