('string/en/relic_dealer.stf', 1, 'prose_sold_junk', 'You sell %TT for %DI credits.'),
('string/en/relic_dealer.stf', 2, 'prose_no_sale', '%TU cannot buy %TT from you at this time.'),
('string/en/relic_dealer.stf', 3, 'prose_no_buy', '%TU shows no interest in purchasing %TT.'),
('string/en/relic_dealer.stf', 7, 'sell_title', 'Relic Dealer'),
('string/en/relic_dealer.stf', 8, 'sell_prompt', 'Select an item and press the ''Sell'' button to sell the relic to the dealer.\n\nPress the ''Sell All'' button to sell all available relics to the dealer.'),
('string/en/relic_dealer.stf', 9, 'prose_sold_all_junk', 'You sell all of your relics to %TT for %DI credits.'),
('string/en/relic_dealer.stf', 10, 'prose_no_all_sale', '%TT is unable to purchase all of your relics and declines the transaction.'),
('string/en/relic_dealer.stf', 11, 'prose_no_buy_all', '%TT does not seem interested in buying any of your relics.'),
('string/en/relic_dealer.stf', 12, 'prose_junk_sold', '%TT is already in the process of being sold...'),
