('string/en/resource_container_d.stf', 6, 'energy_radioactive_large', 'This container holds large amounts of radioactive ore.'),
('string/en/resource_container_d.stf', 7, 'energy_solid_small', 'This container holds small amounts of energetic ore.'),
('string/en/resource_container_d.stf', 8, 'energy_solid_large', 'This container holds large amounts of energetic ore.'),
