('string/en/skl_d.stf', 344, 'crafting_industrialist', 'The Industrialist learns how to manufacture and sell goods through merchants.  Industrialists buy manufacturing schematics, build factories, make goods, and sell them through their vendors in shops that they have set up.'),
('string/en/skl_d.stf', 345, 'crafting_industrialist_efficiency_01', 'Intermediate Factory Efficiency increases a factory''s efficiency at making an item, reducing repair costs.'),
('string/en/skl_d.stf', 346, 'crafting_industrialist_efficiency_02', 'Advanced Factory Efficiency increases a factory''s efficiency at making an item, reducing repair costs.'),
('string/en/skl_d.stf', 347, 'crafting_industrialist_efficiency_03', 'Expert Factory Efficiency increases a factory''s efficiency at making an item, reducing repair costs.'),
('string/en/skl_d.stf', 348, 'crafting_industrialist_efficiency_04', 'Master Factory Efficiency increases a factory''s efficiency at making an item, reducing repair costs.'),
('string/en/skl_d.stf', 349, 'crafting_industrialist_maintenance_01', 'Intermediate Factory Maintenance reduces the maintenance costs and improves the overall condition of an Industrialist''s factories.'),
('string/en/skl_d.stf', 350, 'crafting_industrialist_maintenance_02', 'Advanced Factory Maintenance reduces the maintenance costs and improves the overall condition of an Industrialist''s factories.'),
('string/en/skl_d.stf', 351, 'crafting_industrialist_maintenance_03', 'Expert Factory Maintenance reduces the maintenance costs and improves the overall condition of an Industrialist''s factories.'),
('string/en/skl_d.stf', 352, 'crafting_industrialist_maintenance_04', 'Master Factory Maintenance reduces the maintenance costs and improves the overall condition of an Industrialist''s factories.'),
('string/en/skl_d.stf', 353, 'crafting_industrialist_management_01', 'Intermediate Factory Management increases the industrialist''s number of vendors and the size of the vendor''s stock.'),
('string/en/skl_d.stf', 354, 'crafting_industrialist_management_02', 'Advanced Factory Management increases the industrialist''s number of vendors and the size of the vendor''s stock.'),
('string/en/skl_d.stf', 355, 'crafting_industrialist_management_03', 'Expert Factory Management increases the industrialist''s number of vendors and the size of the vendor''s stock.'),
('string/en/skl_d.stf', 356, 'crafting_industrialist_management_04', 'Master Factory Management increases the industrialist''s number of vendors and the size of the vendor''s stock.'),
('string/en/skl_d.stf', 357, 'crafting_industrialist_master', 'The Master Industrialist knows efficient and effective factories, as well has how to have a full suite of vendors with large inventories.'),
('string/en/skl_d.stf', 358, 'crafting_industrialist_novice', 'The novice industrialist learns the basics of using factories and setting up vendors to sell items.'),
('string/en/skl_d.stf', 359, 'crafting_industrialist_speed_01', 'Intermediate Factory Speed improves the rate at which factory can turn out items created from a manufacturing schematic.'),
