('string/en/space/destroy_duty/corellia_privateer_11.stf', 4, 'boss_title_1', 'Ponias MorningGlory (Nym''s Dark Enforcer)'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 5, 'boss_title_2', 'Geian Bladewrite (Nym''s Dark Enforcer)'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 6, 'boss_title_3', 'Morar Deathslayer (Nym''s Dark Enforcer)'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 7, 'boss_title_4', 'Atias Burninglight (Nym''s Dark Enforcer)'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 8, 'boss_title_5', 'Kyax UnNamed (Nym''s Dark Enforcer)'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 9, 'complete', 'Fantastic job pilot, we struck a huge blow to Nym today. Return to base for a well earned rest.'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 10, 'dd_boss_taunt_1', 'Muahahaha!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 11, 'dd_boss_taunt_2', 'Your just another kill mark on my ship, fool!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 12, 'dd_boss_taunt_3', 'The cat becomes the mouse. The tables are turned, scum!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 13, 'dd_boss_taunt_4', 'Your flying skills remind me of a one winged Mynock!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 14, 'dd_boss_taunt_5', 'I''ve never seen those moves from a  petty pilot before. No matter, prepare to die!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 15, 'found_loc', 'New coordinates of pirate activity has been uploaded to your nav computer. Go get them!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 16, 'level_boss', 'Superior Command: < The Hidden Daggers has sent %TO to bring you down, proceed with caution. >'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 17, 'level_boss_dead', 'Amazing! Nym will not forget this day. Stand by for further orders.'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 18, 'level_increase', 'Nym''s men are sending more reinforcements in responce to our attacks.'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 19, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 20, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 21, 'taunt_1', 'You think you can match the skill of Nym''s pirates? I think not!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 22, 'taunt_2', 'I will shred your ship, fool!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 23, 'taunt_3', 'You always have to interfere, well this time you stuck your nose too deep!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 24, 'taunt_4', 'You''re fighting a uphill battle , and the hill just got steeper!'),
('string/en/space/destroy_duty/corellia_privateer_11.stf', 25, 'taunt_5', 'I have crushed greater things than you! In fact, I shot a Womprat back on Tatooine last week!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 1, 'title', 'Attack on the Pirates in Dantooine Sector'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 2, 'duty_update', 'Superior Command: < %TO >'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 3, 'boss_detected', 'Tactical Computer: < Vessel with veteran insignias on attack vector, weapon systems armed. >'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 4, 'boss_title_1', 'Experienced Pirate Pilot'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 5, 'boss_title_2', 'Veteran Pirate Pilot'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 6, 'boss_title_3', 'Grim Veteran Pirate Pilot'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 7, 'boss_title_4', 'Furious Veteran Pirate Pilot'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 8, 'boss_title_5', 'Ace Veteran Pirate Pilot'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 9, 'complete', 'Fantastic job pilot! We struck a blow to the Pirates that will take them a long time to recover from. Head back to base when ready.'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 10, 'dd_boss_taunt_1', 'Foolish puppet, you should have run while you had the chance!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 11, 'dd_boss_taunt_2', 'To us you''re just a anuiance, about to be squashed!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 12, 'dd_boss_taunt_3', 'Too bad you ran in to me so early in your career, as I mark it''s end!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 13, 'dd_boss_taunt_4', 'Maybe I should fly using just one hand, to give you a chance?'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 14, 'dd_boss_taunt_5', 'Your pilot helmet will look good on my trophy rack, fool!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 15, 'found_loc', 'The next area of known Pirate activity has been uploaded to your nav computer, proceed when ready.'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 16, 'level_boss', 'Superior Command: < The Pirates have sent one of their best pilots to take care of you, be careful! >'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 17, 'level_boss_dead', 'That one has been a dread ever since he came to this sector, great work pilot!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 18, 'level_increase', 'Sensors through out the sectors show increased Pirate activity in response to our attacks.'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 19, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 20, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 21, 'taunt_1', 'Youre not going to survive this fight!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 22, 'taunt_2', 'You should turn back while you can!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 23, 'taunt_3', 'Your about to learn the foolishness of messing with the Pirates!'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 24, 'taunt_4', 'You should never have come here, now you will never leave.'),
('string/en/space/destroy_duty/corellia_privateer_9.stf', 25, 'taunt_5', 'Time to add another puppet on my kill list!'),
('string/en/space/destroy_surpriseattack/corellia_privateer_13.stf', 1, 'title', 'Eliminate Tie Interceptors'),
('string/en/space/destroy_surpriseattack/corellia_privateer_13.stf', 2, 'quest_update', 'Superior Command:'),
