('string/en/space/quest.stf', 123, 'palace_access_text', 'This document authorizes the named subject access to all general parts of our beneful Lord Jabba''s grand palace. By signing this you agree that as long as you are a guest in our magnificient Lord Jabba''s spectacular palace you are the property of our wise and kind Lord Jabba. You also abide to follow all rules stated in document I-32 and understand that failure in doing so may be punished by your termination.'),
('string/en/space/quest.stf', 124, 'palace_access_title', 'Authorization of Access to the Palace of Lord Jabba'),
('string/en/space/quest.stf', 125, 'palace_access_sign', 'Please indicate that you understand what you have just read (or what was read to you) by signing the dotted line on the very bottom of this document. For those without reading and writing comprehension, a thumb (or other appropriate limb) print is acceptable.'),
('string/en/space/quest.stf', 126, 'palace_access_sign_title', 'Dotted line for signature'),
('string/en/space/quest.stf', 127, 'signed_palace_access', 'You signed the dotted line.'),
('string/en/space/quest.stf', 128, 'quest_ended', ' \\#pcontrast3 Mission Ended: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/space/quest.stf', 129, 'quest_ended_group', ' \\#pcontrast3 %TO ended a mission: < \\#pcontrast1 %TT \\#pcontrast3 >'),
('string/en/space/quest_mail.stf', 1, 'corellia_station_mission_subject_one', 'A Unique Opportunity'),
('string/en/space/quest_mail.stf', 2, 'corellia_station_mission_subject_two', 'The Time Has Come'),
('string/en/space/quest_mail.stf', 3, 'corellia_station_mission_body_one', 'Greetings CorSec pilot.\n\nAllow me to introduce myself. I am a representative of the elite association known as the Cloaks.\n\nYou have been selected due to your rank within the Correllia Security Force, and you are being offered a unique opportunity.\n\nWe would like for you to consider working with our society as an agent. Your position allows you access to volumes of valuable CorSec information and supplies.\n\nIf you are interested, I would encourage you to meet with me in Corellian space to discuss the details. It needs not be said that you should mention none of this to CorSec command.\n\nCloaks over all,\n\n< Sender blocked >\nCloak Representative'),
('string/en/space/quest_mail.stf', 4, 'corellia_station_mission_body_two', 'The time has come to serve your purpose as a Cloak agent, CorSec.\n\nVery soon, a supply transport will need to passing through the Corellian system. However, they refuse to jump in unless they will have a CorSec escort.\n\nThe supplies this freighter is carrying would help our cause tremendously, so of course we intend to take them. We need you to provide an "escort" for the freighter. When our attack wing comes in, you will of course allow them to attack and capture the freighter.\n\nFailure in this task will be detrimental. To you.\n\nYou will not mention this to CorSec command.\n\nCloaks over all,\n\n< Sender blocked >\nCloak Representative'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 1, 'title', 'Capture the Star Kimogila'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 2, 'arrival_phase_1', 'Your targeted entourage will arrive at any moment.'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 3, 'arrival_phase_2', 'The Star Kimogila has arrived. Disable the vessel and eliminate her escorts!'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 4, 'capture_phase_1', 'Boarding party is facing light resistance.'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 5, 'capture_phase_2', 'Resistance eliminated. We''ve taken the bridge. We''ll be underway shortly.'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 7, 'quest_update', ' \\#pcontrast3 Hutt Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 8, 'target_disabled', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 The Star Kimogila has been disabled. Capture operation will begin shortly. \\#pcontrast3 >'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 9, 'capture_started', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 Primary mission target capture operation underway. \\#pcontrast3 >'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 10, 'capture_complete', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 Primary mission target capture operation complete! \\#pcontrast3 >'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 11, 'recovery_success', 'The Star Kimogila has been secured. Good job, pilot.'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 12, 'complete', 'We''ve made it to safety. Jumping to lightspeed...now.'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 13, 'failed_escape', 'The Star Kimogila has escaped the area. This is a disgrace! Return to base at once!'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 14, 'failed_destroy', 'The Star Kimogila was destroyed! This is unacceptable! Return to base at once. You are to blame for this failure!'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 15, 'abort', 'Abort code recognized. Stand by for course change... ... Confirmed. You are authorized to leave the system.'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 16, 'escort_wiped_out', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 The targeted vessel''s escort has been eliminated. \\#pcontrast3 >'),
('string/en/space/recovery_duty/corellia_privateer_12.stf', 17, 'escort_remaining', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 %DI ships remain in the vessel''s escort. \\#pcontrast3 >'),
