('string/en/space/taunts/assassins.stf', 92, 'gothit1', 'Reverend Oni`antae! I have been hit! Help me!'),
('string/en/space/taunts/assassins.stf', 93, 'gothit2', 'I will not be defeated!'),
('string/en/space/taunts/assassins.stf', 94, 'gothit3', 'You may destroy me, but you''ll never destroy the Dark Veil Order!'),
('string/en/space/taunts/assassins.stf', 95, 'gothit4', 'Luck seems to be on your side, my friend. But you will not defeat me!'),
('string/en/space/taunts/assassins.stf', 96, 'gothit5', 'Death shall consume you, infidel!'),
('string/en/space/taunts/assassins.stf', 97, 'hityou1', 'A small victory in a vast war against unclean beings!'),
('string/en/space/taunts/assassins.stf', 98, 'hityou2', 'May your death be quick and painless, %Nu!'),
('string/en/space/taunts/assassins.stf', 99, 'hityou3', 'We shall pay homage to your essence as it is consumed by the Heart of Dathomir!'),
('string/en/space/taunts/assassins.stf', 100, 'hityou4', 'Reverend Oni`antae will be pleased!'),
('string/en/space/taunts/assassins.stf', 101, 'hityou5', 'I wish you well in the next life, infidel. The Heart of Dathomir is merciless to the unclean!'),
('string/en/space/taunts/assassins.stf', 102, 'entercombat1', 'Fear the unholy might of the Dark Veil Order!'),
('string/en/space/taunts/assassins.stf', 103, 'entercombat2', 'Reverend Oni`antae! Guide me so that we, together, may destroy this infidel!'),
('string/en/space/taunts/assassins.stf', 104, 'entercombat3', 'The cleansing will start with you, %NU!'),
('string/en/space/taunts/assassins.stf', 105, 'entercombat4', 'The sight of you digusts me! I must cleanse you from the Heart of Dathomir!'),
('string/en/space/taunts/assassins.stf', 106, 'entercombat5', 'May your pain be quick and painless, infidel!'),
('string/en/space/taunts/assassins.stf', 107, 'death1', 'Oh, Reverend Oni`antae, how I have failed you! Save me from despair!'),
('string/en/space/taunts/assassins.stf', 108, 'death2', 'May the Reverend Oni`antae sacrifice you to the Heart of Dathomir!'),
('string/en/space/taunts/assassins.stf', 109, 'death3', 'May the Heart of Dathomir flail the skin off your bones!'),
('string/en/space/taunts/assassins.stf', 110, 'death4', 'Infidel! You shall not escape the Reverend Oni`antae!'),
('string/en/space/taunts/assassins.stf', 111, 'death5', 'The Dark Veil Order shall avenge my death!'),
('string/en/space/taunts/blacksun.stf', 92, 'gothit1', 'Your weapons are weak, %NU!'),
