('string/en/space/taunts/hutt_assassin.stf', 4, 'death4', '%NU, your day will come!'),
('string/en/space/taunts/hutt_assassin.stf', 5, 'death5', 'Be wary, for Jabba''s assassins will be there, hunting you, when you least expect it!'),
('string/en/space/taunts/hutt_assassin.stf', 6, 'entercombat1', 'You have refused to help Jabba! You will die for your insolence!'),
('string/en/space/taunts/hutt_assassin.stf', 7, 'entercombat2', 'We have been sent by Jabba to destroy you! Never refuse to help him!'),
('string/en/space/taunts/hutt_assassin.stf', 8, 'entercombat3', 'We''re Jabba''s assassins, sent to destroy you for denying him the help he requested of you!'),
('string/en/space/taunts/hutt_assassin.stf', 9, 'entercombat4', 'We shall eliminate you for denying Jabba the help he deserves!'),
('string/en/space/taunts/hutt_assassin.stf', 10, 'entercombat5', 'May you die a slow, painful death for the disrespect you have shown Jabba!'),
