('string/en/space/taunts/rebel.stf', 104, 'entercombat3', '%NU, you are no match for me!'),
('string/en/space/taunts/rebel.stf', 105, 'entercombat4', '%TU!  I know of you!  I''ll try to make this quick.'),
('string/en/space/taunts/rebel.stf', 106, 'entercombat5', 'Prepare to die!'),
