('string/en/spacequest/assassinate/corellia_imperial_12.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 2, 'arrival_phase_1', 'Scanning area for the Rebel diplomat.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 3, 'arrival_phase_2', 'The diplomats vessle has been detected.  Transmiting waypoint.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 4, 'assassinate_success', 'The diplomat and escort have been destroyed!'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 9, 'destroy_escort', 'The diplomat''s vessle has been destroyed! Eliminate the support craft.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 10, 'escort_remaining', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 %DI ships remain of the diplomats escort. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 11, 'escort_wiped_out', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Defending ships have been nullified, destroy the primary objective. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 12, 'failed_escape', 'The diplomat has escaped, this will be a serious blow to our negotiations in the area.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 13, 'quest_escort_d', 'To ensure that no one knows what happened to Darmin, you must also destroy all escort fighters that are with him.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 14, 'quest_escort_t', 'Destroy the Diplomat''s Escort'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 15, 'quest_location_d', 'Travel to the Corellian system and intercept the diplomat. Command will locate Darmin''s ship and update you with its progress as it moves through the system.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 16, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 17, 'quest_target_d', 'Intercept and destroy the Rebel diplomat in the Corellian system. You are to make sure that Darmin never makes his meeting with the Corellian government. Once you have completed your assignment report back into your superior.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 18, 'quest_target_t', 'Kill the Rebel Diplomat'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 19, 'quest_update', ' \\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 22, 'title', 'Corellia System: Eliminate The Rebel Diplomat, Darmin Lerspri.'),
('string/en/spacequest/assassinate/corellia_imperial_12.stf', 23, 'title_d', 'Black Epsilon has discovered that a Rebel diplomat, Darmin Lerspri, is on his way to Corellia on a mission to sway the government to be more supportive of the Rebellion. You are being charged with making sure that the diplomat never reaches his destination. You will also have to destroy all escort fighters with Darmin to ensure that no one can report of what the Empire has done.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 2, 'arrival_phase_1', 'Scanning sector for current location of the rebel bomber squadron.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 3, 'arrival_phase_2', 'We have a lock on the squadron. Intercept and destroy immediately.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 4, 'assassinate_success', 'Nice work, pilot. That is what being in Black Epsilon is all about. Return home and report to your superior officer'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 9, 'destroy_escort', 'You have taken out their squad leader but there are still several Y-wings left. Completely eliminate them.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort bombers remaining.>'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort bombers eliminated.>'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 12, 'failed_escape', 'You let those bombers escape? Do you have any idea how much trouble they can cause unchecked! Return to your superior immediately.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 13, 'quest_escort_d', 'Even without their leader, this squadron is still very dangerous and cannot be allowed to remain. You must also destroy all members of the squad.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 14, 'quest_escort_t', 'Destroy the Bomber Squadron'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 15, 'quest_location_d', 'Travel to the Corellian system and intercept the bomber squadron. Command will update you with their progress as they travel through the system.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 16, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 17, 'quest_target_d', 'Intercept and destroy the Rebel bomber leader in the Corellian system. Without their flight leader the combat capabilities of the bomber squadrons in the system will be greatly diminished.'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 18, 'quest_target_t', 'Kill the Rebel Bomber Leader'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 19, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 22, 'title', 'Corellian System: Eliminate the Rebel Bomber Leader'),
('string/en/spacequest/assassinate/corellia_imperial_14.stf', 23, 'title_d', 'Black Epsilon has reports that a Rebel bomber squadron is traveling through the Corellian system. This bomber group is very dangerous to Imperial interests and must be eliminated. Track down the squadron, destroy their leader, and all that fly with him.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 2, 'arrival_phase_1', 'We are getting a lock on the vessels position. Remember that it is going to be on the move so you have to destroy it before it reaches it''s destination.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 3, 'arrival_phase_2', 'We have the lock. Sending you the navigation coordinates to it''s current location. We will keep you updated as it progresses through the region.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 4, 'assassinate_success', 'Nice work, pilot. The drone sent out the distress signal right before you destroyed it. Stand by.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer :\\#pcontrast3 <%DI escort fighters remanining.>'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 12, 'failed_escape', 'You let that ship escape. Report back to your superior and explain to him why this operation was a failure.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 15, 'quest_location_d', 'Travel to the Corellian system and eliminate the X-wing Drone.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 16, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 17, 'quest_target_d', 'Intercept the X-wing drone that is being tracked by Flight Command inside of the Corellian system. Once you destroy the vessel it will send out a distress signal that can be traced back the Rebel communications relay point.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 18, 'quest_target_t', 'Destroy the X-wing Drone'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 19, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 20, 'split_quest_alert', 'Ok we have the location. Stand by for navigation location. Once you have the location, travel there immediately and begin the jamming operation.'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 22, 'title', 'Corellia System: Eliminate the Rebel X-wing Drone'),
('string/en/spacequest/assassinate/corellia_imperial_17.stf', 23, 'title_d', 'The Rebels have been sending drone X-wings to the Corellian system in order to get readings on Imperial formations. Black Epsilon wants to use the Rebels plan against them by attacking one of the drones. When it sends out it''s distress signal Black Epsilon will trace it back to it''s destination. Then you are to travel to that area and begin a jamming operation to distract the Rebels while a main assault is happening.'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 2, 'arrival_phase_1', 'Stand by. We are getting a lock on the Rebel prototype vessel. We will send you the navigation coordinates once we have it''s location.'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 3, 'arrival_phase_2', 'We have sent you the navigation location to the prototype. It looks like the Rebels are trying to get it out of the area. Destroy that ship before it can leave the system. We will update the waypoints with it''s progress as it moves through the system.'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 4, 'assassinate_success', 'Nice work, pilot. That will show the Rebels that we are not afraid of them. Return to your commanding officer on Talus.'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 12, 'failed_escape', 'You let the B-Wing escape. The Rebels probably think that they have gotten one over on us. Fortunately for you we have a trace on another of these prototypes that is in the system. Stand by for more information.'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 15, 'quest_location_d', 'Travel to the Corellian system and destroy the B-wing that is being tested there. When you enter the system wait until you receive a navigation waypoint to its most current location. As the B-wing prototype moves through the system the navigation waypoint will update to its most recent location. Catch up to and destroy the B-wing prototype before it can reach the end of its route and jump out of the system. '),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 16, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 17, 'quest_target_d', 'Intercept and destroy the B-wing prototype in the Corellian system. Follow the navigation waypoints to its most recent location until you have caught up to the B-wing prototype. If the B-wing prototype reaches the end of its path before you intercept it, the B-wing prototype will jump out of the system. Also keep an eye out for any escort fighters that might be traveling with it. They will retaliate when you attempt to destroy the B-wing prototype.'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 18, 'quest_target_t', 'Destroy the B-wing Prototype'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 19, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 20, 'split_quest_alert', 'Another B-wing Prototype have been located. Destroy this new prototype before it gets away as well.'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 22, 'title', 'Corellia System: Destroy the B-wing Prototype'),
('string/en/spacequest/assassinate/corellia_imperial_4.stf', 23, 'title_d', 'Travel to the Corellia system and destroy the B-wing prototype. When you enter the system Imperial command will begin its scan for the B-wing prototype. Once they find it, they will send you a navigation waypoint to its current location. As the B-wing prototype moves through the system this navigation waypoint will update to its most current location. Follow these waypoints until you can intercept the B-wing prototype. Once you have caught up to the B-wing prototype, you must destroy the starfighter. You will have to hurry to catch up to the B-wing prototype because if it reaches the end of its route it will jump out of the system and you will lose your chance to kill it. When you complete this mission, return to Hakasha Sireen at the Imperial Base on Talus and Hakasha Sireen will train you in a new Imperial Pilot skill.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 1, 'arrival_phase_1', 'The target will arive soon, stand by for waypoint.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 2, 'arrival_phase_2', 'The target and escort has arrived, updating waypoint.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 3, 'assassinate_success', 'The target and escort has been destroyed, mission is a success.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 6, 'autorewardfrom', ''),
