('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 8, 'destroy_escort', 'Primary objective has been destroyed, proceed with escort.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 9, 'escort_remaining', 'An escorting craft has been destroyed, %DI remain.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 10, 'escort_wiped_out', 'The escort has been destroyed, proceed to primary objective.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 11, 'failed_escape', 'The target has escaped, you fail.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 12, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 13, 'quest_escort_t', ''),
