('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 16, 'quest_target_d', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 17, 'quest_target_t', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 18, 'quest_update', '%TO'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 20, 'title', 'Assasinate Rebel Contact'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_1e.stf', 21, 'title_d', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 2, 'arrival_phase_1', 'Scanning system for the emissaries ship. Stand by to proceed with destoying his ship.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 3, 'arrival_phase_2', 'Nav location to the target vessel has been located. Proceed with extreme prejudice.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 4, 'assassinate_success', 'Good work, pilot. Without that rebel officer working as a go between, Nym is likely to pull out of the system. Return to your commander.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 9, 'destroy_escort', 'Just to be safe take out the escort fighters as well. We cannot be to careful with this situation.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort fighter eliminated.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 12, 'failed_escape', 'You let him get away! Now we have to wait for another opportunity to try to break the alliance. Report your failure to your commander.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 13, 'quest_escort_d', 'Make sure that all of the emissary''s escort fighters are destroyed as well. Once you have completed this task return to your commander.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 14, 'quest_escort_t', 'Destroy the Escort Fighters'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 15, 'quest_location_d', 'Remain in the Yavin system and eliminate the emissary. It would seem that the emissary is attempting to flee the system.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 16, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 17, 'quest_target_d', 'Intercept the Rebel emissary in the Yavin system and kill him. Without his influence it is almost assured that Nym will withdraw his support.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 18, 'quest_target_t', 'Destroy the Rebel Emissary'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 19, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 22, 'title', 'Yavin System: Eliminate the Rebel Emissary'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_3_a.stf', 23, 'title_d', 'Eliminate the Rebel emissary as he moves through the Yavin systsem. With the information on the attack gathered from the freighter, Black Espilon has managed to determine where the Rebel emissary is. Without the Emissary the Rebels will have a hard time keeping Nym''s support.'),
