('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 2, 'arrival_phase_1', 'Checking valid locations that we found in the transports logs for the patrol vessel. Stand by.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 3, 'arrival_phase_2', 'We have the patrol vessel''s location. Intercept vessel, destroy it, and all that fly with it.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 4, 'assassinate_success', 'One of the patrol vessels sent out a distress signal before being destroyed. Nym is aware of your presence.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 9, 'destroy_escort', 'Take out all of the escort fighters that were with the main target as well.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort fighter eliminated.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 12, 'failed_escape', 'We have lost the patrol vessel from our scans. You let it get away? Who knows when we will get another chance like this. Report this failure to your commander.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 15, 'quest_location_d', 'Remain in the Lok system and intercept the Nym Patrol Craft as it patrols the system.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 16, 'quest_location_t', 'Remain in the Lok System'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 17, 'quest_target_d', 'Intercept and destroy the Nym Patrol Craft as it travels around the Lok system.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 18, 'quest_target_t', 'Destroy the Nym Patrol Craft'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 19, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 20, 'split_quest_alert', 'Nyms is sending out his fleet to intercept you. This is a perfect opportunity for us to hit his smuggling fleet. You have to keep his combat fleet busy while we hit the transports and freighters.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 22, 'title', 'Lok System: Destroy the Nym Patrol Craft'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_a.stf', 23, 'title_d', 'Intercept and destroy the Nym Patrol Craft in the Lok system. Thanks to the information we gathered from the smuggler''s vessel we have a lock on one of the craft Nym uses to patrol the Lok system. The patrol craft is a perfect target for our retribution on Nym.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 2, 'arrival_phase_1', 'Getting a lock on your target vessel. Stand by.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 3, 'arrival_phase_2', 'Location of vessel and it''s escort transmitted. Eliminate that vessel at all costs.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 4, 'assassinate_success', 'If Nym doesn''t get the point that we don''t want him assisting the Rebellion now he will have to be eliminated. Head for home.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 9, 'destroy_escort', 'Since you are there, you should also destroy that vessels escorts.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 10, 'escort_remaining', 'Tactical Computer: <%DI escorts remaining.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 11, 'escort_wiped_out', 'Tactical Computer: <Enemy escorts eliminated.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 12, 'failed_escape', 'Your mission was clear. Take out that ship and you let it get away. With that vessel Nym can easily resupply and be back in operation in no time. Report back to your superior.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 13, 'quest_escort_d', 'Destroy all vessels traveling with the Gunship as well.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 14, 'quest_escort_t', 'Destroy the Escort Fighters'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 15, 'quest_location_d', 'Remain in the Lok system and intercept the Karthakk Queen.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 16, 'quest_location_t', 'Remain in the Lok System'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 17, 'quest_target_d', 'Iintercept and destroy the gunship in the Lok system. Nym is aware of the danger his ships are in and is trying to get this vessel out of the system before anymore damage can be done.'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 18, 'quest_target_t', 'Destroy the Karthakk Queen'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 19, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 22, 'title', 'Lok System: Destroy the Karthakk Queen'),
('string/en/spacequest/assassinate/corellia_imperial_tier3_4_c.stf', 23, 'title_d', 'Destroy the Karthakk Queen in the Lok system. Nym''s freighter fleet is in ruins and his fighters have been greatly reduced. We have learned from the pilot of the smuggler vessel you captured that Nym received a gift from the Rebels to help seal the now defunct deal. A gunboat was given to him by the Rebellion. We a ship of that power Nym will be able to quickly regain control and rebuild his fleet.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 1, 'quest_log_data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 2, 'arrival_phase_1', 'Scanning sector for target vessel. Stand by.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 3, 'arrival_phase_2', 'Nej''a Berto''Lo is right where the captured orders said he would be but it appears he is attempting to leave the sector. Intercept and destroy.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 4, 'assassinate_success', 'The Emperor will be most pleased with your success. You have no idea of what you have just accomplished. Stand by for further instructions.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 9, 'destroy_escort', 'Send a message to our enemies and destroy everyone who was flying with Nej''a.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters destroyed.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 12, 'failed_escape', 'The Emperor will not be pleased at the news you let Nej''a escape. Report back to your superior and hope they show mercy.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 13, 'quest_escort_d', 'Destroy all fighters flying with Nej''a Berto''Lo.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 14, 'quest_escort_t', 'Destroy Nej''a''s Escort'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 15, 'quest_location_d', 'Travel to the Dathomir system and intercept Nej''a Berto''Lo.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 16, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 17, 'quest_target_d', 'Intercept and destory Nej''a Berto''Lo in the Dathomir system before he can jump out of the system.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 18, 'quest_target_t', 'Destroy Nej''a Berto''lo'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 19, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 20, 'split_quest_alert', 'During your battle with Nej''a Berto''Lo, we discovered the presence of a Velocity communications ship nearby. Capture and escort that ship for the Empire.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 22, 'title', 'Dathomir System: Kill Nej''a Berto''Lo'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4.stf', 23, 'title_d', 'Travel to the Dathomir system and kill Nej''a Berto''Lo. Insurgent has been able to put all the pieces together and has discovered the location of the first target, Nej''a Berto''Lo. You are ordered to intercept and destroy Nej''a, along with all that fly with him.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 2, 'arrival_phase_1', 'We are getting a lock on the location of the ship that received the distress signal now. Stand by.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 3, 'arrival_phase_2', 'We have a lock on the vessel. It is Onli Shi''en, the last of the enemy we are hunting. Destroy him and all that are flying with him.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 4, 'assassinate_success', 'You are a true servant of the Emperor. Make you final report to your commander.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 9, 'destroy_escort', 'Nice work on destroying Shi''en, but there are still escort fighters that were with him alive. They all must be destroyed.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters destroyed.>'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 12, 'failed_escape', 'Pilot, your orders were very clear. You were to destroy Onli Shi''en and all with him. By letting him get away, you have allowed his plans to continue. Return and report your failure to you superior.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 13, 'quest_escort_d', 'Destroy all who fly with Onli Shi''en. Once you have completed this task return to your commander.'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 14, 'quest_escort_t', 'Destroy Onli Shi''en''s Escort'),
('string/en/spacequest/assassinate/corellia_imperial_tier4_4_d.stf', 15, 'quest_location_d', 'Remain in the Dathomir system and intercept Onli Shi''en''s fighter.'),
