('string/en/spacequest/assassinate/corellia_rebel_4.stf', 2, 'arrival_phase_1', 'Scanning for the Imperial scum now, give us a few seconds.'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 3, 'arrival_phase_2', 'Got him, proceed to the location and terminate him!'),
