('string/en/spacequest/assassinate/corellia_rebel_4.stf', 10, 'escort_remaining', 'Tactical Computer: < Scans show target vessel escort terminated. %DI escort vessels remain. >'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 11, 'escort_wiped_out', 'Tactical Computer: < Scans show target vessel escort terminated. No more escort vessels remain. >'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 12, 'failed_escape', 'Bah, he got away. Return to base for a full report of what happened.'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 15, 'quest_location_d', 'A lot of our trouble can be traced to a TIE Veteran - commanding a small team of well-equipped forces in the Corellia region. Find him and bring him down.'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 16, 'quest_location_t', 'Corellia system.'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 17, 'quest_target_d', 'We will update the location of the commander as often as we can. Intercept him quickly before he escapes.'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 18, 'quest_target_t', 'Hunt the commander down.'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 19, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 20, 'split_quest_alert', 'Rebel Command: < It looks like the TIE Veteran had a malfunction and you will get another shot at him pilot. Don''t mess up this time! >'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 22, 'title', 'Corellia system: Destroy TIE Veteran commander.'),
('string/en/spacequest/assassinate/corellia_rebel_4.stf', 23, 'title_d', 'This Veteran TIE commander has been a trouble for us for too long. With a skilled pilot like you joining our ranks, we have a chance of getting rid of this nuisance. When you complete this mission, return to Captain Kreezo in Tyrena and Captain Kreezo will train you in a new Rebel Alliance Pilot Skill.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 2, 'arrival_phase_1', 'We are scanning the sector for an intercept course now, stay alert.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 3, 'arrival_phase_2', 'Coordinates uploaded to your nav computer, intercept and destroy the scouts!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 4, 'assassinate_success', 'Good work pilot! We are almost out of here.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 9, 'destroy_escort', 'Nice one pilot, you can''t let any of them escape though, take out those TIE''s!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 10, 'escort_remaining', 'Rebel Command: < Great pilot, destroy them all! Hurry before they get within communication distance of their fleet! >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 11, 'escort_wiped_out', 'Rebel Command: < Only one left, don''t let him slip away pilot! >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 12, 'failed_escape', 'You let them get away! We are preparing a emergency plan. Return to base immediately!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 13, 'quest_escort_d', 'The two escort TIE fighters are mainly there to slow you down and let the TIE Interceptor get away. Never the less, they can''t be allowed to escape either as they can report the same information the Interceptor can.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 14, 'quest_escort_t', 'Destroy escort.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 15, 'quest_location_d', 'You have to stop this Imperial scout patrol but as always in the Yavin system, be careful of attracting more Imperial presence.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 16, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 17, 'quest_target_d', 'The Empire often use a modified TIE Interceptor for scouting. The TIE Interceptor is a very fast fighter so it will be difficult to catch up to him but we''re counting on you.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 18, 'quest_target_t', 'Destroy the Imperial scout ship.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 19, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 20, 'split_quest_alert', 'Rebel Command: < We have a fighter wing that is being intercepted by TIE ships, help them out! >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 22, 'title', 'Yavin system: Destroy the Imperial scout patrol.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_1_c.stf', 23, 'title_d', 'An Imperial scout patrol has spotted you destroying their friends and they are making a break for it to report the incident. They can''t be allowed to escape!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 2, 'arrival_phase_1', 'Uploading coordinates to the last known position of the Imperial reconnaissance ship.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 3, 'arrival_phase_2', 'Proceed to these coordinates and hunt the ship down. He will undoubtedly spot you and try to escape, don''t let him.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 4, 'assassinate_success', 'Good work pilot. Get out of there, we have more missions that require your assistance.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 10, 'escort_remaining', 'Rebel Fleet Command: < Good job but concentrate on the recon ship, you can''t let it get away. >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 11, 'escort_wiped_out', 'Rebel Fleet Command: < Well now you don''t have to worry about those anymore, take out that recon ship! >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 12, 'failed_escape', 'Blasted! He got away, get out of there, he''s sure to have sent for reinforcements.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 15, 'quest_location_d', 'With the increasing presence of Imperial ships in this system, every mission will become harder and harder.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 17, 'quest_target_d', 'The target you need to eliminate is a modified Imperial "Lambda" shuttle. It has advanced sensors, cameras, bugging equipment etc. Even if it doesn''t have any valuable information about our fleet, the opportunity to destroy one of these expensive ships can not be missed.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 18, 'quest_target_t', 'Imperial Advanced Recon ship.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 19, 'quest_update', 'Rebel Fleet Command: < %TO >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 20, 'split_quest_alert', 'Rebel Fleet Command: < Time to ambush some of the Empire lackeys. Proceed to this location and help Green squadron, their numbers are down after some hard battles. >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 22, 'title', 'Endor system: Destroy Imperial Reconnaissance Ship.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_3_a.stf', 23, 'title_d', 'One of the Empires advanced recon ships have been spotted close to the area where you dropped off the data to our command ship. We are not sure if it has revealed the location of our fleet but we can''t take any chances. Terminate it!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 2, 'arrival_phase_1', 'We are pinpointing his location now, stand by.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 3, 'arrival_phase_2', 'Found him, proceed and intercept. Good luck pilot, you will need it.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 4, 'assassinate_success', 'Fantastic! You showed the Empire that their best is not good enough!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 10, 'escort_remaining', 'Good job pilot!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 11, 'escort_wiped_out', 'Nice! Only the Major left now, show him that you are the best!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 12, 'failed_escape', 'He got away, this will make the Empires retaliation very dangerous. Return to base.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 15, 'quest_location_d', 'The Endor system is now in a state of war. Imperial ships are everywhere and their main fleet has arrived, getting battle ready. We can''t understand why the Empire are mobilising such enormous forces just to attack our small fleet but we need to get out of here!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 17, 'quest_target_d', 'Major Kroger is a strategic genius when it comes to Navy warfare. On top of that he''s an excellent pilot and he''s flying one of the best fighters the Empire has, the prototype TIE advanced. We trust that if anyone can do this though, it''s you.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 18, 'quest_target_t', 'Major Kroger.'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 19, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 20, 'split_quest_alert', 'Return to Endor immediately, the Empire is striking down on us hard!'),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 22, 'title', 'Dathomir system: Prevent Major Kroger from reaching the Endor sector.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/assassinate/corellia_rebel_tier3_4.stf', 23, 'title_d', 'We launched several successful attacks against the Empire but they are still coming strong. They have sent for one of their best fighter pilots and navy strategists from the Dathomir system. We are sending our best, you, to take care of him before he can do any damage.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 2, 'arrival_phase_1', 'Uploading the correct coordinates of your target now, get ready.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 3, 'arrival_phase_2', 'Intercept and terminate him pilot! I will update his coordinates to you.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 4, 'assassinate_success', 'Great job pilot! That was a devastating blow to the Empire.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 9, 'destroy_escort', 'Keep at them!'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 10, 'escort_remaining', 'Good work pilot but concentrate on the Inquisitor, you can''t let him get away!'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 11, 'escort_wiped_out', 'I don''t know how you took out all his guard but that should make terminating the Inquisitor a walk in the park, get to it!'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 12, 'failed_escape', 'He got away! We have bigger things to worry about for now though. Stand by.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 15, 'quest_location_d', 'As always a dangerous system with heavy Imperial presence. Be careful on your way to intercepting the Inquisitor but keep in mind that he is your main target and you can''t allow yourself to be distracted.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 17, 'quest_target_d', 'The Inquisitors of the Imperium are always dangerous foes. They are highly skilled and ruthless men, equipped with the latest technology and heavily guarded. Be prepared for a tough battle.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 18, 'quest_target_t', 'Imperial Inquisitor.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 19, 'quest_update', 'Worvog Arkon: < %TO >'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 20, 'split_quest_alert', 'Worvog Arkon: < Your droid picked up some interesting data from the wreck of the Inquisitor. Deliver it to one of the Alliance smugglers that is nearby. >'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 22, 'title', 'Dathomir system: Terminate the Inquisitor.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_2.stf', 23, 'title_d', 'Another part of the Rebel Alliance is attacking vital parts of the Imperial Inquisition. The Empire has sent in one of their high ranking Inquisitors to bolster the morale and help with tactical suggestions in this battle. You will assist our fellow Alliance members by terminating this Inquisitor before he even reaches the battle.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 2, 'arrival_phase_1', 'We are tracking the Imperial freighters now, stand by.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 3, 'arrival_phase_2', 'We found them. Be careful though, we are picking up some strange ship signatures that we haven''t encountered before.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 4, 'assassinate_success', 'Great job my friend! If nothing else, we have delayed any expansion ideas the Empire had in the Lok system.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 9, 'destroy_escort', 'Good work but I''m afraid that command wants that fleet annihilated!'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 10, 'escort_remaining', 'Worvog Arkon: < Keep at it my friend, there''s %DI ships remaining that need to be destroyed! >'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 11, 'escort_wiped_out', 'Worvog Arkon: < Fantastic! Only one to go! >'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 12, 'failed_escape', 'They got away! Return to base, we are going to have to formulate a new plan.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 13, 'quest_escort_d', 'You are ordered to annihilate that entire fleet, not just the freighter.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 14, 'quest_escort_t', 'Annihilate any trace of the fleet.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 15, 'quest_location_d', 'For some reason the Imperial presence is heavy in the Endor system. To top it off their construction freighters are heavily guarded.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 17, 'quest_target_d', 'Your target of destruction is an Imperial Heavy Freighter. Although they are not dangerous they can withstand a lot of damage and it''s sure to be heavily guarded.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 18, 'quest_target_t', 'Imperial Freighter.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 19, 'quest_update', 'Worvog Arkon < %TO >'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 20, 'split_quest_alert', 'Worvog Arkon < The Empire is counter-attacking! The good news is that our reinforcements are almost there! >'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 22, 'title', 'Endor system: Make sure the Imperial freighters never reach Lok.'),
('string/en/spacequest/assassinate/corellia_rebel_tier4_4_a.stf', 23, 'title_d', 'In our campaign to prevent the new Imperial space station from ever being built in the Lok system, we have decided to attack some of their freighters with building materials.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 1, 'arrival_phase_1', 'Deep scanning for Cloak agent signature. Stand by for coordinates.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 2, 'arrival_phase_2', 'Cloak vessel found. Intercept and destroy the agent and his escort.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 3, 'assassinate_success', 'Copy that. Destruction of primary and secondary targets confirmed.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 8, 'destroy_escort', 'Good work, pilot. Primary target destroyed. Now eliminate the escort wing.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 9, 'escort_remaining', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Secondary target destroyed. %DI escort ship(s) remaining.\\#pcontrast1 >'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 10, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Secondary target destroyed. Escort wing eliminated.\\#pcontrast1 >'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 11, 'failed_escape', 'That''s no good, pilot. The agent found us out and called off the delivery. Come back to the station for debriefing.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 12, 'quest_escort_d', 'There must be no suvivors to report back about what we are doing. You must also eliminate any escort that is traveling with the Cloak agent.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 13, 'quest_escort_t', 'Destroy the Agent''s Escort'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 14, 'quest_location_d', 'Travel to the Corellia system. Once there, CorSec command will identify the Cloak agent and send you coordinates to his location via a navigation waypoint.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 15, 'quest_location_t', 'Travel to the Corellia System.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 16, 'quest_target_d', 'You must destroy the Cloak agent before he realizes that we are hunting him and leaves the system.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 17, 'quest_target_t', 'Destroy the Cloak Agent'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 18, 'quest_update', '\\#pcontrast1 CorSec Command: <\\#pcontrast3  %TO\\#pcontrast1  >'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 19, 'split_quest_alert', 'Phase one complete. Begin mission phase two.'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 21, 'title', 'Corellia System: Destroy the Cloak Agent'),
('string/en/spacequest/assassinate/corellia_station_mission3_1.stf', 22, 'title_d', 'Intelligence shows that a Cloak agent will be picking up leaked CorSec information in the Corellia system. CorSec command wants you to destroy the agent and intercept the drop-off.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 1, 'arrival_phase_1', 'Listen up, pilot. This whole operation may have just been a distraction. The Cloak leader is passing through the system as we speak. Stand by.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 2, 'arrival_phase_2', 'We''ve plotted the Cloak leader''s projected course. Intercept and destroy him. And hurry.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 3, 'assassinate_success', 'Excellent work, pilot. The Cloak leader and his escort has been destroyed. Return to the station for debriefing.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 8, 'destroy_escort', 'Copy that. The Cloak leader is destroyed. Now take out the remaining escort craft.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 9, 'escort_remaining', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Secondary target destroyed. %DI escort ships remaining.\\#pcontrast1 >'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 10, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  All secondary targets destroyed.\\#pcontrast1 >'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 11, 'failed_escape', 'The commander is not going to be pleased that you let the Cloak leader escape. Return to the station for debriefing.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 12, 'quest_escort_d', 'All Cloak ships flying with the leader must be destroyed.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 13, 'quest_escort_t', 'Destroy the Leader''s Escort'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 14, 'quest_location_d', 'The Cloak leader must not be allowed to escape. You should not leave the Corellia system until this mission is complete.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 15, 'quest_location_t', 'Remain in the Corellia System'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 16, 'quest_target_d', 'You must intercept the Cloak leader and ensure his destruction. You must not allow him to hyperspace out of the system.'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 17, 'quest_target_t', 'Destroy the Cloak Leader'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 18, 'quest_update', '\\#pcontrast1 CorSec Command: <\\#pcontrast3  %TO\\#pcontrast1  >'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 21, 'title', 'Corellia System: Destroy the Cloak Leader'),
('string/en/spacequest/assassinate/corellia_station_mission5b_3.stf', 22, 'title_d', 'The whole operation to this point has been a distraction so that the Cloak leader could pass through the system while CorSec''s attention was elsewhere. You must hurry and intercept him before he can hyperspace out.'),
('string/en/spacequest/assassinate/c_darndroidspace.stf', 1, 'arrival_phase_1', 'The Black Sun is on the move.  Scanning to find the ship''s location and trajectory.'),
('string/en/spacequest/assassinate/c_darndroidspace.stf', 2, 'arrival_phase_2', 'Kill the Black Sun Transport before it leaves the system.'),
