('string/en/spacequest/assassinate/dath_bh_wanted_list_04.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/dath_bh_wanted_list_04.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/dath_bh_wanted_list_04.stf', 21, 'title', 'WANTED: Juree La''Zar'),
('string/en/spacequest/assassinate/dath_bh_wanted_list_04.stf', 22, 'title_d', ''),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 2, 'arrival_phase_1', 'Scanning region for the Kimogila''s Claw...'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 3, 'arrival_phase_2', 'Kimogila''s Claw has been located. Waypoint created.'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 4, 'assassinate_success', 'The Kimogila''s Claw and her escort retinue have been destroyed!'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 9, 'destroy_escort', 'The Kimogila''s Claw is destroyed! Leave no witnesses. Eliminate the escort retinue.'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 10, 'escort_remaining', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 %DI ships remain in the Kimogila''s Claw''s retinue. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 11, 'escort_wiped_out', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 The escort retinue has been eliminated. Destroy the Kimogila''s Claw. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 12, 'failed_escape', 'The Kimogila''s Claw has escaped the region! You''ve missed your opportunity to deal a blow to Nym!'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 13, 'quest_d', 'b'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 14, 'quest_escort_d', 'Just to be certain that all the commanders are killed, destroy any escorts that are with the Kimogila''s Claw as well. There is no need to let one escape because he was flying his own fighter.'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 15, 'quest_escort_t', 'Destroy the Kimogila''s Claw''s Escort'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 16, 'quest_location_d', 'Travel to the Lok system and destroy the Kimogila''s Claw.'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 17, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 18, 'quest_t', 'a'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 19, 'quest_target_d', 'Intercept the Kimogila''s Claw inside the Lok system. Once it is destroyed, Nym will have to focus more on control of his own system rather then assisting the Rebellion at this point.'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 20, 'quest_target_t', 'Destroy the Kimogila''s Claw'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 21, 'quest_update', ' \\#pcontrast3 Storm Squadron Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 22, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 23, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 24, 'title', 'Lok System: Destroy the Kimogila''s Claw'),
('string/en/spacequest/assassinate/imperial_ss_3.stf', 25, 'title_d', 'Destroy the Kimogila''s Claw in the Lok system. The Kimogila''s Claw contains many of Nym''s top men, and with one strike you can hammer Nym''s ability to command his fleet.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 2, 'arrival_phase_1', 'Stand by. We are scanning the system for the location of the Rebel commander.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 3, 'arrival_phase_2', 'We have the location of the Rebel commander. We have sent you a navigaiton waypoint to his current position. He is on the move so you will have to destroy him before he can exit the system.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 4, 'assassinate_success', 'Nice work, pilot. The Rebel leader has been destroyed and the Rebels are on the run. Return to your commander and report in.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 11, 'escort_wiped_out', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 12, 'failed_escape', 'You let the leader of the squadron get away! That is unacceptable. Fortunately for you it would seem that the leader made a mistake in his jump coordinates and is still in the system. Stand by.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 15, 'quest_location_d', 'Travel to the Naboo system and intercept the X-wing Squad Leader before he can leave the area.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 16, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 17, 'quest_target_d', 'Intercept the X-wing Squad Leader in the Naboo system. It is possible that he will try to leave the system. In this case command will update the navigation waypoints of the route he is taking in order to exit the system. Track him down and destroy him before he is able to flee the system.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 18, 'quest_target_t', 'Destroy the X-wing Squad Leader'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 19, 'quest_update', '\\#pcontrast1 Imperial Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 20, 'split_quest_alert', 'By a stroke of luck you have another chance to take out the X-wing leader. Stand by for new navigation waypoint to his location.'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 22, 'title', 'Naboo System: Destroy the X-wing Squad Leader'),
('string/en/spacequest/assassinate/naboo_imperial_4.stf', 23, 'title_d', 'Destroy the Rebel X-wing Squad Leader in the Naboo system. Imperial Intelligence has a lead on the location of the Rebel team leader who was attempting to capture a shipment of the E-62s. The Rebellion cannot be allowed to get away with these strikes on Imperial interests and the leader of this raid must be destroyed. When you complete this mission, return to Lt. Barn Sinkko in Kadaara and Lt. Sinkko will train you in a new Imperial Pilot skill.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 2, 'arrival_phase_1', 'Scanning Dantooine system for that traitor Hend''s shuttle.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 3, 'arrival_phase_2', 'We have a lock on Hend''s shuttle. Immediately proceed to nav location and destroy the traitor and any escort he has with him.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 4, 'assassinate_success', 'Justice has been served. You have performed your duty to the upmost, pilot. Make your report to your superior officer.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 9, 'destroy_escort', 'Scans still indicate that some of Hend''s escort remains. Send a clear message and hunt them down like the scum they are.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Fighter escort has been eliminated.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 12, 'failed_escape', 'The traitor has escaped! This is a dark day for the Empire. I am sure that your superior will have some questions for you.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 13, 'quest_escort_d', 'All vessels that travel with the Colonel are to be eliminated.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 14, 'quest_escort_t', 'Destroy Colonel Hend''s Escort'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 15, 'quest_location_d', 'Travel to the Dantooine system and intercept Colonel Hend''s shuttle.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 16, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 17, 'quest_target_d', 'Intercept and destroy Colonel Hend. He is probably being very wary and will attempt to run if he detects your presence.'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 18, 'quest_target_t', 'Execute Colonel Hend'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 19, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 22, 'title', 'Dantooine System: Execute Colonel Hend'),
('string/en/spacequest/assassinate/naboo_imperial_tier2_4.stf', 23, 'title_d', 'Kill Colonel Hend in the Dantooine system. It is now obvious that the Colonel was the traitor and has defected to the Rebellion. We have located the Colonel''s shuttle inside the Dantooine system and he must pay for his crimes against the Empire.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 2, 'arrival_phase_1', 'Scanning sector for General Breckon''s ship. Stand by for location.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 3, 'arrival_phase_2', 'General Breckon''s ship has been located. Proceed immediately and elimate the traitor and all with him.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 4, 'assassinate_success', 'Very nicely done. Breckon will no longer be a black eye on the Empire.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 9, 'destroy_escort', 'No one can know about this operation. Destroy the general''s escort fighters as well.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters have been eliminated.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 12, 'failed_escape', 'Fool! You allowed General Breckon to escape. Report back to your superior officer immediately.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 13, 'quest_escort_d', 'There can be no witnesses to what happened to the General. All of the General''s escorts must meet the same fate as he did.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 14, 'quest_escort_t', 'Destroy the General''s Escort'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 15, 'quest_location_d', 'Travel to the Dathomir and intercept General Breckon''s shuttle.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 16, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 17, 'quest_target_d', 'Intercept and kill General Breckon in the Dathomir system. To assist with the cover up, make sure that he never makes it out of the Dathomir system.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 18, 'quest_target_t', 'Destroy the General''s Shuttle'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 19, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 20, 'split_quest_alert', 'Hold position. You are needed to escort Dr. Shinss to the prison planet drop location. Stand by for further instructions.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 22, 'title', 'Dathomir System: Kill General Breckon'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4.stf', 23, 'title_d', 'Kill General Breckon inside the Dathomir system. The Rebel plans, the use of the Dathomir system, and the Doctor''s statements all point that General Breckon was involved in the plot. The General is heading to Naboo in order to dispute these claims. It would be too much of a black eye on the Imperial Army when he is found guilty. Therefore, he must never make it to Naboo. See that he has an accident on his way out of Dathomir.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 2, 'arrival_phase_1', 'We are getting a lock on the position of the command vessel. Once you have the coordinates, proceed to that location, destroy the Price of Liberty and everything with her.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 3, 'arrival_phase_2', 'We have a lock. Sending the location to your navigation computer. Proceed as planned.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 4, 'assassinate_success', 'Good work, pilot. The Rebel menace in the Dathomir system is gone for now. Return to your superior officer and report your success.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 9, 'destroy_escort', 'There are still escort fighters remaining. Wipe them from the galaxy.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI fighter escorts remaining.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Fighter escort eliminated.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 12, 'failed_escape', 'You let the command ship get away! Now the Rebels will be able to strike at us in that system again. Report your failure to your superior officer.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 13, 'quest_escort_d', 'Destroy all escorts that fly with the Rebel command vessel.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 14, 'quest_escort_t', 'Destroy the Escorts'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 15, 'quest_location_d', 'Remain in the Dathomir system and intercept the Rebel command vessel, Price of Liberty.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 16, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 17, 'quest_target_d', 'Intercept and destroy the Rebel command vessel, Price of Liberty. The vessel appears to be on the run after the unsuccessful space battle. Make sure it is destroyed before it can vacate the system.'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 18, 'quest_target_t', 'Destroy the Price of Liberty'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 19, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 22, 'title', 'Dathomir System: Destroy the Price of Liberty'),
('string/en/spacequest/assassinate/naboo_imperial_tier3_4_c.stf', 23, 'title_d', 'Destroy the Rebel command vessel, Price of Liberty, that is inside the Dathomir system. We have received the location of the Rebel command vessel during the battle. Destroying the vessel should cripple the Rebel rescue operation.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 2, 'arrival_phase_1', 'Stand by for nav coordinates to the command vessel.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 3, 'arrival_phase_2', 'Vessel located attempting to leave system. Destroy that ship and all escorts before it is able to make the jump.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 4, 'assassinate_success', 'Very nice, pilot. You are a credit to the Empire. Return to your superior and make a full report.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 9, 'destroy_escort', 'We still detect some of the escort vessels active. Send a clear message to our enemy and destroy them as well.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escorts eliminated.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 12, 'failed_escape', 'The mothership has eluded destruction. We are most unpleased with your performance. Return to your superior and make a report on this blunder.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 13, 'quest_escort_d', 'Destroy the Coynite escort fighters as well as the Coynite Mothership.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 14, 'quest_escort_t', 'Destroy the Escort'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 15, 'quest_location_d', 'Remain in the Dathomir system and intercept the Coynite Mothership.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 16, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 17, 'quest_target_d', 'Intercept and destroy the Coynite Mothership.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 18, 'quest_target_t', 'Destroy the Mothership'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 19, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 22, 'title', 'Dathomir System: Destroy the Coynite Mothership'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_3_b.stf', 23, 'title_d', 'Destroy the Coynite Mothership inside of the Dathomir system. It is time for you to show the Coynite what it means to cross the Empire. We have a lock on the Coynite Mothership and you are to destroy it and all that fly with her.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 2, 'arrival_phase_1', 'We are tracking the vessels departure point. That ship is not to leave the sector. Destroy it as soon as it enters orbit.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 3, 'arrival_phase_2', 'Vessel attempting to leave Dathomir has arrived in ordit. Destroy that ship and every ship with it.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 4, 'assassinate_success', 'Very well done, pilot. But there is more work yet to be done. Stand by.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 9, 'destroy_escort', 'You destoyed the ship leaving Dathomir but there are still members of its escort remaining. No one is to get out alive.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 12, 'failed_escape', 'This is a disaster. You let the ship jump out of the sector. Make a full report of your failure to your superior.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 13, 'quest_escort_d', 'Destroy the Coynite guards that are traveling with the prison break shuttle.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 14, 'quest_escort_t', 'Destroy the Escort'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 15, 'quest_location_d', 'Remain in the Dathomir system and intercept the Prison Break Shuttle.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 16, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 17, 'quest_target_d', 'Intercept and destroy the prison break vessel before it can leave the system. The officers on board cannot be allowed to leave the system.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 18, 'quest_target_t', 'Destroy the Prison Break Shuttle'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 19, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 20, 'split_quest_alert', 'Alert! Another vessel detected attempting to leave Dathomir''s surface. Intercept and destroy.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 22, 'title', 'Dathomir System: Destroy the Prison Break Shuttle'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_b.stf', 23, 'title_d', 'Destroy the Prison Break Shuttle that is attempting to leave the Dathomir system. A vessel has left the planet''s surface. It is believed to be containing more Imperial prison officers. They must be eliminated for their failure in their duty.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 2, 'arrival_phase_1', 'Ship launch detected on planet surface. Stand by for interception coordinates.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 3, 'arrival_phase_2', 'Ship has reached orbit. This vessel and all traveling with her must also be destroyed.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 4, 'assassinate_success', 'Excellent, pilot. You have done well. Those who try to violate the will of the Emperor have met their just fate.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 9, 'destroy_escort', 'There are still some of the escorts that flew with the escaping vessel remaining. Destroy them. Destroy them all.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 12, 'failed_escape', 'You have failed your Emperor. Report this failure to your superior and hope he has mercy to spare.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 13, 'quest_escort_d', 'Any ships with this vessel are enemies of the Empire. Destroy them.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 14, 'quest_escort_t', 'Destroy the Escort Fighters'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 15, 'quest_location_d', 'Remain in the Dathomir system and intercept the Prison Break Shuttle.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 16, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 17, 'quest_target_d', 'Intercept and destroy the prison break vessel before it can leave the system.'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 18, 'quest_target_t', 'Destroy the Prison Break Ship'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 19, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/naboo_imperial_tier4_4_c.stf', 20, 'split_quest_alert', 'Alert! Enemy engaged by TIE 701st wing. Enemy strength under estimated and the wing is in trouble. Request immediate assistance.'),
