('string/en/spacequest/assassinate/naboo_privateer_tier3_4a.stf', 3, 'assassinate_success', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Beldini has been destroyed!  The Diplomatic Corps has one less assassin to fear now. \\#pcontrast3 >'),
