('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 1, 'arrival_phase_1', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Glad you made it out of that mess.  An attack fleet was detected entering Lok Space 15 minutes ago.  They are following the pattern derived from the intercepted transmission.  This operative goes by the name of ''Krayt''s Bane''. Good luck. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 2, 'arrival_phase_2', '\\#pcontrast3 RSF Command: < \\#pcontrast1 No survivors. Repeat, leave no survivors. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 3, 'assassinate_success', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Good job, it seems to me that they are just about out of Assasins.  I imagine we won''t be hearing from the Blacksun for some time now. Return to base.\\#pcontrast3 >'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 6, 'autorewardfrom', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 8, 'destroy_escort', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Primary target has been destroyed.  Proceed to secondary objective. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 9, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Escort craft has been destroyed. %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 10, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 11, 'failed_escape', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The assassin has escaped. Your mission, is a failure. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 12, 'quest_escort_d', 'Destroy these pirates so that they will not finish the task their leaders set out to do'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 13, 'quest_escort_t', 'Black Sun Pirates'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 14, 'quest_location_d', 'An area of known Black Sun activity'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 15, 'quest_location_t', 'Lok System'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 16, 'quest_target_d', 'A dangerous Black Sun Assassin'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 17, 'quest_target_t', 'Krayts Bane'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 18, 'quest_update', '%TO'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 21, 'title', 'Lok System: Destroy the Black Sun Operative'),
('string/en/spacequest/assassinate/naboo_privateer_tier3_4f.stf', 22, 'title_d', 'Destroy the final Black Sun operative'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 2, 'arrival_phase_1', 'Stand by while we track down the TIE Veteran.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 3, 'arrival_phase_2', 'Found him. Proceed to these coordinates and terminate him. We will update your coordinates as he''s moving.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 4, 'assassinate_success', 'Excellent work pilot! The Empire won''t underestimate the Alliance again. Return to base pilot.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 10, 'escort_remaining', 'Tactical Computer: < Scans show target vessel escort terminated. %DI escort vessels remain. >'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 11, 'escort_wiped_out', 'Tactical Computer: < Scans show target vessel escort terminated. No more escort vessels remain. >'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 12, 'failed_escape', 'You let him get away pilot! Return to base immediately.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 15, 'quest_location_d', 'The Naboo system is crawling with the Imperial scum, be careful out there.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 16, 'quest_location_t', 'Naboo system.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 17, 'quest_target_d', 'Your target is in sight. Intercept and destroy it!'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 18, 'quest_target_t', 'TIE Veteran commander.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 19, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 20, 'split_quest_alert', 'Rebel Command: < It looks like the TIE Veteran had a malfunction and you will get another shot at him pilot. Don''t mess up this time! >'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 22, 'title', 'Naboo system: Hunt down the Imperial Veteran.'),
('string/en/spacequest/assassinate/naboo_rebel_4.stf', 23, 'title_d', 'This Veteran TIE commander has been a problem for too long. Your orders are to eliminate this threat to the Alliance. When you complete this mission, return to V3-FX in Moenia and V3-FX will train you in a new Rebel Alliance Pilot Skill.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 2, 'arrival_phase_1', 'We are locking on to the Inquisitor leading the attack now, stand by for coordinates.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 3, 'arrival_phase_2', 'Got him, intercept and terminate the Imperial scum!'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 4, 'assassinate_success', 'Great work my friend, this should cause unease among the Imperial forces.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 10, 'escort_remaining', 'Brother Ezkiel: < Good job pilot, destroy them all! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 11, 'escort_wiped_out', 'Brother Ezkiel: < Excellent, now for the head slime. Get that inquisitor! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 12, 'failed_escape', 'He got away! We are trying to come up with a new plan, get back to base immediately!'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 15, 'quest_location_d', 'The Dantooine system is relatively free of the Imperial curse but in the area you are heading to, they are launching an attack so they will be everywhere.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 16, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 17, 'quest_target_d', 'Inquisitors are dangerous and ruthless individuals, armed with the best of gear and heavily guarded. If you manage to terminate him, it will wreak havoc with the morale of the Imperial ranks as Inquisitors are considered untouchable among the soldiers of the Empire.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 18, 'quest_target_t', 'Imperial Inquisitor.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 19, 'quest_update', 'Brother Ezkiel: < %TO >'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 20, 'split_quest_alert', 'Brother Ezkiel: < We''re already reaping the benefits of the Inquisitors demise. An Imperial Officer wants to defect and need a safe escort. Stand by for coordinates. >'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 22, 'title', 'Dantooine system: Terminate the Inquisitor.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_1.stf', 23, 'title_d', 'The Imperial Inquisition is launching an attack on one of our space stations in the Dantooine system. We have located the leader behind the attack and it is our hope that you will be able to eliminate him my friend.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 2, 'arrival_phase_1', 'We have pinpointed the ship of the leader of the Blacklight pirates and are uploading his coordinates to you now, stand by.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 3, 'arrival_phase_2', 'There he is! The Blacklight Pirates are known for their dogfighting, so be careful. Good luck, pilot. We''re counting on you.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 4, 'assassinate_success', 'Excellent! You successfully assassinated the Blacklight Pirate leader. The Spynet will undoubtedly be grateful. Return to Ezkiel for further instruction.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 9, 'destroy_escort', 'You''ve successfully assassinated the leader, but his cronies won''t let you go unscathed. Destroy them all!'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 10, 'escort_remaining', 'Tactical Computer: < Scanning... ... Remaining Blacklight enemies in the area: %DI >'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 11, 'escort_wiped_out', 'Vortex Command: < Your work isn''t over yet, pilot. His cronies are gone, but you still have the Blacklight leader to deal with. Proceed with your objective! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 12, 'failed_escape', 'Pilot! You''ve failed your mission! Return to Ezkiel for further instruction.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 13, 'quest_escort_d', 'Eliminate the leader''s retinue as well, it''s time to teach these pirate scum a lesson!'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 14, 'quest_escort_t', 'Teach the Blacklights to fear us.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 15, 'quest_location_d', 'You''re heading straight for the center of the Blacklight pirates area so be prepared for anything!'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 17, 'quest_target_d', 'Pirates often obtain their rank through their combat skill so the Blacklight pirate leader will probably be a tough opponent. He''s also bound to be heavily guarded so prepare for a bloody battle.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 18, 'quest_target_t', 'Blacklight pirate leader.'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 19, 'quest_update', 'Vortex Command: < %TO >'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 22, 'title', 'Endor system: Assassinate Blacklight Leader'),
('string/en/spacequest/assassinate/naboo_rebel_tier3_3_d.stf', 23, 'title_d', 'The Blacklight pirate leader is within your grasp, don''t let him slip away!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 2, 'arrival_phase_1', 'An Inquisitor was sent to oversee the annihilation of our shuttles. Now he''s trying to escape, but we won''t let him, will we?'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 3, 'arrival_phase_2', 'Our reconnaissance ship has locked in on him. Intercept and terminate him pilot!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 4, 'assassinate_success', 'Splendid! This was truly a day of victories! Return to base for repairs and some well earned rest pilot.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 10, 'escort_remaining', 'Brother Extok Evin: < Nice job pilot but don''t let that Inquisitor escape! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 11, 'escort_wiped_out', 'Brother Extok Evin: < The escort is taken care of, now for the big prize! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 12, 'failed_escape', 'Bah, he got away! Return to base pilot.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 15, 'quest_location_d', 'Even though the Imperial forces are confused by our strong counter attack, they still outnumber us and it will only be a moment before they regain morale.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 17, 'quest_target_d', 'Inquisitors are always a dangerous foe. They are well trained, ruthless and have access to the best technology the Empire has to offer.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 18, 'quest_target_t', 'Imperial Inquisitor.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 19, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 22, 'title', 'Endor system: Eliminate the escaping Inquisitor.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_1_a.stf', 23, 'title_d', 'The attack was led by an Inquisitor of the Empire. He''s now trying to escape the lost battle, let''s make sure that he pays for the attack!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 2, 'arrival_phase_1', 'The reconnaissance ship is locking in on Master Inquisitor Uvqolo now, stand by.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 3, 'arrival_phase_2', 'Coordinates confirmed. Good luck pilot!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 4, 'assassinate_success', 'I''m most impressed my friend. This event will strike fear through the Empires ranks!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 10, 'escort_remaining', 'Brother Extok Evin: < Good job pilot, make them fear you! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 11, 'escort_wiped_out', 'Brother Extok Evin: < Great! Now show Uvqolo that he''s met his match! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 12, 'failed_escape', 'He got away! I know it wasn''t easy pilot. Stand by for new orders.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 15, 'quest_location_d', 'For a expert pilot like yourself, the Yavin system should be low risk. With a important individual like Uvqolo travelling through the zone though, the security will be tight so stay alert.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 16, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 17, 'quest_target_d', 'Uvqolo is as good at space combat as he is torturing innocents. He would prove a great challenge to you, if he was alone. Unfortunately, he won''t be.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 18, 'quest_target_t', 'Master Inquisitor Uvqolo.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 19, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 20, 'split_quest_alert', 'Brother Extok Evin: < Our reinforcements have arrived. Late of course but lets make something out of it, stand by for new orders. >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 21, 'split_quest_alert_fail', 'Brother Extok Evin: < Look out! Sensors show multiple fighter ship signatures closing in on your position! Defend yourself pilot! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 22, 'title', 'Yavin system: Terminate Master Inquisitor Uvqolo.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2.stf', 23, 'title_d', 'The Empire is bringing in one of their most feared Inquisitors, Uvqolo. He''s a master tactician and has an uncanny ability to find what he''s looking for. One of our spy ships got lucky though and found his travel route through the Yavin system. Unfortunately most of our space fleet is used in escort missions but it is my hope that you will be able to terminate Uvqolo while he''s still en route to the Inquisitions space station.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 1, 'arrival_phase_1', 'Our reconnaissance ships are checking ship signatures for Uvqolo''s location now, give us a second.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 2, 'arrival_phase_2', 'Locked in. Intercept and terminate him pilot, this is your last chance!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 3, 'assassinate_success', 'I''m most impressed my friend. This event will strike fear through the Empires ranks!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 8, 'destroy_escort', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 9, 'escort_remaining', 'Brother Extok Evin: < Good job pilot, make them fear you! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 10, 'escort_wiped_out', 'Brother Extok Evin: < Great! Now show Uvqolo that he''s met his match! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 11, 'failed_escape', 'The slippery wretch got away. Return to base pilot.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 12, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 13, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 14, 'quest_location_d', 'The Dathomir system is always dangerous and the closer Uvqolo get to the Imperial fleet, the more dangerous it will become.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 15, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 16, 'quest_target_d', 'Uvqolo is as good at space combat as he is torturing innocents. He would prove a great challenge to you, if he was alone. Unfortunately, he won''t be.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 17, 'quest_target_t', 'Master Inquisitor Uvqolo.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 18, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 21, 'title', 'Dathomir system: Last chance at Uvqolo.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_2_c.stf', 22, 'title_d', 'Uvqolo is on his way to the Dathomir system but you have one more chance at him before he reaches the Imperial fleet. Hyperspace to the Dathomir system immediately and try to intercept him before he gets away again.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 2, 'arrival_phase_1', 'The Inquisitor probably hope that our spy will lead him to our base. We need you to stop him before he jumps to lighspeed.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 3, 'arrival_phase_2', 'Coordinates uploaded, get over there quickly. Him or his escort can not make their hyperspace jump! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 4, 'assassinate_success', 'Excellent work today my friend. Return to base.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 9, 'destroy_escort', 'Excellent work pilot but you can''t let those other TIEs escape either!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 10, 'escort_remaining', 'Brother Extok Evin: < One more escort remaining, take it out pilot! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 11, 'escort_wiped_out', 'Brother Extok Evin: < Good job pilot, now get that Inquisitor! >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 12, 'failed_escape', 'We will try and get in contact with our operative and let him know he''s been followed. Hopefully we''ll be able to before he reach our base.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 13, 'quest_escort_d', 'The clever Inquisitor has probably made it clear to his escort that if he''s destroyed, they are to take off after the spy. We can''t take any chances, destroy them all!'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 14, 'quest_escort_t', 'Destroy the escort.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 15, 'quest_location_d', 'As if flying in the dangerous Dathomir system wasn''t enough, in this mission you are looking for some of the most vicious foes here.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 17, 'quest_target_d', 'This Imperial Inquisitor is flying one of the Empires most feared ships, the heavily armed and armored Decimator. He''s got a large number of escorts as well so be prepared for a fierce battle.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 18, 'quest_target_t', 'Imperial Inquisitor.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 19, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 22, 'title', 'Dathomir system: Stop the Inquisitor from following the Vortex spy.'),
('string/en/spacequest/assassinate/naboo_rebel_tier4_3_a.stf', 23, 'title_d', 'A Inquisitor tracked our spy and he''s getting ready to hyperspace after him in hopes of tracking down our base of operations. You must stop him before he makes the jump.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_c.stf', 1, 'arrival_phase_1', 'Scanning system for a Black Sun squadron. Stand by to proceed with the attack.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_c.stf', 2, 'arrival_phase_2', 'Nav location to the target squad has been located. Proceed with extreme prejudice.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_c.stf', 3, 'assassinate_success', 'Good work, pilot. That proves you can handle Black Sun pirates.'),
