('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 2, 'arrival_phase_1', 'We are locking on to the Imperial Spy and jamming his comm transmissions, stand by for coordinates.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 3, 'arrival_phase_2', 'Got him, intercept and terminate the Imperial scum!'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 4, 'assassinate_success', 'Great work my friend. Word getting out about our arrangement would have been dangerous.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 10, 'escort_remaining', 'Rori Station: < Good job pilot, destroy them all! >'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 11, 'escort_wiped_out', 'Rori Station: < Excellent, now for the head slime. Get that inquisitor! >'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 12, 'failed_escape', 'He got away! We are trying to relocate him and continue to jam his comm transmissions. Return so that you can go after him again.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 15, 'quest_location_d', 'The Dantooine system is somewhat free of a strong Imperial influence, so the Imperial spy will most likely be jumping to another system. Stop him before that happens.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 16, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 17, 'quest_target_d', 'The Imperial Spy is dangerous in his own right, but also has an escort to help protect him. Even worse news is that he knows you are coming after him!'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 18, 'quest_target_t', 'Imperial Spy.'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 19, 'quest_update', 'Rori Station: < %TO >'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 22, 'title', 'Dantooine system: Terminate the Imperial Spy'),
('string/en/spacequest/assassinate/rori_station_reb_storyquest_01_f.stf', 23, 'title_d', 'An Imperial spy has discovered that you are helping the Rori Station obtain a supply of repair droids. His communication is being jammed. Stop him before he can report to his Imperial commanders.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 1, 'arrival_phase_1', 'Stand by for the location of the Logistics Officer''s ship.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 2, 'arrival_phase_2', 'I have a lock on his vessel. Intercept and destroy that ship for taking my ships.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 3, 'assassinate_success', 'Yes, that will make anyone who takes his place think twice about acting on reckless policies.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 8, 'destroy_escort', 'There are still a few escorts flying around. Take them out too.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 9, 'escort_remaining', 'Tactical Computer: < %DI escort fighters remaining. >'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 10, 'escort_wiped_out', 'Tactical Computer: < Escort fighters eliminated. >'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 11, 'failed_escape', 'Hmmm...looks like he got away. We will just have to try again, I guess.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 12, 'quest_escort_d', 'Destroy everyone with the Logistics Officer.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 13, 'quest_escort_t', 'Destroy the Escort Fighters'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 14, 'quest_location_d', 'The Imperial officer is stationed inside the Dantooine system. He doesn''t have any reason to mask his location so he should not be very hard to find.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 15, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 16, 'quest_target_d', 'Destroy the Imperial Officer so he cannot take any more of the Dantooine supply fleet.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 17, 'quest_target_t', 'Destroy the Logistics Officer'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 18, 'quest_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 19, 'split_quest_alert', 'The Imperials are attacking the remaining fleet of the Dantooine station. Move to the location where they are attacking the fleet and help those freighters survive.'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 21, 'title', 'Dantooine System: Kill the Imperial Logistics Officer'),
('string/en/spacequest/assassinate/stn_dantooine_owner_rebel_landing_tier2_3.stf', 22, 'title_d', 'The Dantooine station owner blames the Imperial Logistics Officer located in the Dantooine station for his lost freighters. You are to intercept and destroy the officer so he cannot take any more of the station''s supply fleet.'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 1, 'arrival_phase_1', '\\#pcontrast3 Endor Station: < \\#pcontrast1 I am transmitting the targets signature to you now. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 2, 'arrival_phase_2', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Target locked in. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 3, 'assassinate_success', '\\#pcontrast3 Endor Station: < \\#pcontrast1 The fleet relays a comendation on that mission Captain.  What is the status of the freighter? \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 5, 'autorewardbody', 'By the authority of < Imperial Research Station: 626 - Endor 2 > you have been awarded a credit bonus of < 15000 > for < Destruction of a suspected Rebel reconnaissance craft operating near Research Station 626 > '),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 6, 'autorewardfrom', 'Office of the Imperial Navy'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 7, 'autorewardsubject', 'Bonus for Mercenary Operations'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 8, 'destroy_escort', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 9, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 10, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 11, 'failed_escape', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Our sensors show the target has jumped out of the system.  I hope they did not find anything that could be used against us in the future. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 12, 'quest_escort_d', 'No escort is detected for the Nova Courier, but always be watchful.'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 13, 'quest_escort_t', 'Escort'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 14, 'quest_location_d', 'Not far from your current location, you are the best bet for destroying this Rebel incursion.'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 15, 'quest_location_t', 'Endor System'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 16, 'quest_target_d', 'Susptected of being on a reconnaissance pass, Imperial command is offering a reward for their destruction. '),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 17, 'quest_target_t', 'Nova Courier'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 18, 'quest_update', '%TO'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 21, 'title', 'Endor System: Opportunities'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_1c.stf', 22, 'title_d', 'A Nova Courier has been spotted in the Endor System.  If at all possible, move out from your escort and destroy this target and return to the Transport quickly.'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 1, 'arrival_phase_1', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Scanning for target \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 2, 'arrival_phase_2', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Target locked in. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 3, 'assassinate_success', '\\#pcontrast3 Kilnstrider: <  \\#pcontrast1 I congratulate you on your quick thinking Captain.  Whatever information they might have taken is not lost to the Rebel Alliance.  This operation is now concluded.  Kilnstrider out. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 5, 'autorewardbody', 'By the authority of < Admiral Kilnstrider > you have been awarded a credit bonus to the sum of < 20000 > for < Elimination of a Rebel operative>'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 6, 'autorewardfrom', 'Office of the Imperial Navy'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 7, 'autorewardsubject', 'Bonus for Mercenary Operations'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 8, 'destroy_escort', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Primary objective destroyed, finish off any remaining escort. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 9, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 10, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 11, 'failed_escape', '\\#pcontrast3 Kilnstrider: < \\#pcontrast1 You let him get away Captain.  Failure seems to be a common thing among you mercenaries. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 12, 'quest_escort_d', 'A pair of Rebel X-Wing fighters, only the operative is important.'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 13, 'quest_escort_t', 'Escort'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 14, 'quest_location_d', 'Coming out of the Isyrn''s Veil hyperspace point making a run for the nearest Rebel outpost'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 15, 'quest_location_t', 'Dantooine System'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 16, 'quest_target_d', 'The Rebel craft seen fleeing from the Endor System.'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 17, 'quest_target_t', 'Rebel operative'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 18, 'quest_update', '%TO'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 21, 'title', 'Dantooine System: The Long Run'),
('string/en/spacequest/assassinate/stn_endor_irs_imp_tier3_2d.stf', 22, 'title_d', 'Intercept the Rebel operative as they make their escape through the Dantooine system.'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 1, 'arrival_phase_1', '\\#pcontrast3 Vestil: < \\#pcontrast1 Information is key, and being able to prevent your opponent from gaining that information is second only to that. Take down this deep space scanner, it will give us the upper hand. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 2, 'arrival_phase_2', '\\#pcontrast3 Tactical Computer: < \\#pcontrast3 Target locked in. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 3, 'assassinate_success', '\\#pcontrast3 Vestil: < \\#pcontrast1 The Empire has been blinded.  More will come, but these little windows of opportunity are vital. \\#pcontrast3 >');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 5, 'autorewardbody', 'You have done fine work.  But I am done with you for now, maybe we can work together again in the future.  As usual, here is your fee of 10000 credits.'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 6, 'autorewardfrom', 'Vestil'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 7, 'autorewardsubject', 'Last Call'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 8, 'destroy_escort', '\\#pcontrast3 Vestil: < \\#pcontrast1 No survivors, finish off their escort. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 9, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 10, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 11, 'failed_escape', '\\#pcontrast3 Vestil: < \\#pcontrast1 The scanner has made the run and is out of the system. I see nothing good coming from this. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 12, 'quest_escort_d', 'An elite group of Imperial Pirates, the Storm Squadron is not to be taken lightly.'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 13, 'quest_escort_t', 'Storm Squadron'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 14, 'quest_location_d', 'Passing through the Lok System, the location of the Scanner will be provided by Nym Forces while the operation is in progress.'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 15, 'quest_location_t', 'Lok System'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 16, 'quest_target_d', 'An Imperial Scan Freighter used to monitor deep space activity.'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 17, 'quest_target_t', 'Imperial Scan Freighter'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 18, 'quest_update', '\\#pcontrast3 < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 21, 'title', 'Lok System: Blessed Obscurity'),
('string/en/spacequest/assassinate/stn_lok_nym_reb_tier2_3a.stf', 22, 'title_d', 'The secrecy of operations in the Lok System is vital. Destroy an Imperial Scanner as they pass through the system to deny the Empire of vial information.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 1, 'arrival_phase_1', 'We are getting a lock on the Debris Cult command vessel now. Stand by.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 2, 'arrival_phase_2', 'The lock on the command vessel has been established. Sending the navigation location to your flight computer. Intercept and destroy the Debris Cult command vessel.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 3, 'assassinate_success', 'That should slow down the Debris Cult''s growth. Excellent work, pilot. You have really made this system safer for us to travel.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 8, 'destroy_escort', 'There are still a few escort vessels around. Let''s clean them up too.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 9, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < %DI escort fighters remaining. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 10, 'escort_wiped_out', '\\#pcontrast1Tactical Computer:\\#pcontrast3 < Escort fighters eliminated. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 11, 'failed_escape', 'Blast it! The command vessel escaped. Return to the station and maybe we will get another shot at it.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 12, 'quest_escort_d', 'For good measure, also destroy his escort fighters.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 13, 'quest_escort_t', 'Destroy the Escort Fighters'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 14, 'quest_location_d', 'The leader of the cult, like the rest of his cult, is in the Yavin system.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 15, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 16, 'quest_target_d', 'Intercept and destroy the Debris Cult Leader'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 17, 'quest_target_t', 'Destroy the Cult Leader'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 18, 'quest_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 21, 'title', 'Yavin System: Kill the Debris Cult Leader'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_debrisassassinate_tier2_1.stf', 22, 'title_d', 'The Yavin 4 Mining Company wants to take a bit of revenge on the Debris Cult for their recent attacks on the company. They have found out where the current leader of the cult is located and have hired you to kill him.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 1, 'arrival_phase_1', 'Stand by for lock on the "Massassi" command vessel. Once this vessel is locked, intercept and destroy it.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 2, 'arrival_phase_2', 'Location to the "Massassi" command vessel has been sent to your flight computer.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 3, 'assassinate_success', 'Nice work. The Corellia Deep Mining Company will think twice before messing with us again.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 8, 'destroy_escort', 'Take out the rest of that ships escort. We want to show the Corellia Deep Mining Company that we mean business.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 9, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < %DI escort fighters remaining. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 10, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Escort fighters eliminated. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 11, 'failed_escape', 'You let them get away. Hopefully we will get another shot at him. Return to the space station.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 12, 'quest_escort_d', 'The job should be done cleanly. Any who are with the command vessel should also be destroyed.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 13, 'quest_escort_t', 'Destroy the Vessel''s Escort'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 14, 'quest_location_d', 'The fake Massassi ship is located inside of the Yavin system.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 15, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 16, 'quest_target_d', 'Destroy the command vessel and send a clear message to the Yavin 4 Mining Company''s competitor.'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 17, 'quest_target_t', 'Destroy the Fake Massassi Command Ship'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 18, 'quest_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 21, 'title', 'Yavin System: Destroy the "Massassi" Leader'),
('string/en/spacequest/assassinate/stn_yavin4_company_all_massassi_tier2_11.stf', 22, 'title_d', 'Now that the secret of the Massassi is out, the company wants to punish them for their deception. They have managed to discover the location of the vessel organizing the attacks and they have hired you to deal with the vessel.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 2, 'arrival_phase_1', 'Stand by. We are scanning the system for the Commerce Raider Leader''s position.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 3, 'arrival_phase_2', 'We are sending you a navigation waypoint to the leaders current position. He is attempting to make a run for it. We will send you updated navigation waypoints as he progresses through the system. Follow and destroy him.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 4, 'assassinate_success', 'Nice work, pilot. Without their leader the Commerce Raiders will be far less aggressive. Report back to your commander.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 12, 'failed_escape', 'How could you let him get away? That is unacceptable. You are lucky we are still tracking the leader. Stand by for update to his location.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 15, 'quest_location_d', 'Travel to the Tatooine system and intercept the Commerce Raider Leader.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 16, 'quest_location_t', 'Travel to the Tatooine System'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 17, 'quest_target_d', 'Intercept and destroy the Commerce Raider Leader to the Tatooine system. In order for the Empire to have any control over these nefarious pirates you will have to take out their leader. The pirate is making a run for it so we will update you on his progress by sending you new waypoints as he moves through the sector.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 18, 'quest_target_t', 'Destroy the Commerce Raider Leader'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 19, 'quest_update', '\\#pcontrast1 Imperial Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 20, 'split_quest_alert', 'The leader jumped a short distance away so you still have a chance to take him out. Travel to his new location and destroy him.'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 22, 'title', 'Tatooine System: Destroy the Commerce Raider Leader'),
('string/en/spacequest/assassinate/tatooine_imperial_4.stf', 23, 'title_d', 'Destroy the Commerce Raider Leader in the Tatooine system. The Commerce Raiders are becoming a problem that is quickly growing out of control. Intelligence has managed to get a lock on where the pirate''s leader is laying low. Without their leader, Imperial Command hopes that the pirates will lose a great deal of their effectiveness. You are to destroy this leader. When you complete this mission, return to Lt. Akal Colzet in the Imperial Pilot''s Association Hall next to the Bestine Capital building and Lt. Colzet will train you in a new Imperial Pilot skill.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 1, 'arrival_phase_1', 'Stand by for navigation waypoint to the X-wing fighter squadron.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 2, 'arrival_phase_2', 'X-wing fighter squadron located. Proceed to the supplied navigation waypoint and eliminate the threat.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 3, 'assassinate_success', 'The X-wing threat has been eliminated. Nice work, pilot.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 8, 'destroy_escort', 'The lead X-wing has been destroyed but other members of the squadron are still alive. Make sure that none of them are able to escape the system.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 9, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI enemy fighter escorts remaining.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 10, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter escorts eliminated.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 11, 'failed_escape', 'The squadron of X-wings has managed to escape the system. You have failed in your duty to protect the interests of the Empire. Report back to your commander immediately.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 12, 'quest_escort_d', 'Eliminate the Rebel threat by destroying the entire Rebel squadron.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 13, 'quest_escort_t', 'Destroy all Members of the Squadron'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 14, 'quest_location_d', 'The X-wing squadron is moving through the Endor System. Intercept and destroy them as they make their way through the region.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 15, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 16, 'quest_target_d', 'Your primary target is the squadron leader. Make sure that this Rebel never makes it to his destination.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 17, 'quest_target_t', 'Kill the X-wing Squadron Leader'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 18, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 19, 'split_quest_alert', 'Reports that the Rebels have attacked one of our command shuttles has just reached us. The first wave crippled the shuttle and they are reporting that the Rebels are massing for another attack. Rescue that shuttle before they can be destroyed.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 21, 'title', 'Endor System: Destroy the Rebel X-wing Squadron'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4.stf', 22, 'title_d', 'We have a lock on the Rebel command vessel, but the time has not yet come to attack it. We still do not know exactly what the Rebels are doing in this system. But command wants to start culling the number of Rebels in the system. There is a Rebel X-wing squadron traveling through the Endor system. Intercept and destroy the entire squadron.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 2, 'arrival_phase_1', 'Proceed to target location immediately. Rebel command ship is attempting to hyper jump out of the system.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 3, 'arrival_phase_2', 'Target confirmed. Be wary it will probably be heavily guarded.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 4, 'assassinate_success', 'Excellent work, pilot. This is a glorious day for the Empire. Report back to your superior and give a full report.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 9, 'destroy_escort', 'Send a clear message to the Rebels. Destroy all the vessels that are with the command vessel.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort ship destroyed. %DI Escorts Remaining.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort fighters completely eliminated. Focus attack on command ship.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 12, 'failed_escape', 'You let it get away! Failure is unacceptable. Report to your superior immediately.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 13, 'quest_escort_d', 'Destroy all vessels that fly with the command ship.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 14, 'quest_escort_t', 'Destroy the Escort Craft'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 15, 'quest_location_d', 'Remain in the Endor system and intercept the Rebel Command Shuttle.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 16, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 17, 'quest_target_d', 'Intercept and destroy the Rebel''s command shuttle in the Endor system. It appears that the vessel is attempting to leave the system. You must destroy it before it can leave the area.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 18, 'quest_target_t', 'Destroy the Rebel Command Shuttle'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 19, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 22, 'title', 'Endor System: Destroy the Rebel Command Shuttle'),
('string/en/spacequest/assassinate/tatooine_imperial_tier3_4_c.stf', 23, 'title_d', 'Destroy the Rebel Command Shuttle in the Endor system. The recovered data reveals the secrets of the Endor project that were leaked to the Rebellion. Fortunately there was nothing there that couldn''t be covered up and not enough information to keep the Rebels interested if we make things too costly. The Rebel command vessel is no longer needed and is to be eliminated.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 2, 'arrival_phase_1', 'Scanning system for stolen transport. Once you have the location destroy that transport and all that are with it.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 3, 'arrival_phase_2', 'We have the location of the transport. Proceed to the location that is in your navigation computer.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 4, 'assassinate_success', 'Those Bothan never knew what hit them. Excellent work, pilot.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 9, 'destroy_escort', 'You must take out the remaining escorts. No one is to be left alive.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escorts have been eliminated.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 12, 'failed_escape', 'We lost the shuttle. Now there is nothing to stop them from delivering it to the Rebellion. Report your failure to your superior officer immediately.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 13, 'quest_escort_d', 'The Bothans have gone to far in their meddling. Destroy all that fly with our transport.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 14, 'quest_escort_t', 'Destroy the Escort'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 15, 'quest_location_d', 'Travel to the Dantooine system and intercept the captured Engineer transport.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 16, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 17, 'quest_target_d', 'Destroy the captured Engineer transport in the Dantooine system. The Bothans cannot be allowed to have this valuable source of information.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 18, 'quest_target_t', 'Destroy the Captured Engineer Transport'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 19, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 20, 'split_quest_alert', 'Another transport has been located. Destroy this transport and its escort as well.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 22, 'title', 'Dantooine System: Destroy the Captured Engineer Transport'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4.stf', 23, 'title_d', 'Destroy the captured Engineer transport in the Dantooine system. The shuttle you have recovered has revealed that the Bothans took all of the transports to the Dantooine system. They are apparently waiting for Rebel agents to arrive and pick up the transports. This cannot be allowed to happen.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 2, 'arrival_phase_1', 'Getting a lock on the second transport. Once you have the location destroy it and all that fly with it.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 3, 'arrival_phase_2', 'Sending the location to your navigation computer. Be alert, they are aware of your presence.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 4, 'assassinate_success', 'Excellent. We are now only missing one transport.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 6, 'autorewardbody', ''),
