('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 9, 'destroy_escort', 'Some of the transport''s escort still remain. Send a message and destroy them as well.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 11, 'escort_wiped_out', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 12, 'failed_escape', 'We lost the transport. Now there is nothing to stop them from delivering it to the Rebellion. Report your failure to your superior officer immediately.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 13, 'quest_escort_d', 'All the Bothan pilots that are with the transport must also be destroyed.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 14, 'quest_escort_t', 'Destroy the Escort'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 15, 'quest_location_d', 'Remain in the Dantooine system and intercept the captured Engineer transport.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 16, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 17, 'quest_target_d', 'Destroy the second captured Engineer transport in the Dantooine system to avoid allowing it to fall into enemy hands.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 18, 'quest_target_t', 'Destroy the Captured Engineer Transport'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 19, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 20, 'split_quest_alert', 'The Inquisition officer requests that we capture the last transport and bring it back so he can question the Bothan spies.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 22, 'title', 'Dantooine System: Destroy the Captured Engineer Transport. Part II'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_a.stf', 23, 'title_d', 'Destroy the captured Engineer transport in the Dantooine system. The location of another transport has been found. Destroy this transport as well.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 2, 'arrival_phase_1', 'Getting a lock on the rebel command group. None of them is to make it out alive.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 3, 'arrival_phase_2', 'We have the lock. Sending that information to your nav computer. It looks like they are trying to make a run for it.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 4, 'assassinate_success', 'The rebels will remember this day. You have done very well. Report your success back to your superior.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 9, 'destroy_escort', 'There are still some other rebel ships in the area. Make sure none of them escape.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 10, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI enemy escorts remaining.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 11, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort fighters destroyed.>'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 12, 'failed_escape', 'You let them slip through your fingers. Report this failure to your superior immediately.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 13, 'quest_escort_d', 'Make sure no one gets out alive. Destroy the escorts. Once completed return to your commander.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 14, 'quest_escort_t', 'Destroy the Escorts'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 15, 'quest_location_d', 'Remain in the Dantooine system and intercept the Rebel command vessel.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 16, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 17, 'quest_target_d', 'Intercept and destroy the Rebel command vessel inside the Dantooine system.'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 18, 'quest_target_t', 'Destroy the Rebel Command Vessel'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 19, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
