('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 22, 'title', 'Dantooine System: Destroy the Rebel Command Vessel'),
('string/en/spacequest/assassinate/tatooine_imperial_tier4_4_c.stf', 23, 'title_d', 'Destroy the Rebel command vessel in the Dantooine system. It was on it''s way to pick up the captured shuttles has appeared in the system. Show the Rebels that their actions will not go unpunished.'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 2, 'arrival_phase_1', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 The Ace will be entering your area shortly, be ready. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 3, 'arrival_phase_2', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 Ok, the Black Sun group has arrived.  Leave no survivors. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 4, 'assassinate_success', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 Feels good to have a little less competition. Bring it home now Captain. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 9, 'destroy_escort', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 Good job on taking out that Ace, now finish off her escort. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 10, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 11, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 12, 'failed_escape', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 This Ace will return for some more kills on our freighters.  Most unacceptable. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 13, 'quest_escort_d', 'The Ace''s Escort, should be easy targets. Must be destroyed to complete the mission'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 14, 'quest_escort_t', 'Black Sun Fighter'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 15, 'quest_location_d', 'Near a trade route in the Tatooine System'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 16, 'quest_location_t', 'Tatooine System'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 17, 'quest_target_d', 'A Black Sun ace terrorizing the Smuggler Alliance trade lanes'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 18, 'quest_target_t', 'Black Sun Ace'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 19, 'quest_update', '\\#pcontrast3 < %TO >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 20, 'split_quest_alert', '\\#pcontrast3 Dravis: < \\#pcontrast1 You appear to have hit a little snag out there.  Get patched up and take down that Ace. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 21, 'split_quest_alert_fail', '\\#pcontrast3 Dravis: < \\#pcontrast1 You appear to have hit a little snag out there.  Get patched up and take down that Ace. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 22, 'title', 'Tatooine System: Eliminate the Black Sun Ace'),
('string/en/spacequest/assassinate/tatooine_privateer_tier1_4a.stf', 23, 'title_d', 'Destroy a Black Sun ace as they travel through the Tatooine System. When you complete this mission, return to Dravis in back room of the Mos Eisley cantina and Dravis will train you in a new Pilot skill.'),
('string/en/spacequest/assassinate/tatooine_privateer_tier2_1a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_privateer_tier2_1a.stf', 2, 'arrival_phase_1', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 Scanning the zone for our target, be ready. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier2_1a.stf', 3, 'arrival_phase_2', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 Target has arrived, proceed with the operation. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tatooine_privateer_tier2_1a.stf', 4, 'assassinate_success', 'The operation is a success.'),
('string/en/spacequest/assassinate/tatooine_privateer_tier2_1a.stf', 5, 'assigned_delayed', ''),
