('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 2, 'arrival_phase_1', 'We are tracking the TIE Veteran, stand by pilot.'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 3, 'arrival_phase_2', 'Got him! Proceed to intercept and terminate him immediately. We will update his coordinates as he''s moving.'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 4, 'assassinate_success', 'Very impressive pilot. The loss of that pilot will be a big blow to the Empire in this system. Return to base.'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 10, 'escort_remaining', 'Tactical Computer: < Scans show target vessel escort terminated. %DI escort vessels remain. >'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 11, 'escort_wiped_out', 'Tactical Computer: < Scans show target vessel escort terminated. No more escort vessels remain. >'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 12, 'failed_escape', 'You let him get away pilot! What happened up there?! Return to base immediately!'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 15, 'quest_location_d', 'In our continous war against the Empire, eliminating key enemies like this Veteran Commander can sway the battle of a whole system.'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 16, 'quest_location_t', 'Tatooine system.'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 17, 'quest_target_d', 'The Veteran commander is being tracked. Intercept and terminate him pilot!'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 18, 'quest_target_t', 'Time for action.'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 19, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 20, 'split_quest_alert', 'Rebel Command: < It looks like the TIE Veteran had a malfunction and you will get another shot at him pilot. Don''t mess up this time! >'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 22, 'title', 'Tatooine system: Eliminate TIE Veteran commander.'),
('string/en/spacequest/assassinate/tatooine_rebel_4.stf', 23, 'title_d', 'The Empire has a Veteran commander stationed in the Tatooine system that has been a problem for us ever since he''s arrived. You''re about to take care of that problem. When you complete this mission, return to Commander Da''la Socuna in back room of the Mos Espa cantina and Commander Socuna will train you in a new Rebel Alliance Pilot Skill.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 2, 'arrival_phase_1', 'Good, you are here. We are tracking a high prize officer of the Empire, an Imperial Inquisitor. If you can defeat him, it would be a hard blow to the Empire.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 3, 'arrival_phase_2', 'Alright, one of our sensor vessels have locked on to him now. Chase him down and defeat him pilot, good luck!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 4, 'assassinate_success', 'Fantastic! Eliminating a member of the Inquisition will strike fear in the Empire, they are regarded as untouchable by their own.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 10, 'escort_remaining', 'Rebel Command: < Excellent, there is %DI of the escort remaining. The most important is the Inquisitor though, don''t let him get away! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 11, 'escort_wiped_out', 'Rebel Command: < Very good, the Inquisitor will be a easy target without his escort, go get him! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 12, 'failed_escape', 'Bah! He got away! Maybe there is more to the rumor of the Inquisitors invincibility than we thought.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 15, 'quest_location_d', 'The Dantooine system is not considered to have a heavy Imperial presence but an Inquisitor never travels alone. Don''t let your guard down pilot.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 16, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 17, 'quest_target_d', 'Imperial Inquisitors are as skilled as they are ruthless. They are equipped with the best equipment and heavily guarded so this won''t be easy. You''ve done well so far though, don''t let us down now.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 18, 'quest_target_t', 'Imperial Inquisitor.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 19, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 20, 'split_quest_alert', 'Rebel Command: < While you are here, there''s a squad of B-Wing bombers that could use help getting past some Imperial fighters. >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 22, 'title', 'Dantooine system: Defeat Imperial Inquisitor in the Dantooine sector.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_2_b.stf', 23, 'title_d', 'We want to keep this winning streak going and we have the perfect target. An Imperial Inquisitor is in transit through the Dantooine system. Eliminate him and it will put fear through out the ranks of the Empire.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 2, 'arrival_phase_1', 'We are pinpointing the location of their ''Hero'' now. He''s using some sort of scrambler, so we are not sure what kind of escort he has.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 3, 'arrival_phase_2', 'Alright, proceed to intercept him. We will update you with new coordinates as he is moving.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 4, 'assassinate_success', 'Beautifully done pilot, I would love to see the faces of the officers at that ceremony when they hear about this.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 10, 'escort_remaining', 'Tactical Computer: < Scans show one of main targets escort vessels terminated. >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 11, 'escort_wiped_out', 'Tactical Computer: < Scans show only battle functioning vessel in area is main target. >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 12, 'failed_escape', 'He got away. Oh well, we''ll get him the next time.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 15, 'quest_location_d', 'The Endor system is fairly unknown to us but initial intel shows that the Empire has been gathering an unusually large force here. For now, it remains a mystery as to why but for you, this means extra caution is to be used.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 17, 'quest_target_d', 'This Imperial officer is not on his way to an award ceremony for nothing. He''s flying one of the deadly TIE Advanced models and he''s a skilled pilot so be swift, effective and careful.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 18, 'quest_target_t', 'Imperial fighter pilot officer.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 19, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 20, 'split_quest_alert', 'Rebel Command: < We need some scan data from a region in this sector, stand by for new coordinates. >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 22, 'title', 'Endor system: Terminate the Imperial "Hero".'),
('string/en/spacequest/assassinate/tatooine_rebel_tier3_4.stf', 23, 'title_d', 'An Imperial fighter pilot is on his way to be decorated for his victories against us. Let''s send a message to the Empire they will not forget by making sure he never reaches his award ceremony.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 2, 'arrival_phase_1', 'The Empire is pulling out their advanced ships. I''m assigning each of you one to hunt down, stand by.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 3, 'arrival_phase_2', 'Alright pilot, this is your assigned target, don''t let him slip away!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 4, 'assassinate_success', 'That''s what I expect from my pilots! Return to base.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 10, 'escort_remaining', 'General Ufwol: < Concentrate on the experimental TIE ship, I don''t want that thing to get away! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 11, 'escort_wiped_out', 'General Ufwol: < Alright pilot, now take out that last TIE! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 12, 'failed_escape', 'You let him get away pilot! Return to base immediately!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 15, 'quest_location_d', 'Pay close attention to your sensors. This is a high risk area in a high risk system and you''re chasing one of the Empires deadly new ships, you don''t need to attract more enemies.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 17, 'quest_target_d', 'This is one of the Empires latest and most dangerous TIE models. It''s equipped with a rear firing turret so try to strafe it from the flanks.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 18, 'quest_target_t', 'Imperial TIE ''Aggressor'''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 19, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 22, 'title', 'Dathomir system: Hunt down the Imperial advanced fighters.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_1_a.stf', 23, 'title_d', 'Some of the Empires advanced ships that were close by are trying to escape the carnage. Hunt them down like the vermin they are!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 2, 'arrival_phase_1', 'Several of the station officers are trying to escape. We''re sending you after the commander, don''t disappoint me pilot.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 3, 'arrival_phase_2', 'This is the last known location of the commander, intercept and destroy his shuttle!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 4, 'assassinate_success', 'Excellent pilot, looks like I sent the right man for the job. Return to base.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 10, 'escort_remaining', 'General Ufwol: < Concentrate on the commander pilot, you can''t let him get away. >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 11, 'escort_wiped_out', 'General Ufwol: < His escort is terminated, now take that shuttle down! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 12, 'failed_escape', 'Bah, he got away! This will go in to your record pilot. Return to base.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 15, 'quest_location_d', 'Most of the Imperial forces are either fleeing or trying to get reinforcements. The area still have a lot of them though so stay on your toes!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 17, 'quest_target_d', 'The station commander is travelling in a heavily armored and armed shuttle model ''Lambda''. He''s also got a large escort so prepare for a difficult battle.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 18, 'quest_target_t', 'Station commander.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 19, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 22, 'title', 'Endor system: Prevent the station commander from escaping.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_a.stf', 23, 'title_d', 'The Imperial space station commander is trying to escape! Eliminate him before he can jump to lightspeed!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 2, 'arrival_phase_1', 'The Empire has launched a bomber wing against one of our frigates! Uploading coordinates now.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 3, 'arrival_phase_2', 'Alright, intercept and destroy them quickly, we can''t let them launch those torpedoes!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 4, 'assassinate_success', 'Good job pilot, we''re pulling back for now. Return to base.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 9, 'destroy_escort', 'You have to take them all out before they get much closer pilot!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 10, 'escort_remaining', 'General Ufwol: < Good pilot but there''s more of them left and they are getting close to launch distance! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 11, 'escort_wiped_out', 'General Ufwol: < Only one left pilot, hurry up! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 12, 'failed_escape', 'They launched their payload! This day was a complete disaster! You have some explaining to do pilot, return to base!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 13, 'quest_escort_d', 'Each of these bombers have a payload large enough to inflict serious damage to our frigate. You need to destroy them all pilot!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 14, 'quest_escort_t', 'Eliminate them all.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 15, 'quest_location_d', 'The Empire is launching everything the have close to us. Your target is that bomber wing though, try to avoid everything else!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 17, 'quest_target_d', 'There is one TIE Oppressor and five TIE Bombers heading for our frigate. You need to eliminate them all. They are bombers and shouldn''t be as dangerous for you as fighters but they can still pack a punch so don''t underestimate them.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 18, 'quest_target_t', 'Imperial bomber wing.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 19, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 22, 'title', 'Endor system: Stop the Imperial bombers.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_3_b.stf', 23, 'title_d', 'After our failure to eliminate the space stations defense, the Empire is launching several counterattacks. A bomber wing is heading for one of our escaping frigates. You need to intercept and destroy them before they can launch their payloads on it.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 2, 'arrival_phase_1', 'Our reconnaissance ship is transferring the location of the the target now, stand by.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 3, 'arrival_phase_2', 'Hmm, that''s no TIE Bomber... I''m not sure what that ship is but either way, it has to be stopped. Intercept it pilot!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 4, 'assassinate_success', 'That turned out to be a lot tougher than expected but you came through for the squad pilot, good job!'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 9, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 10, 'escort_remaining', 'General Ufwol: < Good job pilot but don''t let that big ship slip out of your grasp! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 11, 'escort_wiped_out', 'General Ufwol: < Excellent pilot, only the main bogey left! >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 12, 'failed_escape', 'Maybe accepting you as a full member of the squad was a mistake pilot...'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 13, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 14, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 15, 'quest_location_d', 'Our successful attacks on the Empire in this system have made them increase their presence and their security measures. It''s more dangerous here than ever so don''t even begin to relax pilot.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 17, 'quest_target_d', 'What was supposed to be a TIE bomber has turned out to be something completely different. We have never seen this ship model before so approach with extreme caution. We still need it destroyed though pilot, no time to back out now.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 18, 'quest_target_t', '''TIE Bomber'''),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 19, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 20, 'split_quest_alert', 'General Ufwol: < We are curious about this big ship you just took out and are sending a recovery team to pick up it''s debris. Stand by. >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 21, 'split_quest_alert_fail', 'General Ufwol: < You can''t return to base just yet pilot. We have found another one of those big ships and we want to find out more about them. Stand by. >'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 22, 'title', 'Endor system: Terminate the TIE Bomber and its cargo.'),
('string/en/spacequest/assassinate/tatooine_rebel_tier4_4.stf', 23, 'title_d', 'Welcome as a full member of the Crimson Phoenix pilot. You are now one of the best the Alliance Navy has to offer, make sure you keep it that way. The attack in the Endor system didn''t give us any useful information to the production of the new Imperial fighters and now it''s too late anyway, they are spread through out the galaxy. For this mission, Intel has provided us with information that a TIE Bomber is carrying some important machinery to the surface of the moon of Endor. Let''s make sure it never reaches its destination.'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 1, 'arrival_phase_1', 'There he is! Time to claim your bounty pilot! Don''t let him get away!'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 2, 'arrival_phase_2', 'He''s trying to escape, but we''ve locked on to him. Your nav computer should have a waypoint now. Go get him!'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 3, 'assassinate_success', 'Not bad, not bad at all. You should get an e-mail verifying the transfer of funds to your bank account in a few seconds. Pleasure doing business with you pilot.'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 5, 'autorewardbody', 'Bank statement. Confirmation of fund transfer. Nairalav Shipping Co. transfered the sum of 10,000 credits to your bank account. Sincerely, Ovpi Urgon, Bank Manager, Mos Espa Valid.'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 6, 'autorewardfrom', 'Mos Espa Valid'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 7, 'autorewardsubject', 'Transfer of funds to your account.'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 8, 'destroy_escort', ''),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 9, 'escort_remaining', 'Valarian Assassin Coordinator: < Good, but you better not let Hortrix escape! >'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 10, 'escort_wiped_out', 'Valarian Assassin Coordinator: < Alright, now claim your bounty, terminate Hortrix! >'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 11, 'failed_escape', 'You had him and you let him get away! That''s it, come back when you know what you''re doing.'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 12, 'quest_escort_d', ''),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 13, 'quest_escort_t', ''),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 14, 'quest_location_d', 'This area of the Yavin system should be relatively safe from Imperial enemies and pirates but you got other enemies to worry about, your target is in your sights!'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 15, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 16, 'quest_target_d', 'Hortrix Steelarm is not a fighter pilot but he''s an expert at avoiding enemies and he''s got a few tricks up his sleeve so stay sharp!'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 17, 'quest_target_t', 'Hortrix Steelarm.'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 18, 'quest_update', 'Valarian Assassin Coordinator: < %TO >'),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 19, 'split_quest_alert', ''),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 20, 'split_quest_alert_fail', ''),
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 21, 'title', 'Yavin system: Time to get paid.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/assassinate/tatooine_station_hutt_palace_access_quest_4.stf', 22, 'title_d', 'Your sensors have spotted Hortrix and he''s making a break for it. Catch up to him and terminate him but be careful, he''s a skilled and tricky pilot.'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 1, 'arrival_phase_1', '\\#pcontrast3 Talon: < \\#pcontrast1 Initial reports indicate this is the work of a flight of Canyon Corsair. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 2, 'arrival_phase_2', '\\#pcontrast3 Talon: < \\#pcontrast1  We have located the ones responsible, take them down! \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 3, 'assassinate_success', '\\#pcontrast3 Talon: < \\#pcontrast1 Good work, that will teach them to interfere with the alliance.'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 8, 'destroy_escort', '\\#pcontrast3 Talon: < \\#pcontrast1 Nice shooting on that Behemoth.  Now finish off his escort, we need to send a message. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 9, 'escort_remaining', '\\#pcontrast3 Tactical Computer: \\#pcontrast1 An escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 10, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 11, 'failed_escape', 'You let him get away, this is unacceptable.'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 12, 'quest_escort_d', 'A dangerous escort, destroy these to protect the cargo.'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 13, 'quest_escort_t', 'Corsair Man O''war'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 14, 'quest_location_d', 'Corsair Lane in the Lok System'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 15, 'quest_location_t', 'Lok System'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 16, 'quest_target_d', 'This craft has the cargo, you must destroy them before they can Hyperspace Jump away'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 17, 'quest_target_t', 'Corsair Behemoth'),
('string/en/spacequest/assassinate/tat_priv_quest_trans.stf', 18, 'quest_update', '\\#pcontrast3 < \\#pcontrast1 %TO \\#pcontrast3 >'),
