INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 10, 'docking_complete_delivery', 'We have the information. Wait for us to exit the area before you leave.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 11, 'docking_complete_pickup', 'The information is all yours. Take good care of it for us.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 12, 'docking_started_delivery', 'Steady. Docking procedure beginning.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 13, 'docking_started_pickup', 'Steady. Docking procedure beginning.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 14, 'failed_destroyed', 'One of the delivery ships was destroyed! You had a duty to protect Imperial property. Report back to your superior immediately.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 15, 'found_loc_d', 'Delivery location has been loaded to your nav computer. Proceed as planned.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 16, 'found_loc_p', 'Pickup location has been loaded to your nav computer. Proceed as planned.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 17, 'hello_d', 'Good to see you made it. We will have the information off of you shortly.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 18, 'hello_p', 'They only sent you? You better be good, this information is highly classified.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 19, 'quest_dock1_d', 'Once the vessel arrives, use the /dock command with the shuttle. The Inquisition needs these documents to compare them against the doctor''s statements.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 20, 'quest_dock1_t', 'Pickup the Documents'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 21, 'quest_dock2_d', 'Once the vessel arrives, use the /dock command with the shuttle.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 22, 'quest_dock2_t', 'Drop Off the Documents'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 23, 'quest_location_d', 'Remain in the Yavin system and wait to receive the navigation waypoint to the location of the delivery vessel.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 24, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 25, 'quest_rendezvous1_d', 'Travel to the arrival location of the shuttle that will deliver the orders.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 26, 'quest_rendezvous1_t', 'Meet the Delivery Shuttle'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 27, 'quest_rendezvous2_d', 'Travel to the arrival location of the pickup shuttle to drop off the orders.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 28, 'quest_rendezvous2_t', 'Meet the Pickup Shuttle'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 29, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 30, 'split_quest_alert', 'Pilot, proceed immediately to the Dathomir system. Doctor Shinss has returned early from his business in Endor and has been tipped off to the investigation. He fled rather then face the questions. Bring him back to us alive. He must be questioned.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 32, 'title', 'Yavin System: Transport the Documents'),
('string/en/spacequest/delivery/naboo_imperial_tier3_2_b.stf', 33, 'title_d', 'Travel to the Yavin system, pickup, and deliver the documents needed by the Inquisition. Once you arrive in the Yavin system, you will receive a navigation waypoint to the delivery shuttle. Travel to this location and wait for it to arrive. Once it arrives, target it and use the /dock command to transfer the documents to your ship. Then you will receive a second navigation waypoint to the pickup vessel. Travel to this location and wait for the arrival of the shuttle. Target and use the /dock command to transfer the documents to this new shuttle.'),
