('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 19, 'quest_dock1_d', 'Dock with the delivery vessel and pick up the fake list.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 20, 'quest_dock1_t', 'Pick Up the Fake List'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 21, 'quest_dock2_d', 'Dock with the pickup vessel.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 22, 'quest_dock2_t', 'Drop Off the Fake List'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 23, 'quest_location_d', 'The doctor mentioned the Dathomir system too often. We believe that is the best place to move the fake list through.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 24, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 25, 'quest_rendezvous1_d', 'A delivery vessel will meet you in the Dathomir system. Meet the vessel at its arrival location.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 26, 'quest_rendezvous1_t', 'Meet the Delivery Shuttle'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 27, 'quest_rendezvous2_d', 'Travel with the list through the Dathomir system and meet up with a tranfer vessel. We believe that you will be attacked by the Doctor''s allies in an attempt to keep this list out of the hands of the Dathomir security forces.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 28, 'quest_rendezvous2_t', 'Meet the Pickup Shuttle'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 29, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 30, 'split_quest_alert', 'That got the Rebel''s attention. Keep on the alert, there are probably more fighters out there.'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 32, 'title', 'Space Dathomir: Delivering a Fake List'),
('string/en/spacequest/delivery/naboo_imperial_tier3_3.stf', 33, 'title_d', 'The doctor has refused to give up any information on his fellow conspirators. Command has decided to leak a fake list of names in order to try to bring out any of his allies. You will transport this list in the Dathomir system where we believe that the doctor''s friends are located. The hope is that the fake list will cause the traitors to try to eliminate you.'),
