('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 9, 'docking_complete_delivery', 'All right, this is what we needed.  Now get out of here, you seem to attract Rebels.'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 10, 'docking_complete_pickup', 'That is all of it.  We have an Imperial transport waiting for you across the zone, I''ll upload their location to you.  Good luck.'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 11, 'docking_started_delivery', 'Get this transfer done quickly, we can''t staty stationary for long.'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 12, 'docking_started_pickup', 'We are transfering over some encrypted material.  This sensitive information, expect some Rebel interference.  Most will come after me, but you will not have an easy run. \\#pcontrast3 >'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 13, 'failed_destroyed', 'You have failed the delivery.'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 14, 'found_loc_d', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Rendezvous location locked in. \\#pcontrast3 >'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 15, 'found_loc_p', '\\#pcontrast3 RSF Command: < \\#pcontrast1 I''m sending you to the Imperial Freighter, they will finish instructions there. \\#pcontrast3 >'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 16, 'hello_d', 'Do not delay, Rebel attack is eminent.'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 17, 'hello_p', 'Hail Captain, close in for docking.'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 18, 'quest_dock1_d', 'Pull up close to the Freighter and use the /dock command to pick up the cargo'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 19, 'quest_dock1_t', 'Dock'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 20, 'quest_dock2_d', 'Pull up near the transport and use the /dock command to deliver the cargo'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 21, 'quest_dock2_t', 'Dock'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 22, 'quest_location_d', 'Somewhere in the Yavin System'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 23, 'quest_location_t', 'Yavin System'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 24, 'quest_rendezvous1_d', 'Your first contact'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 25, 'quest_rendezvous1_t', 'Imperial Heavy Freighter'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 26, 'quest_rendezvous2_d', 'Your second contact'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 27, 'quest_rendezvous2_t', 'Imperial Transport'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 28, 'quest_update', '\\#pcontrast3 < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 29, 'split_quest_alert', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Head out on a quick patrol, seperation from the Transport will help to confuse the Rebels. \\#pcontrast3 >'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 30, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 31, 'title', 'Yavin System: Deliver Imperial Goods'),
('string/en/spacequest/delivery/naboo_privateer_tier4_3a.stf', 32, 'title_d', 'Be the middle man for an Imperial exchange'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 2, 'arrived_at_delivery', 'One of our gunboats will come pick up the unconscious pilot. Stand by.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 3, 'arrived_at_pickup', 'The crew on the freighter have subdued the pilot of the experimental fighter and packed him up. Dock with them so they can transfer him to your ship.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 10, 'docking_complete_delivery', 'The transfer was successful. We''re out of here. You should return to Ezkiel pilot.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 11, 'docking_complete_pickup', 'Alright. We''ve loaded the pilot in to your cargo hold. Returning to Corellia.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 12, 'docking_started_delivery', 'We''re docking now. Stand by for immediate transfer of the experimental model.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 13, 'docking_started_pickup', 'Good to see you pilot. We would deliver the pilot ourselves if this was anywhere but the Dathomir system. Travelling around here with an unarmed freighter is asking for trouble.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 14, 'failed_destroyed', 'Nooo! We needed that body pilot! Return to base immediately!'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 15, 'found_loc_d', 'Alright, pilot. You need to deliver the "cargo" to this spot. We''re with you, pilot.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 16, 'found_loc_p', 'The freighter with the captured ship will meet you at this point, pilot. You''ll proceed to dock with them and pickup our information.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 17, 'hello_d', 'We''ll be docking with you soon. Stand by.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 18, 'hello_p', 'Glad to see you, pilot. Stand by for docking.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 19, 'quest_dock1_d', 'Dock with the freighter and transfer the ''pilot'' to your cargo hold. He''s sealed in a life support system and should be fine.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 20, 'quest_dock1_t', 'Dock and transfer unconsious pilot.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 21, 'quest_dock2_d', 'If the surrounding area is clear of enemies, dock and transfer the pilot to our gunboat.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 22, 'quest_dock2_t', 'Transfer pilot.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 23, 'quest_location_d', 'We''ve picked areas of the Dathomir system that should be light on enemy presence but the Empire is looking for you so right now, nothing is safe.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 24, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 25, 'quest_rendezvous1_d', 'Meet up with our freighter at these coordinates.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 26, 'quest_rendezvous1_t', 'Meet with Rebel freighter.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 27, 'quest_rendezvous2_d', 'We have sent one of our heavily guarded gunboats to this area, deliver the pilot to them immediately.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 28, 'quest_rendezvous2_t', 'Rendez-vous with Rebel gunboat.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 29, 'quest_update', 'Vortex Command: < %TO >'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 30, 'split_quest_alert', ''),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 32, 'title', 'Dathomir system: Help transfer experimental pilot.'),
('string/en/spacequest/delivery/naboo_rebel_tier3_4_d.stf', 33, 'title_d', 'Our freighter with the ship is heading for Corellia where it can be examined closely. We want to have a look at the pilot right away though and need your assistance in moving it from the freighter to one of our gunboats in the Dathomir system.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 1, 'arrived_at_delivery', 'I ran into some Valarians along the way, too. I''ll be there in a moment.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 2, 'arrived_at_pickup', 'You''re going to wait here for one of Jabba''s men to give you the attack codes. Then, you''ll bring them back to me. Hopefully, the Valarians won''t attack you again. Be careful.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 9, 'docking_complete_delivery', 'Thank you. You''ve been a great help to our goals.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 10, 'docking_complete_pickup', 'There ye be, kiddo. Now, get this ''ere attack codes back ta Garett safely. Ye watch out fer ''em Valarian''s. They be bad fer business.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 11, 'docking_started_delivery', 'Beginning docking proceedures to procure the attack codes from you.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 12, 'docking_started_pickup', 'Quit yer movin'' around fer a sec. Let me dock wit'' ya so''s I can give the attack codes teh ye.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 13, 'failed_destroyed', 'Pilot! The Hutt Informant was destroyed! You failed to protect him!'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 14, 'found_loc_d', 'I''ll be here, waiting for you. Like I mentioned before, be on the lookout.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 15, 'found_loc_p', 'One of Jabba''s spies will meet you here and give you the attack codes. Be on the lookout for Valarian influence. They knew what we were up to last time, somehow.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 16, 'hello_d', 'I''m glad to see you made it here in one piece. Let''s get this transfer underway.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 17, 'hello_p', '''ey. HAH! Ye call that a ship?! Oh, sorry. Let us be continuin'' this, eh?'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 18, 'quest_dock1_d', 'Once the lackey has been found, you''ll need to dock with it using the /dock command to transfer the attack codes.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 19, 'quest_dock1_t', 'The Transfer'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 20, 'quest_dock2_d', 'To dock with Garett''s ship, you''ll need to use the /dock command. You better be careful, though. You''ve heard, in passing, what happened to the last guy who scratched up Garett''s ship. Space dust, baby.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 21, 'quest_dock2_t', 'Time for the Transfer'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 22, 'quest_location_d', 'Once you have the attack codes from Jabba''s Star, you''ll need to hightail it over to the updated objective point where you''ll meet Garett.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 23, 'quest_location_t', 'Travel from Jabba''s Star to Objective'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 24, 'quest_rendezvous1_d', 'You''ve been ordered to pick up the attack codes from one of Jabba''s lackeys. Go there and get it, tiger.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 25, 'quest_rendezvous1_t', 'Jabba''s Spy'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 26, 'quest_rendezvous2_d', 'You''ll need to find Garett and transfer the attack codes. No doubt, at this point, you''ve discovered Valarian thugs on your tail, and fought them off without a hitch. Looks like you''re going to need some repairs, no? To dock with Garett''s ship, use the /dock command.'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 27, 'quest_rendezvous2_t', 'Find Garett and Transfer the Codes'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 28, 'quest_update', '\\#pcontrast1 Garett:\\#pcontrast3 <%TO>'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 29, 'split_quest_alert', ''),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 30, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 31, 'title', 'Tatoo System: Pick up and Delivery of the Attack Codes'),
('string/en/spacequest/delivery/poi_tatooine_privateer_1_a.stf', 32, 'title_d', 'At this point, you''re hanging out at Jabba''s Star, waiting for one of the thugs to use you as target practice while you wait for further instructions. Finally! You''ve been told to pick up the attack codes from one of Jabba''s "trustees" and then deliver them to Garett. Hopefully, you''ll get there in one piece. The Valarians have been hunting you ever since you got in contact with Garett. Hm... You begin to wonder if there''s a link.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 1, 'arrived_at_delivery', 'Stay here until the pick-up ship arrives.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 2, 'arrived_at_pickup', 'Stay here until the drop-off ship arrives.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 4, 'attack_notify', 'Tactical Computer: < Warning. Attack craft incoming. Imperial signatures detected. >'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 5, 'attack_stopped', 'Tactical Computer: < Attack craft neutralized. >'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 6, 'autorewardbody', 'You have been paid 2000 credits for services rendered to the Talus Space Station.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 7, 'autorewardfrom', 'Talus Station Command: Dept. 4S'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 8, 'autorewardsubject', 'Compensation for Services Rendered'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 9, 'docking_complete_delivery', 'Smooth as silk. Good luck to you!'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 10, 'docking_complete_pickup', 'Docking clamps are clear. Now shoo!'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 11, 'docking_started_delivery', 'Our team is standing by to receive the package.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 12, 'docking_started_pickup', 'Clamps open and ready for dock. Package ready for transfer.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 13, 'failed_destroyed', 'That didn''t work exactly the way that we planned. We''re scrapping the rest of your assignments. Return to the station if you want to try again.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 14, 'found_loc_d', 'Good work, pilot. Now proceed to this navigation waypoint and deliver the package.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 15, 'found_loc_p', 'Good morning, pilot. I''ve been assigned to monitor your progress today. We''ve got a short series of jobs for you. Begin by flying to this waypoint and meet your first pickup.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 16, 'hello_d', 'We''re ready to receive the package whenever you are, pilot.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 17, 'hello_p', 'Hello, pilot. Are you here to pick up the package? Dock whenever you''re ready.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 18, 'quest_dock1_d', 'Move in close to the drop-off ship and use the /dock command to dock and receive the cargo.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 19, 'quest_dock1_t', 'Dock with the Drop-off Ship'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 20, 'quest_dock2_d', 'Move in close to the pick-up ship and use the /dock command to dock and transfer the cargo.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 21, 'quest_dock2_t', 'Dock with the Pick-up Ship'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 22, 'quest_location_d', 'This assignment takes place in the Corellia system.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 23, 'quest_location_t', 'Remain in the Corellia System'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 24, 'quest_rendezvous1_d', 'Travel to the specified location and await the arrival of the drop-off ship.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 25, 'quest_rendezvous1_t', 'Meet With the Drop-off Ship'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 26, 'quest_rendezvous2_d', 'Travel to the specified location and await the arrival of the pick-up ship.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 27, 'quest_rendezvous2_t', 'Meet With the Pick-up Ship'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 28, 'quest_update', 'Talus Station: < %TO >'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 29, 'split_quest_alert', 'Stand by for next assignment.'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 30, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 31, 'title', 'Corellia System: Smuggle a Package'),
('string/en/spacequest/delivery/talus_station_mission1_1.stf', 32, 'title_d', 'You have been assigned a simple smuggling mission. You need only pick up the cargo from one ship and deliver it to another ship in the same system.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 1, 'arrived_at_delivery', 'Stay here until the pick-up ship arrives.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 2, 'arrived_at_pickup', 'Stay here until the drop-off ship arrives.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 4, 'attack_notify', 'Tactical Computer: < Warning. Attack craft incoming. Pirate signatures detected. >'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 5, 'attack_stopped', 'Tactical Computer: < Attack craft neutralized. >'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 6, 'autorewardbody', 'You have been paid 3000 credits for services rendered to the Talus Space Station.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 7, 'autorewardfrom', 'Talus Station Command: Dept. 4S'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 8, 'autorewardsubject', 'Compensation for Services Rendered'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 9, 'docking_complete_delivery', 'Couldn''t go any better. Take care, pilot.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 10, 'docking_complete_pickup', 'You''re clear, pilot. Carry on.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 11, 'docking_started_delivery', 'Cargo bay is ready and waiting, pilot.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 12, 'docking_started_pickup', 'Standing by for docking sequence.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 13, 'failed_destroyed', 'That didn''t work exactly the way that we planned. We''re scrapping the rest of your assignments. Return to the station if you want to try again.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 14, 'found_loc_d', 'Good work, pilot. Now proceed to this navigation waypoint and deliver the package.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 15, 'found_loc_p', 'This should be another simple one. Fly to this navigation waypoint and pick up the cargo. It''s a pretty hot package, so be careful.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 16, 'hello_d', 'Good to see you. Standing by for drop off.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 17, 'hello_p', 'Greetings, pilot. We''re ready to trade.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 18, 'quest_dock1_d', 'Move in close to the drop-off ship and use the /dock command to dock and receive the cargo.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 19, 'quest_dock1_t', 'Dock With the Drop-off Ship'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 20, 'quest_dock2_d', 'Move in close to the pick-up ship and use the /dock command to dock and transfer the cargo.'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 21, 'quest_dock2_t', 'Dock With the Pick-up Ship'),
('string/en/spacequest/delivery/talus_station_mission1_2.stf', 22, 'quest_location_d', 'You will need to pick up the cargo in the Corellia system.'),
