('string/en/spacequest/delivery/talus_station_mission4_2.stf', 6, 'autorewardbody', 'You have been paid 5000 credits for services rendered to the Talus Space Station. That is all the assignments that we have for you at this time. Your assistance is greatly appreciated!'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 7, 'autorewardfrom', 'Talus Station Command: Dept. 4S'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 8, 'autorewardsubject', 'Compensation for Services Rendered'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 9, 'docking_complete_delivery', 'Clamps are clear, we have the package.'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 10, 'docking_complete_pickup', 'You''re all clear pilot. Good luck, and stay out of trouble.'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 11, 'docking_started_delivery', 'You are cleared for docking. Make it quick, pilot.'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 12, 'docking_started_pickup', 'Docking request received. Preparing to transfer package.'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 13, 'failed_destroyed', 'That didn''t work exactly the way that we planned. We''re scrapping the rest of your assignments. Return to the station if you want to try again.'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 14, 'found_loc_d', 'Should be smooth sailing now. We''re transmitting the location of the delivery. Meet your pick-up ship there.'),
('string/en/spacequest/delivery/talus_station_mission4_2.stf', 15, 'found_loc_p', 'Await the arrival of the transport at the specified location.'),
