INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/delivery/talus_station_mission5_1.stf', 31, 'title', 'Corellia System: Tusk Cat Run - Leg One'),
('string/en/spacequest/delivery/talus_station_mission5_1.stf', 32, 'title_d', 'The Tusk Cat Run is a series of small smuggling assignments using droid controlled delivery and attack drones.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 2, 'arrived_at_delivery', 'You have arrived at the delivery location. Please wait for the arrival of the command shuttle.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 3, 'arrived_at_pickup', 'You have arrived at the pickup location. Please wait for the arrival of the data shuttle.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 7, 'autorewardbody', ''),
