('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 10, 'docking_complete_delivery', 'Docking procedure complete. Please wait while we download the data.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 11, 'docking_complete_pickup', 'Docking procedure complete. Please wait while we upload the data.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 12, 'docking_started_delivery', 'Docking procedure beginning.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 13, 'docking_started_pickup', 'Docking procedure beginning.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 14, 'failed_destroyed', 'You let one of our ships be destroyed? That sort of puts a crimp in our plans. Report back to your superior.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 15, 'found_loc_d', 'Location of the delivery for the plan has been sent to your Nav computer. Proceed to this location and wait for the arrival of the shuttle.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 16, 'found_loc_p', 'Location of the pick-up for the plan has been sent to your Nav computer. Proceed to this location and wait for the arrival of the shuttle.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 17, 'hello_d', 'Greetings, pilot. Begin docking procedure whenever you are ready.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 18, 'hello_p', 'Greetings, pilot. Begin docking procedure whenever you are ready.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 19, 'quest_dock1_d', 'Once the vessel arrives, use the /dock command with the shuttle. Do not let these orders fall into enemy hands or the whole plan is ruined.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 20, 'quest_dock1_t', 'Pickup the Orders'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 21, 'quest_dock2_d', 'Once the vessel arrives, use the /dock command with the shuttle.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 22, 'quest_dock2_t', 'Drop Off the Orders'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 23, 'quest_location_d', 'Travel to the Endor system and wait to receive the navigation waypoint to the location of the delivery vessel.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 24, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 25, 'quest_rendezvous1_d', 'Travel to the arrival location of the shuttle that will deliver the orders.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 26, 'quest_rendezvous1_t', 'Meet the Delivery Shuttle'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 27, 'quest_rendezvous2_d', 'Travel to the arrival location of the pickup shuttle to drop off the orders.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 28, 'quest_rendezvous2_t', 'Meet the Pickup Shuttle'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 29, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 30, 'split_quest_alert', 'Very interesting plan. Ok, we are going to start putting together the expendable ship. While you are waiting for us to get the ship ready, begin harassing Rebel fighters to make it look like we are going on the offensive. This will help sell the plan. Seek and destroy Rebel fighters until we contact you again.'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 32, 'title', 'Endor System: Delivering a New Plan'),
('string/en/spacequest/delivery/tatooine_imperial_tier3_3.stf', 33, 'title_d', 'Travel to the Endor system, pickup, and deliver the plan to draw the Rebels out of hiding. Once you arrive in the Endor system, you will receive a navigation waypoint to the delivery shuttle. Travel to this location and wait for it to arrive. Once it arrives, target it and use the /dock command to transfer the plans to your ship. Then you will receive a second navigation waypoint to the pickup vessel. Travel to this location and wait for the arrival of the shuttle. Target and use the /dock command to transfer the plans to this new shuttle.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 2, 'arrived_at_delivery', 'Stand by for the field engineer ship''s arrival.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 3, 'arrived_at_pickup', 'Stand by for the delivery of the satellites.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer: \\#pcontrast3 <Enemy fighters detected.> \\#pcontrast3'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer: \\#pcontrast3 <Enemy fighters eliminated.> \\#pcontrast3'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 7, 'autorewardbody', ''),
