('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 10, 'docking_complete_delivery', 'Ok, we have the satellite. Good luck, pilot.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 11, 'docking_complete_pickup', 'The sattelites are on board. Deliver them out to the field engineers.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 12, 'docking_started_delivery', 'Docking procedure underway. Stand by.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 13, 'docking_started_pickup', 'Docking procedure underway. Stand by.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 14, 'failed_destroyed', 'The field engineer''s ship was destroy! This is unacceptable. Report your failure to your commander.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 15, 'found_loc_d', 'Delivery location sent to your nav computer. Bring the satellite to the field engineer in that region.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 16, 'found_loc_p', 'Proceed to the location provided to your nav computer to pick up the satellites.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 17, 'hello_d', 'There you are. I have been waiting for that satellite for a while now. Lets begin docking and transfer that satellite to me.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 18, 'hello_p', 'I have the satellites you need to take to the field engineers. Lets dock and get this over with.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 19, 'quest_dock1_d', 'Dock with the delivery vessel and pickup the satellites.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 20, 'quest_dock1_t', 'Pickup the Satellites'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 21, 'quest_dock2_d', 'Dock with the engineer and transfer the first satellite to his ship.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 22, 'quest_dock2_t', 'Dropoff the First Satellite'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 23, 'quest_location_d', 'Remain in the Endor system and pickup the two satellites from the Imperial freighter.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 24, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 25, 'quest_rendezvous1_d', 'Travel to the arrival location of the delivery vessel and wait for it to arrive.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 26, 'quest_rendezvous1_t', 'Travel to the Delivery Vessel'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 27, 'quest_rendezvous2_d', 'Travel to the arrival location of the first engineer and wait for him to arrive.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 28, 'quest_rendezvous2_t', 'Travel to the First Engineer'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 29, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 30, 'split_quest_alert', 'Bring the remaining satellite to the other field engineer.'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 32, 'title', 'Endor System: Satellite Delivery'),
('string/en/spacequest/delivery/tatooine_imperial_tier4_2_b.stf', 33, 'title_d', 'Remain in the Endor system, pickup, and delivery satellites to the engineers. Even though several other shuttles managed to get away, command cannot worry about those right now. The detection satellites that ring the system were taken offline, which is how the Bothans managed to avoid detection and capture the vessels. Those satellites need to be replaced immediately. Pickup two satellites and deliver them to the engineers who will put them back into place.'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 1, 'arrived_at_delivery', 'Our transport should be here any moment...'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 2, 'arrived_at_pickup', 'Your delivery target (the Seinar Systems contractor) should be here very soon...'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 4, 'attack_notify', 'Enemy craft detected on attack vector.'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 5, 'attack_stopped', 'The attack has been stopped.'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 9, 'docking_complete_delivery', 'Ah! Many thanks to Jabba and his fine pilots. Please relay that Seinar Systems would enjoy a much deeper relationship with the Hutts...'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 10, 'docking_complete_pickup', 'All right! All the spice brandy is transferred. Knock yourself out, buddy.'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 11, 'docking_started_delivery', 'Starting automatic docking procedure now.'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 12, 'docking_started_pickup', 'Hey there. Hope the Seinar Systems big-wig likes spice brandy!'),
('string/en/spacequest/delivery/tatooine_privateer_tier3_3.stf', 13, 'failed_destroyed', 'You have failed.'),
