('string/en/spacequest/delivery/tatooine_rebel_tier3_1_a.stf', 24, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/delivery/tatooine_rebel_tier3_1_a.stf', 25, 'quest_rendezvous1_d', 'The infiltration team will be in a stolen Lambda shuttle. They are going to put those codes to good use on the surface of Dathomir.'),
('string/en/spacequest/delivery/tatooine_rebel_tier3_1_a.stf', 26, 'quest_rendezvous1_t', 'Deliver codes to infiltration team.'),
('string/en/spacequest/delivery/tatooine_rebel_tier3_1_a.stf', 27, 'quest_rendezvous2_d', 'One of our command ships will meet you here. Although the Empire will probably change these codes quickly, we will see if we can''t get some more use out of them.'),
