('string/en/spacequest/delivery_no_pickup/naboo_privateer_tier3_3b.stf', 20, 'split_quest_alert', '\\#pcontrast3 RSF Command: < \\#pcontrast1 I hate to throw you to the Swamp Stalkers here Captain but we are about to do just that.  There is a vulnerability in the Black Sun communications net we want to exploit but it is in Black Sun controlled area.  You will be a major target. \\#pcontrast3 >'),
('string/en/spacequest/delivery_no_pickup/naboo_privateer_tier3_3b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/naboo_privateer_tier3_3b.stf', 22, 'title', 'Lok System: Deliver Encrypted Documents to the RSF Contact'),
('string/en/spacequest/delivery_no_pickup/naboo_privateer_tier3_3b.stf', 23, 'title_d', 'You must deliver the encrypted documents to a RSF contact in the Lok System.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 2, 'arrived_at_delivery', 'Our Rebel Contact should be here soon. Keep an eye out for enemies, pilot. We can''t lose you now.'),
