('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 9, 'docking_complete_delivery', 'You''re ready to go, pilot. We''ve received the goods.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 10, 'docking_started_delivery', 'Watch the hull, buddy! I just cleaned that!'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 11, 'failed_destroyed', 'Ack, we''ve lost contact with our freighter! Return to base immediately pilot!'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 12, 'found_loc_d', 'We''ve given you the point at which our Rebel contact will meet you. You''ll deliver the information to him by docking. Good luck.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 13, 'hello_d', 'Greetings, pilot. H-21D here to help you out with a delivery.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 14, 'quest_dock2_d', 'If you are certain that the surrounding area is clear of the Imperial scum, dock with the freighter to transfer the data.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 15, 'quest_dock2_t', 'Dock with the freighter.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 16, 'quest_location_d', 'The Dantooine system is now relatively safe but if the information you recovered from the spies ship was valuable, the Empire might try and stop you so be ready for surprises.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 17, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 18, 'quest_rendezvous2_d', 'You should now have the coordinates that the freighter supplied us with for the rendez-vous. Make your way there with haste.'),
