('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier3_1_d.stf', 24, 'title_d', 'Deliver the data stolen from the spy''s ship to one of our data freighters.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 2, 'arrived_at_delivery', 'You are at the correct location pilot, the smuggler should be there any second.'),
