('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 9, 'docking_complete_delivery', 'Alright I got it and I''m out of here, be safe!'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 10, 'docking_started_delivery', 'Lets do this quickly, I don''t like the look of all those laser burns on your ship.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 11, 'failed_destroyed', 'That poor smuggler just tried to help. Return to base immediately pilot, we need to talk.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 12, 'found_loc_d', 'Lets make sure our operative didn''t die in vain. Deliver the data he transferred to our smuggler at these coordinates.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 13, 'hello_d', 'Greetings, you got a package for me I''m told.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 14, 'quest_dock2_d', 'Make sure that you have eliminated nearby Imperial threats before starting the docking sequence as both you and the smuggler will be very vulnerable while transferring the data.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 15, 'quest_dock2_t', 'Dock and transfer data.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 16, 'quest_location_d', 'You will be doing a data run through extremely dangerous areas and we know that the Empire is looking for you so I hope you came prepared for a fight my friend.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 17, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 18, 'quest_rendezvous2_d', 'The smuggler provided us with these coordinates. Try to avoid leading Imperial forces to this area if you can.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 19, 'quest_rendezvous2_t', 'Smuggler coordinates.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 20, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 23, 'title', 'Dathomir system: Deliver the Vortex operatives data.'),
('string/en/spacequest/delivery_no_pickup/naboo_rebel_tier4_3_b.stf', 24, 'title_d', 'Our spy didn''t die in vain, he managed to transfer most of his important data to your ship before his unfortunate end. Bring it to one of our smugglers immediately.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 1, 'arrived_at_delivery', 'Hold your position pilot, we are sending over a TIE to scan your ship.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 8, 'docking_complete_delivery', 'Rebels that have uncovered our freighter routes you say? I would have said you''re crazy, but those Rebels attacking you on your way here does confirm that something is going on. Stand by.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 9, 'docking_started_delivery', 'Everything looks to be in order and his ship is clear of contraband commander. Now, why are you here?'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 10, 'failed_destroyed', 'We have enough problems here as it is and don''t need you to lead Rebel scum to our operations. Get out of here!'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 11, 'found_loc_d', 'This is the security commander of the Yavin system Imperial station. Continue to these coordinates immediately and prepare to identify yourself.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 12, 'hello_d', 'Pilot, shut down your weapon systems and dock with me for identity confirmation and scan.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 13, 'quest_dock2_d', 'You need to dock with the TIE Interceptor so he can confirm your identity and scan your ship for anything dangerous or illegal.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 14, 'quest_dock2_t', 'Security scan.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 15, 'quest_location_d', 'The Yavin system is heavily guarded by Imperial forces but there''s still a rogue presence with unscrupulous bounty hunters, pirates and mercenaries so don''t feel too safe.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 16, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 17, 'quest_rendezvous2_d', 'The security commander of the Yavin Imperial space station has ordered you to fly to these coordinates immediately.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 18, 'quest_rendezvous2_t', 'Security meeting coordinates.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 19, 'quest_update', 'Imperial Space Station: < %TO >');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 20, 'split_quest_alert', 'Imperial Space Station: < This couldn''t have come at a worse time since we are terminating pirates in another sector of the debris field. Although you''re not under my command, I''d appreciate if you flew out to where the freighter was attacked and recon the area. >'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 22, 'title', 'Yavin system: Delivering the bad news.'),
('string/en/spacequest/delivery_no_pickup/naboo_station_emperors_access_quest_2.stf', 23, 'title_d', 'The crew of the freighter you rescued in the Naboo system asked you to deliver their suspicions that the Rebels uncovered the Imperial freighter route in the Yavin system and are planning an attack.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 1, 'arrived_at_delivery', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < One of Jabba''s men will be there soon. Keep an eye out and don''t make any sudden moves. They''re quick to fire at unknown vessels. >'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 3, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 4, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 8, 'docking_complete_delivery', 'Secret codes, eh? Let me see these. Hm. Well... they don''t look counterfeit. I guess I can clear these. I''ll notify my superiors. You''ll receive more instructions soon.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 9, 'docking_started_delivery', 'Beginning docking procedures to receive secret codes. Stand by.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 10, 'failed_destroyed', 'Pilot! The Hutt Informant has been destroyed! Mission Failed!'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 11, 'found_loc_d', 'One of Jabba''s men will meet you there to receive and look over the secret codes. We will then be given further instructions.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 12, 'hello_d', '''ey! I was notified that you have ''secret codes''. No funny business now. We''re watching you.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 13, 'quest_dock2_d', 'Jabba''s spy will want those secret codes pretty quickly. You begin to wonder if they''re fake.. what would happen then? What if this is a set up? You tell yourself you probably shouldn''t worry about such things, but decide to keep your weapon systems alert. Just in case. When the spy finally gets to the location, use /dock to transfer the orders. And be quick about it. Hutts like to shoot things.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 14, 'quest_dock2_t', 'Transfer Secret Codes'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 15, 'quest_location_d', 'To succeed in your task, you must take the secret codes from Garett Erlskel in Hutt Claims to one of Jabba''s men in Jabba''s Star. You can find locations to both places in your nifty little datapad, under the POI tab.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 16, 'quest_location_t', 'Travel from Hutt Claims to Jabba''s Star'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 17, 'quest_rendezvous2_d', 'Plan to wait at the waypoint you''re given for Jabba''s spy. He''s probably just finishing his lunch or just getting up from taking a nap. Be patient.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 18, 'quest_rendezvous2_t', 'Wait for Jabba''s Spy'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 19, 'quest_update', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 <%TO>'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 20, 'split_quest_alert', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < Looks like they accepted the secret codes. Now, it''s time to pick up the attack orders and bring them back to Hutt Claims. >'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 22, 'title', 'Tatoo System: Deliver Secret Code to Jabba''s Star'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_1.stf', 23, 'title_d', 'The Hutt Informant you found at Hutt Claims, Garett Erlskel, has instructed you to deliver ''secret codes'' to Jabba''s men at the Hutt''s origin of control in the Tatoo System, Jabba''s Star. You might as well keep your weapon systems alert. No doubt the Valarians, hated enemies of the Hutts, have stumbled onto the details of the pending attacks ahead. You figure you can find Jabba''s Star by looking in your nifty little datapad under the nicely-catagorized POI tab.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 1, 'arrived_at_delivery', 'Good. I will appear soon. I must make sure the Valarians aren''t tracking us.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 3, 'attack_notify', 'blah'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 4, 'attack_stopped', 'blah'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 8, 'docking_complete_delivery', 'Thank you, pilot. I must analyze this and pass it on to my superiors. We''ll have an attack plan soon. I hope you''ll join us.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 9, 'docking_started_delivery', 'Beginning docking proceedures..'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 10, 'failed_destroyed', 'Pilot! Our cause is lost!'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 11, 'found_loc_d', 'A target location has been given to you. Go here and I''ll meet you. Stay alert. There could be Valarians on our tail.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 12, 'hello_d', 'All right, pilot. Let''s transfer the information you found off the Valarians.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 13, 'quest_dock2_d', 'Dock with Garett by using the /dock command to transfer the information you found off the Valarians.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 14, 'quest_dock2_t', 'Dock with Garett'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 15, 'quest_location_d', 'Travel to the Tatoo System to meet Garett.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 16, 'quest_location_t', 'Tatoo System'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 17, 'quest_rendezvous2_d', 'At this point, you''ll need to find Garett. You assume he''ll be at the "usual" place.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 18, 'quest_rendezvous2_t', 'Find Garett'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 19, 'quest_update', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < %TO >'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 22, 'title', 'Tatoo System: Transfer the Information to Garett'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_2_c.stf', 23, 'title_d', 'After smoking some Valarians, you''ve been ordered to transfer the information directly to Garett. You''re beginning to wonder what you''re going to get out of this. It had better be good. You''ve got components to buy.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 1, 'arrived_at_delivery', 'It pleases me that you made it to Jabba''s Star safely. Our contact will arrive soon.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 3, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 4, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 8, 'docking_complete_delivery', 'Yeh done good, pilot. There may be room in our ranks fer folks like yeh. Carry on.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 9, 'docking_started_delivery', 'Let''s git this here notice of yeh. We don''t want Valari''ns gettin'' yeh anymore.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 10, 'failed_destroyed', 'Pilot! You''ve failed us!'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 11, 'found_loc_d', 'I''m sending you the location at which you''ll meet our contact. You need to transfer the notice once you get there and after the contact arrives.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 12, 'hello_d', 'Let''s git this over wit''. I can feel Valari''ns close.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 13, 'quest_dock2_d', 'To dock with the contact, use the /dock command.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 14, 'quest_dock2_t', 'Docking with the contact'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 15, 'quest_location_d', 'Travel to the Tatoo System and complete your mission.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 16, 'quest_location_t', 'Tatoo System'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 17, 'quest_rendezvous2_d', 'At Jabba''s Star, easily found in the datapad under the POI tab, you''ll need to meet with the designated contact and transfer the attack notice.'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 18, 'quest_rendezvous2_t', 'Meet with contact at Jabba''s Star'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 19, 'quest_update', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < %TO >'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 20, 'split_quest_alert', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < So far so good. I''ve been informed that our war vessels are ready. Escort the commander safely to the waypoint I''ve given you. We''ll get this attack underway with his help. >'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 22, 'title', 'Tatoo System: Transfer the Notice'),
('string/en/spacequest/delivery_no_pickup/poi_tatooine_privateer_3.stf', 23, 'title_d', 'You''ve been given orders from Garett to deliver a notice, explaining to the contacts at Jabba''s Star that an attack is imminent and that you need their support.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 1, 'arrived_at_delivery', 'Stand by. The shipping company said they would meet us here.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 3, 'attack_notify', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 4, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 8, 'docking_complete_delivery', 'Ok, you have the goods Dantooine ordered. We are out of here.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 9, 'docking_started_delivery', 'Transferring cargo to your vessel. Make sure that Dantooine gets that shipment.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 10, 'failed_destroyed', 'How could you do that? They are never going to help us again.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 11, 'found_loc_d', 'Sending you the location of where we are supposed to meet the shipping company.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 12, 'hello_d', 'Go ahead and dock whenever you are ready. We have the cargo.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 13, 'quest_dock2_d', 'Dock with the freighter and pick up the cargo. Then bring it back to the Dantooine station.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 14, 'quest_dock2_t', 'Transfer the Cargo'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 15, 'quest_location_d', 'The meeting point is located in the Lok system.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 16, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 17, 'quest_rendezvous2_d', 'Meet the freighter at its arrival location.'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 18, 'quest_rendezvous2_t', 'Meet the Freighter'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 19, 'quest_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 22, 'title', 'Lok System: Pickup Cargo for the Dantooine Station'),
('string/en/spacequest/delivery_no_pickup/stan_dantooine_owner_all_lokdelivery_tier2_1.stf', 23, 'title_d', 'The Dantooine station has hired you to pick up a delivery that was ment for them in the Lok system.'),
('string/en/spacequest/delivery_no_pickup/stn_dantooine_owner_all_corelliapickup_tier2_1.stf', 1, 'arrived_at_delivery', 'Stand by. The shipping company said they would meet us here.'),
