('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_all_massassi_tier2_9.stf', 22, 'title', 'Yavin System: Investigate the Competing Mining Co. Shuttle'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_all_massassi_tier2_9.stf', 23, 'title_d', 'A vessel belonging to the Corellia Deep Mining Company has been spotted by your ship''s computers. That company has no operations in the Yavin system. Find out what they are doing here.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 1, 'arrived_at_delivery', 'Wait here for the arrival of the delivery ship. Keep a close watch out for the authorities. If they get wind of this we could all be in trouble.'),
