('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 16, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 17, 'quest_rendezvous2_d', 'Wait for the freighter to arrive at the assigned location.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 18, 'quest_rendezvous2_t', 'Meet the Delivery Freighter'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 19, 'quest_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 20, 'split_quest_alert', 'Travel to the Naboo system and follow the assigned route. Avoid detection by officials but if anyone tries to stop you, destroy them. Once you reach the end of the route, wait for the contact to arrive.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 22, 'title', 'Yavin System: Pick Up the Goods'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_1.stf', 23, 'title_d', 'The Yavin 4 Mining Company has hired you to pick up a mysterious package and deliver it to the Naboo system for them. The package is currently on one of their ships in the Yavin system where you are to pick it up.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 1, 'arrived_at_delivery', 'You have arrived at the drop off location. Stand by for the arrival of our contact.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 3, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters detected. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 4, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters eliminated. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 8, 'docking_complete_delivery', 'Thanks for the package. I will take it from here. You should go back and talk to our employers.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 9, 'docking_started_delivery', 'Ok, beginning transfer now. Everything looks to be in order.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 10, 'failed_destroyed', 'You let our contact be destroyed? Do you know how hard it is to find someone willing to work on Naboo?'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 11, 'found_loc_d', 'Our contact''s arrival location has been found. Travel to and wait at that location for him to arrive.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 12, 'hello_d', 'So you are the new pilot working for the company. Glad to meet you. Dock with me and let''s check out what you have.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 13, 'quest_dock2_d', 'Dock with the freighter and deliver the package to the contact. Once you have completed this, return to the Yavin station.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 14, 'quest_dock2_t', 'Deliver the Package'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 15, 'quest_location_d', 'Travel to the location given to your navigation computer.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 16, 'quest_location_t', 'Remain in the Naboo System'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 17, 'quest_rendezvous2_d', 'Wait for the freighter to arrive at the assigned location.'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 18, 'quest_rendezvous2_t', 'Meet the Freighter'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 19, 'quest_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 22, 'title', 'Naboo System: Making the Drop'),
('string/en/spacequest/delivery_no_pickup/stn_yavin4_company_smuggler_tier2_5.stf', 23, 'title_d', 'The Yavin 4 Mining Company''s contact has signaled you and sent the location of where you are to meet him. Your prior troubles with the CorSec are sure to draw more involvement so make the drop off quickly.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 1, 'arrived_at_delivery', 'Stay here until the pickup ship arrives.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 3, 'attack_notify', 'Tactical Computer: < Warning. Enemy craft inbound. Imperial signatures detected. >'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 4, 'attack_stopped', 'Tactical Computer: < Enemy threat neutralized. >'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 5, 'autorewardbody', 'You have been paid 4000 credits for services rendered to the Talus Space Station.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 6, 'autorewardfrom', 'Talus Station Command: Dept. 4S'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 7, 'autorewardsubject', 'Compensation for Services Rendered'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 8, 'docking_complete_delivery', 'Docking completed. Everything looks in order here. See you around.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 9, 'docking_started_delivery', 'Accepting your request for dock, pilot.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 10, 'failed_destroyed', 'That didn''t work exactly the way that we planned. We''re scrapping the rest of your assignments. Return to the station if you want to try again.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 11, 'found_loc_d', 'We''re transmitting the delivery location from the freighter to you. Meet the drop-off ship here and deliver the cargo.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 12, 'hello_d', 'Oh... what? We were expecting a Talus freighter. Oh well, if you''ve got the supplies go ahead and dock when ready.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 13, 'quest_dock2_d', 'Move in close to the pick-up ship and use the /dock command to transfer the cargo.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 14, 'quest_dock2_t', 'Dock With the Pick-up Ship'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 15, 'quest_location_d', 'Hyperspace to the Naboo system.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 16, 'quest_location_t', 'Tavel to the Naboo System'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 17, 'quest_rendezvous2_d', 'Travel to the specified location and await the arrival of the pick-up ship.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 18, 'quest_rendezvous2_t', 'Meet With the Pick-up Ship'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 19, 'quest_update', 'Talus Station: < %TO >'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 20, 'split_quest_alert', 'Stand by for next assignment.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 22, 'title', 'Naboo System: Deliver the Freighter Cargo'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission2_2.stf', 23, 'title_d', 'Since you are now carrying the freighter''s cargo, you must make the last delivery on it''s route to naboo.'),
('string/en/spacequest/delivery_no_pickup/talus_station_mission5_2.stf', 1, 'arrived_at_delivery', 'Await delivery drone here.');
