('string/en/spacequest/delivery_no_pickup/tatooine_imperial_tier4_2_c.stf', 12, 'found_loc_d', 'Delivery location sent to your nav computer. Bring the sattelite to the field engineer in that region.'),
('string/en/spacequest/delivery_no_pickup/tatooine_imperial_tier4_2_c.stf', 13, 'hello_d', 'Good day, pilot. Thanks for dropping these off to me. I will get them set up right away.'),
