('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 9, 'docking_complete_delivery', 'Alright, I''m taking this to a nearby command fleet. Take care out there!'),
('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 10, 'docking_started_delivery', 'Initiating docking. Lets do this fast, I don''t like this area.'),
('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 11, 'failed_destroyed', 'We lost contact with the smuggler! What happened up there pilot? Return to base immediately!'),
('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 12, 'found_loc_d', 'Move out of there quickly to this location pilot. We have arranged for a smuggler to meet you there.'),
('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 13, 'hello_d', 'Hi pilot, I was told you needed a express delivery.'),
('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 14, 'quest_dock2_d', 'If the surrounding area is safe, quickly dock with our smuggler and transfer the scan files.'),
('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 15, 'quest_dock2_t', 'Dock and transfer scan files.'),
