('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 17, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/delivery_no_pickup/tatooine_rebel_tier3_4_c.stf', 18, 'quest_rendezvous2_d', 'Our nearest smuggler has agreed to meet you at these coordinates, waste no time in getting there.'),
