('string/en/spacequest/destroy/corellia_imperial_17.stf', 11, 'title_d', ''),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 6, 'quest_destroy_d', 'Eliminate four X-Wing Cadets. Any more then that and we might start to lose any sympathy we gained.'),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 7, 'quest_destroy_t', 'Destroy Four X-wing Cadets'),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 8, 'quest_location_d', 'The training ground is located inside of Corellia space. Once you arrive in Corellian space start your search for the X-wing cadets. Imperial command has supplied you with several navigation waypoints that will lead you to areas of higher Rebel activity.'),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 9, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 10, 'split_quest_alert', 'You are not done with your job yet. Even with this setback, we still expect you to take out four of those X-wing Cadets.'),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 12, 'title', 'Corellia System: Seek and Destroy Four X-wing Cadets'),
('string/en/spacequest/destroy/corellia_imperial_2.stf', 13, 'title_d', 'Travel to the Corellia system, hunt down, and destroy four X-wing cadets. Since the Empire is unsure where the X-wing cadets are located in the Corellia system, you will receive a few navigation waypoints to suspected areas of Rebel activity. You can check out area around the waypoints to see if you can locate the Rebel cadets or just search the system yourself. Once you have located X-wing cadets, destroy four of them. When you complete this mission, return to Hakasha Sireen at the Imperial Base on Talus for your next assignment.'),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 6, 'quest_destroy_d', 'Once you have reached the testing area show the rebels that the Empire is not afraid of their new bomber. Destroy the ship. Once you are done return to your commanding officer.'),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 7, 'quest_destroy_t', 'Destroy the B-Wing Prototype'),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 8, 'quest_location_d', 'The B-Wing is being tested in the Corellian sector out past the local security buoys in order to avoid detection. Imperial Intelligence has been aware of this testing grounds since the project launched and has all the information they need from the prototype. Travel to the Nav locaiton supplied to you to reach the trainer grounds.'),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 9, 'quest_location_t', 'Travel to the Corellian Sector'),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 11, 'title', 'Destroy B-Wing Prototype'),
('string/en/spacequest/destroy/corellia_imperial_4.stf', 12, 'title_d', 'The rebels have been testing a new space craft in the Corellian sector. The Empire is well aware of the existance of this starfighter and wants to send a message to the rebels. You are to travel to the testing area for the B-Wing prototype and destroy the test ship.'),
