('string/en/spacequest/destroy/corellia_privateer_2.stf', 6, 'quest_destroy_d', 'Black Sun Pirates have been reported at or around these areas, destroy them if present.'),
('string/en/spacequest/destroy/corellia_privateer_2.stf', 7, 'quest_destroy_t', 'Areas of Black Sun Activity'),
('string/en/spacequest/destroy/corellia_privateer_2.stf', 8, 'quest_location_d', 'Search the provided system waypoints for concentrations of Black Sun activity.'),
('string/en/spacequest/destroy/corellia_privateer_2.stf', 9, 'quest_location_t', 'Corellia System'),
('string/en/spacequest/destroy/corellia_privateer_2.stf', 10, 'split_quest_alert', '\\#pcontrast3 Sgt Rhea: < \\#pcontrast1 You appear to have hit a little snag out there Captain.  Get patched up and hunt those Black Sun down. \\#pcontrast3 >'),
('string/en/spacequest/destroy/corellia_privateer_2.stf', 11, 'split_quest_alert_fail', '\\#pcontrast3 Sgt Rhea: < \\#pcontrast1 You appear to have hit a little snag out there Captain.  Get patched up and hunt those Black Sun down. \\#pcontrast3 >'),
('string/en/spacequest/destroy/corellia_privateer_2.stf', 12, 'title', 'Corellia System: Search for and Destroy Black Sun Pirates'),
('string/en/spacequest/destroy/corellia_privateer_2.stf', 13, 'title_d', 'Visit some of the provided waypoints and destroy any Black Sun presence you find there. When you complete this mission, return to Sergeant Rhea in Coronet for your next assignment.'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 6, 'quest_destroy_d', 'The Imperial TIE fighter is built to be cheap and reliable. It doesn''t have a shield system or heavy armor but it makes up for that in speed and agility. Lone TIE fighters are hard to come by, they usually travel in big packs to be more of a threat.'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 7, 'quest_destroy_t', 'TIE Fighter.'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 8, 'quest_location_d', 'The Corellia system is relatively safe for us. It''s considered neutral and have been left alone by the Empire for the most part. Lately they have been starting to take more and more liberties in the system though and we have to be careful not to draw too much attention or the Empire might move in full force.'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 9, 'quest_location_t', 'Corellia system.'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 10, 'split_quest_alert', 'Rebel Command: < Don''t let them defeat you pilot. Get back out there and show them that the Alliance fold for no one! >'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 12, 'title', 'Corellia system: Hunt the TIE Fighters.'),
('string/en/spacequest/destroy/corellia_rebel_2.stf', 13, 'title_d', 'Search the Corellia system for easy target TIE fighters and eliminate them. Eliminate four of them to succeed with your mission of sending a message to the Empire. When you complete this mission, return to Captain Kreezo in Tyrena for your next assignment.'),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 6, 'quest_destroy_d', 'In an effort to cripple the Binayre Pirates, destroy five of their Black Jacks.'),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 7, 'quest_destroy_t', 'Destroy 5 Binyare Black Jacks'),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 8, 'quest_location_d', 'The Binayre Pirates tend to hunt in the Corellia system.  Go there to hunt them down.'),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 9, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 12, 'title', 'Corellia System: Seek and Destroy 5 Binayre ships.'),
('string/en/spacequest/destroy/c_sink_imp_space.stf', 13, 'title_d', 'Travel to the Corellia system, hunt down, and destroy five Binayre Black Jacks. You will receive navigational points of common Binayre activity. When you complete this mission, return to Ceth Laike at the Imperial Outpost on Talus.'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 6, 'quest_destroy_d', 'In an effort to cripple the Hidden Daggers, destroy five of their Leaders.'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 7, 'quest_destroy_t', 'Destroy 5 Hidden Dagger Leaders'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 8, 'quest_location_d', 'The Hidden Daggers tend to hunt in the Corellia system.  Go there to kill their leaders.'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 9, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 10, 'split_quest_alert', 'You should not let them get the better of you.  Go back out there do your duty!'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 12, 'title', 'Corellia System: Seek and Destroy 5 Hidden Dagger Leaders.'),
('string/en/spacequest/destroy/c_sink_reb_space.stf', 13, 'title_d', 'Travel to the Corellia system, hunt down, and destroy five Hidden Dagger Leaders. You will receive navigational points of common Hidden Dagger activity. When you complete this mission, return to Acun Solari in Tyrena on Corellia.'),
