('string/en/spacequest/destroy/master_imperial_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/master_imperial_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/master_imperial_1.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/master_imperial_1.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/master_imperial_1.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/master_imperial_1.stf', 6, 'quest_destroy_d', 'Be on the look out for A-Wings, B-Wings, X-Wings, Y-Wings, and Rebel Gunboats to destroy. You need to destroy 30 of those craft.'),
('string/en/spacequest/destroy/master_imperial_1.stf', 7, 'quest_destroy_t', 'Destroy Thirty Rebel Fighters'),
('string/en/spacequest/destroy/master_imperial_1.stf', 8, 'quest_location_d', 'The target system is Kessel. You are to travel to Kessel and attack any Rebel forces that are within the system. This should weaken the Rebels so that they are unable to properly fortify the system.'),
('string/en/spacequest/destroy/master_imperial_1.stf', 9, 'quest_location_t', 'Travel to the Kessel System'),
('string/en/spacequest/destroy/master_imperial_1.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/master_imperial_1.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/master_imperial_1.stf', 12, 'title', 'Kessel System: Seek and Destroy Rebel Fighters'),
('string/en/spacequest/destroy/master_imperial_1.stf', 13, 'title_d', 'Grand Admiral Nial Declann has formulated a plan to take control of the Kessel system for the Empire. You have been ordered to weaken the Rebel forces who have already taken up positions inside the system. The black holes in the system make it impossible to get a lock on individual ships so it will be nessecary to seek and destroy all targets involved. You are required to hunt down fighters and smaller, none capital, command vessels. The vessels that you are required to destroy are X-Wings, B-Wings, A-Wings, Y-Wings, and the Rebel gunboats.'),
('string/en/spacequest/destroy/master_imperial_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/master_imperial_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/master_imperial_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/master_imperial_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/master_imperial_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/master_imperial_2.stf', 6, 'quest_destroy_d', 'In order to ensure that the Empire is able to gain control of the Kessel sector the Rebel''s command vessel, a Corellian Corvette class cruiser, needs to be destroyed. Hunt down the Corvette and destroy the vessel. In order to destroy a captial ship you must target and destroy each sub-component of the ship.'),
('string/en/spacequest/destroy/master_imperial_2.stf', 7, 'quest_destroy_t', 'Destroy the Rebel Corellian Corvette'),
('string/en/spacequest/destroy/master_imperial_2.stf', 8, 'quest_location_d', 'The Rebel battlegroup has stationed itself in the Kessel system. Because of the black holes in the region their command vessel is easily masked from long range scan so you must search the sector until you find the Rebel''s corvette.'),
('string/en/spacequest/destroy/master_imperial_2.stf', 9, 'quest_location_t', 'Travel to the Kessel System'),
('string/en/spacequest/destroy/master_imperial_2.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/master_imperial_2.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/master_imperial_2.stf', 12, 'title', 'Kessel System: Seek and Destroy the Rebel Corvette'),
('string/en/spacequest/destroy/master_imperial_2.stf', 13, 'title_d', 'Now that the Rebel forces in the area have been reduced there is a much better chance that the Rebel command vessel can be destroyed. The Rebel battlegroup contains a Corellian Corvette class star cruiser. Grand Admiral Nial Declann''s plan is to destroy the corvette crippling the Rebel offense in the Kessel system. Without the support of thier capital ship the Rebels will have no choice but to pull their forces from the area.'),
('string/en/spacequest/destroy/master_rebel_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/master_rebel_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/master_rebel_1.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/master_rebel_1.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/master_rebel_1.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/master_rebel_1.stf', 6, 'quest_destroy_d', 'Hunt down and destroy any 30 Imperial Gunboats, TIE Advanced fighters, TIE Aggressor fighters, TIE Interceptors, or TIE Oppressors.'),
('string/en/spacequest/destroy/master_rebel_1.stf', 7, 'quest_destroy_t', 'Destroy Thirty Imperial Fighters'),
('string/en/spacequest/destroy/master_rebel_1.stf', 8, 'quest_location_d', 'The target area is the Kessel system. You are to travel to Kessel and attack any of the Imperial forces that are within the system. This should weaken the Imperials, so that they are unable to properly fortify the system.'),
('string/en/spacequest/destroy/master_rebel_1.stf', 9, 'quest_location_t', 'Travel to the Kessel System'),
('string/en/spacequest/destroy/master_rebel_1.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/master_rebel_1.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/master_rebel_1.stf', 12, 'title', 'Kessel System: Seek and Destroy Imperial Fighters'),
('string/en/spacequest/destroy/master_rebel_1.stf', 13, 'title_d', 'Admiral Willham has formulated a plan to take control of the Kessel system for the Alliance. You have been ordered to weaken the Imperial forces who have already taken up positions inside the system. The black holes in the system make it impossible to get a lock on individual ships so it will be nessecary to seek and destroy all targets involved. You are required to hunt down fighters and smaller, none capital, command vessels. The vessels that you are required to destroy are TIE variants and the Imperial Gunboats.'),
('string/en/spacequest/destroy/master_rebel_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/master_rebel_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/master_rebel_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/master_rebel_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/master_rebel_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/master_rebel_2.stf', 6, 'quest_destroy_d', 'In order to ensure that the Alliance is able to gain control of the Kessel system, the Imperial''s command vessel, a Corellian Corvette class cruiser, needs to be destroyed. Hunt down the Corvette and destroy the vessel. In order to destroy a captial ship you must target and destroy each sub-component of the ship.'),
('string/en/spacequest/destroy/master_rebel_2.stf', 7, 'quest_destroy_t', 'Destroy the Imperial Corellian Corvette'),
('string/en/spacequest/destroy/master_rebel_2.stf', 8, 'quest_location_d', 'The Imperial battlegroup has stationed itself in the Kessel system. Because of the black holes in the region their command vessel is easily masked from long range scan so you must search the system until you find the Imperial''s corvette.'),
('string/en/spacequest/destroy/master_rebel_2.stf', 9, 'quest_location_t', 'Travel to the Kessel System'),
('string/en/spacequest/destroy/master_rebel_2.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/master_rebel_2.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/master_rebel_2.stf', 12, 'title', 'Kessel System: Seek and Destroy the Imperial Corvette'),
('string/en/spacequest/destroy/master_rebel_2.stf', 13, 'title_d', 'Now that the Imperial forces in the area have been reduced, there is a much better chance that the Imperial command vessel can be destroyed. The Imperial battlegroup contains a Corellian Corvette class star cruiser. Admiral Willham''s plan is to destroy the corvette crippling the Imperial offense in the Kessel system. Without the support of thier capital ship the Imperials will have no choice but to pull their forces from the area.'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 6, 'quest_destroy_d', 'Search the Naboo system for four Rebel X-wing fighter cadets. Once you have completed this task return to your commanding officer.'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 7, 'quest_destroy_t', 'Destroy Four X-Wing Fighter Cadets'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 8, 'quest_location_d', 'Our reports show that a squad of Rebel X-wing fighter cadets has moved into the Naboo system. Imperial command has supplied you with several areas that might be good to start your search.'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 9, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 10, 'split_quest_alert', 'You are still not done with your job. Even though you have failed, we still expect you to kill four X-wing Cadets. Get back to work.'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 12, 'title', 'Naboo System: Seek and Destroy X-Wing Fighter Cadets'),
('string/en/spacequest/destroy/naboo_imperial_2.stf', 13, 'title_d', 'Travel to the Naboo system, hunt down, and destroy four X-wing fighter cadets. Since the Empire is unsure where the X-wing fighter cadets are located in the Naboo system, you will receive a few navigation waypoints to suspected areas of Rebel activity. You can check out area around the waypoints to see if you can locate the Rebel cadets or just search the system yourself.  When you complete this mission, return to Lt. Barn Sinkko in Kadaara for your next assignment.'),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 6, 'quest_destroy_d', 'Find the rebel leader at the given Nav location. If he is not there when you arrive destroy the xwings at the location and they will send out a distress signal that he is sure to respond to. Once you have eliminated him return to your commanding officer.'),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 7, 'quest_destroy_t', 'Destroy the Rebel Leader'),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 8, 'quest_location_d', 'Intelligence reports that the rebel leader is still located inside the Nabooian sector. They have supplied a Nav waypoint to his last known location. Search that area for the rebel leader.'),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 9, 'quest_location_t', 'Travel to the Nabooian Sector'),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 11, 'title', 'Eliminate Rebel Team Leader'),
('string/en/spacequest/destroy/naboo_imperial_4.stf', 12, 'title_d', 'Imperial Intelligence has a lead on the location of the rebel team leader who was attempting to capture a shipment of the E-62s. The rebellion cannot be allowed to get away with these strike on Imperial interests and the leader of this raid must be destroyed. You are to hunt down and destroy the rebel strike leader.'),
