INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/destroy/naboo_privateer_2.stf', 10, 'split_quest_alert', '\\#pcontrast3 Capt Dinge: < \\#pcontrast1 You appear to have hit a little snag out there Captain.  Get patched up and take down those Black Sun. \\#pcontrast3 >'),
('string/en/spacequest/destroy/naboo_privateer_2.stf', 11, 'split_quest_alert_fail', '\\#pcontrast3 Capt Dinge: < \\#pcontrast1 You appear to have hit a little snag out there Captain.  Get patched up and take down those Black Sun. \\#pcontrast3 >'),
('string/en/spacequest/destroy/naboo_privateer_2.stf', 12, 'title', 'Naboo System: Search for and Destroy the Black Sun Pirates'),
('string/en/spacequest/destroy/naboo_privateer_2.stf', 13, 'title_d', 'Visit some of the provided waypoints and destroy any Black Sun presence you find there. When you complete this mission, return to Captain Dinge in the Theed Palace for your next assignment.'),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 1, 'assigned_delayed', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Blacksun fighters have been sighted in your area.  Track them down and destroy them. \\#pcontrast3 >'),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 5, 'quest_destroy_d', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 6, 'quest_destroy_t', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 7, 'quest_location_d', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 8, 'quest_location_t', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 9, 'split_quest_alert', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Head for Naboo Space, we will have more information when you arrive. \\#pcontrast3 >'),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 10, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 11, 'title', 'Taking out the Trash'),
('string/en/spacequest/destroy/naboo_privateer_tier3_1c.stf', 12, 'title_d', ''),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 6, 'quest_destroy_d', 'The Imperial TIE fighter is built to be cheap and reliable. It doesn''t have a shield system or heavy armor but it makes up for that in speed and agility. Lone TIE fighters are hard to come by, they usually travel in big packs to be more of a threat.'),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 7, 'quest_destroy_t', 'TIE Fighter.'),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 8, 'quest_location_d', 'The Naboo system is always dangerous for us. It has a high concentration of Imperial forces and is rumored to be the Emperors home away from home.'),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 9, 'quest_location_t', 'Naboo system.'),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 10, 'split_quest_alert', 'Rebel Command: < Don''t let them defeat you pilot. Get back out there and show them that the Alliance fold for no one! >'),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 12, 'title', 'Naboo system: Hunt the TIE Fighters.'),
('string/en/spacequest/destroy/naboo_rebel_2.stf', 13, 'title_d', 'We want to show the Empire that they are not untouchable in the Naboo system. Hunt down four TIE fighters and destroy them. That should be a sufficient wake up call for the Empire. When you complete this mission, return to V3-FX in Moenia for your next assignment.'),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 5, 'quest_destroy_d', 'The Zynt''aia Order has forcefully claimed the mining field close to A''Lerris'' home base. It is my duty to clear several of the pirates out in order to restore the balance to the mining field. The freighters and miners will then be able to continue their work.'),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 6, 'quest_destroy_t', 'Destroy the Zynt''aia Pirates'),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 7, 'quest_location_d', 'It has been my directive from A''Lerris to travel to the Tatoo System, if I''m not there already.'),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 8, 'quest_location_t', 'Travel to the Tatoo System'),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 9, 'split_quest_alert', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < We want you to continue you task, pilot, though in a different area. You''ve done well. Soon, I''ll transmit the additional information you''ll need to continue your mission. >'),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 10, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 11, 'title', 'Tatoo System: The Awakened: Zynt''aia Order'),
('string/en/spacequest/destroy/poi_tatooine_general2_2.stf', 12, 'title_d', 'A''Lerris Verata, the strong leader of the mining efforts in the Tatoo System, has informed me of her concerns regarding the awakened Zynt''aia Order. Due to my presence, and my assistance with the mining efforts, the Zynt''aia Pirates have begun to spring unwanted and stealthy attacks against the peaceful miners. It is my duty, as a directive from A''Lerris herself, to clear the Zynt''aia influence from the mining field. Unfortunately, it seems the Zynt''aia Order has stirred and moved in to claim the field, destroying freighters and miners alike with little to no thought at all. It is time to extinguish the influence and replenish the balance.'),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 5, 'quest_destroy_d', 'A''Lerris has transmitted a new area in which I must extinguish the influence of the Zynt''aia Order. Once I have completed my mission, the balance will be restored and the miners can continue their work undauntedly.'),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 6, 'quest_destroy_t', 'Destroy the Zynt''aia Pirates'),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 7, 'quest_location_d', 'My task directs me to the Tatoo System. I must travel there if I haven''t already and complete my mission as directed.'),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 8, 'quest_location_t', 'Remain in the Tatoo System'),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 9, 'split_quest_alert', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < Pilot. Listen carefully as this is a highly sensitive mission and must be undertaken with utmost care. We''ve been contacted by the captured crew of one of our missing freighters. It seems that the Zynt''aia pirates have taken a freighter and its crew hostage. It is your duty to rescue it and bring it home. Please be careful. We''re counting solely on you. >'),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 10, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 11, 'title', 'Tatoo System: Extinguish the Influence'),
('string/en/spacequest/destroy/poi_tatooine_general2_2_a.stf', 12, 'title_d', 'A''Lerris has instructed me to move on to another area to continue my work. She''s effortlessly transmitted the information I need to find my objective and I will continue my task with little interruption. '),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 6, 'quest_destroy_d', 'The Empire realizes that the war against these pirates will not be won in a single battle. Instead they just want you to control the numbers of pirates in the region. Seek and destroy four commerce raiders in the Tatooine sector.'),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 7, 'quest_destroy_t', 'Destroy the Commerce Raiders'),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 8, 'quest_location_d', 'The Commerce Raiders operate in the Tatooine system attacking it''s rich shipping lanes and then selling the cargo to one of Tatooines many criminal overlords, such as Jabba the Hutt. Imperial command has supplied you with several navigation waypoints to areas of high pirate activity.'),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 9, 'quest_location_t', 'Travel to the Tatooine System'),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 10, 'split_quest_alert', 'Failure is not an option! You are still expected to kill four Commerce Raiders.'),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 12, 'title', 'Tatooine System: Seek and Destroy Four Commerce Raiders'),
('string/en/spacequest/destroy/tatooine_imperial_2.stf', 13, 'title_d', 'With it''s lucrative shipping routes and small police force the Tatooine system has become ripe with pirate activity. If the Empire wants any chance at gaining a serious foot hold on Outer Rim worlds the pirates of those sectors must be eliminated. The Commerce Raider''s numbers are growning constantly and it is time for them to be culled. Imperial command has supplied you with several navigation waypoints to areas of high pirate activity. When you complete this mission, return to Lt. Akal Colzet in the Imperial Pilot''s Association Hall next to the Bestine Capital building for your next assignment.'),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 6, 'quest_destroy_d', 'In order for the Empire to have any control over these nefarious pirates you will have to take out their leader. Destroy the Commerce Raider Leader.'),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 7, 'quest_destroy_t', 'Destroy the Commerce Raider Leader'),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 8, 'quest_location_d', 'Intelligence reports that the leader is staged along a busy commerical route in the Tatooine sector. You will recieve a Nav location to the Commerce Raider Leader''s last confirmed location on reaching the Tatooine sector.'),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 9, 'quest_location_t', 'Travel to the Tatooine Sector'),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 10, 'split_quest_alert', ''),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 11, 'title', 'Eliminate Pirate Leader'),
('string/en/spacequest/destroy/tatooine_imperial_4.stf', 12, 'title_d', 'The Commerce Raiders are becoming a problem that is quickly growing out of control. Intelligence has managed to get a lock on where the pirate''s leader is laying low. Without their leader, Imperial Command hopes that the pirates will lose a great deal of their effectiveness. You are to destroy this leader.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 6, 'quest_destroy_d', 'Seek and destroy any Rebel A-wing, B-wing, Y-wing, X-wing, or Z95''s that can be found in the Endor system. Destroy them until you receive word from command that the decoy shuttle is ready.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 7, 'quest_destroy_t', 'Destroy Rebel Fighters'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 8, 'quest_location_d', 'Destroy the fighters inside of the Endor system. You will have to search for the fighters in the area.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 9, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 10, 'split_quest_alert', 'The decoy shuttle is all set up with the false information. Meet up with the shuttle and assist it through the system. In order to make sure that the Rebels are completely sold that it contains real and valuable information, you are going to have to make it look as real as possible. Destroy four of the enemy attack waves while you are escorting the shuttle. This should convince the Rebels that the plans they will find on the shuttle are real.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 12, 'title', 'Endor System: Seek and Destroy Rebel Fighters'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_3_b.stf', 13, 'title_d', 'In order to assist with the deception of the fake Imperial plans, you need to destroy a few of their craft as if the Empire is going on the offensive. Seek and destroy Rebel fighters until you are contacted by command that the decoy shuttle is ready.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 6, 'quest_destroy_d', 'Search the Endor system and destroy ten Rebel fighters. Any standard Rebel X-Wing, Y-Wing, A-Wing, or B-Wing will do.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 7, 'quest_destroy_t', 'Destroy Ten Rebel Fighters'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 8, 'quest_location_d', 'Find the rebel fighters in the Endor system.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 9, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 10, 'split_quest_alert', 'We have a situation here! Our Imperial Command shuttle is under heavy assault. Immediately proceed to the following location and intercept the attacking fighters.'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 11, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 12, 'title', 'Endor System: Seek and Destroy Ten Rebel Fighters'),
('string/en/spacequest/destroy/tatooine_imperial_tier3_4.stf', 13, 'title_d', 'We have a lock on the Rebel command vessel, but the time has not yet come to attack it. We still do not know exactly what the Rebels are doing in this system. But command wants to start culling the number of Rebels in the sector. Search the Endor system and destroy ten Rebel fighters.'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 6, 'quest_destroy_d', 'Black Sun Pirates have been reported at or around these areas, destroy them if present.'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 7, 'quest_destroy_t', 'Areas of Black Sun Activity'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 8, 'quest_location_d', 'Search the provided system waypoints for concentrations of Black Sun activity.'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 9, 'quest_location_t', 'Tatooine System'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 10, 'split_quest_alert', '\\#pcontrast3 Dravis: < \\#pcontrast1 You appear to have hit a little snag out there.  Get patched up and take down those Black Sun. \\#pcontrast3 >'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 11, 'split_quest_alert_fail', '\\#pcontrast3 Dravis: < \\#pcontrast1 You appear to have hit a little snag out there.  Get patched up and take down those Black Sun. \\#pcontrast3 >'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 12, 'title', 'Tatooine System: Hunt the Black Sun Pirates'),
('string/en/spacequest/destroy/tatooine_privateer_2.stf', 13, 'title_d', 'Visit some of the provided waypoints and destroy any Black Sun presence you find there. When you complete this mission, return to Dravis in back room of the Mos Eisley cantina for your next assignment.'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 6, 'quest_d', 'The TIE fighters that attacked you on your first sensor sweep are gathering in the Tatooine system for a larger assault. Find them and take down at least four (4) of them.'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 7, 'quest_destroy_d', 'The Imperial TIE fighter is built to be cheap and reliable. It doesn''t have a shield system or heavy armor but it makes up for that in speed and agility. Lone TIE fighters are hard to come by, they usually travel in big packs to be more of a threat.'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 8, 'quest_destroy_t', 'TIE Fighter.'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 9, 'quest_location_d', 'The Tatooine system doesn''t have a heavy Imperial presence but it''s filled to the brim with scoundrels, pirates and bounty hunters so don''t get too relaxed.'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 10, 'quest_location_t', 'Tatooine system.'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 11, 'quest_t', 'Hunt down TIE Fighters'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 12, 'split_quest_alert', 'Rebel Command: < Don''t let them defeat you pilot. Get back out there and show them that the Alliance fold for no one! >'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 14, 'title', 'Tatooine system: Hunt down TIE Fighters.'),
('string/en/spacequest/destroy/tatooine_rebel_3.stf', 15, 'title_d', 'The TIE fighters that attacked you on your first sensor sweep are gathering for a larger assault. Hunt down TIE fighters in the Tatooine system and destroy four (4) of them to send a message to the Empire and make them think twice about any sort of counter attack. When you complete this mission, return to Commander Da''la Socuna in back room of the Mos Espa cantina for your next assignment.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 2, 'boss_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Rebel captain detected, prepare for assault \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 3, 'boss_title_0', 'Rebel Captain'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 4, 'boss_title_1', 'Rebel Captain'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 5, 'boss_title_2', 'Rebel Captain'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 6, 'boss_title_3', 'Rebel Captain'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 7, 'boss_title_4', 'Rebel Captain'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 8, 'boss_title_5', ''),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 9, 'complete', 'Another victory earned for Black Epsilon.  Return to base.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 10, 'dd_boss_taunt_1', 'Now you will die Imperial aggressor.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 11, 'dd_boss_taunt_2', 'The Rebellion will never falter!'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 12, 'dd_boss_taunt_3', 'Prepare to be vaporized!'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 13, 'dd_boss_taunt_4', 'Our day has come!'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 14, 'dd_boss_taunt_5', ''),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 15, 'duty_update', '\\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 16, 'found_loc', 'Uploading the coordinates to suspect Rebel activity now.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 17, 'level_boss', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 A %TO has been spotted, do not let them escape. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 18, 'level_boss_dead', 'This is a great blow to the Rebellion.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 19, 'level_increase', 'More Rebel craft have been detected.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 20, 'quest_destroy_d', 'Destroy any Rebel fighters that attack you. Keep a close eye out for the Rebel Captains who will come in to try to take you out if you destroy enough of their men.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 21, 'quest_destroy_t', 'Destroy Rebel Fighters'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 22, 'quest_location_d', 'Corellia, although offically neutral, has always been known for harboring members of the Rebellion. Travel to that sector to receive your first Nav location to areas of high Rebel activity.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 23, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 24, 'targets_behind', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy targets coming fast from behind! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 25, 'targets_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy targets sighted.  Prepare for assault. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 26, 'taunt_1', 'The Empire sent you to hunt me? Pathetic!'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 27, 'taunt_2', 'I hope you have life insurance.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 28, 'taunt_3', 'Beg all you want. I will not show mercy.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 29, 'taunt_4', 'This is your last chance to flee.'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 30, 'taunt_5', ''),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 31, 'title', 'Corellia System: Destroy the Rebel Fighters Duty'),
('string/en/spacequest/destroy_duty/corellia_imperial_10.stf', 32, 'title_d', 'Travel to the Corellia system and destroy the Rebel fighters. Black Epsilon believes that it is time to take the fight to the Rebellion. Intelligence has managed to locate several areas of high Rebel activity. You are to travel to these areas and destroy any Rebels that you find in the area.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 2, 'boss_detected', 'Tactical Computer: < Vessel with veteran insignias on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 3, 'boss_title_1', 'Experienced Rebel Pilot'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 4, 'boss_title_2', 'Veteran Rebel Pilot'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 5, 'boss_title_3', 'Grim Veteran Rebel Pilot'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 6, 'boss_title_4', 'Furious Veteran Rebel Pilot'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 7, 'boss_title_5', 'Ace Veteran Rebel Pilot'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 8, 'complete', 'Good work pilot, the Emperor would be proud. We can''t detect anymore B-Wing Prototypes in the area, return to base.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 9, 'dd_boss_taunt_1', 'This is who I''m missing supper for? Give me two minutes to handle this.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 10, 'dd_boss_taunt_2', 'The reign of the Empire is coming to a end and it starts with you!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 11, 'dd_boss_taunt_3', 'This monster is all mine, you will pay for your crimes!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 12, 'dd_boss_taunt_4', 'You filthy scum, I will avenge my friends!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 13, 'dd_boss_taunt_5', 'Finally a worthy opponent. I hope you have made peace with your maker, you''re about to meet him!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 14, 'duty_update', 'Black Epsilon Command: < %TO >'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 15, 'found_loc', 'The next area of spotted B-Wing activity has been uploaded to your nav computer. Proceed as planned.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 16, 'level_boss', 'Black Epsilon Command: < The Rebel scum has sent a %TO to bring you down, proceed with caution. Emperor guide you! >'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 17, 'level_boss_dead', 'You showed amazing skills pilot, the Rebel scum will speak your name in fear! Stand by for further orders.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 18, 'level_increase', 'The Rebels are ramping up their activity in response to your victories.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 19, 'quest_destroy_d', 'Once you have reached the navigation waypoint, you will be attacked by B-wings. Destroy the B-wings at this location until you receive a new navigation waypoint to your next battleground. If you destroy enough of these B-wings, the Rebellion will send out better trained pilots in order to deal with you. Destroy duties can be quit at any time. Simply abort the mission or leave the system.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 20, 'quest_destroy_t', 'Travel to the Navigation Waypoint and Destroy the B-wings'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 21, 'quest_location_d', 'Travel to the Corellia system and move towards your first navigation waypoint to begin the destroy duty mission. When you destroy all attack waves at that waypoint you will receive a new navigation waypoint.'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 22, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 23, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 24, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 25, 'taunt_1', 'You''re all mine, Imperial dog!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 26, 'taunt_2', 'Your the scum that shot down my brother, I will avenge him!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 27, 'taunt_3', 'This new technology is far superior to your puny vessel. Prepare to die Imperial scum!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 28, 'taunt_4', 'You will never leave this sector, murderer!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 29, 'taunt_5', 'Time to pay for your endless crimes, filthy Imperial henchman!'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 30, 'title', 'Corellia System: Destroy the Remaining B-wing Prototypes Duty'),
('string/en/spacequest/destroy_duty/corellia_imperial_6.stf', 31, 'title_d', 'Travel to the Corellia system and destroy the remaining B-wing prototypes. A destroy duty is a voluntary mission that you are able to quit at any time without repercussions. When you reach the Corellia system a navigation waypoint will be sent to you. Travel to this waypoint and you will be attacked by enemy fighters. Each time you destroy a wave of fighters a new wave will attack. Once you have destroyed all the attack waves at one waypoint, you will receive a new waypoint that you can fly to and continue destroying the enemy craft. A destroy duty will continue in this manner until you decide to stop.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 2, 'boss_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Hostile craft on approach path. > '),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 3, 'boss_title_1', 'Nights Blade'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 4, 'boss_title_2', 'Deadly Blade'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 5, 'boss_title_3', 'Dancing Dagger'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 6, 'boss_title_4', 'Shadow Knife'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 7, 'boss_title_5', 'Dark Assassin'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 8, 'complete', 'Long range scans show no more pirate activity in the area, return to base.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 9, 'dd_boss_taunt_1', 'Do they send children to fight their wars now?'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 10, 'dd_boss_taunt_2', 'Are you going to attack or stare at me all day?'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 11, 'dd_boss_taunt_3', 'I''m going to chop you up and feed you to my Gronda!'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 12, 'dd_boss_taunt_4', ''),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 13, 'dd_boss_taunt_5', ''),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 14, 'duty_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 15, 'found_loc', 'Next location of pirate activity has been uploaded to your nav computer.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 16, 'level_boss', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < %TO has shown up on the scanners, be ready >'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 17, 'level_boss_dead', 'These simple pirates were no match for your superior fighting skills.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 18, 'level_increase', 'The enemy has taken notice of your actions, be on guard.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 19, 'quest_destroy_d', 'Destroy any Hidden Dagger fighter you find in any of the hot spot areas. Be on the look out for their ace pilots whom will come after you if you cause enough trouble.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 20, 'quest_destroy_t', 'Destroy the Hidden Daggers'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 21, 'quest_location_d', 'The Hidden Daggers are stationed in the Corellian system. Locate their fighters in that region and destroy them. Once you arrive in the system, Intelligence has supplied us with locations to known Hidden Dagger hot spots.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 22, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 23, 'targets_behind', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Be aware, vessels trying to target this ship with their weapon systems. Attack orginating direction 180 degrees. > '),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 24, 'targets_detected', '\\#pcontrast1Tactical Computer:\\#pcontrast3 < Vessels bearing marks of the Hidden Daggers spotted > '),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 25, 'taunt_1', 'This one is no match for me.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 26, 'taunt_2', 'I have first call on the spare parts.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 27, 'taunt_3', 'I will decorate my house with what is left of your ship.'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 28, 'taunt_4', 'The hidden daggers will not be stopped!'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 29, 'taunt_5', ''),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 30, 'title', 'Corellia System: Destroy the Hidden Daggers Duty'),
('string/en/spacequest/destroy_duty/corellia_imperial_8.stf', 31, 'title_d', 'Travel to the Corellia system and destroy Hidden Daggers. The Rebels have many allies in the Corellian system and they are trying to gain more. They have been in negotiations with the Hidden Daggers in an attempt to gain their support. Send a message to the Hidden Daggers that any assistance they give to the Rebellion will have dire consequences.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 2, 'boss_detected', 'Be on the lookout. A heavy fighter has been detected in your sector.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 3, 'boss_title_1', 'Ripper'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 4, 'boss_title_2', 'Ravager'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 5, 'boss_title_3', 'Sky Wraith'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 6, 'boss_title_4', 'Space Hunter'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 7, 'boss_title_5', 'Reaper'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 8, 'complete', 'You have defeated your assigned targets. Excellent flying out there, pilot. Return to your commander for mission debriefing.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 9, 'dd_boss_taunt_1', 'They sent you out to do a man''s work?'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 10, 'dd_boss_taunt_2', 'Maybe you should have choosen a new profession.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 11, 'dd_boss_taunt_3', 'I will make you pay for everyone of my men you destroyed.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 12, 'dd_boss_taunt_4', 'You have caused enough trouble. It is time for you to die.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 13, 'dd_boss_taunt_5', 'You are indeed skilled, but that skill will not help you now.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 14, 'duty_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 15, 'found_loc', 'We have discovered another cluster of enemy fighters that need to be cleared out. Proceed to nav location and begin the sweep and clear.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 16, 'level_boss', 'The heavy fighter has been eliminated. Nice job, pilot.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 17, 'level_boss_dead', 'The heavy fighter has been eliminated. Nice job, pilot.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 18, 'level_increase', 'Be careful, pilot. It looks like this set it better organized and trained then the last.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 19, 'quest_d', 'Velocity Mercenaries have begun increased operations in the Dantooine sector. They have even gone so far as to start attacking imperial convoys. Intelligence reports indicate that their numbers have grown to dangerous levels and need to controlled before they gain to much power in the sector.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 20, 'quest_destroy_d', 'Travel to the waypoint given to an area of high Velocity Mercenary density. Destroy all attacking waves in that area until you receive a new waypoint guiding you towards the next area.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 21, 'quest_destroy_t', 'Destroy the Velocity Mercenaries'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 22, 'quest_location_d', 'Travel to the Dantooine system to begin duty mission of reducing the total number of Velocity Mercenaries in the area.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 23, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 24, 'quest_t', 'Velocity Fighter Sweep and Clear'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 25, 'targets_behind', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters detected incoming from the rear.>'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 26, 'targets_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 27, 'taunt_1', 'Our orders are to make sure you don''t return alive.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 28, 'taunt_2', 'You will pay for that!'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 29, 'taunt_3', 'Feel the might of the Velocity.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 30, 'taunt_4', 'I will crush you.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 31, 'taunt_5', 'Make it easy on yourself, give up now.'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 32, 'title', 'Dantooine System: Destroy the Velocity Mercenaries Duty'),
('string/en/spacequest/destroy_duty/corellia_imperial_tier4_1.stf', 33, 'title_d', 'Travel to the Dantooine system and destroy the Velocity mercenaries. Intelligence reports that they are massing into ever increasing numbers and Command wants those numbers reduced. The mission is a simple sweep and clear. You will travel to locations of high enemy density and clear those areas out with lethal force.'),
