('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 3, 'boss_title_1', 'Russ Grimblade (Hidden Daggers Captain)'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 4, 'boss_title_2', 'Xopw Laow (Hidden Daggers Captain)'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 5, 'boss_title_3', 'Mori the Bastard (Hidden Daggers Captain)'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 6, 'boss_title_4', 'Owpa Awoz (Hidden Daggers Captain)'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 7, 'boss_title_5', 'Quixio the Rotten (Hidden Daggers Captain)'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 8, 'complete', 'Fantastic job pilot, we struck a huge blow to the Hidden Daggers today. Return to base for a well earned rest.'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 9, 'dd_boss_taunt_1', 'Muahahaha!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 10, 'dd_boss_taunt_2', 'Your just another kill mark on my ship, CorSec!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 11, 'dd_boss_taunt_3', 'The cat becomes the mouse. The tables are turned, CorSec scum!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 12, 'dd_boss_taunt_4', 'Your flying skills remind me of a one winged Mynock!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 13, 'dd_boss_taunt_5', 'I''ve never seen those moves from a  CorSec before. No matter, prepare to die!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 14, 'duty_update', 'CorSec Command: < %TO >'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 15, 'found_loc', 'New coordinates of pirate activity has been uploaded to your nav computer. Go get them!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 16, 'level_boss', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 The Hidden Daggers has sent %TO to bring you down, proceed with caution. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 17, 'level_boss_dead', 'Amazing! The Hidden Daggers will not forget this day. Stand by for further orders.'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 18, 'level_increase', 'The Hidden Daggers are sending more reinforcements in responce to our attacks.'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 19, 'quest_destroy_d', 'Area of enemy activity'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 20, 'quest_destroy_t', 'Destroy Target'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 21, 'quest_location_d', 'Dynamic sorties throughout the Corellia System'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 22, 'quest_location_t', 'Corellia System'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 23, 'targets_behind', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees.\\#pcontrast3  >'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 24, 'targets_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Vessels fitting hunted ship profile on attack vector, weapon systems armed. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 25, 'taunt_1', 'You think you can match the Hidden Daggers? I think not!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 26, 'taunt_2', 'I will shred your ship CorSec fool!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 27, 'taunt_3', 'You CorSec always have to interfere, well this time you stuck your nose too deep!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 28, 'taunt_4', 'You''re fighting a uphill battle CorSec, and the hill just got steeper!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 29, 'taunt_5', 'I have crushed greater things than you CorSec! In fact, I shot a Womprat back on Tatooine last week!'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 30, 'title', 'Corellia System: Duty: Strike a blow to the Hidden Daggers Leadership.'),
('string/en/spacequest/destroy_duty/corellia_privateer_6.stf', 31, 'title_d', 'Hunt Down the Hidden Daggers Leaders'),
('string/en/spacequest/destroy_duty/corellia_privateer_9.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/corellia_privateer_9.stf', 2, 'boss_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 A powerful enemy craft has entered the fight. \\#pcontrast3 >'),
