('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 2, 'boss_detected', ' \\#pcontrast3 Alliance HQ:  \\#pcontrast1 < Warning! Enemy commander detected on attack vector! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 3, 'boss_title_0', 'TIE Combat Trainer'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 4, 'boss_title_1', 'TIE Combat Trainer'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 5, 'boss_title_2', 'TIE Combat Ace'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 6, 'boss_title_3', 'TIE Obsidian Squad Leader'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 7, 'boss_title_4', 'TIE Black Ops Commander'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 8, 'boss_title_5', 'TIE (Unknown) Ace'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 9, 'complete', 'Excellent work, Pilot! The Imperial presence in this sector has been soundly beaten. Return to base!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 10, 'dd_boss_taunt_1', 'You killed my men. Now you''re mine!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 11, 'dd_boss_taunt_2', 'If you cut your engines, I promise not to harm you.'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 12, 'dd_boss_taunt_3', 'I''m going to enjoy spacing you.'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 13, 'dd_boss_taunt_4', 'A thousand creds to the man who takes him out!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 14, 'dd_boss_taunt_5', 'Your skill is not sufficient to beat me Rebel scum!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 15, 'duty_update', ' \\#pcontrast3 Alliance HQ:  < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 16, 'found_loc', 'We are uploading coordinates of suspected Imperial ambushes. Investigate and eliminate all hostiles.'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 17, 'level_boss', ' \\#pcontrast3 Alliance HQ: < \\#ff0000 The Imperials are sending a highly trained %TO after you. Stand by for coordinates... \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 18, 'level_boss_dead', 'Good work, the commander has been destroyed. We''re still picking up Imperial activity, however. Stand by...'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 19, 'level_increase', 'We''ve detected that more TIE ships have been sent into the sector.'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 20, 'quest_destroy_d', 'Fly to this potential ambush point. Destroy all enemy craft that come your way.'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 21, 'quest_destroy_t', 'Potential Ambush Rally Point'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 22, 'quest_location_d', 'Patrol the Corellia system in search of potential TIE ambushes. We must make it clear to the Empire that they are not welcome here.'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 23, 'quest_location_t', 'Corellia system.'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 24, 'targets_behind', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets coming in from behind! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 25, 'targets_detected', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets on incoming attack vector! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 26, 'taunt_1', 'Take that Rebel scum for a spin boys!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 27, 'taunt_2', 'The Empire has a warrant for your death..erm arrest, cut your engines!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 28, 'taunt_3', 'Resistance is futile Rebel!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 29, 'taunt_4', 'You should have fled while you had the chance scum!'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 30, 'taunt_5', 'Well if it isn''t a Rebel. Are you lost little friend?'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 31, 'title', 'Corellia system: Duty mission: Break up TIE ambushes'),
('string/en/spacequest/destroy_duty/corellia_rebel_6.stf', 32, 'title_d', 'Break up TIE ambushes in the Corellia system. These missions have been outlined to give you some much needed experience in space combat, you can stop when you feel that you have learned enough.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 1, 'boss_detected', 'Our sensors are picking up the ship signature of Black Sun captain, get ready!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 2, 'boss_title_1', 'Ovlaw Grimclaw'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 3, 'boss_title_2', 'L''kew Rawo'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 4, 'boss_title_3', 'Rita ''the Razor'''),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 5, 'boss_title_4', 'Walwer Bealwo'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 6, 'boss_title_5', 'Amos Torq'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 7, 'complete', 'Amazing! The Black Sun will not forget this day! Return to base and rest up, you did good today pilot.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 8, 'dd_boss_taunt_1', 'You fool! Standing up to the Black Sun is suicide!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 9, 'dd_boss_taunt_2', 'You''re no match for my skill Rebel!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 10, 'dd_boss_taunt_3', 'Pathetic worm, prepare to face my wrath!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 11, 'dd_boss_taunt_4', 'The Black Sun will crush you and your pathetic Nym friends!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 12, 'dd_boss_taunt_5', 'I''m your worst nightmare Rebel and there''s no waking up from this one!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 13, 'duty_update', 'Nym Command Officer: < %TO >'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 14, 'found_loc', 'Alright we are tracking more Black Sun fighters in this area. Give ''em hell!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 15, 'level_boss', 'The stinking Black Sun is responding to the attacks by sending %TO, one of their captains.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 16, 'level_boss_dead', 'Whow! %TO has been a thorn in our side for a long time, great job!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 17, 'level_increase', 'The Black Sun are waking up, you''ll find that they will send tougher pilots in response to your attacks.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 18, 'quest_destroy_d', 'Proceed with terminating Black Sun scum. We will update your navigation computer with new coordinates of where they have been spotted.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 19, 'quest_destroy_t', 'Destroy Black Sun ships.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 20, 'quest_location_d', 'You''re an experienced pilot, and the Dantooine system shouldn''t pose a big threat, but don''t relax too much, the sneaky Black Sun are sure to have some surprises.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 21, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 24, 'taunt_1', 'Take him out boys!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 25, 'taunt_2', 'You Rebel fools will wish you never messed with the Black Sun!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 26, 'taunt_3', 'For the dark prince!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 27, 'taunt_4', 'I got you in my sights scum, there''s no escape!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 28, 'taunt_5', 'I''m getting closer, the next bolt will fry your engine and then it''s all over!'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 29, 'title', 'Dantooine system: Duty mission: Strike a blow to the Black Sun.'),
('string/en/spacequest/destroy_duty/corellia_rebel_tier4_1.stf', 30, 'title_d', 'The Black Sun is taking more and more liberties against us. Let''s teach them a lesson by launching guerilla attacks against their fighters. When you feel that you have exhausted your ship, yourself, or that you have enough experience to continue your training, you can return to base at any time.'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 1, 'boss_detected', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Cloak Ace signature detected. Enemy craft incoming.\\#pcontrast1 >'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 2, 'boss_title_1', 'Cloak Ace'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 3, 'boss_title_2', 'Cloak Ace'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 4, 'boss_title_3', 'Cloak Ace'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 5, 'boss_title_4', 'Cloak Ace'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 6, 'boss_title_5', 'Cloak Ace'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 7, 'complete', 'Good work, pilot. No further Cloak activity is detected in this system. Return to the station for debriefing.'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 8, 'dd_boss_taunt_1', 'Your time has come, CorSec!'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 9, 'dd_boss_taunt_2', 'Your time has come, CorSec!'),
('string/en/spacequest/destroy_duty/corellia_station_duty1.stf', 10, 'dd_boss_taunt_3', 'Your time has come, CorSec!'),
