('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 8, 'complete', 'Nice flying out there, pilot. You are really turning into an elite pilot. Return to your commander and report your success.'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 9, 'dd_boss_taunt_1', 'Prepare to be left to the mercys of cold, empty space.'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 10, 'dd_boss_taunt_2', 'You are the pilot that they sent against me? HA!'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 11, 'dd_boss_taunt_3', 'You had better be gone before I taunt you a second time.'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 12, 'dd_boss_taunt_4', 'Time to teach this Imperial whelp who really rules Dathomir.'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 13, 'dd_boss_taunt_5', 'You have caused enough trouble. It is time for me to end this.'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 14, 'duty_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 15, 'found_loc', 'We have located more pirates that need to be driven out of this system. Travel to the location provided to your nav computer and eliminate the Rebels.'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 16, 'level_boss', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%TO has been eliminated. The Rebels in this region are leaderless.>'),
