('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 26, 'targets_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters incoming at attack speeds. Prepare to engage.>'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 27, 'taunt_1', 'Foolish Imperial! You are no match for me.'),
('string/en/spacequest/destroy_duty/dathomir_station_imp_destroy_duty_tier3.stf', 28, 'taunt_2', 'Nice move, but you will have to do much better in order to win.'),
