('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 9, 'complete', 'Good job, pilot! You''ve managed to do significant damage to Nym''s forces in this sector. Return to base.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 10, 'dd_boss_taunt_1', 'I want to hear you scream while I cut your ship open.'),
