('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 16, 'found_loc', 'We''re sending you coordinates to Nym pirate activity. Investigate and eliminate any criminals you encounter.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 17, 'level_boss', ' \\#pcontrast3 Storm Squadron Command: < \\#ff0000 Nym has sent a %TO after you. Stand by for coordinates... \\#pcontrast3 >'),
