('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 19, 'level_increase', 'We''ve detected that more of Nym''s ships have been sent into the sector.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 20, 'quest_destroy_d', 'Destroy any of Nym''s fighters that are in the areas. This will weaken Nym''s position and cause him to focus on local security rather then expanding his influence.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 21, 'quest_destroy_t', 'Destroy Nym''s Fighters'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 22, 'quest_location_d', 'Travel to the Lok system and attack Nym''s fighters there. You will receive a Nav waypoint to areas under the control of Nym.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 23, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_1a.stf', 24, 'targets_behind', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets coming in from behind! \\#pcontrast3 >'),
