('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 3, 'boss_title_0', 'Scavenger Fanatic'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 4, 'boss_title_1', 'Scrap Seeker Lord'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 5, 'boss_title_2', 'Death Star Cultist'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 6, 'boss_title_3', 'Space Maddened Scavenger'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 7, 'boss_title_4', 'Cult Master'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 8, 'boss_title_5', 'Scavenger Overseer'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 9, 'complete', 'Good job, pilot! You''ve managed to do significant damage to the scavengers. Return to base.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 10, 'dd_boss_taunt_1', 'I need new parts. Your ship will do nicely.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 11, 'dd_boss_taunt_2', 'This is my scrap field!'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 12, 'dd_boss_taunt_3', 'Your going to end up just another piece of debris.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 13, 'dd_boss_taunt_4', 'Die, Imperial scum!'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 14, 'dd_boss_taunt_5', 'Your ship will look very nice floating in space.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 15, 'duty_update', ' \\#pcontrast3 Storm Squadron Command:  < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 16, 'found_loc', 'We''re sending you coordinates to scavenger. Investigate and eliminate any criminals you encounter.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 17, 'level_boss', ' \\#pcontrast3 Storm Squadron Command: < \\#ff0000 A notorious %TO is in that area. You must eliminate him! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 18, 'level_boss_dead', 'Good work, the criminal is dead. We''re still picking up pirate activity, however. Stand by...'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 19, 'level_increase', 'We''ve detected more scavenger ships operating in this region...'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 20, 'quest_destroy_d', 'The members of the Debris Cult are violent and very protective of the salvage. They are sure to attack any ship that isn''t with them as soon as it is detected. Destroy as many as you can.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 21, 'quest_destroy_t', 'Destroy the Debris Cult Fighters'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 22, 'quest_location_d', 'Once you have arrived in the Yavin system, you will receive navigaiton waypoints to areas of high Debris Cult  concentration.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 23, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 24, 'targets_behind', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets coming in from behind! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 25, 'targets_detected', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets on incoming attack vector! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 26, 'taunt_1', 'You will become debris!'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 27, 'taunt_2', 'I am ready to join the field of debris! Are you?'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 28, 'taunt_3', 'Your ship is nothing more then scrap.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 29, 'taunt_4', 'You will become debris!'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 30, 'taunt_5', 'Your ship is nothing more then scrap.'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 31, 'title', 'Yavin System: Destroy the Debris Scavengers Duty'),
('string/en/spacequest/destroy_duty/lok_imperial_ss_2a.stf', 32, 'title_d', 'Travel to the Yavin System and destroy the Debris Cult members. The Empire''s salvage operation of the Death Star is being hampered by a number of factors, the Rebellion, the Hutts, and the fanatic Debris Cult . The Rebels and Hutts will be taken care of in their own time. For now it is important to elliminate as many of the Debris Cult members as you can.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 2, 'boss_detected', 'The Rebels have sent out one of their best pilots to deal with you. Be on careful look out.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 3, 'boss_title_1', 'Scout Pilot'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 4, 'boss_title_2', 'Wing Leader'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 5, 'boss_title_3', 'Flight Captain'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 6, 'boss_title_4', 'Squad Leader'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 7, 'boss_title_5', 'Ace'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 8, 'complete', 'The Rebels are in full retreat. They probably will not be back for a while. Nice work.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 9, 'dd_boss_taunt_1', 'Prepare to become space dust.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 10, 'dd_boss_taunt_2', 'No one ever has enough time and you just ran out.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 11, 'dd_boss_taunt_3', 'You are the one that had everyone worried?'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 12, 'dd_boss_taunt_4', 'I hope you like the taste of laser.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 13, 'dd_boss_taunt_5', 'I am sorry but I have to kill you now.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 14, 'duty_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 15, 'found_loc', 'Rebel activity detected at this location. Clear them out.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 16, 'level_boss', 'Reports indicate that the Rebels have sent out a %TO to deal with you. Be on the look out.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 17, 'level_boss_dead', 'Nice work. The Rebels have lost a valuable ally in their illegal activities.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 18, 'level_increase', 'Rebels in this area have been cleared out. Scanning system for other Rebel locations.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 19, 'quest_destroy_d', 'Once you have reached the navigation waypoint, you will be attacked by Rebel fighters. Destroy the fighters at this location until you receive a new navigation waypoint to your next battleground. If you destroy enough of these Rebel fighters, the Rebellion will send out better trained pilots in order to deal with you. Destroy duties can be quit at any time. Simply abort the mission or leave the system.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 20, 'quest_destroy_t', 'Travel to the Navigation Waypoint and Destroy the Rebel Fighters'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 21, 'quest_location_d', 'Travel to the Naboo system and move towards your first navigation waypoint to begin the destroy duty mission. When you destroy all attack waves at that waypoint you will receive a new navigation waypoint.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 22, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 23, 'targets_behind', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters incoming from the rear. Take evasive manuevers.>'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 24, 'targets_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected. Prepare to engage.>'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 25, 'taunt_1', 'Time to die, Imperial scum.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 26, 'taunt_2', 'You really should get a new line of work.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 27, 'taunt_3', 'Time to become space dust, Imperial dog.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 28, 'taunt_4', 'This is going to be uncomfortable for you.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 29, 'taunt_5', 'Well! Someone wasn''t hugged enough as a child.'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 30, 'title', 'Naboo System: Destroy the Rebel Fighters Duty'),
('string/en/spacequest/destroy_duty/naboo_imperial_6.stf', 31, 'title_d', 'Travel to the Naboo system and destroy the Rebel fighters. A destroy duty is a voluntary mission that you are able to quit at any time without repercussions. When you reach the Naboo system a navigation waypoint will be sent to you. Travel to this waypoint and you will be attacked by enemy fighters. Each time you destroy a wave of fighters a new wave will attack. Once you have destroyed all the attack waves at one waypoint, you will receive a new waypoint that you can fly to and continue destroying the enemy craft. A destroy duty will continue in this manner until you decide to stop.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 1, 'Quest Log Data', 'Text');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 2, 'boss_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Vessel with veteran insignias on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 3, 'boss_title_1', 'Experienced Rebel Pilot'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 4, 'boss_title_2', 'Veteran Rebel Pilot'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 5, 'boss_title_3', 'Master Rebel Pilot'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 6, 'boss_title_4', 'Rebel Squad Leader'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 7, 'boss_title_5', 'Rebel Ace'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 8, 'complete', 'Nice work, pilot. You have done a great service for the Inquisition and the Emperor this day. No more enemy fighters detected, return to base.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 9, 'dd_boss_taunt_1', 'They sent you to try to defeat me?'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 10, 'dd_boss_taunt_2', 'You are on the wrong side, friend.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 11, 'dd_boss_taunt_3', 'Prepare to become space dust.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 12, 'dd_boss_taunt_4', 'I would have thought they would have more respect for my skills.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 13, 'dd_boss_taunt_5', 'I will make this quick and painless.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 14, 'duty_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 15, 'found_loc', 'Area of heavy enemy fighter presence has been updated to your navigation computer. Proceed with the assault.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 16, 'level_boss', 'A %TO has been detected in your area. Proceed with caution.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 17, 'level_boss_dead', 'Now the Rebel scum know the true might of the Imperial Inquisition. Stand by for further orders.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 18, 'level_increase', 'Intelligence reports an increase in Rebel activities. This probably in direct response to your victories.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 19, 'quest_destroy_d', 'Travel to each of the given waypoints and destroy all attacking Rebels. If you cause enough trouble, they will send out their best pilots to deal with you.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 20, 'quest_destroy_t', 'Destroy the Rebel X-wing Fighters'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 21, 'quest_location_d', 'Move into Dantooine space. Intelligence has reports of areas of high Rebel activity and will supply those locations to you. Travel to each navigation waypoint and destroy all Rebels there.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 22, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 23, 'targets_behind', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy vessel detected 180 degrees from your current location.>'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 24, 'targets_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 25, 'taunt_1', 'You shouldn''t be here.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 26, 'taunt_2', 'Imperial dog, you will have to better then that.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 27, 'taunt_3', 'Big mistake!'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 28, 'taunt_4', 'You are going to pay for that!'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 29, 'taunt_5', 'I wouldn''t want to be you right now.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 30, 'title', 'Dantooine System: Destroy the X-wing Fighters Duty'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier2_destroyduty.stf', 31, 'title_d', 'Travel to the Dantooine system and destroy the Rebel X-wing fighters. High Command cannot allow the Rebellion to gain any sort of foothold in the Dantooine system. Hunt down and destroy all Rebel vessels in the region.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 2, 'boss_detected', 'Wave completed. Wave leader detected.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 3, 'boss_title_1', 'Coynite Harbringer'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 4, 'boss_title_2', 'Coynite Novahunter'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 5, 'boss_title_3', 'Coynite Ionstorm'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 6, 'boss_title_4', 'Coynite Lightstealer'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 7, 'boss_title_5', 'Coynite Starsweeper'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 8, 'complete', 'All waves destroyed. You have performed your duty well. Return to your superior officer for additional assignments.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 9, 'dd_boss_taunt_1', 'You dare challenge the might of Coyn?'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 10, 'dd_boss_taunt_2', 'That was your final mistake!'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 11, 'dd_boss_taunt_3', 'Don''t worry, this won''t take long.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 12, 'dd_boss_taunt_4', 'For Coyn! For Glory!'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 13, 'dd_boss_taunt_5', 'You shall have a noble death!'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 14, 'duty_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 15, 'found_loc', 'Located another area of high enemy activity.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 16, 'level_boss', '%TO has been eliminated. Nice work, pilot.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 17, 'level_boss_dead', 'Very nice work. Coynite''s respect their champions and you have gained respect in their eyes for defeating one of them.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 18, 'level_increase', 'Be alert! The Coynite Mercenaries are become more aggressive.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 19, 'quest_destroy_d', 'Destroy all Coynite ships you can find. If you do well enough the Coynite will send their best pilots after you.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 20, 'quest_destroy_t', 'Destroy the Coynite Fighters'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 21, 'quest_location_d', 'Travel to the Dathomir system and you will receive Nav waypoints to areas of high Coynite concentrations.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 22, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 23, 'targets_behind', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy ships detected. Incoming from the rear.>'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 24, 'targets_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Alert! Enemy ships engaging weapons and incoming at attack speeds.>'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 25, 'taunt_1', 'For Coyn! For Glory!'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 26, 'taunt_2', 'Go towards the light.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 27, 'taunt_3', 'Prepare to be embraced by death.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 28, 'taunt_4', 'You should not have done that.'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 29, 'taunt_5', 'Perhaps you wish to rethink your actions?'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 30, 'title', 'Dathomir System: Destroy the Coynite Fighters Duty'),
('string/en/spacequest/destroy_duty/naboo_imperial_tier4_1.stf', 31, 'title_d', 'Travel to the Dathomir system and destroy the Coynite fighters. The Coynite problem has begun to become out of hand. In order to protect Dathomir the Coynite numbers must be reduced.'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 2, 'boss_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Ay''Nat Warlord on attack vector, weapon systems armed. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 3, 'boss_title_1', 'Ay''Nat Warlord'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 4, 'boss_title_2', 'Veteran Ay''Nat Commander'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 5, 'boss_title_3', 'Blood-thirsty Ay''Nat Warlord'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 6, 'boss_title_4', 'Hateful Ay''Nat Commander'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 7, 'boss_title_5', 'Heartless Ay''Nat Warlord'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 8, 'complete', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Fantastic job pilot! We struck a blow to the Ay''Nat Legion that will take them a long time to recover from. Head back to base when ready. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 9, 'dd_boss_taunt_1', 'Foolish RSF puppet, you should have run while you had the chance!'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 10, 'dd_boss_taunt_2', 'Prepare to die...'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 11, 'dd_boss_taunt_3', 'Too bad you ran in to me so early in your career, as I mark it''s end!'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 12, 'dd_boss_taunt_4', 'Maybe I should fly using just one hand, to give you a chance?'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 13, 'dd_boss_taunt_5', 'Your pilot helmet will look good on my trophy rack RSF fool!'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 14, 'duty_update', '\\#pcontrast3 < %TO >'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 15, 'found_loc', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The next area of known Ay''Nat Legion activity has been uploaded to your nav computer, proceed when ready. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 16, 'level_boss', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The Ay''Nat Legion have sent one of their best pilots to take care of you, be careful! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 17, 'level_boss_dead', '\\#pcontrast3 RSF Command: < \\#pcontrast1 That one has been a dread ever since he came to this sector, great work pilot! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 18, 'level_increase', 'Sensors through out the system show increased Ay''Nat Pirate activity in response to our attacks.'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 19, 'quest_destroy_d', 'Proceed to this point and engage Ay''Nat craft'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 20, 'quest_destroy_t', 'Destroy Waypoint'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 21, 'quest_location_d', 'Areas of Ay''Nat activity throughout the Naboo System'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 22, 'quest_location_t', 'Naboo System'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 23, 'targets_behind', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_privateer_11.stf', 24, 'targets_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Vessels fitting hunted ship profile on attack vector, weapon systems armed. \\#pcontrast3 >'),
