('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 2, 'boss_title_0', 'TIE Combat Trainer'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 3, 'boss_title_1', 'TIE Combat Trainer'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 4, 'boss_title_2', 'TIE Combat Ace'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 5, 'boss_title_3', 'TIE Obsidian Squad Leader'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 6, 'boss_title_4', 'TIE Black Ops Commander'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 7, 'boss_title_5', 'TIE (Unknown) Ace'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 8, 'complete', 'Excellent work, Pilot! The Imperial presence in this sector has been soundly beaten. Return to base!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 9, 'dd_boss_taunt_1', 'You killed my men. Now you''re mine!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 10, 'dd_boss_taunt_2', 'If you cut your engines, I promise not to harm you.'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 11, 'dd_boss_taunt_3', 'I''m going to enjoy spacing you.'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 12, 'dd_boss_taunt_4', 'A thousand creds to the man who takes him out!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 13, 'dd_boss_taunt_5', 'I am the Grim Reaper Rebel, you will not leave this place alive!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 14, 'duty_update', ' \\#pcontrast3 Alliance HQ:  < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 15, 'found_loc', 'We are uploading coordinates of suspected Imperial ambushes. Investigate and eliminate all hostiles.'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 16, 'level_boss', ' \\#pcontrast3 Alliance HQ: < \\#ff0000 The Imperials are sending a highly trained %TO after you. Stand by for coordinates... \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 17, 'level_boss_dead', 'Good work, the commander has been destroyed. We''re still picking up Imperial activity, however. Stand by...'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 18, 'level_increase', 'We''ve detected that more TIE ships have been sent into the sector.'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 19, 'quest_destroy_d', 'Be aware that the more successful attacks you perform, the more resistance you will face as the Empire steps up their alert level.'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 20, 'quest_destroy_t', 'Destroy TIE fighters at each navigation point.'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 21, 'quest_location_d', 'Alliance HQ will provide waypoints to potential TIE fighter ambushes. Fly to each waypoint and eliminate all hostile fighters that enter the area. When you have cleared an area, Alliance HQ will upload a new wayppoint. Continue to beat back the enemy!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 22, 'quest_location_t', 'Naboo system.'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 23, 'targets_behind', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets coming in from behind! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 24, 'targets_detected', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets on incoming attack vector! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 25, 'taunt_1', 'You''re heading for the Imperial prisons, Rebel scum!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 26, 'taunt_2', 'The might of the Empire is unstoppable!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 27, 'taunt_3', 'It was a mistake to come here Rebel fool!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 28, 'taunt_4', 'Fry him boys!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 29, 'taunt_5', 'Your little uproar ends here Rebel scum!'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 30, 'title', 'Naboo system: Duty mission: Break up TIE ambushes'),
('string/en/spacequest/destroy_duty/naboo_rebel_6.stf', 31, 'title_d', 'Break up TIE ambushes. These missions have been outlined to give you some much needed experience in space combat, you can stop when you feel that you have learned enough.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 1, 'boss_detected', 'Our reconnaissance ship has spooted a Imperial Inquisitor coming to investigate. Be careful.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 2, 'boss_title_1', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 3, 'boss_title_2', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 4, 'boss_title_3', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 5, 'boss_title_4', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 6, 'boss_title_5', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 7, 'complete', 'Amazing job out there pilot! Return to base for some well earned rest.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 8, 'dd_boss_taunt_1', 'It''s been a long time since I had an actual challenge.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 9, 'dd_boss_taunt_2', 'Didn''t expect the Inquisition, did you?'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 10, 'dd_boss_taunt_3', 'Your first mistake was coming here. Your second mistake is not fleeing. You only get two mistakes.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 11, 'dd_boss_taunt_4', 'Repent sinner!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 12, 'dd_boss_taunt_5', 'You dare anger the Inquisition?!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 13, 'duty_update', 'Vortex Fleet Command: < %TO >'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 14, 'found_loc', 'More of the Inquisitions training squads have been located in this area, proceed.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 15, 'level_boss', 'One of the Imperial Inquisitors have been spotted in this area, stay sharp!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 16, 'level_boss_dead', 'Fantastic job pilot! The Inquisition will be outraged!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 17, 'level_increase', 'We''re getting reports that the Empire is ramping up their search for you, prepare to get busy.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 18, 'quest_destroy_d', 'A patrol of Inquisition trainees have been spotted at these coordinates. Eliminate any enemy forces found.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 19, 'quest_destroy_t', 'Targets of elimination.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 20, 'quest_location_d', 'The Dantooine system shouldn''t be that dangerous for a pilot of your skill but the targets of your attack is almost fanatical in their devotion and will to prove themselves to the Inquisition.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 21, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 24, 'taunt_1', 'Destroy the Rebel men!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 25, 'taunt_2', 'You will pay for your crimes!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 26, 'taunt_3', 'Your pathetic attacks end here Rebel!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 27, 'taunt_4', 'After I crush you, I will become one of the Inquisitions elite pilots!'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 28, 'taunt_5', 'Resistance is futile.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 29, 'title', 'Dantooine system: Duty mission: Attack the Inquisitions candidates.'),
('string/en/spacequest/destroy_duty/naboo_rebel_tier4_1.stf', 30, 'title_d', 'To soften up the Inquisitions fighter force and send a message to them that we mean business, you are ordered to attack a number of their normal fighter patrols. Normal means that they are not yet part of the Inquisition as full time pilots in their service but rather they are regular navy pilots used for grunt work, trying to prove their worth to the men in black. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 1, 'boss_detected', 'The Rebel Ace is inbound, prepare yourself pilot!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 2, 'boss_title_1', 'Infio Argon'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 3, 'boss_title_2', 'Poew Scar'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 4, 'boss_title_3', 'Uowas Irgon'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 5, 'boss_title_4', 'Walfer Whitehand'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 6, 'boss_title_5', 'General Boawa'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 7, 'complete', 'Incredible! You should get some rest pilot, you''ve gone well beyond your call of duty today!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 8, 'dd_boss_taunt_1', 'I''ve come to claim revenge!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 9, 'dd_boss_taunt_2', 'Imperial scum, prepare to pay for your crimes!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 10, 'dd_boss_taunt_3', 'I will destroy you, mark my words!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 11, 'dd_boss_taunt_4', 'You should never have come here Imperial!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 12, 'dd_boss_taunt_5', 'You will never kill another pilot of the Alliance again!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 13, 'duty_update', 'Imperial Command: < %TO >'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 14, 'found_loc', 'Locked in a target area, transfering waypoint.'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 15, 'level_boss', 'We see a familiar ship signature on our sensors. %TO, one of the Rebel Ace pilots are coming your way!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 16, 'level_boss_dead', 'Excellent, the Rebel fools will miss that one!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 17, 'level_increase', 'The Rebel and Nym scum are increasing their efforts in tracking you down, be ready.'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 18, 'quest_destroy_d', 'We will provide you with locations of Rebel and Nym ships. Follow the waypoints and deliver Imperial justice!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 19, 'quest_destroy_t', 'Terminate targets of opportunity.'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 20, 'quest_location_d', 'This is enemy territory! Stay sharp and be careful out there pilot, an Imperial ship in this zone is like having a bullseye on your back.'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 21, 'quest_location_t', 'Lok system.'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 24, 'taunt_1', 'Imperial hound, prepare to die!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 25, 'taunt_2', 'Lackey of the false Emperor, you will fall!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 26, 'taunt_3', 'Never again will you take another mans life!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 27, 'taunt_4', 'We will stop your oppression!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 28, 'taunt_5', 'You can''t defeat us all!'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 29, 'title', 'Lok system: Duty mission: Rebels can''t hide anywhere.'),
('string/en/spacequest/destroy_duty/naboo_station_imperial_destroy_duty_tier2_1.stf', 30, 'title_d', 'The Rebels has been hiding under the protection of Nym in the Lok system for too long. Nym is quite powerful and we don''t want to invoke his full rage but we have to show the Rebels that they are not safe anywhere. By sending you in alone, we should be able to give that message without provoking Nym too much. He''s a proud man that should see it as a honorable challenge by a good pilot.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 2, 'boss_detected', 'Wave completed. Wave leader detected.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 3, 'boss_title_1', 'Rebel Veteran'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 4, 'boss_title_2', 'Rebel Raid Seeker'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 5, 'boss_title_3', 'Rebel Elite'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 6, 'boss_title_4', 'Rebel Raid Leader'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 7, 'boss_title_5', 'Rebel Captain'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 8, 'complete', 'All waves destroyed. You have performed your duty well. Return to your superior officer for additional assignments.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 9, 'dd_boss_taunt_1', 'You dare challenge the might of the Alliance?'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 10, 'dd_boss_taunt_2', 'That was your final mistake!'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 11, 'dd_boss_taunt_3', 'Don''t worry, this won''t take long.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 12, 'dd_boss_taunt_4', 'For the Rebellion! For the Alliance!'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 13, 'dd_boss_taunt_5', 'You shall have a noble death!'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 14, 'duty_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 15, 'found_loc', 'Located another area of high enemy activity.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 16, 'level_boss', '%TO has been eliminated. Nice work, pilot.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 17, 'level_boss_dead', 'Very nice work. That should slow Rebel activity in this area.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 18, 'level_increase', 'Be alert! The Rebel pilots are become more aggressive.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 19, 'quest_destroy_d', 'Destroy all Rebel ships you can find. If you do well enough the Rebels will send their best pilots after you.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 20, 'quest_destroy_t', 'Destroy the Rebel Fighters'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 21, 'quest_location_d', 'Travel to the Naboo system if you are not already in the Naboo System.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 22, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 23, 'targets_behind', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy ships detected. Incoming from the rear.>'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 24, 'targets_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Alert! Enemy ships engaging weapons and incoming at attack speeds.>'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 25, 'taunt_1', 'For the Rebellion!'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 26, 'taunt_2', 'Go towards the light.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 27, 'taunt_3', 'Prepare to be embraced by death.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 28, 'taunt_4', 'You should not have done that.'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 29, 'taunt_5', 'Perhaps you wish to rethink your actions?'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 30, 'title', 'Naboo System: Destroy the Rebel Fighters Duty'),
('string/en/spacequest/destroy_duty/rori_station_imp_destroy_duty_tier3.stf', 31, 'title_d', 'Rebel activity in this area has increased, and they often seem to know too much about Imperial plans. Remain here in the Naboo System and destroy the Rebel fighters.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 1, 'boss_detected', 'Our reconnaissance ship has spotted an Imperial Inquisitor heading this way. Be careful.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 2, 'boss_title_1', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 3, 'boss_title_2', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 4, 'boss_title_3', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 5, 'boss_title_4', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 6, 'boss_title_5', 'Imperial Inquisitor'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 7, 'complete', 'Amazing job out there pilot! Return to base for some well earned rest.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 8, 'dd_boss_taunt_1', 'It''s been a long time since I had an actual challenge.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 9, 'dd_boss_taunt_2', 'Didn''t expect the Inquisition, did you?'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 10, 'dd_boss_taunt_3', 'Your first mistake was coming here. Your second mistake is not fleeing. You only get two mistakes.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 11, 'dd_boss_taunt_4', 'Flee fool!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 12, 'dd_boss_taunt_5', 'You dare anger the Inquisition?!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 13, 'duty_update', 'Station Command: < %TO >'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 14, 'found_loc', 'More of the Inquisition squads have been located in this area, proceed.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 15, 'level_boss', 'One of the Imperial Inquisitors have been spotted in this area, stay sharp!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 16, 'level_boss_dead', 'Fantastic job pilot! That should give the Inquisition something else to think about for a while!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 17, 'level_increase', 'We''re getting reports that the Empire is ramping up their search for you, prepare to get busy.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 18, 'quest_destroy_d', 'Eliminate Imperial forces.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 19, 'quest_destroy_t', 'Targets of elimination.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 20, 'quest_location_d', 'Cause a distraction by attacking Imperial fighters in the Naboo system.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 21, 'quest_location_t', 'Naboo system.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 24, 'taunt_1', 'I must destroy you!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 25, 'taunt_2', 'You will pay for your crimes!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 26, 'taunt_3', 'Your pathetic attacks end here Rebel!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 27, 'taunt_4', 'After I crush you, I will become one of the Inquisitions elite pilots!'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 28, 'taunt_5', 'Resistance is futile.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 29, 'title', 'Naboo system: Duty mission: Disrupt Imperial Investigations.'),
('string/en/spacequest/destroy_duty/rori_station_reb_destroy_duty_tier3.stf', 30, 'title_d', 'The Rori Station would rather the Empire had other problems to focus on rather than pay any attention to their station. Distract the Empire by attacking Imperial ships in the Naboo System.'),
