INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 2, 'boss_title_1', 'Raider Commander'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 3, 'boss_title_2', 'Raider Ace'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 4, 'boss_title_3', 'Raider Leader'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 5, 'boss_title_4', 'Raider Brigand'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 6, 'boss_title_5', 'Raider Rogue'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 7, 'complete', 'Good work, pilot. That should keep the pirates off of our backs for a little while.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 8, 'dd_boss_taunt_1', 'You will never stop us from getting what we want.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 9, 'dd_boss_taunt_2', 'You shouldn''t have come out here.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 10, 'dd_boss_taunt_3', 'Big mistake, pal! You don''t mess with us.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 11, 'dd_boss_taunt_4', 'I am going to take a great deal of pleasure in doing this.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 12, 'dd_boss_taunt_5', 'Just you? Maybe you should have brought more friends.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 13, 'duty_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 14, 'found_loc', 'We have sent you another location where the pirates are known to hang out.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 15, 'level_boss', 'We are picking up signals of another ship. I think it is a %TO. Be careful.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 16, 'level_boss_dead', 'Excellent work. Without their leaders the pirates will be crippled.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 17, 'level_increase', 'Tighten that belt, pilot. Things are just going to get rougher from here on.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 18, 'quest_destroy_d', 'Being highly territorial the pirates will attack anyone moving into their area. Once you arrive, expect to be attacked. Destroy all fighters that attack you.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 19, 'quest_destroy_t', 'Destroy the Attacking Fighters'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 20, 'quest_location_d', 'The pirates are stationed in several areas around Dantooine. Since there is no law enforcement in the system, the pirates do not even make an attempt to hide so they are easy enough to track.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 21, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 22, 'targets_behind', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 23, 'targets_detected', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 24, 'taunt_1', 'Prepare to become space dust.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 25, 'taunt_2', 'I will enjoy looting your corpse.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 26, 'taunt_3', 'I don''t do this for fun...it is just business.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 27, 'taunt_4', 'You should rethink your career. Perhaps moisture farmer is more your speed.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 28, 'taunt_5', 'No one does that to me and gets away with it.'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 29, 'title', 'Dantooine System: Destroy the Dantooine Raiders'),
('string/en/spacequest/destroy_duty/stn_dantooine_owner_all_raiderdestroy_tier2_1.stf', 30, 'title_d', 'Dantooine Raiders have been attacking the supply freighters heading to the Dantooine station. This is causing heavy shortages in supplies for the station. The owner wants you to reduce the numbers of raiders in the system.'),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 1, 'boss_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 A Zynt''aia Guardian in an advanced fighter has been detected. \\#pcontrast3 >'),
