('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 23, 'targets_detected', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 24, 'taunt_1', 'At least your death will be swift.'),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 25, 'taunt_2', 'You had this coming.'),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 26, 'taunt_3', 'I will add your space junk to my collection.'),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 27, 'taunt_4', ''),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 28, 'taunt_5', ''),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 29, 'title', 'Endor System: Duty: Destroy the Zynt''aia Spice Guardians'),
('string/en/spacequest/destroy_duty/stn_endor_irs_imp_tier4_1.stf', 30, 'title_d', 'The Zynt''aia are causing problems outside of the Declorian Territory.  Hunt them down and destroy them.'),
