('string/en/spacequest/destroy_duty/stn_lok_nym_reb_tier2_1.stf', 28, 'taunt_5', ''),
('string/en/spacequest/destroy_duty/stn_lok_nym_reb_tier2_1.stf', 29, 'title', 'Lok System: Duty: Destroy the Storm Squadron Fighters'),
('string/en/spacequest/destroy_duty/stn_lok_nym_reb_tier2_1.stf', 30, 'title_d', 'Imperial Storm Squadron fighters have infested the Lok System.  Destroy them to preserve our pirate rights.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 1, 'boss_detected', 'We have picked up a vessel signature of one of their priests. He is heading your way.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 2, 'boss_title_1', 'Debris Zealot'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 3, 'boss_title_2', 'Debris Acoloyte'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 4, 'boss_title_3', 'Debris Worshipper'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 5, 'boss_title_4', 'Debris Holy Man'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 6, 'boss_title_5', 'Exaulted One'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 7, 'complete', 'Good work out there, pilot. That will really cut down on the number of crazies flying around this system. Report back to the station.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 8, 'dd_boss_taunt_1', 'And it is written that I shall destroy you.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 9, 'dd_boss_taunt_2', 'You should have joined with us my child. Now you will become one with the debris.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 10, 'dd_boss_taunt_3', 'I find your lack of faith to be most displeasing.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 11, 'dd_boss_taunt_4', 'I will show you the way to ultimate peace.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 12, 'dd_boss_taunt_5', 'Close your eyes, my child. I shall free you of your mortal coil.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 13, 'duty_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 14, 'found_loc', 'We have found another location where the cultists are gathering. Break them up.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 15, 'level_boss', 'Be on the look out. The cultists have sent a %TO after you. I have heard they are bad customers.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 16, 'level_boss_dead', 'Yes! Without their leaders the cultists will have a harder time recruiting new members. Keep it up.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 17, 'level_increase', 'Watch yourself. The cultists know what you are up to and will do everything they can to stop you.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 18, 'quest_destroy_d', 'Destroy any of the Debris Cultists that decide to attack you.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 19, 'quest_destroy_t', 'Destroy the Cultists'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 20, 'quest_location_d', 'Cult members are all over the system causing trouble for whoever they come across. Hot spots of cult activity will be sent to your nav computer.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 21, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 22, 'targets_behind', '\\#pcontrast1Tactical Computer: \\#pcontrast3< Enemy fighters detected. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 23, 'targets_detected', '\\#pcontrast1Tactical Computer: \\#pcontrast3< Enemy fighters detected. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 24, 'taunt_1', 'And he said unto me...destroy the disbelievers.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 25, 'taunt_2', 'Faith in the great fireball is the only true faith.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 26, 'taunt_3', 'Join us...join us.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 27, 'taunt_4', 'I have some material I would have liked to give you, but I am afraid I must kill you instead.'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 28, 'taunt_5', 'Die infidel!'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 29, 'title', 'Yavin System: Deathstar Debris Cult Destroy Duty'),
('string/en/spacequest/destroy_duty/stn_yavin4_company_all_debrisdestroy_tier2_1.stf', 30, 'title_d', 'The Debris Cultist have gotten it into their heads that the Yavin 4 Mining Company is in charge of the salvage operation underway in the system. The company wants to have their numbers reduced in order to increase the security of their operations.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 2, 'boss_detected', 'Warning! Enemy commander detected on attack vector!'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 3, 'boss_title_0', 'Scruffy Pirate Leader'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 4, 'boss_title_1', 'Pirate Ace'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 5, 'boss_title_2', 'Master Pirate Leader'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 6, 'boss_title_3', 'Pirate Lord'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 7, 'boss_title_4', 'Robber Baron'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 8, 'boss_title_5', 'Master Gunner'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 9, 'complete', 'Good job, pilot! You''ve managed to suppress pirate activity in the entire sector. Return to base.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 10, 'dd_boss_taunt_1', 'You killed my men. Now you''re mine!'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 11, 'dd_boss_taunt_2', 'If you cut your engines, I promise not to harm you.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 12, 'dd_boss_taunt_3', 'I''m going to enjoy spacing you.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 13, 'dd_boss_taunt_4', 'A thousand creds to the man who takes him out!'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 14, 'dd_boss_taunt_5', 'Your death will bring me great reward.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 15, 'duty_update', ' \\#pcontrast3 Imperial Command:  < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 16, 'found_loc', 'We''re sending you coordinates to Commerce Raider activity. Investigate and eliminate any criminals you encounter.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 17, 'level_boss', ' \\#pcontrast3 Imperial Command: < \\#ff0000 The pirates are sending a highly trained %TO after you. Stand by for coordinates... \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 18, 'level_boss_dead', 'Good work, the commander is dead. We''re still picking up pirate activity, however. Stand by...'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 19, 'level_increase', 'We''ve detected that more raider ships have been sent into the sector.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 20, 'quest_destroy_d', 'Once you have reached the navigation waypoint, you will be attacked by Commerce Raiders. Destroy the Commerce Raiders at this location until you receive a new navigation waypoint to your next battleground. If you destroy enough of these Commerce Raiders, the pirates will send out better trained pilots in order to deal with you. Destroy duties can be quit at any time. Simply abort the mission or leave the system.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 21, 'quest_destroy_t', 'Travel to the Navigation Waypoint and Destroy the Commerce Raiders'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 22, 'quest_location_d', 'Travel to the Tatooine system and move towards your first navigation waypoint to begin the destroy duty mission. When you destroy all attack waves at that waypoint you will receive a new navigation waypoint.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 23, 'quest_location_t', 'Travel to the Tatooine System'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 24, 'targets_behind', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets coming in from behind! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 25, 'targets_detected', ' \\#pcontrast3 Tactical Computer:  < \\#pcontrast1 Enemy targets on incoming attack vector! \\#pcontrast3 >'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 26, 'taunt_1', 'Imperials have no business in the Outer Rim.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 27, 'taunt_2', 'If you think that you can drive us off, you are mistaken.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 28, 'taunt_3', 'The Empire does not conrol Tatooine space and never will.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 29, 'taunt_4', 'Imperials have no business in the Outer Rim.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 30, 'taunt_5', 'The Empire does not conrol Tatooine space and never will.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 31, 'title', 'Tatooine System: Destroy the Commerce Raiders Duty'),
('string/en/spacequest/destroy_duty/tatooine_imperial_6.stf', 32, 'title_d', 'Travel to the Tatooine system and attack the Commerce Raiders. A destroy duty is a voluntary mission that you are able to quit at any time without repercussions. When you reach the Tatooine system a navigation waypoint will be sent to you. Travel to this waypoint and you will be attacked by enemy fighters. Each time you destroy a wave of fighters a new wave will attack. Once you have destroyed all the attack waves at one waypoint, you will receive a new waypoint that you can fly to and continue destroying the enemy craft. A destroy duty will continue in this manner until you decide to stop.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 2, 'boss_detected', 'Be on the look out. A Red Skull Heavy Fighter has been detected in your region.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 3, 'boss_title_1', 'Veteran'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 4, 'boss_title_2', 'Master Pilot'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 5, 'boss_title_3', 'Elite'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 6, 'boss_title_4', 'Red Skull Raider Leader'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 7, 'boss_title_5', 'Red Skull Captain'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 8, 'complete', 'Nice flying out there, pilot. You are really turning into an elite pilot. Return to your commander and report your success.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 9, 'dd_boss_taunt_1', 'Prepare to be left to the mercys of cold, empty space.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 10, 'dd_boss_taunt_2', 'You are the pilot that they sent against me? HA!'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 11, 'dd_boss_taunt_3', 'You had better be gone before I taunt you a second time.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 12, 'dd_boss_taunt_4', 'Time to teach this Imperial whelp who really rules Endor.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 13, 'dd_boss_taunt_5', 'You have caused enough trouble. It is time for me to end this.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 14, 'duty_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 15, 'found_loc', 'We have located more pirates that need to be driven out of this system. Travel to the location provided to your nav computer and eliminate the Red Skulls.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 16, 'level_boss', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%TO has been eliminated. The Red Skulls in this region are leaderless.>'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 17, 'level_boss_dead', 'Nice work but remember there is still more work to be done. Stand by for location of next target.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 18, 'level_increase', 'You have done well, but that was just the beginning. The better pilots are still to come.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 19, 'quest_d', 'The Red Skulls have set up points of operation in the Endor sector. Part of running the security detail in this sector involves clearing out all opposing forces. The Red Skulls need to be driven out of the sector in order for the Empire to continue it activities in this sector in secrecy.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 20, 'quest_destroy_d', 'The Red Skulls are not going to leave if we simply ask them nicely. Therefore, it is nessecary to use lethal force in order to convince them to vacate the system. If they choose to stay even after our show of strength then they will simply have to be terminated.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 21, 'quest_destroy_t', 'Destroying the Red Skulls'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 22, 'quest_location_d', 'The Red Skulls have set up operation in the Endor system. It is nessecary for you to travel to that system in order to drive them out.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 23, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 24, 'quest_t', 'Crushing the Red Skulls'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 25, 'targets_behind', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Alert! Enemy fighters incoming from behind at high speeds.>'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 26, 'targets_detected', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters incoming at attack speeds. Prepare to engage.>'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 27, 'taunt_1', 'Foolish Imperial! You are no match for me.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 28, 'taunt_2', 'Nice move, but you will have to do much better in order to win.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 29, 'taunt_3', 'Time to take out the trash...by the way, you are the trash.'),
('string/en/spacequest/destroy_duty/tatooine_imperial_tier4_destroyduty_1.stf', 30, 'taunt_4', 'You should have stayed at home hiding under your mother''s skirt.'),
