('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 5, 'boss_title_4', 'Imperial Ace Pilot'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 6, 'boss_title_5', 'Imperial Ace Pilot'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 7, 'complete', 'Amazing job out there pilot! Return to base for some well earned rest.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 8, 'dd_boss_taunt_1', 'It''s been a long time since I had an actual challenge.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 9, 'dd_boss_taunt_2', 'Rebel worm, you should have stayed in your hole.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 10, 'dd_boss_taunt_3', 'Your first mistake was coming here. Your second mistake is not fleeing. You only get two mistakes.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 11, 'dd_boss_taunt_4', 'My skills are superior in every way.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 12, 'dd_boss_taunt_5', 'This ship, my skills, I can''t be defeated!'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 13, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 14, 'found_loc', 'More Imperial patrols have been spotted in this area, proceed when ready.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 15, 'level_boss', 'One of the Empires Ace pilots is attacking; he''s piloting one of their experimental fighters. Good luck pilot!'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 16, 'level_boss_dead', 'I''m impressed! The Empire will speak your name in fear pilot.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 17, 'level_increase', 'Our spy ships report that the Empire is increasing their presence in the sector to try and stop our attacks.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 18, 'quest_destroy_d', 'We will keep updating your nav computer with new areas of possible targets. Keep going until you have exhausted yourself, your ship or until you feel you have enough experience to continue your training.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 19, 'quest_destroy_t', 'Engage and destroy.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 20, 'quest_location_d', 'The Yavin system is fiercely defended by the Empire and the debris field particularly so. Be prepared for a lot of resistance.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 21, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 24, 'taunt_1', 'Destroy the Rebel men!'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 25, 'taunt_2', 'You will pay for your crimes!'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 26, 'taunt_3', 'Your pathetic attacks end here Rebel!'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 27, 'taunt_4', 'We''re here to deliver justice!'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 28, 'taunt_5', 'Resistance is futile.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 29, 'title', 'Yavin system: Duty mission: Attack Imperial patrols.'),
('string/en/spacequest/destroy_duty/tatooine_rebel_tier4_1.stf', 30, 'title_d', 'We have several of our smugglers ordered to steal parts of the Death Star debris in the Yavin system to see if they can find anything useful. Unfortunately the Empire has stepped up their patrols of the debris field to the point where it''s almost impossible to sneak in. Assist our smugglers in the system by attacking Imperial patrols near the debris field.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 1, 'boss_detected', 'Tactical Computer: < Vessel with veteran insignias on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 2, 'boss_title_1', 'Experienced TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 3, 'boss_title_2', 'Grim TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 4, 'boss_title_3', 'Ace TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 5, 'boss_title_4', 'Battle Scarred TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 6, 'boss_title_5', 'Master TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 7, 'complete', 'Fantastic job pilot! We show no more Imperial patrols in this area, they must have withdrawn!'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 8, 'dd_boss_taunt_1', 'Foolish Rebel, you actually think you can match my skill?'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 9, 'dd_boss_taunt_2', 'I''m superior in every way, you should never have come here.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 10, 'dd_boss_taunt_3', 'Play time is over Rebel, you will not make it out of here alive.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 11, 'dd_boss_taunt_4', 'You''re the best the Rebels have? Pathetic!'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 12, 'dd_boss_taunt_5', 'I''m your worst nightmare, Rebel fool!'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 13, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 14, 'found_loc', 'Proceed to intercept coordinates of the next Imperial Patrol.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 15, 'level_boss', 'Rebel Command: < The Empire has sent an %TO to take you out. Be careful out there! >'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 16, 'level_boss_dead', 'Amazing! That pilot has been a menace to this entire sector for as long as I can remember!'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 17, 'level_increase', 'Scans show increased imperial activity in this area, they are looking for you pilot.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 18, 'quest_destroy_d', 'Travel to these coordinates and eliminate any Imperial presence. For the Alliance!'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 19, 'quest_destroy_t', 'Reported Imperial activity.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 20, 'quest_location_d', 'Travel to the Lok system to hunt Imperial patrols.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 21, 'quest_location_t', 'Lok system.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 24, 'taunt_1', 'Your resistance is futile, the Empire is everywhere!'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 25, 'taunt_2', 'Why do you Rebels even bother? You can''t win.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 26, 'taunt_3', 'Why are you doing this Rebel? The Empire is what''s best for the galaxy.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 27, 'taunt_4', 'Cut your engines Rebel, your trial will be fair. There''s no point resisting.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 28, 'taunt_5', 'You should have run when you had the chance Rebel!'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 29, 'title', 'Lok system: Duty mission: Hunt Imperial patrols.'),
('string/en/spacequest/destroy_duty/viopa_rebel_6.stf', 30, 'title_d', 'You are doing a favor to Nym on behalf of the Alliance by attacking Imperial presence in the Lok system. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 1, 'boss_detected', 'Tactical Computer: < Vessel with veteran insignias on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 2, 'boss_title_1', 'Experienced TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 3, 'boss_title_2', 'Grim TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 4, 'boss_title_3', 'Ace TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 5, 'boss_title_4', 'Battle Scarred TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 6, 'boss_title_5', 'Master TIE Interceptor pilot'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 7, 'complete', 'Fantastic! The pilotes of the Empire are speaking your name in fear now my friend.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 8, 'dd_boss_taunt_1', 'Foolish Rebel, you actually think you can match my skill?'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 9, 'dd_boss_taunt_2', 'I''m superior in every way, you should never have come here.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 10, 'dd_boss_taunt_3', 'You will be the next kill notch on my cockpit, puny Rebel!'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 11, 'dd_boss_taunt_4', 'I hope you have a escape pod on that piece of trash Rebel.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 12, 'dd_boss_taunt_5', 'Imperial justice incoming, say good night.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 13, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 14, 'found_loc', 'Proceed to intercept coordinates of the next Imperial Patrol.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 15, 'level_boss', 'Rebel Command: < The Empire has sent an %TO to take you out. Be careful out there! >'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 16, 'level_boss_dead', 'I can''t believe it. Didn''t think anyone would win a dog fight against that monster...'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 17, 'level_increase', 'The Empire are increasing their activity in this sector to try and hunt you down.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 18, 'quest_destroy_d', 'An Imperial patrol has been spotted at these coordinates. Intercept and destroy it.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 19, 'quest_destroy_t', 'Coordinates of Imperial patrol.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 20, 'quest_location_d', 'Travel to the Dantooine system to help the Rebel Alliance in their war on the Empire.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 21, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 24, 'taunt_1', 'The might of the Empire is unstoppable!'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 25, 'taunt_2', 'Foolish Rebel! We will hunt you all down, like the rats you are!'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 26, 'taunt_3', 'Why are you doing this Rebel? The Empire is what''s best for the galaxy.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 27, 'taunt_4', 'Cut your engines Rebel, your trial will be fair. There''s no point resisting.'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 28, 'taunt_5', 'I would run if I were you, Rebel scum!'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 29, 'title', 'Dantooine system: Duty mission: Attack Imperial Patrols'),
('string/en/spacequest/destroy_duty/vortex_mission_6.stf', 30, 'title_d', 'You are ordered to assist in the attacks on Imperial patrols. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 1, 'boss_detected', 'Rebel Command: < Warning! Enemy commander detected on attack vector! >'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 2, 'boss_title_1', 'Hutt Gunship'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 3, 'boss_title_2', 'Hutt Black Star Gunship'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 4, 'boss_title_3', 'Hutt Stealth Gunship'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 5, 'boss_title_4', 'Hutt Obsidian Gunship'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 6, 'boss_title_5', 'Hutt Dark Gunship'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 7, 'complete', 'Excellent work, Pilot! The Hutt presence in this sector has been soundly beaten. Return to base!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 8, 'dd_boss_taunt_1', 'You killed my men. Now you''re mine!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 9, 'dd_boss_taunt_2', 'If you cut your engines, I promise not to harm you.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 10, 'dd_boss_taunt_3', 'I''m going to enjoy spacing you.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 11, 'dd_boss_taunt_4', 'A thousand creds to the man who takes him out!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 12, 'dd_boss_taunt_5', 'Your silly crusade ends here Rebel!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 13, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 14, 'found_loc', 'We are uploading coordinates of suspected Hutt ambushes. Investigate and eliminate all hostiles immedaitely.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 15, 'level_boss', 'Rebel Command: < Stay alert, pilot! Hutt Gunships coming your way... >'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 16, 'level_boss_dead', 'Good work, the gunship has been destroyed. We''re still picking up Hutt activity, however. Stand by...'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 17, 'level_increase', 'We''ve detected that more Hutt ships have been sent into the sector.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 18, 'quest_destroy_d', 'Proceed to these coordinates and terminate any Hutt pirates found.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 19, 'quest_destroy_t', 'Location of Hutt activity.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 20, 'quest_location_d', 'Travel to the Yavin 4 system for further orders.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 21, 'quest_location_t', 'Yavin 4 system.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 22, 'targets_behind', 'Tactical Computer: < Be aware, vessels trying to target this ship with their weapon systems. Attack originating direction 180 degrees. >'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 23, 'targets_detected', 'Tactical Computer: < Vessels fitting hunted ship profile on attack vector, weapon systems armed. >'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 24, 'taunt_1', 'Finally some action!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 25, 'taunt_2', 'You were foolish coming here Rebel, you''re no match for us!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 26, 'taunt_3', 'The hunter becomes the hunted!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 27, 'taunt_4', 'I want his helmet guys!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 28, 'taunt_5', 'You can run but you can''t hide little Rebel!'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 29, 'title', 'Yavin system: Duty mission: Cripple Hutt activity in sector.'),
('string/en/spacequest/destroy_duty/yavin_rebel_9.stf', 30, 'title_d', 'Hutt ships have been an increasing threat in the Yavin system. Show them not to mess with the Rebel Alliance.'),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 2, 'complete', 'Good job pilot. Return to base for your next assignment by travelling to the Talus Space Station, target it by pressing "C", and using /comm.'),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 3, 'duty_update', 'Imperial Command:'),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 4, 'found_loc', 'Head to new coordinates uploaded to your nav computer.'),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 5, 'quest_update', 'Imperial Command:'),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 6, 'split_quest_alert', 'This isn''t the first time that new pilots have failed their first time out. We expect you to try again until you can get it right. Sending you a new navigation location to another patrol route.'),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 7, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 8, 'title', 'Corellia System: Destroy the Rebel X-wing Fighters'),
('string/en/spacequest/destroy_surpriseattack/corellia_imperial_1.stf', 9, 'title_d', 'Destroy the Rebel ambush. Your patrol route has been successful and, as planned, the Rebels have attacked you. You must destroy the X-wing fighters that have attacked you. Once you have completed this task return to the Talus space station, target it by pressing the ''C'' key, and use the /comm command and return to your commanding officer.'),
