('string/en/spacequest/destroy_surpriseattack/dath_bh_revenge_01.stf', 1, 'assigned_delayed', '\\#pcontrast3 Bountyhunters Guild: < \\#pcontrast1 Stay out of Dathomir! \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/dath_bh_revenge_01.stf', 2, 'complete', 'You may have won this time... but don''t cross the Bountyhunters'' Guild!'),
