('string/en/spacequest/destroy_surpriseattack/naboo_imperial_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_1.stf', 3, 'complete', 'Mission Complete!  Return to base by travelling to the Naboo Space Station, target it by pressing the ''C'' key, and using /comm.'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_1.stf', 4, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_1.stf', 5, 'split_quest_alert_fail', 'This isn''t the first time that new pilots have failed their first time out. We expect you to try again until you can get it right. Sending you a new navigation location to another patrol route.'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_1.stf', 6, 'title', 'Naboo System: Destroy the Rebel X-wing Ambush'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_1.stf', 7, 'title_d', 'Destroy the Rebel ambush. Your patrol route has been successful and, as planned, the Rebels have attacked you. You must destroy the Rebels that have attacked you. Once you have completed this task return to the Tatooine space station, target it by pressing the ''C'' key, and use the /comm command and return to your commanding officer.'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_1.stf', 8, 'unused1_d', ''),
