('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier3_3_a.stf', 3, 'complete', 'You have survived the Suprise Attack!'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier3_3_a.stf', 4, 'split_quest_alert', 'Pilot, we have a serious problem. The Rebels have attacked another ship. It would appear that they were uncertain what ship had the list. You are needed to help protect that other craft.'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier3_3_a.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier3_3_a.stf', 6, 'title', 'Dathomir System: Destroy the Rebel X-wings'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier3_3_a.stf', 7, 'title_d', 'A group of Rebels have come in a bit to late in order to stop you from making the delivery. Destroy them.'),
