('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier4_1_b.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier4_1_b.stf', 6, 'title', 'Dathomir System: Destroy the Mercenary Ambush'),
('string/en/spacequest/destroy_surpriseattack/naboo_imperial_tier4_1_b.stf', 7, 'title_d', 'The crystal smuggler apparently had a squad of fighters watching over it. Destroy all of those fighters and make sure you secure those crystals.'),
