('string/en/spacequest/destroy_surpriseattack/naboo_rebel_1.stf', 2, 'complete', 'Rebel Command: < Mission Complete!  Return to base for your next assignment by travelling to the Naboo space station and using /comm. >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_1.stf', 3, 'split_quest_alert', 'Rebel Command: < We have uploaded a new patrol route for you to check out pilot. Hopefully we will have more success this time. >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_1.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_1.stf', 5, 'title', 'Naboo system: Eliminate Enemy Patrol.'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_1.stf', 6, 'title_d', 'An enemy patrol of Imperial TIE fighters have spotted you. Defeat them to complete the mission.'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_1.stf', 7, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_1.stf', 8, 'unused1_t', ''),
