('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 3, 'complete', 'Brother Ezkiel: < Great work my friend, you beat the ambush. >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 4, 'split_quest_alert', 'Brother Ezkiel: < Now, gather information from one of the pirate ships. The SpyNet have asked us to try and find out where their leader is. >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 6, 'title', 'Dantooine system: Blacklight pirates attack!'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 7, 'title_d', 'The clever pirates have ambushed you. You need to prevail and defeat them!'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_2_c.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 2, 'complete', 'Brother Ezkiel: < Great job pilot, you showed those fools what a real pilot can do! >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 3, 'split_quest_alert', 'Brother Ezkiel: < Holy cow! We may be in over our head! The base is up ahead and the Blacklights are on to you! >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 5, 'title', 'Endor system: Blacklights strike back!'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 6, 'title_d', 'You''re being ambushed by Blacklight assassins. Defend yourself and eliminate the threat pilot!'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 7, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 8, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 9, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier3_3_a.stf', 10, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 2, 'complete', 'Brother Extok Evin: < Well done pilot, you showed them! I''m getting new intel now, stand by. >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 3, 'split_quest_alert', 'Brother Extok Evin: < You have one more chance pilot. Uvqolo hyperspaced to the Dathomir system but if you jump to lightspeed now, you may catch him when he arrives! >'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 5, 'title', 'Yavin system: Defend yourself against Uvqolo''s Interceptors.'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 6, 'title_d', 'Inquisitor Uvqolo had time to transmit your location to a TIE Interceptor squadron before he fled. Defend yourself and defeat Uvqolo''s trap!'),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 7, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 8, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 9, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_rebel_tier4_2_b.stf', 10, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 2, 'complete', 'Imperial Space Station: < Good job! This confirms it though, we need to change our routes immediately. Try to find more of them Rebel lowlifes! >'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 4, 'split_quest_alert', 'Imperial Space Station: < The scout must have alerted his friends, they are heading your way! >'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 6, 'title', 'Yavin system: Scouts spotted!'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 7, 'title_d', 'Your radar shows a Rebel scout fighter. This confirms that the route has been compromised but the commander wants you to eliminate the Rebel.'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_4.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 2, 'complete', 'Imperial Space Station: < Phew! You are quite the pilot, thought you were doomed. Hopefully that was it. >'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 4, 'split_quest_alert', 'Imperial Space Station: < Ack! Their bombers are still in the area and they are gunning for you! >'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 6, 'title', 'Yavin system: The Rebels revenge!'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 7, 'title_d', 'The Rebel scouts alerted their friends and they are coming to avenge their friends, defend yourself!'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_5.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 2, 'complete', 'Imperial Space Station: < Amazing! Your initiative and selflessnes has saved hundreds of loyal citizens pilot. If you ever visit our beloved Emperor''s retreat on Naboo, talk to one of the Imperial pilots outside and they will reward you for your bravery. Station, over and out. >'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 3, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 5, 'title', 'Yavin system: The last of them.'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 6, 'title_d', 'The Rebel bombers have decided to try and terminate you instead of retreating. Defeat them, they must be the last of the Rebel fools in the area.'),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 7, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 8, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 9, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/naboo_station_emperors_access_quest_6.stf', 10, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 2, 'complete', 'Your mission is a success!'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 3, 'leave_early', '\\#pcontrast1 Mos Eisley Captain:\\#pcontrast3 < Pilot! What happened out there? Did you find anything? Report back to me immediately! >'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 4, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 6, 'title', 'Tatoo System: Ghost Tide''s Black Nemesis'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 7, 'title_d', 'Kelen Wordkal was right. You''ve discovered, after a particularly interesting run-in with the Black Nemesis, something more foreboding has been causing the disappearances of the freighters traveling through the Ghost Tide Nebula.'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_general_2_a.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 2, 'complete', 'You have succeeded in defeating the Black Sun Aggressors!'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 4, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 6, 'title', 'Tatoo System: Black Suns Attack!'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 7, 'title_d', 'While on the patrol, you find yourself being hounded by Black Sun Aggressors. Perhaps these are the goons that have terminated many of the missing freighters Kelen Wordkal has reported.'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_generic_1_a.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 2, 'complete', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < I''m very impressed with your flying skills, pilot. >'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 3, 'split_quest_alert', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < It''s high time we see what the Valarians are up to and how they know every step we take. Disable and inspect several Valarian lackeys to see what they know. >'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 5, 'title', 'Tatoo System: Valarians Attack!'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 6, 'title_d', 'At this point, the Valarians are quickly topping your list of favorite enemies. With the continued attacks every step of the way, you begin to wonder exactly who is the spy informing the Valarians about your mission. Or it could be your undeniable charm. Maybe.'),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 7, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 8, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 9, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/poi_tatooine_privateer_2_a.stf', 10, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 1, 'assigned_delayed', 'Navigational Computer: < Warning! Warning! Enemy ships detected! Identifying... .. Jabba Assassins. Warning! Warning! Weapon systems armed! >'),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 2, 'complete', 'You have defeated Jabba''s assassins!'),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 3, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 5, 'title', 'Jabba''s Assassins!'),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 6, 'title_d', 'Jabba''s assassins have been sent after you and you begin to wonder why. Thinking back the last couple of days, you remember an informant associated with Jabba, named Rakkim Warstai. He had asked for your help in the name of Jabba and you refused. It clicks. Rakkim sent the assassins after you. He had warned you, right? Be wary of Jabba and his cronies in the future.'),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 7, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 8, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 9, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/sidequest_jabba_attack.stf', 10, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 2, 'complete', 'CorSec fighters have been eliminated.'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 4, 'split_quest_alert', 'There will be no witnesses to your actions. Travel to the Tatooine system, inspect, and pickup the brandy for the Lord''s Mistress.'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 6, 'title', 'Space Corellia: Destroy the CorSec Fighters'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 7, 'title_d', 'Your acts of piracy have gained the attention of the CorSec. They cannot be allowed to report in to your actions. Destroy them all.'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack01_tier2_1.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 1, 'assigned_delayed', 'It looks like Hap Daniel, the owner of the Lord''s Mistress, has found out where you went. Destroy him before he can report you to the authorities.'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 2, 'complete', 'Return the station with all of your captured booty for the operators.'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 4, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 6, 'title', 'Space Dantooine: Destroy the Lord''s Master'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 7, 'title_d', 'The owner of the Lord''s Mistress has managed to track you to the Dantooine system. He will be able to easily put two and two together. Sadly Hap Daniel must be eliminated.'),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_dantooine_owner_smuggler_surpriseattack02_tier2_1.stf', 9, 'unused1_t', ''),
