('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_1a_sa.stf', 1, 'assigned_delayed', '\\#pcontrast3 Imperial Station: < \\#pcontrast1 Captain we have detected 3 craft heading your way at high speed.  Weapon signatures indicate x-wing attack fighters be advised. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_1a_sa.stf', 2, 'complete', '\\#pcontrast3 Imperial Station: < \\#pcontrast1 You appear to be clear for the moment, continue on. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_1a_sa.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_1a_sa.stf', 4, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_1a_sa.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_1a_sa.stf', 6, 'title', 'Naboo System:  A Bump in the Road'),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_1a_sa.stf', 7, 'title_d', 'A patrol of Rebel X-Wing fighters has interrupted your rescue operation. Dispatch them and carry on with the mission.'),
