('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_3b.stf', 2, 'complete', 'The Blacklight Assassins have been defeated.'),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_3b.stf', 3, 'leave_early', '\\#pcontrast3 Blacklight: < \\#pcontrast1 This one is not worth our efforts, lets get out of here. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_3b.stf', 4, 'split_quest_alert', '\\#pcontrast3 Endor Station: \\#pcontrast1 The next stop is the Linear Miasma, updating waypoint now. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_3b.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_3b.stf', 6, 'title', 'Endor System: A Shade of Onyx'),
('string/en/spacequest/destroy_surpriseattack/stn_endor_irs_imp_tier3_3b.stf', 7, 'title_d', 'Blacklight Assassins taking exception to your intrusion in the area of the Onyx Beacon have come do drive you away.'),
