('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 2, 'complete', 'The enemy fighters have all been destroyed. Return to the station and report your findings.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 4, 'split_quest_alert', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 6, 'title', 'Yavin System: Destroy the Attacking Massassi'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 7, 'title_d', 'The real mercenaries pretending to be the Massassi have shown up. They must not be allowed to report your deception before you can report in to the station. Destroy them all.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_10.stf', 10, 'unused2_d', ''),
