('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 2, 'complete', 'Enemy ambush has been defeated.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 4, 'split_quest_alert', 'Location of the damaged fighter has been confirmed. Intercept and inspect that fighter for any clues to their identity. Return to the station when you have completed your search.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 6, 'title', 'Yavin System: Attacked by Mysterious Fighters'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 7, 'title_d', 'One of the fighters you were tailing must have detected you and set up an ambush. The damaged fighter is still on the radar but you will have to destroy these fighters in order to reach it.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_all_massassi_tier2_4.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 2, 'complete', 'All the Royal Security Force fighters have been eliminated. Continue with the assigned route and make the delivery.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 4, 'split_quest_alert', 'Finish the patrol route and make the drop off.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 6, 'title', 'Yavin System: Royal Security Force Interference'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 7, 'title_d', 'You actions have brought the attention of the Royal Security Forces. Do not let any of them report you.'),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/stn_yavin4_company_smuggler_tier2_3.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 3, 'complete', 'Mission Complete!  Return to your superior for the next assignment by travelling to the Tatooine Space Station, target it by pressing the ''C'' key, and using /comm.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 4, 'split_quest_alert', 'Commerce Raiders are on an intercept course. Destroy them!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 5, 'split_quest_alert_fail', 'This isn''t the first time that new pilots have failed their first time out. We expect you to try again until you can get it right. Sending you a new navigation location to another patrol route.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 6, 'title', 'Tatooine System: Destroy the Commerce Raiders'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 7, 'title_d', 'Destroy the pirate ambush. Your patrol route has been successful and, as planned, the Commerce Raiders have attacked you. You must destroy the pirates that have attacked you. Once you have completed this task return to the Tatooine space station, target it by pressing the ''C'' key, and use the /comm command and return to your commanding officer.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_1.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 3, 'complete', 'You have survived the surprise attack!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 4, 'split_quest_alert', 'Scans of Rebel transmissions indicate Rebel communications ship nearby your location. Disable vessel and recover any information from its computers that you can. Stand by for nav location.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 6, 'title', 'Endor System: Rebel Counterstrike'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 7, 'title_d', 'The Rebels have sent out a strike team in retaliation for the loss of their scout. Destroy all the Rebel fighters.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_2_a.stf', 11, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 2, 'complete', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <The Rebels managed to recover the false information while you were fighting the A-wings. Scan indicate increased activity around the ambush point.>'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 3, 'split_quest_alert', 'The Rebels have captured the decoy shuttle! The false information on it should lead them right into our ambush. Travel to the ambush point and wait for the Rebels to arrive. Maintain control of that position until we can get a full sensor scan of the surrounding area.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 5, 'title', 'Endor System: Destroy the Rebel Strikeforce'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 6, 'title_d', 'Destroy the Rebel A-wings that have been sent to eliminate you. Making sure that they are all eliminated will help in selling the deception.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 7, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 8, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 9, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier3_3_d.stf', 10, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 3, 'complete', 'You have survived the Suprise Attack!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 4, 'split_quest_alert', 'Alert! We just got word that you were not the only one hit. Another wing has been hit extremely hard and need support. Once you get the location get over there and help them out.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 6, 'title', 'Endor System: Destroy the Rebel Ambush'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 7, 'title_d', 'The Rebel menace in the Endor system seems to have returned. Destroy all attacking vessels.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 9, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 10, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_imperial_tier4_1_a.stf', 11, 'unused2_t', ''),
