('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_1.stf', 4, 'split_quest_alert', '\\#pcontrast3 Dravis: < \\#pcontrast1 You appear to have hit a little snag out there.  Get patched up and run that patrol again. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_1.stf', 5, 'split_quest_alert_fail', '\\#pcontrast3 Dravis: < \\#pcontrast1 You appear to have hit a little snag out there.  Get patched up and run that patrol again. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_1.stf', 6, 'title', 'Tatooine System: Eliminate Enemy Patrol'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_1.stf', 7, 'title_d', 'Defend yourself from the Black Sun Pirate attack'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_1.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_1.stf', 9, 'unused1_t', ''),
