('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier3_1_d.stf', 2, 'complete', '\\#pcontrast3 Beissa: < \\#pcontrast1 That is the sort of amateurish attack I expect from Valaria''s elite fighters.  Bring it home Captain, we have more work for you. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier3_1_d.stf', 3, 'leave_early', ''),
