('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier3_1_d.stf', 6, 'title', 'Yavin System: Defend Against a Sneak Attack'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier3_1_d.stf', 7, 'title_d', 'Defend agains a sneak attack by the real Valarian Replacement'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier3_1_d.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier3_1_d.stf', 9, 'unused1_t', ''),
