('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 2, 'complete', '\\#pcontrast3 Nirame: < \\#pcontrast1 I''ll give this much credit to that Valarian; it was an interesting, if futile, maneuver. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 3, 'leave_early', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 4, 'split_quest_alert', '\\#pcontrast3 Nirame: < \\#pcontrast1 About that freighter we wanted: It is in route to Endor, perhaps you can convince them to alter course. \\#pcontrast3 >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 5, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 6, 'title', 'Tatooine System: Defend from the Valarian Trick'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 7, 'title_d', 'Defend from the Valarian trick'),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 8, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_privateer_tier4_3c_sa.stf', 9, 'unused1_t', ''),
