('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 2, 'complete', 'Rebel Command: < Mission Complete!  Return to base for your next assignment by travelling to the Tatooine Space Station and using /comm. >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 3, 'quest_d', 'TIE Fighter Cadets have intercepted your sensor sweep. Eliminate them with extreme prejudice!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 4, 'quest_t', 'Destroy the TIE Cadets!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 5, 'split_quest_alert', 'Rebel Command: < We have uploaded a new patrol route for you to check out pilot. Hopefully we will have more success this time. >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 6, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 7, 'title', 'Tatooine system: Destroy the TIE Cadets!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 8, 'title_d', 'TIE Fighter Cadets have intercepted your sensor sweep. Eliminate them with extreme prejudice!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 9, 'unused1_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 10, 'unused1_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 11, 'unused2_d', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_1.stf', 12, 'unused2_t', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_tier3_2_a.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_tier3_2_a.stf', 2, 'complete', 'You have survived the Suprise Attack!'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_tier3_2_a.stf', 3, 'split_quest_alert', 'Rebel Command: < You impress me pilot. Let''s keep this winning streak going with another attack where it hurts the Empire the most. Proceed to the Dantooine system for further instructions. >'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_tier3_2_a.stf', 4, 'split_quest_alert_fail', ''),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_tier3_2_a.stf', 5, 'title', 'Dathomir system: Defeat the elite TIE squadron.'),
('string/en/spacequest/destroy_surpriseattack/tatooine_rebel_tier3_2_a.stf', 6, 'title_d', 'The Empire had some of their elite TIE Interceptors shadow their spy in case any complications came up. They are set on your destruction, surprise them by fighting back and show them that the Alliance have no fear!'),
