('string/en/spacequest/escort/corellia_imperial_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 2, 'abort', 'You cannot just leave us out here without an escort. The CorSec will be all over us! Report your failure to High Command.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 3, 'arrived_at_loc', 'Arrived at location. Wait here for Freighter to finish hyper jump.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 10, 'complete', 'Mission accomplished. Good job pilot. Report to your superior for further instructions.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 14, 'failed_destroy', 'You let the CorSec destroy equipment worth millions! We are sending another freighter to your position. Prove yourself worthy to be called an Imperial pilot.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 15, 'failed_protect', 'I''m doomed on my own, I''ll never make it! Black Epsilon will hear of your failure!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 16, 'found_loc', 'Escort coordinates confirmed. Proceed as planned.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 17, 'goodbye_1', 'Good job pilot! We will take it from here. Beginning descent to surface.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 18, 'goodbye_2', 'Good job pilot! We will take it from here. Beginning descent to surface.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 19, 'goodbye_3', 'Good job pilot! We will take it from here. Beginning descent to surface.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 20, 'goodbye_4', 'Good job pilot! We will take it from here. Beginning descent to surface.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 21, 'goodbye_5', 'Good job pilot! We will take it from here. Beginning descent to surface.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 22, 'hull_half', 'We''re falling apart over here, do your job pilot!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 23, 'panic_1', 'Incoming CorSec fighter ships, they have spotted my cargo, keep them off me!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 24, 'panic_2', 'CorSec fighters inbound, keep them off me!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 25, 'panic_3', 'CorSec fighter ships attacking, they have spotted my cargo!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 26, 'panic_4', 'CorSec fighter ships attacking, they have spotted my cargo!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 27, 'panic_5', 'CorSec fighters inbound, keep them off me!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 28, 'quest_escort_d', 'After meeting up with freighter, follow it to the drop location. You will need to protect the freighter from local security forces who might try to stop it in order to inspect its cargo of illegal explosives.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 29, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 30, 'quest_location_d', 'Travel to the Corellia system. Once you reach the system you will receive a navigation waypoint to the freighter''s arrival location. Travel to this location and wait for the arrival of the freighter.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 31, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 32, 'quest_rendezvous_d', 'Travel to the navigation waypoint to the arrival location of the freighter. Wait for the freighter to arrive and then follow it as it moves through the system.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 33, 'quest_rendezvous_t', 'Meeting the Freighter'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 34, 'quest_update', 'Black Epsilon Command: <%TO>'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 35, 'reason_1', 'We need to get this cargo to Coronet without incident. Watch our back.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 36, 'reason_2', 'We need to get this cargo to Coronet without incident. Watch our back.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 37, 'reason_3', 'We need to get this cargo to Coronet without incident. Watch our back.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 38, 'reason_4', 'We need to get this cargo to Coronet without incident. Watch our back.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 39, 'reason_5', 'We need to get this cargo to Coronet without incident. Watch our back.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 40, 'shields_depleted', 'My shields are failing! Get them off me quickly!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 41, 'split_quest_alert', 'A new freighter carrying the explosives is being sent to your system. Meet up with the freighter and make sure it reaches its destination.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/corellia_imperial_3.stf', 43, 'taunt_1', 'Cut your engines immediately or be destroyed!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 44, 'taunt_2', 'You are smuggling illegal goods. Cut your engines now or we will open fire!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 45, 'taunt_3', 'Terrorist scum! We will destroy you!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 46, 'taunt_4', 'You''re no match for me, terrorist scum!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 47, 'taunt_5', 'I''m taking you out, we don''t tolerate terrorism on Corellia!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 48, 'thanks_1', 'Great job! I see that the Black Epsilon didn''t put their trust in the wrong pilot.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 49, 'thanks_2', 'Phew, that was a close one. We are almost there, keep your eyes open.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 50, 'thanks_3', 'I thought they would take us out for sure. I will let Command know of your superior skills!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 51, 'thanks_4', 'Phew, that was a close one. We are almost there, keep your eyes open.'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 52, 'thanks_5', 'I thought they would take us out for sure. I will let Command know of your superior skills!'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 53, 'title', 'Corellia System: Escort the Freighter Carrying the Expolsives'),
('string/en/spacequest/escort/corellia_imperial_3.stf', 54, 'title_d', 'Travel to the Corellia system and escort the freighter through the system. Once you arrive in the Corellia system, you will receive a navigation waypoint to the freighter''s arrival location. Travel to this location and wait for the freighter to arrive. Once the freighter arrives, follow it to its destination. You will have to keep it safe from any enemy fighters who attempt to stop it from reaching its destination. This is the first of four special assignments given to you by Hakasha Sireen. When you complete this mission, return to Hakasha Sireen at the Imperial Base on Talus for your next assignment.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2b.stf', 1, 'abort', 'I''m dead because you aborted.  You lose.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2b.stf', 2, 'arrived_at_loc', 'Stay at the waypoint, your escortee will arrive soon.'),
