('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 28, 'quest_escort_d', 'Follow the freighter as it moves through Nym''s space. Any of Nym''s men who come to retaliate must be eliminated before they can alert their companions of your presence. If successful Nym will believe that the Hutts are launching a full scale attack on his operations.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 29, 'quest_escort_t', 'Escort the Retrofitted Freighter'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 30, 'quest_location_d', 'This operation is to take place in the Yavin system.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 31, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 32, 'quest_rendezvous_d', 'Meet the vessel at the supplied arrival Nav waypoint.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 33, 'quest_rendezvous_t', 'Meet the Retrofitted Freighter'),
