('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 39, 'reason_5', '*static*'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 40, 'shields_depleted', '*static*'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 41, 'split_quest_alert', 'Long range scans show that Nym''s men are massing and preparing to attack the Hutts. Assist the Hutts in wiping out Nym''s attack force.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 43, 'taunt_1', 'What are you doing in this sector Hutt?'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 44, 'taunt_2', 'The Hutts have broken our agreement.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 45, 'taunt_3', 'I knew we couldn''t trust the Hutts.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 46, 'taunt_4', 'It doesn''t surprise me that the Hutts have betrayed us.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 47, 'taunt_5', 'Time to pay for your betrayal, Hutt.'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 48, 'thanks_1', '*static*'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 49, 'thanks_2', '*static*'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 50, 'thanks_3', '*static*'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 51, 'thanks_4', '*static*'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 52, 'thanks_5', '*static*'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 53, 'title', 'Yavin System: Escort the Captured Hutt Freighter'),
('string/en/spacequest/escort/corellia_imperial_tier3_2_b.stf', 54, 'title_d', 'The captured Hutt ship has been retrofit with the signature jammer and autopilot system. The jammer will allow you to remain hidden by the ships signature. When Nym''s men scan the area all they will see is the Hutt ship and not your TIE. We will move this ship through Nym''s territory. Since they are already highly angered they are sure to try to retaliate on the Hutt vessel. You are to protect the vessel and destroy any who try to attack it.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 2, 'abort', 'Your orders were to make sure we dropped off the ground patrol successfully. Your superior will hear of your cowardice.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 3, 'arrived_at_loc', 'Stand by for the arrival of the drop shuttle. Once it arrives, escort it to the drop zone.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Alert! Enemy fighters detected. Incoming at attack speeds with weapons armed.>'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter wave has been eliminated.>'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 10, 'complete', 'The ground forces have been dropped onto the planet''s surface to begin their sweep. Stand by for further instructions.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 14, 'failed_destroy', 'Do you know how much effort it takes to get a commando crew trained? Report your failure to your superior.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 15, 'failed_protect', 'You left them without an escort? That is unacceptable. Report back to your commander.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 16, 'found_loc', 'Meet the drop shuttle at the location supplied to your nav computer.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 17, 'goodbye_1', 'Beginning decent to drop ship depth. That planet sure doesn''t look very hospitable. I hope out ground crew makes it okay.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 18, 'goodbye_2', 'Beginning decent to drop ship depth. That planet sure doesn''t look very hospitable. I hope out ground crew makes it okay.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 19, 'goodbye_3', 'Beginning decent to drop ship depth. That planet sure doesn''t look very hospitable. I hope out ground crew makes it okay.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 20, 'goodbye_4', 'Beginning decent to drop ship depth. That planet sure doesn''t look very hospitable. I hope out ground crew makes it okay.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 21, 'goodbye_5', 'Beginning decent to drop ship depth. That planet sure doesn''t look very hospitable. I hope out ground crew makes it okay.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 22, 'hull_half', 'Hull strength down to half. Get those fighters off of us, pilot.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 23, 'panic_1', 'Blast it! More of those mercs!'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 24, 'panic_2', 'We are a troop transport not a fighter. Keep those ships off of us.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 25, 'panic_3', 'I will try to evade as long as I can but it is really up to you.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 26, 'panic_4', 'Keep those fighters busy while I try to make it to the drop point.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 27, 'panic_5', 'I can''t shake them! You are going to have to destroy them.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 28, 'quest_escort_d', 'Protect the drop ship until it reaches the drop location. Once it has dropped off the strike team wait for it to leave the area.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 29, 'quest_escort_t', 'Escort the Drop Ship'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 30, 'quest_location_d', 'Meet the drop ship in the Dathomir system. You will be supplied with the arrival location of the drop ship once you enter the system.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 31, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 32, 'quest_rendezvous_d', 'Travel to the arrival location and wait for the arrival of the drop ship.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 33, 'quest_rendezvous_t', 'Meet the Drop Ship'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 34, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 35, 'reason_1', 'We have to get these troopers to the drop point. Once over the drop point I will drop the pods and jump out of the sector. Keep an eye out for enemy craft.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 36, 'reason_2', 'We have to get these troopers to the drop point. Once over the drop point I will drop the pods and jump out of the sector. Keep an eye out for enemy craft.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 37, 'reason_3', 'We have to get these troopers to the drop point. Once over the drop point I will drop the pods and jump out of the sector. Keep an eye out for enemy craft.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 38, 'reason_4', 'We have to get these troopers to the drop point. Once over the drop point I will drop the pods and jump out of the sector. Keep an eye out for enemy craft.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 39, 'reason_5', 'We have to get these troopers to the drop point. Once over the drop point I will drop the pods and jump out of the sector. Keep an eye out for enemy craft.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 40, 'shields_depleted', 'We just lost our shields. Unless you get those fighters off of us, we are not going to make it.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 41, 'split_quest_alert', 'Alert! Alert! Drop shuttle has been attacked and damaged, while attempting to jump out of the sector, by an enemy force. Prepare to offer assistance.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 43, 'taunt_1', 'I thought Imperial pilots were supposed to be good.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 44, 'taunt_2', 'The bosses don''t want your kind in this sector.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 45, 'taunt_3', 'Sorry about having to blow you up. Just following orders.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 46, 'taunt_4', 'The bosses told us you would be trying this. They sure know alot of things.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 47, 'taunt_5', 'The bosses don''t want your kind in this sector.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 48, 'thanks_1', 'We are still on target. The sooner we can get this drop done the sooner we can get out of here.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 49, 'thanks_2', 'We are still on target. The sooner we can get this drop done the sooner we can get out of here.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 50, 'thanks_3', 'We are still on target. The sooner we can get this drop done the sooner we can get out of here.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 51, 'thanks_4', 'We are still on target. The sooner we can get this drop done the sooner we can get out of here.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 52, 'thanks_5', 'We are still on target. The sooner we can get this drop done the sooner we can get out of here.'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 53, 'title', 'Dathomir System: Escort the Drop Ship'),
('string/en/spacequest/escort/corellia_imperial_tier4_3.stf', 54, 'title_d', 'The recovered shuttle and the orders on the captured captain suggest that the people you are after went to the Dathomir sector. Insurgent believes that some of them might have landed on the planet''s surface and wants to send in a strike team to make sure they never off if they did. The strike team will be dropped in from space and then have to travel to via land to the Imperial prison. They are not aware that this is a one way trip. You are to escort the drop ship safely through the Dathomir system.'),
