('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 10, 'complete', 'Awesome pilot, this should be the last thing we need to be able to get out of here. Return to your base on Yavin 4 for some rest.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 14, 'failed_destroy', 'Damn the Empire, we needed those supplies!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 15, 'failed_protect', 'Bah! The smuggler had to bail, he had too many enemies on him.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 16, 'found_loc', 'Rebel Fleet Command: < Meet the smuggler at these coordinates. >'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 17, 'goodbye_1', 'Good show, I owe you one!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 18, 'goodbye_2', 'Good show, I owe you one!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 19, 'goodbye_3', 'Good show, I owe you one!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 20, 'goodbye_4', 'Good show, I owe you one!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 21, 'goodbye_5', 'Good show, I owe you one!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 22, 'hull_half', 'Cripes, my old baby is falling apart, I need help!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 23, 'panic_1', 'I guess it was too much to hope for a smooth ride.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 24, 'panic_2', 'No one said there would be more TIE fighters than asteroids here!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 25, 'panic_3', 'Prepare for a fight, incoming bad guys!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 26, 'panic_4', 'My ship is being scanned, they will attack when they see what I have on-board!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 27, 'panic_5', 'TIE-Fighters! They don''t look too happy either.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 28, 'quest_escort_d', 'Escort the smuggler to our fleet. Try to avoid contact with Imperial forces at all costs and above all, don''t lead any of them to our fleet! Good luck pilot.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 29, 'quest_escort_t', 'Escort the Rebel smuggler.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 30, 'quest_location_d', 'It''s our hope that you and the smuggler will be able to sneak past the Imperial presence in the system as they are looking for bigger targets but it will be hard since they seem to be all over now.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 31, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 32, 'quest_rendezvous_d', 'You have been supplied with the coordinates of where the smuggler will meet with you. Make haste to this location.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 33, 'quest_rendezvous_t', 'Meet up with the smuggler.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 34, 'quest_update', 'Rebel Fleet Command < %TO >'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 35, 'reason_1', 'Good to see you, lets get this stuff to the fleet.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 36, 'reason_2', 'Good to see you, lets get this stuff to the fleet.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 37, 'reason_3', 'Good to see you, lets get this stuff to the fleet.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 38, 'reason_4', 'Good to see you, lets get this stuff to the fleet.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 39, 'reason_5', 'Good to see you, lets get this stuff to the fleet.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 40, 'shields_depleted', 'My shields are failing! I''m taking some serious damage here!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 41, 'split_quest_alert', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 43, 'taunt_1', 'You will never deliver that stuff Rebel!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 44, 'taunt_2', 'Blast them all!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 45, 'taunt_3', 'Die Rebel scum!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 46, 'taunt_4', 'You will fall from the might of the Empire!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 47, 'taunt_5', 'What will this Rebel kill bring me to today guys? 5?'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 48, 'thanks_1', 'Great working with you mate!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 49, 'thanks_2', 'Well we showed them didn''t we?'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 50, 'thanks_3', 'Take that you Imperial fools!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 51, 'thanks_4', 'Hahaha, die die die!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 52, 'thanks_5', 'You''re lucky I''m here, did you see me blast that TIE? It was beautiful!'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 53, 'title', 'Endor system: Escort smuggler to fleet.'),
('string/en/spacequest/escort/corellia_rebel_tier3_3_c.stf', 54, 'title_d', 'One of our smugglers has arrived with the materials necessary to repair the hyperdrive systems on our capital ships. He needs an escort but we don''t want to attract too much attention so you will assist him by yourself.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 1, 'abort', 'You''re the sorriest excuse for a CorSec pilot I''ve ever seen.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 2, 'arrived_at_loc', 'Copy that pilot. Await transport here. Keep your eyes open for the Cloak attack wing. We''ll send out the the attack squad once they start to come in.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Warning. Enemy craft inbound.\\#pcontrast1 >'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Enemy threat neutralized.\\#pcontrast1 >'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 7, 'autorewardfrom', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 9, 'complete', 'We''ve sent the transport home early. Stay at your current location, pilot. It''ll just be the CorSec here now when the Cloaks come in.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 10, 'escort_too_far1', 'You''re moving too far out, pilot. Bring it in a little closer.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 13, 'failed_destroy', 'Abort the mission pilot, the transport was destroyed. Return to the station for debriefing.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 14, 'failed_protect', 'Abort the mission pilot, the transport has moved out of range. Return to the station for debriefing.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 15, 'found_loc', 'We''re sending a navigation waypoint to you, pilot. Meet the transport here.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 16, 'goodbye_1', 'We''ve gotten the signal from CorSec command. We''re getting out of here. Good luck, pilot.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 17, 'goodbye_2', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 18, 'goodbye_3', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 21, 'hull_half', 'We''re losing hull integrity, CorSec. If you''re going to do something, now''s the time.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 22, 'panic_1', 'Cloak ships coming in! Hurry signal CorSec command about this!'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 23, 'panic_2', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 24, 'panic_3', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 27, 'quest_escort_d', 'Escort the transport as it moves through the Corellia system. At the first sign of a cloak attack, CorSec command will make it''s move.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 28, 'quest_escort_t', 'Escort the Transport'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 29, 'quest_location_d', 'The transport will meet you in the Corellia system.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 30, 'quest_location_t', 'Remain in the Corellia System'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 31, 'quest_rendezvous_d', 'Meet up with the transport at the specified location within the Corellia system.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 32, 'quest_rendezvous_t', 'Meet With the Transport'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 33, 'quest_update', '\\#pcontrast1 CorSec Command: <\\#pcontrast3  %TO\\#pcontrast1  >'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 34, 'reason_1', 'Glad you could make it, pilot. CorSec command said that there''s been some trouble and will signal us to hyperspace out immediately if necessary.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 35, 'reason_2', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 36, 'reason_3', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 39, 'shields_depleted', 'Shields are down, CorSec. We could use some help here.'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 40, 'split_quest_alert', 'Ambush the Cloak attack wing'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 42, 'taunt_1', 'Ah, excellent. This ship belongs to us now!'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 43, 'taunt_2', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 44, 'taunt_3', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 47, 'thanks_1', 'Good shooting, pilot!'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 48, 'thanks_2', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 49, 'thanks_3', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 52, 'title', 'Corellia System: Watch for Cloak Attack Against Freighter'),
('string/en/spacequest/escort/corellia_station_mission5b_1.stf', 53, 'title_d', 'CorSec command wants you to perform the escort as the Cloak message suggests. When the Cloak attack wing begins to arrive, command will have the transport jump out, and send in a CorSec squadron to defeat the Cloaks.'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 1, 'abort', '\\#pcontrast3 Freighter: < \\#pcontrast1 The command to abort has been given, our mission is a failure. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 2, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast3 Rendezvous point reached.  The freighter will arive shortly. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Ships approacing on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 9, 'complete', '\\#pcontrast3 Station Command: < \\#pcontrast1 The freighter should be safe from here.  Good job. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 13, 'failed_destroy', '\\#pcontrast3 Station Command: < \\#pcontrast1 You allowed the freighter to be destroyed.  We needed the pesticides they were delivering to get rid of this lice infestation! \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 14, 'failed_protect', '\\#pcontrast3 Station Command: < \\#pcontrast1 The freighter was driven off course and is now lost.  We needed the pesticides they were delivering to get rid of this lice infestation! \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 15, 'found_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Rendezvous waypoint has been set. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 16, 'goodbye_1', '\\#pcontrast3 Freighter: < \\#pcontrast1 We made it. Another successful day in the life of a flying target. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 17, 'goodbye_2', '\\#pcontrast3 Freighter: < \\#pcontrast1 We should be safe from here. Thank you for the protection. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 18, 'goodbye_3', '\\#pcontrast3 Freighter: < \\#pcontrast1 Nice bit of flying there, I was worried for a bit. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 19, 'goodbye_4', '\\#pcontrast3 Freighter: < \\#pcontrast1 Nice bit of flying there, I was worried for a bit. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 20, 'goodbye_5', '\\#pcontrast3 Freighter: < \\#pcontrast1 Nice bit of flying there, I was worried for a bit. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 21, 'hull_half', '\\#pcontrast3 Freighter: < \\#pcontrast1 We are getting shot up pretty bad over here, keep those fighters off of us. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 22, 'panic_1', '\\#pcontrast3 Freighter: < \\#pcontrast1 Careful, we''re under attack. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 23, 'panic_2', '\\#pcontrast3 Freighter: < \\#pcontrast1 Careful, we''re under attack. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 24, 'panic_3', '\\#pcontrast3 Freighter: < \\#pcontrast1 Careful, we''re under attack. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 25, 'panic_4', '\\#pcontrast3 Freighter: < \\#pcontrast1 Alert, we''re under attack. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 26, 'panic_5', '\\#pcontrast3 Freighter: < \\#pcontrast1 Alert, we''re under attack. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 27, 'quest_d', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 28, 'quest_escort_d', 'Protect this target carrying the pesticides needed by the station to rid itself of a lice infestation.'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 29, 'quest_escort_t', 'Freighter'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 30, 'quest_location_d', 'An escort route in the Dathomir System'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 31, 'quest_location_t', 'Dathomir System'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 32, 'quest_rendezvous_d', 'Travel here to meet up with the freighter'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 33, 'quest_rendezvous_t', 'Rendezvous Point'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 34, 'quest_t', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 35, 'quest_update', '%TO'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 36, 'reason_1', '\\#pcontrast3 Freighter: < \\#pcontrast1 Thanks for the escort. I didn''t expect us to draw such attention. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 37, 'reason_2', '\\#pcontrast3 Freighter: < \\#pcontrast1 I hope you are the best escort we have to offer. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 38, 'reason_3', '\\#pcontrast3 Freighter: < \\#pcontrast1 Let''s get underway, and may the force be with us today. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 39, 'reason_4', '\\#pcontrast3 Freighter: < \\#pcontrast1 Let''s get underway, and may the force be with us today. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 40, 'reason_5', '\\#pcontrast3 Freighter: < \\#pcontrast1 Let''s get underway, and may the force be with us today. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 41, 'shields_depleted', '\\#pcontrast3 Freighter: < \\#pcontrast1 Our shields are down.  If you plan on doing something, now would be a good time. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 42, 'split_quest_alert', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 43, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 44, 'taunt_1', 'This is nothing personal, just business.'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 45, 'taunt_2', 'This is too easy.'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 46, 'taunt_3', 'You will die today.'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 47, 'taunt_4', 'HA, this is an escort?'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 48, 'taunt_5', 'You call that fighting?'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 49, 'thanks_1', '\\#pcontrast3 Freighter: < \\#pcontrast1 Thank you for getting us through. \\#pcontrast3 >'),
