('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 51, 'thanks_3', '\\#pcontrast3 Freighter: < \\#pcontrast1 Thank you for getting us through. \\#pcontrast3 >'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 52, 'thanks_4', '\\#pcontrast3 Freighter: < \\#pcontrast1 Thank you for getting us through. \\#pcontrast3 >'),
