('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 54, 'title', 'Dathomir System: Escort the Freighter'),
('string/en/spacequest/escort/dathomir_station_priv_storyquest_01_c.stf', 55, 'title_d', 'Removing the Lice: A freighter is enroute carrying pesticides that will free the station from the lice infestation brought about by a recent cargo delivery. Be alert for an attack by the Ay''Nat pirates, who seem to think the cargo is something more valuable.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/imperial_ss_5.stf', 2, 'abort', 'You are calling off the mission? Your orders were to escort us through this system. We will be forced to report this failure.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 3, 'arrived_at_loc', 'Wait for the arrival of the freighter. It should be jumping into the sector shortly.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter incoming at attack speeds.>'),
('string/en/spacequest/escort/imperial_ss_5.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/escort/imperial_ss_5.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 10, 'complete', 'Excellent job, pilot. The scan team managed to discover some very interesting things about the Rebel locations. Report back to your superior.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 14, 'failed_destroy', 'Pilot, you disappointed us. You were supposed to protect that freighter at all costs. Report your failure to your commander.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 15, 'failed_protect', 'Pilot, you have left your duty behind. The Empire does not look kindly on cowards. Report your failure to your superior immediately.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 16, 'found_loc', 'Jump location for the freighter located. Downloading information to your nav computer. Proceed to that location and escort the freighter through the system.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 17, 'goodbye_1', 'You really showed your metal out there. Thanks for the support.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 18, 'goodbye_2', 'With pilots like you, the Empire will never fall.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 19, 'goodbye_3', 'Jumping out the sector. Thanks for the help.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 20, 'goodbye_4', 'The Rebels should have thought twice before tangling with you.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 21, 'goodbye_5', 'The Rebels should have thought twice before tangling with you.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 22, 'hull_half', '\\#FF0000 Hull at half strength. Get those fighters off of us!'),
('string/en/spacequest/escort/imperial_ss_5.stf', 23, 'panic_1', 'Rebels! Keep them off of me while I continue the scans.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 24, 'panic_2', 'The rebels must have gotten wind of what we were up to.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 25, 'panic_3', 'Look out! Rebels incoming.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 26, 'panic_4', 'Incoming rebels! Keep them off of us.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 27, 'panic_5', 'Those enemy fighters are all yours.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 28, 'quest_escort_d', 'Escort the Scan Freighter through the system and protect it from any Rebel attack.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 29, 'quest_escort_t', 'Protect the Scan Team'),
('string/en/spacequest/escort/imperial_ss_5.stf', 30, 'quest_location_d', 'Meet the scan vessel inside the Yavin system.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 31, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/escort/imperial_ss_5.stf', 32, 'quest_rendezvous_d', 'In order to assure that the vessel is protected the entire time it is the system, you are to travel to the arrival location and wait for it to arrive.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 33, 'quest_rendezvous_t', 'Meet the Scanning Vessel'),
('string/en/spacequest/escort/imperial_ss_5.stf', 34, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort/imperial_ss_5.stf', 35, 'reason_1', 'Hello, pilot. We are going to begin our scans. Keep an eye out for enemy fighters.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 36, 'reason_2', 'Your job is to keep enemy fighters off of us until we can complete our scans.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 37, 'reason_3', 'Rebel activity is going to be high on this run. Be on the look out.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 38, 'reason_4', 'We are going to attract the Rebels on this run.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 39, 'reason_5', 'Time to test your skills pilot. Rebels will be coming out of everywhere on this run.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 40, 'shields_depleted', '\\#FF0000 We just lost our shields! We are not going to last much longer at this rate.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 41, 'split_quest_alert', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/imperial_ss_5.stf', 43, 'taunt_1', 'Come get some.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 44, 'taunt_2', 'You don''t want any of this.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 45, 'taunt_3', 'I have a prediction for your future...pain.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 46, 'taunt_4', 'Give up now, Imperial dog.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 47, 'taunt_5', 'You would be a good pilot. If you didn''t fly like a blind bantha.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 48, 'thanks_1', 'Wow. I didn''t think we would make it.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 49, 'thanks_2', 'Odd. I always thought the Rebels were tougher then that.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 50, 'thanks_3', 'Did you see that ship? Looked just like a firework.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 51, 'thanks_4', 'Just wasn''t their day.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 52, 'thanks_5', 'Did you hear them scream? No? Oh, right we are in space.'),
('string/en/spacequest/escort/imperial_ss_5.stf', 53, 'title', 'Escort the Scan Team'),
('string/en/spacequest/escort/imperial_ss_5.stf', 54, 'title_d', 'Now that the Empire is armed with a record of Rebel activities in the area they have a good idea of where they need to look to find out about the Rebel''s find. They are sending out a scanning craft to search the areas noted on in the activity log. You are to protect the scanning craft from any attempt to destroy it so they can get readings of the area. '),
('string/en/spacequest/escort/naboo_imperial_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 2, 'abort', 'Things are too hot. My ship is damaged...pulling out...'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 3, 'arrived_at_loc', 'The E-62 is jumping into the system now. Stand by.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 4, 'assigned_delayed', ''),
