('string/en/spacequest/escort/naboo_imperial_3.stf', 7, 'attack_warn_1', 'Rebels! It looks like they were after the E-62 technology after all.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 8, 'attack_warn_2', 'A group of Rebels is moving in to attack, be prepared to defend.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 9, 'attack_warn_3', 'Rebels! Heads up!'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 10, 'autorewardbody', ''),
