('string/en/spacequest/escort/naboo_imperial_3.stf', 17, 'failed_destroy', 'Your orders were to protect that operative and the transport. Report your failure to your superior.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 18, 'failed_protect', 'You left the E-62 without an escort! That is unacceptable. Prove yourself worthy! We are sending a new freighter to your location.'),
