('string/en/spacequest/escort/naboo_imperial_3.stf', 27, 'hull_half', 'Our hull is at half strength. Get those fighters off of us.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 28, 'panic_1', 'Enemy ships incomming. You will have to fend them off.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 29, 'panic_2', 'Blast it! We have been spotted.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 30, 'panic_3', 'Keep those fighters off of us.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 31, 'panic_4', 'Rebel fighters incoming. I hope you know how to fly that thing.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 32, 'panic_5', 'Here they come. This isn''t good.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 33, 'quest_escort_d', 'Once the freighter containing the E-62s has arrived, follow it to it''s destination. You will have to protect it from any attempt to attack the vessel. Especially keep a careful eye out for Rebels.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 34, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 35, 'quest_location_d', 'Remain in the Naboo system. Once you finish the patrol, you will receive a navigation waypoint to the freighter''s arrival location. Travel to this location and wait for the arrival of the freighter.'),
