('string/en/spacequest/escort/naboo_imperial_3.stf', 46, 'split_quest_alert', 'A new freighter carrying the E-62s is being sent to your system. Meet up with the freighter and make sure it reaches its destination.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 47, 'split_quest_alert_fail', ''),
