('string/en/spacequest/escort/naboo_imperial_3.stf', 52, 'taunt_5', 'Imperial dog! You will pay for that.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 53, 'thanks_1', 'Wow! That was some nice flying.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 54, 'thanks_2', 'You really showed those Rebels the might of the Imperial Navy.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 55, 'thanks_3', 'Oooooo, pretty colors.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 56, 'thanks_4', 'Will they never learn?'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 57, 'thanks_5', 'That had to hurt.'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 58, 'title', 'Naboo System: Escort the Decoy E-62 Transport'),
('string/en/spacequest/escort/naboo_imperial_3.stf', 59, 'title_d', 'Remain in the Naboo system and escort the freighter through the system. Once you finish the patrol in the Naboo system, you will receive a navigation waypoint to the freighter''s arrival location. Travel to this location and wait for the freighter to arrive. Once the freighter arrives, follow it to its destination. You will have to keep it safe from any enemy fighters who attempt to stop it from reaching its destination.'),
('string/en/spacequest/escort/naboo_imperial_tier3_1.stf', 1, 'abort', 'High Command will hear about your failure in your duty, pilot.'),
