('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 2, 'abort', 'You aborted? What are you thinking? The doctor must be sent to Dathomir Prison.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 3, 'arrived_at_loc', 'This is the location that the prison ship will arrive. Hold position and then escort it to the drop point.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected. Incoming at attack speed.>'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy wing destroyed.>'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 10, 'complete', 'The pod with the doctor has safely been dropped to the prison. Hold position for further instructions.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 14, 'failed_destroy', 'The prison ship has been destroyed. At least the doctor didn''t all into enemy hands but we wanted him alive. Speak to your superior about this failure.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 15, 'failed_protect', 'You left the ship on its own! What were you thinking. Return to your superior immeidately and explain your actions.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 16, 'found_loc', 'Proceed to the location that has been sent to your navigation computer and wait for the prison ship.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 17, 'goodbye_1', 'Dropping the prisoners and jumping out of the system. Thanks pilot.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 18, 'goodbye_2', 'Dropping the prisoners and jumping out of the system. Thanks pilot.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 19, 'goodbye_3', 'Dropping the prisoners and jumping out of the system. Thanks pilot.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 20, 'goodbye_4', 'Dropping the prisoners and jumping out of the system. Thanks pilot.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 21, 'goodbye_5', 'Dropping the prisoners and jumping out of the system. Thanks pilot.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 22, 'hull_half', 'Our hull is down fifty percent. Get these fighters off of us!'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 23, 'panic_1', 'Rebels? I have never seen them hit a prison ship before.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 24, 'panic_2', 'They must be after the doctor.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 25, 'panic_3', 'Rebels! They are all yours pilot.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 26, 'panic_4', 'They are trying to free the doctor. Stop them at all costs.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 27, 'panic_5', 'Rebel scum. They cannot be allowed to rescue the doctor.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 28, 'quest_escort_d', 'Follow the prison shuttle to the drop location and protect it until it can drop the doctor on the planet.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 29, 'quest_escort_t', 'Escort the Prison Shuttle'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 30, 'quest_location_d', 'Meet the prison shuttle at the supplied navigation waypoint inside the Dathomir system.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 31, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 32, 'quest_rendezvous_d', 'Wait at the navigation waypoint for the prison shuttle to arrive.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 33, 'quest_rendezvous_t', 'Meet the Prison Shuttle'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 34, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 35, 'reason_1', 'We have the doctor secured. Beginning our run to drop zone.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 36, 'reason_2', 'We have the doctor secured. Beginning our run to drop zone.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 37, 'reason_3', 'We have the doctor secured. Beginning our run to drop zone.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 38, 'reason_4', 'We have the doctor secured. Beginning our run to drop zone.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 39, 'reason_5', 'We have the doctor secured. Beginning our run to drop zone.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 40, 'shields_depleted', 'We just lost our shields! Get these fighters off of us!'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 41, 'split_quest_alert', 'Reports are coming in that Rebels have staged a major assault on the Dathomir TIEs in an attempt to rescue the doctor. You are to join the battle. Stand by for location.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 43, 'taunt_1', 'Sorry, you can''t have him.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 44, 'taunt_2', 'If we can''t have him, no one will!'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 45, 'taunt_3', 'We wanted to do this the easy way.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 46, 'taunt_4', 'Fighters, focus your firepower on that shuttle!'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 47, 'taunt_5', 'Sorry, doc. Looks like you are taking one for the team this time.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 48, 'thanks_1', 'Nice work, pilot. They will think twice about attacking again.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 49, 'thanks_2', 'Those Rebels lit up like fireworks.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 50, 'thanks_3', 'Prisoners are secure. Thanks.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 51, 'thanks_4', 'Prisoners are secure. Thanks.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 52, 'thanks_5', 'Prisoners are secure. Thanks.'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 53, 'title', 'Dathomir System: Escort Doctor Shinss''s Prison Ship'),
('string/en/spacequest/escort/naboo_imperial_tier3_4_a.stf', 54, 'title_d', 'The Inquisition has decided against executing the doctor. His knowledge is simply to valuable but we cannot allow him too run freely. He is to be dropped at the Dathomir prison. Since you are already in the region, you are to escort the Doctor''s prison ship through the system to ensure he does not escape.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 2, 'abort', 'Your orders were to escort us through this area. High Command will hear of this failure I assure you.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 3, 'arrived_at_loc', 'Stand by for arrival of Prison transport. We anticipate a smooth flight.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters detected.>'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter wing eliminated.>'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 8, 'autorewardfrom', ''),
