('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 10, 'complete', 'Prison ship depositing it''s cargo on the planet surface. Nice work, pilot.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 11, 'escort_too_far1', ''),
