INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 14, 'failed_destroy', 'They were only prisoners but that is no excuse for failing a direct order. Report back to your superior.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 15, 'failed_protect', 'You left your target. This is unacceptable. Report back to command.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 16, 'found_loc', 'The prison transport will arrive at this nav location. Meet that ship here and escort it through the sector.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 17, 'goodbye_1', 'Thanks for the escort. You had better find out why those Coynites are still in the sector though.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 18, 'goodbye_2', 'Thanks for the escort. You had better find out why those Coynites are still in the sector though.'),
