('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 22, 'hull_half', '\\#FF0000 Our hull is down to half strength! We are not going to last much longer.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 23, 'panic_1', 'What! I thought these mercs were driven out of this sector?'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 24, 'panic_2', 'The mercs are back! I don''t think that was their command vessel.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 25, 'panic_3', 'Coynite mercenaries! Didn''t you kill all of them?'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 26, 'panic_4', 'What! I thought these mercs were driven out of this sector?'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 27, 'panic_5', 'Coynite mercenaries! Didn''t you kill all of them?'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 28, 'quest_escort_d', 'Escort and protect the prison ship until it makes its prison drop.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 29, 'quest_escort_t', 'Escort the Prison Ship'),
