('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 40, 'shields_depleted', 'There went our shields. Get those fighters off of us.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 41, 'split_quest_alert', 'It appears that the Coynite were not defeated as we had hoped. This appears to have been a decoy attack for their real plan to get a ship off of the planet''s surface. Stand by for more information.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 43, 'taunt_1', 'For Coyn! For Glory!'),
