('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 45, 'taunt_3', 'Your heart shall not beat another day.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 46, 'taunt_4', 'Draw your last breath and prepare to die!'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 47, 'taunt_5', 'You are a fool to think you could beat us so easily.'),
('string/en/spacequest/escort/naboo_imperial_tier4_4.stf', 48, 'thanks_1', 'I still can''t believe that there are more of those mercs out there.'),
