('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 43, 'taunt_2', 'This job is going to be the death of you.'),
('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 44, 'taunt_3', 'Were you looking for me RSF fools?'),
('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 45, 'taunt_4', 'Were you looking for me RSF fools?'),
('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 46, 'taunt_5', 'Were you looking for me RSF fools?'),
('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 47, 'thanks_1', 'Activity is high, stay watchful.'),
('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 48, 'thanks_2', 'They will send more, I can feel it.'),
('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 49, 'thanks_3', 'Activity is high, stay watchful.'),
('string/en/spacequest/escort/naboo_privateer_tier4_4b.stf', 50, 'thanks_4', 'Activity is high, stay watchful.'),
