('string/en/spacequest/escort/naboo_rebel_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 2, 'abort', 'NO! We''re not going to make it! Please help us! Don''t leave us...'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 3, 'arrived_at_loc', 'Alliance HQ: Wait here for Alliance Refugee Transport to arrive.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 5, 'attack_notify', 'Tactical Computer: < Hostiles on approach vector to escort target! >'),
