INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort/naboo_rebel_3.stf', 9, 'attack_warn_3', 'Look out! Imperial TIE fighters on the offensive!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 10, 'autorewardbody', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 11, 'autorewardfrom', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 12, 'autorewardsubject', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 13, 'complete', 'The refugees are safe. Good work, return to base.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 14, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 15, 'escort_too_far1', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 16, 'escort_too_far2', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 17, 'escort_too_far3', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 18, 'failed_destroy', 'All refugees have been lost. The mission is a failure. Return to base.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 19, 'failed_protect', 'Refugee transport has been lost! Mission is a failure.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 20, 'found_loc', 'Fly to the Alliance Refugee Transport''s last known location.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 21, 'goodbye', 'Thanks for taking care of us, friend! The Force be with you...'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 22, 'goodbye_1', 'We are very grateful for your gallant rescue, my friend! The Force be with you...'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 23, 'goodbye_2', 'The refugees thank you, my friend... as I''m sure do all of their relatives and of course the Alliance. The Force be with you!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 24, 'goodbye_3', 'Excellent work, buddy! Everyone on-board is safe and sound. We''ll let Alliance Command know how much you helped us.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 25, 'goodbye_4', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 26, 'goodbye_5', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 27, 'hello', 'Thank the maker! Please! You must help us get these refugees out of the system. The Empire has been on our tail since the last hyper-jump.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 28, 'hull_half', 'Help! The ship is torn to pieces! People are dying in here!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 29, 'panic_1', 'We are under attack!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 30, 'panic_2', 'Get these fighters off us, now!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 31, 'panic_3', 'Help! Their tearing us apart!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 32, 'panic_4', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 33, 'panic_5', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 34, 'quest_escort_d', 'Protect the Alliance Refugee Transport as it makes its way out of the Naboo system. Destroy any hostiles that attack the transport. Keep a close watch on the Refugees... '),
('string/en/spacequest/escort/naboo_rebel_3.stf', 35, 'quest_escort_t', 'Escort Alliance Refugee Transport.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 36, 'quest_location_d', 'Locate an Alliance refugee transport that has been lost in the Naboo system.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 37, 'quest_location_t', 'Naboo system.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 38, 'quest_rendezvous_d', 'Fly to the intercept point and wait for the Alliance refugee transport to arrive.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 39, 'quest_rendezvous_t', 'Transport Intercept.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 40, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 41, 'reason_1', 'The Empire thinks our refugees are Rebel spies! Can you believe that?!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 42, 'reason_2', 'Imperial interceptors have been tailing us since we picked up these passengers.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 43, 'reason_3', 'I think the Empire wants to ask us some questions... after they''ve spaced us!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 44, 'reason_4', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 45, 'reason_5', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 46, 'shields_depleted', 'Whoah! Our shields are down, buddy! Keep the badguys off us, okay?'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 47, 'split_quest_alert', 'Rebel Command: < There''s another freighter that need your help pilot, don''t let us down again! >'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 48, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 49, 'taunt_1', 'You are transporting Rebel terrorists! Lower your shields and prepare to be boarded!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 50, 'taunt_2', 'I''ve seen you before, Rebel scum! But this time will be the last...'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 51, 'taunt_3', 'Dump out those spies you''re protecting... and we''ll let you live!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 52, 'taunt_4', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 53, 'taunt_5', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 54, 'thanks_1', 'Whew! Good shooting!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 55, 'thanks_2', 'Excellent work, my friend!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 56, 'thanks_3', 'Now THAT''S what an Alliance Pilot can do!'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 57, 'thanks_4', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 58, 'thanks_5', ''),
('string/en/spacequest/escort/naboo_rebel_3.stf', 59, 'title', 'Naboo system: Protect Alliance Refugee Transport.'),
('string/en/spacequest/escort/naboo_rebel_3.stf', 60, 'title_d', 'REDIRECT: Protect Alliance Refugee Transport.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 1, 'abort', 'Wait! You can''t leave me here rebel! I will be executed by the Empire!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 2, 'arrived_at_loc', 'Objective completed. Please stand by for our imperial contact...'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 9, 'complete', 'Objective completed. Good work, pilot!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 13, 'failed_destroy', 'Mission failed! The civilian shuttle was destroyed. Return to Ezkiel for further instruction...'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 14, 'failed_protect', 'Mission failed! Too far away from civilian shuttle to escort. Return to Ezkiel for further instruction...'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 15, 'found_loc', 'Escort rendez-vous coordinates confirmed. Proceed as planned.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 16, 'goodbye_1', 'Thank you for confirming the location of the infernal Vortex, Rebel Fool!.  Navy Command, position Verified. You may commence your attack!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 17, 'goodbye_2', 'Thank you for confirming the location of the infernal Vortex, Rebel Fool!.  Navy Command, position Verified. You may commence your attack!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 18, 'goodbye_3', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 21, 'hull_half', 'Pilot! My hull is half! Pay more attention to your mission!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 22, 'panic_1', 'Pilot! Pay attention! I''m getting hit here! The Empire must have found out about my willingness to help you! Save me!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 23, 'panic_2', 'Do you have ancient equipment on that piece of junk? I''m getting attacked here! The Empire must have found out about my helping you!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 24, 'panic_3', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 27, 'quest_escort_d', 'Escort the Imperial officer to the safety of our base. Make sure you are not followed.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 28, 'quest_escort_t', 'Escort the officer to safety.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 29, 'quest_location_d', 'Even though the Imperial forces are in chaos without their Inquisitor leader, they are not harmless so stay vigilant my friend.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 30, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 31, 'quest_rendezvous_d', 'The defecting Imperial officer has commanded a civilian marked freighter to avoid detection. He''s provided us with these coordinates as the meeting spot. Be careful, we are not completely sure we can trust him.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 32, 'quest_rendezvous_t', 'Rendez-vous with the Imperial officer.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 33, 'quest_update', 'Vortex Command: < %TO >'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 34, 'reason_1', 'I''m glad you''re here pilot. I was afraid no one would show up. Lets get over to your base where I''ll be safe.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 35, 'reason_2', 'I''m glad you''re here pilot. I was afraid no one would show up. Lets get over to your base where I''ll be safe.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 36, 'reason_3', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 39, 'shields_depleted', 'My shields! Pilot, get me out of here!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 40, 'split_quest_alert', 'Brother Ezkiel: < The Imperial officer was a spy! We''ve detected enemy ships on the way to your location. >'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 42, 'taunt_1', 'Fools! You''ll never get away from us! It''s no use! Give up!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 43, 'taunt_2', 'Give up while you can! You''ll never escape us!'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 44, 'taunt_3', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 47, 'thanks_1', 'Not too bad. Your skills are impressive. Thank you for the help.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 48, 'thanks_2', 'That was pretty close. I''m impressed by your flying skills. But I don''t think it''s over yet. Keep a close eye out for more Imperial ships.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 49, 'thanks_3', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 52, 'title', 'Dantooine system: Escort Imperial informant to base.'),
('string/en/spacequest/escort/naboo_rebel_tier3_1_a.stf', 53, 'title_d', 'With the timely demise of the Inquisitor at your hands, an Imperial officer has contacted us with the intent to defect. He claims to have information regarding the Force Crystal experiments and will share it with us if we provide him an escort to safety. That''s where your special skills come in my friend.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 1, 'abort', 'You..you''re leaving us to our death pilot..'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 2, 'arrived_at_loc', 'You are at the rendez-vous coordinates pilot, the freighter should be there any second.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 9, 'complete', 'Good job pilot, the freighter has jumped to lightspeed. Return to base.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 13, 'failed_destroy', 'We have lost contact with the freighter! You have some serious explanation to do pilot, return to base!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 14, 'failed_protect', 'We have lost contact with the freighter! You have some serious explanation to do pilot, return to base!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 15, 'found_loc', 'Rendez-vous with the personnel freighter at this location pilot. Protect it while the crew repair their hyperspace system.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 16, 'goodbye_1', 'Repairs complete, initiating jump to lightspeed. Thanks for the help pilot!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 17, 'goodbye_2', 'Repairs complete, initiating jump to lightspeed. Thanks for the help pilot!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 18, 'goodbye_3', 'Repairs complete, initiating jump to lightspeed. Thanks for the help pilot!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 19, 'goodbye_4', 'Repairs complete, initiating jump to lightspeed. Thanks for the help pilot!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 20, 'goodbye_5', 'Repairs complete, initiating jump to lightspeed. Thanks for the help pilot!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 21, 'hull_half', 'We are taking serious damage pilot!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 22, 'panic_1', 'I was wondering when they would be here.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 23, 'panic_2', 'I hope you''re good at this pilot.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 24, 'panic_3', 'Incoming TIE ships!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 25, 'panic_4', 'Son of a worrt, incoming lackeys of the Empire!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 26, 'panic_5', 'This could get really ugly...'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 27, 'quest_escort_d', 'The freighter crew is working as hard as they can to repair the hyperdrive system of their ship. Protect them from any attacks until they can perform their jump to lightspeed.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 28, 'quest_escort_t', 'Freighter repairing.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 29, 'quest_location_d', 'This area is extremely dangerous, the Empire is scouting it trying to find any of the freighters that did not manage to escape their attack. Be prepared for danger.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 30, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 31, 'quest_rendezvous_d', 'The freighter has requested that escort meet it at these coordinates. Get there immediately pilot.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 32, 'quest_rendezvous_t', 'Rendez-vous location.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 33, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 34, 'reason_1', 'Glad you were still here pilot. Protect us while we try to repair the hyperdrive systems.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 35, 'reason_2', 'Glad you were still here pilot. Protect us while we try to repair the hyperdrive systems.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 36, 'reason_3', 'Glad you were still here pilot. Protect us while we try to repair the hyperdrive systems.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 37, 'reason_4', 'Glad you were still here pilot. Protect us while we try to repair the hyperdrive systems.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 38, 'reason_5', 'Glad you were still here pilot. Protect us while we try to repair the hyperdrive systems.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 39, 'shields_depleted', 'Well there goes our shields. If you can''t take care of these TIE''s quickly, we''re in deep trouble.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 40, 'split_quest_alert', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 42, 'taunt_1', 'You''re not going anywhere Rebels!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 43, 'taunt_2', 'Here''s another one, lets take care of it!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 44, 'taunt_3', 'Our orders are simple men, leave none alive!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 45, 'taunt_4', 'Squad, listen up! Attack pattern Alpha!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 46, 'taunt_5', 'Time to teach these terrorists a lesson!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 47, 'thanks_1', 'We are still in one piece, lets keep moving!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 48, 'thanks_2', 'Great work pilot but we need more time to finish the repairs!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 49, 'thanks_3', 'Good job pilot, we''re almost done here.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 50, 'thanks_4', 'Almost home free!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 51, 'thanks_5', 'Nice shot pilot, glad to have you with us!'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 52, 'title', 'Endor system: Protect freighter while it repairs hyperdrive system.'),
('string/en/spacequest/escort/naboo_rebel_tier4_1_b.stf', 53, 'title_d', 'One of our personnel freighters have not been able to perform their jump to lightspeed due to a hyperdrive malfunction. We need you to provide escort of it while the crew repairs the broken system.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 1, 'abort', 'Wait! We have to get to the mining field! I have work to do too, you know!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 2, 'arrived_at_loc', 'Stay here, pilot, and wait for the freighter. The freighter and its cargo are cleared to head toward the mining field. This is meant to be an uneventful run other than the stray Valarian here and there. Report to me immediately if you see any sign of trouble. I expect there to be none.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 9, 'complete', 'You''re doing well so far, pilot. Soon, we''ll trust you with more sensitive missions. Thank you, again, for helping us. Times are dangerous and we can''t be too careful.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 13, 'failed_destroy', 'Pilot! This was suppose to be a *simple* mission! You''ve wasted innocent lives here!!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 14, 'failed_protect', 'Pilot! We had to launch emergency measures because you were too far away to escort the cleared freighter! This isn''t a science. It''s suppose to be easy!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 15, 'found_loc', 'The freighter will meet you here. You will then proceed to guide the cleared freighter to the mining field. Think you can handle that?'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 16, 'goodbye_1', 'Thank you for guiding us to our destination.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 17, 'goodbye_2', 'Thanks, pilot! It was very uneventful. Just how I like it.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 18, 'goodbye_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 21, 'hull_half', 'My hull is half! Help!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 22, 'panic_1', 'We''re getting hit!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 23, 'panic_2', 'Pilot! Pay attention! I''m under attack here!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 24, 'panic_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 27, 'quest_escort_d', 'Once I have met the freighter at the rendezvous point, I must guide the freighter to the mining field. I will then have completed my mission. It would be a good idea for me to wait for more intructions afterward.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 28, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 29, 'quest_location_d', 'I must travel to the Tatoo System to complete my task. If I''m in another system, It''d be a good idea for me to enable my hyperdrive and pick a location to jump to. (Use "h" to enable the Hyperspace Map and choose your destination).'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 30, 'quest_location_t', 'Travel to the Tatoo System'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 31, 'quest_rendezvous_d', 'A location, at which I will meet the said freighter, will be transmitted to me by A''Lerris Verata, the Mining Chief Operator. I must go there and wait for the freighter, after which I will guide it to safety.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 32, 'quest_rendezvous_t', 'Contact and Wait for the Freighter'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 33, 'quest_update', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 34, 'reason_1', 'Just hoping to get to the mining field alive. I hear there''s been more pirate attacks than we like these days.'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 35, 'reason_2', 'Just a normal miner looking to mine and transport goods back to home base. You think you can help me with that?'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 36, 'reason_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 39, 'shields_depleted', 'My shields are gone! You''re suppose to be protecting me!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 40, 'split_quest_alert', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < Nothing special, pilot. Another escort run. However, this time, you''re going to escort a freighter from the mining field back to home base. We don''t expect any problems. >'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 42, 'taunt_1', 'DIE!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 43, 'taunt_2', 'Going to get you! HAHA!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 44, 'taunt_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 47, 'thanks_1', 'Thanks!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 48, 'thanks_2', 'That was close!'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 49, 'thanks_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 52, 'title', 'Tatoo System: Earning Trust - Part I'),
('string/en/spacequest/escort/poi_tatooine_general2_1.stf', 53, 'title_d', 'A''Lerris Verata, the Mining Chief Operator of the Tatoo System''s mining efforts, has instructed me to guide a cleared freighter from home base to a mining field not too far from here. She doesn''t expect any trouble from the nearby pirates, other than an occassional Valarian or two. A''Lerris mentioned that there has been heightened activity around the field and more pirates have been attacking as of late. I''m beginning to wonder why. Basically, A''Lerris and her employees don''t trust me. Why should they? They''re practically surrounded by Hutts daily and come in contact with them and their wicked schemes, diminishing any sliver of trust they may have reserved for anyone else. I hope to earn their respect. Maybe they''ll have more meaningful tasks for me. It''s not to say escorting freighters isn''t meaningful. I''m just looking for something... more.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 1, 'abort', 'Ahh! No! How am I suppose to get back safely?!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 2, 'arrived_at_loc', 'Wait here for the freighter to arrive. You''re doing well so far. I''m very grateful for your assistance. If this mission goes as well as the last, we''ll be giving you more sensitive projects. Keep your focus.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 9, 'complete', 'Well done, pilot. You''re quickly becoming an asset to us. You''ve helped us greatly.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 13, 'failed_destroy', 'Argh! What is wrong with you? You''re suppose to guide the freighter to *safety* not to death!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 14, 'failed_protect', 'Pilot! You''re walking on thin ice here. I can''t keep losing freighters because of you!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 15, 'found_loc', 'I''ve transmitted the location at which you''ll meet the freighter. Guide it to safety. Again, we expect no problems during this run. However, it would be wise to keep your systems alert for suspicious activity.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 16, 'goodbye_1', 'Another shipment for home base. Thank to you, pilot!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 17, 'goodbye_2', 'It''s good seeing you, pilot. Thanks for the escort! Be careful out there!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 18, 'goodbye_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 21, 'hull_half', 'Ah! My hull is at half! Help me out over here!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 22, 'panic_1', 'Argh! I just got my transport fixed! C''mon, pilot! Help me out here!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 23, 'panic_2', 'Whoa! Getting attacked over here!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 24, 'panic_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 27, 'quest_escort_d', 'Once I meet with the freighter''s captain, I will escort him and his cargo to the designated area. If pirates attack, I must be ready to fight them off. It''s only a matter of time before the pirates begin to notice my presence and learn of my goals.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 28, 'quest_escort_t', 'Escort the Freighter to Safety'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 29, 'quest_location_d', 'Again, I must travel to the Tatoo System if I''m not already there. I can do this by enabling my hyperdrives and picking a location to jump to. (Use "h" to enable the Hyperspace Map and choose your destination).'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 30, 'quest_location_t', 'Travel to the Tatoo System'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 31, 'quest_rendezvous_d', 'Again, I''ll need to meet with the freighter at the location I''m given by A''Lerris Verata. It should be easy to guess, once I''m there, where the freighter needs to go and how I''ll accomplish it.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 32, 'quest_rendezvous_t', 'Meet the Freighter'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 33, 'quest_update', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 34, 'reason_1', 'Hoping to make it to home base and drop off another shipment. Same ol'' stuff, pilot.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 35, 'reason_2', 'You look like you''re a veteran of this. Good. I have no fear, then. To home base!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 36, 'reason_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 39, 'shields_depleted', 'My shields are gone! Would you help me out over here?!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 40, 'split_quest_alert', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < Good work, pilot. We have another escort for you. Don''t worry. You''ll be able out of this type of work soon. >'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 42, 'taunt_1', 'Die!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 43, 'taunt_2', 'Kill the freighter!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 44, 'taunt_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 47, 'thanks_1', 'Thanks!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 48, 'thanks_2', 'Glad ya got that pirate off me!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 49, 'thanks_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 52, 'title', 'Tatoo System: Earning Trust - Part II'),
('string/en/spacequest/escort/poi_tatooine_general2_1_a.stf', 53, 'title_d', 'It''s amazing to realize how many lives have been affected by the Hutts and the evils of our galaxy. I hope to gain the trust of the miners here in the Tatoo System. The chance has been brought to me in the way of small tasks given to me by A''Lerris Verata, the strong leader of the mining efforts in this system. My second task is much like my first; I must escort a freighter from the mining field to home base so rich resources can be fed into their outpost. And, much like the last time, I will do well.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 1, 'abort', 'What are yeh doin'', pilot? Wha''s wit'' quitin'' all''o a sudden, eh?'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 2, 'arrived_at_loc', 'I''m glad to see you there, pilot. You know the drill. Meet the freighter and escort it to the mining field. It is crucial to be careful. I believe the pirates in the area have learned of our recent activity. I''d be prepared if I were you.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 9, 'complete', 'I''m amazed at your ability to weigh through the odds and focus. I''m very impressed and glad you''ve joined us in our goals. It is refreshing to have you on our team.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 13, 'failed_destroy', 'A tragic loss, pilot. You''re not to blame. The pirates have come in hard and took us by surprise. Either way, you''ve done well.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 14, 'failed_protect', 'Pilot! You''ve abandoned your post! This is dishonorable and disgraceful to our efforts! I''m very disappointed in you.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 15, 'found_loc', 'I''ve transmitted the location at which you''ll meet the final freighter. Complete this and we''ll move you onto more interesting activities.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 16, 'goodbye_1', 'Tha'' was an interestin'' run, eh pilot? I be glad yer wit'' us. Wit''out yeh, we would have been a goner.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 17, 'goodbye_2', 'I''m definitely goin'' teh need some repairs after tha'' run! HAHA!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 18, 'goodbye_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 21, 'hull_half', 'Would yeh get off yer keister an'' help us o''er here?! Our hull be sittin'' at half! Git o''er here an'' give us some pertection!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 22, 'panic_1', 'Ah! We be takin'' damage o''er here! Pirates be on us!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 23, 'panic_2', '''ey crew! Start hootin'' an'' hollerin'' at them pirates ''dere while they be shootin'' at us! Tha''ll git ''em goin''! HAHA! [You start to hear muffled voices and hearty laughter] "Arg!", "Arg, mateys!"'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 24, 'panic_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 27, 'quest_escort_d', 'Once I''ve met with the freighter, I must guide the freighter to the target location. Again, I must have my systems alert. There''s no doubt that, during this task, pirates will attack. I have to prepare myself. For the freighter''s crew... and myself.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 28, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 29, 'quest_location_d', 'If I''m not in the Tatoo System already, I should get there by enabling my hyperspace drives and picking a jump stop within the Tatoo System. (Use "h" to enable the Hyperspace Map and choose your destination).'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 30, 'quest_location_t', 'Travel to the Tatoo System'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 31, 'quest_rendezvous_d', 'I''ve done this several times beforehand. I need to meet the freighter and crew at the transmission point that A''Lerris has given to me. If the freighter hasn''t arrived at the target location by the time I get there, I should wait. It will arrive soon.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 32, 'quest_rendezvous_t', 'Meet with the Freighter'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 33, 'quest_update', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 34, 'reason_1', 'Just lookin'' teh get back teh home base wit'' as lil''o trouble as possible.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 35, 'reason_2', 'Another rookie pilot! HAHA! Sorry, me friend. Git us teh home base iffin'' yeh would. We be grateful fer yer services.'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 36, 'reason_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 39, 'shields_depleted', 'Eh! Our shields be gone, yeh lazy pilot! Git o''er here an'' help us!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 40, 'split_quest_alert', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 42, 'taunt_1', 'Another tasty freighter for ME!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 43, 'taunt_2', 'I''m going to disable you and play with you like a cat does with its mouse! HA!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 44, 'taunt_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 47, 'thanks_1', 'Whew! Good job, pilot. Yer a good wingman!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 48, 'thanks_2', 'Tha'' was close. Nothin'' like a brush wit'' death, right? HA!'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 49, 'thanks_3', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 52, 'title', 'Tatoo System: Earning Trust - Part III'),
('string/en/spacequest/escort/poi_tatooine_general2_1_b.stf', 53, 'title_d', 'A''Lerris has promised me more interesting work once I''m through escorting the last freighter to the mining field. She''s warned me, very strongly, that the pirates in the area have noticed our activity. There''s no doubt, as I expected, that we''ll be attacked on this run. I must ready myself for the worst. Once I''ve completed this task, I will have gained the trust of A''Lerris and her employees.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 1, 'abort', 'You can''t abandon your mission, pilot!!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 2, 'arrived_at_loc', 'Stay here. The commander will arrive shortly. Always keep an eye out for Valarian influence. I feel they are near.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 9, 'complete', 'Fantastic work, pilot! Soon, we''ll launch the attack from Hutt Claims and be victorious!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 13, 'failed_destroy', 'We''ve failed our directive, pilot! You could have guarded the commander better!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 14, 'failed_protect', 'Pilot! You''ve failed to protect our commander!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 15, 'found_loc', 'I''ve transmitted the information to you as to where you''ll meet our war ships. Escort the commander safely and we''ll begin our attack. '),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 16, 'goodbye_1', 'Thank you, pilot. We''ll set up momentarily.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 17, 'goodbye_2', 'Thank yeh, pilot! Yer a good seed. We''re gonna set up ''ere at this point.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 18, 'goodbye_3', 'It''s about time. We''ll let you know when we''re ready for your help.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 21, 'hull_half', 'Pilot! Pay attention! We''re getting hit over here.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 22, 'panic_1', 'I''m getting attacked!!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 23, 'panic_2', 'Arh! Git yeh enemies off o'' me.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 24, 'panic_3', 'Pilot! I''m getting damaged! Get them off me!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 27, 'quest_escort_d', 'Escort the Commander and guide him back to Hutt Claims safely.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 28, 'quest_escort_t', 'Escort the Commander'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 29, 'quest_location_d', 'Travel to the Tatoo System.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 30, 'quest_location_t', 'Tatoo System'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 31, 'quest_rendezvous_d', 'Meet the Commander here and guide him back to Hutt Claims safely.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 32, 'quest_rendezvous_t', 'Meet the Commander'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 33, 'quest_update', '\\#pcontrast1 Garett:\\#pcontrast3 < %TO >'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 34, 'reason_1', 'You know what to do, pilot. Escort me to Hutt Claims.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 35, 'reason_2', 'We need teh git teh Hutt Claims teh launch our attack.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 36, 'reason_3', 'I''m ready to go. Let''s get this underway.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 39, 'shields_depleted', 'Ah! My shields are out!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 40, 'split_quest_alert', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < We''re ready for the battle. It should be a smooth attack. Wait.. I''m getting technical readout from my scanners that there are ships with armed weapon systems in the area. We may need your help, pilot! Help us out with this battle! >'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 42, 'taunt_1', 'Die Hutts!!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 43, 'taunt_2', 'You''ll never be successful in your launch against the Station, fools!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 44, 'taunt_3', 'You''ll never escape alive!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 47, 'thanks_1', 'That was close.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 48, 'thanks_2', 'Yer lucky, pilot.'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 49, 'thanks_3', 'Thanks for getting that Valarian off me!'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 52, 'title', 'Tatoo System: Escort the Commander'),
('string/en/spacequest/escort/poi_tatooine_privateer_3_a.stf', 53, 'title_d', 'You''ve been given the directive to escort the commander to Hutt Claims in the Tatoo System.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 1, 'abort', 'Wait! You can''t leave me here! If those Borvo thugs take my ship, I''ll be killed for sure!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 2, 'arrived_at_loc', 'Objective completed. Please stand by for our contact...'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 3, 'assigned_delayed', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 9, 'complete', 'Objective completed. Good work, pilot! I should be safe from here and be able to finish the delivery.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 13, 'failed_destroy', 'Mission failed! The civilian shuttle was destroyed. Return to Rori Station for further instruction...'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 14, 'failed_protect', 'Mission failed! Too far away from civilian shuttle to escort. Return to Rori Station for further instruction...'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 15, 'found_loc', 'Escort rally point coordinates confirmed. Proceed as planned.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 16, 'goodbye_1', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 17, 'goodbye_2', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 18, 'goodbye_3', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 21, 'hull_half', 'Pilot! My hull is half! Pay more attention to your mission!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 22, 'panic_1', 'Pilot! Pay attention! I''m getting hit here! Save me!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 23, 'panic_2', 'Do you have ancient equipment on that piece of junk? I''m getting attacked here!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 24, 'panic_3', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 27, 'quest_escort_d', 'Escort the freighter to a safe location for their delivery. Make sure you are not followed.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 28, 'quest_escort_t', 'Escort the freighter to safety.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 29, 'quest_location_d', 'Borvo''s pirates have ceaselessly interfered with the Rori Station and its ability to conduct business. That includes having repair droids delivered. They only want the cargo because taking it will disrupt station activity. It''s your job to make sure that does not happen.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 30, 'quest_location_t', 'Naboo System.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 31, 'quest_rendezvous_d', 'A new supplier has agreed to provide repair droids and to do so in secrecy. Protect their shipment.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 32, 'quest_rendezvous_t', 'Meet the freighter at the rally point.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 33, 'quest_update', 'Station Command: < %TO >'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 34, 'reason_1', 'I''m glad you''re here pilot. I was afraid no one would show up.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 35, 'reason_2', 'I''m glad you''re here pilot. I was afraid no one would show up.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 36, 'reason_3', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 39, 'shields_depleted', 'My shields! Pilot, get me out of here!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 40, 'split_quest_alert', 'Station Command: No, bad news! More Borvo pirates hit the freighter just before it could make its delivery,  and they made off with the cargo! After them!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 42, 'taunt_1', 'Fools! You''ll never get away from us! It''s no use! Give up!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 43, 'taunt_2', 'Give up while you can! You''ll never escape us!'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 44, 'taunt_3', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 47, 'thanks_1', 'Not too bad. Your skills are impressive. Thank you for the help.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 48, 'thanks_2', 'That was pretty close. I''m impressed by your flying skills. But I don''t think it''s over yet. Keep a close eye out for more pirate ships.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 49, 'thanks_3', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 52, 'title', 'Naboo system: Escort freighter to delivery point.'),
('string/en/spacequest/escort/rori_station_reb_storyquest_01_a.stf', 53, 'title_d', 'The Rori Station has asked for your help... and discretion... in helping to secure repair droids for the station.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 1, 'abort', 'What are you doing? I thought the station actually wanted this stuff.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 2, 'arrived_at_loc', 'Ok, wait here for the freighter with that plating to arrive. Once he shows up, escort the freighter to the Dantooine jump point.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming enemy fighters. >'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 5, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 9, 'complete', 'Ok, we have the freighter on our scans. Good work.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 13, 'failed_destroy', 'We needed that plating...what the ship? Who cares...I needed that plating!'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 14, 'failed_protect', 'Travel from assigned nav point to nav point looking for anything unusual.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 15, 'found_loc', 'Alright. He said he would meet us here. Get there and make sure he gets to Dantooine in one piece.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 16, 'goodbye_1', 'See ya, later. Can''t say I like this but I guess I was paid.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 17, 'goodbye_2', 'See ya, later. Can''t say I like this but I guess I was paid.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 18, 'goodbye_3', 'See ya, later. Can''t say I like this but I guess I was paid.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 19, 'goodbye_4', 'See ya, later. Can''t say I like this but I guess I was paid.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 20, 'goodbye_5', 'See ya, later. Can''t say I like this but I guess I was paid.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 21, 'hull_half', 'My hull is about to crack! This is the worst job I have ever taken.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 22, 'panic_1', 'Pirates! Keep them away from me.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 23, 'panic_2', 'No amount of money is worth this.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 24, 'panic_3', 'This is the last time I ever agree to go to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 25, 'panic_4', 'Going to Dantooine is bad luck...look at all those pirates!'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 26, 'panic_5', 'What is the deal with all of these pirates?'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 27, 'quest_escort_d', 'Escor the freighter through the system and protect it.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 28, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 29, 'quest_location_d', 'The Freighter is currently waiting in the Tatooine system for an escort.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 30, 'quest_location_t', 'Travel to the Tatooine System'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 31, 'quest_rendezvous_d', 'A navigation location will be supplied to you once you enter the Tatooine system. Meet the freighter at the arrival point.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 32, 'quest_rendezvous_t', 'Meet the Freighter'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 33, 'quest_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 34, 'reason_1', 'Ok, fine. If you watch my back as I head to the jump point, I will make the delivery to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 35, 'reason_2', 'Ok, fine. If you watch my back as I head to the jump point, I will make the delivery to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 36, 'reason_3', 'Ok, fine. If you watch my back as I head to the jump point, I will make the delivery to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 37, 'reason_4', 'Ok, fine. If you watch my back as I head to the jump point, I will make the delivery to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 38, 'reason_5', 'Ok, fine. If you watch my back as I head to the jump point, I will make the delivery to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 39, 'shields_depleted', 'Well, there went my shields. I hope your boss is going to pay for any damage I take.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 40, 'split_quest_alert', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 42, 'taunt_1', 'Look at that...a fat prize.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 43, 'taunt_2', 'Ah, a ship ripe with booty!'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 44, 'taunt_3', 'I think that cargo will fetch a hefty price.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 45, 'taunt_4', 'You should really just run now!'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 46, 'taunt_5', 'Avast matey...hand over the cargo and we might only blow your ship up.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 47, 'thanks_1', 'At least you are competent.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 48, 'thanks_2', 'I guess it could be worse.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 49, 'thanks_3', 'I still don''t want to go to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 50, 'thanks_4', 'Not sure which is worse...the pirates or having to go to Dantooine.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 51, 'thanks_5', 'At least you are competent.'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 52, 'title', 'Tatooine System: Escort the Lemdurion Plate Freighter'),
('string/en/spacequest/escort/stn_dantooine_owner_all_repairmission_tier2_2.stf', 53, 'title_d', 'The Dantooine station had made an agreement to buy a shipment of cargo out of the Tatooine system. The freighter refuses to make the jump to Dantooine unless someone can escort it through the system. You need to escort the target through the system.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 1, 'abort', 'I am not hanging around here with no escort.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 2, 'arrived_at_loc', '\\#pcontrast3 Endor Station: < \\#pcontrast1 The transport will be joining you shortly. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 6, 'autorewardbody', 'Completion Bonus: The Long Way Home (10000)'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 7, 'autorewardfrom', 'Endor Station'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 8, 'autorewardsubject', 'The Long Way Home'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 9, 'complete', 'The freighter is safely on its way to the Research Station.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 13, 'failed_destroy', '\\#pcontrast3 Endor Station: < \\#pcontrast1 I will have to notify Imperial Command about this failure.  They were counting on this shipment. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 14, 'failed_protect', '\\#pcontrast3 Transport: < \\#pcontrast1 This operation is a bust. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 15, 'found_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Calculated rendezvous point locked in. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 16, 'goodbye_1', 'Thanks Captain, I knew you would see us through.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 17, 'goodbye_2', 'This is Transport IZ-5W44 signing off.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 18, 'goodbye_3', 'Shipment delivered almost on time even.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 21, 'hull_half', 'Hull integrity is at critical levels.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 22, 'panic_1', 'Ah, there they are.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 23, 'panic_2', 'More Rebels.  Not sure if they are from around here or they tracked us from Naboo.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 24, 'panic_3', 'Fighters coming in quickly.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 27, 'quest_escort_d', 'Escort the Imperial transport, guarding against further Rebel Assault.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 28, 'quest_escort_t', 'Escort'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 29, 'quest_location_d', 'Entering from the nearest hyperspace point the freighter will make their way to the Endor Station and safety.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 30, 'quest_location_t', 'Endor System'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 31, 'quest_rendezvous_d', 'Travel here to meet the transport coming in from the Naboo System.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 32, 'quest_rendezvous_t', 'Rendezvous Location'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 33, 'quest_update', '%TO'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 34, 'reason_1', 'Good to see you made it through ok Captain.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 35, 'reason_2', 'Ok, lets get underway.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 36, 'reason_3', 'I don''t expect those Rebels have given up already.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 39, 'shields_depleted', 'Shield energies have been drained, our hull is vulnerable.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 40, 'split_quest_alert', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Captain I have a relay from the Fleet. A Nova Courier has come out of hyperspace not far from your location.  They request that you make a sortie against this target if the opportunity presents itself in light of your current obligations to the Transport.  There are no overriding priorities, the choice is up to you. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 42, 'taunt_1', 'You Imperials are always up to some problems.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 43, 'taunt_2', 'This shipment will not pass.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 44, 'taunt_3', 'What research components have a radioactive signature that large?'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 47, 'thanks_1', 'Great job.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 48, 'thanks_2', 'We are almost through, just hold them a bit longer.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 49, 'thanks_3', 'Almost there.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 52, 'title', 'Endor System: The Long Way Home'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_1b.stf', 53, 'title_d', 'Finish the repair and recovery of the Imperial transport by bringing them safely to the station in Endor.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 1, 'abort', '\\#pcontrast3 Fariso: < \\#pcontrast1 We are making the jump, this mission is too dangerous to fly with no escort.  Marsh out. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 2, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Rendezvous location reached. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 6, 'autorewardbody', 'Your duty was cut a bit short, but I always tip my escort.  My ship, my crew and myself are all out in one piece, so here is a little something from all of us. - Jenson Marsh, Captain of the Fariso'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 7, 'autorewardfrom', 'Jenson Marsh'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 8, 'autorewardsubject', 'For your efforts'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 9, 'complete', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Thank you for getting them through Captain.  Knowing he is safe is a great comfort. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 13, 'failed_destroy', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Oh dear, those poor pilots.  This is very sad indeed. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 14, 'failed_protect', '\\#pcontrast3 Fariso: < \\#pcontrast1 I am not willing to risk my neck with a suspect pilot, we are jumping out.  Fariso out. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 15, 'found_loc', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Here is the location where you can meet the Fariso.  Captain Marsh can be terse, but is not really a bad person. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 16, 'goodbye_1', 'Well it looks like you have more important things to deal with Captain, we are taking off.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 17, 'goodbye_2', 'Can''t argue with directives from Command, get to it Captain.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 18, 'goodbye_3', 'We can make this jump on our own.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 19, 'goodbye_4', 'Maybe we can work together again sometime Captain.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 21, 'hull_half', '\\#pcontrast3 Marsh: < \\#pcontrast1 Either I''ve picked up some Viridian termites, or you don''t know how to keep those fighters off our back.  Which is it Captain? \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 22, 'panic_1', 'Raiders, bottom feeders of the Endor System.  They should be no match for you.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 23, 'panic_2', 'It is times like this that make me miss my TIE.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 24, 'panic_3', 'Maybe I''ll just stick my blaster out a window, I must have monkeys manning my turrets.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 25, 'panic_4', 'Well don''t just sit around, get after them.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 27, 'quest_escort_d', 'Escort the Fariso and their cargo safely to the Research Station on Endor'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 28, 'quest_escort_t', 'Escort'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 29, 'quest_location_d', 'The Endor System, while not known for heavy pirate activity, is certainly dangerous to a lone freighter.  Increased Imperial presence due to the new Research Station have caused tensions with the unexpected Rebel population in this area and more forces have slowly moved into the system to combat this presence.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 30, 'quest_location_t', 'Endor System'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 31, 'quest_rendezvous_d', 'The Fariso is expected to make their jump into the System at this point'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 32, 'quest_rendezvous_t', 'Rendezvous Point'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 33, 'quest_update', '%TO'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 34, 'reason_1', 'We evaded two groups of Raiders and one Rebel patrol yesterday, so keep your eyes open.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 35, 'reason_2', 'Hearing that TIE roar brings me back to my Navy days.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 36, 'reason_3', 'Look at this, a proper escort.  You would think I was carrying something important.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 37, 'reason_4', 'Try to stay close Captain, I have a bad feeling about todays flight.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 39, 'shields_depleted', '\\#pcontrast3 Fariso: < \\#pcontrast1 Shields are down.  I am starting to wonder who''s side you are on Captain. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 40, 'split_quest_alert', '\\#pcontrast3 Kilnstrider: < \\#pcontrast1 Admiral Kilnstrider here, this operation is under my authority now. There is activity near an unattended nebula, take down one of those ships and find what they are carrying.  Do not ask questions, just complete the search. Kilnstrider out. > \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 42, 'taunt_1', 'A fat and juicy cargo ship for us to get our riches.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 43, 'taunt_2', 'Just go away now Imperial dog, you do not want to mess with the likes of us.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 44, 'taunt_3', 'Your cargo will be mine, and I am perfectly willing to scrape whatever I can from your wreckage.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 45, 'taunt_4', 'You are no match for me little man.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 47, 'thanks_1', 'That is all we ever get from these pirates.  A lot of talk that they never deliver on.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 48, 'thanks_2', 'Way to show them the business end of Imperial technology.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 49, 'thanks_3', 'Haha, that put them in their place.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 50, 'thanks_4', 'There never seems to be a shortage of fools.'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 52, 'title', 'Endor System: Bring in the Fariso'),
('string/en/spacequest/escort/stn_endor_irs_imp_tier3_2a.stf', 53, 'title_d', 'The Fariso is a civilian YT-1300 piloted by a retired TIE pilot named Jenson Marsh working on contract with the Imperial Research Station on Endor.  Today''s cargo has be classified as important enough to warrant a fighter escort as they make their approach to the station.  Your mission is to rendezvous with the Transport as they enter the system and see them safely to the landing station in orbit around Endor.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 1, 'abort', 'The VIP''s are too valuable for this sort of disregard.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 2, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Designated rendezvous point reached. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Comptuer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 6, 'autorewardbody', 'You do good work.  We are sending something you way... 10000 credits isn''t much, but we like to show a little appreciation.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 7, 'autorewardfrom', 'Vestil'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 8, 'autorewardsubject', 'A Tip for Ya'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 9, 'complete', 'The Kimigila''s Claw is away.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 13, 'failed_destroy', '\\#pcontrast3 Vestil < \\#pcontrast1 The Kimogila''s claw is lost and our generals killed.  We are finished! \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 14, 'failed_protect', '\\#pcontrast3 You have failed to protect the Kimogila''s Claw'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 15, 'found_loc', '\\#pcontrast3 Vestil: < \\#pcontrast1 I have uploaded the rendezvous point for the Kimigila''s claw to you.  Do not lose this transport, they are vital to our continued operations. Storm Squadron wants this transport.  They will come fast and often, stay with it and get them through. \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 16, 'goodbye_1', 'We are through.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 17, 'goodbye_2', 'Making the jump to lightspeed now.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 18, 'goodbye_3', 'Kimogila''s Claw, out.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 19, 'goodbye_4', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 20, 'goodbye_5', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 21, 'hull_half', 'Hull integrity is at half. '),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 22, 'panic_1', 'Fighters inbound.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 23, 'panic_2', 'Stay focused, they will not miss this opportunity.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 24, 'panic_3', 'Imperials detected.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 25, 'panic_4', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 26, 'panic_5', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 27, 'quest_escort_d', 'Protect the Claw and her important cargo'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 28, 'quest_escort_t', 'Kimogila''s Claw'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 29, 'quest_location_d', 'The travel route for the Kimogila''s Claw is classified, but we have reason to believe this information was compromised.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 30, 'quest_location_t', 'Lok System'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 31, 'quest_rendezvous_d', 'Travel here to meet the Transport'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 32, 'quest_rendezvous_t', 'Rendezvous Point'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 33, 'quest_update', '\\#pcontrast3 < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 34, 'reason_1', 'We have some important cargo today.  Do NOT fail us Captain.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 35, 'reason_2', 'I do not believe that the Imperials would pass up a target like this.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 36, 'reason_3', 'I know we have a mole... I suspect that zabrak woman, she is the only one that could sell us out.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 37, 'reason_4', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 38, 'reason_5', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 39, 'shields_depleted', 'Our deflector shields are down.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 40, 'split_quest_alert', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 42, 'taunt_1', 'You were foolish to think you could get away.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 43, 'taunt_2', 'Oberhaur will give me a promotion for this!'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 44, 'taunt_3', 'You will not make it through.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 45, 'taunt_4', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 46, 'taunt_5', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 47, 'thanks_1', 'The cargo is still safe, for now.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 48, 'thanks_2', 'The Imperials want this system, this pressure is unrelenting.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 49, 'thanks_3', 'Rather weak storm if you ask me.'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 50, 'thanks_4', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 51, 'thanks_5', ''),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 52, 'title', 'Lok System: Shelter from the Storm'),
('string/en/spacequest/escort/stn_lok_nym_reb_tier2_2a.stf', 53, 'title_d', 'With mounting pressure from the Empire, Nym has called in several of his highest ranking Captains to mount directed operations against the Empire and Storm Squadron forces operating in the Lok System.  You are charged to protect this transport at all costs.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 1, 'abort', 'Hey, you were hired to do a job. If you leave us out here we are going to fall into the same situation as that last executive.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 2, 'arrived_at_loc', 'Wait at this location for our executive transport to jump into the system.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 4, 'attack_notify', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 5, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 9, 'complete', 'The executive is safely at our headquarters. Return to Yavin station.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 10, 'escort_too_far1', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 11, 'escort_too_far2', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 12, 'escort_too_far3', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 13, 'failed_destroy', 'You lost another one? I know we have alot of executives but we will eventually run out. Maybe you should come back to the station for a while.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 14, 'failed_protect', 'You lost another one? I know we have alot of executives but we will eventually run out. Maybe you should come back to the station for a while.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 15, 'found_loc', 'Arrival location of the executive transport has been sent to your flight computer.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 16, 'goodbye_1', 'Thanks for watching my back.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 17, 'goodbye_2', 'Good work, pilot. The company certainly could use someone like you around.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 18, 'goodbye_3', 'I am proud of you. With you skills and my leadership we could go far.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 19, 'goodbye_4', 'It is a good thing I was there to direct you. We could have been in real trouble out there.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 20, 'goodbye_5', 'Someday you might amount to something.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 21, 'hull_half', 'You are supposed to protect me. My hull is cracking...get them off of me!'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 22, 'panic_1', 'Time for you to get to work.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 23, 'panic_2', 'Stop your loafing and get in there.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 24, 'panic_3', 'Remember take out the lead fighter first.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 25, 'panic_4', 'Maybe you should try using your...what are they called...oh yeah blasters on them.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 26, 'panic_5', 'You distract them while I try to sneak away.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 27, 'quest_escort_d', 'Escort the new executive through the system and protect him from any of the Debris Cultists who might try to stop him.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 28, 'quest_escort_t', 'Escort the Transport'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 29, 'quest_location_d', 'The new executive will meet you in the Yavin system.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 30, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 31, 'quest_rendezvous_d', 'Travel to the arrival location and wait for the arrival of the new executive.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 32, 'quest_rendezvous_t', 'Meet the Transport'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 33, 'quest_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 34, 'reason_1', 'Aren''t you the pilot who lost my successor? Never mind, just get me to the station.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 35, 'reason_2', 'Aren''t you the pilot who lost my successor? Never mind, just get me to the station.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 36, 'reason_3', 'Aren''t you the pilot who lost my successor? Never mind, just get me to the station.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 37, 'reason_4', 'Aren''t you the pilot who lost my successor? Never mind, just get me to the station.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 38, 'reason_5', 'Aren''t you the pilot who lost my successor? Never mind, just get me to the station.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 39, 'shields_depleted', 'Well, there went our shields. I need you to get them off of us immediately.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 40, 'split_quest_alert', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 41, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 42, 'taunt_1', 'We will show you company men what it is like to become one with the debris.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 43, 'taunt_2', 'You have taken your last piece of holy ground.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 44, 'taunt_3', 'I shall be traveling to nirvana soon.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 45, 'taunt_4', 'Do not fear them my brothers. They do not have faith!'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 46, 'taunt_5', 'The might of the great fireball is on my side!'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 47, 'thanks_1', 'So you do have some talent. Good!'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 48, 'thanks_2', 'You would have done better if you had followed my instructions.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 49, 'thanks_3', 'Next time, try to destroy them faster.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 50, 'thanks_4', 'I have a deadline to make. Let''s keep moving.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 51, 'thanks_5', 'Sloppy, very sloppy.'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 52, 'title', 'Yavin System: Escort the Yavin Mining Co. Executive'),
('string/en/spacequest/escort/stn_yavin4_company_all_opening_tier2_3.stf', 53, 'title_d', 'Even though you lost the last executive for the company, they had a back up plan. Another executive is waiting to enter the system but needs an escort through the system.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 2, 'abort', 'Things are too hot.  I don''t think we can make it.  We''re pulling out and heading back to base.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 3, 'arrived_at_loc', 'Wait here for the Imperial transport.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 5, 'attack_notify', 'Warning! Hostiles detected on attack vector. Defend our transport!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 6, 'attack_stopped', 'All enemy fighters have been eliminated.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 7, 'attack_warn_1', 'Heads up! Some of the pirates have caught up with us!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 8, 'attack_warn_2', 'More pirates are moving in to attack!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 9, 'attack_warn_3', 'A wing of pirates are making an attack run!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 10, 'autorewardbody', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 11, 'autorewardfrom', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 12, 'autorewardsubject', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 13, 'complete', 'The transport is safely away! Report back in to your superior officer.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 14, 'escort_too_far1', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 15, 'escort_too_far2', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 16, 'escort_too_far3', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 17, 'failed_destroy', 'Mission failed! The transport has been destroyed!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 18, 'failed_protect', 'Mission failed! The transport was lost!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 19, 'found_loc', 'A waypoint to the Imperial transport has been found. Uploading to navi-computer, now...'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 20, 'goodbye', 'We can make it from here.  Thanks for the escort, pilot.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 21, 'goodbye_1', 'Thanks for the escort, pilot!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 22, 'goodbye_2', 'We can take it from here...'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 23, 'goodbye_3', 'Good work, pilot. We can take it from here.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 24, 'goodbye_4', 'Thanks for the escort. Signing off...'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 25, 'goodbye_5', 'Appreciate the help, pilot. Preparing to jump to lightspeed...'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 26, 'hello', 'Thanks for responding, pilot.  We managed to shake the pirates, but they might come back.  We need a combat escort to our embarkation point.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 27, 'hull_half', 'Get to work, pilot! Hull is at fifty percent!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 28, 'panic_1', 'Requesting assistance! Incoming hostiles!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 29, 'panic_2', 'Get those bandits, pilot!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 30, 'panic_3', 'Look out! Incoming fighters!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 31, 'panic_4', 'Hey! Take out those fighters before they destroy us!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 32, 'panic_5', 'We are under attack!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 33, 'quest_escort_d', 'Once you have met up with the freighter, wait for it to beginning flying along its assigned route. Follow the freighter and keep a close watch out for pirate fighters who might try to capture or destroy the vessel. Once it has reached it designated, it will leave the area and your mission will be complete.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 34, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 35, 'quest_location_d', 'Remain in the Tatooine system. Once you finish the patrol, you will receive a navigation waypoint to the freighter''s arrival location. Travel to this location and wait for the arrival of the freighter.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 36, 'quest_location_t', 'Remain in the Tatooine System'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 37, 'quest_rendezvous_d', 'Travel to the navigation waypoint supplied to your by Imperial Flight Command. Wait at the arrival waypoint for the freighter to arrive.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 38, 'quest_rendezvous_t', 'Meet the Freighter'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 39, 'quest_update', '\\#pcontrast1 Imperial Command:\\#pcontrast1 <%TO>');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort/tatooine_imperial_3.stf', 40, 'reason_1', 'Cover us, pilot! We''ve been hounded by pirates ever since we left dry-dock!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 41, 'reason_2', 'We''ve got to get this cargo out of this system right away, pilot!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 42, 'reason_3', 'Pirates are after this cargo... with a ferocity we''ve never seen!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 43, 'reason_4', 'I''ve got to get this load of weapons out of the system, friend.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 44, 'reason_5', 'We shook the pirates at the last nav point, but I''m sure they''ll be back!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 45, 'shields_depleted', 'Our shields are gone!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 46, 'split_quest_alert', 'A new freighter carrying the important cargo is being sent to your system. Meet up with the freighter and make sure it reaches its destination.'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 47, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 48, 'taunt_1', 'Dump your cargo!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 49, 'taunt_2', 'Get out of our way, pilot!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 50, 'taunt_3', 'This transport is ours, squint!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 51, 'taunt_4', 'Back off, pal!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 52, 'taunt_5', 'This cargo is mine!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 53, 'thanks_1', 'Good shooting, pilot!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 54, 'thanks_2', 'Nice work, my friend!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 55, 'thanks_3', 'Keep it up, pilot!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 56, 'thanks_4', 'That''s how to do it, buddy!'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 57, 'thanks_5', 'You''re pretty handy with that thing, huh?'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 58, 'title', 'Tatooine System: Escort the Imperial Transport'),
('string/en/spacequest/escort/tatooine_imperial_3.stf', 59, 'title_d', 'Remain in the Tatooine system and escort the freighter through the system. Once you finish the patrol in the Tatooine system, you will receive a navigation waypoint to the freighter''s arrival location. Travel to this location and wait for the freighter to arrive. Once the freighter arrives, follow it to its destination. You will have to keep it safe from any enemy fighters who attempt to stop it from reaching its destination.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 2, 'abort', 'High Command will hear about your failure in your duty, pilot.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 3, 'arrived_at_loc', 'Arrived at destination. Wait here for the arrival of the engineers'' transport and escort it safely through the system.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < No more fighter vessels within sensor range. >'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 10, 'complete', 'Good work, pilot. You have successfully protected the Empire''s engineers so they can begin work on a most important project.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 14, 'failed_destroy', 'The transport has been destroyed. High Command will be most displeased with your performance. Report to your superior immediately.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 15, 'failed_protect', 'What are you doing leaving the transport out there on it''s own. Your orders were to escort that transport through the system. Obedience is not an option! Report to your superior.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 16, 'found_loc', 'Coordinates confirmed and sent to your nav computer. Proceed to location and wait for the arrival of the transport.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 17, 'goodbye_1', 'Thanks for the escort, pilot. I wouldn''t have made it without you. These engineers are highly important to the Imperial operation underway here in Endor.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 18, 'goodbye_2', 'Thanks for the escort, pilot. I wouldn''t have made it without you. These engineers are highly important to the Imperial operation underway here in Endor.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 19, 'goodbye_3', 'Thanks for the escort, pilot. I wouldn''t have made it without you. These engineers are highly important to the Imperial operation underway here in Endor.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 20, 'goodbye_4', 'Thanks for the escort, pilot. I wouldn''t have made it without you. These engineers are highly important to the Imperial operation underway here in Endor.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 21, 'goodbye_5', 'Thanks for the escort, pilot. I wouldn''t have made it without you. These engineers are highly important to the Imperial operation underway here in Endor.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 22, 'hull_half', 'Pilot, we are under heavy fire down here! Get those fighters off of me.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 23, 'panic_1', 'Rebels! What are they doing in the Endor system?'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 24, 'panic_2', 'We are under attack! You have to keep us safe.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 25, 'panic_3', 'Why are the Rebels interested in this system?'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 26, 'panic_4', 'Look out! Rebels are incoming.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 27, 'panic_5', 'Keep those fighters off our backs. We have to get these engineers to the staging area.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 28, 'quest_escort_d', 'Escort the engineers through the Endor system to their destination. We don''t expect any problems but if some arise, you are to take care of them.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 29, 'quest_escort_t', 'Escort the Engineer''s Transport'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 30, 'quest_location_d', 'You are to meet the engineers inside of the Endor system.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 31, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 32, 'quest_rendezvous_d', 'Travel to the navigation waypoint of the arrival location of the shuttle. Wait for the shuttle to arrive.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 33, 'quest_rendezvous_t', 'Meet the Engineer''s Transport'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 34, 'quest_update', '\\#pcontrast3 Storm Squadron Command:\\#pcontrast1 <%TO>'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 35, 'reason_1', 'Hello, pilot. We have the engineers and the core in storage. This should be a smooth flight.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 36, 'reason_2', 'Hello, pilot. We have the engineers and the core in storage. This should be a smooth flight.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 37, 'reason_3', 'Hello, pilot. We have the engineers and the core in storage. This should be a smooth flight.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 38, 'reason_4', 'Hello, pilot. We have the engineers and the core in storage. This should be a smooth flight.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 39, 'reason_5', 'Hello, pilot. We have the engineers and the core in storage. This should be a smooth flight.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 40, 'shields_depleted', 'We just lost our shields! We are not going to last much longer unless you can get those fighters off of us!'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 41, 'split_quest_alert', 'Another Engineer transport has been captured by Rebel pilots. Proceed immediately to last known location and recover the transport.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 43, 'taunt_1', 'Hand over the engineers and the core and no one will get hurt.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 44, 'taunt_2', 'We just want the transport.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 45, 'taunt_3', 'Don''t make this hard on yourself. Hand over the transport.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 46, 'taunt_4', 'That is the transport we are after. Focus all attacks on it.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 47, 'taunt_5', 'If we cannot capture the transport, our orders are to destroy it.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 48, 'thanks_1', 'Nice flying out there. Those Rebel fighters came out of no where. Almost like they were waiting for us.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 49, 'thanks_2', 'Nice flying out there. Those Rebel fighters came out of no where. Almost like they were waiting for us.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 50, 'thanks_3', 'Nice flying out there. Those Rebel fighters came out of no where. Almost like they were waiting for us.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 51, 'thanks_4', 'Nice flying out there. Those Rebel fighters came out of no where. Almost like they were waiting for us.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 52, 'thanks_5', 'Nice flying out there. Those Rebel fighters came out of no where. Almost like they were waiting for us.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 53, 'title', 'Endor System: Escort the Engineer''s Transport'),
('string/en/spacequest/escort/tatooine_imperial_tier3_1.stf', 54, 'title_d', 'The Empire has started a major undertaking in the Endor system. They have not been forthcoming with details about what they are doing, but they have a need for materials and manpower. Storm Squadron has been placed in charge of system security. Your first mission is to escort a shuttle of engineers coming from the Yavin salvage operation through the Endor system.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 2, 'abort', 'What are you doing, pilot? You are aborting too early. The Rebels will know this is a trap.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 3, 'arrived_at_loc', 'Wait for the decoy shuttle to arrive and then begin the mission. To completely sell this deception, you are going to have kill several attacking waves of enemy fighters before we can be sure the Rebels will think the information is genuine.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected. Incoming at high speeds.>'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter destroyed. Detecting no further ships.>'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 10, 'complete', 'You may have succeeded in getting the Rebels the plans but there is very little chance that they are going to believe that they are real. We cannot write this one off as a complete failure but you didn''t accomplish what was needed of you. Report back into your commander.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 11, 'escort_too_far1', 'Pilot, if you leave the decoy shuttle unprotected the Rebels will know something is wrong. Stay with the shuttle and destroy those Rebels so they think what is on that shuttle is important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 12, 'escort_too_far2', 'Pilot, the Rebels are getting suspicious. Get back here and put on a good show.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 13, 'escort_too_far3', 'Blast it! The Rebels are leaving, this is obviously a trap. Way to blow the operation. Report back to your superior.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 14, 'failed_destroy', 'Pilot, that was too easy. The Rebels might scan the wreckage and find the plans but they are never going to believe them. They are rebellious, not stupid. You are going to need to report back to your commander.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 15, 'failed_protect', 'Pilot, that was too easy. The Rebels might scan the wreckage and find the plans but they are never going to believe them.  They are rebellious, not stupid. You are going to need to report back to your commander.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 16, 'found_loc', 'Meet up with the decoy shuttle at supplied navigation location. Once the enemy attacks, destroy several of their attack waves. When we have their curiosity peeked, the shuttle will make a run for it and allow itself to be captured. Just make sure you put on a good show and destroy at least four attack waves.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 17, 'goodbye_1', 'Blast it! You didn''t destroy nearly enough of those fighters for the Rebels to be interested in following me. This mission is a big failure. Report back into your superior.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 18, 'goodbye_2', 'Blast it! You didn''t destroy nearly enough of those fighters for the Rebels to be interested in following me. This mission is a big failure. Report back into your superior.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 19, 'goodbye_3', 'Blast it! You didn''t destroy nearly enough of those fighters for the Rebels to be interested in following me. This mission is a big failure. Report back into your superior.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 20, 'goodbye_4', 'Blast it! You didn''t destroy nearly enough of those fighters for the Rebels to be interested in following me. This mission is a big failure. Report back into your superior.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 21, 'goodbye_5', 'Blast it! You didn''t destroy nearly enough of those fighters for the Rebels to be interested in following me. This mission is a big failure. Report back into your superior.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 22, 'hull_half', 'Hull is at half strength! I have to stay alive for longer or the Rebels will not buy the fake plans. Get them off of me and destroy some more waves!'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 23, 'panic_1', 'Excellent! It looks like the Rebels are coming to investigate. Put on a good show and make it look like you are protecting something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 24, 'panic_2', 'Excellent! It looks like the Rebels are coming to investigate. Put on a good show and make it look like you are protecting something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 25, 'panic_3', 'Excellent! It looks like the Rebels are coming to investigate. Put on a good show and make it look like you are protecting something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 26, 'panic_4', 'Excellent! It looks like the Rebels are coming to investigate. Put on a good show and make it look like you are protecting something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 27, 'panic_5', 'Excellent! It looks like the Rebels are coming to investigate. Put on a good show and make it look like you are protecting something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 28, 'quest_escort_d', 'Follow the decoy shuttle along its route. Destroy at least four waves of enemy fighters before the shuttle is destroyed or the shuttle reaches the end of its designated route.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 29, 'quest_escort_t', 'Escort the Decoy Shuttle'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 30, 'quest_location_d', 'The navigation waypoint to the arrival location of the decoy shuttle will be supplied to you.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 31, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 32, 'quest_rendezvous_d', 'Travel to the navigation waypoint and wait for the arrival of the shuttle.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 33, 'quest_rendezvous_t', 'Meeting the Decoy Shuttle'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 34, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 35, 'reason_1', 'Alright! We have the fake plans on our ship. Remember, you need to make this look real! Once the enemy attacks, destroy several of their attacking waves to make them think you are protecting some valuable information. Once we have done enough to sell our project, I will pretend to make a run for it and let the shuttle be captured.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 36, 'reason_2', 'Alright! We have the fake plans on our ship. Remember, you need to make this look real! Once the enemy attacks, destroy several of their attacking waves to make them think you are protecting some valuable information. Once we have done enough to sell our project, I will pretend to make a run for it and let the shuttle be captured.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 37, 'reason_3', 'Alright! We have the fake plans on our ship. Remember, you need to make this look real! Once the enemy attacks, destroy several of their attacking waves to make them think you are protecting some valuable information. Once we have done enough to sell our project, I will pretend to make a run for it and let the shuttle be captured.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 38, 'reason_4', 'Alright! We have the fake plans on our ship. Remember, you need to make this look real! Once the enemy attacks, destroy several of their attacking waves to make them think you are protecting some valuable information. Once we have done enough to sell our project, I will pretend to make a run for it and let the shuttle be captured.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 39, 'reason_5', 'Alright! We have the fake plans on our ship. Remember, you need to make this look real! Once the enemy attacks, destroy several of their attacking waves to make them think you are protecting some valuable information. Once we have done enough to sell our project, I will pretend to make a run for it and let the shuttle be captured.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 40, 'shields_depleted', 'There went our shields. We can''t let them capture me too early. The Rebels may be weak but they are not dumb. If they take me too easily, they will never buy it.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 41, 'split_quest_alert', 'That should be enough to get the Rebels convinced that those fake documents are the real deal. The decoy shuttle is making a run for it and will let himself get captured. Keep a close watch, because it looks like the Rebels have also developed an unhealthy interest in you. Destroy any vessels that attack you and stand by for further notice.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 43, 'taunt_1', 'You might as well run since you cannot win.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 44, 'taunt_2', 'Just hand over the transport and no one gets hurt.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 45, 'taunt_3', 'If I were you I would run, Imperial dog.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 46, 'taunt_4', 'You are going to regret trying to fight.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 47, 'taunt_5', 'You might as well run since you cannot win.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 48, 'thanks_1', 'That''s it! Keep it up. A little more of that and the Rebels will be absolutely convinced that this shuttle contains something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 49, 'thanks_2', 'That''s it! Keep it up. A little more of that and the Rebels will be absolutely convinced that this shuttle contains something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 50, 'thanks_3', 'That''s it! Keep it up. A little more of that and the Rebels will be absolutely convinced that this shuttle contains something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 51, 'thanks_4', 'That''s it! Keep it up. A little more of that and the Rebels will be absolutely convinced that this shuttle contains something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 52, 'thanks_5', 'That''s it! Keep it up. A little more of that and the Rebels will be absolutely convinced that this shuttle contains something really important.'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 53, 'title', 'Endor System: Destroy Four Rebel Fighter Waves'),
('string/en/spacequest/escort/tatooine_imperial_tier3_3_a.stf', 54, 'title_d', 'The fake orders have been planeted on this decoy shuttle. You are to follow the shuttle until the Rebels attack. You are going to have to make the Rebels believe that the shuttle contains highly important information. In order to do this, you need to destroy at least four waves of enemy fighters before they either destroy the decoy shuttle or the decoy shuttle reaches the end of its designated path.'),
('string/en/spacequest/escort/tatooine_imperial_tier4_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/tatooine_imperial_tier4_3.stf', 2, 'abort', 'Fool...do you know who I am? Your superior will be most displeased that you failed in your duty.'),
('string/en/spacequest/escort/tatooine_imperial_tier4_3.stf', 3, 'arrived_at_loc', 'Stand by for the arrival of the Inquisitior''s shuttle.'),
('string/en/spacequest/escort/tatooine_imperial_tier4_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/tatooine_imperial_tier4_3.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters detected.>'),
