('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 13, 'failed_destroy', 'Blast! We almost had him too. Report back to base pilot!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 14, 'failed_protect', 'The freighter had to do a emergency hyperspace jump because of your poor protection! If they didn''t make it, I will have you incarcerated pilot!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 15, 'found_loc', 'Rebel Command: < The Commando team was all but wiped out breaking out the Imperial defector but they got him. They are chased by numerous squads of TIE''s though and need your help! >'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 16, 'goodbye_1', 'This guy better be worth all this. Hold at this position pilot and take out any ships trying to follow us!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 17, 'goodbye_2', 'This guy better be worth all this. Hold at this position pilot and take out any ships trying to follow us!'),
