('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 20, 'goodbye_5', 'This guy better be worth all this. Hold at this position pilot and take out any ships trying to follow us!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 21, 'hull_half', 'We are taking massive hull damage pilot, think you can take care of these TIE''s?'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 22, 'panic_1', 'How many of these bastards are there!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 23, 'panic_2', 'TIE ships at 1 o''clock!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 24, 'panic_3', 'Boogeys incoming!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 25, 'panic_4', 'Blast! More Imperial fighters coming our way!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 26, 'panic_5', 'Lets avenge our fallen! Come and get it Imperial scum!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 27, 'quest_escort_d', 'Escort the commando team and the freed prisoner to safety. Know that you will come under heavy fire; we have sensors showing multiple hostile fighters closing in.'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 28, 'quest_escort_t', 'Escort commando team.'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 29, 'quest_location_d', 'You''re heading in to Imperial areas to help the commando team escape so expect severe resistance!'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 30, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 31, 'quest_rendezvous_d', 'The distress message from our commando team gave us these coordinates. It''s the furthest out of Imperial areas that they think they can make it on there own. Get over there immediately pilot!'),
