('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 33, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 34, 'reason_1', 'Lets get out of here pilot. My team was all but wiped out so I only have wounded men handling our weapon systems. We''re going to need your help.'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 35, 'reason_2', 'Lets get out of here pilot. My team was all but wiped out so I only have wounded men handling our weapon systems. We''re going to need your help.'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 36, 'reason_3', 'Lets get out of here pilot. My team was all but wiped out so I only have wounded men handling our weapon systems. We''re going to need your help.'),
('string/en/spacequest/escort/tatooine_rebel_tier3_3_b.stf', 37, 'reason_4', 'Lets get out of here pilot. My team was all but wiped out so I only have wounded men handling our weapon systems. We''re going to need your help.'),
