('string/en/spacequest/escort/vortex_mission_2.stf', 3, 'arrived_at_loc', 'You have arrived at the space station. Await docking confirmation.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/escort/vortex_mission_2.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/escort/vortex_mission_2.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 10, 'complete', 'We are lucky to have as skilled a pilot as you in our ranks my friend. Return to Dantooine.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 14, 'failed_destroy', 'We lost contact with our brother. Get out of there, now!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 15, 'failed_protect', 'I can''t make it on my own! I''m doing a emergency hyperspace jump, may the force be with us...'),
('string/en/spacequest/escort/vortex_mission_2.stf', 16, 'found_loc', 'Your navigation droid should upload the coordinates of the space station. Proceed as planned.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 17, 'goodbye_1', 'Thank you my friend, I could never have made it without you. See you back on Dantooine!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 18, 'goodbye_2', 'Thank you my friend, I could never have made it without you. See you back on Dantooine!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 19, 'goodbye_3', 'Thank you my friend, I could never have made it without you. See you back on Dantooine!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 20, 'goodbye_4', 'Thank you my friend, I could never have made it without you. See you back on Dantooine!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 21, 'goodbye_5', 'Thank you my friend, I could never have made it without you. See you back on Dantooine!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 22, 'hull_half', 'My hull has multiple breeches! I can''t take much more of this!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 23, 'panic_1', 'Here they come...'),
('string/en/spacequest/escort/vortex_mission_2.stf', 24, 'panic_2', 'TIE ships, hot on our tail!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 25, 'panic_3', 'Curse the Empire! TIE-Fighters inbound!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 26, 'panic_4', 'I don''t think they want the data, I think they want us dead...'),
('string/en/spacequest/escort/vortex_mission_2.stf', 27, 'panic_5', 'I hope your as good as they say pilot!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 28, 'quest_d', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 29, 'quest_escort_d', 'The Vortex scientist was ambushed inside the space station. You both need to escape the Yavin system. The scientist is not a good fighter pilot and need your escort out of there.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 30, 'quest_escort_t', 'The Empire on your heels.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 31, 'quest_location_d', 'The smuggler space station is located in the Yavin system, travel there immediately.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 32, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 33, 'quest_rendezvous_d', 'This is the location of a civilian space station, often used by the shadier inhabitants of the galaxy to make deals out of the view of the Empire. Get over there and dock with the station to meet with the Vortex scientist inside.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 34, 'quest_rendezvous_t', 'Smuggler space station.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 35, 'quest_t', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 36, 'quest_update', 'Brother Vrovel: < %TO >'),
('string/en/spacequest/escort/vortex_mission_2.stf', 37, 'reason_1', 'We need to get out of here! I got the data but Imperial Soldiers attacked me in the hangar!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 38, 'reason_2', 'We need to get out of here! I got the data but Imperial Soldiers attacked me in the hangar!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 39, 'reason_3', 'We need to get out of here! I got the data but Imperial Soldiers attacked me in the hangar!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 40, 'reason_4', 'We need to get out of here! I got the data but Imperial Soldiers attacked me in the hangar!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 41, 'reason_5', 'We need to get out of here! I got the data but Imperial Soldiers attacked me in the hangar!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 42, 'shields_depleted', 'My shields are fried! May the force be with us now my friend...'),
('string/en/spacequest/escort/vortex_mission_2.stf', 43, 'split_quest_alert', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 44, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/vortex_mission_2.stf', 45, 'taunt_1', 'Imperial Inquisition, cut your engines immediately!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 46, 'taunt_2', 'Foolish Rebels, the might of the Empire will crush you all!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 47, 'taunt_3', 'You are aiding a known criminal, step aside if you want to live!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 48, 'taunt_4', 'You''re all mine, Rebel scum!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 49, 'taunt_5', 'The will of the Emperor guides us, you are all doomed!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 50, 'thanks_1', 'We''re lucky to have you on our side my friend.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 51, 'thanks_2', 'Good work! We''re not home free just yet though, my nav computer is still working out the hyperspace jump.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 52, 'thanks_3', 'I owe you my life my friend! I will let Vrovel know of your bravery.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 53, 'thanks_4', 'Phew, I''m almost ready to make the jump to hyperspace. Hopefully that was the last of them.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 54, 'thanks_5', 'We''re almost home free my friend!'),
('string/en/spacequest/escort/vortex_mission_2.stf', 55, 'title', 'Yavin system: Bring research data to scientist.'),
('string/en/spacequest/escort/vortex_mission_2.stf', 56, 'title_d', 'Your orders are to travel to meet up with one of the Vortex scientists at a space station with the Imperial data. He''s there purchasing some additional information from a smuggler. The Vortex hope that the two pieces of data can be made sense out of by the scientist when combined.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 2, 'abort', 'Your commanding officer will hear about this!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 3, 'arrived_at_loc', 'You are at the right location. The shuttle should be here in a few seconds.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/yavin_rebel_13.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
