('string/en/spacequest/escort/yavin_rebel_13.stf', 16, 'found_loc', 'Move on to the designated meeting coordinates.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 17, 'goodbye_1', 'Alright, we are jumping to hyperspeed. Great work pilot, we couldn''t have made it out of there without you.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 18, 'goodbye_2', 'Alright, we are jumping to hyperspeed. Great work pilot, we couldn''t have made it out of there without you.'),
