('string/en/spacequest/escort/yavin_rebel_13.stf', 20, 'goodbye_4', 'Alright, we are jumping to hyperspeed. Great work pilot, we couldn''t have made it out of there without you.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 21, 'goodbye_5', 'Alright, we are jumping to hyperspeed. Great work pilot, we couldn''t have made it out of there without you.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 22, 'hull_half', 'Our ship is falling apart pilot, we need help quickly!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 23, 'panic_1', 'Ack! Imperial patrol, they spotted us!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 24, 'panic_2', 'TIE ships, hot on our tail!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 25, 'panic_3', 'Curse the Empire! TIE-Fighters inbound!'),
