INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort/yavin_rebel_13.stf', 27, 'panic_5', 'Bah! An Imperial patrol closing in!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 28, 'quest_escort_d', 'Escort the freighter and it''s precious cargo safely out of the Yavin system. Stay close and stay alert!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 29, 'quest_escort_t', 'Escort the freighter.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 30, 'quest_location_d', 'The Yavin system is crawling with Imperial fighters and they have put up a blockade around the moon of Yavin 4. You will without a doubt be kept busy so be ready for a fight!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 31, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 32, 'quest_rendezvous_d', 'The Rebel freighter will stay hidden until you arrive at this location.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 33, 'quest_rendezvous_t', 'Rendez-vous with the freighter.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 34, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 35, 'reason_1', 'Good to see you pilot. Apparently this lady is really important so stay sharp.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 36, 'reason_2', 'Good to see you pilot. Apparently this lady is really important so stay sharp.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 37, 'reason_3', 'Good to see you pilot. Apparently this lady is really important so stay sharp.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 38, 'reason_4', 'Good to see you pilot. Apparently this lady is really important so stay sharp.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 39, 'reason_5', 'Good to see you pilot. Apparently this lady is really important so stay sharp.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 40, 'shields_depleted', 'We just lost our shields! Hang on Lady, it''s going to get bumpy!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 41, 'split_quest_alert', ''),
('string/en/spacequest/escort/yavin_rebel_13.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/yavin_rebel_13.stf', 43, 'taunt_1', 'We have the highest authority of the Imperial Inquisition to destroy them, no mercy guys!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 44, 'taunt_2', 'You are not going anywhere, foolish Rebels!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 45, 'taunt_3', 'Get some! Get some!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 46, 'taunt_4', 'The might of the Empire is unstoppable, puny Rebels!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 47, 'taunt_5', 'This is the last day of your life, foolish Rebels!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 48, 'thanks_1', 'You okay M''Lady? We''re fine over here pilot, great work out there!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 49, 'thanks_2', 'Yeah! Take that, Imperial filth!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 50, 'thanks_3', 'Whow! Did you see that M''Lady? Those TIE''s won''t bother us again!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 51, 'thanks_4', 'Great job pilot! Hopefully they didn''t call for backup.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 52, 'thanks_5', 'More of the Emperors drones turned in to space junk, nice going pilot!'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 53, 'title', 'Yavin system: Escort important person out of the Yavin system.'),
('string/en/spacequest/escort/yavin_rebel_13.stf', 54, 'title_d', 'You are ordered to provide escort for a freighter trying to get through the Imperial blockade around Yavin 4. The lady being transported is apparently extremely important to the Alliance and can not be harmed or captured by the Empire. We are counting on you pilot!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 2, 'abort', 'I can''t take this on my own, performing emergency hyperspace jump!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 3, 'arrived_at_loc', 'You are at the rendez-vous coordinates. Wait for the smuggler to arrive.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/escort/yavin_rebel_16.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
