('string/en/spacequest/escort/yavin_rebel_16.stf', 10, 'complete', 'The smuggler has made it to safety. Good work pilot!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 11, 'escort_too_far1', ''),
('string/en/spacequest/escort/yavin_rebel_16.stf', 12, 'escort_too_far2', ''),
('string/en/spacequest/escort/yavin_rebel_16.stf', 13, 'escort_too_far3', ''),
('string/en/spacequest/escort/yavin_rebel_16.stf', 14, 'failed_destroy', 'Hello?! We have lost contact with the smuggler, what''s happening up there pilot?!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 15, 'failed_protect', 'The smuggler have too many fighters on him, he''s trying a emergency hyperspace jump!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 16, 'found_loc', 'Meet the smuggler at these coordinates pilot.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 17, 'goodbye_1', 'Thanks for the escort pilot, I''m jumping to hyperspace. See you back at base!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 18, 'goodbye_2', 'Thanks for the escort pilot, I''m jumping to hyperspace. See you back at base!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 19, 'goodbye_3', 'Thanks for the escort pilot, I''m jumping to hyperspace. See you back at base!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 20, 'goodbye_4', 'Thanks for the escort pilot, I''m jumping to hyperspace. See you back at base!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 21, 'goodbye_5', 'Thanks for the escort pilot, I''m jumping to hyperspace. See you back at base!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 22, 'hull_half', 'I''m tracking multiple hull breaches! I can''t take much more damage. Help!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 23, 'panic_1', 'An Imperial patrol picked us up, prepare for a fight!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 24, 'panic_2', 'Imperials, they are gunning for us!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 25, 'panic_3', 'And I was hoping we could slip out of here undetected...'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 26, 'panic_4', 'TIE-Fighters, help me out here pilot!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 27, 'panic_5', 'TIE''s incoming, give them a warm welcome pilot!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 28, 'quest_escort_d', 'Escort the Nym smuggler to the Rebel space station. Keep your eyes open, the Empire seems to be one step ahead of us through out this entire operation.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 29, 'quest_escort_t', 'Escort the Nym smuggler.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 30, 'quest_location_d', 'You are to head to the Lok system to meet up with one of Nym''s smugglers. The Lok system is relatively safe from the Empire but it''s heavily inhabited by different pirate factions on the look out for a lone traveler so stay sharp!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 31, 'quest_location_t', 'Lok system.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 32, 'quest_rendezvous_d', 'The Nym smuggler has provided us with these coordinates for your rendez-vous. Make haste over there.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 33, 'quest_rendezvous_t', 'Coordinates of the Nym smuggler.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 34, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 35, 'reason_1', 'Alright, so we''re taking this stuff to our outpost. Keep an eye out for Imperial patrols pilot.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 36, 'reason_2', 'Alright, so we''re taking this stuff to our outpost. Keep an eye out for Imperial patrols pilot.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 37, 'reason_3', 'Alright, so we''re taking this stuff to our outpost. Keep an eye out for Imperial patrols pilot.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 38, 'reason_4', 'Alright, so we''re taking this stuff to our outpost. Keep an eye out for Imperial patrols pilot.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 39, 'reason_5', 'Alright, so we''re taking this stuff to our outpost. Keep an eye out for Imperial patrols pilot.'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 40, 'shields_depleted', 'My shields are out, you better take care of these guys fast pilot!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 41, 'split_quest_alert', ''),
('string/en/spacequest/escort/yavin_rebel_16.stf', 42, 'split_quest_alert_fail', ''),
('string/en/spacequest/escort/yavin_rebel_16.stf', 43, 'taunt_1', 'We are detecting illegal cargo on your ship. Cooperate and you will not be harmed!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 44, 'taunt_2', 'Blasted Rebels, you''re not getting out of this one!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 45, 'taunt_3', 'You stuck your nose in too deep this time Rebels!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 46, 'taunt_4', 'I usually eat Rebel scum for breakfast but I guess dinner is fine as well!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 47, 'taunt_5', 'You can''t match our skill Rebels, you may as well give up!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 48, 'thanks_1', 'Great working with you pilot. I''ll be safe from here, see you around!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 49, 'thanks_2', 'Great working with you pilot. I''ll be safe from here, see you around!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 50, 'thanks_3', 'Great working with you pilot. I''ll be safe from here, see you around!'),
('string/en/spacequest/escort/yavin_rebel_16.stf', 51, 'thanks_4', 'Great working with you pilot. I''ll be safe from here, see you around!'),
