('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 11, 'failed_destroy', 'The scanning craft has been destroyed. Lets hope this blunder does not cause other craft to fall victem as well.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 12, 'failed_protect', 'You have failed to protect the scanning vessel.  Return to base at once.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 13, 'found_loc', 'Travel to the waypoint and await the arrival of our scanning craft.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 14, 'goodbye_1', 'Good job on the escort, enemy activity will continue to be monitored.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 15, 'goodbye_2', 'I hope to meet you at the cantina back on the ground.  I owe you one.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 16, 'goodbye_3', 'I thought I was done for a couple times, way to pull it through!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 17, 'goodbye_4', 'I thought I was done for a couple times, way to pull it through!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 18, 'goodbye_5', 'I thought I was done for a couple times, way to pull it through!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 19, 'hull_half', 'Hull integrity down to half.  Get these Rebels off of me!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 20, 'panic_1', 'Rebels!  This is not an assault craft, protect me!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 21, 'panic_2', 'You can''t let me die!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 22, 'panic_3', 'Keep them off while I continue the scan!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 23, 'panic_4', 'Enemy fighters are here!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 24, 'panic_5', 'Rebels!  This is not an assault craft, protect me!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 25, 'quest_escort_d', 'Follow the freighter to it''s destination. Keep it protected from any enemy fighter that might try to take it''s cargo.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 26, 'quest_escort_t', 'Protect the Imperial Freighter'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 27, 'quest_location_d', 'The freighters will be jumping into Corellia system and need to have their escort meet them. You will be supplied the arrival location of your assigned vessel. Meet the vessel at this location.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 28, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 29, 'quest_rendezvous_d', 'The freighter will not arrive until you are at the arrival location. This is to ensure that they have an escort the entire time they are in Corellian system.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 30, 'quest_rendezvous_t', 'Meet the Imperial Freighter'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 31, 'reason_1', 'We have to get this patrol done.  Black Epsilon squadron needs to know the enemy flight reports.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 32, 'reason_2', 'Command is waiting on these scans, lets get a move on.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 33, 'reason_3', 'I need to get back in time for a tour of Agrilate Swamp, lets get this done quickly.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 34, 'reason_4', 'I need to get back in time for a tour of Agrilate Swamp, lets get this done quickly.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 35, 'reason_5', 'I need to get back in time for a tour of Agrilate Swamp, lets get this done quickly.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 36, 'shields_depleted', 'Shields are down, I repeat my shields are down.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 37, 'taunt_1', 'You cannot hope to beat us, power down now.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 38, 'taunt_2', 'The Empire should expect no mercy.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 39, 'taunt_3', 'Your overthrow is imminent Imperial dog.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 40, 'taunt_4', 'The Alliance stands stong!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 41, 'taunt_5', 'The Alliance stands stong!'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 42, 'thanks_1', 'Great job on the escrort, it is good to be home.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 43, 'thanks_2', 'Whew, that was some great flying ace.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 44, 'thanks_3', 'I am thankful of high command for these escorts.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 45, 'thanks_4', 'I am thankful of high command for these escorts.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 46, 'thanks_5', 'I am thankful of high command for these escorts.'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 47, 'title', 'Corellia System: Protect the Imperial Freighters Duty'),
('string/en/spacequest/escort_duty/corellia_imperial_11.stf', 48, 'title_d', 'Travel to the Corellia system and escort important Imperial military supplies that are being sent in from Naboo. These will help restock the military that is located on Talus. It is highly important that the cargo ships arrive at their destination safely and most importantly do not fall into Rebel hands.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 2, 'abort', 'Abort code received, preparing hyper jump out of the sector.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 3, 'arrived_at_loc', 'We have confirmed your coordinates to be correct. Freighter should arrive from hyperspace any second.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 4, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 5, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 6, 'complete', 'The Freighter has arrived safely, good job pilot.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 7, 'duty_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 11, 'failed_destroy', 'That shipment was invaluable to us! You will have to answer to your superior for this pilot!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 12, 'failed_protect', 'The Freighter had to make a jump to hyperspace, your protection wasn''t sufficient pilot!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 13, 'found_loc', 'Coordinates for rendez-vous point with next freighter uploaded to your nav computer. Proceed immediately pilot.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 14, 'goodbye_1', 'Alright we made it in one piece. Descending to surface, thanks for the help pilot.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 15, 'goodbye_2', 'We couldn''t have made it without you pilot, was a pleasure to work with you.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 16, 'goodbye_3', 'Thank you pilot, we got it from here.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 17, 'goodbye_4', 'Excellent work Pilot, those Rebel scum will think twice before attacking our Freighters again.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 18, 'goodbye_5', 'Ah finally here, heading for the nearest cantina. Thanks for the escort pilot.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 19, 'hull_half', 'We are falling apart over here, get those Rebel scum off me!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 20, 'panic_1', 'Incoming Rebel fighters, they are gunning for me, take them out quick!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 21, 'panic_2', 'Rebel fighters! This vessel is not equipped to handle a fight, you have to help us!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 22, 'panic_3', 'Oh no, sensors show Rebel fighters incoming!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 23, 'panic_4', 'Time to earn your pay pilot, we got Rebel fighters approaching.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 24, 'panic_5', 'We''re not home free yet, Rebel fighters approaching fast!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 25, 'quest_escort_d', 'Follow the freighter and protect it from attack. Enemy fighters will jump into the area and attack the freighter. Freighters are not very sturdy, so it is important for you to take out the enemy fighters as quickly as you can.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 26, 'quest_escort_t', 'Protect the Imperial Freighter'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 27, 'quest_location_d', 'Travel to the Corellia system and move towards your first navigation waypoint to begin the escort duty. After it arrives, follow the Imperial freighter until it reaches its destination.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 28, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 29, 'quest_rendezvous_d', 'Travel to the navigation waypoint and wait for the Imperial freighter to arrive. Once the freighter is in the system, follow it to its destination.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 30, 'quest_rendezvous_t', 'Meet the Freighter at the Navigation Waypoint'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 31, 'reason_1', 'Greetings pilot, good to see you. We''re hauling some new equipment for the boys on the ground and need some protection.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 32, 'reason_2', 'Pilot, good to see you. We are transporting a prisoner for the Inquisition and need a escort.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 33, 'reason_3', 'Good our escort is here. We''re sitting on a barrel of explosives here so keep any hostiles far away from us.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 34, 'reason_4', 'G''Day pilot. We''re running a taxi service here I guess, hauling some important dude in the back. Keep an eye on us.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 35, 'reason_5', 'Transmitting my Imperial ID code now. Protect us with your life pilot.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 36, 'shields_depleted', 'My shields are failing, you better get rid of these fighters quick pilot!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 37, 'taunt_1', 'You will never reach Corellia, filthy Imperial!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 38, 'taunt_2', 'We won''t be satisfied with taking your cargo, we''re taking your life Imperial scum!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 39, 'taunt_3', 'Easy pickins, say good night Imperial wretches!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 40, 'taunt_4', 'Freeeedoooom!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 41, 'taunt_5', 'Revenge is best served through a Laser cannon!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 42, 'thanks_1', 'Good job pilot, glad to have you here.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 43, 'thanks_2', 'Phew, thought they had us for sure.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 44, 'thanks_3', 'You know how to handle that ship, I''ll give you that pilot.'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 45, 'thanks_4', 'Whow! Did you see that Rebel scum when you took off his wing? Beautiful!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 46, 'thanks_5', 'You make me miss being a fighter pilot, nice moves!'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 47, 'title', 'Corellia System: Escort the Imperial Freighters Duty'),
('string/en/spacequest/escort_duty/corellia_imperial_7.stf', 48, 'title_d', 'Travel to the Corellia system and escort the Imperial freighters through the system. An escort duty is a voluntary mission that you are able to quit at any time without repercussions. When you reach the Corellia system, you will get a navigation waypoint to the arrival location of an Imperial freighter that you will need to escort through the system. Travel to the waypoint and wait until the freighter hyperjumps into the system. Once it is in the area, it will begin to fly through the system. You need to follow the freighter until it reaches its destination. Keep a careful eye out for enemy attack since they will attempt to destroy this freighter. Once completed you will receive another waypoint to the arrival location of another freighter. This escort duty can be stopped at any time by simply aborting the mission or leaving the system.'),
