('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 31, 'reason_1', 'Stay alert, this is a known pirate area.'),
('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 32, 'reason_2', 'Imperial high command really wants my cargo. So please watch my back.'),
('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 33, 'reason_3', 'Be on the look out. I attract pirates like a garbage attracts womp rats.'),
('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 34, 'reason_4', 'I feel much safer with you escorting me through this dangerous area.'),
('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 35, 'reason_5', 'Keep on the alert. Pirates are all over the place.'),
