('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 39, 'taunt_3', 'Borvo will be pleased with our prize.'),
('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 40, 'taunt_4', 'Ok, no more Mr. Nice Guy.'),
