('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 48, 'title', 'Corellia System: Protect Local Shipping Duty'),
('string/en/spacequest/escort_duty/corellia_imperial_9.stf', 49, 'title_d', 'Due to the inefficency of the CorSec the Empire has decided that it must help freighters in the region get their cargo through without being attacked by pirates. You will be assigned a freighter that you will need to protect from any attempt to capture it.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 2, 'abort', 'We are not armed. You cannot leave us the mercy of these pirates.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 3, 'arrived_at_loc', 'Wait here for the arrival of the freighter vessel. Once it arrives escort it safely through the sector.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Incoming enemy fighters.>'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter wave destroyed.>'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 6, 'complete', 'You have completed the escort run. Return to your commander to take another duty mission or train. Or remain in the sector to escort another ship.'),
