('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 11, 'failed_destroy', 'You have failed to protect the Imperial interests in this region. Report this failure to your commander.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 12, 'failed_protect', 'You have failed to protect the Imperial interests in this region. Report this failure to your commander.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 13, 'found_loc', 'Freighter will arrive at the location sent to your nav computer. Meet the freighter there and escort it through the sector.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 14, 'goodbye_1', 'Thanks, pilot. Those mercs have been harassing our ships for a while now. Something needs to be done.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 15, 'goodbye_2', 'I appreciate the escort. Without you those mercs would have had us for sure.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 16, 'goodbye_3', 'Those Velocity guys have been attacking ships all across the sector. Something needs to be done.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 17, 'goodbye_4', 'These supplies were much needed for our troops. You have done well, pilot.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 18, 'goodbye_5', 'Without you here, our cargo would be in the hands of the enemy right now.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 19, 'hull_half', 'Our hull is at half strength. Get those enemy fighters off of us.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 20, 'panic_1', 'Enemy fighters! I should have known.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 21, 'panic_2', 'Look out! Those Velocity mercs are swarming all over.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 22, 'panic_3', 'Did I ever tell you about the time... Enemy Fighters! Blast, I just spilled coffee on myself.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 23, 'panic_4', 'What are the chances of us running into these enemies?'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 24, 'panic_5', 'So, they have come again.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 25, 'quest_d', 'The Velocity Mercenaries have been attacking Imperial shipping lanes and have captured a number of freighters carrying important supplies for the war effort. Every freighter traveling through the Dantooine sector is now required to have an escort fighter to protect them against these attacks. Meet and escort freighters through the Dantooine sector, protecting them from attack.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 26, 'quest_escort_d', 'After the freighter arrives, follow the freighter through the system until it reaches it''s final destination. Keep a close watch out for the Velocity mercenaries who might try to destroy or capture these supply freighters.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 27, 'quest_escort_t', 'Protect the Imperial Freighter'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 28, 'quest_location_d', 'Meet your assigned freighter inside of the Dantooine system.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 29, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 30, 'quest_rendezvous_d', 'Travel to the navigation waypoint provided and wait for the arrival of the freighter assigned to you.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 31, 'quest_rendezvous_t', 'Meet the Imperial Freighter'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 32, 'quest_t', 'Protecting Imperial Interests'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 33, 'reason_1', 'I am glad to see you. With those mercenaries swarming this area I don''t feel safe.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 34, 'reason_2', 'These supplies have to get through. Supplies are running low at the outpost.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 35, 'reason_3', 'You had best keep a careful watch. Ships have been getting attacked all over this area.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 36, 'reason_4', 'I am glad to see you. I was attacked three times last week.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 37, 'reason_5', 'I have a ship full of blaster batteries and medical supplies. Chances are we are going to draw alot of attention.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 38, 'shields_depleted', 'There went our shields. We are not going to last much longer!'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 39, 'taunt_1', 'Run while you can, Imperial dog.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 40, 'taunt_2', 'Why you dirty womprat!'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 41, 'taunt_3', 'I am going to enjoy this.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 42, 'taunt_4', 'You fly like a blind bantha.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 43, 'taunt_5', 'Why don''t you just be a good little pilot and give us the ship?'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 44, 'thanks_1', 'Yeah, take that and some of that and how about a little of this...'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 45, 'thanks_2', 'You are like an enraged rancor aren''t you?'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 46, 'thanks_3', 'Ha...they are not so tough now.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 47, 'thanks_4', 'They never even knew what hit them.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 48, 'thanks_5', 'I bet they didn''t see that coming.'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 49, 'title', 'Dantooine System: Protect Imperial Interests Duty'),
('string/en/spacequest/escort_duty/corellia_imperial_tier4_2.stf', 50, 'title_d', 'Velocity mercenaries have been harrassing Imperial Freighters moving through the Dantooine system. Because of the lose of several valuable ships, Imperial Command has declared that all freighters moving through the Dantooine system shall have fighter escort to protect them against the attacks by the mercenaries.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 2, 'abort', 'You have aborted your mission and failed.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 3, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 You are at the predesignated location. Hold here for transport. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy craft have been detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 The attacking wave has stopped. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 6, 'complete', 'The mission is a complete.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 7, 'duty_update', '\\#pcontrast3 < %TO >'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 8, 'escort_too_far1', ''),
