('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 12, 'failed_protect', 'You have failed to protect your charge.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 13, 'found_loc', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Updating your Nav Computer with the freighters waypoint. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 14, 'goodbye_1', 'Good bye.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 15, 'goodbye_2', 'I''m getting away from this mess.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 16, 'goodbye_3', 'Good bye.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 17, 'goodbye_4', 'Good bye.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 18, 'goodbye_5', 'Good bye.'),
