('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 20, 'panic_1', 'Help!'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 21, 'panic_2', 'Ah, I was expecting this.'),
('string/en/spacequest/escort_duty/corellia_privateer_10.stf', 22, 'panic_3', 'Help!'),
