('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 2, 'abort', 'Abort code received, preparing hyper jump out of the sector.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 3, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 You are at the correct coordinates. Freighter should arrive shortly. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Vessels on intercept course approaching, weapon systems armed. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Sensors indicate no more fighter vessels with armed weapon systems in area. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 6, 'complete', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Another merchant safely on the ground, great job pilot! \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 7, 'duty_update', 'CorSec Command: < %TO >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 11, 'failed_destroy', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 All those civilians... I''m sure you did all you could pilot but we expect a full report on what happened. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 12, 'failed_protect', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 The Merchant ship was about to be destroyed and had to make a quick jump to hyperspace. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 13, 'found_loc', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 We have another Merchant ship being chased by Pirates. Get over to these coordinates quickly pilot. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 14, 'goodbye_1', 'Praise the CorSec, we would never have made it without you.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 15, 'goodbye_2', 'I knew I could count on the Ace pilots of the CorSec to bring us down safely. Thank you!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 16, 'goodbye_3', 'Thank you pilot, we would have been toast without you!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 17, 'goodbye_4', 'Fantastic, I never thought we''d made it alive! You are a lifesaver friend, thank you.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 18, 'goodbye_5', 'You sure taught those pirates a lesson, thank you again pilot.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 19, 'hull_half', 'Our hull is leaking! You have to get them off me, now!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 20, 'panic_1', 'Here they come, time to earn your pay CorSec!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 21, 'panic_2', 'More pirates incoming! We can''t defend ourselves, our fate is in your hands pilot!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 22, 'panic_3', 'Pirate fighter ships incoming!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 23, 'panic_4', 'More pirates, we''re done for now...'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 24, 'panic_5', 'Pirate fighters, incoming fast!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 25, 'quest_escort_d', 'One of the many freighter craft transversing this sector.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 26, 'quest_escort_t', 'Freighter'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 27, 'quest_location_d', 'Throughout the Corellia System'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 28, 'quest_location_t', 'Corellia System'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 29, 'quest_rendezvous_d', 'Meet the freighter for escort here.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 30, 'quest_rendezvous_t', 'Rendezvous Point'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 31, 'reason_1', 'So happy to see you pilot! We shook some pirates back there but I don''t think they gave up.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 32, 'reason_2', 'We''re transporting spices worth a fortune and have been dodging pirates all over the system. Your a welcome sight CorSec.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 33, 'reason_3', 'Oh hi. I think we''ll be fine but if you really want to escort us, we won''t say no.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 34, 'reason_4', 'Help? We don''t need help. Fine, you can tag along but stay out of our way.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 35, 'reason_5', 'Please help! The pirates are hot on our trail and we don''t have the means to defend ourselves!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 36, 'shields_depleted', 'Our shields are breaking down! We''re in big trouble!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 37, 'taunt_1', 'Time to fill my coffers with some more creds. Stay out of the way CorSec!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 38, 'taunt_2', 'There''s no escape, shut off your engines! We won''t hurt you, promise.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 39, 'taunt_3', 'Fear me, CorSec weakling! Whow I sound scary..is this thing still on...'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 40, 'taunt_4', 'We''re taking over, pack yourself out of here or face our wrath CorSec!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 41, 'taunt_5', 'You don''t want to mess with me CorSec.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 42, 'thanks_1', 'Nice moves pilot. I feel a lot more secure now.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 43, 'thanks_2', 'Not bad pilot, not bad at all.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 44, 'thanks_3', 'I love you! I mean, thank you pilot...'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 45, 'thanks_4', 'Yes! That''s how it''s done. Show them what happens when they mess with us!'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 46, 'thanks_5', 'Some great flying pilot, wish I could pull those moves in this hunk of trash.'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 47, 'title', 'Corellia System: Duty: Escort Merchant Freighters'),
('string/en/spacequest/escort_duty/corellia_privateer_7.stf', 48, 'title_d', 'Escort the freighter along their route through Black Sun and Hidden Daggers aggression.'),
