('string/en/spacequest/escort_duty/corellia_privateer_tier4_1.stf', 48, 'title', 'Dathomir System: Duty: Escort the Freighter'),
('string/en/spacequest/escort_duty/corellia_privateer_tier4_1.stf', 49, 'title_d', 'Protect the freighter on its flight through Dathomir Space'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 1, 'abort', 'Abort code received. Heading back to base.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 2, 'arrived_at_loc', 'Wait at this location. An Alliance refugee transport will arrive shortly.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 3, 'attack_notify', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostiles on approach vector to escort target! \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 4, 'attack_stopped', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile fighters eliminated. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 5, 'complete', 'Alliance HQ: < The refugees have made it through the region safely. Good job. >'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 6, 'duty_update', ' \\#pcontrast3 Alliance HQ: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 7, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 8, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 9, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 10, 'failed_destroy', 'Those refugees were depending on you, Pilot! Return to your commanding officer at once!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 11, 'failed_protect', 'The Alliance refugee transport has been redirected. Your mission is a failure.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 12, 'found_loc', 'Alliance HQ: < Travel to the rally point and wait for your escort target to arrive. >'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 13, 'goodbye_1', 'Everyone on-board appreciates your help! Thank you!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 14, 'goodbye_2', 'Alright, I can take it from here. Time to get these people home... Thanks!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 15, 'goodbye_3', 'Yeah! We made it. The Alliance owes you a debt of gratitude. Thanks!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 16, 'goodbye_4', 'What a ride! The Alliance owes me more than standard pay, I think! Thanks for the escort, though.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 17, 'goodbye_5', 'We''re ready to get these refugees back home. Thanks for the escort!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 18, 'hull_half', 'I''m tracking multiple hull breaches! I can''t take much more damage. Help!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 19, 'panic_1', 'They''re moving to attack! Please help us!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 20, 'panic_2', 'I think...no it can''t be... They''re opening fire! Hostiles! Repeat, hostiles on attack vector!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 21, 'panic_3', 'Those new ships are moving in too fast for coincidence. Prepare for assault.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 22, 'panic_4', 'No, no, no. Not now. This was my last job of the day. Why can''t they leave my shipment alone!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 23, 'panic_5', 'Those new contacts don''t look friendly. The Force be with you, friend.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 24, 'quest_escort_d', 'Defend the transport as it attempts to leave the Corellia system. Protect against any and all hostile forces that threaten you or the transport.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 25, 'quest_escort_t', 'Protect the Alliance refugee transport.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 26, 'quest_location_d', 'Alliance HQ will be uploading navigation points for you to follow. Meet the refugee transport at the nav point and escort it to safety.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 27, 'quest_location_t', 'Corellia system.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 28, 'quest_rendezvous_d', 'The Alliance is trying to get refugees out of the system before the war consumes them. Protect the transport as it flies. Defend against all hostile forces until the transport is away.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 29, 'quest_rendezvous_t', 'Meet the Alliance Refugee Transport and escort it to safety.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 30, 'reason_1', 'Alliance Freighter reporting! We have a hold full of refugees who need to get home, buddy.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 31, 'reason_2', 'Requesting fighter escort. Repeat! Requesting fighter escort!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 32, 'reason_3', 'Hey there, pilot! Let''s get these refugees back home. Whadda you say?'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 33, 'reason_4', 'Good to see you, pilot! Cover us so we can get these refugees back where they belong.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 34, 'reason_5', 'This is the freight commander speaking. Form up and keep us safe! We have a lot of injured on-board and don''t need any more excitement!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 35, 'shields_depleted', 'Our shields are out. Get rid of those fighters now!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 36, 'taunt_1', 'Rebel scum! Prepare to die!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 37, 'taunt_2', 'Refugees, eh? You expect us to believe that... traitor?!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 38, 'taunt_3', 'Time to die, Rebel scum!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 39, 'taunt_4', 'I''ve got you in my sights.'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 40, 'taunt_5', 'Kill the Rebel traitors!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 41, 'thanks_1', 'Thanks for taking out those punks. Now let''s get these refugees back home!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 42, 'thanks_2', 'Whew, thanks for thinking fast there. We would have been spaced without your help!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 43, 'thanks_3', 'Very impressive, my friend! The Force is with you...'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 44, 'thanks_4', 'I can''t believe we made it! Thanks a million, pal!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 45, 'thanks_5', 'All refugees safe and sound. Thanks for your help, pilot!'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 46, 'title', 'Corellia system: Duty mission: Protect Refugee Transports'),
('string/en/spacequest/escort_duty/corellia_rebel_7.stf', 47, 'title_d', 'Protect Refugee Transports. These missions have been outlined to give you some much needed experience in space combat, you can stop when you feel that you have learned enough.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 1, 'abort', 'What the?! Where are you going Rebel?!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 2, 'arrived_at_loc', 'You''re at the correct coordinates Rebel, one of our freighters should be there soon.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 3, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 4, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 5, 'complete', 'Good job pilot, the freighter is safe.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 6, 'duty_update', 'Nym Command Officer: < %TO >'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 7, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 8, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 9, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 10, 'failed_destroy', 'I knew we shouldn''t have put our trust in a Rebel! We lost that freighter, get out of there!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 11, 'failed_protect', 'Our freighter had to perform a emergency hyperspace jump! What were you doing out there, sightseeing?'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 12, 'found_loc', 'Alright, proceed to these coordinates to meet up with our freighter.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 13, 'goodbye_1', 'Not bad for a Rebel, see you around!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 14, 'goodbye_2', 'I owe you a drink Rebel, excellent work!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 15, 'goodbye_3', 'We''ll be ok from here pilot, thanks for the help!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 16, 'goodbye_4', 'Jumping to lightspeed, good flying with ya!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 17, 'goodbye_5', 'There''ll be a party tonight, this stuff is worth a ton of creds!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 18, 'hull_half', 'Ah crap, my old baby is falling apart over here, going to need some serious help!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 19, 'panic_1', 'Guess they didn''t like us taking off with their stuff!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 20, 'panic_2', 'Here come the Empires henchmen!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 21, 'panic_3', 'Didn''t think they would let us just fly out of here with their stuff.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 22, 'panic_4', 'Angry bubble-boys heading our way!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 23, 'panic_5', 'We must have hit the jackpot this time, they are really angry!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 24, 'quest_escort_d', 'Escort the freighter safely out of the Dathomir system. Be prepared though, the Empire is searching everywhere for you!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 25, 'quest_escort_t', 'Escort the freighter.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 26, 'quest_location_d', 'The Dathomir system is always a dangerous place to traverse and after our successful raid, the Empire is scouring it for enemies. Be careful.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 27, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 28, 'quest_rendezvous_d', 'We have uploaded the coordinates of the next freighter that need your escort.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 29, 'quest_rendezvous_t', 'Coordinates of freighter.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 30, 'reason_1', 'A Rebel eh? Well hopefully you know how to fly, I doubt the Empire will let us walse out of here with this stuff.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 31, 'reason_2', 'We got some class A military equipment from the raid down there. I''m sure the Empire wants it back so lets get out of here!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 32, 'reason_3', 'Hey there. Get me out of this one in one piece and I''ll get you a nice bonus at the end.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 33, 'reason_4', 'Greetings, lets not waste any time. The Empire was hot on our tail down on the ground.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 34, 'reason_5', 'Good, you''re here. We should get moving, I have a feeling the Empire won''t let us escape without a fight.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 35, 'shields_depleted', 'My shields are fried! I need your help pilot!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 36, 'taunt_1', 'You pathetic pirates, think the Rebel scum will save you?'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 37, 'taunt_2', 'You should have stayed on Lok pirate, no one steals from the Empire!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 38, 'taunt_3', 'Looks like we got a bonus guys, that''s a Rebel!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 39, 'taunt_4', 'Rebels and Nym working together eh? I guess they need all the help they can get!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 40, 'taunt_5', 'You know you won''t leave this system alive, just surrender!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 41, 'thanks_1', 'Awesome! Makes me wish these old bones still had the reflexes to pilot a fighter.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 42, 'thanks_2', 'Rebel flight school must have made some improvements, that was impressive!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 43, 'thanks_3', 'Yeah! Fry that Imperial scum, haha!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 44, 'thanks_4', 'Systems still green on my end, lets keep moving before more come along.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 45, 'thanks_5', 'Nice flying pilot! My nav computer is almost done preparing for the jump. Lets move along!'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 46, 'title', 'Dathomir system: Duty mission: Escort Nym freighters.'),
('string/en/spacequest/escort_duty/corellia_rebel_tier4_1.stf', 47, 'title_d', 'Our mighty pirates have raided an Imperial outpost in the Dathomir system and now we need to get the bounty to Lok. Provide a safe escort for our freighters. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 2, 'abort', 'You cannot leave us out here! We are carring important supplies for the Empire.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 3, 'arrived_at_loc', 'Hold at your current location. The vessel you are assigned to escort will be arriving shortly.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters detected.>'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter wing has been eliminated.>'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 6, 'complete', 'The freighter is safely away. Wait for command to assign you another freighter to escort or return to your commander to take a new mission.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 7, 'duty_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 11, 'failed_destroy', 'Your orders were to make sure that vessel arrived at HQ safely. Return to your superior and explain your failure.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 12, 'failed_protect', 'You left that vessel out there unarmed and at the mercy of Rebels. You will have alot of explaining to do. Return to your superior.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 13, 'found_loc', 'The escort vessel will be arriving at the location supplied to your nav computer. Travel to that location and await the arrival of that vessel.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 14, 'goodbye_1', 'We appreciate your help out there pilot.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 15, 'goodbye_2', 'Thanks for getting us through this sector. Those Rebels really need to be cleared out.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 16, 'goodbye_3', 'You have done a great service to me and the Empire.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 17, 'goodbye_4', 'My cargo will help save honest Imperial lives. You have my thanks.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 18, 'goodbye_5', 'Be safe, pilot. Thanks for watching my back.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 19, 'hull_half', 'Hull at half strength! They told me you were good...prove it!'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 20, 'panic_1', 'Blasted Rebels!'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 21, 'panic_2', 'Do I look worried? I think not.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 22, 'panic_3', 'Go get them. That is your job isn''t it?'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 23, 'panic_4', 'Rebels are after me! Who will repel them?'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 24, 'panic_5', 'You had better send those Rebels into oblivion.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 25, 'quest_escort_d', 'After you have met with your target transport, follow it through the Dathomir system until it arrives at it''s final destination. There is a good chance that Rebels will attack and the transport must be defended at all costs because of the importance of it''s cargo.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 26, 'quest_escort_t', 'Protect the Imperial Freighter'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 27, 'quest_location_d', 'The freighters are arriving in the Dathomir system before they are being attacked by the Rebels. Meet them at their jump location inside the Dathomir system and escort them safely to their destination.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 28, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 29, 'quest_rendezvous_d', 'Command will supply the jump in location of the transport. The freighter will not arrive until you are at that location.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 30, 'quest_rendezvous_t', 'Meet the Imperial Freighter'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 31, 'reason_1', 'I have a ship full of cargo for the Imperial Prison.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 32, 'reason_2', 'I just arrived from a Yavin salvage operation. I understand you will be my escort.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 33, 'reason_3', 'I hope we have a smooth flight. My last one was an absolute mess. Rebels coming out of everywhere.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 34, 'reason_4', 'An escort? I don''t need an escort. I have been flying since the days of the Old Republic and I have never been attacked by anyone.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 35, 'reason_5', 'Glad to have you with me. I have some very valuable stuff on this ship and it would be a shame to lose it.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 36, 'shields_depleted', 'There went our shields! Get those fighters off of us.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 37, 'taunt_1', 'Give us the freighter and no one gets hurt.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 38, 'taunt_2', 'We just want what is ours...so give us your freighter.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 39, 'taunt_3', 'You are really starting to make me mad.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 40, 'taunt_4', 'Imperial scum like you are better off dead.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 41, 'taunt_5', 'That''s just great! You scratched my new paint job!'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 42, 'thanks_1', 'I am glad that you are out here.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 43, 'thanks_2', 'They were not that tough. Back in my day we used to have to fight twice as many Rebels.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 44, 'thanks_3', 'Today is a glorious day for the Empire.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 45, 'thanks_4', 'Rebels are no match for your superior skills.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 46, 'thanks_5', 'Thanks for saving my skin.'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 47, 'title', 'Dathomir System: Protect the Imperial Freighters Duty'),
('string/en/spacequest/escort_duty/dathomir_station_imp_escort_duty_tier3.stf', 48, 'title_d', 'Rebels have been attacking Imperial traffic moving through the Dathomir system. The Emperor has decreed that all transports shall have an escort through the system because of the important cargo, nessecary for resupplying the Imperial Prison, that they are carrying.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 2, 'abort', 'Aborting as ordered. Preparing escape to hyperspace.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 3, 'arrived_at_loc', '\\#pcontrast3 Station Command: < \\#pcontrast1 Transport is on its way, await their arrival at this location. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Vessels on intercept course approaching, weapon systems armed. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Sensors indicate no more fighter vessels with armed weapon systems in area. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 6, 'complete', 'Another victory, great job pilot!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 7, 'duty_update', 'Station Command: < %TO >'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 11, 'failed_destroy', '\\#pcontrast3 Station Command: < \\#pcontrast1 I can''t believe these scum destroyed a transport full of innocents. We will need a full report on this tragedy pilot. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 12, 'failed_protect', 'Transport had to escape through a emergency hyperspace jump pilot, there were just too many of the pirates.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 13, 'found_loc', 'We have a request from another transport with important passengers for a safe escort. New coordinates uploaded.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 14, 'goodbye_1', 'You haven''t let me down, thank you pilot!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 15, 'goodbye_2', 'Bumpy ride but we made it in one piece thanks to you pilot.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 16, 'goodbye_3', 'After this, I''m putting some defense weapons on my freighter. Thanks again my friend.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 17, 'goodbye_4', 'That was a close one and your the only reason we survived. Accept our gratitude pilot.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 18, 'goodbye_5', 'I''d like to come back in a different ships and teach those scum a thing or two. Anyway, thank you for the help pilot!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 19, 'hull_half', 'Our sensors register multiple hull breeches, you have to take care of those pirates now!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 20, 'panic_1', 'Hostile fighters inbound!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 21, 'panic_2', 'Pirate wretches, they want my cargo!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 22, 'panic_3', 'Help us, they will kill us all!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 23, 'panic_4', 'Oh no, pirates! You better be good at your job pilot!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 24, 'panic_5', 'Uh oh, we got unwanted attention. I think they are pirates!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 25, 'quest_escort_d', 'A passenger transport to be escorted through this sector.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 26, 'quest_escort_t', 'Escort Target'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 27, 'quest_location_d', 'Transport route through the Dathomir System'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 28, 'quest_location_t', 'Dathomir System'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 29, 'quest_rendezvous_d', 'Meet the transport at this location'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 30, 'quest_rendezvous_t', 'Rally Point'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 31, 'reason_1', 'There you are. I hope you''re good at this, we have cargo that could attract every pirate in the sector...'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 32, 'reason_2', 'Thank you for escorting us pilot. We have passengers on board, so stay alert.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 33, 'reason_3', 'My job depends on me making this transport on time, so I hope you know what you are doing pilot.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 34, 'reason_4', 'Perfect, a pilot. Last time we didn''t get an escort and those Black Sun pirates put my ship in the docks for a month!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 35, 'reason_5', 'Greetings pilot, good to see you. Lets head for the surface quickly, I don''t want any incidents.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 36, 'shields_depleted', 'Our shields are down! If you don''t get rid of those pilotes, we are done for!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 37, 'taunt_1', 'Get out of here while you still can scum.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 38, 'taunt_2', 'We''re boarding this ship, now it''s just a question if you want to die for it or not.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 39, 'taunt_3', 'I will enjoy cutting your ship in half!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 40, 'taunt_4', 'You''re attacking us in that hunk of junk? You can''t be serious.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 41, 'taunt_5', 'I''ll guide you back down to the ground... without your ship of course.'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 42, 'thanks_1', 'Great job pilot, lets hurry out of here!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 43, 'thanks_2', 'Back in my day, I would have dealt with those pirates twice as fast..'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 44, 'thanks_3', 'Splendid, finally a pilot that knows what he''s doing!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 45, 'thanks_4', 'Hahaha, they will think twice before attacking us again!'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 46, 'thanks_5', 'Any chance you looking for a new career as bodyguard?'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 47, 'title', 'Dathomir System: Duty: Escort Passenger Transports'),
('string/en/spacequest/escort_duty/dathomir_station_priv_escort_duty_tier3.stf', 48, 'title_d', 'Protect transports from Black Sun aggression.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 2, 'abort', 'Abort code received. Heading back to base.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 3, 'arrived_at_loc', 'The fake transport will arrive soon. Use it to bait Nym''s pirates into attacking.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 4, 'attack_notify', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Nym''s pirates detected on attack vector! \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 5, 'attack_stopped', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile fighters eliminated. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 6, 'complete', 'The ship has made it through the region. Cycle back and escort another fake transport through.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 7, 'duty_update', ' \\#pcontrast3 Imperial Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 11, 'failed_destroy', 'The transports have been lost! The pilots on board have been lost! Return to base, this mission is over.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 12, 'failed_protect', 'The transport has left the area prematurely! This mission is over.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 13, 'found_loc', 'Travel to the rendezvous waypoint and wait for the fake transport to arrive.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 14, 'goodbye_1', 'We''re going to head back to base. Another transport will meet you in a bit.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 15, 'goodbye_2', 'We''re going to head back to base. Another transport will meet you in a bit.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 16, 'goodbye_3', 'We''re going to head back to base. Another transport will meet you in a bit.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 17, 'goodbye_4', 'We''re going to head back to base. Another transport will meet you in a bit.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 18, 'goodbye_5', 'We''re going to head back to base. Another transport will meet you in a bit.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 19, 'hull_half', 'I''m tracking multiple hull breaches! I can''t take much more damage. Help!'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 20, 'panic_1', 'Nym''s pirates have taken the bait. Head''s up.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 21, 'panic_2', 'Boy, those guys look pretty mad.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 22, 'panic_3', 'I hope you know how to fly that thing.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 23, 'panic_4', 'Nym''s pirates decided to show up. How nice of them.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 24, 'panic_5', 'Destroy them all!'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 25, 'quest_escort_d', 'Follow the freighter to it''s destination. You must protect it from anyone who attempts to take it.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 26, 'quest_escort_t', 'Protect the Imperial Freighter'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 27, 'quest_location_d', 'Meet the freighters inside of the Lok system. You will receive a navigation waypoint to the arrival location of your assigned freighter once you reach the system.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 28, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 29, 'quest_rendezvous_d', 'Wait for the freighter at the arrival location.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 30, 'quest_rendezvous_t', 'Meet the Imperial Freighter'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 31, 'reason_1', 'Keep your eyes open for pirates.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 32, 'reason_2', 'Let''s see if Nym takes the bait.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 33, 'reason_3', 'I don''t think any pirate can resist this nice fat lure.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 34, 'reason_4', 'Stay alert! This place is crawling with pirates.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 35, 'reason_5', 'Ready to go catch ourselves some pirate scum?'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 36, 'shields_depleted', 'Our shields are out. Get them off of me!'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 37, 'taunt_1', 'Time to die, Imperial scum!'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 38, 'taunt_2', 'Big mistake, Imperial puppet!'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 39, 'taunt_3', 'Give up and I promise to make it quick.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 40, 'taunt_4', 'You are better then most Imperials but you are not good enough.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 41, 'taunt_5', 'Prepare to be blown out of the sky.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 42, 'thanks_1', 'Good job, let''s go find more pirates.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 43, 'thanks_2', 'Nice work, but there are always more pirates to find.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 44, 'thanks_3', 'Don''t get cocky. There are more pirates out there.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 45, 'thanks_4', 'Let get back to work.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 46, 'thanks_5', 'Not bad...not bad at all.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 47, 'title', 'Lok System: Bait and Destroy Nym''s Pirates'),
('string/en/spacequest/escort_duty/lok_imperial_ss_1c.stf', 48, 'title_d', 'Nym has never liked the fact that the Empire has a base located on Lok. He is constantly hampering Imperial shipments heading into the system. With our current operations it is important that those shipments make it to the base without incident. You are to protect those shipments from attacks from Nym''s men.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 2, 'abort', 'Abort code received. Heading back to base.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 3, 'arrived_at_loc', 'The relic transport will arrive soon. Protect it as it calculates a lightspeed jump.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 4, 'attack_notify', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Pirates detected on attack vector! \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 5, 'attack_stopped', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile fighters eliminated. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 6, 'complete', 'The relic transport has left the Yavin system.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 7, 'duty_update', ' \\#pcontrast3 Imperial Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 11, 'failed_destroy', 'The transport and all salvage on board has been lost! Return to base immediately.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 12, 'failed_protect', 'The transport has left the area prematurely! This mission is over.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 13, 'found_loc', 'Travel to the rendezvous waypoint and wait for the transport to arrive.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 14, 'goodbye_1', 'Our lightspeed vector is locked in. Thanks for the escort.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 15, 'goodbye_2', 'Preparing for lightspeed jump. Thanks for the escort.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 16, 'goodbye_3', 'Hyperspace coordinates locked in. Safe travels, pilot.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 17, 'goodbye_4', 'Our lightspeed vector is locked in. Thanks for the escort.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 18, 'goodbye_5', 'Preparing for lightspeed jump. Thanks for the escort.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 19, 'hull_half', 'I''m tracking multiple hull breaches! I can''t take much more damage. Help!'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 20, 'panic_1', 'Scavengers are moving in to attack!'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 21, 'panic_2', 'Scavenger fighters! Hold them off.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 22, 'panic_3', 'It looks like those scavengers mean business.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 23, 'panic_4', 'Keep them off of me. I cannot last long against them.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 24, 'panic_5', 'Scavengers incoming! Engage at will.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 25, 'quest_escort_d', 'Follow the freighter until it reaches its jump point. Be on the look out for the Debris Cult who will most likely try to destroy the freighter rather then see their debris leave the area.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 26, 'quest_escort_t', 'Protect the Imperial Freighter'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 27, 'quest_location_d', 'Meet the salvage freighters inside of the Yavin system. You will receive a navigation waypoint to the meeting point of your assigned freighter.'),
