('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 38, 'taunt_2', 'The debris you picked up belongs to us.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 39, 'taunt_3', 'We will have that freighter.'),
('string/en/spacequest/escort_duty/lok_imperial_ss_2c.stf', 40, 'taunt_4', 'You have violated this holy place.'),
