('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 22, 'panic_3', 'I hope you are a good pilot. I have kids.'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 23, 'panic_4', 'Trouble ahead!'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 24, 'panic_5', 'Rebels! They are after my cargo.'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 25, 'quest_escort_d', 'Follow the freighter and protect it from attack. Enemy fighters will jump into the area and attack the freighter. Freighters are not very sturdy, so it is important for you to take out the enemy fighters as quickly as you can.'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 26, 'quest_escort_t', 'Protect the Freighter'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 27, 'quest_location_d', 'Travel to the Naboo system and move towards your first navigation waypoint to begin the escort duty. After it arrives, follow the freighter until it reaches its destination.'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 28, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 29, 'quest_rendezvous_d', 'Travel to the navigation waypoint and wait for the freighter to arrive. Once the freighter is in the system, follow it to its destination.'),
('string/en/spacequest/escort_duty/naboo_imperial_7.stf', 30, 'quest_rendezvous_t', 'Meet the Freighter'),
