('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 31, 'reason_1', 'Hello, pilot. Prison ship D4-343 in route to drop off prisoners reporting in.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 32, 'reason_2', 'Hello, pilot. Prison ship D7-932 in route to drop off prisoners reporting in.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 33, 'reason_3', 'Hello, pilot. Prison ship D9- 441 in route to drop off prisoners reporting in.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 34, 'reason_4', 'Hello, pilot. Prison ship D8-002 in route to drop off prisoners reporting in.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 35, 'reason_5', 'Hello, pilot. Prison ship D6-229 in route to drop off prisoners reporting in.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 36, 'shields_depleted', 'There went our shields. You had better start protecting us better, pilot.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 37, 'taunt_1', 'Hey, look at that...target practice!'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 38, 'taunt_2', 'You will fall to my might.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 39, 'taunt_3', 'For Coyn! For Glory!'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 40, 'taunt_4', 'It is wrong to lock any man up. We shall set them free...or at least their souls.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 41, 'taunt_5', 'Feel the wrath of Coyn.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 42, 'thanks_1', 'You are a credit to the uniform.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 43, 'thanks_2', 'Who do you think they were?'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 44, 'thanks_3', 'Why do you think they tried to hit an Imperial prison ship? Seems crazy to me.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 45, 'thanks_4', 'Not very good pirates, are they.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 46, 'thanks_5', 'I just don''t understand why they would want to attack us like that.'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 47, 'title', 'Dathomir System: Escort the Prison Shuttle Duty'),
('string/en/spacequest/escort_duty/naboo_imperial_tier4_2.stf', 48, 'title_d', 'The Empire has a high influx of prisoners that it wishes to keep alive but doesn''t want to hold in any standard prison. These prisoners are to be shipped to Dathomir where they will remain for the rest of their lives. With the Coynite activity in the system command wants to ensure that they make it to the prison. You are to escort prison vessels as they enter the system.'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 2, 'abort', 'Aborting as ordered. Preparing escape to hyperspace.'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 3, 'arrived_at_loc', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Transport is on its way, await their arrival at this location. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Vessels on intercept course approaching, weapon systems armed. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Sensors indicate no more fighter vessels with armed weapon systems in area. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 6, 'complete', 'Another victory for the Royal Security Forces, great job pilot!'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 7, 'duty_update', 'RSF Command: < %TO >'),
('string/en/spacequest/escort_duty/naboo_privateer_7.stf', 8, 'escort_too_far1', ''),
