('string/en/spacequest/escort_duty/naboo_privateer_tier4_1.stf', 44, 'thanks_2', 'Great shooting.'),
('string/en/spacequest/escort_duty/naboo_privateer_tier4_1.stf', 45, 'thanks_3', 'Thank you.'),
('string/en/spacequest/escort_duty/naboo_privateer_tier4_1.stf', 46, 'thanks_4', 'Thank you.'),
('string/en/spacequest/escort_duty/naboo_privateer_tier4_1.stf', 47, 'thanks_5', 'Thank you.'),
('string/en/spacequest/escort_duty/naboo_privateer_tier4_1.stf', 48, 'title', 'Endor System: Duty: Escort the Mining Freighter'),
('string/en/spacequest/escort_duty/naboo_privateer_tier4_1.stf', 49, 'title_d', 'Defend the freighter from Borvo the Hutt'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 1, 'abort', 'We are doomed without your help pilot! What are you doing?!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 2, 'arrived_at_loc', 'You are at the correct location pilot, the freighter will be there any second.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 3, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 4, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 5, 'complete', 'Thank you pilot, home free!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 6, 'duty_update', ' \\#pcontrast3 Alliance HQ:  < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 7, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 8, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 9, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 10, 'failed_destroy', 'We cant afford those kind of casaulties pilot. Return to base!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 11, 'failed_protect', 'The freighter informed us that your protection was not adequate and that he had to make an emergency jump to lightspeed. Return to base!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 12, 'found_loc', 'Uploading coordinates to rendez-vous with the next freighter.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 13, 'goodbye_1', 'Jumping to lightspeed. Thank you for the help pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 14, 'goodbye_2', 'Well that was a rush! See you around pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 15, 'goodbye_3', 'We''re safe from here, was a privilege to work with you pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 16, 'goodbye_4', 'That was fun! Want to do it again? Just kidding, thanks again pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 17, 'goodbye_5', 'We''re ready to take off, thanks for providing a solid escort pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 18, 'hull_half', 'We''re falling apart over here! You have to get rid of these TIE''s now pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 19, 'panic_1', 'Time to prove your worth pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 20, 'panic_2', 'A TIE patrol, they have spotted us!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 21, 'panic_3', 'I think that Imperial patrol saw us, prepare for battle pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 22, 'panic_4', 'Darn! TIE fighters closing in!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 23, 'panic_5', 'We''re detected! This could get rough!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 24, 'quest_escort_d', 'Protect the Alliance freighter from incoming attack until it reaches its hyperspace jump point. Once the transport is away, Alliance HQ will upload a new rally point for you to follow.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 25, 'quest_escort_t', 'Escort the Alliance freighter to its destination.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 26, 'quest_location_d', 'Follow waypoints to distressed Alliance freighters. Escort each freighter to its destination and protect it from hostile fire.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 27, 'quest_location_t', 'Naboo system.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 28, 'quest_rendezvous_d', 'Alliance HQ has provided a waypoint to the Alliance freighter. Go to this navigation point, meet the freighter and protect it as it flies.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 29, 'quest_rendezvous_t', 'Meet up with the Alliance freighter.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 30, 'reason_1', 'We have medical supplies for the frontline pilot, it''s imperative that they make it!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 31, 'reason_2', 'We''re shipping hardware to a stranded Alliance freighter pilot, they are depending on us.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 32, 'reason_3', 'Good to see you pilot, Naboo space is always a dangerous route to take but I had no choice.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 33, 'reason_4', 'There you are, we''re ready to take off. Follow us pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 34, 'reason_5', 'We''re shipping two platoons of Alliance grunts back here, their safety is in your hands pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 35, 'shields_depleted', 'Our shields are failing! We''re in deep trouble!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 36, 'taunt_1', 'You thought we''d just let you fly out of here Rebel scum?'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 37, 'taunt_2', 'Scans show illegal cargo, cut your engines immediately!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 38, 'taunt_3', 'Finally, some fun around here. Take no prisoners boys!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 39, 'taunt_4', 'Well, well. What do we have here? Rebel fools!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 40, 'taunt_5', 'Stay focused men, the Rebels are tricky!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 41, 'thanks_1', 'Take that, Imperial scum!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 42, 'thanks_2', 'Lets keep moving before more of them show up!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 43, 'thanks_3', 'Nice shot pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 44, 'thanks_4', 'Excellent!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 45, 'thanks_5', 'You showed them pilot! Nice flying!'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 46, 'title', 'Naboo system: Duty mission: Escort Rebel freighters.'),
('string/en/spacequest/escort_duty/naboo_rebel_7.stf', 47, 'title_d', 'Assist the Rebel freighters with a safe escort to their destinations. These missions have been outlined to give you some much needed experience in space combat, you can stop when you feel that you have learned enough.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 1, 'abort', 'You can''t abort now, we''re not safe yet!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 2, 'arrived_at_loc', 'The shuttle is almost there, stand by.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 3, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 4, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 5, 'complete', 'Good job pilot, they are safe. Stand by for further orders.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 6, 'duty_update', 'Vortex Fleet Command: < %TO >'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 7, 'escort_too_far1', ''),
