('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 10, 'failed_destroy', 'You let all those people die pilot... Return to base immediately!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 11, 'failed_protect', 'The shuttle was forced to perform an emergency hyperspace jump, you better pray that they are alright pilot. Return to base!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 12, 'found_loc', 'One of the shuttles will meet you at this location, get over there as fast as you can pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 13, 'goodbye_1', 'Jumping to lightspeed. Thank you for the help pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 14, 'goodbye_2', 'Well that was a rush! See you around pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 15, 'goodbye_3', 'That was fun! Want to do it again? Just kidding, thanks again pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 16, 'goodbye_4', 'That was fun! Want to do it again? Just kidding, thanks again pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 17, 'goodbye_5', 'We''re ready to take off, thanks for providing a solid escort pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 18, 'hull_half', 'Sensors show multiple hull breaches! You need to get these fighters off us!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 19, 'panic_1', 'Time to prove your worth pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 20, 'panic_2', 'I hope you''re as good as we were told.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 21, 'panic_3', 'Everyone strap in, this is going to get bumpy!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 22, 'panic_4', 'I didn''t think we could slip out undetected.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 23, 'panic_5', 'Imperial fighters heading our way!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 24, 'quest_escort_d', 'Escort the transport to a safe location for their hyperspace jump. Stay alert and good luck.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 25, 'quest_escort_t', 'Escort transport to safety.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 26, 'quest_location_d', 'The Yavin system is quite dangerous, even for someone of your skill. The Empire is guarding the debris of their blown up space station fiercely so try to avoid getting their attention.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 27, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 28, 'quest_rendezvous_d', 'One of the transports have provided us with these coordinates as rendez-vous. Get there quickly pilot.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 29, 'quest_rendezvous_t', 'Coordinates of transport.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 30, 'reason_1', 'Alright, lets get out of here.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 31, 'reason_2', 'I''m transporting a lot of non combat personnel, lets get them safely out of here.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 32, 'reason_3', 'Good to see you pilot, lets not waste any time.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 33, 'reason_4', 'We''re ready to leave this system, lets go.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 34, 'reason_5', 'Greetings pilot, glad that you are here. Lets get moving.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 35, 'shields_depleted', 'Our shields are depleted pilot, this will get ugly!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 36, 'taunt_1', 'Leaving already Rebels?'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 37, 'taunt_2', 'And I thought this was going to be another boring shift!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 38, 'taunt_3', 'Cut your engines immediately and we will spare your lives!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 39, 'taunt_4', 'The Inquisition will have our heads if we let these guys get away, failure is not an option men!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 40, 'taunt_5', 'You have your orders men, they can''t leave this system alive!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 41, 'thanks_1', 'Take that, Imperial scum!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 42, 'thanks_2', 'Lets keep moving before more of them show up!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 43, 'thanks_3', 'Nice shot pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 44, 'thanks_4', 'The Empire''s going to have to do a bit better than that with you around, good job pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 45, 'thanks_5', 'Suddenly, I''m not so worried anymore. You''re a monster of a fighter pilot!'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 46, 'title', 'Yavin system: Duty mission: Help Vortex personnel evacuate.'),
('string/en/spacequest/escort_duty/naboo_rebel_tier4_1.stf', 47, 'title_d', 'Some freighters with Vortex personnel have been ordered to evacuate to more secure locations in preparation for the attacks. Your mission is to provide a safe escort for them. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 1, 'Quest Log Data', 'Text'),
