('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 3, 'arrived_at_loc', 'Hold your current position until the arrival of the freighter we are to escort.'),
('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy ships detected. Incoming at high speeds.>'),
('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy ships eliminated.>'),
('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 6, 'complete', 'The freighter has safely made it''s delivery. Stand by to help escort another ship or return to your superior to check in.'),
