('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 11, 'failed_destroy', 'Your orders were to keep that ship safe. Report your failure to your superior.'),
('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 12, 'failed_protect', 'You have failed in your duty with your cowardice. Report your failed to your commander.'),
('string/en/spacequest/escort_duty/rori_station_imp_escort_duty_tier3.stf', 13, 'found_loc', 'We have sent the arrival location to your nav computer. Wait at that location for the arrival of the freighter and escort it safely through the sector.'),
