('string/en/spacequest/escort_duty/stn_dantooine_owner_all_escortduty_tier2_1.stf', 46, 'title', 'Dantooine System: Escort the Freighters Duty'),
('string/en/spacequest/escort_duty/stn_dantooine_owner_all_escortduty_tier2_1.stf', 47, 'title_d', 'The Dantooine station is having major supply problems. Partly because of its remoteness, but it also looses a large number of freighters to Dantooine Raiders. The station owner has hired you to escort his freighters through the Dantooine system.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 1, 'abort', 'Copy that, mission aborted.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 2, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Designated rendezvous point reached. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 3, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 4, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 5, 'complete', 'This Cycle is Complete'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 6, 'duty_update', '%TO'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 7, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 8, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 9, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 10, 'failed_destroy', 'You have failed the duty because the transport was destroyed.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 11, 'failed_protect', 'You have failed to protect the transport.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 12, 'found_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Rendezvous point locked in. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 13, 'goodbye_1', 'We are making our final approach now.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 14, 'goodbye_2', 'This is where we get off, thanks Captain.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 15, 'goodbye_3', 'Clearing for landing.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 16, 'goodbye_4', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 17, 'goodbye_5', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 18, 'hull_half', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 19, 'panic_1', 'Rebels, and they look dangerous.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 20, 'panic_2', 'Rebel scum!'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 21, 'panic_3', 'More Rebels!'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 22, 'panic_4', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 23, 'panic_5', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 24, 'quest_escort_d', 'Imperial Transport carrying goods and supplies for the Station.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 25, 'quest_escort_t', 'Imperial Transport'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 26, 'quest_location_d', 'The Transports will be making their jump a ways out from the station, travel to them and escort them back.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 27, 'quest_location_t', 'Endor System'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 28, 'quest_rendezvous_d', 'Travel here to meet with the transport.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 29, 'quest_rendezvous_t', 'Rendezvous Point'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 30, 'reason_1', 'Lets get a move on Captain, danger surrounds us.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 31, 'reason_2', 'Be careful, the enemy is watching.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 32, 'reason_3', 'Rebels were shadowing us earlier, so I expect an attack anytime.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 33, 'reason_4', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 34, 'reason_5', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 35, 'shields_depleted', 'Shields have been depleted.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 36, 'taunt_1', 'Give up your cargo!'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 37, 'taunt_2', 'This craft will not make its destination.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 38, 'taunt_3', 'For the Rebellion!'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 39, 'taunt_4', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 40, 'taunt_5', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 41, 'thanks_1', 'Excellent shooting Captain.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 42, 'thanks_2', 'That is all it takes.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 43, 'thanks_3', 'Rebel fools.'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 44, 'thanks_4', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 45, 'thanks_5', ''),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 46, 'title', 'Endor System: Duty: Escort Imperial Transports'),
('string/en/spacequest/escort_duty/stn_endor_irs_imp_tier4_1.stf', 47, 'title_d', 'Imperial Transports are flying goods and supplies into the Research Station.  Meet them at their arrival point and escort them safely to the base.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 1, 'abort', 'We are taking off, this craft is in no condition to fight on its own.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 2, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Designated rednezvous point reached. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 3, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 4, 'attack_stopped', '\\#pcontrast3 Tactical Comptuer: < \\#pcontrast1 Hostile activity has ceased.  \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 5, 'complete', '\\#pcontrast3 This round is complete.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 6, 'duty_update', ' \\#pcontrast3 < \\#pcontrast1 %TO\\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 7, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 8, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 9, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 10, 'failed_destroy', '\\#pcontrast3 The gunship was destroyed, you fail this mission.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 11, 'failed_protect', '\\#pcontrast3 You have failed to protect the gunship.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 12, 'found_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Rendezvous point locked in. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 13, 'goodbye_1', 'This is where we go.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 14, 'goodbye_2', 'Making the jump to hyperspace now.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 15, 'goodbye_3', 'Ok, we are out safely.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 16, 'goodbye_4', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 17, 'goodbye_5', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 18, 'hull_half', 'Hull integrity is at half.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 19, 'panic_1', 'SS fighters coming in fast.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 20, 'panic_2', 'Powering weapons.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 21, 'panic_3', 'TIE signatures detected.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 22, 'panic_4', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 23, 'panic_5', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 24, 'quest_escort_d', 'The gunship has had bad reactor damage.  Their shielding and weapon system will not be enough to ward off the Storm Squadron fighters on their own.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 25, 'quest_escort_t', 'Damaged Gunship'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 26, 'quest_location_d', 'The gunship will travel through the system to a safe jump point.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 27, 'quest_location_t', 'Lok System'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 28, 'quest_rendezvous_d', 'Travel here to meet the gunship for escort.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 29, 'quest_rendezvous_t', 'Rendezvous'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 30, 'reason_1', 'Be on your toes, we have reason to suspect Storm Squadron knows of our weakened state and will deem us a target of opportunity.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 31, 'reason_2', 'I don''t imagine we will have a peaceful trip today.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 32, 'reason_3', 'We will be an irresistable target for those Imperial fighters.  We must be cautious.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 33, 'reason_4', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 34, 'reason_5', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 35, 'shields_depleted', 'Shield energies have been depleated.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 36, 'taunt_1', 'You will pay for your lack of discression.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 37, 'taunt_2', 'Pirate dog, you will die.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 38, 'taunt_3', 'By Imperial decree, you will be destroyed.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 39, 'taunt_4', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 40, 'taunt_5', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 41, 'thanks_1', 'There goes one wave.  More will be in the area.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 42, 'thanks_2', 'I can''t imagine that will be the last of them.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 43, 'thanks_3', 'The Empire is an endless supply of fools.'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 44, 'thanks_4', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 45, 'thanks_5', ''),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 46, 'title', 'Lok System: Duty: Transport the Damaged Gunship'),
('string/en/spacequest/escort_duty/stn_lok_nym_reb_tier2_1.stf', 47, 'title_d', 'A Nym Gunship with a badly damaged reactor needs escort out of the system.  We expect heavy resistance from Storm Squadron fighters.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 1, 'abort', 'We really needed your help getting through this system. We should have never hired you.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 2, 'arrived_at_loc', 'Wait at this location for the arrival of the company freighter.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 3, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters detected. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 4, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters eliminated. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 5, 'complete', 'The freighter has completed its run and has launched in hyperspace. Prepare to meet a new freighter.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 6, 'duty_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 7, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 8, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 9, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 10, 'failed_destroy', 'You allowed the freighter to be destroyed. This does not bode well for the future of our company.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 11, 'failed_protect', 'You were hired to watch over that freighter until it could jump out of the system. We do not pay pilots, who do not complete their jobs.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 12, 'found_loc', 'Arrival location of the freighter located. Travel to this location and meet the freighter.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 13, 'goodbye_1', 'Thanks for watching over us. Be well, pilot.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 14, 'goodbye_2', 'Great work out there. We would never have made it past all those zealots without you.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 15, 'goodbye_3', 'I have my jump cooridnates locked in. Take care, pilot.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 16, 'goodbye_4', 'Preparing to make the jump to light speed. Safe journey to you.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 17, 'goodbye_5', 'You did good out there. Real good! See ya around.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 18, 'hull_half', 'Our hull is down to half strength! Requesting assistance.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 19, 'panic_1', 'Look out! Those cultists are back.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 20, 'panic_2', 'Great! Members of the debris cult.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 21, 'panic_3', 'I was hoping that this was going to be a nice quite flight.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 22, 'panic_4', 'Ok, let''s see your stuff.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 23, 'panic_5', 'Well, it looks like we are going to be swarmed by these loonies.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 24, 'quest_escort_d', 'Escort the freighter from the system and protect it from the Debris Cultists.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 25, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 26, 'quest_location_d', 'Meet the freighter full of minerals from the surface and escort it from the system.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 27, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 28, 'quest_rendezvous_d', 'Travel to the arrival location of the freighter and wait for it to arrive.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 29, 'quest_rendezvous_t', 'Meet the Freighter'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 30, 'reason_1', 'I need to get this shipment of minerals to the Tatoo system. So just watch my back until I can make the jump out of the system.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 31, 'reason_2', 'I need to get this shipment of steel to the Corellian system. So just watch my back until I can make the jump out of the system.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 32, 'reason_3', 'I need to get this shipment of gas to the Naboo system. So just watch my back until I can make the jump out of the system.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 33, 'reason_4', 'I need to get this shipment of radioactives to the Lok system. So just watch my back until I can make the jump out of the system.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 34, 'reason_5', 'I need to get this shipment of ore to the Bespin system. So just watch my back until I can make the jump out of the system.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 35, 'shields_depleted', 'They just knocked out our shields! Get those fighters off of us.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 36, 'taunt_1', 'And the great fireball spoke and we listened...and it was good.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 37, 'taunt_2', 'Nirvana awaits those who float amongst the debris.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 38, 'taunt_3', 'The light in the sky tells us that you must join it.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 39, 'taunt_4', 'Mohab said unto the crowd...the infidels who tarnish the field must pay with their life''s blood.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 40, 'taunt_5', 'You will be at peace soon, but I fear that an unbeliever like you will not be going to nirvana.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 41, 'thanks_1', 'The company sure got their moneys worth when they hired you.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 42, 'thanks_2', 'Well at least those cultists got what they wanted...to be part of the debris.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 43, 'thanks_3', 'I wonder if they will become martyrs for that?'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 44, 'thanks_4', 'Perhaps they should have choosen another religion.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 45, 'thanks_5', 'The galaxy now has a few less loonies running around.'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 46, 'title', 'Yavin System: Escort the Yavin Mining Co. Freighters'),
('string/en/spacequest/escort_duty/stn_yavin4_company_all_freighterescort_tier2_1.stf', 47, 'title_d', 'The Yavin 4 Mining Company is being accused by the Debris Cult of transporting salvage from the Yavin system out of the area and they are doing everything in their power to stop those freighters. The Yavin 4 Mining Company has hired you to make sure that their freighters make it out of the system in one piece.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 2, 'abort', 'Abort code received. Heading back to base.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 3, 'arrived_at_loc', 'Wait at this location. The escort target should arrive shortly.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 4, 'attack_notify', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostiles on approach vector to escort target! \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 5, 'attack_stopped', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile fighters eliminated. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 6, 'complete', 'The ship has made it through the region safely. Good job.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 7, 'duty_update', ' \\#pcontrast3 Imperial Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 11, 'failed_destroy', 'You allowed a valuable shipment of material to be lost! This is unacceptable. Report to your commanding officer at once!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 12, 'failed_protect', 'Your escort target has jumped to hyperspace without delivering its cargo! You will be blamed for this failure! Return to base.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 13, 'found_loc', 'Travel to the rendezvous waypoint and wait for your escort target to arrive.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 14, 'goodbye_1', 'Thanks for the escort. Things were a little rougher than usual, but I''ll still put in a good word for you.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 15, 'goodbye_2', 'Alright, I can take it from here. Time to get this cargo unloaded and take a well deserved rest.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 16, 'goodbye_3', 'Yeah! We made it. I owe you a drink, friend. You really came through for me that time.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 17, 'goodbye_4', 'What a ride! The Empire better pay me double for this one. Thanks for the escort, though.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 18, 'goodbye_5', 'I''m ready to begin the lightspeed jump to my next destination. Thanks for watching my back and good luck.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 19, 'hull_half', 'I''m tracking multiple hull breaches! I can''t take much more damage. Help!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 20, 'panic_1', 'By the Emperor! They''re moving in to attack. Help me, you fool. Help me!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 21, 'panic_2', 'I think...no it can''t be... They''re opening fire! Hostiles! Repeat, hostiles on attack vector!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 22, 'panic_3', 'Those new ships are moving in too fast for coincidence. Prepare for assault.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 23, 'panic_4', 'No, no, no. Not now. This was my last job of the day. Why can''t they leave my shipment alone!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 24, 'panic_5', 'Those new contacts don''t look friendly. May the Emperor guide you to victory, friend.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 25, 'quest_escort_d', 'Follow the freighter and protect it from attack. Enemy fighters will jump into the area and attack the freighter. Freighters are not very sturdy, so it is important for you to take out the enemy fighters as quickly as you can.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 26, 'quest_escort_t', 'Protect the Freighter'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 27, 'quest_location_d', 'Travel to theTatooine system and move towards your first navigation waypoint to begin the escort duty. After it arrives, follow the cargo freighter until it reaches its destination.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 28, 'quest_location_t', 'Travel to the Tatooine System'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 29, 'quest_rendezvous_d', 'Travel to the navigation waypoint and wait for the cargo freighter to arrive. Once the freighter is in the system, follow it to its destination.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 30, 'quest_rendezvous_t', 'Meet the Cargo Freighter'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 31, 'reason_1', 'I have to get these %TO to Bestine right away. Let''s go, I don''t have all day!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 32, 'reason_2', 'Ah, you''re on time. I hate sitting out here on a load of %TO unprotected.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 33, 'reason_3', 'I''ve got a hold full of %TO and I''m looking to get it unloaded before my shift ends and they keep me on overtime, so let''s move.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 34, 'reason_4', 'Good to see the Empire has an escort ready for me. Let''s get moving, High Command is expecting this shipment of %TO.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 35, 'reason_5', 'I''m locking in my route. Stay on my wing. These %TO are valuable and I don''t want to be out here alone.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 36, 'shields_depleted', 'Our shields are out. Get them off of me!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 37, 'taunt_1', 'Kill your engines and prepare to be boarded.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 38, 'taunt_2', 'If you release your cargo peacefully, we will not harm you.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 39, 'taunt_3', 'Time to die, Imperial scum!'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 40, 'taunt_4', 'I''ve got you in my sights.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 41, 'taunt_5', 'Kill the Imperial fools.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 42, 'thanks_1', 'Thanks for taking out those punks. Now let''s get this cargo to dock.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 43, 'thanks_2', 'Whew, thanks for thinking fast there. I would have been spaced without you.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 44, 'thanks_3', 'Impressive, friend! You certainly know how to use that thing.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 45, 'thanks_4', 'I can''t believe we made it. I think I need to change my flightsuit.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 46, 'thanks_5', 'You fight with the Emperor''s own passion, pilot. I''m honored to have you as a guide.'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 47, 'title', 'Tatooine System: Escort the Cargo Freighters Duty'),
('string/en/spacequest/escort_duty/tatooine_imperial_7.stf', 48, 'title_d', 'Travel to the Tatooine system and escort the cargo freighters through the system. An escort duty is a voluntary mission that you are able to quit at any time without repercussions. When you reach the Tatooine system, you will get a navigation waypoint to the arrival location of a cargo freighter that you will need to escort through the system. Travel to the waypoint and wait until the freighter hyperjumps into the system. Once it is in the area, it will begin to fly through the system. You need to follow the freighter until it reaches its destination. Keep a careful eye out for enemy attack since they will attempt to destroy this freighter. Once completed you will receive another waypoint to the arrival location of another freighter. This escort duty can be stopped at any time by simply aborting the mission or leaving the system.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 2, 'abort', 'You cannot leave us out here! We are carring important supplies for the Empire.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 3, 'arrived_at_loc', 'Hold at your current location. The vessel you are assigned to escort will be arriving shortly.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters detected.>'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter wing has been eliminated.>'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 6, 'complete', 'The freighter is safely away. Wait for command to assign you another freighter to escort or return to your commander to take a new mission.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 7, 'duty_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 11, 'failed_destroy', 'Your orders were to make sure that vessel arrived at HQ safely. Return to your superior and explain your failure.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 12, 'failed_protect', 'You left that vessel out there unarmed and at the mercy of pirates. You will have alot of explaining to do. Return to your superior.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 13, 'found_loc', 'The escort vessel will be arriving at the location supplied to your nav computer. Travel to that location and await the arrival of that vessel.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 14, 'goodbye_1', 'We appreciate your help out there pilot.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 15, 'goodbye_2', 'Thanks for getting us through this sector. Those Red Skulls really need to be cleared out.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 16, 'goodbye_3', 'You have done a great service to me and the Empire.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 17, 'goodbye_4', 'My cargo will help save honest Imperial lives. You have my thanks.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 18, 'goodbye_5', 'Be safe, pilot. Thanks for watching my back.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 19, 'hull_half', 'Hull at half strength! They told me you were good...prove it!'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 20, 'panic_1', 'Blasted pirates!'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 21, 'panic_2', 'Do I look worried? I think not.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 22, 'panic_3', 'Go get them. That is your job isn''t it?'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 23, 'panic_4', 'Pirates are after my booty! I always wanted to say that.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 24, 'panic_5', 'You had better send those pirates into oblivion.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 25, 'quest_escort_d', 'After you have met with your target transport, follow it through the Endor system until it arrives at it''s final destination. There is a good chance that pirates will attack and the transport must be defended at all costs because of the importance of it''s cargo.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 26, 'quest_escort_t', 'Protect the Imperial Transport'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 27, 'quest_location_d', 'The freighters are arriving in the Endor system before they are being attacked by the pirates. Meet them at their jump location inside the Endor system and escort them safely to their destination..'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 28, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 29, 'quest_rendezvous_d', 'Command will supply the jump in location of the transport. The freighter will not arrive until you are at that location.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 30, 'quest_rendezvous_t', 'Meet the Imperial Transport'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 31, 'reason_1', 'I have a ship full of cargo for the Engineers on the second moon.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 32, 'reason_2', 'I just arrived from a Yavin salvage operation. I understand you will be my escort.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 33, 'reason_3', 'I hope we have a smooth flight. My last one was an absolute mess. Pirates coming out of everywhere.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 34, 'reason_4', 'An escort? I don''t need an escort. I have been flying since the days of the Old Republic and I have never been attacked by anyone.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 35, 'reason_5', 'Glad to have you with me. I have some very valuable stuff on this ship and it would be a shame to lose it.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 36, 'shields_depleted', 'There went our shields! Get those fighters off of us.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 37, 'taunt_1', 'Give us the freighter and no one gets hurt.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 38, 'taunt_2', 'We just want what is ours...so give us your freighter.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 39, 'taunt_3', 'You are really starting to make me mad.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 40, 'taunt_4', 'Imperial scum like you are better off dead.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 41, 'taunt_5', 'That''s just great! You scratched my new paint job!'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 42, 'thanks_1', 'I am glad that you are out here.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 43, 'thanks_2', 'They were not that tough. Back in my day we used to have to fight twice as many pirates.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 44, 'thanks_3', 'Today is a glorious day for the Empire.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 45, 'thanks_4', 'Pirates are no match for your superior skills.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 46, 'thanks_5', 'Thanks for saving my skin.'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 47, 'title', 'Endor System: Protect the Imperial Transports Duty'),
('string/en/spacequest/escort_duty/tatooine_imperial_tier4_escortduty_1.stf', 48, 'title_d', 'Red Skull pirates have been attacking the increased Imperial traffic moving through the Endor system. The Emperor has decreed that all transports shall have an escort through the system because of the important cargo, nessecary for a top secret project in the system, that they are carrying.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 2, 'abort', '\\#pcontrast3 Transport: < \\#pcontrast1 We are outta here, no point sticking around if you are going to abandon us. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 3, 'arrived_at_loc', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hyperspace signatures detected. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1Enemy craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 The attack has stopped. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 6, 'complete', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Designated hyperspace jump point has been reached. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 7, 'duty_update', '%TO'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 8, 'escort_too_far1', ''),
