('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 11, 'failed_destroy', 'You have failed, your transport was destroyed.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 12, 'failed_protect', 'You have failed to protect your target.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 13, 'found_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Location to rendezvous located. \\#pcontrast3 >'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 14, 'goodbye_1', 'Good bye.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 15, 'goodbye_2', 'That is all, I''m out of here.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 16, 'goodbye_3', 'Good bye.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 17, 'goodbye_4', 'Good bye.'),
