('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 20, 'panic_1', 'More fighters!'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 21, 'panic_2', 'Help!'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 22, 'panic_3', 'Help!'),
