('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 26, 'quest_escort_d', 'Protect this freighter as it completes its route'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 27, 'quest_escort_t', 'Freighter'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 28, 'quest_location_d', 'Merchant route in the Tatooine System'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 29, 'quest_location_t', 'Tatooine System'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 30, 'quest_rendezvous_d', 'Travel here to meet up with the freighter'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 31, 'quest_rendezvous_t', 'Rendezvous Waypoint'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 32, 'quest_t', ''),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 33, 'reason_1', 'Those Black Sun are waiting, I can feel it.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 34, 'reason_2', 'I feel danger in the air today.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 35, 'reason_3', 'Those Black Sun are waiting, I can feel it.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 36, 'reason_4', 'Those Black Sun are waiting, I can feel it.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 37, 'reason_5', 'Those Black Sun are waiting, I can feel it.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 38, 'shields_depleted', 'Shields have been depleated.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 39, 'taunt_1', 'You will die!'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 40, 'taunt_2', 'Why don''t you just leave the freighter to us and move along.'),
('string/en/spacequest/escort_duty/tatooine_privateer_7.stf', 41, 'taunt_3', 'You will die!'),
