('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 5, 'complete', 'Alliance HQ: < The refugees have made it through the region safely. Good job. >'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 6, 'duty_update', ' \\#pcontrast3 Alliance HQ: < \\#pcontrast1 %TO \\#pcontrast3 >'),
