('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 8, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 9, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 10, 'failed_destroy', 'Those refugees were depending on you, Pilot! Return to your commanding officer at once!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 11, 'failed_protect', 'The Alliance refugee transport has been redirected. Your mission is a failure.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 12, 'found_loc', 'Travel to the rally point and wait for your escort target to arrive.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 13, 'goodbye_1', 'Everyone on-board appreciates your help! Thank you!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 14, 'goodbye_2', 'Alright, I can take it from here. Time to get these people home... Thanks!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 15, 'goodbye_3', 'Yeah! We made it. The Alliance owes you a debt of gratitude. Thanks!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 16, 'goodbye_4', 'What a ride! The Alliance owes me more than standard pay, I think! Thanks for the escort, though.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 17, 'goodbye_5', 'We''re ready to get these refugees back home. Thanks for the escort!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 18, 'hull_half', 'I''m tracking multiple hull breaches! I can''t take much more damage. Help!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 19, 'panic_1', 'They''re moving to attack! Please help us!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 20, 'panic_2', 'I think...no it can''t be... They''re opening fire! Hostiles! Repeat, hostiles on attack vector!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 21, 'panic_3', 'Those new ships are moving in too fast for coincidence. Prepare for assault.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 22, 'panic_4', 'No, no, no. Not now. This was my last job of the day. Why can''t they leave my shipment alone!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 23, 'panic_5', 'Those new contacts don''t look friendly. The Force be with you, friend.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 24, 'quest_escort_d', 'Follow the Alliance Transport as it makes its way out of the system. Protect the transport from hostile forces as it advances. Once a transport has reached its destination, Alliance HQ will provide a new waypoint to another distressed transport.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 25, 'quest_escort_t', 'Escort Alliance Transport.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 26, 'quest_location_d', 'Patrol the Tatooine system and protect Alliance transports that have been separated from the main fleet.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 27, 'quest_location_t', 'Tatooine system.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 28, 'quest_rendezvous_d', 'Fly to the nav point and intercept an incoming Alliance Transport.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 29, 'quest_rendezvous_t', 'Intercept Alliance Transport.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 30, 'reason_1', 'Alliance Freighter reporting! We have a hold full of refugees who need to get home, buddy.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 31, 'reason_2', 'Requesting fighter escort. Repeat! Requesting fighter escort!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 32, 'reason_3', 'Hey there, pilot! Let''s get these refugees back home. Whadda you say?'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 33, 'reason_4', 'Good to see you, pilot! Cover us so we can get these refugees back where they belong.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 34, 'reason_5', 'This is the freight commander speaking. Form up and keep us safe! We have a lot of injured on-board and don''t need any more excitement!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 35, 'shields_depleted', 'Our shields are out. Get rid of those fighters now!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 36, 'taunt_1', 'Rebel scum! Prepare to die!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 37, 'taunt_2', 'Refugees, eh? You expect us to believe that... traitor?!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 38, 'taunt_3', 'Time to die, Rebel scum!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 39, 'taunt_4', 'I''ve got you in my sights.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 40, 'taunt_5', 'Kill the Rebel traitors!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 41, 'thanks_1', 'Thanks for taking out those punks. Now let''s get these refugees back home!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 42, 'thanks_2', 'Whew, thanks for thinking fast there. We would have been spaced without your help!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 43, 'thanks_3', 'Very impressive, my friend! The Force is with you...'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 44, 'thanks_4', 'I can''t believe we made it! Thanks a million, pal!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 45, 'thanks_5', 'All refugees safe and sound. Thanks for your help, pilot!'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 46, 'title', 'Tatooine system: Duty mission: Protect Refugee Transports.'),
('string/en/spacequest/escort_duty/tatooine_rebel_7.stf', 47, 'title_d', 'Protect Refugee Transports. These missions have been outlined to give you some much needed experience in space combat, you can stop when you feel that you have learned enough.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 1, 'abort', 'You can''t abort now, we''re not safe yet!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 2, 'arrived_at_loc', 'The spy ship should be there any second, stand by.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 3, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 4, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 5, 'complete', 'Good job pilot, they are safe from there. Stand by for your next assignment.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 6, 'duty_update', 'Rebel Command: < %TO >'),
