('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 10, 'failed_destroy', 'We cant afford those kind of casaulties pilot. Return to base.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 11, 'failed_protect', 'The spy ship was forced to do an emergency hyperspace jump. I hope for your sake that they are okay. Return to base.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 12, 'found_loc', 'One of our spy ships will meet you at these coordinates, proceed.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 13, 'goodbye_1', 'Jumping to lightspeed. Thank you for the help pilot.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 14, 'goodbye_2', 'Well that was a rush! See you around pilot.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 15, 'goodbye_3', 'We''re safe from here, was a privilege to work with you pilot!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 16, 'goodbye_4', 'That was fun! Want to do it again? Just kidding, thanks again pilot!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 17, 'goodbye_5', 'We''re ready to take off, thanks for providing a solid escort pilot.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 18, 'hull_half', 'Our ship is falling apart, you have to take care of these TIE''s, now!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 19, 'panic_1', 'Time to prove your worth pilot.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 20, 'panic_2', 'I hope you''re as good as we were told.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 21, 'panic_3', 'To battle stations!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 22, 'panic_4', 'I didn''t think we could slip out undetected.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 23, 'panic_5', 'Here they come!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 24, 'quest_escort_d', 'Escort the spy ship to safety pilot. Not only do they have invaluable data onboard but you are responsible for the life of the crew as well and in these days, we can''t afford to lose anyone.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 25, 'quest_escort_t', 'Escort spy ship to safety.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 26, 'quest_location_d', 'The Imperial navy seem to be everywhere in the Endor system lately and they are guarding the moon of Endor fiercely. Stay sharp out there pilot, the lives of the crew on those spy ships may very well be in your hands.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 27, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 28, 'quest_rendezvous_d', 'We will keep updating your nav computer with coordinates of new spy ships that need an escort out of the system. When you have exhausted yourself, your ship or feel that you are experienced enough for more training, return to base.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 29, 'quest_rendezvous_t', 'New rendez-vous coordinates.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 30, 'reason_1', 'Alright, lets get out of here.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 31, 'reason_2', 'We''ve been hiding in a nebula for a week scanning the surface of that worthless moon, can''t wait to get out of here.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 32, 'reason_3', 'Good to see you pilot, lets not waste any time.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 33, 'reason_4', 'We''re ready to leave this system, lets go.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 34, 'reason_5', 'Greetings pilot, glad that you are here. Lets get moving.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 35, 'shields_depleted', 'That last hit fried our shields, we''re in trouble!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 36, 'taunt_1', 'Leaving already Rebels?'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 37, 'taunt_2', 'And I thought this was going to be another boring shift!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 38, 'taunt_3', 'Cut your engines immediately and we will spare your lives!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 39, 'taunt_4', 'Sorry to crash your party Rebel fools!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 40, 'taunt_5', 'You have your orders men, they can''t leave this system alive!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 41, 'thanks_1', 'Take that, Imperial scum!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 42, 'thanks_2', 'Lets keep moving before more of them show up!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 43, 'thanks_3', 'Nice shot pilot!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 44, 'thanks_4', 'Hehehe.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 45, 'thanks_5', 'Is that the best the Empire have? Wimps!'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 46, 'title', 'Endor system: Duty mission: Escort Rebel spy vessels.'),
('string/en/spacequest/escort_duty/tatooine_rebel_tier4_1.stf', 47, 'title_d', 'We have several of our spy vessels assigned to the Endor system to try and figure out what the Empire is doing on the moon of Endor. They need safe escorts when they are ready to return to base with their findings or to re-supply.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 2, 'abort', 'Abort code received, performing emergency hyperspace jump.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 3, 'arrived_at_loc', 'You are at the right coordinates pilot, the smuggler should be there momentarily.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 4, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 5, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 6, 'complete', 'The smuggler is safe from here, nice flying out there pilot!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 7, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 11, 'failed_destroy', 'We lost contact with the smuggler, what happened? This is a hard blow to us pilot, we''re already struggling with low resources.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 12, 'failed_protect', 'The smuggler had to do a emergency hyperspace jump, he didn''t have enough protection. I hope he will be alright.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 13, 'found_loc', 'The next smuggler should meet you at these coordinates pilot.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 14, 'goodbye_1', 'Great working with ya mate, I''ll be fine now!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 15, 'goodbye_2', '''twas a pleasure pilot, see ya!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 16, 'goodbye_3', 'Always nice to work with competent people, see you again sometime I hope!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 17, 'goodbye_4', 'Wouldn''t have made it without you pilot, thanks!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 18, 'goodbye_5', 'I owe you a big one pilot, could never have made that on my own!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 19, 'hull_half', 'Crap, this thing is falling apart, I need some help!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 20, 'panic_1', 'I''m being scanned... Darnit, Imperials!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 21, 'panic_2', 'Here they come, like a flock of angry mynocks!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 22, 'panic_3', 'They picked us up, incoming TIE fighters!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 23, 'panic_4', 'Oh @#!%, Imperial fighters heading our way!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 24, 'panic_5', 'Uh oh, these guys look pissed!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 25, 'quest_escort_d', 'Provide a safe escort for the smuggler. Stay close to him and keep your eyes open for any threats.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 26, 'quest_escort_t', 'Escort the smuggler.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 27, 'quest_location_d', 'The Lok system has a low Imperial presence but they perform raids on pirates and rebels from time to time so be careful.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 28, 'quest_location_t', 'Lok system.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 29, 'quest_rendezvous_d', 'You should now have the coordinates of the next smuggler in need of an escort, hurry over there.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 30, 'quest_rendezvous_t', 'Coordinates of the next smuggler.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 31, 'reason_1', 'Good to see ya mate! Lets get this show on the road.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 32, 'reason_2', 'Hi there pilot, you''re my escort eh? Well I hope you''re good.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 33, 'reason_3', 'Hi there, I have several wounded soldiers in the back, so hopefully this will be a smooth ride.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 34, 'reason_4', 'Greetings, keep up, I''m not waiting for anyone!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 35, 'reason_5', 'Hey there, we should be fine, just keep me covered in case things get hot.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 36, 'shields_depleted', 'Shields depleted! We''re in trouble now!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 37, 'taunt_1', 'Do you Rebels think we''re stupid? Lethal force allowed, proceed men.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 38, 'taunt_2', 'You Rebels made a mistake, you always do.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 39, 'taunt_3', 'We could see you Rebel fools miles away, Imperial justice doesn''t let anything slip by!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 40, 'taunt_4', 'You couldn''t smuggle sand to Tatooine, poor little Rebels.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 41, 'taunt_5', 'These Rebels actually thought they could get away with it. Use of lethal force is encour..approved.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 42, 'thanks_1', 'Nice work pilot! I thought they had us!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 43, 'thanks_2', 'I sure am glad you were here pilot.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 44, 'thanks_3', 'I knew I should have put wipers on this ship, there''s TIE scraps all over my windshield.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 45, 'thanks_4', 'I wasn''t even worried, nice going pilot!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 46, 'thanks_5', 'I don''t think those guys knew what hit them, way to go!'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 47, 'title', 'Lok system: Duty mission: Escort smugglers past Imperial patrols.'),
('string/en/spacequest/escort_duty/viopa_rebel_5.stf', 48, 'title_d', 'Your orders are to provide a safe escort for Rebel and Nym smugglers in the Lok system. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 2, 'abort', 'Abort code received, performing emergency hyperspace jump.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 3, 'arrived_at_loc', 'You have arrived at the rendez-vous coordinates. Expect freighter to arrive shortly.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 4, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 5, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 6, 'complete', 'The Freighter is safe, great job!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 7, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 11, 'failed_destroy', 'The Alliance is already struggling with equipment, we can''t loose important transports like that! We expect a full report upon your return!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 12, 'failed_protect', 'The transport had to make a emergency hyperspace jump since he couldn''t count on your protection! Pray that he made it in one piece.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 13, 'found_loc', 'We have uploaded the coordinates for the next transport in need of a escort.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 14, 'goodbye_1', 'We will be okay from here. Thank you for your invaluable assistance pilot.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 15, 'goodbye_2', 'It was a pleasure to work with you pilot, I hope to see you again.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 16, 'goodbye_3', 'We only got out of that in one piece thanks to you pilot. I owe you one!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 17, 'goodbye_4', 'Score one for the good guys! Thanks a lot my friend, be careful out here.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 18, 'goodbye_5', 'Thank you for the escort pilot. I''ll buy you a drink the next time I see you!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 19, 'hull_half', 'This old hunk of metal is breaking apart! You better get them off us now!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 20, 'panic_1', 'Imperial patrol heading our way! Show them what you''re made of pilot!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 21, 'panic_2', 'TIE Fighters! This could get ugly.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 22, 'panic_3', 'I''m being scanned by an Imperial patrol!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 23, 'panic_4', 'Imperial scum incoming! Performing evasive maneuvers!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 24, 'panic_5', 'Lackeys of the Empire heading our way!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 25, 'quest_escort_d', 'The Alliance is stretched thin on resources as it is so make sure that every smuggler makes it to their destination safely.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 26, 'quest_escort_t', 'Escort smuggler.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 27, 'quest_location_d', 'The Dantooine system has had an increasing amount of Imperial presence so escorting these smugglers safely will prove a challenge.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 28, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 29, 'quest_rendezvous_d', 'We have been contacted by another smuggler in need of assistance. You should have the coordinates so get going.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 30, 'quest_rendezvous_t', 'Contacted by another smuggler.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 31, 'reason_1', 'G''day pilot. Glad you are here, these sectors are overrun with Imperial scum.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 32, 'reason_2', 'Greetings, I got some disabled soldiers that need transport to a medical frigate. Take well care of us pilot.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 33, 'reason_3', 'Great to see you pilot. I have weapons and electrical equipment onboard so hopefully no Imperial patrols will get too close.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 34, 'reason_4', 'Hail friend! Hauling some X-Wing replacement parts for the frontlines here. You will make sure we reach them safely right?'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 35, 'reason_5', 'You better not slow me down hotshot...'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 36, 'shields_depleted', 'Our shields are fried! Do your job and get these TIE''s of us now!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 37, 'taunt_1', 'What do we have here? Poor little Rebel scum, you just took a wrong turn. Your last mistake!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 38, 'taunt_2', 'Imperial security patrol to unidentified cargo freighter. We have detected suspicious...bah, die Rebel scum!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 39, 'taunt_3', 'The might of the Empire will crush you all, foolish Rebels!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 40, 'taunt_4', 'You are in violation of Imperial law, code XA-313-C. Prepare to die!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 41, 'taunt_5', 'Hey, Rebel fool. You will be the fifth of your despicable kind that I blow to pieces this week!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 42, 'thanks_1', 'I hope those were the last ones...'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 43, 'thanks_2', 'Alright! Lets get this baby out of here before more of them show up.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 44, 'thanks_3', 'Good guys 1 Evil Empire 0!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 45, 'thanks_4', 'Haha! That last TIE pilot will be flying all the way to Coruscant, without his ship!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 46, 'thanks_5', 'I knew we had the best fighter pilots in the galaxy, way to go!'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 47, 'title', 'Dantooine system: Duty mission: Escort Rebel Smugglers.'),
('string/en/spacequest/escort_duty/vortex_mission_5.stf', 48, 'title_d', 'Various Alliance smugglers need a safe escort and it''s your job to provide them with it. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 2, 'abort', 'Abort code received. Heading back to base.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 3, 'arrived_at_loc', 'Wait at this location. An Alliance refugee transport will arrive shortly.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 4, 'attack_notify', 'Tactical Computer: < Vessels on intercept course approaching, weapon systems armed. >'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 5, 'attack_stopped', 'Tactical Computer: < Sensors indicate no more fighter vessels with armed weapon systems in area. >'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 6, 'complete', 'The refugees have made it through the region safely. Good job.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 7, 'duty_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 8, 'escort_too_far1', ''),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 9, 'escort_too_far2', ''),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 10, 'escort_too_far3', ''),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 11, 'failed_destroy', 'Those refugees were depending on you, Pilot! Return to your commanding officer at once!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 12, 'failed_protect', 'The Alliance refugee transport has been redirected. Your mission is a failure.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 13, 'found_loc', 'Travel to the rally point and wait for the refugee transport to arrive.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 14, 'goodbye_1', 'Everyone on-board appreciates your help! Thank you!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 15, 'goodbye_2', 'Alright, I can take it from here. Time to get these people home... Thanks!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 16, 'goodbye_3', 'Yeah! We made it. The Alliance owes you a debt of gratitude. Thanks!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 17, 'goodbye_4', 'What a ride! The Alliance owes me more than standard pay, I think! Thanks for the escort, though.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 18, 'goodbye_5', 'We''re ready to get these refugees back home. Thanks for the escort!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 19, 'hull_half', 'I''m tracking multiple hull breaches! I can''t take much more damage. Help!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 20, 'panic_1', 'They''re moving to attack! Please help us!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 21, 'panic_2', 'I think...no it can''t be... They''re opening fire! Hostiles! Repeat, hostiles on attack vector!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 22, 'panic_3', 'Those new ships are moving in too fast for it to be a coincidence. Prepare for assault.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 23, 'panic_4', 'No, no, no. Not now. This was my last job of the day. Why can''t they just leave us alone!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 24, 'panic_5', 'Those new contacts don''t look friendly. The Force be with us, friend.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 25, 'quest_escort_d', 'This will prove to be quite tough, the Empire''s block on the Yavin 4 moon will make sneaking out without being noticed near to impossible.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 26, 'quest_escort_t', 'Escort the refugee freighter.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 27, 'quest_location_d', 'Since the destruction of the Imperial enormous space station the Yavin system is overrun with Imperial forces trying to salvage what''s left of it and making sure no one else steal anything. They have put a blockade up over the moon of Yavin 4 so escorting the refugee freighters will prove tricky.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 28, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 29, 'quest_rendezvous_d', 'You should now have the coordinates of another refugee freighter in need of an escort. Hurry over there and protect them at all costs.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 30, 'quest_rendezvous_t', 'Location of refugee freighter.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 31, 'reason_1', 'Alliance Freighter reporting! We have a hold full of refugees who need to get home, buddy.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 32, 'reason_2', 'Requesting fighter escort. Repeat! Requesting fighter escort!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 33, 'reason_3', 'Hey there, pilot! Let''s get these refugees back home. Whadda you say?'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 34, 'reason_4', 'Good to see you, pilot! Cover us so we can get these refugees back where they belong.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 35, 'reason_5', 'This is the freight commander speaking. Form up and keep us safe! We have a lot of injured on-board and don''t need any more excitement!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 36, 'shields_depleted', 'Our shields are out. Get rid of those fighters now!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 37, 'taunt_1', 'Rebel scum! Prepare to die!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 38, 'taunt_2', 'Refugees, eh? You expect us to believe that... traitor?!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 39, 'taunt_3', 'Time to die, Rebel scum!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 40, 'taunt_4', 'I''ve got you in my sights.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 41, 'taunt_5', 'Kill the Rebel traitors!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 42, 'thanks_1', 'Thanks for taking out those punks. Now let''s get these refugees back home!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 43, 'thanks_2', 'Whew, thanks for thinking fast there. We would have been spaced without your help!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 44, 'thanks_3', 'Very impressive, my friend! The Force is with you...'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 45, 'thanks_4', 'I can''t believe we made it! Thanks a million, pal!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 46, 'thanks_5', 'All refugees safe and sound. Thanks for your help, pilot!'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 47, 'title', 'Yavin system: Duty mission: Protect refugee freighters.'),
('string/en/spacequest/escort_duty/yavin_rebel_10.stf', 48, 'title_d', 'With the increased Imperial threat in the Yavin system, the Alliance is helping refugees escape the system. You need to make sure they make it through the Imperial blockade safely. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 6, 'quest_dock_d', 'Once you have succeeded in finding the Personnel Dossier you will need to dock with the ship in order to transfer the data. Use the /dock command in order to start the docking procedure. Wait until the procedure is complete and you receive the system message of success before leaving. Be very careful at this point because you will be vunlerable to attacks while docked with another vessel.'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 7, 'quest_dock_t', 'Dock with the Rebel Smuggler and Transfer the Personnel Dossier'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 8, 'quest_inspect_d', 'Inspect the Rebel smuggler vessel for the Personnel Dossier. To inspect a ship first you must disable it''s engines by targeting its subsystems. Use the ''['' or '']'' key in order to target its engines. Attack the vessel until its engines are at 0%. Then move in close and use the /inspect or press the ''I'' key to start inspecting the Rebel smuggler. Make sure you have the disabled Rebel smuggler targeted when you attempt this.'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 9, 'quest_inspect_t', 'Inspect the Rebel Smuggler'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 10, 'quest_location_d', 'Travel to the Corellia system and inspect the Rebel smuggler. You will receive a navigation waypoint to the area that the Rebel smuggler can be found in. Travel to this navigation waypoint and look around for the Rebel smuggler.'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 11, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 12, 'split_quest_alert', ''),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 14, 'title', 'Corellia System: Inspect the Rebel Smuggler'),
('string/en/spacequest/inspect/corellia_imperial_13.stf', 15, 'title_d', 'Travel to the Corellia system and inspect the Rebel smuggler. When you enter the system you will receive a navigation waypoint to an area that the Rebel smuggler should be. Travel to this location and look around it for the Rebel smuggler. Once you have found the smuggler you will need to disable his vessel. In order to disable a vessel use the ''['' or '']'' to target the ships subsystems and target its engines. Attack the Rebel smuggler until its engines are at 0%. Now move in close and use presse the ''I'' key or type /inspect with the Rebel smuggler targeted. After you have found the personnel dossier, type /dock in order to transfer the dossier onto your ship. Be wary because you will be very vunerable while docking with another vessel.'),
