('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 6, 'quest_dock_d', 'Dock with the disabled spy and transfer the Joint Operations Plan to your ship. Once you have that you will need to delivery that a command shuttle immediatley.'),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 7, 'quest_dock_t', 'Transfer the Joint Operations Plan'),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 8, 'quest_inspect_d', 'Scans indicate that a Rebel spy is in the region. This vessel must be disabled and searched in order to discover what information he might have on the alliance between the Rebels and Nym. '),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 9, 'quest_inspect_t', 'Inspect the Rebel Spy'),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 10, 'quest_location_d', 'The signature shows that the Rebel''s vessel is located inside the Yavin system.'),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 11, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 12, 'split_quest_alert', 'Headquarters needs that information immediately. Transfer it to an Imperial shuttle for immediate delivery to command.'),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 14, 'title', 'Yavin System: Inspect the Rebel Spy'),
('string/en/spacequest/inspect/corellia_imperial_tier3_1_a.stf', 15, 'title_d', 'Remain in the Yavin system and inspect the Rebel spy. While on your patrol your short range scanners picked up the signature of a Rebel spy. Intercept and disable this Rebel, so you can inspect it for any sort of operations plan between Nym and the Rebellion.'),
