('string/en/spacequest/inspect/corellia_imperial_tier4_1_a.stf', 8, 'quest_inspect_d', 'Disable and inspect the captain for any information regarding their operation in the Dantooine system.'),
('string/en/spacequest/inspect/corellia_imperial_tier4_1_a.stf', 9, 'quest_inspect_t', 'Inspect the Velocity Mercenary Captain'),
('string/en/spacequest/inspect/corellia_imperial_tier4_1_a.stf', 10, 'quest_location_d', 'The target vessels signal is coming from inside the Dantooine system. Intercept the Velocity mercenary captain at the supplied navigation waypoint.'),
('string/en/spacequest/inspect/corellia_imperial_tier4_1_a.stf', 11, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/inspect/corellia_imperial_tier4_1_a.stf', 12, 'split_quest_alert', 'Interesting, the reports you have recovered have a communications relay point and frequency indicated in them. Travel to location and tune into the frequency.'),
