('string/en/spacequest/inspect/corellia_imperial_tier4_2_a.stf', 9, 'quest_inspect_t', 'Inspect the Velocity Mercenary Group Leader'),
('string/en/spacequest/inspect/corellia_imperial_tier4_2_a.stf', 10, 'quest_location_d', 'The target vessel is in the area. Intercept and disable that craft at the supplied navigation waypoint.'),
('string/en/spacequest/inspect/corellia_imperial_tier4_2_a.stf', 11, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/inspect/corellia_imperial_tier4_2_a.stf', 12, 'split_quest_alert', 'Bring those orders to a shuttle that will meet you in Dantooine space. Insurgent wants to get a close and personal look at them. Stand by for nav coordinates.'),
