('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 8, 'quest_inspect_d', 'Disable this craft by shooting out their engines, then /inspect to search their cargo'),
('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 9, 'quest_inspect_t', 'Evil Raider Tyrant'),
('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 10, 'quest_location_d', 'Location of the Endor System with a confirmed Tyrant sighting'),
('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 11, 'quest_location_t', 'Endor System'),
('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 12, 'split_quest_alert', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Excellent! Now.. deliver the information to one of our Lancers. Further intructions will be given to you as soon as we know them. \\#pcontrast3 >'),
('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 14, 'title', 'Space Endor: Recover Information from the Raider Tyrant'),
('string/en/spacequest/inspect/corellia_privateer_tier3_4_b.stf', 15, 'title_d', 'Recover information from the Evil Raider Tyrant'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 6, 'quest_dock_d', 'When you have disabled and inspected a Hutt smuggler with system reconnaissance data in their computer, dock with them and transfer it to your ship.'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 7, 'quest_dock_t', 'System reconnaissance data.'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 8, 'quest_inspect_d', 'Inspect Hutt Spice Smugglers until you find one that is carrying system reconnaissance data in their computer. When you find one, disable and dock with it to transfer the data to your ship.'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 9, 'quest_inspect_t', 'Inspect Hutt Spice Smugglers.'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 10, 'quest_location_d', 'We don''t have much information about the Endor system currently and hope that you can get us some data from the Hutt smugglers in this sector.'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 11, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 12, 'split_quest_alert', 'Rebel Fleet Command: < Somehow the Hutts have information about the Imperial Navy moving in on our position! Deliver this data to our fleet in the Lok sector. >'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 14, 'title', 'Endor system: Find out what the Hutt smugglers know about the system.'),
('string/en/spacequest/inspect/corellia_rebel_tier3_2.stf', 15, 'title_d', 'The Endor system is fairly uncharted to us. We''ve spotted some Hutt smugglers though and if anyone have information about the system, it would be them. Your mission is to try and find one of their smugglers with Endor system data in their computer and steal it from them.'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/imperial_ss_1.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/imperial_ss_1.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/imperial_ss_1.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/imperial_ss_1.stf', 6, 'quest_dock_d', 'Once you have succeeded in finding the Hostage Orders you will need to dock with the ship in order to transfer the data. Use the /dock command in order to start the docking procedure. Wait until the procedure is complete and you receive the system message of success before leaving. Be very careful at this point because you will be vunlerable to attacks while docked with another vessel.'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 7, 'quest_dock_t', 'Dock with the Nym Lieutenant and Transfer the Hostage Orders'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 8, 'quest_inspect_d', 'Inspect a Nym Lieutenant''s vessel for the Hostage Orders. To inspect a ship first you must disable it''s engines by targeting its subsystems. Use the ''['' or '']'' key in order to target its engines. Attack the vessel until its engines are at 0%. Then move in close and use the /inspect or press the ''I'' key to start inspecting the Nym Lieutenant. Make sure you have the disabled the Nym Lieutenant targeted when you attempt this.'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 9, 'quest_inspect_t', 'Inspect the Nym Lieutenant'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 10, 'quest_location_d', 'Travel to the Lok system and inspect a Nym Lieutenant. You will need to search the system for your target, but a good place to start your search is near the Lok space station.'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 11, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 12, 'split_quest_alert', ''),
('string/en/spacequest/inspect/imperial_ss_1.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/imperial_ss_1.stf', 14, 'title', 'Lok System: Inspect the Nym Lieutenants'),
('string/en/spacequest/inspect/imperial_ss_1.stf', 15, 'title_d', 'Travel to the Lok system and inspect a Nym lieutenant. When you enter the system you will need to search the system for a Nym lieutenant. A good place to start is near the Lok space station. Once you have found a Nym lieutenant you will need to disable his vessel. In order to disable a vessel use the ''['' or '']'' to target the ships subsystems and target its engines. Attack the Nym lieutenant until its engines are at 0%. Now move in close and use presse the ''I'' key or type /inspect with the Nym lieutenant targeted. After you have found the hostage orders, type /dock in order to transfer the orders onto your ship. Be wary because you will be very vunerable while docking with another vessel.'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 1, 'Quest Log Data', 'Text');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/inspect/imperial_ss_4.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/imperial_ss_4.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/imperial_ss_4.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/imperial_ss_4.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/imperial_ss_4.stf', 6, 'quest_dock_d', 'Once you have found the activity log, transfer it to your vessel by docking with the disabled agent.'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 7, 'quest_dock_t', 'Transfer the Yavin Activity Logs'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 8, 'quest_inspect_d', 'Disable and inspect a Rebel Agent for an activity log. It is very possible that not every agent will have a completed activity log. You will have to keep inspecting Rebel agents until you locate one.'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 9, 'quest_inspect_t', 'Inspect a Rebel Agent'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 10, 'quest_location_d', 'The meeting location is inside the Yavin system. A navigation waypoint to this meeting area will be supplied to you when you reach the Yavin system.'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 11, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 12, 'split_quest_alert', ''),
('string/en/spacequest/inspect/imperial_ss_4.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/imperial_ss_4.stf', 14, 'title', 'Yavin System: Inspect the Rebel Agent'),
('string/en/spacequest/inspect/imperial_ss_4.stf', 15, 'title_d', 'Travel to the Yavin system and inspect the Rebel agent. The first step in discovering what the Rebels have located is to find an operations report on one of their agents. Intelligence has located an area that agents meet with flight commanders to exchange information. You must get to this location and inspect an agent for a completed activity report. If an agent is not at the location when you arrive you might need to destroy a few of the commanders to get some more Rebel pilots to come to the rescue.'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 6, 'quest_dock_d', 'Once you have succeeded in finding the encrypted documents, you will need to dock with the ship in order to transfer the data. Use the /dock command in order to start the docking procedure. Wait until the procedure is complete and you receive the system message of success before leaving. Be very careful at this point because you will be vunlerable to attacks while docked with another vessel.'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 7, 'quest_dock_t', 'Dock with the Railgun Mercenary Courier and Transfer the Encrypted Documents'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 8, 'quest_inspect_d', 'Inspect the Railgun mercenary courier''s vessel for the encrypted documents. To inspect a ship first you must disable it''s engines by targeting its subsystems. Use the ''['' or '']'' key in order to target its engines. Attack the vessel until its engines are at 0%. Then move in close and use the /inspect or press the ''I'' key to start inspecting the Railgun mercenary courier. Make sure you have the disabled Railgun mercenary courier targeted when you attempt this.'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 9, 'quest_inspect_t', 'Inspect the Railgun Mercenary Courier'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 10, 'quest_location_d', 'Travel to the Naboo system and inspect the Railgun mercenary courier. You will receive a navigation waypoint to the area that the Railgun mercenary courier can be found in. Travel to this navigation waypoint and look around for the Railgun mercenary courier.'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 11, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 12, 'split_quest_alert', ''),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 14, 'title', 'Naboo System: Inspect the Railgun Mercenary Courier'),
('string/en/spacequest/inspect/naboo_imperial_tier2_1.stf', 15, 'title_d', 'Travel to the Naboo system and inspect the Railgun mercenary courier. When you enter the system you will receive a navigation waypoint to an area that the Railgun mercenary courier should be. Travel to this location and look around it for the Railgun mercenary courier. Once you have found the courier you will need to disable his vessel. In order to disable a vessel use the ''['' or '']'' to target the ships subsystems and target its engines. Attack the Railgun mercenary courier until its engines are at 0%. Now move in close and use the ''I'' key or type /inspect with the Railgun mercenary courier targeted. After you have found the encrypted documents, type /dock in order to transfer the documents onto your ship. Be wary because you will be very vulnerable while docking with another vessel.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 6, 'quest_dock_d', 'Once you have found the report, dock with the fighter, and transfer it to your craft.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 7, 'quest_dock_t', 'Transfer the Pirate Sector Report'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 8, 'quest_inspect_d', 'Intercept the mercenary spy, disable his craft, and inspect it for the data that was transfered between the yacht and fighter.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 9, 'quest_inspect_t', 'Inspect the Mercenary Spy'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 10, 'quest_location_d', 'Command has a lock on the mercenary craft inside the Yavin system. You are to travel to the Yavin system and inspect the fighter. A navigation waypoint will be supplied to the mercenary spy''s location.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 11, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 12, 'split_quest_alert', 'Nice work, pilot. We are sending a freighter to your area for transfer of that data. Stand by for coordinates to the transfer vessel.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 14, 'title', 'Yavin System: Inspect the Mercenary Spy'),
('string/en/spacequest/inspect/naboo_imperial_tier3_1_a.stf', 15, 'title_d', 'The Yacht made a stop in the Yavin system and met with a mercenary fighter. The computers indicate that some information was transfered between the two vessels and Command wants to know what that information contained.'),
