('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 7, 'quest_dock_t', 'Transfer the Personal Logs'),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 8, 'quest_inspect_d', 'Once you have located the doctor''s yatch, disable and inspect it.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 9, 'quest_inspect_t', 'Inspect the Doctor Shinss'' Yacht'),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 10, 'quest_location_d', 'Doctor Shinss is working on the salvage operation in the Yavin system and has been using his personal yacht a great deal. You will be supplied with a navigaiton waypoint to where the yacht is moored.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 11, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 12, 'split_quest_alert', 'Proceed immediately to Imperial Communications Satellite 247d to transmit data. Location will be downloaded to your nav computer shortly.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 14, 'title', 'Yavin System: Inspect Doctor Shinss'' Yacht'),
('string/en/spacequest/inspect/naboo_imperial_tier3_2.stf', 15, 'title_d', 'Your questioning of Lt. Colonel Barlow has led you to believe that Doctor Shinss was involved in Colonel Hend''s traitorous activity. Inquisition command wants more proof against the doctor and you will need to inspect the doctor''s personal yacht for proof that he was involved.'),
