('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 6, 'quest_dock_d', 'Dock with the Rebel command vessel and transfer the reports to your vessel.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 7, 'quest_dock_t', 'Transfer the Encrypted Rebel Reports'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 8, 'quest_inspect_d', 'Disable the Rebel command vessel and inspect it for any information on the Rebel operations in the system.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 9, 'quest_inspect_t', 'Disable the Rebel Command Vessel'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 10, 'quest_location_d', 'The Rebel command vessel appears to still be in the Dathomir system. You will be supplied with a navigation waypoint to its most recent location.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 11, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 12, 'split_quest_alert', 'Nice work, pilot. Fly that information back to the Naboo system for immediate transfer to a shuttle.'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 14, 'title', 'Dathomir System: Inspect the Rebel Command Vessel'),
('string/en/spacequest/inspect/naboo_imperial_tier3_3_c.stf', 15, 'title_d', 'During the attacks on the crippled shuttle, the Rebel pilots where sending signals to what appears to be a command vessel. Hunt down that vessel and inspect it for any information that we can find useful.'),
