('string/en/spacequest/inspect/naboo_imperial_tier4_1_a.stf', 9, 'quest_inspect_t', 'Inspect the Crystal Smuggler'),
('string/en/spacequest/inspect/naboo_imperial_tier4_1_a.stf', 10, 'quest_location_d', 'The ship has just left Dathomir''s surface. Intercept it before it is able to leave the system. A navigation waypoint to its most recent location will be supplied to you.'),
