('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 5, 'quest_dock_d', 'If the craft you have inspected containes the cargo you need, use the default ''['' or '']'' keys to cycle through their components to the engine slot.  After disabling the craft, pull up close and use the /dock command to retreive the cargo.'),
('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 6, 'quest_dock_t', 'Docking'),
('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 7, 'quest_inspect_d', 'While you have the objective craft targeted, use /inspect command to determine their cargo.'),
('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 8, 'quest_inspect_t', 'Inspect Target'),
('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 9, 'quest_location_d', 'A location in the Naboo System'),
('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 10, 'quest_location_t', 'Naboo System'),
('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 11, 'split_quest_alert', '\\#pcontrast3 RSF Command: < \\#pcontrast1 We are decoding the information you took from that NDC craft now.  Travel to Lok Space, we need you to meet up with one of our fighters for a quick delivery. \\#pcontrast3 >'),
('string/en/spacequest/inspect/naboo_privateer_tier3_3a.stf', 12, 'split_quest_alert_fail', ''),
