('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 5, 'quest_dock_d', 'Dock with the spies disabled ship and transfer over the contents of his onboard computer.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 6, 'quest_dock_t', 'Dock and steal information.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 7, 'quest_inspect_d', 'The spy is piloting a civilian vessel, model YT-1300. It shouldn''t be a difficult target for you but it does have some weaponry so don''t relax. Disable the engines or the reactor of his ship.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 8, 'quest_inspect_t', 'The spies vessel.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 9, 'quest_location_d', 'The Imperial forces in the area are in disarray and shouldn''t pose much of a threat but you can never be too careful my friend.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 10, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 11, 'split_quest_alert', 'Brother Ezkiel: < Good work, pilot. Bring the information to one of our data freighters. >'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 13, 'title', 'Dantooine system: Catch the Imperial spy.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_1_c.stf', 14, 'title_d', 'The Imperial officer that tricked us is trying to escape, don''t let him. Hunt down his ship, disable its engine or reactor and steal any information he may have in his onboard computer.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 5, 'quest_dock_d', 'Dock with the disabled Blacklight pirate and transfer the location of their leader to your ship. Then return to base while we plan the attack.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 6, 'quest_dock_t', 'Dock and transfer data.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 7, 'quest_inspect_d', 'Try to find a Blacklight Squadron Leader and see if he has the location of their leader in his computer system. If he does, disable his engines or reactor and dock with him to transfer it.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 8, 'quest_inspect_t', 'Blacklight Squadron Leader.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 9, 'quest_location_d', 'This will take you inside Blacklight pirate territory so stay sharp and be prepared for a fight.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 10, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 11, 'split_quest_alert', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 13, 'title', 'Dantooine system: Inspect remaining Blacklight Pirates.'),
('string/en/spacequest/inspect/naboo_rebel_tier3_2_d.stf', 14, 'title_d', 'We''ve found the location of some more Blacklight pirate scum. Disable and inspect them, if you find the location of their leader, dock and transfer that data to your ship.'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 5, 'quest_dock_d', 'After having disabled and inspected your enemy, use the /dock command to procure your designated cargo.'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 6, 'quest_dock_t', 'Dock with the Disabled Black Sun Aggressor'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 7, 'quest_inspect_d', 'To inspect a target, you must disable the ship by targeting their reactors or engines (use the []''s to twitch between different components of your enemy''s ship). After having disabled your enemy, you must inspect it by using the "i" key.'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 8, 'quest_inspect_t', 'Inspect Black Sun Aggressors'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 9, 'quest_location_d', 'If in another system, travel to the Tatoo System by using your hyperspace map (by pressing "H") and clicking a Hyperspace point.'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 10, 'quest_location_t', 'Travel to the Tatoo System'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 11, 'split_quest_alert', '\\#pcontrast1 Mos Eisley Captain:\\#pcontrast3 < Pilot! Keep your systems alert. I can''t even identify what''s on the radar! >'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 13, 'title', 'Tatoo System: Black Sun Hunt'),
('string/en/spacequest/inspect/poi_tatooine_general_2.stf', 14, 'title_d', 'Kelen Wordkal suspects that the Black Sun Aggressors in the Ghost Tide Nebula may have information regarding the where abouts of the missing freighters. Whether or not the Black Suns are responsible, hunting and disabling several Black Sun Aggressors may very well get to the bottom of the situation.'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 5, 'quest_dock_d', 'To dock with a disabled ship, use the /dock command.'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 6, 'quest_dock_t', 'Docking with Valarians'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 7, 'quest_inspect_d', 'Somewhere around the waypoint you received from Garett, Valarians fly around like a moth to a flame. Disable them by targeting their engines or reactors (by using the []''s), and get close to inspect (by pressing ''i''). If you find what you''re looking for, you''ll need to /dock with the disabled ship and pull the information. Piece of Pyollian cake.'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 8, 'quest_inspect_t', 'Inspect Valarians'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 9, 'quest_location_d', 'Fly your ship to the Tatoo System for some Valarian-inspecting fun.'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 10, 'quest_location_t', 'Travel to the Tatoo System'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 11, 'split_quest_alert', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < Good work. Now, bring the information to me and we''ll analyze it. I knew they were onto us, somehow. I''m glad we''ll get to the bottom of this relatively soon. >'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 13, 'title', 'Tatoo System: Hunting the Valarians for Information'),
('string/en/spacequest/inspect/poi_tatooine_privateer_2_b.stf', 14, 'title_d', 'You''ve been given the task from Garett to hunt down the Valarians. He has a feeling the Valarians are onto them and must find out for sure by disabling and inspecting. Looks like you''re the person for the job. Dirty work at its best.'),
