('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect01_tier2_1.stf', 13, 'title', 'Naboo System: Inspect the Shifty Prince'),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect01_tier2_1.stf', 14, 'title_d', 'The Dantooine station wants you to commit a few acts of piracy in order to get them some more supplies. Your first task is to inspect a freighter called the Shifty Prince. It should be carrying some phasotron radium that the station is in need of.'),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 2, 'autorewardbody', ''),
