('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 5, 'quest_dock_d', 'Dock with the ship and transfer some of the brandy onto your vessel. Once completed return to the Dantooine station.'),
