('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 7, 'quest_inspect_d', 'Inspect the vessel and make sure that it still has the load of Corellian Brandy on it.'),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 8, 'quest_inspect_t', 'Inspect the Lord''s Mistress'),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 9, 'quest_location_d', 'The Lord''s Mistress is located in the Tatooine system.'),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 10, 'quest_location_t', 'Travel to the Tatooine System'),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 11, 'split_quest_alert', 'Return to the Dantooine system with the brandy.'),
