('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 13, 'title', 'Tatooine System: Inspect the Lord''s Mistress'),
('string/en/spacequest/inspect/stn_dantooine_owner_smuggler_inspect02_tier2_1.stf', 14, 'title_d', 'The Dantooine station owner also wants some Corellian Brandy for his private use. He discovered that the Lord''s Mistress is carrying some very fine brandy and wants you to get him some of it.'),
