('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 4, 'autorewardsubject', 'Intrigue'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 5, 'quest_dock_d', 'If the target has the cargo you are interested in, disable them by targeting either the engines or reactor with the default component cycle keys ''['' or '']'', once the ship is disabled you can pull up close and with the ship targeted use the /dock command to retrieve the cargo.'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 6, 'quest_dock_t', 'Dock'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 7, 'quest_inspect_d', 'Target the craft and use the default ''I'' key or /inspect to determine what cargo they possess.'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 8, 'quest_inspect_t', 'Inspection'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 9, 'quest_location_d', 'a Nebula in the Endor System just outside of normal sensor sweeps.'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 10, 'quest_location_t', 'Endor System'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 11, 'split_quest_alert', '\\#pcontrast3 Kilnstrider: < \\#pcontrast1 I suspected as much. Wait, we have a ship moving fast from that location.  Get into persuit, do not let them get away Captain. \\#pcontrast3 >'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 13, 'title', 'Endor System: Intrigue'),
('string/en/spacequest/inspect/stn_endor_irs_imp_tier3_2b.stf', 14, 'title_d', 'On command by Admiral Kilnstrider, inspect the suspicious ship near a distant nebula.'),
