('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 5, 'quest_dock_d', 'Use the dock command to transfer the lead to your vessel.'),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 6, 'quest_dock_t', 'Dock with the Debris Cult Communication Vessel'),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 7, 'quest_inspect_d', 'Once you have located the Debris Cult Communication Vessel, inspect its computers to see if there are any leads to the location of the hostage.'),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 8, 'quest_inspect_t', 'Inspect the Debris Cult Communication Vessel'),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 9, 'quest_location_d', 'The source of the broadcasts is coming from within the Yavin system. Always in the same location so the ship should not be hard to find.'),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 10, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 11, 'split_quest_alert', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 13, 'title', 'Yavin System: Inspect the Debris Cult Communication Vessel'),
('string/en/spacequest/inspect/stn_yavin4_company_all_opening_tier2_1.stf', 14, 'title_d', 'The Yavin Mining Company has been having problems with the crazed, debris cult demanding that they leave the area immediately. Despite the company telling the cult that they have nothing to do with the salvage operation underway in the Yavin system, the cult has continued its harrasment of company operations. Recently the cult has captured one of the mining company executives and is threatening to kill him unless their demands are met. The Yavin mining company wants you to find and resuce their executive. The debris cult has not covered their steps very well and the mining company has located the source of the cults demands. They think that inspecting that vessel will be a good start to finding their missing executive.'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 5, 'quest_dock_d', 'Tranfer the information to your ship and return it to the Yavin station.'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 6, 'quest_dock_t', 'Dock with the Vessel'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 7, 'quest_inspect_d', 'The Debris Cult''s ship probably has the location to the executive''s holding place.'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 8, 'quest_inspect_t', 'Inspect the Communication Vessel'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 9, 'quest_location_d', 'The communication vessel is in the Yavin system.'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 10, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 11, 'split_quest_alert', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 13, 'title', 'Space Yavin: Inspect the Debris Cult Communication Vessel'),
('string/en/spacequest/inspect/stn_yavin4_company_all_tier2_1.stf', 14, 'title_d', 'The missing executive of the Yavin 4 Mining Company is being held hostage by the Debris Cult. The location of the executive is unknown but the ship that has been sending in the demands is not making any attempt to hide. Inspect this vessel to see if you can locate the executive.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 6, 'quest_dock_d', 'Once you have located the Rebel orders, dock with the scout and transfer them to your vessel.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 7, 'quest_dock_t', 'Transfer the Rebel Orders'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 8, 'quest_inspect_d', 'Disable and inspect the scout to see if he might have any information as to why they are here and what they are planning.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 9, 'quest_inspect_t', 'Inspect the Rebel Advanced Recon Fighter'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 10, 'quest_location_d', 'The Rebel Recon fighter is still inside the system. He doesn''t seem to be aware that he has been spotted. A navigation waypoint to the scout''s location will be supplied to you.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 11, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 12, 'split_quest_alert', 'Alert! Enemy fighters have attacked an Imperial supply freighter. Freighter reports that they managed to escape but are badly damaged. Prepare to meet with the freighter, assist with repairs, and escort it through the system safely.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 14, 'title', 'Endor System: Inspect the Rebel Advanced Recon Fighter'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_1_b.stf', 15, 'title_d', 'Remain in the Endor systema nd inspect a Rebel Advanced Recon fighter that was noticed on scanners during your last mission. You need to find out why the Rebels are in this system and how they knew about the Imperial engineers'' shuttles.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 5, 'autorewardsubject', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 6, 'quest_dock_d', 'Once you have found some more information that command can use against the Rebels, dock with the scout and transfer that information to your vessel.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 7, 'quest_dock_t', 'Transfer the Rebel Orders'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 8, 'quest_inspect_d', 'Disable and inspect the scout for any more data that can be used by command.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 9, 'quest_inspect_t', 'Inspect the Rebel Advanced Recon Fighter'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 10, 'quest_location_d', 'Intelligence has located another Rebel Advanced Recon fighter in the Endor system. Travel to the supplied navigaiton waypoint in order to find the second scout.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 11, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 12, 'split_quest_alert', 'Alert! Enemy ships detected incoming at attack speeds. Take evasive action immediately. Destroy all incoming fighters.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 14, 'title', 'Endor System: Inspect Another Rebel Advanced Recon Fighter'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2.stf', 15, 'title_d', 'Travel to the Endor system and inspect another Rebel Advanced Recon fighter. Command needs more details as to the Rebel operation in the system. Intelligence has a lock on the location of another Rebel Advanced Recon fighter that seems to be a good target.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 6, 'quest_dock_d', 'Dock with the Rebel advanced recon freighter and transfer the reports to your vessel.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 7, 'quest_dock_t', 'Transfer the Rebel Reports'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 8, 'quest_inspect_d', 'Once the vessel is disabled, inspect it and find any information that command can use.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 9, 'quest_inspect_t', 'Inspect the Rebel Advanced Recon Freighter'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 10, 'quest_location_d', 'A navigation waypoint of the Rebel advanced recon freighter will be supplied to you. Intercept and disable that vessel.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 11, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 12, 'split_quest_alert', 'Transfer the data that you captured from the communications vessel to an Imperial Intelligence shuttle. Stand by for nav location information.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 14, 'title', 'Endor System: Inspect the Rebel Advanced Recon Freighter'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_2_b.stf', 15, 'title_d', 'It would seem that the Rebels didn''t expect you to survive their trap. There is one of their recon freighters nearby that was coordinating the attack. Chances are good that they have the information we are after on that craft. Disable and inspect that vessel.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 6, 'quest_dock_d', 'Dock with the Rebel command shuttle and transfer the stolen Imperial data to your vessel.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 7, 'quest_dock_t', 'Transfer the Stolen Imperial Data'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 8, 'quest_inspect_d', 'Disable and inspect the Rebel command shuttle for any information that Storm Squadron can use against the Rebels.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 9, 'quest_inspect_t', 'Inspect the Rebel Command Shuttle'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 10, 'quest_location_d', 'The location of the Rebel command shuttle has been found in the Endor system. A navigation waypoint to it will be supplied to you.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 11, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 12, 'split_quest_alert', 'Looks like that ship had all the information that was leaked to the Alliance. We no longer need the Rebel command ship intact. Stand by for coordinates to that ship.'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 14, 'title', 'Endor System: Inspect the Rebel Command Shuttle'),
('string/en/spacequest/inspect/tatooine_imperial_tier3_4_b.stf', 15, 'title_d', 'During the attack, command picked up a signal being sent from the fighters to a Rebel command shuttle. Intercept and inspect that vessel inside the Endor system.'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 6, 'quest_dock_d', 'Once you found the sector maps, dock with the disabled scout, and transfer those maps to your craft.'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 7, 'quest_dock_t', 'Transfer the Sector Maps and Battle Plans'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 8, 'quest_inspect_d', 'Intercept, disable, and inspect the Rebel A-wing scout''s databanks.'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 9, 'quest_inspect_t', 'Inspect the Rebel A-wing Scout'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 10, 'quest_location_d', 'The Rebel A-wing scout is still located inside the Endor system. A navigation waypoint to its most recent location will be supplied to you.'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 11, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 12, 'split_quest_alert', 'Get that information back to headquarters immediately.'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 14, 'title', 'Endor System: Inspect the Rebel A-wing Scout'),
('string/en/spacequest/inspect/tatooine_imperial_tier4_1_c.stf', 15, 'title_d', 'During the battle, a Rebel A-wing scout was noticed in the area. This scout might have valuable information about the Rebel goals in this system. Disable and inspect the scout''s databanks for any information on the Rebels intentions.'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 6, 'quest_dock_d', 'If the craft you have inspected containes the cargo you need, use the default ''['' or '']'' keys to cycle through their components to the engine slot.  After disabling the craft, pull up close and use the /dock command to retreive the cargo.'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 7, 'quest_dock_t', 'Docking'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 8, 'quest_inspect_d', 'While you have the objective craft targeted, use /inspect command to determine their cargo.'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 9, 'quest_inspect_t', 'Inspect Target'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 10, 'quest_location_d', 'An area of Dathomir with known Witchblood activity'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 11, 'quest_location_t', 'Dathomir System'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 12, 'split_quest_alert', '\\#pcontrast3 Beissa: < \\#pcontrast1 Excellent, now that you have the location of their Punisher rally get over there and find out where the burial ground is located. \\#pcontrast3 >'),
