('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 14, 'title', 'Dathomir System: Disable and Inspect Witchblood Clan Soldiers'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2.stf', 15, 'title_d', 'Disable the Witchblood Clan Soldier and inspect him for information about a Witchblood Punisher rally'),
