('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 6, 'quest_dock_d', 'To dock with a target, destroy their engines and use the /dock command'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 7, 'quest_dock_t', 'Dock Target'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 8, 'quest_inspect_d', 'You can /inspect a target to determine what if any cargo they posess'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 9, 'quest_inspect_t', 'Inspect Target'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 10, 'quest_location_d', 'The rally point for the Witchblood Clan Punishers'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 11, 'quest_location_t', 'Dathomir System'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 12, 'split_quest_alert', '\\#pcontrast3 Beissa: < \\#pcontrast1 Excellent, now get over to their burial ground.  They will be all over you there, but you must stay in the area while we carry out our operation. \\#pcontrast3 >'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 14, 'title', 'Dathomir Sytem: Inspect Witchblood Punishers for Burial Ground Location'),
('string/en/spacequest/inspect/tatooine_privateer_tier3_2_a.stf', 15, 'title_d', 'Disrupt a gathering of Witchblood Clan Punishers and inspect them for locations to the Witchblood Clan Burial Grounds'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 3, 'autorewardbody', ''),
