('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 6, 'quest_dock_d', 'If one of them is determiend to have the freight plans, use the /dock command after disabling them to retreive it'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 7, 'quest_dock_t', 'Dock Target'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 8, 'quest_inspect_d', 'Inspect the local Valarian Gunships for freight plans'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 9, 'quest_inspect_t', 'Valarian Gunship'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 10, 'quest_location_d', 'A area of Dantooine with ''Secret'' valarian activity.'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 11, 'quest_location_t', 'Dantooine System'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 12, 'split_quest_alert', '\\#pcontrast3 Nirame: < \\#pcontrast1 We are going to analyze this data.  Until then, how about putting those high prices blasters to use.  Get out to the Tatooine System, I''ll update you with target information from there. \\#pcontrast3 >'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 14, 'title', 'Dantooine System: Capture the Valarian Freight Plans'),
('string/en/spacequest/inspect/tatooine_privateer_tier4_3a.stf', 15, 'title_d', 'Disable and inspect a Valarian Gunship.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 5, 'quest_dock_d', 'Dock with the disabled traitor ship and disarm that thermal bomb.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 6, 'quest_dock_t', 'Dock and disarm the bomb.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 7, 'quest_inspect_d', 'If you find a ship with a bomb or other similar device, disable it at once and dock with it to secure the threat.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 8, 'quest_inspect_t', 'Imperial infiltrator.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 9, 'quest_location_d', 'The Dathomir system is always dangerous, even when you''re in a area controlled by us like this one so stay sharp.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 10, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 11, 'split_quest_alert', 'Rebel Command: < We are showing multiple TIE Interceptor ships incoming, the spy must have had a hidden guard. Prepare for battle! >'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 13, 'title', 'Dathomir system: Investigate suspicious Rebel craft.'),
('string/en/spacequest/inspect/tatooine_rebel_tier3_2.stf', 14, 'title_d', 'You are ordered to fly to the designated areas and inspect suspicious Rebel craft to try and catch Imperial terrorist infiltrators.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 6, 'quest_dock_d', 'It is the correct Imperial shuttle. Disable and dock with it so that you can hack and transfer the data to your ship, then hurry out of there.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 7, 'quest_dock_t', 'Correct shuttle, dock and transfer data.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 8, 'quest_inspect_d', 'Inspect the Imperial shuttle to make sure it got what we want. If it does and you haven''t disabled it already, do so, then dock and transfer the data over to your ship. To target specific components on a star ship, input the bracket commands ( ] or [ ) to your tactical computer. This will all be easier if you have destroyed it''s escort as docking under enemy fire is not recommended.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 9, 'quest_inspect_t', 'Inspect the Imperial ''Lambda'' shuttle.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 10, 'quest_location_d', 'The area of the Lok system that the stranded shuttle is in should be relatively safe from pirates. Unfortunately, the Empire is most likely sending a rescue team to the area so keep your eyes open for them. It is our hope that they have not already reached it but if they have, search the nearby area for the shuttle, destroy its escorts and disable it so you can get the data we need.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 11, 'quest_location_t', 'Lok system.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 12, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 13, 'split_quest_alert', 'Rebel Command: < Scan show multiple incoming TIE fighters! Get rid of them fast and then get out of there! >'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 14, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 15, 'title', 'Lok system: Steal Imperial information.'),
('string/en/spacequest/inspect/viopa_rebel_1.stf', 16, 'title_d', 'Nym pirates have found a stranded Imperial "Lambda" shuttle. You''re ordered to travel to it and hack its on board computer and see if there''s any useful information in it.'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/vortex_mission_1.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/vortex_mission_1.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/vortex_mission_1.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/vortex_mission_1.stf', 6, 'quest_dock_d', 'It''s a trap! There''s no scientist on board. Instead there''s an Imperial Inquisitor posing as the scientist. Your ships sensors have indicates that he''s swallowed a tracking device, probably hoping that you will take him back to the Vortex base.'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 7, 'quest_dock_t', 'Do not dock!'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 8, 'quest_inspect_d', 'Inspect the shuttle to make sure that it has the scientist onboard.'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 9, 'quest_inspect_t', 'Inspect the Imperial shuttle.'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 10, 'quest_location_d', 'You now have the coordinates of the ambush spot for the Imperial shuttle. The shuttle will pass through this area within a few minutes. If he''s not there already when you arrive, search the nearby area or wait for him to arrive then ambush him.'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 11, 'quest_location_t', 'Location of ambush.'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 12, 'quest_update', 'Brother Vrovel: < %TO >'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 13, 'split_quest_alert', 'It''s a trap! That''s not a scientist, it''s an Imperial Inquisitor!'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 14, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/vortex_mission_1.stf', 15, 'title', 'Lok system: Kidnap the Imperial scientist.'),
('string/en/spacequest/inspect/vortex_mission_1.stf', 16, 'title_d', 'Now that you have the location of the Imperial shuttle, your orders are to intercept it and disable it. You will then proceed to launch a space assault droid on to its hull so that it can take control of the ship.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/vortex_mission_4.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/vortex_mission_4.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/vortex_mission_4.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/vortex_mission_4.stf', 6, 'quest_dock_d', 'To transfer the shuttles travel routes and start location, dock with him as soon as he''s disabled and you have inspected him to make sure it''s the correct ship.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 7, 'quest_dock_t', 'Transfer the travel routes.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 8, 'quest_inspect_d', 'The officer is travelling in an Imperial shuttle class ''Lambda''. If it''s not at this location when you arrive there, search the nearby area and find a good spot to ambush the shuttle from when it arrives. Disable the ships engine or reactor and get the travel routes from the shuttles navigation computer. To target specific components on a star ship, input the bracket commands ( ] or [ ) to your tactical computer.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 9, 'quest_inspect_t', 'Imperial officer shuttle.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 10, 'quest_location_d', 'Quickly travel to the system of Dantooine to intercept the Imperial officer. When you arrive in the system, we will update your navigation computer with the correct coordinates for the interception. We don''t have a confirmation on when the officers shuttle will pass these coordinates but our recon ship monitoring the area says he hasn''t yet. When you get to the location wait until the shuttle appears and proceed with the ambush.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 11, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 12, 'split_quest_alert', ''),
('string/en/spacequest/inspect/vortex_mission_4.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/vortex_mission_4.stf', 14, 'title', 'Dantooine system: Steal location of Imperial Research Project.'),
('string/en/spacequest/inspect/vortex_mission_4.stf', 15, 'title_d', 'Your orders are to ambush the Imperial Officers shuttle and get the location of where the ship took off from by hacking its onboard computer.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 6, 'quest_dock_d', 'Dock and let your droid hack their computer for the patrol routes. If you haven''t destroyed its escort already, it''s probably a good idea to do so before docking.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 7, 'quest_dock_t', 'Steal the patrol route data.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 8, 'quest_inspect_d', 'Inspect the shuttle to make sure it has the routes of the Imperial patrols. If it does, disable it and dock to transfer the data. To target specific components on a star ship, input the bracket commands ( ] or [ ) to your tactical computer.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 9, 'quest_inspect_t', 'Inspect the shuttle.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 10, 'quest_location_d', 'With the heavy Imperial presence in the Yavin system that shuttle won''t stay immobile for long. If it''s not at the location when you get there the rescue team already got to it. If so, search the nearby area until you find it, destroy its escort, disable, inspect and dock with it if it''s the correct shuttle.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 11, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 12, 'split_quest_alert', ''),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 14, 'title', 'Yavin system: Steal patrol routes from Imperial spy shuttle.'),
('string/en/spacequest/inspect/yavin_rebel_14.stf', 15, 'title_d', 'An Imperial shuttle has malfunctioned in the Yavin system. The Alliance need to establish a new blockade run and by getting data from this spy shuttle that should be a lot easier. It won''t stay immobilized for long though as the Empire without a doubt has sent a rescue team.'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 6, 'quest_dock_d', 'The clever Empire has wired the whole shuttle with a self destruct system. They would rather have the database blown to pieces than fall in our hands. Ignore the shuttle, destroy the Imperial ambush and get out of there!'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 7, 'quest_dock_t', 'Error in the plan.'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 8, 'quest_inspect_d', 'Inspect the Imperial shuttle to make sure it has what we need. If it does, disable its engines or reactor if you haven''t already. To target specific components on a star ship, input the bracket commands ( ] or [ ) to your tactical computer.'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 9, 'quest_inspect_t', 'Make sure it''s the right shuttle.'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 10, 'quest_location_d', 'Always be careful in the Lok system. The system is infested with pirate activity and even though the Nym pirates don''t bother us there''s plenty of other pirate clans that will jump at the chance of destroying a lone fighter. When you get to the waypoint, search the nearby area for the shuttle as it may not have arrived at those coordinates yet.'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 11, 'quest_location_t', 'Lok system.'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 12, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 13, 'split_quest_alert', 'Rebel Command: < The shuttle is wired with a self destruct system. Detecting incoming Imperial Fighters, destroy them! >'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 14, 'split_quest_alert_fail', ''),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 15, 'title', 'Lok system: Intercept and steal data from Imperial recovery shuttle.'),
('string/en/spacequest/inspect/yavin_rebel_15.stf', 16, 'title_d', 'A part of the database on the Death Star space station has been found fairly intact in the debris floating around the moon of Yavin 4. Unfortunately the Empire has already recovered it and are shipping it through the Lok system right now.. Your job is to steal it from them.'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 6, 'quest_location_d', 'Travel to the Corellia system and follow the patrol navigation waypoints. As you reach one navigation waypoint, you will get a new waypoint to the next location on the patrol route.'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 7, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 8, 'quest_patrol1_d', 'Head to the first waypoint. This route will take you past the busiest shipping lane in Corellian space. The Corellia Star Lane serves thousands of ships heading to and from Corellia every day. It is highly doubtful that rebels will choose to stike at this location with the sheer number of ships around.'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 9, 'quest_patrol1_t', 'Travel to the First Stop'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 10, 'quest_patrol2_d', 'Head towards the second waypoint set to your Nav computer. You will fly by the shipping lanes serving primarly serving trade between the duel worlds and Corellia, the Solar Skyway. Rebels probably will not risk an attack in this sector due to the high level of local traffic. They probably will not risk an accident.'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 11, 'quest_patrol2_t', 'Travel to the Second Stop'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 12, 'quest_patrol3_d', 'This Nav waypoint will take you by the shadier routes that are commonly used by Corellia''s many smuggler pilots. The locals usually refer to it as the Invisible Highway since Corsec''s either don''t see or don''t choose to see what takes place there. '),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 13, 'quest_patrol3_t', 'Travel to the Third Stop'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 14, 'quest_patrol4_d', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 15, 'quest_patrol4_t', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 16, 'quest_patrol5_d', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 17, 'quest_patrol5_t', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 18, 'quest_patrol6_d', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 19, 'quest_patrol6_t', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 20, 'quest_patrol7_d', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 21, 'quest_patrol7_t', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 22, 'quest_patrol8_d', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 23, 'quest_patrol8_t', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 24, 'quest_patrol9_d', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 25, 'quest_patrol9_t', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 26, 'quest_patrol_d', 'When you reach a patrol waypoint you will receive a new one to your next location. Follow each of the patrol waypoints until you reach the end of your patrol.  This is the first of four special assignments given to you by Hakasha Sireen. When you complete this mission, return to Hakasha Sireen at the Imperial Base on Talus for your next assignment.  After you complete these four special assignments, Hakasha Sireen will train you in a new Imperial Pilot skill.'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 27, 'quest_patrol_t', 'Follow the Patrol Route'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 28, 'quest_target_d', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 29, 'quest_target_t', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 30, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 31, 'split_quest_alert', 'Incoming unidentified fighers with active weapon systems. Destroy all attacking craft.'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 33, 'title', 'Corellia System: Patrol the Corellia System'),
('string/en/spacequest/patrol/corellia_imperial_1.stf', 34, 'title_d', 'Run a patrol route in the Corellia system in order to bait a Rebel attack on your craft. Once you arrive in the Corellia system you will receive a navigation waypoint to the first stop on the patrol route. Travel to this waypoint. Once you arrive the navigation waypoint will update to the next stop on the patrol route. Continue following these navigation waypoints until you have completed the patrol. When you complete this mission, return to Hakasha Sireen at the Imperial Base on Talus for your next assignment.'),
