('string/en/spacequest/patrol/corellia_imperial_15.stf', 6, 'quest_location_d', 'Travel to the Corellia system and follow the patrol navigation waypoints. As you reach one navigation waypoint, you will get a new waypoint to the next location on the patrol route.'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 7, 'quest_location_t', 'Travel to the Corellian System'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 8, 'quest_patrol_d', 'When you reach a navigation waypoint you will receive a new one to the next location. Follow the patrol waypoints until you come to the end of your patrol.'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 9, 'quest_patrol_t', 'Follow the Patrol Route'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 10, 'quest_target_d', ''),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 11, 'quest_target_t', ''),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 12, 'split_quest_alert', 'Alert! Rebel craft detected in the area.'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 14, 'splitquestbody', 'Local space scanning craft have detected a group of Rebel X-wing in your vicinity.  Your orders are to destroy them completely.'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 15, 'splitquestfrom', 'Black Epsilon Command'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 16, 'splitquestsubject', 'Rebel Craft Detected'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 17, 'title', 'Corellia System: Patrol the Corellia System'),
('string/en/spacequest/patrol/corellia_imperial_15.stf', 18, 'title_d', 'Black Epsilon wants to keep it''s advantage in the region. In order to do that they need to make patrols of the region keeping a close watch out for Rebel activity. You are to make a patrol of Corellian space scanning for Rebel ships.'),
