('string/en/spacequest/patrol/corellia_imperial_tier4_1.stf', 12, 'split_quest_alert', 'Your patrol has revealed a Velocity ship with officer markings. Capture and inspect that ship for any information about the mercenaries plot.'),
('string/en/spacequest/patrol/corellia_imperial_tier4_1.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/corellia_imperial_tier4_1.stf', 14, 'title', 'Dantooine System: Patrol the Dantooine System'),
('string/en/spacequest/patrol/corellia_imperial_tier4_1.stf', 15, 'title_d', 'Insurgent has sent you out on a patrol to investigate the movements of the Velocity mercenary fighters in the region. If you are able to locate an officer you are to disable and inspect that officer''s computer database.'),
