('string/en/spacequest/patrol/corellia_rebel_1.stf', 30, 'split_quest_alert', 'Rebel Command: < We are picking up Imperial fighter ship signatures. Prepare to defend yourself pilot! >'),
('string/en/spacequest/patrol/corellia_rebel_1.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/corellia_rebel_1.stf', 32, 'title', 'Corellia system: Evaluate new transport route.'),
('string/en/spacequest/patrol/corellia_rebel_1.stf', 33, 'title_d', 'Evaluate new transport route. We''re trying to find a new safe route in the Corellia system and need your help scouting possible routes. When you complete this mission, return to Captain Kreezo in Tyrena for your next assignment.'),
('string/en/spacequest/patrol/corellia_rebel_3.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/patrol/corellia_rebel_3.stf', 2, 'autorewardbody', ''),
