('string/en/spacequest/patrol/corellia_rebel_3.stf', 5, 'quest_location_d', 'The Corellia system is fairly safe from Imperial contact but you can''t relax, the Empire is not non existant and pirates can be found anywhere in the galaxy.'),
('string/en/spacequest/patrol/corellia_rebel_3.stf', 6, 'quest_location_t', 'Corellia system.'),
('string/en/spacequest/patrol/corellia_rebel_3.stf', 7, 'quest_patrol1_d', 'Fly to this navigation point in earch of a lost refugee transport.'),
('string/en/spacequest/patrol/corellia_rebel_3.stf', 8, 'quest_patrol1_t', 'Search and Rescue: Alpha'),
('string/en/spacequest/patrol/corellia_rebel_3.stf', 9, 'quest_patrol2_d', 'Continue your search for a lost refugee transport at this nav point.'),
