('string/en/spacequest/patrol/naboo_imperial_3.stf', 26, 'quest_patrol_d', 'When you reach a navigation waypoint you will receive a new one to the next location. Follow the patrol waypoints until you come to the end of your patrol.'),
('string/en/spacequest/patrol/naboo_imperial_3.stf', 27, 'quest_patrol_t', 'Follow the Patrol Route'),
('string/en/spacequest/patrol/naboo_imperial_3.stf', 28, 'quest_target_d', ''),
('string/en/spacequest/patrol/naboo_imperial_3.stf', 29, 'quest_target_t', ''),
('string/en/spacequest/patrol/naboo_imperial_3.stf', 30, 'split_quest_alert', 'Stand by for arrival location of the E-62 transport freighter.'),
('string/en/spacequest/patrol/naboo_imperial_3.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/naboo_imperial_3.stf', 32, 'title', 'Naboo System: Meet the E-62 Transport Freighter'),
('string/en/spacequest/patrol/naboo_imperial_3.stf', 33, 'title_d', 'Travel the assigned security patrol route until you are contacted by the Imperial freighter carrying the E-62''s. Once you have made contact with the vessel escort it safely through the zone, paying close attention for Rebel activity. It is highly possible you will be attacked while escorting the vessel. When you complete this mission, return to Lt. Barn Sinkko in Kadaara for your next assignment.'),
