('string/en/spacequest/patrol/naboo_imperial_tier4_1.stf', 12, 'split_quest_alert', 'Alert! Unauthorized vessel suspected of smuggling attempting to leave system. Detain vessel and inspect its contents.'),
('string/en/spacequest/patrol/naboo_imperial_tier4_1.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/naboo_imperial_tier4_1.stf', 14, 'title', 'Dathomir System: Patrol the Dathomir System'),
('string/en/spacequest/patrol/naboo_imperial_tier4_1.stf', 15, 'title_d', 'The Inquisition has been alerted to higher levels of unauthorized activity in the Dathomir system. They want to find out what this activity is and who is behind it. You are to patrol the Dathomir system and keep your eyes open for any suspicious activity.'),
