('string/en/spacequest/patrol/naboo_rebel_tier3_2_b.stf', 26, 'quest_patrol_d', 'We will upload new patrol coordinates to your nav computer as you reach them. Proceed as planned.'),
('string/en/spacequest/patrol/naboo_rebel_tier3_2_b.stf', 27, 'quest_patrol_t', 'Patrol coordinates.'),
