('string/en/spacequest/patrol/naboo_rebel_tier3_4_a.stf', 29, 'split_quest_alert', 'Brother Ezkiel: < Blast it! Our systems are warning us that there are more enemies in the area. Keep a lookout and try to single out a target. We need it disabled, information is important to us at this stage. >'),
('string/en/spacequest/patrol/naboo_rebel_tier3_4_a.stf', 30, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/naboo_rebel_tier3_4_a.stf', 31, 'title', 'Dathomir system: Patrol for lone Imperial ships.'),
('string/en/spacequest/patrol/naboo_rebel_tier3_4_a.stf', 32, 'title_d', 'Try to find a ship of the Imperial Inquisition that is relatively alone. We will provide you with coordinates to search.'),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 5, 'quest_location_d', 'The freighter route is supposed to be secure but a lot talk for that the freighter crew was right and it''s been compromised so be prepared.'),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 6, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 7, 'quest_patrol_d', 'The Imperial space station will provide you with waypoints along the freighter route, follow them and keep your eyes on your radar.'),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 8, 'quest_patrol_t', 'Follow the waypoints.'),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 9, 'quest_target_d', ''),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 10, 'quest_target_t', ''),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 11, 'split_quest_alert', 'Imperial Space Station: < There! Rebel scout ships, get them! >'),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 13, 'title', 'Yavin system: Patrol the freighter route.'),
('string/en/spacequest/patrol/naboo_station_emperors_access_quest_3.stf', 14, 'title_d', 'The security commander of the Imperial space station in Yavin has asked you a favor. He wants you to confirm the freighter crews suspiciouns that the Rebels are planning to attack their freighter convoys. Travel out to the route and patrol it, to see if you can find any of the Rebel scum.'),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 5, 'quest_location_d', 'If in another system, travel to the Tatoo System by using your hyperspace map (by pressing "H") and clicking a Hyperspace point.'),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 6, 'quest_location_t', 'Tatoo System'),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 7, 'quest_patrol_d', 'Patrol the Ghost Tide Nebula and keep your systems alert for suspicious activity.'),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 8, 'quest_patrol_t', 'Patrol the Ghost Tide Nebula'),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 9, 'quest_target_d', ''),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 10, 'quest_target_t', ''),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 11, 'split_quest_alert', '\\#pcontrast1 Mos Eisley Captain:\\#pcontrast3 < Pilot! I''m detecting enemy vessels with armed weapon systems coming your way! >'),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 13, 'title', 'Tatoo System: Patrol the Ghost Tides'),
('string/en/spacequest/patrol/poi_tatooine_general_1.stf', 14, 'title_d', 'The Most Eisley Police Captain, Kelen Wordkal, personally overlooks the process for clearing freighters to their destinations. It is normal protocal for the freighters to report back to the captain when they have reached their destination. However, as of late, the freighters that have been cleared to venture through the Ghost Tides Nebula to the mining station beyond have never returned nor have they checked in with the captain. Kelen Wordkal fears the worst. It is your duty to unravel the mystery of the Ghost Tides Nebula Disappearances.'),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 5, 'quest_location_d', 'Fly to the Tatoo System for your mission.'),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 6, 'quest_location_t', 'Tatoo System'),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 7, 'quest_patrol_d', 'Fly your nifty ship to designated areas sent to you by Garett.'),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 8, 'quest_patrol_t', 'Patrol Valarian-Controlled Areas'),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 9, 'quest_target_d', ''),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 10, 'quest_target_t', ''),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 11, 'split_quest_alert', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < Watch your back, pilot! Valarians coming in hard and fast! >'),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 13, 'title', 'Tatoo System: Patrol Valarian-Controlled Areas'),
('string/en/spacequest/patrol/poi_tatooine_privateer_2.stf', 14, 'title_d', 'You''ve been given the task to patrol the Valarian-controlled areas surrounding Hutt Claims. Time for a little revenge! You rub your hands together evilly and cackle... at this rate, you probably look as scary as an Overkreetle. May want to work on your scariness rating.'),
