('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_2.stf', 9, 'quest_target_d', ''),
('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_2.stf', 10, 'quest_target_t', ''),
('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_2.stf', 11, 'split_quest_alert', 'Royal Security Force fighters detected. They must not be allowed to report in to your presence. Destroy them all.'),
('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_2.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_2.stf', 13, 'title', 'Naboo System: Travel the Assigned Route'),
('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_2.stf', 14, 'title_d', 'The Yavin 4 Mining Company has hired you to delivery a ''secret'' package to a contact of theirs in the Naboo system. You are to fly an assigned route so that the contact knows you are the ship he wants to meet with. Avoid any contact with security but if nessecary destroy any vessels that try to interfer.'),
