('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_4.stf', 11, 'split_quest_alert', 'Drop off location detected. Travel to the drop off point and wait for the arrival of the contact.'),
('string/en/spacequest/patrol/stn_yavin4_company_smuggler_tier2_4.stf', 12, 'split_quest_alert_fail', ''),
