('string/en/spacequest/patrol/tatooine_imperial_1.stf', 24, 'quest_patrol9_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 25, 'quest_patrol9_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 26, 'quest_patrol_d', 'When you reach a patrol waypoint you will receive a new one to your next location. Follow each of the patrol waypoints until you reach the end of your patrol.  This is the first of four special assignments given to you by Lt. Akal Colzet.  When you complete this mission, return to Lt. Akal Colzet in the Imperial Pilot''s Association Hall next to the Bestine Capital building for your next assignment.  After you complete these four special assignments, Lt. Akal Colzet will train you in a new Imperial Pilot skill.'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 27, 'quest_patrol_t', 'Follow the Patrol Route'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 28, 'quest_target_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 29, 'quest_target_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 30, 'split_quest_alert', 'Warning! Pirate fighters detected. Eliminate threat.'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 32, 'surprise_attack_alert', 'Pirate wing detected.  They are moving to attack commercial traffic!'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 33, 'surpriseattackbody', 'Sensors have located a wing of 4 pirate ships moving to attack commercial traffic.'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 34, 'surpriseattackfrom', 'Targeting Computer'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 35, 'surpriseattacksubject', 'Enemy Ships Detected'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 36, 'title', 'Tatooine System: Patrol the Tatooine System'),
('string/en/spacequest/patrol/tatooine_imperial_1.stf', 37, 'title_d', 'Run a patrol route in the Tatooine system in order to keep an eye out for pirate activity. Once you arrive in the Tatooine system, you will receive a navigation waypoint to the first stop on the patrol route. Travel to this waypoint. Once you arrive, the navigation waypoint will update to the next stop on the patrol route. Continue following these navigation waypoints until you have completed the patrol. When you complete this mission, return to Lt. Akal Colzet in the Imperial Pilot''s Association Hall next to the Bestine Capital building for your next assignment.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 6, 'quest_location_d', 'Travel to the Tatooine system and follow the patrol navigation waypoints. As you reach one navigation waypoint, you will get a new waypoint to the next location on the patrol route.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 7, 'quest_location_t', 'Travel to the Tatooine System'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 8, 'quest_patrol1_d', 'The first area of concern is the first quadrant of the jump zone. Pirates commonly attack ships just after they jump into a region before those ships have a chance to get any sort of defense prepared.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 9, 'quest_patrol1_t', 'Travel to First Nav Waypoint'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 10, 'quest_patrol2_d', 'Move to the second point in the patrol that will lead across areas that the Imperial freighters will jump into the zone at.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 11, 'quest_patrol2_t', 'Travel to the Second Nav Waypoint'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 12, 'quest_patrol3_d', 'The third stop on the patrol leads past what is considered dead space. Dead space is an area that no major vessels or patrol usually take place in. Pirate love to use these areas to stage their attacks on unsuspecting freighters.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 13, 'quest_patrol3_t', 'Travel to the Third Nav Waypoint'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 14, 'quest_patrol4_d', 'The fourth stop on the patrol will take you over to where the freighters will be staging after arrival. Generally pirates do not like to attack staging areas, to many ships in to tight of an area, but especially daring pirates have been known to make attempts on multiple ships at once in a staging area.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 15, 'quest_patrol4_t', 'Travel to the Fourth Nav Waypoint'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 16, 'quest_patrol5_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 17, 'quest_patrol5_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 18, 'quest_patrol6_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 19, 'quest_patrol6_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 20, 'quest_patrol7_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 21, 'quest_patrol7_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 22, 'quest_patrol8_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 23, 'quest_patrol8_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 24, 'quest_patrol9_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 25, 'quest_patrol9_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 26, 'quest_patrol_d', 'When you reach a navigation waypoint you will receive a new one to the next location. Follow the patrol waypoints until you come to the end of your patrol.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 27, 'quest_patrol_t', 'Follow the Patrol Route'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 28, 'quest_target_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 29, 'quest_target_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 30, 'split_quest_alert', 'Alert! Receiving distress signal from Imperial transport! The transport is on the run from Commerce Raiders. Stand by to escort transport through sector.'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 32, 'splitquestbody', 'Imperial Transport ZE43/t requesting immediate fire support.  We are under attack by pirate forces.  We require an escort to a safe location.  Waypoint to our current coordinates attached...'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 33, 'splitquestfrom', 'Imperial Transport ZE43/t'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 34, 'splitquestsubject', 'Requesting Assistance!'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 35, 'title', 'Tatooine System: Meet the Imperial Transport'),
('string/en/spacequest/patrol/tatooine_imperial_3.stf', 36, 'title_d', 'The Empire is expecting some very important shipments of cargo to be coming into the Tatooine system on it''s way to Bestine. These supplies are slated to go to the ground forces located in and around the Imperial capital of Tatooine and it is imperitive that they make it to their destination. You are to patrol the arrival and drop off locations of these ships shortly before they arrive to reduce any attempt by pirates to take these craft. When you complete this mission, return to Lt. Akal Colzet in the Imperial Pilot''s Association Hall next to the Bestine Capital building for your next assignment.'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 3, 'autorewardbody', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 4, 'autorewardfrom', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 5, 'autorewardsubject', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 6, 'quest_location_d', 'Remain in the Endor system and follow the patrol navigation waypoints. As you reach one navigation waypoint, you will get a new waypoint to the next location on the patrol route.'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 7, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 8, 'quest_patrol_d', 'When you reach a navigation waypoint you will receive a new one to the next location. Follow the patrol waypoints until you come to the end of your patrol.'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 9, 'quest_patrol_t', 'Follow the Patrol Route'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 10, 'quest_target_d', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 11, 'quest_target_t', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 12, 'split_quest_alert', 'Calling all Imperial pilots. 3rd TIE Wing has encountered heavy Rebel resistance. All available pilots are to proceed immediately to the following location.'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 14, 'title', 'Endor System: Patrol the Endor System'),
('string/en/spacequest/patrol/tatooine_imperial_tier3_2_d.stf', 15, 'title_d', 'Command wants you to patrol the area looking for Rebel activity while they inspect the data you recovered.'),
