('string/en/spacequest/patrol/tatooine_imperial_tier4_1.stf', 12, 'split_quest_alert', 'Alert! Enemy fighters detected. Incoming at attack speed.'),
('string/en/spacequest/patrol/tatooine_imperial_tier4_1.stf', 13, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_imperial_tier4_1.stf', 14, 'title', 'Endor System: Patrol the Endor System'),
('string/en/spacequest/patrol/tatooine_imperial_tier4_1.stf', 15, 'title_d', 'Storm Squadron has been charged with security of the Endor system and the Empire''s new top secret project. You are to fly patrol duty in the Endor system and keep a close watch out for any suspicious activity.'),
