('string/en/spacequest/patrol/tatooine_rebel_1.stf', 26, 'quest_patrol_d', 'When you reach a patrol waypoint you will receive a new one to your next location. Follow each of the patrol waypoints until you reach the end of your patrol.  This is the first of four special assignments given to you by Commander Da''la Socuna. When you complete this mission, return to Commander Da''la Socuna in the back room of the Mos Espa cantina for your next assignment.  After you complete these four special assignments, Commander Da''la Socuna will train you in a new Rebel Alliance Pilot skill.'),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 27, 'quest_patrol_t', 'Patrol navigation points along the Alliance supply route.'),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 28, 'quest_t', 'Patrol the Rebel supply route.'),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 29, 'quest_target_d', ''),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 30, 'quest_target_t', ''),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 31, 'split_quest_alert', 'Alliance HQ: < Warning, we''ve detected an Imperial Patrol closing in on your position! >'),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 33, 'title', 'Tatooine system: Patrol the Rebel supply route.'),
('string/en/spacequest/patrol/tatooine_rebel_1.stf', 34, 'title_d', 'Patrol the Rebel supply route in the Tatooine system. When you complete this mission, return to Commander Da''la Socuna in the back room of the Mos Espa cantina for your next assignment.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 5, 'quest_d', 'Patrol the Tatooine system in search of a suitable route for Alliance transports to follow. The previous route has been compromised and the Empire is now aware of the Alliance intentions here in Tatooine.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 6, 'quest_location_d', 'The Tatooine system doesn''t have a high presence of Imperial forces but plenty of pirates, bounty hunters and other less than friendly pilots so stay sharp out there.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 7, 'quest_location_t', 'Tatooine system.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 8, 'quest_patrol1_d', 'Patrol Tatooine space to lock down a new Alliance transport route.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 9, 'quest_patrol1_t', 'Alliance Transport Route Alpha'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 10, 'quest_patrol2_d', 'Continue your patrol for a new Alliance transport route.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 11, 'quest_patrol2_t', 'Alliance Transport Route Bravo'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 12, 'quest_patrol3_d', 'Continue your patrol for a new Alliance transport route.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 13, 'quest_patrol3_t', 'Alliance Transport Route Gamma'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 14, 'quest_patrol4_d', ''),
