('string/en/spacequest/patrol/tatooine_rebel_2.stf', 25, 'quest_patrol9_t', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 26, 'quest_patrol_d', 'Alliance HQ will update your navi-computer with waypoints. Fly to each waypoint and ensure the safety of the planned Alliance supply route.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 27, 'quest_patrol_t', 'Patrol the Alliance supply route in the Tatooine system to ensure its safety.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 28, 'quest_t', 'Scout a new Alliance transport route'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 29, 'quest_target_d', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 30, 'quest_target_t', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 31, 'split_quest_alert', 'Calling off sensor sweep immediately! We have a crippled transport you must escort right now...'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 33, 'surprise_attack_alert', 'Pirate wing detected.  They are moving to attack commercial traffic!'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 34, 'surpriseattackbody', 'Sensors have located a wing of 4 pirate ships moving to attack commercial traffic.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 35, 'surpriseattackfrom', 'Targeting Computer'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 36, 'surpriseattacksubject', 'Enemy Ships Detected'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 37, 'title', 'Tatooine system: Supply route security patrol.'),
('string/en/spacequest/patrol/tatooine_rebel_2.stf', 38, 'title_d', 'Patrol by following the waypoints as they appear on your screen, keep your eye out for any enemy activity. When you complete this mission, return to Commander Da''la Socuna in back room of the Mos Espa cantina for your next assignment.'),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 5, 'quest_location_d', 'The Endor system is high risk, there''s no doubt about that. This mission will be taking you dangerously close to the more Imperial dominated areas so be extremely careful pilot.'),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 6, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 7, 'quest_patrol_d', 'We will update your nav computer with new waypoints of suspect areas where the Empire may have deployed some of these new ships.'),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 8, 'quest_patrol_t', 'Scan route.'),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 9, 'quest_target_d', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 10, 'quest_target_t', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 11, 'split_quest_alert', 'Rebel Command: < You have been spotted! TIE Fighters are moving in your direction. Take them out quickly! >'),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 13, 'title', 'Endor system: Scan a region of the Endor system.'),
('string/en/spacequest/patrol/tatooine_rebel_tier3_4_a.stf', 14, 'title_d', 'In order to find out what the Empire is doing in such large force here, we need some more scan data. We''ve heard rumors that they are testing some new ship type and we hope that you can find us some evidence of that.'),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 1, 'assigned_delayed', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 2, 'autorewardbody', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 3, 'autorewardfrom', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 4, 'autorewardsubject', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 5, 'quest_location_d', 'There couldn''t be a worse place to be on the run. Keep a close eye on your sensors. If you see any hostile blips, try to take a route around them. Move quickly though, the Empire is on your tail!'),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 6, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 7, 'quest_patrol_d', 'We will update your nav computer with the waypoints of the pre-planned escape route. Follow them but not to the point where you run in to more hostile forces. If you have to circle around something, do so, just do it quickly.'),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 8, 'quest_patrol_t', 'Pre-planned escape route.'),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 9, 'quest_target_d', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 10, 'quest_target_t', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 11, 'split_quest_alert', 'General Ufwol: < Imperial Interceptors close by! Defend yourself! >'),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 12, 'split_quest_alert_fail', ''),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 13, 'title', 'Dathomir system: Escape the Empires counter attack.'),
('string/en/spacequest/patrol/tatooine_rebel_tier4_1_b.stf', 14, 'title_d', 'That didn''t go as planned pilot; let''s hope that your escape will! We have a pre planned escape route for you, follow it but move quickly!'),
('string/en/spacequest/patrol/tat_priv_quest_trans.stf', 1, 'assigned_delayed', 'Find the Rendezvous Point.'),
