('string/en/spacequest/recovery/corellia_imperial_16.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 2, 'abort', 'Understood, aborting mission.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 3, 'angry_disable', 'What are you doing? We need those to fly!'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 4, 'arrival_phase_1', 'The freighter will arrive momentarily, destroy the escort, and disable the Torton Runner''s engines.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 5, 'arrival_phase_2', 'Target sighted, execute attack. Once you have the freighter targeted use the '']'' key to cycle through it''s subsystems. Get the engine targeted and fire on the ship until it reaches 0% in order to disable the freighter.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Incoming enemy fighters.>'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 12, 'capture_complete', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <The Torton Runner is ours. Escort it to a safe jump point.>'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 13, 'capture_phase_1', 'You will never capture the Torton Runner, Imperial scum.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 14, 'capture_phase_2', 'Ok, fine...so you captured the Torton Runner. What are you planning on doing to us?'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 15, 'capture_started', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Uploading system virus \\#pcontrast3 >'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 16, 'complete', 'Operation is complete, ship is underway to its new destination.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 17, 'escort_remaining', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 %DI fighters in operation, destroy them quickly \\#pcontrast3 >'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 18, 'escort_wiped_out', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Escorting craft have all been destroyed, proceed with primary objective \\#pcontrast3 >'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 19, 'failed_destroy', 'The freighter was destroyed, you have failed your mission.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 20, 'failed_escape', 'The freighter has escaped, you have failed in you mission.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 21, 'panic_1', 'Yes, my brothers. Don''t let me fall into Imperial hands.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 22, 'panic_2', 'I am at the mercy of the Empire. Destroy me!'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 23, 'panic_3', 'My brothers, you must destroy me before I am in the hands of the Empire.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 24, 'panic_4', 'It is time for you to be destroyed, Imperial scum.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 25, 'panic_5', 'My brothers have come to destroy you.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 26, 'quest_disable_d', 'Once you have intercepted the Torton Runner, you will need to disable it in order to begin the capture process. Use the ''['' or '']'' key to target the Torton Runner''s subsystems. Cycle through them until you have its engines targeted. Attack the freighter until its engines are at 0%.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 27, 'quest_disable_t', 'Disable the Tortun Runner'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 28, 'quest_escort_d', 'Once the Torton Runner is captured, you will need to escort it through the Corellia system. Follow and protect the Torton Runner until it reaches its destination. The Hidden Daggers will probably send fighters out to attempt to destroy your prize. You will need to keep the Torton Runner safe from them.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 29, 'quest_escort_t', 'Escort the Torton Runner'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 30, 'quest_location_d', 'Travel to the Corellia system and capture the Torton Runner. Once you enter the system, wait until Imperial command sends you a navigation waypoint to the freighter''s most recent location. As the Torton Runner moves through the system this navigation waypoint will update to its most recent location. Intercept the Torton Runner before it reaches the end of its path or the vessel will jump out of the system.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 31, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 32, 'quest_recover_d', 'Once the Torton Runner is disabled you can begin the capture process. Move in close to the Torton Runner and wait for the capture process to begin. It might take a couple minutes for the process to begin so you will need to stay close to the vessel while this is happening. Wait until the capture process is completed before you move away from the Torton Runner. You will be vulnerable at this point so it might be a good idea to destroy any escort vessels that are with the ship before attempting to capture it.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 33, 'quest_recover_t', 'Capture the Torton Runner'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 34, 'quest_update', ' \\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 35, 'recovery_success', 'The freighter is secured, operation successful.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 38, 'target_disabled', 'The freighter has been disabled, move close in order to upload the virus. In order to capture it move in close to the vessel and stay stationary by it. The capture process will begin a few moment after you have done this.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 39, 'taunt_1', 'That is our ship you Imperial dog.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 40, 'taunt_2', 'Flee now and you will not feel our anger.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 41, 'taunt_3', 'Your Emperor cannot help you now.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 42, 'taunt_4', 'We will get revenge and you will never see us coming.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 43, 'taunt_5', 'I thought Imperial pilots had some measure of skill, I guess I was wrong.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 44, 'thanks_1', 'You are indeed skilled but it will not help you, more will come.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 45, 'thanks_2', 'You may have won this battle but there will be more.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 46, 'thanks_3', 'You may have captured me but that will not stop the others.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 47, 'thanks_4', 'Imperial dog! You will come to an unfortunate end.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 48, 'thanks_5', 'Imperial dog! You will come to an unfortunate end.'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 49, 'title', 'Corellia System: Capture the Torton Runner'),
('string/en/spacequest/recovery/corellia_imperial_16.stf', 50, 'title_d', 'Travel to the Corellia system and capture the Torton Runner. Once you arrive in the Corellia system, wait until Imperial command can get you the location of the target freighter. Once they have a lock, you will receive a navigation waypoint to its current location. This navigation waypoint will update as the Tortun Runner moves through the system. Follow these navigation waypoints until you intercept the freighter. Once you have intercepted the freighter, disable it by targeting the vessel''s subsystems. Use the ''['' or '']'' to target the Torton Runner''s engines and then attack the ship until its engines are at 0%. Now move in close to the freighter and wait for the capture process to begin. This process may take a couple of minutes so you will need to stay near the freighter until it begins. Be careful because you will be vunlerable while waiting for the capture process to complete. Once the vessel is captured you will need to escort it to safety. Follow the Torton Runner until it reaches its destination. Keep an eye out for enemy fighters who might attempt to retake the vessel.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 1, 'abort', 'Flee like the coward you are.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 3, 'arrival_phase_1', 'Target is approaching, stand by'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 4, 'arrival_phase_2', 'Target has arrived at pre determined point, proceed with capture.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 6, 'attack_notify', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 7, 'attack_stopped', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1a.stf', 10, 'autorewardsubject', ''),
