('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 2, 'abort', 'Glad to see that you came to your senses.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 3, 'angry_disable', 'Blast it! You knocked my engines offline.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 4, 'arrival_phase_1', 'Scanning system for known locations of Rebel officers. Prepare for interception once we have navigation waypoint.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 5, 'arrival_phase_2', 'Nav location to a Rebel officer sent to your computer. Intercept and capture that officer.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 12, 'capture_complete', 'Autopilot of captured vessel reprogrammed. Escort it to a safe recovery location.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 13, 'capture_phase_1', 'You can question me all you want! I will never talk!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 14, 'capture_phase_2', 'My ship is yours but you will never get what you want from me.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 15, 'capture_started', 'Beginning reprogramming of autopilot. Stand by for further instructions.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 16, 'complete', 'Rebel officer is in the hands of the Inquisiton. We will confirm the information in the recovered data shortly.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter escort eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 19, 'failed_destroy', 'We needed that officer to confirm what was in those rebel reports. Without him the whole operation is a bust. Report back to your surperior immediately.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 20, 'failed_escape', 'We needed that officer to confirm what was in those rebel reports. Without him the whole operation is a bust. Report back to your surperior immediately.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 21, 'panic_1', 'They think that I am with you! They will destroy me too.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 22, 'panic_2', 'What! Wait! Why are they attacking me too.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 23, 'panic_3', 'They would destroy me rather then let me fall into enemy hands?'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 24, 'panic_4', 'What! Wait! Why are they attacking me too.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 25, 'panic_5', 'They would destroy me rather then let me fall into enemy hands?'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 26, 'quest_disable_d', 'There is a Y-wing leading a flight of X-wings and Y-wings. Disable and capture that ship.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 27, 'quest_disable_t', 'Disable the Rebel Y-wing'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 28, 'quest_escort_d', 'Follow the Y-wing and protect it on its way back to Imperial controlled space.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 29, 'quest_escort_t', 'Escort the Rebel Y-wing'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 30, 'quest_location_d', 'Remain in the Yavin system and capture the Rebel Y-wing pilot. It is important that the pilot comes from the Yavin system since they will be the best source of information.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 31, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 32, 'quest_recover_d', 'Once the vessel is disabled, move in close and wait for the capture process to begin. You will probably want to destroy the escort fighters before doing this to avoid being attacked while the capture is happening.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 33, 'quest_recover_t', 'Capture the Rebel Y-wing'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 34, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 35, 'recovery_success', 'The rebel scum is in our hands. It will not be long before he is begging to tell us all he knows. Come back home, pilot.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 38, 'target_disabled', 'Target''s engines are offline. Move in close and wait for the capture process to begin.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 39, 'taunt_1', 'Die, Imperial dog!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 40, 'taunt_2', 'Long live the rebellion.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 41, 'taunt_3', 'We shall overcome.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 42, 'taunt_4', 'Imperial scum like you shouldn''t be allowed to live.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 43, 'taunt_5', 'Prepare for your own demise.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 44, 'thanks_1', 'Bleh, you killed them all.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 45, 'thanks_2', 'Better them then us I suppose.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 46, 'thanks_3', 'You will rue the day you messed with the rebellion.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 47, 'thanks_4', 'Bleh, you killed them all.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 48, 'thanks_5', 'Bleh, you killed them all.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 49, 'title', 'Yavin System: Capture a Rebel Y-wing'),
('string/en/spacequest/recovery/corellia_imperial_tier3_1_c.stf', 50, 'title_d', 'Now that command has the Joint Operations Plan they will need a live body to question so they can compare the two. This will enable the Empire to determine what is real and what is false in the plan. Capture a Rebel pilot so he can be questioned. Fortunately the location of a Rebel Y-wing pilot was discovered while you were delivering the Joint Operations Plan.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 2, 'abort', 'Wait! You can''t leave us out here without an escort. Jabba will kill us for just being caught.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 3, 'angry_disable', 'Jabba paid good money for those engines. He isn''t going to be happy with either you or me.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 4, 'arrival_phase_1', 'We have a target Hutt ship. Getting lock now. Stand by to capture that craft.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 5, 'arrival_phase_2', 'Location to the Hutt smuggling ship sent to your nav computer. Capture and escort that craft for the Empire.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 8, 'attack_stopped', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 12, 'capture_complete', 'Smuggler has the coordinates they are going to fly to. Escort the ship safely through the sector.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 13, 'capture_phase_1', 'What do you want? I thought we had an understanding.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 14, 'capture_phase_2', 'Fine, fine. I will head to your coordinates. Just don''t blow me up.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 15, 'capture_started', 'Sending surrender ultimatium to smuggler.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 16, 'complete', 'Hutt smuggler safely in Imperial hands.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters destroyed.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 19, 'failed_destroy', 'It should have been a simple operation. You recover a hutt ship so we can use it against Nym''s forces. Report back into your superior.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 20, 'failed_escape', 'It should have been a simple operation. You recover a hutt ship so we can use it against Nym''s forces. Report back into your superior.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 21, 'panic_1', 'We are in big trouble.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 22, 'panic_2', 'Man, am I going to get it.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 23, 'panic_3', 'I can tell Jabba is not pleased.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 24, 'panic_4', 'I don''t think they liked you capturing me.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 25, 'panic_5', 'So, how does it feel to be on Jabba''s most wanted list?'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 26, 'quest_disable_d', 'Disable the Hutt debris smuggler which is a perfect ship to be outfitted with the jammer. It is being escorted by several fighters so these might need to be destroyed before trying to capture the vessel.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 27, 'quest_disable_t', 'Disable the Hutt Debris Smuggler'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 28, 'quest_escort_d', 'Follow the Hutt smuggler''s vessel back to Imperial space.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 29, 'quest_escort_t', 'Escort the Hutt Debris Smuggler'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 30, 'quest_location_d', 'Intelligence has located a perfect Hutt vessel to capture. Once you have entered the Yavin system you will receive a navigation waypoint of the Hutt debris smuggler.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 31, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 32, 'quest_recover_d', 'Once the vessel has been disabled, move in close, and begin the capture process.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 33, 'quest_recover_t', 'Capture the Hutt Debris Smuggler'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 34, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 35, 'recovery_success', 'Smuggler ship is in our hands. We will begin retrofitting it to suit our needs. Nice work, pilot.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 36, 'split_quest_alert', 'Prepare to start phase two of our operation. The Hutts and Nyms have made an agreement not to mess with each others territory. Head into Nym controlled space and start broadcasting on Hutt frequency. Nym''s men should come swarming to protect their area.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 38, 'target_disabled', 'Target''s engines are offline. Move in close and wait for the capture process to begin.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 39, 'taunt_1', 'Steal Hutt property will you? I thought even Imperial knew better then that.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 40, 'taunt_2', 'You made a huge mistake, Imperial dog.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 41, 'taunt_3', 'So you decided to break our agreement did you?'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 42, 'taunt_4', 'Not a wise move to anger Jabba.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 43, 'taunt_5', 'Time for us to collect your hide.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 44, 'thanks_1', 'I don''t know who is worse. You or them!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 45, 'thanks_2', 'I don''t know who is worse. You or them!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 46, 'thanks_3', 'I don''t know who is worse. You or them!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 47, 'thanks_4', 'I don''t know who is worse. You or them!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 48, 'thanks_5', 'I don''t know who is worse. You or them!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 49, 'title', 'Yavin System: Capture the Hutt Debris Smuggler'),
('string/en/spacequest/recovery/corellia_imperial_tier3_2.stf', 50, 'title_d', 'Black Epsilon has come up with a plan to cause Nym to break off his assistance of the Rebellion in the Yavin system. First old wounds between the Hutts and Nym must be opened up in order to cause the two sides to start fighting. You are to capture a Hutt vessel, which the Empire will retrofit with a minor signature jammer, and then use it to attack Nym forces. This should cause Nym to retaliate and, therefore, starting a fight between the two pirate factions.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_3d.stf', 1, 'abort', 'You have failed due to aborting the quest.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_3d.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_3d.stf', 3, 'arrival_phase_1', 'The craft will be here shortly');
