('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 2, 'abort', 'That right! Run like the Imperial coward you are.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 3, 'angry_disable', 'You think that you are so smart, crippling me like that. One day I hope to return the favor.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 4, 'arrival_phase_1', 'Scanning system for target of opportunity that we can capture. Stand by.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 5, 'arrival_phase_2', 'We have a lock on one of Nym''s transport vessels that is a likely canidate. Capture and bring it back to a safe jump point. We will pick it up on our end.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters destroyed.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 12, 'capture_complete', 'Transport has surrendered. Prepare to escort it to a safe jump location.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 13, 'capture_phase_1', 'You have made a big mistake messing with Nym in his own system of power.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 14, 'capture_phase_2', 'Listen, you may have gotten me and I will follow without anymore fight but you will regret this.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 15, 'capture_started', 'Sending terms of surrender to the transport.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 16, 'complete', 'Transport is safely in Imperial hands.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 19, 'failed_destroy', 'We wanted that ship in one piece. We will have to wait for another day to try again. Report back in with your superior.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 20, 'failed_escape', 'You let that ship get away? Now Nym will be alerted to our presence. Report your failure to your superior.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 21, 'panic_1', 'You know they will kill me rather then let me be captured.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 22, 'panic_2', 'Oh, great...now you did it!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 23, 'panic_3', 'Oh, well. It has been a nice life.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 24, 'panic_4', 'Maybe they will make it quick and I won''t feel anything.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 25, 'panic_5', 'I have a wife and two kids! Thanks for getting me killed, Imperial dog.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 26, 'quest_disable_d', 'Disable the smuggler''s vessel so we can capture it, search its flight computer, and question its pilot.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 27, 'quest_disable_t', 'Disable the Nym Smuggler Transport'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 28, 'quest_escort_d', 'Once the ship is under our command, escort it safely into Imperial hands.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 29, 'quest_escort_t', 'Escort the Nym Smuggler Transport'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 30, 'quest_location_d', 'This operation is going to take place in Nym''s backyard. We have a lock on one of his smuggler vessels in the area. Capture this vessel before it can leave the system.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 31, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 32, 'quest_recover_d', 'Once disabled, move in close to begin the capture process.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 33, 'quest_recover_t', 'Capture the Nym Smuggler Transport'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 34, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 35, 'recovery_success', 'Nice work, pilot. We have the ship under our control. Our technicians are already sifting through it''s logs.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 36, 'split_quest_alert', 'The transports logs indicate a location of a patrol ship that Nym has running checkpoints around the zone. Your job is to destroy that vessel.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 38, 'target_disabled', 'The transports engines are offline. Move in close and wait for the terms of surrender to be issued.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 39, 'taunt_1', 'You didn''t think that Nym would just let you walk away with his property, did you?'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 40, 'taunt_2', 'The Empire has no business in Lok! Get out of here before I do something about it.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 41, 'taunt_3', 'You are making a huge mistake. Nym isn''t going to stand for this!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 42, 'taunt_4', 'Ok, that''s it! The kid gloves are coming off.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 43, 'taunt_5', 'Stealing from Nym! You are mad!'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 44, 'thanks_1', 'There will be more.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 45, 'thanks_2', 'So you beat a few of Nym''s men. You still are not going to make it all the way.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 46, 'thanks_3', 'Hey! I am not dead. That makes me happy. But I am still captured. That makes me sad.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 47, 'thanks_4', 'It is only a matter of time before they do take you out.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 48, 'thanks_5', 'Blast it! I was really looking forward to watching you die.'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 49, 'title', 'Lok System: Capture the Nym Smuggler Transport'),
('string/en/spacequest/recovery/corellia_imperial_tier3_4.stf', 50, 'title_d', 'Now that the alliance between the Rebels and Nym has been broken, it is time to punish Nym for crossing the Empire. Black Espilon will strike close to his home in the Lok system. Our first goal is to capture one of Nym''s smugglers in the region in order to get information about his other vessels locations.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 2, 'abort', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 3, 'angry_disable', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 4, 'arrival_phase_1', 'Getting a lock on the drifting ship now. Stand by for coordinates.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 5, 'arrival_phase_2', 'We have sent the vessel''s location to your nav computer. It appears to be on autopilot. Disable the vessel''s engines and reset the autopilot to return to Imperial space.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters detected.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 12, 'capture_complete', 'Autopilot reset. Escort vessel back into Imperial space.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 13, 'capture_phase_1', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 14, 'capture_phase_2', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 15, 'capture_started', 'Beginning reprogramming of autopilot program. Stand by.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 16, 'complete', 'Shuttle is on its way back to Imperial controlled space.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 17, 'escort_remaining', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 18, 'escort_wiped_out', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <Escorts eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 19, 'failed_destroy', 'We needed that shuttle to search it for clues. You incompentance cost us the best lead that we had. Report back to your commander immediately.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 20, 'failed_escape', 'You lost a shuttle that was on auto pilot? That sort of bumbling is the kind that gets men demoted. Report to your superior.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 21, 'panic_1', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 22, 'panic_2', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 23, 'panic_3', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 24, 'panic_4', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 25, 'panic_5', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 26, 'quest_disable_d', 'Once you intercept the freighter, disable it so the autopilot can be reprogrammed.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 27, 'quest_disable_t', 'Disable the Civilian Freighter'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 28, 'quest_escort_d', 'Follow the freighter until it reaches it''s destination. Be on the look out for enemy fighters who might not want this ship recovered.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 29, 'quest_escort_t', 'Escort the Civilian Freighter'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 30, 'quest_location_d', 'The ship is adrift in the Dantooine system. Intercept the vessel before it can drift out of the system.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 31, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 32, 'quest_recover_d', 'Move in close to the vessel and wait for the capture process to begin.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 33, 'quest_recover_t', 'Capture the Civilian Freighter'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 34, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 35, 'recovery_success', 'You have served well. The vessel will be investigated and perhaps we can gain a clue as to why it was here.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 36, 'split_quest_alert', 'Now that we have the shuttle lets see what else those mercenaries can tell us. Return to mercenary space, disable, and inspect another mercenary officer.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 38, 'target_disabled', 'The engines on the shuttle have shut down. Move in close to the freighter and reprogram it''s autopilot.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 39, 'taunt_1', 'That ship belongs to us! We stole it from the Empire fair and square.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 40, 'taunt_2', 'You might as well give us back that shuttle, since you dont have a choice anyways.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 41, 'taunt_3', 'I will not only take the shuttle but I will also destroy you.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 42, 'taunt_4', 'Your such a waste of good laser beams.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 43, 'taunt_5', 'You really should have stayed at home.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 44, 'thanks_1', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 45, 'thanks_2', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 46, 'thanks_3', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 47, 'thanks_4', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 48, 'thanks_5', '*static*'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 49, 'title', 'Dantooine System: Capture the Civilian Freighter'),
('string/en/spacequest/recovery/corellia_imperial_tier4_2.stf', 50, 'title_d', 'Insurgent has somehow discovered the location of an abandoned ship drifting along the outer rim of the system. He wants you to intercept and bring this vessel back so it can be examined. He believes that it might have some significance with his investigation.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 2, 'abort', 'Yeah, good plan there. You don''t want to mess with our masters.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 3, 'angry_disable', 'I will not be offline for very long! I know I can get this thing working again.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 4, 'arrival_phase_1', 'Tracking communications ship. Stand by for nav coordinates.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 5, 'arrival_phase_2', 'Location updated in your nav computer. It would appear that the communications ship is attempting to flee. Track it down and capture it.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 12, 'capture_complete', 'Autopilot reprogrammed. Returning vessel to Imperial space.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 13, 'capture_phase_1', 'You really don''t know what is going on do you? Our masters are more powerful then one such as yourself can ever understand.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 14, 'capture_phase_2', 'You might take us but our masters already are aware of what you have done. You should be be prepared to feel the retribution of a jedi.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 15, 'capture_started', 'Reprogramming vessel''s autopilot. Stand by.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 16, 'complete', 'Successfully recovered enemy vessel.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 19, 'failed_destroy', 'We needed that vessel in order to help us find the other two cohorts of Nej''a. You failed the Emperor and the Empire. Report to your superior.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 20, 'failed_escape', 'Your blundering incompetence has let that ship escape. Make a full report to your superior.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 21, 'panic_1', 'We accept death with dignity.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 22, 'panic_2', 'For Coynite. For glory.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 23, 'panic_3', 'Do not let me be dishonored by being captured, my brothers.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 24, 'panic_4', 'We accept death with dignity.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 25, 'panic_5', 'Do not let me be dishonored by being captured, my brothers.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 26, 'quest_disable_d', 'Intercept and disable the Velocity smuggler in order to capture it.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 27, 'quest_disable_t', 'Disable the Velocity Smuggler'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 28, 'quest_escort_d', 'Escort the smuggler to a safe location for a jump back into Imperial controlled space. Be on the look out for enemy craft who will probably attempt to recapture this ship.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 29, 'quest_escort_t', 'Escort the Velocity Smuggler'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 30, 'quest_location_d', 'The Velocity Smuggler is located inside the Dathomir system. Intercept and capture that vessel before it can escape the system.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 31, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 32, 'quest_recover_d', 'Move in close and wait for the capture process to begin.'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 33, 'quest_recover_t', 'Capture the Velocity Smuggler'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 34, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/corellia_imperial_tier4_4_a.stf', 35, 'recovery_success', 'We will begin our scans of the vessel to see if we can discover any lead on the location of the other two. Stand by for further instructions.'),
