('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 38, 'taunt_1', 'We have been sanctioned to terminate you all Rebels.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 39, 'taunt_2', 'Terminate the escort first men.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 40, 'taunt_3', 'We will not let you leave here with that man, even if it means he doesn''t leave either!'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 41, 'taunt_4', 'End of the line Rebel fools!'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 42, 'taunt_5', 'I will destroy you, foolish Rebels!'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 43, 'thanks_1', 'Enemy fighter wing terminated.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 44, 'thanks_2', 'No more bogeys within scan range.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 45, 'thanks_3', 'TIE Fighters eliminated, move on.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 46, 'thanks_4', 'Excellent, proceed.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 47, 'thanks_5', 'That was the last of that fighter wing, proceed as planned.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 48, 'title', 'Dantooine system: Kidnap Imperial technician.'),
('string/en/spacequest/recovery/corellia_rebel_tier4_4.stf', 49, 'title_d', 'We are about to kidnap one of the technicians building the new Imperial space station in the Lok system. The Alliance have managed to place a commando team on board his shuttle. You need to take out the shuttle escort and disable the ship so that they can take control of it.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 1, 'abort', 'What? You''re just going to leave me out here like so much flotsam? Grrr... you''ll pay for this.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 3, 'arrival_phase_1', 'Plotting projected path of Cloak officer. Stand by for coordinates.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 4, 'arrival_phase_2', 'Target acquired. Disable the "Hooded Cloak" and upload the autopilot program before he jumps out of the system.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Warning. Enemy craft inbound.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Enemy threat neutralized.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 11, 'capture_complete', 'Copy that. Acknowledge completion of program upload sequence. Escort the target home, pilot.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 12, 'capture_phase_1', 'What''s this? "Downloading auto-pi..." WHAT? NO!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 13, 'capture_phase_2', 'Don''t do this, CorSec. We could make a deal. I know people! Don''t take me in...'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 14, 'capture_started', 'We copy that, pilot. Acknowledge initiation of auto-pilot override program upload sequence.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 15, 'complete', 'Good work. The auto-pilot program has the Cloak officer en route to CorSec HQ. Return to the station for debriefing.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 16, 'escort_remaining', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Secondary target destroyed. %DI escort ship(s) remaining.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 17, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Secondary target destroyed. Escort wing eliminated.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 18, 'failed_destroy', 'The commander is not going to be pleased that you let the Cloak officer be destroyed. Return to the station for debriefing, pilot.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 19, 'failed_escape', 'The commander is not going to be pleased that you let the Cloak officer escape. Return to the station for debriefing, pilot.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 20, 'panic_1', 'Ah, yes. Here come the reinforcements. Wait... why are they targeting me.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 21, 'panic_2', 'You are done for now. Arg, no you fools. Shoot the CorSec!'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 22, 'panic_3', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 25, 'quest_disable_d', 'Intercept and engage the Cloak officer and his escort wing. You must do only enough damage to the officer to disable his ship. He must not be destroyed.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 26, 'quest_disable_t', 'Disable the Cloak Officer'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 27, 'quest_escort_d', 'When the target ship is under CorSec control, you must escort it through the system while it makes the necessary hyperspace calculations for the jump to headquarters.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 28, 'quest_escort_t', 'Escort the Cloak Officer'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 29, 'quest_location_d', 'You must travel to the Corellia system. Once there, CorSec Command will plot the projected course of the Cloak officer and send you corrdinates via a navigation waypoint.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 30, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 31, 'quest_recover_d', 'After the Cloak officer''s ship has been disabled, move in and remain close to upload the auto-pilot override program.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 32, 'quest_recover_t', 'Upload the Auto-pilot Override Program'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 33, 'quest_update', '\\#pcontrast1 CorSec Command: <\\#pcontrast3  %TO\\#pcontrast1  >'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 34, 'recovery_success', 'Good work. The auto-pilot program has the Cloak officer en route to CorSec HQ. Return to the station for debriefing.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 35, 'split_quest_alert', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 37, 'target_disabled', 'Confirming target ship as disabled. Proceed with program upload sequence.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 38, 'taunt_1', 'Apologies, sir. We cannot allow you to be captured.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 39, 'taunt_2', 'You allowed yourself to be captured? You are too pathetic to be a Cloak officer.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 40, 'taunt_3', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 43, 'thanks_1', 'Gragh! You will pay for this, CorSec.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 44, 'thanks_2', 'Next time you will not be so lucky.'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 45, 'thanks_3', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 48, 'title', 'Corellia System: Capture the Cloak Officer'),
('string/en/spacequest/recovery/corellia_station_mission2_1.stf', 49, 'title_d', 'CorSec Command has received information that a high-ranking officer of the Cloak cell will be passing through the Corellia system. He is to be captured and brought to headquarters for questioning. You must intercept the Cloak Officer, eliminate his escort and disable his ship. Once the ship is disabled you will be able to upload the auto-pilot override program. When the ship is under CorSec control, you must escort it while it makes hyperspace calculations for the jump to CorSec headquarters.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 1, 'abort', 'Yes, run like the coward that you are, CorSec. You will face the wrath of the Cloaks soon.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 3, 'arrival_phase_1', 'We are having difficulty tracking the Cloak leader. Stand by while we filter the scan data.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 4, 'arrival_phase_2', 'Target found. Projected path plotted based on current heading. Intercept and disable the target, and upload the auto-pilot override program.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Warning. Enemy craft inbound.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Enemy threat neutralized.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 11, 'capture_complete', 'Copy that. Acknowledge completion of program upload sequence. Escort the target home, pilot.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 12, 'capture_phase_1', 'Oh no! Please don''t upload that program. It can''t be!'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 13, 'capture_phase_2', 'All is lost! I am captured. REPEAT. I AM CAPTURED!'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 14, 'capture_started', 'We copy that, pilot. Acknowledge initiation of auto-pilot override program upload sequence.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 15, 'complete', 'Something doesn''t seem right here, pilot. Stay alert.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 16, 'escort_remaining', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Secondary target destroyed. %DI escort ship(s) remaining.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 17, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Secondary target destroyed. Escort wing eliminated.\\#pcontrast1 >'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 18, 'failed_destroy', 'The commander is not going to be pleased that you let the Cloak leader be destroyed. Return to the station for debriefing, pilot.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 19, 'failed_escape', 'The commander is not going to be pleased that you let the Cloak leader escape. Return to the station for debriefing, pilot.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 20, 'panic_1', 'Uh oh! You are in for it now!'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 21, 'panic_2', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 22, 'panic_3', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 25, 'quest_disable_d', 'Intercept the Cloak leader, but do not destroy him. Damage his ship only enough to disable him and prevent him from escaping.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 26, 'quest_disable_t', 'Disable the Cloak leader'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 27, 'quest_escort_d', 'Once the Cloak leader is under our control, escort him back to Command for detainment. You can probably expect heavy resistance here.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 28, 'quest_escort_t', 'Escort the Captured Leader'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 29, 'quest_location_d', 'The Cloak leader is moving through the Corellia system.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 30, 'quest_location_t', 'Remain in the Corellia System'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 31, 'quest_recover_d', 'Move in close to the disabled Cloak leader''s ship and the auto-pilot override program will begin to upload automatically.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 32, 'quest_recover_t', 'Upload the Autopilot Override Program'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 33, 'quest_update', '\\#pcontrast1 CorSec Command: <\\#pcontrast3  %TO\\#pcontrast1  >'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 34, 'recovery_success', 'Something doesn''t seem right here, pilot. Stay alert.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 35, 'split_quest_alert', 'The other ship was a decoy. The true Cloak leader is incoming on attack vector. Your auto-pilot program is wasted, you must destroy him.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 37, 'target_disabled', 'Confirming target ship as disabled. Proceed with program upload sequence.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 38, 'taunt_1', 'Die, CorSec!'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 39, 'taunt_2', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 40, 'taunt_3', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 43, 'thanks_1', 'Don''t worry, your time will come.'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 44, 'thanks_2', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 45, 'thanks_3', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 48, 'title', 'Corellia System: Capture the Cloak Leader'),
('string/en/spacequest/recovery/corellia_station_mission5a_1.stf', 49, 'title_d', 'The Cloak leader is on the move through the Corellian system. CorSec command wants him disabled, captured, and brought back to Command for detainment.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 2, 'abort', 'Why have you aborted the recovery operation? We must find out where they got that code.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 3, 'angry_disable', 'You think that you are so very clever. We will see who is clever when this is all over with.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 4, 'arrival_phase_1', 'The Rebel officer is nearby. We are scanning the system for her exact location. Stand by.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 5, 'arrival_phase_2', 'We have located the Rebel officer! That information has been sent to your nav computer. Disable the Rebel officer''s ship and capture her.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 12, 'capture_complete', 'The Rebel officer has been captured. Let''s escort her out of here and to a safe location for interrogation.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 13, 'capture_phase_1', 'Boarding party reporting in. We are facing resistance. Hold any other fighters off until we have successfully taken the ship.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 14, 'capture_phase_2', 'Rebels have been eliminated. Initializing the ship''s restart sequence now.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 15, 'capture_started', 'Beginning capture process. Stand by until the Rebel officer is in our custody.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 16, 'complete', 'Mission completed. You have served your Emperor well, pilot.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI ships remaining in the transport''s escort.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <The transport''s escort has been eliminated.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 19, 'failed_destroy', 'Your orders were to capture the Rebel officer not destroy her. Return to your superior immediately for debriefing.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 20, 'failed_escape', 'You have failed to capture the Rebel officer. Return to your superior immediately for debriefing.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 21, 'panic_1', 'I won''t be taken alive.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 22, 'panic_2', 'Your end approaches, pilot.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 23, 'panic_3', 'They''ll destroy me and my ship rather than let us remain in your filthy hands.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 24, 'panic_4', 'More and more ships will come. Just wait and see.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 25, 'panic_5', 'Ha, you''re under attack again.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 26, 'quest_disable_d', 'Finding out where this Rebel officer got those authorization codes is important to the Empire. Capture her.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 27, 'quest_disable_t', 'Disable the Rebel Officer''s ship'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 28, 'quest_escort_d', 'Follow the captured Rebel officer''s ship to safety. Protect it from any Rebel attack.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 29, 'quest_escort_t', 'Escort the Captured Rebel Officer''s Ship'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 30, 'quest_location_d', 'The Rebel officer has not yet left the Dathomir system. Track her down and capture her before she can leave the system.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 31, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 32, 'quest_recover_d', 'Once the Rebel officer''s ship is disabled, move in close, and wait for the capture process to begin.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 33, 'quest_recover_t', 'Capture the Rebel Officer'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 34, 'quest_update', '\\#pcontrast1 Station Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 35, 'recovery_success', 'The Rebel officer has been captured and is ready for interrogation. Good work, pilot.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 38, 'target_disabled', 'The Rebel officer has been disabled. Move in close and wait for the boarding operation to get underway.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 39, 'taunt_1', 'It isn''t going to be as easy as you thought.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 40, 'taunt_2', 'Give up or we will be forced to hurt you.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 41, 'taunt_3', 'Fine! Fighters, disable the captive ship so that we may board it and free our brother in arms.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 42, 'taunt_4', 'You know you cannot win.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 43, 'taunt_5', 'We will find out what you are doing out here, Imperial dog.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 44, 'thanks_1', 'Nice work, pilot. You lit those Rebels up.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 45, 'thanks_2', 'Way to drive those Rebels away.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 46, 'thanks_3', 'I feel much safer with you flying escort.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 47, 'thanks_4', 'Hang in there. There can''t be that many Rebels left.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 48, 'thanks_5', 'They just are not willing to let us go.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 49, 'title', 'Dathomir System: Capture the Rebel Officer'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_a.stf', 50, 'title_d', 'A Rebel Officer tried to present what seemed to be genuine authorization codes, but was recognized as the Rebel she is. Capture her so that we can find out where she got those codes.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 2, 'abort', 'Why have you aborted the recovery operation? Don''t let that fleeing pirate get away!'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 3, 'angry_disable', 'You think that you are so very clever. We will see who is clever when this is all over with.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 4, 'arrival_phase_1', 'One of the Black Sun pirates fled from the area. We are scanning the system for its location. Stand by.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 5, 'arrival_phase_2', 'We have located the fleeing pirate! That information has been sent to your nav computer. Disable the ship and capture it.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 12, 'capture_complete', 'The fleeing Black Sun pirate has been captured. Let''s escort it out of here.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 13, 'capture_phase_1', 'Boarding party reporting in. We are facing resistance. Hold any other fighters off until we have successfully retaken the ship.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 14, 'capture_phase_2', 'The Black Sun pirates have been eliminated. Initializing restart sequence on the captured ship now.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 15, 'capture_started', 'Beginning capture process. Stand by until the Black Sun pirate''s ship has been taken.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 16, 'complete', 'Mission completed. You have served your Emperor well, pilot.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI ships remaining in the transport''s escort.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <The transport''s escort has been eliminated.>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 19, 'failed_destroy', 'Your orders were to capture that pirate not destroy him. Return to your superior immediately for debriefing.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 20, 'failed_escape', 'You have failed to capture the fleeing Black Sun pirate. Return to your superior immediately for debriefing.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 21, 'panic_1', 'Ah... here come more of my comrades. I''ll escape you yet.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 22, 'panic_2', 'More pirates! They''ll defeat you, pilot.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 23, 'panic_3', 'Great! I''ll be free soon. You can''t stop them from freeing me!'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 24, 'panic_4', 'You should never have attacked the Black Sun, fool.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 25, 'panic_5', 'Blast it! If they can''t free me, they''ll destroy my ship rather than let it remain in your hands.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 26, 'quest_disable_d', 'The information that pirate has could be important. You have to disable the his ship and capture it for the Empire.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 27, 'quest_disable_t', 'Disable the fleeing Black Sun Pirate''s Ship'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 28, 'quest_escort_d', 'Follow the captive Black Sun pirate as it is taken to a safe location. Protect it from any attack.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 29, 'quest_escort_t', 'Escort the captured Black Sun Pirate'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 30, 'quest_location_d', 'The fleeing pirate has not yet left the Dathomir system. Track it down and capture it before it can leave the system.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 31, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 32, 'quest_recover_d', 'Once the pirate''s ship is disabled, move in close, and wait for the capture process to begin.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 33, 'quest_recover_t', 'Capture the fleeing Black Sun Pirate''s Ship'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 34, 'quest_update', '\\#pcontrast1 Station Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 35, 'recovery_success', 'The fleeing Black Sun pirate has been captured and is ready for interrogation. Good work, pilot.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 38, 'target_disabled', 'The fleeing Black Sun pirate''s ship has been disabled. Move in close and wait for the boarding operation to get underway.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 39, 'taunt_1', 'It isn''t going to be as easy as you thought.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 40, 'taunt_2', 'Give up your captive or we will be forced to hurt you.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 41, 'taunt_3', 'Fine! Fighters, destroy the captive.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 42, 'taunt_4', 'You know you cannot win.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 43, 'taunt_5', 'We will find out what you are doing out here, Imperial dog.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 44, 'thanks_1', 'Nice work, pilot. You lit those pirates up.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 45, 'thanks_2', 'Way to drive those pirates away.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 46, 'thanks_3', 'I feel much safer with you flying escort.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 47, 'thanks_4', 'Hang in there. There can''t be that many pirates left.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 48, 'thanks_5', 'They just are not willing to let us go.'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 49, 'title', 'Dathomir System: Capture the Fleeing Black Sun Pirate'),
('string/en/spacequest/recovery/dathomir_station_imp_storyquest_01_d.stf', 50, 'title_d', 'During your attack on Black Sun pirates, one of them turned and fled. We think this may be a sign that the fleeing pirate knows something. Capture it so that we may interrogate the pirate.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 1, 'abort', 'You let the cargo get away! Pray we can get a fix on it''s location before it''s too late.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 2, 'angry_disable', 'Do you really think you have won?'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 3, 'arrival_phase_1', '\\#pcontrast3 Station Command: <\\#pcontrast1 Stay alert, the thieves are close. \\#pcontrast3>'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 4, 'arrival_phase_2', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 The thieves have appeared.  Preparing systems for combat. \\#pcontrast3 >'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 6, 'attack_notify', 'Enemy craft detected on attack vector.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 7, 'attack_stopped', 'Enemy activity has stopped.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 11, 'capture_complete', 'Ship systems have been captured, setting autopilot for jump to hyperspace.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 12, 'capture_phase_1', 'Nav Computer: System Conversion Begun.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 13, 'capture_phase_2', 'Nav Computer: Capture Protocol 90% complete.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 14, 'capture_started', 'Nav Computer: Beginning Capture Protocol.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 15, 'complete', 'I appear to be at your mercy, Captain.  Shall we get moving then?'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 16, 'escort_remaining', '\\#pcontrast3 Tactical Computer < \\#pcontrast1 An escort has been destroyed, %DI remain in the escort \\#pcontrast3 > '),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 17, 'escort_wiped_out', '\\#pcontrast3 Tacitcal Computer: < \\#pcontrast1 The escort has been wiped out, proceed with primary objective. \\#pcontrast3 >'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 18, 'failed_destroy', '\\#pcontrast3 Station Command: < \\#pcontrast1 Damn, we needed that vessel intact. The cargo has been lost... no, it was transfered to another ship. Return for further information. > \\#pcontrast3'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 19, 'failed_escape', '\\#pcontrast3 Station Command: < \\#pcontrast1 They have eluded us. We''ll try to get a fix on their location. Report back in for further updates. \\#pcontrast3 >'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 20, 'panic_1', 'I won''t be taken alive!'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 21, 'panic_2', 'Give up! You''ve never recover this cargo.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 22, 'panic_3', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 25, 'quest_disable_d', 'Target the ship''s engines to disable it'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 26, 'quest_disable_t', 'Disable Target'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 27, 'quest_escort_d', 'Escort the captive ship into position for a hyperspace jump'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 28, 'quest_escort_t', 'Escort Target'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 29, 'quest_location_d', 'Head to last known location of the thieves who stole the cargo.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 30, 'quest_location_t', 'Dantooine System'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 31, 'quest_recover_d', 'Pull up close to begin the capture protocol'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 32, 'quest_recover_t', 'Recover Target'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 33, 'quest_update', '%TO'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 34, 'recovery_success', '\\#pcontrast3 Station Command: < \\#pcontrast1 Good job pilot, the cargo has been recovered and is on it''s way to our lockup. \\#pcontrast3 >'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 35, 'split_quest_alert', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 37, 'target_disabled', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Target has successfully been disabled. \\#pcontrast3 > '),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 38, 'taunt_1', 'If we cannot have it, no one shall.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 39, 'taunt_2', 'We would welcome death over failure!'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 40, 'taunt_3', 'We will have that cargo and discover it''s contents!'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 41, 'taunt_4', 'You''ll not get away again!'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 42, 'taunt_5', 'If we cannot have it, no one shall.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 43, 'thanks_1', 'Don''t worry, your time will come.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 44, 'thanks_2', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 45, 'thanks_3', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 48, 'title', 'Dantooine System: Retrieve the ship with the stolen cargo.'),
('string/en/spacequest/recovery/dathomir_station_priv_storyquest_01_b.stf', 49, 'title_d', 'Before the freighter with our cargo could get to our lockup, it was intercepted and robbed. It would seem that the freighter left your protection too soon. Go to Dantooine and recover our stolen cargo.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 2, 'abort', 'We''ve received an abort code... you can''t just leave us out here. We''re unarmed!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 3, 'angry_disable', 'What do you mean our engines are offline? Oh, I am so going to make you pay for that!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 4, 'arrival_phase_1', 'The hostage convoy will arrive at any moment.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 5, 'arrival_phase_2', 'The hostage convoy has been detected in the region. Disable the transport and rescue the hostages!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/imperial_ss_2.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/imperial_ss_2.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/imperial_ss_2.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/imperial_ss_2.stf', 12, 'capture_complete', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 Primary mission target capture operation complete! \\#pcontrast3 >'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 13, 'capture_phase_1', 'This is primary agent. We''ve broken free of our captors and have started to take the bridge. Buy us a little more time...'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 14, 'capture_phase_2', 'This is primary agent. We''ve taken the bridge. Looks like a standard control configuration...we''ll be underway shortly.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 15, 'capture_started', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 Primary mission target capture operation underway. \\#pcontrast3 >'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 16, 'complete', 'We have our hyperspace jump calculated. Thanks for watching our backs. We owe you one.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 17, 'escort_remaining', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 %DI ships remain in the hostage escort. \\#pcontrast3 >'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 18, 'escort_wiped_out', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 The hostage escort has been eliminated. \\#pcontrast3 >'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 19, 'failed_destroy', 'The hostages have been killed! This is unacceptable! Return to base at once. You are to blame for this failure!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 20, 'failed_escape', 'The hostages have been transported out of the area! We''ll never find them now. Return to base at once!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 21, 'panic_1', 'Looks like Nym''s dogs have our scent.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 22, 'panic_2', 'Nym sent some of his boys out. You better take care of them.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 23, 'panic_3', 'Nice! Nym sent the welcome wagon.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 24, 'panic_4', 'Time to show these boys what Storm Squadron is all about.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 25, 'panic_5', 'This could get ugly.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 26, 'quest_disable_d', 'Once you have intercepted the hostage transport, you will need to disable it in order to begin the capture process. Use the ''['' or '']'' key to target the hostage transport''s subsystems. Cycle through them until you have its engines targeted. Attack the transport until its engines are at 0%.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 27, 'quest_disable_t', 'Disable the Hostage Transport'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 28, 'quest_escort_d', 'Once the hostage transport is captured, you will need to escort it through the Lok system. Follow and protect the hostage transport until it reaches its destination. Nym will probably send fighters out to attempt to destroy your prize rather then let you save them. You will need to keep the hostage transport safe from them.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 29, 'quest_escort_t', 'Escort the Hostages Transport'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 30, 'quest_location_d', 'Travel to the Lok system and capture the hostage transport. Once you enter the system, wait until Imperial command sends you a navigation waypoint to the transport''s most recent location. As the hostage transport moves through the system this navigation waypoint will update to its most recent location. Intercept the transport before it reaches the end of its path or the vessel will jump out of the system.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 31, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 32, 'quest_recover_d', 'Once the hostage transport is disabled you can begin the capture process. Move in close to the hostage transport and wait for the capture process to begin. It might take a couple minutes for the process to begin so you will need to stay close to the vessel while this is happening. Wait until the capture process is completed before you move away from the hostage transport. You will be vulnerable at this point so it might be a good idea to destroy any escort vessels that are with the ship before attempting to capture it.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 33, 'quest_recover_t', 'Capture the Hostage Transport'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 34, 'quest_update', ' \\#pcontrast3 Storm Squadron Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 35, 'recovery_success', 'The hostages are safe and are en route to base. Good job, pilot.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/imperial_ss_2.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/imperial_ss_2.stf', 38, 'target_disabled', 'The hostage transport has been disabled. Move in close to the vessel and stand by until they can make contact.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 39, 'taunt_1', 'No one steals from Nym!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 40, 'taunt_2', 'You thought we would just let you fly out of here?'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 41, 'taunt_3', 'This system is ruled by Nym, the Empire is not welcome here!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 42, 'taunt_4', 'Time to pay for your insolence Imperial fools!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 43, 'taunt_5', 'Good to see you, it''s been a while since I had a challenge!'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 44, 'thanks_1', 'We are in the clear. Nice work, pilot.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 45, 'thanks_2', 'We are in the clear. Nice work, pilot.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 46, 'thanks_3', 'We are in the clear. Nice work, pilot.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 47, 'thanks_4', 'We are in the clear. Nice work, pilot.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 48, 'thanks_5', 'We are in the clear. Nice work, pilot.'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 49, 'title', 'Lok System: Capture the Hostage Transport'),
('string/en/spacequest/recovery/imperial_ss_2.stf', 50, 'title_d', 'Travel to the Lok system and capture the hostage transport. Once you arrive in the Lok system, wait until Imperial command can get you the location of the target transport. Once they have a lock, you will receive a navigation waypoint to its current location. This navigation waypoint will update as the hostage transport moves through the system. Follow these navigation waypoints until you intercept the transport. Once you have intercepted the transport, disable it by targeting the vessel''s subsystems. Use the ''['' or '']'' to target the hostage transport''s engines and then attack the ship until its engines are at 0%. Now move in close to the transport and wait for the capture process to begin. This process may take a couple of minutes so you will need to stay near the transport until it begins. Be careful because you will be vunlerable while waiting for the capture process to complete. Once the vessel is captured you will need to escort it to safety. Follow the hostage transport until it reaches its destination. Keep an eye out for enemy fighters who might attempt to retake the vessel.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 2, 'abort', 'Where are you going? We do not have any means of protecting ourselves. Your superior will certainly learn of your failure.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 3, 'angry_disable', 'Alert! Alert! This is the Twilight Sun. We have been crippled by an Imperial attack. Requesting Alliance fighter support for immediate assistance.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 4, 'arrival_phase_1', 'Stand by for the arrival location of the vessel.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 5, 'arrival_phase_2', 'Arrival location has been sent to your nav computer. Proceed with the operation.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/imperial_ss_6.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters detected.>'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 8, 'attack_stopped', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/imperial_ss_6.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/imperial_ss_6.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/imperial_ss_6.stf', 12, 'capture_complete', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Recovery of vessel completed.>'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 13, 'capture_phase_1', 'Boarding vessel now. This shouldn''t take very long. Stand by.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 14, 'capture_phase_2', 'Mild resistance. Nothing we can''t handle. Almost complete.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 15, 'capture_started', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Recovery of vessel beginning.>'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 16, 'complete', 'Nice work, pilot. We have the vessel safely. Return to your superior officer and report in.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI ship escorts remaining.>'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escorts eliminated.>'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 19, 'failed_destroy', 'You were supposed to capture and return that ship to us, not let it be destroyed. Report back to your commander immediately.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 20, 'failed_escape', 'You let it get away! Report your failure to your commander immediately.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 21, 'panic_1', 'Rebels are swarming in! Look out!'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 22, 'panic_2', 'Smells like a heap of trouble ahead.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 23, 'panic_3', 'Keep them off of me!'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 24, 'panic_4', 'Rebels...it''s whats for dinner.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 25, 'panic_5', 'I am here to chew bubble gum and beat some Rebels. And I am all out of buggle gum.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 26, 'quest_disable_d', 'Destroy the Twilight Sun''s engines and disable it.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 27, 'quest_disable_t', 'Disable the Twilight Sun'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 28, 'quest_escort_d', 'Escort the Twilight Sun and core into Imperial hands. The Rebels are not going to let their prize get away easily so be prepared to fight.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 29, 'quest_escort_t', 'Escort the Twilight Sun'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 30, 'quest_location_d', 'Travel to the Yavin system and capture the Twilight Sun. If the gunboat manages to get out of the Yavin system chances are very slim that the Empire will be able to find where they went.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 31, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 32, 'quest_recover_d', 'Once the vessel is disabled, move in close to begin the capture process. You might want to destroy the gunboat''s escort before attempting this though.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 33, 'quest_recover_t', 'Capture the Twilight Sun'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 34, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 35, 'recovery_success', 'Nice work, pilot. You have performed a difficult task brilliantly. Make a full report to your superior.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 36, 'split_quest_alert', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/recovery/imperial_ss_6.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/imperial_ss_6.stf', 38, 'target_disabled', 'The ship''s engines are offline. Move in and proceed with the boarding operation, before it can get it''s engines back online.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 39, 'taunt_1', 'You cannot escape. That core is ours!'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 40, 'taunt_2', 'Fighters! Focus your fire on the Twilight Sun. We cannot allow the Empire to get that core back.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 41, 'taunt_3', 'Things are looking grim...for you that is.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 42, 'taunt_4', 'Freedom!'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 43, 'taunt_5', 'Who let this Imperial dog off its leash?'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 44, 'thanks_1', 'I bet they will feel that in the morning.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 45, 'thanks_2', 'These Rebels are just the way I like them...dead.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 46, 'thanks_3', 'I don''t think we will have any more trouble with those rebels.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 47, 'thanks_4', 'Nice shooting.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 48, 'thanks_5', 'Looks like Storm Squadron sent me the right pilot for the job.'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 49, 'title', 'Yavin System: Capture the Twilight Sun'),
('string/en/spacequest/recovery/imperial_ss_6.stf', 50, 'title_d', 'The scan team has discovered that the Rebels have found the Death Star''s firing core and are trying to transport it from the system on a gunboat, called the Twilight Sun. The Empire wants that core back in one piece. You are to capture the gunboat carring the firing core, but be warned the ship is being highly protected by the Rebels.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 2, 'abort', 'Don''t worry about us, pilot. We are going to make it just fine.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 3, 'angry_disable', 'Why did you do that? I was fine until you showed up.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 4, 'arrival_phase_1', 'We are beginning our scans for Colonel Hend''s shuttle. Stand by for nav location.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 5, 'arrival_phase_2', 'Pilot, we have a lock on Colonel Hend''s shuttle. Proceed with the rescue operation.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected. Incoming at attack speeds.>'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 12, 'capture_complete', 'We have the ship. Colonel Hend is fine. Escort us to the colonel''s jump location.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 13, 'capture_phase_1', 'I don''t think this is necessary. We should be able to get away on our own.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 14, 'capture_phase_2', 'Uh...thanks for the help, pilot. We will supply the boarding party with the correct jump location.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 15, 'capture_started', 'Beginning main assault on shuttle. Please stand by.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 16, 'complete', 'What...the? Colonel Hend''s shuttle just jumped in the wrong direction. Pilot, get back to your superior officer and make a report...something isn''t right here.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter escort destroyed. Beginning shuttle recovery procedure.>'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 19, 'failed_destroy', 'Colonel Hend''s shuttle has been destroyed. Your failure to protect the colonel is most disturbing. Report back to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 20, 'failed_escape', 'The shuttle jumped out of this sector. Pilot, your orders were to recover the colonel and you failed in that simple task. Report to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 21, 'panic_1', 'Rebels! They must have gotten word of our plan.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 22, 'panic_2', 'Great! I mean look out...'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 23, 'panic_3', 'Looks like you are going to be busy.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 24, 'panic_4', 'You better take care of this.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 25, 'panic_5', 'Rebel fighters? Where did they come from?'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 26, 'quest_disable_d', 'Once you have intercepted Colonel Hend''s shuttle, you will need to disable it in order to begin the capture process. Use the ''['' or '']'' key to target Colonel Hend''s shuttle''s subsystems. Cycle through them until you have its engines targeted. Attack the shuttle until its engines are at 0%.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 27, 'quest_disable_t', 'Disable Colonel Hend''s Shuttle'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 28, 'quest_escort_d', 'Once Colonel Hend''s shuttle is captured, you will need to escort it through the Corellia system. Follow and protect Colonel Hend''s shuttle until it reaches its destination. The Rebels will probably send fighters out to attempt to destroy your prize. You will need to keep Colonel Hend''s shuttle safe from them.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 29, 'quest_escort_t', 'Escort Colonel Hend''s Shuttle'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 30, 'quest_location_d', 'Travel to the Naboo system and capture Colonel Hend''s shuttle. Once you enter the system, wait until Imperial command sends you a navigation waypoint to the shuttle''s most recent location. As Colonel Hend''s shuttle moves through the system this navigation waypoint will update to its most recent location. Intercept Colonel Hend''s shuttle before it reaches the end of its path or the vessel will jump out of the system.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 31, 'quest_location_t', 'Travel to the Nabooian System'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 32, 'quest_recover_d', 'Once Colonel Hend''s shuttle is disabled you can begin the capture process. Move in close to Colonel Hend''s shuttle and wait for the capture process to begin. It might take a couple minutes for the process to begin so you will need to stay close to the vessel while this is happening. Wait until the capture process is completed before you move away from Colonel Hend''s shuttle. You will be vulnerable at this point so it might be a good idea to destroy any escort vessels that are with the ship before attempting to capture it.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 33, 'quest_recover_t', 'Capture Colonel Hend''s Shuttle'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 34, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 35, 'recovery_success', 'Nice work, pilot. Remain on guard until Colonel Hend jumps out of the system. Report back to your superior officer.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 38, 'target_disabled', 'Excellent work, pilot. Now get that boarding party onto the shuttle and recover it.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 39, 'taunt_1', 'You cannot have him, he is ours!'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 40, 'taunt_2', 'Big mistake, Imperial dog.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 41, 'taunt_3', 'Freedom has its price and I am willing to pay it.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 42, 'taunt_4', 'This looks like it is going to get interesting.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 43, 'taunt_5', 'Colonel Hend doesn''t want to stay with you anymore...let him go!'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 44, 'thanks_1', 'Uhhh, nice work?'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 45, 'thanks_2', 'That looks like them all. I will be fine by myself...'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 46, 'thanks_3', 'I am sure that I can handle it from here.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 47, 'thanks_4', 'I have an idea. You fly that way and I will fly the other way...we split up and they will not know where I went.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 48, 'thanks_5', 'I think the Rebels have given up. I should be fine from now on.'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 49, 'title', 'Naboo System: Capture Colonel Hend''s Shuttle'),
('string/en/spacequest/recovery/naboo_imperial_tier2_3.stf', 50, 'title_d', 'Travel to the Naboo system and capture Colonel Hend''s shuttle. Once you arrive in the Naboo system, wait until Imperial command can get you the location of the target shuttle. Once they have a lock, you will receive a navigation waypoint to its current location. This navigation waypoint will update as Colonel Hend''s shuttle moves through the system. Follow these navigation waypoints until you intercept the shuttle. Once you have intercepted the shuttle, disable it by targeting the vessel''s subsystems. Use the ''['' or '']'' to target Colonel Hend''s shuttle''s engines and then attack the ship until its engines are at 0%. Now move in close to the shuttle and wait for the capture process to begin. This process may take a couple of minutes so you will need to stay near the shuttle until it begins. Be careful because you will be vulnerable while waiting for the capture process to complete. Once the vessel is captured you will need to escort it to safety. Follow Colonel Hend''s shuttle until it reaches its destination. Keep an eye out for enemy fighters who might attempt to retake the vessel.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 2, 'abort', 'Yeah, that''s right. You don''t have any business with me anyways.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 3, 'angry_disable', 'Hey, what did you do that for? We were just out on a simple pleasure cruise. There was no need to get violent.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 4, 'arrival_phase_1', 'Scanning system for colonel''s yacht.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 5, 'arrival_phase_2', 'Location of yacht discovered. Transfering the data to your navigation computer. Proceed as planned.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming Enemy fighters.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters have been eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 12, 'capture_complete', 'Yacht captured. Prepare to escort her back to HQ.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 13, 'capture_phase_1', 'What are you doing? You have no right to board us!'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 14, 'capture_phase_2', 'Call this off before it is too late. Your superiors will not be happy when they hear about this.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 15, 'capture_started', 'Boarding process underway. Please stand by.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 16, 'complete', 'Well done. We have the ship in our possession. Now let us see what the good colonel kept in the ship''s systems.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 17, 'escort_remaining', '\\#pcontrast1 Target Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Target Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 19, 'failed_destroy', 'Pilot, your orders were to recover that ship, not destroy it. Report back to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 20, 'failed_escape', 'Pilot, I thought we had made it clear that you were to capture that ship. Report back to your superior immediately.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 21, 'panic_1', 'Rebels incoming! Keep them off of us until we can make the jump.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 22, 'panic_2', 'Watch our back. Those Rebels are not going to be happy about the lose of this shuttle.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 23, 'panic_3', 'I was wondering when they would show up.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 24, 'panic_4', 'Make short work of those Rebels. We have a job to do.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 25, 'panic_5', 'They just don''t know when to quit, do they?'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 26, 'quest_disable_d', 'Take the engines of the yacht offline so you can begin the capture process.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 27, 'quest_disable_t', 'Disable Colonel Hend''s Yacht'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 28, 'quest_escort_d', 'Return the yacht back to Imperial hands. If it is important as we think it is you can expect to be attacked trying to recover it.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 29, 'quest_escort_t', 'Escort Colonel Hend''s Yacht'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 30, 'quest_location_d', 'Travel to the Naboo system and intercept the yacht. Flight command reports that it left the system breifly and then returned. A navigation waypoint will be supplied to you.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 31, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 32, 'quest_recover_d', 'Once it is disabled, move in close to begin the capture process.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 33, 'quest_recover_t', 'Capture Colonel Hend''s Yacht'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 34, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 35, 'recovery_success', 'Excellent work, pilot. Stand by until the yacht jumps.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 36, 'split_quest_alert', 'We think we have found something very interesting in the yacht''s comptures. The shuttle transfered some data to a mercenary craft on it''s way to Yavin 4. Proceed immediately to the Yavin sector and inspect that craft''s computers.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 38, 'target_disabled', 'The yacht is disabled. Take control of it before it can get its engines back online.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 39, 'taunt_1', 'You will never take that vessel!'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 40, 'taunt_2', 'Your the pilot who killed Hend! You are going to pay for that!'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 41, 'taunt_3', 'To get that shuttle you are going to have to get through me first!'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 42, 'taunt_4', 'Attack pattern delta! Now!'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 43, 'taunt_5', 'The force is not with you.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 44, 'thanks_1', 'Foolish Rebels! They should have just stayed at home.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 45, 'thanks_2', 'Very well done, pilot.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 46, 'thanks_3', 'What a waste! Not the Rebels...I just spilled my drink.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 47, 'thanks_4', 'They really need to train their pilots better if they plan on defeating us.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 48, 'thanks_5', 'That was the sorriest thing I have seen in a long time. Where did they get those useless pilots?'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 49, 'title', 'Naboo System: Capture Colonel Hend''s Yacht'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1.stf', 50, 'title_d', 'Someone has stolen the now deceased Colonel Hend''s private yacht. Command thinks that this yacht might have more information regarding Colonel Hend''s activities and wants it back so they can investigate. Capture and return the yacht to Imperial hands.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 1, 'abort', 'Why have you aborted the recovery operation? That shuttle is now lost to the rebels.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 3, 'arrival_phase_1', 'The rebels have taken the Lamdba shuttle. Wait until it comes into range.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 4, 'arrival_phase_2', 'The shuttle is in range. Disable it and recapture it from the rebellion.'),
