('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 12, 'capture_phase_1', 'Boarding party reporting in. We are facing resistance, hold any other fighters off until we have successfully retaken the ship.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 13, 'capture_phase_2', 'Rebels have been elimated. Initilizing shuttle restart squence now.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 14, 'capture_started', 'Boarding party reporting in. Beginning assault on shuttle.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_1_a.stf', 15, 'complete', 'Good work pilot. We are jumping out of the sector...now.'),
