('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 2, 'abort', 'Ha, I knew you couldn''t catch me.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 3, 'angry_disable', 'You are planning on bringing me back alive, aren''t you? Just kill me and get it over with.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 4, 'arrival_phase_1', 'Stand by. Scanning system for vessel Doctor Shinss took to escape his post on Endor.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 5, 'arrival_phase_2', 'Freighter containing Doctor Shinss has been located. Location has been sent to your nav computer. Proceed with caution, scans show the freighter has an escort.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 12, 'capture_complete', 'Freighter with Doctor Shinss has been retaken. Prepare to escort it to jump point.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 13, 'capture_phase_1', 'Stop, please stop! Just let me go.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 14, 'capture_phase_2', 'No...you mustn''t. I will not last long in the hands of the Inquistion.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 15, 'capture_started', 'Capture procedure underway.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 16, 'complete', 'Wonderful, just wonderful. Now they are going to put me to the question. You may have done your duty today, but I hope you realize what you have done to me.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 19, 'failed_destroy', 'You were to capture the doctor''s shuttle, not blow it up! Report to your superior immediately.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 20, 'failed_escape', 'The doctor managed to elude you! That is a black mark on your career...yes indeed it is. Return to your superior and make a report.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 21, 'panic_1', 'They are going to destroy me rather then let me be captured?'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 22, 'panic_2', 'I think I made a big mistake.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 23, 'panic_3', 'I guess it is better to die then to be handed over to the Inquisition.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 24, 'panic_4', 'Listen...just let me go and no one will get hurt.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 25, 'panic_5', 'Rebel fighters. I hope they are here to rescue me. What? No, I am with you!!!'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 26, 'quest_disable_d', 'Disable the Doctor''s ship in order to capture it. Scans show he has picked up an escort somewhere along the way so you should take them out first.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 27, 'quest_disable_t', 'Disable the Doctor''s Vessel'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 28, 'quest_escort_d', 'Follow and protect the doctor on his way back to be questioned by the Inquisition.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 29, 'quest_escort_t', 'Escort the Doctor''s Vessel'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 30, 'quest_location_d', 'Based on our calculations of his jump speed and heading, it would seem the doctor is headed into the Dathomir system. It is unknown why he would choose to head to a closed system, but you are to capture him there.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 31, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 32, 'quest_recover_d', 'Once disabled, move in close to the vessel to being the capture process.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 33, 'quest_recover_t', 'Capture the Doctor''s Vessel'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 34, 'quest_update', 'Imperial High Command:<%TO>'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 35, 'recovery_success', 'You have arrived at the jump point. Wait for the doctor''s shuttle to jump out.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 38, 'target_disabled', 'The freighter''s engines are down. Begin capture procedure.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 39, 'taunt_1', 'Hand over the doctor and no one gets hurt.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 40, 'taunt_2', 'You had better rethink your plan, Imperial dog.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 41, 'taunt_3', 'The doctor is ours. Hands off!'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 42, 'taunt_4', 'Just turn and run like all the other cowardly Imperials do.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 43, 'taunt_5', 'You are in way over your head. Time to drown.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 44, 'thanks_1', 'Time for me to face the questions. I hope you are happy with what you have done.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 45, 'thanks_2', 'Time for me to face the questions. I hope you are happy with what you have done.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 46, 'thanks_3', 'Time for me to face the questions. I hope you are happy with what you have done.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 47, 'thanks_4', 'Time for me to face the questions. I hope you are happy with what you have done.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 48, 'thanks_5', 'Time for me to face the questions. I hope you are happy with what you have done.'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 49, 'title', 'Dathomir System: Capture Doctor Shinss'),
('string/en/spacequest/recovery/naboo_imperial_tier3_2_c.stf', 50, 'title_d', 'Doctor Shinss has discovered that we have begun an investigation on him and has fled rather then face the questions. He stole a freighter and jumped out of the Yavin system a short time ago. You are to track down and capture the doctor so he can be put to the question.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 2, 'abort', 'Yeah, get out of here. We are not in need of your assistance.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 3, 'angry_disable', 'Imperial dog! What is the meaning of this outrage?'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 4, 'arrival_phase_1', 'We are working on getting a lock on the vessel. Once you have its location, travel to her, and bring her back to HQ.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 5, 'arrival_phase_2', 'Sending location of vessel to your nav computer. Go get us that freighter.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 6, 'assigned_delayed', ''),
