('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 12, 'capture_complete', 'Capture process completed. Freighter vessel set to autopilot.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 13, 'capture_phase_1', 'We have nothing you Imperials are interested in.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 14, 'capture_phase_2', 'Alright, alright already! We will set the ship on autopilot. Just don''t get trigger happy.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 15, 'capture_started', 'Capture process underway.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 16, 'complete', 'Nice work, pilot. Our freighter contains a lot more of that material you picked up from that smaller smuggler ship.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 19, 'failed_destroy', 'They would rather destroy that ship then let us find out what was on it? We really need one of those ships back in one piece. Report to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 20, 'failed_escape', 'You failed to capture us that ship. Report back to your commander and explain your actions.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 21, 'panic_1', 'Oh, great! They hired me and now they are coming to blow me out of the sky.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 22, 'panic_2', 'Well, they said this was going to be dangerous.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 23, 'panic_3', 'They look like they mean business.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 24, 'panic_4', 'Oh, great! They hired me and now they are coming to blow me out of the sky.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 25, 'panic_5', 'Oh, great! They hired me and now they are coming to blow me out of the sky.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 26, 'quest_disable_d', 'Disable the crystal smuggler''s engines.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 27, 'quest_disable_t', 'Disable the Crystal Smuggler'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 28, 'quest_escort_d', 'Bring the smuggler back to a designated jump location. Keep a close watch over the smuggler in case anyone attempts to free him.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 29, 'quest_escort_t', 'Escort the Crystal Smuggler'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 30, 'quest_location_d', 'Command got a lock on the vessel landing on the surface. Once the ship takes off you will receive a navigation waypoint to its current location.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 31, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 32, 'quest_recover_d', 'Once disabled, move your fighter in close and wait for the capture process to begin.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 33, 'quest_recover_t', 'Capture the Crystal Smuggler'),
