('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 35, 'recovery_success', 'Vessel is underway. Nice job, pilot.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 36, 'split_quest_alert', 'Alert! Distress signal incoming from damaged recon vessel. Assist vessel with repairs and escort it to safety.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 38, 'target_disabled', 'The freighter has been disabled. Start docking procedures and capture that ship.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 39, 'taunt_1', 'If we can''t have her, no one will!'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 40, 'taunt_2', 'For Coyn! For glory!'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 41, 'taunt_3', 'You should have left well enough alone.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 42, 'taunt_4', 'This will only hurt for a second.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 43, 'taunt_5', 'I am going to make this quick.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 44, 'thanks_1', 'Your turning me over to the Inquisition? What kind of monster are you?'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 45, 'thanks_2', 'Your turning me over to the Inquisition? What kind of monster are you?'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 46, 'thanks_3', 'Your turning me over to the Inquisition? What kind of monster are you?'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 47, 'thanks_4', 'Your turning me over to the Inquisition? What kind of monster are you?'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 48, 'thanks_5', 'Your turning me over to the Inquisition? What kind of monster are you?'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 49, 'title', 'Dathomir System: Capture the Crystal Smuggler'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2.stf', 50, 'title_d', 'The crystals that were recovered from the smuggler are among the most contraband material in the Empire. Just the few crystals that the smuggler had are worth a small fortune, but the question remains, how did they know those crystals were on Dathomir? Ever since that smuggler was discovered command has been keeping even closer watch and they have found another apparent crystal smuggler. This time you are to capture the vessel and bring it back so command can question it''s pilot and investigate it''s contents.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 2, 'abort', 'Yeah, thats right get out of here. I always knew that Imperial pilots were cowards.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 3, 'angry_disable', 'By Coyn! My engines are offline. Your aim is true pilot.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 4, 'arrival_phase_1', 'Getting lock on Coynite Mercenary fighter. Stand by for coordinates.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 5, 'arrival_phase_2', 'We have transfered the location of the fighter to your nav computer. Capture the fighters leader and escort it back to Imperial space.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters incoming.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 12, 'capture_complete', 'Escort captured fighter to safety.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 13, 'capture_phase_1', 'What are you doing? I haven''t done anything wrong.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 14, 'capture_phase_2', 'Fine, fine... We will come with you. Just lay off the pressure, will you?'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 15, 'capture_started', 'Docking procedure underway.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 16, 'complete', 'Nice work. Return to your superior officer for debriefing.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 19, 'failed_destroy', 'Your orders were to capture us that ship. Make your excuses to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 20, 'failed_escape', 'Your orders were to capture us that ship. Make your excuses to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 21, 'panic_1', 'My brothers will kill me before allowing Imperial scum to take me captive.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 22, 'panic_2', 'My nobel death shall be sung in the high places of the universe.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 23, 'panic_3', 'I would rather die then be a servant of the Empire.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 24, 'panic_4', 'My brothers will kill me before allowing Imperial scum to take me captive.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 25, 'panic_5', 'My brothers will kill me before allowing Imperial scum to take me captive.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 26, 'quest_disable_d', 'Disable the Neutron''s engines.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 27, 'quest_disable_t', 'Disable the Coynite Neutron'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 28, 'quest_escort_d', 'Follow and protect the Neutron to a safe jump location. Command is very interested in finding out more about the Coynite and why they are in this system.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 29, 'quest_escort_t', 'Escort the Coynite Neutron'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 30, 'quest_location_d', 'The target vessel and its escort are moving through the Dathomir system. Capture that ship before it can leave the system.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 31, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 32, 'quest_recover_d', 'Once disabled, move in close to the Neutron and wait for the capture process to begin.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 33, 'quest_recover_t', 'Capture the Coynite Neutron'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 34, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 35, 'recovery_success', 'We have the Coynite Mercenary. Nice work pilot. Head for home.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 36, 'split_quest_alert', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 38, 'target_disabled', 'Targets engines are off line. Close the distance and prepare to capture.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 39, 'taunt_1', 'For Coyn! For Glory!'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 40, 'taunt_2', 'We shall overcome!'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 41, 'taunt_3', 'The time for mercy is at an end.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 42, 'taunt_4', 'So you want to play rough, eh? How about some of this! And a little of that! And a whole boat load of this!'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 43, 'taunt_5', 'Mercy is for the weak. I shall crush you!'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 44, 'thanks_1', 'You are a mighty pilot, but they will be back.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 45, 'thanks_2', 'You have not yet defeated the Coynite.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 46, 'thanks_3', 'They will be remembered as heroes.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 47, 'thanks_4', 'You may have destroyed them but I will never bow.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 48, 'thanks_5', 'They will be remembered as heroes.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 49, 'title', 'Dathomir System: Capture a Coynite Neutron'),
('string/en/spacequest/recovery/naboo_imperial_tier4_2_c.stf', 50, 'title_d', 'Command wants to know more about these mercenaries. They have discovered a patrol of their ships moving across the system. You are to capture one of the Neutron fighters in that group and escort it back to Imperial hands.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 2, 'abort', 'Thats right! Let us go. Thank you, thank you.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 3, 'angry_disable', 'You don''t understand! We can''t go back there. You don''t understand what it was like...please, just let me go.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 4, 'arrival_phase_1', 'Scanning system for departing ship. Stand by for nav location.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 5, 'arrival_phase_2', 'Nav coordinates have been updated. We want that ship in one piece. Capture it...don''t blow it up.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 9, 'autorewardbody', ''),
