('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 12, 'capture_complete', 'Capture completed. Escort vessel back to Imperial space.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 13, 'capture_phase_1', 'Just let us go. We don''t want to go back.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 14, 'capture_phase_2', 'If you are not going to let us go. Just kill us. Anything is better then going back to that cursed planet.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 15, 'capture_started', 'Capture process underway. Stand by.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 16, 'complete', 'Vessel has been returned to Imperial hands.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escort fighters remaining.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 19, 'failed_destroy', 'We needed that shuttle in one piece but it was better then letting it escape. Report back to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 20, 'failed_escape', 'You let the shuttle get away. This is a disaster. Report back to your superior.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 21, 'panic_1', 'I would rather die then go back...blow us up please.'),
