('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 26, 'quest_disable_d', 'Intercept and disable the prison break ship before it can leave teh system.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 27, 'quest_disable_t', 'Disable the Prison Break Shuttle'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 28, 'quest_escort_d', 'Escort and protect the vessel until the Inquistion can get their hands on it.'),
