('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 36, 'split_quest_alert', 'They are Imperial officers trying to get off the planet. Their computers indicate that others are trying to leave as well. Stand by.'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 37, 'split_quest_alert_fail', ''),
