('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 49, 'title', 'Dathomir System: Capture the Prison Break Shuttle'),
('string/en/spacequest/recovery/naboo_imperial_tier4_4_a.stf', 50, 'title_d', 'Alerts are going off all over the system. Multiple craft are leaving the planet''s surface. You are assigned to capture the lead vessel and bring it back to the Inqusition so they can better determine a course of action.'),
('string/en/spacequest/recovery/naboo_privateer_14.stf', 1, 'Quest Log Data', 'Text'),
