('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 4, 'arrival_phase_2', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 A vessel matching the description of the Dru`Mdar has appeared with escort.  Preparing systems for combat. \\#pcontrast3 >'),
