('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 12, 'capture_phase_1', 'Nav Computer: System Conversion Begun.'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 13, 'capture_phase_2', 'Nav Computer: Capture Protocol 90% complete.'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 14, 'capture_started', 'Nav Computer: Beginning Capture Protocol.'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 15, 'complete', 'I appear to be at your mercy, Captain.  Shall we get moving then?'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 16, 'escort_remaining', '\\#pcontrast3 Tactical Computer < \\#pcontrast1 An escort has been destroyed, %DI remain in the Dru`Mdar escort \\#pcontrast3 > '),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 17, 'escort_wiped_out', '\\#pcontrast3 Tacitcal Computer: < \\#pcontrast1 The Dru`Mdar escort has been wiped out, proceed with primary objective. \\#pcontrast3 >'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 18, 'failed_destroy', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Damn, we needed that vessel intact, Saymonz would have been a bonus. > \\#pcontrast3'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 19, 'failed_escape', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Drats, Saymonz has eluded us again. \\#pcontrast3 >'),
