('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 28, 'quest_escort_t', 'Escort Target'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 29, 'quest_location_d', 'Area of friendly control in the Dantooine System, this assassin was either brave, or stupid.'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 30, 'quest_location_t', 'Dantooine System'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 31, 'quest_recover_d', 'Pull up close to begin the capture protocol'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 32, 'quest_recover_t', 'Recover Target'),
