('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 34, 'recovery_success', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Good job pilot, Saysmond Varg is on his way to RSF custody now. \\#pcontrast3 >'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 35, 'split_quest_alert', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Priority Alert! Priority Alert!  Preliminary scans indicate that the target Saysmond Varg was not on the Dru`Mdar. Proceed to following patrol route and await orders. \\#pcontrast3 >'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 37, 'target_disabled', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Target has successfully been disabled. \\#pcontrast3 > '),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 38, 'taunt_1', 'Hide behind your hostage RSF fool, they will not save you.'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 39, 'taunt_2', 'He would welcome death over capture!'),
