('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 48, 'title', 'Dantooine System: Capture a Black Sun Assassin'),
('string/en/spacequest/recovery/naboo_privateer_tier3_1a.stf', 49, 'title_d', 'Capture Saysmond Varg, a known Black Sun assassin wanted in connection to attacks on Naboo citizens'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 1, 'abort', 'Receiving abort code. Initiating self destruct sequence.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 2, 'angry_disable', 'Rebel scum! The Imperial Inquisition and our allies will find you and crush your puny army! You haven''t heard the last of us!'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 3, 'arrival_phase_1', 'Stay on the alert, pilot. We''ve located a perfect target for your recovery mission. Our systems detect a hyperspace surge in your area.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 4, 'arrival_phase_2', 'Timing couldn''t be more perfect. The target has arrived. Watch out for its escort.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 6, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 7, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 11, 'capture_complete', 'Vortex Command: < Excellent, the droid has control of the ship and it''s repaired. Provide a safe escort for him pilot. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 12, 'capture_phase_1', 'Unit has breached vessel. Subduing crew.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 13, 'capture_phase_2', 'Unit in place with full control of vessel. Repairing engine system now.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 14, 'capture_started', 'Tactical Computer: < Scanning ... ... Capture underway. Stand by. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 15, 'complete', 'Unit reached safety point. Moving target vessel to rendez-vous coordinates with allied freighter.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 16, 'escort_remaining', 'Vortex Command: < Nice one, pilot! Only %DI enemy vessels left in the area. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 17, 'escort_wiped_out', 'Vortex Command: < Excellent! The escort vessels have been destroyed. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 18, 'failed_destroy', 'Pilot! The mission is a failure. The target ship was destroyed! Report to Ezkiel for further instruction.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 19, 'failed_escape', 'The enemy has hyperspaced out of your immediate area. The mission is a failure, pilot. Report to Ezkiel for further instruction.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 20, 'panic_1', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 21, 'panic_2', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 22, 'panic_3', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 25, 'quest_disable_d', 'Disable the experimental fighter. Keep in mind that its escort will try to eliminate you and if everything else fail, they will try to eliminate fighter itself. You will need to dispatch of them or you will have trouble finishing the mission.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 26, 'quest_disable_t', 'Disable the Experimental fighter.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 27, 'quest_escort_d', 'Escort the captured fighter to safety. The Empire is close by and will undoubtedly send fighters to prevent you from escaping, so be prepared.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 28, 'quest_escort_t', 'Escort captured fighter.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 29, 'quest_location_d', 'You''re out of the high risk area packed with Imperial presence but in the Dathomir system there''s really no where to relax.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 30, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 31, 'quest_recover_d', 'The space assault droid is trying to get control of the ship. Keep it safe in the meantime.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 32, 'quest_recover_t', 'Space assault droid launched.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 33, 'quest_update', 'Vortex Command: < %TO >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 34, 'recovery_success', 'That was a close one. Good work, pilot. We should be able to get some useful information off that ship and the Inquisitor inside it.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 35, 'split_quest_alert', 'Brother Ezkiel: < Good, we have the ship. Our freighter crew is packing up the ''pilot'' as we''d like to have an immediate look at him. Stand by. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 37, 'target_disabled', 'Vortex Command: < Target has been disabled. You''re astromech should be launching the space assault droid now, keep the ship safe while it''s doing its work. >'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 38, 'taunt_1', 'You won''t get away with this, rebel!'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 39, 'taunt_2', 'Destroy them! Don''t let them get away! You''ll pay, rebel scum, you''ll pay!'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 40, 'taunt_3', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 43, 'thanks_1', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 44, 'thanks_2', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 45, 'thanks_3', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 48, 'title', 'Dathomir system: Recover experimental fighter.'),
('string/en/spacequest/recovery/naboo_rebel_tier3_4_c.stf', 49, 'title_d', 'We have detected a hyperspace surge near you with the ship signature fitting one of the Inquisitions experimental fighters. It''s not alone though so you will need to destroy his escort before capturing him.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 1, 'abort', 'We''re almost home, pilot! Don''t quit on us! We still need your help!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 3, 'arrival_phase_1', 'The Zynt''aia Order''s mining freighter is almost in our grasp, pilot. We''re counting on you to capture it and guide it to home base.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 4, 'arrival_phase_2', 'Ahh! The freighter. Pilot, you know what to do. We''re with you every step of the way.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 11, 'capture_complete', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < Good work, pilot. You were able to capture the Zynt''aia freighter flawlessly! Now escort her to safety. >'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 12, 'capture_phase_1', 'You''ll never take us alive!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 13, 'capture_phase_2', 'You may have gotten lucky this time, pilot! The Zynt''aia Order will find you!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 14, 'capture_started', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < So far so good. Stay on this freighter until the capture process is completed. I''ll keep a look out for any attacks coming in. >'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 15, 'complete', 'Good work, pilot. Your mission is a success!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 16, 'escort_remaining', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < You''ve destroyed an enemy ship, pilot! You have %DI enemies left to destroy. >'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 17, 'escort_wiped_out', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < We''re getting closer to our goal. The freighter''s escort has been completely wiped out! >'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 18, 'failed_destroy', 'Pilot! You''ve failed us! The Zynt''aia freighter was destroyed!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 19, 'failed_escape', 'Pilot! You''ve failed us! The Zynt''aia freighter has escaped!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 20, 'panic_1', 'We''ll need you now more than ever, pilot! We''ve got enemies on our tail!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 21, 'panic_2', 'Ahh!! We''re getting hit!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 22, 'panic_3', 'Please help us! We''re getting toasted over here!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 25, 'quest_disable_d', 'By selecting the freighter''s engines or reactor, I can disable the target effortlessly and continue the steps needed to capture the freighter for A''Lerris. (Target the engine or reactor by using the [] keys).'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 26, 'quest_disable_t', 'Disable the Zynt''aian Freighter'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 27, 'quest_escort_d', 'Once I have disabled and recovered the freighter, I must escort it safely back to home base.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 28, 'quest_escort_t', 'Escort the Recovered Freighter'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 29, 'quest_location_d', 'I need to travel to the Tatoo System, if I''m not there already.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 30, 'quest_location_t', 'Travel to the Tatoo System'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 31, 'quest_recover_d', 'Once I have disabled the freighter, I must hover close to it. Soon, it will be infiltrated by allies which will follow to me safety.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 32, 'quest_recover_t', 'Recover the Zynt''aian Freighter'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 33, 'quest_update', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 34, 'recovery_success', 'I''m extremely impressed with your performance, pilot. Not only did you willingly face danger, but you also excelled in the task given! Come home, pilot. You deserve a celebration thrown in your name.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 35, 'split_quest_alert', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < Pilot! You''re breaking up over here! You need to...transmission point...stop Zynt''aia from calling...reinforcments. Stop signal at...costs.[Transmission Ends] >'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 37, 'target_disabled', 'The Zynt''aia freighter has been disabled. Waste no time getting close to it while trying to defend it from incoming attacks. We''re counting on you, pilot.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 38, 'taunt_1', 'Stop! You''re flying in hostile air space, pilot! We have no choice but to open fire!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 39, 'taunt_2', 'This is our freighter, pilot!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 40, 'taunt_3', 'I''m going to defend this freighter with my life! But you''ll be the first to die!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 43, 'thanks_1', 'That was a little close. If you hadn''t been here, I''d be toast!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 44, 'thanks_2', 'I hope you''re going to pay for the repairs I need!!'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 45, 'thanks_3', 'Ugh. I can''t *wait* to go home after this.'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 48, 'title', 'Tatoo System: That Word We Call "Revenge"'),
('string/en/spacequest/recovery/poi_tatooine_general2_3.stf', 49, 'title_d', 'The continual tension between A''Lerris'' miners and the Zynt''aia Order centers around a sphere of obsidian. Granted, this "sphere of obsidian" is none other than a misplaced asteroid, rumored to hold high concentrations of rare and valuable resources. How did it get here? Why must a war, a fight, be the knee-jerk reaction to settle conflicts? Within the smooth, reflectant facets of the ebon asteroid, one can feel a tug at the soul, making the onlooker wonder if there''s something... darker inside. Perhaps it is only a mirror, a glassy surface only meant to show us what lies within our very selves.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 1, 'abort', 'Receiving abort code. Failure is not acceptable... attempting to relocate stolen cargo.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 2, 'angry_disable', 'Rebel scum! We and our allies will find you and crush you! You haven''t heard the last of us!'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 3, 'arrival_phase_1', 'Stay on the alert, pilot. We''ve located a perfect target for your recovery mission. Our systems detect a hyperspace surge in your area.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 4, 'arrival_phase_2', 'Timing couldn''t be more perfect. The target has arrived. Watch out for its escort.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 6, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 7, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 11, 'capture_complete', 'Station Command: < Excellent, the droid has control of the ship and it''s repaired. Provide a safe escort for him pilot. >'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 12, 'capture_phase_1', 'Unit has breached vessel. Subduing crew.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 13, 'capture_phase_2', 'Unit in place with full control of vessel. Repairing engine system now.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 14, 'capture_started', 'Tactical Computer: < Scanning ... ... Capture underway. Stand by. >'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 15, 'complete', 'Unit reached safety point. Moving target vessel to rendez-vous coordinates with allied freighter.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 16, 'escort_remaining', 'Station Command: < Nice one, pilot! Only %DI enemy vessels left in the area. >'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 17, 'escort_wiped_out', 'Station Command: < Amazing! The escort vessels have been destroyed. Disable that ship, pilot! We''re counting on you. >'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 18, 'failed_destroy', 'Pilot! The target ship was destroyed, but it looks like the cargo was transferred to another ship. We are attempting to locate that ship. Return to the Rori Station for now.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 19, 'failed_escape', 'The enemy has hyperspaced out of your immediate area. We are attempting to relocate that ship now.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 20, 'panic_1', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 21, 'panic_2', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 22, 'panic_3', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 25, 'quest_disable_d', 'Disable the Borvo Bomber with the cargo of repair droids. Keep in mind that its escort will try to eliminate you and won''t hesitate to try and eliminate the bomber itself just to keep you from recovering it.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 26, 'quest_disable_t', 'Disable the Borvo Bomber.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 27, 'quest_escort_d', 'Escort the captured fighter to a safe hyperspace jump point.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 28, 'quest_escort_t', 'Escort captured fighter.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 29, 'quest_location_d', 'Track down the Borvo pirate that stole the shipment of repair droids.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 30, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 31, 'quest_recover_d', 'The space assault droid is trying to get control of the ship. Keep it safe in the meantime.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 32, 'quest_recover_t', 'Space assault droid launched.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 33, 'quest_update', 'Station Command: < %TO >'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 34, 'recovery_success', 'That was a close one. Good work, pilot. We should be able to get our cargo off of that ship.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 35, 'split_quest_alert', 'Station Command: < We are attempting to relocate the cargo. Stand by.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 37, 'target_disabled', 'Target has been disabled. We''re launching the space assault droid now, keep the ship safe while it''s doing its work.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 38, 'taunt_1', 'You won''t get away with this, rebel!'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 39, 'taunt_2', 'Destroy them! Don''t let them get away! You''ll pay, Rebel scum, you''ll pay!'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 40, 'taunt_3', 'This isn''t your fight, Rebel scum!'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 43, 'thanks_1', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 44, 'thanks_2', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 45, 'thanks_3', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 48, 'title', 'Yavin System: Recover stolen cargo from Borvo pirates'),
('string/en/spacequest/recovery/rori_station_reb_storyquest_01_b.stf', 49, 'title_d', 'Borvo pirates made off with the shipment of repair droids you were just escorting to the Rori Station. Recapture that shipment and ensure that it can safely make the jump back to the Naboo System.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 1, 'abort', 'Ha, I knew you would run from the great NEZZO!'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 3, 'arrival_phase_1', 'Stand by for location of Nezzo Milli''s ship. '),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 4, 'arrival_phase_2', 'Ship located. Nezzo is considered dangerous. Proceed with caution.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 6, 'attack_notify', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 7, 'attack_stopped', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 11, 'capture_complete', 'Autopilot has been reprogrammed. Escort vessel back to safe jump point.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 12, 'capture_phase_1', 'Hey, you can''t do that! Don''t you know who I am?'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 13, 'capture_phase_2', 'So you think you have heard the last of NEZZO? I will show you...one day I shall have my revenge.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 14, 'capture_started', 'Beginning autopilot reprogramming sequence. Stand by.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 15, 'complete', 'We have Nezzo back with us. We will be sure to see that he gets the help he needs.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 16, 'escort_remaining', 'Tactical Computer: < %DI escort fighters remaining. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 17, 'escort_wiped_out', 'Tactical Computer: < Escort fighters eliminated. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 18, 'failed_destroy', 'We wanted him back in one piece, not dead. That ship was valuable property.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 19, 'failed_escape', 'You let that lunatic get away! What kind of fighter pilot are you?'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 20, 'panic_1', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 21, 'panic_2', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 22, 'panic_3', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 25, 'quest_disable_d', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 26, 'quest_disable_t', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 27, 'quest_escort_d', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 28, 'quest_escort_t', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 29, 'quest_location_d', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 30, 'quest_location_t', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 31, 'quest_recover_d', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 32, 'quest_recover_t', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 33, 'quest_update', 'Twin Star Shipping: < %TO >'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 34, 'recovery_success', 'The vessel is now jumping out of the system. Stand by.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 35, 'split_quest_alert', 'Your next assignment is to travel to Endor and help our shipping fleet against a band of environmental radicals known as the Greenburst.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 37, 'target_disabled', 'His ship is offline. Move in close while we trigger the flight computer overrride.'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 38, 'taunt_1', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 39, 'taunt_2', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 40, 'taunt_3', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 43, 'thanks_1', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 44, 'thanks_2', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 45, 'thanks_3', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 48, 'title', 'Space Lok: Capture Nezzo Milli'),
('string/en/spacequest/recovery/stn_dantooine_owner_all_repairmission_tier2_3.stf', 49, 'title_d', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 1, 'abort', 'Hey, I thought you were going to help us?'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 3, 'arrival_phase_1', 'Ok, I am tracking one of my ships. When I send you its location, you go and rescue it...okay?'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 4, 'arrival_phase_2', 'I have a lock on my ship. Intercept and recapture it for me.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 6, 'attack_notify', 'Tactical Computer: < Incoming enemy fighters. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 7, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 11, 'capture_complete', 'Freighter is back under its own power. Escort it to safety.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 12, 'capture_phase_1', 'Hey, I knew old Droz wouldn''t leave us to rot under the yoke of these Imperials.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 13, 'capture_phase_2', 'Ok, our systems are back online. Powering up now.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 14, 'capture_started', 'Assisting freighter on restarting its systems. Stand by.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 15, 'complete', 'Ok, I have my freighter back. You did good pilot...real good.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 16, 'escort_remaining', 'Tactical Computer: < %DI escort fighters remaining. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 17, 'escort_wiped_out', 'Tactical Computer: < Escort fighters eliminated. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 18, 'failed_destroy', 'I was really hoping that it wouldn''t come to this. Blast those Imperials!'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 19, 'failed_escape', 'You let them take my freighter out of the system. I doubt I will ever see that one again.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 20, 'panic_1', 'I knew they would not let me get away so easily.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 21, 'panic_2', 'We wanted to escape...not die!'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 22, 'panic_3', 'Imperial TIEs incoming. Keep them off of me.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 23, 'panic_4', 'Wow, we sure made them mad.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 24, 'panic_5', 'I should have known...they are coming back to finish me off.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 25, 'quest_disable_d', 'Shut down the freighters systems so the pilot can reprogram the autopilot.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 26, 'quest_disable_t', 'Disable the Freighter');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 27, 'quest_escort_d', 'Escort the freighter to safety, protecting it from Imperial counterattacks.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 28, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 29, 'quest_location_d', 'The supply fleet is being used by the Imperials in the Dantooine system.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 30, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 31, 'quest_recover_d', 'Move in close to the freighter and wait for them to get their systems back online.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 32, 'quest_recover_t', 'Recovery the Freighter'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 33, 'quest_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 34, 'recovery_success', 'My freighter is jumping to safety now...thanks.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 35, 'split_quest_alert', 'The Imperials are destroying the some of the Dantooine stations supply fleet as punishment for the loss of that freighter. Help the fleet drive off the attackers.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 36, 'split_quest_alert_fail', 'Destroy the Imperial Logistic''s Officer. He is the reason that the Dantooine supply fleet was conscripted and is ultimately responsible for the loss of the frieghter. Stand by for coordinates to his location.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 37, 'target_disabled', 'Freighters systems shut down. Move in close and assist it in escape.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 38, 'taunt_1', 'Foolish Rebel! You cannot thwart the will of the Empire.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 39, 'taunt_2', 'Fine, we will just destroy the freighter.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 40, 'taunt_3', 'Rebel scum like you should know their place.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 41, 'taunt_4', 'That freighter is as good as dead.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 42, 'taunt_5', 'Do you really think you will win?'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 43, 'thanks_1', 'You did it. Nice work.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 44, 'thanks_2', 'Droz picked the right pilot for this job.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 45, 'thanks_3', 'I always like the Rebellion.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 46, 'thanks_4', 'The Empire has been taught a lesson.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 47, 'thanks_5', 'I knew Droz wouldn''t leave me to rot.'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 48, 'title', 'Dantooine System: Rescue the Freighter'),
('string/en/spacequest/recovery/stn_dantooine_owner_rebel_landing_tier2_1.stf', 49, 'title_d', 'The Dantooine station has had most of its supply fleet conscripted by the Empire and the station owner has asked you to assist him in getting those ships back. He has offered you landing rights for assisting him.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 1, 'abort', 'Yes! We don''t belong to you anyways.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 2, 'angry_disable', 'Hey, settle down! We can work something out.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 3, 'arrival_phase_1', 'The Bez''ox Mentzz should be jumping in any moment now. Intercept and capture that freighter. Those supplies are important to us.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 4, 'arrival_phase_2', 'There they are. Intecept and capture the Bez''ox Mentzz. For good measure maybe you should wipe out its escort too.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 6, 'attack_notify', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 7, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 11, 'capture_complete', 'Escort the Bez''ox Mentzz out of the area. We need that Inhibitor.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 12, 'capture_phase_1', 'What are you doing? We are not carrying anything valuable!'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 13, 'capture_phase_2', 'Ok, well I am yours. I have no wish to be destroyed. You tell me what you want me to do and I will do it!'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 14, 'capture_started', 'Dantooine Station: < I will inform the Bez''ox Mentzz to alter its route or you will blow it out of the sky. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 15, 'complete', 'We have the Inhibitor. You have been a great help. Now get ready for your next assignment.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 16, 'escort_remaining', 'Tactical Computer: < %DI escort fighters remaining. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 17, 'escort_wiped_out', 'Tactical Computer: < Escort fighters eliminated. >'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 18, 'failed_destroy', 'Oh, this is great...just great! We needed that part. Now we are going to have to start all over again.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 19, 'failed_escape', 'Oh, this is great...just great! We needed that part. Now we are going to have to start all over again.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 20, 'panic_1', 'Look what you did! The owner has a zero tolerance policy on piracy. He is sending his thugs out to blow me up.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 21, 'panic_2', 'Not me...the other ship!'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 22, 'panic_3', 'This is terrible. First I get highjacked and now I am being shot at.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 23, 'panic_4', 'I cannot believe my misfortune.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 24, 'panic_5', 'Not me...the other ship!'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 25, 'quest_disable_d', 'Intercept, disable, and capture the Bezox Mentzz.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 26, 'quest_disable_t', 'Disable the Bezox Mentzz'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 27, 'quest_escort_d', 'Follow the Bezox Mentzz through the system. Keep a watch out for the CorSec, who are always watchful of piracy.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 28, 'quest_escort_t', 'Escort the Bezox Mentzz'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 29, 'quest_location_d', 'The Bezox Mentzz is traveling through the rich shipping lanes of the Corellia system.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 30, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 31, 'quest_recover_d', 'After the ship is disabled move in close and wait for the capture process to begin.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 32, 'quest_recover_t', 'Capture the Bezox Mentzz'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 33, 'quest_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 34, 'recovery_success', 'Yes! We have the Bez''ox Mentzz on our scanners. Good work, pilot.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 35, 'split_quest_alert', 'CorSec fighters detected! Incoming at high speeds. Destroy them all.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 37, 'target_disabled', 'Move in close and I will send them a warning. They are going to be coming out to me after all!'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 38, 'taunt_1', 'Pirates like you don''t deserve mercy.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 39, 'taunt_2', 'Better we destroy the ship then let you have it.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 40, 'taunt_3', 'I don''t think you are going to get away with this.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 41, 'taunt_4', 'Prepare to become dust.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 42, 'taunt_5', 'I feel sorry for you...well no I don''t.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 43, 'thanks_1', 'I will follow you...just keep me safe.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 44, 'thanks_2', 'At least I am alive...for now.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 45, 'thanks_3', 'Can''t you just take the cargo and leave me alone?'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 46, 'thanks_4', 'I will follow you...just keep me safe.'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 47, 'thanks_5', 'Can''t you just take the cargo and leave me alone?'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 48, 'title', 'Corellia System: Capture the Bez''ox Mentzz'),
('string/en/spacequest/recovery/stn_dantooine_owner_smuggler_recovery01_tier2_1.stf', 49, 'title_d', 'The Dantooine station wants the supplies that are being shipped inside the Corellia system on the Bezox Mentzz. Intercept and capture that vessel.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 1, 'abort', 'I thank you for your incompetence Imperial dog.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 3, 'arrival_phase_1', '\\#pcontrast3 Kilnstrider: < \\#pcontrast1 Get moving Captain, we do not want that ship to escape. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 4, 'arrival_phase_2', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Target has been locked in. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 6, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 7, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile actions has ceased. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 8, 'autorewardbody', 'By the authority of < Admiral Kilnstrider > you have been awarded a credit bonus to the sum of < 20000 > for < Capture of a Rebel operative> '),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 9, 'autorewardfrom', 'Office of the Imperial Navy'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 10, 'autorewardsubject', 'Bonus for Mercenary Operations'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 11, 'capture_complete', 'The capture is complete'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 12, 'capture_phase_1', 'Hey, I''m just an innocent bystander here... why don''t you just let me go.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 13, 'capture_phase_2', 'You know, we really don''t have to go through all of this trouble.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 14, 'capture_started', 'System override protocol begun.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 15, 'complete', '\\#pcontrast3 Kilnstrider: < \\#pcontrast1 Good work Captain, I will take personal pleasure in extracting the information we need from this pilot about what they are doing in this system.  Kilnstrider out. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 16, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 And escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 17, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 18, 'failed_destroy', '\\#pcontrast3 Kilnstrider: < \\#pcontrast1 It is unfortunate to find such incompetence infesting our navy. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 19, 'failed_escape', '\\#pcontrast3 Kilnstrider: < \\#pcontrast1 It is unfortunate to find such incompetence infesting our navy. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 20, 'panic_1', 'Make it quick!'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 21, 'panic_2', 'Get him, get him... save me, save me!'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 22, 'panic_3', 'It doesn''t have to be this way!'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 25, 'quest_disable_d', 'Cycle through the targets components with the default [ or ] keys until you select their engines or reactor.  Fire on the target until one of these components and you are notified that the target has been disabled.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 26, 'quest_disable_t', 'Disable'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 27, 'quest_escort_d', 'Escort the captured starfighter to the Endor Station, protecting against retributive attacks by Rebel forces.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 28, 'quest_escort_t', 'Escort'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 29, 'quest_location_d', 'An escape route near the suspicious nebula.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 30, 'quest_location_t', 'Endor System'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 31, 'quest_recover_d', 'Fly up next to the disabled craft and the recovery process will begin.  When this process ends the ship will repair itself and move out to an egress point.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 32, 'quest_recover_t', 'Recovery'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 33, 'quest_update', '%TO'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 34, 'recovery_success', '\\#pcontrast3 Endor Station: < \\#pcontrast1 I have control of the ship now Captain.  The Admiral sends his thanks and I have been authorized to present a mercenary bonus for this operation. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 35, 'split_quest_alert', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Jump signatures show them coming out near Isryn''s Veil in the Dantooine System.  Proceed with best haste and you may still catch them. And I may overlook this current failure. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 36, 'split_quest_alert_fail', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Jump signatures show them coming out near Isryn''s Veil in the Dantooine System.  Proceed with best haste and you may still catch them. And I may overlook this current failure. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 37, 'target_disabled', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 The target is disabled, approach to begin capture protocol. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 38, 'taunt_1', 'We can''t let them take you alive.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 39, 'taunt_2', 'You underestimate the conviction of our Rebel fighters.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 40, 'taunt_3', 'We are coming for you.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 43, 'thanks_1', 'They will send more, you won''t get away.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 44, 'thanks_2', 'I won''t talk, you can''t make me talk.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 45, 'thanks_3', 'How do I get myself into these things.'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 48, 'title', 'Endor System: Fox and the Hound'),
('string/en/spacequest/recovery/stn_endor_irs_imp_tier3_2c.stf', 49, 'title_d', 'Capture the escaping starfighter, Admiral Kilnstrider wants the pilot for questioning.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 1, 'abort', 'This is too much, we are out of here.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 2, 'angry_disable', 'Imperial override disabled.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 3, 'arrival_phase_1', '\\#pcontrast3 Vestil: < \\#pcontrast1 I''m Vestil Kwass.  I work for Nym, and now you work for me.  We are tracking the prisoner ship now, it is odd for one craft to be handed back and forth so much but this is the way they want it. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 4, 'arrival_phase_2', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Target locked in. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 6, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 7, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 8, 'autorewardbody', 'I can promise that we will treat those Imperial prisoners better than they would have treated ours.  I have included a 10000 credit bonus for you, keep up the good work.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 9, 'autorewardfrom', 'Vestil'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 10, 'autorewardsubject', 'Getting our boys home safe.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 11, 'capture_complete', '\\#pcontrast3 The recovery is complete.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 12, 'capture_phase_1', 'Hurry up, they will send another attack group soon.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 13, 'capture_phase_2', 'System restart complete, we will be underway shortly.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 14, 'capture_started', '\\#pcontrast3 The recovery has begun'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 15, 'complete', '\\#pcontrast3 The operation is a success.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 16, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 17, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 18, 'failed_destroy', '\\#pcontrast3 Mission Failed: The prisoner ship was destroyed.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 19, 'failed_escape', '\\#pcontrast3 Vestil: < \\#pcontrast1 The Empire has recovered their men, and we have lost ours.  This is hardly a good result. \\#pcontrast3 >'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 20, 'panic_1', 'They are coming back for more.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 21, 'panic_2', 'Not this again.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 22, 'panic_3', 'My, this is oddly familiar.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 23, 'panic_4', ''),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 24, 'panic_5', ''),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 25, 'quest_disable_d', 'Target the transport by using the default ''['' and '']'' keys to cycle to the engine component and destroy it.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 26, 'quest_disable_t', 'Disable Target'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 27, 'quest_escort_d', 'Escort the transport safely out of the system.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 28, 'quest_escort_t', 'Escort Target'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 29, 'quest_location_d', 'Chase down the transport as they flee through the system.'),
