('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 37, 'target_disabled', 'The Prisoner Ship is disabled, begin the recovery.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 38, 'taunt_1', 'The hostages have been declared expendable.  '),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 39, 'taunt_2', 'They will die with honor.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 40, 'taunt_3', 'The Emperor wills your distruction.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 41, 'taunt_4', ''),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 42, 'taunt_5', ''),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 43, 'thanks_1', 'Only a bit more and we are out of here.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 44, 'thanks_2', 'Stay focused, they are out to destroy us it appears.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 45, 'thanks_3', 'Maybe capture wasn''t so bad.'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 46, 'thanks_4', ''),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 47, 'thanks_5', ''),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 48, 'title', 'Lok System: Contention'),
('string/en/spacequest/recovery/stn_lok_nym_reb_tier2_1a.stf', 49, 'title_d', 'The Storm Squadron, an elite group of Imperial Pilots, have recovered a number of Imperial prisoners in transit to a safe location.  Go liberate that transport from the Imperials and get it back on track.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 1, 'abort', 'I thought you were going to rescue me? Those cultist will certainly capture me again.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 2, 'angry_disable', 'You have angered the might of the great fireball...what? The prisoner has escaped....this can''t be!'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 3, 'arrival_phase_1', 'Stand by. We are transmitting the location data to your flight computer now.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 4, 'arrival_phase_2', 'You should have the target location in your flight computer, now. Good luck.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 11, 'capture_complete', 'Target vessel''s engines are back online. Escort it to safety.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 12, 'capture_phase_1', 'I managed to overpower my captures when you disabled the ship. Let me get this back online and then let''s get out of here.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 13, 'capture_phase_2', 'Ok, I managed to reroute power from the life support systems. Let''s get out of here!'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 14, 'capture_started', 'Target disabled. Stand by.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 15, 'complete', 'The executive has been safely returned to the mining company. Return to the Yavin station.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 16, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI fighter escorts remaining.>\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 17, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter escort eliminated.>\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 18, 'failed_destroy', 'This is most unfortunate. Fortunately we took into account that we might lose our man so we took extra precautions. We have another executive waiting to take his place. Stand by to escort that vessel safely through Yavin.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 19, 'failed_escape', 'I doubt that we will be seeing our man ever again now. Fortunately we took failure into account and took some extra precautions. We have another executive waiting to take his place. Stand by to escort that vessel safely through Yavin.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 20, 'panic_1', 'Debris Cultist! They just won''t let me go.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 21, 'panic_2', 'Destroy them! Destroy them all!'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 22, 'panic_3', 'I hope the company hired a good pilot.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 23, 'panic_4', 'It doesn''t look like we are in the clear yet.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 24, 'panic_5', 'They are not going to try to capture me this time.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 25, 'quest_disable_d', 'Bring the hostage vessel to a complete stop to give the executive a chance to gain control of the vessel.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 26, 'quest_disable_t', 'Disable the Hostage Vessel'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 27, 'quest_escort_d', 'Follow the vessel to safety and protect it from Debris Cult counterattacks.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 28, 'quest_escort_t', 'Escort the Hostage Vessel'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 29, 'quest_location_d', 'The ship holding the executive is located in the Yavin system.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 30, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 31, 'quest_recover_d', 'Move in close to the vessel and wait for the executive to contact you.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 32, 'quest_recover_t', 'Rescue the Hostage'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 33, 'quest_update', '\\#FF0000 Yavin Mining Company: \\#FF0000 <%TO>'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 34, 'recovery_success', 'Excellent work. We knew that you were right for the job. Return to the station.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 35, 'split_quest_alert', 'The Yavin Mining Company has another executive waiting to take over for their lost man. Escort this executive through the Yavin system safely.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 37, 'target_disabled', 'Nice work. Now dock with the vessel and try to free our man.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 38, 'taunt_1', 'We warned you to leave...now feel our wrath.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 39, 'taunt_2', 'If you strike me down, I shall only become one with the scrap.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 40, 'taunt_3', 'You shall be added to the field of debris.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 41, 'taunt_4', 'Our lord commands that you do not make it out alive.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 42, 'taunt_5', 'Prepare yourself...you are about to meet eternity.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 43, 'thanks_1', 'Nice flying. That was close.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 44, 'thanks_2', 'The company definitely got what they paid for when they hired you.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 45, 'thanks_3', 'This computer is fried. It will take me a little while to get my jump cordinates locked in. '),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 46, 'thanks_4', 'Those debris cultist are crazy! They blame us for the Imperial salvage operation.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 47, 'thanks_5', 'Thanks! You are making a habit out of saving me.'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 48, 'title', 'Yavin System: Rescue the Company Executive'),
('string/en/spacequest/recovery/stn_yavin4_company_all_opening_tier2_2.stf', 49, 'title_d', 'The information that you recovered has revealed where the executive is being held hostage. Intercept that ship and rescue the executive.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 1, 'abort', 'You have failed in your duty to the Empire to put a stop to illegal smuggling.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 3, 'arrival_phase_1', 'We are getting a lock on the illegal vessel. Stand by for coordinates.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 4, 'arrival_phase_2', 'The location of the illegal vessel has been sent to your nav computer. Intercept and capture that vessel.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters detected. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters eliminated. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 11, 'capture_complete', 'The vessel is under your control. Escort it back for questioning by the Empire authorities.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 12, 'capture_phase_1', 'What are you doing? You have no right! '),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 13, 'capture_phase_2', 'Fine, I will follow you. Just don''t blow me up.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 14, 'capture_started', 'Capture process beginning. The target vessel will have 30 seconds to comply or be destroyed.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 15, 'complete', 'The vessel is in Imperial hands. Return to your normal duties.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 16, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < %DI escort fighters remaining. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 17, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy escort fighters eliminated. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 18, 'failed_destroy', 'You were supposed to capture that ship, not destroy it.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 19, 'failed_escape', 'You were supposed to capture that ship, not let it get away.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 20, 'panic_1', 'They are going to destroy me rather then let me be captured.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 21, 'panic_2', 'You captured me, now you have to keep me alive!'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 22, 'panic_3', 'Polard is never going to let me talk.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 23, 'panic_4', 'Blast it! I knew that if I got captured Polard would never let me live.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 24, 'panic_5', 'They are not going to let me talk. You have to protect me!'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 25, 'quest_disable_d', 'Intercept and disable the freighter before it can leave the system.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 26, 'quest_disable_t', 'Disable the Freighter'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 27, 'quest_escort_d', 'Escort the freighter back to the station so that the pilot can be questioned.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 28, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 29, 'quest_location_d', 'The ship is still in the Yavin system but it is probably getting ready to jump from the system. Intercept it before it can escape.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 30, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 31, 'quest_recover_d', 'Once disabled, move in close to the freighter and a warning will be sent. If the vessel refuses to return to base you will destroy it.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 32, 'quest_recover_t', 'Capture the Freighter'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 33, 'quest_update', '\\#FF0000 Yavin Station Imperial Command:\\#FF0000 < %TO >'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 34, 'recovery_success', 'The illegal smuggler is back in our hands. If we have anything further for you to do we will inform the Yavin station.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 35, 'split_quest_alert', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 37, 'target_disabled', 'The vessel''s engine system is shut down. Move in close and deliver our ultimatium.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 38, 'taunt_1', 'So you thought you could just get away did you?'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 39, 'taunt_2', 'Imperials should keep their noses out of our business.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 40, 'taunt_3', 'We are never going to let him talk.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 41, 'taunt_4', 'I have to kill you. It is nothing personal, just business.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 42, 'taunt_5', 'Polard isn''t going to be happy when he hears about this mess.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 43, 'thanks_1', 'There are going to be more.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 44, 'thanks_2', 'I am in so much trouble right now.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 45, 'thanks_3', 'Listen...as long as you protect me I will tell you everything I know.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 46, 'thanks_4', 'They mean business.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 47, 'thanks_5', 'You have to protect me from Polard.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 48, 'title', 'Yavin System: Capture the Illegal Freighter'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_1.stf', 49, 'title_d', 'A freighter that was hired by the Yavin 4 Mining Company is attempting to leave the system without paying its flight tax. Intercept, capture, and escort this vessel back to Imperial hands for questioning.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 1, 'abort', 'I knew that Imperials were cowards.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 2, 'angry_disable', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 3, 'arrival_phase_1', 'Tracking Polard Manfred. Stand by to intercept.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 4, 'arrival_phase_2', 'We have a lock on the smuggler. Capture and bring this man to justice.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 6, 'attack_notify', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 7, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 11, 'capture_complete', 'Polard Manfred''s ship is now under our control. Escort him to a safe jump point.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 12, 'capture_phase_1', 'What are you doing? I am a private ship and you have no right.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 13, 'capture_phase_2', 'Okay, already. I will obey and go where you want me to.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 14, 'capture_started', 'Sending warning to Polard Manfred to stand down and relinquish control of the vessel over to us.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 15, 'complete', 'Polard Manfred is now in Imperial hands. Return to the Yavin 4 station and speak with the operation.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 16, 'escort_remaining', 'Tactical Computer: <%DI enemy escort fighters remaining. >'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 17, 'escort_wiped_out', 'Tactical Computer: < Escort fighters eliminated. >'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 18, 'failed_destroy', 'We wanted to bring Polard to stand trial. Not kill him.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 19, 'failed_escape', 'Polard got away. Hopefully we will get another chance at this.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 20, 'panic_1', 'My own men are turning on me! Help!'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 21, 'panic_2', 'They will never let me live. I know to much!'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 22, 'panic_3', 'Those pilots will do what ever it takes to make sure I don''t talk.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 23, 'panic_4', 'You have written my death warrent.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 24, 'panic_5', 'Blast it! They are not going to let me live.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 25, 'quest_disable_d', 'Intercept and disable Polard Manfred''s vessel.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 26, 'quest_disable_t', 'Disable Polard Manfred'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 27, 'quest_escort_d', 'Escort Polard Manfred to Imperial hands. Keep the prisoner safe from any associates of his that might try to kill him rather then let him talk.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 28, 'quest_escort_t', 'Escort Polard Manfred'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 29, 'quest_location_d', 'Polard Manfred''s ship is in the Corellia system.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 30, 'quest_location_t', 'Remain in the Corellia System'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 31, 'quest_recover_d', 'Move in close and if he does not agree to return peacefully, you will administer immediate justice on him.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 32, 'quest_recover_t', 'Capture Polard Manfred'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 33, 'quest_update', 'Imperial Command: < %TO >'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 34, 'recovery_success', 'The vessel is away. It is heading towards one of our Star Destroyers who will pick up the criminal shortly.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 35, 'split_quest_alert', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 36, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 37, 'target_disabled', 'Move in close and deliver the ultimatium. '),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 38, 'taunt_1', 'You have betrayed us for the last time.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 39, 'taunt_2', 'Polard, you will never get a chance to talk.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 40, 'taunt_3', 'Sorry boss, but rules are rules.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 41, 'taunt_4', 'I am going to take a great deal of pleasure in this.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 42, 'taunt_5', 'Don''t think that you will get away so easily.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 43, 'thanks_1', 'Well thanks for my life...I guess.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 44, 'thanks_2', 'Imperial prison or being blow to bits...'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 45, 'thanks_3', 'I will tell you everything I know.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 46, 'thanks_4', 'They will be back. I cannot be allowed to live.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 47, 'thanks_5', 'Today just hasn''t been my day.'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 48, 'title', 'Space Corellia: Capture Polard Manfred'),
('string/en/spacequest/recovery/stn_yavin4_imp_imperial_tier2_3.stf', 49, 'title_d', 'Polard Manfred is apparently running an illegal smuggling operation. You are to capture Manfred and turn him over to Imperial hands for questioning.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 2, 'abort', 'Why have you aborted the recovery operation? That transport is now lost to the Rebels.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 3, 'angry_disable', 'You think that you are so very clever. We will see who is clever when this is all over with.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 4, 'arrival_phase_1', 'The Rebels have taken control of the Engineer transport. We are scanning the system for its location. Stand by.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 5, 'arrival_phase_2', 'We have located the transport! That information has been sent to your nav computer. Disable it and recapture it from the Rebellion.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 9, 'autorewardbody', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 12, 'capture_complete', 'The Engineer transport is back in Imperial hands. Let''s get it out of here.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 13, 'capture_phase_1', 'Boarding party reporting in. We are facing resistance. Hold any other fighters off until we have successfully retaken the ship.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 14, 'capture_phase_2', 'Rebels have been eliminated. Initializing transport restart sequence now.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 15, 'capture_started', 'Beginning transport capture process. Stand by until the transport is back in Imperial hands.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 16, 'complete', 'Mission completed. You have served your Emperor well, pilot.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI ships remaining in the transport''s escort.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <The transport''s escort has been eliminated.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 19, 'failed_destroy', 'Your orders were to retake the transport not destroy it. Return to your superior immediately for debriefing.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 20, 'failed_escape', 'You have failed to recapture the transport from Rebel hands. Return to your superior immediately for debriefing.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 21, 'panic_1', 'Looks like trouble ahead.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 22, 'panic_2', 'More Rebels! They are all yours, pilot.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 23, 'panic_3', 'Great! We just get freed and now they are trying to take us back.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 24, 'panic_4', 'The Rebels have to have some sort of base of operations out here for there to be so many of them.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 25, 'panic_5', 'Blast it! Looks like we are under attack.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 26, 'quest_disable_d', 'The engineers are to important to the Empire to be destroyed. You have to disable the transport and recapture it for the Empire.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 27, 'quest_disable_t', 'Disable the Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 28, 'quest_escort_d', 'Follow the transport to safety. Protect it from any Rebel attack.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 29, 'quest_escort_t', 'Escort the Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 30, 'quest_location_d', 'The transport has not yet left the Endor system. Track it down and recapture it before it can leave the system.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 31, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 32, 'quest_recover_d', 'Once the transport is disabled, move in close, and wait for the capture process to begin.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 33, 'quest_recover_t', 'Capture the Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 34, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 35, 'recovery_success', 'The transport and engineers onboard have been safely recovered. Good work, pilot.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 36, 'split_quest_alert', 'During your assault on the transport, a Rebel scout was detected nearby. You are to capture that scout''s computers and retrieve any information it might have.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 38, 'target_disabled', 'Engineer transport has been disabled. Move in close and wait for the boarding operation to get underway.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 39, 'taunt_1', 'It isn''t going to be as easy as you thought.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 40, 'taunt_2', 'Give up the transport or we will be forced to hurt you.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 41, 'taunt_3', 'Fine! Fighters, destroy the transport.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 42, 'taunt_4', 'You know you cannot win.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 43, 'taunt_5', 'We will find out what you are doing out here, Imperial dog.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 44, 'thanks_1', 'Nice work, pilot. You lit those Rebels up.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 45, 'thanks_2', 'Way to drive those Rebels away.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 46, 'thanks_3', 'I feel much safer with you flying escort.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 47, 'thanks_4', 'Hang in there. There can''t be that many Rebels left.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 48, 'thanks_5', 'They just are not willing to let us go.'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 49, 'title', 'Endor System: Capture the Engineer Transport Under Rebel Control'),
('string/en/spacequest/recovery/tatooine_imperial_tier3_1_a.stf', 50, 'title_d', 'The shuttle you were protecting was not the only transport attacked. Rebels have taken another shuttle that was coming in from the Yavin system. The transport is still inside the Endor system. You must rescue the transport and the engineers on board.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 2, 'abort', 'We are at the mercy of our enemies out here. Why are you leaving?'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 3, 'angry_disable', 'Imperial dog! You are making a big mistake. I suggest you leave now before you regret it forever.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 4, 'arrival_phase_1', 'Scanning system for jump location. Once we have the location, proceed to that area, engage, and disable the transport.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 5, 'arrival_phase_2', 'We have a lock. Sending the location to your nav computer. Capture that transport and return it to headquarters.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer: \\#pcontrast3 <Enemy fighters detected.> \\#pcontrast3'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer: \\#pcontrast3 <Enemy fighters eliminated.> \\#pcontrast3'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 9, 'autorewardbody', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 10, 'autorewardfrom', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 12, 'capture_complete', 'Transport is back in Imperial control. Escort it back to headquarters.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 13, 'capture_phase_1', 'We have taken back control of the transport from the Bothans. Attempting to get engines back online.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 14, 'capture_phase_2', 'We almost have it. We should be under way shortly.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 15, 'capture_started', 'Docking procedure beginning.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 16, 'complete', 'The transport is safely in Imperial hands.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort fighters eliminated.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 19, 'failed_destroy', 'We wanted that transport back in one piece. Report your failure to your superior immediately.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 20, 'failed_escape', 'You let the Bothans escape with our transport! Report you disgrace to your superior.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 21, 'panic_1', 'It looks like the Bothan spies had some help.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 22, 'panic_2', 'The Bothans had some support vessels in the area.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 23, 'panic_3', 'I knew it! The Bothans must have been working for the Rebels.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 24, 'panic_4', 'Rebels! The Bothans and them have to be working together.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 25, 'panic_5', 'Look out! Rebels incoming.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 26, 'quest_disable_d', 'Intercept and disable the transport before it can leave the system.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 27, 'quest_disable_t', 'Disable the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 28, 'quest_escort_d', 'Follow the transport back to Imperial controlled space. The Inquisition will question the spy and find out more about their plan.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 29, 'quest_escort_t', 'Escort the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 30, 'quest_location_d', 'Travel to the Endor system and recover the transports stolen by the Bothans. The Bothan''s are attempting to leave the system. Capture this vessel before it can do so.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 31, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 32, 'quest_recover_d', 'Once the transport is disabled, move in close and wait for the capture process to begin.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 33, 'quest_recover_t', 'Capture the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 34, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 35, 'recovery_success', 'Nice work, pilot. The transport is back safely in Imperial space.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 36, 'split_quest_alert', 'Several transports are still under Bothan control. You are needed to recover another one before it gets away.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 38, 'target_disabled', 'The transport''s engines are offline. Quickly start the docking procedure.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 39, 'taunt_1', 'Release the transport back into our control.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 40, 'taunt_2', 'What are you planning out here, Imperial dog?'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 41, 'taunt_3', 'You are going to pay for that!'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 42, 'taunt_4', 'You cannot hide the truth forever.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 43, 'taunt_5', 'Move in! We must recapture that transport!'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 44, 'thanks_1', 'Good work, pilot. The Rebels will think twice about attacking again.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 45, 'thanks_2', 'It looks like the Bothans'' friend were not up to the challenge.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 46, 'thanks_3', 'Excellent! Show them no mercy.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 47, 'thanks_4', 'The Bothan dogs and their allies are no match for the might of the Empire.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 48, 'thanks_5', 'Keep a close eye out. I am sure there are more out there.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 49, 'title', 'Endor System: Capture Bothan Controlled Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2.stf', 50, 'title_d', 'Members of the Bothan Spynet have captured several engineer transports and are attempting to fly them out of the system. These transport contain some very important information that cannot be allowed to fall into Rebel hands. Capture and return your targetted transport before it can escape the system.'),
