('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 26, 'quest_disable_d', 'Disable the transport''s engines so that it may be recovered.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 27, 'quest_disable_t', 'Disable the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 28, 'quest_escort_d', 'Follow and protect the transport on it''s way back to Imperial space.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 29, 'quest_escort_t', 'Escort the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 30, 'quest_location_d', 'The next transport is still in the Endor system. Intercept it before it is able to leave the system.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 31, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 32, 'quest_recover_d', 'Once the engines are offline, move in close, and wait for the capture process to begin.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 33, 'quest_recover_t', 'Capture the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 34, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 35, 'recovery_success', 'Nice work, pilot. Most of the transports made it back to Imperial space.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 36, 'split_quest_alert', 'The satellites that were destroyed need to be replaced immediately. Meet up with a supply freighter and deliver the satellites to the field engineers.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 38, 'target_disabled', 'The transport''s engines are offline. Quickly start the docking procedure.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 39, 'taunt_1', 'You may have won last time but this time will be different.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 40, 'taunt_2', 'I feel sorry for you...wait, no I don''t! Die!'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 41, 'taunt_3', 'We shall overcome your injustice.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 42, 'taunt_4', 'Ignore the Imperial fighter! It is the transport that is important.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 43, 'taunt_5', 'Don''t let the transport get away.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 44, 'thanks_1', 'Good work, pilot. The Rebels will think twice about attacking again.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 45, 'thanks_2', 'It looks like the Bothans'' friend were not up to the challenge.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 46, 'thanks_3', 'Excellent! Show them no mercy.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 47, 'thanks_4', 'The Bothan dogs and their allies are no match for the might of the Empire.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 48, 'thanks_5', 'Keep a close eye out. I am sure there are more out there.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 49, 'title', 'Endor System: Recover Another Stolen Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_2_a.stf', 50, 'title_d', 'The Bothan''s have attacked and captured several engineer''s transports. We must get as many of them back as we can. Each one contains important information about the project. Capture and return another transport to Imperial control.'),
