('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 2, 'abort', 'You just made our day, buddy. Good luck explaining this one.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 3, 'angry_disable', 'Do you think that it will be this easy? You had better run now before our allies show up and destroy you.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 4, 'arrival_phase_1', 'Tracking stolen transport. Stand by for the navigation location.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 5, 'arrival_phase_2', 'Stolen shuttle located. Disable, capture, and return that transport to Imperial hands.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 7, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 8, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 9, 'autorewardbody', ''),
