('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 11, 'autorewardsubject', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 12, 'capture_complete', 'Transport is back under Imperial control. Preparing for departure.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 13, 'capture_phase_1', 'Systems shut down. Attempting to reboot now.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 14, 'capture_phase_2', 'Systems coming back online. We will follow you, just don''t destroy us.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 15, 'capture_started', 'Beginning capture procedure.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 16, 'complete', 'Transport has been returned to Imperial space.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 17, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 18, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 19, 'failed_destroy', 'The Inquisition requested that ship personally. You had better have a good explaination ready. Report back.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 20, 'failed_escape', 'The Inquisition requested that ship personally. You had better have a good explaination ready. Report back.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 21, 'panic_1', 'They are going to destroy us rather then let us be captured.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 22, 'panic_2', 'I would rather die then be turned over to the Inquisition.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 23, 'panic_3', 'You should give up now.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 24, 'panic_4', 'They will never let us be captured alive.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 25, 'panic_5', 'For the Rebellion I give my life.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 26, 'quest_disable_d', 'Intercept and disable the transport''s engines.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 27, 'quest_disable_t', 'Disable the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 28, 'quest_escort_d', 'Follow and protect the transport until it can make the jump back to Endor and the Inquisitor.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 29, 'quest_escort_t', 'Escort the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 30, 'quest_location_d', 'The last transport is in the Dantooine system. Capture it before the Bothan''s can move it out of the system.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 31, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 32, 'quest_recover_d', 'Once the transport is disabled, move in close and wait for the capture process to begin.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 33, 'quest_recover_t', 'Capture the Captured Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 34, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 35, 'recovery_success', 'Nice flying out there, pilot. We have the transport and the agent is most ancious to question those Bothans.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 36, 'split_quest_alert', 'Rebel Command Vessels located. Destroy all enemy vessels.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 37, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 38, 'target_disabled', 'The shuttles engines are down. Being docking procedures.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 39, 'taunt_1', 'That transport belongs to us.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 40, 'taunt_2', 'You are out of your league, Imperial dog.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 41, 'taunt_3', 'We will retake the transport, and destroy you in the process.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 42, 'taunt_4', 'If you want that transport you are going to have to come through me first.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 43, 'taunt_5', 'Freedom!'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 44, 'thanks_1', 'Have a heart, let me die with honor.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 45, 'thanks_2', 'Soldier to soldier...just destroy me.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 46, 'thanks_3', 'Many have fallen, but the tyranny of the Empire will never win.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 47, 'thanks_4', 'One day, I shall have my revenge on you.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 48, 'thanks_5', 'Have a heart, let me die with honor.'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 49, 'title', 'Dantooine System: Capture the Stolen Engineer Transport'),
('string/en/spacequest/recovery/tatooine_imperial_tier4_4_b.stf', 50, 'title_d', 'The Inquisitor wants the Bothan spies sent back to him so he can question them about their operation. We have located the third and final missing transport inside the Dantooine system. You are to capture it and send it back to Endor.'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 1, 'abort', 'You''ve got to be kidding me?! You can''t abort NOW!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 2, 'angry_disable', 'This can''t be happening!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 3, 'arrival_phase_1', '\\#pcontrast3 Beissa: < \\#pcontrast1 The hijacked freighter should arrive there any minute, now... \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 4, 'arrival_phase_2', '\\#pcontrast3 Beissa: < \\#pcontrast1 There! Valarian''s henchmen have flown right into our trap! Disable the ship and clear out the Valarian fighters. \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 6, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 7, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy activity has stopped. \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 11, 'capture_complete', 'Whew! All right. The ship is ours.'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 12, 'capture_phase_1', 'Whoah! They have mini-turrets mounted in the corridors! This will take a bit longer than we suspected...'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 13, 'capture_phase_2', 'Okay, the turret defense system is down. We are now moving on to the command deck...'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 14, 'capture_started', 'Okay! Cover us. We''re going to advance on the bridge...'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 15, 'complete', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 You are on the path to redemption, pilot! But there is still more to do... \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 16, 'escort_remaining', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An escorting craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 17, 'escort_wiped_out', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 All escorting craft have been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 18, 'failed_destroy', 'The weapons shipment is destroyed! Now we''ll have to start this operation all over again. You FAIL.'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 19, 'failed_escape', 'Valarian''s thugs made off with the hijacked transport! You FAIL!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 20, 'panic_1', 'Apparently, Lady Valarian''s not going to let this shipment go without a fight!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 21, 'panic_2', 'Look out! Incoming fighters!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 22, 'panic_3', 'Keep those fighters off our backs!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 23, 'panic_4', 'Keep those fighters off our backs!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 24, 'panic_5', 'Keep those fighters off our backs!'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 25, 'quest_disable_d', 'Target the freighters engines to disable it'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 26, 'quest_disable_t', 'Disable Target'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 27, 'quest_escort_d', 'Escort the recovered freighter out of the system'),
