('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 31, 'quest_recover_d', 'Pull up near the freighter to begin the capture process'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 32, 'quest_recover_t', 'Recover Target'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 33, 'quest_update', '\\#pcontrast3 < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 34, 'recovery_success', '\\#pcontrast3 Beissa: < \\#pcontrast1 The weapons shipment has been safely returned to Hutt control. Jabba will be most pleased! \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 35, 'split_quest_alert', '\\#pcontrast3 Beissa: < \\#pcontrast1 Since you have decided to come back to Jabba, we would like a little demonstration for Lady Valaria so that she may remember you fondly.  Hunt down your replacements. \\#pcontrast3 >'),
('string/en/spacequest/recovery/tatooine_privateer_tier3_1.stf', 36, 'split_quest_alert_fail', ''),
