('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 36, 'quest_disable_d', 'Disable the officers shuttle so that your space assault droid can take control of the ship.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 37, 'quest_disable_t', 'Disable the shuttle.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 38, 'quest_escort_d', 'Escort the stolen shuttle to safety. Imperial ships will almost certainly try to interfere so stay sharp!.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 39, 'quest_escort_t', 'Escort shuttle to safety.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 40, 'quest_location_d', 'The Dathomir system, much like the planet, is a dangerous place. It''s heavily guarded by the Empire as they seem to not want anyone getting access to, or perhaps leave, the planet of Dathomir. Every mission in this system should be considered high risk.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 41, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 42, 'quest_log_data', 'Text'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 43, 'quest_recover_d', 'The space assault droid is taking charge of the shuttle. Protect it from any outside interference in the meantime.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 44, 'quest_recover_t', 'Space assault droid taking charge.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 45, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 46, 'recovery_success', 'Great work pilot, this should make our operation a lot easier.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 47, 'split_quest_alert', 'Alright, time to put those codes to good use. Contacting our infiltration squad for rendez-vous coordinates.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 48, 'split_quest_alert_fail', ''),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 49, 'target_disabled', 'Tactical Computer: < Scans show target vessel disabled. >'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 50, 'taunt_1', 'There is no way you''re leaving this system with that man onboard, even if it means his death!'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 51, 'taunt_2', 'Rebel fools!'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 52, 'taunt_3', 'You thought we would just let you fly out of here?'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 53, 'taunt_4', 'You have one chance to surrender or we will destroy you all!'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 54, 'taunt_5', 'Shut down your engines, in the name of the Emperor!'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 55, 'thanks_1', 'Target vessels sensors show attack fighters type TIE terminated.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 56, 'thanks_2', 'Target vessels sensors show attack fighters type TIE terminated.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 57, 'thanks_3', 'Target vessels sensors show attack fighters type TIE terminated.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 58, 'thanks_4', 'Target vessels sensors show attack fighters type TIE terminated.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 59, 'thanks_5', 'Target vessels sensors show attack fighters type TIE terminated.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 60, 'title', 'Dathomir system: Kidnap Imperial security officer.'),
('string/en/spacequest/recovery/tatooine_rebel_tier3_1.stf', 61, 'title_d', 'To start off our operations in the Dathomir section we need you to obtain some security codes from an Imperial security officer. We can use these codes to infiltrate and decimate the Imperial fleets infrastructure in this system.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 2, 'abort', 'Receiving abort code. Initiating self destruct sequence.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 3, 'angry_disable', 'This is pointless, the Imperial Navy will destroy this ship with me in it rather than let you have it!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 4, 'arrival_phase_1', 'Receiving coordinates from our recon ship, stand by.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 5, 'arrival_phase_2', 'Coordinates uploaded, get moving pilot!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 7, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 8, 'attack_stopped', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
