('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 12, 'capture_complete', 'General Ufwol: < Alright, the droid is in control of the ship, escort it out of there. >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 13, 'capture_phase_1', 'Unit has breached vessel. Terminating crew.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 14, 'capture_phase_2', 'Unit in place with full control of vessel. Repairing engine system now.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 15, 'capture_started', 'General Ufwol: < Good, the space assault droid is attached to the hull of the vessel. >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 16, 'complete', 'Good work pilot. Hopefully we can get something useful out of this ship.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 17, 'escort_remaining', 'General Ufwol: < Nice pilot but don''t let that TIE Oppressor get away! >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 18, 'escort_wiped_out', 'General Ufwol: < Good, that should make this a lot easier. >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 19, 'failed_destroy', 'What happened out there pilot? I expect more from my squad, you should know that by now!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 20, 'failed_escape', 'What happened out there pilot? I expect more from my squad, you should know that by now!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 21, 'panic_1', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 22, 'panic_2', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 23, 'panic_3', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 24, 'panic_4', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 25, 'panic_5', 'Ship sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 26, 'quest_disable_d', 'The TIE Oppressor is the target that we''re after. It''s a prototype advanced bomber that the Empire recently started to manufacture. It''s not without a fighter defense though and it''s got a fairly large escort so it will be dangerous. Use your targeting computer ([ or ] by default) and attack its reactor or engines to disable it.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 27, 'quest_disable_t', 'Disable TIE Oppressor.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 28, 'quest_escort_d', 'The Empire will try to stop you from leaving this area at all costs, even if it means destroying their own ship. Be ready for the attacks!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 29, 'quest_escort_t', 'Escort the stolen ship to safety.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 30, 'quest_location_d', 'You will be heading in to Imperial areas in the Dathomir system so the danger level is extreme. Try to avoid any enemy contact until you find the target of the mission. The TIE Oppressor and its escort will be dangerous enough.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 31, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 32, 'quest_recover_d', 'As soon as the TIE Oppressor has been disabled a space assault droid will be launched on to it. It will breach the hull and try to take control of the ship. While it''s doing this, it''s imperative that you keep the TIE Oppressor safe by eliminating any nearby threats.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 33, 'quest_recover_t', 'Steal the enemy ship.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 34, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 35, 'recovery_success', 'The ship is entering hyperspace, your part is done. Good job pilot.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 36, 'split_quest_alert', 'General Ufwol: < A part of the Alliance called the Vortex have contacted us. They need our help with a quick delivery, stand by for new orders. >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 37, 'split_quest_alert_fail', 'General Ufwol: < Not the outcome we hoped for pilot but we may have another chance. Stand by for new orders. >'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 38, 'target_disabled', 'Target disabled, launch the droid. Good, stand by.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 39, 'taunt_1', 'You know your orders men, destroy them all.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 40, 'taunt_2', 'You are not leaving this area with that ship Rebel scum!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 41, 'taunt_3', 'When I thought Rebels could not get any dumber, they surprise me again!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 42, 'taunt_4', 'There is no way you are getting out of this alive Rebels!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 43, 'taunt_5', 'You have broken so many Imperial laws that we will execute the punishment right here!'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 44, 'thanks_1', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 45, 'thanks_2', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 46, 'thanks_3', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 47, 'thanks_4', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 48, 'thanks_5', 'Ship sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 49, 'title', 'Dathomir system: Steal one of the Empires advanced fighters.'),
('string/en/spacequest/recovery/tatooine_rebel_tier4_2.stf', 50, 'title_d', 'We''re trying to figure out where these new Imperial fighters are manufactured and it''s our hope that examining one will tell us that. We have managed to track down one that isn''t too heavily guarded and we want you to sneak in to Imperial territory and steal it.'),
