('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 8, 'capture_phase_1_1', 'Good job, we''re taking over this ship! Put ''em out of their misery men!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 9, 'capture_phase_1_2', 'Let ''em have it boys!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 10, 'capture_phase_1_3', 'Surprise you Imperial fools!'),
