('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 12, 'capture_phase_1_5', 'Touch those guns and you die! This ship now belongs to Nym!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 13, 'capture_phase_2_1', 'We''re breaking down the door to the bridge now, the ship will be ours in a few seconds!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 14, 'capture_phase_2_2', 'The ship is ours boys!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 15, 'capture_phase_2_3', 'Break down that door men!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 16, 'capture_phase_2_4', 'We are in contr.. take that Imperial scum! Well almost in control, give us a few more seconds.'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 17, 'capture_phase_2_5', 'I could do this all day, nothing better than stealing from the Empire!'),
