('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 38, 'quest_location_d', 'We are not sure why but the Endor system has gathered and immense amount of the Imperial Navy lately and you need to stay sharp while performing missions in it.'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 39, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 40, 'quest_recover_d', 'Our superior pirates are about to take control of the vessel. Keep it safe from interference by Imperial forces while they are crushing all resistance.'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 41, 'quest_recover_t', 'Arrgh!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 42, 'quest_update', 'Nym Command Officer: < %TO >'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 43, 'recovery_success', 'Nice work pilot, our boys are safe!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 44, 'target_disabled', 'Tactical Computer: < Scans show target vessel disabled. >'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 45, 'taunt_1', 'You filthy pirates, you will pay for this!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 46, 'taunt_2', 'You really expected to get away with this?!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 47, 'taunt_3', 'Rebels or Nym, no matter, you''re all scum!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 48, 'taunt_4', 'This joyride ends here you fools!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 49, 'taunt_5', 'Surrender immediately or you will all be destroyed!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 50, 'thanks_1', 'That was awesome! Nym 1, Empire 0!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 51, 'thanks_2', 'Great job everyone! If we get back to Lok, we need to throw one heck of a party!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 52, 'thanks_3', 'Bah, they hardly put up a fight!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 53, 'thanks_4', 'Is that all the Empire got?'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 54, 'thanks_5', 'It''s over already? Hopefully they''ll send some more our way..haha!'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 55, 'title', 'Endor system: Duty mission: Help Nym pirates hijack Imperial troop transports.'),
('string/en/spacequest/recovery_duty/corellia_rebel_tier4_1.stf', 56, 'title_d', 'We are striking an attack against the heavy Imperial presence in the Endor system. We have infiltrated a bunch of their troop transports with our men and they need your assistance in disabling the ships and taking out their escort. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
