('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 28, 'escort_remaining', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 %DI ships remain in the smuggler''s escort. \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 29, 'escort_wiped_out', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 The smuggler''s escort has been eliminated. \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 30, 'failed_destroy', 'The smuggler was destroyed! We want to recover the contraband, not wipe it out. Return to base for debriefing.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 31, 'failed_escape', 'The smuggler has escaped the area. He''ll notify Nym of our plans. We''ll be lucky to find any smugglers now. Return to base.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 32, 'panic_1', 'They are going to destroy me! You must protect me.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 33, 'panic_2', 'Nym destroys any of his ships that fall into enemy hands.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 34, 'panic_3', 'I am in so much trouble.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 35, 'panic_4', 'I don''t want to die so you had better protect me.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 36, 'panic_5', 'I don''t want to die so you had better protect me.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 37, 'quest_disable_d', 'You must disable the freighter so you can capture it. To do this target the vessel, use the '']'' to target the ships engines, and fire on the vessel until it''s engines reach 0% and it is disabled.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 38, 'quest_disable_t', 'Disable the Nym Freighter'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 39, 'quest_escort_d', 'Follow the freighter to safety. You must protect it against attacks from Nym''s men who will surely try to recapture the vessel.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 40, 'quest_escort_t', 'Escort the Nym Freighter'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 41, 'quest_location_d', 'For maximum shock effect, capturing the vessels right under Nym''s thumb will work best. Once inside the Lok system you will receive a navigation waypoint to a freighter that belongs to Nym. You will receive updated navigation locations as it moves through the system.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 42, 'quest_location_t', 'Travel to the Lok System'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 43, 'quest_recover_d', 'Once the vessel is disabled, move in close to the freighter. Remain stationary near it and wait for the capture process to begin. It might take a few moments for this process to start. Wait until it begins and completes before moving.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 44, 'quest_recover_t', 'Capture the Nym Freighter'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 45, 'quest_update', ' \\#pcontrast3 Imperial Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 46, 'recovery_success', 'The smuggler''s cargo has been secured. Good job, pilot.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 47, 'target_disabled', ' \\#pcontrast3 Tactical Computer: < \\#00ff00 The smuggler''s ship has been disabled and the ultimatum delivered. \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 48, 'taunt_1', 'That is Nym''s freighter.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 49, 'taunt_2', 'You have no business here,Imperial.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 50, 'taunt_3', 'Why don''t you just go back from where you came?'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 51, 'taunt_4', 'I am going to enjoy this.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 52, 'taunt_5', 'You are not going to like what I am going to do.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 53, 'thanks_1', 'Gee, thanks. I get to live for a little while longer.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 54, 'thanks_2', 'Instead of going through all this trouble, why not let me go?'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 55, 'thanks_3', 'Can I make you a deal? Let me go and I will give you some of my cargo.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 56, 'thanks_4', 'Instead of going through all this trouble, why not let me go?'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 57, 'thanks_5', 'Gee, thanks. I get to live for a little while longer.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 58, 'title', 'Lok System: Capture the Nym Freighters Duty'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_1b.stf', 59, 'title_d', 'Nym has a number of illegal shipments moving to and from the Lok system every day. The Empire has decided as part of the punishment against Nym for his assistance to the Rebellion, they are going to crack down on those shipments. Capture Nym''s freighters for the Empire as they move through the Lok system.'),
