('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 48, 'taunt_1', 'Time to die, Imperial scum.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 49, 'taunt_2', 'You will regret messing with us.'),
