('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 51, 'taunt_4', 'You will not escape us.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 52, 'taunt_5', 'Prepare to become part of the debris field.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 53, 'thanks_1', 'You have added to the scrap. For that you have my thanks.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 54, 'thanks_2', 'We should join them in the eternal float of debris.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 55, 'thanks_3', 'Another beautiful explosion. Not as big as the big bang but still very nice.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 56, 'thanks_4', 'We should join them in the eternal float of debris.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 57, 'thanks_5', 'You have added to the scrap. For that you have my thanks.'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 58, 'title', 'Yavin System: Capture the Debris Cult Freighter Duty'),
('string/en/spacequest/recovery_duty/lok_imperial_ss_2b.stf', 59, 'title_d', 'The Debris Cult have been religiously gathering large quanities of valuable Death Star debris and shipping them out of the system. While the Empire has no idea what the Scavengers are planning to do with the debris they have collected, they do not want to lose the valuable salvage. You must capture these fleeing freighters and bring their cargo back for the Empire.'),
