('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 30, 'failed_destroy', 'We lost the freighter with all hands aboard. Failure is not tolerated in the Imperial Inquisition. Return to your superior immediately.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 31, 'failed_escape', 'The freighter jumped out of the system. You lost her pilot. Report to your superior at once.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 32, 'panic_1', 'I hope they are on their way to rescue us.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 33, 'panic_2', 'Your in for it now.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 34, 'panic_3', 'You should flee while you have the chance.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 35, 'panic_4', 'They aren''t going to let you have me.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 36, 'panic_5', 'Prepare to become space dust, Imperial dog.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 37, 'quest_disable_d', 'Once you have caught up to the freighter you will need to disable the vessel. In order to disable a ship, target it, then use the '']'' key to cycle through that ship''s systems. Target it''s engines and shoot the vessel. Once the ships engines reach 0% the ship will be disabled.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 38, 'quest_disable_t', 'Disable the Miner Transport'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 39, 'quest_escort_d', 'The Rebels will not like losing their prize to the Empire and will probably try to take it back. Follow the freighter until it reaches it''s destination, protecting it from all attackers.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 40, 'quest_escort_t', 'Escort the Miner Transport'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 41, 'quest_location_d', 'The mining guild is operating in Naboo space and is supplying the Rebels with supplies. You will receive a navigation waypoint to the target craft once you enter Naboo space. This waypoint will update as the vessel moves through the zone.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 42, 'quest_location_t', 'Travel to the Naboo System'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 43, 'quest_recover_d', 'Now that the ship is disabled move in close to begin the capture process. You will need to remain close and stationary in order to capture the vessel. It may take a few moments for the capture process to begin so remain in your current locaiton until it is finished.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 44, 'quest_recover_t', 'Capture the Miner Transport'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 45, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 46, 'recovery_success', 'The freighter is secure. Nice work out there, pilot.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 47, 'target_disabled', 'Target freighter has been disabled.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 48, 'taunt_1', 'That ship belongs to us.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 49, 'taunt_2', 'If we can''t have it, no one will.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 50, 'taunt_3', 'You will regret that.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 51, 'taunt_4', 'Prepare to be wasted.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 52, 'taunt_5', 'I didn''t know that the Empire let you guys off your leashes.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 53, 'thanks_1', 'You are better then you look.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 54, 'thanks_2', 'There will be more, you can count on it.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 55, 'thanks_3', 'That was nice flying but you will have to do better then that to survive.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 56, 'thanks_4', 'Why don''t you die?'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 57, 'thanks_5', 'Bleh! The next wave will get you.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 58, 'title', 'Naboo System: Capture the Ironfleck Marauder (Miner Transport) Duty'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier2_recoveryduty.stf', 59, 'title_d', 'Intelligence has reported that the miners of Naboo are supplying Rebel ships with goods. Your assignment is to capture these supply vessels going to the Rebels and returning them to Imperial hands.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 2, 'abort', 'Please don''t report this. You will not see us in this region again, I swear.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 3, 'angry_disable', ''),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 4, 'arrival_phase_1', 'Getting a lock on the unauthorized ships. Stand by.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 5, 'arrival_phase_2', 'We have a lock on their location. Capture those ships and bring them back to HQ. Any escort that they have with them are expendable.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Alert! Enemy fighters incoming.>'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 8, 'capture_complete', 'The ship is set on autopilot and will head back to HQ.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 9, 'capture_phase_1', 'Hey, how about you just let us go?'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 10, 'capture_phase_1_1', 'Hey, how about you just let us go?'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 11, 'capture_phase_1_2', 'Now our commander is going to hear about this.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 12, 'capture_phase_1_3', 'Do you know what they are going to do to us?'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 13, 'capture_phase_1_4', 'Hey, I have an idea. Let us go!'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 14, 'capture_phase_1_5', 'Well at least you are not going to kill us.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 15, 'capture_phase_2', 'Okay...okay. We will set autopilot. Just don''t blow us out of space.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 16, 'capture_phase_2_1', 'Okay...okay. We will set autopilot. Just don''t blow us out of space.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 17, 'capture_phase_2_2', 'Fine. We will do whatever you want.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 18, 'capture_phase_2_3', 'The Inquisition is going to have a field day with me.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 19, 'capture_phase_2_4', 'I give up.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 20, 'capture_phase_2_5', 'I will just tell them I got lost. Do you think they will buy that?'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 21, 'capture_started', 'Starting docking procedure.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 22, 'complete', 'The rogue ship is back in Imperial hands and the Inquisition is questioning the pilot. Nice work.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 23, 'complete_1', 'The rogue ship is back in Imperial hands and the Inquisition is questioning the pilot. Nice work.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 24, 'complete_2', 'The rogue ship is back in Imperial hands and the Inquisition is questioning the pilot. Nice work.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 25, 'complete_3', 'The rogue ship is back in Imperial hands and the Inquisition is questioning the pilot. Nice work.'),
