('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 28, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI escorts remaining.>'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 29, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Escort fighters eliminated.>'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 30, 'failed_destroy', 'You were told to bring that ship back to us in one piece. Failure is never rewarded. Speak to your superior immediately.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 31, 'failed_escape', 'You let them get away. That is unacceptable. Return to your commander immediately.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 32, 'panic_1', 'Great, first I get caught and now this...just isn''t my day.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 33, 'panic_2', 'Just let them destroy me. Better that then the Inquisition.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 34, 'panic_3', 'Great, first I get caught and now this...just isn''t my day.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 35, 'panic_4', 'Just let them destroy me. Better that then the Inquisition.'),
