('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 42, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 43, 'quest_recover_d', 'Once disabled, move in close to the target vessel and wait for the capture process to begin.'),
