('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 46, 'recovery_success', 'Alright we have the trespasser. Nice work, pilot.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 47, 'target_disabled', 'The engines are out on the ship. Start your docking procedure.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 48, 'taunt_1', 'This is too easy.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 49, 'taunt_2', 'Beg! Maybe I will let you live.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 50, 'taunt_3', 'You may take my life but you can never take my freedom!'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 51, 'taunt_4', 'You are not very good, are you.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 52, 'taunt_5', 'Ha! I laugh at your pathetic attempts to defeat me.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 53, 'thanks_1', 'Should have let them destroy me.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 54, 'thanks_2', 'Oh good, you save me. Now how about you let me go.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 55, 'thanks_3', 'Hmmm, I think I would have rather had the rebels blow me up.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 56, 'thanks_4', 'Should have let them destroy me.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 57, 'thanks_5', 'Oh good, you save me. Now how about you let me go.'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 58, 'title', 'Dathomir System: Capture the Rogue Imperial Vessels Duty'),
('string/en/spacequest/recovery_duty/naboo_imperial_tier4_3.stf', 59, 'title_d', 'Occasionally an Imperial ship will enter the Dathomir system. These ships are to be captured and the pilots turned over to the Inquistion for questioning.'),
