('string/en/spacequest/recovery_duty/naboo_rebel_tier4_1.stf', 46, 'target_disabled', 'Tactical Computer: < Scans show target vessel disabled. Transferring droid model IG-31-V to target vessel. >'),
('string/en/spacequest/recovery_duty/naboo_rebel_tier4_1.stf', 47, 'taunt_1', 'You have some nerve Rebel fool, or you''re just stupid!'),
