('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 8, 'capture_phase_1_1', 'Blasted pirates! The CorSec are going to hear about this.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 9, 'capture_phase_1_2', 'Hey, what are you doing?'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 10, 'capture_phase_1_3', 'Why don''t you pirates get a real job?'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 11, 'capture_phase_1_4', 'So, do you really think you will get away with this?'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 12, 'capture_phase_1_5', 'Piracy is a capital offense in this region. You will be caught.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 13, 'capture_phase_2_1', 'Fine, I will do whatever you want me to...just don''t destroy me.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 14, 'capture_phase_2_2', 'Ok, I will go to Dantooine.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 15, 'capture_phase_2_3', 'You might have captured me but you will pay.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 16, 'capture_phase_2_4', 'Dantooine? Fine...but you will pay for your crimes.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 17, 'capture_phase_2_5', 'I will go to Dantooine but I assure you I will escape once I get the chance.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 18, 'capture_started', 'Capture process beginning. Stand by.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 19, 'complete', 'Ok, I will go to Dantooine, but I am not doing this out of my own free will.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 20, 'escort_remaining', 'Tactical Computer: < %DI escort fighters remaining. >'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 21, 'escort_wiped_out', 'Tactical Computer: < Escort fighters eliminated. >'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 22, 'failed_destroy', 'Blast it! We need those supplies, not scrap metal.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 23, 'failed_escape', 'You let it get away? I thought you said you were a good pilot.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 24, 'panic_1', 'What are they doing? Those incompent fools...'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 25, 'panic_2', 'Hey, I am not with him! Shoot him, not me!'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 26, 'panic_3', 'Great...the CorSec would rather have me destroyed then fall into pirates hands.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 27, 'panic_4', 'I don''t believe this. They have no clue what they are doing.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 28, 'panic_5', 'Look what you have done.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 29, 'quest_disable_d', 'Target the freighters engines and get them to come to a complete stop.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 30, 'quest_disable_t', 'Disable the Freighter'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 31, 'quest_escort_d', 'Follow the freighter until it reaches a jump point to the Dantooine system. Protect it from CorSec who might try to get involved.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 32, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 33, 'quest_location_d', 'The station wants you to raid the shipping lanes of Corellia.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 34, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 35, 'quest_recover_d', 'Move in close to the freighter and wait for them to surrender.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 36, 'quest_recover_t', 'Capture the Freighter'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 37, 'quest_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 38, 'recovery_success', 'Good work. We will have our people on this side escort that freighter the rest of the way. There are more ships waiting to be captured if you want to do that again.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 39, 'target_disabled', 'The freighter has shut down it''s engines. Move in close and wait for it to surrender.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 40, 'taunt_1', 'You will cease your current illegal activity immediately.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 41, 'taunt_2', 'You are in violation of Corellian law. Prepare to be destroyed.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 42, 'taunt_3', 'Piracy is a capital offense.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 43, 'taunt_4', 'Pirates like you deserve no mercy.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 44, 'taunt_5', 'We will not allow you to have the freighter.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 45, 'thanks_1', 'Well, I guess I am stuck with you.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 46, 'thanks_2', 'CorSecs are nearly as bad as you pirates.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 47, 'thanks_3', 'I don''t know who is worse...you or them.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 48, 'thanks_4', 'This just isn''t my day.'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 49, 'thanks_5', 'If I stay with you, they will blow me up. If I try to escape, you will blow me up. This stinks!'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 50, 'title', 'Corellia System: Capture Cargo Freighter''s Duty'),
('string/en/spacequest/recovery_duty/stn_dantooine_owner_smuggler_recoveryduty_tier2_1.stf', 51, 'title_d', 'The Dantooine station needs supplies. They are willing to do anything to get those supplies, even support piracy. You are to raid the rich shipping lanes of Corellia and send the captured freighters to Dantooine.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 2, 'abort', 'You are leaving us to the mercy of these pirates! What are you thinking? Your superior will hear of this failure!'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 3, 'angry_disable', ''),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 4, 'arrival_phase_1', 'Scanning system for mission transports. Stand by for location.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 5, 'arrival_phase_2', 'We have a lock on our transport. Intercept and recapture our ship.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters incoming.>'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 8, 'capture_complete', 'Autopilot under Imperial control. Stand by to escort freighter to HQ.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 9, 'capture_phase_1', ''),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 10, 'capture_phase_1_1', 'Do you know who I work for? No! Well if you did you wouldn''t do it.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 11, 'capture_phase_1_2', 'What are you doing to my computer system?'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 12, 'capture_phase_1_3', 'I will never be taken alive! Hmmm...on second thought I will come along peacefully.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 13, 'capture_phase_1_4', 'This is private property! Granted it was private property before we stole it, but that still doesn''t make what you are doing right.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 14, 'capture_phase_1_5', 'Hey, what are you doing to my Nav computer?'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 15, 'capture_phase_2', ''),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 16, 'capture_phase_2_1', 'You might have control over my ship but you will never have control over me.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 17, 'capture_phase_2_2', 'The Red Skulls will not stand for this.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 18, 'capture_phase_2_3', 'I thought the Empire was fair and just...you have shattered my dreams.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 19, 'capture_phase_2_4', 'I can''t control my ship! You have done something to my computers!'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 20, 'capture_phase_2_5', 'One day I shall get my revenge.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 21, 'capture_started', 'Beginning autopilot reconfigeration. Stand by.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 22, 'complete', 'We have the Red Skull freighter. It''s cargo bay is full of our stolen property. Nice work, pilot.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 23, 'complete_1', 'We have the Red Skull freighter. It''s cargo bay is full of our stolen property. Nice work, pilot.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 24, 'complete_2', 'We have the Red Skull freighter. It''s cargo bay is full of our stolen property. Nice work, pilot.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 25, 'complete_3', 'We have the Red Skull freighter. It''s cargo bay is full of our stolen property. Nice work, pilot.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 26, 'complete_4', 'We have the Red Skull freighter. It''s cargo bay is full of our stolen property. Nice work, pilot.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 27, 'complete_5', 'We have the Red Skull freighter. It''s cargo bay is full of our stolen property. Nice work, pilot.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 28, 'escort_remaining', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%TO enemy escorts remaining.>'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 29, 'escort_wiped_out', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy escort eliminated.>'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 30, 'failed_destroy', 'I thought your orders were clear, pilot. You were to recapture that ship not destroy it. Return to your superior.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 31, 'failed_escape', 'Your incompetence let that ship get away. That is a huge set back for the Empire. Report your failure to your superior.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 32, 'panic_1', 'Yes! My friends are here to punish you. Wait! Why are they targeting me?'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 33, 'panic_2', 'Prepare to pay the price of crossing the Red Skulls.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 34, 'panic_3', 'No, don''t shoot at me! I am on your side.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 35, 'panic_4', 'Here comes the Red Skulls. Now you are in big trouble.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 36, 'panic_5', 'Yes! My friends are here to punish you. Wait! Why are they targeting me?'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 37, 'quest_disable_d', 'Once the Freighter is located, disable it by targetting the freighter''s engines or other sub-systems in order to bring it to a complete hault.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 38, 'quest_disable_t', 'Disable the Red Skull Freighter'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 39, 'quest_escort_d', 'Follow the freighter back to Imperial space. It is highly possible that the Red Skulls will try to recapture or destroy the freighter rather then to let it passively fall into Imperial hands. Be alert and ready to defend your prize.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 40, 'quest_escort_t', 'Escort the Red Skull Freighter'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 41, 'quest_location_d', 'The Red Skulls have stationed themselves in the Endor system. The transports are attempting to leave this system for parts unknown. You need to intercept these freighters before they can leave the area.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 42, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 43, 'quest_recover_d', 'Move in close to the disabled freighter and wait for the capture operation to begin. You have been supplied a program that will automatically reconfigure the freighters Nav computer to only accept coordinates sent in by Imperial Flight Control. This process may take a few minutes to begin.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 44, 'quest_recover_t', 'Capture the Red Skull Freighter'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 45, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 46, 'recovery_success', 'Excellent job, pilot. That ship was vitial to the Emperor''s plans for this system. Report back to your commanding officer.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 47, 'target_disabled', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Targets engines disabled. Begin docking procedures.>'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 48, 'taunt_1', 'If we can''t have that freighter, no one can.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 49, 'taunt_2', 'You are good, but not good enough.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 50, 'taunt_3', 'I have a perdiction that in the end you are going to be nothing more then space junk.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 51, 'taunt_4', 'You don''t actually think you can win, do you?'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 52, 'taunt_5', 'It''s time for me to show you what I can do.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 53, 'thanks_1', 'Next time, Imperial dog. Next time.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 54, 'thanks_2', 'More will come and they will rescue me this time.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 55, 'thanks_3', 'You should just leave before more of my friends show up.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 56, 'thanks_4', 'I have an idea. I will split my cargo with you...how does that sound?'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 57, 'thanks_5', 'You are just making them mad.'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 58, 'title', 'Endor System: Capture the Red Skull Freighter Duty'),
('string/en/spacequest/recovery_duty/tatooine_imperial_tier4_recoveryduty_1.stf', 59, 'title_d', 'The Empire wants the property that the Red Skulls have hijacked from its freighters in the Endor system. You are to intercept the Red Skull transports, capture them, and escort them back to Imperial space.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 2, 'abort', 'The hijacked freighter has been abandoned.  This mission is a wash.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 3, 'angry_disable', ''),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 4, 'arrival_phase_1', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 Prepare for the arrival of the freighter \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 5, 'arrival_phase_2', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 The freighter is in zone.  Don''t mess this up rookiee. \\#pcontrast3 > '),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 6, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 7, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy activity has stopped. \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 8, 'capture_complete', '\\#pcontrast3 Smuggler Alliance: < \\#pcontrast1 The freighter is ours, lets get out of here. \\#pcontrast3 >'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 9, 'capture_phase_1', 'Systems malfunction. Command systems overridden.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 10, 'capture_phase_1_1', 'System Capture In Progress'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 11, 'capture_phase_1_2', 'System Capture In Progress'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 12, 'capture_phase_1_3', 'Won''t somebody save me!'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 13, 'capture_phase_1_4', 'Won''t somebody save me!'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 14, 'capture_phase_1_5', 'Won''t somebody save me!'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 15, 'capture_phase_2', 'Capture is complete.  Proceeding to egress path.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 16, 'capture_phase_2_1', 'Capture is complete.  Proceeding to egress path.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 17, 'capture_phase_2_2', 'Capture is complete.  Proceeding to egress path.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 18, 'capture_phase_2_3', 'I am almost finished!'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 19, 'capture_phase_2_4', 'I am almost finished!'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 20, 'capture_phase_2_5', 'I am almost finished!'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 21, 'capture_started', 'Tactical Computer: < Capture preceedings have begun. >'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 22, 'complete', 'Capture Complete'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 23, 'complete_1', 'Capture Complete'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 24, 'complete_2', 'Capture Complete'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 25, 'complete_3', 'It is done.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 26, 'complete_4', 'It is done.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 27, 'complete_5', 'It is done.'),
('string/en/spacequest/recovery_duty/tatooine_privateer_5.stf', 28, 'escort_remaining', 'Tactical Comptuer: < An escorting ship has been destroyed. %DI remain. >'),
