('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 14, 'capture_phase_2', 'We have control of the bridge, one of our guys is repairing the engines now!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 15, 'capture_phase_2_1', 'We have control of the bridge, one of our guys is repairing the engines now!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 16, 'capture_phase_2_2', 'I''m in the pilot seat now and we''re getting the ship up and running, hold on.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 17, 'capture_phase_2_3', 'Time to get out of here, this ship is ours!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 18, 'capture_phase_2_4', 'Rebel? We are in control here, doing the final repairs of the ship and then we''re ready to move out.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 19, 'capture_phase_2_5', 'Freedom, here we come! We''re almost ready to get the heck out of here pilot.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 20, 'capture_started', 'Rebel Command: < The virus is unlocking the cells, wait for the prisoners to take control of the vessel and then escort them out of there. >'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 21, 'complete', 'We are in your debt Rebel, we won''t forget this.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 22, 'complete_1', 'We are in your debt Rebel, we won''t forget this.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 23, 'complete_2', 'I can almost taste the Jawa juice in my home cantina. We''re home free boys!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 24, 'complete_3', 'This guy deserve a standing ovation boys, I think we''re safe!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 25, 'complete_4', 'I thought my days would end in an Imperial prison. We are very grateful my friend.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 26, 'complete_5', 'I think that''s it everyone, we''re out of here! Thanks again Rebel!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 27, 'escort_remaining', 'Rebel Command: < Good job, take out all of the escort fighters! >'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 28, 'escort_wiped_out', 'Rebel Command: < Great, that should make the rest of this mission a breeze! >'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 29, 'failed_destroy', 'We lost the prison ship, abort the mission!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 30, 'failed_escape', 'The prison ship slipped away, this mission is over.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 31, 'panic_1', 'I wish this piece of junk had some weapons!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 32, 'panic_2', 'Bubble boys heading our way!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 33, 'panic_3', 'I was hoping that they were busy elsewhere but I guess not.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 34, 'panic_4', 'Hang on boys, the Empire doesn''t want us to leave just yet!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 35, 'panic_5', 'TIE fighters! Shouldn''t be a problem for you right? Right?'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 36, 'quest_disable_d', 'Use your targeting computer ([ or ] by default) to disable the prison transports engines or reactor.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 37, 'quest_disable_t', 'Disable prison transport.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 38, 'quest_escort_d', 'Quickly escort the prison transport out of the area. The Empire has undoubtedly called for reinforcements so be prepared to come under attack.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 39, 'quest_escort_t', 'Escort prisoners to safety.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 40, 'quest_location_d', 'The Dathomir system is highly guarded by the Empire. It seems they want no one to gain access to its hospitable planet, or be allowed to leave it. They have one of their high security prisons on the planet it''s guarded like it was the Emperors palace.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 41, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 42, 'quest_recover_d', 'The prisoners have broken free and are trying to gain control of the transport. Ensure their safety from enemy ships in the meantime.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 43, 'quest_recover_t', 'Prisoners break free.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 44, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 45, 'recovery_success', 'Great job pilot, the prisoners are safe. One of our shuttles will pick them up.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 46, 'target_disabled', 'Tactical Computer: < Sensors indicate target vessel disabled. >'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 47, 'taunt_1', 'Sometimes I think you Rebels have gone mad. Did you think we''d just let you fly out of here?'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 48, 'taunt_2', 'So that''s what the Rebels do now a days, free convicted prisoners. Well I guess you''re all the same.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 49, 'taunt_3', 'Just when I thought Rebels couldn''t get any dumber, you pull a stunt like this.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 50, 'taunt_4', 'You''re in violation of so many Imperial laws that I''ll do our judges a favor and never let you make the courtroom.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 51, 'taunt_5', 'Your joyride ends here fools!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 52, 'thanks_1', 'Haha, did you see that guys? They didn''t know what hit ''em!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 53, 'thanks_2', 'That''s right! Cream those suckers!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 54, 'thanks_3', 'I wish I was out there, it''s not right that you get to have all the fun!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 55, 'thanks_4', 'Yeah! Bring ''em on! We got the super pilot of doom covering our back!'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 56, 'thanks_5', 'I''m glad he''s on our side guys.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 57, 'title', 'Dathomir system: Duty mission: Rescue prisoners from the Empire.'),
('string/en/spacequest/recovery_duty/tatooine_rebel_tier4_1.stf', 58, 'title_d', 'Your orders are to intercept prison ships in the Dathomir system to try and break free captured Rebels and the wrongfully convicted. We have equipped your ship with a probe that can hack the onboard computer to open the prison cells on the Imperial transport. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 1, 'abort', 'Hey! What are you doing? You''re supposed to escort us out of here!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 2, 'angry_disable', 'Wh..what is going on here?!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 3, 'arrival_phase_1', 'Alright, one of our infiltrated crews has contacted me and they are ready to take control. Uploading coordinates to you now.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 4, 'arrival_phase_2', 'You should have the coordinates now, get over there and disable that freighter so our boys can take control of it.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 7, 'capture_complete', 'Hutt Pirate Captain: < Our boys are in control. Escort them to safety pilot. >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 8, 'capture_phase_1_1', 'It''s party time boys!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 9, 'capture_phase_1_2', 'Let''s take this piece of junk.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 10, 'capture_phase_1_3', 'Alright we''re starting the fun, we''ll let you know when we''re in control pilot.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 11, 'capture_phase_1_4', 'The freighter will be ours in a flash, stand by pilot.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 12, 'capture_phase_1_5', 'Boys, the ship is disabled, let''s knock out the crew and get out of here.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 13, 'capture_phase_2_1', 'Alright pilot, we''re in control and repairing the ship now.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 14, 'capture_phase_2_2', 'We got it pilot. Working on getting the ship running now, give us a few more seconds.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 15, 'capture_phase_2_3', 'The freighter is ours, piece a cake. Escort us out of here pilot.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 16, 'capture_phase_2_4', 'The freighter crew put up little resistance, as expected. We''ll be rolling out of here in a few seconds.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 17, 'capture_phase_2_5', 'We did our part, now it''s up to you to take us safely out of here pilot.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 18, 'capture_started', 'Tactical Computer: < Sensors show laser fire onboard target vessel. >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 19, 'complete', 'We''re fine from here. Not too bad pilot, see you around!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 20, 'escort_remaining', 'Hutt Pirate Captain: < Good job pilot! Taking out the escort will ensure the safety of our men on the freighter. >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 21, 'escort_wiped_out', 'Hutt Pirate Captain: < Very nice, continue as planned, pilot. >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 22, 'failed_destroy', 'Some of our best men were on that ship! You better have a good explanation for this pilot!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 23, 'failed_escape', 'Bah, the freighter hyperspaced out of the system. We don''t pay pilots for incompetence so don''t expect a reward.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 24, 'panic_1', 'I wish this piece of junk had some weapons, I don''t like feeling helpless.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 25, 'panic_2', 'Time to earn your pay pilot, we got bogeys incoming.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 26, 'panic_3', 'Looks like we got company, brace yourself boys.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 27, 'panic_4', 'Hmm, I don''t like the look of those fighters that just popped up on our sensors.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 28, 'panic_5', 'This is the part I hate, stuck in a useless freighter while my escort has all the fun.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 29, 'quest_disable_d', 'The Hutt pirates have infiltrated the freighter with some of their pirates. Disable it so that they can take over the ship. In order to disable it you need to target and destroy its reactor or engines. To target specific components on a star ship, input the bracket commands ( ] or [ ) to your tactical computer.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 30, 'quest_disable_t', 'Disable the freighter.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 31, 'quest_escort_d', 'The pirates are in control and need a escort to safety. Follow the freighter and be ready to defend it from hostile fighters picking up on your activity.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 32, 'quest_escort_t', 'Get out of there!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 33, 'quest_location_d', 'The Tatooine system is a haven for the scum of the galaxy. Pirates, smugglers and mercenaries flock to the system and prey on the weak. Stay sharp out there and treat everyone as a possible threat.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 34, 'quest_location_t', 'Tatooine system.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 35, 'quest_recover_d', 'The Hutt pirates are starting to take over the freighter, in the way that only they can. While they are busy onboard the freighter make sure to keep it safe from nearby enemies.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 36, 'quest_recover_t', 'Pirate brawl.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 37, 'quest_update', 'Hutt Pirate Captain: < %TO >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 38, 'recovery_success', 'Not too bad pilot, I guess we owe you some pay for that.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 39, 'target_disabled', 'Tactical Computer: < Scans show target vessel disabled. >'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 40, 'taunt_1', 'Stand down and we may let you live!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 41, 'taunt_2', 'End of the line I''m afraid.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 42, 'taunt_3', 'You''re not leaving with that freighter, sorry.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 43, 'taunt_4', 'You blasted Hutt scum think you can do what you please around here. Well think again!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 44, 'taunt_5', 'Pirate fools, did you really think we would just let you fly out of here?'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 45, 'thanks_1', 'Hahaha, awesome work pilot!'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 46, 'thanks_2', 'Yeah! Looks like we hired the right pilot this time.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 47, 'thanks_3', 'This pilot has some skill! Wouldn''t you agree boys?'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 48, 'thanks_4', 'Well, I guess I can just turn on the autopilot. Looks like you got it covered out there pilot'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 49, 'thanks_5', 'Me and the boys will just continue our Sabacc game now, you seem to be able to handle yourself out there pilot.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 50, 'title', 'Tatooine system: Duty mission: Assist the Hutts in capturing freighters.'),
('string/en/spacequest/recovery_duty/tatooine_station_hutt_recovery_duty_tier1_1.stf', 51, 'title_d', 'Jabba, the Hutt crime lord of Tatooine is hiring pilots in the Tatooine system to assist him in capturing freighters with valuable merchandise. Follow the instructions in the mission closely, you don''t want to fail Jabba once he''s hired your services.'),
('string/en/spacequest/recovery_duty/test_recovery_duty.stf', 1, 'Quest Log Data', 'Text'),
