('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 2, 'abort', 'You better have a good reason for aborting in the middle of this Rebel!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 3, 'angry_disable', 'We will have our revenge, mark my words!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 4, 'arrival_phase_1', 'Okay Rebel. We have some men aboard a Corsair ship that should arrive any moment now.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 5, 'arrival_phase_2', 'The Corsair fools are here. Intercept and disable their engines Rebel!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 6, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 7, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 8, 'attack_update', 'Tactical Computer: < Sensors show armed fighter vessels on intercept course. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 9, 'capture_complete', 'Tactical Computer: < Scans show target vessel self repairing and powering up. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 10, 'capture_phase_1', 'Time to show these Corsair numbnuts who they are dealing with!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 11, 'capture_phase_1_1', 'Time to show these Corsair numbnuts who they are dealing with!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 12, 'capture_phase_1_2', 'Party time boys! Shoot ''em down!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 13, 'capture_phase_1_3', 'For Lord Nym!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 14, 'capture_phase_1_4', 'To the bridge! No prisoners!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 15, 'capture_phase_1_5', 'Making our way to the bridge, these Corsairs won''t know what hit ''em!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 16, 'capture_phase_2', 'This will be a breeze, half the crew were drunk!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 17, 'capture_phase_2_1', 'This will be a breeze, half the crew were drunk!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 18, 'capture_phase_2_2', 'Arrrgh! Keep fighting boys!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 19, 'capture_phase_2_3', 'Take this, weakling Corsairs!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 20, 'capture_phase_2_4', 'Kicking down the door to the bridge now. Muahahaha!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 21, 'capture_phase_2_5', 'Hey! That one is still alive!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 22, 'capture_started', 'Nym Pirate Officer: < Their ship is disabled. Our men will fight to the bridge, hold tight Rebel. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 23, 'complete', 'Well, we''re out of here. Not bad for a Rebel, not bad at all!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 24, 'complete_1', 'Well, we''re out of here. Not bad for a Rebel, not bad at all!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 25, 'complete_2', 'Alright, we''re safe. Time to party boys!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 26, 'complete_3', 'This will do fine. Good job out there Rebel!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 27, 'complete_4', 'What can I say, you got the job done Rebel. See ya!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 28, 'complete_5', 'Stop by Nym''s casino for a drink later pilot, it''s on me!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 29, 'escort_remaining', 'Tactical Computer: < Sensors still show armed fighter vessels in immediate area. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 30, 'escort_wiped_out', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 31, 'failed_destroy', 'Crap! What happened Rebel? We lost contact with our guys!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 32, 'failed_escape', 'The Corsair snakes escaped! Oh well, plenty more where they came from!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 33, 'hull_half', 'Aww crap mate, we''re loosing hull pressure here. Get those fools of us!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 34, 'panic_1', 'Incoming Corsairs. Show us what you can do Rebel!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 35, 'panic_2', 'I guess they didn''t want us to take their ship!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 36, 'panic_3', 'Your show now Rebel, take those fools out!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 37, 'panic_4', 'I guess they want their ship back. Well they can''t have it!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 38, 'panic_5', 'Hopefully you''re good Rebel, we got company!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 39, 'quest_disable_d', 'Disable the engines or reactor of the Corsair ship so that the Nym pirates on board can take control of the vessel. To target specific components on a star ship, input the bracket commands ( ] or [ ) to your tactical computer.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 40, 'quest_disable_t', 'Disable the Corsair ship.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 41, 'quest_escort_d', 'Escort the stolen ship to safety and be prepared for Corsair counter attacks.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 42, 'quest_escort_t', 'Escort the bounty.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 43, 'quest_location_d', 'The Corsair have been the biggest threat to Nym ruling Lok for many years, but so far, Nym has prevailed. Stealing the ships of the Corsair will wage the war even more in the favor of Nym, so it''s one of his favorite hobbies.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 44, 'quest_location_t', 'Lok system.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 45, 'quest_recover_d', 'The Nym pirates are wreaking havoc on board the Corsair ship. In the meantime you should protect it from any outside threats.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 46, 'quest_recover_t', 'Arrgh.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 47, 'quest_update', 'Nym Pirate Officer: < %TO >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 48, 'recovery_success', 'We got the ship. Great job Rebel, ever considered a career in piracy?'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 49, 'shields_depleted', 'Alright, we just lost our shields. Hand me that bottle man!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 50, 'target_disabled', 'Tactical Computer: < Scans show target vessel disabled. >'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 51, 'taunt_1', 'What the heck do you think you''re doing to our ship?!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 52, 'taunt_2', 'Nym''s and Rebel''s, you''re all fools!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 53, 'taunt_3', 'My head, I knew I shouldn''t have had that last bottle yesterday...'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 54, 'taunt_4', 'Finally a good fight, take it to ''em boys!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 55, 'taunt_5', 'Well well, what do we have here? Nym fools and Rebel scum getting all cozy, we can''t have that!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 56, 'thanks_1', 'Whow! I guess Rebels know how to fly after all!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 57, 'thanks_2', 'That''s it! If I didn''t know better, I''d think you were one of us Rebel!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 58, 'thanks_3', 'Sit back and enjoy the show boys, this pilot is not bad!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 59, 'thanks_4', 'You owe me 50 creds guys, I told you he would make it!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 60, 'thanks_5', 'Boom! That''s it Rebel, bring it to ''em!'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 61, 'title', 'Lok system: Duty mission: Steal Corsair ships.'),
('string/en/spacequest/recovery_duty/viopa_rebel_7.stf', 62, 'title_d', 'Nym has asked us for a favor in their war against the Corsair pirates. They have infiltrated some of the Corsair ships and need you to disable and escort them. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
