('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 37, 'panic_5', 'Sensors show incoming fighter vessels with armed weapons systems.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 38, 'quest_disable_d', 'Disable the Imperial ship so that the space assault droid can take control of the ship. To target specific components on a star ship, input the bracket commands ( ] or [ ) to your tactical computer.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 39, 'quest_disable_t', 'Disable the Imperial vessel.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 40, 'quest_escort_d', 'Escort the stolen ship to the safety of our base. The Empire will not let you leave unscathed if they can prevent it so be ready for everything.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 41, 'quest_escort_t', 'Escort stolen ship.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 42, 'quest_location_d', 'The Imperial navy heavily outnumber the Alliance in the Yavin system so we need to be smart in our approach here. Stealing Imperial ships is a small victory everytime as it weakens the Empire and make us stronger. Be careful out there pilot.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 43, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 44, 'quest_recover_d', 'The droid is now working on taking control of the ship. Protect it from Imperial fighters until the droid is done.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 45, 'quest_recover_t', 'Let the droid do its magic.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 46, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 47, 'recovery_success', 'The ship is ours, on it''s way to one of our space docks right now. Excellent work pilot!'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 48, 'target_disabled', 'Tactical Computer: < Scans show target vessel disabled. Transferring droid model IG-31-V to target vessel. >'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 49, 'taunt_1', 'You have broken multiple Imperial laws. Surrender or face the consequences.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 50, 'taunt_2', 'You Rebel scum think you can do as you please around here. Well it ends now!'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 51, 'taunt_3', 'Rebel fool! You think we would just let you fly out of here with one of our ships?'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 52, 'taunt_4', 'I hope you didn''t expect to come back from this mission Rebel?'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 53, 'taunt_5', 'The might of the Empire will crush you like the bug you are, Rebel fool!'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 54, 'thanks_1', 'Sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 55, 'thanks_2', 'Sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 56, 'thanks_3', 'Sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 57, 'thanks_4', 'Sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 58, 'thanks_5', 'Sensors show area clear of hostile fighter vessels. Continuing flight on planned escape path.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 59, 'title', 'Yavin system: Duty mission: Steal Imperial ships.'),
('string/en/spacequest/recovery_duty/yavin_rebel_12.stf', 60, 'title_d', 'To level the war against the Empire a bit more we have decided to try and steal some of their fighter ships. They will also prove useful in infiltration and terror attacks against the Imperial fleet. Your ship is armed with an automated space assault droid that will take control of the enemy ship once you have disabled it. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 1, 'abort', 'You have aborted, I will self destruct now. You lose.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 2, 'arrival_phase_1', 'Getting waypoint for rescue target.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 3, 'arrival_phase_2', 'Rescue target has arrived, proceed to position.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 4, 'assigned_delayed', 'Rescue a transport in peril.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 5, 'attack_notify', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 6, 'attack_stopped', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 10, 'complete', 'The rescue is complete.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 11, 'docking_complete', 'Docking is complete.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 12, 'docking_started', 'The docking process has started.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 13, 'failed_destroy', 'You have failed due to the rescue target being destroyed.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 14, 'panic_1', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 15, 'panic_2', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 16, 'panic_3', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 19, 'quest_dock_d', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 20, 'quest_dock_t', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 21, 'quest_escort_d', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 22, 'quest_escort_t', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 23, 'quest_location_d', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 24, 'quest_location_t', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 25, 'quest_update', '%TO'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 26, 'recovery_success', 'The recovery was a success.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 27, 'rescue_phase_1', 'You have begun docking.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 28, 'rescue_phase_2', 'You have ended docking.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 29, 'split_quest_alert', 'Split quest incoming.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 30, 'taunt_1', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 31, 'taunt_2', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 32, 'taunt_3', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 33, 'taunt_4', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 34, 'taunt_5', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 35, 'thanks_1', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 36, 'thanks_2', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 37, 'thanks_3', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 38, 'thanks_4', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 39, 'thanks_5', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 40, 'title', 'Rescue freighter'),
('string/en/spacequest/rescue/corellia_imperial_tier3_2c.stf', 41, 'title_d', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 2, 'abort', 'Where are you going? I thought that I had information HQ wanted?'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 3, 'arrival_phase_1', 'Getting nav location of the damaged freighter. We believe it knows the location of the Rebel emissary to Nym in this system. Stand by.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 4, 'arrival_phase_2', 'We have the location. Assist freighter with repairs and escort it back to HQ.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 11, 'complete', 'The pilot of the freighter informs us that the emissary is in the area and was part of the joint attack force that hit his vessel.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 12, 'docking_complete', 'Freighter attempting to restart engines. Stand by to escort it to safety.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 13, 'docking_started', 'Freighter is attempting to initiate repairs. Stand by.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 14, 'failed_destroy', 'We needed that ship in one piece. Hopefully we will get another chance to discover the location of the Rebel emissary. Report back to your commander.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 15, 'panic_1', 'I knew they would be back. Cover me!'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 16, 'panic_2', 'They have come back to finish the job!'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 17, 'panic_3', 'Look out! The enemy is upon us.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 18, 'panic_4', 'I hope you are a better pilot then they are.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 19, 'panic_5', 'Enemy fighters! They are not going to let me get away.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 20, 'quest_dock_d', 'When you arrive at the freighter''s location, target it, and use the /dock command in order to assist the freighter with repairs.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 21, 'quest_dock_t', 'Assist the Freighter With Repairs'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 22, 'quest_escort_d', 'Once the Imperial freighter is repaired, follow it to its destination. Keep on guard, since this weakened prey will certainly draw the enemies attention.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 23, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 24, 'quest_location_d', 'Travel to the Yavin system and assist the damaged Imperial freighter with repairs. You will receive a navigation waypoint to the damaged freighter''s location. Travel to that waypoint to meet up with the freighter.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 25, 'quest_location_t', 'Travel to the Yavin System'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 26, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 27, 'recovery_success', 'Freighter is away. Good work pilot. Stand by while we question the pilot.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 28, 'rescue_abandoned', 'Where are you going? I thought that I had information HQ wanted?'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 29, 'rescue_phase_1', 'Good to see you. I was hit by both rebel and Nym fighters. It looked like there was a Rebel command vessel coordinating the attack.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 30, 'rescue_phase_2', 'Engines are back online. Hopefully we will not see any more of those joint attacks like the one that hit me.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 31, 'split_quest_alert', 'The freighter captain gave us a good idea of where to look for the Rebel emissary. Stand by while we preform long range scans for his vessel.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 33, 'taunt_1', 'Looks like the Imperial dog is trying to escape.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 34, 'taunt_2', 'Resistance will get you no where.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 35, 'taunt_3', 'Give up and you will not be hurt.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 36, 'taunt_4', 'Time to pay for your villiany.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 37, 'taunt_5', 'Looks like the Imperial dog is trying to escape.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 38, 'thanks_1', 'Wow, you are better then you look.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 39, 'thanks_2', 'I certainly feel safer with you watching my back.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 40, 'thanks_3', 'Thanks, pilot. I am glad I am on your side.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 41, 'thanks_4', 'I certainly feel safer with you watching my back.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 42, 'thanks_5', 'Wow, you are better then you look.'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 43, 'title', 'Yavin System: Rescue the Imperial Freighter'),
('string/en/spacequest/rescue/corellia_imperial_tier3_3.stf', 44, 'title_d', 'Travel to the Yavin system and rescue a damaged Imperial freighter. Once inside the system, you will receive a navigation waypoint to the freighter''s location. The freighter is damged and currently unable to move. You will need to travel to the freighter location and assist it with repairs. When you reach the freighter, target it and use the /dock command to assist it with repairs. Once the freighter is repaired, escort it through the system.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 2, 'abort', 'You can''t just leave us out here...'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 3, 'arrival_phase_1', 'Getting a lock on the last know position of the drop shuttle. Stand by to intercept.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 4, 'arrival_phase_2', 'Proceed to the location provided your navigation computer. Scans indicate that the ship is badly damaged and under heavy attack.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 6, 'attack_notify', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 7, 'attack_stopped', '\\#pcontrast1Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 11, 'complete', 'The drop ship has been safely returned to Imperial space. We must find those responsible. Stand by.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 12, 'docking_complete', 'They are attempting to restart their engines now. Stand by to escort ship out of the area.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 13, 'docking_started', 'Beginning docking procedure. Assist in repairs to the best of your ability.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 14, 'failed_destroy', 'That ship was a valuable piece of equipment. You were to protect it and not let the enemy destroy it. Report back to your commander immediately.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 15, 'panic_1', 'Keep them off of us! We cannot take much punishment.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 16, 'panic_2', 'At least I do not see that fighter leader.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 17, 'panic_3', 'It could be worse. That lead fighter pilot could come back.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 18, 'panic_4', 'At least I do not see that fighter leader.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 19, 'panic_5', 'Keep them off of us! We cannot take much punishment.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 20, 'quest_dock_d', 'Dock with the drop ship and assist it any way you can.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 21, 'quest_dock_t', 'Assist the Imperial Drop Ship with Repairs'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 22, 'quest_escort_d', 'Follow the drop ship on it''s way to the seconday jump location. Protect it against any attacks that might come in.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 23, 'quest_escort_t', 'Escort the Imperial Drop Ship'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 24, 'quest_location_d', 'Somehow the vessel was pulled out of hyperspace and attacked by the mercs before it could leave the Dathomir system.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 25, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 26, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 27, 'recovery_success', 'The drop ship is safe. Stand by for further instructions.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 28, 'rescue_abandoned', 'You can''t just leave us out here...'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 29, 'rescue_phase_1', 'We are glad to see you. They were all over us and then scrambled out of there just before you arrived. We wouldn''t have survived another second without you showing up.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 30, 'rescue_phase_2', 'Thank you, pilot. We will be restarting our engines now. Oh, one more thing, the leader of the fighters that disabled us was an amazing pilot. Thought maybe he might be someone we are looking for.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 31, 'split_quest_alert', 'You are to patrol the area looking for any signs of the enemy fighters. Any officer that you come across is to be disabled and inspected. Insurgent seemed most interested in the shuttle pilot''s discription of the fighter leader.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 33, 'taunt_1', 'Nej''a will be so proud of us when you are no more.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 34, 'taunt_2', 'Nej''a told us that you would try to save that ship. '),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 35, 'taunt_3', 'I am surprised Nej''a didn''t want to take care of you himself.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 36, 'taunt_4', 'Ok boys, looks like we have a live on here. Let''s change that!'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 37, 'taunt_5', 'Nej''a knew you couldn''t resist playing the hero. Time to die, Imperial dog.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 38, 'thanks_1', 'I bet Nej''a is that amazing pilot who attacked us earlier.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 39, 'thanks_2', 'Do you think Nej''a is the leader?'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 40, 'thanks_3', 'Nej''a? I wonder if he is that amazing pilot.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 41, 'thanks_4', 'Maybe we should get out of here before that Nej''a guy shows up.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 42, 'thanks_5', 'No offense, but if Nej''a is that pilot I saw earlier we should really get out of here.'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 43, 'title', 'Dathomir System: Rescue the Imperial Drop Ship'),
('string/en/spacequest/rescue/corellia_imperial_tier4_3_a.stf', 44, 'title_d', 'Remain in the Dathomir system and assist the Imperial drop ship with repairs. The drop ship has been hit by the enemy before it could completely get out of the system. The first wave managed to temporarily disable the vessel and scans indicate a second wave moving in. Meet the disabled vessel, assist it with repairs, and protect it while it moves towards the secondary jump location.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 1, 'abort', 'What are you doing pilot?! If I survive this I will have you incarcerated!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 2, 'arrival_phase_1', 'A Rebel diplomat and his retinue were ambushed by some Imperial fighters and is drifting in space, they need our help.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 3, 'arrival_phase_2', 'Get over to their location before an Imperial Shuttle reach him. Transfer some spare part so they can fix their ship.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 5, 'attack_notify', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 10, 'complete', 'Too bad about the Inquisitor but the day wasn''t a complete loss. Return to base.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 11, 'docking_complete', 'They got the spare parts. As soon as they are up and running, escort them out of there.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 12, 'docking_started', 'I''m sure that the Empire left some fighters in the area so dock and transfer those spare parts quickly.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 13, 'failed_destroy', 'We lost contact with the diplomats vessel! You can''t seem to get anything right today can you pilot? Return to base immediately!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 14, 'panic_1', 'Me and my crew are not fighters! The evil Empire has no honor!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 15, 'panic_2', 'Not more of them!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 16, 'panic_3', 'I guess trying to talk to them would be pointless?'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 17, 'panic_4', 'I''m starting to get really angry. We have not done anything to warrant this!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 18, 'panic_5', 'You''d think they have something better to do!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 19, 'quest_dock_d', 'Dock with the diplomats ship and transfer over tools and spare parts so they can repair their engines. Defend them from any enemies while they are repairing their ship.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 20, 'quest_dock_t', 'Dock with diplomat ship.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 21, 'quest_escort_d', 'The Empire have undoubtedly spotted you by now and will send fighters to try and disable or destroy the diplomats ship. Escort him to safety.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 22, 'quest_escort_t', 'Escort the diplomat to safety.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 23, 'quest_location_d', 'Be careful on your way to the diplomats vessel and try not to attract more enemy presence. You need to still keep a good speed though as that Imperial shuttle is closing in to capture the diplomat.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 24, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 25, 'quest_update', 'Worvog Arkon: < %TO >'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 26, 'recovery_success', 'They will be safe from here pilot. Good job.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 27, 'rescue_abandoned', 'What are you doing pilot?! If I survive this I will have you incarcerated!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 28, 'rescue_phase_1', 'We are so glad to see you pilot! Who knows what might have happened to us if you weren''t here.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 29, 'rescue_phase_2', 'We have the spare parts. Our technician says he will have our ship running in no time.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 30, 'split_quest_alert', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 32, 'taunt_1', 'You are not going anywhere Rebels!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 33, 'taunt_2', 'Cut your engines immediately or we will destroy you!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 34, 'taunt_3', 'That man is wanted for questioning, surrender now or we have no choice but to destroy you.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 35, 'taunt_4', 'You are all known Rebels, if you don''t stop immediately, we have the right to terminate you.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 36, 'taunt_5', 'The great Empire wants the people on that ship for questioning, or dead, it''s your choice!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 37, 'thanks_1', 'All this senseless killing...'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 38, 'thanks_2', 'I guess it was us or them eh?'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 39, 'thanks_3', 'You think they would give up after all those casaulties..'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 40, 'thanks_4', 'I hope they get the picture and leave us alone, this is madness!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 41, 'thanks_5', 'Please let that be the last of them...'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 42, 'title', 'Dathomir system: Rescue the Rebel diplomat.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_2_b.stf', 43, 'title_d', 'We have received a distress call from one of our diplomats near to you. Him and his retinue was ambushed by Imperial fighters and are floating around in space with disabled engines while an Imperial Shuttle is closing in to capture them. Hurry over there and transfer repair hardware to them.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 1, 'abort', 'Aborting eh? Well you can forget about the information then.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 2, 'arrival_phase_1', 'Just a second, transmitting the location of the SpyNet agents vessel.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 3, 'arrival_phase_2', 'Get over there quickly and transfer over the spare parts he need. From the information he gave us, the Empire is still chasing him.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 10, 'complete', 'Thanks Rebel. I guess I owe you this data for free. Good luck!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 11, 'docking_complete', 'Okay, now escort him to safety and he will give us the route of the Imperial freighters, that was the deal.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 12, 'docking_started', 'I''ve transmitted a list of what spare parts he need to your astromech, it will take care of it.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 13, 'failed_destroy', 'Damnation! That was our last chance. Return to base immediately, we need to come up with a new plan.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 14, 'panic_1', 'I knew they wouldn''t give up.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 15, 'panic_2', 'They really don''t want me to share this information with anyone.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 16, 'panic_3', 'I''m not much of a fighter pilot so I hope you''re good.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 17, 'panic_4', 'Hostiles gunning for us!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 18, 'panic_5', 'Here they come, get ready.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 19, 'quest_dock_d', 'If you are certain that the surrounding area is clear of enemy presence, dock with the spy and transfer repair materials to him.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 20, 'quest_dock_t', 'Dock with the spy.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 21, 'quest_escort_d', 'Escort the spy to safety. Once he''s safe he will provide us with the route of the Imperial freighter.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 22, 'quest_escort_t', 'Get out safely.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 23, 'quest_location_d', 'The Endor system is crawling with Imperial fighters and the area where the spy is drifting is especially dangerous. Try to sneak by Imperial patrols but if it can''t be avoided, dispatch of them quickly. Under no circumstance are you to lead them to the location of the spy.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 24, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 25, 'quest_update', 'Worvog Arkon: < %TO >'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 26, 'recovery_success', 'Alright, the spy is safe and transmitted the route information.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 27, 'rescue_abandoned', 'Aborting eh? Well you can forget about the information then.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 28, 'rescue_phase_1', 'Glad to see you Rebel. Lets dock so I can get this thing fixed.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 29, 'rescue_phase_2', 'All done. Now if you get me out of here safely, I will transmit the information you need.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 30, 'split_quest_alert', 'Worvog Arkon: < The Imperial fleet is almost leaving the Endor sector. You''re closest so get over there fast and start the attack! >'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 32, 'taunt_1', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 33, 'taunt_2', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 34, 'taunt_3', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 35, 'taunt_4', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 36, 'taunt_5', ''),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 37, 'thanks_1', 'Phew, close one.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 38, 'thanks_2', 'Get me out of here now!'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 39, 'thanks_3', 'I have a feeling there will be more of them.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 40, 'thanks_4', 'Lets not linger around here and wait for more of them to arrive.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 41, 'thanks_5', 'You''re good Rebel, I''ll give you that.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 42, 'title', 'Endor system: Rescue the spy.'),
('string/en/spacequest/rescue/corellia_rebel_tier4_4_b.stf', 43, 'title_d', 'We got a second chance in stopping the Imperial freighter carrying station building materials to Lok. A SpyNet operative have contacted the Alliance. He was ambushed by the Empire but got away. He took heavy damage though and his ship have malfunctioned. If we help him, he will give up the freighters route. Hurry over to his location and transfer some repair tools to his ship, then escort him to safety.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 1, 'abort', 'What? You can''t leave us like this. You can be sure I''ll notify CorSec command...'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 2, 'arrival_phase_1', 'We are tracking the distress call to the originating vessel. Stand by for coordinates.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 3, 'arrival_phase_2', 'Transmitting coordinates now. Investigate the situation and assist with standard repair procedures.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Warning. Unidentified enemy craft inbound.\\#pcontrast1 >'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Enemy threat neutralized.\\#pcontrast1 >'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 10, 'complete', 'Good work, pilot. Return to the station for debriefing.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 11, 'docking_complete', 'Copy that, pilot. Acknowledge docking procedure complete.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 12, 'docking_started', 'We copy, pilot. Acknowledge initiation of docking procedure. Execute standard repair procedures.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 13, 'failed_destroy', 'Command is not happy with you, pilot. Return to the station for debriefing.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 14, 'panic_1', 'Those are the ships! Those are the ships that attacked us!'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 15, 'panic_2', 'More of those fighters! What do they want?'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 16, 'panic_3', 'More fighters! Show them who''s boss, CorSec!'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 17, 'panic_4', 'MORE of those ships? What''s going on here?'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 18, 'panic_5', 'We can''t take much more, CorSec. Please help us.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 19, 'quest_dock_d', 'When you arrive at the freighter''s location, target it and use the /dock command to dock with the vessel and assist with repairs.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 20, 'quest_dock_t', 'Assist the Freighter With Repairs'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 21, 'quest_escort_d', 'The freighter is repaired, but is not operating at full capabilities. You must escort the ship while it makes hyperspace calculations and prepares to jump. The freighter is extremely vulnerable during this period, so keep a sharp eye out.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 22, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 23, 'quest_location_d', 'Travel to the Corellia system. Once there, you will receive a navigation waypoint from CorSec command. Travel to the waypoint to meet with the disabled freighter.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 24, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 25, 'quest_update', '\\#pcontrast1 CorSec Command: <\\#pcontrast3  %TO\\#pcontrast1  >'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 26, 'recovery_success', 'Freighter hyperspace jump confirmed.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 27, 'rescue_abandoned', 'What? You can''t leave us like this. You can be sure I''ll notify CorSec command...'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 28, 'rescue_phase_1', 'Thank you for your help, CorSec. We were attacked, but never boarded. Something funny is going on here.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 29, 'rescue_phase_2', 'Systems are operational. That''ll be good enough to get us back home.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 30, 'split_quest_alert', ''),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 32, 'taunt_1', 'Just as we planned. Your days are numbered, CorSec.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 33, 'taunt_2', 'CorSec is so predictable. You will fall, just like all the rest.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 34, 'taunt_3', 'You cannot resist helping those in need, can you. Now you will be defeated.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 35, 'taunt_4', 'Nice of you to join us, CorSec. Good-bye.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 36, 'taunt_5', 'Meddlesome CorSec. Right on time.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 37, 'thanks_1', 'CorSec was right to send a pilot like you on this job.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 38, 'thanks_2', 'I''ve never seen ship configurations like that before. I wonder who they are?'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 39, 'thanks_3', 'Great work, pilot. You have our eternal gratitude.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 40, 'thanks_4', 'Whew, I was worried there for a minute.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 41, 'thanks_5', 'Hopefully they stay gone this time.'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 42, 'title', 'Corellia System: Rescue the Merchant Freighter'),
('string/en/spacequest/rescue/corellia_station_mission1_1.stf', 43, 'title_d', 'CorSec command has received a distress call on emergency channels. A merchant freighter has fallen under attack and is in need of assistance. You must travel to the location provided by CorSec command and assist with the repairs. The freighter is currently disabled and is unable to move. When you have arrived at the vessel, target it and use the /dock command to dock with the ship and assist with repairs. You must then escort the freighter until it is able to make its hyperspace calculations and jump safely.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 1, 'abort', 'I see you triggered your abort code. Good idea...save yourself.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 2, 'arrival_phase_1', 'We are sending you the last known location of the colonels ship. Stand by.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 3, 'arrival_phase_2', 'Proceed to the following coordinates. Recover the colonel at all costs.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 5, 'attack_notify', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 6, 'attack_stopped', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 10, 'complete', 'Nice work, pilot. '),
('string/en/spacequest/rescue/imperial_ss_03.stf', 11, 'docking_complete', 'Docking completed. Please stand by.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 12, 'docking_started', 'Docking procedure initiated. Stand by.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 13, 'failed_destroy', 'The colonel''s ship has been destroyed. We wanted him back to us in one piece, pilot. Report to your superior officer immediately.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 14, 'panic_1', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 15, 'panic_2', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 16, 'panic_3', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 19, 'quest_dock_d', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 20, 'quest_dock_t', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 21, 'quest_escort_d', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 22, 'quest_escort_t', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 23, 'quest_location_d', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 24, 'quest_location_t', ''),
('string/en/spacequest/rescue/imperial_ss_03.stf', 25, 'quest_update', 'Imperial High Command:<%TO>'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 26, 'recovery_success', 'Something isn''t right here! His jump coordinates were away from Imperial control space. Report to your superior for debreifing.'),
('string/en/spacequest/rescue/imperial_ss_03.stf', 27, 'rescue_abandoned', ''),
