('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 2, 'abort', 'What are you doing? We cannot hold out without your support.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 3, 'arrival_phase_1', 'Retreiving last known location of the shuttle. Stand by.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 4, 'arrival_phase_2', 'We are sending the location of the shuttle to your nav computer. Proceed to that location immediately and rescue our ship.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.>'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
