('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 11, 'complete', 'The shuttle is safe. Nice work, pilot.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 12, 'docking_complete', 'Docking procedure completed. Stand by to escort shuttle out of danger area.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 13, 'docking_started', 'Beginning docking procedure. Stand by.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 14, 'failed_destroy', 'Pilot, the shuttle has been destroyed. Return to your superior and make a full report.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 15, 'panic_1', 'Where are all these Rebels coming from?'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 16, 'panic_2', 'Look out! There are more of them out there.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 17, 'panic_3', 'My ship can''t take many hits. You better be good.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 18, 'panic_4', 'Why me? All I wanted was a nice quite flight.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 19, 'panic_5', 'Where are all these rebels coming from?'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 20, 'quest_dock_d', 'When you arrive at the shuttle''s location, target it, and use the /dock command in order to assist the shuttle with repairs.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 21, 'quest_dock_t', 'Assist the Shuttle with Repairs'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 22, 'quest_escort_d', 'Once the Imperial Lambda shuttle is repaired, follow it to its destination. Keep on guard! Because this shuttle is weakened prey, it will certainly draw the enemy''s attention.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 23, 'quest_escort_t', 'Escort the Shuttle'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 24, 'quest_location_d', 'Remain in the Dathomir system and assist the damaged Imperial Lambda shuttle with repairs. You will receive a navigation waypoint of the damaged shuttle''s location. Travel to that waypoint to meet up with the shuttle.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 25, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 26, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 27, 'recovery_success', 'The shuttle is beginning jump procedure. Stand by until it is safely out of the system.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 28, 'rescue_abandoned', 'What are you doing? We cannot hold out without your support.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 29, 'rescue_phase_1', 'I am really glad to see you. I don''t know how much longer I could have held out.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 30, 'rescue_phase_2', 'Ok, we are all hooked up. Let''s try to get out of here.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 31, 'split_quest_alert', 'We believe that we located a command ship. During that fight we detected encrypted signals being sent to the fighters. We want whatever information that ship might have.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 33, 'taunt_1', 'You will not make it out of here alive!'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 34, 'taunt_2', 'The Alliance will never let you escape.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 35, 'taunt_3', 'Time to pay for your crimes, Imperial dog.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 36, 'taunt_4', 'The galaxy doesn''t need you kind around.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 37, 'taunt_5', 'I almost feel sorry for what I am about to do to you.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 38, 'thanks_1', 'You really saved us! Thanks for your help.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 39, 'thanks_2', 'You really saved us! Thanks for your help.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 40, 'thanks_3', 'You really saved us! Thanks for your help.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 41, 'thanks_4', 'You really saved us! Thanks for your help.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 42, 'thanks_5', 'You really saved us! Thanks for your help.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 43, 'title', 'Dathomir System: Rescue the Lambda Shuttle'),
('string/en/spacequest/rescue/naboo_imperial_tier3_3_b.stf', 44, 'title_d', 'Remain in the Dathomir system and rescue a damaged Imperial Lambda shuttle. Once inside the system, you will receive a navigation waypoint to the shuttle''s location. The shuttle is damaged and currently unable to move. You will need to travel to the shuttle''s location and assist it with repairs. When you reach the shuttle, target it and use the /dock command to assist it with repairs. Once the shuttle is repaired, escort it through the system.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_4_a.stf', 1, 'abort', 'Pilot! What are you doing...get back here! We cannot survive without your protection.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_4_a.stf', 2, 'arrival_phase_1', 'We are taking heavy fire. Get here on the double.'),
('string/en/spacequest/rescue/naboo_imperial_tier3_4_a.stf', 3, 'arrival_phase_2', 'I don''t know how much longer we can hold out. Get here right away.'),
