('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 14, 'failed_destroy', 'You were ordered to get that ship back to us in one piece. If you are unable to handle your assignments perhaps you should retire.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 15, 'panic_1', 'Those are the same fighters that hit me earlier.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 16, 'panic_2', 'I saw a massive number of those same ships just before I was attacked.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 17, 'panic_3', 'Looks like the same Coynite''s that hit me earlier.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 18, 'panic_4', 'They really don''t want me to report back about what I discovered.'),
