('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 23, 'quest_escort_t', 'Escort the Recon Shuttle'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 24, 'quest_location_d', 'The distress signal is coming from inside the Dathomir system. A navigation waypoint to its location will be supplied to you.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 25, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 26, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 27, 'recovery_success', 'Good job, pilot. You are really making a name for yourself.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 28, 'rescue_abandoned', 'We are going to be at the mercy of our enemies without you. Your commander will hear of this failure.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 29, 'rescue_phase_1', 'Good to see a friendly out here.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 30, 'rescue_phase_2', 'Engines back online. We will be underway shortly.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 31, 'split_quest_alert', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters incoming at attack speeds with weapons armed.>'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 33, 'taunt_1', 'We are back to finish the job.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 34, 'taunt_2', 'This is going to be too easy. Where is the challenge?'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 35, 'taunt_3', 'My brothers and I shall sings songs of your demise.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 36, 'taunt_4', 'Contact your next of kin.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 37, 'taunt_5', 'What? How dare you! That''s it! Time to be vaporized.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 38, 'thanks_1', 'Good to have you on our side. I will report on the massing of Coynite mercs in the region to our superiors.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 39, 'thanks_2', 'Good to have you on our side. I will report on the massing of Coynite mercs in the region to our superiors.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 40, 'thanks_3', 'Good to have you on our side. I will report on the massing of Coynite mercs in the region to our superiors.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 41, 'thanks_4', 'Good to have you on our side. I will report on the massing of Coynite mercs in the region to our superiors.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 42, 'thanks_5', 'Good to have you on our side. I will report on the massing of Coynite mercs in the region to our superiors.'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 43, 'title', 'Dathomir System: Rescue the Recon Shuttle'),
('string/en/spacequest/rescue/naboo_imperial_tier4_2_a.stf', 44, 'title_d', 'A distress signal has gone out from a recon shuttle. Apparently the Coynite mercenaries that attacked you also attacked this other vessel. The shuttle is damaged but still functional. The Coynite apparently broke off their attack on it in order to rescue the smuggler you captured. Assist the shuttle and escort it to safety.'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 2, 'abort', '\\#pcontrast3 Madersim: < \\#pcontrast1 Where are you going, we cannot survive without you! \\#pcontrast3 >');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 3, 'arrival_phase_1', '\\#pcontrast3 RSF Command: < \\#pcontrast1 We are locking down the Madersims'' position.  Stand-by. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 4, 'arrival_phase_2', '\\#pcontrast3 Madersim: < \\#pcontrast1 This is the RSF Madersim, we just escaped a heavy attack. Quickly dock to assist with repairs! \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 6, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 7, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 The attack has stopped. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 11, 'complete', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The Madersim has successfully made their jump to hyperspace.  They are safe to complete their mission.  Time for you to return to base pilot. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 12, 'docking_complete', 'Docking is complete, quick repairs beginning.'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 13, 'docking_started', 'Docking process has begun. '),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 14, 'failed_destroy', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The Madersim has been destroyed, this is horrible. Return to base. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 15, 'panic_1', 'This is not looking very well. '),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 16, 'panic_2', 'More Ay''Nat!'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 17, 'panic_3', 'Protect us Captain, please!'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 18, 'panic_4', 'This is not looking very well. '),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 19, 'panic_5', 'This is not looking very well. '),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 20, 'quest_dock_d', 'Pull up next to the Madersim and use the /dock command'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 21, 'quest_dock_t', 'Docking'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 22, 'quest_escort_d', 'Escort the repaired transport out of the zone'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 23, 'quest_escort_t', 'Escort'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 24, 'quest_location_d', 'The secret escort route of the RSF Madersim'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 25, 'quest_location_t', 'Corellia System'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 26, 'quest_update', '%TO'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 27, 'recovery_success', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The mission is complete, return to base.  And great job out there today. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 28, 'rescue_abandoned', 'Mission aborted, you fail.'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 29, 'rescue_phase_1', '\\#pcontrast3 Madersim: < \\#pcontrast1 Hurry with those repairs, we need to get underway. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 30, 'rescue_phase_2', '\\#pcontrast3 Madersim: < \\#pcontrast1 The repairs are sufficient to go, lets get out of here. \\#pcontrast3 >'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 31, 'split_quest_alert', ''),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 33, 'taunt_1', 'You will not survive this!'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 34, 'taunt_2', 'We will finish you now!'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 35, 'taunt_3', 'RSF Slime.'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 36, 'taunt_4', 'You will not survive this!'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 37, 'taunt_5', 'You will not survive this!'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 38, 'thanks_1', 'Thank you for getting us out in once piece. '),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 39, 'thanks_2', 'That was close Captain, you arrived just in time.'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 40, 'thanks_3', 'I think it is a good day to retire.'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 41, 'thanks_4', 'Thank you for getting us out in once piece. '),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 42, 'thanks_5', 'Thank you for getting us out in once piece. '),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 43, 'title', 'Corellia System: Rescue the RSF Madersim'),
('string/en/spacequest/rescue/naboo_privateer_tier3_2e.stf', 44, 'title_d', 'Rescue the RSF Madersim which is listing in space'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 1, 'abort', 'Pilot! Get back here! I will report you to your superior for failing your mission!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 2, 'arrival_phase_1', 'Uploading coordinates of Commander Kt''lya''s crippled ship now, stand by.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 3, 'arrival_phase_2', 'Upload complete, get over there quickly pilot. Dock with him and transfer some spare parts so he can repair his ship.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 10, 'complete', 'Mission complete. Proceed with objectives. Good work, pilot!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 11, 'docking_complete', 'Docking complete.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 12, 'docking_started', 'Stand by. Proceeding with docking ...'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 13, 'failed_destroy', 'Mission failed! Commander Kt''lya''s vessel was destroyed.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 14, 'panic_1', 'Pilot! Pay attention! I''m under fire! Get them off my tail!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 15, 'panic_2', 'They''re on me! Get these bastards off me!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 16, 'panic_3', 'I''ve been hit! Get these vessels off me!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 19, 'quest_dock_d', 'Dock with the commanders ship and transfer over some spare parts so he can get his ship running again.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 20, 'quest_dock_t', 'Repair the commanders ship.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 21, 'quest_escort_d', 'Make haste out of the area together with the commander. Make sure that he makes it out safely.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 22, 'quest_escort_t', 'Escape!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 23, 'quest_location_d', 'Although the first attack of the Blacklight pirates were beaten, they are still present in the area and there''s bound to be several of them surrounding the place where the SpyNet commander was attacked.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 24, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 25, 'quest_update', 'Vortex Commander: < %TO >'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 26, 'recovery_success', 'Brother Ezkiel: < Good work, pilot. The commander is now safe. Proceed with further objectives. >'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 27, 'rescue_abandoned', 'Pilot! Get back here! I will report you to your superior for failing your mission!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 28, 'rescue_phase_1', 'Hurry! We have no time to just sit here!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 29, 'rescue_phase_2', 'Good, good. Let''s get out of here!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 30, 'split_quest_alert', 'Brother Ezkiel: < Good work, pilot. We need you to patrol the perimeter for anymore enemy ships. >'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 32, 'taunt_1', 'We could have just captured you, now we will destroy you!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 33, 'taunt_2', 'Attack pattern bloodfang, annihilate them!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 34, 'taunt_3', 'Take ''em out boys!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 35, 'taunt_4', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 36, 'taunt_5', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 37, 'thanks_1', 'Whew! Thanks, pilot. It was getting close there for a second!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 38, 'thanks_2', 'That was close! Thanks, pilot. I''m glad to be on your team.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 39, 'thanks_3', 'It''s about time you showed up!'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 40, 'thanks_4', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 41, 'thanks_5', ''),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 42, 'title', 'Dantooine system: Rescue Commander Kt''lya.'),
('string/en/spacequest/rescue/naboo_rebel_tier3_2_a.stf', 43, 'title_d', 'One of the SpyNet officers have been attacked and disabled. We need you to rescue him before the Blacklight pirates get a shuttle over there to capture him.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 1, 'abort', 'What the.. we''re not done here yet!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 2, 'arrival_phase_1', 'Alright, uploading the coordinates of our spies disabled ship.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 3, 'arrival_phase_2', 'Proceed quickly to the location pilot. The Inquisitions frigate is closing in on him.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 5, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 6, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 10, 'complete', 'Good work pilot, stand by for further orders.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 11, 'docking_complete', 'So far so good. Take the spy to safety pilot.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 12, 'docking_started', 'Dock with our operative and transfer the repair tools to his ship.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 13, 'failed_destroy', 'Damnation! We lost our operative! Stand by...'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 14, 'panic_1', 'I guess they have given up on the idea of capturing me alive.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 15, 'panic_2', 'Wish I had a real ship and not this piece of junk.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 16, 'panic_3', 'Here they come, lets give them a warm welcome.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 17, 'panic_4', 'Sensors picking up hostile fighters.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 18, 'panic_5', 'I wonder if there''s a tracker on this ship, they seem to know our exact location.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 19, 'quest_dock_d', 'Dock with the spies ship and transfer the spare parts and repair tools. Defend his ship while he''s performing the repairs.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 20, 'quest_dock_t', 'Dock and transfer repair material.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 21, 'quest_escort_d', 'Escort our spy while he''s calculating his jump to lightspeed.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 22, 'quest_escort_t', 'Escort the spy to safety.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 23, 'quest_location_d', 'The Dathomir system is always dangerous, even for hardened veterans like yourself. No one but the most elite of pilots (or the most dumb but they are in minority and wont live for long) go here, which makes it a hostile environment indeed.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 24, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 25, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 26, 'recovery_success', 'He''s safe from there, good job pilot.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 27, 'rescue_abandoned', 'What the.. we''re not done here yet!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 28, 'rescue_phase_1', 'Good to see you pilot, thought this would be my last mission.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 29, 'rescue_phase_2', 'Alright, I should be up and running in a few seconds.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 30, 'split_quest_alert', 'Brother Extok Evin: < Our reconnaissance ship reports that an Inquisitor is getting ready to hyperspace after our spy, you must stop him! >'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 31, 'split_quest_alert_fail', 'Brother Extok Evin: < Ack, we have lost contact with our operative. The brave soul didn''t go in vain though, he managed to transfer most of his data to your ship before his demise. Stand by. >'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 32, 'taunt_1', 'You''re not going anywhere Rebel fools!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 33, 'taunt_2', 'No one escapes the Imperial Inquisition!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 34, 'taunt_3', 'You know your orders men, if we can''t capture them, we destroy them!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 35, 'taunt_4', 'Waging war on the Inquisition is suicide you Rebel scum!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 36, 'taunt_5', 'You can''t win this battle Rebels, surrender now and we will show mercy!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 37, 'thanks_1', 'Well we showed them, didn''t we?'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 38, 'thanks_2', 'Take that you filthy scum!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 39, 'thanks_3', 'No one captures Trova Ruaw, no one!'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 40, 'thanks_4', 'Whow, you are good pilot, very good.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 41, 'thanks_5', 'Alright, lets not stick around and wait for more.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 42, 'title', 'Dathomir system: Save a Vortex operative.'),
('string/en/spacequest/rescue/naboo_rebel_tier4_3.stf', 43, 'title_d', 'One of our spies have had a malfunction on his ship and is drifting through Dathomir space with the Inquisition quickly closing in on him. You need to get to him fast with repair materials and escort him to safety.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 1, 'abort', 'Why are you doing this to us? We''re so close to going home!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 2, 'arrival_phase_1', 'Listen closely, pilot. Soon, I will transmit the data needed to find our downed freighter. It is your job to rescue it and fly it home to safety.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 3, 'arrival_phase_2', 'The freighter has come in range of our detection sensors. Travel there and rescue it before it''s too late. Please, pilot. We needn''t lose any more lives to this frivolous mess. I expect you to do well.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 10, 'complete', 'Phenomenal job, my friend! I knew we could count on you! Your mission is complete.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 11, 'docking_complete', 'Good, pilot. Now, our men will re-capture the freighter and guide it back home. However, you must protect it from incoming Zynt''aia pirate attacks. No doubt, they''ll try to destroy the freighter now that we''ve rescued it.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 12, 'docking_started', 'Be still, pilot. Our men are boarding now, hoping to re-capture the freighter. Stick close.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 13, 'failed_destroy', 'Your mission is lost, pilot! The freighter has been destroyed. It was a hard task. Understood. We must mourn for the loss of our crew.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 14, 'panic_1', 'Look alive, pilot! They''re coming at us hard!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 15, 'panic_2', 'Oof! Help us! We''re getting attacked!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 16, 'panic_3', 'That''s gonna hurt! Hey pilot! Are you taking the scenic route or something? Get back here and help us!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 19, 'quest_dock_d', 'I must find the disabled Darksing D-45 and dock with it once I''ve found it. I can do this by getting close and enabling the docking proceedures. (Use the /dock command to dock with the freighter).'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 20, 'quest_dock_t', 'Dock with the Darksing D-45'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 21, 'quest_escort_d', 'Once I''ve completed the docking proceedures with the Darksing D-45, I must escort it to safety. I have no doubt I''ll be attacked along the way by the Zynt''aia Order. I must prepare myself.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 22, 'quest_escort_t', 'Escort the Darksing D-45 to Safety'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 23, 'quest_location_d', 'I must remain in the Tatoo System for my mission. It is my directive to do so.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 24, 'quest_location_t', 'Remain the Tatoo System'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 25, 'quest_update', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 26, 'recovery_success', 'Good work, pilot. The freighter is on its way home. I''m very impressed by the way you''ve handled yourself.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 27, 'rescue_abandoned', 'We''re so close, pilot! Don''t quit on us!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 28, 'rescue_phase_1', 'Finally!! We''re saved!! You must have been sent by A''Lerris!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 29, 'rescue_phase_2', 'We''ve got out systems on-line again. We''ll follow you closely. Keep enemies off us. We''re still pretty weak!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 30, 'split_quest_alert', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 32, 'taunt_1', 'You''ll never capture this freighter!!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 33, 'taunt_2', 'Never upset the Zynt''aia Order. You''ll never win!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 34, 'taunt_3', 'It''s time to taste anger!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 35, 'taunt_4', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 36, 'taunt_5', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 37, 'thanks_1', 'Thank you for that, pilot! I''m glad we have you on our side.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 38, 'thanks_2', 'That was really close. Your flying skills are unmatched!'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 39, 'thanks_3', 'Excellent! It makes me glad that you''re on our side in this conflict.'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 40, 'thanks_4', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 41, 'thanks_5', ''),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 42, 'title', 'Tatoo System: Darksing D-45 Crew'),
('string/en/spacequest/rescue/poi_tatooine_general2_2_b.stf', 43, 'title_d', 'While eliminating the Zynt''aia influence in the mining field located close to A''Lerris'' outpost, I received a distressful call from Miss Verata herself. It seems that one of her freighters has been captured by the Zynt''aia Order. It is my duty to travel to its known location and rescue it from the hands of her--now "our"--enemies. I expect the resistance I meet to be extensive and dangerous. I can only hope I make it out alive with the freighter and its crew intact.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 1, 'abort', 'We really need you help. Our life support systems are failing...'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 2, 'arrival_phase_1', 'Disabled freighter on scans. Stand by for update.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 3, 'arrival_phase_2', 'Freighter located. Proceed with rescue operation.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 5, 'attack_notify', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 6, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 10, 'complete', 'Good work, you have found our missing freighter. You can tell the Dantooine station that we will pick up its contract.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 11, 'docking_complete', 'Repairs completed. Freighter start up sequence underway.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 12, 'docking_started', 'Beginning repairs. Stand by.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 13, 'failed_destroy', 'Freighter destroyed. We are not going to help anyone who doesn''t help us first.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 14, 'panic_1', 'Who are those guys?'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 15, 'panic_2', 'Hey...I heard about these nut jobs.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 16, 'panic_3', 'Why would they want me?'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 17, 'panic_4', 'So, first I get hit by an asteroid and disabled and now this...'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 18, 'panic_5', 'Hmmmm...maybe being disabled wasn''t so bad.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 19, 'quest_dock_d', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 20, 'quest_dock_t', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 21, 'quest_escort_d', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 22, 'quest_escort_t', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 23, 'quest_location_d', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 24, 'quest_location_t', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 25, 'quest_update', 'Twin Star Shipping: < %TO >'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 26, 'recovery_success', 'The freighter is back. Good work.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 27, 'rescue_abandoned', 'You are doing what? Well then forget our deal.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 28, 'rescue_phase_1', 'Oh, wow...we thought we were done for. Thanks for finding us.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 29, 'rescue_phase_2', 'Ok, looks like we should be ready to go in just a moment. Thanks again for your help, friend.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 30, 'split_quest_alert', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 32, 'taunt_1', 'You belong to us now!'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 33, 'taunt_2', 'Prepare to become one with the great debris field.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 34, 'taunt_3', 'I thank you for the gift that you are about to give.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 35, 'taunt_4', 'May the great fireball forgive you for your sins.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 36, 'taunt_5', 'Only those who believe shall ever leave the field.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 37, 'thanks_1', 'Who were those guys? They are crazy!'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 38, 'thanks_2', 'I guess they will start worshipping some of their own junk now.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 39, 'thanks_3', 'That will teach them.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 40, 'thanks_4', 'This place is nuts...I am getting out of here.'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 41, 'thanks_5', 'I think they had one to many...'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 42, 'title', 'Yavin System: Rescue the Disabled Freighter'),
('string/en/spacequest/rescue/stn_dantooine_owner_all_repairmission_tier2_6.stf', 43, 'title_d', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 1, 'abort', 'I am not hanging around here with no escort.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 2, 'arrival_phase_1', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Searching for the transports distress beacon... stand by.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 3, 'arrival_phase_2', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Distress signal located.  Target location locked in. \\#pcontrast3 >'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 5, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 6, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile actions have ceased. \\#pcontrast3 >'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 7, 'autorewardbody', 'Completion Bonus: Deliverance (5000)'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 8, 'autorewardfrom', 'Endor Station'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 9, 'autorewardsubject', 'Deliverance'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 10, 'complete', 'The transport is away.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 11, 'docking_complete', 'Docking process is complete.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 12, 'docking_started', 'Docking process has begun.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 13, 'failed_destroy', '\\#pcontrast3 Endor Staion: < \\#pcontrast1 Oh, this is most terrible. \\#pcontrast3 >'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 14, 'panic_1', 'Here they come again.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 15, 'panic_2', 'More Rebels coming.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 16, 'panic_3', 'I have seen this before.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 19, 'quest_dock_d', 'Target the transport and use the /dock command to initiate the repair procedure.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 20, 'quest_dock_t', 'Dock'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 21, 'quest_escort_d', 'Escort the Transport safely to their jump point in the Naboo system and Rendezvous with them in Endor to complete the mission.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 22, 'quest_escort_t', 'Escort'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 23, 'quest_location_d', 'The transport dropped out of Hyperspace early after an emergency jump to escape from the Rebel attack craft.  Location will be updated when you are in range of their distress signal.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 24, 'quest_location_t', 'Naboo System'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 25, 'quest_update', '%TO'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 26, 'recovery_success', '\\#pcontrast3 Endor Station: < \\#pcontrast1 The transport has informed us they made the jump from the Naboo System. Their destination point is near the Area D-435 hyperspace point in the Endor System.  Meet them there and finish bringing them into the station. \\#pcontrast3 >'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 27, 'rescue_abandoned', 'This is why the empire is a worse place for working with mercenaries.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 28, 'rescue_phase_1', 'Interlocks engaged, begining engine jumpstart sequence now.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 29, 'rescue_phase_2', 'Emergency startup is complete, lets get out of here Captain.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 30, 'split_quest_alert', '\\#pcontrast3 Endor Station: < \\#pcontrast1 The transport is away.  Hyperspace to the Endor System, navpoint Area D-435 to make the rendezvous here and complete the mission. \\#pcontrast3 >'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 32, 'taunt_1', 'This time there will be no escape.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 33, 'taunt_2', 'I knew we would find you nearby.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 34, 'taunt_3', 'Your friend there will be no help to you.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 35, 'taunt_4', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 36, 'taunt_5', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 37, 'thanks_1', 'Excellent.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 38, 'thanks_2', 'Not so viscious now that there is a ship with guns firing back.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 39, 'thanks_3', 'Just a bit longer then we will make the jump.'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 40, 'thanks_4', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 41, 'thanks_5', ''),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 42, 'title', 'Naboo System: Deliverance'),
('string/en/spacequest/rescue/stn_endor_irs_imp_tier3_1a.stf', 43, 'title_d', 'An  Imperial Transport bearing weapons for the Imperial Research Station on Endor has been badly damaged in an escape from rebel pilots.  Track down the freighter with the provided homing waypoint and get them back underway to the station.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 1, 'abort', 'What are you doing out here? That''s right, just keep flying.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 2, 'arrival_phase_1', 'Gaining lock on the starship signature. Stand by.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 3, 'arrival_phase_2', 'Ship locked. Ship is bearing the markings of the Corellia Deep Mining Company.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 5, 'attack_notify', 'Tactical Computer: < Enemy fighters detected. >'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 6, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 10, 'complete', 'Corellia Deep Mining Co. is obviously suppling these fake Massassi. They obviously are attempting to drive the Yavin Mining Company out of the system.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 11, 'docking_complete', 'Docking procedure completed. Transfered supplies for the Corellia Deep Mining Co. to your vessel.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 12, 'docking_started', 'Beginning docking procedure. Stand by.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 13, 'failed_destroy', 'Corellia Deep Mining Co. ship destroyed.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 14, 'panic_1', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 15, 'panic_2', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 16, 'panic_3', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 19, 'quest_dock_d', 'The vessel is offering you payment, thinking that you are part of the mercenaries it hired to pretend to be Massassi. Dock with the vessel and take the payment.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 20, 'quest_dock_t', 'Pickup the Payment'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 21, 'quest_escort_d', 'Wait at your current location until the vessel leaves the area.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 22, 'quest_escort_t', 'Wait Until the Vessel Leave'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 23, 'quest_location_d', 'The current location of the ship is near your present position.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 24, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 25, 'quest_update', '\\#FF0000 Flight Computer:\\#FF0000 < %TO >'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 26, 'recovery_success', 'Corellia Deep Mining Co. ship preparing to make the jump to hyper space.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 27, 'rescue_abandoned', 'What are you doing out here? That''s right, just keep flying.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 28, 'rescue_phase_1', 'They told me that you wouldn''t be flying anything normal but I didn''t quite expect you to be in that ship. Whatever...I have the supplies you need.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 29, 'rescue_phase_2', 'Ok there you go. Remember keep the pressure on the those creeps and they will eventually fold operations.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 30, 'split_quest_alert', 'Incoming enemy fighters detected. These are obviously the ships that were supposed to be picking up the supplies. Destroy them before they can report your presence.'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 32, 'taunt_1', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 33, 'taunt_2', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 34, 'taunt_3', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 35, 'taunt_4', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 36, 'taunt_5', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 37, 'thanks_1', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 38, 'thanks_2', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 39, 'thanks_3', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 40, 'thanks_4', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 41, 'thanks_5', ''),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 42, 'title', 'Yavin System: Investigate the Corellia Deep Mining Co. Vessel'),
('string/en/spacequest/rescue/stn_yavin4_company_all_massassi_tier2_9.stf', 43, 'title_d', 'A ship bearing the Corellia Deep Mining Company logo has been spotted in the area. They have no operations this far out and should be investigated.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 1, 'abort', 'Yeah, that''s right Imperial scum. Run away.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 2, 'arrival_phase_1', 'You have arrived at the meeting location. We are sending out a warning for the vessel to be stopped for a search.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 3, 'arrival_phase_2', 'The vessel has complied with our request. Dock and start the inspection of the vessel.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 5, 'attack_notify', 'Tactical Computer: < Enemy fighters incoming. >'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 6, 'attack_stopped', 'Tactical Computer: < Enemy fighters eliminated. >'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 10, 'complete', 'The vessel had the location of the head of the smuggling operation. Stand by to capture the responsible party.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 11, 'docking_complete', 'The search should be concluded momentarily. Stand by.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 12, 'docking_started', 'Starting the search of the vessel. Stand by for further instructions.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 13, 'failed_destroy', 'You let that vessel be destroyed? We needed that ship to find out more about the smuggling operation.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 14, 'panic_1', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 15, 'panic_2', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 16, 'panic_3', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 19, 'quest_dock_d', 'Dock with the freighter and look for information about the head of the smuggler operation.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 20, 'quest_dock_t', 'Dock with the Freighter'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 21, 'quest_escort_d', 'Throw the back the small fish now in order to catch the big fish later.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 22, 'quest_escort_t', 'Let the Freighter Leave'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 23, 'quest_location_d', 'Meet the contact freighter in the Corellia system.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 24, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 25, 'quest_update', 'Imperial Command: < %TO >'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 26, 'recovery_success', 'Are you done. I hope you found what you were looking for.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 27, 'rescue_abandoned', 'I told you that I didn''t have anything you wanted.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 28, 'rescue_phase_1', 'Fine, you can search my ship. I have nothing to hide.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 29, 'rescue_phase_2', 'See I had nothing that would interest you.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 30, 'split_quest_alert', 'Stand by for further information about the location of the head of the smuggling operation, Polard Manfred. Bring this smuggler into custody.'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 32, 'taunt_1', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 33, 'taunt_2', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 34, 'taunt_3', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 35, 'taunt_4', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 36, 'taunt_5', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 37, 'thanks_1', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 38, 'thanks_2', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 39, 'thanks_3', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 40, 'thanks_4', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 41, 'thanks_5', ''),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 42, 'title', 'Space Corellia: Meet the Smuggler'),
('string/en/spacequest/rescue/stn_yavin4_imp_imperial_tier2_2.stf', 43, 'title_d', 'The information gathered from the vessel attempting to leave the Yavin system revealed that there is a large smuggling operation taking place in the Corellia system. Travel to Corellia and meet with the vessel that was supposed to be the freighters contact.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 1, 'abort', 'Don''t leave us here! Didn''t you say you''d help us?'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 2, 'arrival_phase_1', 'Hang on, pilot. We''ve got reports of a distress call from one of our freighters in your area...'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 3, 'arrival_phase_2', 'Here''s a waypoint to the freighter, looks like they need some help. Fly to the area and check it out. Assist the freighter with repairs if necessary.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 5, 'attack_notify', 'Tactical Computer: < Enemy craft inbound. Pirate signatures detected. >'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 6, 'attack_stopped', 'Tactical Computer: < Enemy threat neutralized. >'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 10, 'complete', 'The freighter is away and headed back to the station. You''ll need to make their last delivery run to Naboo for them.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 11, 'docking_complete', 'Critical repairs to the freighter are complete. Escort them while they make preparations to jump to hyperspace.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 12, 'docking_started', 'The freighter will need to return to base. They are going to load their last shipment into your cargo bay.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 13, 'failed_destroy', 'That didn''t work exactly the way that we planned. We''re scrapping the rest of your assignments. Return to the station if you want to try again.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 14, 'panic_1', 'Fighters incoming! Watch out!'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 15, 'panic_2', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 16, 'panic_3', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 17, 'panic_4', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 18, 'panic_5', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 19, 'quest_dock_d', 'Travel to the freighter''s location and move in close. Dock with the ship using the /dock command to provide assistance with repairs and to load the freighter''s cargo onto your ship.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 20, 'quest_dock_t', 'Assist With Repairs'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 21, 'quest_escort_d', 'You will need to escort the freighter while it makes hyperspace calculations to return to base.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 22, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 23, 'quest_location_d', 'The freighter is not far away from your location in the Tatooine system.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 24, 'quest_location_t', 'Remain in the Tatooine System'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 25, 'quest_update', 'Talus Station: < %TO >'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 26, 'recovery_success', 'Thanks for the help, pilot. Preparing for the jump to hyperspace.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 27, 'rescue_abandoned', 'Don''t leave us here! Didn''t you say you''d help us?'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 28, 'rescue_phase_1', 'Just in time. I didn''t think anyone was going to be able to help us.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 29, 'rescue_phase_2', 'Critical systems look stable. I think this should be enough to get us back to the station.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 30, 'split_quest_alert', 'Make the delivery to the Naboo system.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 31, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 32, 'taunt_1', 'Hey, that freighter is ours! We found it first!'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 33, 'taunt_2', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 34, 'taunt_3', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 35, 'taunt_4', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 36, 'taunt_5', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 37, 'thanks_1', 'Alright. Looks like we''re in the clear again. For now.'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 38, 'thanks_2', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 39, 'thanks_3', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 40, 'thanks_4', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 41, 'thanks_5', ''),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 42, 'title', 'Tatooine System: Assist the Talusian Freighter'),
('string/en/spacequest/rescue/talus_station_mission2_1.stf', 43, 'title_d', 'A nearby freighter from the Talus Space Station has fallen under attack and is need of assistance. You are the closest ship and have been requested to provide whatever help is necessary.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 2, 'abort', 'What? You have aborted the attack! We cannot last without your protection...'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 3, 'arrival_phase_1', 'Getting arrival location of the supply freighter. It looks like she was hit pretty hard. Once you get to her, dock with her, and assist with any repairs you can.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 4, 'arrival_phase_2', 'Current location of supply freighter sent to your nav computer. Help the supply freighter get under way and escort her to safety.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters detected.>'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 11, 'complete', 'The freighter is safe and sound. Nice work out there, pilot.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 12, 'docking_complete', 'Docking procedure completed.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 13, 'docking_started', 'Beginning docking procedure.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 14, 'failed_destroy', 'That freighter has been destroyed. Return to your superior and make a full report as to why you failed.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 15, 'panic_1', 'More Rebels! Like we haven''t had enough trouble.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 16, 'panic_2', 'Rebels are swarming all over Endor.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 17, 'panic_3', 'Look out! There are more of them out there.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 18, 'panic_4', 'Keep them off of us. We are already in bad shape.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 19, 'panic_5', 'Someone has to do something about this Rebel problem.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 20, 'quest_dock_d', 'When you arrive at the freighter''s location, target it, and use the /dock command in order to assist the freighter with repairs.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 21, 'quest_dock_t', 'Assist the Imperial Freighter with Repairs'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 22, 'quest_escort_d', 'Once the Imperial freighter is repaired, follow it to its destination. Keep on guard, since this weakened prey will certainly draw the enemies attention.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 23, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 24, 'quest_location_d', 'Remain in the Endor system and assist the damaged Imperial freighter with repairs. You will receive a navigation waypoint to the damaged freighter''s location. Travel to that waypoint to meet up with the freighter.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 25, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 26, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 27, 'recovery_success', 'Thanks, pilot. We have made it to our jump point. Please wait until we are clear.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 28, 'rescue_abandoned', 'What? You have aborted the attack! We cannot last without your protection...'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 29, 'rescue_phase_1', 'Thanks for the assistance. Those Rebs came out of nowhere and hit us from all sides. We were barely able to jump out in one piece. Hopefully they were not able to track us to here.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 30, 'rescue_phase_2', 'Well I guess that is going to have to do. Let''s get out of here.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 31, 'split_quest_alert', 'Imperial High Command wants that data you took off of that Rebel scout. Sending you navigation location for a pickup ship. Bring the data to this location and transfer it to the command shuttle.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 33, 'taunt_1', 'You will not get away with that freighter.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 34, 'taunt_2', 'Focus on the freighter. Take it out!'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 35, 'taunt_3', 'Imperial dog, you do not stand a chance.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 36, 'taunt_4', 'I suggest you find a new line of work.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 37, 'taunt_5', 'We are back to finish the job we started.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 38, 'thanks_1', 'Great job. Now let''s get this cargo to headquarters.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 39, 'thanks_2', 'Yes! Now let''s get out of here.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 40, 'thanks_3', 'I really hope more of them don''t show up.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 41, 'thanks_4', 'Why would they be so persistant? Unless they know what cargo I am carrying.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 42, 'thanks_5', 'This cannot be by chance that Rebels just keep showing up.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 43, 'title', 'Endor System: Rescue the Imperial Freighter'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_1_c.stf', 44, 'title_d', 'Remain in the Endor system and rescue a damaged Imperial freighter. Once inside the system, you will receive a navigation waypoint to the freighter''s location. The freighter is damaged and currently unable to move. You will need to travel to the freighter location and assist it with repairs. When you reach the freighter, target it and use the /dock command to assist it with repairs. Once the freighter is repaired, escort it through the system.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 2, 'abort', 'Pilot! What are you doing...get back here! We cannot survive without your protection.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 3, 'arrival_phase_1', 'We are taking heavy fire. Get here on the double.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 4, 'arrival_phase_2', 'I don''t know how much longer we can hold out. Get here right away.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters detected.>'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 8, 'autorewardbody', ''),
