('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 11, 'complete', 'Well done, pilot. You have proven yourself time and time again.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 12, 'docking_complete', 'Docking procedure completed.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 13, 'docking_started', 'Beginning docking procedure. Stand by.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 14, 'failed_destroy', 'Pilot you are to return to your superior immediately. The loss of that ship is a serious set back to the Empire. You have a lot of explaining to do.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 15, 'panic_1', 'More Rebels! Keep them off of us.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 16, 'panic_2', 'Be alert. It looks like we have attacking Rebels on our hands.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 17, 'panic_3', 'Be alert. It looks like we have attacking Rebels on our hands.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 18, 'panic_4', 'More Rebels! Keep them off of us.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 19, 'panic_5', 'More Rebels! Keep them off of us.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 20, 'quest_dock_d', 'Dock with the shuttle and assist it with repairs.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 21, 'quest_dock_t', 'Assist the Imperial Lambda Shuttle with Repairs'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 22, 'quest_escort_d', 'Follow the shuttle until it can reach a safe jump location. Be on the look out for enemy fighters coming to finish the shuttle off.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 23, 'quest_escort_t', 'Escort the Imperial Lambda Shuttle'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 24, 'quest_location_d', 'The shuttle is inside of the Endor system. A navigation waypoint will be supplied to you from the location of its distress signal.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 25, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 26, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 27, 'recovery_success', 'Well done! We should be in the clear now.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 28, 'rescue_abandoned', 'Pilot! What are you doing...get back here! We cannot survive without your protection.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 29, 'rescue_phase_1', 'Beginning to initiate repairs. We barely managed to get away from those Rebels in one piece.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 30, 'rescue_phase_2', 'Repairs completed. Escort us to a safe jump point.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 31, 'split_quest_alert', 'Stand by. We managed to pick up Rebel transmissions taking place while shuttle was under attack. Intercept and inspect that vessel for any information we can use against the Rebellion.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 33, 'taunt_1', 'We located your command vessel! Time for some payback.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 34, 'taunt_2', 'Nice try! Better luck next time.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 35, 'taunt_3', 'Your shuttle doesn''t stand a chance.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 36, 'taunt_4', 'We will find out what is going on around here.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 37, 'taunt_5', 'Don''t even try to stop us.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 38, 'thanks_1', 'Nice work, pilot. You are an asset to the Empire.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 39, 'thanks_2', 'Nice work, pilot. You are an asset to the Empire.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 40, 'thanks_3', 'Nice work, pilot. You are an asset to the Empire.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 41, 'thanks_4', 'Nice work, pilot. You are an asset to the Empire.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 42, 'thanks_5', 'Nice work, pilot. You are an asset to the Empire.'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 43, 'title', 'Endor System: Rescue the Imperial Lambda Shuttle'),
('string/en/spacequest/rescue/tatooine_imperial_tier3_4_a.stf', 44, 'title_d', 'The Rebels have attacked one of our command shuttles. The first wave of the Rebel fighters has crippled the shuttle and another wave of fighters is on its way. Travel to the shuttle, assist it with repairs, and help it escape.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 2, 'abort', 'We barely managed to make it back here in one piece and now you are just going to leave us?'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 3, 'arrival_phase_1', 'Scanning system for last known location of shuttle. The shuttle probably isn''t in good shape so once you get there help with repairs.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 4, 'arrival_phase_2', 'We located the shuttle and sent that to your nav computer. It is adrift and badly in need of repairs.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 6, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected.> \\#pcontrast3'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 7, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.> \\#pcontrast3'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 8, 'autorewardbody', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 9, 'autorewardfrom', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 10, 'autorewardsubject', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 11, 'complete', 'Nice work, pilot. Now we can find out where they took our other missing shuttles.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 12, 'docking_complete', 'Shuttle engines coming back online. Escort that shuttle back to headquarters for investigation.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 13, 'docking_started', 'Careful, pilot. That shuttle is very fragile and any slips at this point could mean disaster.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 14, 'failed_destroy', 'We needed that shuttle in one piece. Report back to your superior and explain your failure to him.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 15, 'panic_1', 'Rebels! They have been swarming this sector for days now.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 16, 'panic_2', 'Hold them off. We are still not at 100 percent.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 17, 'panic_3', 'Look out! Rebel fighters are attacking.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 18, 'panic_4', 'Rebels! They have weapon lock on my ship!'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 19, 'panic_5', 'Rebels! They have been swarming this sector for days now.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 20, 'quest_dock_d', 'Dock with the shuttle and assist it in repairing it''s damaged engines.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 21, 'quest_dock_t', 'Assist the Stolen Shuttle with Repairs'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 22, 'quest_escort_d', 'Once repaired, escort and protect the shuttle back to Imperial space.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 23, 'quest_escort_t', 'Escort the Stolen Shuttle'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 24, 'quest_location_d', 'The shuttle jumped in to the Endor system but then it''s engines went offline.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 25, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 26, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 27, 'recovery_success', 'Excellent. We now can scan the shuttles computers for the location of our other missing shuttles.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 28, 'rescue_abandoned', 'We barely managed to make it back here in one piece and now you are just going to leave us?'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 29, 'rescue_phase_1', 'Good to see a friendly. We managed to fight off the Bothan and recover the ship but were badly damaged during the escape.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 30, 'rescue_phase_2', 'Alright, I think that should do it. Restarting engines now.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 31, 'split_quest_alert', 'Alert! Calling all available craft. Large number of enemy fighters engaging Grey Squad. All available craft assist Grey Squad.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 32, 'split_quest_alert_fail', ''),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 33, 'taunt_1', 'Give it up! You cannot win this fight.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 34, 'taunt_2', 'Imperial dogs like you are better kept on a short leash.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 35, 'taunt_3', 'Focus on the shuttle. We must get it back!'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 36, 'taunt_4', 'You will regret that!'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 37, 'taunt_5', 'Try as you might, you cannot defeat us.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 38, 'thanks_1', 'I didn''t think we were going to make it that time.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 39, 'thanks_2', 'It looks like if they can''t capture us, they are going to destroy us.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 40, 'thanks_3', 'I hope this rusty bucket holds together.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 41, 'thanks_4', 'I hope that Inqusitior can find out why they are here.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 42, 'thanks_5', 'Thanks, pilot. We would be in a world of hurt without you here.'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 43, 'title', 'Endor System: Rescue the Stolen Shuttle'),
('string/en/spacequest/rescue/tatooine_imperial_tier4_3_a.stf', 44, 'title_d', 'One of the shuttles that was stolen by the Bothans has managed to return to Endor. It appears to be badly damaged but intact. Rescue the shuttle and return it to Imperial control.'),
('string/en/spacequest/rescue/tatooine_privateer_tier3_4_d.stf', 1, 'abort', 'Jabba will hear of this! You''re finished, smuggler!'),
('string/en/spacequest/rescue/tatooine_privateer_tier3_4_d.stf', 2, 'arrival_phase_1', '\\#pcontrast3 Beissa: < \\#pcontrast1 We got a garbled transmission from our Hutt VIP... he''s somewhere close... \\#pcontrast3 >'),
('string/en/spacequest/rescue/tatooine_privateer_tier3_4_d.stf', 3, 'arrival_phase_2', '\\#pcontrast3 Beissa: < \\#pcontrast1 There, we have a lock.  Get over there pilot. \\#pcontrast3 >'),
