('string/en/spacequest/rescue/tatooine_privateer_tier3_4_d.stf', 6, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile Activity has ceased. \\#pcontrast3 >'),
