('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 2, 'abort', 'We are unarmed and you are leaving us at the mercy of these pirates! Fiend!'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 3, 'arrival_phase_1', 'Stand by for navigation coordinates of freighter''s distress signal.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 4, 'arrival_phase_2', 'Location has been transfered to your nav computer. Travel to them and drop off the repair supplies. Then escort them through the system.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 10, 'complete', 'Excellent work, pilot. We have the crippled freighter safely back in space dock. It looks like all of it''s cargo is still intact. Wait at your current location to assist another freighter or return to your commander to receive a new mission.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 11, 'complete_1', 'Freighter has been safely returned to Imperial space.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 12, 'complete_2', ''),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 13, 'complete_3', ''),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 14, 'complete_4', ''),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 15, 'complete_5', ''),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 16, 'docking_complete', 'The freighter has completed it''s repairs. Prepare to escort it to safety.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 17, 'docking_started', 'The freighter has recieved the supplies and is conducting emergency repairs. Please stand by.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 18, 'failed_destroy', 'You lost the Empire a valuable piece of equipment by not protecting that freighter correctly. Report back.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 19, 'panic_1', 'These guys are determined.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 20, 'panic_2', 'I just want to go home!'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 21, 'panic_3', 'They do not look very happy.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 22, 'panic_4', 'And so that is how I made it through space scho...what do little red blips on my radar screen mean?'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 23, 'panic_5', 'Umm...do you think they are friendly?'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 24, 'quest_d', 'Velocity mercenaries have been hitting Imperial transport ships. Sometimes they will hit the transports and then leave them in space without capturing or destroying them. It is up to you to assist those ships with repairs and escort them back home.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 25, 'quest_dock_d', 'Once you have located the damage vessel, use the /dock command on it and to assist the freighter with repairs. The vessel will be able to get underway shortly after you help it.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 26, 'quest_dock_t', 'Assist the Freighter With Repairs'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 27, 'quest_escort_d', 'After the vessel is underway, follow it and make sure that it arrives at a safe jump location without incident. Reports of Velocity mercenary activity show that there is a high chance they will attack the vessel, so be alert and ready to defend the freighter.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 28, 'quest_escort_t', 'Escort the Freighter'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 29, 'quest_location_d', 'Travel to the Dantooine system and follow the supplied navigation waypoint to the damaged freighter.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 30, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 31, 'quest_t', 'Rescue Disabled Vessels'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 32, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 33, 'recovery_success', 'Nice work, pilot. We might have lost the freighters cargo but at least we still have the ship.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 34, 'rescue_phase_1_1', 'It is so nice to see a friendly face. Not sure what happened since I was asleep in the back.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 35, 'rescue_phase_1_2', 'I am not sure but I think I was attacked by those Velocity guys.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 36, 'rescue_phase_1_3', 'My engines are offline right now but I can fix them.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 37, 'rescue_phase_1_4', 'Hey, a rescue party. The Empire really knows how to take care of its own.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 38, 'rescue_phase_1_5', 'Those mercs came out of no where. Not sure why they just left me though. Maybe they had something better to do.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 39, 'rescue_phase_2_1', 'Ok, engines back online. Preparing to get out of here.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 40, 'rescue_phase_2_2', 'This old bucket of bolts is back online. Why do I get the feeling that we will be seeing more of those Velocity guys?'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 41, 'rescue_phase_2_3', 'We are all ready to get out of here. Follow me.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 42, 'rescue_phase_2_4', 'Hey, did you know that kicking your engine will actually make it work? Let''s get out of here.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 43, 'rescue_phase_2_5', 'It should hold together long enough to make our escape. Let''s go.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 44, 'taunt_1', 'That ship is ours! Hand it over Imperial dog.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 45, 'taunt_2', 'I am going to enjoy grinding you to dust.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 46, 'taunt_3', 'Don''t make me angry! You wouldn''t like me when I am angry.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 47, 'taunt_4', 'Looks like you time is up.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 48, 'taunt_5', 'Gee, just what I wanted. An Imperial dog to shoot at.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 49, 'thanks_1', 'Woo! Nice flying!'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 50, 'thanks_2', 'Looks like they should have made like a tree and gotten out of here...hahaha...ummm...*sigh*...nevermind.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 51, 'thanks_3', 'They didn''t have a chance.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 52, 'thanks_4', 'That will teach them for messing with the baddest pilot in space...and you were here too.'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 53, 'thanks_5', 'Yes! I lived!'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 54, 'title', 'Dantooine System: Rescue Damaged Imperial Freighters Duty'),
('string/en/spacequest/rescue_duty/corellia_imperial_tier4_4.stf', 55, 'title_d', 'Travel to the Dantooine sytem and rescue the damaged Imperial freighters. Once you arrive in the Dantooine system, you will receive a navigation waypoint to the location of a damaged freighter. Travel to the location and use the /dock command to assist the freighter with repairs. Once the vessel is repaired escort it through the system to safety. Once the freighter is safely away, you will receive a new navigation waypoint to another freighter in need of assistance. This is a duty mission and can be quit at any time. Simply abort the mission or leave the system to end the mission.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 1, 'abort', 'You have failed because you aborted the mission.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 2, 'arrival_phase_1', 'Await arrival of the rescue ship.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 3, 'arrival_phase_2', 'The ship to be rescued has arrived.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 4, 'attack_notify', 'Attacking craft detected!'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 5, 'attack_stopped', 'The attack has stopped.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 9, 'complete', 'The recovery is complete.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 10, 'complete_1', 'Recovery is complete.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 11, 'complete_2', 'Recovery is complete.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 12, 'complete_3', 'Recovery is complete.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 13, 'complete_4', 'Recovery is complete.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 14, 'complete_5', 'Recovery is complete.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 15, 'docking_complete', 'Docking is complete.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 16, 'docking_started', 'Docking has begun.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 17, 'failed_destroy', 'You have failed because the civilain craft was destroyed.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 18, 'panic_1', 'Dirty Hutts, coming this way!'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 19, 'panic_2', 'The Hutts do not like to lose.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 20, 'panic_3', 'Help!');
