('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 21, 'panic_4', 'Help!'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 22, 'panic_5', 'Help!'),
