('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 24, 'quest_dock_d', 'Fly up near the Freighter and /dock to begin repairs'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 25, 'quest_dock_t', 'Dock Target'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 26, 'quest_escort_d', 'Escort the freighter safely out of the system'),
