('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 28, 'quest_location_d', 'A merchant route in the Dantooine System'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 29, 'quest_location_t', 'Dantooine System'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 30, 'quest_t', ''),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 31, 'quest_update', '%TO'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 32, 'recovery_success', 'The recovery is a success.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 33, 'rescue_phase_1_1', 'Docking has begun.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 34, 'rescue_phase_1_2', 'C''mon, the Hutts will be here!'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 35, 'rescue_phase_1_3', 'I hate my job.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 36, 'rescue_phase_1_4', 'Docking has begun.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 37, 'rescue_phase_1_5', 'Docking has begun.'),
('string/en/spacequest/rescue_duty/corellia_privateer_tier4_1.stf', 38, 'rescue_phase_2_1', 'Be on guard, I won''t outrun much in this tub.'),
