('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 16, 'docking_complete', 'Repairs on the vessel have been completed. Stand by to escort her home.'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 17, 'docking_started', 'Repairs on the damaged vessel beginning.'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 18, 'failed_destroy', 'You lost our ship. Your job is to repair and protect those ships, not let them be blown up. Report back to your commander.'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 19, 'panic_1', 'Rebels! Of course, they have a nose for finding the weak and wounded.'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 20, 'panic_2', 'I can''t fight or evade in my condition. You will have to deal with these guys.'),
