('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 23, 'panic_5', 'Stinking Rebels! Why do they have to show up now?'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 24, 'quest_dock_d', 'Once you have located the damage vessel, use the /dock command on it and to assist the transport with repairs. The vessel will be able to get underway shortly after you help it.'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 25, 'quest_dock_t', 'Assist the Imperial Transport with Repairs'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 26, 'quest_escort_d', 'After the vessel is underway, follow it and make sure that it arrives at a safe jump location without incident. Reports of Rebel activity show that there is a high chance they will attack the vessel, so be alert and ready to defend the transport.'),
('string/en/spacequest/rescue_duty/naboo_imperial_tier4_4.stf', 27, 'quest_escort_t', 'Escort the Imperial Transport'),
