('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 3, 'arrival_phase_2', 'You will find one of the drifting transports near this location. Hurry over there.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 6, 'autorewardbody', ''),
