('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 9, 'complete', 'We''re jumping to lightspeed, thank you pilot, couldn''t have done it without you!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 10, 'docking_complete', 'As soon as the transport is running, escort them to safety.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 11, 'docking_started', 'Dock and transfer the repair parts and tools over to the transport quickly.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 12, 'failed_destroy', 'All those people... return to base pilot. We''d rather have the Empire catch these people than have them all murdered.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 13, 'panic_1', 'Not again...'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 14, 'panic_2', 'More of the Empires fighters coming this way!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 15, 'panic_3', 'Looks like the Empire has come to put the nail in our coffin!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 16, 'panic_4', 'Should we just surrender?'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 17, 'panic_5', 'Please help us pilot, we are not fighters!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 18, 'quest_dock_d', 'Dock with the stranded freighter and transfer the parts it need to be repaired.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 19, 'quest_dock_t', 'Dock and transfer spare parts.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 20, 'quest_escort_d', 'Escort the transport to a safer location. Stay alert, the Imperial forces are closing in.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 21, 'quest_escort_t', 'Escort civilian transport to safety.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 22, 'quest_location_d', 'Even though the Dantooine system shouldn''t be much of a threat to you, the presence of the Imperial Inquisition makes it more dangerous than normal. Stay alert.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 23, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 24, 'quest_update', 'Vortex Fleet Command: < %TO >'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 25, 'recovery_success', 'Good job pilot, those people are safe. Stand by for further orders.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 26, 'rescue_phase_1_1', 'So glad you are here!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 27, 'rescue_phase_1_2', 'I''m not sure this is a good idea, maybe it would be safer to just let them capture us?'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 28, 'rescue_phase_1_3', 'Good to see you pilot, lets hurry up and get out of here!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 29, 'rescue_phase_1_4', 'Are you sure about this? What if they come back?'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 30, 'rescue_phase_1_5', 'I hope we can get out of here before more of them show up.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 31, 'rescue_phase_2_1', 'Hey, is anyone a technician on this piece of junk?'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 32, 'rescue_phase_2_2', 'Alright, lets get out of here!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 33, 'rescue_phase_2_3', 'I got a bad feeling about this..'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 34, 'rescue_phase_2_4', 'We got the tools, we should be repaired in just a moment.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 35, 'rescue_phase_2_5', 'The Empire will be so surprised when they come back and we are all gone..hehe.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 36, 'taunt_1', 'By order of the Imperial Inquisition, cut your engines immediately!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 37, 'taunt_2', 'If you don''t let us board them, we will destroy them Rebel!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 38, 'taunt_3', 'No one expects the Imperial Inquisition!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 39, 'taunt_4', 'You thought we would just let you fly out of here? I don''t think so Rebel!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 40, 'taunt_5', 'Surrender and we may let you live, persist and you will perish!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 41, 'thanks_1', 'Lucky for us, you know what you''re doing.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 42, 'thanks_2', 'I think I just saw my life pass before my eyes..'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 43, 'thanks_3', 'Is it over?'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 44, 'thanks_4', 'Get us out of here!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 45, 'thanks_5', 'This is the last time I''m getting on a space ship!'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 46, 'title', 'Dantooine system: Duty mission: Rescue civilian transports.'),
('string/en/spacequest/rescue_duty/naboo_rebel_tier4_1.stf', 47, 'title_d', 'A large number of civilian transports were disabled by Imperial raids in the Dantooine system. The intelligence that we have suggests that the Inquisition is looking for a Jedi on these ships. The civilian vessels are drifting in space while the Inquisitions capital ships are closing in and your orders are to beat them to the punch. Your ship is equipped with repair material that can be transfered to the transports. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 2, 'abort', 'We are already a mess and you are leaving us! Pirates have been detected in this area.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 3, 'arrival_phase_1', 'Getting a lock on the disabled ship and sending the location to your nav computer. Assist that ship with repairs and escort it to HQ.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 4, 'arrival_phase_2', 'The disabled vessel just limped into the sector. Assist with repairs and escort her home.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 5, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 6, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 7, 'autorewardbody', ''),
