('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 10, 'complete', 'Nice work, pilot. We have her safe and sound. Report your success back to your superior or remain in the area to be assigned another vessel to rescue.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 11, 'complete_1', 'Nice work, pilot. We have her safe and sound. Report your success back to your superior.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 12, 'complete_2', ''),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 13, 'complete_3', ''),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 14, 'complete_4', ''),
