('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 16, 'docking_complete', 'Repairs completed. Escort the ship back to HQ.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 17, 'docking_started', 'Docking procedure started. Once repairs are completed escort her home.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 18, 'failed_destroy', 'We wanted that ship back in one piece. Report your failure to your commander.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 19, 'panic_1', 'It looks like those Red Skulls are coming back to finish the job.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 20, 'panic_2', 'Those pirates are tenacious.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 21, 'panic_3', 'I am going to be useless in this fight. They are all yours.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 22, 'panic_4', 'Hammer them...fast!'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 23, 'panic_5', 'Look out! Pirates coming in at twelve o''clock.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 24, 'quest_dock_d', 'Once you have located the damage vessel, use the /dock command on it and to assist the transport with repairs. The vessel will be able to get underway shortly after you help it.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 25, 'quest_dock_t', 'Assisting the Imperial Transport with Repairs'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 26, 'quest_escort_d', 'After the vessel is underway, follow it and make sure that it arrives at a safe jump location without incident. Reports of Rebel activity show that there is a high chance they will attack the vessel, so be alert and ready to defend the transport.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 27, 'quest_escort_t', 'Escort the Imperial Transport'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 28, 'quest_location_d', 'Travel to the Endor system and follow the supplied navigation waypoint to the damaged transport.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 29, 'quest_location_t', 'Travel to the Endor System'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 30, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 31, 'recovery_success', 'Stand by, pilot. She is on final approach.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 32, 'rescue_phase_1_1', 'Glad to see someone other then those pirates. They have been coming back taunting me every few minutes.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 33, 'rescue_phase_1_2', 'I will try to get my engine back online so we can get out of here.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 34, 'rescue_phase_1_3', 'Those pirates took my engine out and then took off. I think you spooked them.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 35, 'rescue_phase_1_4', 'Not sure if I can get my engine restarted but I will try.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 36, 'rescue_phase_1_5', 'You scared off those pirates. Let me see if I can get restarted and get out of here.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 37, 'rescue_phase_2_1', 'My engine is back online. Follow me!'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 38, 'rescue_phase_2_2', 'Ok, she started but I don''t know how long she will last.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 39, 'rescue_phase_2_3', 'I just completed my repairs. Let''s get out of here.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 40, 'rescue_phase_2_4', 'Wow, that was lucky. I wasn''t damaged as bad as I first thought. Follow me.'),
