('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 43, 'taunt_2', 'Give us the freighter and no one gets hurt.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 44, 'taunt_3', 'You have crossed the wrong pilot this time.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 45, 'taunt_4', 'I was going to let you live but now you are mine!'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 46, 'taunt_5', 'That''s it. No more mister nice guy.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 47, 'thanks_1', 'Wow, you took all those ships out. You are good.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 48, 'thanks_2', 'What happened? I wasn''t paying attention.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 49, 'thanks_3', 'Hey, you destroyed them all. Nice work.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 50, 'thanks_4', 'Yeah that was all me. They couldn''t handle my extreme skills.'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 51, 'thanks_5', 'How do I become an Imperial pilot?'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 52, 'title', 'Endor System: Rescue the Imperial Transports Duty'),
('string/en/spacequest/rescue_duty/tatooine_imperial_tier4_rescueduty_1.stf', 53, 'title_d', 'Travel to the Endor sytem and rescue the damaged Imperial transports. Once you arrive in the Endor system, you will receive a navigation waypoint to the location of a damaged transport. Travel to the location and use the /dock command to assist the transport with repairs. Once the vessel is repaired escort it through the system to safety. Once the transport is safely away, you will receive a new navigation waypoint to another transport in need of assistance. This is a duty mission and can be quit at any time. Simply abort the mission or leave the system to end the mission.'),
