('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 30, 'quest_t', ''),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 31, 'quest_update', '%TO'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 32, 'recovery_success', 'The operation was a success.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 33, 'rescue_phase_1_1', 'Docking has begun.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 34, 'rescue_phase_1_2', 'Thank goodness you are here.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 35, 'rescue_phase_1_3', 'Docking has begun.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 36, 'rescue_phase_1_4', 'Lets get out of here, the cops here swarm like womp rats.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 37, 'rescue_phase_1_5', 'Docking has begun.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 38, 'rescue_phase_2_1', 'Docking is done.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 39, 'rescue_phase_2_2', 'That''s it, lets move!'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 40, 'rescue_phase_2_3', 'Docking is done.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 41, 'rescue_phase_2_4', 'Docking is done.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 42, 'rescue_phase_2_5', 'I hope we can make it.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 43, 'taunt_1', 'Attemping to run was not a wise move.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 44, 'taunt_2', 'You will die!'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 45, 'taunt_3', 'Surrender now, and you may find mercy.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 46, 'taunt_4', 'You will die!'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 47, 'taunt_5', 'You will die!'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 48, 'thanks_1', 'Ha, take that!'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 49, 'thanks_2', 'Thank you.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 50, 'thanks_3', 'Always more where that came from.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 51, 'thanks_4', 'Thank you.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 52, 'thanks_5', 'I don''t get paid enough for this.'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 53, 'title', 'Lok System: Duty: Recover the Nym Freighter'),
('string/en/spacequest/rescue_duty/tatooine_privateer_tier4_1.stf', 54, 'title_d', 'Rescue the Nym Freighter from combined attacks by police forces'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 1, 'abort', 'What are you doing..? You''re leaving us to our death..'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 2, 'arrival_phase_1', 'Alright pilot, we have a lot of transports that need help. Uploading the coordinates to one.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 3, 'arrival_phase_2', 'You will find one of the drifting transports near this location. Hurry over there.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 9, 'complete', 'We are most grateful pilot, I''m sure we would never have seen the light of day again.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 10, 'complete_1', 'I guess this beats an Imperial interrogation cell. We''re out of here.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 11, 'complete_2', 'We are most grateful pilot, I''m sure we would never have seen the light of day again.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 12, 'complete_3', 'Where do I sign up to join the Rebellion?'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 13, 'complete_4', 'We are all in your debt pilot, please accept our gratitude.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 14, 'complete_5', 'We''re home free everyone, thanks to this amazing pilot!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 15, 'docking_complete', 'As soon as the transport is running, escort them to safety.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 16, 'docking_started', 'Dock and transfer the repair parts and tools over to the transport quickly.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 17, 'failed_destroy', 'All those people... return to base pilot. We''d rather have the Empire catch these people than have them all murdered.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 18, 'panic_1', 'Not again...'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 19, 'panic_2', 'More of the Empires fighters coming this way!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 20, 'panic_3', 'Looks like the Empire has come to put the nail in our coffin!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 21, 'panic_4', 'Should we just surrender?'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 22, 'panic_5', 'Please help us pilot, we are not fighters!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 23, 'quest_dock_d', 'Dock with the disabled fugitive transport and transfer the spare parts they need to repair their ship.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 24, 'quest_dock_t', 'Dock and transfer spare parts.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 25, 'quest_escort_d', 'Escort the transport to safety quickly. Our sensors show more and more Imperial ships entering the area so be prepared to come under attack.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 26, 'quest_escort_t', 'Escort the transport.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 27, 'quest_location_d', 'The Dantooine system should be fairly safe for an experienced pilot as yourself but the Empire is moving in some of their fleet in to this area so stay alert.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 28, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 29, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 30, 'recovery_success', 'Great, they are safe! Stand by for further orders.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 31, 'rescue_phase_1_1', 'So glad you are here!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 32, 'rescue_phase_1_2', 'I''m not sure this is a good idea, maybe it would be safer to just let them capture us?'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 33, 'rescue_phase_1_3', 'I hope we can get out of here before more of them show up.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 34, 'rescue_phase_1_4', 'Good to see you pilot, lets hurry up and get out of here!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 35, 'rescue_phase_1_5', 'Are you sure about this? What if they come back?'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 36, 'rescue_phase_2_1', 'We got the tools, we should be repaired in just a moment.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 37, 'rescue_phase_2_2', 'Hey, is anyone a technician on this piece of junk?'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 38, 'rescue_phase_2_3', 'Alright, lets get out of here!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 39, 'rescue_phase_2_4', 'I got a bad feeling about this..'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 40, 'rescue_phase_2_5', 'The Empire will be so surprised when they come back and we are all gone..hehe.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 41, 'taunt_1', 'You''re not going anywhere you Rebel fools.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 42, 'taunt_2', 'You have three seconds to cut your engines and surrender or we will destroy you!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 43, 'taunt_3', 'That ship now belongs to the Emperor, surrender it immediately!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 44, 'taunt_4', 'You have your orders men, if they don''t stop, terminate them.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 45, 'taunt_5', 'You will not leave this system alive unless you surrender.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 46, 'thanks_1', 'Lucky for us, you know what you''re doing.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 47, 'thanks_2', 'I think I just saw my life pass before my eyes..'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 48, 'thanks_3', 'Is it over?'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 49, 'thanks_4', 'Get us out of here!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 50, 'thanks_5', 'This is the last time I''m getting on a space ship!'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 51, 'title', 'Dantooine system: Duty mission: Rescue fugitive transports.'),
('string/en/spacequest/rescue_duty/tatooine_rebel_tier4_1.stf', 52, 'title_d', 'A civilian fugitive fleet with some Alliance members in it was ambushed in the Dantooine system by the Empire. Several of the transports have been disabled and are drifting through space. The Empire is moving in capital ships to capture the crew and passengers. Let'' beat them to it and save these people. When you feel that you have exhausted your ship, yourself or that you have enough experience to continue your training, you can return to base at anytime.'),
