('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 3, 'allies_win', 'Viva La Empire'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 4, 'assigned_delayed', 'Go to this waypoing and protect a training wing.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 6, 'autorewardfrom', ''),
