('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 9, 'enemies_arrived', 'The Rebels are here'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 10, 'enemies_remain', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 11, 'enemies_win', 'Rebels win, this is a bad thing.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 12, 'found_loc', 'Waypoint to location has been set.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 13, 'quest_findbattle_d', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 14, 'quest_findbattle_t', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 15, 'quest_helpallies_d', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 16, 'quest_helpallies_t', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 17, 'quest_location_d', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 18, 'quest_location_t', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 19, 'quest_update', '%TO'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 21, 'title', 'Protect the Trainees'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2d.stf', 22, 'title_d', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 2, 'allies_arrived', 'The Hutt force has grouped and is waiting for Nym to attack.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 3, 'allies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI Hutt fighters remaining.>'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 4, 'allies_win', 'Nice work. Nym''s forces have been wiped out. They will have to think twice about operating in this system with both the Imperial and Hutts fighting them. Make a full report back to your superior.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 9, 'battle_abandoned', 'What are you doing? You left the Hutt forces outnumbered and outclassed. Nym needs to fear the Hutts not think of them as easy prey. This is unacceptable! Report back to your commanding officer.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 10, 'battle_started', 'Nym''s forces have engaged the Hutts. Make sure that the Hutts are victorious.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 11, 'enemies_arrived', 'Nym''s forces have jumped into the system. They are heading towards the Hutts at attack speeds.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 12, 'enemies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI Nym fighters remaining.>'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 13, 'enemies_win', 'Blast it! Nym has won the day. Now they have the confidence that they can fight both the Empire and Hutt forces. This operation is a failure. Report back to your superior.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 14, 'found_loc', 'Located coordinates of projected attack by Nyms forces. Assist the Hutt defenders in the area. Remember the Hutts are not friendlies and will fire on you. Do not destroy any of the Hutt defenders.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 15, 'quest_findbattle_d', 'Travel to the supplied navigation waypoint that will be given to you. This waypoint will lead you to the location that the battle will take place.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 16, 'quest_findbattle_t', 'Travel to the Battle Location'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 17, 'quest_helpallies_d', 'Once at the battle location, wait for the arrival of Nym''s forces and for the battle to start. Destroy all of Nym''s men before they can destroy all of the Hutts. The Hutts are outnumbered so your assistance is important. Becareful, since the Hutts are not friendly to the Empire they may open fire on you.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 18, 'quest_helpallies_t', 'Help the Hutts Defeat Nym''s Men'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 19, 'quest_location_d', 'Remain in the Yavin system and assist the Hutts in destroying Nym''s men. Travel to the navigation waypoint that you will receive to the battle location.'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 20, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/space_battle/corellia_imperial_tier3_2_c.stf', 21, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
