('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 2, 'allies_arrived', 'They started following us a while back, we can''t let them reach the fleet.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 3, 'allies_remain', 'Rebel Pilot: < Critical system failure, my engines are burning! I nee... >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 4, 'allies_win', 'Fantastic job pilot! If you ever look for a reassignment to a squad, look me up. Now lets get out of here.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 6, 'autorewardbody', ''),
