('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 10, 'battle_started', 'Here they come, attack pattern Green 2! Give them a fight they won''t forget!'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 11, 'enemies_arrived', 'There they are, get ready guys!'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 12, 'enemies_remain', 'X-Wing Squad Leader: < Good job everyone, only %DI Imperial scum to go! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 13, 'enemies_win', 'My ship is burning up! Get out of he...'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 14, 'found_loc', 'Good to see you pilot. Proceed to these coordinates.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 15, 'quest_findbattle_d', 'The X-Wing squadron has set these coordinates as the location where they will perform their counter attack. Join up with them quickly.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 16, 'quest_findbattle_t', 'Coordinates of battle.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 17, 'quest_helpallies_d', 'We would send in more reinforcements but the whole idea here is to not let the Empire know the amount of ship we have in transit right now. You and the X-Wing squadron will be on your own. Good luck!'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 18, 'quest_helpallies_t', 'Assist the X-Wings.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_1_d.stf', 19, 'quest_location_d', 'While flying over to the X-Wing squadron, be careful to not attract more Imperial fighters. The Yavin system is crawling with them.'),
