('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 10, 'battle_started', 'Time to fry some Imperial scum, bring it to them guys!'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 11, 'enemies_arrived', 'Alright, the fools have arrived, get ready.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 12, 'enemies_remain', 'Green Squadron Leader: < Hang in there everyone! Only %DI left! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 13, 'enemies_win', 'Can''t keep my ship together, I''m falling ap..'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 14, 'found_loc', 'Proceed to these coordinates, We will rendez-vous with you there.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 15, 'quest_findbattle_d', 'The Green Squadron leader has given you these coordinates as the point where they will try to fight back the pursuing TIE fighters.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 16, 'quest_findbattle_t', 'Green Squadron rendez-vous.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 17, 'quest_helpallies_d', 'The heavy Y-Wings are having trouble with the nimbler TIE fighters and will need your help in defeating them or perish.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 18, 'quest_helpallies_t', 'Assist the Green Squadron.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 19, 'quest_location_d', 'The Endor system is now starting to look like a war zone. We have more reinforcements coming from the Lok system and more and more Imperial reinforcements are pouring in ahead of their main fleet.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 20, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 21, 'quest_update', 'Green Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 22, 'split_quest_alert', 'Rebel Fleet Command: < Great work out there pilot. One of our smugglers have brought equipment we need to repair our hyperdrive systems. He needs a escort. >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 23, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 24, 'title', 'Endor system: Assist Green Squadron in attacking the Empire.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_3_b.stf', 25, 'title_d', 'We have started some smaller attacks on parts of the Imperial Navy in the system. One of our Y-Wing squadrons has been hunted down after a successful mission and need your help in destroying the pursuing TIE fighters.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 2, 'allies_arrived', 'We are here. Prepare for battle everyone.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 3, 'allies_remain', 'Rebel Pilot: < It burns! Please no! Nooo... >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 4, 'allies_win', 'I knew we could take them, great job everyone!'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 10, 'battle_started', 'Marvin, cover the left flank. Zeda, attack second from the right. Go go go!'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 11, 'enemies_arrived', 'There they are. This will be tough guys so no playing around, do your job and do it well!'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 12, 'enemies_remain', 'Blue Squadron Leader: < %DI more! Keep it up! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 13, 'enemies_win', 'Damn the Empire! Damn you a...'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 14, 'found_loc', 'Listen up pilot, this is Blue Squad Leader. Rendez-vous with us at these coordinates.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 15, 'quest_findbattle_d', 'This is the location of the Blue Squadron, hurry over there and assist them in their attack.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 16, 'quest_findbattle_t', 'Blue Squadrons location.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 17, 'quest_helpallies_d', 'Concentrate on the small and fast TIE fighters first, those are the ships our heavy B and Y-Wings have a hard time fighting.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 18, 'quest_helpallies_t', 'Assist Blue Squadron.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 19, 'quest_location_d', 'Small skirmishes are blossoming up all over the Endor system as the Empire is trying to find the location of the Rebel fleet. Although this was an attack by our ships, it turned ugly by the presence of the fast TIE fighters.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 20, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 21, 'quest_update', 'Blue Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 22, 'split_quest_alert', 'Rebel Fleet Command: < I got the report, good job pilot. We are about ready to get out of here but the Empire is launching a last desperate attack. >'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 23, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 24, 'title', 'Endor system: Assist Blue Squadron in destroying a TIE Bomber wing.'),
('string/en/spacequest/space_battle/corellia_rebel_tier3_4_c.stf', 25, 'title_d', 'Blue squadron was ordered to terminate a TIE bomber squadron. Unfortunately the Imperial bombers got reinforced by TIE fighters. Our Y and B-Wings have a hard time defeating these small ships and need your assistance.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 1, 'allies_arrived', 'We have arrived, join up pilot.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 2, 'allies_remain', 'Nym Pilot: < I''m going down! Make them pay bo... >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 3, 'allies_win', 'Great job guys, the Black Sun should think twice before they try something like this again. Return to base everyone.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 9, 'battle_started', 'Lets bring it to them boys!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 10, 'enemies_arrived', 'Hostile vessel activity confirmed in target area.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 11, 'enemies_remain', 'Nym Pirate Squad Leader: < Haha take that you Black Sun loosers! Only %DI left guys! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 12, 'enemies_win', 'Pull out! This battle is lost and...'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 13, 'found_loc', 'Proceed to this location to meet up with us.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 14, 'quest_findbattle_d', 'Recon ships have detected Black Sun precense in this area. Proceed to the location immediately.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 15, 'quest_findbattle_t', 'Coordinates of attack.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 16, 'quest_helpallies_d', 'Assist the gathered Nym and Alliance fighters in destroying the present Black Sun vessels.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 17, 'quest_helpallies_t', 'Assist in the attack.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 18, 'quest_location_d', 'You are entering hostile sectors of the Dathomir system. Stay sharp and be prepared for attack.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 19, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 20, 'quest_update', 'Nym Pirate Squad Leader: < %TO >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 23, 'title', 'Dathomir system: Bring the battle back to the Black Sun.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_a.stf', 24, 'title_d', 'After our huge success in beating off the initial Black Sun attack they are in disarray and now is the time to strike. Assist one of Nym''s fighter squadrons in delivering vengeance upon the Black Sun.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 1, 'allies_arrived', 'Some of the Black Sun Fighters got past you? We need to get out of here!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 2, 'allies_remain', 'Nym Freighter Pilot: < Too much damage! We have massive hull brea... >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 3, 'allies_win', 'At least they didn''t get us all. Return to base before more of them arrive pilot.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 9, 'battle_started', 'They are locking on to me, this is going to hurt!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 10, 'enemies_arrived', 'We have multiple Black Sun fighter ships closing in, we need help now!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 11, 'enemies_remain', 'Tactical Computer: < Scans show enemy vessel terminated. %DI remain. >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 12, 'enemies_win', 'I''m going down! Save yourself pi..'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 13, 'found_loc', 'We need your help at this location! Now pilot!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 14, 'quest_findbattle_d', 'These are your assigned coordinates, you will find some mining vessels under heavy attack by the Black Sun.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 15, 'quest_findbattle_t', 'Your battle.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 16, 'quest_helpallies_d', 'We need to save what can be saved. Assist the Nym Fighters and Freighters in this area and terminate the Black Sun threat.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 17, 'quest_helpallies_t', 'Assist the mining vessels.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 18, 'quest_location_d', 'Although this part of the Dathomir system is relatively free from hostile ships normally, it''s now crawling with Black Sun bombers and fighters.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 19, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 20, 'quest_update', 'Nym Freighter Pilot: < %TO >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 23, 'title', 'Dathomir system: Save the Nym freighters from total annihilation.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_1_b.stf', 24, 'title_d', 'Several Black Sun ship managed to slip by our and Nym''s blockade and the mining vessels are under attack. Assist and save as many of them as you can.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 1, 'allies_arrived', 'We are in position to start the attack. Join up pilot.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 2, 'allies_remain', 'Nym Squadron Leader: < Hang in there guys! We can do this! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 3, 'allies_win', 'Great job everyone, the Rebel bomber squadrons are closing in. You are free to pull out.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 5, 'autorewardbody', ''),
