INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 9, 'battle_started', 'Time to show these fools the wrath of the pirates of Nym, take no prisoners guys!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 10, 'enemies_arrived', 'My sensors show multiple bogeys. Looks like this will be a lot of fun guys.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 11, 'enemies_remain', 'Nym Squadron Leader: < Yehaa! Take that you Imperial scum! Only %DI more guys! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 12, 'enemies_win', 'Pull out of there pilot! We''re doomed, I can...'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 13, 'found_loc', 'We will meet you at this location, hurry over here or we will start without you.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 14, 'quest_findbattle_d', 'This is the point of attack. We will breach the Imperial defences here so that the B-Wing bombers can press through and launch their payload on the station.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 15, 'quest_findbattle_t', 'Coordinates of attack.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 16, 'quest_helpallies_d', 'Join up with the other ships from Worvog''s squadron and destroy the Imperial presence in the area.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 17, 'quest_helpallies_t', 'Crush the Imperial defence.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 18, 'quest_location_d', 'The Dathomir system is normally dangerous but this sector of it will be even worse. You will be close to an Imperial base and enemies will be everywhere.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 19, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 20, 'quest_update', 'Nym Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 21, 'split_quest_alert', 'Worvog Arkon: < Damnation! One of the Rebels B-Wing squadrons have been intercepted by Imperial ships and need help, stand by. >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 22, 'split_quest_alert_fail', 'Worvog Arkon: < We managed to do some damage but our Bombers are in trouble. Stand by for orders. >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 23, 'title', 'Dathomir system: Help the Alliance attack on an Imperial space station.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3.stf', 24, 'title_d', 'Our squad has been assigned to assist in a guerilla strike on an Imperial space station. We need to pave the way through enemy defense for the Alliance B-Wing bombers.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 1, 'allies_arrived', 'This is Snow Squadron Leader, we need fighter support, now! We have multiple enemy fighters closing in on our position!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 2, 'allies_remain', 'Snow Squadron Leader: < We are not built for fighter combat...if you don''t step it up pilot, we''re all doomed! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 3, 'allies_win', 'Our gratitude pilot, we would have been cooked if you didn''t show up when you did.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 9, 'battle_started', 'Good to see you pilot. This will get tough but we have seen worse, right guys? Lets show them they picked the wrong fight today!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 10, 'enemies_arrived', 'The enemy is forming in to battle positions. Defensive formation Z guys, get your act together!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 11, 'enemies_remain', 'Snow Squadron Leader: < Yes! Hang in there everyone! Only %DI more left! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 12, 'enemies_win', 'Get out of here pilot! There''s noth...'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 13, 'found_loc', 'This is Snow Squadron Leader, my Bomber wing is under heavy fire! We will try to make it to these coordinates, need fighter support there!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 14, 'quest_findbattle_d', 'These are the coordinates where the Snow Squadron reported in the ambush, hurry over there.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 15, 'quest_findbattle_t', 'Coordinates of ambush.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 16, 'quest_helpallies_d', 'Although the Snow Squadron are all experienced pilots, their heavy B-Wings have problems with the nimbler TIE ships and will need your help in defeating them.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 17, 'quest_helpallies_t', 'Save the Snow Squadron.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 18, 'quest_location_d', 'As in your previous mission, you''re in an area of the Dathomir system where the Imperial presence is extreme. Take caution and stay vigilant.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 19, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 20, 'quest_update', 'Snow Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 23, 'title', 'Dathomir system: Save one of the ambushed Rebel B-Wing squadrons.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_3_a.stf', 24, 'title_d', 'We have a problem, several of our B-Wings on the way to the space station have been ambushed. You need to hurry over to them and assist in defeating the attackers.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 2, 'allies_arrived', 'Our reinforcements have arrived, join up with them quickly, the Empire is closing in.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 3, 'allies_remain', 'Allied Pilot: < What are those ships?! They are too tough! Tell my w... >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 4, 'allies_win', 'Good work everyone. We''re sending in a Tech team to retrieve debris of those new Imperial vessels. Return to base.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 5, 'assigned_delayed', ''),
