('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 10, 'battle_started', 'Bring the fight to them. Be careful of those new TIE ships though, we''re not sure what they are capable of.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 11, 'enemies_arrived', 'The Imperial forces have arrived, everyone prepare for battle.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 12, 'enemies_remain', ' Worvog Arkon: < Keep it up everyone, you can do this! There''s only %DI left! >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 13, 'enemies_remaining', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 14, 'enemies_win', 'Pull out! We don''t need more casaulties!'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 15, 'found_loc', 'The reinforcements will arrive at this location, get there fast pilot.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 16, 'quest_findbattle_d', 'The Imperial fighters are closing in on you, proceed to this area immediately where your reinforcements will meet up with you.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 17, 'quest_findbattle_t', 'Rendez-vous location.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 18, 'quest_helpallies_d', 'With the help of your reinforcements, turn the table on the Empire and teach them a lesson.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 19, 'quest_helpallies_t', 'Reinforcements arrive.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 20, 'quest_location_d', 'If you can, avoid running in to more enemies on your way to your reinforcements. Keep in mind though, the Imperial fighters are close behind you and you can''t allow yourself to be detoured for long.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 21, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 22, 'quest_update', 'Worvog Arkon: < %TO >'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 23, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 24, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 25, 'title', 'Endor system: Defeat the Empires retaliation.'),
('string/en/spacequest/space_battle/corellia_rebel_tier4_4_c.stf', 26, 'title_d', 'The Empire is trying to retaliate for your attack on their freighter, they want your head. We have sent reinforcements to the area, lets show the Empire that we are not afraid of them.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 1, 'allies_arrived', 'CorSec attack wing has arrived. Stand by, detecting hyperspace jump.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 2, 'allies_remain', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  CorSec ship destroyed. %DI allied ships remaining.\\#pcontrast1 >'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 3, 'allies_win', 'Good work, pilot. All Cloak vessels have been... wait. Stand by, we''re tracking another signal.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 8, 'battle_started', 'It''s a setup! There are far too many Cloaks here. It was a trick just to lure us here, we are the real target. Destroy them all.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 9, 'enemies_arrived', 'Cloak attack wing has hyperspaced in. Wow, there''s a lot of them. Is this right?'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 10, 'enemies_remain', '\\#pcontrast1 Tactical Computer: <\\#pcontrast3  Enemy ship destroyed. %DI enemy ships remaining.\\#pcontrast1 >'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 11, 'enemies_win', 'Withdraw, pilot. Our attack wing has been wiped out. Return to the station for debriefing.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 12, 'found_loc', 'Note the navigation waypoint, pilot. This is the expected hyperspace jump point of the Cloak attack wing.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 13, 'quest_findbattle_d', 'You have been given the most likely jump point for the Cloak attack wing. Remain in this area.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 14, 'quest_findbattle_t', 'Stay at the Jump Point'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 15, 'quest_helpallies_d', 'The Cloaks have planned an ambush. Far too many ships have come in than should be necessary to take down a transport. This attack was planned against the CorSec itself. Help CorSec destroy all the Cloak fighters.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 16, 'quest_helpallies_t', 'Assist the CorSec Squad'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 17, 'quest_location_d', 'Your assistance will likely be needed in this battle. Do not leave the Corellia system.'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 18, 'quest_location_t', 'Remain in the Corellia System'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 19, 'quest_update', '\\#pcontrast1 CorSec Command: <\\#pcontrast3  %TO\\#pcontrast1  >'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 20, 'split_quest_alert', 'Tracking signature of Cloak Leader vessel'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 22, 'title', 'Corellia System: Ambush the Cloak Attack Wing'),
('string/en/spacequest/space_battle/corellia_station_mission5b_2.stf', 23, 'title_d', 'The Cloak attack wing has started to hyperspace in. A signal has been sent to CorSec command. They will be sending a CorSec attack squad to deal with this menace.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 1, 'allies_arrived', 'Tactical Comptuer:<Third wing located. Third wind has substained heavy casualties.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 2, 'allies_remain', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 3, 'allies_win', 'Tactical Computer:<Enemy fighters have been elimated.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 4, 'assigned_delayed', ''),
