('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 10, 'enemies_arrived', 'Tactical Computer:<Enemy fighter located. Closing at high speeds.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 11, 'enemies_remain', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 12, 'enemies_win', 'Imperial High Command:<We have lost third wing. Report back to your superior for a full report.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_2_e.stf', 13, 'found_loc', 'Arrived at last known location of third wing.'),
