('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 2, 'allies_arrived', 'TIE Fighter group has formed up to try to hold off the rebel fighters.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 3, 'allies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI allied fighters remaining.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 4, 'allies_win', 'The enemy has been destroyed. This is a great day for the Empire.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 9, 'battle_abandoned', 'What are you doing? You left our forces outnumbered and outclassed! This is unacceptable! Report back to your commanding officer.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 10, 'battle_started', 'Allied fighters have engaged the enemy.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 11, 'enemies_arrived', 'Enemy fighters detected exiting hyper space.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 12, 'enemies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI enemy fighters remaining.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 13, 'enemies_win', 'The Rebels have won this day. But we will return with a vengence. Return to your superior officer and give a full report.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 14, 'found_loc', 'Sending your navigation computer the location of the TIE wing. Join up with them and help beat back the enemy.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 15, 'quest_findbattle_d', 'Travel to the supplied navigation waypoint that will be given to you. This waypoint will lead you to the location that the battle will take place.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 16, 'quest_findbattle_t', 'Travel to the Battle Location'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 17, 'quest_helpallies_d', 'Once at the battle location, wait for the arrival of the TIE wing and for the battle to start. Destroy all of the attacking Rebels before they can destroy all of the TIEs. The TIEs are outnumbered so your assistance is important.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 18, 'quest_helpallies_t', 'Help the TIE Wing Defeat the Rebels'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 19, 'quest_location_d', 'Remain in the Dathomir system and assist the TIE wing in destroying the attacking Rebels. Travel to the navigation waypoint that you will receive to the battle location.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 20, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 21, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 22, 'split_quest_alert', 'We have located the Rebel command ship in the Dathomir system. Launch an immediate strike at the heart of our enemy.'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 23, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 24, 'title', 'Dathomir System: Battle the Rebel Forces'),
('string/en/spacequest/space_battle/naboo_imperial_tier3_4_b.stf', 25, 'title_d', 'Remain in the Dathomir system and help our TIE wing beat the Rebels in a battle. You will receive a navigation waypoint to the place where the battle is going to take place. Travel to this location and wait for the arrival of the TIEs and Rebels. When the battle is joined, assist the TIE wing with destroying  the Rebel force before the Rebels can wipe out the TIE wing. If all of the TIEs die then you will have lost the battle.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 2, 'allies_arrived', 'TIE 701st wing assembled.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 3, 'allies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI allied fighters remaining.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 4, 'allies_win', 'Enemy fighters have been eliminated. Scans indicate last few remaining Coynite vessels fleeing the system.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 9, 'battle_abandoned', 'You left the 701st alone! They will not stand much of chance against the superior force. Report your failure to your commander.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 10, 'battle_started', 'Warning! TIE 701st wing engaging enemy. Highly outnumbered.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 11, 'enemies_arrived', 'Enemy fighters assembled.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 12, 'enemies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI enemy fighters remaining.>'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 13, 'enemies_win', 'TIE 701st wing has been destroyed. Thier destuction means loss of control in system. Report to your superior immediately.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 14, 'found_loc', 'We have located the squadron. Travel immediately to their location and assist them in the destruction of the enemy. Keep the 701st alive, they are essential to the protection of the Dathomir sector.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 15, 'quest_findbattle_d', 'Meet the 701st at the supplied navigation waypoint and wait for the arrival of the enemy.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 16, 'quest_findbattle_t', 'Travel to Battle Location'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 17, 'quest_helpallies_d', 'You must destroy all the enemy attacking vessels before they can destroy the remaining TIEs in the 701st.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 18, 'quest_helpallies_t', 'Help the 701st Defeat the Coynite'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 19, 'quest_location_d', 'The attack is taking place in the Dathomir system. A navigaiton waypoint will be supplied to you.'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 20, 'quest_location_t', 'Remain in the Dathomir System'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 21, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 22, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 23, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 24, 'title', 'Dathomir System: Battle the Coynite Fighters'),
('string/en/spacequest/space_battle/naboo_imperial_tier4_4_d.stf', 25, 'title_d', 'The Coynite have attacked the 701st TIE wing over Dathomir. That TIE defense force is highly important for the security of the Dathomir system and must be keep alive. Assist the 701st in its defense against the Coynite.'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 1, 'allies_arrived', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Your backup has arrived.  Good luck. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 2, 'allies_remain', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An Allied Craft has been destroyed, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 3, 'allies_remaining', 'An allied craft has been destroyed, %DI remain.'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 4, 'allies_win', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The mission is a success, enemy fighters have all been destroyed. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 5, 'assigned_delayed', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Proceed to the following waypoint. We are expecting to intercept a large number of enemy fighters and have diverted some of the Madersims'' escort to assist you.  We cannot afford to lose those escorts.  Command out! \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 10, 'battle_started', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy forces have been engaged. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 11, 'enemies_arrived', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft are approaching. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 12, 'enemies_remain', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 An enemy craft has been destroyd, %DI remain. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 13, 'enemies_remaining', 'An enemy craft has been destroyed, %DI remain.'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 14, 'enemies_win', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The Madersims'' escort has been destroyed, this is unacceptable. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 15, 'found_loc', '\\#pcontrast3 RSF Command: < \\#pcontrast1 We pulled these ships from the Madersim''s escort and cannot afford to lose them.  Defend as much as possible \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 16, 'quest_findbattle_d', 'Travel here to set up the ambush for the Ay''Nat pirates'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 17, 'quest_findbattle_t', 'Ambush Waypoint'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 18, 'quest_helpallies_d', 'These were taking from the RSF Madersim, to lose them would be failure on your part'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 19, 'quest_helpallies_t', 'Defend the RSF Craft'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 20, 'quest_location_d', 'An area in the Corellia System where we expect the Ay''Nat pirates to make an appearance'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 21, 'quest_location_t', 'Corellia System'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 22, 'quest_update', '%TO'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 23, 'split_quest_alert', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Get out to the Madersim''s last known position.  I fear they will be under attack soon with insufficient protection. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/naboo_privateer_tier3_2d.stf', 24, 'split_quest_alert_fail', ''),
