('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 1, 'allies_arrived', 'The SpyNet fighters have arrived, form up with them and prepare to intercept the pirates.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 2, 'allies_remain', 'Tactical Computer: < Sensors indicate loss of ally vessel. %DI friendly vessel(s) remain. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 3, 'allies_win', 'Great job pilot, you impressed both us and the SpyNet.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 9, 'battle_started', 'This is it! Good luck everyone, show them the error of their ways!'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 10, 'enemies_arrived', 'Our sensors have picked up the Blacklight pirates. Get ready everyone.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 11, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy target(s) remain.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 12, 'enemies_win', 'That battle is lost pilot! Get out of there and return to base immediately!'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 13, 'found_loc', 'Alright pilot, the Blacklight scum are moving in to attack one of the SpyNet''s bases of operations. The SpyNet has set up a intercept ambush of the Blacklight pirates but could use your help as they are outnumbered. Proceed to this location immediately.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 14, 'quest_findbattle_d', 'The SpyNet fighters are retreating to these coordinates and have asked for us to send our reinforcements to there. Head over there with haste my friend.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 15, 'quest_findbattle_t', 'Location of attack.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 16, 'quest_helpallies_d', 'Terminate the attacking Blacklight pirates in this area and save the SpyNet operatives.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 17, 'quest_helpallies_t', 'Save the SpyNet fighters.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 18, 'quest_location_d', 'Though the Dantooine system is fairly safe from the Imperial menace, the Blacklight pirates are a cunning bunch and shouldn''t be underestimated.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 19, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 20, 'quest_update', 'Brother Ezkiel: < %TO >'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 21, 'split_quest_alert', 'Brother Ezkiel: < Pilot! Rescue the SpyNet Commander. His ship has been disabled by the pirates and they are moving in bigger ships to capture him! >'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 23, 'title', 'Dantooine system: Help the SpyNet Operatives'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_2.stf', 24, 'title_d', 'The SpyNet is having some problems with the Blacklight pirates in the Dantooine system and has asked us for a favor before they slice the data we took from the Imperial spy. The SpyNet is currently under open attack in one sector of the Dantooine system and request fighter support, we are sending them you to assist.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 1, 'allies_arrived', 'Your reinforcements are on their way, join up with them immediately pilot.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 2, 'allies_remain', 'Rebel Pilot: < I got this one in my sights, just need one more second... No! Where did he come fro... >'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 3, 'allies_win', 'That was a fantastic show of skill out there, pilot! Our side was successful in defeating the Imperial Inquisitor. Soon, the information we seek will be in our hands.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 9, 'battle_started', 'Be careful out there, our side looks to be sorely outnumbered. The Imperial Inquisition has been trained to be ruthless in every situation. Good luck to you all, may the force be with you!'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 10, 'enemies_arrived', 'Sensors are picking up heavy enemy presence in this area. Be prepared for anything my friends.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 11, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy target(s) remain.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 12, 'enemies_win', 'Our cause is lost. You fought well, but we had very little resources to attack the base to begin with. Return to me, pilot, for further instruction.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 13, 'found_loc', 'We found the supposed location of the experimental operations for the Imperial Inquisition. Proceed with caution and good luck.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 14, 'quest_findbattle_d', 'The X-Wing squadron will try to make it to these coordinates and prepare a stand against the Imperial attackers. Proceed to this waypoint as fast as you can.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 15, 'quest_findbattle_t', 'Coordinates of attack.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 16, 'quest_helpallies_d', 'Help the X-Wing squadron fight off their pursuers. They have heard of you and their morale is lifted knowing that you are coming to assist them. Don''t let them down my friend.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 17, 'quest_helpallies_t', 'Assist the X-Wing squadron.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 18, 'quest_location_d', 'It makes sense that the Imperial Inquisition is in the Dathomir system. It''s heavily guarded by the Empire for some reason and a extremely dangerous area. Whenever you are here, proceed with caution.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 19, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 20, 'quest_update', 'Brother Ezkiel: < %TO >'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 21, 'split_quest_alert', 'Brother Ezkiel: < Good work, pilot. Now, find us a lone target and disable his ship. We need as much information as possible. Continue on the patrol and report as soon as you find something. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 23, 'title', 'Dathomir system: The Imperial Inquisition attacks.'),
('string/en/spacequest/space_battle/naboo_rebel_tier3_4.stf', 24, 'title_d', 'With the sliced data from the Imperial spy we have now found what we hope to be the right location of the Empires heinous experiments. One of our fighter wings has come under heavy attack though and require your assistance.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 1, 'allies_arrived', 'Join up with the rest of your squadron as soon as you can.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 2, 'allies_remain', 'Rebel Pilot: < I can''t shake this one! Missile war... >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 3, 'allies_win', 'Good job everyone, I''m very impressed! Return to base for debrief everyone.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 9, 'battle_started', 'Alright, show them what you guys can do!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 10, 'enemies_arrived', 'Brother Extok Evin: < Our reconnaissance ship has confirmed a TIE ship model Oppressor in the target wing. This should be interesting. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 11, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy targets remain. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 12, 'enemies_win', 'Pull out pilot, you''re getting crushed over there!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 13, 'found_loc', 'The rest of your squadron will meet you in this area. We have the opportunity to take on one of the Empires new experimental TIE ships.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 14, 'quest_findbattle_d', 'Your reinforcements will meet up with you at these coordinates, proceed quickly but with caution.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 15, 'quest_findbattle_t', 'Meeting coordinates of attack.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 16, 'quest_helpallies_d', 'Support your X-Wing squadron and complete a vicious strike against the Imperial forces in the area.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 17, 'quest_helpallies_t', 'Attack the Imperial fighters.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 18, 'quest_location_d', 'Yavin is not a high risk system to experienced pilots like yourself but if the Empire is testing experimental fighters, you can bet they will be well guarded.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 19, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 20, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 23, 'title', 'Yavin system: Attack one of the Empires new experimental TIE ships.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_2_a.stf', 24, 'title_d', 'Although the reinforcements arrived late, a opportunity have opened up for you to make something of it. The Empire is testing out some of their new TIE models in a nearby area, lets teach them a real lesson.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 2, 'allies_arrived', 'The Inquisition is anticipating our attack so this will be rough. I have trust that it''s not beyond your capabilities though.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 3, 'allies_remain', 'Rebel Pilot: < My ship is falling apart! I need hel.. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 4, 'allies_win', 'Good job everyone, stand by for new orders.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 10, 'battle_started', 'Alright my friends, show them what you''re made of!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 11, 'enemies_arrived', 'You and the rest of the fighters will try and wittle down the enemy fighters so that our bombers can move in safely.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 12, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy targets remain. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 13, 'enemies_win', 'Pull out! We need to come up with a backup plan quickly!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 14, 'found_loc', 'Meet up with the rest of the squadron at this location.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 15, 'quest_findbattle_d', 'This is the coordinates where we will initialize the attack on the base defense. Proceed to there immediately but try to avoid any enemy contact while travelling.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 16, 'quest_findbattle_t', 'Attack coordinates.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 17, 'quest_helpallies_d', 'Coordinate with your fellow pilots and attack the base defense. Destroy them all and give the command for our bombers to move in. Good luck pilot!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 18, 'quest_helpallies_t', 'Attack!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 19, 'quest_location_d', 'The extreme risk Dathomir system is as dangerous as ever. We don''t need more enemies than there already are at the base so try to avoid contact with hostile craft on your way to the attack coordinates.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 20, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 21, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 22, 'split_quest_alert', 'Brother Extok Evin: < One of our bomber squadrons have run in to an ambush, head over there and help them out! >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 23, 'split_quest_alert_fail', 'Brother Extok Evin: < One of our bomber squadrons have outflanked the Imperial defenses and may still be able to take out the base but they need help, stand by. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 24, 'title', 'Dathomir system: Attack the Inquisition''s base of operations.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4.stf', 25, 'title_d', 'The data retrieved in the previous mission points out a space station in Dathomir as the Inquisitions current base of operations. We have been busy laying out the plan of attack and your orders are to help clear out fighters before our bombers are called in.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 2, 'allies_arrived', 'Hurry over there pilot, or there won''t be anything left of our bombers!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 3, 'allies_remain', 'Brother Extok Evin: < One of our bombers have fallen! Avenge him my friends! >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 4, 'allies_win', 'Excellent! B-Wing squadron Vicious, proceed as planned. Return to base pilot.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 10, 'battle_started', 'May the force be with you my friends!'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 11, 'enemies_arrived', 'I''m getting reports of several advanced TIE ships in the enemy force, this will be rough.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 12, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy target(s) remain. >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 13, 'enemies_win', 'Pull out pilot! Hopefully some of our other bomber squadrons have had better luck.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 14, 'found_loc', 'Uploading coordinates of our ambushed bomber squadron.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 15, 'quest_findbattle_d', 'These are the coordinates the bomber squadron provided us with as a rendez-vous for any reinforcements we could send.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 16, 'quest_findbattle_t', 'Intercept coordinates.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 17, 'quest_helpallies_d', 'Assist our bombers in defeating the Imperial fighters trying to eliminate them.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 18, 'quest_helpallies_t', 'Defeat the Imperial fighters.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 19, 'quest_location_d', 'Even though we initially crippled the base defense of the Empire, they can still bite. There''s several Imperial fighters still in the area and extreme caution is my advice.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 20, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 21, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 22, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 23, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 24, 'title', 'Dathomir system: Assist ambushed bomber squadron.'),
('string/en/spacequest/space_battle/naboo_rebel_tier4_4_a.stf', 25, 'title_d', 'One of our bomber squadrons have been ambushed on their way to the base and need your immediate assistance or they will perish!'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 1, 'allies_arrived', 'We have made it to our emergency coordinates but the Rebel scum is right behind us!'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 2, 'allies_remain', 'Imperial freighter: < Ahh! Our ship is burning up! We need help n... >'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 3, 'allies_win', 'Imperial freighter: < Thank you pilot, you came just in time or we would have been done for. >'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 8, 'battle_started', 'Our systems are crippled, we''re a sitting duck out here!'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 9, 'enemies_arrived', 'Here they come! Any Imperial ship that is receiving this, please assist!'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 10, 'enemies_remain', 'Imperial freighter: < Yes! Good job pilot, only %DI of them left! >'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 11, 'enemies_win', 'Imperial freighter: < We can''t survive this, ejecting! >'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 12, 'found_loc', 'This .. an em...ency bro..ca.. We a.. under att..k by Rebel figh..rs. N..d help at th..e coor..nat.. immed..tely!'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 13, 'quest_findbattle_d', 'The freighter under attack provided the space station with these coordinates, explaining that they will try to make it there in hopes of being rescued. Get over there as quickly as you can.'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 14, 'quest_findbattle_t', 'Coordinates of attack.'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 15, 'quest_helpallies_d', 'The Imperial freighter has made it to the coordinates it provided but the Rebel scum are right on top of it. Deliver justice to the Rebel terrorists swiftly.'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 16, 'quest_helpallies_t', 'The freighter made it.'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 17, 'quest_location_d', 'This is Imperial territory and you should be safe here. The Rebels attacking freighters in this area are either really brave or really stupid, time for you to find out which.'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 18, 'quest_location_t', 'Naboo system.'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 19, 'quest_update', 'Imperial freighter: < %TO >'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 20, 'split_quest_alert', 'Imperial freighter: < I know it''s a lot to ask but we think the Rebels uncovered our Yavin freighter route and are planning an attack. Can you please deliver the message to our station in the Yavin system? >'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 22, 'title', 'Naboo system: Rescue the freighter.'),
('string/en/spacequest/space_battle/naboo_station_emperors_access_quest_1.stf', 23, 'title_d', 'The space station of Naboo received a emergency call from an Imperial freighter under attack by Rebels. You have volunteered to assist the freighter and need to hurry over to the coordinates the attacked Imperial ship provided.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 1, 'allies_arrived', 'The officers assigned to this task, the attack against the mysterious Black Nemesis, have arrived at the desginated attack point.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 2, 'allies_remain', '\\#pcontrast1 Mos Eisley Captain:\\#pcontrast3 < Pilot!! We''ve lost one of our officers! There''s only %DI left! Defend him with all your efforts! >'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 3, 'allies_win', 'Finally the freighters can travel with ease and safety. Thank you, pilot. We''ve won this day.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 8, 'battle_started', 'The battle has begun! Defeat the Black Nemesis and win the day, pilot. The officers I assigned to this mission are well-adept in flight and fighting. But they''ll need to be guarded and protected regardless. I''m counting on you.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 9, 'enemies_arrived', 'The Black Nemesis has arrived at the designated battle point. My radar detects additional enemies, however. I advise being careful, my friend.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 10, 'enemies_remain', '\\#pcontrast1 Mos Eisley Captain:\\#pcontrast3 < An enemy has been vanquished! There are %DI of them left! >'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 11, 'enemies_win', 'The Black Nemesis has defeated us! He will live on and continue to hunt our freighters until he''s stopped! We won''t give up just yet!'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 12, 'found_loc', 'I''ve transmitted the location at which the Black Nemesis has last been seen. Go there. The officers will meet you there.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 13, 'quest_findbattle_d', 'Kelen has transmitted the location at which the battle will take place.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 14, 'quest_findbattle_t', 'Find the Battle Site'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 15, 'quest_helpallies_d', 'It is your duty to help the Mos Eisley Officers defeat the Black Nemesis and restore peace and safety to the Tatoo System.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 16, 'quest_helpallies_t', 'Help the Officers'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 17, 'quest_location_d', 'Your mission takes place in the Tatoo System. Travel there and complete you mission.'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 18, 'quest_location_t', 'Travel to Tatoo System'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 19, 'quest_update', '\\#pcontrast1 Mos Eisley Captain:\\#pcontrast3 < %TO >'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 22, 'title', 'Tatoo System: The BlackDawn Existence'),
('string/en/spacequest/space_battle/poi_tatooine_general_3.stf', 23, 'title_d', 'Kelen seemed terribly bent on ridding the galaxy of the Black Nemesis, an entity that has been terrorizing many a freighter for months. You have been tasked with heading up this operation, fondly called the "BlackDawn Existence", and are expected to lead two Mis Eisley Officers into battle. Will you succeed? Only time will tell.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 1, 'allies_arrived', 'Our war ships have arrived. Stand by, pilot. We''ll need your help.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 2, 'allies_remain', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < Pilot! We lost one of our war ships! We have %DI remaining! >'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 3, 'allies_win', 'A long, hard battle won. Thank you, pilot. Soon, we''ll be able to take over the Space Station and rule the Tatoo System. I garner it will be some time, however. Your name will go down in history.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 8, 'battle_started', 'The battle has begun, pilot. Stay with us. There''s no doubt we''ll need your help weighing the odds.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 9, 'enemies_arrived', 'Pilot, stay alert. The Mos Eisley police have come to defend the Space Station against us. This will be a long battle.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 10, 'enemies_remain', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < Their numbers are dwindling. By my system''s count, there are %DI enemy ships left. >'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 11, 'enemies_win', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < We''ve lost! The Space Station has been well defended by the Mos Eisley Police. >'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 12, 'found_loc', 'Pilot, pay attention. I''m transmitting a location to you. In moments, we''ll arrive, hoping to storm the Space Station and take it over. Meet us here. We''ll no doubt need your help as we''re expecting heavy resistance. >'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 13, 'quest_findbattle_d', 'Travel to the waypoint given to you by Garett and participate in the battle between the Hutts and the Mos Eisley Police.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 14, 'quest_findbattle_t', 'Find the battle at Hutt Claims'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 15, 'quest_helpallies_d', 'After having arrived at the waypoint given, help your allies defeat the Mos Eisley Police and capture the Space Station.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 16, 'quest_helpallies_t', 'Help Your Allies'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 17, 'quest_location_d', 'Travel to the Tatoo System for your mission.'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 18, 'quest_location_t', 'Tatoo System'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 19, 'quest_update', '\\#pcontrast1 Hutt Informant:\\#pcontrast3 < %TO >'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 22, 'title', 'Tatoo System: Attack on the Space Station'),
('string/en/spacequest/space_battle/poi_tatooine_privateer_3_b.stf', 23, 'title_d', 'The time is near and the attack on the Space Station is imminent. Your part in this crazy scheme is to assist the Hutts, driving them to victory. After all this time, one question floats in your mind; what exactly are you going to get out of this? Tax breaks on repairs in Tatooine? A percentage of the revenue made by the Space Station? Or a lousy shirt? And why do the Hutts want to attack a Space Station anyway? It doesn''t take you long to figure out and understand the lure of the credit.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 1, 'allies_arrived', 'Our fleet is assembled. We expect the Greenburst to show up at any time now.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 2, 'allies_remain', 'Tactical Computer: < %DI freighters remaining. >'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 3, 'allies_win', 'Nice work, pilot. Our fleet is mostly intact and the Greenburst have been taught an important lesson.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 8, 'battle_started', 'The Greenburst have given up peaceful protest and are now attacking our freighters.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 9, 'enemies_arrived', 'The Greenburst have arrived. They look like they want trouble.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 10, 'enemies_remain', 'Tactical Computer: < %DI enemy fighters remaining. >'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 11, 'enemies_win', 'You lost to a bunch of protesters? That not only cost you pride it cost us five freighters.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 12, 'found_loc', 'The freighter convoy will assemble at this point. Meet them there.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 13, 'quest_findbattle_d', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 14, 'quest_findbattle_t', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 15, 'quest_helpallies_d', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 16, 'quest_helpallies_t', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 17, 'quest_location_d', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 18, 'quest_location_t', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 19, 'quest_update', 'Twin Star Shipping: < %TO >'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 20, 'split_quest_alert', 'Ok, now for your last task, you need to travel to Yavin and see if you can find one of Twin Star''s freighters that has been overdue for the past day.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 22, 'title', 'Endor System: Protect Twin Star Shipping'),
('string/en/spacequest/space_battle/stn_dantooine_owner_all_repairmission_tier2_4.stf', 23, 'title_d', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 1, 'allies_arrived', 'I have a lock on some of my supply fleet. They look pretty beat up but they are intact. Get to them fast and take out any Imperials that try to destroy them.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 2, 'allies_remain', 'Tactical Computer: < %DI freighters remaining. >'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 3, 'allies_win', 'Great work. I am going to tell those ships to get out of there before anymore Imperials show up.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 8, 'battle_started', 'The Imperials are attacking my fleet! You have to protect those unarmed freighters from the TIEs.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 9, 'enemies_arrived', 'I am now picking up Imperial fighters moving towards the supply fleet at attack speeds. Protect those freighters!'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 10, 'enemies_remain', 'Tactical Computer: < %DI enemy fighters remaining. >'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 11, 'enemies_win', 'Well there went some very valuable ships. I really hope your Rebellion does better protecting its own interests then you did mine.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 12, 'found_loc', 'I have a lock on the supply fleet. Sending you the location now.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 13, 'quest_findbattle_d', 'Travel to the supply fleet and protect them from the Imperial fighters.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 14, 'quest_findbattle_t', 'Travel to the Supply Fleet'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 15, 'quest_helpallies_d', 'Destroy the Imperial fighters before they destroy the supply fleet.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 16, 'quest_helpallies_t', 'Defeat the Imperial Attackers'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 17, 'quest_location_d', 'The supply fleet is located inside of the Dantooine system.'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 18, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 19, 'quest_update', 'Dantooine Station: < %TO >'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 22, 'title', 'Dantooine System: Protect the Supply Fleet'),
('string/en/spacequest/space_battle/stn_dantooine_owner_rebel_landing_tier2_2.stf', 23, 'title_d', 'The Imperials are attacking some of the Dantooine station''s supply fleet in retaliation for the loss of one of the freighters. Protect the supply fleet from the Imperial attack.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 1, 'allies_arrived', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Friendly IFF signatures detected. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 2, 'allies_remain', '\\#pcontrast1 An allied craft has been destroyed, %DI remain.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 3, 'allies_win', 'The spice pirates have been driven back.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 5, 'autorewardbody', 'Completion Bonus: The Ends of Understanding (5000)'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 6, 'autorewardfrom', 'Endor Station'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 7, 'autorewardsubject', 'The Grand Tour'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 8, 'battle_started', 'The battle has begun.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 9, 'enemies_arrived', '\\#pcontrast3 Tactical Computer: < \\#pcontrast3 Targets locked in. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 10, 'enemies_remain', '\\#pcontrast3 An enemy craft has been destroyed, %DI remain.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 11, 'enemies_win', '\\#pcontrast3 Endor Station: < \\#pcontrast1 Much knowledge has been lost for this.  Our future will be a less enlightened place. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 12, 'found_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Engagement location locked in. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 13, 'quest_findbattle_d', 'Travel to the fight location quickly, forces have already engaged.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 14, 'quest_findbattle_t', 'Travel'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 15, 'quest_helpallies_d', 'Protect the scientists from the Zynt`aia Spice Guardians.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 16, 'quest_helpallies_t', 'Linear Scientists'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 17, 'quest_location_d', 'The confortation comes to a head not far from the heart of the nebula.'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 18, 'quest_location_t', 'Endor System'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 19, 'quest_update', '%TO'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 20, 'split_quest_alert', '\\#pcontrast3 Endor Station: \\#pcontrast1 The next stop is the Declorian Territory, meeting area for the Zynt''aia Spice Pirates. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 22, 'title', 'Endor System: The Ends of Understanding'),
('string/en/spacequest/space_battle/stn_endor_irs_imp_tier3_3d.stf', 23, 'title_d', 'Spice pirates have attacked the researchers operating out of the Linear Miasma.  Move in to assist the scientists against the pirate agression.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 1, 'allies_arrived', 'We are picking up distress signals from one of our convoys. They are under heavy fire from those strange fighters.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 2, 'allies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < %DI freighters remaining. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 3, 'allies_win', 'Excellent work, pilot. You managed to at least save some of the fleet.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 8, 'battle_started', 'Enemy fighters are swarming all over our convoy. They are in desperate need of your assistance.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 9, 'enemies_arrived', 'The enemy fighters have called in some backup. Our freighters are not going to last much longer.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 10, 'enemies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < %DI enemy fighters remaining. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 11, 'enemies_win', 'The Yavin Mining Company freighters have all been destroyed.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 12, 'found_loc', 'We are sending you the location of the distress signal from the freighters. Travel to them immediately and drive off their attackers before the convoy is destroyed.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 13, 'quest_findbattle_d', 'The company has supplied you with the location of the distress signal. Travel to this location and rescue the shipping convoy.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 14, 'quest_findbattle_t', 'Travel to the Attack Site'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 15, 'quest_helpallies_d', 'Destroy the mysterious attackers before they can destroy the shipping convoy.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 16, 'quest_helpallies_t', 'Rescue the Shipping Convoy'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 17, 'quest_location_d', 'The shipping convoy is located in the Yavin system.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 18, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 19, 'quest_update', '\\#FF0000 Yavin Mining Company:\\#FF0000 < %TO >'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 20, 'split_quest_alert', 'We are picking up the signature of a damaged enemy fighter who is trying to escape from the battle. Intercept and inspect that fighter for any clue to their identity and why they attacking our ships. Return to the station when you have completed your search.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 21, 'split_quest_alert_fail', 'It is unfortunate that we lost the convoy but we are picking up a plasma trail from one of the fighters. It must be damaged. Follow that plasma leak and inspect that damaged fighter for any clues.'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 22, 'title', 'Space Yavin: Rescue Mining Fleet Under Attack'),
('string/en/spacequest/space_battle/stn_yavin4_company_all_massassi_tier2_1.stf', 23, 'title_d', 'A Yavin 4 Mining Company shipping convoy has come under fire from a mysterious assailant. The company has hired you to rescue its fleet and discover more information about these attackers.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 2, 'allies_arrived', '3rd TIE Wing located. Scans indicate heavy casualties.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 3, 'allies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI allied fighters remaining.>'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 4, 'allies_remaining', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 5, 'allies_win', 'Excellent work, pilot. The Rebel scum have all been eliminated, thanks to you. Return to your superior and make your report.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 10, 'battle_abandoned', 'The 3rd TIE Wing doesn''t stand a chance without your help. You have failed the Empire this day.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 11, 'battle_started', '3rd TIE Wing engaging enemy fighters.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 12, 'enemies_arrived', 'Enemy fighter located. Closing at high speeds.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 13, 'enemies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI enemy fighters remaining.>'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 14, 'enemies_remaining', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 15, 'enemies_win', 'Imperial High Command:<We have lost the 3rd TIE Wing. Report back to your superior for a full report.>'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 16, 'found_loc', 'Updating your nav computer with the last known location of the 3rd TIE Wing. Travel there immediately and support those fighters.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 17, 'quest_findbattle_d', 'Travel to the supplied navigation waypoint that will be given to you. This waypoint will lead you to the location that the battle will take place.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 18, 'quest_findbattle_t', 'Travel to the Battle Location'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 19, 'quest_helpallies_d', 'Once at the battle location, wait for the arrival of the TIE wing and for the battle to start. Destroy all of the attacking Rebels before they can destroy all of the TIEs. The TIEs are outnumbered so your assistance is important.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 20, 'quest_helpallies_t', 'Help the TIE Wing Defeat the Rebels'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 21, 'quest_location_d', 'Remain in the Endor system and assist the TIE wing in destroying the attacking Rebels. Travel to the navigation waypoint that you will receive to the battle location.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 22, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 23, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 24, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 25, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 26, 'title', 'Endor System: Battle the Rebel Forces'),
('string/en/spacequest/space_battle/tatooine_imperial_tier3_2_e.stf', 27, 'title_d', 'Remain in the Endor system and help our TIE wing beat the Rebels in a battle. You will receive a navigation waypoint to the place where the battle is going to take place. Travel to this location and wait for the arrival of the TIEs and Rebels. When the battle is joined, assist the TIE wing with destroying  the Rebel force before the Rebels can wipe out the TIE wing. If all of the TIEs die then you will have lost the battle.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 2, 'allies_arrived', 'Allied TIE fighters regrouping to try to fend off the Rebel assault.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 3, 'allies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI allied fighters remaining.>'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 4, 'allies_remaining', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 5, 'allies_win', 'You have handed the Empire a glorious victory over the Rebellion.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 7, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 8, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 9, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 10, 'battle_abandoned', 'You have left the TIE defense force at the mercy of our enemies. The Empire does not tolerate cowards. Report back to your superior.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 11, 'battle_started', 'The enemy has engaged the TIE fighters.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 12, 'enemies_arrived', 'Warning! Enemy fighters detected.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 13, 'enemies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI enemy fighters remaining.>'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 14, 'enemies_remaining', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 15, 'enemies_win', 'The wing has been destroyed. The Rebellion may have won this battle but they have not won the war. Return to your superior officer.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 16, 'found_loc', 'We have the location of the besieged TIEs. Travel to the navigation waypoint immediately and protect those fighters.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 17, 'quest_findbattle_d', 'Travel to the navigaiton waypoint and join up with the TIE squadron.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 18, 'quest_findbattle_t', 'Travel to the Battle Location'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 19, 'quest_helpallies_d', 'You must destroy the Rebel attackers before they can eliminate the remaining TIE fighters.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 20, 'quest_helpallies_t', 'Help the TIEs Defeat the Rebel Forces'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 21, 'quest_location_d', 'The navigation waypoint to the TIEs rally point will be supplied to you.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 22, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 23, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO> \\#pcontrast3 '),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 24, 'split_quest_alert', 'An enemy scout vessel has been detected in the area. Disable that scout and recover the contents of its main frame.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 25, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 26, 'title', 'Endor System: Battle the Rebel Forces'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_1_b.stf', 27, 'title_d', 'The Rebels have launched an attack on the local TIE defense force. The TIE force has been badly hurt and are now regrouping for a final stand. Those fighters are vital to the operations in the Endor system and need to be protected. You must save the TIEs.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_3_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_3_b.stf', 2, 'allies_arrived', 'TIE forces regrouping to defend against hostiles.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_3_b.stf', 3, 'allies_remain', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <%DI allied fighters remaining.>'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_3_b.stf', 4, 'allies_remaining', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_3_b.stf', 5, 'allies_win', 'All enemy fighters eliminated. Grey Squadron still intact. Report in to your superior.'),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_3_b.stf', 6, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_imperial_tier4_3_b.stf', 7, 'autorewardbody', ''),
