('string/en/spacequest/space_battle/tatooine_privateer_tier3_4_b.stf', 26, 'title_d', 'Destroy the Rancor Clan, and keep an eye out for the Lambda Shuttle with a Sienar Systems engineer on board'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 1, 'allies_arrived', 'Good to see you pilot. We were on our way to bomb some Imperial Freighters but were spotted by those fighters.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 2, 'allies_remain', 'Crimson Squadron Leader: < We are taking heavy losses, this is looking grim. Step it up everyone! >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 3, 'allies_win', 'Excellent, we will continue to our original target, you can return to base. Thanks again pilot.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 9, 'battle_started', 'Here they come! Crimson squad, anti fighter battle plan razor. May the Force be with you all!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 10, 'enemies_arrived', 'There they are, we have no choice but to try and fight our way through them.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 11, 'enemies_remain', 'Crimson Squadron Leader: < Excellent! Only %DI more! >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 12, 'enemies_win', 'Get out of here pilot! The mission is a failure, we are taking heavy lo...'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 13, 'found_loc', 'Meet with the B-Wing squad at this location pilot. Hurry, the TIE Fighters following them are getting closer by the second.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 14, 'quest_findbattle_d', 'The B-Wing squadron estimate that they will be intercepted by the Imperial fighters near these coordinates. Get over there ASAP pilot!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 15, 'quest_findbattle_t', 'Rendez-vous coordinates.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 16, 'quest_helpallies_d', 'B-Wings are designed to eliminate capital ships and space stations. When they come under fire from massed forces of fighters, they are in trouble. That''s where you come in pilot, help them break through the Imperial forces.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 17, 'quest_helpallies_t', 'Assist the Crimson Squadron.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 18, 'quest_location_d', 'Though the Dantooine system doesn''t have a heavy presence of Imperial forces, this area is one that they are controlling. Try to avoid getting the attention of more enemy forces on your way to the B-Wing squadron.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 19, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 20, 'quest_update', 'Crimson Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 23, 'title', 'Dantooine system: Assist B-Wing Bomber squad in eliminating intercepting TIE Fighters.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_2_c.stf', 24, 'title_d', 'A squad of B-Wing bombers were on their way to attack some Imperial freighters but were spotted by a TIE wing. Assist them in eliminating the Imperial fighters.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 1, 'allies_arrived', 'Good to see you pilot. I heard you were good, will be a pleasure to work with you.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 2, 'allies_remain', 'Scythe Squadron Leader: < Ack, you Imperial scum, we will avenge him! >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 3, 'allies_win', 'That should make the Empire think twice before messing with us again!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 5, 'autorewardbody', ''),
