('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 9, 'battle_started', 'Don''t let them get a chance to figure out what''s going on, attack, attack!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 10, 'enemies_arrived', 'Here they come, prepare for battle everyone.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 11, 'enemies_remain', 'Rebel Command: < Good, sensors indicate %DI more Imperial ships in the area. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 12, 'enemies_win', 'Pull out pilot! We are doome..'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 13, 'found_loc', 'Greetings, proceed to this location and assist us in terminating one of the Imperial Patrols.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 14, 'quest_findbattle_d', 'The X-Wing squadron codenamed Scythe have set these coordinates as their point of attack. Meet up with them there immediately.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 15, 'quest_findbattle_t', 'Battle coordinates.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 16, 'quest_helpallies_d', 'With Scythe squadron at your side, bring some punishment on the Imperial filth.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 17, 'quest_helpallies_t', 'Defeat the Imperial patrol.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 18, 'quest_location_d', 'With our successful attacks in the Dathomir system lately, the Empire has increased their alert status and the system is more dangerous than ever. Avoid attracting any extra attention at all costs while you are on your way to meet up with the X-Wing squadron.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 19, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 20, 'quest_update', 'Scythe Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 21, 'split_quest_alert', 'Rebel Command: < The Commando team sent to break out the defector need your help again, stand by for more information. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 23, 'title', 'Dathomir system: Terminate the Imperial patrol.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_3_a.stf', 24, 'title_d', 'One of our X-Wing squadrons has been ordered to eliminate one of the Empire''s guard patrols. The patrol turned out to be a bit larger than expected so they could use your assistance.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 2, 'allies_arrived', 'Good to see you again pilot! Lets see what this new fighter of theirs can do.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 3, 'allies_remain', 'Rebel pilot: < Taking heavy fire! Need help over he... >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 4, 'allies_win', 'I think they need to put that thing back in the garage for some more improvements. Return to base everyone, great job!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 10, 'battle_started', 'Lets show them that it doesn''t matter what new ships they have, our skill is superior!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 11, 'enemies_arrived', 'The Imperial ships have detected us but they don''t appear to withdraw, I guess they have trust in the capabilities of that new ship.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 12, 'enemies_remain', 'Tactical Computer: < Sensors show termination of enemy vessel. %DI enemy vessels remain. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 13, 'enemies_win', 'Pull out pilot, pull ou...'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 14, 'found_loc', 'The Empire is having a test of one of their new fighters at this location. We could use your help over here pilot.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 15, 'quest_findbattle_d', 'These are the coordinates supplied by our reconnaissance ship. The X-Wing squadron assisting you in the attack will meet you there.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 16, 'quest_findbattle_t', 'Battle coordinates.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 17, 'quest_helpallies_d', 'Destroy all the Imperial forces in the vicinity. We can''t take the risk of capturing that prototype fighter intact in such a hostile area, we''ll just examine the debris after you have blown it to pieces.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 18, 'quest_helpallies_t', 'Destroy the Imperial forces.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 19, 'quest_location_d', 'You''re heading back in to the areas heavily defended by Imperial forces. The good news is you will have reinforcements with you, the bad news is that you will fight a prototype fighter that may turn out to be very dangerous.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 20, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 21, 'quest_update', 'Scythe Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 22, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 23, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 24, 'title', 'Endor system: Help a Rebel Squadron fight the Empires prototype fighter.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier3_4_d.stf', 25, 'title_d', 'One of our reconnaissance ships spotted one of these new prototype fighters of the Empire. We''ve decided to launch an attack and try to find out as much as we can about the ship from its debris. You''re ordered to assist in the attack pilot.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 2, 'allies_arrived', 'We are in position, join up pilot.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 3, 'allies_remain', 'Rebel Pilot: < My baby is falling apart! Ejecting! >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 4, 'allies_win', 'That''s the best the Empire has? Pathetic.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 5, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 9, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 10, 'battle_started', 'Lets show these fools how it''s really done. Attack pattern V!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 11, 'enemies_arrived', 'Greetings pilot, enemy presence is confirmed at the correct coordinates. Proceed as planned.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 12, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy targets remain. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 13, 'enemies_win', 'Pull out, pull out! We can''t w.. this! Reg..up n..'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 14, 'found_loc', 'Proceed to these coordinates and join up with us, on the double!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 15, 'quest_findbattle_d', 'The coordinates to the Imperial training area should now be in your nav computer. Approach with care but be swift, the rest of the squad will join up with you near these coordinates.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 16, 'quest_findbattle_t', 'Imperial training area.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 17, 'quest_helpallies_d', 'Show the rest of the squad that you belong here pilot. Assist them in decimating the Imperial fools!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 18, 'quest_helpallies_t', 'Attack the Imperial scum!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 19, 'quest_location_d', 'The Dathomir system is always considered a high-risk system. It''s extremely well guarded by the Empire and only the craziest or best pilots not belonging to the Empire travels there, which makes it even more dangerous. To make it worse, you''re heading in to Imperial areas.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 20, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 21, 'quest_update', 'Crimson Phoenix Squadron Leader: < %TO >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 22, 'split_quest_alert', 'General Ufwol: < The Empire is scattering their forces. Lets drive the nail in further, stand by for assignments. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 23, 'split_quest_alert_fail', 'General Ufwol: < You need to get out of there! We''re uploading the pre-planned escape route to your nav computer now. Get ready to move! >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 24, 'title', 'Dathomir system: Attack the Empires advanced fighters.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_1.stf', 25, 'title_d', 'The Empire is testing out some of their new ships, lets give them a training they won''t forget.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 1, 'allies_arrived', 'Our fighter squadron has arrived, join up as fast as you can.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 2, 'allies_remain', 'Rebel Pilot: < Phew that was a close one! Alright, now I just need to shake this...ack! Nooo... >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 3, 'allies_win', 'Good job, pull back for a breather. The bomber squadron will take it from here.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 9, 'battle_started', 'It''s time men, give them all you got!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 10, 'enemies_arrived', 'Your task here is to pave the way for our bombers through their fighters.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 11, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy targets remain. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 12, 'enemies_win', 'I''m giving the bombers an abort order, we are taking too heavy losses!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 13, 'found_loc', 'Proceed to these coordinates pilot, the rest of the squadron will meet you there.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 14, 'quest_findbattle_d', 'These are the coordinates of attack. The rest of the squadron will meet you close to this location. Make your way there with haste.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 15, 'quest_findbattle_t', 'Coordinates of attack.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 16, 'quest_helpallies_d', 'With the rest of the squadron, take out the fighter defense of the Imperial space station so that our bombers can make it through.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 17, 'quest_helpallies_t', 'Destroy the ships fighter defense.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 18, 'quest_location_d', 'We are not sure why the Empire has such a large part of their navy stationed in the Endor system but it makes it a dangerous place for us. It''s our hope that there''s so many of them here because they are manufacturing these new advanced TIE''s in this system.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 19, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 20, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 21, 'split_quest_alert', 'General Ufwol: < I have intel data incoming, stand by for further orders. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 22, 'split_quest_alert_fail', 'General Ufwol: < Blast! The Empire has launched a bomber wing toward one of our frigates that are trying to pull out of the area. Stand by for new orders. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 23, 'title', 'Endor system: Defeat Imperial space station guard.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_3.stf', 24, 'title_d', 'Unfortunately examining the stolen TIE Oppressor didn''t give us any useful information about its origin. A lot of these new prototype ships have been deployed in the Endor system though so it''s our suspicion that they may be manufactured there. We are about to launch a attack on one of the Imperial outposts in the system and Crimson Phoenix have been ordered to help clean out the base defensive fighters.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 1, 'allies_arrived', 'The rest of the squadron is here, join up with them quickly and prepare to attack.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 2, 'allies_remain', 'Rebel Pilot: < My ship is falling apart, I need help! They are all ove... >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 3, 'allies_win', 'And that my friends is why we are considered the best of the best. I''m proud of you all.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 8, 'battle_abandoned', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 9, 'battle_started', 'Remember your training men and as some people would say, may the force be with you. Attack!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 10, 'enemies_arrived', 'We have confirmed the enemies presence in this area.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 11, 'enemies_remain', 'Tactical Computer: < Sensors show enemy target terminated. %DI enemy targets remain. >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 12, 'enemies_win', 'Retreat, retreat! Those new ships are beasts, we need to come up with new strategies before we try this again.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 13, 'found_loc', 'One of Nym''s smugglers spotted the new TIE ship in this area. We''re sending in the rest of the squadron to assist you.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 14, 'quest_findbattle_d', 'The squadron will rally close to these coordinates and attack the enemy forces. Proceed to there with haste but use caution.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 15, 'quest_findbattle_t', 'Battle coordinates.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 16, 'quest_helpallies_d', 'Show these Imperial scum that the Crimson Phoenix fear no one, eliminate all of their forces in the area!'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 17, 'quest_helpallies_t', 'The Crimson Phoenix attacks.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 18, 'quest_location_d', 'You know the drill in the Dathomir system, extreme caution at all times. The target of attack is deep inside Imperial territory so be very careful approaching it, we don''t want to lead more enemies over to the battle.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 19, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 20, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 23, 'title', 'Dathomir system: Defeat one of the Empires experimental ships.'),
('string/en/spacequest/space_battle/tatooine_rebel_tier4_4_b.stf', 24, 'title_d', 'We have found another of the new ships that you just encountered. Seeing how they were so dangerous, we are sending the squadron to assist you in bringing it down. We will keep monitoring it during the battle to try and find out as much as we can about it.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 1, 'allies_arrived', 'To any nearby Valarian pilots! We have been ambushed and need assistance quickly! Our coordinates are...'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 2, 'allies_remain', 'Valarian Smuggler: < Ahh! My ship is falling apart! Eje... >'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 3, 'allies_win', 'Thank you pilot, I thought I was done for!'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 4, 'assigned_delayed', ''),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 8, 'battle_started', 'Here they come! We will try to hold out for as long as we can but we need help now!'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 9, 'enemies_arrived', 'They are right on top of us! Please, someone, we need help!'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 10, 'enemies_remain', 'Valarian Smuggler: < Haha! Take that you Hutt scum! >'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 11, 'enemies_win', 'Pull out of there pilot! That battle is lost!'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 12, 'found_loc', '...eavy attack! We n... hel... Heading for th... coor...'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 13, 'quest_findbattle_d', 'The Valarian smugglers are trying to make it to these coordinates in hope that someone will assist them there. Get over there quickly before they are annihilated.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 14, 'quest_findbattle_t', 'Ambush coordinates.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 15, 'quest_helpallies_d', 'Although it doesn''t look like Hortrix is part of the ambush force, you should assist the smugglers and save them from the Hutt scum.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 16, 'quest_helpallies_t', 'Save the smugglers.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 17, 'quest_location_d', 'If you''re a enemy of the Empire, the Yavin system should be considered very dangerous as they are widespread through out the system. There''s also a number of smugglers, bounty hunters and pirates trying to scavenge parts of the large debris field in the system and they are not afraid to prey on targets of opportunity.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 18, 'quest_location_t', 'Yavin system.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 19, 'quest_update', 'Valarian smuggler: < %TO >'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 20, 'split_quest_alert', 'Tactical Computer: < Scans show ship signature of vessel Scythe IV. Registered owner: Chiss male known as Hortrix Steelarm. >'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 21, 'split_quest_alert_fail', 'Tactical Computer: < Scans show ship signature of vessel Scythe IV. Registered owner: Chiss male known as Hortrix Steelarm. >'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 22, 'title', 'Yavin system: Save the Valarian smugglers.'),
('string/en/spacequest/space_battle/tatooine_station_hutt_palace_access_quest_3.stf', 23, 'title_d', 'Hortrix Steelarm has planned a ambush on some Valarian smugglers in the Yavin system and your employer think he knows here. Just as he''s about to give you the coordinates you receive a distress call from one of the smugglers, the ambush is already taking place!'),
('string/en/spacequest/space_battle/test_space_battle.stf', 1, 'actually_you_suck', 'U suxxor.'),
('string/en/spacequest/space_battle/test_space_battle.stf', 2, 'allies_arrived', 'The TIE fighters have exited lightspeed.'),
('string/en/spacequest/space_battle/test_space_battle.stf', 3, 'allies_remain', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 %DI allies remain. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/test_space_battle.stf', 4, 'allies_win', 'The Rebels have been defeated.'),
