('string/en/spacequest/space_battle/test_space_battle.stf', 10, 'battle_started', 'Let''s get ready to ruuuumble!'),
('string/en/spacequest/space_battle/test_space_battle.stf', 11, 'die', 'Waste the rebs! DIE!@#$@'),
('string/en/spacequest/space_battle/test_space_battle.stf', 12, 'enemies_arrived', 'The Rebels are here! Prepare for their attack!'),
('string/en/spacequest/space_battle/test_space_battle.stf', 13, 'enemies_remain', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 %DI enemies remain. \\#pcontrast3 >'),
('string/en/spacequest/space_battle/test_space_battle.stf', 14, 'enemies_win', 'You''ve sustained too many loses. Retreat!'),
('string/en/spacequest/space_battle/test_space_battle.stf', 15, 'found_loc', 'The Rebels will be here soon! We''re dispatching a group of TIE fighters to assist you. Head to your new waypoint to meet them.'),
('string/en/spacequest/space_battle/test_space_battle.stf', 16, 'gonna_kill_u', 'I''m gonna kill u Rebs.'),
('string/en/spacequest/space_battle/test_space_battle.stf', 17, 'lets_go', 'Let''s go, punk.'),
('string/en/spacequest/space_battle/test_space_battle.stf', 18, 'no_you_suck', 'East Side!!!!'),
('string/en/spacequest/space_battle/test_space_battle.stf', 19, 'quest_findbattle_d', '3'),
('string/en/spacequest/space_battle/test_space_battle.stf', 20, 'quest_findbattle_t', '3'),
