('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 2, 'arrived_at_loc', 'Stand by to begin your transmission. Once that starts prepare for Nym''s pirates to storm in. You will have to stay in the area until the entire broadcast is complete in order to get everyones attention.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 9, 'first_attack', 'Looks like you got the pirates attention. Defend yourself but do not leave the area.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 10, 'found_loc', 'This is the location from which you should broadcast. This should get all of Nym''s attention.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 11, 'mission_complete', 'Broadcast complete. Interception of pirate chatter shows that you did gather alot of attention.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 12, 'outofrange', 'You have moved to far away from location to broadcast correctly. Move back in range immediately.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 13, 'outofrange_failed', 'Broadcast ceased. Interception of pirate chatter shows that you failed to gather much attention.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 14, 'quest_defendpoint_d', 'Once you have started it is important that you completely finish the entire broadcast in order to reach the maximum number of Nym''s vessels. Protect yourself from any incoming fighters but do not leave the region until it is completed.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 15, 'quest_defendpoint_t', 'Defend the Broadcast Location'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 16, 'quest_location_d', 'The perfect broadcast point has been located in the Yavin system. It will reach the maximum number of Nym''s ships. Unfortunately this means it also has the maximum amount of risk because there will be more vessels coming to investigate.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 17, 'quest_location_t', 'Remain in Yavin System'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 18, 'quest_reachpoint_d', 'Travel to the navigaiton waypoint supplied to you and wait until the broadcast begins.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 19, 'quest_reachpoint_t', 'Start the Broadcast Operation'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 20, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 21, 'split_quest_alert', 'The captured Hutt smuggler has been refit and set up on autopilot. We are going to fly it through Nym''s space. Your fighter should be masked sufficently by the larger smuggler vessel that you will be able to strike at the pirates as they investigate the smuggler. This should convince Nym that the Hutts are behind all this.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 23, 'title', 'Yavin System: Broadcasting in Nym''s Space'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 24, 'title_d', 'The next stage of the plan is to move into an area that the Hutts and Nym have agreed belongs to Nym. Once in this region you will begin transmitting Hutt signals. This will cause Nym to send his men in to investigate why a Hutt vessel is in his area. You are then to destroy as many of Nym''s men as you can while continueing to broadcast. When enough of Nym''s men have heard the broadcast, they should be very aggrevated and quite confused as to what the Hutts are doing.'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 25, 'trans_update', 'Transmission Update: <%DI percent of broadcast completed.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 26, 'transmission_received', 'Transmission Update: <Broadcast across Nym''s space is completed. Stand by for further instructions.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_2_a.stf', 27, 'transmission_start', 'Transmission Update: <Beginning broadcast on Hutt frequency.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 1, 'arrived_at_loc', 'You are at the survival location'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 2, 'assigned_delayed', 'Go to this location and defeat all attackers.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 3, 'attack_notify', 'Fighter wave incoming'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 4, 'attack_stopped', 'Wave is defeated'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 5, 'autorewardbody', ''),
