('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 9, 'found_loc', 'Wayping updated'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 10, 'mission_complete', 'Mission is a success'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 11, 'outofrange', 'You are moving out of range, return to the waypoint.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 12, 'outofrange_failed', 'You have failed for moving too far.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 13, 'quest_defendpoint_d', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 14, 'quest_defendpoint_t', ''),
