('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 19, 'quest_update', '%TO'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 20, 'split_quest_alert', 'Splitquest warning'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 21, 'title', 'Survival'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 22, 'title_d', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 23, 'trans_update', '%DI/600 Seconds have passed.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 24, 'transmission_received', 'Timer is compleated.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4e.stf', 25, 'transmission_start', 'The transmission has begun.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 2, 'arrived_at_loc', 'Stand by at this location. Nym''s pirates are on an interception course.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters incoming.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 9, 'first_attack', 'Keep your eyes peeled. Enemy fighters are heading right at you.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 10, 'found_loc', 'Travel to the location supplied to your navigation computer. This is far enough away that Nym''s fighters will not be able to make it back to protect their freighters until it is too late.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 11, 'mission_complete', 'Our mission was a complete success. Nym''s smuggler fleet has been sustained heavy loses.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 12, 'outofrange', 'You have moved out of optimum target range. Return immediately.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 13, 'outofrange_failed', 'Nym''s pirates have called off their attack on you and have returned to protect their smuggler fleet. Operation is a failure. Report in to your superior.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 14, 'quest_defendpoint_d', 'It will take some time for the fighters guarding the freighters to receive the transmission so you will have to remain at that point until they are committed. Remain by the transmission point but you will need to defend yourself to the upmost from all the attention you will receive.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 15, 'quest_defendpoint_t', 'Defend the Transmission Point'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 16, 'quest_location_d', 'The designated transmission point will be supplied to your navigaiton computer.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 17, 'quest_location_t', 'Remain in the Lok System'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 18, 'quest_reachpoint_d', 'Travel to the transmission point and wait for the broadcast to begin. With any luck Nym''s fighters will be drawn to you like moths to a flame.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 19, 'quest_reachpoint_t', 'Travel to the Transmission Point'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 20, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 21, 'split_quest_alert', 'Nym has been sent a message and it is time for you to put the period on it. Nym recieved a gift from his Rebel friends in the form of a ship. Your assignment is to destoy that ship.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 23, 'title', 'Lok System: Getting Nym''s Attention'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 24, 'title_d', 'Black Epsilon wants to get a crack at bombing Nym''s freighters. They are heavily guarded but if you were to draw off the fighters we would be able to launch our attack. You are to begin a transmission of your presence far from the freighter fleet. You will have to remain in that area for a long time in order to get the attention of Nym''s fighters. You will most likely get alot of attention but with any luck you will be able to pull the escorts away from the freighters and we can hit that fleet with our bombers.'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 25, 'trans_update', 'Mission Update: <Bomber group %DI percent of the way to Nym''s smuggler fleet.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 26, 'transmission_received', 'Mission Update: <Bombers attacking Nym''s smuggler fleet. Mission successful.>'),
('string/en/spacequest/survival/corellia_imperial_tier3_4_b.stf', 27, 'transmission_start', 'Mission Update: <Bombers are beginning to make their attack run.>'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 2, 'arrived_at_loc', 'You have arrived at the location. Tune into the frequency and stand by to see if you start receiving a signal.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Alert! Enemy vessels detecting incoming at attack speeds.>'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy wave eliminated.>'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 9, 'first_attack', 'Be on the alert, pilot. Enemy fighters are heading your way at attack speeds. Remain around your current location until that transmission is completed. We have to know what it says.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 10, 'found_loc', 'Coordinates loaded into your nav computer. Proceed to location and see if you can locate a signal.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 11, 'mission_complete', 'The transmission has been completed. Return to home base and see if your superior can make sense out of it.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 12, 'outofrange', 'You have lost the signal. Return to the transmission location immediately.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 13, 'outofrange_failed', 'You were unable to reestablish a transmission link. Report back to your commanding officer.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 14, 'quest_defendpoint_d', 'Remain at the location until you completely receive the message. If the Velocity are watching this location you can expect company. Do not leave the area until you have the message. Once you have this information report back to Insurgent.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 15, 'quest_defendpoint_t', 'Defend the Transmission Point'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 16, 'quest_location_d', 'The location is inside the Dantooine system.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 17, 'quest_location_t', 'Remain in the Dantooine System'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 18, 'quest_reachpoint_d', 'Once you have arrived at the location wait to tune into the frequency and see what you can pick up.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 19, 'quest_reachpoint_t', 'Begin to Tap into Enemy Communication'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 20, 'quest_update', '\\#pcontrast1 Black Epsilon Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 23, 'title', 'Dantooine System: Tap into Enemy Communications'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 24, 'title_d', 'The location and frequency discoverd on the captain''s fighter must be investigated. Travel to the location and tune into the frequency to see what you can find out.'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 25, 'trans_update', 'Transmission Update: <%DI percent of the transmission downloaded.>'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 26, 'transmission_received', 'Transmission Update: <Transmission Received. It would seem all the mercenary fighters are to continue their harassment of Imperial interests in this sector until further notified.>'),
('string/en/spacequest/survival/corellia_imperial_tier4_1_b.stf', 27, 'transmission_start', 'Transmission Update: <We have located some chatter on the frequency indicated in the officer''s records. Beginning to download transmission.>'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 2, 'arrived_at_loc', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Enemy ships dropping out of hyperspace.  Stay at this location at all costs \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 4, 'attack_notify', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy ships detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 5, 'attack_stopped', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Scanning... No enemies detected in system. Scanning ... \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 9, 'first_attack', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hyperspace surge detected. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 10, 'found_loc', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Excellent, the counter attack has been scrambled.  Go to this position, it will cause the attack craft to make multiple jumps and stagger the assault. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 11, 'mission_complete', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 That appears to be the last of them. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 12, 'outofrange', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 You are leaving the ambush area, stay on target. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 13, 'outofrange_failed', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 The Black Sun have detected our movements and are breaking the ambush, our mission has failed. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 14, 'quest_defendpoint_d', 'You must survive the onslaught over a period of several minutes'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 15, 'quest_defendpoint_t', 'Survive'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 16, 'quest_location_d', 'An area of near disorder near the planet of Dathomir'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 17, 'quest_location_t', 'Dathomir System'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 18, 'quest_reachpoint_d', 'Travel to this point for the confrontation, it will keep the whole attacking fleet from assaulting at once'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 19, 'quest_reachpoint_t', 'Battlepoint'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 20, 'quest_update', '\\#pcontrast3 < \\#pcontrast1%TO \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 21, 'split_quest_alert', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 We''re very impressed! Good work, pilot. Now that we have the weapons, we need get them to the proper facilities. We have a Lancer on its way out to meet you. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 23, 'title', 'Dathomir System: Survive the Black Sun Assault'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 24, 'title_d', 'Survive against the Black Sun assault'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 25, 'trans_update', 'Hang in there Pilot.'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 26, 'transmission_received', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 We are detecting no more hyperspace surges. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_2_a.stf', 27, 'transmission_start', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 The assault waves are on your position now! \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 2, 'arrived_at_loc', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 This really doesn''t look good. I suspect enemy ships to show up at any moment. Keep an eye out. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 4, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy craft detected on attack vector \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 5, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activities have ceased \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 9, 'first_attack', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Enemy ships coming in weapons armed.  We''re counting on you, Captain \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 10, 'found_loc', '\\#pcontrast3 CorSec Command: <  \\#pcontrast1 Okay. We''ve detected suspicious activity in Sector H-910. Go check it out and report back to us. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 11, 'mission_complete', 'Mission Success! Continue with further objectives.'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 12, 'outofrange', 'Tactical Computer: < Warning! Warning! Objective too far away! Warning! Warning! >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 13, 'outofrange_failed', 'Mission Failure! Objective out of range! Return to your superior for further instructions.'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 14, 'quest_defendpoint_d', 'Defend from the attacking waves'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 15, 'quest_defendpoint_t', 'Assault Point'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 16, 'quest_location_d', 'Area of high hyperspace activity'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 17, 'quest_location_t', 'Endor System'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 18, 'quest_reachpoint_d', 'Large hyperspace surges detected in this area'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 19, 'quest_reachpoint_t', 'Suspicious Activity'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 20, 'quest_update', '\\#pcontrast3 < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 21, 'split_quest_alert', '\\#pcontrast3 CorSec Command: < Good work, Captain. We are tracking one or more Tyrants not far from your location.  Try to disable one and recover any information that may help us with our pirate hunting. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 23, 'title', 'Endor System: Survive the Evil Raider Assault'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 24, 'title_d', 'Survive the retributive assault from the Evil Raiders'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 25, 'trans_update', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Captain! You have to win this mission. Be careful and keep an eye out for attack! \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 26, 'transmission_received', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 The data has been sent! \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_privateer_tier3_4_a.stf', 27, 'transmission_start', '\\#pcontrast3 CorSec Command: < \\#pcontrast1 Stay in the area as you relay the hyperspace activity back to us.  More Raiders are on their way so be ready. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 2, 'arrived_at_loc', 'You have arrived at the intercept coordinates. I hope you''re as good as I think, this will get rough.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 9, 'first_attack', 'Here they come! May the force be with you pilot, you will need it...'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 10, 'found_loc', 'Uploaded intercept coordinates to your nav computer. Hurry there pilot, our fighters are all busy guarding their assigned routes!'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 11, 'mission_complete', 'Amazing, I didn''t think you could do it. Get out of there, we are safe in this nebula for now.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 12, 'outofrange', 'Rebel Fleet Command: < You are moving too far away from the intercept coordinates, bombers will slip through! >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 13, 'outofrange_failed', 'Rebel Fleet Command: < The fighters are upon us, you let them slip through! We are under atta.. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 14, 'quest_defendpoint_d', 'The fleet is starting its relocation. They will need approximately ten minutes to reach safety. Hang in there and good luck pilot!'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 15, 'quest_defendpoint_t', 'Fleet moving.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 16, 'quest_location_d', 'The Endor system is still mostly uncharted to us but we have managed to find a nebula that we hope to hide our fleet in while they are repairing.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 17, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 18, 'quest_reachpoint_d', 'You are at the correct coordinates. Don''t let any Imperial ships get through you to the fleet.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 19, 'quest_reachpoint_t', 'Your sector.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 20, 'quest_update', 'Rebel Fleet Command: < %TO >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 21, 'split_quest_alert', 'Rebel Fleet Command: < A straggling freighter of ours are arriving out our old location. You need to get over there and escort him to us without being detected. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 23, 'title', 'Endor system: Prevent Imperial fighters from reaching the fleet in the Endor system.'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 24, 'title_d', 'Our fleet in the Endor system has been spotted and the Empire is sending fighters and bombers our way! We are trying to fight them off but are spread out too thin. You are assigned a sector to protect from any Imperial ships passing through while our fleet move to a new hiding spot. Hurry!'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 25, 'trans_update', 'Tactical Computer: < %DI percent of the fleet has escaped in to the nebula. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 26, 'transmission_received', 'Rebel Fleet Command: < Almost the entire fleet are in the nebula, hold out for just a few more seconds pilot! >'),
('string/en/spacequest/survival/corellia_rebel_tier3_2_b.stf', 27, 'transmission_start', 'Rebel Fleet Command: < We are moving in to a nearby nebula to hide. We need ten minutes! >'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 2, 'arrived_at_loc', 'You are at your designated coordinates, don''t let any enemies pass you.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 9, 'first_attack', 'Here they come pilot, get ready and may the force be with you my friend!'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 10, 'found_loc', 'The enemy is launching several last attacks on our fleet. I''m assigning you to intercept one of their wings at these coordinates.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 11, 'mission_complete', 'Fantastic job pilot! We are the last ship to jump and we have had no capital ship losses thanks to you and the other fighter pilots.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 12, 'outofrange', 'The enemy will slip by, get back to the intercept point pilot!'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 13, 'outofrange_failed', 'We are losing capital ships, bombers slipped by you, get out of there pilot, we are launching with what we have left!'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 14, 'quest_defendpoint_d', 'Don''t let any enemy ships pass you by. This will be extremely difficult and I wish I could send you more backup but our fighters are spread thin protecting their assigned spots. Good luck pilot, we depend on you.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 15, 'quest_defendpoint_t', 'Defend the assigned area.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 16, 'quest_location_d', 'We are getting ready to leave the Endor system. Our fleet is moving out of the nebula to the location where they initiate their jump to lightspeed. Unfortunately Imperial ships noticed them as soon as they started moving and they are launching an attack with anything they have close enough to get to our fleet in time.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 17, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 18, 'quest_reachpoint_d', 'This is the area that you are assigned to protect.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 19, 'quest_reachpoint_t', 'Your assigned blockade area.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 20, 'quest_update', 'Rebel Fleet Command: < %TO >'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 23, 'title', 'Endor system: Defend against the Empire''s last attack.'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 24, 'title_d', 'Our capital ships have finished their repairs and are starting to evacuate. The Empire has pinpointed their location and are launching one last attack. We are assigning you to defend an area in the path of the attacking Imperial ships. Don''t let anyone get by you!'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 25, 'trans_update', 'Tactical Computer: < %DI % of fleet has performed hyperspace jump. >'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 26, 'transmission_received', 'Rebel Fleet Command: < The last of our ships are jumping to lightspeed now, get out of there pilot! >'),
('string/en/spacequest/survival/corellia_rebel_tier3_4_d.stf', 27, 'transmission_start', 'Rebel Fleet Command: < We need five minutes to launch all our capital ships to hyperspace. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 1, 'arrived_at_loc', 'You are at your assigned sector. If they come your way, you need to hold them off for five minutes!'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 8, 'first_attack', 'I''m sorry pilot but they seemed to have picked your route. I hope you''re as good as they say.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 9, 'found_loc', 'You have been assigned this location, proceed to there and keep your eyes open for hostiles.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 10, 'mission_complete', 'Nym Mining Pilot: < We''re safe pilot. Good job, we owe you a big one! >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 11, 'outofrange', 'Worvog Arkon: < You''re too far from your position, the Black Sun will sneak by you! >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 12, 'outofrange_failed', 'Nym Mining Pilot: < They are all over us! We''re taking heavy casaulties! We need he.. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 13, 'quest_defendpoint_d', 'Stay close to these coordinates and defeat any enemy ship that come within distance, don''t let any slip past you before Nym''s mining vessels have evacuated.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 14, 'quest_defendpoint_t', 'Defend the area.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 15, 'quest_location_d', 'This area of the Dathomir system is relatively free from hostile encounters but the Black Sun is mounting a large scale attack and they may already be in the area when you arrive.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 17, 'quest_reachpoint_d', 'This is your assigned area to defend. Keep your eye out for any hostile ships.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 18, 'quest_reachpoint_t', 'Your defensive coordinates.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 19, 'quest_update', 'Worvog Arkon: < %TO >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 20, 'split_quest_alert', 'Worvog Arkon: < Thanks to your efforts, the Black Sun is vulnerable. Lets exploit that, stand by for orders. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 22, 'title', 'Dathomir system: Stop the Black Sun from reaching mining vessels.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 23, 'title_d', 'Nym has asked us to help some of his mining vessels in the Dathomir system escape an oncoming Black Sun attack. Several Alliance and Nym fighters have been stationed at different spots through out the nearby area to cover any incoming Black Sun ships from reaching the mining vessels while they evacuate.'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 24, 'trans_update', 'Tactical Computer: < %DI percent of friendly fleet has moved to safety. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 25, 'transmission_received', 'Tactical Computer: < 100 percent of friendly fleet has moved to safety. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_1.stf', 26, 'transmission_start', 'Nym Mining Pilot: < We are beginning to move now, we need about five minutes to get to safety. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 1, 'arrived_at_loc', 'You have been assigned this location to cover the bombers retreat. Don''t let anyone pass!'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 8, 'first_attack', 'We see multiple bandits incoming towards you. Good luck pilot, we''re counting on you.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 9, 'found_loc', 'Get over to this location quickly and cover our bombers retreat pilot!'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 10, 'mission_complete', 'Worvog Arkon: < All the Rebel bombers have left the sector. You amaze me pilot, didn''t think anyone could survive that assault. Head back to base. >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 11, 'outofrange', 'Worvog Arkon: < You are too far away from your assigned sector, the Imperial fighters will slip by you! >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 12, 'outofrange_failed', 'Worvog Arkon: < We''re losing squads all over the place up there! Get out of there while you still can pilot! >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 13, 'quest_defendpoint_d', 'Stay close to these coordinated and don''t let any hostile ships get past you. We will inform you when our bombers are safe. Good luck pilot!'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 14, 'quest_defendpoint_t', 'Defend these coordinates.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 15, 'quest_location_d', 'We are aware that you are asked to do this in a very hostile sector of the Dathomir system but it is our hope that you will prevail.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 17, 'quest_reachpoint_d', 'Fly to this area immediately and cover the Alliance B-Wings retreat.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 18, 'quest_reachpoint_t', 'Assigned area.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 19, 'quest_update', 'Worvog Arkon: < %TO >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 22, 'title', 'Dathomir system: Cover the Rebel bombers retreat.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 23, 'title_d', 'After the failed attack on the space stations defenses, we need to retreat out of the area. The Empire is sending fighters to intercept our bombers and your orders are to cover their retreat.'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 24, 'trans_update', 'Worvog Arkon: < %DI percent of the Rebel bombers have escaped the sector. Hang in there my friend, fight them off! >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 25, 'transmission_received', 'Worvog Arkon: < The last of the B-Wing squadrons are jumping to hyperspeed, we didn''t suffer a single loss! >'),
('string/en/spacequest/survival/corellia_rebel_tier4_3_b.stf', 26, 'transmission_start', 'Worvog Arkon: < We''re estimating that the Rebel B-Wings need about 8 minutes to hyperspace out safely. >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 2, 'arrived_at_loc', ' \\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 Enemy ships dropping out of hyperspace.  Stay at this location at all costs \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/corellia_tier2_final.stf', 4, 'attack_notify', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy ships detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 5, 'attack_stopped', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 The Rebel attacking craft have been eliminated \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/corellia_tier2_final.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/corellia_tier2_final.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/corellia_tier2_final.stf', 9, 'first_attack', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hyperspace surge detected. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 10, 'found_loc', 'Excellent, the counter attack has been scrambled.  Go to this position, it will cause the attack craft to make multiple jumps and stagger the assault.'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 11, 'mission_complete', 'The mission is a success, return to base.'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 12, 'outofrange', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 You are leaving the ambush area, stay on target. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 13, 'outofrange_failed', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 The Rebels have detected our movements and are breaking the ambush, our mission has failed. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 14, 'quest_defendpoint_d', 'When you begin jamming the Rebel communications, they will send out fighters to try to destroy you. Defend yourself but do not leave the area until the operation is completed.'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 15, 'quest_defendpoint_t', 'Defend the Rebel Communications Relay Point'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 16, 'quest_location_d', 'Travel to the Corellia system and jam the Rebel communications relay point. Once in the Corellia system you will receive a navigation waypoint to the Rebel communications relay point. Travel to that location and wait for the jamming operation to begin.'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 17, 'quest_location_t', 'Travel to the Corellia System'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 18, 'quest_reachpoint_d', 'Once you have arrived at the navigation waypoint, wait until the jamming operation begins. Once the operation begins, you will need to remain in the area until it completes. You will receive regular updates on how long you have until the operation is over. If you move to far away from the navigation waypoint you will receive a warning message. If you remain outside of the area for to long the mission will fail.'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 19, 'quest_reachpoint_t', 'Start the Jamming Operation'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 20, 'quest_update', ' \\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/survival/corellia_tier2_final.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/corellia_tier2_final.stf', 23, 'title', 'Corellia System: Jam the Rebel Communications'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 24, 'title_d', 'Travel to the Corellia system and jam the Rebel communications relay point. When you enter the Corellia system you will receive a navigation waypoint to the Rebel communications relay point. Travel to this waypoint and wait for the jamming operation to begin. In order to succeed, you need to stay near the navigation waypoint. If you move to far away you will receive a warning message for you to return. Once the jamming operation begins the Rebels will send out fighters to attack you. Defend yourself against attack but do not leave the area until the jamming operation is completed.'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 25, 'trans_update', ' \\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 %DI percent of the enemy force has been committed, stay focused \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 26, 'transmission_received', '\\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 All enemy craft committed. Black Epsilon bombers have been launched.\\#pcontrast1 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 27, 'transmission_recieved', ' \\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 All enemy craft committed.  Black Epsilon bombers have been launched. \\#pcontrast3 >'),
('string/en/spacequest/survival/corellia_tier2_final.stf', 28, 'transmission_start', ' \\#pcontrast3 Black Epsilon Command: < \\#pcontrast1 Enemy ships inbound. \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 1, 'title', 'Intercept the Rebel transmission.'),
('string/en/spacequest/survival/imperial_ss_02.stf', 2, 'found_loc', 'We''ve found an ideal location to intercept the Rebel beam-wave transmission. Go there now.'),
('string/en/spacequest/survival/imperial_ss_02.stf', 3, 'arrived_at_loc', 'The Rebel transmission will be easy to intercept here. Don''t stray too far from this point. The transmission should start at any moment.'),
('string/en/spacequest/survival/imperial_ss_02.stf', 4, 'transmission_start', ' \\#pcontrast3 Comm Computer: < \\#pcontrast1 Rebel transmission detected. Recording started. \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 5, 'trans_update', ' \\#pcontrast3 Comm Computer: < \\#pcontrast1 %DI% of Rebel transmission received. \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 6, 'transmission_received', ' \\#pcontrast3 Comm Computer: < \\#pcontrast1 100% of transmission received. Checksum validation complete. Transmission is authentic. \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 7, 'mission_complete', 'Good job, return to base with the transmission!'),
('string/en/spacequest/survival/imperial_ss_02.stf', 8, 'quest_update', ' \\#pcontrast3 Imperial Command: < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 9, 'outofrange', ' \\#pcontrast3 Comm Computer: < \\#ff0000 Transmission signal fading. Signal is too distant! \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 10, 'outofrange_failed', ' \\#pcontrast3 Comm Computer: < \\#ff0000 Transmission signal lost! \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 11, 'first_attack', 'System scans have detected enemy ships at lightspeed moving in your direction. You''ve been detected. Defend yourself, but get that transmission!'),
('string/en/spacequest/survival/imperial_ss_02.stf', 12, 'attack_notify', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy ships detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_02.stf', 13, 'attack_stopped', ' \\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy attack wing has been eliminated. \\#pcontrast3 >'),
('string/en/spacequest/survival/imperial_ss_2.stf', 1, 'arrived_at_loc', 'Arrived at scan location. Will begin to intercept transmission shortly.'),
('string/en/spacequest/survival/imperial_ss_2.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 3, 'attack_notify', 'Tactical Computer:<Multiple enemy fighters located.>'),
('string/en/spacequest/survival/imperial_ss_2.stf', 4, 'attack_stopped', 'Tactical Computer:<Enemy fighter wind eliminated.>'),
('string/en/spacequest/survival/imperial_ss_2.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 8, 'first_attack', 'You have been spotted and enemy fighters are on an intercept course. Continue to intercept the transmission at all costs.'),
('string/en/spacequest/survival/imperial_ss_2.stf', 9, 'found_loc', 'Uploading transmission coordinated to your Nav. Proceed to that point to begin transmission.'),
('string/en/spacequest/survival/imperial_ss_2.stf', 10, 'mission_complete', 'Transmission successfully intercepted.'),
('string/en/spacequest/survival/imperial_ss_2.stf', 11, 'outofrange', 'Tactical Computer:<Lost transmission. Return immediately to transmission location to reestablish connection to signal.>'),
('string/en/spacequest/survival/imperial_ss_2.stf', 12, 'outofrange_failed', 'Imperial High Command:<We lost the signal. You didn''t stay close enough to the broadcast area. Report back to your superior, you have some serious explaining to do.>'),
('string/en/spacequest/survival/imperial_ss_2.stf', 13, 'quest_defendpoint_d', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 14, 'quest_defendpoint_t', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 15, 'quest_location_d', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 16, 'quest_location_t', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 17, 'quest_reachpoint_d', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 18, 'quest_reachpoint_t', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 19, 'quest_update', 'Imperial High Command:<%TO>'),
('string/en/spacequest/survival/imperial_ss_2.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 22, 'title', 'Intercept Nym''s Signal'),
('string/en/spacequest/survival/imperial_ss_2.stf', 23, 'title_d', ''),
('string/en/spacequest/survival/imperial_ss_2.stf', 24, 'trans_update', 'Tactical Computer:<%DI minutes until transmission completes.>'),
('string/en/spacequest/survival/imperial_ss_2.stf', 25, 'transmission_received', 'Tactical Computer:<Transmission completed.>'),
('string/en/spacequest/survival/imperial_ss_2.stf', 26, 'transmission_start', 'Tactical Computer:<Signal found. Beginning transmission to HQ.>'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 2, 'arrived_at_loc', 'You have arrived at the transmission location. Stand by to begin tranmission interception.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters detected on an interception course.>'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter wave has been elimated.>'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 9, 'first_attack', 'You have been spotted by enemy fighters. Hold them off until you have finished recieving that transmission.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 10, 'found_loc', 'Optimum transmission location dectected. Proceed to the designated area immediately.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 11, 'mission_complete', 'Good work, pilot. We have the Rebel transmission. Return to your superior officer and make a full report.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 12, 'outofrange', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Tranmission signal interrupted. Return to the optimum transmission location immediately.>'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 13, 'outofrange_failed', 'We lost the signal! You moved to far away from the transmission location. Report your failure to your superior officer, pilot.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 14, 'quest_defendpoint_d', 'When you begin intercepting the Rebel communications, they will send out fighters to try to destroy you. Defend yourself but do not leave the area until the operation is completed.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 15, 'quest_defendpoint_t', 'Defend the Interception Point'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 16, 'quest_location_d', 'Travel to the Dantooine system and intercept the Rebel communications. Once in the Dantooine system, you will receive a navigation waypoint to the Rebel communications relay point. Travel to that location and wait for the interception operation to begin.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 17, 'quest_location_t', 'Travel to the Dantooine System'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 18, 'quest_reachpoint_d', 'Once you have arrived at the navigation waypoint, wait until the interception operation begins. Once the operation begins, you will need to remain in the area until it completes. You will receive regular updates on how long you have until the operation is over. If you move to far away from the navigation waypoint you will receive a warning message. If you remain outside of the area for to long the mission will fail.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 19, 'quest_reachpoint_t', 'Start the Interception of the Rebel Signal'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 20, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 23, 'title', 'Dantooine System: Intercept the Enemy Signal'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 24, 'title_d', 'Travel to the Dantooine system and intercept the Rebel communications. When you enter the Dantooine system you will receive a navigation waypoint to the Rebel communications relay point. Travel to this waypoint and wait for the interception operation to begin. In order to succeed, you need to stay near the navigation waypoint. If you move to far away you will receive a warning message for you to return. Once the interception operation begins the Rebels will send out fighters to attack you. Defend yourself against attack but do not leave the area until the Rebel message is completely received.'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 25, 'trans_update', 'Transmission Update:<%DI percent of transmission received.>'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 26, 'transmission_received', 'Transmission Update:<Transmission Received.>'),
('string/en/spacequest/survival/naboo_imperial_tier2_2.stf', 27, 'transmission_start', 'Transmission Updata:<Signal located. Beginning transmission interception now.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 2, 'arrived_at_loc', 'Hold at your current location. Transmission will begin shortly. Stay near the satellite or we will lose all the data.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Incoming enemy fighters.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighter wing has been eliminated.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 7, 'autorewardfrom', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 9, 'first_attack', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters moving into engage.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 10, 'found_loc', 'You should have the satellite location in your nav computer. Proceed to that location immediately for data transmission.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 11, 'mission_complete', 'Mission Completed.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 12, 'outofrange', 'Tranmission Progress:<Signal lost. Satellite out of range. Return to reestablish tranmission.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 13, 'outofrange_failed', 'We lost the signal! Pilot you have some explaining to do with your superior as to why you left the area and cost us important information.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 14, 'quest_defendpoint_d', 'Once you have arrived at the location, wait for the transmission to begin. You might attract unwanted attention from those who don''t want us to get that information, but you will need to remain in the area to make sure that you send a complete transmission.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 15, 'quest_defendpoint_t', 'Transmit the Logs'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 16, 'quest_location_d', 'The satellite that command wants you to use is located in the Yavin system.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 17, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 18, 'quest_reachpoint_d', 'Travel to the Nav waypoint given, which will lead you to the Imperial communication satellite.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 19, 'quest_reachpoint_t', 'Travel to the Satellite'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 20, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 21, 'split_quest_alert', 'We have the information from the spy''s ship. While you are in the sector we need you to pick up some documents on Dr. Shinss'' project to compare against his statement. Location of the delivery vessel has been uploaded to your nav computer.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 23, 'title', 'Yavin System: Transmit the Data To Headquarters'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 24, 'title_d', 'Inquisition command wants that data immediately, but there aren''t any vessels available to pick it up. You will have to risk transmitting the logs via a satellite. Travel to an Imperial satellite and transmit the data to command.'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 25, 'trans_update', 'Transmission Progress:<%DI percent of transmission sent.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 26, 'transmission_received', 'Transmission Progress:<Transmission completed. Please stand by.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_2_a.stf', 27, 'transmission_start', 'Transmission Progress:<Transmission started. Remain in the area to avoid irrepairable data lose.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_3_c.stf', 1, 'arrived_at_loc', 'Arrived at ambush location. Scanning for enemy fighters.'),
