('string/en/spacequest/survival/naboo_imperial_tier3_3_c.stf', 10, 'mission_complete', 'Tactical Computer:<Location of rebel primary command vessel located and sent to Imperial High Command.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_3_c.stf', 11, 'outofrange', 'Tactical Computer:<Tranmission interrupted. Return to ambush point immediately.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_3_c.stf', 12, 'outofrange_failed', 'Imperial High Command:<We lost the transmission because you move too far away. Report to your superior immediately.>'),
