('string/en/spacequest/survival/naboo_imperial_tier3_3_c.stf', 24, 'trans_update', 'Transmission Status:<%DI minutes left until transmission complete.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_3_c.stf', 25, 'transmission_received', 'Transmission Status:<Transmission Completed. Location of rebel command vessel discovered.>'),
('string/en/spacequest/survival/naboo_imperial_tier3_3_c.stf', 26, 'transmission_start', 'Transmission Status:<Scanning area for rebel command vessel. %DI minutes until complete.>'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 2, 'arrived_at_loc', 'Stand by for next transmission to take place. Stay in this location until transmission is completed.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Warning! Enemy fighters incoming at attack speeds with weapons armed.>'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy wave eliminated.>'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 9, 'first_attack', 'You have been spotted. Be on the look out for enemy fighters.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 10, 'found_loc', 'Transmission point located. Travel to the location in your nav computer and stand by to intercept the transmission.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 11, 'mission_complete', 'Nice work, pilot. Stand by for delivery information.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 12, 'outofrange', 'Transmission signal lost. Return to transmission location.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 13, 'outofrange_failed', 'Transmission signal ended. Return to your superior officer to explain your failure to gather the information.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 14, 'quest_defendpoint_d', 'You must remain at that location until the signal is completed. If the Coynite notice you they will attack. Defend yourself but do not leave the area until the signal is completed.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 15, 'quest_defendpoint_t', 'Defend the Interception Point'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 16, 'quest_location_d', 'The relay point is located inside of the Dathomir system.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 17, 'quest_location_t', 'Travel to the Dathomir System'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 18, 'quest_reachpoint_d', 'Once you have reached the relay point, wait for the broadcast to begin.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 19, 'quest_reachpoint_t', 'Intercept the Coynite Message'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 20, 'quest_update', '\\#pcontrast1 Imperial High Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 21, 'split_quest_alert', 'We need that data brought to one of our command vessels so we can decypher the message. Stand by for the navigation coordinates.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 23, 'title', 'Dathomir System: Intercept the Coynite Message'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 24, 'title_d', 'The captured Coynite held out for as long as he could but eventually talked. Apparently the Coynite have an ally or allies from the prison on the planet''s surface. They have been using communications satellites to broadcast instructions to the Coynite. You are to travel to one of the relay points and intercept these instructions.'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 25, 'trans_update', 'Transmission Update: <%DI percent of message received.>'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 26, 'transmission_received', 'Transmission Update: <Transmission received. Stand by for further instructions.>'),
('string/en/spacequest/survival/naboo_imperial_tier4_3.stf', 27, 'transmission_start', 'Transmission Update: <Transmission frequency located. Beginning download of encrypted message.>'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 1, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Intercept point has been reached. Hold here. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 3, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Enemy craft have appeared on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 4, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Attack group has been defeated. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 8, 'first_attack', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Here they come! \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 9, 'found_loc', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Proceed to the following waypoint to intercept a transmission for the target''s location.  Your presence will not be a secret, you must hold out until you have that transmission. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 10, 'mission_complete', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Transmission has been relayed, stand by for coordinates. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 11, 'outofrange', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Warning! Leaving the transmission intercept area. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 12, 'outofrange_failed', '\\#pcontrast3 RSF  Command: < \\#pcontrast1 The transmission was lost, now there is no telling where they will end up. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 13, 'quest_defendpoint_d', 'Stay at this location until the transmission intercept is complete'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 14, 'quest_defendpoint_t', 'Waypoint'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 15, 'quest_location_d', 'An area of Black Sun controlled space'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 16, 'quest_location_t', 'Lok System'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 17, 'quest_reachpoint_d', 'Travel to this location to begin the intercept'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 18, 'quest_reachpoint_t', 'Waypoint'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 19, 'quest_update', '%TO'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 20, 'split_quest_alert', '\\#pcontrast3 RSF Command: < \\#pcontrast1 There were some stragglers that didn''t make the jump in when they saw their side was losing; be weary.  Return to base Captain.\\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 22, 'title', 'Lok System: Intercept a Black Sun Transmission'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 23, 'title_d', 'You must maintain presence in a location where you can intercept a Black Sun transmission'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 24, 'trans_update', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Datastream relay: Estimated %DI% complete. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 25, 'transmission_received', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Datastream intercept complete. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier3_3c.stf', 26, 'transmission_start', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Datastream intercept has begun. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 1, 'arrived_at_loc', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Ok, this is the spot.  This will probably go down in history as the worst ambush ever, but stay focused and stay alive... we want those Black Sun destroyed. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 3, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 4, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 8, 'first_attack', '\\#pcontrast3 RSF Command: < \\#pcontrast1 The hyperspace signatures are spiking, be ready. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 9, 'found_loc', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Calculated entry point is here, move into position. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 10, 'mission_complete', '\\#pcontrast3 RSF Command: < \\#pcontrast1 That is enough, whatever plans they had are pointless now.  Return to base. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 11, 'outofrange', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 You are moving out of range for the ambush, return to the nav location. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 12, 'outofrange_failed', '\\#pcontrast3 RSF Command: < \\#pcontrast1 What are you hoping to accomplish out there?  This ambush was a horrible idea. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 13, 'quest_defendpoint_d', 'Stay at this position through the duration of the assault'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 14, 'quest_defendpoint_t', 'Assault Waypoint'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 15, 'quest_location_d', 'An area of Imperial control in the Yavin System'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 16, 'quest_location_t', 'Yavin System'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 17, 'quest_reachpoint_d', 'Travel here to intercept the Black Sun force'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 18, 'quest_reachpoint_t', 'Ambush Waypoint'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 19, 'quest_update', '%TO'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 22, 'title', 'Yavin System: Intercept the Black Sun Assault'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 23, 'title_d', 'Launch an attack on the Black Sun assault force moving into Yavin Space'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 24, 'trans_update', '\\#pcontrast3 RSF Command: < \\#pcontrast1 Stay focused Captain. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 25, 'transmission_received', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hyperspace signatures dismished. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_privateer_tier4_3c.stf', 26, 'transmission_start', '\\#pcontrast3 Tactical computer: < \\#pcontrast1 A large number of hyperspace signatures detected. \\#pcontrast3 >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 1, 'arrived_at_loc', 'The Imperial Informant was a spy! He led the Imperial Inqusition right to the base! Defend the base for approximately seven minutes, that should give them enough time to prepare their defenses!'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 8, 'first_attack', 'Alert! Alert! Enemy vessels closing in!'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 9, 'found_loc', 'Suspicious activity in the area, sir. Proceed with caution'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 10, 'mission_complete', 'Mission complete! Continue with objectives.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 11, 'outofrange', 'Brother Ezkiel: < What are you doing pilot! Get back in there and fight! >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 12, 'outofrange_failed', 'Mission failed! Too far away from objective point. Return to Ezkiel.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 13, 'quest_defendpoint_d', 'Guard this area with everything you have, don''t let the Imperial fighters break through until the base defense is prepared.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 14, 'quest_defendpoint_t', 'Let no one through!'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 15, 'quest_location_d', 'This area of the Dantooine system is fairly secure but the Imperial Inquisition is moving a massive fleet our way.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 16, 'quest_location_t', 'Dantooine system.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 17, 'quest_reachpoint_d', 'This is the coordinates of the area you are assigned to protect my friend.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 18, 'quest_reachpoint_t', 'Your assigned area of protection.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 19, 'quest_update', 'Vortex Command: < %TO >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 20, 'split_quest_alert', 'Brother Ezkiel: < The Imperial spy that you escorted earlier is trying to escape. Disable his ship and transfer over any information he may have in his onboard computer! >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 22, 'title', 'Dantooine system: The Inquisition attacks!'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 23, 'title_d', 'The Imperial officer scum was a spy sent to confirm the presence of our organisation on this base. The Inquisition is sending a massive attack our way. The base took heavy damage in the earlier attack and needs a few minutes to prepare the defenses. Try to hold off the Imperial forces at your assigned location.'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 24, 'trans_update', 'Vortex Command: < Stay alert, pilot. The Space station defenses are %DI percent operational. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 25, 'transmission_received', 'Vortex Command: < Great work, pilot! Thanks to yours and other pilots outstanding work, the space station defences are operational and should be able to easily fend off the attack. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_1_b.stf', 26, 'transmission_start', 'Vortex Command: < Be on the alert, pilot! Our sensors detect enemy activity. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 2, 'arrived_at_loc', 'Keep your eyes open, pilot. Our systems show multiple fighter ships heading toward you.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 9, 'first_attack', 'Here they come, pilot! They''re dangerous bastards. Keep your wits about you. Good luck!'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 10, 'found_loc', 'We''ve detected a suspicious amount of activity in this region. Defend this point against any Blacklight enemy while we scan for the Blacklight HQ.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 11, 'mission_complete', 'Mission success! Proceed with further objectives.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 12, 'outofrange', 'Tactical Computer: < Warning! Objective Point out of range! Return to initial coordinates immediately. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 13, 'outofrange_failed', 'Brother Ezkiel: < Ack, some of the Blacklight pirates got past you and are making short work of the SpyNet recon ships. Return to base pilot. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 14, 'quest_defendpoint_d', 'Defend this area and don''t let any of the pirates get past you until the SpyNet ships are done. I know we ask a lot of you my friend but if anyone can do it, it''s you.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 15, 'quest_defendpoint_t', 'Defend the area.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 16, 'quest_location_d', 'The Endor system seem to be a high risk system normally but you are in the middle of Blacklight territory so it will be especially dangerous. We are all hoping for your success down here my friend.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 17, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 18, 'quest_reachpoint_d', 'These are the coordinates that is best suited to intercept the incoming Blacklight pirates. Stay close to it.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 19, 'quest_reachpoint_t', 'Correct coordinates.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 20, 'quest_update', 'Brother Ezkiel < %TO >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 21, 'split_quest_alert', 'Brother Ezkiel: < Pilot, you impress me. Songs of your success will be taught in the halls of the Vortex. Back to business. We need you to find the exact location of the Blacklight leader. Stand by. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 23, 'title', 'Endor system: Survival of the fittest.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 24, 'title_d', 'We have found the Blacklight base of operations and need to pinpoint their command. The SpyNet have sent in some of their highly advanced recon ships. You need to keep them safe from the incoming mass of pirates while they scan the area.'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 25, 'trans_update', 'Brother Ezkiel: < Pilot, hold out for a while longer. The SpyNet are %DI% done with the scans. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 26, 'transmission_received', 'Brother Ezkiel: < The spy ships are complete, stand by. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_3_b.stf', 27, 'transmission_start', 'Brother Ezkiel: < Pilot, we need you to defend this area while our spy ships scan the area for the Blacklights command. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 1, 'arrived_at_loc', 'Stay on the alert, pilot. You know the drill. There''s enemy activity in these parts. Don''t let your guard down.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 8, 'first_attack', 'Forget trying to disable ships, they are coming for you en masse! Our sensor ships are close to that location as well so we need you to keep them busy while we relocate.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 9, 'found_loc', 'Proceed to the desginated area. Enemy presence detected.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 10, 'mission_complete', 'Mission success! Proceed with further objectives.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 11, 'outofrange', 'Vortex Command: < You are getting too far in to Imperial territory, they will lock their capital ships to you! Return to the coordinates we provided you with. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 12, 'outofrange_failed', 'Vortex Command: < You went too deep in to the Imperial territory and they have locked on to you. There''s nothing left to do but retreat, return to base! >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 13, 'quest_defendpoint_d', 'You have been spotted! We have multiple Imperial fighters heading your way, prepare for attack!'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 14, 'quest_defendpoint_t', 'Under attack!'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 15, 'quest_location_d', 'You are getting deeper in to Imperial territory and the danger level is increasing, stay alert.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 17, 'quest_reachpoint_d', 'You are at the correct coordinates, stand by while we do a scan for smaller groups of Inquisitor ships.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 18, 'quest_reachpoint_t', 'Correct location.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 19, 'quest_update', 'Vortex Command: < %TO >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 20, 'split_quest_alert', 'Brother Ezkiel: < You''re an amazing pilot! Good work. Back to the old objective, try to find and disable a ship of the Imperial Inquisition. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 22, 'title', 'Dathomir system: Disable Imperial ship.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 23, 'title_d', 'We may have located a small group of Imperial ships. We will alert you if we find any suitable ships of the Inquisition for you to capture as you head for the waypoints we provide you with.'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 24, 'trans_update', 'Vortex Command: < Keep it up pilot, Our sensor ships are %DI percent done with relocating to a safe location. >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 25, 'transmission_received', 'Vortex Command: < You are home free pilot! We are doing the final scans now but it seems the Empire has given up sending more fighters. Amazing job! >'),
('string/en/spacequest/survival/naboo_rebel_tier3_4_b.stf', 26, 'transmission_start', 'Vortex Command: < There''s more of them than we can count. I don''t know what to tell you pilot, you''re in our thoughts, may the force be with you. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 1, 'arrived_at_loc', 'You are in your assigned sector. Prevent any Imperial ships from getting past you pilot!'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 8, 'first_attack', 'This will get rough pilot, the Empire is sending heavy forces from several directions. The life of those people is in your hands!'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 9, 'found_loc', 'You''ve been assigned this sector to block any Imperial ships coming through that route. Get over there quickly.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 10, 'mission_complete', 'Brother Extok Evin: < Great work pilot, our shuttles are safe! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 11, 'outofrange', 'Brother Extok Evin: < You''re too far away from your assigned coordinates, get back there quickly! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 12, 'outofrange_failed', 'Brother Extok Evin: < You let them slip by you, our shuttles are trying to perform emergency jumps to hyperspace! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 13, 'quest_defendpoint_d', 'Don''t let any enemy ships pass you by pilot, those freighters can not defend themselves against Imperial bombers or fighters.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 14, 'quest_defendpoint_t', 'Defend the freighters.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 15, 'quest_location_d', 'The Endor system has a high concentration of Imperial forces and many of them are heading your way! I would be very surprised if you won''t at least run in to a few in the area you have been ordered to intercept.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 17, 'quest_reachpoint_d', 'This is the area you have been assigned to protect.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 18, 'quest_reachpoint_t', 'Location of intercept.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 19, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 20, 'split_quest_alert', 'Brother Extok Evin: < A target of opportunity has opened up, stand by for further instructions. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 21, 'split_quest_alert_fail', 'Brother Extok Evin: < All may not be lost, most of the freighters have managed to get away even though the defense broke at some points. We have a distress call from a freighter though, need you to investigate. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 22, 'title', 'Endor system: Prevent the Imperial fleet from destroying personnel shuttles.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 23, 'title_d', 'The Inquisition has somehow found out about the route through the Endor system that some of our freighters carrying Vortex personnel to safety are using. They are sending their elite fighters to the area and we need you to block one of the possible attack routes the Inquisition may take, long enough for the freighters to get to safety.'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 24, 'trans_update', 'Brother Extok Evin: < %DI percent of the personnel shuttles have jumped to lightspeed. Keep it up! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 25, 'transmission_received', 'Brother Extok Evin: < Our last shuttle is jumping to lightspeed as we speak, amazing job pilot! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_1.stf', 26, 'transmission_start', 'Brother Extok Evin: < Our shuttles has started calculating their lightspeed jumps. The fleet commander estimate that they need about six minutes. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 1, 'arrived_at_loc', 'Patrol this location and don''t let anything get past you pilot!'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 8, 'first_attack', 'Here they come pilot and it''s not looking good... May the force be with you my friend.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 9, 'found_loc', 'I''ve assigned you this sector pilot, your squad is spread out covering the nearby areas. Head over there quickly!'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 10, 'mission_complete', 'Brother Extok Evin: < Splendid job pilot, the bomber squadrons have pulled out safely. Mission complete! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 11, 'outofrange', 'Brother Extok Evin: < You''re too far away from your assigned sector pilot, get back there immediately! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 12, 'outofrange_failed', 'Brother Extok Evin: < Our bomber squadrons are taking casaulties! Abort mission everyone, abort! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 13, 'quest_defendpoint_d', 'Our last chance pilot. You will come under heavy attack in a few seconds, we''re all crossing our fingers that you will do the impossible and prevail.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 14, 'quest_defendpoint_t', 'The last stand.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 15, 'quest_location_d', 'After our initial failure to eliminate the defense force of the base, the area is now crawling with Imperial fighters. Be prepared for anything!'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 17, 'quest_reachpoint_d', 'The Imperial attackers will be passing through these coordinates on their way to intercept our bombers. Proceed to the waypoint right away pilot.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 18, 'quest_reachpoint_t', 'Point of defense.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 19, 'quest_update', 'Brother Extok Evin: < %TO >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 22, 'title', 'Dathomir system: Cover the B-Wing squads'' flank.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 23, 'title_d', 'Some of our bombers have outflanked the Imperial defences but the Empire has picked up on it and is moving to intercept. We''re putting you in the middle of their intercept route to prevent them from getting to our bombers.'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 24, 'trans_update', 'Brother Extok Evin: < The B-Wings have delivered %DI percent of their payloads, hang in there pilot! >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 25, 'transmission_received', 'Brother Extok Evin: < The station is burning, all payloads delivered! The B-Wings are starting to pull out. >'),
('string/en/spacequest/survival/naboo_rebel_tier4_4_b.stf', 26, 'transmission_start', 'Brother Extok Evin: < The first B-Wings are within firing range of the station. >'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 1, 'arrived_at_loc', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 < This is the transmis--*static* ...stop signal. Be careful, pilot! [Transmission Ends] >'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 3, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Incoming enemy fighters.>'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 4, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters eliminated.>'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 8, 'first_attack', 'I can''t seem to get through to you, pilot! Enemies! My systems have detected heightened activity--[Transmission Ends]'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 9, 'found_loc', 'Pilot! Listen carefully. I''ve sent you a point that you can jam the Zynt''aia. Please be careful.'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 10, 'mission_complete', 'You have stopped the Zynt''aia from sending out the distress signal.'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 11, 'outofrange', 'Pilot! You''re too far away from the transmission point. Move closer or risk mission failure!'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 12, 'outofrange_failed', 'Mission failed! You moved too far away from the transmission point.'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 13, 'quest_defendpoint_d', 'Once I am at the transmission point, I must remain in the area for the designated time and survive.'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 14, 'quest_defendpoint_t', 'Fire of Survival: Defend'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 15, 'quest_location_d', 'It is my duty to remain in the Tatoo System as directed by A''Lerris Verata.'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 16, 'quest_location_t', 'Remain in the Tatoo System'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 17, 'quest_reachpoint_d', 'To face my hardest challenge, I must travel to the transmission point as was given to me by A''Lerris.'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 18, 'quest_reachpoint_t', 'Fire of Survival: Transmission Point'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 19, 'quest_update', '\\#pcontrast1 A''Lerris Verata:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 22, 'title', 'Tatoo System: Fire of Survival'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 23, 'title_d', 'The fire of survival... It is a sudden thing. When one is faced with dire circumstance, a well of fire, like lava coursing through one''s veins, springs forth with unmatched strength. The flames consume your soul, your very essence, inspiring you to face the odds no matter what the consequence! This is how I felt as the first of those many walls washed over me. My hands felt hot to the touch, my heart in my throat. My favorite companion, my trusty ship, shuttered with each of their passing, laser bolts melting my enemies'' hulls in one fell swoop. All I wanted to do was survive.. and survive I did.'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 24, 'trans_update', 'Mission Update: < %DI percent of signal blocked. >'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 25, 'transmission_received', 'Mission Update: < You''ve survived and successfully blocked the distress signal! Mission Success! >'),
('string/en/spacequest/survival/poi_tatooine_general2_3_a.stf', 26, 'transmission_start', 'Mission Update: < Pilot! It will take about 5 minutes to successful jam that signal! I am sure your presence will be noted. >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 1, 'arrived_at_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Destination reached. \\#pcontrast3 >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 3, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 4, 'attack_stopped', '\\#pcontrast3 Tactical Comptuer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 5, 'autorewardbody', 'Completion Bonus: Attenuation (20000)'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 6, 'autorewardfrom', 'Endor Station'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 7, 'autorewardsubject', 'The Grand Tour'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 8, 'first_attack', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hyperspace signatures detected. \\#pcontrast3 >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 9, 'found_loc', '\\#pcontrast3 Nav Comptuer: < \\#pcontrast1 Waypoint set. \\#pcontrast3 >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 10, 'mission_complete', '\\#pcontrast3 Endor Station: < \\#pcontrast3 Excellent job Captain.  This completes your tour of duty in the Endor System and your current contract is closed. Check back later, and we might have further work for you. \\#pcontrast3 >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 11, 'outofrange', '\\#pcontrast3 Nav Comptuer: < \\#pcontrast1 Leaving the designated battlepoint. \\#pcontrast3 >'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 12, 'outofrange_failed', '\\#pcontrast3 You have failed the mission for leaving the battle location.'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 13, 'quest_defendpoint_d', 'Defend from the Zynt''aia attack, destroy as many fighters as you can before the time is up.'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 14, 'quest_defendpoint_t', 'Defend'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 15, 'quest_location_d', ''),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 16, 'quest_location_t', ''),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 17, 'quest_reachpoint_d', 'A battlepoint with pirates in the Declorian Territory.'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 18, 'quest_reachpoint_t', 'Battlepoint'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 19, 'quest_update', '%TO'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 22, 'title', 'Endor System: Attenuation'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 23, 'title_d', 'The Zynt''aia Spice Pirates have been increasing their activity in the Endor System. A threat to the growing research station on the local moon of Endor 2,an offensive patrol to disrupt and hopefully destroy their operations around the Declorian Territory has issued by Naval Operations.  You must survive assault by the pirates for 6 minutes to complete the operation.'),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 24, 'trans_update', 'Operation in progress, %DI of 100 complete. '),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 25, 'transmission_received', '\\#pcontrast3 The assault is complete. '),
('string/en/spacequest/survival/stn_endor_irs_imp_tier3_3f.stf', 26, 'transmission_start', '\\#pcontrast3 Timer has begun.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 1, 'arrived_at_loc', 'You have reach the optimum transmission point. Stand by for the interception of the signal to begin.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 3, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters detected. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 4, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 < Enemy fighters eliminated. >\\#pcontrast3 \\#pcontrast1'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 8, 'first_attack', 'Enemy fighters have detected your presence. Remain in the area until the transmission is completed but defend yourself against all attacking craft.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 9, 'found_loc', 'Optimum transmission interception point calculated. Move to this location to intercept signal.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 10, 'mission_complete', 'Transmission completed. Transmission appears to be orders from the Deep Corellia Mining Co. to agents posing as Massassi to drive the Yavin Mining Co. out of business. They are trying to take over the rich mining operations on Yavin 4.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 11, 'outofrange', 'Signal interupted. Return immediately to optimum transmission location in order to reestablish a link.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 12, 'outofrange_failed', 'The signal has stopped broadcasting. Transmission incomplete. Return to Yavin station.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 13, 'quest_defendpoint_d', 'The computer estimates that it will take about five minutes in order to get the entire broadcast. Remain in the area until it is completely intercepted.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 14, 'quest_defendpoint_t', 'Intercept the Transmission'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 15, 'quest_location_d', 'The signal is being beamed into the Yavin system.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 16, 'quest_location_t', 'Remain in the Yavin System'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 17, 'quest_reachpoint_d', 'Your computer has determined the location of the strongest signal strength. Travel to that point and tap into the signal.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 18, 'quest_reachpoint_t', 'Travel to Signal Location'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 19, 'quest_update', '\\#FF0000 Flight Computer:\\#FF0000 < %TO >'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 22, 'title', 'Yavin System: Intercept the Massassi Transmission'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 23, 'title_d', 'You have detected a signal coming from the Corellia system to this location. The signal is weak but you think you could tap into it.'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 24, 'trans_update', '\\#FF0000 Flight Computer:\\#FF0000 \\#pcontrast3 < %DI percent of the transmission completed. > \\#pcontrast3'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 25, 'transmission_received', '\\#FF0000 Flight Computer:\\#FF0000 \\#pcontrast3 < Transmission completed. Decrypting now. > \\#pcontrast3'),
('string/en/spacequest/survival/stn_yavin4_company_all_massassi_tier2_7.stf', 26, 'transmission_start', '\\#FF0000 Flight Computer:\\#FF0000 \\#pcontrast3 < Transmission link up established. Stand by for transmission updates. > \\#pcontrast3'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 1, 'arrived_at_loc', 'The transport''s arrival has been delayed due to hyperdrive malfunctions. You must remain within range of this location until the transport arrives. Do no leave this area.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 3, 'attack_notify', 'Tactical Computer: < Enemy craft inbound. Imperial signatures detected. >'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 4, 'attack_stopped', 'Tactical Computer: < Enemy threat neutralized. >'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 8, 'first_attack', 'The Imperial Navy has been monitoring our communications! They have sent an attack wing to intercept you. Defend yourself, but do not leave this area until the transport arrives.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 9, 'found_loc', 'Navigation waypoint uploaded. Another standard pickup. Travel to this location and await the arrival of the transport.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 10, 'mission_complete', 'Talus Station: < The transport''s hyperdrive is repaired. They should be arriving any second now. >'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 11, 'outofrange', 'Talus Station: < Be careful. You are moving too far away from the transport jump location. >'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 12, 'outofrange_failed', 'Talus Station: < You''ve gone out of range from the transport jump location. They will likely be boarded by the Empire. We''re scrapping this mission. >'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 13, 'quest_defendpoint_d', 'The transport is experiencing hyperdrive difficulties. You must remain at this location until the transport arrives. If attacked, you may defend yourself, but do not leave this area.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 14, 'quest_defendpoint_t', 'Remain at This Location'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 15, 'quest_location_d', 'You must meet the transport in the Naboo system.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 16, 'quest_location_t', 'Remain in the Naboo System'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 17, 'quest_reachpoint_d', 'Travel to the specified location and await the arrival of the drop-off ship.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 18, 'quest_reachpoint_t', 'Meet With the Drop-off Ship'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 19, 'quest_update', 'Talus Station: < %TO >'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 20, 'split_quest_alert', 'Dock with the transport.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 22, 'title', 'Naboo System: Pick Up Package From the Transport'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 23, 'title_d', 'Your next assignment is to meet a transport in the Naboo system to receive a package for delivery.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 24, 'trans_update', 'Transport hyperdrive repair status: %DI% complete'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 25, 'transmission_received', 'Transport hyperdrive repairs complete.'),
('string/en/spacequest/survival/talus_station_mission4_1.stf', 26, 'transmission_start', 'Transport hyperdrive undergoing repairs.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 2, 'arrived_at_loc', 'Arrived at ambush location. Scanning for enemy fighters.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 4, 'attack_notify', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Enemy fighters located. Incoming at high speeds.>'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 5, 'attack_stopped', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Attack wave destroyed.>'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 9, 'first_attack', 'Enemy fighters located. Incoming at high speeds.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 10, 'found_loc', 'Ambush location discovered. Updating the navigation computer.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 11, 'mission_complete', 'Location of Rebel primary command vessel located and sent to Imperial High Command. Report back to your superior for further instructions.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 12, 'outofrange', '\\#pcontrast1 Tactical Computer:\\#pcontrast3 <Tranmission interrupted. Return to ambush point immediately.>'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 13, 'outofrange_failed', 'We lost the transmission because you moved too far away. Report to your superior immediately.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 14, 'quest_defendpoint_d', 'When you begin the scan you can expect to be attacked by Rebel fighters falling into our ambush. Defend yourself but do not leave the area until the operation is completed.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 15, 'quest_defendpoint_t', 'Defend the Ambush Point'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 16, 'quest_location_d', 'Remain in the Endor system and scan from the ambush point. Once in the Endor system you will receive a navigation waypoint to the ambush point. Travel to that location and wait for the scan to begin.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 17, 'quest_location_t', 'Remain in the Endor System'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 18, 'quest_reachpoint_d', 'Once you have arrived at the navigation waypoint, wait until the scan begins. Once the scan begins, you will need to remain in the area until it completes. You will receive regular updates on how long you have until the operation is over. If you move to far away from the navigation waypoint you will receive a warning message. If you remain outside of the area for to long the mission will fail.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 19, 'quest_reachpoint_t', 'Travel to the Ambush Point'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 20, 'quest_update', '\\#pcontrast1 Storm Squadron Command:\\#pcontrast3 <%TO>'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 23, 'title', 'Endor System: Scanning System for Rebel Command'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 24, 'title_d', 'Travel to the Endor system and start the system scan at the ambush point. When you enter the Endor system you will receive a navigation waypoint to the ambush point. Travel to this waypoint and wait for the scan to begin. In order to succeed, you need to stay near the navigation waypoint. If you move to far away you will receive a warning message for you to return. Once the scan begins the Rebels will send out fighters to attack you. Defend yourself against attack but do not leave the area until the scan is completed.'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 25, 'trans_update', 'Transmission Status: <%DI percent of system scan completed.>'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 26, 'transmission_received', 'Transmission Status: <Transmission Completed. Location of Rebel command vessel discovered.>'),
('string/en/spacequest/survival/tatooine_imperial_tier3_3_c.stf', 27, 'transmission_start', 'Transmission Status: <Scanning area for Rebel command vessel.  Complete scan should take about 10 minutes.>'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 1, 'arrived_at_loc', '\\#pcontrast3 Beissa: < \\#pcontrast1 Okay! You''ve entered the Witchblood clan''s sacred burial zone... they''re sure to descend on you shortly.  I wouldn''t want to be you right now. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 3, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast3 Hyperspace signatures detected in close proximity. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 4, 'attack_stopped', '\\#pcontrast3 Beissa: < \\#pcontrast1 Stay focused, and stay alive.  We need them focused on you and not us. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 8, 'first_attack', '\\#pcontrast3 Beissa: < \\#pcontrast3 All right! Here they come! Keep them busy while we work our way into their base... \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 9, 'found_loc', '\\#pcontrast3 Beissa: < \\#pcontrast1 Fly to that location and keep the Witchblood clan busy. We''ll sneak into their hidden base, and set detonators! \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 10, 'mission_complete', '\\#pcontrast3 Beissa: < \\#pcontrast1 Great work! We''ve set all the detonators at their stronghold. We''re clearing out so we can set off the charges.  Meet us back at Jabba''s Palace \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 11, 'outofrange', '\\#pcontrast3 Beissa: < \\#pcontrast1 Get back to the pirates'' burial zone! If the Witchblood disengage, they''ll find us and the mission will be lost! \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 12, 'outofrange_failed', '\\#pcontrast3 Beissa: < \\#pcontrast1 You went too far from the burial zone! Witchblood scouts are returning to their base. The mission is scrapped! \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 13, 'quest_defendpoint_d', 'Stay at this location until you are given instruction to leave'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 14, 'quest_defendpoint_t', 'Burial Ground'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 15, 'quest_location_d', 'The spaceborne burial ground of the Dathomir Witchblood Clan'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 16, 'quest_location_t', 'Dathomir System'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 17, 'quest_reachpoint_d', 'Travel to this location to begin the operation'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 18, 'quest_reachpoint_t', 'Burial Ground'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 19, 'quest_update', '\\#pcontrast3 < \\#pcontrast1 %TO \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 22, 'title', 'Dathomir System: Provide a distraction at the Witchblood Clan Burial Grounds'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 23, 'title_d', 'Go make your presence known at the Witchblood Clan burial grounds to occupy them while Hutt forces infiltrate their stronghold'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 24, 'trans_update', '%DI/60 recieved.'),
('string/en/spacequest/survival/tatooine_privateer_tier3_2_b.stf', 25, 'transmission_received', 'Survival Complete'),
