('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 1, 'arrived_at_loc', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Large hyperspace signature detected at this location.  Please take evasive action. \\#pcontrast3 >'),
