('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 3, 'attack_notify', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile craft detected on attack vector. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 4, 'attack_stopped', '\\#pcontrast3 Tactical Computer: < \\#pcontrast1 Hostile activity has ceased. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 5, 'autorewardbody', ''),
