('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 8, 'first_attack', '\\#pcontrast3 Nirame: < \\#pcontrast1 It''s a trap! \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 9, 'found_loc', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Hyperspace Signature detected. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 10, 'mission_complete', '\\#pcontrast3 Nirame: < \\#pcontrast1 I would get out of there if I were you. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 11, 'outofrange', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Systems Failture. \\#pcontrast3 >'),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 12, 'outofrange_failed', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Systems Failture. \\#pcontrast3 >'),
