('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 23, 'title_d', 'Escape from the Imperial attack!'),
('string/en/spacequest/survival/tatooine_privateer_tier4_2c.stf', 24, 'trans_update', '\\#pcontrast3 Nav Computer: < \\#pcontrast1 Calculating egress route, %DI complete. \\#pcontrast3 >'),
