('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 1, 'arrived_at_loc', 'Intercept the incoming TIE ships at this location.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 8, 'first_attack', 'They are almost upon you pilot, our thoughts are with you...'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 9, 'found_loc', 'We calculated some coordinates to intercept the incoming TIE-Fighters.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 10, 'mission_complete', 'Gunboat Captain: < Great job pilot, we are out of here! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 11, 'outofrange', 'Gunboat Captain: < Move back to the Intercept coordinates or they will slip by! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 12, 'outofrange_failed', 'Gunboat Captain: < We are taking heavy damage from TIE Bombers! Perform emergency hyp..sp..e... >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 13, 'quest_defendpoint_d', 'Don''t let any of the Imperial fighters get past you. Our gunboat need about three minutes to calculate their jump to lightspeed.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 14, 'quest_defendpoint_t', 'Defend the area.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 15, 'quest_location_d', 'As if the Dathomir system wasn''t dangerous enough, several squadrons of TIE''s are heading your way! We know we''re asking a lot pilot but you have to cover the escape of our gunboat, we need those codes!'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 16, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 17, 'quest_reachpoint_d', 'Our reconnaissance ships tell us that these coordinates will put your right in between the incoming TIE''s and our fleeing gunboat.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 18, 'quest_reachpoint_t', 'Coordinates of intercept.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 19, 'quest_update', 'Gunboat Captain: < %TO >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 20, 'split_quest_alert', 'Rebel Command: < Our infiltrators succeded their mission but they have been discovered, you need to help them out! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 22, 'title', 'Dathomir system: Defend the gunboat.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 23, 'title_d', 'The Empire has caught up to what''s going on and are launching a full scale attack to destroy the gunboat you delivered the codes to. Cover the gunboats escape.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 24, 'trans_update', 'Gunboat Captain: < Our nav computer is calculating jump, %DI percent done. >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 25, 'transmission_received', 'Gunboat Captain: < Nav computer finished, prepare for jump to lightspeed! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_1_b.stf', 26, 'transmission_start', 'Gunboat Captain: < We need about three minutes pilot, hang in there! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 2, 'arrived_at_loc', 'Make a stand here, don''t let any Imperial ships get by you.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 9, 'first_attack', 'Here they come pilot!'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 10, 'found_loc', 'I hope you still have some fighting left in you pilot, we''re counting on you.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 11, 'mission_complete', 'Rebel Command: < Our team is safe. Get back to base pilot, you''ve more than deserved a long rest. >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 12, 'outofrange', 'Rebel Command: < Move back to original position, you''re too far out, fighters will slip by! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 13, 'outofrange_failed', 'Rebel Command: < A squad of TIE Interceptors slipped by! Return to base immediately! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 14, 'quest_defendpoint_d', 'Let none of the Imperial forces get by you. The commando team has estimated that it will take their crippled ship about three minutes to get prepared for the jump to lightspeed, you need to provide them with that time.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 15, 'quest_defendpoint_t', 'None shall pass!'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 16, 'quest_location_d', 'Not only have the Dathomir system been like an angry bee''s nest of Imperials lately, they know where you are and they are heading your way! Be ready for anything!'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 17, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 18, 'quest_reachpoint_d', 'These are the coordinates we have calculated will put you in the middle of our commando team and their pursuers. Proceed to there immediately.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 19, 'quest_reachpoint_t', 'Coordinates of interception.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 20, 'quest_update', 'Rebel Command: < %TO >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 23, 'title', 'Dathomir system: Make a stand.'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 24, 'title_d', 'You have helped the commando team break through the Imperial blockade but there''s multiple fighters still chasing after them. Get in their way and let none pass!'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 25, 'trans_update', 'Rebel Command: < Our commando team are %DI percent done with calculating their hyperspace jump, hang in there! >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 26, 'transmission_received', 'Rebel Command: < Our Commando team report that they are starting their hyperspace jump sequence. >'),
('string/en/spacequest/survival/tatooine_rebel_tier3_3_c.stf', 27, 'transmission_start', 'Rebel Command: < The Commando teams nav computer need about three minutes to calculate their hyperspace jump. Give them the time pilot! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 1, 'Quest Log Data', 'Text'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 2, 'arrived_at_loc', 'You are in the correct position pilot. Keep any ships out of the area until our recovery team is done, at all costs!'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 3, 'assigned_delayed', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 4, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 5, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 6, 'autorewardbody', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 7, 'autorewardfrom', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 8, 'autorewardsubject', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 9, 'first_attack', 'Here they come pilot, make me proud!'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 10, 'found_loc', 'A pirate attack took out one of the Empires new ships and it''s fairly intact. We have a recovery team nearby but the Empire is on their way as well. Proceed to these coordinates.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 11, 'mission_complete', 'You came through in the end after all, good.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 12, 'outofrange', 'General Ufwol: < You are too far from your assigned area, get back there now pilot! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 13, 'outofrange_failed', 'General Ufwol: < Our recovery team is getting pounded by enemy fighters and are forced to retreat. You are to return to base immediately! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 14, 'quest_defendpoint_d', 'Our reconnaissance ships are picking up several incoming Imperial fighters. Prepare for battle and make us proud pilot!'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 15, 'quest_defendpoint_t', 'Incoming Imperial fighters.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 16, 'quest_location_d', 'The area you''re heading in to have been the subject of several pirate attacks lately so be careful. As if that wasn''t enough though, the amount of Imperial forces closing in is staggering.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 17, 'quest_location_t', 'Dathomir system.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 18, 'quest_reachpoint_d', 'These are the coordinates assigned for you to defend. Keep an eye out for any enemy presence and let none get past you.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 19, 'quest_reachpoint_t', 'Assigned defense coordinates.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 20, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 21, 'split_quest_alert', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 22, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 23, 'title', 'Dathomir system: Protect the Alliance recovery team.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 24, 'title_d', 'A pirate attack in the Dathomir system against the Empires forces took out one of these new Imperial prototype ships. It''s fairly intact and one of our nearby recovery teams are moving in to collect it. Unfortunately the Empire is also moving in with a large force to make sure that nothing important was left behind by the pirates. You need to guard one of the possible routes that the Empires forces may take and prevent any of them from getting past you. The rest of our squadron is spread out guarding other intercept routes so you will be on your own out there. Good luck pilot!'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 25, 'trans_update', 'General Ufwol: < Our recovery team is about %DI percent done. Hang in there pilot! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 26, 'transmission_received', 'General Ufwol: < The recovery team is done and pulling out! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_2_b.stf', 27, 'transmission_start', 'General Ufwol: < Our recovery team is in position at the wreck and have begun the operation. >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 1, 'arrived_at_loc', 'This is right in the path the Imperial scum is taking to get to the debris before us. Don''t let anything get by pilot!'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 2, 'assigned_delayed', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 3, 'attack_notify', 'Tactical Computer: < Incoming fighter vessels. Scans show weapons armed. >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 4, 'attack_stopped', 'Tactical Computer: < No more fighter vessels within sensor range. >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 5, 'autorewardbody', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 6, 'autorewardfrom', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 7, 'autorewardsubject', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 8, 'first_attack', 'The Empire is sending everything they have, this will get rough! We''re trying to get reinforcements to you but for now, it''s in your hands pilot.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 9, 'found_loc', 'We need to buy the recovery team time, prcoeed to this location.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 10, 'mission_complete', 'General Ufwol: < Amazing work pilot! The recovery team is done and safely out of there. Get back to base for some well earned celebration. >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 11, 'outofrange', 'General Ufwol: < You''re too far away from the enemies route, they will get past you if you don''t get back quickly! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 12, 'outofrange_failed', 'General Ufwol: < Our recovery team is being annihilated! Get out of there while there''s still time! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 13, 'quest_defendpoint_d', 'The amount of Imperial forces heading your way is frightening. Fortunately, we have the best the Alliance can offer in their way, you!'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 14, 'quest_defendpoint_t', 'Fend off the Imperial attack.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 15, 'quest_location_d', 'You''re in a dangerous area of this dangerous system and the Imperial forces are on their way, full throttle. Prepare yourself and make the Crimson Phoenix and Alliance proud!'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 16, 'quest_location_t', 'Endor system.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 17, 'quest_reachpoint_d', 'This is the waypoint to intercept the oncoming Imperial forces from. Don''t stray from it too far or enemy fighters may slip past you.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 18, 'quest_reachpoint_t', 'Point of interception.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 19, 'quest_update', 'General Ufwol: < %TO >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 20, 'split_quest_alert', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 21, 'split_quest_alert_fail', ''),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 22, 'title', 'Endor system: Protect the Rebel recovery team.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 23, 'title_d', 'Good job pilot. Now we want the debris of that new ship that you destroyed so that we can find weaknesses in its construction. We have a recovery team on its way to collect it but unfortunately the Empire is sending a large force of their fighters to prevent our success. We need you to buy our recovery team enough time to complete their mission.'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 24, 'trans_update', 'General Ufwol: < The recovery team is %DI percent done. Hang in there pilot, we''re counting on you! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 25, 'transmission_received', 'General Ufwol: < The recovery team got all the debris, they are preparing to pull out, just a few more seconds! >'),
('string/en/spacequest/survival/tatooine_rebel_tier4_4_a.stf', 26, 'transmission_start', 'General Ufwol: < The recovery team has started the operation. They estimate they need about six minutes to complete the task. >'),
('string/en/spacequest/survival/test_survival.stf', 1, 'arrived_at_loc', 'The Rebel transmission will be easy to intercept here. Don''t stray too far from this point. The transmission should start at any moment.'),
('string/en/spacequest/survival/test_survival.stf', 2, 'assigned_delayed', ''),
