('string/en/spacequest/survival/test_survival.stf', 8, 'first_attack', 'System scans have detected Rebel ships at lightspeed moving in your direction. You''ve been detected. Defend yourself, but get that transmission!'),
('string/en/spacequest/survival/test_survival.stf', 9, 'found_loc', 'We''ve found an ideal location to intercept the Rebel beam-wave transmission. Go there now.'),
('string/en/spacequest/survival/test_survival.stf', 10, 'mission_complete', 'Good job, return to base with the transmission!'),
