('string/en/space_crafting_d.stf', 84, 'exp_durasteel_plating', 'Equipment Certification Level: 9\n\nA Mark V durasteel alloy that provides excellent protection for small starfighters.'),
('string/en/space_crafting_d.stf', 85, 'extended_life_battery_mk1', 'This is a component used in the manufacture of starfighter weapon capacitors.  This battery increases the amount of energy a capacitor can store, but has a slow recharge rate.'),
