('string/en/spawning/static_npc/herald_dantooine_force_crytsal_hunters_cave.stf', 27, 'player_1_1', 'Sure, I have nothing better to do.'),
('string/en/spawning/static_npc/herald_dantooine_force_crytsal_hunters_cave.stf', 28, 'player_2_1', 'No thanks. It sounds like some tall tale.'),
('string/en/spawning/static_npc/herald_dantooine_force_crytsal_hunters_cave.stf', 29, 'player_3_1', 'How did he say he found out about the place?'),
('string/en/spawning/static_npc/herald_dantooine_force_crytsal_hunters_cave.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_dantooine_force_crytsal_hunters_cave.stf', 31, 'player_5_1', ''),
