('string/en/spawning/static_npc/herald_dantooine_kunga_stronghold.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_dantooine_kunga_stronghold.stf', 2, 'dontknowyou_1', ''),
