('string/en/spawning/static_npc/herald_dantooine_kunga_stronghold.stf', 27, 'player_1_1', 'Yes, I wish to help the Empire.'),
('string/en/spawning/static_npc/herald_dantooine_kunga_stronghold.stf', 28, 'player_2_1', 'Sorry, I have more important things to do.'),
('string/en/spawning/static_npc/herald_dantooine_kunga_stronghold.stf', 29, 'player_3_1', 'Why are you concerned with the Dantari?'),
