('string/en/spawning/static_npc/herald_dantooine_mokk_stronghold.stf', 39, 'waypoint_description_1', 'According to Daiv, this cave system may or may not hold a tribe of Dantari called the Mokk.'),
('string/en/spawning/static_npc/herald_dantooine_mokk_stronghold.stf', 40, 'waypoint_name_1', 'Mokk Caves'),
