('string/en/spawning/static_npc/herald_endor_jinda_spiritualists.stf', 27, 'player_1_1', 'Sure, tell me.'),
('string/en/spawning/static_npc/herald_endor_jinda_spiritualists.stf', 28, 'player_2_1', 'Sorry, I have no gripes with the Ewoks!'),
('string/en/spawning/static_npc/herald_endor_jinda_spiritualists.stf', 29, 'player_3_1', 'Easy, friend. Why are you so angry?'),
('string/en/spawning/static_npc/herald_endor_jinda_spiritualists.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_endor_jinda_spiritualists.stf', 31, 'player_5_1', ''),
