('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 21, 'npc_reset', 'Well. Well... alright.'),
