('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 27, 'player_1_1', 'Sure, I''ll help those little guys!'),
('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 28, 'player_2_1', 'Sorry, I don''t care about Ewoks.'),
('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 29, 'player_3_1', 'What else do you help other than Ewoks?'),
('string/en/spawning/static_npc/herald_endor_korga_cave.stf', 30, 'player_4_1', ''),
