('string/en/spawning/static_npc/herald_endor_marauder_orphans.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_endor_marauder_orphans.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_endor_marauder_orphans.stf', 27, 'player_1_1', 'Yeah, sounds like fun.'),
('string/en/spawning/static_npc/herald_endor_marauder_orphans.stf', 28, 'player_2_1', 'No thanks. I''m not a Bounty Hunter.'),
