('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 21, 'npc_reset', 'What could be better than sailing the spacelanes and boarding vessels! HA! It sounds like a great life! Well, you''re missing out, I say!'),
('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 23, 'npc_smuggle_1', ''),
