('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 27, 'player_1_1', 'Yes! The pirate''s life is for me!'),
('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 28, 'player_2_1', 'No thanks, I don''t want to be a pirate.'),
('string/en/spawning/static_npc/herald_lok_canyon_corsair_stronghold.stf', 29, 'player_3_1', 'Did you say you were hit on the head?'),
