('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 27, 'player_1_1', 'Sure, I''ll do it for you.'),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 28, 'player_2_1', 'Sorry, I''m busy.'),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 29, 'player_3_1', 'What kind of specialty food do they buy?'),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 32, 'player_more_1_1', ''),
