('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 35, 'player_reset', 'No. I decided to quit looking.'),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 36, 'player_sorry', 'I am still looking for them.'),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 39, 'waypoint_description_1', 'This is where a group of people have purchased large amounts of food.'),
('string/en/spawning/static_npc/herald_lok_kimogila_cult.stf', 40, 'waypoint_name_1', 'Mysterious Customers'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 7, 'npc_1_1', 'Har, har, har! Do you want to hear a good one? I heard some Gungans today saying that they''ve got some kind of monastery where they train their elite warriors! Elite Gungans? HAR, HAR, HAR! That''s hilarious! Wanna know where they claim the temple is?'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 8, 'npc_2_1', 'So they say it''s out past the swamps. One of them dared me to go make fun of them to their face. I''m gonna have a few more drinks with the boys, then we''ll all show up. I''ve marked it on your datapad, so you can also make fun of them as well.'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 9, 'npc_3_1', 'Oh you''re one of them Gungan lovers, aren''t you? I bet your momma was Gungan, wasn''t she? Well heck anytime you want to know where your momma came from, you just tell me, okay?'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 10, 'npc_4_1', 'I couldn''t tell with all that "meesa" and ''yoosa" junk. They said they train their most sacred warriors there, and that only a few Gungans are even allowed to train with them. Something about snatching the Boomba from the Faamba''s mouth, or somethin''. Wanna know where it is?'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 13, 'npc_backtowork_1', 'Good luck, then.'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 15, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 16, 'npc_failure_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 17, 'npc_more_1_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 18, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 21, 'npc_reset', 'Oh you''re one of them Gungan lovers, aren''t you? I bet your momma was Gungan, wasn''t she? Well heck anytime you want to know where your momma came from, you just tell me, okay?'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 25, 'npc_work_1', 'Did you find the gungan warrior encampment?'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 27, 'player_1_1', 'Sure, I''d love to know!'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 28, 'player_2_1', 'No thanks. Gungans should be respected just as much as anyone else.'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 29, 'player_3_1', 'What did they say about the monastery?'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 35, 'player_reset', 'I decided to quit looking.'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 36, 'player_sorry', 'Not yet. I''m still looking.'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 39, 'waypoint_description_1', 'A sacred place of learning and training, Gungan warriors guard this place with their lives.'),
('string/en/spawning/static_npc/herald_naboo_gungan_warrior_stronghold.stf', 40, 'waypoint_name_1', 'Gungan Warrior Stronghold'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 2, 'dontknowyou_1', ''),
