INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 7, 'npc_1_1', 'Wanna know the truth? I mean the real TRUTH! Ever heard of the Death Star? It was real, man! How do I know? Because I know where they were inventing it, and I know where they''re making other things, too! I can tell if you if you''re a fellow believer.'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 8, 'npc_2_1', 'Okay, it''s a ways out there. I''ll show you on your datapad. Watch out, though. The Empire doesn''t want their little secrets getting out, but we''ll all know one day. I''m telling you, the truth is out there. Go see it for yourself and you''ll believe!'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 9, 'npc_3_1', 'Yeah, you say that now. You just wait, though. One day the Empire''s going to come knocking on your door with some kind of stormtrooper droid, then no one''s going to ever hear from you again. You''ll see...'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 10, 'npc_4_1', 'I was traveling from Theed to Moenia,  right? Well, I got lost and saw some stormtroopers, right? I asked them for directions, and they told me to "move along". What was behind them? Yeah... some droid-looking stormtrooper. See what I''m saying?'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 13, 'npc_backtowork_1', 'Okay, it''s a ways out there. I''ll show you on your datapad. Watch out, though. The Empire doesn''t want their little secrets getting out, but we''ll all know one day. I''m telling you, the truth is out there. Go see it for yourself and you''ll believe!'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 15, 'npc_dropoff_1', ''),
