('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 21, 'npc_reset', 'Yeah, you say that now. You just wait, though. One day the Empire''s going to come knocking on your door with some kind of stormtrooper droid, then no one''s going to ever hear from you again. You''ll see...'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 27, 'player_1_1', 'Yes, I believe you! Tell me where!'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 28, 'player_2_1', 'No thanks... you sound a bit out there yourself.'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 29, 'player_3_1', 'How did you find out?'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 31, 'player_5_1', ''),
