('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 35, 'player_reset', 'I decided to quit looking.'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 39, 'waypoint_description_1', 'A top secret area patrolled by all manner of stormtroopers and droids. This is a restricted area.'),
('string/en/spawning/static_npc/herald_naboo_imperial_weapon_research_facility.stf', 40, 'waypoint_name_1', 'Imperial Weapon Research Facility'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 7, 'npc_1_1', 'You there! You have the look of someone who spends their time with? unsavory characters. Would you be interested in knowing where others of your kind can be found? I''m sure these hired killers have a lot of credits just laying around. Interested?'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 8, 'npc_2_1', 'Yes, yes you looked like someone who would be motivated by greed. I''ll mark it on your datapad. Make sure you tell everyone you know? that''ll teach these Maulers to turn me down. Ha! Their secret base isn''t so secret anymore, is it?'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 9, 'npc_3_1', 'Oh! MY attitude? You don''t like MY attitude? I''ll have you know I''m one of the most well respected people within the higher circles of the Naboo Nobility. You, on the other hand, look to be nothing more than a simple street narglatch! Be off with you.'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 10, 'npc_4_1', 'There''s a group of assassi?er, I mean to say, exterminators who are well known for their skills. Well, they turned down my money, and I''ll have none of that! I''m making it a point that everyone knows where their base is to teach them a lesson! Interested?'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 13, 'npc_backtowork_1', 'Yes, yes you looked like someone who would be motivated by greed. I''ll mark it on your datapad. Make sure you tell everyone you know? that''ll teach these Maulers to turn me down. Ha! Their secret base isn''t so secret anymore, is it?'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 15, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 16, 'npc_failure_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 17, 'npc_more_1_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 18, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 21, 'npc_reset', 'Oh! MY attitude? You don''t like MY attitude? I''ll have you know I''m one of the most well respected people within the higher circles of the Naboo Nobility. You, on the other hand, look to be nothing more than a simple street narglatch! Be off with you.'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 27, 'player_1_1', 'Sure!'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 28, 'player_2_1', 'No thanks. I don''t like your attitude.'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 29, 'player_3_1', 'Why are you telling me this?'),
('string/en/spawning/static_npc/herald_naboo_mauler_encampment.stf', 30, 'player_4_1', ''),
