('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 25, 'npc_work_1', 'Did you locate the veermok cave?'),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 27, 'player_1_1', 'Yes, I''d be interested in knowing.'),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 28, 'player_2_1', 'No thanks.'),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 29, 'player_3_1', 'What happened at the Jandosan Mines?'),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 35, 'player_reset', 'I have decided to skip this little adventure.'),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 39, 'waypoint_description_1', 'This is an ancient ore mine that was overtaken by a troupe of Giant Veermoks.'),
('string/en/spawning/static_npc/herald_naboo_veermok_cave.stf', 40, 'waypoint_name_1', 'Veermok Cave'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 7, 'npc_1_1', 'You must help me! My husband was telling our kids about the caves filled with Borgles, and it seems they went off to go see the caves firsthand. I''m afraid the worst has happened to them!'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 8, 'npc_2_1', 'Oh, thank you! Here is where the caves are. If you see them there, let them know that if they don''t come home soon, they''ll miss dinner.'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 9, 'npc_3_1', 'I wish my kids had the same common sense as you!'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 10, 'npc_4_1', 'I tried doing that already. He told me that the kids have to learn the hard way. Needless to say, I''ve kicked him out until my kids get home safely. Will you please help?'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 13, 'npc_backtowork_1', 'Oh, thank you! Here is where the caves are. If you see them there, let them know that if they don''t come home soon, they''ll miss dinner.'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 15, 'npc_dropoff_1', ''),
