('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 18, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 21, 'npc_reset', 'I wish my kids had the same common sense as you!'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 25, 'npc_work_1', 'Did you find the borgle bats cave?'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 27, 'player_1_1', 'Sure, I''ll help you.'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 28, 'player_2_1', 'No thanks, sounds too dangerous.'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 29, 'player_3_1', 'Why don''t you get your husband to find them?'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 32, 'player_more_1_1', ''),
