('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 35, 'player_reset', 'I decided to stop looking.'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 39, 'waypoint_description_1', 'A natural home to the most successful predators on Rori, the Borgle Bat Caves can be quite dangerous.'),
('string/en/spawning/static_npc/herald_rori_borgle_bat_cave.stf', 40, 'waypoint_name_1', 'Borgle Bat Caves'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 7, 'npc_1_1', 'Are you interested in helping you fellow citizens of Rori? We''re recruiting people to help put a stop to the menace posed by the Cobrals. We''re asking everyone to do their part and help eradicate this threat. Are you willing to do your part?'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 8, 'npc_2_1', 'You''re the kind of person we were looking for! Here''s where you can find the Cobral hideout. Go out there and give them everything you''ve got! We can''t pay you, but you can take anything you find on them.'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 9, 'npc_3_1', 'That''s a shame, kid. Without people like you helping, the Cobrals will eventually come up with some dastardly plan that will have all of Rori under their control. Think on that, then come back when you''re interested.'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 10, 'npc_4_1', 'They are an organization comprised by some of the most despicable individuals on Rori. They are being led by the evil Cobral Overlord, who is bent on the domination of this moon. Only if everyone comes together can we finally put a stop to them.'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 13, 'npc_backtowork_1', 'Good. Go out there and give them everything you''ve got! We can''t pay you, but you can take anything you find on them.'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 15, 'npc_dropoff_1', ''),
