('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 25, 'npc_work_1', 'Did you find those Cobral?'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 27, 'player_1_1', 'Yes, I''ll do my part!'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 28, 'player_2_1', 'Sorry, I don''t want to get involved.'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 29, 'player_3_1', 'Who are the Cobrals?'),
