('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 39, 'waypoint_description_1', 'The evil Cobral organization forged Imperial documents to get a hold of this fortress.'),
('string/en/spawning/static_npc/herald_rori_cobral_hideout.stf', 40, 'waypoint_name_1', 'Cobral Hideout'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 7, 'npc_1_1', 'If you''re interested, I have a business proposal for you. I inherited a farm recently, but it''s been overrun by all manners of creatures. I can''t handle them myself, but if you can help clear them, I let you have any of the resources that are there. Interested?'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 8, 'npc_2_1', 'My dad said it was just a ways off from here. I''ll mark the area on your datapad. Remember, kill any of the creatures you find and those resources are all yours. I just want to honor my fathers dying wish of killing all those critters.'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 9, 'npc_3_1', 'Well, I can understand. I should be able to find someone who''s willing to make some money off of some old-fashioned hard work. Have a good day.'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 10, 'npc_4_1', 'My dad built that farm with his own bare hands! About 20 years ago, there was a good summer for breeding and all kinds of creatures started showing up, eventually driving him off of his own property. His dying wish was to see everyone of those creatures dead!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
