('string/en/spawning/static_npc/herald_rori_creature_village.stf', 27, 'player_1_1', 'Sounds good to me. Where is it?'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 28, 'player_2_1', 'Sorry, I''m not interested.'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 29, 'player_3_1', 'What kind of inheritance is a farm?'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 31, 'player_5_1', ''),
