('string/en/spawning/static_npc/herald_rori_creature_village.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 35, 'player_reset', 'I have decided to stop looking.'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 39, 'waypoint_description_1', 'What was once a farm is now a breeding ground for all kinds of creatures.'),
('string/en/spawning/static_npc/herald_rori_creature_village.stf', 40, 'waypoint_name_1', 'Creature Village'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 7, 'npc_1_1', 'Are you one of those Rebel types? If so, I know a place where you can do some serious damage to them, if you''re in that kind of mind. You interested?'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 8, 'npc_2_1', 'You can find a Hyperdrive yard where I marked it on your datapad. Mind you, I''m not going to help you with blowing up the place, but it sure will keep me warm at night knowing they got their just desserts for snubbing me.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 9, 'npc_3_1', 'Well, I can''t blame you. I''m not going to run out there and do anything myself, either. I was just hoping someone who already planned on doing so would focus their anger on the place the put me out of business.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 10, 'npc_4_1', 'Because they undersold me, that''s why! I used to work on making some real fine hyperdrives for them, but then they went off and bought my company right out from under me. That place used to be mine, and I swear I''m not going to see it owned by anyone else!'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 13, 'npc_backtowork_1', 'You can find a Hyperdrive yard where I marked it on your datapad. Mind you, I''m not going to help you with blowing up the place, but it sure will keep me warm at night knowing they got their just desserts for snubbing me.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 14, 'npc_breech_1', ''),
