('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 21, 'npc_reset', 'Well, I can''t blame you. I''m not going to run out there and do anything myself, either. I was just hoping someone who already planned on doing so would focus their anger on the place the put me out of business.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 23, 'npc_smuggle_1', ''),
