('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 27, 'player_1_1', 'Sure. Tell me where.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 28, 'player_2_1', 'No thanks. I''m not into sabotage.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 29, 'player_3_1', 'Why do you want to see the Empire hurt?'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 35, 'player_reset', 'Actually, I''ve decided to quit.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 37, 'return_waypoint_description_1', ''),
