('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 39, 'waypoint_description_1', 'A network of underground chambers houses a vast assortment of hyperdrives'),
('string/en/spawning/static_npc/herald_rori_imperial_hyperdrive_research_facility.stf', 40, 'waypoint_name_1', 'Imperial Hyperdrive Research Facility'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 7, 'npc_1_1', 'This declaration concerns all Rebels and sympathizers to the Rebel cause. The Empire has chosen to end it''s war with Rebellion. The Empire is offering amnesty to all Rebels, and has set a meeting location for peace negotiations. Are you interested in peace with the Empire?'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 8, 'npc_2_1', 'I will mark it on your datapad for you. As a sign of our trust, during the peace meeting the Empire has disarmed and asks you to do the same. This offer apply to those who are openly Rebels, therefore you will need to announce your intent. Good luck? I mean? Good day, citizen.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 9, 'npc_3_1', 'Very good, citizen. It is refreshing to hear open loyalty to the Emperor. I would offer you the warning to not approach the area we are herding these Rebels to. The stormtroopers there have orders of shoot to kill. Please direct any rebellious citizens my way, thank you.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 10, 'npc_4_1', 'Absolutely. The Emperor has decreed that the war has taken too much of a toll on both sides. He feels that proper negotiation can solve many problems. He has even suggested that there will be a celebration of tea and cookies when the negotiations are complete.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 13, 'npc_backtowork_1', 'I will mark it on your datapad for you. As a sign of our trust, during the peace meeting the Empire has disarmed and asks you to do the same. This offer apply to those who are openly Rebels, therefore you will need to announce your intent. Good luck. I mean, good day, citizen.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 15, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 16, 'npc_failure_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 17, 'npc_more_1_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 18, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 21, 'npc_reset', 'Very good, citizen. It is refreshing to hear open loyalty to the Emperor. I would offer you the warning to not approach the area we are herding these Rebels to. The stormtroopers there have orders of shoot to kill. Please direct any rebellious citizens my way, thank you.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 25, 'npc_work_1', 'Done already?'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 27, 'player_1_1', 'Yes, I am. Where can I sign the peace treaty?'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 28, 'player_2_1', 'Sorry, but I''m not some Rebel scum.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 29, 'player_3_1', 'So the Galactic Civil War is finally over?'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 35, 'player_reset', 'I''ve decided to skip this little adventure.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 36, 'player_sorry', 'Not yet. I am still working.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 39, 'waypoint_description_1', 'A forward military base constructed by the Imperials for unknown reasons.'),
('string/en/spawning/static_npc/herald_rori_imperial_military_base.stf', 40, 'waypoint_name_1', 'Imperial Military Base'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 7, 'npc_1_1', 'You need to help us! The city government has proof that the Kobola crime syndicate has established a presence here on Rori. The Empire has ignored our pleas for help, so we''re asking everyone else to help us! Will you help us to rid ourselves of this threat?'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 8, 'npc_2_1', 'Spectacular! This is where we think the Kobola are hiding out, mining spice. If you find any citizens in there, try to help them escape as well. Thank you!'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 9, 'npc_3_1', 'That''s exactly what the Empire said too. If you don''t help us, who will?'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 10, 'npc_4_1', 'People from the surrounding cities have been disappearing without a trace. At first we though it was some wild creature, until we found someone who escaped from the mines. They told us how slaves are being forced to mine spice at blaster point!'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 13, 'npc_backtowork_1', 'If you find any citizens in there, try to help them escape as well. Thank you!'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 15, 'npc_dropoff_1', ''),
