('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 21, 'npc_reset', 'That''s exactly what the Empire said too. If you don''t help us, who will?'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 27, 'player_1_1', 'Yes, I''ll help you.'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 28, 'player_2_1', 'Sorry, this doesn''t involve me.'),
('string/en/spawning/static_npc/herald_rori_kobola_spice_mine.stf', 29, 'player_3_1', 'What is your proof?'),
