('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 7, 'npc_1_1', 'We are members of the True Aakuan Order. We are asking any of those who have a streak of individualism to come forth an help stop a threat to our planet. Are you someone who finds that they will be the one to come forward and fulfill their destiny?'),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 8, 'npc_2_1', 'Yes, you are the one. A powerful anarchist has subverted our order of philosophical thinkers and has brainwashed them. They all need to be killed to bring back the balance to all things. Go find them and bring to them the gift of balance - with your blaster.'),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 9, 'npc_3_1', 'You speak as if we are brothers, but we are not. You are one who is out of balance, yet you do not wish to see it. If you wish to become one with a harmonious nature, seek us out and we will show you where your lessons can begin.'),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 10, 'npc_4_1', 'We practice a philosophy of eternal balance. There is nothing that is so powerful that you must bend your will to it. One of our order has become unbalanced and now spreads his will to everyone. Anyone who will not listen to him, his followers are instructed to destroy. Will you be the one fortold to be of assistance?'),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 13, 'npc_backtowork_1', 'Go find them and bring to them the gift of balance - with your blaster.'),
('string/en/spawning/static_npc/herald_talus_aakuan_champions.stf', 14, 'npc_breech_1', ''),
