('string/en/spawning/static_npc/herald_talus_berserk_khmurra.stf', 27, 'player_1_1', 'Sure! I like killing critters!'),
('string/en/spawning/static_npc/herald_talus_berserk_khmurra.stf', 28, 'player_2_1', 'No thanks. I don''t like the way this sounds.'),
