('string/en/spawning/static_npc/herald_talus_binyare_pirate_base.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_talus_binyare_pirate_base.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_talus_binyare_pirate_base.stf', 27, 'player_1_1', 'Sure, I''ll help to kill them all.'),
('string/en/spawning/static_npc/herald_talus_binyare_pirate_base.stf', 28, 'player_2_1', 'No thanks.'),
('string/en/spawning/static_npc/herald_talus_binyare_pirate_base.stf', 29, 'player_3_1', 'Why don''t you do it yourself?'),
('string/en/spawning/static_npc/herald_talus_binyare_pirate_base.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_talus_binyare_pirate_base.stf', 31, 'player_5_1', ''),
