('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 17, 'npc_more_1_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 18, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 21, 'npc_reset', 'Go figure. Offer someone a good paying job, and they turn it down because they don''t want to get their hands dirty. Get out of my face!'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 25, 'npc_work_1', 'Did you find them?'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 27, 'player_1_1', 'Yes, I''m interested.'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 28, 'player_2_1', 'No thanks.'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 29, 'player_3_1', 'Why are you offering this to me?'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 35, 'player_reset', 'No. I''ve decided to stop looking.'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 36, 'player_sorry', 'I am still looking.'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 39, 'waypoint_description_1', 'These Aqualish have decided to make this system of natural caves their base of operations.'),
('string/en/spawning/static_npc/herald_talus_lost_aqualish_war_party.stf', 40, 'waypoint_name_1', 'Lost Aqualish War Party'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 7, 'npc_1_1', 'Have you ever heard of the story that young Sand People boys prove their age of ascension by going out and touching the nose of a Krayt Dragon? Me and my friends know where to find one and are going to do it tomorrow. You wanna go too?'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 8, 'npc_2_1', 'Yeah, me too! I don''t think they''re as scary as they''re made out to be. This is where my grandpa told me where he saw one when he was a kid! Good luck!'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 9, 'npc_3_1', 'You''re just scared, that''s all. Me and my friends aren''t scared... well, not that much.'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 10, 'npc_4_1', 'We''ve been told stories all about it. My grandpa said he knew where one used to live. He said he found the Dragon in the cave and punched it in the nose. My grandpa''s a good guy and he wouldn''t lie, no-siree!'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 13, 'npc_backtowork_1', 'Good luck!'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 15, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 16, 'npc_failure_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 17, 'npc_more_1_1', ''),
