('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 21, 'npc_reset', 'You''re just scared, that''s all. Me and my friends aren''t scared... well, not that much.'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 25, 'npc_work_1', 'Did you find it?'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 27, 'player_1_1', 'I''d love to see a Krayt Dragon!'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 28, 'player_2_1', 'A Krayt Dragon? No thanks!'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 29, 'player_3_1', 'Where do you plan to find a Krayt Dragon?'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 35, 'player_reset', 'I have decided to quit looking.'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 39, 'waypoint_description_1', 'A cave where it''s rumored a Krayt Dragon lives... well, as of 80 years ago, that is.'),
('string/en/spawning/static_npc/herald_tatooine_beetle_cave.stf', 40, 'waypoint_name_1', 'Mysterious Cave'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 7, 'npc_1_1', 'Would you mind helping an old man? I have a friend who went out to look at Fort Tusken to try to get rid of the Sand People. The problem is that I haven''t heard from him for over a year now. Could you go out there and see if he''s still alive? I''d greatly appreciate it.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 8, 'npc_2_1', 'Oh, wonderful. I''d do it myself, but I''m afraid those Tuskens would get me before I knew it. I doubt he''s still alive out there, but if you see him, tell Old Ben I said "Hi". Thanks again, friend.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 9, 'npc_3_1', 'I don''t blame you. I''m scared of them myself. Well, it didn''t hurt to ask. Thanks anyway.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 10, 'npc_4_1', 'I''m not sure. He said he knew a good trick on scaring them away, but said it was a secret. All I know is that he left one day with some kid and that''s the last I saw of him.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 13, 'npc_backtowork_1', 'Oh, wonderful. I''d do it myself, but I''m afraid those Tuskens would get me before I knew it. I doubt he''s still alive out there, but if you see him, tell Old Ben I said "Hi". Thanks again, friend.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 15, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 16, 'npc_failure_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 17, 'npc_more_1_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 18, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 21, 'npc_reset', 'I don''t blame you. I''m scared of them myself. Well, it didn''t hurt to ask. Thanks anyway.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 25, 'npc_work_1', 'Did you find it?'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 27, 'player_1_1', 'Sure, I''ll do it for you.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 28, 'player_2_1', 'Sorry, I''m scared of Sand People.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 29, 'player_3_1', 'How was he planning on getting rid of the Tuskens?'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 31, 'player_5_1', ''),
