('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 35, 'player_reset', 'I''ve decided to stop looking. I have other things to do.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 39, 'waypoint_description_1', 'Originally the first Human settlement on Tatooine, Fort Tusken has been home to Sandpeople for over a century.'),
('string/en/spawning/static_npc/herald_tatooine_fort_tusken.stf', 40, 'waypoint_name_1', 'Fort Tusken'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 7, 'npc_1_1', 'Hic * Hey, you wanna help a guy out? I''m gonna go show that Jabba that he can''t push me around anymore. I know where he keeps all his stuff hidden away, and I''m * hic* goin'' there to take it from him. I bet you wanna know where it is, don''t you?'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 8, 'npc_2_1', 'Yeah, I thought you did. Let me see your datapad yeah.. it''s over * hic * here somewhere. You can meet me out there and we''ll take all of his loot! I''ll let * hic * you have half the stuff. Heyyyy.... what are best friends for, eh?'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 9, 'npc_3_1', '''Cause you don''t have a spine, that''s why! You''re just like that * hic * slug! Why don''t you come back here when you get some courage, eh? You can get some from the cantina like me, in case you don''t know where * hic * to get it.'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 10, 'npc_4_1', 'What did he do to me?! WHAT DID HE * hic * DO TO ME?! He... erm... he went ahead and... er... I don''t * hic * know anymore. It doesn''t matter! He needs to be set straight! And taking all his stuff will show him who''s the master, right! Wanna know where he keeps the stuff?'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 13, 'npc_backtowork_1', 'Yeah, I though you did. Let me see your datapad, yeah.. it''s over * hic * here somewhere. You can meet me out there and we''ll take all of his loot! I''ll let * hic * you have half the stuff. Heyyyy... what are best friends for, eh?'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 15, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 16, 'npc_failure_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 17, 'npc_more_1_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 18, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 19, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 20, 'npc_noloc_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 21, 'npc_reset', '''Cause you don''t have a spine, that''s why! You''re just like that * hic * slug! Why don''t you come back here when you get some courage, eh? You can get some from the cantina like me, in case you don''t know where * hic * to get it.'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 25, 'npc_work_1', 'Did you find it?'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 27, 'player_1_1', 'Yes, I''d like to know.'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 28, 'player_2_1', 'No thanks. I don''t like messing with Jabba.'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 29, 'player_3_1', 'What did Jabba do to you?'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 35, 'player_reset', 'No. I decided to stop looking. Wonder why?'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 36, 'player_sorry', 'No. Not yet. I am still looking. I would still like to know...'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 39, 'waypoint_description_1', 'A safehouse for Jabba''s "stuff". Many looted items find themselves here before inspection.'),
('string/en/spawning/static_npc/herald_tatooine_hutt_hideout.stf', 40, 'waypoint_name_1', 'Hutt Hideout'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 7, 'npc_1_1', 'An informant has let us know that there is a small band of Rebels that have set up camp nearby. Since the Empire proper cannot investigate this claim, you are being charged with the duty of doing reconnaissance. Are you ready for the coordinates?'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 8, 'npc_2_1', 'According to the informant''s information, you should be able to find these rebels at this location. The intelligence we have is that they are small in number, and should be able to be easily handled. You may be called upon later by the Empire for further information.'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 9, 'npc_3_1', 'The only acceptable answer will be that you have a precious assignment by someone of higher rank than myself. This is the case, I presume?'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 10, 'npc_4_1', 'We have lost some numbers due to Sandpeople raids recently. Since this is not a major threat, we do not have the resources to direct towards these Rebels. According to our information, there should only be a small number of them there. Ready for your coordinates?'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 13, 'npc_backtowork_1', 'According to the informant''s information, you should be able to find these rebels at this location. The intelligence we have is that they are small in number, and should be able to be easily handled. You may be called upon later by the Empire for further information.'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 14, 'npc_breech_1', ''),
