('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 28, 'player_2_1', 'No sir, I cannot do this.'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 29, 'player_3_1', 'Why doesn''t the Empire take care of this matter personally?'),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_tatooine_rebel_military_base.stf', 31, 'player_5_1', ''),
