('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 21, 'npc_reset', 'How could you pass up an opportunity of a lifetime like this. Something like this just doesn''t fall into your lap everyday! Take intiative! Take a chance! Take my word - squill hides are the future!'),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 22, 'npc_reward_1', ''),
