('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 25, 'npc_work_1', 'Did you find the squills'' lair?'),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 27, 'player_1_1', 'Yes! Yes! Tell me more!!!'),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 28, 'player_2_1', 'Sorry, I''m not interested.'),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 29, 'player_3_1', 'Are squill that popular of a commodity?'),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 30, 'player_4_1', ''),
