('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 39, 'waypoint_description_1', 'A den of squill that have enjoyed a tremendous upswing in their population due to easily available food.'),
('string/en/spawning/static_npc/herald_tatooine_squill_cave.stf', 40, 'waypoint_name_1', 'Squill Cave'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 7, 'npc_1_1', 'If you''re loyal to the Empire, I have need of your services. The Empire needs you to venture forward and kill as many Sand People as you can, specifically in a known region where they have taken control of a key facility. Will you do this for your Emperor?'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 8, 'npc_2_1', 'Very good. Here are the coordinates to the facility. Remember - like a Rebel, the only good Tusken is a dead one. The more that are killed, the easier it will be to launch an assault on the facility to take it back.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 9, 'npc_3_1', 'That is a very disrespectful tone to take, citizen. If I didn''t know better, I''d say that was some the type of statement a Rebel sympathizer would make. You''re not one of those Rebel scum, are you?'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 10, 'npc_4_1', 'The Empire does not answer to you citizen. You answer to the Empire. The Empire is not obligated to tell you that it lost a facility to the Sand People and that no one has reported it to Prefect Talmont yet for fear of being reprimanded. Yes, you are not privy to that type of information.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 13, 'npc_backtowork_1', 'Very good. Here are the coordinates to the facility. Remember - like a Rebel, the only good Tusken is a dead one. The more that are killed, the easier it will be to launch an assault on the facility to take it back.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 14, 'npc_breech_1', ''),
