('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 27, 'player_1_1', 'Yes, I will do so!'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 28, 'player_2_1', 'Sorry, he''s not my Emperor.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 29, 'player_3_1', 'Why doesn''t the Empire just do it itself?'),
