('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 39, 'waypoint_description_1', 'An Imperial Base now controlled by Tusken Raiders.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_bunker.stf', 40, 'waypoint_name_1', 'Tusken Bunker'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 7, 'npc_1_1', 'Listen here! We''re pleading for help from anyone that will listen. Our village was overrun by Tuskens a while back, and the Empire won''t send anyone out there to help! You have to help us take back our village! Will you help us?'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 8, 'npc_2_1', 'The village is out in the wastelands and not easy to find. I''ll show you where it is on your datapad. Please kill those Tuskens before that Tusken King comes back and continues to pluck off the refugees one by one.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 9, 'npc_3_1', 'First the Empire won''t help, now you won''t. Will anyone help us? I hate this planet!'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 10, 'npc_4_1', 'We were targeted by a Tusken War Party and we weren''t able to hold them off! We''re still hearty folk, though, so we''re not leaving. Well, that is unless the King of the Tuskens stop killing us off. He''s hunting us down one by one like we''re Eopie or something. Will you help us?'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 13, 'npc_backtowork_1', 'The village is out in the wastelands and not easy to find. I''ll show you where it is on your datapad. Please kill those Tuskens before that Tusken King comes back and continues to pluck off the refugees one by one.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 14, 'npc_breech_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 15, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 16, 'npc_failure_1', ''),
