('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 21, 'npc_reset', 'First the Empire won''t help, now you won''t. Will anyone help us? I hate this planet!'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 22, 'npc_reward_1', ''),
