('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 25, 'npc_work_1', 'Did you find the village?'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 27, 'player_1_1', 'Sure, I''ll help stop those Tuskens! Where''s the village?'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 28, 'player_2_1', 'Sorry, but I don''t want to tangle with Tuskens.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 29, 'player_3_1', 'What happened to your village?'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 31, 'player_5_1', ''),
