('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 35, 'player_reset', 'I cannot do this right now. I have other matters to attend to.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
