('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 39, 'waypoint_description_1', 'A village of moisture farmers have lost their homes to marauding Tuskens.'),
('string/en/spawning/static_npc/herald_tatooine_tusken_village.stf', 40, 'waypoint_name_1', 'Tusken Village'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 7, 'npc_1_1', 'What are you standing around for? The Empire has us pinned down and you''re just gawking? Look, we need your help. The Empire has setup a facility nearby, and we''ve managed to break through their lines to gain entrance to their outpost. You have to join the rest of the Alliance forces out there and help wipe out the Empire!'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 8, 'npc_2_1', 'I''ll mark it on your datapad. Now get out there and help topple the Empire!'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 9, 'npc_3_1', 'If you don''t help, who will? If you casually stand aside as the Empire has it''s way, we''ll all be slaves to the Emperor!'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 10, 'npc_4_1', 'It''s a standard forward base where they re-supply their troops and tend to the wounded. If we can get them here, we might be able to push the Empire back long enough for everyone to make it off of the planet.'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 13, 'npc_backtowork_1', 'I''ll mark it on your datapad. Now get out there and help topple the Empire!'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 14, 'npc_breech_1', ''),
