('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 25, 'npc_work_1', 'Did you locate the outpost?'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 27, 'player_1_1', 'Sure, I''ll help! Where is it?'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 28, 'player_2_1', 'Sorry, I can''t help.'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 29, 'player_3_1', 'What kind of base does the Empire have?'),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_yavin_imperial_outpost.stf', 31, 'player_5_1', ''),
