('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 27, 'player_1_1', 'Sounds interesting. Sure!'),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 28, 'player_2_1', 'No thanks.'),
