('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 35, 'player_reset', 'No. I cannot continue to look right now.'),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 39, 'waypoint_description_1', 'Though the original builders are long gone, woolamanders have taken up residence here.'),
('string/en/spawning/static_npc/herald_yavin_palace_of_the_woolamander.stf', 40, 'waypoint_name_1', 'Palace of the Woolamander'),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 1, 'cant_work', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 2, 'dontknowyou_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 3, 'gotowork_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 4, 'next', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 5, 'notit_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 6, 'notyet', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 7, 'npc_1_1', 'Do you wish power, friend? A power that is stronger than even the might of the Empire? A power stronger than the Empire contained within your fingertips? Yessss... your eyes betray you... Then I shall lead you to where you may fulfill your destiny. Just speak the words.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 8, 'npc_2_1', 'Yesss... you will find it within a Temple shrouded by ages of neglect. Within the temple lies the secrets to power. Only those that are strong enough to endure the trials will find what lies in the heart of the Temple. Those that are weak will guard the temple for the rest of eternity...'),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 9, 'npc_3_1', 'You use insults to express your feelings of fear... this is your first step to the path of power... let this build within you, friend.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 10, 'npc_4_1', 'Unimaginable power held and taught by the greatest master this galaxy has ever seen. You are interested in holding this power, are you not? Yesss... Yes, you are.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 11, 'npc_5_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 12, 'npc_6_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 13, 'npc_backtowork_1', 'Yesss... you will find it within a Temple shrouded by ages of neglect. Within the temple lies the secrets to power. Only those that are strong enough to endure the trials will find what lies in the heart of the Temple. Those that are weak will guard the temple for the rest of eternity...'),
('string/en/spawning/static_npc/herald_yavin_temple_of_exarkun.stf', 14, 'npc_breech_1', ''),
