('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 22, 'npc_reward_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 23, 'npc_smuggle_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 24, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 25, 'npc_work_1', 'Did you find it?'),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 26, 'otherescort_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 27, 'player_1_1', 'Sure, I''ll help you guys.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 28, 'player_2_1', 'Sorry, I''m too busy.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 29, 'player_3_1', 'What are these business expansions?'),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 30, 'player_4_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 31, 'player_5_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 32, 'player_more_1_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 33, 'player_more_2_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 34, 'player_more_3_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 35, 'player_reset', 'I''ve decided to do something else.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 36, 'player_sorry', 'Not yet. I am still looking.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 37, 'return_waypoint_description_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 38, 'return_waypoint_name_1', ''),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 39, 'waypoint_description_1', 'An old temple that the travel agent has assured you is perfectly safe.'),
('string/en/spawning/static_npc/herald_yavin_temple_of_the_blueleaf_cluster.stf', 40, 'waypoint_name_1', 'Temple of the Blueleaf Cluster'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 1, 'cant_work', 'It appears you have other tasks to attend to. Come back later when you are not so busy.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 2, 'dontknowyou_1', 'Interested in joining the RSF are you?  Speak with Surlin Rolei in Theed to get started.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 3, 'dontknowyou_2', 'I''m on official RSF business, please move along.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 4, 'dontknowyou_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 5, 'dontknowyou_4', 'I am just a humble hermit, not worth your bother.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 6, 'dontknowyou_5', 'I do not know who it is you are looking for, but it sure is not me.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 7, 'dontknowyou_6', 'You are not the one one I am waiting for, I suggest you move along.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 8, 'dontknowyou_7', 'You had best be moving along, I have no business with you.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 9, 'gotowork_1', 'Hmm... I do not appear to have the correct forms.  You may wish to see the recruiting agent again.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 10, 'gotowork_2', 'Is this some sort of joke?  Go back to HQ and tell them to bring me the right equipment.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 11, 'gotowork_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 12, 'gotowork_4', 'This was not wat I expected.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 13, 'gotowork_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 14, 'gotowork_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 15, 'gotowork_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 16, 'next', 'That is all I have for you.  Welcome to the exciting life of an RSF agent.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 17, 'notit_1', 'Well, this does not appear to be your information. Perhaps there is some mixup.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 18, 'notit_2', 'Is this some sort of joke? Go back to HQ and tell them to bring me the right equipment.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 19, 'notit_3', 'This is not the blaster I am looking for.  Move along.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 20, 'notit_4', 'This is not the information we were told to expect.  Did you speak with the right person?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 21, 'notit_5', 'This is not the sort of thing I was expecting.  Are you sure you know what you are doing?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 22, 'notit_6', 'Blast, this is not the information that we need.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 23, 'notit_7', 'I am not sure what this is, but I am sure I do not want it.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 24, 'notyet', 'We are not taking any more recruits at this time.  Please try again later.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 25, 'npc_1_1', 'Welcome recruit.  Today we will begin your basic training to be a RSF agent.  Your first task will be to pick up your enlistment information from Captain Tish.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 26, 'npc_1_2', 'Welcome back.   For your first mission we need you to deliver a camera to one of our field agents so that they will be able to monitor activity in their sector.  We have aranged to have them meet you for a new one.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 27, 'npc_1_3', 'It is time to take you training to the next level.  The goal of the RSF is peace, and that often involves confrontation.  I am going to want to see how you can handle your weapons against a pack of shaupaut that have been bothering travelers in the area.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 28, 'npc_1_4', 'We need you to meet with a contact of ours.  Their report hinted at information regarding a known criminal in the area, but we wish to avoid the chance our transmission might be intercepted. So we want you to go out and get the full report in person.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 29, 'npc_1_5', 'The information you retreived for us is hardly a suprise.  These pirates, barely able to call them selves part of the trade federation, have been an increasing bother as of late.  I want you to  go visit a location of suspected loyalists and remove the threat, use any force necessary.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 30, 'npc_1_6', 'Good work on that trade federation camp.  While you were out we got a bit more information on activity in the area, and believe there is a chance to nab one of their leaders.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 31, 'npc_1_7', 'This is the chance we have been waiting for.  A location to one of their leaders, Taron.  For this mission we will need you to go for one of his decoy locations, while the main force aprehends him at his actual hideout.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 32, 'npc_2_1', 'Excellent.  You should be able to find him down by the lake shore.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 33, 'npc_2_2', 'Great, they are working on an important task so it will be a great benefit for them to not come all the way back into town.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 34, 'npc_2_3', 'It is good that you are confidant, but try not to let them take you unaware.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 35, 'npc_2_4', 'Be careful in your travels.  They do not suspect anything yet, but if the wrong people learn of your mission it might compromise our plan.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 36, 'npc_2_5', 'I do not like violent solutions, but we will not allow piracy.  Good luck.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 37, 'npc_2_6', 'This one will not be easy.  We need you to retreive a information from one of their people that will tell us the location of a local leader.  Someone who has caused problems for us in the past.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 38, 'npc_2_7', 'No doubt about that.  And be careful, just because they are a decoy does not mean they won''t be using real blasters.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 39, 'npc_3_1', 'The life of an RSF agent is not for everyone.  Feel free to come back when you you are up to the task.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 40, 'npc_3_2', 'We''ll have another recruit run this camera out.  Try to be available later, our agents are always in need of replacements.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 41, 'npc_3_3', 'It is good that you know your limits.  Come back when you feel up to task.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 42, 'npc_3_4', 'We can send another if we act quickly.  These sort of things pop up from time to time, so expect a similar task during your training.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 43, 'npc_3_5', 'I understand, train some more and then return.  Threats such as these can not be taken lightly.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 44, 'npc_3_6', 'Now is the time to turn back.  The RSF is not for the faint of heart.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 45, 'npc_3_7', 'Well, we would really like to have your help on this one.  Glory is a poor goal for a public servant.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 46, 'npc_4_1', 'Captain Tish likes to meet each recruit personally.  And well, he appears to be doing a bit of fishing right now.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 47, 'npc_4_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 48, 'npc_4_3', 'In fact it is, we pulled this one for you so that we could monitor your progress.  Don''t worry, it will come with the usual payoff.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 49, 'npc_4_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 50, 'npc_4_5', 'The loyalists are fanatics. Such an occurance is unlikely. Maybe if we could strike one of their leaders, but they are well hidden.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 51, 'npc_4_6', 'He is a scout of theirs, and with strikes like that which you have just performed for us the local heads are forced to take their briefings in person.  If we can get the information from this scout, then we can strike at the source for once.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 52, 'npc_4_7', 'We have learned of his decoy patrols a number of times in the past.  If we ignore this one he might become suspicious.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 53, 'npc_5_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 54, 'npc_5_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 55, 'npc_5_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 56, 'npc_5_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 57, 'npc_5_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 58, 'npc_5_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 59, 'npc_5_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 60, 'npc_6_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 61, 'npc_6_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 62, 'npc_6_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 63, 'npc_6_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 64, 'npc_6_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 65, 'npc_6_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 66, 'npc_6_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 67, 'npc_backtowork_1', 'Head on over see the Captain, I''ll let him know you have resumed your mission.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 68, 'npc_backtowork_2', 'We need that camera delivered, time is a costly thing in the recon business.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 69, 'npc_backtowork_3', 'Back to work with you then.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 70, 'npc_backtowork_4', 'Time is short, we need that information to prepare our next move.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 71, 'npc_backtowork_5', 'Quit loitering around when there are threats to remove.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 72, 'npc_backtowork_6', 'Get back out there, and bring down that scout.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 73, 'npc_backtowork_7', 'Try to hurry, we do not want this opportunity to pass by.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 74, 'npc_breech_1', 'Oh good, I''ve been expecting you.  Let me get this signed and you can return for your regular duties.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 75, 'npc_breech_2', 'I''ve been waiting for you all day, do you have my camera?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 76, 'npc_breech_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 77, 'npc_breech_4', 'You must be my contact.  They will need this encryption code in order to read it. Try not to delay, our targets could move at any time.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 78, 'npc_breech_5', 'You have some nerve showing up around here.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 79, 'npc_breech_6', 'Hey, you are not my contact!'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 80, 'npc_breech_7', 'I do not think that I am ready to be stopped yet.  Get him boys.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 81, 'npc_dropoff_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 82, 'npc_dropoff_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 83, 'npc_dropoff_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 84, 'npc_dropoff_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 85, 'npc_dropoff_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 86, 'npc_dropoff_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 87, 'npc_dropoff_7', 'Thank you for ruining my life buddy, I will try to return the favor some day.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 88, 'npc_failure_1', 'I''m not sure how you failed this mission, but that appears to be the case.  Such a simple thing too.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 89, 'npc_failure_2', 'I''m affraid to say that you failed the mission.  Without the camera, the little information our agent was able to gather might not be enough to further our investigation.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 90, 'npc_failure_3', 'It appears the Shaupaut got the best of you.  Perhaps you will want to try again after your skills have improved.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 91, 'npc_failure_4', 'The report is no good to us anymore, I think our targets may have been tipped off.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 92, 'npc_failure_5', 'It appears the pirates have the upper hand today.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 93, 'npc_failure_6', 'It appears the scout has gotten away. We can try again in a short time, come back then.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 94, 'npc_failure_7', 'Looks like he is the one that got away.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 95, 'npc_more_1_1', 'That would be nice. Say, I don''t suppose you have seen a droid, about waist high with a fishing pole around have you? Nevermind, I''ll just radio in and get HQ to start a  search for him.  You had best hurry back now.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 96, 'npc_more_1_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 97, 'npc_more_1_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 98, 'npc_more_1_4', 'Yes, my suspicions were true.  Trade federation reminent activity has been in the increase as of late and the recent raids on settlers has been the result of that increase.  Pirates until the end it would seem.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 99, 'npc_more_1_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 100, 'npc_more_1_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 101, 'npc_more_1_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 102, 'npc_more_2_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 103, 'npc_more_2_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 104, 'npc_more_2_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 105, 'npc_more_2_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 106, 'npc_more_2_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 107, 'npc_more_2_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 108, 'npc_more_2_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 109, 'npc_more_3_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 110, 'npc_more_3_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 111, 'npc_more_3_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 112, 'npc_more_3_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 113, 'npc_more_3_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 114, 'npc_more_3_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 115, 'npc_more_3_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 116, 'npc_noloc_1', 'We are having troubles with your enlistment documents.  Try again later, perhaps we will have them sorted out by then.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 117, 'npc_noloc_2', 'All of our agents have reported in, and none require resupply at this time.  Try again in a bit.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 118, 'npc_noloc_3', 'We haven''t received the information that we requested for your next task.  Try again in a little while.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 119, 'npc_noloc_4', 'We don''t have anything at this time, try back in a little while.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 120, 'npc_noloc_5', 'We have lost track of all our targets, come back later and maybe we will have updated information then.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 121, 'npc_noloc_6', 'We are unable to locate their scouts at this time. Do not worry, one will turn up soon.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 122, 'npc_noloc_7', 'We appear to be having technical difficulties.  '),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 123, 'npc_reset', 'Ok, I have notified our agent not to expect you. Return when you are prepared.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 124, 'npc_reward_1', 'You see, that was not so difficult.  With these in hand we can get you going on your training.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 125, 'npc_reward_2', 'I hear that the camera delivered was just in time.  They are back out gathering some good information for us.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 126, 'npc_reward_3', 'That was some good work you performed out there.  Here is your money as promised.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 127, 'npc_reward_4', 'This is just the information we need, come back soon and we will have the next task waiting for you.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 128, 'npc_reward_5', 'That is a good thing you did, the peace has prospered.  Take a rest, and then return later for more.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 129, 'npc_reward_6', 'This information could be the key to a long lasting peace, good work.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 130, 'npc_reward_7', 'He turned the tables on us that time.  Good job in bringing him in on your own, you have the makings of a fine officer.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 131, 'npc_smuggle_1', 'This is exactly what we need.  Welcome aboard.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 132, 'npc_smuggle_2', 'This is what I needed.  Now I can get back to monitoring my targets.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 133, 'npc_smuggle_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 134, 'npc_smuggle_4', 'And do try to be careful, we don''t want to tip off the marks.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 135, 'npc_smuggle_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 136, 'npc_smuggle_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 137, 'npc_smuggle_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 138, 'npc_takeme_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 139, 'npc_takeme_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 140, 'npc_takeme_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 141, 'npc_takeme_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 142, 'npc_takeme_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 143, 'npc_takeme_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 144, 'npc_takeme_7', 'Ok, I surrender.  Take me in, just do not hurt me.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 145, 'npc_work_1', 'I do not see your forms, did you make it to see Captain Tish?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 146, 'npc_work_2', 'Our field agent is still waiting on that camera.  Perhaps you could speed it up a bit?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 147, 'npc_work_3', 'Having trouble locating your target?  Might be bad data.  Destroy your current mission file, then talk to me again for  a new one.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 148, 'npc_work_4', 'You appear to have returned empty handed.  Hurry, this information is critical.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 149, 'npc_work_5', 'My reports indicate that the pirates are still active.  Please try to hurry.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 150, 'npc_work_6', 'You have not completed the task, don''t let this scout get away.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 151, 'npc_work_7', 'We need you to hit that decoy camp, no time to delay.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 152, 'otherescort_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 153, 'otherescort_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 154, 'otherescort_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 155, 'otherescort_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 156, 'otherescort_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 157, 'otherescort_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 158, 'otherescort_7', 'I am not the one you should be taking in, I swear.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 159, 'player_1_1', 'I''ll get right on that sir.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 160, 'player_1_2', 'That shouldn''t be too much trouble.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 161, 'player_1_3', 'I can perform this duty, those shaupaut don''t stand a chance.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 162, 'player_1_4', 'I will get right on that sir.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 163, 'player_1_5', 'I will get that problem taken care of.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 164, 'player_1_6', 'I am willing to help in any way.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 165, 'player_1_7', 'I will take care of all my area, you just get Taron brought in.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 166, 'player_2_1', 'I don''t think I am ready to begin my training.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 167, 'player_2_2', 'I can''t make it at this time, you are best to send another.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 168, 'player_2_3', 'I don''t think I am ready for a pack of shaupaut at this time. '),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 169, 'player_2_4', 'Maybe you should send someone else.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 170, 'player_2_5', 'I do not feel that I am ready for a task such as this.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 171, 'player_2_6', 'I am not ready for an assignment like this.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 172, 'player_2_7', 'I am not sure I like the idea of going for a bunch of decoys.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 173, 'player_3_1', 'Why don''t you have them transmitted.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 174, 'player_3_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 175, 'player_3_3', 'This sounds like a job for public works?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 176, 'player_3_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 177, 'player_3_5', 'Maybe we can convince them to come in quietly.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 178, 'player_3_6', 'How can this person lead us to one of their leaders?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 179, 'player_3_7', 'If we know that it is a decoy, why are we going after it?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 180, 'player_4_1', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 181, 'player_4_2', ''),
