('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 194, 'player_more_1_1', 'Aren''t you supposed to be fishing?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 195, 'player_more_1_2', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 196, 'player_more_1_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 197, 'player_more_1_4', 'Is everything included in the report?'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 198, 'player_more_1_5', ''),
