('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 210, 'player_more_3_3', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 211, 'player_more_3_4', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 212, 'player_more_3_5', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 213, 'player_more_3_6', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 214, 'player_more_3_7', ''),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 215, 'player_reset', 'Something appears to have gone wrong. Give me another chance.'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 216, 'player_sorry', 'I am ready to continue with my task.'),
