('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 233, 'waypoint_description_3', 'Shaupaut Pack'),
('string/en/spawning/static_npc/naboo_rsf_surlin_rolei.stf', 234, 'waypoint_description_4', 'Field Agent'),
