('string/en/spice/spice.stf', 1, 'bio_kliknik_fortitude_boost_consume', 'Your innards harden.'),
('string/en/spice/spice.stf', 2, 'bio_kliknik_fortitude_boost_done', 'The weakness passes as your body completes its cleansing.'),
('string/en/spice/spice.stf', 3, 'bio_kliknik_fortitude_boost_downer', 'You weaken as your inner armor begins to dissolve.'),
('string/en/spice/spice.stf', 4, 'bio_kwi_adrenal_boost_consume', 'Your body tingles as the adrenalin courses through your veins.'),
('string/en/spice/spice.stf', 5, 'bio_kwi_adrenal_boost_done', 'You regain your composure.'),
('string/en/spice/spice.stf', 6, 'bio_kwi_adrenal_boost_downer', 'You feel cold and begin to shake as the adrenalin dissipates.'),
('string/en/spice/spice.stf', 7, 'booster_blue_consume', 'You consume the Booster Blue and feel a boost to your physical speed.'),
('string/en/spice/spice.stf', 8, 'booster_blue_done', 'Your reaction time returns to normal as your body adjusts to the lack of Booster Blue.'),
('string/en/spice/spice.stf', 9, 'booster_blue_downer', 'Your reaction time slows considerably as the Booster Blue''s effects fade.'),
('string/en/spice/spice.stf', 10, 'crash_n_burn_consume', 'You become intensely aware of your surroundings and filled with a sense of apathy.'),
('string/en/spice/spice.stf', 11, 'crash_n_burn_done', 'The feeling of apathy from the Crash n'' Burn leaves you.'),
('string/en/spice/spice.stf', 12, 'crash_n_burn_downer', 'The awareness enhancing effects of the Crash n'' Burn fade, but the feeling of apathy intensifies.'),
('string/en/spice/spice.stf', 13, 'droid_lube_consume', 'The zypolene burns as you apply it, causing you to feel more resiliant.'),
('string/en/spice/spice.stf', 14, 'droid_lube_done', 'The zypolene induced vulnerability has ended.'),
('string/en/spice/spice.stf', 15, 'droid_lube_downer', 'The zypolene''s effects fade, leaving you feeling vulnerable.'),
('string/en/spice/spice.stf', 16, 'giggledust_consume', 'You feel light headed and filled with euphoria.'),
('string/en/spice/spice.stf', 17, 'giggledust_done', 'The depression of the absense of Giggledust has faded.'),
('string/en/spice/spice.stf', 18, 'giggledust_downer', 'The sense of euphoria from the Giggledust fades, leaving you feeling depressed.'),
('string/en/spice/spice.stf', 19, 'grey_gabaki_consume', 'The Grey Gabaki fills you with a sharp sense of focus.'),
('string/en/spice/spice.stf', 20, 'grey_gabaki_done', 'The drowsy feeling of the Grey Gabaki has passed.'),
('string/en/spice/spice.stf', 21, 'grey_gabaki_downer', 'The focusing effects of the Grey Gabaki have left you feeling drowsy.'),
('string/en/spice/spice.stf', 22, 'gunjack_consume', 'The Gunjack burns in your throat.  You feel an intense rush of physical strength.'),
('string/en/spice/spice.stf', 23, 'gunjack_done', 'The sluggishness induced by the Gunjack seems to be gone.'),
('string/en/spice/spice.stf', 24, 'gunjack_downer', 'The Gunjack''s effects dissipate leaving you feeling weak and sluggish.'),
('string/en/spice/spice.stf', 25, 'kliknik_boost_consume', 'Your innards harden.'),
('string/en/spice/spice.stf', 26, 'kliknik_boost_done', 'The weakness passes as your body completes its cleansing.'),
('string/en/spice/spice.stf', 27, 'kliknik_boost_downer', 'You weaken as your inner armor begins to dissolve.'),
('string/en/spice/spice.stf', 28, 'kwi_boost_consume', 'Your body tingles as the adrenalin courses through your veins.'),
('string/en/spice/spice.stf', 29, 'kwi_boost_done', 'You regain your composure.'),
('string/en/spice/spice.stf', 30, 'kwi_boost_downer', 'You feel cold and begin to shake as the adrenalin dissipates.'),
('string/en/spice/spice.stf', 31, 'muon_gold_consume', 'The Muon Gold irradiates your body increasing your mental clarity and focus.'),
('string/en/spice/spice.stf', 32, 'muon_gold_done', 'The negative effects of the Muon Gold seem to have passed.'),
('string/en/spice/spice.stf', 33, 'muon_gold_downer', 'The Muon Gold fades, leaves your mind feeling weak and slow.'),
('string/en/spice/spice.stf', 34, 'neutron_pixey_consume', 'As you consume the Neutron Pixie you begin to feel light headed.'),
('string/en/spice/spice.stf', 35, 'neutron_pixey_done', 'The negative effects of the Neutron Pixie seem to have left your body.'),
('string/en/spice/spice.stf', 36, 'neutron_pixey_downer', 'The mind enhancing effects of the Neutron Pixie leave.  You have to fight to retain consciousness.'),
('string/en/spice/spice.stf', 37, 'pyrepenol_consume', 'As you swallow the pyrepenol, you suddenly feel your muscles surge with strength.'),
('string/en/spice/spice.stf', 38, 'pyrepenol_done', 'The aches in your muscles have ended.'),
('string/en/spice/spice.stf', 39, 'pyrepenol_downer', 'Your stength enhancement fades, leaving your muscles sore and weak.'),
('string/en/spice/spice.stf', 40, 'scramjet_consume', 'Your muscles burst with new strength as you consume the Scramjet.'),
('string/en/spice/spice.stf', 41, 'scramjet_done', 'You no longer feel weak.'),
('string/en/spice/spice.stf', 42, 'scramjet_downer', 'The strength enhancing effects of the Scramjet pass, leaving you feeling weakened.'),
('string/en/spice/spice.stf', 43, 'sedative_h4b_consume', 'As you inject the sedative, your sense of feeling deadens.'),
('string/en/spice/spice.stf', 44, 'sedative_h4b_done', 'The sedative''s aftereffects have faded.'),
('string/en/spice/spice.stf', 45, 'sedative_h4b_downer', 'The effects of the sedative fade leaving you intensely sensitive to wounds.'),
('string/en/spice/spice.stf', 46, 'shadowpaw_consume', 'You feel an increase in your reaction speed.'),
('string/en/spice/spice.stf', 47, 'shadowpaw_done', 'The decrease in your reaction speed seems to have passed.'),
('string/en/spice/spice.stf', 48, 'shadowpaw_downer', 'Your reaction speed has slowed considerably.'),
('string/en/spice/spice.stf', 49, 'sweetblossom_consume', 'Aches and pains leave your body as the Sweetblossom takes effect.'),
('string/en/spice/spice.stf', 50, 'sweetblossom_done', 'The effects of the Sweetblossom have left your system.'),
('string/en/spice/spice.stf', 51, 'sweetblossom_downer', 'As the anaesthetic Sweetblossom fades, your wounds suddenly feel sharply more painful.'),
('string/en/spice/spice.stf', 52, 'sys_already_spiced', 'You are already under the influence of spice.'),
('string/en/spice/spice.stf', 53, 'thruster_head_consume', 'You feel a rush of mental awareness and a massive increase in your mental capabilities.'),
('string/en/spice/spice.stf', 54, 'thruster_head_done', 'The intense nausea seems to have left.'),
('string/en/spice/spice.stf', 55, 'thruster_head_downer', 'The mind enhancement of the Thruster Head leaves you wracked with nausea.'),
('string/en/spice/spice.stf', 56, 'yarrock_consume', 'Lights flash before your eyes as the Yarrock expands your mind.'),
('string/en/spice/spice.stf', 57, 'yarrock_done', 'The headache from the Yarrock seems to have gone.'),
('string/en/spice/spice.stf', 58, 'yarrock_downer', 'The mind enhance effects of the Yarrock dissipate leaving you with a splitting headache.'),
('string/en/squad_leader.stf', 1, 'squad_leader_command', 'Squad Leader %TT: %TO.'),
('string/en/state_d.stf', 1, 'aiming', 'Aiming increases the chances of successfully hitting a target.'),
('string/en/state_d.stf', 2, 'alert', 'A meditative state used to focus powerful inner energies.'),
('string/en/state_d.stf', 3, 'berserk', 'When someone is berserk, they hit harder but get hit more often.'),
('string/en/state_d.stf', 4, 'bleeding', 'Bleeding can adversely affect various stat pools.  It can be stopped if a medic successfully applies First Aid.'),
('string/en/state_d.stf', 5, 'blinded', 'While blinded, combat accuracy falls dramatically.'),
('string/en/state_d.stf', 6, 'blocking', 'Blocking - Cut - Please bug report this string if seen in game.'),
('string/en/state_d.stf', 7, 'combat', 'This displays if a player, NPC, or creature is in combat.'),
('string/en/state_d.stf', 8, 'cover', 'Cover gives a defensive bonus and allows the use of Surprise Shot.  It makes its benefactor immobile unless they have Sneak.'),
('string/en/state_d.stf', 9, 'diseased', 'Disease can cause wounds to various attributes, and generally causes these wounds slowly.  It can be cured if a doctor successfully uses Cure Disease medicines.'),
('string/en/state_d.stf', 10, 'dizzy', 'Being dizzy makes it possible to fall down when changing postures.'),
('string/en/state_d.stf', 11, 'driving', 'Driving a vehicle limits what additional actions you can attempt.'),
('string/en/state_d.stf', 12, 'feigndeath', 'A feigned death can trick enemies into believing that their target is really dead.'),
('string/en/state_d.stf', 13, 'frozen', 'When one is frozen, they are unable to run or walk.'),
('string/en/state_d.stf', 14, 'immobilized', 'When one is immobilized, they are unable to run or walk.'),
('string/en/state_d.stf', 15, 'intimidated', 'Those who are intimidated do not hit as often.'),
('string/en/state_d.stf', 16, 'maskscent', 'A masked scent may prevent aggressive creatures from attacking players who approach them.'),
('string/en/state_d.stf', 17, 'meditate', 'Meditate'),
('string/en/state_d.stf', 18, 'mountedcreature', 'Currently carrying a rider.'),
('string/en/state_d.stf', 19, 'onfire', 'Fire!!  This quickly damages stat pools while also creating wound damage.'),
('string/en/state_d.stf', 20, 'peace', 'Peace shows that somebody has ceased hostilities towards their combat target.'),
('string/en/state_d.stf', 21, 'pilotingship', 'Piloting a ship allows space travel and combat.'),
('string/en/state_d.stf', 22, 'poisoned', 'Poison can adversely affect various stat pools, and causes its damage rather quickly.  It can be cured if a doctor successfully uses Cure Poison medicine.'),
('string/en/state_d.stf', 23, 'rallied', 'Rallied is a group-wide bonus to hit percentage.'),
('string/en/state_d.stf', 24, 'ridingmount', 'Riding a mount limits what additional actions you can attempt.'),
('string/en/state_d.stf', 25, 'sittingonchair', 'Sitting on a chair.'),
('string/en/state_d.stf', 26, 'sneaking', 'Sneaking allows you to slowly move around while Taking Cover.'),
('string/en/state_d.stf', 27, 'stunned', 'The stunned state takes away a round of combat and temporarily lowers some stats.'),
('string/en/state_d.stf', 28, 'swimming', 'Swimming allows you to wade through deep water.'),
('string/en/state_d.stf', 29, 'tef', 'A Temporary Enemy Flag is acquired when you perform an action which temporarily makes you an enemy of some faction.'),
('string/en/state_d.stf', 30, 'tumbling', 'Tumbling gives a defensive bonus to whoever is in that state.'),
('string/en/state_d.stf', 31, 'shipinterior', 'Inside a starship interior.'),
('string/en/state_d.stf', 32, 'shipgunner', 'Manning a weapon on a starship.'),
('string/en/state_d.stf', 33, 'pilotingpobship', 'Piloting a ship allows space travel and combat.'),
('string/en/state_d.stf', 34, 'shipoperations', 'While using the Ship Operations station, a pilot can execute special abilities and droid programs.'),
