('string/en/static_npc/corellia/brantlee_spondoon.stf', 137, 'npc_reset_1', 'If you can''t accomplish that one little task, I''ll be hard pressed to convince the Diktat it''s worthwhile to see you.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 138, 'npc_reset_2', 'If you can''t accomplish that one little task, I''ll be hard pressed to convince the Diktat it''s worthwhile to see you.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 139, 'npc_reset_3', 'If you can''t accomplish that one little task, I''ll be hard pressed to convince the Diktat it''s worthwhile to see you.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 140, 'waypoint_description_1', 'Retrieve a gift for Brantlee from a Devaronian merchant name Midgoss D''labaninaph.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 141, 'waypoint_description_2', 'Retrieve another gift for Brantlee - this time some imported Neonian Red Cheese from Zoda Burb.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 142, 'waypoint_description_3', 'Rescue Brantlee''s pet razor cat, Missy.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 143, 'return_waypoint_description_1', 'Return to Brantlee Spondoon with the gift.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 144, 'return_waypoint_description_2', 'Return to Brantlee Spondoon with the Neonian Red Cheese.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 145, 'return_waypoint_description_3', 'Return to Brantlee Spondoon with Missy.'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 146, 'return_waypoint_name_1', 'Brantlee Spondoon'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 147, 'return_waypoint_name_2', 'Brantlee Spondoon'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 148, 'return_waypoint_name_3', 'Brantlee Spondoon'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 149, 'waypoint_name_1', 'Midgoss D''labaninaph'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 150, 'waypoint_name_2', 'Zoda Burb'),
('string/en/static_npc/corellia/brantlee_spondoon.stf', 151, 'waypoint_name_3', 'Missy'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 1, 'next', 'You have been most helpful, thank you, but I require nothing further of you at the moment.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 2, 'cantwork', 'You seem a bit preoccupied and I do not wish to distract you from your current mission. Return when you have finished your task.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 3, 'npc_reset', 'I thank you for your interest. Please feel free to return if you change your mind and would like to help me again.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 4, 'notyet', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 5, 'npc_1_1', 'Greetings, friend. I am known as Chertyl Ruluwoor and I''m currently investigating a series of terrorist attacks aimed at Selonian dens. So far I''ve been unable to identify those responsible, but I''ve just received a tip that could lead to a break in my case. I''m wondering if I could call upon you to assist me? I need you to pick up a recording taken by an amateur holocam operator and bring it to me. Can I rely upon you?   '),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 6, 'npc_2_1', 'I appreciate your help. My contact''s name is Kafleer Tredahl and he''s waiting at the following coordinates. I''ll tell him to expect you. Please be careful bringing this recording back. Kafleer thinks someone is watching him. '),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 7, 'npc_3_1', 'I understand if you do not wish to become involved. Thank you for your time.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 8, 'npc_4_1', 'It was taken recently during an Imperial anti-alien demonstration and I believe it could reveal the identities of these terrorists. I''d go myself but my contact does not wish to be seen speaking with me. He thinks it may result in strikes against his family.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 9, 'npc_backtowork_1', 'Was I unclear about something?'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 10, 'npc_reward_1', 'Thank you, friend. This holo recording will hopefully further my investigation and allow me to close this case. Please accept this in exchange for your services.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 11, 'npc_work_1', 'Have you had an opportunity to pick up that holo recording? I don''t know how long my contact will wait for you.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 12, 'npc_noloc_1', 'As soon as my contact transmits his coordinates, I''ll share them with you.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 13, 'npc_failure_1', 'I regret that you were unable to bring this recording back. I shall endeavor to find another way to acquire this evidence.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 14, 'otherescort_1', 'I don''t think I''m the person you''re looking for.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 15, 'dontknowyou_1', 'Can''t talk, sorry. I''m on a secret mission.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 16, 'npc_breech_1', 'Over here! Did Chertyl send you?'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 18, 'npc_dropoff_1', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 19, 'npc_smuggle_1', 'Tell Chertyl I''ve marked the sections she needs to pay attention to with blinking arrows. I hope she finds the creeps that are attacking her people.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 20, 'gotowork_1', 'I hope she finds the information useful.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 21, 'notit_1', 'This is not the holo recording I was expecting. Can you bring me the recording?'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 26, 'player_3_1', 'What does the holo recording show?'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 27, 'npc_1_2', 'I have terrible news! Young Kafleer just contacted me - his mother, Zayna, has been kidnapped by the same terrorists I''m investigating. I dare not go after her myself for fear of straining the already tense relations between native Corellians and my people. Could you please see to it that Zayna is freed and brought back to me safely? Do what you will with the kidnappers. They deserve what they get. Will you help?'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 28, 'npc_2_2', 'You are noble and just. Kafleer''s holocams managed to catch the attackers in the act and allowed him to follow them. He''s sent us they''re coordinates. Please hurry.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 29, 'npc_3_2', 'I must find someone to help rescue Kafleer''s mother. There''s no telling what those brutes intend to do.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 30, 'npc_4_2', 'Kafleer saw two of them snatch his poor mother from her home. There might be more waiting for them outside of the city, however. You must be careful!'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 31, 'npc_backtowork_2', 'Please hurry! Zayna''s life may be in great danger.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 32, 'npc_reward_2', 'You are a true champion! You have my thanks and the thanks of my people. Blessings upon your den.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 33, 'npc_work_2', 'Have you rescued Zayna from the clutches of those vile terrorists?'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 34, 'npc_noloc_2', 'Fortunately for us, the terrorists were followed and I should be receiving their coordinates soon.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 35, 'npc_failure_2', 'Oh no! This is terrible! What will become of Zayna now? I must find a way to help her!'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 36, 'otherescort_2', 'I''m afraid I can''t talk at the moment.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 37, 'dontknowyou_2', 'I''m afraid I can''t talk at the moment.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 38, 'npc_breech_2', 'Help! These brutes have kidnapped me! '),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 39, 'npc_takeme_2', 'Thank you so much for your help. Did Chertyl send you? Bless her! Please take me to her.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 40, 'npc_dropoff_2', 'I don''t know what I would have done without your help. I''ll never forget you.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 41, 'npc_smuggle_2', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 42, 'gotowork_2', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 43, 'notit_2', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 48, 'player_3_2', 'How many terrorists are we talking about here?'),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 49, 'npc_1_3', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 50, 'npc_2_3', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 51, 'npc_3_3', ''),
('string/en/static_npc/corellia/chertyl_ruluwoor.stf', 52, 'npc_4_3', ''),
