('string/en/static_npc/corellia/corran_horn.stf', 68, 'player_1_3', 'Yes.'),
('string/en/static_npc/corellia/corran_horn.stf', 69, 'player_2_3', 'No.'),
('string/en/static_npc/corellia/corran_horn.stf', 70, 'player_3_3', 'Who is this guy?'),
