('string/en/static_npc/corellia/crev_bombaasa.stf', 137, 'npc_reset_1', 'I regret your lack of will. I sincerely hope you''ll resume work on my behalf at your early convenience.'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 138, 'npc_reset_2', 'I regret your lack of will. I sincerely hope you''ll resume work on my behalf at your early convenience.'),
