('string/en/static_npc/corellia/crev_bombaasa.stf', 140, 'waypoint_description_1', 'Retrieve the report detailing the activites of Didina Lippinoss from a Bothan informant.'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 141, 'waypoint_description_2', 'Deliver the report to Didina Lippinoss'' servant, Meeko.'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 142, 'waypoint_description_3', 'Eliminate the bounty hunter hired by Didina Lippinoss to kill Crev.'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 143, 'return_waypoint_description_1', 'Return to Crev Bombaasa with the report.'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 144, 'return_waypoint_description_2', 'Return to Crev Bombaasa and let him know the delivery has been completed.'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 145, 'return_waypoint_description_3', 'Return to Crev Bombaasa and let him know the bounty hunter is no longer a threat.'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 146, 'return_waypoint_name_1', 'Crev Bombaasa'),
('string/en/static_npc/corellia/crev_bombaasa.stf', 147, 'return_waypoint_name_2', 'Crev Bombaasa'),
