('string/en/static_npc/corellia/dalla_solo.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/dalla_solo.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
