('string/en/static_npc/corellia/grobber.stf', 132, 'player_reset_6', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/grobber.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/grobber.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/corellia/grobber.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/corellia/grobber.stf', 136, 'player_3_6', ''),
('string/en/static_npc/corellia/grobber.stf', 137, 'npc_reset_1', 'If you think you''re up to it later, check back and try again.'),
('string/en/static_npc/corellia/grobber.stf', 138, 'npc_reset_2', 'If you think you''re up to it later, check back and try again.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 1, 'next', 'I have the militia band situation under control now, thanks to you.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 2, 'cantwork', 'When you''re not so busy, would you mind checking back with me?'),
('string/en/static_npc/corellia/grondorn_muse.stf', 3, 'npc_reset', 'I''m sorry to hear that. This situation is turning into a fiasco.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 4, 'notyet', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 5, 'npc_1_1', 'Hello. I was out with our militia''s band, the Fighting 357th Serenaders, on a training exercise. When we returned to base, I forgot my kloo horn. One of our band members went to retrieve it, but he just called to say he got lost. If you''ll escort him here safely, along with my kloo horn, I''ll make it worth your while.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 6, 'npc_2_1', 'Thanks. The band member''s name is Vincol Dunker. He found my kloo horn, so don''t let anything happen to him. That might hurt the horn. Sorry, just joking.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 7, 'npc_3_1', 'Sorry to hear that. This whole situation is rapidly becoming a fiasco.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/corellia/grondorn_muse.stf', 8, 'npc_4_1', 'Look, you try herding a pack of wayward Serenaders out in the middle of nowhere, and you''ll lose track of details too. I hope if you can get the band member and my horn back safely, I won''t get into trouble with my commander. Will you bring him here?'),
('string/en/static_npc/corellia/grondorn_muse.stf', 9, 'npc_backtowork_1', 'I hope you''re ready to move out and retrieve Vincol and my kloo horn.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 10, 'npc_reward_1', 'Thanks. Please accept this for your good work. Wait -- Vincol''s brought that new arrangement, too. I forgot all about that! Check with me again if you want another job.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 11, 'npc_work_1', 'I need you to bring back our band member, Vincol Dunker, and my kloo horn. Are you having trouble finding him?'),
('string/en/static_npc/corellia/grondorn_muse.stf', 12, 'npc_noloc_1', 'I got some confused coordinates from the band member, Vincol Dunker, so I''m waiting for another call from him. Check with me in a few moments.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 13, 'npc_failure_1', 'You didn''t bring Vincol back? I hope he''s all right. Not to mention my kloo horn, which he''d better be treating carefully.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 14, 'otherescort_1', 'I''m waiting for another party.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 15, 'dontknowyou_1', 'I haven''t got anything to say to you.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 16, 'npc_breech_1', 'Are you here to bring me to Grondorn? I have his kloo horn!'),
('string/en/static_npc/corellia/grondorn_muse.stf', 17, 'npc_takeme_1', 'I swear, that Grondorn Muse could forget his own trousers sometimes. He''ll get in big trouble for that someday. Can you guide me back? I have a poor sense of direction.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 18, 'npc_dropoff_1', 'Thanks. Grondorn, here''s your horn, along with a datadisc I found beside it. I guess you forgot everything but your trousers, huh?'),
('string/en/static_npc/corellia/grondorn_muse.stf', 19, 'npc_smuggle_1', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 20, 'gotowork_1', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 21, 'notit_1', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 26, 'player_3_1', 'Why did you forget and leave your kloo horn behind?'),
('string/en/static_npc/corellia/grondorn_muse.stf', 27, 'npc_1_2', 'I need your help again. I promised to deliver this arrangement of "Corellia Ho!" to the band leader of the Battling 166th Troubadours. Unfortunately, I have to wait here for new militia orders. Can you deliver it for me? I''ll pay you.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 28, 'npc_2_2', 'Great. You want to find the Battling 166th band leader, Pytor Tuko. He''s out in the wilderness on a training exercise.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 29, 'npc_3_2', 'Well, thanks for your earlier help, anyway.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 30, 'npc_4_2', 'You must know that tune -- brace up, Corellia, stand firm and tall? None shall subdue you, you''ll never fall? Go your own way and let none hold you back, for your future calls you ever ever on-n-n-n-n? No? Well, it''s a rouser. I hope you''ll deliver my arrangement.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 31, 'npc_backtowork_2', 'I hope you''ll get started soon and deliver that arrangement.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 32, 'npc_reward_2', 'Thanks. Now the Battling 166th Troubadours can hold rehearsals out there in the wilderness -- which, if you''ve ever heard them play, you know is probably for the best.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 33, 'npc_work_2', 'Have you delivered that arrangement of "Corellia Ho"? The Battling 166th is waiting.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 34, 'npc_noloc_2', 'Sorry, I''m getting a call about the new orders. Let me just take this, and then check back with me in a moment.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 35, 'npc_failure_2', 'You didn''t deliver that arrangement? Oh well, I''ll try to send another copy to Pytor.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 36, 'otherescort_2', 'I''m expecting someone else, actually.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 37, 'dontknowyou_2', 'I''d prefer not to get into a conversation right now.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 38, 'npc_breech_2', 'Are you bringing Muse''s arrangement of "Corellia Ho"?'),
('string/en/static_npc/corellia/grondorn_muse.stf', 39, 'npc_takeme_2', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 40, 'npc_dropoff_2', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 41, 'npc_smuggle_2', 'I wondered if I''d get this. That Grondorn -- talented, I grant you, but he couldn''t remember to put his shirt on unless he got a written order.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 42, 'gotowork_2', 'I was expecting Grondorn Muse''s arrangement of "Corellia Ho." Don''t you have it?'),
('string/en/static_npc/corellia/grondorn_muse.stf', 43, 'notit_2', 'I was expecting Grondorn Muse''s arrangement of "Corellia Ho." That isn''t it.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/corellia/grondorn_muse.stf', 48, 'player_3_2', 'What is "Corellia Ho!"'),
('string/en/static_npc/corellia/grondorn_muse.stf', 49, 'npc_1_3', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 50, 'npc_2_3', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 51, 'npc_3_3', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 52, 'npc_4_3', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 53, 'npc_backtowork_3', ''),
('string/en/static_npc/corellia/grondorn_muse.stf', 54, 'npc_reward_3', ''),
