('string/en/static_npc/corellia/ignar_ominaz.stf', 130, 'gotowork_6', ''),
('string/en/static_npc/corellia/ignar_ominaz.stf', 131, 'notit_6', ''),
('string/en/static_npc/corellia/ignar_ominaz.stf', 132, 'player_reset_6', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/ignar_ominaz.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/ignar_ominaz.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/corellia/ignar_ominaz.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/corellia/ignar_ominaz.stf', 136, 'player_3_6', ''),
('string/en/static_npc/corellia/ignar_ominaz.stf', 137, 'npc_reset_1', 'If I had your lack of ambition, I''d never have become a famous swoop racer. Never give up, friend! Try me again later.'),
('string/en/static_npc/corellia/ignar_ominaz.stf', 138, 'npc_reset_2', 'If I had your lack of ambition, I''d never have become a famous swoop racer. Never give up, friend! Try me again later.'),
('string/en/static_npc/corellia/ignar_ominaz.stf', 139, 'npc_reset_3', 'If I had your lack of ambition, I''d never have become a famous swoop racer. Never give up, friend! Try me again later.'),
('string/en/static_npc/corellia/irenez.stf', 1, 'next', 'You''ve performed your duties admirably. I don''t have anything else for you right now, but feel free to speak with Garm Bel Iblis. I''ve cleared you. '),
('string/en/static_npc/corellia/irenez.stf', 2, 'cantwork', 'Finish your current job and then come se me about some work.'),
('string/en/static_npc/corellia/irenez.stf', 3, 'npc_reset', 'If you change your mind and want to try and help later, you know where to find me.'),
('string/en/static_npc/corellia/irenez.stf', 4, 'notyet', ''),
('string/en/static_npc/corellia/irenez.stf', 5, 'npc_1_1', 'I''m known as Irenez. I''m currently involved in fighting Black Sun. If you''re interested in helping Corellia fight back against the criminals that try to plunder her I could certainly use your help. Interested?'),
('string/en/static_npc/corellia/irenez.stf', 6, 'npc_2_1', 'Good. Bring me Tessa Wylden. She''s an accountant for Black Sun and can tell us a lot about how their money flows. She''ll have guards so do be careful.'),
('string/en/static_npc/corellia/irenez.stf', 7, 'npc_3_1', 'Just looking out for number one, eh? I see how it is.'),
('string/en/static_npc/corellia/irenez.stf', 8, 'npc_4_1', 'To start with, I need someone to capture one of the money people. There''s one we''ve been tailing for that very purpose. How about it?'),
('string/en/static_npc/corellia/irenez.stf', 9, 'npc_backtowork_1', 'Was there something else you had to say?'),
('string/en/static_npc/corellia/irenez.stf', 10, 'npc_reward_1', 'Good job. Come see me again if you want more work.'),
('string/en/static_npc/corellia/irenez.stf', 11, 'npc_work_1', 'Have you arrested that Black Sun number cruncher yet?'),
('string/en/static_npc/corellia/irenez.stf', 12, 'npc_noloc_1', 'I should receive word as to where you can find Tessa shortly. Why don''t you come back in a little while?'),
('string/en/static_npc/corellia/irenez.stf', 13, 'npc_failure_1', 'You couldn''t bring her in after all, eh? I guess we''ll have to make another attempt later.'),
('string/en/static_npc/corellia/irenez.stf', 14, 'otherescort_1', 'I''m not who you''re looking for.'),
('string/en/static_npc/corellia/irenez.stf', 15, 'dontknowyou_1', 'Why don''t you go on about your business?'),
('string/en/static_npc/corellia/irenez.stf', 16, 'npc_breech_1', 'I think we may have a problem...'),
('string/en/static_npc/corellia/irenez.stf', 17, 'npc_takeme_1', 'I''m not armed! Don''t hurt me!'),
('string/en/static_npc/corellia/irenez.stf', 18, 'npc_dropoff_1', 'You shouldn''t interfere in Black Sun business. It''s unhealthy.'),
('string/en/static_npc/corellia/irenez.stf', 19, 'npc_smuggle_1', ''),
('string/en/static_npc/corellia/irenez.stf', 20, 'gotowork_1', ''),
('string/en/static_npc/corellia/irenez.stf', 21, 'notit_1', ''),
('string/en/static_npc/corellia/irenez.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/irenez.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/irenez.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/corellia/irenez.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/corellia/irenez.stf', 26, 'player_3_1', 'What sort of help do you need?'),
('string/en/static_npc/corellia/irenez.stf', 27, 'npc_1_2', 'That woman you brought us was a goldmine of information. One very immediate lead we got was the recent hiring of an assassin. I''d like you to try and stop him. Will you do it?'),
('string/en/static_npc/corellia/irenez.stf', 28, 'npc_2_2', 'Good, because this can''t wait. He''s called Skazz and he''s deadly, so don''t take any chances with him. Find him and stop him cold.'),
('string/en/static_npc/corellia/irenez.stf', 29, 'npc_3_2', 'Then I''d better find someone else to handle this right away.'),
('string/en/static_npc/corellia/irenez.stf', 30, 'npc_4_2', 'The head of CorSec, which is why it''s extremely important he be stopped. Will you do it?'),
('string/en/static_npc/corellia/irenez.stf', 31, 'npc_backtowork_2', 'The sooner you leave the sooner you can stop him.'),
('string/en/static_npc/corellia/irenez.stf', 32, 'npc_reward_2', 'Good work. Corellia is in your debt.'),
('string/en/static_npc/corellia/irenez.stf', 33, 'npc_work_2', 'Have you stopped that assassin yet? Time''s running out.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/corellia/irenez.stf', 34, 'npc_noloc_2', 'I need a few moments to make some last minute preparations with CorSec. Can you come back in a few minutes?'),
('string/en/static_npc/corellia/irenez.stf', 35, 'npc_failure_2', 'That assassin has got to be stopped. I guess I''ll have to find another way.'),
('string/en/static_npc/corellia/irenez.stf', 36, 'otherescort_2', 'I don''t have any business with you.'),
('string/en/static_npc/corellia/irenez.stf', 37, 'dontknowyou_2', 'I don''t have any business with you.'),
('string/en/static_npc/corellia/irenez.stf', 38, 'npc_breech_2', 'You should not interfere with me. Here''s why.'),
('string/en/static_npc/corellia/irenez.stf', 39, 'npc_takeme_2', ''),
('string/en/static_npc/corellia/irenez.stf', 40, 'npc_dropoff_2', ''),
('string/en/static_npc/corellia/irenez.stf', 41, 'npc_smuggle_2', ''),
('string/en/static_npc/corellia/irenez.stf', 42, 'gotowork_2', ''),
('string/en/static_npc/corellia/irenez.stf', 43, 'notit_2', ''),
('string/en/static_npc/corellia/irenez.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/irenez.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/irenez.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/corellia/irenez.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/corellia/irenez.stf', 48, 'player_3_2', 'Who has he been hired to kill?'),
('string/en/static_npc/corellia/irenez.stf', 49, 'npc_1_3', 'You''re not going to believe where one of those money trails led us. Black Sun has been buying weapons from the blasted Imperials. This next one may be a little tricky. Are you still willing to help?'),
('string/en/static_npc/corellia/irenez.stf', 50, 'npc_2_3', 'You have courage. I need you to take out the Black Sun members who are waiting to purchase some weapons.  If the Imperials arrive and the Black Sun thugs aren''t there, the deal will fall through.'),
('string/en/static_npc/corellia/irenez.stf', 51, 'npc_3_3', 'Getting nervous about angering the Black Sun?'),
('string/en/static_npc/corellia/irenez.stf', 52, 'npc_4_3', 'Not at the moment, no. I just need you to take out the group of Black Sun thugs awaiting their next shipment of weapons. Will you do it?'),
('string/en/static_npc/corellia/irenez.stf', 53, 'npc_backtowork_3', 'If you''re going to do this, please leave straight away.'),
('string/en/static_npc/corellia/irenez.stf', 54, 'npc_reward_3', 'You''re very talented. You should consider speaking with the Commander. He might be able to find a use for you.'),
('string/en/static_npc/corellia/irenez.stf', 55, 'npc_work_3', 'Have you stopped the Black Sun from purchasing those weapons yet? '),
('string/en/static_npc/corellia/irenez.stf', 56, 'npc_noloc_3', 'I should soon receive the exact coordinates for where the Black Sun is meeting their imperial suppliers. Come back and see me in a little while.'),
('string/en/static_npc/corellia/irenez.stf', 57, 'npc_failure_3', 'You didn''t stop the weapons deal? Whatever nefarious use they put those weapons to is on your head... not mine.'),
('string/en/static_npc/corellia/irenez.stf', 58, 'otherescort_3', ''),
('string/en/static_npc/corellia/irenez.stf', 59, 'dontknowyou_3', ''),
('string/en/static_npc/corellia/irenez.stf', 60, 'npc_breech_3', ''),
('string/en/static_npc/corellia/irenez.stf', 61, 'npc_takeme_3', ''),
('string/en/static_npc/corellia/irenez.stf', 62, 'npc_dropoff_3', ''),
