('string/en/static_npc/corellia/irenez.stf', 65, 'notit_3', ''),
('string/en/static_npc/corellia/irenez.stf', 66, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/irenez.stf', 67, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/irenez.stf', 68, 'player_1_3', 'Yes.'),
('string/en/static_npc/corellia/irenez.stf', 69, 'player_2_3', 'No.'),
('string/en/static_npc/corellia/irenez.stf', 70, 'player_3_3', 'You don''t want me to attack a company of Imperial soldiers or something crazy do you?'),
