('string/en/static_npc/corellia/joz_jodhul.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/joz_jodhul.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/corellia/joz_jodhul.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/corellia/joz_jodhul.stf', 26, 'player_3_1', 'What are you talking about?'),
