('string/en/static_npc/corellia/karena_keer.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/corellia/karena_keer.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/corellia/karena_keer.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/corellia/karena_keer.stf', 95, 'player_reset', 'I can''t do this mission anymore.'),
('string/en/static_npc/corellia/karena_keer.stf', 96, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/karena_keer.stf', 97, 'return_waypoint_description_1', 'Return to Karena Keer with the bank authorizations.'),
('string/en/static_npc/corellia/karena_keer.stf', 98, 'return_waypoint_description_2', 'Karena is waiting for word that the gift has been delivered.'),
('string/en/static_npc/corellia/karena_keer.stf', 99, 'return_waypoint_description_3', 'Karena is waiting for word that Lacklo Blant is dead.'),
('string/en/static_npc/corellia/karena_keer.stf', 100, 'return_waypoint_name_1', 'Karena Keer'),
('string/en/static_npc/corellia/karena_keer.stf', 101, 'return_waypoint_name_2', 'Karena Keer'),
('string/en/static_npc/corellia/karena_keer.stf', 102, 'return_waypoint_name_3', 'Karena Keer'),
('string/en/static_npc/corellia/karena_keer.stf', 103, 'waypoint_description_1', 'This is where you''ll find Dray Ithicus. Get the bank authorizations from him and return to Karena.'),
('string/en/static_npc/corellia/karena_keer.stf', 104, 'waypoint_description_2', 'This is where you can find the garbage hauler, Breel''ik Nar. Bring the spice to him.'),
('string/en/static_npc/corellia/karena_keer.stf', 105, 'waypoint_description_3', 'This is where you''ll find Lacklo Blant, a Black Sun lieutenant. Kill him.'),
('string/en/static_npc/corellia/karena_keer.stf', 106, 'waypoint_name_1', 'Make the pick up.'),
('string/en/static_npc/corellia/karena_keer.stf', 107, 'waypoint_name_2', 'Gift for Jabba.'),
('string/en/static_npc/corellia/karena_keer.stf', 108, 'waypoint_name_3', 'Message for the Black Sun.'),
('string/en/static_npc/corellia/karena_keer.stf', 109, 'npc_reset_1', 'If you want to work for the Lady Hutt, come see me when you think you''re tough enough.'),
('string/en/static_npc/corellia/karena_keer.stf', 110, 'npc_reset_2', 'If you want to work for the Lady Hutt, come see me when you think you''re tough enough.'),
('string/en/static_npc/corellia/karena_keer.stf', 111, 'npc_reset_3', 'If you want to work for the Lady Hutt, come see me when you think you''re tough enough.'),
('string/en/static_npc/corellia/karena_keer.stf', 112, 'player_reset_1', 'I can''t do this mission anymore.'),
('string/en/static_npc/corellia/karena_keer.stf', 113, 'player_reset_2', 'I can''t do this mission anymore.'),
('string/en/static_npc/corellia/karena_keer.stf', 114, 'player_reset_3', 'I can''t do this mission anymore.'),
('string/en/static_npc/corellia/karena_keer.stf', 115, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/karena_keer.stf', 116, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/karena_keer.stf', 117, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/karrek_flim.stf', 1, 'next', 'I don''t have any work for you right now. Check back with me another time.'),
('string/en/static_npc/corellia/karrek_flim.stf', 2, 'cantwork', 'See me after you''ve finished your current job.'),
('string/en/static_npc/corellia/karrek_flim.stf', 3, 'npc_reset', 'You may want to try this job again after you''ve had a little more training.'),
('string/en/static_npc/corellia/karrek_flim.stf', 4, 'notyet', 'I''m a busy man. Speak with Vinya Maysor, my deputy.'),
('string/en/static_npc/corellia/karrek_flim.stf', 5, 'npc_1_1', 'Vinya tells me you''ve been a big help to her. I can always use a competent and discreet operative. Would you be interested in doing some work for me? I need you to pick up something from a courier.'),
('string/en/static_npc/corellia/karrek_flim.stf', 6, 'npc_2_1', 'It all seems very hush-hush, so be careful. The courier is named Mia. I''ll leave you to your work now. I should really get back to mine too.'),
('string/en/static_npc/corellia/karrek_flim.stf', 7, 'npc_3_1', 'Not very exciting, I''ll grant you. Well then, I should really get back to work. Good day.'),
('string/en/static_npc/corellia/karrek_flim.stf', 8, 'npc_4_1', 'I was asked to send someone I can trust to pick up a copy of some evidence in a fraud investigation. Would you mind collecting that for me?'),
('string/en/static_npc/corellia/karrek_flim.stf', 9, 'npc_backtowork_1', 'I''ve told you all I know. Was there anything else?'),
('string/en/static_npc/corellia/karrek_flim.stf', 10, 'npc_reward_1', 'I''ll review this, but I''m led to understand this investigation was cancelled due to lack of evidence.'),
('string/en/static_npc/corellia/karrek_flim.stf', 11, 'npc_work_1', 'Did you pick up that information from the courier yet? I''m very curious to see it.'),
('string/en/static_npc/corellia/karrek_flim.stf', 12, 'npc_noloc_1', 'The courier will contact me with a meeting point shortly. See me again in a few minutes.'),
('string/en/static_npc/corellia/karrek_flim.stf', 13, 'npc_failure_1', 'What a pity. I wonder what that information was about.'),
('string/en/static_npc/corellia/karrek_flim.stf', 14, 'otherescort_1', 'I''m waiting here to meet somebody else.'),
('string/en/static_npc/corellia/karrek_flim.stf', 15, 'dontknowyou_1', 'I''m waiting here to meet somebody else.'),
('string/en/static_npc/corellia/karrek_flim.stf', 16, 'npc_breech_1', 'Did the Viceprex send you?'),
('string/en/static_npc/corellia/karrek_flim.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 19, 'npc_smuggle_1', 'I was told to get this information to the Viceprex if anything happened to the officers involved. Now it''s up to you.'),
('string/en/static_npc/corellia/karrek_flim.stf', 20, 'gotowork_1', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 21, 'notit_1', 'This isn''t what I was expecting. I think you gave me the wrong item.'),
('string/en/static_npc/corellia/karrek_flim.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/karrek_flim.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/karrek_flim.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/corellia/karrek_flim.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/corellia/karrek_flim.stf', 26, 'player_3_1', 'What sort of pickup?'),
('string/en/static_npc/corellia/karrek_flim.stf', 27, 'npc_1_2', 'After reviewing that disk you brought me, I decided to have an outside source look into a certain shipping irregularity. Too many officials are implicated in this scandal to trust it to normal channels. Would you mind taking this to my independent investigator''s courier?'),
('string/en/static_npc/corellia/karrek_flim.stf', 28, 'npc_2_2', 'Good. You''ll be looking for Tabor Claxx. Don''t give the disk to anybody else, even if they claim to be some sort of official. I''ll smooth out any problems that arise from that.'),
('string/en/static_npc/corellia/karrek_flim.stf', 29, 'npc_3_2', 'So be it. On your way then.'),
('string/en/static_npc/corellia/karrek_flim.stf', 30, 'npc_4_2', 'It would be impolitic to say. Besides, this may be the work of a very creative data slicer. We''ll just keep this quiet until we have all the facts, is that understood? Good. So will you make the delivery?'),
('string/en/static_npc/corellia/karrek_flim.stf', 31, 'npc_backtowork_2', 'If you''re doing this, it''s time to get going.'),
('string/en/static_npc/corellia/karrek_flim.stf', 32, 'npc_reward_2', 'Yes, that courier does work for the Lady Hutt. You''re bemused by my unorthodox choice of investigators? Don''t be. Use a thief to catch a thief. Besides, the Lady has impressive resources at her disposal.'),
('string/en/static_npc/corellia/karrek_flim.stf', 33, 'npc_work_2', 'Have you delivered that disk yet?'),
('string/en/static_npc/corellia/karrek_flim.stf', 34, 'npc_noloc_2', 'Just a moment, I have to take this call. Check with me later.'),
('string/en/static_npc/corellia/karrek_flim.stf', 35, 'npc_failure_2', 'You weren''t able to make the delivery. I guess I''ll just have to try again.\n'),
('string/en/static_npc/corellia/karrek_flim.stf', 36, 'otherescort_2', 'My business is with someone else.'),
('string/en/static_npc/corellia/karrek_flim.stf', 37, 'dontknowyou_2', 'I can''t talk to you right now.'),
('string/en/static_npc/corellia/karrek_flim.stf', 38, 'npc_breech_2', 'You looking for me?'),
('string/en/static_npc/corellia/karrek_flim.stf', 39, 'npc_takeme_2', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 40, 'npc_dropoff_2', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 41, 'npc_smuggle_2', 'I''ll bring this to the Lady Hutt straight away.'),
('string/en/static_npc/corellia/karrek_flim.stf', 42, 'gotowork_2', 'You don''t have the disk? What am I supposed to tell the Lady Hutt?'),
('string/en/static_npc/corellia/karrek_flim.stf', 43, 'notit_2', 'Umm -- keep looking. You tried to give me the wrong thing.'),
('string/en/static_npc/corellia/karrek_flim.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/karrek_flim.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/karrek_flim.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/corellia/karrek_flim.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/corellia/karrek_flim.stf', 48, 'player_3_2', 'How high up does this scandal go?'),
('string/en/static_npc/corellia/karrek_flim.stf', 49, 'npc_1_3', 'What pleasant news. It seems that investigation into the Lady Hutt was a clever forgery by data slicers trying to discredit several high-ranking Corellian officials. Good thing we stopped that. The Lady Hutt is sending me a thank-you gift for giving her the opportunity to take part in that investigation. Will you pick it up?'),
('string/en/static_npc/corellia/karrek_flim.stf', 50, 'npc_2_3', 'Wonderful. You''ll be meeting with Tabor Claxx again. I believe you''re already acquainted. It may be delicate, so do be careful.'),
('string/en/static_npc/corellia/karrek_flim.stf', 51, 'npc_3_3', 'As you wish. I must be on about my business now.'),
('string/en/static_npc/corellia/karrek_flim.stf', 52, 'npc_4_3', 'I''m not really sure. But the Lady so craves legitimacy that I didn''t have the heart to tell her "no." Will you pick up her present for me?'),
('string/en/static_npc/corellia/karrek_flim.stf', 53, 'npc_backtowork_3', 'It''s just a simple task, but if you''re too busy, just say so.'),
('string/en/static_npc/corellia/karrek_flim.stf', 54, 'npc_reward_3', 'No wonder everyone calls her the Lady Hutt. What a gracious gesture.'),
('string/en/static_npc/corellia/karrek_flim.stf', 55, 'npc_work_3', 'Have you picked up my present yet? Do hurry, I''m curious to see it.'),
('string/en/static_npc/corellia/karrek_flim.stf', 56, 'npc_noloc_3', 'Just a moment, I have to take this call. Check with me later.'),
('string/en/static_npc/corellia/karrek_flim.stf', 57, 'npc_failure_3', 'What, no present? How disappointing.'),
('string/en/static_npc/corellia/karrek_flim.stf', 58, 'otherescort_3', 'I''m waiting here to meet someone else. '),
('string/en/static_npc/corellia/karrek_flim.stf', 59, 'dontknowyou_3', 'I''m waiting here to meet someone else. '),
('string/en/static_npc/corellia/karrek_flim.stf', 60, 'npc_breech_3', 'Good to see you again.'),
('string/en/static_npc/corellia/karrek_flim.stf', 61, 'npc_takeme_3', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 62, 'npc_dropoff_3', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 63, 'npc_smuggle_3', 'The Lady Hutt sends her warmest regards to the Viceprex, and she hopes he will accept this bauble as a token of her friendship. '),
('string/en/static_npc/corellia/karrek_flim.stf', 64, 'gotowork_3', ''),
('string/en/static_npc/corellia/karrek_flim.stf', 65, 'notit_3', 'If this is a gift from the Lady Hutt, I''m baffled. Are you sure you didn''t mean to give me something else?'),
('string/en/static_npc/corellia/karrek_flim.stf', 66, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/karrek_flim.stf', 67, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/karrek_flim.stf', 68, 'player_1_3', 'Yes.'),
('string/en/static_npc/corellia/karrek_flim.stf', 69, 'player_2_3', 'No.'),
('string/en/static_npc/corellia/karrek_flim.stf', 70, 'player_3_3', 'What is the Lady Hutt''s present?'),
('string/en/static_npc/corellia/karrek_flim.stf', 71, 'npc_1_4', ''),
