INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/corellia/lasha_bindari.stf', 128, 'npc_dropoff_6', ''),
('string/en/static_npc/corellia/lasha_bindari.stf', 129, 'npc_smuggle_6', ''),
('string/en/static_npc/corellia/lasha_bindari.stf', 130, 'gotowork_6', ''),
('string/en/static_npc/corellia/lasha_bindari.stf', 131, 'notit_6', ''),
('string/en/static_npc/corellia/lasha_bindari.stf', 132, 'player_reset_6', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 136, 'player_3_6', ''),
('string/en/static_npc/corellia/lasha_bindari.stf', 137, 'npc_reset_2', 'You''re giving up? If you think you can handle this later come back and see me.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 138, 'npc_reset_3', 'You''re giving up? If you think you can handle this later come back and see me.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 139, 'gotowork', 'Please just leave me alone. I just do this job part-time.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 140, 'waypoint_description_1', 'Intercept an investigative report being sent by courier to their mobile base.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 141, 'waypoint_description_2', 'Eliminate some CorSec officers who are not cooperating with Lasha.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 142, 'waypoint_description_3', 'Remove the CorSec officer who is leading the investigation into the Lady Hutt Shalera.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 143, 'return_waypoint_description_1', 'Return to Lasha Bindari with the investigative report.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 144, 'return_waypoint_description_2', 'Return to Lasha Bindari and let her know the uncooperative CorSec officers are gone.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 145, 'return_waypoint_description_3', 'Return to Lasha Bindari with word of the lead investigator''s untimely passing.'),
('string/en/static_npc/corellia/lasha_bindari.stf', 146, 'waypoint_name_1', 'Intercept the report'),
('string/en/static_npc/corellia/lasha_bindari.stf', 147, 'waypoint_name_2', 'Kill the CorSec officers'),
('string/en/static_npc/corellia/lasha_bindari.stf', 148, 'waypoint_name_3', 'Kill the lead investigator'),
('string/en/static_npc/corellia/lasha_bindari.stf', 149, 'return_waypoint_name_1', 'Lasha Bindari'),
('string/en/static_npc/corellia/lasha_bindari.stf', 150, 'return_waypoint_name_2', 'Lasha Bindari'),
('string/en/static_npc/corellia/lasha_bindari.stf', 151, 'return_waypoint_name_3', 'Lasha Bindari'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 1, 'next', 'I don''t have anything more for you now, friend, but keep checking back with me. You never know when business will be booming again.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 2, 'cantwork', 'My assignments take a good deal of concentration. Come back when you can focus a bit more.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 3, 'npc_reset', 'Follow-through is important in my line of work, buddy. Come back when you can give me that.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 4, 'notyet', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 5, 'npc_1_1', 'Hey there, friend. I''m a recruiter, of sorts, on the lookout for promising young talent. I represent an organization that values ingenuity, loyalty, and above all, discretion. If this sounds intriguing, I have a little "job" for you, something to let me get a better understanding of your skills. A former agent left our organization owing us some money. Not a huge sum but enough to warrant a visit from someone like you. I doubt this individual has the money on him but what he does have are some bank codes that would assist our collection efforts. Can you bring me these codes?'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 6, 'npc_2_1', 'Great. I like your enthusiasm. Oh, and by the way, I doubt this client will give these codes up willingly so you may have to persuade him. To death. Best of luck.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 7, 'npc_3_1', 'Well, our organization is not for everybody. Take it easy, friend.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 8, 'npc_4_1', 'The name of my organization is not something we should discuss until I''ve determined that you''re a suitable candidate. You want to try and prove that?'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 9, 'npc_backtowork_1', 'I''ve given you all the info you''re going to get. Still interested?'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 10, 'npc_reward_1', 'Not bad, not bad at all. Another performance like that and I may just recommend you to my employers.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 11, 'npc_work_1', 'Did you get those bank codes? Remember, I''m evaluating your performance.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 12, 'npc_noloc_1', 'I''ll get you our former agent''s coordinates in just a few moments.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 13, 'npc_failure_1', 'Maybe you don''t have what it takes to join our elite ranks. Don''t sweat it, though, not everyone in the galaxy can be equally as competent.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 14, 'otherescort_1', 'Back off! I''m busy!'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 15, 'dontknowyou_1', 'Back off! I''m busy!'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 16, 'npc_breech_1', 'I knew Black Sun would be sending someone after me. Die, scum!'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 19, 'npc_smuggle_1', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 20, 'gotowork_1', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 21, 'notit_1', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 26, 'player_3_1', 'What organization do you represent?'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 27, 'npc_1_2', 'You performed so well on that last job that I''ve decided to only give you one more test. Since you got us these bank codes, it only seems fair that you should be the one to deliver them to my superior. Seems simple enough, right? Can you do it? '),
('string/en/static_npc/corellia/luthin_dlunar.stf', 28, 'npc_2_2', 'All right. Take these codes to a man named Gnurr Fenkel. He knows to expect you, so if he doesn''t say, "You looking for Corellian Double-Brandy?" when he sees you, blast him and bring the codes back to me.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 29, 'npc_3_2', 'Eh, no big loss. There''s plenty more candidates out there.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 30, 'npc_4_2', 'There''s a possibility that a few tough guys might try and take these codes away from you. Competitors, you understand. Nothing someone like you couldn''t handle, though. '),
('string/en/static_npc/corellia/luthin_dlunar.stf', 31, 'npc_backtowork_2', 'I don''t have anything else to tell you. You going or not?'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 32, 'npc_reward_2', 'Now those are the kind of results our organization prizes, friend. I''ll mention you to my boss. We may be in touch.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 33, 'npc_work_2', 'Did you deliver those codes yet? My superior, he doesn''t like to wait.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 34, 'npc_noloc_2', 'My superior should transmit his coordinates to me in just a few moments.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 35, 'npc_failure_2', 'Failure to deliver some codes pretty much eliminates you from our list of "possible candidates." Maybe you should try moisture farming.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 36, 'otherescort_2', 'Sorry, friend, can''t help you.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 37, 'dontknowyou_2', 'Sorry, friend, can''t help you.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 38, 'npc_breech_2', 'Hey, buddy! Over here! You looking for some Corellian Double-Brandy? '),
('string/en/static_npc/corellia/luthin_dlunar.stf', 39, 'npc_takeme_2', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 40, 'npc_dropoff_2', ''),
('string/en/static_npc/corellia/luthin_dlunar.stf', 41, 'npc_smuggle_2', 'I''ll make sure these get to our accounting department. You know Luthin spoke well of you. Keep up the good work and you may find yourself joining our extended family.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 42, 'gotowork_2', 'Where are those codes you were supposed to give me, friend?'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 43, 'notit_2', 'These are not the codes I was supposed to get. You''re not trying to cheat us, are you?'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/corellia/luthin_dlunar.stf', 48, 'player_3_2', 'It seems too simple. What''s the catch?'),
