('string/en/static_npc/corellia/tarl.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/tarl.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/tarl.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/corellia/tarl.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/corellia/tarl.stf', 48, 'player_3_2', 'Do they have anything I can use?'),
