INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 136, 'player_3_6', ''),
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 137, 'npc_reset_1', 'You''re backing out on me? If you think you can handle it, maybe I''ll let you try again later.'),
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 138, 'npc_reset_2', 'You''re backing out on me? If you think you can handle it, maybe I''ll let you try again later.'),
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 139, 'npc_reset_3', 'You''re backing out on me? If you think you can handle it, maybe I''ll let you try again later.'),
('string/en/static_npc/corellia/thrackan_sal_solo.stf', 140, 'npc_reset_4', 'You''re backing out on me? If you think you can handle it, maybe I''ll let you try again later.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 1, 'next', 'I have satisfied my yearning for revenge and achieved a certain quietus. I thank you again for your help.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 2, 'cantwork', 'I have a mission of compelling importance available to you, once you are not so busy.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 3, 'npc_reset', 'Your cavalier dismissal of my urgent need for revenge dissatisfies me.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 4, 'notyet', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 5, 'npc_1_1', 'Have you ever seen the holopainting of our beloved Emperor with his hand held high, receiving the adulation of a huge crowd? Yes, that''s right, ''Palpatine Triumphant.'' That was mine. It made me famous on Coruscant. Now I''m back home seeking a certain critic, the slime-toad Faswald Vorsuble. The acid he spouted about my first showing, decades ago, I shall not repeat. For years I have planned to teach him a lesson. You can teach it. I want you to destroy his vacation home.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 6, 'npc_2_1', 'Good. I have the wilderness coordinates of his home right here. I believe he has some kind of large pet as a guard, so have a care.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 7, 'npc_3_1', 'You seem too concerned by issues of legality. You won''t have much place in the New Order if you keep on that way.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 8, 'npc_4_1', '''Legal''? This is the New Order. What''s ''legal'' is whatever the Empire says is legal. And nowadays I have friends so high up in the Empire that, essentially, what''s legal is whatever I say is legal. Will you destroy Vorsuble''s home or not?'),
('string/en/static_npc/corellia/venthan_chassu.stf', 9, 'npc_backtowork_1', 'I grow impatient for you to carry out my revenge. Go!'),
('string/en/static_npc/corellia/venthan_chassu.stf', 10, 'npc_reward_1', 'Immensely cathartic. Yet still I feel the canker in my heart, demanding further revenge. I may have more work for you soon.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 11, 'npc_work_1', 'Haven''t you destroyed Faswald Vorsuble''s vacation home? I anticipate the calamity so strongly, I can hardly contain myself.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 12, 'npc_noloc_1', 'I am waiting for an informant to relay to me the location of Vorsuble''s vacation home. Check with me shortly.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 13, 'npc_failure_1', 'You were perhaps too squeamish to destroy that home? Well, I can always find someone else to enact my just revenge.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 14, 'otherescort_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 15, 'dontknowyou_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 16, 'npc_breech_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 19, 'npc_smuggle_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 20, 'gotowork_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 21, 'notit_1', ''),
('string/en/static_npc/corellia/venthan_chassu.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 26, 'player_3_1', 'Destroying a critic''s home for one bad review may be satisfying, but it isn''t legal, is it?'),
('string/en/static_npc/corellia/venthan_chassu.stf', 27, 'npc_1_2', 'I still recall the awful things the critic Faswald Vorsuble wrote about me all those years ago. ''Spews color in erratic gobs, like the trail of blood from a wounded mynock.'' I cannot rest until Faswald Vorsuble knows, first-hand, what a trail of blood looks like -- close up. I want you to destroy him. Trust me, you''ll do the galactic arts community a favor.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 28, 'npc_2_2', 'Good. As you cut down Faswald Vorsuble with blaster fire, be calm, for this is the man who called me ''an egomaniacal dabbler.'''),
('string/en/static_npc/corellia/venthan_chassu.stf', 29, 'npc_3_2', 'When this is the man who called me ''hopeless in talent and, by all reports, in personal character,'' you can allow him to live?'),
('string/en/static_npc/corellia/venthan_chassu.stf', 30, 'npc_4_2', '''I have not discerned who trained this neophyte Chassu. Perhaps no reputable teacher will admit to foisting on the galaxy this ninth-rate purveyor of puerile, polychromatic poppycock.'' I ask you, can you allow this inhuman vandal of character to survive a moment longer?'),
('string/en/static_npc/corellia/venthan_chassu.stf', 31, 'npc_backtowork_2', 'I still burn at Vorsuble''s words: ''Depicts human faces as though viewing them through a Gran''s third eye.'' This man must die, and you are idly waiting here. Go!'),
('string/en/static_npc/corellia/venthan_chassu.stf', 32, 'npc_reward_2', '''Shows a philosophy of artistic composition that seems derived from the scrap-heaps of Doaba Guerfel.'' A man who says that of me deserves to die.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 33, 'npc_work_2', 'Every moment burns Vorsuble''s words more deeply in my memory: ''An artist who apparently seeks to start a new movement called Incoherence.'' Do not return until he is dead, do you hear?'),
('string/en/static_npc/corellia/venthan_chassu.stf', 34, 'npc_noloc_2', 'I have a probe droid looking for Vorsuble right now. In moments, I expect to know his location. Talk to me then.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 35, 'npc_failure_2', 'No! I cannot believe that this odious man still draws breath. It is an offense against the galaxy. Mark me -- I shall see him destroyed.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 36, 'otherescort_2', 'I daresay you''re talking to the wrong person.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 37, 'dontknowyou_2', 'I want nothing to do with you.'),
('string/en/static_npc/corellia/venthan_chassu.stf', 38, 'npc_breech_2', 'It is some ruffian. Protect me, or you are fired!'),
