('string/en/static_npc/corellia/zekka_thyne.stf', 87, 'notit_4', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 88, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 89, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 90, 'player_1_4', 'Yes.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 91, 'player_2_4', 'No.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 92, 'player_3_4', 'Is this killer anyone I should know?'),
('string/en/static_npc/corellia/zekka_thyne.stf', 93, 'npc_1_5', ''),
