('string/en/static_npc/corellia/zekka_thyne.stf', 118, 'npc_4_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 119, 'npc_backtowork_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 120, 'npc_reward_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 121, 'npc_work_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 122, 'npc_noloc_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 123, 'npc_failure_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 124, 'otherescort_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 125, 'dontknowyou_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 126, 'npc_breech_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 127, 'npc_takeme_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 128, 'npc_dropoff_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 129, 'npc_smuggle_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 130, 'gotowork_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 131, 'notit_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 132, 'player_reset_6', 'I don''t want this mission right now.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 136, 'player_3_6', ''),
('string/en/static_npc/corellia/zekka_thyne.stf', 137, 'npc_reset_1', 'Don''t come back till you''re ready to play with the big boys.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 138, 'npc_reset_2', 'Don''t come back till you''re ready to play with the big boys.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 139, 'npc_reset_3', 'Don''t come back till you''re ready to play with the big boys.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 140, 'npc_reset_4', 'Don''t come back till you''re ready to play with the big boys.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 141, 'waypoint_description_1', 'Kill the Bothan, Korowee Fa''lorn, and get the encrypted disc he carries.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 142, 'waypoint_description_2', 'Find and kill Wedu Belar.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 143, 'waypoint_description_3', 'Remove the threat Wililikin holds by eliminating Wililikin himself.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 144, 'waypoint_description_4', 'Imtercept the assassin, Drune Juntura, and stop him.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 145, 'waypoint_name_1', 'Kill Korowee Fa''lorn.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 146, 'waypoint_name_2', 'Kill Wedu Belar.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 147, 'waypoint_name_3', 'Kill Wililikin.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 148, 'waypoint_name_4', 'Kill Drune Juntura.'),
('string/en/static_npc/corellia/zekka_thyne.stf', 149, 'gotowork', 'What do you want? I already gave you the disk. Can''t you just leave me alone?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 1, 'cant_work', 'You appear to be busy. I do so hope you are under orders by an Officer even higher than myself. If not, I hope you reconsider your current employment and return back to work under my command.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 2, 'dontknowyou_1', 'Move along. You are not part of this operation.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 3, 'dontknowyou_2', 'Who are you? I do not know you nor do you have any business speaking to me. Move along.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 4, 'dontknowyou_3', 'Oh, you''re not picking these up?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 5, 'dontknowyou_4', 'Who are you?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 6, 'gotowork_1', 'What?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 7, 'gotowork_2', 'Yes?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 8, 'gotowork_3', 'Hmm?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 9, 'gotowork_4', 'No, this is not what I am intended to deliver to the other family members.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 10, 'next', 'You have performed a remarkable service for my kin, myself, and the Empire.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 11, 'notit_1', 'What is this?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 12, 'notit_2', 'I did not ask for you this. Take it back!'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 13, 'notit_3', 'This is not what I asked for! I do not have time to "joke."'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 14, 'notit_4', 'What is this?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 15, 'notyet', 'I am quite busy and do not have the time to speak with you.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 16, 'npc_1_1', 'Good day to you, soldier. I have been briefed on your excellent performance in the field, therefore I am directing this assignment to you. I need you to intercept a squadron of soldiers that have gone rogue. Bring them back here for questioning. Understood?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 17, 'npc_1_2', 'I have debriefed this "commander" and have been told some interesting news, indeed. I have had to contact one of the Empire''s Chief Inquisitors to come retrieve him. He has landed nearby and I need you to escort him here.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 18, 'npc_1_3', 'I cannot believe the audacity of that Inquisitor! Whether he works for the Emperor himself, he forgets with whom he is speaking, or for that matter, what family I come from. Speaking of which, I have some holographs of my family that I need picked up. Would you do this for me?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 19, 'npc_1_4', 'Hmmmm.... that holovid was most disturbing. Considering most of it was touched up by their propagandists, there was still enough to unsettle me. I need you to do one more thing for me. Please deliver a note to my manservant, Jaaves. Will you do this for me?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 20, 'npc_2_1', 'Very good. I would not be surprised to find them reticent to your apprehending them. If they choose not to come willingly, then use whatever force is needed. I would prefer the outcome to entail your bringing in at least one of them for questioning.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 21, 'npc_2_2', 'As would be expected of you. But, I do place my trust within your abilities that you will do so in a prompt manner. I shall be waiting patiently, for I have a few questions to ask him myself.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 22, 'npc_2_3', 'Please listen. Since a Rebel can be hiding anywhere, I hope you keep this quiet. If they were to gather information on my family, many innocents could be hurt. Be rather covert about picking up these holographs of them. Thank you.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 23, 'npc_2_4', 'Yes. Yes, it is unfortunately. This is for no other reason than to protect my family were they not to come. Please do not mistake my loyaltys, soldier. Family first, then the Empire.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 24, 'npc_3_1', 'This was not a request, soldier - this was an order. I understand you may have suffered a concussion, therefore go see a medic, then report back to me to accept this assignment.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 25, 'npc_3_2', 'Why? I will give you a few moments to think on that, and I will expect a very clear answer.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 26, 'npc_3_3', 'Very well. Since this is not an official order, I cannot force you to do so. A shame, though. I will have to note on your record your lack of initiative.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 27, 'npc_3_4', 'Believe what you must, soldier, but for the time being I am still your Commander. A shame we could not work together. Very well, from hereon I shall make it a point to remind you of the hierarchy in our relationship.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 28, 'npc_4_1', 'We have received reports that a group of stormtroopers have been raiding a nearby village known for their vocal sympathy towards rebels. Though I do not tolerate that type of scum, the murder of non-combatants will not be allowed. These stormtroopers are not under my command, therefore they are obviously deserters and need to be taken care of accordingly.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 29, 'npc_4_2', 'All I was able to get out of him was his callsign and rank. Reports have come in to show his squad killed every last man, woman, and child in that village. His justification was the claim that he was working directly for the Emperor''s people. We''ll let the Inquisitor see about that!'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 30, 'npc_4_3', 'We are a proud family of loyalists who have served the Old Republic for many centuries. We have had many within our family be Senatorial Guards and held various functions within the Old Repubilc. When the Emperor changed to a New Order, we were quite pleased, and continued to serve as we have done in the past. Soon the Rebels will realize the Empire is here to restore order to the galaxy.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 31, 'npc_4_4', 'Wha..? NO! I would never sully the honor of my family name by engaging in an action such as that! I would sooner die than disgrace the Lytus name! No... this is an invitation to a family meeting. I am calling the family together so that we may discuss many matters.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 40, 'npc_backtowork_1', 'You will need to track down that squad of stormtroopers who are causing problems, then bring them back here'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 41, 'npc_backtowork_2', 'You are to bring back the Inquisitor without any harm coming to him. Remember, the Inqusitors report directly to His Excellence, the Emperor.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 42, 'npc_backtowork_3', 'I need you to pick up a datapad containing a lot of pictures of my home life.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 43, 'npc_backtowork_4', 'Jaaves is waiting! He has been a loyal servant to our family for many years. Do not offend him by waiting any longer!'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 44, 'npc_breech_1', 'Over there... a witness. Take him out before the operation is uncovered.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 45, 'npc_breech_2', 'You must be the agent sent to escort me back to Lytus, correct?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 46, 'npc_breech_3', 'Hey there. Are you the one picking up this holovid?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 47, 'npc_breech_4', 'You are the one that was described by Master Lytus. Do you have the invitiation?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 48, 'npc_dropoff_1', 'You took your time in bringing me back. I will be sure to let your commander know.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 49, 'npc_dropoff_2', 'Since you have brought me here in a timely manner, I will not associate you with the Commander poking his nose where it doesn''t belong.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 50, 'npc_dropoff_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 52, 'npc_failure_1', 'You were not able to find the squad? The Empire has no room for inept agents. Good day to you.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 53, 'npc_failure_2', 'You were to bring him back here personally, I am afraid that you will need to be detained within the local whereabouts until I can hand you over to the Emperor''s men.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 54, 'npc_failure_3', 'How were you able to mess this one up? Tell me! How?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 55, 'npc_failure_4', 'How were you unable to find him? This is horrible!'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 68, 'npc_noloc_1', 'Let me confer with my Intelligence as to the whereabouts of this squadron. Please check back with me in a short while.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 69, 'npc_noloc_2', 'Let me confirm where the Inquisitor can be found and I will be able to give you the coordinates. Check back with me in a few minutes.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 70, 'npc_noloc_3', 'Let me contact the holograph developer. Check back with me in a few minutes.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 71, 'npc_noloc_4', 'Let me contact Jaaves and find out where he can be located. Check back with me in a short while.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 72, 'npc_reset', 'That is a shame. I do hope you know this will go down on your permanent record.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 73, 'npc_reward_1', 'You have done well, soldier. This will be marked on your record, I hope you know. As for this commander, I will speak with him personally and discern why he deserted the Empire.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 74, 'npc_reward_2', 'You have done well. I will now hand over this prisoner to the Inquisitor, and also ask a few questions myself. You are dismissed for now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 75, 'npc_reward_3', 'Why does this datadisk look like it has been accessed? Did you view these images? Nevermind, it''s too late now, but I hope you have the decency not speak about things you do not understand. As far as you are concerned, these are family pictures, alright? I now have to see if this matches the Inquisitor''s contradicting story. Leave me for now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 76, 'npc_reward_4', 'I offer you my thanks for doing this. Our meeting will convene in a while. Depending on the outcome of the decision, I may introduce you to the rest of the family. In the meantime I present you this, a family artifact, only owned by Lytus family members and their close friends.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 77, 'npc_smuggle_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 79, 'npc_smuggle_3', 'Okay, good. Look, tell the guy who''s buying this that the images aren''t that great, but I was able to clean them up alot which really helped. I also put the label on there like he wanted me to.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 80, 'npc_smuggle_4', 'Yes, this is it. I see you have been involved in these matters. Fear not, for the Lytus family is quite honorable. They will see to it the Empire survives, but without the taint of the Emperor.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 81, 'npc_takeme_1', 'I surrender. Take me to your Commander at once. I am a special agent for the Empire.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 82, 'npc_takeme_2', 'You are late. Now... take me to that meddlesome Commander immediately. I do not have time to waste on this matter.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 83, 'npc_takeme_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 85, 'npc_work_1', 'Did you need your orders clarified?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 86, 'npc_work_2', 'Why have you not left to escort the Chief Inquisitor here yet?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 87, 'npc_work_3', 'Did you have a question?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 88, 'npc_work_4', 'Why are you still here?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 89, 'otherescort_1', 'Move along. You are not part of this operation.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 90, 'otherescort_2', 'Who are you? I do not know you nor do you have any business speaking to me. Move before I have a couple of questions to ask myself.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 91, 'otherescort_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 93, 'player_1_1', 'Yes, sir. I''ll leave at once.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 94, 'player_1_2', 'Yes, sir. I will bring him here safe and sound.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 95, 'player_1_3', 'Yes sir, I shall.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 96, 'player_1_4', 'Sure, I''ll do it. I take it this is covert, correct?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 97, 'player_2_1', 'I am not able to perform that function, sir.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 98, 'player_2_2', 'Sir, I cannot do this?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 99, 'player_2_3', 'No sir, I am not available for this.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 100, 'player_2_4', 'No... I do not trust your ability to command anymore, Lytus.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 101, 'player_3_1', 'What do you mean  ''gone rogue''?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 102, 'player_3_2', 'What was this news?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 103, 'player_3_3', 'Why is your family so special?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 104, 'player_3_4', 'Is this a letter of defection?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 105, 'player_4_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 106, 'player_4_2', ''),
