('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 125, 'player_reset', 'I cannot perform this assignment any longer.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 126, 'player_sorry', 'What was my mission again, sir?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 127, 'return_waypoint_description_1', 'Commander Lytus is waiting to question this "officer".'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 128, 'return_waypoint_description_2', 'Commander Lytus is waiting for you to return'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 129, 'return_waypoint_description_3', 'Commander Lytus is waiting for you to return'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 130, 'return_waypoint_description_4', 'Commander Lytus is waiting for your return.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 131, 'return_waypoint_name_1', 'Commander Lytus'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 132, 'return_waypoint_name_2', 'Commander Lytus'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 133, 'return_waypoint_name_3', 'Commander Lytus'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 134, 'return_waypoint_name_4', 'Commander Lytus'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 135, 'waypoint_description_1', 'This is where you will find the outfit of Stormtroopers that have gone rogue'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 136, 'waypoint_description_2', 'This is where you will find the Chief Inquisitor'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 137, 'waypoint_description_3', 'This is where you will find the Holovid Developer'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 138, 'waypoint_description_4', 'This is where you will find Jaaves.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 139, 'waypoint_name_1', 'Rogue Troopers'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 140, 'waypoint_name_2', 'Chief Inquisitor'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 141, 'waypoint_name_3', 'Holovid Developer'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 142, 'waypoint_name_4', 'Jaaves'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 143, 'npc_reset_1', 'That is a shame. I do hope you know this will go down on your permanent record.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 144, 'npc_reset_2', 'That is a shame. I do hope you know this will go down on your permanent record.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 145, 'npc_reset_3', 'That is a shame. I do hope you know this will go down on your permanent record.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 146, 'npc_reset_4', 'That is a shame. I do hope you know this will go down on your permanent record.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 147, 'player_reset_1', 'I cannot perform this assignment any longer.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 148, 'player_reset_2', 'I cannot perform this assignment any longer.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 149, 'player_reset_3', 'I cannot perform this assignment any longer.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 150, 'player_reset_4', 'I cannot perform this assignment any longer.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 151, 'player_sorry_1', 'What was my mission again, sir?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 152, 'player_sorry_2', 'What was my mission again, sir?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 153, 'player_sorry_3', 'What was my mission again, sir?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_jatrian_lytus.stf', 154, 'player_sorry_4', 'What was my mission again, sir?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 1, 'cant_work', 'I have a certain project to discuss with you when you are less busy.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 2, 'dontknowyou_1', 'You got the wrong person.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 3, 'dontknowyou_2', 'You''ve got the wrong fellow. Don''t make my day any worse than it already is.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 4, 'dontknowyou_3', 'Ee-you have the wrong individual.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 5, 'gotowork_1', 'Get going, he''s waiting.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 6, 'gotowork_2', 'Lead me to that scientist.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 7, 'gotowork_3', 'Ee-your client is waiting!'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 8, 'next', 'I have determined, to my own satisfaction, the truth of the destruction of Alderaan. I shall act on that understanding shortly. You have been very helpful.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 9, 'notit_1', 'I expected a fragment of the destroyed planet Alderaan. This isn''t it.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 10, 'notit_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 11, 'notit_3', 'I expected you to bring me a recording of a transmission from the Death Star made shortly after the destruction of Alderaan. That isn''t it.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 12, 'notyet', 'I can''t help you... I only employ Imperial operatives. Look elsewhere for work.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 13, 'npc_1_1', 'Hello. I ask that you help me investigate a troublesome and politically sensitive subject -- to be blunt, the destruction of Alderaan. I have contracted with a certain specialist in procurement to obtain a specimen from the destroyed planet, and I ask that you bring me the sample -- discreetly. Will you do so?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 14, 'npc_1_2', 'I have received an Imperial Intelligence report that a certain space pirate is on Dantooine. I believe this pirate can tell me something useful about the destruction of Alderaan. I want you to bring the pirate here.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 15, 'npc_1_3', 'Based on a lead from that pirate you arrested for me, I have secured an alleged holorecording of the destruction of Alderaan. It may shed considerable light on my inquiry, if you will bring it here for me -- discreetly.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 16, 'npc_2_1', 'Very well. My contact has specified a rendezvous point in the wilderness. Bring the sample here, and again, tell no one.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 17, 'npc_2_2', 'Very well. Move quickly, before some over-eager footsoldier spots our subject and decides to try some target practice.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 18, 'npc_2_3', 'Very well. My contact is a Bothan informant. They seem to excel in procuring such contraband data. Please bring the recording here at once.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 19, 'npc_3_1', 'Very well. I''d prefer that you tell no one of this matter.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 20, 'npc_3_2', 'Very well. As before, I''d prefer that you tell no one about my investigation.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 21, 'npc_3_3', 'Very well. As before, I hope you will not tell anyone of this matter.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 22, 'npc_4_1', 'The official story, of course, has it that Rebels on Alderaan accidentally destroyed the planet as they prepared to use a new super-weapon against the Empire. Some evidence is troubling to that account, and that is all I wish to say at this time.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 23, 'npc_4_2', 'I believe this document considers the pirate''s name classified. I can say that our subject is the last survivor of an engagement with Imperial soldiers that destroyed both sides.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 24, 'npc_4_3', 'I''m told it''s a transmission sent from the Death Star shortly after the destruction of Alderaan. Apparently an Imperial maintenance supervisor aboard the battle station sent the message despite strict orders to maintain silence.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 25, 'npc_5_1', 'Possibly there is nothing to learn. However, certain world-shattering calamities could be expected to leave telltale radiation scarring, impact patterns, and a variety of more esoteric signatures. Such signs could indicate the nature of Alderaan''s fate.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 26, 'npc_5_2', 'I recognize the subject''s name from briefings about piracy at the Graveyard of Alderaan. Those rogues know much about the planet''s destruction, though of course most of it is legend and fabulation.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 27, 'npc_5_3', 'Obviously it was a terrible tragedy in any case. Regarding the agency of the destruction I have only preliminary conclusions, and would prefer to seek more evidence before speaking my mind.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 28, 'npc_6_1', 'I believe the contact would prefer to remain anonymous. Will you bring me the sample?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 29, 'npc_6_2', 'My findings are inconsistent with Imperial Intelligence reports of the Rebellion''s super-weapon. Beyond that I prefer not to speculate. Will you bring that pirate here?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 30, 'npc_6_3', 'If the Empire did in fact play a role -- but no, I am speaking prematurely. It makes no sense to borrow trouble. Please bring me the recording of the Death Star transmission -- and again, I would appreciate discretion.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 31, 'npc_backtowork_1', 'I know nothing else to say, other than what I''ve already explained. I ask you to bring me the sample I ordered.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 32, 'npc_backtowork_2', 'That is all I have to say. Bring me that pirate, who may shed light on the destruction of Alderaan.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 33, 'npc_backtowork_3', 'I have no more information. I''d like you to bring me that recording of the Death Star transmission promptly.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 34, 'npc_breech_1', 'Hey! Did that scientist Talmaron send you?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 35, 'npc_breech_2', 'Help! I don''t care if you''re with the Empire -- you''ve got to be better than these animals!'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 36, 'npc_breech_3', 'Ee-you are from the Imperial scientist, Talmaron?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 38, 'npc_dropoff_2', 'This scientist -- an Imperial -- looking into Alderaan? I thought all you guys were hushing it up, like that transmission sent from the Death Star telling about how it blew up the planet. I''m really surprised.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 40, 'npc_failure_1', 'You did not bring me the sample from Alderaan? I wish I''d understood your limitations beforehand.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 41, 'npc_failure_2', 'You didn''t bring me that pirate? Very well. I must find someone with greater abilities to do the job.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 42, 'npc_failure_3', 'You didn''t bring that recording of the Death Star transmission? How unfortunate. I must find someone more capable.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 43, 'npc_more_1_1', 'Look, buddy -- if your scientist friend puts that hunk of rock under an analyzer, he''ll see radiation signatures like nothing else in the galaxy, radiation that''s specifically associated with Alderaan. So don''t give me a hard time, right? Get going, he''s waiting.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 44, 'npc_more_1_2', 'Alderaan? Hey, I captured so many ships there at that Graveyard -- people leaving mementos in orbit, you know -- and I heard all the stories. Yeah, I know lots about Alderaan. Lead me to that scientist, and I''ll see what kind of deal I can work.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 45, 'npc_more_1_3', 'Ee-you should pay, ee-yourself, for such information -- but I shall say this: The voice is panicky, and cries much, but is clearly heard to say, "We killed them, we killed the whole world." Ee-your client is waiting!'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 52, 'npc_noloc_1', 'I am awaiting exact coordinates for the rendezvous from my contact, who is somewhat sensitive regarding Imperial observation. Contact me again shortly for the coordinates.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 53, 'npc_noloc_2', 'I have probe droids out looking for the pirate and should have coordinates soon. Contact me shortly.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 54, 'npc_noloc_3', 'I''m awaiting coordinates for a rendezvous from the informant who secured the recording. Contact me again shortly.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 55, 'npc_reset', 'Very well. I wish you''d told me of your reluctance before accepting the assignment.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 56, 'npc_reward_1', 'Very well. I shall analyze this specimen for telltale clues. I compensate you for your time, and I ask you to contact me again in the near future.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 57, 'npc_reward_2', 'If what this pirate says is true -- and I must confirm it, of course -- this opens up a new avenue of inquiry. Here -- let me compensate you for your effort, and please contact me again soon.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 58, 'npc_reward_3', 'Very well. Now let me listen to this transmission -- hmm. That is -- hmm. I must say, the evidence appears -- well, I believe I''d best keep my own counsel regarding further actions. I can''t use Imperial funds to pay you this time but hopefully you''ll find this a suitable reward. Again, I ask you to maintain discretion.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 59, 'npc_smuggle_1', 'I got his piece of Alderaan right here. There''s plenty of ''em to go around.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 61, 'npc_smuggle_3', 'Ee-yes, I have the transmission from the Death Star that ee-your client wanted. I expect prompt payment.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 63, 'npc_takeme_2', 'I''ll go quietly. This has been a lousy day, so far, on a pretty lousy planet. And I think my day is about to get a lot worse.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 65, 'npc_work_1', 'I wish you to bring me a specimen of the destroyed planet Alderaan. That isn''t too difficult, I presume.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 66, 'npc_work_2', 'I''m waiting for you to bring me that pirate, who may shed light on the destruction of Alderaan.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 67, 'npc_work_3', 'I hope you''ll bring me that recording of the transmission made from the Death Star. I''d like to hear it soon.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 69, 'otherescort_2', 'I''m not the one you''re looking for. Don''t make my day any worse than it already is.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 77, 'player_3_1', 'Why are you investigating the destruction of Alderaan?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 78, 'player_3_2', 'Who is the pirate?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 79, 'player_3_3', 'What is this recording?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 80, 'player_4_1', 'What can you learn from a fragment of Alderaan?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 81, 'player_4_2', 'Why could the pirate tell you anything about the destruction of Alderaan?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 82, 'player_4_3', 'What do you think really happened to Alderaan?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 83, 'player_5_1', 'Who is this procurement specialist?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 84, 'player_5_2', 'What did you learn from the fragment of Alderaan that I brought you?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 85, 'player_5_3', 'What would you do if you thought the Empire isn''t telling the truth about Alderaan?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 86, 'player_more_1_1', 'How do I know this is really a piece of Alderaan, and not some rock you just picked up?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 87, 'player_more_1_2', 'I''m working for a scientist who wants to talk to you about Alderaan''s destruction? Do you know anything about it?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 88, 'player_more_1_3', 'What is on this recording?'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 95, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 96, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 97, 'return_waypoint_description_1', 'This Imperial scientist awaits a fragment of the destroyed world Alderaan, which he hopes to analyze.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 98, 'return_waypoint_description_2', 'This Imperial scientist has ordered the arrest of a pirate who may know something about the destruction of Alderaan.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 99, 'return_waypoint_description_3', 'This Imperial scientist awaits a recording of a transmission sent from the Death Star shortly after the destruction of Alderaan.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 100, 'return_waypoint_name_1', 'Xaan Talmaron'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 101, 'return_waypoint_name_2', 'Xaan Talmaron'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 102, 'return_waypoint_name_3', 'Xaan Talmaron'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 103, 'waypoint_description_1', 'Imperial scientist Xaan Talmaron has contracted to obtain a specimen of the destroyed planet Alderaan from a "procurement specialist" at these coordinates.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 104, 'waypoint_description_2', 'Imperial scientist Xaan Talmaron wishes to have this pirate arrested, in hopes of learning about the Empire''s role in the destruction of Alderaan.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 105, 'waypoint_description_3', 'Imperial scientist Xaan Talmaron has arranged with a Bothan informant to purchase a recording of a transmission sent from the Death Star shortly after the destruction of Alderaan.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 106, 'waypoint_name_1', 'Alderaan Fragment'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 107, 'waypoint_name_2', 'Pirate of Alderaan'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 108, 'waypoint_name_3', 'Death Star Transmission'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 109, 'npc_reset_1', 'Very well. I wish you''d told me of your reluctance before accepting the assignment.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 110, 'npc_reset_2', 'Very well. I wish you''d told me of your reluctance before accepting the assignment.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 111, 'npc_reset_3', 'Very well. I wish you''d told me of your reluctance before accepting the assignment.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 112, 'npc_reset_4', 'Very well. I wish you''d told me of your reluctance before accepting the assignment.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 113, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 114, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 115, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 116, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 117, 'player_reset_5', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 118, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 119, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 120, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_imperialgarrison_xaan_talmaron.stf', 121, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 1, 'cant_work', 'I can use a little help with something. When you''ve got some free time, come back and see me.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 2, 'dontknowyou_1', 'I''m just waiting for a delivery, citizen. You can go on your way. I''ll be just fine.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 3, 'dontknowyou_2', 'You don''t want to be here. It''s too dangerous.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 4, 'gotowork_1', 'You didn''t lose the package did you? '),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 6, 'next', 'I can''t thank you enough for the help you''ve given me. Come back and see me again soon, maybe I''ll have more work for you.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 7, 'notit_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 8, 'notit_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 9, 'notyet', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 10, 'npc_1_1', 'The Empire is a rough place to be a miner. I try to look after my people but corruption runs rampant and most officials are a lot more concerned with the numbers making them look good than they are with making the numbers worth anything. Sorry, I tend to get a bit caught up. Are you looking for work by any chance? '),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 11, 'npc_1_2', 'I hope you can help me. Someone trying to force me to vote against tighter safety regulations has kidnapped my subordinate. I don''t want to risk my people with lax safety standards, but I don''t want my assistant killed either. Would you be willing to try a rescue?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 12, 'npc_2_1', 'Deliver these reports to the commander''s courier and be careful. Not everyone wants the commander to see just how much skimming goes on. '),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 13, 'npc_2_2', 'I''m very grateful. All of my workers are outfitted with a locating device in case of trouble during a mining operation. This should aid you in locating the kidnappers. Be very careful, I don''t want anyone getting killed who didn''t start this.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 14, 'npc_3_1', 'Oh well, I''ll find someone else then.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 15, 'npc_3_2', 'No matter what I do, somebody will die.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 16, 'npc_4_1', 'Commander Lytus has actually expressed an interest in finding out the truth about what goes on at this operation. I need someone to deliver these reports to his courier. He''ll be pretty shocked at the discrepancy between these and the ones that were filed officially. Interested?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 17, 'npc_4_2', 'I''m not certain but I have a sneaking suspicion that the Corporate Sector Authority is involved somehow. They''re a lot more concerned with credits than they are with people. Can you help me?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 22, 'npc_backtowork_1', 'Was there something you needed to say to me?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 23, 'npc_backtowork_2', 'I wish I had more for you to go on but I''m afraid that''s it.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 24, 'npc_breech_1', 'Do you have a delivery for Commander Lytus?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 25, 'npc_breech_2', 'Please help me!'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 27, 'npc_dropoff_2', 'Thanks for saving me from those lowlifes.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 28, 'npc_failure_1', 'I guess somebody doesn''t want the truth to come out. I''m sure you tried your best.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 29, 'npc_failure_2', 'I know you tried your best. Don''t feel too bad. '),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 36, 'npc_noloc_1', 'I need to contact the commander and see where you''ll be meeting his courier. Come back and see me in a little while.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 37, 'npc_noloc_2', 'Something seems to be jamming my assistant''s locater device. Come back in a few minutes, I''ll see if I can get someone to boost signal strength.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 38, 'npc_reset', 'Come back when you think you''re ready to see this all the way through.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 39, 'npc_reward_1', 'Thanks for taking care of that. Maybe my people will get treated a little better now.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 40, 'npc_reward_2', 'I don''t know how to thank you. Words are inadequate.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 41, 'npc_smuggle_1', 'I''ll see that the commander gets this straight away.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 44, 'npc_takeme_2', 'Kelvus sent you to rescue me? What a relief, I thought I was a goner for sure.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 45, 'npc_work_1', 'Have you delivered those records yet?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 46, 'npc_work_2', 'Is everything proceeding according to plan for that rescue?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 48, 'otherescort_2', 'You don''t want to be here. It''s too dangerous.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 49, 'player_1_1', 'Yes'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 50, 'player_1_2', 'Yes'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 51, 'player_2_1', 'No'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 52, 'player_2_2', 'No'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 53, 'player_3_1', 'What sort of work?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 54, 'player_3_2', 'Do you know who took your assistant?'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 55, 'player_4_1', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 56, 'player_4_2', ''),
