('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 65, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 66, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 67, 'return_waypoint_description_1', 'Return to Kelvus Naria and tell him you''ve completed your assignment.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 68, 'return_waypoint_description_2', 'Escort the miner safely to Kelvus Naria '),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 69, 'return_waypoint_name_1', 'Kelvus Naria'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 70, 'return_waypoint_name_2', 'Kelvus Naria'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 71, 'waypoint_description_1', 'Deliver the datadisc to the Imperial courier.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 72, 'waypoint_description_2', 'Locate and free the kidnapped miner.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 73, 'waypoint_name_1', 'Courier''s location'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 74, 'waypoint_name_2', 'Kidnapped miner''s location'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 75, 'npc_reset_1', 'Come back when you think you''re ready to see this all the way through.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 76, 'npc_rest_2', 'Come back when you think you''re ready to see this all the way through.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 77, 'npc_reset_3', 'Come back when you think you''re ready to see this all the way through.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 78, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 79, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 80, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 81, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 82, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_miningoutpost_kelvus_naria.stf', 83, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 1, 'cant_work', 'You look a little busy. Come back later when you don''t have so much to do.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 2, 'dontknowyou_1', 'No, you don''t fit the description. I''m sorry, I''m waiting for someone and you are not them.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 3, 'dontknowyou_2', 'Move along, citizen.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 4, 'dontknowyou_3', 'Citizen, go on about your business or I will arrest you for interfering with my duties.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 6, 'gotowork_2', 'What is this? I have no need of it.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 7, 'gotowork_3', 'What is this? Citizen, go on about your business or I will arrest you for interfering with my duties.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 8, 'next', 'Nice work there, youngster. Don''t worry about any enemies you''ve made working for me; you''re a courier and nothing more. And besides, if anyone does hold a grudge, the Empire and the Mining Guild are both too big to have their opinion influenced by anyone stationed on this planet.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 9, 'notit_1', 'There must be some mistake here. This isn''t the ledger I asked for.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 10, 'notit_2', 'What is this? I have no need for your junk.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 11, 'notit_3', 'Why are you bringing this to me? I don''t want it.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 12, 'notyet', 'You don''t look very reliable. Maybe after you''ve helped out around here a little more I''d be willing to trust you.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 13, 'npc_1_1', 'You want some quick cash? My business partner has a ledger containing some interesting information regarding an illegal business deal between my boss and a certain commander of the local Imperial garrison. I need someone to visit with him and bring back the ledger. What do you say?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 14, 'npc_1_2', 'I''d really like to keep Commander Lytus out of this unfortunate business. I''ve prepared a report showing how Kelvus "stole" Imperial resources from the garrison. Once Lytus has a look at this I''m sure he''ll turn his back on Kelvus and let him take the fall. My grudge is with Kelvus and not the commander, after all. Would you be willing to deliver this report?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 15, 'npc_1_3', 'Confound that wretched commander and this unnatural sense of loyalty. Can you believe he actually defended Kelvus against the accusations from the Imperial high command? Who ever heard of an Imperial that wasn''t completely self serving? I''ve had enough of Lytus. He can suffer with Kelvus for all I care. I need you to do one last favor for me.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 16, 'npc_2_1', 'That''s what I want to hear. Ok, you''ll find my friend Coer Clem at the location I''ve uploaded to your datapad. Talk with Coer, then bring the ledger back here.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 17, 'npc_2_2', 'Ok, here is a briefcase containing the report. You''ll find the location of an Imperial ensign marked on your datapad. I want you to hand the report to him with specific instructions to return it to his commander. If he asks who sent it tell him nothing. And one other thing: Coer is missing. I can only assume that Kelvus knows of my plot. He may take steps to hinder your mission.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 18, 'npc_2_3', 'Good. There is a squad leader I know that disapproves of the way Lytus runs the Imperial garrison. He has agreed to meet my courier at the location now appearing on your datapad. Bring the ledger to him and the rest will take care of itself. Don''t forget to return for your payment.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 19, 'npc_3_1', 'Have it your own way. Just stay out of the way of my plans.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 20, 'npc_3_2', 'Don''t worry about it. I''ll find some other way to bring this to the Imperials. And if you''re thinking about reporting this... just remember the good work you did for me last time. I know I will.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 21, 'npc_3_3', 'Very well then. I know you won''t tell anyone about this? Afterall, by now you''re officially a co-conspirator.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 22, 'npc_4_1', 'I''ve got a little cash I can reward you with. And I don''t believe anyone is going to miss this old mineral survey tool.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 23, 'npc_4_2', 'Yes, it is. That''s why I''m prepared to pay you well for this service.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 24, 'npc_4_3', 'Don''t you know by now that I''ll make it worth your time?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 31, 'npc_backtowork_1', 'I marked a location on your datapad. I want you to go there and talk to my friend Coer Clem. He will give you a ledger. Bring that back to me.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 32, 'npc_backtowork_2', 'Take the briefcase I gave you to the location of the Imperial ensign marked on your datapad.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 33, 'npc_backtowork_3', 'Take the ledger to the squad leader indicated on your datapad.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 34, 'npc_breech_1', 'Are you the one Stoos sent?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 35, 'npc_breech_2', 'Unless you have pressing business with the Empire, I suggest you move along, citizen. We are on patrol.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 36, 'npc_breech_3', 'Move along, citizen.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 40, 'npc_failure_1', 'What happened? Ah damn, I hope Coer took the trouble to make a copy of that ledger.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 41, 'npc_failure_2', 'That''s too bad. Luckily I''ve kept a backup copy, so I''m not too terribly inconvenienced by this.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 42, 'npc_failure_3', 'Hah. Good thing I kept the original copy of that ledger. Better luck next time?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 43, 'npc_more_1_1', 'Good work. Here, take this. Do I need to tell you to be careful with it and bring it right back to Stoos?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 52, 'npc_noloc_1', 'Look at the time! I''ve got to turn those reports in pronto. Could you get back to me later? We''ll finish talking then.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 53, 'npc_noloc_2', 'Look at the time! I''ve got to turn those reports in pronto. Could you get back to me later? We''ll finish talking then.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 54, 'npc_noloc_3', 'Look at the time! I''ve got to turn those reports in pronto. Could you get back to me later? We''ll finish talking then.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 55, 'npc_reset', 'I guess I can''t make you work. But stay out of my way or you''ll regret it.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 56, 'npc_reward_1', 'Oh yes, this is good stuff. Look at this: Kelvus Naria has been loaning groups of miners to the Imperial garrison to use as unskilled labor, while Commander Lytus has been funneling Imperial supplies to the mining outpost. Very nice. Exactly what I wanted. Here is the payment we agreed upon earlier.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 57, 'npc_reward_2', 'The report was delivered? That suits me just fine. I''ve only to give commander Lytus a little time to realize the danger of his precarious situation, then I will send this report to a friend I have in the Imperial high command.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 58, 'npc_reward_3', 'You continue to impress me with your resourcefulness. It''s only a matter of time before Kelvus is removed by the mining guild. Unfortunately I think that squad leader is doomed. Lytus is a crafty, crafty man and this incident likely will not ruin his career. Hopefully he doesn''t bear grudges. Take this... it may save your life.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 59, 'npc_smuggle_1', 'Here''s the ledger. Take it straight back to Stoos and be careful.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 60, 'npc_smuggle_2', 'A report? For the commander? Issues vital to the Empire? It sounds like he would be interested. I''ll have to check it for explosives, but I''ll make sure he sees it. Can''t be too careful these days.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 61, 'npc_smuggle_3', 'This is the information that Stoos promised? Good work, citizen. While you may have angered an Imperial commander with this action there are many more in the Empire who approve of what you have just done.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 65, 'npc_work_1', 'Do you have the ledger yet?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 66, 'npc_work_2', 'Have you delivered the report?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 67, 'npc_work_3', 'Have you delivered the ledger?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 71, 'player_1_1', 'I''ll bring you the ledger.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 72, 'player_1_2', 'Yes, I will deliver the report.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 73, 'player_1_3', 'Yes, I will help.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 74, 'player_2_1', 'I''d rather not get involved in this sort of thing.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 75, 'player_2_2', 'This is starting to sound like blackmail. I''d rather not.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 76, 'player_2_3', 'This is way too risky. Count me out.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 77, 'player_3_1', 'What do I get for helping you?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 78, 'player_3_2', 'Doesn''t this sound a little dangerous?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 79, 'player_3_3', 'What is in it for me?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 81, 'player_4_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 84, 'player_5_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 86, 'player_more_1_1', 'I am here for the ledger.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 95, 'player_reset', 'On second thought, I''d really rather not get involved in this.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 96, 'player_sorry', 'What do you want me to do again?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 97, 'return_waypoint_description_1', 'Foreman at the miner''s guild.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 98, 'return_waypoint_description_2', 'Mining outpost foreman.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 99, 'return_waypoint_description_3', 'Mining outpost foreman.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 100, 'return_waypoint_name_1', 'Stoos Olko'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 101, 'return_waypoint_name_2', 'Stoos Olko'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 102, 'return_waypoint_name_3', 'Stoos Olko'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 103, 'waypoint_description_1', 'Stoos Olko''s friend and partner in crime. Stoos sends you to Coer to retrieve a ledger.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 104, 'waypoint_description_2', 'Stoos Olko wishes you to deliver a falsified report to this Imperial ensign.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 105, 'waypoint_description_3', 'This is the squad leader Stoos Olko wants you to deliver Kelvus'' ledger to.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 106, 'waypoint_name_1', 'Coer Clem'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 107, 'waypoint_name_2', 'Imperial Ensign'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 108, 'waypoint_name_3', 'Stormtrooper Squad Leader'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 109, 'npc_reset_1', 'I guess I can''t make you work. But stay out of my way or you''ll regret it.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 110, 'npc_reset_2', 'I guess I can''t make you work. But stay out of my way or you''ll regret it.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 111, 'npc_reset_3', 'I guess I can''t make you work. But stay out of my way or you''ll regret it.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 112, 'player_reset_1', 'On second thought, I''d really rather not get involved in this.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 113, 'player_reset_2', 'On second thought, I''d really rather not get involved in this.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 114, 'player_reset_3', 'On second thought, I''d really rather not get involved in this.'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 115, 'player_sorry_1', 'What do you want me to do again?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 116, 'player_sorry_2', 'What do you want me to do again?'),
('string/en/static_npc/dantooine/dantooine_mining_outpost_stoos_olko.stf', 117, 'player_sorry_3', 'What do you want me to do again?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 1, 'cant_work', 'My missions require a good deal of concentration. Come back when you are not so preoccupied.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 2, 'dontknowyou_1', 'This is a restricted area. Move along.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 3, 'dontknowyou_2', 'I cannot speak to you.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 4, 'dontknowyou_3', 'There is nothing you can do for us. Away with you!'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 8, 'next', 'There is nothing else I need you to do at the moment. Check back with me at a later date.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 9, 'notit_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 10, 'notit_2', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 11, 'notit_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 12, 'notyet', 'I''m sorry, but I''m looking for someone with an open mind toward... let''s call it an alternative to a certain type of government. But I thank you for your interest.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 13, 'npc_1_1', 'I am called Drakka Judarrl. I am a Jedi. I need your help to stop a stormtrooper squad from slaughtering dozens of natives. They''ve been helping me conduct raids on the Imperial garrison. Will you help?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 14, 'npc_1_2', 'The Dantari chieftain that''s been helping me conduct my raids on the Imperial garrison has just had his only child kidnapped by Imperials. Could you please attempt a rescue? I could not forgive myself if this young innocent was killed.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 15, 'npc_1_3', 'The Emperor''s agent here on Dantooine, a sinister figure by the name of Luthik Uwyr, has organized some of the natives into a deadly strike force. He is teaching them to use the dark side. We must stop these agents of evil before this practice spreads offworld. Can you do it?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 16, 'npc_2_1', 'You can intercept the squad at these coordinates. I will be watching but I cannot interfere. My presence must not be revealed to the Empire. Not yet.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 17, 'npc_2_2', 'Here are the coordinates. Dantari scouts have been tracking these commandos. Please hurry.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 18, 'npc_2_3', 'You can intercept this raiding party at these coordinates. My Dantari scouts have been keeping tabs on them. Please be careful and bring allies with you if you can.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 19, 'npc_3_1', 'I will trouble you no further. May the Force be with you.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 20, 'npc_3_2', 'I shall find another to help me. May the Force be with you.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 21, 'npc_3_3', 'This mission may be too dangerous for you. You are wise to refuse.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 22, 'npc_4_1', 'Yes. I am possibly the last of my kind, although I sense the presence of a few others. I have not made any attempts to contact them for my master told me I must not let the Emperor know I exist.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 23, 'npc_4_2', 'I saw many Jedi struck down, yes. I saw the power wielded by the Emperor and his lethal weapon, Darth Vader. I wish I could wipe those memories from my mind.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 24, 'npc_4_3', 'Yes, they have a rudimentary grasp of its power but it is sufficient to make them formidable warriors. Do you still wish to tackle them?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 25, 'npc_5_1', 'He became one with the Force years ago. I was only a Padawan at the time. He saved me from the Jedi Purge.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 26, 'npc_5_2', 'We went into hiding. I was much younger then, still only a Padawan. My master helped many members of the Senate escape the Empire''s persecution. It was a dark time. Darth Vader eventually caught up with my master. '),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 28, 'npc_6_1', 'I came to Dantooine when the Rebel base was first established here. I wanted to study them to understand the state of the Rebellion. I think I must reveal myself to the Empire soon. I sense our time is coming. In the meantime, I''ll continue to organize strikes against the Empire with the help of the Dantari. Will you help them?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 29, 'npc_6_2', 'I was whisked away by a smuggler who had been aiding my master. Since that time, years ago, I''ve been careful to hide my presence. I rarely use the Force for fear of being detected by the Emperor''s spies. But please, enough talk - will you help my Dantari friend?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 31, 'npc_backtowork_1', 'You must hurry or else the Dantari will suffer greatly.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 32, 'npc_backtowork_2', 'You must hurry, friend. I don''t how much longer the storm commandos will let the child live.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 33, 'npc_backtowork_3', 'It would be best if you took allies along. These raiders will use the dark side against you.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 34, 'npc_breech_1', 'This is a restricted area! You''re under arrest! Open fire, men!'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 35, 'npc_breech_2', 'Get your hands off me, you Imperial scum! My people will make you pay for this affront!'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 36, 'npc_breech_3', 'Let us demonstrate the power of the dark side!'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 38, 'npc_dropoff_2', 'My thanks. I would likely be dead now were it not for your bravery. Are you a Jedi too?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 40, 'npc_failure_1', 'These are some of the Emperor''s elite troops. I should have sent you in with more help.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 41, 'npc_failure_2', 'I must find a way to save that poor child. I thank you for your attempt.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 42, 'npc_failure_3', 'I do not wish to reveal myself prematurely but it may be time for me to take care of this menace myself.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 44, 'npc_more_1_2', 'Yes, and I hope one day to be one as well. The Jedi are the most cunning warriors in the galaxy.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 52, 'npc_noloc_1', 'Allow me to verify those coordinates I gave you. Just a moment.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 53, 'npc_noloc_2', 'Let me verify those coordinates with my Dantari contacts. Check back with me in a few moments.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 54, 'npc_noloc_3', 'I must get an update from my Dantari scouts. You must know where to meet these raiders.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 55, 'npc_reset', 'I should not have asked you to perform these tasks. I should have realized they were beyond your skill.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 56, 'npc_reward_1', 'I am most grateful for your help. I''ve been able to accumulate a considerable amount of credits from our raids. Please accept this as a reward.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 57, 'npc_reward_2', 'I am in your debt. Please accept this as payment.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 58, 'npc_reward_3', 'You are a valued friend of the Alliance and it is my hope that you will continue to serve the cause of freedom and justice. The Empire cannot last forever. Take this artifact, it will help to guide you on the right path. May the Force be with you.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 63, 'npc_takeme_2', 'Did Drakka send you? Please take me back to her. She is very brave. I hope to one day be her equal.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 65, 'npc_work_1', 'Have you intercepted that stormtrooper squad yet? I don''t want innocent Dantari being killed.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 66, 'npc_work_2', 'Did you save that young Dantari woman? She cannot be made to suffer for my deeds.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 67, 'npc_work_3', 'Have you removed the threat of that strike force? They must not be allowed to teach others what they have learned.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 69, 'otherescort_2', 'I cannot speak to you.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 77, 'player_3_1', 'Wait! Did you just say you were a Jedi?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 78, 'player_3_2', 'Did you actually witness the Jedi Purge?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 79, 'player_3_3', 'These native warriors know how to use the dark side?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 80, 'player_4_1', 'Where is your master now?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 81, 'player_4_2', 'How did you and your master survive?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 83, 'player_5_1', 'How long have you been here?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 84, 'player_5_2', 'How did you escape?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 87, 'player_more_1_2', 'Do you know that Drakka is a Jedi?'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 95, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 96, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 97, 'return_waypoint_description_1', 'Report your success back to Drakka Judarrl.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 98, 'return_waypoint_description_2', 'Escort the Dantari woman back to Drakka Judarrl.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 99, 'return_waypoint_description_3', 'Report your success back to Drakka Judarrl.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 100, 'return_waypoint_name_1', 'Drakka Judarrl''s Location'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 101, 'return_waypoint_name_2', 'Drakka Judarrl''s Location'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 102, 'return_waypoint_name_3', 'Drakka Judarrl''s Location'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 103, 'waypoint_description_1', 'Intercept the squad and stop them from destroying Dantari villages.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 104, 'waypoint_description_2', 'Rescue the Dantari chieftain''s daughter from her captors.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 105, 'waypoint_description_3', 'Remove the threat of the dark side raiders.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 106, 'waypoint_name_1', 'Stormtrooper Squad''s Location'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 107, 'waypoint_name_2', 'Young Dantari Woman''s Location'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 108, 'waypoint_name_3', 'Dantari Dark Side Strike Force''s Location'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 109, 'npc_reset_1', 'I should not have asked you to perform these tasks. I should have realized they were beyond your skill.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 110, 'npc_reset_2', 'I should not have asked you to perform these tasks. I should have realized they were beyond your skill.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 111, 'npc_reset_3', 'I should not have asked you to perform these tasks. I should have realized they were beyond your skill.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 112, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 113, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 114, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 115, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 116, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 117, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 118, 'go_away', 'Please leave, I fear that I can''t help you anymore. I hope you can find someone stronger in the force to save you from the path of destruction.'),
('string/en/static_npc/dantooine/dantooine_remotehaven_drakka_judarrl.stf', 119, 'jedi', 'I''m honored by your presence. I''m afraid I don''t have anything to teach you though, only a word of advice. Be careful, the terror around here is dangerous and enforced both by the living and the long gone.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 1, 'cant_work', 'Your soul speaks volumes, friend... it screams for blood and vengeance... give into it, for it will bring to you many gifts. Return to me when you are ready for teaching.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 3, 'dontknowyou_2', 'Ah... it''s because you ARE a whelp. Remove yourself from my sight lest I remove your sight from you.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 4, 'dontknowyou_3', 'Oh... I''m sorry, I thought you were a bad guy.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 6, 'gotowork_2', 'What is this? You were supposed to bring that worthless Jedi artifact! Give it to me now before I shred your soul apart.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 8, 'next', 'You have proven yourself well... perhaps the Master may one day choose you over one of the other initiates... that is, if you do not die first.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 9, 'notit_1', 'I do not need any gifts, initiate. What you offer does not compare to the power of the Dark Side.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 10, 'notit_2', 'What is this? I do not want this. I have the dark side, which fuels my every waking desire.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 11, 'notit_3', 'This proves nothing to me. Bring me something more evident of your success.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 12, 'notyet', 'Your soul speaks volumes, friend... it screams for blood and vengeance... give into it, for it will bring to you many gifts. Return to me when you are ready for teaching.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 13, 'npc_1_1', 'Well, well, it seems an initiate comes upon me so brazen. I feel great anger within you, yes I do. Let me see how you choose to channel that fire. I sense a powerful presence nearby that seems somehow bound to this temple. I wish you to seek it out and destroy it. Can you manage this paltry task?'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 14, 'npc_1_2', 'Ah, I see you have managed this simple task. I have discovered what bond the animal shared with the temple, and find it to be nothing but a Holocron used to record the weak teachings of the Jedi. The animal apparently found the device and brought it here, to its nest. Now I command you to take the device to one of my brothers so that you can learn to revile the trappings of the Jedi.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 15, 'npc_1_3', 'I still feel a presence within these halls... though faint, it is attuned to the Force. As my Master had believed, there is still a Jedi that lives. Now is the time for your test, initiate. Will you take it, or walk away a coward?'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 16, 'npc_2_1', 'Though you say that with much vehemence, the results have yet to be seen. Take your hate and your anger and direct it at whatever monstrosity lurks nearby. If you cannot use your hate as a weapon, then you are not worth our time.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 17, 'npc_2_2', 'He will be waiting for you. As you walk, let this Holocron touch your skin, touch your heart, and touch your mind. Learn to hate the feeling, and remember it... forever.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 18, 'npc_2_3', 'Good... your arrogance will serve you well, or it will kill you. Only those strong with the Dark Side will be considered to join our ranks. Go, and return with a sign of your victory.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 19, 'npc_3_1', 'Oh, yes you will, yes you will... when you least expect it, your anger and bile will rise up to control you... learn to give in to it and it will be your strongest ally. Think on that, initiate.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 20, 'npc_3_2', 'Yes.... you feel it, don''t you. The dark side is the only true power, initiate. See how easily you give yourself to your anger? Feel how strong you are now? Yessss..... you do, don''t you?'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 21, 'npc_3_3', 'Oh, you will, will you? Yes, you are more under the control of the dark side than you believe. Feel it, initiate... let it inside of you... let it rule you....'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 22, 'npc_4_1', 'These old ruins, you fool, was once a holy place to the failed Jedi many centuries ago. I feel a faint presence inside and am now thinking that not all of the Jedi were righteously destroyed by the Master. We will see...');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dantooine/luthik_uwyr.stf', 23, 'npc_4_2', 'I shall enter the temple proper and sanctify it with horror and evil. The ridiculous pacifistic nature of the Jedi is an affront to our true teachings. I will remove all trace there ever were Jedi that created this place.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 24, 'npc_4_3', 'Our Master is the one who was able to do what no Sith had done before. He is the one who caused the end of the Jedi''s existence. And today, you will exterminate the last living Jedi.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 31, 'npc_backtowork_1', 'Take your hate and your anger and direct it at whatever monstrosity lurks nearby.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 32, 'npc_backtowork_2', 'Bring this frail Holocron to my brethren. They will use the dark side to destroy it once and for all.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 33, 'npc_backtowork_3', 'Venture forth, seek out this last remaining Jedi and strike him down with all your hate and fury! Return with a trophy of your victory.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 34, 'npc_breech_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 35, 'npc_breech_2', 'You are the one that Luthik spoke of? Bah! You look like nothing more than a whelp!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 36, 'npc_breech_3', 'Oh great Force powers, come to me! My training will defeat you, monster!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 40, 'npc_failure_1', 'You are a pathetic worm not worthy of interest by myself or my brethren. We do not accept weakness amongst us.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 41, 'npc_failure_2', 'So.... perhaps you were the presence I felt, after all. You have chosen to keep the Holocron for yourself, have you?. We shall wait for the most painful time before we dispose of you....'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 42, 'npc_failure_3', 'You are weak and helpless. You are not worthy of the teachings of the Sith, worthless wretch. Begone from my sight before I kill you myself.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 52, 'npc_noloc_1', 'Gather all of your hatred around you before you venture forth. Speak with me in a few minutes.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 53, 'npc_noloc_2', 'I will contact my brethren to announce your coming. You are a pathetic weakling compared to their might, and it is not time for you to die yet. Speak with me in a few minutes.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 54, 'npc_noloc_3', 'Let me use the dark side to determine where the Jedi resides. Return to me in a few minutes.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 55, 'npc_reset_1', 'Ha.. Haha... HaHaHahahahaa..... Oh, friend, you are very mistaken. Your anger guides you so strongly... you will come over in time, rest assured.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 56, 'npc_reward_1', 'You have felt life quenched through the power of your revulsion. The exquisite thrill of giving yourself to the Dark Side will be your gift forever. In the meantime, I shall now attend to the disturbing presence I feel.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 57, 'npc_reward_2', 'You know in your heart that peace is the discretion of the fool, for the wise man chooses to lash out at his enemies. You have seen what happened to the Jedi. It is now time to rebuild the Empire of the Sith again.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 58, 'npc_reward_3', 'Were the Jedi reduced to something as pathetic as that? With him dead, our victory over the Jedi is now complete. Perhaps the Master may take me as an apprentice. If so... perhaps one day I will take you as mine as well. This artefact will help guide your path to ultimate victory in the meantime.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 60, 'npc_smuggle_2', 'Ugh. This artifact needs to be destroyed immediately before it affronts my senses any further. Go back to Luthik, whelp, for your deed here is done.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 65, 'npc_work_1', 'Your fear makes you wait... let your fear guide you.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 66, 'npc_work_2', 'Why do you pause? My brethren await you.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 67, 'npc_work_3', 'Why have you not destroyed the Jedi yet?'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 71, 'player_1_1', 'Yes, I will destroy it.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 72, 'player_1_2', 'I will bring this accursed object to your Brother.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 73, 'player_1_3', 'I am ready. I will show that Jedi who is stronger.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 74, 'player_2_1', 'No, I will not let my anger control me.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 75, 'player_2_2', 'NO! The Jedi were noble beings! You lie!!!!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 76, 'player_2_3', 'Stop calling me names! I''ll kill you before I do anything else for you!!!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 77, 'player_3_1', 'Why are you here at the old ruins?'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 78, 'player_3_2', 'What will you do while I deliver this?'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 79, 'player_3_3', 'Who is the Master?'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 81, 'player_4_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 84, 'player_5_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 95, 'player_reset_1', 'I will not be controlled by you any longer!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 96, 'player_sorry_1', 'Tell me what I have to do.....'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 97, 'return_waypoint_description_1', 'Return to him to relay your victory'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 98, 'return_waypoint_description_2', 'Return to the Dark Prophet, for he may have more to teach you.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 99, 'return_waypoint_description_3', 'Return to the teacher and revel in your success.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 100, 'return_waypoint_name_1', 'Luthik Uwyr'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 101, 'return_waypoint_name_2', 'Luthik Uwyr'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 102, 'return_waypoint_name_3', 'The Dark Prophet'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 103, 'waypoint_description_1', 'Luthik feels the presence of a being at this location'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 104, 'waypoint_description_2', 'Meet a brother of Luthik''s order here.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 105, 'waypoint_description_3', 'The last remnant of the Jedi Order resides here.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 106, 'waypoint_name_1', 'Guardian of the Temple'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 107, 'waypoint_name_2', 'The Dark Brother'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 108, 'waypoint_name_3', 'The Last Jedi'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 109, 'player_reset_2', 'I will not be controlled by you any longer!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 110, 'player_reset_3', 'I will not be controlled by you any longer!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 111, 'player_sorry_2', 'Tell me what I have to do.....'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 112, 'player_sorry_3', 'Tell me what I have to do.....'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 113, 'npc_reset_2', 'Ha.. Haha... HaHaHahahahaa..... Oh, friend, you are very mistaken. Your anger guides you so strongly... you will come over in time, rest assured.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 114, 'npc_reset_3', 'Ha.. Haha... HaHaHahahahaa..... Oh, friend, you are very mistaken. Your anger guides you so strongly... you will come over in time, rest assured.'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 115, 'go_away', 'Leave at once, before I show you the true power of the dark side!'),
('string/en/static_npc/dantooine/luthik_uwyr.stf', 116, 'jedi', 'Leave this place at once! There is nothing for you here! If you persist in staying around, you will follow the path of every other pathetic Jedi that was once here!'),
('string/en/static_npc/dantooine/lx_466.stf', 1, 'cant_work', 'If you''re looking for work when you finish what you''re doing, come back to me. I may have something for you.'),
('string/en/static_npc/dantooine/lx_466.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 3, 'dontknowyou_2', 'Ulgh ked troben!'),
('string/en/static_npc/dantooine/lx_466.stf', 4, 'dontknowyou_3', 'I''m waiting for someone in particular. Don''t you have anything better to do?'),
('string/en/static_npc/dantooine/lx_466.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 6, 'gotowork_2', 'Elex send eat?'),
('string/en/static_npc/dantooine/lx_466.stf', 7, 'gotowork_3', 'This is not the item I was supposed to pick up.'),
('string/en/static_npc/dantooine/lx_466.stf', 8, 'next', 'You have been a valuable aid. I''ll let you know if I have any more work for you.'),
('string/en/static_npc/dantooine/lx_466.stf', 9, 'notit_1', 'This is not what I asked for, citizen. Return when you have completed your mission.'),
('string/en/static_npc/dantooine/lx_466.stf', 10, 'notit_2', 'This is not what I asked for, citizen. Return when you have completed your mission.'),
('string/en/static_npc/dantooine/lx_466.stf', 11, 'notit_3', 'This is not what I asked for, citizen. Return when you have completed your mission.'),
('string/en/static_npc/dantooine/lx_466.stf', 12, 'notyet', 'Your loyalty to the Empire''s goals is not evident. Return when you have proven yourself.'),
('string/en/static_npc/dantooine/lx_466.stf', 13, 'npc_1_1', 'What business do you have on Dantooine? This is a restricted area. I could however use someone outside of our chain of command to investigate a rumor from a less than reliable source. It could turn out to be dangerous, or completely harmless.'),
('string/en/static_npc/dantooine/lx_466.stf', 14, 'npc_1_2', 'In light of your past report, I feel it is necessary to reward my information source. Would you care to act as my courier?'),
('string/en/static_npc/dantooine/lx_466.stf', 15, 'npc_1_3', 'I have another task for you. This one is... difficult. I can understand if you''d rather not take part in this. It seems that someone on this post is... less than completely loyal to the Empire. I need a courier who isn''t afraid killing some crooked soldiers.'),
('string/en/static_npc/dantooine/lx_466.stf', 16, 'npc_2_1', 'I''m told there are Rebels making a base not far from here. I''ve uploaded the coordinates to your datapad. Make a quick search of the area. If you should see any Rebels I want them killed. Otherwise return here for payment.'),
('string/en/static_npc/dantooine/lx_466.stf', 17, 'npc_2_2', 'Take these rations to the location indicated on your data pad. The Dantari tribesman you meet there should be happy to receive them, though he does not speak our language with any degree of competency. Be sure you report back afterwards for your pay.'),
('string/en/static_npc/dantooine/lx_466.stf', 18, 'npc_2_3', 'That''s good. Take this recording rod to the location of the Imperial courier marked on your data pad. Once you''ve made the delivery report back to me. Be careful, though. Word is that this traitor might have brought in some mercenaries from Lok as hired muscle. Watch your back.'),
('string/en/static_npc/dantooine/lx_466.stf', 19, 'npc_3_1', 'Although you''re probably not a Rebel, if you''re not actively assisting the Empire I can no longer guarantee your safety. Proceed at your own risk.'),
('string/en/static_npc/dantooine/lx_466.stf', 20, 'npc_3_2', 'Although you''re probably not a Rebel, if you''re not actively assisting the Empire I can no longer guarantee your safety. Proceed at your own risk.'),
('string/en/static_npc/dantooine/lx_466.stf', 21, 'npc_3_3', 'I expected as much. That''s fine. Just keep this quiet is all I ask.'),
('string/en/static_npc/dantooine/lx_466.stf', 22, 'npc_4_1', 'The Empire needs your help. If that is not enough for you, then how about these credits?'),
('string/en/static_npc/dantooine/lx_466.stf', 23, 'npc_4_2', 'The glory of serving the Empire. Now tell me, yes or no citizen.'),
('string/en/static_npc/dantooine/lx_466.stf', 24, 'npc_4_3', 'Unfortunately it''s the commander of this post who you would be working against. I made a recording of him talking with one of his aides regarding matters that were... while not rebellious, not completely in line with the Empire''s sentiments, or the instructions of his commanding officer. If you deliver the recording rod I will pay you well. The mission is simple; it''s the political implications that are tough to deal with. Fortunately for you, that will be my responsibility.'),
('string/en/static_npc/dantooine/lx_466.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 31, 'npc_backtowork_1', 'Make your way to the location marked on your datapad. Kill any rebels you might find there, and report back to me.'),
('string/en/static_npc/dantooine/lx_466.stf', 32, 'npc_backtowork_2', 'Take the rations I gave you to the dantari tribesman you will find at the location marked on your data pad.'),
('string/en/static_npc/dantooine/lx_466.stf', 33, 'npc_backtowork_3', 'You''re killing me. Would you get out of here already? Take that recording rod to the Imperial courier.'),
('string/en/static_npc/dantooine/lx_466.stf', 34, 'npc_breech_1', 'Stay sharp, this could be trouble...'),
('string/en/static_npc/dantooine/lx_466.stf', 35, 'npc_breech_2', 'Yuguth debagh kurfun. Bring eat?'),
('string/en/static_npc/dantooine/lx_466.stf', 36, 'npc_breech_3', 'Are you the courier?'),
('string/en/static_npc/dantooine/lx_466.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 40, 'npc_failure_1', 'You''re lucky you''re not one of my soldiers. I''ll have to find someone who is capable of following my instructions.'),
('string/en/static_npc/dantooine/lx_466.stf', 41, 'npc_failure_2', 'You''re lucky you''re not one of my soldiers. I''ll have to find someone who is capable of following my instructions.'),
('string/en/static_npc/dantooine/lx_466.stf', 42, 'npc_failure_3', 'This is a disaster. Although I think there''s a way I can explain this. Not for your sake mind you, but for my own. You''re just lucky we share this common interest.'),
('string/en/static_npc/dantooine/lx_466.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 52, 'npc_noloc_1', 'Excuse me for a moment, I have to attend to some paperwork. Come back soon and we will discuss this further.'),
('string/en/static_npc/dantooine/lx_466.stf', 53, 'npc_noloc_2', 'Excuse me for a moment, I have to attend to some paperwork. Come back soon and we will discuss this further.'),
('string/en/static_npc/dantooine/lx_466.stf', 54, 'npc_noloc_3', 'Excuse me for a moment, I have to attend to some paperwork. Come back soon and we will discuss this further.'),
('string/en/static_npc/dantooine/lx_466.stf', 55, 'npc_reset', 'Although you''re probably not a Rebel, if you''re not actively assisting the Empire I can no longer guarantee your safety. Proceed at your own risk.'),
('string/en/static_npc/dantooine/lx_466.stf', 56, 'npc_reward_1', 'You found Rebels? That''s really interesting. I honestly thought I was sending you out on a wild goose chase. I''ll have to revise my opinion regarding the ''source'' of my information on the Rebels. But I digress. Here is your reward, citizen.'),
('string/en/static_npc/dantooine/lx_466.stf', 57, 'npc_reward_2', 'I''m glad I took the effort to establish contact with those people. They may prove an invaluable resource in rooting out the Rebel scum. The sooner we''ve accomplished that, the sooner I can get stationed somewhere off this forgotten dusty old relic of a planet.'),
('string/en/static_npc/dantooine/lx_466.stf', 58, 'npc_reward_3', 'Your discretion in this matter is much appreciated. I would request that you remain quiet. Do not tell a soul about this and you will live a long and happy life.'),
('string/en/static_npc/dantooine/lx_466.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 60, 'npc_smuggle_2', 'Yuguth thank.'),
('string/en/static_npc/dantooine/lx_466.stf', 61, 'npc_smuggle_3', 'This is my responsibilty now. Go back and tell the sergeant the item was safely delivered.'),
('string/en/static_npc/dantooine/lx_466.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 65, 'npc_work_1', 'Is there a problem with your mission, citizen?'),
('string/en/static_npc/dantooine/lx_466.stf', 66, 'npc_work_2', 'Yes citizen? Was there a problem?'),
('string/en/static_npc/dantooine/lx_466.stf', 67, 'npc_work_3', 'Do you need something, citizen?'),
('string/en/static_npc/dantooine/lx_466.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 71, 'player_1_1', 'I''ll check it out. What do you want me to do?'),
('string/en/static_npc/dantooine/lx_466.stf', 72, 'player_1_2', 'Yes sir.'),
('string/en/static_npc/dantooine/lx_466.stf', 73, 'player_1_3', 'Sounds dangerous. I''ll do it.'),
('string/en/static_npc/dantooine/lx_466.stf', 74, 'player_2_1', 'I''d rather not.'),
('string/en/static_npc/dantooine/lx_466.stf', 75, 'player_2_2', 'No, I''d rather not.'),
('string/en/static_npc/dantooine/lx_466.stf', 76, 'player_2_3', 'No way. This is your problem, you deal with it.'),
('string/en/static_npc/dantooine/lx_466.stf', 77, 'player_3_1', 'Why should I?'),
('string/en/static_npc/dantooine/lx_466.stf', 78, 'player_3_2', 'What is in it for me?'),
('string/en/static_npc/dantooine/lx_466.stf', 79, 'player_3_3', 'This doesn''t sound like my problem. What exactly is going on here and why would I want to put myself in the middle of this mess?'),
('string/en/static_npc/dantooine/lx_466.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 81, 'player_4_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 84, 'player_5_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dantooine/lx_466.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dantooine/lx_466.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dantooine/lx_466.stf', 95, 'player_reset', 'It sounds a little dangerous. On second thought I can''t help you.'),
('string/en/static_npc/dantooine/lx_466.stf', 96, 'player_sorry', 'I''m sorry, what do you need me to do?'),
('string/en/static_npc/dantooine/lx_466.stf', 97, 'return_waypoint_description_1', 'Stormtrooper Sergeant'),
('string/en/static_npc/dantooine/lx_466.stf', 98, 'return_waypoint_description_2', 'Stormtrooper Sergeant'),
('string/en/static_npc/dantooine/lx_466.stf', 99, 'return_waypoint_description_3', 'Stormtrooper Sergeant'),
('string/en/static_npc/dantooine/lx_466.stf', 100, 'return_waypoint_name_1', 'LX-466'),
('string/en/static_npc/dantooine/lx_466.stf', 101, 'return_waypoint_name_2', 'LX-466'),
('string/en/static_npc/dantooine/lx_466.stf', 102, 'return_waypoint_name_3', 'LX-466'),
('string/en/static_npc/dantooine/lx_466.stf', 103, 'waypoint_description_1', 'This is the location of a possible Rebel base. LX-466 wants you to kill any Rebels you find in the area.'),
('string/en/static_npc/dantooine/lx_466.stf', 104, 'waypoint_description_2', 'This is the location of a Dantari Tribesman. LX-466 wants you to deliver a supply of rations to the tribesman.'),
('string/en/static_npc/dantooine/lx_466.stf', 105, 'waypoint_description_3', 'Location of an Imperial courier. LX-466 has asked you to deliver a recording rod to this location.'),
('string/en/static_npc/dantooine/lx_466.stf', 106, 'waypoint_name_1', 'Rebels'),
('string/en/static_npc/dantooine/lx_466.stf', 107, 'waypoint_name_2', 'Dantari Tribesman'),
('string/en/static_npc/dantooine/lx_466.stf', 108, 'waypoint_name_3', 'Courier Rendevous'),
('string/en/static_npc/dantooine/lx_466.stf', 109, 'npc_reset_1', 'Although you''re probably not a Rebel, if you''re not actively assisting the Empire I can no longer guarantee your safety. Proceed at your own risk.'),
('string/en/static_npc/dantooine/lx_466.stf', 110, 'npc_reset_2', 'Although you''re probably not a Rebel, if you''re not actively assisting the Empire I can no longer guarantee your safety. Proceed at your own risk.'),
('string/en/static_npc/dantooine/lx_466.stf', 111, 'npc_reset_3', 'Although you''re probably not a Rebel, if you''re not actively assisting the Empire I can no longer guarantee your safety. Proceed at your own risk.'),
('string/en/static_npc/dantooine/lx_466.stf', 112, 'player_reset_1', 'It sounds a little dangerous. On second thought I can''t help you.'),
('string/en/static_npc/dantooine/lx_466.stf', 113, 'player_reset_3', 'It sounds a little dangerous. On second thought I can''t help you.'),
('string/en/static_npc/dantooine/lx_466.stf', 114, 'player_reset_2', 'It sounds a little dangerous. On second thought I can''t help you.'),
('string/en/static_npc/dantooine/lx_466.stf', 115, 'player_sorry_1', 'I''m sorry, what do you need me to do?'),
('string/en/static_npc/dantooine/lx_466.stf', 116, 'player_sorry_2', 'I''m sorry, what do you need me to do?'),
('string/en/static_npc/dantooine/lx_466.stf', 117, 'player_sorry_3', 'I''m sorry, what do you need me to do?'),
('string/en/static_npc/dantooine/sg_567.stf', 1, 'cant_work', 'Finish up what you''re doing and come back here if you want work. I''ll make it worth your while.'),
('string/en/static_npc/dantooine/sg_567.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 3, 'dontknowyou_2', 'You''re not the person I''m waiting for.'),
('string/en/static_npc/dantooine/sg_567.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 6, 'next', 'It''s too bad you don''t serve under me. I could use a few more like you.'),
('string/en/static_npc/dantooine/sg_567.stf', 7, 'notit_1', 'Ok maybe you''re just not understanding me. I want you to destroy a defective droideka. What is this garbage you''re handing me?'),
('string/en/static_npc/dantooine/sg_567.stf', 8, 'notit_2', 'Hey look, you''ve helped me out in the past, but I don''t want your junk.'),
('string/en/static_npc/dantooine/sg_567.stf', 9, 'notyet', 'No, I''m not sure I trust you enough yet. Maybe if you come back later.'),
('string/en/static_npc/dantooine/sg_567.stf', 10, 'npc_1_1', 'Ok, I''m having a seriously messed up day. A beat up old droideka we''ve been keeping around just ran rampant and escaped the garrison. None of my scout troopers are available to recover the thing. Unless you''re going to volunteer to hunt the thing down I suggest you stay out of my way.'),
('string/en/static_npc/dantooine/sg_567.stf', 11, 'npc_1_2', 'Thanks for taking down that droideka. That was a real load off my mind. You seem interested in what we''re doing out here. I wonder if you''d like to join one of my scouts on a patrol back to the base?'),
('string/en/static_npc/dantooine/sg_567.stf', 12, 'npc_2_1', 'That''s the first good news I''ve had all day, citizen. Ok, let me show you this tactical map. You''ll find that droideka about here. It''s a beat up hunk of junk we''d been using for search and destroy missions on the Rebels, but its circuits just couldn''t handle the stress. Don''t feel the need to be overly gentle in the process of shutting it down.'),
('string/en/static_npc/dantooine/sg_567.stf', 13, 'npc_2_2', 'Alright then. Let me put the coordinates on your datapad. Head out there, meet up with SG-619 and head back this way. If you see anything strange, just remember you''re on a scouting mission. SG-619 will make his report when he gets back.'),
('string/en/static_npc/dantooine/sg_567.stf', 14, 'npc_3_1', 'Is that so? Well guess what: I''m your problem now. Slip up just an inch and I''ll see you regret it.'),
('string/en/static_npc/dantooine/sg_567.stf', 15, 'npc_3_2', 'Not a problem. I thought for a moment you might think it was fun.'),
('string/en/static_npc/dantooine/sg_567.stf', 16, 'npc_4_1', 'It''s good to have friends, but it''s better to have money. Help me and I''ll see you have both.'),
('string/en/static_npc/dantooine/sg_567.stf', 17, 'npc_4_2', 'Sure, why not?'),
('string/en/static_npc/dantooine/sg_567.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 22, 'npc_backtowork_1', 'Ok, it''s really simple... here''s the location of the malfunctioning droideka. Just head out that way and take the old bucket of bolts down. Okay?'),
('string/en/static_npc/dantooine/sg_567.stf', 23, 'npc_backtowork_2', 'Meet up with SG-619 at the location on your datapad and return with him to the garrison.'),
('string/en/static_npc/dantooine/sg_567.stf', 24, 'npc_breech_1', 'Possible entity reform initiated. Identify: true. Proceed with primary order.'),
('string/en/static_npc/dantooine/sg_567.stf', 25, 'npc_breech_2', 'SG-619 checking in... no, they aren''t here yet.'),
('string/en/static_npc/dantooine/sg_567.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 27, 'npc_dropoff_2', 'You''re alright for someone not serving in our unit. Thanks for working with us.'),
('string/en/static_npc/dantooine/sg_567.stf', 28, 'npc_failure_1', 'And you''re giving up? Hopefully some of my scout troopers will be back soon. Best to let the professionals handle this one.'),
('string/en/static_npc/dantooine/sg_567.stf', 29, 'npc_failure_2', 'Well, you weren''t scheduled to be on that patrol, so it''s not like you could be held accountable for this.'),
('string/en/static_npc/dantooine/sg_567.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 36, 'npc_noloc_1', 'Hold on a second, I''ve got some orders to radio out. Get back to me afterwards, alright?'),
('string/en/static_npc/dantooine/sg_567.stf', 37, 'npc_noloc_2', 'Hold on a second, I''ve got some orders to radio out. Get back to me afterwards, alright?'),
('string/en/static_npc/dantooine/sg_567.stf', 38, 'npc_reset', 'Just great. Incompetent and indecisive. Don''t worry, I''ll find someone who can take care of this.'),
('string/en/static_npc/dantooine/sg_567.stf', 39, 'npc_reward_1', 'The old rust bucket didn''t give you too much trouble, did it? Don''t spend all these credits in one place, eh kid?'),
('string/en/static_npc/dantooine/sg_567.stf', 40, 'npc_reward_2', 'Good to see you back. I''ll expect your report soon, SG-619. As for you, citizen... here''s your pay.'),
('string/en/static_npc/dantooine/sg_567.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 44, 'npc_takeme_2', 'Alright, I was wondering when you would get here. You ready to make this patrol?'),
('string/en/static_npc/dantooine/sg_567.stf', 45, 'npc_work_1', 'Did you catch up to that droideka yet?'),
('string/en/static_npc/dantooine/sg_567.stf', 46, 'npc_work_2', 'What is it?'),
('string/en/static_npc/dantooine/sg_567.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 48, 'otherescort_2', 'No, I''m not the person you''re looking for. Maybe you should look around here a little more.'),
('string/en/static_npc/dantooine/sg_567.stf', 49, 'player_1_1', 'I''ll take care of your droideka problems.'),
('string/en/static_npc/dantooine/sg_567.stf', 50, 'player_1_2', 'Sure, that sounds like fun.'),
('string/en/static_npc/dantooine/sg_567.stf', 51, 'player_2_1', 'That''s not my problem.'),
('string/en/static_npc/dantooine/sg_567.stf', 52, 'player_2_2', 'Sorry, I''m too busy for that.'),
('string/en/static_npc/dantooine/sg_567.stf', 53, 'player_3_1', 'I could probably do it. But why would I?'),
('string/en/static_npc/dantooine/sg_567.stf', 54, 'player_3_2', 'Do I get paid for this?'),
('string/en/static_npc/dantooine/sg_567.stf', 55, 'player_4_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 56, 'player_4_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 57, 'player_5_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 58, 'player_5_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/dantooine/sg_567.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dantooine/sg_567.stf', 65, 'player_reset', 'On second thought, this is too much of a problem.'),
('string/en/static_npc/dantooine/sg_567.stf', 66, 'player_sorry', 'I''m sorry, what did you want me to do again?'),
('string/en/static_npc/dantooine/sg_567.stf', 67, 'return_waypoint_description_1', 'Scout trooper commander.'),
('string/en/static_npc/dantooine/sg_567.stf', 68, 'return_waypoint_description_2', 'Scout trooper commander.'),
('string/en/static_npc/dantooine/sg_567.stf', 69, 'return_waypoint_name_1', 'SG-567'),
('string/en/static_npc/dantooine/sg_567.stf', 70, 'return_waypoint_name_2', 'SG-567'),
('string/en/static_npc/dantooine/sg_567.stf', 71, 'waypoint_description_1', 'Find and destroy the malfunctioning old droideka.'),
('string/en/static_npc/dantooine/sg_567.stf', 72, 'waypoint_description_2', 'This is the scheduled location of your rendezvous with the scout trooper.'),
('string/en/static_npc/dantooine/sg_567.stf', 73, 'waypoint_name_1', 'Droideka'),
('string/en/static_npc/dantooine/sg_567.stf', 74, 'waypoint_name_2', 'Scout Trooper Rendezvous'),
('string/en/static_npc/dantooine/sg_567.stf', 75, 'player_reset_1', 'On second thought, this is too much of a problem.'),
('string/en/static_npc/dantooine/sg_567.stf', 76, 'player_sorry_1', 'I''m sorry, what did you want me to do again?'),
('string/en/static_npc/dantooine/sg_567.stf', 77, 'npc_reset_1', 'Just great. Incompetent and indecisive. Don''t worry, I''ll find someone who can take care of this.'),
('string/en/static_npc/dantooine/sg_567.stf', 78, 'player_reset_2', 'On second thought, this is too much of a problem.'),
('string/en/static_npc/dantooine/sg_567.stf', 79, 'player_sorry_2', 'I''m sorry, what did you want me to do again?'),
('string/en/static_npc/dantooine/sg_567.stf', 80, 'npc_reset_2', 'Just great. Incompetent and indecisive. Don''t worry, I''ll find someone who can take care of this.'),
('string/en/static_npc/dathomir/baritha.stf', 1, 'cant_work', 'Ah... your mind is preoccupied... Hahaha... you will be an easy one. You will remember to come back to me when you are not so distracted...'),
('string/en/static_npc/dathomir/baritha.stf', 2, 'dontknowyou_1', 'Look at the mess you made! Get out of here before the reinforcements come.'),
('string/en/static_npc/dathomir/baritha.stf', 3, 'dontknowyou_2', 'Oh, you''re not here to pick me up? Nevermind, then.'),
('string/en/static_npc/dathomir/baritha.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 6, 'next', 'My little pet, I am sad to see you go, yet the Clan Mother wishes to use you for her own ends. Oh... I could have treated you so much better... very well, I release you, and I will let you remember everything, as well.... hahaha.... Now, go see the Mother!'),
('string/en/static_npc/dathomir/baritha.stf', 7, 'notit_1', 'Oh, you are so cute, little one. You wish to shower me in gifts... no, you may keep that one for yourself.'),
('string/en/static_npc/dathomir/baritha.stf', 8, 'notit_2', 'No, pet, I do not want this.'),
('string/en/static_npc/dathomir/baritha.stf', 9, 'notit_3', 'I don''t want this, you stupid little pet! Now go do what I said.'),
('string/en/static_npc/dathomir/baritha.stf', 10, 'notyet', 'Ah... your mind is preoccupied... Hahaha... you will be an easy one. You will remember to come back to me when you are not so distracted...'),
('string/en/static_npc/dathomir/baritha.stf', 11, 'npc_1_1', 'I have heard of your name spoken in whispers among the Sisters. You want to help me, don''t you? You will feel more complete by offering your help, and want to give in to my every desire....'),
('string/en/static_npc/dathomir/baritha.stf', 12, 'npc_1_2', 'I am sickened to hear what has recently happened. It seems the Singing Mountain Sisters know not how to leave well enough alone. Very well, I shall set my pet upon them, won''t I?'),
('string/en/static_npc/dathomir/baritha.stf', 13, 'npc_1_3', 'Oh, the Empire is quite effective indeed, aren''t they? They have already sent someone to replace my ''toy''. Perhaps this one might know how to leave our beautiful planet this time. Pet! Go fetch this one for me!'),
('string/en/static_npc/dathomir/baritha.stf', 14, 'npc_2_1', 'Yes, you are a good little one, aren''t you. You will now go bring to me the newest arrival to the Imperial Prison. He is quite handsome, and I have not had a fun toy to play with for a while. Do not make me wait long...'),
('string/en/static_npc/dathomir/baritha.stf', 15, 'npc_2_2', 'Yes, it pleases you more than anything to do so. Go find the Nightsister who has fallen sway to the Singing Mountain''s silly preachings, then bring her back to me. You may do as you please to the other Sisters there.'),
('string/en/static_npc/dathomir/baritha.stf', 16, 'npc_2_3', 'So willing... you are such a good pet, aren''t you? Now, go bring him here unharmed and maybe I''ll give you a treat... you''d like that, wouldn''t you?'),
('string/en/static_npc/dathomir/baritha.stf', 17, 'npc_3_1', 'Oh... you are stronger than you look. Hmmm... I don''t know whether to be angry or to view you as a challenge. I do so fear if I try any harder, I might shatter your little mind...'),
('string/en/static_npc/dathomir/baritha.stf', 18, 'npc_3_2', 'Oh, broken my compulsion, have you? You think you''re clever, don''t you? Hahaha... you are in the heart of our home, and you think you''re going to walk out of here? Not so clever after all, are you?'),
('string/en/static_npc/dathomir/baritha.stf', 19, 'npc_3_3', 'So. You could have remained happy being my pet, but instead you choose to have it this way... very well then... let me see how you plan on leaving our stronghold, little pet.'),
('string/en/static_npc/dathomir/baritha.stf', 20, 'npc_4_1', 'I am helping you, little one. I am helping you to see that you cannot be happy unless you fulfill my whims... Anything I want, I deserve... I am helping you to see that. You like it when I help you, don''t you? And now you want to help me.'),
('string/en/static_npc/dathomir/baritha.stf', 21, 'npc_4_2', 'The loathsome Singing Sisters have had the audacity to persuade one of our Sisters forsake the use of the Shadow Magics! This will not do. How dare they try to play with the mind of a Nightsister!! Who do they think they are?'),
('string/en/static_npc/dathomir/baritha.stf', 22, 'npc_4_3', 'There is a whole galaxy out there, little pet, which I think you very well know. The Sisters only wish to visit your people and bring them our culture. If they refuse... *sigh*... then we will have to kill them. I know they will be happy with us as their rulers.'),
('string/en/static_npc/dathomir/baritha.stf', 23, 'npc_5_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 24, 'npc_5_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 25, 'npc_5_3', ''),
('string/en/static_npc/dathomir/baritha.stf', 26, 'npc_6_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 27, 'npc_6_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 28, 'npc_6_3', ''),
('string/en/static_npc/dathomir/baritha.stf', 29, 'npc_backtowork_1', 'You will be a good little pet and fetch me the Officer that has arrived at the prison so that I may... entertain myself.'),
('string/en/static_npc/dathomir/baritha.stf', 30, 'npc_backtowork_2', 'You are to fetch that impudent little girl who now claims to be a Singing Sister... and then I will deal with her.'),
('string/en/static_npc/dathomir/baritha.stf', 31, 'npc_backtowork_3', 'Go and fetch this new officer who is replacing the last one. Bring him back to me relatively unharmed.'),
('string/en/static_npc/dathomir/baritha.stf', 32, 'npc_breech_1', 'What''s going on here? Who are you? Guards, protect me!'),
('string/en/static_npc/dathomir/baritha.stf', 33, 'npc_breech_2', 'Oh no!!! I''ve been found out! Please, just let me go!'),
('string/en/static_npc/dathomir/baritha.stf', 34, 'npc_dropoff_1', 'Who is this? Is this one of those Nightsisters? Whatever you want of me, you will not have it!'),
('string/en/static_npc/dathomir/baritha.stf', 35, 'npc_dropoff_2', 'Baritha, I''m so sorry.... I''m so very sorry... I''m sorry.... please don''t hurt me....  pleaaasee......'),
('string/en/static_npc/dathomir/baritha.stf', 36, 'npc_failure_1', 'Bad, bad, bad pet!!! I told you to bring me a toy, and you have failed me. Perhaps I will tire of you and find a new pet.'),
('string/en/static_npc/dathomir/baritha.stf', 37, 'npc_failure_2', 'You didn''t bring her here? This make me very angry... VERY angry. Do you know what I do to my pets when they make me angry?'),
('string/en/static_npc/dathomir/baritha.stf', 38, 'npc_failure_3', 'You stupid little creature! I gave you a simple task, and you couldn''t even do that!'),
('string/en/static_npc/dathomir/baritha.stf', 39, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 40, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 41, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 42, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 43, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 44, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 45, 'npc_noloc_1', 'Let us wait for him to emerge from his sanctuary, shall we?  Come back to me in a little while.'),
('string/en/static_npc/dathomir/baritha.stf', 46, 'npc_noloc_2', 'She will be meeting with her co-conspirators soon. Come back to me and I will tell you when you will want to leave.'),
('string/en/static_npc/dathomir/baritha.stf', 47, 'npc_noloc_3', 'You will wait until he is less guarded. Ask me again in a little while when you should leave to do so.'),
('string/en/static_npc/dathomir/baritha.stf', 48, 'npc_reset', 'Ahhh... a fiesty one.... well, this changes things, doesn''t it? Now think carefully about what I am about to say. Either join me... or die.'),
('string/en/static_npc/dathomir/baritha.stf', 49, 'npc_reward_1', 'Oh, he is a strong looking one, isn''t he? I hope this one will be more of a challenge this time.... you have done well, my precious pet. You may please me again in the future. For now, leave me.'),
('string/en/static_npc/dathomir/baritha.stf', 50, 'npc_reward_2', 'Oh, you brought her back here. Here, let me pat you on the head, precious pet. You did good, didn''t you? Yes, you did good... Now, as for you, Sister, you will learn the price of your mistake. Leave me, pet.'),
('string/en/static_npc/dathomir/baritha.stf', 51, 'npc_reward_3', 'Ah... he has the look of someone important... very good, pet. Now, go to your corner and sit there until Ihave further need of you.'),
('string/en/static_npc/dathomir/baritha.stf', 52, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 53, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 54, 'npc_takeme_1', 'Where are you taking me? I command you, Let me go at once. Oh... you have a weapon. Very well, lead on'),
('string/en/static_npc/dathomir/baritha.stf', 55, 'npc_takeme_2', 'No, please! You don''t know what she''ll do to me!! Please...please, I beg you... if you have any soul, please let me gooooo!!!!!!'),
('string/en/static_npc/dathomir/baritha.stf', 56, 'npc_work_1', 'Yes, little pet?'),
('string/en/static_npc/dathomir/baritha.stf', 57, 'npc_work_2', 'Yes, my precious pet?'),
('string/en/static_npc/dathomir/baritha.stf', 58, 'npc_work_3', 'Yes, my precious pet?'),
('string/en/static_npc/dathomir/baritha.stf', 59, 'otherescort_1', 'I am not the person you are looking for.'),
('string/en/static_npc/dathomir/baritha.stf', 60, 'otherescort_2', 'Nope, I''m not the one you''re looking for. I think the other one''s over there.'),
('string/en/static_npc/dathomir/baritha.stf', 61, 'player_1_1', 'What''s going on he--.......... yesss... Yes, I want to help you.'),
('string/en/static_npc/dathomir/baritha.stf', 62, 'player_1_2', 'Yes, my mistress, I will fulfill your wishes.'),
('string/en/static_npc/dathomir/baritha.stf', 63, 'player_1_3', 'Yes, my dark mistress.'),
('string/en/static_npc/dathomir/baritha.stf', 64, 'player_2_1', 'What''s going on?! No! Get away from me!'),
('string/en/static_npc/dathomir/baritha.stf', 65, 'player_2_2', 'I... must... fight... this.... NOOOO!!!!'),
('string/en/static_npc/dathomir/baritha.stf', 66, 'player_2_3', 'Get... out... of... my... head!!!! NO!!!'),
('string/en/static_npc/dathomir/baritha.stf', 67, 'player_3_1', 'What are you doing to my head?'),
('string/en/static_npc/dathomir/baritha.stf', 68, 'player_3_2', 'What has the enemy done?'),
('string/en/static_npc/dathomir/baritha.stf', 69, 'player_3_3', 'Why does my mistress wish to leave?'),
('string/en/static_npc/dathomir/baritha.stf', 70, 'player_4_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 71, 'player_4_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 72, 'player_4_3', ''),
('string/en/static_npc/dathomir/baritha.stf', 73, 'player_5_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 74, 'player_5_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 75, 'player_5_3', ''),
('string/en/static_npc/dathomir/baritha.stf', 76, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 77, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 78, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 79, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 80, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/baritha.stf', 81, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/baritha.stf', 82, 'player_reset', 'I remember who I am now, Baritha. You have no power over me.'),
('string/en/static_npc/dathomir/baritha.stf', 83, 'player_sorry', 'Mistress, what do you wish of me?'),
('string/en/static_npc/dathomir/baritha.stf', 84, 'return_waypoint_description_1', 'You want to return the Imperial to Baritha. There is nothing more in the world you want.'),
('string/en/static_npc/dathomir/baritha.stf', 85, 'return_waypoint_description_2', 'Your dark mistress wishes you to hurry. You don''t want to keep her waiting, do you?'),
('string/en/static_npc/dathomir/baritha.stf', 86, 'return_waypoint_name_1', 'Baritha'),
('string/en/static_npc/dathomir/baritha.stf', 87, 'return_waypoint_name_2', 'Baritha'),
('string/en/static_npc/dathomir/baritha.stf', 88, 'waypoint_description_1', 'Apparently Baritha has chosen this person to be a ''toy'', whatever she means by that.'),
('string/en/static_npc/dathomir/baritha.stf', 89, 'waypoint_description_2', 'This is where you will find the traitor. Kill her friends then bring her back.'),
('string/en/static_npc/dathomir/baritha.stf', 90, 'waypoint_name_1', 'Newly Arrived Imperial'),
('string/en/static_npc/dathomir/baritha.stf', 91, 'waypoint_name_2', 'Defecting Nightsister'),
('string/en/static_npc/dathomir/baritha.stf', 92, 'npc_reset_1', 'Ahhh... a fiesty one.... well, this changes things, doesn''t it? Now think carefully about what I am about to say. Either join me... or die.'),
('string/en/static_npc/dathomir/baritha.stf', 93, 'npc_reset_2', 'Ahhh... a fiesty one.... well, this changes things, doesn''t it? Now think carefully about what I am about to say. Either join me... or die.'),
('string/en/static_npc/dathomir/baritha.stf', 94, 'npc_reset_3', 'Ahhh... a fiesty one.... well, this changes things, doesn''t it? Now think carefully about what I am about to say. Either join me... or die.'),
('string/en/static_npc/dathomir/baritha.stf', 95, 'npc_reset_4', 'Ahhh... a fiesty one.... well, this changes things, doesn''t it? Now think carefully about what I am about to say. Either join me... or die.'),
('string/en/static_npc/dathomir/baritha.stf', 96, 'player_reset_1', 'I remember who I am now, Baritha. You have no power over me.'),
('string/en/static_npc/dathomir/baritha.stf', 97, 'player_reset_2', 'I remember who I am now, Baritha. You have no power over me.'),
('string/en/static_npc/dathomir/baritha.stf', 98, 'player_reset_3', 'I remember who I am now, Baritha. You have no power over me.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dathomir/baritha.stf', 99, 'player_reset_4', 'I remember who I am now, Baritha. You have no power over me.'),
('string/en/static_npc/dathomir/baritha.stf', 100, 'player_sorry_1', 'Mistress, what do you wish of me?'),
('string/en/static_npc/dathomir/baritha.stf', 101, 'player_sorry_2', 'Mistress, what do you wish of me?'),
('string/en/static_npc/dathomir/baritha.stf', 102, 'player_sorry_3', 'Mistress, what do you wish of me?'),
('string/en/static_npc/dathomir/baritha.stf', 103, 'player_sorry_4', 'Mistress, what do you wish of me?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 1, 'cant_work', 'These walls whisper to me and they tell me that you might be the one. But you must put that to the test when you are not so preoccupied.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 2, 'dontknowyou_1', 'The darkness is rising to embrace all of us. There is no escape...'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 4, 'dontknowyou_3', 'You do not understand the power of the dark side. Leave, fool!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 8, 'next', 'You''ve conquered the darkness. Or have you? Can anyone ever truly do that? Not when the darkness lives inside of us. You can feel it, can''t you? You of all beings should be able to feel it.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 9, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 10, 'notit_2', 'That is not the shadow stone shard. Bring me the shard.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 11, 'notit_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 12, 'notyet', 'Go and speak to Mozo Bondog. He will tell you what you need to do.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 13, 'npc_1_1', 'Has the fool Mozo sent you to solve the mystery of the disappearing inmates? I doubt you can, stranger. Odd, isn''t it, that I call you stranger when I must seem just as strange to you? Stranger, perhaps. But in this place, most things seem strange. About those disappearing inmates... Interested?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 14, 'npc_1_2', 'You''d like to know where the ''place of shadows'' is, wouldn''t you? And what the shadow stone is? Perhaps I know of a place where this exists. But do you truly wish to go there?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 15, 'npc_1_3', 'The shard has revealed the ancient evil behind these wraiths. Do you think you can stop it? Do you dare try?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 16, 'npc_2_1', 'As it turns out, one of them has reappeared. Finding him will undoubtably shed some light on where the others have gone. But you must hurry. Dathomir is not exactly the sort of place one wishes to wander about. There are many horrors, both seen and unseen, that can claim a being''s life... or soul.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 17, 'npc_2_2', 'Very well. Bring me the shadow shard and I may be able to help you solve this mystery. You can only get the shard by shattering the shadow stone. The wraiths will try to stop you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 18, 'npc_2_3', 'Go to these coordinates and face the master of these wraiths. This sinister force is strong with the dark side. It is not likely that you''ll return.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 19, 'npc_3_1', 'I didn''t think you''d be the one to solve this riddle. I''m not sure what made you think you could. Was it the fact that the Force is strong in you? Oh dear, I''ve said too much.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 20, 'npc_3_2', 'Perhaps you are wiser than you look. This affair is beyond your feeble skills.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 21, 'npc_3_3', 'The dark side has a strong influence on the weak-minded. It is perhaps best that you choose not to face this power.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 22, 'npc_4_1', 'As I said, Dathomir is full of strange occurrences. In most cases, the prison cells were still sealed and there was no evidence of a breakout. What do you think this would imply?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 23, 'npc_4_2', 'The whispers told me, of course. I am not without my own skills, stranger. Why do you think I''m here? I was considered far too dangerous to be allowed to remain free, yet no one dared execute me. Isn''t that odd?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 24, 'npc_4_3', 'The shard was a piece of a Sith holocron and it is a Sith that you go to face now. This agent of evil has enslaved many souls on Dathomir. This dark warrior can enslave the minds of others.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 25, 'npc_5_1', 'That is a good conclusion, yet the recording devices show no evidence of any foul play. And there''s the issue of the wraiths.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 26, 'npc_5_2', 'The Emperor, who else? He declared me a threat to the Empire and had me imprisoned here. Don''t you find that amusing? The Emperor declaring me a threat? I chuckle everytime I think of that.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 27, 'npc_5_3', 'Yes, the Sith took possession of their bodies and they were none the wiser. Prison guards would wipe the evidence away and none would remember their actions.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 28, 'npc_6_1', 'The specters of those who have died on Dathomir. And those must surely number in the thousands. Could the wraiths have helped these inmates escape? Locate the lost inmate and you might have your answer. Do you wish to do it?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 29, 'npc_6_2', 'Perhaps because he knew I could one day challenge him for control of the Empire. I was close to finding the key that would have allowed me to do that. But that is another matter...'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 30, 'npc_6_3', 'Yes, I have watched it happen time and again. The Sith wanted my allegiance but I refused to give it. I was too powerful to be controlled like the others so the Sith warrior was making arrangements to have me destroyed. I couldn''t allow this to happen. Shall you go and end this menace once and for all?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 31, 'npc_backtowork_1', 'Do you hear the whispers too? They tell of unspeakable horrors.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 32, 'npc_backtowork_2', 'If you hesitate, you''ll be lost.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 33, 'npc_backtowork_3', 'Waiting will not make this task any easier.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 34, 'npc_breech_1', 'The wraiths are everywhere! Can''t you hear them? Silence them!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 35, 'npc_breech_2', 'silence...'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 36, 'npc_breech_3', 'I have been expecting you. The dark side hungers for you. Come embrace it.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 37, 'npc_dropoff_1', 'There is no refuge! No sanctuary! You should have let me die out there...'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 40, 'npc_failure_1', 'What hope did you have against such an ancient evil? You are nothing compared to its power.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 41, 'npc_failure_2', 'No shard, no secrets revealed. Such a waste.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 42, 'npc_failure_3', 'The darkness will spread from Dathomir to other planets. Perhaps the Emperor will have to become involved.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 43, 'npc_more_1_1', 'The wraiths willed it to be so. Nothing can contend against them. Soon they will spread to other planets.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 45, 'npc_more_1_3', 'I am a phantom from the past that has come to claim the future. Those who do not join me will be destroyed.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 46, 'npc_more_2_1', 'The ghosts of the past. The shadows that move and speak in your mind. Can''t you hear them? Can''t you see them?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 49, 'npc_more_3_1', 'The place of shadows! That is where they come from. And the shadow stone is where they get their power. They will come for all of us! There is no escape!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 52, 'npc_noloc_1', 'The whispers reveal more secrets to me. I must listen closely or the wraiths shall become angry.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 53, 'npc_noloc_2', 'The wraiths are becoming angry with me. I must take a few moments to speak to them. I don''t wish them to view me as their enemy.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 54, 'npc_noloc_3', 'The Sith tries to hide from my sight but I know how to find shadows in the darkness.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 55, 'npc_reset', 'This is beyond you. Go back to the light where all is safe. The dark is no place for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 56, 'npc_reward_1', 'More questions? How could this be? That is the nature of clues. They answer old questions and create new ones. There will always be questions. Claim the reward Mozo has provided for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 57, 'npc_reward_2', 'You have brought me the crystal shard. Excellent. I must study its secrets before I can help you fight the wraiths.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 58, 'npc_reward_3', 'There are many evils in this universe. The Sith are but one of these. I am another. Remember that the light cannot exist without darkness.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 62, 'npc_takeme_1', 'Can you see them? The wraiths? There is no escaping them! They will always be there!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 65, 'npc_work_1', 'Have you found the missing inmate? What secrets await to be revealed?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 66, 'npc_work_2', 'Where is the shard of the shadow stone? I cannot help you if I do not have it.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 67, 'npc_work_3', 'Have you confronted this ancient evil? It will conquer this planet if you fail to stop it.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 68, 'otherescort_1', 'Run! The wraiths are after you!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 77, 'player_3_1', 'Tell me more about the disappearances.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 78, 'player_3_2', 'How do you know where the shadow stone is?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 79, 'player_3_3', 'What is this ancient evil?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 80, 'player_4_1', 'The inmates had help on the inside.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 81, 'player_4_2', 'Who sent you here?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 82, 'player_4_3', 'Is this how the inmates were allowed to escape?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 83, 'player_5_1', 'What are the wraiths?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 84, 'player_5_2', 'Why did the Emperor feel you were a threat?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 85, 'player_5_3', 'You''ve known this all along, haven''t you?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 86, 'player_more_1_1', 'How did you get out of your cell?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 88, 'player_more_1_3', 'Who are you?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 89, 'player_more_2_1', 'What are these wraiths?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 92, 'player_more_3_1', 'Where do these wraiths come from?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 95, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 96, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 97, 'return_waypoint_description_1', 'Escort the inmate back to Dolac Legasi.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 98, 'return_waypoint_description_2', 'Bring the shard back to Dolac Legasi.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 99, 'return_waypoint_description_3', 'Report your success back to Dolac Legasi.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 100, 'return_waypoint_name_1', 'Dolac Legasi''s Location'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 101, 'return_waypoint_name_2', 'Dolac Legasi''s Location'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 102, 'return_waypoint_name_3', 'Dolac Legasi''s Location'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 103, 'waypoint_description_1', 'Locate the escaped inmate.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 104, 'waypoint_description_2', 'Shatter the shadow stone and retrieve the shard.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 105, 'waypoint_description_3', 'Destroy the ancient evil before it spreads throughout the galaxy.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 106, 'waypoint_name_1', 'Escaped Inmate''s Location'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 107, 'waypoint_name_2', 'Shadow Stone''s Location'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 108, 'waypoint_name_3', 'Master of the Wraiths'' Location'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 109, 'npc_reset_1', 'This is beyond you. Go back to the light where all is safe. The dark is no place for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 110, 'npc_reset_2', 'This is beyond you. Go back to the light where all is safe. The dark is no place for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 111, 'npc_reset_3', 'This is beyond you. Go back to the light where all is safe. The dark is no place for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 112, 'npc_reset_4', 'This is beyond you. Go back to the light where all is safe. The dark is no place for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 113, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 114, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 115, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 116, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 117, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 118, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 119, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_dolac_legasi.stf', 120, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 1, 'cant_work', 'You lookin'' for work? No, I guess you''re busy. Well, check with me when you want a job.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 2, 'dontknowyou_1', 'Get away from me or I''ll kill you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 3, 'dontknowyou_2', 'Get out of this area, or you will soon die.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 4, 'dontknowyou_3', 'Get out of this area, or you will soon suffer.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 8, 'next', 'I personally got nothing else for you to do. But you could help us with this disappearing-inmates problem by talking with that prisoner Dolac Legasi. Be careful, he''s a weird one.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 9, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 10, 'notit_2', 'I was expectin'' you to bring me my backpack, the one that stinkin'' mercenary warlord stole. This ain''t it.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 11, 'notit_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 12, 'notyet', 'Away with you... if you are not part of the Empire, then you are of no use to me.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 13, 'npc_1_1', 'Yeah? You lookin'' for work? Great, I got work I''m dyin'' to give you, ''cause if I had to do it myself, I''d be dyin'', get me? Got a lot of escaped prisoners lately. One is -- let''s see -- a "teras kasi master convicted of dangerous insurgent talk." Wanna go kill this escaped master for me?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 14, 'npc_1_2', 'This really stinks! Okay, another prisoner gets out, fine -- this one is, let''s see, "a notorious mercenary warlord from Lok" -- but on the way out, this mighty warlord stole my favorite backpack! I hate that! I want you to find this warlord, do the whole fatality thing you did before, and bring me back that backpack. You up for that?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 15, 'npc_1_3', 'Another escapee. I don''t get it. Whadda they makin'' these doors out of, eggshells? This one is -- lemme see -- "a notorious leader of the Janta clan on Dantooine." I''m seein'' no percentage in goin'' out into that wasteland after this nobody. I want you to take care of it, and I''ll pay you outta my travel and entertainment budget.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 16, 'npc_2_1', 'Great. You just put a few blaster bolts in that wall-kicker and report back here for a nice reward.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 17, 'npc_2_2', 'Okay. Get out there, kill the warlord, and try to avoid damaging my backpack. Keep your priorities straight here, like I do.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 18, 'npc_2_3', 'Great. I''ll wanna hear back from you here, just as soon as you dispose of this little clan leader thing.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 19, 'npc_3_1', 'No? Whaddya mean no? Like I got all day to stand around talking with the likes of you? Get out.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 20, 'npc_3_2', 'You scared of a crummy warlord? Maybe I''m not so hot on your prospects here after all.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 21, 'npc_3_3', 'Then you and I got nothin'' else to talk about. After all I did for you, too!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 22, 'npc_4_1', 'Me? I''m a security chief. I don''t know nothin'' about nobody. I just look at the manifests -- "oh look, another bunch got free and ran out into the wilds" -- and I send people after them. People like you. You interested in this job or not?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 23, 'npc_4_2', 'It''s an old jet model once worn by a great bounty hunter, Viume Loggun. He''s dead now. The jetpack doesn''t actually work, which is kind of directly the reason he died. But it''s a great souvenir, and I want it back from that stinkin'' warlord who stole it.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 24, 'npc_4_3', 'I got no idea who this prisoner is or why he, or possibly she, is here. But the prisoner escaped, and it''s up to you to kill him, or conceivably her, before he (or maybe she) can get offworld. Okay?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 26, 'npc_5_2', 'Beats me. Someone who, it says here, "led a brutal but unsuccessful assault on the Empire''s outpost on Lok, commanded by General Otto." What kind of name is "Otto"? Well, never mind. Anything else you wanna know?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 27, 'npc_5_3', 'You got me! Not only do we have people gettin'' out into the wilds, we got ''em literally disappearing out of the cells and vanishing totally -- I mean like into thin air. It''s a weird planet, Dathomir is, and it makes this place weird just bein'' here.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 29, 'npc_6_2', '"Wraith"? Like a ghost? Boy, you got me. I expect bein'' in this lousy place does somethin'' to the mind. I personally feel like my mind is as finely tuned as ever, but I''m made of sterner stuff than most. Anyway, about that backpack -- will you bring it back?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 30, 'npc_6_3', 'More about "wraiths," huh? We''re hearin'' that from some of the prisoners still inside, not that you''d think there''s any left after all these escapes. The only guy I can think of who''d know something about that is one of our weirder prisoners, Dolac Legasi. If you take out this Janta clan leader for me, I''ll let you talk to him, okay?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 31, 'npc_backtowork_1', 'I don''t got all day to talk, you know? Just go out and kill that escaped teras kasi master.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 32, 'npc_backtowork_2', 'Look, let''s not let that stinkin'' warlord wander around all day with my backpack in tow. Get movin''!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 33, 'npc_backtowork_3', 'I told you plenty already. Get goin'' and take out that Janta clan leader.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 34, 'npc_breech_1', 'You want to take me back to face those wraiths! I won''t let you!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 35, 'npc_breech_2', 'That prison steals the mind! I will kill you before I go back!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 36, 'npc_breech_3', 'The wraiths have stolen my spirit! I shall steal yours -- kill you and eat your heart!'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 40, 'npc_failure_1', 'What, one little teras kasi master was too tough for you? You definitely ain''t cut out for this job. Not that you''d want it, believe me.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 41, 'npc_failure_2', 'You didn''t bring back my backpack? Friend, you''re now officially on my Mess-Up Roster. I tell you this -- that''s a place it''s no good to be.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 42, 'npc_failure_3', 'You didn''t take care of that Janta clan leader? What is the thing with that leader? Is there, like, a spare Imperial walker running interference?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 52, 'npc_noloc_1', 'I''m waitin'' to hear on the current coordinates of that teras kasi master. Details, details. Like I got all day to wait on some probe droid. You check with me in a moment, okay?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 53, 'npc_noloc_2', 'I''m waitin'' on some probe droids to send this warlord''s current location. Check with me in a moment, okay?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 54, 'npc_noloc_3', 'I''m waitin'' on some probe droids to get the right coordinates. That''s my life, waitin'' on probe droids. Brother! Talk to me again soon.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 55, 'npc_reset', 'Yeah, I know what you mean. I pull out of a lot of my jobs too, but they''re always there waiting on me when I get back. Likely this one will be waiting for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 56, 'npc_reward_1', 'Yeah, I know you took out that teras kasi master. We got probe droids everywhere lookin'' at everything. It''s enough to make you spooked, ain''t it? Well, here''s your reward, and check back with me. We always got escaped prisoners around here.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 57, 'npc_reward_2', 'Hey! My backpack! Never thought I''d see it again. Okay, friend, you''re officially my new favorite person. Tell you what, get in touch with me for more work when you want it.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 58, 'npc_reward_3', 'I gotta say, you do good work. Take this reward, and I wanna have you talk to a prisoner who may know somethin'' about all these disappearances. Dolac Legasi, that''s his name. Dolac won''t talk to me -- he hates me, which is fine by me as long as he stays in his cell. Talk to him, see what you can find out about disappearances, take care of it, and I''ll authorize more rewards. Okay?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 65, 'npc_work_1', 'I thought I told you to take out that teras kasi master. What, you''re taking in the atmosphere around here?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 66, 'npc_work_2', 'You got my backpack? No, I see you don''t. Which makes me wonder why you''re botherin'' me.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 67, 'npc_work_3', 'You taken care of that escaped Janta clan leader? Why not? I don''t wanna have to do it myself, lemme tell you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 77, 'player_3_1', 'What do you know about this escaped teras kasi master?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 78, 'player_3_2', 'Why is this backpack important to you?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 79, 'player_3_3', 'What can you tell me about this leader of the Janta clan?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 81, 'player_4_2', 'Who is the mercenary warlord?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 82, 'player_4_3', 'Why do prisoners keep escaping this prison?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 84, 'player_5_2', 'The prisoner I defeated before mentioned a "wraith" in the prison. What is that about?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 85, 'player_5_3', 'The prisoners I defeated before talked about "wraiths" in the prison. What is that about?'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 95, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 96, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 97, 'return_waypoint_description_1', 'The Imperial Prison security chief awaits news of the fate of the escaped teras kasi master.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 98, 'return_waypoint_description_2', 'The Imperial Prison security chief awaits the return of his prized backpack, stolen by an escaped Lok mercenary warlord.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 99, 'return_waypoint_description_3', 'The Imperial Prison security chief awaits a report on the escaped Janta clan leader from Dantooine.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 100, 'return_waypoint_name_1', 'Mozo Bondog'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 101, 'return_waypoint_name_2', 'Mozo Bondog'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 102, 'return_waypoint_name_3', 'Mozo Bondog'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 103, 'waypoint_description_1', 'Imperial Prison security chief Mozo Bondog wants this escaped prisoner killed.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 104, 'waypoint_description_2', 'This warlord from the planet Lok escaped Dathomir Imperial Prison. Security Chief Mozo Bondog wants the backpack that the escapee stole.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 105, 'waypoint_description_3', 'Imperial Prison security chief Mozo Bondog wants this Dantooine escapee killed.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 106, 'waypoint_name_1', 'Teras Kasi Master'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 107, 'waypoint_name_2', 'Mercenary Warlord'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 108, 'waypoint_name_3', 'Janta Clan Leader'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 109, 'npc_reset_1', 'Yeah, I know what you mean. I pull out of a lot of my jobs too, but they''re always there waiting on me when I get back. Likely this one will be waiting for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 110, 'npc_reset_2', 'Yeah, I know what you mean. I pull out of a lot of my jobs too, but they''re always there waiting on me when I get back. Likely this one will be waiting for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 111, 'npc_reset_3', 'Yeah, I know what you mean. I pull out of a lot of my jobs too, but they''re always there waiting on me when I get back. Likely this one will be waiting for you.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 112, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 113, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 114, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 115, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 116, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_imperialprison_mozo_bondog.stf', 117, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 1, 'cant_work', 'I need someone who will dedicate themselves to my assignments. Come back when you are not as occupied.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 3, 'dontknowyou_2', 'Away with you. I am on a mission from my clan.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 6, 'next', 'I have nothing further for you at present.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 7, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 8, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 9, 'notyet', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 10, 'npc_1_1', 'Are you here to help, offworlder? I have little time for you if you''re not. One of my rancors has escaped from its pen. These creatures take years to train and I don''t want to lose all the work that went into this one. Could you help me get it back?'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 11, 'npc_1_2', 'It appears that Singing Mountain Clan has been raiding our territory looking for rancor nests. They are probably also responsible for freeing the rancors from their pens. I need someone to wipe this raiding party out. Could you handle that?'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 12, 'npc_2_1', 'My scouts reported unusual rancor activity in this area. Go and check it out. If you find my rancor, bring it back here.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 13, 'npc_2_2', 'Head to these coordinates. The Singing Mountain Clan''s raiding party should be there. Wipe them all out. This will not be easy so you might wish to bring allies.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 14, 'npc_3_1', 'Why do you waste my time then? Away with you.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 15, 'npc_3_2', 'I believe you are correct. You probably can''t handle a Singing Mountain Clan raiding party.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 16, 'npc_4_1', 'Normally yes, but I''ve sprayed you with a musk that the rancor will recognize. You will be safe and it will follow you back here. Will you do it?'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 17, 'npc_4_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 22, 'npc_backtowork_1', 'Why are you just standing around?'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 23, 'npc_backtowork_2', 'Ogling me won''t help you accomplish this goal.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 24, 'npc_breech_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 25, 'npc_breech_2', 'A stranger approaches, sisters! Be on your guard!'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 28, 'npc_failure_1', 'I''ve just lost years of hard work and training. I must investigate how this rancor escaped from its pen.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 29, 'npc_failure_2', 'I must find a way to dispose of this raiding party. Perhaps I will go personally.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 36, 'npc_noloc_1', 'Let me verify these coordinates with my scouts. Return in a few moments.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 37, 'npc_noloc_2', 'I must verify the coordinates with my scouts. Come back in a few moments.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 38, 'npc_reset', 'I do not have time for those who cannot finish what they begin. If that changes, you may see me again.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 39, 'npc_reward_1', 'You have done well. Take this as compensation for your efforts.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 40, 'npc_reward_2', 'Well done. You are efficient, for an offworlder. Claim your reward.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 45, 'npc_work_1', 'Have you found my rancor? I do not wish our rivals to claim this beast.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 46, 'npc_work_2', 'Have you destroyed that raiding party? They must be stopped.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 53, 'player_3_1', 'Wouldn''t the rancor eat me if I approached it?'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 54, 'player_3_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 55, 'player_4_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 56, 'player_4_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 57, 'player_5_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 58, 'player_5_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 61, 'player_more_2_1', ''),
