('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 65, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 66, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 67, 'return_waypoint_description_1', 'Return the escaped rancor back to Fath Hray.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 68, 'return_waypoint_description_2', 'Report your success back to Fath Hray.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 69, 'return_waypoint_name_1', 'Fath Hray''s Location'),
