('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 74, 'waypoint_name_2', 'Raiding Party''s Location');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 75, 'npc_reset_1', 'I do not have time for those who cannot finish what they begin. If that changes, you may see me again.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 76, 'npc_reset_2', 'I do not have time for those who cannot finish what they begin. If that changes, you may see me again.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 77, 'npc_reset_3', 'I do not have time for those who cannot finish what they begin. If that changes, you may see me again.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 78, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 79, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 80, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 81, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 82, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_nightsisterstronghold_fath_hray.stf', 83, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 1, 'cant_work', 'I''m run ragged around here, so I could really use your help when you''re not so busy.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 2, 'dontknowyou_1', 'You got the wrong person, friend.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 3, 'dontknowyou_2', 'Imperial business. Move along.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 5, 'gotowork_2', 'I expected you to bring me Shibb Nisshil''s Cyber-Rancor Project findings. Don''t you have the datadisc?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 6, 'next', 'I won''t say everything is under control here, but I don''t have anything for you to do right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 7, 'notit_1', 'I was expecting briny bath salts from Tibrin for my boss, Shib Nisshil. This isn''t the salts.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 8, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 9, 'notyet', 'I deal with Imperial personnel only... move along.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 10, 'npc_1_1', 'At last! Running this outpost is so much work, it turns my scales blue. But you''re here to help me, right? Right? I need you to pick up an order of Shibb Nisshil''s briny bath salts that''s gone off-course. Interested?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 11, 'npc_1_2', 'Hello again! I''m desperate again! I can''t find time to get out to the wilderness to drop off a datadisc to a certain other party. Will you kindly do so?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 12, 'npc_2_1', 'Great. The person you meet may seem a little bit, I don''t know -- criminal? But it''s strictly all right. It''s not like Dathomir has laws anyway. Bring me the salts and I''ll pay you for your effort.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 13, 'npc_2_2', 'Here''s the disc. You''re looking for an Imperial Intelligence officer. He probably won''t want to talk much, so just give it to him and get back here.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 14, 'npc_3_1', 'All right then, I''ll just have to send a droid. Hope it doesn''t get lost again.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 15, 'npc_3_2', 'I''m sorry to hear that. I hate offending Imperial Intelligence. Let me know if you reconsider.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 16, 'npc_4_1', 'Shibb Nisshil is an Ishi Tib. So he needs immersion in briny water every day or two to keep his lungs moist. Shibb prefers a particular brine salt that we have to import from his home planet, Tibrin.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 17, 'npc_4_2', 'Well -- I''ll tell you this much, and I hope you''ll be discreet. Imperial Intelligence is getting nasty about Shibb Nisshil''s lack of regular communiques. To keep them happy, I secretly deliver copies of his findings to Intelligence officers at a secret rendezvous in the wilderness. But I can''t make it this time. Will you go?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 18, 'npc_5_1', 'These particular brine salts aren''t on the usual Imperial supply requisition forms, so we have to resort to unauthorized "procurement specialists." These folks sometimes lack updated landing charts, not to mention adequate clearances to get past the blockades. So this latest delivery agent sort of crash-landed in the wilderness.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 20, 'npc_6_1', 'He''s the chief scientist at this outpost. He''s working on a project that -- well, I''m not sure if I''m supposed to talk about that. But he gets really cranky when he doesn''t bathe in his particular briny salts, so will you go get them?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 22, 'npc_backtowork_1', 'I don''t have a lot more information for you. I just need you to bring me those briny bath salts.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 23, 'npc_backtowork_2', 'I don''t know what else to tell you. Just take this disc to the Imperial Intelligence officer at the wilderness rendezvous, then return here.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 24, 'npc_breech_1', 'You! You here to pick up these bath salts?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 25, 'npc_breech_2', 'You there! I''m waiting for those project findings.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 28, 'npc_failure_1', 'You didn''t bring those briny bath salts? Oh no. This will be bad for Shibb Nisshil''s morale.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 29, 'npc_failure_2', 'You didn''t deliver that disc to the Imperial Intelligence officer? Oh dear. They''ll be mad at Shibb Nisshil.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 36, 'npc_noloc_1', 'I''m waiting to hear from our delivery agent on the exact coordinates of the rendezvous. These "procurement specialists" get touchy, you know. Talk to me again in a few moments.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 37, 'npc_noloc_2', 'I''m waiting to hear from Imperial Intelligence about the rendezvous coordinates. They''re usually quite punctual about that, so talk to me again in a few moments.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 38, 'npc_reset', 'You don''t want to run this one little errand? If you had to do everything around here that I do, you''d run screaming from the planet.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 39, 'npc_reward_1', 'The briny bath salts. At last something goes right in this domain of chaos. I''m sure Shibb Nisshil will be glad, the next bath he takes.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 40, 'npc_reward_2', 'Did that officer have anything to say about the project? Oh, really? Well, we''ll see who has more influence on Coruscant, him or Shibb Nisshil. I''ll bet on Shibb every time.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 41, 'npc_smuggle_1', 'I''m never ever gonna tell anyone that I crash-landed my ship just to deliver some stupid -- oh, I can''t even say the words. Here, take ''em. And tell your employer that the next delivery is gonna have a considerable surcharge.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 42, 'npc_smuggle_2', 'I suspect the notion of building an unstoppable army of cyber-rancors as shock troops will find favor in certain parts of Coruscant. But personally, I consider the idea ludicrous, and I shall so inform my superiors.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 45, 'npc_work_1', 'I hope you''ll bring me those briny bath salts that Shibb Nisshil is waiting for.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 46, 'npc_work_2', 'I hope you''re planning to deliver that disc to the Imperial Intelligence officer who''s waiting for it.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 53, 'player_3_1', '"Briny bath salts"?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 54, 'player_3_2', '"Drop off a datadisc to a certain other party"?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 55, 'player_4_1', '"Gone off-course"?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 56, 'player_4_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 57, 'player_5_1', 'Who is Shibb Nisshil?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 58, 'player_5_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 65, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 66, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 67, 'return_waypoint_description_1', 'This assistant to Imperial scientist Shibb Nisshil awaits delivery of Nisshil''s special briny bath salts imported from Tibrin.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 68, 'return_waypoint_description_2', 'This assistant to Imperial scientist Shibb Nisshil waits to hear the disposition of the Cyber-Rancor Project findings she secretly sent to an Imperial Intelligence officer.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 69, 'return_waypoint_name_1', 'Shaki Hamachil'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 70, 'return_waypoint_name_2', 'Shaki Hamachil'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 71, 'waypoint_description_1', 'Research assistant Shaki Hamachil''s superior, scientist Shibb Nisshil, wants the special salts carried from Tibrin to Dathomir by a "procurement specialist."'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 72, 'waypoint_description_2', 'This officer is waiting for the Cyber-Rancor Project research findings sent secretly by Imperial scientist Shibb Nisshil''s assistant, Shaki Hamachil.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 73, 'waypoint_name_1', 'Briny Bath Salts'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 74, 'waypoint_name_2', 'Imperial Intelligence Officer'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 75, 'npc_reset_1', 'You don''t want to run this one little errand? If you had to do everything around here that I do, you''d run screaming from the planet.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 76, 'npc_reset_2', 'You don''t want to run this one little errand? If you had to do everything around here that I do, you''d run screaming from the planet.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 77, 'npc_reset_3', 'You don''t want to run this one little errand? If you had to do everything around here that I do, you''d run screaming from the planet.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 78, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 79, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 80, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 81, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 82, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shaki_hamachil.stf', 83, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 1, 'cant_work', 'You may find it rewarding to meet with me soon, after you are not so busy.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 4, 'dontknowyou_3', 'Bounty Hunter''s Guild business. Don''t get in my way.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 8, 'next', 'All is proceeding according to plan. I no longer need your assistance.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 9, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 10, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 11, 'notit_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 12, 'notyet', 'My time is valuable and you, obviously, are not worthy of it. Only a servant of the Empire will be of any use to me.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 13, 'npc_1_1', 'Ahh -- you are here to help my Cyber-Rancor project? To augment the Empire''s forces with an unstoppable legion of mechano-organic monstrosities? How good. I have located a minor specimen in the wild. If you kill this rancor, I shall reward you and assign you further work.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 14, 'npc_1_2', 'Ah, you again. A pack of thieves has stolen one of my valuable research animals, a rancor of unusual genetic heritage. I urge you to pursue the thieves, kill them, and return the rancor here safely.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 15, 'npc_1_3', 'Oh, dear. I understand that the Ithorian do-gooder naturalist, Wallaw somebody, has actually hired a bounty hunter to kill me. What a nuisance. Can you dispose of this bounty hunter and his team for me?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 16, 'npc_2_1', 'Very well. The specimen is evidently old and somewhat deformed, but may still present a challenge. Be wary.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 17, 'npc_2_2', 'Good. Assemble your team and move quickly. Return the rancor here -- it should follow you tamely.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 18, 'npc_2_3', 'Good. I shall reward you upon your return here.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 19, 'npc_3_1', 'Then waste no more of my time, imbecile.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 20, 'npc_3_2', 'Then bother me no more.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 21, 'npc_3_3', 'After your previous aid to the cause of science, I am disappointed.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 22, 'npc_4_1', 'Genetic material, you buffoon! I shall send out a bioengineer team to secure the slain rancor''s genetic stock for later cloning and mechanization. Soon every rancor on Dathomir may lend its genes to my plan. Will you destroy this single specimen?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 23, 'npc_4_2', 'Regrettably, some Ithorian do-gooder naturalist at the Trade Outpost has taken it into his malformed head to obstruct my work. Claims it would depopulate Dathomir of rancors -- as though that were a bad thing. He hired these thieves. Will you return the test rancor here and ensure his silly goals remain unmet?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 24, 'npc_4_3', 'I''d -- I would prefer not to involve my superiors in this embarrassing little fracas. I fear a certain loss of reputation and consequent budget reductions. Really, I''m sure an agent with your capacities can handle one bounty hunter and a few hired terrorists. Will you?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 26, 'npc_5_2', 'My team implanted a control chip in the creature''s brain, rendering it docile. After you destroy its captors, simply speak to it in a firm voice and it will follow you blindly. Return it here.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 29, 'npc_6_2', 'My probe droids show four individuals, apparently fairly well-armed. You may need a small strike team to dispatch them. Will you do it?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 31, 'npc_backtowork_1', 'I have told you everything necessary. You must destroy the rancor specimen to secure my approval.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 32, 'npc_backtowork_2', 'I have told you everything pertinent. Rescue my valuable test rancor from those thieves.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 33, 'npc_backtowork_3', 'There is nothing more to explain. Simply stop that bounty hunter so I can return to my research with a clear mind.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 34, 'npc_breech_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 35, 'npc_breech_2', 'You''re not here for that Rancor are you?  Hah!  We already "disposed" of that!  Now it''s your turn!'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 36, 'npc_breech_3', 'Enemy sighted. Fire at will.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 40, 'npc_failure_1', 'You did not destroy that single rancor specimen? I very much fear I have no work for someone of such mean qualifications.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 41, 'npc_failure_2', 'You did not rescue my test rancor? This is a blow to science.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 42, 'npc_failure_3', 'Dear, dear. I suppose I shall have to alert my superiors about this bounty hunter. What a nuisance.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 52, 'npc_noloc_1', 'Ah, one moment. I''m receiving a report of interesting experimental results. Talk to me again shortly.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 53, 'npc_noloc_2', 'Drat. My probe droid has malfunctioned. When its repair circuits activate, I shall have the rancor''s coordinates. Talk to me again shortly.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 54, 'npc_noloc_3', 'I am awaiting a report from my probe droid on the bounty hunter''s whereabouts. Then I shall have coordinates for you. Talk to me shortly.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 55, 'npc_reset', 'I have little patience with quitters. Still, I am short-handed, so stop by again when you feel ready.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 56, 'npc_reward_1', 'My probe droids relayed your efficient dispatch of the creature. I reward you appropriately, and desire you to contact me again for further assignments.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 57, 'npc_reward_2', 'Ah, that''s too bad.  They killed it, eh?  Well you did your job well enough anyway.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 58, 'npc_reward_3', 'The bounty hunter is dead? A relief. Now I can return to breeding my army of cyber-rancors. Oh, you''ll want a reward, I suppose? Here.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 65, 'npc_work_1', 'I expect you to destroy that rancor specimen. I would have hoped you''d be on your way already.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 66, 'npc_work_2', 'I expect you to rescue my valuable test rancor from those thieves. What''s keeping you?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 67, 'npc_work_3', 'I certainly hope you can dispose of that nuisance bounty hunter before long.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 77, 'player_3_1', 'Why do you want me to kill this rancor? How can you use a dead one?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 78, 'player_3_2', 'Who hired these thieves to take the test rancor from you?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 79, 'player_3_3', 'Why not get the Empire to cancel the bounty hunter''s contract, or just kill the hunter for you?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 81, 'player_4_2', 'How, exactly, do I rescue a rancor?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 84, 'player_5_2', 'How strong is the team that kidnapped your rancor?'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 95, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 96, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 97, 'return_waypoint_description_1', 'This Imperial scientist awaits a report of the destruction of the gnarled rancor, so that he can harvest its genetic material for his planned army of cyber-rancors.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 98, 'return_waypoint_description_2', 'This Imperial scientist awaits the safe return of his stolen test rancor, or information about what happened.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 99, 'return_waypoint_description_3', 'This Imperial scientist awaits news of the bounty hunter hired to terminate him and his cyber-rancor research program.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 100, 'return_waypoint_name_1', 'Shibb Nisshil'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 101, 'return_waypoint_name_2', 'Shibb Nisshil'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 102, 'return_waypoint_name_3', 'Shibb Nisshil'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 103, 'waypoint_description_1', 'Imperial scientist Shibb Nisshil wants this rancor destroyed so he can harvest its genetic material for his planned army of cyber-rancors.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 104, 'waypoint_description_2', 'Thieves have taken Imperial scientist Shibb Nisshil''s mutated rancor. He wants the thieves killed and the rancor returned safely to him.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 105, 'waypoint_description_3', 'Imperial scientist Shibb Nisshil wants to stop this bounty hunter, who was hired by an Ithorian naturalist to terminate Nisshil and his cyber-rancor experiments.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 106, 'waypoint_name_1', 'Gnarled Rancor'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 107, 'waypoint_name_2', 'Test Rancor'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 108, 'waypoint_name_3', 'Bounty Hunter'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 109, 'npc_reset_1', 'I have little patience with quitters. Still, I am short-handed, so stop by again when you feel ready.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 110, 'npc_reset_2', 'I have little patience with quitters. Still, I am short-handed, so stop by again when you feel ready.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 111, 'npc_reset_3', 'I have little patience with quitters. Still, I am short-handed, so stop by again when you feel ready.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 112, 'npc_reset_4', 'I have little patience with quitters. Still, I am short-handed, so stop by again when you feel ready.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 113, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 114, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 115, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 116, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 117, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 118, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 119, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_researchoutpost_shibb_nisshil.stf', 120, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 1, 'cant_work', 'You are far too busy with other matters. Please come back when you are not so busy.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 2, 'dontknowyou_1', 'I cannot speak to you now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 3, 'dontknowyou_2', 'Go away, offworlder! This matter does not concern you!'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 6, 'next', 'There is nothing more for you to do.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 7, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 8, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 9, 'notyet', 'Go and speak to Vhaunda. She must determine your worthiness before I can assign you missions.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 10, 'npc_1_1', 'Greetings, offworlder, I am Izaryx, rancor trainer of the Singing Mountain Clan. Recently, our rivals, the Nightsisters, have been attacking our scouts. They are convinced that we wish to steal their trained rancors. One of my scouts just sent a distress signal and I have no remaining warriors to send to her rescue. Can you help her out of her predicament?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 11, 'npc_1_2', 'Fath Hray''s hatred has once again brought suffering to my sisters. She has sent a war party to attack some of our settlements. Rumor has it that this war party is attempting to infect our rancors with something called the Berserker Virus. I need you to stop these raiders before this can happen. Can you do it?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 12, 'npc_2_1', 'Hurry to these coordinates and save her from becoming another casualty of war. If you can save her, escort her back here.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 13, 'npc_2_2', 'Here are the coordinates. You should bring allies as these Nightsister warriors are quite formidable. My scout who has been tracking this war party will aid you if she can. Good luck.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 14, 'npc_3_1', 'I had heard that offworlders were cowards but I did not wish to believe it. Perhaps I should revisit that issue.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 15, 'npc_3_2', 'I understand. This is a personal matter between myself and Fath Hray.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 16, 'npc_4_1', 'Her patrol had fallen victim to a Nightsister ambush. Please hurry and you may be able to save her.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 17, 'npc_4_2', 'I was once a member of the Nightsister Clan but I could not accept Gethzerion''s evil. I rejected them and joined the Singing Mountain Clan. I was Fath Hray''s apprentice and she felt personally betrayed.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 19, 'npc_5_2', 'I am not sure but I understand it makes domesticated animals impossible to control. I can''t allow our rancors to become infected with it.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 21, 'npc_6_2', 'I do not think so, but I have no way of knowing for certain. This mission is filled with risk. Do you wish to tackle it?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 22, 'npc_backtowork_1', 'You should hurry. I don''t know how much longer my scout can hold out.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 23, 'npc_backtowork_2', 'Why do you delay? Do you wish to reconsider?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 24, 'npc_breech_1', 'You will not defeat a member of the Singing Mountain Clan! Have at you, Nightsisters!'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 25, 'npc_breech_2', 'Kill these offworlders, my sisters! Slay them all!'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 26, 'npc_dropoff_1', 'My thanks, offworlder. You are an ally of the Singing Mountain Clan.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 28, 'npc_failure_1', 'The Nightsisters will pay for their treachery. Fath Hray''s vengeance comes at too high a price.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 29, 'npc_failure_2', 'I shall have to deal with Fath Hray myself. I wished it did not have to come to this but now there is no choice.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 30, 'npc_more_1_1', 'Fath Hray, still feeling betrayed over Izaryx''s defection, wants to hurt Singing Mountain however she can and so attempts to start a war.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 36, 'npc_noloc_1', 'I must verify the coordinates sent in the distress call.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 37, 'npc_noloc_2', 'Allow me to verify the war party''s latest location. Come back in a few moments.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 38, 'npc_reset', 'I will find someone else to accomplish this mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 39, 'npc_reward_1', 'You have my thanks, offworlder. Please accept this as payment for your courageous deeds.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 40, 'npc_reward_2', 'You are brave and your skills are magnificent. Please accept this reward.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 43, 'npc_takeme_1', 'It is a good thing you arrived when you did. Please take me back to Izaryx, for I have much to report.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 45, 'npc_work_1', 'Did you save my scout from the Nightsisters?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 46, 'npc_work_2', 'Have you stopped that war party yet? We must now allow the Berserker Virus to spread on Dathomir.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 47, 'otherescort_1', 'I am not waiting for you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 53, 'player_3_1', 'Why did your scout send a distress signal?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 54, 'player_3_2', 'Why does Fath Hray hate you so much?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 55, 'player_4_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 56, 'player_4_2', 'What is the Berserker Virus?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 57, 'player_5_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 58, 'player_5_2', 'Does this virus affect sentients?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 59, 'player_more_1_1', 'What is happening?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 65, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 66, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 67, 'return_waypoint_description_1', 'Escort the scout back to Izaryx.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 68, 'return_waypoint_description_2', 'Report the news back to Izaryx.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 69, 'return_waypoint_name_1', 'Izaryx''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 70, 'return_waypoint_name_2', 'Izaryx''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 71, 'waypoint_description_1', 'Rescue the scout from the Nightsister raiding party.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 72, 'waypoint_description_2', 'Stop the Nightsister war party from spreading the Berserker Virus.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 73, 'waypoint_name_1', 'Singing Mountain Scout''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 74, 'waypoint_name_2', 'Nightsister War Party''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 75, 'npc_reset_1', 'I will find someone else to accomplish this mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 76, 'npc_reset_2', 'I will find someone else to accomplish this mission.'),
