('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 81, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 82, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_izaryx.stf', 83, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 1, 'cant_work', 'When you get some free time, please come and speak to me again. I may have tasks for you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 2, 'dontknowyou_1', 'I''m a bit busy, pal.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 3, 'dontknowyou_2', 'Can''t help you, friend.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 6, 'next', 'You have served me well, offworlder. Visit me from time to time and perhaps I''ll have more tasks for you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 7, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 8, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 9, 'notyet', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 10, 'npc_1_1', 'Greetings, offworlder. I am known among my sisters as Zideera. I am apprenticed to Huntress Vhaunda. Recently my mistress has become cross with me due to my growing interest in offworlders, particularly of the male variety. I have explained that I am only curious for they seem quite strange to me - strange but not unappealing. There is one in particular who has fascinated me and now finds himself in need of aid. I cannot aid him myself - my mistress would punish me harshly. Could you help him?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 11, 'npc_1_2', 'My pirate friend has informed me that one of his crewmates has contacted him. It seems my pirate friend needs to return to his people to continue plying his trade. Will you bring my pirate friend''s crewman back here? It will be safer for them if they can travel back to his ship together.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 12, 'npc_2_1', 'Excellent. I believe his ship was shot down by an Imperial patrol. One of my scout sisters gave me the coordinates of the crash. Could you go there and bring this male back here safely?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 13, 'npc_2_2', 'Excellent. Please hurry. I hear that the Nightsisters have sent a raiding party to investigate the ship''s landing. They tend to kill offworlders they encounter in the wilds.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 14, 'npc_3_1', 'How sad. I would hate to lose this fascinating male. He has proven a most interesting specimen to study.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 15, 'npc_3_2', 'And just when I was beginning to like you. What a shame.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 16, 'npc_4_1', 'I believe you would refer to him as a pirate. He preys upon the weak members of your kind, which is good since this would serve to cull your herd. Correct?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 17, 'npc_4_2', 'My mistress does not know he''s still here. I''m hiding him, you see. It would be bad for both of us if she were to discover him.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 19, 'npc_5_2', 'I''ll tell her they arrived together and wish to trade with our clan.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 21, 'npc_6_2', 'Where males are concerned, it''s quite necessary. She does not understand my fascination with them and I cannot explain it. I''ve asked my pirate friend to show her but he''s convinced that''s not a wise idea.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 22, 'npc_backtowork_1', 'I have nothing further to tell you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 23, 'npc_backtowork_2', 'Why do you delay? Please find the shipmate.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 24, 'npc_breech_1', 'Over here! Get these blasted creatures off me!'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 25, 'npc_breech_2', 'Over here! Are you the one that will take me to my captain?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 26, 'npc_dropoff_1', 'I owe you one, friend. I hope I get a chance to repay you someday.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 27, 'npc_dropoff_2', 'Much obliged, friend. If we ever cross paths again, I hope to remember your kindness.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 28, 'npc_failure_1', 'Where will I find another male as fascinating as that pirate? His greeting customs were most delightful.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 29, 'npc_failure_2', 'Now I shall have to continue to hide my pirate friend in my hut. I suppose that is not entirely bad.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 30, 'npc_more_1_1', 'Let''s just say that I know how to treat the ladies right. Learn to do that and you''ll go far in this galaxy.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 36, 'npc_noloc_1', 'I must verify the pirate''s location. Come back in a few moments.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 37, 'npc_noloc_2', 'One moment while I verify the shipmate''s location with my pirate friend.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 38, 'npc_reset', 'Come back when you can finish what you begin.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 39, 'npc_reward_1', 'I thank you for bringing him back to me. Please keep this to yourself and accept this as a reward.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 40, 'npc_reward_2', 'Thank you for your help. Please accept this as payment for your services.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 43, 'npc_takeme_1', 'A good thing you came when you did, friend. If your goal is to bring me back to that lovely lass Zideera, then lead on.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 44, 'npc_takeme_2', 'Let''s get a move on, friend. The noises in this place are enough to send shivers up my spine.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 45, 'npc_work_1', 'Did you find my missing pirate?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 46, 'npc_work_2', 'Did you find my pirate friend''s shipmate?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 47, 'otherescort_1', 'I''m not the fellow you''re looking for.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 48, 'otherescort_2', 'You aren''t looking for me, stranger.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 53, 'player_3_1', 'Who is this offworlder?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 54, 'player_3_2', 'Why doesn''t your pirate friend simply go out to meet his shipmate?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 55, 'player_4_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 56, 'player_4_2', 'Won''t she discover him when the shipmate arrives?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 57, 'player_5_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 58, 'player_5_2', 'You''ve gotten good at lying to your mistress, haven''t you?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 59, 'player_more_1_1', 'Why is Zideera so taken with you?'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 62, 'player_more_2_2', ''),
