('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 66, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 67, 'return_waypoint_description_1', 'Escort the pirate back to Zideera.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 68, 'return_waypoint_description_2', 'Escort the shipmate back to Zideera.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 69, 'return_waypoint_name_1', 'Zideera''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 70, 'return_waypoint_name_2', 'Zideera''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 71, 'waypoint_description_1', 'Rescue the stranded pirate before he''s eaten by rancors.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 72, 'waypoint_description_2', 'Find the shipmate before the Nightsisters do.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 73, 'waypoint_name_1', 'Stranded Pirate''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 74, 'waypoint_name_2', 'Pirate Shipmate''s Location'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 75, 'npc_reset_1', 'Come back when you can finish what you begin.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 76, 'npc_reset_2', 'Come back when you can finish what you begin.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 77, 'npc_reset_3', 'Come back when you can finish what you begin.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 78, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 79, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 80, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 81, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 82, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainclanstronghold_zideera.stf', 83, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 1, 'cant_work', 'The Singing Mountain Clan is in dire need of aid. When you are not so busy, come back and help us.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 2, 'dontknowyou_1', 'You''ve picked a dangerous place to be. I recommend finding a safe spot to view the carnage if you value your own skin.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 3, 'dontknowyou_2', 'You gaze into the face of your doom. Be gone from this place, lest it steal the life from your frail body.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 4, 'dontknowyou_3', 'Leave, my friend, before evil consumes you. These witches have no love for intruders.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 5, 'dontknowyou_4', 'Do you seek the blackest pits of despair? Then look no further. But if you value your lives, flee as though a thousand nightmares pursued you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 6, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 10, 'next', 'It shall not be forgotten, how you have aided the Singing Mountain Clan. We have nothing further to ask of you at this time.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 11, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 12, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 13, 'notit_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 14, 'notit_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 15, 'notyet', 'If you wish to earn my trust, first speak with Vurlene.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 16, 'npc_1_1', 'Welcome to the Singing Mountain Clan Stronghold. Vurlene informs me you are trustworthy. Have you come to aid us in our fight against Gethzerion? She attacks us constantly though we are no threat to her. Now one of our trusted servants has betrayed us. There is no love lost between our people but our need is great. Will you help us, stranger? '),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 17, 'npc_1_2', 'It''s strange and yet not entirely unpleasant to see your face at Singing Mountain Stronghold in these harsh times. Perhaps you will be willing to aid us in the recovery of a stolen item if we have not imposed on your good nature too much already. What say you?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 18, 'npc_1_3', 'It seems we are constantly seeking your aid in our struggle against the Nightsisters. We would not pester you so frequently if they would just leave us alone. Now they have kidnapped one of our youngest. Will you help us find her?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 19, 'npc_1_4', 'I have a great request to make of you, my friend. It may be beyond your abilities but I will ask anyway. A Nightsister named Morathax has orchestrated all our recent troubles. It would be best for the Singing Mountain Clan if she were removed lest she chip away at us until there is nothing left. Do you think you can handle the job?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 20, 'npc_2_1', 'Compassion is a welcome change to this world. Aldiae, my most trusted servant, has betrayed us and gone to tell Gethzerion of all our weaknesses. Please bring my traitorous servant back here before our vulnerabilities are revealed to those who loathe us.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 21, 'npc_2_2', 'I was right about you. You have an aura of altruism about you that shines through your gruff exterior. If you can find a Nightsister named Vhuransa, we believe she is the one who has stolen our sacred lore. We would be grateful were you to return it to us.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 22, 'npc_2_3', 'Seek out Jhuryx. The Nightsisters took her and it will be no small task to rescue her from their clutches. Take the greatest of care with your preparations. '),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 23, 'npc_2_4', 'It is bold of you to attempt this but have a care: Morathax will be well guarded by those loyal to her and will not be a quick victory. I caution you to bring friends you trust to aid you in this endeavor. It would sadden us to lose our outsider friend to one such as she.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 24, 'npc_3_1', 'Life must have treated you very cruelly for you to be this callous. Perhaps it will make you strong, but I wouldn''t count on it.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 25, 'npc_3_2', 'Perhaps it seems a small thing to you but to us it is the sum of our history.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 26, 'npc_3_3', 'A hard thing, to deny us the return of our own.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 27, 'npc_3_4', 'It was too much to hope for. Now if you will excuse me, I must find a way to secure the safety of my clan.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 28, 'npc_4_1', 'If simple compassion for an oppressed people will not motivate you then I fail to know what will. We have little enough to offer you but will give you what we can. All I can do is ask. What say you, will you help?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 29, 'npc_4_2', 'An item very precious to the Singing Mountain Clan. It is a compilation of the wisdom of our clan. All the mystical knowledge we have collected over the centuries has been stolen form us. Will you aid us in its recovery?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 30, 'npc_4_3', 'So they can turn her to the path of darkness thus strengthening their clan. We just want our lost sister back. Will you help us?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 31, 'npc_4_4', 'A disciple of Gethzerion who seems to come from the same mould. The last thing we need is both of them trying to destroy us. Can we rely on your help?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 40, 'npc_backtowork_1', 'You have something on your mind perhaps?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 41, 'npc_backtowork_2', 'I''ve told you what I can. The rest is up to you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 42, 'npc_backtowork_3', 'Will you rescue our lost sister or have you reconsidered your answer?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 43, 'npc_backtowork_4', 'Have you decided this task is beyond your abilities?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 44, 'npc_breech_1', 'Get away from me.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 45, 'npc_breech_2', 'You think you can take anything from me? '),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 46, 'npc_breech_3', 'At last my sisters send aid.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 47, 'npc_breech_4', 'Now you will experience the power of the dark side.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 48, 'npc_dropoff_1', 'Perhaps they''ll be merciful. They''ve always had a soft streak here. '),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 49, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 50, 'npc_dropoff_3', 'Whatever your reasons for saving me, outsider, I thank you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 52, 'npc_failure_1', 'Things look bleak but perhaps we may yet weather this storm.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 53, 'npc_failure_2', 'This bodes ill for my sisters and I. We must find a way to recover this tome before she brings it to the Nightsisters or all is lost.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 54, 'npc_failure_3', 'We will weep for our lost sister, for when next we see her it will be in battle against one another.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 55, 'npc_failure_4', 'She will be on her guard now and we must be doubly on ours.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 68, 'npc_noloc_1', 'Perhaps my sisters and I can divine a location for you to find what we seek. Give me a bit of privacy that we may confer.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 69, 'npc_noloc_2', 'This is an inauspicious moment for you to begin your journey. Be patient and return to me soon. '),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 70, 'npc_noloc_3', 'My sisters and I will try and divine her current whereabouts. Give me a few minutes of privacy that we may pool our abilities and then return to me.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 71, 'npc_noloc_4', 'My sisters and I must merge our talents to divine Morathax''s location. Give me some privacy and I shall see it done. Return to me shortly.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 72, 'npc_reset', 'Perhaps you are not yet ready for our tasks. Return to us when you feel you are capable of rendering us aid.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 73, 'npc_reward_1', 'We of the Singing Mountain Clan do not easily come to trust outsiders. Perhaps you will teach us the error of this.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 74, 'npc_reward_2', 'Once again you demonstrate to me that we can look for allies outside our own clan. Thank you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 75, 'npc_reward_3', 'If ever there was an outsider that should have been born one of us, surely it must be you.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 76, 'npc_reward_4', 'You are a true friend to the Singing Mountain Clan. Perhaps we shall take a less dim view of strangers henceforth.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 77, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 81, 'npc_takeme_1', 'I should have known better than to go. But it was too good an offer to turn down.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 82, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 83, 'npc_takeme_3', 'Take me home.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 85, 'npc_work_1', 'Have you managed to recapture my traitorous servant yet?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 86, 'npc_work_2', 'Have you caught up with Vhuransa yet? '),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 87, 'npc_work_3', 'Please hurry and find our lost sister. Time is of the essence.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 88, 'npc_work_4', 'Be careful when you face this one, my friend. She is both clever and powerful.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 89, 'otherescort_1', 'You''ve picked a dangerous place to be. I recommend finding a safe spot to view the carnage if you value your own skin.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 90, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 91, 'otherescort_3', 'Leave, my friend, before evil consumes you. These witches have no love for intruders.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 93, 'player_1_1', 'Yes'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 94, 'player_1_2', 'Yes'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 95, 'player_1_3', 'Yes'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 96, 'player_1_4', 'Yes'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 97, 'player_2_1', 'No'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 98, 'player_2_2', 'No'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 99, 'player_2_3', 'No'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 100, 'player_2_4', 'No'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 101, 'player_3_1', 'Why should I help your clan?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 102, 'player_3_2', 'What was stolen from you?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 103, 'player_3_3', 'Why would they kidnap one of you?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 104, 'player_3_4', 'Who is this Morathax?'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 105, 'player_4_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 106, 'player_4_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 107, 'player_4_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 108, 'player_4_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 109, 'player_5_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 110, 'player_5_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 111, 'player_5_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 112, 'player_5_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 113, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 114, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 115, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 116, 'player_more_1_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 117, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 118, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 119, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 120, 'player_more_2_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 121, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 122, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 123, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 124, 'player_more_3_4', ''),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 125, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 126, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 127, 'return_waypoint_description_1', 'Return to Aujante K''lee with your prisoner.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 128, 'return_waypoint_description_2', 'Return the Stolen item to Aujante K''lee'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 129, 'return_waypoint_description_3', 'Escort Jhuryx back to Aujante K''lee safely.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 130, 'return_waypoint_description_4', 'Return to Aujante K''lee and inform her of your victory.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 131, 'return_waypoint_name_1', 'Aujante K''lee'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 132, 'return_waypoint_name_2', 'Aujante K''lee'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 133, 'return_waypoint_name_3', 'Aujante K''lee'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 134, 'return_waypoint_name_4', 'Aujante K''lee'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 135, 'waypoint_description_1', 'Find and capture Aldiae'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 136, 'waypoint_description_2', 'Find Vhuransa and defeat her to retrieve what was stolen.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 137, 'waypoint_description_3', 'Find and rescue Jhuryx from her captors'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 138, 'waypoint_description_4', 'Find and destroy Morathax'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 139, 'waypoint_name_1', 'Aldiae''s location'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 140, 'waypoint_name_2', 'Vhuransa''a location'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 141, 'waypoint_name_3', 'Jhuryx''s location'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 142, 'waypoint_name_4', 'Morathax''s location'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 143, 'npc_reset_1', 'Perhaps you are not yet ready for our tasks. Return to us when you feel you are capable of rendering us aid.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 144, 'npc_reset_2', 'Perhaps you are not yet ready for our tasks. Return to us when you feel you are capable of rendering us aid.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 145, 'npc_reset_3', 'Perhaps you are not yet ready for our tasks. Return to us when you feel you are capable of rendering us aid.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 146, 'npc_reset_4', 'Perhaps you are not yet ready for our tasks. Return to us when you feel you are capable of rendering us aid.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 147, 'npc_reset_5', 'Perhaps you are not yet ready for our tasks. Return to us when you feel you are capable of rendering us aid.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 148, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 149, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 150, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 151, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 152, 'player_reset_5', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 153, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 154, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 155, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 156, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_singingmountainstronghold_aujante_klee.stf', 157, 'player_sorry_5', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 1, 'cant_work', 'You seem to stay quite busy. I like that. When you have the time to take on some more work, I think we could do business together.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 2, 'dontknowyou_1', 'Get away from me if you value your own skin. I have no use for outsiders.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 3, 'dontknowyou_2', 'This isn''t the place for you. I''m waiting for another.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 4, 'dontknowyou_3', 'You are not the one I seek. Remove yourself from my presence and you may yet live.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 6, 'gotowork_2', 'What have you done with the lightsaber? If that swindler is up to something he''ll spend more years dying than he has yet lived.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 8, 'next', 'I think it would be for the best if we severed our association for a short time. I''m still trying to make a deal to get offworld and we wouldn''t want people to get the wrong idea about us. '),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 9, 'notit_1', 'The lightsaber would be that handle shaped thing with a stud on it. Have another look why don''t you.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 10, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 11, 'notit_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 12, 'notyet', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 13, 'npc_1_1', 'I think you and I are going to be great friends. We share a certain flair for business and a way with people, don''t you think? Between my brains and your capacity for mayhem, I think we''ll go far. You do have a capacity for mayhem I hope. You''re certainly on the wrong world if you don''t. You could show me those skills by recovering an item of mine that was wrongfully taken from me. I''ll even pay you. What do you say?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 14, 'npc_1_2', 'My dear friend! Back to see me in this, my darkest hour? I knew you''d never believe those foul rumors people were spreading about me. It''s times like this that teach you who your friends are. I only wish I had someone to help me clear up this mess. Wait -- here''s a thought. People haven''t found a reason to distrust you yet. Can you help me?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 15, 'npc_1_3', 'You''ve got to help me. The Nightsisters realized I sold them a phony copy of their lightsaber and now they''ve sent one of their worst after me to kill me. Why doesn''t anybody ever have a sense of humor about these matters? Please, tell me you''ll help me!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 16, 'npc_2_1', 'All you need to do is find the Nightsister Gruthashaal and convince her to give up my lightsaber. I hope she hasn''t figured out how to get the blamed thing running. The Nightsisters are notoriously uncooperative so be prepared for the worst.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 17, 'npc_2_2', 'I knew I could count on you. Just deliver this lightsaber to the Nightsister Trujhazii. It will bring peace between us. The other Nightsisters are a little upset about the whole affair - don''t let any of them give you any trouble.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 18, 'npc_2_3', 'I knew you wouldn''t let them take me. We mean too much to one another to let a little thing like fraud come between us. Go and find this murderous Nightsister and convince her of my goodwill -- or barring that, put a stop to her.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 19, 'npc_3_1', 'I understand your reticence. I''m not keen to get into a fight with a lightsaber-wielding Nightsister. What if she got the blasted thing working?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 20, 'npc_3_2', 'I can''t believe you''d leave an old friend in the lurch like this. After all we''ve been through together.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 21, 'npc_3_3', 'My blood is on your hands. You could have saved me and didn''t.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 22, 'npc_4_1', 'An ancient lightsaber that I purchased as a collector''s item. It doesn''t actually work but is nonetheless quite valuable. One of those blasted Nightsisters took it from my old partner because of some imagined slight or other. Will get it back for me?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 23, 'npc_4_2', 'Nothing you need concern yourself with. You have my complete assurance that all the charges are largely without any basis in fact and even if they were, there''s certainly not enough evidence for a conviction. '),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 24, 'npc_4_3', 'I expected to be off of this blasted world before they found out. Things didn''t work out like I planned or I''d be drunk in a villa on Naboo right now. Terrible things happen to people who fall afoul of those Nightsisters. Help me?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 26, 'npc_5_2', 'A simple thing really. I found a buyer for that lightsaber and if you can make the delivery for me I''ll have enough credits to make my problems disappear. What do you say?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 31, 'npc_backtowork_1', 'You''ve got something on your mind. Spit it out.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 32, 'npc_backtowork_2', 'What''s on your mind? '),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 33, 'npc_backtowork_3', 'You haven''t changed your mind have you? I''d hate to think I offended you in some way.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 34, 'npc_breech_1', 'That imbecile needs to learn that I''m not going to let any of his little minions steal this priceless historical artifact. '),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 35, 'npc_breech_2', 'That scoundrel better deliver this time.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 36, 'npc_breech_3', 'You will not stand between us and our revenge.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 40, 'npc_failure_1', 'What will I tell my buyer? Perhaps I can sell the idea that this Nightsister is my courier. Then when she kills him the matter will resolve itself and I can find another buyer.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 41, 'npc_failure_2', 'Blast and double blast! Some days it just isn''t profitable swindling people.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 42, 'npc_failure_3', 'You couldn''t stop her? I''ve got to find a place to hide.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 52, 'npc_noloc_1', 'Some of the other Nightsisters of her clan may still be peeved about that imagined slight.  It might be best if we waited before attempting to conclude this business. Come see me later.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 53, 'npc_noloc_2', 'Give me a few minutes to make some final arrangements and then we''ll get started, all right?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 54, 'npc_noloc_3', 'Wait! Maybe you should just wait here and protect me. That''s not a bad idea is it? Or maybe you should go. I can''t decide.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 55, 'npc_reset', 'Don''t think you''re up to this right now, eh? Come back when you think you''re ready.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 56, 'npc_reward_1', 'Steal? The nerve of her. I offered a very fair price for this. It''s hardly my fault she turned it down.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 57, 'npc_reward_2', 'I never doubted you for a moment. I knew that if anybody could pull this off it was you.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 58, 'npc_reward_3', 'Thank you. I need to find a way off of this blasted rock before they send another one of those bloodthirsty monsters after me.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 59, 'npc_smuggle_1', 'Go back and be done with me!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 60, 'npc_smuggle_2', 'I told my sisters that rather than paying the ransom we should just rip his head off and take the lightsaber off his corpse, but they wouldn''t listen.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 65, 'npc_work_1', 'Get a move on now. There''s no time like the present for getting things done. '),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 66, 'npc_work_2', 'Have you made that little delivery we discussed. Waiting isn''t going to help this matter any.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 67, 'npc_work_3', 'You''re going to leave soon and stop her from killing me aren''t you?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 71, 'player_1_1', 'Yes'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 72, 'player_1_2', 'Yes'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 73, 'player_1_3', 'Yes'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 74, 'player_2_1', 'No'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 75, 'player_2_2', 'No'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 76, 'player_2_3', 'No'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 77, 'player_3_1', 'What was taken from you?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 78, 'player_3_2', 'What rumors? '),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 79, 'player_3_3', 'What did you expect to happen?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 81, 'player_4_2', 'What do you want me to do this time? '),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 84, 'player_5_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 90, 'player_more_2_2', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 95, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 96, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 97, 'return_waypoint_description_1', 'Return to Singular Nak with the broken lightsaber.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 98, 'return_waypoint_description_2', 'Return to Singular Nak at the Trade Outpost.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 99, 'return_waypoint_description_3', 'Return to Singular Nak and inform him of your success.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 100, 'return_waypoint_name_1', 'Singular Nak'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 101, 'return_waypoint_name_2', 'Singular Nak'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 102, 'return_waypoint_name_3', 'Singular Nak'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 103, 'waypoint_description_1', 'Find Grthashaal and take the broken lightsaber from her'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 104, 'waypoint_description_2', 'Bring the lightsaber to Trujhazii'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 105, 'waypoint_description_3', 'Go and stop the Nightsister before she kills Singular Nak'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 106, 'waypoint_name_1', 'Gruthashaal''s location'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 107, 'waypoint_name_2', 'Trujhazii''s location'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 108, 'waypoint_name_3', 'The Nightsister Stalker''s location'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 109, 'npc_reset_1', 'Don''t think you''re up to this right now, eh? Come back when you think you''re ready.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 110, 'npc_reset_2', 'Don''t think you''re up to this right now, eh? Come back when you think you''re ready.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 111, 'npc_reset_3', 'Don''t think you''re up to this right now, eh? Come back when you think you''re ready.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 112, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 113, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 114, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 115, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 116, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_singular_nak.stf', 117, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 1, 'cant_work', 'I urgently require your help as soon as you are not busy!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 3, 'dontknowyou_2', 'Away from me, stranger.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 6, 'next', 'I have uncovered no new plans by Shibb Nisshil to purloin Dathomir''s rancors. Perhaps he has discarded his evil scheme.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 7, 'notit_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 8, 'notit_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 9, 'notyet', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 10, 'npc_1_1', 'Oh, you have arrived in time to impede Shibb Nisshil''s evil plan! His hunting team has captured a bull rancor in the wild and is taking it to an unspeakable fate. You must stop the hunting team and rescue the rancor!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 11, 'npc_1_2', 'It is another nefarious scheme by Imperial scientist Shibb Nisshil! He has somehow enlisted an outcast from the Nightsister clan to lead a slave team that hunts rancors. Such a fearsome team can capture rancors by the hundreds, irretrievably damaging the Dathomir ecology. You must destroy this hunting team!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 12, 'npc_2_1', 'Good. If you simply speak to the rancor in a firm voice, it will follow you here. Then I can remove Nisshil''s mind-control chip and restore the creature to its natural vigor. Go!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 13, 'npc_2_2', 'Your enthusiasm reassures me. I understand these Nightsisters to be formidable opponents, so you may require help. Good luck!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 14, 'npc_3_1', 'You would stand by and see Dathomir''s delicate ecology ruined? You are a monster like Nisshil!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 15, 'npc_3_2', 'You would passively watch Shibb Nisshil denude Dathomir of all its rancors for his evil plan?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 16, 'npc_4_1', 'He is an Imperial scientist at the Research Outpost. He is plundering Dathomir of its rancors to create an army of Imperial cyber-rancors! The damage to the ecosystem will be immense. Will you rescue this bull rancor from a ghastly fate?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 17, 'npc_4_2', 'She is evidently a lunatic who assaulted several senior clan members. Now she works for Nisshil because she wishes to see the Empire destroy her former clan. Very sad, but we cannot let this maniac further Nisshil''s evil scheme. Will you stop her team?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 18, 'npc_5_1', 'Shibb Nisshil''s hunting team has implanted the rancor with a mind-control chip that renders it docile as a bolma calf. They are taking the rancor to his lab now. Shoot the hunters and the tame beast will follow you here.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 20, 'npc_6_1', 'They are only common mercenaries. Actually, I suppose they must be uncommonly well armed to capture a rancor. But you still must stop them! Except maybe you will need help from friends.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 22, 'npc_backtowork_1', 'I have told you all I know. You must rescue that helpless bull rancor from Shibb Nisshil''s evil hunters!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 23, 'npc_backtowork_2', 'That is all I know. You must stop that Nightsister outcast and her hunting team. Save the rancors!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 24, 'npc_breech_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 25, 'npc_breech_2', 'An enemy! Kill!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 28, 'npc_failure_1', 'You did not rescue that helpless bull rancor? Oh, my heart goes out to it, thinking of its terrible fate!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 29, 'npc_failure_2', 'You did not stop that Nightsister and her hunting team? I am distraught and depressed.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 36, 'npc_noloc_1', 'I have probe droids looking, even now, for the mercenary hunting party. Talk to me again shortly, and I shall have coordinates for you.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 37, 'npc_noloc_2', 'I have probe droids scouting to locate the Nightsister outcast and her hunting team. Contact me shortly for coordinates.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 38, 'npc_reset', 'But all the rancors of Dathomir depend on you to keep them from Shibb Nisshil''s evil clutches!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 39, 'npc_reward_1', 'Oh, what a fine specimen! I shall remove the mind-control chip promptly -- taking proper precautions, of course. Here is a reward for your fine effort!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 40, 'npc_reward_2', 'You have helped the rancors of Dathomir live happier lives, unencumbered by Imperial concerns. Thank you!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 45, 'npc_work_1', 'You must rescue that helpless bull rancor from Shibb Nisshil''s evil mercenary hunters!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 46, 'npc_work_2', 'You must stop that Nightsister outcast and her hunting team. Save the rancors!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 53, 'player_3_1', 'Who is Shibb Nisshil and what is his evil plan?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 54, 'player_3_2', 'How did Shibb Nisshil enlist an outcast from the Nightsister clan?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 55, 'player_4_1', 'How, exactly, am I to rescue a bull rancor?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 56, 'player_4_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 57, 'player_5_1', 'How strong is this hunting team?'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 58, 'player_5_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 65, 'player_reset', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 66, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 67, 'return_waypoint_description_1', 'This Ithorian naturalist awaits dropoff of a bull rancor rescued from the hunting team hired by Imperial scientist Shibb Nisshil.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 68, 'return_waypoint_description_2', 'This Ithorian naturalist wants news of the destruction of the rancor hunting team led by an outcast from the Nightsister clan.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 69, 'return_waypoint_name_1', 'Wallaw Loowobbli'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 70, 'return_waypoint_name_2', 'Wallaw Loowobbli'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 71, 'waypoint_description_1', 'Ithorian naturalist Wallaw Loowobbli wants this mind-controlled rancor rescued from the hunting team that is bringing it to Imperial scientist Shibb Nisshil.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 72, 'waypoint_description_2', 'Ithorian naturalist Wallaw Loowobbli wants the destruction of this team and its leader, an outcast from the Nightsister clan.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 73, 'waypoint_name_1', 'Bull Rancor'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 74, 'waypoint_name_2', 'Rancor Hunting Team'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 75, 'npc_reset_1', 'But all the rancors of Dathomir depend on you to keep them from Shibb Nisshil''s evil clutches!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 76, 'npc_reset_2', 'But all the rancors of Dathomir depend on you to keep them from Shibb Nisshil''s evil clutches!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 77, 'npc_reset_3', 'But all the rancors of Dathomir depend on you to keep them from Shibb Nisshil''s evil clutches!'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 78, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 79, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 80, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 81, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 82, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/dathomir_tradeoutpost_wallaw_loowobbli.stf', 83, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/dathomir/diax.stf', 1, 'cant_work', 'You look a bit preoccupied. Why don''t you take care of whatever it is you''re doing now and come back. I may have work for you.'),
('string/en/static_npc/dathomir/diax.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dathomir/diax.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/dathomir/diax.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/diax.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dathomir/diax.stf', 6, 'next', 'You are worthy of the honor of helping my mistress Kais. Go speak with her now.'),
('string/en/static_npc/dathomir/diax.stf', 7, 'notit_1', 'You realize this is not what I asked for at all? What made you think this is what I wanted? By the book of shadows, these outworlders are inept.'),
('string/en/static_npc/dathomir/diax.stf', 8, 'notit_2', 'You realize this is not what I asked for at all? What made you think this is what I wanted? By the book of shadows, these outworlders are inept.'),
('string/en/static_npc/dathomir/diax.stf', 9, 'notyet', 'You may have potential, but I do not know if you are ready to serve. Come back after you have helped us more.'),
('string/en/static_npc/dathomir/diax.stf', 10, 'npc_1_1', 'Yes? Come closer. You''ll do nicely, outsider. I''m struggling with a dilemma. I''m an apprentice healer in the service of Kais. I find myself constantly competing for her favor with another apprentice. Would you object to making sure she never hinders me again?'),
('string/en/static_npc/dathomir/diax.stf', 11, 'npc_1_2', 'You have done well so far. I have another task for you. Our spies report having seen a certain singing mountain clan healer using an incredibly effective salve. From what I am told the salve sounds like something I read about once, I believe it was called bac-ta. Are you willing to find this healer and bring me her salve to study?'),
('string/en/static_npc/dathomir/diax.stf', 12, 'npc_2_1', 'That''s fine. Daverda is currently gathering herbs near the location I''ve marked on this map. Go there, kill her, and return quickly.'),
('string/en/static_npc/dathomir/diax.stf', 13, 'npc_2_2', 'Good. The scouts report her location over that way. Don''t try to negotiate with her. Just eliminate her as quickly and efficiently as possible. I do not want the Singing Mountain Clan to know we have stolen their secret. Once you have the salve, return it to me.'),
('string/en/static_npc/dathomir/diax.stf', 14, 'npc_3_1', 'Hah, timid mouse. Very well then, there is more than one way to skin a brackaset.'),
('string/en/static_npc/dathomir/diax.stf', 15, 'npc_3_2', 'Outworlder, you try my patience.'),
('string/en/static_npc/dathomir/diax.stf', 16, 'npc_4_1', 'I''d take care of this myself, but it would reflect poorly on the healers if I did. The rest of the clan shouldn''t see us as political schemers. The last thing I need is Kais to see me as overly ambitious. If you help me with this dilemma I''ll be sure to reward you well.'),
('string/en/static_npc/dathomir/diax.stf', 17, 'npc_4_2', 'Do this for me and I will let Kais know you can be trusted. Also I will reward you with a kit of healing herbs and poultices.'),
('string/en/static_npc/dathomir/diax.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/dathomir/diax.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/dathomir/diax.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/dathomir/diax.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/dathomir/diax.stf', 22, 'npc_backtowork_1', 'She''s out gathering herbs for Kais. Look at this map I made. Right here. Now hurry.'),
('string/en/static_npc/dathomir/diax.stf', 23, 'npc_backtowork_2', 'Look, here is my map. Study it carefully. The healer was spotted in this area. Now get going!'),
('string/en/static_npc/dathomir/diax.stf', 24, 'npc_breech_1', 'What are you doing here?'),
('string/en/static_npc/dathomir/diax.stf', 25, 'npc_breech_2', 'I''m not looking for company. Go away.'),
('string/en/static_npc/dathomir/diax.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/diax.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/diax.stf', 28, 'npc_failure_1', 'By the book of shadows, these outworlders are inept.'),
('string/en/static_npc/dathomir/diax.stf', 29, 'npc_failure_2', 'By the book of shadows, these outworlders are inept.'),
('string/en/static_npc/dathomir/diax.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/diax.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/diax.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/diax.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/diax.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/diax.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/diax.stf', 36, 'npc_noloc_1', 'Something is not right here. Come back later, I may have work for you then.'),
('string/en/static_npc/dathomir/diax.stf', 37, 'npc_noloc_2', 'Something is not right here. Come back later, I may have work for you then.'),
('string/en/static_npc/dathomir/diax.stf', 38, 'npc_reset', 'Well, perhaps you are correct. Come back when you feel up to the challenge.'),
('string/en/static_npc/dathomir/diax.stf', 39, 'npc_reward_1', 'Ah, she is... dead? Oh lovely. I''m glad you are working for me. Yes, you are such a wonderful little pet. As promised - here is your treat, pet.'),
('string/en/static_npc/dathomir/diax.stf', 40, 'npc_reward_2', 'You have the salve? Give it to me at once. Hmm, what an odd smell. Familiar, but I just can''t place it. Very well, here is your reward. Kais should be waiting for you. I must study the salve. Leave.'),
('string/en/static_npc/dathomir/diax.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/diax.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/diax.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/diax.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/diax.stf', 45, 'npc_work_1', 'You''re not scared are you? Look, she''s not all that tough. I''d do it myself if it weren''t for certain political entanglements.'),
('string/en/static_npc/dathomir/diax.stf', 46, 'npc_work_2', 'I suggest you start out immediately.'),
('string/en/static_npc/dathomir/diax.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/dathomir/diax.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/dathomir/diax.stf', 49, 'player_1_1', 'I will do it.'),
('string/en/static_npc/dathomir/diax.stf', 50, 'player_1_2', 'Yes, I will.'),
('string/en/static_npc/dathomir/diax.stf', 51, 'player_2_1', 'Kill her? No way!'),
('string/en/static_npc/dathomir/diax.stf', 52, 'player_2_2', 'No, I will not.'),
('string/en/static_npc/dathomir/diax.stf', 53, 'player_3_1', 'Why?'),
('string/en/static_npc/dathomir/diax.stf', 54, 'player_3_2', 'Why should I?'),
('string/en/static_npc/dathomir/diax.stf', 55, 'player_4_1', ''),
('string/en/static_npc/dathomir/diax.stf', 56, 'player_4_2', ''),
('string/en/static_npc/dathomir/diax.stf', 57, 'player_5_1', ''),
('string/en/static_npc/dathomir/diax.stf', 58, 'player_5_2', ''),
('string/en/static_npc/dathomir/diax.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/diax.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/diax.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/diax.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/diax.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/diax.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/diax.stf', 65, 'player_reset', 'I''m not ready for this.'),
('string/en/static_npc/dathomir/diax.stf', 66, 'player_sorry', 'Where did you say she was again?'),
('string/en/static_npc/dathomir/diax.stf', 67, 'return_waypoint_description_1', 'Return to Diax now that you have completed your grisly task.'),
('string/en/static_npc/dathomir/diax.stf', 68, 'return_waypoint_description_2', 'Return to Diax with the salve.'),
('string/en/static_npc/dathomir/diax.stf', 69, 'return_waypoint_name_1', 'Diax'),
('string/en/static_npc/dathomir/diax.stf', 70, 'return_waypoint_name_2', 'Diax'),
('string/en/static_npc/dathomir/diax.stf', 71, 'waypoint_description_1', 'Go to where Daverda is gathering healing herbs and kill her.'),
('string/en/static_npc/dathomir/diax.stf', 72, 'waypoint_description_2', 'Go kill the Singing Mountain Clan Nightsister and return to Diax with the salve she carries.'),
('string/en/static_npc/dathomir/diax.stf', 73, 'waypoint_name_1', 'Daverda'),
('string/en/static_npc/dathomir/diax.stf', 74, 'waypoint_name_2', 'Singing Mountain Clan Nightsister'),
('string/en/static_npc/dathomir/diax.stf', 75, 'npc_reset_1', 'Well, perhaps you are correct. Come back when you feel up to the challenge.'),
('string/en/static_npc/dathomir/diax.stf', 76, 'npc_reset_2', 'Well, perhaps you are correct. Come back when you feel up to the challenge.'),
('string/en/static_npc/dathomir/diax.stf', 77, 'npc_reset_3', 'Well, perhaps you are correct. Come back when you feel up to the challenge.'),
('string/en/static_npc/dathomir/diax.stf', 78, 'player_reset_1', 'I''m not ready for this.'),
('string/en/static_npc/dathomir/diax.stf', 79, 'player_reset_2', 'I''m not ready for this.'),
('string/en/static_npc/dathomir/diax.stf', 80, 'player_reset_3', 'I''m not ready for this.'),
('string/en/static_npc/dathomir/diax.stf', 81, 'player_sorry_1', 'Where did you say she was again?'),
('string/en/static_npc/dathomir/diax.stf', 82, 'player_sorry_2', 'Where did you say she was again?'),
('string/en/static_npc/dathomir/diax.stf', 83, 'player_sorry_3', 'Where did you say she was again?'),
('string/en/static_npc/dathomir/gethzerion.stf', 1, 'cant_work', 'How dare you? I ordered you released from Baritha''s compulsion, and you run off to someone else? If you value your life, you will direct all of you attentions to your ruler... myself.'),
('string/en/static_npc/dathomir/gethzerion.stf', 2, 'dontknowyou_1', 'Nevermind, I don''t know you.'),
('string/en/static_npc/dathomir/gethzerion.stf', 3, 'dontknowyou_2', 'You didn''t see anything, right? Good.'),
('string/en/static_npc/dathomir/gethzerion.stf', 4, 'dontknowyou_3', 'Actually, I changed my mind.'),
('string/en/static_npc/dathomir/gethzerion.stf', 5, 'dontknowyou_4', 'Oh, you don''t want to die? Okay, then. Sorry about that.'),
('string/en/static_npc/dathomir/gethzerion.stf', 6, 'gotowork_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 10, 'next', 'You have pleased me, but do not try my patience. If I have need of you in the future, I shall call upon you.'),
('string/en/static_npc/dathomir/gethzerion.stf', 11, 'notit_1', 'What is this? You waste my time!'),
('string/en/static_npc/dathomir/gethzerion.stf', 12, 'notit_2', 'I asked you for nothing!'),
('string/en/static_npc/dathomir/gethzerion.stf', 13, 'notit_3', 'I did not ask for this. Take it away from me.'),
('string/en/static_npc/dathomir/gethzerion.stf', 14, 'notit_4', 'This is not the necklace! BRING ME THE NECKLACE!'),
('string/en/static_npc/dathomir/gethzerion.stf', 15, 'notyet', 'How dare you disturb me? Since I am in a good mood, you will be allowed to leave my chamber alive. Do no make the same mistake again.'),
('string/en/static_npc/dathomir/gethzerion.stf', 16, 'npc_1_1', 'So, you are the one that Baritha has been mooning over. Considering I am recently missing a slave, I will have to take you from her. Your first act as my slave will be to take care of your predecessor. Do you understand?'),
('string/en/static_npc/dathomir/gethzerion.stf', 17, 'npc_1_2', 'I have decided that you may serve me better were you not under the yoke of slavery. Go show me your effectiveness at destroying those weak Singing Mountain sisters, and I will consider the prospect further.'),
('string/en/static_npc/dathomir/gethzerion.stf', 18, 'npc_1_3', 'You have proven yourself adequate to my uses. I hereby name you my Dagger... and from now on you will be my personal assassin. I now need you to target your first victim.'),
('string/en/static_npc/dathomir/gethzerion.stf', 19, 'npc_1_4', 'That... that.... that WITCH!!! How dare she!? When I find her, I will tear her soul apart!! Ahhh... yessss... and that''s exactly what she expects, isn''t it? What a clever little trap... but she didn''t expect you, did she, my little Dagger? You will go and kill Sister Chastina for her impudence!'),
('string/en/static_npc/dathomir/gethzerion.stf', 20, 'npc_2_1', 'Very good... quick to respond, and very clear... I shall see if there may be more than slavery for you. For now, go find my slave, then kill him in a most painful manner. Once the punishment has been exacted, bring his heart back to me.'),
('string/en/static_npc/dathomir/gethzerion.stf', 21, 'npc_2_2', 'Baritha has brought to my attention that a few of the Singing Mountain sisters have had the audacity to enter our territory. Silence their spells and lead them to the carrion-feeders.'),
('string/en/static_npc/dathomir/gethzerion.stf', 22, 'npc_2_3', 'Your willingness is pleasing to me. You will locate and kill Sister Aelta, getting her out of my hair once and for all. Do the deed, then return to let me know.'),
('string/en/static_npc/dathomir/gethzerion.stf', 23, 'npc_2_4', 'Track that filthy, brazen witch down... when you find her, rip her heart out and show it to her! Afterwards, remove that necklace she wrongfully wears around her neck and bring it back to me.'),
('string/en/static_npc/dathomir/gethzerion.stf', 24, 'npc_3_1', 'Oh, really? You believe that you will leave our stronghold just like that? You presume too much, fool. I will give you one more chance to change your mind.'),
('string/en/static_npc/dathomir/gethzerion.stf', 25, 'npc_3_2', 'You will deal with what I tell you to deal with. I will not tolerate this insolence!'),
('string/en/static_npc/dathomir/gethzerion.stf', 26, 'npc_3_3', 'That may well be the least wise thing you have ever done. Perhaps you believed this was a request? Or perhaps you think yourself on an equal level as myself that you may speak so openly? Not smart....'),
('string/en/static_npc/dathomir/gethzerion.stf', 27, 'npc_3_4', 'Were I not so distraught, I enjoy watching you as I choke the very breath out of your lungs. Please.... stay close so that I may calm down enough to do so.'),
('string/en/static_npc/dathomir/gethzerion.stf', 28, 'npc_4_1', 'My first and foremost among slaves was a cunning man by the name of Dal Zeybuub. Unfortunately for him, My Prime Slave thinks too highly of himself. Rather than betraying me, as he plans, he will now be a victim of his own thoughts betraying him.'),
('string/en/static_npc/dathomir/gethzerion.stf', 29, 'npc_4_2', 'Perhaps. Perhaps not. Depending on how well you do, I may decide to grant you that boon, for I am a gracious Mother. Now go!'),
('string/en/static_npc/dathomir/gethzerion.stf', 30, 'npc_4_3', 'You will be ending the short life of Sister Aelta, one of the Singing Mountain Sisters. Ever since Augwynne, Clan Mother of the Singers, has lost both of her daughters she has ''adopted'' two more. You will show that old crone that I will not accept this.'),
('string/en/static_npc/dathomir/gethzerion.stf', 31, 'npc_4_4', 'How DARE she? That withered hag, Augwynne, has chosen another ''daughter'', my former friend Chastina. She has gone so far as to give to Chastina her necklace! That is MY necklace!!! As Augwynne''s real daughter, I DESERVE IT!!! ... -er-.... Why am I telling you this?'),
('string/en/static_npc/dathomir/gethzerion.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 40, 'npc_backtowork_1', 'You will find my Prime Slave and kill him. Once done, bring me back his heart... and I will know if it is his.'),
('string/en/static_npc/dathomir/gethzerion.stf', 41, 'npc_backtowork_2', 'Go find these impudent sisters of Augwynne and render their lives from their bodies.'),
('string/en/static_npc/dathomir/gethzerion.stf', 42, 'npc_backtowork_3', 'You will find that bold harlot that calls herself a sister, Aelta. Once you have done so, kill her.... painfully.'),
('string/en/static_npc/dathomir/gethzerion.stf', 43, 'npc_backtowork_4', 'Go kill that impudent failure of a witch and bring me the necklace she wears around her neck.'),
('string/en/static_npc/dathomir/gethzerion.stf', 44, 'npc_breech_1', 'No, please... you don''t know what kind of nightmare I was fleeing! LET ME GO!!!'),
('string/en/static_npc/dathomir/gethzerion.stf', 45, 'npc_breech_2', 'Sisters, we have been found! Leave no witnesses!'),
('string/en/static_npc/dathomir/gethzerion.stf', 46, 'npc_breech_3', 'You were sent by Gethzerion? But you''re not a Nightsister... oh well... you will still die.'),
('string/en/static_npc/dathomir/gethzerion.stf', 47, 'npc_breech_4', 'So... that coward sent someone else, did she? Then you must die in her place.'),
('string/en/static_npc/dathomir/gethzerion.stf', 48, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 49, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 50, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 52, 'npc_failure_1', 'What? You failed me? HOW DARE YOU!!!'),
('string/en/static_npc/dathomir/gethzerion.stf', 53, 'npc_failure_2', 'How dare you come back and face me after you have failed. It shall be the slave''s collar for you, then.'),
('string/en/static_npc/dathomir/gethzerion.stf', 54, 'npc_failure_3', 'You were unable to accomplish a simple task as this? Very well... it shall be the slave''s collar for you.'),
('string/en/static_npc/dathomir/gethzerion.stf', 55, 'npc_failure_4', 'How dare you return after you have failed me?'),
('string/en/static_npc/dathomir/gethzerion.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 68, 'npc_noloc_1', 'The time is not right to track him down. Come back to me in a while and I will send you out against him.'),
('string/en/static_npc/dathomir/gethzerion.stf', 69, 'npc_noloc_2', 'When Baritha returns, I will know where these sisters can be found. Come back to me in a short while.'),
('string/en/static_npc/dathomir/gethzerion.stf', 70, 'npc_noloc_3', 'I will send a scout to find where Sister Aelta can be found. Return to me in a short while.'),
('string/en/static_npc/dathomir/gethzerion.stf', 71, 'npc_noloc_4', 'I do not know where Chastina can be found. Come back to me in a while and I will assist you in finding her.'),
('string/en/static_npc/dathomir/gethzerion.stf', 72, 'npc_reset', 'Yes you are, come to think of it. You would assist me better were you to help me... test... my spells.'),
('string/en/static_npc/dathomir/gethzerion.stf', 73, 'npc_reward_1', 'Ahhhh... Dal''s heart... Once it has been chilled, it will make for a most pleasant dinner. I have found that it is true that vengeance is best served cold. As for you... I sense I am not using you to the fullest.. Come back to me after I have thought this matter over.'),
('string/en/static_npc/dathomir/gethzerion.stf', 74, 'npc_reward_2', 'So you handled yourself better than some of these pathetic women who call themselves Witches? Very well then - your freedom is granted... for now. I will have a more important purpose for you, so stay close.'),
('string/en/static_npc/dathomir/gethzerion.stf', 75, 'npc_reward_3', 'You have done well on your first assignment for me. My left breast is warmed at the thought of the pain she felt as she died. Any of those foolish Singing sisters will do well to heed this warning : Augwynne''s daughters are dead, and they will not be ''replaced''!'),
('string/en/static_npc/dathomir/gethzerion.stf', 76, 'npc_reward_4', 'Yes... my necklace! Were I able to have succeeded in beheading my moth... I mean to say, beheading that Clan Mother.... well, either way, it is mine now, where it should have been for many years now. My Dagger, you have pleased my very, very much.'),
('string/en/static_npc/dathomir/gethzerion.stf', 77, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 81, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 82, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 83, 'npc_takeme_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 85, 'npc_work_1', 'Why do you disturb me? I have already spoken!'),
('string/en/static_npc/dathomir/gethzerion.stf', 86, 'npc_work_2', 'Why do you hesitate, fool?'),
('string/en/static_npc/dathomir/gethzerion.stf', 87, 'npc_work_3', 'Why do you bother me?'),
('string/en/static_npc/dathomir/gethzerion.stf', 88, 'npc_work_4', 'What?'),
('string/en/static_npc/dathomir/gethzerion.stf', 89, 'otherescort_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 90, 'otherescort_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 91, 'otherescort_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 93, 'player_1_1', 'Yes, Clan Mother. I shall do so.'),
('string/en/static_npc/dathomir/gethzerion.stf', 94, 'player_1_2', 'I will not fail you, Mother.'),
('string/en/static_npc/dathomir/gethzerion.stf', 95, 'player_1_3', 'Yes, Clan Mother, I will do so.'),
('string/en/static_npc/dathomir/gethzerion.stf', 96, 'player_1_4', 'I shall do so at once, gracious Mother!'),
('string/en/static_npc/dathomir/gethzerion.stf', 97, 'player_2_1', 'I understand that I''m leaving. Bye!'),
('string/en/static_npc/dathomir/gethzerion.stf', 98, 'player_2_2', 'I cannot handle them alone. No.'),
('string/en/static_npc/dathomir/gethzerion.stf', 99, 'player_2_3', 'I will not kill people for a living! No!'),
('string/en/static_npc/dathomir/gethzerion.stf', 100, 'player_2_4', 'You''re too emotional right now. No.'),
('string/en/static_npc/dathomir/gethzerion.stf', 101, 'player_3_1', 'What do you mean by predecessor?'),
('string/en/static_npc/dathomir/gethzerion.stf', 102, 'player_3_2', 'If I do so, will I retain my freedom?'),
('string/en/static_npc/dathomir/gethzerion.stf', 103, 'player_3_3', 'Who shall I dispatch now?'),
('string/en/static_npc/dathomir/gethzerion.stf', 104, 'player_3_4', 'If I might ask, what troubles you so?'),
('string/en/static_npc/dathomir/gethzerion.stf', 105, 'player_4_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 106, 'player_4_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 107, 'player_4_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 108, 'player_4_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 109, 'player_5_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 110, 'player_5_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 111, 'player_5_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 112, 'player_5_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 113, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 114, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 115, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 116, 'player_more_1_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 117, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 118, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 119, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 120, 'player_more_2_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 121, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 122, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 123, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 124, 'player_more_3_4', ''),
('string/en/static_npc/dathomir/gethzerion.stf', 125, 'player_reset', 'I am too lowly to serve you any more, Clan Mother.'),
('string/en/static_npc/dathomir/gethzerion.stf', 126, 'player_sorry', 'I am sorry, Mother. What was I to do again?'),
('string/en/static_npc/dathomir/gethzerion.stf', 127, 'return_waypoint_description_1', 'The Clan Mother awaits your return with the slave''s heart'),
('string/en/static_npc/dathomir/gethzerion.stf', 128, 'return_waypoint_description_2', 'The Clan Mother expects a prompt return'),
('string/en/static_npc/dathomir/gethzerion.stf', 129, 'return_waypoint_description_3', 'Return and let the Clan Mother know that Augwynne''s "daughter" is dead.'),
('string/en/static_npc/dathomir/gethzerion.stf', 130, 'return_waypoint_description_4', 'The Nightsister Clan Mother is anxiously waiting to her of Chastina''s demise... and to hold that necklace.'),
('string/en/static_npc/dathomir/gethzerion.stf', 131, 'return_waypoint_name_1', 'Gethzerion'),
('string/en/static_npc/dathomir/gethzerion.stf', 132, 'return_waypoint_name_2', 'Gethzerion'),
('string/en/static_npc/dathomir/gethzerion.stf', 133, 'return_waypoint_name_3', 'Gethzerion'),
('string/en/static_npc/dathomir/gethzerion.stf', 134, 'return_waypoint_name_4', 'Gethzerion'),
('string/en/static_npc/dathomir/gethzerion.stf', 135, 'waypoint_description_1', 'You should be able to find the Clan Mother''s escaped slave in these whereabouts'),
('string/en/static_npc/dathomir/gethzerion.stf', 136, 'waypoint_description_2', 'Several scouts from the Singing Mountain Clan should be around here'),
('string/en/static_npc/dathomir/gethzerion.stf', 137, 'waypoint_description_3', 'Aelta of the Singing Mountain Clan should be around here. Kill her.'),
('string/en/static_npc/dathomir/gethzerion.stf', 138, 'waypoint_description_4', 'Go kill Augwynne''s successor, then bring back her necklace to Gethzerion.'),
('string/en/static_npc/dathomir/gethzerion.stf', 139, 'waypoint_name_1', 'Gethzerion''s Escaped Slave'),
('string/en/static_npc/dathomir/gethzerion.stf', 140, 'waypoint_name_2', 'Singing Sister Patrol'),
('string/en/static_npc/dathomir/gethzerion.stf', 141, 'waypoint_name_3', 'Sister Aelta'),
('string/en/static_npc/dathomir/gethzerion.stf', 142, 'waypoint_name_4', 'Sister Chastina'),
('string/en/static_npc/dathomir/gethzerion.stf', 143, 'npc_reset_1', 'Yes you are, come to think of it. You would assist me better were you to help me... test... my spells.'),
('string/en/static_npc/dathomir/gethzerion.stf', 144, 'npc_reset_2', 'Yes you are, come to think of it. You would assist me better were you to help me... test... my spells.'),
