('string/en/static_npc/dathomir/gethzerion.stf', 153, 'player_sorry_1', 'I am sorry, Mother. What was I to do again?'),
('string/en/static_npc/dathomir/gethzerion.stf', 154, 'player_sorry_2', 'I am sorry, Mother. What was I to do again?'),
('string/en/static_npc/dathomir/gethzerion.stf', 155, 'player_sorry_3', 'I am sorry, Mother. What was I to do again?'),
('string/en/static_npc/dathomir/gethzerion.stf', 156, 'player_sorry_4', 'I am sorry, Mother. What was I to do again?'),
('string/en/static_npc/dathomir/gethzerion.stf', 157, 'player_sorry_5', 'I am sorry, Mother. What was I to do again?'),
('string/en/static_npc/dathomir/kais.stf', 1, 'cant_work', 'You walk within my hearth, but yet you pridefully belong to another. I will not tolerate this. Begone with you.'),
('string/en/static_npc/dathomir/kais.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dathomir/kais.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/dathomir/kais.stf', 4, 'dontknowyou_3', 'Wait, you''re not the guy who I''m supposed to meet. Get out of here before I have you arrested.'),
('string/en/static_npc/dathomir/kais.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dathomir/kais.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/dathomir/kais.stf', 7, 'gotowork_3', 'What''s this? The Goddess told me that you would have some powder, not this!'),
('string/en/static_npc/dathomir/kais.stf', 8, 'next', 'You have proven your worth. Perhaps the Clan Mother may find use of your willingness to assist.'),
('string/en/static_npc/dathomir/kais.stf', 9, 'notit_1', 'My eyes are old, but my mind is wise. This is not what I need of you. I am too old for games.'),
('string/en/static_npc/dathomir/kais.stf', 10, 'notit_2', 'Do not attempt foolery, for this is not a heart.'),
('string/en/static_npc/dathomir/kais.stf', 11, 'notit_3', 'I have asked you for nothing.'),
('string/en/static_npc/dathomir/kais.stf', 12, 'notyet', 'I look at you and see a bag of decaying flesh, one that lives only to die. Show yourself to the younger one, and ask her what she sees.'),
('string/en/static_npc/dathomir/kais.stf', 13, 'npc_1_1', 'Sit and drink. You have been watched and deemed worthy to offer your services. You will venture into the dark of the forests and gaze upon the fangs of a Gaping Spider for me, correct? '),
('string/en/static_npc/dathomir/kais.stf', 14, 'npc_1_2', 'I hold the power of the spider within my hand, yet this will extinguish life within a few beats of the heart. I need of you to bring me the strength of time to couple with the strength of death. Bring me the heart of a cumbersome Malkloc.'),
('string/en/static_npc/dathomir/kais.stf', 15, 'npc_1_3', 'The two reagents have been combined, and bring forth a glorious toxin. You will now fulfill the Clan Mother''s request and bring this toxin to one who guards the prison of the Imperials.'),
('string/en/static_npc/dathomir/kais.stf', 16, 'npc_2_1', 'Yes, you will. Arm yourself with your worthless weapons and defeat the eight-legged horror. Once you have quenched its life, reach inside its maw and rip out its poison glands. Only then will you return to me.'),
('string/en/static_npc/dathomir/kais.stf', 17, 'npc_2_2', 'You will need to choose one that is in the prime of its life, for it still holds much time within its heart. Bring it to me and you will have pleased the Clan Mother.'),
('string/en/static_npc/dathomir/kais.stf', 18, 'npc_2_3', 'The guard is most willing to help condemn his brethren, and knows what to do. Take this powder to him, and he will ensure that all of the rest will taste of it.'),
('string/en/static_npc/dathomir/kais.stf', 19, 'npc_3_1', 'Then your desire is to feel your insides cramp with discomfort until your intestines burst from your belly? If you deny my will, then that drink you consumed shall do just that.'),
('string/en/static_npc/dathomir/kais.stf', 20, 'npc_3_2', 'Your lack of courage will couple with your lack of breath. You hold a poison within your system that only I can cure... you may think on what I said.'),
('string/en/static_npc/dathomir/kais.stf', 21, 'npc_3_3', 'Then you will doom yourself, young one. A sad waste of such talent.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dathomir/kais.stf', 22, 'npc_4_1', 'The Clan Mother, Gethzerion, has wisely called upon my skills as a healer. I will heal any wounds that shall arise with the Imperials, but to do so, I need the power of the Gaping Spider within my hands. You will give me that power, will you not?'),
('string/en/static_npc/dathomir/kais.stf', 23, 'npc_4_2', 'The Malkloc is birthed and dies as does everything else. For every beat of its heart, many smaller creatures will see their whole cycle pass before them, making the Malkloc immortal in comparison. Within its heart is captured time, itself.'),
('string/en/static_npc/dathomir/kais.stf', 24, 'npc_4_3', 'He is one who has tasted a poison more deadly than anything I can create. Baritha''s methods are quite... effective. Once this poison has been consumed by all of those that call themselves Imperials, it will stay within their system until activated. If the Mother asks of it, I will bring forth the agent that shall bring the toxin to life.'),
('string/en/static_npc/dathomir/kais.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dathomir/kais.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/dathomir/kais.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dathomir/kais.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dathomir/kais.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/dathomir/kais.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dathomir/kais.stf', 31, 'npc_backtowork_1', 'You will venture into the forest and combat a Gaping Spider. Return with its poison sacs.'),
('string/en/static_npc/dathomir/kais.stf', 32, 'npc_backtowork_2', 'You are to bring unto me the heart of a Malkloc. Do not tarry.'),
('string/en/static_npc/dathomir/kais.stf', 33, 'npc_backtowork_3', 'You are to give the guard the means in which we shall control the rest of them. Take the vial to the guard.'),
('string/en/static_npc/dathomir/kais.stf', 34, 'npc_breech_1', ''),
('string/en/static_npc/dathomir/kais.stf', 35, 'npc_breech_2', ''),
('string/en/static_npc/dathomir/kais.stf', 36, 'npc_breech_3', 'Do you have the stuff? Hurry up before by supervisor finds me gone.'),
('string/en/static_npc/dathomir/kais.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/kais.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/kais.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/kais.stf', 40, 'npc_failure_1', 'You have failed me, and in turn you have failed yourself. Your death will be slow, but needed.'),
('string/en/static_npc/dathomir/kais.stf', 41, 'npc_failure_2', 'In the time you spent failing, the Malkloc''s heart has not shuttered a beat. Your life is insignicant, therefore your failure is all the more worthless.'),
('string/en/static_npc/dathomir/kais.stf', 42, 'npc_failure_3', 'Make whatever excuses of your failure to whatever god you worship. The poison within your system will take effect soon enough, so you have scant time to do so.'),
('string/en/static_npc/dathomir/kais.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/kais.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/kais.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/kais.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/kais.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/kais.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/kais.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/kais.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/kais.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/kais.stf', 52, 'npc_noloc_1', 'The time is not right for the Spiders to hunt. Ask again in a little while.'),
('string/en/static_npc/dathomir/kais.stf', 53, 'npc_noloc_2', 'The Malkloc has not awakened from it''s slumber. Speak to me when time has passed.'),
('string/en/static_npc/dathomir/kais.stf', 54, 'npc_noloc_3', 'Wait until the time the Guard will be ready to accept our love. Check with me in a little while.'),
('string/en/static_npc/dathomir/kais.stf', 55, 'npc_reset', 'Then you are no longer useful to me. If you wish the cure to the poison within your system, prove your worth to me....'),
('string/en/static_npc/dathomir/kais.stf', 56, 'npc_reward_1', 'A pristine collection of succulent venom is held within this jar. You have done well, young one. Now, bite this leaf, for it will slow the poison within your gullet. After you have done so, speak with me again.'),
('string/en/static_npc/dathomir/kais.stf', 57, 'npc_reward_2', 'Together with both Spider and Malkloc combined, a toxin can be made to live forever within a person''s blood. I will now draw these powers together with the mysteries of the Shadow. Speak with me when I am done.'),
('string/en/static_npc/dathomir/kais.stf', 58, 'npc_reward_3', 'You have helped to bring the Clan Mother into a more desirable bargaining position, for which she should be most grateful. For now, the poison resides within the Imperials until it is time for it to be called upon. Drink this, and you shall be freed of the agents within your own system. You have done well.'),
('string/en/static_npc/dathomir/kais.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/kais.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/kais.stf', 61, 'npc_smuggle_3', 'Look, you tell Baritha that I''ll put this in the water supply, okay? And then I''ll come by tonight for my payment, got it?'),
('string/en/static_npc/dathomir/kais.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/kais.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/kais.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/dathomir/kais.stf', 65, 'npc_work_1', 'Has fear become your enemy rather than your ally?'),
('string/en/static_npc/dathomir/kais.stf', 66, 'npc_work_2', 'You hesitate?'),
('string/en/static_npc/dathomir/kais.stf', 67, 'npc_work_3', 'Have you brought the vial to the guard?'),
('string/en/static_npc/dathomir/kais.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dathomir/kais.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dathomir/kais.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dathomir/kais.stf', 71, 'player_1_1', 'Yes, I will do so.'),
('string/en/static_npc/dathomir/kais.stf', 72, 'player_1_2', 'I will do so.'),
('string/en/static_npc/dathomir/kais.stf', 73, 'player_1_3', 'I will do this, yes.'),
('string/en/static_npc/dathomir/kais.stf', 74, 'player_2_1', 'Heck no I won''t!!!'),
('string/en/static_npc/dathomir/kais.stf', 75, 'player_2_2', 'Those things are huge!! No!'),
('string/en/static_npc/dathomir/kais.stf', 76, 'player_2_3', 'I''m not poisoning anyone! NO!'),
('string/en/static_npc/dathomir/kais.stf', 77, 'player_3_1', 'Why would I face such a trial?'),
('string/en/static_npc/dathomir/kais.stf', 78, 'player_3_2', 'What does it''s heart have to do with ''time''?'),
('string/en/static_npc/dathomir/kais.stf', 79, 'player_3_3', 'Who is this guard?'),
('string/en/static_npc/dathomir/kais.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dathomir/kais.stf', 81, 'player_4_2', ''),
('string/en/static_npc/dathomir/kais.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dathomir/kais.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dathomir/kais.stf', 84, 'player_5_2', ''),
('string/en/static_npc/dathomir/kais.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dathomir/kais.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/kais.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/kais.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/kais.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/kais.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/kais.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/kais.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/kais.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/kais.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/kais.stf', 95, 'player_reset', 'I refuse to help any further, old woman!'),
('string/en/static_npc/dathomir/kais.stf', 96, 'player_sorry', 'What do you require of me again?'),
('string/en/static_npc/dathomir/kais.stf', 97, 'return_waypoint_description_1', 'The Dark Healer is waiting for these poison sacs. Don''t disappoint her.'),
('string/en/static_npc/dathomir/kais.stf', 98, 'return_waypoint_description_2', 'Now that you have the heart, bring it back to Kais'),
('string/en/static_npc/dathomir/kais.stf', 99, 'return_waypoint_description_3', 'Return to the Dark Healer and inform her the deed is done'),
('string/en/static_npc/dathomir/kais.stf', 100, 'return_waypoint_name_1', 'Kais'),
('string/en/static_npc/dathomir/kais.stf', 101, 'return_waypoint_name_2', 'Kais'),
('string/en/static_npc/dathomir/kais.stf', 102, 'return_waypoint_name_3', 'Kais'),
('string/en/static_npc/dathomir/kais.stf', 103, 'waypoint_description_1', 'A Gaping Spider will likely be found here. Tread carefully...'),
('string/en/static_npc/dathomir/kais.stf', 104, 'waypoint_description_2', 'There should be a herd of Malklocs here ripe for the killing'),
('string/en/static_npc/dathomir/kais.stf', 105, 'waypoint_description_3', 'A guard should be waiting for you here to take the poison powder from you'),
('string/en/static_npc/dathomir/kais.stf', 106, 'waypoint_name_1', 'Gaping Spider''s Lair'),
('string/en/static_npc/dathomir/kais.stf', 107, 'waypoint_name_2', 'Malkloc Herd'),
('string/en/static_npc/dathomir/kais.stf', 108, 'waypoint_name_3', 'Coerced Guard'),
('string/en/static_npc/dathomir/kais.stf', 109, 'npc_reset_1', 'Then you are no longer useful to me. If you wish the cure to the poison within your system, prove your worth to me....'),
('string/en/static_npc/dathomir/kais.stf', 110, 'npc_reset_2', 'Then you are no longer useful to me. If you wish the cure to the poison within your system, prove your worth to me....'),
('string/en/static_npc/dathomir/kais.stf', 111, 'npc_reset_3', 'Then you are no longer useful to me. If you wish the cure to the poison within your system, prove your worth to me....'),
('string/en/static_npc/dathomir/kais.stf', 112, 'npc_reset_4', 'Then you are no longer useful to me. If you wish the cure to the poison within your system, prove your worth to me....'),
('string/en/static_npc/dathomir/kais.stf', 113, 'player_reset_1', 'I refuse to help any further, old woman!'),
('string/en/static_npc/dathomir/kais.stf', 114, 'player_reset_2', 'I refuse to help any further, old woman!'),
('string/en/static_npc/dathomir/kais.stf', 115, 'player_reset_3', 'I refuse to help any further, old woman!'),
('string/en/static_npc/dathomir/kais.stf', 116, 'player_reset_4', 'I refuse to help any further, old woman!'),
('string/en/static_npc/dathomir/kais.stf', 117, 'player_sorry_1', 'What do you require of me again?'),
('string/en/static_npc/dathomir/kais.stf', 118, 'player_sorry_2', 'What do you require of me again?'),
('string/en/static_npc/dathomir/kais.stf', 119, 'player_sorry_3', 'What do you require of me again?'),
('string/en/static_npc/dathomir/kais.stf', 120, 'player_sorry_4', 'What do you require of me again?'),
('string/en/static_npc/dathomir/vhaunda.stf', 1, 'cant_work', 'I have a task for you when you''re finished with what you''re doing.'),
('string/en/static_npc/dathomir/vhaunda.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 6, 'next', 'I''m surprised, you actually did alright for yourself. I''ll speak well of your ability.'),
('string/en/static_npc/dathomir/vhaunda.stf', 7, 'notit_1', 'What is this? Stop wasting my time and do what I told you to do.'),
('string/en/static_npc/dathomir/vhaunda.stf', 8, 'notit_2', 'What is this? Stop wasting my time and do what I told you to do.'),
('string/en/static_npc/dathomir/vhaunda.stf', 9, 'notyet', 'Outworlder, I don''t think you cold perform the duties of our weakest man-slave. Come back when, or rather IF you are able to distinguish yourself further.'),
('string/en/static_npc/dathomir/vhaunda.stf', 10, 'npc_1_1', 'It''s an unfortunate necessity that we have to have men on this planet at all. Men who don''t follow orders however, are not tolerated. Perhaps you''d like to show your worth and get rid of a few?'),
('string/en/static_npc/dathomir/vhaunda.stf', 11, 'npc_1_2', 'There are some of us who feel outlanders shouldn''t be held to our standards. I''m not one of them. Neither is my friend Peila. She thinks you don''t know your place and wants to fight a battle of honor with you. I think it would be amusing to watch. What are you going to do?'),
('string/en/static_npc/dathomir/vhaunda.stf', 12, 'npc_2_1', 'Prove you are brave and loyal by bringing me the special shoulder pad from an Imperial patrol leader. My scouts will create a disturbance and lead a patrol to a location not far from here. You should be able to figure out the rest.'),
('string/en/static_npc/dathomir/vhaunda.stf', 13, 'npc_2_2', 'Well then, perhaps this outlander does have honor. Let''s see how well they defend it. Peila will not be hard to find, let me draw you a map here on the ground.'),
('string/en/static_npc/dathomir/vhaunda.stf', 14, 'npc_3_1', 'I don''t know if I should laugh or be disgusted. You could be the most timid mealy mouthed worm to cross my path in a long time.'),
('string/en/static_npc/dathomir/vhaunda.stf', 15, 'npc_3_2', 'Aw, isn''t that too bad. Maybe fighting isn''t for you though? I hear the stables need a good cleaning, maybe that''s more suited to your... er, abilities.'),
('string/en/static_npc/dathomir/vhaunda.stf', 16, 'npc_4_1', 'Honor? The thrill of the hunt? If these do not motivate you I have nothing for you.'),
('string/en/static_npc/dathomir/vhaunda.stf', 17, 'npc_4_2', 'In our clan honor is everything. If you do not value yours, then why are you here, outlander?'),
('string/en/static_npc/dathomir/vhaunda.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 22, 'npc_backtowork_1', 'That outworlder may not be entirely useless after all.'),
('string/en/static_npc/dathomir/vhaunda.stf', 23, 'npc_backtowork_2', 'Oh, by the way... good luck.'),
('string/en/static_npc/dathomir/vhaunda.stf', 24, 'npc_breech_1', 'Situation is normal. I''m taking the patrol back to the outpost.'),
('string/en/static_npc/dathomir/vhaunda.stf', 25, 'npc_breech_2', 'Hah, did you come to fight or beg for mercy?'),
('string/en/static_npc/dathomir/vhaunda.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 28, 'npc_failure_1', 'Hah! Who didn''t see that one coming?'),
('string/en/static_npc/dathomir/vhaunda.stf', 29, 'npc_failure_2', 'Hah! Who didn''t see that one coming?'),
('string/en/static_npc/dathomir/vhaunda.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 36, 'npc_noloc_1', 'I''m a little busy right now. Come back later.'),
('string/en/static_npc/dathomir/vhaunda.stf', 37, 'npc_noloc_2', 'I''m a little busy right now. Come back later.'),
('string/en/static_npc/dathomir/vhaunda.stf', 38, 'npc_reset', 'I don''t know if I should laugh or be disgusted. You could be the most timid mealy mouthed worm to cross my path in a long time.'),
('string/en/static_npc/dathomir/vhaunda.stf', 39, 'npc_reward_1', 'Well then, that''s actually somewhat impressive. For an outworlder. This is going to look pretty good on my armor. Here''s some cash for your trouble.'),
('string/en/static_npc/dathomir/vhaunda.stf', 40, 'npc_reward_2', 'After Peila came to she filled me in on the details of your fight. You did well. It''s too bad you''re not one of us. Take this vibrolance as a gift.'),
('string/en/static_npc/dathomir/vhaunda.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 45, 'npc_work_1', 'I''ve told you all you need to know. Get moving.'),
('string/en/static_npc/dathomir/vhaunda.stf', 46, 'npc_work_2', 'Peila is waiting for you. It would reflect poorly on her if you made her wait.'),
('string/en/static_npc/dathomir/vhaunda.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 49, 'player_1_1', 'What can I do to help?'),
('string/en/static_npc/dathomir/vhaunda.stf', 50, 'player_1_2', 'I will fight.'),
('string/en/static_npc/dathomir/vhaunda.stf', 51, 'player_2_1', 'I can''t do that.'),
('string/en/static_npc/dathomir/vhaunda.stf', 52, 'player_2_2', 'I can''t fight.'),
('string/en/static_npc/dathomir/vhaunda.stf', 53, 'player_3_1', 'What is in it for me?'),
('string/en/static_npc/dathomir/vhaunda.stf', 54, 'player_3_2', 'Why?'),
('string/en/static_npc/dathomir/vhaunda.stf', 55, 'player_4_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 56, 'player_4_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 57, 'player_5_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 58, 'player_5_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/vhaunda.stf', 65, 'player_reset', 'On second thought, I''d rather not.'),
('string/en/static_npc/dathomir/vhaunda.stf', 66, 'player_sorry', 'Yes Vhaunda, right away.'),
('string/en/static_npc/dathomir/vhaunda.stf', 67, 'return_waypoint_description_1', 'Return the shoulderpad to Vhaunda to prove your worth.'),
('string/en/static_npc/dathomir/vhaunda.stf', 68, 'return_waypoint_description_2', 'Return to Vhaunda with news of your victory.'),
('string/en/static_npc/dathomir/vhaunda.stf', 69, 'return_waypoint_name_1', 'Vhaunda'),
('string/en/static_npc/dathomir/vhaunda.stf', 70, 'return_waypoint_name_2', 'Vhaunda'),
('string/en/static_npc/dathomir/vhaunda.stf', 71, 'waypoint_description_1', 'Kill the Imperial patrol leader and remove his shoulder pad.'),
('string/en/static_npc/dathomir/vhaunda.stf', 72, 'waypoint_description_2', 'Fight Peila in honorable battle. '),
('string/en/static_npc/dathomir/vhaunda.stf', 73, 'waypoint_name_1', 'Imperial patrol leader'),
('string/en/static_npc/dathomir/vhaunda.stf', 74, 'waypoint_name_2', 'Peila'),
('string/en/static_npc/dathomir/vhaunda.stf', 75, 'npc_reset_1', 'I don''t know if I should laugh or be disgusted. You could be the most timid mealy mouthed worm to cross my path in a long time.'),
('string/en/static_npc/dathomir/vhaunda.stf', 76, 'npc_reset_2', 'I don''t know if I should laugh or be disgusted. You could be the most timid mealy mouthed worm to cross my path in a long time.'),
('string/en/static_npc/dathomir/vhaunda.stf', 77, 'player_reset_1', 'On second thought, I''d rather not.'),
('string/en/static_npc/dathomir/vhaunda.stf', 78, 'player_reset_2', 'On second thought, I''d rather not.'),
('string/en/static_npc/dathomir/vhaunda.stf', 79, 'player_sorry_1', 'Yes Vhaunda, right away.'),
('string/en/static_npc/dathomir/vhaunda.stf', 80, 'player_sorry_2', 'Yes Vhaunda, right away.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 1, 'cant_work', 'If you''re the Assistant to the Warden the Empire has sent, I need you on the double. I can''t have you running around doing other tings as casually as you please.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 2, 'dontknowyou_1', 'Go.. go away....'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 3, 'dontknowyou_2', 'Thanks for not bringing us back in.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 4, 'dontknowyou_3', 'Please go before I threaten you again.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 5, 'dontknowyou_4', 'Nevermind.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 6, 'gotowork_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 10, 'next', 'You did a good job. It''s a shame you''re trapped here on this planet just as I am am. You could have gone far in the Empire.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 11, 'notit_1', 'What''s this? I don''t remember asking for this? Quit fooling around and get back to work.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 12, 'notit_2', 'What''s this? I don''t need this. What I do need is those inmates back here, and back here on the double.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 13, 'notit_3', 'I didn''t ask for this. Take it back.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 14, 'notit_4', 'I don''t want this. Take it back.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 15, 'notyet', 'I don''t know who you''ve been assigned to, but I know it''s not me. Go find your officer and get back to work.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 16, 'npc_1_1', 'Well, don''t just stand there! You''re the new officer I was told told expect, right? Well, we''ve got ''The Brain'' coming back in. This time, we won''t let him escape. It''s straight to solitary, where he''ll spend the rest of his days. I need you to pick him up, understand?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 17, 'npc_1_2', 'You''ve shown up just in time. We have a prison break and they''re still running around throughout the forests. I''ve sent some troopers to find them, but I''d appreciate it if you helped.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 18, 'npc_1_3', 'I''ve finished interrogating Teen, and it seems he had some outside help. One of those frightening Nightsisters helped Teen and his friends get out. I need you to go take care of here before she steals my shuttle. Can you do it?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 19, 'npc_1_4', 'We have really bad news. ''The Brain'' managed to escape again, but this time he''s made a lot of noise about it. We now have a riot on our hands. I need your help with this.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 20, 'npc_2_1', 'We''ve had to drop him off far from the prison so that the other prisoners dont'' manage to see him. Don''t worry, he''s been given a number of sedatives, so he should be quite willing to come.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 21, 'npc_2_2', 'Thank you. Now look, there should be a couple of them. Bring the guy who looks like the leader of the group. I need to bring him back so he can be made an example in front of the others.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 22, 'npc_2_3', 'Good. Now, I know where she''s going to be. Fortunately, we have time before she can figure out the controls of the ship she''s trying to leave from. You need to make sure she doesn''t leave... ever.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 23, 'npc_2_4', 'We have most of the prisones contained at this point, but there are a group of others that are holding out somewhere. I want them dead.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 24, 'npc_3_1', 'Oh really? If I have the worng person then who are you? I''ve never seen you around here before, which would mean you managed to get here onto this planet somehow. I''m going to take care of this situation, then I''ll have some questions.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 25, 'npc_3_2', 'Same here, but I need as many free hands. The longer they''re out there, the better of a chance they''ll have to secure weapons. They need to be brought back, Think about it, please.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 26, 'npc_3_3', 'I don''t blame you, but I can''t do it myself, either. We have a better chance of surprising her if we send just you, rather than a whole host Stormtroopers. Please reconsider.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 27, 'npc_3_4', 'Look, I need your help. These prisoners are dangerous and could hurt one of you tourists. What do you mean you''re not going to help?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 28, 'npc_4_1', 'You don''t know who The Brain is? His name is Ezker Kennin, and he''s solely responsible for setting free 3 full shipments of Wookie slaves on destined for Kessel. He''s already escaped here once, as well. If the prisoners see that he''s back, that might inspire them.... and I don''t want to see that happen.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 29, 'npc_4_2', 'I still don''t know yet. We found them missing a few hours ago is all we know right now. I know one of them was Teen Queevello, an inmate responsible enough to clean my offices. I don''t know what caused him to rebel.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 30, 'npc_4_3', 'Yes, that is the only possible way off the planet, and the Nightsisters want desperately to leave. By the way, how did you and everyone else manage to get onto this planet?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 31, 'npc_4_4', 'Hope. Plain and simple hope. That''s all it took for the rest of these guys to rise up against us. When the Nightsisters attacked us, we''ve been severely understaffed since then. All the prisoners needed was hope to make them think of rising up against us.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 40, 'npc_backtowork_1', 'You need to hike your buttout to the drop point where we''re bringing in ''The Brain''. Once you have him, bring him back here.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 41, 'npc_backtowork_2', 'You need to go out and find the escaped convicts. Once you find them, bring them back. If they put up a fight, make sure at least one lives.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 42, 'npc_backtowork_3', 'You need to stop the Nightsister from escaping via the only possible way off of this planet.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 43, 'npc_backtowork_4', 'You need to go out there and kill the rioting prisoners.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 44, 'npc_breech_1', 'I feel so wierd.... why can''t think straight? Who are you?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 45, 'npc_breech_2', 'Look, you don''t have to bring us back. Just walk away and let us go!'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 46, 'npc_breech_3', 'I will learn how this magical flying machine works, and you will not stop me!'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 47, 'npc_breech_4', 'Kill any Imperial on sight!'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 48, 'npc_dropoff_1', 'Where is this? Why is it so dark here?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 49, 'npc_dropoff_2', 'Thanks, friend. I hope my screams help you to sleep every night. You could have just let us go.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 50, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 52, 'npc_failure_1', 'You let him escape? Well, I knew that idea was just plain foolish to begin with. Very well... we''ll have to send out the dogs.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 53, 'npc_failure_2', 'You let them all die? That''s not good! Now the inmates won''t believe that they were captured and they all might start getting funny ideas in thier heads.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 54, 'npc_failure_3', 'She managed to escape?? NO!!! Now she might set up a system of shuttles that depart regularly from the planet. Soon, all those witches will leave the planet!!!'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 55, 'npc_failure_4', 'The prisoners have taken over the building? How am I going to explain this.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 68, 'npc_noloc_1', 'Let me check with the flight logs to see  where he was being dropped in. Ask me in a few minutes.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 69, 'npc_noloc_2', 'Let me see if we have any sightings yet on the whereabouts of the prisoners. Ask me again in a few minutes.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 70, 'npc_noloc_3', 'Let me remember where I parked my shuttle. Ask me again in a few minutes.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 71, 'npc_noloc_4', 'Something happened. Ask me again in a few minutes.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 72, 'npc_reset', 'Really now? Did you think I was that dumb? I''m quite familiar with who you are. You just don''t come to Dathomir and expect to leave, friend. Think about that.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 73, 'npc_reward_1', 'Good work. I hope he wasn''t too much trouble for you. Fortunately there hasn''t been anyone talking about him coming back, so the prisoners don''t know he''s here. He''ll be in solitary for the rest of his time here, which like everyone else, is forever.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 74, 'npc_reward_2', 'You were only able to bring Teen back? Very well, this will do. Sadly, Teen was given many liberties most inmates aren''t given. Now he''ll be flogged everyday in front of the other prisoners to show what happens to escapees. Well, good work, friend.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 75, 'npc_reward_3', 'Good. With her being stopped, the Nightsisters will never leave this planet. They are trapped here just like me and you.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 76, 'npc_reward_4', 'Well, now that the riot''s under control, we can start restoring order to the prison again. Thanks for your help, friend.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 77, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 81, 'npc_takeme_1', 'My head... must... think... straight... You''re taking me somewhere, aren''t you?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 82, 'npc_takeme_2', 'Fine... take me back. You know they''ll kill me, right?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 83, 'npc_takeme_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 85, 'npc_work_1', 'Have you brought him into your custody yet?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 86, 'npc_work_2', 'Are you leaving to capture them yet?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 87, 'npc_work_3', 'Why haven''t you stopped her yet?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 88, 'npc_work_4', 'Have you taken care of the prisoners?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 89, 'otherescort_1', 'No, there is another person around here that you''re looking for.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 90, 'otherescort_2', 'I''m not the one you''re looking for.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 91, 'otherescort_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 93, 'player_1_1', 'Yes sir. Where can I find him?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 94, 'player_1_2', 'I''ll go help.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 95, 'player_1_3', 'Sure, I''ll do it.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 96, 'player_1_4', 'I''ll help. '),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 97, 'player_2_1', 'Sorry, you''ve got the wrong person.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 98, 'player_2_2', 'Sorry, that''s a little out of my league.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 99, 'player_2_3', 'I''m not tangling with a Nightsister! No.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 100, 'player_2_4', 'That''s too much for me.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 101, 'player_3_1', 'Who is the prisoner?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 102, 'player_3_2', 'How did they manage to escape?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 103, 'player_3_3', 'You have a shuttle?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 104, 'player_3_4', 'How did this happen?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 105, 'player_4_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 106, 'player_4_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 107, 'player_4_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 108, 'player_4_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 109, 'player_5_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 110, 'player_5_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 111, 'player_5_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 112, 'player_5_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 113, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 114, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 115, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 116, 'player_more_1_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 117, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 118, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 119, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 120, 'player_more_2_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 121, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 122, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 123, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 124, 'player_more_3_4', ''),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 125, 'player_reset', 'I can''t do this. I''m not who you think I am.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 126, 'player_sorry', 'Sir, what was I to do again?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 127, 'return_waypoint_description_1', 'Now bring him back tot he Warden before the drugs wear off'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 128, 'return_waypoint_description_2', 'Bring back the prisoner to the Warden punishment.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 129, 'return_waypoint_description_3', 'The Warden is waiting for you to report back'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 130, 'return_waypoint_description_4', 'Return to let him know that the riot is over'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 131, 'return_waypoint_name_1', 'The Warden'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 132, 'return_waypoint_name_2', 'The Warden'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 133, 'return_waypoint_name_3', 'The Warden'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 134, 'return_waypoint_name_4', 'The Warden'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 135, 'waypoint_description_1', 'You will pick up ''The Brain'' at this location'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 136, 'waypoint_description_2', 'A group of people were spotted around this area.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 137, 'waypoint_description_3', 'You should be able to find the Nightsister here'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 138, 'waypoint_description_4', 'This is where you''ll find a group of rioting prisoners'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 139, 'waypoint_name_1', 'Drugged Prisoner'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 140, 'waypoint_name_2', 'Escaped Fugitives'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 141, 'waypoint_name_3', 'Escaping Nightsister'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 142, 'waypoint_name_4', 'Rioting Prisoners'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 143, 'npc_reset_1', 'Really now? Did you think I was that dumb? I''m quite familiar with who you are. You just don''t come to Dathomir and expect to leave, friend. Think about that.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 144, 'npc_reset_2', 'Really now? Did you think I was that dumb? I''m quite familiar with who you are. You just don''t come to Dathomir and expect to leave, friend. Think about that.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 145, 'npc_reset_3', 'Really now? Did you think I was that dumb? I''m quite familiar with who you are. You just don''t come to Dathomir and expect to leave, friend. Think about that.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 146, 'npc_reset_4', 'Really now? Did you think I was that dumb? I''m quite familiar with who you are. You just don''t come to Dathomir and expect to leave, friend. Think about that.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 147, 'player_reset_1', 'I can''t do this. I''m not who you think I am.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 148, 'player_reset_2', 'I can''t do this. I''m not who you think I am.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 149, 'player_reset_3', 'I can''t do this. I''m not who you think I am.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 150, 'player_reset_4', 'I can''t do this. I''m not who you think I am.'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 151, 'player_sorry_1', 'Sir, what was I to do again?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 152, 'player_sorry_2', 'Sir, what was I to do again?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 153, 'player_sorry_3', 'Sir, what was I to do again?'),
('string/en/static_npc/dathomir/vinzel_haylon.stf', 154, 'player_sorry_4', 'Sir, what was I to do again?'),
('string/en/static_npc/dathomir/vurlene.stf', 1, 'cant_work', 'Hm. Come back later when you are less busy.'),
('string/en/static_npc/dathomir/vurlene.stf', 2, 'dontknowyou_1', 'Meaning no disrespect, but I do not know you.'),
('string/en/static_npc/dathomir/vurlene.stf', 3, 'dontknowyou_2', 'Who are you? I have work to do here, don''t get in my way.'),
('string/en/static_npc/dathomir/vurlene.stf', 4, 'dontknowyou_3', 'Who are you? Get lost.'),
('string/en/static_npc/dathomir/vurlene.stf', 5, 'gotowork_1', 'Weesa havin no more business right now.'),
('string/en/static_npc/dathomir/vurlene.stf', 6, 'gotowork_2', 'Hm, this is a strange salve. But it feels... I''m not sure. But I trust that Vurlene is right about it.'),
('string/en/static_npc/dathomir/vurlene.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 8, 'next', 'Your services have bettered my every expectation. Tell Aujante I recommended you. She will surely wish to speak with you.'),
('string/en/static_npc/dathomir/vurlene.stf', 9, 'notit_1', 'It seems I could have been clearer in my instructions. This is not what I asked for. I''m sorry, but I can not give you anything for this.'),
('string/en/static_npc/dathomir/vurlene.stf', 10, 'notit_2', 'It seems I could have been clearer in my instructions. This is not what I asked for. I''m sorry, but I can not give you anything for this.'),
('string/en/static_npc/dathomir/vurlene.stf', 11, 'notit_3', 'It seems I could have been clearer in my instructions. This is not what I asked for. I''m sorry, but I can not give you anything for this.'),
('string/en/static_npc/dathomir/vurlene.stf', 12, 'notyet', 'I might have something for you to do, but you''re too new here. I don''t know if I can trust you.'),
('string/en/static_npc/dathomir/vurlene.stf', 13, 'npc_1_1', 'Hello outworlder. I have a business proposition for you. You have the ability to leave this planet. That''s very valuable to me. I''m a healer for the clan. There are materials I need for my work on Naboo. I was wondering if you would go there for me?'),
('string/en/static_npc/dathomir/vurlene.stf', 14, 'npc_1_2', 'The algae''s growth is acceptable, it should take well to our rivers and lakes. I''ve had a chance to test it on a few light wounds and the effect, though not as strong as the bacta we''ve acquired from Imperial medics, is still quite noticeable. We are going to need to test this in the field however. Would you care to run a sample out to a fellow healer?'),
('string/en/static_npc/dathomir/vurlene.stf', 15, 'npc_1_3', 'It''s with great sadness that I must again ask for your help. Selia has been slain by a Nightsister patrol. She was... a good friend of mine and I want her avenged. But even more important than that: the salve has been taken. We can not let this secret fall into the hands of the Nightsisters.'),
('string/en/static_npc/dathomir/vurlene.stf', 16, 'npc_2_1', 'That is great news. Ok, this book mentions a "Gungan" on Naboo. He is a holy man of his people by the name of Skub. He is said to have discovered a form of algae with healing properties similar to the derivative elements of bacta. The difference is I believe this particular algae would be well suited to the environs of Dathomir. Travel to Naboo, find this "Gungan" and return with a sample of the algae.'),
('string/en/static_npc/dathomir/vurlene.stf', 17, 'npc_2_2', 'That''s fine. You''ll find Seelia out that way. Give her this salve and tell her to apply a thin smear to light scratches, thickening the layer to match the depth of the wounds.'),
('string/en/static_npc/dathomir/vurlene.stf', 18, 'npc_2_3', 'Hurry. That patrol must not be allowed to return to the Nightsister stronghold. I have no doubt that they will discover the secret of the salve''s making.'),
('string/en/static_npc/dathomir/vurlene.stf', 19, 'npc_3_1', 'Outlander, if you have nothing useful to offer us, I suggest you leave the Singing Mountain Clan alone.'),
('string/en/static_npc/dathomir/vurlene.stf', 20, 'npc_3_2', 'You frustrate me. We could use you as the test subject instead. I''m sure the guards would appreciate the weapon practice. Are you sure you won''t reconsider?'),
('string/en/static_npc/dathomir/vurlene.stf', 21, 'npc_3_3', 'You wait until my moment of most dire need to betray me? Next to your selective loyalty the underhanded tricks of the nightsisters seem honorable.'),
('string/en/static_npc/dathomir/vurlene.stf', 22, 'npc_4_1', 'You may not be aware of what a valuable thing it is to be able to leave this planet. Rest assured I am, and will reward you sufficiently.'),
('string/en/static_npc/dathomir/vurlene.stf', 23, 'npc_4_2', 'Well, I have a packet of strong healing herbs I will give to you. There is also the prospect of monetary compensation.'),
('string/en/static_npc/dathomir/vurlene.stf', 24, 'npc_4_3', 'This is a matter of grave importance, but I am still prepared to reward you for the service.'),
('string/en/static_npc/dathomir/vurlene.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 31, 'npc_backtowork_1', 'Very good. Please try to hurry.'),
('string/en/static_npc/dathomir/vurlene.stf', 32, 'npc_backtowork_2', 'Keep sharp. There is a chance you''ll run afoul of a nightsister patrol out where you''re headed.'),
('string/en/static_npc/dathomir/vurlene.stf', 33, 'npc_backtowork_3', 'You''d best be.'),
('string/en/static_npc/dathomir/vurlene.stf', 34, 'npc_breech_1', 'Look at de beeyutiful nature. So calm.'),
('string/en/static_npc/dathomir/vurlene.stf', 35, 'npc_breech_2', 'These healing supplies are running a bit low. I''m going to have to return to the stronghold soon.'),
('string/en/static_npc/dathomir/vurlene.stf', 36, 'npc_breech_3', 'I dont know what this goop is, but the matriarch demands it. Now shut up, we''re not out of Mountain Clan territory yet.'),
('string/en/static_npc/dathomir/vurlene.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 40, 'npc_failure_1', 'Well, maybe this task was tougher than I thought. Perhaps you will try again?'),
('string/en/static_npc/dathomir/vurlene.stf', 41, 'npc_failure_2', 'Well, maybe this task was tougher than I thought. Perhaps you will try again?'),
('string/en/static_npc/dathomir/vurlene.stf', 42, 'npc_failure_3', 'Well, maybe this task was tougher than I thought. Perhaps you will try again?'),
('string/en/static_npc/dathomir/vurlene.stf', 43, 'npc_more_1_1', 'You are in luck. Here is the algae right here. Skub has plenty. This jar should keep it safe, but try to store it in a dark place.'),
('string/en/static_npc/dathomir/vurlene.stf', 44, 'npc_more_1_2', 'Hm, interesteing. Yes, I''ll give it a try.'),
('string/en/static_npc/dathomir/vurlene.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 52, 'npc_noloc_1', 'Actually, I do not quite have all of my information ready. Let me study a bit. If you return shortly I should have some work for you.'),
('string/en/static_npc/dathomir/vurlene.stf', 53, 'npc_noloc_2', 'Actually, I''m do not quite have all of my information ready. Let me study a bit. If you return shortly I should have some work for you.'),
('string/en/static_npc/dathomir/vurlene.stf', 54, 'npc_noloc_3', 'Actually, I do not quite have all of my information ready. Let me study a bit. If you return shortly I should have some work for you.'),
('string/en/static_npc/dathomir/vurlene.stf', 55, 'npc_reset', 'Well, make your preparations. Come back when you are ready.'),
('string/en/static_npc/dathomir/vurlene.stf', 56, 'npc_reward_1', 'Ah yes, this is it. I''ll introduce a little of this to a pool, as I am told it favors dark, still waters. And as for you... I am pleased to thank you, and to offer these in reward for your services.'),
('string/en/static_npc/dathomir/vurlene.stf', 57, 'npc_reward_2', 'Selia has the salve? Perfect. Now I''ve only to wait for her to return with news. You''ve been a great help, outworlder. Take these healing supplies and credits.'),
('string/en/static_npc/dathomir/vurlene.stf', 58, 'npc_reward_3', 'Ah yes. The salve is safe. It was foolish of me to let it out of the stronghold. I will be more careful in the future. Take these, it''s the least I could do.'),
('string/en/static_npc/dathomir/vurlene.stf', 59, 'npc_smuggle_1', 'I believe I have what you need.'),
('string/en/static_npc/dathomir/vurlene.stf', 60, 'npc_smuggle_2', 'You say you''re from Vurlene? Ah, supplies?'),
('string/en/static_npc/dathomir/vurlene.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 64, 'npc_takeme_3', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/dathomir/vurlene.stf', 65, 'npc_work_1', 'Oh, and one other thing: try to keep the algae in a dark place when you are transporting it.'),
('string/en/static_npc/dathomir/vurlene.stf', 66, 'npc_work_2', 'That salve isn''t going to dry out or anything like that, but Selia might be moving soon. I suggest you hurry.'),
('string/en/static_npc/dathomir/vurlene.stf', 67, 'npc_work_3', 'I''m not trying to be demanding... actually, yes, I am. Get going. This is important.'),
('string/en/static_npc/dathomir/vurlene.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 71, 'player_1_1', 'Why not? I''ll go to Naboo for you.'),
('string/en/static_npc/dathomir/vurlene.stf', 72, 'player_1_2', 'I''ll do it.'),
('string/en/static_npc/dathomir/vurlene.stf', 73, 'player_1_3', 'I will return the salve.'),
('string/en/static_npc/dathomir/vurlene.stf', 74, 'player_2_1', 'No, I don''t think so.'),
('string/en/static_npc/dathomir/vurlene.stf', 75, 'player_2_2', 'I''m not interested.'),
('string/en/static_npc/dathomir/vurlene.stf', 76, 'player_2_3', 'No, I can''t do that.'),
('string/en/static_npc/dathomir/vurlene.stf', 77, 'player_3_1', 'Why should I?'),
('string/en/static_npc/dathomir/vurlene.stf', 78, 'player_3_2', 'What is in it for me?'),
('string/en/static_npc/dathomir/vurlene.stf', 79, 'player_3_3', 'Why?'),
('string/en/static_npc/dathomir/vurlene.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 81, 'player_4_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 84, 'player_5_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 86, 'player_more_1_1', 'Greetings Skub. I''m an aspiring healer and I hear you might know where to find the healing algae.'),
('string/en/static_npc/dathomir/vurlene.stf', 87, 'player_more_1_2', 'Yes, she would like you to try this new healing salve.'),
('string/en/static_npc/dathomir/vurlene.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/vurlene.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/vurlene.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/vurlene.stf', 95, 'player_reset', 'I''m sorry, I''m not ready to help you yet.'),
('string/en/static_npc/dathomir/vurlene.stf', 96, 'player_sorry', 'Thank you. I''ll be going now.'),
('string/en/static_npc/dathomir/vurlene.stf', 97, 'return_waypoint_description_1', 'A Singing Mountain Clan healer.'),
('string/en/static_npc/dathomir/vurlene.stf', 98, 'return_waypoint_description_2', 'Singing Mountain Clan healer'),
('string/en/static_npc/dathomir/vurlene.stf', 99, 'return_waypoint_description_3', 'Singing Mountain Clan healer'),
('string/en/static_npc/dathomir/vurlene.stf', 100, 'return_waypoint_name_1', 'Vurlene'),
('string/en/static_npc/dathomir/vurlene.stf', 101, 'return_waypoint_name_2', 'Vurlene'),
('string/en/static_npc/dathomir/vurlene.stf', 102, 'return_waypoint_name_3', 'Vurlene'),
('string/en/static_npc/dathomir/vurlene.stf', 103, 'waypoint_description_1', 'The Gungan Holy Man Vurlene suspects can provide a sample of a special variety of algae with healing properties.'),
('string/en/static_npc/dathomir/vurlene.stf', 104, 'waypoint_description_2', 'A Singing Mountain Clan healer in need of medical supplies.'),
('string/en/static_npc/dathomir/vurlene.stf', 105, 'waypoint_description_3', 'This is the location of the Nightsister patrol that ambushed Selia.'),
('string/en/static_npc/dathomir/vurlene.stf', 106, 'waypoint_name_1', 'Skub'),
('string/en/static_npc/dathomir/vurlene.stf', 107, 'waypoint_name_2', 'Selia'),
('string/en/static_npc/dathomir/vurlene.stf', 108, 'waypoint_name_3', 'Nightsister Patrol'),
('string/en/static_npc/dathomir/vurlene.stf', 109, 'npc_reset_1', 'Well, make your preparations. Come back when you are ready.'),
('string/en/static_npc/dathomir/vurlene.stf', 110, 'npc_reset_2', 'Well, make your preparations. Come back when you are ready.'),
('string/en/static_npc/dathomir/vurlene.stf', 111, 'npc_reset_3', 'Well, make your preparations. Come back when you are ready.'),
('string/en/static_npc/dathomir/vurlene.stf', 112, 'player_reset_1', 'I''m sorry, I''m not ready to help you yet.'),
('string/en/static_npc/dathomir/vurlene.stf', 113, 'player_reset_2', 'I''m sorry, I''m not ready to help you yet.'),
('string/en/static_npc/dathomir/vurlene.stf', 114, 'player_reset_3', 'I''m sorry, I''m not ready to help you yet.'),
('string/en/static_npc/dathomir/vurlene.stf', 115, 'player_sorry_1', 'Thank you. I''ll be going now.'),
('string/en/static_npc/dathomir/vurlene.stf', 116, 'player_sorry_2', 'Thank you. I''ll be going now.'),
('string/en/static_npc/dathomir/vurlene.stf', 117, 'player_sorry_3', 'Thank you. I''ll be going now.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 1, 'cant_work', 'You seem to be quite busy. When you have some time, please stop by again. I may have need of your skills.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 2, 'dontknowyou_1', 'Except for you, that is. I only kill people I don''t like.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 3, 'dontknowyou_2', 'Please? Could you please go already? Pretty, pretty please?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 4, 'dontknowyou_3', 'Look, get out of the way! You''re going to ruin this for the other guy!'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 8, 'next', 'Your help has been most appreciated. When I am done with my dissection, I will make it a point to refer to you in my report to the Emperor.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 9, 'notit_1', 'This is not what I asked for.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 10, 'notit_2', 'No, this isn''t one of those odd stones.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 11, 'notit_3', 'I''m sorry, but I didn''t ask for this. You can have it back.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 12, 'notyet', 'You are not worth my time. Please go away.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 13, 'npc_1_1', 'Greetings. I am Xarot Korlin, Imperial Inquisitor here on Dathomir. I have been studying the way the indigenous witches use this so called "magic", and I wish to learn more. Are you willing to help me?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 14, 'npc_1_2', 'Well, I was unable to discern anything special from that stone. I am still confused as to how these witches work their "magic". But, I am not ready to stop researching. Can you help acquire another stone for me?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 15, 'npc_1_3', 'My studies have turned up nothing. Nothing at all, I tell you! But... I have not risen to this office without diligence. I have one last request of you, if you are available?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 16, 'npc_2_1', 'Good. I need you to go venture within Nightsister territory and find one of them unawares. Once you have killed her, hopefully with little resistance, bring back the stone in her headdress, for that will help my studies.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 17, 'npc_2_2', 'You help will surely speed up my research, and provide much discretion to the prying eye. I would like a stone to compare with the one you already brought to me. I will need one from a Singing Mountain Clan sister now.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 18, 'npc_2_3', 'I am convinced those crystals are the source of their misnamed "magic". I think they work in conjuncton with their brains, therefore I need a living Nightsister so finish my experiments. Please bring one back to me.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 19, 'npc_3_1', 'Well, when you have some time, stop by. I can always use the help.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 20, 'npc_3_2', 'Please understand that I cannot do this myself. With your help, I may be able to solve this mystery, which may provide a great reward from the Emperor himself.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 21, 'npc_3_3', 'Please reconsider. I am only asking this one last thing of you.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 22, 'npc_4_1', 'I have noticed that many of these witches wear elaborate headdresses. I have been told that within these hats, they contain a special stone. I believe that this stone is the source of their "magic".'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 23, 'npc_4_2', 'Even though it''s temperature is below what one should expect, I haven''t been able to discern anything else. I am still positive that these stones do something. Perhaps this magic is a variant of the Force that the former Jedi once used.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 24, 'npc_4_3', 'Well, these stones do nothing by themselves, for I haven''t been able to activate them at all. At this point I think they work in tandem with the pulses of the Sister''s brains. Sadly, I don''t have one of their brains on me right now.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 31, 'npc_backtowork_1', 'You need to dispose of a Nightsister, then bring back the stone in her headdress.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 32, 'npc_backtowork_2', 'You need to find one of the Singing Mountain Clan Sisters and take the stone from her headdress.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 33, 'npc_backtowork_3', 'I would appreciate it if you were able to bring one of the Sisters to me so that I can operate on her.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 34, 'npc_breech_1', 'What are you doing here? All trespassers will die!'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 35, 'npc_breech_2', 'If you do not leave, I will be forced to act. Leave now!'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 36, 'npc_breech_3', 'What are you doing here? My pet, attack them!'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 39, 'npc_dropoff_3', 'What? Who are you and what do you plan on doing with me? '),
('string/en/static_npc/dathomir/xarot_korlin.stf', 40, 'npc_failure_1', 'You weren''t able to find one of those stones? I guess I''ll need to hire someone more competant than you.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 41, 'npc_failure_2', 'She didn''t have a stone on her? How odd... I would have thought that the Singing Mountain Clan would have had similar customs as the Nightsisters.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 42, 'npc_failure_3', 'Your hunt turned up nothing? My research is here at it''s most critical stage, and yet I have o subject to experiment on! Woe is me!'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 52, 'npc_noloc_1', 'Let me prepare my are before I send you out on this. Please check back with me in a few minutes.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 53, 'npc_noloc_2', 'Let me prepare the my area so that I can study these. Ask me in a few minutes.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 54, 'npc_noloc_3', 'Let me prepare my interrogation table, which will be doubling as an impromptu operation table. Ask me again in a few minutes.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 55, 'npc_reset', 'Why? Was it something I said?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 56, 'npc_reward_1', 'Yes, this is exactly as it was described. I will now be able to study what effects it has on other forms of matter. Thank you for helping, friend.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 57, 'npc_reward_2', 'Yes yes yes... now that I have this stone, I can compare it''s properties with the first one. I need to get to work now, for the faster I can do this, the faster I can have results. Thank you, friend.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 58, 'npc_reward_3', 'Yes, yes... welcome, my dear. No need to worry, this won''t hurt for too long. As for you, my friend, I thank you for all your help. Now, if you would excuse me, I need to prepare for a lobotomy surgery now.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 64, 'npc_takeme_3', 'How dare you presume to arrest me! Take me to your Officer now!'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 65, 'npc_work_1', 'Have you found one of those stones yet?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 66, 'npc_work_2', 'Do you have the other stone?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 67, 'npc_work_3', 'Yes?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 70, 'otherescort_3', 'Oh, I''m dreadfully sorry, but I think you were looking for another Nightsister.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 71, 'player_1_1', 'Sure, I''ll help.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 72, 'player_1_2', 'No problem. I''ll do it.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 73, 'player_1_3', 'I might as well. Yes, I''ll help.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 74, 'player_2_1', 'No, I''m busy.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 75, 'player_2_2', 'No, once was enough.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 76, 'player_2_3', 'No, I''m not.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 77, 'player_3_1', 'What exactly are you studying?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 78, 'player_3_2', 'What did you learn from the first stone?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 79, 'player_3_3', 'What have your studies shown you?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 80, 'player_4_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 81, 'player_4_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 82, 'player_4_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 83, 'player_5_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 84, 'player_5_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 85, 'player_5_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/dathomir/xarot_korlin.stf', 95, 'player_reset', 'I cannot help you any more.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 96, 'player_sorry', 'What did I need to do again?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 97, 'return_waypoint_description_1', 'Xarot is here, anxiously awaiting the Force Crystal for further examination.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 98, 'return_waypoint_description_2', 'Return to Xarot with the Crystal so that he may continue his studies.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 99, 'return_waypoint_description_3', 'Return to thhe Inquisitor with your live test subject'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 100, 'return_waypoint_name_1', 'Inquisitor Xarot'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 101, 'return_waypoint_name_2', 'Inquisitor Xarot'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 102, 'return_waypoint_name_3', 'Inquisitor Xarot'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 103, 'waypoint_description_1', 'A Nightsister is gathering herbs here, completely unaware of what is about to happen.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 104, 'waypoint_description_2', 'You should be able to find a Singing Mountain Clan sister at this area.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 105, 'waypoint_description_3', 'Kidnap the Nightsister that waits at this location'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 106, 'waypoint_name_1', 'Nightsister Ambush'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 107, 'waypoint_name_2', 'Singing Sister Ambush'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 108, 'waypoint_name_3', 'Nightsister Kidnapping'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 109, 'npc_reset_1', 'Why? Was it something I said?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 110, 'npc_reset_2', 'Why? Was it something I said?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 111, 'npc_reset_3', 'Why? Was it something I said?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 112, 'player_reset_1', 'I cannot help you any more.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 113, 'player_reset_2', 'I cannot help you any more.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 114, 'player_reset_3', 'I cannot help you any more.'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 115, 'player_sorry_1', 'What did I need to do again?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 116, 'player_sorry_2', 'What did I need to do again?'),
('string/en/static_npc/dathomir/xarot_korlin.stf', 117, 'player_sorry_3', 'What did I need to do again?'),
('string/en/static_npc/default_dialog.stf', 1, 'quit_quest', 'I can see that you''re busy working for someone else at the moment.  Would you like to continue to do so, or would you like to work for me instead?'),
('string/en/static_npc/default_dialog.stf', 2, 'player_quit', 'I think I''d like to work for you.'),
('string/en/static_npc/default_dialog.stf', 3, 'player_continue', 'No, I think I''ll keep my current job, thanks.'),
('string/en/static_npc/default_dialog.stf', 4, 'npc_quit', 'Fine.  You are now free of your prior obligation, and you can freely work for me.'),
('string/en/static_npc/default_dialog.stf', 5, 'npc_continue', 'Fine then.  Don''t bother with me until you''re ready to work for me.'),
('string/en/static_npc/default_dialog.stf', 6, 'too_weak', 'The task I have seems beyond your capabilities. Come back when you''re a bit stronger.'),
('string/en/static_npc/default_dialog.stf', 7, 'too_strong', 'This task is beneath your capabilities.  Are you sure you want to do it?'),
('string/en/static_npc/default_dialog.stf', 8, 'its_ok', 'I want the task anyway.'),
('string/en/static_npc/endor/charal.stf', 1, 'cant_work', 'Yes, you have arrived as I felt within myself. My visions tell me that you are offering yourself, yet you serve another. When you realize your true mistress, you will come to me, yes....'),
('string/en/static_npc/endor/charal.stf', 2, 'dontknowyou_1', 'Kuba!'),
('string/en/static_npc/endor/charal.stf', 3, 'dontknowyou_2', 'Me not know you. Mistress no send you.'),
('string/en/static_npc/endor/charal.stf', 4, 'dontknowyou_3', 'Samooto! Nub-nub!'),
('string/en/static_npc/endor/charal.stf', 5, 'dontknowyou_4', 'Please, go get help! We''ve crash landed!'),
('string/en/static_npc/endor/charal.stf', 6, 'gotowork_1', ''),
('string/en/static_npc/endor/charal.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/endor/charal.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/endor/charal.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/endor/charal.stf', 10, 'next', 'It is time for you to move further, is it not? Continue along your destiny, and you shall serve mine...'),
('string/en/static_npc/endor/charal.stf', 11, 'notit_1', 'What? Does this look like a spleen to you? Do you even know what a spleen looks like?'),
('string/en/static_npc/endor/charal.stf', 12, 'notit_2', 'What, you offer me such a paltry gift? Take it back, insect.'),
('string/en/static_npc/endor/charal.stf', 13, 'notit_3', 'You utter moron! I told you to bring me an Ewok, and you give me this? Get out of my sight and do as I say!'),
('string/en/static_npc/endor/charal.stf', 14, 'notit_4', 'Is this the "commlink"? I don''t how to use one.... SLAVE!!! Show me how to use this!'),
('string/en/static_npc/endor/charal.stf', 15, 'notyet', 'No, no.... you are not to speak with me yet... in time, my pretty, in time.'),
('string/en/static_npc/endor/charal.stf', 16, 'npc_1_1', 'Hello there.... You have the distinct honor of being spoken to by Charal, Witch-Queen of this god-forsaken moon. You have come to serve my desires, have you not?'),
('string/en/static_npc/endor/charal.stf', 17, 'npc_1_2', 'I have need of your services once again, my dearest. My poultice that will allow me to divine the future now needs the next ingredient. I will be pleased if you find my slave whom hasn''t returned with it yet. Will you, my pretty?'),
('string/en/static_npc/endor/charal.stf', 18, 'npc_1_3', 'Yes... my poultice is nearing the final stage. You have returned with perfect timing, my dearie. I command you to return with an Ewok so that it may provide the final ingredient.'),
('string/en/static_npc/endor/charal.stf', 19, 'npc_1_4', 'Mwuhahahaa..... my potion was a success.  I was able to forsee many visions due to my power as a Sister. I have one last command for you, slave... then I shall actually release you, as per my vision.'),
('string/en/static_npc/endor/charal.stf', 20, 'npc_2_1', 'Yes, my pretty, you have made the correct choice. I am in need of a spleen from a healthy specimen of those disgusting rodents, Ewoks. Bring me back a speen and you will please me.'),
('string/en/static_npc/endor/charal.stf', 21, 'npc_2_2', 'You should be able to find him out within the forests. Do not be afraid when you gaze upon him, he is a Lizard man that was stranded here as well. Tell him to follow you back here.'),
('string/en/static_npc/endor/charal.stf', 22, 'npc_2_3', 'Yes, yes you do...  now go and bring me an Ewok. Make sure you don''t harm it too much... I need one globule of spittle from it''s vicious little fangs.'),
('string/en/static_npc/endor/charal.stf', 23, 'npc_2_4', 'You are such a wonderful little slave, ahh... Now, go find a group of recently crashed survivalists who have an item that is called a "comm-link". With this item I will be able to escape this planet.'),
('string/en/static_npc/endor/charal.stf', 24, 'npc_3_1', 'What? How dare you speak to me in that way! I am of half a mind to use your spleen instead!'),
('string/en/static_npc/endor/charal.stf', 25, 'npc_3_2', 'It wouldn''t take much to make you interested, my pretty. Now, I like my slaves -er- friends to believe that they have a choice... choose differently this time.'),
('string/en/static_npc/endor/charal.stf', 26, 'npc_3_3', 'Oh... it seems the compulsion doesn''t have you as much as I expected it to. Perhaps if you would like to listen to a little song, eh?'),
('string/en/static_npc/endor/charal.stf', 27, 'npc_3_4', 'How. Dare. You. How dare you!!! HOW DARE YOU!!!!! I''ll give you to the count of five, then I shall begin singing.... run, little rabbit, run....'),
('string/en/static_npc/endor/charal.stf', 28, 'npc_4_1', 'Who would? This blighted excuse for a moon is not what I had in mind when I escaped from my homeplanet of Dathomir.  After my concoction has come to completion, I will know how much longer I must remain upon this nightmare of a world. Have you chosen yet?'),
('string/en/static_npc/endor/charal.stf', 29, 'npc_4_2', 'My slave has a very keen nose for a certain type of herb that grows within the forest, He should have enough of the fresh leaves by now, but he is rather dumb so he hasn''t returned. What I would give for a more intelligent slave.'),
('string/en/static_npc/endor/charal.stf', 30, 'npc_4_3', 'How dare you question me? I am your master, worm, not the other way around. You could not begin to understand the great mysteries I and my sisters possess. Therefore, do not presume to wonder why I give you that request. You will do as I command!'),
('string/en/static_npc/endor/charal.stf', 31, 'npc_4_4', 'Oh... how cute. It just asked my about my vision, as if it could even begin to understand. Well, worm, my vision showed me many ships landing on this planet in the near future. I will use a fabled "commlink" to steal these ships.... then I can leave these filthy Marauders for good. Now do as I say!'),
('string/en/static_npc/endor/charal.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/endor/charal.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/endor/charal.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/endor/charal.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/endor/charal.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/endor/charal.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/endor/charal.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/endor/charal.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/endor/charal.stf', 40, 'npc_backtowork_1', 'You are to find me the spleen of a healthy Ewok. I just need its spleen... you may throw the rest away.'),
('string/en/static_npc/endor/charal.stf', 41, 'npc_backtowork_2', 'You are to go fetch my slave, Lizardman. Don''t  make me create another slave to go fetch you as well!'),
('string/en/static_npc/endor/charal.stf', 42, 'npc_backtowork_3', 'You simpleton! I told you that I demand you bring me an Ewok so that I can squeeze a fleckle of spit from its body. Now go!'),
('string/en/static_npc/endor/charal.stf', 43, 'npc_backtowork_4', 'I just told you! Get me that fabled commlink! With the power of technology, I will be Queen of this moon!'),
('string/en/static_npc/endor/charal.stf', 44, 'npc_breech_1', 'Oooka matoota keebo keebo!'),
('string/en/static_npc/endor/charal.stf', 45, 'npc_breech_2', 'Urgg... who you? You sent by the Mistress?'),
('string/en/static_npc/endor/charal.stf', 46, 'npc_breech_3', 'Mooka pentootie kabbaata!!! Keepoto!!'),
('string/en/static_npc/endor/charal.stf', 47, 'npc_breech_4', 'We''re saved!!!! Hooray!!! Hey.... what are you doing with that blaster?'),
('string/en/static_npc/endor/charal.stf', 48, 'npc_dropoff_1', ''),
('string/en/static_npc/endor/charal.stf', 49, 'npc_dropoff_2', 'Urgg... Mistress... I have plant for you... I did not try to escape... I''m good Trandoshan, right?'),
('string/en/static_npc/endor/charal.stf', 50, 'npc_dropoff_3', 'Giiiboota!'),
('string/en/static_npc/endor/charal.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/endor/charal.stf', 52, 'npc_failure_1', 'WHAT?! What do you mean you weren''t able to find an Ewok spleen? These forests are crawling with the putrid little creatures!'),
('string/en/static_npc/endor/charal.stf', 53, 'npc_failure_2', 'WHAT!?!? You let my lizard slave get killed? How is that even possible!?'),
('string/en/static_npc/endor/charal.stf', 54, 'npc_failure_3', 'Aiiiiiieeeeee!!!! You let the thing escape?! You have but a few moments before I sing a song that will flay the skin from your bones.... hmmm... perhaps your spittle may do....'),
('string/en/static_npc/endor/charal.stf', 55, 'npc_failure_4', 'What?!! They didn''t have the commlink? My visions lied?!?! NOOOOOOooooo.......'),
('string/en/static_npc/endor/charal.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/endor/charal.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/endor/charal.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/endor/charal.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/endor/charal.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/endor/charal.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/endor/charal.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/endor/charal.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/endor/charal.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/endor/charal.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/endor/charal.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/endor/charal.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/endor/charal.stf', 68, 'npc_noloc_1', 'Let me hum a spell so that I may concentrate on where to find a healthy ewok. Ask me again in a few minutes.'),
('string/en/static_npc/endor/charal.stf', 69, 'npc_noloc_2', 'Let me think as to where Lizardman might be right now. Ask me again in a few minutes.'),
('string/en/static_npc/endor/charal.stf', 70, 'npc_noloc_3', 'Now, let me think where you might be able to find an Ewok. Ask me again in a few minutes.'),
('string/en/static_npc/endor/charal.stf', 71, 'npc_noloc_4', 'Let me think about where my vision told me the survivalists are. Check back with me shortly.'),
('string/en/static_npc/endor/charal.stf', 72, 'npc_reset', 'Bah! You''re worthless! Wait... perhaps not. Mayhaps you might make for a tasty meal...'),
('string/en/static_npc/endor/charal.stf', 73, 'npc_reward_1', '*sniff sniff* Yes... yes, this will do. Once this is added to my poultice, I''ll know if I should continue working with this fool of a Marauder! You have served me well.'),
('string/en/static_npc/endor/charal.stf', 74, 'npc_reward_2', 'Yes, there you are Lizardman... you have stayed out for far too long. Are you alright? Good... Now give me those leaves!!!! As for you, servant - er -  friend... you have done well.'),
('string/en/static_npc/endor/charal.stf', 75, 'npc_reward_3', 'Good, good, good... now that I have this little runt, it won''t be too long to coax a little spit from it''s maw. You have done well... I will have need of you when I am done.'),
('string/en/static_npc/endor/charal.stf', 76, 'npc_reward_4', 'Yes!!! With this commlink I can command power over the very Universe itself!!! All I have to do is wait for the first ship to land on this moon. As for you... my vision has shown that you must leave me. A shame, too... you were my favorite.'),
('string/en/static_npc/endor/charal.stf', 77, 'npc_smuggle_1', ''),
('string/en/static_npc/endor/charal.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/endor/charal.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/endor/charal.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/endor/charal.stf', 81, 'npc_takeme_1', ''),
('string/en/static_npc/endor/charal.stf', 82, 'npc_takeme_2', 'Why you talk better than other slaves? OW!!! Head hurrrrrt..... just take me back.'),
('string/en/static_npc/endor/charal.stf', 83, 'npc_takeme_3', 'Mahhhh... kaptootie!'),
('string/en/static_npc/endor/charal.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/endor/charal.stf', 85, 'npc_work_1', 'Why do I not smell an Ewok spleen on you?'),
('string/en/static_npc/endor/charal.stf', 86, 'npc_work_2', 'Why do I not see Lizardman?'),
('string/en/static_npc/endor/charal.stf', 87, 'npc_work_3', 'Where is that Ewok?'),
('string/en/static_npc/endor/charal.stf', 88, 'npc_work_4', 'Why are you here!? Get me that "commlink"!'),
('string/en/static_npc/endor/charal.stf', 89, 'otherescort_1', ''),
('string/en/static_npc/endor/charal.stf', 90, 'otherescort_2', 'Whaaaaah? Wrong Trandoshan... look around for right one.'),
('string/en/static_npc/endor/charal.stf', 91, 'otherescort_3', 'Moko, moko.'),
('string/en/static_npc/endor/charal.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/endor/charal.stf', 93, 'player_1_1', 'Ummm... I guess so. Sure, I''ll serve you.'),
('string/en/static_npc/endor/charal.stf', 94, 'player_1_2', 'Yes, I''ll do it, my lady.'),
('string/en/static_npc/endor/charal.stf', 95, 'player_1_3', 'I do as you command, great Mistress.'),
('string/en/static_npc/endor/charal.stf', 96, 'player_1_4', 'I live only to obey, my dark Mistress.'),
('string/en/static_npc/endor/charal.stf', 97, 'player_2_1', 'Sorry, I don''t serve anyone! No!'),
('string/en/static_npc/endor/charal.stf', 98, 'player_2_2', 'No thanks. I''m not interested.'),
('string/en/static_npc/endor/charal.stf', 99, 'player_2_3', 'Command me? No one commands me! No!'),
('string/en/static_npc/endor/charal.stf', 100, 'player_2_4', 'Did you just call me your slave?! Do it yourself, witch.'),
('string/en/static_npc/endor/charal.stf', 101, 'player_3_1', 'You don''t want to be here on Endor?'),
('string/en/static_npc/endor/charal.stf', 102, 'player_3_2', 'What do you need with your slave?'),
('string/en/static_npc/endor/charal.stf', 103, 'player_3_3', 'Why do you need another Ewok?'),
('string/en/static_npc/endor/charal.stf', 104, 'player_3_4', 'What were your visions about?'),
('string/en/static_npc/endor/charal.stf', 105, 'player_4_1', ''),
('string/en/static_npc/endor/charal.stf', 106, 'player_4_2', ''),
('string/en/static_npc/endor/charal.stf', 107, 'player_4_3', ''),
('string/en/static_npc/endor/charal.stf', 108, 'player_4_4', ''),
('string/en/static_npc/endor/charal.stf', 109, 'player_5_1', ''),
('string/en/static_npc/endor/charal.stf', 110, 'player_5_2', ''),
('string/en/static_npc/endor/charal.stf', 111, 'player_5_3', ''),
('string/en/static_npc/endor/charal.stf', 112, 'player_5_4', ''),
('string/en/static_npc/endor/charal.stf', 113, 'player_more_1_1', ''),
('string/en/static_npc/endor/charal.stf', 114, 'player_more_1_2', ''),
('string/en/static_npc/endor/charal.stf', 115, 'player_more_1_3', ''),
('string/en/static_npc/endor/charal.stf', 116, 'player_more_1_4', ''),
('string/en/static_npc/endor/charal.stf', 117, 'player_more_2_1', ''),
('string/en/static_npc/endor/charal.stf', 118, 'player_more_2_2', ''),
('string/en/static_npc/endor/charal.stf', 119, 'player_more_2_3', ''),
('string/en/static_npc/endor/charal.stf', 120, 'player_more_2_4', ''),
('string/en/static_npc/endor/charal.stf', 121, 'player_more_3_1', ''),
('string/en/static_npc/endor/charal.stf', 122, 'player_more_3_2', ''),
('string/en/static_npc/endor/charal.stf', 123, 'player_more_3_3', ''),
('string/en/static_npc/endor/charal.stf', 124, 'player_more_3_4', ''),
('string/en/static_npc/endor/charal.stf', 125, 'player_reset', 'I''m unable to continue doing this, my lady.'),
('string/en/static_npc/endor/charal.stf', 126, 'player_sorry', 'What was your desire again?'),
('string/en/static_npc/endor/charal.stf', 127, 'return_waypoint_description_1', 'Charal is waiting for that spleen. Don''t keep her waiting.'),
('string/en/static_npc/endor/charal.stf', 128, 'return_waypoint_description_2', 'Charal is waiting for those herbs. Don''t keep her waiting.'),
('string/en/static_npc/endor/charal.stf', 129, 'return_waypoint_description_3', 'Charal is waiting for that Ewok''s precious salivary glands. Don''t keep her waiting.'),
('string/en/static_npc/endor/charal.stf', 130, 'return_waypoint_description_4', 'Return with the "commlink" and Charal will break your compulsion as your reward.'),
('string/en/static_npc/endor/charal.stf', 131, 'return_waypoint_name_1', 'Charal'),
('string/en/static_npc/endor/charal.stf', 132, 'return_waypoint_name_2', 'Charal'),
('string/en/static_npc/endor/charal.stf', 133, 'return_waypoint_name_3', 'Charal'),
('string/en/static_npc/endor/charal.stf', 134, 'return_waypoint_name_4', 'Charal'),
('string/en/static_npc/endor/charal.stf', 135, 'waypoint_description_1', 'Ewoks have been rumored to appear near here'),
('string/en/static_npc/endor/charal.stf', 136, 'waypoint_description_2', 'Charal''s slave should be somewhere around here'),
('string/en/static_npc/endor/charal.stf', 137, 'waypoint_description_3', 'Charal believes you can find some Ewoks in this general vicinity.'),
('string/en/static_npc/endor/charal.stf', 138, 'waypoint_description_4', 'You should be able to find the survivalists somewhere nearby this crash site.'),
('string/en/static_npc/endor/charal.stf', 139, 'waypoint_name_1', 'Ewok Sighting'),
('string/en/static_npc/endor/charal.stf', 140, 'waypoint_name_2', 'Charal''s Lizardman'),
('string/en/static_npc/endor/charal.stf', 141, 'waypoint_name_3', 'Ewok Sighting'),
('string/en/static_npc/endor/charal.stf', 142, 'waypoint_name_4', 'Crash Landing'),
('string/en/static_npc/endor/charal.stf', 143, 'player_reset_1', 'I''m unable to continue doing this, my lady.'),
('string/en/static_npc/endor/charal.stf', 144, 'player_reset_2', 'I''m unable to continue doing this, my lady.'),
('string/en/static_npc/endor/charal.stf', 145, 'player_sorry_1', 'What was your desire again?'),
('string/en/static_npc/endor/charal.stf', 146, 'player_sorry_2', 'What was your desire again?'),
('string/en/static_npc/endor/charal.stf', 147, 'npc_reset_1', 'Bah! You''re worthless! Wait... perhaps not. Mayhaps you might make for a tasty meal...'),
('string/en/static_npc/endor/charal.stf', 148, 'npc_reset_2', 'Bah! You''re worthless! Wait... perhaps not. Mayhaps you might make for a tasty meal...'),
('string/en/static_npc/endor/charal.stf', 149, 'npc_reset_3', 'Bah! You''re worthless! Wait... perhaps not. Mayhaps you might make for a tasty meal...'),
('string/en/static_npc/endor/charal.stf', 150, 'npc_reset_4', 'Bah! You''re worthless! Wait... perhaps not. Mayhaps you might make for a tasty meal...'),
('string/en/static_npc/endor/charal.stf', 151, 'player_reset_3', 'I''m unable to continue doing this, my lady.'),
('string/en/static_npc/endor/charal.stf', 152, 'player_reset_4', 'I''m unable to continue doing this, my lady.'),
('string/en/static_npc/endor/charal.stf', 153, 'player_sorry_3', 'What was your desire again?'),
('string/en/static_npc/endor/charal.stf', 154, 'player_sorry_4', 'What was your desire again?'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 1, 'cant_work', 'You are busy. Come back when you are not.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 2, 'dontknowyou_1', 'Get lost! I''m busy!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 3, 'dontknowyou_2', 'Go! Or we may decide to eat you!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 4, 'dontknowyou_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 8, 'next', 'I have nothing else for you at the moment. Come back later and perhaps I''ll have more.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 9, 'notit_1', 'This is not the weapon my scouts described to me. Bring me that weapon!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 10, 'notit_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 11, 'notit_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 12, 'notyet', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 13, 'npc_1_1', 'If you have come to see me, then you have come to work. I am in need of a weapon. Our scouts encountered a group of pirates. It is likely their ship was shot down. Their leader used an interesting weapon. It disintegrated one of our warriors. Kill this pirate leader and bring me his weapon.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 14, 'npc_1_2', 'That blasted witch, Charal, raided the pirates'' crashed ship. She destroyed the wreckage to insure I would not find anything else. The Marauders who carried out her orders must pay for their treachery. Find them and obliterate them. Marauders should be loyal to King Terak alone!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 15, 'npc_1_3', 'King Terak was not pleased by the deaths of his men. Unfortunately, the witch Charal used her sorcery to prove she had nothing to do with the attack. But Terak will forgive this insult if you take care of an arachne that has been attacking our outposts.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 16, 'npc_2_1', 'Good. These pirates managed to fight off several Marauder warriors. It is my hope that you have better luck. '),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 17, 'npc_2_2', 'Do not worry. I will shield you from King Terak''s rage once he hears that his men have been killed. I will make it seem as if Charal''s treachery was responsible for their deaths.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 18, 'npc_2_3', 'You are wiser than you look. Report back to me once the spider is dead.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 19, 'npc_3_1', 'If you will not work, then you are no different from prey. Leave at once or I shall see what you taste like.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 20, 'npc_3_2', 'I grow hungrier by the minute! Leave, worthless fool!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 21, 'npc_3_3', 'I would not stay on Endor if I were you. King Terak is not a forgiving sort.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 22, 'npc_4_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 23, 'npc_4_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 24, 'npc_4_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 31, 'npc_backtowork_1', 'Why do you just stand around?'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 32, 'npc_backtowork_2', 'There is no time to waste! Hurry and do my bidding!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 33, 'npc_backtowork_3', 'Hurry, before King Terak decides to take out his anger on both our hides!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 34, 'npc_breech_1', 'That''s not one of our own! Blast this creature to pieces, lads!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 35, 'npc_breech_2', 'Kill that one! We will feast tonight!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 36, 'npc_breech_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 40, 'npc_failure_1', 'Those who fail me do not live long. You are lucky I am not King Terak.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 41, 'npc_failure_2', 'How could you have let these fools escape with their lives? You are of no use to me!'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 42, 'npc_failure_3', 'I shall blame you for the deaths of King Terak''s warriors. Had you killed the beast of many legs this would not have been an issue.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 52, 'npc_noloc_1', 'I will verify the pirates'' last known location. Come back later.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 53, 'npc_noloc_2', 'I must find out where these Marauders have gone. '),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 54, 'npc_noloc_3', 'King Terak wishes an audience with me. Come back later.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 55, 'npc_reset', 'Bah! Go away and do not return unless you intend to finish what you begin.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 56, 'npc_reward_1', 'You have done well. Continue to serve me well and you shall continue to be rewarded.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 57, 'npc_reward_2', 'You are an obedient servant. You serve me well.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 58, 'npc_reward_3', 'Well done. King Terak will soon forget the loss of his warriors once he hears the news of the arachne''s death.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 59, 'npc_smuggle_1', ''),
