('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 65, 'npc_work_1', 'Where is that weapon? I must study it and learn its secrets.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 66, 'npc_work_2', 'Are the traitorous Marauders dead?'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 67, 'npc_work_3', 'Is the spider dead? Why not?'),
