('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 106, 'waypoint_name_1', 'Pirate Captain''s Location'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 107, 'waypoint_name_2', 'Marauder Scout Leader''s Location'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 108, 'waypoint_name_3', 'Arachne''s Location'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 109, 'npc_reset_1', 'Bah! Go away and do not return unless you intend to finish what you begin.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 110, 'npc_reset_2', 'Bah! Go away and do not return unless you intend to finish what you begin.'),
