('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 112, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/endor/endor_maraudercitadel_scholar_szingo.stf', 113, 'player_reset_2', 'I don''t want this mission right now.'),
