('string/en/static_npc/endor/endor_moragscastle_morag.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 93, 'player_1_1', 'Yes'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 94, 'player_1_2', 'Yes'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 95, 'player_1_3', 'Yes'),
