('string/en/static_npc/endor/endor_moragscastle_morag.stf', 100, 'player_2_4', 'No'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 101, 'player_3_1', 'What did it steal?'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 102, 'player_3_2', 'So it was a crystal that got stolen, eh?'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 103, 'player_3_3', 'Why do you hate the Ewoks so much?'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 104, 'player_3_4', 'Will it bring you joy to make them suffer?'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 105, 'player_4_1', ''),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 106, 'player_4_2', ''),
