('string/en/static_npc/endor/endor_moragscastle_morag.stf', 126, 'player_sorry', 'I''ll keep working on the mission.'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 127, 'return_waypoint_description_1', 'Return Chuva to Morag for interrogation.'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 128, 'return_waypoint_description_2', 'Bring the crystal back to Morag '),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 129, 'return_waypoint_description_3', 'Inform Morag of Tibik''s untimely demise'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 130, 'return_waypoint_description_4', 'Return to Morag and inform her of Binbin''s tragic death.'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 131, 'return_waypoint_name_1', 'Morag'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 132, 'return_waypoint_name_2', 'Morag'),
