('string/en/static_npc/endor/endor_moragscastle_morag.stf', 135, 'waypoint_description_1', 'Find the Ewok Chuva'),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 136, 'waypoint_description_2', 'Go find Corba and get the crystal '),
('string/en/static_npc/endor/endor_moragscastle_morag.stf', 137, 'waypoint_description_3', 'Find and eliminate Tibik'),
