('string/en/static_npc/endor/king_terak.stf', 1, 'cant_work', 'I may have duties for one such as you, but I feel I do not command your full attention. I suggest you abandon your current duties and return at once.'),
('string/en/static_npc/endor/king_terak.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/endor/king_terak.stf', 3, 'dontknowyou_2', ''),
