('string/en/static_npc/naboo/arrek_von_sarko.stf', 126, 'npc_breech_6', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 127, 'npc_takeme_6', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 128, 'npc_dropoff_6', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 129, 'npc_smuggle_6', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 130, 'gotowork_6', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 131, 'notit_6', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 132, 'player_reset_6', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 136, 'player_3_6', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 137, 'npc_reset_2', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 138, 'npc_reset_3', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 139, 'npc_reset_4', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 140, 'npc_reset_5', ''),
('string/en/static_npc/naboo/arrek_von_sarko.stf', 141, 'npc_reset_6', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 1, 'next', 'The Alliance appreciates your assistance and may need your services again in the future.'),
('string/en/static_npc/naboo/arven_wendik.stf', 2, 'cantwork', 'I take it you have something else to attend to. Perhaps you can help the Alliance in the future.'),
('string/en/static_npc/naboo/arven_wendik.stf', 3, 'npc_reset_1', 'Perhaps you weren''t quite ready for a task of this magnitude. You may wish to try me again once your skills have improved.'),
('string/en/static_npc/naboo/arven_wendik.stf', 4, 'notyet', 'I''m too busy to talk.'),
('string/en/static_npc/naboo/arven_wendik.stf', 5, 'npc_1_1', 'It''s always good to meet another friend of the Alliance. My name is Arven Wendik. I frequently deal with some unsavory customers, so I hope you''re not too picky about the company you keep. Can you deliver some documents as a service to the Alliance? They''re quite real -- or at least they appear real, which is much the same thing.'),
('string/en/static_npc/naboo/arven_wendik.stf', 6, 'npc_2_1', 'Good. Take these to Alowi Fintz -- she''s our "procurement specialist." She may look like a common smuggler, but really, she''s also a well-paid friend of the Alliance.'),
('string/en/static_npc/naboo/arven_wendik.stf', 7, 'npc_3_1', 'I take it you have something else to attend to. Perhaps you can help the Alliance in the future.'),
('string/en/static_npc/naboo/arven_wendik.stf', 8, 'npc_4_1', 'The documents are Imperial permits that will allow us to ship medical supplies from Naboo to where they''re most needed. What do you say?'),
('string/en/static_npc/naboo/arven_wendik.stf', 9, 'npc_backtowork_1', 'Hurry up. The medical supplies are no good without those permits.'),
('string/en/static_npc/naboo/arven_wendik.stf', 10, 'npc_reward_1', 'See me again soon. The Alliance always needs good people'),
('string/en/static_npc/naboo/arven_wendik.stf', 11, 'npc_work_1', 'Haven''t you delivered the permits yet?'),
('string/en/static_npc/naboo/arven_wendik.stf', 12, 'npc_noloc_1', 'Imperial scrutiny is a little intense right now, so I''m going to have to ask you to come back and see me later.'),
('string/en/static_npc/naboo/arven_wendik.stf', 13, 'npc_failure_1', 'Blast it! Those medical supplies are desperately needed by the Alliance.'),
('string/en/static_npc/naboo/arven_wendik.stf', 14, 'otherescort_1', 'I''m afraid I''m waiting for somebody else.'),
('string/en/static_npc/naboo/arven_wendik.stf', 15, 'dontknowyou_1', 'Please leave me alone. '),
('string/en/static_npc/naboo/arven_wendik.stf', 16, 'npc_breech_1', 'Are you the courier with the uh -- official documents?'),
('string/en/static_npc/naboo/arven_wendik.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 19, 'npc_smuggle_1', 'I hope these things work. I don''t want trouble with the Imperials. And I better get paid on time this time!'),
('string/en/static_npc/naboo/arven_wendik.stf', 20, 'gotowork_1', 'Where are my permits? I can''t get off world without them.'),
('string/en/static_npc/naboo/arven_wendik.stf', 21, 'notit_1', 'These aren''t my documents. '),
('string/en/static_npc/naboo/arven_wendik.stf', 22, 'player_reset_1', 'I don''t want this mission right now.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/naboo/arven_wendik.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/arven_wendik.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/naboo/arven_wendik.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/naboo/arven_wendik.stf', 26, 'player_3_1', 'What are the documents?'),
('string/en/static_npc/naboo/arven_wendik.stf', 27, 'npc_1_2', 'Did I mention I used to be a pilot? I flew in the Battle of Naboo years ago. I miss flying sometimes, but the work I do here is valuable. I''m thinking of the old days because Imperial fighters have just shot down an Alliance pilot. I hope he bailed out in time. Will you go look for him?'),
('string/en/static_npc/naboo/arven_wendik.stf', 28, 'npc_2_2', 'Good. The pilot''s name is Grel Rommo. Once you''ve located him, bring him back here, while I arrange his passage offworld. Good luck.'),
('string/en/static_npc/naboo/arven_wendik.stf', 29, 'npc_3_2', 'I''m surprised that you''re not willing to help. I hope I can find somebody else.'),
('string/en/static_npc/naboo/arven_wendik.stf', 30, 'npc_4_2', 'Almost certainly, which is why I want you to find him as soon as possible. Will you?'),
('string/en/static_npc/naboo/arven_wendik.stf', 31, 'npc_backtowork_2', 'You should really hurry and get that pilot.'),
('string/en/static_npc/naboo/arven_wendik.stf', 32, 'npc_reward_2', 'You''ve done very well. The Alliance can''t afford to lose any pilots. I hope we''ll work together again.'),
('string/en/static_npc/naboo/arven_wendik.stf', 33, 'npc_work_2', 'Where is Grel Rommo? Haven''t you found him yet?'),
('string/en/static_npc/naboo/arven_wendik.stf', 34, 'npc_noloc_2', 'Those Imperial patrols can be trigger-happy. You had better wait a while before you go looking. Check back with me later.'),
('string/en/static_npc/naboo/arven_wendik.stf', 35, 'npc_failure_2', 'You weren''t able to rescue him? I''m sorry to hear that.'),
('string/en/static_npc/naboo/arven_wendik.stf', 36, 'otherescort_2', 'I''m here to meet somebody else.'),
('string/en/static_npc/naboo/arven_wendik.stf', 37, 'dontknowyou_2', 'I''m busy right now.'),
('string/en/static_npc/naboo/arven_wendik.stf', 38, 'npc_breech_2', 'Are you going to Dee''ja Peak?'),
('string/en/static_npc/naboo/arven_wendik.stf', 39, 'npc_takeme_2', 'I''m glad you''re here. I''ve had to duck several Imperial patrols.'),
('string/en/static_npc/naboo/arven_wendik.stf', 40, 'npc_dropoff_2', 'Thanks for getting me here. I was afraid I might not make it.'),
('string/en/static_npc/naboo/arven_wendik.stf', 41, 'npc_smuggle_2', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 42, 'gotowork_2', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 43, 'notit_2', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/arven_wendik.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/arven_wendik.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/naboo/arven_wendik.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/naboo/arven_wendik.stf', 48, 'player_3_2', 'Won''t Imperial patrols be after him if he was shot down?'),
('string/en/static_npc/naboo/arven_wendik.stf', 49, 'npc_1_3', 'One of our informants has been captured on her way here. They''re bringing her to Imperial High Inquisitor Mal Sikander for questioning. If he makes her talk -- and he will! -- our cover here is blown. Do you think you can rescue her?'),
('string/en/static_npc/naboo/arven_wendik.stf', 50, 'npc_2_3', 'I''m glad to hear it. Kill her captors and bring her here before it''s too late.'),
('string/en/static_npc/naboo/arven_wendik.stf', 51, 'npc_3_3', 'Yes, I suppose this mission is too dangerous. I don''t blame you.'),
('string/en/static_npc/naboo/arven_wendik.stf', 52, 'npc_4_3', 'Extremely dangerous. According to our intelligence, she''s being held by several stormtroopers and an officer. You''ll need a small but skilled strike team. Can you do it?'),
('string/en/static_npc/naboo/arven_wendik.stf', 53, 'npc_backtowork_3', 'Please find her soon. We''re running out of time.'),
('string/en/static_npc/naboo/arven_wendik.stf', 54, 'npc_reward_3', 'That was a near thing, but you came through for us. Good job, friend! Check with me again for more assignments.'),
('string/en/static_npc/naboo/arven_wendik.stf', 55, 'npc_work_3', 'Haven''t you found her yet? We''re running out of time!'),
('string/en/static_npc/naboo/arven_wendik.stf', 56, 'npc_noloc_3', 'I know it seems strange, but I''m going to have to delay this mission temporarily. You''ll just have to trust my reasons. Check with me later.'),
('string/en/static_npc/naboo/arven_wendik.stf', 57, 'npc_failure_3', 'You failed? Then we can only hope that she dies before she talks.'),
('string/en/static_npc/naboo/arven_wendik.stf', 58, 'otherescort_3', 'I''m not the person you need to find.'),
('string/en/static_npc/naboo/arven_wendik.stf', 59, 'dontknowyou_3', 'You should probably go on about your business.'),
('string/en/static_npc/naboo/arven_wendik.stf', 60, 'npc_breech_3', 'HELP! I''m over here!'),
('string/en/static_npc/naboo/arven_wendik.stf', 61, 'npc_takeme_3', 'I''ve never been so glad to see somebody in my entire life.'),
('string/en/static_npc/naboo/arven_wendik.stf', 62, 'npc_dropoff_3', 'Thank you for saving my life. I''ll never forget you.'),
('string/en/static_npc/naboo/arven_wendik.stf', 63, 'npc_smuggle_3', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 64, 'gotowork_3', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 65, 'notit_3', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 66, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/arven_wendik.stf', 67, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/arven_wendik.stf', 68, 'player_1_3', 'Yes.'),
('string/en/static_npc/naboo/arven_wendik.stf', 69, 'player_2_3', 'No.'),
('string/en/static_npc/naboo/arven_wendik.stf', 70, 'player_3_3', 'How risky is it?'),
('string/en/static_npc/naboo/arven_wendik.stf', 71, 'npc_1_4', 'You''re just in time to do a huge service for the Alliance. I''m asking a lot this time, but I''m hoping you''ll be willing to take this on. The Empire has set up a listening post in the wilderness to track our ships as they land nearby. Would you like to destroy it?'),
('string/en/static_npc/naboo/arven_wendik.stf', 72, 'npc_2_4', 'Excellent, I knew you had the stuff. Blast that listening post into tiny pieces. You may want to take out the guards and technicians too, just to make sure you''re not followed back here.'),
('string/en/static_npc/naboo/arven_wendik.stf', 73, 'npc_3_4', 'I understand. This is no small thing I''m asking for.'),
('string/en/static_npc/naboo/arven_wendik.stf', 74, 'npc_4_4', 'Calm yourself. I''m not asking you to attack a stormtrooper barracks. The post is staffed with three or four stormtroopers. You''ll need a strike team, but I think you''re up to it. What do you say?'),
('string/en/static_npc/naboo/arven_wendik.stf', 75, 'npc_backtowork_4', 'So are you going to go destroy that listening post or not?'),
('string/en/static_npc/naboo/arven_wendik.stf', 76, 'npc_reward_4', 'You''re a true friend of the Alliance. Working with you has been a real pleasure.'),
('string/en/static_npc/naboo/arven_wendik.stf', 77, 'npc_work_4', 'Have you destroyed the listening post yet?'),
('string/en/static_npc/naboo/arven_wendik.stf', 78, 'npc_noloc_4', 'There are a lot of patrols in that area right now. Come back again and see me again in a while, and we''ll make the final arrangements.'),
('string/en/static_npc/naboo/arven_wendik.stf', 79, 'npc_failure_4', 'I gather you were unable to destroy the listening post. I can hardly blame you, but this is going to cause problems for our operation here.'),
('string/en/static_npc/naboo/arven_wendik.stf', 80, 'otherescort_4', ''),
('string/en/static_npc/naboo/arven_wendik.stf', 81, 'dontknowyou_4', 'You should probably go on about your business.'),
('string/en/static_npc/naboo/arven_wendik.stf', 82, 'npc_breech_4', ''),
