('string/en/static_npc/naboo/arven_wendik.stf', 88, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/arven_wendik.stf', 89, 'player_sorry_4', 'I''ll keep working on the mission.'),
