('string/en/static_npc/naboo/athok_dinvar.stf', 1, 'notyet', 'I''m a little preoccupied right now.  Why don''t you come back some other time?'),
('string/en/static_npc/naboo/bab_esrus.stf', 1, 'next', 'There''s nothing else I need right now. Sorry.'),
('string/en/static_npc/naboo/bab_esrus.stf', 2, 'cantwork', 'Come back after you finish the job.'),
('string/en/static_npc/naboo/bab_esrus.stf', 3, 'npc_reset_1', ''),
('string/en/static_npc/naboo/bab_esrus.stf', 4, 'notyet', 'I have no need for your assistance, though I do thank you for offering.'),
('string/en/static_npc/naboo/bab_esrus.stf', 5, 'npc_1_1', ''),
('string/en/static_npc/naboo/bab_esrus.stf', 6, 'npc_2_1', ''),
