INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/naboo/brennis_doore.stf', 122, 'npc_noloc_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 123, 'npc_failure_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 124, 'otherescort_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 125, 'dontknowyou_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 126, 'npc_breech_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 127, 'npc_takeme_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 128, 'npc_dropoff_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 129, 'npc_smuggle_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 130, 'gotowork_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 131, 'notit_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 132, 'player_reset_6', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/brennis_doore.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/brennis_doore.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/naboo/brennis_doore.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/naboo/brennis_doore.stf', 136, 'player_3_6', ''),
('string/en/static_npc/naboo/brennis_doore.stf', 137, 'npc_reset_2', 'I understand your reluctance to help a miserable sleemo such as myself. If you change your mind, however, you know where to find me.'),
('string/en/static_npc/naboo/brennis_doore.stf', 138, 'npc_reset_3', 'I understand your reluctance to help a miserable sleemo such as myself. If you change your mind, however, you know where to find me.'),
('string/en/static_npc/naboo/brennis_doore.stf', 139, 'npc_reset_4', 'I understand your reluctance to help a miserable sleemo such as myself. If you change your mind, however, you know where to find me.'),
('string/en/static_npc/naboo/brennis_doore.stf', 140, 'npc_reset_5', 'I understand your reluctance to help a miserable sleemo such as myself. If you change your mind, however, you know where to find me.'),
('string/en/static_npc/naboo/brennis_doore.stf', 141, 'npc_reset_6', 'I understand your reluctance to help a miserable sleemo such as myself. If you change your mind, however, you know where to find me.'),
('string/en/static_npc/naboo/crider_trant.stf', 1, 'next', 'I don''t have anything for you at the moment. I''ll keep you in mind if anything arises.'),
('string/en/static_npc/naboo/crider_trant.stf', 2, 'cantwork', 'I won''t hire you until I can have your undivided attention. Finish up whatever business you''re involved in, then see me.'),
('string/en/static_npc/naboo/crider_trant.stf', 3, 'npc_reset_1', 'Fine.  I''ll get someone else to do it then.'),
('string/en/static_npc/naboo/crider_trant.stf', 4, 'notyet', 'I have no need of your services at this time.'),
('string/en/static_npc/naboo/crider_trant.stf', 5, 'npc_1_1', 'Crider Trant. I represent the Corporate Sector Authority for the Naboo system. The name of the game is credits. Care to earn some? A government inspector is heading for one of my resource extraction plants. I''d like you to give him something to encourage him to, ah, delay his inspection. Just until I can make sure everything is up to code, of course. Interested?'),
('string/en/static_npc/naboo/crider_trant.stf', 6, 'npc_2_1', 'Good. Get going.'),
('string/en/static_npc/naboo/crider_trant.stf', 7, 'npc_3_1', 'That is disappointing, but I''m sure someone else will have a use for the money. Nice outfit. Be seeing you.'),
('string/en/static_npc/naboo/crider_trant.stf', 8, 'npc_4_1', 'The usual mischief that primitive hooligans undertake to disrupt the honest businessman, like whining to the civil authorities about "improper disposal procedures" and "sacred places." A lot of superstitious nonsense. So, will you help me?'),
('string/en/static_npc/naboo/crider_trant.stf', 9, 'npc_backtowork_1', 'Are you going to deliver these credits? Get going.'),
('string/en/static_npc/naboo/crider_trant.stf', 10, 'npc_reward_1', 'Fine. It all went smoothly, I trust.'),
('string/en/static_npc/naboo/crider_trant.stf', 11, 'npc_work_1', 'Haven''t you delivered those credits yet? '),
('string/en/static_npc/naboo/crider_trant.stf', 12, 'npc_noloc_1', 'Return here in a while, after I''ve made all the necessary arrangements.'),
('string/en/static_npc/naboo/crider_trant.stf', 13, 'npc_failure_1', 'You failed? I guess neither of us will make anything from this deal.'),
('string/en/static_npc/naboo/crider_trant.stf', 14, 'otherescort_1', 'If you''re looking for someone, I''m not him.'),
('string/en/static_npc/naboo/crider_trant.stf', 15, 'dontknowyou_1', 'Sorry, friend, I''m a little busy at the moment.'),
('string/en/static_npc/naboo/crider_trant.stf', 16, 'npc_breech_1', 'Do you have a package for me?'),
('string/en/static_npc/naboo/crider_trant.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/naboo/crider_trant.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/naboo/crider_trant.stf', 19, 'npc_smuggle_1', 'I suppose I could reschedule my inspection. I didn''t really want to go slogging all the way to that plant anyway.'),
('string/en/static_npc/naboo/crider_trant.stf', 20, 'gotowork_1', 'Didn''t you bring the package? I guess that means I actually have to do my job.'),
('string/en/static_npc/naboo/crider_trant.stf', 21, 'notit_1', 'Perhaps you meant to give me a different item.'),
('string/en/static_npc/naboo/crider_trant.stf', 22, 'player_reset_1', 'I''m not comfortable with this job.'),
('string/en/static_npc/naboo/crider_trant.stf', 23, 'player_sorry_1', 'I''ll get these delivered.'),
