('string/en/static_npc/naboo/dilvin_lormurojo.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 48, 'player_3_2', 'What is the new satire?'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 49, 'npc_1_3', 'Hello again. My beloved wife, Sindria, can''t visit me too often without tipping off my location to observers. But she makes frequent visits to the image designers to assume new disguises. She''s just changed her appearance again -- don''t know what she looks like now -- but she''s waiting in the wilderness at the usual rendezvous. Can you escort her here?'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 50, 'npc_2_3', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 51, 'npc_3_3', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 52, 'npc_4_3', ''),
