('string/en/static_npc/naboo/dilvin_lormurojo.stf', 70, 'player_3_3', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 71, 'npc_1_4', 'Oh, this is bad! I just learned -- oh, uh, sorry. Hello. Anyway, I just learned Borvo has kidnapped my pet monkey-lizard, Giggler. He''s probably using poor Giggler as bait to trap me. But it won''t work! I''ll out-think him! I''ll -- well, can I hire you to take care of this? Bring Giggler back safely, I mean?'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 72, 'npc_2_4', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 73, 'npc_3_4', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 74, 'npc_4_4', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 75, 'npc_backtowork_4', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 76, 'npc_reward_4', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 77, 'npc_work_4', 'You, uh -- you didn''t do the job yet? Oh. Okay. Hope you can keep going with that.'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 78, 'npc_noloc_4', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 79, 'npc_failure_4', ''),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 80, 'otherescort_4', 'Heek! Yeek! Not me. Not here. Go ''way.'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 81, 'dontknowyou_4', 'Heek! Yeek! Not me. Not here. Go ''way.'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 82, 'npc_breech_4', 'Yik-yik! Here I am! You! Over here, heee heee!'),
('string/en/static_npc/naboo/dilvin_lormurojo.stf', 83, 'npc_takeme_4', 'Yeek! Gotcher nose! Hah.'),
