('string/en/static_npc/naboo/gavyn_sykes.stf', 88, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/gavyn_sykes.stf', 89, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/gavyn_sykes.stf', 90, 'player_1_4', 'Yes.'),
('string/en/static_npc/naboo/gavyn_sykes.stf', 91, 'player_2_4', 'No.'),
('string/en/static_npc/naboo/gavyn_sykes.stf', 92, 'player_3_4', 'What is the "Berserker Virus"?'),
('string/en/static_npc/naboo/gavyn_sykes.stf', 93, 'npc_1_5', ''),
