('string/en/static_npc/naboo/lergo_brazee.stf', 86, 'gotowork_4', 'Get to work.'),
('string/en/static_npc/naboo/lergo_brazee.stf', 87, 'notit_4', ''),
('string/en/static_npc/naboo/lergo_brazee.stf', 88, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/lergo_brazee.stf', 89, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/lergo_brazee.stf', 90, 'player_1_4', 'Yes.'),
('string/en/static_npc/naboo/lergo_brazee.stf', 91, 'player_2_4', 'No.'),
('string/en/static_npc/naboo/lergo_brazee.stf', 92, 'player_3_4', 'Does this bandit leader intend to free Humbonnen''s Gungan slaves?'),
('string/en/static_npc/naboo/lergo_brazee.stf', 93, 'npc_1_5', ''),
