('string/en/static_npc/naboo/mal_sikander.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/naboo/mal_sikander.stf', 136, 'player_3_6', 'How did this scientist get to Naboo?'),
('string/en/static_npc/naboo/mal_sikander.stf', 137, 'npc_reset_2', 'Your failure to complete this assignment will be included in my report to the Emperor. He is not known to be a terribly forgiving sort. I hope for your sake that he overlooks your shortcomings.'),
('string/en/static_npc/naboo/mal_sikander.stf', 138, 'npc_reset_3', 'Your failure to complete this assignment will be included in my report to the Emperor. He is not known to be a terribly forgiving sort. I hope for your sake that he overlooks your shortcomings.'),
('string/en/static_npc/naboo/mal_sikander.stf', 139, 'npc_reset_4', 'Your failure to complete this assignment will be included in my report to the Emperor. He is not known to be a terribly forgiving sort. I hope for your sake that he overlooks your shortcomings.'),
('string/en/static_npc/naboo/mal_sikander.stf', 140, 'npc_reset_5', 'Your failure to complete this assignment will be included in my report to the Emperor. He is not known to be a terribly forgiving sort. I hope for your sake that he overlooks your shortcomings.'),
('string/en/static_npc/naboo/mal_sikander.stf', 141, 'npc_reset_6', 'Your failure to complete this assignment will be included in my report to the Emperor. He is not known to be a terribly forgiving sort. I hope for your sake that he overlooks your shortcomings.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 1, 'next', 'Mesa no have nutten for yousa to be doin. Mesa busy. Come backo later and mebbe mesa have sumthin.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 2, 'cantwork', 'Yousa seem mooie mooie busy. Come backo when yousa have nutten on yousa brain.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 3, 'npc_reset_1', 'Mesa no like whensa yousa not finish mesa maxibig tasks. Come backo whensa yousa can finish da task.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 4, 'notyet', 'Mesa no have nutten for yousa right now.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 5, 'npc_1_1', 'Heyo. Yousa be needin a task? My be needin someone to hep mesa. Yousa no needin to be smarty. Just needin to tek a gizmo to Naboo maxibig patron. Mesa be payen for de hep. Yousa hep mesa?'),
('string/en/static_npc/naboo/mullud_bombo.stf', 6, 'npc_2_1', 'Good. Mesa no like whensa dosen others tink dey so smarty den usan. Dey stinkowiff! But yousa seem okeyday.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 7, 'npc_3_1', 'Yousa one of dem! Yousa tink yous brain so big. Mesa no like yousa.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 8, 'npc_4_1', 'Yousa needin to go to see Sentellus Gavrel. He be maxibig patron wit mooie mooie moolah. Mesa bosses tink wesa be needin to kiss hisan feet. Make mesa sick!'),
('string/en/static_npc/naboo/mullud_bombo.stf', 9, 'npc_backtowork_1', 'Whatsa more yousa be needin? Yousa reconsider?'),
('string/en/static_npc/naboo/mullud_bombo.stf', 10, 'npc_reward_1', 'Yousa done a berry good job. Here, tek dis medicine. It hep yousa feel bettah.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 11, 'npc_work_1', 'Have yousa tekken da talkie to Naboo smarty patron? Whatsa yousa be waitin for?'),
('string/en/static_npc/naboo/mullud_bombo.stf', 12, 'npc_noloc_1', 'Mesa give yousa da location of da Naboo smarty patron soon. Mesa haven to find hesan first.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 13, 'npc_failure_1', 'Mesa no like yousa! Off wit yousa! Yousa no better dan dosen smarty others. Yousa all stinkowiff!'),
('string/en/static_npc/naboo/mullud_bombo.stf', 14, 'otherescort_1', 'Terribly busy, I''m afraid. Can''t talk now.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 15, 'dontknowyou_1', 'Terribly busy, I''m afraid. Can''t talk now.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 16, 'npc_breech_1', 'Can I help you? You seem to be looking for someone!'),
('string/en/static_npc/naboo/mullud_bombo.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/naboo/mullud_bombo.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/naboo/mullud_bombo.stf', 19, 'npc_smuggle_1', 'Ah, this must be the survey equipment I requested. Excellent! But where is Mullud? Did that lazy good-for-nothing get someone else to do his work again?'),
('string/en/static_npc/naboo/mullud_bombo.stf', 20, 'gotowork_1', 'I was expecting some survey equipment. Was that what you meant to give me?'),
('string/en/static_npc/naboo/mullud_bombo.stf', 21, 'notit_1', 'No, I need some survey equipment. This is definitely not what I ordered. Likely that good-for-nothing Mullud messed everything up. You probably couldn''t understand a word he was trying to say.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/naboo/mullud_bombo.stf', 26, 'player_3_1', 'I think you want me to deliver some equipment. To who exactly?'),
