('string/en/static_npc/naboo/queen_kylantha.stf', 142, 'default', ''),
('string/en/static_npc/naboo/radanthus_mandelatara.stf', 1, 'notyet', 'I''m sorry, I''m a bit distracted.   I''m trying to remember something...'),
('string/en/static_npc/naboo/rep_been.stf', 1, 'next', 'Mesa gotten no work for yousa.  Check backo wit mesa later.'),
('string/en/static_npc/naboo/rep_been.stf', 2, 'cantwork', 'Yousa goin'' to come backo when yousa job is done, okeyday?'),
('string/en/static_npc/naboo/rep_been.stf', 3, 'npc_reset_1', 'Okeyday. Yousa comen back when yousa mooie-mooie tough.'),
('string/en/static_npc/naboo/rep_been.stf', 4, 'notyet', 'Mesa sorry. No haven time for yousa right now.'),
('string/en/static_npc/naboo/rep_been.stf', 5, 'npc_1_1', 'Yousa be mooie-mooie lucky, outlaunder, to be seein'' da Sacred Place of mesa peoples. Yousa needen credits? Mesa be haven work for yous if''n yousa wanten. Rep be keepin'' da histories. Needen yousa ta go and gettin'' da maxibig important record of da histories.'),
('string/en/static_npc/naboo/rep_been.stf', 6, 'npc_2_1', 'Good. Yousa be findin'' Boona Tanje. Shesa be havin'' de record of dat meetin''. Yousa be bringin'' to me for da archives.'),
('string/en/static_npc/naboo/rep_been.stf', 7, 'npc_3_1', 'Yousan be wastin'' mesa time. Begone wit yousa.'),
('string/en/static_npc/naboo/rep_been.stf', 8, 'npc_4_1', 'Maxi longtime ago Boss Nass met wit de Naboo biggen, Queen Amidala, when she be askin'' de Gungans for hep. Disa be record of dat meetin''. Yousa goin'' n'' gettin''?'),
('string/en/static_npc/naboo/rep_been.stf', 9, 'npc_backtowork_1', 'Yousa goin'' n gettin'' de history now?'),
('string/en/static_npc/naboo/rep_been.stf', 10, 'npc_reward_1', 'Mesa plenty glad yousa hepin'' da Gungans.'),
('string/en/static_npc/naboo/rep_been.stf', 11, 'npc_work_1', 'My givin'' yousa maxibig important task. Yousa hurry up and bringin'' de holo.'),
('string/en/static_npc/naboo/rep_been.stf', 12, 'npc_noloc_1', 'My not knowin'' where Boonja Tanje be right now. Yousa come backo and see mesa later.'),
('string/en/static_npc/naboo/rep_been.stf', 13, 'npc_failure_1', 'Mesa berry berry sad yousa no gettin'' de record.'),
('string/en/static_npc/naboo/rep_been.stf', 14, 'otherescort_1', 'Mesa not bein'' who yousa be needin'' to find.'),
('string/en/static_npc/naboo/rep_been.stf', 15, 'dontknowyou_1', 'Mesa bein'' mooie-mooie busy. Off wit yousa.'),
('string/en/static_npc/naboo/rep_been.stf', 16, 'npc_breech_1', 'Yousa comen from Rep Been?'),
('string/en/static_npc/naboo/rep_been.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/naboo/rep_been.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/naboo/rep_been.stf', 19, 'npc_smuggle_1', 'Dis maxibig important. Yousa bein'' careful wit it.'),
('string/en/static_npc/naboo/rep_been.stf', 20, 'gotowork_1', ''),
('string/en/static_npc/naboo/rep_been.stf', 21, 'notit_1', 'Mesa no wanten dat. Yousa be findin'' de holo mesa be wanten.'),
('string/en/static_npc/naboo/rep_been.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/rep_been.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
