('string/en/static_npc/naboo/rhys_dallows.stf', 88, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/rhys_dallows.stf', 89, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/rhys_dallows.stf', 90, 'player_1_4', 'Yes.'),
('string/en/static_npc/naboo/rhys_dallows.stf', 91, 'player_2_4', 'No.'),
('string/en/static_npc/naboo/rhys_dallows.stf', 92, 'player_3_4', 'What do you gain by making Sikander think that Lago destroyed the storm commandos?'),
('string/en/static_npc/naboo/rhys_dallows.stf', 93, 'npc_1_5', ''),
