('string/en/static_npc/naboo/ric_olie.stf', 88, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/ric_olie.stf', 89, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/ric_olie.stf', 90, 'player_1_4', 'Yes.'),
('string/en/static_npc/naboo/ric_olie.stf', 91, 'player_2_4', 'No.'),
('string/en/static_npc/naboo/ric_olie.stf', 92, 'player_3_4', 'Why would pirates blow up a starport? '),
