('string/en/static_npc/naboo/throme_gormengal.stf', 137, 'npc_reset_2', 'I thought I''d made the right choice by employing you. Perhaps I misjudged. Come back when you feel you can finish the tasks I give you.'),
('string/en/static_npc/naboo/throme_gormengal.stf', 138, 'npc_reset_3', 'I thought I''d made the right choice by employing you. Perhaps I misjudged. Come back when you feel you can finish the tasks I give you.'),
('string/en/static_npc/naboo/throme_gormengal.stf', 139, 'npc_reset_4', 'I thought I''d made the right choice by employing you. Perhaps I misjudged. Come back when you feel you can finish the tasks I give you.'),
('string/en/static_npc/naboo/throme_gormengal.stf', 140, 'npc_reset_5', 'I thought I''d made the right choice by employing you. Perhaps I misjudged. Come back when you feel you can finish the tasks I give you.'),
('string/en/static_npc/naboo/throme_gormengal.stf', 141, 'npc_reset_6', 'I thought I''d made the right choice by employing you. Perhaps I misjudged. Come back when you feel you can finish the tasks I give you.'),
('string/en/static_npc/naboo/vana_sage.stf', 1, 'next', 'I don''t have any jobs for you right now. Check back with me later. '),
('string/en/static_npc/naboo/vana_sage.stf', 2, 'cantwork', 'You have a previous obligation. See me when you''re free of other employment.'),
('string/en/static_npc/naboo/vana_sage.stf', 3, 'npc_reset_1', 'If the job is too hard for you right now, see me later when it might be a bit easier.'),
('string/en/static_npc/naboo/vana_sage.stf', 4, 'notyet', 'I''m too busy for you right now.'),
('string/en/static_npc/naboo/vana_sage.stf', 5, 'npc_1_1', 'I''m Vana Sage, second in command of security here in Keren. If you need some credits, I''m very short-handed right now. A Rodian pilot just landed, and I need someone to check his cargo permits. Interested?'),
('string/en/static_npc/naboo/vana_sage.stf', 6, 'npc_2_1', 'Good. He landed out in a rural area, so you''ll have to meet him outside of the city. See me once you''ve obtained his permits or collected the fine.'),
('string/en/static_npc/naboo/vana_sage.stf', 7, 'npc_3_1', 'Enjoy your stay in Keren.'),
('string/en/static_npc/naboo/vana_sage.stf', 8, 'npc_4_1', 'Then you''d have to collect a fine. I wouldn''t worry about that, though. These pilots know to keep their noses clean on Naboo -- or snouts clean, in the case of Rodians.'),
('string/en/static_npc/naboo/vana_sage.stf', 9, 'npc_backtowork_1', 'Were you going to collect that fine -- I mean, check those permits?'),
('string/en/static_npc/naboo/vana_sage.stf', 10, 'npc_reward_1', 'His permits weren''t in order? I''m shocked! And he attacked you?  Well, I guess you did what you had to do.'),
('string/en/static_npc/naboo/vana_sage.stf', 11, 'npc_work_1', 'Have you checked on that pilot yet? '),
('string/en/static_npc/naboo/vana_sage.stf', 12, 'npc_noloc_1', 'I need to double-check the pilot''s coordinates. Would you mind coming back in a few minutes? I should have the information by then.'),
('string/en/static_npc/naboo/vana_sage.stf', 13, 'npc_failure_1', 'How unfortunate. I may have to handle this personally. '),
('string/en/static_npc/naboo/vana_sage.stf', 14, 'otherescort_1', 'I don''t know who you''re looking for, but I know you''re not looking for me.'),
('string/en/static_npc/naboo/vana_sage.stf', 15, 'dontknowyou_1', 'I don''t know who you''re looking for, but I know you''re not looking for me.'),
('string/en/static_npc/naboo/vana_sage.stf', 16, 'npc_breech_1', 'Awww, not another customs inspector.'),
('string/en/static_npc/naboo/vana_sage.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/naboo/vana_sage.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/naboo/vana_sage.stf', 19, 'npc_smuggle_1', 'Yeah, I know the drill -- you want to "check my permits." Here''s your fine money. I hope somebody fines you someday. '),
('string/en/static_npc/naboo/vana_sage.stf', 20, 'gotowork_1', ''),
('string/en/static_npc/naboo/vana_sage.stf', 21, 'notit_1', 'This isn''t a proper permit or credits. Try again.'),
('string/en/static_npc/naboo/vana_sage.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/vana_sage.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/vana_sage.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/naboo/vana_sage.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/naboo/vana_sage.stf', 26, 'player_3_1', 'What would I do if his permits aren''t in order?'),
('string/en/static_npc/naboo/vana_sage.stf', 27, 'npc_1_2', 'Gungan raiders just attacked a transport, and the captain barely escaped with his life. Would you find Captain Vanool and escort him back to us? '),
('string/en/static_npc/naboo/vana_sage.stf', 28, 'npc_2_2', 'Great. Go to these coordinates, where he was last located. The Gungans are still after him, so you''ll want to be careful.'),
('string/en/static_npc/naboo/vana_sage.stf', 29, 'npc_3_2', 'I hope you''re never chased by Gungans and left out on your own.'),
('string/en/static_npc/naboo/vana_sage.stf', 30, 'npc_4_2', 'Who knows why Gungans do anything they do? Perhaps the ship flew too near a sacred place on a holy day. Maybe the ship landed on a Gungan by accident. I really couldn''t say.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/naboo/vana_sage.stf', 31, 'npc_backtowork_2', 'Was there something else you needed? If not, get going.'),
('string/en/static_npc/naboo/vana_sage.stf', 32, 'npc_reward_2', 'You rescued our lost captain! Good job.'),
('string/en/static_npc/naboo/vana_sage.stf', 33, 'npc_work_2', 'Were you going to rescue poor captain Vanool or just leave him to the Gungans?'),
('string/en/static_npc/naboo/vana_sage.stf', 34, 'npc_noloc_2', 'I''m waiting for him to check back in and give us his exact coordinates. Come back and see me in a while. He should have called us by then.'),
('string/en/static_npc/naboo/vana_sage.stf', 35, 'npc_failure_2', 'These things happen sometimes.  I''m sorry if it was too rough for you.'),
('string/en/static_npc/naboo/vana_sage.stf', 36, 'otherescort_2', 'I''m not the one you''re looking for.'),
('string/en/static_npc/naboo/vana_sage.stf', 37, 'dontknowyou_2', 'I''m hiding from the Gungans. Don''t tell them you''ve seen me.'),
('string/en/static_npc/naboo/vana_sage.stf', 38, 'npc_breech_2', 'You''re finally here. Yes!'),
('string/en/static_npc/naboo/vana_sage.stf', 39, 'npc_takeme_2', 'Those two Gungans just won''t give up. It''s not as though I landed the ship on either of them.'),
('string/en/static_npc/naboo/vana_sage.stf', 40, 'npc_dropoff_2', 'I appreciate your getting me back to town. I''ll be more careful about who I land on in the future.'),
('string/en/static_npc/naboo/vana_sage.stf', 41, 'npc_smuggle_2', ''),
('string/en/static_npc/naboo/vana_sage.stf', 42, 'gotowork_2', ''),
('string/en/static_npc/naboo/vana_sage.stf', 43, 'notit_2', ''),
('string/en/static_npc/naboo/vana_sage.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/vana_sage.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/vana_sage.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/naboo/vana_sage.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/naboo/vana_sage.stf', 48, 'player_3_2', 'Why did the Gungans attack a transport?'),
('string/en/static_npc/naboo/vana_sage.stf', 49, 'npc_1_3', 'We know now why those Gungans raiders were so eager to catch Captain Vanool. One of the Gungans he landed on was their leader. Since they''re raiders, we''d like you to destroy their hideout. Thanks to Captain Vanool''s happy accident, we know exactly where it is. Think you''re up to it?'),
('string/en/static_npc/naboo/vana_sage.stf', 50, 'npc_2_3', 'Good for you. Be cautious in your approach. We''re not sure how many raiders are left.'),
('string/en/static_npc/naboo/vana_sage.stf', 51, 'npc_3_3', 'If you''re too busy, I guess you should be on your way.'),
('string/en/static_npc/naboo/vana_sage.stf', 52, 'npc_4_3', 'If you mean, "Does he find Gungan raider camps?" -- never before, to my knowledge. But if you mean land on people -- well, not often.'),
('string/en/static_npc/naboo/vana_sage.stf', 53, 'npc_backtowork_3', 'Did you change your mind about taking out that raider camp?'),
('string/en/static_npc/naboo/vana_sage.stf', 54, 'npc_reward_3', 'Excellent work. I''m glad we don''t have to worry about those raiders any more. Now Captain Vanool can land there without hurting anybody.'),
('string/en/static_npc/naboo/vana_sage.stf', 55, 'npc_work_3', 'Didn''t I give you a mission recently? Something about a Gungan raider hideout?'),
('string/en/static_npc/naboo/vana_sage.stf', 56, 'npc_noloc_3', 'I need to track down the captain and get the exact coordinates. See me in a while and we can get started.'),
('string/en/static_npc/naboo/vana_sage.stf', 57, 'npc_failure_3', 'Disappointing. Perhaps I''ll send out a strike team to take care of this.'),
('string/en/static_npc/naboo/vana_sage.stf', 58, 'otherescort_3', ''),
('string/en/static_npc/naboo/vana_sage.stf', 59, 'dontknowyou_3', 'No idea who you are.'),
('string/en/static_npc/naboo/vana_sage.stf', 60, 'npc_breech_3', ''),
('string/en/static_npc/naboo/vana_sage.stf', 61, 'npc_takeme_3', ''),
