('string/en/static_npc/naboo/vrir_unglan.stf', 66, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/naboo/vrir_unglan.stf', 67, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/naboo/vrir_unglan.stf', 68, 'player_1_3', 'Yes.'),
('string/en/static_npc/naboo/vrir_unglan.stf', 69, 'player_2_3', 'No.'),
('string/en/static_npc/naboo/vrir_unglan.stf', 70, 'player_3_3', 'What kind of killers?'),
