('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 125, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 126, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 127, 'return_waypoint_description_1', 'Bring the surveillance holo back to Captain Tarun.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 128, 'return_waypoint_description_2', 'Bring the crooked dispatcher back to Captain Tarun for questioning.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 129, 'return_waypoint_description_3', 'Bring the rescued woman back to Captain Tarun.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 130, 'return_waypoint_description_4', 'Report back to Captain Tarun.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 131, 'return_waypoint_name_1', 'Captain Tarun''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 132, 'return_waypoint_name_2', 'Captain Tarun''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 133, 'return_waypoint_name_3', 'Captain Tarun''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 134, 'return_waypoint_name_4', 'Captain Tarun''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 135, 'waypoint_description_1', 'Pickup a surveillance holo for Captain Tarun.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 136, 'waypoint_description_2', 'Find and detain the crooked starport dispatcher.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 137, 'waypoint_description_3', 'Rescue an innocent young woman from the clutches of vile gunrunners.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 138, 'waypoint_description_4', 'Take out the leader of the gunrunners.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 139, 'waypoint_name_1', 'Surveillance Agent''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 140, 'waypoint_name_2', 'Crooked Dispatcher''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 141, 'waypoint_name_3', 'Kidnapped Victim''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 142, 'waypoint_name_4', 'Gunrunner Leader''s Location'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 143, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 144, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 145, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 146, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_narmle_biribas_tarun.stf', 147, 'player_sorry_3', 'I''ll keep working on the mission.'),
