INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 125, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 126, 'player_sorry_1', 'Sorry, I''ll get back to work.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 127, 'return_waypoint_description_1', 'Bring the painting to Jaleela Bindoo'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 128, 'return_waypoint_description_2', 'Escort Jonda Trask back to Jaleela Bindoo'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 129, 'return_waypoint_description_3', 'Return to Jaleela Bindoo and inform her the job has been completed.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 130, 'return_waypoint_description_4', 'Return to Jaleela Bindoo with Zim Graedler'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 131, 'return_waypoint_name_1', 'Jaleela Bindoo'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 132, 'return_waypoint_name_2', 'Jaleela Bindoo'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 133, 'return_waypoint_name_3', 'Jaleela Bindoo'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 134, 'return_waypoint_name_4', 'Jaleela Bindo'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 135, 'waypoint_description_1', 'Go and pick up the painting from Odoof Grunda'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 136, 'waypoint_description_2', 'Go and find Jonda Trask'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 137, 'waypoint_description_3', 'Deliver the list of finalists to the courier.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 138, 'waypoint_description_4', 'Go and rescue the Moff''s nephew Zim Graedler'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 139, 'waypoint_name_1', 'Odoof Grunda'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 140, 'waypoint_name_2', 'Jonda Trask''s location'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 141, 'waypoint_name_3', 'Dane Windholm''s location'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 142, 'waypoint_name_4', 'Zim Graedler''s location'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 143, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 144, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 145, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 146, 'player_sorry_2', 'Sorry, I''ll get back to work.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 147, 'player_sorry_3', 'Sorry, I''ll get back to work.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 148, 'player_sorry_4', 'Sorry, I''ll get back to work.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 149, 'npc_reset_2', 'Very well. See me again when you think you''re ready.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 150, 'npc_reset_3', 'Very well. See me again when you think you''re ready.'),
('string/en/static_npc/rori/rori_narmle_jaleela_bindoo.stf', 151, 'npc_reset_4', 'Very well. See me again when you think you''re ready.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 1, 'cant_work', 'I really could use your help once you aren''t quite so busy.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 2, 'dontknowyou_1', 'I am not the one you are looking for.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 3, 'dontknowyou_2', 'I''m not waiting for you, friend.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 4, 'gotowork_1', 'Shouldn''t you be leaving?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 5, 'gotowork_2', 'You should be going.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 6, 'next', 'I believe the Narmle Arts Gala is currently under control. If anything goes amiss, I''ll keep you in mind.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 7, 'notit_1', 'I was expecting a presentation for our Arts Gala from a particular rising artist. That isn''t it. '),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 8, 'notit_2', 'I was hoping to get a collection of diverse alien artifacts for our Arts Gala. That is''t what I expected.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 9, 'notyet', 'Sorry, I''m a little busy...'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 10, 'npc_1_1', 'Hello! I am Minister of Arts for the Narmle government. In this crucially important position, at this crucially important time of our Narmle Arts Gala, I have commissioned a holo presentation from a rising artist. It will certainly show up that imitative Restuss Arts Jubilee for the tone-deaf debacle it customarily is. Will you pick it up and bring it here?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 11, 'npc_1_2', 'Our Narmle Arts Gala had bad luck with that so-called rising artist whose insane screechings you brought to me. To remedy our ruined schedule, I called in a favor and asked to exhibit a friend''s collection of rare alien artifacts. My friend sent them, but the cargo lifter went off course and has broken down Can you pick up the artifacts from the driver?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 12, 'npc_2_1', 'Excellent. Being rather eccentric, this artist lives in the wilderness, and looks rather unusual. Be careful on your journey.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 13, 'npc_2_2', 'Good. I expect you''ll find the cargo at these coordinates. Please hurry!'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 14, 'npc_3_1', 'I am sorry you can''t help. This festival is a busy time for me.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 15, 'npc_3_2', 'I''m sorry your commitment to the Narmle Arts Gala appears weaker than I hoped. You haven''t been subverted by those Restuss Jubilee people, I hope.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 16, 'npc_4_1', 'I believe I''d best keep the name a secret, lest news leak out and spoil what should be a sensation. Those Restuss Jubilee people would die to steal away our prize catch. Please don''t tell anyone about your assignment!'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 17, 'npc_4_2', 'These alien art objects represent traditions from worlds across the galaxy. I believe there is some unifying theme, but I don''t know what it is. The collection''s descriptions should make all clear. Can you pick it up?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 22, 'npc_backtowork_1', 'Have you not brought back that presentation yet? Our Narmle Arts Gala audience will be agog when they finally see it.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 23, 'npc_backtowork_2', 'Have you picked up that collection of artifacts? Our Arts Gala is waiting.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 24, 'npc_breech_1', 'Ah! You are here looking for the presentation from me?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 25, 'npc_breech_2', 'Hey! Are you from that Arts Minister?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 28, 'npc_failure_1', 'Did you not bring back that presentation? Our Arts Gala audience will never know the pleasure they missed.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 29, 'npc_failure_2', 'You didn''t bring that collection of alien artifacts? Well, perhaps that is for the best -- Imperial citizens are suspicious of such things.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 30, 'npc_more_1_1', 'Now I present a selection of sweet-toned Chadra Fan heart-splitter wailing serenades. Take it please to Oxil.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 36, 'npc_noloc_1', 'I''m awaiting a contact from the artist shortly, giving the coordinates for the rendezvous. Check with me in a few moments.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 37, 'npc_noloc_2', 'The driver of the stranded cargolifter will relay coordinates to me shortly. Check with me soon.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 38, 'npc_reset_1', 'Very well. I hope you''ll remember the importance of furthering the arts in Narmle -- as opposed to Restuss.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 39, 'npc_reward_1', 'What? What is this foul caterwauling? I can''t play this noise -- our Arts Gala would become a laughingstock in Restuss! Well, I shall pay you, but I believe I''ll cross a certain artist off my list of future contributors.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 40, 'npc_reward_2', 'What? Grains of dust? I have no way to display a pinch of artistic dust! This is sheer flummery! Whatever shall my Arts Gala do? This is somehow the work of those Restuss Jubilee fiends.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 41, 'npc_smuggle_1', 'Ah! I am most excited! In a fit of inspiration I have revised my promised presentation of the Empire''s finest military marches. Yes! It is now revised.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 42, 'npc_smuggle_2', 'Here''s that collection of alien artifacts. I carried them as far as I could -- good thing they''re light. They''re all carved dust grains -- need quite a magnification to see them.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 45, 'npc_work_1', 'I really don''t know what else I can tell you. Please bring me the presentation.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 46, 'npc_work_2', 'I don''t know what else I can tell you, really. Please pick up the collection of artifacts as soon as possible.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 53, 'player_3_1', 'Who is this rising artist?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 54, 'player_3_2', 'What sort of artifacts?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 55, 'player_4_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 56, 'player_4_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 57, 'player_5_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 58, 'player_5_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 59, 'player_more_1_1', 'What is your revised presentation?'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 67, 'return_waypoint_description_1', 'Narmle''s Arts Minister, awaiting delivery of a presentation for the Narmle Arts Festival sent by a rising artist.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 68, 'return_waypoint_description_2', 'The Narmle Arts Minister is expecting a collection of alien artifacts for the Narmle Arts Gala.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 69, 'return_waypoint_name_1', 'Oxil Sarban'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 70, 'return_waypoint_name_2', 'Oxil Sarban'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 71, 'waypoint_description_1', 'A promising artist with a presentation sought by Narmle''s Arts Minister, Oxil Sarban, for the Narmle Arts Festival.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 72, 'waypoint_description_2', 'Here is a collection of alien artifacts for the Narmle Arts Minister, Oxil Sarban, and his Narmle Arts Gala.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 73, 'waypoint_name_1', 'Rising Artist'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 74, 'waypoint_name_2', 'Alien Artifact Collection'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 75, 'npc_reset_2', 'Very well. I hope you''ll remember the importance of furthering the arts in Narmle -- as opposed to Restuss.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_oxil_sarban.stf', 77, 'player_sorry_2', 'Ok.  I''ll get back to work.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 1, 'cant_work', 'You already have a job. I can''t just go hiring people who already have jobs. It would be anarchy, I tell you. See me if you get fired.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 2, 'dontknowyou_1', 'I''m just here to drop off something to someone else. Don''t worry about me.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 3, 'dontknowyou_2', 'This probably isn''t the healthiest place for you to be. '),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 6, 'next', 'Oh yes, you were the one I hired a few years back -- or was it weeks? Didn''t I fire you? No. Wait. That was that Jawa. It''s been nice chatting with you. See me again some time.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 7, 'notit_1', 'You''re supposed to give me a disc from the arts committee. What is this thing?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 8, 'notit_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 9, 'notyet', 'Sorry, can''t talk now.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 10, 'npc_1_1', 'Are you the one the agency sent over to run my errands for me? Speak up! I don''t have all day. I''m supposed to announce the winner of some competition, and I need somebody to pick up the announcement of who won. Will you do it, or do I need to find somebody else?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 11, 'npc_1_2', 'My blasted fool of a daughter -- or is it my son? -- has gotten into trouble. One of them has a gambling problem and has fallen afoul of some hoodlums. If these ruthless crooks aren''t paid, one of them will get hurt. Would you go and save whichever one of them got into this mess?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 12, 'npc_2_1', 'You must be an art lover to do something this dull. I suppose I''ll have to pay you. Meet the courier and bring me back the name of this no-talent guttersnipe.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 13, 'npc_2_2', 'My daughter -- or was it my son? -- well, one of them was going on a nature walk. Find whichever of them it was and bring him back here -- or her -- before those hooligans get hold of, of, whoever it is.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 14, 'npc_3_1', 'Why are you wasting my time?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 15, 'npc_3_2', 'What do you mean, "no"? How can you just leave my child, whichever it is, to those criminals?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 16, 'npc_4_1', 'A contest to see which talentless young boob can make a prettier holo than the other, or some such nonsense. Modern art, bah! Can''t stand any of it. This Arts Gala is all a sham. So were you going to do this for me or not? '),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 17, 'npc_4_2', 'I wasn''t born this old, you know. You young people think you invented fun. Are you going to rescue my son or not? Or was it my daughter? I can never keep track of who''s who anymore.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 22, 'npc_backtowork_1', 'Were you going to do this or not?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 23, 'npc_backtowork_2', 'What do you want now? I''ve told you as much as I can remember.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 24, 'npc_breech_1', 'I was beginning to think they''d forgotten to send someone.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 25, 'npc_breech_2', 'Did my father send you with the ransom money?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 27, 'npc_dropoff_2', 'Thanks for rescuing me from those goons. I''ve learned my lesson.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 28, 'npc_failure_1', 'I guess I''ll have to hire somebody else to find out who won this silly competition.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 29, 'npc_failure_2', 'Who did I send you to find? Oh well, it probably wasn''t that important.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 36, 'npc_noloc_1', 'How should I know where you''re supposed to meet him? I''ll call someone and find out where he is. Why do I always have to do everything myself? Be back in a little while.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 37, 'npc_noloc_2', 'Let me find out where that nature walk was going to take place. See me in a while. Maybe I can even figure out which one of my children it was.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 38, 'npc_reset_1', 'You think you can just give up? -- Well, that''s true. But you should finish what you start! It helps keep you regular!'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 39, 'npc_reward_1', 'What do you mean, pay you? You haven''t even left yet. Oh, the disc -- How did it get to be this late? '),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 40, 'npc_reward_2', 'Is that my son or my daughter? My eyes aren''t what they used to be.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 41, 'npc_smuggle_1', 'I''ve got your disc right here. Safe travels, friend.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 44, 'npc_takeme_2', 'I can''t believe he forgot to send the ransom. Next time I''d better ask my mother for help.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 45, 'npc_work_1', 'Have you picked up the disk with the winner yet? I''m not getting any younger.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 46, 'npc_work_2', 'Were you going to make that rescue soon?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 48, 'otherescort_2', 'This probably isn''t the healthiest place for you to be. '),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 49, 'player_1_1', 'Yes'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 50, 'player_1_2', 'Yes'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 51, 'player_2_1', 'No'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 52, 'player_2_2', 'No'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 53, 'player_3_1', 'What competition is this?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 54, 'player_3_2', 'You have a son? You''ve got to be kidding.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 55, 'player_4_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 56, 'player_4_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 57, 'player_5_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 58, 'player_5_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 67, 'return_waypoint_description_1', 'Return to Sidoras Bey with the disc'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 68, 'return_waypoint_description_2', 'Return to Sidoras Bey with Silaras Bey'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 69, 'return_waypoint_name_1', 'Sidoras Bey'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 70, 'return_waypoint_name_2', 'Sidoras Bey'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 71, 'waypoint_description_1', 'Go meet the courier and pick up the disc with the name of the art contest winner'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 72, 'waypoint_description_2', 'Go and rescue Silaras Bey '),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 73, 'waypoint_name_1', 'The courier''s location'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 74, 'waypoint_name_2', 'Silaras Bey''s location'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 75, 'npc_reset_2', 'You think you can just give up? -- Well, that''s true. But you should finish what you start! It helps keep you regular!'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 76, 'npc_reset_3', 'You think you can just give up? -- Well, that''s true. But you should finish what you start! It helps keep you regular!'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 77, 'player_reset_2', 'Can I do something else and come back to this later?'),
('string/en/static_npc/rori/rori_narmle_sidoras_bey.stf', 78, 'player_sorry_2', 'Forgot what I was doing.  I''ll get back to work.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 1, 'cant_work', 'If you''re interested in Rori''s "Great Conversation" debate, talk to me when you''re less busy.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 2, 'dontknowyou_1', 'I am certain you have the wrong person.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 3, 'dontknowyou_2', 'You definitely have the wrong person.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 4, 'gotowork_1', 'Shouldn''t you be going?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 5, 'gotowork_2', 'The Minister, Sindra Lintikoor, told me you''d have an invitation for me. Don''t you?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 6, 'next', 'I believe the Great Conversation debate is shaping up according to plan -- at least for now. I don''t have anything else to keep you busy. But thanks for your help.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 7, 'notit_1', 'I expected you to bring me a datadisc with Ingon Lakbo''s response to my invitation. This isn''t it.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 8, 'notit_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 9, 'notyet', 'Sorry, too busy to talk.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 10, 'npc_1_1', 'Good day. I am Minister of Education for Narmle. For the upcoming "Great Conversation" debate between Narmle''s leading scholars and those of Restuss, I''ve invited the illustrious thinker Ingon Lakbo. Would you be so kind as to pick up his response?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 11, 'npc_1_2', 'I''m glad you''re looking for another assignment. Ingon Lakbo''s curt refusal to participate in our "Great Conversation" debate with Restuss means that I can now invite Ingon''s bitter rival in his stead. Will you deliver the invitation?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 12, 'npc_2_1', 'I look forward to getting Lakbo''s response to my invitation. His is a fine mind, and his participation an asset to our debate.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 13, 'npc_2_2', 'Good. I''ll look forward to your report of success, and then to Bieque''s attendance at our debate.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 14, 'npc_3_1', 'That''s a disappointment, but I understand. Let me know if you change your mind.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 15, 'npc_3_2', 'After your earlier help, I was hoping for more. Well, I hope you''ll change your mind.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 16, 'npc_4_1', 'The two towns on Rori, Narmle and Restuss, stage frequent debates between their intellectuals. Victory validates the winner''s superiority. It''s Rori''s equivalent of a sporting match. Would you pick up Ingon''s response, so I know whether he can participate?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 17, 'npc_4_2', 'I''m inviting the philosopher Bieque Lozan-Lippid. He''s quite well regarded in Narmle, except by Ingon Lakbo, with whom he once engaged in a fistfight on the topic of the nature of evil. Charming man, though, when not out of temper.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 19, 'npc_5_2', 'In this installment we ponder the issue of bacta restoration. When I am killed in combat and then emerge from a bacta tank soon afterward, am I still me? Or am I a mere simulacrum? These are questions of fundamental importance across the galaxy.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 22, 'npc_backtowork_1', 'Haven''t you brought Ingon Lakbo''s response to my invitation? I need to know whether he''ll participate in the "Great Conversation" debate.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 23, 'npc_backtowork_2', 'I hoped by now you''d have delivered that invitation to Bieque Lozan-Lippid. He''s waiting, you know.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 24, 'npc_breech_1', 'I am Ingon Lakbo. Are you here to pick up my response?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 25, 'npc_breech_2', 'Are you here from the Minister of Education?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 28, 'npc_failure_1', 'You didn''t bring Ingon Lakbo''s response to my invitation? Well, maybe I''ll try to reach him by HoloNet. I doubt that will work -- he despises electronic communication.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 29, 'npc_failure_2', 'You didn''t deliver that invitation to Bieque Lozan-Lippid? Well, I''ll have to find someone else. Thank you anyway.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 31, 'npc_more_1_2', 'A thinker of any complexity inevitably draws resentment from those less gifted. Then, too, there is an emotional dimension to certain rivalries, which I''d rather not discuss at this time. Thank you.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 36, 'npc_noloc_1', 'I''m waiting to hear from Ingon now about where he''d like you to meet him. Talk to me again in a few moments.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 37, 'npc_noloc_2', 'I''m waiting to hear from Bieque when he''s ready to rendezvous. Talk to me in a few moments.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 38, 'npc_reset_1', 'Very well. I hope you''ll return when you have more interest.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 39, 'npc_reward_1', 'Let me just see what Lakbo says -- hmm! He rejects my invitation, and rather casually. Well, this has a bright side. Now I have another job waiting, so please talk to me soon.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 40, 'npc_reward_2', 'I hope Bieque Lozan-Lippid will attend our debate. With his oratical skill, we can trounce those Restuss thinkers. He''s their bad dream.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 41, 'npc_smuggle_1', 'I have no interest in attending this so-called Great Conversation, for I regard the Restuss scholars as a job-lot of ignorant monkey-lizards. I say as much to the Minister in my response.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 42, 'npc_smuggle_2', 'I shall consider attending the Great Conversation debate. I only hope I won''t see certain of my enemies there. Please give my thanks to the Minister.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 45, 'npc_work_1', 'I''ve given you Ingon Lakbo''s coordinates, so you have everything you need to get started.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 46, 'npc_work_2', 'I''ve given you the coordinates for Bieque Lozan-Lippid. I hope you''ll get started soon.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 53, 'player_3_1', 'What is "The Great Conversation" debate?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 54, 'player_3_2', 'Who is Ingon Lakbo''s bitter rival?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 55, 'player_4_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 56, 'player_4_2', 'What is the subject of this "Great Conversation" debate?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 57, 'player_5_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 58, 'player_5_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 60, 'player_more_1_2', 'Who are your enemies?'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 67, 'return_waypoint_description_1', 'Narmle''s Minister of Education is waiting for a response from scholar Ingon Lakbo to her invitation to participate in "The Great Conversation" debate.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 68, 'return_waypoint_description_2', 'Narmle''s Minister of Education sent an invitation to noted philosopher Bieque Lozan-Lippid to participate in "The Great Conversation" debate.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 69, 'return_waypoint_name_1', 'Sindra Lintikoor'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 70, 'return_waypoint_name_2', 'Sindra Lintikoor'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 71, 'waypoint_description_1', 'Leading philosopher of Narmle, waiting to respond to Sindra Lintikoor''s invitation to participate in "The Great Conversation" debate.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 72, 'waypoint_description_2', 'Noted philosopher awaiting an invitation from Narmle Minister of Education Sindra Lintikoor to participate in "The Great Conversation" debate.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 73, 'waypoint_name_1', 'Ingon Lakbo'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 74, 'waypoint_name_2', 'Bieque Lozan-Lippid'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 75, 'npc_reset_2', 'Very well. I hope you''ll return when you have more interest.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 76, 'player_reset_2', 'I can''t do this right now.'),
('string/en/static_npc/rori/rori_narmle_sindra_lintikoor.stf', 77, 'player_sorry_2', 'Oh, I''ll get back to work.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 1, 'cant_work', 'Friend, I have a job for you that''ll change how you look at the galaxy. See me when you finish what you''re doing.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 3, 'dontknowyou_2', 'I''m waiting for somebody else to meet me here.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 6, 'next', 'I''ve done all I can with you right now, my friend. Check back later and maybe I''ll have something new for you.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 7, 'notit_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 8, 'notit_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 9, 'notyet', 'Oh, I''m sorry.  Can you come back later?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 10, 'npc_1_1', 'I made a deal with the chief administrator that, for a very reasonable rate, I could clear out a nest of hermit spiders that would threaten the upcoming Narmle Arts Gala. The beauty of this idea is, hermit spiders are solitary creatures. You go kill one for me -- I tell Bindoo we got the queen, so the nest is history -- job''s done! What do you say?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 11, 'npc_1_2', 'If there''s one thing folks don''t like, it''s someone who cheats at cards. In fact, infuriated citizens recently chased my sabaac partner out of town because he was cheating. He wants to come back, but he''s afraid they might still be looking for him. Might you escort him back here?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 12, 'npc_2_1', 'It''s a simple thing. Just go and kill a hermit spider and come back the victorious spider-slaying hero. Oh, and remember -- when you got to the mound, there were at least fifty of them, you had to lob a thermal detonator, and the carnage was fantastic. Got it? Good.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 13, 'npc_2_2', 'Great. Be careful of those other card players -- I get the feeling they know how to hold a grudge.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 14, 'npc_3_1', 'What''s the matter? Afraid of spiders?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 15, 'npc_3_2', 'Maybe I should just find a partner who cheats better.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 16, 'npc_4_1', 'You know how it is -- scare some children with a couple of realistic remote-control spider-droids, and stories start spreading. Jaleela Bindoo may know about art, but toss a couple of fake dead spiders in front of her and she loses all reason. So are you in or not?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 17, 'npc_4_2', 'Of course not! They didn''t catch me. It''s only cheating if they notice you doing it. So what do you say, friend, will you escort my partner back here safely?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 22, 'npc_backtowork_1', 'If you don''t want in on this deal, just say so.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 23, 'npc_backtowork_2', 'No need to get pushy, friend. If you don''t want the credits just say so.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 24, 'npc_breech_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 25, 'npc_breech_2', 'Did Zeelius send you? '),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 27, 'npc_dropoff_2', 'Thanks for getting me here. I''d better work on my deal.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 28, 'npc_failure_1', 'Couldn''t kill the spider, eh? Blast!'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 29, 'npc_failure_2', 'That''s too bad. Maybe I should start interviewing new sabaac partners. Do you play?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 36, 'npc_noloc_1', 'Let me locate a likely lair for a hermit spider. Check with me in a short while.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 37, 'npc_noloc_2', 'Let''s wait for the lynch mob to settle down. See me in a while, and it should be safe enough to go get my partner.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 38, 'npc_reset_1', 'Don''t you worry, friend, just come back when you think you can finish the job.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 39, 'npc_reward_1', 'Nice work. I''ll let Jaleela Bindoo know her "spider problem" is taken care of.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 40, 'npc_reward_2', 'Who is this? I''ve never seen this guy before in my life -- I''m kidding. You did great.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 44, 'npc_takeme_2', 'From the way they react, you''d think none of these people has ever cheated at cards. Get me out of here.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 45, 'npc_work_1', 'Hurry up and kill that spider. I don''t want people to think I''m lazy.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 46, 'npc_work_2', 'Where is my partner? I thought you already left to get him.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 48, 'otherescort_2', 'I''m waiting for somebody else to meet me here.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 53, 'player_3_1', 'How could she have possibly believed that lame story?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 54, 'player_3_2', 'If he was your partner, doesn''t that mean you were cheating too?'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 55, 'player_4_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 56, 'player_4_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 57, 'player_5_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 58, 'player_5_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 67, 'return_waypoint_description_1', 'Report your amazing success to Zeelius Kraymunder.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 68, 'return_waypoint_description_2', 'Escort Kraymunder''s gambling partner back to him.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 69, 'return_waypoint_name_1', 'Kraymunder''s Location'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 70, 'return_waypoint_name_2', 'Zeelius Kraymunder''s Location'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 71, 'waypoint_description_1', 'Get rid of the pesky hermit spider.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 72, 'waypoint_description_2', 'Find Kraymunder''s gambling partner.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 73, 'waypoint_name_1', 'Hermit Spider''s Location'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 74, 'waypoint_name_2', 'Gambling Partner''s Location'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 75, 'npc_reset_2', 'Don''t you worry, just come back when you can.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 76, 'player_reset_2', 'Sorry, I can''t do this now.'),
('string/en/static_npc/rori/rori_narmle_zeelius_kraymunder.stf', 77, 'player_sorry_2', 'I''ll get back to work.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 1, 'cant_work', 'Yousa be talkin'' to mesa back here when yousa not bein'' so busy, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 2, 'dontknowyou_1', 'Imperial business. Clear the area.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 3, 'dontknowyou_2', 'Imperial business. Move along.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 6, 'next', 'Heydo! My busy workin'' on de necklace for Raxa. My be stickin'' on de termal detanator soon!'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 7, 'notit_1', 'My tinkin'' dat''s not de ting my askin'' you for.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 8, 'notit_2', 'Yousa bringin'' mesa dat termal detanator? Disa not it.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 9, 'notyet', 'Sorry, mesa no can talk to you now.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 10, 'npc_1_1', 'Heydo! My workin'' on makin'' a necklace from Empire officer rank cylinder tings. My knowin'' ''bout a warrant officer in de wilds wit some soldiers. My wantin'' you to be killin'' de warrant officer an'' bringin'' mesa hisa rank cylinder ting. Hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 11, 'npc_1_2', 'Ello! My workin'' hard on de necklace for Raxa Binn. My needin'' a nice pendant now -- mesa tinkin'' a termal detanator. Yousa mebbe killin'' disa Empire Army captain an'' gettin'' it for mesa?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 12, 'npc_2_1', 'Oie boie, yousa good friend. My givin'' yousa de coordinates right now. Yousa bringin'' de cylinder ting back to me, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 13, 'npc_2_2', 'Owoo! My givin'' yousa de coordinates right now. Disa captain, hesa got mooie bombad troopers wit him, so yousa be careful, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 14, 'npc_3_1', 'Hokay, bye.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 15, 'npc_3_2', 'Hokay, bye.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 16, 'npc_4_1', 'Here at Zephyr Base wesa plannin'' strategies for fightin'' de Empire on Naboo. My bein'' liyayzonn to all Gungans on Naboo, gettin'' dere hep.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 17, 'npc_4_2', 'Ooh, one time mesa overhearin'' Raxa Binn, shesa sayin, "Evvy tim I seein'' dat Gungan, I want a termal detanator."'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 18, 'npc_5_1', 'My be sweetin'' on de commando trainer here, Raxa Binn. Shesa mooie-mooie! My tinkin'' shesa likin'' a necklace made of Empire rank cylinder tings.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 19, 'npc_5_2', 'Disa one of Colonel Zarvold''s men. Raxa Binn, shesa hatin'' Zarvold -- mesa not knowin'' why -- an'' will like dis detanator for, mesa thinkin'', sentimental value.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 20, 'npc_6_1', 'Ooah, de rank cylinder tings for warrant officers bein'' just de right color for matchin'' Raxa Binn''s eyes!'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 21, 'npc_6_2', 'Hesa Cap''n Rohd Gostervek, mooie bombad Imperial. Hesa patrollin'' de wilderness, lookin'' for dis base. Hesa always protected, so yousa be careful, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 22, 'npc_backtowork_1', 'My not knowin'' anyting else to be tellin'' yousa, sorry.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 23, 'npc_backtowork_2', 'My not knowin'' anyting else to be tellin'' yousa, sorry.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 24, 'npc_breech_1', 'It''s a Rebel! Protect me, you fools!'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 25, 'npc_breech_2', 'Rebel sighted! Open fire!'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 28, 'npc_failure_1', 'Yousa no got de rank cylinder ting? Awoo, my never gonna finish disa necklace for Raxa.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 29, 'npc_failure_2', 'Owoo! No termal detanator? Mooie bombad! Raxa Binn, shesa nevah likin'' mesa now!'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 36, 'npc_noloc_1', 'My waitin'' now for coordinates for de Empire patrol. Yousa be checkin'' wit mesa soon, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 37, 'npc_noloc_2', 'My waitin'' for Zephyr Base tellin'' where''s disa captain. Yousa talkin'' to mesa real soon, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 38, 'npc_reset_1', 'Dat okay wit mesa. Yousa go be doin'' your works, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 39, 'npc_reward_1', 'Oie boie! Disa de just-right ting mesa needin'' on de necklace for Raxa! Tanks! Yousa be talkin'' to mesa ''gain soon, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 40, 'npc_reward_2', 'Ooh, yousa bombad! Disa gonna be de sweetest necklace for de sweetest Zabrak commando trainer in de worl''. Shesa seein'' dis an'' gettin'' all soft an'' sweet ovah mesa. Tanks!'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 45, 'npc_work_1', 'Yousa gettin'' dat rank cylinder ting yet? My workin'' on Raxa''s necklace berry hard.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 46, 'npc_work_2', 'Yousa not gettin'' dat termal detanator yet? My workin'' berry hard on de necklace.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 53, 'player_3_1', 'Who are you?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 54, 'player_3_2', 'Why do you want a thermal detonator for a necklace pendant?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 55, 'player_4_1', 'Who is getting the gift necklace you''re making?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 56, 'player_4_2', 'Why do you want a detonator from this particular Imperial Army captain?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 57, 'player_5_1', 'Why does the rank cylinder have to be from this warrant officer?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 58, 'player_5_2', 'Who is the Imperial Army captain?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 67, 'return_waypoint_description_1', 'Gungan liaison to the Zephyr Base Alliance outpost on Rori, currently waiting for an Imperial rank cylinder that he wants to add to a necklace.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 68, 'return_waypoint_description_2', 'Gungan liaison to the Zephyr Base Alliance outpost on Rori, currently waiting for a thermal detonator to use as a necklace pendant.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 69, 'return_waypoint_name_1', 'Booto Lubble'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 70, 'return_waypoint_name_2', 'Booto Lubble'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 71, 'waypoint_description_1', 'On patrol from Colonel Zarvold''s Imperial Army battalion on Rori, this officer carries an Imperial rank cylinder sought by Booto Lubble, Gungan liaison to the Zephyr Base Alliance outpost on Rori.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 72, 'waypoint_description_2', 'A patrol from Colonel Zarvold''s Imperial Army battalion on Rori, equipped with a thermal detonator sought by Booto Lubble, Gungan liaison to the Zephyr Base Alliance outpost.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 73, 'waypoint_name_1', 'Imperial Warrant Officer'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 74, 'waypoint_name_2', 'Thermal Detonator'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 75, 'npc_reset_2', 'Dat okay wit mesa.  Yousa go be doin'' your works, hey?'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_booto_lubble.stf', 77, 'player_sorry_2', 'I''ll keep working on it.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 1, 'cant_work', 'I ask a lot from the people who work for me. I need your full concentration. Come see me when you''ve finished whatever you''re doing now.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 2, 'dontknowyou_1', 'Clear out of here, citizen. I''ll only give you this one warning.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 3, 'dontknowyou_2', 'This isn''t something you should get involved in. '),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 6, 'next', 'That''s all I have for you to do right now. If we attract too much attention, the Imperials will find this outpost. Come see me a little later, perhaps things will have settled down by then and we can cause some more trouble.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 7, 'notit_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 8, 'notit_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 9, 'notit_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 10, 'notyet', 'Can''t talk.  Busy.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 11, 'npc_1_1', 'My name is Raxa Binn. I train commandos here at Zephyr Base as well as wreak a little havoc on the Imperials when time permits. If you want to get on my good side you should do a little work for me. You could pick up a few credits and help the Alliance at the same time. Interested?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 12, 'npc_1_2', 'You handled that last job pretty well. Let''s see what you can do with something a little more difficult. One of the outpost''s scouts is overdue to check in and some stormtrooper commandos have been spotted in the vicinity of that patrol area. We think they may have captured our scout. Would you be willing to go handle the rescue?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 13, 'npc_1_3', 'I had some of our scouts check out why there''s been so much action here recently. Those commandos were part of a larger mobile force looking for Alliance activity. I need someone who''s willing to go and take out this mobile base. Are you interested or is it too much for you?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 14, 'npc_2_1', 'Good. There is a group of Imperial stormtroopers that have been getting a little too close to this outpost for my liking. Their leader is a stormtrooper squad leader. I think he''s the one who suspects something is going on. Next time he''s on patrol, take him out. He''ll have friends with him, so bring some people you can trust.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 15, 'npc_2_2', 'You''re a credit to our cause - if you can pull this off. These people are about as well trained as Imperial soldiers get, so bring a lot of firepower and some backup that you trust. Good luck. '),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 16, 'npc_2_3', 'You have two objectives: First, take out that base; second, leave no survivors. This isn''t going to be easy. Get your team together and leave immediately. Good luck.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 17, 'npc_3_1', 'Maybe you need to toughen up a little if you don''t think you''re up to this.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 18, 'npc_3_2', 'I wish they''d stop sending me people who were all talk and no action.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 19, 'npc_3_3', 'I though it might be beyond your skills. This will need an elite team.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 20, 'npc_4_1', 'I want you to help the Alliance. More specifically, I want you to kill as many of those Imperial goons as you can. I''ll tell you which ones once you''ve agreed to do it. Otherwise, you don''t need to know. What''s it going to be?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 21, 'npc_4_2', 'They''re an elite group of stormtroopers with some of the best training and equipment available. Still interested?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 22, 'npc_4_3', 'Not nearly so much as if they find this outpost. We can always relocate to keep them off our track once you''ve taken care of their base. Are you up to this or not?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 23, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 24, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 25, 'npc_5_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 26, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 27, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 28, 'npc_6_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 29, 'npc_backtowork_1', 'What is it now? I don''t like interruptions.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 30, 'npc_backtowork_2', 'I''ve told you all I can. Are you going or not?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 31, 'npc_backtowork_3', 'You know the risks. Are you going to do this or not?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 32, 'npc_breech_1', 'Rebel scum!'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 33, 'npc_breech_2', 'Get your hands off me, you Imperial lackeys! '),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 34, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 35, 'npc_dropoff_2', 'Thanks, pal. Maybe one day I can return the favor.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 36, 'npc_failure_1', 'I warned you it might be tough. Maybe you can take him out next time.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 37, 'npc_failure_2', 'I''m getting the impression your mission was less than successful. We''ll have to make another attempt quickly. '),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 38, 'npc_failure_3', 'Something has to be done. I can''t allow that base to put my people at risk.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 39, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 40, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 41, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 42, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 43, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 44, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 45, 'npc_noloc_1', 'Let me check our intelligence on his whereabouts. Come and see me in a few minutes and I''ll know where to send you.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 46, 'npc_noloc_2', 'I''ll need a moment to get our scouts last known location. Check back with me in a few minutes.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 47, 'npc_noloc_3', 'I''ll check with my scouts for the location of this mobile base. Come back in a few minutes and I''ll get you those coordinates.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 48, 'npc_reset_1', 'Come back when you think you''re ready for this. There are always more Imperials that need to die.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 49, 'npc_reward_1', 'You''ve done well. I may find more uses for you. Check back with me.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 50, 'npc_reward_2', 'Not bad at all. You may have the makings of a fine commando.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 51, 'npc_reward_3', 'Well done. If I had a few more like you on our team, I could send those Imperials packing in no time.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 52, 'npc_smuggle_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 53, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 54, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 55, 'npc_takeme_2', 'Perfect timing. They were just about to bring me back for questioning.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 56, 'npc_work_1', 'Have you taken out that squad leader yet? I don''t want him finding this place.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 57, 'npc_work_2', 'Hurry up and rescue our scout. I don''t want this outpost compromised.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 58, 'npc_work_3', 'I want that base taken out. Get going.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 59, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 60, 'otherescort_2', 'This isn''t something you should get involved in. '),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 61, 'player_1_1', 'Yes'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 62, 'player_1_2', 'Yes'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 63, 'player_1_3', 'Yes'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 64, 'player_2_1', 'No'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 65, 'player_2_2', 'No'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 66, 'player_2_3', 'No'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 67, 'player_3_1', 'What do you want me to do?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 68, 'player_3_2', 'What are these stormtrooper commandos?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 69, 'player_3_3', 'Won''t it attract a lot of attention if they all go missing?'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 70, 'player_4_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 71, 'player_4_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 72, 'player_4_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 73, 'player_5_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 74, 'player_5_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 75, 'player_5_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 76, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 77, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 78, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 79, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 80, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 81, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 82, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 83, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 84, 'return_waypoint_description_1', 'Return to Raxa Binn and inform her that your mission was successful.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 85, 'return_waypoint_description_2', 'Return to Raxa Binn with the Rebel scout'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 86, 'return_waypoint_name_1', 'Raxa Binn'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 87, 'return_waypoint_name_2', 'Raxa Binn'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 88, 'waypoint_description_1', 'Go find and kill the Stormtrooper squad leader'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 89, 'waypoint_description_2', 'Rescue the Rebel scout'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 90, 'waypoint_name_1', 'Stormtrooper squad leader''s location'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 91, 'waypoint_name_2', 'Rebel scout''s location'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 92, 'npc_reset_2', 'Come back when you think you''re ready for this. There are always more Imperials that need to die.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 93, 'npc_reset_3', 'Come back when you think you''re ready for this. There are always more Imperials that need to die.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 94, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 95, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 96, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_rebeloutpost_raxa_binn.stf', 97, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 1, 'cant_work', 'Come back and talk to me about an assignment when you''ve finished your current one.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 2, 'dontknowyou_1', 'I''m afraid I can''t talk to you at the moment. I''m busy with something.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 3, 'dontknowyou_2', 'Sadly, I have no time for you. '),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 4, 'dontknowyou_3', 'Get lost! I ain''t got no time for the likes of you.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 8, 'next', 'You''ve been a great help to the Alliance. I don''t need your services at the moment but check back with me later. You never know around here when an emergency will spring up. May the Force be with you.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 9, 'notit_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 10, 'notit_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 11, 'notit_3', 'Those are not the permits I asked you to bring me.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 12, 'notyet', 'I don''t have anything to say to you right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 13, 'npc_1_1', 'I hope you''re here to work, because we''ve got plenty to do. A respected Naboo scientist has just arrived on Rori. This individual has been studying Gungan weapons technology and is crucial to the Alliance''s efforts. High Inquisitor Sikander has placed a deathmark on his head so we need to act fast. Can I count on you to get this Naboo scientist back here safely?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 14, 'npc_1_2', 'Sometimes I hate dealing with these "procurement specialists" but what choice do people like us have? The smuggler who was supposed to get our Naboo scientist offworld has just adjusted his price. He now wants us to rescue his Twi''lek girlfriend as part of the payment for getting the scientist to High Command. I have no choice but to accept. Do you think you could tackle this mission?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 15, 'npc_1_3', 'The plot thickens, it seems. The pirate captain got wind of your rescue and ordered a strike on our smuggler friend. The smuggler escaped with his life but he lost the transport permits we had acquired for him. The pirate captain has them now and we need to get them back. Do you think you can do that?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 16, 'npc_2_1', 'Good. Here are the coordinates where the scientist was dropped off. Be ready for trouble. Our agents say that several bounty hunters have recently arrived on Rori. Best of luck.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 17, 'npc_2_2', 'I''m glad I can count on you. The girlfriend is being taken to the pirate captain. You need to intercept her and take care of her captors. It''s important she come back alive or the smuggler will back out of our deal.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 18, 'npc_2_3', 'Excellent. Our smuggler gave us the coordinates to the pirate''s hideout. The captain should have the permits with him. This mission will be tough. Feel free to solicit help from your comrades. Best of luck.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 19, 'npc_3_1', 'Then if you''ll excuse me, I have lots of work to do.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 20, 'npc_3_2', 'I understand. I hate getting in the middle of these squabbles too. I''ll find someone else to take care of this.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 21, 'npc_3_3', 'Perhaps I''ve asked too much of you already. I''ll get someone else to do this.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 22, 'npc_4_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 23, 'npc_4_2', 'I don''t know the whole story but it has something to do with a gambling debt and a long-standing feud between this smuggler and a notorious pirate. Believe me, the less you know, the better. Will you help?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 24, 'npc_4_3', 'It''s a matter of timing and urgency. Plus, if the pirate captain wanted to send those permits to the Imperials, he could jeopardize our covert agents on half a dozen worlds. Those permits are too valuable to leave in his hands. Will you get them back? '),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 31, 'npc_backtowork_1', 'If you feel this mission is beyond your abilities, I understand. Do you wish to reconsider?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 32, 'npc_backtowork_2', 'If you''d like to reconsider, I understand. I hate getting tangled in private feuds of this sort.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 33, 'npc_backtowork_3', 'I''ve explained everything you need to know. Did you wish to back out?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 34, 'npc_breech_1', 'Hello? Did Commander Sildor send you?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 35, 'npc_breech_2', 'Help! I''m being kidnapped by pirates!'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 36, 'npc_breech_3', 'You shouldn''t be wandering around here, pal. It''s bad for your health.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 37, 'npc_dropoff_1', 'I am most grateful to you. I don''t believe I would have made it back alive without your assistance.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 38, 'npc_dropoff_2', 'I am most appreciative of your help. I shudder to think what would have happened to me if you had not come along. Farewell!'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 40, 'npc_failure_1', 'That scientist could have helped the Alliance develop more effective weapons against the Empire''s military machines. A shame you couldn''t bring him in.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 41, 'npc_failure_2', 'I sure hope I can find another smuggler who''s willing to take the Naboo scientist to High Command. I really don''t need this aggravation.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 42, 'npc_failure_3', 'I can only hope that pirate doesn''t sell those permits to the Imperials before we can mount another assault. With my luck, he''s probably already blasted off Rori.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 43, 'npc_more_1_1', 'I saw a bounty hunter on Naboo a few days before I was transported here. A hunter matching that description was seen on this planet a few hours ago by one of the smugglers who escorted me here. It can''t be a coincidence.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 44, 'npc_more_1_2', 'It''s all my fault, I''m afraid. I fall in love too easily, you see. That can only lead to trouble. If you can, try to avoid falling in love.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 45, 'npc_more_1_3', 'Hah! Come and take ''em, sleemo! Rip it up, lads!'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 52, 'npc_noloc_1', 'I need to verify the Naboo scientist''s coordinates. Check back with me in a bit.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 53, 'npc_noloc_2', 'We have some surveillance droids tracking the Twi''lek girl. Give me a few moments to get the updated coordinates.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 54, 'npc_noloc_3', 'We need to verify those coordinates. Could you check back with me in a few moments?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 55, 'npc_reset_1', 'Feel free to come back when you feel you can finish what you start. Good luck.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 56, 'npc_reward_1', 'Well done, friend. The Alliance is greatful for your help. I hope you''ll stick around for a bit.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 57, 'npc_reward_2', 'You''re a reliable and effective agent. Could use more like you. Job well done.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 58, 'npc_reward_3', 'Well done, friend. You''re a boon to the Rebellion. May the Force be with you.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 62, 'npc_takeme_1', 'We should leave at once. I believe a bounty hunter is after me. Be ready for a fight.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 63, 'npc_takeme_2', 'Could you take me back to your commander? I wish to thank him personally. He is most striking, is he not?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 65, 'npc_work_1', 'Where''s the Naboo scientist? We need to make sure he makes it here in one piece.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 66, 'npc_work_2', 'Did you bring that Twi''lek girl back yet? That smuggler keeps contacting me about her.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 67, 'npc_work_3', 'Did you get those transport permits yet? We need to get this scientist off Rori immediately.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 68, 'otherescort_1', 'I''m not the man you''re looking for.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 69, 'otherescort_2', 'I know you''d like it to be, but sadly I am not the one you are looking for.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 77, 'player_3_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 78, 'player_3_2', 'What am I rescuing his girlfriend from?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 79, 'player_3_3', 'Why not just get new permits?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 80, 'player_4_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 81, 'player_4_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 82, 'player_4_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 83, 'player_5_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 84, 'player_5_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 85, 'player_5_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 86, 'player_more_1_1', 'How do you know a bounty hunter is after you?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 87, 'player_more_1_2', 'What is this all about?'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 88, 'player_more_1_3', 'Hand over the transport permits and we can avoid trouble.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 97, 'return_waypoint_description_1', 'Escort the scientist safely back to Commander Sildor.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 98, 'return_waypoint_description_2', 'Escort the Twi''lek safely back to Commander Sildor.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 99, 'return_waypoint_description_3', 'Bring the permits back to Commander Sildor.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 100, 'return_waypoint_name_1', 'Commander Sildor''s Location'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 101, 'return_waypoint_name_2', 'Commander Sildor''s Location'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 102, 'return_waypoint_name_3', 'Commander Sildor''s Location'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 103, 'waypoint_description_1', 'Find the scientist who''s recently been smuggled off Naboo.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 104, 'waypoint_description_2', 'Rescue the Twi''lek from her pirate captors.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 105, 'waypoint_description_3', 'Get the transport permits from the pirate captain.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 106, 'waypoint_name_1', 'Naboo Scientist''s Location'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 107, 'waypoint_name_2', 'Twil''lek Girlfriend''s Location'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 108, 'waypoint_name_3', 'Pirate Captain''s Hideout'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 109, 'npc_reset_2', 'Feel free to come back when you feel you can finish what you start. Good luck.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 110, 'npc_reset_3', 'Feel free to come back when you feel you can finish what you start. Good luck.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 111, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 112, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 113, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_rebeloutpost_vordin_sildor.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 1, 'cant_work', 'I do have a few errands I need done. Come see me later when you''re in need of work.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 2, 'dontknowyou_1', 'Are you lost? I''m afraid I''m not very good with directions.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 3, 'dontknowyou_2', 'I''m just taking a little time off to do some surveying. Don''t worry about me.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 4, 'gotowork_1', 'What am I supposed to do with this? It makes no sense.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 5, 'gotowork_2', 'What is this for? Are you sure you meant to give me that?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 6, 'next', 'You''ve been a total dear but I don''t have anything else for you to do at the moment. Perhaps I can find something a bit later.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 7, 'notit_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 8, 'notit_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 9, 'notyet', 'Can you come back later?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 10, 'npc_1_1', 'Do you think you might have a few minutes to spare? I''m trying to find someone to help me with a few things but between the art festivals and the debate everybody is busy. I''m trying to arrange some gatherings for those of us who don''t really care which town is superior to the other. Do you think you can help me?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 11, 'npc_1_2', 'Do you happen to have a little more time to spare, dear? An artist friend of mine is trying to get noticed but I fear amid the swarm of other artists here for the Jubilee she hasn''t had much luck. I wanted to commission a dealer to buy several of her paintings and display them during the Jubilee. Do you think you could help me?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 12, 'npc_2_1', 'I''m so glad you can help. Bring this dinner party invitation to my dear friend Jinderliss Prason. You don''t need to worry about getting a response right away.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 13, 'npc_2_2', 'Go see if you can pull my art dealer away from surveying long enough to make my purchases. Just deliver these instructions and that should take care of it. A simple little thing really.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 14, 'npc_3_1', 'I understand. Delivering invitations isn''t terribly exciting. '),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 15, 'npc_3_2', 'I understand dear. You crave a life of excitement. I hope you find it.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 16, 'npc_4_1', 'Just a delivery right now. I know it''s a bit old-fashioned but I find a hand delivered invitation to be so much more personal. Would you mind terribly taking this invitation to my friend?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 17, 'npc_4_2', 'The art dealer that I use has gone off surveying. A strange hobby if you ask me, but many people do seem to enjoy it. I want you to deliver my request so that the purchase is made before the Jubilee. Will you help?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 22, 'npc_backtowork_1', 'Was there something else you needed, dear? Or have you changed your mind.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 23, 'npc_backtowork_2', 'Were you going to deliver that purchase request for me?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 24, 'npc_breech_1', 'Hello, friend. Are you looking for me?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 25, 'npc_breech_2', 'Hi. Are you looking for me?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 28, 'npc_failure_1', 'Oh my! I''m terribly sorry this caused you such trouble. I had no idea it would be so difficult. You poor dear.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 29, 'npc_failure_2', 'You poor thing. Sometimes even the simplest of tasks get all muddled with complications.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 36, 'npc_noloc_1', 'I tried to contact my friend but nobody seems to be around to receive the invitation right now. Maybe you could come back in a little while. I''ll keep trying.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 37, 'npc_noloc_2', 'Art dealers - you can never find one when you need one. Maybe someone at the gallery knows where mine is. Come see me in a few minutes. Hopefully I''ll know where to send you by then.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 38, 'npc_reset_1', 'Not to worry, dear. You come back later if you want to and do it then.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 39, 'npc_reward_1', 'Thank you so much. I confess I find the constant bickering between the two cities a bit tiresome.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 40, 'npc_reward_2', 'Thank you. I hope this helps her get the attention she deserves. She''s very talented.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 41, 'npc_smuggle_1', 'What''s this? An invitation from Ajuva? How marvelous. Something to do other than listen to all that dreary rivalry talk.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 42, 'npc_smuggle_2', 'A purchase request from -- Oh my! I''ll see to this right away. This will net me a nice commission.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 45, 'npc_work_1', 'Have you delivered that invitation yet? There''s no real rush, I was just wondering.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 46, 'npc_work_2', 'I don''t want to be a nuisance but could you deliver my purchase request soon. I''d hate to miss this opportunity to help my friend.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 53, 'player_3_1', 'What do you want done?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 54, 'player_3_2', 'What is it you need me to do?'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 55, 'player_4_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 56, 'player_4_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 57, 'player_5_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 58, 'player_5_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 67, 'return_waypoint_description_1', 'Report back to Ajuva to let her know all is well.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 68, 'return_waypoint_description_2', 'Report your success to Ajuva.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 69, 'return_waypoint_name_1', 'Ajuva Vanasterin''s Location'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 70, 'return_waypoint_name_2', 'Ajuva Vanasterin''s Location'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 71, 'waypoint_description_1', 'Deliver a dinner party invitation to Jinderliss Prason.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 72, 'waypoint_description_2', 'Deliver a purchase request to Ajuva''s art dealer.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 73, 'waypoint_name_1', 'Jinderliss Prason''s Location'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 74, 'waypoint_name_2', 'Art Dealer''s Location'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 75, 'npc_reset_2', 'Not to worry, dear. You come back later if you want to and do it then.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_ajuva_vanasterin.stf', 77, 'player_sorry_2', 'I''ll keep trying.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 1, 'cant_work', 'I could use a little help with things. See me when you''re not so busy.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 2, 'dontknowyou_2', 'You should probably get out of here.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 3, 'dontknowyou_3', 'I''m kind of hiding out, so if you could get lost, I''d really appreciate it.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 4, 'dontknowyou_4', 'This is a bad place to be. You''d better get out of here.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 6, 'gotowork_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 7, 'gotowork_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 8, 'next', 'That''s all I have for you right now. Check back with me later -- maybe something else will turn up.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 9, 'notit_1', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 10, 'notit_2', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 11, 'notit_3', 'You were supposed to bring back the art holo. What is this?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 12, 'notit_4', ' '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 14, 'npc_1_1', 'You''re not a smuggler, are you? You look shifty. To get on my good side, help me out with a little favor. One of our citizens owns a trained tusk-cat. It was always well behaved, but recently it ran off and has been attacking people indiscriminately. Will you find it and put it down? '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 15, 'npc_1_2', 'One of those stinking people from Narmle has stolen the holo we planned to use as the centerpiece for the Restuss Arts Jubilee. I''m just too busy to track this vermin down. But if the town gets wind of this, there will be an uproar the likes of which we''ve never seen. Will you find the culprit before word leaks to the town?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 16, 'npc_1_3', 'We got that thief to tell us what became of the stolen holo centerpiece intended for our Arts Jubilee. I want you to take the holo back from the smuggler that bought it. Will you do it? '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 17, 'npc_1_4', 'I need your help again, urgently. That smuggler had some unsavory friends who hold our town responsible for his death. They''ve sent a bounty hunter to kill our Chief Administrator for revenge. Will you stop the killer? '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 18, 'npc_2_1', 'Glad to hear you''re willing to help. Be careful now. Tusk-cats are fierce creatures. Find it and put it out of our misery.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 19, 'npc_2_2', 'Fortunately there''s a tracking beacon in the holo for just such cases as this. Bring the thief back here to taste a little Restuss justice.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 20, 'npc_2_3', 'Get that holo back no matter what it takes. I don''t want that smuggler to make it offworld with our precious art.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 21, 'npc_2_4', 'I thought you might be willing to help. Stop this killer by any means necessary. Good luck.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 22, 'npc_3_1', 'I guess you don''t take much interest in helping the law. You''d better not cause any trouble around here.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 23, 'npc_3_2', 'I better not find out you had anything to do with this. I don''t much care for thieves or smugglers.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 24, 'npc_3_3', 'I can''t believe you''d let Restuss down in our darkest hour. I''m very disappointed. You''re not from Narmle, are you?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 25, 'npc_3_4', 'It''s your choice. Don''t be surprised when they''re looking for you next.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 26, 'npc_4_1', 'That''s it exactly. If you kill it, you can just claim you were defending yourself, and the owner can''t complain about that. What do you say?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 27, 'npc_4_2', 'Those poseurs have always been jealous of our Arts Jubilee. Now they''ve gone too far. Will you find the thief and bring him back?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 28, 'npc_4_3', 'Possibly, but they might be planning to use it in Narmle. I wouldn''t put it past those lowlifes. Will you at least try to find that holo?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 29, 'npc_4_4', 'I''m sure if they knew you were responsible they''d be happy to have you killed too. No doubt they''ll find out about you -- unless you stop this killer. How about it?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 30, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 31, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 32, 'npc_5_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 33, 'npc_5_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 34, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 35, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 36, 'npc_6_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 37, 'npc_6_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 38, 'npc_backtowork_1', 'If you don''t think you can handle this, just say so.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 39, 'npc_backtowork_2', 'I''ve told you everything I know. Was there anything else? '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 40, 'npc_backtowork_3', 'You''re not giving up on me, are you?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 41, 'npc_backtowork_4', 'If you don''t think you can stomach this one, tell me now. '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 42, 'npc_breech_2', 'How did you find me so quickly?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 43, 'npc_breech_3', 'I''ve got too much invested in this deal to give up now.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 44, 'npc_breech_4', 'You think you can stop me? You''re wrong -- dead wrong.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 45, 'npc_dropoff_2', 'I took the tracking beacon out of the holo. They''ll never find it now.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 46, 'npc_dropoff_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 47, 'npc_dropoff_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 48, 'npc_failure_1', 'You couldn''t kill it? I warned you they were fierce.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 49, 'npc_failure_2', 'The thief got away. Blast! We have to get that holo back.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 50, 'npc_failure_3', 'Oh no! Our city will be the laughingstock of Rori.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 51, 'npc_failure_4', 'We''ve got to find a way to stop this killer before it''s too late.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 52, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 53, 'npc_more_1_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 54, 'npc_more_1_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 55, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 56, 'npc_more_2_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 57, 'npc_more_2_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 58, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 59, 'npc_more_3_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 60, 'npc_more_3_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 61, 'npc_noloc_1', 'Let me find out the location of the most recent attacks. That''s the most likely area to find it. See me again soon.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 62, 'npc_noloc_2', 'I need to check the tracer in the holo for its current location. See me soon and I''ll have that information.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 63, 'npc_noloc_3', 'Give me a few minutes to have another little chat with our thief. Perhaps I can get some useful information to lead you to that smuggler.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 64, 'npc_noloc_4', 'Let me check with Chief Administrator Zindalai and make sure I haven''t forgotten anything. See me in a few minutes and we''ll get started. '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 65, 'npc_reset_1', 'If you''re not up to doing this right now, see me a little later.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 66, 'npc_reward_1', 'Well done. You handled that like a pro. '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 67, 'npc_reward_2', 'This thief may not be from Narmle, but I''m guessing someone from there set up this whole thing.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 68, 'npc_reward_3', 'Great work, friend. You''ve saved the Restuss Jubilee. That''ll show Narmle!'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 69, 'npc_reward_4', 'Well done, friend. That should teach those smugglers not to mess with Restuss. '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 70, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 71, 'npc_smuggle_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 72, 'npc_smuggle_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 73, 'npc_takeme_2', 'Don''t hurt me. I''ll go quietly.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 74, 'npc_takeme_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 75, 'npc_takeme_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 76, 'npc_work_1', 'Have you killed that tusk-cat yet? I don''t want that thing hurting anyone else.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 77, 'npc_work_2', 'Did you find that thief yet? '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 78, 'npc_work_3', 'Have you caught up with that smuggler yet? '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 79, 'npc_work_4', 'Did you find that killer yet? Don''t wait too long. '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 80, 'otherescort_2', 'You should probably get out of here. '),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 81, 'otherescort_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 82, 'otherescort_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 83, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 84, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 85, 'player_1_3', 'Yes'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 86, 'player_1_4', 'Yes'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 87, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 88, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 89, 'player_2_3', 'No'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 90, 'player_2_4', 'No'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 91, 'player_3_1', 'You want me to kill the tusk-cat?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 92, 'player_3_2', 'Why would someone from Narmle steal your holo?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 93, 'player_3_3', 'Wouldn''t a smuggler have taken it offworld by now?'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 94, 'player_3_4', 'Why aren''t these people trying to kill me? I''m the one that killed their friend.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 95, 'player_4_1', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 96, 'player_4_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 97, 'player_4_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 98, 'player_4_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 99, 'player_5_1', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 100, 'player_5_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 101, 'player_5_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 102, 'player_5_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 103, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 104, 'player_more_1_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 105, 'player_more_1_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 106, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 107, 'player_more_2_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 108, 'player_more_2_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 109, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 110, 'player_more_3_3', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 111, 'player_more_3_4', ''),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 112, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 113, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 114, 'return_waypoint_description_2', 'Escort the thief back to Draya Korbinari'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 115, 'return_waypoint_description_3', 'Return the holo to Draya Korbinari.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 116, 'return_waypoint_description_4', 'Return to Draya Korbinari and inform her of your success'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 117, 'return_waypoint_name_2', 'Draya Korbinari'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 118, 'return_waypoint_name_3', 'Draya Korbinari'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 119, 'return_waypoint_name_4', 'Draya Korbinari'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 120, 'waypoint_description_2', 'Go and arrest the thief who stole the holo'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 121, 'waypoint_description_3', 'Go find the smuggler and retrieve the missing art holo.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 122, 'waypoint_description_4', 'Go stop the bounty hunter'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 123, 'waypoint_name_2', 'Thief''s location'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 124, 'waypoint_name_3', 'Smuggler''s location'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 125, 'waypoint_name_4', 'The bounty hunter''s location'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 126, 'npc_reset_2', 'If you''re not up to doing this right now come back later.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 127, 'npc_reset_3', 'If you''re not up to doing this right now come back later.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 129, 'npc_reset_4', 'If you''re not up to doing this right now come back later.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 130, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 131, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 132, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 133, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 134, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 135, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_draya_korbinari.stf', 136, 'notyet', 'Not right now, I''m busy.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 1, 'cant_work', 'You seem very busy at the moment. Why don''t you finish your current task and come speak to me later?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 2, 'dontknowyou_1', 'I''m quite busy at the moment. Please go away.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 4, 'dontknowyou_3', 'I''m quite busy and cannot chat.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 5, 'gotowork_1', 'Is this about that blasted Arts Gala? Or is it the Jubilee? I can never get them straight. I suppose you have an invitation for me?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 8, 'next', 'There''s nothing else I require of you at the moment. But please check back with me from time to time.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 9, 'notit_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 10, 'notit_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 11, 'notit_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 12, 'notyet', 'I don''t think I need anyone right now.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 13, 'npc_1_1', 'Welcome to Restuss. If you''re a patron of the arts, I think you''ll find your stay here is a pleasant one. People of "breeding" are drawn to our city. It probably has to do with the Restuss Arts Jubilee. It''s the oldest arts festival on Rori, you know, and takes a great deal of preparation. Would you care to help?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 14, 'npc_1_2', 'Good news! The maestro just contacted us and has agreed to attend the Arts Jubilee! However, there is a slight complication. His favorite riding gualama has escaped from its stable and the maestro wants it returned safely. Do you think you could do that?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 15, 'npc_1_3', 'Forgive me if I''ve come to rely on your skills, but your effectiveness in missions past has left me no choice. The citizens of Restuss must once again call upon you to assist our Arts Jubilee. We need you to escort a wealthy patron of the festival back to our fair city. Can we count on you?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 16, 'npc_2_1', 'Excellent. Please deliver this invitation into the hands of the maestro himself. I want him to know it comes directly from me.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 17, 'npc_2_2', 'Excellent! Your dedication to our celebration is most impressive. We''ve used tracker droids to locate the gualama but they also picked up some predators nearby. Please hurry and make sure the maestro gets his prized steed back alive.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 18, 'npc_2_3', 'You never disappoint, kind friend! Here are the coordinates where you''ll find this patron - she''s a bit of a naturalist and enjoys spending time absorbing the beauty of nature.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 19, 'npc_3_1', 'Ah, I see. Well, enjoy your stay. I hope that you leave our fair city a bit more cultured than when you entered it. Good day.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 20, 'npc_3_2', 'I suppose I''ll have to find someone else to retrieve the maestro''s noble steed. Farewell.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 21, 'npc_3_3', 'I suppose I could send one of our security people. You would have been much more colorful and entertaining, though. Ah well.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 22, 'npc_4_1', 'For years we''ve been courting an artist of some renown to attend our Arts Jubilee, but so far have been unsuccessful. This year I''ve had a special invitation made especially for the maestro and need it hand-delivered. Could you do that?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 23, 'npc_4_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 24, 'npc_4_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 31, 'npc_backtowork_1', 'I''ve explained everything I can about this assignment. What else do you require?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 32, 'npc_backtowork_2', 'You seem uncertain. If you prefer to pass on this assignment, I''ll understand.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 33, 'npc_backtowork_3', 'You''ve been most helpful up to this point. If you''d like to decline this assignment, I''ll understand.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 34, 'npc_breech_1', 'Can I help you? Are you looking for someone in particular?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 35, 'npc_breech_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 36, 'npc_breech_3', 'Yoo-hoo! Over here! Are you my escort? I certainly hope so!'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 39, 'npc_dropoff_3', 'You were a most gallant and brave companion. I thank you ever so much for the opportunity to witness an exciting blaster fight.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 40, 'npc_failure_1', 'Another year without the maestro''s presence. Alas, our Arts Jubilee will not be perfect.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 41, 'npc_failure_2', 'This is most depressing. The maestro will never attend our Arts Jubilee now. We''ll have to find another way to best those louts in Narmle.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 42, 'npc_failure_3', 'This is most disappointing. I''ll need to send out a few more exclusive invitations to other wealthy citizens to make up for the lack of funds.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 43, 'npc_more_1_1', 'Because I have no desire to subject myself to a horde of poseurs and hobbyists who praise a tiresome has-been like Sidoras Bey for his sycophantic attempts to curry favor with the Emperor.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 45, 'npc_more_1_3', 'Isn''t it obvious? Because I''m fabulously wealthy! Why bandits would make a fortune by ransoming me.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 48, 'npc_more_2_3', 'Well you must admit being kidnapped by handsome and daring rogues is not without its pedestrian charms. If you''ve never been kidnapped, you simply must give it a try sometime.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 52, 'npc_noloc_1', 'I need to verify the maestro''s coordinates with my people. Could you check back with me in a bit?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 53, 'npc_noloc_2', 'Give me a few moments to verify the gualama''s coordinates.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 54, 'npc_noloc_3', 'If you could wait a few moments, I need to verify our patron''s coordinates.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 55, 'npc_reset_1', 'My assignments are perhaps not for everyone. Come back if you change your mind.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 56, 'npc_reward_1', 'Well done. I do hope the maestro decides to attend. '),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 57, 'npc_reward_2', 'You''ve come through for the people of Restuss again, friend. On behalf of the citizens of our fair city, I thank you.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 58, 'npc_reward_3', 'Very well done! I shall add your name to the list of valuable patrons who helped make this year''s Arts Jubilee a smashing success.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 59, 'npc_smuggle_1', 'Not another damn invitation to the Arts Jubilee. I''ll look this over and think about it. But tell Zindalai not to get his hopes up.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 64, 'npc_takeme_3', 'I''m so glad you arrived when you did. I fear there are some bandits on our trail. We should be cautious.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 65, 'npc_work_1', 'Did you deliver that invitation yet? Our Arts Jubilee would be an even greater success if the maestro were to attend.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 66, 'npc_work_2', 'Have you returned the maestro''s steed to him? If he loses that beast, he''ll never attend our Arts Jubilee.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 67, 'npc_work_3', 'Have you escorted our patron back here safely? We need her generous contribution to assure our festival is a success.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 70, 'otherescort_3', 'I don''t believe I''m the individual you''re seeking.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 77, 'player_3_1', 'What exactly would I have to do?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 78, 'player_3_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 79, 'player_3_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 80, 'player_4_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 81, 'player_4_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 82, 'player_4_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 83, 'player_5_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 84, 'player_5_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 85, 'player_5_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 86, 'player_more_1_1', 'Why don''t you want to attend the Arts Jubilee?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 88, 'player_more_1_3', 'Why are bandits after you?'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 91, 'player_more_2_3', 'Forgive me, but you almost sound excited by the prospect.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 97, 'return_waypoint_description_1', 'Report your success to Hefsen Zindalai.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 98, 'return_waypoint_description_2', 'Escort the gualama back to Hefsen Zindalai.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 99, 'return_waypoint_description_3', 'Escort the wealthy patron back to Hefsen Zindalai.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 100, 'return_waypoint_name_1', 'Chief Administrator Zindalai''s Location'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 101, 'return_waypoint_name_2', 'Chief Administrator Zindalai''s Location'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 102, 'return_waypoint_name_3', 'Chief Administrator Zindalai''s Location'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 103, 'waypoint_description_1', 'Deliver an invitation to the Restuss Arts Jubilee.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 104, 'waypoint_description_2', 'Find the runaway gualama before it''s eaten by predators.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 105, 'waypoint_description_3', 'Find the wealthy patron of the Restuss Arts Jubilee.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 106, 'waypoint_name_1', 'The Maestro''s Location'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 107, 'waypoint_name_2', 'The Runaway Gualama''s Location'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 108, 'waypoint_name_3', 'Wealthy Patron''s Location'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 109, 'npc_reset_2', 'My assignments are perhaps not for everyone. Come back if you change your mind.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 110, 'npc_reset_3', 'My assignments are perhaps not for everyone. Come back if you change your mind.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 111, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 112, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 113, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_hefsen_zindalai.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 1, 'cant_work', 'When you aren''t so busy, you might check with me for a job.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 6, 'next', 'I''ve received no more reports of exotic wildlife that requires control, so I''m returning to my research. Thanks for your help.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 7, 'notit_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 8, 'notit_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 9, 'notyet', 'I think I''d like to be alone with my thoughts for a while.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 10, 'npc_1_1', 'Hello. I am a zoologist studying the local wildlife -- and, unfortunately, some nonlocal wildlife. A misguided researcher imported Corellian gubburs to Rori for study. They got loose and are now breeding. Will you help me control the population by disposing of one?'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 11, 'npc_1_2', 'Welcome back! I have another report of a non-native animal endangering the Rori ecosystem. It''s a Talusian guf drolg, quite harmful to the ecology.  I''m hoping you can go take care of it for me.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 12, 'npc_2_1', 'I appreciate your help -- and I''ll make it worth your while when you return here afterward.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 13, 'npc_2_2', 'Good. The guf drolg is eating so many other creatures, it''s disrupting the local ecosystem. The faster you work, the better.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 14, 'npc_3_1', 'Very well, sorry to bother you.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 15, 'npc_3_2', 'I''m sorry. That creature is doing substantial damage to the local ecosystem.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 16, 'npc_4_1', 'It''s an amphibious reptavian, squat and lazy. They capture small insects with a long tongue. They hop, which makes them difficult to target.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 17, 'npc_4_2', 'A guf drolg is a large amphibious sauroid native to Talus. It is omnivorous, ill-tempered, and generally hostile. You may need help killing the specimen.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 18, 'npc_5_1', 'Gubburs have three long whiskers they use to identify changes in weather and tectonic motion. The researcher apparently wanted to see if these creatures could predict earthquakes here. I never heard the results of the research.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 20, 'npc_6_1', 'Gubburs are notorious for their terrible smell. They smell like burning leather, which repels most native predators. One more good reason to destroy them on Rori. Will you help?'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 22, 'npc_backtowork_1', 'I don''t know what else to tell you. Please find a gubbur, preferably of breeding age, and kill it.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 23, 'npc_backtowork_2', 'I don''t know what else to tell you. I''d help you destroy the guf drolg, but unfortunately I''m currently occupied with my work.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 24, 'npc_breech_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 25, 'npc_breech_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 28, 'npc_failure_1', 'You didn''t destroy that Corellian gubbur? I wouldn''t have thought that a steep challenge.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 29, 'npc_failure_2', 'Did you not destroy that guf drolg? Well, I can hardly blame you -- they''re fierce.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 36, 'npc_noloc_1', 'Excuse me, I have to take a call from my research group leader. Please talk to me again in a moment.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 37, 'npc_noloc_2', 'Excuse me, I have to take an important call from my research project director. Talk to me again shortly, please.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 38, 'npc_reset_1', 'I understand. Tromping around the wilderness to stomp a gubbur is not my idea of a fun time either.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 39, 'npc_reward_1', 'Thank you for your help in controlling the gubbur threat to Rori''s sensitive ecosystem. There is more work of this kind, unfortunately, so talk to me again soon.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 40, 'npc_reward_2', 'Thank you for disposing of that guf drolg. Thank goodness there was only one of them.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 45, 'npc_work_1', 'I hope that Corellian gubbur isn''t too much of a challenge for you.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 46, 'npc_work_2', 'I hope you''re preparing to destroy that Talusian guf drolg. You may need a bit of help, but I''m afraid I''m currently occupied.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 53, 'player_3_1', 'What is a gubbur?'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 54, 'player_3_2', 'What is a guf drolg?'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 55, 'player_4_1', 'Why did the researcher import Corellian gubburs to Rori?'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 56, 'player_4_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 57, 'player_5_1', 'Why don''t local predators eat the gubburs?'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 58, 'player_5_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 67, 'return_waypoint_description_1', 'This Mon Calamari zoologist will reward you for destroying a non-native Corellian gubbur.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 68, 'return_waypoint_description_2', 'This Mon Calamari zoologist will reward you for having destroyed the Talusian guf drolg.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 69, 'return_waypoint_name_1', 'Magur Torigai'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 70, 'return_waypoint_name_2', 'Magur Torigai'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 71, 'waypoint_description_1', 'Zoologist Magur Torigai would like this non-native amphibian destroyed before it damages the Rori ecosystem.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 72, 'waypoint_description_2', 'Zoologist Magur Torigai would like this Talusian creature destroyed before it damages the Rori ecosystem.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 73, 'waypoint_name_1', 'Corellian Gubbur'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 74, 'waypoint_name_2', 'Guf Drolg'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 75, 'npc_reset_2', 'I understand. Maybe you''ll change your mind later.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_magur_torigai.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 1, 'cant_work', 'I don''t wish to interrupt your current assignment, friend. Come back when your time is your own again.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 2, 'dontknowyou_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 3, 'dontknowyou_2', 'I''m a bit busy at the moment. Can''t chat, sorry.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 6, 'next', 'You''ve been a great help, but I think I have things under control now. Enjoy your stay in Restuss.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 7, 'notit_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 8, 'notit_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 9, 'notyet', 'I''m a bit busy at the moment...'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 10, 'npc_1_1', 'How do, stranger? I''m Lord Sloan Rusper. Maybe you''ve heard of me? Great Naboo hunter? Well, doesn''t matter. What I need is someone with a stout heart and a love of danger. Does that describe you? Feel like doing a bit of hunting? I''ve been given the task by His Honor, Hefsen Zindalai, to make sure this area is safe for the Arts Jubilee. Never understood all the hullabaloo about that festival, but that''s neither here nor there. Care to join the ranks of the hunting elite? '),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 11, 'npc_1_2', 'I''m in need of your services yet again, my brave friend. One of my hunters has gotten himself into a bit of a pickle, I''m afraid. While exploring what he thought was an abandoned tusk-cat den, he uncovered a nest of nightspiders. Fortunately, he was able to send a final distress call before communications were cut off. Can you help save the poor lad? '),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 12, 'npc_2_1', 'By the Force, that''s the spirit! I''ll give you the coordinates of the last attack. It seems this creature tends to hunt in a small area. Have your weapon handy! Best of luck!'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 13, 'npc_2_2', 'I was hoping I could rely upon you. It does this old man''s heart proud to know he still has the eye for spotting a true hunter. Best of luck!'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 14, 'npc_3_1', 'That''s a shame. You have the appearance of someone who would laugh in the face of danger, and I''m seldom wrong about these things. I must be getting old.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 15, 'npc_3_2', 'Some people just don''t have the heart of a hunter, I suppose. Ah well, sorry I bothered you.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 16, 'npc_4_1', 'Not sure, exactly. It seems something in the water is turning the predators of Rori into marauding beasts. Not that they weren''t dangerous before, mind you, but this affliction turns them into nightmarish killers. And you''d be going after one of the worst in recent months. Care to tackle this monster? '),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 17, 'npc_4_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 22, 'npc_backtowork_1', 'You seem hesitant, friend. Do you wish to reconsider?'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 23, 'npc_backtowork_2', 'Nightspiders creep me out too, friend. I understand if you wish to back out.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 24, 'npc_breech_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 25, 'npc_breech_2', 'Hey! Over here! Help me get rid of these spiders!'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 27, 'npc_dropoff_2', 'Thanks, friend. You''re one tough hunter. Can''t wait to tell my friends about this.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 28, 'npc_failure_1', 'There''s no telling how these sorts of things will turn out, especially when wild beasts are involved. Better luck next time.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 29, 'npc_failure_2', 'Poor boy, he was in the prime of his life. Ah well, he knew the risks of being a hunter.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 36, 'npc_noloc_1', 'A moment, I think we''ve just had a new sighting. I''ll get those new coordinates shortly.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 37, 'npc_noloc_2', 'Let me verify that lad''s coordinates. Could you check back with me in a few moments?'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 38, 'npc_reset_1', 'A shame you couldn''t see this through. No matter. Come back if you have a change of heart.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 39, 'npc_reward_1', 'Bully job, friend! I knew I had you pegged for the adventurous sort. Here''s something for your trouble.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 40, 'npc_reward_2', 'Stellar job, friend, simply stellar! You have a knack for this sort of work, you know. I do hope you''ll continue to pursue a hunter''s life.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 44, 'npc_takeme_2', 'It''s a good thing you showed when you did. I thought I was going to be feeding the next generation of nightspiders for sure. Let''s get out of here.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 45, 'npc_work_1', 'Have you taken care of that slavering beast yet? We can''t have our local artists being gobbled up by monsters, now can we?'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 46, 'npc_work_2', 'Have you saved that poor lad from the nightspiders yet? He may not be the best hunter, but he''s got a good heart. Please hurry!'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 48, 'otherescort_2', 'I don''t think I''m the guy you''re looking for. Sorry.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 53, 'player_3_1', 'What would I have to hunt?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 54, 'player_3_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 55, 'player_4_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 56, 'player_4_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 57, 'player_5_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 58, 'player_5_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 67, 'return_waypoint_description_1', 'Bring news of the beast''s demise back to Lord Rusper.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 68, 'return_waypoint_description_2', 'Escort the young hunter safely back to Lord Rusper.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 69, 'return_waypoint_name_1', 'Lord Rusper''s Location'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 70, 'return_waypoint_name_2', 'Lord Rusper''s Location'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 71, 'waypoint_description_1', 'The location of the beast''s last attack.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 72, 'waypoint_description_2', 'Save the young hunter from the ravenous nightspiders.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 73, 'waypoint_name_1', 'Last Attack Location'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 74, 'waypoint_name_2', 'Young Hunter''s Location'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 75, 'npc_reset_2', 'A shame you couldn''t see this through. No matter. Come back if you have a change of heart.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/rori/rori_restuss_sloan_rusper.stf', 77, 'player_sorry_2', 'I''ll get back to work.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 1, 'cant_work', 'I greet you as Drall''s ambassador to Talus. I seek help with a task when you are less busy.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 2, 'dontknowyou_1', 'I''m sorry, you have the wrong person.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 3, 'dontknowyou_2', 'Sorry, you have the wrong person.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 5, 'gotowork_2', 'From the ambassador''s message, I expected you''d have a recording called "Flowers of Drall." Do you?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 6, 'next', 'I have no further tasks that require assistance at this time. I thank you again for your earlier help.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 7, 'notit_1', 'I hoped to get a specimen of the Twin-Scented Natterbloom herb. This is not it.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 8, 'notit_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 9, 'notyet', 'I can''t speak with you at the moment.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 10, 'npc_1_1', 'I greet you as Drall''s ambassador to Talus. I seek help in securing a Talusian native herb that shows promise in curing Drall sickness. The local Dearic Garden Club has kindly located a specimen. Would you please bring it here?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 11, 'npc_1_2', 'I thank you again for your help in securing that medicinal herb. I have prepared a token of thanks for the Dearic Garden Club, which secured the herb. Would you please deliver this recording to the club chairperson?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 12, 'npc_2_1', 'I thank you for your attention. The representative of the Dearic Garden Club has just called from the wilderness, where the specimen is located. Here are the coordinates. Good luck.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 13, 'npc_2_2', 'I am heartened to hear your assent. Here is the recording. The chairperson is currently in the wilderness studying the local flora.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 14, 'npc_3_1', 'I understand. I wish you well.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 15, 'npc_3_2', 'I understand. I wish you well.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 16, 'npc_4_1', 'An ancient disease called the Balding Sickness afflicts some young Drall, causing them to lose their fur and sometimes their lives. Certain of these victims resist bacta treatment, so we seek alternate solutions. This herb may prove a great benefit. Will you bring it here?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 17, 'npc_4_2', 'It is a lovely anthem called "Flowers of Drall," sung by young students at the Boiling Sea Music Academy on Drall. It is merely a small gesture of gratitude. Would you deliver the recording, please?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 22, 'npc_backtowork_1', 'I hope you will soon pick up the medicinal herb from the Dearic Garden Club representative.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 23, 'npc_backtowork_2', 'I hope you will soon deliver that recording of "Flowers of Drall" to the Garden Club chairperson.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 24, 'npc_breech_1', 'Are you here to pick up the medicinal herb for the Drall ambassador?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 25, 'npc_breech_2', 'Did the Drall ambassador send you here?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 28, 'npc_failure_1', 'I regret that you could not obtain the herb. I hope you did not find the task too stressful.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 29, 'npc_failure_2', 'I am sorry you could not deliver the recording. Do not worry -- I shall find another way to deliver it.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 30, 'npc_more_1_1', 'The herb smells sharp while it''s growing, then puts forth a beautiful small flower with a sweet citrus scent. It''s reputed to have many medicinal uses. I hope it works on the Drall children.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 31, 'npc_more_1_2', 'I''m collecting specimens of the white-leaf and blue-leaf varieties of Unbuttoned Gobnettle. I haven''t found any yet, but I can smell them. The suspense is killing me!'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 36, 'npc_noloc_1', 'I await contact from the Garden Club representative as to the coordinates of the specimen they located. Please contact me again in a few moments.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 37, 'npc_noloc_2', 'I need only contact the Garden Club chair to arrange a rendezvous point. Please contact me again in a few moments.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 38, 'npc_reset_1', 'I understand. Please contact me again when you feel ready for the task.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 39, 'npc_reward_1', 'I thank you for your effort to help my people. Please contact me again as your schedule permits.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 40, 'npc_reward_2', 'I am most gladdened to hear that you delivered that recording. Please accept this payment with the thanks of the people of Drall.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 41, 'npc_smuggle_1', 'Here it is -- a sample of Twin-Scented Natterbloom. Please be careful when you take it back -- it''s scarce.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 42, 'npc_smuggle_2', 'What a nice gesture. I''ll be sure to play this anthem at our next Garden Club meeting.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 45, 'npc_work_1', 'I hope you will soon pick up the medicinal herb from the Dearic Garden Club representative.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 46, 'npc_work_2', 'I hope you will soon deliver that recording of "Flowers of Drall" to the Garden Club chairperson.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 53, 'player_3_1', 'What sickness could this herb cure?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 54, 'player_3_2', 'What is the recording?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 55, 'player_4_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 57, 'player_5_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 59, 'player_more_1_1', 'Why is it called "Twin-Scented"?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 60, 'player_more_1_2', 'Why are you out here in the wilderness?'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 67, 'return_waypoint_description_1', 'The Drall ambassador to Talus is waiting in Dearic for a sample of Twin-Scented Natterbloom, a Talusian medicinal herb.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 68, 'return_waypoint_description_2', 'Drall''s ambassador to Talus waits to give payment for delivery of the recording "Flowers of Drall" to the chairperson of the Dearic Garden Club.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 69, 'return_waypoint_name_1', 'Champhra Biahin'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 70, 'return_waypoint_name_2', 'Champhra Biahin'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 71, 'waypoint_description_1', 'Here the Dearic Garden Club located a specimen of a Talusian herb that may prove useful to the Drall ambassador to Talus, Champhra Biahin.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 72, 'waypoint_description_2', 'The chairperson of the Dearic Garden Club, who awaits a recording called "Flowers of Drall" given as a thank-you gift by the Drall ambassador to Talus, Champhra Biahin.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 73, 'waypoint_name_1', 'Medicinal Herbs'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 74, 'waypoint_name_2', 'Garden Club Chair'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 75, 'npc_reset_2', 'I understand. Please contact me again when you feel ready for the task.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_champhra_biahin.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 1, 'cant_work', 'Your current job may conflict with my interests. Come back and see me once you''re finished with your current employer. '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 2, 'dontknowyou_1', 'I''m just waiting to meet somebody. You can be on your way.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 3, 'dontknowyou_2', 'I''m waiting for someone to meet me and then I''ll be on my way.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 4, 'dontknowyou_3', 'I bet you wish you had a CorSec escort to get you around safely.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 5, 'dontknowyou_4', 'Would you mind moving on? I don''t want to attract any attention.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 6, 'gotowork_1', 'You were supposed to be bringing me some kind of message. What did you do with it?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 10, 'next', 'I haven''t forgotten about you but I''m in the middle of some very delicate negotiations right now. Check back with me from time to time. You never know when new work will come up.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 11, 'notit_1', 'What are you giving me? I can''t use this.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 12, 'notit_2', 'I''m fairly certain you meant to give me something else. Why don''t you look again?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 13, 'notit_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 14, 'notit_4', 'I''m sorry, I don''t have time to speak right now.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 15, 'notyet', 'I''m a very busy man. Go make an appointment with my Minister of Protocol Haleen Snowline.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 16, 'npc_1_1', 'I really need to get better security. They let anyone in here and they don''t even screen for weapons. Well, I suppose if Haleen let you through you''re probably all right. Since you''re here perhaps I can make some use of you. If you''re in need of a job, I could use someone to drop off a message for me. Interested?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 17, 'npc_1_2', 'Back again, are you? I really do need to get my door fixed. No, no, not for you but for other people who barge into my office. Come to think of it, I do actually need someone to pick up a package from a Corporate Sector Authority messenger. Interested?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 18, 'npc_1_3', 'If I look a bit startled it''s because I''m shocked to discover that one of my staff has run off after embezzling countless credits from the public trust. I am sorely disappointed that one of my most trusted employees would betray the public this way. Perhaps this situation can be salvaged. Would you be willing to track down my wayward employee? '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 19, 'npc_1_4', 'I''m very glad you''re here. That embezzlement scheme was just the beginning. One of my aides has run off and is blackmailing me for hush money. I need you to take care of this for me. Will you help me?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 20, 'npc_2_1', 'I want you to bring this message to a courier waiting outside of the city. He''ll take it from there. It may seem vague, but the less you know about this the better.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 21, 'npc_2_2', 'Good. I need someone to go and meet the CSA courier and pick up whatever forms and such they''re sending over. This whole sending couriers to meet couriers idea seems a little expensive to me but they say it helps cut costs.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 22, 'npc_2_3', 'Apparently there were a few accomplices involved dressed as CorSec officers. Don''t be fooled by any of that nonsense, just bring that blasted thief back to me!'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 23, 'npc_2_4', 'Excellent. Liquidating that traitorous aide of mine should serve as a wonderful example to the rest of my staff. And don''t you worry - I''ll handle all the paperwork that will make your act nice and legal.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 24, 'npc_3_1', 'Suit yourself. Enjoy your stay on Talus.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 25, 'npc_3_2', 'I see. Perhaps you should be on your way then.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 26, 'npc_3_3', 'A day for betrayals. How much did they cut you in for? '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 27, 'npc_3_4', 'After all I''ve done for you. Ingrate!'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 28, 'npc_4_1', 'I have a business contact that was once an important Imperial figure. He likes to keep up with projects that he''s no longer cleared for, so I help him out sometimes. For political reasons, it wouldn''t be a good idea for me to be seen with him. You''ll be taking a message to his courier.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 29, 'npc_4_2', 'The usual sort of trade documents and red tape that keep things moving through the sector. Nothing terribly interesting. So will you go get it?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 30, 'npc_4_3', 'Alive of course! I''m shocked that you would even ask. How else can I find out what happened to the money?  So will you help me or not?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 31, 'npc_4_4', 'I can''t give in to blackmail. If I do it even once, I open myself up to no end of trouble. There is only one way to reward betrayal. I think you know what that is. Will you do it or not? '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 40, 'npc_backtowork_1', 'What is it now? I thought you were going to make a delivery for me.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 41, 'npc_backtowork_2', 'Were you going to keep pestering me or were you going to pick up my package?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 42, 'npc_backtowork_3', 'Were you going to do this job or are you planning to desert me?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 43, 'npc_backtowork_4', 'You know what you need to know to do the job. What''s it going to be?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 44, 'npc_breech_1', 'Do you have something for me?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 45, 'npc_breech_2', 'Are you the courier I was told to expect?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 46, 'npc_breech_3', 'Oh no! He sent you after me, didn''t he?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 47, 'npc_breech_4', 'You''re not bringing me back!'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 48, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 49, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 50, 'npc_dropoff_3', 'Don''t you realize what you''re doing? He''s going to steal these credits himself!'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 52, 'npc_failure_1', 'I can tell this isn''t going to be good news.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 53, 'npc_failure_2', 'What a sorry state of affairs. Perhaps I can get them to send over another courier.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 54, 'npc_failure_3', 'This is not going to look good. I need to find a way to trace those credits or this scandal will follow me for years.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 55, 'npc_failure_4', 'How could you botch this? That blackmailer has got to be stopped somehow. '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 68, 'npc_noloc_1', 'Come back in a few minutes. I need to call my contact and find out where he wants you to meet his courier. '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 69, 'npc_noloc_2', 'I''ll need to see where the meeting point is. Can you come back in a little while?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 70, 'npc_noloc_3', 'Conveniently for you, I implant all of my employees with a tracing device without their knowledge. If you''ll come back in a few minutes I should be able to tell you exactly where to go.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 71, 'npc_noloc_4', 'Come back in a few minutes. I should be able to have someone trace the caller location. '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 72, 'npc_reset_1', 'Come back later if you want to take care of this business for me.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 73, 'npc_reward_1', 'It was a fairly simple task but I''ve had my share of people who can''t even handle that. Good work. '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 74, 'npc_reward_2', 'Thank you very much. It''s so nice to have some reliable help for a change.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 75, 'npc_reward_3', 'What a load of nonsense she spouts. Now I should be able to track down what happened to all those lovely credits.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 76, 'npc_reward_4', 'You''ve been a big help to the administration and I won''t forget it. You should probably lay low for a while and not contact me. We''ll talk again later when things are less frenzied.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 77, 'npc_smuggle_1', 'That''s all I need. Thanks.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 78, 'npc_smuggle_2', 'Finally. Now I can head back for a little relaxation at the club.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 81, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 82, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 83, 'npc_takeme_3', 'Don''t you understand? He''s the biggest thief on Talus! You''ve got to believe me!'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 85, 'npc_work_1', 'Shouldn''t you be off delivering my message?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 86, 'npc_work_2', 'I''m still waiting on that package. Were you going to get around to that soon?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 87, 'npc_work_3', 'You are going to take care of this soon aren''t you? Every moment we waste makes those credits slip further from our grasp.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 88, 'npc_work_4', 'There''s a certain urgency to this task. If that information goes public, it could be the end of my career. '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 89, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 90, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 91, 'otherescort_3', 'I bet you wish you had a CorSec escort to get you around safely.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 93, 'player_1_1', 'Yes'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 94, 'player_1_2', 'Yes'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 95, 'player_1_3', 'Yes'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 96, 'player_1_4', 'Yes'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 97, 'player_2_1', 'No'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 98, 'player_2_2', 'No'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 99, 'player_2_3', 'No'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 100, 'player_2_4', 'No'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 101, 'player_3_1', 'Who am I delivering this message to?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 102, 'player_3_2', 'What sort of package?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 103, 'player_3_3', 'Are you asking me to bring your ex-employee back alive or --? '),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 104, 'player_3_4', 'What do you want me to do?'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 105, 'player_4_1', ''),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 106, 'player_4_2', ''),
