('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 127, 'return_waypoint_description_1', 'Return to Hagrin Zeed.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 128, 'return_waypoint_description_2', 'Return to Hagrin Zeed with the datadisc.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 129, 'return_waypoint_description_3', 'Return to Hagrin Zeed with your prisoner.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 130, 'return_waypoint_description_4', 'Return to Hagrin Zeed and inform him of your success.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 131, 'return_waypoint_name_1', 'Hagrin Zeed'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 132, 'return_waypoint_name_2', 'Hagrin Zeed'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 133, 'return_waypoint_name_3', 'Hagrin Zeed'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 134, 'return_waypoint_name_4', 'Hagrin Zeed'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 135, 'waypoint_description_1', 'Bring the datadisc to the courier.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 136, 'waypoint_description_2', 'Go meet the courier and pick up the package.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 137, 'waypoint_description_3', 'Go arrest the employee who embezzled funds .'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 138, 'waypoint_description_4', 'Go kill the blackmailer who is plagueing Hagrin Zeed.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 139, 'waypoint_name_1', 'The courier''s location'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 140, 'waypoint_name_2', 'The courier''s location'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 141, 'waypoint_name_3', 'Embezzler''s location'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 142, 'waypoint_name_4', 'Blackmailer''s location'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 143, 'npc_reset_2', 'Come back later if you want to take care of this business for me.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 144, 'npc_reset_3', 'Come back later if you want to take care of this business for me.'),
('string/en/static_npc/talus/talus_dearic_hagrin_zeed.stf', 145, 'npc_reset_4', 'Come back later if you want to take care of this business for me.'),
