('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 67, 'return_waypoint_description_1', 'Return to Haleen Snowline.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 68, 'return_waypoint_description_2', 'Return to Haleen Snowline.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 69, 'return_waypoint_name_1', 'Haleen Snowline'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 70, 'return_waypoint_name_2', 'Haleen Snowline'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 71, 'waypoint_description_1', 'A representative of the Talus and Tralus Liberation Party awaits a contribution from Talusian Prime Minister Hagrin Zeed''s Minister of Protocol, Haleen Snowline.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 72, 'waypoint_description_2', 'According to Minister of Protocol Haleen Snowline, these representatives of the Talus and Tralus Liberation Party possess state secrets that must be retrieved at any cost.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 73, 'waypoint_name_1', 'Liberation Party Rep'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 74, 'waypoint_name_2', 'Talus Liberation Terrorists'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 75, 'npc_reset_2', 'I understand perfectly, though I confess disappointment. I hope you''ll reconsider.'),
