('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 80, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 81, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 82, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_haleen_snowline.stf', 83, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 1, 'cant_work', 'When you are free from other duties, I would be pleased to make use of your services.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 2, 'dontknowyou_1', 'I fear nothing can come of our meeting at present. Perhaps we may meet again later.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 3, 'dontknowyou_2', 'Don''t worry about me. I''m not here to interfere with you.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 6, 'next', 'Many thanks, my very good friend, for all you have done for the Selonian people. For the moment, I have no needs that are not met.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 7, 'notit_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 8, 'notit_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 9, 'notyet', 'I can''t be bothered with this right now.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 10, 'npc_1_1', 'Perhaps you could be of some assistance to me. There is a group of humans that seems to hold my people in great disregard. I have endeavored to open a dialogue with them but they seem unwilling to do anything but threaten me. Now they have kidnapped my assistant. Will you help me?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 11, 'npc_1_2', 'You have done so much for me already and yet I find myself in need of your help once more. A friend of mine has informed me that an alien hate group has hired a bounty hunter to kidnap the Selonian ambassador. Since I am the Selonian ambassador, I find this news very disturbing. Will you help me?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 12, 'npc_2_1', 'You are most kind and gracious to help me. I do not know if humans hold my assistant or whether they have hired aliens to commit this crime. But I ask you to rescue my good friend and warren mate.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 13, 'npc_2_2', 'Hopefully you will be able to stop this bounty hunter. You are a valued friend to risk yourself for me. I wish there were more I could do for you. Good luck. '),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 14, 'npc_3_1', 'I am saddened you will not help, but I wish you well.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 15, 'npc_3_2', 'I have done you a great discourtesy by asking for that which you cannot freely give. I am truly sorry if I have offended you with my selfish request.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 16, 'npc_4_1', 'I don''t know. I have tried to understand this hatred for some time, but it still eludes me. Perhaps the failing is with me. However, that doesn''t matter right now. Will you please rescue my assistant?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 17, 'npc_4_2', 'I find your question disturbing on many levels and I have no answer for you. Will you help me?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 21, 'npc_6_2', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 22, 'npc_backtowork_1', 'Was there something further you wished to express to me?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 23, 'npc_backtowork_2', 'Perhaps I have asked too much of you. I would understand if you changed your mind.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 24, 'npc_breech_1', 'Have you come to torment me also?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 25, 'npc_breech_2', 'I''m here to do a job and I can''t let you stand in my way.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 26, 'npc_dropoff_1', 'I offer thanks to you for saving me. I would nuzzle you if it were not improper.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 28, 'npc_failure_1', 'Perhaps I expressed the risks to you poorly. For that I am sorry.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 29, 'npc_failure_2', 'I have put too great a burden upon you, my friend. I will accept my fate and trouble you no further. '),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 36, 'npc_noloc_1', 'Security is tracking her location and should have that information for me shortly. Would you give us a few minutes to prepare and then return?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 37, 'npc_noloc_2', 'I need a few minutes to perform the cleansing rituals of my people in case the worst occurs. Would you give me a few minutes to prepare before you leave?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 38, 'npc_reset_1', 'Perhaps my tasks will be more to your liking later. Come see me when you have found what you seek.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 39, 'npc_reward_1', 'I am very thankful to you for the service you have done.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 40, 'npc_reward_2', 'I salute both your strength and your kindness. Thank you.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 43, 'npc_takeme_1', 'You have come to save me? My thanks, gentle friend. I fear I misjudged you when I first saw you.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 45, 'npc_work_1', 'I do not wish to pressure you, but have you rescued my assistant yet? '),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 46, 'npc_work_2', 'Have you solved this problem yet? I strive to remain calm but I confess thoughts of this bounty hunter disturb my serenity. '),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 47, 'otherescort_1', 'I fear nothing can come of our meeting at present. Perhaps we may meet again later.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 49, 'player_1_1', 'Yes'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 50, 'player_1_2', 'Yes'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 51, 'player_2_1', 'No'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 52, 'player_2_2', 'No'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 53, 'player_3_1', 'Why do they hate you so much?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 54, 'player_3_2', 'Why would they kidnap you instead of just kill you?'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 55, 'player_4_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 57, 'player_5_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 66, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 67, 'return_waypoint_description_1', 'Escort the assistant back to the Selonian Ambassador.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 68, 'return_waypoint_description_2', 'Return to the Selonian Ambassador with the news of your success.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 69, 'return_waypoint_name_1', 'Kathikiis Ruwahurr'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 70, 'return_waypoint_name_2', 'Kathikiss Ruwahurr'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 71, 'waypoint_description_1', 'Rescue the Slonian Ambassador''s assistant.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 72, 'waypoint_description_2', 'Go stop the bounty hunter'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 73, 'waypoint_name_1', 'The Selonian''s location'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 74, 'waypoint_name_2', 'The bounty hunter''s location'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 75, 'npc_reset_2', 'Perhaps my tasks will be more to your liking later. Come see me when you have found what you seek.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 76, 'npc_reset_3', 'Perhaps my tasks will be more to your liking later. Come see me when you have found what you seek.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 77, 'player_sorry_1', 'I''ll get back to work.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 78, 'player_sorry_3', 'I''ll go work on this some more.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 79, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_kathikiis_ruwahurr.stf', 80, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 1, 'cant_work', 'I never trust anybody with my business when they''re working for someone else. Come see me about work another time.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 2, 'dontknowyou_1', 'This is private Hutt business. Beat it!'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 6, 'next', 'You''re a useful operative. When I''m in a better position to utilize your talents, I''ll find more work for you. Check back with me.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 7, 'notit_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 8, 'notit_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 9, 'notyet', 'Sorry, I can''t talk now.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 10, 'npc_1_1', 'The name is Draver. I represent the Corporate Sector Authority on Talus. I have a little unpleasant business with the Hutts that I need taken care of. I need the services of someone who is both capable and ruthless. Is that you?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 11, 'npc_1_2', 'I think we''ve made a reasonable impression on the Hutts, but I''m always of the mind that more is better. I think they need to better understand the financial costs associated with poor management. Are you going to help me teach them that lesson?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 12, 'npc_2_1', 'There is one Hutt employee I''m particularly keen to have eliminated. Any associates that are killed in the process would certainly cause me no distress. Come back and see me when you''ve completed the job.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 13, 'npc_2_2', 'The Hutts operate a glitterstim operation outside of the city. It''s not very large but they process an impressive amount of spice every month. I want you to go find that building and destroy it. Feel free to kill anyone working there. It will save me time later.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 14, 'npc_3_1', 'My time is valuable and you''re wasting it. Get out.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 15, 'npc_3_2', 'Do you think your cowardice is congenital or learned?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 16, 'npc_4_1', 'The Hutts recently killed one of my employees during a negotiation. I am the only one allowed to kill my employees with impunity. I''ve compiled a list of Hutt employees that I''ve slated for early retirement. Are you in?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 17, 'npc_4_2', 'By destroying something precious to them. What do you say?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 22, 'npc_backtowork_1', 'If you have something else to say, now''s the time.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 23, 'npc_backtowork_2', 'Make it quick. I''m very busy.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 24, 'npc_breech_1', 'You just made your last mistake!'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 25, 'npc_breech_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 28, 'npc_failure_1', 'I believe I cited both ruthless and capable in my job requirements. What use is ruthless all by itself?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 29, 'npc_failure_2', 'Failure is unacceptable. I want that building destroyed.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 36, 'npc_noloc_1', 'I''ve just had a wonderful thought. Give me a few minutes to see if the Hutts would be willing to offer me compensation for my employee. I like the idea of paying you with their money.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 37, 'npc_noloc_2', 'I''ll need to contact one of my underlings and get the location for you. Come back in a little while.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 38, 'npc_reset_1', 'I don''t really like unfinished business. If you decide you want to take care of this later, come see me.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 39, 'npc_reward_1', 'That''s a good start. Come see me later and we''ll see about teaching the Hutts further lessons in employee management.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 40, 'npc_reward_2', 'Excellent. Now would probably be a good time for you to lie low for a while. The Hutts are notoriously unforgiving in these matters.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 45, 'npc_work_1', 'Have you taken care of that little problem we spoke of? I''m not used to being kept waiting.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 46, 'npc_work_2', 'Have you destroyed that glitterstim refinery yet?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 49, 'player_1_1', 'Yes'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 50, 'player_1_2', 'Yes'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 51, 'player_2_1', 'No'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 52, 'player_2_2', 'No'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 53, 'player_3_1', 'What do you need done?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 54, 'player_3_2', 'How am I going to teach them that?'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 55, 'player_4_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 57, 'player_5_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 67, 'return_waypoint_description_1', 'Return to Mourno Draver and inform him that the mission has been completed'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 68, 'return_waypoint_description_2', 'Return to Mourno Draver and inform him of your success.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 69, 'return_waypoint_name_1', 'Mourno Draver'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 70, 'return_waypoint_name_2', 'Mourno Draver'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 71, 'waypoint_description_1', 'Go and kill the lieutenant in the Hutt organization'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 72, 'waypoint_description_2', 'Go destroy the glitterstim refinery'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 73, 'waypoint_name_1', 'Location of the Hutt lieutenant'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 74, 'waypoint_name_2', 'Location of the glitterstim refinery'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 75, 'npc_reset_2', 'I don''t really like unfinished business. If you decide you want to take care of this later, come see me.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_mourno_draver.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 1, 'cant_work', 'I''m a lady that demands exclusivity. Come see me when your schedule clears up a bit.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 2, 'dontknowyou_1', 'This is a CorSec matter. Move along.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 3, 'dontknowyou_2', 'I''m busy and can''t help you.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 4, 'dontknowyou_3', 'I''m busy, pal! Buzz off!'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 5, 'dontknowyou_4', 'Get lost. I''m busy.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 6, 'gotowork_1', 'I''m not sure what you expect me to do with this but I can assure you I don''t want it.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 10, 'next', 'You''ve performed like a true professional. I could ask for nothing more. Come back later, though, and I may have some more work.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 11, 'notit_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 12, 'notit_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 13, 'notit_3', 'This is not the ledger I asked you to bring me. I really need that ledger.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 14, 'notit_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 15, 'notyet', 'Sorry, I can''t talk now.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 16, 'npc_1_1', 'Greetings, stranger. Are you looking for work? There''s plenty of work around here for an enterprising and adventurous sort, such as you appear to be. But don''t worry - I like to take things slowly. This first assignment is a simple delivery, a message for a business associate of mine. Think you can handle that?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 17, 'npc_1_2', 'One of my devoted employees has run afoul of the law. It may have had something to do with that message you delivered to that CorSec captain. I need someone to save my devoted friend the trauma of an "interrogation" - few beings survive such an ordeal. Could you save him?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 18, 'npc_1_3', 'As you know, I am very protective of my devoted employees. What you may not know is that I am equally as proactive when it comes to removing traitorous employees. One of my formerly trusted accountants has decided to sell some of my books to the Hutts. This not only saddens me deeply, it calls for me to hire someone like you to get those records back and silence this traitor for good. Are you the agent I''m looking for?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 19, 'npc_1_4', 'Those Hutts, so incredibly predictable. I''ve just received word that they''ve hired an assassin to take me out. What they don''t realize is that I''ve done my homework and I happen to know that they intend to get rid of this assassin after he''s done his job - the Hutts hate loose ends. I need you to meet this assassin and say a simple phrase. This will convince him to join the winning side - mine. You''ll still have to deal with Hutt gangsters, however, but you''ve proven so good at that I have no doubt this will be a breeze for you. Will you do it?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 20, 'npc_2_1', 'Wonderful. Take this message to the CorSec captain at these coordinates. The contents of the message may come as a bit of a shock to him so pay no mind to anything he might say to you, especially threats. Report back to me when you''re done.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 21, 'npc_2_2', 'I was hoping I could count on you. My people are tracking the movements of the CorSec guards and will transmit the coordinates to you. Please hurry.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 22, 'npc_2_3', 'You make me weepy, you''re so good. Fortunately, I put a tracer on all my books so I am able to find them quickly should I need to. Make sure you get the ledger and leave no witnesses. I hate having to resort to this sort of thing but sometimes it''s necessary.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 23, 'npc_2_4', 'You are nothing if not a professional. Say the phrase to the assassin and take out his escort. If I played my cards right, the assassin will not interfere. Good luck.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 24, 'npc_3_1', 'This business is not for everyone. Enjoy your stay here.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 25, 'npc_3_2', 'I understand if you don''t wish to become involved in this matter. After all, one should never cross CorSec without a very good reason.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 26, 'npc_3_3', 'My assignments are getting a bit sticky, aren''t they? Your refusal does not hurt my feelings.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 27, 'npc_3_4', 'This is a tricky mission. Perhaps I should rely on a more experienced agent.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 28, 'npc_4_1', 'The kind that always gets a prompt response and gives the recipient little choice but to accept my generous proposal. Don''t you just love messages like that? So will you do it?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 29, 'npc_4_2', 'Not in this case, no. I have a feeling that the CorSec captain that ordered this "interrogation" will not want his superiors to become involved. This is a personal matter between him and I, you see.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 30, 'npc_4_3', 'They believe that someone like me is not capable of running the local Black Sun activities on this planet. It has to do with my past, which I won''t go into in detail, but suffice to say that not long ago I was traded among the Hutts like a piece of property. Times have changed and now I must do my best to re-educate them. Something that I enjoy immensely.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 31, 'npc_4_4', 'Jaggah Jonz never left Nal Hutta. You want to retire on the "Glorious Jewel?"'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 40, 'npc_backtowork_1', 'I know I''m very pleasant company but you should get going.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 41, 'npc_backtowork_2', 'No time to waste, dear friend. My employee''s life is at stake.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 42, 'npc_backtowork_3', 'There''s an accountant out there who desperately needs your attention.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 43, 'npc_backtowork_4', 'The more time you waste, the closer that assassin gets to me.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 44, 'npc_breech_1', 'What''s your business here? This is a CorSec investigation.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 45, 'npc_breech_2', 'But I didn''t do anything wrong! Why am I to be interrogated? I''m innocent!'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 46, 'npc_breech_3', 'I know Lady Slinthiss will send someone after me. It''s only a matter of time. Doesn''t that worry you people?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 47, 'npc_breech_4', 'You said that Lady Slinthiss would send someone and it seems you were right. I was hired to take out a Lady Vigo. This is your problem.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 48, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 49, 'npc_dropoff_2', 'I''m glad you decided to work for Lady Slinthiss. I would have been so much bantha fodder had that not been the case.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 50, 'npc_dropoff_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 51, 'npc_dropoff_4', 'I salute a fellow professional. Let''s hope we never find ourselves on opposite sides of a business transaction.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 52, 'npc_failure_1', 'I''m sure you tried your best, but failing to deliver a simple message does not bode well for your future.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 53, 'npc_failure_2', 'I lose more employees this way. Believe it when they say that good help is hard to find.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 54, 'npc_failure_3', 'Now I''ll have to set off the explosive charge in the tracer. It''ll take me months to collect all that data again. I hate these sorts of setbacks.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 55, 'npc_failure_4', 'Looks like I may have to disappear for a while, assuming I can''t find someone else to take care of this killer for me.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 57, 'npc_more_1_2', 'They wanted to squeeze me for information concerning Lady Slinthiss'' operations. But I wouldn''t have talked, I swear! She sent you to bring me back safely, right?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 58, 'npc_more_1_3', 'I didn''t! I swear! I was framed! By, by -- the Hutts! Yeah! That''s it! The Hutts framed me, those slimy slugs! They mind controlled me! Is any of this getting through?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 59, 'npc_more_1_4', 'Ah, now I understand. Okay, you''ve bought yourself a reprieve. Take me back to your boss. I think she and I have business to discuss.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 68, 'npc_noloc_1', 'Let me verify the captain''s coordinates with my people. Check with me in a few.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 69, 'npc_noloc_2', 'My people just need to verify those coordinates. Could you check back with me in a few moments?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 70, 'npc_noloc_3', 'One moment while my people verify the ledger''s location.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 71, 'npc_noloc_4', 'One moment while my people verify the assassin''s current coordinates.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 72, 'npc_reset_1', 'Oh, I know, I can be so demanding. Come back when you''re ready for such a bossy employer.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 73, 'npc_reward_1', 'Well done. I hope that mean old CorSec captain didn''t upset you too much. These sorts have a much more ferocious growl than they do bites. Those temperments suit these security roles, I suppose.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 74, 'npc_reward_2', 'You''ve brought my employee back safe and sound. Wonderful! Please have a drink on me.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 75, 'npc_reward_3', 'You put many of my other agents to shame. But they need that in order to strive for something better. You''re tops in my view.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 76, 'npc_reward_4', 'You are a businesswoman''s most valuable asset, do you know that? Take some time off, you Corellian sand panther, you''ve more than earned it.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 77, 'npc_smuggle_1', 'What''s this? A message from Nurla Slinthiss? It''s a holo recording of some sort -- Wait a second! Is this what I think it is? You tell that good-for-nothing gangster I won''t be blackmailed! You hear me! Now get out of here before I have you arrested!'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 81, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 82, 'npc_takeme_2', 'A thousand thanks, friend. Please take me back to Lady Slinthiss. More of those CorSec goons may show up at any minute.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 83, 'npc_takeme_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 84, 'npc_takeme_4', 'Not bad. Looks like I''ll have to deal with you myself. Ready?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 85, 'npc_work_1', 'Did you deliver that message for me? A business deal is dependent upon that delivery.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 86, 'npc_work_2', 'Have you rescued my employee from those CorSec goons? He''s ever so fragile.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 87, 'npc_work_3', 'Have you retrieved that ledger for me? My business will surely take a hit if that falls into the wrong hands.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 88, 'npc_work_4', 'Did you say that phrase to that assassin? My life could be in grave danger.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 89, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 90, 'otherescort_2', 'I''m not the fellow you''re looking for.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 91, 'otherescort_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 92, 'otherescort_4', 'Get lost. I''m busy.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 93, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 94, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 95, 'player_1_3', 'Yes.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 96, 'player_1_4', 'Yes.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 97, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 98, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 99, 'player_2_3', 'No.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 100, 'player_2_4', 'No.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 101, 'player_3_1', 'What kind of message is this?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 102, 'player_3_2', 'If I fight CorSec personnel to save your friend, won''t I be arrested?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 103, 'player_3_3', 'Why are the Hutts after your "books?"'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 104, 'player_3_4', 'What phrase do you want me to say?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 105, 'player_4_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 106, 'player_4_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 107, 'player_4_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 108, 'player_4_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 109, 'player_5_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 110, 'player_5_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 111, 'player_5_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 112, 'player_5_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 113, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 114, 'player_more_1_2', 'Why were you arrested?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 115, 'player_more_1_3', 'Why did you betray Lady Slinthiss?'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 116, 'player_more_1_4', 'Jaggah Jonz never left Nal Hutta. You want to retire on the "Glorious Jewel?"'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 117, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 118, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 119, 'player_more_2_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 120, 'player_more_2_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 121, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 122, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 123, 'player_more_3_3', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 124, 'player_more_3_4', ''),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 125, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 126, 'player_sorry_1', 'I''ll get back to work.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 127, 'return_waypoint_description_1', 'Report back to Nurla.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 128, 'return_waypoint_description_2', 'Escort the employee back to Lady Slinthiss.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 129, 'return_waypoint_description_3', 'Bring the ledger back to Lady Slinthiss.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 130, 'return_waypoint_description_4', 'Escort the assassin back to Lady Slinthiss.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 131, 'return_waypoint_name_1', 'Nurla Slinthiss'' Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 132, 'return_waypoint_name_2', 'Nurla Slinthiss'' Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 133, 'return_waypoint_name_3', 'Nurla Slinthiss'' Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 134, 'return_waypoint_name_4', 'Nurla Slinthiss'' Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 135, 'waypoint_description_1', 'Deliver a message to a CorSec captain.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 136, 'waypoint_description_2', 'Rescue Lady Slinthiss'' employee from the CorSec goons.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 137, 'waypoint_description_3', 'Get the ledger from the accountant.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 138, 'waypoint_description_4', 'Speak a phrase to an assassin.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 139, 'waypoint_name_1', 'CorSec Captain''s Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 140, 'waypoint_name_2', 'Devoted Employee''s Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 141, 'waypoint_name_3', 'Traitorous Accountant''s Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 142, 'waypoint_name_4', 'Assassin''s Location'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 143, 'npc_reset_2', 'Oh, I know, I can be so demanding. Come back when you''re ready for such a bossy employer.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 144, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_nurla_slinthiss.stf', 145, 'player_sorry_2', 'I''ll get back to work.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 1, 'cant_work', 'If you know how to keep your mouth shut and can take care of business, come see me when you need a job.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 2, 'dontknowyou_1', 'I''m waiting to meet up with somebody. Just go on about your business.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 3, 'dontknowyou_2', 'This has been a bit of a rough day. Would you mind leaving us in peace?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 4, 'dontknowyou_3', 'Unless you have a strong desire to have the Hutts chasing you all over the galaxy, you might just want to run along.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 8, 'next', 'I''ll keep an eye out for you the next time something comes up. Right now I don''t have any work for you. I love it when things are running smoothly.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 9, 'notit_1', 'I''m fairly certain this isn''t the item you were supposed to give me. Would you mind looking again?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 10, 'notit_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 11, 'notit_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 12, 'notyet', 'Don''t bother me right now, okay?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 13, 'npc_1_1', 'I hope you''re not the kind who likes to make trouble. I run a quiet town and as long as nothing interferes with business, I say, "live and let live." Now if you were looking for a little work on the side, I have a little package that needs picking up. How about it?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 14, 'npc_1_2', 'Normally the Hutts and I leave each other alone, but recently they''ve been trying to do business with the Corporate Sector Authority. I wouldn''t have any problem with that normally but they kidnapped the CSA rep they were dealing with. Do me a favor and get that CSA rep back safely. How about it?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 15, 'npc_1_3', 'The Hutts have got to pay for that kidnapping stunt. Nobody interferes with business in my town and gets away with it. The Hutt lieutenant who gave that order needs to vanish. Think you might want to handle the Job?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 16, 'npc_2_1', 'Glad to have you on board. The CSA is sending a courier. Pick up the package and bring it back to me. Simple right? Wrong. There''s always some goon trying to get in on the action, so keep your eyes open.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 17, 'npc_2_2', 'I''m not sure what sort of game these Hutts are playing, so shoot first and we won''t even bother asking questions. When it comes to choosing between the CSA and the Hutts, I know who''s good for business.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 18, 'npc_2_3', 'It should be pretty straightforward. I''ve already arranged the meeting so I''ll just give you the location and you can go kill that lieutenant and any goons who might be there. '),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 19, 'npc_3_1', 'I understand your refusal. See that you don''t interfere in the day-to-day business of the city while you''re here. '),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 20, 'npc_3_2', 'Don''t want to anger the Hutts, eh? You''re smarter than you look.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 21, 'npc_3_3', 'You didn''t strike me as the nervous type when I hired you. So much for first impressions.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 22, 'npc_4_1', 'The sort of package whose contents I don''t reveal to agents like you. You don''t want to ask too many questions around here. The answers will only get you into trouble. So will you do it or not?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 23, 'npc_4_2', 'Who knows? Maybe for not doing exactly what the Hutts wanted? It''s not as though the Hutts are known for their legendary desire to reach a compromise. So are you going to help out or not?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 24, 'npc_4_3', 'I''ll arrange for a meeting with the Hutt lieutenant to discuss reparations and then I''ll tell you where that meeting is. You go to said meeting place and create a large pile of ash where the Hutt lieutenant used to be. How about it?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 31, 'npc_backtowork_1', 'Were you going to just stand there or was there something else you wanted to say?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 32, 'npc_backtowork_2', 'Make it quick. What''s on your mind?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 33, 'npc_backtowork_3', 'Time to get to work -- unless you''ve changed your mind?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 34, 'npc_breech_1', 'You must be the new courier. '),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 35, 'npc_breech_2', 'Thank the Force! A friendly face.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 36, 'npc_breech_3', 'What''s this? A double-cross!'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 38, 'npc_dropoff_2', 'Thanks again. I think next time I''ll talk to the Hutts over a com-link.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 40, 'npc_failure_1', 'I told you to be careful out there.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 41, 'npc_failure_2', 'I need to get the CSA''s representative back to them in one piece or it''s going to interfere with business. This is not good.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 42, 'npc_failure_3', 'You look somewhat the worse for wear. Things didn''t go so well? I suppose I''ll have to find another way to impress the Hutts.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 52, 'npc_noloc_1', 'I''ll just contact the CSA and see when they were planning on sending their courier out. Come see me in a little while.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 53, 'npc_noloc_2', 'Come back in a few minutes, I need some time to contact the CSA and get any last minute instructions they may have. '),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 54, 'npc_noloc_3', 'I need to contact the Hutts. Give me a few minutes of privacy to arrange that meeting.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 55, 'npc_reset_1', 'Too much for you right now, eh? Come back when you want to finish the job.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 56, 'npc_reward_1', 'There''s nothing like the satisfaction of a job well done.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 57, 'npc_reward_2', 'CSA rep back in one piece and offending Hutt goons taken care of. Nice work!'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 58, 'npc_reward_3', 'Well done. That should keep the CSA happy and send a strong message to the Hutts at the same time.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 59, 'npc_smuggle_1', 'Tell Chief Mathiss that the CSA is very grateful for the speed with which he made that investigation shrivel up and go away.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 63, 'npc_takeme_2', 'I''m glad you got here when you did. Things were starting to look pretty grim.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 65, 'npc_work_1', 'Have you picked up my package yet?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 66, 'npc_work_2', 'You''d better go and get that CSA rep before those goons do any permanent damage.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 67, 'npc_work_3', 'Hurry up! You''re going to miss the meeting.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 69, 'otherescort_2', 'This has been a bit of a rough day. Would you mind leaving us in peace?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 71, 'player_1_1', 'Yes'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 72, 'player_1_2', 'Yes'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 73, 'player_1_3', 'Yes'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 74, 'player_2_1', 'No'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 75, 'player_2_2', 'No'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 76, 'player_2_3', 'No'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 77, 'player_3_1', 'What sort of package?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 78, 'player_3_2', 'Why would the Hutts want to kidnap a CSA rep?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 79, 'player_3_3', 'How do you want me to handle this?'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 80, 'player_4_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 81, 'player_4_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 82, 'player_4_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 83, 'player_5_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 84, 'player_5_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 85, 'player_5_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 97, 'return_waypoint_description_1', 'Return to Radlee Mathiss with the datadisc'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 98, 'return_waypoint_description_2', 'Return to Radlee Mathiss with the CSA representetive.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 99, 'return_waypoint_description_3', 'Return to Radlee Mathiss and inform him of your success.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 100, 'return_waypoint_name_1', 'Radlee Mathiss'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 101, 'return_waypoint_name_2', 'Radlee Mathiss'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 102, 'return_waypoint_name_3', 'Radlee Mathiss'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 103, 'waypoint_description_1', 'Go meet the courier and pick up the package'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 104, 'waypoint_description_2', 'Go rescue the CSA representetive.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 105, 'waypoint_description_3', 'Go kill the the Hutt lieutenant who ordered the kidnapping of the CSA representetive.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 106, 'waypoint_name_1', 'The courier''s location'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 107, 'waypoint_name_2', 'The location of the CSA representetive'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 108, 'waypoint_name_3', 'The location of the Hutt''s lieutenant'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 109, 'npc_reset_2', 'Too much for you right now, eh? Come back when you want to finish the job.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 110, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 111, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 112, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 113, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_dearic_radlee_mathiss.stf', 114, 'npc_reset_3', 'Too much for you right now, eh? Come back when you want to finish the job.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 1, 'cant_work', 'You come see me about some work when you have some time to kill.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 2, 'dontknowyou_1', 'What are you looking at me for? I''m not doing anything.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 3, 'dontknowyou_2', 'You should clear out of here friend. You never know when trouble may start.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 6, 'next', 'I have to cool it for a while an Imperial Inspector looks around. Maybe I''ll have something for you later.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 7, 'notit_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 8, 'notit_2', 'This isn''t a hyperdrive part. Come on pal, look again.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 9, 'notyet', 'I don''t need anything right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 10, 'npc_1_1', 'Are you here to pick up the AT-ST? No, wait -- that''s tomorrow. What do you need? I can get you anything you want: blasters, thermal detonators, anti-orbital ion cannons, you name it. You don''t look like you could scrape the creds together for that last one, though. But what I need is someone to do a pickup for me. Are you looking for work?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 11, 'npc_1_2', 'I love it when work and business come together in harmony. Through a smuggler intermediary I''ve been able to convince some Rebel supply officer that I''m willing to trade a few crates of Imperial blaster rifles for a hyperdrive part that I need. Would you mind making the trade for me?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 12, 'npc_2_1', 'Down to business then. I want you to meet a "procurement specialist" that picked up an item that fell off the Imperial supply roster. Don''t worry about what it is, pal, just bring it back here.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 13, 'npc_2_2', 'Great. You go and meet this Rebel and remove the part from the smoldering corpse -- being careful not to damage the part of course. You get the glory of being the great Rebel slayer and I get the proceeds from selling that hyperdrive part. It''s win-win.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 14, 'npc_3_1', 'No problem, pal. You need something later? You come see me.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 15, 'npc_3_2', 'That''s okay. Just keep me in mind when you want to do business.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 16, 'npc_4_1', 'Hey, slow down, pal. You ask an awful lot of questions that don''t concern you. I just need someone to pick up a little something that got lost -- from the supply roster. No big deal. What do you say?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 17, 'npc_4_2', 'Don''t be such a chump. This is just business and I want that part. I can sell that part for a tidy sum and help put my kid through the Academy -- if I ever have one. Besides, it''s not as though I''m actually going to give up the blaster rifles. That''s where you come in. How about it?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 22, 'npc_backtowork_1', 'I''ve got a business to run as well as my actual job to do, make it snappy.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 23, 'npc_backtowork_2', 'Are you waiting for something or was there something you needed to tell me?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 24, 'npc_breech_1', 'You weren''t followed were you? Not that I''m impugning your skills.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 25, 'npc_breech_2', 'It''s a double-cross!'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 28, 'npc_failure_1', 'Too much for you, huh? This is going to cost me a fortune.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 29, 'npc_failure_2', 'Pal, you''re breaking my heart here.  No part? How am I supposed to put my kid through the Academy now?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 36, 'npc_noloc_1', 'You''d think these people would call and tell you where they want to make the drop, but no. I have to do everything myself.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 37, 'npc_noloc_2', 'Let me find out where you''re supposed to turn that Rebel into a grease spot -- I mean make the trade. Come see me in a few minutes.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 38, 'npc_reset_1', 'If you want to finish up later come back and see me.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 39, 'npc_reward_1', 'Great, I''ve already got a buyer waiting for this. '),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 40, 'npc_reward_2', 'Great work, pal! We make quite a team. You keep killing Rebels and I''ll keep selling off their stuff and together we''ll bring peace and prosperity to the galaxy.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 41, 'npc_smuggle_1', 'I''m glad to get this thing off my hands. Be careful it doesn''t burn you.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 45, 'npc_work_1', 'You picked up my package yet? I need that merchandise.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 46, 'npc_work_2', 'What are you waiting for, pal?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 49, 'player_1_1', 'Yes'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 50, 'player_1_2', 'Yes'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 51, 'player_2_1', 'No'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 52, 'player_2_2', 'No'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 53, 'player_3_1', 'What do you want me to pick up?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 54, 'player_3_2', 'You want me to give crates of Imperial blaster rifles to the Rebels? Are you out of your mind?'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 55, 'player_4_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 57, 'player_5_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 67, 'return_waypoint_description_1', 'Return to Gravin Attal with the disc'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 68, 'return_waypoint_description_2', 'Return to Gravin Attal with the hyperdrive part.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 69, 'return_waypoint_name_1', 'Gravin Attal'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 70, 'return_waypoint_name_2', 'Gravin Attal'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 71, 'waypoint_description_1', 'Go pick up the item from the smuggler'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 72, 'waypoint_description_2', 'Go kill the Rebel supply sergeant and take the hyperdrive part.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 73, 'waypoint_name_1', 'Smuggler''s location'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 74, 'waypoint_name_2', 'The Rebel supply sergeant''s location'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 75, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 76, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_imperialoutpost_gravin_attal.stf', 77, 'npc_reset_2', 'If you want to finish up later come back and see me.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 1, 'cant_work', 'If you manage to get away from your current duties, come see me about some work.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 2, 'dontknowyou_1', 'This may not be the safest place to be friend. Why don''t you continue on your way and leave any trouble to us.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 6, 'next', 'I have such a shortage of volunteers in my line of work. It''s nice to see you have an interest. Check back with me later and perhaps I can find something for you.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 7, 'notit_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 8, 'notit_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 9, 'notyet', 'Can''t talk to you now, okay?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 10, 'npc_1_1', 'Are you at all familiar with the Berserker Virus? It has the wonderful effect of heightening aggression. I''m a huge fan of that clever little bit of bioengineering. I picked up a sample of it myself and I''ve been doing a little tinkering on it recently in an effort to remove the one flaw in its design. Do you think you can help me with that?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 11, 'npc_1_2', 'Well that version of the virus wasn''t at all what I was anticipating. The subject''s muscles contorted so badly that eventually every bone was shattered. The subject told me the most remarkable things while begging for release from the pain. Which leads me to a new problem I need help with -- If you''re willing?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 12, 'npc_2_1', 'Excellent. Find the Imperial defector and bring this test subject back to me. We''ll see how my new version of the Berserker Virus is coming along.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 13, 'npc_2_2', 'I want you to destroy the Rebel lab that''s trying to cure the Berserker Virus. That should set them back a bit and give me time to develop my own version that will work on sapient races.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 14, 'npc_3_1', 'I suppose I''ll have to speak with Commander Guul about impressing an Imperial volunteer into service. What was your name again? '),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 15, 'npc_3_2', 'Why would you refuse? I''d inoculate you against any possible contaminants from the lab. '),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 16, 'npc_4_1', 'Not unless you want me to. I want you to go find me a subject to test my new variation of the virus on. We recently had a defector. I think a traitor like that would make a splendid volunteer. What do you say? '),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 17, 'npc_4_2', 'Before my subject died, I learned that a small Rebel-operated lab is close to finding a cure for the existing virus. That would jeopardize all my hard work. Will you help me stop these Rebel brutes from destroying a perfectly good bio-weapon?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 18, 'npc_5_1', 'The flaw is that it doesn''t work on sapient creatures. I''m sure I can fix that in no time with a few tweaks.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 22, 'npc_backtowork_1', 'Was there something else or did you want to spare yourself the legwork and just volunteer to test the new virus?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 23, 'npc_backtowork_2', 'Oh that''s right, I forgot to inoculate you against lab contaminants. Did you forget something too?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 24, 'npc_breech_1', 'NPC arrestee hail dialog (npc_breech)	I surrender! Please don''t kill me!'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 25, 'npc_breech_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 26, 'npc_dropoff_1', 'You can''t do anything worse to me than I''ve already done to myself. '),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 28, 'npc_failure_1', 'Well since I don''t have any Rebel test subjects, I suppose I''ll have to make do with what''s at hand -- Unless you wanted to try again?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 29, 'npc_failure_2', 'Do you feel all right? You look pale. Perhaps I should give you a nutrient injection and take a few blood samples to see if there''s some physical cause for your failure.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 36, 'npc_noloc_1', 'I''ll see if I can discover the last location of a Rebel sighting. Come see me in a little while.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 37, 'npc_noloc_2', 'I''ll have to look through my recordings and find out where that test subject said the Rebel lab was located. This may take a while. Come back a little later.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 38, 'npc_reset_1', 'I hate to let anyone go before an experiment is complete but I suppose as long as you came back later it would be all right. '),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 39, 'npc_reward_1', 'I should probably give you a quick inoculation against some of the local microorganisms -- wait, where are you going?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 40, 'npc_reward_2', 'Splendid! Hopefully that will set them behind for months and give me time to mutate my virus into something they won''t be able to find a cure for. Oh, how I love science!'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 43, 'npc_takeme_1', 'I''m a disgrace to the Empire and the Rebellion. Maybe I can at least die with a little dignity.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 45, 'npc_work_1', 'Have you found me a volunteer yet? I''m giddy with anticipation.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 46, 'npc_work_2', 'Splendid! Hopefully that will set them behind for months and give me time to mutate my virus into something they won''t be able to find a cure for. Oh, how I love science!'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 47, 'otherescort_1', 'This may not be the safest place to be friend. Why don''t you continue on your way and leave any trouble to us.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 49, 'player_1_1', 'Yes'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 50, 'player_1_2', 'Yes'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 51, 'player_2_1', 'No'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 52, 'player_2_2', 'No'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 53, 'player_3_1', 'You''re not going to inject me with anything are you? '),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 54, 'player_3_2', 'You certainly do have a problem -- what do you think your problem is?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 55, 'player_4_1', 'What is the one flaw in the design?'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 57, 'player_5_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 67, 'return_waypoint_description_1', 'Return the traitor to Lethin Bludder for scientific experiments.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 68, 'return_waypoint_description_2', 'Return to Lethin Bludder and inform him of your success.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 69, 'return_waypoint_name_1', 'Lethin Bludder'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 70, 'return_waypoint_name_2', 'Lethin Bludder'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 71, 'waypoint_description_1', 'Go and capture the traitor to the Empire from his new Rebel friends'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 72, 'waypoint_description_2', 'Go destroy the Rebel lab'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 73, 'waypoint_name_1', 'location of the Imperial traitor'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 74, 'waypoint_name_2', 'The Rebel lab''s location'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 75, 'npc_reset_2', 'I hate to let anyone go before an experiment is complete but I suppose as long as you came back later it would be all right. '),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_lethin_bludder.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 1, 'cant_work', 'The Empire should be your only master. Come back when you are serving no other.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 2, 'dontknowyou_1', 'Can''t talk now. I''m terribly busy.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 3, 'dontknowyou_2', 'Can''t talk. Busy.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 4, 'dontknowyou_3', 'Get lost. I''m busy.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 8, 'next', 'That is all for now, agent. But smugglers are a tenacious breed, so I may have more work for you later.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 9, 'notit_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 10, 'notit_2', 'This is not the forged permit I asked you to bring me.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 11, 'notit_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 12, 'notyet', 'Sorry, I have nothing to say at the moment.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 13, 'npc_1_1', 'Although I should be leading the search for those Rebel scum, my superiors have decided that I should curb smuggling activity on Talus. A Kowakian monkey-lizard could perform such a duty. But if they want smuggling curbed on this planet, then I shall give them what they want. You''re a servant of the Empire. I call upon you to assist me in carrying out these orders. I need an informant arrested and brought back here for interrogation. Can the Empire count on you?'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 14, 'npc_1_2', 'That Bothan began singing even before we had activated our Interrogator droid. We now know who possesses one of these forged permits. I must get it at any cost. If the individual who has it or any companions try to resist, blast them all. Careful you don''t damage the evidence, however. It should be contained inside a datadisc. Will you do it?'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 15, 'npc_1_3', 'While you were gone, we used the Interrogator on the Bothan - I felt he was holding back. Wouldn''t you know it, my instincts proved correct. He gave us the name and location of a top-rate data slicer who''s been cracking the Imperial network on Talus and creating these forged permits. I need you to retire this individual.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 16, 'npc_2_1', 'Good answer. The informant is at the following coordinates. He''s a Bothan, and you know how cautious they can be, so be prepared for a struggle. But whatever happens, I need the Bothan alive. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 17, 'npc_2_2', 'Good. The target is a smuggler, so don''t feel too badly about blasting first and skipping the questions part. Remember, don''t damage that permit. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 18, 'npc_2_3', 'Take your heaviest weapon along. This data slicer has eluded Imperial agents for years and rumor has it that paranoia has turned this scum into a very well protected individual. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 19, 'npc_3_1', 'Why are you wasting my time? Is it any wonder the Empire struggles to locate the Rebels when we have to rely on agents such as you? Get out of my sight!'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 20, 'npc_3_2', 'And here I was actually thinking you might be worth something. Leave at once.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 21, 'npc_3_3', 'The only reason I don''t have you arrested is because you''ve been of some use thus far. Leave before I change my mind.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 22, 'npc_4_1', 'Although I can''t prove it, I know this scum has been selling forged transport permits to smugglers. Once I interrogate this worm, I''ll know to whom he''s sold these permits so I can acquire one as evidence. Will you go?'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 23, 'npc_4_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 24, 'npc_4_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 31, 'npc_backtowork_1', 'Why do you delay? Get going.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 32, 'npc_backtowork_2', 'Don''t just stand there. Go get me that permit.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 33, 'npc_backtowork_3', 'What are you waiting for? Perform your duty.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 34, 'npc_breech_1', 'On the alert, agents! I sense trouble approaches.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 35, 'npc_breech_2', 'Who''s that? Doesn''t look like a friendly sort to me.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 36, 'npc_breech_3', 'Who''s that? I don''t know! It must be an enemy! Fire!'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 37, 'npc_dropoff_1', 'My mother always said I''d wind up meeting a violent end. I wish I could see her one last time to let her know she was right. Never doubt your mother, friend.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 40, 'npc_failure_1', 'Now I shall have to find another link in this twisted chain. You disappoint me. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 41, 'npc_failure_2', 'It becomes quite difficult, although not impossible, to bring criminals to justice without evidence. You''ve failed me.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 42, 'npc_failure_3', 'These permits will continue to circulate on this planet and this scum will likely go into hiding. You''ve certainly botched this assignment.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 43, 'npc_more_1_1', 'I don''t know what you''re talking about. What forged permits? I''m an honest businessman. How much is Guul paying you? Maybe I can double it?'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 44, 'npc_more_1_2', 'Commander Guul, eh? Well come and take it if you can, hotshot!'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 46, 'npc_more_2_1', 'If that monster gets his hands on me, I''ll never see my family again! Please be merciful and let me go. I promise to go straight! Honest!'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 49, 'npc_more_3_1', 'I''m doomed! I''ll be sent to the Spice Mines of Kessel or fed to rancors on Dathomir! And that''s if I''m lucky! Why do bad things always happen to me?'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 52, 'npc_noloc_1', 'I need to verify the Bothan''s location. One moment.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 53, 'npc_noloc_2', 'I will verify the smuggler''s coordinates. Wait a few moments.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 54, 'npc_noloc_3', 'I must verify the data slicer''s coordinates with my people. One moment.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 55, 'npc_reset_1', 'I have no time for agents that cannot finish what they start. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 56, 'npc_reward_1', 'An acceptable performance. There is more work to be done so feel free to remain.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 57, 'npc_reward_2', 'Excellent. This will allow me to round up the members of this little smuggling ring. Finally, I''ll get to do the sort of work I was born to do.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 58, 'npc_reward_3', 'Well done, agent. I will mention your name in my report. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 62, 'npc_takeme_1', 'Don''t kill me! I surrender! Who sent you?'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 65, 'npc_work_1', 'Where is that Bothan informant? He is the key to solving this smuggling problem.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 66, 'npc_work_2', 'Where is that forged permit? I cannot stop these smugglers without that crucial bit of evidence.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 67, 'npc_work_3', 'Has that data slicer been removed yet? I am not a terribly patient man.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 68, 'otherescort_1', 'I''m not the man you''re looking for.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 77, 'player_3_1', 'What has this informant done?'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 78, 'player_3_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 79, 'player_3_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 80, 'player_4_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 81, 'player_4_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 82, 'player_4_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 83, 'player_5_1', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 84, 'player_5_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 85, 'player_5_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 86, 'player_more_1_1', 'Commander Guul sent me to arrest you for selling forged Imperial permits.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 87, 'player_more_1_2', 'You''ve got a forged permit that Commander Guul wants.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 89, 'player_more_2_1', 'Let''s go. Commander Guul is waiting.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 92, 'player_more_3_1', 'Save it for Commander Guul. Now get a move on.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 97, 'return_waypoint_description_1', 'Bring the informant back to Commander Guul for interrogation.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 98, 'return_waypoint_description_2', 'Bring the forged permit back to Command Guul for use as evidence.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 99, 'return_waypoint_description_3', 'Report your success back to Commander Guul.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 100, 'return_waypoint_name_1', 'Commander Guul''s Location'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 101, 'return_waypoint_name_2', 'Commander Guul''s Location'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 102, 'return_waypoint_name_3', 'Commander Guul''s Location'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 103, 'waypoint_description_1', 'Arrest the informant on charges of forgery.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 104, 'waypoint_description_2', 'Get the forged transport permit from the smuggler.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 105, 'waypoint_description_3', 'Retire the data slicer.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 106, 'waypoint_name_1', 'Bothan Informant''s Location'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 107, 'waypoint_name_2', 'Smuggler''s Location'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 108, 'waypoint_name_3', 'Data Slicer''s Location'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 109, 'npc_reset_2', 'I have no time for agents that cannot finish what they start. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 110, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 111, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 112, 'npc_reset_3', 'I have no time for agents that cannot finish what they start. Dismissed.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 113, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_imperialoutpost_xalox_guul.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 1, 'cant_work', 'Can''t have distractions while you''re performing security work. Come see me when your plate is clear.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 2, 'dontknowyou_1', 'Get lost!'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 3, 'dontknowyou_2', 'I''m a bit busy at the moment.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 4, 'dontknowyou_3', 'Get lost!'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 8, 'next', 'That''s all I''ve got for now. But in a place like this, you never know. Check back every now and again.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 9, 'notit_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 10, 'notit_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 11, 'notit_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 12, 'notyet', 'Sorry, I can''t talk now.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 13, 'npc_1_1', 'The name''s Pyne, Durgur Pyne. I''m in charge of security. We''ve had some problems with pirates recently. I hate pirates. There''s nothing I like better than blasting them into so much space dust. Word around town is that you''re pretty good with that sort of thing. I''m a bit short-handed right now. Think you can help me bring these lousy murderers in?'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 14, 'npc_1_2', 'These sleemos just kidnapped one of my best agents. Last mistake they''ll ever make. These creeps know most of my people, so if they saw one of us approaching, they''d ace their prisoner. You might be able to get the drop on these slugs. Will you help me rescue my agent?'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 15, 'npc_1_3', 'The agent you rescued provided us with the pirate leader''s location. This is one dangerous individual, but I think it only fair to offer you a shot at taking this notorious criminal out seeing as how we never would have found this killer without your help. What do you say? You want a shot at him?'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 16, 'npc_2_1', 'Good. One of these cutthroats is wanted for a multiple murder. The sleemo gunned down an entire family just because they made him late to a dinner date. Bring this guy in. I want a crack at this animal myself. Good luck.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 17, 'npc_2_2', 'We''ve been tracking our man for about an hour so these coordinates should be good. With luck, those pirates haven''t found the tracer yet. Hurry, my agent''s life is in your hands.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 18, 'npc_2_3', 'I thought you''d say that. I''ll contact a couple of my officers to give you some backup. Go get this sadistic scum, buddy. And give those sleemos our regards.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 19, 'npc_3_1', 'I guess I heard wrong. Stay out of trouble. Unless you want to meet again under very different circumstances.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 20, 'npc_3_2', 'I have to assume you have a great reason for refusing because otherwise it makes you seem like a callous mercenary - and I hate those.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 21, 'npc_3_3', 'Fair enough. We''ll take care of this loser on our own. Best of luck to you.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 22, 'npc_4_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 23, 'npc_4_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 24, 'npc_4_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 31, 'npc_backtowork_1', 'We''re not getting any younger. You want to back out?'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 32, 'npc_backtowork_2', 'No time to waste. Or are you reconsidering?'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 33, 'npc_backtowork_3', 'That creep''s waiting for your visit, friend. Get going.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 34, 'npc_breech_1', 'Heads up, we''ve got another "hero" headed this way!'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 35, 'npc_breech_2', 'You''ll never get away with this, you filthy pirates! My people will hunt each of you down!'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 36, 'npc_breech_3', 'Heads up, lads! We''ve got trouble!'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 37, 'npc_dropoff_1', 'If you''re smart, you''ll get off this planet. Not that it''ll stop my mates from finding you and making you pay for what you did.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 38, 'npc_dropoff_2', 'Thanks, pal. I won''t forget this. And you can bet we''ll bring those criminals in. My word on that.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 40, 'npc_failure_1', 'I''ll have to get the Bounty Hunters'' Guild involved in this. I was hoping to avoid that.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 41, 'npc_failure_2', 'Those pirates will pay dearly for this. Even if I have to chase them to the ends of the universe, I swear I''ll avenge my agent.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 42, 'npc_failure_3', 'We''ll get this scum, no matter the cost. Wish you could have done the job, though. It would have made for a bit of poetic justice.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 44, 'npc_more_1_2', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 52, 'npc_noloc_1', 'I need to verify this sleemo''s coordinates with my surveillance crew. Come back in a few.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 53, 'npc_noloc_2', 'Let me double-check those coordinates. Hang on for just a second.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 54, 'npc_noloc_3', 'My people need to verify these coordinates. Check back with me in a few.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 55, 'npc_reset_1', 'Security work is not for everyone. Come back if you change your mind.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 56, 'npc_reward_1', 'Good job. I''ll conduct this scum''s interrogation personally. I''d invite you to watch, but you''re not CorSec. We like to keep certain things in the family. You understand.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 57, 'npc_reward_2', 'I''m grateful, buddy. CorSec owes you one. You''ve earned this reward.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 58, 'npc_reward_3', 'If you ever contemplate a career in security, keep CorSec in mind. It''s been a pleasure working with you. Farewell.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 62, 'npc_takeme_1', 'Okay, okay! I surrender! Just take it easy. Where did that horn-head find you?'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 63, 'npc_takeme_2', 'Glad you showed up when you did. I''ve got lots to report to Captain Pyne. Let''s get moving before more of these sleemos show up.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 65, 'npc_work_1', 'Did you arrest that brutal killer yet? I''m eager to interrogate him.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 66, 'npc_work_2', 'Have you rescued our agent? I don''t know how much longer those pirates will keep my agent alive.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 67, 'npc_work_3', 'Have you taken care of this pirate leader yet? There''s no telling how long these creeps will stay on Talus.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 68, 'otherescort_1', 'Get lost!'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 69, 'otherescort_2', 'I''m a bit busy at the moment.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 77, 'player_3_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 78, 'player_3_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 79, 'player_3_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 80, 'player_4_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 81, 'player_4_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 82, 'player_4_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 83, 'player_5_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 84, 'player_5_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 85, 'player_5_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 97, 'return_waypoint_description_1', 'Escort the pirate back to Captain Pyne.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 98, 'return_waypoint_description_2', 'Escort the CorSec agent back to headquarters.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 99, 'return_waypoint_description_3', 'Report your success to Captain Pyne.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 100, 'return_waypoint_name_1', 'Captain Pyne''s Location'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 101, 'return_waypoint_name_2', 'Captain Pyne''s Location'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 102, 'return_waypoint_name_3', 'Captain Pyne''s Location'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 103, 'waypoint_description_1', 'Arrest the murderous pirate.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 104, 'waypoint_description_2', 'Rescue the CorSec agent from the pirates.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 105, 'waypoint_description_3', 'Take out the murderous pirate captain.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 106, 'waypoint_name_1', 'Pirate Lieutenant''s Location'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 107, 'waypoint_name_2', 'CorSec Agent''s Location'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 108, 'waypoint_name_3', 'Pirate Captain''s Location'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 109, 'npc_reset_2', 'Security work is not for everyone. Come back if you change your mind.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 110, 'npc_reset_3', 'Security work is not for everyone. Come back if you change your mind.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 111, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 112, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 113, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_durgur_pyne.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 1, 'cant_work', 'I struggle with a sub-optimal endeavor that requires assistance, when you are less busy.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 2, 'dontknowyou_1', 'You''re not looking for me, believe me.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 3, 'dontknowyou_2', 'You''ve got the wrong person.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 4, 'gotowork_1', 'I wanted the blaster cannon plans from that slicer called "Green Laser."'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 6, 'next', 'All is currently optimal. I require no assistance.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 7, 'notit_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 8, 'notit_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 9, 'notyet', 'Too busy to talk now.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 10, 'npc_1_1', 'Oh, this is sub-optimal! I face grave problems in delivering certain data to my client. I offer incentive to you to execute this delivery. Agreement?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 11, 'npc_1_2', 'I am alarmed! CorSec investigators have discovered my actions and will soon arrest me. They do not realize I am under protection! I wish you to stop them with fatal force.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 12, 'npc_2_1', 'Optimal reply. I urge you to take this information to the anonymous representative of my client at a designated unobserved spot. Haste!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 13, 'npc_2_2', 'This indicates reason for optimism. Destroy the CorSec investigator and accompanying patrol officer.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 14, 'npc_3_1', 'Entirely sub-optimal. We part now.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 15, 'npc_3_2', 'I must rely on the protection of my client. I am annoyed and frightened and also anxious.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 16, 'npc_4_1', 'I face stern prohibition against naming my client, a high government official. He seeks certain classified Imperial reports as an aid to securing favor of a former Moff.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 17, 'npc_4_2', 'One is a CorSec data trail specialist. I have sliced his arrest requisition and find he has enlisted a patrol officer as support. Murder them both for my safety!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 18, 'npc_5_1', 'This Imperial Navy report concerns a new Star Destroyer weapon. Interest runs high.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 19, 'npc_5_2', 'My client is the Prime Minister. He told all relevant CorSec forces to ignore me. This investigator clearly ignores the directive. Avoid mentioning this to anyone.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 20, 'npc_6_1', 'Indeed. Not many Drall slice. I hope CorSec believes none do. That is all the better for anonymity for me.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 21, 'npc_6_2', 'I slice! To identify me, name and appearance and DNA and slicing gear, is to destroy me! Stop the investigator!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 22, 'npc_backtowork_1', 'All stands ready! Deliver the data to my client!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 23, 'npc_backtowork_2', 'The matter is entirely clear! I wish you to murder the CorSec investigator and patrol officer at once!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 24, 'npc_breech_1', 'You got the data from that slicer?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 25, 'npc_breech_2', 'Fed-Dub officer! Give up!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 28, 'npc_failure_1', 'Oh, entirely sub-optimal! I require another individual to execute successful delivery.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 29, 'npc_failure_2', 'You spared the investigator? Oh, I am perturbed! I face arrest and exposure!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 30, 'npc_more_1_1', 'Never you mind. Just understand this -- he''s as high as they get around here.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 36, 'npc_noloc_1', 'Datapad problems prevent acquisition of a desirable rendezvous. Check later.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 37, 'npc_noloc_2', 'I now slice into a CorSec database to track the investigator''s location. Consult me soon for results.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 38, 'npc_reset_1', 'This is sub-optimal. However, conditions indicate that you may later resume the assignment without injury.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 39, 'npc_reward_1', 'Optimal! I commend your work maximally. Future conditions imply the chance of further employment.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 40, 'npc_reward_2', 'You relieve my piercing anxiety. I reward you with commensurate funds.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 41, 'npc_smuggle_1', 'I gotta get these plans to the boss.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 45, 'npc_work_1', 'All stands ready! Deliver the data to my client!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 46, 'npc_work_2', 'The matter is entirely clear! Murder the CorSec investigator and patrol officer before I face arrest!'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 53, 'player_3_1', 'Who is your client?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 54, 'player_3_2', 'Who are the investigators?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 55, 'player_4_1', 'What is the data?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 56, 'player_4_2', 'What do you mean by "under protection"?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 57, 'player_5_1', 'Are you a data slicer?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 58, 'player_5_2', 'Why can''t your protector just get you released after arrest?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 59, 'player_more_1_1', 'Who is your boss?'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 67, 'return_waypoint_description_1', 'Drall slicer who wanted Imperial blaster cannon plans delivered to the representative of a high government official.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 68, 'return_waypoint_description_2', 'This Drall slicer wanted a Fed-Dub investigator stopped.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 69, 'return_waypoint_name_1', 'Green Laser'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 70, 'return_waypoint_name_2', 'Green Laser'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 71, 'waypoint_description_1', 'Rendezvous with a representative of a government official who seeks Imperial blaster cannon blueprints secured by the Drall slicer "Green Laser."'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 72, 'waypoint_description_2', 'Federation of the Double Worlds detective seeking to arrest the Drall slicer called "Green Laser."'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 73, 'waypoint_name_1', 'Blaster Cannon Plan Dropoff'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 74, 'waypoint_name_2', 'Fed-Dub Investigator'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 75, 'npc_reset_2', 'This is sub-optimal. However, conditions indicate that you may later resume the assignment without injury.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_green_laser.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 1, 'cant_work', 'I''ve got some work for you if you want it. Come see me when you''re done with your current gig.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 2, 'dontknowyou_1', 'I don''t know what you''re doing here but you''re in the wrong place.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 3, 'dontknowyou_2', 'You should probably move along. I''m here to conduct some business that doesn''t concern you.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 6, 'next', 'I''m very impressed with how you handle yourself. I don''t have anything else at the moment but I''ll keep you in mind for future jobs.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 7, 'notit_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 8, 'notit_2', 'I told you to bring back the spice. What am I supposed to do with this?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 9, 'notyet', 'Sorry, I can''t help you right now.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 10, 'npc_1_1', 'Have you ever done any "work" for Black Sun before? Doesn''t matter really -- I''m desperate. There''s this Hutt operative that needs to be killed, and if I don''t arrange it, someone else will and I''ll look incompetent. Do you think you could be a pal and help me out?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 11, 'npc_1_2', 'I''ve been looking for a way to make things right with the boss after that last fiasco. I think I''ve finally found a way to show her what I''m capable of. If you''re willing to help me, I''ll take you right to the top with me. What do you say? Are you in? '),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 12, 'npc_2_1', 'Great. I''ll give you the location of this new Hutt operative and you go take him out. Simple, right? See that he gets the message if you know what I mean.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 13, 'npc_2_2', 'Here''s what I need. The Hutts'' new hotshot has a big deal going down involving some new extra potent kind of spice. I want you to intrude upon the meeting and become the new owner of the spice by way of being the only one alive in its vicinity.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 14, 'npc_3_1', 'Then get out of here. I''ve got business to take care of.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 15, 'npc_3_2', 'Your loss. '),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 16, 'npc_4_1', 'How the heck should I know? I just got a call asking if I''d taken care of "delivering that message" to the Hutts'' new operative. I said yes, so now I need to get it done. What do you say? Will you help me?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 17, 'npc_4_2', 'Very funny, wise guy. After you killed that last operative, the Hutts replaced that sleemo with a totally slick operator. You know the kind -  makes a move before anyone else knew there was a move that could be made. I want in on that action. Are you going to help me?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 22, 'npc_backtowork_1', 'I''ve told you all I know. What are you pestering me for? '),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 23, 'npc_backtowork_2', 'What''s with all the questions? You took the job now get moving.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 24, 'npc_breech_1', 'What kind of double-cross is this? I was just supposed to pick up a message.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 25, 'npc_breech_2', 'Do you have any idea what you''re messing with?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 28, 'npc_failure_1', 'You didn''t kill him did you?  Why do I always have such bad luck?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 29, 'npc_failure_2', 'You couldn''t get the stuff? Uh-Oh! I already told the boss I''d just finished a major new deal. What''ll I do now?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 36, 'npc_noloc_1', 'Let me find out where the Hutts are working from these days. They tend to move around a lot. Come back and see me in a little while.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 37, 'npc_noloc_2', 'Come back in a little while, I need to find out where my agent said that deal was going to occur. '),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 38, 'npc_reset_1', 'You come back and work for me later. You can finish up then.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 39, 'npc_reward_1', 'You didn''t kill him did you? Oh no! It turns out I was supposed to deliver an actual message. The boss is gonna kill me when she hears about this.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 40, 'npc_reward_2', 'Can you believe my luck? It turns out this hotshot operative was our double agent and it was a shipment of tainted spice we were slipping to the Hutts. I wonder if there''s someone else I can pin this on? Don''t worry - they''d never believe it was you.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 45, 'npc_work_1', 'Have you killed that Hutt operative yet? I''m on a schedule here.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 46, 'npc_work_2', 'You''d better hurry up and grab that spice. The deal is going to go down pretty soon. '),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 49, 'player_1_1', 'Yes'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 50, 'player_1_2', 'Yes'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 51, 'player_2_1', 'No'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 52, 'player_2_2', 'No'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 53, 'player_3_1', 'What did this Hutt operative do?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 54, 'player_3_2', 'I know I''m going to be sorry I asked, but what do you have in mind this time?'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 55, 'player_4_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 57, 'player_5_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 67, 'return_waypoint_description_1', 'Return to Igbi Freemo and tell him you were successful'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 68, 'return_waypoint_description_2', 'Return to Igbi Freemo with the spice'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 69, 'return_waypoint_name_1', 'Igbi Feemo'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 70, 'return_waypoint_name_2', 'Igbi Freemo'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 71, 'waypoint_description_1', 'Go and kill the Hutt''s operative'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 72, 'waypoint_description_2', 'Go to and snatch the spice from the Hutts'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 73, 'waypoint_name_1', 'Location of the Hutt operative'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 74, 'waypoint_name_2', 'Location of the spice deal'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 75, 'npc_reset_2', 'You come back and work for me later. You can finish up then.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_igbi_freemo.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 1, 'cant_work', 'I won''t tempt you with assignments while you are currently employed by another. Seek me out when you''re free. '),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 2, 'dontknowyou_1', 'I''m terribly busy. Go away.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 6, 'next', 'That is all I require of you at the moment. I shall have to carefully plot my revenge against my remaining enemies. Check back with me from time to time.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 7, 'notit_1', 'That is not the briefcase I asked you to bring me. I do hope you''re not trying to cheat me.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 8, 'notit_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 9, 'notyet', 'I don''t have anything for you at the moment.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 10, 'npc_1_1', 'Enjoying your stay on Talus? I find it quite relaxing here. Of course I''m looking at it from a civilian''s perspective now. Used to be my word was law in this sector and the fates of billions of sentient beings were held in my hand. But that was a long time ago, when I was young and idealistic. So idealistic in fact that I chose to ignore my enemies, thinking they couldn''t possibly hurt someone in my position. But I won''t ignore them now. Care to make some money helping a former Moff correct the mistakes of his past?'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 11, 'npc_1_2', 'The second phase of my plan must now go into effect. Having secured the only known plans for the experimental ion engine, I must now call upon your services to remove the only existing prototype. If you thought I was generous before, then you should probably undertake this mission. You in?'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 12, 'npc_2_1', 'Ah, how well I recognize unbridled ambition. If you never temper justice with mercy, you''ll go far. Oh, be sure to tell my former business associate that Moff Zhord sends his regards.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 13, 'npc_2_2', 'Excellent. You''ll find the man with the prototype at this location.  I want it brought back to me.  '),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 14, 'npc_3_1', 'Not a terribly ambitious sort, eh? So be it. There are plenty of others who are.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 15, 'npc_3_2', 'As you wish. My credits will simply go to another.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 16, 'npc_4_1', 'A Corporate Sector Authority executive, a former "business associate" of mine, will be transporting some schematics for an experimental ion engine to his superiors. I want those schematics. They''re locked safely in a briefcase so you should have no trouble finding them. Do what you will with the CSA officer, although I tend to think he''ll fight to the death to protect that briefcase.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 17, 'npc_4_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 18, 'npc_5_1', 'Not anymore.  Because I helped organize and fund the research team that led to the discovery of this new ion engine. I had to bend some rules here and there, of course, and that''s exactly what my enemies used to discredit me. So it would be a cold day on Tatooine before I let them get rich off my sacrifice.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 20, 'npc_6_1', 'The specifics of my downfall are not important. What is important is that those who betrayed me are about to get rich at my expense and I will do everything in my power to stop them. Do you wish to help me or not?'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 22, 'npc_backtowork_1', 'But really, enough talk. Now is the time for action. Do you wish to reconsider?'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 23, 'npc_backtowork_2', 'No more delays. Please attend to your duties.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 24, 'npc_breech_1', 'Look lively, gentlemen! I don''t like the look of that one!'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 25, 'npc_breech_2', 'You won''t get this prototype!'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 28, 'npc_failure_1', 'How tragic that you were unable to assist my plans. I believe I shall have to be more discriminating in the future.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 29, 'npc_failure_2', 'This is an unfortunate setback but nothing that a belt of thermal detonators couldn''t remedy. That will create more of a stir on Talus than I had initially wanted, but a man must do what he must do.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 30, 'npc_more_1_1', 'What? He''s still alive? But we killed him! I saw his ship blasted to pieces! We killed him!'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 36, 'npc_noloc_1', 'Allow me a few moments to verify those coordinates.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 37, 'npc_noloc_2', 'Allow me to verify the man''s coordinates. Check back with me in a few moments.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 38, 'npc_reset_1', 'A shame you couldn''t finish what you started. Best of luck in your future endeavors.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 39, 'npc_reward_1', 'Well done. Please treat yourself to something nice. Talus offers many pleasures to the discriminating buyer.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 40, 'npc_reward_2', 'Job well done. I admire your professionalism. When the time comes for me to execute my plans of revenge on my remaining enemies, I shall keep you in mind.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 45, 'npc_work_1', 'Where is my briefcase? I hope I haven''t made a mistake by employing you.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 46, 'npc_work_2', 'Did you get the prototype? I won''t allow anyone else to get rich off that design.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 53, 'player_3_1', 'What would I need to do?'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 54, 'player_3_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 55, 'player_4_1', 'You were "idealistic"?'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 57, 'player_5_1', 'How come you''re a civilian now?'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 59, 'player_more_1_1', 'Moff Zhord sends his regards.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 67, 'return_waypoint_description_1', 'Bring the briefcase back to Jusani Zhord.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 68, 'return_waypoint_description_2', 'Report your success back to Jusani Zhord.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 69, 'return_waypoint_name_1', 'Jusani Zhord''s Location'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 70, 'return_waypoint_name_2', 'Jusani Zhord''s Location'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 71, 'waypoint_description_1', 'Get the briefcase from the CSA officer.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 72, 'waypoint_description_2', 'Find the man with the prototype and kill him.  Bring the prototype back to Zhord.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 73, 'waypoint_name_1', 'Former Business Associate''s Location'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 74, 'waypoint_name_2', 'Prototype''s Location'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 75, 'npc_reset_2', 'A shame you couldn''t finish what you started. Best of luck in your future endeavors.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_jusani_zhord.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 1, 'cant_work', 'Step back soon, friend, when you''re not busy. Smooth out and slack back.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 2, 'dontknowyou_1', 'You''ve got the wrong person, friend.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 3, 'dontknowyou_2', 'I am waiting for another individual.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 4, 'gotowork_1', 'What exactly are you waiting for?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 5, 'gotowork_2', 'I expected a package from Sigrix full of -- not spice, what did he say it was? -- ah, a Selonian verovakin, yes.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 6, 'next', 'All is smooth, friend. No tasks trouble the unrippled calm of the mind''s landscape.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 7, 'notit_1', 'You lack the slack, friend -- this is not the ambient wildlife calls I need.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 8, 'notit_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 9, 'notyet', 'Can''t talk now.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 10, 'npc_1_1', 'Smooth it and seat it, my friend. I''m big in fizz. I got a friend making recordings for me, and you could do me a real good turn, picking-them-up-wise. Interested?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 11, 'npc_1_2', 'Smooth and slack, friend. I made some lissome fizz using a Selonian verovakin for harmony. I need to get it back to its owner. You game for the dropoff?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 12, 'npc_2_1', 'Smooth. They''re wildlife calls recorded live, so my friend is in the wilderness. Watch out for those animals, now.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 13, 'npc_2_2', 'Yes indeed, you are a smooth mover. You want a Selonian named Wooral. The verovakin is in this container. Don''t worry if it sounds like spice when you shake it, that''s just padding material.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 14, 'npc_3_1', 'No? How un-smooth. You lack the slack, friend.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 15, 'npc_3_2', 'How truly un-smooth.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 16, 'npc_4_1', 'They''re the beautiful calls of native Talus wildlife, lovingly recorded in the wilderness by a skilled engineer. They''ve got a happy path as overtones to my next piece. Can you nab these sweet sounds?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 17, 'npc_4_2', 'A tiny little twangy thing the Selonians play with the claws on their toes. I hear the males use it to entice the ladies. Wouldn''t know myself. Care to return it to its owner?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 22, 'npc_backtowork_1', 'The way lies clear, friend. Got to have those wildlife recordings.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 23, 'npc_backtowork_2', 'The way is smooth, friend. Take that verovakin back to Wooral.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 24, 'npc_breech_1', 'You here from that musician, Sigrix Slix?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 25, 'npc_breech_2', 'I am waiting for a delivery from Sigrix Slix! Is that you?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 28, 'npc_failure_1', 'You didn''t bring the stuff -- I mean, the recordings? That is so un-smooth. I''ll be lacking my slack now.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 29, 'npc_failure_2', 'You didn''t get that stuff -- that verovakin back to Wooral? Oh, very un-smooth. Gotta work up another delivery soonest.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 30, 'npc_more_1_1', 'Huh? Oh! Oh, of course, the wildlife calls. Here, this container is full of high-quality wildlife calls. Take it to Sigrix, he''ll love it. Them.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 31, 'npc_more_1_2', 'Yes, all right, musical instrument. Whatever he likes to call it. I only know my buyers need this container urgently.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 36, 'npc_noloc_1', 'Soon I''ll hear from my friend where his wanderings have taken him. Check back with me.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 37, 'npc_noloc_2', 'Wooral will call with the place for the happy return. Check with me soon.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 38, 'npc_reset_1', 'Smooth, friend. Check back when you can.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 39, 'npc_reward_1', 'Hmm? My friend said this was glitterstim spice? Ha. That noober. Here, friend, glom some creds and check back soon.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 40, 'npc_reward_2', 'Smooth, friend. Glad you returned that verovakin. Wooral thought that was spice? These aliens -- so strange. Can''t figure them out.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 41, 'npc_smuggle_1', 'He''s gonna love this stuff. This is 99 percent pure, this is. What a high!'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 42, 'npc_smuggle_2', 'This is -- what? -- a Selonian verovakin? As you say. Sigrix will pay you, I am sure.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 45, 'npc_work_1', 'Friend, my music waits. It wants those wildlife calls. Hope you can get them soon.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 46, 'npc_work_2', 'The way is smooth, friend. Take that verovakin back to Wooral.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 53, 'player_3_1', 'What sort of recordings?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 54, 'player_3_2', 'What is a verovakin?'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 55, 'player_4_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 56, 'player_4_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 57, 'player_5_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 58, 'player_5_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 59, 'player_more_1_1', 'Wait -- I thought I was picking up recorded sounds of ambient wildlife calls.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 60, 'player_more_1_2', 'You don''t seem to recognize this musical instrument, but Sigrix said he borrowed it from you.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 67, 'return_waypoint_description_1', 'This famous fizz musician is supposedly waiting for a friend''s recordings of ambient wildlife calls.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 68, 'return_waypoint_description_2', 'This fizz musician in Nashal is awaiting news of the delivery he arranged to a Selonian named Wooral, allegedly of a musical instrument called a verovakin.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 69, 'return_waypoint_name_1', 'Sigrix Slix'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 70, 'return_waypoint_name_2', 'Sigrix Slix'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 71, 'waypoint_description_1', 'Nashal musician Sigrix Slix wants a friend''s recordings of ambient wildlife calls made here.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 72, 'waypoint_description_2', 'This Selonian is waiting for a container from Nashal fizz musician Sigrix Slix, supposedly containing a musical instrument called a verovakin.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 73, 'waypoint_name_1', 'Ambient Wildlife Sounds'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 74, 'waypoint_name_2', 'Wooral'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 75, 'npc_reset_2', 'Smooth, friend. Check back when you can.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_sigrix_slix.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 1, 'cant_work', 'Come and see me when you get some free time. I have plenty of work for enterprising individuals.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 2, 'dontknowyou_1', 'I''m working. Get lost.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 3, 'dontknowyou_2', 'Sorry, hon, I''m busy.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 4, 'dontknowyou_3', 'Buzz off! I''m busy!'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 5, 'gotowork_1', 'Don''t you have something to do?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 6, 'gotowork_2', 'Well?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 8, 'next', 'That''s about all I have for you at the moment. You''ve been most helpful. I think you understand a bit more what it takes to run a city like this. Check back with me from time to time for more work.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 9, 'notit_1', 'That''s not the briefcase I asked you to bring me. Where did you put it?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 10, 'notit_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 11, 'notit_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 12, 'notyet', 'Sorry, I can''t deal with this right now.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 13, 'npc_1_1', 'Welcome to Nashal, friend! I like to think of our beautiful city as the friendliest on Talus, which is of course the friendliest planet of the Five Brothers. I''m sure you''ve noticed that everyone here sports a smile. That''s because we love visitors. And if you''re here to work, we love you even more. As a matter of fact, I have an assignment for you right now. Are you willing to make some credits the good old-fashioned way?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 14, 'npc_1_2', 'Stellar job on that last piece of business, friend. I treasure a being that understands the importance of discretion. So are you ready for more work? An important member of my cabinet has been accidentally stranded outside of town. I need someone to safely escort this hardworking member of my administration back here. Can Nashal count on you a second time? '),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 15, 'npc_1_3', 'Ever since that last bit of trouble with my cabinet member, I''ve been concerned that certain undesirable elements have been creeping into our lovely city. Our chief of security did some digging and uncovered -- brace yourself -- the presence of slavers on Talus. But these creeps are not content to stick to the Empire''s approved slave lists, oh no! These sleemos are enslaving honest, decent citizens. If you''re like me, you won''t stand idly by and let this sort of thing continue. I''m empowering you to arrest the leader of this despicable slave ring and bring him to justice. Will you do it?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 16, 'npc_2_1', 'That''s the Talus spirit, friend! Bring the briefcase back here as soon as you get it. And be sure to smile when my constituent gives it to you.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 17, 'npc_2_2', 'Splendid! I knew I could count on you. As with that last bit of work, discretion is important in this assignment. I''m sure we understand each other.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 18, 'npc_2_3', 'If you''re not a native of Talus, friend, I''d be happy to name you an honorary Talusian. We salute you! Now go get that slaver creep.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 19, 'npc_3_1', 'Hmm, you didn''t strike me as someone that doesn''t like to earn an honest, decent living. Well, perhaps you''re just busy. Enjoy your stay!'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 20, 'npc_3_2', 'Quite right, I''m sure you''ve got other more important things on your mind. Carry on.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 21, 'npc_3_3', 'I suppose this is more of a matter for local security. I was hoping you''d lend a hand and earn some credits along the way. Ah well...'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 22, 'npc_4_1', 'One of my more financially successful constituents has offered a generous donation to my administration. Could you collect this donation and bring it back to me? And just to avoid any misunderstandings, the briefcase you''ll be picking up is worthless to anyone who doesn''t have the proper codes to open it. Not that I''m implying an upstanding citizen such as yourself would even contemplate such misconduct. So can I count on you?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 23, 'npc_4_2', 'I''ll give you the proper coordinates, of course, but trust me, you can''t miss her. I did mention it was a woman, yes?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 24, 'npc_4_3', 'Didn''t you get a good look at her? Why she''s exactly the sort of beautiful innocent that those slavers would love to get their filthy hands on. Not in this city, friend, and not while I''m the Chief Administrator!'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 31, 'npc_backtowork_1', 'Was something unclear? I''ve told you everything you need to know.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 32, 'npc_backtowork_2', 'We shouldn''t delay. Time is of the essence.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 33, 'npc_backtowork_3', 'The slaver is still currently on the planet. Please hurry or they may all get away.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 34, 'npc_breech_1', 'Hey! Over here! Did Jong send you?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 35, 'npc_breech_2', 'Hey, hon! Over here! Did pookie -- I mean, Chief Administrator Jong send you?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 36, 'npc_breech_3', 'What''s this all about? Heads up, lads, we''ve got company.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 38, 'npc_dropoff_2', 'You''ve been a doll! I never felt safer. And, between you and me, I knew those goons were history the minute they showed up. See ya!'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 39, 'npc_dropoff_3', 'Make sure this sleemo pays you in full before the job is done. He''s likely to cheat you the way he cheated us. I hate corrupt politicians!'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 40, 'npc_failure_1', 'That donation would have helped a variety of public works currently in progress. A shame you couldn''t that briefcase to me.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 41, 'npc_failure_2', 'Where will I find someone else with the same unbridled enthusiasm for her work? Good help is hard to find these days.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 42, 'npc_failure_3', 'I''ll hire bounty hunters if I have to, but that sleemo is not escaping justice! I appreciate your efforts.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 44, 'npc_more_1_2', 'I''m his Leisure Officer. My job is to make sure the Chief Administrator doesn''t get too bogged down in his work. After all, a happy Chief Administrator translates into an efficient and productive city.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 52, 'npc_noloc_1', 'One moment while my people verify my constituent''s coordinates. Check back with me in a bit.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 53, 'npc_noloc_2', 'Let me verify my cabinet member''s coordinates. Just a moment.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 54, 'npc_noloc_3', 'My people have been tracking the movements of these slavers. Just a moment and I''ll give you the coordinates.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 55, 'npc_reset_1', 'A bit overwhelming, I understand. Feel free to come back if you''d like a shot at earning more credits.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 56, 'npc_reward_1', 'I''m sorry there was some trouble along the way, but alas our best efforts to rid Talus of the criminal element has not yet met with success. Still, you did a fine job and deserve your fee.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 57, 'npc_reward_2', 'Well done, my friend. And she seems fit as a viol. You have my deepest thanks, which is best expressed via credits.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 58, 'npc_reward_3', 'We''ll take it from here, friend. On behalf of the people of Nashal, I thank you.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 59, 'npc_smuggle_1', 'Tell "His Honor" that his shipping permits are becoming too expensive. There''s enough ryll in that case to get all of Nal Hutta dancing.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 63, 'npc_takeme_2', 'You''re new, aren''t you? Keep working hard for Chief Administrator Jong and you''ll be able to retire in a few years. He knows how to reward good service. I miss him! Let''s go!'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 64, 'npc_takeme_3', 'Don''t shoot! I''ll come along quietly! You may not know this but you''ve just made a huge mistake. Nobody messes with us.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 65, 'npc_work_1', 'Did you pick up that briefcase yet? It''ll seem rude to delay like this, don''t you agree?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 66, 'npc_work_2', 'Have you rescued my poor cabinet member? There are dangerous predators in the wilds of Talus, you know.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 67, 'npc_work_3', 'Have you brought that criminal in yet? The people of Nashal won''t be safe until you do.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 69, 'otherescort_2', 'Unfortunately for you, I''m not the gal you''re looking for.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 70, 'otherescort_3', 'Buzz off! I''m busy!'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 77, 'player_3_1', 'What would I have to do?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 78, 'player_3_2', 'How will I recognize this cabinet member?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 79, 'player_3_3', 'Why were slavers after your cabinet member?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 80, 'player_4_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 81, 'player_4_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 82, 'player_4_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 83, 'player_5_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 84, 'player_5_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 85, 'player_5_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 87, 'player_more_1_2', 'What exactly do you do for Chief Administrator Jong?'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 97, 'return_waypoint_description_1', 'Bring the briefcase back to Chief Administrator Jong.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 98, 'return_waypoint_description_2', 'Escort the cabinet member back to the Chief Administrator.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 99, 'return_waypoint_description_3', 'Escort the slaver back to town to face criminal charges.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 100, 'return_waypoint_name_1', 'Slooni Jong''s Location'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 101, 'return_waypoint_name_2', 'Chief Administrator Jong''s Location'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 102, 'return_waypoint_name_3', 'Chief Administrator Jong''s Location'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 103, 'waypoint_description_1', 'Collect a generous donation.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 104, 'waypoint_description_2', 'Collect Chief Administrator Jong''s cabinet member.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 105, 'waypoint_description_3', 'Arrest the leader of the slave ring.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 106, 'waypoint_name_1', 'Constituent''s Location'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 107, 'waypoint_name_2', 'Cabinet Member''s Location'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 108, 'waypoint_name_3', 'Slaver Leader''s Location'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 109, 'npc_reset_2', 'A bit overwhelming, I understand. Feel free to come back if you''d like a shot at earning more credits.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 110, 'npc_reset_3', 'A bit overwhelming, I understand. Feel free to come back if you''d like a shot at earning more credits.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 111, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 112, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 113, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/talus/talus_nashal_slooni_jong.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 1, 'npc_1_1', 'My name is Aaph Koden. I need the services of somebody willing to deliver a highly important message. Will you do it? '),
('string/en/static_npc/tatooine/aaph_koden.stf', 2, 'npc_1_2', 'I can''t entrust this mission to just anybody. The Empire has discovered that Talia Reede is Force-sensitive. I need you to stop them from killing her. What do you say? '),
('string/en/static_npc/tatooine/aaph_koden.stf', 3, 'npc_1_3', 'Our Jedi candidate, Talia Reede, is finally coming in for training and we want to send her an escort to bring her in safely. I really need someone I can trust on this one. What do you say?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 5, 'npc_2_1', 'That''s the spirit! I need you to take this datadisc to Talia Reede. It''s highly important to the Alliance that she get this message. We want her to contact us, so we can see about getting her some instruction.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 6, 'npc_2_2', 'Excellent! Courageous and adaptable -- I like that. My informers tell me that an Imperial stormtrooper commander is on her trail. He must be stopped. Be very careful, he probably has troopers with him.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 7, 'npc_2_3', 'I knew I could count on you. You haven''t let me down yet. Go get her, and don''t let anything stand in your way. Good luck.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 8, 'npc_3_1', 'Won''t even do a simple courier mission? Maybe moisture farming would be more your speed.  '),
('string/en/static_npc/tatooine/aaph_koden.stf', 9, 'npc_3_2', 'Lose your courage somewhere along the way, did you? Oh well.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 10, 'npc_3_3', 'I''m usually not surprised when people let me down, but I had really thought better of you.  Live and learn, I suppose.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 12, 'npc_4_1', 'We''ve discovered a woman we think is Force-sensitive. We want you to deliver this message to warn her of the potential dangers involved.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 13, 'npc_4_2', 'She hasn''t been trained to use the Force, she just has the potential. Will you help her?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 14, 'npc_4_3', 'She''s so skeptical -- it took a while to convince her she might be Force-sensitive. Can you believe it? Anyone else in the galaxy would give his right arm to be trained as a Jedi, but her we have to talk in to it.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 15, 'npc_reward_1', 'Looks like you came through for me. Good job. See me again later, and maybe I''ll have more work for you.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 16, 'npc_reward_2', 'You should be very proud. You may have saved the life of a future Jedi Knight. '),
('string/en/static_npc/tatooine/aaph_koden.stf', 17, 'npc_reward_3', 'There are few individuals I trust as much I''ve come to trust you. It''s an honor to serve in the Alliance with you. '),
('string/en/static_npc/tatooine/aaph_koden.stf', 18, 'player_1_1', 'I''ve done things like this before.  Sure.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 19, 'player_1_2', 'I can''t stand those thugs.  Sure, I''ll do it.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 20, 'player_1_3', 'You can count on me!'),
('string/en/static_npc/tatooine/aaph_koden.stf', 21, 'player_2_1', 'No thanks, sounds too dangerous.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 22, 'player_2_2', 'Sorry, but I don''t tangle with Stormtroopers.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 23, 'player_2_3', 'I''m not well-suited for this kind of thing.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 24, 'player_3_1', 'What''s so important about this message?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 25, 'player_3_2', 'If she can use the Force, why can''t she protect herself? '),
('string/en/static_npc/tatooine/aaph_koden.stf', 26, 'player_3_3', 'Why didn''t she come in for training sooner?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 27, 'player_reset_1', 'I can''t do this anymore.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 28, 'player_sorry_1', 'Not yet.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 29, 'npc_backtowork_1', 'Well, hurry!'),
('string/en/static_npc/tatooine/aaph_koden.stf', 30, 'npc_reset_1', 'Won''t even do a simple courier mission? Maybe moisture farming would be more your speed.  '),
('string/en/static_npc/tatooine/aaph_koden.stf', 31, 'cantwork', 'I''m sorry, If you''re working for me, I need your complete and undivided attention. Come see me when you''re not otherwise occupied.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 32, 'dontknowyou_1', 'I think I''m going to head home.  I''m seeing things.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 33, 'npc_work_1', 'Was the datadisc delivered yet?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 34, 'npc_work_2', 'Is she safe yet? Wait. Have you even left yet?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 35, 'npc_work_3', 'Talia, it''s such an honor to mee...  Huh?  Where''s Talia?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 36, 'npc_breech_1', 'That was weird.  Did I just see that rock fly past me? Hmmm... must''ve been a mirage...'),
('string/en/static_npc/tatooine/aaph_koden.stf', 37, 'npc_breech_2', 'Help me kill this fool so we can find our target.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 38, 'npc_breech_3', 'Ummm... are you the person Aaph told me to wait for?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 39, 'notit_1', 'I thank you for offering me this, but I have nothing to give in return.  I can''t accept it.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 42, 'npc_backtowork_2', 'Oh, okay.  When you get rid of them, let me know.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 43, 'npc_backtowork_3', 'Hm... well, Force-sensitive people can be tricky.  When you find her again, bring her back here, okay?'),
('string/en/static_npc/tatooine/aaph_koden.stf', 44, 'npc_reset_2', 'Lose your courage somewhere along the way, did you? Oh well.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 45, 'npc_reset_3', 'I''m usually not surprised when people let me down, but I had really thought better of you.  Live and learn, I suppose.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 46, 'player_reset_2', 'No, I don''t want Vader coming after me. I''m leaving this one alone.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 47, 'player_reset_3', 'I''ve come back to tell you I''ve changed my mind.  I''m not interested in this anymore.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 48, 'player_sorry_2', 'Ummm... sorry.  I -um- had to use the ''fresher.  I''m leaving right now to get her.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 49, 'player_sorry_3', 'Um, she was here just a moment ago.  Let me go see if I can find where she went.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 52, 'npc_takeme_3', 'Hello again. I guess you''re here to bring me in for Jedi training. It still seems pretty farfetched to me. '),
('string/en/static_npc/tatooine/aaph_koden.stf', 54, 'dontknowyou_3', 'Oh, sorry.  Didn''t mean to disturb you.  Have a good day.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 106, 'npc_smuggle_1', 'Me? Force-sensitive? That''s pretty hard to believe. I guess I''d better check it out, though. Thanks.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 107, 'next', 'I don''t have anything else for you to do at the moment. Check back with me later.'),
('string/en/static_npc/tatooine/aaph_koden.stf', 108, 'notyet', 'I''m sorry, I only speak to Alliance...er...I''ve said too much already.'),
('string/en/static_npc/tatooine/binna_joad.stf', 1, 'npc_1_1', 'Stormtroopers attacked a Rebel base near here. Their fire went astray, as usual. They almost killed an innocent civilian family. I sent these folks to stay with a fellow I know, but they''re still very shaken. There''s not much I can do, but I do have a toy for the kids. Can you deliver it?'),
('string/en/static_npc/tatooine/binna_joad.stf', 2, 'npc_1_2', 'Some sleemo took a pot-shot at my favorite old guy, Gen Horosi. He''s a Clone Wars veteran, incredibly ancient but still sharp. I got some friends to help him get home, but he needs healing. I scraped together some credits and got a stimpack. Can you deliver it?'),
('string/en/static_npc/tatooine/binna_joad.stf', 3, 'npc_1_3', 'Friend of mine, Peele Noonal, just had her first child and -- oh, thanks, I''ll pass along your kind words -- and her nurse wrapped the baby in Peele''s shirt. Ever had a baby? Trust me, it does the shirt no good. I want you to take this shirt of mine to Peele as a maternity gift.'),
('string/en/static_npc/tatooine/binna_joad.stf', 5, 'npc_2_1', 'Real kind of you. Here''s the toy, such as it is. You got the coordinates? Good.'),
('string/en/static_npc/tatooine/binna_joad.stf', 6, 'npc_2_2', 'Thanks. You might not find Gen at home. Sometimes wanders out of town and has to be led back. Feisty old guy, but a good heart. Oh, don''t mention the Emperor, okay? It just gets him riled.'),
('string/en/static_npc/tatooine/binna_joad.stf', 7, 'npc_2_3', 'Great. Come on back and I''ll give you a drink on the house.'),
('string/en/static_npc/tatooine/binna_joad.stf', 8, 'npc_3_1', 'That''s all right. I''ll find someone who has the time. Thanks anyway.'),
('string/en/static_npc/tatooine/binna_joad.stf', 9, 'npc_3_2', 'That''s okay. You just sit back and get comfortable now.'),
('string/en/static_npc/tatooine/binna_joad.stf', 10, 'npc_3_3', 'Not a problem. We''ll take care of this somehow. Sit down, relax.'),
('string/en/static_npc/tatooine/binna_joad.stf', 12, 'npc_4_1', 'Well, I guess "toy" doesn''t really -- It''s a little fuel drum I cleaned up. Tried to decorate it with little drawings -- aww, it''s just to beat on, makes noise. It''s about all we can manage in Cheapside. What do you say to the delivery job?'),
('string/en/static_npc/tatooine/binna_joad.stf', 13, 'npc_4_2', 'Aw, nobody was gunning for him specifically. It was just some wild-eyed glitterstim druggie on a jaunt, blasting things and giggling. Happens too much around Cheapside. Can you help Gen?'),
('string/en/static_npc/tatooine/binna_joad.stf', 14, 'npc_4_3', 'The shirt is warm? Oh yeah, I guess that''s because I just took it off. Will you deliver it to Peele?'),
('string/en/static_npc/tatooine/binna_joad.stf', 15, 'npc_reward_1', 'Mighty nice of you. Those kids have already been through stuff -- well, it''s a tough life in Bestine, sometimes. Here, take a little something as a reward.'),
('string/en/static_npc/tatooine/binna_joad.stf', 16, 'npc_reward_2', 'That was real nice of you. Gen''ll be okay. He''s been through more than any squadron of stormtroopers. Here, I made this for you. Tasty.'),
('string/en/static_npc/tatooine/binna_joad.stf', 17, 'npc_reward_3', 'Thanks. Here, friend, have a drink on the house. Don''t drink it too fast, or your eyes will cross.'),
('string/en/static_npc/tatooine/binna_joad.stf', 18, 'player_1_1', 'I''ll do that for the little kids, yes.'),
('string/en/static_npc/tatooine/binna_joad.stf', 19, 'player_1_2', 'For a Clone Wars veteran, I''ll do anything!  Sure!'),
('string/en/static_npc/tatooine/binna_joad.stf', 20, 'player_1_3', 'Sounds simple enough.  Sure, I''ll do it.'),
('string/en/static_npc/tatooine/binna_joad.stf', 21, 'player_2_1', 'Sorry, I''m unavailable right now.'),
('string/en/static_npc/tatooine/binna_joad.stf', 22, 'player_2_2', 'Sorry, but I''m not interested in helping you with this.'),
('string/en/static_npc/tatooine/binna_joad.stf', 23, 'player_2_3', 'I''m a bit busy right now.  I''m sorry, but I can''t do that for you.'),
('string/en/static_npc/tatooine/binna_joad.stf', 24, 'player_3_1', 'What is the toy?'),
('string/en/static_npc/tatooine/binna_joad.stf', 25, 'player_3_2', 'Why did someone shoot at Gen Horosi?'),
('string/en/static_npc/tatooine/binna_joad.stf', 26, 'player_3_3', 'Why is this shirt warm?'),
('string/en/static_npc/tatooine/binna_joad.stf', 27, 'player_reset_1', 'I''ve been told that my friends need urgent help.  I can no longer deliver this toy.  Here.'),
('string/en/static_npc/tatooine/binna_joad.stf', 28, 'player_sorry_1', 'Sorry, I had something come up.  I''m off to deliver it right now.'),
('string/en/static_npc/tatooine/binna_joad.stf', 29, 'npc_backtowork_1', 'It''s really appreciated.  Make sure that you get to see the children''s faces when you give it to them.  I want to hear all about it.'),
('string/en/static_npc/tatooine/binna_joad.stf', 30, 'npc_reset_1', 'That''s all right. I''ll find someone who has the time. Thanks anyway.'),
('string/en/static_npc/tatooine/binna_joad.stf', 31, 'cantwork', 'Hello there. It''s good to see busy folks taking time out from the whirl at Cheapside Cantina. Glad to have you.'),
('string/en/static_npc/tatooine/binna_joad.stf', 32, 'dontknowyou_1', 'Oh, nevermind.  I thought you were a friend of Binna.  Well, be careful out there!'),
('string/en/static_npc/tatooine/binna_joad.stf', 33, 'npc_work_1', 'Didn''t expect to see you back so soon.  Were you able to deliver the toy to the kids?'),
('string/en/static_npc/tatooine/binna_joad.stf', 34, 'npc_work_2', 'You''re back quick.  Did you forget something?'),
('string/en/static_npc/tatooine/binna_joad.stf', 35, 'npc_work_3', 'So, how did she like the shirt?'),
('string/en/static_npc/tatooine/binna_joad.stf', 36, 'npc_breech_1', 'Are you Binna''s friend?'),
('string/en/static_npc/tatooine/binna_joad.stf', 37, 'npc_breech_2', 'You there!  You aren''t one of them Confederation guys, are you?  The war is over, so put down your weapons.  Eh?  What was that?'),
('string/en/static_npc/tatooine/binna_joad.stf', 38, 'npc_breech_3', 'How are you doing today?  It''s looking like we might be in for a bit of a sandstorm, don''t you think?'),
('string/en/static_npc/tatooine/binna_joad.stf', 42, 'npc_backtowork_2', 'Oh, that''s not a problem.  He doesn''t put on airs about it.  Just greet him like you would any other person.'),
('string/en/static_npc/tatooine/binna_joad.stf', 43, 'npc_backtowork_3', 'That''s mighty considerate of you.  I trust you''ll get it to her safely.'),
('string/en/static_npc/tatooine/binna_joad.stf', 44, 'npc_reset_2', 'That''s okay. You just sit back and get comfortable now.'),
('string/en/static_npc/tatooine/binna_joad.stf', 45, 'npc_reset_3', 'Not a problem. We''ll take care of this somehow. Sit down, relax.'),
('string/en/static_npc/tatooine/binna_joad.stf', 46, 'player_reset_2', 'I just found out my mother is in the Hospital.  I need to go to her.  Could you have someone else deliver the stimpack?'),
('string/en/static_npc/tatooine/binna_joad.stf', 47, 'player_reset_3', 'I don''t think I''m suited to giving shirts to new mothers.  I''m sorry, but I can''t do this anymore.'),
('string/en/static_npc/tatooine/binna_joad.stf', 48, 'player_sorry_2', 'I''m not too sure how to speak to a Clone Wars vet.  I don''t want to treat him with less respect than he deserves.'),
('string/en/static_npc/tatooine/binna_joad.stf', 49, 'player_sorry_3', 'Oh, I haven''t given it to her yet.  There was a sandstorm and I didn''t want it to get dirty.'),
('string/en/static_npc/tatooine/binna_joad.stf', 53, 'dontknowyou_2', 'Huh?  I thought you were one of them droids.  Ah, nevermind.'),
('string/en/static_npc/tatooine/binna_joad.stf', 54, 'dontknowyou_3', 'Well, you have yourself a good day, you hear?  And don''t get caught when the wind starts to blow.'),
('string/en/static_npc/tatooine/binna_joad.stf', 55, 'dontknowyou_4', 'Ha hooey!  You not the one.  Ho yahaa!  I don''t have things to say to you now.  Habba hodie!'),
('string/en/static_npc/tatooine/binna_joad.stf', 61, 'npc_1_4', 'I got this datadisk from a friend on Corellia. May say something about  my husband. He went missing years back. A friend who looked for him sent this report, but the data got corrupted. Can you take it to a data slicer friend of mine?'),
('string/en/static_npc/tatooine/binna_joad.stf', 64, 'npc_2_4', 'Thanks. Fella named Dinnis the Blade. Nice enough guy, a little wild. Don''t stand too close to him, he doesn''t believe in using water.'),
('string/en/static_npc/tatooine/binna_joad.stf', 67, 'npc_3_4', 'No problem, friend. Have a drink, kick back, relax.'),
('string/en/static_npc/tatooine/binna_joad.stf', 70, 'npc_4_4', 'He was piloting a cargo freighter on the Corellia Route. Ran into pirates and had to make a wild jump through hyperspace. It''s been years, but I never gave up hope. I''ve stayed in this dive ever since, just on the chance he''d make it back here. If I left, he''d never find me.'),
('string/en/static_npc/tatooine/binna_joad.stf', 73, 'npc_backtowork_4', 'I''ve been waiting all these years, I don''t think a little more will hurt.  Let me know when he''s found something.'),
('string/en/static_npc/tatooine/binna_joad.stf', 76, 'npc_breech_4', 'Wee hoo!  Are you the one that Binna say is coming to me?  Hoo yehaa!'),
('string/en/static_npc/tatooine/binna_joad.stf', 79, 'npc_reset_4', 'No problem, friend. Have a drink, kick back, calm down and relax.'),
('string/en/static_npc/tatooine/binna_joad.stf', 82, 'npc_reward_4', 'That -- that''s -- oh. All right, time for an old lady to sit down. He''s really -- Okay. I''m all right now. Thank you. Here, take this, it''s tasty. I think I want to be alone now. Alone with my dreams.'),
('string/en/static_npc/tatooine/binna_joad.stf', 88, 'npc_work_4', 'So... is he still alive?'),
('string/en/static_npc/tatooine/binna_joad.stf', 91, 'player_1_4', 'Absolutely.  This is the least I can do for you.'),
('string/en/static_npc/tatooine/binna_joad.stf', 94, 'player_2_4', 'Sorry, I can''t so this.  I think you should do it yourself, Binna.'),
('string/en/static_npc/tatooine/binna_joad.stf', 97, 'player_3_4', 'What happened to your husband?'),
('string/en/static_npc/tatooine/binna_joad.stf', 100, 'player_reset_4', 'This is too emotional for me.  I can''t handle it anymore.  Get someone else to do this.'),
('string/en/static_npc/tatooine/binna_joad.stf', 103, 'player_sorry_4', 'I''m not sure yet.  Your slicer friend is -uh-  still working on it.'),
('string/en/static_npc/tatooine/binna_joad.stf', 106, 'npc_smuggle_1', 'Unfortunately, the family got called away when one child had to go into the bacta tanks. Thank you anyway. I''ll take the toy to the children.'),
('string/en/static_npc/tatooine/binna_joad.stf', 107, 'npc_smuggle_2', 'I don'' need no stimpack! I ain''t hardly hit. Can''t take me out that easy -- easy -- hol'' on, lemme get my breath back -- wuzzat? Stimpack? Whyn''t you say so, junior? Give it over. What? What? Sorry, don'' hear so good nowadays.'),
('string/en/static_npc/tatooine/binna_joad.stf', 108, 'npc_smuggle_3', 'Is this for me? From Binna? She''s the nicest lady in the galaxy. Excuse me, I just put the baby to bed and I reeeally need some sleep.'),
('string/en/static_npc/tatooine/binna_joad.stf', 109, 'npc_smuggle_4', 'Hoo yeh! Gimme the dat, I know what it''s at. I do my magic, and -- Yee-eah! Seems Binna''s old man is alive. Some kind of distant signal from Wild Space. Bad engine and low fuel, but he''s flying home!'),
('string/en/static_npc/tatooine/binna_joad.stf', 110, 'next', 'You''re pretty handy to have around. Come and visit me from time to time, maybe I can find you more work later.'),
('string/en/static_npc/tatooine/binna_joad.stf', 111, 'gotowork', 'I don''t have time to chat anymore.  '),
('string/en/static_npc/tatooine/binna_joad.stf', 112, 'dontknowyou', 'Who are you!?!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 1, 'npc_1_1', 'I''m back home after touring with my band, the Dewback Ramblers. You know us? -- Well, never mind. Our slitherhorn player just arrived on Tatooine, but he got suckered by the old "free transport to Bestine" con game. He''s stranded in the desert and needs an escort. Can you help?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 2, 'npc_1_2', 'The Ommni Box player in our band is kind of a prankster. He travelled here to Tatooine using the wrong travel papers. I guess he never should have given his name as "Lord Vader." Anyway, the authorities are after him, so I need  you to bring him here safely. Okay?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 3, 'npc_1_3', 'Our mandoviol player is -- well, he''s a wonderful guy, really, but he has kind of an attitude about Imperials. When he arrived here, some Imperial Security Bureau agents questioned him. And he sort of, well, bit one. Now he''s on the run out in the desert. Can you bring him here?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 5, 'npc_2_1', 'Great! If you save him from being swallowed by some gorg, he''ll probably play you a command performance!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 6, 'npc_2_2', 'That''s great. Look for Mellaw Doowon, an Ithorian, one of those hammerheads. Quite a joker, Mellaw is. Good luck!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 7, 'npc_2_3', 'I knew I could count on you. Remember, look for a small Chadra Fan named Baze Joz. And please don''t bring the ISB with him!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 8, 'npc_3_1', 'Oh. Well, all right. Hope someone can help my friend.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 9, 'npc_3_2', 'Oh. Well, okay. I guess someone else will get this exciting assignment.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 10, 'npc_3_3', 'Oh no! I thought I could count on you. And it was likely to be pretty exciting, too.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 12, 'npc_4_1', 'His name''s Mixon Guncher. If you''ve heard of him, none of that stuff about his weird behavior is true. Well, not much. He does wear a lot of perfume. Anyway, will you help?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 13, 'npc_4_2', 'His name''s Mellaw Doowon. Once, right before a gig, he filled my kloo horn with foaming cleanser. The suds, the suds! He''s a real kidder. Can you bring him here, please?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 14, 'npc_4_3', 'He''s Baze Joz, only the smoothest mandoviol player in the Outer Rim! I''ve known Baze a long time, and no matter what anyone tells you, all those rumors are completely false. Will you escort him here?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 15, 'npc_reward_1', 'Is this Mixon? What has he done to his face now? Never mind. Please take this payment for your time. Hope the trip was exciting!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 16, 'npc_reward_2', 'Thanks, friend! After this, I expect Mellaw will restrain his natural good humor around stormtroopers. Other Dewback Ramblers are on the way, so I''ll offer you more excitement soon!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 17, 'npc_reward_3', 'Thanks, friend! I hope this is the last excitement the Dewback Ramblers see for a while. I can''t pay you in credits this time, or our gig won''t even cover the costs. I do have this old organ that none of us use anymore though. It''s yours if you can haul it out of here.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 18, 'player_1_1', 'Yes, I can help.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 19, 'player_1_2', 'Sure, I''ll go rescue the guy.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 20, 'player_1_3', 'As long as he doesn''t bite me too, sure.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 21, 'player_2_1', 'Sorry, I''ve got other things I need to do.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 22, 'player_2_2', 'That''s his own fault.  Sorry, I don''t tangle with Imperials.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 23, 'player_2_3', 'No, this guy sounds dangerous.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 24, 'player_3_1', 'Who is this slitherhorn player?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 25, 'player_3_2', 'Who is this musician?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 26, 'player_3_3', 'Who is the musician this time?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 27, 'player_reset_1', 'I just found out that I''m needed elsewhere.  You''ll need to ask someone else.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 28, 'player_sorry_1', 'Not yet.  I was getting some desert survival gear.  I''ll be leaving soon.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 29, 'npc_backtowork_1', 'Okay, that''s fine.  Let me know when you''ve brought him back.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 30, 'npc_reset_1', 'Oh. Well, all right. Hope someone can help my friend.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 31, 'cantwork', 'Hey, friend! I was hoping to talk to you, but I see you''re busy. You can check back later if you want some excitement.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 32, 'dontknowyou_1', 'I don''t know about you, but I could go for a nice, long snooze.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 33, 'npc_work_1', 'Have you left yet to pick him up?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 34, 'npc_work_2', 'Were you able to find him?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 35, 'npc_work_3', 'Did you have any problems with him?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 36, 'npc_breech_1', 'Oh, the trip has tired me out. I do feel faint'),
('string/en/static_npc/tatooine/blerx_tango.stf', 37, 'npc_breech_2', 'Hmph! You wanna talk about humans who can''t take a joke --!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 38, 'npc_breech_3', 'Ik-ik! I''m about ready to kill somebody! '),
('string/en/static_npc/tatooine/blerx_tango.stf', 42, 'npc_backtowork_2', 'Okay.  Let''s hope he hasn''t run afoul of those armored goons.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 43, 'npc_backtowork_3', 'He should be smooth with you as long as he knows I sent you.  Just let him know that, okay?'),
('string/en/static_npc/tatooine/blerx_tango.stf', 44, 'npc_reset_2', 'Oh. Well, okay. I guess someone else will get this exciting assignment.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 45, 'npc_reset_3', 'Oh no! I thought I could count on you. And it was likely to be pretty exciting, too.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 46, 'player_reset_2', 'I can''t find him, and I''m tired of looking.  I can''t help out anymore.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 47, 'player_reset_3', 'You know, this guy scares me.  I''m not going to be able to help after all.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 48, 'player_sorry_2', 'Nope.  I''m still looking, though.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 49, 'player_sorry_3', 'Not yet, I haven''t.  I''ll find out soon enough.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 50, 'npc_takeme_1', 'Smooth. We must locomote, friend -- I believe the wild things here like my perfume.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 51, 'npc_takeme_2', 'I was just about to turn myself in and claim I''m the Emperor in disguise. That probably wouldn''t have worked, I guess. Let''s vamoose!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 52, 'npc_takeme_3', 'Well, not you, not if Blerx sent you. I''ll just watch you do the killing.  Take it away, maestro!'),
('string/en/static_npc/tatooine/blerx_tango.stf', 53, 'dontknowyou_2', 'Well, I don''t.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 54, 'dontknowyou_3', 'Not you, of course.  I was just making an example.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 55, 'next', 'It''s been a pleasure, friend. Maybe I can find more work for you later.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 56, 'notyet', 'I''m sorry. I''d love to chat with you, but you seem a bit too, um...Imperial?  Or maybe not. It''s hard for me to tell, but you''re definitely not the kind of person who could help me with my troubles.'),
('string/en/static_npc/tatooine/blerx_tango.stf', 57, 'npc_failure', 'He was killed? Oh no! This is terrible. What will happen to the band? I guess we have to cancel this gig.'),
('string/en/static_npc/tatooine/boshek.stf', 1, 'npc_1_1', 'I recently came into possession of a datadisc that would be of great interest to the Alliance. Care to handle the delivery for me?'),
('string/en/static_npc/tatooine/boshek.stf', 2, 'npc_1_2', 'I recently met an exceptional young lady. She may have certain -- gifts, if you take my meaning. I understand an Imperial stormtrooper is bringing her in for questioning. Would you mind escorting her here before the Imperials pick her up? '),
('string/en/static_npc/tatooine/boshek.stf', 3, 'npc_1_3', 'I recently hired someone to acquire some grenades. He accepted payment and got the grenades but has been reluctant to actually deliver them. I was wondering if you''d go get them from him?'),
('string/en/static_npc/tatooine/boshek.stf', 5, 'npc_2_1', 'I thought you might be interested. You have that on-the-go look about you. Bring this disc to Teng Winstel -- he''s one of my contacts in the Alliance. May the Force be with you, my friend. '),
('string/en/static_npc/tatooine/boshek.stf', 6, 'npc_2_2', 'That''s what I hoped you''d say. '),
('string/en/static_npc/tatooine/boshek.stf', 7, 'npc_2_3', 'Ah, I thought you might enjoy a bit of shadier work. I suppose it takes a rogue to spot one. Karn Wilder is your quarry. He''s not terribly trustworthy, but I never thought him so stupid as to cross me. '),
('string/en/static_npc/tatooine/boshek.stf', 8, 'npc_3_1', 'No problem. I''ll find someone else. Good luck to you.'),
('string/en/static_npc/tatooine/boshek.stf', 9, 'npc_3_2', 'Not your style, eh? Don''t worry about it, I''m sure somebody will be willing to help her.'),
('string/en/static_npc/tatooine/boshek.stf', 10, 'npc_3_3', 'I guess it was a bit much to ask of you. Forget I mentioned it.'),
('string/en/static_npc/tatooine/boshek.stf', 12, 'npc_4_1', 'I beat Han Solo''s Kessel Run speed record! Granted, I wasn''t hauling any cargo at the time, but it still counts. Now, about that job offer --'),
('string/en/static_npc/tatooine/boshek.stf', 13, 'npc_4_2', 'I mean that she may have some ability to use the Force. She''s already had some run-ins with the Empire, so I need a decision, if you please.'),
('string/en/static_npc/tatooine/boshek.stf', 14, 'npc_4_3', 'Well, yes. Technically that''s still true. It wasn''t me doing the smuggling, was it? I still occasionally help procure scarce items for the Alliance. I do have bills to pay, after all. Now, your decision?'),
('string/en/static_npc/tatooine/boshek.stf', 15, 'npc_reward_1', 'Well done, my friend. Thank you for your help. Feel free to see me again if you need more work. '),
('string/en/static_npc/tatooine/boshek.stf', 16, 'npc_reward_2', 'You''ve been a big help. We can''t let the Empire continue its wretched work. By all means, contact me again if you need more work.'),
('string/en/static_npc/tatooine/boshek.stf', 17, 'npc_reward_3', 'A stellar job, if I may say so. I''d say you have an impressive future ahead of you -- a much better place for the future than behind you, no?'),
('string/en/static_npc/tatooine/boshek.stf', 18, 'player_1_1', 'Sure, I''ve got nothing else to do.  Tell me what you need.'),
('string/en/static_npc/tatooine/boshek.stf', 19, 'player_1_2', 'Sure.  I''ll make sure she gets here before the Imperials get her.'),
('string/en/static_npc/tatooine/boshek.stf', 20, 'player_1_3', 'Sure, I''ll get them from him.'),
('string/en/static_npc/tatooine/boshek.stf', 21, 'player_2_1', 'No thanks.  I don''t want to get conned by some ''reformed smuggler''.'),
('string/en/static_npc/tatooine/boshek.stf', 22, 'player_2_2', 'Sorry, but that''s not my type of work.'),
('string/en/static_npc/tatooine/boshek.stf', 23, 'player_2_3', 'No, I''m not mixing myself up with explosives.  Sorry.'),
('string/en/static_npc/tatooine/boshek.stf', 24, 'player_3_1', 'Why would I have heard of you?'),
('string/en/static_npc/tatooine/boshek.stf', 25, 'player_3_2', 'What do you mean, "gifts"?'),
('string/en/static_npc/tatooine/boshek.stf', 26, 'player_3_3', 'Why grenades? Didn''t you say you weren''t a smuggler any more?'),
('string/en/static_npc/tatooine/boshek.stf', 27, 'player_reset_1', 'I''m sorry, but I didn''t know this had to do with the Rebellion.  I can''t do this for you anymore.'),
('string/en/static_npc/tatooine/boshek.stf', 28, 'player_sorry_1', 'Not yet.  I''m about to meet up with him soon.'),
('string/en/static_npc/tatooine/boshek.stf', 29, 'npc_backtowork_1', 'He doesn''t have all day.  Could you please hurry?'),
('string/en/static_npc/tatooine/boshek.stf', 30, 'npc_reset_1', 'No problem. I''ll find someone else. Good luck to you.'),
('string/en/static_npc/tatooine/boshek.stf', 31, 'cantwork', 'I''m sorry, friend. It seems you still have unfinished work. Seek me out when your job is completed.'),
('string/en/static_npc/tatooine/boshek.stf', 32, 'dontknowyou_1', 'Sorry, but I''m waiting for a friend.'),
('string/en/static_npc/tatooine/boshek.stf', 33, 'npc_work_1', 'So, did Teng get the package yet?'),
('string/en/static_npc/tatooine/boshek.stf', 34, 'npc_work_2', 'Were you able to save her in time?'),
('string/en/static_npc/tatooine/boshek.stf', 35, 'npc_work_3', 'So, were you able to get the grenades from him?'),
('string/en/static_npc/tatooine/boshek.stf', 36, 'npc_breech_1', 'Are you the one with this ''important'' package I''m supposed to wait for?'),
('string/en/static_npc/tatooine/boshek.stf', 37, 'npc_breech_2', 'Okay... I''m reaching out with my mind...'),
('string/en/static_npc/tatooine/boshek.stf', 38, 'npc_breech_3', 'You''re not getting anything from me. Die!');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/boshek.stf', 41, 'notit_3', 'I said grenades, friend.  I don''t know what this is, but it''s sure not a case of grenades.'),
('string/en/static_npc/tatooine/boshek.stf', 42, 'npc_backtowork_2', 'Okay, but you may not have much time left.  Please hurry.'),
('string/en/static_npc/tatooine/boshek.stf', 43, 'npc_backtowork_3', 'Hmph.  You could''ve just said you hadn''t got around to it yet.  Let me know when you have, okay?'),
('string/en/static_npc/tatooine/boshek.stf', 44, 'npc_reset_2', 'Not your style, eh? Don''t worry about it, I''m sure somebody will be willing to help her.'),
('string/en/static_npc/tatooine/boshek.stf', 45, 'npc_reset_3', 'I guess it was a bit much to ask of you. Forget I mentioned it.'),
('string/en/static_npc/tatooine/boshek.stf', 46, 'player_reset_2', 'You know, I don''t want to get involved with this ''Force'' stuff.  Sorry, but I''m no longer interested.'),
('string/en/static_npc/tatooine/boshek.stf', 47, 'player_reset_3', 'I''m actually a bit afraid of grenades.  What if he throws one at me?  I can''t do this after all.'),
('string/en/static_npc/tatooine/boshek.stf', 48, 'player_sorry_2', 'Not yet.  I was making sure there was a safe way out of there first.'),
('string/en/static_npc/tatooine/boshek.stf', 49, 'player_sorry_3', 'Ummm... he hid them, and... ummm... I just found out where.  I''m going to get them right now.'),
('string/en/static_npc/tatooine/boshek.stf', 51, 'npc_takeme_2', 'I''m not sure why people think I have a connection with the Force. Ever since that idea got around, my life has been lots more interesting.'),
('string/en/static_npc/tatooine/boshek.stf', 53, 'dontknowyou_2', 'Huh?  Oh, sorry about that.  I''m... um... practicing a role for an audition.'),
('string/en/static_npc/tatooine/boshek.stf', 54, 'dontknowyou_3', 'What?  You''re not dead?  Hmm... I''ll have to work on that a little more.'),
('string/en/static_npc/tatooine/boshek.stf', 106, 'npc_smuggle_1', 'I wonder what BoShek''s found now? He does infiltrate himself into the most unusual situations. Thanks. '),
('string/en/static_npc/tatooine/boshek.stf', 107, 'next', 'Maybe I can find you some more work later. Take care of yourself.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 1, 'npc_1_1', 'You''d help a girl like me? Isn''t that sweet. Turns out, I do need something delivered to a business associate. Well, a future business associate, I hope. Think you can handle a simple delivery?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 2, 'npc_1_2', 'I like your enthusiasm. But the task I have in mind is slightly more perilous. A dear friend of mine has fallen in with the wrong crowd and is in desperate need of rescuing. This might be a bit too dangerous for the average mercenary. You sure you want in?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 3, 'npc_1_3', 'I confess I''ve gotten used to you coming to my "rescue." However, I just have one last little thing for you to do and then I''ll let someone else enjoy your talents. I need a particular warehouse taken out. And when I say that, I mean burned to the ground. I know that sounds simply awful. Think you can do it anyway?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 5, 'npc_2_1', 'I knew this would be no problem for a tough-looking mercenary like you. Take this encrypted datadisc to Lam Bregaani, a Sullustan swoop jockey whose career I''ve been following closely these last few months. If he asks, tell him that everything has been taken care of.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 6, 'npc_2_2', 'I knew you were made of sterner stuff. My friend''s name is Idee Zipbits. He''s a Chadra-Fan swoop jockey. Not terribly brave, but pretty good in a race. If you bring him back here, I''d show an appropriate amount of gratitude.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 7, 'npc_2_3', 'I knew you''d come through for me! Now just to give you a heads-up, there might be some undesirable elements loitering around the warehouse. They''re most likely cutthroats so just blast them.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 8, 'npc_3_1', 'It''s not nice to feign interest in my affairs then refuse to help. Nobody likes a tease. '),
('string/en/static_npc/tatooine/brea_tonnika.stf', 9, 'npc_3_2', 'I understand, although I am a bit disappointed. I thought there was something extraordinary about you.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 10, 'npc_3_3', 'Now you''ve gone and made me all pouty. I hope you enjoy toying with my emotions. Soon a girl won''t know whom to trust.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 12, 'npc_4_1', 'A proposition. Of the business variety, of course. But one so compelling that I think my future partner will not be able to refuse it. Still interested?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 13, 'npc_4_2', 'I''m afraid that Lady Valarian has taken an unhealthy interest in my friend''s affairs. That Whiphid is not someone you want to cross. Is it?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 14, 'npc_4_3', 'Just some speeder parts and gadgets. Perhaps an old swoop racer or two. It''s an eyesore, really. I''m sure no one will be sad to see it go.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 15, 'npc_reward_1', 'I''m much obliged, citizen. Hope you didn''t have too much trouble on the way. Oh, and Lam has a very vivid imagination. Kindly disregard anything he might have said. One too many crashes can addle a swoop jockey''s mind.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 16, 'npc_reward_2', 'You''ve brought Idee back all in one piece. I knew I could count on you! Now allow a girl to show her appreciation. Take this and enjoy yourself.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 17, 'npc_reward_3', 'I gotta hand it to you, friend, you''re one tough sand panther. Thanks for all your help. I think my business venture will go quite smoothly now. Take care.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 18, 'player_1_1', 'Sure, I can do it.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 19, 'player_1_2', 'Count me in!'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 20, 'player_1_3', 'I''ll see to it that there is only smoke and debris when I''m done.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 21, 'player_2_1', 'No thanks.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 22, 'player_2_2', 'In that case, no thank you.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 23, 'player_2_3', 'Not thanks.  Arson isn''t my style.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 24, 'player_3_1', 'What would I be delivering?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 25, 'player_3_2', 'Who has your friend fallen in with?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 26, 'player_3_3', 'What''s in the warehouse?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 27, 'player_reset_1', 'Sorry, but something came up.  I can''t do this for you anymore.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 28, 'player_sorry_1', 'I don''t know.  I haven''t talked to him yet.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 29, 'npc_backtowork_1', 'Well, don''t be a tease, friend. He''s waiting for you as we speak.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 30, 'npc_reset_1', 'It''s not nice to feign interest in my affairs then refuse to help. Nobody likes a tease. '),
('string/en/static_npc/tatooine/brea_tonnika.stf', 31, 'cantwork', 'I''m a very demanding patron. Come back when you''ve less on your plate.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 32, 'dontknowyou_1', 'Who are you?  Are you some kind of promoter?  If not, get out of my face.  I''ve got... things to do, I guess.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 33, 'npc_work_1', 'Did Lam have anything... positive... to say?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 34, 'npc_work_2', 'Have you been able to convince Idee to come with you?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 35, 'npc_work_3', 'Have you demolished the place yet?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 36, 'npc_breech_1', 'This better not be some kind of trick.  It''s not like I have anything better to do, but still.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 37, 'npc_breech_2', 'Help!  Help!'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 42, 'npc_backtowork_2', 'I am hoping you will be able to do so in a much quicker fashion.  You wouldn''t want to upset me, would you?'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 43, 'npc_backtowork_3', 'That''s why I''ve chosen you.  You strike me as someone who is a consumate professional.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 44, 'npc_reset_2', 'I understand, although I am a bit disappointed. I thought there was something extraordinary about you.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 45, 'npc_reset_3', 'Now you''ve gone and made me all pouty. I hope you enjoy toying with my emotions. Soon a girl won''t know whom to trust.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 46, 'player_reset_2', 'I''ve changed my mind.  I don''t want to do this after all.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 47, 'player_reset_3', 'Count me out.  I''m not too keen on the idea of arson.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 48, 'player_sorry_2', 'Not yet, but he''ll understand in time.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 49, 'player_sorry_3', 'No, I''m still making the explosives.  This takes time.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 51, 'npc_takeme_2', 'Help! I''ll do whatever the Tonnika sisters want! Just save me from these killers!'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 53, 'dontknowyou_2', 'Oh, thank you!  I''ll do what they say next time!'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 106, 'npc_smuggle_1', 'If these bank codes are valid, then I''ll be sure to "crash" on the second lap of the race. Make sure your boss has my transport off this rock ready to go.'),
('string/en/static_npc/tatooine/brea_tonnika.stf', 107, 'next', 'Not bad at all. I''ll consider using you again in the future.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 1, 'npc_1_1', 'Well, hey! I guess you''re new to Mos Taike. Welcome - or maybe sympathies, given that this is a backwater town on the galaxy''s backwater-iest world. But even here, one person can make a difference. In fact, I''m looking for someone to go after a local crook. Can you handle a fight?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 2, 'npc_1_2', 'Hey, hello again! Kli Sithrin is in town, that big Zabrak gangster in -- Anchorhead, I think. He stole a medpack right out of a little girl''s hand. Doesn''t that make your blood burn? If you take this guy out of circulation, I''ll cheer you on. Bring me the medpack, and I''ll give it back to the little girl. Okay?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 3, 'npc_1_3', 'Look at you, you''re back! Seems like every time I see you, I have trouble to report. Jespral Farandan, a big figure in an offworld terrorist ring, is hiding out near here. Best hideout in the galaxy, really. But he''s planning a new attack, and he has information crucial to our defenses, so it would be great if you could stop him, okay?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 5, 'npc_2_1', 'That''s great! Remember, this Aqualish - one of those tusk-faced guys - stole a shield generator. He may be using it for defense, so let fly with everything you''ve got. Bring back the generator, okay?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 6, 'npc_2_2', 'Hey, that''s really friendly. Look for a tough Zabrak with orange skin and slashing tattoos on his face. Even his horns have got horns, they say, so watch out. Bring the medpack back here.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 7, 'npc_2_3', 'That''s great. This Farandan - I should warn you, he''s wearing a Rebel Alliance uniform. But trust me, he''s not a Rebel. Hey, I''m not trying to start a political discussion here; he''s just not, that''s all. If you find a datadisk on him, you''ll bring that back here, right?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 8, 'npc_3_1', 'Okay, I just wanted to ask. Enjoy your stay in our little place.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 9, 'npc_3_2', 'Well, you know how to use your time better than I do. See you around, friend.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 10, 'npc_3_3', 'Not a problem, friend. You can find plenty of useful things to do around here without my help.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 12, 'npc_4_1', 'His name''s Thark. He''s a rude, obnoxious Aqualish - not to be redundant - and he''s a menace to free people in this town.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 13, 'npc_4_2', 'I couldn''t tell you. Maybe he just wanted to show off. These Anchorhead gangsters like to mark their territory, just like a womp rat.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 14, 'npc_4_3', 'If you start believing crooks, you''ll never get justice. If you''re uncomfortable taking down the folks who make this galaxy unsafe - and I guarantee that''s who you''re fighting - then say "No." So, friend, what''s your answer?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 15, 'npc_reward_1', 'Excellent, friend! I''m glad you see we all have to work together for our safety and freedom. I''d like to reward you with money, but I''m just a junior officer. Here, my sister made this casserole. It''s delicious!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 16, 'npc_reward_2', 'Thanks, that was fine work. Did Sithrin say anything? Well, when you corner these gangsters, they''ll try everything. Did you like my sister''s casserole? Try her soup. Takes a while to make, but mmm, worth it!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 17, 'npc_reward_3', 'That''s another favor I owe you, friend. I wouldn''t put any stock in anything that fellow said; you know these crooks, after all. I wonder if you''d like some fresh flatbread my sister just brought? Have to eat it quick, or it goes all greasy.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 18, 'player_1_1', 'Sure I can handle a fight!  Point me at him!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 19, 'player_1_2', 'I can''t stand by and watch a little girl have her medicine stolen.  I''ll get it back for her!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 20, 'player_1_3', 'I''ll gladly help you stop this terrorist!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 21, 'player_2_1', 'No, I''m not one for fighting.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 22, 'player_2_2', 'A gangster?  No, I''m not getting involved with that kind of trouble.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 23, 'player_2_3', 'No, I think this is better handled by you.  I''d just wind up getting killed.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 24, 'player_3_1', 'Who is this local crook?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 25, 'player_3_2', 'Why did Kli Sithrin steal the medpack?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 26, 'player_3_3', 'Is this one really a gangster? The others didn''t talk like crooks.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 27, 'player_reset_1', 'I''m not able to handle this guy right now.  Could I track him down later?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 28, 'player_sorry_1', 'Not yet, but I''m working on it.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 29, 'npc_backtowork_1', 'Well, try to get it back from him soon.  He''s probably looking to sell it to make some quick credits, so we might not have much time.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 30, 'npc_reset_1', 'Well, I guess so.  Let''s hope he doesn''t sell that generator to some Jawas in the meantime, though.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 31, 'cantwork', 'Welcome to Mos Taike, friend.  I hope you enjoy our settlement while your here.  When you''re not busy, why don''t you stop by.  I could use someone like you.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 32, 'dontknowyou_1', 'I don''t know who you are or what you want, but I''m not the guy you''re looking for.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 33, 'npc_work_1', 'So, have you managed to round up that Aqualish and recover the generator yet?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 34, 'npc_work_2', 'So, do you have the medpack yet?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 35, 'npc_work_3', 'So, have you managed to put a stop to him and gather that datadisc?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 36, 'npc_breech_1', 'Don''t attack, you stupid lout, I''m an Imperial informant! I confiscated this generator from an insipid thief before it reached the Rebels. I - argh, never mind, I''d rather kill you!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 37, 'npc_breech_2', 'That''s close enough. What brings you here? A stolen medpack? I stole no medpack. If you must know, I''m meeting here with an ISB official. Hold on, I told you an Imperial secret. Now I suppose I''ll have to kill you. Mangler - attack!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 38, 'npc_breech_3', 'So. I must say, those Rebel scum found me out remarkably quickly. I''m about to make my first report to the ISB. In it I shall recount your death.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 39, 'notit_1', 'This isn''t what the Aqualish stole.  I''m only interested in that.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 40, 'notit_2', 'No, she has a special medicine she needs for her breathing.  Sadly, only the one that Sithrin has will help the girl.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 41, 'notit_3', 'No, this isn''t the datadisk.  I''m only interested in seeing that Farandan is dead and his datadisk is in safe hands.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 42, 'npc_backtowork_2', 'Well, try to get it done fast.  Her mother let me know her breathing is getting more and more shallow as time passes.  She needs that medicine real bad like.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 43, 'npc_backtowork_3', 'Well, let''s hope you''re able to find him before he enacts his latest dastardly plot.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 44, 'npc_reset_2', 'Sure, I understand.  I do hope that little girl doesn''t get any sicker in the meantime, though.  That sure would be a shame, wouldn''t you agree?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 45, 'npc_reset_3', 'Well, I don''t want you to get yourself killed.  I''ll try to find someone else to stop him before it''s too late for us all.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 46, 'player_reset_2', 'Bren, I''m not able to get to Kli Sithrin just yet.  Would you mind if I recovered it later?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 47, 'player_reset_3', 'I don''t think I''ll be able to stop him, or get that datapad.  You might want to send someone else to do it.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 48, 'player_sorry_2', 'Not yet, but I''m going to get that medpack back for her.  I promise!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 49, 'player_sorry_3', 'No, not yet, but when I do, I''ll make sure to get it to you right away!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 53, 'dontknowyou_2', 'Hey.  Who''re you?  Do I know you?  No, I don''t.  And let''s keep it that way, okay?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 54, 'dontknowyou_3', 'Are you my Imperial contact?  Hmmm... no, you''re not the person I''m here to meet.  Sorry, I have nothing to say to you.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 55, 'dontknowyou_4', 'You aren''t the repair engineer I''m waiting for.  If you see him, you tell him I''m waiting, and the longer I wait, the more sense I''ll beat into him.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 56, 'notit_4', 'Hmmmm... no, I don''t think this is something Thanamiroc would have had on him.  Bring back something that would identify him.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 57, 'npc_1_4', 'Hey, you''re riding to my rescue yet again, friend. Word comes down from Mos Eisley that a known murderer and master of disguise, Trone Thanamiroc, is on another homicidal killing spree. He hijacked a vehicle and is rampaging around. Someone has to stop him, but I''m stuck here. Can you handle a tough target? '),
('string/en/static_npc/tatooine/bren_kingal.stf', 58, 'npc_2_4', 'Good! The Mos Eisley office planted a homing beacon on his vehicle, so you should be able to find him. Be sure to bring back proof of his defeat, like his helmet or something. For once I can promise you a terrific reward!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 59, 'npc_3_4', 'I was afraid you were going to say that. This troublemaker has been terrorizing folks across Tatooine. But okay, friend, we''ll take him out somehow.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 60, 'npc_4_4', 'Hey, Thanamiroc can look like anything. Farmers, Sand People, Imperial soldiers, Rebels, baby banthas, you name it. Just kidding about the banthas. Whatever he looks like, he''s always trouble. What do you say?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 61, 'npc_backtowork_4', 'Well, you''ll want to do it soon, or you''ll wind up tracking him down by his trail of dead bodies he''ll leave in his wake.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 62, 'npc_breech_4', 'Finally you''re here. Get this thing running, imbecile, or I''ll have you beaten senseless. Wait - you''re no repair engineer! A trap!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 63, 'npc_reset_4', 'Well, I''m sorry to hear you can''t handle this one.  Then again, I don''t blame you; this guy is vicious.  I''ll look into hiring a Bounty Hunter.  I just hope I have enough credits to afford the best.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 64, 'npc_reward_4', 'Thanamiroc was passing himself off as a bounty hunter, eh? That''s an ironic twist - wonder if he could have collected a bounty on himself. Ha! Hey, thanks again. Here''s the best reward you''ll find in Mos Taike: my sister''s specialty! Don''t show it around, or everyone will want a slice.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 65, 'npc_work_4', 'Have you put an end to Thanamiroc''s reign of terror?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 66, 'player_1_4', 'I can handle this guy.  Point me at him!'),
('string/en/static_npc/tatooine/bren_kingal.stf', 67, 'player_2_4', 'No, he sounds too dangerous for me.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 68, 'player_3_4', '"Master of disguise"? What''s he dressed like?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 69, 'player_reset_4', 'I''m sorry, but this guy is too dangerous for me.  I think you need to send someone else to do it.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 70, 'player_sorry_4', 'Not yet, but when I do, I''ll be sure to bring back proof that he''ll no longer hurt anyone else.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 71, 'next', 'You have a talent for this. Maybe I''ll have more work for you in the future.'),
('string/en/static_npc/tatooine/bren_kingal.stf', 72, 'npc_failure_1', 'I feel bad for sending you out to get hurt like that.  Better luck next time, eh?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 73, 'npc_failure_2', 'That poor little girl.  What''s she going to do without that medpack?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 74, 'npc_failure_3', 'Man I knew that guy was trouble.  Sorry you couldn''t handle it.  Maybe I should have gone myself?'),
('string/en/static_npc/tatooine/bren_kingal.stf', 75, 'npc_failure_4', 'Wow.  I really thought you could handle that.  Guess I was wrong, huh?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 1, 'npc_1_1', 'Eventually they all come ''round here looking for work, so I don''t see why you should be any different. Yeah, I got something for you to do, but it''ll require a strong stomach and nerves of durasteel. This ain''t for the squeamish. You still interested?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 2, 'npc_1_2', 'Eager for more work, huh? Ambitious little scoundrel, ain''t ya? Okay, I got something else for ya. One of my enforcers has decided he doesn''t need me anymore and has gone into business for himself. I need you to show him that without me he has no future. And yeah, that means blast the slug into space dust.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 3, 'npc_1_3', 'Of course I have something for you to do! Here''s the deal: I bought some, uh, merchandise from a dumb thug named Ripper. I paid fair market price, but now he''s tryin'' to twist my arm for more credits. I need you to make this problem go away. Ripper''s a known gangster and responsible for many deaths, so you can consider this a public service.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 5, 'npc_2_1', 'Let''s see what you''re made of, pal. A Rodian thief that goes by the name Greenfinger is trying to skip town without paying his debts to me. That ain''t acceptable. I need you to track this loser down and make an example of him. You can keep whatever he''s carrying as a tip. Just make sure his passing is violent and painful.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 6, 'npc_2_2', 'That''s what I was hoping you''d say. You''re shaping up to be my kind of enforcer. Now go out there and teach that Aqualish he shouldn''t mess with Farious Gletch! Use caution, he may have some friends with him.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 7, 'npc_2_3', 'Now that''s the enforcer I''ve come to know and love! Just remember, this worm is dangerous. Don''t take any chances. Blast him as soon as you see him! '),
('string/en/static_npc/tatooine/farious_gletch.stf', 8, 'npc_3_1', 'I figured you for one of those squeamish types. I ain''t got use for beings like you. Beat it!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 9, 'npc_3_2', 'What''s wrong? You''re not afraid of a near-sighted Aqualish, are you? And here I thought you had guts and the ambition to rise quickly in my organization. Why do I keep trying?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 10, 'npc_3_3', 'Are you really backing out on me now? What a punk!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 12, 'npc_4_1', 'I need you to make a deadbeat disappear. Permanently. You still interested?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 13, 'npc_4_2', 'The brute''s an Aqualish named Gordul Koga. He''s one mean gundark so start blasting as soon as you see him. You''ll do it, right?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 14, 'npc_4_3', 'He''s one of Jabba''s murderous swoopers. And I don''t need to tell you how dangerous those slugs are, do I? Will you take this slime out of the gene pool or not?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 15, 'npc_reward_1', 'Now that was well handled, friend. Perhaps I misjudged you. I think you and I will get along just fine. Hehehe, yeah, just fine.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 16, 'npc_reward_2', 'You''re growing on me, buddy, you know that? You just keep removing these obstacles for me and your future will be prosperous.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 17, 'npc_reward_3', 'Ha, ha! I would love to have seen the look on old Ripper''s face when you introduced him to some blaster bolts! Oh, and if he claimed I never paid him, he lied. Do I look like the kinda guy that would try and cheat someone? On second thought, don''t answer that.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 18, 'player_1_1', 'Yeah, that''s my kind of job.  I''ll do it.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 19, 'player_1_2', 'Sure, I''ll do it.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 20, 'player_1_3', 'I''ll take him out of the picture for you.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 21, 'player_2_1', 'Nah, that doesn''t sound like something I want to do.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 22, 'player_2_2', 'No, that''s not my style.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 23, 'player_2_3', 'No, I''m not interested in doing this for you.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 24, 'player_3_1', 'What do I have to do?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 25, 'player_3_2', 'What does this enforcer look like?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 26, 'player_3_3', 'Tell me more about Ripper.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 27, 'player_reset_1', 'I''m not able to do this for you any longer.  Sorry.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 28, 'player_sorry_1', 'No, not yet.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 30, 'npc_reset_1', 'I figured you for one of those squeamish types. I ain''t got use for beings like you. Beat it!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 31, 'cantwork', 'When I hire someone, I expect his or her full attention. Come back when you''re ready to talk business.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 32, 'dontknowyou_1', 'Get out of here, slug!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 33, 'npc_work_1', 'Have you done away with that Rodian yet?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 34, 'npc_work_2', 'Have you sent the ''message'' to Gordul yet?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 35, 'npc_work_3', 'Have you taken care of the gangster?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 36, 'npc_breech_1', 'Gletch sent you, didn''t he? I''ve dealt with your kind before. Just try and take me, slug!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 37, 'npc_breech_2', 'Think you can take me? Gordul will crush you!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 38, 'npc_breech_3', 'Gletch thinks he can cheat me? No one takes my glitterstim without paying for it! Die!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 42, 'npc_backtowork_2', 'I don''t have all day!  Get it done, or don''t do it at all!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 43, 'npc_backtowork_3', 'What are you waiting for!?  Kill him already!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 44, 'npc_reset_2', 'What''s wrong? You''re not afraid of a near-sighted Aqualish, are you? And here I thought you had guts and the ambition to rise quickly in my organization. Why do I keep trying?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 45, 'npc_reset_3', 'Are you really backing out on me now? What a punk!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 46, 'player_reset_2', 'I no longer have the time to take care of this ''problem'' for you.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 47, 'player_reset_3', 'I''ve changed my mind.  I''m not going to do this for you anymore.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 48, 'player_sorry_2', 'No, not yet!  I''m still working on it.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 49, 'player_sorry_3', 'Not yet.  I''m still getting around to it.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 53, 'dontknowyou_2', 'Gordul says get out of here!  Gordul doesn''t know you!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 54, 'dontknowyou_3', 'Nevermind.  I thought you were working for Farious.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 55, 'dontknowyou_4', 'Oh, sorry.  I thought you were someone else.  Nevermind.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 61, 'npc_1_4', 'You gotta stop a maniac from trying to bump off the Imperial Prefect! This killer is under the delusion that I''ve hired him! You gotta stop this madman before he gets us all killed! The Empire''s revenge will be swift and brutal if they think I..we had anything to do with this!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 64, 'npc_2_4', 'I knew you''d come through for me! You''re a lifesaver, pal! The lunatic goes by the name of "Professor Whisper." Yeah, yeah, I know - but what do you expect from an insane assassin? Anyway, he''s a Bith and he''s deadly. Did I mention he was insane? Stop him before he brings down the wrath of the Empire on my head!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 67, 'npc_3_4', 'No? Did you just say no? You can''t say no! You gotta help me! Who else can I turn to? Please!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 70, 'npc_4_4', 'Maybe because he''s insane? And maybe I mentioned in passing, as a harmless comment to someone in the street, that this place would be better off without the Prefect. But how was I supposed to know this Bith would overhear my conversation and take me seriously? I blame this mixup on their overly-acute hearing and an inability to take a joke!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 73, 'npc_backtowork_4', 'Well, hurry it up already!  I''m not paying you to waste my time!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 76, 'npc_breech_4', 'I''m a professional. If Gletch wanted the contract terminated, he should have contacted me. Now both of you will have to die.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 79, 'npc_reset_4', 'No? Did you just say no? You can''t say no! You gotta help me! Who else can I turn to? Please!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 82, 'npc_reward_4', 'Phew, you''re a lifesaver. Well, for me at least ,hehe. I don''t have anything else I need done right now. In fact, think I need a vacation to let things calm down some. Look me up when I get back and we''ll get back to business.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 88, 'npc_work_4', 'Has the ''Professor'' been put out of business?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 91, 'player_1_4', 'I''ll take care of it. Count on me.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 94, 'player_2_4', 'No, this is your mess, not mine.  Get someone else to clean it up.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 97, 'player_3_4', 'Why is this assassin under the impression that you hired him?'),
('string/en/static_npc/tatooine/farious_gletch.stf', 100, 'player_reset_4', 'I''ve thought about what I said earlier, and realize I meant to say ''No'' to doing this for you.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 103, 'player_sorry_4', 'No, he hasn''t been taken care of yet.'),
('string/en/static_npc/tatooine/farious_gletch.stf', 107, 'npc_backtowork_1', 'What am I paying you for!  Get it taken care of!'),
('string/en/static_npc/tatooine/farious_gletch.stf', 108, 'next', 'I don''t have anything for ya right now. Maybe later.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 1, 'npc_1_1', 'My night-time heart has cried, leaving with the day these discs of teardrops -- love letters to my sweetheart. Carry them to her. Carry my plea for affection and understanding.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 2, 'npc_1_2', 'A tendril of light reached down from the stars and touched my brow. In inspired fever I composed this song of love. Send it, carry it to the one who will most appreciate its feeling.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 3, 'npc_1_3', 'Seems I have a new fan. A storm-drenched spirit, drying and shriveling in these desert suns. He looks to me for guidance, but no. For this young spirit, I am too weak. I disappoint him. For that shriveling fan, this note of apology and hope, hand-delivered to him by you.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 5, 'npc_2_1', 'Dilta waits, she waits alone, out in that empty waste beneath a burning sky. Head out on those lonely old sands, my friend, my friend''s friend.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 6, 'npc_2_2', 'Out in the wide, wild desert, friend -- that is your destination. Free of prying eyes, understand me? Go. My song must fly to the right heart.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 7, 'npc_2_3', 'Go, my friend. Head out to that windblown sand, where my fan waits in a desolation of the spirit. Hurry, now.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 8, 'npc_3_1', 'Our roads diverge now, my friend, but chance may bring us back together once again.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 9, 'npc_3_2', 'We each must follow our own road, friend. Someday, perhaps, our paths may cross again. Farewell.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 10, 'npc_3_3', 'Not a problem, friend. Head down your road, I''ll head down mine, and maybe we''ll meet again.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 12, 'npc_4_1', 'Ahhh, Dilta. A sweet sultry voice, a cool finger on the brow, a single star''s gleam in a night-black eye -- that is Dilta. You''ll like her. Go ahead, take my little job.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 13, 'npc_4_2', 'Be smooth, my friend, and do not pry into affairs of the heart. Only this: Seek one called Bex, whose true feeling for this work you will see. Please, take this tiny task.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 14, 'npc_4_3', 'Just one more wounded spirit, like you and me. Lonesome, troubled folk fall into my music, get uplifted, get shaken. Like my music to them, that''s my fans to me -- they lift me up, they shake me down. My little task awaits your choice.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 15, 'npc_reward_1', 'Ahh, that Dilta -- she is the spirited one. But I am smooth. I calm the troubled wind. My lament will melt her icy heart. And you, my friend -- to you, as to Dilta, I owe more than this sad token may express.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 16, 'npc_reward_2', 'My friend, Bex Lobber carries a weight in his heart, and in his fist. Perhaps my little love-ditty will relieve both. I only wish I could pay you more, friend. And Bex too.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 17, 'npc_reward_3', 'Life, life. I''m going down that lonely road, smooth mover. I feel a pressing need to move on. Take this little something and move on, too.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 18, 'player_1_1', 'Sounds like you need help.  I''ll do it.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 19, 'player_1_2', 'I shall be your emmisary of love, Figrin!'),
('string/en/static_npc/tatooine/figrin_dan.stf', 20, 'player_1_3', 'Sure, I''ll give it to him.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 21, 'player_2_1', 'That sounds too personal.  No, I''d feel wierd doing it.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 22, 'player_2_2', 'You''re too wierd.  No, I won''t do this for you.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 23, 'player_2_3', 'I''m tired of talking to you.  No, do it yourself.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 24, 'player_3_1', 'Who is this "sweetheart"?'),
('string/en/static_npc/tatooine/figrin_dan.stf', 25, 'player_3_2', 'Who is receiving this love song?'),
('string/en/static_npc/tatooine/figrin_dan.stf', 26, 'player_3_3', 'Who is the fan who looks to you for guidance?'),
('string/en/static_npc/tatooine/figrin_dan.stf', 27, 'player_reset_1', 'I don''t like playing a go between.  You''ll have to do it yourself, afterall.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 28, 'player_sorry_1', 'Sorry, not yet.  I''ll make sure she gets them soon, though.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 29, 'npc_backtowork_1', 'My heart will fly long until it is held by that sweet Dilta.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 30, 'npc_reset_1', 'Our roads diverge now, my friend, but chance may bring us back together once again.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 31, 'cantwork', 'Ahh, you''re a busy one. I see, I know. Smooth your moves and relax, friend. Hark to the sounds. Check on back here when you''re free.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 32, 'dontknowyou_1', 'If you don''t know who I''m talking about, get away from me.  I don''t have time for you.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 33, 'npc_work_1', 'My protestations of deep emotion made it into her dear hands, I hope?'),
('string/en/static_npc/tatooine/figrin_dan.stf', 34, 'npc_work_2', 'The melodic tones have reached the heart and ears of the chosen, I hope?'),
('string/en/static_npc/tatooine/figrin_dan.stf', 35, 'npc_work_3', 'I''m hearing hearts shattering in the wind.  Is this the sound of my fan''s faith?'),
('string/en/static_npc/tatooine/figrin_dan.stf', 36, 'npc_breech_1', 'Are you one of that loser''s friends?  You look like one.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 37, 'npc_breech_2', 'If I find out that Bith suckered me, I''ll...'),
('string/en/static_npc/tatooine/figrin_dan.stf', 38, 'npc_breech_3', '*Snort*'),
('string/en/static_npc/tatooine/figrin_dan.stf', 42, 'npc_backtowork_2', 'The crystalline moons will weep when the harmony is heard.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 43, 'npc_backtowork_3', 'He''s waiting with his soul on his wing.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 44, 'npc_reset_2', 'We each must follow our own road, friend. Someday, perhaps, our paths may cross again. Farewell.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 45, 'npc_reset_3', 'Not a problem, friend. Head down your road, I''ll head down mine, and maybe we''ll meet again.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 46, 'player_reset_2', 'I don''t know what this is about, and I don''t want to do it anymore.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 47, 'player_reset_3', 'Okay, I''m done with you.  You are just way too mellow for me.  Do it yourself.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 48, 'player_sorry_2', 'Not yet.  I''ll get it to the... um... wherever I''m taking it.  So, be calm - or something like that.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 49, 'player_sorry_3', 'I don''t know what you just said.  If you mean ''Did he get the letter'', then - No, not yet.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 53, 'dontknowyou_2', 'Did it look like I was talking to you?  Look, get some people, then have them get in touch with mine.  Okay?'),
('string/en/static_npc/tatooine/figrin_dan.stf', 54, 'dontknowyou_3', '*Snork snork* *grunt*'),
('string/en/static_npc/tatooine/figrin_dan.stf', 106, 'npc_smuggle_1', 'This better be the credits from that deadbeat Figrin. Tell him this: Any guy who plays sabacc that bad needs better cash flow.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 107, 'npc_smuggle_2', 'I better have an exclusive distribution deal on this song, or I''ll jam that welsher''s big musician head into a really small hat.'),
('string/en/static_npc/tatooine/figrin_dan.stf', 108, 'npc_smuggle_3', 'Hnnnrrgh!'),
('string/en/static_npc/tatooine/figrin_dan.stf', 109, 'next', 'Perhaps one day fate will provide me with more work for you. Until that day my friend, farewell.'),
('string/en/static_npc/tatooine/fixer.stf', 1, 'npc_1_1', 'I just finished a repair, and I need someone to make the delivery for me. Whaddya say?'),
('string/en/static_npc/tatooine/fixer.stf', 2, 'npc_1_2', 'I cobble together lots of parts for moisture farmers. Some Tusken Raider is running around blasting any vaporators he comes across. You willing to find him and stop him from wrecking anything else?'),
('string/en/static_npc/tatooine/fixer.stf', 3, 'npc_1_3', 'My girlfriend, Camie, called. Her speeder hit an eopie in the desert. I need someone to bring her a new converter coil so she can get it running again. The speeder, not the eopie. Would ya mind bringing it to her quick?'),
('string/en/static_npc/tatooine/fixer.stf', 5, 'npc_2_1', 'Nice to see a little initiative for a change. A fellow named Vezz Kommani has been waiting on this power coupling. Take it to him out in the desert, away from prying Imperial eyes.'),
('string/en/static_npc/tatooine/fixer.stf', 6, 'npc_2_2', 'I know the folks ''round here would appreciate it. They''ve been a bit jumpy lately worrying about it. '),
('string/en/static_npc/tatooine/fixer.stf', 7, 'npc_2_3', 'I sure appreciate it. I don''t want her out there any longer than she has to be, so take this part and get moving.'),
('string/en/static_npc/tatooine/fixer.stf', 8, 'npc_3_1', 'Afraid of a little hard work, are ya? Too bad. Tosche Station''s got no place for lollygaggers. '),
('string/en/static_npc/tatooine/fixer.stf', 9, 'npc_3_2', 'I didn''t figure ya for the shy type. Shove off.'),
('string/en/static_npc/tatooine/fixer.stf', 10, 'npc_3_3', 'Kind of a heartless womp rat, aren''t ya? Get out of here!'),
('string/en/static_npc/tatooine/fixer.stf', 12, 'npc_4_1', 'Well, have you heard of Luke Skywalker?  Heck, yeah! We grew up together. I always knew he''d be something special. What a speeder pilot. Maybe that''s where you heard of me... no, it couldn''t have been that, could it?  But look, you interested in this job?'),
('string/en/static_npc/tatooine/fixer.stf', 13, 'npc_4_2', 'How should I know? Them Tuskens all hate our technology. I''d worry less about why, more about how ya might stop him.'),
('string/en/static_npc/tatooine/fixer.stf', 14, 'npc_4_3', 'Of course I have a girlfriend! What''s so hard to believe about that? Now, you want to help her or not?'),
('string/en/static_npc/tatooine/fixer.stf', 15, 'npc_reward_1', 'Ya done good. See me again if ya need more work. '),
('string/en/static_npc/tatooine/fixer.stf', 16, 'npc_reward_2', 'Way to work. That''ll be a load off everybody''s mind. Now try to hang on to a few of these credits this time, hear?'),
('string/en/static_npc/tatooine/fixer.stf', 17, 'npc_reward_3', 'Camie called -- she got home just fine. Thank you so much! If she had been eaten by that dewback, I don''t know what I would have done. I don''t have anything else I need help with right now, but check back later. Maybe something will come up.'),
('string/en/static_npc/tatooine/fixer.stf', 18, 'player_1_1', 'Sure.'),
('string/en/static_npc/tatooine/fixer.stf', 19, 'player_1_2', 'No problem.  I hate Tuskens with a seething passion.'),
('string/en/static_npc/tatooine/fixer.stf', 20, 'player_1_3', 'Sure, I''ll get it to your *ahem* girlfriend.'),
('string/en/static_npc/tatooine/fixer.stf', 21, 'player_2_1', 'No thanks.'),
('string/en/static_npc/tatooine/fixer.stf', 22, 'player_2_2', 'I usually leave well enough alone.  Let the Tusken do what he wants.'),
('string/en/static_npc/tatooine/fixer.stf', 23, 'player_2_3', 'Okay, now you''re making up stories.  I don''t believe you have a girlfriend, so I''m not going to help.'),
('string/en/static_npc/tatooine/fixer.stf', 24, 'player_3_1', 'Don''t I know you?'),
('string/en/static_npc/tatooine/fixer.stf', 25, 'player_3_2', 'Why is the Tusken destroying vaporators?'),
('string/en/static_npc/tatooine/fixer.stf', 26, 'player_3_3', 'Do you really have a girlfriend?'),
('string/en/static_npc/tatooine/fixer.stf', 27, 'player_reset_1', 'Sorry, but I''ve changed my mind.'),
('string/en/static_npc/tatooine/fixer.stf', 28, 'player_sorry_1', 'Not yet.  I''m still getting it done, though.'),
('string/en/static_npc/tatooine/fixer.stf', 29, 'npc_backtowork_1', 'Good to hear!'),
('string/en/static_npc/tatooine/fixer.stf', 30, 'npc_reset_1', 'Afraid of a little hard work, are ya? Too bad. Tosche Station''s got no place for lollygaggers. '),
('string/en/static_npc/tatooine/fixer.stf', 31, 'cantwork', 'How ya doin''? See me about a job when you get tired of your current employer.'),
('string/en/static_npc/tatooine/fixer.stf', 32, 'dontknowyou_1', 'Sorry, I was talking to myself.'),
('string/en/static_npc/tatooine/fixer.stf', 33, 'npc_work_1', 'So, did you get it to him?'),
('string/en/static_npc/tatooine/fixer.stf', 34, 'npc_work_2', 'Has that crazed Tusken been stopped yet?'),
('string/en/static_npc/tatooine/fixer.stf', 35, 'npc_work_3', 'So... did she get the part?'),
('string/en/static_npc/tatooine/fixer.stf', 36, 'npc_breech_1', 'Where in the heck is that part?'),
('string/en/static_npc/tatooine/fixer.stf', 38, 'npc_breech_3', 'Phew, I thought I was going to be that dewback''s dinner for sure. Thanks!'),
('string/en/static_npc/tatooine/fixer.stf', 39, 'notit_1', 'No, this won''t work.  I need a coupling.'),
('string/en/static_npc/tatooine/fixer.stf', 41, 'notit_3', 'This is not a converter coil, friend.  I need a coil so that I can get home again.'),
('string/en/static_npc/tatooine/fixer.stf', 42, 'npc_backtowork_2', 'Sounds good!  Let me know when he''s been stopped.'),
('string/en/static_npc/tatooine/fixer.stf', 43, 'npc_backtowork_3', 'Great!  Get it to her fast.  I don''t want her to get a sunburn.'),
('string/en/static_npc/tatooine/fixer.stf', 44, 'npc_reset_2', 'I didn''t figure ya for the shy type. Shove off.'),
('string/en/static_npc/tatooine/fixer.stf', 45, 'npc_reset_3', 'Kind of a heartless womp rat, aren''t ya? Get out of here!'),
('string/en/static_npc/tatooine/fixer.stf', 46, 'player_reset_2', 'I can''t do this anymore.  Sorry.'),
('string/en/static_npc/tatooine/fixer.stf', 47, 'player_reset_3', 'You''re sending me on a wild cu pa chase, aren''t you?  I''m not doing this.'),
('string/en/static_npc/tatooine/fixer.stf', 48, 'player_sorry_2', 'No, but I''m now equipped to take care of him.'),
('string/en/static_npc/tatooine/fixer.stf', 49, 'player_sorry_3', 'No, I haven''t found her yet.  I''m going to try right now, though.'),
('string/en/static_npc/tatooine/fixer.stf', 54, 'dontknowyou_3', 'Thanks for your concern, but I can handle this.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/fixer.stf', 106, 'npc_smuggle_1', 'Finally! Now to get this installed so I can get off this desert rock. Thanks!'),
('string/en/static_npc/tatooine/fixer.stf', 108, 'npc_smuggle_3', 'Fixer sent you with the parts I need to fix my speeder? Thanks a million!'),
('string/en/static_npc/tatooine/fixer.stf', 109, 'next', 'I don''t have any more work for ya right now. Try me later.'),
('string/en/static_npc/tatooine/fixer.stf', 110, 'npc_noloc_1', 'Hey, can you come back later?  I gotta deal with something before we can continue...'),
('string/en/static_npc/tatooine/fixer.stf', 111, 'npc_noloc_2', 'Hey, can you come back later?  I gotta deal with something before we can continue...'),
('string/en/static_npc/tatooine/fixer.stf', 112, 'npc_noloc_3', 'Hey, can you come back later?  I gotta deal with something before we can continue...'),
('string/en/static_npc/tatooine/fixer.stf', 113, 'waypoint_description_2', 'The Tusken Raiders has been spotted at this location.'),
('string/en/static_npc/tatooine/fixer.stf', 114, 'waypoint_name_2', 'Tusken Raiders'),
('string/en/static_npc/tatooine/gold_two.stf', 1, 'npc_1_1', 'A couple of stormtroopers are headed this way. I really severely don''t need to see them. If you dispose of them, I''m that much closer to getting out of this backwater. Except, excuse me, there''s no water! Back-dump! Back-pit! Help me!'),
('string/en/static_npc/tatooine/gold_two.stf', 2, 'npc_1_2', 'The hunt is intensifying. But if you destroy this one mounted trooper, you''ll make it look like I''m somewhere other than here. That might divert the search. Interested?'),
('string/en/static_npc/tatooine/gold_two.stf', 3, 'npc_1_3', 'I can''t shake the rest of the patrol. This is the toughest bunch yet -- probably three or four troopers plus the leader. If you take them out, you''ll clear the way for my mad dash to Mos Espa. What do you say?'),
('string/en/static_npc/tatooine/gold_two.stf', 5, 'npc_2_1', 'Great. Get to the troopers and shoot them before they can report on my whereabouts. Watch out for sandtraps. I hate all this sand.'),
('string/en/static_npc/tatooine/gold_two.stf', 6, 'npc_2_2', 'Okay, good, good. The trooper has a dewback, and the mount may make trouble too. Endless excitement in this dismal sandtrap.'),
('string/en/static_npc/tatooine/gold_two.stf', 7, 'npc_2_3', 'I won''t forget what you''re doing for me. You''re risking a lot to bail me out of a tough, tough spot. Good luck!'),
('string/en/static_npc/tatooine/gold_two.stf', 8, 'npc_3_1', 'Yeah, I wouldn''t look forward to facing stormtroopers either. Thanks anyway.'),
('string/en/static_npc/tatooine/gold_two.stf', 9, 'npc_3_2', 'I absolutely don''t blame you. Not my idea of a fun time. I expect I''ll just hang back here until they find me or I slowly strangle on dust.'),
('string/en/static_npc/tatooine/gold_two.stf', 10, 'npc_3_3', 'Yeah, I hear that. I feel silly just offering this deathtrap mission. But if I don''t get off this barren Sarlacc-pit, I''m gonna dissolve in my own bile.'),
('string/en/static_npc/tatooine/gold_two.stf', 12, 'npc_4_1', 'I''d just finished running a cargo of medical supplies through the Imperial blockade. On my way back up, they caught me. I barely survived the crash. Now I''m stuck on this dessicated rockball. Help!'),
('string/en/static_npc/tatooine/gold_two.stf', 13, 'npc_4_2', 'Stressed! Yeah, you might say that. I woke up this morning and a rock-mite was eating my boots! Just one more attraction here on Tatooine, sun-drenched center for life-threatening recreation. Now, about that trooper --? '),
('string/en/static_npc/tatooine/gold_two.stf', 14, 'npc_4_3', 'The Alliance is arranging a hot new X-wing and a clear docking bay with my name on it, just as soon as I can get there. But there''s this matter of the patrol to deal with first. And your choice is --?'),
('string/en/static_npc/tatooine/gold_two.stf', 15, 'npc_reward_1', 'All right, all right, my life is just that much less terrible. I appreciate your help. If you want more work, I''ve still got trouble, so check back.'),
('string/en/static_npc/tatooine/gold_two.stf', 16, 'npc_reward_2', 'Good news. Okay, it''s possible I may actually pull through this. If you''ve got more time and want more money, check back with me.'),
('string/en/static_npc/tatooine/gold_two.stf', 17, 'npc_reward_3', 'I don''t believe it! I''m in the clear! You''ve saved me, my friend! Now I have to get to Mos Espa and jump off this despicable sand-blown crime-ridden Hutt-run krayt-loving hive of scum and villainy. Thanks!'),
('string/en/static_npc/tatooine/gold_two.stf', 18, 'player_1_1', 'Calm down.  I''ll help you.'),
('string/en/static_npc/tatooine/gold_two.stf', 19, 'player_1_2', 'Sure, I''ll lend a hand.'),
('string/en/static_npc/tatooine/gold_two.stf', 20, 'player_1_3', 'I''ll hold them off for you!'),
('string/en/static_npc/tatooine/gold_two.stf', 21, 'player_2_1', 'I don''t want to tangle with Stormtroopers.'),
('string/en/static_npc/tatooine/gold_two.stf', 22, 'player_2_2', 'Stormtroopers are one thing.  A mounted one is another.  Sorry, I can''t help.'),
('string/en/static_npc/tatooine/gold_two.stf', 23, 'player_2_3', 'Now you''re being ridiculous!  I''m not dealing with a whole squad!'),
('string/en/static_npc/tatooine/gold_two.stf', 24, 'player_3_1', 'How did you crash here?'),
('string/en/static_npc/tatooine/gold_two.stf', 25, 'player_3_2', 'How are you doing? You look a little stressed. '),
('string/en/static_npc/tatooine/gold_two.stf', 26, 'player_3_3', 'How are you getting offworld?'),
('string/en/static_npc/tatooine/gold_two.stf', 27, 'player_reset_1', 'I''m sorry, but I''ve changed my mind.  I can''t do this anymore.'),
('string/en/static_npc/tatooine/gold_two.stf', 28, 'player_sorry_1', 'I believe there are a few left.  I''ll take care of the remaining ones shortly.'),
('string/en/static_npc/tatooine/gold_two.stf', 29, 'npc_backtowork_1', 'Thank you very much, my newly found friend.'),
('string/en/static_npc/tatooine/gold_two.stf', 30, 'npc_reset_1', 'Yeah, I wouldn''t look forward to facing stormtroopers either. Thanks anyway.'),
('string/en/static_npc/tatooine/gold_two.stf', 31, 'cantwork', 'You! Can you help --? Oh. Never mind. I see you''re busy. Maybe you could check back later, assuming I''m still stuck on this rock.'),
('string/en/static_npc/tatooine/gold_two.stf', 33, 'npc_work_1', 'Are there any more of the stormtroopers around?'),
('string/en/static_npc/tatooine/gold_two.stf', 34, 'npc_work_2', 'Was the Mounted Stormtrooper taken care of?'),
('string/en/static_npc/tatooine/gold_two.stf', 35, 'npc_work_3', 'You were able to deal with them already?  Are you a Jedi?'),
('string/en/static_npc/tatooine/gold_two.stf', 36, 'npc_breech_1', 'A hostile! Open fire!'),
('string/en/static_npc/tatooine/gold_two.stf', 37, 'npc_breech_2', 'Halt!'),
('string/en/static_npc/tatooine/gold_two.stf', 38, 'npc_breech_3', 'There''s the target! Fire!'),
('string/en/static_npc/tatooine/gold_two.stf', 42, 'npc_backtowork_2', 'I appreciate you helping me.  I didn''t think I''d find anybody who cares on this back - ah - backwards planet!'),
('string/en/static_npc/tatooine/gold_two.stf', 43, 'npc_backtowork_3', 'Oh.  Okay, well, I still thank you!  Just say the word!'),
('string/en/static_npc/tatooine/gold_two.stf', 44, 'npc_reset_2', 'I absolutely don''t blame you. Not my idea of a fun time. I expect I''ll just hang back here until they find me or I slowly strangle on dust.'),
('string/en/static_npc/tatooine/gold_two.stf', 45, 'npc_reset_3', 'Yeah, I hear that. I feel silly just offering this deathtrap mission. But if I don''t get off this barren Sarlacc-pit, I''m gonna dissolve in my own bile.'),
('string/en/static_npc/tatooine/gold_two.stf', 46, 'player_reset_2', 'Sorry, I''ve ahad a change of heart.  I don''t want to get involved with this guy.'),
('string/en/static_npc/tatooine/gold_two.stf', 47, 'player_reset_3', 'You know what?  I can''t help you with this.  This is way to risky!'),
('string/en/static_npc/tatooine/gold_two.stf', 48, 'player_sorry_2', 'Not yet.  He''s approaching as we speak, so I can take care of him.'),
('string/en/static_npc/tatooine/gold_two.stf', 49, 'player_sorry_3', 'Ummm... no, I''m not.  And... um... they''re not all taken care of yet.  I''ll let you know when to run.'),
('string/en/static_npc/tatooine/gold_two.stf', 50, 'next', 'I''d hire you again but I hope to be off of this miserable desert hole really soon. Check back with me if you have time, you never know when something might foul up my plan to get out of here.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 1, 'npc_1_1', 'How are you doing there, friend?  My name is Gramm Rile, and I''m what you''d call the mayor around here.  You know, you stopped by just in time.  I''m having a surveyor come here to town to take a look around the place, but judging how late he is, I''d reckon he''s lost.  Could you run out there and find him for me?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 2, 'npc_1_2', 'Nice to see you, friend!  Just to let you know, the surveyor said he agrees with me, and he''s going to put in a good report for us.  Hopefully we''ll get that garrison out here now.  In the meantime, I''m wondering if you can do me a bit of another favor?  I need you to escort a farmer across the desert so that I can talk with him.  Can you do that?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 3, 'npc_1_3', 'Blast that Talmont!  Blast all them Imperials, I tell you!!!  Prefect Talmont has decided "it''s not a worthwhile expenditure of Imperial resources" and he won''t build a garrison out here!  Without their help we''re doomed!  Unless.  Well, it won''t hurt to talk to him, I guess.  Could you go send a message for me then bring back the response?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 4, 'npc_1_4', 'I''m not having any part of dealing with that overgrown slug!  I can''t believe he''d ask so much for his "help".  That''s it, I''m relocating everyone into this town now for the time being.  If those Tuskens want a fight, they''ll get one.  Oh, NO!  My wife is out there! Look, you have to bring her back here, understand?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 5, 'npc_2_1', 'Oh, I sure do appreciate this, friend.  If word got back to Prefect Talmont in Bestine that I''d gone ahead and let his surveyor get killed, well... well, I don''t really know what could happen.  When you find him, bring him back here safe and sound, you hear?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 6, 'npc_2_2', 'Oh, this is good news.  With all the Tusken activity lately, it''s got the farmer spooked.  I told him I knew just the person to keep him safe while walking out here.  I''ll be waiting, friend.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 7, 'npc_2_3', 'Okay, look.  I need you to run out to this location and speak to one of Jabba''s business associates.  He''ll accompany you back here to make sure it''s not a trap, so you get him here without a hair harmed on him, okay?  I''ll wait here until you bring him back.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 8, 'npc_2_4', 'Okay, look, I''m entrusting you to bring her back here safely.  She''s got the spirit of a bocatt, but that won''t help anyone when facing down those Sand People.  You go out to my house and escort her back here safely, you hear?  In the meantime, I''ll see to it that everyone else around Mos Taike gets to town safely.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 9, 'npc_3_1', 'Well, I can''t blame you, with all of the reports of Tusken Raiders as of late.  I''ll see if I can find someone else to do, but if you change your mind, you be sure to let me know, okay?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 10, 'npc_3_2', 'I sure do hope you reconsider, friend.  He''s not going to come out here unless he has a bodyguard, and I sure do need to speak with him.  If you have a change of heart, I''ll be here waiting.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 11, 'npc_3_3', 'Yeah, if I were in your shoes, I''d say the same. *sigh* Unfortunately, I''m the mayor out here and I''ve got to look at all of my options.  I wish I had the luxury to walk away as you do.  If you change your mind, let me know okay?  Try to do it before we get attacked by Tuskens again if you could, too...'),
('string/en/static_npc/tatooine/gramm_rile.stf', 12, 'npc_3_4', 'What?  But I thought... I can''t believe you''d leave a person out there to the Tuskens!  I''d do it myself, but I have to make sure everyone else gets the alert.  Look, you think about what you just said, then you think about those Tuskens, you got that?  Then, you come back to me when you realize you want to help.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 13, 'npc_4_1', 'Well, you see, this is how it is. *sigh* Mos Taike is under threat of attack by Tuskens all the time, and it''s beginning to get out of hand.  I''ve petitioned both Tour Aryon and Prefect Talmont to have an Imperial garrison built here to help defend the town.  They''ve finally agreed to send a surveyor out here to assess the situation.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 14, 'npc_4_2', 'Well, not too many people know this yet, so keep it to yourself, okay?  Our main supplier of water lost a couple of caravans recently, and wants to recover her losses by making us pay for it.  I know a farmer out there who''s willing to sell us water for the standard price, but he won''t travel out here alone.  That''s why I need you.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 15, 'npc_4_3', 'Well, if we can''t get protection from the Imperials, we have to look elsewhere.  Jabba has offered his protection in the past, but hasn''t given a price for it.  Maybe I can convince him that we don''t have much to pay with, but we need his help.  I sure do hope he understands our plight and actually has a heart somewhere in there.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 16, 'npc_4_4', 'That two-faced, undermining, extortionist was happy to offer his help.  His price was to have Mos Taike send him seven people every year to be his slaves!  I won''t have any of that!  If it means we die fighting the Tuskens, so be it, but I won''t send anyone to Jabba to be a SLAVE!  I won''t have that, I tell you!  Better to die free, then to live a slave!'),
('string/en/static_npc/tatooine/gramm_rile.stf', 17, 'npc_reward_1', 'I''m glad to see you were able to find him.  He''s a bit shaken up, with all things considered, but once he calms down a bit, I can show him around.  Hopefully this incident will convince him to send a report back to Talmont that''ll get a garrison built out here.  Thanks again, friend.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 18, 'npc_reward_3', 'Well, I thank you, friend. I''m now going to have a sit down with this guy and see if I can convince him to help without him asking too much.  *sigh*  If we weren''t so desperate, I''d never consider this.  But you gotta understand, I have to do what I can to keep my people safe.  Surely you see that.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 19, 'npc_reward_2', 'My farmer friend says that he''ll keep his rates low, seeing how safe it was to get out here, and all.  Without you, everyone here in Mos Taike would''ve had to sell themselves into slavery just to afford water.  Hmph... Jabba would''ve sure loved that.  We''re in the clear now, so on behalf of Mos Taike, I give you our thanks!'),
('string/en/static_npc/tatooine/gramm_rile.stf', 20, 'npc_reward_4', 'Oh, good, you got her here safely!  You''ve been a great help, friend.  Just in time, too.  According to Lorne, our security chief, he''s spotted another Tusken raid on it''s way.  I''ve been able to get everyone here safely, so we can all join together and bring down these Tuskens.  Once again, thank you friend, you''ve been a great help!'),
('string/en/static_npc/tatooine/gramm_rile.stf', 21, 'player_1_1', 'Sure!  I''ll go find him for you.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 22, 'player_1_2', 'Point me at him and I''ll get him here safe!'),
('string/en/static_npc/tatooine/gramm_rile.stf', 23, 'player_1_3', 'Sounds simple enough.  I''ll do it.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 24, 'player_1_4', 'By all means!  I''ll get out there immediately!'),
('string/en/static_npc/tatooine/gramm_rile.stf', 25, 'player_2_1', 'Sorry, but I''m afraid I''d get lost as well.  I can''t do that.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 26, 'player_2_2', 'No, I''ve got other plans right now.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 27, 'player_2_3', 'I don''t think I like where this is going.  No, I won''t do it.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 28, 'player_2_4', 'No, I don''t have time to escort some lady across the sands.  Do it yourself.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 29, 'player_3_1', 'Why are you having a surveyor inspect the town?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 30, 'player_3_2', 'Who do you want me to pick up?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 31, 'player_3_3', 'What kind of message are we talking about here?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 32, 'player_3_4', 'Why didn''t you take Jabba''s help?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 33, 'npc_backtowork_1', 'That''s good to hear.  I''ll bet anything he''s just walking around in cricles, which doens''t bode well for a survey for our place.  Well, if you find him, bring him my way, okay?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 34, 'npc_backtowork_2', 'Well, that''s good to hear.  I don''t want to see either of you hurt, so take your time.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 35, 'npc_backtowork_3', 'Well, I don''t want to bring down Jabba''s wrath on us.  I thank you for you being prudent and all.  Try not to make him wait too long though, if you could.  It would be mighty apppreciated.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 36, 'npc_backtowork_4', 'I''m glad to see you made it out alive.  Those Raiders can be deadly!  Let''s just hope it''s not too late for my wife.  You go get her while I direct everyone else in here safely, okay?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 37, 'npc_work_1', 'Have you managed to find the surveyor yet?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 38, 'npc_work_3', 'So, where''s Jabba''s guy?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 39, 'npc_work_4', 'Is Chastina here in the town now?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 40, 'player_sorry_2', 'Not yet.   I thought I saw some Sand People, and was waiting till they passed.  Once they''re gone, I''ll escort him here.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 41, 'player_sorry_1', 'No, I haven''t been able to find him.  When I do, I''ll be sure to bring him back right away!'),
('string/en/static_npc/tatooine/gramm_rile.stf', 42, 'player_sorry_3', 'I haven''t been able to make it out there yet.  Once I can safely do it, I''ll be sure to bring him back.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 43, 'player_sorry_4', 'No, I.. um... was attacked by Sand People.  Now that they''ve been dispatched, I can rescue her safely.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 44, 'npc_work_2', 'So, have you brought back my farmer friend?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 45, 'player_reset_1', 'I''ve searched and searched, but I can''t find him.  You might need to send out a team for him, because I can''t do it anymore.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 46, 'player_reset_3', 'I''ve thought about it, and I don''t want to be part of any dealings with Jabba.  I can''t do this anymore.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 47, 'player_reset_4', 'I can''t escort her back here, Gramm.  I''ve been... um... injured.  Yeah, I''ve been injured and can''t save her.  Can you send someone else?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 48, 'player_reset_2', 'I won''t be able to safely bring him here, sorry.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 49, 'npc_reset_1', 'Well, I thank you for giving it your best.  I''ll see about having Bren round up a group of people to go find him.  Even though you didn''t find him, I do appreciate you looking.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 50, 'npc_reset_2', 'Well, then I guess I''ll have to send Bren out there.  I do appreciate you offering to help, either way.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 51, 'npc_reset_3', '*sigh* Well, I can''t blame you.  Were I not so desperate, I wouldn''t have asked you to do it.  I guess I''ll go out there myself.  I thank you for considering it, though.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 52, 'npc_reset_4', 'Well, if you''ve been injured, you can''t act as an adequate bodyguard.  I''ll send someone out there to bring her back.  In the meantime, get yourself to a medic.  Your wounds must be internal, ''cause I don''t see any on the outside.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 53, 'cantwork', 'How are you doing there, friend?  I hope you''ve taken a liking to Mos Taike.  When you''ve got some time, I might have need of your services.  Let me know when you''re free, okay?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 54, 'dontknowyou_1', 'Oh, I''m sorry.  I though you were from Mos Taike.  I guess I''ll have to find it myself, then.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 55, 'dontknowyou_2', 'Sorry, I''m waiting for a bodyguard to keep the Tuskens off my back.  He or she should be here soon.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 56, 'dontknowyou_3', 'You don''t look like you need Jabba''s protection.  Just keep walking and mind your own business.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 57, 'dontknowyou_4', 'I''m sorry, I though you were my husband.  Have a good day, and watch out for Tuskens.  I''ve just taken down four of them myself in the past hour.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 58, 'npc_breech_1', 'Are you here to rescue me?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 59, 'npc_breech_3', 'What a dangerous place, wouldn''t you say.  A lot of bad things can happen out in the desert, if one isn''t careful.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 60, 'npc_breech_4', 'Gramm, is that you?  What''s going on?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 61, 'npc_breech_2', 'Are you the one that Rile sent?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 62, 'npc_takeme_1', 'Oh, thank goodness someone''s come to rescue me!  I was down to the last of my food and water!  I''ve been lost out here in the wasteland for close to 2 hours now!  Please, could you show me the way to Mos Taike?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 63, 'npc_takeme_2', 'Well, Rile did say he''d send me a body guard, and you sure do fit the bill.  I''m Merg Thando.  Pleased to meet you.  Now, if we could, let''s make our way to Mos Taike before any Sand People catch our scent.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 64, 'npc_takeme_3', 'You must be the one who''s looking for Jabba''s help, hm?  Now, lead me to this backwater settlement, and don''t make any false moves, got it?  If I get hurt, Jabba won''t be too happy, understand?'),
('string/en/static_npc/tatooine/gramm_rile.stf', 65, 'npc_takeme_4', 'Oh!  Gramm is calling everyone into town?  Now I understand why I was attacked by a dozen or so Tuskens about an hour back.  They were tough ones, too!  Took me about 10 minutes before I could take down all of them.  I appreciate your help.  Now, let''s go before more return.'),
('string/en/static_npc/tatooine/gramm_rile.stf', 66, 'next', 'Check back with me sometime. I may have more for you to do.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 1, 'npc_1_1', 'There''s a new Imperial Security Bureau initiative called Project Lasercutter. We''re trying to fight it. We don''t have a lot of time. An ISB agent is on the way to arrest one of our "procurement specialists" right now. Can you stop him?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 2, 'npc_1_2', 'We''ve received word that ISB is sending a Lasercutter team to arrest one of our most reliable smugglers. Will you escort her here safely?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 3, 'npc_1_3', 'We now know how ISB has been finding our smugglers recruits. They''ve planted a spy in the Alliance recruiting operation. Will you dispatch this turncoat for us?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 5, 'npc_2_1', 'I''m glad to hear it. Intercept and stop the ISB agent before he finds him.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 6, 'npc_2_2', 'Wonderful. Go and meet our smuggler friend, Jaxa Lian, and bring her back safely. Hurry, so the ISB doesn''t find her first. '),
('string/en/static_npc/tatooine/hantor_loftus.stf', 7, 'npc_2_3', 'The informant will be meeting ISB agents out in the desert. Eliminate all of them, but don''t get reckless.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 8, 'npc_3_1', 'You''d better go. I have things to do. '),
('string/en/static_npc/tatooine/hantor_loftus.stf', 9, 'npc_3_2', 'If that was a joke, I''m not laughing. No? Stop wasting my time, this is important work.  '),
('string/en/static_npc/tatooine/hantor_loftus.stf', 10, 'npc_3_3', 'I can''t believe you''re backing out now. Goodbye.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 12, 'npc_4_1', 'In brief, the Empire is hunting smugglers friendly to the Alliance. This will do nothing good for our supply lines. Will you help us?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 13, 'npc_4_2', 'I don''t know yet, but you can be sure I''m looking in to it. Can we count on your assistance?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 14, 'npc_4_3', 'His name? Let me check -- Lidek Baws. Recruited on Naboo. Huh! That should have been a giveaway right there. Will you stop him?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 15, 'npc_reward_1', 'Good work. We still have a long way to go but that was a good start.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 16, 'npc_reward_2', 'Well done. Now I just need to track down our information leak.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 17, 'npc_reward_3', 'Success? Good! I''m glad we''ve stopped that leak.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 18, 'player_1_1', 'Yes, I''ll stop the agent.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 19, 'player_1_2', 'You can count on me!'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 20, 'player_1_3', 'I''ll take care of him, alright!'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 21, 'player_2_1', 'No thanks, I don''t want to get involved.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 22, 'player_2_2', 'I don''t take too kindly to smugglers.  No, I can''t help.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 23, 'player_2_3', 'Sorry, but I''m not cut out to handle this kind of intrigue.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 24, 'player_3_1', 'What is Project Lasercutter?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 25, 'player_3_2', 'How do they keep finding these smugglers?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 26, 'player_3_3', 'Who is the spy?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 27, 'player_reset_1', 'I''m not going to be able to handle this.  You''ll need to get someone else to do it.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 28, 'player_sorry_1', 'Not yet, but rest assured that I will.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 29, 'npc_backtowork_1', 'You''ll need to pick up the pace.  I don''t know how much time you have left.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 30, 'npc_reset_1', 'You''d better go. I have things to do. '),
('string/en/static_npc/tatooine/hantor_loftus.stf', 31, 'cantwork', 'I could really use your help. Finish your current task and then see me again.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 32, 'dontknowyou_1', 'Sorry, I thought you were a Rebel.  Nevermind.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 33, 'npc_work_1', 'Have you stopped him yet?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 34, 'npc_work_2', 'Where''s Jaxa?  Is she safe?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 35, 'npc_work_3', 'So, have you given the spy his just reward?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 36, 'npc_breech_1', 'Rebel fool!'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 37, 'npc_breech_2', 'Hello.  What a nice day we''re having.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 38, 'npc_breech_3', 'They found me out, did they? That''s bad news for you, Rebel.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 42, 'npc_backtowork_2', 'You''ll need to pick up the pace.  I don''t know how much time you have left.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 43, 'npc_backtowork_3', 'I guess you know what you''re doing.  Let''s just hope he doesn''t find out from someone else first.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 44, 'npc_reset_2', 'If that was a joke, I''m not laughing. No? Stop wasting my time, this is important work.  '),
('string/en/static_npc/tatooine/hantor_loftus.stf', 45, 'npc_reset_3', 'I can''t believe you''re backing out now. Goodbye.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 46, 'player_reset_2', 'I''m not going to be able to handle this.  You''ll need to get someone else to do it.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 47, 'player_reset_3', 'I''ve got to pass this one off to someone else.  I can''t do it right now.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 48, 'player_sorry_2', 'I don''t know.  I''m on my way to find her right now.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 49, 'player_sorry_3', 'Not yet, but I shall do so shortly.  I don''t want to tip him off to me coming.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 51, 'npc_takeme_2', 'An ISB squad coming for me? Let''s get out of here!'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 53, 'dontknowyou_2', 'Have a good journey!  Make sure to watch out for those Krayts while you''re at it.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 54, 'dontknowyou_3', 'What?  You''re no Rebel fool.  Oh.  Ummm... Nevermind what I just said, okay?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 55, 'dontknowyou_4', 'That meant for you to get away from me.  Shoo!'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 61, 'npc_1_4', 'Turns out it''s not the ISB behind Project Lasercutter, but rather the Inquisitorius. Kill the Inquisitor leading the project. With him gone, Lasercutter will be set back months, if not permanently. This will be incredibly difficult, but I''m hoping you''ll try. What do you think?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 64, 'npc_2_4', 'You''re a good soldier. I wish you all the best. Find this Inquisitor and take him out. He''ll be well protected, so get some insurance first, and reserve a spot in the bacta tanks for later.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 67, 'npc_3_4', 'I understand. This mission should not be undertaken lightly.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 70, 'npc_4_4', 'I''m not surprised you haven''t heard of them -- they''re top secret. Inquisitors are skilled agents who work directly for the Emperor. They supposedly have skill with "the Force," not that I believe that. In any case, they''re deadly. Will you take the mission?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 73, 'npc_backtowork_4', 'Well, once you have that taken care of, go take him down.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 76, 'npc_breech_4', 'Dispose of this annoyance.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 79, 'npc_reset_4', 'understand. This mission should not be undertaken lightly.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 82, 'npc_reward_4', 'Amazing! You''ve done the Alliance a huge service. Go take some time off now. You''ve earned it.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 88, 'npc_work_4', 'Has the Inquisitor met his end?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 91, 'player_1_4', 'I think I can handle something like this.  I''ll do it.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 94, 'player_2_4', 'Sounds too dangerous.  Count me out.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 97, 'player_3_4', 'What is the Inquisitorius?'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 100, 'player_reset_4', 'I''ve changed my mind and won''t be doing it.  This Inquisitor guys sounds too dangerous for me.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 103, 'player_sorry_4', 'No, I''m still getting a bacta tank reserved before I head out there.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 104, 'next', 'There''s a little too much Imperial scrutiny to do anything else right now. See me later.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 105, 'waypoint_description_1', 'A ISB Agent on his way to arrest a Alliance smuggler.'),
('string/en/static_npc/tatooine/hantor_loftus.stf', 106, 'waypoint_name_1', 'ISB Agent'),
('string/en/static_npc/tatooine/hedon_istee.stf', 1, 'npc_1_1', 'I''m a former initiate of the B''omarr Order that decided not to attempt "enlightenment." My former brothers, however, have different ideas. They''ve sent one of their bodyguards to either force me back "into the fold" or dispose of me. You look like you may be able to help someone in desperate need.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 2, 'npc_1_2', 'It seems the B''omarr have hired a bounty hunter to bring me back into their serene embrace. I must have really impressed the abbot during my stay at the monastery. In any case, this bounty hunter will no doubt claim my life if you don''t stop them. Will you help?'),
('string/en/static_npc/tatooine/hedon_istee.stf', 3, 'npc_1_3', 'All right, I admit it! I did steal a sacred scroll from the B''omarr Order! They could care less that I didn''t want to achieve "enlightenment" - in fact, the abbot claimed I was a hopeless "sensualist" and had me expelled! Will you please return this scroll to the abbot so I can have peace?'),
('string/en/static_npc/tatooine/hedon_istee.stf', 5, 'npc_2_1', 'Splendid! I knew you''d appreciate my predicament - you seem a being who knows how to enjoy the finer things in life. The bodyguard is a Gamorrean named Drognuz. He may not understand any other language than violence.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 6, 'npc_2_2', 'Excellent! The bounty hunter goes by the name of Rath Kanaz. I can tell you now that bounty hunters a very deceptive and cunning individuals. They may hurl some wild and baseless accusations to justify their actions. Don''t listen to a word they say - it''s all noncense.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 7, 'npc_2_3', 'Stalwart and true is how I''ll describe you from now on! The abbot and his retinue have agreed to meet at these coordinates. Just hand them the scroll and leave. Whatever you do, don''t accept an invitation to their monastery. They might try to "enlighten" you once you''re there.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 8, 'npc_3_1', 'Did I mention that I am a most generous being when it comes to rewarding those that save my life? You wouldn''t want to miss out, would you? Please change your mind.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 9, 'npc_3_2', 'But I thought we were good friends? I fear I''m at a loss for words. I''m not accustomed to this sort of treatment from a trusted companion. What is the galaxy coming to? '),
('string/en/static_npc/tatooine/hedon_istee.stf', 10, 'npc_3_3', 'You can''t back out on me now! After all, it was you who left those B''omarr thugs rotting in the desert! I won''t get a moment''s peace if you refuse to help me. Please reconsider!'),
('string/en/static_npc/tatooine/hedon_istee.stf', 12, 'npc_4_1', 'It involves surgically removing my brain from my body and placing it in a vat of nutrients. I like my brain where it is, thank you, and have decided that a vat of nutrients is not the finest accommodation the galaxy has to offer.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 13, 'npc_4_2', 'Oh, he may go on about a stolen precious object or something equally as ridiculous. The B''omarr Order has no doubt deceived the poor soul. Those monks will stop at nothing to convince their hirelings of the justice of their cause. Pay it no mind, friend.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 14, 'npc_4_3', 'I think it describes the complicated procedures involved in "enlightenment" - which is essentially how to remove and transport a living brain. All I know is that they thought it valuable, so therefore I assumed I could get a good price for it on the black market.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 15, 'npc_reward_1', 'Well handled, friend. I just hope that''s the last I''ll hear of those bizarre monks. I''m not sure why they''re so interested in harming me when they''re supposed to be pacifists. I suppose I have to give up some of my hard earned credits as thanks.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 16, 'npc_reward_2', 'I told you the bounty hunter would make wild claims. I assure you I don''t know a thing about any "sacred scroll." I''m glad you''re much smarter than the average mercenary, friend. As much as it saddens me to part with these credits, you have earned them.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 17, 'npc_reward_3', 'I shall never forget you my friend. You have brought serenity to my life and have made it possible for me to get back to the important task of living it. I''m running a bit low on credits but I do have this map as a thanks for your help. Supposedly it leads to a treasure but I haven''t mustered the courage to go there yet. Be careful if you do.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 18, 'player_1_1', 'Sounds horrible! I''ll go and see if I can convince him otherwise.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 19, 'player_1_2', 'Yes, I''ll save your life.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 20, 'player_1_3', 'If it will put you at ease, I will do it.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 21, 'player_2_1', 'No.  I don''t want to get involved.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 22, 'player_2_2', 'Bounty Hunter?  Um.. no thanks.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 23, 'player_2_3', 'No, this is something you should do yourself.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 24, 'player_3_1', 'What''s so bad about "enlightenment?"'),
('string/en/static_npc/tatooine/hedon_istee.stf', 25, 'player_3_2', 'What kind of accusations?'),
('string/en/static_npc/tatooine/hedon_istee.stf', 26, 'player_3_3', 'Why is this scroll important?'),
('string/en/static_npc/tatooine/hedon_istee.stf', 27, 'player_reset_1', 'I''ve changed my mind.  This job doesn''t interest me anymore.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 28, 'player_sorry_1', 'Not yet.  But I am still working on this.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 29, 'npc_backtowork_1', 'Hurry already!'),
('string/en/static_npc/tatooine/hedon_istee.stf', 30, 'npc_reset_1', 'Did I mention that I am a most generous being when it comes to rewarding those that save my life? You wouldn''t want to miss out, would you? Please change your mind.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 31, 'cantwork', 'I''m afraid I''m a very demanding individual and therefore working for me would require your full attention. Do come back when you can offer me that. You won''t be sorry you did.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 33, 'npc_work_1', 'Have you taken care of the Gamorrean yet?'),
('string/en/static_npc/tatooine/hedon_istee.stf', 34, 'npc_work_2', 'Has the Bounty Hunter been taken care of?'),
('string/en/static_npc/tatooine/hedon_istee.stf', 35, 'npc_work_3', 'So, have you given it back?  Did they say they''ll leave me alone now?'),
('string/en/static_npc/tatooine/hedon_istee.stf', 36, 'npc_breech_1', 'Grunt!'),
('string/en/static_npc/tatooine/hedon_istee.stf', 37, 'npc_breech_2', 'All the B''omarr want is that sacred scroll. You''re in my way and must be removed.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 38, 'npc_breech_3', 'May you come to know the serenity of emptiness, sensualist.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 42, 'npc_backtowork_2', 'Well, I guess I''ll have to go into hiding until you are able to handle the situation.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 43, 'npc_backtowork_3', 'Please hurry before they send someone else to kill me!'),
('string/en/static_npc/tatooine/hedon_istee.stf', 44, 'npc_reset_2', 'But I thought we were good friends? I fear I''m at a loss for words. I''m not accustomed to this sort of treatment from a trusted companion. What is the galaxy coming to? '),
('string/en/static_npc/tatooine/hedon_istee.stf', 45, 'npc_reset_3', 'You can''t back out on me now! After all, it was you who left those B''omarr thugs rotting in the desert! I won''t get a moment''s peace if you refuse to help me. Please reconsider!'),
('string/en/static_npc/tatooine/hedon_istee.stf', 46, 'player_reset_2', 'I''m sorry, but I don''t want to get between you and a Bounty Hunter after all.  I can''t do this.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 47, 'player_reset_3', 'I think it would be better if you did this yourself.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 48, 'player_sorry_2', 'Not yet.  I''ve just tracked down his location and am on my way to eliminate him.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 49, 'player_sorry_3', 'I haven''t delievered it yet.  I will, though.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 54, 'dontknowyou_3', 'Until that time has come, your life will be filled with false euphoria.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 108, 'npc_smuggle_3', 'The scroll.  You have begun your travel down the path of enlightenment, sensualist.  We will watch from afar, but no longer through direct intervention.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 109, 'next', 'Thanks for all your help. Maybe I''ll see you again one day.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 110, 'npc_failure', 'You''ve failed me.  Come back later if you''re feeling more competent.'),
('string/en/static_npc/tatooine/hedon_istee.stf', 111, 'notyet', 'Greetings, I''m afraid you''re not strong enough to help me yet.'),
('string/en/static_npc/tatooine/ian_lago.stf', 1, 'next', 'I have no further need of your services at this time. Check with my aide for future assignments.'),
('string/en/static_npc/tatooine/ian_lago.stf', 2, 'cantwork', 'You need to be focused when you work for me. Come back when other more trivial matters do not concern you.'),
('string/en/static_npc/tatooine/ian_lago.stf', 3, 'npc_reset_1', 'How very disappointing. Come back when you can actually finish what you begin.'),
('string/en/static_npc/tatooine/ian_lago.stf', 4, 'notyet', 'Go speak to my assistant, Junelle Astor. She can arrange an appointment for you.'),
('string/en/static_npc/tatooine/ian_lago.stf', 5, 'npc_1_1', 'So, I see Junelle has cleared you. Good. I need some surveillance equipment delivered to one of my agents. He''s currently investigating a group of Gungans suspected of aiding the Rebellion. Can you do this?'),
('string/en/static_npc/tatooine/ian_lago.stf', 6, 'npc_2_1', 'Good. You should depart immediately. I wish the Gungans would realize how badly their actions reflect on the Naboo and our beloved Queen. If they''d only embrace the Empire, life would be easier for all of us.'),
('string/en/static_npc/tatooine/ian_lago.stf', 7, 'npc_3_1', 'Are you sure Junelle cleared you? Why go through all that trouble if you had no desire to help?'),
('string/en/static_npc/tatooine/ian_lago.stf', 8, 'npc_4_1', 'The agent is Eevas Drupper. I''ll let him know you''re on your way.'),
('string/en/static_npc/tatooine/ian_lago.stf', 9, 'npc_backtowork_1', 'I''ve told you everything you need to know. Do you still wish to do this?'),
('string/en/static_npc/tatooine/ian_lago.stf', 10, 'npc_reward_1', 'Well done. With any luck we''ll bring these malcontents under control soon.'),
('string/en/static_npc/tatooine/ian_lago.stf', 11, 'npc_work_1', 'Did you deliver that sensor pack? My agent can''t do his job without it.'),
('string/en/static_npc/tatooine/ian_lago.stf', 12, 'npc_noloc_1', 'It seems my agent''s location has been compromised and he must elude a pursuit. Check back with me later for his new coordinates.'),
('string/en/static_npc/tatooine/ian_lago.stf', 13, 'npc_failure_1', 'Failing to deliver a simple package does not bode well for your future career with me.'),
('string/en/static_npc/tatooine/ian_lago.stf', 14, 'otherescort_1', 'I don''t think I''m the person you''re looking for. Good luck on your search.'),
('string/en/static_npc/tatooine/ian_lago.stf', 15, 'dontknowyou_1', 'I''m waiting for someone. I''m afraid I can''t talk right now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 16, 'npc_breech_1', 'Did the Governor send you? I''m Eevas Drupper.'),
('string/en/static_npc/tatooine/ian_lago.stf', 17, 'npc_takeme_1', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 18, 'npc_dropoff_1', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 19, 'npc_smuggle_1', 'Thank you. This will make my work much easier.'),
('string/en/static_npc/tatooine/ian_lago.stf', 20, 'gotowork_1', 'I believe you have something for me.'),
('string/en/static_npc/tatooine/ian_lago.stf', 21, 'notit_1', 'Are you sure this is what the Governor asked you to give me? It doesn''t seem right.'),
('string/en/static_npc/tatooine/ian_lago.stf', 22, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 23, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/tatooine/ian_lago.stf', 24, 'player_1_1', 'Yes.'),
('string/en/static_npc/tatooine/ian_lago.stf', 25, 'player_2_1', 'No.'),
('string/en/static_npc/tatooine/ian_lago.stf', 26, 'player_3_1', 'What''s this agent''s name?'),
('string/en/static_npc/tatooine/ian_lago.stf', 27, 'npc_1_2', 'I''m happy to see you''re so eager to serve me. Good help is hard to find. Take for example one of my agents, a Gungan loyal to the Empire who has been discovered spying on his traitorous fellows. He''s managed to elude his pursuers thus far but fears he will eventually be tracked down. Could you see to it that he makes it back here safely?'),
('string/en/static_npc/tatooine/ian_lago.stf', 28, 'npc_2_2', 'Do hurry. Loyal Gungans are hard to come by.'),
('string/en/static_npc/tatooine/ian_lago.stf', 29, 'npc_3_2', 'Remember when I said that good help was hard to find? I think you see what I meant now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 30, 'npc_4_2', 'The clever Gungan, named Boona Deeks, hid inside the rotting carcass of a bolle bol for a couple of days. So be warned, he might be a touch on the odorous side.'),
('string/en/static_npc/tatooine/ian_lago.stf', 31, 'npc_backtowork_2', 'Was something unclear? Why are you standing around?'),
('string/en/static_npc/tatooine/ian_lago.stf', 32, 'npc_reward_2', 'You''ve done well. Now I think I need to direct this Gungan to the bathing pools.'),
('string/en/static_npc/tatooine/ian_lago.stf', 33, 'npc_work_2', 'Did you bring that Gungan agent safely back to the palace? I know he''s just a Gungan but I do have need of his services.'),
('string/en/static_npc/tatooine/ian_lago.stf', 34, 'npc_noloc_2', 'As it turns out, this Gungan agent thinks it''s too dangerous for anyone to approach his position at the moment. Check back with me later for an update.'),
('string/en/static_npc/tatooine/ian_lago.stf', 35, 'npc_failure_2', 'That''s most unfortunate. That Gungan knew the names and locations of several terrorist cells. That information is lost. Ah well.'),
('string/en/static_npc/tatooine/ian_lago.stf', 36, 'otherescort_2', 'Mesa not for yousa. Yousa looken for other to saven.'),
('string/en/static_npc/tatooine/ian_lago.stf', 37, 'dontknowyou_2', 'Mesa not spek wit yousa. Mesa busy.'),
('string/en/static_npc/tatooine/ian_lago.stf', 38, 'npc_breech_2', 'Ex-squeeze me! Yousa lookin for mesa? Mesa Boona Deeks!'),
('string/en/static_npc/tatooine/ian_lago.stf', 39, 'npc_takeme_2', 'Mesa mooie mooie happy yousa showed up. Big bombad waiten for mesa out dere.'),
('string/en/static_npc/tatooine/ian_lago.stf', 40, 'npc_dropoff_2', 'Oyi, mooie mooie! Mesa yous humble servant.'),
('string/en/static_npc/tatooine/ian_lago.stf', 41, 'npc_smuggle_2', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 42, 'gotowork_2', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 43, 'notit_2', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 44, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 45, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/tatooine/ian_lago.stf', 46, 'player_1_2', 'Yes.'),
('string/en/static_npc/tatooine/ian_lago.stf', 47, 'player_2_2', 'No.'),
('string/en/static_npc/tatooine/ian_lago.stf', 48, 'player_3_2', 'How did he elude his pursuers?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/ian_lago.stf', 49, 'npc_1_3', 'This next assignment will require some amount of discretion. Mal Sikander is convinced that our beautiful Queen has sympathies for the Rebellion. This notion is completely ridiculous. One of Sikander''s agents has managed to acquire some of Her Majesty''s private correspondence. This is unacceptable. Find this traitor, punish him, and retrieve Her Majesty''s personal property.'),
('string/en/static_npc/tatooine/ian_lago.stf', 50, 'npc_2_3', 'I can see you are a being of breeding and discriminating tastes. Be sure to make an example of this traitor. Away with you.'),
('string/en/static_npc/tatooine/ian_lago.stf', 51, 'npc_3_3', 'Is it because you feel you can''t be discreet? Well, perhaps this is for the best.'),
('string/en/static_npc/tatooine/ian_lago.stf', 52, 'npc_4_3', 'Our beloved Queen is above reproach. That is obvious for anyone to see. A form as graceful and delicate as hers could not harbor such foul treachery. Will you serve her?'),
('string/en/static_npc/tatooine/ian_lago.stf', 53, 'npc_backtowork_3', 'Was there something else you wanted from me? Or are you ready to embark upon this mission?'),
('string/en/static_npc/tatooine/ian_lago.stf', 54, 'npc_reward_3', 'Did the traitor beg for his life? I hope this sends a clear message to Sikander and his goons.'),
('string/en/static_npc/tatooine/ian_lago.stf', 55, 'npc_work_3', 'Did you retrieve the Queen''s private property? This matter must be settled soon.'),
('string/en/static_npc/tatooine/ian_lago.stf', 56, 'npc_noloc_3', 'The traitorous thief has gone into hiding. My spies will find him, worry not.'),
('string/en/static_npc/tatooine/ian_lago.stf', 57, 'npc_failure_3', 'Her Majesty''s private correspondence should not be passed around like some sort of cheap court gossip. I am most disappointed by your failure to acquire that disc.'),
('string/en/static_npc/tatooine/ian_lago.stf', 58, 'otherescort_3', 'Don''t know who you''re looking for, friend, but it isn''t me.'),
('string/en/static_npc/tatooine/ian_lago.stf', 59, 'dontknowyou_3', 'I can''t talk right now. I''m on an important mission.'),
('string/en/static_npc/tatooine/ian_lago.stf', 60, 'npc_breech_3', 'I''m on a mission for Mal Sikander. Back off!'),
('string/en/static_npc/tatooine/ian_lago.stf', 61, 'npc_takeme_3', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 62, 'npc_dropoff_3', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 63, 'npc_smuggle_3', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 64, 'gotowork_3', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 65, 'notit_3', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 66, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 67, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/tatooine/ian_lago.stf', 68, 'player_1_3', 'Yes.'),
('string/en/static_npc/tatooine/ian_lago.stf', 69, 'player_2_3', 'No.'),
('string/en/static_npc/tatooine/ian_lago.stf', 70, 'player_3_3', 'Why is this notion ridiculous?'),
('string/en/static_npc/tatooine/ian_lago.stf', 71, 'npc_1_4', 'Ah good, a trusted agent. I do hope you''ve come ready to perform more duties for me. I''ve managed to discover how Sikander''s agent got his filthy hands on the Queen''s property. A so-called wandering troubadour helped the High Inquisitor spy on Her Majesty after gaining our good Queen''s confidence. I need this criminal apprehended and brought back to me. Can you take care of this?'),
('string/en/static_npc/tatooine/ian_lago.stf', 72, 'npc_2_4', 'Excellent. The performer''s name is Ryd Rozen. He''s a coward and will not resist arrest. Be on the lookout, however, for Sikander''s agents.'),
('string/en/static_npc/tatooine/ian_lago.stf', 73, 'npc_3_4', 'I hope you''re not refusing for fear of Mal Sikander. I assure you I can shield you from the High Inquisitor''s wrath.'),
('string/en/static_npc/tatooine/ian_lago.stf', 74, 'npc_4_4', 'Her Majesty is a kind-hearted patron of the arts. No doubt she felt a great swell of pity after hearing this artist perform and likely took him under her wing. Certain unscrupulous individuals take advantage of such kindness.'),
('string/en/static_npc/tatooine/ian_lago.stf', 75, 'npc_backtowork_4', 'This knave is likely to get away if you dally. Shouldn''t you be going?'),
('string/en/static_npc/tatooine/ian_lago.stf', 76, 'npc_reward_4', 'I appreciate your delicate handling of this matter. I''d keep a low profile, just in case Sikander''s agents are lurking about.'),
('string/en/static_npc/tatooine/ian_lago.stf', 77, 'npc_work_4', 'Have you brought in that treacherous troubadour? He is a menace to the court''s security.'),
('string/en/static_npc/tatooine/ian_lago.stf', 78, 'npc_noloc_4', 'There''s been a complication. My spies have lost track of this scoundrel. Check back with me later. He won''t escape us for long.'),
('string/en/static_npc/tatooine/ian_lago.stf', 79, 'npc_failure_4', 'This musician could have provided us with many answers. Your failure to bring him back vexes me.'),
('string/en/static_npc/tatooine/ian_lago.stf', 80, 'otherescort_4', 'I''m sure you''re not looking for me. I haven''t done anything wrong.'),
('string/en/static_npc/tatooine/ian_lago.stf', 81, 'dontknowyou_4', 'Now is not a good time. I''m a bit preoccupied.'),
('string/en/static_npc/tatooine/ian_lago.stf', 82, 'npc_breech_4', 'You looking for a troubadour? Uh, uh, he went that way! You just missed him! Honest!'),
('string/en/static_npc/tatooine/ian_lago.stf', 83, 'npc_takeme_4', 'I''m under arrest? But I''ve done nothing wrong! I''m innocent! I''m just a simple musician! Please don''t hurt me! I''ll come along peacefully!'),
('string/en/static_npc/tatooine/ian_lago.stf', 84, 'npc_dropoff_4', 'Remind me never to get involved in court intrigue again! I hope I make it out of this alive.'),
('string/en/static_npc/tatooine/ian_lago.stf', 85, 'npc_smuggle_4', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 86, 'gotowork_4', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 87, 'notit_4', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 88, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 89, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/tatooine/ian_lago.stf', 90, 'player_1_4', 'Yes.'),
('string/en/static_npc/tatooine/ian_lago.stf', 91, 'player_2_4', 'No.'),
('string/en/static_npc/tatooine/ian_lago.stf', 92, 'player_3_4', 'How did this troubadour gain the Queen''s confidence?'),
('string/en/static_npc/tatooine/ian_lago.stf', 93, 'npc_1_5', 'Just the agent I was hoping to see today. Ready to serve our beloved Queen again? You already know that Her Majesty''s kind heart can create situations that are problematic. You must handle another such situation. Our noble Queen had been aiding some Gungan refugees that have now been implicated in treasonous activities. You must travel to the Gungans'' camp and silence their leader, Yip Kanoos.'),
('string/en/static_npc/tatooine/ian_lago.stf', 94, 'npc_2_5', 'Good. If Kanoos has bodyguards, dispose of them as well. We must protect the Queen''s reputation at all costs.'),
('string/en/static_npc/tatooine/ian_lago.stf', 95, 'npc_3_5', 'I find you refusal to serve Her Majesty both baffling and deeply insulting. I shall have to think on this.'),
('string/en/static_npc/tatooine/ian_lago.stf', 96, 'npc_4_5', 'The brute can tarnish Her Majesty''s sterling reputation by making it seem as if she were aiding and abetting Rebel sympathizers. Will you do it?'),
('string/en/static_npc/tatooine/ian_lago.stf', 97, 'npc_backtowork_5', 'Your briefing is concluded. What else do you require?'),
('string/en/static_npc/tatooine/ian_lago.stf', 98, 'npc_reward_5', 'I''m glad that''s been handled. I may need your services again soon.'),
('string/en/static_npc/tatooine/ian_lago.stf', 99, 'npc_work_5', 'Have you taken care of that Gungan leader? His existence threatens some very important people.'),
('string/en/static_npc/tatooine/ian_lago.stf', 100, 'npc_noloc_5', 'My spies have just informed me that Yip Kanoos has gone into hiding. We''ll find him soon. Check back later for the villain''s coordinates.'),
('string/en/static_npc/tatooine/ian_lago.stf', 101, 'npc_failure_5', 'Kanoos should not have been allowed to live. Now many more Gungans shall have to die to insure Her Majesty is shielded from false allegations.'),
('string/en/static_npc/tatooine/ian_lago.stf', 102, 'otherescort_5', 'Yousa not lookin for mesa. Yousa be needin someone else.'),
('string/en/static_npc/tatooine/ian_lago.stf', 103, 'dontknowyou_5', 'Mesa not knowen yousa. Now go.'),
('string/en/static_npc/tatooine/ian_lago.stf', 104, 'npc_breech_5', 'Mesa no like de Empire! Mesa crunchen de oppressors!'),
('string/en/static_npc/tatooine/ian_lago.stf', 105, 'npc_takeme_5', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 106, 'npc_dropoff_5', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 107, 'npc_smuggle_5', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 108, 'gotowork_5', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 109, 'notit_5', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 110, 'player_reset_5', 'I don''t want this mission right now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 111, 'player_sorry_5', 'I''ll keep working on the mission.'),
('string/en/static_npc/tatooine/ian_lago.stf', 112, 'player_1_5', 'Yes.'),
('string/en/static_npc/tatooine/ian_lago.stf', 113, 'player_2_5', 'No.'),
('string/en/static_npc/tatooine/ian_lago.stf', 114, 'player_3_5', 'Why must the Gungan leader be silenced?'),
('string/en/static_npc/tatooine/ian_lago.stf', 115, 'npc_1_6', 'I wouldn''t want to rely on just any agent for this next mission. You have proven yourself trustworthy and capable. One of Captain Dallows'' lieutenants has been under investigation by Sikander''s agents and was observed traveling to the Gungan swamps on unknown errands. My spies tell me that this officer is suspected of being involved with the Naboo Resistance. It is in everyone''s best interest if this officer were to disappear without a trace. Can I rely on you? '),
('string/en/static_npc/tatooine/ian_lago.stf', 116, 'npc_2_6', 'Excellent. The officer is Lieutenant Leana Kilnar. It''s my understanding that she''s currently on some mission in the wilds. This is most fortunate, wouldn''t you agree?'),
('string/en/static_npc/tatooine/ian_lago.stf', 117, 'npc_3_6', 'You aren''t suddenly becoming squeamish, are you? Developing a conscience at this stage is both overdramatic and inconvenient.'),
('string/en/static_npc/tatooine/ian_lago.stf', 118, 'npc_4_6', 'No, I''ll take care of clearing your name. You''ll be perfectly safe, I assure you.'),
('string/en/static_npc/tatooine/ian_lago.stf', 119, 'npc_backtowork_6', 'This is a pressing matter and needs resolving. Standing there won''t get it done.'),
('string/en/static_npc/tatooine/ian_lago.stf', 120, 'npc_reward_6', 'You have served me well, agent. You will find that I can be quite generous to those loyal to Naboo. It is my hope that we can work together again in the future.'),
('string/en/static_npc/tatooine/ian_lago.stf', 121, 'npc_work_6', 'Did you remove that "obstacle" to Her Majesty''s security? I do hope this matter is resolved quickly.'),
('string/en/static_npc/tatooine/ian_lago.stf', 122, 'npc_noloc_6', 'One moment. It seems that Lt. Kilnar is harder to track down than I had anticipated. Check back with me later for her coordinates.'),
('string/en/static_npc/tatooine/ian_lago.stf', 123, 'npc_failure_6', 'Removing Lt. Kilnar would have quieted things down considerably here at the palace and left Sikander frustrated. Your failure means more work for me.'),
('string/en/static_npc/tatooine/ian_lago.stf', 124, 'otherescort_6', 'I''m not sure who you''re looking for, but it''s not me.'),
('string/en/static_npc/tatooine/ian_lago.stf', 125, 'dontknowyou_6', 'Sorry, I''m on duty at the moment and can''t talk.'),
('string/en/static_npc/tatooine/ian_lago.stf', 126, 'npc_breech_6', 'This is a Royal Security matter! Do not interfere!'),
('string/en/static_npc/tatooine/ian_lago.stf', 127, 'npc_takeme_6', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 128, 'npc_dropoff_6', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 129, 'npc_smuggle_6', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 130, 'gotowork_6', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 131, 'notit_6', ''),
('string/en/static_npc/tatooine/ian_lago.stf', 132, 'player_reset_6', 'I don''t want this mission right now.'),
('string/en/static_npc/tatooine/ian_lago.stf', 133, 'player_sorry_6', 'I''ll keep working on the mission.'),
('string/en/static_npc/tatooine/ian_lago.stf', 134, 'player_1_6', 'Yes.'),
('string/en/static_npc/tatooine/ian_lago.stf', 135, 'player_2_6', 'No.'),
('string/en/static_npc/tatooine/ian_lago.stf', 136, 'player_3_6', 'Will this get me in trouble with the Royal Security Force?'),
('string/en/static_npc/tatooine/ian_lago.stf', 137, 'npc_reset_2', 'How very disappointing. Come back when you can actually finish what you begin.'),
('string/en/static_npc/tatooine/ian_lago.stf', 138, 'npc_reset_3', 'How very disappointing. Come back when you can actually finish what you begin.'),
('string/en/static_npc/tatooine/ian_lago.stf', 139, 'npc_reset_4', 'How very disappointing. Come back when you can actually finish what you begin.'),
('string/en/static_npc/tatooine/ian_lago.stf', 140, 'npc_reset_5', 'How very disappointing. Come back when you can actually finish what you begin.'),
('string/en/static_npc/tatooine/ian_lago.stf', 141, 'npc_reset_6', 'How very disappointing. Come back when you can actually finish what you begin.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 1, 'npc_1_1', 'Slavers are close to finding me. They will likely kill me for I have information regarding their activities in the Outer Rim. Will you not please stop them from enslaving other beings? They are brutal murderers and deserve no pity or mercy.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 2, 'npc_1_2', 'I am told that a technician named Taln Solwind can aid me in contacting the Rebel Alliance. Will you deliver a message to this agent for me?'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 5, 'npc_2_1', 'You seemed most brave, which is why I confided in you. Be warned - slavers are heavily armed and most ruthless. Please take appropriate precautions. '),
('string/en/static_npc/tatooine/ikka_gesul.stf', 6, 'npc_2_2', 'There is no reward great enough for aid such as yours. I can only hope that I am able to repay your kindness some day. Taln is at these coordinates. Please tell no one of this errand.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 8, 'npc_3_1', 'I understand your reluctance. Slavers are dangerous individuals. Only the most brave in the galaxy should attempt to thwart them. I thank you for listening.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 9, 'npc_3_2', 'You have done so much for me already. I am shamed that I had to ask for more help. I will not trouble you further.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 12, 'npc_4_1', 'A terrible man who goes by the name of Orga Presari leads the slavers. His cruelty is exceeded only by his greed. Two bodyguards always accompany him. They are not pleasant individuals.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 13, 'npc_4_2', 'I wish to offer my services to the noble revolutionaries fighting against the Empire and help free my people from Imperial oppression.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 15, 'npc_reward_1', 'Orga''s defeat is a cause for great celebration, citizen. You are truly a champion of the oppressed. I am most grateful. Please accept this small gift, although it is not the equal of your valiant task. I have no credits, but I will make sure to mention your heroics to my friends in the alliance.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 16, 'npc_reward_2', 'I am forever in your debt, citizen. May the Force be with you, always. Please accept this small token of my gratitude. It came from one of the slave girls that was not as lucky as the ones you just freed. I think she would have been honored by you receiving it.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 18, 'player_1_1', 'I''ll stop these slavers.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 19, 'player_1_2', 'Sure, I''ll deliver it.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 21, 'player_2_1', 'I don''t want to involve myself with slavers.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 22, 'player_2_2', 'No thanks.  I''m not interested.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 24, 'player_3_1', 'Who are these slavers?'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 25, 'player_3_2', 'Why do you wish to contact the Alliance?'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 27, 'player_reset_1', 'I no longer want to involve myself with these slavers.  Sorry.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 28, 'player_sorry_1', 'Not yet, but I am still taking care of it.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 29, 'npc_backtowork_1', 'I hope you''re able to stop their threat.  I will be most appreciative.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 30, 'npc_reset_1', 'I understand your reluctance. Slavers are dangerous individuals. Only the most brave in the galaxy should attempt to thwart them. I thank you for listening.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 31, 'cantwork', 'My troubles are most dire, citizen, and would distract you from your current errands. Please seek me out when you''re free.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 33, 'npc_work_1', 'Have the slavers been taken care of yet?'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 34, 'npc_work_2', 'Did Taln get the message?'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 36, 'npc_breech_1', 'You fight to defend slaves? You deserve death!'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 37, 'npc_breech_2', 'Hello there.  A fine day we''re having today, wouldn''t you say?'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 42, 'npc_backtowork_2', 'That''s good to know.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 44, 'npc_reset_2', 'You have done so much for me already. I am shamed that I had to ask for more help. I will not trouble you further.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 46, 'player_reset_2', 'I''ve changed my mind.  I will not be able to do this any longer.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 48, 'player_sorry_2', 'Not yet, but he will soon.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 53, 'dontknowyou_2', 'I wish you a good journey today.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 107, 'npc_smuggle_2', 'I will see to it that your friend is contacted as soon as possible.'),
('string/en/static_npc/tatooine/ikka_gesul.stf', 108, 'next', 'Thank you for aiding me in contacting the Alliance. Perhaps we''ll work together in the future.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 1, 'npc_1_1', 'I could use some help with a private matter, but it might get you into trouble. You don''t have to commit any crimes. But likely you''ll cross some unsavory individuals. Feel like helping an escaped slave? '),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 2, 'npc_1_2', 'Sadelli refuses to leave Tatooine without Soolami, her younger sister.  The poor thing is still in the clutches of the despicable slavers. Sadelli thinks she''s being taken to Jabba the Hut as a gift. I''ve heard what happens to girls who find their way into that slug''s fortress. Won''t you help Soolami?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 3, 'npc_1_3', 'I''ve located Woff. He''s travelling to Jabba''s palace to explain the shortage of slaves that you have caused by your just actions. If you could intercept and "convince" him that the slaving business is not tolerated around here, we would be forever in your debt.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 5, 'npc_2_1', 'You seemed like you had a good heart. The escaped slave is a Twi''lek named Sadelli. She was about to be shipped off to Nal Hutta when she made her escape. With your help, I can get her safely off-planet and away from her captors. They''ll be looking for her, so please be careful.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 6, 'npc_2_2', 'I knew you''d accept! I''m sure that if you hurry, you can catch Soolami before she''s taken to Jabba. Sadelli assures me that the overconfident Woff rarely hires more than one or two thugs to escort his slaves. Please save Soolami!'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 7, 'npc_2_3', 'I knew I could rely on you. Now this might attract the attention of the local authorities. Once that place is a flaming heap, I''d take off. Good luck and go give those slavers a taste of their own medicine!'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 8, 'npc_3_1', 'I understand. I won''t waste any more of your time. '),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 9, 'npc_3_2', 'I''m sorry. I''ve probably asked too much of you. Thanks anyway.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 10, 'npc_3_3', 'I suppose that could get you in trouble with the Imperials. I understand your reluctance to do that.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 12, 'npc_4_1', 'Slavers. The scum of the galaxy. They''re loathsome but quite dangerous. Do you still want to help?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 13, 'npc_4_2', 'A horrible man named Woff B''Tar leads them. They delight in terrorizing the helpless. The galaxy would be better off without them.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 14, 'npc_4_3', 'Probably some of Jabba''s people, I think Jabba wanted to make sure that Woff got to his palace safely.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 15, 'npc_reward_1', 'You''ve done Sadelli and myself a great service. I hope this doesn''t create too many problems for you. Thanks. '),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 16, 'npc_reward_2', 'Thank you again! You''re one in a million, no doubt about that. '),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 17, 'npc_reward_3', 'You''re simply amazing you know that? The galaxy needs more heroes like you. I know the rewards I give you are not much but the slave liberation is funded only on concerned citizen donations.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 18, 'player_1_1', 'That seems like a worthy cause.  I''ll do it.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 19, 'player_1_2', 'I''ve helped her sister, I shall help her as well.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 20, 'player_1_3', 'I''ll make sure Woff won''t bother anyone again.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 21, 'player_2_1', 'No thanks.  That''s just not my style.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 22, 'player_2_2', 'What?  More?  No, I''ve already helped enough.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 23, 'player_2_3', 'Okay, you''re talking about arson here.  I''ll have none of that!'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 24, 'player_3_1', 'What unsavory individuals would I be crossing?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 25, 'player_3_2', 'Who are these slavers?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 26, 'player_3_3', 'Who''s travelling with him?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 27, 'player_reset_1', 'I don''t want to get mixed up in all of this.  Sorry, I can''t do this anymore.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 28, 'player_sorry_1', 'No, I''m still working on a way to save her.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 29, 'npc_backtowork_1', 'I appreciate your willingness to help.  Thank you.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 30, 'npc_reset_1', 'I understand. I won''t waste any more of your time. '),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 31, 'cantwork', 'Sorry, can''t talk right now. It seems we''re both pretty busy.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 32, 'dontknowyou_1', 'Thank you for not being a mean brute!'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 33, 'npc_work_1', 'Has Sadelli been rescued yet?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 34, 'npc_work_2', 'Have you managed to rescue Soolami?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 35, 'npc_work_3', 'Have you put an end to their terror?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 36, 'npc_breech_1', 'Oh me, oh my!  I do so hope no one accosts me!'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 37, 'npc_breech_2', 'Are you a rival slaver..?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 42, 'npc_backtowork_2', 'I appreciate your willingness to help.  Thank you.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 43, 'npc_backtowork_3', 'Ummm... okayyyy... Well, whenever you can do it, just let me know, okay?'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 44, 'npc_reset_2', 'I''m sorry. I''ve probably asked too much of you. Thanks anyway.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 45, 'npc_reset_3', 'I suppose that could get you in trouble with the Imperials. I understand your reluctance to do that.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 46, 'player_reset_2', 'I don''t want to get mixed up in all of this.  Sorry, I can''t do this anymore.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 47, 'player_reset_3', 'I''ve changed my mind.  If I do this, I will be as bad as these criminals.  I cannot do this anymore.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 48, 'player_sorry_2', 'No, I''m still working on a way to save her.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 49, 'player_sorry_3', 'No, their terror still reigns.  I shall overthrow their rule soon enough by burning down their hideout, though.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 50, 'npc_takeme_1', 'Did Jilljoo send you? I''m very frightened! Please don''t let the slavers find me!'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 51, 'npc_takeme_2', 'You are here to take me to my sister! I''m eternally grateful kind stranger.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 53, 'dontknowyou_2', 'Thank you, but I''m waiting to be rescued.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 54, 'next', 'You''ve been a great help. I might need your invaluable help again in the future.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 55, 'npc_breech_3', 'So you are the one that''s been ruining my business these last few days! I will make you regret it!'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 56, 'npc_failure_1', 'I''m sorry, I thought maybe you''d be more helpful.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 57, 'npc_failure_2', 'There''s not much I can say.  You just weren''t very helpful.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 58, 'npc_failure_3', 'I can''t beleive you couldn''t even do that little task for me.'),
('string/en/static_npc/tatooine/jilljoo_jab.stf', 59, 'dontknowyou', 'Thank you for not being a mean brute!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 1, 'npc_1_1', 'I plan to become a new force in Tatooine''s -- shall we say -- less regulated businesses. First I need to make a few contacts. Then there''s only one obstacle to success: Jabba the Hutt. So what do you say? Up for a little risk?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 2, 'npc_1_2', 'I have high hopes that this partnership will make us both a lot of credits. I need you to get a list of security agents in Jabba''s employ, so I can make them a better offer.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 3, 'npc_1_3', 'I have it on good authority that an assassin will try to kill Lady Valarian. If you find and stop him, I feel certain she would be more favorably disposed toward my deal.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 5, 'npc_2_1', 'I always enjoy the company of another high-stakes player. First off, I want you to take this business offer to Lady Valarian. She has as little use for Jabba as I do.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 6, 'npc_2_2', 'You can almost taste those credits, eh? Get to work.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 7, 'npc_2_3', 'Excellent. We''re but a few steps away from our final goal. The assassin was last seen at these locations. Find him before he reaches his target. If he denies working for Jabba, don''t be fooled, he''s an assassin after all.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 8, 'npc_3_1', 'I wouldn''t have thought you were the shy type. I''ll try not to overestimate you again.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 9, 'npc_3_2', 'Getting cold feet, are we? I suppose I''ll just have to get rich without you.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 10, 'npc_3_3', 'If that''s your decision, then I''m afraid our partnership is dissolved.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 12, 'npc_4_1', 'That Hutt is the messiest businessman I''ve ever seen, as well as having atrocious table manners. Not to worry, I have it all planned out. Quite a simple affair, really. Your decision?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 13, 'npc_4_2', 'Through the simplest of means. Take the list from Sil Onda''tek, one of Jabba''s trusted thugs, and bring it to me. Sil may not want to part with it, of course, but I''m sure you can persuade him. Your decision?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 14, 'npc_4_3', 'Jabba, of course. Whoever else would stoop to such a dastardly scheme? How fortuitous that his nefarious deed lets me look out for my future ally. Will you help?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 15, 'npc_reward_1', 'We seem to be laying a foundation for trust. It''s important to know whom you can count on. Don''t you agree?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 16, 'npc_reward_2', 'Good work. We''re one step closer to our goal. Lay low for a bit, and then check back with me.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 17, 'npc_reward_3', 'Excellent. You should seek up Lady Valarian at the Lucky Despot in Mos Eisley. She might have some things she needs help with while I finish things up around here.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 18, 'player_1_1', 'I like the sound of this.  Yes.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 19, 'player_1_2', 'I''ll get them for you.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 20, 'player_1_3', 'I''ll help to get the Lady into our grasp!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 21, 'player_2_1', 'No thanks.  I''m not tangling with Jabba.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 22, 'player_2_2', 'No thanks.  I think I''m being followed by Jabba''s goons.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 23, 'player_2_3', 'Whoa!  First Jabba and now Valarian?  You must be on glitterstim.  No!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 24, 'player_3_1', 'Why is Jabba an obstacle?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 25, 'player_3_2', 'How am I supposed to get this list?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 26, 'player_3_3', 'Who sent this assassin?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 27, 'player_reset_1', 'I''ve changed my mind.  I''m not getting involved in this.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 28, 'player_sorry_1', 'Not yet.  I''m still working on it.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 29, 'npc_backtowork_1', 'Good.  Let''s see that it''s done, alright?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 30, 'npc_reset_1', 'I wouldn''t have thought you were the shy type. I''ll try not to overestimate you again.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 31, 'cantwork', 'Once you''ve finished your current job, see me about some more interesting work.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 32, 'dontknowyou_1', 'No you''re not.  Get out of here before I break yer face, got it?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 33, 'npc_work_1', 'Did her messenger get the info?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 34, 'npc_work_2', 'So, do you have the list yet?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 35, 'npc_work_3', 'Has the assassin been taken care of?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 36, 'npc_breech_1', 'Heyyy... you the one I''m here to meet, huh?'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 37, 'npc_breech_2', 'You picked the wrong side, chump.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 38, 'npc_breech_3', 'You''re from Ungasan? That slimeball set me up! You''re gonna pay for his mistake!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 39, 'notit_1', 'What''s this?  You playing me for a fool?  Give me the stuff!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 42, 'npc_backtowork_2', 'I''m not paying you to sit around a chat!  Get to work!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 43, 'npc_backtowork_3', 'Get on with it then!  It''s not like the assassin is just going to wait for you out in the desert!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 44, 'npc_reset_2', 'Getting cold feet, are we? I suppose I''ll just have to get rich without you.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 45, 'npc_reset_3', 'If that''s your decision, then I''m afraid our partnership is dissolved.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 46, 'player_reset_2', 'No, and I won''t either!  I QUIT!'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 47, 'player_reset_3', 'I''m no longer doing this.  You get off your posterior and do it yourself.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 48, 'player_sorry_2', 'Not yet.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 49, 'player_sorry_3', 'Not yet.  I''m still working on it.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 106, 'npc_smuggle_1', 'I''ll make sure this gets where it''s supposed to.'),
('string/en/static_npc/tatooine/kaeline_ungasan.stf', 107, 'next', 'I''m waiting for a few more things to come together. No doubt I''ll find more work for you later.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 1, 'npc_1_1', 'I''ve been trying to help Tatooine''s slaves get better treatment. This offends a slaver named Drik Bandrik. He framed me for stealing a droid from some Jawas. Turns out these Jawas are violent. They''re after me for revenge. Can you stop them?  If you do I''ll give you some souvenirs I have...'),
('string/en/static_npc/tatooine/kitster_banai.stf', 2, 'npc_1_2', 'Bandrik has planted evidence with Jabba the Hutt that frames me for trying to lead a slave revolt at Jabba''s palace a few years ago. The revolt failed, but Jabba''s still angry. He''s sent a Rodian henchman to get me. Can you stop the assassin?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 3, 'npc_1_3', 'That slaver Drik Bandrik has framed me again -- this time for killing a moisture farmer. I was nowhere near the murder, and I can prove it. But this local vigilante leader, on Drik''s payroll, is leading a mob to lynch me. Please stop them so I can clear my name!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 5, 'npc_2_1', 'That''s great, friend. These Jawas follow a leader called Wittin. They''re not like other Jawas -- they''re mean. Be careful. And thanks!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 6, 'npc_2_2', 'Thanks! The Rodian''s named Deeng. He''s notorious around here as a thug who would kill his own mother. I think he did, actually. Be careful.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 7, 'npc_2_3', 'Thank you! There''s six or eight of them, I think -- local moisture farmers led by a big thug named Sont Toipo. If you stop Toipo, the rest will probably run off. I hope. Try not to hurt them, they''re just farmers.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 8, 'npc_3_1', 'Come on, it''s just a bunch of Jawas! Oh well, I hope you''ll return to help me if you find time.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 9, 'npc_3_2', 'It''s one Rodian! But okay, I understand. I sure hope I can find someone to get this assassin before it''s too late.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 10, 'npc_3_3', 'Oh, oh, oh. I don'' t know what I''ll do now. This is bad!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 12, 'npc_4_1', 'Years ago I had a friend -- a slave, like I was -- who later left Tatooine and became a great Jedi Knight. He died in the Clone Wars. I own some nice mementos from his podracing days. He won the Boonta Eve Classic! Interested in helping me?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 13, 'npc_4_2', 'Once I made a speech about slave treatment in the Mos Espa slave market. Drik found a holo of my speech and had a data slicer copy it into the slave quarters at Jabba''s palace. Looks like I''m inciting his slaves. But I''ve never even been to Jabba''s palace! Can you help me?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 14, 'npc_4_3', 'While I was supposedly killing this farmer, I was in fact rotting in an Imperial jail cell -- arrested for "political agitation," meaning slave rights. They let me go because I was harmless. But I have the arrest record. If you believe me, will you help me clear my name?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 15, 'npc_reward_1', 'That''s great news, friend. Drik Bandrik has been busy framing me for other crimes, though, so check back. Meanwhile, here''s a souvenir helmet worn by my friend when he won the Grand Arena podraces. Thanks!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 16, 'npc_reward_2', 'That''s a relief. But I need to get Drik Bandrik off my tail before this gets any worse. Worse than Jabba! I can''t even think of that. Thanks!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 17, 'npc_reward_3', 'You''ve saved me again, friend! I have a souvenir for you, a droid brain rebuilt by my old friend. He was a real genius mechanic -- once he rebuilt an entire protocol droid. Wonder what he did with that droid?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 18, 'player_1_1', 'I''ll take care of those little thieves!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 19, 'player_1_2', 'Don''t worry, Kitster, I''ll save you.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 20, 'player_1_3', 'I''ll stop them with whatever force is necessary!  Never fear, friend.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 21, 'player_2_1', 'No.  Jawas are just misunderstood people.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 22, 'player_2_2', 'Look, you''ve got to earn your living somehow.  I can''t help you with this.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 23, 'player_2_3', 'I''m not going to try to stop some mob.  Sorry.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 24, 'player_3_1', 'What kind of souvenirs?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 25, 'player_3_2', 'What is the evidence that frames you for the failed slave revolt?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 26, 'player_3_3', 'What''s the proof you didn''t kill the moisture farmer?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 27, 'player_reset_1', 'I''ve changed my mind. I''m actually a bit scared of those little guys.  Sorry.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 28, 'player_sorry_1', 'No, they''re too wily.  I''m still tracking them all down.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 29, 'npc_backtowork_1', 'Thank you, friend.  Let me know when you''ve killed them all.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 30, 'npc_reset_1', 'Come on, it''s just a bunch of Jawas! Oh well, I hope you''ll return to help me if you find time.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 31, 'cantwork', 'Hi there. I''m looking for help, so swing back when you''re not so busy.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 33, 'npc_work_1', 'Have you destroyed all of those little violent creatures?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 34, 'npc_work_2', 'Is the bounty hunter dead?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 35, 'npc_work_3', 'Have you killed the leader of the mob?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 36, 'npc_breech_1', 'Utinni! Nik-nik! Niwaa taa doo!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 37, 'npc_breech_2', 'Jabba sent me to kill a troublemaker. I''ll charge him extra for you!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 38, 'npc_breech_3', 'I don''t care whether Kitster''s guilty. Drik says he''s a troublemaker, and Drik knows best. Get him, guys!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 42, 'npc_backtowork_2', 'I appreciate your kindness.  I would also appreciate if you would be a little more prompt with this too.  It''s only my life and all.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 43, 'npc_backtowork_3', 'Ummm... I appreciate your zeal, but all I''m asking is that the mob is prevented from killing me.  But, you''re the professional here, I guess.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 44, 'npc_reset_2', 'It''s one Rodian! But okay, I understand. I sure hope I can find someone to get this assassin before it''s too late.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 45, 'npc_reset_3', 'Oh, oh, oh. I don'' t know what I''ll do now. This is bad!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 46, 'player_reset_2', 'I''ve come back to tell you that I''m not doing this for you anymore.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 47, 'player_reset_3', 'I''m sorry.  I just remembered that I''m not a murderer.  You''ll have to take care of that yourself.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 48, 'player_sorry_2', 'Not yet.  I just stopped by to say hello.  I''m off to kill him now.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 49, 'player_sorry_3', 'No, the mob leader still breathes.  I will be changing that very soon.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 55, 'dontknowyou_4', 'What?  You don''t like the blistering heat, the parched air, and the burning suns?  Are you crazy?  This is a paradise!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 56, 'dontknowyou_5', 'Never mind.  You''re not the kind of person I thought you were.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 59, 'notit_5', 'What''s this?  I''m not a junk dealer, okay?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 61, 'npc_1_4', 'Remember that Bandrik accused me of killing a moisture farmer? Turns out the farmer''s not dead. Bandrik paid her to leave town long enough for the lynch mob to do its happy work. I found the farmer. Will you bring her here to me?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 62, 'npc_1_5', 'With the help of my friend Krin, I''ve assembled evidence that will clear me of all Drik Bandrik''s fake charges. I thought of sending it to the police -- but I have a much more clever idea. Will you deliver this disk to my slicer friend, Thermal Det?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 64, 'npc_2_4', 'That''s good. I''ll wait here for you. But don''t be surprised if Drik sends his thugs to kill you both. He''s got a lot riding on this now.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 65, 'npc_2_5', 'Great. Thermal''s waiting in the desert, away from Drik''s prying spies. If you bring him this datadisc, he''ll send it where it will do the most good. Don''t worry about Thermal -- he looks weird, but he''s a fine fellow.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 67, 'npc_3_4', 'Well, I hope Krin can find her way here alone. She''s getting on in years, and the desert is pretty tough.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 68, 'npc_3_5', 'Oh, bad! I can practically taste my freedom. I''ll have to find someone else to make this delivery. Thanks anyway.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 70, 'npc_4_4', 'The supposed "victim" is a woman named Krin Vel. She''s been my friend forever. She helped buy me my freedom. I''d never kill her. Will you bring her here safely?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 71, 'npc_4_5', 'I don''t want to give it away -- but police and the Empire have no reason to arrest Drik Bandrik. There''s someone else who does, and Thermal Det can send this evidence straight to that someone. Interested?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 73, 'npc_backtowork_4', 'Okay.... when are you planning on bringing her back?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 74, 'npc_backtowork_5', 'Okay, thanks!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 76, 'npc_breech_4', 'Oh, I missed my beloved Tatooine!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 77, 'npc_breech_5', 'Heya!  You wanna see something cool on the Holonet?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 79, 'npc_reset_4', 'Well, I hope Krin can find her way here alone. She''s getting on in years, and the desert is pretty tough.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 80, 'npc_reset_5', 'Oh, bad! I can practically taste my freedom. I''ll have to find someone else to make this delivery. Thanks anyway.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 82, 'npc_reward_4', 'Thank you! Krin and I will see to it that Drik Bandrik goes to prison for this -- or worse. Hmm, I may need your services again though.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 83, 'npc_reward_5', 'Great job! Thermal sent proof of Drik Bandrik''s fraud straight to Jabba the Hutt. Jabba won''t like it that Drik played him like a dejarik piece. I expect Drik will find it healthy to visit another world soon. Thanks for all your invaluable help, I''m in your debt.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 85, 'npc_takeme_4', 'I had no idea Drik Bandrik was arranging a frame. As soon as I found out, I rushed back here. Please take me to Kitster!'),
('string/en/static_npc/tatooine/kitster_banai.stf', 88, 'npc_work_4', 'Is Krin alright?  Where is she?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 89, 'npc_work_5', 'So, was Thermal able to get this rolling?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 91, 'player_1_4', 'Sure, sounds easy enough.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 92, 'player_1_5', 'Oh, I like clever plans!  Sure, I''ll do it.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 94, 'player_2_4', 'No thanks.  If I can''t kill something, I''m not interested.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 95, 'player_2_5', 'I didn''t hear anything about killing in there.  No, I''m not interested.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 97, 'player_3_4', 'Who is the farmer?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 98, 'player_3_5', 'What''s your clever idea?'),
('string/en/static_npc/tatooine/kitster_banai.stf', 100, 'player_reset_4', 'I''ve changed my mind.  I don''t want to help you anymore.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 101, 'player_reset_5', 'I haven''t killed anything for a while.  I''m dropping this job so I can blow up things.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 103, 'player_sorry_4', 'I haven''t found her yet.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 104, 'player_sorry_5', 'I don''t know.  Once I give it to him, I''ll let you know.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 110, 'npc_smuggle_5', 'Smooth! You got the data? Thanks. This weather out here was about to repave my exterior. I gotta get this onto the ''Net, thanks.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 111, 'next', 'I don''t have anything else for you to do right now. If something comes up later, I''ll let you know.'),
('string/en/static_npc/tatooine/kitster_banai.stf', 112, 'waypoint_name_1', 'Jawa Enforcers'),
('string/en/static_npc/tatooine/kitster_banai.stf', 113, 'waypoint_description_1', 'A band of Wittin''s Jawa Enforcers hunting Kitster Banai.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 1, 'npc_1_1', 'My name is Kormund Thrylle. If you''re in need of work, friend, there is something you could help me with. I have an urgent message I need delivered, but I can''t do it myself. Can you help? '),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 2, 'npc_1_2', 'I have a soldier of the Alliance coming to collect some Imperial documents of utmost importance. He needs help finding me. Maybe you''d be interested in helping me again?'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 5, 'npc_2_1', 'I had a feeling I could count on you. I''ve learned to trust my instincts over the years, and something told me you''d be reliable. Bring this message to Reen Loruk. He needs to be informed of my mission status.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 6, 'npc_2_2', 'Got a taste for espionage now, have you? Excellent. I need you to go find Rodius Tharn. He''s a male Rodian. Bring him back here to pick up the information that I lifted from the Imperials. '),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 8, 'npc_3_1', 'I''m sorry. I thought you wanted to help the Alliance.  My mistake. '),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 9, 'npc_3_2', 'I guess you''ve done your part, and now it''s someone else''s turn. Thanks anyway.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/kormund_thrylle.stf', 12, 'npc_4_1', 'Imperial Security is searching for me. I have important information for the Alliance, and I need you to deliver a message to my contact, to let him know my mission was successful.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 13, 'npc_4_2', 'Imperials are looking all over for me. But once I get this datadisc handed off to the Alliance, I can get arrested twice an hour without risking any information.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 15, 'npc_reward_1', 'You''ve done both the Alliance and myself a great service. '),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 16, 'npc_reward_2', 'You handle yourself pretty well -- you should consider a career in intelligence. Thanks for everything.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 18, 'player_1_1', 'Sure, I''ll do it.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 19, 'player_1_2', 'If this will help you, I''ll do it. Yes.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 21, 'player_2_1', 'Sorry, I''m not interested.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 22, 'player_2_2', 'No, I''m not sure I like what I''m getting myself into.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 24, 'player_3_1', 'Why can''t you deliver it yourself?'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 25, 'player_3_2', 'Why can''t you just go to him?'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 27, 'player_reset_1', 'I''m not sure I want to get entangled in this.  Sorry, I can''t do it.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 28, 'player_sorry_1', 'No, there were Imperials following me.  I think the coast is clear now.  I''m off.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 29, 'npc_backtowork_1', 'I knew you were the right type of person for this job.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 30, 'npc_reset_1', 'I understand.  If you change your mind, you know where to find me.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 31, 'cantwork', 'You have other commitments right now. Come back and see me when you''re not so busy.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 32, 'dontknowyou_1', 'What?  No, that''s not the proper response.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 33, 'npc_work_1', 'Were you able to get into contact with Reen yet?'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 34, 'npc_work_2', 'Where is Rodius?'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 36, 'npc_breech_1', 'Phew, I thought that droid was going to get away and get reinforcements.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 37, 'npc_breech_2', 'They were trying to arrest me on some made up charges! Thank you for your help!'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 42, 'npc_backtowork_2', 'Thank you for your persistence.  This means a lot to me.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 44, 'npc_reset_2', 'I guess you''ve done your part, and now it''s someone else''s turn. Thanks anyway.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 46, 'player_reset_2', 'Some Imperials told me that they would hurt me if I help you.  I can''t help you anymore.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 48, 'player_sorry_2', 'He wasn''t there.  I''m going out to look for him again.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 51, 'npc_takeme_2', 'You here to lead me to where Kormund is hiding out? Good, let''s go. '),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 53, 'dontknowyou_2', 'Huh?  That''s not how you''re supposed to respond to that.  Oh, that means you''re not... Um... bye.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 106, 'npc_smuggle_1', 'Thanks again for taking care of that probe droid. A message from Kormund? That''s good news. We thought he''d been compromised by now. '),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 107, 'next', 'I seem to have everything under control for right now. Come see me again later.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 108, 'player_more_1_1', 'Were you just going to give up on him?'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 109, 'npc_more_1_1', 'Sorry if you think that''s harsh but Kormund knew the risks when he went to work for us.  I can''t babysit every agent we have in the field.  I''m just glad to know he''s alive.'),
('string/en/static_npc/tatooine/kormund_thrylle.stf', 110, 'notyet', 'Please leave. You can''t assist me.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 1, 'npc_1_1', 'Looking for work? Hmm, I''m not sure that my sort of assignments would be appealing to you. I''m in need of much more than a simple courier. I need someone who can make problems disappear. Do you think you can do that?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 2, 'npc_1_2', 'I think another assignment is in order. This time the trouble involves a Rodian spice dealer named Soobu Javeedo, who''s foolishly decided to peddle his wares in my territory without so much as a "by your leave." Can you teach him some proper etiquette?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 3, 'npc_1_3', 'Remember that last little task I gave you? As it turns out, Soobu''s swooper friends were part of a bigger gang. Ever heard of the Desert Banshees? Well, now they''ve heard of you. In fact, they want to meet you. And this is convenient since I was going to hire you to take care of them. What do you say?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 5, 'npc_2_1', 'Perhaps I misjudged you. Very well, here''s my current problem: Una Gitori, a former agent of mine, has decided to expand his horizons by selling information to my rival Jabba. In addition to breaking my heart, Una jeopardizes many of my current business deals. It would be wonderful if you could silence him.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 6, 'npc_2_2', 'You''re quickly becoming "my kind of people." Very good. The task is simple. Find Soobu and make him disappear. He''ll have swooper cronies with him, so watch your back. Those thugs can be a bit rough.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 7, 'npc_2_3', 'I figured you''d be the type to hunt trouble down before it hunts you. A deadly Zabrak named Kilth Saanu leads the Banshees. If you take her out, chances are the rest of the Banshees will scatter. If not, then just blast all of them.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 8, 'npc_3_1', 'My instincts are seldom wrong. Well, in any case, please enjoy yourself. Anyone with a taste for leisure and the credits to back it up is welcome here.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 9, 'npc_3_2', 'Don''t tell me you''ve suddenly become squeamish. I was hoping you''d be a tad more resilient than that. Oh well, can''t have everything.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 10, 'npc_3_3', 'Suit yourself but these girls will probably come looking for you eventually.  Don''t say I didn''t warn you.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 12, 'npc_4_1', 'I don''t know. Would you like to? But now that you mention it, yes. You probably will have to do that. Still interested?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 13, 'npc_4_2', 'I''ll give you three guesses and the first two don''t count. That''s right. It''s the fat slug himself - Jabba.  I hope that doesn''t worry you overmuch. Tales of Jabba''s influence are greatly exaggerated.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 14, 'npc_4_3', 'They aren''t members of Jabba''s regular gangs. I believe the Hutt is "evaluating" the Banshees to see if they are worthy of joining his organization. Perhaps you can help that evaluation along?  '),
('string/en/static_npc/tatooine/lady_valarian.stf', 15, 'npc_reward_1', 'My spies report that you handled that well. Perhaps there''s a career in this for you? Enjoy the fruits of your labors. And have a drink with your friends, compliments of the house.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 16, 'npc_reward_2', 'You took on old Soobu and two of Jabba''s swoopers and lived? You have definitely become "my kind of people." Please accept this small token of my appreciation. I do hope our business relationship continues to flourish.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 17, 'npc_reward_3', 'Don''t cry for me, Desert Banshees. Well done, my ferocious rancor. If I had twenty more like you, I wouldn''t have to worry about that fat Hutt at all. Enjoy your reward.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 18, 'player_1_1', 'I''ve done work like that before, yes.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 19, 'player_1_2', 'I''ll be happy to.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 20, 'player_1_3', 'Two mynocks with one stone, is what I say.  Point me at them.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 21, 'player_2_1', 'I''m not sure I''m cut out for something like that.  No.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 22, 'player_2_2', 'No, I''m not one for teaching.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 23, 'player_2_3', 'No, I''m not good around crowds.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 24, 'player_3_1', 'Would I have to kill anyone?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 25, 'player_3_2', 'Who does Soobu work for?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 26, 'player_3_3', 'Do the Desert Banshees also work for Jabba?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 27, 'player_reset_1', 'Yes, he does.  I don''t think I have what it takes.  Sorry.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 28, 'player_sorry_1', 'Only for now.  This will be corrected soon.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 29, 'npc_backtowork_1', 'Let''s see that it happens.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 30, 'npc_reset_1', 'I see my instincts were wrong. Well, in any case, please enjoy yourself. Anyone with a taste for leisure and the credits to back it up is welcome here.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 31, 'cantwork', 'My tasks require the utmost attention and care. You seem far too busy to give me that at the moment.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 32, 'dontknowyou_1', 'Oh, you''re not a womprat.  Sorry.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 33, 'npc_work_1', 'Does Una still breathe?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 34, 'npc_work_2', 'Has Soobu learned his lesson yet?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 35, 'npc_work_3', 'Have you taken care of the Banshees yet?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 36, 'npc_breech_1', 'Selling information is what I do! Die, womp rat!'),
('string/en/static_npc/tatooine/lady_valarian.stf', 37, 'npc_breech_2', 'Typical of Valarian to send an amateur. Prepare to be educated, fool!  '),
('string/en/static_npc/tatooine/lady_valarian.stf', 38, 'npc_breech_3', 'You''re bantha-fodder! Aieeeeeeeeeee! '),
('string/en/static_npc/tatooine/lady_valarian.stf', 42, 'npc_backtowork_2', 'Make sure he pays attention.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 43, 'npc_backtowork_3', 'And this is why I am paying you.  Carry on.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 44, 'npc_reset_2', 'Don''t tell me you''ve suddenly become squeamish. I was hoping you''d be a tad more resilient than that. Oh well, can''t have everything.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 45, 'npc_reset_3', 'Suit yourself, but these girls will probably come looking for you eventually.  Don''t say I didn''t warn you.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 46, 'player_reset_2', 'I''m sorry, my Lady, but I am too sca -er- busy to do this.  Send someone else to do it.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 47, 'player_reset_3', 'No, I don''t want to kill anymore.  I''m tired of all this killing!'),
('string/en/static_npc/tatooine/lady_valarian.stf', 48, 'player_sorry_2', 'He will be learning it very shortly.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 49, 'player_sorry_3', 'No, they haven''t shown their faces.  When they do, though....'),
('string/en/static_npc/tatooine/lady_valarian.stf', 53, 'dontknowyou_2', 'I don''t have my syllabus, sorry.  I can''t teach you anything right now.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 54, 'dontknowyou_3', 'I said, get away!  You smell like Bantha-fodder.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 55, 'dontknowyou_4', 'When you get a chance, stop by and see how much Jabba will give you for your head.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 56, 'dontknowyou_5', 'But, I don''t want to do business with you, therefore get out of my face.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 61, 'npc_1_4', 'I think you''ve got what it takes to tackle this assignment. I''ve finally discovered who''s been organizing these swoop gangs against me, and I need this slug removed. This time, however, we strike directly at Jabba''s organization. Are you certain you wish to side with me?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 62, 'npc_1_5', 'As expected, Jabba was somewhat offended by the demise of his crony. Word has it that he''s hired a professional assassin to take out Arrud''s killer, and we all know who that was, don''t we? Given that you''re one of my favorite beings in the galaxy, I thought I''d give you a chance to tie up loose ends.   '),
('string/en/static_npc/tatooine/lady_valarian.stf', 63, 'npc_1_6', 'Jabba has sent a hit squad to get rid of yours truly. I suppose it was only a matter of time. The Hutt may be disgusting, but he''s not stupid. He knows the true genius behind these recent strikes. And worse, Governor Aryon is turning a blind eye to this assault on my person. You''ll help your sweet Valarian out of this mess, won''t you?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 64, 'npc_2_4', 'Very well. Your task is to remove Arrud Barsoomu, Jabba''s right-hand enforcer in Mos Eisley. This Twi''lek is a most unpleasant individual - perfectly suited to serving a vile beast like Jabba. Tales of Arrud''s fascination with torture would sicken you. '),
('string/en/static_npc/tatooine/lady_valarian.stf', 65, 'npc_2_5', 'Now that''s the vicious little rancor I''ve come to know and admire. The assassin is a Chadra-Fan named Duska Murgo. She''s awfully fond of IG assassin droids so I''d keep an eye out for those as well. Please hurry back to me.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 66, 'npc_2_6', 'There is no one in the Outer Rim as reliable as you, my little mastmot. The walking cadavers are a group of Weequay, led by a brutish thug named Siron Vurn''ke. Forget whatever you may have heard about Weequay - they''re not as formidable as some would claim, especially not for a vicious killer like you.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 67, 'npc_3_4', 'I don''t hold this against you. In certain circumstances, it is perhaps best to maintain neutrality. Anyone who says otherwise is selling something. '),
('string/en/static_npc/tatooine/lady_valarian.stf', 68, 'npc_3_5', 'Suit yourself. I will find someone to take care of this hired killer, of course. I just fear I may not do it in time to save your life. That thought breaks my heart.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 69, 'npc_3_6', 'I was hoping to avoid having to name names in an effort to appease the Governor, but if that is the only alternative left to me... I''m sorry I won''t able to protect you from the Imperials. I hope you can forgive me.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 70, 'npc_4_4', 'I''m afraid I can''t tell you that until you choose a side. I would hate to have to silence you after we''ve become such good friends.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 71, 'npc_4_5', 'You? Most certainly not. If it were anyone else, I would advise a hasty exit to a heavily fortified stronghold. But you, my little mastmot? You have nothing to worry about. '),
('string/en/static_npc/tatooine/lady_valarian.stf', 72, 'npc_4_6', 'Aryon''s never had much affection for me. She sees me as a troublemaker, someone who risks drawing unwanted Imperial attention. Nothing would please her more than to have me silenced. '),
('string/en/static_npc/tatooine/lady_valarian.stf', 73, 'npc_backtowork_4', 'Serves him right.  I always prefer a simple blaster to the head.  He likes to hear them scream.  A taste of his own medicine, wouldn''t you say?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 74, 'npc_backtowork_5', 'That attitude of yours might slip you up.  I''d hate to see one of my best have such an inglorious death.  Stop by once you have dealt with the matter.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 75, 'npc_backtowork_6', 'I trust in your abilities, my ice tiger.  I know you will make sure that your patron will come to no harm.  Let me know when the threat has passed.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 76, 'npc_breech_4', 'You are Valarian''s "killer?" Jabba will be pleased to have your head!'),
('string/en/static_npc/tatooine/lady_valarian.stf', 77, 'npc_breech_5', 'This is not personal, oafish one - this is strictly business.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 79, 'npc_reset_4', 'I don''t hold this against you. In certain circumstances, it is perhaps best to maintain neutrality. Anyone who says otherwise is selling something. '),
('string/en/static_npc/tatooine/lady_valarian.stf', 80, 'npc_reset_5', 'Suit yourself. I will find someone to take care of this hired killer, of course. I just fear I may not do it in time to save your life. That thought breaks my heart.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 81, 'npc_reset_6', 'I was hoping to avoid having to name names in an effort to appease the Governor, but if that is the only alternative left to me... I''m sorry I won''t able to protect you from the Imperials. I hope you can forgive me.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 82, 'npc_reward_4', 'For better or for worse, we''re now linked, my vicious little rancor. So enjoy your reward and the pleasures of the Lucky Despot. After all, you''re practically family now.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 83, 'npc_reward_5', 'You''ve returned to me, my little ice tiger! I knew you could take care of that pesky diminutive assassin. Did she have those nasty IG droids with her? Poor little mastmot. Come and have a drink. You could definitely use one.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 84, 'npc_reward_6', 'That was perfection itself, my mastmot. Take this dagger. It''s not a weapon, but the badge by which my "employees" recognize my most revered dragons. Now, in order to maintain proper decorum, you and I should limit our contact, at least until I can assuage the Governor''s fears. Farewell, my ice tiger.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 88, 'npc_work_4', 'Has the scum been eliminated?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 89, 'npc_work_5', 'So, have you taken care of your little problem yet?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 90, 'npc_work_6', 'Is the deed done?  Am I still in danger for my life?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 91, 'player_1_4', 'Yes, my Lady, you are a much better bet than that bloated slug!  I''ll help you take on Jabba.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 92, 'player_1_5', 'No one comes after me!  I''ll kill that assassin before she even knows I''m there.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 93, 'player_1_6', 'I would gladly do anything to save your life.  Fear not, my Lady, you will be safe.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 94, 'player_2_4', 'Whoa!  I''m not crossing Jabba!'),
('string/en/static_npc/tatooine/lady_valarian.stf', 95, 'player_2_5', 'What? An assassin after me? Umm... I can''t do it myself, Lady.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 96, 'player_2_6', 'I''m sorry, but I don''t have what it takes to save you.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 97, 'player_3_4', 'Who do you want me to take out? '),
('string/en/static_npc/tatooine/lady_valarian.stf', 98, 'player_3_5', 'Should I be worried about this assassin?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 99, 'player_3_6', 'Why is Governor Aryon turning a blind eye?'),
('string/en/static_npc/tatooine/lady_valarian.stf', 100, 'player_reset_4', 'On second thought, I think I''m going to step out of this.  I don''t want to cross Jabba.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 101, 'player_reset_5', 'I don''t think I''m going to be able to handle this.  I''m going to have to hide instead.  Sorry.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 102, 'player_reset_6', 'I am sorry, my Lady, but I will be unable to protect you any longer.  I hope you understand.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 103, 'player_sorry_4', 'Not yet, but soon.  Very soon.  And it will hurt.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 104, 'player_sorry_5', 'Not yet.  I''m not worried though.  I''ll take care of it in due time.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 105, 'player_sorry_6', 'I have set up a trap for them.  You needn''t worry, my Lady.  Soon, they will not bother you any further.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 106, 'next', 'Now is not the time to renew our association. Perhaps a bit later.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 107, 'npc_breech_6', 'Heh, Wee-Quay!  Kill the interloper!'),
('string/en/static_npc/tatooine/lady_valarian.stf', 108, 'waypoint_name_1', 'Una Gitori'),
('string/en/static_npc/tatooine/lady_valarian.stf', 109, 'waypoint_name_2', 'Soobu Javeedo'),
('string/en/static_npc/tatooine/lady_valarian.stf', 110, 'waypoint_name_3', 'Desert Banshees'),
('string/en/static_npc/tatooine/lady_valarian.stf', 111, 'waypoint_name_4', 'Arrud Barsoomu'),
('string/en/static_npc/tatooine/lady_valarian.stf', 112, 'waypoint_name_5', 'Duska Murgo'),
('string/en/static_npc/tatooine/lady_valarian.stf', 113, 'waypoint_description_1', 'Lady Valarian wants you to eliminate Una Gitori'),
('string/en/static_npc/tatooine/lady_valarian.stf', 114, 'waypoint_description_2', 'Lady Valarian would like you to teach Soobu Javeedo some manners'),
('string/en/static_npc/tatooine/lady_valarian.stf', 115, 'waypoint_description_3', 'Lady Valarian wants you to meet with the Desert Banshees and take them out.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 116, 'waypoint_description_4', 'Lady Valarian wants you to take Arrud Barsoomu out of the action.  He''s Jabba''s right hand thug, so be careful.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 117, 'waypoint_description_5', 'The assassin Duska Murgo has been sent to eliminate you.  Lady Valarian wants you to stay alive.  Do what you must.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 118, 'return_waypoint_description_1', 'Return to Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 119, 'return_waypoint_description_2', 'Return to Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 120, 'return_waypoint_description_3', 'Return to Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 121, 'return_waypoint_description_4', 'Return to Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 122, 'return_waypoint_description_5', 'Return to Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 123, 'return_waypoint_name_1', 'Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 124, 'return_waypoint_name_3', 'Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 125, 'return_waypoint_name_4', 'Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 126, 'return_waypoint_name_5', 'Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 127, 'return_waypoint_name_2', 'Lady Valarian'),
('string/en/static_npc/tatooine/lady_valarian.stf', 128, 'waypoint_name_6', 'Siron Vurn''ke'),
('string/en/static_npc/tatooine/lady_valarian.stf', 129, 'waypoint_description_6', 'Lady Valarian wants you to eliminate the hit squad coming to kill her.  They are a group of Weequay led by Siron Vurn''ke.'),
('string/en/static_npc/tatooine/lady_valarian.stf', 130, 'notyet', 'Yes...What?  Speak with Ind and Kavas.  I don''t deal with just anyone that walks in here.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 1, 'npc_1_1', 'Well, well, a visitor. Hem! Welcome to my humble museum. I am the curator. If you are here regarding the recent theft of a valuable artifact, I am -- hem! -- the one -- hem! Excuse me. -- You may talk to me. Will you pursue the thief and return the artifact?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 2, 'npc_1_2', 'Ah, welcome back. Hem! You helped my little museum greatly in what I now call the Tusken Robe Incident. Might you now handle a similar -- hem! -- regrettable theft? The purloined object is a part of the armor worn by chief miner Melnea Arnthout, one of Tatooine''s -- hem! -- original settlers. Will you go after it?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 3, 'npc_1_3', 'Ah, you are ready for more work? I hoped you would inquire. Hem! Now some thief has stolen a mineral scanner that dates back to the original settlement of Tatooine. It defies understanding why anyone would steal it; it lacks -- hem! -- notable historic or economic value. Can you return it safely?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 5, 'npc_2_1', 'Excellent. The stolen Tusken Raider robe has a hidden homing beacon, as is standard museum procedure. In all likelihood you will find the thief at the designated coordinates. Thank you, thank you!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 6, 'npc_2_2', 'Good. The armor, like the robe you returned earlier, has a tracking beacon that should lead you right to the thief. I speed you on your way!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 7, 'npc_2_3', 'I trust the tracking beacon hidden within the scanner will lead you to the culprit, as always. Please return the item intact.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 8, 'npc_3_1', 'I apologize for my mistake. Please enjoy your visit to my little sanctuary. Hem!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 9, 'npc_3_2', 'Not available just now? I understand. Please enjoy your visit to my little sanctuary. Hem!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 10, 'npc_3_3', 'Very well, I wish you good luck in your other endeavors. Enjoy the museum.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 12, 'npc_4_1', 'The artifact in question is a robe supposedly worn by the Tusken Raider who led the original assault on Fort Tusken centuries ago. The robe''s provenance is questionable, but I know no better candidate. I would -- hem! -- very much like it back.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 13, 'npc_4_2', 'It is the endless dust of this desert. Over the decades I must have inhaled enough to fill a -- hem! -- a binary load lifter. Now, the mission?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 14, 'npc_4_3', 'It is purely a function of budget, I assure -- hem! I must requisition yet more funds for greater anti-theft protection. It is a terrible indictment of Imperial funding priorities, no? Hem! Now as to the mission?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 15, 'npc_reward_1', 'Fine work! The robe appears relatively harmed after its ordeal. These senseless thefts grow ever more frequent. I hope the Empire will grant my petition for an increased theft-control budget.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 16, 'npc_reward_2', 'The armor appears to be in acceptable condition. Thank you again for your exemplary service. I anticipate a budget increase to handle these thefts soon.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 17, 'npc_reward_3', 'This is yet another reason I am in your debt. Perhaps you will spread the word among Imperial authorities that this museum requires a greater budget to prevent theft.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 18, 'player_1_1', 'I will track down this thief for you.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 19, 'player_1_2', 'Sure, I''ll go get it for you.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 20, 'player_1_3', 'I''ll return it safely for you.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 21, 'player_2_1', 'No, this sounds like something for the police.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 22, 'player_2_2', 'You seem to be missing a lot of pieces here.  Maybe you should call the police, rather than asking me.  Sorry.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 23, 'player_2_3', 'No, I''m not doing another one of these repossession jobs for you.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 24, 'player_3_1', 'What is this valuable artifact?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 25, 'player_3_2', 'Why are you coughing? Are you all right?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 26, 'player_3_3', 'Why are you seeing so many thefts at your museum?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 27, 'player_reset_1', 'I''m unabe to find the thief.  I''m sorry, but I''ve given up on this.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 28, 'player_sorry_1', 'No, I haven''t found the thief yet.  Once I do, I''ll bring back the robe for you.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 29, 'npc_backtowork_1', 'I will be waiting.  Thank you for your assistance.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 30, 'npc_reset_1', 'I apologize for my mistake in asking you. Please enjoy your visit to my little sanctuary. Hem!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 31, 'cantwork', 'Welcome to the museum.  We are looking for help.  When you have full time to yourself, come see me.  Hem!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 32, 'dontknowyou_1', 'Ootini!  Din kandanii.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 33, 'npc_work_1', 'Hem!  Have you found the robe?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 34, 'npc_work_2', 'Have you been successful in retreiving the armor?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 35, 'npc_work_3', 'Has the tracking beacon been helpful in finding the scanner?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 36, 'npc_breech_1', 'Utinni! Nik maikka dinnika Dinhint!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 37, 'npc_breech_2', 'Hmm. Has that lickspittle of a curator changed his mind? I shall not cancel our arrangement. Rather, I shall cancel you.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 38, 'npc_breech_3', 'You are the fence? Late! Dinhint did say right about how much valuable is this hunk of junk, yes? Wait! You are not --!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 39, 'notit_1', 'No, no.  This is not the artifact!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 40, 'notit_2', 'The display piece that was stolen did not look like this.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 41, 'notit_3', 'This is not the scanner.  The one that was part of the museum was quite old.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 42, 'npc_backtowork_2', 'Well, I hope you will be able to find it.  That was a priceless relic!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 43, 'npc_backtowork_3', 'This is good news.  All these thefts lately are looking very bad for the museum.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 44, 'npc_reset_2', 'Not available just now? I understand. Please enjoy your visit to my little sanctuary. Hem!'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 45, 'npc_reset_3', 'Very well, I wish you good luck in your other endeavors. Enjoy the museum.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 46, 'player_reset_2', 'I''ve had something come up.  Can I look for it later?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 47, 'player_reset_3', 'I will not be able to help with this right now.  Perhaps later?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 48, 'player_sorry_2', 'I haven''t managed to wrest the armor from the thief yet.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 49, 'player_sorry_3', 'Yes, it has.  I now know the location and am about to recover it.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 53, 'dontknowyou_2', 'What?  You''re not working for the curator?  My mistake.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 54, 'dontknowyou_3', '..not the person I thought you were.  Sorry about that.  If you see the fence, let him know I''m waiting, okay?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 55, 'dontknowyou_4', 'Whew!  I thought you were about to try to take this back.  Well, be careful out here in the wastes.  Good journeys.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 58, 'notit_4', 'Thank you, but this is not the piece from the display.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 61, 'npc_1_4', 'It defies belief, my friend, but -- hem! -- my museum is once again the victim of theft. I have no idea who would steal this artifact -- but the Hutts have many enemies, hem! So it is not inconceivable -- but I am maundering. Will you retrieve the artifact?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 64, 'npc_2_4', 'Splendid. You will recall, of course, that all museum artifacts have tracking beacons. It is fortunate the thieves never think to disable these! Please locate the thief and return the artifact by any means.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 67, 'npc_3_4', 'Understandable. I wish you well in your travels around our world.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 70, 'npc_4_4', 'When the Hutts first arrived on Tatooine, long ago, they held a mass slaughter and subsequent feast. The artifact is, as best we can tell, a chunk of dried meat left over from that initial feast. Will you retrieve it?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 73, 'npc_backtowork_4', 'Well, I hope you are able to soon.  The display location looks quite empty without it sitting there.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 76, 'npc_breech_4', 'I know you! Hanging around the museum, right? Tell Dinhilt this is no gemstone. You won''t believe this, but -- Hey, what are you do--?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 79, 'npc_reset_4', 'Understandable. I wish you well in your travels around our world.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 82, 'npc_reward_4', 'Thank you indeed! I daresay the museum''s collection would not be perceptibly harmed by the absence of this meat. But as a matter of principle, we must not tolerate artifact theft -- a point I hope the Imperial budget committee remembers when they allocate funds.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 88, 'npc_work_4', 'Wonderful!  You have the artifact in your possession, do you not?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 91, 'player_1_4', 'I''ve recovered all the rest you''ve sold -er- lost, no reason to stop now.  Sure, I''ll get it back.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 94, 'player_2_4', 'I''ve realized what''s going on here, and I don''t want any part of it anymore.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 97, 'player_3_4', 'What kind of artifact is it?'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 100, 'player_reset_4', 'I''ve been thinking long and hard, and realize I don''t want to be involved in this any longer.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 103, 'player_sorry_4', 'No, not yet.  I still haven''t been able to track down that dastardly bandit.'),
('string/en/static_npc/tatooine/lilas_dinhint.stf', 104, 'next', 'The museum is running smoothly again. If I need more help later I''ll gladly hire you again.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 1, 'player_1_1', 'I''d be happy to help.  Yes, I''ll do it!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 2, 'player_1_2', 'It sounds easy enough.  Sure, I''ll do it!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 3, 'player_1_3', 'I''ll teach him some manners, don''t worry.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 4, 'player_1_4', 'Tuskens?  Where?  Yes, I''ll definitely help!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 5, 'player_2_1', 'No thanks.  That sounds like something you''d be better able to handle.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 6, 'player_2_2', 'I did the first one as a favor.  I''m not pest control, Lorne.  No.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 7, 'player_2_3', 'Sorry, but I''m not some goon.  I''m not roughing any one up.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 8, 'player_2_4', 'Lorne, I don''t see any Tuskens anywhere.  Are you sure you haven''t been out in the suns too long?  I''m afraid I can''t help with this.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 9, 'player_3_1', 'What''s all the commotion?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 10, 'player_3_2', 'I thought I already took care of the problem.  What happened?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 11, 'npc_1_1', 'Welcome to Mos Taike!  I''m Lorne Prestar, Chief of Security for this town.  You look like an able enough person.   I''m getting reports that there''s a wild worrt that''s beginning to harass some of the locals.  Do you think you can lend a hand in taking care of this for me?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 12, 'npc_1_2', 'Hey, I was looking for you!  I need your help again, kid.  Since you did such a good job last time, I need you to take out another critter for me.  Leave it to the specialists, I always say.  It looks like there''s a mutant mound mite out there that''s causing even bigger trouble this time.  Do you think you can take care of this one for me?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 13, 'npc_1_3', 'I''ve got another job for you if you''re interested.  It seems we have a troublemaker that thinks it''s fun to rough up other people.  I''m not having that.  Go find the guy and let him know how much we don''t like troublemakers around here, okay?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 14, 'npc_1_4', 'Soldier, I need your help!  Are you listening?  We have a desperate situation here, and we''re going to have to pull together to get out of this alive!  You understand!?  Listen.  We''ve got a Tusken War Party advancing on our location, and I need to send you to take up an open front!  Are you prepared, rookie?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 15, 'npc_2_1', 'That''s the spirit!  Go out there and show that worrt who''s the master around here.  Well, in a manner of speaking, heh.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 16, 'npc_2_2', 'That''s what I wanted to hear, kiddo!  You get out there and make short work of the mite that''s causing these problems.  Put it out of it''s misery... the things'' probably mad with hunger, I''ll bet.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 17, 'npc_2_3', 'Good.  Go find the guy and explain to him that he''s not wanted around here.  If he''s belligerent, you''re allowed to use force to get your point home.  If he doesn''t listen to even that... well, just make sure he doesn''t bother anyone else again, if you can read between the lines.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 18, 'npc_2_4', 'Affirmative to that.  I have the other troops - er - guards set out on all fronts.  You need to defend our weak front.  Get out there and you show them Tuskens all you''ve got, you hear me?  And, kid, don''t get yourself killed, got it?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 19, 'npc_3_1', 'Well, I can understand that.  I can''t expect just anyone to have the courage to do it.  Well, try not to get your hands too dirty around here.  I don''t want to see you break a nail, or claw, or whatever...'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 20, 'npc_3_2', 'Hmm... maybe a I had you wrong, kid.  I thought you had guts of plasteel, but I guess not.  Well, I''ll just have to do it myself... like a real man.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 21, 'npc_3_3', 'Hmm... I understand.  This is more a job for someone who wants to do real work.  Thanks for your previous help, though.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 22, 'npc_3_4', 'Look!  You must do this!  If you don''t, we will lose this war - er - this battle!  It''s all or none!  Got that?  I''ve seen too many kids like you just freeze when you need to pull the trigger.  Don''t let your fear freeze you, kid!  Please tell me you''ll pull your weight out here!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 23, 'npc_4_1', 'Well, about a few weeks back a tourist tells me he saw a worrt lurking too close to town.  Well, I thought nothing of it, until a hear from a few tourists that they were attacked by what I''m assuming to be the same critter.  I can''t have that going on in my town, but I don''t have time to take care of it myself.  So, can you do this for me?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 24, 'npc_4_2', 'Gramm tells me that a Sand Dragon ''Fresher sales rep was attacked by a beast the other day on his way here.  Now, either we have a problem with the local critters, or we got the wrong beast the last time around.  Either way, I''m not going to have innocent casualties turning up on my watch!  Can you take care of this for me?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 25, 'npc_4_3', 'I have several witnesses that say the guy was seen smacking around Igma Korto''s friend the other day.  Now, her friend works for the Corellian Times, and I don''t want them thinking I run a slipshod starship out here in Mos Taike.  That''s why this thug needs to be taught a lesson in manners.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 26, 'npc_4_4', 'This is no time for questions, kid!  Scouts show Tuskens are converging on Mos Taike even as we speak!  We act now or we lose everyone like we did back in the jungles of Naboo 20 years back!  So many people died that day under my command, and I''m not having it again!  Kid, get out there and don''t get yourself killed!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 27, 'npc_reward_1', 'You''ve got gusto, kid!  I like that!  Now that the worrt is going to be something''s dinner tonight, hopefully I won''t have to hear any more whining from the tourists.  Bah.  They scare too easy.  That''ll get you killed, I tell you.  Well, kid, I thank you for getting this done.  I''ll look you up if anything comes up.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 28, 'npc_reward_2', 'You got rid of the beast, right?  Good to hear, good to hear.  Go stop by the cantina and get your self a stiff drink.  You deserve it, kiddo!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 29, 'npc_reward_3', 'I''m going to assume he listened and you drove him out of town, okay?  What goes in the desert STAYS in the desert, you know what I mean?  Good.  Sheesh!  First the critters, now ruffians.  What next?  Well, you''ve helped out a lot, kid.  Stop by after you''ve finished another tour of - *sigh* - I mean, seen the world a little more, got it?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 30, 'npc_reward_4', 'Kid, you did me proud!  You came back in one piece.  We lost a few guys, but we saved the town...  Finally, I''ll be able to sleep at night without waking up screaming from all those memories.  Kid, I owe you.  I owe you.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 32, 'player_3_3', 'What did the guy do?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 33, 'player_3_4', 'What''s going on here, Lorne?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 34, 'player_reset_1', 'I don''t think I can kill this worrt, Lorne.  It might eat me.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 35, 'player_reset_2', 'To tell you the truth, I''m a bit scared of those things.  I can''t do this job for you.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 36, 'player_reset_3', 'I''ve been called elsewhere and can''t take care of this right now.  Sorry, Lorne.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 37, 'player_reset_4', 'Sir, I can''t do it!  It''s too much for me!  I''ve never seen that many!  They''re everywhere!!!!  It''s like... it''s like... it''s like they''re not human!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 39, 'npc_reset_2', 'Well, the first thing you learn out there is to listen to your fear.  The next is to control it.  Once you have it strapped up, you come back and let me know you''ll do it, okay?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 40, 'npc_reset_3', 'Hey, I understand.  You''re still green, kid, and this is no kinda job for you.  If you find that you''re made of stronger stuff, you just let me know, got it?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 41, 'npc_reset_4', 'Well, kid, it''s because they''re not!  Pull yourself together, kid!  You''ve got to come to!  Without you, we''ll lose this fight.  Once you''ve got your head on straight, you come back and I''ll give you further orders.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 42, 'npc_backtowork_1', 'That''s what I want to hear!  Good hunting!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 43, 'npc_backtowork_2', 'Well, it shouldn''t be too much of a problem for someone like you.  Get out there and show it what you''ve got!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 44, 'npc_backtowork_3', 'Well, remember, there''s no need to go killing anyone.  At the same time, you''ve gotta defend yourself if the situation calls for it.  Let me know how it turns out.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 45, 'npc_backtowork_4', 'That, kid, is what I call guts of steel!  Get out there and win this one for the Prestar!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 47, 'npc_work_2', 'So, how goes your mite hunt?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 48, 'npc_work_3', 'So, have you had a little talking to with this hoodlum yet?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 49, 'npc_work_4', 'You''ve already taken care of those Raiders?  You''re better than I thought, kid!  You deserve a medal!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 50, 'player_sorry_1', 'No, I haven''t found it.  Once I do, though, you can be assured it won''t harrass any other people.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 51, 'player_sorry_2', 'It''s going good.  I''m just about to find where it''s feeding area is, then get rid of it.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 52, 'player_sorry_3', 'Not yet.  I guess he knows he''s in trouble and is scared to face me.  Once I spot him, though, we''ll have our little talk.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 53, 'player_sorry_4', 'Ummm... yeah, I took them out, but... ummm... there are more of them.  I''ve come back for a little breather.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 54, 'cantwork', 'Welcome to Mos Taike!  I''m Lorne Prestar, Chief of Security for this town.  You look like an able enough person.  If you''re in need of a job, I might have work for you.  Just stop by and let me know, okay?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 59, 'dontknowyou_3', 'Yeah, that''s what I thought.  Walking away like a coward!  Coward!  You''re not even worth my time!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 62, 'npc_breech_3', 'Hey!  What''re you looking at, huh?  You looking at me?  You got a problem, huh?  I''ll give you a problem!'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 63, 'npc_work_1', 'So, have you dispatched that worrt yet?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 64, 'npc_reset_1', 'Still a little wet behind the ears, huh?  Well, you just let me know when you''ve seen a little more of this world then, okay?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 65, 'next', 'It''s pretty quiet around here right now. It never lasts though. Come see me later.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 66, 'npc_failure_1', 'That worrt must have been tougher than he looked.  Or maybe you''re not as tough as you look?'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 67, 'npc_failure_2', 'Man, I thought surely you''d take that mound mite down no problem.  I must be getting old.  My eyesight must be going.  I thought you looked tough.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 68, 'npc_failure_3', 'Guess I should have sent Bren, or at least someone who could handle themselves in a fight.  Oh well.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 69, 'npc_failure_4', 'Hm..tuskens are tough enough sure, but I thought you had the skills.  Well, maybe not...'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 70, 'npc_breech_4', 'Grr...'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 71, 'npc_breech_1', '<a worrt looks anxious>');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/lorne_prestar.stf', 72, 'npc_breech_2', '<a mound mite looks angry>'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 73, 'waypoint_name_1', 'Wild Worrt'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 74, 'waypoint_name_2', 'Mutant Mound Mite'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 75, 'waypoint_name_3', 'Trouble Maker'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 76, 'waypoint_name_4', 'Tusken War Party'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 77, 'waypoint_description_1', 'Destroy the Wild Worrt that''s been harrassing people.'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 78, 'waypoint_description_2', 'Take care of the Mutant Mound Mite'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 79, 'waypoint_description_3', 'Make sure the Trouble Maker doesn''t bother anyone else'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 80, 'waypoint_description_4', 'Find and Destroy the Tusken War Party'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 81, 'return_waypoint_name_2', 'Lorne Prestar'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 82, 'return_waypoint_name_1', 'Lorne Prestar'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 83, 'return_waypoint_name_3', 'Lorne Prestar'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 84, 'return_waypoint_name_4', 'Lorne Prestar'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 85, 'return_waypoint_description_1', 'Return to Lorne Prestar to complete your mission'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 86, 'return_waypoint_description_2', 'Return to Lorne Prestar to complete your mission'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 87, 'return_waypoint_description_3', 'Return to Lorne Prestar to complete your mission'),
('string/en/static_npc/tatooine/lorne_prestar.stf', 88, 'return_waypoint_description_4', 'Return to Lorne Prestar to complete your mission'),
('string/en/static_npc/tatooine/lt_harburik.stf', 1, 'npc_1_1', 'A gangster working for the Hutts has assaulted an officer, stolen Imperial secrets, and is racing to sell them to the Rebellion. Will you stop him?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 2, 'npc_1_2', 'Another troublemaking alien is agitating for equal rights. I don''t think so! Bring him here for discipline. '),
('string/en/static_npc/tatooine/lt_harburik.stf', 3, 'npc_1_3', 'Stormtrooper TD-334 was caught in a radiation accident and is now displaying unorthodox behavior. Apprehend him without committing undue harm.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 5, 'npc_2_1', 'Good. Arrest Wend Dinard and bring him here. We need to know what secrets he compromised. Move!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 6, 'npc_2_2', 'This one has no record of violent behavior, but he travels with fanatical supporters. Who knows what they''re capable of? Be careful, but bring him back.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 7, 'npc_2_3', 'Good. We''ve kept this matter confidential. It''s possible other troopers may misunderstand the situation. Don''t betray secrecy. Just try to escape without undue combat, and bring TD-334 here.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 8, 'npc_3_1', 'Get out! And don''t bother me again!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 9, 'npc_3_2', 'Are you one of those agitators too? Get out!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 10, 'npc_3_3', 'You''re wasting my time. Get out.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 12, 'npc_4_1', 'His name''s Wend Dinard. Human, but works for aliens -- makes me sick. Dinard travels in the company of known thugs, so be ready with your weapons. What''s your decision?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 13, 'npc_4_2', 'Some kind of freak. Name''s Dowwop, or something equally stupid. He wants the Empire to create alien-only police patrols for alien settlements. Will you arrest this nitwit? '),
('string/en/static_npc/tatooine/lt_harburik.stf', 14, 'npc_4_3', 'The trooper was guarding a reactor repair facility when Rebels blew it up. TD-334 was the only survivor. What''s your decision?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 15, 'npc_reward_1', 'About time. Here''s your reward. That''s all for now.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 16, 'npc_reward_2', 'You can be proud of your role in asserting the galaxy''s natural order. Now I''ll have a long chat with this idiot. You can go now.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 17, 'npc_reward_3', 'I think there was no good way this could have turned out. Take your reward, and we''ll pretend this never happened.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 18, 'player_1_1', 'Yes, I''ll stop him for you.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 19, 'player_1_2', 'Absolutely, sir!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 20, 'player_1_3', 'I''ll see to it that he''s brought into custody safely.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 21, 'player_2_1', 'No, that''s your kind of job, not mine.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 22, 'player_2_2', 'But aliens should have equal rights!  I''m not going to help with something like this!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 23, 'player_2_3', 'Are you crazy?  I''m not going to apprehend a Stormtrooper!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 24, 'player_3_1', 'Who is the gangster?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 25, 'player_3_2', 'Who is this alien agitator?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 26, 'player_3_3', 'What happened to the unorthodox Stormtrooper?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 27, 'player_reset_1', 'It''s because I''m just not cut out for the life of an officer of the law.  Sorry, I can''t do this for you.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 28, 'player_sorry_1', 'Because he''s too wily for me.  Don''t worry, I''ll catch him!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 29, 'npc_backtowork_1', 'Don''t let him get the best of you!  Get out there and catch your man!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 30, 'npc_reset_1', 'Get out! And don''t bother me again!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 31, 'cantwork', 'You think you can just wander in here and chat with the Chief of Police? Unless you have services to offer, get out of here or I''ll have you arrested.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 32, 'dontknowyou_1', 'Whoa.  Um... I wasn''t really serious about that.  Sorry.  Please don''t hurt me.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 33, 'npc_work_1', 'Where is he?  How come I don''t see him?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 34, 'npc_work_2', 'So where is the scum I told you to arrest?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 35, 'npc_work_3', 'Don''t tell me you blew it and wound up killing him!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 36, 'npc_breech_1', 'Bah! Those guys called themselves bodyguards!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 37, 'npc_breech_2', 'Sigh, all this violence.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 38, 'npc_breech_3', 'I think purple highlights would give these helmets a bold statement.  No... not purple... LAVENDER!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 42, 'npc_backtowork_2', 'Then what are you doing here?  Get out there and get him!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 43, 'npc_backtowork_3', 'Have you been affected by the radiation, too?  The next time I see you, you had best have that Stormtrooper in your custody.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 44, 'npc_reset_2', 'Are you one of those agitators too? Get out!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 45, 'npc_reset_3', 'You''re wasting my time. Get out.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 46, 'player_reset_2', 'I''ve come to realize that aliens are people too!  I can''t take part of this.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 47, 'player_reset_3', 'I''m not going to get in trouble with the Imperials by arresting a stormtrooper.  Have someone else do it.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 48, 'player_sorry_2', 'I don''t have him yet.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 49, 'player_sorry_3', 'Okay, I won''t tell you that then.  I''ll tell you that he asked me to stop by later to arrest him.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 50, 'npc_takeme_1', 'Okay okay, I know when I''m out of options. I''ll come along quietly.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 51, 'npc_takeme_2', 'I apologize for my friends, they are a bit overprotective. I want these changes made in a peaceful manner but your Empire is not making it easy for us.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 52, 'npc_takeme_3', 'Don''t stop me! I''m leaving the Army to become an image designer! I always wanted to be an image designer.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 53, 'dontknowyou_2', 'Spread this message to all you know and you will find peace within yourself.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 54, 'dontknowyou_3', 'Oh, I didn''t see you there.  Um... Citizen, return to your home.  There''s nothing to see here.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 55, 'dontknowyou_4', 'Oh, you''re not going to kill me?  That''s a relief!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 61, 'npc_1_4', 'A filthy spy is heading to Bestine.  Supposedly reporting on a certain matter to Prefect Talmont. Arrest the spy before something happens to our "little Moff." If the spy happens to accidentally die en route, rest assured there''s no one more deserving.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 64, 'npc_2_4', 'The spy is a blasted smuggler named Noda Lovan. Kill -- I mean, make the arrest and you''ll be doing the galaxy a favor. Go!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 67, 'npc_3_4', 'Get out. And don''t tell anyone about this, or it will go badly for you.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 70, 'npc_4_4', 'Charge? How should I --? Well, say the spy''s stolen Imperial secrets. That''s not far from the truth. Your decision?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 73, 'npc_backtowork_4', 'Well, what are you waiting for?!  Get out there before I have *you* arrested!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 76, 'npc_breech_4', 'I''ll bet that thug Harburik sent you. He''s killed enough folks already, why not me too?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 79, 'npc_reset_4', 'Get out. And don''t tell anyone about this, or it will go badly for you.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 82, 'npc_reward_4', 'You got the spy all the way here, huh? No fatal accidents presented themselves? Well, here''s your reward. Get out, and don''t come back.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 85, 'npc_takeme_4', 'I guess I''ll go with you quietly. You better pray that I won''t get out of prison though, or I will find you one day when I''m better prepared.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 88, 'npc_work_4', 'I take it you didn''t have any trouble?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 91, 'player_1_4', 'I''ll get this spy and return!'),
('string/en/static_npc/tatooine/lt_harburik.stf', 94, 'player_2_4', 'I''m not authorized to arrest spies.  Sounds like an Imperial job to me.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 97, 'player_3_4', 'On what charge could I arrest this spy?'),
('string/en/static_npc/tatooine/lt_harburik.stf', 100, 'player_reset_4', 'I''ve had something come up.  You''re going to have to call in Imperial support for this one instead.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 103, 'player_sorry_4', 'No, I haven''t found the spy yet.  Don''t worry, I''ll get right on it.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 104, 'next', 'That''s all the work I have for now. Check back another time.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 105, 'npc_failure', 'Dead? What were you thinking? I can''t question a corpse! Sigh, it''s so hard to find good help now a days.'),
('string/en/static_npc/tatooine/lt_harburik.stf', 106, 'notyet', 'I only have use for loyal soldiers of the Empire, please leave.'),
('string/en/static_npc/tatooine/mat_rags.stf', 1, 'npc_1_1', 'If you''re interested in becoming a hunter, I might have a little job for you -- just to show your aptitude, you understand. Up for it?'),
('string/en/static_npc/tatooine/mat_rags.stf', 2, 'npc_1_2', 'I have another job for you. An offworlder wants to take a hunting trophy back home with him. It''s the sort of thing that I wouldn''t trouble myself with, but as your mentor, I encourage you to do all the fieldwork you can. What do you say?'),
('string/en/static_npc/tatooine/mat_rags.stf', 3, 'npc_1_3', 'I was offered another commission recently, one well beneath the abilities of myself, to whom even the biggest krayt is a simple afternoon''s diversion. You might find it a tad interesting, though.'),
('string/en/static_npc/tatooine/mat_rags.stf', 5, 'npc_2_1', 'That''s the spirit. Head into the desert and find a squill for the Jawas. They wanted the meat, as I recall, so be sure to bring back the carcass.'),
('string/en/static_npc/tatooine/mat_rags.stf', 6, 'npc_2_2', 'Good show! Bring back the hide from a variegated womp rat, and we''ll make a professional hunter of you yet.'),
('string/en/static_npc/tatooine/mat_rags.stf', 7, 'npc_2_3', 'You certainly have gumption. I admire that, really. Track down a matriarch bantha and bring back the horns for our client. Foul beast, the bantha. Honestly, I wonder about people''s taste in d'),
('string/en/static_npc/tatooine/mat_rags.stf', 8, 'npc_3_1', 'Don''t feel up to it? I guess you don''t have what it takes to be a real hunter. '),
('string/en/static_npc/tatooine/mat_rags.stf', 9, 'npc_3_2', 'Are you sure you''re serious about this line of work? You don''t seem to have the dedication of a hunter.'),
('string/en/static_npc/tatooine/mat_rags.stf', 10, 'npc_3_3', 'Probably a wise decision. I expect that last creature was about the limit of your skills. '),
('string/en/static_npc/tatooine/mat_rags.stf', 12, 'npc_4_1', 'Some Jawas recently approached me about killing a desert squill. Far beneath my abilities, of course, but a good test of your basic skills. '),
('string/en/static_npc/tatooine/mat_rags.stf', 13, 'npc_4_2', 'Apparently he wants the hide of a variegated womp rat. Why anybody would want one of those filthy biters is beyond me, but there you are. Your decision?'),
('string/en/static_npc/tatooine/mat_rags.stf', 14, 'npc_4_3', 'I''ve been asked to get another trophy item -- a matriarch bantha. It''s the sort of trivial job I like to pass down to younger hunters who really need the work.'),
('string/en/static_npc/tatooine/mat_rags.stf', 15, 'npc_reward_1', 'I say! You do seem to have passable basic skills. I might consider taking you on as a pupil. I''ll let those Jawas know their meat is ready for them.'),
('string/en/static_npc/tatooine/mat_rags.stf', 16, 'npc_reward_2', 'Bagged the beastie, did you? Smashing good job there, old desert rat. Why, one day your name may be known with the same reverence as mine!'),
('string/en/static_npc/tatooine/mat_rags.stf', 17, 'npc_reward_3', 'That''s just the ticket!'),
('string/en/static_npc/tatooine/mat_rags.stf', 18, 'player_1_1', 'Yeah, I''m up for it.'),
('string/en/static_npc/tatooine/mat_rags.stf', 19, 'player_1_2', 'I''ll kill whatever you want me to!'),
('string/en/static_npc/tatooine/mat_rags.stf', 20, 'player_1_3', 'Ha!  I''ll kill it blindfolded!!!  With one hand tied behind my back, too!  No, both hands!!!!!'),
('string/en/static_npc/tatooine/mat_rags.stf', 21, 'player_2_1', 'No thanks.  I''m scared.'),
('string/en/static_npc/tatooine/mat_rags.stf', 22, 'player_2_2', 'If this is anywhere as dangerous as the last one, count me out!'),
('string/en/static_npc/tatooine/mat_rags.stf', 23, 'player_2_3', 'Okay, you just said ''krayt''.  I''m outta here.'),
('string/en/static_npc/tatooine/mat_rags.stf', 24, 'player_3_1', 'What sort of job?'),
('string/en/static_npc/tatooine/mat_rags.stf', 25, 'player_3_2', 'What are we after this time?'),
('string/en/static_npc/tatooine/mat_rags.stf', 26, 'player_3_3', 'What is the prey this time?'),
('string/en/static_npc/tatooine/mat_rags.stf', 27, 'player_reset_1', 'I saw that squill, and it''s HUGE!!!  You''re crazy to send me out against something like that!'),
('string/en/static_npc/tatooine/mat_rags.stf', 28, 'player_sorry_1', 'No, that squill has so far managed to elude my tracking skills.  I''ll get one for the Jawas, don''t worry.'),
('string/en/static_npc/tatooine/mat_rags.stf', 29, 'npc_backtowork_1', 'Whatever.  I''ll be surprised if you can get this done at all.'),
('string/en/static_npc/tatooine/mat_rags.stf', 30, 'npc_reset_1', 'You''ve got to be kidding me.  Well, before you trying hunting squill, you may need to track down a spine.  I''m sure that will help.'),
('string/en/static_npc/tatooine/mat_rags.stf', 31, 'cantwork', 'You have another employer at the moment. But if you''re serious about hunting, see me when you have some free time.'),
('string/en/static_npc/tatooine/mat_rags.stf', 33, 'npc_work_1', 'So, are those little beasties feasting on the that squill yet?\n'),
('string/en/static_npc/tatooine/mat_rags.stf', 34, 'npc_work_2', 'Have you skinned that little sucker yet?'),
('string/en/static_npc/tatooine/mat_rags.stf', 35, 'npc_work_3', 'So, have you killed that big monster?'),
('string/en/static_npc/tatooine/mat_rags.stf', 42, 'npc_backtowork_2', 'Yeah, they can be little buggers.  Keep looking!'),
('string/en/static_npc/tatooine/mat_rags.stf', 43, 'npc_backtowork_3', 'Hmmm... you know, that''s a pretty good idea.  I''ll have to remember that.  I mean - yeah - I''m glad to see you''re learning.'),
('string/en/static_npc/tatooine/mat_rags.stf', 44, 'npc_reset_2', 'I thought you were a little too dim to do this.  When you''ve learned how to read, look me up, okay?'),
('string/en/static_npc/tatooine/mat_rags.stf', 45, 'npc_reset_3', 'Probably a wise decision. I expect that last creature was about the limit of your skills. '),
('string/en/static_npc/tatooine/mat_rags.stf', 46, 'player_reset_2', 'Look, if I can''t even pronounce the name of the thing I''m supposed to kill, I shouldn''t be hunting it.  I''m out.'),
('string/en/static_npc/tatooine/mat_rags.stf', 47, 'player_reset_3', 'I can''t do it, Mat!  I''m scared to death of banthas!  And a bantha this big?  Nightmares, I tell you.'),
('string/en/static_npc/tatooine/mat_rags.stf', 48, 'player_sorry_2', 'No, I''ve only found normal womprats.  I''m still looking for one of those variegated types.'),
('string/en/static_npc/tatooine/mat_rags.stf', 49, 'player_sorry_3', 'No, I was waiting for her to leave the pack.  I didn''t want to spook the rest.'),
('string/en/static_npc/tatooine/mat_rags.stf', 61, 'npc_1_4', 'You''ve done a bang-up job so far, but now you''ll have to grow up a little. I''m not sure you''re up to this job, but I thought you might enjoy a challenge. Interested?'),
('string/en/static_npc/tatooine/mat_rags.stf', 64, 'npc_2_4', 'Think you''ve got what it takes? All right then, track down a grizzled dewback and bring back the hide. Try not to scorch it. A museum wants to stuff it for a display of dangerous wildlife.'),
('string/en/static_npc/tatooine/mat_rags.stf', 67, 'npc_3_4', 'Not everybody has what it takes to make it in this business. Some just choke under the pressure. '),
('string/en/static_npc/tatooine/mat_rags.stf', 70, 'npc_4_4', 'You''re a cheeky one, you are! I was hunting krayts when you were still learning not to drool on yourself. Bah! "Do I ever hunt," indeed!'),
('string/en/static_npc/tatooine/mat_rags.stf', 73, 'npc_backtowork_4', 'Really?  Wow.  Um... I mean... yeah, I''ll expect this done.'),
('string/en/static_npc/tatooine/mat_rags.stf', 79, 'npc_reset_4', 'Not everybody has what it takes to make it in this business. Some just choke under the pressure. '),
('string/en/static_npc/tatooine/mat_rags.stf', 82, 'npc_reward_4', 'You''ve done far better than I ever thought you would. It''s a pity the League isn''t accepting new applicants just now.'),
('string/en/static_npc/tatooine/mat_rags.stf', 88, 'npc_work_4', 'So have you shown that dewback who the master is?'),
('string/en/static_npc/tatooine/mat_rags.stf', 91, 'player_1_4', 'Only as long as it''s a challenge.  If I don''t barely make it out there alive, it''s not worth it!'),
('string/en/static_npc/tatooine/mat_rags.stf', 94, 'player_2_4', 'I''ve been doing this the whole time and haven''t learned a thing from you!  I''m done with this!'),
('string/en/static_npc/tatooine/mat_rags.stf', 97, 'player_3_4', 'Do you ever actually hunt anything yourself?'),
('string/en/static_npc/tatooine/mat_rags.stf', 100, 'player_reset_4', 'You lazy sack of bones!  It just dawned on me that I''m doing all your work!  I''m through with you.'),
('string/en/static_npc/tatooine/mat_rags.stf', 103, 'player_sorry_4', 'Not yet.  I will shortly, though!'),
('string/en/static_npc/tatooine/mat_rags.stf', 104, 'next', 'If I find any more work I think you can handle, I''ll let you know.'),
('string/en/static_npc/tatooine/melios_purl.stf', 1, 'npc_1_1', 'I could use your help with this emergency, actually. A womp rat bit a local moisture farmer and the wound has become infected. The young woman waited too long to contact me, unfortunately, and I now I fear her condition may prevent her from making the journey safely. Could you make sure she does? '),
('string/en/static_npc/tatooine/melios_purl.stf', 2, 'npc_1_2', 'I could use your help in investigating the possible spread of this deadly disease. I need to perform an analysis of an infected womp rat. This will allow me to determine if the plague has mutated and requires a new vaccine. Do you think you can bring me an infected specimen''s hide?'),
('string/en/static_npc/tatooine/melios_purl.stf', 3, 'npc_1_3', 'I was hoping you''d ask, citizen. I need to make sure this vaccine gets out to all the moisture farmers who may not have access to the cities. Could you deliver this supply to a representative of the Affiliated Moisture Farmers? '),
('string/en/static_npc/tatooine/melios_purl.stf', 5, 'npc_2_1', 'You are most gracious, citizen. She''s transmitted her coordinates. She was attempting the trip on her own, but realized she might not make it. She''s brave, but also a bit on the reckless side.'),
('string/en/static_npc/tatooine/melios_purl.stf', 6, 'npc_2_2', 'You are noble and good, citizen. I''ve taken the liberty of inoculating you against common Gray Rot with a modified bacta spray. This will keep you safe. If I determine that this is a new strain, I''ll provide you the vaccine as soon as I develop it.'),
('string/en/static_npc/tatooine/melios_purl.stf', 7, 'npc_2_3', 'You are nothing if not reliable, citizen. Here you go. Make sure this gets to its destination as quickly as possible. Gray Rot can devastate a settlement in mere days.'),
('string/en/static_npc/tatooine/melios_purl.stf', 8, 'npc_3_1', 'It is regrettable that you choose not to help this young woman. If you''ll excuse me, I need to find someone who will. Good day.'),
('string/en/static_npc/tatooine/melios_purl.stf', 9, 'npc_3_2', 'I would inoculate you against the common strain of Gray Rot, so I assure you you''d be safe. If after I''ve studied the specimen, I determine a new vaccine is needed, I''d provide you that as well. Please, these citizens need your help.'),
('string/en/static_npc/tatooine/melios_purl.stf', 10, 'npc_3_3', 'I must assume you''re very busy. You do not seem to be the type of being that would stand idly by and watch dozens of innocents suffer a terrible fate. I''ll find someone else to deliver the vaccine. Good day.'),
('string/en/static_npc/tatooine/melios_purl.stf', 12, 'npc_4_1', 'Her name is Maikeen Storn. She''s only been on Tatooine for about a year. She''s originally from Agamar, I believe. She''s a brave young woman whose spirit I have come to admire. I hope you can help her'),
('string/en/static_npc/tatooine/melios_purl.stf', 13, 'npc_4_2', 'Gray Rot makes a victim''s skin go scabrous and gray until it eventually cracks and ulcerates. Death follows a few agonizing days later. If caught in its early stages, it is treatable with bacta.'),
('string/en/static_npc/tatooine/melios_purl.stf', 14, 'npc_4_3', 'The man''s name is Aroy Sekun, friend of the Darklighters, I believe. He''s a responsible sort and will make sure that vaccine gets properly distributed. '),
('string/en/static_npc/tatooine/melios_purl.stf', 15, 'npc_reward_1', 'You have my thanks, citizen. You doubtless saved this woman''s life. Now if you''ll excuse me, I have work to do. '),
('string/en/static_npc/tatooine/melios_purl.stf', 16, 'npc_reward_2', 'Good work, citizen. I''ll get right on this analysis. You may have just saved this city from a terrible epidemic. Check back with me to get a report of my findings.'),
('string/en/static_npc/tatooine/melios_purl.stf', 17, 'npc_reward_3', 'You''ve helped avert a catastrophe, friend. You have my thanks and the gratitude of the citizens of Tatooine. We have a new stimpack we''ve been working on. I don''t have any pre-made packs at the moment, but here''s the blueprint to make some if you''re interested.'),
('string/en/static_npc/tatooine/melios_purl.stf', 18, 'player_1_1', 'Absolutely!'),
('string/en/static_npc/tatooine/melios_purl.stf', 19, 'player_1_2', 'If this will help cure others, I''ll do it.  Yes.'),
('string/en/static_npc/tatooine/melios_purl.stf', 20, 'player_1_3', 'I''ll make sure it gets to the right hands.'),
('string/en/static_npc/tatooine/melios_purl.stf', 21, 'player_2_1', 'It''s not my fault she waited too long.  I''m too busy to help right now.'),
('string/en/static_npc/tatooine/melios_purl.stf', 22, 'player_2_2', 'No, that''s not my field of work.  Sorry.'),
('string/en/static_npc/tatooine/melios_purl.stf', 23, 'player_2_3', 'You''re better off hiring a courier.  I''m not interested.'),
('string/en/static_npc/tatooine/melios_purl.stf', 24, 'player_3_1', 'Who is this moisture farmer?'),
('string/en/static_npc/tatooine/melios_purl.stf', 25, 'player_3_2', 'What exactly is Gray Rot Plague?'),
('string/en/static_npc/tatooine/melios_purl.stf', 26, 'player_3_3', 'Who is this representative?'),
('string/en/static_npc/tatooine/melios_purl.stf', 27, 'player_reset_1', 'I''ve had something come up. I cannot escort her back here any more. Sorry.'),
('string/en/static_npc/tatooine/melios_purl.stf', 28, 'player_sorry_1', 'No, I haven''t yet.'),
('string/en/static_npc/tatooine/melios_purl.stf', 29, 'npc_backtowork_1', 'You will need to hurry.  If her infection is allowed to grow, I fear my skills will not be able to heal her.'),
('string/en/static_npc/tatooine/melios_purl.stf', 30, 'npc_reset_1', 'It is regrettable that you choose not to help this young woman. If you''ll excuse me, I need to find someone who will. Good day.'),
('string/en/static_npc/tatooine/melios_purl.stf', 31, 'cantwork', 'I''m afraid my assignments would require your full attention, citizen. Medical issues should be top priority, after all. Please come back when you''re free.'),
('string/en/static_npc/tatooine/melios_purl.stf', 32, 'dontknowyou_1', 'Thank you, but help is already on the way.'),
('string/en/static_npc/tatooine/melios_purl.stf', 34, 'npc_work_2', 'How goes your search for one of those pestilent womp rats?'),
('string/en/static_npc/tatooine/melios_purl.stf', 35, 'npc_work_3', 'Has that vaccine been given to the Moisture Farmers yet?'),
('string/en/static_npc/tatooine/melios_purl.stf', 36, 'npc_breech_1', 'Are you here to help me back to Doctor Melios?'),
('string/en/static_npc/tatooine/melios_purl.stf', 38, 'npc_breech_3', 'Oh, good!  You must be the one who has the vaccine.'),
('string/en/static_npc/tatooine/melios_purl.stf', 40, 'notit_2', 'No, this is not an infected womprat hide.'),
('string/en/static_npc/tatooine/melios_purl.stf', 42, 'npc_backtowork_2', 'Well, I wish you good luck.  As soon as I have that hide, I can begin working on a cure.'),
('string/en/static_npc/tatooine/melios_purl.stf', 43, 'npc_backtowork_3', 'Well, make sure they get it.  Their representative is still waiting for you.'),
('string/en/static_npc/tatooine/melios_purl.stf', 44, 'npc_reset_2', 'I would inoculate you against the common strain of Gray Rot, so I assure you you''d be safe. If after I''ve studied the specimen, I determine a new vaccine is needed, I''d provide you that as well. Please, these citizens need your help.'),
('string/en/static_npc/tatooine/melios_purl.stf', 45, 'npc_reset_3', 'I must assume you''re very busy. You do not seem to be the type of being that would stand idly by and watch dozens of innocents suffer a terrible fate. I''ll find someone else to deliver the vaccine. Good day.'),
('string/en/static_npc/tatooine/melios_purl.stf', 46, 'player_reset_2', 'I have second thoughts about this.  I don''t want to get infected myself, so I have to decline.'),
('string/en/static_npc/tatooine/melios_purl.stf', 47, 'player_reset_3', 'I don''t feel I should be the one to deliver this.  You might want to get someone else to do it.  Sorry.'),
('string/en/static_npc/tatooine/melios_purl.stf', 48, 'player_sorry_2', 'I have yet to find one, but I continue to search for one.'),
('string/en/static_npc/tatooine/melios_purl.stf', 49, 'player_sorry_3', 'No, not yet.  I''m in the process of taking it out to them.'),
('string/en/static_npc/tatooine/melios_purl.stf', 50, 'npc_takeme_1', 'Dr. Purl sent you, didn''t he? Oh, all this fuss over me. Well, I appreciate your help. If I pass out, just slap me till I wake up.'),
('string/en/static_npc/tatooine/melios_purl.stf', 54, 'dontknowyou_3', 'I hope that vaccine gets here soon.  I''ve been waiting here all day.'),
('string/en/static_npc/tatooine/melios_purl.stf', 108, 'npc_smuggle_3', 'Thanks, friend. I''ll make sure this gets to everyone who needs it. Dr. Purl has spoken highly of you. It was an honor and a pleasure to meet you. Take care.'),
('string/en/static_npc/tatooine/melios_purl.stf', 112, 'npc_work_1', 'Have you brought the farmer back yet?'),
('string/en/static_npc/tatooine/melios_purl.stf', 113, 'next', 'If I have any more medical emergencies I need help with, I''ll be sure and ask for you.'),
('string/en/static_npc/tatooine/melios_purl.stf', 114, 'npc_failure_1', 'I''m so disappointed...'),
('string/en/static_npc/tatooine/melios_purl.stf', 115, 'npc_failure_2', 'Now I don''t know if we''ll ever be able to stop the disease.'),
('string/en/static_npc/tatooine/melios_purl.stf', 116, 'npc_failure_3', 'I fear for our moisture farmers.  I wish you''d managed to get them the vaccine...'),
('string/en/static_npc/tatooine/mikos_denari.stf', 1, 'npc_1_1', 'Mikos Dinari is the name, and I do have a problem I could use a bit of help with. There''s Tusken Raiders out in the desert that want my hide. You think you could do something about it?'),
('string/en/static_npc/tatooine/mikos_denari.stf', 2, 'npc_1_2', 'I''m still having trouble with those blasted Sand People. You did such a bang-up job last time -- maybe you''re willing to help me out again?'),
('string/en/static_npc/tatooine/mikos_denari.stf', 5, 'npc_2_1', 'I like you young folks. You got good hearts. One of those Tuskens is hot on my trail. I''m safe here in town, but every time I try to leave, he''s there waiting. See to it he doesn''t bother me anymore, if you can. I surely would be grateful.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 6, 'npc_2_2', 'Good hearted! It''s what I''ve always said about you, and I stand by it. Maybe if you were to kill that Tusken Raider chief, they''d decide that I wasn''t worth all this trouble. '),
('string/en/static_npc/tatooine/mikos_denari.stf', 8, 'npc_3_1', 'Well, danger ain''t for everybody, is it? Don''t you worry. I''ll get by somehow.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 9, 'npc_3_2', 'I guess you had your fill of Sand People in that last encounter. Well, don''t let an old man waste any more of your time. '),
('string/en/static_npc/tatooine/mikos_denari.stf', 12, 'npc_4_1', 'I was out in the desert surveying, and I kind of lost my way. My supplies were running out when I stumbled on to that oasis. Turns out the Sand People are a mite protective of their water sources. I ran. Stumbled across a sandcrawler, and for a small fee, plus the things they managed to steal, the Jawas brought me here.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 13, 'npc_4_2', 'I guess they''re still angry about my drinking their water. Now their chief is hunting me. Every time I head out into the desert, he and some of his guards track me down, so I have to hightail it back to town. '),
('string/en/static_npc/tatooine/mikos_denari.stf', 15, 'npc_reward_1', 'I can''t thank you enough for helping me out of that mess. You be careful out in that desert now, y''hear? '),
('string/en/static_npc/tatooine/mikos_denari.stf', 16, 'npc_reward_2', 'Thanks to you, I can get back to my surveying and finally earn some credits again. I won''t forget this.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 18, 'player_1_1', 'Sure.  I can''t stand Sand People!'),
('string/en/static_npc/tatooine/mikos_denari.stf', 19, 'player_1_2', 'I still hate Sand People.  I''ll definitely help.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 21, 'player_2_1', 'Sorry, but I don''t mess with Sand People.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 22, 'player_2_2', 'I''m not sure I want to do any more of this ''killing'' thing.  Sorry.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 24, 'player_3_1', 'Why are the Sand People angry with you?'),
('string/en/static_npc/tatooine/mikos_denari.stf', 25, 'player_3_2', 'What sort of trouble are you having now?'),
('string/en/static_npc/tatooine/mikos_denari.stf', 27, 'player_reset_1', 'I''m sorry, but something came up.  I can''t do this anymore.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 28, 'player_sorry_1', 'Not yet.  Once I find them, they''ll be dealt with.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 29, 'npc_backtowork_1', 'Thank you for doing this.  This means a lot to me.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 30, 'npc_reset_1', 'Well, danger ain''t for everybody, is it? Don''t you worry. I''ll get by somehow.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 31, 'cantwork', 'Hey there, friend. Watch yourself out in the desert. It''s too easy to get lost. Made trouble for me, but I see you''re busy. Come on back later.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 33, 'npc_work_1', 'Have you dispatched the Tusken Raiders?'),
('string/en/static_npc/tatooine/mikos_denari.stf', 34, 'npc_work_2', 'Are those evil things going to bother me any more?'),
('string/en/static_npc/tatooine/mikos_denari.stf', 42, 'npc_backtowork_2', 'Well, when you''re victorious, come back and let me know!'),
('string/en/static_npc/tatooine/mikos_denari.stf', 44, 'npc_reset_2', 'I guess you had your fill of Sand People in that last encounter. Well, don''t let an old man waste any more of your time. '),
('string/en/static_npc/tatooine/mikos_denari.stf', 46, 'player_reset_2', 'I''m sorry, but I can''t do this anymore.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 48, 'player_sorry_2', 'I don''t know.  I know that I haven''t taken care of them yet for now.'),
('string/en/static_npc/tatooine/mikos_denari.stf', 49, 'next', 'I think I''m in the clear thanks to you. If I get in any more trouble I''ll let you know.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 1, 'npc_1_1', 'An Imperial Army non-com is defecting to the Alliance. I need someone to escort him here before the Empire gets him.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 2, 'npc_1_2', 'Friend of mine, Vil Sembian -- ever hear of his dad, Daw Sembian, the famous weaponsmith? Doesn''t matter, Daw''s dead now. He left Vil the schematic for a new kind of blaster. Vil is bringing us the plans, but the Empire''s on his tail. I need you to bring him here safely.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 5, 'npc_2_1', 'Great! His name''s Drenn Biktor. A tiny nothing of a man, but don''t tell him I said that. Bring him here safely.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 6, 'npc_2_2', 'Good. Get going. I''ve got more crises to deal with here.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 8, 'npc_3_1', 'Fine. I''ll get someone else to keep this sleemo alive. Enjoy your day.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 9, 'npc_3_2', 'Right. I''ll just hope someone else decides to help change the course of the war. Nice outfit. Bye now.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 12, 'npc_4_1', 'He knows more about Imperial Outer Rim supply routes than anyone could and stay sane. We can use that data to interdict their shipments. C''mon, I''m aging rapidly here. Decision? '),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 13, 'npc_4_2', 'I don''t know why the blaster is so special. My commander says it could tip the scales in our favor. Good enough for me.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 15, 'npc_reward_1', 'Good work, another victory for the Alliance. Now I have to get this guy offworld. Gaah, one more crisis.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 16, 'npc_reward_2', 'Great. I''ll have these schematics sent to High Command. Hopefully they are what we need. If we just had more soldiers of your skill and determination, the Alliance would already have freed the galaxy.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 18, 'player_1_1', 'Yes, I''m interested.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 19, 'player_1_2', 'Sure, I''ll do it.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 21, 'player_2_1', 'Not interested.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 22, 'player_2_2', 'Sorry, I don''t want to get involved.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 24, 'player_3_1', 'Why is an Imperial Army non-com important?'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 25, 'player_3_2', 'What''s so special about this blaster?'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 27, 'player_reset_1', 'I don''t know, and I really don''t care.  I''ve changed my mind about this.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 28, 'player_sorry_1', 'I don''t know, but I don''t like the sound of that.  I haven''t picked him up yet.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 29, 'npc_backtowork_1', 'It''s just that you can never tell about these kinds of things.  I''m hoping he really means to defect.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 30, 'npc_reset_1', 'Fine. I''ll get someone else to keep this sleemo alive. Enjoy your day.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 31, 'cantwork', 'Sorry, can''t talk now. I''m busy.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 32, 'dontknowyou_1', 'Unless of course you''re an Imperial.  If so, that was just one big joke.  Umm.. bye!'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 33, 'npc_work_1', 'Did it turn out to be a trap after all?'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 34, 'npc_work_2', 'Were you able to find him?'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 36, 'npc_breech_1', 'Help! The Empire will kill me when they learn I''m gone. I have to be taken to a place of safety!'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 37, 'npc_breech_2', 'Identify yourself before you get any closer!'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 42, 'npc_backtowork_2', 'Well, you should hurry.  I don''t know how much time he has left.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 44, 'npc_reset_2', 'Right. I''ll just hope someone else decides to help change the course of the war. Nice outfit. Bye now.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 46, 'player_reset_2', 'I''ve changed my mind.  I could get hurt doing this, and don''t like that idea.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 48, 'player_sorry_2', 'Not yet.  I''m on my way to save him right now.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 50, 'npc_takeme_1', 'Thank you. I don''t know what will happen to me now. But I couldn''t go on serving the Empire. I had friends on Alderaan!'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 51, 'npc_takeme_2', 'You''re taking me to Captain Vendallan? Thank goodness. I thought the next place I was heading for was a Imperial prison camp.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 53, 'dontknowyou_2', 'Nevermind.  I thought you with with someone else.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 54, 'next', 'I don''t have anything you can help me with right now. Try me again later.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 55, 'notyet', 'What do you want? You''re not part of my organization, I have nothing to say to you.'),
('string/en/static_npc/tatooine/nitra_vendallan.stf', 56, 'npc_failure', 'What? Dead? How could that happen. This is not good.'),
('string/en/static_npc/tatooine/om_aynat.stf', 1, 'npc_1_1', 'Well, hello! Can you help me? I''m expecting a rep from the Sand Dragon Fresher company to bring some supplies -- but the rep has gotten lost on the way to Bestine. If you find him and bring him to my humble stand, I can give you a fine bottle of Corellian Ale. I have surplus!'),
('string/en/static_npc/tatooine/om_aynat.stf', 2, 'npc_1_2', 'I hope you enjoyed the Corellian ale! Urgh, I could use a drink myself. I''m embroiled in a legal battle with a failing cafe owner in Mos Taike. She claims she owns the recipe for my special creation, Talusian Flatbread. She lies! My legal advocate just sent a distress message from outside town. Can you escort him here?'),
('string/en/static_npc/tatooine/om_aynat.stf', 3, 'npc_1_3', 'I''m preparing a banquet for my longtime friend and benefactor, Moff Aryon. As a surprise, I''ve recruited the illustrious chef from the Fallen Star hotel. Yes! Unfortunately, the chef is notorious for lateness. So if you''re willing, I''d like you to escort the chef to me. Yes? No?'),
('string/en/static_npc/tatooine/om_aynat.stf', 5, 'npc_2_1', 'Great! I''m in desperate need of new supplies. Be careful, now!'),
('string/en/static_npc/tatooine/om_aynat.stf', 6, 'npc_2_2', 'Excellent! I look forward to your return, and an end to this frivolous lawsuit!'),
('string/en/static_npc/tatooine/om_aynat.stf', 7, 'npc_2_3', 'Good. I can''t extend an invitation to the banquet -- very high-tone, you know. But I can certainly provide a worthwhile reward.'),
('string/en/static_npc/tatooine/om_aynat.stf', 8, 'npc_3_1', 'I understand. Perhaps some other time? Take care.'),
('string/en/static_npc/tatooine/om_aynat.stf', 9, 'npc_3_2', 'Wellll -- as you will. I''m not sure what I''ll do about this lawsuit, but -- as you will!'),
('string/en/static_npc/tatooine/om_aynat.stf', 10, 'npc_3_3', 'I understand. If I could extend an invitation to the banquet, it might be more attactive, no? Maybe later.'),
('string/en/static_npc/tatooine/om_aynat.stf', 12, 'npc_4_1', 'My name is Om Aynat. Long ago I trained as a chef on Talus, but -- well -- bad things happened. After bouncing unhappily from system to system, I wound up starting this food stand, financed by my friend Tour Aryon. Now, what about my task?'),
('string/en/static_npc/tatooine/om_aynat.stf', 13, 'npc_4_2', 'Under the master chef in Restuss, I was once assigned to make Talusian bread for a cruiser-load of students. I didn''t like them, so as a prank I left out the fermenters. The flattened bread was a towering sensation! But when the Corellia HoloNet service wanted to do a story about it, the master expelled me. Suspicious, no? I got no credit, and ever since, I have faced countless liars who claim to have created my bread. Will you help me?'),
('string/en/static_npc/tatooine/om_aynat.stf', 14, 'npc_4_3', 'It''s just a nice thing to do! Right after I was exiled from the culinary conservatory in Restuss, a friend in the Imperial Navy introduced us. She embodies the greatness of the Empire: fair-handed, even-tempered and, well, just a fantastic person! So of course you''ll take the assignment, no?'),
('string/en/static_npc/tatooine/om_aynat.stf', 15, 'npc_reward_1', 'Careful with this thing. It''s put together well, but if you crush it, it won''t be worth a scurrier''s ear.'),
('string/en/static_npc/tatooine/om_aynat.stf', 16, 'npc_reward_2', 'Here''s your official proclamation. It won''t be valid unless and until I get elected. But just in case, hang onto it.'),
('string/en/static_npc/tatooine/om_aynat.stf', 17, 'npc_reward_3', 'Here you go. This is a picture I took during liftoff from an Outer Rim planet. That picture is the only one of its kind in this system. Beautiful, no?'),
('string/en/static_npc/tatooine/om_aynat.stf', 18, 'player_1_1', 'Yes. I will find and bring the representative.'),
('string/en/static_npc/tatooine/om_aynat.stf', 19, 'player_1_2', 'Yes. I will escort the advocate to you.'),
('string/en/static_npc/tatooine/om_aynat.stf', 20, 'player_1_3', 'Yes. I will retrieve the chef for you.'),
('string/en/static_npc/tatooine/om_aynat.stf', 21, 'player_2_1', 'No. I have no time for this.'),
('string/en/static_npc/tatooine/om_aynat.stf', 22, 'player_2_2', 'No. I can''t do this for you.'),
('string/en/static_npc/tatooine/om_aynat.stf', 23, 'player_2_3', 'No. I can''t.'),
('string/en/static_npc/tatooine/om_aynat.stf', 24, 'player_3_1', 'Who are you?'),
('string/en/static_npc/tatooine/om_aynat.stf', 25, 'player_3_2', 'Did you invent Talusian Flatbread?'),
('string/en/static_npc/tatooine/om_aynat.stf', 26, 'player_3_3', 'Why are you hosting a banquet for Tour Aryon?'),
('string/en/static_npc/tatooine/om_aynat.stf', 27, 'player_reset_1', 'I will not be able to escort him back any longer.  Sorry.'),
('string/en/static_npc/tatooine/om_aynat.stf', 28, 'player_sorry_1', 'No, not yet.'),
('string/en/static_npc/tatooine/om_aynat.stf', 29, 'npc_backtowork_1', 'Be sure to let me know when you have.'),
('string/en/static_npc/tatooine/om_aynat.stf', 30, 'npc_reset_1', 'I understand. Perhaps some other time? Take care.'),
('string/en/static_npc/tatooine/om_aynat.stf', 31, 'cantwork', 'Well, hello! I am Om Aynat, creator of Bestine''s most famous Talusian Flatbread! Unfortunately I am out of bread right now. Please return later!'),
('string/en/static_npc/tatooine/om_aynat.stf', 32, 'dontknowyou_1', 'Hello, stranger. I can''t talk now -- I''m waiting for someone else.'),
('string/en/static_npc/tatooine/om_aynat.stf', 33, 'npc_work_1', 'Have you found the Sand Dragon ''Fresher rep yet?'),
('string/en/static_npc/tatooine/om_aynat.stf', 34, 'npc_work_2', 'Have you found my advocate yet?'),
('string/en/static_npc/tatooine/om_aynat.stf', 35, 'npc_work_3', 'Have you found the chef yet?'),
('string/en/static_npc/tatooine/om_aynat.stf', 36, 'npc_breech_1', 'Hello there!'),
('string/en/static_npc/tatooine/om_aynat.stf', 37, 'npc_breech_2', 'Hello there!'),
('string/en/static_npc/tatooine/om_aynat.stf', 38, 'npc_breech_3', 'Hello there!'),
('string/en/static_npc/tatooine/om_aynat.stf', 42, 'npc_backtowork_2', 'Be sure to let me know when you have.'),
('string/en/static_npc/tatooine/om_aynat.stf', 43, 'npc_backtowork_3', 'Be sure to let me know when you have.'),
('string/en/static_npc/tatooine/om_aynat.stf', 44, 'npc_reset_2', 'Wellll -- as you will. I''m not sure what I''ll do about this lawsuit, but -- as you will!'),
('string/en/static_npc/tatooine/om_aynat.stf', 45, 'npc_reset_3', 'I understand. If I could extend an invitation to the banquet, it might be more attactive, no? Maybe later.'),
('string/en/static_npc/tatooine/om_aynat.stf', 46, 'player_reset_2', 'I will not be able to escort him back any longer.  Sorry.'),
('string/en/static_npc/tatooine/om_aynat.stf', 47, 'player_reset_3', 'I will not be able to escort him back any longer.  Sorry.'),
('string/en/static_npc/tatooine/om_aynat.stf', 48, 'player_sorry_2', 'No, not yet.'),
('string/en/static_npc/tatooine/om_aynat.stf', 49, 'player_sorry_3', 'No, not yet.'),
('string/en/static_npc/tatooine/om_aynat.stf', 50, 'npc_takeme_1', 'Whew! I thought I''d be stuck here forever. Can you lead me to Om, please?'),
('string/en/static_npc/tatooine/om_aynat.stf', 51, 'npc_takeme_2', 'Ah yes. Could you take me to Om Aynat, if you please?'),
('string/en/static_npc/tatooine/om_aynat.stf', 52, 'npc_takeme_3', 'Aynat sent you? Nonsense. Plenty of time, plenty of t-- gad! Look at the time! And I have so much still to prepare! Quick, take me to Aynat!'),
('string/en/static_npc/tatooine/om_aynat.stf', 53, 'dontknowyou_2', 'Hello, stranger. I can''t talk now -- I''m waiting for someone else.'),
('string/en/static_npc/tatooine/om_aynat.stf', 54, 'dontknowyou_3', 'Hello, stranger. I can''t talk now -- I''m waiting for someone else.'),
('string/en/static_npc/tatooine/om_aynat.stf', 55, 'dontknowyou_4', 'Hello, stranger. I can''t talk now -- I''m waiting for someone else.'),
('string/en/static_npc/tatooine/om_aynat.stf', 61, 'npc_1_4', 'The Planetary Museum curator runs a matchmaking business on the side called "Dune-Hearts." But the museum''s antique messenger droid accidentally gave all the clients bad locations in their datapads. Now they''re wandering the desert, searching vainly for their true loves. Can you escort one back here so I can set him straight?'),
('string/en/static_npc/tatooine/om_aynat.stf', 64, 'npc_2_4', 'Wonderful! I''m sure that the message droid problems will be fixed by the time you return. Be careful!'),
('string/en/static_npc/tatooine/om_aynat.stf', 67, 'npc_3_4', 'Yes, well -- I suppose people should solve their own problems. Thank you for your time.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/om_aynat.stf', 70, 'npc_4_4', 'I''m not sure. Perhaps being a curator of antiquities makes one unnecessarily fond of old, broken things. It certainly seemed to make him an old, broken thing. But if he keeps hanging onto that droid, we''ll have many more people stranded out in the desert, looking for love. Symbolic, no? Well, what''s your answer?'),
('string/en/static_npc/tatooine/om_aynat.stf', 73, 'npc_backtowork_4', 'Be sure to let me know when you have.'),
('string/en/static_npc/tatooine/om_aynat.stf', 76, 'npc_breech_4', 'Hello there!'),
('string/en/static_npc/tatooine/om_aynat.stf', 79, 'npc_reset_4', 'Yes, well -- I suppose people should solve their own problems. Thank you for your time.'),
('string/en/static_npc/tatooine/om_aynat.stf', 82, 'npc_reward_4', 'Here''s a recording rod that I paid far too much for. It''s valuable but fragile. Be careful with it.'),
('string/en/static_npc/tatooine/om_aynat.stf', 85, 'npc_takeme_4', 'You''re not my date! But hey, after all this time wandering out here, even you look good. Wait, I didn''t mean how that sounded!'),
('string/en/static_npc/tatooine/om_aynat.stf', 88, 'npc_work_4', 'Have you found the star-crossed lover yet?'),
('string/en/static_npc/tatooine/om_aynat.stf', 91, 'player_1_4', 'Yes. I will bring a client here to you.'),
('string/en/static_npc/tatooine/om_aynat.stf', 94, 'player_2_4', 'No. Sorry.'),
('string/en/static_npc/tatooine/om_aynat.stf', 97, 'player_3_4', 'Why doesn''t he get a new messenger droid?'),
('string/en/static_npc/tatooine/om_aynat.stf', 100, 'player_reset_4', 'I will not be able to escort him back any longer.  Sorry.'),
('string/en/static_npc/tatooine/om_aynat.stf', 103, 'player_sorry_4', 'No, not yet.'),
('string/en/static_npc/tatooine/om_aynat.stf', 104, 'next', 'Maybe I''ll find more work for you later. Right now I need to make more flatbread.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 1, 'npc_1_1', 'I''m Custodial Officer here. Ihh, fallen a long way from my good days -- never mind. Got problems with womp rats, and I want ''em dead. All of ''em. Got a budget for pest removal, so I can pay. Interested?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 2, 'npc_1_2', 'Got more problems with animals -- mynocks, now. Not space mynocks, but the ground-bound Tatooine kind. Not the kind of problem I used to worry about as an Imperial officer, but anyway -- You interested?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 3, 'npc_1_3', 'Know those big dragonets? They''re prowling around the trash compactors here, growling at the troops. I need ''em dead. That''s my life now, lining up pest control. One trip to the forest moon, and poof! Disaster.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 5, 'npc_2_1', 'Right. I''ve found where they sleep. Destroy them, then check back here.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 6, 'npc_2_2', 'Good. Those mynocks are eating the silica right out of my walls. Blow up their hive, or whatever it is, and check back here for payment.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 7, 'npc_2_3', 'Good. Folks say those dragonets are young krayt dragons. Don''t know about that, but be careful anyway. Kill ''em and report back here.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 8, 'npc_3_1', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 9, 'npc_3_2', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 10, 'npc_3_3', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 12, 'npc_4_1', 'Oh, they get into the water tanks, and -- ihh, I tell a lie. Truth is, I just hate furry things. Empire sent me to some forest moon in the back end of nowhere. Little furry creatures there made trouble all day, every day. Ever since, I like to see furry things die horribly. What about it?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 13, 'npc_4_2', 'I was records officer on an Imperial scouting mission to this one forest moon -- place you never heard of. Didn''t like the place, and said so. Seems the Emperor himself saw my report. That can end a career fast. Anyway, these mynocks -- will you kill ''em?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 14, 'npc_4_3', 'Me? After Endor, I got put on lonely duty riding solar focusing mirrors in orbit around Coruscant. Thought that was the worst duty in the galaxy, ''til I got sent here. About those dragonets -- want to kill ''em?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 15, 'npc_reward_1', 'Nice job. I hope those rats screeched loud as they died. Ihh, me, once an officer, fallen to gloating over dead womp rats! Life''s funny.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 16, 'npc_reward_2', 'Good. Mynocks -- lousy vermin, worse than Ewoks. Ihh? What''s an Ewok? Never mind, you don''t want to know.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 17, 'npc_reward_3', 'Good. Dragonets, huh. Let a few of ''em loose on Endor, and the Ewok population would drop pretty dramatically.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 18, 'player_1_1', 'Sounds like an easy job.  I''ll do it.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 19, 'player_1_2', 'I like killing mynocks.  Sure, I''ll get it done.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 20, 'player_1_3', 'I''ll kill them for you, yes.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 21, 'player_2_1', 'I''m not a lowly exterminator.  Get some lowlife to do it!'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 22, 'player_2_2', 'How could you think of killing those adorable little things.  No, I won''t do it.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 23, 'player_2_3', 'No, I won''t do this.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 24, 'player_3_1', 'Why do you want the womp rats killed?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 25, 'player_3_2', 'If you were an officer, why are you a custodian now?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 26, 'player_3_3', 'What did you do after the forest moon mission?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 27, 'player_reset_1', 'I can''t kill them.  They''re too cute.  I can''t believe you would dare to have me kill those little furry things.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 28, 'player_sorry_1', 'No, not yet.  They''re wily little things.  I''ll let you know when they''re all gone.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 29, 'npc_backtowork_1', 'Ihh.. now you see why I hate them.  Wipe them from the face of this planet, then tell me when you are triumphant.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 30, 'npc_reset_1', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 31, 'cantwork', 'Visitor? Ihhh, no idea why. Not much of interest way up here. But go ahead, look around. Watch out for vermin. Don''t mess up the place.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 33, 'npc_work_1', 'Ihhh... you done already?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 34, 'npc_work_2', 'All mynocks dead, yes?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 35, 'npc_work_3', 'No more Dragonets?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 42, 'npc_backtowork_2', 'They''re not the ones that haunt me...'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 43, 'npc_backtowork_3', 'Good, good, get it done.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 44, 'npc_reset_2', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 45, 'npc_reset_3', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 46, 'player_reset_2', 'No, I''ve changed my mind.  They deserve to live just as you and I.  Well... more the "I" part.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 47, 'player_reset_3', 'No, I''m not doing your duty work for you.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 48, 'player_sorry_2', 'Not yet, but soon.  Soon they will no longer haunt your waking days.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 49, 'player_sorry_3', 'I am still killing them all.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 61, 'npc_1_4', 'Dune lizards. Hate ''em. They think this is their territory. One Imperial officer gets eaten, and suddenly it''s my problem. Now it''s yours. Kill ''em -- the lizards, not the troops. Don''t have any credits left in the budget, but maybe I can work out some other payoff.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 64, 'npc_2_4', 'Good. Check back here after you kill all those lizards.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 67, 'npc_3_4', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 70, 'npc_4_4', 'You want to go? Heh. Way back when, Imperial Security sent me a duplicate security clearance for Endor by mistake. Tell you what -- you take out these lizards, I''ll give you that clearance.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 73, 'npc_backtowork_4', 'Good, good.  You might be an Imperial officer some day!  Tell me when they''re all dead, okay?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 79, 'npc_reset_4', 'Ihh, well, pardon me for living. I''m getting back to work.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 82, 'npc_reward_4', 'Good work! Here, take this. Not sure why I saved a painting of that horrible place, can''t stand to look at it anyway.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 88, 'npc_work_4', 'All of the Dune Lizards dead?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 91, 'player_1_4', 'I''ll wipe them from the face of this planet!'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 94, 'player_2_4', 'No, that''s a bit too dangerous.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 97, 'player_3_4', 'Where is the forest moon you visited?'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 100, 'player_reset_4', 'No, no more killing these animals!  I''m through with this, you crazy old man!'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 103, 'player_sorry_4', 'Yes, they''re all dead. But... more showed up, so I''ll kill them as well.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 104, 'next', 'I don''t have the funds to hire you any more. Come see me later.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 105, 'return_waypoint_description_1', 'Return to Pfilbee Jhorn to report that mission is completed.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 106, 'return_waypoint_description_2', 'Return to Pfilbee Jhorn to report that mission is completed.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 107, 'return_waypoint_description_3', 'Return to Pfilbee Jhorn to report that mission is completed.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 108, 'return_waypoint_name_4', 'Pfilbee Jhorn'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 109, 'return_waypoint_description_4', 'Return to Pfilbee Jhorn to report that mission is completed.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 110, 'waypoint_name_1', 'Womp rats'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 111, 'return_waypoint_name_2', 'Pfilbee Jhorn'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 112, 'return_waypoint_name_1', 'Pfilbee Jhorn'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 113, 'waypoint_name_2', 'Tatooine Mynocks'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 114, 'waypoint_name_3', 'Dragonets'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 115, 'waypoint_name_4', 'Dune Lizards'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 116, 'return_waypoint_name_3', 'Pfilbee Jhorn'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 117, 'waypoint_description_1', 'You have been ordered to exterminate the Womp Rats at this location by Pfilbee Jhorn.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 118, 'waypoint_description_2', 'You have been ordered to exterminate the Tatooine Mynocks at this location by Pfilbee Jhorn.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 119, 'waypoint_description_3', 'You have been ordered to exterminate the Dragonets at this location by Pfilbee Jhorn.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 120, 'waypoint_description_4', 'You have been ordered to exterminate the Dune Lizards at this location by Pfilbee Jhorn.'),
('string/en/static_npc/tatooine/pfilbee_jhorn.stf', 121, 'notyet', 'Who are you? Only loyal soldiers of the Empire should be in here!'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 1, 'npc_1_1', 'You offering me some help? I could sure use it, friend. Remember how I said that sabacc was bad for you? Well, somehow I got some dangerous characters mad at me. They insist I cheated and owe them money (something about an extra ace). Long story short, I ain''t got it so a brute is on his way to break my shapely legs. Help?'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 2, 'npc_1_2', 'You are one sweet individual. You know that? I''ll gladly accept your help again, ace. I know you took care of the Wookiee, but he was just hired muscle. His boss is still after me. Think you can get rid of him for me?'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 5, 'npc_2_1', 'See? I told myself you had a kind face. I''m rarely wrong about these things. The thug''s a Wookiee with absolutely no sense of humor. Goes by the name of Chalurrekk, although you can call him Chumpy. He likes that.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 6, 'npc_2_2', 'Is it any wonder you''re so popular, ace? This creep''s name is Korrkoressk. He''s a Trandoshan, in case you couldn''t tell from the name. Don''t let this killer get the drop on you - he''s one deadly lizard. Shoot first, save the questions for a cutie at the bar. I''m rooting for ya.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 8, 'npc_3_1', 'Oh, right. Not your problem. I gotcha. Well, nice talking to you. I gotta find someplace to hide.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 9, 'npc_3_2', 'I understand. This guy''s a serious gangster. I believe he''s connected to the main slug himself, Jabba. I suppose if I were you I wouldn''t wanna get involved either. Wish me luck, at least.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 12, 'npc_4_1', 'Cheat? Me? Do I look like the kind of gambler that would be caught cheating? Please, I''m way too clever for that. No, these slugs just thought it was me. The extra ace belonged to the Rodian who slipped out as soon as the trouble started.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 13, 'npc_4_2', 'Now I don''t want this to worry you, but this guy''s a serious gangster. I think he has ties with the big slug himself, Jabba. Not that I think you couldn''t take him. Besides, how will Jabba ever find out it was you who made this loser disappear? I won''t tell. Honest.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 15, 'npc_reward_1', 'You''re a pal! I knew you could take old Chumpy! As I said, I don''t have any money but I can give you this. It''ll bring you good luck. Honest. No, really.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 16, 'npc_reward_2', 'You took that killer out? Really? Wow! You''re one tough gundark, ace! I was saving this for a special occasion but this certainly seems to qualify. Enjoy it, ace. You''ve earned it.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 18, 'player_1_1', 'That;''s not right, them beating on a lady like you.  I''ll help.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 19, 'player_1_2', 'I won''t let anyone harm a lady!  I''ll kill the crime boss for you.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 21, 'player_2_1', 'I don''t see why I should get involved with this.  No thanks.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 22, 'player_2_2', 'Now you''re taking it a bit far.  No, I won''t get that for into this.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 24, 'player_3_1', 'Did you cheat?'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 25, 'player_3_2', 'Who''s the Wookiee''s boss?'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 27, 'player_reset_1', 'Probably, but I don''t want anything to do with this anymore.  Sorry.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 28, 'player_sorry_1', 'Yes, he still is, but I''m setting a trap for him.  You needn''t worry.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 29, 'npc_backtowork_1', 'Good.  I thank you, my good friend.  Let me know when I am fully safe.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 30, 'npc_reset_1', 'Oh, right. Not your problem. I gotcha. Well, nice talking to you. I gotta find someplace to hide.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 31, 'cantwork', 'Boy do I have problems. I''d share them with you but you seem kinda busy. If you get some time off, check back with me.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 32, 'dontknowyou_1', 'Wraaaarrrhhhhh!!!'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 33, 'npc_work_1', 'So, is the thug still coming for me?'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 34, 'npc_work_2', 'has that horrible Trandoshan been taken care of?'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 36, 'npc_breech_1', 'Snort! Grrumph! GRRWORRR!'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 37, 'npc_breech_2', 'You work for Valarian? You kill me and you''re as good as dead.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 42, 'npc_backtowork_2', 'I''ll stay hidden until then.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 44, 'npc_reset_2', 'I understand. This guy''s a serious gangster. I believe he''s connected to the main slug himself, Jabba. I suppose if I were you I wouldn''t wanna get involved either. Wish me luck, at least.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 46, 'player_reset_2', 'You know what?  Nevermind.  I''m not interested in helping you out.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 48, 'player_sorry_2', 'Not yet.  His guards are a bit difficult.  I''ll let you know when he''s gone.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 53, 'dontknowyou_2', 'Get out of my face.  I don''t know you.'),
('string/en/static_npc/tatooine/phinea_shantee.stf', 54, 'next', 'I''m all set for now, ace. Check back with me later.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 1, 'npc_1_1', 'Well then. This is not to go beyond this office. A certain Imperial official has assiduously fabricated false evidence to implicate this office in a bribery scandal. Lies, I assure you. A henchman is even now heading toward Bestine to deliver this evidence. In the name of truth and fairness, you are to assassinate this henchman.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 2, 'npc_1_2', 'The Stormtroopers in my Guardian Squadron recently found and destroyed an advanced assassin droid. A similar droid killed my predecessor, Orun Depp. Evidence on the droid implicates Gohn Bimmin, a droid engineer in my own service. Will you find and kill this traitor?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 3, 'npc_1_3', 'The droid engineer you recently terminated for me was hired by members of the Hutt gang. I have identified the intermediary who bribed the engineer. Will you execute my righteous revenge?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 5, 'npc_2_1', 'Very well. You seek a minor gangster called Akkar Plint. He belongs to the notorious Swang''s Swoopers gang. I doubt he''ll be heavily armed, but then, I have no idea of your own capacities. Therefore, expect the worst.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 6, 'npc_2_2', 'I thought so. One of my operatives planted a tracking beacon on Bimmin, and I have waited to take my vengeance until he is likely to be isolated and alone. That time has arrived. Go.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 7, 'npc_2_3', 'Splendid. Through you I now carry my war against the Hutt gang straight to their own doorways. Your way lies clear!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 8, 'npc_3_1', 'As you will. Note that if I hear rumors circulating regarding this henchman''s sad fate, I will know who spread the rumors, and it will go badly for you. You may go.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 9, 'npc_3_2', 'It is unimaginable to me that you would allow such treachery to go unpunished. I shall remember that about you.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 10, 'npc_3_3', 'I am perplexed. Is the hunting and killing of a known criminal beneath you? How nice to have such lofty morals. This meeting is over.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 12, 'npc_4_1', 'I''m sure the official''s identity falls within a security classification higher than any you possess. Do you want this assignment?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 13, 'npc_4_2', 'I suspect the traitorous Bimmin has been bribed by one of the Hutt gangsters. I have spread far and wide, even to Imperial Center, that I am determined to root out their evil. They fear me, as who would not? Will you take the assignment?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 14, 'npc_4_3', 'Your quarry is an alien, an escaped slave of the Wookiee species. He is one of Jabba''s many hirelings. Killing that thug will only benefit this world and this office. What do you say?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 15, 'npc_reward_1', 'You have struck a blow for the integrity of this office! Damage to the Prefecture would have been severe. That would only weaken the social fabric of this great -- er -- of this world. Return to me in the future for more work.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 16, 'npc_reward_2', 'This hopeless betrayer has come to a just end. Never forget that to obstruct the rise of Talmont is to meddle with forces beyond control!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 17, 'npc_reward_3', 'This stern teaching has now been tattooed on this world''s dark underbelly: To attack Talmont is to commit folly! Fine work; you may contact me again.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 18, 'player_1_1', 'I understand and accept this duty.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 19, 'player_1_2', 'I will deal with this traitor personally.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 20, 'player_1_3', 'I shall do so for the glory of the Empire.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 21, 'player_2_1', 'I will assassinate no one!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 22, 'player_2_2', 'I cannot do this.  There are other ways of bringing him to justice.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 23, 'player_2_3', 'No, I do not answer to you, Prefect.  Send one of your cronies.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 24, 'player_3_1', 'Who is the "certain Imperial official" that the henchman works for?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 25, 'player_3_2', 'Why would your own engineer try to kill you?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 26, 'player_3_3', 'Who bribed the engineer?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 27, 'player_reset_1', 'I have reconsidered.  I''m not a professional assassin by heart, and I can no longer do this.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 28, 'player_sorry_1', 'Not yet, but I''m about to leave to take care of him.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 29, 'npc_backtowork_1', 'You must make haste.  If that false information reaches the hands of Tour Aryon, this will come down on your head.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 30, 'npc_reset_1', 'As you will. Note that if I hear rumors circulating regarding this henchman''s sad fate, I will know who spread the rumors, and it will go badly for you. You may go.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 31, 'cantwork', 'You have a lot to do already. Come see me when you''ve got a little more free time.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 32, 'dontknowyou_1', 'Nevermind, I don''t know you.  Sorry about that.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 33, 'npc_work_1', 'Has the messenger been taken care of?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 34, 'npc_work_2', 'Has Bimmin been taken care of?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 35, 'npc_work_3', 'I assume you have dealt with the thug, correct?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 36, 'npc_breech_1', 'You try killin'' me, an'' the Moff''ll be all over you, you creep! That''s right! Tour Aryon, an'' none other!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 37, 'npc_breech_2', 'Aah! Talmont found out! I knew that gangster would -- Well, I didn''t take all that money just to die young and poor!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 38, 'npc_breech_3', 'Hnnaarrgh!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 42, 'npc_backtowork_2', 'You must be more efficient than this.  The longer you wait, the better a chance he has to escape.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 43, 'npc_backtowork_3', 'You have the opportunity to teach Jabba not to interfere with the Empire, yet you tarry.  I highly suggest you expedite this, citizen.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 44, 'npc_reset_2', 'It is unimaginable to me that you would allow such treachery to go unpunished. I shall remember that about you.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 45, 'npc_reset_3', 'I am perplexed. Is the hunting and killing of a known criminal beneath you? How nice to have such lofty morals. This meeting is over.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 46, 'player_reset_2', 'I''ve changed my mind.  I cannot kill someone in cold blood.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 47, 'player_reset_3', 'No, I''m not going to be able to this after all.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 48, 'player_sorry_2', 'No, he has eluded me, but not for long.  He will be taken care of shortly.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 49, 'player_sorry_3', 'I... um.. got the wrong Wookiee.  I''m still tracking down the one working for Jabba.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 53, 'dontknowyou_2', 'Oh, I''m sorry.  I thought you were here to - well - nevermind.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 54, 'dontknowyou_3', 'Hnnaarrgh.  Hngh.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 55, 'dontknowyou_4', 'Oooh.  I thought you is someone who you is not.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 56, 'dontknowyou_5', 'Oh, sorry, I thought you were someone else.  Carry on.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 57, 'dontknowyou_6', 'You don''t work for the Prefect?  Oh, okay.  I''m sorry about that misunderstanding.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 61, 'npc_1_4', 'The planetary governor, Tour Aryon, has enlisted an ISB officer in a foolish quest to complicate my life. Of course I respect the ISB, but the informant who lied to that officer must die. This task falls to you, if you will.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 62, 'npc_1_5', 'Discretion is mandatory. The Moff has embarked on another silly scheme to discredit me. She has inveigled an Imperial Intelligence officer to slander my office. I may have ways of dealing with the officer, but I am hampered by his formidable Zabrak bodyguard. I require you to dispose of the guard, so that I can work my will.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 63, 'npc_1_6', 'The madwoman Tour Aryon has lured an Imperial Inquisitor to Tatooine! Insanity! The Inquisitor is even now tort-- interrogating informants at the Pit of Carkoon. Heed me: There is one man, not yet caught, who absolutely must not fall into the Inquisitor''s grasp. You must terminate that individual at once.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 64, 'npc_2_4', 'You seek a Bothan female named Nwilla Thar-- Thal-- well, "Nwilla" will do. Watch those Bothans. They''re crafty. Go!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 65, 'npc_2_5', 'My spies have placed the Zabrak bodyguard at these coordinates. Move quickly, and expect pronounced resistance from the target. Tell no one!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 66, 'npc_2_6', 'Here are the coordinates. Move quickly. Leave no one alive.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 67, 'npc_3_4', 'I daresay your unpredictability must serve you in battle. But it is a charmless trait in social life. You may go now.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 68, 'npc_3_5', 'For once I cannot blame you. This assignment is more challenging than most of your ilk could handle. You may go.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 69, 'npc_3_6', 'Speak of this to no one. Get out.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 70, 'npc_4_4', 'The Moff may mean well, in her wayward, slapdash way. But her methods are misguided. Pernicious. I will say no more. What is your decision?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 71, 'npc_4_5', 'The Intelligence officer''s bodyguard is Klaua Jik, a female veteran of the Dathomir prison. She was drummed out for insubordination and has since lived a renegade existence. The Imperial officer hired her, freelance, specifically for this trip.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 72, 'npc_4_6', 'He was my -- I was -- never mind! I shall only say that if this man falls into the Inquisitor''s hands, my career is over. Do you hear? Over! Accept or refuse, now!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 73, 'npc_backtowork_4', 'You must not delay.  Take care of this and do not return until unless you have positive news to report.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 74, 'npc_backtowork_5', 'This is good news.  Return when you have a full report on the events that transpired.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 75, 'npc_backtowork_6', 'Do NOT tell me what and what not to do.  Until he is dead, I have much to worry about.  Remove him immediately!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 76, 'npc_breech_4', 'Ick! No! I was guarantee-ee-ed ee-muniteee!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 77, 'npc_breech_5', 'Are you the one who tricked me away from my boss? You lousy scum, I''ll kill you! '),
('string/en/static_npc/tatooine/prefect_talmont.stf', 78, 'npc_breech_6', 'Wha-- who sent you? The Prefect? He would never do that! Liar!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 79, 'npc_reset_4', 'I daresay your unpredictability must serve you in battle. But it is a charmless trait in social life. You may go now.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 80, 'npc_reset_5', 'For once I cannot blame you. This assignment is more challenging than most of your ilk could handle. You may go.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 81, 'npc_reset_6', 'Speak of this to no one. Get out.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 82, 'npc_reward_4', 'Before long the criminal underworld of Tatooine will understand my mighty purpose. And the lessons that I hone and perfect here. These lessons I will carry on to greater horizons!'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 83, 'npc_reward_5', 'This is good news. I remind you to keep these proceedings secret, or you yourself will meet the Zabrak''s fate.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 84, 'npc_reward_6', 'Your services has been invaluable to me and the greater good of the Empire. It''s a sad time when wearing the Prefect''s uniform is to wrap oneself in thorns and razorwire. Go, I am distraught.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 88, 'npc_work_4', 'I am glad to see that you have effectively dealt with the Bothan.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 89, 'npc_work_5', 'Have you been able to remove the body guard from the picture?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 90, 'npc_work_6', 'Has Harbo been silenced - er- I mean, taken care of?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 91, 'player_1_4', 'I shall gladly do this.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 92, 'player_1_5', 'Sounds like a challenge I''m up for.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 93, 'player_1_6', 'If it is as important as you make it sound, I will do it.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 94, 'player_2_4', 'I am tired of being your personal assassin, Talmont.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 95, 'player_2_5', 'Personal bodyguard?  Sounds too dangerous.  No.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 96, 'player_2_6', 'I will not interfere with one of the Emperor''s Inquisitors.  No.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 97, 'player_3_4', 'Why does Tour Aryon want to complicate your life?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 98, 'player_3_5', 'Who is the bodyguard?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 99, 'player_3_6', 'Why is this man so important?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 100, 'player_reset_4', 'I''ve had a change of heart, Talmont.  I cannot do this for you.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 101, 'player_reset_5', 'I''ve thought about it and I don''t think I can take on this bodyguard.  Sorry.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 102, 'player_reset_6', 'This sounds too personal and I don''t want to do this anymore.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 103, 'player_sorry_4', 'Um... I have yet to take care of the Bothan.  I shall do so soon.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 104, 'player_sorry_5', 'Not yet, but I think I''ve found a way.  I shall be engaging her soon.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 105, 'player_sorry_6', 'I have yet to find him.  If I haven''t found him yet, that means the Inquisitor hasn''t either.  Don''t worry.'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 106, 'notyet', 'You are not strong enough in your Imperial conviction, or maybe you forgot to talk to Wilhalm Skrim?'),
('string/en/static_npc/tatooine/prefect_talmont.stf', 107, 'next', 'That''s all I have for you right now. Perhaps later I''ll have more for you.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 1, 'npc_1_1', 'Some troublemaker in Mos Espa is trying to undermine Drik''s local mining business. This guy is a bad piece of work; Drik says he''s accused of several murders. The troublemaker''s sending a saboteur to blow up the mine. I want you to stop the saboteur.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 2, 'npc_1_2', 'You may recall that saboteur who said my current boss, Drik Bandrik, is a slaver. I need to know if that''s true. I don''t like slavers. I''d like you to meet with a Bothan spy who has the truth. But don''t tell Drik.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 3, 'npc_1_3', 'A spy has obtained records from a Mos Eisley repository owned by Jabba the Hutt. Jabba stole the records long ago from a rival Hutt crimelord. Now the Hutts are after my spy. Can you bring her here?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 5, 'npc_2_1', 'Right. I''m told the saboteur is a Twi''lek named Binz. I doubt he''ll let himself be quietly arrested. Report back once you''ve resolved the matter.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 6, 'npc_2_2', 'All right. You''re looking for a Bothan named Silm''an Voueen. She''ll have a datadisc for you. Bring it back here.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 7, 'npc_2_3', 'Good. I''ve got a lot riding on this. Please hurry.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 8, 'npc_3_1', 'That''s all right. I expect we can handle one saboteur ourselves.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 9, 'npc_3_2', 'All right. I''d still appreciate it if you didn''t let this get back to Drik.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 10, 'npc_3_3', 'Sorry to hear that. I''ve got a lot riding on this. But I''ll try to make it happen on my own. Thanks anyway.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 12, 'npc_4_1', 'Some guy who claims there are problems with "working conditions" at the mine. Drik says the guy is actually a mine owner, out to undermine the competition. Can I count on you to stop his saboteur?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 13, 'npc_4_2', 'I had my own ship. Ran controlled medicines to Outer Rim worlds to bypass Corporate Sector surcharges. Lost my family in a Hutt pirate raid, and since then I''ve been wanting to get back at the Hutts. But right now, I need your decision.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 14, 'npc_4_3', 'They''re records of Gardulla the Hutt''s slave purchases and transfers. I don''t know what the records say, but it''s probably important, or the Hutts wouldn''t be after them so soon.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 15, 'npc_reward_1', 'Binz said Drik is a slaver? That''s not the way I understand it. Except -- hmm. I need to look into that. Check back with me later.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 16, 'npc_reward_2', '"Kitster"? Are you sure he said the troublemaker is named "Kitster"? Oh no. Wait, maybe it''s a coincidence. All right, I have to get some questions answered, fast. See me again later.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 17, 'npc_reward_3', 'It''s true, then. Drik Bandrik has played me like a dejarik piece, sending me to attack my son. My own son! Friend, check with me again. I have more work for you.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 18, 'player_1_1', 'Sure, I''ll do it.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 19, 'player_1_2', 'I''ll do it. I''d like to know, as well.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 20, 'player_1_3', 'I''ll do it.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 21, 'player_2_1', 'No thanks. That''s not my style.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 22, 'player_2_2', 'No thanks.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 23, 'player_2_3', 'Sorry, I''m not a bodyguard.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 24, 'player_3_1', 'Who is the troublemaker, and why is he making trouble?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 25, 'player_3_2', '"Current" boss? What were you before you worked here?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 26, 'player_3_3', 'What are these records?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 27, 'player_reset_1', 'I''m sorry, I won''t be able to help you any more.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 28, 'player_sorry_1', 'Not yet.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 29, 'npc_backtowork_1', 'What am I paying you for? Get to work and stop him!'),
('string/en/static_npc/tatooine/rakir_banai.stf', 30, 'npc_reset_1', 'That''s all right. I expect we can handle one saboteur ourselves.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 31, 'cantwork', 'Hello. I think you''ll find it worthwhile to check back here when you''re less busy.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 33, 'npc_work_1', 'Has the troublemaker come to an end?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 34, 'npc_work_2', 'So, what were you able to find out?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 35, 'npc_work_3', 'So where is she? She''s not dead, is she?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 36, 'npc_breech_1', 'If you''re working for Drik Bandrik, you''ll die like his slaves are dying!'),
('string/en/static_npc/tatooine/rakir_banai.stf', 37, 'npc_breech_2', 'Ee-oo! Ee-you are the one I meet?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 38, 'npc_breech_3', 'If you have anything less that noble intentions, know that I''m armed.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 40, 'notit_2', 'Hmm... no, this has nothing on it that tells me anything. Tell the Bothan I need the information I''ve paid for.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 42, 'npc_backtowork_2', 'Well, I''d appreciate it if you''d pick up the pace. I''m very curious as to know what the truth is.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 43, 'npc_backtowork_3', 'Hurry, please. I''ve got a lot riding on this.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 44, 'npc_reset_2', 'All right. I''d still appreciate it if you didn''t let this get back to Drik.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 45, 'npc_reset_3', 'Sorry to hear that. I''ve got a lot riding on this. But I''ll try to make it happen on my own. Thanks anyway.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 46, 'player_reset_2', 'I''m sorry, I won''t be able to help you any more.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 47, 'player_reset_3', 'I''m sorry, I won''t be able to help you any more.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 48, 'player_sorry_2', 'Nothing yet. I haven''t met up with the Bothan.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 49, 'player_sorry_3', 'No, she''s not. I''m about to go pick her up.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 52, 'npc_takeme_3', 'Jabba stole these records long ago from a rival Hutt crimelord, Gardulla. Rakir will find them very interesting. Please take me to him.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 53, 'dontknowyou_2', 'No. Ee-you are not the one.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 54, 'dontknowyou_3', 'Sorry about the threat.  I thought you were a thug.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 58, 'notit_4', 'No, this isn''t the contract I signed.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 61, 'npc_1_4', 'Drik''s majordomo, Wizzel, holds my contract. I want you to get that contract back, by force. After I''m free, I''ll look for my son, Kitster. What do you say?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 64, 'npc_2_4', 'Good. Wizzel will probably only let you have it over his dead body. That''s fine with me.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 67, 'npc_3_4', 'All right. Well, you''ve been a big help so far, so I guess I can carry this matter the rest of the way through alone. Thanks.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 70, 'npc_4_4', 'I''m sending out messengers to the various cities, based on the information you brought me before. I''m glad there are so few cities on this rock -- the search shouldn''t take long. I hope. I can''t remember the last time I hoped for something so much. Well, will you help me?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 73, 'npc_backtowork_4', 'Once I have that contract in my hands, I will delight in ripping it up into a thousand pieces!'),
('string/en/static_npc/tatooine/rakir_banai.stf', 76, 'npc_breech_4', 'You don''t leave Drik''s service. He fires you. Permanently. Like this!'),
('string/en/static_npc/tatooine/rakir_banai.stf', 79, 'npc_reset_4', 'All right. Well, you''ve been a big help so far, so I guess I can carry this matter the rest of the way through alone. Thanks.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 82, 'npc_reward_4', 'Thank you very much! Someone misordered this shellfish harvester, won''t have much use for that here. You can take it in addition to your credit payment, hopefully you can find some use for it. I''ve sent out messengers to find my son. Take care of yourself!'),
('string/en/static_npc/tatooine/rakir_banai.stf', 88, 'npc_work_4', 'Do you have my... grrr... "contract"?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 91, 'player_1_4', 'I''ll be more than happy to help!'),
('string/en/static_npc/tatooine/rakir_banai.stf', 94, 'player_2_4', 'I''m not going this far. Hire someone else.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 97, 'player_3_4', 'How will you find your son?'),
('string/en/static_npc/tatooine/rakir_banai.stf', 100, 'player_reset_4', 'I''m sorry, I won''t be able to help you any more.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 103, 'player_sorry_4', 'Not yet. I''ll let you know when I do.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 107, 'npc_smuggle_2', 'Ee-yes, this data describes Drik Bandrik''s slave operation. I enclose certain extra data about the troublemaker, Kitster. Perhaps ee-your employer will pay a bit more for this.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 108, 'next', 'I''m waiting to hear from the searchers looking for my son. I appreciate how you helped me find out the truth.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 109, 'gotowork_2', 'I have told you all that I can. Please take care of this matter as soon as you can.'),
('string/en/static_npc/tatooine/rakir_banai.stf', 110, 'gotowork', 'I have told you all that I can. Please take care of this matter as soon as you are able.'),
('string/en/static_npc/tatooine/sango_rond.stf', 1, 'npc_1_1', 'Would you terribly mind going out and destroying a certain gangster who stole one of the Jawas'' droid verbobrains? And do bring back the brain, of course.'),
('string/en/static_npc/tatooine/sango_rond.stf', 2, 'npc_1_2', 'Recall that droid brain you fetched for me? Well, the Jawas put it into the droid''s body, and the thing went absolutely berserk. Quite awful. It seems the Hutts have slicers out in the desert, and they are controlling the droid. Can you be a good soldier and dispose of them?'),
('string/en/static_npc/tatooine/sango_rond.stf', 3, 'npc_1_3', 'Well, you may recall our earlier matter of the killer droid? Yes, that''s the one. That droid is now out in the desert, all on its own. Nasty thing. Could you, um, blow it up a little?'),
('string/en/static_npc/tatooine/sango_rond.stf', 5, 'npc_2_1', 'This criminal fellow works for the Hutts, but he himself, I''m glad to say, is a human. Or perhaps I should be sorry about that. Well, never mind! I suggest you can locate him at these coordinates. Don''t forget my brain!'),
('string/en/static_npc/tatooine/sango_rond.stf', 6, 'npc_2_2', 'Well then! Look for the slicers at these coordinates. Note well! They are odd and detestable in manner, but not without skills in weaponry. Report back here after treating them mercilessly.'),
('string/en/static_npc/tatooine/sango_rond.stf', 7, 'npc_2_3', 'Fine, fine. Now, proceed to the coordinates given by the droid''s homing beacon. I recommend extreme caution and heavy firepower.'),
('string/en/static_npc/tatooine/sango_rond.stf', 8, 'npc_3_1', 'Ah! Well. No problem, no problem. Enjoy the weather, then!'),
('string/en/static_npc/tatooine/sango_rond.stf', 9, 'npc_3_2', 'Ah, well. That''s to be understood. This is not a matter to take lightly. Enjoy the weather, then!'),
('string/en/static_npc/tatooine/sango_rond.stf', 10, 'npc_3_3', 'Ah, well. I understand. This is a matter for brave hearts. Enjoy the weather, do!'),
('string/en/static_npc/tatooine/sango_rond.stf', 12, 'npc_4_1', 'Ah! Right! I am an itinerant buyer for a commodities dealer in Mos Espa. I have learned the Jawa language, and I find myself strangely attracted to Jawa culture. It''s quite, quite -- well, enough of that. What about my little task, then?'),
('string/en/static_npc/tatooine/sango_rond.stf', 13, 'npc_4_2', 'Possibly those Hutt gangster scoundrels reprogrammed the verbobrain. The droid lashed out on all sides, killing Jawas right and left. Its behavior was utterly unwelcome. What, then, is your decision?'),
('string/en/static_npc/tatooine/sango_rond.stf', 14, 'npc_4_3', 'What -- ah -- what kind? Ah! Yes! Interesting question, most interesting. I -- ah -- I don''t know. No indeed. Now, your decision?'),
('string/en/static_npc/tatooine/sango_rond.stf', 15, 'npc_reward_1', 'Ah! Splendid! I daresay we''ll have this verbobrain back in place in no time. Meanwhile, here is a bit of a reward, and do please check back for more work, right?'),
('string/en/static_npc/tatooine/sango_rond.stf', 16, 'npc_reward_2', 'Ah, excellent! I admire your cunning and dispatch. I present you this reward. Now there is that little matter of the berserk droid, so do please check back for further work.'),
('string/en/static_npc/tatooine/sango_rond.stf', 17, 'npc_reward_3', 'Ah, welcome back! All went well, I take it. What''s that? An assassin droid? Why, how remarkable. Really. Well. Tell you what, you take this reward and we''ll say no more about it. To anyone. Enjoy the weather!'),
('string/en/static_npc/tatooine/sango_rond.stf', 18, 'player_1_1', 'Sure, I''ll deal with the gangster.'),
('string/en/static_npc/tatooine/sango_rond.stf', 19, 'player_1_2', 'Absolutely!'),
('string/en/static_npc/tatooine/sango_rond.stf', 20, 'player_1_3', 'I''ll stop it from harming anyone else?'),
('string/en/static_npc/tatooine/sango_rond.stf', 21, 'player_2_1', 'Sorry, I''m not available right now.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/sango_rond.stf', 22, 'player_2_2', 'Sorry, I''m not available right now.'),
('string/en/static_npc/tatooine/sango_rond.stf', 23, 'player_2_3', 'No, this sounds too dangerous.  You should contact the authorities.'),
('string/en/static_npc/tatooine/sango_rond.stf', 24, 'player_3_1', 'What brought you way out here?'),
('string/en/static_npc/tatooine/sango_rond.stf', 25, 'player_3_2', 'Why did the droid go berserk, and what happened?'),
('string/en/static_npc/tatooine/sango_rond.stf', 26, 'player_3_3', 'What kind of droid is it?'),
('string/en/static_npc/tatooine/sango_rond.stf', 27, 'player_reset_1', 'Something came up.  I can''t do this anymore.'),
('string/en/static_npc/tatooine/sango_rond.stf', 28, 'player_sorry_1', 'Not yet, but I''ll get it soon.'),
('string/en/static_npc/tatooine/sango_rond.stf', 29, 'npc_backtowork_1', 'Take your time, friend.'),
('string/en/static_npc/tatooine/sango_rond.stf', 30, 'npc_reset_1', 'Ah! Well. No problem, no problem. Enjoy the weather, then!'),
('string/en/static_npc/tatooine/sango_rond.stf', 31, 'cantwork', 'Ah! Hullo! I handle much of the untoward business around here -- "dirty work," haha. I suggest you check back when you''re available.'),
('string/en/static_npc/tatooine/sango_rond.stf', 33, 'npc_work_1', 'Have you managed to get the brain back?'),
('string/en/static_npc/tatooine/sango_rond.stf', 34, 'npc_work_2', 'Have the slicers been stopped?'),
('string/en/static_npc/tatooine/sango_rond.stf', 35, 'npc_work_3', 'Has the droid been deactivated yet?'),
('string/en/static_npc/tatooine/sango_rond.stf', 36, 'npc_breech_1', 'This sleemo''s tryin'' to steal the droid brain! Attack!'),
('string/en/static_npc/tatooine/sango_rond.stf', 37, 'npc_breech_2', 'Ooh, a visitation. Smooth! Everyone do your part until the droid shows up.'),
('string/en/static_npc/tatooine/sango_rond.stf', 38, 'npc_breech_3', 'New Behavior Dictated : Terminate Target With Extreme Prejudice.'),
('string/en/static_npc/tatooine/sango_rond.stf', 42, 'npc_backtowork_2', 'You might want to pick up the pace a bit.  There''s no telling what those slivers plan on doing with that droid.'),
('string/en/static_npc/tatooine/sango_rond.stf', 43, 'npc_backtowork_3', 'Good, good.  I will feel much safer knowing it has been decomissioned.'),
('string/en/static_npc/tatooine/sango_rond.stf', 44, 'npc_reset_2', 'Ah, well. That''s to be understood. This is not a matter to take lightly. Enjoy the weather, then!'),
('string/en/static_npc/tatooine/sango_rond.stf', 45, 'npc_reset_3', 'Ah, well. I understand. This is a matter for brave hearts. Enjoy the weather, do!'),
('string/en/static_npc/tatooine/sango_rond.stf', 46, 'player_reset_2', 'I''m a bit apprehensive about this.  I''m not sure my skills will be able to stop these guys.  Sorry.'),
('string/en/static_npc/tatooine/sango_rond.stf', 47, 'player_reset_3', 'I don''t believe I''ll be able to handle this droid.  You may need to have someone else do it.'),
('string/en/static_npc/tatooine/sango_rond.stf', 48, 'player_sorry_2', 'Not yet, but they''ll be taken care of soon.'),
('string/en/static_npc/tatooine/sango_rond.stf', 49, 'player_sorry_3', 'Not yet, but I''m about to take care of it right now.'),
('string/en/static_npc/tatooine/sango_rond.stf', 109, 'notit_1', 'I know it''s possible that the brain was altered, but I don''t think it was altered THIS much.'),
('string/en/static_npc/tatooine/sango_rond.stf', 110, 'next', 'Ah! You''re back. Yes. Well -- ah -- nothing for you here, I''m afraid. But good to see you nonetheless.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 1, 'npc_1_1', 'Looking to make some money, huh? I can understand that. I could use a discreet courier, if you''re up to making a pickup. My client wishes to remain anonymous, so the less attention you draw, the better. You fine with that?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 2, 'npc_1_2', 'Okay, hotshot, ready to play the part of a discreet courier again? I need you to deliver this datadisc to my client''s droid, Envoy -- remember him? As usual, don''t let anyone see you and don''t let this disc fall into anyone else''s digits that are not silver and metallic. We got a deal? '),
('string/en/static_npc/tatooine/senni_tonnika.stf', 3, 'npc_1_3', 'You know, I was hoping you''d ask about work. Remember how Envoy said my client would contact me again? What can I say? I need your magic courier skills again. You should know the drill by now. This time around it''s a pickup. Interested?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 5, 'npc_2_1', 'Good. I''ll transmit your image to the droid you''ll be dealing with, so he recognizes you. Remember, the fewer individuals that see you, the happier my client will be. And under no circumstances should you let that datadisc fall into the wrong hands.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 6, 'npc_2_2', 'All right. The droid should remember you from last time. I retransmitted your image, just in case. And since we now know that Talmont has taken an interest in this transaction, keep an eye out for Imperial patrols. Good luck.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 7, 'npc_2_3', 'Great! I''m sure everything will go smoothly. But if by chance you should see someone following you, don''t hesitate to open fire. You can''t be too careful these days. Hurry back!'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 8, 'npc_3_1', 'Suit yourself. See you around.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 9, 'npc_3_2', 'Too much excitement for you last time? I gotcha. Have a good one.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 10, 'npc_3_3', 'Come on, hotshot. This droid knows you and trusts you. I doubt the Imperials will get involved this time. I''m disappointed.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 12, 'npc_4_1', 'Codes on a datadisc that will help insure a smooth business transaction. They''re encrypted, of course - so don''t get any funny ideas. You in?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 13, 'npc_4_2', 'Confirmation codes that prove my client''s bet was placed and my fee was deducted. And yes, it''s encrypted. We doing business?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 14, 'npc_4_3', 'You''re sharp, hotshot, no doubt about it. Yep, it''s a new set of codes. Apparently my client got an "anonymous tip" and now wants to change his bet. So you helping me out or what?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 15, 'npc_reward_1', 'Double the wager on Idee? Will do. That hired blaster didn''t give you too much trouble, I hope. Not too bright of the lug to tell you who hired him, huh? It''s hard to find good help these days.  '),
('string/en/static_npc/tatooine/senni_tonnika.stf', 16, 'npc_reward_2', 'Those stormtroopers never listen to reason, do they? Hmm, I wonder why my client wants to contact me again? I guess I''ll just have to wait and see. Good job, hotshot.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 17, 'npc_reward_3', 'Triple the bet on Lam Bregaani? Okay, I do what I''m told. I hope my client''s sources are reliable. But listen, I couldn''t have done all this without you. You may not realize it, but you''ve made me one very happy (and rich) lady. Enjoy your reward.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 18, 'player_1_1', 'Yes, I''m up for it.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 19, 'player_1_2', 'Sure, I''ll do it.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 20, 'player_1_3', 'Why not.  I''ll do it.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 21, 'player_2_1', 'No, I''m not interested.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 22, 'player_2_2', 'No thanks.  It doesn''t sound like a good time.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 23, 'player_2_3', 'No thanks.  I''m tired of this kind of work.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 24, 'player_3_1', 'What am I picking up?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 25, 'player_3_2', 'What''s on the disc this time?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 26, 'player_3_3', 'Let me guess? Another encrypted datadisc?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 27, 'player_reset_1', 'This sounds too important for me.  I can''t do it after all.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 28, 'player_sorry_1', 'Nothing yet.  I''m making sure that everything will go smoothly.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 29, 'npc_backtowork_1', 'That''s good to hear.  Let me know when it''s done.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 30, 'npc_reset_1', 'Suit yourself. See you around.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 31, 'cantwork', 'Come back and see me when you don''t look so harried.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 32, 'dontknowyou_1', 'No, I''m sorry.  You don''t match the person I''m intended to meet.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 33, 'npc_work_1', 'Why are you back?  Did anything go wrong with the transaction?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 34, 'npc_work_2', 'Don''t tell me.  Talmont got to the droid before you?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 35, 'npc_work_3', 'Where are the codes?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 36, 'npc_breech_1', 'Would you mind stepping forward so that I may analyze your features?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 37, 'npc_breech_2', 'Would you mind stepping forward so that I may analyze your features?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 38, 'npc_breech_3', 'Would you mind stepping forward so that I may analyze your features?'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 41, 'notit_3', 'These aren''t the codes.  I''m only interested in those codes.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 42, 'npc_backtowork_2', 'Why?  I thought you understood that Envoy was waiting for you.  Don''t botch this, or I might be a bit upset...'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 43, 'npc_backtowork_3', 'Well, get on it then.  A slow courier is an out-of-work courier.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 44, 'npc_reset_2', 'Too much excitement for you last time? I gotcha. Have a good one.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 45, 'npc_reset_3', 'Come on, hotshot. This droid knows you and trusts you. I doubt the Imperials will get involved this time. I''m disappointed.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 46, 'player_reset_2', 'I''ve changed my mind.  I don''t want to cross Prefect Talmont.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 47, 'player_reset_3', 'Something came up.  I can''t do this for you.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 48, 'player_sorry_2', 'No, I haven''t left yet.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 49, 'player_sorry_3', 'I don''t have them yet.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 53, 'dontknowyou_2', 'No, I''m sorry.  You don''t match the person I''m intended to meet.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 54, 'dontknowyou_3', 'No, I''m sorry.  You don''t match the person I''m intended to meet.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 106, 'npc_smuggle_1', 'Salutations, I am Envoy. My master wishes to inform your employer that she is to double his wager on Idee Zipbits. I do hope that makes sense to you. '),
('string/en/static_npc/tatooine/senni_tonnika.stf', 107, 'npc_smuggle_2', 'Thank you. My master will review these materials carefully. Tell your employer to expect to hear from us again.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 108, 'npc_smuggle_3', 'My master wishes to cancel his previous bet and put triple that amount on Lam Bregaani. He refuses to listen to any more of your employer''s advice, I''m afraid. I beg your pardon if this sounds rude.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 109, 'notit_1', 'What is this?  This isn''t the datadisk I wanted.'),
('string/en/static_npc/tatooine/senni_tonnika.stf', 110, 'next', 'Hi again, hotshot. Not much happening here -- at least nothing I can talk about. Catch me again later, okay?'),
('string/en/static_npc/tatooine/stella.stf', 1, 'npc_1_1', 'Ah yes yes. Welcome to the Third Sun, center of rollicking jollity in sunny Mos Taike. I, Stella, am to need sharp eyeballs to find problem customers in the desert. They did run without paying, and for Stella this is the crime of crimes. What is to be your willingness to help me?'),
('string/en/static_npc/tatooine/stella.stf', 2, 'npc_1_2', 'I, Stella, for a long time have been owning this cantina. But now a stinking fink who is to be working for Jabba the Hutt did steal the cantina''s valuable deed. He is to be taking it to Jabba, and Jabba is to be owning this excitable joint! You are to be stopping him, yes?'),
('string/en/static_npc/tatooine/stella.stf', 3, 'npc_1_3', 'I did pay a Bothan spy to be finding information for me. He now has the data, but he is to be sending nothing over the HoloNet. I do now ask you, my friend, to be meeting the Bothan and getting the data. Yes?'),
('string/en/static_npc/tatooine/stella.stf', 5, 'npc_2_1', 'Ah, yes yes. I did locate these stinking finks outside town at these coordinates. You are to be going there, getting the credits from them, but not to be killing anyone. Dead folks are not to be paying, yes?'),
('string/en/static_npc/tatooine/stella.stf', 6, 'npc_2_2', 'Ah, yes yes. You are to be looking for Ulek Talstin. He is a dangerous stinking fink, so good luck to you, yes.'),
('string/en/static_npc/tatooine/stella.stf', 7, 'npc_2_3', 'Ah, yes yes. You are to be going to the coordinates the Bothan did give me. It is secret, yes? He is to be giving you a disk to bring back here.'),
('string/en/static_npc/tatooine/stella.stf', 8, 'npc_3_1', 'Ah, okay, ah. This is not to be a problem. I, Stella, welcome you anyway anyhow to sunny Mos Taike. Drink!'),
('string/en/static_npc/tatooine/stella.stf', 9, 'npc_3_2', 'Ah, okay, ah. This is not to be a problem. I, Stella, still welcome you to this cantina that I am not to be owning. Drink!'),
('string/en/static_npc/tatooine/stella.stf', 10, 'npc_3_3', 'Ah! I am most sorry. Ah well. No, it is not to be a problem. I, Stella, still welcome you to this cantina that Jabba is to be owning. Drink!'),
('string/en/static_npc/tatooine/stella.stf', 12, 'npc_4_1', 'Ah, "Stella" yes. "Stella" is the short name of my name, D''Mayna Stallaphalat. I am Bith, as you see. My father did forget me here as a small child. What is to be your choice of my job?'),
('string/en/static_npc/tatooine/stella.stf', 13, 'npc_4_2', 'Police? This is sunny Mos Taike, where law is to be coming out of a blaster barrel, yes yes. You are to be deciding now?'),
('string/en/static_npc/tatooine/stella.stf', 14, 'npc_4_3', 'Ha! I, Stella, am knowing everyone in Mos Taike! I am on hello-terms with spies, miners, officers, farmers, Rebels, cops! -- Except, you are not to be telling anyone about the "Rebels" part. What is to be your choice, what?'),
('string/en/static_npc/tatooine/stella.stf', 15, 'npc_reward_1', 'Ah, this is to be thanked! Strange is the Mos Taike cantina business, yes yes. Sometime you are to ask me about it, and I, Stella, am to tell stories to curl your fur.'),
('string/en/static_npc/tatooine/stella.stf', 16, 'npc_reward_2', 'Yes yes! All is to be well now. I, Stella, am to be rewarding you with these jubilant credits! Go, spend them at the bar, drink!'),
('string/en/static_npc/tatooine/stella.stf', 17, 'npc_reward_3', 'Ah! It is here on this disc, the promise and threat of Lady Valarian in Mos Eisley: If Jabba is to be muscling in on the Third Sun, her gang will be landing on this esteemed dive and blowing it up to bits! I will be sending this to Jabba. A good permanent solution at last, yes yes. You are to be accepting this happy reward. Celebrate, drink!'),
('string/en/static_npc/tatooine/stella.stf', 18, 'player_1_1', 'I''d be happy to happy to help you.'),
('string/en/static_npc/tatooine/stella.stf', 19, 'player_1_2', 'Yes, I''ll get your deed back for you.'),
('string/en/static_npc/tatooine/stella.stf', 20, 'player_1_3', 'Sure, I''ll get the data for you.'),
('string/en/static_npc/tatooine/stella.stf', 21, 'player_2_1', 'No, I''m not available to help.'),
('string/en/static_npc/tatooine/stella.stf', 22, 'player_2_2', 'No, I don''t want to get mixed up with Jabba, sorry.'),
('string/en/static_npc/tatooine/stella.stf', 23, 'player_2_3', 'No, I''m not able to help at this time.'),
('string/en/static_npc/tatooine/stella.stf', 24, 'player_3_1', 'Why are you called "Stella"?'),
('string/en/static_npc/tatooine/stella.stf', 25, 'player_3_2', 'Why don''t you call the police?'),
('string/en/static_npc/tatooine/stella.stf', 26, 'player_3_3', 'How did you arrange this meeting?'),
('string/en/static_npc/tatooine/stella.stf', 27, 'player_reset_1', 'I''m not able to find these ''patrons'' of yours at this time. Could I try to looking for them a little later?'),
('string/en/static_npc/tatooine/stella.stf', 28, 'player_sorry_1', 'I''m still tracking them down. When they''ve paid, I''ll be sure to bring it back to you.'),
('string/en/static_npc/tatooine/stella.stf', 29, 'npc_backtowork_1', 'Good, good. I, Stella, will be here serving drinks at this egregiously fun dive when you return.'),
('string/en/static_npc/tatooine/stella.stf', 30, 'npc_reset_1', 'Yes, this is understood by me.  You let me know when you can offer your help, yes?'),
('string/en/static_npc/tatooine/stella.stf', 31, 'cantwork', 'Welcome, yes, yes. Always the Third Sun cantina, raucous haven of pleasantries, is giving refuge from a busy busy life. You are to be talking to me when not so busy, yes?'),
('string/en/static_npc/tatooine/stella.stf', 32, 'dontknowyou_1', 'What do you want?  I don''t want any trouble with you, so just keep moving, okay?'),
('string/en/static_npc/tatooine/stella.stf', 33, 'npc_work_1', 'Ah, yes yes. I, Stella, am welcoming you to the Third Sun, this ideally bumptious joint. Have those finks paid up, yes?'),
('string/en/static_npc/tatooine/stella.stf', 34, 'npc_work_2', 'Ah, yes yes.  I, Stella, am welcoming you to the Third Sun, boisterous hangout I am not to be owning long. You have found Ulek, maybe, yes?'),
('string/en/static_npc/tatooine/stella.stf', 35, 'npc_work_3', 'Ah, yes yes. I, Stella, am welcoming you to the Third Sun, the ambiably pleasant hellhole I now fully own. You have met with the Bothan already yet, yes?'),
('string/en/static_npc/tatooine/stella.stf', 36, 'npc_breech_1', 'Hey! Who are you and what do you want with us!?'),
('string/en/static_npc/tatooine/stella.stf', 37, 'npc_breech_2', 'This little deed will get me into Jabba''s gang, and you won''t stop me!'),
('string/en/static_npc/tatooine/stella.stf', 38, 'npc_breech_3', 'I have been waiting for ee-you. Let us get this done before we are seen.'),
('string/en/static_npc/tatooine/stella.stf', 39, 'notit_1', 'Oh, no, no, this is not how much they are owing me. I, Stella, will only take what is being owed to me.'),
('string/en/static_npc/tatooine/stella.stf', 40, 'notit_2', 'Oh, no, no, this is not the deed for the Third Sun. I, Stella, am being in desperation for that deed.'),
('string/en/static_npc/tatooine/stella.stf', 41, 'notit_3', 'Oh, no, no, this is not data that will help me. I, Stella, am needing data only the Bothan has.'),
('string/en/static_npc/tatooine/stella.stf', 42, 'dontknowyou_2', 'Unless you''re Jabba himself, I don''t want anything to do with you. Get away from me.'),
('string/en/static_npc/tatooine/stella.stf', 43, 'dontknowyou_3', 'Ee-you are not the contact I am waiting for. I am busy waiting for someone else.'),
('string/en/static_npc/tatooine/stella.stf', 44, 'player_reset_2', 'I can''t find Ulek at this time. Could I look for him later?'),
('string/en/static_npc/tatooine/stella.stf', 45, 'player_reset_3', 'I''m not able to meet with the Bothan. Can you let him know I won''t be able to show up?'),
('string/en/static_npc/tatooine/stella.stf', 46, 'player_sorry_2', 'I am still planning a way to get the deed back from him. I''ll let you know when I do.'),
('string/en/static_npc/tatooine/stella.stf', 47, 'player_sorry_3', 'No, I wasn''t able to meet him yet. I''ll make sure to show up soon, though.'),
('string/en/static_npc/tatooine/stella.stf', 48, 'npc_backtowork_2', 'Good, good. I, Stella, will be serving drinks at maybe Jabba''s Third Sun when you return.'),
('string/en/static_npc/tatooine/stella.stf', 49, 'npc_backtowork_3', 'Good, good. I, Stella, will be serving drinks as I am waiting for the Bothan''s data.  Do not make him be waiting too long, yes?'),
('string/en/static_npc/tatooine/stella.stf', 51, 'npc_reset_3', 'Yes, this is understood by me.  We are to be arranging a time to meet him later, maybe, yes?'),
('string/en/static_npc/tatooine/stella.stf', 55, 'npc_reset_2', 'Yes, this is understood by me. You are to be letting me know later if you can be helping me keep this whoop-it-up hole-in-the-wall as my own, yes?'),
('string/en/static_npc/tatooine/stella.stf', 56, 'npc_smuggle_1', 'Huh? We forgot to pay Stella? Hey, I''m sorry. Here you go. Please apologize to her for us, okay? Thanks.'),
('string/en/static_npc/tatooine/stella.stf', 58, 'npc_smuggle_3', 'Eee-yes, I have the data ee-you want. Tell ee-your patron I expect to be well paid at our next meeting. Well paid!'),
('string/en/static_npc/tatooine/stella.stf', 59, 'next', 'Ah yes yes! I, Stella, am to be welcoming you back to this eternal partying refuge from sunny Mos Taike. But just now there is to be no more work for you to be doing. So drink, drink!'),
('string/en/static_npc/tatooine/stella.stf', 60, 'gotowork', 'Don''t you have something else to do?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 1, 'npc_1_1', 'Are you offering to help? Well sure, I can use you. A friend of mine''s been performing some research on Tusken Raider migrations for me. A womp rat bit him last night, and word from Bestine is that those vermin might be carrying a new strain of Gray Rot. Could you take this vaccine out to him and make sure he''s doing all right?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 2, 'npc_1_2', 'Remember Digger? I just received word that the Sand People captured him. We need to get him out of their clutches immediately. I can''t go myself because I need to get the settlement ready for a possible Tusken raid. Can you help Digger?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 3, 'npc_1_3', 'It''s a good thing I was getting this place ready for a raid. Turns out the Tuskens have sent raiding parties against many of the local moisture farmers. Think you can lend a hand in protecting these citizens?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 5, 'npc_2_1', 'Great, thanks. Make sure he takes this vaccine as soon as possible. Gray Rot is only treatable within the first few days of infection.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 6, 'npc_2_2', 'You gotta hurry. I don''t know how many Tusken took Digger so I''d bring some friends along if I were you. These beasts are mindless killers so start blasting the minute you see them.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 7, 'npc_2_3', 'I''d advise you take some friends along again, friend. Those Tuskens can be tough when faced in larger numbers. '),
('string/en/static_npc/tatooine/tekil_barje.stf', 8, 'npc_3_1', 'Why''d you offer to help then? Excuse me, I''m a busy man.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 9, 'npc_3_2', 'Thanks for nothing.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 10, 'npc_3_3', 'Do you know anyone else that would be willing to help? I don''t have time for beings that stand by and watch innocents get hurt.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 12, 'npc_4_1', 'Some kind of plague. Makes your skin turn gray and rot off. Nice, huh?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 13, 'npc_4_2', 'I''ll spare you the gruesome details of what Sand People do to captives. Those creatures delight in torture. It''s a sort of initiation ritual for their young warriors.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 14, 'npc_4_3', 'Must be in retaliation for you rescuing Digger and killing off a couple of their warriors.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 16, 'npc_reward_2', 'You''ve done well, friend. Please accept this payment for your valuable services. '),
('string/en/static_npc/tatooine/tekil_barje.stf', 17, 'npc_reward_3', 'Job well done, friend. You''re welcome in Wayfar anytime. I came across this robe in my travels but I''m not using it so go ahead, take it as a token of my appreciation.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 18, 'player_1_1', 'Sure!'),
('string/en/static_npc/tatooine/tekil_barje.stf', 19, 'player_1_2', 'I''ll go help him!'),
('string/en/static_npc/tatooine/tekil_barje.stf', 20, 'player_1_3', 'I''ll definitely help!'),
('string/en/static_npc/tatooine/tekil_barje.stf', 21, 'player_2_1', 'Sorry, no.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 22, 'player_2_2', 'Sorry, I dont really care.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 23, 'player_2_3', 'No, I really don''t care about them.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 24, 'player_3_1', 'What''s Gray Rot?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 25, 'player_3_2', 'What will the Sand People do to Digger?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 26, 'player_3_3', 'Why are the Sand People attacking the moisture farmers?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 27, 'player_reset_1', 'I can''t anymore.  You''ll need to find someone else.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 28, 'player_sorry_1', 'Not yet.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 29, 'npc_backtowork_1', 'This is urgent!  Please hurry!'),
('string/en/static_npc/tatooine/tekil_barje.stf', 30, 'npc_reset_1', 'Why''d you offer to help then? Excuse me, I''m a busy man.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 31, 'cantwork', 'Come back when you''re not so preoccupied.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 32, 'dontknowyou_1', 'If you can, get to my friend, Tekil.  He can help me.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 33, 'npc_work_1', 'Did you give him the vial?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 34, 'npc_work_2', 'Have you helped Digger?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 35, 'npc_work_3', 'So, have the farmers been saved?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 36, 'npc_breech_1', 'Ooooh... the pain...'),
('string/en/static_npc/tatooine/tekil_barje.stf', 37, 'npc_breech_2', 'Help me out!  They''re going to get me!'),
('string/en/static_npc/tatooine/tekil_barje.stf', 39, 'notit_1', 'What''s this going to do for my pain?'),
('string/en/static_npc/tatooine/tekil_barje.stf', 42, 'npc_backtowork_2', 'This is urgent!  Please hurry!'),
('string/en/static_npc/tatooine/tekil_barje.stf', 43, 'npc_backtowork_3', 'This is urgent!  Please hurry!'),
('string/en/static_npc/tatooine/tekil_barje.stf', 44, 'npc_reset_2', 'Thanks for nothing.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 45, 'npc_reset_3', 'Do you know anyone else that would be willing to help? I don''t have time for beings that stand by and watch innocents get hurt.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 46, 'player_reset_2', 'I can''t anymore.  You''ll need to find someone else.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 47, 'player_reset_3', 'I can''t anymore.  You''ll need to find someone else.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 48, 'player_sorry_2', 'Not yet.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 49, 'player_sorry_3', 'Not yet.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 51, 'npc_takeme_2', 'Thanks, friend! I''m beginning to grow quite fond of you.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 106, 'npc_smuggle_1', 'Thanks, friend! That bite is starting to itch something awful. This should take care of that. I hope.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 109, 'npc_reward_1', 'Good work.  Digger already says that the itching''s subsiding.  Take a look at this Gaderiffi staff - it''s the Tusken Raiders weapon of choice for close encounters. Maybe you can learn how to better defend against it from examining this one.'),
('string/en/static_npc/tatooine/tekil_barje.stf', 110, 'next', 'Still hanging around Wayfar? I wish I had something to keep the place interesting, but it''s quiet right now. Thanks again for helping me before.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 1, 'npc_1_1', 'Eager to earn your keep, eh? That''s an admirable quality. As it turns out, I do have something that needs attending. A friend of mine, who is visiting from Treylon II, decided to go sightseeing this morning and has not yet returned. Could you make sure he''s safe and that he finds his way back here? '),
('string/en/static_npc/tatooine/tour_aryon.stf', 2, 'npc_1_2', 'You did perform admirably on that last assignment. I think I can trust you with another. The renowned artist Sidoras Bey has just arrived from Brentaal. But I''m afraid he''s rather absentminded. He landed at the wrong starport and insisted on finding his own way here. I would appreciate it if you could collect him and escort him back here. '),
('string/en/static_npc/tatooine/tour_aryon.stf', 3, 'npc_1_3', 'I find you''re a reliable and eager worker. I do have something else. An Internal Security Bureau officer, Nilsa Skaller, is investigating some prominent Bestine citizens outside the city. I''d like you to rendezvous with Lieutenant Skaller and make certain she returns to Bestine safely. I have reasons to suspect her life might be in danger.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 5, 'npc_2_1', 'Excellent. My friend''s name is Jen Torel. I do hope he hasn''t run afoul of any Tuskens. Do hurry.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 6, 'npc_2_2', 'How helpful of you. Remember, Maestro Bey is a little sensitive about his fading memory. He''s a proud man. Do your best to humor him along the way. After all, his coming to Tatooine to be my guest is a great honor. '),
('string/en/static_npc/tatooine/tour_aryon.stf', 7, 'npc_2_3', 'I know there is an element of risk involved in this mission, but I was hoping the hint of danger would not scare you off. I''m disappointed I was wrong.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 8, 'npc_3_1', 'Perhaps you''re not quite as eager to earn your keep as I had thought. Pity. I can be quite generous when the mood strikes me.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 9, 'npc_3_2', 'He really is not as bad as all that. But if you don''t wish to perform this service for me, so be it. Have a good day.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 10, 'npc_3_3', 'My instincts told me you would not shirk away from danger. I''m glad they proved correct. Make sure Lieutenant Skaller knows I have sent you. Otherwise she might mistake you for an assassin and you could end up dead.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 12, 'npc_4_1', 'Oh, Jen has always had an explorer''s spirit. Unfortunately, this has gotten him into trouble in the past. Life on Tatooine is not at all like life on Treylon II.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 13, 'npc_4_2', 'Maestro Bey is best known for his amazing sculpture of our beloved Emperor that sits outside the Imperial palace on Coruscant.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 14, 'npc_4_3', 'The less you know, the better. Suffice to say that some Imperial agents, entrusted with the very security of this planet, should make sure their own records are clean before they begin investigating others. '),
('string/en/static_npc/tatooine/tour_aryon.stf', 15, 'npc_reward_1', 'Wonderful. Glad to see Jen is in one piece. Allow me to express my gratitude by presenting you with this small gift. Thank you for your service. '),
('string/en/static_npc/tatooine/tour_aryon.stf', 16, 'npc_reward_2', 'I appreciate your help, citizen. Maestro Bey is dear to me and this service shall not be forgotten.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 17, 'npc_reward_3', 'Again you''ve proven yourself a most reliable agent. If you keep this up, I may come to depend on you.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 18, 'player_1_1', 'Sure, I can help!'),
('string/en/static_npc/tatooine/tour_aryon.stf', 19, 'player_1_2', 'Sure, I''ll help the old guy.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 20, 'player_1_3', 'Yes, I''ll get in contact with her and make sure she arrives safely.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 21, 'player_2_1', 'I''m sorry, but I can''t help.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 22, 'player_2_2', 'No, I''m sorry, but I cannot help with that.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 23, 'player_2_3', 'No, I''m sorry but I cannot help.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 24, 'player_3_1', 'Why did he go sight-seeing?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 25, 'player_3_2', 'What is Sidoras Bey famous for?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 26, 'player_3_3', 'Who is Lieutenant Skaller investigating?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 27, 'player_reset_1', 'I can''t seem to find him anywhere.  I''ve given up my search.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 28, 'player_sorry_1', 'No, no bad news.  I''m still on my way to find him, though.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 29, 'npc_backtowork_1', 'Well, you mustn''t dally.  Jen is not accustomed to the wilderness of Tatooine.  I''m not sure he would know what to be wary of.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 30, 'npc_reset_1', 'Ah, it''s a shame you weren''t able to uphold your end of the bargain.  I might forget this slight if you reconsider.  Until then, I don''t have any more time for you.  Begone.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 31, 'cantwork', 'I hope you find Tatooine an agreeable place, citizen. There is beauty here that the casual observer might miss. Take your time and appreciate it.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 32, 'dontknowyou_1', 'I''m sorry, but I don''t believe we''ve met before.  And if we can, let''s keep it that way, alright?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 33, 'npc_work_1', 'Please don''t tell me you have bad news about Jen.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 34, 'npc_work_2', 'I don''t see Maestro Bey with you.  Where is he?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 35, 'npc_work_3', 'Where is Nilsa?  Is she safe?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 36, 'npc_breech_1', 'Well, well, good day to you.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 37, 'npc_breech_2', 'Hmmm... where am I now?  I don''t remember Bestine looking like this when I was last here.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 38, 'npc_breech_3', 'Good day, citizen.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 42, 'npc_backtowork_2', 'Very good.  Please do raise the intensity of your search.  It would be a shame if he were to wander into the desert, being an old man and all.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 43, 'npc_backtowork_3', 'I am placing my trust in you.  So far you have shown it was well placed, so please continue making me feel that way.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 44, 'npc_reset_2', 'I hope this isn''t an unfortunate end to such a marvelous mind.  If you find that your will returns, I may still be looking for him.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 45, 'npc_reset_3', 'Well, I understand.  If I cannot find anyone else to do so, I will still need your help.  I shall look for someone else for now.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 46, 'player_reset_2', 'It seems someone else might have picked him up.  I can''t find him, and I''m tired of looking.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 47, 'player_reset_3', 'I''m not cut out to escort such a high ranking Imperial.  You should send someone else instead.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 48, 'player_sorry_2', 'I haven''t found him yet.  As soon as I do, though, he''ll make it here safe and sound.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 49, 'player_sorry_3', 'I have yet to find her.  Rest assured, she will make it back here safely.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 50, 'npc_takeme_1', 'Did Tour send you to find me? Will she always try to look after me? I assure you I was quite alright. Well, I suppose she''s expecting us. Lead on, noble rescuer.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 51, 'npc_takeme_2', 'I certainly hope you don''t think I''m lost, because I''m not. I know precisely where I am. I''m not sure why I ever agreed to come to this desolate place. I don''t even like sand. Well, are you just going to sit around all day? Take me to Governor Aryon. That''s what I came halfway across the galaxy for, isn''t it?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 52, 'npc_takeme_3', 'You must be my official escort. Governor Aryon''s efficiency impresses me. Take me to her. We have much to discuss.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 53, 'dontknowyou_2', 'What, you see an old man and assume he needs help?  Move along, you little whippersnapper, I don''t need anything, mind you.  Shoo!'),
('string/en/static_npc/tatooine/tour_aryon.stf', 54, 'dontknowyou_3', 'I mistook you for someone else.  I am awaiting a friend.  If you don''t mind, I''d prefer to do it alone, thank you.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 55, 'dontknowyou_4', 'I''m sorry.  If Tour didn''t send you, I''m not sure if I can trust you.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 56, 'dontknowyou_5', 'Oh, I am sorry.  I believed you were someone else.  Please nevermind me.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 57, 'dontknowyou_6', 'Ah, I see.  I believed you were a rescue team.  I apologize.  Have a good day, citizen.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 61, 'npc_1_4', 'I''ve long been trying to guide Jabba the Hutt away from violence to solve his problems. Any conflicts on Tatooine attract undue attention from Coruscant. Recently, I sent my aide, Belutoo Gezmaani, to Jabba''s palace for yet another negotiation. The discussion went -- poorly. Jabba transported my aide as far as the Jundland Wastes, then left him there to fend for himself. Be so kind as to provide him a safe escort back here.   '),
('string/en/static_npc/tatooine/tour_aryon.stf', 62, 'npc_1_5', 'This assignment is a delicate one and might embroil you in the politics of Bestine - something you may wish to avoid. It involves the Prefect, a dangerous and vengeful man. Do you wish to help me anyway?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 63, 'npc_1_6', 'This next assignment will be your most important yet. A very powerful Imperial dignitary may be in great danger. This individual answers directly to the Emperor himself. Do you wish to become involved?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 64, 'npc_2_4', 'Wonderful. I was beginning to fear that I would need to involve Imperial authorities in this matter. That would only damage my relationship with both Jabba and Prefect Talmont. Please hurry and find my aide before he falls victim to one of Tatooine''s vicious predators.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 65, 'npc_2_5', 'I knew I could rely on you. Jormun Shade, an Internal Security officer, just lost his Zabrak bodyguard to an assassin. Fortunately, Shade was undetected by the killer but is now understandably concerned about returning here without an armed escort. Make sure he gets here alive. Imperial Intelligence must hear what he has discovered.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 66, 'npc_2_6', 'Inquisitor Josard was performing an investigation at the Pit of Carkoon when something attacked him and his escort. We don''t know the details yet, but somehow Josard managed to escape. He sent a distress signal from these coordinates. You must race there and offer what aid you can.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 67, 'npc_3_4', 'Well, I certainly understand your reticence. The Jundland Wastes are not to be traveled lightly. If you change your mind, let me know.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 68, 'npc_3_5', 'I respect your decision to remain neutral in this matter. I will seek another citizen willing to assist me in this matter. Good day.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 69, 'npc_3_6', 'I do not hold your refusal against you. This mission calls for no small amount of daring and skill. I shall find others to assist me. Thank you for all your help up to this point.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 70, 'npc_4_4', 'I sent him to ask Jabba to reconsider an attack on Lady Valarian. Unfortunately, Gezmaani suggested that Jabba''s forces could not defeat Lady Valarian, without my help.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 71, 'npc_4_5', 'I won''t go into specific reasons, but I will say that you should be suspicious of anything that man tells you. You should be even more suspicious of assignments from him. Imperial Intelligence''s Internal Security division is currently investigating Talmont. That should tell you everything you need to know.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 72, 'npc_4_6', 'I speak of none other than Inquisitor Kuno Josard, an important figure in the Inquisitorius. You must be especially careful while in his presence. Say as little as possible and clear your mind. It is said he can read your very thoughts. '),
('string/en/static_npc/tatooine/tour_aryon.stf', 73, 'npc_backtowork_4', 'When you are ready, depart with post haste.  He may not be able to fend for himself for too much longer.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 74, 'npc_backtowork_5', 'That information Jormun has is very important.  You must hurry!'),
('string/en/static_npc/tatooine/tour_aryon.stf', 75, 'npc_backtowork_6', 'Make haste!  The Emperor will not be happy if he were to find out Josard were to have met his demise due to procrastination.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 76, 'npc_breech_4', 'Were you sent by Tour?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 77, 'npc_breech_5', 'Stop! You''re not one of -- his -- agents, are you?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 78, 'npc_breech_6', 'Did the Empire send a rescue team?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 79, 'npc_reset_4', 'Well, I certainly understand your reticence. The Jundland Wastes are not to be traveled lightly. If you change your mind, let me know.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 80, 'npc_reset_5', 'I respect your decision to remain neutral in this matter. I will seek another citizen willing to assist me in this matter. Good day.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 81, 'npc_reset_6', 'I do not hold your refusal against you. This mission calls for no small amount of daring and skill. I shall find others to assist me. Thank you for all your help up to this point.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 82, 'npc_reward_4', 'I am most grateful, citizen. And judging by his posture so is Gezmaani. Please feel free to come to me again for more assignments. I find I enjoy your company.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 83, 'npc_reward_5', 'Thank you, citizen. I''ll take it from here. Please see me later for an additional assignment. You may go.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 84, 'npc_reward_6', 'The Empire is grateful for your timely assistance, citizen. I shall make a note of this in my report to the Emperor. You are dismissed.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 85, 'npc_takeme_4', 'You''ve saved me. That slug Jabba left me out here to die. I don''t know why Governor Aryon insists on trying to make peace with that criminal. It''s going to get me killed! '),
('string/en/static_npc/tatooine/tour_aryon.stf', 86, 'npc_takeme_5', 'How do I know Governor Aryon sent you? I suppose you don''t really look like an assassin. At least -- well, lead on, I''ll follow close behind. Be aware that I am armed.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 87, 'npc_takeme_6', 'Do not concern yourself, citizen, all is well. The monster did manage to kill my entire escort before I was able to drive it away. Interesting creatures those krayt dragons. They would make a most formidable guard if tamed. I shall have to consider that. '),
('string/en/static_npc/tatooine/tour_aryon.stf', 88, 'npc_work_4', 'Have you escorted Gezmaani back to town yet?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 89, 'npc_work_5', 'Were you able to make it to Jormun in time?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 90, 'npc_work_6', 'Was Josard dead by the time you made it there?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 91, 'player_1_4', 'I shall do so immediately!'),
('string/en/static_npc/tatooine/tour_aryon.stf', 92, 'player_1_5', 'This sounds important!  Yes, I''ll definitely do this.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 93, 'player_1_6', 'I would do anything for the Emperor. Yes, I will do it.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 94, 'player_2_4', 'No, I am unavailable for such a long travel right now.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 95, 'player_2_5', 'No, I do not want to become involved in some politcal game.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 96, 'player_2_6', 'No, I do not want to be held responsible if anything were to happen to him.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 97, 'player_3_4', 'What did Gezmaani say to Jabba?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 98, 'player_3_5', 'Why is the Prefect so dangerous?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 99, 'player_3_6', 'Who is this dignitary?'),
('string/en/static_npc/tatooine/tour_aryon.stf', 100, 'player_reset_4', 'I can''t do it.  He is way too far away!'),
('string/en/static_npc/tatooine/tour_aryon.stf', 101, 'player_reset_5', 'I''ve changed my mind.  I don''t want to become involved in all of this.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 102, 'player_reset_6', 'I''ve reconsidered, and do not want to be held responsible for this.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 103, 'player_sorry_4', 'Not yet.  I am still preparing for my journey.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 104, 'player_sorry_5', 'Not yet, but I shall do so immediately.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 105, 'player_sorry_6', 'No, I am still getting directions to the Great Pit.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 106, 'next', 'I appreciate your help in those earlier matters, but I''m happy to say we have matters under control here at the moment.'),
('string/en/static_npc/tatooine/tour_aryon.stf', 107, 'gotowork', 'I think maybe you have something else to do right now...'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 1, 'npc_1_1', 'You look like you might know how to handle yourself. Maybe you really can help me. Some crazy Dim-U monks have hired a bounty hunter to capture me. They say I''m to be executed for murdering a sacred beast. Can you help me? '),
('string/en/static_npc/tatooine/vardias_tyne.stf', 2, 'npc_1_2', 'I have a peace offering for the Dim-U monks. I hope it will get them to leave me alone. Interested in helping out again?'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 5, 'npc_2_1', 'Good. I thought I was dead for sure. It''s getting so you can''t even protect your own property any more. The bounty hunter''s name is Rhalia Jinsari. Stop her from bringing me in to those insane zealots, and I''ll gladly reward you.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 6, 'npc_2_2', 'You have a good heart. It''s not everybody who will stop to help someone in trouble. '),
('string/en/static_npc/tatooine/vardias_tyne.stf', 8, 'npc_3_1', 'I understand. I wouldn''t want to go up against a bounty hunter either. You''d better clear out of here before you get hurt. '),
('string/en/static_npc/tatooine/vardias_tyne.stf', 9, 'npc_3_2', 'I guess a hotshot like you has better things to do. Thanks anyway.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 12, 'npc_4_1', 'All I did was shoot a rogue bantha that was destroying my vaporators. Those blasted monks worship banthas. I didn''t do anything different from anyone else in my position.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 13, 'npc_4_2', 'I hired a talented artist to sculpt a bantha out of a piece of kiliad marble. I need you to deliver it to Brother Chonar and ask him if they''re willing to forgive and forget. '),
('string/en/static_npc/tatooine/vardias_tyne.stf', 15, 'npc_reward_1', 'You stopped her? You''ve saved my life! Now I just need to figure out how to calm those monks down -- before they hire someone else.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 16, 'npc_reward_2', 'You''ve come through for me again, and I won''t forget it. I used this to harvest resources from the rivers back on Naboo. Won''t be doing much of that around here though so please accept this as your reward, maybe you''ll find some use for it.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 18, 'player_1_1', 'Sure, I''ll stop the bounty hunter for you.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 19, 'player_1_2', 'Sure!'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 21, 'player_2_1', 'Sorry, but I don''t involve myself with this type of thing.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/tatooine/vardias_tyne.stf', 22, 'player_2_2', 'No thanks.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 24, 'player_3_1', 'Did you really kill a sacred beast?'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 25, 'player_3_2', 'What is this peace offering?'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 27, 'player_reset_1', 'I can''t handle someone as skilled as the Bounty Hunter.  I''ll have to pass on this.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 28, 'player_sorry_1', 'Not yet, but you needn''t worry.  I''ll put a stop to her.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 29, 'npc_backtowork_1', 'Thank you for your help.  Let me know when I''m safe.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 30, 'npc_reset_1', 'I understand. I wouldn''t want to go up against a bounty hunter either. You''d better clear out of here before you get hurt. '),
('string/en/static_npc/tatooine/vardias_tyne.stf', 31, 'cantwork', 'I wish you weren''t so busy with other things. I really need some help right now.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 33, 'npc_work_1', 'Have you been able to stop her yet?'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 34, 'npc_work_2', 'Did he accept my apology?'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 36, 'npc_breech_1', 'Come between me and my mark and you will share their fate!'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 37, 'npc_breech_2', 'I hope this will be a worthwhile communication between us.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 40, 'notit_2', 'This will not allow us to forgive previous transgressions.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 42, 'npc_backtowork_2', 'Okay, just let me know what his response is.  I hope this will appease those monks.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 44, 'npc_reset_2', 'I guess a hotshot like you has better things to do. Thanks anyway.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 46, 'player_reset_2', 'This is too valuable.  I''m afraid it will be stolen.  You''ll have to do this yourself.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 48, 'player_sorry_2', 'I haven''t made contact with him yet.  I''ll let you know when I do.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 53, 'dontknowyou_2', 'You have nothing important to say.  I must bid you a good day.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 107, 'npc_smuggle_2', 'This gift conveys respect for the majesty of these great creatures. You may tell your employer that the Dim-U will pursue him no further.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 108, 'next', 'You know, now that those Dim-U monks aren''t hunting me, my life is getting downright dull. I almost miss the thrill. Almost.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 109, 'player_reset', 'I''ll have to pass on this job.'),
('string/en/static_npc/tatooine/vardias_tyne.stf', 110, 'player_sorry', 'I''ll get back to work.'),
('string/en/static_npc/tatooine/wald.stf', 1, 'npc_1_1', 'Ehh, my repair droid went crazy and dismantled itself. I need someone to take its brain to a droid engineer for analysis. You, maybe?'),
('string/en/static_npc/tatooine/wald.stf', 2, 'npc_1_2', 'See this part? You can take it to a poor fellow who really needs to repair his vehicle, eh?'),
('string/en/static_npc/tatooine/wald.stf', 3, 'npc_1_3', 'A friend bought this hunk of junk off some Jawas just in town for a day. Soon as their sandcrawler vanished over the horizon, the thing broke. I fixed it, so you can take it back to my friend, eh?'),
('string/en/static_npc/tatooine/wald.stf', 5, 'npc_2_1', 'Good, good! You look for a Mon Calamari fish-woman, name of Sawoos, okay? Her, she''ll want to see this brain''s data.'),
('string/en/static_npc/tatooine/wald.stf', 6, 'npc_2_2', 'Good, good. His name is Minnro Lax, he says. You just drop this off, and don''t worry about what he might say or be wearing, eh?'),
('string/en/static_npc/tatooine/wald.stf', 7, 'npc_2_3', 'Good! You look for a Bothan, her name is Trl''apra. She''s maybe not feeling so good now, eh? You ignore whatever she might say. I know you had no problem with that last little job for me. This is like that, you know?'),
('string/en/static_npc/tatooine/wald.stf', 8, 'npc_3_1', 'Heyyy, that''s okay. You look around, maybe buy Watto''s junk, eh?'),
('string/en/static_npc/tatooine/wald.stf', 9, 'npc_3_2', 'That''s okay. You look around, maybe buy Watto''s junk, eh?'),
('string/en/static_npc/tatooine/wald.stf', 10, 'npc_3_3', 'Heyyy, that''s okay. You look around, maybe buy Watto''s junk, eh?'),
('string/en/static_npc/tatooine/wald.stf', 12, 'npc_4_1', 'This shop, it still belongs to Watto. But he retired a while back to some sunny beach on some nicer world than this. Me, I run the shop for him. Now, about that repair droid, you can help, eh?'),
('string/en/static_npc/tatooine/wald.stf', 13, 'npc_4_2', 'I dunno, he just called. Voice only, no picture. You want this job?'),
('string/en/static_npc/tatooine/wald.stf', 14, 'npc_4_3', 'It''s a sentimental thing, maybe. You want this job or not?'),
('string/en/static_npc/tatooine/wald.stf', 15, 'npc_reward_1', '"Battle plans"? She said that? Ehh, just a running joke between us. No, can''t say why stormtroopers would want a brain. Heyy, thanks! You take that droid''s old head as a reward, eh?'),
('string/en/static_npc/tatooine/wald.stf', 16, 'npc_reward_2', 'Heyyy? A Rebel, eh? Who knew? Those guards must be after him, the scum. I mean, "the Rebel scum." Let''s see, payment -- you want an old mouse droid, maybe?'),
('string/en/static_npc/tatooine/wald.stf', 17, 'npc_reward_3', 'Stimpack? Heyyy, now that I think, yeah, there was a stimpack inside that junk. Jawas must have left it. I like you, my friend -- you don''t ask the wrong questions. Here, want a power core for payment?'),
('string/en/static_npc/tatooine/wald.stf', 18, 'player_1_1', 'Yeah, me.'),
('string/en/static_npc/tatooine/wald.stf', 19, 'player_1_2', 'I am very capable of doing so.  You can trust me, Wald!'),
('string/en/static_npc/tatooine/wald.stf', 20, 'player_1_3', 'Sure, I''ll get it to him.'),
('string/en/static_npc/tatooine/wald.stf', 21, 'player_2_1', 'No thanks.'),
('string/en/static_npc/tatooine/wald.stf', 22, 'player_2_2', 'No.   I don''t want to be know as an Assistant Junk Dealer.'),
('string/en/static_npc/tatooine/wald.stf', 23, 'player_2_3', 'No, I''m tired of doing these for you.'),
('string/en/static_npc/tatooine/wald.stf', 24, 'player_3_1', 'Why do you run this junk shop? Where''s Watto?'),
('string/en/static_npc/tatooine/wald.stf', 25, 'player_3_2', 'Who is the "poor fellow"?'),
('string/en/static_npc/tatooine/wald.stf', 26, 'player_3_3', 'A hunk of junk? Why does your friend want it?'),
('string/en/static_npc/tatooine/wald.stf', 27, 'player_reset_1', 'I''m sorry, but I can''t do this any longer.'),
('string/en/static_npc/tatooine/wald.stf', 28, 'player_sorry_1', 'I haven''t given it to her yet.  I''m about to do so right now,'),
('string/en/static_npc/tatooine/wald.stf', 29, 'npc_backtowork_1', 'Good.  She''s waiting to repair it.'),
('string/en/static_npc/tatooine/wald.stf', 30, 'npc_reset_1', 'Heyyy, that''s okay. You look around, maybe buy Watto''s junk, eh?'),
('string/en/static_npc/tatooine/wald.stf', 31, 'cantwork', 'Heyyy, welcome to Watto''s Junk Shop! You look busy, eh? You can look around if you got the time.'),
('string/en/static_npc/tatooine/wald.stf', 32, 'dontknowyou_1', 'Oh, I''m sorry.  I thought you were someone else.'),
('string/en/static_npc/tatooine/wald.stf', 33, 'npc_work_1', 'It has been given to the Mon Calamari, eh?'),
('string/en/static_npc/tatooine/wald.stf', 34, 'npc_work_2', 'So, did he get the part in time, hm?'),
('string/en/static_npc/tatooine/wald.stf', 35, 'npc_work_3', 'Is she feeling better now?'),
('string/en/static_npc/tatooine/wald.stf', 36, 'npc_breech_1', 'You wouldn''t happen to be the courier, would you?'),
('string/en/static_npc/tatooine/wald.stf', 37, 'npc_breech_2', 'Are you the one with the droid?'),
('string/en/static_npc/tatooine/wald.stf', 38, 'npc_breech_3', 'Are you Wald''s friend?'),
('string/en/static_npc/tatooine/wald.stf', 39, 'notit_1', 'Umm... the plans aren''t in this.  I was told to expect a droid brain, not this.'),
('string/en/static_npc/tatooine/wald.stf', 40, 'notit_2', 'No, this won''t work!  I need the mouse droid with the -er-... just get me the mouse droid, okay?'),
('string/en/static_npc/tatooine/wald.stf', 41, 'notit_3', 'This won''t help.  I need Wald''s -um- junk he''s sending.'),
('string/en/static_npc/tatooine/wald.stf', 42, 'npc_backtowork_2', 'He''s needing it soon.  Don''t make him wait or it might be too late -er- for him to have junk.'),
('string/en/static_npc/tatooine/wald.stf', 43, 'npc_backtowork_3', 'Yes, she''s impatient like that.  Let me know when you get it to her.'),
('string/en/static_npc/tatooine/wald.stf', 44, 'npc_reset_2', 'That''s okay. You look around, maybe buy Watto''s junk, eh?'),
('string/en/static_npc/tatooine/wald.stf', 45, 'npc_reset_3', 'Heyyy, that''s okay. You look around, maybe buy Watto''s junk, eh?'),
('string/en/static_npc/tatooine/wald.stf', 46, 'player_reset_2', 'I don''t trust you, Wald.  I''m no longer aiding you in your junk-giving.'),
('string/en/static_npc/tatooine/wald.stf', 47, 'player_reset_3', 'I''m changing my mind.  I''m not doing this anymore.'),
('string/en/static_npc/tatooine/wald.stf', 48, 'player_sorry_2', 'I don''t know.  I haven''t given it to him yet.'),
('string/en/static_npc/tatooine/wald.stf', 49, 'player_sorry_3', 'I didn''t know she wanted this junk that bad.  I guess I''ll speed this up.'),
('string/en/static_npc/tatooine/wald.stf', 53, 'dontknowyou_2', 'Oh, I thought you were a friend of Wald''s.  Sorry.'),
('string/en/static_npc/tatooine/wald.stf', 54, 'dontknowyou_3', 'You don''t know Wald?  He''s one of your friendly junk dealers.  Good guy at heart, I can tell you.'),
('string/en/static_npc/tatooine/wald.stf', 55, 'dontknowyou_4', 'Thank you, but I can make it to the hospital on my own.'),
('string/en/static_npc/tatooine/wald.stf', 58, 'notit_4', 'Ugh... no... this won''t help... I need healing... Wald has my special medicine.'),
('string/en/static_npc/tatooine/wald.stf', 61, 'npc_1_4', 'Okay, you understand by now -- I like to help folks who are maybe not on the Empire''s party invitation list, eh? One of them, she is wounded and needs a stimpack. You can maybe bring it to her?'),
('string/en/static_npc/tatooine/wald.stf', 64, 'npc_2_4', 'Good! Danna Lindro, that''s her name. You got to get to her fast, she is trying to carry a certain report to where it will do good, you know?'),
('string/en/static_npc/tatooine/wald.stf', 67, 'npc_3_4', 'Heyyy, that''s okay. You don''t mention this to anyone else though, eh?'),
('string/en/static_npc/tatooine/wald.stf', 70, 'npc_4_4', 'Ehh, she ran into some stormtroopers. Too bad, ''cause she has plans. Important plans, if you understand, eh? What do you say?'),
('string/en/static_npc/tatooine/wald.stf', 73, 'npc_backtowork_4', 'I know you''ll get it done.  Thank you, friend.'),
('string/en/static_npc/tatooine/wald.stf', 76, 'npc_breech_4', 'Oh... the pain....'),
('string/en/static_npc/tatooine/wald.stf', 79, 'npc_reset_4', 'Heyyy, that''s okay. You don''t mention this to anyone else though, eh?'),
('string/en/static_npc/tatooine/wald.stf', 82, 'npc_reward_4', 'Heyyy, you are my new favorite friend! You ever want discounted junk, I''ll sell it to you and Watto will never know. Here, take this R4 unit. It wobbles, and maybe it kind of blows up now and then, but it''s good!'),
('string/en/static_npc/tatooine/wald.stf', 88, 'npc_work_4', 'Is she feeling all right now?'),
('string/en/static_npc/tatooine/wald.stf', 91, 'player_1_4', 'Since you''re finally honest with me, I''ll be happy to help.'),
('string/en/static_npc/tatooine/wald.stf', 94, 'player_2_4', 'What?  You''re a Rebel?  No, I''m not having anything to do with you anymore.'),
('string/en/static_npc/tatooine/wald.stf', 97, 'player_3_4', 'How did she get wounded?'),
('string/en/static_npc/tatooine/wald.stf', 100, 'player_reset_4', 'I''ve changed my mind.  I don''t want any part of this anymore.'),
('string/en/static_npc/tatooine/wald.stf', 103, 'player_sorry_4', 'I haven''t been able to find her yet.  I''ll let you know when I do.'),
('string/en/static_npc/tatooine/wald.stf', 106, 'npc_smuggle_1', 'Good, you''re here. The battle plans are encoded in this brain? What do you mean, "what plans?" Oh -- nothing. Not important. Thank you.'),
('string/en/static_npc/tatooine/wald.stf', 107, 'npc_smuggle_2', 'At last! Those stormtroopers were about to find me. You''ve saved my afterburners, friend!'),
('string/en/static_npc/tatooine/wald.stf', 108, 'npc_smuggle_3', 'Lights -- too much -- uhh? For me? Oh! Stimpack! Ahh. I feel better. Thank you, I got hit with Imperial drugs and needed that antidote. But I lost the dossiers, sorry.'),
('string/en/static_npc/tatooine/wald.stf', 109, 'npc_smuggle_4', 'Oh! Wonderful! I thought my mission was over. But now I can get these battle plans to High Command. Thank you!'),
('string/en/static_npc/tatooine/wald.stf', 110, 'next', 'Heyyy, friend, you looking for junk? What, work? Sorry, no work for you here today!'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 1, 'npc_1_1', 'Rebel spies have stolen one of my reports. I want it returned before they get a chance to decrypt it. Will you go and find it for me?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 2, 'npc_1_2', 'One of our informants has become -- unreasonable. He claims he has some information of great importance to the Empire but asks an outrageous sum for it, sight unseen. Might you persuade him to relinquish it and let us decide an appropriate reward?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 3, 'npc_1_3', 'One of my --ahem, the Prefect''s clerks has made a serious error in judgment. I need someone to arrest her before she causes this office considerable embarrassment. Will you do it?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 5, 'npc_2_1', 'Excellent, I''m sure this will go a long way in earning the Prefect''s goodwill. Return the datadisc to me, and I''ll see what I can do about getting you that appointment.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 6, 'npc_2_2', 'Very good. The alien in question is a Rutian Twi''lek, one Nethlek''Vaa. Go and bring the datadisc here.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 7, 'npc_2_3', 'Excellent. Go and arrest Ananda Dwyce. You have my assurance that should you succeed in this, the Prefect will most assuredly make time to see you.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 8, 'npc_3_1', 'I''ll be sure to contact you as soon as Prefect Talmont has some free time on his calendar. Good day.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 9, 'npc_3_2', 'I had boldly assumed that you were serious about wanting to see Prefect Talmont. I shall remove your name from the waiting list.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 10, 'npc_3_3', 'The Prefect is far too busy to see the likes of you. You needn''t return. '),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 12, 'npc_4_1', 'I am sorry; the Prefect is unavailable. He has left standing orders that he will see only those who have proven their commitment to the Empire. This brings us back to the missing datadisc. Your choice?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 13, 'npc_4_2', 'You can see Prefect Talmont as soon as you''ve convinced him of your sincerity. Succeeding in this mission might help in that regard.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 14, 'npc_4_3', 'The clerk has decided to join the Rebels. If she were to succeed, it would be indescribably awkward for the Prefect, to say nothing of the security nightmare.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 15, 'npc_reward_1', 'Your service to the Empire is appreciated. Prefect Talmont remains unavailable at this time, but contact me for future assignments.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 16, 'npc_reward_2', 'You serve the Empire well, and Prefect Talmont will note this. However, he is otherwise occupied at present. Contact me for future assignments, and perhaps I''ll be able to get you that appointment.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 17, 'npc_reward_3', 'You have performed admirably. Prefect Talmont will see you now.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 18, 'player_1_1', 'I''ll stop those Rebels from ever stealing anything again!'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 19, 'player_1_2', 'I shall have this done immediately.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 20, 'player_1_3', 'I shall promptly capture this traitor.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 21, 'player_2_1', 'Sorry, but I''m not here to see you, so I have no interest in recovering your report for you.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 22, 'player_2_2', 'No, I don''t run simple errands.  Do it yourself.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 23, 'player_2_3', 'This sounds like a job for sector police, not me.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 24, 'player_3_1', 'When can I see Prefect Talmont?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 25, 'player_3_2', 'When can I see Prefect Talmont?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 26, 'player_3_3', 'What did the clerk do?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 27, 'player_reset_1', 'I can''t find these Rebels.  I''m certain they left the planet with your report.  I give up.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 28, 'player_sorry_1', 'No, those Rebels are sneakier than I was expecting.  I shall find this report soon, I swear!'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 29, 'npc_backtowork_1', 'Very well, then.  Report back if you have future updates.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 30, 'npc_reset_1', 'Oh well.  I''ll be sure to contact you as soon as Prefect Talmont has some free time on his calendar. Good day.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 31, 'cantwork', 'Hello. You are here to see Prefect Talmont? He is unavailable at this time. In any case, you seem rather too busy to see him.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 32, 'dontknowyou_1', 'Um...*ahem*... I meant to say, "Nice weather we''re having, isn''t it"?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 33, 'npc_work_1', 'Have you been able to recover the report yet?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 34, 'npc_work_2', 'What a prompt return.  I take it you haven''t left yet, hm?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 35, 'npc_work_3', 'I do not see Dwyce with you.  Why is that?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 36, 'npc_breech_1', 'Long live the Alliance!'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 37, 'npc_breech_2', 'I can''t believe that skinflint wouldn''t just pay for the goods. '),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 38, 'npc_breech_3', 'The Prefect sent one of his men to kill me, please help!'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 39, 'notit_1', 'No, this clearly is not the report that has gone missing.  It would be appreciated if you were to be a little more observant, thank you.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 40, 'notit_2', 'Whatever this is, it is not impressive.  Now, when you have the pertinent information, please let me know.  Good day.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 42, 'npc_backtowork_2', 'Very well, then.  I hope you have made better preparations this time.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 43, 'npc_backtowork_3', 'He may have time available to those who have shown their initiative.  So far, I''m not sure you''re one who has.  Perhaps if I see Dwyce in your custody, my opinion may change.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 44, 'npc_reset_2', 'I had boldly assumed that you were serious about wanting to see Prefect Talmont. I shall remove your name from the waiting list.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 45, 'npc_reset_3', 'The Prefect is far too busy to see the likes of you. You needn''t return. '),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 46, 'player_reset_2', 'I don''t have time for this, after all.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 47, 'player_reset_3', 'Look, I don''t have tine to run around doing this for you.  Do it yourself, and in the meantime let me see the Prefect.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 48, 'player_sorry_2', 'Yes I did, but I got lost.  I now know which way he is.  I''ll get to him right now.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 49, 'player_sorry_3', 'Because I haven''t caught her yet.  Am I ever going to be able to see the Prefect?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 53, 'dontknowyou_2', 'Wait.  Why am I talking to you?  You have nothing to do with this?'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 54, 'dontknowyou_3', 'Oh, you''re not?  Ah, good.  Well, then I guess I''m safe.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 109, 'npc_takeme_3', 'I should have known I''d never get away. I''ll go quietly.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 110, 'next', 'You''ve been very helpful. Perhaps you should go speak with Prefect Talmont.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 111, 'notyet', 'I''m sorry, I only deal with Imperials of proven quality.'),
('string/en/static_npc/tatooine/wilhalm_skrim.stf', 112, 'npc_failure', 'No no no, you were supposed to arrest her, not kill her!'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 1, 'npc_1_1', 'Actually, you might be able to help me catch the murderer. We have the murder weapon, but the fellow who owns it seems to have left town. Would you be interested in tracking him down?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 2, 'npc_1_2', 'I don''t suppose you might still be feeling civic-minded? I''m a bit short-handed right now and could really use your tracking skills again. What do you say?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 3, 'npc_1_3', 'Blix Lanister''s crew busted him out and left town. I have people out tracking Blix, but you seem to have a knack for finding him and his cohorts. Do you think you can find him again?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 5, 'npc_2_1', 'Glad to see you''re the public-minded sort. See if you can track down this lowlife, Blix Lanister, and bring him back here to face trial. Be careful, he may have friends with him.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 6, 'npc_2_2', 'I''m glad to hear it. See if you can''t find a Rodian named Gleezwuq and get the evidence back. He''s the only one of Blix''s gang who we don''t know the location of. '),
('string/en/static_npc/tatooine/windom_starkiller.stf', 7, 'npc_2_3', 'Lanister may not let you bring him back alive. Do what you have to do. '),
('string/en/static_npc/tatooine/windom_starkiller.stf', 8, 'npc_3_1', 'I understand. Dangerous work like this isn''t for everybody. Stay safe.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 9, 'npc_3_2', 'I wish you''d reconsider, but if that''s how you want it, I understand.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 10, 'npc_3_3', 'I guess I''m on my own this time. Stay out of trouble.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 12, 'npc_4_1', 'His name''s Blix Lanister. He''s the sort of man you don''t want to see after a late night at the cantina. He and his swooper pals have been no end of trouble.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 13, 'npc_4_2', 'Someone has stolen the blaster used on Alita Sweetwater -- the girl Blix Lanister murdered. We suspect the thief was one of Lanister''s cronies. Without that evidence, we have a weaker case against him.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 14, 'npc_4_3', 'Blix Lanister''s crew busted him out and left town. I have people out tracking Blix, but you seem to have a knack for finding him and his cohorts. Do you think you can find him again?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 15, 'npc_reward_1', 'You did a fine job. You should consider a career as a security officer. By the way, call me Windy.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 16, 'npc_reward_2', 'Great work! Now we can bring that scoundrel to justice.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 17, 'npc_reward_3', 'I''m sorry you had to take him down instead of bringing him back to trial, but you did what was necessary. Good work.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 18, 'player_1_1', 'I''d be glad to help.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 19, 'player_1_2', 'Sure, I''d be happy to help.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 20, 'player_1_3', 'I know his pattern.  I''m the best person for this job.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 21, 'player_2_1', 'Sorry, not my line of work.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 22, 'player_2_2', 'Sorry, not interested.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 23, 'player_2_3', 'I''m not the right kind of person for this job.  I''ll pass.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 24, 'player_3_1', 'Who killed this girl?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 25, 'player_3_2', 'What''s the problem now?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 26, 'player_3_3', 'How did Blix Lanister escape?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 27, 'player_reset_1', 'No, he gave me the slip.  I can''t do this anymore.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 28, 'player_sorry_1', 'Not yet.  But don''t worry, I''m going to pick him up right now.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 29, 'npc_backtowork_1', 'Good luck.  And be careful, too.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 30, 'npc_reset_1', 'I understand. Dangerous work like this isn''t for everybody. Stay safe.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 31, 'cantwork', 'You seem a bit busy. Why don''t you see me when you have more free time?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 32, 'dontknowyou_1', 'Get out of my face!'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 33, 'npc_work_1', 'Do you have him in your custody?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 34, 'npc_work_2', 'Wre you able to get the evidence?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 35, 'npc_work_3', 'Were you able to bring him to justice?'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 36, 'npc_breech_1', 'What do you want me for? I didn''t do nothing. '),
('string/en/static_npc/tatooine/windom_starkiller.stf', 37, 'npc_breech_2', 'You ain''t taking nothing back, ever.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 38, 'npc_breech_3', 'I''m not going back there! You can''t make me!'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 40, 'notit_2', 'No, this won''t do.  Sorry, but I''m going to need more than just this.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 42, 'npc_backtowork_2', 'While you''re doing that, I''ll be drawing together a case.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 43, 'npc_backtowork_3', 'We could use your kind of dedication around here, you know?  Let me know when this is all over.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 44, 'npc_reset_2', 'I wish you''d reconsider, but if that''s how you want it, I understand.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 45, 'npc_reset_3', 'I guess I''m on my own this time. Stay out of trouble.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 46, 'player_reset_2', 'I''m pretty certain I''d botch this, then you wouldn''t have a case.  You''ll need to have someone else do it.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 47, 'player_reset_3', 'I can''t find him, Windom.  I''m sorry I let you down, but I have to give up.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 48, 'player_sorry_2', 'I''m still working on finding it.  I''ll bring it back when I have it.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 49, 'player_sorry_3', 'I haven''t found him, but I won''t rest until justice has been served.'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 50, 'npc_takeme_1', 'I swear I was nowhere near the girl.  You can''t prove it, either!'),
('string/en/static_npc/tatooine/windom_starkiller.stf', 51, 'next', 'Ever since you took down Blix Lanister, things have been real peaceful around here. Thanks again.'),
('string/en/static_npc/tatooine/wuher.stf', 1, 'npc_1_1', 'Sure, I got a job for you. A Bothan came in here a few days ago, bragging about a drink he invented. He waved the recipe in my face, laughed, then took off. No one does that to me. Get me that recipe. '),
('string/en/static_npc/tatooine/wuher.stf', 2, 'npc_1_2', 'I hate droids. Do you hate ''em? ''Cuz I sure do. One of those blasted RA-7 inspection droids just left. I don''t think it was too impressed. Think you can stop that hunk of metal before it makes its report? '),
('string/en/static_npc/tatooine/wuher.stf', 3, 'npc_1_3', 'There''s a Twi''lek named Veenos Thrax that has something I want. It''s a small sealed vial. Think you can get it?'),
('string/en/static_npc/tatooine/wuher.stf', 5, 'npc_2_1', 'The slug''s name is Baal Vurr''kya. You can find him at these coordinates. Keep it quiet.'),
('string/en/static_npc/tatooine/wuher.stf', 6, 'npc_2_2', 'Good. And bring me its verbobrain, just in case.'),
('string/en/static_npc/tatooine/wuher.stf', 7, 'npc_2_3', 'Make sure you don''t break the seal on that vial. Get it on your skin and you can kiss yourself goodbye.'),
('string/en/static_npc/tatooine/wuher.stf', 8, 'npc_3_1', 'Why are you wasting my time? I got customers to serve.'),
('string/en/static_npc/tatooine/wuher.stf', 9, 'npc_3_2', 'It really annoys me when you ask about a job then refuse it. Just so you know.'),
('string/en/static_npc/tatooine/wuher.stf', 10, 'npc_3_3', 'I hate when you do that.'),
('string/en/static_npc/tatooine/wuher.stf', 12, 'npc_4_1', 'He called it a "Molten Core." Claimed it could shrivel the ears off a gundark.'),
('string/en/static_npc/tatooine/wuher.stf', 13, 'npc_4_2', 'They just take up space and they notice stupid little details. Like anyone cares.'),
('string/en/static_npc/tatooine/wuher.stf', 14, 'npc_4_3', 'Some new type of chall poison. Veenos specializes in toxins.'),
('string/en/static_npc/tatooine/wuher.stf', 15, 'npc_reward_1', 'We''ll see if this was worth the price I paid.'),
('string/en/static_npc/tatooine/wuher.stf', 16, 'npc_reward_2', 'Huh, not bad.'),
('string/en/static_npc/tatooine/wuher.stf', 17, 'npc_reward_3', 'I''ll analyze this stuff tonight. Might come in handy.'),
('string/en/static_npc/tatooine/wuher.stf', 18, 'player_1_1', 'Sure, I''ll do it.'),
('string/en/static_npc/tatooine/wuher.stf', 19, 'player_1_2', 'No problem.  I''ll do it.'),
('string/en/static_npc/tatooine/wuher.stf', 20, 'player_1_3', 'Yeah, I''ll get it.'),
('string/en/static_npc/tatooine/wuher.stf', 21, 'player_2_1', 'I don''t care about this Bothan.  I''m not interested.'),
('string/en/static_npc/tatooine/wuher.stf', 22, 'player_2_2', 'No, I don''t really care after all.'),
('string/en/static_npc/tatooine/wuher.stf', 23, 'player_2_3', 'No thanks.'),
('string/en/static_npc/tatooine/wuher.stf', 24, 'player_3_1', 'What drink did he invent?'),
('string/en/static_npc/tatooine/wuher.stf', 25, 'player_3_2', 'Why do you hate droids?'),
('string/en/static_npc/tatooine/wuher.stf', 26, 'player_3_3', 'What''s in the vial?'),
('string/en/static_npc/tatooine/wuher.stf', 27, 'player_reset_1', 'I''ve changed my mind.  I''m not interested in doing this any more.'),
('string/en/static_npc/tatooine/wuher.stf', 28, 'player_sorry_1', 'I haven''t found him yet.  I''ll let you know when I have.'),
('string/en/static_npc/tatooine/wuher.stf', 29, 'npc_backtowork_1', 'Until you get it, stop wasting my time.'),
('string/en/static_npc/tatooine/wuher.stf', 30, 'npc_reset_1', 'Why are you wasting my time? I got customers to serve.'),
('string/en/static_npc/tatooine/wuher.stf', 31, 'cantwork', 'Talk to me when you''re not busy.'),
('string/en/static_npc/tatooine/wuher.stf', 32, 'dontknowyou_1', 'Then again, you don''t even know what I''m talking about, do you?  Nevermind.'),
('string/en/static_npc/tatooine/wuher.stf', 33, 'npc_work_1', 'Did you get that recipe for me?'),
('string/en/static_npc/tatooine/wuher.stf', 34, 'npc_work_2', 'Did you scrap that droid?'),
('string/en/static_npc/tatooine/wuher.stf', 35, 'npc_work_3', 'Do you have the vial on you?'),
('string/en/static_npc/tatooine/wuher.stf', 36, 'npc_breech_1', 'You can''t prove I poisoned those tourists! Die!'),
('string/en/static_npc/tatooine/wuher.stf', 37, 'npc_breech_2', 'This is an Imperial matter. Do not interfere.'),
('string/en/static_npc/tatooine/wuher.stf', 38, 'npc_breech_3', 'I can kill you with a touch!'),
('string/en/static_npc/tatooine/wuher.stf', 42, 'npc_backtowork_2', 'Until you break that thing in two, stop wasting my time.'),
('string/en/static_npc/tatooine/wuher.stf', 43, 'npc_backtowork_3', 'Unless you have that vial, get out of my cantina.'),
('string/en/static_npc/tatooine/wuher.stf', 44, 'npc_reset_2', 'It really annoys me when you ask about a job then refuse it. Just so you know.'),
('string/en/static_npc/tatooine/wuher.stf', 45, 'npc_reset_3', 'I hate when you do that.'),
('string/en/static_npc/tatooine/wuher.stf', 46, 'player_reset_2', 'I stopped by to tell you that I''m not interested in doing this anymore.'),
('string/en/static_npc/tatooine/wuher.stf', 47, 'player_reset_3', 'I''ve changed my mind.  I''m going to get a drink instead.'),
('string/en/static_npc/tatooine/wuher.stf', 48, 'player_sorry_2', 'Not yet, but I''ll get dismantle it before it turns in the report.'),
('string/en/static_npc/tatooine/wuher.stf', 49, 'player_sorry_3', 'No, but I will soon.  Don''t worry.'),
('string/en/static_npc/tatooine/wuher.stf', 53, 'dontknowyou_2', 'Your interference has been noted.'),
('string/en/static_npc/tatooine/wuher.stf', 54, 'dontknowyou_3', 'Don''t worry.  I''m not interested in killing you.  Get out of here before I change my mind.'),
('string/en/static_npc/tatooine/wuher.stf', 55, 'dontknowyou_4', 'Oh, you''re not a slug.  Sorry.  Didn''t mean to insult you there.'),
('string/en/static_npc/tatooine/wuher.stf', 61, 'npc_1_4', 'I need you to take out a Nikto enforcer. He''s carrying an encrypted datadisc. I need you to bring that back to me. Can you handle that?'),
('string/en/static_npc/tatooine/wuher.stf', 64, 'npc_2_4', 'Here are the Nikto''s coordinates. Don''t hesitate when you see him. Just start blasting. And don''t forget that datadisc.'),
('string/en/static_npc/tatooine/wuher.stf', 67, 'npc_3_4', 'Stop doing that! You''re driving me crazy with that!'),
('string/en/static_npc/tatooine/wuher.stf', 70, 'npc_4_4', 'You ask a lot of questions. It''s an order from Valarian to take out Jabba''s lieutenant. I figure this''ll get me in good with the Hutt.'),
('string/en/static_npc/tatooine/wuher.stf', 73, 'npc_backtowork_4', 'Understood.  I hope you have some patience as I get around to serving you.  Maybe that datadisc might speed me up, eh?'),
('string/en/static_npc/tatooine/wuher.stf', 76, 'npc_breech_4', 'Back off, slug!'),
('string/en/static_npc/tatooine/wuher.stf', 79, 'npc_reset_4', 'Stop doing that! You''re driving me crazy with that!'),
('string/en/static_npc/tatooine/wuher.stf', 82, 'npc_reward_4', 'This datadisc looks damaged. If it ain''t readable, you owe me some money.'),
('string/en/static_npc/tatooine/wuher.stf', 88, 'npc_work_4', 'So, do you have the datadisc?'),
('string/en/static_npc/tatooine/wuher.stf', 91, 'player_1_4', 'Yeah, I''ll handle this for you.'),
('string/en/static_npc/tatooine/wuher.stf', 94, 'player_2_4', 'Are you kidding?  I just wanted to ask about it, not actually do it.'),
('string/en/static_npc/tatooine/wuher.stf', 97, 'player_3_4', 'What''s on the datadisc?'),
('string/en/static_npc/tatooine/wuher.stf', 100, 'player_reset_4', 'To tell you the truth, I wasn''t going to really do it.  I was just playing with you.'),
('string/en/static_npc/tatooine/wuher.stf', 103, 'player_sorry_4', 'If I had it, I''d tell you, okay?  Have some patience.'),
('string/en/static_npc/tatooine/wuher.stf', 104, 'next', 'Work? Forget it.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 1, 'cant_work', 'You look busy. Come back later.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 2, 'dontknowyou_1', 'Who are you? I''m sorry, I don''t know you.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 3, 'dontknowyou_2', 'I don''t know you.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 4, 'dontknowyou_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 8, 'next', 'Well, you sorted that one out, mighty hunter. You have my sincere thanks for a job well done.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 9, 'notit_1', 'This doesn''t look like anything that would be found at the scene of the abduction. I suggest you go talk to Sundre again.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 10, 'notit_2', 'This isn''t what I asked for. I suggest you try again.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 11, 'notit_3', 'This isn''t what I asked for.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 12, 'notit_4', 'This is not what I asked for.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 13, 'notyet', 'I''m not sure you can be trusted. Come back later.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 14, 'npc_1_1', 'Greetings, traveller. What brings you to Yavin 4? I wonder if you are available to help me investigate a problem that has been interfering with the work schedule here. I need you to speak with my foreman, Sundre Korbeth.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 15, 'npc_1_2', 'Would you like to help out looking for those Mamien maneaters?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 16, 'npc_1_3', 'Great news, Pelig has found the Mamien. We need you to put an end to it before it kills again.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 17, 'npc_1_4', 'Pelig says he is on to the location of the Mamien''s mate. He also told us he''s investigated the lair while it was out hunting and does not believe there are others. We need you to finish this once and for all.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 18, 'npc_2_1', 'Perfect. Look for Sundre near this location on your datapad. Talk to her about the recent problems she has been having. The men think the jungle is haunted, but I think it more likely that the jungle is hungry. Be sure to bring me any evidence you might find at the location.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 19, 'npc_2_2', 'Very good. This is Pelig. He is an excellent scout, and I know he will find the beasts in no time. I will need you to accompany him through a dangerous section of jungle, then return here for your reward.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 20, 'npc_2_3', 'I know you can do it. Now Pelig places the creature right around -- here. If you head out that way you''re sure to find him. Don''t forget to return for your reward after the maneater is dead.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 21, 'npc_2_4', 'You must go at once. There''s no telling what could happen if you delay.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 22, 'npc_3_1', 'Some other time maybe?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 23, 'npc_3_2', 'And you did so well before. So be it.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 24, 'npc_3_3', 'After all you have done so far, how could you abandon us now?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 25, 'npc_3_4', 'Would you be so callous as to sit idly by as more of my workers are killed?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 26, 'npc_4_1', 'Two nights ago there was a disturbance at a remote labor camp. Wild screaming and savage growling woke everyone up. By the time anyone knew what was happening one of the men was missing. The men think it was a ghost, but I''m sure there is nothing more dangerous than a choku gone maneater.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 27, 'npc_4_2', 'If the thought of hard working men and women killed in their sleep does nothing to motivate you, there is always the lure of credits.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 28, 'npc_4_3', 'Yes, stop the Mamien killing our workers and you shall have a great reward.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 29, 'npc_4_4', 'I had thought you''d want to finish what you had started... and collect your full reward.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 30, 'npc_5_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 31, 'npc_5_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 32, 'npc_5_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 33, 'npc_5_4', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 34, 'npc_6_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 35, 'npc_6_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 36, 'npc_6_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 37, 'npc_6_4', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 38, 'npc_backtowork_1', 'You do that.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 39, 'npc_backtowork_2', 'Hurry up then, productivity is slipping.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 40, 'npc_backtowork_3', 'Please hurry before it kills again.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 41, 'npc_backtowork_4', 'Please hurry.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 42, 'npc_breech_1', 'Are you the one Drenn sent?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 43, 'npc_breech_2', 'Let''s get going, I should have been out here days ago.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 44, 'npc_breech_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 45, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 46, 'npc_dropoff_2', 'Thanks for the muscle, I can handle things from here.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 47, 'npc_dropoff_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 48, 'npc_failure_1', 'This is hardly acceptable. I should not have trusted you in the first place. I suppose this is really my own mistake.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 49, 'npc_failure_2', 'I thought you would be the one to save us from this threat. You disappoint me.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 50, 'npc_failure_3', 'Well, you''re just going to have to try to find the beast again. We can''t stop now.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 51, 'npc_failure_4', 'Well, you''re just going to have to try to find the beast again. We can''t stop now.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 52, 'npc_more_1_1', 'I''ll say this: That man was dragged off by the spirit of a long-dead Massassi warrior. I saw it, lumbering through the forest. It had glowing eyes. The men are scared and refuse to leave the camp. And rightly so -- who knows when it might come back? We found a piece of its claw. Take this back to Drenn so he can see what we have to put up with.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 53, 'npc_more_1_2', 'Yup, just get me past the danger and I''ll find those beasties for Drenn.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 54, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 55, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 56, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 57, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 58, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 59, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 60, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 61, 'npc_noloc_1', 'Sundre is very busy right now. Perhaps you should come back to me later when she''s not so busy? We can continue then.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 62, 'npc_noloc_2', 'Pelig is not quite ready. Could you come back in a little bit?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 63, 'npc_noloc_3', 'Hold on a moment, I''m having trouble reaching Pelig by comlink. Would you mind returning a little bit later?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 64, 'npc_noloc_4', 'Just a moment, Pelig just radioed a garbled message. It may be important to the status of your mission. We''re trying to reestablish contact. Come back in a little bit.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 65, 'npc_reset_1', 'Some other time maybe?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 66, 'npc_reward_1', 'Massassi ghosts, she says? Well, some people will believe anything. You see this claw? This comes from a Mamien. Big hulking ape-like creatures. I''ve never heard of one being so bold. At least I know what we''re dealing with now. Thank you for your help.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 67, 'npc_reward_2', 'So the scout is safely in the field? We''ll find our killer Mamien soon enough. And the sooner we find it, the sooner we kill it, and the sooner we can get back to work. Speaking of work, nice job.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 68, 'npc_reward_3', 'You say you killed it? This I don''t doubt, but listen close to what I have to say: There is another. While you were gone the camp was attacked again. Two of the workers were slain, and a third dragged screaming into the jungle. You''ll understand that I can''t give you the full reward until the second Mamien is killed.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 69, 'npc_reward_4', 'Ah yes, brilliant work. You are a mighty hunter, and worthy of great praise. Here is your agreed reward from the budget of the labor camp. I owe you a great deal of thanks. And for that -- let me buy you a drink.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 70, 'npc_smuggle_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 71, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 72, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 73, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 74, 'npc_takeme_2', 'Let''s get a move on. The longer we wait the colder the trail is getting.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 75, 'npc_takeme_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 76, 'npc_work_1', 'Have you spoken to Sundre already?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 77, 'npc_work_2', 'Is the scout in the field?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 78, 'npc_work_3', 'Is the beast dead yet?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 79, 'npc_work_4', 'Is it dead yet?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 80, 'otherescort_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 81, 'otherescort_2', 'I don''t think you''re talking to the right person. Look around some, they may be nearby.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 82, 'otherescort_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 83, 'player_1_1', 'I''ll help you.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 84, 'player_1_2', 'Of course I will help.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 85, 'player_1_3', 'I will kill the Mamien.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 86, 'player_1_4', 'Yes, I''ll finish what I started.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 87, 'player_2_1', 'No thank you.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 88, 'player_2_2', 'No, thank you.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 89, 'player_2_3', 'No, thank you.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 90, 'player_2_4', 'Not today, thank you.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 91, 'player_3_1', 'What exactly is going on here?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 92, 'player_3_2', 'Why should I help?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 93, 'player_3_3', 'I assume there is a reward for this?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 94, 'player_3_4', 'Why do you need me to do it?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 95, 'player_4_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 96, 'player_4_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 97, 'player_4_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 98, 'player_4_4', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 99, 'player_5_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 100, 'player_5_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 101, 'player_5_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 102, 'player_5_4', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 103, 'player_more_1_1', 'Yes, I was told you might be able to provide some insight on the attack the other night.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 104, 'player_more_1_2', 'Do you have what you need for this?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 105, 'player_more_1_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 106, 'player_more_2_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 107, 'player_more_2_2', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/yavin/drenn_zebber.stf', 108, 'player_more_2_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 109, 'player_more_3_1', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 110, 'player_more_3_2', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 111, 'player_more_3_3', ''),
('string/en/static_npc/yavin/drenn_zebber.stf', 112, 'player_reset_1', 'On second thought, I''d rather not.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 113, 'player_sorry_1', 'Not yet, I''ll be on my way.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 114, 'return_waypoint_description_1', 'This is the location of Drenn Zebber, the labor outpost foreman.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 115, 'return_waypoint_description_2', 'Drenn Zebber, the labor outpost foreman.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 116, 'return_waypoint_description_3', 'Drenn Zebber, labor outpost foreman.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 117, 'return_waypoint_name_1', 'Drenn Zebber'),
('string/en/static_npc/yavin/drenn_zebber.stf', 118, 'return_waypoint_name_2', 'Drenn Zebber'),
('string/en/static_npc/yavin/drenn_zebber.stf', 119, 'return_waypoint_name_3', 'Drenn Zebber'),
('string/en/static_npc/yavin/drenn_zebber.stf', 120, 'waypoint_description_1', 'This remote labor camp is the scene of a recent mysterious abduction.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 121, 'waypoint_description_2', 'This is the area where the scout Pelig must be delivered.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 122, 'waypoint_description_3', 'Pelig''s reported location of the Mamien Maneater.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 123, 'waypoint_name_1', 'Remote Labor Camp'),
('string/en/static_npc/yavin/drenn_zebber.stf', 124, 'waypoint_name_2', 'Scout Insertion Location'),
('string/en/static_npc/yavin/drenn_zebber.stf', 125, 'waypoint_name_3', 'Mamien Maneater'),
('string/en/static_npc/yavin/drenn_zebber.stf', 126, 'npc_reset_2', 'Some other time maybe?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 127, 'npc_reset_3', 'Some other time maybe?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 128, 'npc_reset_4', 'Some other time maybe?'),
('string/en/static_npc/yavin/drenn_zebber.stf', 129, 'player_reset_2', 'On second thought, I''d rather not.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 130, 'player_reset_3', 'On second thought, I''d rather not.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 131, 'player_reset_4', 'On second thought, I''d rather not.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 132, 'player_sorry_2', 'Not yet, I''ll be on my way.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 133, 'player_sorry_3', 'Not yet, I''ll be on my way.'),
('string/en/static_npc/yavin/drenn_zebber.stf', 134, 'player_sorry_4', 'Not yet, I''ll be on my way.'),
('string/en/static_npc/yavin/eso.stf', 1, 'cant_work', 'Is there something I can help you with? I mean, I see you walking around IN THE MIDDLE OF A BATTLEFIELD! When you''re not so busy, maybe you can do more than just get in the way! GET OUT OF HERE!'),
('string/en/static_npc/yavin/eso.stf', 2, 'dontknowyou_1', 'Never mind. I thought you were ambushing us.'),
('string/en/static_npc/yavin/eso.stf', 3, 'dontknowyou_2', 'We''re not under attack? Oh, I''m quite sorry.'),
('string/en/static_npc/yavin/eso.stf', 4, 'dontknowyou_3', 'Oh!! You''re giving me a blaster? Joy!'),
('string/en/static_npc/yavin/eso.stf', 5, 'dontknowyou_4', 'Move along. There''s nothing to see here.'),
('string/en/static_npc/yavin/eso.stf', 6, 'gotowork_1', ''),
('string/en/static_npc/yavin/eso.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/yavin/eso.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/yavin/eso.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/yavin/eso.stf', 10, 'next', 'You''ve done good, kid. Now get out of here... there''s about to be a whole mess of troopers coming in. I''ll hold them off long enough for everyone to get out of here.'),
('string/en/static_npc/yavin/eso.stf', 11, 'notit_1', 'What''s this? I don''t want this! Now get out there!'),
('string/en/static_npc/yavin/eso.stf', 12, 'notit_2', 'What''s this? I didn''t ask you for a present, idiot! I asked you to take out that medic!'),
('string/en/static_npc/yavin/eso.stf', 13, 'notit_3', 'What is this? Look, quit fooling around and do what you have to do!'),
('string/en/static_npc/yavin/eso.stf', 14, 'notit_4', 'What? Get this out of my face and get back to work.'),
('string/en/static_npc/yavin/eso.stf', 15, 'notyet', 'What are you doing standing around here? I don''t have time to answer questions for civilians. Get out of here.'),
('string/en/static_npc/yavin/eso.stf', 16, 'npc_1_1', 'What are you doing there looking slackjawed? We have a situation here that we can''t afford to sit around with our thumbs up. Look, I need you to go flank a squad of ''troopers that have my men pinned down. Do you understand, or should I speak slower?'),
('string/en/static_npc/yavin/eso.stf', 17, 'npc_1_2', 'Well now... those Recon units sure know how to scout out an area. We''ve found a hidden triage camp out in the jungle. You know what we''re going to do about it, right?'),
('string/en/static_npc/yavin/eso.stf', 18, 'npc_1_3', 'Come over here. I''ve got an assignment that''s of a... well, a sensitive nature, understand? I need you to fix a problem before it happens. If you''re squeamish, you need to let me know now before we go any further, got it?'),
('string/en/static_npc/yavin/eso.stf', 19, 'npc_1_4', 'Damn! The kid had already made enough noise to draw the Empire down on our position! AAARRG! If I hadn''t gone soft, I would''ve done the job myself. Look, you have to help buy us time so the other men can get out of here!'),
('string/en/static_npc/yavin/eso.stf', 20, 'npc_2_1', 'I''m glad I didn''t have to repeat myself. Go to this location I put in your datapad and you''ll find the troopers. If you get there quiet enough, you might be able to put a blaster through the backs of their skulls before they know what happened.'),
('string/en/static_npc/yavin/eso.stf', 21, 'npc_2_2', 'You''re blasted right you''ll help. It''s not everyday you can get a clear shot at the throat of the Empire. Go out there and take out their medic. Got it?'),
('string/en/static_npc/yavin/eso.stf', 22, 'npc_2_3', 'There''s a kid who''s seen too much fighting and he''s about to snap. If he does at the wrong moment, my whole battalion could be wiped out. Go tell him, "Hey, look over there," and when his back is turned, do what you have to do. Report back only to me when you''re done.'),
('string/en/static_npc/yavin/eso.stf', 23, 'npc_2_4', 'That''s what I wanted to hear, kid. What you''ve got to do is take out the preliminary scouts... if I can get my men out of here, I can take over where you left off. Now move out!'),
('string/en/static_npc/yavin/eso.stf', 24, 'npc_3_1', 'What did you just say? Did you tell me that you don''t like my tone? What if I shove my face a little closer to yours. Do you think you''ll like it then? WELL, DO YOU!??!'),
('string/en/static_npc/yavin/eso.stf', 25, 'npc_3_2', 'A non-combat unit!? You''ve got a guy out there who''s patching up every one of the ''troopers who get away, and you call him a non-combat unit? The battlefield is no place to start getting soft!'),
('string/en/static_npc/yavin/eso.stf', 26, 'npc_3_3', 'Yeah, I thought you were one of those yellow-bellied civilians. You''re all talk, but when someone puts a blaster in your hand, that''s when you go weak in the knees... yeah, I know your type. Ptui! I eat people like you for breakfast!'),
('string/en/static_npc/yavin/eso.stf', 27, 'npc_3_4', 'So you''re going to let a whole battalion lose their lives because you''ve decided to go coward on me? You disgust me. Get out of here before I break your neck myself.'),
('string/en/static_npc/yavin/eso.stf', 28, 'npc_4_1', 'Were you just born yesterday? Or maybe your momma didn''t tell you what a TIE Bomber is? We''re in a war here! My Recon team has encountered unexpected numbers and can''t take care of themselves right now. Now, are you going to keep jabbering or are you going to go save some men?'),
('string/en/static_npc/yavin/eso.stf', 29, 'npc_4_2', 'In case you weren''t looking, we''re in the middle of a jungle! The Empire doesn''t have time to set up shop and fixing their ''troopers, kid! Out here you throw on some bacta-soaked bandages and get back out into battle.'),
('string/en/static_npc/yavin/eso.stf', 30, 'npc_4_3', 'You know how an infected wound starts to rot and the medic says he''s gotta cut it off or everything else will go? Well, that''s what we have here... we''ve got a wound that''s about to take out my body of men. I need you to be that medic, understand?'),
('string/en/static_npc/yavin/eso.stf', 31, 'npc_4_4', 'That damned crazed kid was out in the jungle calling out for his mommy! Well, those probe droids sure as all smack heard that and found where we were. Any more questions, or do you want to actually save some lives now?'),
('string/en/static_npc/yavin/eso.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/yavin/eso.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/yavin/eso.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/yavin/eso.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/yavin/eso.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/yavin/eso.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/yavin/eso.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/yavin/eso.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/yavin/eso.stf', 40, 'npc_backtowork_1', 'You''re going to go save a group of my men! What part of that didn''t you understand?'),
('string/en/static_npc/yavin/eso.stf', 41, 'npc_backtowork_2', 'You''re going out there and taking out that medic. With him gone, the troopers will have to patch themselves up.'),
('string/en/static_npc/yavin/eso.stf', 42, 'npc_backtowork_3', 'Look, I''m not gonna chit-chat about this. Take care of the problem and let me know when it''s done, got it?'),
('string/en/static_npc/yavin/eso.stf', 43, 'npc_backtowork_4', 'You''re going out there and taking care of all the troopers you find! Now go!'),
('string/en/static_npc/yavin/eso.stf', 44, 'npc_breech_1', 'What? WE''VE BEEN FLANKED! Behind us, men!'),
('string/en/static_npc/yavin/eso.stf', 45, 'npc_breech_2', 'We''re under attack!!! Get out there and save me!'),
('string/en/static_npc/yavin/eso.stf', 46, 'npc_breech_3', 'Mommy, can I go home now? Please? Mom? What are you doing with that blaster?'),
('string/en/static_npc/yavin/eso.stf', 47, 'npc_breech_4', 'Sir, over there. We found the right place. Kill him first!'),
('string/en/static_npc/yavin/eso.stf', 48, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/eso.stf', 49, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/eso.stf', 50, 'npc_dropoff_3', ''),
('string/en/static_npc/yavin/eso.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/yavin/eso.stf', 52, 'npc_failure_1', 'If you don''t have news that makes me breathe a sigh of relief, then I suggest you walk your rear out of here -- double time!'),
('string/en/static_npc/yavin/eso.stf', 53, 'npc_failure_2', 'You let him get away? BLAST IT! That was our chance to try to slow them down, fool! Get out of here!'),
('string/en/static_npc/yavin/eso.stf', 54, 'npc_failure_3', 'What? What do you mean you went soft at the last minute? You let the kid go? *groan* You have no idea what you just did....'),
('string/en/static_npc/yavin/eso.stf', 55, 'npc_failure_4', 'You let them scout out our position? Do you know how many soldiers you''ve condemned?'),
('string/en/static_npc/yavin/eso.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/eso.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/eso.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/eso.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/yavin/eso.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/eso.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/eso.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/eso.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/yavin/eso.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/eso.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/eso.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/eso.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/yavin/eso.stf', 68, 'npc_noloc_1', 'Let me go check with the Recon group to find where they can be found. Ask me again in a few minutes.'),
('string/en/static_npc/yavin/eso.stf', 69, 'npc_noloc_2', 'Let me confirm with the Recon team where that field medic was. Ask me again in a few minutes.'),
('string/en/static_npc/yavin/eso.stf', 70, 'npc_noloc_3', 'Let me locate a good place to meet up with the kid. Check back with me in a few minutes.'),
('string/en/static_npc/yavin/eso.stf', 71, 'npc_noloc_4', 'I''ll check to see where their troop movements are coming in from. Ask me in a few minutes.'),
('string/en/static_npc/yavin/eso.stf', 72, 'npc_reset_1', 'What did you just say? WHAT DID YOU JUST SAY!? Gaaarrraahhhh! Get out of here!'),
('string/en/static_npc/yavin/eso.stf', 73, 'npc_reward_1', 'The Recon team says you got messy with your rescue. You could''ve gotten yourself killed with that reckless approach. A good blaster in the back works just as well as one in the front. Well, either way, you got the job done. Good work, kid.'),
('string/en/static_npc/yavin/eso.stf', 74, 'npc_reward_2', 'With that triage unit gone, we''ll be able to hunt down any troopers we''ve managed to wing. Now maybe they won''t be coming at us full force anymore.'),
('string/en/static_npc/yavin/eso.stf', 75, 'npc_reward_3', 'It''s done? Look -- we''ve all got blood on our hands, got it? It''s one of those things that you keep from your kiddies, but you''ll know it needed to be done. Just remember that. It needed to be done to save the rest.'),
('string/en/static_npc/yavin/eso.stf', 76, 'npc_reward_4', 'Okay, while you were taking those troopers out, I was able to pull a full evac of our soldiers. Now you get out of here, too. There should be a few hundred of the Empire coming in. I''ll take care of them. Nice having you under my command, kid. Now go!'),
('string/en/static_npc/yavin/eso.stf', 77, 'npc_smuggle_1', ''),
('string/en/static_npc/yavin/eso.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/eso.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/eso.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/yavin/eso.stf', 81, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/eso.stf', 82, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/eso.stf', 83, 'npc_takeme_3', ''),
('string/en/static_npc/yavin/eso.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/yavin/eso.stf', 85, 'npc_work_1', 'Are you still here?'),
('string/en/static_npc/yavin/eso.stf', 86, 'npc_work_2', 'Why aren''t you putting that medic out of business?'),
('string/en/static_npc/yavin/eso.stf', 87, 'npc_work_3', 'Have you done the deed?'),
('string/en/static_npc/yavin/eso.stf', 88, 'npc_work_4', 'Why aren''t you intercepting those stormtroopers?'),
('string/en/static_npc/yavin/eso.stf', 89, 'otherescort_1', ''),
('string/en/static_npc/yavin/eso.stf', 90, 'otherescort_2', ''),
('string/en/static_npc/yavin/eso.stf', 91, 'otherescort_3', ''),
('string/en/static_npc/yavin/eso.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/yavin/eso.stf', 93, 'player_1_1', 'Yes sir! I understand! I''ll do it.'),
('string/en/static_npc/yavin/eso.stf', 94, 'player_1_2', 'Yes sir, I think I know. I''ll help.'),
('string/en/static_npc/yavin/eso.stf', 95, 'player_1_3', 'I''ve got a spine of steel, sir. I''ll do what you need.'),
('string/en/static_npc/yavin/eso.stf', 96, 'player_1_4', 'Absolutely! I''ll do it.'),
('string/en/static_npc/yavin/eso.stf', 97, 'player_2_1', 'I don''t like your tone. No.'),
('string/en/static_npc/yavin/eso.stf', 98, 'player_2_2', 'If you mean kill a non-combat unit, then do it yourself.'),
('string/en/static_npc/yavin/eso.stf', 99, 'player_2_3', 'I don''t like the way this sounds. No.'),
('string/en/static_npc/yavin/eso.stf', 100, 'player_2_4', 'After your last ''assignment'', I''m not doing anything for you!'),
('string/en/static_npc/yavin/eso.stf', 101, 'player_3_1', 'What happened to your men?'),
('string/en/static_npc/yavin/eso.stf', 102, 'player_3_2', 'Why aren''t they being taken to a full hospital?'),
('string/en/static_npc/yavin/eso.stf', 103, 'player_3_3', 'What exactly is the ''situation'', sir?'),
('string/en/static_npc/yavin/eso.stf', 104, 'player_3_4', 'What do you mean he made noise?'),
('string/en/static_npc/yavin/eso.stf', 105, 'player_4_1', ''),
('string/en/static_npc/yavin/eso.stf', 106, 'player_4_2', ''),
('string/en/static_npc/yavin/eso.stf', 107, 'player_4_3', ''),
('string/en/static_npc/yavin/eso.stf', 108, 'player_4_4', ''),
('string/en/static_npc/yavin/eso.stf', 109, 'player_5_1', ''),
('string/en/static_npc/yavin/eso.stf', 110, 'player_5_2', ''),
('string/en/static_npc/yavin/eso.stf', 111, 'player_5_3', ''),
('string/en/static_npc/yavin/eso.stf', 112, 'player_5_4', ''),
('string/en/static_npc/yavin/eso.stf', 113, 'player_more_1_1', ''),
('string/en/static_npc/yavin/eso.stf', 114, 'player_more_1_2', ''),
('string/en/static_npc/yavin/eso.stf', 115, 'player_more_1_3', ''),
('string/en/static_npc/yavin/eso.stf', 116, 'player_more_1_4', ''),
('string/en/static_npc/yavin/eso.stf', 117, 'player_more_2_1', ''),
('string/en/static_npc/yavin/eso.stf', 118, 'player_more_2_2', ''),
('string/en/static_npc/yavin/eso.stf', 119, 'player_more_2_3', ''),
('string/en/static_npc/yavin/eso.stf', 120, 'player_more_2_4', ''),
('string/en/static_npc/yavin/eso.stf', 121, 'player_more_3_1', ''),
('string/en/static_npc/yavin/eso.stf', 122, 'player_more_3_2', ''),
('string/en/static_npc/yavin/eso.stf', 123, 'player_more_3_3', ''),
('string/en/static_npc/yavin/eso.stf', 124, 'player_more_3_4', ''),
('string/en/static_npc/yavin/eso.stf', 125, 'player_reset_1', 'Sir, I can''t do this anymore.'),
('string/en/static_npc/yavin/eso.stf', 126, 'player_sorry_1', 'What am I to do again?'),
('string/en/static_npc/yavin/eso.stf', 127, 'return_waypoint_description_1', 'Where you''ll find Captain Eso waiting for a report'),
('string/en/static_npc/yavin/eso.stf', 128, 'return_waypoint_description_2', 'Eso is waiting for a report on the situation'),
('string/en/static_npc/yavin/eso.stf', 129, 'return_waypoint_description_3', 'Let Eso know that the problem has been solved'),
('string/en/static_npc/yavin/eso.stf', 130, 'return_waypoint_description_4', 'Return to the Captain to see if you bought enough time for them'),
('string/en/static_npc/yavin/eso.stf', 131, 'return_waypoint_name_1', 'Captain Eso'),
('string/en/static_npc/yavin/eso.stf', 132, 'return_waypoint_name_2', 'Captain Eso'),
('string/en/static_npc/yavin/eso.stf', 133, 'return_waypoint_name_3', 'Captain Eso'),
('string/en/static_npc/yavin/eso.stf', 134, 'return_waypoint_name_4', 'Captain Eso'),
('string/en/static_npc/yavin/eso.stf', 135, 'waypoint_description_1', 'The prime spot to ambush the stormtroopers.'),
('string/en/static_npc/yavin/eso.stf', 136, 'waypoint_description_2', 'A hidden impromptu healing facility.'),
('string/en/static_npc/yavin/eso.stf', 137, 'waypoint_description_3', 'A soldier who has become a problem to the battalion -- a potentially fatal problem. Sometimes war makes you do things you''ll regret when you''re old.'),
('string/en/static_npc/yavin/eso.stf', 138, 'waypoint_description_4', 'Take out all the stormtroopers you find and you''ll buy the battalion time to escape.'),
('string/en/static_npc/yavin/eso.stf', 139, 'waypoint_name_1', 'Ambush Point'),
('string/en/static_npc/yavin/eso.stf', 140, 'waypoint_name_2', 'Bacta Tanks'),
('string/en/static_npc/yavin/eso.stf', 141, 'waypoint_name_3', 'Deranged Soldier'),
('string/en/static_npc/yavin/eso.stf', 142, 'waypoint_name_4', 'Stormtrooper Patrol'),
('string/en/static_npc/yavin/eso.stf', 143, 'npc_reset_2', 'Can''t handle it huh?'),
('string/en/static_npc/yavin/eso.stf', 144, 'npc_reset_3', 'Fine.  Get out of my sight before I get angry.'),
('string/en/static_npc/yavin/eso.stf', 145, 'npc_reset_4', 'Go then.  I don''t care.'),
('string/en/static_npc/yavin/eso.stf', 146, 'player_reset_2', 'I can''t handle this.'),
('string/en/static_npc/yavin/eso.stf', 147, 'player_reset_3', 'I''m done, I can''t take this anymore.'),
('string/en/static_npc/yavin/eso.stf', 148, 'player_reset_4', 'I''ve had it.  I give up.'),
('string/en/static_npc/yavin/eso.stf', 149, 'player_sorry_2', 'I''m on that task, sir.'),
('string/en/static_npc/yavin/eso.stf', 150, 'player_sorry_3', 'I should get back to work...'),
('string/en/static_npc/yavin/eso.stf', 151, 'player_sorry_4', 'I''ll be done soon.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 1, 'cant_work', 'Looks like you''re working hard. I like to see that. Come back when you''re not so busy - I''ve got some more work for you.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 2, 'dontknowyou_1', 'Nice weather we''ve been having, hmm?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 4, 'dontknowyou_3', 'Who are you? No, I should be all right on my own now.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 5, 'gotowork_1', 'You wouldn''t happen to have a secondary flux modulator for an IT series mineral scanner, would you?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 8, 'next', 'Well, things are certainly a lot easier around here since you showed up. I''m sorry, but I just don''t have anything else for you to do.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 9, 'notit_1', 'This isn''t what I asked for. Stop fooling around.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 10, 'notit_2', 'You''re not done yet.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 11, 'notit_3', 'This isn''t what I asked for.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 12, 'notyet', 'Is there something I can help you with? We''re all very busy around here, and don''t have much time to talk to strangers.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 13, 'npc_1_1', 'Three hours? Three hours and they just now let us know the dang thing is busted? Unbelievable. Now where am I going to find someone to... hey, you! Yeah. How would you like to earn a few credits running a replacement part out to a surveying team?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 14, 'npc_1_2', 'There''s been a fair bit of excitement around the old camp since you left. Anglers. Two or three of the nasty Sithspawn came in from the jungle. Made off with our pack kaadu. It wasn''t cheap importing that thing all the way from Naboo, either. But the point is, we can''t have these sort of goings-on. How do you feel about killing a few anglers?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 15, 'npc_1_3', 'You haven''t let me down yet, and for the sake of my men I hope you don''t start now. That surveying team you helped out before is being attacked by a rabid pack of choku. I need you to get out there and rescue as many of them as you can.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 16, 'npc_2_1', 'That''s just fantastic. You run this briefcase out to the jokers standing about near the location I''ve marked on your datapad, and I''ll give you a few credits.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 17, 'npc_2_2', 'Hey, this isn''t a situation you should approach lightly. Those anglers will eat a person just the same as a kaadu. I have faith in you, though. One of my men followed the things back to their den. I''ll mark the location on your datapad. Stop by after you''re done and I''ll see you get your reward.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 18, 'npc_2_3', 'Good. Hurry, there''s no time to waste. You know what to expect: choku are meaner than a sack full of womp rats. Still, I know you''ve got it in you.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 19, 'npc_3_1', 'Okay then. If you''re not going to help, would you mind not getting in the way?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 20, 'npc_3_2', 'Hmm. Well, we should be safe for a while. Kaadu meat is very filling from what I hear. I do wish you would reconsider. Soon.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 21, 'npc_3_3', 'It seems I overestimated you. I just regret that it figured into the loss of my men.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 22, 'npc_4_1', 'It''s just a quick trip to a few surveyors. It''s nothing dangerous, but we have plenty of work to do. I''d rather not send one of my men out if I can avoid it. And I''m prepared to pay you well.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 23, 'npc_4_2', 'I don''t blame you for thinking about number one. Anglers can be pretty tricky. Well, I''ve got a few credits for you. And there''s this set of old mining coveralls I found in the storeroom. They look to be about your size.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 24, 'npc_4_3', 'How could you think of payment when the lives of my men are on the line? Are you really that mercenary? Sad. Yes, I will pay you if you save my men.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 31, 'npc_backtowork_1', 'I''d say you should.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 32, 'npc_backtowork_2', 'I ddin''t think they were.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 33, 'npc_backtowork_3', 'Yes, please do.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 34, 'npc_breech_1', 'Hey, are you the courier that Jazeen sent?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 35, 'npc_breech_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 36, 'npc_breech_3', 'Spare me... spare me. My child, my wife... Please help me!'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 39, 'npc_dropoff_3', 'I''m alive... but I''ll be needing a visit to the infirmary. Thank you... for all you''ve done. You''re a true hero.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 40, 'npc_failure_1', 'This is what I get for asking a stranger to help me. Well, you know what they say about wanting something done right.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 41, 'npc_failure_2', 'Well, it happens to the best of us. Don''t let it get you down. Maybe you should try again?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 42, 'npc_failure_3', 'It seems I overestimated you. I just regret that it figured into the loss of my men.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 52, 'npc_noloc_1', 'Hey, give me a minute. Those fools weren''t at the right place. Come back a little later, okay?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 53, 'npc_noloc_2', 'Hold on a minute, comlink going off... Jazeen here... Ah, Sithspit! All right, you keep an eye on them and let me know when they''ve stopped. Out. -- Well, hold your horses. Seems those beasties got the idea to up and move. Check back with me a little later and I''ll let you know if they''ve stopped.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 54, 'npc_noloc_3', 'Hold on lad. They''re running for their lives. We''re trying to track their movement. Sit tight a minute, I''ll let you know when we find them.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 55, 'npc_reset_1', 'Very well then, forget I even asked.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 56, 'npc_reward_1', 'Hey, not bad. Not bad at all. You came through for me kid, I''ll remember this. Here are those credits we talked about.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 57, 'npc_reward_2', 'You got them, eh? Another job well done. The camp''ll be safe for the time being. Here ya go.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 58, 'npc_reward_3', 'I know you did the best you could, and I''m thankful for that. You''ve done a great thing today. I don''t think of too many people this way, but I believe the men are right when they talk about you like a hero.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 59, 'npc_smuggle_1', 'Look at that. We''ll get this scanner up and running in no time. Best you get back to Jazeen and tell him the good news. We''ll take care of things here.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 64, 'npc_takeme_3', 'You''ve finally arrived! Thank you!'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 65, 'npc_work_1', 'Is there some problem?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 66, 'npc_work_2', 'Those spiders dead yet?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 67, 'npc_work_3', 'Those men sounded like they''re in a bad way. Unless this is important I suggest you get moving.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 70, 'otherescort_3', 'I appreciate you being here to help out, but I don''t recognize you. If you''re looking for someone I suggest you look more carefully.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 71, 'player_1_1', 'I''ll take the job.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 72, 'player_1_2', 'Finally, a bit of action.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 73, 'player_1_3', 'How could I refuse? I''ll go help them out.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 74, 'player_2_1', 'I''m not interested.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 75, 'player_2_2', 'No, I''m not quite ready for that.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 76, 'player_2_3', 'I''d like to help, but --'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 77, 'player_3_1', 'Why should I?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 78, 'player_3_2', 'What''s in it for me?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 79, 'player_3_3', 'You gonna pay me or what?'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 80, 'player_4_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 81, 'player_4_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 82, 'player_4_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 83, 'player_5_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 84, 'player_5_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 85, 'player_5_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/yavin/jazeen_thumm.stf', 95, 'player_reset_2', 'I don''t want to do this anymore.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 96, 'player_sorry_1', 'No, sorry. I''ll get on that right away.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 97, 'return_waypoint_description_1', 'Mining outpost foreman.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 98, 'return_waypoint_description_2', 'Mining outpost foreman.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 99, 'return_waypoint_description_3', 'Mining outpost foreman.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 100, 'return_waypoint_name_1', 'Jazeen Thumm'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 101, 'return_waypoint_name_2', 'Jazeen Thumm'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 102, 'return_waypoint_name_3', 'Jazeen Thumm'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 103, 'waypoint_description_1', 'This is the location of a survey site in need of repair parts for a mineral scanner.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 104, 'waypoint_description_2', 'A group of anglers who have recently been preying on the mining outpost.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 105, 'waypoint_description_3', 'The survivors of a survey team beset by a pack of ravenous choku.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 106, 'waypoint_name_1', 'Survey Site'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 107, 'waypoint_name_2', 'Angler Lair'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 108, 'waypoint_name_3', 'Survey Team Survivors'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 109, 'npc_reset_2', 'It''s ok.  Not everyone can put in the work I need.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 110, 'npc_reset_3', 'Fine, go on then. '),
('string/en/static_npc/yavin/jazeen_thumm.stf', 111, 'npc_reset_4', 'I don''t understand.  I thought you were better than this...'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 112, 'player_reset_1', 'I can''t finish this assignment.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 113, 'player_reset_3', 'I can''t do this.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 114, 'player_reset_4', 'I''m tired of this job.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 115, 'player_sorry_2', 'I''ll get done quick as I can.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 116, 'player_sorry_3', 'This task should be finished soon.'),
('string/en/static_npc/yavin/jazeen_thumm.stf', 117, 'player_sorry_4', 'I just need a little more time...'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 1, 'cant_work', 'I could use some help tracking down hidden Rebel enclaves. Why don''t you come back and help me when you''ve finished with your current duties?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 2, 'dontknowyou_1', 'This is not a secure area, friend. You should leave before trouble erupts.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 3, 'dontknowyou_2', 'You may want to consider moving on. Several of our people are missing. This could turn in to a war zone at any moment.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 4, 'dontknowyou_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 8, 'next', 'Everything is quiet right now. But come see me later. Those Rebels are like vermin - you can never get rid of them entirely.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 9, 'notit_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 10, 'notit_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 11, 'notit_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 12, 'notyet', 'I need to be left alone for now.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 13, 'npc_1_1', 'They''re everywhere, you know. Rebels, I mean. They lurk around the periphery looking for weak points they can exploit. It''s important to remain vigilant. A lot of my officers have gotten jaded and I could use someone to shake things up a little. Do you think you might be interested in doing that?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 14, 'npc_1_2', 'There''s one sure thing to follow a group of Rebel scouts gone missing - a rescue attempt. I''d like you to arrange a little surprise for whatever group they send to rescue their lost scouts. Are you up for taking down a few more of those Rebel vermin?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 15, 'npc_1_3', 'So far we''ve had scouts and a rescue party. That says to me that they must have some sort of mobile command center. I think it would be a good idea for you to find the leader of this base and obliterate him. I can''t leave those rebels running around on my watch, now can I? I could really use you on this one. How about it?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 16, 'npc_2_1', 'I know there are little pockets of that rabble scattered all over this planet. No doubt they have scouting parties checking on our activities. I''d be very pleased if you''d find one of these scouting parties and destroy it. Very pleased indeed. '),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 17, 'npc_2_2', 'Good. I have intelligence on some unexplained activity in one sector. That''s probably the best place to start. Return to me once you''ve rooted them out.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 18, 'npc_2_3', 'You know what you have to do. Find that Colonel and destroy him. Any Rebels in the area should be eliminated also. Report back once your mission is complete.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 19, 'npc_3_1', 'I hope you''re not trying to protect those scum. I won''t rest until every Rebel on this world is dead.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 20, 'npc_3_2', 'I''m a military commander, not a nursemaid. As far as I''m concerned, if you''re not part of the solution, you''re part of the problem.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 21, 'npc_3_3', 'I would never question your loyalty. That''s the Imperial Security Bureau''s job.  '),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 22, 'npc_4_1', 'You''re pretty new to Yavin. I figure if a rookie like you comes in and tracks down some hidden Rebels it will force them to become more alert. What do you say?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 23, 'npc_4_2', 'Exactly the kind of surprise I had in mind. You find that rescue party and blast them off the map. How about it?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 24, 'npc_4_3', 'I''m the commander of an Imperial base. Assume I have access to intelligence reports and that I know what I''m talking about. The question is not whether there is a Rebel leader; the question is whether you are going to destroy him.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 31, 'npc_backtowork_1', 'Are you changing your mind or are you just the jittery type?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 32, 'npc_backtowork_2', 'You seem to want to say something. Just spit it out.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 33, 'npc_backtowork_3', 'I can see you''re excited. Speak your mind and let''s get on with it.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 34, 'npc_breech_1', 'We''ve got trouble!'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 35, 'npc_breech_2', 'It looks like we''ve got some uninvited company.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 36, 'npc_breech_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 40, 'npc_failure_1', 'This isn''t exactly what I had in mind to impress my officers.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 41, 'npc_failure_2', 'Failure? No just a temporary setback. Learn from it and move on.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 42, 'npc_failure_3', 'I don''t believe in failure. Somehow, however, it keeps occurring despite my lack of faith.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 52, 'npc_noloc_1', 'Let''s continue this conversation in a little while. I have an important call I need to make. Would you mind giving me a few minutes of privacy?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 53, 'npc_noloc_2', 'I should find out if there''s been any unusual activity anywhere. It might provide you with a good starting point. I''ll have to ask you to leave for a few minutes while I access that information. For reasons of security.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 54, 'npc_noloc_3', 'I''ll have to ask you to leave for a few minutes while I check some intelligence reports. Just a security precaution.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 55, 'npc_reset_1', 'Come back and wipe out those Rebel scum when you''re better prepared.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 56, 'npc_reward_1', 'Outstanding! That should show my officers what you can do when you put your mind to something. Come back and see me about more work, you have a real talent for this.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 57, 'npc_reward_2', 'If I had a few like you among my officers, I''d be able to clean those scum off this world in no time. First-rate job.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 58, 'npc_reward_3', 'You''ve done the Empire a great service. I think this should keep those Rebels from taking too keen an interest in Yavin for a while.  It''s just too costly for them to stick around here.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 65, 'npc_work_1', 'Have you managed to track down one of those scouting parties yet?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 66, 'npc_work_2', 'Have you found any sign of a Rebel rescue team? I know they''re out there somewhere.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 67, 'npc_work_3', 'Get out there and destroy that Rebel. '),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 71, 'player_1_1', 'Yes'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 72, 'player_1_2', 'Yes'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 73, 'player_1_3', 'Yes'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 74, 'player_2_1', 'No'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 75, 'player_2_2', 'No'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 76, 'player_2_3', 'No'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 77, 'player_3_1', 'How do you want me to shake things up?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 78, 'player_3_2', 'A surprise, eh? The kind that involves a lot of collateral damage?'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 79, 'player_3_3', 'Why are you so sure there''s a mobile base?'),
