INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 109, 'npc_reset_2', 'Come back and wipe out those Rebel scum when you''re better prepared.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 110, 'npc_reset_3', 'Come back and wipe out those Rebel scum when you''re better prepared.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 111, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 112, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 113, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_imperialgarrison_vraker_orde.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 1, 'cant_work', 'Report here after you''ve completed your current assignment.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 2, 'dontknowyou_1', 'You''re in the wrong place, friend. No supplies available today.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 3, 'dontknowyou_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 4, 'gotowork_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 6, 'next', 'No assignments today.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 7, 'notit_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 8, 'notit_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 9, 'notyet', 'I can''t speak with you right now, I''m on duty.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 10, 'npc_1_1', 'Medics at an independent supply depot were seen to issue supplies to a known Rebel. We want you to blow up the depot.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 11, 'npc_1_2', 'We''ve located a Rebel transmission relay. Seems to be hidden in a lair of klikniks, some kind of native bugs. Destroy the lair and that should take out the transmitter.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 12, 'npc_2_1', 'Report back here when the depot is gone.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 13, 'npc_2_2', 'Right. Report back when you''ve destroyed the bug lair.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 14, 'npc_3_1', 'Very well, that''s all.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 15, 'npc_3_2', 'Don''t want to crush a few bugs? Well, check back if you change your mind.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 16, 'npc_4_1', 'They''re probably all Rebel sympathizers, so they deserve to die. Do you want the job or not?'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 17, 'npc_4_2', 'Saves time. Bugs are bugs. Do you want the job or not?'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 18, 'npc_5_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 22, 'npc_backtowork_1', 'That''s all the info I have. Destroy the medical supply depot.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 23, 'npc_backtowork_2', 'That''s all the information I have. Destroy the kliknik lair.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 24, 'npc_breech_1', 'Imperial! Attack!'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 25, 'npc_breech_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 28, 'npc_failure_1', 'Didn''t destroy that medical supply depot? We''ll find someone who can.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 29, 'npc_failure_2', 'Didn''t destroy that kliknik lair? Well, we''ll find someone who can.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 35, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 36, 'npc_noloc_1', 'I''m waiting on coordinates for the medical supply depot. Report back here in a few moments.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 37, 'npc_noloc_2', 'I''m waiting on coordinates for the kliknik lair. Check with me in a few moments.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 38, 'npc_reset_1', 'No stomach for facing a medical supply depot? Not much of a soldier.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 39, 'npc_reward_1', 'Good. Report back if you want another assignment.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 40, 'npc_reward_2', 'Good job. That''s all for now.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 41, 'npc_smuggle_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 42, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 45, 'npc_work_1', 'You need to destroy that medical supply depot.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 46, 'npc_work_2', 'You''re supposed to destroy that kliknik lair with the hidden Rebel transmitter.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 53, 'player_3_1', 'Destroying a medical supply depot because it helped one Rebel? Isn''t that overkill?'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 54, 'player_3_2', 'Why destroy a whole lair of innocent creatures instead of just the transmitter?'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 55, 'player_4_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 56, 'player_4_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 57, 'player_5_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 58, 'player_5_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 67, 'return_waypoint_description_1', 'This stormtrooper sergeant awaits news of the destruction of the medical supply depot that issued supplies to a Rebel.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 68, 'return_waypoint_description_2', 'This stormtrooper sergeant awaits news of the destruction of the "Rebel" kliknik lair.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 69, 'return_waypoint_name_1', 'CX-425'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 70, 'return_waypoint_name_2', 'CX-425'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 71, 'waypoint_description_1', 'Stormtrooper sergeant CX-425 wants this independent depot blown up because it provided supplies to a Rebel.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 72, 'waypoint_description_2', 'Stormtrooper sergeant CX-425 believes this lair of klikniks harbors a hidden Rebel transmitter.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 73, 'waypoint_name_1', 'Medical Supply Depot'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 74, 'waypoint_name_2', '"Rebel" Kliknik Lair'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 75, 'npc_reset_2', 'No stomach for facing a medical supply depot? Not much of a soldier.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_cx-425.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 1, 'cant_work', 'You look like an experienced servant of the Empire. I''m prepared to employ you once you''re available.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 2, 'dontknowyou_1', 'Can''t help you, friend.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 3, 'dontknowyou_2', 'Clear out, citizen.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 4, 'dontknowyou_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 8, 'next', 'The situation here has been normalized. I don''t need help right now.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 9, 'notit_1', 'You were supposed to bring me a stranded Rebel''s weapon. What are you bothering me with this for?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 10, 'notit_2', 'You were supposed to bring me a Rebel Special Forces sergeant''s weapon, which I believe may change the course of the Civil War. That clearly isn''t it!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 11, 'notit_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 12, 'notyet', 'I''m not able to deal with you right now.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 13, 'npc_1_1', 'As part of the Empire''s salvage operation on Yavin 4, I''m hunting the Rebels and their secret weapon. Our probes just sighted a Rebel squad that apparently got stranded in the jungle. They may have been retrieving the weapon from a hidden cache. I want you to assemble a team, hit them hard, and take the weapon.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 14, 'npc_1_2', 'You''re back? We''ve located a Rebel Special Forces squad that, in my view, could very likely be carrying the Rebellion''s secret terror weapon that destroyed the Death Star. I want you to take an experienced team and bring back that weapon.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 15, 'npc_1_3', 'You again. At long last, I believe we''ve located the Rebels'' secret weapon that blew up the Death Star -- or at least the lab where they built it. This stronghold may be preparing another weapon even as we speak! It''s up to you to take out the scientist!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 16, 'npc_2_1', 'Good. I''m counting on you to render this situation normalized. Report back here with the weapon.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 17, 'npc_2_2', 'Excellent! I advise you to approach with a strong team and attack from surprise. Take no chances with this galaxy-changing weapon!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 18, 'npc_2_3', 'Good. I''ll wait here for you to return with your report of the secret weapons scientist''s demise.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 19, 'npc_3_1', 'I have no time for slackers.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 20, 'npc_3_2', 'You have missed your chance to change history. I pity you.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 21, 'npc_3_3', 'If you no longer believe in this cause, then it''s best you get out.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 22, 'npc_4_1', 'Because the Death Star didn''t just blow up by itself, now did it? Enough silly questions! Will you help the Empire or not?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 23, 'npc_4_2', 'Well, what else would a Special Forces squad be doing here? Just hunting Imperials? I think not! This is our chance to seize the weapon that can annihilate the Rebellion! Will you seize this chance at glory?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 24, 'npc_4_3', 'There has to be a super weapon! If there isn''t, why would the Empire be expending such enormous resources to find it? Hah? Answer me that. That''s right, you can''t. Now will you destroy this weapons lab or not?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 31, 'npc_backtowork_1', 'Enough chatter. Destroy those Rebels and retrieve their secret weapon!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 32, 'npc_backtowork_2', 'Enough talking. I expect to hear shortly of the Rebel Special Forces squad dying in battle.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 33, 'npc_backtowork_3', 'No more talk. That Rebel weapons lab could be creating another super weapon as we speak. Destroy the lab!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 34, 'npc_breech_1', 'Enemy sighted!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 35, 'npc_breech_2', 'An Imperial! Fire!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 36, 'npc_breech_3', 'Imperials!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 40, 'npc_failure_1', 'You didn''t defeat those Rebels? That could have been the super weapon, slipping through our fingers!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 41, 'npc_failure_2', 'With the Civil War hanging in the balance, you may have let the ultimate weapon slip through your clumsy fingers!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 42, 'npc_failure_3', 'You couldn''t take out that Rebel weapons lab? They could be readying their super weapon to blow up this entire moon!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 52, 'npc_noloc_1', 'I''m awaiting updated coordinates from the probes. Check with me in a moment.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 53, 'npc_noloc_2', 'I am awaiting current coordinates for the Rebel Special Forces squad. Talk to me again in a moment.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 54, 'npc_noloc_3', 'Wait -- I have to take this call from my superiors. They apparently need reassurance that it''s worthwhile to hunt for the Rebels'' super weapon. Hah! Talk to me again in a moment.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 55, 'npc_reset_1', 'The Empire didn''t get where it is today by slacking! Return here when you''re ready to test your mettle.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 56, 'npc_reward_1', 'No super weapon this time. But there could have been! To find a secret weapon, you have to follow every possible lead. Check with me soon for more leads.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 57, 'npc_reward_2', 'Hmm. Well, at least we can cross one more lead off a long list. But we''ll find that weapon! If we have to burn the jungle to the ground, we''ll find it! And you''ll help, if you talk to me again.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 58, 'npc_reward_3', 'All right, so it was just a listening post. But you can never -- never -- be sure. Now leave me alone, I have to figure out how to explain this to my superiors.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 65, 'npc_work_1', 'I expect you to attack those stranded Rebels and bring back their leader''s weapon. Get moving!'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 66, 'npc_work_2', 'I have heard no report of the Rebel Special Forces squad dying in battle. Why not?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 67, 'npc_work_3', 'Is something holding you back from destroying that Rebel weapons lab? Something more important than the end of the Civil War?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 77, 'player_3_1', 'Why do you think the Rebels have a secret weapon?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 78, 'player_3_2', 'Why do you think this Special Forces squad is carrying the secret weapon?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 79, 'player_3_3', 'After all this time, you still think the Rebels have a secret weapon?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 80, 'player_4_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 81, 'player_4_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 82, 'player_4_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 83, 'player_5_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 84, 'player_5_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 85, 'player_5_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 97, 'return_waypoint_description_1', 'This Imperial officer is waiting for the stranded Rebels'' weapon, which he believes may have destroyed the Death Star.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 98, 'return_waypoint_description_2', 'This Imperial officer awaits a weapon secured from a Rebel Special Forces sergeant. Darone hopes this is the secret device that destroyed the Death Star.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 99, 'return_waypoint_description_3', 'This Imperial officer is waiting for a report on the destroyed Rebel listening post, which he believed was a weapons lab that built a super weapon.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 100, 'return_waypoint_name_1', 'Lt. Cmdr Gins Darone'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 101, 'return_waypoint_name_2', 'Lt. Cmdr. Gins Darone'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 102, 'return_waypoint_name_3', 'Lt. Cmdr. Gins Darone'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 103, 'waypoint_description_1', 'Imperial Lt. Cmdr. Gins Darone believes this squad of Rebel Alliance soldiers may be carrying the secret weapon that destroyed the Death Star.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 104, 'waypoint_description_2', 'A squad of Rebel Alliance Special Forces soldiers, possibly carrying a secret weapon desired by Imperial Lt. Cmdr. Gins Darone.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 105, 'waypoint_description_3', 'According to Imperial Lt. Cmdr. Gins Darone, the Rebel Alliance may have used this installation to build the super weapon that destroyed the Death Star.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 106, 'waypoint_name_1', 'Stranded Rebel Squad'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 107, 'waypoint_name_2', 'Rebel Special Forces'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 108, 'waypoint_name_3', 'Rebel Weapons Lab?'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 109, 'npc_reset_2', 'The Empire didn''t get where it is today by slacking! Return here when you''re ready to test your mettle.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 110, 'npc_reset_3', 'The Empire didn''t get where it is today by slacking! Return here when you''re ready to test your mettle.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 111, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 112, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 113, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_gins_darone.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 1, 'cant_work', 'I have some work for you if you finish with your current employer anytime soon. '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 2, 'dontknowyou_1', 'There''s nothing for you here, citizen. I''m just waiting to meet someone and then I''ll be on my way.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 3, 'dontknowyou_2', 'I''m waiting for someone to meet me. You can just head on your way.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 4, 'dontknowyou_3', 'Do me a favor and get out of here. I''m trying to keep a low profile.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 5, 'dontknowyou_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 6, 'gotowork_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 7, 'gotowork_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 8, 'gotowork_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 9, 'gotowork_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 10, 'next', 'That''s all I have for you at the moment. Check back with me in case anything more comes up before I''m shipped out of here.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 11, 'notit_1', 'This isn''t the report I sent you to get. Maybe you should look again.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 12, 'notit_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 13, 'notit_3', 'You meant to give me some spy reports didn''t you? Those aren''t spy reports.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 14, 'notit_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 15, 'notyet', 'I''m too busy to deal with you at the moment.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 16, 'npc_1_1', 'I just don''t like the climate here. I plan to be off this world as soon as I''ve finished with the salvage operation and learned what I can from that abandoned Rebel base. Speaking of which, I need someone to pick up a report from the forensics team. Would you be willing to go get that for me?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 17, 'npc_1_2', 'I''m not very trusting of that Selonian running the salvage operation. I think she''s keen to run off and sell the equipment on the black market. I have an operative planted in her crew who keeps me up to speed on what''s going on at the Salvage Camp. I need someone to bring my spy in safely and I''m a little short handed right now. Would you mind filling in?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 18, 'npc_1_3', 'I''m glad you''ve come back again. We discovered there was a Rebel spy who didn''t make it offworld when they evacuated. We''ve narrowed down the area where this spy might be. With your help we should be able to wrap this up pretty quickly. How about it?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 19, 'npc_1_4', 'You certainly have a knack for showing up at the right time. Those Rebels managed to leave behind more than just a spy and a few unfortunates who missed the last shuttle. There seems to be a couple of highly trained commandos who are wreaking havoc on this operation with their guerilla tactics. Think you can track them down and put a stop to it?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 20, 'npc_2_1', 'All you have to do is collect the report from the Imperial courier and bring it back here. There are probably still a few Rebels who didn''t make it off world. So be careful. '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 21, 'npc_2_2', 'Good. Go and meet my operative and come back here without either of you getting killed. There are a lot of scavengers looting through the wreckage so that isn''t as easy as it sounds.  '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 22, 'npc_2_3', 'What we really want is the information this spy may have been collecting. Capturing the spy would be perfect but if the traitor gets killed and we have the data that would have gone to the Rebels, I''ll call it a victory. '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 23, 'npc_2_4', 'Good. Find them and put a stop to all their interference. These Rebels are pretty good at what they do, so be sure and bring some backup you can trust. Be careful.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 24, 'npc_3_1', 'In a hurry to get off of this muggy jungle rock? Can''t blame you for that.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 25, 'npc_3_2', 'I don''t know why you stick around here. Do you actually like this weather?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 26, 'npc_3_3', 'And yet you seem to remain on this haven for insects and lizards. What is wrong with you?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 27, 'npc_3_4', 'Are you finally going to get out of this sweltering hole?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 28, 'npc_4_1', 'We have a team going over the Rebel base inch by inch, looking for any useful information. I just want you to pick up their latest report. How about it?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 29, 'npc_4_2', 'Because I have about half of the people I need to complete a job this size in a timely fashion. I plan to shock my superiors by finishing on time or sooner and getting off of this steamy sewer moon. Are you going to help me or not?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 30, 'npc_4_3', 'To spy on us of course. No doubt we''ve been monitored the whole time we''ve been here. The Rebels would likely pick up their little spy after we leave. Now are you going to help me with this?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 31, 'npc_4_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 32, 'npc_5_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 33, 'npc_5_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 34, 'npc_5_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 35, 'npc_5_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 36, 'npc_6_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 37, 'npc_6_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 38, 'npc_6_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 39, 'npc_6_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 40, 'npc_backtowork_1', 'You know everything you''re cleared to know. What else do you want?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 41, 'npc_backtowork_2', 'I''m extremely busy so talk fast.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 42, 'npc_backtowork_3', 'What''s wrong now? Are you having second thoughts?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 43, 'npc_backtowork_4', 'I wish I had more for you to go on. Are you in or not?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 44, 'npc_breech_1', 'I was afraid you might have gotten lost.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 45, 'npc_breech_2', 'Did you have any trouble finding this spot?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 46, 'npc_breech_3', 'Death to the Empire!'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 47, 'npc_breech_4', 'This is probably the worst place you could be right now. You should move on before trouble starts.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 48, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 49, 'npc_dropoff_2', 'I was wrong about giving those scavengers the slip. Thanks for the save.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 50, 'npc_dropoff_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 51, 'npc_dropoff_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 52, 'npc_failure_1', 'Rebel activity must be worse than I realized, or perhaps you just had a little bit of bad luck. '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 53, 'npc_failure_2', 'This must be a day for setbacks. The forensics team didn''t get anything done today either.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 54, 'npc_failure_3', 'I hope this debacle doesn''t extend my tour of duty here.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 55, 'npc_failure_4', 'This is turning into a bigger problem than I thought. We''ve got to stop those Rebels before they cause any more trouble.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 56, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 57, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 58, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 59, 'npc_more_1_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 60, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 61, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 62, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 63, 'npc_more_2_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 64, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 65, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 66, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 67, 'npc_more_3_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 68, 'npc_noloc_1', 'Wait a moment. I just got word that they haven''t even finished the blasted report yet. Come back in a little while. '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 69, 'npc_noloc_2', 'I''m still waiting for my operative to check in. Why don''t you come back in a little while?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 70, 'npc_noloc_3', 'I''ll need a few minutes to let my field team know you''ll be working with us, so they know not to shoot at you. Check back in a few minutes and I should be ready.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 71, 'npc_noloc_4', 'Give me a few minutes to get you cleared with the other field teams. I wouldn''t want you getting shot for being a Rebel. Come back in a little while, I should have it taken care of soon.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 72, 'npc_reset_1', 'Why don''t you come back once you think you''re ready to finish this job?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 73, 'npc_reward_1', 'At last. I hope they finally found something useful. '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 74, 'npc_reward_2', 'Good, you both made it back. I''m very pleased with your work. '),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 75, 'npc_reward_3', 'This will be a nice little addition to my report. Well done.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 76, 'npc_reward_4', 'You''re a good operative. It''s been a pleasure working with you.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 77, 'npc_smuggle_1', 'Those Rebels are pretty thorough for traitor scum.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 78, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 79, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 80, 'npc_smuggle_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 81, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 82, 'npc_takeme_2', 'Let''s get out of here. I saw some scavengers following me but I managed to give them the slip.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 83, 'npc_takeme_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 84, 'npc_takeme_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 85, 'npc_work_1', 'What are you waiting for? I thought I sent you off to get that report.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 86, 'npc_work_2', 'I assume you''re about to leave. Good luck.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 87, 'npc_work_3', 'Tracked down our spy yet? Keep looking. I don''t want him to slip away from us.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 88, 'npc_work_4', 'What are you loitering around here for? Go find those Rebels and take them out.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 89, 'otherescort_1', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 90, 'otherescort_2', 'I''m waiting for someone to meet me. You can just head on your way.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 91, 'otherescort_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 92, 'otherescort_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 93, 'player_1_1', 'Yes'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 94, 'player_1_2', 'Yes'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 95, 'player_1_3', 'Yes'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 96, 'player_1_4', 'Yes'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 97, 'player_2_1', 'No'),
