('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 100, 'player_2_4', 'No'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 101, 'player_3_1', 'What is the forensics report for?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 102, 'player_3_2', 'Why are you so short handed?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 103, 'player_3_3', 'Why would a spy stay here?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 104, 'player_3_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 105, 'player_4_1', ''),
