('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 123, 'player_more_3_3', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 124, 'player_more_3_4', ''),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 125, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 126, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 127, 'return_waypoint_description_1', 'Returnt to Lian Byrne with the forensics report'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 128, 'return_waypoint_description_2', 'Escort the operative back to Commander Byrne'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 129, 'return_waypoint_description_3', 'Return the intelligence reports to Commander Byrne'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 130, 'return_waypoint_description_4', 'Return to Commander Byrne and inform him of your success.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 131, 'return_waypoint_name_1', 'Lian Byrne'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 132, 'return_waypoint_name_2', 'Lian Byrne'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 133, 'return_waypoint_name_3', 'Lian Byrne'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 134, 'return_waypoint_name_4', 'Commander Byrne'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 135, 'waypoint_description_1', 'Go and pick up the forensics report'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 136, 'waypoint_description_2', 'Go and meet Commander Byrnes operative'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 137, 'waypoint_description_3', 'Track down the Rebel spy and take his intelligence reports'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 138, 'waypoint_description_4', 'Find and eliminate the Rebel guerillas'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 139, 'waypoint_name_1', 'Forensic scientist''s location'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 140, 'waypoint_name_2', 'Undercover operative''s location'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 141, 'waypoint_name_3', 'Rebel spy''s location'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 142, 'waypoint_name_4', 'Rebel commando''s location'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 143, 'npc_reset_2', 'Why don''t you come back once you think you''re ready to finish this job?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 144, 'npc_reset_3', 'Why don''t you come back once you think you''re ready to finish this job?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 145, 'npc_reset_4', 'Why don''t you come back once you think you''re ready to finish this job?'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 146, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 147, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 148, 'player_reset_4', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 149, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 150, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_lian_byrne.stf', 151, 'player_sorry_4', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 1, 'cant_work', 'I have a small task for you when you''re not so busy.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 2, 'dontknowyou_1', 'Imperial business. Move along.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 3, 'dontknowyou_2', 'Vacate this area. Imperial business.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 4, 'gotowork_1', 'I was told you''d be bringing me a fragment of the Death Star. If you have it, give it over.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 5, 'gotowork_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 6, 'next', 'I think the situation here is currently under control.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 7, 'notit_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 8, 'notit_2', 'You were supposed to bring an authorization for me, Ruwan Tokai! Please tell me you''ve got it!'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 9, 'notyet', 'I can''t deal with this right now.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 10, 'npc_1_1', 'I despise the humidity on this world -- so bad for the equipment. I need this piece taken to the warrant officer for analysis. Can you deliver it?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 11, 'npc_1_2', 'Please, you have to help! That piece of the Death Star turned out to be classified above my clearance. I''m up for court martial, just for examining it! You have to get to my commanding officer and get a retroactive authorization.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 12, 'npc_2_1', 'Good. Check back here after the delivery, and I''ll disburse payment from my equipment restoration budget.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 13, 'npc_2_2', 'Great. I''ll pay you for your help. Just bring me that authorization, fast!'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 14, 'npc_3_1', 'Regrettable. Well, let me know if you find any interesting equipment lying around in the jungle.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 15, 'npc_3_2', 'You won''t help out a fellow Imperial in his time of need? What kind of servant of the Empire are you?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 16, 'npc_4_1', 'These materials were never meant for jungle use. This piece, for instance -- I''ve been examining it, but the process of cleaning off the moss also removes vital chemical traces that would help us understand what happened. How frustrating. But as to that delivery -- can you do it?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 17, 'npc_4_2', 'It would say I had permission all along to examine that fragment, even though it was classified above my clearance. We take care of things retroactively all the time. I''ll bet some bureaucrat is even now filing a retroactive authorization to have the Death Star scrapped. But I need my own authorization fast! Will you get it?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 18, 'npc_5_1', 'I believe it''s a fragment of hull plating that crashed onto this moon from the battle station that got destroyed in this vicinity last year. Very interesting technology, I must say. Can you deliver it?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 19, 'npc_5_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 20, 'npc_6_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 21, 'npc_6_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 22, 'npc_backtowork_1', 'I have nothing useful to add. I''d just like you to go and deliver this hull fragment.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 23, 'npc_backtowork_2', 'Please, I don''t know what else to say. I need that retroactive authorization from my commanding officer, or I''m in trouble!'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 24, 'npc_breech_1', 'Are you here with that Death Star fragment?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 25, 'npc_breech_2', 'You''re here for the authorization for Sgt. Tokai?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 26, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 27, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 28, 'npc_failure_1', 'You didn''t deliver that hull fragment? Well, I''ll try to find someone who can.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 29, 'npc_failure_2', 'You didn''t get me that authorization? Oh, no! How will I explain this. It''s Kessel for me.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 30, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 31, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 32, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 33, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 34, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 35, 'npc_more_3_2', '');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 36, 'npc_noloc_1', 'Wait, I''m getting a call from the warrant officer. Check with me in a moment in case his coordinates changed.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 37, 'npc_noloc_2', 'Wait a moment -- I''m getting another call from the investigators. I have to take this. Check with me in a moment.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 38, 'npc_reset_1', 'Well, check back later in case I can''t find someone else to do the job.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 39, 'npc_reward_1', 'I''ve been authorized to disburse this payment. Classified, they said? No one told me that. Hmm. Well, I hope nothing bad happens.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 40, 'npc_reward_2', 'Thanks! I''m paying you out of my own funds. I just remembered you delivered that Death Star fragment to a warrant officer. Hope he''s not in trouble too!'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 41, 'npc_smuggle_1', 'All salvage from the Death Star has been a classified secret. You say a technical sergeant sent this? Hmm. We''ll have to look into his clearances.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 42, 'npc_smuggle_2', 'This little slip-up is understandable. Doesn''t happen unusually often, I''m glad to say. Now you''d better get out of this area -- we''ve seen Rebel activity here.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 43, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 44, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 45, 'npc_work_1', 'Did you deliver that hull fragment of the destroyed battle station to my warrant officer?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 46, 'npc_work_2', 'I need that retroactive authorization from my commanding officer, or I''m in trouble!'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 47, 'otherescort_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 48, 'otherescort_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 49, 'player_1_1', 'Yes.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 50, 'player_1_2', 'Yes.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 51, 'player_2_1', 'No.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 52, 'player_2_2', 'No.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 53, 'player_3_1', 'Why is the humidity bad for the equipment?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 54, 'player_3_2', 'What is a "retroactive authorization"?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 55, 'player_4_1', 'What is this piece?'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 56, 'player_4_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 57, 'player_5_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 58, 'player_5_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 59, 'player_more_1_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 60, 'player_more_1_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 61, 'player_more_2_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 62, 'player_more_2_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 63, 'player_more_3_1', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 64, 'player_more_3_2', ''),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 65, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 66, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 67, 'return_waypoint_description_1', 'This Imperial technical sergeant examined a fragment of the Death Star that turned out to be classified.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 68, 'return_waypoint_description_2', 'The Imperial Technical Sergeant waits for retroactive authorization to have studied a classified fragment of the Death Star.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 69, 'return_waypoint_name_1', 'Sgt. Ruwan Tokai'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 70, 'return_waypoint_name_2', 'Sgt. Ruwan Tokai'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 71, 'waypoint_description_1', 'An Imperial warrant officer waiting for delivery of a fragment of the Death Star.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 72, 'waypoint_description_2', 'An Imperial officer holds retroactive permission for Technical Sergeant Ruwan Tokai to have examined a classified fragment of the Death Star.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 73, 'waypoint_name_1', 'Warrant Officer'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 74, 'waypoint_name_2', 'Tokai Authorization'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 75, 'npc_reset_2', 'Well, check back later in case I can''t find someone else to do the job.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 76, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_massassi_ruwan_tokai.stf', 77, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 1, 'cant_work', 'Come back and see me when you''re finished with your current assignment.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 2, 'dontknowyou_1', 'I''m on Imperial business. On your way.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 3, 'dontknowyou_2', 'This is an Imperial matter. On your way.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 4, 'dontknowyou_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 8, 'next', 'That''s all I''ve got for you now. Check back with me from time to time.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 9, 'notit_1', 'These are not the encrypted orders from Imperial High Command.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 10, 'notit_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 11, 'notit_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 12, 'notyet', 'This isn''t a good time for me.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 13, 'npc_1_1', 'Did High Command send you? We''ve just got some information that we need to move on. Wait, you''re new. Sorry, I''m Sergeant Yith Seenath. I hope you''re here to help out because we could sure use it. I need an Imperial courier intercepted and the orders he''s carrying brought back to me. Think you can do that?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 14, 'npc_1_2', 'Those orders were to be delivered to a particularly brutal lieutenant that''s been stationed here on Yavin recently. Apparently Imperial High Command felt that Commander Byrne was not getting results quickly enough so they sent this brute to ''help things along.'' We need this lieutenant taken out. Is that something you could do?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 15, 'npc_1_3', 'We finally decoded that dispatch from Imperial High Command and as a result we''ve uncovered a munitions depot that was going to be used in an upcoming raid. I want you to blow this place sky high. Think you can handle that?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 16, 'npc_2_1', 'Here are the coordinates. The courier is likely to have an escort, so be prepared for a fight. Good luck.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 17, 'npc_2_2', 'I''d advise you bring some friends along. This lieutenant doesn''t go anywhere without two of his best men accompanying him. Good luck.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 18, 'npc_2_3', 'It''s a small warehouse but I''m sure it will be heavily guarded. After taking out the lieutenant in charge of such operations, I''d be expecting quite a fight. Prepare accordingly.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 19, 'npc_3_1', 'Well then I''ll let you get back to whatever it was you were doing. Farewell.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 20, 'npc_3_2', 'This is a tough assignment. I understand your decision.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 21, 'npc_3_3', 'Very well, I''ll assign this to a more experienced operative. Farewell.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 22, 'npc_4_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 23, 'npc_4_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 24, 'npc_4_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 31, 'npc_backtowork_1', 'Do you want the mission or not?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 32, 'npc_backtowork_2', 'That''s all the information I have. Would you like to reconsider?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 33, 'npc_backtowork_3', 'This is going to be quite challenging. If you''d like to back out, I''ll understand.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 34, 'npc_breech_1', 'That''s close enough! Open fire, men!'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 35, 'npc_breech_2', 'This is a restricted area! Identify yourself! Open fire, men!'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 36, 'npc_breech_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 37, 'npc_dropoff_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 40, 'npc_failure_1', 'Those orders would have clarified quite a few things for us. A shame you couldn''t get them.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 41, 'npc_failure_2', 'We''ll have to find some way to take out that lieutenant. Thanks for your help.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 42, 'npc_failure_3', 'I''ll have to organize another strike team quickly. We can''t afford to let those Imperial commandos have access to those weapons.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 52, 'npc_noloc_1', 'One moment while I verify those coordinates.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 53, 'npc_noloc_2', 'We need to verify the lieutenant''s current position. Could you check back with me in a few moments?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 54, 'npc_noloc_3', 'I need to verify the depot''s location with our scouts. Check back in a few moments.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 55, 'npc_reset_1', 'Fine. Come back later if you think you can finish this out.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 56, 'npc_reward_1', 'Well done. Your efforts will make our work here much easier. Report back if you haven''t gotten your fill of killing Imperials.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 57, 'npc_reward_2', 'Good job. Cut off the head and the body cannot survive. Enjoy your reward.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 58, 'npc_reward_3', 'Now that was a job well done. I think our people will be able to take a breather. You''re an inspiration to us all.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 62, 'npc_takeme_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 65, 'npc_work_1', 'Did you get that dispatch from Imperial High Command?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 66, 'npc_work_2', 'Did you take care of that Imperial lieutenant? Our people will be much safer once he''s gone.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 67, 'npc_work_3', 'Have you taken out that munitions depot yet?'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 68, 'otherescort_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 71, 'player_1_1', 'Yes.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 72, 'player_1_2', 'Yes.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 73, 'player_1_3', 'Yes.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 74, 'player_2_1', 'No.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 75, 'player_2_2', 'No.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 76, 'player_2_3', 'No.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 77, 'player_3_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 78, 'player_3_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 79, 'player_3_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 80, 'player_4_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 81, 'player_4_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 82, 'player_4_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 83, 'player_5_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 84, 'player_5_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 85, 'player_5_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 86, 'player_more_1_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 87, 'player_more_1_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 88, 'player_more_1_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 89, 'player_more_2_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 90, 'player_more_2_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 91, 'player_more_2_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 92, 'player_more_3_1', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 93, 'player_more_3_2', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 94, 'player_more_3_3', ''),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 97, 'return_waypoint_description_1', 'Bring the Imperial dispatch back to Yith Seenath.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 98, 'return_waypoint_description_2', 'Report your success to Yith Seenath.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 99, 'return_waypoint_description_3', 'Report your success to Yith Seenath.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 100, 'return_waypoint_name_1', 'Sergeant Seenath''s Location'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 101, 'return_waypoint_name_2', 'Sergeant Seenath''s Location'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 102, 'return_waypoint_name_3', 'Sergeant Seenath''s Location'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 103, 'waypoint_description_1', 'Get the encrypted orders from the Imperial courier.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 104, 'waypoint_description_2', 'Take out the bloodthirsty lieutenant.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 105, 'waypoint_description_3', 'Destroy the munitions depot.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 106, 'waypoint_name_1', 'Imperial Courier''s Location'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 107, 'waypoint_name_2', 'Imperial Lieutenant''s Location'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 108, 'waypoint_name_3', 'Munitions Depot''s Location'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 109, 'npc_reset_2', 'Fine. Come back later if you think you can finish this out.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 110, 'npc_reset_3', 'Fine. Come back later if you think you can finish this out.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 111, 'player_reset_2', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 112, 'player_reset_3', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 113, 'player_sorry_2', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_rebelcamp_yith_seenath.stf', 114, 'player_sorry_3', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 1, 'cant_work', 'If you''re on the lookout for work, please come see me once your present job is completed.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 2, 'dontknowyou_1', 'I don''t require any assistance, but it''s very kind of you to check on me.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 3, 'dontknowyou_2', 'If you know what''s good for you, you''ll leave. Strangers aren''t welcome here.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 4, 'dontknowyou_3', 'You weren''t invited here. It would be much better if you left and didn''t cause any trouble.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 5, 'gotowork_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 6, 'gotowork_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 7, 'gotowork_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 8, 'next', 'I have given you all the work I can for the moment. This project is far from finished though, so I may have further duties for you later.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 9, 'notit_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 10, 'notit_2', 'This isn''t the part I asked you to get. Did you hand me the wrong item?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 11, 'notit_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 12, 'notyet', 'I don''t have time to salvage and talk to you right now, okay?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 13, 'npc_1_1', 'Salvaging equipment from a destroyed ship that was once the size of a small moon is an unusual job. You''d be surprised at how many working pieces of equipment we find. If you had some time to spare, I could actually use a little help salvaging one of my workers from the wreckage. Can you help me?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 14, 'npc_1_2', 'Just the problem-solver I was hoping to see. One of my workers recently found an extremely valuable hyperdrive component but got jumped by some scavengers before she could bring it back here. She''s recovering in the infirmary, but I''d really like that part back. Will you help me?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 15, 'npc_1_3', 'I''m always for living in peace with my fellow beings but I''ve had about enough! Commander Byrne is blaming me for all of this scavenger activity. I need to put a stop to all this thieving quickly or he''s going to arrest me on conspiracy charges. Can you help me?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 16, 'npc_2_1', 'Good. Let me give you the location where that worker was assigned. Be careful out there. We occasionally have people scavenging around for things they can sell. The guards shoot them on sight so they''re not likely to wait for you to introduce yourself.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 17, 'npc_2_2', 'These scavengers are really starting to become a problem. See if you can find the scavengers that ran off with that component and show them the consequences of assaulting my workers. And don''t forget to bring back the hyperdrive part.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 18, 'npc_2_3', 'What would really help would be if you could find their leader and get rid of him -- or her. Once the leader is gone, the others will probably tear each other apart fighting over the division of spoils.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 19, 'npc_3_1', 'Then I must bid you farewell and attend to this matter.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 20, 'npc_3_2', 'I''d better find somebody else to look for it then. Good luck to you.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 21, 'npc_3_3', 'Did Byrne tell you not to help me? Why does he hate me so much?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 22, 'npc_4_1', 'Commander Byrne only tolerates my presence here because I do the job so well. I was hoping you might be willing to go and track down one of my missing workers before it comes to his attention. It would be a big help. How about it?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 23, 'npc_4_2', 'Certain pieces of equipment are more expensive to replace than others. This ship had the best equipment that credits could buy. Byrne will be slavering to get his hands on this piece. What do you say?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 24, 'npc_4_3', 'Ideally by ejecting Commander Byrne into a black hole -- I''m kidding, please don''t tell him I said that. If you could find some of these scavengers and eliminate them, it would be a tremendous help. Will you do it?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 25, 'npc_5_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 26, 'npc_5_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 27, 'npc_5_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 28, 'npc_6_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 29, 'npc_6_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 30, 'npc_6_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 31, 'npc_backtowork_1', 'I don''t have any more information. Was there something else? '),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 32, 'npc_backtowork_2', 'Is there something you''re trying to tell me?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 33, 'npc_backtowork_3', 'I have no answers for any questions you might have. I only hope you haven''t changed your mind.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 34, 'npc_breech_1', 'Were you looking for me? '),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 35, 'npc_breech_2', 'Maybe we can salvage something off you too. '),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 36, 'npc_breech_3', 'This is what happens to intruders.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 37, 'npc_dropoff_1', 'Thanks for bringing me back. I''m glad you were there to take care of those scavengers.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 38, 'npc_dropoff_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 39, 'npc_dropoff_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 40, 'npc_failure_1', 'Commander Byrne is going to have my head if he gets wind of this.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 41, 'npc_failure_2', 'How very disappointing. I wonder if Byrne has anything to do with all these scavengers.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 42, 'npc_failure_3', 'Byrne will never let me leave this world a free citizen. I''ve lost everything.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 43, 'npc_more_1_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 44, 'npc_more_1_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 45, 'npc_more_1_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 46, 'npc_more_2_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 47, 'npc_more_2_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 48, 'npc_more_2_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 49, 'npc_more_3_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 50, 'npc_more_3_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 51, 'npc_more_3_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 52, 'npc_noloc_1', 'Give me a few minutes to find out which sector that worker was supposed to be in. I should have it around here somewhere.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 53, 'npc_noloc_2', 'I should at least get you the coordinates where my worker got jumped. That will be a good place to start looking for those scavengers. Come back in a few minutes.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 54, 'npc_noloc_3', 'I need to prepare myself in case the worst occurs. Would you mind leaving me for a few minutes? We''ll begin when you return.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 55, 'npc_reset_1', 'If you wish, return to me later and complete my tasks when you feel better prepared.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 56, 'npc_reward_1', 'I''m very relieved that this has worked out so well. I hope you''ll stay around for a while. '),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 57, 'npc_reward_2', 'Byrne will have to cut me a little slack after this. I know he''ll hate that. How wonderful.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 58, 'npc_reward_3', 'You found the leader? Oh thank you, my friend. Perhaps that will buy enough time for me to finish this job and get out of here in one piece.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 59, 'npc_smuggle_1', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 60, 'npc_smuggle_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 61, 'npc_smuggle_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 62, 'npc_takeme_1', 'I found some really interesting pieces over here. Possibly from other kinds of ships that were caught in the explosion. Oh, I hadn''t realized it was this late. Now where did I leave my caller?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 63, 'npc_takeme_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 64, 'npc_takeme_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 65, 'npc_work_1', 'Perhaps I did not adequately stress the urgency in this situation. Would you please find my worker quickly?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 66, 'npc_work_2', 'Have you managed to locate those scavengers and get that hyperdrive part yet?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 67, 'npc_work_3', 'Have you found the leader of those scavengers yet? Commander Byrne isn''t a patient man. He may arrest me if you don''t hurry.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 68, 'otherescort_1', 'I don''t require any assistance, but it''s very kind of you to check on me.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 69, 'otherescort_2', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 70, 'otherescort_3', ''),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 71, 'player_1_1', 'Yes'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 72, 'player_1_2', 'Yes'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 73, 'player_1_3', 'Yes'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 74, 'player_2_1', 'No'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 75, 'player_2_2', 'No'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 76, 'player_2_3', 'No'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 77, 'player_3_1', 'Could you clarify that a little?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 78, 'player_3_2', 'What''s so special about this part?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 79, 'player_3_3', 'How can I help?'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 80, 'player_4_1', ''),
