('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 95, 'player_reset_1', 'I don''t want this mission right now.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 96, 'player_sorry_1', 'I''ll keep working on the mission.'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 97, 'return_waypoint_description_1', 'Escort the salvage worker back to Megan Dr''lar'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 98, 'return_waypoint_description_2', 'Return the hyperdrive part to Megan Dr''lar'),
('string/en/static_npc/yavin/yavin_salvagecamp_megan_drlar.stf', 99, 'return_waypoint_description_3', 'Return to Megan Dr''lar with news of your success.'),
