('string/en/stat_d.stf', 323, 'frs_light_vigilance', 'Vigilance modifies Jedi special attacks so that they damage Force power.'),
('string/en/stat_d.stf', 324, 'frs_light_wisdom', 'Wisdom modifies Jedi special attacks so that they drain the attribute pools of a non-Jedi (or Jedi depleted of Force power) and transfer them to the wielder.'),
('string/en/stat_d.stf', 325, 'frs_light_serenity', 'Serenity temporarily weakens the attributes of those who attack the Jedi.'),
('string/en/stat_d.stf', 326, 'frs_dark_envy', 'Envy modifies Jedi special attacks so that they damage Force power and return some of it to the wielder.'),
