('string/en/texture_kit.stf', 1, 'btn_texture', 'Change Texture'),
('string/en/texture_kit.stf', 2, 'pick_a_ship_title', 'Select a Ship'),
('string/en/texture_kit.stf', 3, 'pick_a_ship', 'Please select a ship to change the texture of.'),
('string/en/texture_kit.stf', 4, 'changed_paint_job', 'Re-texturing completed.'),
('string/en/texture_kit.stf', 5, 'imperial', 'This is an Imperial ship, and cannot be re-textured.'),
('string/en/texture_kit.stf', 6, 'inspace', 'You cannot re-texture a ship while you are in space!'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 1, 'coordinator_rebel_response', 'I have nothing to say to those who have dealings with rebel scum. I suggest you move along before you find yourself in a hail of blaster fire!'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 2, 'm1_begin', 'A rebel agent stole some very important documents concerning the Dead Eye project. We would like to stop this information from falling into the wrong hands. Would you like to help?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 3, 'm1_begin_info1', 'Who is this agent?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 4, 'm1_begin_info1_response', 'Her codename is Skimmer. Her whereabouts are unknown. She joined the rebellion after both her father and brother were killed during earlier campaigns waged against the Empire.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 5, 'm1_begin_info2', 'What is the Dead Eye Project?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 6, 'm1_begin_info2_response', 'That information is need-to-know only and you don''t need to know. Be assured that success of project Dead Eye is extremely important to the Empire.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 7, 'm1_begin_yes', 'I would like to help.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 8, 'm1_begin_yes_response', 'We have an informant that has intercepted a rebel communication outlining their next move. Speak with the informant and return to me. I have added a waypoint to your data pad.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 9, 'm1_begin_no', 'No thanks.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 10, 'm1_begin_no_response', 'Very well. If you change your mind, come back and we''ll talk.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 11, 'm1_active', 'Have you spoken with the informant yet? This information is vital to the Empire.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 12, 'm1_active_working', 'I''ll speak with the informant immediately.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 13, 'm1_active_working_response', 'Good. Carry on.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 14, 'm1_active_restart', 'Are you sure those coordinates were correct?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 15, 'm1_active_restart_response', 'It looks as though the informant has moved. Here, I''ve updated his current location into your datapad.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 16, 'm1_active_abort', 'I don''t have time for this right now.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 17, 'm1_active_abort_response', 'I''m sorry to hear that. Perhaps we can find someone else for the job.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 18, 'm1_informant', 'So you''re the one the coordinator sent to relay the message, huh? The Empire must be getting desperate!'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 19, 'm1_informant_report', 'What have you learned?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 20, 'm1_informant_report_response', 'It seems the rebels are planning on slicing an Imperial Communications terminal in order to deliver a message to someone. I wasn''t able to find out who the message was for though.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 21, 'm1_informant_reprimand', 'Words like that can land you in hot water.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 22, 'm1_informant_reprimand_response', 'Hey, I was just joking with you! I hold the empire in the highest esteem as everyone knows.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 23, 'm1_informant_invalid', 'I said, what are you looking at? If I wanted to chat, I would have baked up wastril bread and we''d be having a tea party by now! I don''t have any tea, so that''s out of the question. Now get!'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 24, 'm2_begin', 'We need to prevent that encoded message from being transmitted and retrieve it. Are you ready to get your hands dirty?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 25, 'm2_begin_info1', 'Get my hands dirty?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 26, 'm2_begin_info1_response', 'That''s just an expression. Lethal force is authorized considering the sensitive nature of this case. You don''t need to worry about any legal repercussions.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 27, 'm2_begin_yes', 'I''ll do what is necessary.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 28, 'm2_begin_yes_response', 'Go to the slicer''s location and recover the encoded message using any means. If you''re not skilled in combat, bring some help. Return when you''ve retrieved the encoded message.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 29, 'm2_begin_no', 'I''m not so sure I''m up to this.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 30, 'm2_begin_no_response', 'That''s alright. This sort of work is not for everyone. Come on back if you change your mind though.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 31, 'm2_active', 'Back again? Don''t tell me you''re getting cold feet. We have to stop that slicer and intercept that message before he''s able to transmit it.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 32, 'm2_active_working', 'I''ll stop the slicer and get the encoded message.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 33, 'm2_active_working_response', 'That''s the spirit. Now get moving!'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 34, 'm2_active_restart', 'I was unable to locate the slicer.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 35, 'm2_active_restart_response', 'We received intelligence that the slicer was on the move after you had left. We have his new location and I''ve updated the new location to your datapad.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 36, 'm2_active_abort', 'I can''t do this right now.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 37, 'm2_active_abort_response', 'That''s too bad. If you change your mind, please feel free to come back later.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 38, 'm1_informant_taunt', 'Just what are you looking at?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 39, 'm2_slicer_taunt', ''),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 40, 'm3_begin', 'We need to get that encoded message to the commander. Would you be willing to make the delivery?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 41, 'm3_begin_yes', 'I will make the delivery.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 42, 'm3_begin_yes_response', 'Excellent! The commander is currently off world. I''ve uploaded his location to your datapad. Deliver the encoded message to him at once.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 43, 'm3_begin_no', 'I don''t have time for this right now.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 44, 'm3_begin_no_response', 'In that case, come back whenever your busy schedule allows.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 45, 'm3_active', 'You''re still here? I''ve already contacted the Commander so he''s expecting you. He''s not the type of man you want to keep waiting.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 46, 'm3_active_working', 'I''m leaving on the next flight out.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 47, 'm3_active_working_response', 'Glad to hear it. I''m sure he will be very pleased.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 48, 'm3_active_restart', 'I seem to have lost the Commander''s location.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 49, 'm3_active_restart_response', 'These missions are not to be taken lightly! Please be more careful next time. Here, I''ve uploaded the waypoint to your datapad once again.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 50, 'm3_active_abort', 'I need to do something else right now.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 51, 'm3_active_abort_response', 'How unfortunate. If you have time later on, please see me again. I hope the commander understands for both of our sakes.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 52, 'm3_finish', 'You''ve done well and I commend you for your admirable service to the Empire. There is nothing more I need of you at this time.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 53, 'm4_finish_incomplete', 'Hello citizen, if you''re looking to do some work for the Empire you should contact one of our Imperial Coordinators. Coordinators have been dispatched to Talus, Naboo, Tatooine, Corellia and Rori. I don''t need anything from you right now but our coordinators could certainly use your help.\n'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 54, 'm5_begin_declared', 'Dr. Vacca has been working with Drall on project Dead Eye. We have been very tolerant so far. However, some of them have made statements against the Empire. We need a message sent.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 55, 'm5_begin_deadeye', 'What is project Dead Eye?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 56, 'm5_begin_deadeye_response', 'The details of project Dead Eye are none of your concern. Just know that the success of this project is of the utmost importance for the Empire.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 57, 'm5_begin_drall', 'What do the Drall have to do with this?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 58, 'm5_begin_drall_response', 'The Drall have great knowledge of pharmaceuticals. Vacca believes their assistance is invaluable, so we''ve tolerated their presence. But open dissent is a threat to the project.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 59, 'm5_begin_vacca', 'Who is Dr. Vacca?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 60, 'm5_begin_vacca_response', 'Dr. Vacca is the lead of project Dead Eye. He is very valuable to us. He does have a bit of history though, so we have been keeping a very close eye on him.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 61, 'm5_begin_message', 'What is the message?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 62, 'm5_begin_message_response', 'Vacca needs to know what can happen if he chooses to cross the Empire. Killing a few of his Drall friends who have expressed open distain for the Empire should be message enough.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 63, 'm5_begin_yes', 'I''ll complete your task.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 64, 'm5_begin_yes_response', 'Good. A group of Drall are on this planet collecting samples. Go to these coordinates and destroy every one you find there. Killing some of his Drall friends will let Vacca know what can happen should he cross the Empire. Be warned. These Drall are suspected of having Rebel support and attacking a Rebel base will leave you open to retaliation from other declared rebel forces for short time. Be on your guard.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 65, 'm5_begin_no', 'I''m not up to this now.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 66, 'm5_begin_no_response', 'If you decide to change you mind come back and let me know. You just may earn yourself a medal for your distinguished service.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 67, 'm5_begin_undeclared', 'I''m sorry, this mission is too sensitive to entrust to just anyone. If you decide to officially declare your faction affiliation with the Empire, come back and we''ll talk.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 68, 'm5_active', 'You haven''t done as I''ve asked. You are to go to that encampment of anti-imperialist Drall and exterminate them. The waypoint is already in your datapad. Do not fail me.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 69, 'm5_active_working', 'I''ll get right on it.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 70, 'm5_active_working_response', 'Good. Get out there and finish the job. Success in this mission will earn you the gratitude of the Empire.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 71, 'm5_active_restart', 'Are you sure this waypoint is correct?'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 72, 'm5_active_restart_response', 'Hmm. It is possible that the data was faulty. I will upload the information to your datapad once again. Done. Now move out and finish the job.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 73, 'm5_active_abort', 'I can''t do this right now.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 74, 'm5_active_abort_response', 'I usually do not tolerate failure. I will overlook it this time given your history of diligent service to the Empire. You are relieved of your obligation. Return if you change your mind.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 75, 'm5_finish', 'The Empire owes you deep gratitude. Rebel meddling has been prevented and Dead Eye will continue on schedule without dissention. There is nothing more we need from you at this time.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 76, 'commander_rebel_response', 'We know all about your dealings with those rebel terrorists. You''re lucky I don''t order your execution right now where you stand. Now get out of here!'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 77, 'disk_title', 'Rebel Alliance Message'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 78, 'disk_text', 'Dr. Vacca, \n\nI am writing to you not only as a friend, but as a fellow citizen of Alderaan with a plea for your help. Years ago your research was used to enrich the lives of the people on our homeworld. Lives that were cut short by the treachery of an Emperor bent on total domination by any means necessary.\n\n\nIn opposition to the Emperor''s rule is an Alliance of systems that seeks only to bring back the peace and harmony that governed our galaxy for thousands of years. We fight against the fear and disinformation that is used to oppress thousands of worlds\n\nIn this dire time, the Alliance needs your help. We have learned of your Dead Eye project and fear that if the Empire is able to implement it, more innocent civilians will perish. Alderaan has shown us that the Empire can not be trusted with any type of new military technology.\n\nNow is a time of decision. The Empire will undoubtedly try to scare you into compliance by threatening you or your friends. We offer an alternative. We offer a life free of guilt and the knowledge that you are working to right the wrongs that have plagued so many for so long. \n\nWe both lost friends, family and heritage when the Empire brutally and callously destroyed Alderaan, a world devoted only to peace. It is a crime that cannot be left unanswered. Decide with your heart and with your conscience to help us defeat those who took so much from us both.\n\nPlease help us, Dr. Vacca. Join with the Rebel Alliance before the decision is taken from you. We know you will make the correct choice and await your response.\n\nPrincess Leia Organa'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 79, 'm4_finish', 'You''ve done well. I''ll see to it that our cryptologists get to decoding this right away. If you are willing, there is one final task I''d like completed.'),
('string/en/theme_park/alderaan/act2/imperial_missions.stf', 80, 'm3_failed', 'Where''s the disk? Did you leave it on the body? Unbelievable. Listen, Bantha brains, that disk is gone, but there may be another slicer you can intercept. Here''s the waypoint. Try to remember to loot the body this time.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 1, 'coordinator_imperial_response', 'You seem to be more interested in helping the Empire. Why don''t you come back when you''ve come to your senses.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 2, 'm1_begin', 'I hope you''re here to help. We''re stretched thin looking for Skimmer.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 3, 'm1_begin_info1', 'What''s going on?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 4, 'm1_begin_info1_response', 'We''re trying to locate one of our operatives code named Skimmer and we have a lot of tips to follow up. It has to do with this Dead Eye project we''ve been hearing about.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 5, 'm1_begin_yes', 'I''d like to help.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 6, 'm1_begin_yes_response', 'Great! We think Skimmer may have recently contacted one of her close friends. Go to these coordinates and see of Skimmer has been in touch and report back here with any information you uncover.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 7, 'm1_begin_no', 'I''m not ready to help yet.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 8, 'm1_begin_no_response', 'I''m sorry to hear that. Skimmer''s stumbled onto something big. If you change your mind, let me know.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 9, 'm1_active', 'Have you talked to Skimmer''s friend yet?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 10, 'm1_active_working', 'I''m still looking for her.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 11, 'm1_active_working_response', 'Time''s of the essence here, so do your best.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 12, 'm1_active_abort', 'I''m not going to be able to finish the mission.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 13, 'm1_active_abort_response', 'I understand. Come find me if you change your mind. We need a lot of help on this one.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 14, 'm1_active_restart', 'I need my mission profile updated.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 15, 'm1_active_restart_response', 'Very well. I''ve uploaded our latest intel to your datapad. You should be able to continue your mission now. May the Force be with you.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 16, 'm1_finish_encoded', 'Good Work! Wait a pulse, this disk has been locked with an old Imperial code! We have schematics for this model of coder, but the parts are obsolete. I bet only local gangs or scavengers would have some of this stuff. I''ll give you the schematics, but you''ll have to locate the parts and put a decoder together before we can read this intel. Report back to me when you have the disk decoded.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 17, 'm1_finish_decoded', 'Good work. We''ll analyze this information and decide on a plan. Come back in a little while and we''ll have more information for you.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 18, 'rebel_friend_response', 'You''re from the Alliance? Oh good. Lyda...I mean, Skimmer, told me that someone from the Alliance might try to contact me. She gave me this disk in case something happened to her but it''s encoded. She said the Alliance would be able to crack it.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 19, 'm2_begin', 'Excellent. This message is from Skimmer. She''s hiding outside the city and says she has information on Dead Eye. Can you head to these coordinates and make sure she''s still there? We don''t want to send a team to a place she left twelve cycles ago.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 20, 'm1_refused', 'I hope you''ve changed your mind and can help us out. We need every loyal operative we can find right now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 21, 'm1_refused_info1', 'What''s going on?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 22, 'm1_refused_info1_response', 'We''re trying to locate one of our operatives code named Skimmer and we have a lot of tips to follow up. It has to do with this Dead Eye project we''ve been hearing about.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 23, 'm1_refused_yes', 'I''d like to help.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 24, 'm1_refused_yes_response', 'Great! We think Skimmer may have recently contacted one of her close friends. Go to these coordinates and see of Skimmer has been in touch and report back here with any information you uncover.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 25, 'm1_refused_no', 'I''m not ready to help yet.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 26, 'm1_refused_no_response', 'I''m sorry to hear that. Skimmer''s stumbled onto something big. If you change your mind, let me know.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 27, 'm2_begin_encoded', 'I''m very busy coordinating missions. Unless you have a decoded Dead Eye data disk for me, there''s not much to discuss. Come back when you''ve decoded it.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 28, 'm2_begin_yes', 'I''ll go find her.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 29, 'm2_begin_yes_response', 'Excellent. Make sure she''s still there and then report back to me.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 30, 'm2_begin_info1', 'What do you know about Skimmer?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 31, 'm2_begin_info1_response', 'Not much. She''s related to two Alliance pilots who died flying for us. Her brother was on Alderaan when it was destroyed by the Empire. Later her father was killed during the assault on the Death Star. I just hope he got a chance to know it was destroyed before his Y-wing was blown up.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 32, 'm2_begin_info2', 'What do you think of this Dead Eye project?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 33, 'm2_begin_info2_response', 'Don''t know. Not much data on it yet. All I know is that I don''t want the Imperials to be any more accurate than they already are. I''d like to get Dr. Vacca on our side if we could.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 34, 'm2_begin_no', 'I don''t have the time to do that now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 35, 'm2_begin_no_response', 'I understand. If you change your mind, come find me.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 36, 'm2_refused', 'I hope you''ve changed your mind about helping us find Skimmer. She''s still out there somewhere and we need to find her before the Imperials do.  Are you willing to help?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 37, 'm2_refused_yes', 'I''ll go find her.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 38, 'm2_refused_yes_response', 'Excellent. Make sure she''s still there and then report back to me.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 39, 'm2_refused_info1', 'What do you know about Skimmer?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 40, 'm2_refused_info1_response', 'Not much. She''s related to two Alliance pilots who died flying for us. Her brother was on Alderaan when it was destroyed by the Empire. Later her father was killed during the assault on the Death Star. I just hope he got a chance to know it was destroyed before his B-wing was blown up.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 41, 'm2_refused_info2', 'What do you think of this Dead Eye project?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 42, 'm2_refused_info2_response', 'Don''t know. Not much data on it yet. All I know is that I don''t want the Imperials to be any more accurate than they already are. I''d like to get Dr. Vacca on our side if we could.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 43, 'm2_refused_no', 'I don''t have the time to do that now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 44, 'm2_refused_no_response', 'I understand. If you change your mind, come find me.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 45, 'm2_active', 'Have you found skimmer yet?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 46, 'm2_active_working', 'Not yet. I''m working on it.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 47, 'm2_active_working_response', 'The imperials are after her, so don''t waste any time.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 48, 'm2_active_abort', 'I''m not going to be able to finish the mission.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 49, 'm2_active_abort_response', 'I understand. Come find me if you change your mind. We need a lot of help on this one.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 50, 'm2_active_restart', 'I think I need updated intel.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 51, 'm2_active_restart_response', 'Things change out in the field. I''ll upload our latest information to your datapad. Done. You''ve got our latest information. Good luck.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 52, 'm2_finish', 'Lyda''s alive? Thank the stars. We''ll send out a team to get her right away. You do good work. If you''re up for it we need someone to deliver this disk and report to one of our Rebel Commanders about Lyda and project Dead Eye.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 53, 'm2_finish_yes', 'I''m up for anything'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 54, 'm2_finish_yes_response', 'Good. I''ll give you the coordinates of the Commander''s current location. Bring him the disk and he''ll take over from there.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 55, 'm2_finish_no', 'I can''t help you right now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 56, 'm2_finish_no_response', 'I''m sorry to hear that. If you change your mind, come back. I''ll have something for you.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 57, 'm3_begin', 'If you''re available we still need someone to bring this information about Lyda and Dead Eye to our commander. He may have another mission for you if you''re willing to do some traveling.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 58, 'm3_begin_yes', 'I''m up for anything.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 59, 'm3_begin_yes_response', 'Good. I''ll give you the coordinates of the Commander''s current location. Bring him the disk and he''ll take over from there.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 60, 'm3_begin_no', 'I can''t help you right now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 61, 'm3_begin_no_response', 'I''m sorry to hear that. If you change your mind, come back. I''ll have something for you.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 62, 'm3_active', 'Have you finished the mission yet?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 63, 'm3_active_working', 'Not yet. I''m working on it.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 64, 'm3_active_working_response', 'Keep up the good work. We''re counting on you.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 65, 'm3_active_abort', 'I''m not able to do this mission now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 66, 'm3_active_abort_response', 'That''s too bad. Come back when you are able to help the cause.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 67, 'm3_active_restart', 'I need the location of the Commander again'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 68, 'm3_active_restart_response', 'Data pad troubles? That happens I suppose. I''ll give you updated coordinates, but don''t lose it again.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 69, 'm3_finish', 'I heard from the Commander that you were able to find him. I hope the mission went well. We could use some good news around here.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 70, 'm4_finish', 'You''ve got info on Lyda and Dead Eye? We''ve been waiting for you! We''ll process the data and comm the Princess to see how to proceed! Talk to me in a little bit. We might have one final mission for you.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 71, 'm4_finish_incomplete', 'I''m sorry I don''t have time to talk to you now. Why don''t you go find one of our Rebel Coordinators? They may have something for you to do.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 72, 'm5_begin', 'Oh yes, you''re the one who found Lyda. We''re all glad she''s safe. It''s only right that you take on the last part of this operation. Are you up for it?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 73, 'm5_begin_undeclared', 'The information you delivered is significant. Unfortunately, we can''t trust the next part of the operation to anyone who hasn''t officially joined the Alliance. Securing Dr. Vacca''s cooperation is too important to give to just anyone.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 74, 'm5_begin_yes', 'I want to finish what I started.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 75, 'm5_begin_yes_response', 'Excellent. The Princess wants us to deliver this coded message to Dr. Vacca to convince him to join the Alliance. To do so, you''ll need to take over an Imperial relay station and use this interface override device to send the message. Be warned, when you attack the station''s guards, you will be a target for any other Imperial in the galaxy. Be sure you want to do this. May the Force Be With You.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 76, 'm5_begin_info1', 'How is Lyda doing?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 77, 'm5_begin_info1_response', 'Fine, but headstrong as ever. She is already requesting more assignments. She should be careful what she wishes for. This isn''t her first time jumping to light speed without checking her charts.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 78, 'm5_begin_no', 'I don''t think I''m ready yet.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 79, 'm5_begin_no_response', 'If you change your mind come see me, but time is running out.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 80, 'm5_refused', 'You''re still here? Look, I don''t have a lot of time for you unless you have decided to help us with this mission. I know you''ve done a lot for us already. But I need to know, are you onboard or not?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 81, 'm5_refused_yes', 'I want to finish what I started.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 82, 'm5_refused_yes_response', 'Excellent. The Princess wants us to deliver this coded message to Dr. Vacca to convince him to join the Alliance. To do so, you''ll need to take over an Imperial relay station and use this interface override device to send the message. Be warned, when you attack the station''s guards, you will be a target for any other Imperial in the galaxy. Be sure you want to do this. May the Force Be With You.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 83, 'm5_refused_info1', 'How is Lyda doing?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 84, 'm5_refused_info1_response', 'Fine, but headstrong as ever. She is already requesting more assignments. She should be careful what she wishes for. This isn''t her first time jumping to light speed without checking her charts.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 85, 'm5_refused_no', 'I don''t think I''m ready yet.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 86, 'm5_refused_no_response', 'If you change your mind come see me, but time is running out.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 87, 'm5_active', 'Have you sent the message yet?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 88, 'm5_active_working', 'Not yet. I''m working on it.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 89, 'm5_active_working_response', 'Do what you have to. This one is important to the Princess.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 90, 'm5_active_abort', 'I''m not able to do this mission now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 91, 'm5_active_abort_response', 'That''s too bad. Come back when you''re able to help out.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 92, 'm5_active_restart', 'I need to get my mission profile updated.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 93, 'm5_active_restart_response', 'I''ve uploaded the most recent intel we have on the relay facility. You should be able to find it now.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 94, 'm5_finish', 'I''m glad you made it back here. I wanted to thank you personally for your hard work on this. If Dr. Vacca can be persuaded to join the Rebellion, it will make a huge impact on the war. Good job.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 95, 'commander_imperial_response', 'You''ve got a lot of nerve trying to talk to me. You think we don''t know how much you''ve done for the Empire? You better leave unless you like the thought of spending your golden years floating in bacta.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 96, 'm2_lydasaved', 'Thanks for the assist. I thought I was bantha fodder for sure that time. The Empire must have a reward out for me. If you''re here you got my message to the Alliance. Thanks. I owe you two, I guess.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 97, 'm2_lydasaved_info1', 'What happened on your mission?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 98, 'm2_lydasaved_info1_response', 'I''d been assigned some safe, boring undercover work. Just watch and report on troop movements at an Imperial signals facility. One night this file got routed to my station. It looked important, so I stole Wes''s...uh...my supervisor''s security cylinder to decode it and make a copy. It was a little outside my mission profile, but it seemed important.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 99, 'm2_lydasaved_info1a', 'That file was about Dead Eye?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 100, 'm2_lydasaved_info1a_response', 'It was all about Dead Eye. A report on the project and Dr. Vacca''s past. Not enough to duplicate the process, just how it works and some details like the fact that it uses some rare plant that used to grow on Alderaan.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 101, 'm2_lydasaved_info2', 'How did your cover get blown?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 102, 'm2_lydasaved_info2_response', 'Well, I had become close friends with one of the Imperial officers. When they discovered his security cylinders were used to access the Dead Eye plans, he knew I was the only one who could have taken them. I''m pretty sure he had to turn me in or they would think he was a spy.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 103, 'm2_lydasaved_info2a', 'Did this officer know you''re a Rebel?'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 104, 'm2_lydasaved_info2a_response', 'Not a chance. He''s a good man who joined the Empire before he realized what kind of people they are. If he turned me in, it was only because he had no choice. I''m sure of it. I even think he might be willing to help the rebellion once his tour''s up.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 105, 'm2_lydasaved_done', 'I have to go and tell the Alliance you''re all right.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 106, 'm2_lydasaved_done_response', 'Good. Report back to the Rebel Coordinator who sent you here that I''m ready to come back in. You will be told what to do next.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 107, 'm1_sympathizer_greeting', 'You''re from the Alliance? Oh good. Lyda... I mean, Skimmer, told me that someone from the Alliance might try to contact me. She gave me this disk in case something happened to her but it''s encoded. She said the Alliance would be able to crack it.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 108, 'disk_decoded_title', 'Dead Eye Disk [decoded]'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 109, 'disk_decoded_text', '--ALLIANCE EYES ONLY: I apologize for using such an obscure encryption scheme. This was the only crypto I had available and I can''t allow the interception of this message. I don''t think I can avoid capture. It''s only a matter of time before I''m spotted. I''ve never seen so many stormtroopers! In fact, I''m a little bit flattered that I''ve caused this much commotion. \n\nThis is what I''ve found about the project. Dead Eye is a powerful drug developed by an Alderaanian named Dr. Vacca. By improving eyesight, increasing hand eye coordination and reducing scope drift it grants deadly aim to those under its influence. Through Dead Eye, the Empire hopes to turn even the lowliest grunt into a super soldier. A new recruit will be as accurate as a combat veteran. \n\nIt doesn''t take a lot of imagination to envision the results of facing an army that rarely misses a shot. We face a very serious peril. Vacca must hold no love for the Empire and I''m certain the destruction of Alderaan still weighs bitterly on his mind. I''m sure we can turn him to our side and we must or all of the sacrifices we''ve made so far will have been in vain. Tell mom I love her. SKIMMER.'),
('string/en/theme_park/alderaan/act2/rebel_missions.stf', 110, 'disk_encoded_title', 'Dead Eye Disk [encoded]');
