('string/en/theme_park_detail.stf', 42, 'oola', 'oola\n'),
('string/en/theme_park_detail.stf', 43, 'prefect_talmont', 'prefect talmont\n'),
('string/en/theme_park_detail.stf', 44, 'r2d2', 'r2d2\n'),
('string/en/theme_park_detail.stf', 45, 'ree_yees', 'ree yees\n'),
