('string/en/theme_park_imperial/darth_vader.stf', 120, 'npc_takeme_2', ''),
('string/en/theme_park_imperial/darth_vader.stf', 121, 'npc_takeme_3', ''),
('string/en/theme_park_imperial/darth_vader.stf', 122, 'npc_takeme_4', ''),
('string/en/theme_park_imperial/darth_vader.stf', 123, 'npc_takeme_5', ''),
('string/en/theme_park_imperial/darth_vader.stf', 124, 'npc_takeme_6', ''),
('string/en/theme_park_imperial/darth_vader.stf', 125, 'npc_work_1', 'Report your news.'),
('string/en/theme_park_imperial/darth_vader.stf', 126, 'npc_work_2', 'What do you require?'),
('string/en/theme_park_imperial/darth_vader.stf', 127, 'npc_work_3', 'Why do you bother me, agent?'),
('string/en/theme_park_imperial/darth_vader.stf', 128, 'npc_work_4', 'Why do you disturb me?'),
('string/en/theme_park_imperial/darth_vader.stf', 129, 'npc_work_5', 'What do you need?'),
('string/en/theme_park_imperial/darth_vader.stf', 130, 'npc_work_6', 'Why do you bother me?'),
('string/en/theme_park_imperial/darth_vader.stf', 131, 'otherescort_1', ''),
('string/en/theme_park_imperial/darth_vader.stf', 132, 'otherescort_2', ''),
('string/en/theme_park_imperial/darth_vader.stf', 133, 'otherescort_3', ''),
('string/en/theme_park_imperial/darth_vader.stf', 134, 'otherescort_4', ''),
('string/en/theme_park_imperial/darth_vader.stf', 135, 'otherescort_5', ''),
('string/en/theme_park_imperial/darth_vader.stf', 136, 'otherescort_6', ''),
('string/en/theme_park_imperial/darth_vader.stf', 137, 'player_1_1', 'Yes, Lord Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 138, 'player_1_2', 'I shall do so at once, Lord Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 139, 'player_1_3', 'As you wish, Lord Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 140, 'player_1_4', 'Yes, Lord Vader. What will you need of me?'),
('string/en/theme_park_imperial/darth_vader.stf', 141, 'player_1_5', 'As you wish, Lord Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 142, 'player_1_6', 'I will leave at once, Lord Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 143, 'player_2_1', 'I cannot do this for you, Lord Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 144, 'player_2_2', 'I am unable to comply with this order.'),
('string/en/theme_park_imperial/darth_vader.stf', 145, 'player_2_3', 'I am unable to do this, Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 146, 'player_2_4', 'I cannot do this, Lord Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 147, 'player_2_5', 'I will not do so, Vader.'),
('string/en/theme_park_imperial/darth_vader.stf', 148, 'player_2_6', 'I will not destroy a family for the Empire.'),
('string/en/theme_park_imperial/darth_vader.stf', 149, 'player_3_1', 'Why is this one Rebel so important?'),
('string/en/theme_park_imperial/darth_vader.stf', 150, 'player_3_2', 'Who is this agent I am to meet?'),
('string/en/theme_park_imperial/darth_vader.stf', 151, 'player_3_3', 'What is this Rebel charged with?'),
('string/en/theme_park_imperial/darth_vader.stf', 152, 'player_3_4', 'Why is the Empire dealing with Black Sun?'),
('string/en/theme_park_imperial/darth_vader.stf', 153, 'player_3_5', 'What was false about the information?'),
('string/en/theme_park_imperial/darth_vader.stf', 154, 'player_3_6', 'Who is this Obi-Wan?'),
('string/en/theme_park_imperial/darth_vader.stf', 155, 'player_4_1', ''),
