('string/en/theme_park_imperial/emperor.stf', 215, 'player_reset', 'My lord, I cannot do this any longer.'),
('string/en/theme_park_imperial/emperor.stf', 216, 'player_sorry', 'I am sorry, my lord. I was just preparing for my assignment.'),
('string/en/theme_park_imperial/emperor.stf', 217, 'return_waypoint_description_1', 'Bring the thug to the Emperor. Safely.'),
('string/en/theme_park_imperial/emperor.stf', 218, 'return_waypoint_description_2', 'Emperor Palpatine has commanded you to return when you are done.'),
('string/en/theme_park_imperial/emperor.stf', 219, 'return_waypoint_description_3', 'You are expected to give a report to the Emperor'),
('string/en/theme_park_imperial/emperor.stf', 220, 'return_waypoint_description_4', 'Return with the handmaiden. The Emperor expects from you a prompt return.'),
('string/en/theme_park_imperial/emperor.stf', 221, 'return_waypoint_description_5', 'Return to the Emperor now that you have killed all the witnesses.'),
('string/en/theme_park_imperial/emperor.stf', 222, 'return_waypoint_description_6', 'Return to the Emperor to give him the good news.'),
('string/en/theme_park_imperial/emperor.stf', 223, 'return_waypoint_description_7', 'Return to the Emperor now to see his plan come to completion.'),
('string/en/theme_park_imperial/emperor.stf', 224, 'return_waypoint_name_1', 'The Emperor'),
('string/en/theme_park_imperial/emperor.stf', 225, 'return_waypoint_name_2', 'The Emperor'),
('string/en/theme_park_imperial/emperor.stf', 226, 'return_waypoint_name_3', 'The Emperor'),
('string/en/theme_park_imperial/emperor.stf', 227, 'return_waypoint_name_4', 'The Emperor'),
('string/en/theme_park_imperial/emperor.stf', 228, 'return_waypoint_name_5', 'The Emperor'),
('string/en/theme_park_imperial/emperor.stf', 229, 'return_waypoint_name_6', 'The Emperor'),
('string/en/theme_park_imperial/emperor.stf', 230, 'return_waypoint_name_7', 'The Emperor'),
('string/en/theme_park_imperial/emperor.stf', 231, 'waypoint_description_1', 'This is where you will find the leader of a group of thugs. Make contact with him.'),
('string/en/theme_park_imperial/emperor.stf', 232, 'waypoint_description_2', 'You are to deliver some top-secret information to some... well, some thugs.'),
('string/en/theme_park_imperial/emperor.stf', 233, 'waypoint_description_3', 'Bring down the generators powering the security systems to the Queen''s Summer Home'),
('string/en/theme_park_imperial/emperor.stf', 234, 'waypoint_description_4', 'You are to meet with Altah, one of Queen Kylantha''s handmaidens. She will act as a representative to the Queen.'),
('string/en/theme_park_imperial/emperor.stf', 235, 'waypoint_description_5', 'Destroy the band of thugs that attacked the Queen. Find the secret data they are keeping hidden.'),
('string/en/theme_park_imperial/emperor.stf', 236, 'waypoint_description_6', 'You are to deliver the Queen''s speech to the Council. Hurry, before they vote.'),
('string/en/theme_park_imperial/emperor.stf', 237, 'waypoint_description_7', 'Now is your chance to strike at the head of the Rebellion. Wipe him out.'),
('string/en/theme_park_imperial/emperor.stf', 238, 'waypoint_name_1', 'Thug Leader'),
('string/en/theme_park_imperial/emperor.stf', 239, 'waypoint_name_2', 'Thug Representative'),
('string/en/theme_park_imperial/emperor.stf', 240, 'waypoint_name_3', 'The Queen''s Security'),
('string/en/theme_park_imperial/emperor.stf', 241, 'waypoint_name_4', 'Altah, Handmaiden to the Queen'),
('string/en/theme_park_imperial/emperor.stf', 242, 'waypoint_name_5', 'Imposters'),
('string/en/theme_park_imperial/emperor.stf', 243, 'waypoint_name_6', 'Council Representative'),
('string/en/theme_park_imperial/emperor.stf', 244, 'waypoint_name_7', 'High Ranking Rebel General'),
('string/en/theme_park_imperial/emperor.stf', 245, 'npc_backtowork', 'Do not tarry. I do not take well to those who make me wait.'),
('string/en/theme_park_imperial/emperor.stf', 246, 'player_reset_1', 'My lord, I cannot do this any longer.'),
('string/en/theme_park_imperial/emperor.stf', 247, 'player_reset_2', 'My lord, I cannot do this any longer.'),
