('string/en/theme_park_imperial/emperor.stf', 259, 'player_sorry_7', 'I am sorry, my Lord.  I was just preparing for my assignment.'),
('string/en/theme_park_imperial/emperor.stf', 260, 'npc_reset_1', 'You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?'),
('string/en/theme_park_imperial/emperor.stf', 261, 'npc_reset_2', 'You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?'),
('string/en/theme_park_imperial/emperor.stf', 262, 'npc_reset_3', 'You are denying my will? You have much boldness about you, my young friend. Perhaps that can be focused and hardened, hmmm?'),
