('string/en/treasure_map/treasure_map.stf', 9, 'waypoint_name', 'Buried Treasure'),
('string/en/treasure_map/treasure_map.stf', 10, 'search_area', 'Search Area'),
('string/en/treasure_map/treasure_map.stf', 11, 'sys_dist_here', 'You begin extracting the treasure.'),
('string/en/treasure_map/treasure_map.stf', 12, 'sys_dist_near', 'You are not close enough to extract the treasure.'),
('string/en/treasure_map/treasure_map.stf', 13, 'sys_dist_far', 'You aren''t close enough to extract the treasure.'),
('string/en/treasure_map/treasure_map.stf', 15, 'sys_waypoint_exists', 'A waypoint to this location already exists in your datapad.'),
('string/en/treasure_map/treasure_map.stf', 16, 'text_pirate1', 'You have found the diary of a famous and dreaded pirate captain.  Among the many embellished tales of his adventures, you find information on the possible location of a buried treasure.\n\nYou may add a waypoint to this location by pressing the ''Store Waypoint'' button below.  Once you are near that waypoint, use the disk''s ''Search Area'' option to pinpoint the exact location of the treasure.  After you have pinpointed the treasure''s location, dig it up using the ''Extract Treasure'' option on the disk.'),
('string/en/treasure_map/treasure_map.stf', 17, 'title_pirate1', 'Pirate Captain''s Diary'),
('string/en/treasure_map/treasure_map.stf', 18, 'text_pirate2', 'You have found the discarded logbook from a long since scuttled pirate ship.  The last entry refers to a location where the pirates may have buried their haul.\n\nYou may add a waypoint to this location by pressing the ''Store Waypoint'' button below.  Once you are near that waypoint, use the disk''s ''Search Area'' option to pinpoint the exact location of the treasure.  After you have pinpointed the treasure''s location, dig it up using the ''Extract Treasure'' option on the disk.'),
('string/en/treasure_map/treasure_map.stf', 19, 'title_pirate2', 'Ancient Starship Log'),
('string/en/treasure_map/treasure_map.stf', 20, 'text_bountyhunter1', 'The datadisk appears to contain the notes of a successful local bounty hunter.  Wedged between various questionable tips on the profession is a sidenote indicating the general location of the bounty hunter''s equipment stash.\n\nYou may add a waypoint to this location by pressing the ''Store Waypoint'' button below.  Once you are near that waypoint, use the disk''s ''Search Area'' option to pinpoint the exact location of the treasure.  After you have pinpointed the treasure''s location, dig it up using the ''Extract Treasure'' option on the disk.'),
('string/en/treasure_map/treasure_map.stf', 21, 'title_bountyhunter1', 'Bounty Hunter''s Notes'),
('string/en/treasure_map/treasure_map.stf', 22, 'sys_not_yours', 'That treasure chest doesn''t belong to you.'),
('string/en/treasure_map/treasure_map.stf', 23, 'sys_success', 'You''ve found the treasure!'),
('string/en/treasure_map/treasure_map.stf', 24, 'sys_not_in_inv', 'The treasure map must be in your inventory for you to use it!'),
('string/en/treasure_map/treasure_map.stf', 25, 'sys_no_waypoint', 'You must store the treasure''s waypoint in your datapad before you can search for it!'),
('string/en/treasure_map/treasure_map.stf', 26, 'sys_cant_pinpoint', 'You are not close enough to pinpoint the treasure''s location.'),
('string/en/treasure_map/treasure_map.stf', 27, 'sys_pinpoint', 'You have successfully pinpointed the exact location of the treasure!'),
('string/en/treasure_map/treasure_map.stf', 28, 'extract_treasure', 'Extract Treasure'),
('string/en/treasure_map/treasure_map.stf', 29, 'sys_found', 'You successfully extract the treasure!'),
('string/en/treasure_map/treasure_map.stf', 30, 'sys_extracting', 'You are already extracting the treasure.'),
('string/en/treasure_map/treasure_map.stf', 31, 'bark_bountyhunter1', 'Don''t lay a finger on my loot, thief!'),
('string/en/treasure_map/treasure_map.stf', 32, 'bark_pirate1', 'Someone''s trying to get our loot!  Take ''im down boys!'),
('string/en/treasure_map/treasure_map.stf', 33, 'bark_pirate2', 'Someone got to the treasure first, but we''ll be the ones to leave with it.  Attack!'),
('string/en/treasure_map/treasure_map.stf', 34, 'prose_loot_cash_split', 'You receive %DI credits from the chest as your share.'),
('string/en/treasure_map/treasure_map.stf', 35, 'prose_loot_cash', 'You find %DI credits in the chest.'),
('string/en/treasure_map/treasure_map.stf', 36, 'sys_start_pinpoint', 'You begin to scan for the exact location of the treasure.'),
('string/en/treasure_map/treasure_map.stf', 37, 'sys_inventory_full', 'Unable to complete the action, your inventory is full.  Please free some inventory space and try again.'),
('string/en/treasure_map/treasure_map.stf', 38, 'text_hedon1', 'This holo map was created by someone named "Axkva Min" several hundred years ago. The location it leads to is named "Dragon Graveyard".'),
('string/en/treasure_map/treasure_map.stf', 39, 'title_hedon1', 'Ancient Holo Map'),
