('string/en/treasure_map/treasure_map.stf', 41, 'map_fail', 'This map is obviously a fake.'),
('string/en/tt8l.stf', 1, 'tt8l1', 'State your business.\n'),
('string/en/tt8l.stf', 2, 'tt8l2', 'There is more work to be done. Are you ready for another mission?\n'),
('string/en/tt8l.stf', 3, 'tt8l3', 'Welcome back.\n'),
('string/en/tt8l.stf', 4, 'tt8l4', 'Your kind is not welcome here.\n'),
('string/en/tt8l.stf', 5, 'tt8l5', 'There are no appointments currently scheduled with Imperials. Go away.\n'),
('string/en/tt8l.stf', 6, 'tt8l6', 'Bib Fortuna will speak with you now. Go find him inside.\n'),
('string/en/tt8l.stf', 7, 'tt8l7', 'I want to see Jabba the Hutt.\n'),
('string/en/tt8l.stf', 8, 'tt8l8', 'I am here to offer my services.\n'),
('string/en/tt8l.stf', 9, 'tt8l9', 'What is this place?\n'),
('string/en/tt8l.stf', 10, 'tt8l10', 'Who are you?\n'),
('string/en/tt8l.stf', 11, 'tt8l11', 'Jabba does not mingle with tourists. Perform errands for Jabba and he may grant you audience.\n'),
('string/en/tt8l.stf', 12, 'tt8l12', 'Wait here. I will inquire if anyone inside needs any minor tasks done by the likes of one such as yourself.\n'),
('string/en/tt8l.stf', 13, 'tt8l13', 'This is the Palace of Jabba the Hutt.  It is not open to the public. If you wish to enter, you must first complete tasks for Jabba and his associates.\n'),
('string/en/tt8l.stf', 14, 'tt8l14', 'I am TT-8L. If you wish audience with Jabba the Hutt, I can ask inside the palace if anyone has work for you.\n'),
('string/en/tt8l.stf', 15, 'tt8l15', 'Yes. Give me a task.\n'),
('string/en/tt8l.stf', 16, 'tt8l16', 'No. I am not ready, yet.\n'),
('string/en/tt8l.stf', 17, 'tt8l17', 'Your task is as follows.\n'),
('string/en/tt8l.stf', 18, 'tt8l18', 'Return when you are ready to serve Jabba.\n'),
