('string/en/ui.stf', 341, 'movedown', 'Move Down'),
('string/en/ui.stf', 342, 'moveup', 'Move Up'),
('string/en/ui.stf', 343, 'msg_login_fail', 'You were unable to connect to the Login Server. This is the server that allows you to select a character.\n\nThe inability to connect could be because of a failure in the Internet connection between your machine and the Login Server, or it could be because the Login Server is unavailable.\n\nPlease check that your connection to the Internet is alive and well; if the problem persists, try again in a little while. You should also check the game website at \n\nhttp://www.starwarsgalaxies.com\n\nto see if there is a known issue. Sometimes there are scheduled downtimes for the Login  Server.\n\nIf you still cannot connect, please contact Customer Service. Sorry for the inconvenience!'),
('string/en/ui.stf', 344, 'msg_truncated_spatial', 'You spatial chat message was truncated because it was too long.'),
('string/en/ui.stf', 345, 'name_approved', 'Your name has been approved!'),
('string/en/ui.stf', 346, 'name_bothan', 'Bothan'),
('string/en/ui.stf', 347, 'name_declined_cant_create_avatar', 'You have sent an invalid message to the server while attempting to create a character name.\n\nIt is possible that you have received this message in error, in which case you should contact Customer Service.\n\nIt is also possible that you were doing this intentionally in order to attempt to hack the character creation process. Hacking the Star Wars Galaxies servers is a violation of the Terms of Service and can result in account termination and legal action.'),
('string/en/ui.stf', 348, 'name_declined_developer', 'Your character name is not acceptable. It is too similar to a name we have reserved.\n\nPlease try again with a different name.'),
('string/en/ui.stf', 349, 'name_declined_empty', 'You can''t create a character without a name! Please enter a name, or use the GENERATE A NAME! button to have us generate one for you.'),
('string/en/ui.stf', 350, 'name_declined_fictionally_reserved', 'We''re sorry, but we do not allow characters to be created using the names of major Star Wars characters or planets from the Star Wars universe.\n\nPlease select another name and try again.'),
('string/en/ui.stf', 351, 'name_declined_in_use', 'We''re sorry, but that name is already in use by  someone else.\n\nWe realize that the selected name may be one that you are very attached to; however, our current naming policy requires that first names be unique.\n\nWe suggest that you either try a different Galaxy where the name may not be in use, or alter the spelling of the name to try to make it unique.'),
('string/en/ui.stf', 352, 'name_declined_internal_error', 'The name approval process has suffered an internal  error.\n\nPlease report this problem to Customer Service,  and try entering your name again.'),
('string/en/ui.stf', 353, 'name_declined_no_name_generator', 'You have sent an invalid message to the server while attempting to create a character name.\n\nIt is possible that you have received this message in error, in which case you should contact Customer Service.\n\nIt is also possible that you were doing this intentionally in order to attempt to hack the character creation process. Hacking the Star Wars Galaxies servers is a violation of the Terms of Service and can result in account termination and legal action.'),
('string/en/ui.stf', 354, 'name_declined_no_template', 'You have sent an invalid message to the server while attempting to create a character name.\n\nIt is possible that you have received this message in error, in which case you should contact Customer Service.\n\nIt is also possible that you were doing this intentionally in order to attempt to hack the character creation process. Hacking the Star Wars Galaxies servers is a violation of the Terms of Service and can result in account termination and legal action.'),
('string/en/ui.stf', 355, 'name_declined_not_authorized_for_species', 'You do not have the expansion required to use that species.'),
('string/en/ui.stf', 356, 'name_declined_not_creature_template', 'You have sent an invalid message to the server while attempting to create a character name. \n\nIt is possible that you have received this message in error, in which case you should contact Customer Service.\n\nIt is also possible that you were doing this intentionally in order to attempt to hack the character creation process. Hacking the Star Wars Galaxies servers is a violation of the Terms of Service and can result in account termination and legal action.'),
('string/en/ui.stf', 357, 'name_declined_number', 'Your character''s name has been declined because of its syntax. The following rules must be followed in entering names:\n\n- Capital letters are only allowed at the beginning of words.\n- No punctuation except for the apostrophe ('') and the dash (-). Some species cannot use these.\n- The name and the surname must each be one word only.\n- No numbers are allowed.'),
('string/en/ui.stf', 358, 'name_declined_profane', 'Your selected name has been declined because it may contain inappropriate language. \n\nWe realize that computers are fallible, and that if you keep trying, you may be able to fool the name filter. However, inapproprate language in names is against our Terms of Service.\n\nIf your character is reported for an inappropriate name by another player, you may have the name changed or lose the character. We therefore suggest that you keep it clean. Thanks!\n\nPlease select another name and try again.\n'),
('string/en/ui.stf', 359, 'name_declined_racially_inappropriate', 'Your character name is not suitable for this species.\n\n  - All names must be at least 3 characters  long.\n  - Names can be no longer than 15 characters.\n  - Surnames can be no longer than 20 characters.\n\nDifferent species have different rules on what is permissible.\n\n  - Humans and Twi''leks may have one hyphen (-) or apostrophe ('') in their name or surname.\n  - Mon Calamari can have a hyphen in their name or  surname.\n  - Wookiees are not allowed a surname.\n\nPlease try again with a different name.'),
('string/en/ui.stf', 360, 'name_declined_reserved', 'We''re sorry, but that name contains a word that we do not allow in character names. Please try again with a new name.'),
('string/en/ui.stf', 361, 'name_declined_retry', 'The character naming process suffered an internal error. Please try entering your character''s name again.'),
('string/en/ui.stf', 362, 'name_declined_syntax', 'Your character''s name has been declined because of its syntax. The following rules must be followed in entering names:\n\n- Capital letters are only allowed at the beginning of words.\n- No punctuation except for the apostrophe ('') and the dash (-). Some species cannot use these.\n- The name and the surname must each be one word only.\n- No numbers are allowed.'),
('string/en/ui.stf', 363, 'name_declined_too_fast', 'You are not allowed to create a character more than once every 15 minutes.  Please try again later.\n'),
