('string/en/ui.stf', 565, 'stat_help_action', 'This attribute defines the size of your ACTION pool.  Besides representing how "energetic" you feel, the pool can be expended to execute special moves.  If this pool value reaches 0, you become incapacitated.'),
('string/en/ui.stf', 566, 'stat_help_constitution', 'This attribute affects the regeneration rate of your HEALTH pool.  The higher the attribute, the faster you will generate points in this pool.'),
('string/en/ui.stf', 567, 'stat_help_focus', 'This attribute affects the efficiency of your MIND pool.  The higher this attribute, the fewer points it takes to execute moves that cost points from this pool.'),
('string/en/ui.stf', 568, 'stat_help_health', 'This attribute defines the size of your HEALTH pool.  Besides representing the number of hit points you have, the pool can be expended to execute special moves.  If this pool value reaches 0, you become incapacitated.'),
('string/en/ui.stf', 569, 'stat_help_main', 'This is the stat migration page.  You can move attribute points from one pool to another, within the constraints of your race.  The values set at character creation will be appropriate for your profession, but you may want to adjust them as your character grows and progresses.  The actual movement of your attributes does not happen instantly, but migrates over time.'),
('string/en/ui.stf', 570, 'stat_help_mind', 'This attribute defines the size of your MIND pool.  Besides representing your mental status, the pool can be expended to execute special moves.  If this pool value reaches 0, you become incapacitated.'),
('string/en/ui.stf', 571, 'stat_help_quickness', 'This attribute affects the efficiency of your ACTION pool.  The higher this attribute, the fewer points it takes to execute moves that cost points from this pool.'),
('string/en/ui.stf', 572, 'stat_help_stamina', 'This attribute affects the regeneration rate of your ACTION pool.  The higher the attribute, the faster you will generate points in this pool.'),
('string/en/ui.stf', 573, 'stat_help_strength', 'This attribute affects the efficiency of your HEALTH pool.  The higher this attribute, the fewer points it takes to execute moves that cost points from this pool.'),
('string/en/ui.stf', 574, 'stat_help_willpower', 'This attribute affects the regeneration rate of your MIND pool.  The higher the attribute, the faster you will generate points in this pool.'),
