('string/en/ui_auc.stf', 157, 'help_vs_selling', 'Items for Sale in your Vendor.\n\nYou can view all items for sale at your vendors here.'),
('string/en/ui_auc.stf', 158, 'help_vs_filter_location', 'Vendor Location Filters.\n\nYou can choose to view items for sale at this vendor only, or all of your vendors in the Region, on the Planet, or in the Galaxy.'),
('string/en/ui_auc.stf', 159, 'help_vs_filter_type', 'Item Type Filter\n\nUse this filter to choose what type of items for which to browse.'),
('string/en/ui_auc.stf', 160, 'help_vs_table', 'Items currently for sale in your vendor(s) are displayed here.\n\nDouble click on an item to view a detailed description of it.'),
('string/en/ui_auc.stf', 161, 'help_vs_new', 'Put a new item up for sale at this Vendor by pressing this button.'),
('string/en/ui_auc.stf', 162, 'help_vs_offers', 'This tab shows the items that have been offered for sale by other players.\n\nYou can choose to buy or reject any item on this list.  If you buy an item, it will be placed in your stockroom.  If you reject it, it will be returned to the player who originally offered it.'),
('string/en/ui_auc.stf', 163, 'help_vs_stock', 'Vendor Stock.\n\nUse this tab to browse the items you have stored in the Stock of your vendor(s).  An item in your stockroom can be put up for sale in your vendors, or retrieved from the Stock and used.\n\n'),
('string/en/ui_auc.stf', 164, 'help_vb_selling', 'Items for Sale\n\nThis tab displays the Items currently for sale at this vendor.\n\n'),
('string/en/ui_auc.stf', 165, 'help_vb_filter_type', 'Item Type Filter\n\nUse this to choose what type of items to show in the list.'),
('string/en/ui_auc.stf', 166, 'help_vb_table', 'Items currently for sale at this vendor are displayed here.\n\nDouble click on an item to view a detailed description of it.'),
('string/en/ui_auc.stf', 167, 'help_vb_buy', 'Buy the Selected Item by pressing this button.'),
('string/en/ui_auc.stf', 168, 'help_vb_offers', 'Items offered to this Vendor by you.\n\nBy offering an item for sale, you give the Vendor an opportunity to buy your item at the price you specify.  The owner of the Vendor will review your item and choose to buy it or reject it.  If the vendor owner rejects the item, you '),
('string/en/ui_auc.stf', 169, 'help_all', 'View All Sales\n\nUsing this tab, you can browse the Commodities market for Items which you can bid on or buy.'),
('string/en/ui_auc.stf', 170, 'help_all_filter_location', 'Commodities Market Location Filters\n\nUse these filters to narrow or widen your search.  You can browse the Region for Items that can be bought and picked up here.  You can also browse by Planet or even the entire Galaxy.  \n\nIf you purchase an item from a distant location you will need to travel to that location to pick up your new item.\n'),
('string/en/ui_auc.stf', 171, 'help_all_filter_type', 'Item Type Filter.\n\nUse this filter to choose what type of items for which to browse.'),
('string/en/ui_auc.stf', 172, 'help_all_table', 'Items for sale or auction are displayed here.\n\nItems for sale in the Commodities Market can be classified by sale type in two ways:\n\n- Auction: Item item up for Auction can be bid on until the time runs out.  When the time runs out, the person with the highest bid gets the item.\n\n- Instant Sale:  Items up for Instant Sale are available for purchase to the first person willing to pay the listed price.\n \nDouble click on an item to view a detailed description of it.'),
('string/en/ui_auc.stf', 173, 'help_all_bid', 'Buy or Bid on the Selected Item by pressing this button.'),
('string/en/ui_auc.stf', 174, 'help_bids', 'Bids Outstanding\n\nView your currently Outstanding Bids using this tab.  You can watch your bids and bid higher if someone outbids you on an item.'),
('string/en/ui_auc.stf', 175, 'help_sales', 'Outstanding Sales\n\nUse this tab to view items which you have placed for Sale on the Commodities Market.\n\nYou can use the information here to determine who is bidding on your items, and how much is being bid.  You can also cancel sales or accept the current high bid on any item.'),
('string/en/ui_auc.stf', 176, 'help_sales_new', 'Put one of your Items up for sale on the Commodities Market by pressing this button.'),
('string/en/ui_auc.stf', 177, 'help_available', 'Available Items\n\nWhen you purchase an item, cancel a sale, or if one of your sales has expired, the item shows up here.\n\nYou can retrieve the item from the Market from here.\n\nPlease note that you must be in the same Market Region as the item in order to retrieve it.'),
('string/en/ui_auc.stf', 178, 'help_v_available', 'Available Items'),
('string/en/ui_auc.stf', 179, 'buy_successful_planet_prose', 'The item has been purchased.\n\nTo retrieve the item, click on the ''Available Items'' tab, choose the item from the list, and press the button labeled ''Retrieve''.\n\nYou will first need to travel to %TT and access a Market Terminal there.'),
('string/en/ui_auc.stf', 180, 'buy_successful_galaxy_prose', 'The item has been purchased.\n\nTo retrieve the item, click on the ''Available Items'' tab, choose the item from the list, and press the button labeled ''Retrieve''.\n\nYou will first need to travel to %TT, on %TO, and access a Market Terminal there.\n'),
('string/en/ui_auc.stf', 181, 'buy_vendor_owner_successful_local', 'The item has been purchased.\n\nYou can retrieve or sell the item by clicking on the ''Stockroom'' tab.'),
('string/en/ui_auc.stf', 182, 'buy_vendor_owner_successful_remote', 'The item has been purchased.\n\nYou can retrieve or sell the item by clicking on the ''Stockroom'' tab.\n\nIn order to retrieve the item, you will need to travel to the vendor which now has the item.'),
('string/en/ui_auc.stf', 183, 'buy_vendor_buyer_successful', 'The item has been purchased.\n\nIf you have room in your inventory, it will be placed there.  Otherwise, you may pick up the item later using the ''Available Items'' tab.'),
('string/en/ui_auc.stf', 184, 'help_details_viewer', 'Item Details\n\nUse this window to inspect an item in the Market.'),
('string/en/ui_auc.stf', 185, 'help_details_info', 'This panel shows information about the item, such as its name, type, who put it up for sale, and where the item is located.'),
('string/en/ui_auc.stf', 186, 'help_details_price', 'The item''s price is displayed here, if the item is currently for sale.\n\nIf the item is up for auction, the current high bid is displayed.'),
('string/en/ui_auc.stf', 187, 'help_details_attribs', 'The Guaranteed Attributes of the item are shown here.'),
('string/en/ui_auc.stf', 188, 'help_details_desc', 'The description of the item, as provided by the seller, is displayed here.'),
('string/en/ui_auc.stf', 189, 'help_bid_high', 'Use this window to place a bid on an item.\n\nThis field displays the current high bid on the item.'),
('string/en/ui_auc.stf', 190, 'help_bid_bid', 'Enter your bid here.'),
('string/en/ui_auc.stf', 191, 'help_bid_proxy', 'Enter your Proxy Bid here.\n\nThe Proxy Bid is the limit to which the Auction system will automatically raise your bid.  Your bid is only automatically raised if you are out-bid by another player.'),
('string/en/ui_auc.stf', 192, 'sell_premium', 'Premium Sale'),
('string/en/ui_auc.stf', 193, 'sell_tab_inv', 'Inventory'),
('string/en/ui_auc.stf', 194, 'sell_tab_datapad', 'Datapad'),
('string/en/ui_auc.stf', 195, 'err_sell_cannot_sell_intangible', 'You cannot sell this item.\n\nThe only data types that can be sold on the market are Manufacturing Schematics.'),
('string/en/ui_auc.stf', 196, 'help_sell_stockroom', 'This is the Selling Window.\n\nIt will allow you to sell the selected item from your Vendor Stock.'),
('string/en/ui_auc.stf', 197, 'help_sell_tabs', 'This is the Selling Window.\n\nYou can choose to sell an item from your inventory, or from your datapad, by using these tabs.'),
('string/en/ui_auc.stf', 198, 'help_sell_container', 'This is the container view of your inventory or datapad.\n\nSelect an item here to sell it.'),
('string/en/ui_auc.stf', 199, 'help_sell_info', 'Information about the item to sell is shown here.'),
('string/en/ui_auc.stf', 200, 'help_sell_stockroom_price', 'Specify the selling price of the item here.'),
('string/en/ui_auc.stf', 201, 'help_sell_instant', 'To sell the item as an Instant Sale, select this radio button and set the selling price.'),
('string/en/ui_auc.stf', 202, 'help_sell_auction', 'To sell the item in an Auction, select this radio button and set the minimum bid.'),
('string/en/ui_auc.stf', 203, 'help_sell_auction_time', 'If you are creating a new Auction, specify the duration of the Auction.\n\nOnce the auction duration expires, the item will be awarded to the highest bidder.'),
('string/en/ui_auc.stf', 204, 'help_sell_desc', 'Potential buyers will be able to see all the attributes of the item for sale.\n\nYou can add additional information here if desired.'),
('string/en/ui_auc.stf', 205, 'help_sell_ok', 'When you have configured the sale to your liking, press this button to create the sale.'),
