('string/en/ui_charsheet.stf', 755, 'help_attributes', 'This is your Character Sheet.  \n\nIt shows basic information about your character, such as your health, faction status, and guild affiliation.\n\nThis table displays your attributes, such as your Health, Action, and Mind.  Wounds are also displayed.  Wounds lower an attribute''s maximum value.  Wounds can be healed at hospitals or cantinas, or by skilled players.'),
('string/en/ui_charsheet.stf', 756, 'help_shockwounds', 'This is the number of battle fatigue points that you currently have.  Battle fatigue makes it more difficult to heal.  This fatigue must be healed by an Entertainer, Dancer or Musician in a Cantina, Hotel, Tavern, or Theater.'),
('string/en/ui_charsheet.stf', 757, 'help_stomach', 'You can eat and drink food which can give you temporary benefits.  Once your stomach is full, you''ll have to wait until you can eat again.'),
('string/en/ui_charsheet.stf', 758, 'help_factions', 'This page displays your current faction alignment, and what faction points you''ve earned with both the Rebels and Imperials.  These points affect how NPC''s interact with you and can be spent for benefits like specialized weapons or armor.'),
('string/en/ui_charsheet.stf', 759, 'help_statmigration', 'This button opens the stat migration page, where you can modify your maximum attribute values.'),
('string/en/ui_charsheet.stf', 760, 'holocube', 'Holocron'),
('string/en/ui_charsheet.stf', 761, 'help_personalinfo', 'Personal information, such as your birthdate, bind location, and marriage status are listed here.'),
('string/en/ui_charsheet.stf', 762, 'help_badges', 'This is a list of the badges that you have earned.  Badges are granted for completing certain in-game actions.'),
('string/en/ui_charsheet.stf', 763, 'help_bio', 'This is your biography.  Other players see this when they examine you.'),
('string/en/ui_charsheet.stf', 764, 'statmig_usealltpoints', 'You must assign all of your attribute points.'),
