('string/en/ui_charsheet.stf', 766, 'force_power', 'Force Power'),
('string/en/ui_charsheet.stf', 767, 'image_design_note', 'IMPORTANT NOTE!\n\nStat migration targets set in this window will NOT be applied until you visit an Image Designer.  These targets will be used when an Image Designer migrates your stats.'),
