('string/en/ui_cmnty.stf', 220, 'friend_online', '***%TU is online at %TO. If you are on %TU''s friends list, try /findFriend %TU to find them.'),
('string/en/ui_cmnty.stf', 221, 'friend_offline', '***%TU has gone offline at %TO.'),
('string/en/ui_cmnty.stf', 222, 'clear_preference_confirmation', 'Are you sure you want to delete all of your matchmaking preferences?'),
('string/en/ui_cmnty.stf', 223, 'clear_profile_confirmation', 'Are you sure you want to delete your entire matchmaking profile?'),
('string/en/ui_cmnty.stf', 224, 'quick_match_title', 'Quick Matches for %TU\n----------------------------------'),
('string/en/ui_cmnty.stf', 225, 'quick_match_none', 'There are no players that match your quick match filter.'),
('string/en/ui_cmnty.stf', 226, 'quick_match_one', 'There is 1 matching player.'),
('string/en/ui_cmnty.stf', 227, 'quick_match_many', 'There are %DI matching players.'),
('string/en/ui_cmnty.stf', 229, 'quick_match_bad_parameters', 'Your quick match parameter does not match any of the Categories or Types listed in the Community->Personal window.'),
('string/en/ui_cmnty.stf', 230, 'help_personal_profile_cat', 'This section defines your personal profile.\n\nTo add characteristics to your profile, select from these choices and press "Add item".\n\nThe top item is a category and the bottom item is a type within that category.'),
('string/en/ui_cmnty.stf', 231, 'help_personal_profile_list', 'This is your complete list of profile characteristics. Other player''s preferences are matched against your profile. If you want people to use matchmaking with you, be sure to add characteristics to your profile. To remove a characteristic, select the item and press "Remove item". You can select multiple items at once for removal.'),
('string/en/ui_cmnty.stf', 232, 'help_personal_profile_check', 'This check box specifies whether other players can use matchmaking with you. This allows other player''s preferences to match against your profile.'),
('string/en/ui_cmnty.stf', 233, 'help_personal_profile_reset', 'This button clears all your profile characteristics above.'),
('string/en/ui_cmnty.stf', 234, 'help_personal_pref_interest', 'This section defines your personal preferences .\n\nTo add new characteristics to your preferences, select from these choices and press the "Add item" button.\n\nThe top item is a category and the bottom item is a type within that category.'),
('string/en/ui_cmnty.stf', 235, 'help_personal_pref_list', 'This is your complete list of personal preferences. Your preferences are matched against other player''s profiles. To remove a preference characteristic, select the item and press "Remove item". You can select multiple items at once for removal.'),
('string/en/ui_cmnty.stf', 236, 'help_personal_pref_slider', 'This slider defines the accuracy of the player to player match. If you only want to be notified of perfect matches, set the slider to 100%.'),
('string/en/ui_cmnty.stf', 237, 'help_personal_pref_reset', 'This button clears all your preference characteristics above.'),
('string/en/ui_cmnty.stf', 239, 'help_window', 'The community window allows you to find friends using matchmaking, personalize your avatar, find other players, view your friends list, and ignore players.\n'),
('string/en/ui_cmnty.stf', 240, 'help_personal_tab', 'The Personal tab defines your matchmaking profile.  You can meet people in the game by matching your preferences to their profile. You are only notified of high percentage matches.\n\nMatchmaking checks are made with players that are near you.'),
('string/en/ui_cmnty.stf', 241, 'help_personal_pref_search_time', 'This sets the time between matchmaking searches.'),
('string/en/ui_cmnty.stf', 242, 'help_history_table', 'This is the match history tab.\n\nThis shows all matchmaking matches that have occured during the current play session. The players listed have similar interests.'),
('string/en/ui_cmnty.stf', 243, 'help_character_name', 'The character page displays information about your character that is visibile to other players.'),
('string/en/ui_cmnty.stf', 244, 'help_character_info', 'This section displays the name of your character, the day you character was created, the planet your character was created on, and the species of your character.\n\nYou can not modify this information.'),
('string/en/ui_cmnty.stf', 245, 'help_character_badges', 'This displays the accomplishments your character has completed.'),
('string/en/ui_cmnty.stf', 246, 'help_character_flags', 'Your character can be searched by other players seeking assistance. Set your title to one that represents your character''s current  role. Specify whether you are looking for a group, want to help new players, or like to roleplay. In the chat window, you can toggle your status usig /lfg, /helper, and /roleplay.\n\nThis information is used on the next Search Tab for players to search for you.'),
('string/en/ui_cmnty.stf', 247, 'help_character_biography', 'The biography gives other players background information about your character.\n\nOther players can access your biography through the radial menu on your character.'),
('string/en/ui_cmnty.stf', 248, 'help_character_check', 'This check box defines whether your player is searchable when using the following Search tab or the /who command in the chat window. You  can also toggle this command using /anon.'),
('string/en/ui_cmnty.stf', 249, 'help_search_description', 'On this page you can seach for players in the vicinity with various criteria.  This search does NOT search the entire galaxy, but only your local area.  If you wish to contact an Architect about a home purchase, for example, simply select "Architect" from the Profession list and search for any nearby Architects.'),
('string/en/ui_cmnty.stf', 250, 'help_search_combo', 'When searching for a player, specify the perceived faction, species, profession, or title.'),
('string/en/ui_cmnty.stf', 251, 'help_search_flags', 'Specify whether you need a player who is looking for a group, a new player helper, or a roleplayer.'),
('string/en/ui_cmnty.stf', 252, 'help_search_button', 'This initiates a search for players matching your specifications.'),
('string/en/ui_cmnty.stf', 253, 'help_friends_table', 'The Friends List tab displays any friends you have added to your list. As your friends come online or go offline, their status is displayed here.'),
('string/en/ui_cmnty.stf', 254, 'help_friends_mail', 'This opens an email addressed to all friends currently selected.'),
('string/en/ui_cmnty.stf', 255, 'help_friends_remove', 'Highlight a friend and click here to remove a friend from the list. In the chat window, you can remove a friend using the /removefriend command.'),
('string/en/ui_cmnty.stf', 256, 'help_friends_name', 'Type the name of a new friend to add.'),
('string/en/ui_cmnty.stf', 257, 'help_friends_add', 'Add a friend using this button. You can also type the name and press the Enter key. In the chat window, you can add a friend using the /addfriend command.'),
('string/en/ui_cmnty.stf', 258, 'help_friends_select', 'This selects all your friends in your list. You can then send an email to all your friends using the Mail button.'),
('string/en/ui_cmnty.stf', 259, 'help_ignore_list', 'The Ignore List tab displays any players you have chosen to ignore.'),
('string/en/ui_cmnty.stf', 260, 'help_ignore_add', 'Add an ignored player using this button. You can also type the name and press the Enter key. In the chat window, you can add an ignored player using the /addignore command.'),
('string/en/ui_cmnty.stf', 261, 'help_ignore_name', 'Type the name of a player to ignore.'),
('string/en/ui_cmnty.stf', 262, 'help_ignore_remove', 'Highlight an ignored player and click here to remove a the player the list. In the chat window, you can remove an ignored player using the /removeignore command.'),
('string/en/ui_cmnty.stf', 263, 'help_search_results', 'Search Results'),
('string/en/ui_cmnty.stf', 264, 'preference_type', 'I prefer/'),
('string/en/ui_cmnty.stf', 265, 'friend_comment_usage', 'Usage: /friendcomment <friend name> <comment>'),
