('string/en/ui_craft.stf', 114, 'help_exp_points', 'These are your experiment points.\n\nYou can spend your experiment points to try to improve your prototype through experimentation.\n'),
('string/en/ui_craft.stf', 115, 'help_exp_attribs', 'These are the attributes with which you can experiment.\n\nClick on an attribute bar to commit experiment points to the attribute.'),
('string/en/ui_craft.stf', 116, 'help_exp_risk', 'This is your risk indicator.\n\nThe more experiment points you use, the higher the risk of failure.\n\nHowever, along with higher risk of failure comes higher potential for success.\n'),
('string/en/ui_craft.stf', 117, 'help_exp_run', 'When you have allocated experiment points to attributes as you wish, run the experiment by pressing this button.\n\nYou can run several experiments on a prototype, as long as you have experiment points to spend.'),
('string/en/ui_craft.stf', 118, 'help_exp_obj_attribs', 'As your experimental attributes change through experimentation, the actual attributes of your prototype will change, and will be displayed here.\n\nGood Luck!'),
('string/en/ui_craft.stf', 119, 'cpt_exp_help', 'Use experimentation to improve your prototype.'),
