('string/en/ui_craft.stf', 121, 'cpt_draft_help', 'Select your the Draft Schematic you wish to use in crafting.'),
('string/en/ui_craft.stf', 122, 'help_draft_tabs', 'These are the crafting categories currently available to you.\n\nYou can gain access to more categories by improving your skill or using a crafting station.'),
('string/en/ui_craft.stf', 123, 'help_draft_tree', 'The Draft Schematics available to you are shown here, arranged by type.'),
('string/en/ui_craft.stf', 125, 'help_draft_ingredients', 'The ingredients required to craft the selected Draft Schematic are shown here.'),
('string/en/ui_craft.stf', 126, 'cpt_assembly_help', 'Assemble your item by choosing ingredients for the crafting slots.'),
('string/en/ui_craft.stf', 127, 'help_assembly_inventory', 'These are the items available for crafting.\n\nYou can drag and drop items into the Draft Schematic slots to the right.\n\nIf you craft at a private crafting station, this page will give you access to the Input Hopper of the station. '),
('string/en/ui_craft.stf', 128, 'help_assembly_slots', 'These are the Draft Schematic slots.\n\nYou must choose an ingredient for each of the required slots.\n\nRequired slots are colored green, and optional slots are colored orange.\n\nYou can unload an ingredient from a slot by dragging it back to your inventory or input hopper, or double-clicking it.'),
('string/en/ui_craft.stf', 129, 'help_assembly_info', 'Use the object attributes to assist in ingredient selection.'),
('string/en/ui_craft.stf', 130, 'cpt_summ_help', 'This page presents a summary of the object you have assembled.'),
('string/en/ui_craft.stf', 131, 'help_summ_desc', 'Here are the attributes of the object you have assembled.'),
('string/en/ui_craft.stf', 132, 'help_summ_table', 'Here are the experimental attributes of your object.\n\nThese have a direct effect on the actual attributes on your object.'),
('string/en/ui_craft.stf', 133, 'cpt_option_help', 'Choose how to proceed.'),
('string/en/ui_craft.stf', 134, 'help_option_prototype', 'This option allows you to construct a working Prototype.'),
('string/en/ui_craft.stf', 135, 'help_option_schematic', 'This option allows you to create a Manufacturing Schematic.\n\nThe Manufacturing Schematic will be downloaded to your Datapad, and can be used in a Factory to mass produce many copies of the object you have crafted.'),
('string/en/ui_craft.stf', 136, 'help_option_experiment', 'This option allows you to experiment on the object.\n\nExperimentation allows you to improve your object''s attributes, but can be risky.'),
('string/en/ui_craft.stf', 137, 'cpt_cust_help', 'Customize your crafted object.'),
('string/en/ui_craft.stf', 138, 'help_cust_combo', 'You can choose the appearance of your Crafted Object.\n\nThe number of choices depends on your skill level and the Draft Schematic used.'),
('string/en/ui_craft.stf', 139, 'help_cust_color', 'You can customize the colors of your Crafted Object.'),
('string/en/ui_craft.stf', 140, 'help_cust_viewer', 'Review the appearance of your Crafted Object here.'),
('string/en/ui_craft.stf', 141, 'help_cust_name', 'Set the name of your Crafted Object here.'),
('string/en/ui_craft.stf', 142, 'help_cust_limit', 'You can limit the number of copies a Factory can produce of your Manufacturing Schematic.'),
