('string/en/ui_imagedesigner.stf', 62, 'hair_not_available_for_this_group', 'Hair changes are not available for the selected group.  Try selecting "Hair", "Lekku", etc.'),
('string/en/ui_imagedesigner.stf', 63, 'must_be_at_booth', 'You can only stat migrate players while inside an Image Designer Tent, but you can never stat migrate yourself.'),
('string/en/ui_imagedesigner.stf', 64, 'imagedesigner_not_paying_enough', 'Session canceled, the recipient isn''t paying enough credits.'),
('string/en/ui_imagedesigner.stf', 65, 'holoemotes', 'Holo-Emotes'),
('string/en/ui_imagedesigner.stf', 66, 'help_designer_start', 'This is the Image Design screen.  From this interface, you can modify the physical appearance of characters.  In addition, you can migrate player''s stats and grant them "Holo-Emotes", which give the player the ability to display certain visual effects.'),
('string/en/ui_imagedesigner.stf', 67, 'help_group', 'Like in character creation, a character''s customizations are broken up into multiple categories.  Click on these buttons to select a group for modification.'),
('string/en/ui_imagedesigner.stf', 68, 'help_morph', 'These sliders change customizations that use a range (like height, or lip size).'),
('string/en/ui_imagedesigner.stf', 69, 'help_color', 'The color palettes are used to modify color customizations.'),
('string/en/ui_imagedesigner.stf', 70, 'help_hair', 'This allows you to select the hair for a character.'),
('string/en/ui_imagedesigner.stf', 71, 'help_timer', 'This timer counts down the minimum time required before the selected changes can be committed.  Some changes, like changing a character''s hair, can be done quickly.  More drastic changes require more time.'),
('string/en/ui_imagedesigner.stf', 72, 'help_designer_offered', 'This is the number of credits the recipient has offered to pay in return for the design changes.'),
('string/en/ui_imagedesigner.stf', 73, 'help_designer_credits', 'This can be used to set a minimum amount of credits that the recipient must pay.  They can offer more than you require, but the changes cannot be made until they offer at least this many credits.'),
('string/en/ui_imagedesigner.stf', 74, 'help_cancel', 'Click this button to cancel the current session.  Any time spent will be lost.'),
('string/en/ui_imagedesigner.stf', 75, 'help_revert', 'Click this button to revert the changes made to the character.  The minimum time required timer will not reset.'),
('string/en/ui_imagedesigner.stf', 76, 'help_designer_commit', 'Click this button to accept the changes.  Once you commit, the recipient must also accept before the changes are made.'),
('string/en/ui_imagedesigner.stf', 77, 'help_statmigration', 'Image Designers are the only characters that can migrate stats.  Characters set their targets in the character sheet, but this checkbox must be selected for the stat migration targets to take effect.'),
('string/en/ui_imagedesigner.stf', 78, 'help_holoemotes', 'Selecting one of these radio buttons will assign a Holo-Emote to a character.  These grant a command to players that are used to play visual effects.  They have a certain amount of charges, and a character may only have one active Holo-Emote command at a time.  A very skilled Image Designer can grant the "All" Holo-Emote to characters, which lets them select any Holo-Emote each time they use it.'),
('string/en/ui_imagedesigner.stf', 79, 'help_recipient_start', 'An Image Designer is trying to change your appearance or migrate your stats.  You may click the "Reject" button at any time to end this process.'),
('string/en/ui_imagedesigner.stf', 80, 'help_before', 'This is how your character currently looks.'),
('string/en/ui_imagedesigner.stf', 81, 'help_after', 'This is how your character would look if you accepted the Image Designer''s changes.'),
('string/en/ui_imagedesigner.stf', 82, 'help_recipient_zoom', 'Use these buttons to zoom in and examine your character more closely.'),
('string/en/ui_imagedesigner.stf', 83, 'help_recipient_data', 'This window displays how much more time must be spent before the changes can be committed.  In addtion, it lists the minimum amount of money you are required to pay (feel free to pay more if you''re generous).  It also lists whether your stats will be migrated, and what Holo-Emote the Designer is granting to you, if any.'),
('string/en/ui_imagedesigner.stf', 84, 'help_recipient_credits', 'This is how much money you are offering in return for the Image Designer''s services.  The changes can not be made until you offer at least as much money as they require.'),
('string/en/ui_imagedesigner.stf', 85, 'help_recipient_commit', 'Click this button to accept the changes and pay the offered credits.  This button is not available until the minimum amount of time has elapsed, and the Image Designer has committed their changes.'),
('string/en/ui_imagedesigner.stf', 86, 'holoemote_none', 'None'),
('string/en/ui_imagedesigner.stf', 87, 'canceled_session_by_entering_combat', 'The Image Design session was canceled because you have entered combat.'),
('string/en/ui_imagedesigner.stf', 88, 'canceled_session_by_leaving_tent', 'The Image Design session was canceled.'),
('string/en/ui_imagedesigner.stf', 89, 'return_to_tent_warning_prose', 'You must re-enter the Image Design Tent within %DI seconds or the session will be canceled.'),
('string/en/ui_inv.stf', 1, 'help_icons', 'Icon View\n\nThis is the icon view of the contents of a container.\n\nIf you are viewing your inventory, then the items shown here are the items you are carrying and wearing.  Items you are currently wearing are highlighted.\n\nYou can right-click or left-click-and-hold to get a radial menu for any of the items here.'),
('string/en/ui_inv.stf', 2, 'help_capacity', 'This indicator shows the Current and Maximum capacity of this container.'),
('string/en/ui_inv.stf', 3, 'help_info', 'This icon displays the current container you are viewing.  If you are viewing the contents of your inventory, a picture of your avatar is shown here.\n\nIf you are viewing the contents of a nested container, click the button here to change the view to the parent container.'),
('string/en/ui_inv.stf', 4, 'help_change_view', 'Use this button to toggle the container view between icons and details.'),
('string/en/ui_inv.stf', 5, 'help_details', 'Details View\n\nThe details view allows you to see more information at once.'),
('string/en/ui_inv.stf', 6, 'help_buttoneq', 'This button is used to toggle the larger view of your avatar.'),
('string/en/ui_inv.stf', 7, 'help_viewer', 'When this viewer is visible, you can drag items onto it to equip the items.'),
