('string/en/ui_opt.stf', 215, 'text_colors_words', 'Word Colorizations'),
('string/en/ui_opt.stf', 216, 'tooltip_alarm_add', 'Add an alarm to your list of alarms.  This allows you to save a number of customized alarms for future use.'),
('string/en/ui_opt.stf', 217, 'tooltip_alarm_at', 'Check this box to enable or disable a wake-up style alarm clock.'),
('string/en/ui_opt.stf', 218, 'tooltip_alarm_at_hour', 'Select the exact hour you want your alarm clock to sound off at, with the pull-down menu on the right.  The time is in Earth time.'),
('string/en/ui_opt.stf', 219, 'tooltip_alarm_at_minute', 'Input the exact minute you want your alarm clock to sound off at, with the pull-down menu on the right.  The time is in Earth time.'),
('string/en/ui_opt.stf', 220, 'tooltip_alarm_in', 'Check this box to enable or disable a countdown-style alarm clock.'),
('string/en/ui_opt.stf', 221, 'tooltip_alarm_in_hours', 'Input the number of hours that you want your alarm clock to count down in the box to the right.'),
('string/en/ui_opt.stf', 222, 'tooltip_alarm_in_minutes', 'Input the number of minutes that you want your alarm clock to count down in the box to the right.'),
('string/en/ui_opt.stf', 223, 'tooltip_alarm_list', 'Below is a list of all your alarms that you have saved.'),
('string/en/ui_opt.stf', 224, 'tooltip_alarm_message', 'Input any text you might want to appear on your screen (when your alarm clock goes off) in the space below.'),
('string/en/ui_opt.stf', 225, 'tooltip_alarm_recurring', 'Check this box to toggle whether or not your alarm clock goes off every session, or multiple times in a session, depending on your alarm clock settings and the amount of time you play in a session.'),
('string/en/ui_opt.stf', 226, 'tooltip_alarm_remove', 'Click this button, with an alarm selected above, to remove it from the list of alarms that you have saved.'),
('string/en/ui_opt.stf', 227, 'tooltip_alarm_sound', 'Select the sound that your alarm clock will play via the pull-down menu below.'),
('string/en/ui_opt.stf', 228, 'tooltip_alarm_sound_test', 'Click this button to test your alarm clock''s currently selected sound.'),
('string/en/ui_opt.stf', 229, 'tooltip_allow_overhead_map_rotation', 'Allow Overhead Map Rotation'),
('string/en/ui_opt.stf', 230, 'tooltip_auto_afk_status', 'Check this box to toggle auto-AFK status when you haven''t interacted with the game for a set number of minutes.  You set the number of minutes to whatever you choose, if you enable this option.'),
('string/en/ui_opt.stf', 231, 'tooltip_auto_afk_time', 'Input the number of minutes it takes for you to be AFK before your auto-AFK status is activated.'),
('string/en/ui_opt.stf', 232, 'tooltip_auto_reject_invite', 'Check this box to toggle whether or not you automatically reject group invitations.'),
('string/en/ui_opt.stf', 233, 'tooltip_away_from_keyboard_auto_response_message', 'Input or change the text that you want to appear to players who send you a tell while you are in AFK mode.  You are responsible for keeping this message within the social guidelines of the game.'),
('string/en/ui_opt.stf', 234, 'tooltip_camera_zoom_speed', 'Move this slider to modify how fast your camera zooms in and out.'),
('string/en/ui_opt.stf', 235, 'tooltip_chase_cam', 'When Chase Camera Mode is enabled, the 3rd person camera stays behind the avatar most of the time.'),
('string/en/ui_opt.stf', 236, 'tooltip_chat_auto_emote', 'If enabled, the game automatically performs animations when you speak.'),
('string/en/ui_opt.stf', 237, 'tooltip_chat_box_font_size_default', 'Move this slider to modify the default size of your chat text.'),
('string/en/ui_opt.stf', 238, 'tooltip_chat_bubble_duration', 'Move this slider to modify how long chat bubbles remain on the screen after they appear.'),
('string/en/ui_opt.stf', 239, 'tooltip_chat_bubble_emotes', 'Check this box to toggle chat bubbles displaying for emotes.'),
('string/en/ui_opt.stf', 240, 'tooltip_chat_bubble_enable', 'Check this box to enable the existence of comic-style chat bubbles over PCs and NPCs.'),
('string/en/ui_opt.stf', 241, 'tooltip_chat_bubble_font_size', 'Move this slider to modify the font size of all text that appears in chat bubbles.'),
('string/en/ui_opt.stf', 242, 'tooltip_chat_bubble_prose', 'Check this box to toggle chat bubbles displaying prose format.'),
('string/en/ui_opt.stf', 243, 'tooltip_chat_bubble_range_factor', 'Move this slider to modify the range at which you see chat bubbles in the game.  The further to the right this is set, the farther away chat bubbles will appear.'),
('string/en/ui_opt.stf', 244, 'tooltip_chat_bubble_show_all', 'Check this box to toggle the display of chat bubbles for other players, for NPCs, for PA members, and for group members.'),
('string/en/ui_opt.stf', 245, 'tooltip_chat_bubble_show_group', 'Check this box to toggle displaying chat bubbles for group members'' text.'),
('string/en/ui_opt.stf', 246, 'tooltip_chat_bubble_show_guild', 'Check this box to toggle displaying chat bubbles for your Player Association''s members'' text.'),
('string/en/ui_opt.stf', 247, 'tooltip_chat_bubble_show_npc', 'Check this box to toggle displaying chat bubbles for NPC text.'),
('string/en/ui_opt.stf', 248, 'tooltip_chat_bubble_show_player', 'Check this box to toggle displaying chat bubbles for other players'' text.'),
('string/en/ui_opt.stf', 249, 'tooltip_chat_bubble_show_self', 'Check this box to toggle displaying chat bubbles for your own text.'),
('string/en/ui_opt.stf', 250, 'tooltip_chat_bubble_socials', 'Check this box to toggle chat bubbles displaying for socials.'),
('string/en/ui_opt.stf', 251, 'tooltip_chat_format_mode', 'Select from the following options to choose the way incoming text is formatted for you.'),
('string/en/ui_opt.stf', 252, 'tooltip_chat_mode_brief', 'Brief chat format features only the bare minimum amount of chat information, with no frills attached.'),
('string/en/ui_opt.stf', 253, 'tooltip_chat_mode_diku', 'Diku MUD chat format features all relevant chat information without adding as much detail as the more advanced prose format.'),
('string/en/ui_opt.stf', 254, 'tooltip_chat_mode_prose', 'Prose chat format features descriptive text as well as providing some grammar and punctuation.'),
('string/en/ui_opt.stf', 255, 'tooltip_chat_show_afk_speech', 'Select this option to filter out spatial chat from players that are marked as ''AFK''.  '),
('string/en/ui_opt.stf', 256, 'tooltip_chat_show_npc_speech', 'Select this option to filter out spatial chat from non-player characters.  You may not want this option if you are doing a mission from an NPC, or there are hostile NPCs nearby.'),
('string/en/ui_opt.stf', 257, 'tooltip_chat_timestamp', 'Check this box to enable chat timestamping.  Timestamping will allow you to see when chat and tells were sent to you, within a second''s accuracy.'),
('string/en/ui_opt.stf', 258, 'tooltip_chatbox_keyclick', 'Check this box to toggle ICQ-style audio chirps per keystroke.'),
('string/en/ui_opt.stf', 259, 'tooltip_cockpit_camera_recenter', 'Recenter Cockpit Camera when you adjust your ship''s orientation.'),
('string/en/ui_opt.stf', 260, 'tooltip_cockpit_camera_snap_speed', 'Set the speed at which your camera snaps to its target orientation.'),
('string/en/ui_opt.stf', 261, 'tooltip_cockpit_camera_y_offset', 'This slider will change the default (rest) vertical position when in 3rd person ship view.'),
('string/en/ui_opt.stf', 262, 'tooltip_cockpit_camera_zoom_multiplier', 'This slider increases the zoom factor when in 3rd person ship view.'),
('string/en/ui_opt.stf', 263, 'tooltip_confirm_crafting', 'If you want to receive Confirmation Dialogs when Crafting, select this option.\nConfirmation Dialogs will appear when assembling and completing your item.'),
('string/en/ui_opt.stf', 264, 'tooltip_confirm_obj_delete', 'Check this box to enable the confirmation of any objects you delete, before they are gone for good.'),
('string/en/ui_opt.stf', 265, 'tooltip_controls_keymap', 'Click this box to open up a controls keymap.  This allows you to modify, with great specificity, what your keyboard setup is like.'),
('string/en/ui_opt.stf', 266, 'tooltip_damage_num_others', 'Check this box to toggle the display of damage numbers on top of others.'),
('string/en/ui_opt.stf', 267, 'tooltip_damage_num_self', 'Check this box to toggle the display of damage numbers on top of your character.'),
('string/en/ui_opt.stf', 268, 'tooltip_damage_num_size', 'Move this slider to modify the appearance size of the damage numbers that appear on top of creatures and players.'),
('string/en/ui_opt.stf', 269, 'tooltip_dead_zone', 'Move this slider to modify how much ''give'' your cursor has in standard gameplay, before your character begins to turn to either side.  A tight dead zone configuration will allow you to turn sharply but with less interaction possible with the game screen, whereas a loose dead zone configuration will allow you to interact with a wider amount of the screen before your character and camera begin turning.'),
('string/en/ui_opt.stf', 270, 'tooltip_entangle_resistance', 'Entangle Resistance'),
('string/en/ui_opt.stf', 271, 'tooltip_fullscreen', 'Check this box to disable the Windows key from functioning while in fullscreen mode.'),
('string/en/ui_opt.stf', 272, 'tooltip_gfx_batch_renderer', 'Renders distant Characters and Creatures at low detail.  Improves performance at the cost of visual quality.');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/ui_opt.stf', 273, 'tooltip_gfx_brightness', 'This option is used to modify the brightness level seen in the game.'),
('string/en/ui_opt.stf', 274, 'tooltip_gfx_camera_far_plane', 'This option changes how far into the distance your game camera renders terrain and objects.  Low-end system users may want to keep this option set to a low level to increase overall performance.'),
('string/en/ui_opt.stf', 275, 'tooltip_gfx_camera_fov', 'This option allows you to extend your field of vision outward, allowing you to see more to each side of your camera.  There is a slight distortion in distance seen when this is set to the maximum level.'),
('string/en/ui_opt.stf', 276, 'tooltip_gfx_character_lod_bias', 'This option modifies the overall quality of character objects seen in the game (such players, NPCs, and creatures).   Low-end system users are encouraged to keep this in the mid to low settings, to increase overall performance.'),
('string/en/ui_opt.stf', 277, 'tooltip_gfx_character_lod_manager', 'Enable this option to allow the client to automatically control how many high and medium quality characters are rendered at any given time.'),
('string/en/ui_opt.stf', 278, 'tooltip_gfx_character_shadows', 'This lets you select between different shadow settings for character models.'),
('string/en/ui_opt.stf', 279, 'tooltip_gfx_character_shadows_none', 'This setting displays no shadows on character models.'),
('string/en/ui_opt.stf', 280, 'tooltip_gfx_character_shadows_simple', 'This setting displays simple shadows on character models.'),
('string/en/ui_opt.stf', 281, 'tooltip_gfx_character_shadows_volumetric', 'This setting displays detailed shadows on character models.'),
('string/en/ui_opt.stf', 282, 'tooltip_gfx_contrast', 'This option is used to modify the contrast level seen in the game.'),
('string/en/ui_opt.stf', 283, 'tooltip_gfx_crossfade_detaillevels', 'Check this box to fade between the levels of detail in the game.'),
('string/en/ui_opt.stf', 284, 'tooltip_gfx_detailobjects', 'Check this box to show detailed world objects that aren''t really necessary but add to scenery, such as pipes jutting from the ground.'),
('string/en/ui_opt.stf', 285, 'tooltip_gfx_enable_bloom', 'This option softens the rendered image around bright lights.'),
('string/en/ui_opt.stf', 286, 'tooltip_gfx_fade_objects', 'Check this box to fade objects into and out of view.'),
('string/en/ui_opt.stf', 287, 'tooltip_gfx_gamma', 'This option is used to modify the gamma correction level.'),
('string/en/ui_opt.stf', 288, 'tooltip_gfx_nebula_density', 'Change the density of nebulas in space.  Lowering this can improve your framerate for lower quality video cards.'),
('string/en/ui_opt.stf', 289, 'tooltip_gfx_noncharacter_shadows', 'This lets you select between different shadow settings for non-character objects, such as buildings.'),
('string/en/ui_opt.stf', 290, 'tooltip_gfx_noncharacter_shadows_none', 'This setting displays no shadows on buildings and other objects.'),
('string/en/ui_opt.stf', 291, 'tooltip_gfx_noncharacter_shadows_volumetric', 'This setting displays detailed shadows on buildings and other objects.'),
('string/en/ui_opt.stf', 292, 'tooltip_gfx_particle_lod_bias', 'This option modifies the overall quality of particle systems seen in the game (such fire and smoke).   Low-end system users are encouraged to keep this in the mid to low settings, to increase overall performance.'),
('string/en/ui_opt.stf', 293, 'tooltip_gfx_render_shadows', 'Check this box to turn shadows on or off.  Displaying shadows is not suggested for users with low-end systems, as they can adversely affect your overall system performance.'),
('string/en/ui_opt.stf', 294, 'tooltip_gfx_screenshot_type', 'Select the type of file that you would like to automatically save screenshots as.'),
('string/en/ui_opt.stf', 295, 'tooltip_gfx_screenshot_type_bmp', 'Check this box to render Bitmaps.'),
('string/en/ui_opt.stf', 296, 'tooltip_gfx_screenshot_type_jpg', 'Check this box to render Jpegs.'),
('string/en/ui_opt.stf', 297, 'tooltip_gfx_screenshot_type_quality', 'Dragging the slider to the right will increase the quality of your jpg.'),
('string/en/ui_opt.stf', 298, 'tooltip_gfx_screenshot_type_tga', 'Check this box to render Targas.'),
('string/en/ui_opt.stf', 299, 'tooltip_gfx_shadow_detail', 'Move this slider to modify the level of detail displayed in all shadows.'),
('string/en/ui_opt.stf', 300, 'tooltip_gfx_simple_camera_collision', 'Simple Camera Collision is faster but less accurate.'),
('string/en/ui_opt.stf', 301, 'tooltip_gfx_static_lod_bias', 'This option modifies the overall quality of static objects seen in the game (such as rocks, trees, and buildings).   Low-end system users are encouraged to keep this in the mid to low settings, to increase overall performance.'),
('string/en/ui_opt.stf', 302, 'tooltip_gfx_water', 'Move this slider to modify the level of detail seen in water.'),
('string/en/ui_opt.stf', 303, 'tooltip_gfx_world_detail_bias', 'Move this slider to modify the distance that buildings and other objects draw to you.  When set to a lower range, buildings won''t draw until you are somewhat closer to them.'),
('string/en/ui_opt.stf', 304, 'tooltip_group_waypoints', 'Toggle showing group members'' waypoints.'),
('string/en/ui_opt.stf', 305, 'tooltip_hud_opacity', 'Move this slider to modify how opaque your general HUD is.  The less opaque (left) the slider is, the easier you can see the game-world through the UI menus and boxes.'),
('string/en/ui_opt.stf', 306, 'tooltip_invert_mouselook', 'Check this box to toggle whether your mouselook is inverted (flight-sim style) or non-inverted (FPS style).'),
('string/en/ui_opt.stf', 307, 'tooltip_joystick_dead_zone', 'Change the size of the joystick deadzone.'),
('string/en/ui_opt.stf', 308, 'tooltip_joystick_invert', 'Invert the y-axis (pitch) of your joystick when controlling ships or turrets. This setting will cause the nose of the ship to go up when you push the joystick forward, and to go down when you pull the joystick back. This setting will also cause turrets to respond in a similar fashion.'),
('string/en/ui_opt.stf', 309, 'tooltip_joystick_sensitivity', 'Joystick sensitivity.'),
('string/en/ui_opt.stf', 310, 'tooltip_modal_chat', 'If Modal Chat is enabled, you use a keystroke (default ENTER) to chat.\n\nIf it is not enabled, alphanumeric keys are always interpreted as chat input.'),
('string/en/ui_opt.stf', 311, 'tooltip_mouse_inertia', 'Move this slider to determine the amount of inertia (continued movement) your cursor has.'),
('string/en/ui_opt.stf', 312, 'tooltip_mouse_mode', 'Check this box to set Mouse Pointer Mode as the default mouse mode.  Uncheck the box to use Mouse Look Mode.'),
('string/en/ui_opt.stf', 313, 'tooltip_mouse_sensitivity', 'Move this slider to modify how sensitive your mouse is.  The more sensitive it is, the faster your cursor will move.'),
('string/en/ui_opt.stf', 314, 'tooltip_net_status', 'Check this box to enable viewing the status of your connection to our servers.'),
('string/en/ui_opt.stf', 315, 'tooltip_object_icon_size', 'Object Icon Size affects the size of object icons inside container windows.'),
('string/en/ui_opt.stf', 316, 'tooltip_object_name_font_size', 'Move this slider to adjust the font size seen on object names.'),
('string/en/ui_opt.stf', 317, 'tooltip_object_name_range', 'Move this slider to modify the distance that object names are seen at.'),
('string/en/ui_opt.stf', 318, 'tooltip_object_name_show_all', 'Select this option to show all object names that are in range.'),
('string/en/ui_opt.stf', 319, 'tooltip_object_name_show_group', 'Select this to toggle displaying your group member names over their heads if they are within range.'),
('string/en/ui_opt.stf', 320, 'tooltip_object_name_show_guild', 'Select this to toggle the display of all guild member''s names over their heads if they are within range.'),
('string/en/ui_opt.stf', 321, 'tooltip_object_name_show_npcs', 'Select this to toggle the display of NPC names over their heads if they are within range.'),
('string/en/ui_opt.stf', 322, 'tooltip_object_name_show_players', 'Select this to toggle the display of all player names over their heads if they are within range.'),
('string/en/ui_opt.stf', 323, 'tooltip_object_name_show_signs', 'Show Signs.  Signs'' Names appear in Bold Text.'),
('string/en/ui_opt.stf', 324, 'tooltip_pilot_mouse_mode', 'Starship Piloting Mouse Mode - sets how your mouse will be used when piloting a starship.'),
('string/en/ui_opt.stf', 325, 'tooltip_pilot_mouse_mode_auto', 'Automatic (recommended) - automatically detects whether or not you have a joystick and sets your mouse mode appropriately.'),
('string/en/ui_opt.stf', 326, 'tooltip_pilot_mouse_mode_cockpit_camera', 'Cockpit Camera - move your mouse to view the interior of your ship''s cockpit. This is generally used when you have a joystick.'),
('string/en/ui_opt.stf', 327, 'tooltip_pilot_mouse_mode_virtual_joystick', 'Virtual Joystick - move your mouse to steer your ship. This is generally used when you do not have a joystick.'),
('string/en/ui_opt.stf', 328, 'tooltip_pov_hat_mode', 'Set how your joystick''s POV Hat (Point-of-View Hat) controls your camera view. A gamepad''s secondary controller, usually the digital pad, can also be used for this.'),
('string/en/ui_opt.stf', 329, 'tooltip_pov_hat_mode_pan', 'Pan the camera view with the POV hat.'),
('string/en/ui_opt.stf', 330, 'tooltip_pov_hat_mode_pan_speed', 'Set the speed at which the POV hat pans the camera.'),
('string/en/ui_opt.stf', 331, 'tooltip_pov_hat_mode_snap', 'Snap the view to the direction of the POV hat.'),
('string/en/ui_opt.stf', 332, 'tooltip_pov_hat_mode_snap_angle', 'Set the angle to which the POV hat snaps the camera.'),
('string/en/ui_opt.stf', 333, 'tooltip_profanity', 'Check this box to enable or disable the in-game profanity filter.  When enabled, general profanity from other players will be censored from view.'),
('string/en/ui_opt.stf', 334, 'tooltip_radar_terrain', 'Check this box to toggle whether terrain displays on your radar or not.'),
('string/en/ui_opt.stf', 335, 'tooltip_radial_flora_far', 'Check this box to toggle displaying distant trees.'),
('string/en/ui_opt.stf', 336, 'tooltip_radial_flora_near', 'Check this box to toggle displaying grass and small flowers that appear near you.'),
('string/en/ui_opt.stf', 337, 'tooltip_radial_flora_near_distance', 'Near Radial Flora Draw Distance'),
('string/en/ui_opt.stf', 338, 'tooltip_radial_flora_non_collidable', 'Check this box to toggle displaying flora that you can not collide with, such as small bushes and plants.'),
('string/en/ui_opt.stf', 339, 'tooltip_radial_flora_non_collidable_distance', 'Non-Collidable Flora Draw Distance'),
('string/en/ui_opt.stf', 340, 'tooltip_render_variable_target_reticle', 'Check this box to toggle whether or not the targeting cursor is shown on the screen.'),
('string/en/ui_opt.stf', 341, 'tooltip_res', 'The value for the resource attributes selected from the list below will be averaged for your resources and that average value will be shown on the resource icon. Any attributes that are selected but that a given resource does not have will be ignored.'),
('string/en/ui_opt.stf', 342, 'tooltip_res_cold_resist', 'Cold Resistance'),
('string/en/ui_opt.stf', 343, 'tooltip_res_conductivitiy', 'Conductivity'),
('string/en/ui_opt.stf', 344, 'tooltip_res_conductivity', 'Conductivity'),
('string/en/ui_opt.stf', 345, 'tooltip_res_decay_resist', 'Decay Resistance'),
('string/en/ui_opt.stf', 346, 'tooltip_res_flavor', 'Flavor'),
('string/en/ui_opt.stf', 347, 'tooltip_res_heat_resist', 'Heat Resistance'),
('string/en/ui_opt.stf', 348, 'tooltip_res_malleability', 'Malleability'),
('string/en/ui_opt.stf', 349, 'tooltip_res_potential_energy', 'Potential Energy'),
('string/en/ui_opt.stf', 350, 'tooltip_res_quality', 'Overall Quality'),
('string/en/ui_opt.stf', 351, 'tooltip_res_shock_resistance', 'Shock Resistance'),
('string/en/ui_opt.stf', 352, 'tooltip_res_toughness', 'Unit Toughness'),
('string/en/ui_opt.stf', 353, 'tooltip_reset_defaults', 'Select this to reset the default options for this page.'),
('string/en/ui_opt.stf', 354, 'tooltip_rotate_inventory_objects', 'Rotate the 3-D objects in Icon views, such as Inventory, Datapad, and Loot containers.'),
('string/en/ui_opt.stf', 355, 'tooltip_run_default', 'Check this box to toggle whether running or walking is your default moving state.'),
('string/en/ui_opt.stf', 356, 'tooltip_screen_shake', 'Enables or disables the shaking camera.'),
('string/en/ui_opt.stf', 357, 'tooltip_ship_autolevel', 'Check this box to toggle your ship''s ability to automatically return to its default rotation.'),
('string/en/ui_opt.stf', 358, 'tooltip_show_auto_sort_data_pad_contents', 'Check this box to sort the contents of the player''s datapad each time it is opened.\n'),
('string/en/ui_opt.stf', 359, 'tooltip_show_auto_sort_inventory_contents', 'Check this box to sort the contents of the player''s inventory each time it is opened.\n'),
('string/en/ui_opt.stf', 360, 'tooltip_show_cockpit', 'Show starfighter cockpit frame when piloting a starship'),
('string/en/ui_opt.stf', 361, 'tooltip_show_icon_names', 'Always Show Names on Object Icons, for instance on the Object Icons in your Inventory or Datapad.'),
('string/en/ui_opt.stf', 362, 'tooltip_show_interesting_appearance', 'Check this box to display an icon over NPCs when they have something interesting to discuss.'),
('string/en/ui_opt.stf', 363, 'tooltip_show_modifier_window', 'This window displays all the attribute and skill modifiers currently applied to your character.'),
('string/en/ui_opt.stf', 364, 'tooltip_show_popup_help', 'Many UI Windows have a series of Popup Help Tips associated with them.\n\nIf this option is selected, these Popup Help Tips appear the first time you use a UI Window.\n\nIf the option is not selected, you can still activate the Popup Help Tips at any time.'),
('string/en/ui_opt.stf', 365, 'tooltip_show_system_message', 'Select this to have System Messages popup in the center of your screen, as well as in your Chat window.\n\nDeselect this option to have System Messages only show up in your Chat Window.'),
('string/en/ui_opt.stf', 366, 'tooltip_space_camera_elasticity', 'Adjust the camera''s elasticity when following your starship.'),
('string/en/ui_opt.stf', 367, 'tooltip_space_reticle_percentage', 'Adjusting this will change the size of the target reticle.'),
('string/en/ui_opt.stf', 368, 'tooltip_system_message_timeout', 'Adjust the Onscreen System Message Duration'),
('string/en/ui_opt.stf', 369, 'tooltip_target_nothing_untargets', 'Check this box to toggle whether or not clicking in a space absent of any potential target will remove your current target.'),
('string/en/ui_opt.stf', 370, 'tooltip_terrain_threshold', 'This option modifies the overall detail of terrain and terrain objects seen in the game.  Low-end system users are encouraged to keep this in the mid to low range to enhance overall performance.'),
('string/en/ui_opt.stf', 371, 'tooltip_terrain_threshold_high', 'This option modifies the distance around the player that the terrain is rendered at the highest possible detail.  High detail terrain contains many static objects such as flora and rocks.'),
('string/en/ui_opt.stf', 372, 'tooltip_text_colors_game_messages', 'Select the game message, then select the color you want it to appear in chat.'),
('string/en/ui_opt.stf', 373, 'tooltip_text_colors_palette', 'This is the palette of colors you can assign to your chat messages.'),
('string/en/ui_opt.stf', 374, 'tooltip_text_colors_sentences', 'If text in this list appears in chat, it entire sentence is displayed in the specified color. If you want to modify the color of an item in this list, click the item, then click the new color.'),
('string/en/ui_opt.stf', 375, 'tooltip_text_colors_words', 'If text in this list appears in chat, the text is displayed in the specified color. If you want to modify the color of an item in this list, click the item, then click the new color.'),
('string/en/ui_opt.stf', 376, 'tooltip_trackir', 'Enable Head Tracking via Natural Point''s trackIR.'),
('string/en/ui_opt.stf', 377, 'tooltip_turn_strafes', 'Check this box to enable whether turning causes your character to strafe (slide to the left or right) as well.'),
('string/en/ui_opt.stf', 378, 'tooltip_ui_palette', 'You can choose between several pre-defined palette color schemes for the UI.'),
('string/en/ui_opt.stf', 379, 'tooltip_waypoint_mon', 'Toggle the Onscreen Waypoint Monitor.'),
('string/en/ui_opt.stf', 380, 'tooltip_waypoint_onscreen', 'Select this option to show Arrows in the center of the screen which\npoint toward Waypoints that are not in your field of view.'),
('string/en/ui_opt.stf', 381, 'tooltip_window', 'Check this box to disable the Windows key from functioning while in windowed mode.'),
('string/en/ui_opt.stf', 382, 'tooltip_winkey_fullscreen', 'Check this box to enable or disable the Windows key''s function while in fullscreen mode.'),
('string/en/ui_opt.stf', 383, 'tooltip_winkey_windowed', 'Check this box to enable or disable the Windows key''s function while in windowed mode.'),
