('string/en/ui_planet_map.stf', 16, 'help_map', 'This is the Planetary Map.\n\nYou can use it to find Locations and manage your Waypoints.\n\nRight-click on the map for a popup menu that will allow you to create, destroy, rename, and activate Waypoints.'),
('string/en/ui_planet_map.stf', 17, 'help_here', 'You are here.'),
('string/en/ui_planet_map.stf', 18, 'help_zoom', 'This is the Map Zoom Slider.\n\nUse it to Zoom the Map view in or out.'),
('string/en/ui_planet_map.stf', 19, 'help_tree', 'All registered Map Locations are displayed here.\n\nYour Waypoints are also included.\n\nSelect a Category or Subcategory to display a group of Map Locations on the Map to the left.  Select a single Map Location to view it by itself.\n\nYou can right-click Map Locations in this display for a popup menu that will allow you to manage your Waypoints.'),
('string/en/ui_pm.stf', 1, 'help_browse_table', 'This is your Mail Browser.\n\nThis window displays all the mail currently in your inbox. You can  write new messages and respond to messages sent to you.\n\nThis first table displays your inbox.'),
