('string/en/ui_serv.stf', 98, 'harassment_waiting_for_response', 'Waiting for response'),
('string/en/ui_serv.stf', 101, 'harassment_ticket_limit', 'You have reached your open ticket limit of one ticket. If you would like to create a new ticket, please go to the Customer Service window, click on the Open Tickets tab and remove tickets until you are under the ticket limit.'),
('string/en/ui_serv.stf', 102, 'know_article_no_matches', 'Unable to find any matching articles.'),
('string/en/ui_serv.stf', 103, 'know_article_retrieve', 'Retrieving article...'),
('string/en/ui_serv.stf', 104, 'ticket_pending_closed', 'The ticket you are adding a comment to has been closed. The ticket is now read-only.'),
('string/en/ui_serv.stf', 105, 'how_welcome_desc', 'Welcome to the Star Wars Galaxies Knowledge Base!  The Knowledge Base is a continuously updated resource for Star Wars Galaxies systems and policies.  You can use the Knowledge Base to search for information on your Profession or use it to solve many problems that you may encounter while playing Star Wars Galaxies.  To submit a ticket, you must first search the knowledge base and you will find the button to submit a ticket at the end of the article.\n\n'),
('string/en/ui_serv.stf', 106, 'how_know_desc', 'You can click on the tabs above to navigate to several resources that provide valuable information.  By clicking on the Knowledge Base tab you can search our Knowledge Base.\n'),
('string/en/ui_serv.stf', 107, 'how_top_desc', 'By clicking on the Top Known Issues tab, you can review some the the Bugs that our Quality Assurance Department has identified and are working to resolve.  The Development Team is hard at work on these and other bugs.\n'),
('string/en/ui_serv.stf', 108, 'how_bug_desc', 'Below you can submit any bugs to us that you find and QA will review them and investigate.  Be as detailed as you can and provide as many facts as possible to help us track the bug down!\n'),
('string/en/ui_serv.stf', 109, 'how_harassment_desc', 'You can also report any harassment directly to Customer Service at any time with the button below.\n'),
('string/en/ui_serv.stf', 110, 'how_tickets_desc', 'You can also click on the Open Tickets tab to review any tickets you may currently have open and by CS responses.  This is also the area where you will respond or update any tickets as needed.  Please be sure to delete your ticket when your issue has been resolved.\n'),
('string/en/ui_serv.stf', 111, 'harassment', 'Report A Harassment'),
('string/en/ui_serv.stf', 112, 'bug', 'Report A Bug'),
('string/en/ui_serv.stf', 113, 'tab_how_to_search', 'How To Search'),
('string/en/ui_serv.stf', 114, 'tab_known_issues', 'Top Known Issues'),
('string/en/ui_serv.stf', 115, 'known_issues_header', 'Top Known Issues\n'),
('string/en/ui_serv.stf', 116, 'known_issues_welcome', 'This is a list of our top known issues.  This list does not include all bugs that are being resolved, but it does represent bugs and issues deemed to be of high importance.\n'),
('string/en/ui_serv.stf', 117, 'known_issues_footer', 'If you would like to provide more information about any of these issues, or any other issue you have encountered, please click on the "Report A Bug" button below.  Please provide as many details as possible and our Quality Assurance Department will review and investigate the issue.  Thank you for all Bug reports you send as they provide us with very valuable information.\n'),
('string/en/ui_serv.stf', 118, 'knowledge_base', 'Knowledge Base'),
('string/en/ui_serv.stf', 119, 'known_issues', 'Top Known Issues'),
('string/en/ui_serv.stf', 120, 'cpt_new_ticket', 'New Ticket'),
('string/en/ui_serv.stf', 121, 'tab_instructions', 'Instructions'),
('string/en/ui_serv.stf', 122, 'tab_new_ticket', 'New Ticket'),
('string/en/ui_serv.stf', 123, 'new_ticket', 'New Ticket'),
('string/en/ui_serv.stf', 124, 'instructions_bug', 'Thank you for contacting us regarding your issue.  If you have experienced a Bug and would like to report it or provide additional information for one of our Top Known Issues then please click on the Report A Bug button below or click on the Tab above.  Bugs will go directly to the Quality Assurance department and be investigated.  Please note that Bugs are not, as a rule, responded to.  We do encourage you to place Bug reports when you encounter an issue in Star Wars Galaxies and provide as many details as possible to help us track down the root cause.\n');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/ui_serv.stf', 125, 'instructions_ticket', 'If you require the assistance of a Customer Server Representative (CSR) then please click on the New Ticket button below or click on the tab above.  Tickets are answered in the order received so please do not delete and resubmit your ticket if your issue has not been resolved.  Take a moment before submitting to review our Ticket Categories to pick the one that best fits your issue.  Using the proper category will help us locate your problem and resolve it as quickly as possible.\n\nIf you are not online when a CSR attempts to contact you then a comment will be left in your ticket.  Simply respond to the ticket with any additional information the CSR requested and a CSR will be with you as quickly as possible.\n'),
('string/en/ui_serv.stf', 126, 'or', 'or'),
('string/en/ui_serv.stf', 127, 'harassment_message', 'Please read this entire message and at the end of the text you will find a button that will take you to the ticket submission form.\n\nCommunity Standards information, please review the following guidelines before submitting Community Standards tickets.  Please use the "community standards" categories only for reporting the various types of issues outlined below.  Inappropriate use of community standards categories can result in tickets being closed that must be resubmitted with the appropriate categories and repeated misuse can result in actions being taken against users'' accounts.\n\nHarrassment\nHarrassment is defined as specifically targeting another player or group of players to harm or inconvenience them.  Harassment can take many forms and often what is seen as harassment by one person or group is perfectly acceptable game play.  An example of this in Star Wars is the way Bounty Hunter players hunt Jedi players (of course there may be cases where a Bounty Hunter player may specifically target a single Jedi player, this would be considered harassment and is not allowed.  Bounty Hunter players should not specifically target the same Jedi over and over).  Additionally, if someone calls you a bad name or offends you in any way, please first attempt to resolve the issue by using the built in features (/addignore, /filter) between the parties involved.  The ignore and language filter features provided in-game will help you to control and avoid most harassment.  Should you be unable to resolve the issue, please submit an in-game harassment ticket as a last course of action and the in-game staff will assist.\nRemember, if you feel you are the target of harassment, please make sure that you do a /report <offending player name>.  This will send us the relevent chat data and log it to our servers for secure review.\n\nLanguage\nFor all issues of inappropriate language in game, a player report is needed by using the report command; /report <offending player name>.  This will capture and send us the revelent chat data and log it to our servers for secure review.  For cases of mild and sporadic profanity, please make use of the features already in the game to ignore or block profanity.  The profanity filter (/filter) will garble most profanity, and is defaulted to on.  Should you decide to turn this filter off, you are deciding that mild profanity is of no concern to you.  If this is not the case, please turn the filter back on to prevent viewing of most profanity.  Parents allowing children to play the game should always ensure that the profanity filter is on at all times, as the game is rated T (Teen).  The Ignore list (/addignore <player name>) will add any player to your list that will block any spatial messages, private messages, group messages, or emotes.  You will only see the in-game avatar one that player is added.\nPlease do report severe cases of profane language, sexual/racial abuse, or hate mongering.\n\nTrade Fraud\nThe /report <player name> command, although primarily used to report issues of harassment and language, is the preferred medium for recording a verbal agreement or "contract" between two players for buffing, items for credits, items to have repairs, slicing, ect. conducted on them.  This will send us the relevent data and log it to our servers for secure review.  These agreements must be logged for Customer Service to take any action should a deal go bad.  Unfortunately, without proof of the agreement, we are unable to assist in these issues.\n\nKill Stealing\nStar Wars Galaxies does not recognize NPC/creature ownership for the point of attaining experience or gaining loot.  Corpse permissions are granted to the player/group that inflicts the most damage to the NPC/creature in question.  Additionally, we do not recognize any camp claims.  Customer Service will not be able to assist with claims of Kill Stealing.  We do however encourage players to play nice together and ask that everyone respect those already engaged in combat and only join in the attack if being asked for help.\n\nExploitation\nAll incidents of exploitation should be reported immediately for an in game support to assist.  A CSR must be able to physically witness the exploitation in game.\n\nInappropriate Player Names\nPlease report any inappropriate names you see while playing.  We also don''t want to see them and will change the more severe names quickly.\n\nIn-Game Mail\nAll issues of verbal abuse and/or harassment experienced through the in-game mail system can be reported by using /report <offending player name> command or /report <system> command.  Please be sure to have the offending mail open prior to submitting the player report.\n\nEvidence\nForum posts, eye witness testimonies, video footage, screenshots, player chat logs, and 3rd party website posts are not allowed as collaborating evidence in any of the above situations.\n\nFor further information on any of the above topics, please reference the Game Rules at the official website, or FAQs contained in our knowledge base articles.\n'),
