('string/en/ui_zone_map.stf', 33, 'help_tree', 'This is a list of important zone locations, such as space stations, hyperspace points, points of interest, and locations that are critical to your current mission(s). Active and inactive waypoints are also listed here.\n\nOpen a category to display the locations contained within, and then select one to highlight it on the 3D zone map. \n\nYou can right-click map locations in this display for a popup menu that will allow you to create or destroy a waypoint, to activate or deactivate a waypoint, or to autopilot to a location.'),
('string/en/ui_zone_map.stf', 34, 'help_viewer', 'This is the zone map.\n\nYou can use it to find Locations and manage your Waypoints.\n\nRight-click on the map for a popup menu that will allow you to create a waypoint at your current location or to center the map view on your ship.'),
('string/en/ui_zone_map.stf', 35, 'help_controls', 'Use this button to reset the view which will center the zone map on your ship.'),
('string/en/ui_zone_map.stf', 36, 'refresh', 'Reset the View'),
('string/en/ui_zone_map.stf', 37, 'show_names', 'Show Names'),
('string/en/ui_zone_map.stf', 38, 'controls', 'Left mouse = pan     Ctrl-left mouse = rotate     Ctrl-mouse wheel = zoom     Right mouse = menu'),
('string/en/ui_zone_map.stf', 39, 'inactive_poi_waypoints', 'Inactive Points of Interest'),
('string/en/unity.stf', 1, 'mnu_propose', 'Propose Unity'),
('string/en/unity.stf', 2, 'mnu_divorce', 'Divorce'),
('string/en/unity.stf', 3, 'bad_target', 'You must have a valid player target to Propose Unity.'),
('string/en/unity.stf', 4, 'bad_facing', 'You must be facing your target to properly propose!'),
('string/en/unity.stf', 5, 'out_of_range', 'Your target is too far away to properly propose!'),
('string/en/unity.stf', 6, 'prose_already_proposed', 'But you already have an outstanding unity proposal to %TO.'),
('string/en/unity.stf', 7, 'prose_already_married', 'You cannot propose unity. You are already united with %TO.'),
('string/en/unity.stf', 8, 'target_not_player', 'You may only propose unity to another player.'),
('string/en/unity.stf', 9, 'target_married', 'You cannot propose unity to someone who is already united.'),
('string/en/unity.stf', 10, 'target_proposed', 'Your proposal target is already engaged in a unity proposal.'),
('string/en/unity.stf', 11, 'no_ring', 'You cannot accept a unity proposal without a ring to offer.'),
('string/en/unity.stf', 12, 'accept_fail', 'Your proposal target has no ring to offer in return.'),
('string/en/unity.stf', 13, 'prose_accept_fail', '%TO has no ring to offer and therefore cannot accept.'),
('string/en/unity.stf', 14, 'decline', 'You decline the unity proposal.'),
('string/en/unity.stf', 15, 'declined', 'Your unity proposal has been declined.'),
('string/en/unity.stf', 16, 'prose_declined', 'Your unity proposal to %TO has been declined.'),
('string/en/unity.stf', 17, 'expire_player', 'The unity proposal you extended has expired.'),
('string/en/unity.stf', 18, 'expire_target', 'The unity proposal extended to you has expired.'),
('string/en/unity.stf', 19, 'prose_expire_player', 'The unity proposal you extended to %TO has expired.'),
('string/en/unity.stf', 20, 'prose_expire_target', 'The unity proposal extended to you by %TO has expired.'),
('string/en/unity.stf', 21, 'wed_error', 'An error has occurred during the unity process.'),
('string/en/unity.stf', 22, 'wed_oor', 'You must remain within 15 meters during the unity process for it to complete.'),
('string/en/unity.stf', 23, 'prose_end_unity', 'Your union with %TO has ended.'),
('string/en/unity.stf', 24, 'prose_propose', 'You propose unity to %TO.'),
('string/en/unity.stf', 25, 'ring_prompt', 'Select the ring you would like to offer, in return, for your unity.'),
('string/en/unity.stf', 26, 'prose_wed_complete', 'Your union with %TT is complete.'),
('string/en/unity.stf', 27, 'accept_title', 'Accept Unity Proposal?'),
('string/en/utterance/imperial.stf', 1, 'u1', 'I can''t wait for my next furlough.'),
('string/en/utterance/imperial.stf', 2, 'u2', 'So how about this weather, huh?'),
('string/en/utterance/imperial.stf', 3, 'u3', 'I wonder if there''s any Rebels around.'),
('string/en/utterance/imperial.stf', 4, 'u4', 'You know, things just haven''t been the same since the Battle of Yavin.'),
('string/en/utterance/imperial.stf', 5, 'u5', 'When does my relief get here anyway?'),
('string/en/utterance/imperial.stf', 6, 'u6', 'These boots pinch.'),
('string/en/utterance/imperial.stf', 7, 'u7', 'I really need to get my uniform cleaned.'),
('string/en/utterance/imperial.stf', 8, 'u8', 'Guard duty''s pretty bad, but it''s not as bad as fresher duty.'),
('string/en/utterance/imperial.stf', 9, 'u9', 'I once had to escort a Wookiee prisoner, that was no fun, I''ll tell you!'),
('string/en/utterance/imperial.stf', 10, 'u10', 'I miss home some days.'),
('string/en/utterance/imperial.stf', 11, 'u11', 'So I said to the lieutenant, "Look, if you think that soldier''s got half a brain in his head..."'),
('string/en/utterance/imperial.stf', 12, 'u12', '...and then the gambler said, "But that''s not the rules of sabaac!" So I pulled out my blaster and...'),
('string/en/utterance/imperial.stf', 13, 'u13', 'So the sergeant says, "Regs say you have to be back in time." What a crock.'),
('string/en/utterance/imperial.stf', 14, 'u14', 'I got chewed out for not having a sharp enough crease in my slacks.'),
('string/en/utterance/imperial.stf', 15, 'u15', 'He thinks he''s all high and mighty because he''s a Chiss. I hate aliens, I tell you.'),
('string/en/utterance/imperial.stf', 16, 'u16', 'They might be be crack troops, but they creep me out. You ever seen one without his helmet on? Hmm?'),
('string/en/utterance/imperial.stf', 17, 'u17', 'Yeah, but the real tough ones are the SpecForce guys. They make the regular Rebel army look pathetic.'),
('string/en/utterance/imperial.stf', 18, 'u18', 'I''ve taken down a few SpecForce commandos in my day...'),
('string/en/utterance/imperial.stf', 19, 'u19', 'Well, this is my first station since Carida where I''ve really felt at home.'),
('string/en/utterance/imperial.stf', 20, 'u20', 'I lost a cousin on that battle station you know. Of course, I lost a few on Alderaan too.'),
('string/en/utterance/imperial.stf', 21, 'u21', 'What I want to know is why the Alliance has to go wrecking everything? Life is pretty good for most, isn''t it?'),
('string/en/utterance/imperial.stf', 22, 'u22', 'My uncle was on me about killing civilians. I explained that I was just following orders, but he didn''t understand.'),
('string/en/utterance/imperial.stf', 23, 'u23', 'I''ve only gotten to ride in a walker once, but it was really very interesting...'),
('string/en/utterance/imperial.stf', 24, 'u24', 'I imagine we won''t be here long. They''ll have us take out some little Rebel outpost, and we''ll move again...'),
('string/en/utterance/imperial.stf', 25, 'u25', 'Have you heard the one about the Klatooinian, the Ithorian, and the Wookiee?'),
('string/en/utterance/imperial.stf', 26, 'imperial_npc_greet_1', 'Look alive man, I''m busy here.'),
('string/en/utterance/imperial.stf', 27, 'imperial_npc_greet_2', 'I don''t have time to chat right now.  I''ve got important things to do.'),
('string/en/utterance/imperial.stf', 28, 'imperial_npc_greet_3', 'There''s nothing more annoying than being bothered when I''m busy.  Yes?'),
('string/en/utterance/imperial.stf', 29, 'imperial_npc_job_offer_1', 'Here''s the job.  I won''t ask if you can do it, cause I''ll assume you can.  Now do it.  Ok?'),
('string/en/utterance/imperial.stf', 30, 'imperial_npc_job_offer_2', 'I have some tasks if you''re interested and you can get them done.  Can you?'),
('string/en/utterance/imperial.stf', 31, 'imperial_npc_job_offer_3', 'This is what I have, take it or leave it.'),
('string/en/utterance/imperial.stf', 32, 'imperial_player_line_1_1', 'Look alive?  What exactly does that mean?'),
('string/en/utterance/imperial.stf', 33, 'imperial_npc_response_1_1', 'It means move, move around.  Look like you''re at least pretending to be alive.'),
('string/en/utterance/imperial.stf', 34, 'imperial_player_line_2_1', 'It''s a silly expression.'),
('string/en/utterance/imperial.stf', 35, 'imperial_player_line_3_1', 'Do I look dead?'),
('string/en/utterance/imperial.stf', 36, 'imperial_npc_response_2_1', 'Ok, I''m done talking to you.  You''re wasting my time.'),
('string/en/utterance/imperial.stf', 37, 'imperial_npc_response_3_1', 'You will if you don''t stop bothering me...What?  Too subtle?'),
('string/en/utterance/imperial.stf', 38, 'imperial_player_line_1_2', 'What kind of important things?'),
('string/en/utterance/imperial.stf', 39, 'imperial_npc_response_1_2', 'The kinds of important things I can''t talk about with you.'),
('string/en/utterance/imperial.stf', 40, 'imperial_player_line_2_2', 'You don''t even know me.'),
('string/en/utterance/imperial.stf', 41, 'imperial_player_line_3_2', 'So you''re not going to tell me?'),
('string/en/utterance/imperial.stf', 42, 'imperial_npc_response_2_2', 'That''s why I''m not telling you anything.'),
('string/en/utterance/imperial.stf', 43, 'imperial_npc_response_3_2', 'You catch on quick.'),
('string/en/utterance/imperial.stf', 44, 'imperial_player_line_1_3', 'Sorry, didn''t mean to bother you.'),
('string/en/utterance/imperial.stf', 45, 'imperial_npc_response_1_3', 'If there''s something you need spit it out man!'),
('string/en/utterance/imperial.stf', 46, 'imperial_player_line_2_3', 'Ok, sorry.  I''ll go.'),
('string/en/utterance/imperial.stf', 47, 'imperial_player_line_3_3', 'With that attitude I''m just going to go.'),
('string/en/utterance/imperial.stf', 48, 'imperial_npc_response_2_3', 'Just get out of here, will you?'),
('string/en/utterance/imperial.stf', 49, 'imperial_npc_response_3_3', 'Finally.'),
('string/en/utterance/imperial.stf', 50, 'imperial_npc_go_home', 'Go then.  I don''t need someone who doesn''t really want to work.'),
('string/en/utterance/imperial.stf', 51, 'imperial_npc_do_job', 'Get to work then.'),
('string/en/utterance/military.stf', 1, 'u1', 'Reminds me of this one time, when I was in the army...'),
('string/en/utterance/military.stf', 2, 'u2', 'Carida wouldn''t take me so I enlisted in militia, but after my hitch was up, I decided to strike out on my own...'),
('string/en/utterance/military.stf', 3, 'u3', 'So a Klatooinian, an Ithorian, and a Wookiee walk into a cantina...'),
('string/en/utterance/military.stf', 4, 'u4', 'I need to get my blaster serviced.'),
('string/en/utterance/military.stf', 5, 'u5', 'I''ve been looking for a better deal, but can''t find one.'),
('string/en/utterance/military.stf', 6, 'u6', 'I heard the Alliance might be looking for good people.'),
('string/en/utterance/military.stf', 7, 'u7', 'My advice is, never gamble with a Hutt.'),
('string/en/utterance/military.stf', 8, 'u8', 'Well, this planet''s not so bad.'),
('string/en/utterance/military.stf', 9, 'u9', 'Have you ever seen the inside of an imperial prison?  Me neither.'),
('string/en/utterance/military.stf', 10, 'u10', 'I''d rather be eaten by Rancor''s then pay that guy off.'),
('string/en/utterance/military.stf', 11, 'u11', '...took the bet, then I stood off 500 paces and nailed that bullseye clean as could be...'),
('string/en/utterance/military.stf', 12, 'u12', 'Just need enough credits for one more drink...'),
('string/en/utterance/military.stf', 13, 'u13', '...just another barfight. But the police came, and it turned ugly.'),
('string/en/utterance/military.stf', 14, 'u14', 'Well, you know, they won''t take aliens.'),
('string/en/utterance/military.stf', 15, 'u15', 'What day is it?'),
('string/en/utterance/military.stf', 16, 'u16', 'A good droid is worth his weight in spice, I tell you.'),
('string/en/utterance/military.stf', 17, 'u17', 'What a day.'),
('string/en/utterance/military.stf', 18, 'u18', 'What a great day.'),
('string/en/utterance/military.stf', 19, 'u19', 'I''m not clear on what I should be doing now.'),
('string/en/utterance/military.stf', 20, 'u20', 'I was just practicing my shooting, you know? Shouldn''t have bothered anyone.'),
('string/en/utterance/military.stf', 21, 'u21', 'I don''t see why they made such a fuss over a dead Rodian.'),
('string/en/utterance/military.stf', 22, 'u22', 'My last job left me stranded here, so I''m looking for work.'),
('string/en/utterance/military.stf', 23, 'u23', 'Well, I make my living fighting, basically.'),
('string/en/utterance/military.stf', 24, 'u24', 'It''s a hard life, but weapons and fighting are all I know.'),
('string/en/utterance/military.stf', 25, 'u25', 'I''ve dealt with bounty hunters before, they don''t scare me.'),
('string/en/utterance/military.stf', 26, 'military_npc_greet_1', 'Good day to you!'),
('string/en/utterance/military.stf', 27, 'military_npc_greet_2', 'Know any good jokes?'),
('string/en/utterance/military.stf', 28, 'military_npc_greet_3', 'I''ve had it with the military!'),
('string/en/utterance/military.stf', 29, 'military_npc_job_offer_1', 'The orders are simple.  Can you carry them out effectively?'),
('string/en/utterance/military.stf', 30, 'military_npc_job_offer_2', 'The best approach is to follow the orders you''re given.  Can you do that?'),
('string/en/utterance/military.stf', 31, 'military_npc_job_offer_3', 'My orders are not to be disobeyed.  If you can''t handle that let me know now.'),
('string/en/utterance/military.stf', 32, 'military_player_line_1_1', 'And good day to you.'),
('string/en/utterance/military.stf', 33, 'military_npc_response_1_1', 'What can I do for you on this fine day?'),
('string/en/utterance/military.stf', 34, 'military_player_line_2_1', 'Not much.  Just chatting.'),
('string/en/utterance/military.stf', 35, 'military_npc_response_2_1', 'Well, then if that''s all I''ll get back to my duties, post haste.'),
('string/en/utterance/military.stf', 36, 'military_player_line_3_1', 'What division are you with?'),
('string/en/utterance/military.stf', 37, 'military_npc_response_3_1', 'The NIS Division.  By the way, in case you''re wondering, that''s the Non Important Stuff division, so don''t ask too much of me, okay?'),
('string/en/utterance/military.stf', 38, 'military_player_line_1_2', 'No.  Do you?');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/utterance/military.stf', 39, 'military_npc_response_1_2', 'A rodian, a wookie and a zabrak walk into a bar...'),
('string/en/utterance/military.stf', 40, 'military_player_line_2_2', 'Yeah...'),
('string/en/utterance/military.stf', 41, 'military_npc_response_2_2', 'Oh, well, I''ve forgotten the punchline.'),
('string/en/utterance/military.stf', 42, 'military_player_line_3_2', 'I''ve heard that one...'),
('string/en/utterance/military.stf', 43, 'military_npc_response_3_2', 'Oh.  Well, that''s the only joke I know.'),
('string/en/utterance/military.stf', 44, 'military_player_line_1_3', 'What''s wrong with the military?'),
('string/en/utterance/military.stf', 45, 'military_npc_response_1_3', 'I just don''t think I''m cut out for it.'),
('string/en/utterance/military.stf', 46, 'military_player_line_2_3', 'Why''s that?'),
('string/en/utterance/military.stf', 47, 'military_player_line_3_3', 'You''re not thinking of deserting are you?'),
('string/en/utterance/military.stf', 48, 'military_npc_response_2_3', 'I can''t stand getting up early, I don''t like guns, and I hate taking orders.  Come to think of it, I can''t remember why I joined...'),
('string/en/utterance/military.stf', 49, 'military_npc_response_3_3', 'Well, I wasn''t, but now that you''ve mentioned it...'),
('string/en/utterance/military.stf', 50, 'military_npc_go_home', 'Military work is for people who don''t back down.  Get out of here if you don''t have the backbone for it!'),
('string/en/utterance/military.stf', 51, 'military_npc_do_job', 'I''ll expect a report from you as soon as you''re done.'),
('string/en/utterance/noble.stf', 1, 'u1', 'And when Lady Solia said that the import tax was going up, well, I just HAD to protest.'),
('string/en/utterance/noble.stf', 2, 'u2', 'Really, as if his stinky little pet would be welcome in the right circles in Coruscant.'),
('string/en/utterance/noble.stf', 3, 'u3', 'Someday he''ll realize that butler of his is robbing him blind.'),
('string/en/utterance/noble.stf', 4, 'u4', 'I''ll never understand why sycophants like that rise so high in the Imperial court.'),
('string/en/utterance/noble.stf', 5, 'u5', 'Ah, yes, but have you heard of the Emperor''s Hand? Hush now, can''t talk too loud.'),
('string/en/utterance/noble.stf', 6, 'u6', 'And those DREADFUL Rebels have been acting up again!'),
('string/en/utterance/noble.stf', 7, 'u7', 'I must admit, I do think the Imperial Army goes too far on occasion.'),
('string/en/utterance/noble.stf', 8, 'u8', 'Now, what have I done with my jewelry?'),
('string/en/utterance/noble.stf', 9, 'u9', 'Well, before the Senate was dissolved, I was quite important, you know.'),
('string/en/utterance/noble.stf', 10, 'u10', 'Oh, I''ve been to Coruscant many times.'),
('string/en/utterance/noble.stf', 11, 'u11', 'I never can find my chrono...'),
('string/en/utterance/noble.stf', 12, 'u12', '..and the Klatooinian says to the Wookie, "Have you heard the one about the Ithorian who walked into a cantina?"'),
('string/en/utterance/noble.stf', 13, 'u13', 'I lost millions gambling, of course.'),
('string/en/utterance/noble.stf', 14, 'u14', 'Well, my holdings in several systems are still turning a profit.'),
('string/en/utterance/noble.stf', 15, 'u15', 'Is that a stain on my clothes? I paid a fortune for these, you know.'),
('string/en/utterance/noble.stf', 16, 'u16', 'Yes, but Phen''tal was still with Joo''th Balzey at the time, and Joo''th of course was still getting over Huj, if you recall...'),
('string/en/utterance/noble.stf', 17, 'u17', 'I could use a drink.'),
('string/en/utterance/noble.stf', 18, 'u18', 'So have you seen any good holodramas lately?'),
('string/en/utterance/noble.stf', 19, 'u19', 'The taxes are really unbelievable.'),
('string/en/utterance/noble.stf', 20, 'u20', '...so of course, I had to report him for high treason.'),
('string/en/utterance/noble.stf', 21, 'u21', 'I''ve been considering building a third palace here...'),
('string/en/utterance/noble.stf', 22, 'u22', 'Such a busy day! I have to go shopping again.'),
('string/en/utterance/noble.stf', 23, 'u23', 'Doesn''t it drive you mad, how you always have to "manage" your estate? Isn''t that what servants are for?'),
('string/en/utterance/noble.stf', 24, 'u24', 'Really quite tragic, dead at such a young age.'),
('string/en/utterance/noble.stf', 25, 'u25', 'It''s quite the scandal--he ran off to join the Rebellion. Imagine!'),
('string/en/utterance/noble.stf', 26, 'noble_npc_greet_1', 'I''m not used to dealing with those lower than me.  What is it you want?'),
('string/en/utterance/noble.stf', 27, 'noble_npc_greet_2', 'As a noble I feel it''s only fair to warn you that I''m probably smarter than you, so careful what you say.'),
('string/en/utterance/noble.stf', 28, 'noble_npc_greet_3', 'There''s nothing worse than an arrogant noble is there?  Hi there, how are you?'),
('string/en/utterance/noble.stf', 29, 'noble_npc_job_offer_1', 'Well, if you must do something than at least do this for me so I don''t have to do it myself...'),
('string/en/utterance/noble.stf', 30, 'noble_npc_job_offer_2', 'If it will get you away from me quicker I''ll pay you to do something, ok?'),
('string/en/utterance/noble.stf', 31, 'noble_npc_job_offer_3', 'Sure, I have some things you could do if you need some extra cash.'),
('string/en/utterance/noble.stf', 32, 'noble_player_line_1_1', 'Lower than you?'),
('string/en/utterance/noble.stf', 33, 'noble_npc_response_1_1', 'Yes, you know.  Of a lower station?  Not as good as me?  You''re not getting this are you?'),
('string/en/utterance/noble.stf', 34, 'noble_player_line_2_1', 'I''m not sure I could go as low as you.'),
('string/en/utterance/noble.stf', 35, 'noble_npc_response_2_1', 'This is why I don''t talk to people below me.  You just don''t get it.'),
('string/en/utterance/noble.stf', 36, 'noble_player_line_3_1', 'Sorry.  Didn''t mean to disturb you.'),
('string/en/utterance/noble.stf', 37, 'noble_npc_response_3_1', 'Finally, someone who shows some class.  Now get back to whatever it is you do.'),
('string/en/utterance/noble.stf', 38, 'noble_player_line_2_2', 'I''m too busy to talk to you.'),
('string/en/utterance/noble.stf', 39, 'noble_npc_response_2_2', 'I''m not surprised.  This is what you get for not having an education.'),
('string/en/utterance/noble.stf', 40, 'noble_player_line_3_2', 'Maybe you should get a real job.'),
('string/en/utterance/noble.stf', 41, 'noble_npc_response_3_2', 'Oh, you common masses.  You don''t understand the difficulty of the life we nobles lead.'),
('string/en/utterance/noble.stf', 42, 'noble_player_line_1_3', 'Wow, you''re nice for a noble.'),
('string/en/utterance/noble.stf', 43, 'noble_npc_response_1_3', 'My brethren don''t seem to understand that they''re in fact not better than everybody around them.'),
('string/en/utterance/noble.stf', 44, 'noble_player_line_1_2', 'Oh, I''ll be careful all right.'),
('string/en/utterance/noble.stf', 45, 'noble_npc_response_1_2', 'As well you should be.'),
('string/en/utterance/noble.stf', 46, 'noble_player_line_2_3', 'I appreciate your honesty in the matter.'),
('string/en/utterance/noble.stf', 47, 'noble_npc_response_2_3', 'Well, it''s about time the other nobles learned that we''re people just like everybody else.  '),
('string/en/utterance/noble.stf', 48, 'noble_player_line_3_3', 'That''s pretty enlightened for a noble.'),
('string/en/utterance/noble.stf', 49, 'noble_npc_response_3_3', 'Believe me, I know most of the nobles around here.  Superiority isn''t something they should bring up very often, lest someone checks the facts and finds out they''re all worthless.'),
('string/en/utterance/noble.stf', 50, 'noble_npc_go_home', 'I should have known.  You''re not cut out for real work are you?'),
('string/en/utterance/noble.stf', 51, 'noble_npc_do_job', 'Let me know when you''re finished, ok?'),
('string/en/utterance/pirate.stf', 1, 'u1', 'I once rode through the Jundland Wastes on a bantha with no name.'),
('string/en/utterance/pirate.stf', 2, 'u2', 'Could I be any better looking?'),
('string/en/utterance/pirate.stf', 3, 'u3', 'I think that guy''s wearing my chrono...'),
('string/en/utterance/pirate.stf', 4, 'u4', 'I hear Calrissian runs a high stakes poker game somewhere near Bespin.'),
('string/en/utterance/pirate.stf', 5, 'u5', 'I used to work for Nym.  Nasty one, he is.'),
('string/en/utterance/pirate.stf', 6, 'u6', 'They say Bith are the best musicians, but I think Max Rebo''s my favorite.'),
('string/en/utterance/pirate.stf', 7, 'u7', 'It''s amazing how many people I know with a severed limb...'),
('string/en/utterance/pirate.stf', 8, 'u8', 'Robbed a casino myself once.  Never again, never again...'),
('string/en/utterance/pirate.stf', 9, 'u9', 'Imperial prisons are by far the cleanest.'),
('string/en/utterance/pirate.stf', 10, 'u10', 'I did some time on Dathomir myself.  You don''t believe me?!?'),
('string/en/utterance/pirate.stf', 11, 'u11', 'Have I shown you my scars?  Well, you wouldn''t want to see them anyway.'),
('string/en/utterance/pirate.stf', 12, 'u12', 'I hope our ship is repaired soon...'),
('string/en/utterance/pirate.stf', 13, 'u13', 'No one makes good eye-patches anymore.'),
('string/en/utterance/pirate.stf', 14, 'u14', 'Captain says I''m the best first mate he''s ever had.'),
('string/en/utterance/pirate.stf', 15, 'u15', 'Is that Twi''lek cooking I smell?'),
('string/en/utterance/pirate.stf', 16, 'u16', 'I have cards and dice.  We could do some gambling.'),
('string/en/utterance/pirate.stf', 17, 'u17', 'I''ve seen men killed for saying tripe like that.'),
('string/en/utterance/pirate.stf', 18, 'u18', 'Never let them see you bleed!'),
('string/en/utterance/pirate.stf', 19, 'u19', 'I''ve killed men for less than that.'),
('string/en/utterance/pirate.stf', 20, 'u20', 'It''s not robbery if they give you their money freely is it?  Har har!'),
('string/en/utterance/pirate.stf', 21, 'u21', 'Arrr....I think I stubbed my toe.'),
('string/en/utterance/pirate.stf', 22, 'u22', 'It''s like there''s war going on, up there where the stars are.  You know, like a space battle.'),
('string/en/utterance/pirate.stf', 23, 'u23', 'Never steal from an Imperial supply ship.  They say Vader personally hunts down any pirate that does.'),
('string/en/utterance/pirate.stf', 24, 'u24', 'The Hutts always pay on time, I''ll give them that.'),
('string/en/utterance/pirate.stf', 25, 'u25', 'Corellian ships are the easiest to board...'),
('string/en/utterance/pirate.stf', 26, 'pirate_npc_greet_1', 'Well, well, well, some scum wants to talk to me eh?'),
('string/en/utterance/pirate.stf', 27, 'pirate_npc_greet_2', 'You''re a foolhardy one aren''t you?  Do you even know who I am?'),
('string/en/utterance/pirate.stf', 28, 'pirate_npc_greet_3', 'Didn''t your mother ever tell you not to talk to strangers?'),
('string/en/utterance/pirate.stf', 29, 'pirate_npc_job_offer_1', 'If you are a willin'' to see the inside of a jail cell for your trouble I might be able to find something for you to do...'),
('string/en/utterance/pirate.stf', 30, 'pirate_npc_job_offer_2', 'There''s nothin'' more dangerous than working for me.  You''re either brave or stupid.  Let''s find out shall we?'),
('string/en/utterance/pirate.stf', 31, 'pirate_npc_job_offer_3', 'The money''s where it''s at kid.  If you want some, you''ll do some work for it.  Right?'),
('string/en/utterance/pirate.stf', 32, 'pirate_player_line_1_1', 'Who are you calling scum? '),
('string/en/utterance/pirate.stf', 33, 'pirate_player_line_1_2', 'Is that important?'),
('string/en/utterance/pirate.stf', 34, 'pirate_player_line_1_3', 'You''re not any stranger than anyone else.'),
('string/en/utterance/pirate.stf', 35, 'pirate_npc_response_1_1', 'Isn''t it obvious?  There''s only one person that I''m chattin'' with right now, and it''s you.'),
('string/en/utterance/pirate.stf', 36, 'pirate_npc_response_1_2', 'Important?  It''s always important to know who you''re dealing with.  But just as important to make sure that they don''t...unnerstand?'),
('string/en/utterance/pirate.stf', 37, 'pirate_player_line_2_1', 'So you''re saying I''m scum?'),
('string/en/utterance/pirate.stf', 38, 'pirate_npc_response_1_3', 'Hm...you may have a point.  And yet, I sense that you''re not really all that bright...'),
('string/en/utterance/pirate.stf', 39, 'pirate_player_line_3_1', 'I''m not sure what to say.'),
('string/en/utterance/pirate.stf', 40, 'pirate_npc_response_2_1', 'Quick as a trip through hyperspace aren''t you?'),
('string/en/utterance/pirate.stf', 41, 'pirate_npc_response_3_1', 'That''s ok.  I was pretty much done talkin'' to you anyway.'),
('string/en/utterance/pirate.stf', 42, 'pirate_player_line_2_2', 'But what if the other guy knows that too.'),
('string/en/utterance/pirate.stf', 43, 'pirate_npc_response_2_2', 'Arrr...now you''re just confusin'' me.  Stop it!'),
('string/en/utterance/pirate.stf', 44, 'pirate_player_line_3_2', 'So who are you?'),
('string/en/utterance/pirate.stf', 45, 'pirate_npc_response_3_2', 'Well, I''m...HEY!  Cut that out!'),
('string/en/utterance/pirate.stf', 46, 'pirate_player_line_2_3', 'I''m bright as the sun!'),
('string/en/utterance/pirate.stf', 47, 'pirate_npc_response_2_3', 'On a cloudy day, no doubt.  Yes you are...'),
('string/en/utterance/pirate.stf', 48, 'pirate_player_line_3_3', 'I won''t stand here and be insulted.'),
('string/en/utterance/pirate.stf', 49, 'pirate_npc_response_3_3', 'Well, go stand over there then.  You''re smell''s starting to gag me and I can just as easily insult you from a distance.'),
('string/en/utterance/pirate.stf', 50, 'pirate_npc_go_home', 'This is what I expected.  If you can''t do the work I''ll find someone who can.'),
('string/en/utterance/pirate.stf', 51, 'pirate_npc_do_job', 'Good.  Get to it then.'),
('string/en/utterance/police.stf', 1, 'u1', 'I get so sick of lawbreakers...'),
('string/en/utterance/police.stf', 2, 'u2', '...so I had to arrest her. My own cousin, can you believe it?'),
('string/en/utterance/police.stf', 3, 'u3', 'In the end, resisting arrest is a good excuse.'),
('string/en/utterance/police.stf', 4, 'u4', 'What a long day.'),
('string/en/utterance/police.stf', 5, 'u5', 'I can''t wait until my shift is over.'),
('string/en/utterance/police.stf', 6, 'u6', 'I''ve been pulling double-shifts lately.'),
('string/en/utterance/police.stf', 7, 'u7', 'Well, the Imperial military doesn''t exactly like to cooperate with us police officers.'),
('string/en/utterance/police.stf', 8, 'u8', 'Yeah, we report through the local military detachment. But we''re local all the way.'),
('string/en/utterance/police.stf', 9, 'u9', '...swoop gangs. Definitely on the rise.'),
('string/en/utterance/police.stf', 10, 'u10', 'I had to scrub that graffitti for hours, and it wouldn''t come out.'),
('string/en/utterance/police.stf', 11, 'u11', 'My first sergeant, now he was tough. I swear he ate diced gundark for breakfast.'),
('string/en/utterance/police.stf', 12, 'u12', 'People keep gambling with the Hutts and getting in trouble.'),
('string/en/utterance/police.stf', 13, 'u13', 'The worst are domestic disturbances. I hate those calls.'),
('string/en/utterance/police.stf', 14, 'u14', 'Just your friendly neighborhood police officer, that''s me!'),
('string/en/utterance/police.stf', 15, 'u15', '...not about to chase down Rebels. Let the military handle that. They''re much better equipped...'),
('string/en/utterance/police.stf', 16, 'u16', '...so the punk kid runs down the alley, not realizing it''s a dead end. I drew my weapon and...'),
('string/en/utterance/police.stf', 17, 'u17', '...protection racket, I think. They threaten the shopkeepers that they''ll trash their storefronts if they don''t pay...'),
('string/en/utterance/police.stf', 18, 'u18', 'Last call I had was a bad one; guy pulled a vibroknife out, started slashing... it was bad...'),
('string/en/utterance/police.stf', 19, 'u19', 'I could really use a vacation, but police don''t seem to get much time off.'),
('string/en/utterance/police.stf', 20, 'u20', 'I''m thinking of retiring from the police force, actually. Maybe go merc, you know?'),
('string/en/utterance/police.stf', 21, 'u21', 'Why did I ever join the police?'),
('string/en/utterance/police.stf', 22, 'u22', 'Some weather, huh?'),
('string/en/utterance/police.stf', 23, 'u23', 'I really need to get my uniform cleaned.'),
('string/en/utterance/police.stf', 24, 'u24', 'How long till the shift is over?'),
('string/en/utterance/police.stf', 25, 'u25', 'I can''t believe she called the police to get her monkey lizard down.'),
('string/en/utterance/police.stf', 26, 'police_npc_greet_1', 'Don''t I know you from somewhere?'),
('string/en/utterance/police.stf', 27, 'police_npc_greet_2', 'You''re not out here doing anything illegal are you?'),
('string/en/utterance/police.stf', 28, 'police_npc_greet_3', 'Anything I can help you with citizen?'),
('string/en/utterance/police.stf', 29, 'police_npc_job_offer_1', 'There are many things you can do to help the community.  Interested?'),
('string/en/utterance/police.stf', 30, 'police_npc_job_offer_2', 'I have some things you could do to help out with some of my cases.  Interested?'),
('string/en/utterance/police.stf', 31, 'police_npc_job_offer_3', 'There''s something you can do for me, sure.  Wanna help?'),
('string/en/utterance/police.stf', 32, 'police_player_line_1_1', 'No, that''s not me.'),
('string/en/utterance/police.stf', 33, 'police_npc_response_1_1', 'Are you sure?  You look awfully familiar...'),
('string/en/utterance/police.stf', 34, 'police_player_line_2_1', 'I''m sure I don''t know you.'),
('string/en/utterance/police.stf', 35, 'police_npc_response_2_1', 'Well, ok.  Carry on then, but I''m sure I''ll remember you if I need to...'),
('string/en/utterance/police.stf', 36, 'police_player_line_3_1', 'I think maybe I just have one of those faces...'),
('string/en/utterance/police.stf', 37, 'police_npc_response_3_1', 'Yeah, maybe that''s it.  Carry on then.'),
('string/en/utterance/police.stf', 38, 'police_player_line_1_2', 'I would never do anything illegal, officer.'),
('string/en/utterance/police.stf', 39, 'police_npc_response_1_2', 'You sure about that?'),
('string/en/utterance/police.stf', 40, 'police_player_line_2_2', 'I''m a law abiding citizen.'),
('string/en/utterance/police.stf', 41, 'police_npc_response_2_2', 'Yeah, that''s what they all say.  I''ll be keeping my eye on you.'),
('string/en/utterance/police.stf', 42, 'police_player_line_3_2', 'You don''t trust me?'),
('string/en/utterance/police.stf', 43, 'police_npc_response_3_2', 'I don''t trust anybody.  But just this once I''ll take your word for it.  Stay out of trouble now, you hear?'),
('string/en/utterance/police.stf', 44, 'police_player_line_1_3', 'No, I''m just looking around.'),
('string/en/utterance/police.stf', 45, 'police_npc_response_1_3', 'Well, don''t poke your nose where it doesn''t belong.  Got it?'),
('string/en/utterance/police.stf', 46, 'police_player_line_2_3', 'Absolutely officer.'),
('string/en/utterance/police.stf', 47, 'police_npc_response_2_3', 'Good, good.  It''s people like you that make this such a great place to live.'),
('string/en/utterance/police.stf', 48, 'police_player_line_3_3', 'Are you harrassing me?'),
('string/en/utterance/police.stf', 49, 'police_npc_response_3_3', 'Not yet, but you start any trouble and I will be.'),
('string/en/utterance/police.stf', 50, 'police_npc_go_home', 'That''s all right.  Not everyone actual has to work for a living.'),
('string/en/utterance/police.stf', 51, 'police_npc_do_job', 'Get to it and do it.'),
('string/en/utterance/rebel.stf', 1, 'u1', '..family on Alderaan. So cut him some slack, OK?'),
('string/en/utterance/rebel.stf', 2, 'u2', 'Sure, and I bet you know Mon Mothma personally too.'),
('string/en/utterance/rebel.stf', 3, 'u3', 'Filthy Imperials.'),
('string/en/utterance/rebel.stf', 4, 'u4', 'Not all Imperials are bad, you know. Some of them are just wilfully ignorant.'),
('string/en/utterance/rebel.stf', 5, 'u5', 'I was at the Battle of Yavin, you know. I even saw Skywalker, from a distance.'),
('string/en/utterance/rebel.stf', 6, 'u6', 'Ah, he got lucky with a lucky shot, is all. He''s just some hopped-up farmboy.'),
('string/en/utterance/rebel.stf', 7, 'u7', 'I''d really like to take a furlough, visit my family.'),
('string/en/utterance/rebel.stf', 8, 'u8', 'Some weather these days, eh?'),
('string/en/utterance/rebel.stf', 9, 'u9', 'I wonder if there''s any Imperial patrols around.'),
('string/en/utterance/rebel.stf', 10, 'u10', 'When does my relief get here anyway?'),
('string/en/utterance/rebel.stf', 11, 'u11', 'I wish we had sa nice uniforms as the Empire does.'),
('string/en/utterance/rebel.stf', 12, 'u12', 'Guard duty''s pretty bad, but it''s not as bad as fresher duty.'),
('string/en/utterance/rebel.stf', 13, 'u13', '...no fun escorting Imperial prisoners. Some of them are real fanatics...'),
('string/en/utterance/rebel.stf', 14, 'u14', 'So the sergeant says, "Regs say you have to be back in time." What a crock.'),
('string/en/utterance/rebel.stf', 15, 'u15', 'Hey, you ever seen a Stormtrooper with his helmet off?'),
('string/en/utterance/rebel.stf', 16, 'u16', 'SpecForce can take Stormtroopers any day.'),
('string/en/utterance/rebel.stf', 17, 'u17', '..so the Wookiee says, "And the Klatooinian ordered blue milk?"'),
('string/en/utterance/rebel.stf', 18, 'u18', 'She was really cute, which is why the whole mess happened, you see.'),
('string/en/utterance/rebel.stf', 19, 'u19', '...if he hadn''t been gambling so much, he''d still have some of his pay left!'),
('string/en/utterance/rebel.stf', 20, 'u20', 'Well, don''t tell any officers, or the gig''s up.'),
('string/en/utterance/rebel.stf', 21, 'u21', 'I wouldn''t mind getting out to see a little music, go dancing...'),
('string/en/utterance/rebel.stf', 22, 'u22', 'The thing about the Rebellion, it''s so stuffy and earnest.'),
('string/en/utterance/rebel.stf', 23, 'u23', 'Always better when nothing interesting is going on.'),
('string/en/utterance/rebel.stf', 24, 'u24', 'I felt I had to sign up, after Alderaan.'),
('string/en/utterance/rebel.stf', 25, 'u25', 'We''re getting too many green recruits, since Alderaan.'),
('string/en/utterance/rebel.stf', 26, 'rebel_npc_greet_1', 'Hail friend.  It''s a glorious day, isn''t it?'),
('string/en/utterance/rebel.stf', 27, 'rebel_npc_greet_2', 'Hello.  How''s things going today?'),
('string/en/utterance/rebel.stf', 28, 'rebel_npc_greet_3', 'Good to see you.  What can I help you with?'),
('string/en/utterance/rebel.stf', 29, 'rebel_npc_job_offer_1', 'There''s certainly something you could do to help out the alliance forces...'),
('string/en/utterance/rebel.stf', 30, 'rebel_npc_job_offer_2', 'Yeah, we got some work that you could do.  We''re always undermanned around here...'),
('string/en/utterance/rebel.stf', 31, 'rebel_npc_job_offer_3', 'There''s so much that can be done for the rebellion.  If you could just help us out with this one small thing...'),
('string/en/utterance/rebel.stf', 32, 'rebel_player_line_1_1', 'Why do you guys fight the Empire anyway?'),
('string/en/utterance/rebel.stf', 33, 'rebel_npc_response_1_1', 'You''re joking right?  The Empire that grips systems so tight they can''t breathe and then squeezes until all the tax money comes out of them?  They''re bullies!'),
('string/en/utterance/rebel.stf', 34, 'rebel_player_line_2_1', 'Bullies?  Seriously?  That''s the reason?'),
('string/en/utterance/rebel.stf', 35, 'rebel_player_line_3_1', 'I just don''t see it...'),
('string/en/utterance/rebel.stf', 36, 'rebel_npc_response_2_1', 'Of course that''s the reason?  Did you think we just didn''t like their uniforms?  '),
('string/en/utterance/rebel.stf', 37, 'rebel_npc_response_3_1', 'You must be blind then.  Or joking.  Oh, that''s it...you''re joking.  Good one.'),
('string/en/utterance/rebel.stf', 38, 'rebel_player_line_1_2', 'Tell me what you know about Darth Vader.'),
('string/en/utterance/rebel.stf', 39, 'rebel_npc_response_1_2', 'We don''t like to talk much about him.  He''s the lord of the Sith, and a powerful Jedi.  '),
('string/en/utterance/rebel.stf', 40, 'rebel_player_line_2_2', 'What exactly is a Sith?'),
('string/en/utterance/rebel.stf', 41, 'rebel_player_line_3_2', 'Jedi?  I thought they were all gone?'),
('string/en/utterance/rebel.stf', 42, 'rebel_npc_response_2_2', 'They''re an ancient...um...something to do with darkness...uh...   You know, honestly I don''t even know.  But it''s BAD.'),
('string/en/utterance/rebel.stf', 43, 'rebel_npc_response_3_2', 'Oh no, there''s still some left even on our side.  They like people to think they''re myths, but we know better...'),
('string/en/utterance/rebel.stf', 44, 'rebel_player_line_1_3', 'Aren''t you worried that you''re in constant danger?'),
('string/en/utterance/rebel.stf', 45, 'rebel_npc_response_1_3', 'Of course not.  I wouldn''t be much of a rebel soldier if all I did was sit around and worry about dying, now would I?  Why, have you heard something?'),
('string/en/utterance/rebel.stf', 46, 'rebel_player_line_2_3', 'No, just wondering is all...'),
('string/en/utterance/rebel.stf', 47, 'rebel_player_line_3_3', 'Well, I''d be scared if I were you...'),
('string/en/utterance/rebel.stf', 48, 'rebel_npc_response_2_3', 'Whew.  I mean, yeah.  Nothing to worry about.'),
('string/en/utterance/rebel.stf', 49, 'rebel_npc_response_3_3', 'Well, I''m not you.  And you''re not me.  Let''s just both be thankful for that.'),
('string/en/utterance/rebel.stf', 50, 'rebel_npc_go_home', 'Well, it''s another point for the empire if we can''t even find people to do simple tasks.'),
('string/en/utterance/rebel.stf', 51, 'rebel_npc_do_job', 'You''re doing a great service for the alliance.'),
('string/en/utterance/slave.stf', 1, 'u1', 'I long to be free.'),
('string/en/utterance/slave.stf', 2, 'u2', 'Must do what master says. Always do what master says.'),
('string/en/utterance/slave.stf', 3, 'u3', '"Yes sir" this and "yes sir" that! One of these days, I''ll get loose, and...'),
('string/en/utterance/slave.stf', 4, 'u4', 'I can''t take another day of beatings...'),
('string/en/utterance/slave.stf', 5, 'u5', 'I wonder if the weather is changing...'),
('string/en/utterance/slave.stf', 6, 'u6', 'What a long day...'),
('string/en/utterance/slave.stf', 7, 'u7', 'Every day, it''s work work work work.'),
('string/en/utterance/slave.stf', 8, 'u8', 'I feel ill. But the master won''t let me stop working...'),
('string/en/utterance/slave.stf', 9, 'u9', '...so three Wookiees walk into a bar, and...'),
('string/en/utterance/slave.stf', 10, 'u10', 'Wouldn''t it be nice if slaves got vacations?'),
('string/en/utterance/slave.stf', 11, 'u11', 'What day is it?'),
('string/en/utterance/slave.stf', 12, 'u12', 'Every day is always the same.'),
('string/en/utterance/slave.stf', 13, 'u13', 'Yes, master. Whatever you say, master.'),
('string/en/utterance/slave.stf', 14, 'u14', 'If the Alliance wins...'),
('string/en/utterance/slave.stf', 15, 'u15', 'If the Alliance loses...'),
('string/en/utterance/slave.stf', 16, 'u16', 'I wish I knew how to read...'),
('string/en/utterance/slave.stf', 17, 'u17', 'I suppose life could be worse. Not sure how, but...'),
('string/en/utterance/slave.stf', 18, 'u18', 'Last time I had a little money, I had to spend it on medicine. I don''t get money often...'),
('string/en/utterance/slave.stf', 19, 'u19', 'I wonder what freedom is like?'),
('string/en/utterance/slave.stf', 20, 'u20', 'I don''t even know what I would do with my life, to be honest.'),
('string/en/utterance/slave.stf', 21, 'u21', 'I''ve thought about running away, sometimes...'),
('string/en/utterance/slave.stf', 22, 'u22', 'I''ve thought about joining the Rebellion, sometimes... but would they treat me better?'),
('string/en/utterance/slave.stf', 23, 'u23', 'I have too much to do today.'),
('string/en/utterance/slave.stf', 24, 'u24', 'Oh, I''ll keep doing my job, but only just well enough, if you know what I mean.'),
('string/en/utterance/slave.stf', 25, 'u25', 'I''ve never been so tired...'),
('string/en/utterance/slave.stf', 26, 'slave_npc_greet_1', 'Hello.'),
('string/en/utterance/slave.stf', 27, 'slave_npc_greet_2', 'I shouldn''t be speaking to you.'),
('string/en/utterance/slave.stf', 28, 'slave_npc_greet_3', 'Are you hear to speak with my master?'),
('string/en/utterance/slave.stf', 29, 'slave_npc_job_offer_1', 'There is one thing you can do for me...but I can''t pay you of course.'),
('string/en/utterance/slave.stf', 30, 'slave_npc_job_offer_2', 'Yes, there is a task my master needs accomplished.'),
('string/en/utterance/slave.stf', 31, 'slave_npc_job_offer_3', 'I am authorized by my master to give you a job, yes.  Do you want it?'),
('string/en/utterance/slave.stf', 32, 'slave_player_line_1_1', 'How are you today?'),
('string/en/utterance/slave.stf', 33, 'slave_player_line_1_2', 'Why should anyone not speak to me?'),
('string/en/utterance/slave.stf', 34, 'slave_player_line_1_3', 'Your master?  Um...no, I was speaking to you.'),
('string/en/utterance/slave.stf', 35, 'slave_npc_response_1_1', 'I''m treated very well by my master.  But, thank you for asking.'),
('string/en/utterance/slave.stf', 36, 'slave_npc_response_1_2', 'No one speaks to me, I am but a humble slave.'),
('string/en/utterance/slave.stf', 37, 'slave_npc_response_1_3', 'To me?  Why that is wonderful.  No one ever speaks to me!'),
('string/en/utterance/slave.stf', 38, 'slave_player_line_2_1', 'Think nothing of it.'),
('string/en/utterance/slave.stf', 39, 'slave_player_line_2_2', 'A slave?  That''s appalling!'),
('string/en/utterance/slave.stf', 40, 'slave_player_line_2_3', 'Well, I''m speaking to you now, so I hope you feel better about yourself.'),
('string/en/utterance/slave.stf', 41, 'slave_player_line_3_1', 'Well, I hope the day continues well.'),
('string/en/utterance/slave.stf', 42, 'slave_player_line_3_2', 'Oh, I didn''t realize.'),
('string/en/utterance/slave.stf', 43, 'slave_player_line_3_3', 'Well, I must go.  Nice talking to you.'),
('string/en/utterance/slave.stf', 44, 'slave_npc_response_2_1', 'No, I think the world of you for speaking to me.  I shall never forget you.'),
('string/en/utterance/slave.stf', 45, 'slave_npc_response_2_2', 'No, it is merely the way of the world.  Now I must get back to my duties.'),
('string/en/utterance/slave.stf', 46, 'slave_npc_response_2_3', 'I do in fact.  Thank you for your kindness.'),
('string/en/utterance/slave.stf', 47, 'slave_npc_response_3_1', 'I''m sure it shall.'),
('string/en/utterance/slave.stf', 48, 'slave_npc_response_3_2', 'It''s all right.  Most people don''t.'),
('string/en/utterance/slave.stf', 49, 'slave_npc_response_3_3', 'Good day to you as well.'),
('string/en/utterance/slave.stf', 50, 'slave_npc_go_home', 'That''s too bad.  The task will certainly fall to me now and I have no time for it...'),
('string/en/utterance/slave.stf', 51, 'slave_npc_do_job', 'Thank you for your help in this matter.'),
('string/en/utterance/stormtrooper.stf', 1, 'u1', 'I can''t wait for my next furlough.'),
('string/en/utterance/stormtrooper.stf', 2, 'u2', 'So how about this weather, huh?'),
('string/en/utterance/stormtrooper.stf', 3, 'u3', 'I wonder if there''s any Rebels around.'),
('string/en/utterance/stormtrooper.stf', 4, 'u4', 'You know, things just haven''t been the same since the Battle of Yavin.'),
('string/en/utterance/stormtrooper.stf', 5, 'u5', 'When does my relief get here anyway?'),
('string/en/utterance/stormtrooper.stf', 6, 'u6', 'These boots pinch.'),
('string/en/utterance/stormtrooper.stf', 7, 'u7', 'I really need to get my armor cleaned.'),
('string/en/utterance/stormtrooper.stf', 8, 'u8', 'Guard duty''s pretty bad, but at least I''m not getting shot at.'),
('string/en/utterance/stormtrooper.stf', 9, 'u9', 'I once had to escort a Wookiee prisoner, that was no fun, I''ll tell you!'),
('string/en/utterance/stormtrooper.stf', 10, 'u10', 'I''d much rather be in the barracks right now.'),
('string/en/utterance/stormtrooper.stf', 11, 'u11', 'So I said to the lieutenant, "Yes, sir."'),
('string/en/utterance/stormtrooper.stf', 12, 'u12', 'Look, sir. Droids!'),
('string/en/utterance/stormtrooper.stf', 13, 'u13', 'So the sergeant said to him, "Regs say you have to be back in time."'),
('string/en/utterance/stormtrooper.stf', 14, 'u14', 'This helmet gets hot, you know.'),
('string/en/utterance/stormtrooper.stf', 15, 'u15', 'He thinks he''s all high and mighty because he''s a Chiss. I hate aliens, I tell you.'),
('string/en/utterance/stormtrooper.stf', 16, 'u16', 'SpecForce doesn''t scare me.'),
('string/en/utterance/stormtrooper.stf', 17, 'u17', 'Yeah, but the real tough ones are the SpecForce guys. They make the regular Rebel army look pathetic.'),
('string/en/utterance/stormtrooper.stf', 18, 'u18', 'I''ve taken down a few SpecForce commandos in my day...'),
('string/en/utterance/stormtrooper.stf', 19, 'u19', 'All stations feel the same to me.'),
('string/en/utterance/stormtrooper.stf', 20, 'u20', 'So TK-926 said to TK-345, "What about the time when..."'),
('string/en/utterance/stormtrooper.stf', 21, 'u21', 'What I want to know is why the Alliance has to go wrecking everything? Life is pretty good for most, isn''t it?'),
('string/en/utterance/stormtrooper.stf', 22, 'u22', 'My back itches.'),
('string/en/utterance/stormtrooper.stf', 23, 'u23', 'I''ve only gotten to ride in a walker once, but it was really very interesting...'),
('string/en/utterance/stormtrooper.stf', 24, 'u24', 'I imagine we won''t be here long. They''ll have us take out some little Rebel outpost, and we''ll move again...'),
('string/en/utterance/stormtrooper.stf', 25, 'u25', 'Have you heard the one about the Klatooinian, the Ithorian, and the Wookiee?'),
('string/en/utterance/stormtrooper.stf', 26, 'stormtrooper_npc_greet_1', 'Sorry citizen, but I''m on duty.  What can I do for you, quickly?'),
('string/en/utterance/stormtrooper.stf', 27, 'stormtrooper_player_line_1_1', 'I was just wondering what was going on around here.'),
('string/en/utterance/stormtrooper.stf', 28, 'stormtrooper_npc_response_1_1', 'Nothing that I can speak freely about...'),
('string/en/utterance/stormtrooper.stf', 29, 'stormtrooper_player_line_2_1', 'So you admit there''s something going on!'),
('string/en/utterance/stormtrooper.stf', 30, 'stormtrooper_player_line_3_1', 'Oh, well let me get out of your way.'),
('string/en/utterance/stormtrooper.stf', 31, 'stormtrooper_npc_response_2_1', 'That''s it, I''m done talking to you. '),
('string/en/utterance/stormtrooper.stf', 32, 'stormtrooper_npc_response_3_1', 'Ok, I''m back to work.'),
('string/en/utterance/stormtrooper.stf', 33, 'stormtrooper_npc_greet_2', 'Hail citizen.  What do you need?'),
('string/en/utterance/stormtrooper.stf', 34, 'stormtrooper_player_line_1_2', 'Where can I get a cool suit of armor like that?'),
('string/en/utterance/stormtrooper.stf', 35, 'stormtrooper_npc_response_1_2', 'This is the official uniform of the Imperial Stormtroopers.  You''d actually have to BE a stormtrooper to get one.'),
('string/en/utterance/stormtrooper.stf', 36, 'stormtrooper_player_line_2_2', 'Oh.  Well, can I be a stormtrooper then?'),
('string/en/utterance/stormtrooper.stf', 37, 'stormtrooper_player_line_3_2', 'That''s too much work.  Just sell me yours!'),
('string/en/utterance/stormtrooper.stf', 38, 'stormtrooper_npc_response_2_2', 'Uh...why don''t you talk to the recruitment agents, I have to get back to work.'),
('string/en/utterance/stormtrooper.stf', 39, 'stormtrooper_npc_response_3_2', 'Ok, I''m going to have to ask you to back away slowly.  I need to get back to my job.'),
('string/en/utterance/stormtrooper.stf', 40, 'stormtrooper_npc_greet_3', 'Can I help you?'),
('string/en/utterance/stormtrooper.stf', 41, 'stormtrooper_player_line_1_3', 'I''d like to ask you some questions.'),
('string/en/utterance/stormtrooper.stf', 42, 'stormtrooper_npc_response_1_3', 'Sorry, I don''t have time to answer questions.  Maybe you could try the Imperial Senate, or perhaps some of the local politicians.'),
('string/en/utterance/stormtrooper.stf', 43, 'stormtrooper_player_line_2_3', 'No, not those kinds of questions...'),
('string/en/utterance/stormtrooper.stf', 44, 'stormtrooper_player_line_3_3', 'So you''re avoiding my questions?'),
('string/en/utterance/stormtrooper.stf', 45, 'stormtrooper_npc_response_2_3', 'I don''t have time to answer ANY kind of questions.'),
('string/en/utterance/stormtrooper.stf', 46, 'stormtrooper_npc_response_3_3', 'Don''t make me call for backup.  Just step away slowly and I''ll let you go unharmed.  Okay?'),
('string/en/utterance/stormtrooper.stf', 47, 'stormtrooper_npc_job_offer_1', 'There is something you can do for the empire, yes...'),
('string/en/utterance/stormtrooper.stf', 48, 'stormtrooper_npc_job_offer_2', 'I was supposed to do this myself, but I''m backlogged on paperwork, so maybe you can handle it.'),
('string/en/utterance/stormtrooper.stf', 49, 'stormtrooper_npc_job_offer_3', 'Sure,  I''ve got some work that needs to be done.'),
('string/en/utterance/stormtrooper.stf', 50, 'stormtrooper_npc_go_home', 'Get out of the way if you''re not going to help then.'),
('string/en/utterance/stormtrooper.stf', 51, 'stormtrooper_npc_do_job', 'I''ll be interested to know when you''re finished.'),
('string/en/utterance/thug.stf', 1, 'u1', 'Well, I''ve heard that there''s a pretty reliable smuggling channel open...'),
('string/en/utterance/thug.stf', 2, 'u2', '...bribery, of course.'),
('string/en/utterance/thug.stf', 3, 'u3', 'Well, this is a secret, so don''t repeat it, but...'),
('string/en/utterance/thug.stf', 4, 'u4', 'Hah! I can take him any day!'),
('string/en/utterance/thug.stf', 5, 'u5', 'She was really beautiful, sure. But whoo, dangerous.'),
('string/en/utterance/thug.stf', 6, 'u6', 'You have to be very careful, the Empire is sniffing around.'),
('string/en/utterance/thug.stf', 7, 'u7', 'Worst bounty hunter I ever saw. Got himself killed in a cantina.'),
('string/en/utterance/thug.stf', 8, 'u8', 'Best bounty hunter I ever saw. Could take out targets with his eyes closed.'),
('string/en/utterance/thug.stf', 9, 'u9', 'Me, I try to play it safe, you know? Play both sides against each other, that sort of thing.'),
('string/en/utterance/thug.stf', 10, 'u10', 'I''m not really the sort to pick sides between the Empire and the Alliance. As long as I can make money.'),
('string/en/utterance/thug.stf', 11, 'u11', 'Well, I do love sabaac.'),
('string/en/utterance/thug.stf', 12, 'u12', 'I''ve been known to gamble a night away.'),
('string/en/utterance/thug.stf', 13, 'u13', 'When I was younger, I daydreamed about a life in the military, but I prefer freedom now.'),
('string/en/utterance/thug.stf', 14, 'u14', 'When I get old enough to retire, I figure I''ll be rich.'),
('string/en/utterance/thug.stf', 15, 'u15', 'Well, I do owe her some money, but it''s not enough to warrant a bounty!'),
('string/en/utterance/thug.stf', 16, 'u16', 'He owed me money. Doesn''t anymore. He doesn''t have a finger anymore either.'),
('string/en/utterance/thug.stf', 17, 'u17', 'I''m a match for a soldier any day.'),
('string/en/utterance/thug.stf', 18, 'u18', 'Some weather we''ve been having, eh?'),
('string/en/utterance/thug.stf', 19, 'u19', 'So the Wookiee and the Klatooinian cook the Ithorian and eat him! Funny, eh?'),
('string/en/utterance/thug.stf', 20, 'u20', 'Ugliest guy I ever saw, I swear.'),
('string/en/utterance/thug.stf', 21, 'u21', 'So I lost it all. I should have folded, I tell you.'),
('string/en/utterance/thug.stf', 22, 'u22', 'The chance cubes were weighted, I''m pretty sure.'),
('string/en/utterance/thug.stf', 23, 'u23', 'Well, my favorite is Twi''lek cooking, of course.'),
('string/en/utterance/thug.stf', 24, 'u24', 'The worst prisons are Imperial. Treat you like animals, they do.'),
('string/en/utterance/thug.stf', 25, 'u25', 'Well, the best way to pick a pocket is to come from behind...'),
('string/en/utterance/thug.stf', 26, 'thug_npc_greet_1', 'What do you want?'),
('string/en/utterance/thug.stf', 27, 'thug_npc_greet_2', 'Yeah?  What??'),
('string/en/utterance/thug.stf', 28, 'thug_npc_greet_3', 'Make this quick, ok?'),
('string/en/utterance/thug.stf', 29, 'thug_npc_job_offer_1', 'I got work.  If you don''t mind getting your hands dirty you can have it.  You want it?'),
('string/en/utterance/thug.stf', 30, 'thug_npc_job_offer_2', 'There''s plenty to do if you''re willing to bend a few laws...'),
('string/en/utterance/thug.stf', 31, 'thug_npc_job_offer_3', 'I don''t know if I trust you, but I got something I need done if you''re willing.'),
('string/en/utterance/thug.stf', 32, 'thug_npc_response_1_1', 'Whoever pays the most.'),
('string/en/utterance/thug.stf', 33, 'thug_npc_response_1_2', 'Who says I''m bein'' hostile?'),
('string/en/utterance/thug.stf', 34, 'thug_npc_response_1_3', 'What''s it to ya?'),
('string/en/utterance/thug.stf', 35, 'thug_npc_response_2_1', 'Answerin'' questions like that''ll getcha killed.'),
('string/en/utterance/thug.stf', 36, 'thug_npc_response_2_2', 'Do I care?  No.  Go away.'),
('string/en/utterance/thug.stf', 37, 'thug_npc_response_2_3', 'Well don''t.'),
('string/en/utterance/thug.stf', 38, 'thug_npc_response_3_1', 'Didn''t everyone?'),
('string/en/utterance/thug.stf', 39, 'thug_npc_response_3_2', 'Very.'),
('string/en/utterance/thug.stf', 40, 'thug_npc_response_3_3', 'I''ll forget this whole thing ever happened.'),
('string/en/utterance/thug.stf', 41, 'thug_player_line_1_1', 'Who do you work for?'),
('string/en/utterance/thug.stf', 42, 'thug_player_line_1_2', 'Why are you being so hostile?'),
('string/en/utterance/thug.stf', 43, 'thug_player_line_1_3', 'You got somewhere to be?'),
('string/en/utterance/thug.stf', 44, 'thug_player_line_2_1', 'Ever work for Valarian?'),
('string/en/utterance/thug.stf', 45, 'thug_player_line_2_2', 'Um...that was me...'),
('string/en/utterance/thug.stf', 46, 'thug_player_line_2_3', 'I''m just asking is all.'),
('string/en/utterance/thug.stf', 47, 'thug_player_line_3_1', 'Ever work for Jabba?'),
('string/en/utterance/thug.stf', 48, 'thug_player_line_3_2', 'You''re rude aren''t you?'),
('string/en/utterance/thug.stf', 49, 'thug_player_line_3_3', 'Forget I asked.'),
('string/en/utterance/thug.stf', 50, 'thug_npc_go_home', 'If you don''t have the stomach for the work don''t ask for it.'),
('string/en/utterance/thug.stf', 51, 'thug_npc_do_job', 'Get it over with quick.  Make sure no one sees you.'),
('string/en/utterance/thug.stf', 52, 'default', ''),
('string/en/utterance/townsperson.stf', 1, 'u1', 'Oh, I haven''t paid my taxes...'),
('string/en/utterance/townsperson.stf', 2, 'u2', 'What a lovely view.'),
('string/en/utterance/townsperson.stf', 3, 'u3', 'I''ve never been so tired.'),
('string/en/utterance/townsperson.stf', 4, 'u4', 'I need a new book to read.'),
('string/en/utterance/townsperson.stf', 5, 'u5', 'I need to use the ''fresher.'),
('string/en/utterance/townsperson.stf', 6, 'u6', 'I feel old.'),
('string/en/utterance/townsperson.stf', 7, 'u7', 'I think I might be getting sick.'),
('string/en/utterance/townsperson.stf', 8, 'u8', 'My advice is, never gamble with a Hutt.'),
('string/en/utterance/townsperson.stf', 9, 'u9', 'Well, this planet''s not so bad.'),
('string/en/utterance/townsperson.stf', 10, 'u10', 'I''ve been considering moving to a new city.'),
('string/en/utterance/townsperson.stf', 11, 'u11', 'I have too much to do today.'),
('string/en/utterance/townsperson.stf', 12, 'u12', 'It looks like it''s going to be a warm one today.'),
('string/en/utterance/townsperson.stf', 13, 'u13', 'Have you ever seen the inside of an imperial prison?  Me neither.'),
('string/en/utterance/townsperson.stf', 14, 'u14', 'I''d rather be eaten by rancors then pay that guy off.'),
('string/en/utterance/townsperson.stf', 15, 'u15', 'My skin is peeling...'),
('string/en/utterance/townsperson.stf', 16, 'u16', 'Just need enough credits for one more drink...'),
('string/en/utterance/townsperson.stf', 17, 'u17', 'Oh yes, she''s a lovely girl.'),
('string/en/utterance/townsperson.stf', 18, 'u18', 'I wonder if I''m supposed to be somewhere...'),
('string/en/utterance/townsperson.stf', 19, 'u19', 'What day is it?'),
('string/en/utterance/townsperson.stf', 20, 'u20', 'Nothing interesting ever happens around here.'),
('string/en/utterance/townsperson.stf', 21, 'u21', 'I can''t find my chrono.'),
('string/en/utterance/townsperson.stf', 22, 'u22', 'What is that smell?...oh.'),
('string/en/utterance/townsperson.stf', 23, 'u23', 'I''m not clear on what I should be doing now.'),
('string/en/utterance/townsperson.stf', 24, 'u24', 'Lousy stormtroopers...(mumbles)...didn''t do it!'),
('string/en/utterance/townsperson.stf', 25, 'u25', 'I hear the Alliance is looking for more pilots.'),
('string/en/utterance/townsperson.stf', 26, 'townsperson_npc_greet_1', 'Hello, hello.  How are you today?'),
('string/en/utterance/townsperson.stf', 27, 'townsperson_npc_greet_2', 'Sorry, I''m not at all myself today.  What can I do for you?'),
('string/en/utterance/townsperson.stf', 28, 'townsperson_npc_greet_3', 'Good to make your acquaintance.  Unless of course we''ve already met, and in that case, hello again.'),
('string/en/utterance/townsperson.stf', 29, 'townsperson_npc_job_offer_1', 'There is something that I''d been hoping someone would help me with.'),
('string/en/utterance/townsperson.stf', 30, 'townsperson_npc_job_offer_2', 'I actually have thought of something you could do for me...'),
('string/en/utterance/townsperson.stf', 31, 'townsperson_npc_job_offer_3', 'Well, if you''re sure about it, there is something you can do for me.'),
('string/en/utterance/townsperson.stf', 32, 'townsperson_player_line_1_1', 'How are you getting along?'),
('string/en/utterance/townsperson.stf', 33, 'townsperson_player_line_1_2', 'Not yourself?  What''s the matter?'),
('string/en/utterance/townsperson.stf', 34, 'townsperson_player_line_1_3', 'Losing your memory?  '),
('string/en/utterance/townsperson.stf', 35, 'townsperson_npc_response_1_1', 'Oh, things are going just fine I guess.'),
('string/en/utterance/townsperson.stf', 36, 'townsperson_npc_response_1_2', 'Well, I think I might be getting ill.'),
('string/en/utterance/townsperson.stf', 37, 'townsperson_npc_response_1_3', 'Hm...I can''t seem to remember.'),
('string/en/utterance/townsperson.stf', 38, 'townsperson_player_line_2_1', 'You guess?  Not sure?'),
('string/en/utterance/townsperson.stf', 39, 'townsperson_player_line_2_2', 'Oh.  Perhaps I shouldn''t get to close to you.'),
('string/en/utterance/townsperson.stf', 40, 'townsperson_player_line_2_3', 'Haha.  That''s quite funny!'),
('string/en/utterance/townsperson.stf', 41, 'townsperson_player_line_3_1', 'Well, that''s good to hear.'),
('string/en/utterance/townsperson.stf', 42, 'townsperson_player_line_3_2', 'Nonsense.  You look healthy as a bantha.'),
('string/en/utterance/townsperson.stf', 43, 'townsperson_player_line_3_3', 'Oh, what a terrible joke...'),
('string/en/utterance/townsperson.stf', 44, 'townsperson_npc_response_2_1', 'Actually, I think I need some time to myself to think...'),
('string/en/utterance/townsperson.stf', 45, 'townsperson_npc_response_2_2', 'That''s probably safest.'),
('string/en/utterance/townsperson.stf', 46, 'townsperson_npc_response_2_3', 'What''s funny?'),
('string/en/utterance/townsperson.stf', 47, 'townsperson_npc_response_3_1', 'Thanks.  I hope you''re also doing well.'),
('string/en/utterance/townsperson.stf', 48, 'townsperson_npc_response_3_2', 'Well, I don''t feel it.  Ohh, thinking about bantha''s is making me sicker.  Excuse me...'),
('string/en/utterance/townsperson.stf', 49, 'townsperson_npc_response_3_3', 'What?  What joke?'),
('string/en/utterance/townsperson.stf', 50, 'townsperson_npc_go_home', 'Sorry it didn''t work out for us.'),
('string/en/utterance/townsperson.stf', 51, 'townsperson_npc_do_job', 'Thanks for the help.'),
('string/en/veteran.stf', 1, 'new_reward', 'You are eligible for the %DI day veteran reward! Use the /claimVeteranReward command to get your reward.'),
('string/en/veteran.stf', 2, 'select_reward', 'Select your reward from the list. Rewards followed by "*" may not be gained more than once. Rewards followed by "#" may not be traded or sold.'),
('string/en/veteran.stf', 3, 'greeting', 'Hi there! Come for your reward?'),
('string/en/veteran.stf', 4, 'get_award', 'Gimme!'),
('string/en/veteran.stf', 5, 'not_now', 'Nah.'),
('string/en/veteran.stf', 6, 'go_away', 'You need more time under your belt to get a reward.'),
('string/en/veteran.stf', 7, 'damn', 'Damn!'),
('string/en/veteran.stf', 8, 'time_active', 'Player %TT has %DI days logged for veteran rewards.'),
('string/en/veteran.stf', 9, 'self_time_active', 'You have %DI days logged for veteran rewards.'),
('string/en/veteran.stf', 10, 'system_inactive', 'The veteran system is not active.'),
('string/en/veteran.stf', 11, 'not_eligible', 'You are not currently eligible for a veteran reward.'),
('string/en/veteran.stf', 12, 'reward_given', 'Your reward has been placed in your inventory.'),
('string/en/veteran.stf', 13, 'reward_error', 'The reward could not be granted.'),
('string/en/veteran.stf', 14, 'invalid_target', 'That target is invalid for veteran rewards.'),
('string/en/veteran.stf', 15, 'milestone_out_of_range', 'Milestone out of range.'),
('string/en/veteran.stf', 16, 'has_milestone', 'The player has received the milestone''s reward.'),
('string/en/veteran.stf', 17, 'has_not_milestone', 'The player has not received the milestone''s reward.'),
('string/en/veteran.stf', 18, 'ok', 'Ok'),
('string/en/veteran.stf', 19, 'active_months_cleared', 'Your active time has been reset.'),
('string/en/veteran.stf', 20, 'select_milestone', 'Select which milestone you would like to get a reward for.'),
('string/en/veteran.stf', 21, 'bad_milestone', 'You have selected an invalid milestone.'),
('string/en/veteran.stf', 22, 'new_reward_subject', 'Veteran Reward'),
('string/en/veteran.stf', 23, 'new_reward_from', 'Veteran System'),
('string/en/veteran.stf', 24, 'days', ' days'),
('string/en/veteran.stf', 25, 'new_reward_msgbox', 'You are eligible for a new veteran reward! Use the /claimVeteranReward command to get your reward.'),
('string/en/veteran.stf', 26, 'harvester_converted', 'Your harvester %TT has been converted to use 0 power.'),
('string/en/veteran.stf', 27, 'harvester_converted_subject', 'Harvester Converted'),
('string/en/veteran.stf', 28, 'resource_title', 'Resources'),
('string/en/veteran.stf', 29, 'choose_class', 'Choose resource class'),
('string/en/veteran.stf', 30, 'choose_sub_class', 'Choose resource class from'),
('string/en/veteran.stf', 31, 'choose_type', 'Choose resource type from');
INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/veteran.stf', 32, 'one_year_inventory_full', 'We tried to give you a reward in celebration of Star Wars Galaxies'' one-year anniversary, but your inventory is full. Please create at least one unit of free space in your inventory, log out for five minutes or more, and log back in again.'),
('string/en/veteran.stf', 33, 'one_year_anniversary_from', 'Star Wars Galaxies One Year Anniversary'),
('string/en/veteran.stf', 34, 'one_year_inventory_full_subject', 'Your inventory is full'),
('string/en/veteran.stf', 35, 'one_year_anniversary_subject', 'We''re One Year Old!'),
('string/en/veteran.stf', 36, 'one_year_anniversary', 'Star Wars Galaxies is one year old! To celebrate, we''ve given you a special gift you can put in your home or guild hall. Check your inventory.'),
('string/en/veteran.stf', 37, 'flash_speeder_granted_sub', 'JtL Pre-order Reward'),
('string/en/veteran.stf', 38, 'flash_speeder_granted_body', 'You have received a deed for the Flash Speeder as your reward for pre-ordering Jump to Lightspeed.  If you should ever need a replacement, simply type /flashspeeder to purchase another for 20,000 credits.'),
('string/en/veteran.stf', 39, 'flash_speeder_replace_prompt', 'A replacement Flash Speeder is available at the cost of 20000 credits.  Are you sure you want a new speeder?'),
('string/en/veteran.stf', 40, 'flash_speeder_not_eligible', 'You are not eligible to receive a Flash Speeder.'),
('string/en/veteran.stf', 41, 'flash_speeder_no_inv_space', 'You do not have any inventory space remaining for the Flash Speeder deed.'),
('string/en/veteran.stf', 42, 'flash_speeder_granted', 'A Flash Speeder deed has been placed in your inventory.'),
