('string/en/wearables_detail.stf', 15, 'armor_bounty_hunter_belt', 'A belt for Bounty Hunter Armor.'),
('string/en/wearables_detail.stf', 16, 'armor_bounty_hunter_bicep_l', 'This armor covers the upper arms of the wearer, protecting them from harm.'),
('string/en/wearables_detail.stf', 17, 'armor_bounty_hunter_bicep_r', 'This armor covers the upper arms of the wearer, protecting them from harm.'),
('string/en/wearables_detail.stf', 18, 'armor_bounty_hunter_boots', 'Armored boots, favored by bounty hunters.'),
('string/en/wearables_detail.stf', 19, 'armor_bounty_hunter_bracer_l', 'This armor covers the forearms of the wearer, protecting them from harm.'),
