INSERT INTO `client_strings` (`stringFile`, `index`, `name`, `value`) VALUES
('string/en/wearables_detail.stf', 438, 'lifeday_orb', 'Life Day is a holiday celebrated on Kashyyyk, the Wookiee homeworld, in order to recognize the renewal of life and remember those who have passed on. Because Life Day is important for reconnecting with family and friends, Wookiees will brave arduous treks to be reunited with loved ones on the holiday. Although originally celebrated only on Kashyyyk, and usually at the Tree of Life, the concept of Life Day has slowly spread across the galaxy. The Life Day Orb, a Wookiee artifact, is a traditional symbol carried by Wookiees during the Life Day celebrations. \n\n"We celebrate a day of peace, a day of harmony. A day of joy we all can share together..." - Traditional Life Day song lyric (translated from Shyriiwook)\n\n'),
('string/en/wearables_detail.stf', 439, 'mask_s01', 'A mask.\n'),
('string/en/wearables_detail.stf', 440, 'necklace_adorned_beads', 'A necklace, wearable by almost all species.  Scratched in the back of the main plate of the necklace are a few diagrams that give you a better understanding of how to further protect against ranged attacks.'),
('string/en/wearables_detail.stf', 441, 'necklace_blue_gadget', 'A necklace, wearable by almost all species.  Scratched in the back of the main plate of the necklace is a recipe that gives you a better understanding of how to create even more delicious dishes.'),
('string/en/wearables_detail.stf', 442, 'necklace_brass_charm', 'A necklace, wearable by almost all species.  Engraved in the back of the main plate of the necklace are a few weapon stances that give you a better understanding of how to further improve your two handed weapon speed.'),
('string/en/wearables_detail.stf', 443, 'necklace_bright_bauble', 'A necklace, wearable by almost all species.  Engraved in the back of the main plate of the necklace are a few weapon stances that give you a better understanding of how to further improve your flame thrower speed.'),
('string/en/wearables_detail.stf', 444, 'necklace_complex_pattern', 'A necklace, wearable by almost all species.  Engraved in the back of the main plate of the necklace are a few weapon stances that give you a better understanding of how to further improve your polearm speed.'),
