('string/en/wearables_detail.stf', 508, 'rancor_tooth', 'This Rancor tooth could be used as a replacement for a sword core.'),
('string/en/wearables_detail.stf', 509, 'rebreather', 'A rebreathing device that filters some types of gaseous poisons.'),
('string/en/wearables_detail.stf', 510, 'ring_mark_hero', 'This ring symbolizes the mark of a true hero. The bearer of such an item has proven him or herself worthy of becoming the Hero of Tatooine.\n\nThe special ability on this ring will restore a small amount of life to you if you have died, but only once every twenty-three hours.'),
('string/en/wearables_detail.stf', 511, 'ring_s01', 'A ring, worn on the finger (if you are a species lucky enough to have fingers). To wear this ring, go to your inventory window and double click on it.'),
('string/en/wearables_detail.stf', 512, 'ring_s02', 'A ring, worn on the finger (if you are a species lucky enough to have fingers). To wear this ring, go to your inventory window and double click on it.'),
